local Text_AvgDialog = readonly({
  AvgDialog_100303_Content_1 = {
    Text = "Huff... huff... Nein, das ist es nicht... irgendetwas fühlt sich immer noch merkwürdig an..."
  },
  AvgDialog_100303_Content_10 = {
    Text = "Warum ist es direkt vor mir, und doch kann ich es immer noch nicht finden..."
  },
  AvgDialog_100303_Content_11 = {
    Text = "Keine Eile, Pickman. Da die Muse es dir bereits gesagt hat, ist die Antwort sicherlich ganz nah. Denk gut nach, was du vielleicht übersehen hast."
  },
  AvgDialog_100303_Content_12 = {
    Text = "Steh vorher auf... Zisch..."
  },
  AvgDialog_100303_Content_13 = {
    Text = "Du ziehst deine Hand abrupt zurück, die du ausstrecken wolltest, um ihm aufzuhelfen. In seinem glühend heißen Körper scheint Lava zu fließen."
  },
  AvgDialog_100303_Content_14 = {
    Text = "Wie erwartet, ist es wieder Thais, der Ärger macht..."
  },
  AvgDialog_100303_Content_15 = {
    Text = "Thais... Ah! Richtig! Wie konnte ich das nicht denken! Wie konnte ich das übersehen!!"
  },
  AvgDialog_100303_Content_16 = {
    Text = "Er richtete sich plötzlich auf und starrte dich mit Augen an, die dich fast verbrennen konnten."
  },
  AvgDialog_100303_Content_17 = {
    Text = "Der verrückteste Wunsch... Genau! Ich wusste es, ich wusste es..."
  },
  AvgDialog_100303_Content_18 = {
    Text = "Er war so aufgeregt, dass er sogar vergaß aufzustehen und mit Händen und Füßen zu dir kroch."
  },
  AvgDialog_100303_Content_19 = {
    Text = "Hüter, kannst du einmal wieder mein Model sein? Nur einmal! Nur einmal!"
  },
  AvgDialog_100303_Content_2 = {Text = "Pickman?"},
  AvgDialog_100303_Content_20 = {
    Text = "Ich weiß, was du tun willst, absolut nicht..."
  },
  AvgDialog_100303_Content_21 = {
    Text = "Pickmans ängstlich flehende, bemitleidenswerte rote Augen funkelten schwach im dämmerigen Licht. Die Worte der Ablehnung konnten nicht mehr ausgesprochen werden."
  },
  AvgDialog_100303_Content_22 = {
    Text = "...Na gut. Wenn es nur als Modell ist, sitze ich dann auf diesem Sofa?"
  },
  AvgDialog_100303_Content_23 = {
    Text = "Nein, nein, nein, Hüter! Wie kannst du ein solches Gemälde im Atelier erschaffen?!"
  },
  AvgDialog_100303_Content_24 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_100303_Content_25 = {
    Text = "Ist dies... die Welt in deinem Gemälde?"
  },
  AvgDialog_100303_Content_26 = {
    Text = "Genau richtig! Es ist das Ritual des Karnevals der Geister!"
  },
  AvgDialog_100303_Content_27 = {
    Text = "Ich habe es erschaffen, aber ich habe es nie beendet. Es fehlt ein Paar Protagonisten im Mittelpunkt. Sie repräsentieren die primitivsten und wildesten Wünsche dieses Universums, die Wünsche, die ich vergessen habe..."
  },
  AvgDialog_100303_Content_28 = {
    Text = "Ich habe bis jetzt kein Modell gefunden, das ausreichend ist, um der Protagonist zu werden..."
  },
  AvgDialog_100303_Content_29 = {
    Text = "Pickman bleibt weiterhin in der knienden Position und zieht sein Knie zu dir heran."
  },
  AvgDialog_100303_Content_3 = {
    Text = "Pickmans düsteres Atelier ist noch chaotischer als zuvor, unzählige mit Farben und Linien gefüllte Lederblätter liegen unordentlich in jeder Ecke des Ateliers verstreut, als hätten sie gerade einen seltsamen Krieg erlebt."
  },
  AvgDialog_100303_Content_30 = {
    Text = "Bitte, Hüter... gewähre mir die Muse!"
  },
  AvgDialog_100303_Content_31 = {
    Text = "Du kannst mich alles machen lassen! Einmal, nur einmal! Bitte nimm mich mit, um dieses Bild zu vollenden..."
  },
  AvgDialog_100303_Content_32 = {
    Text = "Ohne lange zu zögern, seufztest du leise und kamst ihm näher."
  },
  AvgDialog_100303_Content_33 = {
    Text = "Er hob den Kopf und sah dich mit weit aufgerissenen Augen an. Es waren Augen, die einem Tier oder einem Haustier gehörten, gierig, verlangend, gehorsam und treu. Er flehte, flehte um einen Befehl, der ihn zu der Muse führen würde."
  },
  AvgDialog_100303_Content_34 = {
    Text = "Alles ist möglich... Nun, ich muss gründlich nachdenken..."
  },
  AvgDialog_100303_Content_35 = {
    Text = "Deine Hand liegt sanft auf Pickmans Gesicht. Der heiße Atem und der Körper werden sanft. Du weißt nicht, ob du es zähmst oder ob es dich gerade schmelzen lässt."
  },
  AvgDialog_100303_Content_36 = {
    Text = "Die Stimmen der Ghule begannen zu verschwinden, während die raue, primitive Stimme dieses Protagonisten die gesamte Welt des Bildes erfüllte."
  },
  AvgDialog_100303_Content_37 = {
    Text = "Das ist die Stimme der Muse."
  },
  AvgDialog_100303_Content_4 = {
    Text = "Er kniete mit zerzauster Kleidung auf dem Boden und kritzelte wahnsinnig auf ein leeres Blatt Papier, bis es fast zerfetzt war. Die spritzende Farbe bespritzte seinen Körper, wie ein Anhänger, der an einem barbarischen Ritual teilnahm."
  },
  AvgDialog_100303_Content_5 = {
    Text = "Was ist hier los..."
  },
  AvgDialog_100303_Content_6 = {
    Text = "Ich habe es gehört, Hüter! Ich habe die Stimme der Muse gehört, die ruft! Direkt in meinem Ohr!"
  },
  AvgDialog_100303_Content_7 = {
    Text = "Meine Augen, meine Hände, mein Herz, jede Zelle in meinem Körper zittert beim Klang davon!"
  },
  AvgDialog_100303_Content_8 = {
    Text = "Nur noch ein Schritt! Ich bin nur noch einen Schritt von der größten Kunst entfernt!"
  },
  AvgDialog_100303_Content_9 = {
    Text = "Aber ich kann es nicht finden... Töten, Erobern, Schlemmen, Gier, Verschwenden, Nichtigkeit... Ich habe all den Wahnsinn gezeichnet, aber ich habe es immer noch nicht gefunden..."
  },
  AvgDialog_100588_Content_1 = {
    Text = "Eine schwarze Gestalt erscheint allmählich vor dir."
  },
  AvgDialog_100588_Content_2 = {
    Text = "[Angriff]???"
  },
  AvgDialog_100588_Content_3 = {
    Text = [[
Du hast 677 Schaden verursacht! Du glaubst, insgesamt 27.188 Schaden an ihm verursacht zu haben.
 Alle haben insgesamt 14.636.643.707 Schaden an ihm verursacht, aber er ist immer noch nicht gefallen.]]
  },
  AvgDialog_100588_Content_4 = {Text = "[Weiter]"},
  AvgDialog_100588_Content_5 = {
    Text = "Du hast das Gefühl, hier schon einmal gewesen zu sein...\n Unter dem Blick des Schattens wird dein Bewusstsein allmählich verschwommen."
  },
  AvgDialog_100588_Content_6 = {Text = "[Schlaf]"},
  AvgDialog_100629_Content_1 = {
    Text = "Bald schon wurde diese Welt nicht mehr von der Erosion geplagt, die Menschheit entwickelte sich rasant, und später hielt die Mythag Universität einen Zug im Sternenhimmel an..."
  },
  AvgDialog_10120_Content_1 = {
    Text = "Schütze dein Kommando-Gerät und hüte dich vor der Auflösungs-Kontamination.\nEs wird im bevorstehenden Kampf entscheidend sein."
  },
  AvgDialog_10120_Content_2 = {
    Text = "Halte die <Yellow:Command Card> gedrückt und ziehe sie in die <Yellow:Central Command Zone>, um mir einen Aktionsbefehl zu erteilen."
  },
  AvgDialog_10121_Content_1 = {
    Text = "<Yellow:Silber>? Hat nicht erwartet, es hier zu finden..."
  },
  AvgDialog_10121_Content_2 = {
    Text = "Schmiede Silber-Schlüssel, verbinde Erwacher und stelle spirituelle Energie bereit...\nAlles in Mythag dreht sich um <Yellow:Silber>."
  },
  AvgDialog_10121_Content_3 = {
    Text = "Selbst eine winzige Menge <Yellow:Silber> hat außergewöhnlichen Wert für Mythags Forschung.\nVersuche, sie alle zu sammeln."
  },
  AvgDialog_10122_Content_1 = {
    Text = "Das Herauszögern ist nachteilig; wir müssen dies schnell zu Ende bringen."
  },
  AvgDialog_10122_Content_2 = {
    Text = "Hier ist das <Yellow:\"Königinsschwert\">, mit dem ich seit meiner Kindheit geübt habe.\nLass es uns mit diesem Schlag beenden!"
  },
  AvgDialog_10123_Content_1 = {
    Text = "Du gehst durch die kleine Tür unter dem Glockenturm und betrittst einen versteckten, geschlossenen Durchgang."
  },
  AvgDialog_10123_Content_10 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_10123_Content_11 = {
    Text = "Die Tür öffnet sich langsam und zeigt zum ersten Mal die Szene des verbotenen Ortes"
  },
  AvgDialog_10123_Content_13 = {
    Text = "Die untere Hälfte im schwarzen Morast versunken, verstärkt die alles verschlingende Dunkelheit ihre strahlende Reinheit und macht sie makellos weiß."
  },
  AvgDialog_10123_Content_14 = {
    Text = "In einem Dämmerzustand überschneidet sich die unmenschliche Gestalt vor dir subtil mit der Silhouette der jungen Frau, die du im Schlüsselgrab gesehen hast."
  },
  AvgDialog_10123_Content_15 = {
    Text = "Es hat kein Gesicht, doch du spürst eine gewisse Mitgefühl aus seiner Körperhaltung."
  },
  AvgDialog_10123_Content_16 = {
    Text = "Höchste, Reine, Gute, Schöne."
  },
  AvgDialog_10123_Content_17 = {
    Text = "<Shake:Du... bist angekommen...>"
  },
  AvgDialog_10123_Content_18 = {
    Text = "Das weiße Monster gab ein heiseres Geräusch von sich, teil Brüller, teil Klage."
  },
  AvgDialog_10123_Content_19 = {
    Text = "Es ist keine menschliche Sprache, doch du verstehst die Bedeutung seiner Wörter."
  },
  AvgDialog_10123_Content_2 = {
    Text = "Doll führt den Weg voraus, ihre Schritte hallen hohl auf der Metalloberfläche."
  },
  AvgDialog_10123_Content_20 = {
    Text = "Alles vor dir wird plötzlich verschwommen. Du blinzelst, und warme Flüssigkeit rinnt dir die Wange herunter."
  },
  AvgDialog_10123_Content_21 = {
    Text = "Ist das eine Träne? Aber warum? Was lässt deine Brust eng und deine Augen brennen?"
  },
  AvgDialog_10123_Content_22 = {
    Text = "......<Yellow:Tawil>?"
  },
  AvgDialog_10123_Content_23 = {
    Text = "Die Worte, die Doll murmelt, lassen Ramonas Ausdruck sich verändern."
  },
  AvgDialog_10123_Content_24 = {
    Text = "Tawil? Diejenige, die eine der Gründerinnen ist, die Erweckerin Tawil?"
  },
  AvgDialog_10123_Content_25 = {
    Text = [[
Du erinnerst dich auch.
In <Blue:"Die Geschichte von Mythag"> erscheint dieser Name alongside zwei anderen]]
  },
  AvgDialog_10123_Content_26 = {
    Text = "In Alluvium 90 gründeten <Blue:Ward Phillips>, <Blue:Klararksh> und <Blue:Tawil> <Blue:Mythag College>."
  },
  AvgDialog_10123_Content_27 = {
    Text = "Das ist genau da, wo du jetzt bist, der Vorgänger von <Blue:Mythag University (Mythag University)>."
  },
  AvgDialog_10123_Content_28 = {Text = "Keeper."},
  AvgDialog_10123_Content_29 = {
    Text = "Ich bin hier."
  },
  AvgDialog_10123_Content_3 = {
    Text = "Es ist das erste Mal, dass ich gelernt habe, dass es einen solchen geheimen Gang unter dem Uhrturm gibt..."
  },
  AvgDialog_10123_Content_30 = {
    Text = "Die Tatsache, dass du hier stehst, ohne von Tawil vertrieben zu werden, zeigt, dass dein Schicksal nun untrennbar mit der Zukunft von Mythag verbunden ist."
  },
  AvgDialog_10123_Content_31 = {
    Text = "Also, du bist qualifiziert, die Informationen zu hören, die ich dir gleich mitteilen werde."
  },
  AvgDialog_10123_Content_32 = {
    Text = "Das ist das tiefste Geheimnis der Mythag Universität.\nTawil—der Gründer der Mythag Universität—ist weder Mensch noch Erwecker."
  },
  AvgDialog_10123_Content_33 = {
    Text = "Er ist ein Wesen aus einer anderen Dimension. Zunächst war er nur ein Flüstern, das vom ersten Direktor, Phillips, gehört wurde."
  },
  AvgDialog_10123_Content_34 = {
    Text = "Entgegen der Wahrnehmung, dass \"Tawil ein Erwachter ist\", entstand die Technik der Silberextraktion und <Yellow:Erweckung der Verstorbenen, die mit dem Oberen Willen schwingen>, unter ihrer Anleitung."
  },
  AvgDialog_10123_Content_35 = {
    Text = "Tawil prophezeite die Ankunft der Auflösung und die Zukunft der Weltzerstörung, übermittelte die anfängliche \"Wahrheit\" und fiel nach der Gründung des Mythag Colleges in den Schlaf."
  },
  AvgDialog_10123_Content_36 = {
    Text = "Laut Mr. Phillips wählte Tawil eine \"nicht existierende\" Form der Existenz, um \"beobachtet zu werden\" zu vermeiden."
  },
  AvgDialog_10123_Content_37 = {
    Text = "Nur wenn „Variablen“ erscheinen, wird Er in der Form von „Erwachen“ wiedergeboren —"
  },
  AvgDialog_10123_Content_38 = {Text = "Sieh!"},
  AvgDialog_10123_Content_39 = {
    Text = "Als ob es die Ankunft von einigen Tabus und Verwandten vorausahnte, ließ \"Tawil\" einen durchdringenden Schrei los, der Trommelfelle zerbrach."
  },
  AvgDialog_10123_Content_4 = {
    Text = "Wenn jeder davon weiß, kann es wohl keinen geheimen Durchgang genannt werden.\nDer Durchgang verbindet sich mit dem <Yellow:Black Pool>, der Grundlage von Mythag."
  },
  AvgDialog_10123_Content_40 = {
    Text = "Mit einem Zittern, das dem Ausbrechen eines Küken ähnelt, entfalten sich sechs massive silberne Flügel von seinem Körper."
  },
  AvgDialog_10123_Content_41 = {
    Text = "Die Tipps der Flügel tropfen silberne Tropfen, die sanft ins schwarze Becken fallen."
  },
  AvgDialog_10123_Content_42 = {
    Text = "Sobald die silberne Flüssigkeit in den Schwarzen Pool eindringt, entstehen Wellen und verzerrte Aufgelöste Körper tauchen auf."
  },
  AvgDialog_10123_Content_43 = {
    Text = "Die deformierten Monster widersetzen sich den physikalischen Gesetzen, während sie aus der schwarzen Pfütze hervorbrechen. Einige stürzen auf dich zu, während andere zum Platz außerhalb des Uhrenturms gelangen"
  },
  AvgDialog_10123_Content_44 = {
    Text = "<Shake:Endlich... gefunden... dich...>"
  },
  AvgDialog_10123_Content_45 = {
    Text = "Halt ihn auf! Nur indem wir ihn aufhalten, können wir die Quelle der Monster abschneiden!"
  },
  AvgDialog_10123_Content_5 = {
    Text = "Ohne das <Yellow:giant Silver> namens <Yellow:Core> am Grund des Schwarzen Pools würde es Jahrzehnte kosten, ganz allein auf schwache menschliche Geister zu vertrauen, um die Erwacher zu unterstützen, und somit Mythags Technologie für Erwacher zurückzuwerfen."
  },
  AvgDialog_10123_Content_6 = {
    Text = "Also, das Verhindern, dass unverbundene Erwachte Mythag verlassen, ist also auch aus der Sorge entstanden, dass wir in den Wahnsinn fallen könnten?"
  },
  AvgDialog_10123_Content_7 = {
    Text = "Nicht ganz.\nWenn nur jeder Awakener so leicht zu handhaben wäre wie du, Ogier."
  },
  AvgDialog_10123_Content_8 = {
    Text = "Alright, wir sind hier."
  },
  AvgDialog_10123_Content_9 = {
    Text = "Als sie sprach, drückte die Puppe einen unauffälligen Knopf an der Seitenwand des Durchgangs.\nMit einem Ding öffnete sich die Tür, und du tratst in den schwach beleuchteten, engen Raum ein."
  },
  AvgDialog_10124_Content_1 = {
    Text = "Es scheint, dass du deinen Zustand gefunden hast. Der nächste Befehl gehört dir, Hüter!"
  },
  AvgDialog_10125_Content_1 = {
    Text = "Verzeih, es bleibt keine Zeit, dich einzugewöhnen."
  },
  AvgDialog_10125_Content_10 = {
    Text = "Ramona war entsetzt, du hattest sie noch nie so panisch gesehen"
  },
  AvgDialog_10125_Content_11 = {
    Text = "Das Mädchen, das mit Fragen bombardiert wurde, zitterte in der Stimme und sah erschöpft aus"
  },
  AvgDialog_10125_Content_12 = {
    Text = "Sie erkennen sie. Sie ist Professorin Puppe, bekannt dafür, schwer zu kommunizieren zu sein, und gehört zum <Blue:Erwachen Forschungsinstitut>. Mit anderen Worten, sie ist eine Nicht-Kämpferin."
  },
  AvgDialog_10125_Content_13 = {
    Text = "Bin ich hier im Urlaub?"
  },
  AvgDialog_10125_Content_14 = {
    Text = "Sie schloss die Augen und sammelte sich"
  },
  AvgDialog_10125_Content_15 = {
    Text = "Wurde der Schlüsselraum angegriffen? Dieser Ort ist nahe der Hintertür; beeil dich und geh."
  },
  AvgDialog_10125_Content_16 = {
    Text = "Wir können helfen! %player% kann uns alle verknüpfen und dann befehligen—"
  },
  AvgDialog_10125_Content_17 = {
    Text = [[
Ramona.
Das sind unsere Verantwortlichkeiten, %player% ist nur ein Neueinsteiger, der gerade die Vorbereitungsschule abgeschlossen hat.]]
  },
  AvgDialog_10125_Content_18 = {
    Text = "Aber %player% ist mit mir verbunden, ich weiß, dass {Male=er,Female=sie} es kann... Ich glaube an {Male=er,Female=sie}"
  },
  AvgDialog_10125_Content_19 = {
    Text = "Puppe musterte dich von Kopf bis Fuß und wandte sich mit einem strengen Blick Ramona zu"
  },
  AvgDialog_10125_Content_2 = {
    Text = "Der Mutant erreichte das Schlüssellager, bevor die Glocke läutete, und die <Blue:Nebelbarriere> um Missaga war wahrscheinlich bereits ausgefallen"
  },
  AvgDialog_10125_Content_20 = {
    Text = "Wenn ich mich nicht irre, ist die Schwurzeremonie noch nicht abgeschlossen.\n{Male=er,Female=sie} hat den Silberschlüssel noch nicht erhalten, oder?"
  },
  AvgDialog_10125_Content_21 = {
    Text = "Als nächstes, werden wir in die Mythag-Verbotszone eintreten. Unbefugter Zutritt ist ein schweres Verbrechen, und ich dachte, du wüsstest das, da du hier aufgewachsen bist."
  },
  AvgDialog_10125_Content_22 = {
    Text = "Die Lage ist dringend, wir haben keine Wahl, oder? \nAußerdem ist %player% kein gewöhnlicher Neuling, {Male=er,Female=sie} ist unser einziger Geheimnisträger"
  },
  AvgDialog_10125_Content_23 = {
    Text = "Du erinnerst dich sicher an die <Yellow:Akut-Explosion> vor einem Jahr. Wenn {Male=er,Female=sie} damals nicht alle Erwachten verbunden hätte, könnte ich jetzt nicht hier stehen und mit dir streiten"
  },
  AvgDialog_10125_Content_24 = {
    Text = "Das Mädchen mit den rosa Haaren antwortet nicht, sondern wendet sich dir zu"
  },
  AvgDialog_10125_Content_25 = {
    Text = "Ich weiß, du hast einen Blick auf <Yellow:„das Tor“> geworfen. Aber egal ob die Zukunft der Welt oder der Kern von Missaga, es könnte schlimmer sein, als du denkst"
  },
  AvgDialog_10125_Content_26 = {
    Text = "Wir stehen einem Phänomen gegenüber, das die materielle Existenz selbst zerstört. Sobald du von <Yellow:Aufsäusung> kontaminiert bist, wird alles über dich verschwinden."
  },
  AvgDialog_10125_Content_27 = {
    Text = "Der Name, den du während der Eid-Zeremonie auf den Grabstein eingraviert hast, wird sich ebenfalls in einen Pool aus schwarzem Schlamm auflösen, von allen vergessen."
  },
  AvgDialog_10125_Content_28 = {
    Text = "Antworte mir, bist du wirklich bereit?"
  },
  AvgDialog_10125_Content_29 = {
    Text = "Puppe starrte dich kalt an, ihre Stimme war völlig eben"
  },
  AvgDialog_10125_Content_3 = {
    Text = "<Blue:William> wusste vom Ritual im Schlüsselschrein, aber keine Verstärkung kam, und die Glocken...\nWir müssen uns mit ihnen treffen und <Yellow:die Quelle der Mutation> beseitigen"
  },
  AvgDialog_10125_Content_30 = {
    Text = "Sie wirkte ausdruckslos, aber aus dem frostigen Grund ihrer Pupillen schimmerte loderndes Feuer"
  },
  AvgDialog_10125_Content_31 = {
    Text = "Deine Antwort ist—"
  },
  AvgDialog_10125_Content_32 = {
    Text = "Mein Grabstein, steht jetzt im Schlüsselgrab"
  },
  AvgDialog_10125_Content_33 = {
    Text = [[
Du bist ein Teil von Missaga.
Vielleicht warst du es schon in Akut]]
  },
  AvgDialog_10125_Content_34 = {
    Text = "Hier gibt es Dinge, die nur ich tun kann"
  },
  AvgDialog_10125_Content_35 = {
    Text = "Diese Entscheidung mag übereilt sein, aber wer kann garantieren, dass man immer perfekt vorbereitet ist?"
  },
  AvgDialog_10125_Content_36 = {Text = "Gut."},
  AvgDialog_10125_Content_37 = {
    Text = "Ich verleihe dir im Namen des sechsten Rektors von Missaga, <Blue:Oliver Elsie>, diesen silbernen Schlüssel, Nummer K-0617"
  },
  AvgDialog_10125_Content_39 = {
    Text = "Puppe nahm einen silbernen Schlüssel aus einer präzisen kleinen Box und befestigte ihn an deiner Brust.\nDer silberne Schlüssel leuchtete und ein vertrautes Gefühl erfüllte deinen Brustkorb"
  },
  AvgDialog_10125_Content_4 = {
    Text = "Ist das...?!"
  },
  AvgDialog_10125_Content_40 = {
    Text = "Von nun an wirst du als Hüter des Geheimnisses mit den vielen Schülern und Lehrern von Missaga zusammen sein"
  },
  AvgDialog_10125_Content_41 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_10125_Content_42 = {
    Text = "Jetzt, verbinde dich mit mir"
  },
  AvgDialog_10125_Content_43 = {
    Text = "Du aktivierst vorsichtig den Silber-Schlüssel.\nSilbernes Licht flackert, und die Geisterverbindung verknüpft deine Sinne mit denen der Puppe wie tausende unsichtbare Fäden."
  },
  AvgDialog_10125_Content_44 = {
    Text = "Als ob eine elektrische Spannung mit einem \"Klick\" verbunden wäre, strömten unzählige Nachrichten aus Licht und Schatten in deinen Geist.\nVon intensiven Herzklopfen erschüttert, kannst du kaum stehen."
  },
  AvgDialog_10125_Content_45 = {
    Text = "Doll, du..."
  },
  AvgDialog_10125_Content_46 = {
    Text = "Du bist genau zur rechten Zeit angekommen, Hüter.\nSowohl Ogier als auch ich sind am Ende."
  },
  AvgDialog_10125_Content_47 = {
    Text = "Du bleibst hier und ruhst dich aus. Ramona und ich werden in den Kampf ziehen, um Ogier zu unterstützen."
  },
  AvgDialog_10125_Content_48 = {
    Text = "Beruhige dich. Selbst wenn dein Geist es handhaben kann, sind Romanas Verletzungen nicht für den sofortigen Kampf geeignet."
  },
  AvgDialog_10125_Content_49 = {
    Text = "Das Kind kann eine Weile durchhalten. Folge mir zuerst."
  },
  AvgDialog_10125_Content_6 = {
    Text = "Am Ende des Blickfelds hebt ein blonder Junge einen unverhältnismäßig großen schwarzen Schild und wehrt die Angriffe eines agilen Doppelschwertkämpfers ab"
  },
  AvgDialog_10125_Content_7 = {
    Text = "Er schützte das Mädchen mit den rosa Haaren hinter sich mit einem Schild und wurde dabei immer weiter zurückgedrängt"
  },
  AvgDialog_10125_Content_8 = {
    Text = "Warte... der, der angreift... ist <Yellow:Erwacher> Lotan?!"
  },
  AvgDialog_10125_Content_9 = {
    Text = "Dorl? <Blue:Glockenturm> ist außer Kontrolle?!"
  },
  AvgDialog_10126_Content_1 = {
    Text = "Wenn das Leben auf 0 sinkt, wird die Geisterkraft Schwierigkeiten haben, das Instrument weiterhin zu betreiben, um <Yellow:Bereich> zu erkennen. Um die Sicherheit der Kampfmannschaft zu gewährleisten, wird das Instrument dich gewaltsam aus dem Kampf ziehen."
  },
  AvgDialog_10126_Content_2 = {
    Text = "Die Situation ist dringend. Ich habe die Leistungsausgabe des Geräts basierend auf den gesunden Vitalzeichen des Hüters und einer vollständigen Ladung von Aliemus angepasst."
  },
  AvgDialog_10126_Content_3 = {
    Text = "Diese Methode ist extrem riskant, aber wir haben keine Wahl, als das Risiko einzugehen. Nutze jetzt Exalt, um diesen Kampf zu beenden!"
  },
  AvgDialog_10127_Content_1 = {
    Text = "Wie warm ... Die Geisterverbindung ist sehr stabil. Dein Geist und deine Lebensenergie sind noch nie so stark gewesen wie heute"
  },
  AvgDialog_10127_Content_2 = {
    Text = "Sie können nicht so leicht fallen, <Yellow:die einzige auf der Welt> Hüter.\nWir zählen darauf, dass Sie alle durch die Auflösung ausgelöschte Geschichte untersuchen und dokumentieren."
  },
  AvgDialog_10127_Content_3 = {
    Text = "Die Sorge in ihren Augen verschwindet, Ramona lächelt halb im Scherz beruhigend"
  },
  AvgDialog_10127_Content_4 = {
    Text = "Der Klang von tröpfelndem Regen erfüllt die Welt."
  },
  AvgDialog_10127_Content_5 = {
    Text = "<Red:Unruhe, Schmerz, Erstickung> erfüllten meine Brust, als ein Regentropfen fiel."
  },
  AvgDialog_10127_Content_7 = {Text = "Ramona!"},
  AvgDialog_10127_Content_9 = {
    Text = "Die Glocke schlägt."
  },
  AvgDialog_10128_Content_1 = {
    Text = "Sei vorsichtig, der Gegner hat eine starke Offensive eingenommen!"
  },
  AvgDialog_10128_Content_2 = {
    Text = "Was fürchtest du? Ich bin immer noch hier.\nHüter, lass mich <Yellow:\"Äußere Operation\"> durchführen."
  },
  AvgDialog_10129_Content_1 = {
    Text = "Aktiviere den Silber Schlüssel, %player%."
  },
  AvgDialog_10129_Content_2 = {
    Text = "Der Silberne Schlüssel flackert, und eine flüchtige Vision erscheint plötzlich, die allmählich mit der Realität vor den Augen verschmilzt."
  },
  AvgDialog_10129_Content_3 = {
    Text = "Schwindel, verschwommene Gedanken, ein Sirenengeheul im Kopf, und die Stimme der Puppe begann zu verblassen..."
  },
  AvgDialog_10129_Content_4 = {
    Text = "Du kämpfst, um deinen Geist zu beruhigen und die Informationen von der Puppe aus dem chaotischen Gemurmel herauszulesen."
  },
  AvgDialog_10129_Content_5 = {
    Text = "Siehst du es? Vor dir liegt der Bereich—ein spezieller Ort, der durch <Yellow:Traum Dimension> und <Yellow:Realitätsdimension> gebildet wurde."
  },
  AvgDialog_10129_Content_6 = {
    Text = "Mythag projizierte einen Teil von <Blue:Junction> in den Bereich, um die zunehmend wahnsinnigen Geister der Ermittler zu stabilisieren und die Erwacher zu heilen."
  },
  AvgDialog_10129_Content_7 = {
    Text = "Jedoch hat menschliches Eingreifen im Bereich begrenzte Auswirkungen, daher können wir die Position von <Blue:Junction> nicht garantieren. Alles hängt von deiner Anpassungsfähigkeit ab."
  },
  AvgDialog_10129_Content_8 = {
    Text = "Gehe zur nächsten <Blue:Verbindung> und hilf, Ramonas Wunden zu heilen."
  },
  AvgDialog_10130_Content_10 = {
    Text = "Solange unsere Namen auf dem Denkmal eingraviert sind, wird unsere Existenz nicht von @2 ausgelöscht."
  },
  AvgDialog_10130_Content_11 = {
    Text = "Eine sanfte Stimme, verwoben mit verzerrten Kreischen, hallt in deinem Geist wider."
  },
  AvgDialog_10130_Content_12 = {
    Text = "Ich werde Ihr Assistent sein und Sie bis zum Ende dieses Pfades begleiten... <Yellow:Möge der Silberne Schlüssel Ihren Weg erleuchten.>"
  },
  AvgDialog_10130_Content_13 = {
    Text = [[
Alles in Ordnung, %player%?
Seit einer Weile siehst du blass aus. Soll ich dich ins Krankenzimmer bringen?]]
  },
  AvgDialog_10130_Content_14 = {
    Text = "Ihre klare Stimme brachte Klarheit in den Geist, und der Schwindel ließ allmählich nach."
  },
  AvgDialog_10130_Content_15 = {
    Text = "Keine Sorgen, nur ein wenig schwindelig, aber es ist jetzt besser."
  },
  AvgDialog_10130_Content_16 = {
    Text = "Hmm, nur um auf Nummer sicher zu gehen, bleiben wir verbunden.\nAls dein Assistent und Partner ist es meine Pflicht, immer deinen Zustand zu überprüfen."
  },
  AvgDialog_10130_Content_17 = {
    Text = "Jetzt? Hier?"
  },
  AvgDialog_10130_Content_18 = {
    Text = "Etwas früher, aber das ist in Ordnung, oder?"
  },
  AvgDialog_10130_Content_19 = {
    Text = "Seit einem Jahr freue ich mich auf heute"
  },
  AvgDialog_10130_Content_2 = {
    Text = "Willkommen an der Mythag Universität, %player%."
  },
  AvgDialog_10130_Content_21 = {
    Text = "Der Regen benetzt deine Fingerspitzen, ein schwacher Strom durchdringt die Handschuhe und fließt heimlich über deine Haut und ihre Fingerspitzen"
  },
  AvgDialog_10130_Content_22 = {
    Text = "Ein unerklärliches Gefühl durchströmte deine Nerven, es war Freude, Aufregung, Unruhe und"
  },
  AvgDialog_10130_Content_23 = {
    Text = "...<Yellow: Hoffnung>."
  },
  AvgDialog_10130_Content_3 = {
    Text = "Oder vielmehr... willkommen, du hast offiziell die verborgene Seite der Welt betreten."
  },
  AvgDialog_10130_Content_4 = {
    Text = "Ich bin zurück."
  },
  AvgDialog_10130_Content_5 = {
    Text = "Dein Beitritt ist das, worauf alle gewartet haben. In zwei Tagen wird William uns eine <Yellow:Katastrophen-Ermittlungsaufgabe> zuweisen."
  },
  AvgDialog_10130_Content_6 = {
    Text = "Er wird dir keinen Aufschub gewähren, einem einmal-in-einem-Jahrhundert Hüter."
  },
  AvgDialog_10130_Content_7 = {
    Text = "Hoffe, dass dein @1-Feldauftrag nicht so auf mich, den <Blue:>, angewiesen ist wie ein Kurs in Analysis."
  },
  AvgDialog_10130_Content_8 = {
    Text = "Never thought I'd attend my own funeral."
  },
  AvgDialog_10130_Content_9 = {
    Text = "Umarmung des Todes, damit wir ihn nicht mehr fürchten."
  },
  AvgDialog_10131_Content_1 = {
    Text = "Jetzt betreten Ogier und ich die Schlacht."
  },
  AvgDialog_10131_Content_2 = {
    Text = "Ich kann durch die Verknüpfung spüren, dass dein und Ogier Zustand noch nicht ausreichend ist, um"
  },
  AvgDialog_10131_Content_3 = {
    Text = "Es ist in Ordnung, Hüter.\nRitter existieren, um alle zu schützen, und Ogier kann durchhalten!"
  },
  AvgDialog_10131_Content_4 = {
    Text = "Mach dir keine Sorgen. Mit dir hier, um unsere Gedanken zu stabilisieren, werden wir die Kontrolle nicht verlieren und das Beste aus Aliemus machen können."
  },
  AvgDialog_10131_Content_5 = {
    Text = "Solange ich genügend Aliemus sammle, kann ich meinen Zustand wiederherstellen."
  },
  AvgDialog_10131_Content_6 = {
    Text = "Zögere nicht länger, Hüter.\nOb wir den Ring durchbrechen können, hängt von deinem Befehl ab."
  },
  AvgDialog_10131_Content_7 = {
    Text = "Lass mich sehen – was für eine Zukunft Missaga erwartet"
  },
  AvgDialog_10132_Content_1 = {
    Text = "Hmph, du denkst, du kannst diesen Planeten zerstören?"
  },
  AvgDialog_10132_Content_2 = {
    Text = "Weit davon entfernt! Bring es, egal wie viel mehr es gibt!"
  },
  AvgDialog_10133_Content_1 = {
    Text = "Ist es... vorbei...?"
  },
  AvgDialog_10133_Content_10 = {
    Text = "Sie streckte die Hand aus und klopfte leicht auf den Silbernen Schlüssel auf deiner Brust"
  },
  AvgDialog_10133_Content_11 = {
    Text = "Der Silberne Schlüssel blitzt mit einer schwachen Antwort."
  },
  AvgDialog_10133_Content_12 = {
    Text = "Du bist die Variable, die Antwort sowohl auf den Anfang als auch auf das Ende."
  },
  AvgDialog_10133_Content_13 = {
    Text = "Hoffentlich bist du der Wendepunkt..."
  },
  AvgDialog_10133_Content_15 = {
    Text = "Weiße sechsflügelige Monster, eine Frau mit einem gleichgültigen Ausdruck, schlammige Monster, die in einem Angriff verstreut sind, schattenhafte, verzerrte Hüter-Formen..."
  },
  AvgDialog_10133_Content_16 = {
    Text = "Sie verwandelten sich alle in einen Pool schwarzen Wassers und verschwanden dann spurlos."
  },
  AvgDialog_10133_Content_17 = {
    Text = "Ignoriere Ramona und Dolls Rufe, während du den silbernen Schlüssel hältst und nach oben in die \"Tür\" blickst, die zurück zu \"Tawil\" führt"
  },
  AvgDialog_10133_Content_18 = {
    Text = "Du erinnerst dich deutlich an das Gesicht, das du gerade gesehen hast.\nDer gleichgültige Ausdruck, die Konturen der Augenbrauen und Augen, und die Kurve der Lippen ähneln Ramona—"
  },
  AvgDialog_10133_Content_19 = {
    Text = "—Genau gleich."
  },
  AvgDialog_10133_Content_2 = {
    Text = "\"Tawil\" bleibt stehen, aber nicht mehr mit der gleichen Gelassenheit."
  },
  AvgDialog_10133_Content_20 = {
    Text = "Zwei Tage später\n\nSchlüsselgrab"
  },
  AvgDialog_10133_Content_21 = {
    Text = "...Die Mythag-Universität ist Pionier im Kampf gegen die Auflösung und dient als entscheidende Verteidigungslinie für die Zukunft der Menschheit."
  },
  AvgDialog_10133_Content_22 = {
    Text = "300 Jahre lang hat die Mythag-Universität einen hohen Preis gezahlt, um den Frieden der Menschheit vor der Auflösung zu schützen."
  },
  AvgDialog_10133_Content_23 = {
    Text = "Dieser Friedhof ist unser vorbereiteter Ruheort und auch der Entschluss der Lehrer und Schüler von Mythag, ihr Leben für das Überleben der Menschheit zu opfern."
  },
  AvgDialog_10133_Content_24 = {
    Text = "Die Rede ging weiter. Czort schloss die Augen und seufzte, der weiße Nebel aus seinem Atem dissipierte im Regen."
  },
  AvgDialog_10133_Content_25 = {
    Text = "...Ich glaube, unter all den neuen Studenten kann niemand das Gewicht dieser Worte besser verstehen als du."
  },
  AvgDialog_10133_Content_26 = {
    Text = "In den letzten 300 Jahren sind Anomalien wie Silber und Auflösungs-Mutanten gelegentlich im Schwarzen Pool aufgetaucht, aber eine Mutation in diesem Ausmaß ist ohnegleichen."
  },
  AvgDialog_10133_Content_27 = {
    Text = "Viele sind nie zurückgekehrt."
  },
  AvgDialog_10133_Content_28 = {
    Text = "Der Sprecher ist Czort, die amtierende Dekanin der Mythag Lebenswissenschaften. Es wird gemunkelt, dass sie überweltliche Wesen sehen kann und die Lieblingsschülerin des ehemaligen Dekans war."
  },
  AvgDialog_10133_Content_29 = {
    Text = "Ereignisse im Zusammenhang mit Auflösung kommen immer mit Überraschungen, Wahnsinn und Tod. Dies ist eine unvermeidliche Erfahrung auf unserem Weg."
  },
  AvgDialog_10133_Content_3 = {
    Text = "Bevor jemand anders reagieren konnte, breiteten sich plötzlich seine silbernen Flügel aus und stürzte sich auf Ramona."
  },
  AvgDialog_10133_Content_30 = {
    Text = [[
Du verstehst die Bedeutung von Czorts Worten.
Unter dem Grabstein vor dir ist niemand.]]
  },
  AvgDialog_10133_Content_31 = {
    Text = "Schwarzer Schleim fließt langsam über den Grabstein."
  },
  AvgDialog_10133_Content_32 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_10133_Content_33 = {
    Text = "Nach der Zeremonie hat der edle Dexter dich in sein Büro eingeladen."
  },
  AvgDialog_10133_Content_34 = {
    Text = [[
Der Name "Dexter" ist dir vertraut; es ist Ramonas Nachname.
Dieser "Edel Dexter" ist dein Professor und auch Ramonas Adoptivvater.]]
  },
  AvgDialog_10133_Content_35 = {
    Text = "Ich habe diesen Teil im Bericht gesehen, und ich muss Sie um einen Gefallen bitten."
  },
  AvgDialog_10133_Content_36 = {
    Text = "Über Tawils Erscheinung... könntest du das bitte Ramona gegenüber geheim halten?"
  },
  AvgDialog_10133_Content_37 = {Text = "Warum?"},
  AvgDialog_10133_Content_38 = {
    Text = "Wie soll ich es ausdrücken... die Kausalität dahinter ist ziemlich komplex und schwer kurz zu erklären."
  },
  AvgDialog_10133_Content_39 = {
    Text = "Jedoch werde ich es ihr früher oder später mitteilen, nur nicht in diesem Moment."
  },
  AvgDialog_10133_Content_4 = {
    Text = "Die Zeit scheint zum Stillstand gekommen zu sein."
  },
  AvgDialog_10133_Content_40 = {
    Text = "Das liegt nicht an Mythags Vertraulichkeitsüberlegungen, sondern an der Bitte eines Vaters, seine Tochter zu schützen."
  },
  AvgDialog_10133_Content_41 = {
    Text = "Bitte, gib uns etwas Zeit, okay?"
  },
  AvgDialog_10133_Content_42 = {
    Text = "Auch wenn du die Wahrheit wissen möchtest, nickst du dennoch zustimmend."
  },
  AvgDialog_10133_Content_43 = {
    Text = "Danke für Ihr Verständnis.\nApropos, eine Charge königlichen Blend-Whiskys ist kürzlich angekommen. Ich habe es geschafft, dass jemand heimlich zwei Flaschen beiseitegeräumt hat."
  },
  AvgDialog_10133_Content_44 = {
    Text = "Hier, nimm es und lade Ramona ein, den Geschmack des Erwachsenseins zu erleben — betrachte es als dein exklusives Initiationsritual, wie wäre es damit?"
  },
  AvgDialog_10133_Content_45 = {
    Text = "Ich fürchte, das ist unangemessen, edler Dexter.\nDie Auflösung wird nicht aufhören zu verbreiten, während wir rasten."
  },
  AvgDialog_10133_Content_46 = {
    Text = "Oh nein, William hat seinen Weg hierher gefunden.\nIch fürchte, ich kann dich jetzt nicht retten, Kleines."
  },
  AvgDialog_10133_Content_47 = {
    Text = "Das Dossier wurde organisiert. Du kannst dich jetzt auf deine Pflicht vorbereiten, neuer Hüter."
  },
  AvgDialog_10133_Content_48 = {
    Text = "Möge der Silberschlüssel unseren Weg erhellen."
  },
  AvgDialog_10133_Content_5 = {
    Text = "Du sprintetest mit maximaler Geschwindigkeit und schaffst es kaum, Ramona zu beschützen."
  },
  AvgDialog_10133_Content_6 = {
    Text = "Das weiße Monster starrt dich direkt an."
  },
  AvgDialog_10133_Content_7 = {
    Text = "Es blickt still mit seinem gesichtslosen, blassen Körper auf Sie."
  },
  AvgDialog_10133_Content_9 = {
    Text = "Bevor dir das Gesicht einer Frau mit einem gleichgültigen Ausdruck erscheint."
  },
  AvgDialog_10134_Content_1 = {
    Text = "Hey, du! Beeile dich und lass mich <Yellow:\"Klinge des Widerstands\"> entfesseln."
  },
  AvgDialog_10134_Content_2 = {
    Text = "Warte, Hüter.\nZuerst, setze \"Strike\" frei, wodurch Lotans Blutlust entfacht wird, was den Arithmetica-Verbrauch von <Yellow:\"Klinge der Herausforderung\"> reduzieren kann."
  },
  AvgDialog_10134_Content_3 = {
    Text = "Die richtige Kombination von Befehlen kann die Effektivität unserer Angriffe verdoppeln.\nDie Taktiken sind in den Befehlen verborgen, Hüter. Denk sorgfältig nach."
  },
  AvgDialog_10135_Content_1 = {
    Text = "Sei vorsichtig, komm nicht näher! Mein Schild steht kurz davor, zu brechen!"
  },
  AvgDialog_10135_Content_10 = {
    Text = "Du weißt, niemand sonst kann das außer mir."
  },
  AvgDialog_10135_Content_11 = {
    Text = "Wenn sie mich loben, ist es \"einmal im Jahrhundert\", aber wenn eine echte Krise kommt, werde ich wie eine Vase behandelt. Das ist unfair."
  },
  AvgDialog_10135_Content_12 = {
    Text = "Einige Risiken müssen eingegangen werden."
  },
  AvgDialog_10135_Content_13 = {
    Text = "Wir haben keine Wahl. Zu viele Menschen hier haben die Kontrolle verloren. Wenn wir uns nicht wehren, werden wir vom Wahnsinn verzehrt."
  },
  AvgDialog_10135_Content_14 = {
    Text = "Außerdem können wir beide allein unmöglich den Einschluss um den Uhrenturm durchbrechen.\nWir brauchen Hilfe. Wir brauchen die Macht, die Erwachten zu kontrollieren."
  },
  AvgDialog_10135_Content_15 = {
    Text = "Ramona, unterstütze mich."
  },
  AvgDialog_10135_Content_16 = {
    Text = "Da du so entschlossen bist... als dein \"Partner\" habe ich keinen Grund mehr, dich aufzuhalten."
  },
  AvgDialog_10135_Content_17 = {
    Text = "Ramona, immer bereit für den Kampf!"
  },
  AvgDialog_10135_Content_2 = {
    Text = "Mit einem \"Klang\" zerschlugen Lotans Zwillingsschwerter erneut den riesigen Schild, der aus schwarzem Schlamm gebildet wurde."
  },
  AvgDialog_10135_Content_3 = {
    Text = "Nicht genug, nicht genug! Entfache den Sturm! Gib mir einen aufregenden Kampf!"
  },
  AvgDialog_10135_Content_4 = {
    Text = "Der Erwacher namens Lotan schwang ihre Zwillingsklingen und griff unermüdlich Ogier an. Die bloße Kraft ihrer Angriffe offenbarte eine harte Realität—sie hatte die Kontrolle vollständig verloren."
  },
  AvgDialog_10135_Content_5 = {
    Text = "Angesichts der Situation können wir nur..."
  },
  AvgDialog_10135_Content_6 = {
    Text = "Ramona, hilf mir, Lotan zu bezwingen!"
  },
  AvgDialog_10135_Content_7 = {
    Text = "Sie können doch nicht denken, dass..."
  },
  AvgDialog_10135_Content_8 = {
    Text = "Ich werde sie verknüpfen!"
  },
  AvgDialog_10135_Content_9 = {
    Text = "Mach keine Witze, der Verlust der Kontrolle eines Erwachers resoniert über die Verknüpfung mit dem Ermittler, selbst du —"
  },
  AvgDialog_10136_Content_1 = {
    Text = "Das ist... Lotans stolzes <Yellow:\"Klinge der Widerstandsfähigkeit\">, fähig, mehrere Angriffe sofort auszuführen!"
  },
  AvgDialog_10136_Content_2 = {
    Text = "Um diesen Zug zu kontern... benutze <Yellow:\"Offensive Analyse\">, um kritische Schwachstellen zu vermeiden. Das ist sicherer."
  },
  AvgDialog_10137_Content_1 = {
    Text = "Du kannst mich nicht aufhalten! ...Unverschämte Menschen..."
  },
  AvgDialog_10137_Content_2 = {
    Text = "Du berührst den neu erworbenen Silberschlüssel und spürst eine schwache Vibration, die dich drängt, die Resonanz mit Lotan zu vervollständigen."
  },
  AvgDialog_10137_Content_4 = {
    Text = "<Shake:Wenn ich nur gewusst hätte... Ich hätte niemals einen Pakt mit dir geschlossen...>"
  },
  AvgDialog_10137_Content_5 = {
    Text = "Ramona näherte sich Lotan und streckte ihre Hand aus."
  },
  AvgDialog_10137_Content_6 = {
    Text = "Ich weiß, als du erweckt wurdest, versprach Mythag, an deiner Seite zu kämpfen... Kämpfen bis zum Ende dieses Planeten."
  },
  AvgDialog_10137_Content_7 = {
    Text = "Wir hatten nie die Absicht, unser Versprechen zu brechen. In den letzten 300 Jahren und in den nächsten 300 Jahren werden wir diese Last weiterhin tragen."
  },
  AvgDialog_10137_Content_8 = {
    Text = "Lotan, der intensive Kampf, auf den du gewartet hast, steht direkt vor deinen Augen."
  },
  AvgDialog_10138_Content_1 = {
    Text = "Bleib wachsam, es wird gleich angreifen. Dieser Schaden könnte mir gerade jetzt tödlich sein."
  },
  AvgDialog_10138_Content_2 = {
    Text = "Vertraue darauf, dass du die richtige Wahl triffst. Für die Aktion in dieser Runde wähle <Yellow:\"Verteidigung\">."
  },
  AvgDialog_10139_Content_1 = {
    Text = "Vielen Dank, Hüter. Du hast mich erneut gerettet.\nWenn es nicht für diese Verknüpfung wäre, wäre ich wahrscheinlich jetzt in großer Gefahr."
  },
  AvgDialog_10139_Content_2 = {
    Text = "Jetzt ist nicht die Zeit, um darüber zu sprechen—"
  },
  AvgDialog_10139_Content_3 = {
    Text = "Während du sprichst, breitet sich die pechschwarze Anomalie um dich herum aus.\nSchreie hallen ununterbrochen, während deine Klassenkameraden aus dem gestrigen Unterricht nacheinander in schwarzen Schlamm verwandelt werden."
  },
  AvgDialog_10139_Content_4 = {
    Text = "Ich habe die <Yellow:Intention> des Feindes, die durch den Silbernen Schlüssel erkannt wurde, über den Link geteilt. Sei vorsichtig, er wird gleich angreifen!"
  },
  AvgDialog_10140_Content_1 = {
    Text = "Spürst du die Aliemus, die durch mich fließt, Hüter?\nDank deines Unterdrückens mit geistiger Kraft hätte es mich sonst wie Lotan in den Wahnsinn getrieben."
  },
  AvgDialog_10140_Content_2 = {
    Text = "Jedoch kann es uns jetzt nützlich sein."
  },
  AvgDialog_10140_Content_3 = {
    Text = "Blick in die Richtung, in der Aliemus fließt... Ja, schaue auf das <Blue:oben links> des Kommandogeräts."
  },
  AvgDialog_10140_Content_4 = {
    Text = "Entfessle Exalt und umarme meine <Yellow:\"Mundus Deduction\">! \nWährend des Kampfes gegen Auflösung kann <Yellow:nur eine rationale Reaktion auf den Angriff die größte Überlebenschance sichern>."
  },
  AvgDialog_10141_Content_1 = {
    Text = "Verdammter, Lotan steht kurz davor, <Yellow:Exalt> zu entfesseln... Nur mit diesen Befehlen..."
  },
  AvgDialog_10141_Content_2 = {
    Text = "Der Silberne Schlüssel verbindet sich mit deinem Geist, resoniert einzigartig mit deinen starken Einsichten und Erinnerungen und erzeugt eine charakteristische Kraft."
  },
  AvgDialog_10141_Content_3 = {
    Text = "Schau auf die <Blue:unten links> des Kontrollgeräts! Der silberne Schlüssel ist vollständig aufgeladen, und die <Yellow:Truppe> ist bereit."
  },
  AvgDialog_10141_Content_4 = {
    Text = "Greife den Silber-Schlüssel, rezitiere den geheimen Text... entfessle <Yellow:Posse>, und gib mir mehr taktischen Raum!"
  },
  AvgDialog_10142_Content_2 = {
    Text = "Lass dich während einer so wichtigen Zeremonie nicht ablenken, <Yellow:Hüter>, du wirst als nächstes den Silbernen Schlüssel verliehen bekommen."
  },
  AvgDialog_10142_Content_3 = {
    Text = "Errichte deinen Grabstein, um unseren Willen zu beweisen, gegen <Yellow:Auflösung> zu kämpfen—eine Tradition von Mythag, die das Ende der Vorstudie markiert und die offiziellen Ermittler werden lässt."
  },
  AvgDialog_10142_Content_4 = {
    Text = "Wenn du bereit bist, gravier deinen Namen auf den Grabstein."
  },
  AvgDialog_116003_Content_1 = {
    Text = "Während die Baum-Menschen-Gemälde, die dir gehören, zerbrechen, schmilzt alles um dich herum in der Verzerrung."
  },
  AvgDialog_116003_Content_10 = {
    Text = "Aber ich möchte nicht, dass es nur ein Traum ist."
  },
  AvgDialog_116003_Content_11 = {
    Text = "Ich möchte zurück nach Misaq, ich möchte sie wiedersehen."
  },
  AvgDialog_116003_Content_12 = {
    Text = "...eine erwartbare Antwort."
  },
  AvgDialog_116003_Content_13 = {
    Text = "Aber diesmal kann ich endlich beruhigt sein, nachdem du deinen Entschluss gezeigt hast."
  },
  AvgDialog_116003_Content_14 = {
    Text = "%player%, dein Wille ist noch standhafter und mächtiger, als ich mir vorgestellt habe... stark genug, um Ihm und dem Chaos und Wahnsinn dieser Welt entgegenzutreten."
  },
  AvgDialog_116003_Content_15 = {
    Text = "Du schüttelst den Kopf und blickst in den kurz davor stehenden, vollständig zerbrochenen Traum zu Clementine."
  },
  AvgDialog_116003_Content_16 = {
    Text = "Nein, du liegst falsch, der Wille eines Menschen hat schließlich seine Grenzen."
  },
  AvgDialog_116003_Content_17 = {
    Text = "Der Grund, warum ich bis jetzt durchhalten konnte, ist, dass jeder in Misaq mich unterstützt."
  },
  AvgDialog_116003_Content_18 = {
    Text = "Sie haben gemeinsam für dich diesen schönen Traum in “dieser Welt“ erschaffen, und du bist entschlossen, diesen Traum in die Realität umzusetzen."
  },
  AvgDialog_116003_Content_19 = {
    Text = "Als Clementine deine Worte hörte und deinen ernsten Gesichtsausdruck sah, lächelte sie und zeigte ein entspanntes Lächeln."
  },
  AvgDialog_116003_Content_2 = {
    Text = "Du hast deinen eigenen Traum mit eigenen Händen zerbrochen."
  },
  AvgDialog_116003_Content_20 = {
    Text = "Ja, du hast noch “sie“, noch Tawil... und mich."
  },
  AvgDialog_116003_Content_21 = {
    Text = "Das stimmt. Ich war nie allein."
  },
  AvgDialog_116003_Content_22 = {
    Text = "In der ständig schmelzenden Landschaft ertönte ein Aufschrei, das war Tawils Antwort auf deine Worte.\nSie war immer da."
  },
  AvgDialog_116003_Content_23 = {
    Text = "Nun, %player%, ist dein schöner Traum wirklich zu Ende."
  },
  AvgDialog_116003_Content_24 = {
    Text = "Als Dank für deine Mitarbeit bei dieser Behandlung schenke ich dir ein kleines Geschenk. Ich hoffe, es gefällt dir."
  },
  AvgDialog_116003_Content_25 = {
    Text = "Mit Clementines letzten Worten zerbrach der Traum endgültig——"
  },
  AvgDialog_116003_Content_26 = {
    Text = "Der Himmel mit der hohen schwarzen Sonne erscheint vor dir, bringt grauenhaften Nebel und die Grausamkeit dieser Welt."
  },
  AvgDialog_116003_Content_27 = {
    Text = "Und in deiner Handfläche liegt still ein Foto. \n Ein Foto, das in einem “falschen schönen Traum“ aufgenommen wurde und in der grausamen Realität nicht existieren sollte."
  },
  AvgDialog_116003_Content_28 = {
    Text = "Am Meer, Volleyball, Festlichkeit, das Einzige, was anders ist als in der Erinnerung, ist Ramona."
  },
  AvgDialog_116003_Content_29 = {
    Text = "Das vertraute Gesicht lächelt ruhig, als ob es durch Zeit und Raum gereist wäre und dir in die Augen blickt. \n Es scheint direkt vor dir zu sein."
  },
  AvgDialog_116003_Content_3 = {
    Text = "Seit ich beschlossen habe, ihre Stärke zu nutzen, um diesen Traum zu erschaffen, wusste ich, dass dieser Tag kommen würde."
  },
  AvgDialog_116003_Content_30 = {
    Text = "<Small:Ramona......>"
  },
  AvgDialog_116003_Content_31 = {
    Text = "Du legst deine Hand auf das Foto, während dich Rührung und Zweifel überkommen."
  },
  AvgDialog_116003_Content_32 = {
    Text = "<Shake:Warum ist es Ramona...>"
  },
  AvgDialog_116003_Content_33 = {
    Text = [[
Deine Fragen bleiben unbeantwortet.
In einer von grauem Nebel durchzogenen Welt gibt es nur die stille schwarze Sonne, die stets wie zuvor bleibt.]]
  },
  AvgDialog_116003_Content_34 = {
    Text = "Egal wie auch immer......"
  },
  AvgDialog_116003_Content_35 = {
    Text = "Du hältst das Foto vor deine Brust, an der Stelle deines Herzens, und schließt die Augen."
  },
  AvgDialog_116003_Content_36 = {
    Text = "Egal was passiert, ich bin nicht allein."
  },
  AvgDialog_116003_Content_37 = {
    Text = "Dann öffnest du die Augen und blickst auf die hochhängende schwarze Sonne, gehst mit festen Schritten darauf zu."
  },
  AvgDialog_116003_Content_38 = {
    Text = "Diese Welt zerfällt weiterhin, von unbeschreiblichem Horror beobachtet, in einem instabilen Zustand, aber..."
  },
  AvgDialog_116003_Content_39 = {
    Text = "<Big:Du wirst einen Weg finden, es zu retten>"
  },
  AvgDialog_116003_Content_4 = {
    Text = "Ich hätte nur nicht gedacht, dass es so schnell kommen würde, und ich hätte nicht gedacht, dass du so entschlossen sein würdest."
  },
  AvgDialog_116003_Content_5 = {
    Text = "Eigentlich... ich habe gezögert und auch ausgewichen. Als ich am Strand war."
  },
  AvgDialog_116003_Content_6 = {
    Text = "Warum also nicht weiter in diesem Zustand verweilen? Ist dieser Ort nicht schön genug, nicht glücklich genug?"
  },
  AvgDialog_116003_Content_7 = {
    Text = "Du schweigst und erinnerst dich an dein Baum-Mensch-Gemälde."
  },
  AvgDialog_116003_Content_8 = {
    Text = "Es ist unbestreitbar, dass dies wirklich ein schöner Traum ist. Aber......"
  },
  AvgDialog_116003_Content_9 = {
    Text = "Allmählich ist die Szene in deinem Kopf nicht mehr eine Malerei, sondern das wahre Misaq, das wahre Doll, Ramona, Lotan und Ogier."
  },
  AvgDialog_117499_Content_1 = {
    Text = "<Shake:Zu viel...>"
  },
  AvgDialog_117499_Content_2 = {
    Text = "Unter dem düsteren Himmel schien der Sturm der Fischschwärme endlos zu sein. Du blickst dich um, in einer Ecke hängt eine rostige Metallleiter, und vorsichtig kletterst du damit auf die zweite Plattform."
  },
  AvgDialog_117499_Content_3 = {
    Text = "Hier können wir uns vorübergehend verstecken."
  },
  AvgDialog_117499_Content_4 = {
    Text = "Ein Hauch von Täuschung, begleitet von einem zahnverzerrenden Reibungsgeräusch, zieht deine Aufmerksamkeit auf sich."
  },
  AvgDialog_117499_Content_5 = {
    Text = "Warte, das da drüben ist..."
  },
  AvgDialog_117500_Content_1 = {Text = "Fesseln"},
  AvgDialog_117500_Content_10 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_117500_Content_100 = {
    Text = "Murphy schüttelte deprimiert den Kopf, ihre leblosen Augen suchten leer nach deiner Position. \n Sie wandte sich dir zu, presste ihre rissigen Lippen, die durch Blutarmut geschädigt waren, zusammen und zwang sich zu einem schwachen Lächeln."
  },
  AvgDialog_117500_Content_101 = {
    Text = "Du bist gekommen... Ich hätte nicht gedacht, dass ich dich jemals sehen würde..."
  },
  AvgDialog_117500_Content_102 = {
    Text = "Der Rumpf neigte sich plötzlich stark, und das salzige, kalte Wasser strömte heftig in die Kabine."
  },
  AvgDialog_117500_Content_103 = {
    Text = "Was ist los?!"
  },
  AvgDialog_117500_Content_104 = {
    Text = "Das Schiff ist auf ein Riff gestoßen?"
  },
  AvgDialog_117500_Content_105 = {
    Text = "Es ist unmöglich, das Rumpf der Paradeis hat einen sehr tiefen Tiefgang. Selbst wenn die Kabine auf Grund läuft und Wasser eindringt, kann sie in so kurzer Zeit nicht bis zur obersten Etage vollaufen..."
  },
  AvgDialog_117500_Content_106 = {
    Text = "Es sei denn..."
  },
  AvgDialog_117500_Content_107 = {
    Text = "Wilhelm rannte zum Bullauge, das vor ihm liegende Schauspiel glich den absurdesten Wahnvorstellungen. Die Paradeis sank mit unglaublicher Geschwindigkeit."
  },
  AvgDialog_117500_Content_108 = {
    Text = "Als ob der riesige Wal das kleine Boot zog, mit einer gewaltigen, unwiderstehlichen Kraft, die die Paradeis unaufhaltsam in die Tiefsee hinabzog."
  },
  AvgDialog_117500_Content_109 = {Text = "Ah—"},
  AvgDialog_117500_Content_11 = {
    Text = "Du öffnest erneut die Augen. Weich, warm, vertraut."
  },
  AvgDialog_117500_Content_110 = {
    Text = "Unter dem heftigen Zittern brach die Kette, die Murphys Handfläche durchbohrte, plötzlich."
  },
  AvgDialog_117500_Content_111 = {
    Text = "Eine klebrige, feuchte, weiche Hand tastet über deinen Handrücken, sie erträgt den Schmerz der durchstechenden Wunde in ihrer Handfläche, hält sanft deine Hand und sieht dir in die Augen."
  },
  AvgDialog_117500_Content_112 = {
    Text = "Sie murmelte, und die Worte, die sie ausstieß, hatten den metallischen Geruch von Rost, unklar, ob es vom Meerwasser oder vom Blut kam."
  },
  AvgDialog_117500_Content_113 = {
    Text = "Rette mich...... Wenn du es bist, kannst du es bestimmt......"
  },
  AvgDialog_117500_Content_114 = {
    Text = "Die letzten Worte versanken mit dem Wasser, das den Schiffsraum überflutete, in der Dunkelheit."
  },
  AvgDialog_117500_Content_12 = {
    Text = "<Small:Zuh, müssen wir wirklich auf diesen Kerl warten, bis er aufwacht?>"
  },
  AvgDialog_117500_Content_13 = {
    Text = "<Small:Goliath, du darfst den Befehl der Göttlichen Mutter nicht in Frage stellen.>"
  },
  AvgDialog_117500_Content_14 = {
    Text = "<Small:Sei unauffällig, Herr Goliath. Heute Morgen hat die Göttliche Mutter die Hohepriesterin eine Weile zur Zurechtweisung gerufen...>"
  },
  AvgDialog_117500_Content_15 = {
    Text = "Die Auseinandersetzung mit gedämpfter Stimme kam von hinter dem Vorhang."
  },
  AvgDialog_117500_Content_16 = {
    Text = "*Hust, hust...*"
  },
  AvgDialog_117500_Content_17 = {
    Text = "Bist du wach? Alle warten auf dich."
  },
  AvgDialog_117500_Content_18 = {
    Text = "Faros hob den Schleier an."
  },
  AvgDialog_117500_Content_19 = {
    Text = "Wurde ich das... wieder gerettet?"
  },
  AvgDialog_117500_Content_2 = {Text = "...Spinne?"},
  AvgDialog_117500_Content_20 = {
    Text = "Du bist ein Glückspilz, dass du überlebt hast. Wir sind nicht verpflichtet, all deine Fragen zu beantworten."
  },
  AvgDialog_117500_Content_21 = {
    Text = "Auf Befehl der Göttlichen Mutter haben die Seefahrer lange auf dein Erwachen gewartet."
  },
  AvgDialog_117500_Content_22 = {
    Text = "Das ist der frisch gepresste Zitronensaft, den die Göttliche Mutter mir aufgetragen hat. Trink ihn mit Dankbarkeit, Mensch."
  },
  AvgDialog_117500_Content_23 = {
    Text = "Da Er bereits wohlbehalten ist, werde ich also zu meiner Aufgabe als Navigator zurückkehren. Das Göttliche Reich ruft mich."
  },
  AvgDialog_117500_Content_24 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_117500_Content_25 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_117500_Content_26 = {
    Text = "Ist es eine wirklich geschehene Sache, oder ist es der Albtraum, als ich von Wasser überwältigt wurde...?"
  },
  AvgDialog_117500_Content_27 = {
    Text = "(muss einen Weg finden, um es zu überprüfen.)"
  },
  AvgDialog_117500_Content_28 = {
    Text = "Wenn ich mich nicht irre, war die letzte Person, die ich gesehen habe..."
  },
  AvgDialog_117500_Content_29 = {
    Text = "Du bist auf das Deck gegangen."
  },
  AvgDialog_117500_Content_3 = {
    Text = "Eine kleine dunkelviolette Spinne sieht dich mit großen Augen an. Als sie sieht, dass du aufwachst, hebt sie ihr Vorderbein und begrüßt dich."
  },
  AvgDialog_117500_Content_30 = {
    Text = "<Shake:Hey——Wilhelm, der Seniorstudent——>"
  },
  AvgDialog_117500_Content_31 = {
    Text = "<Shake:Versteck dich nicht——ich weiß, dass du hier bist——>"
  },
  AvgDialog_117500_Content_32 = {
    Text = "Auf dem Deck gibt es nur das Rauschen der ruhigen Wellen, dein Ruf verstreut sich im Morgennebel."
  },
  AvgDialog_117500_Content_33 = {
    Text = "(Lass es gut sein, es war wirklich nur mein Traum...)"
  },
  AvgDialog_117500_Content_34 = {Text = "Wow!"},
  AvgDialog_117500_Content_35 = {
    Text = "Der Boden unter deinen Füßen öffnete plötzlich eine Falltür, und du fällst mit einem dumpfen Geräusch in die Dunkelheit."
  },
  AvgDialog_117500_Content_36 = {
    Text = "Ein Haufen Stroh mildert den Aufprall deines Absturzes."
  },
  AvgDialog_117500_Content_37 = {
    Text = "Lange nicht gesehen, Hüter."
  },
  AvgDialog_117500_Content_38 = {
    Text = "Du kennst mich... du bist Wilhelm, der Seniorstudent, aus der ursprünglichen Welt..."
  },
  AvgDialog_117500_Content_39 = {
    Text = "Wilhelm ignoriert deinen überraschten Ton und wird stattdessen ernst."
  },
  AvgDialog_117500_Content_4 = {
    Text = "Schicht für Schicht liegen leichte Schleier und Samt auf dem verrosteten Deck. Die Frau mit dem Spinnrad starrt dich an."
  },
  AvgDialog_117500_Content_40 = {
    Text = "Ich erinnere mich nicht, dass ich dir in Misaq beigebracht habe, so auffällig in der feindlichen Basis zu handeln."
  },
  AvgDialog_117500_Content_41 = {
    Text = "Selbst der am bekanntesten für seine rüden Entscheidungen Dekan Czort wird deine Wahl wohl nicht unterstützen."
  },
  AvgDialog_117500_Content_42 = {
    Text = "Der vertraute Duft von Zedernholz, die vertraute aufrechte Haltung, der vertraute strenge Tonfall."
  },
  AvgDialog_117500_Content_43 = {
    Text = "Wilhelm, der Seniorstudent..."
  },
  AvgDialog_117500_Content_44 = {
    Text = "Ich hatte nicht vor, vor dir zu erscheinen, bevor wir das zentrale Problem gelöst haben."
  },
  AvgDialog_117500_Content_45 = {
    Text = "Dein Unbedachtsamkeit zwingt mich jedoch, die Strategie zu ändern."
  },
  AvgDialog_117500_Content_46 = {
    Text = "Weißt du, dass ich dir immer gefolgt bin?"
  },
  AvgDialog_117500_Content_47 = {
    Text = "William antwortete nicht auf die Frage, sondern warf dir nur einen scharfen Blick zu, der sagte: “Hältst du mich für einen Idioten?“"
  },
  AvgDialog_117500_Content_48 = {
    Text = "Wir sind bereits auf demselben Schiff, da können wir wahrscheinlich nicht ausweichen. Lass mich die Situation direkt klären, um Missverständnisse zu vermeiden."
  },
  AvgDialog_117500_Content_49 = {
    Text = "Kannst du mir vorher bitte die Informationen mitteilen, die du hast?"
  },
  AvgDialog_117500_Content_5 = {
    Text = "Diesmal seufzte sie nicht, sprach nicht, sondern schwieg einfach."
  },
  AvgDialog_117500_Content_50 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_117500_Content_51 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_117500_Content_52 = {
    Text = "Vom Gehirntank, der aus Schmelzen·Puppe gemacht wurde, über das Gefangensein im Sanatorium von Clementine, bis zu den Sehenswürdigkeiten der Nekropolis und schließlich zu dem “Albtraum“, den ich auf der Paradeis erlebt habe."
  },
  AvgDialog_117500_Content_53 = {
    Text = "Du wirst alles, was du auf dem Weg siehst, erzählen, während Wilhelm aufmerksam zuhört und gelegentlich nickt, um zu zeigen, dass er konzentriert bleibt."
  },
  AvgDialog_117500_Content_54 = {
    Text = "Als du von dem jungen Wilhelm erzählst, den du gesehen hast, zögerst du einen Moment, aber Wilhelm hebt nur die Hand und signalisiert dir, fortzufahren."
  },
  AvgDialog_117500_Content_55 = {
    Text = "Die Informationen, die du bereitgestellt hast, sind sehr nützlich."
  },
  AvgDialog_117500_Content_56 = {
    Text = "Wilhelm, der Seniorstudent, kannst du mir jetzt sagen, was du eigentlich verfolgst?"
  },
  AvgDialog_117500_Content_57 = {
    Text = "Wilhelm denkt einen Moment nach."
  },
  AvgDialog_117500_Content_58 = {
    Text = "Lass mich nachdenken, wo ich anfangen soll."
  },
  AvgDialog_117500_Content_59 = {
    Text = "Seit ich in diese Welt gefallen bin, habe ich zwei Fragen untersucht: Warum bin ich hierher gefallen und wie kann ich in meine ursprüngliche Welt zurückkehren?"
  },
  AvgDialog_117500_Content_6 = {
    Text = "Warum, ich erinnere mich klar daran, dass ich von unzähligen Seefahrern umzingelt wurde, und dann..."
  },
  AvgDialog_117500_Content_60 = {
    Text = "William nahm feierlich einen silbernen Schlüssel, den er nahe am Herzen aufbewahrt hatte, aus seiner Brust und sein Blick verriet einen Hauch von Nostalgie."
  },
  AvgDialog_117500_Content_61 = {
    Text = "Dieser Silberschlüssel ist von mir persönlich rekonstruiert worden, stammt von meinem ehemaligen Partner Fengol... Es wird oft gesagt, ich sei der legendärste Ermittler von Misaq, aber meiner Meinung nach liegt das nur daran, dass er früh verstorben ist."
  },
  AvgDialog_117500_Content_62 = {
    Text = "Erst als ich in diese Dimension fiel, wurde mir klar, dass er lediglich früher den Einblick in die Essenz der Welt hatte und als Pionier an der Frontlinie gegen die Auflösung kämpfte."
  },
  AvgDialog_117500_Content_63 = {
    Text = "Er hat das Geheimnis der Verbindung zwischen den beiden Welten verfolgt und einen entscheidenden Hinweis hinterlassen – eine Elfenbeinstatue."
  },
  AvgDialog_117500_Content_64 = {
    Text = "Wie gewohnt ist er immer einen Schritt voraus."
  },
  AvgDialog_117500_Content_65 = {
    Text = "Wilhelm schaute traurig, schüttelte den Kopf und steckte den Silberschlüssel wieder in seine Brust."
  },
  AvgDialog_117500_Content_66 = {
    Text = "... Hast du die Elfenbeinstatue gesehen, die Miryam oder Murphy in der Hand hatte?"
  },
  AvgDialog_117500_Content_67 = {Text = "Du nickst."},
  AvgDialog_117500_Content_68 = {
    Text = "Wenn sich alles wie beim letzten Mal entwickelt, findet über uns auf dem Deck ein Ritual statt, bei dem Murphy diese Statue verwendet."
  },
  AvgDialog_117500_Content_69 = {
    Text = "Die Elfenbeinstatue scheint in zahllosen Verbindungen mit der Essenz dieser Welt zu stehen."
  },
  AvgDialog_117500_Content_7 = {
    Text = "Du fühlst deinen Körper. Obwohl der Phantomschmerz weiterhin besteht, gibt es keine Spur von Wunden auf deiner Haut, und der große Kampf vor deiner Ohnmacht scheint nie stattgefunden zu haben."
  },
  AvgDialog_117500_Content_70 = {
    Text = "Also, um zurückzukehren, müssen wir vermutlich die Elfenbeinstatue bekommen und sie analysieren und erforschen."
  },
  AvgDialog_117500_Content_71 = {
    Text = "Nach dem Ende des Rituals sollte die Elfenbeinstatue in Murphys Raum zurückkehren..."
  },
  AvgDialog_117500_Content_72 = {
    Text = "Es ist drinnen sehr ruhig, eigentlich sollten alle nicht drinnen sein..."
  },
  AvgDialog_117500_Content_73 = {
    Text = "Vorsicht ist besser, wir sollten unnötige Konflikte vermeiden."
  },
  AvgDialog_117500_Content_74 = {
    Text = "Gut, dann schauen wir zuerst heimlich einen Blick darauf."
  },
  AvgDialog_117500_Content_75 = {
    Text = "Du schiebst die Tür vorsichtig auf."
  },
  AvgDialog_117500_Content_76 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_117500_Content_77 = {
    Text = "Ein Luftstrom, der von einem unangenehmen Geruch durchzogen ist, strömt in deine Nase, und du bemerkst, dass du unwillkürlich tief eingeatmet hast."
  },
  AvgDialog_117500_Content_78 = {
    Text = "Was ist los?"
  },
  AvgDialog_117500_Content_79 = {Text = "Geräusch."},
  AvgDialog_117500_Content_8 = {
    Text = "Ist das... ein Albtraum?"
  },
  AvgDialog_117500_Content_80 = {
    Text = "Im ruhigen Raum ertönte endlich ein Geräusch."
  },
  AvgDialog_117500_Content_81 = {
    Text = "Geräusch von Wassertropfen."
  },
  AvgDialog_117500_Content_82 = {
    Text = "Tick, Tack, das Geräusch von Tropfen, die in die gerade entstandene kleine Pfütze fallen."
  },
  AvgDialog_117500_Content_83 = {
    Text = "Acht straffe Eisenketten erstrecken sich von Murphys Gliedmaßen und fesseln sie fest. \n Ihre Brust wurde von einem riesigen blutigen Loch aufgebrochen."
  },
  AvgDialog_117500_Content_84 = {
    Text = "Das Blut fließt entlang der erschreckenden Wunde und tropft in die sich langsam bildende Blutlache, die die Quelle des tikkenden Geräuschs ist, das in deinen Ohren widerhallt."
  },
  AvgDialog_117500_Content_85 = {Text = "Murphy...!"},
  AvgDialog_117500_Content_86 = {
    Text = "Du bist zu spät gekommen."
  },
  AvgDialog_117500_Content_87 = {
    Text = "Es fühlt sich an, als würde eine unsichtbare Hand dein Herz fest umklammern, und der vertraute, erstickende Schmerz durchdringt dich heftig, begleitet von den Bruchstücken von Erinnerungen."
  },
  AvgDialog_117500_Content_88 = {
    Text = "Das zu grelle Licht schmerzte in den Augen und ließ unkontrollierbar Tränen fließen"
  },
  AvgDialog_117500_Content_89 = {
    Text = "Die trübe Flüssigkeit floss ab, und die Augen konnten sich endlich wieder auf das Mädchen fokussieren"
  },
  AvgDialog_117500_Content_9 = {
    Text = "Die Frau nickte stumm, ihre Gestalt verschwand im nebligen Dunst."
  },
  AvgDialog_117500_Content_90 = {
    Text = "Die Klinge steckt tief in der Brust, das mondbeschienene Mädchen öffnet ihre Augen"
  },
  AvgDialog_117500_Content_91 = {
    Text = "Der Todessymbol-Mond ist nah, aber das junge Gesicht zeigt keine Angst"
  },
  AvgDialog_117500_Content_92 = {
    Text = "Ich habe es getan... Ich habe es wirklich getan."
  },
  AvgDialog_117500_Content_93 = {
    Text = "Ich... habe es durchbohrt... Es wird nicht geboren..."
  },
  AvgDialog_117500_Content_94 = {Text = "Damit"},
  AvgDialog_117500_Content_95 = {
    Text = "Die Hand, die den Messergriff hielt, sank kraftlos herab, und rote, zähe, tiefschwarze Flüssigkeit strömte aus der Wunde und tropfte zwischen den Fingern ins Meer"
  },
  AvgDialog_117500_Content_96 = {
    Text = "*Hust, hust...*"
  },
  AvgDialog_117500_Content_97 = {
    Text = "Du bist... die Person im Traum..."
  },
  AvgDialog_117500_Content_98 = {
    Text = "Sprich erst einmal nicht! Ich helfe dir..."
  },
  AvgDialog_117500_Content_99 = {
    Text = "Du versuchst verzweifelt, doch es bringt nichts, die Ketten geben bei Murphys schmerzhaften Zitterern ein leises Wimmern von sich."
  },
  AvgDialog_117501_Content_10 = {
    Text = "Warum fragt die Göttliche Mutter so?"
  },
  AvgDialog_117501_Content_11 = {
    Text = "In der letzten Nacht hatte ich einen Traum."
  },
  AvgDialog_117501_Content_12 = {
    Text = "In meinem Traum benutze ich diesen Ritualdolch..."
  },
  AvgDialog_117501_Content_13 = {
    Text = "Sie hob die Hand und deutete auf den Dolch, den Miryam nie von sich ließ. \n Die Klinge schimmerte und strahlte ein gespenstisches Licht aus, das wie vergiftet wirkte."
  },
  AvgDialog_117501_Content_14 = {
    Text = "Durch die eigene Brust gestochen."
  },
  AvgDialog_117501_Content_15 = {
    Text = "“Er wird nicht geboren...“"
  },
  AvgDialog_117501_Content_16 = {
    Text = "Murphy murmelte vor sich hin, während ihre Fingerspitzen sanft über die blutigen Narben auf ihrer Brust strichen."
  },
  AvgDialog_117501_Content_17 = {
    Text = "Es ist ein illusorischer Albtraum."
  },
  AvgDialog_117501_Content_18 = {
    Text = "Miryam trat vor und kniete sich vor Murphys Knien nieder, legte sanft ihre Handfläche auf ihren Handrücken, um Trost zu spenden."
  },
  AvgDialog_117501_Content_19 = {
    Text = "Sei unbesorgt, der Wunsch der Seefahrer ist erfüllt, Er existiert, Er ist in dieser Welt erschienen."
  },
  AvgDialog_117501_Content_2 = {Text = "Gemurmel"},
  AvgDialog_117501_Content_20 = {
    Text = "Und du und ich werden schließlich das ewige Göttliche Reich erreichen und vor seinem Thron die Herrlichkeit der Götter teilen."
  },
  AvgDialog_117501_Content_21 = {
    Text = "Ihre Worte waren wie das Gebet vor dem Altar, erfüllt von Ehrfurcht und Andacht."
  },
  AvgDialog_117501_Content_22 = {
    Text = "Was, wenn wir das Göttliche Reich nicht erreichen können? Ich meine, wenn..."
  },
  AvgDialog_117501_Content_23 = {
    Text = "Miryam unterbrach sofort Murphys zögerliche Nachfrage."
  },
  AvgDialog_117501_Content_24 = {
    Text = "In der Prophezeiung des Götterkönigs wurden solche Angelegenheiten nicht übermittelt.\nDer nächste Moment der richtigen Position ist morgen, sein Blut wird uns den Weg zum verheißenen Land weisen."
  },
  AvgDialog_117501_Content_25 = {
    Text = "Murphy runzelte die Stirn."
  },
  AvgDialog_117501_Content_26 = {
    Text = "Ich werde mich ausruhen, Miryam, du solltest auch zurückgehen und dich ausruhen."
  },
  AvgDialog_117501_Content_27 = {
    Text = "Ich werde bis zum Morgengrauen für die Göttliche Mutter beten und um eine ruhige Nacht für Sie bitten."
  },
  AvgDialog_117501_Content_28 = {
    Text = "Murphy schwieg, ihr tiefer Blick folgte Miryams Gestalt, bis das Quietschen der sich schließenden Tür zu hören war."
  },
  AvgDialog_117501_Content_29 = {
    Text = "Sie wandte sich deprimiert dem Altar im Schatten zu, schloss die Augen und betete."
  },
  AvgDialog_117501_Content_3 = {
    Text = "Oh, edle Göttliche Mutter, du schaust wieder auf das Licht."
  },
  AvgDialog_117501_Content_30 = {
    Text = "Morgen, der Tag der richtigen Position......"
  },
  AvgDialog_117501_Content_31 = {
    Text = "Das seltsame Wesen, das auf dem Altar verehrt wurde, gab ihr keinerlei Antwort, still wie ein Fossil unter dem Eis. \n Murphy öffnete entschlossen die Augen."
  },
  AvgDialog_117501_Content_32 = {
    Text = "Um die Fortsetzung dieses Traums zu gewährleisten..."
  },
  AvgDialog_117501_Content_33 = {
    Text = "Sie streckte ihren von schwerem schwarzem Stoff verdeckten zarten Arm aus und hob den Ritualdolch hoch —"
  },
  AvgDialog_117501_Content_34 = {
    Text = "Im Licht der Kerze sticht der Schatten des Dolches heftig in das schlafende Wickeln auf dem Altar."
  },
  AvgDialog_117501_Content_35 = {
    Text = "Mit einem Plopp ertönt das unheimliche Geräusch von durchstochenem, zähem Fleisch. \n Der schwarze Schleim breitet sich allmählich aus und durchnässt die auffälligen Seefahrer-Runen auf dem Samtwickeln."
  },
  AvgDialog_117501_Content_36 = {
    Text = "Eine weitere Nacht steht bevor, die bald erscheinen wird..."
  },
  AvgDialog_117501_Content_37 = {
    Text = "Sie atmete erleichtert auf und schloss die Augen, doch was sie überkam, war nicht die bodenlose Dunkelheit, sondern der Traum von gestern."
  },
  AvgDialog_117501_Content_38 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_117501_Content_39 = {
    Text = "(Der Moment, in dem es mir ins Herz sticht, die Person, die neben mir steht...)"
  },
  AvgDialog_117501_Content_4 = {
    Text = "Ruhe dich frühzeitig aus, morgen ist der Tag der richtigen Position, und du musst den Seefahrern den Weg mit heiligem Blut weisen."
  },
  AvgDialog_117501_Content_40 = {
    Text = "(Es scheint, als hätte ich es noch nie gesehen, aber es fühlt sich irgendwie nostalgisch an...)"
  },
  AvgDialog_117501_Content_41 = {
    Text = "......Spinne?"
  },
  AvgDialog_117501_Content_42 = {
    Text = "Eine kleine dunkelviolette Spinne starrt dich am Mast mit großen Augen an. Als sie sieht, dass du aufwachst, hebt sie ihr Vorderbein und begrüßt dich."
  },
  AvgDialog_117501_Content_43 = {
    Text = "Im Traum schien ich Gesang zu hören..."
  },
  AvgDialog_117501_Content_44 = {
    Text = "Ätherisch, weich, wie die Gesänge einer Dichterin des Meeres, die in deinen Ohren widerhallen."
  },
  AvgDialog_117501_Content_45 = {
    Text = "Die Söhne und Töchter der Tragödie, das Gewebe des Schicksals ist bereits gewoben, ihr werdet schließlich den vorbestimmten Weg beschreiten."
  },
  AvgDialog_117501_Content_46 = {
    Text = "Und du, Gast aus einer anderen Welt——"
  },
  AvgDialog_117501_Content_47 = {
    Text = "Wenn die Sterne richtig stehen, setze bitte das Ende des Zyklus der Tragödie fest."
  },
  AvgDialog_117501_Content_48 = {
    Text = "Begleitet von einem langen Seufzer verschwand das Phantasma der Frau."
  },
  AvgDialog_117501_Content_49 = {Text = "?!"},
  AvgDialog_117501_Content_5 = {
    Text = "Murphy starrte gebannt auf die flackernde Flamme der Laterne, das schwarze Tuch schwang mit ihren Bewegungen und warf vorhangartige Phantasma an die Wände der Kabine."
  },
  AvgDialog_117501_Content_50 = {
    Text = "Nachdem das plötzliche Gefühl des Schreckens vergangen ist, kannst du dich beruhigen und die Umgebung um dich herum beobachten."
  },
  AvgDialog_117501_Content_51 = {
    Text = "Wo bin ich...?"
  },
  AvgDialog_117501_Content_52 = {
    Text = "Weiche Matratze. Ein ruhiger Raum, bedeckt mit schwarzem Schleier. Ein Hauch von Salbei und Räucherduft schwebt in der Luft."
  },
  AvgDialog_117501_Content_53 = {
    Text = "Vorher... ich..."
  },
  AvgDialog_117501_Content_54 = {
    Text = "Doll! Kannst du das Signal empfangen? Doll?"
  },
  AvgDialog_117501_Content_55 = {
    Text = "Schrei nicht so laut, du störst meinen Sprachwellenempfänger."
  },
  AvgDialog_117501_Content_56 = {
    Text = "Ich habe das Schiff gefunden, auf das William laut den Fischern gestiegen ist! Aber es ist in den Sturm gefahren!"
  },
  AvgDialog_117501_Content_57 = {
    Text = "Der nächste Satz ist..."
  },
  AvgDialog_117501_Content_58 = {
    Text = "Ich werde hineinverfolgen!"
  },
  AvgDialog_117501_Content_59 = {
    Text = "Mit diesem kleinen Fischerboot? In die Schlucht der Bermudainseln rasen? Hast du keine Angst, darin umzukippen?"
  },
  AvgDialog_117501_Content_6 = {
    Text = "Miryam, hast du einen Traum gehabt?"
  },
  AvgDialog_117501_Content_60 = {
    Text = "Wir dürfen keine Hinweise mehr verlieren, das ist die einzige wahre und nützliche Information, die wir seit Monaten erhalten haben!"
  },
  AvgDialog_117501_Content_61 = {
    Text = "Möge der Silberne Schlüssel deinen Weg weisen!"
  },
  AvgDialog_117501_Content_62 = {
    Text = "Am anderen Ende der Kommunikation kam nicht der Satz “Möge der Silberschlüssel uns leiten“, den du hättest hören sollen, sondern das Zischen von unterbrochener Verbindung."
  },
  AvgDialog_117501_Content_63 = {
    Text = "Was dich erwartet, sind riesige Wellen von tausend Metern Höhe, gefolgt von der endlosen Dunkelheit, die dich verschlingt——"
  },
  AvgDialog_117501_Content_64 = {
    Text = "Vor drei Monaten, verfolgt von den Nachrichten über den geheimnisvollen blonden Mann, der den Hafen von Innsmouth verließ, hast du William auf seiner Spur verfolgt."
  },
  AvgDialog_117501_Content_65 = {
    Text = "Kürzlich hast du endlich die von den Fischern beschriebene Flagge auf dem Meer gesehen, doch ein plötzlich aufkommender Sturm raubte dir die Richtung."
  },
  AvgDialog_117501_Content_66 = {
    Text = "Als ich die Augen erneut öffne, ist es die Szene vor mir."
  },
  AvgDialog_117501_Content_67 = {
    Text = "Bist du wach? Alle warten auf dich."
  },
  AvgDialog_117501_Content_68 = {
    Text = "Der schwarze Vorhang wurde leicht hochgehoben, und eine vertraute, aber fremde Frauenstimme ertönte."
  },
  AvgDialog_117501_Content_69 = {
    Text = "Leute...? Wer...?"
  },
  AvgDialog_117501_Content_7 = {
    Text = "Natürlich habe ich das. In unzähligen Träumen erhebt sich das große Lemuria aus der Tiefsee und erscheint im Sonnenlicht."
  },
  AvgDialog_117501_Content_70 = {
    Text = "Vier vertraute Gesichter umgeben seltsamerweise dein Bett."
  },
  AvgDialog_117501_Content_71 = {
    Text = "Gemäß dem Befehl der Göttlichen Mutter hat der Seefahrer lange auf dein Erwachen gewartet. Komm, trink diesen heilenden Trank, den die Göttliche Mutter für dich vorbereitet hat."
  },
  AvgDialog_117501_Content_72 = {
    Text = "Caecus stellte ein kunstvoll geschnitztes Glas auf den Tisch, die trübe, leuchtend gelbe Flüssigkeit war beunruhigend."
  },
  AvgDialog_117501_Content_73 = {
    Text = "Was ist hier drin...?"
  },
  AvgDialog_117501_Content_74 = {
    Text = "Wenn du die große Katastrophe überstanden hast, hör auf, weiter Fragen zu stellen."
  },
  AvgDialog_117501_Content_75 = {
    Text = "Es wurde auf Befehl der Göttlichen Mutter gepresst. Trink es mit Dankbarkeit, Mensch."
  },
  AvgDialog_117501_Content_76 = {
    Text = "Vor den Augen aller nimmst du vorsichtig einen Schluck."
  },
  AvgDialog_117501_Content_77 = {
    Text = "Puh—— so sauer——! Ist das reiner Zitronensaft?!"
  },
  AvgDialog_117501_Content_78 = {
    Text = "Du sitzt abrupt auf, von der Säure überrascht, und deine Augenbrauen sind zusammengezogen."
  },
  AvgDialog_117501_Content_79 = {
    Text = "Da Er wohlbehalten ist, möchte ich auf das Deck gehen und die Eingebung empfangen. Das Göttliche Reich ruft mich."
  },
  AvgDialog_117501_Content_8 = {
    Text = "Ewiges Licht säen in fernen Meeren, weist dir und mir den neuen Kurs."
  },
  AvgDialog_117501_Content_80 = {
    Text = "(Diese Welt und ich, einer von uns muss verrückt geworden sein...)"
  },
  AvgDialog_117501_Content_81 = {
    Text = "Lass mich vorerst fragen... Wo ist das hier?..."
  },
  AvgDialog_117501_Content_82 = {
    Text = "Die Paradeis-Kreuzfahrt, das einzige und wichtigste maritime Paradies der Seefahrer."
  },
  AvgDialog_117501_Content_83 = {
    Text = "Wir segeln zum ewigen Göttlichen Reich, Lemuria."
  },
  AvgDialog_117501_Content_9 = {
    Text = "Miryam gab die Antwort nahezu instinktiv, und in den folgenden Fragen schwang eine unübersehbare Verwunderung mit."
  },
  AvgDialog_117502_Content_1 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_117502_Content_10 = {
    Text = "In dem letzten Schimmer des Lichts, bevor das Sichtfeld in absolute Dunkelheit versinkt, siehst du eine Gestalt vorbeihuschen."
  },
  AvgDialog_117502_Content_11 = {
    Text = "Eine strahlende goldene Mähne, der präzise mechanische Arm flackert im metallischen Schimmer."
  },
  AvgDialog_117502_Content_12 = {
    Text = "Wilhelm... Seniorstudent..."
  },
  AvgDialog_117502_Content_2 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_117502_Content_3 = {
    Text = "Wie lange hast du im stinkenden Fischschwarm gekämpft?"
  },
  AvgDialog_117502_Content_4 = {
    Text = "Eine Stunde? Ein Tag? Oder eine Zeit, die man überhaupt nicht zählen kann?"
  },
  AvgDialog_117502_Content_5 = {
    Text = "(Das Fest ist die Zeit, in der die Seefahrer kollektiv mobilisiert werden. Zu diesem Zeitpunkt einzudringen... ist wirklich eine impulsive Fehlentscheidung.)"
  },
  AvgDialog_117502_Content_6 = {
    Text = "Das glitschige Gefühl ist so gewohnheitsmäßig geworden, dass es taub ist, und der faulige Schleim stellt kein Problem mehr für die verstopfte Nase dar."
  },
  AvgDialog_117502_Content_7 = {
    Text = "(Wenn ich noch einmal kommen könnte... schade...)"
  },
  AvgDialog_117502_Content_8 = {
    Text = "Du kämpfst, um den Silberschlüssel zu heben, der einst strahlende Kern beginnt zu zittern. \n Du bist wacklig und spuckst ein wenig Blut aus."
  },
  AvgDialog_117502_Content_9 = {
    Text = "(Ich bin schon... am Limit... Es tut mir leid... ich konnte nicht entkommen...)"
  },
  AvgDialog_117503_Content_1 = {
    Text = "Ein Reisender"
  },
  AvgDialog_117503_Content_10 = {
    Text = "Das Herz schlägt plötzlich unruhig, du öffnest instinktiv den Mund, denn du weißt bereits, wer der Besitzer des Gesichts hinter dem schwarzen Schleier ist."
  },
  AvgDialog_117503_Content_100 = {
    Text = "Der Fischschwarm bricht die Fesselung der Flüssigkeitsoberfläche, kämpft und zuckt in der klebrigen Luft und lässt nacheinander einen stinkenden, klebrigen Regen an deiner Seite niederprasseln."
  },
  AvgDialog_117503_Content_101 = {
    Text = "Begleitet von einem schaurigen Geräusch springt der halb verrottete Körper vergeblich auf dem Deck herum, und der verfaulte Schleim an der Aufprallstelle verströmt einen erstickenden, intensiven Gestank."
  },
  AvgDialog_117503_Content_102 = {
    Text = "Dünne, zerbrechliche Tentakel zerreißen den blassen Bauch und kriechen halb auf dich zu——"
  },
  AvgDialog_117503_Content_11 = {
    Text = "<Shake:Murphy...>"
  },
  AvgDialog_117503_Content_12 = {
    Text = "Zwischen den Stofffäden kam ihre blass-grünliche Haut zum Vorschein, so weiß wie der zerfallende Staub von Plankton."
  },
  AvgDialog_117503_Content_13 = {
    Text = "Mutig! Wie kannst du den Namen der Göttlichen Mutter so direkt aussprechen!"
  },
  AvgDialog_117503_Content_14 = {
    Text = "Kein Problem, Caecus, {Male=er,Female=sie} ist ein Gast des Paradieses und wird sich unserer großen Reise anschließen."
  },
  AvgDialog_117503_Content_15 = {
    Text = "Fünf Augen starren dich an und drängen alle Worte, die du ausspucken möchtest, zurück in deinen Bauch."
  },
  AvgDialog_117503_Content_16 = {
    Text = "...Murphy, kann ich kurz mit dir sprechen?"
  },
  AvgDialog_117503_Content_17 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_117503_Content_18 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_117503_Content_19 = {Text = "Murphy..."},
  AvgDialog_117503_Content_2 = {
    Text = "Das Mädchen, das mit dir spricht, sitzt still am Fußende deines Bettes, ein verschwommenes, schwarzes Gewebe verhüllt ihr Gesicht."
  },
  AvgDialog_117503_Content_20 = {
    Text = "Wenn du deine Gedanken noch nicht geordnet hast, habe ich eine Frage, die ich stellen möchte."
  },
  AvgDialog_117503_Content_21 = {
    Text = "Warum bist du auf dem Paradies angekommen? Soweit ich weiß, muss man in den Sturm eindringen, um dem Paradies näher zu kommen."
  },
  AvgDialog_117503_Content_22 = {
    Text = "Wenn du bereit bist, solch ein Risiko einzugehen, musst du etwas im Sinn haben."
  },
  AvgDialog_117503_Content_23 = {
    Text = "So, habt ihr einen Mann gesehen, der einen halben Kopf größer ist als ich und blonde Haare hat?"
  },
  AvgDialog_117503_Content_24 = {
    Text = "Murphy warf dir einen Blick zu und gab ein zischendes Lachen von sich."
  },
  AvgDialog_117503_Content_25 = {
    Text = "Bei deiner Größe gibt es unter der Besatzung sicher einige Leute wie dich."
  },
  AvgDialog_117503_Content_26 = {
    Text = "Nein, du erkennst ihn auf einen Blick... Er hat einen mechanischen Arm, sieht sehr gutaussehend aus und trägt einen Hauch von Zedern-Duft."
  },
  AvgDialog_117503_Content_27 = {
    Text = "...Dann kann ich bestätigen, dass ich sie noch nie gesehen habe.\nDie Besatzung strahlt immer einen schmutzigen und stinkenden Fischgeruch aus."
  },
  AvgDialog_117503_Content_28 = {
    Text = "Nun, Murphy, gibt es noch eine entscheidende Sache."
  },
  AvgDialog_117503_Content_29 = {Text = "Hm?"},
  AvgDialog_117503_Content_3 = {
    Text = "(So eine vertraute Stimme... wer ist das...)"
  },
  AvgDialog_117503_Content_30 = {
    Text = "Willst du mit mir entkommen?"
  },
  AvgDialog_117503_Content_31 = {Text = "Haah?!"},
  AvgDialog_117503_Content_32 = {
    Text = "Murphy war von deinen Worten überrascht und wurde dann wütend, was sich in ihrem Gesicht widerspiegelte.\n Sie bemühte sich, ihre Emotionen zu beherrschen, und gab ein spöttisches Lachen von sich."
  },
  AvgDialog_117503_Content_33 = {
    Text = "Entkommen, was bedeutet das?"
  },
  AvgDialog_117503_Content_34 = {
    Text = "Wörtlich gesagt, wir müssen einen Weg finden, von diesem Schiff zu entkommen und der Kontrolle der Seefahrer zu entfliehen."
  },
  AvgDialog_117503_Content_35 = {
    Text = "Warum soll ich mit dir fliehen?"
  },
  AvgDialog_117503_Content_36 = {
    Text = "Weil du das Leben hier nicht magst."
  },
  AvgDialog_117503_Content_37 = {
    Text = "Du magst die von Miryam erfundenen Lehren nicht, magst den heuchlerischen Kult der Gläubigen nicht und hast kein Interesse an den illusorischen Ehren."
  },
  AvgDialog_117503_Content_38 = {
    Text = "Murphys Kopf senkte sich allmählich."
  },
  AvgDialog_117503_Content_39 = {
    Text = "Als du sie schweigend sahst, hast du rechtzeitig Feuer hinzugefügt."
  },
  AvgDialog_117503_Content_4 = {
    Text = "Du stützt deinen Oberkörper mit deinen schmerzenden Armen auf und versuchst, die aktuelle Umgebung zu erfassen."
  },
  AvgDialog_117503_Content_40 = {
    Text = "In einer anderen Welt habe ich dich gesehen, ich kenne dich, wir haben ähnliche Umstände erlebt, und du hast schließlich erfolgreich aus der Höhle der Monster entkommen..."
  },
  AvgDialog_117503_Content_41 = {Text = "Hmph..."},
  AvgDialog_117503_Content_42 = {
    Text = "Falsch, falsch! Du liegst völlig falsch!"
  },
  AvgDialog_117503_Content_43 = {Text = "Murphy...?"},
  AvgDialog_117503_Content_44 = {
    Text = "Murphys Reaktion übertraf all deine Erwartungen, sie lachte kichernd."
  },
  AvgDialog_117503_Content_45 = {
    Text = "Das Lachen wurde allmählich wahnsinnig, bis im Raum nur noch ihr übertriebenes, ausschweifendes Lachen widerhallte."
  },
  AvgDialog_117503_Content_46 = {
    Text = "Nach einer Weile schien sie schließlich müde vom Lachen zu sein, ihr Lachen verstummte abrupt.\nSie hob den Kopf und starrte dich wütend an."
  },
  AvgDialog_117503_Content_47 = {
    Text = "Der Embryo des Gottes wird in meiner Brust geboren. Ich bin die ehrwürdige Mutter des Gottes, von allen geliebt. Warum sollte ich den gewöhnlichen Menschen wie euch “entfliehen“?"
  },
  AvgDialog_117503_Content_48 = {
    Text = "Aber wenn der Gott geboren wird, wirst du sterben..."
  },
  AvgDialog_117503_Content_49 = {
    Text = "Warte nicht mehr, du törichter Mensch."
  },
  AvgDialog_117503_Content_5 = {
    Text = "Dummkopf, beweg dich nicht."
  },
  AvgDialog_117503_Content_50 = {
    Text = "Murphy hielt einen deformierten Wickel in den Händen, der ursprünglich der Kopf eines Babys war, und darin war eine vertraut aussehende, bläulich-violette, gallertartige Masse aus Fleisch eingekapselt."
  },
  AvgDialog_117503_Content_51 = {
    Text = "Heiliges Kind?!"
  },
  AvgDialog_117503_Content_52 = {
    Text = "Aus der Silhouette erkennst du, dass es sich um den deformierten falschen Gott handelt, den das Geburtsritual der Sona-Nyl zu beschwören versucht."
  },
  AvgDialog_117503_Content_53 = {
    Text = "In dieser Welt ist das Heilige Kind bereits geboren? Aber warum ist es... so klein?!"
  },
  AvgDialog_117503_Content_54 = {
    Text = "Warum ist es so klein... das ist wirklich eine lächerliche Frage."
  },
  AvgDialog_117503_Content_55 = {
    Text = "Wenn es immer so klein bleibt, wird es nicht wie ein mit Muskelkraft aufgeblasener Wasserstoffballon sein, der gierig die Energie der Mutter absorbiert und unermüdlich meine Brust füllt, dehnt und drückt..."
  },
  AvgDialog_117503_Content_56 = {
    Text = "Dann, im Moment des Todes des Mutterkörpers, Absturz, Zerschmetterung, Veraschung..."
  },
  AvgDialog_117503_Content_57 = {
    Text = "Du hast es gesehen, das ist das Heilige Kind, das ich geboren habe."
  },
  AvgDialog_117503_Content_58 = {
    Text = "Nennst du das... Gott?"
  },
  AvgDialog_117503_Content_59 = {
    Text = "Und was ist damit? Hat jemand gesehen, wie der Gott, von dem die Seefahrer sprechen, geboren wurde?"
  },
  AvgDialog_117503_Content_6 = {
    Text = "Das Mädchen stand unruhig auf, der verhüllende schwarze Schleier wackelte nervös."
  },
  AvgDialog_117503_Content_60 = {
    Text = "Wer kann schon behaupten, dass dieses stinkende Fleisch und Blut in unseren Händen nicht der wahre “Gott“ ist?"
  },
  AvgDialog_117503_Content_61 = {
    Text = "Die Fragen ertönen wie ein Donnerschlag in deinem Kopf."
  },
  AvgDialog_117503_Content_62 = {
    Text = "Ich bin nicht die Murphy, die du kennst, ich bin die Göttliche Mutter der Seefahrer, die einzige Person, die mit seinem Blut verwandt ist."
  },
  AvgDialog_117503_Content_63 = {
    Text = "Was dich betrifft... Lass mich nicht bereuen, dich ins Paradies gebracht zu haben. \n Jetzt lass mich in Ruhe und verschwinde mit deinen lächerlichen Gedanken aus diesem Raum."
  },
  AvgDialog_117503_Content_64 = {
    Text = "Du wanderst auf der Paradeis, den Erinnerungen der Vergangenheit folgend, während die kleinen Fischmenschen-Seemänner geschäftig umherlaufen und dich ignorieren."
  },
  AvgDialog_117503_Content_65 = {
    Text = "Bis du neben dem Kraftwerk zwei vertraute Gestalten siehst."
  },
  AvgDialog_117503_Content_66 = {
    Text = "Kleiner, sei großzügig, greif an!"
  },
  AvgDialog_117503_Content_67 = {Text = "Ja!"},
  AvgDialog_117503_Content_68 = {
    Text = "Ding Dong——!"
  },
  AvgDialog_117503_Content_69 = {
    Text = "Wurde es immer noch abgewehrt...? Verdammt, wie lange wird es noch dauern, bis ich Herr Goliath helfen kann, zu erobern..."
  },
  AvgDialog_117503_Content_7 = {
    Text = "Auf der Paradeis haben wir viele Patienten gesehen, die empfindlich auf die Ozeanumgebung reagieren. Bevor sie sich an das “Paradies“ gewöhnen, sollten sie ihre Spiritualität nicht stark schwanken lassen."
  },
  AvgDialog_117503_Content_70 = {
    Text = "Beruhig dich, Kleiner, Wände haben Ohren. Wenn wir entdeckt werden, können du und ich nicht entkommen."
  },
  AvgDialog_117503_Content_71 = {
    Text = "Herr Goliath, Sie haben doch gesagt, dass unser Blut von den Starken stammt, wir sollten nichts zu fürchten haben..."
  },
  AvgDialog_117503_Content_72 = {
    Text = "Verdammter Bursche, selbst die Starken müssen manchmal unter fremdem Dach leben. Auf diesem Schiff müssen wir so tun, als würden wir auf die verrückten Weiber hören."
  },
  AvgDialog_117503_Content_73 = {Text = "Aber..."},
  AvgDialog_117503_Content_74 = {
    Text = "Nicht viel reden, jemand kommt."
  },
  AvgDialog_117503_Content_75 = {
    Text = "Der Körper des Riesen trat aus dem Schatten des Kraftwerks, das Quietschen der riesigen gezackten Klinge, die über den Boden schleifte, übertönte fast das Dröhnen der Kabine."
  },
  AvgDialog_117503_Content_76 = {
    Text = "Wir sehen uns wieder, kleiner Kerl."
  },
  AvgDialog_117503_Content_77 = {
    Text = "Goliath... wie bin ich auf dieses Schiff gekommen?"
  },
  AvgDialog_117503_Content_78 = {
    Text = "Du solltest dich fragen, in Miryams Gebiet sind gewöhnliche Reisende nicht willkommen, geschweige denn ein plötzlich auftauchendes kleines Boot."
  },
  AvgDialog_117503_Content_79 = {
    Text = "Ich weiß nicht, welches Glück du hast, aber das kleine Mädchen hat vor ein paar Tagen ihre Meinung geändert und erlaubt uns auf keinen Fall, dich zu berühren."
  },
  AvgDialog_117503_Content_8 = {
    Text = "Du blickst in ein paar dir vertraut erscheinende rote Augen, die dir entgegenkommen."
  },
  AvgDialog_117503_Content_80 = {
    Text = "Sonst wird die Frau dich wahrscheinlich dazu bringen, Silberkerne zu raffinieren, schließlich kann man in einer Welt, in der die Menschen bereits ausgestorben sind, sagen, dass Silberkerne mit jedem Stück, das man verwendet, weniger werden."
  },
  AvgDialog_117503_Content_81 = {
    Text = "Und was ist mit deiner Position? Der Goliath, den ich kenne, ist kein schwacher Mensch, der sich herumkommandieren lässt."
  },
  AvgDialog_117503_Content_82 = {
    Text = "Kleiner, du bist gerade erst an Bord dieses Schiffs, es gibt noch viele Dinge, die du nicht weißt."
  },
  AvgDialog_117503_Content_83 = {
    Text = "Du musst nur eine Sache merken: Diese verrückte Frau ist jetzt völlig der Göttlichen Mutter untergeordnet. Alles auf diesem Schiff wird von diesem kleinen Mädchen entschieden."
  },
  AvgDialog_117503_Content_84 = {
    Text = "Versuche nicht, ihren Willen zu widersprechen—lass dich zumindest nicht von ihr entdecken."
  },
  AvgDialog_117503_Content_85 = {
    Text = "Die anderen Dinge werde ich dir erzählen, wenn wir uns an einem anderen Ort wiedersehen."
  },
  AvgDialog_117503_Content_86 = {
    Text = "Ich muss darüber nachdenken... Lass uns auf das Deck gehen und den Seewind genießen."
  },
  AvgDialog_117503_Content_87 = {
    Text = "Du stehst allein an der Schiffsspitze und blickst in die Ferne."
  },
  AvgDialog_117503_Content_88 = {
    Text = "Der Meeresspiegel ist von einem sanften, weißen Nebel umhüllt, während das Kreuzfahrtschiff ruhig und stabil die Geräusche des aufbrechenden Wassers und des mechanischen Betriebs durchbricht."
  },
  AvgDialog_117503_Content_89 = {
    Text = "Du holst tief Luft von der salzigen, fischigen Meeresbrise und versuchst, deine verworrenen Gedanken zu ordnen."
  },
  AvgDialog_117503_Content_9 = {
    Text = "——Dongdong, Dongdong——"
  },
  AvgDialog_117503_Content_90 = {
    Text = "Ich verfolgte Wilhelms Schiff in den Sturm und hatte einen Unfall, wurde von den Seefahrern gerettet..."
  },
  AvgDialog_117503_Content_91 = {
    Text = "Das Heilige Kind ist bereits geboren, Murphy ist die Heilige Mutter der Seefahrer, Miryam sammelt Silberkerne, und Goliath plant im Verborgenen etwas..."
  },
  AvgDialog_117503_Content_92 = {
    Text = "<Shake:Klick——>"
  },
  AvgDialog_117503_Content_93 = {
    Text = "Hm, was ist das für ein Geräusch?"
  },
  AvgDialog_117503_Content_94 = {
    Text = "Du drehst dich um, um der Quelle des Geräuschs nachzugehen, aber das Deck ist still und es ist kein Mensch zu sehen."
  },
  AvgDialog_117503_Content_95 = {
    Text = "(Ist es eine Illusion?)"
  },
  AvgDialog_117503_Content_96 = {
    Text = "<Shake:Platsch Platsch Platsch——>"
  },
  AvgDialog_117503_Content_97 = {Text = "Hä?!"},
  AvgDialog_117503_Content_98 = {
    Text = "In der Tiefe unter Wasser breiten sich zahlreiche kleine Körper dicht über die Wasseroberfläche aus, und der schwebende trübe Schimmer erinnert an einen Hautausschlag des menschlichen Körpers."
  },
  AvgDialog_117503_Content_99 = {
    Text = "Das sind... Fische?"
  },
  AvgDialog_117504_Content_1 = {Text = "Leitritual"},
  AvgDialog_117504_Content_10 = {
    Text = "Ich und Faros bereiten das Navigationsritual vor, während sich die spirituellen Wesen natürlich versammeln und zu Nahrung für das Ritual werden."
  },
  AvgDialog_117504_Content_100 = {
    Text = "Diese Stimme ruft dich—"
  },
  AvgDialog_117504_Content_101 = {
    Text = "<Italic:<Red:Hilf mir!>>"
  },
  AvgDialog_117504_Content_102 = {
    Text = "Der unbändige Impuls lässt dich vom Mast herab springen."
  },
  AvgDialog_117504_Content_103 = {
    Text = "Du musst ihre Hand halten und sie aus diesem blutigen Ritual befreien."
  },
  AvgDialog_117504_Content_104 = {
    Text = "Murphy, hör auf mit dem Ritual! Du wirst sterben! Komm mit mir, lass uns entkommen!"
  },
  AvgDialog_117504_Content_105 = {
    Text = "Bist du verrückt? Wie kannst du es wagen, die Göttliche Mutter zu beleidigen!"
  },
  AvgDialog_117504_Content_106 = {
    Text = "Ich bin nicht der Murphy, den du kennst, ich habe meine Entscheidung getroffen!"
  },
  AvgDialog_117504_Content_107 = {
    Text = "Obwohl du nicht der Murphy bist, den ich kenne, habe ich viele Ursprungserwecker gesehen – Ramona: Zeitverwittert, Helot: Kette, Doll: Inferno..."
  },
  AvgDialog_117504_Content_108 = {
    Text = "Sie sind in den Wahnsinn gefallen, weil sie auf dem Weg hierher mehr Unglück erlebt haben. Begegnungen werden die innere Grundfarbe nicht verändern."
  },
  AvgDialog_117504_Content_109 = {
    Text = "Komm nicht mehr von deinem Irrweg ab, lass uns zusammen fliehen!"
  },
  AvgDialog_117504_Content_11 = {
    Text = "Lotsenritual?"
  },
  AvgDialog_117504_Content_110 = {
    Text = "Flucht...? Wohin können wir noch fliehen?"
  },
  AvgDialog_117504_Content_111 = {
    Text = "Dies ist bereits die perfekteste Welt, alle Versuche zu fliehen werden nur in eine tiefere, verzweifeltere Schleife führen."
  },
  AvgDialog_117504_Content_112 = {
    Text = "Sieh zurück, die gewaltigen Wellen hinter dir."
  },
  AvgDialog_117504_Content_113 = {
    Text = "Begleitet von dem heftigen Kochen der Wasseroberfläche erhoben sich Tausende von Seefahrern und Wasserschlangen, die die blassweiße Elfenbeinstatue umschlangen, mit einem Gefühl unendlicher Bedrängnis."
  },
  AvgDialog_117504_Content_114 = {
    Text = "Göttliche Mutter... bitte verzeih mir, dass ich deinen Anweisungen nicht mehr folgen kann und diese blasphemischen Torheiten nicht länger ertragen kann."
  },
  AvgDialog_117504_Content_115 = {
    Text = "Miryam kniete am Bug des Schiffes und vollzog das ehrerbietige Opferritual in Richtung der geteilten Wasseroberfläche."
  },
  AvgDialog_117504_Content_116 = {
    Text = "Gottheit, die im Himmel ist, gläubiger Mensch. Der Blasphemiker, der versucht, das Ritual zu stören, ist bereits erschienen."
  },
  AvgDialog_117504_Content_117 = {
    Text = "Bitte bestrafen Sie die respektlosen Unholde, die es wagen, die Göttliche Mutter zu beleidigen."
  },
  AvgDialog_117504_Content_118 = {
    Text = "Sie schritten mit glitschigen und unheimlichen Schritten die unsichtbaren Stufen hinauf, die von den Wellen geformt wurden, und traten schweigend auf das Deck des Kreuzfahrtschiffes."
  },
  AvgDialog_117504_Content_119 = {
    Text = "<Big:<Shake:Geh, beiß sie zermahlen, zerreiß sie!!>>"
  },
  AvgDialog_117504_Content_12 = {
    Text = "Die Göttliche Mutter wird uns führen, um das aufsteigende Lemuria zu erreichen."
  },
  AvgDialog_117504_Content_13 = {
    Text = "Als sie dein unverständliches Gesicht sah, wurde Miryams Miene überraschend sanft."
  },
  AvgDialog_117504_Content_14 = {
    Text = "Du hast sicherlich viele Zweifel, mach dir keine Sorgen, im Auftrag der Göttlichen Mutter werde ich dir alles beantworten."
  },
  AvgDialog_117504_Content_15 = {
    Text = "...Um ehrlich zu sein, ist deine Einstellung schon ziemlich schockierend."
  },
  AvgDialog_117504_Content_16 = {
    Text = "Rückblickend war der Konflikt zwischen dir und den Seefahrern völlig unnötig."
  },
  AvgDialog_117504_Content_17 = {
    Text = "Wie kann das sein, ich habe einst mit eigenen Augen gesehen, wie die Seefahrer ein heidnisches Opferfest abhielten..."
  },
  AvgDialog_117504_Content_18 = {
    Text = "Es war ein Missverständnis. Die Seefahrer hielten ein geheimes Ritual ab, um die Energie zu sammeln, die für den Betrieb dieses Schiffes erforderlich ist."
  },
  AvgDialog_117504_Content_19 = {
    Text = "In dem Moment, in dem die meisten Menschen zu Asche zerfallen sind, reicht der in verschiedenen Orten angesammelte Silberkern aus, um unseren Bedarf zu decken."
  },
  AvgDialog_117504_Content_2 = {
    Text = "Inmitten des fischigen Geruchs runzelte die Frau in lila Roben die Stirn und wandte sich an Faros."
  },
  AvgDialog_117504_Content_20 = {
    Text = "Daher begaben sich die Seefahrer nach Nekropolis, um Silber von den Verstorbenen zu sammeln. Leider geriet unser Plan in Konflikt mit den Gelüsten von Doresain, dem König von Nekropolis."
  },
  AvgDialog_117504_Content_21 = {
    Text = "Laut unserem Verständnis der Misaq Universität werdet ihr auch den raffinierten Silberkern als Energiequelle verwenden, oder?"
  },
  AvgDialog_117504_Content_22 = {
    Text = "Der Silberschlüssel an deiner Brust ist aus der Silberkern-Technik gegossen."
  },
  AvgDialog_117504_Content_23 = {
    Text = "Du kannst es im Moment nicht akzeptieren, bist aber auch nicht in der Lage, zu widersprechen, und musst das Thema wechseln."
  },
  AvgDialog_117504_Content_24 = {
    Text = "Miryam... was ist dein Ziel mit den Seefahrern?"
  },
  AvgDialog_117504_Content_25 = {
    Text = "Es ist natürlich, das Göttliche Reich wieder aufzubauen und Lemuria wiederzubeleben."
  },
  AvgDialog_117504_Content_26 = {
    Text = "In dem Moment, in dem unser Herr bereits erschienen ist, gibt es nichts Wichtigeres, als in das Göttliche Reich zurückzukehren und das blühende Lemuria wiederzubeleben."
  },
  AvgDialog_117504_Content_27 = {
    Text = "Sprichst du von dem Erscheinen... Tulu?"
  },
  AvgDialog_117504_Content_28 = {
    Text = "Sein Geist ist noch im Halbschlaf, aber er wird sein Versprechen erfüllen und uns ins Göttliche Reich zurückführen."
  },
  AvgDialog_117504_Content_29 = {
    Text = "Lemuria... wo ist das?"
  },
  AvgDialog_117504_Content_3 = {
    Text = "Sammle den Geist hier."
  },
  AvgDialog_117504_Content_30 = {
    Text = "Über dem Himmel, unter dem Meer. Das Orakel hat nicht mehr offenbart."
  },
  AvgDialog_117504_Content_31 = {
    Text = "Nachdem sie diesen Code ausgesprochen hatte, verstummte Miryam."
  },
  AvgDialog_117504_Content_32 = {
    Text = "Faros, der alle Silberkerne eingesammelt hatte, hielt eine Holzkiste voller Silberperlen und stellte sich an die Seite von Miryam."
  },
  AvgDialog_117504_Content_33 = {
    Text = "Faros, warum bist du wieder den Seefahrern beigetreten?"
  },
  AvgDialog_117504_Content_34 = {
    Text = "Muss man das noch fragen? Weil das Meeresreich dort ist. Das Meeresreich ruft mich."
  },
  AvgDialog_117504_Content_35 = {
    Text = "Egal wohin ich gehe, kann ich seinen Ruf hören, wie das tägliche Surge der Wellen."
  },
  AvgDialog_117504_Content_36 = {
    Text = "Sie blickte in die Ferne, ihre Worte waren nur eine Nichtigkeit."
  },
  AvgDialog_117504_Content_37 = {
    Text = "Es sieht so aus, als ob das Wetter heute schön sein wird. Sieh mal, die Sonne kommt gleich heraus."
  },
  AvgDialog_117504_Content_38 = {
    Text = "Sonne......"
  },
  AvgDialog_117504_Content_39 = {
    Text = "Du folgst ihrem Blick—"
  },
  AvgDialog_117504_Content_4 = {
    Text = "Ja, Hohepriester."
  },
  AvgDialog_117504_Content_40 = {
    Text = "Donnernd, donnernd. Dein Herzschlag droht, das Trommelfell zu zerreißen."
  },
  AvgDialog_117504_Content_41 = {
    Text = "<Shake:Moment, wo ist die... Sonne am Himmel?>"
  },
  AvgDialog_117504_Content_42 = {
    Text = "Sonne? Steht die Sonne nicht dort?"
  },
  AvgDialog_117504_Content_43 = {
    Text = "Nein, nein, das ist nicht die Sonne!"
  },
  AvgDialog_117504_Content_44 = {
    Text = "Am Horizont erhebt sich die Sonne, die du dir immer gewünscht hast, sanft durch den hauchdünnen weißen Nebel strahlend."
  },
  AvgDialog_117504_Content_45 = {
    Text = "Nicht diese Sonne? Welche andere Sonne gibt es?"
  },
  AvgDialog_117504_Content_46 = {
    Text = "Das warme Licht scheint eine außergewöhnliche Hitze auszustrahlen, die deinen Verstand raubt, deinen Hals austrocknet und die Worte, die dir über die Lippen kommen, schwerfällig und unverständlich macht."
  },
  AvgDialog_117504_Content_47 = {
    Text = "Es sollte eine schwarze, lichtlose Sonne sein!"
  },
  AvgDialog_117504_Content_48 = {
    Text = "Ich habe noch nie von einer schwarzen Sonne gehört oder sie gesehen..."
  },
  AvgDialog_117504_Content_49 = {
    Text = "Faros, welches Jahr ist es dieses Jahr?"
  },
  AvgDialog_117504_Content_5 = {
    Text = "Faros kniete auf dem Boden und hob Stück für Stück die stinkenden Überreste auf."
  },
  AvgDialog_117504_Content_50 = {
    Text = "Im Jahr 1920. Gibt es da etwas, das nicht stimmt?"
  },
  AvgDialog_117504_Content_51 = {
    Text = "Es ist nicht die Überschwemmung... Ich bin tatsächlich in der neuen Welt..."
  },
  AvgDialog_117504_Content_52 = {
    Text = "Lass dich nicht ablenken, die Göttliche Mutter ist gekommen."
  },
  AvgDialog_117504_Content_53 = {
    Text = "Als Gast der Göttlichen Mutter werde ich dir gestatten, dieser prächtigsten Navigationszeremonie beizuwohnen."
  },
  AvgDialog_117504_Content_54 = {
    Text = "Aber verlasse diesen Ort auf keinen Fall, sonst werde ich den Blasphemiker enthaupten und zur Schau stellen."
  },
  AvgDialog_117504_Content_55 = {
    Text = "Ein kleines Team in Schwarz-Violett kommt vom Heck des Kreuzfahrtschiffs, ihre Schritte sind seltsam synchron und kriechen über das Deck unter euch."
  },
  AvgDialog_117504_Content_56 = {
    Text = "Das anführende Mädchen trug ein lebloses, weißes Kleid und hielt ein schweres, aufgeblähtes Bündel in den Händen, während ihr Gesicht unter dem schwarzen Schleier verschwommen und schwer zu erkennen war."
  },
  AvgDialog_117504_Content_57 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_117504_Content_58 = {
    Text = "Die Reihe stellte sich schnell am Bug des Schiffes auf, jeder schwarze Stein schien bereits genau zu wissen, wo er fallen sollte."
  },
  AvgDialog_117504_Content_59 = {
    Text = "Ein Paar barfüßiger Füße dringt in den schmalen Durchgang ein, der für sie in der Formation zurückgelassen wurde, hinter ihr fallen unzählige kleine silberne Fragmente leise zu Boden."
  },
  AvgDialog_117504_Content_6 = {
    Text = "Sie strahlte ein sanftes Licht von der Stirn aus, und nach einigen Sekunden blieb nur noch der silberne Rest des Fischschwarms übrig."
  },
  AvgDialog_117504_Content_60 = {
    Text = "Danke, Muttergöttin, für das gespendete Nabelblut! Wir werden das Feuer des Geistes verschlingen, das Blutgebet trinken und die tausend gläubigen Seelen zu einem Leuchtfeuer verwandeln!"
  },
  AvgDialog_117504_Content_61 = {
    Text = "Die Monster kriechen auf dem Boden und kämpfen darum, die silbernen Perlen aufzuheben."
  },
  AvgDialog_117504_Content_62 = {
    Text = "... Miryam ..."
  },
  AvgDialog_117504_Content_63 = {
    Text = "Miryam beugte sich demütig zu Boden, in der Mitte des von ihren Händen gehaltenen schwarzen Tuches lag ein schimmernder Dolch."
  },
  AvgDialog_117504_Content_64 = {
    Text = "Ehrwürdige Göttliche Mutter, ziehe das Blut des Gottkönigs und leite die fehlgeleiteten Seefahrer, um uns den Standort von Lemuria zu zeigen."
  },
  AvgDialog_117504_Content_65 = {
    Text = "Das Mädchen nahm den Dolch."
  },
  AvgDialog_117504_Content_66 = {
    Text = "Ehrenwerter Gottkönig..."
  },
  AvgDialog_117504_Content_67 = {
    Text = "Der Dolch sticht in das Wickeln, ein Tropfen zähflüssiger Blutmasse scheint wie von eigener Hand in der Luft zu schweben und sich zu sammeln."
  },
  AvgDialog_117504_Content_68 = {
    Text = "<Change>Ich folge dem Blut der Götter."
  },
  AvgDialog_117504_Content_69 = {
    Text = "Alle Gläubigen knieten nieder, die Hände gen Himmel erhoben, und schnitt mit einem dünnen Messer die mit Schuppen bedeckte linke Handgelenk auf."
  },
  AvgDialog_117504_Content_7 = {
    Text = "Miryam... sind diese fliegenden Fische von dir und Faros beschworen worden?"
  },
  AvgDialog_117504_Content_70 = {
    Text = "Zahlreiche silberne Fäden umschlingen die Blutperlen, die sich aus den Handgelenken der hundert Gläubigen verbreiten und entlang einer ungreifbaren Spur zu einem einzigen Punkt hinziehen."
  },
  AvgDialog_117504_Content_71 = {
    Text = "<Change>Opfer mit dem Geist aller Dinge."
  },
  AvgDialog_117504_Content_72 = {
    Text = "Die tintenschwarzen Bluttröpfchen drehen sich, verfestigen sich und springen in eine milchweiße Elfenbeinstatue, durchdringen ein feines Netzwerk aus Blutadern."
  },
  AvgDialog_117504_Content_73 = {
    Text = "Die Elfenbeinstatue schien mit Leben erfüllt zu sein, sie flog über das Stahlmonster und stürzte direkt in den stillen Ozean."
  },
  AvgDialog_117504_Content_74 = {
    Text = "<Change>Bitte zerreißen Sie die trügerische Tiefe des Meeres und führen Sie uns direkt in Ihr Reich."
  },
  AvgDialog_117504_Content_75 = {
    Text = "Plötzlich erbebte der Himmel und das Meer, die gesamte Weite des Ozeans tobte, und ein Klagelied wie das eines gebärenden Ungeheuers ertönte."
  },
  AvgDialog_117504_Content_76 = {
    Text = "Die Wellen tanzten wild, weinten und formten sich zu einer zitternden Wand."
  },
  AvgDialog_117504_Content_77 = {
    Text = "Herrin Göttliche Mutter, die Menge an Seelen scheint etwas unzureichend zu sein..."
  },
  AvgDialog_117504_Content_78 = {
    Text = "Kein Problem."
  },
  AvgDialog_117504_Content_79 = {
    Text = "Das Mädchen hebt den Schleier und schaut auf die knienden Wesen zurück."
  },
  AvgDialog_117504_Content_8 = {
    Text = "Miryam schien gerade erst deine Anwesenheit wahrzunehmen, neigte leicht den Kopf und schaute in deine Richtung."
  },
  AvgDialog_117504_Content_80 = {
    Text = "Bitte, Göttliche Mutter, gewähre heiliges Blut!"
  },
  AvgDialog_117504_Content_81 = {
    Text = "<Big:<Shake:Bitte, Göttliche Mutter, gewähre uns heiliges Blut!>>"
  },
  AvgDialog_117504_Content_82 = {
    Text = "Die Welle der Stimmen erhob sich immer mehr, und inmitten des lauten Rufs streckte das Mädchen ihre Fingerspitzen zu ihrer Brust aus."
  },
  AvgDialog_117504_Content_83 = {
    Text = "Ihre Fingernägel sind scharf wie Klingen und reißen entlang der lila Narben die Brust auf, um das einzige verbleibende Herz zu zeigen."
  },
  AvgDialog_117504_Content_84 = {
    Text = "<Shake:Ergreift sie, jagt sie! Wenn ich das Blut und Fleisch der Göttlichen Mutter opfere, wirst du für mich die umgekehrte Treppe zum Göttlichen Reich schmieden!>"
  },
  AvgDialog_117504_Content_85 = {
    Text = "Die Gläubigen strömten herbei. Ihre Flossen und seltsamen Klammern streckten sich ungeduldig nach dem dünnen Körper der Göttlichen Mutter aus."
  },
  AvgDialog_117504_Content_86 = {
    Text = "Sie saugen ihr Blut und nagen an ihrem Fleisch. Rote Fäden proliferieren heftig und drängen sich hastig in das Aequor."
  },
  AvgDialog_117504_Content_87 = {
    Text = "Blutrot proliferiert wahnsinnig um den Mittelpunkt der Statue, während die Wellen sich in Millionen von Blutkorallen verfestigen."
  },
  AvgDialog_117504_Content_88 = {
    Text = "Die Zeremonie ist beendet! Zurücktreten!"
  },
  AvgDialog_117504_Content_89 = {
    Text = "Sie trat über die Leichname der Seefahrer, die sich vor dem Mädchen drängten, und hüllte Murphys Körper in einen schwarzen Umhang. Unter dem Umhang floss der Blutstrom weiterhin leise und unaufhörlich."
  },
  AvgDialog_117504_Content_9 = {
    Text = "Solltest du nicht im Gemach der Göttlichen Mutter sein? Warum..."
  },
  AvgDialog_117504_Content_90 = {
    Text = "Lemuria! Lemuria! Das Blut der Göttlichen Mutter hat den Weg nach Lemuria bestimmt!"
  },
  AvgDialog_117504_Content_91 = {
    Text = "Unter den vielen Blutlinien erblickst du einen ungewöhnlichen Silberfaden. Dieser Silberfaden entspringt deiner Brust und streckt sich nach oben, immer weiter..."
  },
  AvgDialog_117504_Content_92 = {
    Text = "Bis jenseits des Himmels, an einem unbekannten Ort."
  },
  AvgDialog_117504_Content_93 = {
    Text = "Das Mädchen schien sich auch der Existenz des silbernen Fadens bewusst zu werden. Sie blickte nach oben, ihre Pupillen zitterten plötzlich, und ihr erschrockener Blick durchbohrte deinen Standort."
  },
  AvgDialog_117504_Content_94 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_117504_Content_95 = {
    Text = "Im Moment des Blickes, der sich begegnet, zieht eine unsichtbare und gewaltige Kraft an dir, ungeachtet deines gesamten Widerstands, und lässt dich direkt in eine furchtbare Illusion wie einen Alptraum fallen."
  },
  AvgDialog_117504_Content_96 = {
    Text = "......das ist die unreine schwarze Sonne, die du gesehen hast."
  },
  AvgDialog_117504_Content_97 = {
    Text = "Handtrommelgeräusch?"
  },
  AvgDialog_117504_Content_98 = {
    Text = "Nein, das ist der Herzschlag."
  },
  AvgDialog_117504_Content_99 = {
    Text = "Lange, atemlose, dem Tod nahestehende, längst vergangene, aber nach dem langen Traum wieder auferstandene..."
  },
  AvgDialog_118123_Content_1 = {
    Text = "Windradritter"
  },
  AvgDialog_118123_Content_10 = {
    Text = "Gerade mit solch einer Sehnsucht wurde diesem Kerl ein Nachsicht gewährt."
  },
  AvgDialog_118123_Content_11 = {
    Text = "(Das Ergebnis ist trotzdem, völlig nutzlos...)"
  },
  AvgDialog_118123_Content_12 = {
    Text = "Tatsächlich... muss ich dir wohl helfen."
  },
  AvgDialog_118123_Content_13 = {
    Text = "Renn wie eine kopflose Fliege! Wohin willst du eigentlich!"
  },
  AvgDialog_118123_Content_14 = {
    Text = "Wie Wilhelm, der Seniorstudent, gerade gesagt hat, geht es vom Deck zu den Rettungsbooten im Rumpf!"
  },
  AvgDialog_118123_Content_15 = {
    Text = "Das Sichtfeld auf dem Deck ist so weit, ich sehe, du willst dich wohl den Fischmenschen zum Fraß vorwerfen!"
  },
  AvgDialog_118123_Content_16 = {
    Text = "In der vorvorherigen Wiedergeburt warst du es, der die Fischmenschen gefüttert hat!"
  },
  AvgDialog_118123_Content_17 = {
    Text = "Verdammtes, sprich nicht mit der Göttlichen Mutter! Lauf jetzt sofort zum Cockpit, dort gibt es eine Struktur, die zum Rettungsboot führt!"
  },
  AvgDialog_118123_Content_18 = {
    Text = "Lass mich auch runter, meine Haare sehen schon aus wie ein Vogelnest!"
  },
  AvgDialog_118123_Content_19 = {
    Text = "Du bist meine wichtige Geisel, jetzt ist nicht die Zeit, um über das Image nachzudenken! Bitte halte noch ein wenig durch, Göttliche Mutter!"
  },
  AvgDialog_118123_Content_2 = {
    Text = "Du springst hinunter und spürst, wie der schneidende Wind über deine Wangen peitscht, dann zieht sich das Seil um deine Taille plötzlich straff und stoppt deinen Fall."
  },
  AvgDialog_118123_Content_20 = {
    Text = "<Shake:Sei vorsichtig, die Verfolger von Miryam kommen näher!>"
  },
  AvgDialog_118123_Content_3 = {
    Text = "Hey! Was machst du eigentlich?!"
  },
  AvgDialog_118123_Content_4 = {
    Text = "Du ziehst ein kleines Messer, durchtrennst das Seil und springst dann zu Boden."
  },
  AvgDialog_118123_Content_5 = {
    Text = "Willst du einfach so mit mir auf dem Rücken weglaufen? Sie werden gleich hinter uns her sein, oder!"
  },
  AvgDialog_118123_Content_6 = {
    Text = "Ach, das ist ja zum Verzweifeln dumm!"
  },
  AvgDialog_118123_Content_7 = {
    Text = "Was habe ich mir nur gedacht, dass ich diesem Dummkopf ein wenig Hoffnung geschenkt habe."
  },
  AvgDialog_118123_Content_8 = {
    Text = "Diese Flucht von {Male=er,Female=sie} ist waghalsiger als jede, die ich damals unternommen habe."
  },
  AvgDialog_118123_Content_9 = {
    Text = "Wenn es diese Welt auch <Yellow:%player%> gibt, wird sich dann der Verlauf der Geschichte anders gestalten?"
  },
  AvgDialog_118124_Content_1 = {
    Text = "Du zogst den Vorhang herunter und bandst die fauchende Murphy fest."
  },
  AvgDialog_118124_Content_10 = {
    Text = "Wenn du uns drei genau beobachtest, wirst du wissen, dass die Prinzessin jemand anderen hat."
  },
  AvgDialog_118124_Content_11 = {
    Text = "Wilhelm band die Seile fest um eure Taillen, dich und Murphy."
  },
  AvgDialog_118124_Content_12 = {
    Text = "Achte darauf, die Prinzessin gut zu betreuen und sie nicht zu verlieren! Im unteren Schiffsrumpf gibt es Rettungsboote, wir treffen uns dort!"
  },
  AvgDialog_118124_Content_13 = {
    Text = "Drei, zwei, eins, spring!"
  },
  AvgDialog_118124_Content_2 = {
    Text = "Fertig! Beweg dich nicht, sei vorsichtig, dass du dich nicht verletzt!"
  },
  AvgDialog_118124_Content_3 = {
    Text = "Zum Verzweifeln! Wenn du so weitermachst, werde ich dich beißen!"
  },
  AvgDialog_118124_Content_4 = {
    Text = "So bist du ohne Allüren viel mehr wie du selbst, Murphy."
  },
  AvgDialog_118124_Content_5 = {
    Text = "Weniger Reden! Die Schuld der Demütigung der Göttlichen Mutter werde ich dir anrechnen, sobald ich meine Freiheit wiedererlangt habe!"
  },
  AvgDialog_118124_Content_6 = {
    Text = "Aber werden die Schritte draußen nicht immer dichter?"
  },
  AvgDialog_118124_Content_7 = {
    Text = "Das Plätschern der Schritte vereint sich zu einem Meer, während immer wieder kleine, stämmige Körper gegen die Wohnzimmertür schlagen und dumpfe Klopfgeräusche erzeugen."
  },
  AvgDialog_118124_Content_8 = {
    Text = "Komm, wir brechen das Fenster auf und gehen hinaus! Nimm das hier und spring auf das Deck!"
  },
  AvgDialog_118124_Content_9 = {
    Text = "Ein Bettlaken zum Knoten benutzen...? Wilhelm, du siehst aus wie die entlaufene Prinzessin aus einem Märchen."
  },
  AvgDialog_118125_Content_1 = {
    Text = "Turmprinzessin"
  },
  AvgDialog_118125_Content_10 = {
    Text = "Du beobachtest genau, dass es insgesamt zwei gebrochene Fäden gibt, und auf der Spule sind noch vier Runden Faden gewickelt."
  },
  AvgDialog_118125_Content_11 = {
    Text = "Ich habe noch vier Versuche... oder?"
  },
  AvgDialog_118125_Content_12 = {
    Text = "Sie nickte und schüttelte den Kopf."
  },
  AvgDialog_118125_Content_13 = {
    Text = "Ich habe deine Stimme gehört, du kannst doch sprechen... dir ist nicht erlaubt, etwas zu sagen...?"
  },
  AvgDialog_118125_Content_14 = {
    Text = "Sie öffnete den Mund, aber es kam nur ewige Stille heraus."
  },
  AvgDialog_118125_Content_15 = {
    Text = "Sie blickte zurück in den hohen Himmel der Ferne, und du folgtest ihrem Blick und schaust in die Ferne."
  },
  AvgDialog_118125_Content_16 = {
    Text = "Dort gibt es nur eine in Wasser getauchte schwarze Sonne."
  },
  AvgDialog_118125_Content_17 = {
    Text = "Hust, hust...!"
  },
  AvgDialog_118125_Content_18 = {
    Text = "Du wachst plötzlich aus dem Bett auf und hustest laut, gequält von den Schmerzen des Ertrinkens."
  },
  AvgDialog_118125_Content_19 = {
    Text = "Noch einmal... der Kreislauf..."
  },
  AvgDialog_118125_Content_2 = {
    Text = "Der Seewind ist salzig und fangfrisch, und wenn er in den Mund weht, hinterlässt er einen anhaltenden bitteren Geschmack."
  },
  AvgDialog_118125_Content_20 = {
    Text = "Die Menschen des Meeresreichs empfinden entweder Überraschung oder Gleichgültigkeit, echte oder falsche Sorge, doch all dies ist durch dicke Barrieren von dir getrennt. In deinem Kopf schwebt nur Murphys Gesicht, bevor der letzte Kreislauf endete."
  },
  AvgDialog_118125_Content_21 = {
    Text = "Rette mich...... wenn du es bist, kannst du es bestimmt......"
  },
  AvgDialog_118125_Content_22 = {
    Text = "Dann verschlang die Dunkelheit alles und verwandelte sich in den unvergänglichen Zweifel in deinem Geist."
  },
  AvgDialog_118125_Content_23 = {
    Text = "Egal wie, du musst zuerst mit Wilhelm zusammentreffen."
  },
  AvgDialog_118125_Content_24 = {
    Text = "Goliath und Miryam gingen einen leeren Korridor entlang, und die Schritte hallten wider."
  },
  AvgDialog_118125_Content_25 = {
    Text = "Vorbei an barocken Wandmalereien der Madonna, kleinen Laternen, die die vergoldeten Wandleuchten ersetzen, und ruhigen, menschenleeren Schlafzimmern."
  },
  AvgDialog_118125_Content_26 = {
    Text = "Sie hatten keinen Kontakt, sprachen nicht, und die angespannte Atmosphäre schwebte zwischen den beiden."
  },
  AvgDialog_118125_Content_27 = {
    Text = "Miryam hielt an der Tür zum Kapitänszimmer an, drehte sich um und öffnete die Tür."
  },
  AvgDialog_118125_Content_28 = {
    Text = "Goliath holte einige Schritte auf und blieb hinter ihr stehen."
  },
  AvgDialog_118125_Content_29 = {
    Text = "Hey, Miryam. Das kleine Mädchen täuscht dich."
  },
  AvgDialog_118125_Content_3 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_118125_Content_30 = {
    Text = "Was gibt es? Zu dieser Zeit solltest du doch im Steuerhaus Wache halten, oder?"
  },
  AvgDialog_118125_Content_31 = {
    Text = "Sollte die Frau, die das Kraftwerk aufrechterhält, auch nur den geringsten Unterschied haben, würde ich nur dich fragen."
  },
  AvgDialog_118125_Content_32 = {
    Text = "Reden wir nicht über den ganzen Unsinn, Caecus sieht zu, und diese dummen Matrosen können auch keine Wellen schlagen."
  },
  AvgDialog_118125_Content_33 = {
    Text = "Der einzige Knackpunkt ist, dass das kleine Mädchen dich anlügt."
  },
  AvgDialog_118125_Content_34 = {
    Text = "Philistinen, die über die Göttliche Mutter sprechen, sind nicht dein übliches Verhalten."
  },
  AvgDialog_118125_Content_35 = {
    Text = "Weißt du, dass dieses Schiff niemals zu diesem Lemuria gelangen wird?"
  },
  AvgDialog_118125_Content_36 = {
    Text = "...Goliath."
  },
  AvgDialog_118125_Content_37 = {
    Text = "Du bist nur mein aufgezogener Jagdhund, solange ich dir nicht befehle, die riesige Klinge gegen einen Feind zu schwingen, gibt es hier keinen Raum für deine großen Worte."
  },
  AvgDialog_118125_Content_38 = {
    Text = "Bevor wir anlegen, musst du nur dafür sorgen, dass die Seeleute an Bord gut verwaltet werden und sie nicht die Ruhe der Göttlichen Mutter stören."
  },
  AvgDialog_118125_Content_39 = {
    Text = "Wenn es etwas gibt, das du unbedingt wissen musst..."
  },
  AvgDialog_118125_Content_4 = {
    Text = "Die Frau mit dem Spinnrad sieht dich traurig an."
  },
  AvgDialog_118125_Content_40 = {
    Text = "<Shake:Wenn dieses Schiff auch nur die geringste Chance hat, Lemuria zu erreichen, dann ist das allein dem Glanz der Göttlichen Mutter zu verdanken.>"
  },
  AvgDialog_118125_Content_41 = {
    Text = "Tsk, die störrische, stinkende Frau..."
  },
  AvgDialog_118125_Content_42 = {
    Text = "Gute und schlechte Worte habe ich bereits gesagt."
  },
  AvgDialog_118125_Content_43 = {
    Text = "Für die nächsten Dinge kann man mir dann keinen Vorwurf machen."
  },
  AvgDialog_118125_Content_44 = {
    Text = "Caecus, führe den Plan aus."
  },
  AvgDialog_118125_Content_45 = {Text = "Hier!"},
  AvgDialog_118125_Content_46 = {
    Text = "Übernehmt die Hauptkontrolle des Schiffs, bevor das Ritual abgeschlossen ist."
  },
  AvgDialog_118125_Content_47 = {
    Text = "Du wanderst über das Deck und suchst verzweifelt nach Hinweisen, die auf Wilhelms Versteck hindeuten könnten."
  },
  AvgDialog_118125_Content_48 = {
    Text = "Wenn ich mich nicht irre, dann ist es an dieser Position..."
  },
  AvgDialog_118125_Content_49 = {
    Text = "Du hebst die Falltür entlang der Ritzen auf dem Deck und springst dann, nachdem du die Zähne zusammengebissen hast, hinunter."
  },
  AvgDialog_118125_Content_5 = {
    Text = "Hast du etwas, das du mir sagen möchtest?"
  },
  AvgDialog_118125_Content_50 = {
    Text = "<Shake:Pfui, pfui...>"
  },
  AvgDialog_118125_Content_51 = {
    Text = "Du hustest das Schilf aus, das du dir in den Mund gesteckt hast, und bereust, dass du die Methode gewählt hast, direkt nach unten zu fallen."
  },
  AvgDialog_118125_Content_52 = {
    Text = "Wilhelm, der Seniorstudent, versteck dich nicht, ich weiß, dass du hier bist!"
  },
  AvgDialog_118125_Content_53 = {
    Text = "Nach einer Weile waren einige Raschelgeräusche hinter dem Schilfhalm-Ballen zu hören."
  },
  AvgDialog_118125_Content_54 = {
    Text = "Das ist nicht vernünftig."
  },
  AvgDialog_118125_Content_55 = {
    Text = "...Wenn du so präzise die Fähigkeit hättest, mich zu orten, hättest du mich bereits auf den Straßen Londons eingeholt."
  },
  AvgDialog_118125_Content_56 = {
    Text = "Erzähl mal... Was hast du alles erlebt, seit du auf dieses Schiff gestiegen bist?"
  },
  AvgDialog_118125_Content_57 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_118125_Content_58 = {
    Text = "Du hast die Geschichte der Wiedergeburt in wenigen Worten zusammengefasst."
  },
  AvgDialog_118125_Content_59 = {
    Text = "Es tut mir leid, aber nach Beginn der Zeremonie wird es zu spät sein.\nWilhelm, der Seniorstudent, wir müssen die Falle im Wohnraum von Murphy vorher aufheben."
  },
  AvgDialog_118125_Content_6 = {
    Text = "Die Frau nickte."
  },
  AvgDialog_118125_Content_60 = {
    Text = "Geh, auf diesem Weg, hier gibt es keine Augenlinien."
  },
  AvgDialog_118125_Content_61 = {
    Text = "Du meinst also, dass Goliath eine Rebellion plant und ich mich mit dir verstecken muss."
  },
  AvgDialog_118125_Content_62 = {
    Text = "Und das alles weißt du, weil du die Rückverfolgung der Zeit erlebt hast?"
  },
  AvgDialog_118125_Content_63 = {
    Text = "Es ist zu absurd, zu lächerlich... Es sei denn, mein Verstand ist außer Kontrolle...<Shake:Ugh...>"
  },
  AvgDialog_118125_Content_64 = {
    Text = "Entschuldigung, hier gibt es keinen Platz mehr für deine Launen."
  },
  AvgDialog_118125_Content_65 = {
    Text = "Senior William!"
  },
  AvgDialog_118125_Content_66 = {
    Text = "Mach dir keine Sorgen, ich habe mir gedacht, dass es nicht so einfach ist, und habe die Geräusche außerhalb des Wohnzimmers abgeschottet."
  },
  AvgDialog_118125_Content_67 = {
    Text = "Bring sie zuerst weg!"
  },
  AvgDialog_118125_Content_7 = {
    Text = "Hat es mit der Wiedergeburt zu tun?"
  },
  AvgDialog_118125_Content_8 = {
    Text = "Die Frau schüttelte den Kopf, ihre Fingerspitzen strichen über den Faden des Spinnrades, drehten sich im Uhrzeigersinn eine Runde und blieben am Ausgangspunkt stehen."
  },
  AvgDialog_118125_Content_9 = {
    Text = "Mit der Drehung des Spinnrades zerfällt der ursprüngliche Faden."
  },
  AvgDialog_118699_Content_1 = {
    Text = "Unsere Wünsche"
  },
  AvgDialog_118699_Content_10 = {
    Text = "Mehr starke geistige Kraft? ... Ich verstehe, ich werde allen Erweckern eine Benachrichtigung senden."
  },
  AvgDialog_118699_Content_11 = {
    Text = "Auf dem Spielplatz in der Dämmerung beendete Ogier wie gewohnt sein tägliches Training, das nicht weniger war als zuvor."
  },
  AvgDialog_118699_Content_12 = {
    Text = "Heute wurde wieder ein wenig der vergangene Rekord gebrochen..."
  },
  AvgDialog_118699_Content_13 = {
    Text = "Er wischte den schweiß ab, der ihm herunterlief, und stützte die schwere Lanze auf den Boden. Ogier drehte sich um und sah, dass die Gestalt, die ihm zuvor lächelnd Mut zugesprochen hatte, nicht mehr da war. Nur sein einsames Schatten zog sich lang über den Boden."
  },
  AvgDialog_118699_Content_14 = {
    Text = "Lotans Stichschwert warf im Schatten zwei konventionelle Waffen der Ermittler weg und beendete einen weiteren Kampf, der nur eine Minute dauerte."
  },
  AvgDialog_118699_Content_15 = {
    Text = "Was ist mit den neuen Studenten los? Ihre Qualitäten sind wirklich zu schlecht, komm schon!"
  },
  AvgDialog_118699_Content_16 = {
    Text = "Bevor sie das Schwert ergreifen konnte, um weiterhin die Leute zu schikanieren, hatten die beiden keuchenden Neugeborenen vor ihr bereits begonnen, ununterbrochen mit gefalteten Händen um Gnade zu bitten."
  },
  AvgDialog_118699_Content_17 = {
    Text = "Tsk, langweilig..."
  },
  AvgDialog_118699_Content_18 = {
    Text = "Als sie an jemanden dachte, der ihr spannende Kämpfe bieten konnte, seufzte Lotan, blickte auf die untergehende Sonne und wandte sich gelangweilt um."
  },
  AvgDialog_118699_Content_19 = {
    Text = "Aigis schnitt ein Stück des restlichen Garns ab, entfaltete den neu gestrickten Pullover sorgfältig und hängte ihn dann auf Zehenspitzen in den Schrank, der mit Stoffen gefüllt war."
  },
  AvgDialog_118699_Content_2 = {
    Text = [[
Kardas-Welt
Jetzt]]
  },
  AvgDialog_118699_Content_20 = {
    Text = "Aigis wird immer mehr Muster stricken, wie Zopfmuster, Rautenmuster, Wellenmuster, kleine Blumen und Tiermuster."
  },
  AvgDialog_118699_Content_21 = {
    Text = "Großer{Male=Herr Schutzherr,Female=Frau Schutzherrin}, was würdest du mögen...?"
  },
  AvgDialog_118699_Content_22 = {
    Text = "Die flinke graue Maus kroch durch die Türöffnung und legte treu einen glänzenden Ring in die Hände ihres Partners."
  },
  AvgDialog_118699_Content_23 = {
    Text = "Na gut, gut gemacht, Braun."
  },
  AvgDialog_118699_Content_24 = {
    Text = "Die kleine Maus sah zu, wie ihr Partner gelangweilt gähnte und den Ring achtlos in die offene Holzkiste warf, die bereits mit durcheinanderliegenden “Sammlerstücken“ überquoll."
  },
  AvgDialog_118699_Content_25 = {Text = "Quiek..."},
  AvgDialog_118699_Content_26 = {
    Text = "Die Person ist schon lange nicht mehr ins Dormitory gekommen, um ihre Schatzkiste zu durchsuchen und hat den Boss gezwungen, die Gegenstände einzeln zurückzugeben. Aber warum ist der Boss trotzdem niedergeschlagen?"
  },
  AvgDialog_118699_Content_27 = {
    Text = "Das brave Mädchen saß ordentlich am Schreibtisch und schlug ein weiteres Geschichtsbuch auf."
  },
  AvgDialog_118699_Content_28 = {
    Text = "In der Ecke des Tisches hat sich ein hoher Stapel gelesener Kinderbücher angesammelt, und im Heft des Mädchens sind die Ideen für Geschichten, die ihr in den Sinn kamen, notiert."
  },
  AvgDialog_118699_Content_29 = {
    Text = "Als sie an die Begeisterung dachte, erschien ein sanftes Lächeln auf dem ruhigen Gesicht des Mädchens, und ihre Füße begannen leicht unter dem Tisch zu wippen."
  },
  AvgDialog_118699_Content_3 = {
    Text = "Der noch unförmige, verschwommene Tunnel wurde von der plötzlich auftauchenden Horror-Korrosion zerschlagen. Ramonas Körper stöhnte leise, als ihr Bewusstsein unter dem dringenden Rückruf des Geräts zurückgezogen wurde."
  },
  AvgDialog_118699_Content_30 = {
    Text = "Diese Geschichte werden alle sicher mögen..."
  },
  AvgDialog_118699_Content_31 = {
    Text = "Der Bleistift raschelte und hielt die kindlichen Fantasien fest. Doch bald legte das Mädchen den Stift nieder und starrte gedankenverloren aus dem Fenster."
  },
  AvgDialog_118699_Content_32 = {
    Text = "Aber, wann kann Großer{Male=Herr Schutzherr,Female=Frau Schutzherrin} Lily wieder mitnehmen, um Filme zu drehen?"
  },
  AvgDialog_118699_Content_33 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_118699_Content_34 = {
    Text = "Der Krieger kippt den Weinsack und gießt ihn auf den Boden vor dem Grabstein."
  },
  AvgDialog_118699_Content_35 = {
    Text = "Nachdem der Krieger den verbleibenden halben Krug Wein in einem Zug ausgetrunken hatte, war er still gegangen, nur ein Lorbeerkranz hing still auf dem Grabstein."
  },
  AvgDialog_118699_Content_36 = {
    Text = "Auf dem prächtigen Samttischdecken ist der Nachmittagstee der Damen wie immer reichhaltig."
  },
  AvgDialog_118699_Content_37 = {
    Text = "Das Besteck und die Teller erzeugen ein gedämpftes Klirren, während der köstliche Sahnekuchen in den Mund gelangt."
  },
  AvgDialog_118699_Content_38 = {
    Text = "In übertriebener Stille genoss die Dame still den Anblick des leeren Stuhls gegenüber, vor dem das spezielle Geschirr dieser Person lag."
  },
  AvgDialog_118699_Content_39 = {
    Text = "Es ist wirklich unprofessionell, den Meister hier allein zu lassen..."
  },
  AvgDialog_118699_Content_4 = {
    Text = "Ramona! Pollux! Wie geht es euch?"
  },
  AvgDialog_118699_Content_40 = {
    Text = "In einem absichtlich freigehaltenen leeren Schlafsaal scheint die ordentlich neue Einrichtung unbewohnt zu sein, nur vor dem Fenster steht ein Topf mit einem gerade keimenden Setzling."
  },
  AvgDialog_118699_Content_41 = {
    Text = "In seltenen Momenten kann man hinter dem Fenster eine Frau mit honigfarbener Haut sehen, die am Fensterbrett liegt und den kleinen Baum zart umarmt."
  },
  AvgDialog_118699_Content_42 = {
    Text = "Selbst jetzt, wo die Vereinsaktivitäten allmählich wieder belebt und aktiv sind, wagt es immer noch niemand, diesen Musikraum, der dem Meister gehört, leicht zu stören."
  },
  AvgDialog_118699_Content_43 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_118699_Content_44 = {
    Text = "Die Vorhänge werden sanft vom Nachtwind gehoben, Hameln steht vor dem Klavier und blickt in Richtung des Glockenturms."
  },
  AvgDialog_118699_Content_45 = {
    Text = "Vor den einst gemeinsam gespielten Tasten ist niemand mehr, nur die täglich wiederholte Flötenmelodie schwebt still im Mondlicht, ungehört."
  },
  AvgDialog_118699_Content_46 = {
    Text = "In der Tiefe des schwarzen Pools hat der ewige einsame Gefangene hinter der Tür in diesem Moment einen schlafenden Gefährten."
  },
  AvgDialog_118699_Content_47 = {
    Text = "Die mitfühlenden Augen öffneten sich still und betrachteten die Hülle, in der die Seele in der Ferne umherirrte."
  },
  AvgDialog_118699_Content_48 = {
    Text = "Im Labor der Forschungsabteilung trainiert Ramona weiterhin Tag und Nacht ihre geistigen Fähigkeiten, der Schweiß hat ihre Trainingskleidung bereits durchnässt."
  },
  AvgDialog_118699_Content_49 = {
    Text = "Doll beobachtete die kämpferische Gestalt, trank schweigend eine weitere Tasse starken Kaffee, blätterte die nächste Seite des Versuchsberichts um und setzte die Anpassung der Gerätedaten fort."
  },
  AvgDialog_118699_Content_5 = {
    Text = "Hust... Mir geht's gut, es wurde rechtzeitig unterbrochen."
  },
  AvgDialog_118699_Content_50 = {
    Text = "<Small:Ah, Winkles Kaffee ist wirklich ein wenig zu stark...>"
  },
  AvgDialog_118699_Content_51 = {
    Text = "Auf dem Kommunikationsgerät, das sie gerade freigegeben hat, blinkt eine Benachrichtigung, die an alle Erwecker gesendet wurde."
  },
  AvgDialog_118699_Content_52 = {
    Text = "Alle Erwecker auf dem Campus schauten gleichzeitig auf den plötzlich ertönenden Kommunikator, auf den Namen, auf den sie so lange gewartet hatten."
  },
  AvgDialog_118699_Content_53 = {
    Text = "An alle Erwecker: \n\nIn der nicht allzu fernen Vergangenheit kämpften wir weiterhin gegen die schwarze Katastrophe, die alles verschlingt. Bis heute sind auf dem Grabstein des Keygrave unzählige verschwommene Namen eingraviert, sowie der Name des Schutzherrn, der uns den endgültigen Frieden brachte. \nDas war unser Freund, Kamerad, der Schüler, der am häufigsten in Misaq geschwänzt hat, viele besondere Freunde, unser einzigartiger Führer und der Held, der uns alle gerettet hat."
  },
  AvgDialog_118699_Content_54 = {
    Text = "Nach dem Verlust von {Male=ihm,Female=ihre} hat Misaq eine intensive Farbe verloren. Während wir alle traurig sind, hat die Forschungsabteilung die schwache Hoffnung nicht aufgegeben und sucht weiterhin nach den Spuren des Bewusstseins des Schutzherrn. \n Ursprünglich wollte ich euch keine unbekannte Hoffnung bringen, bevor wir den Erfolg bestätigt haben, um das leidige Warten nicht unnötig zu verlängern. Aber jetzt haben wir die Methode verifiziert, um <Yellow:%player%> zu finden, und werden bald den finalen Versuch starten."
  },
  AvgDialog_118699_Content_55 = {
    Text = "Dieser Kampf zur Rückkehr von {Male=ihm,Female=ihr} braucht euch, braucht uns alle, um unsere Sehnsucht nach {Male=ihm,Female=ihr} in Wegweiser zu verwandeln, die uns zu {Male=ihm,Female=ihr} führen. \n Ich lade euch im Namen von Misaq herzlich ein, gemeinsam zum schwarzen Pfütze zu kommen, so wie wir es in der letzten Schlacht getan haben, um erneut Schulter an Schulter für <Yellow:%player%> zu kämpfen. \n\n Euer Kamerad Doll"
  },
  AvgDialog_118699_Content_56 = {
    Text = [[
Kardas-Welt
 Tag der Vereinbarung]]
  },
  AvgDialog_118699_Content_57 = {
    Text = "Vor dem stillen schwarzen Teich unter dem Glockenturm stehen viele ruhige Menschen."
  },
  AvgDialog_118699_Content_58 = {
    Text = "Nachdem Doll das Prinzip des Dimensionen-Wechsels erklärt hatte, standen die ursprünglich lautstark verlangenden Erwecker still neben dem Resonanzgerät."
  },
  AvgDialog_118699_Content_59 = {
    Text = "Aufgrund der geistigen Eigenschaften des Dimensionsraums zieht das gleichzeitige Auftreten von mehr Geistern nur mehr Aufmerksamkeit höherer Wesen auf sich, was die Hüter auf der anderen Seite nur noch mehr erschwert."
  },
  AvgDialog_118699_Content_6 = {
    Text = "Warum... Ich habe doch gerade eben {Male=his,Female=her} Stimme gehört. Warum kann ich {Male=him,Female=her} nicht finden?"
  },
  AvgDialog_118699_Content_60 = {
    Text = "Vor der Menge hielt Ramona einen Strauß verwelkter Rosen und starrte still auf die schwarze Pfütze, während sie mit der anderen Hand den Silberschlüssel mit der Nummer 0617 fest umschloss."
  },
  AvgDialog_118699_Content_61 = {
    Text = "Das Gerät ist bereit zum Start, konzentriert euch bitte."
  },
  AvgDialog_118699_Content_62 = {
    Text = "Die Scheren drücken den Knopf, und eine Welle geistiger Energie breitet sich wie Wasserwellen aus, wobei die Geister aller zu einem Faden gebündelt werden und ein riesiges Netz der Verbindung weben."
  },
  AvgDialog_118699_Content_63 = {
    Text = "Ramona öffnete feierlich ihre Handfläche, der Silberschlüssel erhob sich langsam in einer seltsamen Anziehungskraft und schwebte in der Mitte eines unsichtbaren Netzwerks, während er mit atemähnlichem Licht blitzte."
  },
  AvgDialog_118699_Content_64 = {
    Text = "Alle schauten auf den Schlüssel und beteten still in ihrem Herzen."
  },
  AvgDialog_118699_Content_65 = {
    Text = "Diese Schule, die Menschen hier, sie brauchen dich. Egal ob in einem Jahr, zwei Jahren oder zehn Jahren... solange die Forschung sinnvoll ist, werden wir dich auf jeden Fall zurückholen."
  },
  AvgDialog_118699_Content_66 = {
    Text = "Mein Herr, ich kann jetzt 40 Sekunden ohne Verbindung durchhalten. Ich kann dich jetzt besser schützen. Ich möchte dir wirklich meine Trainingsergebnisse zeigen..."
  },
  AvgDialog_118699_Content_67 = {
    Text = "Es gibt keinen Neugeborenen in Misaq, der so widerstandsfähig ist wie du. Wann darf ich wieder einen Kampf unter deinem Kommando erleben?"
  },
  AvgDialog_118699_Content_68 = {
    Text = "Aigis hat brav gehört und gut gegessen. Ich habe für große {Male=Herr Schutzherr,Female=Frau Schutzherrin} viele, viele Schals, Mützen, Handschuhe und verschiedene Pullover gestrickt. Wird große {Male=Herr Schutzherr,Female=Frau Schutzherrin} das mögen?"
  },
  AvgDialog_118699_Content_69 = {
    Text = "West-Whelp, du hast das Überleben im Ostviertel noch nicht vollständig gelernt, für das ich dir die Gebühr bereits abgenommen habe. Komm schnell zurück, lass nicht zu, dass der Ruf dieses Diebs leidet..."
  },
  AvgDialog_118699_Content_7 = {
    Text = "In der Tat kann das “Heilige Herz“ nur die ungefähre Richtung von {Male=seiner,Female= ihrer} wahrnehmen, kann jedoch keine genaueren Koordinaten finden."
  },
  AvgDialog_118699_Content_70 = {
    Text = "Geheimnisträger {Male=Herr,Female=Frau}, ich glaube, dass gute Menschen immer vom Glück beschützt werden. Jemand wie Sie wird bestimmt ein glückliches Ende haben."
  },
  AvgDialog_118699_Content_71 = {
    Text = "Großer{Male=Herr Schutzherr,Female=Frau Schutzherrin}, Lily kann schon viele Geschichtenbücher lesen. Wenn du zurückkommst, können wir einen Film über Großer{Male=Herr Schutzherr,Female=Frau Schutzherrin} und Lily drehen?"
  },
  AvgDialog_118699_Content_72 = {
    Text = "Der siegreiche Krieger sollte in seine {Male=Heimat,Female=Heimat} zurückkehren."
  },
  AvgDialog_118699_Content_73 = {
    Text = "Komm schnell zurück, du dummer Diener! Du schuldest mir so viele Nachmittags-Tees, die musst du mir alle gut nachholen!"
  },
  AvgDialog_118699_Content_74 = {
    Text = "Du hast mich einmal gefragt, was mein Wunsch ist... Jetzt habe ich endlich meinen eigenen Wunsch, nämlich, dass du sicher zurückkommst."
  },
  AvgDialog_118699_Content_75 = {
    Text = "Der unzuverlässige kleine Setzling, in der neuen Welt, die du mir versprochen hast, darfst du nicht fehlen..."
  },
  AvgDialog_118699_Content_76 = {
    Text = "Unser Stamm wird kein einzelnes Mitglied im Stich lassen."
  },
  AvgDialog_118699_Content_77 = {
    Text = "Mein Flötenklang wird immer auf Sie warten."
  },
  AvgDialog_118699_Content_78 = {
    Text = "Alle Erwecker murmeln den vertrauten Namen, während Wellen von Geisterkraft wie Glühwürmchen in den schwebenden Silberschlüssel strömen, und das Zentrum des Schlüssels beginnt allmählich, wie Sterne zu strahlen."
  },
  AvgDialog_118699_Content_79 = {
    Text = "Pollux und Castor sahen sich einen Moment lang an und nickten einander zu. Castors Körper verwandelte sich in einen Lichtstrahl und verschmolz mit Pollux' Brust."
  },
  AvgDialog_118699_Content_8 = {
    Text = "Aber der starke Wunsch von Fräulein Ramona im letzten Moment machte die Gefühle des “Heiligen Herzens“ für <Yellow:%player%> klarer."
  },
  AvgDialog_118699_Content_80 = {
    Text = "Ein grünlich schimmernder Lichtkranz fließt im Heiligen Herzen, hinter Pollux entfaltet sich plötzlich ein Paar prächtiger schwarz-grüner Flügel. Er hebt seinen Finger und berührt, woraufhin das Heilige Herz im Einklang mit dem Licht des Silberschlüssels zu blitzen beginnt."
  },
  AvgDialog_118699_Content_81 = {
    Text = "Fräulein Ramona."
  },
  AvgDialog_118699_Content_82 = {
    Text = "Ramona ergriff die leuchtende Rose, die sie mit dem Schutzherrn vereinbart hatte, als sie dem ernsten Blick von Pollux gegenüberstand."
  },
  AvgDialog_118699_Content_83 = {
    Text = "Die geistige Kraft, die tausendfach geübt wurde, beginnt sich entlang der vertrauten Führung zu konzentrieren. Sie hebt den Kopf und blickt auf den Silberschlüssel, während sie ihre innere Stimme zusammen mit allen anderen ins Zentrum des Schlüssels einbringt."
  },
  AvgDialog_118699_Content_84 = {
    Text = "(<Yellow:%player%>, warte auf mich, ich komme dich nach Hause holen.)"
  },
  AvgDialog_118699_Content_9 = {
    Text = "Wenn wir mehr starke geistige Kräfte, die auf <Yellow:%player%> ausgerichtet sind, bündeln, können wir vielleicht %player%s Position präziser wahrnehmen."
  },
  AvgDialog_118700_Content_1 = {
    Text = "Ein Moment der Umarmung"
  },
  AvgDialog_118700_Content_10 = {
    Text = "Die Umgebungsgeräusche verschwanden. In den tiefsten Gedanken starrte Ramona auf ihr entferntes Ich."
  },
  AvgDialog_118700_Content_11 = {
    Text = "Deine Kraft ist stärker als meine... vielleicht solltest du diese Mission übernehmen, um sicherer zu sein..."
  },
  AvgDialog_118700_Content_12 = {
    Text = "Ramona spürte, was in Ramonas Innerem vorging, schüttelte den Kopf und hob ihre von einer Maske verdeckten Augen, um still in den Abgrund zu blicken."
  },
  AvgDialog_118700_Content_13 = {
    Text = "Ich bin nur hier, um dich zu verabschieden. Auf dieser langen Reise durch die Dimensionen gibt es keinen Unterschied zwischen uns, ganz zu schweigen von..."
  },
  AvgDialog_118700_Content_14 = {
    Text = "Du bist {Male=sein, Female=ihre} Partner, das ist euer Schicksal, nicht meins."
  },
  AvgDialog_118700_Content_15 = {
    Text = "Geh, bring {Male=ihn,Female=sie} zurück, “Ramona“."
  },
  AvgDialog_118700_Content_16 = {
    Text = "Ramona umklammerte die Rose fest mit ihrer Hand, und nach einer Weile nickte sie ernsthaft, während sie von einem anderen Ich beobachtet wurde, und setzte sich in das Trennungsgerät."
  },
  AvgDialog_118700_Content_17 = {
    Text = "Die physischen Augen sind fest geschlossen, während ein anderes Paar Augen langsam sich öffnet. Eine greifbare Seele löst sich vom Körper und wird von dem schimmernden Licht des “Heiligen Herzens“ des Pollux in einen nebligen, weißen Glanz gehüllt."
  },
  AvgDialog_118700_Content_18 = {
    Text = "Unter dem Blick von Dutzenden Augen drehte sich Ramona um, sah ihre Kameraden nacheinander an und trug die schweren Hoffnungen auf ihren Schultern."
  },
  AvgDialog_118700_Content_19 = {
    Text = "Unter dem Einfluss der Sehnsucht drehte sie sich um und sprang in den riesigen Wirbel. Der Eingang, der wie die Pforte zur Hölle war, verschlang im nächsten Moment die schmale Seele."
  },
  AvgDialog_118700_Content_2 = {
    Text = "Die hochschwebenden Engel senken das heilige Licht herab und warten darauf, die verirren Seelen zu Gott zu bringen."
  },
  AvgDialog_118700_Content_3 = {
    Text = "Doll und Ramona sahen sich an und aktivierten das riesige Gerät, das fast die gesamte schwarze Pfütze bedeckte. In der heftigen Erschütterung des Teichwassers stürzte der große Wirbel mit einem lauten Knall zusammen und bildete einen Abgrund, der alles zu verschlingen schien."
  },
  AvgDialog_118700_Content_4 = {Text = "Das ist..."},
  AvgDialog_118700_Content_5 = {
    Text = "Die gewaltigen Wasser des Beckens scheinen in eine andere Welt hinabzufließen, im bodenlosen Wirbel beginnt die Existenz der Welt verschwommen zu werden."
  },
  AvgDialog_118700_Content_6 = {
    Text = "Der Rand dieser Welt, der Eingang zum Dimensionsraum."
  },
  AvgDialog_118700_Content_7 = {
    Text = "Hinter dem Abgrund wartet {Male=er,Female=sie} auf dich."
  },
  AvgDialog_118700_Content_8 = {
    Text = "Ramona nickte. Bevor sie in den Abgrund trat, hielt sie plötzlich an und blickte in die Menge."
  },
  AvgDialog_118700_Content_9 = {
    Text = "Eine Nichtigkeit-Silhouette steht still hinter der Menge der Betenden. Es ist die Gestalt, die tief in ihrem Bewusstsein verborgen ist und nur sie sehen kann."
  },
  AvgDialog_118701_Content_1 = {Text = "Warten"},
  AvgDialog_118701_Content_10 = {
    Text = "Der Nebel verdichtete sich und verschwand wieder, als ein Stammgast von Misaq am Eingang zur schwarzen Pfütze erschien, still neben der Puppe stand und gemeinsam den Schatten betrachtete, der vor der “Tür“ saß."
  },
  AvgDialog_118701_Content_11 = {
    Text = "Langfristiger Kontakt mit dem Teichwasser ist nicht gut für den Körper. Willst du sie nicht ein wenig aufhalten?"
  },
  AvgDialog_118701_Content_12 = {
    Text = "Ich habe ihr eine grundlegende Schutzvorrichtung gegeben, und was die körperlichen Verletzungen betrifft, habe ich Möglichkeiten zur Behandlung. Psychische Schäden sind jedoch nicht so leicht zu heilen."
  },
  AvgDialog_118701_Content_13 = {
    Text = "Der vernünftige Professor seufzte und drehte sich neugierig um."
  },
  AvgDialog_118701_Content_14 = {
    Text = "Du bist selten bereit, hierher zu kommen. Was hast du dieses Mal mitgebracht?"
  },
  AvgDialog_118701_Content_15 = {
    Text = "Ah, eine gute Nachricht, die ihr Herz heilen kann."
  },
  AvgDialog_118701_Content_16 = {
    Text = "Partner, dank deiner Heldentaten sind die Fusionsrisse in der letzten Zeit weltweit stark zurückgegangen."
  },
  AvgDialog_118701_Content_17 = {
    Text = "Die Ermittler der Schule haben sich entspannt, jeder muss nur noch zur Schule gehen und Prüfungen ablegen, Misaq wird immer mehr zu einer normalen Universität."
  },
  AvgDialog_118701_Content_18 = {
    Text = "Es wurde vorgeschlagen, dir eine Statue neben Direktor Ward zu errichten, die Schule denkt noch darüber nach."
  },
  AvgDialog_118701_Content_19 = {
    Text = "Ich habe einen nicht unterstützten Vorschlag eingereicht. Du bist doch noch hier, warum machst du es wie der Direktor und lässt dich zur Statue machen."
  },
  AvgDialog_118701_Content_2 = {
    Text = "Kardas-Welt\nBeerdigung des Hüters"
  },
  AvgDialog_118701_Content_20 = {
    Text = "Außerdem wirst du, wenn du zurückkommst und dich siehst, wie du neben dem Direktor stehst, sicher so verlegen sein, dass du kein Wort herausbekommst."
  },
  AvgDialog_118701_Content_21 = {
    Text = "Dein Ausdruck ist so friedlich, ich kann es nicht glauben... Du musst dich in einer anderen Welt verirrt haben und vergessen haben, wie du zurückkommst..."
  },
  AvgDialog_118701_Content_22 = {
    Text = "Du hast recht, {Male=er,Female=sie} ist tatsächlich in eine andere Dimension eingetreten, eine sehr entfernte Dimension."
  },
  AvgDialog_118701_Content_23 = {
    Text = "Als Ramona die Stimme von Daffodil hinter sich plötzlich hörte, sprang sie fast unbeherrscht auf und konnte sich kaum zurückhalten, um nicht den Arm der Ladenbesitzerin zu packen."
  },
  AvgDialog_118701_Content_24 = {
    Text = "Was sagen Sie? Haben Sie {Male=ihn,Female=sie} gefunden? Dimension... ich erinnere mich, dass Sie zwischen den Dimensionen reisen können!"
  },
  AvgDialog_118701_Content_25 = {
    Text = "Wie kann ich {Male=er,Female=Sie} zurückbringen? Ich bin bereit, jeden Preis zu zahlen!"
  },
  AvgDialog_118701_Content_26 = {
    Text = "Nachdem sie kaum ihre Aufregung verbergen konnte und flehte, bemerkte Ramona das ausdruckslose Gesicht von Doll neben ihr."
  },
  AvgDialog_118701_Content_27 = {Text = "...Was?"},
  AvgDialog_118701_Content_28 = {
    Text = "Obwohl dein Entschluss sehr berührend ist, tut es mir leid, das ist eine Dimension, die nicht mit dieser Welt verbunden ist, und ich kann den Schutzherrn nicht durch den unbekannten dimensionalen Raum bringen."
  },
  AvgDialog_118701_Content_29 = {
    Text = "Wenn keine sichere Route gefunden werden kann und willkürlich durch die Dimensionströme geschwommen wird, gibt es nur das Ergebnis des Verlorenseins."
  },
  AvgDialog_118701_Content_3 = {
    Text = "Mit einem summenden Geräusch, das das Ende der Überprüfung signalisierte, zeigten zahlreiche Instrumente erneut keine Reaktion. Doll schwenkte schweigend die Hand, und die Forscher sahen sich gegenseitig an und begannen einvernehmlich, die Geräte abzubauen."
  },
  AvgDialog_118701_Content_30 = {
    Text = "Mit der aktuellen Technologie von Misaq ist es ebenfalls nicht möglich, dies zu erreichen."
  },
  AvgDialog_118701_Content_31 = {
    Text = "Was bedeutet das... Wir haben so lange versucht, endlich gibt es Nachrichten über {Male=ihn,Female=sie}. Soll {Male=er,Female=sie} wirklich alleine zurückgelassen werden?!"
  },
  AvgDialog_118701_Content_32 = {
    Text = "Die Technik des Dimensionenreisens könnte ich vielleicht mit Professor Doll besprechen, als ob es ein kostenloses Geschenk für alte Kunden wäre."
  },
  AvgDialog_118701_Content_33 = {
    Text = "Aber um <Yellow:%player%> zurückzuholen, ist das Schwierigste, wie man den Weg zu dieser Welt findet. Selbst in meiner Sammlung gibt es keinen solchen Schatz, der die Transzendenz des Universums ermöglicht."
  },
  AvgDialog_118701_Content_34 = {
    Text = "Ich werde die Forschungsabteilung ab sofort mit voller Kraft in die Dimensionforschung investieren."
  },
  AvgDialog_118701_Content_35 = {
    Text = "Zwischen den Dimensionen gibt es manchmal nie eine Schnittmenge, die man nicht durch Ausschluss finden kann."
  },
  AvgDialog_118701_Content_36 = {
    Text = "Was ihr euch stellen müsst, könnte ein Versuch sein, der so lange dauert, dass ihr die Hoffnung nicht mehr sehen könnt."
  },
  AvgDialog_118701_Content_37 = {
    Text = "Wir werden nicht aufgeben."
  },
  AvgDialog_118701_Content_38 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_118701_Content_39 = {
    Text = "Ich weiß, dass ich, egal wie lange es dauert, warten werde {Male=er,Female=sie}."
  },
  AvgDialog_118701_Content_4 = {
    Text = "Warum die Geräte wegpacken? Versuch es noch einmal, es gibt bestimmt noch Testmethoden, an die wir nicht gedacht haben..."
  },
  AvgDialog_118701_Content_40 = {
    Text = "Kardas-Welt\nSchutzherr-Begräbnis nach zehn Monaten\nschwarze Pfütze"
  },
  AvgDialog_118701_Content_41 = {
    Text = "Echos von Schritten durchdringen die versperrten Türen, treten in die zähen Wasserwellen ein, und das stille schwarze Teichwasser empfängt den zweiten Besucher des Tages."
  },
  AvgDialog_118701_Content_42 = {
    Text = "Ich wusste, dass du wieder hier bist."
  },
  AvgDialog_118701_Content_43 = {
    Text = "Der Gesprächspartner des Professors antwortete nicht, seine reglose Silhouette wandte sich weiterhin dem schwebenden Wesen vor der “Tür“ zu, wie eine Statue in der Ferne."
  },
  AvgDialog_118701_Content_44 = {
    Text = "Heute wurde wieder ein Vorschlag von jemandem an mich übermittelt. Das ist dein siebter Versuch, die Zuweisung eines Partners abzulehnen und weiterhin die Doppeluntersuchung alleine durchzuführen, oder."
  },
  AvgDialog_118701_Content_45 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_118701_Content_46 = {
    Text = "Es ist in Ordnung, ich bin nicht hier, um dich zu kritisieren oder zu befehlen, noch um dir Ratschläge zu geben, obwohl Sylvia sagt, dass deine psychologische Bewertung tatsächlich ein kleines Problem aufweist."
  },
  AvgDialog_118701_Content_47 = {
    Text = "Aber wie viele Leute an dieser Universität haben wirklich keine Probleme?"
  },
  AvgDialog_118701_Content_48 = {
    Text = "Die rosa Scheren standen neben der Statue und blickten zusammen auf die stets schlafende Gestalt."
  },
  AvgDialog_118701_Content_49 = {
    Text = "Gibt es spezielle Aufgaben, die ich ausführen soll?"
  },
  AvgDialog_118701_Content_5 = {
    Text = "Die Anzahl der Messungen und Frequenzen ist bereits ausreichend, dein Silberkern-Gerätekurs hat die volle Punktzahl, betrüge dich nicht weiter, Ramona."
  },
  AvgDialog_118701_Content_50 = {
    Text = "Die regungslose Statue begann schließlich zu sprechen, der Tonfall war so ruhig wie der einer Maschine."
  },
  AvgDialog_118701_Content_51 = {Text = "Ja."},
  AvgDialog_118701_Content_52 = {
    Text = "Aufgabenanforderungen?"
  },
  AvgDialog_118701_Content_53 = {
    Text = "Du musst an einen sehr gefährlichen Ort gehen, um deinen Partner abzuholen."
  },
  AvgDialog_118701_Content_54 = {
    Text = "Ich benötige das nicht..."
  },
  AvgDialog_118701_Content_55 = {
    Text = "Vorherige Person."
  },
  AvgDialog_118701_Content_56 = {
    Text = "Ramona drehte sich abrupt um und starrte die leblosen Augen der Puppe an."
  },
  AvgDialog_118701_Content_57 = {
    Text = "Diese Mission ist ein Glücksspiel und hat ein noch nie dagewesenes Gefahrenlevel. Ich fürchte, die Unterstützung innerhalb der Akademie kann dir nicht folgen..."
  },
  AvgDialog_118701_Content_58 = {
    Text = "Gibt es Ergebnisse von der Forschungsabteilung? Wann?"
  },
  AvgDialog_118701_Content_59 = {
    Text = "Doll lächelte und reichte dem Gegenüber den frisch erstellten Forschungsbericht."
  },
  AvgDialog_118701_Content_6 = {
    Text = "Dies ist lediglich eine leere Hülle, ohne Anzeichen von Leben. Das Bewusstsein des Schutzherrn... hat sich möglicherweise bereits aufgelöst."
  },
  AvgDialog_118701_Content_60 = {
    Text = "Seit Daffodil uns die Nachricht des Schutzherrn mitgeteilt hat, hat die Forschungsabteilung alle verfügbaren technischen Mittel ausprobiert. Unerwartet lag der letzte Durchbruch bei den Erweckern."
  },
  AvgDialog_118701_Content_61 = {
    Text = "Wir haben entdeckt, dass Pollux'“Heiliges Herz“eine Anziehung auf diese Existenz ausüben kann. Ursprünglich wurde das“Heilige Herz“des Laternenordens hergestellt, um reine Seelen zu erschaffen und das göttliche Blut zu verbreiten."
  },
  AvgDialog_118701_Content_62 = {
    Text = "Schließlich das Opfer des Heiligen Sohnes, um das sogenannte Heiligtum zu beschwören."
  },
  AvgDialog_118701_Content_63 = {
    Text = "Tatsächlich basiert das Prinzip darauf, die Aufmerksamkeit dieser einen Person zu erregen, um die Auflösung zu verbreiten. Nach gezielter Behandlung könnte das “Heilige Herz“ uns sehr wahrscheinlich gezielt den Standort des Schutzherrn weisen."
  },
  AvgDialog_118701_Content_64 = {
    Text = "Die Schule plant, ein außergewöhnliches Bewusstsein mit geistiger Kraft in den Dimensionsraum zu senden, um den Anweisungen des “Heiligen Herzens“ zu folgen, die Dimensionen zu überschreiten und einen Tunnel zu schaffen, der die beiden Welten verbindet."
  },
  AvgDialog_118701_Content_65 = {
    Text = "Wenn alle Testdaten reibungslos vorankommen, können wir in weniger als einem Monat mit dem Versuch beginnen."
  },
  AvgDialog_118701_Content_66 = {
    Text = "Deine nächsten Aufgaben werden einen Teil über das Training der geistigen Kraft enthalten. Ich hoffe, dass du... nicht zu fleißig bist, um dein Gehirn nicht zu schädigen."
  },
  AvgDialog_118701_Content_67 = {
    Text = "Kardas-Welt\nSchutzherr-Beerdigung ein Jahr später\nschwarze Pfütze"
  },
  AvgDialog_118701_Content_68 = {
    Text = "Das schnell laufende Trennungsgerät für Geister gab einen unerträglichen roten Alarm aus, und die daneben aufmerksam beobachtende Puppe drückte sofort den Stoppknopf."
  },
  AvgDialog_118701_Content_69 = {
    Text = "Die Tür des Kapsels mit dem Benutzer sprang sofort auf, und die bereits erschöpfte Ramona bewegte einen Finger, während sie von den beiden Forschern schnell herausgeholfen wurde."
  },
  AvgDialog_118701_Content_7 = {
    Text = "Das grausame Urteil fiel endlich aus dem Mund der Puppe. Als er die Tränen in Ramonas perplexen Augen sah, schloss der Professor, der an Opfergaben gewöhnt war, ebenfalls unwillig die Augen."
  },
  AvgDialog_118701_Content_70 = {
    Text = "Halte sie fest und gehe schnell in die psychische Kühlflüssigkeit!"
  },
  AvgDialog_118701_Content_71 = {
    Text = "Das hellgrüne Wasser des Teiches umschloss ihre Brust, Ramonas fieberhafte Temperatur sank endlich, und die einst rationalen, jetzt jedoch paranoid wirkenden Augen öffneten sich langsam."
  },
  AvgDialog_118701_Content_72 = {
    Text = "Selbst wenn übermorgen das Datum des ersten offiziellen Versuchs ist, darfst du deinen Körper nicht so gefährden."
  },
  AvgDialog_118701_Content_73 = {
    Text = "Es ist okay, ich kann es aushalten..."
  },
  AvgDialog_118701_Content_74 = {
    Text = "Pollux, der von einem der Geräte herübergegangen war, trat nun ebenfalls leise neben die beiden und unterbrach Dors weitere Ratschläge."
  },
  AvgDialog_118701_Content_75 = {
    Text = "Ich kann den Schmerz verstehen, einen wichtigen Menschen zu verlieren, und den Hass auf sich selbst, weil man hilflos ist... Keine Sorge, Miss Ramona."
  },
  AvgDialog_118701_Content_76 = {
    Text = "Jetzt kann das “Heilige Herz“ den Ruf der Laterne spüren. Castor und ich werden unser Bestes tun, um den Wohltäter gemeinsam zurückzuholen."
  },
  AvgDialog_118701_Content_8 = {
    Text = "Bereite die Beerdigung für <Yellow:%player%> vor, das Testament... wirst du für {Male=ihn,Female= sie} lesen."
  },
  AvgDialog_118701_Content_9 = {
    Text = "Kardas-Welt\nBeerdigung des Hüters drei Monate später"
  },
  AvgDialog_118702_Content_1 = {
    Text = "Nachricht aus der Ferne"
  },
  AvgDialog_118702_Content_10 = {
    Text = "Du schwingst deine Hände wie ein Blinder und kämpfst darum, voranzukommen, wie ein Reisender, der durch Wasser watet, während du in der zähen Dunkelheit voranschreitest und suchst."
  },
  AvgDialog_118702_Content_100 = {
    Text = "Hier gibt es keine kochend heiße Temperatur, nur endlose, zähflüssige Dunkelheit. Beim Vorwärtsbewegen beginnen Vorwärts und Rückwärts zu verschwimmen, als ob das Dasein selbst zu Nichtigkeit wird."
  },
  AvgDialog_118702_Content_101 = {
    Text = "Weiter nach vorne, nicht zurückschauen."
  },
  AvgDialog_118702_Content_102 = {
    Text = "Du vertraust dieser Stimme, versuchst deinen Geist zu leeren und gehst unermüdlich weiter, bis eine Reihe von hypnotisierenden Farben dich in einen heftigen Schwindel versetzt."
  },
  AvgDialog_118702_Content_103 = {
    Text = "...Das ist es!"
  },
  AvgDialog_118702_Content_104 = {
    Text = "Außerhalb des Meer der Ur-Essenz von Daffodil stehst du zum ersten Mal außerhalb des Universums und blickst auf die Welt."
  },
  AvgDialog_118702_Content_105 = {
    Text = "Es ist, als wäre man in die mikroskopische Welt eingetreten, ein gelartiger Raum, unzählige sich windende Linien, bizarre Formen von Geist, und weit entfernte, blitzende Galaxien..."
  },
  AvgDialog_118702_Content_106 = {
    Text = "und die grenzenlose Weltgrenze."
  },
  AvgDialog_118702_Content_107 = {
    Text = "Wenn es nicht genügend mentale Anker gibt, wirst du in diesem chaotischen und grenzenlosen Raum schnell verloren gehen, aber in deinem Herzen gibt es nicht viel Angst."
  },
  AvgDialog_118702_Content_108 = {
    Text = "Bist du bereit? Nachdem du die Verbindung hergestellt hast, werde ich mein Bestes tun, um etwas Lärm zu machen, um ihn anzuziehen. Der Rest ist dein Kampf."
  },
  AvgDialog_118702_Content_109 = {
    Text = "Du umklammerst den silbernen Schlüssel an deiner Brust und streckst ernsthaft und liebevoll die Tentakeln deines Geistes nach der blühenden Rose in deiner Hand aus."
  },
  AvgDialog_118702_Content_11 = {
    Text = "Endlich... habe ich dich gefunden! Wir @3... durch den @2 Tunnel..."
  },
  AvgDialog_118702_Content_110 = {
    Text = "Lass uns anfangen."
  },
  AvgDialog_118702_Content_111 = {
    Text = "Ein gewaltiger psychischer Wellenstoß ertönte in der Dimensionsraum und riss an der Grenze deiner geistigen Antennen plötzlich einen Riss im Raum auf."
  },
  AvgDialog_118702_Content_112 = {
    Text = "Eine riesige Pupille erschien plötzlich hinter dem Spalt, wie die Augen eines Riesen, die plötzlich aufblitzen."
  },
  AvgDialog_118702_Content_12 = {
    Text = "Du kannst ihr Erscheinungsbild nicht sehen, sondern nur abgehackte Geräusche hören. Die Person, die du gut kennst, ist ebenfalls aufgeregt und erzählt von der Freude des Wiedersehens."
  },
  AvgDialog_118702_Content_13 = {
    Text = "Du kannst spüren, dass zwischen euch ein echtes Seil zieht; es scheint, als könntest du, wenn du diesem Seil folgst, den Weg nach Hause finden."
  },
  AvgDialog_118702_Content_14 = {
    Text = "Während du unermüdlich dem Hinweis des Seils folgst, ertönt plötzlich ein Geräusch des Zerbrechens, und der gesamte Raum beginnt unter dem gewaltigen Beben zu wanken."
  },
  AvgDialog_118702_Content_15 = {
    Text = "Es greift etwas an @2, das Heilige Herz hält nicht mehr!"
  },
  AvgDialog_118702_Content_16 = {
    Text = "Ramona, Verbindung trennen!"
  },
  AvgDialog_118702_Content_17 = {Text = "Aber!"},
  AvgDialog_118702_Content_18 = {
    Text = "Schutzherr, geh und suche Daffodil! Wir werden nicht aufgeben——"
  },
  AvgDialog_118702_Content_19 = {
    Text = "Alles Licht ist verschwunden. In der fernen Distanz hat sich ein großes Unbekanntes gewendet und verschwindet allmählich im Chaos des Nichts."
  },
  AvgDialog_118702_Content_2 = {
    Text = "Schutzherr@2...Hüter..."
  },
  AvgDialog_118702_Content_20 = {Text = "!!!"},
  AvgDialog_118702_Content_21 = {
    Text = "Du setzt dich plötzlich auf dem Bett auf, umgeben von dem Raum der Schmelzen·Puppe-Basis, mit den vertrauten dunkelroten Ziegelwänden und dem leichten Geruch von Desinfektionsmittel."
  },
  AvgDialog_118702_Content_22 = {
    Text = "Du fragst mich, was los ist? Seit wann hat sich mein Forschungsbereich auch auf die Traumdeutung ausgeweitet? Solltest du nicht Clementine danach fragen?"
  },
  AvgDialog_118702_Content_23 = {
    Text = "Aber du hast recht, angesichts der Besonderheit deines Geistes neige ich auch dazu zu glauben, dass dies nicht deine Halluzination oder ein einfacher Traum ist."
  },
  AvgDialog_118702_Content_24 = {
    Text = "Was die Antwort auf das Rätsel der Wahrheit betrifft, habe ich dir das nicht schon im Traum gesagt?"
  },
  AvgDialog_118702_Content_25 = {
    Text = "Ein Silberkern, den du einst gestohlen hast, wird von Schmelzen·Puppe herausgeholt und in das Erweckungsgerät geworfen, während ein Hauch von schimmerndem violetten Rauch aus dem mechanischen Summen aufsteigt."
  },
  AvgDialog_118702_Content_26 = {
    Text = "Ach, wir sehen uns wieder, meine alten Kunden?"
  },
  AvgDialog_118702_Content_27 = {
    Text = "Daffodil! Ich......"
  },
  AvgDialog_118702_Content_28 = {
    Text = "Pssst, du musst nicht sprechen, ein kompetenter Händler kann die Wünsche des Kunden von selbst verstehen."
  },
  AvgDialog_118702_Content_29 = {
    Text = "Ich habe deine Freunde tatsächlich schon gesehen."
  },
  AvgDialog_118702_Content_3 = {
    Text = "Es scheint, als wärst du von einem riesigen Bühnenvorhang verdeckt und bedeckt, während schichtweise dicke Samtstoffe auf dir lasten, die dich unsichtbar und unbeweglich machen."
  },
  AvgDialog_118702_Content_30 = {Text = "?!"},
  AvgDialog_118702_Content_31 = {
    Text = "Als Doll: Inferno deinen schockierten Gesichtsausdruck sieht, rollt sie mit den Augen."
  },
  AvgDialog_118702_Content_32 = {
    Text = "Ich dachte, mit deinem Verstand solltest du genug darüber nachdenken können, was der Schlüssel zu ihrer Kraft ist."
  },
  AvgDialog_118702_Content_33 = {
    Text = "Die... Schlüssel der Stärke?"
  },
  AvgDialog_118702_Content_34 = {
    Text = "Du erinnerst dich an das graue Meer voller Köpfe."
  },
  AvgDialog_118702_Content_35 = {
    Text = "Dimensionsraum? Du meinst, dass Daffodil zwischen verschiedenen Welten reisen kann... sind sie dieselbe Person?"
  },
  AvgDialog_118702_Content_36 = {
    Text = "Sehr nah dran, kluges Kind, hier ich und dort ich sind tatsächlich dasselbe “Existenz“, aber du hast vergessen, dass wir keine Menschen sind."
  },
  AvgDialog_118702_Content_37 = {
    Text = "Daffodil biegt ihre Augen anerkennend und schüttelt das Rauchrohr, indem sie ihr Handgelenk dreht."
  },
  AvgDialog_118702_Content_38 = {
    Text = "Wir sind nur die Gesichter, die an der Wasseroberfläche erscheinen, das Meer aus grauem Nebel, das zwischen allen Dimensionen fließt, ist unser Wesen."
  },
  AvgDialog_118702_Content_39 = {
    Text = "Wir sind dadurch geistig verbunden, sind aber nicht dieselbe “Person“."
  },
  AvgDialog_118702_Content_4 = {
    Text = "In einem Traum aus Nichtigkeit breitet sich eine gedämpfte Stimme wie Wellen aus und verschwindet im Nu."
  },
  AvgDialog_118702_Content_40 = {
    Text = "Das heißt, du kannst durch das Meer der Ur-Essenz zwischen verschiedenen Welten reisen? Im Traum gerade eben hat mich Doll gebeten, dich zu suchen, was bedeutet, dass du jetzt einen Weg hast, mich zurück in diese Welt zu bringen?"
  },
  AvgDialog_118702_Content_41 = {
    Text = "Sei nicht ungeduldig, ich habe gesagt, selbst ich kann nicht so einfach zwischen zwei Welten eine Dimensionsreise durchführen."
  },
  AvgDialog_118702_Content_42 = {
    Text = "Wenn ich wirklich so einen Weg hätte, wie könnte ich ihn dann so geizig bis jetzt aufbewahren?"
  },
  AvgDialog_118702_Content_43 = {
    Text = "Du bist perplex und senkst langsam den Kopf."
  },
  AvgDialog_118702_Content_44 = {
    Text = "Aber diesmal haben deine mutigen Freunde einen neuen Weg gefunden."
  },
  AvgDialog_118702_Content_45 = {
    Text = "Du rissest deinen Kopf plötzlich hoch, und deine Augen leuchten wieder auf. Daraufhin lachte Daffodil leise, während Doll: Inferno spöttisch schnitt."
  },
  AvgDialog_118702_Content_46 = {
    Text = "Seit dem letzten Mal, als wir uns in dieser Welt getroffen haben, habe ich ihnen deine Nachricht übermittelt."
  },
  AvgDialog_118702_Content_47 = {
    Text = "Nachdem sie von der Besonderheit dieser Dimension erfahren hatten, hat Doll zusammen mit den Forschern von Misaq Tag und Nacht hart gearbeitet, um diese Welt zu lokalisieren. Kürzlich fanden sie eine Methode, um zwei Dimensionen zu verbinden."
  },
  AvgDialog_118702_Content_48 = {
    Text = "Was du gerade gefühlt hast, ist das Ergebnis ihrer erfolgreichen Verbindung."
  },
  AvgDialog_118702_Content_49 = {
    Text = "Also war das kein Traum? Diese Geisterverbindung ist echt?!"
  },
  AvgDialog_118702_Content_5 = {
    Text = "Wer? Ruft mich jemand? Eine so vertraute Stimme..."
  },
  AvgDialog_118702_Content_50 = {
    Text = "Ja, aber der Zusammenbruch des gerade hergestellten Links ist ebenfalls echt. Du solltest die plötzliche Ankunft dieser Person bemerkt haben."
  },
  AvgDialog_118702_Content_51 = {
    Text = "Dimensionsreisen sind extrem gefährlich. Auch wenn ich euch helfen kann, die Verfolgung durch die Jagdhunde abzuschütteln, gibt es im Dimensionsraum noch zu viele hochrangige Wesen."
  },
  AvgDialog_118702_Content_52 = {
    Text = "Sie haben normalerweise ihre eigenen Tätigkeitsbereiche, so wie Könige ihre Länder beherrschen."
  },
  AvgDialog_118702_Content_53 = {
    Text = "Ursprünglich hättest du vielleicht auf verschiedene Weisen vorsichtig ausweichen können, aber leider ist der Gegner, der auf den Tunnel abgesehen hat, der dir am vertrautesten ist."
  },
  AvgDialog_118702_Content_54 = {
    Text = "Am vertrautesten... dieses Gefühl, beobachtet zu werden, Toguwaibo? Ist er erwacht?!"
  },
  AvgDialog_118702_Content_55 = {
    Text = "Sei nicht so angespannt, die Früchte deines Opfers werden nicht so leicht verschwinden. Er ist immer noch im Schlaf gefangen."
  },
  AvgDialog_118702_Content_56 = {
    Text = "Aber er ist schließlich er. Dein und Pollux' “Heiliges Herz“ ist zu strahlend, selbst im Schlaf hat sein Unterbewusstsein euch bemerkt."
  },
  AvgDialog_118702_Content_57 = {
    Text = "Daffodils Miene wird ungewöhnlich ernst, du schweigst und erinnerst dich an den Kampf, bei dem alles geopfert wurde."
  },
  AvgDialog_118702_Content_58 = {
    Text = "Zum Glück war das Geräusch des Dimensionstransfers diesmal weit weniger als das, was Juliette beim letzten Mal verursacht hat. Der Blick, der aus ihrem Unterbewusstsein projiziert wird, wird nicht die ganze Welt zerstören."
  },
  AvgDialog_118702_Content_59 = {
    Text = "Selbst so ist eine solche Kraft nicht von dem Erwecker, der gekommen ist, um dich zu führen, zu ertragen. Daher kann man allein mit den Menschen auf der anderen Seite keinen vollständigen Dimension-Link aufbauen."
  },
  AvgDialog_118702_Content_6 = {
    Text = "Hüter... Partner!"
  },
  AvgDialog_118702_Content_60 = {
    Text = "Ich brauche dich, <Yellow:%player%>, um hier seine Aufmerksamkeit auf dich zu ziehen und ihn zurückzuschlagen, damit du den Tunnel zwischen den beiden Welten schützt, die weit entfernt in einer anderen Welt sind."
  },
  AvgDialog_118702_Content_61 = {
    Text = "Der Blick von Toguwaibo... es ist wieder Er..."
  },
  AvgDialog_118702_Content_62 = {
    Text = "Dieser Kampf war so fern, so fern wie etwas, das in einem früheren Leben geschehen ist."
  },
  AvgDialog_118702_Content_63 = {
    Text = "Der Kampf war so nah, dass du dir jedes Detail darin mühelos ins Gedächtnis rufen kannst."
  },
  AvgDialog_118702_Content_64 = {
    Text = "Jede schreckliche Wunde, jeder grausame Sieg, jedes Angstbeben, jeder verzweifelte Schrei am Rande des Todes..."
  },
  AvgDialog_118702_Content_65 = {
    Text = "Den Gottheiten ins Gesicht zu blicken, hat all deinen Mut und dein Leben gekostet. Wenn du an diese Blicke zurückdenkst, die über die Regeln hinausgehen, beginnt deine Stimme unkontrollierbar zu zittern."
  },
  AvgDialog_118702_Content_66 = {
    Text = "Selbst die Projektion des unbewussten Blicks ist wahrscheinlich nicht die Kraft, die ich aufhalten kann..."
  },
  AvgDialog_118702_Content_67 = {
    Text = "Jetzt kann ich die Kraft der drei Plasmide nicht vollständig abrufen und habe keine Hilfe von anderen Dimensionen, um ihn aufzuhalten..."
  },
  AvgDialog_118702_Content_68 = {
    Text = "Was ist los, unser mutiger Hüter, hast du Angst?"
  },
  AvgDialog_118702_Content_69 = {
    Text = "Du ballst die Fäuste, schüttelst den Kopf und schaust Daffodil ernst an."
  },
  AvgDialog_118702_Content_7 = {Text = "Ramona?!"},
  AvgDialog_118702_Content_70 = {
    Text = "Egal wie viel Angst ich habe, solange ich zurückkehren kann, kann mich nichts aufhalten. Ich mache mir nur Sorgen, dass meine Fähigkeiten im Moment nicht ausreichen."
  },
  AvgDialog_118702_Content_71 = {
    Text = "Wenn ich versage, besteht sogar die Gefahr, dass er erneut erweckt wird... Eine solche Katastrophe kann von niemandem ertragen werden."
  },
  AvgDialog_118702_Content_72 = {
    Text = "Gut. Es scheint, dass unser Schutzherr den Mut, sich gegen die Götter zu stellen, noch nicht verloren hat."
  },
  AvgDialog_118702_Content_73 = {
    Text = "Keine Sorge, <Yellow:%player%>. Diesmal werde ich dir auch helfen, die Lücken zwischen den verschiedenen Dimensionen zu öffnen und seine Kraft auf verschiedene Dimensionen zu verteilen."
  },
  AvgDialog_118702_Content_74 = {
    Text = "Beim letzten Mal kämpften die Hüter aus anderen Dimensionen Schulter an Schulter mit dir. Diesmal werden sie auch weiterhin an Orten sein, die du nicht sehen kannst, und denselben Kampf mit dir führen."
  },
  AvgDialog_118702_Content_75 = {
    Text = "Wirklich?! Wenn das der Fall ist, werden wir auf jeden Fall die Kraft haben, Ihn erneut aufzuhalten!"
  },
  AvgDialog_118702_Content_76 = {
    Text = "Dennoch wird ein Kampf auf dieser Ebene die gesamte Welt hier durch ihn zerstören, und außer <Yellow:%player%> hat kein Überlebender in dieser Welt die Fähigkeit, ihm entgegenzutreten."
  },
  AvgDialog_118702_Content_77 = {
    Text = "Genau, deshalb muss dieser Kampf im Dimensionsraum stattfinden. Wie man <Yellow:%player%> dazu bringt, längere Zeit im Dimensionsraum zu verweilen, benötigt ebenfalls die Hilfe eines Genies."
  },
  AvgDialog_118702_Content_78 = {
    Text = "Bitte, Schmelzen·Doll!"
  },
  AvgDialog_118702_Content_79 = {
    Text = "...Hm, ein oder zwei sind gut organisiert."
  },
  AvgDialog_118702_Content_8 = {
    Text = "Mit der Aussprechung dieses Namens wird eine unsichtbare Barriere sofort durchbrochen, eine zärtliche und warme Verbindung überquert unzählige Zeiten und wird zu einem schimmernden Faden, der sich deinem Herzen nähert."
  },
  AvgDialog_118702_Content_80 = {
    Text = "Lass es gut sein, wer hat mir versprochen, dir zu helfen, nach Hause zu kommen? Das Versprechen gegenüber dem Welpen werde ich einhalten."
  },
  AvgDialog_118702_Content_81 = {Text = "Danke!"},
  AvgDialog_118702_Content_82 = {
    Text = "Keine Eile mit dem Dank. Zuerst kläre ich, dass ich nur dein Bewusstsein im Dimensionsraum festhalten kann und so gut wie möglich sicherstellen werde, dich jederzeit in diese Welt zurückzubringen."
  },
  AvgDialog_118702_Content_83 = {
    Text = "Was deinen Kampf mit jener Person betrifft, gibt es immer noch die Möglichkeit des Scheiterns oder sogar des Todes."
  },
  AvgDialog_118702_Content_84 = {
    Text = "Ich bin nicht optimistisch gegenüber einem so impulsiven Plan. Dennoch musst du ein solches Risiko eingehen, um auf ein unbekanntes Ergebnis zu wetten?"
  },
  AvgDialog_118702_Content_85 = {
    Text = "Ich bin bereit, sie haben das gleiche Risiko für mich auf sich genommen, ich habe keinen Grund, ihnen nicht zu antworten. Egal wie, selbst wenn wir in zwei verschiedenen Welten sind, kämpfen wir immer noch Schulter an Schulter wie früher."
  },
  AvgDialog_118702_Content_86 = {
    Text = "Schmelzen·Doll nickte ohne Überraschung, und Daffodil sah dich lächelnd an, als ob sie niemals daran gedacht hätte, dass du zurückweichen könntest."
  },
  AvgDialog_118702_Content_87 = {
    Text = "Verstanden, solche kitschigen Schwüre sind besser für deine tapferen Gefährten geeignet. Ich brauche etwas Zeit zur Vorbereitung, und was den Zeitpunkt für den Beginn der Aktion angeht, hast du sicherlich bereits einen Plan?"
  },
  AvgDialog_118702_Content_88 = {
    Text = "Angesichts der Frage von Schmelzen·Doll wandte Daffodil ihren Blick stattdessen dir zu."
  },
  AvgDialog_118702_Content_89 = {
    Text = "Natürlich hat dein Partner mir ein Geschenk mitgebracht."
  },
  AvgDialog_118702_Content_9 = {
    Text = "Das ist... eine geistige Verbindung?! Ramona, bist du das? Wo bist du?"
  },
  AvgDialog_118702_Content_90 = {
    Text = "Der Nebel wirbelt, und eine Rose, die aus dem Nichts hervorgeholt wurde, wird dir entgegengereicht."
  },
  AvgDialog_118702_Content_91 = {
    Text = "Das ist... die Blume, die Ramona mir geschenkt hat...?!"
  },
  AvgDialog_118702_Content_92 = {
    Text = "Leider habe ich noch nicht die Fähigkeit, reale Objekte durch Dimensionsprojektion zu transportieren."
  },
  AvgDialog_118702_Content_93 = {
    Text = "Allerdings hat jedes Ding in diesen beiden Dimensionen sein entsprechendes Gegenstück."
  },
  AvgDialog_118702_Content_94 = {
    Text = "Die Rose, die diesem entspricht, ist die, die Ramona dir in dieser Dimension geschenkt hat."
  },
  AvgDialog_118702_Content_95 = {
    Text = "Ich habe diese Blume ein wenig bearbeitet. Wenn du bereit bist, verbinde deine mentale Verbindung mit dieser Blume. Die Leute dort werden die Nachricht erhalten."
  },
  AvgDialog_118702_Content_96 = {
    Text = "Sie sagte, dass sie dir diese Blume persönlich an die Brust stecken wird, wenn ihr euch begegnet."
  },
  AvgDialog_118702_Content_97 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_118702_Content_98 = {
    Text = "Du erfährst zum ersten Mal, dass der Weg, den Schmelzen·Doll beim Verlassen der Welt benutzt hat, die bereits verschwundene Sonne über deinem Kopf ist."
  },
  AvgDialog_118702_Content_99 = {
    Text = "Das schwarze Loch der Sonne ist wie eine Wunde, die die Welt nicht heilen kann. Als dein Bewusstsein langsam darin eindringt, ist es, als würdest du in den leeren Brustkorb eines Riesen kriechen."
  },
  AvgDialog_118703_Content_1 = {
    Text = "Die angehobenen Fingerspitzen"
  },
  AvgDialog_118703_Content_10 = {
    Text = "Ein schrecklicher Schrei, der nicht zu irgendeinem Wesen oder einer Dimension gehört und direkt aus den Tiefen des Bewusstseins ertönt, zerreißt fast dein Gehirn."
  },
  AvgDialog_118703_Content_100 = {
    Text = "Ugh—Kopf... mir tut so weh..."
  },
  AvgDialog_118703_Content_101 = {
    Text = "Die angeschlossenen Geräte sind fast vollständig beschädigt, dass du lebend zurückgekommen bist, ist einfach ein Wunder."
  },
  AvgDialog_118703_Content_102 = {
    Text = "Aber dieser Ort hat schon zu viele Wunder gesehen. Vielleicht ist die Wahrscheinlichkeitstheorie selbst ein Irrtum für die schwarze Pfütze."
  },
  AvgDialog_118703_Content_103 = {
    Text = "Gut gemacht, Ramona. Mach das beim nächsten Mal nicht wieder."
  },
  AvgDialog_118703_Content_104 = {
    Text = "Sei unbesorgt, Professor Doll... ich verstehe, was ich tue."
  },
  AvgDialog_118703_Content_105 = {
    Text = "Für %player% ist es vielleicht wichtiger, dich wiederzusehen als viele andere Dinge."
  },
  AvgDialog_118703_Content_106 = {
    Text = "Das einzige Bedauern ist, dass du die letzte Aussage von {Male=ihm,Female=ihr} nicht hören konntest."
  },
  AvgDialog_118703_Content_107 = {
    Text = "Nein, Narzissenfrau. {Male=seine,Female=ihre} Worte habe ich bereits gehört..."
  },
  AvgDialog_118703_Content_108 = {
    Text = "Ramona stand schwach auf und lächelte, als sie vor dem verschwindenden Loch in der schwarzen Pfütze stand."
  },
  AvgDialog_118703_Content_109 = {
    Text = "Der Abgrund kollabiert in ihren Augen, von einem alles verschlingenden Ungeheuer zu einer Tür, die Dimensionen trennt, bis hin zu einem Spalt der Nichtigkeit, bis er vollständig verschwindet."
  },
  AvgDialog_118703_Content_11 = {
    Text = "Du fällst auf die Knie und hältst dir fest die Ohren zu, während das Blut unkontrollierbar aus deinen Augenhöhlen quillt..."
  },
  AvgDialog_118703_Content_110 = {
    Text = "Ramonas Hand strich sanft über den Ort, an dem der Abgrund einst existierte, über den zerschundenen Körper."
  },
  AvgDialog_118703_Content_111 = {
    Text = "Sie lächelte, als würde sie die nahende Zukunft sehen, in der der Besitzer ihres Körpers vor ihr steht, an einem Tag, der ebenso gewöhnlich war wie einst in Misaq."
  },
  AvgDialog_118703_Content_112 = {
    Text = "Ich habe es gehört, Hüter des Geheimnisses... wir werden es schaffen."
  },
  AvgDialog_118703_Content_113 = {
    Text = "Ich warte auf dich, %player%."
  },
  AvgDialog_118703_Content_12 = {
    Text = "<Shake:Puh... Puh...>"
  },
  AvgDialog_118703_Content_13 = {
    Text = "Scheint es... vorbei zu sein?"
  },
  AvgDialog_118703_Content_14 = {
    Text = "Der durchdringende Schrei ist verschwunden, ohne dass du es bemerkt hast. Du hebst den Kopf. In der zerbrechlichen, illusionären Dimension gibt es längst keine schreckliche Atmosphäre mehr, die dir einen Schauer über den Rücken jagt."
  },
  AvgDialog_118703_Content_15 = {
    Text = "Du hast gesiegt. Sein Unterbewusstsein ist von hier getrennt, das letzte große Auge ist in der Dimension verschwunden."
  },
  AvgDialog_118703_Content_16 = {
    Text = "Du hältst mit Mühe deinen erschöpften Geist stabil und drehst dich fast instinktiv um."
  },
  AvgDialog_118703_Content_17 = {Text = "Knack"},
  AvgDialog_118703_Content_18 = {
    Text = "Ein Geräusch von zerbrechendem, illusorischem Kristall dringt in dein Ohr, und du siehst einen dimensionale Tunnel, der wie ein Spinnennetz aufbricht, und Ramona, deren Geist zu flackern beginnt wie ein alter Fernseher."
  },
  AvgDialog_118703_Content_19 = {
    Text = "<Big:<Shake:Ramona!!!>>"
  },
  AvgDialog_118703_Content_2 = {
    Text = "Es fehlt nur noch... der letzte Punkt...!"
  },
  AvgDialog_118703_Content_20 = {
    Text = "Der bereits erschöpfte Körper scheint in einem Moment geheilt zu sein. Du kannst an nichts anderes mehr denken und fliegst wie der Wind zu ihr, zitternd greifst du nach ihren Händen."
  },
  AvgDialog_118703_Content_21 = {
    Text = "Ich, ich bin okay..."
  },
  AvgDialog_118703_Content_22 = {
    Text = "Dein Partner lächelt wie gewohnt, sie greift deine Hand fester, als ob nichts passiert wäre, und setzt die ursprünglichen Pläne fort."
  },
  AvgDialog_118703_Content_23 = {
    Text = "Du hast ihn besiegt, komm, folge mir, ich werde dich zurückbringen."
  },
  AvgDialog_118703_Content_24 = {
    Text = "Sie zieht dich, wie sie es bei den Aufgaben gewöhnlich tut.\n Nur eine rationalere Stimme ertönt fast kalt."
  },
  AvgDialog_118703_Content_25 = {
    Text = "Ramona, der Dimensions-Tunnel wurde von ihm zerschlagen, dein Geist kann die Last des Tunnels nicht weiter tragen. Wenn das so weitergeht, wirst du nur ins Hirntod gehen."
  },
  AvgDialog_118703_Content_26 = {
    Text = "Diese Rettung ist bereits... gescheitert. Du musst sofort zurückkommen, ich werde den Rückrufmodus des Trennungsgeräts aktivieren, damit dein Geist in deinen Körper zurückkehrt."
  },
  AvgDialog_118703_Content_27 = {
    Text = "<Big:Ich gehe nicht!>"
  },
  AvgDialog_118703_Content_28 = {
    Text = "Du siehst zum ersten Mal, wie diese immer so ruhige Person so unbeherrscht schreit. Sie scheint kurz ihre Nasenflügel zu bewegen und zeigt dir schnell ein viel natürlicheres Lächeln."
  },
  AvgDialog_118703_Content_29 = {
    Text = "Ich kann noch, <Yellow:%player%>, ich habe in letzter Zeit viel trainiert, meine geistige Kraft ist gewachsen, Doll weiß nicht, wo meine wahren Grenzen liegen."
  },
  AvgDialog_118703_Content_3 = {
    Text = "Als dein Geist am Rande der Erschöpfung steht, beginnen die Augen des Göttlichen aufgrund der Schwäche zu zittern."
  },
  AvgDialog_118703_Content_30 = {
    Text = "Gib nicht auf, lass es uns noch einmal versuchen, nur ein bisschen ausprobieren, okay?"
  },
  AvgDialog_118703_Content_31 = {
    Text = "Sie bittet dich."
  },
  AvgDialog_118703_Content_32 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_118703_Content_33 = {
    Text = "Du kannst kein Wort sagen."
  },
  AvgDialog_118703_Content_34 = {
    Text = "Warum sich so quälen? Lass mich ihren Geist in diese Welt bringen und in den sorgfältig hergestellten Körper der Puppe einsetzen, damit sie wieder an der Seite von <Yellow:%player%> sein kann."
  },
  AvgDialog_118703_Content_35 = {
    Text = "Die stets amüsierte Schmelzen·Dore trat ebenfalls dem Kommunikationskanal bei und ließ ein schelmisches Lachen hören."
  },
  AvgDialog_118703_Content_36 = {
    Text = "Nichtiges Gerede. Du weißt, dass nicht jeder wie ein Schutzherr über längere Zeit geistig vom physischen Körper abgekoppelt sein kann, sonst müssten wir nicht jeden Tag mit einem Fass voller pinker Gehirne herumlaufen."
  },
  AvgDialog_118703_Content_37 = {
    Text = "Kein Problem, Ramona, beim nächsten Mal warte ich darauf, dass du dich ausgeruht hast, um mich abzuholen."
  },
  AvgDialog_118703_Content_38 = {
    Text = "Du blickst auf die durchsichtige Gestalt, die sich wie auflösen scheint, lächelst leicht und verbirgst all deine Sehnsüchte nach Heimat."
  },
  AvgDialog_118703_Content_39 = {
    Text = "So einfach ist das nicht, diese “Route“ wurde bereits von Ihm entdeckt. Bei der nächsten Nutzung wird nur eine stärkere Beobachtung hervorgerufen."
  },
  AvgDialog_118703_Content_4 = {
    Text = "Das ist das Schlachtfeld des Willens. Du bist wie ein sterbendes Biest, das all seine Kraft aufbringt, um das letzte bisschen Stärke aus der vertrockneten geistigen Welt herauszupressen."
  },
  AvgDialog_118703_Content_40 = {
    Text = "Schmelzen·Dore hat deine Illusionen ohne Gnade durchbohrt, während die andere Doll nur schwieg."
  },
  AvgDialog_118703_Content_41 = {
    Text = "<Shake:Wir sind bis hierher gekommen, diesmal, jetzt, möchte ich dich zurückbringen.>"
  },
  AvgDialog_118703_Content_42 = {
    Text = "Ramona begann ebenfalls zu zittern. Du atmetest langsam ein, klopfst ihr mit einer scheinbar lockeren Geste auf die Hand."
  },
  AvgDialog_118703_Content_43 = {
    Text = "Ramona, erinnerst du dich an unser erstes Treffen?"
  },
  AvgDialog_118703_Content_44 = {
    Text = "Ramona nickte und schüttelte den Kopf, sah dich mit einem fast flehenden Blick an. Du musstest die Augen schließen und unbarmherzig weitersprechen."
  },
  AvgDialog_118703_Content_45 = {
    Text = "Das war wirklich eine schreckliche Katastrophe. Nach der großen Explosion erinnere ich mich nur verschwommen, dass alles um mich herum mit einem ohrenbetäubenden Knall in Trümmer fiel. Als ich die Augen öffnete, dachte ich, ich sei bereits im Himmel angekommen."
  },
  AvgDialog_118703_Content_46 = {
    Text = "Das grelle Sonnenlicht strömt durch die zwischen den ausgegrabenen Steinen hindurch und dann ist es deine Hand, die sich mir entgegenstreckt."
  },
  AvgDialog_118703_Content_47 = {
    Text = "Damals dachte ich, ist die Kleidung der Engel wirklich so seltsam? So eine strenge Uniform, ich hätte nie gedacht, dass ich bald selbst in so einer Uniform stecken würde."
  },
  AvgDialog_118703_Content_48 = {
    Text = "Ramona wollte noch etwas sagen, wurde aber von dir unterbrochen. Du redetest unaufhörlich wie ein alter Mann, der in Erinnerungen schwelgt."
  },
  AvgDialog_118703_Content_49 = {
    Text = "Nachdem ihr mich ausgegraben habt, habe ich dich immer als den freundlichsten Menschen angesehen, aber als ich in Misaq ankam, stellte ich fest, dass ich einem riesigen Betrug zum Opfer gefallen bin."
  },
  AvgDialog_118703_Content_5 = {
    Text = "Du hebst den silbernen Schlüssel mit zitternden Händen hoch."
  },
  AvgDialog_118703_Content_50 = {
    Text = "Als ich anfing, den Vorbereitungskurs zu besuchen, hast du gesagt, du seist mein Partner und würdest mir bei allen Problemen im Leben und im Studium helfen, und ich habe dir geglaubt."
  },
  AvgDialog_118703_Content_51 = {
    Text = "Tatsächlich hast du mein Problem gelöst, und zwar mit der Methode, die das Problem an der Wurzel packt — <Shake:Löse mich>."
  },
  AvgDialog_118703_Content_52 = {
    Text = "Der sogenannte Partner ist eigentlich der größte Aufseher. In diesem Jahr warst du derjenige, der im Vorbereitungskurs am strengsten mit mir umging."
  },
  AvgDialog_118703_Content_53 = {
    Text = "Nicht nur im Unterricht muss ich aufpassen, wenn ich neben mir sitze, sondern auch nach dem Unterricht beim Hausaufgaben machen. Manchmal nach dem Fitnesstraining darf ich nicht einmal eine Portion Fish and Chips essen, das ist wirklich zu gemein."
  },
  AvgDialog_118703_Content_54 = {
    Text = "Ramonas stiller und trauriger Gesichtsausdruck wurde für einen Moment durchbrochen, und die Mundwinkel zuckten unwillkürlich nach oben."
  },
  AvgDialog_118703_Content_55 = {
    Text = "Aber, mein lieber Partner, der gleichzeitig auch derjenige ist, der sich am meisten um mich kümmert."
  },
  AvgDialog_118703_Content_56 = {
    Text = "Die unverständliche Sprache von Leo, der Druck, bei Prüfungen zusammenzubrechen, Hausaufgaben, die man nicht schreiben kann... In allen traurigen Momenten kann man sich an den allmächtigen Partner wenden."
  },
  AvgDialog_118703_Content_57 = {
    Text = "Ich erinnere mich, dass ich nach dem ersten Mal, als ich die Schüler sah, die bei der Mission ihr Leben verloren haben, nachts im Bett wälzte und heimlich an deine Zimmertür klopfte."
  },
  AvgDialog_118703_Content_58 = {
    Text = "Dann ziehst du mich mit und rennst auf das Dach des Glockenturms, ich klettere mühsam hinter dir her auf das Dach, und so sitzen wir Seite an Seite und schauen die Sterne an."
  },
  AvgDialog_118703_Content_59 = {
    Text = "Du hast lange und viel mit mir gesprochen. Das war das erste Mal, dass ich wusste, dass du auch nicht weißt, wie deine Mutter und deine Kindheit waren."
  },
  AvgDialog_118703_Content_6 = {
    Text = "Hier... endet es!——"
  },
  AvgDialog_118703_Content_60 = {
    Text = "Mein Herz, das immer ein wenig einsam und ein wenig verwirrt war, ist plötzlich gefallen."
  },
  AvgDialog_118703_Content_61 = {
    Text = "Ich denke, obwohl ich keine Familie habe, ist dies vielleicht die einzige Person auf der Welt, die so gut zu mir ist und so ähnlich wie ich, fast wie eine Familie."
  },
  AvgDialog_118703_Content_62 = {
    Text = "Ich schwöre dir feierlich, dass ich in Zukunft sicher meine Hausaufgaben ernsthaft machen, aufmerksam im Unterricht sein und meine Aufgaben gewissenhaft erledigen werde."
  },
  AvgDialog_118703_Content_63 = {
    Text = "Seitdem betrachte ich Misaq als mein echtes Zuhause. Bei den darauf folgenden Aufgaben habe ich so viele Erwecker kennengelernt und immer wieder neue Familienmitglieder gefunden."
  },
  AvgDialog_118703_Content_64 = {
    Text = "<Yellow:%player%>..."
  },
  AvgDialog_118703_Content_65 = {
    Text = "Also, danke dir, danke euch, dass ihr mich abgeholt habt, meine Familie."
  },
  AvgDialog_118703_Content_66 = {
    Text = "Ich weiß, dass ihr es schon lange versucht habt und viel Mühe investiert habt."
  },
  AvgDialog_118703_Content_67 = {
    Text = "Dann komm mit mir, ich werde dich auf jeden Fall zurückbringen."
  },
  AvgDialog_118703_Content_68 = {
    Text = "Während du die Tränen, die aus Ramonas Augenwinkeln flossen, anschaust, lächelst du weiterhin, doch eine heiße Flüssigkeit strömt unkontrolliert über deine Wangen."
  },
  AvgDialog_118703_Content_69 = {
    Text = "Du betrachtest ihre Gestalt, die aufgrund ihrer mentalen Erschöpfung verschwommen und flackernd wird, und schüttelst sanft den Kopf."
  },
  AvgDialog_118703_Content_7 = {
    Text = "Blendendes silbernes Licht entfaltet sich in deiner Hand, das silberweiße Licht erhellt die gesamte illusorische Dimension."
  },
  AvgDialog_118703_Content_70 = {
    Text = "Lass es gut sein, Ramona."
  },
  AvgDialog_118703_Content_71 = {
    Text = "Nein, nein..."
  },
  AvgDialog_118703_Content_72 = {
    Text = "Ramona schien bereits etwas geahnt zu haben, sie schüttelte verzweifelt den Kopf und hielt mit ihren verschwommenen Händen fest deinen Geist."
  },
  AvgDialog_118703_Content_73 = {
    Text = "Ich verspreche dir, ich werde zurückkehren ..."
  },
  AvgDialog_118703_Content_74 = {
    Text = "Ich verspreche dir, wir werden uns wiedersehen."
  },
  AvgDialog_118703_Content_75 = {
    Text = "Du ziehst sanft deine Hand aus der vertrauten Handfläche zurück und lässt sie los."
  },
  AvgDialog_118703_Content_76 = {
    Text = "Am anderen Ende der Kommunikation empfängt Doll das Signal, das vertraute Gefühl des Abzugs des Geräts dringt in Ramonas Geist ein, sie weiß, dass sie gehen muss."
  },
  AvgDialog_118703_Content_77 = {
    Text = "“Sicher“,“absolut“, so wie die Worte, die du gesagt hast, als du zum ersten Mal durch die Tür tratst... Eigentlich glaubst du selbst nicht daran, oder?"
  },
  AvgDialog_118703_Content_78 = {
    Text = "Du bist wirklich eine herzlose Person..."
  },
  AvgDialog_118703_Content_79 = {
    Text = "Ramona, ich..."
  },
  AvgDialog_118703_Content_8 = {
    Text = "<Shake:Ugh@2@4@3!!!——>"
  },
  AvgDialog_118703_Content_80 = {
    Text = "Ermittlerkodex... Was versprochen wurde, muss gehalten werden."
  },
  AvgDialog_118703_Content_81 = {
    Text = "Ich glaube an dich. Auch wenn du selbst nicht daran glaubst, auch wenn du mich unzählige Male belogen hast, ich glaube an dich."
  },
  AvgDialog_118703_Content_82 = {
    Text = "In dem Gesicht, in dem Weinen und Lachen miteinander verwoben sind, starrten Ramonas Pupillen dich an, als ob sie dein Antlitz fest im Gedächtnis behalten wollte."
  },
  AvgDialog_118703_Content_83 = {
    Text = "Im letzten Moment, als der Geist zurückgerufen wurde, streckte sie dir mit aller Kraft erneut die Hand entgegen."
  },
  AvgDialog_118703_Content_84 = {
    Text = "Wie in dem Moment vor langer Zeit unter dem nächtlichen Sternenhimmel, streckte sie ihren kleinen Finger aus und berührte sanft deine Fingerspitze."
  },
  AvgDialog_118703_Content_85 = {
    Text = "Du wirst es schaffen, oder?"
  },
  AvgDialog_118703_Content_86 = {
    Text = "Ich habe auf deine Antwort gewartet. Im nächsten Moment zerfiel die illusorische Silhouette zusammen mit dem Dimensionstunnel und verwandelte sich in funkelnde Schatten, die langsam verschwanden, ohne eine Spur zu hinterlassen."
  },
  AvgDialog_118703_Content_87 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_118703_Content_88 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_118703_Content_89 = {
    Text = "Atmung normal. Herzfrequenz normal. Mentale Stärke unter Warnlinie... Erholung läuft."
  },
  AvgDialog_118703_Content_9 = {Text = "Ah—"},
  AvgDialog_118703_Content_90 = {
    Text = "So viel geistige Kraft auspressen und trotzdem überleben, das Leben des Welpen ist wirklich stark."
  },
  AvgDialog_118703_Content_91 = {
    Text = "Ich habe ein großartiges Stück gesehen. Schade, dass ich nicht gesehen habe, wie die Götter, die ihr herbeigerufen habt, diese Welt zerstören, das Ende war nicht spektakulär genug."
  },
  AvgDialog_118703_Content_92 = {
    Text = "Keine Sorge... Ich habe gesagt, ich werde ihn in einem anderen Raum aufhalten. Ein nicht einhaltbares Versprechen... wird es nicht noch einmal geben."
  },
  AvgDialog_118703_Content_93 = {
    Text = "Diese Worte sollten wir aufbewahren und ihr persönlich sagen, wenn wir zurück sind."
  },
  AvgDialog_118703_Content_94 = {
    Text = "Da ich diesen Weg mit euch gegangen bin, möchte ich auch sehen, wie weit ihr gehen könnt."
  },
  AvgDialog_118703_Content_95 = {
    Text = "Nachdem du dich gut ausgeruht hast, mach weiter auf dem Weg, mein Welpe."
  },
  AvgDialog_118703_Content_96 = {
    Text = "Du spürst die Restwärme, die ihre Fingerspitzen hinterlassen haben, und umschließt langsam den kleinen Finger, den du gerade mit ihr verbunden hast, drückst ihn fest gegen deine Brust."
  },
  AvgDialog_118703_Content_97 = {
    Text = "In Richtung des weiten, einsamen Dimensionraums, in Richtung der längst verschwundenen fernen Gestalt, flüsterst du leise und erzählst von dem Versprechen, das du auf jeden Fall einhalten wirst."
  },
  AvgDialog_118703_Content_98 = {
    Text = "Auch wenn du mich jetzt nicht hören kannst... Ich werde es schaffen. Warte auf mich, Ramona!"
  },
  AvgDialog_118703_Content_99 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_118944_Content_1 = {
    Text = "Nachdem du den letzten deformierten Fischmenschen niedergeschlagen hast, näherst du dich kämpfend und zurückweichend dem Mädchen in der Ecke."
  },
  AvgDialog_118944_Content_10 = {
    Text = "William versuchte, die Luke zum Schiffsrumpf zu öffnen, aber egal wie sehr er sich anstrengte, das Luke bewegte sich keinen Zentimeter."
  },
  AvgDialog_118944_Content_11 = {
    Text = "Nein, die Tür ist von unten versiegelt!"
  },
  AvgDialog_118944_Content_12 = {
    Text = "Der Rumpf des Schiffes stöhnte gespenstisch, während er sich in den übermächtigen Wellen mühsam und entschlossen wendete, auf ein noch dunkleres, sturmreicheres Seegebiet zusteuernd."
  },
  AvgDialog_118944_Content_13 = {
    Text = "Miryam breitete ihre Arme aus und umarmte diese zerstörerische Richtung, während ein fast mütterliches Lächeln auf ihrem Gesicht erschien."
  },
  AvgDialog_118944_Content_14 = {
    Text = "Das Ritual neigt sich dem Ende zu!"
  },
  AvgDialog_118944_Content_15 = {
    Text = "Hast du die Antwort gefunden?"
  },
  AvgDialog_118944_Content_16 = {
    Text = "Inmitten des Kampfes zwischen Sturm und Chaos kann niemand die Position aller unterscheiden..."
  },
  AvgDialog_118944_Content_17 = {
    Text = "Egal, wenn es noch ein kleines Boot gibt..."
  },
  AvgDialog_118944_Content_18 = {
    Text = "Unzählige Hinweise leuchten in deinem Kopf auf..."
  },
  AvgDialog_118944_Content_19 = {
    Text = "Wächter des Wohnzimmers."
  },
  AvgDialog_118944_Content_2 = {
    Text = "Murphy, komm mit mir!"
  },
  AvgDialog_118944_Content_20 = {
    Text = "Die Lotsenzeremonie auf dem Deck."
  },
  AvgDialog_118944_Content_21 = {
    Text = "Explosion im Kraftwerk."
  },
  AvgDialog_118944_Content_22 = {
    Text = "Rettungsboot im unteren Schiffsrumpf."
  },
  AvgDialog_118944_Content_23 = {
    Text = "Lichtpunkte verbinden sich, verweben sich, dehnen sich aus... und sammeln sich schließlich zu einer zusammenhängenden und klaren Fluchtlinie."
  },
  AvgDialog_118944_Content_24 = {
    Text = "Wilhelm nickte."
  },
  AvgDialog_118944_Content_25 = {
    Text = "Da du die Antwort bereits erhalten hast, ist das Ziel dieser Wiederholung im Wesentlichen erreicht, du musst nicht bedauern."
  },
  AvgDialog_118944_Content_26 = {
    Text = "Nach dem Muster, das du beschrieben hast, wird das Schiff anfangen zu sinken."
  },
  AvgDialog_118944_Content_27 = {
    Text = "Bist du bereit?"
  },
  AvgDialog_118944_Content_28 = {
    Text = "Die Flut hat bereits eure Brust verschlungen, du hältst sanft den silbernen Schlüssel an deiner Brust und flüsterst die Worte des Abschieds."
  },
  AvgDialog_118944_Content_29 = {
    Text = "Wir sehen uns im nächsten Kreislauf wieder."
  },
  AvgDialog_118944_Content_3 = {
    Text = "Sie zuckte erschrocken zusammen, ihre verschwommenen Augen mühten sich, deinen Gesichtsausdruck zu fokussieren."
  },
  AvgDialog_118944_Content_30 = {
    Text = "Möge der Silberschlüssel unseren Weg erhellen."
  },
  AvgDialog_118944_Content_4 = {
    Text = "Nein, es hat keinen Sinn, alles ist Illusion... Egal ob vorwärts oder rückwärts, es ist..."
  },
  AvgDialog_118944_Content_5 = {
    Text = "Egal, solange es nicht die letzte Minute ist, gib nicht auf zu versuchen! Selbst wenn ich dieses Mal wieder scheitere, werde ich deine Hand wieder ergreifen!"
  },
  AvgDialog_118944_Content_6 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_118944_Content_7 = {
    Text = "Murphy sah dich verwirrt an."
  },
  AvgDialog_118944_Content_8 = {
    Text = "Du greifst ihr Handgelenk mit einer sanften, aber unnachgiebigen Kraft und ziehst sie aus der verzweifelten Ecke heraus."
  },
  AvgDialog_118944_Content_9 = {
    Text = "Wilhelm, der Seniorstudent, gibt es einen Fluchtweg?"
  },
  AvgDialog_118945_Content_1 = {
    Text = "Kleiner Kerl, du hast im Kampf nachgelassen."
  },
  AvgDialog_118945_Content_10 = {
    Text = "Einige Menschen begehen böse Taten, um in der letzten Phase ihres Lebens ihr eigenes Überleben zu sichern."
  },
  AvgDialog_118945_Content_11 = {
    Text = "Einige Menschen wählen andere nach ihren eigenen Vorstellungen aus, um ihre ideale neue Welt zu schaffen."
  },
  AvgDialog_118945_Content_12 = {
    Text = "Es gibt auch Menschen, die nur zum Spaß enorme Unruhen auslösen und unzählige Probleme verursachen können."
  },
  AvgDialog_118945_Content_13 = {
    Text = "Du wartest und erwartest ihre Antwort. Denn du hast in einem fernen Traum den Weg gesehen, auf dem sie gekommen ist."
  },
  AvgDialog_118945_Content_14 = {
    Text = "Die heute wahnsinnige Miryam war einst das Mädchen, das sich inmitten des Verderbens dem Priestermission opferte, um die wenigen verbliebenen Familienmitglieder zu beschützen."
  },
  AvgDialog_118945_Content_15 = {
    Text = "Miryam antwortete nicht direkt auf deine Frage. Sie faltete die Hände und betete in Richtung des fernen Horizonts."
  },
  AvgDialog_118945_Content_16 = {
    Text = "“Jeder Fromme wird von meinem Herrn gesegnet...“"
  },
  AvgDialog_118945_Content_17 = {
    Text = "\"Allen, die es wünschen, wird mein Herr gewähren.\""
  },
  AvgDialog_118945_Content_18 = {
    Text = "Als ob sie die Zustimmung des Meeres erhalten hätte, öffnete sie langsam ihre benommenen, violett-schwarzen Augen."
  },
  AvgDialog_118945_Content_19 = {
    Text = "Ich komme zur Wiederbelebung des Göttlichen Reiches, um die Herrlichkeit der Götter wieder auf Erden erscheinen zu lassen."
  },
  AvgDialog_118945_Content_2 = {
    Text = "Für mich ist dieses Gespräch mit Miryam viel entscheidender als ein Sieg."
  },
  AvgDialog_118945_Content_20 = {
    Text = "Was erwartest du also zu sehen, wenn Lemuria wieder in der Welt erscheint?"
  },
  AvgDialog_118945_Content_21 = {
    Text = "“In dem langen Traum der Götter teilen wir beide den ewigen Frieden und das Wohlbefinden.“"
  },
  AvgDialog_118945_Content_22 = {
    Text = "Die Blütezeit von Lemuria kehrt zurück, genau wie es dir zu Lebzeiten vermittelt wurde."
  },
  AvgDialog_118945_Content_23 = {
    Text = "Du hast noch nie einen solchen Glanz erlebt, selbst nicht für einen Tag. Weißt du wirklich, wie man ihn erschafft?"
  },
  AvgDialog_118945_Content_24 = {
    Text = "“Der Wille Gottes wird den Gläubigen den Weg nach Lemuria zeigen.“"
  },
  AvgDialog_118945_Content_25 = {
    Text = "Du bist in dieser Welt wirklich genau so, wie ich es mir vorgestellt habe."
  },
  AvgDialog_118945_Content_26 = {
    Text = "Warum hältst du Murphy in diesem Moment, in dem der Gott bereits geboren ist, so fest in deiner Hand?"
  },
  AvgDialog_118945_Content_3 = {
    Text = "Egal, ob du Miryam nur für einen Moment zum Schwanken bringen kannst, der Geheimgang wird seine Risse zeigen, und sein verborgener “Kern“..."
  },
  AvgDialog_118945_Content_4 = {
    Text = "Ihr habt die Hoffnung, diesen hartnäckigen künstlichen Traum endgültig zu beenden."
  },
  AvgDialog_118945_Content_5 = {
    Text = "Bitte erklären Sie Ihr Anliegen."
  },
  AvgDialog_118945_Content_6 = {
    Text = "Ich komme mit einer Frage."
  },
  AvgDialog_118945_Content_7 = {
    Text = "Miryam, warum möchtest du das Göttliche Reich wiederherstellen?"
  },
  AvgDialog_118945_Content_8 = {
    Text = "Du hast eine sehr interessante Frage gestellt."
  },
  AvgDialog_118945_Content_9 = {
    Text = "Auf meinem Weg im Kampf gegen die Auflösung habe ich viele Menschen kennengelernt."
  },
  AvgDialog_118946_Content_1 = {
    Text = "Flug und Freiheit"
  },
  AvgDialog_118946_Content_10 = {
    Text = "Sie hob ihre blassen Fingerspitzen und drehte das Spinnrad erneut."
  },
  AvgDialog_118946_Content_100 = {
    Text = "Bis die Dunkelheit die Welt verschlingt."
  },
  AvgDialog_118946_Content_11 = {
    Text = "Obwohl ich deinen Namen noch nicht kenne, bitte segne mich, Fremder."
  },
  AvgDialog_118946_Content_12 = {
    Text = "Die Vogelschar flog mit einem Rauschen vorbei und erzeugte Wellen aus weißen Federn.\n Nachdem die Wellen sich gelegt hatten, war die Frau verschwunden."
  },
  AvgDialog_118946_Content_13 = {
    Text = "Du hast Wilhelm schnell einen Überblick über den Gesamtplan gegeben."
  },
  AvgDialog_118946_Content_14 = {
    Text = "Klingt nach einem Plan, um im Chaos zu gewinnen."
  },
  AvgDialog_118946_Content_15 = {
    Text = "Das Ritual ist beendet, die Rebellion bricht aus, und es ist die schwächste Zeit der gesamten Seefahrer-Kirche."
  },
  AvgDialog_118946_Content_16 = {
    Text = "Basierend auf den Hinweisen von Faros müssen wir vielleicht nur die Elfenbeinstatue erlangen, um den Geheimgang zu verlassen."
  },
  AvgDialog_118946_Content_17 = {
    Text = "Murphy mitnehmen, ist das nicht zu kompliziert?"
  },
  AvgDialog_118946_Content_18 = {
    Text = "Wilhelm, der Seniorstudent, hast du mir gesagt, dass die Ereignisse im Geheimgang die reale Welt außerhalb des Geheimgangs beeinflussen könnten."
  },
  AvgDialog_118946_Content_19 = {
    Text = "Wenn das so ist, kann ich Murphy nicht einfach ignorieren..."
  },
  AvgDialog_118946_Content_2 = {
    Text = "Wieder ein Kreislauf."
  },
  AvgDialog_118946_Content_20 = {
    Text = "Goliath hat es auf das Schiff abgesehen, er wird sich nicht um Murphys Flucht kümmern; Miryam ist erschöpft von der Auseinandersetzung mit Goliath und kann ebenfalls nicht verfolgen."
  },
  AvgDialog_118946_Content_21 = {
    Text = "Das ist eine hervorragende Gelegenheit."
  },
  AvgDialog_118946_Content_22 = {
    Text = "William schloss die Augen, schob seine Brille zurecht und seufzte scheinbar resigniert."
  },
  AvgDialog_118946_Content_23 = {
    Text = "Ich höre dir zu."
  },
  AvgDialog_118946_Content_24 = {
    Text = "Wie im letzten Zyklus hast du dich mit Wilhelm im Plattform des Mastes versteckt."
  },
  AvgDialog_118946_Content_25 = {
    Text = "Während Goliath den Aufstand begann, sprangst du hinunter und ergriffst Murphys Handgelenk."
  },
  AvgDialog_118946_Content_26 = {
    Text = "Schnell, komm mit mir, spring aufs Schiff!"
  },
  AvgDialog_118946_Content_27 = {
    Text = "Bist du verrückt? Warum kommst du zurück? Wir können nicht entkommen, lass uns einfach alles ruhig weiterlaufen?"
  },
  AvgDialog_118946_Content_28 = {
    Text = "Murphy versuchte, sich von dir zu befreien, aber dein Beharren war nicht abzulehnen. Ein Ring in hellem Rot erschien an ihrem Handgelenk."
  },
  AvgDialog_118946_Content_29 = {
    Text = "Murphy, die Ruhe, die du wolltest, gibt es schon lange nicht mehr."
  },
  AvgDialog_118946_Content_3 = {
    Text = "Die Vögel über dem Meer schwirren über der Frau, ihr klagender Gesang klingt wie eine Melodie."
  },
  AvgDialog_118946_Content_30 = {
    Text = "Goliath und Caecus planen, das Schiff zu übernehmen, Faros strebt nach der Macht der Elfenbeinstatue, die gesamte Gruppe der Seefahrer ist bereits zerbrochen."
  },
  AvgDialog_118946_Content_31 = {
    Text = "Glaub mir, glaub mir noch einmal. Ich werde dich auf jeden Fall entkommen lassen."
  },
  AvgDialog_118946_Content_32 = {
    Text = "Entkommen, und dann?"
  },
  AvgDialog_118946_Content_33 = {
    Text = "Dann werden wir einen Weg finden, nach Misaq zurückzukehren, und du wirst mit allen zusammen ein Teil von Misaq sein."
  },
  AvgDialog_118946_Content_34 = {
    Text = "Sie sagen oft, dass meine Träume Weissagungen sind. In einem fernen Traum habe ich solche Szenen gesehen..."
  },
  AvgDialog_118946_Content_35 = {
    Text = "Du fühlst, dass die Kraft des Widerstands etwas nachgelassen hat."
  },
  AvgDialog_118946_Content_36 = {
    Text = "Komm, spring mit mir zur rechten Seite des Schiffs... drei, zwei, eins, spring!"
  },
  AvgDialog_118946_Content_37 = {
    Text = "Platsch, Platsch."
  },
  AvgDialog_118946_Content_38 = {
    Text = "Zwei frei springende Fische kehrten in ihr loyalen Meer zurück, während ihre Hände fest miteinander verbunden blieben."
  },
  AvgDialog_118946_Content_39 = {
    Text = "Das Sonnenlicht strömt von der Meeresoberfläche herein und erleuchtet ihr schwebendes Haar und den Schleier im klaren Wasser.\n Ihre rosafarbenen Pupillen blicken dich an, wie in einem stillen Traum."
  },
  AvgDialog_118946_Content_4 = {
    Text = "Keine Sorge, dieses Mal sind wir bestens vorbereitet."
  },
  AvgDialog_118946_Content_40 = {
    Text = "Ihr seid frei."
  },
  AvgDialog_118946_Content_41 = {Text = "Platsch—"},
  AvgDialog_118946_Content_42 = {
    Text = "Ein Ruder sticht in das kristallklare Wasser vor dir."
  },
  AvgDialog_118946_Content_43 = {
    Text = "Du nickst Murphy zu, und die beiden klettert gemeinsam am Ruder."
  },
  AvgDialog_118946_Content_44 = {
    Text = "Hast du es festgehalten?"
  },
  AvgDialog_118946_Content_45 = {
    Text = "Er zog euch aus dem Wasser, und du kletterst am Rand des kleinen Bootes hoch."
  },
  AvgDialog_118946_Content_46 = {
    Text = "Hey, zieh mich mal hoch!"
  },
  AvgDialog_118946_Content_47 = {
    Text = "Was ist los, kannst du nicht selbst hochkommen?"
  },
  AvgDialog_118946_Content_48 = {
    Text = "Reden wir nicht um den heißen Brei herum, ich habe dich noch nicht für die Schuld verantwortlich gemacht, dass die Göttliche Mutter ins Wasser gefallen ist!"
  },
  AvgDialog_118946_Content_49 = {
    Text = "Du ziehst vorsichtig an Murphys Schulter, hebst sie mit genau der richtigen Kraft über die Wasseroberfläche."
  },
  AvgDialog_118946_Content_5 = {
    Text = "Wir wissen, dass das Schiff nach dem Ende des Lotsenrituals kentern wird; wir wissen, dass die Elfenbeinstatue die Macht hat, Träume zu manipulieren."
  },
  AvgDialog_118946_Content_50 = {Text = "Puh—"},
  AvgDialog_118946_Content_51 = {
    Text = "Gut, jetzt können wir richtig reden. Wohin wollen wir gehen?"
  },
  AvgDialog_118946_Content_52 = {
    Text = "Während Goliath und Miryam im Kampf verwickelt sind, steuern wir drei gemeinsam dieses Schiff und verlassen die Grenzen des Geheimgangs."
  },
  AvgDialog_118946_Content_53 = {
    Text = "Dann finden wir gemeinsam den Weg zurück in die ursprüngliche Welt, wo du deinem Selbst aus dieser Welt begegnest und täglich in der Mensa um die kleinen Kuchen kämpfst..."
  },
  AvgDialog_118946_Content_54 = {
    Text = "Puh, das wird eine lange Reise werden."
  },
  AvgDialog_118946_Content_55 = {
    Text = "Na gut, dann erzähl mir mal ordentlich von diesem Ort namens Misaq..."
  },
  AvgDialog_118946_Content_56 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_118946_Content_57 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_118946_Content_58 = {
    Text = "Und dann und dann?"
  },
  AvgDialog_118946_Content_59 = {
    Text = "Dann entdeckte Ramona den Wein, den Lord Dexter in der Ecke ihres Bücherregals versteckt hatte. Um den Wein zu verstecken, hatte er einige Innenseiten seiner Bücher ausgehöhlt."
  },
  AvgDialog_118946_Content_6 = {
    Text = "Wir wissen auch, dass es im unteren Schiffsraum nur ein Rettungsboot gibt. Egal, sobald wir von diesem Kreuzfahrtschiff entkommen, sind wir nicht mehr an Miryam gebunden."
  },
  AvgDialog_118946_Content_60 = {
    Text = "Du bemerkst im Augenwinkel, dass Wilhelm den Kopf hängen lässt, die Stirn runzelt und sich die Schläfen reibt."
  },
  AvgDialog_118946_Content_61 = {
    Text = "Sie war wütend und stürmte mit dem Fechtblatt in das Salon von Frau Sorel!"
  },
  AvgDialog_118946_Content_62 = {Text = "Und dann?"},
  AvgDialog_118946_Content_63 = {
    Text = "Murphy hielt nervös deinen Ärmel fest, während ihr Appetit von den neuartigen Geschichten hochgehängt wurde."
  },
  AvgDialog_118946_Content_64 = {
    Text = "Das Lachen und die Freude im Salon erstarrten plötzlich, alle starrten mit weit aufgerissenen Augen auf diesen ungebetenen Gast!"
  },
  AvgDialog_118946_Content_65 = {
    Text = "Genau so, wie Wilhelm, der Seniorstudent, jetzt!"
  },
  AvgDialog_118946_Content_66 = {Text = "Und..."},
  AvgDialog_118946_Content_67 = {
    Text = "Es gibt Attentäter, es gibt Attentäter! Überall schreien die Leute durcheinander!"
  },
  AvgDialog_118946_Content_68 = {
    Text = "Dein Lächeln erstarrte auf deinem Gesicht."
  },
  AvgDialog_118946_Content_69 = {
    Text = "Hinter Murphy, am Rand des kleinen Bootes, erhob sich plötzlich ein hohes Monster, das aus Millionen von Leichenteilen verschmolzen war und aus dem Meer auftauchte."
  },
  AvgDialog_118946_Content_7 = {
    Text = "Unser Plan ist, dass ich in die Lotsenzeremonie eindringe und Murphy in dem Moment, in dem sie schwach ist, mit ihr ins Meer springe."
  },
  AvgDialog_118946_Content_70 = {Text = "<Big:...>"},
  AvgDialog_118946_Content_71 = {
    Text = "Er öffnete lautlos seinen riesigen Mund, der aus sich windenden Knochen und Schädeln bestand——"
  },
  AvgDialog_118946_Content_72 = {
    Text = "<Red:Verschlinge Murphy lebendig>"
  },
  AvgDialog_118946_Content_73 = {
    Text = "<Shake:Nein... Puppe der faulen Flut... sollte nicht bereits in der Nekropolis sein...>"
  },
  AvgDialog_118946_Content_74 = {
    Text = "In diesem Geheimgang... Goliath manipulierte immer noch die Puppe der faulen Flut."
  },
  AvgDialog_118946_Content_75 = {
    Text = "Seine Kerntruppe kämpft gegen Miryam, daher wurde diese externe Formation ausgesandt, um die Verfolgung aufzunehmen..."
  },
  AvgDialog_118946_Content_76 = {
    Text = "Wir... haben versagt."
  },
  AvgDialog_118946_Content_77 = {
    Text = "<Big:<Shake:...!!!>>"
  },
  AvgDialog_118946_Content_78 = {
    Text = "Der das Verschlingen von Murphy vollzogene Troll hob seinen seltsamen Kopf und gab ein zufriedenes Schmatzen aus seinem Hals von sich."
  },
  AvgDialog_118946_Content_79 = {
    Text = "Die verunreinigte Dunstwolke breitete sich über die Meeresoberfläche aus, das Paradeis war in der Ferne längst nicht mehr sichtbar, nur die Knochenberge drückten überwältigend und verdunkelnd herab."
  },
  AvgDialog_118946_Content_8 = {
    Text = "Wilhelm, der Seniorstudent, wird das Rettungsboot steuern, um mich und Murphy am Schiff zu empfangen. Nachdem ich an Bord bin, werde ich so schnell wie möglich das Geheimnis der Elfenbeinstatue entschlüsseln und den Geheimgang verlassen."
  },
  AvgDialog_118946_Content_80 = {
    Text = "Geh schnell weg!"
  },
  AvgDialog_118946_Content_81 = {
    Text = "Wilhelm umarmte dich fest, der du verloren und verwirrt warst, rollte zur Seite des Schiffes und entging nur mit Mühe dem ersten heftigen Schlag der Knochenschnauze."
  },
  AvgDialog_118946_Content_82 = {
    Text = "Wilhelm, der Seniorstudent, dein Rücken..."
  },
  AvgDialog_118946_Content_83 = {
    Text = "Blut, das tropfende Blut."
  },
  AvgDialog_118946_Content_84 = {
    Text = "Kümmere dich nicht um mich, steig hinauf und durchtrenne die Wirbelsäule der Puppe der faulen Flut!"
  },
  AvgDialog_118946_Content_85 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_118946_Content_86 = {Text = "<Big:...>"},
  AvgDialog_118946_Content_87 = {
    Text = "Die Puppe der faulen Flut stürzt wie ein hoher Turm zusammen, während der blasse Knochenregen in den unendlichen Ozean fällt."
  },
  AvgDialog_118946_Content_88 = {
    Text = "Wie du sagst... Goliaths Stärke wurde im Geheimgang erheblich geschwächt."
  },
  AvgDialog_118946_Content_89 = {
    Text = "Deshalb können wir gerade so widerstehen..."
  },
  AvgDialog_118946_Content_9 = {
    Text = "Die Frau senkte den Kopf, ihre feinen Ponyhaare verdeckten ihren Ausdruck."
  },
  AvgDialog_118946_Content_90 = {
    Text = "Vielleicht liegt es an der schweren Verletzung, dass du Williams Worte nicht mehr hören kannst."
  },
  AvgDialog_118946_Content_91 = {
    Text = "In den zusammengebrochenen Leichentrachten und Knochen ist die Silhouette des Mädchens nicht zu sehen."
  },
  AvgDialog_118946_Content_92 = {
    Text = "Murphy... Murphy!"
  },
  AvgDialog_118946_Content_93 = {
    Text = "Du stürzt auf die schwebenden Skelette zu und gräbst Stück für Stück die aufgestapelten Schädel an der Stelle des Verdauungstraktes auf."
  },
  AvgDialog_118946_Content_94 = {
    Text = "<Yellow:%player%>..."
  },
  AvgDialog_118946_Content_95 = {
    Text = "Nirgends ist Murphy zu finden."
  },
  AvgDialog_118946_Content_96 = {
    Text = "In der Mitte der kreuz und quer liegenden Knochen befindet sich nur ein dünner, leichter schwarzer Schleier."
  },
  AvgDialog_118946_Content_97 = {
    Text = "Du hebst den schwarzen Schleier sanft an, und ein Gefühl der Traurigkeit überkommt dich."
  },
  AvgDialog_118946_Content_98 = {
    Text = "Ich dachte, dieses Mal könnte ich sie unbedingt entkommen lassen..."
  },
  AvgDialog_118946_Content_99 = {
    Text = "Du gibst ein leises Schluchzen von dir. Dann wird das Schluchzen allmählich lauter."
  },
  AvgDialog_118947_Content_1 = {
    Text = "“ParadiesNr.“"
  },
  AvgDialog_118947_Content_10 = {
    Text = "Du nimmst das Blech mit einer Zange heraus, und Murphy greift sofort ungeduldig nach einem kleinen Kuchen, der dampft."
  },
  AvgDialog_118947_Content_11 = {
    Text = "Keine Eile, heiß heiß heiß heiß heiß!"
  },
  AvgDialog_118947_Content_12 = {
    Text = "Murphy schien es völlig ungern loszulassen, sie wechselte mehrmals zwischen der linken und der rechten Hand, bis der Kuchen endlich die richtige Temperatur erreicht hatte."
  },
  AvgDialog_118947_Content_13 = {
    Text = "Probier einen Biss... ich muss es anscheinend nicht sagen."
  },
  AvgDialog_118947_Content_14 = {
    Text = "Bevor du deinen Satz beendet hast, hat Murphy bereits hinein gebissen."
  },
  AvgDialog_118947_Content_15 = {
    Text = "Wie ist es, schmeckt es gut?"
  },
  AvgDialog_118947_Content_16 = {
    Text = "Das Rezept basiert ganz auf deinem Gedächtnis. Um die hungrige junge Dame, die mitten in der Nacht nach Essen verlangt, zu versorgen, hast du mehrmals die Küche von Misaq ausgeliehen."
  },
  AvgDialog_118947_Content_17 = {
    Text = "Hmpf, die Zutaten sind zu einfach, sie können nicht mit dem verglichen werden, was Miryam mir normalerweise anbietet."
  },
  AvgDialog_118947_Content_18 = {
    Text = "Murphy schluckte vorsichtig die Reste in ihrem Mund hinunter und sprach ernsthaft."
  },
  AvgDialog_118947_Content_19 = {
    Text = "Aber wer kann schon leugnen, dass die Kochkünste dieser Göttlichen Mutter erstaunlich sind und das Verfall in Wunder verwandeln können."
  },
  AvgDialog_118947_Content_2 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_118947_Content_20 = {
    Text = "Warm und zart... das ist das köstlichste Essen, das ich je gegessen habe."
  },
  AvgDialog_118947_Content_21 = {
    Text = "Ich probiere auch ein Stück."
  },
  AvgDialog_118947_Content_22 = {
    Text = "William hebt vorsichtig ein Stück mit dem silbernen kleinen Messer auf und steckt es sich in den Mund."
  },
  AvgDialog_118947_Content_23 = {
    Text = "Seniorstudent, wenn ich mich nicht irre, hast du zum Schneiden des Kuchens das Skalpell verwendet, das zuvor bei der Sektion von Nubien benutzt wurde?"
  },
  AvgDialog_118947_Content_24 = {
    Text = "Es wurde bereits gründlich desinfiziert. Die groben Messer und Gabeln, die die Matrosen benutzen, sind wirklich schwer zu essen."
  },
  AvgDialog_118947_Content_25 = {
    Text = "Hätte ich gewusst, hätte ich Doresain in der Nekropolis nach zwei Bestecken fragen sollen...\n Egal, wenn ich darüber nachdenke, ist es schwer zu sagen, was Doresains Besteck schon geschnitten hat..."
  },
  AvgDialog_118947_Content_26 = {
    Text = "Ihr schlemmt und lacht, während ihr euch Sahne ins Gesicht schmiert."
  },
  AvgDialog_118947_Content_27 = {
    Text = "(Wenn das ihre letzte Erinnerung ist...)"
  },
  AvgDialog_118947_Content_28 = {Text = "Bang—"},
  AvgDialog_118947_Content_29 = {
    Text = "Ein lauter Knall durchbrach die seltene Stille, und die Küche, in der ihr euch befindet, begann plötzlich unaufhörlich heftig zu beben."
  },
  AvgDialog_118947_Content_3 = {
    Text = "In ein paar Minuten."
  },
  AvgDialog_118947_Content_30 = {
    Text = "Was ist los?!"
  },
  AvgDialog_118947_Content_31 = {
    Text = "Goliath raubte das Kraftwerk, Miryam leistete heftigen Widerstand, und das Kraftwerk explodierte."
  },
  AvgDialog_118947_Content_32 = {
    Text = "Du antwortest gelassen."
  },
  AvgDialog_118947_Content_33 = {
    Text = "Mit anderen Worten, das Schiff wird sinken."
  },
  AvgDialog_118947_Content_34 = {
    Text = "Das Schiff wird sinken, hast du gar keine Reaktion?"
  },
  AvgDialog_118947_Content_35 = {
    Text = [[
Murphy, ich muss mit dir reden.
Dieses Schiff muss sinken.]]
  },
  AvgDialog_118947_Content_36 = {
    Text = "Ich habe fünf Zyklen durchlebt, in jedem Zyklus plant Goliath Raubüberfälle auf Schiffe."
  },
  AvgDialog_118947_Content_37 = {
    Text = "Dieser Prozess wird eine Explosion im Kraftwerk auslösen, danach wird das Schiff von einem Wirbel in die Tiefen des Meeres gezogen."
  },
  AvgDialog_118947_Content_38 = {Text = "Also?"},
  AvgDialog_118947_Content_39 = {
    Text = "Ich habe ständig nach Möglichkeiten gesucht, die Zerstörung dieses Schiffs zu verhindern, aber meine Überlegungen waren fehlerhaft."
  },
  AvgDialog_118947_Content_4 = {
    Text = "Ihr starrt auf den Ofen, während der geknetete Teig Stück für Stück aufgeht, und euer erwartungsvolles Herz bläht sich leicht mit der fluffigen Kurve auf."
  },
  AvgDialog_118947_Content_40 = {
    Text = "Dieses Schiff sollte sinken... Nur wenn es sinkt, kann es dir den Weg zur Freiheit ebnen."
  },
  AvgDialog_118947_Content_41 = {
    Text = "Krach——"
  },
  AvgDialog_118947_Content_42 = {
    Text = "Der Schiffsrumpf zuckte und zitterte, als wäre er von einem Blitz getroffen worden, als ob ein riesiges Tier in der Explosion des Schmerzes außer Kontrolle geriet und zuckte."
  },
  AvgDialog_118947_Content_43 = {
    Text = "Gut, jetzt müssen wir nicht so viel erklären, komm schnell mit mir."
  },
  AvgDialog_118947_Content_44 = {
    Text = "Noch etwas später und es wird nichts mehr rechtzeitig sein."
  },
  AvgDialog_118947_Content_45 = {
    Text = "Du ziehst Murphy und gehst den kleinen Weg entlang, den Wilhelm dir gezeigt hat."
  },
  AvgDialog_118947_Content_46 = {
    Text = "Hey, willst du wirklich, dass die Dame die Leiter hochklettert? Vor den Fremden so unbeholfen zu sein, ist doch zu peinlich?!"
  },
  AvgDialog_118947_Content_47 = {
    Text = "Du gehst zuerst runter und wartest auf mich, ich werde dich auf keinen Fall anblicken."
  },
  AvgDialog_118947_Content_48 = {
    Text = "Die Augen gewöhnten sich allmählich an die Dunkelheit, in der Ecke des Frachtraums lag einsam ein kleines Boot."
  },
  AvgDialog_118947_Content_49 = {
    Text = "Das ist der Fluchtweg, den Goliath für sich vorbereitet hat und den wir gefunden haben."
  },
  AvgDialog_118947_Content_5 = {
    Text = "Der Duft von Eiermilch breitet sich aus, die Speicheldrüsen nehmen es schneller wahr als das Gehirn, und der Appetit lässt deinen Bauch grummeln."
  },
  AvgDialog_118947_Content_50 = {
    Text = "Dieser schlaue Kerl hat fast alle Rettungsboote zerstört, bevor er den Aufstand begann, um sicherzustellen, dass nur er entkommen kann."
  },
  AvgDialog_118947_Content_51 = {
    Text = "Hier, der Ersatzschlüssel, den ich Wilhelm besorgen ließ. Jetzt, geh an Bord."
  },
  AvgDialog_118947_Content_52 = {
    Text = "Moment mal, was redest du da für einen Unsinn, ich habe nie zugestimmt, mit dir zu entkommen——"
  },
  AvgDialog_118947_Content_53 = {
    Text = "Ich habe auch nicht gesagt, dass ich mit dir an Bord gehe. Hier gibt es nur ein einziges Rettungsboot. Du steigst allein ein und gehst an Land."
  },
  AvgDialog_118947_Content_54 = {Text = "!"},
  AvgDialog_118947_Content_55 = {
    Text = "Wenn wir einfach so gehen, wird Miryam nicht aufgeben. Eines Tages wird der Schatten der Seefahrer dich wieder einholen."
  },
  AvgDialog_118947_Content_56 = {
    Text = "Ich muss hier bleiben, um sicherzustellen, dass die Seefahrer und der Heilige Embryo für immer im Aequor versinken."
  },
  AvgDialog_118947_Content_57 = {
    Text = "Das ist auch, was sie sich wünschen, die Rückkehr in ihr ewiges Heimatland und das Göttliche Reich, nicht wahr?"
  },
  AvgDialog_118947_Content_58 = {Text = "Pff—"},
  AvgDialog_118947_Content_59 = {
    Text = "Murphy lächelte unter Tränen."
  },
  AvgDialog_118947_Content_6 = {
    Text = "Die verzerrten, feuchten und hastigen Schritte der Seefahrer hallten gelegentlich über den Holzboden, während die dünne Tür zwei Welten voneinander trennte. In diesem kleinen Raum herrschte eine übermäßig einfache Glückseligkeit und Wärme, die wie ein Trugbild erschienen."
  },
  AvgDialog_118947_Content_60 = {
    Text = "Vor dem Aufbruch hatte ich bereits alles geplant."
  },
  AvgDialog_118947_Content_61 = {
    Text = "Wenn ich dich entkommen lassen kann, dann wäre das das beste Ende."
  },
  AvgDialog_118947_Content_62 = {
    Text = "Wenn ich es nicht kann... zumindest habe ich mein Bestes getan, um dir einen Tag wiederherzustellen, den der Murphy, den ich kenne, mögen würde."
  },
  AvgDialog_118947_Content_63 = {
    Text = "Wir kennen uns noch nicht lange und ich habe nicht genug über dich erfahren. Ich hoffe, es gefällt dir auch."
  },
  AvgDialog_118947_Content_64 = {
    Text = "Murphy stellte sich auf die Zehenspitzen und gab dir eine sanfte Umarmung."
  },
  AvgDialog_118947_Content_65 = {
    Text = "Ich erinnere mich, dass du gesagt hast, du würdest die Wiedergeburt immer wieder erleben."
  },
  AvgDialog_118947_Content_66 = {
    Text = "Diesmal wird es nicht das Ende sein."
  },
  AvgDialog_118947_Content_67 = {
    Text = "Beim nächsten Mal, nimm mich mit, okay?"
  },
  AvgDialog_118947_Content_68 = {
    Text = "<Red:Es gibt kein nächstes Mal.>\nEin saurer Geschmack steigt dir in die Nase."
  },
  AvgDialog_118947_Content_69 = {
    Text = "Ich verspreche dir. Wir entkommen zusammen."
  },
  AvgDialog_118947_Content_7 = {
    Text = "Sieh mal, die Haut hat sich bereits verfärbt, es kann serviert werden!"
  },
  AvgDialog_118947_Content_70 = {
    Text = "Dunkle Wolken hingen am Himmel, und unter dem Bug des Schiffes standen Miryam und Goliath einander gegenüber."
  },
  AvgDialog_118947_Content_71 = {
    Text = "Gib mir das kleine Mädchen und die Elfenbeinstatue, dann kann ich dir, wie du einst gedroht hast, den Tod voller Ruhm schenken."
  },
  AvgDialog_118947_Content_72 = {
    Text = "Redet hier nicht so einen Unsinn, ihr habt doch die Göttermutter geraubt und diesen Aufstand ausgelöst, oder?"
  },
  AvgDialog_118947_Content_73 = {
    Text = "Ihr müsst euch nicht mehr streiten, Murphy ist nicht mehr auf diesem Schiff.\nSie ist den Klauen entkommen und weit weg vom Strudel."
  },
  AvgDialog_118947_Content_74 = {
    Text = "Ein Gefühl der unerklärlichen Erleichterung überkam mich."
  },
  AvgDialog_118947_Content_75 = {
    Text = "Bist du dieser Typ, der sie rausgebracht hat? Du hast wirklich ein bisschen Mut."
  },
  AvgDialog_118947_Content_76 = {
    Text = "Wenn ihr bereit seid, hier einen großen Kampf auszutragen, hätte ich nichts dagegen, davon zu profitieren."
  },
  AvgDialog_118947_Content_77 = {
    Text = "Es bist du, der unbedeutende Fremde..."
  },
  AvgDialog_118947_Content_78 = {
    Text = "Glaubst du, dass du mit dem Schutz der göttlichen Mutter nach Belieben handeln kannst?"
  },
  AvgDialog_118947_Content_79 = {
    Text = "Miryam, ich möchte mit dir reden."
  },
  AvgDialog_118947_Content_8 = {Text = "...Okay!"},
  AvgDialog_118947_Content_80 = {
    Text = "Es geht nicht darum, unhöflich und willkürlich Krieg zu erklären, sondern mit einem Gespräch zu beginnen, oder?"
  },
  AvgDialog_118947_Content_81 = {
    Text = "Ich bin auch sehr neugierig, welcher unüberlegene Geselle du bist, dass du den Ruf der Göttlichen Mutter erhälst und dennoch so unüberlegt und furchtlos handeln kannst."
  },
  AvgDialog_118947_Content_82 = {
    Text = "Wenn du den Apostel Gottes aufrichtig um eine Antwort bittest, werde ich dir möglicherweise den Willen Gottes gewähren."
  },
  AvgDialog_118947_Content_83 = {
    Text = "<Red:<Shake:Aber jetzt, ertrage zuerst den Zorn der Seefahrer!>>"
  },
  AvgDialog_118947_Content_9 = {
    Text = "Der Duft von Eiermilch strömt hervor."
  },
  AvgDialog_118948_Content_1 = {Text = "Wirbel"},
  AvgDialog_118948_Content_10 = {
    Text = "“Knack!“ machte es, und der silberne Faden riss sofort."
  },
  AvgDialog_118948_Content_11 = {
    Text = "Caecus merkt nichts davon, sondern mustert dich nur argwöhnisch."
  },
  AvgDialog_118948_Content_12 = {
    Text = "Freund, was sagst du, Freund?"
  },
  AvgDialog_118948_Content_13 = {
    Text = "Das muss eine verführerische Technik sein! Glaubt nicht an {Male=er,Female=sie}, mein Herr Caecus!"
  },
  AvgDialog_118948_Content_14 = {
    Text = "Befehl, ja, Befehl..."
  },
  AvgDialog_118948_Content_15 = {
    Text = "Caecus atmete tief ein, als würde der Mut neu in seinen Körper fließen, und er hob plötzlich den Kopf."
  },
  AvgDialog_118948_Content_16 = {
    Text = "Ich weiß nur, dass die Seefahrer dich vorübergehend untergebracht haben, das bedeutet nicht, dass du beliebig Zugang zu wichtigen Orten hast."
  },
  AvgDialog_118948_Content_17 = {
    Text = "Befolge den Befehl von Herrn Goliath, unbefugte Personen dürfen das Kraftwerk nicht betreten!"
  },
  AvgDialog_118948_Content_2 = {
    Text = "Schau dorthin, es sieht so aus, als ob jemand das Kraftwerk bewacht."
  },
  AvgDialog_118948_Content_3 = {
    Text = "Mehrere gebeugte Gestalten wandern umher, und unter ihnen hält ein aufrechter Junge mit einer membranartigen Speer vorsichtig die Umgebung im Blick und ist wachsam gegenüber dem Rascheln des Windes im Gras."
  },
  AvgDialog_118948_Content_4 = {
    Text = "Seid alle vorsichtig! Die wichtige Aufgabe, die Herr Goliath angeordnet hat, darf auf keinen Fall schiefgehen..."
  },
  AvgDialog_118948_Content_5 = {Text = "Caecus!"},
  AvgDialog_118948_Content_6 = {
    Text = "Hmm, du bist..."
  },
  AvgDialog_118948_Content_7 = {
    Text = "Du versuchst, den Silberschlüssel zu aktivieren, um dich mit seinem Bewusstsein zu verbinden und eure vergangenen Erinnerungen zu wecken."
  },
  AvgDialog_118948_Content_8 = {
    Text = "Die silbernen Illusionslichter tentakeln sich aus, kriechen entlang der schuppigen Muster seines Körpers und dringen in sein Rückenmark ein..."
  },
  AvgDialog_118948_Content_9 = {
    Text = "Caecus, ich bin dein Freund, darf ich hinter dir eintreten..."
  },
  AvgDialog_118949_Content_1 = {
    Text = "Entschuldigung, Lord Goliath..."
  },
  AvgDialog_118949_Content_10 = {
    Text = "Aber jetzt ist der entscheidende Moment des Plans, und die Variablen sollten so gering wie möglich sein."
  },
  AvgDialog_118949_Content_11 = {
    Text = "Halt hier für immer den Mund, kleiner Kerl."
  },
  AvgDialog_118949_Content_12 = {
    Text = "Herr Goliath, ich kämpfe an deiner Seite!"
  },
  AvgDialog_118949_Content_13 = {
    Text = "Nicht nötig, solche schwachen Dinge, hier gibt es nicht genug Platz für uns beide."
  },
  AvgDialog_118949_Content_14 = {
    Text = "<Small:Aber ich...>"
  },
  AvgDialog_118949_Content_15 = {
    Text = "Caecus murmelte leise, aber die gerade verlorene Schlacht ließ ihn erkennen, dass er keine Position mehr hatte, um weiter zu klagen, und so verstummte er und trat einen Schritt zurück."
  },
  AvgDialog_118949_Content_16 = {
    Text = "Caecus, der Junge."
  },
  AvgDialog_118949_Content_17 = {Text = "Hm?"},
  AvgDialog_118949_Content_18 = {
    Text = "Goliath sah nicht zurück."
  },
  AvgDialog_118949_Content_19 = {
    Text = "Gib nicht auf, du bist die Person, die ich ausgewählt habe. Sobald wir diese Angelegenheit erledigt haben, werde ich dir 500 weitere Trainingseinheiten hinzufügen."
  },
  AvgDialog_118949_Content_2 = {
    Text = "Hm, weniger Aufregung."
  },
  AvgDialog_118949_Content_20 = {Text = "Ah... Ja!"},
  AvgDialog_118949_Content_21 = {
    Text = "Faros, bist du bereit?"
  },
  AvgDialog_118949_Content_22 = {
    Text = "Egal, ob es darum geht, eine Treppe zum Göttlichen Reich zu errichten... Faros hört immer auf Ihre Befehle."
  },
  AvgDialog_118949_Content_3 = {
    Text = "Goliath trat langsam heraus und hielt das Messer kopfüber, während die gezahnte Klinge ein kreischendes Geräusch auf dem Boden verursachte."
  },
  AvgDialog_118949_Content_4 = {
    Text = "Mit diesem kleinen Geräusch könnt ihr nichts anfangen, das ist wirklich eine Schande für das Volk der Philistinen."
  },
  AvgDialog_118949_Content_5 = {
    Text = "Entschuldigung, ich..."
  },
  AvgDialog_118949_Content_6 = {
    Text = "Gugu, Herr Goliath, macht Caecus keinen Vorwurf. Dieser unbekannte Typ wird unsichtbare große Monster beschwören!"
  },
  AvgDialog_118949_Content_7 = {
    Text = "Noch einer... Hey, kleiner Kerl, bist du es."
  },
  AvgDialog_118949_Content_8 = {
    Text = "Lass die Nekropolis sein, hier gibt es keinen Platz für dich, um dich auszutoben."
  },
  AvgDialog_118949_Content_9 = {
    Text = "Wenn wir uns ein wenig später treffen, können wir vielleicht etwas Zeit finden, um uns zu setzen und zu plaudern."
  },
  AvgDialog_118950_Content_1 = {
    Text = "Der Himmel brennt."
  },
  AvgDialog_118950_Content_10 = {
    Text = "Eine rote Blutspur zieht sich hinter ihm entlang und verschmilzt mit der Holzmaserung des Decks."
  },
  AvgDialog_118950_Content_11 = {
    Text = "<Red:Stirb, Bastard, Abweichler!>"
  },
  AvgDialog_118950_Content_12 = {
    Text = "Der Priester mit den weit aufgerissenen Augen hob den Speer, der dem Jungen gehörte, hoch und stach präzise und grausam in seinen Rücken. Die scharfe Speerspitze durchbohrte den Körper und nagelte den Jungen fest auf das Deck."
  },
  AvgDialog_118950_Content_13 = {
    Text = "Der Junge zuckte kurz zusammen und blieb dann einen Schritt entfernt vom Mann stehen."
  },
  AvgDialog_118950_Content_14 = {
    Text = "Haha, hahahaha!"
  },
  AvgDialog_118950_Content_15 = {
    Text = "Oh mein Herr, großer mein Herr, haben Sie es gesehen? Dies ist das Sakrament, das ich Ihnen und der Göttlichen Mutter darbringe!"
  },
  AvgDialog_118950_Content_16 = {
    Text = "Die von Blut besudelte Miryam blickte aus der Ferne auf dieses Höllenbild, lachte überheblich gen Himmel und die zerrissene Priesterrobe flatterte im Feuer."
  },
  AvgDialog_118950_Content_17 = {
    Text = "<Shake:Möge Ihr Göttliches Reich erneut aus der Tiefe aufsteigen, möge Ihr Wille bald wieder auf der Erde geschehen!>"
  },
  AvgDialog_118950_Content_18 = {
    Text = "Der Hauptopfer-Blick durchstreifte ihr Territorium, glitt über Faros, der von der riesigen Klinge in zwei Hälften zerschlagen wurde, über die beiden schwer verletzten Ermittler, die sich nicht rühren konnten, und verweilte auf dem Mädchen, dessen schwarzer Schleier mit Blut und Gift durchtränkt war."
  },
  AvgDialog_118950_Content_19 = {
    Text = "Göttliche Mutter, komm zu mir. Ich habe alle Abtrünnigen, die das Licht verlassen haben, und die verfluchten Sünder, die die Götter beleidigt haben, bestraft!"
  },
  AvgDialog_118950_Content_2 = {
    Text = "Das Meer brennt."
  },
  AvgDialog_118950_Content_20 = {
    Text = "Der beschädigte Schiffskörper hat durch das Eindringen von Wasser das Gleichgewicht verloren, die Hälfte des Schiffs ist bereits unter die Wasseroberfläche gesunken, aber sie merkt es nicht."
  },
  AvgDialog_118950_Content_21 = {
    Text = "<Red:<Shake:Nun werden du und ich das Unsterbliche des Göttlichen Reiches erben, bis der nächste Moment der Sterne richtig steht, und sein heiliger Name in der ganzen Welt verkündet wird!>>"
  },
  AvgDialog_118950_Content_22 = {
    Text = "An der schrägen Spitze des Schiffs, die wie eine Guillotine wirkt, streckte Miryam ihre blutverschmierte Hand von oben herab aus."
  },
  AvgDialog_118950_Content_23 = {
    Text = "<Shake:Nein, nein, nicht... nicht...>"
  },
  AvgDialog_118950_Content_24 = {
    Text = "Murphys Beine gaben nach und sie kniete auf dem Boden. \n Ihr zierlicher Körper hatte seine frühere Anmut völlig verloren und zitterte im Schein des Feuers."
  },
  AvgDialog_118950_Content_25 = {
    Text = "<Shake:Es tut mir leid, ich sollte nicht... ich sollte nicht fliehen wollen...>"
  },
  AvgDialog_118950_Content_26 = {
    Text = "Tränen rollen und hinterlassen fleckige Wasserflecken auf dem Deck, die dann von der Hitze der Flammen trocken geleckt werden."
  },
  AvgDialog_118950_Content_27 = {
    Text = "<Red:<Shake:Ich hätte es wissen müssen, das ist mein Schicksal, dem ich nicht ausweichen und dem ich nicht entkommen kann...>>"
  },
  AvgDialog_118950_Content_28 = {
    Text = "Murphy... so ist es nicht, Murphy, es gibt noch eine Chance..."
  },
  AvgDialog_118950_Content_29 = {
    Text = "Du bist ungeduldig und möchtest das Mädchen trösten, doch dein Körper verrät deinen Willen."
  },
  AvgDialog_118950_Content_3 = {
    Text = "Nein, so ist es nicht... nur dein Sichtfeld brennt. \n Tod und Verzweiflung umhüllen das herrenlose Land über diesem Ozean."
  },
  AvgDialog_118950_Content_30 = {
    Text = "Die heftigen Schmerzen in deinem Knöchel reißen an jedem deiner Sinne, die schweren Verletzungen, die du im Kampf erlitten hast, halten dich fest an Ort und Stelle, und du kannst dich keinen Zentimeter bewegen."
  },
  AvgDialog_118950_Content_31 = {
    Text = "Entschuldigung."
  },
  AvgDialog_118950_Content_32 = {
    Text = "Die Wunde, aus der Blut floss, ignorierend, stand das Mädchen ruhig auf."
  },
  AvgDialog_118950_Content_33 = {
    Text = "Der Schmerz konnte sie nicht mehr aufhalten, ohne Zögern, ohne Illusionen und ohne Bedauern."
  },
  AvgDialog_118950_Content_34 = {
    Text = "Über die Leichenschaukel, über das Feuermeer. \n Sie ging mit bedächtigen Schritten, Schritt für Schritt auf den Priester zu."
  },
  AvgDialog_118950_Content_35 = {
    Text = "Nein... es kann hier nicht enden..."
  },
  AvgDialog_118950_Content_36 = {
    Text = "William... Wilhelm, der Seniorstudent...! Kannst du dich noch bewegen?"
  },
  AvgDialog_118950_Content_37 = {
    Text = "Was möchtest du... tun?"
  },
  AvgDialog_118950_Content_38 = {
    Text = "Wilhelm liegt in einer Blutlache und schnauft schwer."
  },
  AvgDialog_118950_Content_39 = {
    Text = "<Red:<Big:...töte mich, starte den Kreislauf neu.>>"
  },
  AvgDialog_118950_Content_4 = {
    Text = "Die Kettenexplosion riss das Kraftwerk auf, das brennende Deck wölbte sich in der Verzerrung."
  },
  AvgDialog_118950_Content_40 = {
    Text = "Nein, warum..."
  },
  AvgDialog_118950_Content_41 = {
    Text = "Ich kann nicht zulassen, dass diese Welt zum Ende wird... Ich kann so ein Ende nicht akzeptieren..."
  },
  AvgDialog_118950_Content_42 = {
    Text = "Beeil dich, ich kann mich nicht mehr bewegen..."
  },
  AvgDialog_118950_Content_43 = {
    Text = "Wilhelms mechanischer Arm war bereits vom Körper getrennt, und er streckte mühsam den noch beweglichen Arm aus, um den Dolch zu greifen, den Miryam neben sich geworfen hatte."
  },
  AvgDialog_118950_Content_44 = {
    Text = "Entschuldigung, ich kann dir in diesem Moment nicht mein Gesicht zeigen..."
  },
  AvgDialog_118950_Content_45 = {
    Text = "Dann kommt ein stechender Schmerz aus dem linken unteren Rücken."
  },
  AvgDialog_118950_Content_46 = {
    Text = "Komm nicht näher!"
  },
  AvgDialog_118950_Content_47 = {
    Text = "Hohepriester, fangt diesen Kerl lebend, lasst {Male=er,Female=sie} nicht sterben!"
  },
  AvgDialog_118950_Content_48 = {
    Text = "Miryam gab den Befehl, und ein weiterer Dreizack durchbohrte Wilhelms Brust. Du blicktest schockiert zurück und sahst nur eine goldene Haarsträhne, die sanft herabhing."
  },
  AvgDialog_118950_Content_49 = {
    Text = "Der Fischmenschpriester drehte sich seltsam im Kreis und lachte herzlich."
  },
  AvgDialog_118950_Content_5 = {
    Text = "Die einst an deiner Seite kämpfenden Gefährten und die erbitterten Feinde liegen ununterscheidbar in der kochend heißen, blutroten Pfütze."
  },
  AvgDialog_118950_Content_50 = {
    Text = "Grr, hehe, was auch immer du tun möchtest, jetzt ist es nicht möglich!"
  },
  AvgDialog_118950_Content_51 = {
    Text = "Das Herz schmerzt mehr als ein Schnitt mit dem Messer, die blutenden Gliedmaßen sind kalt und stechen bis ins Mark."
  },
  AvgDialog_118950_Content_52 = {
    Text = "<Red:Du musst sterben>, du musst zum nächsten Kreislauf gehen."
  },
  AvgDialog_118950_Content_53 = {
    Text = "<Red:<Shake:Ich... werde es bestimmt...>>"
  },
  AvgDialog_118950_Content_54 = {
    Text = "Halt den Dolch mit einem Schiffsbrett auf"
  },
  AvgDialog_118950_Content_55 = {
    Text = "Der Dolch dringt Stück für Stück in deinen Körper ein, gefolgt von einem Schmerz, der bis ins Mark geht."
  },
  AvgDialog_118950_Content_56 = {
    Text = "Mit Kraft nach hinten fallen"
  },
  AvgDialog_118950_Content_57 = {
    Text = "Die scharfe Klinge durchbohrt deine Brust, das Gefühl der Nichtigkeit des vergehenden Bewusstseins umhüllt dein Sichtfeld."
  },
  AvgDialog_118950_Content_58 = {
    Text = "<Shake:Murphy... Wilhelm... bitte wartet auf mich im nächsten Kreislauf.>"
  },
  AvgDialog_118950_Content_59 = {
    Text = "<Yellow:Wir werden auf jeden Fall... entkommen.>"
  },
  AvgDialog_118950_Content_6 = {
    Text = "<Shake:Herr Goliath, es tut mir leid, wenn ich nur ein wenig stärker wäre...>"
  },
  AvgDialog_118950_Content_7 = {
    Text = "Der schwer verletzte Junge zieht seinen beschädigten Körper mühsam über den rauen Boden, während er mit seinen zehn Fingern verzweifelt gräbt und sich dem schlafenden Mann nähert."
  },
  AvgDialog_118950_Content_8 = {
    Text = "<Shake:Herr Goliath...>"
  },
  AvgDialog_118950_Content_9 = {
    Text = "Egal wie oft er ihn ruft, der Mann, der seine Wut verloren hat, rührt sich nicht."
  },
  AvgDialog_118951_Content_1 = {
    Text = "Also hast du mich hereingelegt, um was zu tun?"
  },
  AvgDialog_118951_Content_10 = {
    Text = "Mach etwas, das nichts mit der Göttlichen Mutter, den Lehren oder den Opfern zu tun hat."
  },
  AvgDialog_118951_Content_11 = {
    Text = "Ich weiß, dass du zwar ständig über diese Dinge sprichst, aber das, was du wirklich magst, sind nicht diese."
  },
  AvgDialog_118951_Content_12 = {
    Text = "Sag nicht so viel, nimm das schnell!"
  },
  AvgDialog_118951_Content_13 = {
    Text = "Das, das ist?"
  },
  AvgDialog_118951_Content_14 = {
    Text = "Schnelles Rühren, in eine Richtung!"
  },
  AvgDialog_118951_Content_15 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_118951_Content_16 = {
    Text = "Dann muss Mehl hinzugefügt werden! Backpulver! Ein wenig Salz!"
  },
  AvgDialog_118951_Content_17 = {
    Text = "Wilhelm, der Seniorstudent, solltest du dich auch nicht langweilen? Geh und hilf, die Butter zu schmelzen!"
  },
  AvgDialog_118951_Content_18 = {Text = "...Gut."},
  AvgDialog_118951_Content_19 = {
    Text = "Wilhelm ging weg und spielte geduldig den chaotischen, aber pflichtbewussten Küchenhelfer."
  },
  AvgDialog_118951_Content_2 = {
    Text = "Komm, lass Wilhelm, den Seniorstudenten, dir einen Zauber zeigen!"
  },
  AvgDialog_118951_Content_20 = {
    Text = "Endlich habt ihr den vorbereiteten Teig in den Ofen geschoben."
  },
  AvgDialog_118951_Content_21 = {
    Text = "Murphy starrte auf den Ofen und war in Gedanken versunken."
  },
  AvgDialog_118951_Content_22 = {
    Text = "Ich erinnere mich an einige Dinge von vor langer Zeit..."
  },
  AvgDialog_118951_Content_23 = {Text = "Hm?"},
  AvgDialog_118951_Content_24 = {
    Text = "Das war, als wir noch in der Antarktis-Basis waren. Ich entdeckte einen Altar in der Bergschlucht, auf dem viele kleine Steinskulpturen waren."
  },
  AvgDialog_118951_Content_25 = {
    Text = "Ich habe Mama... Miryam gebeten, mir ein kleines Messer und einige Holzstücke zu geben, ich möchte einige Holzschnitzereien machen."
  },
  AvgDialog_118951_Content_26 = {
    Text = "Nach langer Zeit gab sie mir nur ein stumpfes kleines Messer und sagte, sie mache sich Sorgen, dass der “heilige Körper der Göttlichen Mutter“ beschädigt wird."
  },
  AvgDialog_118951_Content_27 = {
    Text = "Ich habe das Gefühl, dass mein Körper mir nicht gehört, und natürlich gehört er auch nicht ihr. Wir scheinen beide wie ein Steinziegel aus diesem Göttlichen Reich zu sein, der an seinem Platz festgeklebt ist und sich nicht bewegen kann."
  },
  AvgDialog_118951_Content_28 = {
    Text = "Ich sah einige Holzschnitzereien an deinem Nachttisch."
  },
  AvgDialog_118951_Content_29 = {
    Text = "Nun, ich habe heimlich Goliath gebeten, mir einen Ölschiefer zu besorgen."
  },
  AvgDialog_118951_Content_3 = {
    Text = "Alles wurde gemäß der Liste abgeholt, bitte überprüfen Sie es."
  },
  AvgDialog_118951_Content_30 = {
    Text = "Ich habe viel Mühe aufgewendet, um die Klinge so weit zu schleifen, dass sie Holz schneiden kann."
  },
  AvgDialog_118951_Content_31 = {
    Text = "Ich habe viele Tage lang geschnitzt und mich bemüht, die Details meiner Vorstellung wiederherzustellen."
  },
  AvgDialog_118951_Content_32 = {
    Text = "Als ich schließlich zufrieden war, gab ich es Miryam..."
  },
  AvgDialog_118951_Content_33 = {
    Text = "Weißt du, was sie gesagt hat?"
  },
  AvgDialog_118951_Content_34 = {
    Text = "Miryam... sie sagt, du schnitzt schlecht, Verfluchung der Götter?"
  },
  AvgDialog_118951_Content_35 = {
    Text = "Du versuchst, Miryams Denkweise zu ergründen und gibst vorsichtig eine Vermutung ab."
  },
  AvgDialog_118951_Content_36 = {Text = "Nein."},
  AvgDialog_118951_Content_37 = {
    Text = "Sie hat nicht einmal hingesehen, sondern nur gesagt, dass sie, wenn ich solche Statuen mag, den besten Bildhauer beauftragen kann, um sie mir täglich zu schnitzen."
  },
  AvgDialog_118951_Content_38 = {
    Text = "Murphy lachte wahnsinnig, unbeschreibliche Schmerzen und Verspotten strömten aus ihrem starren Lächeln heraus."
  },
  AvgDialog_118951_Content_39 = {
    Text = "Ich bin das Kind der Götter und auch der Leib der Götter. Was immer ich will, kann ich einfach durch das Heben meiner Hand besitzen."
  },
  AvgDialog_118951_Content_4 = {
    Text = "William öffnete nacheinander die Dutzenden von Taschen in seiner Brust, seinem Rücken und seinen Armen, groß und klein."
  },
  AvgDialog_118951_Content_40 = {
    Text = "Da ich bereits alles habe, ist es natürlich eine Kleinigkeit, eine Holzfigur zu schnitzen."
  },
  AvgDialog_118951_Content_41 = {
    Text = "Sie lachte, lachte, und ohne es zu merken, liefen ihr die Tränen über das Gesicht. Die unerwarteten Tränen rannen schnell über ihre Wangen, die sich durch das herzliche Lachen verzogen hatten."
  },
  AvgDialog_118951_Content_42 = {
    Text = "Ich habe deine Werke gesehen, die du auf dem Nachttisch platziert hast, dein Handwerk ist wirklich gut."
  },
  AvgDialog_118951_Content_43 = {
    Text = "Gut und schlecht, was spielt das schon für eine Rolle..."
  },
  AvgDialog_118951_Content_44 = {
    Text = "Murphy, von nun an kannst du schnitzen, wie du willst."
  },
  AvgDialog_118951_Content_45 = {
    Text = "Dann gehen wir zusammen kleine Kuchen machen und gemeinsam die Blumenarrangements studieren."
  },
  AvgDialog_118951_Content_46 = {
    Text = "Ich werde einen Weg finden, um in meine Welt zurückzukehren, und ich werde dir den Murphy vorstellen, den ich kenne, damit ihr zusammen frei alles tun könnt, was ihr wollt."
  },
  AvgDialog_118951_Content_47 = {
    Text = "Murphy wischte sich die Tränen vom Gesicht und hob dann den Kopf, um dir ein strahlendes Lächeln zu schenken, das du noch nie zuvor gesehen hast."
  },
  AvgDialog_118951_Content_48 = {
    Text = "Gut, das hast du mir versprochen."
  },
  AvgDialog_118951_Content_49 = {
    Text = "Absolut, auf keinen Fall versäumen."
  },
  AvgDialog_118951_Content_5 = {
    Text = "Danke an den großartigen Gott der Magie, Wilhelm, den Seniorstudenten, für die Rohstoffe, die er uns aus der Küche gestohlen hat."
  },
  AvgDialog_118951_Content_50 = {
    Text = "Das ist eine Geschichte, die nichts mit der Göttlichen Mutter zu tun hat."
  },
  AvgDialog_118951_Content_51 = {
    Text = "Aber sie scheint in ihrem Leben noch nie so glücklich gewesen zu sein."
  },
  AvgDialog_118951_Content_6 = {
    Text = "Es gibt Mehl, Eier, Zitrone, Honig, Zucker, Backpulver und Butter."
  },
  AvgDialog_118951_Content_7 = {
    Text = "Das ist ganz vollständig! Die Taschen der Seemannskleidung sind wirklich praktisch."
  },
  AvgDialog_118951_Content_8 = {
    Text = "Ich verstehe immer noch nicht... warum?"
  },
  AvgDialog_118951_Content_9 = {
    Text = "Möchtest du nicht versuchen, deinen eigenen Kuchen zu backen, den du normalerweise isst?"
  },
  AvgDialog_118952_Content_1 = {
    Text = "Göttliche Geburt - Sieben Tage"
  },
  AvgDialog_118952_Content_10 = {
    Text = "Ich bete zu Gott um eine Antwort."
  },
  AvgDialog_118952_Content_11 = {
    Text = "Ich frage nach der Zukunft des Göttlichen Reiches, frage nach seiner Verbindung zu mir, frage nach allem, was ich wissen möchte, und nach allem, was Miryam zu erkunden versucht."
  },
  AvgDialog_118952_Content_12 = {
    Text = "Der Gott schweigt."
  },
  AvgDialog_118952_Content_13 = {
    Text = "<color=#E6E6E6>Tag fünf nach der Geburt Gottes</color>"
  },
  AvgDialog_118952_Content_14 = {
    Text = "Miryam fragte mich nach dem Ergebnis des Treffens mit den Göttern."
  },
  AvgDialog_118952_Content_15 = {
    Text = "In der Not erfand ich die Antwort Gottes: “Göttliches Reich steht kurz bevor“."
  },
  AvgDialog_118952_Content_16 = {
    Text = "Sie fragte immer wieder nach der Zeit, und ich konnte nur mit “Wenn die Sterne richtig stehen“ antworten."
  },
  AvgDialog_118952_Content_17 = {
    Text = "Miryam war vor Freude außer sich, das war ein Ausdruck von Glück, den ich noch nie zuvor gesehen hatte, als ich ihr die Holzschnitzerei schenkte, und auch nicht, als ich den heiligen Embryo gebar."
  },
  AvgDialog_118952_Content_18 = {
    Text = "<color=#E1E1E1>Tag sechs nach der Geburt Gottes.</color>"
  },
  AvgDialog_118952_Content_19 = {
    Text = "Miryam fragte nach dem Standort von Lemuria, ich konnte nur vage antworten, ihr Gesichtsausdruck war skeptisch."
  },
  AvgDialog_118952_Content_2 = {
    Text = "Der erste Tag der Geburt Gottes"
  },
  AvgDialog_118952_Content_20 = {
    Text = "Sie hat einen noch lebenden Gott gesehen, meine Lügen könnten möglicherweise nicht wirken."
  },
  AvgDialog_118952_Content_21 = {
    Text = "<Shake:Gott, bitte rette mich, auch nur mit einem Wort, antworte meinem Gebet.>"
  },
  AvgDialog_118952_Content_22 = {
    Text = "<Red:Der siebte Tag der Geburt Gottes>"
  },
  AvgDialog_118952_Content_23 = {
    Text = "Götter sind gestorben. Götter wurden nie geboren."
  },
  AvgDialog_118952_Content_24 = {
    Text = "Auf meiner Brust liegt nur eine heuchlerische Statue, ein toter Klumpen aus Fleisch, der fälschlicherweise als <Yellow:“Gott“> bezeichnet wird."
  },
  AvgDialog_118952_Content_25 = {
    Text = "Miryam hat niemanden geliebt. Niemanden gekümmert."
  },
  AvgDialog_118952_Content_26 = {
    Text = "Nachdem ich die Autorität der Göttlichen Mutter erlangt hatte, las ich alle Aufzeichnungen der Seefahrer."
  },
  AvgDialog_118952_Content_27 = {
    Text = "Alle sechzig Jahre kommt es über einen Zeitraum von mehreren Tausend Jahren zu einem Moment, in dem die Sterne richtig stehen."
  },
  AvgDialog_118952_Content_28 = {
    Text = "Der geopferte Mutterkörper, ich bin nicht der Erste, und ich bin nicht der Letzte."
  },
  AvgDialog_118952_Content_29 = {
    Text = "Überleben wollen, bleiben wollen..."
  },
  AvgDialog_118952_Content_3 = {
    Text = "Der göttliche Embryo wird aus dem veraschten Körper geboren."
  },
  AvgDialog_118952_Content_30 = {
    Text = "Dann muss man denjenigen töten..."
  },
  AvgDialog_118952_Content_31 = {
    Text = "Das schwache, naive Ich..."
  },
  AvgDialog_118952_Content_4 = {
    Text = "Ich bin erschöpft von der ausgehauenen Spiritualität, aber auf allen Gesichtern strahlt die leidenschaftliche Freude."
  },
  AvgDialog_118952_Content_5 = {
    Text = "<color=#F7F7F7>Zweiter Tag nach der Geburt Gottes</color>"
  },
  AvgDialog_118952_Content_6 = {
    Text = "Ich taufe den heiligen Embryo. Er schläft mit geschlossenen Augen in seinem Wickeln."
  },
  AvgDialog_118952_Content_7 = {
    Text = "<color=#F2F2F2>Der dritte Tag nach der Geburt Gottes</color>"
  },
  AvgDialog_118952_Content_8 = {
    Text = "Der heilige Embryo hat die Augen noch nicht geöffnet. Ich kann seinen Herzschlag spüren, als ob er direkt vor meiner Brust schlagen würde."
  },
  AvgDialog_118952_Content_9 = {
    Text = "<color=#F0F0F0>Der vierte Tag nach der Geburt Gottes</color>"
  },
  AvgDialog_118953_Content_1 = {
    Text = "Der Vorhang am Himmel wankt und tobt, als wäre es ein Sturm in einem kleinen Universum."
  },
  AvgDialog_118953_Content_10 = {
    Text = "Der Wind weht und die Wolken bewegen sich, der von dunklen Wolken bedeckte trübe Himmel beginnt sich zu verändern."
  },
  AvgDialog_118953_Content_11 = {
    Text = "Sonne im Himmel......"
  },
  AvgDialog_118953_Content_12 = {
    Text = "Der falsche Glanz verschwindet, und unter dem fernen Himmelsgewölbe schwingt der den Himmel und die Sonne verdeckende schwarze Schleier sanft mit dem Atem."
  },
  AvgDialog_118953_Content_13 = {
    Text = "Das war eine schwarze Sonne."
  },
  AvgDialog_118953_Content_2 = {
    Text = "Ein Hauch von durchziehendem Wind hebt den schwarzen Schleier, der ihr Gesicht verschwommen macht, und darunter sind zwei Augen, die längst ausgetrocknet sind."
  },
  AvgDialog_118953_Content_3 = {
    Text = "Es gibt einen Zögern!"
  },
  AvgDialog_118953_Content_4 = {Text = "Oh!"},
  AvgDialog_118953_Content_6 = {
    Text = "Im Moment des Schwankens des Himmels schnitt die gezackte Riesenklinge abrupt in den wogenden Riss."
  },
  AvgDialog_118953_Content_7 = {
    Text = "Die Elfenbeinstatue brach in ein heftiges weißes Licht aus, wie ein verzweifelter Widerstand."
  },
  AvgDialog_118953_Content_8 = {
    Text = "Nach wenigen Sekunden erlosch das weiße Licht plötzlich, und die Elfenbeinstatue zerbrach mit einem Knall, während in einem Durchmesser von zwanzig Zentimetern ein Regen aus weißen Bruchstücken niederfiel."
  },
  AvgDialog_118953_Content_9 = {
    Text = "Es ist alles vorbei..."
  },
  AvgDialog_118954_Content_1 = {
    Text = "Zeitwiedergeburt"
  },
  AvgDialog_118954_Content_10 = {Text = "Hüter..."},
  AvgDialog_118954_Content_11 = {Text = "Ramona!"},
  AvgDialog_118954_Content_12 = {
    Text = "Beruhige dich und hör mir zu."
  },
  AvgDialog_118954_Content_13 = {
    Text = "Ich habe unzählige Zeitüberschreitungen und Rückführungen erlebt."
  },
  AvgDialog_118954_Content_14 = {
    Text = "Deshalb bin ich mir sicher, dass das, was dir widerfahren ist, nicht die “Zeitwiedergeburt“ ist."
  },
  AvgDialog_118954_Content_15 = {
    Text = "Die Zeit, die du erlebt hast, verstrichen weiterhin ganz natürlich."
  },
  AvgDialog_118954_Content_16 = {
    Text = "Es gibt keine “Zeitwiedergeburt“..."
  },
  AvgDialog_118954_Content_17 = {
    Text = "Die merkwürdigen Erscheinungen, die ich jedes Mal beim Erwachen erlebe, das Sinken und Wiederaufleben des Kreuzfahrtschiffes, das auferstandene Mädchen, das unversehrt ist..."
  },
  AvgDialog_118954_Content_18 = {
    Text = "Warum ist das eigentlich?"
  },
  AvgDialog_118954_Content_19 = {
    Text = "Ich kann dir nicht antworten."
  },
  AvgDialog_118954_Content_2 = {
    Text = "Du nimmst wahr, dass du träumst."
  },
  AvgDialog_118954_Content_20 = {
    Text = "Und die Sonne am Himmel..."
  },
  AvgDialog_118954_Content_21 = {
    Text = "Ramona schwieg. Sie wusste auch nicht die Antwort auf die Frage."
  },
  AvgDialog_118954_Content_22 = {
    Text = "Die Wasseroberfläche begann allmählich zu schwanken, ihr Schatten begann am Rand zu wanken und verwandelte sich schließlich in unerreichbare Erinnerungsfragmente, die sich im glitzernden Wellenlicht verstreuten."
  },
  AvgDialog_118954_Content_23 = {
    Text = "Brennen. Schmerzen. Die Zunge des Feuers leckt über jede Hautstelle."
  },
  AvgDialog_118954_Content_24 = {
    Text = "Die Nervenenden krümmen sich vor stechenden Schmerzen und karbonisieren durch Wassermangel.\nDu wirst sehr leicht, so leicht, dass du zu verkohlten, mageren Knochen wirst."
  },
  AvgDialog_118954_Content_25 = {
    Text = "Du hustest heftig."
  },
  AvgDialog_118954_Content_26 = {
    Text = "Bist du wach?"
  },
  AvgDialog_118954_Content_27 = {
    Text = "<Shake:... nochmal... Schleife?>"
  },
  AvgDialog_118954_Content_28 = {
    Text = "Wenn du dich bereits erholt hast, werde ich mit den Vorbereitungen für die Zeremonie beginnen."
  },
  AvgDialog_118954_Content_29 = {
    Text = "Geh nicht, warte einen Moment, Murphy..."
  },
  AvgDialog_118954_Content_3 = {
    Text = "Der Traum ist die Veranschaulichung innerer Wünsche und Ängste, das Traumreich sind schwebende Inseln in der Leere."
  },
  AvgDialog_118954_Content_30 = {
    Text = "Sie... alle?"
  },
  AvgDialog_118954_Content_31 = {
    Text = "Murphy atmete tief ein und ließ dann lange aus."
  },
  AvgDialog_118954_Content_32 = {
    Text = "Jeder hat seine eigenen Dinge zu erledigen. Ruh dich hier gut aus."
  },
  AvgDialog_118954_Content_33 = {
    Text = "Wenn die Sterne wieder richtig stehen, wird dieses Schiff Lemuria erreichen, und alles wird gut werden."
  },
  AvgDialog_118954_Content_34 = {
    Text = "Mit einem Quietschen schloss sich die Tür.\nDu bist allein im Wohnzimmer zurückgelassen worden."
  },
  AvgDialog_118954_Content_35 = {
    Text = "Du darfst nicht bleiben, du musst aktiv werden."
  },
  AvgDialog_118954_Content_36 = {
    Text = "Hast du nach drei Wiedergeburten irgendwelche Schlussfolgerungen?"
  },
  AvgDialog_118954_Content_37 = {
    Text = "Da die Anzahl der Reinkarnationen festgelegt ist, ist Information viel wichtiger als Flucht."
  },
  AvgDialog_118954_Content_38 = {
    Text = "Im ersten Zyklus habe ich die Seefahrer grob kennengelernt; im dritten Zyklus, obwohl ich grausam gescheitert bin, habe ich ein grundlegendes Verständnis für die Bewegungen der anderen Personen auf dem Schiff gewonnen."
  },
  AvgDialog_118954_Content_39 = {
    Text = "Im Gegenteil, die Zeit des zweiten Zyklus ist vergeudet."
  },
  AvgDialog_118954_Content_4 = {
    Text = "In einem Wirrwarr von chaotischen Träumen stechen unzählige bunte Klingen in deine Brust und reflektieren wie Blasen die Schatten voneinander."
  },
  AvgDialog_118954_Content_40 = {
    Text = "Dringend ist es, mehr Informationen über die Paradeis und die Seefahrer zu sammeln."
  },
  AvgDialog_118954_Content_41 = {
    Text = "Obwohl der geheimnisvolle Mensch andeutet, dass es insgesamt sechs Wiedergeburten gibt..."
  },
  AvgDialog_118954_Content_42 = {
    Text = "Hast du nicht darüber nachgedacht, dass wenn dies jetzt die letzte Wiedergeburt ist, du vielleicht eine Gelegenheit umsonst verschwendet hast?"
  },
  AvgDialog_118954_Content_43 = {
    Text = "Wenn jetzt der letzte Kreislauf ist..."
  },
  AvgDialog_118954_Content_44 = {
    Text = "Du schüttelst den Kopf und wirfst alle unheilvollen Vermutungen ab."
  },
  AvgDialog_118954_Content_45 = {
    Text = "In diesem Traum zu Beginn des neuen Zyklus gab mir Ramona: Zeitverwittert eine Information: <Yellow: Sie kann spüren, dass die Zeit auf mir weiterhin kontinuierlich fließt>."
  },
  AvgDialog_118954_Content_46 = {
    Text = "Und du sagst, dass du einmal in einer Schleife gefangen warst..."
  },
  AvgDialog_118954_Content_47 = {Text = "!"},
  AvgDialog_118954_Content_48 = {
    Text = "Es scheint, dass Wilhelm, der Seniorstudent, es auch verstanden hat."
  },
  AvgDialog_118954_Content_49 = {
    Text = "Hier ist es nicht “Zeitwiedergeburt“, sondern “die gleichen Dinge passieren immer wieder“..."
  },
  AvgDialog_118954_Content_5 = {
    Text = "Du brauchst eine Methode, um den Traum zu beenden."
  },
  AvgDialog_118954_Content_50 = {
    Text = "In Misaq werde ich oft gezwungen, in ähnliche Dilemmata zu geraten."
  },
  AvgDialog_118954_Content_51 = {
    Text = "“künstliches Labyrinth“......"
  },
  AvgDialog_118954_Content_52 = {
    Text = "Ja, das hier ist höchstwahrscheinlich ein “künstliches Labyrinth“."
  },
  AvgDialog_118954_Content_53 = {
    Text = "Das künstliche Labyrinth ist nur ein Träger von Informationen, während wir in Wirklichkeit möglicherweise von einem Sturm und Gewitter in der Luft herumgewirbelt werden."
  },
  AvgDialog_118954_Content_54 = {
    Text = "Wie entsteht dieses künstliche Labyrinth? Warum wird der Geheimgang ständig neu gestartet? Was ist der Auslöser für sein Ende?"
  },
  AvgDialog_118954_Content_55 = {
    Text = "Ohne das alles zu verstehen, sind unsere Versuche im Geheimgang nur ein Kopf-an-Kopf-Rennen."
  },
  AvgDialog_118954_Content_56 = {
    Text = "Vernunft. Dreihundert Jahre lang hat die Vernunft Missaga dabei geholfen, dem Wahnsinn namens Auflösung entgegenzutreten."
  },
  AvgDialog_118954_Content_57 = {
    Text = "Ich glaube, dass auch Wilhelm, der Seniorstudent, bereits bemerkt hat, dass die Sonne, die wir in den letzten Tagen betrachtet haben, nicht die schwarze Sonne ist, die nach der Verbreitung des schwarzen Nebels entstanden ist, sondern die echte, normale Sonne der Welt."
  },
  AvgDialog_118954_Content_58 = {
    Text = "Die Geburtszeit des Geheimgangs liegt vor dem Erscheinen des schwarzen Nebels in der Welt."
  },
  AvgDialog_118954_Content_59 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_118954_Content_6 = {
    Text = "Als Weberin des Schicksals muss ich schweigen und kann die Wahrheit nicht aussprechen."
  },
  AvgDialog_118954_Content_60 = {
    Text = "Habe ich etwas Falsches gesagt? Warum starrst du mich so an?"
  },
  AvgDialog_118954_Content_61 = {
    Text = "... Nein, ich habe nur plötzlich an die Zeit in Misaq gedacht, als ich im Außendienst war und immer du und Ramona an meiner Seite waren, was meinen Verstand maximal befreite."
  },
  AvgDialog_118954_Content_62 = {
    Text = "Denken ist ein wesentlicher Bestandteil der Untersuchung."
  },
  AvgDialog_118954_Content_63 = {
    Text = "Nun, Wilhelm, der Seniorstudent, was denkst du, wer der Besitzer des Geheimgangs ist?"
  },
  AvgDialog_118954_Content_64 = {
    Text = "Basierend auf den Prinzipien der Bildung des Geheimgangs und den bekannten Informationen schätze ich vorläufig, dass der Geheimgang zu Miryam oder Faros gehört."
  },
  AvgDialog_118954_Content_65 = {
    Text = "Der <Yellow:“Kern“> des Bereichs ist das “Götterbeschwörungsritual“, die Verfolgung des Verbleibs von Lemuria sollte die Besessenheit des Herrschers des Bereichs sein."
  },
  AvgDialog_118954_Content_66 = {
    Text = "Und laut den Ermittlungsberichten der Sona-Nyl ist Goliaths Ziel die Stärke, Caecus' Besessenheit ist das Blut, nur Miryam und Faros streben nach dem Glanz des Göttlichen Reiches."
  },
  AvgDialog_118954_Content_67 = {
    Text = "Als Nächstes, den Meister des Geheimgangs anvisieren, und dann?"
  },
  AvgDialog_118954_Content_68 = {
    Text = "Wenn der Meister des Geheimgangs an den Ursachen des Geheimgangs zu schwanken beginnt, wird ein Riss erscheinen, in dem die “Katastrophe“ sichtbar wird."
  },
  AvgDialog_118954_Content_69 = {
    Text = "Aber da es sich um ein künstliches Labyrinth handelt, kann die Sicherheit unseres Körpers gewährleistet werden."
  },
  AvgDialog_118954_Content_7 = {
    Text = "Deshalb habe ich dir die Person übergeben, die Erleuchtung schenken kann."
  },
  AvgDialog_118954_Content_70 = {
    Text = "Sei nicht nachlässig. Ganz zu schweigen davon, dass das künstliche Labyrinth derzeit nur in unseren Vermutungen verweilt..."
  },
  AvgDialog_118954_Content_71 = {
    Text = "Im Jahr 306 der Überschwemmung brach der Ermittler Jude Bright nach dem Betreten des Geheimgangs sein rechtes Bein, als er in eine Falle des Jägers trat. Nach seiner Rückkehr in die Realität begann sein rechtes Bein ebenfalls allmählich zu sterben."
  },
  AvgDialog_118954_Content_72 = {
    Text = "Die Art und Weise, wie der Geheimgang die Realität beeinflusst, ist derzeit unbekannt, aber Vorsicht ist immer angebracht."
  },
  AvgDialog_118954_Content_73 = {
    Text = "Verstanden."
  },
  AvgDialog_118954_Content_74 = {
    Text = "Nach dem Ritual werde ich mich Miryam widmen, Faros überlasse ich dir."
  },
  AvgDialog_118954_Content_75 = {
    Text = "Möge der Silberschlüssel unseren Weg erhellen."
  },
  AvgDialog_118954_Content_76 = {
    Text = "Der vertraute Tonfall lässt dich einen Moment lang stocken, aber bald zeigst du ein ehrliches Lächeln."
  },
  AvgDialog_118954_Content_77 = {
    Text = "Möge der Silberschlüssel uns leiten"
  },
  AvgDialog_118954_Content_78 = {
    Text = "Die intellektuelle Frau sitzt einsam in einer Ecke der Kapitänskajüte, das Licht über ihrem Kopf flackert unmerklich mit jedem Atemzug."
  },
  AvgDialog_118954_Content_79 = {Text = "Faros..."},
  AvgDialog_118954_Content_8 = {
    Text = "In der flimmernden Reflexion des Traums erscheint eine aufrechte Gestalt."
  },
  AvgDialog_118954_Content_80 = {
    Text = "Im Moment, als du den Mund öffnest, stockst du plötzlich. Du versuchst, dich an die Informationen über Faros zu erinnern, und dir wird klar, dass es in Misaq nur wenige Aufzeichnungen über sie gibt."
  },
  AvgDialog_118954_Content_81 = {
    Text = "Sie sehnt sich danach, ins Göttliche Reich zurückzukehren, sie führt die Reisenden in die Irre."
  },
  AvgDialog_118954_Content_82 = {
    Text = "Außer dem sind die anderen Akten leer."
  },
  AvgDialog_118954_Content_83 = {
    Text = "Was ist los? An deinem Gesichtsausdruck sehe ich, dass du verwirrt bist?"
  },
  AvgDialog_118954_Content_84 = {
    Text = "Vielleicht... kann ich dir ein wenig den Weg weisen?"
  },
  AvgDialog_118954_Content_85 = {
    Text = "Ich fürchte..."
  },
  AvgDialog_118954_Content_86 = {
    Text = "Ich weiß, wer der Herr des Geheimgangs ist."
  },
  AvgDialog_118954_Content_9 = {
    Text = "Der Schatten fluktuiert, zerbricht und vereint sich, bis er allmählich das vertraute, kalte Gesicht aus deiner Erinnerung stabilisiert."
  },
  AvgDialog_118955_Content_1 = {
    Text = "Außenstehender"
  },
  AvgDialog_118955_Content_10 = {Text = "Wilhelm..."},
  AvgDialog_118955_Content_11 = {
    Text = "Aber du solltest hier nicht verweilen. Nur wenn du den Herrn des Traumreichs findest, kann das unzählige Tage und Nächte, die er hier verbracht hat, enden."
  },
  AvgDialog_118955_Content_12 = {
    Text = "Am Ende des Schiffes siehst du ein Mädchen."
  },
  AvgDialog_118955_Content_13 = {
    Text = "Zahlreiche in schwarze Roben gehüllte Seefahrer lagen schräg und quer um sie herum, während sie ruhig am Altar lehnte und in ihren Händen ein Stück blutrot stinkendes verwestes Fleisch hielt."
  },
  AvgDialog_118955_Content_14 = {Text = "Murphy..."},
  AvgDialog_118955_Content_15 = {
    Text = "Wie du es versprochen hast, bist du gekommen."
  },
  AvgDialog_118955_Content_16 = {
    Text = "Herr des Traumreichs, das bist du."
  },
  AvgDialog_118955_Content_17 = {
    Text = "Ja, alles auf diesem Schiff ist ein Traum. Alles, was du jetzt siehst, ist nur die “Realität im Traum“."
  },
  AvgDialog_118955_Content_18 = {Text = "Warum?"},
  AvgDialog_118955_Content_19 = {
    Text = "Warum sollte man so einen Traumraum erschaffen? Oder warum sollte ich die Person werden, die ich jetzt bin?"
  },
  AvgDialog_118955_Content_2 = {
    Text = "Hust, hust, ha..."
  },
  AvgDialog_118955_Content_20 = {
    Text = "Das war an einem weit entfernten Tag."
  },
  AvgDialog_118955_Content_21 = {
    Text = "Die kleine Gestalt wandert durch den Schnee."
  },
  AvgDialog_118955_Content_22 = {
    Text = "Huch... Huch..."
  },
  AvgDialog_118955_Content_23 = {
    Text = "Seit sie in der Antarktis ist, hat Murphy eine absurde Freiheit erlangt."
  },
  AvgDialog_118955_Content_24 = {
    Text = "Sie kann alleine überall hingehen. Aber wohin sie auch geht, überall sieht sie nur das blasse Schneefeld."
  },
  AvgDialog_118955_Content_25 = {
    Text = "Nicht einmal der Mensch, nicht einmal die Spuren, dass Menschen jemals existiert haben."
  },
  AvgDialog_118955_Content_26 = {
    Text = "Bin ich hier... verloren gegangen?"
  },
  AvgDialog_118955_Content_27 = {
    Text = "Das Mädchen blickte auf ihre eigenen Fußspuren zurück. In dem weiten Schneefeld führt eine fast gerade Linie von Schritten zu einem unbekannten Ort."
  },
  AvgDialog_118955_Content_28 = {
    Text = "Egal, solange wir weitergehen, werden wir irgendwann an einen Ort kommen."
  },
  AvgDialog_118955_Content_29 = {
    Text = "Das Mädchen zählte die mitgeführten Vorräte und bestätigte, dass sie mit der nächsten Zeit sparsam umgehen konnte, um die weiteste Strecke zu erreichen."
  },
  AvgDialog_118955_Content_3 = {
    Text = "Du hustest kräftig, um das ins Lungengewebe eingedrungene Meerwasser loszuwerden."
  },
  AvgDialog_118955_Content_30 = {
    Text = "Mach weiter, Murphy. Das ist eine Reise in die Freiheit, ein bisschen Hunger ist nicht so schlimm."
  },
  AvgDialog_118955_Content_31 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_118955_Content_32 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_118955_Content_33 = {
    Text = "Das geht nicht, bei solchem Schneesturm kann man den Weg überhaupt nicht unterscheiden."
  },
  AvgDialog_118955_Content_34 = {
    Text = "Trockenbrot mit Schneewasser ist wirklich schwer zu essen."
  },
  AvgDialog_118955_Content_35 = {
    Text = "Manchmal hielt sie sich in einer Schneehöhle auf und konnte das Heulen des Biestes hören. Sie hatte es nie gesehen, wusste aber, dass es eine Art weißer Wolf war."
  },
  AvgDialog_118955_Content_36 = {Text = "Hilfe!"},
  AvgDialog_118955_Content_37 = {
    Text = "Murphy floh panisch aus der Höhle. Die leuchtend grünen Augen blieben in der Höhle zurück und verfolgten ihre Schritte nicht."
  },
  AvgDialog_118955_Content_38 = {
    Text = "In einer solchen ausweglosen Situation sah ich eine Reihe von Fußspuren."
  },
  AvgDialog_118955_Content_39 = {
    Text = "Es sind Fußspuren von Menschen...!"
  },
  AvgDialog_118955_Content_4 = {
    Text = "Aber ich kann nichts heraus husten, in meinen Lungen bleiben nur zuckende Nerven und der Phantomschmerz des Ertrinkens."
  },
  AvgDialog_118955_Content_40 = {
    Text = "Egal, ob jemand da ist, es gibt Hoffnung. Ich folgte ohne zu zögern."
  },
  AvgDialog_118955_Content_41 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_118955_Content_42 = {
    Text = "Bald darauf verwandelten sich die Fußspuren in zwei Reihen."
  },
  AvgDialog_118955_Content_43 = {
    Text = "Drei Zeilen."
  },
  AvgDialog_118955_Content_44 = {
    Text = "Die Fußspuren werden immer mehr, aber der Besitzer der Fußspuren bleibt unauffindbar."
  },
  AvgDialog_118955_Content_45 = {
    Text = "Ich, zu erschöpft, bin schließlich in Ohnmacht gefallen."
  },
  AvgDialog_118955_Content_46 = {
    Text = "Später erfuhr ich, dass jeder beim Gehen in eine Richtung, ohne die Richtung zu bestimmen, leicht in eine Richtung abdriftet, da die Längen der linken und rechten Füße unterschiedlich sind."
  },
  AvgDialog_118955_Content_47 = {
    Text = "Mit anderen Worten... Zu dieser Zeit war meine Gehspur ein Ring."
  },
  AvgDialog_118955_Content_48 = {
    Text = "Die Spuren, die ich als Hoffnung sehe, stammen von meinem früheren Ich und führen in die endlose Schleife."
  },
  AvgDialog_118955_Content_49 = {
    Text = "Wegen einer kleinen, fast unbedeutenden Abweichung...\n Mein Leben wird ständig von einem Teufelskreis gefesselt."
  },
  AvgDialog_118955_Content_5 = {
    Text = "Warum... sollte es nicht der letzte Kreislauf sein?"
  },
  AvgDialog_118955_Content_50 = {
    Text = "Der Mittelpunkt des Rings wird Schicksal genannt."
  },
  AvgDialog_118955_Content_51 = {
    Text = "Das ist die Schleife, die ich geschaffen habe, um mich selbst zu fangen."
  },
  AvgDialog_118955_Content_52 = {
    Text = "Das heißt..."
  },
  AvgDialog_118955_Content_53 = {
    Text = "Seit dem ersten Aufstand von Goliath ist die Zeit stehen geblieben."
  },
  AvgDialog_118955_Content_54 = {
    Text = [[
Alle sind in den Traum eingetaucht, der sich endlos wiederholt. 
 Der Kreislauf des Traums beginnt mit der Geburt des Heiligen Embryos und endet mit dem Untergang des Kreuzfahrtschiffes.]]
  },
  AvgDialog_118955_Content_55 = {
    Text = "Egal, solange Goliath keinen Aufstand entfesselt hat, kann alles in Ordnung sein."
  },
  AvgDialog_118955_Content_56 = {
    Text = "Aber ich habe Goliath einmal in der Nekropolis gesehen..."
  },
  AvgDialog_118955_Content_57 = {
    Text = "Um das Traumreich aufrechtzuerhalten, werde ich regelmäßig eine Gruppe von Menschen aussenden, um Energie für die Elfenbeinstatue zu sammeln."
  },
  AvgDialog_118955_Content_58 = {
    Text = "Egal, wenn sie in das Traumreich zurückkehren, werden sie diese Erfahrung wieder vergessen und zu den Bewohnern des Traumreichs werden."
  },
  AvgDialog_118955_Content_59 = {
    Text = "Leider ist das Traumgebiet seit dem Zeitpunkt, als du uns daran gehindert hast, Energie aus der Nekropolis zu absorbieren, immer instabiler geworden."
  },
  AvgDialog_118955_Content_6 = {
    Text = "Du schaust umher, das weite Deck ist leer, keine lila Spinnen und keine Gläubigen des Seereichs, die dich umgeben."
  },
  AvgDialog_118955_Content_60 = {
    Text = "Warum willst du, dass ich dich sehe?"
  },
  AvgDialog_118955_Content_61 = {
    Text = "Ich habe dich ursprünglich beschworen, um alle instabilen Faktoren zu beseitigen und dich in diesem Traumraum zu ersticken..."
  },
  AvgDialog_118955_Content_62 = {
    Text = "Nur vorher schien mein Silberkern mit deinem Silberschlüssel in Resonanz zu treten, ich verband mich mit deinem Traum, deinen Erinnerungen."
  },
  AvgDialog_118955_Content_63 = {
    Text = "In einem Traum sah ich eine andere Möglichkeit... ein anderes Ich."
  },
  AvgDialog_118955_Content_64 = {
    Text = "Ich habe gesehen, dass sie im Bildhauerunterricht mit ihren Klassenkameraden konkurriert;"
  },
  AvgDialog_118955_Content_65 = {
    Text = "Ich sah sie im Brunnen mit einer streunenden Katze kämpfen;"
  },
  AvgDialog_118955_Content_66 = {
    Text = "Ich sah, wie sie von ihren Freunden überredet wurde, ein kleines Teufelskleid anzuziehen und mit einer Kürbislaterne von Tür zu Tür Süßigkeiten zu verteilen..."
  },
  AvgDialog_118955_Content_67 = {
    Text = "In einer Welt, in der der heilige Embryo nicht geboren wurde, ist sie wirklich... zu glücklich."
  },
  AvgDialog_118955_Content_68 = {
    Text = "Neidisch, beneidenswert."
  },
  AvgDialog_118955_Content_69 = {
    Text = "Es macht auch den Wunsch zu sein."
  },
  AvgDialog_118955_Content_7 = {
    Text = "Du rennst umher und suchst."
  },
  AvgDialog_118955_Content_70 = {
    Text = "<Yellow:%player%>, bis ich dich traf, wusste ich, dass es auf der Welt noch so eine einfache und glückliche Lebensweise gibt..."
  },
  AvgDialog_118955_Content_71 = {
    Text = "Ich brauche keine eitlen Kronen der Göttlichen Mutter, keinen Ruhm, der von der Menge verehrt wird, und ich brauche kein tägliches Konfrontieren mit den lästigen Gesichtern der Gläubigen..."
  },
  AvgDialog_118955_Content_72 = {
    Text = "Welche Verantwortung, welches Erbe, warum müssen so viele Menschen ihr Leben für einen Haufen faules Fleisch opfern?"
  },
  AvgDialog_118955_Content_73 = {
    Text = "Du schweigst, du kannst nur schweigen."
  },
  AvgDialog_118955_Content_74 = {
    Text = "Murphy leugnete ihr früheres Ich."
  },
  AvgDialog_118955_Content_75 = {
    Text = "Ich habe noch eine letzte Frage an dich."
  },
  AvgDialog_118955_Content_76 = {
    Text = "Machst du in deiner Welt auch kleine Kuchen mit ihr?"
  },
  AvgDialog_118955_Content_77 = {
    Text = "In dieser Welt... wird es nicht nur mich geben, sondern viele Menschen, die bereit sind, dir zu helfen und alles zu tun, was du willst und was vielleicht auch unvernünftig ist."
  },
  AvgDialog_118955_Content_78 = {
    Text = "Murphy, weil du die Welt und alle Menschen liebst."
  },
  AvgDialog_118955_Content_79 = {
    Text = "Wegen dir hast du dein Herz geöffnet, und alle haben es mit eigenen Augen gesehen."
  },
  AvgDialog_118955_Content_8 = {
    Text = "Schlaf, schlaf, alle schlafen."
  },
  AvgDialog_118955_Content_80 = {
    Text = "Das pulsierende Herz."
  },
  AvgDialog_118955_Content_81 = {
    Text = "Murphy lächelte, so strahlend wie deine Erinnerungen aus der Vergangenheit."
  },
  AvgDialog_118955_Content_82 = {
    Text = "Weißt du? Dieses Schiff ist ein Traum."
  },
  AvgDialog_118955_Content_83 = {
    Text = "Ich dachte, es sei ein schöner Traum...\n Ich bin die erhabene Göttinmutter, und dieser sich windende Klumpen Fleisch ist das sogenannte Gottheit."
  },
  AvgDialog_118955_Content_84 = {
    Text = "Tag und Nacht lebe ich umarmt von Angst, voller Furcht und gequält."
  },
  AvgDialog_118955_Content_85 = {
    Text = "Es stellte sich heraus, dass dieser Traum kein schöner Traum war, sondern ein Albtraum, von dem ich selbst nicht einmal wusste, dass ich darin versunken war."
  },
  AvgDialog_118955_Content_86 = {
    Text = "Also, lass den Vorhang der Lügen fallen und lass den Traum erwachen."
  },
  AvgDialog_118955_Content_9 = {
    Text = "Wilhelm liegt auf dem Deck, seine Uniform ist zerfetzt und sieht aus, als wäre sie wiederholt von Sturm und brennender Sonne verwüstet worden, Öl und Salzkruste bilden eine fleckige Landkarte."
  },
  AvgDialog_118956_Content_1 = {
    Text = "Ihr kämpft und zieht euch zurück, vom Kraftwerk zum Korridor, vom Korridor zum Deck, bis hinter euch nur ein Geländer und der unendliche Ozean bleibt."
  },
  AvgDialog_118956_Content_10 = {
    Text = "Der monströse Riese mit übermenschlicher Kraft rutscht unter deinem Aufprall hastig zurück und scheint kurz davor zu sein, heftig gegen das Deck zu prallen."
  },
  AvgDialog_118956_Content_11 = {
    Text = "In einem Augenblick der Elektrizität stach er die riesige Klinge gerade in den Boden und hielt sich mühsam aufrecht."
  },
  AvgDialog_118956_Content_12 = {
    Text = "Du Bursche, du hast dich seit unserem letzten Treffen wirklich verbessert."
  },
  AvgDialog_118956_Content_13 = {
    Text = "Nein, so ist es nicht."
  },
  AvgDialog_118956_Content_14 = {
    Text = "Es liegt nicht daran, dass du stärker geworden bist, sondern dass Goliath schwächer geworden ist."
  },
  AvgDialog_118956_Content_15 = {
    Text = "Selbst mit Faros' Unterstützung ist Goliaths Stärke bei weitem nicht so groß wie bei deinem letzten Treffen mit ihm."
  },
  AvgDialog_118956_Content_16 = {
    Text = "Jeder Hieb ist leicht und ganz und gar nicht aus der Hand eines kraftvollen Riesen."
  },
  AvgDialog_118956_Content_17 = {
    Text = "Goliath, ich habe von Anfang an im Kampf erkannt, dass deine übermenschliche Kraft... rapide abnimmt."
  },
  AvgDialog_118956_Content_18 = {
    Text = "Hmph, selbst wenn ich zehnmal schwächer wäre, könntest du, dieser kleine Kerl, mich nicht besiegen."
  },
  AvgDialog_118956_Content_19 = {
    Text = "Hat das mit Faros zu tun, dass wir hier sind?"
  },
  AvgDialog_118956_Content_2 = {
    Text = "Du kannst wirklich durchhalten... Du hast es bis hierher geschafft."
  },
  AvgDialog_118956_Content_20 = {
    Text = "Geht es noch weiter, hat das mit der Vision auf diesem Schiff zu tun?"
  },
  AvgDialog_118956_Content_21 = {
    Text = "Bist du so eilig dabei, die sogenannte Anordnung auszuführen, weil deine eigene Kraft nachgelassen hat?"
  },
  AvgDialog_118956_Content_22 = {
    Text = "Hmph, das sind Dinge, die du nicht wissen solltest. Egal wie sehr du fragst, erwarte nicht, dass ich ein Wort davon von mir gebe."
  },
  AvgDialog_118956_Content_23 = {
    Text = "Wenn unsere Ziele übereinstimmen, bin ich möglicherweise nicht die Option, die du ausschließen solltest."
  },
  AvgDialog_118956_Content_24 = {
    Text = "Gib nach, ich greife nicht in deine Absichten der Verräter gegen die Seefahrer ein, und du machst mir auch keine Schwierigkeiten."
  },
  AvgDialog_118956_Content_25 = {
    Text = "Goliath hatte noch nicht geantwortet, als zwei schattenhafte Schlangen blitzschnell auf euch zuschossen!"
  },
  AvgDialog_118956_Content_27 = {
    Text = "Ihr zieht euch plötzlich zurück, die Schattenschlangen explodieren auf dem Deck und reißen in einem Augenblick zwei furchterregende Löcher, aus denen schwarzer Rauch aufsteigt."
  },
  AvgDialog_118956_Content_28 = {
    Text = "Zwei undankbare Verräter, hier gibt es keinen Spielraum für eure Einigung."
  },
  AvgDialog_118956_Content_29 = {
    Text = "Was die Außenseiter angeht... Beim Fliehen scheinst du etwas Entscheidendes vergessen zu haben."
  },
  AvgDialog_118956_Content_3 = {
    Text = "Aber du hast keinen Rückweg mehr."
  },
  AvgDialog_118956_Content_30 = {
    Text = "Die Elfenbeinstatue schwebte in Miryams Hand. \n Sie betete fromm, während die verfluchten Wörter wie Maden aus ihrem Mund strömten."
  },
  AvgDialog_118956_Content_31 = {
    Text = "<Change>Eure Leiber und Seelen gehören schon längst dem Schatten des Abgrunds."
  },
  AvgDialog_118956_Content_32 = {
    Text = "Warte, Miryam, nicht—"
  },
  AvgDialog_118956_Content_33 = {
    Text = "Es tut mir leid, Göttliche Mutter, ich muss diese Blasphemiker im Namen von Ihnen bestrafen."
  },
  AvgDialog_118956_Content_34 = {
    Text = "Die Elfenbeinstatue gibt ein lautloses Zischen von sich, unzählige silberne Fäden verbreiten sich und parasitieren wie seltsame lebende Wesen auf den Herzen der Meeresbewohner."
  },
  AvgDialog_118956_Content_35 = {
    Text = "Das ist... verrückte Frau, was machst du?!"
  },
  AvgDialog_118956_Content_36 = {
    Text = "Was mache ich? Natürlich gebe ich euch die Barmherzigkeit, das Mitgefühl und die höchste Kraft der Götter."
  },
  AvgDialog_118956_Content_37 = {
    Text = "Der Faden verheddert sich fest und zieht sich im nächsten Moment heftig zusammen——"
  },
  AvgDialog_118956_Content_38 = {
    Text = "Herr Goliath... ich fühle, dass ich gleich nicht mehr atmen kann..."
  },
  AvgDialog_118956_Content_39 = {
    Text = "<Shake:Ah ah... Ich spüre... die Adern des Gottes... Ich habe... seine Seele berührt...>"
  },
  AvgDialog_118956_Content_4 = {
    Text = "Du atmest tief ein, sammelst deine Gedanken und bereitest dich auf den erneuten Schlag von Goliaths riesiger Klinge vor."
  },
  AvgDialog_118956_Content_40 = {Text = "Klatsch."},
  AvgDialog_118956_Content_41 = {
    Text = "Das Herz explodiert nacheinander, und blutrote Unreinheit entfaltet sich auf dem Deck in blutigen Wellen."
  },
  AvgDialog_118956_Content_42 = {
    Text = "Egal wie viele Tage vergehen, die Dummheit der Ungläubigen kann nicht umgekehrt werden."
  },
  AvgDialog_118956_Content_43 = {
    Text = "<Shake:Lasst uns mit eurem Blut und Geist die Treppe zum Göttlichen Reich erschaffen!>"
  },
  AvgDialog_118956_Content_44 = {
    Text = "<Shake:Stoppe sie...<Big:Komm mit mir, stoppe sie!>>"
  },
  AvgDialog_118956_Content_6 = {
    Text = "Der Weg, den du als auswegslos ansiehst, ist in Wahrheit das Schlachtfeld, das ich für dich ausgewählt habe."
  },
  AvgDialog_118956_Content_7 = {
    Text = "Du hast ständig Kraft verschwendet, und jetzt ist es Zeit für meinen Gegenangriff."
  },
  AvgDialog_118956_Content_8 = {
    Text = "Silbernes Licht brach plötzlich hervor, mit einer überwältigenden Kraft, die auf Goliath niederschlug. \n Goliath hob sofort sein Schwert zur Verteidigung, doch es war zu spät."
  },
  AvgDialog_118957_Content_1 = {Text = "Epilog"},
  AvgDialog_118957_Content_10 = {
    Text = "Das war wirklich ein sehr langer Traum."
  },
  AvgDialog_118957_Content_11 = {
    Text = "Tod, Verrat, Untergang; je mehr man versucht, das Gewollte festzuhalten, desto unvermeidlicher entgleitet es einem zwischen den Fingern."
  },
  AvgDialog_118957_Content_12 = {
    Text = "Vielleicht ist das das Schicksal. Unwiederbringlich, man muss nicht festhalten."
  },
  AvgDialog_118957_Content_13 = {
    Text = "Lass frühzeitig los, vielleicht triffst du noch gleichgesinnte Gefährten."
  },
  AvgDialog_118957_Content_14 = {
    Text = "Zum Beispiel... Misaq?"
  },
  AvgDialog_118957_Content_15 = {
    Text = "Die Leute in Misaq scheinen sehr gut darin zu sein, tolerant zu sein... oder die Eigenheiten aller zu glätten."
  },
  AvgDialog_118957_Content_16 = {
    Text = "Ich erinnere mich, dass Murphy eines Jahres unbedingt jede Geschmacksrichtung von Süßigkeiten probieren wollte, und am Ende hatte sie Zahnschmerzen."
  },
  AvgDialog_118957_Content_17 = {
    Text = "Sylvia ließ schließlich Jenkin den gesamten Vorrat der Dame stehlen."
  },
  AvgDialog_118957_Content_18 = {
    Text = "Pff. Und dann?"
  },
  AvgDialog_118957_Content_19 = {
    Text = "Dann begann sie, groß aufzutischen und Diebe zu fangen, und ließ die Süßigkeiten völlig außer Acht."
  },
  AvgDialog_118957_Content_2 = {
    Text = "Die Paradeis ist bereits eingelaufen, und als Nächstes......"
  },
  AvgDialog_118957_Content_20 = {
    Text = "Noch einmal..."
  },
  AvgDialog_118957_Content_21 = {
    Text = "Gut, wie viel willst du, dass ich sie noch beneide?"
  },
  AvgDialog_118957_Content_22 = {
    Text = "Wenn wir nach Missaga zurückkehren, wird dir das alles gehören."
  },
  AvgDialog_118957_Content_23 = {
    Text = "Dann wünschen wir uns, dass wir eines Tages in Misaq wiedersehen."
  },
  AvgDialog_118957_Content_24 = {
    Text = "Murphy streckte die Hände zum fernen Himmel aus, als ob sie die Sonne hoch oben berühren wollte."
  },
  AvgDialog_118957_Content_25 = {
    Text = "Der schwarze, runde Schatten rollte zwischen ihren Fingern."
  },
  AvgDialog_118957_Content_26 = {
    Text = "Und eine Sache, die ich dir unbedingt mitteilen muss."
  },
  AvgDialog_118957_Content_27 = {
    Text = "Murphys Blick durchdringt dich direkt."
  },
  AvgDialog_118957_Content_28 = {
    Text = "Diese Welt ist bereits untergegangen und nicht mehr zu retten, sie ist von einer tieferen Verzweiflung bedeckt als die Schleifen, die ich erlebt habe."
  },
  AvgDialog_118957_Content_29 = {
    Text = "Wenn es möglich ist, kann ich versuchen, dich zurückzubringen."
  },
  AvgDialog_118957_Content_3 = {
    Text = "Sie wissen bereits alles über die Götter dieser Welt und werden bald ihre eigene Wahl treffen."
  },
  AvgDialog_118957_Content_30 = {
    Text = "Bring mich... zurück?"
  },
  AvgDialog_118957_Content_31 = {
    Text = "Weißt du, wie man zwischen zwei Welten reist?"
  },
  AvgDialog_118957_Content_32 = {
    Text = "Man kann nicht sagen, dass man es weiß, aber solange man die Essenz dieser Welt kennt, kann man natürlich die Knotenpunkte der Verbindung der Welt verstehen."
  },
  AvgDialog_118957_Content_33 = {
    Text = "Dieses Schiff ist ein Traum, aber als der Vorhang der Lügen sich hebt..."
  },
  AvgDialog_118957_Content_34 = {
    Text = "Die ganze Welt ist ebenfalls der Traum einer bestimmten Person, nur ist dieser Traum größer, illusorischer und ferner..."
  },
  AvgDialog_118957_Content_35 = {
    Text = "Selbst Sonne, Mond und Sterne stammen aus seiner Einbildung, nur die Wesen, die mit seinem Geist verwoben sind, können..."
  },
  AvgDialog_118957_Content_36 = {
    Text = "Sonne, Mond und Sterne..."
  },
  AvgDialog_118957_Content_37 = {
    Text = "Der schwarze Schleier zitterte und erstreckte sich zu einem gewundenen Weg, der zum Himmel führte."
  },
  AvgDialog_118957_Content_38 = {
    Text = "Geh, geh zurück, zurück in die Welt, die dir gehört! Es gibt keinen Grund, an dieser bereits toten Welt festzuhalten."
  },
  AvgDialog_118957_Content_39 = {
    Text = "Und du, Murphy?"
  },
  AvgDialog_118957_Content_4 = {
    Text = "Meiner Meinung nach werden Miryam und Faros erneut in See stechen, um nach dem Verbleib von Lemuria zu suchen."
  },
  AvgDialog_118957_Content_40 = {
    Text = "Du unterdrückst den Impuls, sofort den Seidenweg zu betreten, und fragst die schweigende Murphy zurück."
  },
  AvgDialog_118957_Content_41 = {
    Text = "Wer weiß? Diese Welt ist eine bereits zerstörte Welt."
  },
  AvgDialog_118957_Content_42 = {
    Text = "Nimm es an. Vielleicht kannst du eines Tages in dieser Welt meinen Silberkern spüren."
  },
  AvgDialog_118957_Content_43 = {
    Text = "Ein aus einem Blutstropfen geformter Edelstein fiel in deine Handfläche, aus der grotesken Wunde, die ihre Brust durchbohrte."
  },
  AvgDialog_118957_Content_44 = {
    Text = "Damals hast du beschworen, ich weiß nicht, aus welcher Zeit “Ich“ kommen würde."
  },
  AvgDialog_118957_Content_45 = {
    Text = "Aber wenn du mich rufst, vergiss nicht, wie ich jetzt aussehe..."
  },
  AvgDialog_118957_Content_46 = {
    Text = "Seine Geburt ist eine Illusion... Das Formen von Träumen ist alles Illusion..."
  },
  AvgDialog_118957_Content_47 = {
    Text = "Nennt mich einfach...“<Yellow:Wahngeboren·Murphy>“!"
  },
  AvgDialog_118957_Content_48 = {
    Text = "Du schreitest langsam den Seidenweg entlang, unzählige Gedanken fliegen in deinem Kopf vorbei."
  },
  AvgDialog_118957_Content_49 = {
    Text = "Die Reise gegen die Auflösung, zwei Welten, die von einem schwarzen Albtraum umschlungen sind, viele ähnliche oder identische Gesichter überlappen sich ..."
  },
  AvgDialog_118957_Content_5 = {
    Text = "Goliath und Caecus werden wahrscheinlich gehen, selbst in dieser zunehmend verwüsteten Welt werden sie ihren eigenen Weg finden."
  },
  AvgDialog_118957_Content_50 = {
    Text = "Zwei Puppen..."
  },
  AvgDialog_118957_Content_51 = {
    Text = "Zwei Clementinen..."
  },
  AvgDialog_118957_Content_52 = {
    Text = "Zwei Murphys..."
  },
  AvgDialog_118957_Content_53 = {
    Text = "Schließlich bleibt es bei dem lächelnden Gesicht von Ramona stehen."
  },
  AvgDialog_118957_Content_54 = {
    Text = "Kann ich... zurückkehren?"
  },
  AvgDialog_118957_Content_55 = {
    Text = "Traumhaft stehst du nur einen Arm entfernt von der schwarzen Sonne, spürst jedoch keine Wärme."
  },
  AvgDialog_118957_Content_56 = {
    Text = "Das unendliche Dunkel verschlingt alles Licht und ist darauf bedacht, auch dich vollständig zu verschlingen."
  },
  AvgDialog_118957_Content_57 = {
    Text = "Ramona... wartest du hier nach mir?"
  },
  AvgDialog_118957_Content_58 = {
    Text = "Du schließt die Augen, streckst vorsichtig die Fingerspitzen aus und berührst den schwarzen Durchgang."
  },
  AvgDialog_118957_Content_59 = {
    Text = "Wenn möglich, halte meine Hand."
  },
  AvgDialog_118957_Content_6 = {
    Text = "Was “dieser“ Murphy betrifft..."
  },
  AvgDialog_118957_Content_60 = {
    Text = "Von deinen Füßen, aus den vielen Tiefträumen."
  },
  AvgDialog_118957_Content_61 = {
    Text = "Ausgehend von der schwarzen Sonne löste sich der schwarze Schleier schichtweise auf."
  },
  AvgDialog_118957_Content_62 = {
    Text = "Du fällst aus großer Höhe."
  },
  AvgDialog_118957_Content_63 = {
    Text = "<Yellow:In den Wirbel namens “Schicksal“ stürzen.>"
  },
  AvgDialog_118957_Content_64 = {
    Text = "Ich erblickte das Schicksal des Mädchens im Tieftraum."
  },
  AvgDialog_118957_Content_65 = {
    Text = "Es ist bedauerlich, dass ich sie ursprünglich aus Lemuria weggeschickt und die Elfenbeinstatue in ihrem Traum bei ihr gelassen habe, nicht für ein solches Ende."
  },
  AvgDialog_118957_Content_66 = {
    Text = "Sollte man mir nicht für meine Vermittlung danken?"
  },
  AvgDialog_118957_Content_67 = {
    Text = "Das Licht der Hoffnung in dieser Welt ist längst erloschen, das solltest du wissen, oder?"
  },
  AvgDialog_118957_Content_68 = {
    Text = "Die Frau, die den Spinnrad berührt, schweigt und lässt den Faden in die Himmelsdecke und in die Welt hinausfließen."
  },
  AvgDialog_118957_Content_69 = {
    Text = "Egal ob es nur ein Samen gibt."
  },
  AvgDialog_118957_Content_7 = {
    Text = "Ich denke, sie hat etwas, das sie dir sagen möchte."
  },
  AvgDialog_118957_Content_70 = {
    Text = "Egal wie lange die Stille dauert, egal in welchem Boden, eines Tages wird es sprießen."
  },
  AvgDialog_118957_Content_71 = {
    Text = "Was mich betrifft..."
  },
  AvgDialog_118957_Content_72 = {
    Text = "Die Frau senkte den Blick."
  },
  AvgDialog_118957_Content_73 = {
    Text = "Ich bin kein Sämann, kein Erzieher und kein Erntearbeiter."
  },
  AvgDialog_118957_Content_74 = {
    Text = "Ich ziehe nur an den Fäden, folge den Gesetzen des Himmels und skizziere den Schicksalsweber."
  },
  AvgDialog_118957_Content_75 = {
    Text = "Ich werde die Fäden der Spindel ziehen, um den passendsten Boden für sie zu finden."
  },
  AvgDialog_118957_Content_76 = {
    Text = "Ich werde still warten."
  },
  AvgDialog_118957_Content_8 = {
    Text = "Bist du gekommen?"
  },
  AvgDialog_118957_Content_9 = {Text = "Gut."},
  AvgDialog_118958_Content_1 = {Text = "Kern"},
  AvgDialog_118958_Content_10 = {
    Text = "Ich habe einst mit Goliath verbündet, doch die Barbaren, die nur Krieg und Gewalt verstehen, wissen offensichtlich nicht, wie man Verträge einhält, geschweige denn den Weg nach Lemuria weist."
  },
  AvgDialog_118958_Content_11 = {
    Text = "Wie? Egal, ob du nickst und zustimmst, ich werde dir die Identität des Meisters des Geheimgangs verraten."
  },
  AvgDialog_118958_Content_12 = {
    Text = "Das Mädchen hatte das Herz bis zum Hals."
  },
  AvgDialog_118958_Content_13 = {
    Text = "Lass mich ablehnen."
  },
  AvgDialog_118958_Content_14 = {
    Text = "Ich kann nicht hastig zustimmen, das Leben einer Person zu nehmen, ohne zu wissen, wer die andere Person ist."
  },
  AvgDialog_118958_Content_15 = {
    Text = "Zudem, da du eine solche Forderung gestellt hast, ist der Herr des Geheimgangs offensichtlich nicht zwischen dir, Goliath und Caecus."
  },
  AvgDialog_118958_Content_16 = {
    Text = "Und du hast bereits verraten, dass die Macht des Traums mit jener Elfenbeinstatue verbunden ist."
  },
  AvgDialog_118958_Content_17 = {
    Text = "Der einzige verbleibende Verdächtige ist also sie..."
  },
  AvgDialog_118958_Content_18 = {
    Text = "Dein Geschmack bei der Wahl des Aussichtspunkts ist wirklich lobenswert."
  },
  AvgDialog_118958_Content_19 = {
    Text = "Du ziehst das Seil straff, sodass das Segel am Mast dich und Wilhelm verdeckt."
  },
  AvgDialog_118958_Content_2 = {
    Text = "<Shake:Tapp tapp tapp, tapp tapp tapp.>"
  },
  AvgDialog_118958_Content_20 = {
    Text = "Beim letzten Ritual ist mir aufgefallen, dass die Paradeis im Vergleich zur Sonaniel eine relativ alte Maststruktur beibehalten hat."
  },
  AvgDialog_118958_Content_21 = {
    Text = "Es entspricht einem Aussichtspunkt, von dem aus man die Situation der Einweisungszeremonie überblicken kann."
  },
  AvgDialog_118958_Content_22 = {
    Text = "Wenn das Einführungsritual beginnt, wird Miryam die Elfenbeinstatue an Murphy übergeben, und das ist auch die einzige Gelegenheit, die wir haben, um die Elfenbeinstatue zu berühren."
  },
  AvgDialog_118958_Content_23 = {
    Text = "Nehmt die Statue und analysiert sie, vielleicht können wir so die Methode zur Auflösung des Geheimgangs erlangen."
  },
  AvgDialog_118958_Content_24 = {
    Text = "Pst, sie kommen."
  },
  AvgDialog_118958_Content_25 = {
    Text = "William klopfte dir auf die Schulter und deutete dir, dich umzudrehen."
  },
  AvgDialog_118958_Content_26 = {
    Text = "Achte auf die Position der Elfenbeinstatue... das ist unsere Lebenslinie."
  },
  AvgDialog_118958_Content_27 = {
    Text = "Und deine Erinnerungen sind nicht anders, das Navigationsritual verläuft reibungslos."
  },
  AvgDialog_118958_Content_28 = {
    Text = "Ehrwürdige Göttliche Mutter, ziehe das Blut des Gottkönigs und führe die umherirrenden Seefahrer, um uns den Kurs nach Lemuria zu weisen."
  },
  AvgDialog_118958_Content_29 = {
    Text = "Murphy biss sich auf die Lippen und nahm den schimmernden Dolch aus Miryams Hand."
  },
  AvgDialog_118958_Content_3 = {
    Text = "Das Mädchen rennt den Flur entlang."
  },
  AvgDialog_118958_Content_30 = {
    Text = "Sie hob das Messer hoch — und stach lange nicht zu."
  },
  AvgDialog_118958_Content_31 = {
    Text = "Die Göttliche Mutter, haben Sie nicht schon längst eine Entscheidung getroffen? Lemuria liegt immer noch am Grund des Abgrunds und erwartet Ihre Ankunft."
  },
  AvgDialog_118958_Content_32 = {
    Text = "... ich mache das sofort..."
  },
  AvgDialog_118958_Content_33 = {
    Text = "Der zweite Teil des Satzes wurde verschluckt."
  },
  AvgDialog_118958_Content_34 = {
    Text = "Sie hielt die blutgetränkte Elfenbeinstatue in den Händen und ließ das deformierte Monster ihre Seele auslaugen."
  },
  AvgDialog_118958_Content_35 = {
    Text = "Der Blutfluss breitet sich am Schiffsrand aus und zieht nach links."
  },
  AvgDialog_118958_Content_36 = {
    Text = "Steuerbord! Seefahrer, höre das göttliche Wort, volle Linkskurve!"
  },
  AvgDialog_118958_Content_37 = {
    Text = "Was sie beantwortete, war ein scharfer durchdringender Klang."
  },
  AvgDialog_118958_Content_38 = {
    Text = "Ich denke, das ist nicht nötig."
  },
  AvgDialog_118958_Content_39 = {
    Text = "Der scharfe Dreizack, wie die spitzen Zähne eines riesigen Hais, schoss plötzlich aus der dunklen Nacht hervor und durchbohrte präzise die Kehle des Steuermanns."
  },
  AvgDialog_118958_Content_4 = {
    Text = "Als sie an der Kapitänskajüte vorbeiging, drang die ruhige Stimme gerade in ihr Ohr."
  },
  AvgDialog_118958_Content_40 = {
    Text = "Die schwere Riesenklinge zog Funken über das Deck, als der Riese aus der Dunkelheit der Nacht trat, den Schädel des Steuermanns zertrümmerte und der Hexe vor ihm ein grausames Lächeln zeigte."
  },
  AvgDialog_118958_Content_41 = {
    Text = "Hinter ihm steht ein Barbar in einem blaugrauen Ölzeugregenmantel, der eine Klinge in der Hand hält und gierig auf den Befehl zum Töten wartet."
  },
  AvgDialog_118958_Content_42 = {
    Text = "Goliath... du willst immer noch nicht aufgeben?"
  },
  AvgDialog_118958_Content_43 = {
    Text = "Sammle die Seemänner, um Chaos zu erzeugen... in dem Wahn, das Paradies zu stören..."
  },
  AvgDialog_118958_Content_44 = {
    Text = "Es tut mir leid, ich bin nicht Teil dieser Ruhe. Diesmal, das nächste Mal, das übernächste Mal... Die Philistinen werden sich niemals damit abfinden, in Ewigkeit unterlegen zu sein."
  },
  AvgDialog_118958_Content_45 = {
    Text = "Komm, Philister!"
  },
  AvgDialog_118958_Content_46 = {
    Text = "In der bösen Stimme erscheinen die mit Ölschutzjacken bekleideten Barbaren, bewaffnet mit Klingen, zahlreich aus den Schatten."
  },
  AvgDialog_118958_Content_47 = {
    Text = "Das tiefe Brüllen zittert vor Aufregung. Sie warten gierig auf den Moment, in dem der Ruhm zurückkehrt, und warten auf den Befehl, alles zu massakrieren."
  },
  AvgDialog_118958_Content_48 = {
    Text = "<Big:Tötet sie!>"
  },
  AvgDialog_118958_Content_49 = {
    Text = "Ein grober Kriegsgesang durchbrach den Nachthimmel über dem Meer, während die barbarischen Stämme mit unglaublicher Geschwindigkeit die Taue schwenkten und in die Menschenmenge auf dem Deck schlugen."
  },
  AvgDialog_118958_Content_5 = {
    Text = "Ich weiß, wer der Meister des Geheimgangs ist, und ich kann euch helfen, die Grenzen des Geheimgangs zu überwinden und in die reale Welt zurückzukehren."
  },
  AvgDialog_118958_Content_50 = {
    Text = "Die seit langem von Küstenschlägen lebenden Philistine stürmten wie Haie, die den Geruch von Blut riechen, gierig und brutal auf ihre Beute zu und zerfetzten mit ihren messerscharfen gebogenen Klingen die Körper ihrer Feinde."
  },
  AvgDialog_118958_Content_51 = {
    Text = "Mein Herr, bitte höre den Ruf deiner Gläubigen... bitte segne dein Volk..."
  },
  AvgDialog_118958_Content_52 = {
    Text = "Miryam breitete die Arme aus, während das dunkle Licht allmählich sich ausbreitete."
  },
  AvgDialog_118958_Content_53 = {
    Text = "Die in seltsame schwarze Roben gehüllten Seefahrer gaben keinen Laut von sich, wie eine Gruppe frommer schwarzer Geister, die still in den tiefen Segen eintauchten und schweigend die Dolche in die Brust der Feinde stießen."
  },
  AvgDialog_118958_Content_54 = {
    Text = "Blaugrau und schwarzviolett, zwei klar voneinander getrennte Truppen kämpfen in dieser beweglichen Hölle bis zum Tod."
  },
  AvgDialog_118958_Content_55 = {
    Text = "Schlachtet, meine Verwandten... hier, lasst die Herrlichkeit der Philistinen wiederauferstehen!"
  },
  AvgDialog_118958_Content_56 = {
    Text = "Die riesige Klinge schnitt ungehindert den Kopf des vor ihm stehenden Seefahrer-Gläubigen ab, und das spritzende salzige Blut färbte Goliaths halbes Gesicht blutrot."
  },
  AvgDialog_118958_Content_57 = {
    Text = "Er leckte das Blut von seinem Gesicht und schwang unter dem Licht des Donners die riesige Klinge in seiner Hand, tötete jeden Gläubigen, der sich ihm in den Weg stellte."
  },
  AvgDialog_118958_Content_58 = {
    Text = "Blut strömte gerade aus dem warmen Körper und wurde im Handumdrehen von dem heftigen Regen verdünnt, vermischte sich mit dem Meerwasser und bildete auf dem heftig schwankenden Deck blutrote, glitschige Bäche."
  },
  AvgDialog_118958_Content_59 = {
    Text = "<Shake:Mein Herr, ich habe Ihren Befehl gehört. Ihre Gläubigen werden mit Ihnen ins Göttliche Reich zurückkehren...>"
  },
  AvgDialog_118958_Content_6 = {
    Text = "Das Mädchen tat so, als wäre sie ruhig, und trat leise auf."
  },
  AvgDialog_118958_Content_60 = {
    Text = "Ritual, Sturm, Kampf..."
  },
  AvgDialog_118958_Content_61 = {
    Text = "Mitten in diesem Chaos, unter der unheilvollen Elfenbeinstatue am Bug des Schiffes, stand Miryam und flüsterte fromm im Sturm."
  },
  AvgDialog_118958_Content_62 = {
    Text = "Sie ignorierte das Blutmeer und die Leichenschauplätze um sie herum, der Dolch strich an ihrem Ohr vorbei, die riesigen Wellen durchnässerten ihren ganzen Körper, sie bemerkte nichts davon."
  },
  AvgDialog_118958_Content_63 = {
    Text = "Möge Ihr Orakel uns leiten, möge Ihr Leib uns umhüllen."
  },
  AvgDialog_118958_Content_64 = {
    Text = "Miryam... gib auf! Wir können Lemuria nicht erreichen!"
  },
  AvgDialog_118958_Content_65 = {
    Text = "Nein... Er hat es mir versprochen, und Sie haben Sein Orakel gehört, oder?"
  },
  AvgDialog_118958_Content_66 = {
    Text = "Miryam blickte fromm in den Himmel."
  },
  AvgDialog_118958_Content_67 = {
    Text = "Der Sturm ist dein Atem, der Donner ist dein Kriegstrommel!"
  },
  AvgDialog_118958_Content_68 = {
    Text = "Bitte, führe dieses irrende Lamm, <Big: weise den Kurs zu deinem Reich!>"
  },
  AvgDialog_118958_Content_69 = {
    Text = "Ein greller Blitz zerriss den Himmel und erhellte sofort ihre fanatisch frommen Augen."
  },
  AvgDialog_118958_Content_7 = {
    Text = "Aber meine Unterstützung ist bedingt."
  },
  AvgDialog_118958_Content_70 = {
    Text = "Das Mädchen in schwarzem Tuch kauert still in einer Ecke des Schiffs, ihr leerer Blick ist hoffnungslos auf das Schlachtfeld gerichtet, wie eine Puppe, die im Schrotthaufen zurückgelassen wurde."
  },
  AvgDialog_118958_Content_71 = {
    Text = "Los, wir gehen runter!"
  },
  AvgDialog_118958_Content_72 = {
    Text = "Ich bin verantwortlich für die Abholung der Elfenbeinstatue!"
  },
  AvgDialog_118958_Content_73 = {
    Text = "Ich werde die Gelegenheit nutzen, während sie im Chaos sind, um Murphy zu retten!"
  },
  AvgDialog_118958_Content_8 = {
    Text = "Deine Bedingung ist...?"
  },
  AvgDialog_118958_Content_9 = {
    Text = "Töte den Herrscher des Geheimgangs, erobere die Elfenbeinstatue und übertrage die Macht des Geheimgangs an mich."
  },
  AvgDialog_118959_Content_1 = {
    Text = "Ich tötete mich selbst und nahm die Krone in die Hand. Außer der Freiheit erhielt ich alles, wonach ich mich sehnte."
  },
  AvgDialog_118959_Content_10 = {
    Text = "Weil du anders bist."
  },
  AvgDialog_118959_Content_11 = {
    Text = "Was unterscheidet mich von ihnen? Sie sind nur die Opfergaben in deinen Augen, sie sind nur das Futter für dieses faulige Fleisch."
  },
  AvgDialog_118959_Content_12 = {
    Text = "Murphy hielt den schmutzigen Klumpen in ihren Händen, das Blut floss in Strömen herab."
  },
  AvgDialog_118959_Content_13 = {
    Text = "Nein, du bist anders als sie."
  },
  AvgDialog_118959_Content_14 = {Text = "Weil..."},
  AvgDialog_118959_Content_15 = {
    Text = "Wir sind zusammen einen Weg gegangen."
  },
  AvgDialog_118959_Content_16 = {
    Text = "Ich erinnere mich an den Tag, an dem du den heiligen Embryo in deine Brust implantiert hast, und du hast gesagt, du möchtest Churros essen."
  },
  AvgDialog_118959_Content_17 = {
    Text = "Du hast plötzlich festgestellt, dass es zu lecker ist, um es alleine zu genießen, und zögerst, mir die Hälfte zu geben."
  },
  AvgDialog_118959_Content_18 = {
    Text = "Später begann der heilige Embryo zu wachsen, du hattest anhaltendes Fieber, und wir haben alles versucht, um die Temperatur zu senken, letztendlich konnten wir dich nur in die Eisgrube in der Antarktis bringen."
  },
  AvgDialog_118959_Content_19 = {
    Text = "Das kann uns wirklich viel Ärger bereiten."
  },
  AvgDialog_118959_Content_2 = {
    Text = "Doch ich, die das heilige Kind geboren hat, konnte die Gnade der Gottheit nicht erlangen und nicht den Weg nach Lemuria weisen..."
  },
  AvgDialog_118959_Content_20 = {
    Text = "Selbst in solch schwierigen Umständen hältst du weiterhin an deiner Pflicht als Göttliche Mutter fest."
  },
  AvgDialog_118959_Content_21 = {
    Text = "Die meisten Priester ertragen die Kälte und begleiten, erwarten und beten am Altar in der Antarktis."
  },
  AvgDialog_118959_Content_22 = {
    Text = "Und du hast die Erwartungen nicht enttäuscht und bist die erste Mutter geworden, die das heilige Kind geboren hat."
  },
  AvgDialog_118959_Content_23 = {
    Text = "Wir sind gemeinsam an diesem Moment angekommen."
  },
  AvgDialog_118959_Content_24 = {
    Text = "Wir werden gemeinsam in das ewige Göttliche Reich segeln."
  },
  AvgDialog_118959_Content_25 = {
    Text = "Miryam ging langsam und fest zu Murphy und beugte sich hinunter."
  },
  AvgDialog_118959_Content_26 = {
    Text = "Du bist die ehrwürdige Göttliche Mutter, und ich bin bereit, ewig zu deinen Füßen zu knien und dir meine lebenslange Frommigkeit darzubringen."
  },
  AvgDialog_118959_Content_27 = {
    Text = "Ich bin bereit, dich ewig mit der Haltung zu betrachten, die ich für diese “Gottheit“ hege."
  },
  AvgDialog_118959_Content_28 = {
    Text = "Murphy starrte gedankenverloren auf Miryam."
  },
  AvgDialog_118959_Content_29 = {
    Text = "Miryam kniete halb und ergriff ihren Handrücken, auf den sie einen frommen Kuss niederließ."
  },
  AvgDialog_118959_Content_3 = {
    Text = "Also hast du diesen niemals endenden Traum geschaffen..."
  },
  AvgDialog_118959_Content_30 = {
    Text = "Komm zurück zu mir, okay, “Göttliche Mutter“?"
  },
  AvgDialog_118959_Content_31 = {
    Text = "Murphy senkte den Kopf. Der Wind legte sich, in den kleinen Ritzen des Universums herrschte stille."
  },
  AvgDialog_118959_Content_32 = {
    Text = "Alle deine Geschichten handeln vom Heiligen Embryo. Alle deine Bezeichnungen sind untrennbar mit der Göttlichen Mutter verbunden."
  },
  AvgDialog_118959_Content_33 = {
    Text = "Du verstehst immer noch nicht... und du wirst es auch nie verstehen..."
  },
  AvgDialog_118959_Content_34 = {
    Text = "Zwischen den Zähnen dringen einige geflüsterte Worte hervor."
  },
  AvgDialog_118959_Content_35 = {
    Text = "Nur du, der nur von Gebet, Zeremonien, dem Göttlichen Reich, Lemuria und der Geburt der Gottheit weiß..."
  },
  AvgDialog_118959_Content_36 = {
    Text = "Wird nie verstehen."
  },
  AvgDialog_118959_Content_37 = {
    Text = "Alles, was ich getan habe, das Ziel, das ich mit Zähnen zusammengebissen erreicht habe, diese Illusion, die ich mühsam aufrechterhalte..."
  },
  AvgDialog_118959_Content_38 = {
    Text = "Ich möchte dich nur so ansprechen, wie du es wirklich verdienst..."
  },
  AvgDialog_118959_Content_39 = {Text = "Mutter..."},
  AvgDialog_118959_Content_4 = {
    Text = "Wenn ich es nicht tue, wird sie mir mit eigenen Händen das Herz herausreißen..."
  },
  AvgDialog_118959_Content_40 = {
    Text = "Der Sturm über dem Meer verdeckte das ohnehin schon verschwommene Flüstern."
  },
  AvgDialog_118959_Content_41 = {
    Text = "Schade, schade."
  },
  AvgDialog_118959_Content_42 = {
    Text = "Murphy wischte sich die Tränen weg."
  },
  AvgDialog_118959_Content_43 = {
    Text = "Alle meine Erwartungen an dich sind nur ein Delirium, und das Gleichgewicht, das durch Lügen aufrechterhalten wird, ist nur eine ewige Illusion."
  },
  AvgDialog_118959_Content_44 = {
    Text = "Du wirst niemals meine Mama sein."
  },
  AvgDialog_118959_Content_45 = {
    Text = "Die Murphy, die du gekannt hast, ist längst tot. Ihr Tod kam mit der Geburt des Gottes."
  },
  AvgDialog_118959_Content_46 = {
    Text = "Hier steht ein Erwachter, geboren aus der Asche des Lebens und dem Silber des Luminis..."
  },
  AvgDialog_118959_Content_47 = {
    Text = "Die Person, die mich aus den Trümmern erweckt hat... Nein, kann man das als Mensch bezeichnen?"
  },
  AvgDialog_118959_Content_48 = {
    Text = "Mein Verketter steht direkt vor euch."
  },
  AvgDialog_118959_Content_49 = {
    Text = "Sie hob sanft das Wickeln an, und auf ihrem Gesicht erhaschtest du eine nie zuvor gesehene, fast gruselige Zärtlichkeit."
  },
  AvgDialog_118959_Content_5 = {
    Text = "Opfere mich dem verehrten König von ihr."
  },
  AvgDialog_118959_Content_50 = {
    Text = "Ich brachte es in diese Welt... und es brachte mich wieder in diese Welt..."
  },
  AvgDialog_118959_Content_51 = {
    Text = "Die vom Kurs abweichenden Schicksale sind untrennbar miteinander verbunden, der verzerrte Kreislauf endet niemals."
  },
  AvgDialog_118959_Content_52 = {
    Text = "Ein Vater bringt Kinder zur Welt, die Tochter trägt den Vater, der Vater erweckt die Tochter erneut..."
  },
  AvgDialog_118959_Content_53 = {
    Text = "Niemand kommt, um diese schwere Bindung zu durchtrennen, niemand kommt, um die Verwirrung zu hindern, die durch die unendliche Verbindung des Blutes entsteht."
  },
  AvgDialog_118959_Content_54 = {
    Text = "Glaubst du, dass du die erste Person bist, die in die Schleife geraten ist?"
  },
  AvgDialog_118959_Content_55 = {
    Text = "Davor bin ich unzählige Male in die Schleife eingetreten, und das Ende jeder Schleife ist ein unaussprechlicher Albtraum."
  },
  AvgDialog_118959_Content_56 = {
    Text = "Weil ich Lemuria abgelehnt habe, endete ich durch Miryams Durchstechen des Brustkorbs."
  },
  AvgDialog_118959_Content_57 = {
    Text = "Von Goliath mit Ketten gefangen, die Elfenbeinstatue geraubt, endete das Schicksal mit dem Untergang des gesamten Schiffs."
  },
  AvgDialog_118959_Content_58 = {
    Text = "Und in dem Traum öffnete eine schmale, aber kräftige Gestalt einen Fluchtweg für mich."
  },
  AvgDialog_118959_Content_59 = {
    Text = "Ich habe immer geglaubt, dass das alles keine echten Enden sein werden. \n Ich warte auf das Ende, das nur für “dieses Ich“ bestimmt ist."
  },
  AvgDialog_118959_Content_6 = {
    Text = "Also sagst du, dass sie die ganze Zeit auf mich gewartet hat... Ich verstehe nicht."
  },
  AvgDialog_118959_Content_60 = {
    Text = "Das wahre Ende kann kommen."
  },
  AvgDialog_118959_Content_61 = {
    Text = "Lasst dieses Schiff kentern."
  },
  AvgDialog_118959_Content_62 = {
    Text = "Der schwarze Vorhang ist wie der Seidenstoff, der vom Himmel herabfällt, und verhüllt das Schiff und trennt es von der lichtlosen schwarzen Sonne und der Außenwelt."
  },
  AvgDialog_118959_Content_63 = {
    Text = "Das grenzenlose Meer stieg auf und begrub das gesamte Schiff Paradeis in der dunklen Nichtigkeit der Tiefe."
  },
  AvgDialog_118959_Content_64 = {
    Text = "Ein weiteres Mal bist du in die grenzenlose Dunkelheit gefallen."
  },
  AvgDialog_118959_Content_7 = {
    Text = "<Shake:Warum? Miryam, warum?>"
  },
  AvgDialog_118959_Content_8 = {
    Text = "Wenn ich nicht die qualifizierte Göttliche Mutter bin, warum gibst du mich dann nicht einfach wie gewohnt auf?"
  },
  AvgDialog_118959_Content_9 = {
    Text = "<Red:Aufgeben mich... Gib mir Freiheit...>"
  },
  AvgDialog_118960_Content_1 = {
    Text = "Ewiger Schleier"
  },
  AvgDialog_118960_Content_10 = {
    Text = "Nein, ich konnte alles im Traum manipulieren, ich konnte das Ende und den Beginn der Schleife entscheiden, ich..."
  },
  AvgDialog_118960_Content_11 = {
    Text = "Die Götter gaben dir die Macht, zu träumen, doch du bist in deiner eigenen Besessenheit gefangen und missbrauchst ihren guten Willen."
  },
  AvgDialog_118960_Content_12 = {Text = "Leihen...?"},
  AvgDialog_118960_Content_13 = {
    Text = "Weißt du noch, woher die Statue stammt?"
  },
  AvgDialog_118960_Content_14 = {
    Text = "Statue... Sein Abbild..."
  },
  AvgDialog_118960_Content_15 = {
    Text = "Bei der Geburt... des Heiligen Kindes..."
  },
  AvgDialog_118960_Content_16 = {
    Text = "Das stimmt nicht, in den sieben Tagen nach der ersten Geburt des Heiligen Kindes habe ich diese Statue nie gesehen."
  },
  AvgDialog_118960_Content_17 = {
    Text = "Sein Abbild... ist..."
  },
  AvgDialog_118960_Content_18 = {
    Text = "Kein Wunder, dass ich immer das Gefühl habe, dass ein Teil des vollständigen Lösungsansatzes fehlt."
  },
  AvgDialog_118960_Content_19 = {
    Text = "%player%, erinnerst du dich an unser Rätsel?\nDie Entstehungszeit des Geheimgangs, bevor die Auflösung die Welt verschlang und die Sonne sich in die schwarze Sonne verwandelte."
  },
  AvgDialog_118960_Content_2 = {
    Text = "<Red:Es sollte nicht enden>"
  },
  AvgDialog_118960_Content_20 = {
    Text = "Doch das Geburtsritual des Heiligen Kindes, Murphys Opferritual und Wiedergeburt fanden eindeutig nach der Geburt der schwarzen Sonne statt."
  },
  AvgDialog_118960_Content_21 = {
    Text = "Mit anderen Worten, zu jener Zeit war Murphy nur ein geistig lebendiger Mensch, der nicht in der Lage war, diesen Traum zu erschaffen."
  },
  AvgDialog_118960_Content_22 = {
    Text = "Die Person, die zuvor die Macht innehatte... sollte sein..."
  },
  AvgDialog_118960_Content_23 = {
    Text = "Der Götterkönig dieser Welt ist längst geboren... Nein, besser gesagt, er ist nie gestorben."
  },
  AvgDialog_118960_Content_24 = {
    Text = "Du kannst sein Bewusstsein nicht erwecken, weil es noch im langen Schlaftraum verweilt."
  },
  AvgDialog_118960_Content_25 = {
    Text = "Er kann es nicht ertragen, dass du durch das Opferritual stirbst, und hat dir absichtlich einen Hauch von Stärke gegeben, um dir einen Traum im Traum zu erschaffen."
  },
  AvgDialog_118960_Content_26 = {
    Text = "Leider verlangst du nach zu viel... und so zerfallen die Träume immer wieder und beginnen von neuem, das ist die Essenz der Paradies."
  },
  AvgDialog_118960_Content_27 = {
    Text = "Es ist aus deinem Wunsch geboren, aber es ist nicht dein Sklave..."
  },
  AvgDialog_118960_Content_28 = {
    Text = "<Yellow:Also, jetzt wird Er die Mission erfüllen, die der Schöpfer Ihm gegeben hat.>"
  },
  AvgDialog_118960_Content_29 = {
    Text = "Der Himmel beginnt zu brodeln, ein schwarzes Tuch verhüllt das Sichtfeld, ein riesiger Körper erhebt sich wie ein Gebirgsgipfel."
  },
  AvgDialog_118960_Content_3 = {Text = "?!"},
  AvgDialog_118960_Content_30 = {
    Text = "Es ist nicht aus dem Abgrund aufgestiegen, sondern der “Wille“ selbst hat die Hülle der Dimension durchbrochen."
  },
  AvgDialog_118960_Content_31 = {
    Text = "Unter der erstickenden Kuppel erscheint Sein Körper lautlos: blass, zart, mit verdrehten Gelenken, wie die deformierten Skelette gequälter Heiligen."
  },
  AvgDialog_118960_Content_32 = {
    Text = "<Big:<Shake:...!!!>>"
  },
  AvgDialog_118960_Content_33 = {Text = "Murphy..."},
  AvgDialog_118960_Content_34 = {
    Text = "Die Silhouette dieser riesigen Gestalt ist offensichtlich die dir vertraute Gestalt des Mädchens."
  },
  AvgDialog_118960_Content_35 = {
    Text = "<Red:Traum......muss......fortgesetzt werden......>"
  },
  AvgDialog_118960_Content_4 = {
    Text = "<Red:Kann nicht enden>"
  },
  AvgDialog_118960_Content_5 = {
    Text = "Der Himmel beginnt sich zu schließen, ein schwarzes, dünnes Tuch verdeckt den Himmel und die Sonne und formt einen falschen Himmel."
  },
  AvgDialog_118960_Content_6 = {
    Text = "Kratzen, du hörst das Geräusch des wieder drehenden Spinnrades."
  },
  AvgDialog_118960_Content_7 = {
    Text = "Warum? Warum? Ich habe doch entschieden, diesen Traum zu beenden..."
  },
  AvgDialog_118960_Content_8 = {
    Text = "Denn... oh, ehrwürdige Göttliche Mutter, der Herrscher dieses Traums bist nicht du."
  },
  AvgDialog_118960_Content_9 = {Text = "??!!"},
  AvgDialog_118961_Content_1 = {Text = "Wahn"},
  AvgDialog_118961_Content_10 = {
    Text = "Bist du überrascht? Der einzige Fluchtweg auf diesem Schiff liegt in meiner Hand."
  },
  AvgDialog_118961_Content_11 = {
    Text = [[
Goliath packte Murphy und hielt die riesige Klinge an ihren Hals. 
 Blut rannte von ihrem Hals und floss in die unheilbare Narbe an ihrer Brust.]]
  },
  AvgDialog_118961_Content_12 = {Text = "Murphy!"},
  AvgDialog_118961_Content_13 = {
    Text = "Göttliche Mutter!"
  },
  AvgDialog_118961_Content_14 = {
    Text = "Entschuldigung, ich kann mich immer noch nicht beruhigen..."
  },
  AvgDialog_118961_Content_15 = {
    Text = "Es ist nicht Miryam, die das kleine Mädchen nicht freigeben will, sondern das kleine Mädchen, das Miryam fesselt."
  },
  AvgDialog_118961_Content_16 = {
    Text = "Es ist sie, die nicht möchte, nicht will und nicht wagt, Miryam die Wahrheit entdecken zu lassen."
  },
  AvgDialog_118961_Content_17 = {
    Text = "Was du sagst, ist die Wahrheit?"
  },
  AvgDialog_118961_Content_18 = {
    Text = "Sie weiß auch nicht, wo dieses Lemuria ist, sie hat das wahre Antlitz der Götter nie gesehen."
  },
  AvgDialog_118961_Content_19 = {
    Text = "Weil sie es nicht weiß, kann dieses Schiff nur auf dem Meer treiben, einfach so immer weiter treiben."
  },
  AvgDialog_118961_Content_2 = {
    Text = "Warum hältst du Murphy in diesem Moment, in dem der Gott bereits geboren wurde, so fest in deiner Hand?"
  },
  AvgDialog_118961_Content_20 = {
    Text = "Ich weiß nicht, mit welchen Worten dieses kleine Mädchen euch beiden einen Zauber auferlegt hat..."
  },
  AvgDialog_118961_Content_21 = {
    Text = "Ein Seefahrer-Hauptopfer, ein geheimnisvoller Mensch, der vom Himmel herabkommt, wird von einem kleinen Mädchen herumgeführt."
  },
  AvgDialog_118961_Content_22 = {
    Text = "Hast du etwa vergessen, als sie geflohen ist?"
  },
  AvgDialog_118961_Content_23 = {Text = "Laufen."},
  AvgDialog_118961_Content_24 = {
    Text = "Das Mädchen läuft."
  },
  AvgDialog_118961_Content_25 = {
    Text = "Sie weiß nicht, wo das Ende der Reise ist, noch ob sie den Augen der Mutter entkommen kann."
  },
  AvgDialog_118961_Content_26 = {
    Text = "<Shake:Ha, Ha...>"
  },
  AvgDialog_118961_Content_27 = {
    Text = "Niemand wartete vorne auf sie, und das merkwürdig komische Geräusch von Flossen, die auf den Boden schlugen, wurde immer dichter."
  },
  AvgDialog_118961_Content_28 = {
    Text = "Die Nachricht über das Verschwinden der Heiligen hat sich verbreitet, die Seefahrer versammeln sich."
  },
  AvgDialog_118961_Content_29 = {
    Text = "Verdammte, diese nervigen Typen."
  },
  AvgDialog_118961_Content_3 = {
    Text = "Deine anklagende Stimme ist ohrenbetäubend."
  },
  AvgDialog_118961_Content_30 = {
    Text = "Hinter dem Glanz trat langsam die purpurne Gestalt hervor, die ihr Versagen symbolisierte..."
  },
  AvgDialog_118961_Content_31 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_118961_Content_32 = {
    Text = "Murphy in dieser Welt konnte nicht entkommen."
  },
  AvgDialog_118961_Content_33 = {
    Text = "Weil es die Person war, die sie zu den Seefahrern brachte und dann plötzlich bereute, sie wieder herauszuschicken..."
  },
  AvgDialog_118961_Content_34 = {
    Text = "Ist für immer in der Auflösungs-Katastrophe des großen Ausbruchs verschwunden."
  },
  AvgDialog_118961_Content_35 = {
    Text = "Dieses kleine Mädchen ist nicht freiwillig zur Göttlichen Mutter geworden, so wie ich nicht freiwillig dein Sklave bin."
  },
  AvgDialog_118961_Content_36 = {
    Text = "Wir tun das alles für... die Dinge, die wir wollen."
  },
  AvgDialog_118961_Content_37 = {
    Text = "<Shake:Nein, ich habe nichts, was ich will.> Ich... ich will nichts."
  },
  AvgDialog_118961_Content_38 = {
    Text = "Willst du nichts? Nein, du willst viel."
  },
  AvgDialog_118961_Content_39 = {
    Text = "Du möchtest sowohl das wohlhabende Leben der Göttlichen Mutter genießen als auch die Pflichten eines Führers nicht übernehmen."
  },
  AvgDialog_118961_Content_4 = {
    Text = "In deiner Hand, was meinst du...?"
  },
  AvgDialog_118961_Content_40 = {
    Text = "Du hast Angst, von anderen verlassen zu werden, deshalb behandelst du andere als Puppen in deinem Leben, als Spielzeug für dein Teekränzchen."
  },
  AvgDialog_118961_Content_41 = {
    Text = "Alle paar Zeitintervalle löschst du das Gedächtnis aller an Bord und beginnst einen neuen Zyklus."
  },
  AvgDialog_118961_Content_42 = {
    Text = "Kleines Mädchen, lass mich dir sagen: Sei nicht zu schlau, alles, was man in dieser Welt erhält, hat seinen Preis."
  },
  AvgDialog_118961_Content_43 = {
    Text = "Dachtest du, dass niemals jemand deine kleinen Tricks entdecken würde? Dachte, mit dieser Elfenbeinstatue seist du unbesiegbar?"
  },
  AvgDialog_118961_Content_44 = {
    Text = "Murphy ballte die Elfenbeinstatue fest in ihrer Hand."
  },
  AvgDialog_118961_Content_45 = {
    Text = "Sei nicht dumm, du dummer Junge."
  },
  AvgDialog_118961_Content_46 = {
    Text = "Glaubst du, ich wüsste nichts über dein Verhalten? Ich bin nur noch nicht bereit, dir direkt entgegenzutreten."
  },
  AvgDialog_118961_Content_47 = {
    Text = "In jeder Wiederholung versuche ich, die Methode des Schiffsraubs zu ändern. Dich bedrohen, Miryam bedrohen, das Kraftwerk sprengen..."
  },
  AvgDialog_118961_Content_48 = {
    Text = "Später entdeckte ich, dass ich keine Chance hatte, mich gegen dich zu wehren, solange die verdammte Elfenbeinstatue noch da war."
  },
  AvgDialog_118961_Content_49 = {
    Text = "Goliaths spöttisches Lachen hallte über das Deck."
  },
  AvgDialog_118961_Content_5 = {
    Text = "Du hast diesen Traum erschaffen und Murphy in der Schleife des Traums gefangen, nicht wahr?"
  },
  AvgDialog_118961_Content_50 = {
    Text = "Bis vor ein paar Monaten die Aktion in der Nekropolis, die von diesem kleinen Ding hier ruiniert wurde."
  },
  AvgDialog_118961_Content_51 = {
    Text = "Nicht genug Silberkerne erbeutet, die göttliche Kraft der Elfenbeinstatue schwindet, die Erinnerungen der Erwecker an Bord sind längst löchrig geworden."
  },
  AvgDialog_118961_Content_52 = {
    Text = "Erinnerst du dich an alles... Erinnern sie sich an alles?..."
  },
  AvgDialog_118961_Content_53 = {
    Text = "Also, dass Wilhelm sich an nichts erinnert, liegt daran, dass er aus einer anderen Welt stammt."
  },
  AvgDialog_118961_Content_54 = {
    Text = "Andere spirituelle Wesen sind nicht anders als ich... Sie wissen, dass sich Himmel und Erde umkehren und die Zeit zurückfließt."
  },
  AvgDialog_118961_Content_55 = {
    Text = "<Small:<Shake:Meinst du alle... einschließlich... sie?>>"
  },
  AvgDialog_118961_Content_56 = {
    Text = "Murphy senkte den Kopf, ihre Stimme war so leise, dass sie fast verschwommen klang, ihr Blick war unstet und wanderte immer wieder zu der Frau an ihrer Seite, doch bevor sie ihren Blick berührte, zog sie ihn sofort zurück."
  },
  AvgDialog_118961_Content_57 = {
    Text = "Du dummes kleines Mädchen, ich spreche von allen Erweckern."
  },
  AvgDialog_118961_Content_58 = {
    Text = "Darunter ist natürlich auch die dumme Frau Miryam."
  },
  AvgDialog_118961_Content_59 = {
    Text = "Meinst du...?"
  },
  AvgDialog_118961_Content_6 = {
    Text = "Miryam überlegte, bevor sie sprach, als ein tiefes Schmunzeln hinter dir ertönte."
  },
  AvgDialog_118961_Content_60 = {
    Text = "Miryam erinnert sich an die Dinge, die bei jeder Wiedergeburt geschehen, sie wartet immer wieder auf dich."
  },
  AvgDialog_118961_Content_61 = {
    Text = "Ich kann die Träume von diesem Typen dort drüben verbinden, ich habe das Ende dieser Welt bezeugt. Ich schätze, Miryam kann das auch."
  },
  AvgDialog_118961_Content_62 = {
    Text = "Aber in allen mir bekannten Zyklen hat sie nichts unternommen, sondern nur passiv gewartet."
  },
  AvgDialog_118961_Content_63 = {
    Text = "Goliath hob das Kinn und deutete auf die schweigende Miryam neben ihm."
  },
  AvgDialog_118961_Content_64 = {
    Text = "Du glaubst, dass sie freiwillig in dieser von dir geschaffenen Festung gefangen ist."
  },
  AvgDialog_118961_Content_65 = {
    Text = "Miryam antwortete Goliath mit Schweigen auf seine Vermutungen."
  },
  AvgDialog_118961_Content_66 = {
    Text = "<Shake:Warum? Ich verstehe nicht, warum?>"
  },
  AvgDialog_118961_Content_67 = {
    Text = "Sollte ich für dich nicht ein Fehlschlag, ein überflüssiges Werkzeug sein?"
  },
  AvgDialog_118961_Content_68 = {
    Text = "Solltest du mich nicht so aufgeben wie sie?"
  },
  AvgDialog_118961_Content_7 = {
    Text = "Lasst mich euch erzählen."
  },
  AvgDialog_118961_Content_8 = {
    Text = "<Shake:Weil dieses Mädchen namens Murphy eine Betrügerin ist.>"
  },
  AvgDialog_118961_Content_9 = {
    Text = "Die von den Philistinen geführte Menge machte einen kleinen Spalt auf, und zwischen der Lücke wurde ein hilfloser Murphy von einem Seemann herausgeschoben."
  },
  AvgDialog_118962_Content_1 = {
    Text = "Du schließt die Tür des Cockpits und verriegelst sie. Während du den Schritten der Verfolger lauschst, die sich in eine andere Richtung wenden, drehst du dich um, um dein kleines Geisel zu beobachten."
  },
  AvgDialog_118962_Content_10 = {
    Text = "Wenn sie ihrer Pflicht nicht nachkommen... wo wären sie dann?"
  },
  AvgDialog_118962_Content_11 = {
    Text = "Nach Goliaths Temperament sollte er nicht im Untergrund-Casino faulenzen."
  },
  AvgDialog_118962_Content_12 = {
    Text = "Er plant bestimmt etwas im Verborgenen..."
  },
  AvgDialog_118962_Content_13 = {
    Text = "Wilhelm hält Wache in Murphys Schlafzimmer."
  },
  AvgDialog_118962_Content_14 = {
    Text = "Selbst wenn ich allein bin, kann ich sie mindestens zwanzig Minuten aufhalten... das reicht."
  },
  AvgDialog_118962_Content_15 = {
    Text = "Die Schritte wurden plötzlich seltener."
  },
  AvgDialog_118962_Content_16 = {
    Text = "Willkommen, Hohepriester!"
  },
  AvgDialog_118962_Content_17 = {
    Text = "Hohepriester, wir haben die Eindringlinge im Schlafgemach der Göttlichen Mutter eingekesselt! Sie brauchen nur einen Befehl zu geben..."
  },
  AvgDialog_118962_Content_18 = {
    Text = "Nicht nötig, die Göttliche Mutter ist nicht mehr hier."
  },
  AvgDialog_118962_Content_19 = {
    Text = "(Entdeckt?!)"
  },
  AvgDialog_118962_Content_2 = {Text = "Hmph..."},
  AvgDialog_118962_Content_20 = {
    Text = "Wie wäre es, wenn wir im Zimmer reden?"
  },
  AvgDialog_118962_Content_21 = {
    Text = "Worüber möchtest du sprechen?"
  },
  AvgDialog_118962_Content_22 = {
    Text = "Egal ob du oder deine Freunde, seit ihr an Bord seid, werden alle Seefahrer mit Respekt behandelt."
  },
  AvgDialog_118962_Content_23 = {
    Text = "Die beiden jedoch danken mit Verrat, indem sie die Göttliche Mutter entführen, wodurch das entscheidende Navigationsritual nicht rechtzeitig abgehalten werden kann."
  },
  AvgDialog_118962_Content_24 = {
    Text = "Sollten wir diesen Moment der Ausrichtung der Sterne verpassen, müssen wir unsere großen Wünsche noch sechzig Mal bis zur Drehung der Sterne warten."
  },
  AvgDialog_118962_Content_25 = {
    Text = "Es muss einen Grund dafür geben, und ich möchte die Gründe von euch beiden hören."
  },
  AvgDialog_118962_Content_26 = {
    Text = "Weil der Hüter die Schleife erlebt hat? Weil das Mädchen einst ein Teil von Misaq war?"
  },
  AvgDialog_118962_Content_27 = {
    Text = "William hatte noch nicht die Fäden der Antwort entwirrt, als hinter ihm plötzlich ein widerliches, glitschiges Wabern zu hören war."
  },
  AvgDialog_118962_Content_28 = {
    Text = "Er drehte sich abrupt um — die Pupillen verengten sich sofort. Mehrere Fischmenschen hatten das gesamte Fenster wie eine übergelaufene, schmutzige Flut gefüllt."
  },
  AvgDialog_118962_Content_29 = {
    Text = "Die verzerrten Gliedmaßen drängten sich hastig in den Raum, während der stinkende, zähe Körperflüssigkeit wie ein Wasserfall herabströmte und den Teppich in ein glitschiges Moor verwandelte."
  },
  AvgDialog_118962_Content_3 = {
    Text = "Sie zog einen kleinen Spiegel hervor, den sie irgendwoher hatte, und ordnete sorgfältig die strubbeligen Haare an ihrer Stirn."
  },
  AvgDialog_118962_Content_30 = {
    Text = "Er war wie ein Nagel, festgenagelt an dem Punkt des Todes, wo zwei böse Strömungen kurz davor waren, sich zu treffen."
  },
  AvgDialog_118962_Content_31 = {
    Text = "Wie hast du das gemacht..."
  },
  AvgDialog_118962_Content_32 = {
    Text = "Das Bullauge ist gut zehn Meter hoch über dem Deck, und der Schutzherr hat nach seiner Flucht rechtzeitig das lange Seil durchtrennt."
  },
  AvgDialog_118962_Content_33 = {
    Text = "Wie sind sie lautlos durch die glatte Wand und das Fenster geschlüpft?"
  },
  AvgDialog_118962_Content_34 = {
    Text = "Das Göttliche Reich hat uns die Kraft gegeben, um dem Verderben entgegenzuwirken. Solche unbedeutenden Hindernisse können die Seefahrer natürlich nicht aufhalten."
  },
  AvgDialog_118962_Content_35 = {
    Text = "Ozeanlebewesen... die Saugfüße an den Füßen?"
  },
  AvgDialog_118962_Content_36 = {
    Text = "Neben den Seefahrern, die auf dem Kreuzfahrtschiff stationiert sind, sind die Meereslebewesen, die das gesamte Schiff umgeben, alle durch die spirituelle Anrufung meines Herrn herbeigekommen und gehorchen unserem Willen."
  },
  AvgDialog_118962_Content_37 = {
    Text = "Selbst wenn es nicht auf diese Weise ist, solltest du wissen, dass du mit einem so kleinen Raum nicht gegen die gesamte Seefahrer-Kirche ankommen kannst..."
  },
  AvgDialog_118962_Content_38 = {
    Text = "Die Ermittler von Misaq sind nicht so unüberlegt ... Sag mir, was du noch weißt?"
  },
  AvgDialog_118962_Content_39 = {
    Text = "<Big:<Shake:Krach——>>"
  },
  AvgDialog_118962_Content_4 = {
    Text = "Wo ist die Struktur, von der du sprichst...?"
  },
  AvgDialog_118962_Content_40 = {
    Text = "Ein ohrenbetäubendes, metallisches Zerreißen durchbrach den Himmel, begleitet von heftigem Zittern, als ob der Schiffsrumpf plötzlich von einer unsichtbaren, riesigen Hand ergriffen und heftig gedreht wurde!"
  },
  AvgDialog_118962_Content_41 = {
    Text = "Was ist los?!"
  },
  AvgDialog_118962_Content_42 = {
    Text = "Jemand zwingt die Kursänderung!"
  },
  AvgDialog_118962_Content_43 = {
    Text = "Das zehntausend Tonnen schwere Schiff wütete wie ein wütendes, außer Kontrolle geratenes Biest, drehte sich wild und wurde von den riesigen Wellen der Nachtmeere zerquetscht. Jeder heftige Ruck schien den Schiffsrumpf auseinanderzureißen!"
  },
  AvgDialog_118962_Content_44 = {
    Text = "Kraftwerk... es ist das Kraftwerk!"
  },
  AvgDialog_118962_Content_45 = {
    Text = "Goliath hat Geiseln genommen und das Kraftwerk eingenommen!"
  },
  AvgDialog_118962_Content_46 = {
    Text = "Wieder da..."
  },
  AvgDialog_118962_Content_47 = {
    Text = "Heftige Erschütterungen kommen wellenartig."
  },
  AvgDialog_118962_Content_48 = {Text = "Murphy..."},
  AvgDialog_118962_Content_49 = {
    Text = "Ich weiß, du wirst deinen Seniorstudenten bestimmt nicht loslassen, oder?"
  },
  AvgDialog_118962_Content_5 = {
    Text = "Direkt unter dem Platz des Kapitäns, hier."
  },
  AvgDialog_118962_Content_50 = {
    Text = "Ich verstehe das alles, jeder sagt, dass ich die wichtigste Person bin, aber in entscheidenden Momenten werfen sie mich ganz leicht weg."
  },
  AvgDialog_118962_Content_51 = {Text = "Ich..."},
  AvgDialog_118962_Content_52 = {
    Text = "Okay, okay, das sind nur ein paar nutzlose Beschwerden, die auf andere abzielen. Wir sind uns doch überhaupt nicht vertraut, oder?"
  },
  AvgDialog_118962_Content_53 = {
    Text = "Außerdem, wenn das Kraftwerk explodiert, wird der untere Schiffsrumpf wahrscheinlich auch betroffen sein."
  },
  AvgDialog_118962_Content_54 = {
    Text = "Los, wir haben keine zweite Wahl."
  },
  AvgDialog_118962_Content_6 = {
    Text = "Sie trat auf das Eisenblech unter ihren Füßen."
  },
  AvgDialog_118962_Content_7 = {
    Text = "Aber hier ist es ein bisschen seltsam..."
  },
  AvgDialog_118962_Content_8 = {
    Text = "Zu dieser Zeit sollten Goliath und Caecus normalerweise das Cockpit bewachen."
  },
  AvgDialog_118962_Content_9 = {
    Text = "Vor dem Ritual werden die Wesen des Meeres unruhig, wir müssen verhindern, dass der rasende Fischschwarm den Kurs des Schiffs stört..."
  },
  AvgDialog_118963_Content_1 = {
    Text = "Göttliche Mutter Feiertag"
  },
  AvgDialog_118963_Content_10 = {
    Text = "Du meinst..."
  },
  AvgDialog_118963_Content_11 = {
    Text = "Ja, du kannst immer noch deine Göttliche Mutter sein. Aber heute ist der Urlaub der Göttermutter."
  },
  AvgDialog_118963_Content_12 = {
    Text = "Du erzählst Lügen, ohne dein Gesicht zu verändern."
  },
  AvgDialog_118963_Content_13 = {
    Text = "Urlaub der Göttermutter?"
  },
  AvgDialog_118963_Content_14 = {
    Text = "Ja, heute bin ich beauftragt, dich den ganzen Tag auf dem Schiff zu unterhalten."
  },
  AvgDialog_118963_Content_15 = {
    Text = "Hast du nach dem Einsteigen noch nicht das wahre Leben der Besatzung erlebt?"
  },
  AvgDialog_118963_Content_16 = {
    Text = "Unabweisbar hast du Murphy aus dem Schlafzimmer “gebeten“."
  },
  AvgDialog_118963_Content_17 = {
    Text = "Müssen wir wirklich an so einen Ort klettern?"
  },
  AvgDialog_118963_Content_18 = {
    Text = "Komm schnell hoch, nur dort ist das Sichtfeld gut und man kann die Situation der patrouillierenden Seefahrer beobachten."
  },
  AvgDialog_118963_Content_19 = {
    Text = "Wenn du noch langsamer bist, wirst du entdeckt!"
  },
  AvgDialog_118963_Content_2 = {
    Text = "Du öffnest die Augen. Die grelle Sonne lässt deine Augen schmerzen."
  },
  AvgDialog_118963_Content_20 = {
    Text = "Was soll das, es ist ein völliges Durcheinander!"
  },
  AvgDialog_118963_Content_21 = {
    Text = "Obwohl sie das sagt, ergreift sie gehorsam deine Hand, und mit einem leichten Ziehen ziehst du sie auf die Plattform."
  },
  AvgDialog_118963_Content_22 = {Text = "Pff—"},
  AvgDialog_118963_Content_23 = {
    Text = "Murphy lachte plötzlich laut auf."
  },
  AvgDialog_118963_Content_24 = {
    Text = "Worüber lachst du?"
  },
  AvgDialog_118963_Content_25 = {
    Text = "Du kletterst wie ein Affe an den Takelagen!"
  },
  AvgDialog_118963_Content_26 = {
    Text = "Du Kerl, wenn ich nicht jetzt die Lautstärke halten müsste, würde ich dir definitiv einen großen Beule auf die Stirn hauen..."
  },
  AvgDialog_118963_Content_27 = {
    Text = "Lach nicht mehr! Du kannst dich auch nicht verstecken!"
  },
  AvgDialog_118963_Content_28 = {
    Text = "Du greifst nach Murphys Hand und ziehst sie an deine Seite."
  },
  AvgDialog_118963_Content_29 = {
    Text = "Hey, wie kannst du es wagen!"
  },
  AvgDialog_118963_Content_3 = {
    Text = "Aber du hast deinen Blick nicht abgewendet."
  },
  AvgDialog_118963_Content_30 = {Text = "Pst!"},
  AvgDialog_118963_Content_31 = {
    Text = "Ihr haltet den Atem an, während eine Gruppe von Seefahrern in alten, schmutzigen Strohmänteln wankend über das Deck taumelt."
  },
  AvgDialog_118963_Content_32 = {
    Text = "Schnell, finde den Aufenthaltsort der Göttlichen Mutter! Sie muss sich bestimmt auf diesem Schiff befinden!"
  },
  AvgDialog_118963_Content_33 = {
    Text = "Wir sind direkt über ihren Köpfen, und sie sehen uns überhaupt nicht?"
  },
  AvgDialog_118963_Content_34 = {
    Text = "Seit jeher schaut die Patrouille nicht nach oben."
  },
  AvgDialog_118963_Content_35 = {
    Text = "Mach dir keine Sorgen, solange wir uns hier verstecken, wird uns niemand entdecken."
  },
  AvgDialog_118963_Content_36 = {
    Text = "Quack, schau nach oben, dort ist jemand!"
  },
  AvgDialog_118963_Content_37 = {
    Text = "Du bist wirklich ein bisschen zu treffsicher mit deinem Krähenmaul, oder!"
  },
  AvgDialog_118963_Content_38 = {
    Text = "Sei unauffällig, nachdem wir dieses kleine Team beseitigt haben, verschwinden wir sofort in die Besatzungskabine!"
  },
  AvgDialog_118963_Content_4 = {
    Text = "Rascheln, Rascheln, das Krabbeln der Spinne klingt wie die sanfte Aufforderung der Mutter."
  },
  AvgDialog_118963_Content_5 = {
    Text = "Erinnere mich nicht daran. Ich weiß, das ist der letzte Zyklus."
  },
  AvgDialog_118963_Content_6 = {
    Text = "Du wischst dir die Tränen aus den Augenwinkeln und drehst dich in die Richtung, aus der der Ruf kommen wird, ohne dich umzudrehen, um die Herkunft des Gesangs zu bestätigen."
  },
  AvgDialog_118963_Content_7 = {
    Text = "Denn du weißt, dass die Frau, die den Webstuhl umarmt, dich mit barmherzigen Augen anblickt."
  },
  AvgDialog_118963_Content_8 = {
    Text = "Was machst du hier noch? Die Reise dieses Schiffes ist wieder aufgenommen, hier ist kein Platz mehr für dich."
  },
  AvgDialog_118963_Content_9 = {
    Text = "Nichtig, du bist die Göttliche Mutter der Seefahrer, auch die Kapitänin der Paradeis, die Herrin des Paradieses. Das hat nichts damit zu tun, dass ich dir eine Auszeit geben möchte."
  },
  AvgDialog_119922_Content_1 = {
    Text = "Willkommen zurück, Partner."
  },
  AvgDialog_119922_Content_10 = {
    Text = "Keine Sorge, mein Herr, egal wie lange Sie laufen wollen, Ogier wird bei Ihnen bleiben. Ich hoffe nur, dass..."
  },
  AvgDialog_119922_Content_11 = {
    Text = "Der junge Ritter schaut dich ernst an, und in seinen Augen steht die Aufrichtigkeit geschrieben, sowie das Flehen, das unter der Aufrichtigkeit verborgen ist."
  },
  AvgDialog_119922_Content_12 = {
    Text = "Ich wünsche mir nur... dass, falls mein Herr beim nächsten Mal wieder zum “Entspannen“ gehen möchte und so lange wegbleibt, Sie mich unbedingt mitnehmen. Ogier wird Ihr Leben bis zum Tod beschützen."
  },
  AvgDialog_119922_Content_13 = {
    Text = "Oder ich kann auch."
  },
  AvgDialog_119922_Content_14 = {
    Text = "Lotan sah dich auch an, ihre normalerweise auffälligen Augen waren voller Ernst. In diesem Moment dachte sie tatsächlich nicht an Sieg oder Niederlage, nicht an den Kampf, sondern nur an deine Fürsorge."
  },
  AvgDialog_119922_Content_15 = {
    Text = "... ich wusste, dass es so kommen würde. Ihr beiden, vergesst nicht das Ziel dieses Teekreises. Wir feiern die “Rückkehr“ von %player%."
  },
  AvgDialog_119922_Content_16 = {
    Text = "Ich hoffe, dass du diesmal nach deiner “Rückkehr“ nicht mehr gehst."
  },
  AvgDialog_119922_Content_17 = {
    Text = "Es ist nur ein kleiner Ausflug, rede nicht so ernst darüber... Und ich bin doch zurückgekommen, oder?"
  },
  AvgDialog_119922_Content_18 = {
    Text = "Als sie deine Worte hörte, schaute Doll dich an. Sie schien etwas sagen zu wollen, seufzte schließlich aber nur leise."
  },
  AvgDialog_119922_Content_19 = {
    Text = "Ja, du bist zurückgekehrt. Die Tage, an denen diejenigen, die auf dem Campus nach dir suchten, nur enttäuscht waren und die, die still vor deiner Tür standen, sich aber nicht trauten, anzuklopfen, sind ebenfalls vorbei."
  },
  AvgDialog_119922_Content_2 = {
    Text = "Irgendwann wurde der Misaq Platz in ein kleines Teegespräch verwandelt, und Ramona stand an einem kleinen Tisch, der mit Muffins, Marmelade und Tee gedeckt war, und lächelte dir zu, während sie dir die Hand entgegenstreckte."
  },
  AvgDialog_119922_Content_20 = {
    Text = "%player%, ich habe es unzählige Male gesagt und werde es auch in Zukunft weiterhin sagen, deine Existenz ist von unschätzbarem Wert."
  },
  AvgDialog_119922_Content_21 = {
    Text = "Egal ob für diese Welt oder für uns. Also..."
  },
  AvgDialog_119922_Content_22 = {
    Text = "Du wartest still auf Dors Fortsetzung, doch Doll schloss nur die Augen und sagte nichts mehr."
  },
  AvgDialog_119922_Content_23 = {
    Text = "In diesem Moment legte eine sanfte, aber feste Hand sich auf deinen Handrücken, es war Ramona."
  },
  AvgDialog_119922_Content_24 = {
    Text = "Partner, ich weiß, dass du als Schutzherr viel Druck trägst. Wir alle verstehen das und akzeptieren es. Daher werden wir nicht zu viel verlangen."
  },
  AvgDialog_119922_Content_25 = {
    Text = "Ich möchte nur, dass du weißt, egal wie oft du gehst, egal wie lange du weg bist, wenn du zurückkommst, sind wir hier."
  },
  AvgDialog_119922_Content_26 = {
    Text = "Als sie das sagte, machte das Mädchen eine Pause, lächelte dich langsam an."
  },
  AvgDialog_119922_Content_27 = {
    Text = "Nochmals willkommen zu deiner Rückkehr, Partner. Jetzt genieße die Teegespräch, die für dich vorbereitet wurde."
  },
  AvgDialog_119922_Content_28 = {
    Text = "Genau. Heute gibt es keine Prüfungen und keine zusätzlichen Aufgaben. Deine einzige Aufgabe ist es, dich selbst glücklich zu machen."
  },
  AvgDialog_119922_Content_29 = {
    Text = "Wenn du dir keine Sorgen über Karies und übermäßigen Zuckerkonsum machst, kannst du all diese Süßigkeiten aufessen. Schließlich sind sie auch für dich vorbereitet."
  },
  AvgDialog_119922_Content_3 = {
    Text = "Ich weiß nicht, ob ich das Vergnügen habe, dich zu unserem Rückkehr-Tee-Treffen einzuladen, das wir für dich vorbereitet haben?"
  },
  AvgDialog_119922_Content_30 = {
    Text = "Nicht nötig..."
  },
  AvgDialog_119922_Content_31 = {
    Text = "Obwohl du das sagst, hast du trotzdem einen Bissen von der mit Zuckerguss überzogenen Butterrolle genommen. Der Geschmack ist genau wie du es dir vorgestellt hast, übermäßig süß, aber nicht unangenehm."
  },
  AvgDialog_119922_Content_32 = {
    Text = "Denn im Blick der Menschen hast du Zufriedenheit gefunden. Vielleicht besteht das Leben darin, in den bitteren Intervallen der Realität einen solch berührenden süßen Geschmack zu erleben."
  },
  AvgDialog_119922_Content_4 = {
    Text = "Du nickst, und das Mädchen ergreift sanft deine Hand und führt dich zu dem dreieckigen Tisch, der voller Speisen ist, sowie zu den bereits seit langem wartenden Erweckern."
  },
  AvgDialog_119922_Content_5 = {
    Text = "Wenn du mich fragst, ist ein Kampf nicht \"aufregender\" als eine Teeparty? Aber in der Tat... dieses Mal ist es ein bisschen anders."
  },
  AvgDialog_119922_Content_6 = {
    Text = "Diesmal hat es nichts mit Gewinnen oder Verlieren zu tun, nichts mit dem Kampf. Es hat nur mit dir zu tun."
  },
  AvgDialog_119922_Content_7 = {
    Text = "%player%, du bist der absolute Hauptdarsteller dieser Teeparty."
  },
  AvgDialog_119922_Content_8 = {
    Text = "Lotan sagte und schob dir die Platte mit den Zuckerguss-Butterrollen vor die Nase. \n Nur ein Blick genügte, um zu wissen, dass sie unheimlich kalorienreich sind."
  },
  AvgDialog_119922_Content_9 = {
    Text = "Ich habe das Gefühl, dass ich nur einen Biss nehmen muss und dann ein ganzes Semester rennen muss, um es zu verdauen..."
  },
  AvgDialog_119923_Content_1 = {
    Text = "Im pechschwarzen seelischen Morast ertönt ein stechender Schmerz, der bis zur Seele reicht, sowie kalte Worte."
  },
  AvgDialog_119923_Content_10 = {
    Text = "Als du dich an das Gefühl der Gehirnoperation erinnerst, durchzuckt ein Kribbeln dein Gehirn. Um dieses Gefühl loszuwerden, lenkst du das Gespräch aktiv in eine andere Richtung."
  },
  AvgDialog_119923_Content_11 = {
    Text = "Diese Welt... Wie ist die Lage jetzt?"
  },
  AvgDialog_119923_Content_12 = {
    Text = "Es ist immer noch das Gleiche. Jede Sekunde nähert sich der Absturz und die Zerstörung. Aber zumindest gibt es gute Nachrichten für dich."
  },
  AvgDialog_119923_Content_13 = {
    Text = "Währenddessen schaltete Schmelzen·Dore den Kommunikator ein, und bald erschien eine vertraute Gestalt vor dir. Es war eine zuvor aufgezeichnete Nachricht."
  },
  AvgDialog_119923_Content_14 = {
    Text = "Schmelzen·Doll, wenn %player% erfolgreich zurückkehrt oder irgendwelche Nachrichten hat, erinnere dich daran, es mir zu sagen. Außerdem halte ich deinen vorherigen Vorschlag zur Implantation von psychologischen Hinweisen für sehr vernünftig."
  },
  AvgDialog_119923_Content_15 = {
    Text = "Als professioneller Psychologe kann ich %player% in dieser Angelegenheit nicht zu sehr nach dem Wunsch des Patienten anpassen..."
  },
  AvgDialog_119923_Content_16 = {
    Text = "Die Kommunikation endet hier abrupt und wird von Schmelzen·Doll unterbrochen. Sie klopft sanft auf den Tisch, um dir zu signalisieren, dass du deine Aufmerksamkeit auf sie richten sollst."
  },
  AvgDialog_119923_Content_17 = {
    Text = "Die nutzlosen Höflichkeiten können hier aufhören. Ich habe das hier nur freigegeben, um dir zu zeigen, was du in der Zeit, in der du „weg\" warst, verpasst hast."
  },
  AvgDialog_119923_Content_18 = {
    Text = "Das Wichtigste ist, dass mein Experiment noch nicht zu Ende ist..."
  },
  AvgDialog_119923_Content_19 = {
    Text = "Schmelzen·Doll kommt mit einem Skalpell auf dich zu. Ihr Gesichtsausdruck ist sehr ruhig, verbirgt jedoch eine Art Wahnsinn."
  },
  AvgDialog_119923_Content_2 = {
    Text = "Wie lange willst du noch so tun, als würdest du schlafen? Mein süßer Welpe."
  },
  AvgDialog_119923_Content_20 = {
    Text = "Was willst du tun?"
  },
  AvgDialog_119923_Content_21 = {
    Text = "Die Absicht, deinen Geist dauerhaft in diesem Kopf, diesem Körper zu fixieren. So hast du keine Möglichkeit mehr, zu “gehen“."
  },
  AvgDialog_119923_Content_22 = {
    Text = "Du trittst einen Schritt zurück vor Angst, aber schnell fasst du dich wieder, weil dir einfällt, dass du noch etwas zu erledigen hast——"
  },
  AvgDialog_119923_Content_23 = {
    Text = "Schmelzen·Doll, das ist nicht nötig. Egal wie lange diese Welt nicht normal ist, ich werde nicht wirklich gehen."
  },
  AvgDialog_119923_Content_24 = {
    Text = "Die Gestalt mit dem Skalpell hielt inne und sah dich nur still an, als würde sie die Wahrheit deiner Worte beurteilen."
  },
  AvgDialog_119923_Content_25 = {
    Text = "Ich meine es ernst. Als Schutzherr werde ich niemals aufgeben, diese Welt zu retten, also egal wie lange ich “weg“ bin, ich werde immer zurückkommen."
  },
  AvgDialog_119923_Content_26 = {
    Text = "Schmelzen·Doll legte das Skalpell nieder. In diesem Moment greifst du nach deiner Brust. \n Als deine Fingerspitzen den vertrauten Silberschlüssel berühren, fühlst du dich endlich beruhigt."
  },
  AvgDialog_119923_Content_27 = {
    Text = "Jetzt bin ich zurück. Die zuvor unterbrochene Ermittlung kann ebenfalls fortgesetzt werden."
  },
  AvgDialog_119923_Content_28 = {
    Text = "Während du sprichst, gehst du zur Tür. Schmelzen·Doll wirft dir einen Blick zu und folgt dir ebenfalls."
  },
  AvgDialog_119923_Content_29 = {
    Text = "Es scheint, dass du dir der Bedeutung deiner Existenz für diese Welt sehr bewusst bist."
  },
  AvgDialog_119923_Content_3 = {
    Text = "Schmelzen·Doll?"
  },
  AvgDialog_119923_Content_30 = {
    Text = "Natürlich, denn wie Tawil gesagt hat, bin ich die Variable dieser Welt, die Zukunft dieser Welt."
  },
  AvgDialog_119923_Content_31 = {
    Text = "Mit deinen Worten öffnete sich die Tür des Labors langsam. Die Luft und das Sonnenlicht von draußen fielen sanft auf dich, wie ein stiller Empfang oder eine Antwort."
  },
  AvgDialog_119923_Content_32 = {
    Text = "Diese Welt wartet auf dich, wartet auf die Veränderungen, die du bringen wirst, und auf die Zukunft, die du erschaffen wirst."
  },
  AvgDialog_119923_Content_4 = {
    Text = "Du erkennst den Besitzer der Stimme und öffnest langsam die Augen. Bald schwindet die Dunkelheit, und das Licht erscheint——"
  },
  AvgDialog_119923_Content_5 = {
    Text = "Wie fühlt es sich an, diese Welt zu verlassen?"
  },
  AvgDialog_119923_Content_6 = {
    Text = "Vielleicht sollte ich beim nächsten Mal auch deinen “Geist“ einsperren, dann brauche ich ihn nicht zurückzuholen."
  },
  AvgDialog_119923_Content_7 = {
    Text = "Schmelzen·Dore blinzelte und zeigte einen Ausdruck, der wie ein Lächeln aussah, während sie langsam das in kaltem Licht schimmernde Skalpell in der Hand drehte."
  },
  AvgDialog_119923_Content_8 = {
    Text = "...Wie bin ich hierher gekommen?"
  },
  AvgDialog_119923_Content_9 = {
    Text = "Natürlich liegt es daran, dass dein “Geist“ nach dem Verlassen die Hülle ihre Funktion verliert, weshalb ich erneut operieren musste, um deinen “Geist“ zurückzuholen."
  },
  AvgDialog_120290_Content_1 = {
    Text = "Vergoldeter Fleischtopf"
  },
  AvgDialog_120290_Content_10 = {
    Text = "Das Tor öffnet sich und du fällst in eine Umarmung. Sie hebt dich auf das Bett, tuckt die Decken um dich und beugt sich dann herunter, um ihre Stirn an deine zu legen, während sie dich nah an ihre Seite zieht."
  },
  AvgDialog_120290_Content_11 = {
    Text = "Mūmā...? Mūmā!"
  },
  AvgDialog_120290_Content_12 = {
    Text = "Papa hat sich schon lange nicht mehr um mich gekümmert. Es ist niemand im Haus, der mir helfen kann, und es gibt kein Wasser... Mein Kopf tut so weh und mein ganzer Körper schmerzt."
  },
  AvgDialog_120290_Content_13 = {
    Text = "...Mūmā's guter Nānnān, weine nicht."
  },
  AvgDialog_120290_Content_14 = {
    Text = "Keine Sorge, alles wird bald gut sein, Mūmā verspricht dir."
  },
  AvgDialog_120290_Content_15 = {
    Text = "Du sinkst in die warme Decke und nimmst schläfrig den Duft wahr, der allmählich stärker wird, nicht mehr dem gewohnten Jasminduft deiner Mutter ähnelt, sondern wie..."
  },
  AvgDialog_120290_Content_16 = {
    Text = "Wie riecht es? Wie die tiefsten, gewundenen Gassen von Shencheng, wo große Magnolienblüten fallen und in der drückenden Hitze fermentieren – eine seltsame, süßliche, kränkliche Süße."
  },
  AvgDialog_120290_Content_17 = {
    Text = "Mama, hat sich dein Duft verändert? Es riecht so gut, und... es ist auch ein bisschen seltsam."
  },
  AvgDialog_120290_Content_18 = {
    Text = "Die sanfte Stimme antwortete nicht auf deine Frage. Mit ihrem sanften Streicheln wurde der Duft stärker, fast greifbar."
  },
  AvgDialog_120290_Content_19 = {
    Text = "Du willst ihr Gesicht klar sehen, aber nur endloser Nebel wirbelt vor deinen Augen und umhüllt dich schließlich."
  },
  AvgDialog_120290_Content_2 = {
    Text = "Ein leichter Nebel trägt den Duft von Jasmin, der sich um deine Gliedmaßen wickelt und dich in eine unsichtbare, feuchte Umarmung verstrickt."
  },
  AvgDialog_120290_Content_20 = {
    Text = "Schlaf, gutes Baby, schlaf. Mama wird bald wieder an deiner Seite sein."
  },
  AvgDialog_120290_Content_21 = {
    Text = "...Ich habe es ihr bereits versprochen."
  },
  AvgDialog_120290_Content_22 = {
    Text = "Im Dunkeln krallt der Durst weiterhin an dir wie die Pfote einer Katze, und dann scheint eine warme, viskose Flüssigkeit aus deinen Nasenlöchern oder aus dem Mundwinkel in deinen Hals zu fließen."
  },
  AvgDialog_120290_Content_23 = {
    Text = "Deine Augenlider werden immer schwerer, und inmitten des Duftes und der Murmeln verlierst du allmählich das Bewusstsein vollständig."
  },
  AvgDialog_120290_Content_24 = {
    Text = "...bis das Geräusch von Schritten leise vor der Tür zusammenkommt und dich mit den Geräuschen von Gesprächen aus deinem schweren, pulsierenden Dämmerzustand weckt."
  },
  AvgDialog_120290_Content_25 = {
    Text = "Oh je, Fräulein Die, jeden Tag wachen Sie auf und wollen sofort Tee. Es ist so nervig! Glauben Sie wirklich, dass Sie immer noch die verwöhnte Dame sind, die Sie zu Lebzeiten waren?"
  },
  AvgDialog_120290_Content_26 = {
    Text = "Sei leise! ... Der Meister kümmert sich nicht einmal um seine eigene Tochter. Wie viele schöne Konkubinen gibt es im Innenhof? Sieh nur, läuft sie heute nicht wieder zur Vierten Straße."
  },
  AvgDialog_120290_Content_27 = {
    Text = "Sieh nur zu, es wird nicht lange dauern. Bald werden alle Konkubinen im Haus die kleinen Herren und Damen herausbringen..."
  },
  AvgDialog_120290_Content_28 = {
    Text = "...Mein Herr?"
  },
  AvgDialog_120290_Content_29 = {
    Text = "Du hebst deinen Kopf, und ein leicht schmutziger kupferner Becken auf dem Holzrahmen spiegelt schwach die zarten und jugendlichen Züge einer östlichen Person wider. Du blinzelst verwirrt, und das kleine Mädchen im Spiegel blinzelt zurück."
  },
  AvgDialog_120290_Content_3 = {
    Text = "Die Schläfrigkeit nach dem Fieber macht es dir unmöglich, dem Nebel zu widerstehen..."
  },
  AvgDialog_120290_Content_30 = {
    Text = "Dein Bewusstsein wird allmählich klarer, und Fragmente über deine Identität tauchen in deinem Geist auf."
  },
  AvgDialog_120290_Content_31 = {
    Text = "...Mein Herr, Ho Fong, Vater... Ich bin im Anwesen der Familie He, ich bin die Tochter von Ho Fong, mein Name ist..."
  },
  AvgDialog_120290_Content_32 = {
    Text = "Oh nein, du kannst nicht so auf dem Boden liegen. Der Meister wird mich schimpfen, wenn er dich sieht."
  },
  AvgDialog_120290_Content_33 = {
    Text = "Die Tür wurde plötzlich aufgestoßen, wodurch deine Gedanken unterbrochen wurden, als jemand vorstürzte und ungeduldig half, dich aufzurichten."
  },
  AvgDialog_120290_Content_34 = {
    Text = "Gerade eben, wie bin ich auf den Boden gekommen? Wo ist Mama?"
  },
  AvgDialog_120290_Content_35 = {
    Text = "Gnädige Frau? Fräulein, Sie sollten sich im Klaren sein; die Dame ist seit über einem Monat weg."
  },
  AvgDialog_120290_Content_36 = {
    Text = "Sie platzte heraus, als sie dich dort im Daze stehen sah, mit einem zögernden Ausdruck auf deinem Gesicht."
  },
  AvgDialog_120290_Content_37 = {
    Text = "<Small:Es ist nur so klein, wahrscheinlich weiß es nicht einmal, was gehen bedeutet.>"
  },
  AvgDialog_120290_Content_38 = {
    Text = "<LightGray:Ja, Mama hat das vor über einem Monat gemacht...>"
  },
  AvgDialog_120290_Content_39 = {
    Text = "Hast du wieder geträumt? Seufz. Hier, ich habe dir etwas Wasser gebracht."
  },
  AvgDialog_120290_Content_4 = {
    Text = "Dann fiel er direkt auf den Boden."
  },
  AvgDialog_120290_Content_40 = {
    Text = "Wasser... du bemerkst plötzlich, dass du keinen Durst mehr hast; die Flüssigkeit, die zuvor geflossen ist, begleitet von ihrem Duft."
  },
  AvgDialog_120290_Content_41 = {
    Text = "Der süße, fast verrottende Duft von Magnolie verweilt noch in deinen Zähnen und Nasenlöchern!\nPlötzlich wirst du aufmerksam und stürmst nach draußen."
  },
  AvgDialog_120290_Content_42 = {
    Text = "Hey, hey! Wohin glaubst du, dass du läufst, Fräulein!"
  },
  AvgDialog_120290_Content_43 = {
    Text = "Das Festival des Fernen Ostens ist angekommen, die Lichter gehen gerade an, und rote Laternen sowie moderne Neonlichter ergänzen sich. Doch die Menschen, die an diesem Tag eigentlich früh nach Hause hätten gehen sollen, strömen alle in die gleiche Richtung."
  },
  AvgDialog_120290_Content_44 = {
    Text = "Die Luft ist erfüllt von dem Duft von Pulver, Kerosin, dem fettigen Geruch von Imbissständen und Restaurants und einem immer stärker werdenden..."
  },
  AvgDialog_120290_Content_45 = {
    Text = "Meine Mūmā. Es ist ihr Duft. Es war kein Traum! Es war keiner!"
  },
  AvgDialog_120290_Content_46 = {
    Text = "Du hast es gefunden, die Quelle dieses seltsamen, intensiven, vertrauten, intimen und zarten süßmetallischen Dufts."
  },
  AvgDialog_120290_Content_47 = {
    Text = "Das Zeichen des Goldenen Verkaufsgebäudes hängt hoch oben am kunstvoll verzierten Tor."
  },
  AvgDialog_120290_Content_48 = {Text = "Herr Xu!"},
  AvgDialog_120290_Content_49 = {
    Text = "Tritt zur Seite, Herr Xu, du blockierst meinen Weg, schau dort drüben!"
  },
  AvgDialog_120290_Content_5 = {
    Text = "Ugh! Es tut weh... Mama... Wasser..."
  },
  AvgDialog_120290_Content_50 = {Text = "Tsk"},
  AvgDialog_120290_Content_51 = {
    Text = "Die Gestalt auf der hohen Plattform spielte gelangweilt mit einem schwarzen Fächer, die Hälfte ihres Gesichts war hinter der Fläche des Fächers verborgen."
  },
  AvgDialog_120290_Content_52 = {
    Text = "Die Menschen drängten sich gegeneinander, überwältigten dich fast, mit einem vagen Strom von Enthusiasmus und Angst, der in ihre Augen schlich, aber es schien keinen Einfluss auf sie zu haben."
  },
  AvgDialog_120290_Content_53 = {
    Text = "Du fandest die Quelle dieses Duftes, oder besser gesagt, ein gewisses Verlangen und Schauer, die du nicht begreifen konntest, faszinierten dich. Verzweifelt hobst du deinen Kopf und blicktest nach oben."
  },
  AvgDialog_120290_Content_54 = {Text = "...yeah."},
  AvgDialog_120290_Content_55 = {
    Text = "Als sie etwas fühlte, senkte sie die Augen, und alles, was man sah, waren ein Paar sehr, sehr schöner Augen."
  },
  AvgDialog_120290_Content_56 = {
    Text = "Der schwarze Ventilator bewegte sich langsam zur Seite mit atemberaubender Eleganz."
  },
  AvgDialog_120290_Content_57 = {
    Text = "Nebel Nebel Nebel \nNebel Nebel Nebel Nebel Sie Er? Er... Sie... Mutter... Mutter Mutter Mutter Mutter Mutter Augen ihrer Augen \nNebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel \nSie Sie Sie Sie Sie Sie Er Er Er Er Er Mutter Mutter Mutter Mutter Mutter Mutter Mutter Mutter Mutter Er \nAugen Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel schöne Augen Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel \nNebel Nebel Nebel Nebel Sie Sie Sie Sie schöne Augen Sie Sie Sie Sie Nebel schöne Augen Sie Er Er Sie Nebel Nebel Nebel \nNebel Nebel Nebel Nebel Sie Er Er Er Er Er Nebel Nebel schöne Augen Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel \nMutter Mutter Mutter Mutter Mutter Mutter Mutter schöne Augen Mutter Mutter Mutter Mutter Mutter Mutter Augen Augen Augen \nAugen Augen Augen Augen Nebel Nebel Nebel Nebel Nebel Nebel Nebel schöne Augen von ihr Augen Sie Er Sie Sie Er Er Er Er Er Sie \nIhre Augen Augen Augen Mutter Augen schöne Augen Mutter Augen von Mutter Sie Mutter Er Sie Mutter Mutter \nNebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel schöne Augen Sie Er Er Er Er Er Er Er Er Er Er Augen Augen Sie Sie Sie \nSie Er Er Sie Er Er Er Sie Sie Sie Sie Er schöne Augen Sie Sie Sie Sie Er Er Sie Er Er Er Sie Sie Sie Er Er Sie \nMutter Mutter Mutter Mutter Mutter Mutter Nebel Nebel Nebel Nebel Nebel schöne Augen Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel \n@4@4@4@1@1@3@3 Nebel Nebel Nebel Nebel @1@3 \nSie Er Sie Er Er Sie schöne Augen Sie Sie Er Er Sie Er Er Er @3 Er Er Sie @1 Er Er Er Sie Sie Sie \nSie @4@3@4@4@4 Augen @2@4 \nMutter Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel Nebel schöne Augen Nebel Nebel Nebel Nebel Nebel Nebel schöne Augen Mutter Mutter Mutter \nSie Sie Sie schöne Augen Sie Sie Sie @4 Er Er Er schöne Augen Er Er Er Er Er schöne Augen"
  },
  AvgDialog_120290_Content_58 = {
    Text = "Weinen, Schreien, Heulen explodieren plötzlich in deinen Ohren, während sich Schicht um Schicht von Menschen auf dich zubewegt!"
  },
  AvgDialog_120290_Content_59 = {
    Text = "Ich habe es gesehen, ich habe es gesehen, sie sieht mich an!"
  },
  AvgDialog_120290_Content_6 = {
    Text = "Deine Gliedmaßen fühlen sich so schwach an, dass du keine Kraft aufbringen kannst; die Erinnerung ist noch nicht zurückgekehrt, und du hast einen unglaublichen Durst, instinktiv sprichst du den vertrautesten Namen aus."
  },
  AvgDialog_120290_Content_60 = {
    Text = "Sie sieht mich an!"
  },
  AvgDialog_120290_Content_61 = {
    Text = "<Change>So... so schön!! Was für ein Gesicht es ist, so lieblich, so... außergewöhnlich... so furchterregend!!!"
  },
  AvgDialog_120290_Content_62 = {
    Text = "Herr Xu! Herr Xu... Bitte, bitte!!"
  },
  AvgDialog_120290_Content_63 = {
    Text = "Bitte schau mich an!"
  },
  AvgDialog_120290_Content_64 = {
    Text = "<Shake:<Red:AAAAHHHHH!!!!>>"
  },
  AvgDialog_120290_Content_65 = {
    Text = "Der gut gekleidete Mann schrie plötzlich und stürzte sich auf den Mann im Anzug, der zwischen ihm und Xu stand, während letzterer direkt Xu anstarrte, bis ihm unerwartet das Auge herausgerissen wurde."
  },
  AvgDialog_120290_Content_66 = {
    Text = "Der Mann, dem die Augen ausgestochen wurden, schrie vor Qual, während er manisch lachte. Die kugelförmigen Kristalle hingen sanft aus seinen Augenhöhlen, während er lässig sein Gesicht abwischte und mit aller Kraft in Richtung der hohen Plattform griff, seine Venen anschwoll."
  },
  AvgDialog_120290_Content_67 = {
    Text = "Als ob ein Signal gegeben wurde, verwandelt sich die Menge in eine wütende Flut. Mitten im Lachen und Schreien strömen sie vorwärts, verzweifelt darauf aus, die hohe Bühne zu berühren."
  },
  AvgDialog_120290_Content_68 = {
    Text = "<Change>Xu!! Xu!!!"
  },
  AvgDialog_120290_Content_69 = {
    Text = "<Change>Xu——!!!!!"
  },
  AvgDialog_120290_Content_7 = {
    Text = "Eine sanfte, summende Stimme näherte sich aus der Ferne, und eine weibliche Gestalt ging an der Tür vorbei, vertraut und warm. Du fühltest, wie dein Unterkörper schwächer wurde, während du versuchtest, dich zu erheben..."
  },
  AvgDialog_120290_Content_70 = {
    Text = "Das scharfe, durchdringende Geräusch steht kurz davor, deine Trommelfelle zu zerreißen. Die Menge drängt und schubst, und dieser junge Körper ächzt unter der Belastung, während die Züge unter dem Ventilator klarer, aber dennoch undeutlicher werden."
  },
  AvgDialog_120290_Content_71 = {
    Text = "Am Ende vereinte es sich zu einem abgrundähnlichen Nebel, der alles Licht verschlang."
  },
  AvgDialog_120290_Content_72 = {
    Text = "Und ein angenehm leichter Lachen, das durch den Nebel zog."
  },
  AvgDialog_120290_Content_73 = {
    Text = "Du bist hier, mein kleiner Jasmin."
  },
  AvgDialog_120290_Content_74 = {
    Text = "Kurz bevor du von Dunkelheit und Erstickung verschlungen wirst, erhaschst du einen Blick auf die Menge, die ebenso in Raserei gefangen ist und alle Würde ablegt, während sie voranstürmt..."
  },
  AvgDialog_120290_Content_75 = {
    Text = "Die Gestalt deines Vaters, der dir nicht einmal einen Blick geschenkt hat."
  },
  AvgDialog_120290_Content_8 = {
    Text = "<Shake:Knarren—Yaa—>"
  },
  AvgDialog_120290_Content_9 = {
    Text = "Oh je, armes Ding, wie bist du an einen Ort wie diesen geraten?"
  },
  AvgDialog_120291_Content_1 = {
    Text = "Plötzliche Erscheinung"
  },
  AvgDialog_120291_Content_10 = {
    Text = "Ein Stück pulveriger und süßer Gebäck, eindeutig nicht raffiniert, wurde dir in den Mund geschoben. Als der Kuchen kaum anfing sich aufzulösen, begann dein Speichel wild in deinem Mund zu fließen."
  },
  AvgDialog_120291_Content_11 = {
    Text = "Du folgst dicht hinter der anderen Person und kaust auf dem Gebäck. Gerade als sich dein Magen zu beruhigen beginnt, ergreift ein stärkerer Druck dein Herz."
  },
  AvgDialog_120291_Content_12 = {
    Text = "Stehen Sie nicht einfach da, Fräulein, beeilen Sie sich hinein, Herr Xu wartet schon lange."
  },
  AvgDialog_120291_Content_13 = {
    Text = "Vater war wie immer von vielen Konkubinen umgeben, deren Gesichter man nicht genau erinnern kann. Die Konkubinen im Innenhof kommen und gehen, jede mit ihrer eigenen Figur und ihrem Charme, lebhaft und lebendig."
  },
  AvgDialog_120291_Content_14 = {
    Text = "Doch jetzt ist sein Blick extrem verwirrt und fixiert sich auf nur eine Person."
  },
  AvgDialog_120291_Content_15 = {
    Text = "Die Besitzerin dieser ärgerlich schönen Augen spielte offensichtlich eine Art distanzierte, aber höfliche Rolle aus Langeweile, bis ihr Blick sanft auf dich fiel."
  },
  AvgDialog_120291_Content_16 = {
    Text = "Obwohl ich wusste, dass du nach der Zeremonie herabsteigen würdest, hätte ich nie erwartet, dass du so charmant bist."
  },
  AvgDialog_120291_Content_17 = {
    Text = "Ich hätte dich nicht ins Bordell schicken sollen, oder? Ich hätte dich an meiner Seite behalten sollen. Es ist jetzt alles sinnlos; nichts zählt außer dir!"
  },
  AvgDialog_120291_Content_18 = {
    Text = "Herr He, bitte seien Sie nicht so formell. Wir können später plaudern; ich bin heute gekommen, um mich zu entschuldigen."
  },
  AvgDialog_120291_Content_19 = {
    Text = "Was weiß ein dummes Mädchen? Heute werde ich wieder Geschenke für das Bordell vorbereiten. Wenn dir diese gefallen, behalte sie nah bei dir und bringe ihr persönlich bei, wie man sich um sie kümmert?"
  },
  AvgDialog_120291_Content_2 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_120291_Content_20 = {
    Text = "Herr He hat ein außergewöhnliches Auftreten. Wenn wir dazu bestimmt sind, uns zu treffen, würde es mir sicherlich große Freude bereiten."
  },
  AvgDialog_120291_Content_21 = {
    Text = "Ich fühle auf den ersten Blick eine starke Verbindung zu diesem Kind, trotz unserer vorherigen Konflikte... Wenn du und ich enger zusammenkommen wollen, muss sie auch Frieden finden."
  },
  AvgDialog_120291_Content_22 = {
    Text = "Die Frau, die als Mr. Xu bekannt ist, kommt auf dich zu und beugt sich sanft nach unten."
  },
  AvgDialog_120291_Content_23 = {
    Text = "Ich habe mich noch nicht vorgestellt; mein Name ist Xu. Was denkst du also, liebe junge Dame der Familie He?"
  },
  AvgDialog_120291_Content_24 = {
    Text = "Xu ist irgendwie vor dir angekommen. Instinktiv greifst du nach der Hand der Frau, die dich hierher gebracht hat, und möchtest dich hinter ihr verstecken."
  },
  AvgDialog_120291_Content_25 = {
    Text = "Ihre jadeartigen Fingerspitzen wiegen sanft Ihr Kinn an und heben es an, und Sie sehen diese Augen erneut.\nSo ähnlich wie Ihre Mutter, und doch so schön, dass es Sie mit Furcht erfüllt."
  },
  AvgDialog_120291_Content_26 = {
    Text = "Ich... Ich..."
  },
  AvgDialog_120291_Content_27 = {
    Text = "<Shake:Alle, die dich auf der Straße gesehen haben, sind verrückt geworden. Der Onkel im Anzug hatte seine Augen herausgerissen! Ich-ich habe Angst!>"
  },
  AvgDialog_120291_Content_28 = {
    Text = "Die kindlichen Worte, die dir über die Lippen kamen, verblüfften Xu tatsächlich für einen Moment, und dann lachte er so laut, dass er fast die Fassung verlor."
  },
  AvgDialog_120291_Content_29 = {
    Text = "Was für ein Zufall. Du Langjun, genau rechtzeitig, könntest du mir bitte helfen? Kleine Jasmin, schau mal, ist das der Gentleman, von dem wir sprechen?"
  },
  AvgDialog_120291_Content_3 = {
    Text = "Der Schock, im Zentrum eines unbekannten Wahnsinns zu sein, hätte deinen Verstand zerstören oder zumindest deinen Willen brechen sollen."
  },
  AvgDialog_120291_Content_30 = {
    Text = "Als du ihrem Finger folgst, der sich von deinem Kinn entfernt, bemerkst du, dass hinter den eifersüchtigen Tanten ein anderer Mann steht, der immer noch in diesem Anzug gekleidet ist."
  },
  AvgDialog_120291_Content_31 = {
    Text = "Es ist er. Hmm? Warum sind seine Augen noch da?"
  },
  AvgDialog_120291_Content_32 = {
    Text = "Sein Gesicht ist nicht mehr blutig, und seine Augen sind dort, wo sie sein sollten; du hast ihn tatsächlich erkannt."
  },
  AvgDialog_120291_Content_33 = {
    Text = "Als die Mutter noch da war, gingen du und der Vater zu Banketten. Der Vater versuchte mehrmals, mit ihm zu sprechen, aber jedes Mal wurde er abgewiesen und kehrte wütend zurück."
  },
  AvgDialog_120291_Content_34 = {
    Text = "Ist das das kleine Mädchen, das an diesem Tag Angst hatte? Ist sie wirklich so viel wert, dass du dir die Mühe machst, mich bis hierher zu schicken, um Essen für sie zu kaufen?"
  },
  AvgDialog_120291_Content_35 = {
    Text = "Die Familie He kann nicht einmal mit ihrer hysterischen Tochter umgehen, und doch wollen sie sich in das Import- und Exportgeschäft von Haicheng einmischen. Wie lächerlich."
  },
  AvgDialog_120291_Content_36 = {
    Text = "Meine Tochter liegt seit dem Tod meiner Frau bettlägerig und in schlechter Stimmung, was Herrn Du wohl amüsiert haben muss. Ich werde mich sofort darum kümmern..."
  },
  AvgDialog_120291_Content_37 = {
    Text = "Als du den finsteren Gesichtsausdruck deines Vaters siehst, bist du stunned und erstarrst an Ort und Stelle, doch bald nimmst du den Duft von Magnolien wahr. Du bist in Xus Umarmung gehalten, der dich gedankenlos kneift und knetet."
  },
  AvgDialog_120291_Content_38 = {
    Text = "Du Langjun, ich habe gesagt, dass ich dieses junge Fräulein aus der Familie He mag. Wenn du dich mit ihr streitest und die Dinge ernst nimmst, werde ich unglücklich sein – wenn ich unglücklich bin, was wirst du dann tun?"
  },
  AvgDialog_120291_Content_39 = {
    Text = "Als er dies hörte, verlor der zuvor verächtliche Blick des Mannes, der dich von oben bis unten musterte, plötzlich seinen Fokus. Dann schwang er seinen Arm und begann, sich wiederholt ins Gesicht zu schlagen."
  },
  AvgDialog_120291_Content_4 = {
    Text = "Aber dieses Bewusstsein ist immer noch zu klein, wie eine Mayfly. Nein, lassen Sie es uns noch weiter vereinfachen. Ein Pantoffeltierchen oder ein anderer einzelliger Organismus. Sie wissen nur, dass Sie satt sein müssen, warm bleiben und Vorteile suchen sollten, während Sie Schäden vermeiden."
  },
  AvgDialog_120291_Content_40 = {
    Text = "Sein Gesicht schwoll sofort an, doch er schien keinen Hauch von Schmerz zu empfinden, öffnete stumpf den Mund und zeigte ein Lächeln, das dem eines Schaufensterpuppen ähnelte, die man auf einem westlichen Jahrmarkt gesehen haben könnte."
  },
  AvgDialog_120291_Content_41 = {
    Text = "Ich habe mich versprochen!"
  },
  AvgDialog_120291_Content_42 = {
    Text = "Ich habe mich versprochen, ich habe mich versprochen!"
  },
  AvgDialog_120291_Content_43 = {
    Text = "Mit einem Klaps nahm Xu fröhlich eine Tüte Süßigkeiten aus seiner Tasche, zog ein Stück heraus und steckte es dir in den Mund."
  },
  AvgDialog_120291_Content_44 = {
    Text = "Wie merkwürdig! Möchte Fräulein He einen Blick darauf werfen?"
  },
  AvgDialog_120291_Content_45 = {
    Text = "Der süße Nektar schmilzt dahin, und du starrst leer auf alles vor dir. Schließlich hebst du deinen Kopf, um Xu anzusehen."
  },
  AvgDialog_120291_Content_46 = {
    Text = "...Die Birnensirupbonbons aus dem Stadtgotttempel, meine Mutter hat sie früher für mich gekauft."
  },
  AvgDialog_120291_Content_47 = {
    Text = "Herr Xu, bist du Mama?"
  },
  AvgDialog_120291_Content_48 = {
    Text = "Xu antwortete dir nicht, lächelte nur unaufhörlich, während die Konkubinen und der Vater wie verzaubert dastehen, schweigend und regungslos."
  },
  AvgDialog_120291_Content_49 = {
    Text = "Du Langjun, schau dir selbst an. Ich habe nur ein kleines Wutanfall gehabt. Du hast mich so hart geschlagen, dass es meinem Herzen wehtut."
  },
  AvgDialog_120291_Content_5 = {
    Text = "So wirst du erneut von diesem Käfig aus Nebel gehalten und öffnest deine Augen unversehrt."
  },
  AvgDialog_120291_Content_50 = {
    Text = "Sobald der Mann stoppte, schienen die Konkubinen aus einer Benommenheit zu erwachen und schauten schockiert und verwirrt auf Herrn Du, dessen Wangen eine bläulich-violette Farbe angenommen hatten."
  },
  AvgDialog_120291_Content_51 = {
    Text = "Ich erinnere mich, dass Herr He etwas mit Lord Du zu besprechen hatte, also habe ich mir erlaubt, dieses Besuchsgeschenk mitzubringen."
  },
  AvgDialog_120291_Content_52 = {
    Text = "Junge Dame der Familie He, wären Sie bereit, mich bei der Besprechung der Angelegenheiten nach draußen auf einen Spaziergang zu nehmen?"
  },
  AvgDialog_120291_Content_53 = {
    Text = "Bevor du den Raum verlässt, kannst du nicht anders, als einen Blick auf deinen Vater zu werfen. Sein Gesicht trug nicht den leeren und seltsamen Ausdruck von Mr. Du und den Tanten, sondern er billigte alles schweigend."
  },
  AvgDialog_120291_Content_54 = {
    Text = "Herr Xu, du..."
  },
  AvgDialog_120291_Content_55 = {
    Text = "Du hast viele Fragen zu stellen, nicht wahr?"
  },
  AvgDialog_120291_Content_56 = {
    Text = "Keine Eile... mein liebes Baby, mein gutes Baby."
  },
  AvgDialog_120291_Content_57 = {
    Text = "Mein kleiner Jasmin... komm, schau mich an."
  },
  AvgDialog_120291_Content_58 = {
    Text = "Die schwere Dunkelheit drückt nach unten, und unter dem knochenweißen Silbermond bewegt Xu den Fächer, während der neblige Dunst auf dich zurast, dich umhüllt und dich verschlingt."
  },
  AvgDialog_120291_Content_59 = {
    Text = "Vage sieht Mutter dich im warmen Licht an, lächelt sanft und beugt sich mit weit offenen Armen zu dir herunter."
  },
  AvgDialog_120291_Content_6 = {
    Text = "Der Himmel ist komplett dunkel geworden, und die Fenster anderer Räume spiegeln das entfernte Kerzenlicht wider, während schwache, verstreute Schritte sich wieder nähern."
  },
  AvgDialog_120291_Content_60 = {
    Text = "Wie ein plötzlich reißender Faden trifft dich eine Welle der Emotionen, und Tränen verschwommen völlig deine Sicht. Ohne zu zögern, hältst du sie fest in deiner Umarmung."
  },
  AvgDialog_120291_Content_61 = {
    Text = "Mama, kannst du bitte nicht wieder gehen."
  },
  AvgDialog_120291_Content_62 = {
    Text = "Waaah, waaahhh, mein Kopf ist so verwirrt, ich habe solche Angst. Ich vermisse dich so sehr! Mama."
  },
  AvgDialog_120291_Content_63 = {
    Text = "Die Frau legt sanft ihre Arme um dich und streichelt sanft deinen Rücken."
  },
  AvgDialog_120291_Content_64 = {
    Text = "Mamas kostbares kleines Mädchen, Mamas brav kleines Mädchen."
  },
  AvgDialog_120291_Content_65 = {
    Text = "Mein liebes Baby, mein gutes Baby."
  },
  AvgDialog_120291_Content_66 = {
    Text = "Wofür würdest du bereit sein, aufzugeben, um für immer bei Mama zu sein?"
  },
  AvgDialog_120291_Content_67 = {
    Text = "Der Nebel scheint dich wieder zu umhüllen, und du hörst das Geräusch deines eigenen Murmelns."
  },
  AvgDialog_120291_Content_68 = {
    Text = "Alles ist erlaubt... Alles ist in Ordnung."
  },
  AvgDialog_120291_Content_69 = {
    Text = "Ist das ganze Haus verfügbar?"
  },
  AvgDialog_120291_Content_7 = {
    Text = "Oh je, Fräulein, du hast mich zu Tode erschreckt. Laufst du in einem Anfall auf die Straße, willst du uns einfache Leute umbringen?"
  },
  AvgDialog_120291_Content_70 = {
    Text = "Ich will das Haus nicht, ich will nur Mama."
  },
  AvgDialog_120291_Content_71 = {
    Text = "Das ganze Haus, die gesamte Stadt Haicheng und dein Vater, können sie alle erledigt werden?"
  },
  AvgDialog_120291_Content_72 = {
    Text = "Vater... Papa..."
  },
  AvgDialog_120291_Content_73 = {
    Text = "Du bist für einen Moment in Gedanken versunken und erinnerst dich plötzlich an die Nächte, als deine Mutter geduldig auf dich wartete und die Hand, die auf deinem Kopf ruhte, als dein Vater nach Hause kam."
  },
  AvgDialog_120291_Content_74 = {
    Text = "Keine Sorge, es ist noch viel Zeit, kleine Jasmin."
  },
  AvgDialog_120291_Content_75 = {
    Text = "Es scheint, als würdest du von jemandem gehoben und in ein weiches Bett fallen, wo dich etwas noch Wärmeres und Zärtlicheres intim umarmt."
  },
  AvgDialog_120291_Content_76 = {
    Text = "Es ist schon spät in der Nacht, also schlaf. Ich werde ganz bald an deiner Seite sein, ganz bald."
  },
  AvgDialog_120291_Content_77 = {
    Text = "Nachdem deine Mutter gegangen war, fühltest du zum ersten Mal ein unvergleichliches Gefühl der Erleichterung, zusammen mit der folgenden Schläfrigkeit, und versankst in einen tiefen und süßen Traum."
  },
  AvgDialog_120291_Content_8 = {
    Text = "<Shake:Glug—>"
  },
  AvgDialog_120291_Content_9 = {
    Text = "...Seufz, ich fühle mich wirklich leid für dich. Beeil dich und kaue. Der Meister wartet bereits in der Halle, mach mir keine weiteren Schwierigkeiten, verstanden?"
  },
  AvgDialog_120296_Content_1 = {
    Text = "Oh, Mein Liebster"
  },
  AvgDialog_120296_Content_10 = {
    Text = "In Ordnung, steck deine kleinen Gedanken weg. Sag nicht, ich mache dir Angst; dieses Herrenhaus ist nicht sicher. Alle Frauen, die der Lord mochte, sind am Ende verschwunden."
  },
  AvgDialog_120296_Content_11 = {
    Text = "Sogar seine Jugendliebe, die Ex-Frau, von der gesagt wurde, dass sie an einer Krankheit gestorben ist, wer weiß, dass es..."
  },
  AvgDialog_120296_Content_12 = {
    Text = "Oh nein! Warum drängst du mich?"
  },
  AvgDialog_120296_Content_13 = {
    Text = "Madam, ich entschuldige mich wirklich... ich entschuldige mich wirklich. Meine Schwester redet oft unüberlegt, bitte hören Sie nicht auf ihren Unsinn. Wir wollen Ihnen absolut nicht zu nahe treten, ich bitte Sie, erzählen Sie es bitte nicht dem Meister."
  },
  AvgDialog_120296_Content_14 = {
    Text = "Plötzlich von ihrer Schwester zurückgezogen, kam die Konkubine mit fein gezeichneten Augenbrauen und exquisitem Make-up zu sich, ihr Gesicht wurde sofort blass vor Angst, während sie hastig ihren Mund bedeckte, um sich zum Schweigen zu bringen."
  },
  AvgDialog_120296_Content_15 = {
    Text = "Da dieses Haus nicht sicher ist, warum hast du nicht daran gedacht, einen anderen Ort zu finden?"
  },
  AvgDialog_120296_Content_16 = {
    Text = "...Wohin sonst gibt es noch zu gehen? Wenn wir von der Aristokratie wie Juwelen geschätzt werden könnten, dann könnten wir wirklich überall hingehen."
  },
  AvgDialog_120296_Content_17 = {
    Text = "Hehe, es wie ein kostbares Juwel halten?"
  },
  AvgDialog_120296_Content_18 = {
    Text = "Xu brach plötzlich in Gelächter aus, und in diesem Moment hörten mehrere Konkubinen im Flur eine Art geheimnisvolles, flüsterndes Lachen."
  },
  AvgDialog_120296_Content_19 = {
    Text = "Ihre Blicke wurden unkonzentriert, als sie verwirrt aufschauten und die Frau beobachteten, die weiter in den Flur ging."
  },
  AvgDialog_120296_Content_2 = {
    Text = "Der Neuling hat ein paar Tricks im Ärmel."
  },
  AvgDialog_120296_Content_20 = {
    Text = "Meine kleine Jasmin schläft; lass uns sie nicht wecken. Folge mir."
  },
  AvgDialog_120296_Content_21 = {
    Text = "Ich werde Ihnen, mein Herr, verständlich machen, dass eine edle Person, ebenso wie ein kostbares Objekt, nur interessant ist, wenn sie zart zwischen den Fingerspitzen gehalten wird."
  },
  AvgDialog_120296_Content_22 = {
    Text = "Die Konkubinen trugen ein dummes Lächeln auf ihren Gesichtern, während der Nebel ihre Lippen verdeckte und die Fächer ihre Gesichter verhüllten."
  },
  AvgDialog_120296_Content_23 = {
    Text = "Der fischig-süße, reichhaltige Magnolienduft breitete sich leise im ganzen Herrenhaus aus."
  },
  AvgDialog_120296_Content_24 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_120296_Content_25 = {
    Text = "Nachdem Xu als Stiefmutter in Hes Anwesen gebracht wurde, hast du nie wieder Hunger gelitten. Jeder behandelte dich warmherzig und freundlich, als wärst du immer noch das junge Fräulein, als deine Mutter noch bei dir war."
  },
  AvgDialog_120296_Content_26 = {
    Text = "Aber Vater verließ sein Zimmer nie wieder, und Xu war nie drinnen gewesen; stattdessen schienen die Konkubinen von unsichtbaren Fäden angezogen zu werden und kamen häufig aus Xus Kammer und gingen wieder hinein."
  },
  AvgDialog_120296_Content_27 = {
    Text = "Oh mein Gott, Fräulein, könnten Sie bitte helfen? Der Meister hat ausdrücklich angeordnet, dass sich niemand seinem Zimmer nähern soll."
  },
  AvgDialog_120296_Content_28 = {
    Text = "Ich habe meinen Vater schon so lange nicht mehr gesehen. Ich werde nur aus der Ferne einen Blick darauf werfen, ich verspreche, dass ich ihn nicht stören werde."
  },
  AvgDialog_120296_Content_29 = {
    Text = "Bevor du jedoch näher kommen konntest, hörtest du ein frenetisches, unnatürlich aufgeregtes heiseres Knurren aus dem Raum."
  },
  AvgDialog_120296_Content_3 = {
    Text = "Du hast eine scharfe Zunge, aber du kannst dich nicht von dem Fächer trennen, den sie dir gegeben hat, oder?"
  },
  AvgDialog_120296_Content_30 = {
    Text = "Xu... mein Liebster, mein Retter, mein Herz, ich kann dich nicht mehr loslassen, du gehörst mir, du kannst nur mein sein."
  },
  AvgDialog_120296_Content_31 = {
    Text = "Ihr Blut und ihre Knochen sind nichts... Egal wie viel, ah! Solange es dich zurückbringen kann, solange es dich zurückbringen kann, ist es alles wert!"
  },
  AvgDialog_120296_Content_32 = {
    Text = "Ich verstehe, ich sehe! Haha, hahahaha!!!"
  },
  AvgDialog_120296_Content_33 = {
    Text = "Das glitschige, wabernde Geräusch schien über den Boden zu schlängeln, bis schließlich ein Atemzug von irgendwoher in ein kurzes, scharfes Keuchen wie ein ersticktes Blasebalg umschlug, als ob sich etwas darum wickelte und das Atmen erschwerte."
  },
  AvgDialog_120296_Content_34 = {Text = "Dad!"},
  AvgDialog_120296_Content_35 = {
    Text = "Du wurdest von seiner todgleichen Stimme erschreckt und hast dich hastig über die Tür gedrängt."
  },
  AvgDialog_120296_Content_36 = {
    Text = "Drinnen lehnte nur He Fang verzweifelt an der Bettkante und fiel auf die dunkle Bettwäsche, die feucht war, als wäre sie durchtränkt, zusammen mit der gesamten Kabine."
  },
  AvgDialog_120296_Content_37 = {
    Text = "Zerschmetterte Fragmente von Objekten und Stoffen lagen schrecklich verstreut herum. Er kam plötzlich wieder zur Realität zurück, sein Gesicht war von einer abnormalen, kränklichen Farbe bedeckt, und er hob ein hölzernes Kissen auf, um es auf dich zu schlagen."
  },
  AvgDialog_120296_Content_38 = {
    Text = "Wer hat dich hereingelassen!"
  },
  AvgDialog_120296_Content_39 = {
    Text = "Niemand kann unsere Einsamkeit stören, geh raus! Geh weg!"
  },
  AvgDialog_120296_Content_4 = {
    Text = "Ge Mei ist schön, hat einen großartigen Geschmack und ihre Geschenke sind beeindruckend. Fächelst du dir nicht auch auf der einen Seite und dann auf der anderen, wünschst dir, du könntest wie sie sein, mit einem Fächer vor deinem Gesicht?"
  },
  AvgDialog_120296_Content_40 = {
    Text = "Die Frau eilte dir nach und zog schnell die Tür zu, während irgendwoher ein Lärm ertönte."
  },
  AvgDialog_120296_Content_41 = {
    Text = "Ich habe dir gesagt, dass du meinen Herrn nicht stören sollst, er wird wütend. Lauf nicht herum, meine kleine Tante."
  },
  AvgDialog_120296_Content_42 = {
    Text = "Papa... Papa, was ist los? Warum ruft er ständig Herrn Xu?"
  },
  AvgDialog_120296_Content_43 = {
    Text = "<Shake:Herr Xu ist eindeutig heute Morgen früh ausgegangen. Mit wem spricht er? Sein Ausdruck ist so erschreckend...>"
  },
  AvgDialog_120296_Content_44 = {
    Text = "Angelegenheiten, die meinen Herrn betreffen, sind nicht für uns niedere Diener zu regeln."
  },
  AvgDialog_120296_Content_45 = {
    Text = "Du taumelst zu dem Ort, den du am besten kennst, in der Hoffnung, jemanden zu finden, der dir helfen kann."
  },
  AvgDialog_120296_Content_46 = {
    Text = "Das Gemach der Dame, jetzt Xus Gemach, ist auch das Gemach, in dem meine Mutter einst verweilte."
  },
  AvgDialog_120296_Content_47 = {
    Text = "Die Tür, die seit dem Weggang der Mutter verblasst ist, ist nun wieder mit vergoldeten Schnitzereien geschmückt, als ob sie zu einer Art Eingang geworden wäre, bei jedem Öffnen und Schließen einen schläfrigen, überirdischen Duft freisetzend."
  },
  AvgDialog_120296_Content_48 = {
    Text = "Haha, hee hee... Wuwuwuwu... Es stellt sich heraus, dass ich die ganze Zeit falsch lag, völlig irren!"
  },
  AvgDialog_120296_Content_49 = {
    Text = "Hacken, zertrümmern, aufbrechen! Einfach aufbrechen, es dampft immer noch, Ihm angeboten, und sie werden gehorchen. Ich werde nicht mehr im Meer des Leidens leiden müssen!"
  },
  AvgDialog_120296_Content_5 = {
    Text = "Redest du über mich?"
  },
  AvgDialog_120296_Content_50 = {
    Text = "<Change>Xu... unser Retter, unser @3!"
  },
  AvgDialog_120296_Content_51 = {
    Text = "Der ungreifbare Nebel füllte den ganzen Raum, während sie ehrfurchtsvoll die Fächer erhoben, die ihnen am Tag, als Xu das Haus betrat, gegeben wurden, weinend und lachend, und allmählich in ein bizarrs Wimmern übergingen."
  },
  AvgDialog_120296_Content_52 = {
    Text = "Du kannst kein Wort verstehen, das die Dienerinnen im Raum sagen; deine Ohren sind mit Summen und dem Pochen deines Herzens gefüllt. Du stolperst erneut rückwärts, stößt versehentlich gegen das Geländer und verursachst ein Geräusch."
  },
  AvgDialog_120296_Content_53 = {
    Text = "...ja, da ist ein Geräusch."
  },
  AvgDialog_120296_Content_54 = {
    Text = "<Shake:<Red:Ist es ein weiteres Blutopfer, das dargebracht werden kann?>>"
  },
  AvgDialog_120296_Content_55 = {
    Text = "Ihre Stimmen tragen ein leichtes Lachen, und alle Schreie sind verschwunden, ein unerklärliches, schauriges Gefühl der Angst überkommt dich!"
  },
  AvgDialog_120296_Content_56 = {Text = "Run!!!!"},
  AvgDialog_120296_Content_57 = {
    Text = "Das ist der Schrecken, Beute zu sein, die Angst, die seit Urzeiten tief in den Blutlinien aller Kreaturen liegt!"
  },
  AvgDialog_120296_Content_58 = {
    Text = "Oh? Eine bloße Schachtel Schmetterlingscrackern, und meine kleine Jasmin stürzt sich mit so viel Freude in meine Arme?"
  },
  AvgDialog_120296_Content_59 = {
    Text = "Die jadeähnlichen Arme hielten dich gerade noch auf, bevor du fast gefallen wärst. Wenn du durch die Lücken im Hofzaun schaust, schließt der renommierte Inspektor Huang aus Haicheng die Autotür für sie."
  },
  AvgDialog_120296_Content_6 = {
    Text = "*Rufe Ah! Entschuldigung, gnädige Dame!"
  },
  AvgDialog_120296_Content_60 = {
    Text = "Die Gebäckschachtel wird dir überreicht, und die geschichteten, augenförmigen Muster auf dem Blumepapier erschrecken dich völlig. Du atmest tief ein, sammelst deinen Mut und stößt sie auf den Boden."
  },
  AvgDialog_120296_Content_61 = {
    Text = "Wer bist du?! Warum bist du in unserem Haus?! Was ist mit meiner Familie passiert, meinem Vater, meiner Tante, diesen Onkeln? Seit du hier bist, verhalten sich alle seltsam..."
  },
  AvgDialog_120296_Content_62 = {
    Text = "Ups... es ist nur eine kleine Sache, schau, meine kleine Jasmin weint sogar."
  },
  AvgDialog_120296_Content_63 = {
    Text = "Sie war nicht wütend über den Snack, den du umgeworfen hattest; stattdessen beugte sie sich liebevoll herunter und berührte sanft die Ecke deines Auges, wo sich aus Angst Tränen gebildet hatten."
  },
  AvgDialog_120296_Content_64 = {
    Text = "Mein kleiner Jasmin, ist das wirklich dein Zuhause, ein Ort, an dem nicht einmal ein Tropfen Wasser zu finden ist?"
  },
  AvgDialog_120296_Content_65 = {
    Text = "Fräulein! Nur für einen Moment, in dem ich nicht aufgepasst habe, wie konnten Sie... Meine Dame, es tut mir leid, es ist ganz meine Schuld, dass ich auf die junge Dame nicht geachtet habe."
  },
  AvgDialog_120296_Content_66 = {
    Text = "Xu ignorierte die Menschen, die herbeigelaufen kamen, und hielt dich fester, wie immer, streichelte deinen Rücken, als würde sie ein kleines Tier liebkosen, ihre Stimme weich und sanft."
  },
  AvgDialog_120296_Content_67 = {
    Text = "Kleine Jasmin, denke gründlich darüber nach. Was ist mit dieser Angelegenheit los, und wie steht es um jene Angelegenheit? Was ist die Verbindung zwischen ihnen?"
  },
  AvgDialog_120296_Content_68 = {
    Text = "Solange du dich gut benimmst und mir die ganze Zeit gehorsam zuhörst."
  },
  AvgDialog_120296_Content_69 = {
    Text = "Alles kann dir gehören, und jeder kann dein Spielzeug werden."
  },
  AvgDialog_120296_Content_7 = {
    Text = "Tch, welche Dame? Nur eine langhaarige Frau aus einer Buchhandlung, wovor hat sie Angst? Kann sie dich wirklich essen?"
  },
  AvgDialog_120296_Content_70 = {
    Text = "Sie streichelt von deinem Rücken zu deinen Haaren, und nachdem sie schließlich genug mit deinen Haaren gespielt hat, lässt sie los und strahlt vor Freude."
  },
  AvgDialog_120296_Content_71 = {
    Text = "Da jetzt. Bring mein kleines Jasmin ins Bett... sie muss sich ausruhen."
  },
  AvgDialog_120296_Content_72 = {
    Text = "Du bist weit im Nebel gegangen, und im grauen Dunst siehst du ein weites Gebiet aus dunklem Wasser."
  },
  AvgDialog_120296_Content_73 = {
    Text = "Zahlreiche viskose, sich windende Gliedmaßen, bedeckt mit Saugnäpfen, ruhen an der Grenze von Wasser und Nebel, während eine sanfte Gestalt mit dem Rücken zu dir am Ufer sitzt."
  },
  AvgDialog_120296_Content_74 = {
    Text = "Mama? Bist du das?"
  },
  AvgDialog_120296_Content_75 = {
    Text = "<Shake:...Falsch... alles... lauf...>"
  },
  AvgDialog_120296_Content_76 = {
    Text = "Mama, was sagst du? Ich kann dich nicht klar hören."
  },
  AvgDialog_120296_Content_77 = {
    Text = "Du näherst dich und bemerkst plötzlich, dass sie nicht am Wasser sitzt; stattdessen hat sich ihr Unterkörper in unzählige Tentakel verwandelt, die sich ins graue Wasser einfügen."
  },
  AvgDialog_120296_Content_78 = {
    Text = "<Shake:Falsch. Alles davon.>"
  },
  AvgDialog_120296_Content_79 = {
    Text = "<Shake:Sie ist nicht... ES ist nicht...>"
  },
  AvgDialog_120296_Content_8 = {
    Text = "Schaut euch alle an, ihr seht aus wie eine Gruppe von flauschigen Katzen; das ist so süß."
  },
  AvgDialog_120296_Content_80 = {
    Text = "Die Frau drehte sich um, ihr vertrautes Gesicht war mit grauen Tränen streaked, sie schrie und rief dir zu."
  },
  AvgDialog_120296_Content_81 = {
    Text = "<Red:Sie hat das Gesicht ihrer Mutter.>"
  },
  AvgDialog_120296_Content_82 = {
    Text = "<Change>Er ist es nicht! Er ist es nicht! Er ist es nicht! Er ist es nicht!!"
  },
  AvgDialog_120296_Content_83 = {
    Text = "<Red:<Shake:Falsch! Alles falsch!! Nānnān!!! Lauf!! SCHNELL!! LAUF!!!>>"
  },
  AvgDialog_120296_Content_9 = {
    Text = "Keine Sorge, ich bin nur neu hier. Ich habe euch alle so lebhaft plaudern sehen und dachte, ich komme mal rüber und teile ein kleines Flüstern."
  },
  AvgDialog_120297_Content_1 = {
    Text = "Blut des Sire"
  },
  AvgDialog_120297_Content_10 = {
    Text = "Manchmal waren es sie selbst, und manchmal waren es ihre Frauen. In diesen Momenten wurde das Lächeln auf Xus Gesicht ausgeprägter. Als sie ein zweites Mal kamen, erschienen die gleichen schwarzen Fans wie die im Innenhof in ihren Händen."
  },
  AvgDialog_120297_Content_100 = {
    Text = "Doch der heftige und bedrohliche He Fang hatte überraschend seinen Ausdruck gemildert."
  },
  AvgDialog_120297_Content_101 = {
    Text = "Denkst du das wirklich?"
  },
  AvgDialog_120297_Content_102 = {
    Text = "He Lang weiß, dass ich zwar göttliche Macht besitze, aber immer noch mit dem verbunden bin, der mich erweckt. Was auch immer He Lang von mir verlangt, kann ich nur gehorchen; es gibt keine Möglichkeit, dich zu täuschen?"
  },
  AvgDialog_120297_Content_103 = {
    Text = "Genau wie in der Gasse kannst du weder sprechen noch dich bewegen. Es fühlt sich an, als ob diese bizarre \"Göttin\" entschlossen ist, dich zu einem Zuschauer dieser Farce zu machen."
  },
  AvgDialog_120297_Content_104 = {
    Text = "Er ging fröhlich weg, genau wie an diesem Tag vor dem Goldenen Pavillon, ohne dir auch nur einen weiteren Blick zuzuwerfen."
  },
  AvgDialog_120297_Content_105 = {
    Text = "In dem Moment, in dem du einen Laut von dir geben kannst, drehst du dich um und stürzt dich auf Xu, lässt ein tierähnliches Wailen von dir. Füße, Fäuste, Zähne—obwohl du weißt, dass es vergeblich ist, nutzt du jede Angriffsart, die du kennst."
  },
  AvgDialog_120297_Content_106 = {
    Text = "Gib es mir zurück, gib mir Mama zurück, gib mir Papa zurück!"
  },
  AvgDialog_120297_Content_107 = {
    Text = "Xu Zhi Shan steht still und lässt dich ohne Bewegung ausventilieren. Das Lächeln in ihren Augen lässt dich deine Angst vergessen, übrig bleibt nur Wut und Verzweiflung."
  },
  AvgDialog_120297_Content_108 = {
    Text = "Alles ist wegen dir; du bist überhaupt keine Göttin, du bist ein Monster!"
  },
  AvgDialog_120297_Content_109 = {
    Text = "Die Frau vor mir... nickte."
  },
  AvgDialog_120297_Content_11 = {
    Text = "Wenn wir noch länger warten, sehen wir nicht einmal mehr den Schatten von Herrn Xu. Beeil dich."
  },
  AvgDialog_120297_Content_110 = {
    Text = "Das ist richtig, mein kleiner Jasmin, ich bin ein Monster."
  },
  AvgDialog_120297_Content_111 = {
    Text = "Aber der Tod deiner Mutter hat nichts mit mir zu tun; es war er, der zahllose Frauen, einschließlich ihr, getötet hat, nur um mich im Austausch für seinen Reichtum und seine Macht zu beschwören."
  },
  AvgDialog_120297_Content_112 = {
    Text = "Gerade wollte er dich töten. Du willst nicht sterben, und ich habe dir geantwortet. Wenn ich dich im Stich lasse, wirst du zweifellos sterben, oder?"
  },
  AvgDialog_120297_Content_113 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_120297_Content_114 = {
    Text = "Du warst sprachlos, ihre Stimme voller Begeisterung, und ihre schönen Augen funkelten vor Freude."
  },
  AvgDialog_120297_Content_115 = {
    Text = "Jetzt, mein kleiner Jasmin, wie wirst du wählen?"
  },
  AvgDialog_120297_Content_116 = {
    Text = "Du öffnetest deinen Mund vergeblich und starrtest sie letztendlich nur benommen an, das scharfe Klingeln in deinen Ohren rüttelte an deinen Nerven. Sie klopfte dir lediglich auf den Rücken, bevor sie in den Innenhof ging."
  },
  AvgDialog_120297_Content_117 = {
    Text = "Hehe... Bald. Sehr, sehr bald... wird die Zeit kommen, in der du die endgültige Wahl treffen musst."
  },
  AvgDialog_120297_Content_118 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_120297_Content_119 = {
    Text = "Szenen des Tages spielen sich in deinen Träumen ab. Du wachst mitten in der Nacht schreiend auf, und das Haus ist unheimlich still. Niemand antwortet dir, und diese durchdringende Stimme existiert nicht mehr."
  },
  AvgDialog_120297_Content_12 = {
    Text = "Die Rikscha rumpelte heftig. Obwohl es unbemerkt blieb, verlor sie nach dem Wenden und Drehen die Verfolgung, als das Fahrzeug in einen Baumhain einbog."
  },
  AvgDialog_120297_Content_120 = {
    Text = "Der Hunger nagt an deinem Inneren, und nachdem du lange zusammengerollt warst, stehst du schließlich auf und findest, geleitet von Erinnerungen, die Schachtel mit den zerbrochenen Gebäck. Stumm stehst du im Mondlicht und isst alles auf."
  },
  AvgDialog_120297_Content_121 = {
    Text = "Als du wieder einschliefst, kehrtest du an den grauen Wasserrand zurück, wo deine Mutter ihre tentakelartigen Arme ausstreckte und nach dir griff. Hinter ihr war eine andere massive Gestalt vage zu erkennen."
  },
  AvgDialog_120297_Content_122 = {
    Text = "Mama, ist sie noch hier?"
  },
  AvgDialog_120297_Content_123 = {
    Text = "Mama wird immer bei dir sein."
  },
  AvgDialog_120297_Content_124 = {
    Text = "Ich werde immer, immer an der Seite meines kleinen Jasmins sein."
  },
  AvgDialog_120297_Content_125 = {
    Text = "Zwei Stimmen ertönten gleichzeitig in deinen Ohren, und du hast nicht weiter gefragt. Du warst einfach zu müde und zu ängstlich."
  },
  AvgDialog_120297_Content_126 = {
    Text = "Du tauchst ohne Zögern ein in diese erschreckende, klebrige, aber unglaublich sanfte Umarmung."
  },
  AvgDialog_120297_Content_13 = {
    Text = "Du wurdest weggeführt, und aus irgendeinem Grund raste dein Herz immer schneller. Das Einzige, was dich ein wenig besser fühlen ließ, war das feste Halten der Hand der Frau."
  },
  AvgDialog_120297_Content_14 = {
    Text = "Der Himmel verdunkelte sich allmählich, und der Mond schlich lautlos über die Baumwipfel.\nPlötzlich machte die Frau ein Zeichen, dass du still sein solltest."
  },
  AvgDialog_120297_Content_15 = {Text = "Shh—"},
  AvgDialog_120297_Content_16 = {
    Text = "In der Ferne erschien Xus Gestalt, die weiße Kutsche raste davon, während Herr Du still neben ihr stand. In der Ecke zogen mehrere lange Schatten durch die Bäume und wurden vom Mondlicht auf den Boden geworfen."
  },
  AvgDialog_120297_Content_17 = {
    Text = "Herr Du, Inspektor Huang, der Leiter der Nordschule für Flussverkehr, und auf der Hauptstraße, oh mein, Herr Xu ist wirklich bemerkenswert..."
  },
  AvgDialog_120297_Content_18 = {
    Text = "In der Ferne erschienen die Gesichter der Männer mit einem abnormalen Röte, ähnlich wie das des Vaters an jenem Tag. Es begann mit leisen Murmeln, die später in schnelle, aufgeregte zischende Schreie übergingen, fast wie ein Gesang."
  },
  AvgDialog_120297_Content_19 = {
    Text = "<Shake:Sie... kann... nicht... bleiben...>"
  },
  AvgDialog_120297_Content_2 = {
    Text = "Alle Konkubinen werden immer mehr wie Xu, und Vater hat die Tür nicht wieder verlassen."
  },
  AvgDialog_120297_Content_20 = {
    Text = "<Shake:Töte... nur dann...>"
  },
  AvgDialog_120297_Content_21 = {
    Text = "<Shake:Töte... Töte... TÖTE!! TÖTE sie—HACKE sie in Stücke!!!>"
  },
  AvgDialog_120297_Content_22 = {
    Text = "<Change>Mein, mein, mein, mein, mein, mein, sie gehört mir!!"
  },
  AvgDialog_120297_Content_23 = {
    Text = "Das blasse Licht durchdrang deine Augen, und erst dann wurde dir bewusst, dass hinter jedem Mann eine Sense lauerte, die nun einheitlich hochgehoben war—"
  },
  AvgDialog_120297_Content_24 = {
    Text = "Ha—hahaha, ahhahahahahaha!!!"
  },
  AvgDialog_120297_Content_25 = {
    Text = "Die Männer schlossen sich allmählich zusammen, und Xu brach plötzlich in Gelächter aus, als hätte er das lächerlichste Ding der Welt gesehen, und zeigte mit dem Finger nacheinander auf ihre Gesichter."
  },
  AvgDialog_120297_Content_26 = {
    Text = "Im nächsten Moment stürzten scharfe Sensen aus allen Richtungen herab, das dumpfe Geräusch von zerfetztem Fleisch, das Knacken von durchtrennten Knochen, und eine Hand so weiß wie Jade wurde hochgeworfen."
  },
  AvgDialog_120297_Content_27 = {
    Text = "Zirp, schnapp."
  },
  AvgDialog_120297_Content_28 = {
    Text = "Mmh, mmh mmh mmh mmh mmh mmh!"
  },
  AvgDialog_120297_Content_29 = {
    Text = "Du bist fest in ihren Armen gehalten, ihre Hände bedecken fest deinen Mund und ersticken die schmerzhaften Schreie, die auszubrechen drohen."
  },
  AvgDialog_120297_Content_3 = {
    Text = "Die Mutter erscheint nicht mehr in deinen Träumen. Manchmal träumst du von Xus Gesicht unter jedem Ventilator, und manchmal träumst du davon, dass dein Vater von einem Monster gefressen wird, und wachst am Ende schweißgebadet auf."
  },
  AvgDialog_120297_Content_30 = {
    Text = "<Change>Kopf, Hals, Brust, Arme, Bauch..."
  },
  AvgDialog_120297_Content_31 = {
    Text = "<Shake:Bohre aus dem Schädel, bohre aus dem Hals, bohre aus der Brusthöhle, bohre aus den Armen, bohre aus dem Bauch...>"
  },
  AvgDialog_120297_Content_32 = {
    Text = "<Change>Bohre den Schädel aus, bohre den Hals aus, bohre die Brusthöhle aus, bohre aus..."
  },
  AvgDialog_120297_Content_33 = {Text = "Mein Herr."},
  AvgDialog_120297_Content_34 = {
    Text = "Sanft, flirtend und süß."
  },
  AvgDialog_120297_Content_35 = {
    Text = "So weit weg, wie Nebel, wirbelt es um die Konturen deines Ohres und in deinen Geist."
  },
  AvgDialog_120297_Content_36 = {
    Text = "Der Blutnebel vertiefte sich allmählich, und einer nach dem anderen tauchten Gestalten aus den Leichnamen auf, deren Arme so weiß wie Jade waren und mit schwarzem Schlamm flossen, hoch erhoben."
  },
  AvgDialog_120297_Content_37 = {
    Text = "Es tut so weh, bitte gib mir einen Kuss—"
  },
  AvgDialog_120297_Content_38 = {
    Text = "<Change>Ich, @3, gib mir einen Kuss..."
  },
  AvgDialog_120297_Content_39 = {
    Text = "<Change>Ich, @3, gib mir @4!"
  },
  AvgDialog_120297_Content_4 = {
    Text = "Fräulein, bitte hören Sie auf, sich zu benehmen. Herr Xu ist so gut zu Ihnen und bringt Ihnen jeden Tag so viele frische Lebensmittel und Spielzeuge."
  },
  AvgDialog_120297_Content_40 = {
    Text = "<Change>Es tut so weh, bitte gib mir einen Kuss!"
  },
  AvgDialog_120297_Content_41 = {
    Text = "Xu... ein Monster, das Xu ähnelt, ihre Unterkörper verschmolzen mit zerbrochenen Leichenteilen, der Schlamm bedeckt ihr ganzes Gesicht, nur der Umriss ihrer Lippen ist sichtbar."
  },
  AvgDialog_120297_Content_42 = {
    Text = "Auf jedem \"Xu\"-Gesicht waren Dutzende von prallen, schönen, blütenblattartigen Lippen, die zu den Männern saugten, die wie unter einem Zauber verrückt lachten."
  },
  AvgDialog_120297_Content_43 = {
    Text = "<Change>Mahlen—Mahlen—"
  },
  AvgDialog_120297_Content_44 = {
    Text = "Das Geräusch von zerbrochenen Schädeln, das Geräusch von brechenden Schädeln."
  },
  AvgDialog_120297_Content_45 = {
    Text = "<Change>Schlürf—Glug—"
  },
  AvgDialog_120297_Content_46 = {
    Text = "Sauger Geräusche, Essgeräusche."
  },
  AvgDialog_120297_Content_47 = {
    Text = "Du sahst hilflos zu, wie ihre Köpfe zerbrachen und dann wieder in perfekten Zustand zurückkehrten. Die „Xu“ stießen zufriedene Seufzer aus und versammelten sich inmitten der zufriedenen Murmeln."
  },
  AvgDialog_120297_Content_48 = {
    Text = "Herr Du, Inspektor Huang, der Leiter der Nordschule für Flussverkehr..."
  },
  AvgDialog_120297_Content_49 = {
    Text = "Sie standen schweigend auf, als wäre nichts geschehen, taumelten verwirrt auseinander, während Xu längst spurlos verschwunden war."
  },
  AvgDialog_120297_Content_5 = {
    Text = "Die Frau seufzte und benutzte ein Taschentuch, um den erschreckten Schweiß von deiner Stirn abzuwischen."
  },
  AvgDialog_120297_Content_50 = {
    Text = "Diese Hand ließ dich schließlich los, und in der erstickenden Stille fielen deine Tränen unkontrolliert. In dem Moment, als du dich umdrehst, zitterten deine Pupillen heftig."
  },
  AvgDialog_120297_Content_51 = {Text = "Oops!..."},
  AvgDialog_120297_Content_52 = {
    Text = "Ich habe darüber nachgedacht, wie ich ehrlich zu meinem kleinen Jasmin sein kann."
  },
  AvgDialog_120297_Content_53 = {
    Text = "Deine Pupillen verengen sich bis zum Äußersten, und am Ende bleibt nur die Frau vor dir. In einem Augenblick sendet dein bereits überforderter Geist einen Schmerzstoß intensiver Qual."
  },
  AvgDialog_120297_Content_54 = {
    Text = "Wie sieht sie aus, die Frau mit der scharfen Stimme?"
  },
  AvgDialog_120297_Content_55 = {
    Text = "Die Diener in Ihrem Zimmer wurden vor langer Zeit entlassen, als Ihre Mutter starb."
  },
  AvgDialog_120297_Content_56 = {
    Text = "Niemand hat sich jemals um dein Leben oder Sterben gekümmert, und du hast nie wirklich gesehen, wie sie aussieht, aber warum finden alle ihr Aussehen so natürlich?"
  },
  AvgDialog_120297_Content_57 = {
    Text = "Ich habe mich in diese Haut verliebt... Ich liebte den Duft von Jasmin, den sie trug. Von Anfang an habe ich mich gefragt... wie würde ihr \"Kleiner Jasmin\" – mein kleiner Jasmin – aussehen?"
  },
  AvgDialog_120297_Content_58 = {
    Text = "Also, ich konnte es schon lange nicht mehr widerstehen, meine kleine Jasmin zu sehen."
  },
  AvgDialog_120297_Content_59 = {
    Text = "Du fliehst um dein Leben. Sie hält dich nicht auf, sondern beobachtet dich nur mit einem Lächeln hinter der Tür, als würde sie eine verängstigte kleine Wildkatze beobachten, die davonläuft."
  },
  AvgDialog_120297_Content_6 = {
    Text = "Fräulein, wenn Sie wirklich so ängstlich sind, habe ich eine Idee."
  },
  AvgDialog_120297_Content_60 = {
    Text = "Papa! Xu ist ein Monster, sie..."
  },
  AvgDialog_120297_Content_61 = {
    Text = "Du kannst dich nicht erinnern, wie lange du schon rennst oder wie viele falsche Abbiegungen du genommen hast. Im erstaunten Blick des Türstehers stürmst du auf das Zimmer deines Vaters zu, öffnest die Tür fast mit einem Ruck und greifst nervös nach dem Saum der Kleidung deines Vaters."
  },
  AvgDialog_120297_Content_62 = {
    Text = "Doch sobald Xus Name deine Lippen verlässt, wirst du mit einem schweren Schlag ins Gesicht getroffen."
  },
  AvgDialog_120297_Content_63 = {
    Text = "Ich habe dir gesagt, du musst sie <Red:\"Mutter\"> nennen."
  },
  AvgDialog_120297_Content_64 = {
    Text = "Das Gesicht des Vaters war ungewöhnlich wachsam und ernst, das Chaos der letzten Tage war vollständig verschwunden. Er packte dich am Kragen und riss dich von seiner Seite weg."
  },
  AvgDialog_120297_Content_65 = {
    Text = "Nein, Papa, sie ist jemand geworden, der mir nahe steht. Sie interagiert mit vielen Menschen und hat sie sogar mitgebracht—"
  },
  AvgDialog_120297_Content_66 = {Text = "Genug!"},
  AvgDialog_120297_Content_67 = {
    Text = "Damals war es Xu, der dich mochte, weshalb ich dich zu Hause behalten habe, aber du hast dich als so undankbar erwiesen wie deine kurzlebige Mutter."
  },
  AvgDialog_120297_Content_68 = {
    Text = "Du machst alles durcheinander, redest Unsinn und sprichst respektlos mit deiner Mutter! Geh in die Halle und knie als Strafe nieder, und steh nicht auf, bis vor der Stunde des Hahns!"
  },
  AvgDialog_120297_Content_69 = {
    Text = "Sie ist nicht meine Mutter, sie ist ein menschenfressendes Monster!"
  },
  AvgDialog_120297_Content_7 = {
    Text = "Du hast so viel Angst vor Mr. Xu. Warum folgst du ihm nicht einfach und siehst, was er jeden Tag macht? Wenn er wirklich ein Monster ist, gehen wir zusammen zu dem alten Mann und lassen ihn ihn aus dem Haus werfen, einverstanden?"
  },
  AvgDialog_120297_Content_70 = {
    Text = "Du schrienst aus vollem Halse, und der Raum fiel für einen Moment in Schweigen. Dann hörtest du..."
  },
  AvgDialog_120297_Content_71 = {
    Text = "<Red:Das tiefe, kalte Kichern deines Vaters.>"
  },
  AvgDialog_120297_Content_72 = {
    Text = "<Shake:Ein Monster?>"
  },
  AvgDialog_120297_Content_73 = {
    Text = "Xu, es ist die \"Göttin\", die ich persönlich als Opfer einzeln ausgewählt und mit meinen eigenen Händen aufgeschnitten habe, unzählige Preise bezahlt und all meine Kräfte aufgewendet habe, dass ich sie schließlich beschworen habe <Red:\"Göttin\">!"
  },
  AvgDialog_120297_Content_74 = {
    Text = "Ich habe es so oft versucht, doch diese oberflächlichen und gewöhnlichen Menschen verdienen ihre Aufmerksamkeit nicht. Glaubst du, mein Herz schmerzt nicht? Ich kann es auch nicht ertragen, deine Mutter zu sehen."
  },
  AvgDialog_120297_Content_75 = {
    Text = "Wie ein Donnerschlag fällt es dir schwer, die Bedeutung der Worte deines Vaters zu begreifen, während dein Bewusstsein vollständig von dem scharfen Klingelton übernommen wird."
  },
  AvgDialog_120297_Content_76 = {
    Text = "<Shake:Du solltest dich geehrt fühlen; ihr Fleisch bildet die irdische Form der Göttlichen Jungfrau.>"
  },
  AvgDialog_120297_Content_77 = {
    Text = "Die Stimme des Vaters strahlt eine eisige Kälte aus, und du bemerkst mit einem Schaudern, dass er sich unheilvoll zwischen dir und die Tür positioniert hat, während er Schritt für Schritt auf dich zugeht."
  },
  AvgDialog_120297_Content_78 = {
    Text = "Da du bereits alles weißt, kannst du nicht in diesem Haus bleiben, und ich werde dich niemals hinauslassen und zu viel reden lassen."
  },
  AvgDialog_120297_Content_79 = {
    Text = "Bevor dein Schrei entweichen konnte, wurde dein Hals von deinem Vater ergriffen, dessen Gesicht von Wahnsinn erfüllt war, und deine Sicht wurde schnell blutrot getönt."
  },
  AvgDialog_120297_Content_8 = {
    Text = "Fahren Sie Herrn Xu weg?"
  },
  AvgDialog_120297_Content_80 = {
    Text = "Die <Red:Göttin> ist herabgestiegen. Von jetzt an wird sie <Red:für immer> mir gehören. Ruhm, Reichtum... sie bedeuten jetzt nichts. Solange die <Red:Göttin> bei mir ist, war jedes Opfer es wert!"
  },
  AvgDialog_120297_Content_81 = {
    Text = "<Shake:Mama, hilf...>"
  },
  AvgDialog_120297_Content_82 = {
    Text = "Ich... will nicht sterben, ich will leben, Mama..."
  },
  AvgDialog_120297_Content_83 = {
    Text = "<Change><Shake:Ich will nicht sterben, es tut weh, es tut weh, ES TUT WEH, Mama, rette mich, RETTE MICH, RETTE MICH, hilf mir @4!!>"
  },
  AvgDialog_120297_Content_84 = {
    Text = "Jemand, bitte rette mich..."
  },
  AvgDialog_120297_Content_85 = {
    Text = "Niemand antwortet auf deine stillen Gebete."
  },
  AvgDialog_120297_Content_86 = {
    Text = "Chaos. Ersticken. Schmerz. Ruhe... Der vertraute, fischig-süße Duft der Magnolie."
  },
  AvgDialog_120297_Content_87 = {
    Text = "<Red:<Shake:Quieeek—>>"
  },
  AvgDialog_120297_Content_88 = {
    Text = "Benommen brach ein schwarzer Tentakel durch die Tür, schwang mit immensem Schwung und schleuderte ihn direkt auf das Bett."
  },
  AvgDialog_120297_Content_89 = {
    Text = "He Lang, wie kannst du mit einem Kind konkurrieren?"
  },
  AvgDialog_120297_Content_9 = {
    Text = "Das Geräusch von Autohupen kam vom Vordereingang, und jeden Tag warteten verschiedene Gesichter vor dem Anwesen der Familie He, allesamt bedeutende Persönlichkeiten, mit denen der Besitzer dieses Anwesens einst in Verbindung treten wollte."
  },
  AvgDialog_120297_Content_90 = {
    Text = "Eine sanfte Umarmung ergreift dich, während die Luft erneut deine fast entleerten Lungen füllt, während du sanft deinen Schwanzfächer hebst, unsichtbar von irgendwoher unterstützt."
  },
  AvgDialog_120297_Content_91 = {
    Text = "Es ist nur so, dass sie etwas gesehen hat, was sie nicht hätte sehen sollen. Ich möchte nicht, dass sie sich daran erinnert, also wird sie es natürlich nicht tun."
  },
  AvgDialog_120297_Content_92 = {
    Text = "Ihr Ton ist so fröhlich und unauffällig wie eh und je, selbst der Druck ihrer Hand, die auf deinem Kopf ruht."
  },
  AvgDialog_120297_Content_93 = {
    Text = "Draußen vor der Tür ist die Stimme eines berichtenden Dieners zu hören."
  },
  AvgDialog_120297_Content_94 = {
    Text = "Mein Herr, es warten mehrere Herren in der Eingangshalle auf Sie."
  },
  AvgDialog_120297_Content_95 = {
    Text = "Hes Gesicht von He Fang veränderte sich drastisch und sah sogar schlimmer aus als in dem Moment, als er gerade dabei war, dich zu töten."
  },
  AvgDialog_120297_Content_96 = {
    Text = "Qingqing, warum hast du wieder angefangen? Ich habe gesagt, dass materielle Besitztümer für mich nichts mehr bedeuten; nur du, nur du musst mein sein."
  },
  AvgDialog_120297_Content_97 = {
    Text = "Seit ich von dir, He Lang, erweckt wurde, sind andere nur flüchtige Schatten. Dennoch erinnere ich mich an das große Vorhaben, das du planst, und bin bereit, meinen bescheidenen Beitrag zu leisten."
  },
  AvgDialog_120297_Content_98 = {
    Text = "Was ich tue, ist lediglich, mehr Unterstützung zu suchen, während ich mit dir, He Lang, in dieser Welt bleibe."
  },
  AvgDialog_120297_Content_99 = {
    Text = "In Xus Augen war eindeutig kein Hauch von Aufrichtigkeit zu sehen, etwas, das sogar du als Kind erkennen konntest. Ganz zu schweigen davon, dass sie gerade die Person, der sie so viel Zärtlichkeit entgegengebracht hatte, gnadenlos hinausgeworfen hatte."
  },
  AvgDialog_120298_Content_1 = {
    Text = "Der Traumlose"
  },
  AvgDialog_120298_Content_10 = {
    Text = "Wenn ich mit ihnen spreche, bohrt sich dein Duft immer wieder in meine Nasenlöcher, und allein der Gedanke daran, dass du dich anderen Männern näherst, macht mich völlig verrückt!"
  },
  AvgDialog_120298_Content_11 = {
    Text = "Ich habe dir gesagt, alles, was ich brauche, ist, dass du an meiner Seite bist. Warum gehörst du nicht nur mir? Warum flirtest du immer noch mit anderen Männern!"
  },
  AvgDialog_120298_Content_12 = {
    Text = "So eine verwirrte Miene hast du noch nie auf Xus Gesicht gesehen; sie scheint nach einem Ausweg zu suchen, ihr Blick wandert wild umher und landet überraschend auf dir, der hinter dem Fenster versteckt ist und von niemandem bemerkt wird."
  },
  AvgDialog_120298_Content_13 = {
    Text = "Du hast dich instinktiv unter das Fensterbrett versteckt und Xu's Blick bemerkt. Du hast zurückgeschaut und dann sind deine Augen wieder zu ihr zurückgekehrt."
  },
  AvgDialog_120298_Content_14 = {
    Text = "Denkst du immer noch darüber nach, wie du laufen kannst? Gib es auf. Ich bin dein <Red:Erwecker>, deine Kraft ist mit mir verbunden, und deine göttliche Kraft hat keinen Einfluss auf mich."
  },
  AvgDialog_120298_Content_15 = {
    Text = "<Red:<Shake:Ich verstehe jetzt vollständig. Solange ich dich töte, nur indem ich dich ermorde... können wir wirklich für immer zusammen sein.>>"
  },
  AvgDialog_120298_Content_16 = {
    Text = "Du hältst den Atem an und drehst dich um, dann rennst du hastig von einem Raum zum anderen, in der Hoffnung, jemanden zu finden, der sie aufhalten kann."
  },
  AvgDialog_120298_Content_17 = {
    Text = "Nein, nein, nein. Das große He-Anwesen ist leer, nicht einmal ein Türsteher ist in Sicht."
  },
  AvgDialog_120298_Content_18 = {
    Text = "Sogar das Tor des Innenhofs ist mit einem schweren Vorhängeschloss verriegelt, und ein bodenloser grauer Nebel wirbelt draußen."
  },
  AvgDialog_120298_Content_19 = {
    Text = "Wenn das so weitergeht, wird Herr Xu enden wie Mama..."
  },
  AvgDialog_120298_Content_2 = {
    Text = "Am nächsten Tag, vor der Morgendämmerung, hallte ein verzweifelter Schrei durch den Innenhof."
  },
  AvgDialog_120298_Content_20 = {
    Text = "<Shake:Du solltest dich verstecken. Du solltest verborgen bleiben, bis alles vorbei ist.>"
  },
  AvgDialog_120298_Content_21 = {
    Text = "Aber du hast keinen Ort, wohin du gehen kannst. Du hast dieses Ding gefunden, hast deine Hände hinter deinem Rücken versteckt und bist wieder auf Mamas altes Zimmer zugegangen."
  },
  AvgDialog_120298_Content_22 = {
    Text = "<Red:<Shake:Meine Frau... mein Liebling... du kannst nur mein sein.>>"
  },
  AvgDialog_120298_Content_23 = {
    Text = "In dem Moment, als die helle Sense erhoben wurde, tauschtest du einen Blick mit Xu aus; ihre Augen leuchteten plötzlich auf und blitzten mit einer Bitte."
  },
  AvgDialog_120298_Content_24 = {
    Text = "Aber dann schüttelte sie subtil den Kopf—"
  },
  AvgDialog_120298_Content_25 = {
    Text = "<Red:Lauf weg.>"
  },
  AvgDialog_120298_Content_26 = {
    Text = "Diese schönen Augen haben sich geschlossen, und ihr Meister ist bereit zur Schlachtung."
  },
  AvgDialog_120298_Content_27 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_120298_Content_28 = {Text = "ARGH!!"},
  AvgDialog_120298_Content_29 = {
    Text = "Du Elender, wie kannst du es wagen!"
  },
  AvgDialog_120298_Content_3 = {
    Text = "Sein Gebrüll ist verzerrt, giftig und voller Bosheit. Du hast keine Zeit zum Nachdenken; ein Gefühl enormer Angst zwingt dich, auf die Quelle des Geräusches zuzulaufen."
  },
  AvgDialog_120298_Content_30 = {
    Text = "Die Sense klirrte, als sie zu Boden fiel, und He Fang, mit schmerzverzerrtem Gesicht, hielt sich den unteren Rücken, wo ein kleines Messer, das du gefunden hattest, tief in seinem Körper steckte."
  },
  AvgDialog_120298_Content_31 = {
    Text = "In einem Wutanfall drehte sich He Fang um und griff nach dir. Plötzlich hörtest du eine Reihe von Kichern, nicht nur eines, während die Quelle der Geräusche dicht in das Abteil strömte."
  },
  AvgDialog_120298_Content_32 = {
    Text = "Mitten in den Scherzen brach ein unkontrollierbares Lachen aus. Xu, hinter He Fang, lachte so laut, dass er sich vor Lachen krümmte, und Tränen liefen ihm über das Gesicht."
  },
  AvgDialog_120298_Content_33 = {
    Text = "AHAHA! AHAHAHAHAHAHA! Kleine Jasmin... meine liebste, am meisten geliebte Kleine Jasmin. Du hast mich wirklich nicht enttäuscht – du bist so interessant, wie ich es mir vorgestellt habe!"
  },
  AvgDialog_120298_Content_34 = {
    Text = "Frauen in gelben und schwarzen Qipaos traten ein, ihre Faltfächer verdeckten ihre Nasen und Lippen. Jede einzelne von ihnen hatte ein Paar sehr, sehr schöne Augen."
  },
  AvgDialog_120298_Content_35 = {
    Text = "In einem Moment purer Angst, bevor seine Schreie widerhallten, hatte dich bereits eine kalte, sanfte Umarmung umhüllt."
  },
  AvgDialog_120298_Content_36 = {
    Text = "<Red:Ekliges Ding. Du wirst die Augen meines kleinen Jasmins nicht verschmutzen.>"
  },
  AvgDialog_120298_Content_37 = {
    Text = "<Shake:Mein Herr...>"
  },
  AvgDialog_120298_Content_38 = {
    Text = "<Shake:Mein Herr...>"
  },
  AvgDialog_120298_Content_39 = {
    Text = "Was machst du? Bist du verrückt! Geht raus, ihr alle, geht raus."
  },
  AvgDialog_120298_Content_4 = {
    Text = "Xu wurde von Ho Fong gegen das Bett gedrängt, seine Augen blutunterlaufen und sein Haar zerzaust, als hätte er die ganze Nacht nicht geschlafen."
  },
  AvgDialog_120298_Content_40 = {
    Text = "Die Konkubinen vor mir schoben langsam die Fächer zur Seite und enthüllten dasselbe Gesicht hinter jedem Fächer."
  },
  AvgDialog_120298_Content_41 = {
    Text = "Warum hat der Herr uns in Opfer verwandelt?"
  },
  AvgDialog_120298_Content_42 = {
    Text = "Warum hat der Herr unsere Gliedmaßen abgetrennt?"
  },
  AvgDialog_120298_Content_43 = {
    Text = "Zahlreiche Xus sind sich He Fangs zitternden Wutausbrüchen nicht bewusst und umringen He Fang verspielt in der Mitte, während schwarze Fächer und Sense abwechselnd einen Kreis um ihn bilden."
  },
  AvgDialog_120298_Content_44 = {
    Text = "<Change>Sind wir jetzt schön genug?"
  },
  AvgDialog_120298_Content_45 = {
    Text = "<Change>Können wir jetzt für immer mit meinem Herrn zusammenbleiben?"
  },
  AvgDialog_120298_Content_46 = {
    Text = "Ein massiver Phantom stieg von Xus Rücken in den Himmel empor, eins, zwei, drei... unzählige drachenzahnartige Münder quollen aus der geschwollenen Haut, tropfend vor Speichel, begierig darauf, auszuwählen und zu verschlingen,"
  },
  AvgDialog_120298_Content_47 = {
    Text = "Die federartigen Tentakeln erstrecken sich über den Hof der Familie He, verhüllen alles Licht und dämpfen alle Geräusche."
  },
  AvgDialog_120298_Content_48 = {
    Text = "Dein Blick ist im Nebel gehüllt, und alles, was du wahrnehmen kannst, ist der seltsame Duft, der von Xu ausgeht, und die unheimlichen, langsamen Geräusche des Schmausens."
  },
  AvgDialog_120298_Content_49 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_120298_Content_5 = {
    Text = "Meine dumme Tochter hat nichts Falsches gesagt... Ich kann es riechen."
  },
  AvgDialog_120298_Content_50 = {
    Text = "Nachdem das kontinuierliche Saugen aufgehört hatte, stand He Fang schweigend auf und ging nach draußen, um sich in einer Gruppe von Männern zu stellen, die ebenfalls in Stille warteten."
  },
  AvgDialog_120298_Content_51 = {
    Text = "Inspektoren, Präsidenten, Vorsitzende... Ihre Frauen stehen neben den Männern, das aufsteigende Sonnenlicht blendet dich, und du siehst das gleiche geheimnisvolle Lächeln auf ihren Gesichtern wie das von Xu."
  },
  AvgDialog_120298_Content_52 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_120298_Content_53 = {
    Text = "Wo immer du sagst, dass deine Macht mit ihm verbunden ist, wirst du verschwinden, jetzt, wo er so geworden ist?"
  },
  AvgDialog_120298_Content_54 = {
    Text = "Das ist das Erste, was meine kleine Jasmin fragt? Wirklich... ich bin so berührt."
  },
  AvgDialog_120298_Content_55 = {
    Text = "Ihre Finger streichen über deine Stirn und ruhen schließlich an der Spitze deiner Nase."
  },
  AvgDialog_120298_Content_56 = {
    Text = "Vielleicht ja, vielleicht... nein, aber möchtest du mein Meister sein?"
  },
  AvgDialog_120298_Content_57 = {
    Text = "Xu griff leicht in die Luft und zog ein Seidentuch hervor, so dünn wie der Flügel einer Zikade. Er tauchte den silbernen Pinsel in die Tinte und entfaltete es vor dir."
  },
  AvgDialog_120298_Content_58 = {
    Text = "Ich werde dir alles geben, was nicht erhalten wurde, sowie das Beste der Welt."
  },
  AvgDialog_120298_Content_59 = {
    Text = "Als meine Mutter lebte, wurde Haicheng von einem neuen Trend erfasst, und du hattest Bücher gelesen und das Schreiben geübt."
  },
  AvgDialog_120298_Content_6 = {
    Text = "<Shake:<Red:Diese Männer...>>"
  },
  AvgDialog_120298_Content_60 = {
    Text = "Xu nahm deine Hand und wartete darauf, dass du anfängst zu schreiben, und du... wie war dein Name nochmal?"
  },
  AvgDialog_120298_Content_61 = {
    Text = "Der kupferne Spiegel, bespritzt mit frischem rotem Flüssigkeit, spiegelt die zarten und jugendlichen Züge einer östlichen Person wider, die einem Bündel blasser und fragiler Jasminblüten ähnelt."
  },
  AvgDialog_120298_Content_62 = {
    Text = "Du blinzelst verwirrt, und das kleine Mädchen im Spiegel blinzelte zurück. \n Du erinnerst dich, der Seidenstoff trug deine kindliche Handschrift, und dein Name war—"
  },
  AvgDialog_120298_Content_63 = {Text = "He Fang."},
  AvgDialog_120298_Content_64 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_120298_Content_65 = {
    Text = "Also, die Anführerin dieser Untergrundgesellschaft, die später in Haicheng auftrat, ist ein kleines Mädchen von etwa der gleichen Größe wie Jenkins?!"
  },
  AvgDialog_120298_Content_66 = {
    Text = "Dein Kopf pocht heftig aufgrund der Nachwirkungen des Traums, und du wirst von der Frau, die nach deinem Aufwachen lautlos erscheint, erschreckt."
  },
  AvgDialog_120298_Content_67 = {
    Text = "Das Wohnheim der Mythag sollte wirklich einige Sicherheitsmaßnahmen umsetzen. In diesem Sinne beginnst du darüber nachzudenken, was dich vor dieser Frau schützen könnte, die nicht einmal vor Kindern Halt macht."
  },
  AvgDialog_120298_Content_68 = {
    Text = "...Laut den Aufzeichnungen gibt es in den Legenden des Fernen Ostens einen alten bösen Gott, der als <Red:\"Die Obsidianmatriarchin der Tausend Fächer\"> bekannt ist. Er erfreut sich daran, die Herzen der Menschen zu manipulieren und schwelgt im Gehirnmaterial derjenigen, die Wünsche nach ihm hegen."
  },
  AvgDialog_120298_Content_69 = {
    Text = "Selbst wenn du nur ihre Augen sehen kannst, ist klar, dass die Frau vor dir glücklich lächelt. Sie ruht faul ihr Kinn auf ihrer Hand, und du kannst nicht anders, als dich zu fragen, ob ihr Blick sogar einen Mop liebevoll erscheinen lassen könnte."
  },
  AvgDialog_120298_Content_7 = {
    Text = "Dachtest du, du könntest mich täuschen? Vergiss nicht, ich bin derjenige, der dich persönlich mit der Leiche meiner Frau <Red:\"Leiche\"> herbeigerufen hat; wie könnte ich diesen Duft jemals verwechseln?"
  },
  AvgDialog_120298_Content_70 = {
    Text = "Du verstehst mich so gut, das macht mich wirklich überglücklich."
  },
  AvgDialog_120298_Content_71 = {
    Text = "Dieser törichte Mann kam in den Besitz einer alten Schriftrolle und wollte mich beschwören, um Täuschungszauber zu wirken, die unzählige Menschen töteten, und am Ende blieb selbst seine geliebte Frau, die ihn von ganzem Herzen liebte, nicht verschont."
  },
  AvgDialog_120298_Content_72 = {
    Text = "Ursprünglich fand ich es nur amüsant, dass der Hass seiner Frau mich dazu brachte, ihr ihren Feind schmecken lassen zu wollen."
  },
  AvgDialog_120298_Content_73 = {
    Text = "Doch zu dieser Zeit war Shencheng von dem überwältigenden Gestank von Verfall und Bosheit erfüllt, was mich... zögerte, zu gehen."
  },
  AvgDialog_120298_Content_74 = {
    Text = "...Du brauchst tatsächlich keinen Linker, oder?"
  },
  AvgDialog_120298_Content_75 = {
    Text = "Ich habe die „Silberlageraufzeichnungen“ gelesen. Du bist perfekt in der Lage, die Erweckungszeremonie selbstständig abzuschließen. Deine geistige Gesundheit zu bewahren wird ein Kinderspiel für dich sein."
  },
  AvgDialog_120298_Content_76 = {
    Text = "Was ist dein Zweck, aktiv mit He Fang in Haicheng zu verbinden?"
  },
  AvgDialog_120298_Content_77 = {
    Text = "Xu schwieg, ein Hauch von Nebel wirbelte um dich und erleichterte sanft den Druck in deinem Kopf. Sie zwinkerte dir von hinter dem Bildschirm zu."
  },
  AvgDialog_120298_Content_78 = {
    Text = "Ich dachte ursprünglich, dass es in dieser Welt keinen Unterschied zwischen Erwachsenen und Erwachsenen gibt, aber jedes Kind ist anders als das andere."
  },
  AvgDialog_120298_Content_79 = {
    Text = "Ich nähre sie mit Nebel und gieße sie mit Macht und Verlangen. Ich liebe sie, warum kommst du also immer noch, um mich zu bestrafen?"
  },
  AvgDialog_120298_Content_8 = {
    Text = "Wenn es nicht für deine Intimität mit ihnen wäre, warum würden sie dann einen Duft ausstrahlen, der zu <Red:deinem Duft> gehört?"
  },
  AvgDialog_120298_Content_80 = {
    Text = "Das ist keine Liebe"
  },
  AvgDialog_120298_Content_81 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_120298_Content_82 = {
    Text = "Hehe, ich verstehe wirklich nicht, was menschliche Liebe ist. Ich werde die besten Geschenke in dieser Welt anbieten: Essen, Spielzeug und die Macht, ein Reh ein Pferd zu nennen."
  },
  AvgDialog_120298_Content_83 = {
    Text = "Und natürlich... werde ich die Bezahlung erhalten, die ich mir wünsche. Und an dem Tag, an dem du dich in Not befindest, mein kleiner Jasmin... wie wirst <Italic:du> dich entscheiden?"
  },
  AvgDialog_120298_Content_84 = {
    Text = "In meinem Traumland bin ich immer bereit, auf dein Kommen zu warten, jederzeit und überall."
  },
  AvgDialog_120298_Content_85 = {
    Text = "Sanft, umgeben von den zarten, verspielten Kichern, breitete sich der Nebel aus – im nächsten Moment blieb nur der Duft der Magnolie im Schlafsaal zurück."
  },
  AvgDialog_120298_Content_9 = {
    Text = "Er lachte plötzlich nervös, lehnte sich vor und griff Xu's Handgelenk, das den Fächer hielt."
  },
  AvgDialog_120313_Content_1 = {
    Text = "Inzwischen\naußerhalb der schwarzen Sonne"
  },
  AvgDialog_120313_Content_10 = {
    Text = "Jenseits der Milliarden von blitzenden Sternen kämpft die Gestalt mühsam gegen die turbulente Strömung und kommt Schritt für Schritt auf dich zu."
  },
  AvgDialog_120313_Content_11 = {Text = "Ramona!!!"},
  AvgDialog_120313_Content_12 = {
    Text = "Du hast ihre Konturen, ihr Gesicht und ihre Augen, die vor Freude strahlen, klar gesehen; es ist keine falsche Illusion mehr, sondern nicht nur eine gedämpfte Stimme."
  },
  AvgDialog_120313_Content_13 = {
    Text = "Die durch den Tunnel verbundenen Energiewellen heulen und lassen dein Haar wehen. Schließlich berühren sich eure Fingerspitzen und umarmen sich fest."
  },
  AvgDialog_120313_Content_14 = {
    Text = "Die Sehnsucht aus einer anderen Welt verwandelt sich in einen weißen Lichtschimmer, der wirbelnd durch deine Seele fließt."
  },
  AvgDialog_120313_Content_15 = {
    Text = "<Shake:<color=#DEDEDE>Endlich... dich... gefunden.</color>>"
  },
  AvgDialog_120313_Content_16 = {
    Text = "Eure Köpfe liegen aneinander, ihre beiden Hände umarmen liebevoll deinen Rücken, ihre Stimme zittert vor Freude und Tränen."
  },
  AvgDialog_120313_Content_17 = {
    Text = "Alle Erschöpfung, Einsamkeit und Schmerz verschwinden in diesem Moment, und du weißt, dass deine Seele an ihren wahren Ort zurückgekehrt ist."
  },
  AvgDialog_120313_Content_18 = {
    Text = "Es ist gefährlich, zwischen den Dimensionen zu reisen, hast du dich verletzt?"
  },
  AvgDialog_120313_Content_19 = {
    Text = "Du erinnerst dich an etwas und siehst dir die Seele an, die lange gereist ist, und siehst nur ihre etwas abgemagerte Gestalt. Ramona schüttelte den Kopf und streichelte sanft dein Gesicht."
  },
  AvgDialog_120313_Content_2 = {
    Text = "Erscheinen, Zerstörung, Wiedergeburt... Widerstand, Kampf, Standhaftigkeit..."
  },
  AvgDialog_120313_Content_20 = {
    Text = "Und du? Du warst so lange allein in einer fremden Welt, es muss sehr hart für dich gewesen sein."
  },
  AvgDialog_120313_Content_21 = {
    Text = "Dein Nasenspitze brannte, du schütteltest ebenfalls den Kopf, und in den Blicken, die sich gegenüberstanden, und den Tränen, die in deinen Augen hingen und nicht fielen, lachtet ihr beide gleichzeitig."
  },
  AvgDialog_120313_Content_22 = {
    Text = "Warum lachst du, wie ein Dummkopf."
  },
  AvgDialog_120313_Content_23 = {
    Text = "Lachst du nicht auch...?"
  },
  AvgDialog_120313_Content_24 = {
    Text = "In unermesslichem Glück konntest du nicht widerstehen, ihre Hand zu ergreifen und sofort den Rückweg antreten zu wollen."
  },
  AvgDialog_120313_Content_25 = {Text = "!!!"},
  AvgDialog_120313_Content_26 = {
    Text = "Plötzlich siehst du, wie sich ihre Pupillen plötzlich verengen, und im nächsten Moment stürzt sie sich auf dich und stößt dich heftig zur Seite."
  },
  AvgDialog_120313_Content_27 = {
    Text = "In dem Moment, als du hinausgeschleudert wirst, siehst du an dem Ort, der ursprünglich hinter dir war, dass in einem neuen Dimensionsriss ein weiteres Auge sich dreht und öffnet und Ramona anblickt, die an Ort und Stelle bleibt."
  },
  AvgDialog_120313_Content_28 = {
    Text = "In einem Augenblick wurde sie von schwarzem Schleim verschlungen."
  },
  AvgDialog_120313_Content_29 = {
    Text = "<Shake:<Big:Nein!!!>>"
  },
  AvgDialog_120313_Content_3 = {
    Text = "Unter dem Druck des obersten Willens ist alles so vertraut."
  },
  AvgDialog_120313_Content_4 = {
    Text = "Die riesigen, blassen Augen in der anderen Dimension verschwinden nacheinander mit einem lauten Knall, und dein Geist neigt sich allmählich dem Ende entgegen. Das Einzige, was dich noch stützt, ist die blutrote Rose in deiner Hand."
  },
  AvgDialog_120313_Content_5 = {
    Text = "Huh... Ich darf nicht umfallen, sie warten noch auf mich..."
  },
  AvgDialog_120313_Content_6 = {
    Text = "In der Benommenheit beginnt dein Herz plötzlich heftig zu schlagen, und du drehst dich mit diesem Gefühl um."
  },
  AvgDialog_120313_Content_7 = {
    Text = "Als ob ein Meteor vorbeifliegt, und wie gefrorene Kristalle, erstreckt sich ein lichtstrahlartiger Tunnel, begleitet von seltsamen und ätherischen Klängen."
  },
  AvgDialog_120313_Content_8 = {
    Text = "Ein Klang, der in der Erinnerung tausendfach widerhallt, überwindet den fernen dimensionalen Raum hinter dir und ertönt in deinem Kopf durch die Verbindung deiner geistigen Antennen."
  },
  AvgDialog_120313_Content_9 = {
    Text = "<Yellow:%player%>!!!"
  },
  AvgDialog_121232_Content_1 = {
    Text = "Das Licht der Heimat blitzt vor meinen Augen, Herr Goliath, nun überlasse ich es Ihnen..."
  },
  AvgDialog_121232_Content_2 = {
    Text = "Die heranströmende göttliche Kraft... hat einige Ähnlichkeiten mit dieser verrückten Frau."
  },
  AvgDialog_121232_Content_3 = {
    Text = "Gut, der kleine Kerl dort drüben, mach dich bereit, die Macht der Philistin zu erleben, die über dem Segen steht!"
  },
  AvgDialog_121369_Content_1 = {
    Text = "Im leeren Saal hallen nur deine und Murphys Schritte wider."
  },
  AvgDialog_121369_Content_10 = {
    Text = "Bevor du die Situation klären kannst, wickeln sich die kühlen Tentakel um dein Unterschenkel und die Muskelkraft drückt dich nach unten auf die Knie."
  },
  AvgDialog_121369_Content_11 = {
    Text = "Du versuchst, Widerstand zu leisten, aber das Lähmungstoxin dringt in die Nerven ein und lässt dich kraftlos."
  },
  AvgDialog_121369_Content_12 = {
    Text = "Murphy, was machst du?!"
  },
  AvgDialog_121369_Content_13 = {
    Text = "Ich weiß nicht warum, aber ich fühle mich sehr wütend."
  },
  AvgDialog_121369_Content_14 = {
    Text = "In meinem Herzen brennt ein Feuer, und wenn ich dich sehe, brennt es noch intensiver."
  },
  AvgDialog_121369_Content_15 = {
    Text = "(Ruhig, ruhig. Man darf nichts tun, was die Autorität der Göttlichen Mutter gefährdet.)"
  },
  AvgDialog_121369_Content_16 = {
    Text = "Also... was soll ich hier eigentlich tun?"
  },
  AvgDialog_121369_Content_17 = {
    Text = "Knie nieder, ohne zu fragen!"
  },
  AvgDialog_121369_Content_18 = {
    Text = "Murphys Tonfall klang wütend, und der Tentakel klopfte nervös mit einem Platschen an deinem Bein. Es sieht so aus, als müsstest du dich selbst auf dich verlassen."
  },
  AvgDialog_121369_Content_19 = {
    Text = "Du kämpfst gewaltsam gegen die Lähmung des Toxins an und hebst den Kopf, berührst ihre geröteten Wangen."
  },
  AvgDialog_121369_Content_2 = {
    Text = "Seit vorhin hast du nichts gesagt."
  },
  AvgDialog_121369_Content_20 = {
    Text = "Murphy, bist du... von der Stärke des Heiligen Flusses gestört worden?"
  },
  AvgDialog_121369_Content_21 = {
    Text = "Frechheit! Ich bin die Mutter der Götter, wie könnte ich von solch dummen Einflüssen betroffen sein..."
  },
  AvgDialog_121369_Content_22 = {
    Text = "Die Tentakel des Blau-Rings kriechen deinen Rücken hinauf und hinterlassen ein Gefühl von Kribbeln und Juckreiz."
  },
  AvgDialog_121369_Content_23 = {
    Text = "Bleib bis zum Morgengrauen gut hier."
  },
  AvgDialog_121369_Content_24 = {
    Text = "Beweg dich nicht!"
  },
  AvgDialog_121369_Content_25 = {
    Text = "Doch du spürst, dass die Tentakel, die dich fesseln, sich ein wenig lockern, als ob Wolken dich tragen, aber wenn du versuchst, dich zu befreien, lassen sie dich keinen Millimeter bewegen."
  },
  AvgDialog_121369_Content_26 = {
    Text = "Sei dankbar, du wirst die Ehre erhalten, mit der Göttlichen Mutter die Morgendämmerung zu begrüßen."
  },
  AvgDialog_121369_Content_27 = {
    Text = "Als Gegenleistung..."
  },
  AvgDialog_121369_Content_28 = {
    Text = "Ihr Atemhauch verweilt in deinem Ohr. Dann ist da ein sanfter, weicher Kuss, der auf deiner Stirn landet."
  },
  AvgDialog_121369_Content_29 = {
    Text = "Du wirst auch die Gnade der Göttlichen Mutter erhalten."
  },
  AvgDialog_121369_Content_3 = {
    Text = "Was ist passiert, Murphy?"
  },
  AvgDialog_121369_Content_4 = {
    Text = "Murphy antwortete nicht, sondern ging direkt zur Spitze der Treppe, dem Ort des Thrones."
  },
  AvgDialog_121369_Content_5 = {
    Text = "Du folgst ihr Schritt für Schritt, bis sie schließlich auf dem Thron Platz nimmt und dich mit einem leicht verärgerten Blick anstarrt."
  },
  AvgDialog_121369_Content_6 = {
    Text = "Wer hat dir erlaubt, an meiner Seite zu stehen? Senk dich, du darfst mich nicht von oben herab ansehen."
  },
  AvgDialog_121369_Content_7 = {
    Text = "Du bist ratlos, trittst aber trotzdem zwei Schritte zurück, und dein Blick ist auf gleicher Höhe mit dem Mädchen auf dem Thron."
  },
  AvgDialog_121369_Content_8 = {Text = "Knie."},
  AvgDialog_121369_Content_9 = {Text = "Ha?"},
  AvgDialog_121741_Content_1 = {
    Text = "Groß, verfallen, nichtig... die absurde Fantasie erhält die Illusion über dem “Schleier“..."
  },
  AvgDialog_121741_Content_2 = {
    Text = "In Sucht nach dem “Paradies“ bin ich so dumm und lächerlich..."
  },
  AvgDialog_121741_Content_3 = {
    Text = "%player%, hilf mir, diesen Traum endgültig zu beenden."
  },
  AvgDialog_121741_Content_4 = {
    Text = "Hilf mir, mein Schicksal zurückzuerlangen..."
  },
  AvgDialog_121742_Content_1 = {
    Text = "Die Ketten zitterten, während das Monster hinter dem Vorhang seinen Blick über das gesamte Schiff schweifen ließ und einen verzweifelten Schrei ausstieß."
  },
  AvgDialog_121742_Content_10 = {
    Text = "Leb wohl, zerbrechliches Nichtiges “Gestern“...!"
  },
  AvgDialog_121742_Content_2 = {
    Text = "Ich verstehe... ich verstehe alles... deine Zuneigung, die Dinge, die du nicht loslassen kannst..."
  },
  AvgDialog_121742_Content_3 = {
    Text = "Aber ich habe mich entschieden."
  },
  AvgDialog_121742_Content_4 = {
    Text = "Murphy blickte zu ihm zurück, nach einer Weile, als hätte sie sich entschieden, schenkte sie dir ein sanftes Lächeln."
  },
  AvgDialog_121742_Content_5 = {
    Text = "Schaut euch das an... das Herz in meiner Brust..."
  },
  AvgDialog_121742_Content_6 = {
    Text = "Selbst heute pulsiert es immer noch vor Leben."
  },
  AvgDialog_121742_Content_7 = {
    Text = "Wie bei der Lotsenzeremonie schnitt Murphy sich die Brust auf."
  },
  AvgDialog_121742_Content_8 = {
    Text = "Um hier wegzukommen, für den Tag, an dem wir uns in Misaq wiedersehen."
  },
  AvgDialog_121742_Content_9 = {
    Text = "Der geistige Blut fließt von Murphys Brust herab, feine silberne Fäden verheddern sich und versuchen hartnäckig, den Vorhang über dem Himmel zu zerreißen."
  },
  AvgDialog_121743_Content_1 = {
    Text = "Du weißt nicht, wie lange du gekämpft hast, fühlst nur, dass dein Gehirn anfängt zu schwirren und deine Arme schwer werden. Das blasse, dünne, riesige Monster schwingt jedoch unermüdlich seine gebrochenen und wiedergeborenen Arme."
  },
  AvgDialog_121743_Content_10 = {
    Text = "Wilhelms Versprechen erschien wie eine unsichtbare Barriere, die hinter ihm errichtet wurde. Das über Jahre hinweg geschmiedete Vertrauen ließ die fast erschöpfte Stärke wieder aus dem tiefsten Mark hervorsprudeln."
  },
  AvgDialog_121743_Content_11 = {
    Text = "Wir haben vereinbart, dass wir zusammen zurückkehren."
  },
  AvgDialog_121743_Content_12 = {
    Text = "Möge der Silberschlüssel unseren Weg erhellen."
  },
  AvgDialog_121743_Content_13 = {
    Text = "Möge der Silberschlüssel uns leiten"
  },
  AvgDialog_121743_Content_2 = {
    Text = "Der Schweiß läuft von deiner Stirn und verwischt deine Sicht, doch du kannst nicht einmal deine Hand heben, um ihn abzuwischen."
  },
  AvgDialog_121743_Content_3 = {
    Text = "Verdammt..."
  },
  AvgDialog_121743_Content_4 = {
    Text = "%player%, halte durch."
  },
  AvgDialog_121743_Content_5 = {
    Text = "Ein schwarz-roter Umhang flattert vor dir, während ein präziser mechanischer Arm dich vor den heftig angreifenden blassen Skelette schützt."
  },
  AvgDialog_121743_Content_6 = {
    Text = "Die langen Gliedmaßen schlagen wütend erneut zu, werden aber erneut abgeblockt, Trümmer schlagen neben euch ein und wirbeln Rauch auf."
  },
  AvgDialog_121743_Content_7 = {Text = "Wilhelm?"},
  AvgDialog_121743_Content_8 = {
    Text = "Konzentrier dich und schau ihn an.\nÜberlass mir deinen Rücken."
  },
  AvgDialog_121743_Content_9 = {
    Text = "In der neuen Welt... werde ich vorübergehend die Aufgaben deines Partners übernehmen. \n Bis zu dem Tag, an dem wir gemeinsam nach Misaq zurückkehren."
  },
  AvgDialog_121744_Content_1 = {
    Text = "Das Monster brüllte und weinte, der verhüllende Vorhang zerbrach, während sein Körper aus der Tiefe des Aequors auftauchte."
  },
  AvgDialog_121744_Content_10 = {
    Text = "Die Kraft nicht gut zu nutzen und das Schicksal in die Hände anderer zu legen, ist nicht die Art der Philistine."
  },
  AvgDialog_121744_Content_11 = {
    Text = "Der Riese schwingt seine Waffe und richtet die Spitze der riesigen Klinge auf den sich verändernden großen Fleischklumpen."
  },
  AvgDialog_121744_Content_12 = {
    Text = "Also, redet nicht mehr herum und bereitet euch auf den Kampf vor!"
  },
  AvgDialog_121744_Content_13 = {
    Text = "Nur der Gewinner hat das Recht zu überleben."
  },
  AvgDialog_121744_Content_2 = {
    Text = "Verdammtes...! Er expandiert immer noch!"
  },
  AvgDialog_121744_Content_3 = {
    Text = "Ein Blitz durchbrach den pechschwarzen Nachthimmel, und die blutrünstige Riesenklinge schnitt mit rasendem purpurschwarzem Blitzlicht heftig auf die blassen, schwachen Glieder des Vorhangs ein."
  },
  AvgDialog_121744_Content_4 = {
    Text = "...Miryam? Goliath? Warum seid ihr hier?"
  },
  AvgDialog_121744_Content_5 = {
    Text = "Die Göttliche Mutter hat ihre Entschlossenheit gefasst, und wir werden im Namen der Göttlichen Mutter diesen unnötigen “Schleier“ durchtrennen."
  },
  AvgDialog_121744_Content_6 = {Text = "Miryam..."},
  AvgDialog_121744_Content_7 = {
    Text = "Sei unbesorgt, gnädige Göttliche Mutter. Egal, was Sie in Zukunft planen, die Seefahrer sind der stabilste und festeste Grundstein hinter Ihnen."
  },
  AvgDialog_121744_Content_8 = {
    Text = "Hör auf zu quatschen, wollen wir wirklich zusehen, wie ihr beiden kleinen gegen diesen Typen ankämpft?"
  },
  AvgDialog_121744_Content_9 = {
    Text = "Eine vertraute Stimme ertönt plötzlich und unterbricht Murphys Worte. Es sind Goliath und Caecus."
  },
  AvgDialog_121745_Content_1 = {
    Text = "Das aufragende Monster hebt stolz den Kopf und “blickt“ auf euch alle hinter dem trüben Vorhang."
  },
  AvgDialog_121745_Content_10 = {
    Text = "Bitte, sei wie ich... lass dich für immer in den unendlichen Tiefen des Aequors begraben!"
  },
  AvgDialog_121745_Content_2 = {Text = "...!!!"},
  AvgDialog_121745_Content_3 = {
    Text = "Eine gewisse unsichtbare Verbindung durchdringt sie und IHN wirklich, unvermeidlich, sodass das Mädchen seine Verletzungen, sein Schluchzen und sogar seine Zweifel sieht..."
  },
  AvgDialog_121745_Content_4 = {
    Text = "Wie ein verletztes Kind, das die “Verrat“ seiner Mutter in Frage stellt."
  },
  AvgDialog_121745_Content_5 = {
    Text = "Sieh mich nicht an, befrage mich nicht... Ich habe mich entschieden. Dies ist mein letztes Mal des “Verrats“."
  },
  AvgDialog_121745_Content_6 = {
    Text = "Einst habe ich einen Wunsch an das“Paradies“geäußert, einen “Traum“, den ich in meiner Kindheit ersehnte."
  },
  AvgDialog_121745_Content_7 = {
    Text = "Ich dachte, dass mir “Macht“ “Glück“ bringen könnte, aber das ist letztendlich nur eine illusorische Traumwelt..."
  },
  AvgDialog_121745_Content_8 = {
    Text = "Murphy lächelte und wischte die Tränen aus den Augenwinkeln. Sie wischte langsam und sorgfältig, bis der letzte Tränenstrich vollständig verschwunden war. Dann hob sie den Kopf und blickte auf das riesige “Ich“."
  },
  AvgDialog_121745_Content_9 = {
    Text = "Ich brauche kein Paradies, keine Selbsttäuschung mit schönen Träumen. Ich brauche es nicht mehr."
  },
  AvgDialog_121858_Content_1 = {
    Text = "Aus seinen Füßen strömten unzählige Monster hervor, und ihr tötet sie eines nach dem anderen. \n Auf den tausenden Leichnamen tretend, erreicht ihr die Füße der riesigen Silhouette."
  },
  AvgDialog_121858_Content_10 = {
    Text = "Diesmal werde ich nicht zulassen, dass das Leben anderer für den Sieg geopfert wird."
  },
  AvgDialog_121858_Content_11 = {
    Text = "Bereit zum Kampf, der “Vorhang“, der schließlich verwelken wird!"
  },
  AvgDialog_121858_Content_2 = {
    Text = "Das ist mein Wille, der Wille des “Paradies“..."
  },
  AvgDialog_121858_Content_3 = {
    Text = "“Das Kind“ gehört nie zur “Mutter“, nach seiner Geburt hat es auch seinen eigenen “Wunsch“ entwickelt."
  },
  AvgDialog_121858_Content_4 = {
    Text = "<Red:Traum... muss... fortgesetzt werden...>"
  },
  AvgDialog_121858_Content_5 = {
    Text = "Du hast einmal gesagt, solange du den Herrscher der Träume tötest und die Macht an dich übergibst..."
  },
  AvgDialog_121858_Content_6 = {
    Text = "Ja. Hast du bereits erwacht?"
  },
  AvgDialog_121858_Content_7 = {
    Text = "Nein, sie muss so ein Opfer nicht bringen."
  },
  AvgDialog_121858_Content_8 = {
    Text = "...%player%!"
  },
  AvgDialog_121858_Content_9 = {
    Text = "Der “Kern“ des Geheimgangs, die sich zeigende “Katastrophe“, in solch einem Ausmaß kann ich mich nicht mehr erinnern, wie oft ich schon dagegen gekämpft habe."
  },
  AvgDialog_121859_Content_1 = {
    Text = "Die Kraft, die Er hinter dem Vorhang anwendet... verändert sich..."
  },
  AvgDialog_121859_Content_2 = {
    Text = "Abgeschnitten, verlassen... Er ist unzufrieden, wütend und klagend..."
  },
  AvgDialog_121859_Content_3 = {
    Text = "Sein Zorn wird sich über euch ergießen...!"
  },
  AvgDialog_121864_Content_1 = {
    Text = "Überrascht? Weil das Orakel mich ruft, jenseits des Vorhangs..."
  },
  AvgDialog_121865_Content_1 = {
    Text = "Mein Blut pulsiert, der Abgrund singt einstimmig und lädt mich ein!"
  },
  AvgDialog_121866_Content_1 = {
    Text = "Götter der Ferne, euer frommer Diener wird euch eine bescheidene Kraft darbringen..."
  },
  AvgDialog_121867_Content_1 = {
    Text = "Glücklicher Kerl, lass dich von der Stärke der Philister überzeugen!"
  },
  AvgDialog_122640_Content_1 = {
    Text = "<Shake:Boom!——>"
  },
  AvgDialog_122640_Content_2 = {
    Text = "Der wahnsinnige Blick lässt die gesamte Dimension zu zittern beginnen, der Link zwischen Ramona und dir wird durch die Auflösung verdeckt und ist nicht mehr sichtbar."
  },
  AvgDialog_122640_Content_3 = {
    Text = "Du atmest tief ein und unterdrückst gewaltsam das Gefühl der Unruhe, das durch den Wahnsinn entstanden ist."
  },
  AvgDialog_122640_Content_4 = {
    Text = "Lass diesen Wahnsinn für dich selbst...<Big:Ich werde nicht zulassen, dass dein Wahnsinn noch jemandem schadet!>"
  },
  AvgDialog_122641_Content_1 = {
    Text = "...@3!! ..."
  },
  AvgDialog_122641_Content_2 = {
    Text = "Vertrauter Druck. Vertrauter Blick. Vertrauter Schmerz, der fast dein Gehirn zerreißt."
  },
  AvgDialog_122641_Content_3 = {
    Text = "Ah... wir sehen uns wieder, Toguwaibo, der höchste Gott... Auch wenn du nicht hören kannst, muss ich dir danken."
  },
  AvgDialog_122641_Content_4 = {
    Text = "Du hast mich einmal sterben lassen, und in diesem Tod habe ich eine universelle Wahrheit erkannt..."
  },
  AvgDialog_122641_Content_5 = {
    Text = "Du umklammerst den Silberschlüssel fest und starrst in den Blick, den Sein Wille auf dich wirft — und erst später wirst du erkennen, dass du <Italic:gelächelt> hast."
  },
  AvgDialog_122641_Content_6 = {
    Text = "Du hast mir gezeigt, dass in deinem großartigen Traum nichts unveränderlich und nichts unbesiegbar ist."
  },
  AvgDialog_122641_Content_7 = {
    Text = "Um uns wiederzusehen, haben wir lange gewartet... Selbst du wirst uns nicht aufhalten!"
  },
  AvgDialog_122642_Content_1 = {
    Text = "...@2... @2... @1@3...!!"
  },
  AvgDialog_122642_Content_2 = {
    Text = "Ein starker Aufprall lässt die gesamte Dimension zu zerbrechen beginnen. Du öffnest deine rot glühenden Augen und schaust auf das Auge, das dir immer näher kommt."
  },
  AvgDialog_122642_Content_3 = {
    Text = "Dein Bewusstsein ist ebenfalls am Limit, Toguwaibo... Jetzt, schlafe weiter!"
  },
  AvgDialog_122642_Content_4 = {
    Text = "Du schöpfst deine fast erschöpfte geistige Kraft und leitest die letzte geistige Energie in den Silberschlüssel ein."
  },
  AvgDialog_122642_Content_5 = {
    Text = "Du hältst das silberne Licht wie eine Klinge in der Hand und stichst nach dem Gott vor dir——"
  },
  AvgDialog_122643_Content_1 = {
    Text = "<Big:<Shake:Ramona!!!>>"
  },
  AvgDialog_122643_Content_2 = {
    Text = "Die vertraute Gestalt wird von der Auflösung, die der Blick mit sich bringt, verschlungen, während die alten, bösen Zauber in diesem Blick schwach sichtbar sind."
  },
  AvgDialog_122643_Content_3 = {
    Text = "Diese Gesänge enden hier...!"
  },
  AvgDialog_122644_Content_1 = {
    Text = "Die Welt bricht vor dir zusammen und wird neu aufgebaut, die dir Nahestehenden sterben vor deinen Augen und werden wieder lebendig. Dieser verwirrte Blick bringt das gesamte Chaos des Universums in deinen Geist."
  },
  AvgDialog_122644_Content_2 = {
    Text = "Chaos, Verwirrung, Verwirrung... Das, was deine Macht bringt, sind immer noch diese Dinge."
  },
  AvgDialog_122644_Content_3 = {
    Text = "Dein Blick hat mich niemals verwirrt, Toguwaibo. Früher so, heute auch."
  },
  AvgDialog_122644_Content_4 = {
    Text = "Silberlicht blitzt auf. Inmitten dieser endlosen Illusionen hast du den Weg gefunden, um dich ihm entgegenzustellen——"
  },
  AvgDialog_122645_Content_1 = {
    Text = "In einer fernen Dimension blitzt ein Lichtpunkt leicht auf."
  },
  AvgDialog_122645_Content_2 = {
    Text = "Das ist... Pollux'“Heiliges Herz“?"
  },
  AvgDialog_122645_Content_3 = {
    Text = "Ihre Suche hat auch bereits begonnen... Sie befinden sich jetzt sicherlich in Gefahr."
  },
  AvgDialog_122645_Content_4 = {
    Text = "Ich erinnere mich noch an die Angst, die ich hatte, als ich dir zum ersten Mal gegenüberstand, Toguwaibo. Dieses Mal werde ich sie nicht lange warten lassen!"
  },
  AvgDialog_122646_Content_1 = {
    Text = "Ein stechender Schmerz durchdringt jeden Knochen und jedes Stück Fleisch in dir. Du erträgst diesen durchdringenden Schmerz und versuchst mühsam zu lächeln."
  },
  AvgDialog_122646_Content_2 = {
    Text = "Dummer Gott, du weißt nicht, dass in deinem Traum viele Schmerzen weit über den Körper hinausgehen..."
  },
  AvgDialog_122646_Content_3 = {
    Text = "So einen Schmerz werde ich nicht noch einmal zulassen!"
  },
  AvgDialog_122694_Content_1 = {
    Text = "Die Tür auf halbem Weg des Korridors ist bereits mit weißem Frost bedeckt, und der Frost scheint sich auszubreiten."
  },
  AvgDialog_122694_Content_10 = {
    Text = "Bitte, Schutzherr, halt mich einfach fest – nur ein bisschen, nur ein wenig Wärme ist alles, was ich brauche~ Die Fee wird deine Güte für immer in Erinnerung behalten."
  },
  AvgDialog_122694_Content_11 = {
    Text = "Es ist das erste Mal, dass du diese kleine Schwindlerin mit einem solchen Ausdruck siehst, doch eine anhaltende Vorsicht hält dich an Ort und Stelle, deinen Atem als weißen Nebel aushauchend, während du nur deine Glieder bewegst, um warm zu bleiben."
  },
  AvgDialog_122694_Content_12 = {
    Text = "Ich habe das Verwaltungsbüro bereits benachrichtigt. Sie werden bald hier sein, um zu helfen. Bleib einfach, wo du bist, beweg dich nicht, tu nichts."
  },
  AvgDialog_122694_Content_13 = {
    Text = "Aber mir geht es gerade so schrecklich... Die Kraft dieses Flusses hat mich zurück an diesen bleichen... eiskalten... furchtbaren Ort gezogen..."
  },
  AvgDialog_122694_Content_14 = {
    Text = "Ohne Vorwarnung fallen Caraboos Tränen geradewegs herab, als hätte sie wirklich gerade etwas Entsetzliches erlebt."
  },
  AvgDialog_122694_Content_15 = {
    Text = "Ich glaube nicht, dass ich bis zur Hilfe durchhalte, Schutzherr. Es tut mir leid... dass ich dich früher immer angelogen habe..."
  },
  AvgDialog_122694_Content_16 = {
    Text = "Eiskristalle breiten sich mit ihr als Mittelpunkt aus, und sie wirkt hilflos, zerbrechlich, die Augen gerötet, während sie dich anstarrt – schwankend, als könnte sie jeden Moment zusammenbrechen."
  },
  AvgDialog_122694_Content_17 = {Text = "Caraboo!"},
  AvgDialog_122694_Content_18 = {
    Text = "Im Augenblick bevor sie zu Boden fällt, stürzt du vor und fängst sie doch noch auf – und bereust es im nächsten Moment sofort."
  },
  AvgDialog_122694_Content_19 = {
    Text = "Diese eiskalten Arme schlingen sich mit der knochenlosen Leichtigkeit eines wirbellosen Wesens um dich, und ein mit Schneekristallen bestäubter Atem ergießt sich in die Mulde deines Halses und die Kurve deines Ohres."
  },
  AvgDialog_122694_Content_2 = {
    Text = "Du stählst dich und kämpfst gegen eine so heftige Kälte an, dass deine klappernden Zähne dir fast die Zunge durchbeißen könnten, während du die Tür zu Caraboos Schlafsaal aufstößt."
  },
  AvgDialog_122694_Content_20 = {
    Text = "Hihihi~ Ach herrje, ich wusste es. %player% ist wirklich so ein Weichherz."
  },
  AvgDialog_122694_Content_21 = {
    Text = "Hinter ihr hüllt dich etwas noch Weicheres und Kälteres träge ein und zieht dich hinab durch Schicht um Schicht tiefen Schnees."
  },
  AvgDialog_122694_Content_22 = {
    Text = "Du strampelst, gedämpfte Laute bleiben dir im Hals stecken, und kurz bevor du vollständig das Bewusstsein verlierst, hörst du dieses verschmitzte kleine Lachen."
  },
  AvgDialog_122694_Content_23 = {
    Text = "Alles gut. Deine Fee wird mit ihrem allerliebsten kleinen Lämmchen ganz, ganz sanft sein~"
  },
  AvgDialog_122694_Content_3 = {
    Text = "Caraboo, was hast du da ge—zss, hier drin ist es eiskalt."
  },
  AvgDialog_122694_Content_4 = {
    Text = "Doch die flinke, schelmische kleine Gestalt springt nicht auf irgendeine blendende Art hervor, um ihren neuesten Streich zur Schau zu stellen, wie sie es immer tut."
  },
  AvgDialog_122694_Content_5 = {
    Text = "Eine ungewöhnliche Röte liegt auf ihrem Gesicht. Sie wirkt, nun ja, fast... bemitleidenswert."
  },
  AvgDialog_122694_Content_6 = {
    Text = "Schutzherr, was soll ich tun~? Mir ist wirklich nicht gut. Mein Körper fühlt sich seltsam an, mein Kopf auch."
  },
  AvgDialog_122694_Content_7 = {
    Text = "Mir ist so kalt. Fast erfriere ich hier auf der Stelle."
  },
  AvgDialog_122694_Content_8 = {
    Text = "Und mir ist auch so heiß – so heiß, dass mir die Beine weich werden, ich kann keinen einzigen Schritt machen."
  },
  AvgDialog_122694_Content_9 = {
    Text = "Sie beißt sich auf die Unterlippe und streckt dir, die Augen voller Tränen, die Arme entgegen – die Haltung eines Kindes, das darum bettelt, gehalten zu werden."
  },
  AvgDialog_122696_Content_1 = {
    Text = "Im leeren Saal hallen nur deine und Murphys Schritte wider."
  },
  AvgDialog_122697_Content_1 = {
    Text = "Heute verdunkelt sich der Himmel schneller als gewöhnlich, und es ist düster, was eindeutig darauf hindeutet, dass es regnen wird."
  },
  AvgDialog_122697_Content_10 = {
    Text = "Mouchette hob ihren Kopf, ihr Gesicht war von einem abnormalen Röte überzogen, und sie zeigte ein Lächeln, das Verwirrung und Leidenschaft vermischte."
  },
  AvgDialog_122697_Content_11 = {
    Text = "Kämpf mit mir, jetzt sofort, unmittelbar!"
  },
  AvgDialog_122697_Content_13 = {
    Text = "Bevor du ein Wort ausstoßen kannst, schwingt ihre Axt. Sie streift mit erschreckender Präzision deine Wange und hinterlässt nur ein Pfeifen kalter Luft."
  },
  AvgDialog_122697_Content_14 = {
    Text = "Der Wind dringt ohne Erlaubnis in deinen Kragen ein, strömt in deine Brust und lässt deinen Körper instinktiv eine Gänsehaut bekommen."
  },
  AvgDialog_122697_Content_15 = {
    Text = "Warum hat es wegen einer Meinungsverschiedenheit zu einem Streit eskaliert!?"
  },
  AvgDialog_122697_Content_16 = {
    Text = "Deine Frage wurde von der Axt und ihrem Besitzer ignoriert."
  },
  AvgDialog_122697_Content_17 = {
    Text = "<Shake:Mouchette?>"
  },
  AvgDialog_122697_Content_18 = {
    Text = "Mouchette!?"
  },
  AvgDialog_122697_Content_19 = {
    Text = "Unter deinem ständigen Fragen hörte die Axt schließlich auf. Sie drückte gegen deine Schulter und war tief in die Wand eingegraben."
  },
  AvgDialog_122697_Content_2 = {
    Text = "Um zu vermeiden, dass du durchnässt wirst, bist du hastig in Richtung des Wohnheims gerannt, aber eine Gestalt blockierte deinen Weg."
  },
  AvgDialog_122697_Content_20 = {
    Text = "Und der Meister der Axt steht direkt vor dir, mit gerötetem Gesicht, die Fäuste fest geballt, und packt gewaltsam deinen Kragen."
  },
  AvgDialog_122697_Content_21 = {
    Text = "<Shake:Halt den Mund... Es tut weh... Ich leide... Nur ein Kampf wird es aufhören lassen...>"
  },
  AvgDialog_122697_Content_22 = {
    Text = "Die Finger, die deinen Kragen packen, üben weiterhin Druck aus, wobei sie von fleischfarben zu blass wechseln, was die Sturheit und den Unwillen des Besitzers symbolisiert, nachzugeben."
  },
  AvgDialog_122697_Content_23 = {
    Text = "Ich hasse es, wenn andere ihre Ideen anderen aufzwingen..."
  },
  AvgDialog_122697_Content_24 = {
    Text = "Es ist nur der Heilige Fluss, und du denkst, er kann mich beeinflussen? <Shake: Du unterschätzt mich...>"
  },
  AvgDialog_122697_Content_25 = {
    Text = "Mouchette atmete kräftig aus, während sie sprach, und versuchte, den Einfluss des Heiligen Flusses auf sich zu beruhigen, aber du konntest die aufwallende Hitze in ihr spüren, das umherirrende Verlangen und den kämpfenden Konflikt."
  },
  AvgDialog_122697_Content_26 = {
    Text = "Als du Mouchettes Emotionen bemerkst, kannst du nicht anders, als zu seufzen, nimmst ihre Hand und führst das Mädchen dazu, den Axtgriff erneut zu umklammern."
  },
  AvgDialog_122697_Content_27 = {
    Text = "<Shake:Was machst du?>"
  },
  AvgDialog_122697_Content_28 = {
    Text = "Willst du nicht kämpfen? Dann lass uns kämpfen."
  },
  AvgDialog_122697_Content_29 = {
    Text = "Egal, wie du kämpfen möchtest, egal wie lange du kämpfen möchtest, ich werde bis zum Ende an deiner Seite stehen."
  },
  AvgDialog_122697_Content_3 = {
    Text = "Mouchette? Ist etwas nicht in Ordnung?"
  },
  AvgDialog_122697_Content_30 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_122697_Content_31 = {
    Text = "Die Augen des Mädchens weiten sich plötzlich, als sie dich überrascht ansieht."
  },
  AvgDialog_122697_Content_32 = {
    Text = "In diesem Moment fiel der lange geplante Regen endlich, mit Tropfen, die auf Mouchettes Gesicht landeten, an ihrem Kinn hinunterrutschten und in deinen Kragen verschwanden, während sie über deine Brust floss."
  },
  AvgDialog_122697_Content_33 = {
    Text = "Dann kamen weitere Regentropfen, die wild auf den Boden prasselten, gegen deine und die Wangen des Mädchens schlugen und ein Gefühl von Juckreiz brachten."
  },
  AvgDialog_122697_Content_34 = {
    Text = "<Shake:Hahaha! Das ist die Antwort, die ich wollte.>"
  },
  AvgDialog_122697_Content_35 = {
    Text = "Die Dinge fangen an, interessant zu werden, nicht wahr?"
  },
  AvgDialog_122697_Content_36 = {
    Text = "Mouchette griff den Axtgriff und zog die Axt von der Wand zurück, schwang sie jedoch nicht erneut; stattdessen sah sie dich an, starrte dich direkt an."
  },
  AvgDialog_122697_Content_37 = {
    Text = "Normalerweise kämpfe ich nicht unbewaffnet gegen andere, aber manchmal muss man neue Dinge ausprobieren, oder?"
  },
  AvgDialog_122697_Content_38 = {
    Text = "Das Leben ist so lang, und einige interessante Dinge sollten persönlich und schrittweise erlebt werden."
  },
  AvgDialog_122697_Content_39 = {
    Text = "Mouchette sagte, während sie langsam auf dich zuging. Und die Axt lehnte ruhig gegen die Wand und empfing die feuchte Taufe der Welt."
  },
  AvgDialog_122697_Content_4 = {
    Text = "Sie hält den Kopf gesenkt, schweigt. Du kannst nur ihren inneren Aufruhr daran spüren, wie ihre Knöchel weiß geworden sind, während sie die Axt mit zitternder Kraft umklammert."
  },
  AvgDialog_122697_Content_5 = {
    Text = "<Shake:Mouchette!?>"
  },
  AvgDialog_122697_Content_6 = {
    Text = "Schließlich sprach das Mädchen, aber ihre Stimme trug einen Hauch von Zögern und Unsicherheit."
  },
  AvgDialog_122697_Content_7 = {
    Text = "%player%, ich... ich brauche deine Hilfe..."
  },
  AvgDialog_122697_Content_8 = {
    Text = "Brauchst du Hilfe? Kein Problem. Was brauchst du?"
  },
  AvgDialog_122697_Content_9 = {
    Text = "<Shake:Ich brauche dich...>"
  },
  AvgDialog_122700_Content_1 = {
    Text = "Willkommen in meinem Theater. Du bist genau rechtzeitig, {Male=Herr, Female=Fräulein} Schutzherr."
  },
  AvgDialog_122700_Content_10 = {
    Text = "Fortpflanzen... wiedergeboren... sag mir nicht, du bist auch—"
  },
  AvgDialog_122700_Content_11 = {
    Text = "Ah, eigentlich... mir fällt gerade ein, dass Professor Dors Aufgabe noch nicht fertig ist... Ich denke, ich sollte besser—"
  },
  AvgDialog_122700_Content_12 = {
    Text = "Du drehst dich um und möchtest gehen, doch deine Schritte führen dich unwillkürlich weiter nach vorne, bis du vor Arachne stehst."
  },
  AvgDialog_122700_Content_13 = {
    Text = "Ja, ich stehe unter dem Einfluss des Flusses... und du stehst unter dem Sog des Schicksals. Heute Nacht ist eine Nacht, die uns beiden allein gehört."
  },
  AvgDialog_122700_Content_14 = {
    Text = "Ein Stück, das schon immer dazu bestimmt war, aufgeführt zu werden — und endlich ist die vorbestimmte Hauptrolle eingetroffen."
  },
  AvgDialog_122700_Content_15 = {
    Text = "Der Atem der Arachne hat bereits dein Ohr berührt, warm und leise."
  },
  AvgDialog_122700_Content_16 = {
    Text = "Ihr Lächeln bleibt so gelassen wie eh und je. Doch tief in diesen unergründlichen Augen brennt etwas: eine Flamme, die du noch nie zuvor gesehen hast, als könnte sie alles verzehren, was sie berührt."
  },
  AvgDialog_122700_Content_17 = {
    Text = "Nein, nein, das geht nicht... Arachne... ich..."
  },
  AvgDialog_122700_Content_18 = {
    Text = "Du brauchst nicht zu fliehen, %player%. Das Netz hat jede Möglichkeit an ihren Platz gewoben. Es wird uns beide durch die heutige Aufführung geleiten."
  },
  AvgDialog_122700_Content_19 = {
    Text = "Ein unsichtbares Netz schließt sich um dich, entzieht dir jedes letzte Quäntchen Kraft und verschlingt jeden Impuls zum Widerstand."
  },
  AvgDialog_122700_Content_2 = {
    Text = "Du schiebst die schweren Türen des Theaters auf, das Mondlicht fällt schräg durch die hohen Fenster und der kühle Nachttau zusammen mit der sanften Stimme von Arachne im Theater lässt dich plötzlich aufschrecken."
  },
  AvgDialog_122700_Content_20 = {
    Text = "Die Fäden spannen sich. Du blickst in das Gesicht, das deinem so nah ist, und dein Herz macht einen Satz, dein Atem wird schneller."
  },
  AvgDialog_122700_Content_21 = {
    Text = "Das Schicksal bestimmt, dass du nie fliehen wolltest. Du hast dir dies gewünscht: <Italic:Du> wolltest hierherkommen, wolltest diese Aufführung bis zum Ende sehen, ohne anderes Publikum als euch beide."
  },
  AvgDialog_122700_Content_22 = {
    Text = "Du... du hast mein Schicksal umgeschrieben?!"
  },
  AvgDialog_122700_Content_23 = {
    Text = "Es gibt noch nie etwas umgeschrieben worden, {Male=Herr, Female=Fräulein} Schutzherr. Ich habe dein Schicksal nur auf den Pfad zurückgeführt, den es schon immer gehen sollte."
  },
  AvgDialog_122700_Content_24 = {
    Text = "Arachne... du... du kannst das Schicksal vollkommen ändern und den Einfluss des Heiligen Flusses vermeiden... warum tust du das nicht?"
  },
  AvgDialog_122700_Content_25 = {
    Text = "Warum sollte ich?"
  },
  AvgDialog_122700_Content_26 = {
    Text = "Für eine Spielerin, die das Skript längst auswendig kennt, ist das Unerwartete das seltenste Geschenk, das das Schicksal je zu geben für gut befunden hat..."
  },
  AvgDialog_122700_Content_27 = {
    Text = "Die sanften Worte von Arachne flüstern in deinem Ohr. Sie ist nicht mehr friedlich und fern, ihr Atem zittert leise, ihr Lächeln ist zum Greifen nah."
  },
  AvgDialog_122700_Content_28 = {
    Text = "Und wie es sich trifft... stelle ich fest, dass ich nichts gegen ein Ende einzuwenden habe, bei dem niemand verletzt wird."
  },
  AvgDialog_122700_Content_29 = {
    Text = "Das Netz aus Fäden ist kalt, geschmeidig, schmiegt sich so eng an, dass kein Raum zum Atmen bleibt, zieht sich enger, drückt durch den Stoff, gegen die Haut."
  },
  AvgDialog_122700_Content_3 = {
    Text = "Warte! Ich sollte in meinem Schlafsaal schlafen. Wie bin ich hierher gekommen... warst du das?"
  },
  AvgDialog_122700_Content_30 = {
    Text = "Dann schließen sich Cheliceren um dich, und kalte Pedipalpen teilen deine Lippen, versiegeln jeden Widerstand, der noch keine Worte gefunden hatte."
  },
  AvgDialog_122700_Content_31 = {
    Text = "Die Fäden beginnen, deine Glieder zu führen. Sanft und ohne Widerrede."
  },
  AvgDialog_122700_Content_32 = {
    Text = "Mach dir keine Sorgen, Schutzherr. Es gibt keinen Grund, sich dem zu widersetzen, was das Schicksal dir zugedacht hat."
  },
  AvgDialog_122700_Content_33 = {
    Text = "Denn... das ist es, was auch du willst, nicht wahr?"
  },
  AvgDialog_122700_Content_34 = {
    Text = "... ja, Arachne... das ist... was ich will..."
  },
  AvgDialog_122700_Content_35 = {
    Text = "Natürlich. Du warst nie eine Marionette des Schicksals. Du bist der Schutzherr von Misaq, derjenige, der sein Schicksal in den eigenen Händen hält."
  },
  AvgDialog_122700_Content_36 = {
    Text = "Das ist genau das, was du willst. Es ist das Schicksal, das sich deinem Willen beugt. Es ist dein Körper, der deinem eigenen Ruf folgt."
  },
  AvgDialog_122700_Content_37 = {
    Text = "Die Fäden erzittern, wie das Schicksal, das einen Bogen über Saiten zieht. Du streckst die Hand aus, fährst die Spinnenbeine nach, die sanft in der Luft schwanken, fährst die Hände nach, die nie aufgehört haben, die Spindel zu drehen, fährst die Linien dieses sanften Gesichts nach."
  },
  AvgDialog_122700_Content_38 = {
    Text = "Dieses vertraute Gesicht. Das Mitgefühl, das es stets trägt, die Stille, die es nie verlässt. Und jetzt, ganz zaghaft, etwas anderes — eine Wärme, die an die Oberfläche steigt, ungeschützt, die du noch nie zuvor gesehen hast."
  },
  AvgDialog_122700_Content_39 = {
    Text = "Lasst uns gemeinsam willkommen heißen, was das Schicksal uns gebracht hat... {Male=Herr, Female=Fräulein} Schutzherr."
  },
  AvgDialog_122700_Content_4 = {
    Text = "Du bist deinem eigenen Willen gefolgt. Du <Italic:wolltest> hierherkommen. Hattest du das vergessen?"
  },
  AvgDialog_122700_Content_40 = {
    Text = "Zwei Schicksalsfäden winden sich umeinander, ziehen, geben nach, ohne Unterlass. Das Zittern breitet sich wellenförmig entlang des unsichtbaren Netzes aus und löst sich auf in Richtung eines grenzenlosen, unerreichbaren Randes."
  },
  AvgDialog_122700_Content_41 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_122700_Content_5 = {
    Text = "Sie lächelt dich an. Ein Druck, wie das Gewicht des Schicksals selbst, schließt sich von allen Seiten um dich."
  },
  AvgDialog_122700_Content_6 = {
    Text = "Die Welt hat das Schicksal stets als unentrinnbare Fessel betrachtet, als Ursprung all ihres Leids."
  },
  AvgDialog_122700_Content_7 = {
    Text = "Aber du und ich, die wir die Fäden des Schicksals mit unseren eigenen Händen berührt haben, wissen es besser — es ist nur das, was wir selbst daraus zu machen gewählt haben."
  },
  AvgDialog_122700_Content_8 = {
    Text = "Sich fortpflanzen, damit wir zerstört werden können. Zerstört werden, damit wir wiedergeboren werden können."
  },
  AvgDialog_122700_Content_9 = {
    Text = "Immer und immer wieder, ohne Ende... Das ist alles, was das Schicksal ist, nicht wahr?"
  },
  AvgDialog_122780_Content_1 = {
    Text = "Nachricht aus der Ferne"
  },
  AvgDialog_122780_Content_2 = {
    Text = "Das ist ein Testdokument"
  },
  AvgDialog_122780_Content_3 = {
    Text = "Das ist ein Testdokument"
  },
  AvgDialog_122780_Content_4 = {
    Text = "Dies ist ein Testdokument"
  },
  AvgDialog_122780_Content_5 = {
    Text = "Dies ist ein Testdokument"
  },
  AvgDialog_122780_Content_6 = {
    Text = "Das ist ein Testdokument"
  },
  AvgDialog_122780_Content_7 = {
    Text = "Abschlussausdruck"
  },
  AvgDialog_123116_Content_1 = {
    Text = "Das verlorene Lamm"
  },
  AvgDialog_123116_Content_10 = {
    Text = "Aber jeder Priester, der in Hawick ankam – John, James, Anderson – hat innerhalb kurzer Zeit den Kontakt vollständig verloren."
  },
  AvgDialog_123116_Content_11 = {
    Text = "Gute Kinder... Nach dem Kataklysmus haben sie den Lehren des Allvaters gefolgt und die Initiative ergriffen, zu verschiedenen Pfarreien zu gehen, um das Evangelium des Allvaters zu verbreiten."
  },
  AvgDialog_123116_Content_12 = {
    Text = "Selbst in einer großen Stadt wie London haben es gewöhnliche Menschen oft schwer, sich nach einer Katastrophe um sich selbst zu kümmern, und die Situation in Hawick wird nur schlimmer sein. Warum tun sie das—"
  },
  AvgDialog_123116_Content_13 = {
    Text = "So wie du es für diese Welt und die vergangenen Welten getan hast, blasser Bote."
  },
  AvgDialog_123116_Content_14 = {
    Text = "Salvador faltete die Hände zusammen, sein Gesichtsausdruck war andächtig und voller Mitgefühl, während er betete."
  },
  AvgDialog_123116_Content_15 = {
    Text = "Denn unsere Brüder und Schwestern leiden."
  },
  AvgDialog_123116_Content_16 = {
    Text = "Das Leiden von diesem Land zu beseitigen, ist die Pflicht der Botschafter des Allvaters; sie können andere nicht in Verzweiflung zurücklassen, aufgrund der Weite des Weges."
  },
  AvgDialog_123116_Content_17 = {
    Text = "...Ich sehe."
  },
  AvgDialog_123116_Content_18 = {
    Text = [[
Vater Salvador, ich werde dir helfen, sie gemeinsam zu finden. 
 Ob Leben oder Tod.]]
  },
  AvgDialog_123116_Content_19 = {
    Text = "In diesem Moment"
  },
  AvgDialog_123116_Content_2 = {
    Text = "Howick, eine abgelegene Stadt am Rande von London"
  },
  AvgDialog_123116_Content_20 = {
    Text = "Salvador, da scheint ein Licht vor uns zu sein..."
  },
  AvgDialog_123116_Content_21 = {
    Text = "Deine Stimme verstummt abrupt aufgrund einer unerwarteten Entdeckung—ein grobes Käfig erscheint plötzlich im leeren Höhle."
  },
  AvgDialog_123116_Content_22 = {
    Text = "Laut visueller Inspektion sind mindestens ein Dutzend Menschen im Käfig eingesperrt, jeder sieht hager aus, mehrere haben ein geschwollenes Gesicht und Verletzungen am ganzen Körper."
  },
  AvgDialog_123116_Content_23 = {
    Text = "<Shake:Henry... ist tot? Sie haben Henry erschossen, Henry totgeschossen...!>"
  },
  AvgDialog_123116_Content_24 = {
    Text = "Die Frau hält sich den Kopf, murmelt vor sich hin, ihr wilder Blick und intensives Zittern verraten ihre Instabilität."
  },
  AvgDialog_123116_Content_25 = {
    Text = "Plötzlich hebt sie den Kopf und bemerkt euch alle in der Nähe."
  },
  AvgDialog_123116_Content_26 = {
    Text = "<Shake:Nein, sie kommen, schnell, bring uns hier weg!>"
  },
  AvgDialog_123116_Content_27 = {
    Text = "Ihre Bewegung zog mehr Aufmerksamkeit auf sich, und ein Mann im Käfig rannte plötzlich auf die Gitterstäbe zu und griff nach deinem Arm."
  },
  AvgDialog_123116_Content_28 = {
    Text = "Hilf mir! Ich will kein Menschenopfer werden, ich will nicht geopfert werden..."
  },
  AvgDialog_123116_Content_29 = {
    Text = "Ahhhhh—— bringt uns hier weg!"
  },
  AvgDialog_123116_Content_3 = {
    Text = "Wenn die Informationen von „Puppe“ korrekt sind, sollten sie genau hier sein."
  },
  AvgDialog_123116_Content_30 = {
    Text = "Alle*schweigen*halt den Mund!"
  },
  AvgDialog_123116_Content_31 = {
    Text = "Ein lautes Gebrüll unterbrach die Schreie der Opfer, und die Gefangenen schienen außergewöhnlich vor dem Besitzer des Gebrülls Angst zu haben, aus ihren Sinnen heraus erschrocken."
  },
  AvgDialog_123116_Content_32 = {
    Text = "Das Opferritual hat noch nicht begonnen, und ihr Schweinegezücht drängt schon darauf, zu sterben!?"
  },
  AvgDialog_123116_Content_33 = {
    Text = "Eilige Schritte folgten."
  },
  AvgDialog_123116_Content_34 = {
    Text = "Es sollte der Kult sein, der diese Menschen gefangen hält, %player%, wir..."
  },
  AvgDialog_123116_Content_35 = {
    Text = "Bleib versteckt und denk später an einen Weg, sie zu retten. Sie haben Waffen, und im Chaos können wir die Sicherheit dieser Menschen nicht gewährleisten."
  },
  AvgDialog_123116_Content_36 = {
    Text = "Aber der Mann hält dich immer noch fest, mit solcher Kraft, dass es fast deinen Arm bricht."
  },
  AvgDialog_123116_Content_37 = {
    Text = "Rette uns, rette zuerst uns! Wenn du uns nicht rettest, stirb mit uns!!"
  },
  AvgDialog_123116_Content_38 = {
    Text = "Die Schritte kommen näher, und der Geisteszustand der anderen Partei kann offensichtlich keine Logik mehr begreifen."
  },
  AvgDialog_123116_Content_39 = {
    Text = "Du beißt die Zähne zusammen und schlägst ihn mit einem schnellen Schlag nieder."
  },
  AvgDialog_123116_Content_4 = {
    Text = "Ich vertraue deinem Urteil, %player%."
  },
  AvgDialog_123116_Content_40 = {Text = "Ha..."},
  AvgDialog_123116_Content_41 = {
    Text = "Ein leises Lachen hallte plötzlich aus der Ecke der Zelle."
  },
  AvgDialog_123116_Content_42 = {
    Text = "Du drehst instinctiv deinen Kopf, um zu schauen, und im Käfig sieht dich ein seltsam gekleidetes Mädchen an, ihr schwaches Lächeln steht in starkem Kontrast zur chaotischen und verrückten Umgebung in diesem Moment."
  },
  AvgDialog_123116_Content_43 = {
    Text = "Wie interessant! Im einen Moment sagt man, dass man jemanden retten will, im nächsten Moment knockt man ihn aus..."
  },
  AvgDialog_123116_Content_44 = {
    Text = "Der aktuelle Zustand der Abtrennung hat dich vorübergehend an Ort und Stelle eingefroren."
  },
  AvgDialog_123116_Content_45 = {
    Text = "Mach dir nichts aus mir, mach weiter."
  },
  AvgDialog_123116_Content_46 = {
    Text = "Beeilst du dich nicht? Die Anhänger des Sternen-Dawns werden bald ankommen."
  },
  AvgDialog_123116_Content_47 = {Text = "...?"},
  AvgDialog_123116_Content_48 = {
    Text = "Die Zeit ist kostbar, und es gibt keinen Platz für belangloses Gerede. Du hast keine Wahl, als das Mädchen zurückzulassen und dich mit Salvador im Schatten zu verstecken."
  },
  AvgDialog_123116_Content_49 = {
    Text = "Bald erschienen zwei Kultisten, die mit Schrotflinten bewaffnet waren, vor dem Käfig. Sie standen auf beiden Seiten, hoben ihre Waffen und zielten mit den Läufen in den Gefängniskäfig hinein."
  },
  AvgDialog_123116_Content_5 = {
    Text = "Möge der Allvater sie segnen und sie vor Schatten schützen, damit sie in Frieden wohnen können."
  },
  AvgDialog_123116_Content_50 = {
    Text = "Wer hat gerade all den Lärm gemacht? Kommt heraus!"
  },
  AvgDialog_123116_Content_51 = {
    Text = "Niemand antwortete. Die Gefangenen hockten entweder zitternd in den Ecken oder starrten leer, betäubt und schweigend.\nAußer diesem seltsamen Mädchen."
  },
  AvgDialog_123116_Content_52 = {
    Text = "Sie trug weiterhin ein lässiges Lächeln und betrachtete in aller Ruhe die Kultanhänger, die mit Schusswaffen bewaffnet waren."
  },
  AvgDialog_123116_Content_53 = {
    Text = "Ist dieser Kerl ein Wahnsinniger? Er ist so entspannt, selbst wenn der Tod bevorsteht."
  },
  AvgDialog_123116_Content_54 = {
    Text = "In dieser verdammten Welt, wo sind die normalen Menschen geblieben, ha! Wenn wir auch verrückt wären, wäre es vielleicht viel einfacher."
  },
  AvgDialog_123116_Content_55 = {
    Text = "Hoffentlich wird dieses Ritual erfolgreich sein. Ich habe wirklich genug von diesen seltsamen Nebeln..."
  },
  AvgDialog_123116_Content_56 = {
    Text = "Wann beginnt das Ritual, von dem ihr sprecht?"
  },
  AvgDialog_123116_Content_57 = {
    Text = "Der Kultanhänger war sichtbar verblüfft."
  },
  AvgDialog_123116_Content_58 = {
    Text = "Mit wem redest du, mit uns?"
  },
  AvgDialog_123116_Content_59 = {
    Text = "Was noch? Hör auf, Quatsch zu reden, und beantworte meine Frage."
  },
  AvgDialog_123116_Content_6 = {
    Text = "Salvador senkte andächtig den Kopf, flüsterte ein Gebet und führte dann den Weg tiefer in die Höhle."
  },
  AvgDialog_123116_Content_60 = {
    Text = "Der Kultanhänger war völlig wütend auf das Mädchen, grinste, während er seine Hand hob und die Waffe auf ihr Bein zielte."
  },
  AvgDialog_123116_Content_61 = {
    Text = "Verrückte Frau, alles, was du tun musst, ist gehorsam zu warten, um geopfert zu werden. Ich kann sehen, dass du keine Ahnung hast, was vor sich geht."
  },
  AvgDialog_123116_Content_62 = {Text = "Bang—"},
  AvgDialog_123116_Content_63 = {
    Text = "Eine unsichtbare Kraft ließ die Kugel ihr Ziel verfehlen, sie schlug in die Höhle darüber ein und entzündete eine schwache Flamme—"
  },
  AvgDialog_123116_Content_64 = {
    Text = "Du und Salvador tauchtet aus der Dunkelheit auf und startetet einen Überfall auf die Kultanhänger."
  },
  AvgDialog_123116_Content_66 = {
    Text = "Du hast deine Zeit gut genutzt, es scheint, dass du doch nicht dumm bist."
  },
  AvgDialog_123116_Content_67 = {
    Text = "Danke, dass Sie uns, gnädige Dame, von den Kultanhängern abgelenkt haben."
  },
  AvgDialog_123116_Content_68 = {
    Text = "Möge der All-Vater über dich wachen."
  },
  AvgDialog_123116_Content_69 = {
    Text = "El Salvador zog das heilige Symbol des Vaters im Himmel in die Luft. \n Du beschlagnahmtest alle Waffen der Kultisten, befahlst ihnen, vor dem Käfig zu knien, und begannst mit dem Verhör."
  },
  AvgDialog_123116_Content_7 = {
    Text = "Vor drei Tagen"
  },
  AvgDialog_123116_Content_70 = {
    Text = "Sag, wann findet das Ritual statt? Wo wird es abgehalten? Hat das Verschwinden der Priester der Lebenskirche etwas mit euch zu tun!?"
  },
  AvgDialog_123116_Content_71 = {
    Text = "Lebenskirche... Priester...?"
  },
  AvgDialog_123116_Content_72 = {
    Text = "Genau, wo sind John, James und Anderson?"
  },
  AvgDialog_123116_Content_73 = {
    Text = "Als die Kultanhänger das hörten, waren sie einen Moment lang verblüfft und brachen dann plötzlich in schallendes Lachen aus."
  },
  AvgDialog_123116_Content_74 = {
    Text = "<Shake:Wir werden uns gemäß dem Willen des Allvaters erlösen! Ja, das Serene Reich frei von Zerstreuung ist nah!>"
  },
  AvgDialog_123116_Content_75 = {
    Text = "<Shake:<Big:Es ist herabgestiegen! Ihr unglücklichen Elenden werdet hier verrotten, während die Welt zugrunde geht!>>"
  },
  AvgDialog_123116_Content_76 = {
    Text = "Also, die Zeremonie steht kurz bevor? <Small:Ich nehme an, ich muss mich beeilen.>"
  },
  AvgDialog_123116_Content_77 = {
    Text = "Beeil dich... Was bedeutet das? Weißt du etwas?"
  },
  AvgDialog_123116_Content_78 = {
    Text = "Das Mädchen antwortete nicht; sie warf dir und Salvador einen Blick zu und zeigte ein unschuldiges und brav wirkendes Lächeln.\nAus irgendeinem Grund spürtest du einen Hauch von List darin."
  },
  AvgDialog_123116_Content_79 = {
    Text = "Ach ja, ich heiße Mouchette, und was eure Namen angeht—muss ich nicht sagen, ich bin nicht interessiert."
  },
  AvgDialog_123116_Content_8 = {
    Text = "Alle Priester, die von der Chantry des Lebens nach Hawick geschickt wurden, werden vermisst?"
  },
  AvgDialog_123116_Content_80 = {
    Text = "Ich weiß, wo die Zeremonie ist, und ich kann euch dorthin bringen, aber..."
  },
  AvgDialog_123116_Content_81 = {
    Text = "Ich brauche einen kleinen Gefallen von dir."
  },
  AvgDialog_123116_Content_82 = {
    Text = "Was für ein Gefallen? Ich hoffe, du kannst es klarstellen."
  },
  AvgDialog_123116_Content_83 = {
    Text = "Immer noch keine Antwort, das Mädchen hinterließ nur einen Satz und ging mit einem stotternden Ton davon."
  },
  AvgDialog_123116_Content_84 = {
    Text = "Hm☆Hm! Ich gehe zuerst ein paar Dinge erledigen. In zehn Minuten versammeln wir uns draußen~"
  },
  AvgDialog_123116_Content_85 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_123116_Content_86 = {
    Text = "Das ist auch gut; wir können zuerst die Chantry des Lebens kontaktieren, um Verstärkung zu senden, um diesen leidenden Personen zu helfen."
  },
  AvgDialog_123116_Content_87 = {
    Text = "Es bleibt mir nichts anderes übrig."
  },
  AvgDialog_123116_Content_88 = {
    Text = "Als du in die Richtung blickst, in die das Mädchen gegangen war, lässt das wachsende Gefühl der Unruhe dich fühlen, als würde etwas deinen Rücken hinaufkriechen."
  },
  AvgDialog_123116_Content_89 = {
    Text = "Seine Quelle ist das Gefühl der Entfremdung, das unter der naiven äußeren Erscheinung des anderen liegt, einer, die der Menschheit extrem nahe ist, aber grell falsch..."
  },
  AvgDialog_123116_Content_9 = {
    Text = "Ja, nachdem der Kontakt zu Pater White, der für die Pfarrei Howick zuständig ist, abgebrochen wurde, beschloss der Vatikan, Verstärkung zu senden."
  },
  AvgDialog_123117_Content_1 = {
    Text = "In Silber und Blut"
  },
  AvgDialog_123117_Content_10 = {
    Text = "...Ich hätte diese Dinge nicht mit dir besprechen sollen."
  },
  AvgDialog_123117_Content_100 = {
    Text = "Mouchette... wenn du noch da bist... komm heraus... ich bitte dich..."
  },
  AvgDialog_123117_Content_101 = {
    Text = "Dennoch bleibt die Leere leer. Das Mädchen namens Mouchette ist verschwunden."
  },
  AvgDialog_123117_Content_102 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_123117_Content_103 = {
    Text = "Du schließt die Augen und lässt einen tiefen Seufzer aus. Es bleibt keine Zeit mehr. \n Salvador ist noch draußen, und das unsichtbare Tor ist immer noch da. Du musst zurückgehen."
  },
  AvgDialog_123117_Content_104 = {
    Text = "Es tut mir leid, dass du in diese grausame Welt gekommen bist... und es tut mir leid, dass ich dich nicht nach Hause bringen konnte..."
  },
  AvgDialog_123117_Content_105 = {
    Text = "Im nächsten Moment unterbrichst du die Verbindung zur psychischen Dimension von Mouchette——"
  },
  AvgDialog_123117_Content_106 = {
    Text = "Nach einem kurzen Moment der Schwindelgefühle kehrte dein Geist in die Hülle zurück, und alles kehrte zum Ausgangspunkt zurück:"
  },
  AvgDialog_123117_Content_107 = {
    Text = "Das unsichtbare Tor ist immer noch außer Kontrolle, und Mo Xias Axt liegt ruhig in deiner Hand."
  },
  AvgDialog_123117_Content_108 = {
    Text = "<Shake:Mouchette...Ich...>"
  },
  AvgDialog_123117_Content_109 = {
    Text = "Du umklammerst den Griff und siehst das stille Mädchen an. Sie steht in den Ruinen ihres Verstandes da und wartet auf den tödlichen Schlag."
  },
  AvgDialog_123117_Content_11 = {
    Text = "Du seufztest, ganz niedergeschlagen. Salvador sah alles und konnte sich ein leises Lachen nicht verkneifen."
  },
  AvgDialog_123117_Content_110 = {
    Text = "Vielleicht ist es ein psychologischer Effekt, aber du hast immer das Gefühl, dass diese Augen nicht ganz ihren Verstand verloren haben.\nWeil du diese Augen schon einmal lächeln gesehen hast."
  },
  AvgDialog_123117_Content_111 = {
    Text = "<Shake:Wie lange... wirst du... mich einfach nur anstarren...?>"
  },
  AvgDialog_123117_Content_112 = {
    Text = "Mouchette! Du bist zurück?!"
  },
  AvgDialog_123117_Content_113 = {
    Text = "<Shake:Ich habe nicht... aber ich... habe... deine Worte gehört...>"
  },
  AvgDialog_123117_Content_114 = {
    Text = "Du hast recht... Es sollte nicht so sein... Ich kann nicht einfach aufgeben, ohne es überhaupt zu versuchen..."
  },
  AvgDialog_123117_Content_115 = {
    Text = "Mouchette greift mit all ihrer letzten Kraft nach dir und berührt den silbernen Schlüssel an deiner Brust."
  },
  AvgDialog_123117_Content_116 = {
    Text = "Egal wie das Ergebnis ausfällt, das unsichtbare Tor wird verschwinden..."
  },
  AvgDialog_123117_Content_117 = {
    Text = "Ich werde niemals... zulassen, dass dieser Ort zu einer weiteren Welt des Nebelunglücks wird..."
  },
  AvgDialog_123117_Content_118 = {
    Text = "Besonders nachdem ich erfahren habe, wie hart ihr gearbeitet habt, um diese Welt zu retten"
  },
  AvgDialog_123117_Content_119 = {
    Text = "Dann aktiviert sich der silberne Schlüssel auf deiner Brust und strahlt Licht aus, das deinen Blick in ein Weiß taucht."
  },
  AvgDialog_123117_Content_12 = {
    Text = "Mouchette, sie ist wirklich ein besonderes Kind... nur besonders, aber immer noch ein sehr gutes Kind."
  },
  AvgDialog_123117_Content_120 = {
    Text = "Du hörtest einen durchdringenden Schrei, ein schmerzhaftes Wimmern, die Verzerrung einer Flöte und das Geräusch von etwas, das zerbricht."
  },
  AvgDialog_123117_Content_121 = {
    Text = "Oder vielleicht sind das nur die Halluzinationen, die durch deine Anspannung hervorgerufen werden, denn in dieser Weite reinen Weißes hast du die Kontrolle über deine Sinne und dein Zeitgefühl verloren."
  },
  AvgDialog_123117_Content_122 = {
    Text = "Nach einer unbekannten Zeit, als alle akustischen Halluzinationen verblassen, kehren deine verschiedenen Sinne schließlich zurück—"
  },
  AvgDialog_123117_Content_123 = {
    Text = "Der Nebel ist verschwunden. Das Tor ist weg. Nur der blutgetränkte Altar bleibt zurück, und Salvador sieht dich mit hohlen, besorgten Augen an."
  },
  AvgDialog_123117_Content_124 = {
    Text = "Der bleiche Bote, haben wir... versagt?"
  },
  AvgDialog_123117_Content_125 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_123117_Content_126 = {
    Text = "In diesem Moment ertönte ein leises Lachen hinter euch."
  },
  AvgDialog_123117_Content_127 = {
    Text = "%player%, Salvador, was starrt ihr so? Die Aufgabe ist beendet."
  },
  AvgDialog_123117_Content_128 = {
    Text = "<Big:MOUCHETTE—!!>"
  },
  AvgDialog_123117_Content_129 = {
    Text = "Überrascht riefst du laut, doch im nächsten Moment konntest du dir ein Lächeln nicht verkneifen."
  },
  AvgDialog_123117_Content_13 = {
    Text = "Braves Kind? Bitte, benutze dieses Wort nicht, um... Moment mal, habt ihr irgendein Geräusch gehört?"
  },
  AvgDialog_123117_Content_130 = {
    Text = "Du musst nicht so laut sein, ich kann dich auch so gut hören. Die aufregenden Kämpfe sind sowieso vorbei, jetzt bleibt nur noch das langweilige Alltagsleben."
  },
  AvgDialog_123117_Content_131 = {
    Text = "Nachdem ich zurück bin, möchte ich wirklich eine dampfende Tasse Haselnuss-Kava-Tee haben, oh... Hier gibt es das nicht, dann esse ich eben einen kleinen Kuchen."
  },
  AvgDialog_123117_Content_132 = {
    Text = "Wir können plaudern, während wir ein paar Cupcakes genießen, zum Beispiel, wer Murphy ist, wer Liz ist, wer Dole ist und welche interessanten Abenteuer du mit dem Erwachungskörper hattest?"
  },
  AvgDialog_123117_Content_133 = {
    Text = "Egal, ich kann sowieso nicht zurückkehren, ich kann nur mehr über diese Welt erfahren."
  },
  AvgDialog_123117_Content_134 = {
    Text = "Ich denke, diese Bitte wird %player% nicht ablehnen."
  },
  AvgDialog_123117_Content_135 = {
    Text = "Salvador lächelte dich an, und du lächelst ebenfalls und siehst zu Mouchette. \n Der dichte Nebel verflog, das Mondlicht des Nachthimmels fiel auf euch und warf einen zarten Glanz."
  },
  AvgDialog_123117_Content_136 = {
    Text = "Du hast immer noch viele Fragen an Mouchette, aber du hast sie in deinem Herzen unterdrückt——"
  },
  AvgDialog_123117_Content_137 = {
    Text = "Vielleicht liegt es an dem schönen Mondlicht, oder vielleicht an einem Gefühl, das du nicht genau beschreiben kannst, das fast wie eine “Wiedergeburt“ ist, ein Gefühl des Entkommens aus dem Tod."
  },
  AvgDialog_123117_Content_138 = {
    Text = "Egal, den Bericht kann ich jederzeit schreiben, aber so einen anderen Weltbesucher zu feiern, gibt es nicht oft die Gelegenheit zur Wiedergeburt in der neuen Welt."
  },
  AvgDialog_123117_Content_139 = {
    Text = "Herzlichen Glückwunsch, du bist ein Erwecker, Mouchette. Von nun an ist dies nicht nur unsere Welt, sondern auch deine Welt..."
  },
  AvgDialog_123117_Content_14 = {
    Text = "Es scheint, als würde jemand weinen... und das Weinen wird immer lauter..."
  },
  AvgDialog_123117_Content_140 = {
    Text = [[
Erwecker Mouchette
Willkommen in unserer Welt]]
  },
  AvgDialog_123117_Content_15 = {
    Text = "Du hörtest aufmerksam zu, aber du hörtest nichts. \n Du sahst Salvador wieder an, und er schüttelte sanft den Kopf."
  },
  AvgDialog_123117_Content_16 = {
    Text = "In diesem Moment ließ Mouchette plötzlich einen Schrei los, beugte sich nach vorne und hielt sich schmerzerfüllt die Ohren zu."
  },
  AvgDialog_123117_Content_17 = {
    Text = "<Shake:Warte eine Sekunde... Jemand, nein, viele Leute, schreien und heulen in meinem Kopf...>"
  },
  AvgDialog_123117_Content_18 = {
    Text = "Du bemerkst, dass etwas nicht stimmt, und siehst dir Mouchettes Zustand an, aber du siehst nur, dass sie unaufhörlich schmerzhaft zittert und ihre Pupillen sich ständig weiten."
  },
  AvgDialog_123117_Content_19 = {
    Text = "Außer Kontrolle? Liegt es an der Silberkern Flüssigkeit...?"
  },
  AvgDialog_123117_Content_2 = {
    Text = "Unter dem himmelweiten Silber und Blut wogt der grenzenlose dichte Nebel, das unsichtbare Tor strahlt Licht aus, aber es scheint nicht mehr unbesiegbar zu sein —"
  },
  AvgDialog_123117_Content_20 = {
    Text = "Silberkern Flüssigkeit!?"
  },
  AvgDialog_123117_Content_21 = {
    Text = "Du hast die Blutspuren auf Mouchette sorgfältig untersucht, und mitten im dunklen Rot floss die silberne Flüssigkeit langsam, die durch ihre ungeschützte Haut in ihren Körper eindrang."
  },
  AvgDialog_123117_Content_22 = {
    Text = "Mouchette ist durch das Opferritual in unsere Welt gekommen, und diese Silberkern Flüssigkeit wurde als Opfergabe verwendet, wodurch sie wahrscheinlich auch als “Teil“ des Rituals betrachtet wurde..."
  },
  AvgDialog_123117_Content_23 = {
    Text = "Das geht nicht, hier gibt es zu viel und zu gemischte Silberkern Flüssigkeit, sie muss sofort behandelt werden, sonst wird sie als gewöhnlicher Mensch verrückt!"
  },
  AvgDialog_123117_Content_24 = {
    Text = "Du und Salvador habt sofort begonnen, die silberne Flüssigkeit von Mouchette zu reinigen, aber es war bereits zu spät—"
  },
  AvgDialog_123117_Content_25 = {
    Text = "<Red:<Shake:AAAAHHH—!>>"
  },
  AvgDialog_123117_Content_26 = {
    Text = "Mit einem schrecklichen Schrei zerstreuten sich Mouchettes Pupillen offiziell, spalteten sich, und ihr Körper brach verzerrt auseinander, spritzte eine große Menge Fleisch und verwandelte sich in eine schwer zu beschreibende Existenz."
  },
  AvgDialog_123117_Content_27 = {
    Text = "Diese zersplitterten Fleischstücke spritzen auf dich und Salvador sowie auf die unsichtbare Tür und erzeugen auf der Oberfläche des unbekannten und unheilvollen Letzteren Schichten von Wellen."
  },
  AvgDialog_123117_Content_28 = {
    Text = "Es stimmt etwas nicht, die “Tür“ verändert sich..."
  },
  AvgDialog_123117_Content_29 = {
    Text = "Bevor du zu Ende sprechen kannst, überträgt ein starker Aufprall über die Verbindung zwischen der unsichtbaren Tür und dem Silberschlüssel in dein Gehirn, sodass du sofort verstummst."
  },
  AvgDialog_123117_Content_3 = {
    Text = "Der silberne Schlüssel in deiner Hand strahlt ein blendendes und resolutes Leuchten aus, das allmählich den Riss in der Zeit und im Raum schließt und langsam alle Anomalien beseitigt, die durch die Zeremonie verursacht wurden."
  },
  AvgDialog_123117_Content_30 = {
    Text = "Unter dem unerträglichen psychischen Trauma blutest du aus der Nase, verlierst alle Kraft und kniest halb am Boden."
  },
  AvgDialog_123117_Content_31 = {
    Text = "<Red:<Shake:Töte, töte, töte! Töte alle!>>"
  },
  AvgDialog_123117_Content_32 = {
    Text = "<Red:<Shake:Hahaha! Sieh zu, wie diese Welt brennt!>>"
  },
  AvgDialog_123117_Content_33 = {
    Text = "Die Axt, die einst den Weg für dich frei machte, wird jetzt hochgehoben und zielt auf deinen Kopf. Und du bist durch eine seltsame geistige Verbindung völlig erschöpft, verlierst das Bewusstsein und kannst dich nicht bewegen."
  },
  AvgDialog_123117_Content_34 = {
    Text = "<Shake:Mouchette...>"
  },
  AvgDialog_123117_Content_35 = {
    Text = "Du kämpfst darum, zu sprechen, aber deine Stimme ist heiser und schwach, unfähig, Mouchettes Verstand überhaupt zu wecken."
  },
  AvgDialog_123117_Content_37 = {
    Text = "Am Ende fiel die Axt schwer und drang tief ins Fleisch ein—\n im letzten Moment trat Salvador vor dich und nahm den Schlag auf."
  },
  AvgDialog_123117_Content_38 = {
    Text = "Blut floss über Salvadors Schulter, doch sein Gesichtsausdruck zeigte keinen Groll, sondern nur Mitgefühl und Barmherzigkeit."
  },
  AvgDialog_123117_Content_39 = {
    Text = "Kind, ich weiß, dass das nicht deine Absicht war. Du hast dich nur verloren."
  },
  AvgDialog_123117_Content_4 = {
    Text = "Nach langer Zeit fängt das schwebende Silber und Blut an zu fallen, landet auf dem Boden und auf euch, und der dichte Nebel um euch herum wird mit bloßem Auge sichtbar dünner und zieht sich zusammen, alles wird besser."
  },
  AvgDialog_123117_Content_40 = {
    Text = "<Red:<Shake:TÖTE! ZERSTÖRE ALLES!>>"
  },
  AvgDialog_123117_Content_41 = {
    Text = "Der Wahnsinn hat Mouchette vollständig verzehrt; in diesem Moment wird sie nur von einem gewalttätigen Impuls der Zerstörung und des Gemetzels getrieben."
  },
  AvgDialog_123117_Content_42 = {
    Text = "<Shake:Salvador, nutzlos, sie...>"
  },
  AvgDialog_123117_Content_43 = {
    Text = "Du sahst einen Blick auf Mouchette, die nicht mehr als “Mensch“ bezeichnet werden konnte, und deine Stimme zitterte. \n Noch im vorherigen Moment war sie so lebendig."
  },
  AvgDialog_123117_Content_44 = {
    Text = "Nein, bleicher Bote. Sie ist nur verloren."
  },
  AvgDialog_123117_Content_45 = {
    Text = "Salvador trat vor und näherte sich der erneut von Mouchette erhobenen scharfen Axt."
  },
  AvgDialog_123117_Content_46 = {
    Text = "Blut spritzte von der Klinge der Axt auf sein Gesicht, doch Salvador zeigte keine Anzeichen von Angst."
  },
  AvgDialog_123117_Content_47 = {
    Text = "Es tut mir leid, dass ich nicht da war, als die Morgenröte der Sterne Menschen opferte und dich herbeirief."
  },
  AvgDialog_123117_Content_48 = {
    Text = "Der Tropfen Blut von Mouchettes Axt lief Salvadors Wange hinunter, wie eine Träne."
  },
  AvgDialog_123117_Content_49 = {
    Text = "Salvador wischte diesen Tropfen “Träne“ nicht ab, er hielt nur fest den Axtkopf von Mouchette und hob gleichzeitig die andere Hand——"
  },
  AvgDialog_123117_Content_5 = {
    Text = "Bald wird die Anomalie der Dimensionstür auf das Minimum reduziert, Mouchette, das ist der beste Zeitpunkt für dich, nach Hause zu gehen."
  },
  AvgDialog_123117_Content_50 = {
    Text = "Aber in diesem Moment bin ich hier und werde dich erlösen."
  },
  AvgDialog_123117_Content_51 = {
    Text = "Die blutige Hand des Priesters berührte die Stirn der Jungfrau. In einem Augenblick strahlte ein helles und entschlossenes Licht von dem Kontaktpunkt zwischen ihnen aus."
  },
  AvgDialog_123117_Content_52 = {
    Text = "Das ist ein Priester einer Welt, der dem Lamm einer anderen Welt einen Segen erteilt."
  },
  AvgDialog_123117_Content_53 = {
    Text = "Als dieses Licht aufleuchtet, verschwindet der heftige Schmerz in deinem Kopf plötzlich schnell, als hätte jemand all deinen Schmerz übernommen..."
  },
  AvgDialog_123117_Content_54 = {
    Text = "Salvador, halt an, das betrifft eine Verbindung zwischen Dimensionen, die niemand ertragen kann!"
  },
  AvgDialog_123117_Content_55 = {Text = "Ich weiß."},
  AvgDialog_123117_Content_56 = {
    Text = "Salvadors Stimme zitterte und brach. Diese Stufe der Verbindung war, selbst für ihn, eine Qual, die alle Grenzen überschritt."
  },
  AvgDialog_123117_Content_57 = {
    Text = "Bald konnte er es nicht mehr ertragen und Blutstränen flossen aus ihm."
  },
  AvgDialog_123117_Content_58 = {
    Text = "Aber da ich der Stellvertreter des All-Vaters bin, muss ich mein Bestes geben."
  },
  AvgDialog_123117_Content_59 = {
    Text = "Mehr Blut und Tränen flossen aus Salvadors Augenbinde, doch diese Farbe wurde von dem intensiven Glanz des “Segens“ beeinflusst, als ob das, was aus Salvadors Augen floss, kein Blut, sondern geschmolzenes Gold wäre."
  },
  AvgDialog_123117_Content_6 = {
    Text = "Ich werde die Energie des Silberschlüssels immer auf Maximum einstellen, damit du sicher die Dimensionen überqueren kannst."
  },
  AvgDialog_123117_Content_60 = {
    Text = "Dieses Gold fiel und tropfte auf den Handrücken von Mouchette, schälte die goldene Schale ab und offenbarte die blutrote Farbe, die sich mit dem Blut der Menschenopfer, das auf Mouchette gespritzt war, und mit Mouchettes eigenem Blut vereinte."
  },
  AvgDialog_123117_Content_61 = {
    Text = "Im Namen des All-Vaters, Mouchette, werde ich nicht zulassen, dass du vom rechten Weg abkommst."
  },
  AvgDialog_123117_Content_62 = {
    Text = "Mit diesem Ruf strahlte Mouchettes Stirn in starkem Licht, das so intensiv war, dass es das Blut, das ihren Körper bedeckte, und das Licht der immateriellen Tür vollständig überstrahlte."
  },
  AvgDialog_123117_Content_63 = {
    Text = "Das ist das Licht, das Salvador mit seinem Leben entfaltet hat."
  },
  AvgDialog_123117_Content_64 = {
    Text = "<Shake:Ugh...>"
  },
  AvgDialog_123117_Content_65 = {
    Text = "In diesem Licht, das alles erleuchtet, erhält das gespaltene Auge einen Moment der Klarheit und blickt mit dem verbliebenen Verstand auf seinen Handrücken."
  },
  AvgDialog_123117_Content_66 = {
    Text = "Dort gibt es kein Zeichen mehr von Salvadors Blut, da alles Blut bereits verschmolzen ist."
  },
  AvgDialog_123117_Content_67 = {
    Text = "Das Blut des Opfers und des Täters, das Blut der Schuldigen und des Erlösers, verwoben sich zu demselben Blutfluss."
  },
  AvgDialog_123117_Content_68 = {
    Text = "Ich... habe gesagt..."
  },
  AvgDialog_123117_Content_69 = {
    Text = "<Shake:Ich hasse es... andere zu opfern... um sich selbst zu retten...>"
  },
  AvgDialog_123117_Content_7 = {
    Text = "Es wäre gut, vor dem Durchqueren ein Bad zu nehmen. Mit blutverschmierten Kleidern zurückzukehren, ich frage mich, ob ich den Ermittler erschrecken werde."
  },
  AvgDialog_123117_Content_70 = {
    Text = "Mo Xia schob Salvador mit dem letzten Rest ihres Verstandes weg und sah dich an. \n Du sahst, wie sie die Axt mit all ihrer Kraft hob, und du sahst auch, wie die Tränen über ihr Gesicht strömten."
  },
  AvgDialog_123117_Content_71 = {
    Text = "Von jetzt an... lass ihn das nicht wieder tun... Diejenigen, die wirklich leben sollten, sind Menschen wie er..."
  },
  AvgDialog_123117_Content_72 = {
    Text = "Wegen des Rituals... hat das unsichtbare Tor mich ein Teil davon gemacht..."
  },
  AvgDialog_123117_Content_73 = {
    Text = "<Shake:Wenn du mich tötest, wird es sich auflösen... Diese Menschen... werden ebenfalls befreit...>"
  },
  AvgDialog_123117_Content_74 = {
    Text = "Und... das ist keine Desertion... es ist, den Feind... mit dir... niederzuschlagen..."
  },
  AvgDialog_123117_Content_75 = {
    Text = "Mouchette gab mit aller Kraft die Axt in deine Hände, während du, der die Axt entgegennahm, nur regungslos an Ort und Stelle verharren konntest."
  },
  AvgDialog_123117_Content_76 = {
    Text = "Im Ernst... warum habe ich... eine Wahl getroffen, die ich nicht einmal verstehe..."
  },
  AvgDialog_123117_Content_77 = {
    Text = "Offensichtlich entspricht die Zerstörung der Welt mehr meinem Stil..."
  },
  AvgDialog_123117_Content_78 = {
    Text = "Mouchette schluchzte, und im nächsten Moment fiel ohne Vorwarnung ein Tropfen Träne aus ihren Augen und zerbrach in deiner Handfläche, während er an ihrer Axt entlangrann."
  },
  AvgDialog_123117_Content_79 = {
    Text = "Bald begannen die von Tränen durchflossenen Augen, verwirrt zu werden und langsam den Wahnsinn zu entwickeln.\nMouchette wird wieder den Verstand verlieren."
  },
  AvgDialog_123117_Content_8 = {
    Text = "Sollten wir nicht noch einen Tisch decken und ein paar kleine Kuchen für den Nachmittagstee bringen?"
  },
  AvgDialog_123117_Content_80 = {
    Text = "Der bleiche Bote, bitte nicht... Ich werde sie erneut erlösen."
  },
  AvgDialog_123117_Content_81 = {
    Text = "Salvador kämpft, um sich zu erheben, seine Stimme ist ein verzweifelter Hilferuf. Du blickst auf die Axt, dein Geist ist ein Sturm aus Trauer und Konflikten."
  },
  AvgDialog_123117_Content_82 = {
    Text = "Es war nicht nur eine Axt; es war ein Lebensvertrauen und ein Abschied."
  },
  AvgDialog_123117_Content_83 = {
    Text = "<Shake:Gib mir einen Moment... es muss einen anderen Weg geben... es muss...>"
  },
  AvgDialog_123117_Content_84 = {
    Text = "Plötzlich erschien eine grausame Methode in deinem Kopf –"
  },
  AvgDialog_123117_Content_85 = {
    Text = "Ohne zu viel nachzudenken, umklammerst du mit einer Hand den Silberschlüssel und greifst mit der anderen nach Mouchettes Hand, während du in die trüben Tiefen des Bewusstseins eintauchst."
  },
  AvgDialog_123117_Content_86 = {
    Text = "Durch den Link des Silberschlüssels Mouchette zwangsweise von einem Menschen in einen Erwecker zu verwandeln, ist das einzige, was dir momentan einfällt."
  },
  AvgDialog_123117_Content_87 = {
    Text = "In dem Moment, als du in Mouchettes Geist eintauchtest, drangen unzählige writhing und strömende Lichtpunkte in dein Sichtfeld ein. \n Sie schrien alle und riefen, aber keiner von ihnen war Mouchette."
  },
  AvgDialog_123117_Content_88 = {
    Text = "In Mouchettes geistiger Welt gibt es keine Mouchette."
  },
  AvgDialog_123117_Content_89 = {
    Text = "Mouchette! Mouchette, wo bist du..."
  },
  AvgDialog_123117_Content_9 = {
    Text = "Das wäre noch besser. Wenn ich mir dieses langweilige, chaotische Weltbild anschaue, wird der kleine Kuchen bestimmt noch leckerer schmecken."
  },
  AvgDialog_123117_Content_90 = {
    Text = "Keine Antwort. Als normale Person war das letzte “Gesuch“ das Maximum, das sie unter Wahnsinn und Absturz tun konnte."
  },
  AvgDialog_123117_Content_91 = {
    Text = "Mouchette? Hast du aufgegeben? Ja, du hast gesagt, dass es jede Woche ein paar Mal gibt, an denen du nicht mehr leben willst, und du hast ständig das Wort “Tod“ im Mund..."
  },
  AvgDialog_123117_Content_92 = {
    Text = "Aber so ist es nicht... Salvador, ich und der Ermittler, den du immer wieder erwähnst, wollen nicht, dass so etwas passiert..."
  },
  AvgDialog_123117_Content_93 = {
    Text = "Also, Mouchette, komm heraus..."
  },
  AvgDialog_123117_Content_94 = {
    Text = "Doch egal, wie sehr du schreist oder suchst, alles um dich herum sind die wahnsinnigen Heul- und Schreigerausche."
  },
  AvgDialog_123117_Content_95 = {
    Text = "Mouchette ist \"verschwunden.\""
  },
  AvgDialog_123117_Content_96 = {
    Text = "...eigentlich habe ich einen Weg gefunden..."
  },
  AvgDialog_123117_Content_97 = {
    Text = "Es ist nur möglich, den Silberkern, der in deinen Körper eingedrungen ist, zu nutzen, um dich in einen Erwecker zu verwandeln. Das Risiko des Scheiterns ist sehr hoch, aber es ist momentan die einzige Methode, die mir einfällt."
  },
  AvgDialog_123117_Content_98 = {
    Text = "<Small:Ich dachte, das Schwierigste an dieser Sache sei die “Erweckung“, aber ich hätte nie gedacht, dass ich nicht einmal deinen Geist finden kann...>"
  },
  AvgDialog_123117_Content_99 = {
    Text = "Du fielst in eine lange Stille, in der jeder Atemzug immens schwerfiel. \n Als Wächter bist du dir der Folgen für gewöhnliche Menschen bewusst, wenn sie übermäßigem Silber ausgesetzt sind."
  },
  AvgDialog_123118_Content_1 = {
    Text = "Im grenzenlosen dichten Nebel hallen die frostigen Klagegesänge unaufhörlich wider."
  },
  AvgDialog_123118_Content_10 = {
    Text = "Die Liebe des Vaters kann nicht jeden retten, aber wir werden unser Bestes tun, um jedem Opfer eine helfende Hand zu reichen."
  },
  AvgDialog_123118_Content_11 = {
    Text = "<Shake:Ruf nicht mehr an...>"
  },
  AvgDialog_123118_Content_12 = {
    Text = "Unter dem Gewicht des psychischen Traumas begann sie unkontrollierbar aus der Nase zu bluten."
  },
  AvgDialog_123118_Content_13 = {
    Text = "<Shake:Ich habe gesagt, <Big:ruf nicht mehr an...>>"
  },
  AvgDialog_123118_Content_15 = {
    Text = "Mouchette rief wütend und, in ihrer Aufregung, schwang sie die Axt und hieb auf die humanoiden Nebel, doch sie sah, wie der Nebel lautlos spaltete und sich schnell wieder vereinigte."
  },
  AvgDialog_123118_Content_16 = {
    Text = "Nutzlos. Egal wie lange der dichte Nebel bleibt, diese Monster werden nicht verschwinden."
  },
  AvgDialog_123118_Content_17 = {
    Text = "Deshalb hast du uns vorher gebeten, dir zu helfen, die Monster abzulenken, nicht wahr?"
  },
  AvgDialog_123118_Content_18 = {
    Text = "Wollt ihr jetzt mit mir abrechnen? Ihr müsst euch anstellen, rückt bitte ein wenig nach hinten..."
  },
  AvgDialog_123118_Content_19 = {
    Text = "Mouchette wischte sich das Nasenbluten ab und schwang weiter die Axt. Das Gefühl des Kämpfens ließ ihr Blut so kochen, dass sie einfach nicht aufhören konnte."
  },
  AvgDialog_123118_Content_2 = {
    Text = "@2I... speichern @2..."
  },
  AvgDialog_123118_Content_20 = {
    Text = "Da es jetzt keinen Rückzug gibt, sollten wir diesen Angriff zuerst abwehren!"
  },
  AvgDialog_123118_Content_21 = {
    Text = "Mouchette, sei vernünftig! Wenn das so weitergeht, wirst du..."
  },
  AvgDialog_123118_Content_22 = {
    Text = "Wirst du sterben, oder?"
  },
  AvgDialog_123118_Content_23 = {
    Text = "Ich habe jede Woche ein paar Mal das Gefühl, nicht mehr leben zu wollen, passend dazu..."
  },
  AvgDialog_123118_Content_24 = {
    Text = "Mouchettes Worte verstummten plötzlich. Vor ihr erstrahlte plötzlich ein Licht, und dann fiel ein warmes Gefühl auf sie herab und strömte in ihre Gliedmaßen und zu ihrem ganzen Körper."
  },
  AvgDialog_123118_Content_25 = {
    Text = "Salvador segnete sie."
  },
  AvgDialog_123118_Content_26 = {
    Text = "<Shake:Was machst du?!>"
  },
  AvgDialog_123118_Content_27 = {
    Text = "Mouchette trat unwillkürlich einen Schritt zurück. \n Dieses warme Gefühl war zu fremd. Es sollte nicht an ihr auftreten."
  },
  AvgDialog_123118_Content_28 = {
    Text = "Wir, wir sind Feinde, warum..."
  },
  AvgDialog_123118_Content_29 = {
    Text = "Ich habe gesagt, dass wir keine Feinde sind."
  },
  AvgDialog_123118_Content_3 = {
    Text = "Speichern @2... @2 mir..."
  },
  AvgDialog_123118_Content_30 = {
    Text = "Nicht ein Feind zu sein, bedeutet nicht, ein Partner zu sein!"
  },
  AvgDialog_123118_Content_31 = {
    Text = "Ich wäre nicht naiv genug zu denken, dass jemand, den ich nur ein paar Mal getroffen habe, ein Begleiter ist..."
  },
  AvgDialog_123118_Content_32 = {
    Text = "Aber wir haben bereits gemeinsam gegen diese Kultisten gekämpft, nicht wahr? Diejenigen, die Seite an Seite kämpfen, sind Partner."
  },
  AvgDialog_123118_Content_33 = {
    Text = "Übrigens glaube ich nicht, dass dies meine langweilige Theorie ist, dass ich jeden liebe und jeder mich liebt, ich neige eher dazu, dass..."
  },
  AvgDialog_123118_Content_34 = {
    Text = "Ich neige eher dazu, es als die Überlebensweisheit in dieser grausamen Welt zu verstehen."
  },
  AvgDialog_123118_Content_35 = {
    Text = "Der Glanz des Allvaters strahlt über die ganze Erde; selbst in den öden Ländern werden Brüder und Schwestern sich gegenseitig unterstützen."
  },
  AvgDialog_123118_Content_36 = {
    Text = "Mouchette presste die Lippen zusammen und schwieg. Ihr Blick war weiterhin wachsam und skeptisch, aber schließlich schwand diese Wachsamkeit und Skepsis allmählich und verwandelte sich in eine Art Verwirrung und leichten Nostalgie."
  },
  AvgDialog_123118_Content_37 = {
    Text = "Ihre Lippen bewegten sich, als würde sie etwas flüstern, aber da die Stimme zu leise war, konntest du nur undeutlich die drei Worte “Ermittler“ hören."
  },
  AvgDialog_123118_Content_38 = {
    Text = "Die Toten können wir beim nächsten Mal bedenken, ich habe noch jemanden, den ich zurücksehen muss."
  },
  AvgDialog_123118_Content_39 = {
    Text = "Du meinst... den Ermittler?"
  },
  AvgDialog_123118_Content_4 = {
    Text = "<Shake:Hör auf zu rufen! Warum heulen diese Nebel... immer?!>"
  },
  AvgDialog_123118_Content_40 = {
    Text = "Bevor Mouchette antworten konnte, kam plötzlich ein unsichtbarer Aufprall, der dich sofort erschaudern ließ und die Monster im Nebel noch wütender machte."
  },
  AvgDialog_123118_Content_41 = {
    Text = "Dieses Gefühl...<Shake:<Big:Das Ritual hat begonnen!>>"
  },
  AvgDialog_123118_Content_42 = {
    Text = "Beginnt die Zeremonie? Aber wir haben diese Menschen eindeutig gerettet."
  },
  AvgDialog_123118_Content_43 = {
    Text = "Und, blasser Bote, es waren gerade keine Priester der Chantry des Lebens unter den Gefangenen..."
  },
  AvgDialog_123118_Content_44 = {
    Text = "Sind die Menschen, die wir gerettet haben, nur Reserven? Oder ist der Zeitpunkt des Rituals festgelegt, sodass es durchgeführt werden muss, auch wenn nicht genügend Opfer vorhanden sind?"
  },
  AvgDialog_123118_Content_45 = {
    Text = "Jetzt ist nicht die Zeit, um Detektiv zu spielen."
  },
  AvgDialog_123118_Content_46 = {
    Text = "Wirst du hier weiter plappern, oder kommst du mit mir? Triff schnell deine Entscheidung!"
  },
  AvgDialog_123118_Content_47 = {
    Text = "Mouchette zeigte einen ungeduldigen Ausdruck, drehte sich um, wandte sich von dir ab und trat in den dichten Nebel ein."
  },
  AvgDialog_123118_Content_48 = {Text = "Mouchette!"},
  AvgDialog_123118_Content_49 = {
    Text = "Ich weiß, worüber du dir Sorgen machst. Diesmal werde ich keine Tricks anwenden."
  },
  AvgDialog_123118_Content_5 = {
    Text = "Wegen dieses dichten Nebels ist es möglicherweise nicht die \"Nebelkatastrophe\" deiner Welt, und diese Monster sind nicht die \"Uralten Objekte\", von denen du sprichst."
  },
  AvgDialog_123118_Content_50 = {
    Text = "Mouchette schwang ihre Axt, um den humanoiden Nebel zu zerstreuen, der sie überfiel, während sie antwortete."
  },
  AvgDialog_123118_Content_51 = {
    Text = "Obwohl dein Optimismus ziemlich problematisch ist und einige deiner Worte mit unrealistischem Idealismus gefüllt sind, die ans Licht gebracht werden müssen, ..."
  },
  AvgDialog_123118_Content_52 = {
    Text = [[
Aber es gibt immer einige Menschen, die darauf bestehen, diese langweilige Welt zu retten.
<Small:Du bist einer von ihnen, und der Ermittler ebenfalls...>]]
  },
  AvgDialog_123118_Content_53 = {
    Text = "Vielleicht versteht ihr euch gut, wer weiß?"
  },
  AvgDialog_123118_Content_54 = {
    Text = "Hat das Thema ein wenig zu weit abgeschweift... Diese Leute warten immer noch auf uns..."
  },
  AvgDialog_123118_Content_55 = {
    Text = "Warum läufst du noch nicht? Ich hoffe, das kann bald vorbei sein; ich möchte nach Hause gehen."
  },
  AvgDialog_123118_Content_56 = {
    Text = "Komm schon, halte mit mir Schritt, bleib nicht zurück. Ich bin die schnellste Vorhut des Nebelreich-Ermittlungsteams!"
  },
  AvgDialog_123118_Content_57 = {
    Text = "Mouchettes Silhouette sprintete durch den dichten Nebel nach vorne, und du tauschtest einen Blick mit Salvador aus, bevor du ihr folgtest."
  },
  AvgDialog_123118_Content_6 = {
    Text = "<Shake:Sie... was sind sie?>"
  },
  AvgDialog_123118_Content_7 = {
    Text = "Mouchette konnte nicht anders, als sich die Ohren zuzuhalten, aber leider war es vergeblich."
  },
  AvgDialog_123118_Content_8 = {
    Text = "Dieser Schmerz und Verzweiflung dringen langsam mit dem dichten Nebel in das Fleisch und die Knochen des Zuhörers ein und erreichen tief die Seele."
  },
  AvgDialog_123118_Content_9 = {
    Text = "Ich kann erkennen, dass ihre Seelen... die opfernden Menschen aus dem letzten Ritual sind."
  },
  AvgDialog_123119_Content_1 = {
    Text = "Zwischen Dimensionen"
  },
  AvgDialog_123119_Content_10 = {
    Text = "Mouchette zuckte mit den Schultern und hob die Hand, um auf die Dimensionstür zu zeigen, die kontinuierlich dichten Nebel ausspuckte und diese Welt erodierte."
  },
  AvgDialog_123119_Content_100 = {
    Text = "Nein, %player%, warte einen Moment..."
  },
  AvgDialog_123119_Content_101 = {
    Text = "Mouchette möchte deine Rettung verhindern. Nachdem sie von deinen Erfahrungen erfahren hat, ist sie voller Zweifel und Fragen."
  },
  AvgDialog_123119_Content_102 = {
    Text = "Aber es bleibt keine Zeit. Ein Ziehen aus der Seele zog sie an und führte sie hartnäckig aus dieser seltsamen Welt voller Lichtpunkte."
  },
  AvgDialog_123119_Content_103 = {
    Text = "Und der Lichtfleck, der sie inspiriert hatte, war dort, nicht weit entfernt, und strahlte sanfte und warme Güte aus, die ihr ein letztes Lebewohl zurief."
  },
  AvgDialog_123119_Content_104 = {
    Text = "Zeige @4 Informationen @3“Ich“, dann kannst du @2 nach Hause @1."
  },
  AvgDialog_123119_Content_105 = {
    Text = "@2, leb wohl, Mouchette, @2... ein anderes “Ich“."
  },
  AvgDialog_123119_Content_106 = {
    Text = "Sehr bald verzerrte das unsichtbare Summen, verschwand und schließlich gänzlich, zusammen mit Mouchettes Sehen, Hören und verschiedenen Sinnen."
  },
  AvgDialog_123119_Content_107 = {
    Text = "Als Mouchette wieder zu hören und zu sehen begann und in die Realität zurückkehrte, sah sie erneut die vertraute Gestalt, die Person, die sie nicht verstehen konnte."
  },
  AvgDialog_123119_Content_108 = {
    Text = "Mouchette, geh weg von hier, Salvador und ich werden uns um den Rest kümmern."
  },
  AvgDialog_123119_Content_109 = {
    Text = "Die Korrosion der “Tür“ vertieft sich weiterhin, und ich und der bleiche Bote müssen uns auf das Schlimmste vorbereiten..."
  },
  AvgDialog_123119_Content_11 = {
    Text = "Also muss ich gehen, nur ich kann gehen."
  },
  AvgDialog_123119_Content_110 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_123119_Content_111 = {
    Text = "Mouchette? Was starrst du? Verlass diesen Ort schnell."
  },
  AvgDialog_123119_Content_112 = {
    Text = "Sie schaut dich an, während Wut, Zorn, Mitleid und viele andere Emotionen in Mouchettes Brust miteinander verwoben sind, sodass sie kein Wort herausbringen kann."
  },
  AvgDialog_123119_Content_113 = {
    Text = "Schließlich schnaufte sie wütend, ballte die Fäuste und sprach widerwillig:"
  },
  AvgDialog_123119_Content_114 = {
    Text = "Von unserem ersten Treffen an hätte ich es wissen müssen, du bist so ein herzlicher und neugieriger “Protagonist“, eine Art Mensch, die ich niemals verstehen kann."
  },
  AvgDialog_123119_Content_115 = {
    Text = "Selbst in 100 Jahren werde ich deine Gehirnschaltungen nicht verstehen. Also gebe ich auf."
  },
  AvgDialog_123119_Content_116 = {Text = "Was?"},
  AvgDialog_123119_Content_117 = {
    Text = "Ich kenne den Schwingwellenwert, den du meinst, das ist ein anderes @4@3......"
  },
  AvgDialog_123119_Content_118 = {
    Text = "Ein vertrauter stechender Schmerz überkam Mouchette, wodurch ihre Worte verzerrt und verändert wurden. Nachdem sie es mehrmals versucht hatte, die Wahrheit des Lichtpunkts auszusprechen, gab Mouchette auf."
  },
  AvgDialog_123119_Content_119 = {
    Text = "Das Mädchen ersetzte Worte durch Taten, hielt fest deine Hand und ihr Gesichtsausdruck war voller Entschlossenheit."
  },
  AvgDialog_123119_Content_12 = {
    Text = "In euren Worten ausgedrückt, ist das... oh, die Überlebensweisheit in dieser grausamen Welt."
  },
  AvgDialog_123119_Content_120 = {
    Text = "Ich werde dir helfen, dieses große Problem zu lösen."
  },
  AvgDialog_123119_Content_121 = {
    Text = "Ich, Mouchette, die auffälligste Vorhut des Ermittlungsteams, werde diesen Kampf nicht als “Deserteur“ beenden."
  },
  AvgDialog_123119_Content_13 = {
    Text = "Als du Mouchettes Worte hörst, fallt ihr und Salvador in ein Schweigen und öffnet dann gleichzeitig den Mund——"
  },
  AvgDialog_123119_Content_14 = {
    Text = "Ich stimme nicht zu, Kind. Das Opfer sollte ich bringen."
  },
  AvgDialog_123119_Content_15 = {
    Text = "Ich stimme zu. Ich verspreche, dich zu retten oder dich auf diese Weise nach Hause zu bringen, egal welchen Preis es kostet."
  },
  AvgDialog_123119_Content_16 = {
    Text = "In dem gleichen Moment äußert ihr völlig gegensätzliche Meinungen und blickt euch unwillkürlich an."
  },
  AvgDialog_123119_Content_17 = {
    Text = "%player%, warum..."
  },
  AvgDialog_123119_Content_18 = {
    Text = "Dann ist es beschlossen, ich überlasse dir die Rückkehr, %player%."
  },
  AvgDialog_123119_Content_19 = {
    Text = "Mouchette unterbricht, bevor du oder Salvador reagieren könnt, und geht direkt auf das unbekannte und unheilvolle Tor zu."
  },
  AvgDialog_123119_Content_2 = {
    Text = "Mouchette, du sagst, dass du durch die unbekannte “Tür“ gehen willst...?"
  },
  AvgDialog_123119_Content_20 = {
    Text = "Du umklammerst den Silberschlüssel mit einer Hand fest und ziehst Salvador mit der anderen kräftig zu dir, während du Mouchettes Silhouette anschaust, ganz konzentriert, ohne auch nur zu blinzeln."
  },
  AvgDialog_123119_Content_21 = {
    Text = "Salvador, hör mir zu, vielleicht ist Mouchette anders."
  },
  AvgDialog_123119_Content_22 = {
    Text = "Das ist die Tür, die mit einer anderen Dimension verbunden ist, und Mouchette stammt aus dieser Dimension, sie wurde sogar mit demselben Ritual beschworen."
  },
  AvgDialog_123119_Content_23 = {
    Text = "Aber... wenn..."
  },
  AvgDialog_123119_Content_24 = {
    Text = "Wenn etwas nicht stimmt, werde ich den Silberschlüssel aktivieren und die Verbindung auf mich übertragen."
  },
  AvgDialog_123119_Content_25 = {
    Text = "Salvador sah in deine Augen, die sich vergeblich ruhig hielten, und sah, wie du den Silberschlüssel fest umklammert hast, schließlich seufzte er."
  },
  AvgDialog_123119_Content_26 = {
    Text = "Wenn es so weit ist, lass mich bitte mittragen."
  },
  AvgDialog_123119_Content_27 = {
    Text = "Der bleiche Bote, ich werde dich auf keinen Fall vor mir fallen lassen."
  },
  AvgDialog_123119_Content_28 = {
    Text = "Deine Antwort ist ein verständnisvolles Lächeln."
  },
  AvgDialog_123119_Content_29 = {
    Text = "Inzwischen hebt Mouchette die Hand und versucht, die unsichtbare Tür zu berühren."
  },
  AvgDialog_123119_Content_3 = {
    Text = "Nicht nur du, sondern auch Salvador war fassungslos."
  },
  AvgDialog_123119_Content_30 = {
    Text = "<Shake:Das ist...>"
  },
  AvgDialog_123119_Content_31 = {
    Text = "In dem Moment, in dem Mo Xia das Unsichtbare Tor berührte, strahlte es plötzlich ein helles Licht aus, genau wie zuvor."
  },
  AvgDialog_123119_Content_32 = {
    Text = "Gleichzeitig hast du auch den Silberschlüssel aktiviert."
  },
  AvgDialog_123119_Content_33 = {
    Text = "Das Licht, das vom Silberschlüssel ausbricht, resoniert mit dem Glanz der unsichtbaren Tür, und der Himmel aus Silber und Blut scheint von einer unsichtbaren Kraft geleitet zu werden, brodelnd und strömend."
  },
  AvgDialog_123119_Content_34 = {
    Text = "Unter der Kombination beider Aspekte ertönt ein unbekanntes Summen, das die Seele erodieren kann, vermischt mit endlosem dichten Nebel, der alles um sich herum erschüttert und alle Anwesenden in eine Art Schwindel der Trennung von Geist und Fleisch versetzt..."
  },
  AvgDialog_123119_Content_35 = {
    Text = "Die Welt@2 ist leer, wie@2@1 wie dichter Nebel, @3, was wird@2 in dieser Nichtigkeit@3 geboren."
  },
  AvgDialog_123119_Content_36 = {
    Text = "@1Nur große @4Traum ist @2unerwartet, dieses kleine @2kämpft jedoch, windet sich, entwickelt sich und verwandelt sich in @4Rassen."
  },
  AvgDialog_123119_Content_37 = {
    Text = "Im Dunkel ertönte der chaotische, verzerrte Flötenton, der Mouchettes Willen quälte. Es war offensichtlich Musik, doch sie erhaschte vage einen Blick auf die schreckliche Bedeutung darin."
  },
  AvgDialog_123119_Content_38 = {
    Text = "Menschen, das ist @3, wie sie sich selbst nennen. @2 im Vergleich zum endlosen @1 Universum, @4 klein und vergänglich."
  },
  AvgDialog_123119_Content_39 = {
    Text = "@3 ist nicht, dass @3 keine Spuren hinterlassen hat, sondern dass @1 Blut und Silber von Generation zu Generation fließen, @4@2 die Spuren @1 Beweise."
  },
  AvgDialog_123119_Content_4 = {
    Text = "Genau. Ich gehe rein, um dir zu helfen, diese Schwingwelle zu klären."
  },
  AvgDialog_123119_Content_40 = {
    Text = "Der chaotisch verzerrte Flötenton wurde immer schärfer und furchterregender, als würde er die Seele von Mouchette foltern. Sie konnte es nicht länger ertragen und öffnete plötzlich die Augen."
  },
  AvgDialog_123119_Content_41 = {
    Text = "Nachdem sie die Augen öffnete, hörte Mouchette keinen Klang von Flöten und sah auch keine Musiker. Die Umgebung war seltsam und bunt, nur große Lichtpunkte umgaben sie und hielten einen Abstand, der weder nah noch fern war."
  },
  AvgDialog_123119_Content_42 = {
    Text = "Es freut mich, dich zu sehen, Mouchette, “Ich“ Freund."
  },
  AvgDialog_123119_Content_43 = {
    Text = "Der Lichtfleck summte, und das Merkwürdige war, dass sie es vollkommen verstehen konnte. \n Oder besser gesagt, in diesem Moment war sie auch der Lichtfleck."
  },
  AvgDialog_123119_Content_44 = {
    Text = "Bin ich gefallen? So fühlt es sich also an, gefallen zu sein..."
  },
  AvgDialog_123119_Content_45 = {
    Text = "Nein, du lebst noch. Du wurdest nur von mir hierher gebracht. Du trägst den Duft von “Ich“ in dir."
  },
  AvgDialog_123119_Content_46 = {
    Text = "Wenn ich das nicht tue, wirst du aufgrund der Dimension des Fehlschlags @4 erleiden, weil du bereits @3 bist."
  },
  AvgDialog_123119_Content_47 = {
    Text = "Mouchette hörte die letzten Worte des Lichtpunkts nicht, denn in dem Moment, als die chaotischen Silben erklangen, begann ihr Kopf heftig zu schmerzen und drohte zu zerreißen."
  },
  AvgDialog_123119_Content_48 = {
    Text = "<Shake:Halt! Halt! Sag etwas, das ich hören kann... Wenn das so weitergeht, wird mein Kopf explodieren.>"
  },
  AvgDialog_123119_Content_49 = {
    Text = "Sie schien das Seufzen der Lichtpunkte zu hören, vielleicht aber auch nicht, denn unzählige seltsame Informationen strömten in Mouchettes Geist und zogen ihre gesamte Aufmerksamkeit auf sich."
  },
  AvgDialog_123119_Content_5 = {
    Text = "Kind, du verstehst die Gefahren nicht; Verletzungen in der psychischen Dimension können ebenfalls die reale Welt beeinflussen, du wirst..."
  },
  AvgDialog_123119_Content_50 = {
    Text = "Was ist das?"
  },
  AvgDialog_123119_Content_51 = {
    Text = "Was ihr jetzt braucht. Zeigt es mir, {Male=er,Female=sie} wird es verstehen."
  },
  AvgDialog_123119_Content_52 = {
    Text = "Was ich, deiner, nicht verstehen kann—"
  },
  AvgDialog_123119_Content_53 = {
    Text = "Warte, du bist... %player%?"
  },
  AvgDialog_123119_Content_54 = {
    Text = "Das ist unmöglich, ich habe dich gerade noch lebhaft gesehen, du siehst aus, als könntest du problemlos noch 100 Jahre leben."
  },
  AvgDialog_123119_Content_55 = {
    Text = "Die Lichtpunkte summten und ließen ein leises Lachen hören. Mouchette wusste nicht, ob man das als “Lachen“ bezeichnen konnte, denn es war nicht von Freude erfüllt. Genauer gesagt, es gab keine Emotionen."
  },
  AvgDialog_123119_Content_56 = {
    Text = "Du kannst es als das“Ich“einer anderen Dimension verstehen, und ich, das wahre Ich——"
  },
  AvgDialog_123119_Content_57 = {
    Text = "Mit den Worten der Lichtpunkte strömten unzählige Informationen in Mouchettes Geist. Diese Informationen spalteten sich ständig und vereinigten sich, wodurch instabile Bilder entstanden."
  },
  AvgDialog_123119_Content_58 = {
    Text = "Zunächst waren diese Bilder abstrakt und fleckig, vage und unklar, aber bald—"
  },
  AvgDialog_123119_Content_59 = {
    Text = "Diese seltsamen Lichter und Schatten formten sich zu einer Gestalt, einer Gestalt, die sie erkannte."
  },
  AvgDialog_123119_Content_6 = {
    Text = "Hier bin nur ich geeignet. Auch wenn ich etwas einfältig bin, bin ich nicht dumm."
  },
  AvgDialog_123119_Content_60 = {
    Text = "Die vertraute Gestalt erwacht mitten in einer Explosion und blickt verwirrt in diese Welt."
  },
  AvgDialog_123119_Content_61 = {
    Text = "Viele Jahre später werden die Menschen diese Explosion als die \"Akutsk-Explosion\" bezeichnen"
  },
  AvgDialog_123119_Content_62 = {
    Text = "Dann trat %er/sie% in Misaq ein, erlangte den Silberschlüssel, wurde ein “Schutzherr“ und begann, mit Gefährten, die als “Erwecker“ bekannt sind, Missionen zu übernehmen und diese seltsame und erschreckende Welt zu erkunden."
  },
  AvgDialog_123119_Content_63 = {
    Text = "So wie sie und der Ermittler, das Nebeluntersuchungsteam."
  },
  AvgDialog_123119_Content_64 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_123119_Content_65 = {
    Text = "Als sie an die vertrauten Menschen und die Vergangenheit denkt, seufzt Mouchette nostalgisch. Und das Leben von %player% geht weiter——"
  },
  AvgDialog_123119_Content_66 = {
    Text = "Sie sah, wie %player% durch die verschneite Stadt wanderte, dem Jagdhund gegenüberstand, der durch Zeit und Raum im geheimnisvollen Sanatorium streift, und die Ewigkeit der familiären Liebe erlebte."
  },
  AvgDialog_123119_Content_67 = {
    Text = "Ich bin %player% auch gefolgt, um die Cité zu erkunden, die voller Poesie und Blumen ist, während ich den Seufzern der Flammen lauschte und um das Verwelken der Rosen trauerte."
  },
  AvgDialog_123119_Content_68 = {
    Text = "Und es gibt Geisterschiffe, die auf dem Meer treiben. Glauben, Gottheiten und Opfer - zusammen mit %player% hat sie die Verzerrungen, Grausamkeiten und den Wahnsinn dieser Welt verstanden."
  },
  AvgDialog_123119_Content_69 = {
    Text = "Egal wie tief die Dunkelheit reichte, %player% und die Erwecker gaben niemals auf."
  },
  AvgDialog_123119_Content_7 = {
    Text = "Mouchette unterbrach Salvador und sah euch ernst an."
  },
  AvgDialog_123119_Content_70 = {
    Text = "So wie in dieser Welt konnten die Nebelkatastrophe, die Aschenreste und die Uralten Objekte sie und den Ermittler nicht besiegen, noch konnten sie das Mist Realm Untersuchungsteam besiegen."
  },
  AvgDialog_123119_Content_71 = {
    Text = "Das ist doch fast dasselbe!"
  },
  AvgDialog_123119_Content_72 = {
    Text = "Ich frage mich, wie es diesen kleinen Kerlen im Nebel jetzt geht?"
  },
  AvgDialog_123119_Content_73 = {
    Text = "Ah, ich möchte wirklich eine dampfende Tasse Haselnuss-Kava-Tee haben!"
  },
  AvgDialog_123119_Content_74 = {
    Text = "Mouchette lächelte. \n Sie dachte, %player% würde für immer an der Seite der Erwachten kämpfen—"
  },
  AvgDialog_123119_Content_75 = {
    Text = "Es ist nur natürlich, denn sie hat nie daran gedacht, das Nebeluntersuchungsteam zu verlassen, und die Erwachten würden natürlich nicht daran denken, ihre Hüter zu verlassen."
  },
  AvgDialog_123119_Content_76 = {
    Text = "Sie werden kämpfen und kämpfen, bis die Probleme der Welt gelöst sind, oder bis sie von der Welt gelöst werden.\nSo wie in allen Geschichten."
  },
  AvgDialog_123119_Content_77 = {
    Text = "Aber diese Welt ist viel grausamer, als Mouchette sich vorgestellt hat, viel grausamer als die, in der sie lebt."
  },
  AvgDialog_123119_Content_78 = {
    Text = "<Shake:Wie konnte das passieren!!>"
  },
  AvgDialog_123119_Content_79 = {
    Text = "Also du...!?"
  },
  AvgDialog_123119_Content_8 = {
    Text = "Salvador, deine Fähigkeit ist die Grundlage, um in dem dichten Nebel sicher zu bleiben, und %player%, offensichtlich ist auch dein Silberschlüssel sehr wichtig."
  },
  AvgDialog_123119_Content_80 = {
    Text = "Du, Kerl, ich sollte nicht erwarten, dass du aufhörst, diese langweilige Welt zu retten."
  },
  AvgDialog_123119_Content_81 = {
    Text = "Um andere zu retten, so etwas zu opfern... so etwas..."
  },
  AvgDialog_123119_Content_82 = {
    Text = "Mouchette konnte nicht mehr weitersprechen, denn weder Wut noch Zorn halfen mehr."
  },
  AvgDialog_123119_Content_83 = {
    Text = "%player% ist tatsächlich Mouchettes Freund, aber Mouchette ist nur ein Vorbeigehender in dieser Welt."
  },
  AvgDialog_123119_Content_84 = {
    Text = "Was die beiden trennt, ist nicht nur eine \"Dimension\", sondern auch zwei völlig unterschiedliche \"Welten\""
  },
  AvgDialog_123119_Content_85 = {
    Text = "Eigentlich ist mein Traum, mit den Menschen, die ich liebe, gemütlich am Kamin zu sitzen und unser wertloses Leben zu verschwenden."
  },
  AvgDialog_123119_Content_86 = {
    Text = "Der Schnee draußen fällt langsam, Jahr für Jahr, bis wir unser Leben aushauchen. Dann wird auf meinem Grabstein stehen: {Male=er,Female=sie} war ein langes und glückliches Nichts."
  },
  AvgDialog_123119_Content_87 = {
    Text = "Bis heute hat sich mein Traum auch nie verändert."
  },
  AvgDialog_123119_Content_88 = {
    Text = "Dann geh und verwirkliche diesen Traum, was macht es schon, wenn die Welt untergeht? Diese langweilige Welt, was macht es schon, selbst wenn sie zerstört wird!?"
  },
  AvgDialog_123119_Content_89 = {
    Text = "Es ist besser, als mit einem ewigen Bedauern zurückzubleiben, für immer allein in diesem gottverlassenen Ort gefangen zu sein!"
  },
  AvgDialog_123119_Content_9 = {
    Text = "Wenn dir etwas zustößt, kann niemand das Problem lösen."
  },
  AvgDialog_123119_Content_90 = {
    Text = [[
Das Lichtpunkt lachte erneut leise, doch Mouchette konnte bereits nicht mehr unterscheiden, ob in dieser Stimme Freude lag oder nicht.
Denn ihr Herz war voller Bitterkeit.]]
  },
  AvgDialog_123119_Content_91 = {
    Text = "Ich möchte diesen Traum auch verwirklichen, ich möchte ihn wirklich sehr, aber..."
  },
  AvgDialog_123119_Content_92 = {
    Text = "In dieser grausamen Welt treffen wir immer einige “Wahlen“, Entscheidungen, die wir vielleicht nicht einmal selbst verstehen können."
  },
  AvgDialog_123119_Content_93 = {
    Text = "Vielleicht ist es nicht völlig unverständlich. Obwohl ich keinen dampfenden Haselnuss-Kava-Tee hatte, habe ich meine eigenen Favoriten."
  },
  AvgDialog_123119_Content_94 = {
    Text = "Murphys kleiner Kuchen, Liz' Tanz und sogar die zusätzlichen Hausaufgaben, die Doll jedes Mal aufgab, erscheinen jetzt voller Spaß..."
  },
  AvgDialog_123119_Content_95 = {
    Text = "Genug, hör auf zu reden. Du bist einfach hoffnungslos..."
  },
  AvgDialog_123119_Content_96 = {
    Text = "Mouchette! Mouchette!"
  },
  AvgDialog_123119_Content_97 = {
    Text = "Plötzlich ertönte eine Stimme in Mouchettes Kopf. Und sie erkannte die Person sofort."
  },
  AvgDialog_123119_Content_98 = {
    Text = "Nachdem sie die Kämpfe und Opfer von “{Male=er,Female=sie}“ gesehen hat, um die Welt zu retten, denkt sie, dass sie diese Stimme und diese Person nur schwer vergessen kann."
  },
  AvgDialog_123119_Content_99 = {
    Text = "Halt durch, ich und Salvador werden dich bald retten! Das habe ich versprochen."
  },
  AvgDialog_123120_Content_1 = {
    Text = "Das Selbstopfer"
  },
  AvgDialog_123120_Content_10 = {
    Text = "Vater Salvador...?"
  },
  AvgDialog_123120_Content_100 = {
    Text = "Ich weiß nicht, in welchem Ausmaß dieses verdammte Ding sich ausbreiten wird, wenn es wirklich so ist wie in meiner Welt..."
  },
  AvgDialog_123120_Content_101 = {
    Text = "Mouchette sprach nicht weiter, aber du verstanden ihren Subtext—"
  },
  AvgDialog_123120_Content_102 = {
    Text = "Die Nebelkatastrophe ist eine Katastrophe, die eine ganze Welt betreffen kann."
  },
  AvgDialog_123120_Content_103 = {
    Text = "Es muss um jeden Preis beendet werden, dieses Ritual...<Shake:Salvador!>"
  },
  AvgDialog_123120_Content_104 = {
    Text = "Ich bin hier. Ich werde eure Sicherheit gewährleisten... und auch diesen Verirrten die wahre Erlösung bringen..."
  },
  AvgDialog_123120_Content_105 = {
    Text = "Dann erschien plötzlich ein warmes, sanftes Licht auf Salvador, das sich bis zu dir und Mouchette ausbreitete und die Schäden der Nebelkatastrophe abgrenzte."
  },
  AvgDialog_123120_Content_106 = {
    Text = "Mouchette, um diesen Raumriss zu schließen, muss ich als Nächstes die Schwingwelle der psychischen Dimension messen und bestimmen. Den Kampf überlasse ich dir."
  },
  AvgDialog_123120_Content_107 = {
    Text = "Kampf? Kein Problem. Solange ich hier bin, wirst du keinen einzigen Haar verlieren!"
  },
  AvgDialog_123120_Content_108 = {
    Text = "So lange zurückgehalten, endlich kann ich mich auslassen——"
  },
  AvgDialog_123120_Content_109 = {
    Text = "Jeder liebt es, jung und alt!\n<Big:Shining☆Tornado——!!>"
  },
  AvgDialog_123120_Content_11 = {
    Text = "Salvador atmete still tief ein und ließ dann schwer aus."
  },
  AvgDialog_123120_Content_111 = {
    Text = "Eine Axt fliegt heraus, zerschlägt eine Reihe humanoider Nebelgestalten und schafft dir einen kurzen sicheren Weg, um der unbekannten Tür, die den dichten Nebel ständig ausstößt, näher zu kommen."
  },
  AvgDialog_123120_Content_112 = {
    Text = "Und du bedienst ständig das Messgerät, versuchst, die Schwingwellen aus verschiedenen Dimensionen einzufangen."
  },
  AvgDialog_123120_Content_113 = {
    Text = [[
Eine Minute verging still.
Zwei Minuten vergingen still.]]
  },
  AvgDialog_123120_Content_114 = {
    Text = "Dann kamen drei Minuten, fünf Minuten, zehn Minuten..."
  },
  AvgDialog_123120_Content_115 = {
    Text = "Der Schweiß tropft von deiner Stirn, du hast die Zeit noch nie so lang empfunden."
  },
  AvgDialog_123120_Content_116 = {
    Text = "Wie lange noch? Ich habe das Gefühl, dass diese Monster stärker geworden sind, man muss mehrere Schläge austeilen, um sie zu zerstreuen..."
  },
  AvgDialog_123120_Content_117 = {
    Text = "Das ist ein Zeichen dafür, dass eine andere Dimension versucht, in unsere Welt einzudringen und sie zu verschlingen, nicht wahr, bleicher Bote?"
  },
  AvgDialog_123120_Content_118 = {
    Text = "Ein weiterer Schweißtropfen fällt von deiner Stirn, und in deinem angespannten Zustand hast du sogar das Nicken vergessen."
  },
  AvgDialog_123120_Content_119 = {
    Text = "Schwingwelle... verändert sich ständig..."
  },
  AvgDialog_123120_Content_12 = {
    Text = "Keine Notwendigkeit mehr zu suchen, Vater White... ist direkt hier."
  },
  AvgDialog_123120_Content_120 = {
    Text = "Es könnte an dem dichten Nebel selbst liegen, oder an den Störungen durch die Seelen, die im Nebel gefangen sind... Ich brauche Zeit, um das zu überprüfen."
  },
  AvgDialog_123120_Content_121 = {
    Text = "Du hebst den Blick zum Himmel, und jetzt kannst du keine “Sterne“ mehr sehen. \n Die ganze Welt scheint nur noch aus dichtem Nebel zu bestehen und dem Dimensionstor, das unaufhörlich dichten Nebel ausstößt."
  },
  AvgDialog_123120_Content_122 = {
    Text = "Aber wir haben keine Zeit mehr."
  },
  AvgDialog_123120_Content_123 = {
    Text = "...Das ist absolut richtig."
  },
  AvgDialog_123120_Content_124 = {
    Text = "Du verstaust das Messgerät und hebst die Hand, um den Silberschlüssel zu greifen."
  },
  AvgDialog_123120_Content_125 = {
    Text = "Es sieht so aus, als müsste ich alles auf eine Karte setzen..."
  },
  AvgDialog_123120_Content_126 = {
    Text = "Der bleiche Bote, möchtest du verbinden...?"
  },
  AvgDialog_123120_Content_127 = {
    Text = "Salvador runzelte die Stirn und sah dich missbilligend an. Doch du schwiegst nur."
  },
  AvgDialog_123120_Content_128 = {
    Text = "Hey, hey, hier ist auch ein \"Gast aus einer anderen Welt\". Kannst du etwas sagen, das ich verstehen kann?"
  },
  AvgDialog_123120_Content_129 = {
    Text = "%player%s bedeutet... die Verbindung zu der unbekannten “Tür“ herzustellen, um die Schwingwelle der Dimension zu bestimmen."
  },
  AvgDialog_123120_Content_13 = {
    Text = "Der Hohepriester auf dem Altar... ist Pater White."
  },
  AvgDialog_123120_Content_130 = {
    Text = "Was? Das Ding ist sehr seltsam, wer weiß, welches Ergebnis es haben wird. Mach keine Dummheiten."
  },
  AvgDialog_123120_Content_131 = {
    Text = "Du hältst den Silberschlüssel fest und gehst mit einem schweren Ausdruck auf das unsichtbare Lichttor zu. In diesem Moment zählt die Aktion mehr als Worte."
  },
  AvgDialog_123120_Content_132 = {
    Text = "Ich bin wirklich beeindruckt von euch, die ihr denkt, dass diese langweilige Welt noch rettenswert ist..."
  },
  AvgDialog_123120_Content_133 = {
    Text = "Unerwartet hielt Mouchette dich auf. Ihr Gesichtsausdruck war komplex, als sie dich ansah, als ob sie dich sah, gleichzeitig jedoch durch dich hindurchsah und jemand anderen wahrnahm."
  },
  AvgDialog_123120_Content_134 = {
    Text = "Am Ende verwandelten sich alle Verwicklungen in ein Lächeln auf ihrem Gesicht, und Mouchette bemühte sich, ihre Stimme entspannt klingen zu lassen."
  },
  AvgDialog_123120_Content_135 = {
    Text = "Egal, wer könnte schon erwarten, dass ich die auffällige Vorhut des Ermittlungsteams bin, es ist nur natürlich, dass ich an der Spitze stürme——"
  },
  AvgDialog_123120_Content_136 = {
    Text = "Also, lass mich gehen."
  },
  AvgDialog_123120_Content_137 = {
    Text = "Mouchette sieht dich an, ihr Ausdruck ist ernst und entschlossen."
  },
  AvgDialog_123120_Content_138 = {
    Text = "Vom Eck des Käfigs aus ist dies das erste Mal, dass sie einen so ernsten Ausdruck gezeigt hat."
  },
  AvgDialog_123120_Content_14 = {Text = "Was?!"},
  AvgDialog_123120_Content_15 = {
    Text = "In Schock konntest du nicht anders, als dich zu White umzudrehen und den ehemaligen Priester der Lebenskirche, jetzt den Anführer eines Kultes, leidenschaftlich sprechen zu sehen."
  },
  AvgDialog_123120_Content_16 = {
    Text = "In diesem Moment haben wir mit Silber und Blut eine Wahl getroffen und werden dies niemals bereuen."
  },
  AvgDialog_123120_Content_17 = {
    Text = "Um in das “Reich der Stille ohne das Leid des Verschwindens“ zu gelangen, um uns in dieser brennenden Welt zu erlösen——"
  },
  AvgDialog_123120_Content_18 = {
    Text = "Um in das “Reich der Stille ohne das Leid des Verschwindens“ zu gelangen, um uns in dieser brennenden Welt zu erlösen——"
  },
  AvgDialog_123120_Content_19 = {
    Text = "Ein Dutzend oder mehr Gläubige der Sternen-Dämmerung schworen einstimmig—"
  },
  AvgDialog_123120_Content_2 = {
    Text = "<Shake:Diese Welt brennt, diese Welt bricht zusammen, diese Welt ist zum Untergang verurteilt.>"
  },
  AvgDialog_123120_Content_20 = {
    Text = "Ein Dutzend oder mehr Gläubige der Sternen-Dämmerung erhoben einstimmig ihre silberbeschichteten Dolche—"
  },
  AvgDialog_123120_Content_21 = {Text = "Hör auf!"},
  AvgDialog_123120_Content_22 = {
    Text = "In deinem Schrei sticht der silberbeschichtete Dolch gleichzeitig in das Herz des menschlichen Viehs, dringt tief ein und regt sich heftig."
  },
  AvgDialog_123120_Content_23 = {
    Text = "Blinder Blut strömte aus der Brust des Opfers und färbte den Altar rot."
  },
  AvgDialog_123120_Content_24 = {
    Text = "Mitten in einem Meer aus Blut trittst du aus den verborgenen Schatten hervor, starrst direkt auf Weiß und konfrontierst die Quelle all dieser Tragödie."
  },
  AvgDialog_123120_Content_25 = {
    Text = "Ein weiterer ahnungsloser Narr kommt, um das Ritual des Allvaters zu stoppen?"
  },
  AvgDialog_123120_Content_26 = {
    Text = "Ha, ihr wart gleichgültig, als die Katastrophe herabkam, und jetzt, da ich im Begriff bin, meine Brüder und Schwestern zur Erlösung zu führen, wagt ihr es, mich aufzuhalten—"
  },
  AvgDialog_123120_Content_27 = {
    Text = "Der Anführer der Sternen-Dämmerung lächelte verächtlich und sah euch an, dann weiteten sich seine Augen plötzlich und er erstarrte an Ort und Stelle."
  },
  AvgDialog_123120_Content_28 = {
    Text = "<Shake:Bischof Salvador!?>"
  },
  AvgDialog_123120_Content_29 = {
    Text = "Salvadors Ausdruck war in Dunkelheit gehüllt, und du bemerktest, dass sein hoher und schlanker Körper unter seinem weiten Gewand tatsächlich leicht zitterte."
  },
  AvgDialog_123120_Content_3 = {
    Text = "<Shake:Der einzige Weg zur Erlösung führt in das <Yellow:\"ruhige Reich ohne den Schmerz der Zerstreuung\">, das direkt über uns ist, im Universum, wo die Sterne leuchten.>"
  },
  AvgDialog_123120_Content_30 = {
    Text = "White... Mein verlorenes Kind..."
  },
  AvgDialog_123120_Content_31 = {
    Text = "Oh, ich verstehe, das Kind, das Eure Exzellenz, der Bischof, bis hierher gerettet hat, ist tatsächlich der Anführer eines Kultes! Wie interessant!"
  },
  AvgDialog_123120_Content_32 = {Text = "Mouchette!"},
  AvgDialog_123120_Content_33 = {
    Text = "Gut, gut, ich werde nichts sagen. Selbst wenn ich nichts sage, werden die Fakten sich nicht ändern, oder?"
  },
  AvgDialog_123120_Content_34 = {
    Text = "So wurde es still vor Ort, nur das Blut des Menschenopfers floss langsam über den Altar und durchtränkte den Boden."
  },
  AvgDialog_123120_Content_35 = {
    Text = "John, James, Anderson... sie waren alle deine Kollegen."
  },
  AvgDialog_123120_Content_36 = {
    Text = "Als Priester der Chantry des Lebens... solltest du verstehen, warum sie nach Hawick gekommen sind."
  },
  AvgDialog_123120_Content_37 = {
    Text = "...Natürlich verstehe ich."
  },
  AvgDialog_123120_Content_38 = {
    Text = "Weil ich einst mit edlen Idealen hierher kam, genau wie sie!"
  },
  AvgDialog_123120_Content_39 = {
    Text = "Whites Stimme wurde plötzlich aufgeregt, und er blickte eifrig zu Salvador, wie ein Kind, das nach Anerkennung sucht."
  },
  AvgDialog_123120_Content_4 = {
    Text = "<Shake:<Big:Finde es, umarme es, widme dich ihm! Nur dann werden unsere Leben die ewige Morgenröte willkommen heißen——>>"
  },
  AvgDialog_123120_Content_40 = {
    Text = "Und ich habe mein Versprechen erfüllt, indem ich den einzigen Weg gefunden habe, um meine Brüder und Schwestern zu retten."
  },
  AvgDialog_123120_Content_41 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_123120_Content_42 = {
    Text = "Der Tod ist nicht die Lehre des Allvaters, Weiß. Du bist vom Weg abgekommen."
  },
  AvgDialog_123120_Content_43 = {
    Text = "<Shake:Nein! Ich folge immer noch der Anleitung des Vatergottes!>"
  },
  AvgDialog_123120_Content_44 = {
    Text = "Der Allvater verkündet: <Italic: \"Wir sind alle seine Kinder, würdig seiner Liebe\">, <Italic: \"Liebt einander, wie ihr euch selbst liebt\">."
  },
  AvgDialog_123120_Content_45 = {
    Text = "Der Allvater rät <Italic:„Diejenigen unter euch, die edel sind, sollen meine Botschafter sein und meinen Willen ausführen, um das Leiden von dieser Erde zu beseitigen.“>."
  },
  AvgDialog_123120_Content_46 = {
    Text = "...Es ist nicht falsch. Das sind alles die Absichten des All-Vaters."
  },
  AvgDialog_123120_Content_47 = {
    Text = "Und ich habe es geschafft. Ich werde meine Brüder und Schwestern retten und das Leid, das ihnen auferlegt wurde, beseitigen."
  },
  AvgDialog_123120_Content_48 = {
    Text = "Ich werde sie aus diesem Land des Leidens führen und sie zum Morgen leiten, der unter den Sternen strahlt, zu dem—"
  },
  AvgDialog_123120_Content_49 = {
    Text = "<Yellow:<Big:„Das Reich der Stille ohne das Leid des Verschwindens“>>."
  },
  AvgDialog_123120_Content_5 = {
    Text = "In der Höhle voller Verfluchungszeichen hielt der Anführer der Sternen-Dämmerung eine leidenschaftliche Rede, und mit seinem letzten Wort wurden die Menschenopfer in die Mitte des Altars gezogen."
  },
  AvgDialog_123120_Content_50 = {
    Text = "Um in das “Reich der Stille ohne das Leid des Verschwindens“ zu gelangen, um uns in dieser brennenden Welt zu erlösen——"
  },
  AvgDialog_123120_Content_51 = {
    Text = "Um in das “Reich der Stille ohne das Leid des Verschwindens“ zu gelangen, um uns in dieser brennenden Welt zu erlösen——"
  },
  AvgDialog_123120_Content_52 = {
    Text = "In diesem Moment durchdrang ein kaltes Kichern die leidenschaftlichen und geordneten Rufe der Gläubigen wie ein scharfer Dolch."
  },
  AvgDialog_123120_Content_53 = {
    Text = "Ein ruhiges Reich ohne den Schmerz der Zerstreuung? Sprichst du von der Welt jenseits des Tores?"
  },
  AvgDialog_123120_Content_54 = {
    Text = "Was für ein Witz. Meine Welt ist nicht so wunderbar."
  },
  AvgDialog_123120_Content_55 = {
    Text = "Nebelkatastrophe, Antiquitäten, Asche, und verschiedene mutierte Monster, und egal, welches ihr trefft, es reicht für einen ganzen Krug."
  },
  AvgDialog_123120_Content_56 = {
    Text = "Also, redet nicht mehr von so etwas wie Erlösung, ihr opfert nur andere, um euer eigenes Leben zu retten."
  },
  AvgDialog_123120_Content_57 = {
    Text = "<Shake:So ist das nicht! Weil—>"
  },
  AvgDialog_123120_Content_58 = {
    Text = "White trat einen Schritt näher zu Mouchette und hob aufgeregt den silberbeschichteten Dolch in seiner Hand."
  },
  AvgDialog_123120_Content_59 = {
    Text = "Du schützt instinktiv Mouchette, aber der erwartete Schlag bleibt aus."
  },
  AvgDialog_123120_Content_6 = {
    Text = "Du versteckst dich in den Schatten nicht weit entfernt und zählst vorsichtig die Anzahl der Menschenopfer."
  },
  AvgDialog_123120_Content_60 = {
    Text = "Das Ziel des Dolches war von Anfang an sein Meister—"
  },
  AvgDialog_123120_Content_61 = {
    Text = "Blut spritzt aus Whites Herz, fließt und vermischt sich mit dem Blut der Menschenopfer auf dem blutroten Altar."
  },
  AvgDialog_123120_Content_62 = {
    Text = "<Shake:Jetzt... Silber und Blut sind genug...>"
  },
  AvgDialog_123120_Content_63 = {
    Text = "Mit Whites Flüstern brach ein unsichtbarer Aufprall vom Altar aus."
  },
  AvgDialog_123120_Content_64 = {
    Text = "Das Blut, das auf der Oberfläche des Altars floss, begann sich zu winden und zu steigen, zusammen mit dem Körper des Opfers, der in die Luft schwebte."
  },
  AvgDialog_123120_Content_65 = {
    Text = "<Shake:Ah ah ah——Bischof Salvador...>"
  },
  AvgDialog_123120_Content_66 = {
    Text = "<Shake:Siehst du... ich habe mich nicht... von meinem... Versprechen an den All-Vater... abgewandt...>"
  },
  AvgDialog_123120_Content_67 = {
    Text = "White schrie, sein sterbender Körper zuckte unaufhörlich, während das Silber und das Blut in ihm von einer unsichtbaren Kraft ausgepresst wurden und seltsame Muster am Himmel zeichneten."
  },
  AvgDialog_123120_Content_68 = {
    Text = "<Shake:Mein Bischof, ich weiß, dass ich gesündigt habe... Ich bin bereit, die Sünden zu tragen, zusammen mit ihnen.>"
  },
  AvgDialog_123120_Content_69 = {
    Text = "<Shake:Aber ich bereue niemals... denn ich habe in diesem leidvollen Land... meine Brüder und Schwestern gerettet...>"
  },
  AvgDialog_123120_Content_7 = {
    Text = "John, James, Anderson... sie sind alle hier."
  },
  AvgDialog_123120_Content_70 = {
    Text = "Weißes Augenmerk war auf Salvador gerichtet. Und Salvador, der Bischof, der sich einst der Pflege von ihm gewidmet hatte, zog langsam das heilige Symbol des Allvaters in die Luft."
  },
  AvgDialog_123120_Content_71 = {
    Text = "Die Hand, die mit dem heiligen Symbol markiert war, zitterte und unterdrückte den Drang zu \"segnen\". Denn Salvador wusste, dass das verlorene Kind seine eigene Wahl getroffen hatte."
  },
  AvgDialog_123120_Content_72 = {
    Text = "Ich stimme deiner Vorgehensweise immer noch nicht zu, White, aber du setzt die Lehre des Allvaters in die Tat um. Also..."
  },
  AvgDialog_123120_Content_73 = {
    Text = "Möge der All-Vater dir vergeben, mögest du... in die Arme des All-Vaters zurückkehren... aus dem Leiden entkommen und Erlösung erlangen..."
  },
  AvgDialog_123120_Content_74 = {
    Text = "Salvador seufzte und sprach sein letztes Gebet."
  },
  AvgDialog_123120_Content_75 = {
    Text = "Aber Weiß konnte nichts mehr hören. \n Sein Ausdruck schwankte zwischen einem seligen Lächeln und extremem Schmerz, sein Herzschlag hörte auf."
  },
  AvgDialog_123120_Content_76 = {
    Text = "Und dann begann das in der Luft schwebende Silber und Blut plötzlich zu brodeln, wie unzählige kochende “Sterne“, die den Nachthimmel erleuchteten."
  },
  AvgDialog_123120_Content_77 = {
    Text = "In diesem blendenden und majestätischen Licht reorganisieren sich unzählige unbekannte Lichtflecken und bilden ein unsichtbares Tor, dessen Ziel unbekannt ist."
  },
  AvgDialog_123120_Content_78 = {
    Text = "Ist das das, was sie das „Tor“ nennen?"
  },
  AvgDialog_123120_Content_79 = {
    Text = "Kann ich damit in meine eigene Welt zurückkehren?"
  },
  AvgDialog_123120_Content_8 = {
    Text = "Also, brauchen wir nur Pater White...?"
  },
  AvgDialog_123120_Content_80 = {
    Text = "Es ist schwer zu sagen. Theoretisch können wir durch mehrmaliges Simulieren der gleichen Schwingwelle die gleiche Dimension verbinden, aber in der Praxis können leicht unerwartete Ereignisse auftreten."
  },
  AvgDialog_123120_Content_81 = {
    Text = "Insbesondere bei diesem Opferritual, das voller Variablen ist und zu weiteren Problemen führen kann—"
  },
  AvgDialog_123120_Content_82 = {
    Text = "Warte, geh dort nicht hin!"
  },
  AvgDialog_123120_Content_83 = {
    Text = "Du erhöhst deine Stimme, um die Kultanhänger zu stoppen, die einheitlich auf das immaterielle Tor zusteuern, aber sie scheinen dich nicht zu hören und schreiten in ruhigem Tempo weiter."
  },
  AvgDialog_123120_Content_84 = {
    Text = "Um in das “Reich der Stille ohne das Leid des Verschwindens“ zu gelangen, um uns in dieser brennenden Welt zu erlösen——"
  },
  AvgDialog_123120_Content_85 = {
    Text = "Um in das “Reich der Stille ohne das Leid des Verschwindens“ zu gelangen, um uns in dieser brennenden Welt zu erlösen——"
  },
  AvgDialog_123120_Content_86 = {
    Text = "Endlich hob der erste Gläubige die Hand, berührte das unsichtbare Tor und trat in die neue Welt ein, nach der er sich sehnte."
  },
  AvgDialog_123120_Content_87 = {
    Text = "<Shake:Ahhhhh——>"
  },
  AvgDialog_123120_Content_88 = {
    Text = "In verzweifelten Schreien begannen die Hände der Gläubigen, die das Lichttor berührten, sich zu verzerren und zu schmelzen, während sie in dem starken Licht verschwanden, das plötzlich aus dem unsichtbaren Tor strömte."
  },
  AvgDialog_123120_Content_89 = {
    Text = "Daraufhin strömte der endlose dichte Nebel aus dem unsichtbaren Tor und verschlang das Fleisch und die Seelen der Gläubigen, während er diejenigen, die nach den Sternen strebten, zu einem Teil der “Sterne“ machte."
  },
  AvgDialog_123120_Content_9 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_123120_Content_90 = {
    Text = "Der speziell angefertigte Kommunikator beginnt wieder, ein fehlerhaftes Stromgeräusch von sich zu geben und spielt das vertraute Flüstern der Sterbenden ab."
  },
  AvgDialog_123120_Content_91 = {
    Text = "@2I... speichern @2..."
  },
  AvgDialog_123120_Content_92 = {
    Text = "Speichern @2... @2 mir..."
  },
  AvgDialog_123120_Content_93 = {
    Text = "Das ist... <Shake:Das Ritual ist schiefgegangen!>"
  },
  AvgDialog_123120_Content_94 = {
    Text = "Salvador, pass auf die Monster im Nebel auf!"
  },
  AvgDialog_123120_Content_95 = {
    Text = "Kaum waren die Worte gefallen, formierten sich aus dem dichten Nebel unzählige humanoide Nebelgestalten, die brüllend auf euch zukamen."
  },
  AvgDialog_123120_Content_96 = {
    Text = "Die Dinge werden endlich interessant."
  },
  AvgDialog_123120_Content_97 = {
    Text = "Mouchette——"
  },
  AvgDialog_123120_Content_98 = {
    Text = "Okay, ich sage nichts mehr, aber ich muss dich daran erinnern, dass sich die Nebelkatastrophe weiter ausbreitet."
  },
  AvgDialog_123120_Content_99 = {
    Text = "... bleicher Bote, eben konnte ich die Umgebung noch klar sehen, jetzt kann ich sie gar nicht mehr erkennen."
  },
  AvgDialog_123121_Content_1 = {
    Text = "Erloschene Sterne"
  },
  AvgDialog_123121_Content_10 = {
    Text = "Mit deiner Stärke solltest du dich definitiv nicht von ein paar erbärmlichen Kultanhängern einsperren lassen."
  },
  AvgDialog_123121_Content_11 = {
    Text = "Und ich denke, wir beide haben bemerkt, dass diese Dame mehrfach nach der Uhrzeit der Zeremonie gefragt hat, und ihr Ausdruck... ist eindeutig einer der Vorfreude."
  },
  AvgDialog_123121_Content_12 = {
    Text = "Ah, ich habe mich also an diesen Stellen verraten... das war unachtsam."
  },
  AvgDialog_123121_Content_13 = {
    Text = "Also, wer bist du eigentlich? Was ist das für ein Ritual? Was weißt du darüber?"
  },
  AvgDialog_123121_Content_14 = {
    Text = "Mouchette zeigte ein gleichgültiges Lächeln und antwortete mit einer Gegenfrage—"
  },
  AvgDialog_123121_Content_15 = {
    Text = "Was ist mit euch? Warum seid ihr an diesen Ort gekommen, an dem die weltliche Ordnung vollständig zusammengebrochen ist und nur noch langweilige Glaubenssätze übrig sind?"
  },
  AvgDialog_123121_Content_16 = {
    Text = "Salvador verfolgte die Beleidigung gegen den Glauben an Mouchettes Worte nicht weiter und zeigte nur einen mitleidigen Blick."
  },
  AvgDialog_123121_Content_17 = {
    Text = "Ich komme zur Erlösung."
  },
  AvgDialog_123121_Content_18 = {
    Text = "Erlösung? Wen erlösen? Diese Menschenopfer? Mit Verlaub, manchmal ist ein schneller Tod besser als ein schmerzhaftes Leben."
  },
  AvgDialog_123121_Content_19 = {
    Text = "insbesondere in einer so... äh, aufregenden und unterhaltsamen Welt."
  },
  AvgDialog_123121_Content_2 = {
    Text = "Nachdem ihr ein Signal an das Heilige Siegel des Lebens gesendet habt, wart ihr und Salvador draußen vor der Höhle auf das seltsame Mädchen, das sich \"Mouchette\" nennt"
  },
  AvgDialog_123121_Content_20 = {
    Text = "Der Segen des Allvaters wird in jede Ecke verbreitet, die nach Erlösung dürstet."
  },
  AvgDialog_123121_Content_21 = {
    Text = "Diese Gefangenen rufen nach mir und der Kirche des Lebens um Hilfe in ihrem Leiden, und wir werden ihren Bitten sicherlich nachkommen."
  },
  AvgDialog_123121_Content_22 = {
    Text = "Als All-Vaters Stellvertreter werde ich mein Bestes tun, um das Leiden von dieser Erde zu beseitigen."
  },
  AvgDialog_123121_Content_23 = {
    Text = "Salvador senkte den Kopf und faltete fromm die Hände zur Ehrerbietung.\nDaraufhin antwortete ihm Mouchettes leises Lachen."
  },
  AvgDialog_123121_Content_24 = {
    Text = "Ich schätze, ihr seid alle die Art von guten Menschen im weltlichen Sinne, die an langweilige Phrasen wie Liebe die Menschen, und sie werden dich lieben glauben, oder?"
  },
  AvgDialog_123121_Content_25 = {
    Text = "Deshalb hast du mir so leicht geglaubt und bist mir hierher gefolgt..."
  },
  AvgDialog_123121_Content_26 = {
    Text = "Es ist so naiv, dass es Kopfschmerzen bereitet."
  },
  AvgDialog_123121_Content_27 = {
    Text = "Du kannst nicht erkennen, ob Mouchettes Ausdruck eine Hänselei oder Nostalgie ist, da ein Hauch von Nebel, der aus dem Nichts herüberweht, ihr Gesicht verdeckt."
  },
  AvgDialog_123121_Content_28 = {
    Text = "Du liegst falsch, wir wollen nur nicht böswillig über einen Fremden spekulieren."
  },
  AvgDialog_123121_Content_29 = {
    Text = "Ach, es ist egal, denn ihr versteht überhaupt nichts..."
  },
  AvgDialog_123121_Content_3 = {
    Text = "Und als Mouchette am Rand deines Blickfelds erschien, hatte sie unerwartet eine stilvolle Axt in der Hand."
  },
  AvgDialog_123121_Content_30 = {
    Text = "Gerade in diesem Moment unterbrach ein plötzliches Geräusch eines Schalters die Worte von Mouchette."
  },
  AvgDialog_123121_Content_31 = {
    Text = "Der Kommunikator erkannte spirituelle Schwankungen... Die Quelle ist... Nebel?!"
  },
  AvgDialog_123121_Content_32 = {
    Text = "Unbemerkt setzte sich der Nebelschleier weiter in Bewegung und verdeckte nicht nur den Großteil von Mouchettes Figur, sondern auch die umliegende Landschaft."
  },
  AvgDialog_123121_Content_33 = {
    Text = "Geistige Welle? So erklärt ihr also die “Nebelkatastrophe“..."
  },
  AvgDialog_123121_Content_34 = {
    Text = "\"Nebelkatastrophe\"?"
  },
  AvgDialog_123121_Content_35 = {
    Text = "Natürlich wird es in dieser abgestürzten Welt so etwas Interessantes nicht geben, es kommt von mir —"
  },
  AvgDialog_123121_Content_36 = {
    Text = "Aus <Yellow:meiner Welt>."
  },
  AvgDialog_123121_Content_37 = {
    Text = "Deine Welt...?"
  },
  AvgDialog_123121_Content_38 = {
    Text = "Diese Narren der Morgenröte der Sterne haben die verbotene Tür geöffnet, die nicht geöffnet werden sollte."
  },
  AvgDialog_123121_Content_39 = {
    Text = "Dann misslang das Ritual mit einem „Knacken—“, und ließ nur mich, den Unglücklichen, und die verworrenen Dinge zurück—"
  },
  AvgDialog_123121_Content_4 = {
    Text = "Wie ist es? Sieht es nicht sehr schick aus?"
  },
  AvgDialog_123121_Content_40 = {
    Text = "Eine freundliche Erinnerung: Ihr könnt jetzt darüber nachdenken, wann ihr mit der Flucht beginnen wollt."
  },
  AvgDialog_123121_Content_41 = {
    Text = "Sie? Flucht?"
  },
  AvgDialog_123121_Content_42 = {
    Text = "Hmpf☆Hmpf, die kleinen Kerle im Nebel kommen gleich——"
  },
  AvgDialog_123121_Content_43 = {
    Text = "Viel Spaß euch."
  },
  AvgDialog_123121_Content_44 = {
    Text = "Während sie sprach, zog sich Mouchette zurück und verbarg sich im dichten Nebel, nur die Stimme schwebte immer weiter in der dichten Nebel."
  },
  AvgDialog_123121_Content_45 = {
    Text = "Also, danke für eure Hilfe. Ich schulde euch einen Gefallen, also müsst ihr mir diesmal genug Zeit kaufen~"
  },
  AvgDialog_123121_Content_46 = {
    Text = "...Mouchette, warte!?"
  },
  AvgDialog_123121_Content_47 = {
    Text = "Du willst sie aufhalten, aber der dichte Nebel lässt dich völlig ratlos, wo du mit dem Verfolgen anfangen sollst."
  },
  AvgDialog_123121_Content_48 = {
    Text = "Du denkst einen Moment nach, ergreifst den Silberschlüssel und bereitest dich darauf vor, \"Geisterverfolgung\" zu aktivieren, als das Kommunikationsgerät erneut ein Geräusch von sich gibt."
  },
  AvgDialog_123121_Content_49 = {
    Text = "Es ist ein schrilles Geräusch von fehlerhaftem Strom, das im ständig sich bewegenden dichten Nebel immer lauter und klarer wird."
  },
  AvgDialog_123121_Content_50 = {
    Text = "@2I... speichern @2..."
  },
  AvgDialog_123121_Content_51 = {Text = "...!?"},
  AvgDialog_123121_Content_52 = {
    Text = "Salvador, hast du es gehört?"
  },
  AvgDialog_123121_Content_53 = {
    Text = "Klingt das nach... der Stimme eines Menschen?"
  },
  AvgDialog_123121_Content_54 = {
    Text = "Nachdem du das gehört hast, nimmst du den Kommunikator und wartest auf das nächste Geräusch, und der Kommunikator antwortet——"
  },
  AvgDialog_123121_Content_55 = {
    Text = "Ein Schrei der Verzweiflung, der ausreicht, um das Trommelfell zu durchbohren, dringt wie eine Klinge in deinen Kopf und lässt dich schwindelig werden."
  },
  AvgDialog_123121_Content_56 = {
    Text = "Währenddessen strömen aus dem dichten Nebel unzählige humanoide Nebelgestalten hervor und stürzen heulend auf dich und Salvador zu."
  },
  AvgDialog_123121_Content_57 = {Text = "Vorsicht!"},
  AvgDialog_123121_Content_58 = {
    Text = "Die Steinplatte durchquert den dichten Nebel, zerstreut die aus Nebel bestehenden Monster, doch das durchdringende Klagegeschrei bleibt bestehen, unaufhörlich, und trifft deine Seele."
  },
  AvgDialog_123121_Content_59 = {
    Text = "Das Blut fließt ununterbrochen aus deiner Nase und spritzt auf den Boden, aber du kannst wegen Schwindel nichts erkennen."
  },
  AvgDialog_123121_Content_6 = {
    Text = "Mo Xia schwang die Axt ein paar Mal, ihre Bewegungen waren sauber und schnell, als ob diese riesige Waffe ein Teil von ihr wäre."
  },
  AvgDialog_123121_Content_60 = {
    Text = "Dein Geist scheint den Körper zu verlassen, sich ständig auszubreiten, in einem unsichtbaren und chaotischen Zustand, und berührt das Dorf, in dem du dich befindest."
  },
  AvgDialog_123121_Content_61 = {
    Text = "Du spürst es – der allgegenwärtige dichte Nebel verschlingt ungeniert das Land, die Gebäude und jede Spur menschlichen oder nicht-menschlichen Lebens."
  },
  AvgDialog_123121_Content_62 = {
    Text = "Und in diesem grenzenlosen dichten Nebel brennen unzählige Sterne still und kalt, offensichtlich schon seit langer Zeit tot."
  },
  AvgDialog_123121_Content_63 = {Text = "%player%!"},
  AvgDialog_123121_Content_64 = {
    Text = "Salvadores Stimme hallt in deinem Kopf wider, doch die Verzweiflung und der Schmerz, die aus den Tiefen deiner Seele strömen, lassen dich regungslos."
  },
  AvgDialog_123121_Content_65 = {
    Text = "@2I... speichern @2..."
  },
  AvgDialog_123121_Content_66 = {
    Text = "Speichern @2... @2 mir..."
  },
  AvgDialog_123121_Content_67 = {
    Text = "Die verstorbenen Sterne umgeben dich mit unendlicher Verzweiflung und Schmerz, schmelzen hartnäckig an dir, verfallen dir und wollen dich in den ewigen Schlaf ziehen."
  },
  AvgDialog_123121_Content_68 = {
    Text = "...Ich kann einfach nicht so einschlafen, Thrall..."
  },
  AvgDialog_123121_Content_69 = {
    Text = "Sal...vador... hilf mir..."
  },
  AvgDialog_123121_Content_7 = {
    Text = "Als dir das klar wurde, hast du einen Angriff gestartet."
  },
  AvgDialog_123121_Content_70 = {
    Text = "In diesem Moment strahlte ein sanftes Licht in deine Welt, wie die wärmste Sonne, die dich sanft umhüllte und alle Kälte sowie das Gefühl des Todes vertieb."
  },
  AvgDialog_123121_Content_71 = {
    Text = "Das ist der Glanz von Salvador."
  },
  AvgDialog_123121_Content_72 = {
    Text = "Er hat deine Bitte gehört."
  },
  AvgDialog_123121_Content_73 = {
    Text = "Er hat auf deine Anfrage geantwortet."
  },
  AvgDialog_123121_Content_74 = {
    Text = "<Shake:Hust hust...>"
  },
  AvgDialog_123121_Content_75 = {
    Text = "Mit Salvadors Hilfe bist du schließlich aus diesem schwindelerregenden Nebel erwacht. Du hast nach Luft geschnappt und das Gefühl, einen Teil deiner Vernunft zurückgewonnen zu haben."
  },
  AvgDialog_123121_Content_76 = {
    Text = "Salvador, du kannst aufhören zu segnen, mir geht es schon viel besser."
  },
  AvgDialog_123121_Content_77 = {
    Text = "Salvador nickte und widmete sich ganz dem Kampf gegen die unbekannte Bedrohung im Nebel."
  },
  AvgDialog_123121_Content_78 = {
    Text = "Diese Monster im Nebel sterben nicht. Selbst wenn sie zerstreut werden, erscheinen sie schnell wieder."
  },
  AvgDialog_123121_Content_79 = {
    Text = "Egal, solange dieser Nebel existiert, werden diese Monster ewig leben."
  },
  AvgDialog_123121_Content_8 = {
    Text = "Mouchette, du bist freiwillig von den Kultanhängern gefangen genommen worden."
  },
  AvgDialog_123121_Content_80 = {
    Text = "Vater Salvador, glaubst du... dass das, was Mouchette gesagt hat, wahr ist?"
  },
  AvgDialog_123121_Content_81 = {
    Text = "Von dem Moment an, als wir uns trafen, blieb das Seelenfeuer von Lady Mouchette konstant. Meiner Ansicht nach hat sie weder das Verhalten einer Lügnerin noch das Motiv zu lügen gezeigt."
  },
  AvgDialog_123121_Content_82 = {
    Text = "Nun, ich habe einige Hypothesen. Wir müssen jedoch zuerst Mouchette finden."
  },
  AvgDialog_123121_Content_83 = {
    Text = "Ich respektiere deine Entscheidung, bleicher Bote."
  },
  AvgDialog_123121_Content_84 = {
    Text = "Mach dir keine Sorgen um die Monster im Nebel, ich werde für deine Sicherheit sorgen."
  },
  AvgDialog_123121_Content_85 = {
    Text = "Du schaust Salvador dankbar an und bewegst dann deine Hand zum Silberschlüssel."
  },
  AvgDialog_123121_Content_86 = {
    Text = "Blut fließt erneut von deiner Wange, aber du bleibst unberührt, die schrecklichen Vermutungen während des Schwindels haben deinen gesamten Verstand eingenommen."
  },
  AvgDialog_123121_Content_87 = {
    Text = "@2I... speichern @2..."
  },
  AvgDialog_123121_Content_88 = {
    Text = "Speichern @2... @2 mir..."
  },
  AvgDialog_123121_Content_89 = {
    Text = "Schließlich, als der Kommunikator erneut Geräusche von sich gab, durchquerteest du unzählige kalte, tote Sterne und berührtest den Geist von Mouchette."
  },
  AvgDialog_123121_Content_9 = {
    Text = "Hä? Machst du Witze? Eine normale Person würde sich nicht freiwillig zu einem Gefangenen eines Kults machen, eingesperrt in einem Käfig ohne Essen oder Wasser."
  },
  AvgDialog_123122_Content_1 = {
    Text = "Durch deinen Blick"
  },
  AvgDialog_123122_Content_10 = {
    Text = "Ich bin gerade beschäftigt und habe keine Zeit, um langweilige Rollenspiele zu spielen, geschweige denn Interesse daran, die Rolle der gebildeten Tochter zu spielen."
  },
  AvgDialog_123122_Content_11 = {
    Text = "Du verstehst diese Welt nicht, noch kennst du die wahren Kosten und Auswirkungen des Rituals der Morgenröte der Sterne."
  },
  AvgDialog_123122_Content_12 = {
    Text = "Mit anderen Worten, die Gefangenen, mit denen du gerade eingesperrt warst, sind alle wesentliche Opfer für das nächste Ritual."
  },
  AvgDialog_123122_Content_13 = {
    Text = "Außerdem, selbst wenn das Ritual erneut abgehalten wird, weißt du nicht, ob sich die Tore zwischen den beiden Welten wieder öffnen und ob du durch sie in deine eigene Welt zurückkehren kannst."
  },
  AvgDialog_123122_Content_14 = {
    Text = "Mouchettes Bewegung kam zum Stillstand, und dann biss sie sich fest auf die Lippe."
  },
  AvgDialog_123122_Content_15 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_123122_Content_16 = {
    Text = "Kind, ich weiß, dass du nicht freiwillig in diese grausame Welt gekommen bist, und ich verstehe dein Verlangen, zurückzukehren."
  },
  AvgDialog_123122_Content_17 = {
    Text = "Wir hoffen nur, dir helfen zu können, damit du nicht auf den falschen Weg gerätst."
  },
  AvgDialog_123122_Content_18 = {
    Text = "Du sagst, dass es ein Irrweg ist, wenn ich durch das Ritual der Sternen-Dämmerung in meine eigene Welt zurückkehren möchte?"
  },
  AvgDialog_123122_Content_19 = {
    Text = "Mouchettes kürzlich weich gewordene Haltung schien wieder zu verhärten, ihr Ton war von scharfer Ironie durchzogen."
  },
  AvgDialog_123122_Content_2 = {
    Text = "Wie habt ihr mich alle gefunden?!"
  },
  AvgDialog_123122_Content_20 = {
    Text = "Der dichte Nebel um uns herum beginnt zu brodeln und zu toben."
  },
  AvgDialog_123122_Content_21 = {
    Text = "Was ist also der rechte Weg? Wer bestimmt, was der rechte Weg ist? Du oder dein Gott?"
  },
  AvgDialog_123122_Content_22 = {
    Text = "Die Maske ist endlich gefallen. Mouchette verbirgt ihre Verachtung und Missachtung für Salvador nicht mehr."
  },
  AvgDialog_123122_Content_23 = {
    Text = "Was spielt es für eine Rolle, ob du richtig oder falsch geurteilt hast? Ich sehe diese Welt als noch öder und trostloser als Taimuran."
  },
  AvgDialog_123122_Content_24 = {
    Text = "Wo ist der \"Allvater\", von dem du sprichst, wenn diese Menschen leiden?"
  },
  AvgDialog_123122_Content_25 = {
    Text = "Der dichte Nebel brodelt immer heftiger und verdeckt Mouchettes Gesicht sowie Salvadors Ausdruck."
  },
  AvgDialog_123122_Content_26 = {
    Text = "Das Einzige, was du in diesem Nebel hören kannst, ist Salvadores Seufzer und die unheimlichen Geräusche, die das Herannahen von Gefahr ankündigen."
  },
  AvgDialog_123122_Content_27 = {Text = "Ich..."},
  AvgDialog_123122_Content_28 = {
    Text = "Reden Sie frei heraus, Priester, schließlich haben Sie auch nichts zu tun."
  },
  AvgDialog_123122_Content_29 = {
    Text = "Kaum hatte Mouchette ihre Worte ausgesprochen, brachen aus dem Nebel um euch unzählige humanoide Nebel hervor und kamen auf euch zu."
  },
  AvgDialog_123122_Content_3 = {
    Text = "Ist etwas mit dem Nebel gerade schiefgelaufen? Oder hast du auch die Fähigkeit, durch den Nebel zu sehen wie der Ermittler?"
  },
  AvgDialog_123122_Content_30 = {
    Text = "Aber Mouchettes Bewegungen waren schneller als die humanoiden Nebel. Als du sahst, dass sie erneut entkommen wollte, riefst du unwillkürlich."
  },
  AvgDialog_123122_Content_31 = {
    Text = "Salvador, halt sie auf!"
  },
  AvgDialog_123122_Content_4 = {
    Text = "Mouchettes Erstaunen währte nicht lange; im Handumdrehen wurde ihr Ausdruck ruhig."
  },
  AvgDialog_123122_Content_5 = {
    Text = "Du hast einige Mittel, um den Artefakten im Nebel zu entkommen. Aber—"
  },
  AvgDialog_123122_Content_6 = {
    Text = "<Big:<Shake:Stör mich nicht bei meiner Arbeit!>>"
  },
  AvgDialog_123122_Content_7 = {
    Text = "Mouchette sagte, indem sie die Axt fest umklammerte, ihr Blick war voller Wachsamkeit und Feindseligkeit."
  },
  AvgDialog_123122_Content_8 = {
    Text = "Mouchette, du musst das nicht tun, wir sind keine Feinde. Zumindest jetzt nicht."
  },
  AvgDialog_123122_Content_9 = {
    Text = "Aber bevor du deine Entscheidung triffst, habe ich einen Ratschlag, den ich dir unbedingt mitteilen muss."
  },
  AvgDialog_125040_Content_1 = {
    Text = "Die Überschwemmung des Heiligen Flusses hat Mythag unprecedented Probleme gebracht. Unerwartet ist Xus Zimmer zu einem der wenigen Orte geworden, an denen du Zuflucht suchen kannst."
  },
  AvgDialog_125040_Content_10 = {
    Text = "Ich kann eine Lüge, ein flüchtiger Gedanke sein, aber wenn es um mich selbst geht... ist es völlig langweilig."
  },
  AvgDialog_125040_Content_11 = {
    Text = "...Äh? Xu?"
  },
  AvgDialog_125040_Content_12 = {Text = "Fog."},
  AvgDialog_125040_Content_13 = {
    Text = "Dünner, gossamer-artiger Nebel wickelt sich schichtweise um dich."
  },
  AvgDialog_125040_Content_14 = {
    Text = "<Gray:Moment, warst du nicht unbeeindruckt? Haben wir nicht gerade geplaudert und Weiqi gespielt?! Warum sagen ihr Erwecker immer das eine und tut das andere?!>"
  },
  AvgDialog_125040_Content_15 = {
    Text = "Während ein flackernder goldener Phantom durch den Nachglühen weht, bindet eine samtartige Berührung deine Arme und deinen Rücken und leitet dich dazu an, den aus Nebel gewebten Schleier zu heben."
  },
  AvgDialog_125040_Content_16 = {
    Text = "Ah, weil ich wirklich, wirklich neugierig bin."
  },
  AvgDialog_125040_Content_17 = {
    Text = "Als sie mich berührten, berührten sie einen Phantasmus. Als sie mich ansahen, sahen sie durch mich hindurch, als ob sie das sahen, was sie \"dachten\", ihr Geliebter zu sein."
  },
  AvgDialog_125040_Content_18 = {
    Text = "Aber du bist anders. Hast du den Schatten von jemandem? Wenn du genau hinsiehst, wessen Gesicht wirst du unter meinem Fächer sehen...?"
  },
  AvgDialog_125040_Content_19 = {
    Text = "Der Nebel teilt sich, und unter dem Fächer berührt etwas Warmes sanft deine Nase. Die Federn auf der Schulter der Frau fallen und streifen sanft über deine unerklärlich zitternde Haut."
  },
  AvgDialog_125040_Content_2 = {
    Text = "Hat der Heilige Fluss dich überhaupt nicht beeinflusst?"
  },
  AvgDialog_125040_Content_20 = {
    Text = "<Gray:Großartig. Glühend heiß — noch einer, der vom Heiligen Fluss beeinflusst ist.>"
  },
  AvgDialog_125040_Content_21 = {
    Text = "Xu, wenn ich mich richtig erinnere, hast du stattdessen gesagt: \"keine Ablenkungen\"."
  },
  AvgDialog_125040_Content_22 = {
    Text = "In der Tat, im Fernen Osten, wenn ein Monarch wichtige Angelegenheiten mit jemandem zu besprechen hat, lädt er diese Person hinter den Vorhang ein, daher der Begriff – Gast im Theater."
  },
  AvgDialog_125040_Content_23 = {
    Text = "Für Frauen hat es jedoch eine andere Bedeutung, im Theater zu Gast zu sein."
  },
  AvgDialog_125040_Content_24 = {Text = "Tropf."},
  AvgDialog_125040_Content_25 = {
    Text = "Ein Tropfen Kerzenwachs fiel auf den Tisch und verstreute die Schachfiguren."
  },
  AvgDialog_125040_Content_26 = {
    Text = "Das Licht ist erloschen."
  },
  AvgDialog_125040_Content_27 = {
    Text = "Ich musste immer nur zur Seite treten, aber vielleicht kannst du mich endlich sehen."
  },
  AvgDialog_125040_Content_28 = {
    Text = "Nur du machst mich bereit, hinter dem Vorhang zu stehen und vielleicht dem wichtigsten Gast meines Lebens gegenüberzustehen. Wie könnte ich da irgendwelche „Ablenkungen“ haben?"
  },
  AvgDialog_125040_Content_29 = {
    Text = "Die Fesseln verschwinden, und diese alte und mysteriöse Gottheit hat dir eindeutig einen Ausweg gelassen."
  },
  AvgDialog_125040_Content_3 = {
    Text = "Ob es daran liegt, dass die Quelle der Macht von den drei Äonen kommt oder an meiner Fertigkeit im Umgang mit Vergnügen, ich scheine keine Ablenkungen zu haben."
  },
  AvgDialog_125040_Content_30 = {
    Text = "Und ihre Einladung, voller Freude, ist kaum hörbar und schwer von echt und falsch zu unterscheiden."
  },
  AvgDialog_125040_Content_31 = {
    Text = "Ich fiel ins dunkle Meer, suchte das Ufer, konnte es aber nicht finden..."
  },
  AvgDialog_125040_Content_4 = {
    Text = "Diese schönen Augen funkelten vor Freude, als mehrere weiße Figuren sanft auf das Schachbrett klopften. Ihre Besitzerin hatte großes Interesse daran, sich mit diesem alten Spiel aus dem Osten die Zeit zu vertreiben."
  },
  AvgDialog_125040_Content_5 = {
    Text = "Menschen sind eine seltsame Spezies; sie verlieren ihre Gelassenheit für flüchtige Freude, und sobald sie sie erlangen, zeigen sie sofort Desinteresse."
  },
  AvgDialog_125040_Content_6 = {
    Text = "Jahr für Jahr werden sie müde voneinander. Nur indem man Illusionen für sie webt, sie dazu bringt, Leben und Tod aufzugeben, ihre Herzen zu zerreißen und ihre Lebern herauszuschneiden, können sie niemals vergessen."
  },
  AvgDialog_125040_Content_7 = {
    Text = "Das flackernde Kerzenlicht umreißt die sitzende Gestalt der Frau auf dem Bett und wirft eine schwache und schattenhafte Silhouette."
  },
  AvgDialog_125040_Content_8 = {
    Text = "Der Himmel war irgendwann völlig dunkel geworden, und sie ließ ein leises Lachen hören."
  },
  AvgDialog_125040_Content_9 = {
    Text = "Gute Familien in das Gewerbe zu zwingen, @2 zu überzeugen, zu einem tugendhaften Leben zurückzukehren. Ich bin ziemlich gut darin, eine Geschichte zu weben, die halb wahr und halb falsch ist, und sie dann dieses Antlitz sehen zu lassen, das entweder Schuld oder unerwiderte Liebe trägt."
  },
  AvgDialog_126907_Content_1 = {
    Text = "Feuer der vergangenen Tage"
  },
  AvgDialog_126907_Content_10 = {
    Text = "Dann bitte gehen Sie voran."
  },
  AvgDialog_126907_Content_11 = {
    Text = "Elsas Augen funkelten, als sie dich herüberzog und in einem Augenblick den Tanz begann, der von dir geleitet werden sollte."
  },
  AvgDialog_126907_Content_12 = {
    Text = "Ihre Kraft ist so groß, dass sie dich fast hinauswirft, und in einem Aufruhr zieht sie dich mit purer Macht zurück."
  },
  AvgDialog_126907_Content_13 = {
    Text = "<Shake:Ja, es tut mir leid>, edler Herr, ich werde es beim nächsten Mal sicher besser kontrollieren..."
  },
  AvgDialog_126907_Content_14 = {
    Text = "Du fühlst dich wie ein Kreisel, der herumgeschwungen wird, endlos rotiert, und deine ohnehin schon unbeholfenen Tanzschritte erscheinen noch ungeschickter."
  },
  AvgDialog_126907_Content_15 = {Text = "Pfft."},
  AvgDialog_126907_Content_16 = {
    Text = "Als sie dein Peinlichkeit sieht, kann Ramona nicht anders, als leise zu lachen."
  },
  AvgDialog_126907_Content_17 = {
    Text = "Du triffst ihren Blick und spürst, wie ihre lächelnden Augen dir zuflüstern—"
  },
  AvgDialog_126907_Content_18 = {
    Text = "Lord Dexter, heute bist du dran."
  },
  AvgDialog_126907_Content_19 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_126907_Content_2 = {
    Text = "Auf der Tanzfläche drehen ein Jugendlicher und ein Mädchen in Schuluniformen sich anmutig. Die Musik fließt wie Wasser und webt durch ihre verschränkten Hände, die sanft gehobenen Röcke und die ausgetauschten Blicke."
  },
  AvgDialog_126907_Content_20 = {
    Text = "Als das Lied zu Ende ging, küsstest du hastig die Hand deiner Tanzpartnerin, um Abschied zu nehmen, und gingst direkt auf Ramona zu."
  },
  AvgDialog_126907_Content_21 = {
    Text = "Ich erinnere mich, dass Sie, Lord Dexter, als der eleganteste Professor in ganz Mythag bekannt sind, wenn es um das Gesellschaftstanz geht."
  },
  AvgDialog_126907_Content_22 = {
    Text = "Du durchsuchst deinen Kopf, um Lord Dexters geschmeidige und schlaue Antwort zu formulieren."
  },
  AvgDialog_126907_Content_23 = {
    Text = "Ich denke, wenn ein Wettbewerb \"Tanz mit Elsa\" stattfinden würde, wäre ich immer noch der Gewinner."
  },
  AvgDialog_126907_Content_24 = {
    Text = "Ramona wandte ihren Blick ab und schwenkte sanft das Weinglas in ihrer Hand."
  },
  AvgDialog_126907_Content_25 = {
    Text = "Elsa bewundert dich. Auch wenn dieser Tanz nicht perfekt ist, kann er als Erfüllung ihres Frühlingsfestwunsches betrachtet werden."
  },
  AvgDialog_126907_Content_26 = {
    Text = "Leider ist derjenige, der mit ihr tanzt, nicht der echte Lord Dexter."
  },
  AvgDialog_126907_Content_27 = {
    Text = "Was noch höllischer ist, ist, dass die Person, die sie kennt, selbst ohne deinen Besitzakt nicht der echte Lord Dexter ist."
  },
  AvgDialog_126907_Content_28 = {
    Text = "Aber das ist nicht das Thema, über das du sprechen möchtest."
  },
  AvgDialog_126907_Content_29 = {
    Text = "Ramona, hast du irgendwelche Wünsche für das Frühlingsfest?"
  },
  AvgDialog_126907_Content_3 = {
    Text = "Du bemerkst, dass Ramona allein an einem kleinen Tisch außerhalb der Tanzfläche steht und ein geheimnisvolles Getränk nippt."
  },
  AvgDialog_126907_Content_30 = {
    Text = "Hat sich das Rollenspiel geändert? Anstatt deine Dame und die Dame zu begrüßen, bist du gekommen, um nach deiner adoptierten Tochter zu sehen?"
  },
  AvgDialog_126907_Content_31 = {
    Text = "Ich sehe, du bist nicht tanzen gegangen; liegt es daran, dass du keinen Partner hast, den du magst?"
  },
  AvgDialog_126907_Content_32 = {
    Text = "Keine Mühe machen."
  },
  AvgDialog_126907_Content_33 = {
    Text = "Würdest du mir die Ehre erweisen, mit meinem einsamen alten Vater zu tanzen?"
  },
  AvgDialog_126907_Content_34 = {
    Text = "Ramona schweigt. Du weißt, dass sie in der Halle ihrer Gedanken nach Gründen sucht."
  },
  AvgDialog_126907_Content_35 = {
    Text = "Die Person, auf die du wartest, hofft ebenfalls, dass du diese Tanzaufforderung annimmst."
  },
  AvgDialog_126907_Content_36 = {
    Text = "Wie weißt du das?"
  },
  AvgDialog_126907_Content_37 = {
    Text = "Ich weiß es einfach."
  },
  AvgDialog_126907_Content_38 = {
    Text = "Eine noch längere Stille."
  },
  AvgDialog_126907_Content_39 = {
    Text = "Vergiss es, ich werde dir diesmal vertrauen."
  },
  AvgDialog_126907_Content_4 = {
    Text = "Während du darüber nachdenkst, aus welchem Grund du das Gespräch beginnen sollst, ertönt eine schüchterne Stimme neben dir."
  },
  AvgDialog_126907_Content_40 = {
    Text = "Sie betritt elegant die Tanzfläche, ihre zarten Finger ruhen auf deiner Handfläche."
  },
  AvgDialog_126907_Content_41 = {
    Text = "Komm schon, ich habe noch nicht mit dir getanzt."
  },
  AvgDialog_126907_Content_42 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_126907_Content_43 = {
    Text = "Ramonas Tanzschritte sind wie ihre Persönlichkeit — rational, zurückhaltend, präzise und akribisch."
  },
  AvgDialog_126907_Content_44 = {
    Text = "Du kannst dich ein wenig entspannen; es scheint, als würdest du die Tanzfläche wie ein Schlachtfeld behandeln."
  },
  AvgDialog_126907_Content_45 = {
    Text = "Und Sie könnten ein wenig ernster sein, edler Herr. Seit Sie mit dem Tanzen begonnen haben, sind Sie mir fast dreimal auf den Fuß getreten."
  },
  AvgDialog_126907_Content_46 = {
    Text = "Das ist nicht wie Lord Dexter, der sich seit Jahrzehnten in sozialen Kreisen bewegt."
  },
  AvgDialog_126907_Content_47 = {
    Text = "Vielleicht möchte ich manchmal eine andere Rolle spielen?"
  },
  AvgDialog_126907_Content_48 = {
    Text = "Ist das so?"
  },
  AvgDialog_126907_Content_49 = {
    Text = "Weißt du was? Du bist heute ein bisschen zu still."
  },
  AvgDialog_126907_Content_5 = {
    Text = "<Shake:<Small:LORD Dexter... darf ich mit Ihnen tanzen?>>"
  },
  AvgDialog_126907_Content_50 = {
    Text = "<LightGray:Ich dachte, ich hätte es ziemlich gut wiederhergestellt...>"
  },
  AvgDialog_126907_Content_51 = {
    Text = "Ist das so? Vielleicht liegt es daran, dass das Wetter zu kalt ist, was die Menschen den Wunsch zu reden verlieren lässt."
  },
  AvgDialog_126907_Content_52 = {
    Text = "Wenn es Lord Dexter wäre, würde er sagen: Es ist ziemlich tabu, mit seiner eigenen Adoptivtochter zu flirten, wissen Sie."
  },
  AvgDialog_126907_Content_53 = {
    Text = "<Yellow:Wer bist du eigentlich?>"
  },
  AvgDialog_126907_Content_54 = {
    Text = "Ramona, die Zeit, die wir zum Treffen haben, ist zu kurz; ich möchte nicht..."
  },
  AvgDialog_126907_Content_55 = {
    Text = "Ein leises Husten von Xu erreicht deine Ohren."
  },
  AvgDialog_126907_Content_56 = {
    Text = "Genug davon, schau!"
  },
  AvgDialog_126907_Content_59 = {
    Text = "In einem Augenblick schossen unzählige Feuerwerkskörper mit einem Zischen in den Himmel."
  },
  AvgDialog_126907_Content_6 = {
    Text = "Oh? Warum ist das so?"
  },
  AvgDialog_126907_Content_62 = {
    Text = "Am Kopf erblühen die blühenden Feuerbaumblüten."
  },
  AvgDialog_126907_Content_64 = {
    Text = "Genau wie am Tag der Schlüsselübergabe hast du Ramonas Hand genommen."
  },
  AvgDialog_126907_Content_66 = {
    Text = "Du schließt die Augen inmitten ihres erstaunten Ausdrucks."
  },
  AvgDialog_126907_Content_68 = {
    Text = "In der Dunkelheit hallen unzählige Stimmen der Freude und Vorfreude wider:"
  },
  AvgDialog_126907_Content_69 = {
    Text = "<Big:<Shake:“Jahreswechsel FestGlück!“>>"
  },
  AvgDialog_126907_Content_7 = {
    Text = "Sie weigern sich alle, mit mir zu tanzen... und sagen, sie fühlen, dass es gefährlich ist."
  },
  AvgDialog_126907_Content_70 = {
    Text = "Frohes Jahreswechsel Fest, Ramona."
  },
  AvgDialog_126907_Content_71 = {
    Text = "Mitternacht ist gekommen, der Wind heult, und all die Geschichten, die dir gehören sollten, entfernen sich von dir."
  },
  AvgDialog_126907_Content_72 = {
    Text = "Aber du weißt, der Tag des Wiedersehens ist nicht mehr weit entfernt."
  },
  AvgDialog_126907_Content_8 = {
    Text = "Aber keine Sorge! Ich werde sicherstellen, dass ich meine Kraft kontrolliere!"
  },
  AvgDialog_126907_Content_9 = {
    Text = "Dein Blick streift auf und ab über die zitternde kleine Gestalt."
  },
  AvgDialog_126908_Content_1 = {
    Text = "Dunkler Raum"
  },
  AvgDialog_126908_Content_10 = {
    Text = "Ihr Lächeln und ihre Gestalt verschwanden unklar und zerstreuten sich im Wind, der zu Asche wurde."
  },
  AvgDialog_126908_Content_11 = {
    Text = "Geh schon, hol dir deine Beute."
  },
  AvgDialog_126908_Content_12 = {
    Text = "Hinter dem Nebel und der Asche gibt es eine Tür—die zum Cockpit des Zuges führt."
  },
  AvgDialog_126908_Content_13 = {
    Text = "Keine Tricks, keine Geräte, keine unnötige Existenz."
  },
  AvgDialog_126908_Content_14 = {
    Text = "Es war nur eine gewöhnliche Tür, wie alle anderen auf der Welt, die die Funktion des „Eingangs und Ausgangs“ erfüllte und am Ende des Rätsels auf dich wartete."
  },
  AvgDialog_126908_Content_15 = {
    Text = "Du atmest tief ein, umklammerst den Silberschlüssel fest und drückst das Tor auf."
  },
  AvgDialog_126908_Content_16 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_126908_Content_17 = {
    Text = "<LightGray:Ich bin ein bisschen ungewohnt an die Abwesenheit von mehr Körpern oder sogar ein paar zerteilten Mitarbeitern.>"
  },
  AvgDialog_126908_Content_18 = {Text = "Hm?"},
  AvgDialog_126908_Content_19 = {
    Text = "Ein Wölkchen Nebel strömt vom Tisch herunter und entfaltet sanft ein Seidentuch, das sanft schimmert und nachdenklich die Worte von Londinium niederschreibt, die völlig im Widerspruch zu seinem Stil stehen."
  },
  AvgDialog_126908_Content_2 = {
    Text = "Wagen Nr. 1"
  },
  AvgDialog_126908_Content_20 = {
    Text = "Lieber Keeper:\n\nIch hoffe, dieser Brief erreicht dich wohlbehalten.\nJetzt, wo du hier angekommen bist, musst du das Geheimnis dieses Zuges entdeckt haben – es ist ein Künstliches Reich, das von N. erschaffen wurde. Die Konkubine in diesem Zug ist nun verstorben.\nIch habe euch alle über eure Ziele diskutieren gesehen. Winkle und Tinct, ihre Heimatstädte sind längst verschwunden; ich hatte ebenfalls ein Auge auf Miryam geworfen, aber bei näherer Betrachtung ist das Lemuria, das von Miryam beschrieben wird, auch eine Sache der Vergangenheit, die nicht zurückgeholt werden kann."
  },
  AvgDialog_126908_Content_21 = {
    Text = "Aber wohin möchte ich zurückkehren? Ich denke, es ist wahrscheinlich das wahre Traumlose Land. \n Alle von ihnen, wir alle, haben längst die Orte verloren, zu denen wir zurückkehren können. \n Aber du, nur du, %player%, die Mythag Universität, nach der du dich sehnst und die du schätzt, existiert noch, und es gibt immer noch Menschen, die auf deine Rückkehr warten. \n Daher musst du der letzte Gewinner dieses Spiels werden. \n\n Daher widme ich diesen Sieg dir, markiere ihn mit meinem Tod. \n Ziehe einfach den Hebel mit deiner Hand, und er wird dich an den Ort bringen, an dem diese Menschen auf dich warten."
  },
  AvgDialog_126908_Content_22 = {
    Text = "Möge unser beider Wunsch erfüllt werden. \n\n Xu"
  },
  AvgDialog_126908_Content_23 = {
    Text = "Es ist ein seltsamer Streich, der zu N's fiesem Charakter passt..."
  },
  AvgDialog_126908_Content_24 = {
    Text = "Du murmelst leise vor dich hin und versuchst, den Impuls aus deinem Kopf zu schütteln."
  },
  AvgDialog_126908_Content_25 = {
    Text = "Aber diese Versuchung ist einfach zu groß, da vertraute Begleiter in deinem Kopf erscheinen, bis diese Gestalt auftaucht..."
  },
  AvgDialog_126908_Content_26 = {Text = "Ramona..."},
  AvgDialog_126908_Content_27 = {
    Text = "Das pochende Herzklopfen erfüllt deine Wahrnehmung, und dein Körper handelt, bevor dein Verstand hinterherkommen kann; du drückst den Hebel des Zuges."
  },
  AvgDialog_126908_Content_28 = {
    Text = "Der Zug beschleunigt plötzlich und rast auf das entfernte schwarze Loch zu."
  },
  AvgDialog_126908_Content_29 = {
    Text = "Sekunden später erschien am Ende des Tunnels, über hundert Meter entfernt, plötzlich eine gewaltige Klippe."
  },
  AvgDialog_126908_Content_3 = {
    Text = "Am Ende des Wagens Nummer eins wartet eine elegante Gestalt mit einem Fächer, der ihr Gesicht verdeckt, still auf dich."
  },
  AvgDialog_126908_Content_30 = {
    Text = "Was für ein Witz..."
  },
  AvgDialog_126908_Content_31 = {
    Text = "Du ziehst den Hebel nervös kräftig, aber er scheint festzustecken und reagiert nicht, während die Bergwand mit über hundert Kilometern pro Stunde auf dich zurast."
  },
  AvgDialog_126908_Content_32 = {
    Text = "<Red:Es wird gleich crashen...>"
  },
  AvgDialog_126908_Content_33 = {
    Text = "Du schließt hilflos die Augen und wartest auf den Moment des Aufpralls."
  },
  AvgDialog_126908_Content_34 = {
    Text = "<Shake:So niederträchtig... Warum war ich so töricht, an irgendeinen von N's Avataren zu glauben?...>"
  },
  AvgDialog_126908_Content_35 = {
    Text = "Krach——!!"
  },
  AvgDialog_126908_Content_36 = {
    Text = "Im nächsten Moment nach dem Aufprall des Zuges zieht das Gefühl der Schwerelosigkeit dich direkt nach unten."
  },
  AvgDialog_126908_Content_37 = {Text = "!!! Uff!!"},
  AvgDialog_126908_Content_38 = {
    Text = "Die Zeit ist ungewiss vergangen."
  },
  AvgDialog_126908_Content_39 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_126908_Content_4 = {
    Text = "Bitte erlauben Sie mir, mich vorzustellen. Ich bin Thais auf diesem Zug, oder Sie können mich auch als N's Maulwurf bezeichnen."
  },
  AvgDialog_126908_Content_40 = {
    Text = "Hier ist...?<Shake:Misaq?!>"
  },
  AvgDialog_126908_Content_41 = {
    Text = "Die architektonische Struktur außerhalb des Fensters ist allzu vertraut. Die immense Freude lässt dich einige Eigenheiten übersehen, und du springst fast aus dem teuren Sessel."
  },
  AvgDialog_126908_Content_42 = {
    Text = "Bis du selbstverständlich einen Spiegel siehst, der absichtlich und sorgfältig in einem bestimmten Winkel positioniert ist."
  },
  AvgDialog_126908_Content_43 = {
    Text = "drin spiegelte das Gesicht von Lord Dexter wider."
  },
  AvgDialog_126908_Content_44 = {Text = "???"},
  AvgDialog_126908_Content_45 = {
    Text = "Du berührst misstrauisch dein Gesicht, während Dexters Fingerspitzen im Spiegel über seine eingefallenen Wangen gleiten."
  },
  AvgDialog_126908_Content_46 = {
    Text = "Oh je, die Belohnung für das Überleben des internen Kampfes ist “Rückkehr nach Misaq“, aber es gibt kein Versprechen, wie man zurückkehrt, oder?"
  },
  AvgDialog_126908_Content_47 = {
    Text = "Die Grenze dessen, was ich tun kann, ist es, dir zu erlauben, für eine Weile meinen Avatar auszuleihen."
  },
  AvgDialog_126908_Content_48 = {
    Text = "Dennoch ist dies ein Vorgang, der gegen die Gesetze des Universums verstößt. Du musst dich unbedingt beherrschen und darauf achten, dass niemand entdeckt, dass du nicht der LORD Dexter selbst bist~"
  },
  AvgDialog_126908_Content_49 = {
    Text = "Ich schätze, du wirst gleich sagen: “Sonst“..."
  },
  AvgDialog_126908_Content_5 = {
    Text = "In einem Leben, das sich über Tausende oder sogar Zehntausende von Jahren erstreckt, bin ich mehr an den Namen „Xu“ gewöhnt. Er ist gewöhnlich genug, weit verbreitet genug und vertraut genug, um als jemand angesehen zu werden."
  },
  AvgDialog_126908_Content_50 = {
    Text = "Andernfalls, klingeling! Die Mitternachtsglocke wird früh läuten, und die Kürbiskutsche und der Glaspantoffel werden in ihre ursprünglichen Formen zurückkehren."
  },
  AvgDialog_126908_Content_51 = {
    Text = "Schätze die Momente vor Mitternacht; sie sind die Zeit, die du mit dem Leben deiner Gefährten verdient hast."
  },
  AvgDialog_126908_Content_6 = {
    Text = "Ich habe viele Dinge, die ich dir sagen möchte, aber nicht hier."
  },
  AvgDialog_126908_Content_7 = {
    Text = "Wenn das Schicksal es erlaubt, lasst uns in der Zukunft irgendwo anders wiedersehen."
  },
  AvgDialog_126908_Content_8 = {
    Text = "Sie hob die Hand und zerdrückte dann den Silberkern in ihrer Handfläche."
  },
  AvgDialog_126908_Content_9 = {
    Text = "Du bist der ultimative Sieger, Hüter."
  },
  AvgDialog_126909_Content_1 = {
    Text = "Wunschjahreszug"
  },
  AvgDialog_126909_Content_10 = {
    Text = "<Shake:Kling, kling, kling—>"
  },
  AvgDialog_126909_Content_11 = {
    Text = "<Shake:Hmm... so müde.>\nIm Zug schlafen, egal wie lange ich schlafe, es ist nie genug."
  },
  AvgDialog_126909_Content_12 = {
    Text = "<LightGray:Es fühlt sich an, als wäre mein Gehirn in einem Durcheinander aus Schleim verheddert und ich vergesse etwas Entscheidendes...>"
  },
  AvgDialog_126909_Content_13 = {
    Text = "<LightGray:<Shake:Was soll's, ich gehe zurück ins Zimmer, um den Körper zu verstecken, unter dem Vorwand, dass ich wegen des Jahreswechsel Fests Urlaub machen muss. Egal, wie sehr Doll die Hausaufgaben drängt oder Ramona den Bericht fordert, ich werde bis zum Ende widerstehen...>>"
  },
  AvgDialog_126909_Content_14 = {
    Text = "Oh je, was für ein schläfriger kleiner Setzling. Du kannst dich bis zur Ankunft des Zuges an meine Schulter lehnen, okay?"
  },
  AvgDialog_126909_Content_15 = {Text = "Whoa?!"},
  AvgDialog_126909_Content_16 = {
    Text = "Du schaust dich um und zählst die Anzahl der Passagiere."
  },
  AvgDialog_126909_Content_17 = {
    Text = "Wanda wirbelte ein halbes Glas Rotwein und senkte ihren Kopf, um ihre sorgfältig polierten spitzen Nägel zu bewundern."
  },
  AvgDialog_126909_Content_18 = {
    Text = "Tinct hielt leise ein Musikstück, ihre dünnen Lippen bewegten sich, als würde sie es sanft in ihrem Geist üben."
  },
  AvgDialog_126909_Content_19 = {
    Text = "Winkle lehnte neben der schwachen kleinen Lampe, ihr Blick schien an dem Docht festgeklebt, als hätte sie Angst, dass ein Lichtstrahl entweichen könnte."
  },
  AvgDialog_126909_Content_2 = {
    Text = "Tada! Meine Damen und Herren im Publikum, frohes Frühlingsfest! Endlich ist es meine Zeit, kleine N, um zu glänzen!"
  },
  AvgDialog_126909_Content_20 = {
    Text = "Miryam neigt den Kopf zurück und schließt die Augen, scheinbar ahnungslos über die Veränderungen um sie herum."
  },
  AvgDialog_126909_Content_21 = {
    Text = "<LightGray:Alle, die Atmosphäre, sich nicht gegenseitig zu stören, ist so angenehm...>"
  },
  AvgDialog_126909_Content_22 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_126909_Content_23 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_126909_Content_24 = {
    Text = "<LightGray:Aber dauert dieser Zug nicht ein wenig zu lange?>"
  },
  AvgDialog_126909_Content_25 = {
    Text = "Der Mythag-Sonderzug ist eingerichtet, um die Nebelschranke außerhalb des Campus zu durchfahren; es handelt sich um einen Kurzstreckenzug. Doch da du eingeschlafen bist und dann wieder aufgewacht bist, ist bereits mindestens eine Stunde vergangen."
  },
  AvgDialog_126909_Content_26 = {
    Text = "Nach einem Moment des Nachdenkens näherst du dich dem einzigen Lehrer im Fahrzeug."
  },
  AvgDialog_126909_Content_27 = {
    Text = "Winkle... warum ist der <Yellow:Misaq-Express> heute so langsam?"
  },
  AvgDialog_126909_Content_28 = {
    Text = "Winkle sprang auf wie ein erschrecktes Kaninchen."
  },
  AvgDialog_126909_Content_29 = {
    Text = "Was ist der besondere Mythag-Zug? Fährt dieser Zug nicht zum Heimatplaneten von @1?"
  },
  AvgDialog_126909_Content_3 = {
    Text = "Selbst wenn du mein Doppelgänger bist, muss ich deinen Plan dieses Mal kritisieren, da er unterdurchschnittlich und etwas absurd ist."
  },
  AvgDialog_126909_Content_30 = {
    Text = "Alle Augen sind auf Winkle gerichtet, wie auf ein Spotlight."
  },
  AvgDialog_126909_Content_31 = {
    Text = "Mach keine Witze, kleines Mädchen. Ist das nicht der Zug nach Aram?"
  },
  AvgDialog_126909_Content_32 = {
    Text = "Huh, aber Aram liegt tief in der Wüste, und es ist unmöglich, hier einen Zug zu haben..."
  },
  AvgDialog_126909_Content_33 = {
    Text = "Soweit ich weiß, sollte das endgültige Ziel dieses Zuges Isalaw sein."
  },
  AvgDialog_126909_Content_34 = {
    Text = "Das ist noch absurder. Ist Isarau nicht schon lange zerstört?"
  },
  AvgDialog_126909_Content_35 = {
    Text = "Reden ist billig; ich habe die Belege als Beweis."
  },
  AvgDialog_126909_Content_36 = {
    Text = "Wanda zog ein metallisches Ticket heraus und zeigte es allen."
  },
  AvgDialog_126909_Content_37 = {
    Text = "An der Ausschiffungsstation auf dem Ticket steht der Name Isarawu deutlich geschrieben."
  },
  AvgDialog_126909_Content_38 = {
    Text = "Miryam, Tinct, ihr beiden..."
  },
  AvgDialog_126909_Content_39 = {
    Text = "Ohne weitere Umschweife wird sein Wille mich auf dem Weg zurück nach Lemuria leiten."
  },
  AvgDialog_126909_Content_4 = {
    Text = "Es ist noch nicht das Frühlingsfest, also müssen wir dem Publikum etwas anderes Unterhaltung bieten, oder?"
  },
  AvgDialog_126909_Content_40 = {
    Text = "Ich... ich möchte die Gelegenheit der Frühlingsfestferien nutzen, um nach Wild Star zurückzukehren und etwas Zeit mit meiner Schwester zu verbringen..."
  },
  AvgDialog_126909_Content_41 = {
    Text = "<LightGray:Wilde Sterne... Tinct wanderte unzählige Epochen, um Kadath zu erreichen. Diese Distanz ist für einen Zug völlig unerreichbar...>"
  },
  AvgDialog_126909_Content_42 = {
    Text = "Lemuria sank vor tausend Jahren auf den Meeresboden."
  },
  AvgDialog_126909_Content_43 = {
    Text = "Und Isaraul... ist schon lange zerstört."
  },
  AvgDialog_126909_Content_44 = {
    Text = "Kleines, du hast die Landschaft so lange beschrieben. Wie heißt der Heimatplanet, zu dem du zurückkehren möchtest, und wo ist er?"
  },
  AvgDialog_126909_Content_45 = {
    Text = "Der Gesichtsausdruck von Winkle änderte sich drastisch."
  },
  AvgDialog_126909_Content_46 = {
    Text = "<Shake:Heimatplanet... ist der Heimatplanet! Der Name des Heimatplaneten... ist... <Small:@1...>>"
  },
  AvgDialog_126909_Content_47 = {
    Text = "Hä? Ich muss mir etwas einbilden; du kannst dich nicht einmal an den Namen deines Heimatplaneten erinnern?"
  },
  AvgDialog_126909_Content_48 = {
    Text = "Alle, beruhigt euch und hört mir zu."
  },
  AvgDialog_126909_Content_49 = {
    Text = "Jedes Ziel klingt sehr unrealistisch. Aber jeder hat tatsächlich ein Ticket zu seiner eigenen Heimat."
  },
  AvgDialog_126909_Content_5 = {
    Text = "Trotzdem ist es nicht zu bizarr, nur eine Szene von Anfang bis Ende zu haben?"
  },
  AvgDialog_126909_Content_50 = {
    Text = "Deshalb müssen wir vor allem den <Yellow:Schaffner> im Zug finden, um Informationen über diesen Zug zu sammeln, anstatt uns hier in sinnlosen Diskussionen zu verlieren."
  },
  AvgDialog_126909_Content_51 = {
    Text = "Hust, hust."
  },
  AvgDialog_126909_Content_52 = {
    Text = "Ein etwas komisches Geräusch kommt aus der Ecke."
  },
  AvgDialog_126909_Content_53 = {
    Text = "Ist das das Ende der Aufregung? Ich möchte die Show noch ein wenig länger sehen~"
  },
  AvgDialog_126909_Content_54 = {
    Text = "Kleines N?!"
  },
  AvgDialog_126909_Content_55 = {
    Text = "Was ist los? Keine herzliche Begrüßung für mich? Ich habe sogar ein großes Geschenk für alle zum Frühlingsfest vorbereitet!"
  },
  AvgDialog_126909_Content_56 = {
    Text = "Der eigentlich im Dunkel verborgene Drahtzieher trat ins Zentrum der Bühne, und seine finsteren Absichten wurden offensichtlich—er muss eine noch größere Verschwörung planen."
  },
  AvgDialog_126909_Content_57 = {
    Text = "Was machst du hier?"
  },
  AvgDialog_126909_Content_58 = {
    Text = "Ist es nicht offensichtlich? Der fürsorgliche, selbstlose und großzügige Ich hat diesen Schnellzug nach Hause für das Frühlingsfest ins Leben gerufen, damit jeder, der seine Heimat vermisst, die Wärme der Feiertage genießen kann."
  },
  AvgDialog_126909_Content_59 = {
    Text = "Du bist nicht so gutherzig. Was versteckst du jetzt noch?"
  },
  AvgDialog_126909_Content_6 = {
    Text = "<Shake:Uhhuh, jetzt ist nicht die Zeit, dass Sie das Theater leiten und mit dieser Dame umgehen. Das Projektteam für die Neujahrsveranstaltung ist finanziell am Ende und kann nur eine so karge Veranstaltungsortgestaltung bereitstellen...>"
  },
  AvgDialog_126909_Content_60 = {
    Text = "Oh, beeil dich nicht. Lass mich langsam sprechen."
  },
  AvgDialog_126909_Content_61 = {
    Text = "Viele Menschen wollen nach Hause zurückkehren, aber es gibt nur einen Zug. Also kann nur eine Person in die ersehnte Heimat zurückfahren, oder?"
  },
  AvgDialog_126909_Content_62 = {
    Text = "Oh mein Gott, als rücksichtsvoller, selbstloser und wohlwollender N muss ich die fairsten Mittel verwenden, um zu bestimmen, wer diese Qualifikation erhalten kann, oder?"
  },
  AvgDialog_126909_Content_63 = {Text = "Also..."},
  AvgDialog_126909_Content_64 = {
    Text = "<Big:Also, <Shake:<Red:Lasst uns mit dem gegenseitigen Schlachten beginnen!>>!>"
  },
  AvgDialog_126909_Content_65 = {
    Text = "Töte alle, und die letzte lebende Person wird das Ziel dieses Zuges bestimmen und die Chance auf einen <Yellow:Heimtagestour> bekommen!"
  },
  AvgDialog_126909_Content_66 = {
    Text = "Unmöglich! Niemand würde das Leben eines anderen für so etwas opfern... oder etwa doch?!"
  },
  AvgDialog_126909_Content_67 = {
    Text = "Das stimmt, auch wenn ich Faint sehr vermisse... kann ich an einem so grausamen Wettbewerb nicht teilnehmen..."
  },
  AvgDialog_126909_Content_68 = {
    Text = "Hmph, hier zu bleiben, um guten Wein und Diener zu genießen, ist nicht so schlecht. Isaraul ist nur ein Kapitel aus meiner Vergangenheit."
  },
  AvgDialog_126909_Content_69 = {
    Text = "Obwohl es schwer ist, diesen Ort zu verlassen... meine kleinen Setzlinge sind hier, und die Aramiten sind nicht mehr auf mich angewiesen, um den Stamm zu führen. Ich nehme an, ich habe keine Motivation, an diesem gegenseitigen Gemetzel teilzunehmen."
  },
  AvgDialog_126909_Content_7 = {
    Text = "Es scheint, dass ich keine andere Wahl habe, als abzuwarten und zu sehen."
  },
  AvgDialog_126909_Content_70 = {
    Text = "Alle Blicke richteten sich auf die letzte Person."
  },
  AvgDialog_126909_Content_71 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_126909_Content_72 = {
    Text = "Dein Blick störte sie nicht im Geringsten; Miryam schwieg."
  },
  AvgDialog_126909_Content_73 = {
    Text = "Du bist dir ihrer Besessenheit bewusst und kennst die Bedeutung und den Wert des Wortes Lemuria für sie."
  },
  AvgDialog_126909_Content_74 = {
    Text = "Seufz, ich wusste, dass es nicht so einfach sein würde..."
  },
  AvgDialog_126909_Content_75 = {
    Text = "Um diese unangenehme Situation zu vermeiden, habe ich die Regeln speziell verfeinert – du musst mir 5 Verstorbene bringen, um das letzte Ticket zu tauschen."
  },
  AvgDialog_126909_Content_76 = {
    Text = "Du musst alle sieben Tickets sammeln, um den Zug zu starten!"
  },
  AvgDialog_126909_Content_77 = {
    Text = "Mit anderen Worten, niemand kann hier weg, bis nur noch eine Person nach dem Gemetzel im Zug übrig ist."
  },
  AvgDialog_126909_Content_78 = {
    Text = "Außerdem gibt es unter euch einen <Yellow:Maulwurf>, den ich eingesetzt habe, verwandelt aus meinem Avatar, dem sich ständig verändernden kleinen N!"
  },
  AvgDialog_126909_Content_79 = {
    Text = "Wenn du nichts tust, wird es dich nacheinander töten! Dann wird niemand mehr zurückkehren können!"
  },
  AvgDialog_126909_Content_8 = {
    Text = "Ohne weitere Umschweife bringt euch Xiao N das <Shake:neueste und heißeste<Red:exklusive Jahreswechsel Fest-Echosimulationstheater>>!"
  },
  AvgDialog_126909_Content_81 = {
    Text = "Kaum hatte N gesprochen, durchbohrte ein Weinstock plötzlich den schwarzen Nebel."
  },
  AvgDialog_126909_Content_82 = {
    Text = "Alright, alle. Hört nicht auf die täuschenden Worte dieses Typen."
  },
  AvgDialog_126909_Content_83 = {
    Text = "Wir sind sechs, einschließlich des bemerkenswertesten Wächters von Mythag. Können wir wirklich diesem kleinen Raum nicht entkommen?"
  },
  AvgDialog_126909_Content_9 = {
    Text = "Applaus und Jubel hallen wider!"
  },
  AvgDialog_126910_Content_1 = {
    Text = "Der zweite Tote"
  },
  AvgDialog_126910_Content_10 = {
    Text = "Ist nicht die dringlichere Angelegenheit, den Mörder unter uns zu finden?"
  },
  AvgDialog_126910_Content_11 = {
    Text = "Nein, ich denke nicht... Es sind nur so wenige von uns, und wenn wir in gegenseitigen Verdacht geraten, wird es nur schlimmer."
  },
  AvgDialog_126910_Content_12 = {
    Text = "Noch wichtiger ist, dass wir die Sicherheit der verbleibenden Personen gewährleisten. Wie wäre es, wenn wir alle in Wagen 2 bleiben?"
  },
  AvgDialog_126910_Content_13 = {
    Text = "Du sahst den erschöpften Winkle an und nicktest."
  },
  AvgDialog_126910_Content_14 = {
    Text = "Der kleine Sämling hat eine Entscheidung getroffen, und ich werde sie sicherlich nicht ablehnen."
  },
  AvgDialog_126910_Content_15 = {
    Text = "...alle drei Stunden muss ich einen ruhigen Ort finden, um allein zu beten."
  },
  AvgDialog_126910_Content_16 = {
    Text = "Auf keinen Fall! Wer weiß, welche schlimmen Dinge du während des Betens tun könntest!"
  },
  AvgDialog_126910_Content_17 = {
    Text = "Außerdem, als alle über die Idee diskutierten, auf das Töten einander zu verzichten, warst du der Einzige, der seine Meinung nicht äußerte. Wer weiß, ob du einer von Ns Handlangern bist?"
  },
  AvgDialog_126910_Content_18 = {
    Text = "Es gibt nur einen Herrn, dem ich diene, und das ist die Gottheit von Lemuria."
  },
  AvgDialog_126910_Content_19 = {
    Text = "Wenn du noch mehr blasphemische Worte von dir gibst, würde ich es nicht ablehnen, im Namen meines Herrn göttliche Strafe zu verhängen."
  },
  AvgDialog_126910_Content_2 = {
    Text = "Drei Stunden später, in der Kutsche"
  },
  AvgDialog_126910_Content_20 = {
    Text = "Als du siehst, dass Miryam bereits den Dolch gezogen hat, versuchst du hastig zu vermitteln."
  },
  AvgDialog_126910_Content_21 = {
    Text = "Wir haben derzeit keine Beweise, um jemanden zu beschuldigen, Tinct... Jeder schlief zu diesem Zeitpunkt."
  },
  AvgDialog_126910_Content_22 = {
    Text = "Außerdem könnte dieser sogenannte Maulwurf nur einer von Ns Tricks sein, der uns dazu verleitet, uns gegenseitig nach seinem Plan zu töten."
  },
  AvgDialog_126910_Content_23 = {
    Text = "Wie kannst du das über mich sagen? Boohoo, ich wollte dich wirklich an alles erinnern—"
  },
  AvgDialog_126910_Content_24 = {
    Text = "<LightGray:Augenmesser...>"
  },
  AvgDialog_126910_Content_25 = {
    Text = "Okay, okay, ich verschwinde, waaah..."
  },
  AvgDialog_126910_Content_26 = {
    Text = "Mit einem Knall verschwand die Gestalt des kleinen N in Luft."
  },
  AvgDialog_126910_Content_27 = {
    Text = "In diesem Fall... Miryam, könntest du bitte alleine im Auto Nummer 1 beten und nicht ohne Erlaubnis gehen?"
  },
  AvgDialog_126910_Content_28 = {
    Text = "Wir treffen uns an der Hintertür von Wagen 1, während die anderen alle im selben Raum sind, sodass keine Gefahr besteht."
  },
  AvgDialog_126910_Content_29 = {
    Text = "Ist das nicht ein bisschen unfair gegenüber Miryam...?"
  },
  AvgDialog_126910_Content_3 = {
    Text = "<Shake:Glug glug glug—>"
  },
  AvgDialog_126910_Content_30 = {
    Text = "Ich habe keine Einwände."
  },
  AvgDialog_126910_Content_31 = {
    Text = "Miryam ignorierte dein Hindernis und stand direkt auf, um das Auto Nummer 2 zu verlassen, ohne zu vergessen, sich sorgfältig umzudrehen und die Trennwandtür abzuschließen."
  },
  AvgDialog_126910_Content_32 = {
    Text = "Die verbleibenden Personen sollten sich jetzt entspannen können..."
  },
  AvgDialog_126910_Content_33 = {
    Text = "Ich habe immer das Gefühl, dass diese Angelegenheit nicht so einfach ist..."
  },
  AvgDialog_126910_Content_34 = {
    Text = "In einer Stunde, in Wagen Nr. 2"
  },
  AvgDialog_126910_Content_35 = {
    Text = "Mmh mmh mmh..."
  },
  AvgDialog_126910_Content_36 = {
    Text = "Ich werde für eine Weile weg sein..."
  },
  AvgDialog_126910_Content_37 = {
    Text = "Winkle wackelte in Richtung der Ecke des Fahrzeugs."
  },
  AvgDialog_126910_Content_38 = {
    Text = "<LightGray:Habe ich zu viel Kaffee gehabt...?>"
  },
  AvgDialog_126910_Content_39 = {
    Text = "In einer Stunde, in Wagen Nr. 2"
  },
  AvgDialog_126910_Content_4 = {
    Text = "Hör auf zu trinken."
  },
  AvgDialog_126910_Content_40 = {
    Text = "<LightGray:Seltsam, warum ist Winkle noch nicht zurückgekehrt...>"
  },
  AvgDialog_126910_Content_41 = {
    Text = "Bist du sehr besorgt? Möchtest du, dass ich dich zu einer Untersuchung begleite?"
  },
  AvgDialog_126910_Content_42 = {
    Text = "Lass uns gehen."
  },
  AvgDialog_126910_Content_43 = {
    Text = "Ein Gefühl der Unruhe breitet sich in deiner Brust aus, die hohlen Schritte und Schatten füllen den ganzen Waggon aus."
  },
  AvgDialog_126910_Content_44 = {
    Text = "Du verstehst diesen düsteren Namen—"
  },
  AvgDialog_126910_Content_45 = {Text = "Tod."},
  AvgDialog_126910_Content_46 = {
    Text = "Du klopfst immer wieder an die Badezimmertür und rufst Winkles Namen, aber es gibt keine Antwort."
  },
  AvgDialog_126910_Content_47 = {
    Text = "Du versuchst, die Tür einzutreten."
  },
  AvgDialog_126910_Content_48 = {
    Text = "Dumpf, dumpf, dumpf!"
  },
  AvgDialog_126910_Content_49 = {
    Text = "Was ist passiert?"
  },
  AvgDialog_126910_Content_5 = {
    Text = "<Shake:Glug glug glug—>"
  },
  AvgDialog_126910_Content_50 = {
    Text = "Auch Wanda wurde von dem ungewöhnlichen Geräusch angezogen."
  },
  AvgDialog_126910_Content_51 = {
    Text = "Winkle ist seit einer Stunde im Badezimmer. Wir haben an die Tür geklopft, aber es gab keine Antwort."
  },
  AvgDialog_126910_Content_52 = {
    Text = "Das Tor kann ebenfalls nicht aufgebrochen werden. Es ist seltsam, eine Gruppe von Erwachten kann Winde und Regen heraufbeschwören und ist in der Lage, gegen mythische Kreaturen alles zu tun, doch sie können nicht einmal eine einzige Tür öffnen!"
  },
  AvgDialog_126910_Content_53 = {
    Text = "Hast du von dem neuen Genre gehört?"
  },
  AvgDialog_126910_Content_54 = {
    Text = "Wenn wir vom neuen Genre sprechen, dürfen wir das klassische Genre nicht vergessen."
  },
  AvgDialog_126910_Content_56 = {
    Text = "Im Kontext des Denkens beziehen sich klassische Werke auf Detektivgeschichten mit klaren Rätseln und logischem Denken, während die neue Klassik dieser Grundlage einzigartige Weltanschauungen hinzufügt."
  },
  AvgDialog_126910_Content_57 = {
    Text = "Dennoch muss der neue Klassiker die Leser und die Fairness respektieren und Fragen im Rahmen der bekannten Gegebenheiten aufwerfen, ohne willkürliche Hinzufügungen übernatürlicher Elemente zuzulassen."
  },
  AvgDialog_126910_Content_58 = {
    Text = "Mit anderen Worten, wenn du nicht die Fähigkeit hast, zu entriegeln, kannst du die von innen verschlossene Tür nicht einfach so öffnen."
  },
  AvgDialog_126910_Content_59 = {
    Text = "Kleiner N kletterte eine Weile auf die Gepäckablage, dann versteckte er sich hinter der Rückenlehne des Stuhls, während er all die Dornen und Ranken auswich und seine lange Rede zu Ende brachte."
  },
  AvgDialog_126910_Content_6 = {Text = "Winkle..."},
  AvgDialog_126910_Content_60 = {
    Text = "Also meinst du... das ist ein Mord in einem verschlossenen Raum, und drinnen ist der Tatort?"
  },
  AvgDialog_126910_Content_61 = {
    Text = "Wer weiß! Was, wenn Winkle aus Angst vor Strafe geflohen ist und durch das Badezimmerfenster aus dem Auto gesprungen ist?"
  },
  AvgDialog_126910_Content_62 = {
    Text = "Hast du nicht gesagt, dass wir den Zug nicht verlassen können?"
  },
  AvgDialog_126910_Content_63 = {
    Text = "Oh je, da war ein Fehler in der Deduktion!"
  },
  AvgDialog_126910_Content_64 = {
    Text = "Bevor der echte Detektiv auftritt, muss es immer einen Typen geben, der für die falsche Schlussfolgerung verantwortlich ist."
  },
  AvgDialog_126910_Content_65 = {
    Text = "Wenn sonst niemand die Rolle des Narren übernehmen möchte, dann lass mich, den großen und treuen kleinen N, sie spielen!"
  },
  AvgDialog_126910_Content_66 = {
    Text = "Hör auf, mit diesem Kerl zu plaudern."
  },
  AvgDialog_126910_Content_67 = {
    Text = "Obwohl es ein wenig unhöflich ist... gibt es ein kleines Fenster mit Jalousien an der Badezimmertür, und die Struktur ist sehr zerbrechlich."
  },
  AvgDialog_126910_Content_68 = {
    Text = "Wanda hob den Stachel an."
  },
  AvgDialog_126910_Content_69 = {
    Text = "Knarren, die Jalousien wurden abgenommen."
  },
  AvgDialog_126910_Content_7 = {
    Text = "Egal wie viel Kaffee konsumiert wird, Tinct wird nicht zurückkommen, oder?"
  },
  AvgDialog_126910_Content_70 = {
    Text = "Überlass den Rest mir."
  },
  AvgDialog_126910_Content_71 = {
    Text = "Die Ranken griffen hinein und öffneten die Tür, und du drücktest sie auf."
  },
  AvgDialog_126910_Content_72 = {
    Text = "Keine Zeit mehr."
  },
  AvgDialog_126910_Content_73 = {
    Text = "Winkle hatte sich still in die Ecke des Badezimmers gekauert."
  },
  AvgDialog_126910_Content_74 = {Text = "Winkle!"},
  AvgDialog_126910_Content_75 = {
    Text = "Du eiltest hastig zu Winkle, ihre Lippen sickerten tiefrotes Blut, und sie hatte bereits ihren Atem verloren."
  },
  AvgDialog_126910_Content_76 = {
    Text = "Um ehrlich zu sein, Winkle... zu dem Zeitpunkt deines Todes haben weder du, noch ich, noch Wanda den Wagen Nr. 2 verlassen."
  },
  AvgDialog_126910_Content_77 = {
    Text = "Der einzige Mörder... kann nur Miryam sein."
  },
  AvgDialog_126910_Content_78 = {
    Text = "Mein Herr hat mich nicht geleitet, solche Handlungen vorzunehmen. Wenn ihr jedoch besteht, kann ich im Namen der Götter ein Urteil fällen."
  },
  AvgDialog_126910_Content_79 = {
    Text = "Oh nein, wir sind an einem Stillstand!"
  },
  AvgDialog_126910_Content_8 = {
    Text = "<Shake:Du——>"
  },
  AvgDialog_126910_Content_80 = {
    Text = "Da wir schon von göttlichem Urteil sprechen, möchte ich euch einen einfachen Weg zum Sieg anbieten!"
  },
  AvgDialog_126910_Content_81 = {
    Text = "Wir können jetzt eine Abstimmung abhalten, und die Person mit den meisten Stimmen wird von mir persönlich aus dem Zug geworfen und verliert ihre Chance, nach Hause zu gehen!"
  },
  AvgDialog_126910_Content_82 = {
    Text = "Ohne Zweifel werde ich Miryam besetzen."
  },
  AvgDialog_126910_Content_83 = {Text = "Thais."},
  AvgDialog_126910_Content_84 = {
    Text = "Kleiner, was denkst du? Angesichts der aktuellen Situation würde ich auch für Miryam stimmen."
  },
  AvgDialog_126910_Content_85 = {
    Text = "Miryam 2 Stimmen! Thais 1 Stimme!"
  },
  AvgDialog_126910_Content_86 = {
    Text = "N, wie berechnen wir das Ergebnis, wenn es ein Unentschieden gibt?"
  },
  AvgDialog_126910_Content_87 = {
    Text = "Wenn es ein Unentschieden gibt, wird angenommen, dass niemand draußen ist~"
  },
  AvgDialog_126910_Content_88 = {
    Text = "Aber überleg es dir gut, es sind jetzt nur noch vier Personen übrig. Wenn du diese Gelegenheit aufgibst und der Verräter noch jemanden tötet, erhöht sich die Gewinnchance erheblich – erheblich –!"
  },
  AvgDialog_126910_Content_89 = {
    Text = "Ich möchte guten Menschen nicht Unrecht tun. Ich wähle Thais."
  },
  AvgDialog_126910_Content_9 = {
    Text = "Das stimmt, was wichtiger ist, ist einen Weg zu finden, um den Zug zu verlassen."
  },
  AvgDialog_126910_Content_90 = {
    Text = "Wirst du wirklich nicht noch einmal darüber nachdenken? Das ist die einzige Chance zu wählen?"
  },
  AvgDialog_126910_Content_91 = {
    Text = "Nein, je mehr du das sagst, desto mehr fühle ich, dass ich die richtige Wahl getroffen habe."
  },
  AvgDialog_126910_Content_92 = {
    Text = "In Ordnung, das Abstimmungsergebnis für diese Runde ist: ein Unentschieden, und niemand ist ausgeschieden~"
  },
  AvgDialog_126910_Content_93 = {
    Text = "Seufz~ So enttäuscht~ Kleines N muss sich in eine Ecke zurückziehen, um sich zu beruhigen. Bis später~"
  },
  AvgDialog_126911_Content_1 = {
    Text = "Das Spiel beginnt"
  },
  AvgDialog_126911_Content_10 = {
    Text = "Wenn du weiterhin plauderst, würde ich es nicht bereuen, dies zu benutzen, um dich erneut das Gefühl zu erleben, als wäre dein Herz durchbohrt, weißt du?"
  },
  AvgDialog_126911_Content_11 = {
    Text = "Wanda streichelte den Dorn in ihrer Handfläche."
  },
  AvgDialog_126911_Content_12 = {
    Text = "Ach je, was für eine herzzerreißende Aussage das ist."
  },
  AvgDialog_126911_Content_13 = {
    Text = "Ist das Jahreswechsel Fest-Programm, das ich mühsam vorbereitet habe, wirklich so unbeliebt? <Italic:Schnief...>"
  },
  AvgDialog_126911_Content_14 = {
    Text = "N täuschte für weniger als eine Sekunde Tränen vor und brach dann sofort in ein strahlendes Lächeln aus."
  },
  AvgDialog_126911_Content_15 = {
    Text = "Kurz gesagt, bitte gebt euer Bestes und kämpft untereinander! Kleiner N wird auf eure Auftritte warten!"
  },
  AvgDialog_126911_Content_16 = {
    Text = "„Whoosh“, der kleine N verschwand wieder. \n Der Zug kehrte erneut in die beunruhigende Stille zurück."
  },
  AvgDialog_126911_Content_17 = {
    Text = "Dann folgt eine lange Stille, die Dunkelheit vor den Schienen scheint endlos."
  },
  AvgDialog_126911_Content_18 = {
    Text = "Wie lange wird der Zug noch fahren? Wo ist das Ziel?"
  },
  AvgDialog_126911_Content_19 = {
    Text = "In den Herzen der Menschen mag es keine Antwort geben, oder es mag eine Antwort geben, die nicht ausgesprochen werden kann."
  },
  AvgDialog_126911_Content_2 = {
    Text = "...Kann nicht raus."
  },
  AvgDialog_126911_Content_20 = {
    Text = "Ähm, alle..."
  },
  AvgDialog_126911_Content_21 = {
    Text = "Eine klare Stimme durchbrach die Stille."
  },
  AvgDialog_126911_Content_22 = {
    Text = "Es ist ziemlich langweilig, hier nur zu sitzen... Wenn es niemanden stört, wie wäre es, wenn ich ein Lied für alle singe?"
  },
  AvgDialog_126911_Content_23 = {
    Text = "Hmm?! Ich liebe das! Kann ich ein Lied anfordern?"
  },
  AvgDialog_126911_Content_24 = {
    Text = "Geh weg, was geht dich das an?"
  },
  AvgDialog_126911_Content_25 = {
    Text = "Da es das Frühlingsfest des Panlong-Reiches ist, erinnere ich mich an ein östliches Lied, das ich einmal vom Schattenchor gehört habe."
  },
  AvgDialog_126911_Content_26 = {
    Text = "Ich bin mir nicht sicher, ob ich genug östliche Stücke gemeistert habe..."
  },
  AvgDialog_126911_Content_27 = {
    Text = "Der Name dieses Liedes ist \"Jasminblüte\"."
  },
  AvgDialog_126911_Content_28 = {
    Text = "Oh? Ist es wirklich dieser Stil?"
  },
  AvgDialog_126911_Content_29 = {
    Text = "Was für ein Zufall, ich war auch im Publikum für die Aufführung des Schattenchores."
  },
  AvgDialog_126911_Content_3 = {
    Text = "Winkle sprach niedergeschlagen das Fazit aus."
  },
  AvgDialog_126911_Content_30 = {
    Text = "Wenn ich mich recht erinnere, bin ich auch... im Publikum begegnet."
  },
  AvgDialog_126911_Content_31 = {
    Text = "Wandas Blick ist auf Miryam gerichtet, während Miryam einfach schweigend nickt."
  },
  AvgDialog_126911_Content_32 = {
    Text = "Da sich niemand dagegen wehrt... werde ich anfangen zu singen."
  },
  AvgDialog_126911_Content_33 = {
    Text = "Tinktur räusperte sich."
  },
  AvgDialog_126911_Content_34 = {
    Text = "<Shake:Was für eine Jasminblume, was für eine Jasminblume♪~ Keine Blume im ganzen Garten kann mit ihr vergleichen♪~>"
  },
  AvgDialog_126911_Content_35 = {
    Text = "<Shake:La-la-la~ la-la-la~ la-la-la♪~>"
  },
  AvgDialog_126911_Content_36 = {
    Text = "Ätherisches und melodisches Singen hallt im leeren Wagen wider."
  },
  AvgDialog_126911_Content_37 = {
    Text = "Unter der beruhigenden Melodie entspannen sich die angespannten Saiten in deinem Kopf allmählich, und du verspürst überraschend einen Hauch von Schläfrigkeit."
  },
  AvgDialog_126911_Content_38 = {
    Text = "Ich schätze, alle sind müde, oder? Ich bin es gewohnt, wach zu bleiben, damit ich für alle Wache halten kann."
  },
  AvgDialog_126911_Content_39 = {
    Text = "Du nicktest und tauchtest dann tief in den lang herannahenden Traum ein."
  },
  AvgDialog_126911_Content_4 = {
    Text = "Neben dem Cockpit besteht dieser Zug aus drei Wagen. Wir befinden uns derzeit im Wagen Nr. 2, der der mittlere ist."
  },
  AvgDialog_126911_Content_40 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_126911_Content_41 = {
    Text = "Nach langer Zeit hat auch Tink fertig gesungen."
  },
  AvgDialog_126911_Content_42 = {
    Text = "Alle schlafen, also solltest du auch ein wenig ruhen, oder?"
  },
  AvgDialog_126911_Content_43 = {
    Text = "Wirklich... ist alles in Ordnung?"
  },
  AvgDialog_126911_Content_44 = {
    Text = "Was, hast du Angst, dass ich der Maulwurf bin?"
  },
  AvgDialog_126911_Content_45 = {
    Text = "Das wird nicht passieren. Es ist nur so, dass ich in der Vergangenheit gewartet habe, bis Schwach eingeschlafen ist, bevor ich mich zur Ruhe gelegt habe..."
  },
  AvgDialog_126911_Content_46 = {
    Text = "Also heute ist es an dir, dich gut auszuruhen! Mach weiter, mach weiter."
  },
  AvgDialog_126911_Content_47 = {
    Text = "Unter Winkles Drängen nahm Tinktur ebenfalls eine Decke und lehnte sich gegen die Rückenlehne des Stuhls, während sie die Augen schloss."
  },
  AvgDialog_126911_Content_48 = {
    Text = "Kein Wunder, dass alle schlafen; es ist eine so entspannende Atmosphäre..."
  },
  AvgDialog_126911_Content_49 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_126911_Content_5 = {
    Text = "Wagen 1 und Wagen 3 sind beide leer, alle Fenster und Türen sind komplett verriegelt, es ist unmöglich, sie mit physischen Mitteln oder Silberschlüssel-Technologie zu durchbrechen."
  },
  AvgDialog_126911_Content_50 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_126911_Content_51 = {Text = "Mmh...?"},
  AvgDialog_126911_Content_52 = {
    Text = "Das Erste, was ins Auge fällt, ist Winkles friedliches und ruhiges schlafendes Gesicht."
  },
  AvgDialog_126911_Content_53 = {
    Text = "Die Lichter im Zug gingen irgendwann aus, und die Umgebung wurde von Dunkelheit verschlungen, nur ein sanftes Licht schien durch die Verbindung zwischen den Waggons."
  },
  AvgDialog_126911_Content_54 = {
    Text = "Winkle... wie bist du eingeschlafen...?"
  },
  AvgDialog_126911_Content_55 = {
    Text = "Winkle ließ einen leisen Atemzug hören."
  },
  AvgDialog_126911_Content_56 = {
    Text = "...Hmm? Bin ich... eingeschlafen?"
  },
  AvgDialog_126911_Content_57 = {
    Text = "Hey hey hey?!!! Bin ich eingeschlafen!!!"
  },
  AvgDialog_126911_Content_58 = {
    Text = "Winkles Ruf war wie ein plötzlicher Sturm, der alle schlafenden Passagiere sofort aufweckte."
  },
  AvgDialog_126911_Content_59 = {
    Text = "Die Lichter leuchteten plötzlich auf und erhellten das gesamte Auto."
  },
  AvgDialog_126911_Content_6 = {
    Text = "Ich habe es dir gesagt! Es gibt keinen Grund zur Aufregung! Niemand kann das Auto verlassen, bis nur noch ein Gewinner übrig ist!"
  },
  AvgDialog_126911_Content_60 = {
    Text = "Liebe Fahrgäste, ruht ihr euch gut im Heimwärts-Express aus?"
  },
  AvgDialog_126911_Content_61 = {
    Text = "Nachdem festgestellt wurde, dass alle Passagiere in einen Schlafzustand eingetreten sind, hat kleine N speziell eine ruhige und lichtdichte Umgebung für euch vorbereitet!"
  },
  AvgDialog_126911_Content_62 = {
    Text = "Entschuldigung, ich verlasse mich normalerweise darauf, viel Kaffee zu trinken, um wach zu bleiben..."
  },
  AvgDialog_126911_Content_63 = {
    Text = "Warte, fehlt einer von uns?"
  },
  AvgDialog_126911_Content_64 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_126911_Content_65 = {
    Text = "Hä? Schaut der kleine Setzling mich an? Ich bin hier."
  },
  AvgDialog_126911_Content_66 = {
    Text = "Also, die vermisste Person ist..."
  },
  AvgDialog_126911_Content_67 = {
    Text = "Alle Blicke richteten sich auf das Ende des Wagens—"
  },
  AvgDialog_126911_Content_68 = {
    Text = "Ein großes Loch wurde von einem scharfen Gegenstand in Tincts Hals gestochen, und Blutplasma floss von der Wunde ihren schwanartigen, graziösen Hals hinunter und durchnässte die Vorderseite ihres Kleides."
  },
  AvgDialog_126911_Content_69 = {
    Text = "Die Nachtigall, die blutet, kann nicht mehr singen."
  },
  AvgDialog_126911_Content_7 = {
    Text = "Warum bist du schon wieder... Hat Thais nicht gerade...?"
  },
  AvgDialog_126911_Content_70 = {
    Text = "<Shake:Yiya————!!!>"
  },
  AvgDialog_126911_Content_71 = {
    Text = "Winkle stieß einen Schrei aus, der durch den Nachthimmel schnitt, rutschte die Wand hinunter in die Ecke, umschlang sich fest mit den Armen und zitterte unkontrollierbar."
  },
  AvgDialog_126911_Content_72 = {
    Text = "<Shake:Es tut mir leid, ich hätte nicht so selbstsicher sein sollen, ich hätte nicht alleine Wache halten sollen, ich hätte nicht denken sollen, dass ich ohne Kaffee nicht einschlafen würde...>"
  },
  AvgDialog_126911_Content_73 = {
    Text = "Winkle kaute nervös auf ihren Nägeln, panikartige Tränen stiegen kontinuierlich auf und tropften auf den Teppich."
  },
  AvgDialog_126911_Content_74 = {
    Text = "Klang! Was hat das verständnisvolle kleine N gehört? <Shake:Die Bedürfnisse der Passagiere>!"
  },
  AvgDialog_126911_Content_75 = {
    Text = "Jetzt bieten wir unseren geschätzten Passagieren durchdienten Service – <Yellow:unbegrenzte Kaffeemaschine>!"
  },
  AvgDialog_126911_Content_76 = {
    Text = "Solange du diesen roten Knopf drückst, wird ein endloser Strom von tiefem, intensivem amerikanischem Feuer aus der Düse strömen!"
  },
  AvgDialog_126911_Content_77 = {
    Text = "Du trittst schweigend vor und hebst die Hand—"
  },
  AvgDialog_126911_Content_78 = {
    Text = "Dann schlug ich diesen kleinen N vor mir heftig und machte ihn platt."
  },
  AvgDialog_126911_Content_79 = {
    Text = "<Shake:Entschuldigung, Entschuldigung, Entschuldigung...>"
  },
  AvgDialog_126911_Content_8 = {
    Text = "Hmph, wenn es so einfach wäre zu sterben, wäre ich nicht mein kleines N!"
  },
  AvgDialog_126911_Content_80 = {
    Text = "Winkles Schluchzen hallte durch das Auto."
  },
  AvgDialog_126911_Content_81 = {
    Text = "Egal wie du widerstehst, die Öffnung wird durch Tincts Tod markiert werden—"
  },
  AvgDialog_126911_Content_82 = {
    Text = "Die gegenseitige Schlachtung hat begonnen."
  },
  AvgDialog_126911_Content_9 = {
    Text = "Nun, wie geht es allen? Hat jeder in seinem Herzen das Ziel für den heutigen Abend gewählt?"
  },
  AvgDialog_126912_Content_1 = {
    Text = "Versteckter Finishing Move"
  },
  AvgDialog_126912_Content_10 = {
    Text = "Aus irgendeinem Grund hast du immer das Gefühl, dass hinter diesem Lächeln eine bestimmte Emotion steckt, die du noch nicht entdeckt hast."
  },
  AvgDialog_126912_Content_11 = {
    Text = "Lass uns gehen, Miryam. Wir gehen zu Wagen Nummer 1."
  },
  AvgDialog_126912_Content_12 = {
    Text = "Im Moment, als das verbindende Tor sich schließen will, dreht Wanda ihren Kopf zurück."
  },
  AvgDialog_126912_Content_13 = {
    Text = "Frohes Frühlingsfest, Hüter."
  },
  AvgDialog_126912_Content_14 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_126912_Content_15 = {
    Text = "Wagen Nr. 2"
  },
  AvgDialog_126912_Content_16 = {
    Text = "Nachdem Wanda und Miryam gegangen sind, sind nur noch du und Thais im Auto geblieben."
  },
  AvgDialog_126912_Content_17 = {
    Text = "Was sollen wir als Nächstes mit dieser seltenen Zeit alleine machen, mein kleiner Setzling?"
  },
  AvgDialog_126912_Content_18 = {
    Text = "Thais lehnt sich plötzlich mit bösen Absichten vor, was dich erschreckt und dich dazu bringt, einen Schritt zurückzutreten, um einen sicheren Abstand zu wahren."
  },
  AvgDialog_126912_Content_19 = {
    Text = "Ich kann den Bericht schnell holen..."
  },
  AvgDialog_126912_Content_2 = {
    Text = "Wagen Nr. 2"
  },
  AvgDialog_126912_Content_20 = {
    Text = "Es ist schon das Frühlingsfest, entspann dich ein wenig und hör auf, die ganze Zeit an deinen Bericht zu denken."
  },
  AvgDialog_126912_Content_21 = {
    Text = "Ihre honigfarbenen Arme legen sich sanft um deine Schultern, ihre unbestimmten Atemzüge umschlingen dich wie der nächtliche Dunst."
  },
  AvgDialog_126912_Content_22 = {Text = "Das..."},
  AvgDialog_126912_Content_23 = {
    Text = "Der ernste Ausdruck von Doll, Ramonas Seufzer und Czorts Lehrstock blitzen sofort vor deinen Augen auf."
  },
  AvgDialog_126912_Content_24 = {
    Text = "Immer noch nicht... können..."
  },
  AvgDialog_126912_Content_25 = {
    Text = "Du lächelst unterwürfig und scheinst Thais' Zuneigung beiläufig zu vermeiden."
  },
  AvgDialog_126912_Content_26 = {
    Text = "In Ordnung, wie wäre es, wenn wir uns ruhig setzen und eine Weile plaudern?"
  },
  AvgDialog_126912_Content_27 = {
    Text = "Sag mir, Wächter... In diesem flüchtigen Moment, als dein Blick schwankte, an wen hast du gedacht?"
  },
  AvgDialog_126912_Content_28 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_126912_Content_29 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_126912_Content_3 = {
    Text = "Mit dem Grollen des Zuges war Wanda die erste, die die Stille durchbrach."
  },
  AvgDialog_126912_Content_30 = {
    Text = "Du erinnerst dich nicht, wie lange du schon erzählst, nur dass die vergangenen Ereignisse lebhaft in deinem Kopf klar sind."
  },
  AvgDialog_126912_Content_31 = {
    Text = "Und dann gibt es die Mensa in Mythag, die ein viel lebhafterer Ort ist als das Labor."
  },
  AvgDialog_126912_Content_32 = {
    Text = "Besonders wenn die Cupcakes verfügbar sind, stürzen die Kinder zur Theke und ignorieren dabei völlig die Eleganz und Tugend der Anmut und Bescheidenheit einer Dame..."
  },
  AvgDialog_126912_Content_33 = {
    Text = "Einige kleine Unruhestifter betrügen, indem sie ihre tierischen Freunde die Essensmarken halten lassen und Platz im Ausgabebereich einnehmen, und dann geben sie die gestohlenen Kuchen an ihre schüchternen Freunde weiter."
  },
  AvgDialog_126912_Content_34 = {
    Text = "<Shake:Und... Huh?>"
  },
  AvgDialog_126912_Content_35 = {
    Text = "Du stellst fest, dass deine Stimme erstickt ist und Tränen unkontrolliert aus deinen Augen rinnen."
  },
  AvgDialog_126912_Content_36 = {
    Text = "Es gibt mehr..."
  },
  AvgDialog_126912_Content_37 = {
    Text = "Tränen sammeln sich immer mehr an, wodurch mein Sehen zunehmend verschwommen wird."
  },
  AvgDialog_126912_Content_38 = {
    Text = "<Shake:Ich möchte wirklich nach Mythag zurückkehren, um wieder mit allen zusammen zu sein...>"
  },
  AvgDialog_126912_Content_39 = {
    Text = "Es ist seltsam. Ich habe Mythag nur <Yellow:drei Tage ago> verlassen, um Feldforschung zu betreiben. Es sollte nicht sein..."
  },
  AvgDialog_126912_Content_4 = {
    Text = "Ich habe einen Vorschlag."
  },
  AvgDialog_126912_Content_40 = {
    Text = "Aber die Qual der Sehnsucht lässt deine Nase schmerzen, als ob ein straff gespanntes Band in deinem Kopf kurz davor ist, zu reißen."
  },
  AvgDialog_126912_Content_41 = {
    Text = "Keine Sorge, keine Sorge, Hüter."
  },
  AvgDialog_126912_Content_42 = {
    Text = "Du bist in eine sanfte Umarmung gehüllt. Eine Umarmung der Mutter."
  },
  AvgDialog_126912_Content_43 = {
    Text = "@2 Ich verspreche dir, du wirst an den Ort zurückkehren, den du dir sehnst."
  },
  AvgDialog_126912_Content_44 = {
    Text = "Thais' Züge wurden verschwommen."
  },
  AvgDialog_126912_Content_45 = {
    Text = "Der neblige Dunst umhüllte euch beide, und du kuscheltest dich leise in ihren Arm und wurdest zu einem sehr kleinen Wesen."
  },
  AvgDialog_126912_Content_46 = {
    Text = "Du riechst den Duft. <Yellow:Der Duft von Magnolie>."
  },
  AvgDialog_126912_Content_47 = {
    Text = "<Red:Der Duft großer Magnolienblüten.>"
  },
  AvgDialog_126912_Content_48 = {
    Text = "Du findest dich in diesem duftenden Aroma eingehüllt, und versinkst in einen schlafähnlichen Zustand wie ein Baby, der dich all deine Sorgen und Ängste vergessen lässt."
  },
  AvgDialog_126912_Content_49 = {
    Text = "Bevor das Bewusstsein schwindet, erinnerst du dich nur an Mamas <Yellow:goldene, sehnsüchtige Augen>."
  },
  AvgDialog_126912_Content_5 = {
    Text = "Wir können uns zusammentun und in den Wagen 1 und 2 bleiben, damit wir aufeinander achten können."
  },
  AvgDialog_126912_Content_50 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_126912_Content_51 = {Text = "Dann—"},
  AvgDialog_126912_Content_52 = {
    Text = "Ein lautes \"Klang\" kam aus Auto Nummer eins."
  },
  AvgDialog_126912_Content_53 = {
    Text = "Du weißt, das Spiel des gegenseitigen Schlachtens läuft immer noch, und der Traum sollte erwachen."
  },
  AvgDialog_126912_Content_54 = {
    Text = "Wagen Nr. 1"
  },
  AvgDialog_126912_Content_55 = {
    Text = "Im Wagen Nr. 1 waren Wandas und Miryams schwer verletzte Körper miteinander verstrickt, ein Dolch war vollständig in Wandas Brust eingedrungen, während Miryam von unzähligen Stacheln durchbohrt wurde."
  },
  AvgDialog_126912_Content_56 = {
    Text = "Wanda öffnete langsam ihre benommenen Augen und zeigte euch allen intermittierend."
  },
  AvgDialog_126912_Content_57 = {
    Text = "Ich wusste, dass Miryam zuschlagen würde, also war ich bereit für einen \"Gegenangriff\"..."
  },
  AvgDialog_126912_Content_58 = {
    Text = "Jetzt hat N absolut keinen Weg, seinen Sieg zu erreichen..."
  },
  AvgDialog_126912_Content_59 = {
    Text = "Ihr müsst alle..."
  },
  AvgDialog_126912_Content_6 = {
    Text = "Ist es nicht gefährlich für die, die neben dem Mörder geblieben sind?"
  },
  AvgDialog_126912_Content_60 = {
    Text = "Wandas letzte Worte verwandelten sich in ein Flüstern. Der Segen in ihren letzten Worten wurde ebenfalls von der Stille verschluckt."
  },
  AvgDialog_126912_Content_61 = {
    Text = "Nach einer langen Stille sprach Thaïs schließlich mit zitternder Stimme."
  },
  AvgDialog_126912_Content_62 = {
    Text = "Es scheint, dass der Mörder tatsächlich Miryam ist. Sie wusste, dass sie unter der Regel der gegenseitigen Bewachung zwischen den beiden zuerst Wanda töten musste; andernfalls würden ihre Handlungen sicher die Feindseligkeit der verbleibenden Personen hervorrufen, also handelte sie."
  },
  AvgDialog_126912_Content_63 = {
    Text = "Wanda... genau weil sie weiß, dass sie im \"Gegenschlag\" hervorragend ist, hat sie die Initiative ergriffen, um ein Zimmer mit der Verräterin Miryam zu teilen."
  },
  AvgDialog_126912_Content_64 = {
    Text = "Sie tauschte ihr eigenes Opfer gegen den Sieg der \"guten Menschen\" ein"
  },
  AvgDialog_126912_Content_65 = {
    Text = "Thais' Ton war schwer, doch von Respekt durchzogen.\nWenn es nur aus dem Herzen kommen könnte."
  },
  AvgDialog_126912_Content_66 = {
    Text = "Was für eine Schande, das ist es nicht."
  },
  AvgDialog_126912_Content_67 = {
    Text = "Nein... Miryam... es ist nicht N, der in unsere Reihen infiltriert hat."
  },
  AvgDialog_126912_Content_68 = {
    Text = "<Shake:Nicht sie? Warum dann sie?...>"
  },
  AvgDialog_126912_Content_69 = {
    Text = "Für den Sieg, für das Gewinnen, für das von N versprochene \"Lemuria\", würde die Miryam, die ich kenne, tatsächlich so weit gehen, die Dinge selbst in die Hand zu nehmen."
  },
  AvgDialog_126912_Content_7 = {
    Text = "Aber das stellt zumindest sicher, dass N den endgültigen Sieg nicht erringt."
  },
  AvgDialog_126912_Content_70 = {Text = "Dann ..."},
  AvgDialog_126912_Content_71 = {
    Text = "Der wirkliche Verräter bist du. Thais, oder besser gesagt, <Yellow: jemand, der sich als Thais ausgibt>."
  },
  AvgDialog_126912_Content_72 = {
    Text = "Vielleicht war deine Vorbereitung ausreichend; Thais zeigte wenig Erstaunen, sondern sah dich mit ruhigem Auftreten und einem Hauch von Lächeln in die Augen."
  },
  AvgDialog_126912_Content_73 = {
    Text = "Oh? Wann hast du das herausgefunden? Ich würde gerne mehr hören."
  },
  AvgDialog_126912_Content_74 = {
    Text = "Nachdem Winkle... gegangen war, schlug Wanda vor, die beiden Fächer zu teilen."
  },
  AvgDialog_126912_Content_75 = {
    Text = "Wirklich... so früh? Ich dachte, die Methoden, die ich gewählt habe, wären vorsichtig genug und würden nicht viel Spuren hinterlassen."
  },
  AvgDialog_126912_Content_76 = {
    Text = "Die durchdringenden Wunden an Tinct könnten von Thais' Dornen, Wandas Stacheln oder dem Dolch stammen, den Miryam trägt."
  },
  AvgDialog_126912_Content_77 = {
    Text = "Was den Tod von Winkle betrifft... Thais, Wanda und Miryam haben alle die Fähigkeit, Vergiftung zuzufügen."
  },
  AvgDialog_126912_Content_78 = {
    Text = "In Anbetracht von Winkles Kaffeekonsum wird der Tod unweigerlich eintreten, sobald Gift in die Kaffeemaschine hinzugefügt wird."
  },
  AvgDialog_126912_Content_79 = {
    Text = "Also ja, was die Methoden zur Begehung des Verbrechens betrifft, war dein Verkleidung sehr erfolgreich."
  },
  AvgDialog_126912_Content_8 = {
    Text = "Ich werde Miryam im Auge behalten. Mach dir keine Sorgen, ich habe ein Trumpfkarte, mit der die andere Seite niemals rechnen würde."
  },
  AvgDialog_126912_Content_80 = {
    Text = "Was ist also die Grundlage deiner Argumentation...?"
  },
  AvgDialog_126912_Content_81 = {
    Text = "Hast du von einem Partyspiel namens \"Nacht des Blutmondes\" gehört? Jeden Blutmond öffnen die Werwölfe ihre Augen und beginnen zu jagen, nur um am nächsten Tag unter den guten Menschen zu verschwinden."
  },
  AvgDialog_126912_Content_82 = {
    Text = "Um die versteckten Werwölfe zu identifizieren, ist es entscheidend, die Motive aller während der Diskussionsphase zu erschließen. Die Werwölfe kennen die Identitäten der guten Spieler, daher sind ihre Anschuldigungen oft selbstbewusster."
  },
  AvgDialog_126912_Content_83 = {
    Text = "Die wahre Thais ist die Königin, die seit tausend Jahren in Aram in einen Schlaf gefallen ist. Ihr wahres Wesen steht in völliger Gegensatz zu ihrem Äußeren; sie handelt vorsichtig und ist sicherlich nicht jemand, der leicht Misstrauen gegenüber anderen hegt."
  },
  AvgDialog_126912_Content_84 = {
    Text = "Also hast du für mich und nicht für Miryam gestimmt."
  },
  AvgDialog_126912_Content_85 = {
    Text = "Ich habe mich entschieden, im selben Raum wie der Mörder zu sein."
  },
  AvgDialog_126912_Content_86 = {
    Text = "Ich war bereit, dich auf frischer Tat zu ertappen, als du zuschlugst, aber leider waren Miryams Aktionen schneller als deine..."
  },
  AvgDialog_126912_Content_87 = {
    Text = "Bevor du meine Hypnose abgeschlossen hast, hat sie bereits Wanda angegriffen."
  },
  AvgDialog_126912_Content_88 = {
    Text = "Wunderbar, wunderbare Überlegungen. Das beeindruckt mich wirklich."
  },
  AvgDialog_126912_Content_89 = {
    Text = "Nein, bei weitem nicht genug... Schließlich habe ich nicht vor, in dieser Geschichte die Rolle eines Detektivs gemäß der Anordnung von kleinem N zu spielen."
  },
  AvgDialog_126912_Content_9 = {
    Text = "Wanda schloss die Augen zusammen und zeigte ein beruhigendes Lächeln."
  },
  AvgDialog_126912_Content_90 = {
    Text = "Ich hätte es vorgezogen, eure Verschwörung zu stoppen, bevor der Vorfall eintrat. Aber es ist bereits zu spät."
  },
  AvgDialog_126912_Content_91 = {
    Text = "Heutzutage kann ich nur noch dich bitten, mir zu sagen... was deine wahre Gestalt wirklich ist?"
  },
  AvgDialog_126912_Content_92 = {
    Text = "Ein silbernes Licht bricht aus dem silbernen Schlüssel auf deiner Brust hervor und scheint alle flüchtigen Täuschungen zu durchdringen."
  },
  AvgDialog_126912_Content_93 = {
    Text = "Hehe, hehehehe~"
  },
  AvgDialog_126912_Content_94 = {
    Text = "Dein Angriff scheint ins Leere gegangen zu sein."
  },
  AvgDialog_126912_Content_95 = {
    Text = "Sie verwandelte sich in einen Hauch von Rauch, einen Hauch von Nebel, eine schwer fassbare und unbeschreibliche Präsenz."
  },
  AvgDialog_126912_Content_96 = {
    Text = "Komm, folge mir."
  },
  AvgDialog_126912_Content_97 = {
    Text = "Der Nebel kicherte leise und sprach eine mehrdeutige und unerklärliche Einladung an dich aus."
  },
  AvgDialog_126912_Content_98 = {
    Text = "Komm mit mir, um die Wahrheit der Geschichte aufzudecken."
  },
  AvgDialog_128696_Content_1 = {
    Text = "WUMM! WUMM! WUMM!"
  },
  AvgDialog_128696_Content_10 = {Text = "Nautila!"},
  AvgDialog_128696_Content_11 = {
    Text = "Mosk rannte hastig vor und legte sich auf Nautilas Brust, entdeckte, dass Nautila einfach zu müde war und in einen tiefen Schlaf gefallen war."
  },
  AvgDialog_128696_Content_12 = {
    Text = "Mosk atmete erleichtert auf und konnte nicht anders, als laut zu lachen."
  },
  AvgDialog_128696_Content_13 = {
    Text = "Pff, hahahahahaha!"
  },
  AvgDialog_128696_Content_14 = {
    Text = "Sie trug Nautila zum Bett und ignorierte deinen Widerstand, während sie dich ein paar große Runden über den Boden rollte."
  },
  AvgDialog_128696_Content_15 = {
    Text = "Flucht, wir müssen uns nicht trennen!"
  },
  AvgDialog_128696_Content_16 = {
    Text = "Dies ist Mosk's erste Gelegenheit, sich seit diesem Tag so entspannt zu fühlen; ihre Augen glänzen vor Hoffnung, während sie spielerisch mit ihrer Nase dein weiches Fell anstubst."
  },
  AvgDialog_128696_Content_17 = {
    Text = "Schlafen ... nur kurz ... morgen früh ... morgen früh ..."
  },
  AvgDialog_128696_Content_18 = {
    Text = "Mosk, die ebenfalls seit mehreren Tagen nicht geschlafen hat, hält dich fest und lehnt sich an die Ecke von Nautilas Bett, während sie ebenfalls in einen tiefen Schlaf fällt."
  },
  AvgDialog_128696_Content_19 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_128696_Content_2 = {
    Text = "Boom——Boom——Boom!"
  },
  AvgDialog_128696_Content_20 = {
    Text = "@2, Mosk, @4..."
  },
  AvgDialog_128696_Content_21 = {
    Text = "@4 kommt näher..."
  },
  AvgDialog_128696_Content_22 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_128696_Content_23 = {
    Text = "Das Schiff war erst seit einem halben Tag unterwegs, als ohne Vorwarnung ein gewaltiger Sturm aufkam."
  },
  AvgDialog_128696_Content_24 = {
    Text = "Der Kurs ist völlig verloren, der Regen fällt herab und lässt den übermütigen Herausforderern keine Möglichkeit, sich zurückzuziehen."
  },
  AvgDialog_128696_Content_25 = {
    Text = "Das Schiff's Steuer war seltsam fehljustiert, und egal wie sehr Nautila und Mosk es versuchten, selbst als sie es fast zerbrachen, gab es kein Zeichen dafür, dass es auf den richtigen Kurs zurückkehrte."
  },
  AvgDialog_128696_Content_26 = {
    Text = "Wie kann das sein, das darf nicht so sein! Es gab keinerlei Vorwarnung, der Luftdruck war völlig normal ... bis wir uns diesem Gewässer näherten, gab es überhaupt keine Probleme."
  },
  AvgDialog_128696_Content_27 = {
    Text = "Es ist einfach... Es ist fast so, als hätte dieser Strudel den Wirbelsturm heraufbeschworen, um gezielt eine Falle für uns zu stellen."
  },
  AvgDialog_128696_Content_28 = {Text = "Falle?"},
  AvgDialog_128696_Content_29 = {
    Text = "Gerade als wir dem Wirbel am nächsten waren, hätten wir nur noch fünf, nein, sogar drei Seemeilen gebraucht, um aus dem Einflussbereich des Wirbels herauszukommen."
  },
  AvgDialog_128696_Content_3 = {
    Text = "Der lange schlafende Stahlriese stößt ein heiseres Brüllen aus, das Nebelhorn ertönt, und zwischen dem Flattern der Möwen scheint das ganze Schiff langsam zum Leben zu erwachen."
  },
  AvgDialog_128696_Content_30 = {
    Text = "Dein Kopf ist bereits im Chaos, und du versuchst verzweifelt, einen Laut von dir zu geben. Was ist das...?"
  },
  AvgDialog_128696_Content_31 = {Text = "Ah, ah—!"},
  AvgDialog_128696_Content_32 = {
    Text = "Alles, was du tun kannst, ist einen verwirrten Schrei auszulassen; du verstehst nicht, können sie es nicht fühlen?"
  },
  AvgDialog_128696_Content_33 = {
    Text = "(Komm nicht näher zum Wirbel, großer Kerl, komm nicht näher zum Wirbel!)"
  },
  AvgDialog_128696_Content_34 = {
    Text = "Dieses enorme, furchterregende Wesen, er hat Mosk gesehen."
  },
  AvgDialog_128696_Content_35 = {
    Text = "<Red:Er hat nicht die Absicht, irgendjemanden gehen zu lassen.>"
  },
  AvgDialog_128696_Content_36 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_128696_Content_37 = {
    Text = "Keine Sorge, Kohleball, Mosk, hier."
  },
  AvgDialog_128696_Content_38 = {
    Text = "Ja, vertraue mir, Kohleball, Mosk. Es gibt einen Weg, ich werde definitiv einen Weg finden!"
  },
  AvgDialog_128696_Content_39 = {Text = "Nautila..."},
  AvgDialog_128696_Content_4 = {
    Text = "Der Motor. Der letzte Schritt..."
  },
  AvgDialog_128696_Content_40 = {
    Text = "Ich bin es, der das Schiff wegfahren muss. Ich habe euch hierher gebracht, und ich werde einen Weg finden. Ich werde dafür sorgen, dass ihr in Sicherheit seid!"
  },
  AvgDialog_128696_Content_41 = {
    Text = "<change:Öffne den Rumpf an dieser Stelle und lass Wasser als Ballast hinein...>"
  },
  AvgDialog_128696_Content_42 = {
    Text = "<Change>Nein ... @2 Antrieb, ja, wenn, solange ich einen der Motoren überlaste, um der Anziehungskraft von @1 zu entkommen"
  },
  AvgDialog_128696_Content_43 = {
    Text = "Das Mädchen raste mit dir und Mosk durch die verschiedenen Kammern, versuchte immer wieder verschiedene Möglichkeiten, während sich in ihren Augen allmählich ein wahnsinniges Blutrot breit machte."
  },
  AvgDialog_128696_Content_44 = {
    Text = "Klang——Peng!"
  },
  AvgDialog_128696_Content_45 = {Text = "Nautila..."},
  AvgDialog_128696_Content_46 = {
    Text = "Begleitet von Erschöpfung schlug der Schraubenschlüssel gegen die Wand und traf dann hart Nautilas Fuß; jedoch schien sie den Schmerz überhaupt nicht zu spüren und murmelte, dass sie den Schraubenschlüssel weiter aufheben wollte."
  },
  AvgDialog_128696_Content_47 = {
    Text = "<change>Es ist zu spät, der Wirbel kommt näher... Warum, warum, warum, WARUM!! Ich muss euch beide retten, ich muss... ich muss...!"
  },
  AvgDialog_128696_Content_48 = {
    Text = "Krack—Bumm—!"
  },
  AvgDialog_128696_Content_49 = {
    Text = "Der Sturm und die Schläge durchbrachen schließlich die Grenzen der Kabine. Nach einem klaren, knackenden Geräusch fielen die alten Planken schnell von über Nautilas Kopf—"
  },
  AvgDialog_128696_Content_5 = {
    Text = "Großartig! Mosk, Kohleball, wir haben es geschafft!"
  },
  AvgDialog_128696_Content_50 = {
    Text = "<Big:Nautila! Halt!>"
  },
  AvgDialog_128696_Content_51 = {
    Text = "Sie öffnete die Augen, die aus Angst geschlossen waren, und vor Nautila erschien ein unerwartetes Bild."
  },
  AvgDialog_128696_Content_52 = {
    Text = "Mosk lehnt sich einhändig an die Wand, um sich zu schützen, während die andere Hand die gesamte Decke stützt."
  },
  AvgDialog_128696_Content_53 = {Text = "Ugh..."},
  AvgDialog_128696_Content_54 = {Text = "Ha!"},
  AvgDialog_128696_Content_55 = {
    Text = "Mosk schob die Decke mit aller Kraft zur Seite, packte dann die fast verrückte Nautila, hielt ihr Gesicht mit beiden Händen, um ihren Blick auf sich zu fixieren."
  },
  AvgDialog_128696_Content_56 = {
    Text = "Alles gut, geh zurück, beim nächsten Mal."
  },
  AvgDialog_128696_Content_57 = {
    Text = "Zurück... aber..."
  },
  AvgDialog_128696_Content_58 = {
    Text = "Nautila blickte verwirrt umher und ließ den strömenden Regen auf sich niederprasseln."
  },
  AvgDialog_128696_Content_59 = {
    Text = "Der Sturm tobte mit Donner und Blitz, stimulierte jeden Nerv wie der unerbittliche Soundtrack eines dämonischen Festmahls."
  },
  AvgDialog_128696_Content_6 = {
    Text = "Nachher arbeitete Nautila fast schlaflos daran, den Schiffsrumpf zu reparieren. Es blieben noch drei Tage bis zur erwarteten Ankunft des Sturms, und alle kritischen Teile waren wieder an ihren richtigen Stellen."
  },
  AvgDialog_128696_Content_60 = {
    Text = "Die Schwerkraft des Wirbels ist zu stark, wir können nicht mehr zurückkehren..."
  },
  AvgDialog_128696_Content_61 = {
    Text = "Mosk ignorierte Nautilas Worte und zog den Taucheranzug aus der Kabine, während er ungeschickt versuchte, ihn Nautila in einer chaotischen Weise anzuziehen."
  },
  AvgDialog_128696_Content_62 = {
    Text = "Taucheranzug? Auf keinen Fall, ich ziehe ihn an, was wirst du tun?"
  },
  AvgDialog_128696_Content_63 = {
    Text = "In diesem Moment neigt sich der Rumpf bereits unkontrolliert vollständig in Richtung des Wirbels."
  },
  AvgDialog_128696_Content_64 = {
    Text = "<Shake:knarrend—Quiek Quiek—>"
  },
  AvgDialog_128696_Content_7 = {
    Text = "Solange ich den Anker noch ... puh ... so schläfrig ..."
  },
  AvgDialog_128696_Content_8 = {Text = "Platsch."},
  AvgDialog_128696_Content_9 = {
    Text = "Zirp?! Zirp—? (Mensch?! Mensch—?)"
  },
  AvgDialog_128697_Content_1 = {
    Text = "Gut. Besser. Am allerbesten!"
  },
  AvgDialog_128697_Content_10 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_128697_Content_11 = {Text = "*Jubel"},
  AvgDialog_128697_Content_12 = {
    Text = "Obwohl es tatsächlich eine gewisse Zerstörungskraft hat."
  },
  AvgDialog_128697_Content_13 = {
    Text = "Geheimnisträger! Mosk! Besiege die bösen Hausaufgaben! Unglaublich!"
  },
  AvgDialog_128697_Content_14 = {
    Text = "Hey ... Geheimnishüter ... Kohleball?!"
  },
  AvgDialog_128697_Content_15 = {
    Text = "Mosks tierähnliche Intuition spürte sofort etwas anderes. Sie sprang wie ein Tier auf und umarmte dich."
  },
  AvgDialog_128697_Content_16 = {
    Text = "Aua! Mosk, es tut weh!"
  },
  AvgDialog_128697_Content_17 = {
    Text = "Gleichzeitig fügte sie deinem armen Nasenrücken mit ihrem Mund einen schmerzhaften Schlag zu."
  },
  AvgDialog_128697_Content_18 = {
    Text = "Mundkäfig, Einschränkung, Mosk-Stahl, gut! Hehe, Mosk, sicher."
  },
  AvgDialog_128697_Content_19 = {
    Text = "Das von Misaq speziell entwickelte Gerät kontrolliert effektiv das Überlaufen der Stärke, und die derzeit maximale Zerstörungskraft von Mosk entspricht nur der eines leicht stärkeren gewöhnlichen Menschen."
  },
  AvgDialog_128697_Content_2 = {
    Text = "Hallo, Schutzherr. Bezüglich des Erweckers O-1841, da er gerade erst erwacht ist und gelegentlich Anzeichen von Wut zeigt und seine eigenen Fähigkeiten nicht vollständig kontrollieren kann, wird geraten, einen vorsichtigen Zustand bei der Interaktion mit ihm aufrechtzuerhalten."
  },
  AvgDialog_128697_Content_20 = {
    Text = "Freunde, später, ein sehr perfektes Abenteuer, oder? Nein?"
  },
  AvgDialog_128697_Content_21 = {
    Text = "Du hast viel Mühe investiert, um den ausgelassenen großen Hund von dir zu lösen. Sie stimmt schließlich zu, eine Weile ruhig gegenüber von dir am Schreibtisch zu sitzen, ihre Augen funkeln, während sie dich anstarrt."
  },
  AvgDialog_128697_Content_22 = {Text = "Hmm..."},
  AvgDialog_128697_Content_23 = {
    Text = "Eigentlich..."
  },
  AvgDialog_128697_Content_24 = {
    Text = "Unterhalb des Wirbels M- Muskus existiert ein gewaltiger Fusionsriss. Nautila und ich haben uns zwar vom Einfluss des Wirbels befreit, aber bei uns beiden zeigen sich grundsätzlich Anzeichen von Gedächtnisschwund."
  },
  AvgDialog_128697_Content_25 = {
    Text = "Du hast nur einen kurzen Moment pausiert und dich entschieden, “Ich“ als Ersatz für das Bewusstsein im Traum zu verwenden."
  },
  AvgDialog_128697_Content_26 = {
    Text = "Nautila hat seitdem nach dir gesucht. Sie hat ein Abenteurerteam gegründet, aber auf der Rückreise einen weiteren Unglücksfall erlebt..."
  },
  AvgDialog_128697_Content_27 = {
    Text = "Sie erinnert sich wahrscheinlich nicht mehr, aber... sie hat die gleiche Wahl getroffen wie du."
  },
  AvgDialog_128697_Content_28 = {
    Text = "So ist es..."
  },
  AvgDialog_128697_Content_29 = {
    Text = "Aber das ist großartig."
  },
  AvgDialog_128697_Content_3 = {
    Text = "Danke, Erica. Aber es ist in Ordnung, ich denke, ich kenne meinen... Freund gut genug."
  },
  AvgDialog_128697_Content_30 = {Text = "Natürlich"},
  AvgDialog_128697_Content_31 = {
    Text = "Natürlich gibt es das! Später, Nautila und ich..."
  },
  AvgDialog_128697_Content_32 = {
    Text = "Kurz gesagt, bis Nautila und ich zu alt zum Bewegen sind, werden wir verschiedene Abenteuer erleben."
  },
  AvgDialog_128697_Content_33 = {
    Text = "Du zermaterst dir das Gehirn, um all die Abenteuergeschichten, die du während deines kurzen, bewussten Lebens gehört hast, in deine Erzählung für Mosk zu verweben."
  },
  AvgDialog_128697_Content_34 = {
    Text = "Schließlich, oh mein Gott, kannst du diesen Augen wirklich nichts Gemeines sagen."
  },
  AvgDialog_128697_Content_35 = {
    Text = "Die Geschichte von Lu@2, Mosk, ich habe davon gehört."
  },
  AvgDialog_128697_Content_36 = {
    Text = "<Gray:Oh nein, ich habe vergessen, dass dies die Lektüre für den Allgemeinunterricht ist...>"
  },
  AvgDialog_128697_Content_37 = {
    Text = "Schon in Ordnung."
  },
  AvgDialog_128697_Content_38 = {Text = "Hey?"},
  AvgDialog_128697_Content_39 = {
    Text = "Mosk senkt den Kopf und drückt sein Gesicht, wie als du noch ein Kohleball warst, gegen deine Handfläche."
  },
  AvgDialog_128697_Content_4 = {
    Text = "Entgegen den Erwartungen der Akademie ist deine erste Verbindung mit diesem wütenden Erwecker ungewöhnlich reibungslos."
  },
  AvgDialog_128697_Content_40 = {
    Text = "Freund, Kohleball, wir sehen uns wieder."
  },
  AvgDialog_128697_Content_41 = {
    Text = "Kohleball, nach dem Durchlaufen der Dunkelheit, erinnere dich an Mosk, gut."
  },
  AvgDialog_128697_Content_42 = {
    Text = "Sie grinste und schenkte dir ein sehr, sehr glückliches Lächeln."
  },
  AvgDialog_128697_Content_43 = {
    Text = "Obwohl, das Armband ist weg."
  },
  AvgDialog_128697_Content_44 = {
    Text = "Aber unser Wiedersehen ist besser, besser als besser!"
  },
  AvgDialog_128697_Content_45 = {Text = "Mosk..."},
  AvgDialog_128697_Content_46 = {Text = "Piep?"},
  AvgDialog_128697_Content_47 = {
    Text = "?? Warum ist hier ein Seeotter mit einem Mythag-Hut?"
  },
  AvgDialog_128697_Content_48 = {
    Text = "Entschuldigung, Schutzherr, es scheint, dass viele Schüler dieses ausländische Otter sehr mögen und ihm einige unnötige Dekorationen gegeben haben."
  },
  AvgDialog_128697_Content_49 = {
    Text = "Erica wird das Ausweisungsverfahren so schnell wie möglich einleiten, 1, 2——"
  },
  AvgDialog_128697_Content_5 = {
    Text = "Nach diesem unerwarteten Traum denkst du, dass du die Antwort gefunden hast."
  },
  AvgDialog_128697_Content_50 = {
    Text = "Ah, ein Seeotter! So niedlich, lass uns mit Mosk spielen!"
  },
  AvgDialog_128697_Content_51 = {
    Text = "Bumm. Dong. Klong—"
  },
  AvgDialog_128697_Content_52 = {Text = "Bang!"},
  AvgDialog_128697_Content_53 = {
    Text = "Zisch, Mosk!"
  },
  AvgDialog_128697_Content_54 = {
    Text = "Sobald Nautila das Klassenzimmer betrat, sah sie ihren neuen Freund, der einem Seeotter mit einem Misaq-Hut hinterherjagte und das Lehrmaterial durcheinanderbrachte."
  },
  AvgDialog_128697_Content_55 = {
    Text = "Schutzherr, sag Professorin Erica, dass ich alles im Klassenzimmer reparieren werde!"
  },
  AvgDialog_128697_Content_56 = {
    Text = "Mosk, hör schnell auf!"
  },
  AvgDialog_128697_Content_57 = {Text = "Ah—Ah!"},
  AvgDialog_128697_Content_58 = {Text = "Autsch!!"},
  AvgDialog_128697_Content_59 = {Text = "*Jubel"},
  AvgDialog_128697_Content_6 = {
    Text = "Sie mag gegrilltes Fleisch, liebt das Meer, ist sehr schüchtern, hasst die Kälte, die Dunkelheit und die Einsamkeit und weint leise, wenn sie ihnen gegenübersteht."
  },
  AvgDialog_128697_Content_60 = {
    Text = "Wenn ich richtig verstanden habe, sagt dieser Seeotter “spiel mit mir“, richtig...? Wie kommuniziert er mit Mosk?"
  },
  AvgDialog_128697_Content_61 = {
    Text = "Hey, warte mal, warum kann ich auch verstehen, was der Seeotter sagt?!"
  },
  AvgDialog_128697_Content_62 = {
    Text = "Warte, so ist es..."
  },
  AvgDialog_128697_Content_63 = {
    Text = "Hust hust, unbekannter Misaq-Seelöwe, ich werde dir jetzt den Titel Kohleball verleihen."
  },
  AvgDialog_128697_Content_64 = {
    Text = "Du wirst den Namen des Kohleballs erben und der große, glorreiche Kohleball der Zweite werden!"
  },
  AvgDialog_128697_Content_65 = {Text = "!"},
  AvgDialog_128697_Content_66 = {
    Text = "Kohleball, der Zweite! Kohleball, der Zweite!"
  },
  AvgDialog_128697_Content_67 = {
    Text = "Piep—(Seehundwirkung!)"
  },
  AvgDialog_128697_Content_68 = {
    Text = "Nautila——"
  },
  AvgDialog_128697_Content_69 = {
    Text = "Großartig, es ist ein völliges Durcheinander——"
  },
  AvgDialog_128697_Content_7 = {
    Text = "Am Nachmittag ist das Sonnenlicht in Misaq angenehm. Die Sonne scheint durch das farbige Glas und wirft Licht auf das Gesicht des Mädchens, das mit ihrem Sprachbuch kämpft."
  },
  AvgDialog_128697_Content_70 = {
    Text = "Und so ist es als mein rechtmäßiger Erbe <Small:deine feierliche Pflicht, das zu erledigen, was mir, Kohleball dem Ersten, missfällt...>"
  },
  AvgDialog_128697_Content_71 = {
    Text = "Du pfeifst lässig, leise, leise—"
  },
  AvgDialog_128697_Content_72 = {
    Text = "Ich warf meine Analysis-Hausaufgaben im Chaos auf die Pfote des Seeotters."
  },
  AvgDialog_128697_Content_73 = {
    Text = "Im Handumdrehen verwandelte sich die Hausaufgabe in einen zerknitterten Haufen Papiermüll, der leise im Papiermüllhaufen lag."
  },
  AvgDialog_128697_Content_74 = {
    Text = "Was für ein schöner Tag, oder, Nautila, Mosk?"
  },
  AvgDialog_128697_Content_75 = {Text = "Ah—!"},
  AvgDialog_128697_Content_76 = {
    Text = "Heute ist Misaq auch sehr freundlich und friedlich."
  },
  AvgDialog_128697_Content_77 = {
    Text = "Herzlichen Glückwunsch, herzlichen Glückwunsch."
  },
  AvgDialog_128697_Content_8 = {
    Text = "Aber sie ist auch sehr mutig, bereit, sich für ihre Freunde allem, was sie nicht mag, entgegenzustellen."
  },
  AvgDialog_128697_Content_9 = {
    Text = "Zisch—Das Lehrbuch zerbrach in zwei Hälften in der gerade aufkommenden emotionalen Atmosphäre."
  },
  AvgDialog_128698_Content_1 = {
    Text = "Platsch～Platsch～"
  },
  AvgDialog_128698_Content_10 = {
    Text = "Mit Antrieb und Treibstoff gibt es keine Probleme, aber der Schiffsrumpf ist wirklich zu dünn ... Mosk, gibt es eine Möglichkeit, den großen Wirbel zu umgehen? Die frühere Flotte hatte genau in seiner Nähe einen Unfall."
  },
  AvgDialog_128698_Content_11 = {
    Text = "...Kann nicht raus."
  },
  AvgDialog_128698_Content_12 = {
    Text = "Mosk schüttelt den Kopf, hebt dich wieder hoch, und zusammen versucht ihr beide, mit vier Händen und vier Füßen heftig zu gestikulieren."
  },
  AvgDialog_128698_Content_13 = {
    Text = "Böse Menschen, fangen Mama und Papa. Mosk, beißen, weggebracht. Kohleball, auf Schiff, treffen."
  },
  AvgDialog_128698_Content_14 = {
    Text = "Das Meer, ruf—hier, Mosk, denk dir etwas aus, keine Möglichkeit."
  },
  AvgDialog_128698_Content_15 = {
    Text = "Du wurdest von schlechten Menschen hierher gebracht, und nachdem du von Mama und Papa getrennt wurdest, konntest du nicht wieder raus?"
  },
  AvgDialog_128698_Content_16 = {
    Text = "Nicht hier, Papa und Mama."
  },
  AvgDialog_128698_Content_17 = {
    Text = "Entschuldigung..."
  },
  AvgDialog_128698_Content_18 = {
    Text = "Recht, Papa und Mama, kommt schon!"
  },
  AvgDialog_128698_Content_19 = {
    Text = "Mosk! Wohin ziehst du mich?!"
  },
  AvgDialog_128698_Content_2 = {
    Text = "Egal, solange dieses Lager vollständig repariert ist, wird das Steuerrad..."
  },
  AvgDialog_128698_Content_20 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_128698_Content_21 = {
    Text = "Puh... Puh, bist du ein Monster?! Warum kannst du so schnell schwimmen, während du mich trägst?!"
  },
  AvgDialog_128698_Content_22 = {
    Text = "Hey, was ist das für ein Ort?"
  },
  AvgDialog_128698_Content_23 = {Text = "Ah—!"},
  AvgDialog_128698_Content_24 = {
    Text = "Du sprangst fröhlich als Erster ins Wasser und erschrecktest die Fische um dich herum."
  },
  AvgDialog_128698_Content_25 = {
    Text = "Während du und Mosk nacheinander mit Jubel ins Wasser platschtet, stiegen Wellen aus den Tiefen empor, als würden sie auf eure Rufe antworten."
  },
  AvgDialog_128698_Content_26 = {
    Text = "Mama, Papa, so wie sie! Nautila, Mosk, das Gleiche!"
  },
  AvgDialog_128698_Content_27 = {
    Text = "Mehrere schöne, weiße Delfine schwimmen aus der Tiefe auf, umgeben euch und streichen liebevoll mit ihren Schnauzen und Rückenflossen gegen euch und Mosk."
  },
  AvgDialog_128698_Content_28 = {
    Text = "Sie schwimmen leicht um euch herum, springen sogar aus dem Wasser, um Nautila ein wenig Wasserfontänen zuzuspülen, als würden sie sie einladen."
  },
  AvgDialog_128698_Content_29 = {
    Text = "Das sind... Delfine? Mosk, willst du sagen, dass deine Eltern auch Delfine sind?"
  },
  AvgDialog_128698_Content_3 = {
    Text = "Schiff usurpieren?"
  },
  AvgDialog_128698_Content_30 = {
    Text = "Ja. Kleiner Mosk, verloren. Delfine, füttern kleinen Mosk. Mosk, aufgewachsen!"
  },
  AvgDialog_128698_Content_31 = {
    Text = "Mosk, hey, Kohleball, Kohleball, wach auf!"
  },
  AvgDialog_128698_Content_32 = {
    Text = "Mosk kicherte, als sie den Wasserspritzern, die du wütend auf sie warfst, auswich, und dann streckten ihr beide die Hände nach Nautila aus."
  },
  AvgDialog_128698_Content_33 = {
    Text = "Vertraue mir, Freund."
  },
  AvgDialog_128698_Content_34 = {Text = "...Okay!"},
  AvgDialog_128698_Content_35 = {
    Text = "Nautila hält fest eure Hände. Eine vorne, eine hinten, führt ihr und Mosk Nautila zu einer versteckten Höhle."
  },
  AvgDialog_128698_Content_36 = {
    Text = "Nach einer kurzen Dunkelheit erwacht ein, zwei ... unzählige traumhafte, schemenhafte Lichtschimmer. Die Quallen strömen an die Wasseroberfläche, werden sanft vom Wirbel weggetragen, bis helleres Licht vom Gewölbe herabfällt."
  },
  AvgDialog_128698_Content_37 = {
    Text = "... Ich ... träume doch nicht gerade, oder?"
  },
  AvgDialog_128698_Content_38 = {
    Text = "Das Sonnenlicht dringt durch die Gesteinsschichten und spiegelt tiefe und flache Blautöne auf der bodenlosen Meeresoberfläche wider. Bunte Korallen durchschneiden das Blau erneut und präsentieren zusammen mit zahlreichen Meeresbewohnern eine Szene, die einen sprachlos macht."
  },
  AvgDialog_128698_Content_39 = {
    Text = "Die giftigen Tentakeln der Seeanemonen tanzen in einem langsamen, hypnotischen Tanz. Schalentiere schmiegen sich eng an sie und leben in stiller Harmonie mit ihnen. Raubtiere lauern im Dunkel des Abgrunds und warten auf ihre Gelegenheit. Dieser Ort ist gefährlich und schön, dunkel und prächtig — eine eigene Welt, ein Miniaturozean."
  },
  AvgDialog_128698_Content_4 = {
    Text = "Das Steuerrad ist wie ein Lenkrad, etwas, das die Richtung kontrolliert. Weißt du, was ein Lenkrad ist?"
  },
  AvgDialog_128698_Content_40 = {Text = "Nautila?"},
  AvgDialog_128698_Content_41 = {
    Text = "Das hier, schön, für dich."
  },
  AvgDialog_128698_Content_42 = {
    Text = "Mosk wusste nicht, wann, nahm eine Perle heraus, die einen schimmernden Glanz ausstrahlte, und legte sie mit einem sehr, sehr ernsten Gesichtsausdruck in Nautilas Handfläche."
  },
  AvgDialog_128698_Content_43 = {
    Text = "Mosk, hier, mag. Mosk, Schatz, mag. Nautila, Freund, für dich."
  },
  AvgDialog_128698_Content_44 = {
    Text = "(Ich habe dich so oft danach gefragt und du hast es mir nie gegeben, großer Kerl, schlecht!)"
  },
  AvgDialog_128698_Content_45 = {
    Text = "Obwohl du innerlich so vor dich hin murmelst, denkst du an den köstlichen gebratenen Fisch und die geschmorten Meeresfrüchte, die du in letzter Zeit gegessen hast, und schubst großzügig die Perle zusammen mit Mosk in die Hand von Nautila."
  },
  AvgDialog_128698_Content_46 = {
    Text = "Oh — danke! Nun, dann habe ich auch ein Geschenk für Mosk."
  },
  AvgDialog_128698_Content_47 = {Text = "Lis Haus?"},
  AvgDialog_128698_Content_48 = {
    Text = "Nautila bindet das kleine Armband von ihrem Handgelenk ab — das, das sie immer trägt, verziert mit einem kleinen Nautilus-Anhänger."
  },
  AvgDialog_128698_Content_49 = {
    Text = "Etwas, das ein Freund einem Freund gibt, nennt man ein „Geschenk\". Die Perle ist dein Geschenk an mich. Und das hier... das ist mein Geschenk an dich."
  },
  AvgDialog_128698_Content_5 = {Text = "Hm...?"},
  AvgDialog_128698_Content_50 = {
    Text = "Meine Mutter hat mir eine Halskette und ein Armband geschenkt, und wir haben vereinbart, große Abenteurer zu werden."
  },
  AvgDialog_128698_Content_51 = {
    Text = "Mosk, ich werde das Schiff bald reparieren. Wir werden zusammen aufbrechen und deine Eltern suchen."
  },
  AvgDialog_128698_Content_52 = {
    Text = "Und danach... würdest du dieses Armband tragen, Kohleball mitnehmen und mit mir auf Abenteuer gehen?"
  },
  AvgDialog_128698_Content_53 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_128698_Content_54 = {
    Text = "Nautila, Mosk, Kohleball, Abenteuer!"
  },
  AvgDialog_128698_Content_55 = {Text = "Ja hu!"},
  AvgDialog_128698_Content_56 = {
    Text = "Nach einer kurzen Stille, die fast wie eine Illusion erschien, hob Mosk ihr strahlendes Lächeln wie immer an und umarmte dich, während sie einen Jubel ausstieß."
  },
  AvgDialog_128698_Content_57 = {
    Text = "Zirp! (Abenteuer!)"
  },
  AvgDialog_128698_Content_58 = {
    Text = "Was kannst du wahrnehmen? Du bist nur ein Seeotter. Selbst wenn du einen Hauch von etwas aufgeschnappt hast, kann dein kleines Gehirn es nicht ganz erfassen. Und so lässt du es los und tauchst kopfüber in die fröhliche Atmosphäre ein."
  },
  AvgDialog_128698_Content_59 = {
    Text = "Super, Kohleball, ich habe auch ein Geschenk für dich vorbereitet!"
  },
  AvgDialog_128698_Content_6 = {
    Text = "Das Lenkrad ist das, was die Richtung aller großen Dinge steuert. Wohin das Lenkrad die Straße weist, dorthin werden das Schiff und das Auto fahren."
  },
  AvgDialog_128698_Content_60 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_128698_Content_61 = {Text = "!"},
  AvgDialog_128698_Content_62 = {
    Text = "Die einst heruntergekommene Kajüte hat sich jetzt vollständig verwandelt; zwischen zwei identischen, einfachen, aber sauberen und stabilen Betten steht eine Holzkiste, gefüllt mit weichen Kissen."
  },
  AvgDialog_128698_Content_63 = {
    Text = "Hehe, jetzt hat jeder sein eigenes Bett."
  },
  AvgDialog_128698_Content_64 = {
    Text = "Noch bevor Nautilas Stimme verklungen ist, fielst du kopfüber in dein perfektes kleines Nest — Nautila hat sogar einen besonderen Platz für deine kostbaren kleinen Muscheln freigelassen!"
  },
  AvgDialog_128698_Content_65 = {
    Text = "Die Meeresfrüchtesuppe vom Abendessen wärmt immer noch deinen Bauch, und bald fällst du in den Schlaf beim gleichmäßigen Atmen der Mädchen."
  },
  AvgDialog_128698_Content_66 = {
    Text = "Aber wenn die Nacht wirklich hereinbricht, breitet sich der unheilvolle Faden wie der dicke Nachtnebel über das Meer aus."
  },
  AvgDialog_128698_Content_67 = {
    Text = "<Shake:Mosk, @3...>"
  },
  AvgDialog_128698_Content_68 = {
    Text = "<Shake:Rückgabe zu mir, unterwirf dich mir, @4...@4!>"
  },
  AvgDialog_128698_Content_69 = {
    Text = "In der Dunkelheit wird das Meer von Schrecken und Geheimnis erfüllt. Sonnenlicht berührt die Oberfläche nicht mehr, und tief im Abgrund regt sich etwas mit einem tiefen, kehligen Grollen."
  },
  AvgDialog_128698_Content_7 = {
    Text = "Ohhhh! Ein Lenkrad! Das ist so cool!"
  },
  AvgDialog_128698_Content_70 = {
    Text = "Du treibst in der grenzenlosen Leere und Kälte und versuchst verzweifelt, dich der Gestalt in der Ferne zu nähern, die leise weint."
  },
  AvgDialog_128698_Content_71 = {
    Text = "Ah— (Großer Kerl—)"
  },
  AvgDialog_128698_Content_72 = {
    Text = "Ah! (Großer Kerl!)"
  },
  AvgDialog_128698_Content_73 = {
    Text = "Du wirst plötzlich wach, ohne das sanfte Atmen der Mädchen im tiefen Schlaf; alles ist still, du krabbelst aus deinem Nest und folgst dem Duft von Mosk auf das Deck."
  },
  AvgDialog_128698_Content_74 = {
    Text = "Sie sieht auf den fernen Wirbel."
  },
  AvgDialog_128698_Content_75 = {
    Text = "(Der Traum wieder, wie oft ist es seit dem Tod dieser nervigen Menschen gewesen, seit wir uns hier niedergelassen haben?)"
  },
  AvgDialog_128698_Content_76 = {
    Text = "Ruf, Mosk, dort."
  },
  AvgDialog_128698_Content_77 = {
    Text = "Unheimlich... nein..."
  },
  AvgDialog_128698_Content_78 = {
    Text = "Hey, Kohleball, Mosk, warum seid ihr draußen?"
  },
  AvgDialog_128698_Content_79 = {
    Text = "Nautilas Stimme unterbrach Mosks gemurmelndes Flüstern, und im nächsten Moment schob Nautila aufgeregt ein Set von Eisenblechen vor, um es euch zu zeigen."
  },
  AvgDialog_128698_Content_8 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_128698_Content_80 = {
    Text = "Mosk, hast du nicht vorher gesagt, dass es unangenehm wäre, zu tief zu tauchen, aber du willst trotzdem wirklich hingehen und nachsehen?"
  },
  AvgDialog_128698_Content_81 = {
    Text = "Ich habe den Taucheranzug repariert, den ich auf dem Schiff gefunden habe. Mit diesem kannst du länger tauchen, ohne dich unwohl zu fühlen."
  },
  AvgDialog_128698_Content_82 = {
    Text = "Schade, dass ich das Schiff reparieren muss, bevor der nächste Sturm kommt. Nach dem Sturm mache ich mir auch einen."
  },
  AvgDialog_128698_Content_83 = {
    Text = "Eines Tages werden wir zusammen das Meer erkunden können!"
  },
  AvgDialog_128698_Content_84 = {
    Text = "Mosk wird selten ruhig. Nach einem Moment nickte sie energisch, hob dich hoch und umarmte Nautila fest."
  },
  AvgDialog_128698_Content_85 = {Text = "Flucht."},
  AvgDialog_128698_Content_86 = {
    Text = "Mosk, Nautila, Kohleball, Flucht! Zusammen!"
  },
  AvgDialog_128698_Content_9 = {
    Text = "Laut den Instrumentendaten haben wir höchstens eine Woche, bevor ein Sturm kommt—einer, der mindestens einen halben Monat andauern wird. Dieses Schiff ist schon in schlechtem Zustand... Ich weiß nicht, ob es den Sturm überhaupt übersteht."
  },
  AvgDialog_128699_Content_1 = {
    Text = "Pitter, patter."
  },
  AvgDialog_128699_Content_10 = {
    Text = "Mosk, hör mir zu, es war mein Vorschlag, die Segel zu setzen, und es war auch mein Fehler in der Wetterberechnung, daher habe ich die Pflicht, dich und den Kohleball zu retten."
  },
  AvgDialog_128699_Content_11 = {
    Text = "Ich ziehe dir sofort den Taucheranzug aus. Das Schiff kann noch fahren, und ich werde mein Bestes tun, um es an den Rand des Wirbels zu steuern. Bis dahin wirst du..."
  },
  AvgDialog_128699_Content_12 = {Text = "Du..."},
  AvgDialog_128699_Content_13 = {
    Text = "Nautila stand regungslos da, als sie sah, dass das zuvor unschuldige, lebhafte, unbeschwerte Mädchen selten einen komplexen Ausdruck von Sorge zeigte."
  },
  AvgDialog_128699_Content_14 = {
    Text = "Nautila, Entschuldigung."
  },
  AvgDialog_128699_Content_15 = {
    Text = "Mosk streckte die Hand aus. Obwohl sie nicht verstand, wie das Gerät funktionierte, vollendete sie mit biestartiger Intuition die Montage des Taucheranzugs an Nautila."
  },
  AvgDialog_128699_Content_16 = {
    Text = "Mosk, Gefahr, Vorahnung."
  },
  AvgDialog_128699_Content_17 = {
    Text = "Aber, Erwartung, wird nicht passieren."
  },
  AvgDialog_128699_Content_18 = {
    Text = "Regenwasser sickert durch das Loch im Dach und spritzt auf die beiden."
  },
  AvgDialog_128699_Content_19 = {
    Text = "Die Stille erfüllte den Raum, und schließlich war es Mosk, der die Schwere durchbrach."
  },
  AvgDialog_128699_Content_2 = {
    Text = "<Shake:knarrend—Quiek Quiek—>"
  },
  AvgDialog_128699_Content_20 = {
    Text = "Mosk, komm hierher, Traum."
  },
  AvgDialog_128699_Content_21 = {
    Text = "Mosk träumte von... etwas, das Mosk genannt wurde..."
  },
  AvgDialog_128699_Content_22 = {
    Text = "Aber, will nicht gehen. Kalt, niemand da, einsam..."
  },
  AvgDialog_128699_Content_23 = {
    Text = "Nautila wurde plötzlich klar, warum der Starkregen früher einsetzte, warum der Tornado ohne Vorwarnung erschien. Sie begann unkontrolliert zu zittern."
  },
  AvgDialog_128699_Content_24 = {
    Text = "Das Ding... genau dort..."
  },
  AvgDialog_128699_Content_25 = {
    Text = "Folgend von Mosks Finger spürte Nautila eine Angst, die sich in ihrem Unterbewusstsein ausbreitete."
  },
  AvgDialog_128699_Content_26 = {
    Text = "Angst aus den Tiefen des Merscus-Wirbels, die über sterbliche Dinge hinausgeht."
  },
  AvgDialog_128699_Content_27 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_128699_Content_28 = {
    Text = "Nein, nein, nein — ich weiß, was du vorhast, auf keinen Fall!"
  },
  AvgDialog_128699_Content_29 = {
    Text = "Vertraue mir, es muss einen anderen Weg geben!"
  },
  AvgDialog_128699_Content_3 = {
    Text = "Der tobende Strudel ist wie eine riesige Hand, die das Schiff wie ein Handtuch verdrehen will."
  },
  AvgDialog_128699_Content_30 = {
    Text = "Nautila drängte sich ängstlich gegen Mosk. Obwohl Mosk mit ihrer Stärke sich jederzeit aus der Fessel befreien könnte, tat das das bestialische Mädchen nicht."
  },
  AvgDialog_128699_Content_31 = {
    Text = "Sie hob dich einfach hoch und schnuffelte liebevoll an dir."
  },
  AvgDialog_128699_Content_32 = {
    Text = "Freund, stark, aber, nein. Nur, Mosk, kann."
  },
  AvgDialog_128699_Content_33 = {
    Text = "Nur Mosk kann."
  },
  AvgDialog_128699_Content_34 = {
    Text = "...Warum, warum ist das so."
  },
  AvgDialog_128699_Content_35 = {
    Text = "Freund, weine nicht, lächle, Mosk, ich mag es!"
  },
  AvgDialog_128699_Content_36 = {
    Text = "Äh, Entschuldigung, ich habe gesehen, dass ihr alle rohen Fisch esst, also habe ich ihn etwas verarbeitet ... Auch wenn es keine Gewürze gibt, möchtet ihr kosten?"
  },
  AvgDialog_128699_Content_37 = {Text = "Auu!"},
  AvgDialog_128699_Content_38 = {Text = "Auu!"},
  AvgDialog_128699_Content_39 = {Text = "Lecker"},
  AvgDialog_128699_Content_4 = {
    Text = "Der Rumpf gab unter der Last ein quälendes Geräusch von sich, und Mosk schrie fast im Sturm, während sie verzweifelt Nautila in den Taucheranzug stopfte und dich festhielt, um zu verhindern, dass du abgeworfen wirst."
  },
  AvgDialog_128699_Content_40 = {
    Text = "Abenteuer, ich freue mich darauf!"
  },
  AvgDialog_128699_Content_41 = {
    Text = "Mosk, ich werde das Schiff bald reparieren können und dich von hier wegbringen, um deine Mama und deinen Papa zu finden."
  },
  AvgDialog_128699_Content_42 = {
    Text = "Möchtest du danach dieses Armband nehmen, Coalsie mitnehmen und mit mir auf ein Abenteuer gehen?"
  },
  AvgDialog_128699_Content_43 = {
    Text = "Nautila, Mosk, Kohleball, Abenteuer!"
  },
  AvgDialog_128699_Content_44 = {
    Text = "Freund, ich mag es!"
  },
  AvgDialog_128699_Content_45 = {
    Text = "Freund, ich habe es so viel an Mosk gegeben!"
  },
  AvgDialog_128699_Content_46 = {
    Text = "Also möchte Mosk den Freunden viel, viel geben!"
  },
  AvgDialog_128699_Content_47 = {
    Text = "Sie schien sich wie eine Mauer im Sturm aufgebaut zu haben, die dich und Nautila fest in der Mitte einschloss. Dann atmete sie tief ein, öffnete den Mund und zeigte Mosks einzigartiges, beruhigendes Lächeln."
  },
  AvgDialog_128699_Content_48 = {
    Text = "Mosk, auf jeden Fall, wird zurückkommen!"
  },
  AvgDialog_128699_Content_49 = {
    Text = "...In Ordnung, ich glaube an Mosk. Wenn du zurückkommst, werde ich das beste Schiff der Welt vorbereiten und dich sowie Kohleball auf das größte Abenteuer mitnehmen."
  },
  AvgDialog_128699_Content_5 = {
    Text = "Gefahr! Festhalten!"
  },
  AvgDialog_128699_Content_50 = {
    Text = "Nautila wischte sich die Tränen ab, raffte sich zusammen und zeigte ein etwas hässliches Lächeln."
  },
  AvgDialog_128699_Content_51 = {
    Text = "Als sie sieht, dass Nautila sie endlich loslässt, nimmt Mosk leise, ganz leise deine Pfote in ihre und drückt ihr Gesicht gegen deine Pfotenballen."
  },
  AvgDialog_128699_Content_52 = {
    Text = "Nein, fürchte dich nicht."
  },
  AvgDialog_128699_Content_53 = {
    Text = "Ah... Ah! (Du wirst mich verlassen...)"
  },
  AvgDialog_128699_Content_54 = {
    Text = "Ah!! Ah—(Du wirst mich verlassen!!)"
  },
  AvgDialog_128699_Content_55 = {
    Text = "Du wirst in Nautilas Umarmung gestoßen, während die durchdringenden Schreie ertönen, und im nächsten Moment wendet sich Mosk ohne Zögern um und stürzt in Richtung des Wirbels."
  },
  AvgDialog_128699_Content_56 = {Text = "...Plop."},
  AvgDialog_128699_Content_57 = {
    Text = "Wie ein Fisch, der in ihr Meer eintaucht."
  },
  AvgDialog_128699_Content_58 = {Text = "Mosk!!"},
  AvgDialog_128699_Content_59 = {
    Text = "Der Sturm übertönte alle Schreie, massive Wellen schwollen auf das Deck und zogen euch ins Meer."
  },
  AvgDialog_128699_Content_6 = {Text = "Boom—"},
  AvgDialog_128699_Content_60 = {
    Text = "Unter dem schwarzblauen Meerwasser breiteten sich unzählige fadenartige schwarze Schleime in Richtung Mosk aus. Ihre Hände verwandelten sich in massive Strudel, ihr Ausdruck war friedlich und gelassen, und in den tiefen, ruhigen Augen schien es wie das Zentrum eines Wirbels."
  },
  AvgDialog_128699_Content_61 = {
    Text = "Mosk, Strudel. Mosk, Steuerrad."
  },
  AvgDialog_128699_Content_62 = {
    Text = "Kohleball, Nautila, hier, immer."
  },
  AvgDialog_128699_Content_63 = {
    Text = "Mosk kann schließlich nicht anders und bricht in Tränen aus, drückt ihre Hand gegen ihre eigene Brust."
  },
  AvgDialog_128699_Content_64 = {
    Text = "Dann hebt sie ihre Hand. Ein Wirbel mit zerstörerischer Kraft, doch ungewöhnlich sanft, schiebt euch beide weit, weit weg vom Strudel."
  },
  AvgDialog_128699_Content_65 = {
    Text = "Ein Faden nach dem anderen haftete der Schleim an Mosks Körper und kroch schnell über ihren ganzen Körper."
  },
  AvgDialog_128699_Content_66 = {
    Text = "Der Wirbel begann, sich gegen das Zentrum hin zu bündeln, um seine Wünsche zu erfüllen. Das Mädchen wurde von unzähligen schwarzen Algen umschlungen und gezogen und sank allmählich in den düsteren Meeresboden."
  },
  AvgDialog_128699_Content_67 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_128699_Content_68 = {
    Text = "Alles hat sich gelegt, der Himmel ist klar, und die Boote treiben ruhig auf der friedlichen Meeresoberfläche."
  },
  AvgDialog_128699_Content_69 = {
    Text = "Hmm, wo bin ich hier, warum bin ich im Wasser? Ugh, es ist so stickig!"
  },
  AvgDialog_128699_Content_7 = {
    Text = "Das gewaltsame Zittern schleuderte Nautila weg und sie krachte gegen ein Holzfass, das auf dem Boden rollte."
  },
  AvgDialog_128699_Content_70 = {
    Text = "Du wirfst einen seltsamen Blick auf den merkwürdig gekleideten Menschen, der auf dem Wasser schwebt."
  },
  AvgDialog_128699_Content_71 = {
    Text = "(Wie bin ich hierher gelandet, und wer ist dieser Typ?)"
  },
  AvgDialog_128699_Content_72 = {
    Text = "Platsch, platsch."
  },
  AvgDialog_128699_Content_73 = {
    Text = "Platsch, platsch."
  },
  AvgDialog_128699_Content_74 = {
    Text = "(Ach richtig, ich bin ein Seeotter! Und Seeotter suchen nach Muscheln. Muscheln, Muscheln, Muscheln!)"
  },
  AvgDialog_128699_Content_75 = {
    Text = "Du tauchst glücklich in das warme Wasser und schwimmst in die entgegengesetzte Richtung zu dem Menschen, der sich mühsam in Richtung des Schiffes kämpft."
  },
  AvgDialog_128699_Content_76 = {
    Text = "Du hast nicht bemerkt, dass du in die Tränen im Meer verschmolzen bist."
  },
  AvgDialog_128699_Content_8 = {Text = "Ugh..."},
  AvgDialog_128699_Content_9 = {
    Text = "Nautila biss die Zähne zusammen vor Schmerz, taumelte auf die Beine und stürmte zu Mosks Seite."
  },
  AvgDialog_128700_Content_1 = {
    Text = "Gluck... Gluck..."
  },
  AvgDialog_128700_Content_10 = {
    Text = "Du bist ein anderthalb Jahre alter Seeotter, der draußen mit deinem Lieblingsgroßen nach Futter sucht."
  },
  AvgDialog_128700_Content_100 = {
    Text = "Speichel fließt unkontrolliert heraus, und unter dem Reiz des gekochten Essens springt ihr und Mosk fast gleichzeitig darauf und beißt beide in den gebratenen Fisch."
  },
  AvgDialog_128700_Content_101 = {Text = "Lecker—!"},
  AvgDialog_128700_Content_102 = {
    Text = "Hey, ah ... Nautila, die Hand?"
  },
  AvgDialog_128700_Content_103 = {
    Text = "Es ist nur eine Verrenkung; ich habe es bereits selbst wieder eingerenkt. Für einen Abenteurer ist das kein großes Ding. Danke für die Medizin!"
  },
  AvgDialog_128700_Content_104 = {
    Text = "<Small:(Obwohl es bitter und stark im Nachgeschmack ist, ist seine Wirkung tatsächlich sehr gut.)>"
  },
  AvgDialog_128700_Content_105 = {
    Text = "Yay! Glücklich, umarmen..."
  },
  AvgDialog_128700_Content_106 = {
    Text = "Hehe, Mosk, pass auf."
  },
  AvgDialog_128700_Content_107 = {
    Text = "Eh? Eh! Mach dir keine Sorgen, Mosk, beim nächsten Mal werde ich laut schreien, dass es weh tut, um dich daran zu erinnern."
  },
  AvgDialog_128700_Content_108 = {Text = "Quiek!"},
  AvgDialog_128700_Content_11 = {
    Text = "(Was haben wir hier? Seetang, Seegras, kleine Steine...)"
  },
  AvgDialog_128700_Content_12 = {
    Text = "(Und Stein, Steins Tante, Steins Großvater...?)"
  },
  AvgDialog_128700_Content_13 = {
    Text = "(STEIN! Sag deiner Familie, sie sollen hier nicht mehr herumschwimmen!!)"
  },
  AvgDialog_128700_Content_14 = {
    Text = "<Shake:ROAARRR—>"
  },
  AvgDialog_128700_Content_15 = {Text = "(Nein...)"},
  AvgDialog_128700_Content_16 = {
    Text = "Das Meer wirbelt zu einem gewaltigen Strudel auf. Eine vertraute Gestalt stürmt auf dich zu und schleppt etwas Großes auf ihrem Rücken!"
  },
  AvgDialog_128700_Content_17 = {
    Text = "Kohleball! Fleisch! Mosk, gefunden!"
  },
  AvgDialog_128700_Content_18 = {
    Text = "Glücklich! Nach Hause gehen! Zusammen!"
  },
  AvgDialog_128700_Content_19 = {
    Text = "Bevor du protestieren kannst, packt das Mädchen dich ebenfalls auf ihren Rücken und schießt wie ein Fisch zur Oberfläche."
  },
  AvgDialog_128700_Content_2 = {
    Text = "<Shake:Gluckern... Grummeln...>"
  },
  AvgDialog_128700_Content_20 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_128700_Content_21 = {
    Text = "Krach——! Blitze zucken, Donner grollt, und die aufgequollenen Regenwolken brechen endlich auf und ergießen ihr Wasser ins Meer."
  },
  AvgDialog_128700_Content_22 = {
    Text = "Du und Mosk zieht euch in die sichere Kabine zurück und starrt euch gegenseitig an."
  },
  AvgDialog_128700_Content_23 = {
    Text = "Ah? Ah, ah! (Ist das Fleisch? Großer Kerl, es sieht genau wie du aus!)"
  },
  AvgDialog_128700_Content_24 = {
    Text = "Genau wie ich?"
  },
  AvgDialog_128700_Content_25 = {
    Text = "Mosk neigte den Kopf, was ihren charakteristischen Ausdruck der Verwirrung offenbarte, und sah dann ernsthaft auf das “Fleisch“, das sie auf den Boden gelegt hatte."
  },
  AvgDialog_128700_Content_26 = {Text = "Pff—Ugh."},
  AvgDialog_128700_Content_27 = {
    Text = "Was ist gerade passiert? Mein Kopf fühlt sich an, als wäre er die ganze Zeit im Wasser. Wo bin ich? Bin ich tot?"
  },
  AvgDialog_128700_Content_28 = {
    Text = "Der Fremde hustete ein paar Mal und spuckte einen Mundvoll Meerwasser aus."
  },
  AvgDialog_128700_Content_29 = {
    Text = "Freund? Freund!! Genau wie Mosk!"
  },
  AvgDialog_128700_Content_3 = {
    Text = "<Shake:Glug glug glug—>"
  },
  AvgDialog_128700_Content_30 = {Text = "Eh... Hä?"},
  AvgDialog_128700_Content_31 = {
    Text = "<LightGray:Ist sie von einem nahegelegenen indigenen Stamm? Seltsam... Und wo genau ist das hier?>"
  },
  AvgDialog_128700_Content_32 = {
    Text = "Du bemerkst, dass sie zwar vorsichtig ist, aber nicht feindselig. Leise rückst du näher heran, um diesen Neuankömmling besser in Augenschein zu nehmen."
  },
  AvgDialog_128700_Content_33 = {
    Text = "Das sollte eine Schiffskabine sein. Abgenutzt, aber größtenteils strukturell intakt..."
  },
  AvgDialog_128700_Content_34 = {
    Text = "Moment—sind das Nieten der Northdrey Corporation?! Wasserstandsmesser, Ringschieberventile—"
  },
  AvgDialog_128700_Content_35 = {
    Text = "Mal sehen, in dem Fall..."
  },
  AvgDialog_128700_Content_36 = {
    Text = "Der Fremde durchstöbert aufgeregt die vollgestopfte Kabine. Währenddessen steht Mosk daneben und blinzelt mit fröhlicher Neugier."
  },
  AvgDialog_128700_Content_37 = {
    Text = "Glänzend, schön. Mosk, bringen. Freund, magst du?"
  },
  AvgDialog_128700_Content_38 = {
    Text = "Mosk, mit diesen Teilen kann ich dieses Schiff wieder zum Laufen bringen. Könntest du sie mir geben?"
  },
  AvgDialog_128700_Content_39 = {
    Text = "Wenn wir Aglo erreichen, verspreche ich dir, dass ich dir noch mehr, noch schönere glänzende Dinge mitbringe."
  },
  AvgDialog_128700_Content_4 = {
    Text = "Du liegst auf dem Rücken im warmen Meerwasser, streckst zufrieden deine kurzen kleinen Gliedmaßen aus und drehst einen perfekten Kreis."
  },
  AvgDialog_128700_Content_40 = {
    Text = "QUIEK—!! (Auf keinen Fall! Mein schöner kleiner Ball ist da noch drin!!)"
  },
  AvgDialog_128700_Content_41 = {
    Text = "Du schreist vor Wut und möchtest deinen kleinen Ball zurückholen, aber dein Blick wird sofort von Mosk angezogen."
  },
  AvgDialog_128700_Content_42 = {
    Text = "Pssst. Mosk, geben dir. Muscheln."
  },
  AvgDialog_128700_Content_43 = {
    Text = "Mosk schob dir heimlich zwei Muscheln zu, die du schon lange im Auge hattest, und schob diese Teile dann zu einem Fremden, um zu signalisieren, dass er sie ihr geben könnte."
  },
  AvgDialog_128700_Content_44 = {
    Text = "Freund, mag, Mosk gibt!"
  },
  AvgDialog_128700_Content_45 = {
    Text = "Du verstehst nicht, wie solche Dinge Fremde so aufregen können, während du glücklich deine kleine Nase in die beiden schönen Muscheln vergräbst, die Mosk zuvor nicht einmal bereit war, dich berühren zu lassen."
  },
  AvgDialog_128700_Content_46 = {
    Text = "Das ist großartig! Danke... mein Freund."
  },
  AvgDialog_128700_Content_47 = {
    Text = "Gewärmt von Mosks offener, aufrichtiger Freundlichkeit, entspannt sich die Fremde schließlich ein wenig und lächelt euch beide an."
  },
  AvgDialog_128700_Content_48 = {
    Text = "Übrigens, mein Name ist Nautila."
  },
  AvgDialog_128700_Content_49 = {
    Text = "Juhuu!! Nautila, Mosk, Freunde, glücklich!"
  },
  AvgDialog_128700_Content_5 = {
    Text = "(Warte, kurze Gliedmaßen?)"
  },
  AvgDialog_128700_Content_50 = {
    Text = "Mosk jubelt und breitet ihre Arme weit aus, bereit, ihrer brandneuen Freundin eine riesige Umarmung zu geben."
  },
  AvgDialog_128700_Content_51 = {
    Text = "Ah! (Mist ... der Große ...)"
  },
  AvgDialog_128700_Content_52 = {
    Text = "Freund, umarmen!"
  },
  AvgDialog_128700_Content_53 = {
    Text = "Warte, Mosk... Ugh! Es tut weh!"
  },
  AvgDialog_128700_Content_54 = {
    Text = "Die Wirbel in der Luft konvergierten plötzlich, und inmitten des abrupt verstärkten Winddrucks ertönte ein knackendes Geräusch."
  },
  AvgDialog_128700_Content_55 = {Text = "Autsch!!"},
  AvgDialog_128700_Content_56 = {
    Text = "Mosk wurde plötzlich wieder bewusst und ließ Nautila hastig los, aber Nautilas Gesicht war bereits vor Schmerz verzerrt, und ihr Arm war offensichtlich in einem unnatürlichen Winkel verdreht."
  },
  AvgDialog_128700_Content_57 = {
    Text = "Entschuldigung, entschuldigung... Ich..."
  },
  AvgDialog_128700_Content_58 = {
    Text = "Als du Mosk in Panik erstarrt siehst, beißt du in ihr Hosenbein und ziehst sie zu etwas hin."
  },
  AvgDialog_128700_Content_59 = {
    Text = "Ah, ah! (Großer Kerl, hierher!)"
  },
  AvgDialog_128700_Content_6 = {
    Text = "<Shake:Klick, klack.>"
  },
  AvgDialog_128700_Content_60 = {
    Text = "Oh richtig, das hier! Nautila—trink!"
  },
  AvgDialog_128700_Content_61 = {
    Text = "Berühre mich nicht!"
  },
  AvgDialog_128700_Content_62 = {
    Text = "Nautila wischte instinktiv Mosks Hand weg und lehnte sich zurück."
  },
  AvgDialog_128700_Content_63 = {
    Text = "[@Kombiniertes Tonikum]"
  },
  AvgDialog_128700_Content_64 = {
    Text = "Gluck, gluck—Die Medizinflasche fällt zu Boden und rollt zu Mosks Füßen."
  },
  AvgDialog_128700_Content_65 = {
    Text = "Das gerade noch selbstbewusste Mädchen spürte scharf die Angst des anderen und senkte langsam ihre Hand."
  },
  AvgDialog_128700_Content_66 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_128700_Content_67 = {
    Text = "Entschuldigung, aber ... gibt es noch andere Orte auf dem Schiff? Ich muss mich vielleicht kurz alleine ausruhen."
  },
  AvgDialog_128700_Content_68 = {
    Text = "Mosk schwieg einen Moment, zog die größte und weichste Decke auf dem Schiff herüber und breitete sie aus der Ferne auf dem Boden aus."
  },
  AvgDialog_128700_Content_69 = {
    Text = "Mosk, rücksichtslos, Großkraft, Schaden."
  },
  AvgDialog_128700_Content_7 = {
    Text = "Platsch platsch～"
  },
  AvgDialog_128700_Content_70 = {
    Text = "Mosk, schlecht, Entschuldigung. Zuhause, warm, Nautila."
  },
  AvgDialog_128700_Content_71 = {
    Text = "Dein Körper fühlte sich plötzlich schwerelos an, während Mosk dich vorsichtig und ein wenig schüchtern wie einen Schatz zu Nautila reichte."
  },
  AvgDialog_128700_Content_72 = {
    Text = "Draußen, Mosk. Kohleball, warm, Nautila, hier."
  },
  AvgDialog_128700_Content_73 = {
    Text = "Sie hob ihr Kinn, zeigte nach draußen und dann auf die Decke, stand hartnäckig zwischen Nautila und der Tür."
  },
  AvgDialog_128700_Content_74 = {
    Text = "... Na gut, danke."
  },
  AvgDialog_128700_Content_75 = {
    Text = "Ah, ah? (Hey, hey, großer Kerl?)"
  },
  AvgDialog_128700_Content_76 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_128700_Content_77 = {
    Text = "Der Regen lässt die ganze Nacht nicht nach. Um Mitternacht geht Nautila zur Kabinentür und blickt auf das Mädchen, das auf dem Deck schläft."
  },
  AvgDialog_128700_Content_78 = {
    Text = "Eng zusammengerollt in der Ecke des Schiffes schützt sie sich vor Wind und Regen."
  },
  AvgDialog_128700_Content_79 = {
    Text = "...So tief schlafen an einem Ort wie diesem. Du bist wirklich wie ein kleines Tier..."
  },
  AvgDialog_128700_Content_8 = {
    Text = "(Oh, richtig! Ich bin ein Seeotter!)"
  },
  AvgDialog_128700_Content_80 = {
    Text = "Entschuldigung, ich hätte nicht so hart zu dir sein sollen, Mosk."
  },
  AvgDialog_128700_Content_81 = {
    Text = "Mosk wird mit einer zusätzlichen Decke zugedeckt. Sie schmatzt im Schlaf und sinkt in einen noch tieferen, süßeren Traum."
  },
  AvgDialog_128700_Content_82 = {Text = "Quiek!"},
  AvgDialog_128700_Content_83 = {
    Text = "Am nächsten Morgen, nach dem Regen, ist die perfekte Zeit zum Angeln. \n Du beißt stolz auf den größten Fisch des Tages und wirfst ihn in Richtung Mosk, aber..."
  },
  AvgDialog_128700_Content_84 = {Text = "Klatsch!"},
  AvgDialog_128700_Content_85 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_128700_Content_86 = {
    Text = "Mosk fing den Fisch direkt mit ihrem Gesicht, ein Riss erschien in der Betäubung, die seit dem Morgen begonnen hatte. Sie sah dich an, die Mundwinkel nach unten gezogen, und dann begannen große Tränen zu fallen."
  },
  AvgDialog_128700_Content_87 = {
    Text = "Ugh... Aaaaaaah!"
  },
  AvgDialog_128700_Content_88 = {
    Text = "Sofort vergrub sie rücksichtslos ihr Gesicht vollständig in deinen Bauch und begann laut zu weinen."
  },
  AvgDialog_128700_Content_89 = {
    Text = "Mosk, schlecht!"
  },
  AvgDialog_128700_Content_9 = {
    Text = "Dein kleines Köpfchen erinnert sich fröhlich an die aktuelle Situation."
  },
  AvgDialog_128700_Content_90 = {
    Text = "Iiiik!! Quiek! QUIEK!! (Großer Kerl!! DEIN ROTZ!! Pass auf deinen Rotz auf!!)"
  },
  AvgDialog_128700_Content_91 = {
    Text = "<Italic:Schnief>— reden können, gleich, Freund, nie...wääh wääh..."
  },
  AvgDialog_128700_Content_92 = {
    Text = "Mosk weinte atemlos, und du versuchtest verzweifelt, deinen Bauch von ihrem Gesicht zu befreien, letztendlich konntest du nur ein Seufzen ausstoßen, während sie ihren Schnodder gleichmäßig verteilte."
  },
  AvgDialog_128700_Content_93 = {
    Text = "(Vielleicht wolltest du sagen, dass du endlich einen Freund gefunden hast, der so reden kann wie du, aber es scheint, dass du es vermasselt hast. Aber kann ein großer Typ wirklich als jemand gelten, der redet?)"
  },
  AvgDialog_128700_Content_94 = {
    Text = "(Hey, warte mal, was für ein duftender Geruch!)"
  },
  AvgDialog_128700_Content_95 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_128700_Content_96 = {
    Text = "In der Kabine fädelt Nautila mehrere Meeresfische mit dünnem Eisendraht auf. Die Flammen haben die Oberfläche der Fische verbrannt, und das Fett tropft auf den Boden und verströmt ein Aroma, das stark genug ist, um urtümliche Instinkte bei Tieren zu wecken."
  },
  AvgDialog_128700_Content_97 = {
    Text = "Äh, Entschuldigung, ich habe gesehen, dass ihr alle rohen Fisch esst, also habe ich ihn etwas verarbeitet ... Auch wenn es keine Gewürze gibt, möchtet ihr kosten?"
  },
  AvgDialog_128700_Content_98 = {Text = "Auu!"},
  AvgDialog_128700_Content_99 = {Text = "Auu!"},
  AvgDialog_130451_Content_1 = {
    Text = "Die Nacht ist dunkel. Du hast gerade einen Feldeinsatz abgeschlossen, und der Erwecker, der dich begleitet hat — der kleine Ritter aus einer anderen Welt, Eidbrecher·Ogier — folgt dir still im Hintergrund."
  },
  AvgDialog_130451_Content_10 = {
    Text = "Warte — bitte komm nicht näher!"
  },
  AvgDialog_130451_Content_11 = {
    Text = "Noch bevor seine Worte verklungen sind, wird dein Blickfeld plötzlich pechschwarz."
  },
  AvgDialog_130451_Content_12 = {
    Text = "Die unsichtbaren Präsenzen, die seit Langem mit Eidbrecher·Ogier koexistieren, stürzen sich plötzlich auf dich, drücken sich gegen deine Gliedmaßen, bedecken deine Augen, winden sich fest um dich — und hinterlassen ein leises Kältegefühl."
  },
  AvgDialog_130451_Content_13 = {Text = "Ogier!"},
  AvgDialog_130451_Content_14 = {
    Text = "Du rufst um Hilfe, doch der dunkle Schlamm ringelt sich nur noch enger zusammen, als wäre er verzweifelt darauf bedacht, dich vollständig in sich einzuschließen. Du streckst die Hand aus und reißt daran, doch er wickelt sich hartnäckig wie Rankentriebe wieder um dich."
  },
  AvgDialog_130451_Content_15 = {Text = "Ugh..."},
  AvgDialog_130451_Content_16 = {
    Text = "Die schwache, verschwommene Stimme des Jungen dringt in bruchstückhaften Fetzen zu dir — er kämpft offensichtlich darum, etwas zurückzuhalten."
  },
  AvgDialog_130451_Content_17 = {
    Text = "Ogier? Kannst du mich hören?"
  },
  AvgDialog_130451_Content_18 = {
    Text = "Der Griff, der dich fesselt, zittert leicht, zieht sich dann wieder zusammen — als würde er zwischen zwei entgegengesetzten Willen hin- und hergezogen."
  },
  AvgDialog_130451_Content_19 = {
    Text = "Wegen meiner Unfähigkeit wurdest du dennoch verletzt. Wenn ich nur einen besseren Weg finden könnte, dich zu schützen…"
  },
  AvgDialog_130451_Content_2 = {
    Text = "Dieser Einsatz war nicht besonders schwierig. Als erfahrener Schutzherr hast du gemeinsam mit Eidbrecher·Ogier jeden Feind mühelos ausgeschaltet. Doch aufgrund eines kurzen Moments der Unaufmerksamkeit hast du dir dennoch einen kleinen Schnitt am Handgelenk zugezogen."
  },
  AvgDialog_130451_Content_20 = {
    Text = "Du kannst nur ein paar verworrene Worte verstehen, wie jemand, der mit sich selbst spricht."
  },
  AvgDialog_130451_Content_21 = {
    Text = "Obwohl der Schlamm dich fest umschlingt, bereitet er dir nicht den geringsten Schmerz oder Erstickungsgefühl. Dir wird plötzlich klar, dass dies wohl nicht dazu gedacht ist, dir zu schaden — es fühlt sich eher wie ein Versuch an, dich irgendwo absolut sicher zu verbergen, an einem Ort, dem nichts nahekommen kann."
  },
  AvgDialog_130451_Content_22 = {
    Text = "Es ist in Ordnung. Mir geht es vollkommen gut — du musst keine Angst haben."
  },
  AvgDialog_130451_Content_23 = {
    Text = "Deine Worte scheinen gewirkt zu haben. Diesmal beginnt der Griff des Schlamms endlich nachzulassen. Du nutzt den Moment und reißt ihn von dir."
  },
  AvgDialog_130451_Content_24 = {
    Text = "Du siehst Eidbrecher·Ogier mit gesenktem Kopf und leicht gerunzelter Stirn dastehen, seine Augen noch immer von Verwirrung getrübt — wie eine reuige Statue, die das Gewicht einer ungeheuren Sünde trägt."
  },
  AvgDialog_130451_Content_25 = {
    Text = "Geht es dir gut?"
  },
  AvgDialog_130451_Content_26 = {
    Text = "Zu denken, dass ich eine solch unkontrollierbare Macht auf dich losgelassen habe…"
  },
  AvgDialog_130451_Content_27 = {
    Text = "Nein, ich muss mich… wieder besinnen."
  },
  AvgDialog_130451_Content_28 = {
    Text = "Er schließt die Augen und murmelt, während er die kleine Masse schwarzen Schlamms, die um seine Hand wirbelt, in die Form eines Dolches formt. Mondlicht fällt auf die kalt schimmernde Klinge — und sie ist auf seinen eigenen anderen Arm gerichtet."
  },
  AvgDialog_130451_Content_29 = {
    Text = "Doch der scharfe Gegenstand fällt nie. Du eilst rechtzeitig vor, um seine Bewegung aufzuhalten. Erst dann erkennst du, mit einiger Verzögerung, dass die unsichtbaren Dinge, die sich eben noch so fest an dich geklammert hatten, vollständig zurückgewichen sind."
  },
  AvgDialog_130451_Content_3 = {
    Text = "Die Umgebung ist vollkommen still. Die Erschöpfung lässt deinen Geist ein wenig benebelt wirken, und du wirst von einem plötzlichen Geräusch hinter dir aufgeschreckt."
  },
  AvgDialog_130451_Content_30 = {
    Text = "Mein Herr...?"
  },
  AvgDialog_130451_Content_31 = {
    Text = "Du hockst dich halb hin und legst sanft die Arme um ihn, klopfst ihm tröstend auf den Rücken."
  },
  AvgDialog_130451_Content_32 = {
    Text = "Er zieht sich nicht wie sonst zurück, sondern steht reglos da und verharrt in der Haltung, von dir gehalten zu werden."
  },
  AvgDialog_130451_Content_33 = {
    Text = "Nur keine Eile — entspann dich. Siehst du, Es wurde von dir erfolgreich unterdrückt. Aber was genau ist passiert?"
  },
  AvgDialog_130451_Content_34 = {
    Text = "Ich entschuldige mich, mein Herr. Aus irgendeinem Grund war die Präsenz, die mir heute anhaftet, ungewöhnlich unruhig, und meine Gedanken wurden sehr zerstreut."
  },
  AvgDialog_130451_Content_35 = {
    Text = "Selbst mit dir direkt an meiner Seite zog Es sich nicht nur nicht zurück wie sonst — Es wurde sogar noch aktiver… Deshalb wollte ich Schmerz nutzen, um mich zu beruhigen."
  },
  AvgDialog_130451_Content_36 = {
    Text = "Während du Ogier hältst, kannst du die abnorme Hitze spüren, die von seinem Körper ausstrahlt, und du hast in deinem Kopf mehr oder weniger eine Schlussfolgerung gezogen. Du hättest nicht erwartet, dass der Einfluss des Heiligen Flusses direkt in die andere Macht eingreifen würde, die in Ogier wohnt."
  },
  AvgDialog_130451_Content_37 = {
    Text = "Das ist nicht deine Schuld — es ist der Einfluss von gewissen… anderen Dingen."
  },
  AvgDialog_130451_Content_38 = {
    Text = "Außerdem hat mich dieser schwarze Schlamm zwar für einen Moment gefangen gehalten, aber er hat mir überhaupt nicht geschadet… Das muss daran liegen, dass du Es unter Kontrolle gehalten hast, nicht wahr? Wirklich bemerkenswert."
  },
  AvgDialog_130451_Content_39 = {
    Text = "Nach einer kurzen Stille hörst du schließlich die gedämpfte Stimme des jungen Mannes."
  },
  AvgDialog_130451_Content_4 = {
    Text = "……Genug! Wie könnte ich nur — gegenüber meinem Lehnsherrn—"
  },
  AvgDialog_130451_Content_40 = {
    Text = "…Danke. Ich habe dich wieder dazu gebracht, mich zu trösten."
  },
  AvgDialog_130451_Content_41 = {
    Text = "Es wird spät. Bitte erlaubt mir, zuerst eure Wunden zu versorgen und euch dann auf euer Zimmer zu begleiten."
  },
  AvgDialog_130451_Content_5 = {
    Text = "Du weißt schon lange, dass Eidbrecher·Ogier gegen die unsichtbare Präsenz ankämpft, die an ihm haftet, doch seine Reaktion heute wirkt ungewöhnlich übertrieben."
  },
  AvgDialog_130451_Content_6 = {
    Text = "Also drehst du dich um und gehst auf ihn zu."
  },
  AvgDialog_130451_Content_7 = {
    Text = "Ogier? Geht es dir gut? Versucht Es wieder, dich zu kontrollieren?"
  },
  AvgDialog_130451_Content_8 = {Text = "!"},
  AvgDialog_130451_Content_9 = {
    Text = "Eidbrecher·Ogier reißt plötzlich den Kopf hoch — er hatte starr auf seine Schuhspitzen gestarrt — und taumelt zitternd einen Schritt zurück."
  },
  AvgDialog_130453_Content_1 = {
    Text = "Angesichts Shayes besonderer Fähigkeiten waren alle angespannt, wie sie auf den Einfluss des Heiligen Flusses reagieren könnte."
  },
  AvgDialog_130453_Content_10 = {
    Text = "Alles, was ich durchgemacht habe, macht mich zu der, die ich bin, aber es gibt noch so vieles, das ich erst lernen muss."
  },
  AvgDialog_130453_Content_11 = {
    Text = "„Der Instinkt ist Fortpflanzung\", also. Ach... ich verstehe..."
  },
  AvgDialog_130453_Content_12 = {
    Text = "Während sie spricht, reicht sie dir ein Kissen."
  },
  AvgDialog_130453_Content_13 = {
    Text = "Du atmest lang und erleichtert aus und lehnst dich zurück, genau wie sie."
  },
  AvgDialog_130453_Content_14 = {
    Text = "Ich verstehe... nach allem, was du durchgemacht hast, siegt die Vernunft über den Instinkt..."
  },
  AvgDialog_130453_Content_15 = {
    Text = "<Small: Selbst nachdem sie ein Erweckter Körper geworden ist, bleibt Shaye wirklich einzigartig...>"
  },
  AvgDialog_130453_Content_16 = {
    Text = "Shaye—wenn es nicht zu viel verlangt ist, kann ich deinen Ort als sicheres Versteck nutzen?!"
  },
  AvgDialog_130453_Content_17 = {
    Text = "Deine Augen füllen sich mit Tränen purer Erleichterung, während du deine verzweifelte Bitte aussprichst."
  },
  AvgDialog_130453_Content_18 = {
    Text = "In diesem Moment zählt vor allem, dass der arme Schutzherr der Misaq endlich ein verlässliches sicheres Versteck hat."
  },
  AvgDialog_130453_Content_19 = {
    Text = "Hm? Obwohl ich es nicht ganz verstehe..."
  },
  AvgDialog_130453_Content_2 = {
    Text = "Doch zur Überraschung aller steht sie einfach schweigend am Fenster. Ihre blasse Haut ist beinahe durchscheinend, als wäre sie in einer anderen Welt versiegelt."
  },
  AvgDialog_130453_Content_20 = {
    Text = "Shaye runzelte gespielt besorgt die Stirn und lachte erst wieder, nachdem sie Deine enttäuschte Miene gesehen hatte."
  },
  AvgDialog_130453_Content_21 = {
    Text = "Shaye runzelt spielerisch zögernd die Stirn und lächelt erst, nachdem sie die Enttäuschung in deinem Gesicht gesehen hat."
  },
  AvgDialog_130453_Content_22 = {
    Text = "Natürlich kannst du das. Aber... %player%, im Gegenzug, könntest du mir verraten:"
  },
  AvgDialog_130453_Content_23 = {
    Text = "Wer ist die Person, die dir am meisten am Herzen liegt?"
  },
  AvgDialog_130453_Content_24 = {
    Text = "Wie zwei enge Freunde, die alles miteinander teilen, verfallt ihr in ein behagliches, unbeschwertes Gespräch."
  },
  AvgDialog_130453_Content_25 = {
    Text = "Eine Gestalt erscheint in deinem Bewusstsein, du schließt entspannt die Augen und spendest auch Shayes Zukunft deinen Segen — möge dieses Dasein die weite Spanne der Zeit überdauern."
  },
  AvgDialog_130453_Content_26 = {
    Text = "Eine bestimmte Gestalt taucht in deinen Gedanken auf. Du schließt die Augen, entspannt, und sprichst einen stillen Segen für Shayes Zukunft aus—solange diese Gefühle nicht tatsächlich die Welt beenden. Aber wer weiß?"
  },
  AvgDialog_130453_Content_27 = {
    Text = "Die Kraft des Heiligen Flusses fließt zwischen euch wie eine sanfte Gezeit, still und ohne Eile."
  },
  AvgDialog_130453_Content_3 = {
    Text = "Hallo, Schutzherr."
  },
  AvgDialog_130453_Content_4 = {
    Text = "Shaye... geht es dir gut? Ist irgendetwas... nicht in Ordnung?"
  },
  AvgDialog_130453_Content_5 = {
    Text = "Als würde sie deine Sorge spüren, dreht sich das Mädchen leichtfüßig auf den Fersen—"
  },
  AvgDialog_130453_Content_6 = {
    Text = "kein Fieber, kein rasender Herzschlag, keine seltsame Euphorie. Nichts Ungewöhnliches."
  },
  AvgDialog_130453_Content_7 = {
    Text = "Mach dir keine Sorgen um mich. Es scheint, als wäre mir nichts Besonderes widerfahren."
  },
  AvgDialog_130453_Content_8 = {
    Text = "Der Instinkt von Lady Thais' Art ist also die Fortpflanzung... aber könnte das auch mich betreffen?"
  },
  AvgDialog_130453_Content_9 = {
    Text = "Sie setzt sich näher zu dir, kuschelt sich in ein weiches Kissen und lächelt wie ein harmloses, kleines Tier."
  },
  AvgDialog_130454_Content_1 = {
    Text = "Im leeren Saal hallen nur deine und Murphys Schritte wider."
  },
  AvgDialog_13049_Content_1 = {
    Text = "Ogier hielt seine Waffe fest umklammert und war bei jedem Geräusch um ihn herum auf der Hut. In seinen Augen könnte jede Bewegung ein Hinterhalt feindlicher Truppen sein."
  },
  AvgDialog_13049_Content_10 = {
    Text = "Der Klang von Wasser? Es kommt wahrscheinlich von der Wasseruhr dort drüben."
  },
  AvgDialog_13049_Content_11 = {
    Text = "Klingt, als käme es von draußen. Ich gehe mal nachsehen!"
  },
  AvgDialog_13049_Content_12 = {
    Text = "Eile nicht! Lass uns zusammen gehen!"
  },
  AvgDialog_13049_Content_13 = {
    Text = "Bevor jemand ihn stoppen konnte, hob Ogier seine Waffe und stürmte zum Tor des Palastes."
  },
  AvgDialog_13049_Content_14 = {
    Text = "Das ist—?!"
  },
  AvgDialog_13049_Content_15 = {
    Text = "Feind Angriff!"
  },
  AvgDialog_13049_Content_2 = {
    Text = "Du kannst keine Worte finden, um ihn zu trösten. Die Worte aus dem Dossier des Erweckers blitzen vor dir auf—"
  },
  AvgDialog_13049_Content_3 = {
    Text = "Erklärung des Erwachenden: Ogier Danske, @2 Ritter des Herzogtums\nFiel in der Nacht der Heimatverteidigung..."
  },
  AvgDialog_13049_Content_4 = {
    Text = "Lord Chamberlain, bitte evakuieren Sie sich in die Randgebiete zur Sicherheit. Wir können die Dinge hier regeln..."
  },
  AvgDialog_13049_Content_5 = {
    Text = "Ihr beiden Ritter könnt nicht einmal Eisenhut von Orchideen unterscheiden. Was, wenn ihr versehentlich Gift der Prinzessin gebt?"
  },
  AvgDialog_13049_Content_6 = {
    Text = "Eine klare Ablehnung erleichterte die Spannung. Ogier errötete, der Wachritter unterdrückte ein Lachen, und sogar ein gedämpftes Kichern kam von hinter der Tür."
  },
  AvgDialog_13049_Content_7 = {
    Text = "Du kannst nicht gehen—eingeklemmt im ogier-zentrierten Rätsel, hastig zu gehen kann unbekannte Konsequenzen nach sich ziehen."
  },
  AvgDialog_13049_Content_8 = {
    Text = "Tick-tack—"
  },
  AvgDialog_13049_Content_9 = {
    Text = "Hast du irgendwelche Geräusche gehört?"
  },
  AvgDialog_13050_Content_1 = {
    Text = "Schließlich endete der Kampf. Du und Ogier blieben am Fuße der Treppe, um die Palastraum zu reinigen, während die Wachen bereits vor dem Zimmer der Prinzessin zurückgekehrt waren."
  },
  AvgDialog_13050_Content_10 = {
    Text = "Raschelnde..."
  },
  AvgDialog_13050_Content_11 = {
    Text = "Doch... kann die Plage sich in Monster verwandeln, die normale Menschen nicht sehen können?"
  },
  AvgDialog_13050_Content_12 = {
    Text = "Dies ist wirklich absurd. Selbst wenn die Hofpoeten darüber singen würden, würden es nur wenige glauben."
  },
  AvgDialog_13050_Content_13 = {
    Text = "Zunächst dachten mein Vater und ich, es sei ein Fluch der Zauberer des Nachbarlandes, aber... bald berichteten auch sie von der wütenden Plage."
  },
  AvgDialog_13050_Content_14 = {
    Text = "Selbst ich... *hust, hust*..."
  },
  AvgDialog_13050_Content_15 = {
    Text = "Während des Sprechens hallte ein herzzerreißender Husten von hinter der Tür wider."
  },
  AvgDialog_13050_Content_16 = {
    Text = "Prinzessin, bitte unterlasse es vorerst zu sprechen. Kehre zuerst ins Bett zurück."
  },
  AvgDialog_13050_Content_17 = {
    Text = "Raschelnde..."
  },
  AvgDialog_13050_Content_18 = {
    Text = "Helfer! Helfer, komm zurück und hilf! Die Prinzessin—"
  },
  AvgDialog_13050_Content_19 = {Text = "Ugh!"},
  AvgDialog_13050_Content_2 = {
    Text = "Es ist das erste Mal, dass wir gegen unsichtbare Feinde kämpfen. Wenn das alles vorbei ist, wie wäre es, wenn wir einen Barden finden, der unsere Geschichte aufschreibt und in ein Lied verwandelt?"
  },
  AvgDialog_13050_Content_20 = {
    Text = "Das knirschende Geräusch zerbrechender Knochen hallte wider, als etwas gewaltsam das eng gewobene Muskelgewebe auseinander riss und leuchtend rotes Liquid spritzte."
  },
  AvgDialog_13050_Content_21 = {
    Text = "Wh...at...?"
  },
  AvgDialog_13050_Content_22 = {
    Text = "Sir Fernando!!!"
  },
  AvgDialog_13050_Content_23 = {
    Text = "Der Wächterritter hustete, Blut und Stücke von Fleisch spritzten aus seiner Kehle. Seine Augen weiteten sich ungläubig, erfüllt von Verwirrung und Angst."
  },
  AvgDialog_13050_Content_3 = {
    Text = "Ich habe bereits den Namen entschieden: \"Dansks Auge, Fernandos Schwert\"!"
  },
  AvgDialog_13050_Content_4 = {
    Text = "Ogier, der beim Namen gerufen wurde, sah zu dem Wachenritter auf. Seine Hände waren mit viel D-Schleim bedeckt. Er zögerte, unsicher, wie er sie reinigen sollte, und fühlte sich äußerst beschämt."
  },
  AvgDialog_13050_Content_5 = {
    Text = "Wirst du meinen Namen auch ins Lied schreiben? Was hat Ogier getan, um das zu verdienen"
  },
  AvgDialog_13050_Content_6 = {
    Text = "Hehe... Kann der Kammerdiener und ich uns nicht wenigstens unsere Namen darauf setzen?"
  },
  AvgDialog_13050_Content_7 = {
    Text = "Natürlich! Absolut! Dein Name wird in der ersten Linie dieses Liedes stehen!"
  },
  AvgDialog_13050_Content_8 = {
    Text = "Raschelnde..."
  },
  AvgDialog_13050_Content_9 = {
    Text = "@1 Prinzessinnen-Suite... Was denkst du? Habe ich ein Talent für Poesie?"
  },
  AvgDialog_13051_Content_1 = {
    Text = "Was ist... was passiert hier?"
  },
  AvgDialog_13051_Content_10 = {
    Text = "Sir Fernando... Ich erinnere mich, dass er das einzige Kind in seiner Familie war."
  },
  AvgDialog_13051_Content_11 = {
    Text = "Wenn ich nur wachsamer gewesen wäre..."
  },
  AvgDialog_13051_Content_12 = {
    Text = "Gib dir selbst keine Schuld für seinen Tod. Diese @1 Monster sind schwer fassbar. Wir haben unser Bestes gegeben."
  },
  AvgDialog_13051_Content_13 = {
    Text = "Ogier schüttelte den Kopf; dein blasser Trost konnte ihn offensichtlich nicht trösten.\nGerade dann ertönte ein leises Klopfen von hinten."
  },
  AvgDialog_13051_Content_14 = {
    Text = "Kämmerer, nimm Ogier mit dir."
  },
  AvgDialog_13051_Content_15 = {Text = "Warum!"},
  AvgDialog_13051_Content_16 = {
    Text = "Du... brauchst mich nicht mehr? Ich weiß, ich habe Lord Fernando nicht gerettet, aber..."
  },
  AvgDialog_13051_Content_17 = {
    Text = "Die Plage bringt Krankheit, Krieg und Schmerz... Hier zu bleiben macht dich nur zu ihrer nächsten Mahlzeit."
  },
  AvgDialog_13051_Content_18 = {
    Text = "Ihre Stimme zitterte, dennoch sprach sie in einem verspielten Ton. Angesichts der drohenden Gefahr des Todes zeigte sie keine Spur von Angst."
  },
  AvgDialog_13051_Content_19 = {
    Text = "Ich nehme an... Lord Fernando würde nicht so bald mit dir wiedervereint sein wollen, oder?"
  },
  AvgDialog_13051_Content_2 = {
    Text = "Ein leises Geräusch von Schritten kam aus dem Inneren, gefolgt vom Rutschen des Türverschlusses—"
  },
  AvgDialog_13051_Content_20 = {
    Text = "Aber... das... ist meine Verantwortung..."
  },
  AvgDialog_13051_Content_21 = {
    Text = "Jetzt... es bin nur ich... Ich werde den Willen von Lord Fernando fortführen... Ich werde erben..."
  },
  AvgDialog_13051_Content_22 = {
    Text = "Ein langes, resigniertes Seufzen kam von hinter der Tür. Nach einer Weile sprach die Prinzessin mit dir."
  },
  AvgDialog_13051_Content_23 = {
    Text = "Verwalter, verspreche mir... wenn meine Stimme völlig verschwunden ist, musst du Ogier wegbringen, auch wenn du ihn bewusstlos schlagen musst, okay?"
  },
  AvgDialog_13051_Content_24 = {
    Text = "...Wie du wünschst."
  },
  AvgDialog_13051_Content_25 = {
    Text = "Ogier hielt seine Waffe fest umklammert, seine Hände wurden weiß vor Anstrengung. Es fühlte sich an, als wäre der Speer in seinen Armen seine Familie, deren Schicksal ungewiss war, eine sterbende Prinzessin oder der für immer verstorbene Fernando."
  },
  AvgDialog_13051_Content_26 = {
    Text = "Er starrte fest auf das Tor des Palastes, seine Gedanken schwebten weit weg. Selbst der laute Knall, als das Tor getroffen wurde, konnte ihn nicht in die Realität zurückbringen."
  },
  AvgDialog_13051_Content_27 = {
    Text = "Ogier? Ogier?"
  },
  AvgDialog_13051_Content_28 = {
    Text = "Jemand kommt."
  },
  AvgDialog_13051_Content_29 = {
    Text = "Jemand... kommt? Sind die Ritter zurückgekehrt!?"
  },
  AvgDialog_13051_Content_3 = {
    Text = "Komm nicht raus!"
  },
  AvgDialog_13051_Content_30 = {
    Text = "Das Tor wurde aufgerissen, aber die im Wind flatternde Flagge hatte nicht die Farbe, die du erwartet hattest."
  },
  AvgDialog_13051_Content_4 = {
    Text = "Prinzessin... bitte komm nicht heraus..."
  },
  AvgDialog_13051_Content_5 = {
    Text = "Ogier mühte sich, den Körper von Ritter Fernando von der Tür zu schieben, zog dann den Vorhang herunter, um das Blut zu verdecken, das durch die Lücke sammelte."
  },
  AvgDialog_13051_Content_6 = {
    Text = "Die Stacheln des Mutanten durchbohrten die Brustpanzerung und das Fleisch und hinterließen die Brust in einer blutigen Sauerei, als wäre sie explodiert. Ritter Fernando war bereits in Qual gestorben."
  },
  AvgDialog_13051_Content_7 = {
    Text = "...In Ordnung."
  },
  AvgDialog_13051_Content_8 = {
    Text = "Bitte gib dein Bestes, um ihm eine ordentliche Beerdigung zu geben."
  },
  AvgDialog_13051_Content_9 = {
    Text = "Du und Ogier tauscht einen Blick aus, rollt leise den Körper des Ritters in einen Teppich und setzt euch vor die Schlafzimmertür auf den Boden. Schmerz und Angst liegen in der Luft."
  },
  AvgDialog_13052_Content_1 = {
    Text = "Was ist los? Wo sind die Feinde?"
  },
  AvgDialog_13052_Content_10 = {
    Text = "Euer Exzellenz, können Sie es auch sehen?"
  },
  AvgDialog_13052_Content_11 = {
    Text = "Du gibst ihm einen beruhigenden Blick und verhandelst weiter mit dem Ritter."
  },
  AvgDialog_13052_Content_12 = {
    Text = "Ogier war nie der Typ, der unvernünftig handelt, und das weißt du am besten aus deinem Training mit ihm, nicht wahr?"
  },
  AvgDialog_13052_Content_13 = {
    Text = "Selbst wenn du das sagst, habe ich wirklich nichts getan..."
  },
  AvgDialog_13052_Content_14 = {
    Text = "...Warte einen Moment, Lord Fernando."
  },
  AvgDialog_13052_Content_15 = {
    Text = "Ein Klopfen kam von der Richtung der Schlafzimmertür und zog alle mit einer schwachen weiblichen Stimme zurück."
  },
  AvgDialog_13052_Content_16 = {
    Text = "Sie hatten recht... Es war der unsichtbare Feind, der die Pest verbreitete."
  },
  AvgDialog_13052_Content_17 = {
    Text = "Seit die Prinzessin das gesagt hat..."
  },
  AvgDialog_13052_Content_18 = {
    Text = "Der Wächterritter biss die Zähne zusammen, hob seine Waffe und stellte sich an deine Seite."
  },
  AvgDialog_13052_Content_19 = {
    Text = "Sag mir die Position des Feindes und ich werde mein Bestes tun, um im Kampf zu helfen!"
  },
  AvgDialog_13052_Content_2 = {
    Text = "Der Wachsoldat eilte ebenfalls die Treppe hinunter zu dir, völlig ratlos."
  },
  AvgDialog_13052_Content_3 = {
    Text = "Jetzt ist nicht die Zeit zum Herumspielen. Bleib wachsam."
  },
  AvgDialog_13052_Content_4 = {
    Text = "Ich mache keine Scherze! Siehst du das nicht?!"
  },
  AvgDialog_13052_Content_5 = {
    Text = "Ogier verteidigt sich ängstlich, aber der Wachenritter bleibt skeptisch."
  },
  AvgDialog_13052_Content_6 = {
    Text = "Es ist nicht seine Schuld; schließlich waren die Feinde, die du und Ogier besiegt habt, vollständig Abweichungen, die aus der Auflösung hervorgegangen sind."
  },
  AvgDialog_13052_Content_7 = {
    Text = "Visuelle Beobachtungen des D-Phänomens sind extrem selten.\nOgier gehört zu den unglücklichen wenigen, die auch als glücklich gelten."
  },
  AvgDialog_13052_Content_8 = {
    Text = "Bitte vertraue uns."
  },
  AvgDialog_13052_Content_9 = {
    Text = "Bitte vertraue uns und glaube an die Integrität von Ogier."
  },
  AvgDialog_13053_Content_1 = {
    Text = "Der letzte Vorhang"
  },
  AvgDialog_13053_Content_10 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_13053_Content_11 = {
    Text = "Lass uns Ogier zusammen den Palast bewachen.\nEr ist schließlich ein rechtmäßiger und großherziger, vom Herzog ernannter Wächterritter, nicht wahr?"
  },
  AvgDialog_13053_Content_12 = {
    Text = "Der Wächterritter konnte keinen anderen Grund finden, um abzulehnen. Nach einem zustimmenden Nicken kehrten sie beide in den Palast zurück"
  },
  AvgDialog_13053_Content_13 = {
    Text = [[
Der Palast ist leer; sogar die laute Dienerin ist gegangen.
Abgesehen von euch dreien bleibt nur die Prinzessin.]]
  },
  AvgDialog_13053_Content_14 = {
    Text = "Du klopfst an die opulente Schlafzimmertür, das Geräusch hallt durch die stille Halle, unheimlich gedämpft."
  },
  AvgDialog_13053_Content_15 = {
    Text = "Prinzessin? Geht es dir gut?"
  },
  AvgDialog_13053_Content_16 = {
    Text = "Es gab keine Antwort von innen. Nachdem du einen Moment gewartet hattest, klopfst du erneut an die Tür."
  },
  AvgDialog_13053_Content_17 = {
    Text = "Prinzessin, der Wachenritter, Ogier, und ich sind alle hier."
  },
  AvgDialog_13053_Content_18 = {
    Text = "Durch die schwere Holztür drang das Geräusch von raschelndem Stoff, als sich jemand mühsam aus dem Bett aufrichten wollte."
  },
  AvgDialog_13053_Content_19 = {
    Text = "...Torheit."
  },
  AvgDialog_13053_Content_2 = {Text = "\"Traum\""},
  AvgDialog_13053_Content_20 = {
    Text = "Du... geh voraus und schließe dich den anderen an. Es gibt keinen Grund, bei einem Leichnam zu bleiben."
  },
  AvgDialog_13053_Content_21 = {
    Text = "Die Atmung des Mädchens ist schwach, ihre Stimme so sanft wie die eines Mücken. Es scheint, dass das bloße Antworten auf dich all ihre Kraft gekostet hat."
  },
  AvgDialog_13053_Content_22 = {
    Text = "Die Plage breitete sich chaotisch im Herzogtum aus und machte vor niemandem halt, nicht einmal vor dem Adel. Die Prinzessin fiel krank, bevor der Krieg begann, und bis heute hat sie nicht die Kraft, ihr Bett zu verlassen."
  },
  AvgDialog_13053_Content_23 = {
    Text = "Der königliche Arzt hat offen erklärt, dass die Prinzessin den Stress des Umzugs aus dem Palast nicht mehr ertragen kann. Selbst milde Stöße könnten ihr das Leben kosten."
  },
  AvgDialog_13053_Content_24 = {
    Text = "Prinzessin..."
  },
  AvgDialog_13053_Content_25 = {
    Text = "Egal was du sagst, ich werde nicht gehen. Bitte erlaube mir, dich zu bewachen...\nmeine Pflichten als Ritter zu erfüllen."
  },
  AvgDialog_13053_Content_26 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_13053_Content_27 = {
    Text = "...Komm mir nicht zu nah. Die Pest ist irreversibel, zumindest... lasst euch nicht anstecken."
  },
  AvgDialog_13053_Content_28 = {
    Text = [[
Wenn die Sanduhr abgelaufen ist, komm und sprich mit mir, okay?
Wenn ich nicht mehr reagiere... solltest du gehen.]]
  },
  AvgDialog_13053_Content_3 = {
    Text = "Verschwörungen rühren sich in der Dunkelheit und entzünden die Zündschnur, die von der Plage gelegt wurde. Der Krieg bricht über Nacht aus."
  },
  AvgDialog_13053_Content_4 = {
    Text = "Die unheilbare <Yellow:Pest> hat sich bereits im gesamten Herzogtum ausgebreitet, und die Stadtwachen, die von Krankheit geplagt sind, können dem Vorstoß der Eindringlinge nicht widerstehen."
  },
  AvgDialog_13053_Content_5 = {
    Text = "Selbst die königlichen Ritter haben auf Befehl des Großherzogs den Graben überschritten und sich der letzten Verteidigungslinie der Hauptstadt angeschlossen."
  },
  AvgDialog_13053_Content_6 = {
    Text = "Ogier, warum bist du noch hier?"
  },
  AvgDialog_13053_Content_7 = {
    Text = "Ich... Ich möchte mit dir auf die Eskorte-Mission gehen."
  },
  AvgDialog_13053_Content_8 = {
    Text = "Du bist zu jung; der Krieg... betrifft dich noch nicht. \nGeh zurück und finde einen sicheren Ort bei deiner Familie."
  },
  AvgDialog_13053_Content_9 = {
    Text = "Ogiers Zuhause, das Dansk Estate... Sollte sich außerhalb der Verteidigungslinie befinden, oder?"
  },
  AvgDialog_13054_Content_1 = {
    Text = "Traum oder Ideal"
  },
  AvgDialog_13054_Content_10 = {
    Text = "Bediensteter, könnten Sie bitte in meinem Auftrag gehen?"
  },
  AvgDialog_13054_Content_100 = {
    Text = "Die Dinge, über die wir gerade gesprochen haben... Du wirst der Prinzessin wirklich nichts erzählen, oder?"
  },
  AvgDialog_13054_Content_101 = {
    Text = "Was? Habe ich überhaupt keinen Kredit bei dir?"
  },
  AvgDialog_13054_Content_102 = {
    Text = "Wie könnte das sein! Ich würde niemals...!"
  },
  AvgDialog_13054_Content_103 = {
    Text = "Alright, ich werde das, was heute passiert ist, nutzen, um dich zu bedrohen."
  },
  AvgDialog_13054_Content_104 = {Text = "Bedrohung?"},
  AvgDialog_13054_Content_105 = {
    Text = "Du kniest vor Ogier nieder, blickst dem ängstlichen Welpen in die Augen und streckst deine Hand zu ihm aus."
  },
  AvgDialog_13054_Content_106 = {
    Text = "Heutige Gespräche werden für immer in unseren Herzen vergraben bleiben. Doch im Austausch für mein Bewahren dieses Geheimnisses, musst du mir eine Sache versprechen."
  },
  AvgDialog_13054_Content_107 = {
    Text = "In dieser Ära gibt es keinen Brauch des kleinen Fingerschwurs, aber Ogier hat trotzdem unschuldig deinen ausgestreckten kleinen Finger gefasst."
  },
  AvgDialog_13054_Content_108 = {
    Text = "Solange es in meinem Ermessen liegt..."
  },
  AvgDialog_13054_Content_109 = {
    Text = "Sehr gut, ich behalte mir das Recht vor, einen Wunsch zu äußern. Eines Tages in der Zukunft könnte ich kommen, um ihn einzufordern. Vergiss nicht, \"Sir Ritter.\""
  },
  AvgDialog_13054_Content_11 = {
    Text = "Wenn es letzteres ist, sollte das Erwachen des Traumbesitzers uns ermöglichen, von hier zu entkommen, oder?"
  },
  AvgDialog_13054_Content_12 = {
    Text = "Hey! Lord Attendant? Wach auf!"
  },
  AvgDialog_13054_Content_13 = {
    Text = "Deine Gedanken schweiften weit, den Hinweisen folgend. Gerade als der Plan \"Den Traummeister erwecken\" Gestalt annahm, grubst du dir scharf die Nägel in den Arm, und der Schmerz katapultierte dich zurück in die Realität."
  },
  AvgDialog_13054_Content_14 = {
    Text = "Hiss – Es tut weh!"
  },
  AvgDialog_13054_Content_15 = {
    Text = "So kannst du Schmerz empfinden! Wir haben dich ewig gerufen und du hast gar nicht reagiert, wie eine Leiche. Ist etwas mit deinen Ohren nicht in Ordnung?"
  },
  AvgDialog_13054_Content_16 = {
    Text = "Du warst in letzter Zeit abgelenkt. Bist du zu müde? Wie wäre es mit einer Pause im Lehen deiner Familie? Es ist schon lange her, dass du zuletzt Urlaub hattest."
  },
  AvgDialog_13054_Content_17 = {
    Text = "Mach nicht—Es tut mir wirklich leid, ich habe nur etwas im Kopf..."
  },
  AvgDialog_13054_Content_18 = {
    Text = "Der Schlüssel zur Flucht aus dem \"Traum\" liegt bei Ogier. Auch wenn dich interessiert, wie die Welt jenseits des Traumzentrums aussieht, ist dies nicht der Zeitpunkt, zu weit umherzuwandern."
  },
  AvgDialog_13054_Content_19 = {
    Text = "Etwas auf deinem Herzen? Was ist es? Geht es um jemanden, den du magst und der dir Probleme bereitet?"
  },
  AvgDialog_13054_Content_2 = {
    Text = [[
"Traum"
Palast der Prinzessin]]
  },
  AvgDialog_13054_Content_20 = {
    Text = "Machst du dir Sorgen, dass die andere Person dich nicht zurückliebt? Prinzessin, warum macht Ihr nicht eine kleine Weissagung für unseren lieben Bediensteten? Oder besser noch, gebt {Male=him,Female=her} einfach einen Liebestrank—"
  },
  AvgDialog_13054_Content_21 = {
    Text = "Komm schon, wie kannst du Magie und Tränke benutzen, um eine Beziehung aufrechtzuerhalten?"
  },
  AvgDialog_13054_Content_22 = {
    Text = "Die Prinzessin lächelte und lenkte das von der Dienerin angesprochene Thema geschmeidig um, während sie dir zuwinkte."
  },
  AvgDialog_13054_Content_23 = {
    Text = "Ogier trainiert derzeit mit den Rittern. Bitte schau nach ihm und stelle sicher, dass ihm nichts zustößt."
  },
  AvgDialog_13054_Content_24 = {
    Text = "Wie Ihr wünscht!"
  },
  AvgDialog_13054_Content_25 = {
    Text = "Als die Prinzessin dir ein Kissen brachte, während du schläfrig warst, gab es dir einen legitimen Grund, dich Ogier zu nähern."
  },
  AvgDialog_13054_Content_26 = {
    Text = "Jedoch, wenn du wirklich Tränke benötigst, kannst du dich dennoch an mich wenden."
  },
  AvgDialog_13054_Content_27 = {
    Text = "\"Traum\"\nRittertrainingsgelände"
  },
  AvgDialog_13054_Content_28 = {
    Text = "Von anderen Dienern geleitet, bahnst du dir deinen Weg durch das labyrinthische Schloss und die Gärten zu den Trainingsgeländen."
  },
  AvgDialog_13054_Content_29 = {
    Text = "Das knackende Klirren der Waffen und die ununterbrochenen Jubelrufe der anderen zeigen eindeutig, dass jemand unter der brennenden Sonne übt."
  },
  AvgDialog_13054_Content_3 = {
    Text = "Nach dem dritten Versuch, aufzuwachen, der nur dazu führte, dass die Szene unerklärlich wechselte, akzeptiertest du endlich, dass du in Ogier's Erinnerungen gefangen bist."
  },
  AvgDialog_13054_Content_30 = {
    Text = "—Dich wusste nicht, dass einer der Übungspartner Ogier war."
  },
  AvgDialog_13054_Content_32 = {Text = "Hmm...!"},
  AvgDialog_13054_Content_33 = {
    Text = "Im Angesicht einer absoluten Machtungleichheit sind Beharrlichkeit und Glauben nutzlos. Der erwachsene Ritter hat nicht einmal seine volle Stärke eingesetzt, und dennoch hat die metallische Resonanz bereits den Griff von Ogier geschwächt."
  },
  AvgDialog_13054_Content_34 = {
    Text = "Der Speer wurde abgeschlagen, und der junge Mann, durchnässt von Schweiß, kniete auf dem rauen Kiesboden und keuchte nach Atem."
  },
  AvgDialog_13054_Content_35 = {
    Text = "Kind, geh vorerst zurück. Wenn du weiter so übst, brechst du dir am Ende die Hand."
  },
  AvgDialog_13054_Content_36 = {
    Text = "Das stimmt, du bist noch zu jung.\nKomm in ein paar Jahren zurück zum Training. Du kannst jetzt nicht mal eine Waffe heben."
  },
  AvgDialog_13054_Content_37 = {Text = "Nein..."},
  AvgDialog_13054_Content_38 = {
    Text = "Ogier zitterte, beugte sich herunter, um den gefallen Speer aufzuheben, und richtete mit großer Mühe seine Haltung aus, wobei er die Speerspitze auf den Kämpfenden Ritter richtete."
  },
  AvgDialog_13054_Content_39 = {
    Text = "Ich kann... festhalten!"
  },
  AvgDialog_13054_Content_4 = {
    Text = "Du stehst in einer Ecke der Kammer der Prinzessin und tust so, als würdest du zuhören, während du gehorsam die Rolle eines Bediensteten spielst."
  },
  AvgDialog_13054_Content_40 = {
    Text = "Du hartnäckiges Kind..."
  },
  AvgDialog_13054_Content_41 = {
    Text = "Das Gesicht des Jungen wurde rot vor Erschöpfung und Sauerstoffmangel. Die Person, die beabsichtigt hatte, Ogier durch das Training aufzugeben, sprach schließlich angesichts eines so starken Willens."
  },
  AvgDialog_13054_Content_42 = {
    Text = "Überhaupt nicht schlecht. Die Außenstehenden schielen gierig auf unser Herzogtum. Wir brauchen mehr standhafte Kinder wie den jungen Meister Danske."
  },
  AvgDialog_13054_Content_43 = {
    Text = "Soll ich es ernst nehmen?"
  },
  AvgDialog_13054_Content_44 = {
    Text = "Sei nicht so rücksichtslos! Wenn dieses Kind während des Trainings zusammenbricht, wie wirst du das dem Großherzog und der Prinzessin erklären?"
  },
  AvgDialog_13054_Content_45 = {
    Text = "Beginne mit grundlegenden körperlichen Trainings. Halte ein Auge auf ihn und stelle sicher, dass ihn die Waffen nicht verletzen."
  },
  AvgDialog_13054_Content_46 = {
    Text = "Die Worte der Anführerin entzündeten Ogier. Die Augen des jungen Mannes leuchteten sofort auf, voll von Aufregung."
  },
  AvgDialog_13054_Content_47 = {
    Text = "Hast du zugestimmt, mich den Rittern beizutreten?!"
  },
  AvgDialog_13054_Content_48 = {
    Text = "Auch ohne den Witz des Großherzogs, mit diesem Maß an Willenskraft bist du qualifiziert, ein Lehrling Ritter zu sein."
  },
  AvgDialog_13054_Content_49 = {
    Text = "Als der Kapitän die Abschürfungen und Blutspuren des Jungen sah, zögerte er und fühlte sich etwas zurückhaltend."
  },
  AvgDialog_13054_Content_5 = {
    Text = "Prinzessin, Prinzessin! Ich habe gehört, dass der junge Meister von Dansk den Rittern erneut Bericht erstattet hat. Es ist der dritte Tag!"
  },
  AvgDialog_13054_Content_50 = {
    Text = "Geh für heute zurück. Ab morgen gebe ich dir einen maßgeschneiderten Trainingsplan—Und ihr anderen! Hört auf zu schauen und macht zwei zusätzliche Runden mit Gewichten!"
  },
  AvgDialog_13054_Content_51 = {
    Text = "Verschont uns, Captain—"
  },
  AvgDialog_13054_Content_52 = {
    Text = "Bevor der Anführer zu Ende sprach, entfachte die rare heitere Atmosphäre kleine Akte des Aufstands, wobei junge Ritter ihren Stress auf diese Weise abbauten."
  },
  AvgDialog_13054_Content_53 = {
    Text = "Drei Runden!"
  },
  AvgDialog_13054_Content_54 = {
    Text = "Inmitten des unaufhörlichen Weinens entspannte sich Ogier schließlich und fiel mit einem dumpfen Geräusch zu Boden."
  },
  AvgDialog_13054_Content_55 = {
    Text = "Klasse... Endlich..."
  },
  AvgDialog_13054_Content_56 = {
    Text = "Ogier, können wir reden?"
  },
  AvgDialog_13054_Content_57 = {
    Text = "Du bist... Lord Chamberlain! Dass du mich in so einem beschämenden Zustand siehst, ich..."
  },
  AvgDialog_13054_Content_58 = {
    Text = "Ogier richtete sich sofort auf, sein aufgeschürftes Knie rieb sich am Sand, der Schmerz verzerrte seinen angespannter Gesichtsausdruck."
  },
  AvgDialog_13054_Content_59 = {
    Text = "Du hast ihm zugewunken und das Heiltrank herausgeholt, das die Prinzessin dir irgendwann in die Tasche gesteckt hatte."
  },
  AvgDialog_13054_Content_6 = {
    Text = "Er hat die Worte seines Vaters tatsächlich zu Herzen genommen... Wie kann jemand so jung das Training der Ritter aushalten?"
  },
  AvgDialog_13054_Content_60 = {
    Text = "Huh... Tut es nicht weh? Ist das etwa ein Heilmittel?"
  },
  AvgDialog_13054_Content_61 = {
    Text = "Dies ist ein von der Prinzessin persönlich zubereitetes Medikament, wahrscheinlich mit einer speziellen Behandlung."
  },
  AvgDialog_13054_Content_62 = {
    Text = "\"Die Prinzessin, die du dienst, ist ein geheimnisvolles Mädchen. Sie verlässt selten ihre Gemächer, besitzt jedoch ein einzigartiges Verständnis und Talent für Medizin. In deiner Ära wäre sie eine angesehene Pharmazeutin.\""
  },
  AvgDialog_13054_Content_63 = {
    Text = "Es ist schade, dass ihre Talente in den verlorenen Jahrhunderten missverstanden wurden. Du hast andere Bedienstete heimlich mehr als einmal als „Hexe“ bezeichnet hören."
  },
  AvgDialog_13054_Content_64 = {
    Text = "Trank der Prinzessin?! Er ist zu kostbar, um an mir verwendet zu werden—Au!"
  },
  AvgDialog_13054_Content_65 = {
    Text = [[
Beweg dich nicht, oder du verschwendest die Gnade der Prinzessin.
Setz dich zuerst und lass mich die Wunde fertig behandeln.]]
  },
  AvgDialog_13054_Content_66 = {
    Text = "In der Angst, wertvolle Medizin zu verschwenden, setzte sich Ogier schließlich ruhig hin.\nDie anderen Ritter verließen allmählich das Gebiet und nutzten diese seltene Gelegenheit."
  },
  AvgDialog_13054_Content_67 = {
    Text = "Ogier, kannst du spüren, dass du träumst?"
  },
  AvgDialog_13054_Content_68 = {
    Text = "In der Tat, es ist wie ein Traum..."
  },
  AvgDialog_13054_Content_69 = {
    Text = "Der junge Mann verdrehte deine Worte, um der aktuellen Situation gerecht zu werden. Er schloss die Augen und seufzte, seine Stimme war erfüllt von Zufriedenheit und Sehnsucht."
  },
  AvgDialog_13054_Content_7 = {
    Text = "Nein... nein, warte... vielleicht gibt es eine andere Möglichkeit."
  },
  AvgDialog_13054_Content_70 = {
    Text = "Beschworen, gewählt und von den Rittern anerkannt... Es fühlt sich wirklich wie ein Traum an."
  },
  AvgDialog_13054_Content_71 = {
    Text = "<LightGray:(Soll ich ihm direkt sagen, dass dies ein Traum ist? Aber ich habe das Wesen hier noch nicht herausgefunden. Ist es eine Erinnerung oder ein Traum...?)>"
  },
  AvgDialog_13054_Content_72 = {
    Text = "Deine Zögern erregte Ogier's Aufmerksamkeit. Er wurde plötzlich ein wenig unruhig und rieb nervös den Saum seiner Kleidung."
  },
  AvgDialog_13054_Content_73 = {
    Text = "Sir Chamberlain, ist... ist die Prinzessin unzufrieden mit mir?"
  },
  AvgDialog_13054_Content_74 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_13054_Content_75 = {
    Text = "Ogier ist das Kind eines Adligen, der ein Leben in Luxus hätte leben können. Warum besteht er darauf, ein Ritter zu werden?"
  },
  AvgDialog_13054_Content_76 = {
    Text = "Weil... weil..."
  },
  AvgDialog_13054_Content_77 = {
    Text = "Ogier's Stimme wurde leiser und sein Kopf senkte sich weiter in Verlegenheit. Die Antwort auf die Frage ließ ihn offensichtlich zu beschämt fühlen, um zu sprechen."
  },
  AvgDialog_13054_Content_78 = {
    Text = "Ich schwöre, unser Gespräch wird keinem Dritten bekannt sein."
  },
  AvgDialog_13054_Content_79 = {
    Text = "Weil... mein Vater auch krank ist, genau wie Tante Merlyn in der Küche und Bruder Pedro, der Gärtner..."
  },
  AvgDialog_13054_Content_8 = {
    Text = "Basierend auf der Beschreibung der Dienerin befindet sich Ogier in Ausbildung bei dem Ritterorden. Da Ogier an diesem Gespräch nicht teilnahm, kann die Hypothese zu \"Ogiers Erinnerungen\" nicht aufgestellt werden."
  },
  AvgDialog_13054_Content_80 = {
    Text = "Es gibt viele, viele andere, die sich mit derselben Krankheit angesteckt haben."
  },
  AvgDialog_13054_Content_81 = {
    Text = "Mein Vater kann sein Bett nicht mehr verlassen, und ich bin noch nicht erwachsen... Als sein einziges Kind, ich..."
  },
  AvgDialog_13054_Content_82 = {
    Text = "Wenn Vater verstirbt, wird jeder im Herrenhaus entlassen.\nSie sind alle noch krank... und haben keinen Ort, an den sie gehen können."
  },
  AvgDialog_13054_Content_83 = {
    Text = "Ich muss... Ich muss Verantwortung für alle übernehmen... Nur durch das Werden eines Ritters und den Schutz des Herzogs..."
  },
  AvgDialog_13054_Content_84 = {
    Text = "Als er dies sagte, wurde Ogier’s Gesicht blass. Er sah dich besorgt an, als wäre er Angst, dass du ihn wegen „unreiner Motive“ anklagen oder ihn im Namen der Prinzessin bestrafen würdest."
  },
  AvgDialog_13054_Content_85 = {
    Text = "Ähnliche Unschuld, identischer unerschütterlicher Wille.\nOhne Zweifel ist er der Ogier, den du kennst."
  },
  AvgDialog_13054_Content_86 = {
    Text = "Entschuldigung, Eure Exzellenz... Wenn, wenn Sie wünschen, dass die Prinzessin mich ersetzt... Ich-Ich habe keine Einwände..."
  },
  AvgDialog_13054_Content_87 = {
    Text = "In der Nacht, als du vom Großherzog gewählt wurdest, hast du vor all den Gästen bei der Ehre deiner Familie geschworen, nicht wahr?"
  },
  AvgDialog_13054_Content_88 = {
    Text = "Schwöre, deine ritterlichen Pflichten mit deinem Leben zu erfüllen... Warst du ernsthaft, als du den Eid zusammen mit anderen gesprochen hast?"
  },
  AvgDialog_13054_Content_89 = {
    Text = "<Big:Natürlich! Ich mache keine Witze!>"
  },
  AvgDialog_13054_Content_9 = {
    Text = "Das ist nicht nur eine \"Erinnerung.\" Vielleicht bist du in ein Stück realer Geschichte eingetreten, oder vielleicht ist es ein Traum, der von deinem Unterbewusstsein vollendet wurde?"
  },
  AvgDialog_13054_Content_90 = {
    Text = "\"Ich werde immer loyal sein, immer engagiert\" ... Mein Vater würde das Gleiche von mir erwarten."
  },
  AvgDialog_13054_Content_91 = {
    Text = "Alright, ich werde die Prinzessin nicht darüber informieren.\nSei nicht so besorgt, du stehst kurz vor den Tränen."
  },
  AvgDialog_13054_Content_92 = {
    Text = "Gibt es... wirklich?! Entschuldigung!"
  },
  AvgDialog_13054_Content_93 = {
    Text = "Ugh... Ugh?! Meine Augen... sie tun weh..."
  },
  AvgDialog_13054_Content_94 = {
    Text = "Ogier rieb sich unbeholfen die Augen, aber sein Taschentuch war während des Trainings bereits staubig geworden, was seine Verlegenheit verstärkte."
  },
  AvgDialog_13054_Content_95 = {
    Text = "Ich kann es nicht glauben, dass der Kammerdiener mich in einem so peinlichen Zustand gesehen hat..."
  },
  AvgDialog_13054_Content_96 = {
    Text = "Es ist nichts, ich habe dich schon in einem schlechteren Zustand gesehen.\nLass uns zum Palast zurückkehren und dich auffrischen. Du kannst nicht so nach Hause gehen."
  },
  AvgDialog_13054_Content_97 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_13054_Content_98 = {
    Text = "Eure Exzellenz, darf ich Sie um einen Gefallen bitten?"
  },
  AvgDialog_13054_Content_99 = {
    Text = "Ich würde gerne mehr Details hören."
  },
  AvgDialog_13055_Content_1 = {
    Text = "Fäden der Vergangenheit"
  },
  AvgDialog_13055_Content_10 = {
    Text = "Wiederverbinden"
  },
  AvgDialog_13055_Content_11 = {
    Text = "Als du siehst, dass Ogier kurz davor ist, die Kontrolle zu verlieren, entscheidest du dich, nicht länger zu warten, und fasst fest seine Hände, die jetzt mit schwarzem Schlamm bedeckt sind."
  },
  AvgDialog_13055_Content_12 = {
    Text = "Der Silberne Schlüssel flackert, während du deine mentalen Tentakeln durch den Gnosis-Sturm führst, über Schichten der Dunkelheit, und dich wieder mit Ogier verbindest."
  },
  AvgDialog_13055_Content_13 = {
    Text = "Begleitet von einem stechenden Schmerz wie ein elektrischer Schlag, fliegen Szenen vor deinen Augen auf und verschwinden dann sofort."
  },
  AvgDialog_13055_Content_14 = {
    Text = "Anzeichen von Kontrollverlust zogen sich wie eine Flut zurück, und Ogier's Zustand stabilisierte sich. Sein jugendliches Gesicht zeigte einen Hauch von Müdigkeit."
  },
  AvgDialog_13055_Content_15 = {
    Text = "Mein Herr, diesmal... wie lange habe ich durchgehalten?"
  },
  AvgDialog_13055_Content_16 = {
    Text = "Der Timer hat nur eine halbe Umdrehung abgeschlossen; nachdem die Verbindung getrennt wurde, konnte Ogier nicht länger durchhalten als in der vorherigen Trainingssession."
  },
  AvgDialog_13055_Content_17 = {
    Text = "Hmm... 30 Sekunden, plus 200 Millisekunden."
  },
  AvgDialog_13055_Content_18 = {
    Text = "Wie... wie konnte das passieren...!"
  },
  AvgDialog_13055_Content_19 = {
    Text = "Sein Ton war unruhig, schließlich war es seine Idee, das <Yellow:Chain-Breaking Training> vorzuschlagen."
  },
  AvgDialog_13055_Content_2 = {
    Text = "Mythag Universität Trainingsgelände\nDämmerung"
  },
  AvgDialog_13055_Content_20 = {
    Text = "Er wird von der Anomalie am Tag der Schlüsselübergabe verfolgt, aus Angst, dass er eines Tages die Kontrolle verlieren und seine Speere gegen dich richten könnte. Daher versucht er, seine Fähigkeit zu verbessern, rational zu bleiben, ohne eine Verknüpfung"
  },
  AvgDialog_13055_Content_21 = {
    Text = "Mein Herr, lass es uns noch einmal versuchen!"
  },
  AvgDialog_13055_Content_22 = {
    Text = "Wir haben lange trainiert. Übertraining wird nach hinten losgehen."
  },
  AvgDialog_13055_Content_23 = {
    Text = "Ogier's Augen flackerten, dimmten sich aber schließlich, sein Ton war von Selbstvorwurf getönt."
  },
  AvgDialog_13055_Content_24 = {
    Text = "Es war mein Versehen..."
  },
  AvgDialog_13055_Content_25 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_13055_Content_26 = {
    Text = "Bis morgen nach dem Mittagessen. Ich habe auch keine Ermittlungsaufgaben."
  },
  AvgDialog_13055_Content_27 = {Text = "Mein Herr!"},
  AvgDialog_13055_Content_28 = {
    Text = "Unter dem begeisterten Blick des Welpen zogst du deinen ebenso erschöpften Körper zurück ins Wohnheim."
  },
  AvgDialog_13055_Content_29 = {
    Text = "Eine einfach gewaschene Mumie liegt auf einem weichen Bett, dankbar für Mythags Wahl der Bettwaren, während das Bewusstsein allmählich dahindriftet..."
  },
  AvgDialog_13055_Content_3 = {
    Text = "Der silberne Schlüssel funkelt, während du den unsichtbaren, zarten Silberfaden in deinem Geist kontrollierst und ihn aus dem strahlenden Licht zurückziehst."
  },
  AvgDialog_13055_Content_30 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_13055_Content_31 = {
    Text = "Seltsame Melodien hallen in der Dunkelheit wider, begleitet vom Klang der silbernen Becher. Eine geschäftige, aber elegante Atmosphäre erfüllt den Traum."
  },
  AvgDialog_13055_Content_32 = {
    Text = "So laut... Wer feiert mitten in der Nacht in den Schlafsälen...?"
  },
  AvgDialog_13055_Content_33 = {
    Text = "Du hast dich umgedreht und nach der Decke gegriffen, die vom Bett geschmissen worden war."
  },
  AvgDialog_13055_Content_34 = {
    Text = "Eine Hand griff in den Nebel und erfasste eine Wolke voller Unbekanntem, fühlte sich sowohl real als auch unreal an."
  },
  AvgDialog_13055_Content_35 = {
    Text = "Oh, da bist du ja! Ich habe gerade nach dir gesucht."
  },
  AvgDialog_13055_Content_36 = {
    Text = "Wh...at...?"
  },
  AvgDialog_13055_Content_37 = {
    Text = "Meine Beine fühlen sich wieder schwach an. Könntest du bitte zu meinem Vater gehen und meinen Ritter holen?"
  },
  AvgDialog_13055_Content_38 = {Text = "Ritter...?"},
  AvgDialog_13055_Content_39 = {
    Text = "Worauf wartest du? Hast du nicht gehört, was die Prinzessin gesagt hat?"
  },
  AvgDialog_13055_Content_4 = {Text = "Hmm...!"},
  AvgDialog_13055_Content_40 = {
    Text = "Die Frau klopfte dir plötzlich auf die Schulter. Die Dunkelheit verblasste und offenbarte einen unbekannten Ort."
  },
  AvgDialog_13055_Content_41 = {
    Text = "Ein großer Saal, eine Band, die in der Ferne alte Suiten spielt, exquisite und verlockende Desserts, und Adelige Frauen, die dich alle anstarren."
  },
  AvgDialog_13055_Content_42 = {
    Text = "Und das Mädchen, das auf dem weichen Sofa faulenzt, umgeben von ihnen."
  },
  AvgDialog_13055_Content_43 = {
    Text = "Das macht nichts, seid nicht zu streng mit {Male=him,Female=her}. Meine Bedienstete war die ganze Nacht ohne Rast beschäftigt, um allen ein perfektes Bankett zu bereiten."
  },
  AvgDialog_13055_Content_44 = {
    Text = "Das Mädchen, das oft von anderen wegen ihres adligen Status als Prinzessin bezeichnet wird, half dir sanft aus der Situation."
  },
  AvgDialog_13055_Content_45 = {
    Text = "Könntest du den „Ritter“, den mein Vater mir zur Begegnung zugewiesen hat, mitbringen? Dann kannst du dich für den Tag ausruhen, okay?"
  },
  AvgDialog_13055_Content_46 = {
    Text = "Eine Flut von fragmentierten Erinnerungen strömt in deinen Geist. Sie sind unzusammenhängend und unvollständig, aber genügend, damit du die Rolle dieser Hülle übernehmen kannst – die einzige Dienerin der Prinzessin."
  },
  AvgDialog_13055_Content_47 = {
    Text = "...Danke für deine Freundlichkeit, Prinzessin."
  },
  AvgDialog_13055_Content_48 = {
    Text = "Der Instinkt deines Körpers forderte dich auf, ihr zu huldigen. Zwischen neidischen oder verächtlichen Blicken bahntest du dir deinen Weg durch die Gruppe von Adligen in den überfüllten Saal."
  },
  AvgDialog_13055_Content_49 = {
    Text = "Du schaust auf \"deine\" Hände. Die Haut ist ein paar Nuancen dunkler als das, was du normalerweise unter Handschuhen verbirgst, übersät mit schwachen Narben, die eindeutig auf ein Leben weit entfernt von Luxus hinweisen."
  },
  AvgDialog_13055_Content_5 = {
    Text = "Drücke dich nicht zu sehr. Wenn du nicht mehr weitermachen kannst, verknüpfe dich mit dem Schwarzen Pool!"
  },
  AvgDialog_13055_Content_50 = {
    Text = "Die vorbeiziehende verzierte Metallvase bestätigte weiter das unheilvolle Gefühl—"
  },
  AvgDialog_13055_Content_51 = {
    Text = "Die Reflexion, die dort gezeigt wird, ist nicht dein Gesicht."
  },
  AvgDialog_13055_Content_52 = {
    Text = "Euer Exzellenz! Sind Sie hier im Namen der Prinzessin gekommen?"
  },
  AvgDialog_13055_Content_53 = {
    Text = "Die Dienstmagd, die aus der Menge auftauchte, hatte schärfere Augen als du und entdeckte das vertraute \"du\" sofort in der geschäftigen Menge."
  },
  AvgDialog_13055_Content_54 = {
    Text = "<Small:Der Herzog hat einen so jungen Ritter gewählt! Lassen sie wirklich ein so junges Kind an der Ritterausbildung teilnehmen? Ich bezweifle, dass er überhaupt eine Waffe heben kann.>"
  },
  AvgDialog_13055_Content_55 = {
    Text = "<BigItalic: Entschuldigung, bitte machen Sie Platz. Wir sind hier im Auftrag von Prinzessin @1, um eine Audienz anzufragen—>"
  },
  AvgDialog_13055_Content_56 = {
    Text = "<Small:Du hast es gerade nicht gesehen, aber als der Herzog ihn vor allen brachte, wurde sein Gesicht vor Scham knallrot.>"
  },
  AvgDialog_13055_Content_57 = {
    Text = "<BigItalic:Entschuldigung, Entschuldigung! Die Dienerin der Prinzessin ist angekommen!!>"
  },
  AvgDialog_13055_Content_58 = {
    Text = "<Small:Wie lange wird es dauern, bis ein Kind wie dieses ein wahrer Ritter wird... Der Herzog muss scherzen, oder?>"
  },
  AvgDialog_13055_Content_59 = {
    Text = "Die Dienstmagd bahnte sich mit ihren Worten geschickt einen Weg durch die Menge, während sie dir spielerische Bemerkungen ins Ohr flüsterte, und führte dich zum Thron."
  },
  AvgDialog_13055_Content_6 = {
    Text = "Ich kann... immer noch... festhalten..."
  },
  AvgDialog_13055_Content_60 = {
    Text = "Hallo. Sind Sie der Kammerherr?"
  },
  AvgDialog_13055_Content_61 = {
    Text = "Du bist...!"
  },
  AvgDialog_13055_Content_62 = {
    Text = "Ich bin der älteste Sohn der Familie Danske. Ich bin dem Großherzog für seine Gunst tief dankbar und fühle mich äußerst geehrt, als Ritter von Prinzessin @1 zu dienen."
  },
  AvgDialog_13055_Content_7 = {
    Text = "Ogier kniete auf einem Knie; ohne die Unterstützung der Verknüpfung hielt er seinen Körper mit einem Speer in Schach, um nicht zu fallen"
  },
  AvgDialog_13055_Content_8 = {Text = "Meister..."},
  AvgDialog_13055_Content_9 = {
    Text = "Schwarze Flüssigkeit trat aus den Ecken seiner Augen, den Rändern seiner Lippen und seinen Gehörgängen hervor. Seine Organe waren von amorphem schwarzem Schleim zerdrückt worden, was deutlich machte, wie unvorstellbar der Schmerz war, den der Junge ertrug."
  },
  AvgDialog_13056_Content_1 = {
    Text = "Neue Ballade"
  },
  AvgDialog_13056_Content_10 = {
    Text = "Komm nicht näher! Ich werde kein Erbarmen zeigen!"
  },
  AvgDialog_13056_Content_100 = {
    Text = "Lass uns gehen. Heute ist ein freier Tag, und der Ostmarkt wird belebt sein. Wir können auch das Waisenhaus besuchen und nach den Kindern sehen..."
  },
  AvgDialog_13056_Content_101 = {
    Text = "Du murmelst absichtlich deinen Zeitplan und gehst ohne Sorgen aus dem Trainingsgelände weg."
  },
  AvgDialog_13056_Content_102 = {
    Text = "Meister! Meister! Bitte sag mir, wie du es wusstest—"
  },
  AvgDialog_13056_Content_103 = {
    Text = "Weil du weißt, dass er folgen wird."
  },
  AvgDialog_13056_Content_11 = {
    Text = "Ogier erhob seinen Speer und blockierte die Treppe."
  },
  AvgDialog_13056_Content_12 = {
    Text = "Dies ist deine letzte Warnung. Verlasse jetzt den Palast!"
  },
  AvgDialog_13056_Content_13 = {
    Text = "Hey, hast du das gehört? Was hat er gesagt? \"Bitte bitten Sie uns zu gehen\"?"
  },
  AvgDialog_13056_Content_14 = {
    Text = "Hahaha, das ist lustig! Kein Wunder, dass das Herzogtum so schwach ist – sie spielen mit Kindern Ritter."
  },
  AvgDialog_13056_Content_15 = {
    Text = "Sei leise, meine Ohren tun weh."
  },
  AvgDialog_13056_Content_16 = {
    Text = "Der Offizier ignorierte Ogiers Warnung, ging zur Schlafzimmer Tür und sah auf Ogier hinunter."
  },
  AvgDialog_13056_Content_17 = {
    Text = "Tretet zur Seite."
  },
  AvgDialog_13056_Content_18 = {
    Text = "Ogier strengte sich an, den Speer horizontal zu halten, um den Ansturm des Offiziers zu blockieren."
  },
  AvgDialog_13056_Content_19 = {
    Text = "Bitte gehen Sie!"
  },
  AvgDialog_13056_Content_2 = {
    Text = "Stiefel, funkelnd und mit Staub bedeckt, traten auf den Palastteppich."
  },
  AvgDialog_13056_Content_20 = {
    Text = "Wusstest du, dass eine Ritterwaffe dir nicht passt?"
  },
  AvgDialog_13056_Content_22 = {
    Text = "Widerstand ist angesichts überwältigender Macht zwecklos.\nDer Offizier wischte mühelos Ogier's Speer beiseite und stieß ihm ein Messer in die Brust."
  },
  AvgDialog_13056_Content_23 = {Text = "*Hust—!*"},
  AvgDialog_13056_Content_24 = {
    Text = "Siehst du das? Das ist die Fähigkeit, die du lernen solltest.\nSchließlich, mit deinem Land, das zerstört ist, verdienst du es nur, in den dunklen Gassen zu bleiben, ohne jemals das Licht des Tages zu sehen."
  },
  AvgDialog_13056_Content_25 = {
    Text = "Diebstahl, Hunger und gegenseitiger Hass... das ist dein Schicksal.  \nDer Speer, der den Ritterehren symbolisiert, wird dir in Zukunft natürlich von keinem Nutzen sein."
  },
  AvgDialog_13056_Content_26 = {
    Text = "Blut stieg in die Luftröhre und verursachte einen dumpfen Schmerz, als würde man an Land ertrinken. Jeder Atemzug spritzte mit dem Geruch von Blut."
  },
  AvgDialog_13056_Content_27 = {
    Text = "Du möchtest über den niedrigen Tisch springen, den Sergeant die Treppe hinunterstoßen und Ogier, der an der Tür kniet, beschützen.\nAber dein Körper zittert plötzlich, erstarrt und gehorcht deinen Befehlen nicht mehr."
  },
  AvgDialog_13056_Content_28 = {
    Text = "Nein... *husten*..."
  },
  AvgDialog_13056_Content_29 = {
    Text = "Ich habe mich missverstanden; diese Zukunft wirst du nicht mehr sehen – du wirst zu Brennstoff für diesen Palast, genau wie er."
  },
  AvgDialog_13056_Content_3 = {
    Text = "Dies ist dein Lieblingsteppich in \"Traum Erinnerungen.\" Du und das lärmende Dienstmädchen habt den ganzen Nachmittag damit verbracht, ihn im Lagerhaus des Großherzogs auszuwählen, und einen weiteren halben Tag damit, ihn auszulegen."
  },
  AvgDialog_13056_Content_30 = {
    Text = "Der gepanzerte Stiefel trat auf Fernandos Leiche, begleitet vom Klirren von Metall und dem scharfen Geräusch brechender Knochen."
  },
  AvgDialog_13056_Content_31 = {Text = "...Fair..."},
  AvgDialog_13056_Content_33 = {
    Text = "Jeder Muskel von Adrenalin getrieben, hebt er plötzlich seinen Speer und stürmt auf den Feind zu!"
  },
  AvgDialog_13056_Content_34 = {
    Text = "<Big:Berühre ihn nicht!>"
  },
  AvgDialog_13056_Content_36 = {Text = "Hngh—!"},
  AvgDialog_13056_Content_37 = {
    Text = "Widerstand war zwecklos. Sein Angriff konnte den Offizier nicht einmal erschüttern und ließ seinen Rücken dem Späher schutzlos."
  },
  AvgDialog_13056_Content_38 = {
    Text = "Dieses Kind ist wirklich stur. Wenn er zu Beginn weggelaufen wäre, hätten wir nicht die Zeit gehabt, ihn zu verfolgen, oder?"
  },
  AvgDialog_13056_Content_39 = {
    Text = "Kleiner Bruder, du wirkst so entschlossen. Beschützt du etwas?\nIst die Prinzessin hinter der Tür?"
  },
  AvgDialog_13056_Content_4 = {
    Text = "Die Prinzessin verlässt selten ihr Zimmer. An das Geländer des Korridors im zweiten Stock gelehnt, beobachtet sie, wie ihr alle beschäftigt in der Halle seid, mit einer entspannten Haltung. Ogier, hier für eine Audienz, ist so nervös, dass er nicht weiß, wo er seine Füße platzieren soll."
  },
  AvgDialog_13056_Content_40 = {
    Text = "Blut floss aus den Ohren von Ogier. Er konnte nicht jedes Wort hören, aber er erfasste dennoch die entscheidende Aussprache."
  },
  AvgDialog_13056_Content_41 = {
    Text = "Nein... geh nicht..."
  },
  AvgDialog_13056_Content_42 = {
    Text = "Die Sicht beginnt an den Rändern zu erbleichen, und eine Kraft zieht das Bewusstsein aus dem jugendlichen Körper heraus."
  },
  AvgDialog_13056_Content_43 = {
    Text = "Er kroch vorwärts, über Fernandos Leiche, vorbei an den Stiefeln der Offiziere und Späher, bis seine Finger schließlich die schwere Holztür berührten."
  },
  AvgDialog_13056_Content_44 = {
    Text = "Warm anzufassen, mit einem leicht scharfen, holzigen Aroma, kommt oft eine sanfte und fürsorgliche Stimme von hinter der Tür.\nIn diesem Moment gibt es außer dem Ticken der Wasseruhr kein einziges Geräusch von hinter der Tür."
  },
  AvgDialog_13056_Content_45 = {
    Text = "Verlassen... diesen Ort..."
  },
  AvgDialog_13056_Content_46 = {
    Text = "<Big:Ah——!>"
  },
  AvgDialog_13056_Content_47 = {
    Text = "Dieses Mal war es seine lange Speere, die tief ins Fleisch eindrang."
  },
  AvgDialog_13056_Content_48 = {
    Text = "Die Waffe, die von unzähligen Menschen verspottet, von Feinden verachtet, aber niemals von ihrem Träger verlassen wurde."
  },
  AvgDialog_13056_Content_49 = {
    Text = "Der Speer durchbohrte seinen Körper und pinte ihn an die Tür, sodass er sich nicht bewegen konnte."
  },
  AvgDialog_13056_Content_5 = {
    Text = "Kein Herzogritter... Versteck dich schnell!"
  },
  AvgDialog_13056_Content_50 = {
    Text = "Ow—sei nicht so grausam.\nWas ist, wenn die \"Hexenprinzessin\" uns verflucht, weil wir ihren Ritter so quälen?"
  },
  AvgDialog_13056_Content_51 = {
    Text = "Eine Hexe? Lächerlich."
  },
  AvgDialog_13056_Content_52 = {
    Text = "<Small:@1Prinzessin... nicht...>"
  },
  AvgDialog_13056_Content_53 = {
    Text = "Ogier öffnete seinen Mund, der Name der Prinzessin lag ihm auf der Zunge, doch er konnte sich einfach nicht dazu bringen, ihn auszusprechen."
  },
  AvgDialog_13056_Content_54 = {
    Text = "<Small:@1...>"
  },
  AvgDialog_13056_Content_55 = {
    Text = "Er hörte das Geräusch von fließendem Wasser. War die Wasseruhr umgefallen? Bedeutete das...@1 die Prinzessin war noch am Leben?"
  },
  AvgDialog_13056_Content_56 = {
    Text = "<Small:Nein... komm nicht... nein... komm nicht rein...>"
  },
  AvgDialog_13056_Content_57 = {
    Text = "Genug... Ogier... Danke..."
  },
  AvgDialog_13056_Content_58 = {
    Text = "Danke... mein..."
  },
  AvgDialog_13056_Content_59 = {
    Text = "Schwarze Ströme sickerten zuerst unter die Tür und vermischten sich mit Ogier's Blut, wie Tränen, die für jemanden vergossen wurden."
  },
  AvgDialog_13056_Content_6 = {
    Text = "Warte! Was ist mit dir?!"
  },
  AvgDialog_13056_Content_60 = {
    Text = "Dann brach eine massive, flutähnliche Welle durch die Ritzen in der Tür, brüllte und schwoll an, um sofort den Palast zu engulfieren."
  },
  AvgDialog_13056_Content_61 = {
    Text = "<Shake:Ugh—Ugh!>"
  },
  AvgDialog_13056_Content_62 = {
    Text = "Die Pest, für gewöhnliche Menschen unsichtbar, überschüttete die beiden, als schwarzes Geschmiere ihre Sinne flutete und sie in der Luft ertränkte."
  },
  AvgDialog_13056_Content_63 = {
    Text = "<Shake: Fluch, es ist ein Fluch—>"
  },
  AvgDialog_13056_Content_65 = {
    Text = "Keeper? Wach auf, Keeper? %player%?"
  },
  AvgDialog_13056_Content_66 = {Text = "Ogier!"},
  AvgDialog_13056_Content_67 = {
    Text = "Hast du einen Albtraum? Sieh genauer hin. Wer bin ich?"
  },
  AvgDialog_13056_Content_68 = {
    Text = "...Puppe? Was machst du in meinem Zimmer?"
  },
  AvgDialog_13056_Content_69 = {
    Text = "Es ist mir egal, was der Inhalt deines Albtraums ist, aber letzte Nacht waren deine Geisterwellen aktiv, als würden sie tanzen."
  },
  AvgDialog_13056_Content_7 = {
    Text = "Ogier drängt dich heftig, zwingt dich unter den niedrigen Tisch.\nDein Blick dreht sich, und alles, was du sehen kannst, ist der luxuriöse persische Teppich, der sich wegen der Flammen an den Rändern kräuselt."
  },
  AvgDialog_13056_Content_70 = {
    Text = "Die mit dir verbundenen Erwecker, einschließlich mir, haben mehr oder weniger etwas Ungewöhnliches wahrgenommen."
  },
  AvgDialog_13056_Content_71 = {
    Text = "Letzte Nacht? ...Es ist nur eine Nacht vergangen. Könnte es wirklich nur ein Traum gewesen sein?"
  },
  AvgDialog_13056_Content_72 = {
    Text = [[
Du beschreibst alles im absurden Traum der Puppe.
Prinzessinnen, Ritter, Plagen...]]
  },
  AvgDialog_13056_Content_73 = {
    Text = "Unter den Ermittlern, die mit den Erwachern verbunden sind, sind Fälle von Gedächtnis- und Emotionresonanz selten. Aber das, was du beschrieben hast... habe ich noch nie gehört."
  },
  AvgDialog_13056_Content_74 = {
    Text = "Es scheint, dass dieser „Traum-Eintrag“ dir keine weiteren Folgen bereitet hat. Ich werde weiterhin deine mentale Wellenform genau überwachen."
  },
  AvgDialog_13056_Content_75 = {
    Text = "...Vielleicht möchtest du Ogier jetzt treffen?"
  },
  AvgDialog_13056_Content_76 = {
    Text = "Das Gefühl, von D-Schleim verschlungen zu werden, war zu real. Das Morgenlicht wärmte die Decken, aber der Körper fühlte sich an, als wäre er in einen eisigen Abgrund gefallen."
  },
  AvgDialog_13056_Content_77 = {
    Text = "Ogier... Ja, ich habe heute mehr Training mit ihm organisiert..."
  },
  AvgDialog_13056_Content_78 = {
    Text = "Mythag Universität Trainingsgelände\nMorgen"
  },
  AvgDialog_13056_Content_79 = {
    Text = "Wow—Nein, nein, nein, ich werde sterben—"
  },
  AvgDialog_13056_Content_8 = {
    Text = "Ist es nur dieses Kind? Sind wir am richtigen Ort angekommen?"
  },
  AvgDialog_13056_Content_80 = {
    Text = "Verschone mir, verschone diesem armen kleinen Journalisten, Sir Ogier—"
  },
  AvgDialog_13056_Content_81 = {
    Text = "Miss Hannah, halte noch ein wenig durch. Es gibt nur noch eine Runde übrig.\nDu wirst diesen Fitnesstest definitiv bestehen!"
  },
  AvgDialog_13056_Content_82 = {
    Text = "Waaah... In Ordnung..."
  },
  AvgDialog_13056_Content_83 = {
    Text = "Die Campus-Brokerin, mit beschwerten Sandsäcken an den Waden, weinte, während sie um das Trainingsfeld joggte.\nOgier joggte neben ihr her, ermutigte sie und hielt mühelos mit ihrem Tempo Schritt, ohne ins Schwitzen zu kommen."
  },
  AvgDialog_13056_Content_84 = {Text = "Ogier"},
  AvgDialog_13056_Content_85 = {Text = "Hüter!"},
  AvgDialog_13056_Content_86 = {
    Text = "Er wies die Aufsicht über Hannahs Aufgaben anderen Mitarbeitern zu und rannte auf dich zu."
  },
  AvgDialog_13056_Content_87 = {
    Text = "Hast du nicht gesagt, unser Training beginnt am Nachmittag? Warum bist du so früh hier?"
  },
  AvgDialog_13056_Content_88 = {
    Text = "Er und die anderen Schüler, die Erwacher, sind den ganzen Morgen im Trainingsbereich, und dennoch zeigen sie keine Ermüdungserscheinungen, sondern schauen euch mit Ehrfurcht und Energie an."
  },
  AvgDialog_13056_Content_89 = {Text = "Ich..."},
  AvgDialog_13056_Content_9 = {
    Text = "Das stimmt, es ist deutlich auf der strategischen Karte verzeichnet - dies sind die Frauenquartiere."
  },
  AvgDialog_13056_Content_90 = {
    Text = "... Nach Hannahs Training erkunden wir das Stadtzentrum von Londinium."
  },
  AvgDialog_13056_Content_91 = {Text = "Huh?"},
  AvgDialog_13056_Content_92 = {
    Text = "Ogier hat offensichtlich nicht erwartet, dass du plötzlich vorschlägst, eine Pause einzulegen, und du hast das auch nicht."
  },
  AvgDialog_13056_Content_93 = {
    Text = "Meister, bitte erlaube mir, abzulehnen. Die Krise der Auflösung steht kurz bevor. Ich... bin noch nicht bereit."
  },
  AvgDialog_13056_Content_94 = {
    Text = "Statt mich der Freizeit hinzugeben, möchte ich mich mehr auf die Verfeinerung meiner Kampfkünste konzentrieren."
  },
  AvgDialog_13056_Content_95 = {
    Text = "Lass es uns anders sagen."
  },
  AvgDialog_13056_Content_96 = {
    Text = "Dieser Nachmittag, den ich mit ihm in den Rittern verbracht habe, kam mir plötzlich in den Sinn. Erinnerungen, von denen du dachtest, sie würden mit dem Traum verblassen, tauchten wieder auf."
  },
  AvgDialog_13056_Content_97 = {
    Text = "Jetzt ist die Zeit, deinen Wunsch zu erfüllen, Sir Ritter."
  },
  AvgDialog_13056_Content_98 = {Text = "!?"},
  AvgDialog_13056_Content_99 = {
    Text = "Wie... Wie hast du das gewusst?!"
  },
  AvgDialog_130571_Content_1 = {
    Text = "Peng——————"
  },
  AvgDialog_130571_Content_10 = {
    Text = "Ah, ah... Kohleball, es tut mir leid... Mosk, halt sie fest."
  },
  AvgDialog_130571_Content_11 = {
    Text = "Es ist nichts, aber Mosk, warum bist du plötzlich hereingestürmt?"
  },
  AvgDialog_130571_Content_12 = {
    Text = "Ah! Mosk, heiß! Umarme den Kohleball, fühlt sich gut an!"
  },
  AvgDialog_130571_Content_13 = {
    Text = "Mosk, seltsam, weil es nicht mehr kalt ist."
  },
  AvgDialog_130571_Content_14 = {
    Text = "Aber, so heiß, so heiß..."
  },
  AvgDialog_130571_Content_15 = {
    Text = "(Scheiße, könnte es der Einfluss des Heiligen Flusses sein?)"
  },
  AvgDialog_130571_Content_16 = {
    Text = "Mosk, ich weiß nicht..."
  },
  AvgDialog_130571_Content_17 = {
    Text = "Mosk's Blick wird zunehmend verschwommen, während ihre zarten Finger durch die Lücken deiner Kleidung gleiten und sanft deine Haut streicheln."
  },
  AvgDialog_130571_Content_18 = {
    Text = "Du bist mit diesem Gefühl sehr vertraut, in diesem Traum würde “Kohleball“ gelegentlich diesen Pflege-Service in Mosks Armen genießen."
  },
  AvgDialog_130571_Content_19 = {
    Text = "Kohleball, umarmen, ruhig~"
  },
  AvgDialog_130571_Content_2 = {
    Text = "Kohleball, umarmen——"
  },
  AvgDialog_130571_Content_20 = {
    Text = "Kohleball, der Geruch, schön~"
  },
  AvgDialog_130571_Content_21 = {
    Text = "Mosk schnüffelt sanft an dir. Du bist dir nicht sicher, ob es der verbleibende Duft des Parfums auf dir ist oder ob deine eigene Einzigartigkeit Mosk beruhigt hat."
  },
  AvgDialog_130571_Content_22 = {
    Text = "Aber du verstehst, dass du Mosk nicht so weitermachen lassen kannst."
  },
  AvgDialog_130571_Content_23 = {
    Text = "Der Boden ist hart, und dein Rücken protestiert; er vermisst die Weichheit des Bettes."
  },
  AvgDialog_130571_Content_24 = {
    Text = "Dann halte mich heute Nacht fest und lass uns zusammen schlafen?"
  },
  AvgDialog_130571_Content_25 = {
    Text = "Ja! Kohleball, gefällt mir! Ich möchte eine Umarmung!"
  },
  AvgDialog_130571_Content_26 = {
    Text = "Umarmen Kohleball, schlafen, schlafen~"
  },
  AvgDialog_130571_Content_27 = {
    Text = "Du liegst mit Mosk auf dem weichen Bett, die beiden von euch umarmen euch und schauen euch in die Augen, genau wie früher auf dem Schiff."
  },
  AvgDialog_130571_Content_28 = {
    Text = "Mosk, es ist nicht mehr heiß~ Mosk, so angenehm~"
  },
  AvgDialog_130571_Content_29 = {
    Text = "Gute Nacht...zzz...Kohleball...zzz"
  },
  AvgDialog_130571_Content_3 = {Text = "M-Mosk?"},
  AvgDialog_130571_Content_4 = {
    Text = "Mosk stürmt plötzlich lebhaft in den Raum, umschlingt deinen Taillenumfang mit ihren Händen, ihr silbernes Haar reibt ständig an deiner Brust."
  },
  AvgDialog_130571_Content_5 = {
    Text = "Du atmest leise erleichtert auf. Es scheint, als hätte sie die Weitsicht gehabt, das ‚grauenhafte Objekt' an ihrer linken Hand einzuziehen, und dir so das Risiko eines versehentlichen Bisses erspart."
  },
  AvgDialog_130571_Content_6 = {
    Text = "Kohleball, angenehm——"
  },
  AvgDialog_130571_Content_7 = {
    Text = "Mosk, warte, warte einen Moment, ah——"
  },
  AvgDialog_130571_Content_8 = {Text = "Dong."},
  AvgDialog_130571_Content_9 = {
    Text = "Leider hat Mosk, wie du gedacht hast, ihre Kraft nicht gut kontrolliert, und ihr seid beide zu Boden gefallen."
  },
  AvgDialog_131200_Content_1 = {
    Text = "Sanfte Fesseln"
  },
  AvgDialog_131200_Content_10 = {
    Text = "Arachne streichelte die verbleibende Hälfte des Gesichts des Mädchens. Als sie sanft die Augen des Mädchens schloss, strahlte die riesige Säule hinter ihr ein schwaches Licht aus."
  },
  AvgDialog_131200_Content_11 = {
    Text = "Arachne streckte die Hand aus. Ein wenig Glut aus der Laterne wirbelte wie vom Wind aufgewirbelter feiner Sand um ihre zarten Finger, tanzte und floss, bevor es zu Boden fiel."
  },
  AvgDialog_131200_Content_12 = {
    Text = "Die Reste der Dimension Glut... Unsere Wahrnehmung trügt nicht, hier war einst der Ort, an dem Nefraea die Glut verborgen hat, aber jetzt wurde die Glut von ihr mitgenommen."
  },
  AvgDialog_131200_Content_13 = {
    Text = "Nimm die Glut mit, töte die Geheimeinheit, was will Nefraea eigentlich erreichen..."
  },
  AvgDialog_131200_Content_14 = {Text = "Hm?"},
  AvgDialog_131200_Content_15 = {
    Text = "Es scheint, als wäre Arachne von etwas erschreckt worden. Sie hob den Kopf und blickte durch das bunt verglaste Fenster mit dem Laternen-Symbol in Richtung der Station, die nicht weit entfernt war."
  },
  AvgDialog_131200_Content_16 = {
    Text = "Arachne? Was ist los mit dir?"
  },
  AvgDialog_131200_Content_17 = {
    Text = "Die Präsenz des Wesens... ich kann sie nicht mehr wahrnehmen."
  },
  AvgDialog_131200_Content_18 = {Text = "!!!"},
  AvgDialog_131200_Content_19 = {
    Text = "Sagst du, dass du das Theater verlassen hast?"
  },
  AvgDialog_131200_Content_2 = {
    Text = "Finger, Unterschenkel, Augapfel, Rippen, Kopf... Der Meister schnitt die geliebte Puppe ab und warf sie in die schleimige Substanz und das Blut."
  },
  AvgDialog_131200_Content_20 = {
    Text = "Während wir nach dem geheimen Wesen suchten, reinigte mein Körper die Diener der Abgründe entlang der Fäden der Stadt. Nachdem sie von dem Aufenthaltsort der „Erinnerung\" erfahren hatte, machte sie sich auf den Weg zur Kirche, um uns abzuholen."
  },
  AvgDialog_131200_Content_21 = {
    Text = "Ihre Präsenz ist bereits sehr nah... aber jetzt ist diese Präsenz verschwunden."
  },
  AvgDialog_131200_Content_22 = {
    Text = "Kann es sein, dass... ihr etwas zugestoßen ist? Aber die „Erinnerung\" ist erst vor kurzem gestorben, wie könnte das sein..."
  },
  AvgDialog_131200_Content_23 = {
    Text = "Was genau passiert ist, weiß ich nicht. Aber bevor sie verschwand, berührte sie das Netz, über das ich Kontakt zu ihr hatte. Abgesehen von den zurückkommenden Anweisungen war das letzte Wort, das sie hinterließ, ein einziges Wort."
  },
  AvgDialog_131200_Content_24 = {
    Text = "„Freude\"."
  },
  AvgDialog_131200_Content_25 = {Text = "Freude...?"},
  AvgDialog_131200_Content_26 = {
    Text = "Vor dir erscheint N mit diesem abscheulichen Lächeln."
  },
  AvgDialog_131200_Content_27 = {
    Text = "Ich habe nicht verstanden... Ihr habt die gleiche Erinnerung, du musst wissen, was sie ausdrücken möchte."
  },
  AvgDialog_131200_Content_28 = {
    Text = "Arachne schüttelte sanft den Kopf."
  },
  AvgDialog_131200_Content_29 = {
    Text = "Dein Schicksal ist ein Schmetterling, den ich nicht zu berühren wage; jede Erklärung würde unermessliche Wellen schlagen."
  },
  AvgDialog_131200_Content_3 = {
    Text = "„Erinnerung \"..."
  },
  AvgDialog_131200_Content_30 = {
    Text = "Aber du solltest wissen, dass in deiner kurzen Zukunft „Freude\" ein Schlüssel ist, der das Geheimnis öffnet, dem du gegenüberstehst."
  },
  AvgDialog_131200_Content_31 = {
    Text = "Meine... Zukunft? Du meinst, du kannst jetzt tatsächlich meinen Schicksalsfaden sehen?!"
  },
  AvgDialog_131200_Content_32 = {
    Text = "Ihr erwidert ihren Blick. In diesem sanften Lächeln erkennt Ihr die unbestreitbare Autorität des Schicksals."
  },
  AvgDialog_131200_Content_33 = {
    Text = "...Egal was passiert, vertraue mir und vertraue dir selbst."
  },
  AvgDialog_131200_Content_34 = {
    Text = "Kehrt zurück zum Theater des Schicksals. Der Schlüssel und das Schloss erwarten Euch dort, %player%."
  },
  AvgDialog_131200_Content_35 = {Text = "Aber..."},
  AvgDialog_131200_Content_36 = {
    Text = "Arachne's ruhige Stimme war wie die sanfte Abendsonne eines Herbsttages. Ihre Gestalt verwandelte sich in eine Handvoll Spinnweben und verschwand im stillen Licht der Kirche."
  },
  AvgDialog_131200_Content_37 = {
    Text = "Unter dem kaleidoskopischen Schein der Glasfenster treiben nur dimensionale Glut über das Blut und die abgetrennten Gliedmaßen."
  },
  AvgDialog_131200_Content_38 = {
    Text = "„Freude\"..."
  },
  AvgDialog_131200_Content_39 = {
    Text = "Du murmelst das unverständliche Wort und drehst dich um, um die Körperreste zu sehen, die „Erinnerungen\" genannt werden."
  },
  AvgDialog_131200_Content_4 = {
    Text = "Du hebst vorsichtig die Bruchstücke des Mädchens auf, die klebrige Flüssigkeit und das Blut von den Überresten haben deine Kleidung durchtränkt."
  },
  AvgDialog_131200_Content_40 = {
    Text = "Gebadet in trüber Flüssigkeit und heiligem Licht scheinen die Fragmente mit der heiligen Kathedrale selbst zu verschmelzen."
  },
  AvgDialog_131200_Content_41 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131200_Content_42 = {
    Text = "Der von Spinnweben durchzogene Weg zittert leicht, beleuchtet von schummrigem Licht auf der Bühne. In dem Moment, als du auf das Spinnennetz trittst, halten alle Puppen ihre Aufführung an."
  },
  AvgDialog_131200_Content_43 = {
    Text = "Alle Menschen in allen Dimensionen blicken auf dich. Sie sind neugierig, sie sind begeistert, sie sind voller Freude und Ehrfurcht."
  },
  AvgDialog_131200_Content_44 = {
    Text = "Dies ist eine großartige und stille Willkommenszeremonie. Unzählige Schauspieler werden zu Zuschauern, während der einzige Zuschauer zur Hauptfigur wird."
  },
  AvgDialog_131200_Content_45 = {
    Text = "Vielleicht ist es keine gute Idee, auf Arachne zu hören..."
  },
  AvgDialog_131200_Content_46 = {
    Text = "Du umklammerst den Silberschlüssel heimlich und gehst allein durch diese dichte, seltsame Stille."
  },
  AvgDialog_131200_Content_47 = {
    Text = "Der neue Herr des Theaters hat Euch bereits erwartet, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131200_Content_48 = {
    Text = "Die Schatten auf der Bühne oben versammeln sich. Fast instinktiv lehnst du dich schnell zurück und hältst den silbernen Schlüssel vor dich."
  },
  AvgDialog_131200_Content_49 = {
    Text = "Neuer Meister?"
  },
  AvgDialog_131200_Content_5 = {
    Text = "Vielleicht... vielleicht gibt es eine Möglichkeit, sie zu retten... die Kraft des Plasmids... die Korrektur des Schicksals..."
  },
  AvgDialog_131200_Content_50 = {
    Text = "Willkommen zurück im Theater, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131200_Content_51 = {
    Text = "Arachne, du......"
  },
  AvgDialog_131200_Content_52 = {
    Text = "Es tut mir leid, aber für unsere neue Geschichte benötigen wir deine Teilnahme."
  },
  AvgDialog_131200_Content_53 = {
    Text = "Das Spinnennetz zittert sanft. Die Besitzerin des Theaters, die langsam auf dich zukommt, hat eine Stimme, die immer noch warm wie die Dämmerung ist."
  },
  AvgDialog_131200_Content_54 = {
    Text = "Auf der Bühne um dich herum drehen sich die Puppen, die den kalten Spinnen-Zofen zum Verwechseln ähnlich sind, und springen gleichzeitig auf dich zu..."
  },
  AvgDialog_131200_Content_55 = {Text = "!!!"},
  AvgDialog_131200_Content_6 = {
    Text = "Nefraea hat ihre Fäden zerstört... ihr Schicksal ist bereits zu Ende, Schutzherr {Male=Herr, Female=Dame}."
  },
  AvgDialog_131200_Content_7 = {
    Text = "Das Geräusch des Spinnrades ist weiterhin ruhig und fern."
  },
  AvgDialog_131200_Content_8 = {
    Text = "„Die Erinnerung\" wurde ebenfalls von ihr getötet, bedeutet das, dass..."
  },
  AvgDialog_131200_Content_9 = {
    Text = "Nefraea hat bereits die Stärke, das Schicksal dieser Bühne zu verändern."
  },
  AvgDialog_131201_Content_1 = {
    Text = "Huh... Diese Diener von Nefraea sind wirklich hartnäckig..."
  },
  AvgDialog_131201_Content_10 = {
    Text = "Zwanzig Tage später wird er beginnen, ernsthaft das zu studieren, was in diesem Buch aufgezeichnet ist ... Ab diesem Moment wird diese Bühne, wie alle anderen Bühnen, unaufhaltsam das Schicksal der Zerstörung empfangen."
  },
  AvgDialog_131201_Content_100 = {
    Text = "Der Thronfolger und seine Frau sitzen auf der hinteren Bank des Cabrios und bewundern diese alte Stadt. Die Menschen rennen hinter dem Wagen her und eilen ihrem längst besiegelten Schicksal entgegen."
  },
  AvgDialog_131201_Content_11 = {
    Text = "Erinnerungen an diese Welt – zugleich neu und seltsam vertraut – durchfluten deinen Geist. Du hast noch nie einen Ort gesehen, der so lebendig und blühend war."
  },
  AvgDialog_131201_Content_12 = {
    Text = "Du hast zu viel erlebt, die Auflösung der öden Landschaft hat diese blühende Welt mühelos überdeckt und deine Vorstellung überflutet."
  },
  AvgDialog_131201_Content_13 = {
    Text = "Arachne streckte die Hand aus und streichelte sanft das Licht, das am Eingang der Gasse fiel. Sie trauerte um eine weitere Welt, die bald sterben würde."
  },
  AvgDialog_131201_Content_14 = {
    Text = "Eine Welt, die von den Göttern nicht beachtet wird... So eine Vorstellung hatte ich zuvor noch nie."
  },
  AvgDialog_131201_Content_15 = {
    Text = "Haben wir noch die Chance, das zu ändern?"
  },
  AvgDialog_131201_Content_16 = {
    Text = "Das ist genau der Grund, warum wir hierher gekommen sind."
  },
  AvgDialog_131201_Content_17 = {
    Text = "Sag mir, was ich tun soll?"
  },
  AvgDialog_131201_Content_18 = {Text = "Warte!..."},
  AvgDialog_131201_Content_19 = {
    Text = "Du hast sie bemerkt, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131201_Content_2 = {
    Text = "Du lehnst dich an die feuchte Wand einer abgelegenen Gasse und ringst nach Luft."
  },
  AvgDialog_131201_Content_20 = {
    Text = "Vor der Gasse nähert sich eine Gruppe von Menschen mit deutlich abweichenden mentalen Schwingungen in eure Richtung."
  },
  AvgDialog_131201_Content_21 = {
    Text = "Hinter dir, über dir, vor dir... immer mehr Feinde erscheinen in deinem Bewusstsein."
  },
  AvgDialog_131201_Content_22 = {
    Text = "Wir sind umzingelt!..."
  },
  AvgDialog_131201_Content_23 = {
    Text = "Seit ich die Bühne betreten habe, habe ich begonnen, das manipulierte Schicksal zu korrigieren. Doch das Schicksal so vieler Menschen zu korrigieren, ist keine leichte Aufgabe."
  },
  AvgDialog_131201_Content_24 = {
    Text = "Nefraea ließ diese Menschen zurück, um meine Reparatur des Schicksals zu behindern."
  },
  AvgDialog_131201_Content_25 = {
    Text = "Vielleicht haben wir noch einen anderen Weg..."
  },
  AvgDialog_131201_Content_26 = {
    Text = "Arachne, die Wiedervereinigungsgesellschaft plant heute hier einen Mord, ich bin einer der Vollstrecker."
  },
  AvgDialog_131201_Content_27 = {
    Text = "Diese Welt wird wegen dieser Person, dem Kronprinzen, der das Buch der Zauberei studiert, untergehen. Wenn ich erfolgreich bin, könnte ich vielleicht verhindern, dass dies geschieht"
  },
  AvgDialog_131201_Content_28 = {
    Text = "Das ist nicht das Richtigste..."
  },
  AvgDialog_131201_Content_29 = {
    Text = "Dort! Fangt sie"
  },
  AvgDialog_131201_Content_3 = {
    Text = "Du hast Arachne nicht rennend gesehen, sie steht ruhig neben dir, als wäre es ihr Schicksal, genau in diesem Moment in dieser Gasse zu stehen."
  },
  AvgDialog_131201_Content_30 = {
    Text = "Arachne zupfte an den Saiten und bereitete den mutierten Diener vor, der am Eingang der Gasse wie eine Statue erstarrt war."
  },
  AvgDialog_131201_Content_31 = {
    Text = "In der Ferne ertönte das Spiel von Trompete und Saxophon, begleitet vom Dröhnen der Autos, und kam langsam näher."
  },
  AvgDialog_131201_Content_32 = {
    Text = "Der Plan für das Attentat ist aufgeflogen, andere können dies nicht tun... Diese Person, der Kronprinz, ist bereits nah dran, wenn wir jetzt nichts tun, wird es zu spät sein"
  },
  AvgDialog_131201_Content_33 = {
    Text = "Arachne schaut in deine besorgten Augen und nickt nach einem kurzen Zögern sanft."
  },
  AvgDialog_131201_Content_34 = {
    Text = "Da das Schicksal so verläuft... vielleicht ist es deine Aufgabe, zu versuchen, eine Wahl für diese Welt zu treffen."
  },
  AvgDialog_131201_Content_35 = {
    Text = "Geh. Tu, was du tun musst, {Male=Mr.,Female=Miss} Schutzherr. Die Wahrheit des Schicksals wird sich dir hier offenbaren."
  },
  AvgDialog_131201_Content_36 = {
    Text = "Du hast keine Zeit, um über Arachnes Worte nachzudenken, nickst und stürmst mit Arachnes Hilfe aus der Gasse und mischst dich unter die tobende Menge."
  },
  AvgDialog_131201_Content_37 = {
    Text = "Das ist Erzherzog Flavian? Der Thronfolger des Reiches... Ich frage mich, wie viel so ein Wagen überhaupt kostet."
  },
  AvgDialog_131201_Content_38 = {
    Text = "Bah! Bastardssohn eines Diebes! Jeden Cent, den er ausgibt, hat er uns aus Blut und Schweiß herausgepresst!"
  },
  AvgDialog_131201_Content_39 = {
    Text = "Wenn ich nicht hinken würde, würde ich sicherlich auf dem Schlachtfeld sterben, während ich gegen diese Räuber anrenne"
  },
  AvgDialog_131201_Content_4 = {
    Text = "Nach so gründlichen Vorbereitungen... Was hat sie eigentlich vor?"
  },
  AvgDialog_131201_Content_40 = {
    Text = "Pssst! Hier sind überall die Wachen des Imperiums, willst du nicht mehr leben?"
  },
  AvgDialog_131201_Content_41 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131201_Content_42 = {
    Text = "Als du dich durch die Menschenmenge drängst und schließlich am Straßenrand ankommst, fährt das neueste Cabrio langsam vor dir vorbei."
  },
  AvgDialog_131201_Content_43 = {
    Text = "Der Kronprinz, ein Mann um die sechzig, sitzt mit seiner Frau im Fond. Sie winken der Menge huldvoll zu und deuten auf die historische Architektur von Hewatz."
  },
  AvgDialog_131201_Content_44 = {
    Text = "Selbst mit deinen verschwommenen Erinnerungen weißt du nur zu gut, welch tiefgreifendes Leid dieses Königshaus über das Land gebracht hat."
  },
  AvgDialog_131201_Content_45 = {
    Text = "Besorgt darüber, negative Auswirkungen auf diese Welt zu haben, hast du die Hand, die unwillkürlich nach dem Silberschlüssel greift, angehalten und die Pistole, die dort sein sollte, aus deinem Mantel gezogen, während du dich dem langsam fahrenden Fahrzeug näherst."
  },
  AvgDialog_131201_Content_46 = {
    Text = "Hey! Der Schüler! Du kannst nicht näher kommen..."
  },
  AvgDialog_131201_Content_47 = {
    Text = "Es tut mir leid, fürstlicher Herr, wenn ich einmal auf der Bühne stehe, muss ich die Dinge für diese Rolle zu Ende bringen"
  },
  AvgDialog_131201_Content_48 = {
    Text = "BANG! BANG BANG!"
  },
  AvgDialog_131201_Content_49 = {
    Text = "In dieser chaotischen Straße gibt es um den stolzen Erben des Imperiums nicht die strengen Sicherheitsmaßnahmen, die du dir vorgestellt hast. Dank des strengen Trainings kannst du dich leicht dem Fahrzeug nähern und drückst den Abzug."
  },
  AvgDialog_131201_Content_5 = {
    Text = "Nefraea hinterließ einen Hinweis. In diesem riesigen Schicksalsnetz dieser Welt verschmutzte sie einen der Fäden."
  },
  AvgDialog_131201_Content_50 = {
    Text = "Als drei Kugeln präzise durch die Brust des Fürsten drangen, hielt die gesamte Welt an."
  },
  AvgDialog_131201_Content_51 = {
    Text = "Der leidende Fürst, die erstaunte Prinzessin, die laufenden Wachen, alle hielten auf komische Weise inne, wie ein lebendiges Ölgemälde."
  },
  AvgDialog_131201_Content_52 = {
    Text = "!!!Das ist..."
  },
  AvgDialog_131201_Content_53 = {
    Text = "Nach einer kurzen Pause beginnen die Farben des Ölgemäldes zu fließen und sich zu verflechten, Raum-Zeit und Gravitation treten in dieses chaotische Fest ein, dein Körper wird zerrissen, unzählige Bilder ziehen vor deinen Augen vorbei."
  },
  AvgDialog_131201_Content_54 = {
    Text = "Ein prunkvolles Begräbnis. Der Zorn eines Königs. Krieg. Kanonen. Tod. Das Dröhnen der Kriegshörner und die Schreie der Zivilisten. Geier, die auf die blutroten Felder von Verdun herabstoßen, um sich an vierhunderttausend verstümmelten Überresten zu laben."
  },
  AvgDialog_131201_Content_55 = {
    Text = "Der Untergang des Imperiums, das zersplitterte Land, der verarmte König, das wiedergeöffnete Buch der Magie..."
  },
  AvgDialog_131201_Content_56 = {
    Text = "Schwarze, klebrige Flüssigkeit verschlang kurzzeitig dein Sichtfeld. Die Geschichte, die du kennst, spielt sich erneut ab, völlige Dunkelheit und Schmerz korrodieren jede deiner Zellen..."
  },
  AvgDialog_131201_Content_57 = {
    Text = "Keine Sorge, {Male=Mr.,Female=Miss} Schutzherr. Du bist jetzt in Sicherheit."
  },
  AvgDialog_131201_Content_58 = {
    Text = "Eine Hand ruht auf deiner Schulter. Die chaotischen, blutenden Farben und die grenzenlose Dunkelheit verschwinden."
  },
  AvgDialog_131201_Content_59 = {
    Text = "Deine Augen fliegen auf. Das Café ist so still wie eh und je; die Browning–Pistole ist aus deiner Hand verschwunden, und die frisch servierte Sachertorte steht vor dir und verströmt ein unwiderstehliches Aroma."
  },
  AvgDialog_131201_Content_6 = {
    Text = "In dieser korrumpierten Zeitlinie hat der Kronprinz des Fiorreichs vor zwei Monaten ein bestimmtes Buch entdeckt."
  },
  AvgDialog_131201_Content_60 = {
    Text = "Arachne... was... ist hier los?! Wir..."
  },
  AvgDialog_131201_Content_61 = {
    Text = "Bitte keine Panik, wir sind wieder an dem Punkt, an dem wir das Café betreten haben. Die gute Nachricht ist, dass wir eine Tasse kostenlosen Kaffee bekommen haben."
  },
  AvgDialog_131201_Content_62 = {
    Text = "Arachne hob die Kaffeetasse an und lächelte, während sie einen Schluck nahm. Auf der braunen Flüssigkeit spiegelte sich dein erstauntes Gesicht wider."
  },
  AvgDialog_131201_Content_63 = {
    Text = "Die Fäden des Schicksals sind nicht das, was du klar sehen kannst. Die Schauspieler von außerhalb der Bühne, die gewaltsam das Schicksal dieser Welt verändern, werden im Netz des Schicksals verloren."
  },
  AvgDialog_131201_Content_64 = {
    Text = "Vergangenheit und Zukunft, die zahllosen Schicksale dieser Bühne, die sich vor deinen Augen verweben... das ist das wahre Antlitz des Schicksalsnetzes."
  },
  AvgDialog_131201_Content_65 = {
    Text = "Die Zukunft des Schicksals... Meinst du, dass das, was gerade passiert ist, alles wahr ist? Diese Kriege, der Tod... sind alles von mir verursacht worden?"
  },
  AvgDialog_131201_Content_66 = {
    Text = "Das Schicksal hat dich Zeuge werden lassen. Nach der Ermordung des Erzherzogs war das tatsächlich der Weg, den die Welt einschlagen sollte. Aber sei unbesorgt, {Male=Mr.,Female=Miss} Schutzherr. Ich habe das Schicksal dieser Bühne bereits neu verwoben."
  },
  AvgDialog_131201_Content_67 = {
    Text = "Du hast aus dem Fenster geschaut. Es war immer noch die lebhafte Menge, aber die Bürger und Polizisten, die von Nefraea beeinflusst wurden, waren längst verschwunden."
  },
  AvgDialog_131201_Content_68 = {
    Text = "Wenn ich es so gemacht hätte wie gerade eben... wenn du das Schicksal nicht repariert hättest..."
  },
  AvgDialog_131201_Content_69 = {
    Text = "In einem Monat wird die Welt aufgrund des Todes dieses Thronfolgers in den größten Krieg der Geschichte ausbrechen. Acht Imperien werden darin verwickelt sein, und zwanzig Millionen Menschen werden in diesem Krieg ihr Leben verlieren."
  },
  AvgDialog_131201_Content_7 = {
    Text = "Ein Buch, das geheimnisvolle Zauberei dokumentiert und mit Göttern verbindet, die nicht zu dieser Dimension gehören."
  },
  AvgDialog_131201_Content_70 = {
    Text = "Der Boden unter unseren Füßen wird zu Asche, und die Menschen, die neben uns im Café sitzen, haben den Krieg nicht überlebt."
  },
  AvgDialog_131201_Content_71 = {
    Text = "Arachne schüttelte die Kaffeetasse und blickte aus dem Fenster auf das geschäftige Treiben der Straße. Sie erzählte ruhig, als ob sie ein ganz gewöhnliches Dessert vorstellte."
  },
  AvgDialog_131201_Content_72 = {
    Text = "Die lauten Stimmen auf der Straße bringen die Melodien von Frieden und Wohlstand in dein Ohr."
  },
  AvgDialog_131201_Content_73 = {
    Text = "Und die Erosion? Warum habe ich den Thronfolger bereits getötet und dennoch bringt es diese Welt zur Erosion..."
  },
  AvgDialog_131201_Content_74 = {
    Text = "In diesem großangelegten Krieg wurde dieses Imperium besiegt. Diese Person, der König, musste ursprünglich das grausame Urteil des Schicksals akzeptieren. Doch jetzt hat er eine neue Wahl."
  },
  AvgDialog_131201_Content_75 = {
    Text = "Magie, die nicht zu dieser Welt gehört, Götter, die alle Kräfte überschreiten. Was könnte für einen Vater, der sein Kind verloren hat, oder einen Monarchen, der sein Land verloren hat, attraktiver sein?"
  },
  AvgDialog_131201_Content_76 = {
    Text = "Die sanften Worte von Arachne lassen dich frösteln. Das Gewicht von zwei Milliarden Leben drückt wie eine Substanz auf dich."
  },
  AvgDialog_131201_Content_77 = {
    Text = "<Shake:Ich hätte nie gedacht, dass die Ermordung eines Prinzen so eskalieren würde... Ich dachte, ich würde helfen...>"
  },
  AvgDialog_131201_Content_78 = {
    Text = "Das Schicksal lässt dich diese Wahl treffen, um dir zu zeigen, wie es ist. Du kannst die Fäden nicht sehen, aber jetzt verstehst du, auf welche komplexe Weise sie verwoben sind."
  },
  AvgDialog_131201_Content_79 = {
    Text = "Die Fäden des Schicksals weben ein riesiges Netz, jede zarte Erschütterung eines Fadens könnte das Netz des Schicksals zum Wanken bringen."
  },
  AvgDialog_131201_Content_8 = {
    Text = "Arachne hob den Kopf und blickte auf die Fäden, die du nicht sehen kannst."
  },
  AvgDialog_131201_Content_80 = {
    Text = "Das ist das Schicksal—— so komplexes Schicksal."
  },
  AvgDialog_131201_Content_81 = {
    Text = "Du atmest einmal tief ein und beruhigst dein Herz, das vor Angst heftig schlägt."
  },
  AvgDialog_131201_Content_82 = {
    Text = "Zum Glück, zum Glück hast du diesen Krieg verhindert..."
  },
  AvgDialog_131201_Content_83 = {
    Text = "Ich habe den Krieg nicht aufgehalten, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131201_Content_84 = {
    Text = "Arachne schüttelte leicht den Kopf."
  },
  AvgDialog_131201_Content_85 = {
    Text = "In einem neuen Schicksal wird der König des Imperiums einen kleinen Teil der Wunder sehen, die im Buch der Magie dargestellt sind. Diese Stärke wird seine Stütze für den Krieg sein."
  },
  AvgDialog_131201_Content_86 = {
    Text = "Der König und seine Verbündeten führten einen großangelegten Krieg, in den auch die Imperien anderer Kontinente verwickelt wurden."
  },
  AvgDialog_131201_Content_87 = {
    Text = "In diesem Krieg sterben die Menschen in vierfacher Zahl."
  },
  AvgDialog_131201_Content_88 = {
    Text = "Sie fährt mit ihrer ruhigen Erzählung fort und klingt dabei wie eine Mutter, die einem Kind, das nicht einschlafen kann, eine Gutenachtgeschichte erzählt."
  },
  AvgDialog_131201_Content_89 = {
    Text = "<Shake:Das ... warum ist das so?>"
  },
  AvgDialog_131201_Content_9 = {
    Text = "Diese Bühne hatte nie eine Verbindung zu den Göttern, und lange Zeit hätte sie sich dem Sturz in das Schicksal der Auflösung entziehen können."
  },
  AvgDialog_131201_Content_90 = {
    Text = "Du hast die Komplexität des Schicksalsnetzes gesehen. Wenn du versuchst, einige vorbestimmte Ereignisse gewaltsam zu vermeiden, wird das zu ernsthafteren Katastrophen führen."
  },
  AvgDialog_131201_Content_91 = {
    Text = "Der König wird dennoch besiegt; das begrenzte Wissen in jenem Buch bietet dem Reich keine dauerhafte Rettung."
  },
  AvgDialog_131201_Content_92 = {
    Text = "Nach diesem zweiten Scheitern wird Zauberei als Farce abgetan werden. Kein Herrscher auf dieser Bühne wird jemals wieder darauf zurückgreifen."
  },
  AvgDialog_131201_Content_93 = {
    Text = "Ihr Blick fiel auf andere Dinge. Sie verehrten die Wissenschaft, erforschten Waffen, die Planeten verschlingen konnten, genossen in der Abschreckung dieser Waffen einen kurzen Frieden und wurden dann von den Waffen, die sie selbst geschaffen hatten, zerstört."
  },
  AvgDialog_131201_Content_94 = {
    Text = "Diese Bühne ist weiterhin dazu bestimmt, in irgendeiner zukünftigen Apokalypse zu vergehen – das ist ihr unausweichliches Schicksal. Aber für eine Weile werden sie eine Zeit des Wohlstands genießen, so schön wie ein Kunstwerk."
  },
  AvgDialog_131201_Content_95 = {
    Text = "Der Blick des Toguwaibo wird in Schach gehalten werden, zumindest für eine Weile."
  },
  AvgDialog_131201_Content_96 = {
    Text = "Arachnes Löffel dreht sich langsam in der Tasse, der tiefbraune Wirbel gleicht genau dem, was du im Schicksalsnetz gesehen hast."
  },
  AvgDialog_131201_Content_97 = {
    Text = "Sie senkte den Kopf. Das Sonnenlicht fiel von draußen auf sie, wie ein Trauerschleier."
  },
  AvgDialog_131201_Content_98 = {
    Text = "Ringen, weben, flicken... und doch ändert sich nichts wirklich. Das ist das Schicksal, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131201_Content_99 = {
    Text = "Die Musik von Trompete und Saxophon kam zum Fenster, begleitet von den Jubelrufen und dem Schimpfen der Menge, und entfernte sich allmählich."
  },
  AvgDialog_131202_Content_1 = {Text = "Knack—"},
  AvgDialog_131202_Content_10 = {
    Text = "Gläubiger?..."
  },
  AvgDialog_131202_Content_11 = {
    Text = "Der violette Umhang... ich habe nie... nie gesehen..."
  },
  AvgDialog_131202_Content_12 = {
    Text = "Sie... haben „Erinnern \" zum Altar gebracht... <Shake:Hust, hust...>"
  },
  AvgDialog_131202_Content_13 = {
    Text = "Die Straße St. Basilius... gehört einer ihrer Kirchen..."
  },
  AvgDialog_131202_Content_14 = {
    Text = "Die Knochen und das Fleisch zittern, kämpfen und drücken die letzte Lebensenergie dieses zerfallenen Körpers heraus."
  },
  AvgDialog_131202_Content_15 = {
    Text = "Er wusste, dass Miss Arachne die Fäden dieser Leute nicht sehen konnte. Er wusste, dass dies etwas war, das er erledigen musste."
  },
  AvgDialog_131202_Content_16 = {
    Text = "Fräulein... die Bösewichte im Schatten... jagen uns... sie hat unser Schicksal verfälscht..."
  },
  AvgDialog_131202_Content_17 = {
    Text = "Sie haben mein Blut mitgenommen... In dieser Kirche wird sie das schreckliche Ritual durchführen..."
  },
  AvgDialog_131202_Content_18 = {
    Text = "Rächer des Schicksals, bade in unserem Blut ... Der böse Gott aus den Schatten wird erscheinen, und alles Schicksal wird in ... völliges ... <Shake:Hust, hust, hust ...><Big:völliges Chaos ... !>"
  },
  AvgDialog_131202_Content_19 = {
    Text = "Die Pupillen des alten Mannes weiteten sich plötzlich, und sein Körper zitterte vor Kälte und Angst, als ob er etwas noch Schrecklicheres als seinen tiefsten Alptraum, die Hölle, sah."
  },
  AvgDialog_131202_Content_2 = {
    Text = "Die Spinnen verstreuen sich, die letzte Gestalt fällt im silbernen Licht, der Herr des Regens ist längst verschwunden. Du und Arachne stehen vor der gefallenen Gestalt in der Mitte des Raumes."
  },
  AvgDialog_131202_Content_20 = {
    Text = "Er hielt fest an Arachne's Ärmel und blickte sie mit fast flehenden Augen an."
  },
  AvgDialog_131202_Content_21 = {
    Text = "Fräulein... ich gewöhne mich immer noch daran, Sie Fräulein zu nennen... Sie haben lange gebraucht, um sprechen zu lernen, und haben den Herren und die Dame sehr besorgt gemacht..."
  },
  AvgDialog_131202_Content_22 = {
    Text = "Du verabschiedest dich von mir, alle freuen sich, dass du endlich sprechen kannst, aber ich weiß, nur ich weiß... dieses Wort ist das unwiderrufliche Urteil des Schicksals..."
  },
  AvgDialog_131202_Content_23 = {
    Text = "Ich bin nach Hause zurückgekehrt und warte auf das Erscheinen des Todes. Ich kann nicht aufhören zu weinen, nicht für mich selbst, sondern für Sie, Frau Arachne..."
  },
  AvgDialog_131202_Content_24 = {
    Text = "Ich weiß, welche schwere Fluch Sie tragen werden..."
  },
  AvgDialog_131202_Content_25 = {
    Text = "Tränen liefen über das von Falten durchzogene Gesicht des alten Mannes. Er hielt zitternd die Hand von Arachne. Durch den verschwommenen Schleier der Tränen sah er die junge Arachne vor sich stehen."
  },
  AvgDialog_131202_Content_26 = {
    Text = "Das junge Gesicht hat nie laut geweint, es schaut immer neugierig in den leeren Himmel und lächelt dem Schicksal zu, das sie nicht sehen können."
  },
  AvgDialog_131202_Content_27 = {
    Text = "Fräulein Arachne, bitte schützen Sie sie gut, schützen Sie „Erinnern\" ... Bitte kümmern Sie sich gut um sich selbst ..."
  },
  AvgDialog_131202_Content_28 = {
    Text = "Bitte nicht... verloren gehen im... Netz..."
  },
  AvgDialog_131202_Content_29 = {
    Text = "„Güte\" Stimme war am Ende fast nicht mehr hörbar. Als sein Atem verstummte, schloss Arachne sanft seine Augen."
  },
  AvgDialog_131202_Content_3 = {
    Text = "Es bist du..."
  },
  AvgDialog_131202_Content_30 = {
    Text = "„Ruhe nun, Herr Lawrence...\""
  },
  AvgDialog_131202_Content_31 = {
    Text = "Edgar's Mundwinkel hob sich sanft. In den letzten Momenten seines Lebens hörte er erneut die ersten Worte, die Arachne in ihrem Leben gesagt hatte."
  },
  AvgDialog_131202_Content_32 = {
    Text = "Er hat nichts weiter zu verlangen."
  },
  AvgDialog_131202_Content_33 = {
    Text = "Du hast die Erinnerungen deines eigenen Butlers benutzt, um diese Geheimeinheit zu erschaffen... er ist ganz anders als die anderen Puppen, die du gemacht hast. Warum?"
  },
  AvgDialog_131202_Content_34 = {
    Text = "Vielleicht ist es zur Erinnerung, vielleicht... um mich selbst zu beruhigen."
  },
  AvgDialog_131202_Content_35 = {Text = "Trost?"},
  AvgDialog_131202_Content_36 = {
    Text = "Mich selbst zu trösten, sie waren immer an meiner Seite, niemals weit weg..."
  },
  AvgDialog_131202_Content_37 = {
    Text = "Arachne legte den zerbrochenen Körper des alten Mannes ruhig ab, ohne weitere Erklärungen zu geben, und du hast nicht weiter nachgefragt. Du wusstest, die Antwort wartete nicht weit entfernt auf dich."
  },
  AvgDialog_131202_Content_38 = {
    Text = "In diesem Schicksalsnetz sind Nefraea's Stärke und sie miteinander verbunden. Ihr Tod wird Nefraea's Verbindung zum Netz enger machen."
  },
  AvgDialog_131202_Content_39 = {
    Text = "Wir müssen sie aufhalten, bevor sie die Macht erlangt, das Netz zu zerreißen. Das ist alles, was jetzt zählt, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131202_Content_4 = {
    Text = "<Shake:Fräulein Arachne......Fremder......hust hust......>"
  },
  AvgDialog_131202_Content_40 = {
    Text = "Arachne's Hände streicheln den Kopf des alten Mannes und berühren den Faden, der fast unsichtbar geworden ist. Am anderen Ende dieser Stadt kommt ein schwaches Echo des Schicksalsfadens."
  },
  AvgDialog_131202_Content_41 = {
    Text = "Hat das Schicksal auf dich reagiert?"
  },
  AvgDialog_131202_Content_42 = {
    Text = "Arachne nickte. Bevor sie aufstand, warf sie einen letzten Blick auf das lächelnde Gesicht des alten Mannes."
  },
  AvgDialog_131202_Content_43 = {
    Text = "„Erinnerungen\" leben noch. Die Gäste aus dem Abgrund warten auf unser Kommen."
  },
  AvgDialog_131202_Content_5 = {
    Text = "Der Körper vor dir ist zur Hälfte von zerfressenen, fauligen Fleisch und zur anderen Hälfte von blutigen, weißen Knochen."
  },
  AvgDialog_131202_Content_6 = {
    Text = "Der alte Mann hustete heftig und presste ein paar Tropfen frisches Blut heraus, das noch nicht getrocknet war. Ein unsichtbarer Faden lag in den Händen von Arachne, wie eine Kerze im Sturm, wacklig."
  },
  AvgDialog_131202_Content_7 = {
    Text = "Blutstillung... Wir brauchen etwas zur Blutstillung..."
  },
  AvgDialog_131202_Content_8 = {
    Text = "Es ist zu spät... Fräulein Arachne... Rettet sie... Rettet „Erinnern\"..."
  },
  AvgDialog_131202_Content_9 = {
    Text = "Die Gläubigen... haben sie weggebracht..."
  },
  AvgDialog_131203_Content_1 = {
    Text = "Arachne! Was machst du da?! Ist das dein... Vertrauen?"
  },
  AvgDialog_131203_Content_10 = {
    Text = "Darstellung. Täuschung. Veralberung."
  },
  AvgDialog_131203_Content_11 = {
    Text = "„Verzückung \" – dies ist Euer Schicksal. Betretet die Bühne, {Male=Mr., Female=Miss} Schutzherr. \nAuf dieser Bühne werdet Ihr Eure eigene Geschichte vollenden."
  },
  AvgDialog_131203_Content_12 = {
    Text = "Auf dieser Bühne wirst du deinen Wunsch erfüllt bekommen."
  },
  AvgDialog_131203_Content_2 = {
    Text = "Wilhelm, der Seniorstudent... E-Er erholt sich noch von seinen Wunden!..."
  },
  AvgDialog_131203_Content_3 = {
    Text = "Sorgt Euch nicht, {Male=Mr.,Female=Miss} Schutzherr. Er hat nichts mit diesem Faden des Schicksals zu tun. Ich habe ihn an einen sicheren Ort teleportiert."
  },
  AvgDialog_131203_Content_4 = {
    Text = "Dies ist ein Schicksal, dem keiner von uns entkommen kann, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131203_Content_5 = {
    Text = "Ich habe dir nie Lügen erzählt. Ich werde dich zu deiner Bühne bringen, auf der du deine großartige Aufführung vollenden wirst."
  },
  AvgDialog_131203_Content_6 = {
    Text = "Arachne kommt langsam auf dich zu. Du blickst in ihre nebligen Augen und möchtest die Informationen, die sie dir nicht direkt übermitteln kann, darin lesen."
  },
  AvgDialog_131203_Content_7 = {
    Text = "(Von mir...Aufführung...)"
  },
  AvgDialog_131203_Content_8 = {
    Text = "Ein Lichtstrahl zieht durch dein Bewusstsein, wie ein flüchtiger Meteor, der in den verworrenen Fragmenten des Geistes verschwindet."
  },
  AvgDialog_131203_Content_9 = {
    Text = "Die kalten Spinnenzofen verstreuten sich um die Umgebung und traten nicht näher. Arachne hob sanft die Hand und zupfte an den leeren Saiten der Laute."
  },
  AvgDialog_131204_Content_1 = {
    Text = "Silberlicht schnitt durch die Spinnweben wie eine Klinge, und in diesem Moment hast du schnell die Verteidigung der Zofen durchbrochen und bist vor Arachne angekommen."
  },
  AvgDialog_131204_Content_10 = {
    Text = "Sie drehte sich um. Die Fäden drehten sich sanft, und ein plötzlicher Impuls entbrannte in deinem Inneren und trieb dich dazu, aufzustehen."
  },
  AvgDialog_131204_Content_11 = {
    Text = "Bist du dir sicher, dass du vollkommen selbstbestimmt bist, dass du der perfekte Vertreter des freien Willens bist? Du folgst ganz aus eigenem Willen dem Pfad von Arachne, mit genau dem gleichen Schritt und Rhythmus, gehst du dem Ende des Spinnenweges entgegen."
  },
  AvgDialog_131204_Content_12 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131204_Content_13 = {
    Text = "Oh, willkommen! {Male=Mr.,Female=Miss} %player%, mein geschätzter Gast! Eure Schritte haben sich noch nie so melodisch angehört."
  },
  AvgDialog_131204_Content_14 = {
    Text = "Der neue Besitzer des Theaters betritt die Bühne, und auf der dunklen Bühne ertönt Nefraea mit übertriebenem Tonfall."
  },
  AvgDialog_131204_Content_15 = {
    Text = "Es ist nicht angenehm, nicht wahr? Wenn mit dem eigenen Schicksal gespielt wird? Macht nichts, {Male=Mr.,Female=Miss} Schutzherr. Diese Geschichte ist bald vorüber."
  },
  AvgDialog_131204_Content_16 = {
    Text = "Nefraea, was willst du eigentlich tun?..."
  },
  AvgDialog_131204_Content_17 = {
    Text = "Suspense, genau, das ist der Grund, warum die Zuschauer in dieses Theater kommen! Aber keine Eile, mein Lieber."
  },
  AvgDialog_131204_Content_18 = {
    Text = "Meine Damen und Herren! Bereiten Sie Ihr Jubeln vor... Huch, wo ist meine Puppe... Oh, ich habe sie gefunden"
  },
  AvgDialog_131204_Content_19 = {
    Text = "Die großartigen Rächer des Schicksals, die die drei geheimen Idole erlegt haben, was für eine fantasievolle Darbietung wollen sie diesem Bühnenbild bieten?"
  },
  AvgDialog_131204_Content_2 = {
    Text = "Hab's bekommen!"
  },
  AvgDialog_131204_Content_20 = {
    Text = "Nun, seid Zeugen des <Big:<Red:Höhepunkts des Zweiten Akts!>>"
  },
  AvgDialog_131204_Content_21 = {
    Text = "Ich nenne es „Neugeboren\" —"
  },
  AvgDialog_131204_Content_22 = {Text = "Knack—"},
  AvgDialog_131204_Content_23 = {
    Text = "Ein heller Lichtstrahl versammelt sich auf der Bühne und durchbricht die kurze Stille und Dunkelheit des Theaters. Eine Puppe mit einem Spinnrad betritt die Bühne."
  },
  AvgDialog_131204_Content_24 = {
    Text = "Nefraea, die Totengöttin des Abgrunds, die Rächerin des Schicksals...<Shake:Ich habe mich Ihrer großen Stärke ergeben!>"
  },
  AvgDialog_131204_Content_25 = {
    Text = "Das ist Romantik, sie macht die Menschen dumm. Das ist Güte, sie macht die Menschen zerbrechlich. Das ist Erinnerung... Unter all den schönen Eigenschaften ist die Erinnerung die Quelle allen Leidens."
  },
  AvgDialog_131204_Content_26 = {
    Text = "Ich kann sie nicht ertragen... Ich widme sie Ihnen, der großen Nefraea."
  },
  AvgDialog_131204_Content_27 = {
    Text = "Echt, Schwester? Meine gute Schwester..."
  },
  AvgDialog_131204_Content_28 = {
    Text = "Kein Problem, in dieser Welt bin ich derjenige, der dich am besten versteht. Du musst nicht länger leiden, überlass all diesen Schmerz mir."
  },
  AvgDialog_131204_Content_29 = {
    Text = "Sieh mal, die Laterne aus dem Abgrund ist bereits entzündet, ihr Licht wird uns den Weg nach Hause weisen——"
  },
  AvgDialog_131204_Content_3 = {Text = "Ding—"},
  AvgDialog_131204_Content_30 = {
    Text = "Wie warm das Licht ist... Aber wo genau ist der Weg nach Hause?"
  },
  AvgDialog_131204_Content_31 = {
    Text = "Verstehen Sie immer noch nicht? Meine liebe Schwester."
  },
  AvgDialog_131204_Content_32 = {
    Text = "Dieses Spinnrad ist der Leib des Apostels. Diese Lichter sind der Blick des Apostels — Er schaut uns an"
  },
  AvgDialog_131204_Content_33 = {
    Text = "„Nefraea\" stand begeistert auf und breitete die Arme aus."
  },
  AvgDialog_131204_Content_34 = {
    Text = "Du musst nur die Macht der drei Plasmide versammeln, dann wird der namenlose Apostel hier erwachen"
  },
  AvgDialog_131204_Content_35 = {
    Text = "Er wird uns den Weg zur höchsten Gottheit öffnen ... Dann wird <Big:alles Leid vergehen und alles Vergebliche ein Ende finden!>"
  },
  AvgDialog_131204_Content_36 = {
    Text = "„Nefraea\" riss plötzlich die hölzerne Maske ab und offenbarte Nefraea ihr lebendiges Gesicht."
  },
  AvgDialog_131204_Content_37 = {
    Text = "Die hölzerne Bühne, die hölzerne Puppe, der einzige lebendige Körper steht in der Mitte der Bühne, breitet die Arme aus und genießt den Blick des einzigen Publikums."
  },
  AvgDialog_131204_Content_38 = {
    Text = "Der Durchgang der Götter wird sich bald öffnen, deine Mission wird bald erfüllt sein, verstehst du, Schwester?"
  },
  AvgDialog_131204_Content_39 = {
    Text = "Du musst dein endloses Netz nicht mehr weben, du musst dich nicht mehr aufgeben"
  },
  AvgDialog_131204_Content_4 = {
    Text = "Zarte Hände strecken sich in die Luft und bewegen sich sanft. Die Saiten vibrieren leicht, und in der Luft breitet sich eine elegante Welle aus."
  },
  AvgDialog_131204_Content_40 = {
    Text = "Nimm mich wieder auf, okay, Arachne? ... Lass mich wieder ein Teil von dir werden ..."
  },
  AvgDialog_131204_Content_41 = {
    Text = "Tränen wischten das Make-up weg und hinterließen schwarze Spuren wie bei einer Auflösung auf ihrem Gesicht. Wahnsinniges Lachen und Weinen waren wie ein riesiges Netz, das diesen einzigen lebendigen Individuum auf der Bühne umschlang.."
  },
  AvgDialog_131204_Content_42 = {
    Text = "Nefraea hockte sich nieder und hob das glatte, gesichtslosen Wangen von „Arachne\" hoch. Tränen liefen über das weinende Gesicht und tropften auf die lächelnde Maske der Puppe."
  },
  AvgDialog_131204_Content_43 = {
    Text = "Sie starrte fest auf die Arachne unten auf der Bühne, ihre zitternden Lippen lagen sanft an dem Ohr der Puppe. Ihre Stimme war so leise, als würde sie nur sich selbst etwas erzählen."
  },
  AvgDialog_131204_Content_44 = {
    Text = "Lass mich nicht mehr allein... bitte?"
  },
  AvgDialog_131204_Content_5 = {
    Text = "Wellen streichen über das silberne Licht, das silberne Licht verschwindet, und der Silberschlüssel, der eine mächtige geistige Kraft trägt, ist verschwunden. Wellen streichen über deinen Körper, dein Leib verwandelt sich in vertrocknete Knochen, das Blut wird zu Schlamm. Du zerfällst und kehrst dann wieder zu dir zurück."
  },
  AvgDialog_131204_Content_6 = {
    Text = "Alle Kräfte verschwinden in der Unform, alle Gedanken zerfallen zu Staub. Wo die Wellen hinreichen, verwandeln sich tausend Welten in die Fäden in ihrer Hand. Einschließlich dir, dir selbst."
  },
  AvgDialog_131204_Content_7 = {
    Text = [[
Sie ist die Herrin des Theaters.
Sie ist das Schicksal selbst.]]
  },
  AvgDialog_131204_Content_8 = {
    Text = "Arachne, du... du kannst mein Schicksal kontrollieren?!..."
  },
  AvgDialog_131204_Content_9 = {
    Text = "Arachnes Lächeln ist wie ein ruhiger See, in dem du das Aussehen des Sees nicht erkennen kannst; auf dieser Wasseroberfläche siehst du nur dein eigenes Spiegelbild."
  },
  AvgDialog_131205_Content_1 = {
    Text = "Schussfeuer"
  },
  AvgDialog_131205_Content_10 = {
    Text = "Du musst keine Hausaufgaben abgeben."
  },
  AvgDialog_131205_Content_11 = {
    Text = "Lehrerin Arachne, was meinen Sie...?"
  },
  AvgDialog_131205_Content_12 = {
    Text = "Weißt du noch, wer du bist und woher du kommst?"
  },
  AvgDialog_131205_Content_13 = {
    Text = "Ich? Ich bin natürlich..."
  },
  AvgDialog_131205_Content_14 = {
    Text = "%player%. Durch und durch ein Hewatz–Kind. Erstsemester an der Akademie für Dramatische Künste. Deine Eltern sind gewöhnliche Regierungsbeamte, die dich vergöttern. Du hattest zwei anständige Romanzen. Leidenschaftlich, wenn auch nicht außergewöhnlich talentiert, mit einer Schwäche für Sachertorte und gegrillte Fleisch–Wraps."
  },
  AvgDialog_131205_Content_15 = {
    Text = "Ursprünglich klare Erinnerungen werden plötzlich verschwommen, eine andere Erinnerung springt abrupt aus deinem Kopf heraus. Misaq, Erwecker, Auflösung, Toguwaibo..."
  },
  AvgDialog_131205_Content_16 = {
    Text = "Du schlägst plötzlich die Augen auf und schaust die Frau gegenüber an, die gerade Kaffee genießt."
  },
  AvgDialog_131205_Content_17 = {
    Text = "Nein... das stimmt nicht... ich bin der Schutzherr von Misaq... was ist hier los?"
  },
  AvgDialog_131205_Content_18 = {
    Text = "Ich erinnere mich... Wir sind in deinem Theater auf eine Bühne gegangen, und dann... und dann..."
  },
  AvgDialog_131205_Content_19 = {
    Text = "Dann hast du dem Kellner Nachmittagstee bestellt. Als Einheimischer hast du einen ziemlich guten Geschmack."
  },
  AvgDialog_131205_Content_2 = {
    Text = "Ding Ding——"
  },
  AvgDialog_131205_Content_20 = {
    Text = "Arachne nahm einen Schluck aus der Tasse mit der braunen Flüssigkeit und nickte anerkennend."
  },
  AvgDialog_131205_Content_21 = {
    Text = "Ihr beiden, eure Sachen sind bereit."
  },
  AvgDialog_131205_Content_22 = {
    Text = "Der Teller in der Hand des Kellners verströmt einen betörenden Duft, während er sich über dich beugt, kommt sein Kopf leise an dein Ohr."
  },
  AvgDialog_131205_Content_23 = {
    Text = "Das Attentatsvorhaben ist durchgesickert. Der Erzherzog wird wahrscheinlich seine Route ändern. Der Führungsoffizier wird dich benachrichtigen, sobald es Neuigkeiten gibt. Mach dich bereit, %player%."
  },
  AvgDialog_131205_Content_24 = {
    Text = "Eine brandneue Browning-Pistole wird dir heimlich in die Hand gelegt. Als du wieder aufblickst, hat der Kellner sein freundliches Lächeln zurückgewonnen, verbeugt sich vor euch und trägt das Tablett zurück in die Küche."
  },
  AvgDialog_131205_Content_25 = {
    Text = "Übermäßige Erinnerungen häufen sich in deinem Kopf, und du reibst dir schmerzhaft die geschwollene Stirn."
  },
  AvgDialog_131205_Content_26 = {
    Text = "Zwei verschiedene Erinnerungen existieren in einem Gehirn, und für jemanden, der es zum ersten Mal erlebt, ist dieses Gefühl tatsächlich nicht sehr angenehm."
  },
  AvgDialog_131205_Content_27 = {
    Text = "Zum Glück, im Vergleich zu Toguwaibo ist dieser Grad an Kopfschmerzen wie eine Massage."
  },
  AvgDialog_131205_Content_28 = {
    Text = "Meiner Erinnerung nach befolge ich die Befehle der Eisernen Hand. In zwei Stunden soll ich mit dieser Waffe den zu Besuch weilenden Thronfolger des Fiorreichs ermorden..."
  },
  AvgDialog_131205_Content_29 = {
    Text = "Du streichelst die Oberfläche der Pistole und ordnest in deinem Kopf die Erinnerungen an, die zu dieser Welt gehören."
  },
  AvgDialog_131205_Content_3 = {
    Text = "Die Räder rollen über den unebenen Kopfsteinpflaster, wütende Glocken läuten und schreien in Richtung des riesigen Umzugs, während eine Wolke aus Staub und Flüchen aufsteigt."
  },
  AvgDialog_131205_Content_30 = {
    Text = "Bevor du weitersprechen kannst, strahlt ein grelles Licht ins Café. Militärstiefel treffen klar auf den Zementboden und kommen vor der Bar zum Stehen."
  },
  AvgDialog_131205_Content_31 = {
    Text = "Hallo, meine Herren Polizisten, darf ich fragen..."
  },
  AvgDialog_131205_Content_32 = {
    Text = "Bevor er seinen Satz beenden konnte, trat ein Polizist schnell vor, drehte ihm die Hände auf den Rücken und drückte seinen Kopf auf die Theke."
  },
  AvgDialog_131205_Content_33 = {
    Text = "In seinem ängstlichen Blick drückte eine Waffe auf seine Stirn."
  },
  AvgDialog_131205_Content_34 = {
    Text = "Mitglied des Wiedervereinigungskomitees, Bosant. Du hast zehn Sekunden, um mir zu sagen, wo sich dein Komplize befindet."
  },
  AvgDialog_131205_Content_35 = {
    Text = "Der Kellner schnappt nach Luft und zittert. In seinem verzweifelten Kampf huschen seine Augen zur Ecke des Raumes."
  },
  AvgDialog_131205_Content_36 = {
    Text = "Doch der Tisch, an dem du eben noch gesessen hast, ist leer. Nur eine halb volle Tasse Kaffee ist geblieben, ihr Dampf steigt träge in die Luft."
  },
  AvgDialog_131205_Content_37 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131205_Content_38 = {
    Text = "Hier sollte es vorerst sicher sein."
  },
  AvgDialog_131205_Content_39 = {
    Text = "Ihr verlasst das Café durch die Hintertür, wie zwei unauffällige Wassertropfen, die in die laute Menge zusammenfließen."
  },
  AvgDialog_131205_Content_4 = {
    Text = "Du winkst und vertreibst den Staub, der durch die Vorhänge des Cafés dringt."
  },
  AvgDialog_131205_Content_40 = {
    Text = "Was ist mit dieser Situation jetzt... Was ist mit diesen unterschiedlichen Erinnerungen los?"
  },
  AvgDialog_131205_Content_41 = {
    Text = "Betritt die Bühne des Schicksalstheaters, wirst du zu einer Figur auf der Bühne. Jede Figur hat ihr eigenes Leben."
  },
  AvgDialog_131205_Content_42 = {
    Text = "Diese Welt befindet sich in einer fernen Dimension, von der du noch nie gehört und die du nie betreten hast. Aber als Charakter, der in dieser Welt gewachsen ist, kennst du sie in- und auswendig."
  },
  AvgDialog_131205_Content_43 = {
    Text = "Willkommen auf einer meiner Bühnen, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131205_Content_44 = {
    Text = "Du meinst also... du kannst andere Welten durch die Bühne verbinden?"
  },
  AvgDialog_131205_Content_45 = {
    Text = "Arachne verstand die Bedeutung deines glühenden Blicks. Sie hob die Tasse Kaffee, die sie aus dem Laden mitgenommen hatte, und schnüffelte ernsthaft daran, während sie sanft den Kopf schüttelte."
  },
  AvgDialog_131205_Content_46 = {
    Text = "Mit Kaffee und Kuchen auf der Flucht, hat diese seltsame Sache keinerlei Aufmerksamkeit auf sich gezogen. Sie geschieht so harmonisch bei Arachne, als wäre sie ganz natürlich Teil ihres Schicksals."
  },
  AvgDialog_131205_Content_47 = {
    Text = "Lady Daffodil hat dir die Prinzipien des Dimensionsreisens erklärt. Die Barrieren zwischen den Welten sind unglaublich massiv. Jede Überquerung fordert einen schrecklichen Preis; so etwas tut man nicht leichtfertig."
  },
  AvgDialog_131205_Content_48 = {
    Text = "Aber sind wir jetzt nicht schon hier...?"
  },
  AvgDialog_131205_Content_49 = {
    Text = "Das Theater des Schicksals kann die Schicksale verschiedener Welten kurzzeitig miteinander verbinden."
  },
  AvgDialog_131205_Content_5 = {
    Text = "Eine Person einen Schawarma–Wrap, eine Sachertorte und zwei Tassen Hewatz–Kaffee. Danke."
  },
  AvgDialog_131205_Content_50 = {
    Text = "Derzeit sind wir nur zwei Figuren, verloren in einem Meer von Menschen – flüchtige Projektionen, die im Handumdrehen verschwinden werden."
  },
  AvgDialog_131205_Content_51 = {
    Text = "Hologramm... selbst ein Hologramm wäre in Ordnung, kannst du mir auf diese Weise zurückhelfen..."
  },
  AvgDialog_131205_Content_52 = {
    Text = "Es tut mir wirklich leid, %player%. Das Tor, das du geschlossen hast, hat den Blick des Toguwaibo blockiert, aber es hat auch die Schicksalsleine durchtrennt."
  },
  AvgDialog_131205_Content_53 = {
    Text = "Wenn wir versuchen, dort Einfluss zu nehmen, werden wir mit einer Katastrophe konfrontiert, die wir nicht ertragen können."
  },
  AvgDialog_131205_Content_54 = {
    Text = "Sie sah deinen enttäuschten Ausdruck und lächelte, während sie dir den Kuchen auf dem Teller reichte."
  },
  AvgDialog_131205_Content_55 = {
    Text = "Sei unbesorgt, %player%. Sobald wir uns um meine Schwester gekümmert haben, wird sich der Durchgang zurück nach Kardas wieder öffnen."
  },
  AvgDialog_131205_Content_56 = {
    Text = "Das Schicksal wird jede Wartezeit nicht enttäuschen, und wir dürfen auch kein Geschenk des Schicksals enttäuschen. Probier mal."
  },
  AvgDialog_131205_Content_57 = {
    Text = "Du atmest tief ein, nimmst den Kuchen und beißt vorsichtig hinein. Der süße Geschmack lässt dich fast das Unbehagen vergessen, das durch das Aufeinandertreffen zweier unterschiedlicher Erinnerungen verursacht wurde."
  },
  AvgDialog_131205_Content_58 = {
    Text = "Hmm... Man sagt, Erzherzog Flavian lässt sich nie die Gelegenheit entgehen, die lokale Spezialitätentorte zu probieren, wann immer er zu Besuch kommt. Für einen Kronprinzen hat er wahrlich einen feinen Geschmack."
  },
  AvgDialog_131205_Content_59 = {
    Text = "Was hat Nefraea also mit dieser Welt beeinflusst? Wie sollten wir es korrigieren..."
  },
  AvgDialog_131205_Content_6 = {
    Text = "Du reichst dem Kellner die aus Pergament gefertigte Speisekarte und blickst frustriert auf die vertraute Straße draußen."
  },
  AvgDialog_131205_Content_60 = {
    Text = "Während du sprichst, scheint Arachne von etwas angezogen zu werden und schaut nach oben auf die Fäden, die du nicht klar sehen kannst."
  },
  AvgDialog_131205_Content_61 = {
    Text = "Sie lächelte, trank den letzten Schluck Kaffee aus der Tasse und reichte ein paar Münzen zusammen mit den verbleibenden Tassen einem zufällig vorbeikommenden Kellner, der zurück zum Café musste, und bedankte sich leise bei ihm."
  },
  AvgDialog_131205_Content_62 = {
    Text = "Sie hat uns gefunden. Perfektes Timing. Sei vorsichtig, %player%."
  },
  AvgDialog_131205_Content_63 = {Text = "Bang—"},
  AvgDialog_131205_Content_64 = {
    Text = "Du beugst dich instinktiv nach vorne, eine Kugel fliegt kaum an deinem Kopf vorbei."
  },
  AvgDialog_131205_Content_65 = {Text = "Genau dort"},
  AvgDialog_131205_Content_66 = {
    Text = "Es sind Attentäter der Wiedervereinigungsgesellschaft! Fangt sie"
  },
  AvgDialog_131205_Content_67 = {
    Text = "Angeführt von einigen schreienden Bürgern, drängt sich ein Schwarm von Beamten durch die Menge und umzingelt euch."
  },
  AvgDialog_131205_Content_68 = {
    Text = "Während sie sich nähern, beginnen sich ihre Körper zu verformen – dunkle, chitinöse Spinnenbeine brechen aus ihren Oberkörpern hervor, und rasiermesserscharfe Klauen schlagen um sich."
  },
  AvgDialog_131205_Content_7 = {
    Text = "Diese Straße sollte wirklich erweitert werden, als wir Kinder waren, sah es hier genau so aus, außer dass es immer mehr verfällt, hat sich in all den Jahren wirklich nichts geändert."
  },
  AvgDialog_131205_Content_8 = {
    Text = "Die Obrigkeit taugt zu nichts, wenn es ums Aufbauen geht. Das Einzige, worin sie gut ist, ist Hewatz–Land zu verscherbeln und der Königsfamilie Kuchen zu servieren."
  },
  AvgDialog_131205_Content_9 = {
    Text = "Obdachlose, Demonstrationen, die Großherzog, der unbedingt zu diesem Zeitpunkt kommen muss... Lehrerin Arachne, kann ich meine ethnologischen Forschungsarbeit etwas später abgeben? Die Aktivitäten der Wiedervereinigungsgesellschaft haben mir in letzter Zeit zu viel Energie geraubt."
  },
  AvgDialog_131206_Content_10 = {
    Text = "Quiek——Quiek——Die Göttin des Schicksals dreht ihr Spinnrad."
  },
  AvgDialog_131206_Content_11 = {
    Text = "Quiek——Quiek——Der Faden des Schicksals versammelt sich in ihrer Hand."
  },
  AvgDialog_131206_Content_12 = {
    Text = "Die Puppen stehen in der Warteschlange, um in das große Netz des Schicksals einzutreten."
  },
  AvgDialog_131206_Content_13 = {
    Text = "Sie tanzen. Sie singen. Quiek——Quiek——"
  },
  AvgDialog_131206_Content_14 = {
    Text = "Sie starben still zusammen mit dem großen Netz."
  },
  AvgDialog_131206_Content_15 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131206_Content_16 = {
    Text = "Meister, unser neues Stück ist aufgeführt worden."
  },
  AvgDialog_131206_Content_17 = {
    Text = "Der Durchgang nach Kardas ist rechtzeitig geschlossen worden, diese Person {Male=Herr,Female=Dame} ist bereits in der Stadt angekommen."
  },
  AvgDialog_131206_Content_18 = {
    Text = "Wie gefällt dir das neue Stück?"
  },
  AvgDialog_131206_Content_19 = {
    Text = "Mmh... vielleicht ist es etwas zu kompliziert?"
  },
  AvgDialog_131206_Content_2 = {
    Text = "Nebelstadt nicht erweckt"
  },
  AvgDialog_131206_Content_20 = {
    Text = "Einfache Geschichten sind natürlich unbeschwert, aber für manche Menschen können solche Geschichten ihr Schicksal nicht schreiben."
  },
  AvgDialog_131206_Content_21 = {
    Text = "Dies ist das Schicksal, das einem „Helden\" gehört."
  },
  AvgDialog_131206_Content_22 = {
    Text = "Geh weiter; du bist an der Reihe auf der Bühne."
  },
  AvgDialog_131206_Content_23 = {
    Text = "Geh, es ist Zeit für deinen Auftritt."
  },
  AvgDialog_131206_Content_24 = {
    Text = "Das Mädchen warf sich zu Boden. In dem Moment, als ihre Stirn den Boden berührte, zerfiel ihr Körper in alle Richtungen – Fleisch und Haut verwandelten sich allesamt in hellviolette Spinnen, die in den Ecken des Raumes verschwanden."
  },
  AvgDialog_131206_Content_25 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131206_Content_26 = {
    Text = "<Shake:Hust... hust>"
  },
  AvgDialog_131206_Content_27 = {
    Text = "Unter dir ist der harte Asphalt. Du stehst wankend auf und reibst dir kräftig den chaotischen Kopf."
  },
  AvgDialog_131206_Content_28 = {
    Text = "Gerade eben... ist passiert..."
  },
  AvgDialog_131206_Content_29 = {
    Text = "Ah! Der Durchgang von Kardas!"
  },
  AvgDialog_131206_Content_3 = {
    Text = "Ah, Kardas, die Heimat meiner Träume! Endlich kann ich zurückkehren!"
  },
  AvgDialog_131206_Content_30 = {
    Text = "Du wachst plötzlich auf und blickst zum Himmel."
  },
  AvgDialog_131206_Content_31 = {
    Text = "Am tiefblauen Himmel strahlt die helle Sonne herab, und es gibt keine Spur mehr von der schwarzen Sonne und den Dimensionstoren."
  },
  AvgDialog_131206_Content_32 = {
    Text = "Das... diese Person ist seltsam... {Male=er,Female=sie} ist gerade vom Himmel gefallen?"
  },
  AvgDialog_131206_Content_33 = {
    Text = "Nun, soweit ich weiß, testet ein Technologieunternehmen in der Umgebung Fluggeräte, {Male=er,Female=sie} sollte ein Fluggerät-Tester sein."
  },
  AvgDialog_131206_Content_34 = {
    Text = "Hm... das... das ist..."
  },
  AvgDialog_131206_Content_35 = {Text = "Menschen."},
  AvgDialog_131206_Content_36 = {
    Text = "Die dicht gedrängte Menge erscheint in den von grellem Licht schmerzenden Augen."
  },
  AvgDialog_131206_Content_37 = {
    Text = "Belebte Straßen, versammelte Menschenmengen, überall Geschäfte, die vor Farben bersten..."
  },
  AvgDialog_131206_Content_38 = {
    Text = "Die Welt dieser Dimension hat durch das Schmelzen einen drastischen Bevölkerungsrückgang erlebt. Du hast nie eine so lebendige Szene erlebt, nicht einmal in Nekropolis."
  },
  AvgDialog_131206_Content_39 = {
    Text = "Die Bevölkerung dieser Dimension ist aufgrund der Auflösung stark zurückgegangen, selbst in der Nekropolis hast du nie einen so blühenden Anblick gesehen."
  },
  AvgDialog_131206_Content_4 = {
    Text = "Ah, Kardas, meine Heimat im Traum! Jetzt kann ich endlich zurückkehren"
  },
  AvgDialog_131206_Content_40 = {
    Text = "Wo ist das hier...?"
  },
  AvgDialog_131206_Content_41 = {
    Text = "Ha, seltsam, dass es tatsächlich jemanden gibt, der noch nie von Lentiniën gehört hat? Das ist die größte Stadt der Welt"
  },
  AvgDialog_131206_Content_42 = {
    Text = "<Shake:!!!>"
  },
  AvgDialog_131206_Content_43 = {
    Text = "Wie heißt dieser Ort hier?"
  },
  AvgDialog_131206_Content_44 = {
    Text = "Bist du dir sicher, dass du diese vier Wörter gehört hast."
  },
  AvgDialog_131206_Content_45 = {
    Text = "Dein benebelter Kopf wird sofort klar, du stehst plötzlich auf und schaust dich um."
  },
  AvgDialog_131206_Content_46 = {
    Text = "Die Brick Crossroads, die verwitterten Spuren auf dem Wegweiser sind genau wie in deiner Erinnerung."
  },
  AvgDialog_131206_Content_47 = {
    Text = "Im Zeitfalten-Secondhandbuchladen, jedes Mal, wenn du heimlich aus der Schule schlüpfst, ist es dein Lieblingsbeschäftigung, dich hier zu verstecken und Detektivromane zu lesen."
  },
  AvgDialog_131206_Content_48 = {
    Text = "Im Duftmarkt kauft Professor Dexter immer eine Flasche Goldwein, die du ihm von hier mitbringen sollst. N's kleiner Streich."
  },
  AvgDialog_131206_Content_49 = {
    Text = "Morgentau-Blumenhaus. Bei der Feier zu deinem einjährigen Jubiläum als Schutzherr hatte Ramona geplant, hier einen Strauß der schönsten Blumen aus ganz Lentiniën für dich zu bestellen..."
  },
  AvgDialog_131206_Content_5 = {
    Text = "Mein Lehrer, mein Gefährte, mein Freund, mein... alles."
  },
  AvgDialog_131206_Content_50 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131206_Content_51 = {
    Text = "Lentiniën... bin ich wirklich... zurück?"
  },
  AvgDialog_131206_Content_52 = {
    Text = "Darf ich fragen... Wie steht es jetzt um Misaq?"
  },
  AvgDialog_131206_Content_53 = {
    Text = "Misaq? Dieser {Male=Herr,Female=Fräulein}, von dem Sie sprechen, haben wir noch nie gehört."
  },
  AvgDialog_131206_Content_54 = {
    Text = "Wie steht es um die Auflösung? Wie sieht die Schadenslage hier aus?"
  },
  AvgDialog_131206_Content_55 = {
    Text = "Junger {Male=sir,Female=lady}, ich glaube, du bist einfach müde und ein wenig verwirrt... Setz dich auf die Bank dort und iss etwas. Ich habe zufällig ein wenig dabei."
  },
  AvgDialog_131206_Content_56 = {
    Text = "Kind, ich denke, du bist müde... Setz dich auf die Bank im Park und iss etwas. Ich habe hier gerade etwas."
  },
  AvgDialog_131206_Content_57 = {
    Text = "Der alte Mann reicht dir das Brot und das Wasser, die er gerade im Lebensmittelgeschäft gekauft hat."
  },
  AvgDialog_131206_Content_58 = {
    Text = "Ah, vielen Dank... aber ich habe jetzt keinen Hunger, ich habe nur... einige Fragen, die ich nicht ganz verstanden habe..."
  },
  AvgDialog_131206_Content_59 = {
    Text = "<Small:Das ist unmöglich... weder Misaq noch Auflösung...>"
  },
  AvgDialog_131206_Content_6 = {
    Text = "Egal, wenn ich durch diese dunkle Tür gehe, werde ich mich wieder mit ihnen vereinen"
  },
  AvgDialog_131206_Content_60 = {
    Text = "Das ist nicht nett. {Male=he,Female=she} macht vielleicht gerade etwas Schwieriges durch. Benimm dich gegenüber Gästen, die von weit her gekommen sind."
  },
  AvgDialog_131206_Content_61 = {
    Text = "Rede nicht dumm, {Male=er,Female=sie} könnte auf einige Schwierigkeiten gestoßen sein. Seid höflich zu den Gästen aus der Ferne."
  },
  AvgDialog_131206_Content_62 = {
    Text = "Eine Hand klopfte sanft auf deine Schulter. Du drehst dich um und siehst ein fremdes Gesicht."
  },
  AvgDialog_131206_Content_63 = {
    Text = "Wir sind die umliegenden Streifenpolizisten, die der Prüfungskommission unterstehen. Hier ist mein Ausweis."
  },
  AvgDialog_131206_Content_64 = {
    Text = "Ich grüße Sie. Ein wohlwollender Bürger hat uns mitgeteilt, dass ein Passagier sich in unserer schönen Stadt verlaufen hat."
  },
  AvgDialog_131206_Content_65 = {
    Text = "Darf ich fragen, ob dieser {Male=Herr,Female=Fräulein} Hilfe benötigt?"
  },
  AvgDialog_131206_Content_66 = {
    Text = "Du nimmst dir einen kurzen Moment zum Nachdenken. Bis du verstehst, was hier vor sich geht, ist es am besten, so wenig Aufmerksamkeit wie möglich auf dich zu ziehen."
  },
  AvgDialog_131206_Content_67 = {
    Text = "Ah... danke für eure Mühe. Ich bin nur auf dem Weg umgefallen, es ist nichts passiert."
  },
  AvgDialog_131206_Content_68 = {
    Text = "Vielen Dank euch. Wir haben noch etwas zu erledigen, geht schon mal vor..."
  },
  AvgDialog_131206_Content_69 = {
    Text = "Der Offizier tritt mit einem Lächeln auf dich zu und wischt dir den Staub von der Schulter"
  },
  AvgDialog_131206_Content_7 = {
    Text = "Aber warum ist diese Tür, die so nah ist, geschlossen? Warum hat mich dieser grausame Himmel verlassen?"
  },
  AvgDialog_131206_Content_70 = {
    Text = "Der Polizist kam lächelnd zu euch und klopfte den Staub von deiner Schulter."
  },
  AvgDialog_131206_Content_71 = {
    Text = "<Red:Hüter> – so sollte ich Dich ansprechen, richtig?"
  },
  AvgDialog_131206_Content_72 = {
    Text = "Ich möchte fragen ... Bist Du mit dieser Willkommenszeremonie für mich zufrieden?"
  },
  AvgDialog_131206_Content_73 = {Text = "!!!"},
  AvgDialog_131206_Content_74 = {
    Text = "Ein übelkeitserregendes, feuchtes Reißgeräusch erfüllt die Luft. Massive Spinnenbeine brechen durch die Körper der Beamten und Umstehenden und spritzen dickes, nach Eisen riechendes Blut über euch."
  },
  AvgDialog_131206_Content_75 = {
    Text = "Unser geschätzter Gast ist im Theater eingetroffen. Geleitet {Male=him,Female=her} zu {Male=his,Female=her} Platz, meine Kinder."
  },
  AvgDialog_131206_Content_76 = {
    Text = "Ja, meine Dame."
  },
  AvgDialog_131206_Content_77 = {Text = "Vorsicht!!"},
  AvgDialog_131206_Content_78 = {Text = "Vorsicht!!"},
  AvgDialog_131206_Content_8 = {
    Text = "Mein lieber Silberschlüssel... bitte erleuchte meinen Weg... bitte gib mir die bruchstückhaften Antworten..."
  },
  AvgDialog_131206_Content_9 = {
    Text = "Knarrend — knarrend — dreht die Göttin des Schicksals ihr Spinnrad."
  },
  AvgDialog_131207_Content_1 = {
    Text = "Spiegelbild des Gottes"
  },
  AvgDialog_131207_Content_10 = {
    Text = "Du hast noch die Chance, anzuhalten, Nefraea."
  },
  AvgDialog_131207_Content_11 = {
    Text = "Verschwinde vollständig, und was dann?"
  },
  AvgDialog_131207_Content_12 = {
    Text = "Nefraea lächelte frivol und wandte sich den frommen Dienern zu."
  },
  AvgDialog_131207_Content_13 = {
    Text = "Sagt mir, Kinder, habt ihr Angst?"
  },
  AvgDialog_131207_Content_14 = {
    Text = "Die Antwort auf Arachne ist ein verzweifeltes Lachen."
  },
  AvgDialog_131207_Content_15 = {
    Text = "Haha! Wir sind die vom Schicksal Verlassenen, nichts wird uns Angst einjagen... Bitte bring uns Erlösung, mein Herr."
  },
  AvgDialog_131207_Content_16 = {
    Text = "Braves Kind."
  },
  AvgDialog_131207_Content_17 = {
    Text = "Nefraea streichelte ihren Diener zärtlich über den Kopf."
  },
  AvgDialog_131207_Content_18 = {
    Text = "Du liegst falsch, meine liebe Schwester. Das Schicksal hat uns bereits zum Tode und zur ewigen Haft verurteilt. Eine Gruppe verlassener Geister wird nicht mehr um das Mitleid des Schicksals bitten."
  },
  AvgDialog_131207_Content_19 = {
    Text = "Wir rächen uns an dem Schicksal."
  },
  AvgDialog_131207_Content_2 = {
    Text = "Auf der grandiosen Bühne, die du noch nie gesehen hast, steht Nefraea's schwarzes Spinnrad einsam in der Mitte der Bühne. In der Mitte des riesigen Rings scheint ein niemals erlöschendes, tiefblaues Licht Nefraea's freudiges Gesicht zu beleuchten."
  },
  AvgDialog_131207_Content_20 = {
    Text = "Ob es absichtlich oder unbeabsichtigt war, eine der Schicksalsleinen, die Nefraea spielte, brach heimlich."
  },
  AvgDialog_131207_Content_21 = {
    Text = "Während der Faden riss, zerbrach in der Nähe eine Bühne mit einem gewaltigen Knall und verwandelte sich in verstreute Fragmente, die in den endlosen Dimensionen des Theaters vernichtet wurden."
  },
  AvgDialog_131207_Content_22 = {
    Text = "Oh je, Entschuldigung, Entschuldigung, ich habe versehentlich deinen Faden beschädigt..."
  },
  AvgDialog_131207_Content_23 = {
    Text = "Mach schnell, gute Schwester. Es gibt zwar viele Bühnen im Theater, aber wenn du sie noch einmal kaputt machst, wirst du auch traurig sein, oder?"
  },
  AvgDialog_131207_Content_24 = {
    Text = "Arachne's Seufzer ist kaum hörbar. Als sie die Augen wieder öffnete, hob sie die Fingerspitzen und klopfte leicht auf deinen Kopf."
  },
  AvgDialog_131207_Content_25 = {
    Text = "Arachne! Mach das nicht... Wir werden einen anderen Weg finden..."
  },
  AvgDialog_131207_Content_26 = {
    Text = "Betritt die Bühne. Opfere den Druckbefehl der Plasmide dem Apostel... Dies ist dein unausweichliches Schicksal, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131207_Content_27 = {
    Text = "Arachne's unwiderstehliche Stimme hallt in deiner geistigen Welt wider. Als du deine Schritte in Richtung der Bühne hebst, beginnen drei längst vergessene Kräfte in dir unruhig zu werden."
  },
  AvgDialog_131207_Content_28 = {
    Text = "Sie verwickeln und stoßen in deinem Körper und kämpfen gegen die prophetischen Worte von Arachne."
  },
  AvgDialog_131207_Content_29 = {
    Text = "Ach, das ist wirklich die Trinität... So ein wenig Macht, über so weit entfernte Dimensionen hinweg, kann immer noch Einfluss auf den Wirt ausüben."
  },
  AvgDialog_131207_Content_3 = {
    Text = "Schau, {Male=Mr.,Female=Miss} Schutzherr, was für wunderschöne Lichter..."
  },
  AvgDialog_131207_Content_30 = {
    Text = "Bring sie zur Räson, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131207_Content_4 = {
    Text = "Dieses Licht ist ein Geschenk des Schicksals, es wird uns führen zu dem paradiesischen Ort ohne Leid..."
  },
  AvgDialog_131207_Content_5 = {
    Text = "Nefraea streckte die Hand aus und streichelte die Spuren des Lichts, die im Dimensionsraum hinterlassen wurden. Der Schatten der Finger zog sich langsam zusammen und wühlte sich über das Gesicht von Arachne."
  },
  AvgDialog_131207_Content_6 = {
    Text = "Komm, Schwester, unser Hauptdarsteller soll auftreten."
  },
  AvgDialog_131207_Content_7 = {
    Text = "...Das Schicksal ist nichts, was man spielen oder manipulieren kann, Nefraea."
  },
  AvgDialog_131207_Content_8 = {
    Text = "Jedes Schicksal ist bereits besiegelt. Wenn du diese Gottheit erweckst und alles enden lässt... das gewaltsame Verändern des Schicksals wird eine Katastrophe heraufbeschwören, die deine Vorstellungskraft übersteigt."
  },
  AvgDialog_131207_Content_9 = {
    Text = "Ob es das ist, was du verachtest, oder das, was dir lieb ist—alles wird in der Apokalypse vergehen."
  },
  AvgDialog_131208_Content_1 = {Text = "Urteil"},
  AvgDialog_131208_Content_10 = {
    Text = "Das Mädchen atmete tief ein und lächelte zufrieden."
  },
  AvgDialog_131208_Content_11 = {
    Text = "Die Iris hat bereits zu blühen begonnen... Ein weiterer Frühling ist wirklich gekommen."
  },
  AvgDialog_131208_Content_12 = {
    Text = "Hey, Xiao Fu, habe ich dich schon einmal gefragt, welche Jahreszeit du am liebsten magst?"
  },
  AvgDialog_131208_Content_13 = {
    Text = "... Ich habe keine Lieblingsjahreszeit, Meister."
  },
  AvgDialog_131208_Content_14 = {
    Text = "Langweilig."
  },
  AvgDialog_131208_Content_15 = {
    Text = "Arachne rollte mit den Augen, streckte die Hand aus, die keinen Faden spann, und fing das von draußen fallende Sonnenlicht ein."
  },
  AvgDialog_131208_Content_16 = {
    Text = "Ich liebe jede Jahreszeit, besonders den Frühling. Es ist so lange her, seit wir das Haus verlassen haben... sollten wir uns Zeit für eine Wanderung nehmen?"
  },
  AvgDialog_131208_Content_17 = {
    Text = "Neben dem Gutshaus, in dem ich geboren wurde, gibt es einen sehr schön gepflegten Blumenbeet, den ihr sicherlich mögen werdet."
  },
  AvgDialog_131208_Content_18 = {
    Text = "Sie haben drei Tage gewartet... Es ist Zeit, eine Entscheidung zu treffen, mein Herr."
  },
  AvgDialog_131208_Content_19 = {
    Text = "Die Zofe erfüllt ihre Pflichten, ihre kalten Worte sind wie ein kalter Regen. Sie löschen den strahlenden Frühling in Arachne's Augen aus."
  },
  AvgDialog_131208_Content_2 = {
    Text = "Quiek——Quiek——Die Göttin des Schicksals dreht ihr Spinnrad."
  },
  AvgDialog_131208_Content_20 = {
    Text = "Quiek, Quiek......"
  },
  AvgDialog_131208_Content_21 = {
    Text = "Nach einem kurzen Zögern begann das Spinnrad erneut zu drehen. Seine Frequenz ist sanft, klar und unverändert seit Anbeginn der Zeit."
  },
  AvgDialog_131208_Content_22 = {
    Text = "Das Land, in dem wir uns befinden, hat gerade einen hundertjährigen Krieg beendet. Die Menschen haben ihre Städte auf den Ruinen neu aufgebaut und warten auf eine lange Friedenszeit, die vor ihnen liegt."
  },
  AvgDialog_131208_Content_23 = {
    Text = "Sieh mal, dort..."
  },
  AvgDialog_131208_Content_24 = {
    Text = "Dem Blick von Arachne folgend, schaute die Zofe auf das riesige Gemälde, das in der Halle hing. Sie hatte es nie verstanden."
  },
  AvgDialog_131208_Content_25 = {
    Text = "Unter all den großartigen Gemälden von Herrn Zoss ist dieses Bild das am wenigsten beachtete, aber es ist mein Lieblingswerk."
  },
  AvgDialog_131208_Content_26 = {
    Text = "Diese Hirsche, gemalt in Ocker und geometrischen Formen... selbst als abstrakte Symbole pulsieren sie vor Leben."
  },
  AvgDialog_131208_Content_27 = {
    Text = "Jedes Mal, wenn ich es sehe, denke ich an mein Lieblingsstück..."
  },
  AvgDialog_131208_Content_28 = {
    Text = "Der Riss existiert seit drei Tagen, Meister. Das Schicksal dieser Dimension ist bereits vom Blick jener Gottheit infiziert worden."
  },
  AvgDialog_131208_Content_29 = {
    Text = "Wenn das so weitergeht, wird Sein Blick Orte zerstören, die weit über diesen hier hinausgehen."
  },
  AvgDialog_131208_Content_3 = {
    Text = "Quiek——Quiek——Der Faden des Schicksals versammelt sich in ihrer Hand."
  },
  AvgDialog_131208_Content_30 = {
    Text = "Quiek, Quiek."
  },
  AvgDialog_131208_Content_31 = {
    Text = "Das Mädchen schloss die Augen und genoss die Berührung der Sonnenstrahlen. Der warme Raum fiel in Stille, nur das Spinnrad drehte sich weiterhin mit der uralten Frequenz."
  },
  AvgDialog_131208_Content_32 = {
    Text = "Erinnerst du dich, wie viele Schicksale von Welten wir bereits gewoben haben?"
  },
  AvgDialog_131208_Content_33 = {
    Text = "Insgesamt siebenundzwanzig, Meister."
  },
  AvgDialog_131208_Content_34 = {
    Text = "Nachdem mein Vater mir dieses Spinnrad geschenkt hatte, näherte ich mich mit seinen Fäden der Tür zur Wahrheit. Hinter dieser Tür sah ich das Schicksal, das diese Welt erwarten wird..."
  },
  AvgDialog_131208_Content_35 = {
    Text = "Ich weiß, was auf mich wartet. Ich weiß, welche Entscheidungen ich treffen sollte... aber ich kann es nicht."
  },
  AvgDialog_131208_Content_36 = {
    Text = "Verwandte. Freunde. Erinnerungen. Siebzehntausend Jahre glorreiche Geschichte. Sternenartige Technologie und Kunst..."
  },
  AvgDialog_131208_Content_37 = {
    Text = "Nachdem ich diese Antwort gesehen hatte, begann ich, das Schicksal dieser Welt zu weben... Ich dachte immer, das Schicksal hat mir diese Fähigkeit gegeben, ich kann sicher etwas für diese Welt tun."
  },
  AvgDialog_131208_Content_38 = {
    Text = "Das ist mein Zuhause. Mein Kind. <Shake:Ich... ich kann es nicht tun>, Xiaofu..."
  },
  AvgDialog_131208_Content_39 = {Text = "Meister..."},
  AvgDialog_131208_Content_4 = {
    Text = "Die Puppen stehen in der Warteschlange, um in das große Netz des Schicksals einzutreten."
  },
  AvgDialog_131208_Content_40 = {
    Text = "Die Zofe kniete sich nieder und wischte die Tränen der Herrin weg. Im Frühlingssonnenschein war ihre Stimme klar und fest."
  },
  AvgDialog_131208_Content_41 = {
    Text = "Sie haben diesen Tag vorausgesehen, deshalb haben Sie mich zu Ihrer Dienerin gemacht."
  },
  AvgDialog_131208_Content_42 = {
    Text = "Der gesamte Sinn meines Lebens besteht darin, Ihnen in diesem Moment zu sagen, was Sie tun sollten..."
  },
  AvgDialog_131208_Content_43 = {
    Text = "Sie sind der Herr des Schicksals, der Wächter dieser vielen Dimensionen. Es ist ein harter Weg, aber Sie haben bereits eine Wahl getroffen."
  },
  AvgDialog_131208_Content_44 = {
    Text = "Die drei Göttinnen des Schicksals, verantwortlich für das Weben, das Messen... und das Schneiden."
  },
  AvgDialog_131208_Content_45 = {
    Text = "Von dem Moment an, in dem Sie Ihre Wahl getroffen haben, sind dies die Pflichten, die Sie erfüllen müssen."
  },
  AvgDialog_131208_Content_46 = {
    Text = "Arachne hob den Kopf, in ihren verschwommenen Augen blitzte der Riss am Himmel, den gewöhnliche Menschen nicht sehen können. Er war immer dort, neben dem warmen Frühlingssonnenlicht, wie ein grausames Lächeln."
  },
  AvgDialog_131208_Content_47 = {
    Text = "Der Riss flüstert zu Arachne und erzählt ihr von den kalten Zukünften. Sie hat diesen Fluch schon lange angenommen, und als die Zukunft erscheint, zittert ihr Körper noch immer vor Angst."
  },
  AvgDialog_131208_Content_48 = {
    Text = "Arachne sitzt wieder vor dem Webstuhl. Nach Angst und Verzweiflung hat sich ein ungesundes Rot auf ihrem Gesicht gezeigt."
  },
  AvgDialog_131208_Content_49 = {
    Text = "Sie streicht über die dichten, verwirrten Fäden, als streichle sie das Gesicht eines Kindes."
  },
  AvgDialog_131208_Content_5 = {
    Text = "Sie tanzen. Sie singen. Quiek——Quiek——"
  },
  AvgDialog_131208_Content_50 = {
    Text = "Im Jahr 804, noch bevor ich sprechen konnte, spielte unser Butler ein Stück auf dem Klavier."
  },
  AvgDialog_131208_Content_51 = {
    Text = "Elysions <Italic:„Begräbnis am Fluss Loos\".> Die Musik war wie ein Brunnen, der vor einem Tempel fließt. Ich sah, wie selbst die Götter innehielten, um zu lauschen..."
  },
  AvgDialog_131208_Content_52 = {
    Text = "Ein Faden wird lautlos durchtrennt. Er schwebt still in der Luft und schwebt lautlos in den Nachbeben des Schicksals."
  },
  AvgDialog_131208_Content_53 = {
    Text = "Die Musik im Saal verklingt, nur der Phonograph dreht sich weiter. Die Rillen auf der Platte sind gefüllt, der schön geschwungene Titel des Liedes ist übermalt."
  },
  AvgDialog_131208_Content_54 = {
    Text = "Elysion hat sein anderes Schicksal begrüßt. In dieser einsamen Welt hat sein grandioses Leben nie existiert."
  },
  AvgDialog_131208_Content_55 = {
    Text = "Kassandra, die von ihr entworfene Kirche, ist mehr wert, bewundert zu werden als die Götter darin..."
  },
  AvgDialog_131208_Content_56 = {
    Text = "Ein weiterer Faden reißt. Zweihundert Kilometer entfernt zerbricht und stürzt die prächtige Kirche ein, die mitleidigen Augen der Gottheit zerbrechen und sind nicht mehr von Staub zu unterscheiden."
  },
  AvgDialog_131208_Content_57 = {
    Text = "Mornlins Märchen, Aldos Oper, Malmos Gemälde, Rovils Poesie..."
  },
  AvgDialog_131208_Content_58 = {
    Text = "Bücher werden zu Papierfetzen, Skulpturen zu Fragmenten, Gemälde zu ungeordneten Farben."
  },
  AvgDialog_131208_Content_59 = {
    Text = "Sie ist die Gedenkreporterin. Sie ist die Henkerin. Sie spricht die Namen aller großen Künstler dieser Welt aus und durchtrennt den Faden, der ihnen gehört."
  },
  AvgDialog_131208_Content_6 = {
    Text = "Das Sonnenlicht erhellt ihre Gesichter, wie fröhlich——"
  },
  AvgDialog_131208_Content_60 = {
    Text = "Wilderburg, eine majestätische Stadt der Helden. Sie hat hundertfünf Kriege überstanden, wurde siebenunddreißig Mal zerstört und wieder aufgebaut, und einundzwanzig große Herren haben hier Ruhm und Ehre erlangt, während sie im Sand scheiterten."
  },
  AvgDialog_131208_Content_61 = {
    Text = "Die Adligen singen hier, die Armen schreien hier, die Dichter hinterlassen schöne Verse für sie, und die Gesänge am Ufer des Nerkin-Flusses und das Kanonenfeuer hallen über ihr. Ihre heldenhafte Geschichte endet heute."
  },
  AvgDialog_131208_Content_62 = {
    Text = "Eine Gruppe von durchtrennten Fäden wehte chaotisch, wie ein ausgelassener Tanz. Zweitausenddreihundert Kilometer entfernt stürzte die prächtige Stadt mit einem gewaltigen Krachen ein."
  },
  AvgDialog_131208_Content_63 = {
    Text = "Siebzehntausend Jahre des Bestehens, in denen die alte Zivilisation zwischen Verderben und menschlichem Unheil mühsam standhaft blieb und nie gefallen ist..."
  },
  AvgDialog_131208_Content_64 = {
    Text = "Weich, zitternd. Arachne hob mit all ihrer Kraft die Hand und griff nach den endlosen Fäden vor ihr."
  },
  AvgDialog_131208_Content_65 = {
    Text = "Der Faden riss. Acht tausend Kilometer entfernt verschwand das große alte Land, das die menschliche Zivilisation über Jahrtausende hinweg bewahrt hatte und nie abgebrochen war, so einfach aus der Geschichte der Menschheit, wie ein Hauch von Rauch."
  },
  AvgDialog_131208_Content_66 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131208_Content_67 = {
    Text = "Menschen. Kunst. Stadt. Nation. Zivilisation."
  },
  AvgDialog_131208_Content_68 = {
    Text = "Alles bricht zusammen, alles verschwindet."
  },
  AvgDialog_131208_Content_69 = {
    Text = "<Shake:Siehst du, Xiaofu?> Mein erstes Kind ist tot... Ich habe sie mit meinen eigenen Händen getötet."
  },
  AvgDialog_131208_Content_7 = {
    Text = "Quiek, Quiek."
  },
  AvgDialog_131208_Content_70 = {
    Text = "Tränen fallen ruhig herab. Arachne lächelt schwach und schaut aus dem Fenster. Inmitten der Ruinen der ganzen Welt steht nur noch das wacklige Herrenhaus draußen."
  },
  AvgDialog_131208_Content_71 = {
    Text = "Ich habe mir einmal gedacht, dass es mich weniger einsam auf diesem Weg fühlen lassen würde, wenn ich beim Weben des Schicksals immer auf den Ort schauen könnte, an dem ich früher gelebt habe."
  },
  AvgDialog_131208_Content_72 = {
    Text = "Es ist wirklich kindisch... Für einen Henker ohne Wahl habe ich mir selbst die grausamste Strafe bereitet."
  },
  AvgDialog_131208_Content_73 = {
    Text = "Sie streckte die Hand aus und berührte den verschwommenen, für sie unsichtbaren Faden auf ihrem Kopf, und verband einen Teil davon mit dem letzten Faden dieser Welt."
  },
  AvgDialog_131208_Content_74 = {
    Text = "Meister, was ist das...?"
  },
  AvgDialog_131208_Content_75 = {
    Text = "Romantik bringt Dummheit, Güte bringt Zerbrechlichkeit, Erinnerungen bringen Schmerz..."
  },
  AvgDialog_131208_Content_76 = {
    Text = "Ich habe es mir überlegt, Xiaofu. Ich bin der verfluchte Henker, die schönen Dinge sollten nicht in mir existieren."
  },
  AvgDialog_131208_Content_77 = {
    Text = "Du willst... einen Teil von dir selbst auslöschen? Aber das sind die Stücke, die du am meisten schätzt – wie kannst du..."
  },
  AvgDialog_131208_Content_78 = {
    Text = "Als ich sehr klein war, hatte ich meinen ersten Traum."
  },
  AvgDialog_131208_Content_79 = {
    Text = "Arachne streckte die Hand aus und fing das Licht der Sonne ein, das die endlosen Ruinen erhellte."
  },
  AvgDialog_131208_Content_8 = {
    Text = "Das alte Spinnrad erzeugt eine sanfte Begleitung, das Mädchen sitzt vor dem Spinnrad und summt ein einfaches Lied."
  },
  AvgDialog_131208_Content_80 = {
    Text = "Im Traum gehe ich über die Oberfläche eines Sees. Um mich herum sind endlose Ruinen und knochige Überreste, während unter der Wasseroberfläche das Spiegelbild meiner Kindheit in einem schönen Königreich wandelt."
  },
  AvgDialog_131208_Content_81 = {
    Text = "Kein Tod, kein Leid, kein Vergessen. Sanfte Sonne strahlt dort für immer, die Menge singt fröhlich an ihrer Seite, unermüdlich..."
  },
  AvgDialog_131208_Content_82 = {
    Text = "Ich kann nicht sehen, wohin meine Fäden führen, aber ich glaube, ich habe jetzt das Schicksal erkannt, das dieser Traum voraussagt."
  },
  AvgDialog_131208_Content_83 = {
    Text = "Sie bemühte sich, die Mundwinkel zu bewegen, vielleicht zu ihrer Zofe oder zu etwas anderem."
  },
  AvgDialog_131208_Content_84 = {
    Text = "Die Mutter sagte, man solle den Namen Arachne umdrehen, und er werde zu Nefraea. In den Legenden dieser Welt ist es der Name der Frühlingsgöttin."
  },
  AvgDialog_131208_Content_85 = {
    Text = "Ich mag jede Jahreszeit, besonders den Frühling. Der Frühling ist viel kleiner als das Schicksal, viel, viel kleiner. Doch das Schicksal führt immer zum Tod, während der Frühling, der Frühling nur neues Leben bringt..."
  },
  AvgDialog_131208_Content_86 = {
    Text = "Sie schaut aus dem Fenster. An den Seiten des Fensters blicken Schicksal und Frühling ein letztes Mal aufeinander."
  },
  AvgDialog_131208_Content_87 = {
    Text = "Lass mich gehen, mein Schatten, meine liebe Schwester. Zusammen mit all unseren schönen Eigenschaften und all unseren schönen Erinnerungen."
  },
  AvgDialog_131208_Content_88 = {
    Text = "Schicksal... Ich opfere einen Teil meiner selbst als vollkommene Gabe an dich. Ich werde diesen beschwerlichen Pfad an ihrer Stelle gehen."
  },
  AvgDialog_131208_Content_89 = {
    Text = "Arachne streichelte sanft die miteinander verwobenen Fäden. Die Fäden zitterten leicht, als ob sie kämpften und schrien."
  },
  AvgDialog_131208_Content_9 = {
    Text = "Ein Sonnenstrahl fällt durch das Fenster und beleuchtet ein Namensschild mit der Gravur „Moirai\" neben dem Spinnrad."
  },
  AvgDialog_131208_Content_90 = {
    Text = "Ihre Tränen flossen durch den Faden und tropften auf das Schild von „Moirai\"."
  },
  AvgDialog_131208_Content_91 = {
    Text = "Du bist frei, „Arachne\"."
  },
  AvgDialog_131208_Content_92 = {Text = "Quiek."},
  AvgDialog_131208_Content_93 = {
    Text = "Der Faden reißt. In der warmen Frühlingssonne gibt das Spinnrad einen letzten Seufzer von sich."
  },
  AvgDialog_131209_Content_1 = {
    Text = "Wiedervereinigung"
  },
  AvgDialog_131209_Content_10 = {
    Text = "Wenn ich mich entscheiden würde, Opernsänger zu werden, würde die Schlange vor dem Theater sicher drei Straßenblocks lang sein."
  },
  AvgDialog_131209_Content_11 = {
    Text = "Schade, dass die Puppen aus Lentiniën keine Gelegenheit hatten, meine großartige Aufführung zu sehen. So betrachtet, bist du wirklich glücklich, kleine Süße."
  },
  AvgDialog_131209_Content_12 = {
    Text = "Nefraea streichelte sanft das Gesicht des Mädchens, als ob eine Mutter liebevoll ihre Tochter berührt."
  },
  AvgDialog_131209_Content_13 = {
    Text = "Im Zentrum des Kirchensaals durchbohrte der Stahlstift die Brust, den Bauch, die Schultern, die Schambeine und die Handflächen des Mädchens und nagelte sie an den riesigen Spinnrad-Lampenständer, indem er jeden Punkt ihres Körpers durchdrang, der für das Hängen und das Empfinden von Schmerz geeignet war."
  },
  AvgDialog_131209_Content_14 = {
    Text = "Nefraea brachte ihre blutigen Hände an die Nasenspitze und schloss besessen die Augen."
  },
  AvgDialog_131209_Content_15 = {
    Text = "Ah... der Duft des Lebens, so lebendig."
  },
  AvgDialog_131209_Content_16 = {
    Text = "In den letzten Jahren habe ich es viele Male versucht, die Körper der Kinder zu beißen, meinen eigenen Körper zu beißen, aber ich habe nicht einmal den kleinsten Hauch des Geschmacks des Lebens schmecken können."
  },
  AvgDialog_131209_Content_17 = {
    Text = "Das richtige Schicksal. Lebendige Leidenschaft. Wie beneidenswert... Aber weißt du? Du hättest, genau wie wir, in den Müll des Schicksals geworfen werden sollen."
  },
  AvgDialog_131209_Content_18 = {
    Text = "Du musst nicht essen, sprichst nie. Außer den Erinnerungen, die für sie bewahrt wurden, hast du nichts, weißt du nichts."
  },
  AvgDialog_131209_Content_19 = {
    Text = "Das Schicksal hat dich längst verlassen, armes Kind. Du bist nur eine Puppe, die ihr Trost bietet, ein Wächter der Erinnerungen, der einsam auf dieser heuchlerischen Bühne umherirrt..."
  },
  AvgDialog_131209_Content_2 = {
    Text = "<Shake:La...♪ La la...♪>"
  },
  AvgDialog_131209_Content_20 = {
    Text = "Sie sah das Mädchen an, das kaum noch Atem hatte, ihre flüsternde Stimme zitterte vor Traurigkeit, während ihre kalten Finger sanft die zerzausten Strähnen am Kopf des Mädchens ordneten."
  },
  AvgDialog_131209_Content_21 = {
    Text = "Jetzt kommt deine grausame Schicksalsmutter... Egal was passiert, stelle dich allem in der schönsten Form, verstanden, mein Lieber?"
  },
  AvgDialog_131209_Content_22 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131209_Content_23 = {
    Text = "Nachdem sich die Augen an das düstere Licht der Kirche gewöhnt haben, fällt dein Blick zuerst auf eine Gruppe riesiger Wandmalereien."
  },
  AvgDialog_131209_Content_24 = {
    Text = "Eine schleimige Farbe wurde an die Dutzende Meter hohen Wände aufgetragen und erstreckte sich endlos in die unergründliche Dunkelheit. Monumental, heilig, schmutzig, wie eine Statue des Erlösers, die in einem Abwasserkanal steht."
  },
  AvgDialog_131209_Content_25 = {
    Text = "Die einfühlsame Gastgeberin räumte den Raum für die Besucher, und in der weitläufigen Kirche hallten nur die Geräusche von Schritten und Atem. Du kommst unter dem großen Wandgemälde an und blickst nach oben."
  },
  AvgDialog_131209_Content_26 = {
    Text = "Eine Frau sitzt vor dem Spinnrad und schneidet mit einer Schere den Seidenfaden durch... Ist das Wandgemälde von dir?"
  },
  AvgDialog_131209_Content_27 = {
    Text = "Es sieht tatsächlich so aus... ich denke, das sind die Worte, die meine Schwester uns sagen möchte."
  },
  AvgDialog_131209_Content_28 = {
    Text = "Arachne war nicht eilig, den Ort des „Erinnerns\" zu suchen. Sie folgte deinen Schritten und betrachtete interessiert die Wandmalereien."
  },
  AvgDialog_131209_Content_29 = {
    Text = "Eine identische Silhouette verlässt die sitzende Frau und stürzt in die Dunkelheit der Höhle..."
  },
  AvgDialog_131209_Content_3 = {
    Text = "Quiek——Quiek——Die Göttin des Schicksals dreht ihr Spinnrad."
  },
  AvgDialog_131209_Content_30 = {
    Text = "In der dunklen Höhle führen eine Frau und andere Kreaturen der Nacht einen seltsamen Tanz auf. Sie hält... ein Spinnrad?"
  },
  AvgDialog_131209_Content_31 = {
    Text = "Die Mitte leuchtet wie eine Latern und erhellt die Schatten."
  },
  AvgDialog_131209_Content_32 = {
    Text = "Die Frau kam mit einer spinnradförmigen Laterne in die Stadt ... Eine Gruppe von Menschen in heiligen Gewändern kniete vor der Frau und der Laterne. Auf ihren Kleidern war ... das Symbol der Laterne eingraviert?"
  },
  AvgDialog_131209_Content_33 = {
    Text = "Es gibt einige subtile Unterschiede zu dem Laternenzeichen, das du früher gesehen hast; um das böse umgekehrte Dreieck herum gibt es einen zusätzlichen kreisförmigen Spinnrad-Rand."
  },
  AvgDialog_131209_Content_34 = {
    Text = "Aber du verstehst jedes Element dieses Symbols. Du weißt genau, dass es das Symbol des Laternenordens ist, dass es die Geburt des Laternenordens ist."
  },
  AvgDialog_131209_Content_35 = {
    Text = "Das letzte Bild..."
  },
  AvgDialog_131209_Content_36 = {
    Text = "Das letzte Wandgemälde steht am Ende des Flurs, wie eine Tür, die das Schicksal abtrennt. Schmutzige Farben wogen auf dem Wandgemälde und spiegeln das trübe Licht und Schatten in der Kirche wider."
  },
  AvgDialog_131209_Content_37 = {
    Text = "Eine Frau hält eine Latern und kniet vor einer verschwommenen Gestalt. Hinter ihnen ragt etwas Gewaltiges auf..."
  },
  AvgDialog_131209_Content_38 = {Text = "Ugh..."},
  AvgDialog_131209_Content_39 = {
    Text = "Als du das riesige, noch geschlossene Auge erkennst, überkommt dich ein vertrauter, starker Stechschmerz und entfesselt eine tobende Welle in deinem mentalen Raum."
  },
  AvgDialog_131209_Content_4 = {
    Text = "Quiek——Quiek——Der Faden des Schicksals versammelt sich in ihrer Hand."
  },
  AvgDialog_131209_Content_40 = {
    Text = "Du wendest schnell den Blick ab und atmest tief durch, um die aufsteigende Übelkeit zu unterdrücken."
  },
  AvgDialog_131209_Content_41 = {
    Text = "<Shake:Huff... huff...> Die Kirche der Lichtträger... Toguwaibo..."
  },
  AvgDialog_131209_Content_42 = {
    Text = "In dieser Dimension ist Nefraea tatsächlich... die Schöpferin des Laternenordens"
  },
  AvgDialog_131209_Content_43 = {
    Text = "Ach so, ich habe es verstanden!......"
  },
  AvgDialog_131209_Content_44 = {
    Text = "Du hast die Wahrheit gesehen, {Male=Mr.,Female=Miss} Schutzherr. Als die Höchste Gottheit ihrem Erwachen nahekam, entkam meine verstoßene Schwester aus dem Abgrund."
  },
  AvgDialog_131209_Content_45 = {
    Text = "Sie störte meine Sicht und verbarg diese Sekte unter meiner Bühne."
  },
  AvgDialog_131209_Content_46 = {
    Text = "Diese Person, die sie verehrt, ist der Apostel, der in dieser Dimension mit dem höchsten Gott verbunden ist."
  },
  AvgDialog_131209_Content_47 = {
    Text = "Du siehst erneut den verschwommenen Schatten an der Wandmalerei, der mit Toguwaibo verbunden ist."
  },
  AvgDialog_131209_Content_48 = {
    Text = "Ich verstehe... Nefraea möchte die Verbindung zu Toguwaibo wiederherstellen, indem sie sich auf die Stärke derjenigen Apostel stützt!..."
  },
  AvgDialog_131209_Content_49 = {
    Text = "Aber wenn das so ist, warum jagt sie dann diese geheimen Objekte..."
  },
  AvgDialog_131209_Content_5 = {
    Text = "Die Puppen stehen in der Warteschlange, um in das große Netz des Schicksals einzutreten."
  },
  AvgDialog_131209_Content_50 = {Text = "Dong——"},
  AvgDialog_131209_Content_51 = {
    Text = "Der trübe Glockenklang ertönt vom Glockenturm der Kirche, wie eine schmutzige Offenbarung."
  },
  AvgDialog_131209_Content_52 = {
    Text = "Die riesige Kathedrale dröhnt dumpf. In den langen Vibrationen erhebt sich langsam die steinerne Wand mit den schmutzigen Wandmalereien."
  },
  AvgDialog_131209_Content_53 = {
    Text = "Das ist es!"
  },
  AvgDialog_131209_Content_54 = {
    Text = "Arachne......Dame......"
  },
  AvgDialog_131209_Content_55 = {
    Text = "Ach... unsere kleine „Erinnerung\", die Stimme ist wirklich so schwach, dass sie bedauernswert ist."
  },
  AvgDialog_131209_Content_56 = {
    Text = "Nefraea! Freigeben Sie sie"
  },
  AvgDialog_131209_Content_57 = {
    Text = "Der Körper des kleinen Mädchens hängt am majestätischen Spinnrad-Lampenständer, und blutrotes Blut fließt langsam auf dem weißen Marmor."
  },
  AvgDialog_131209_Content_58 = {
    Text = "Helles Licht strahlt hinter dem Mädchen und umreißt die blutige Gestalt mit einem heiligen Schatten."
  },
  AvgDialog_131209_Content_59 = {
    Text = "Nefraea, hör auf mit diesen sinnlosen Kämpfen. Lass sie gehen."
  },
  AvgDialog_131209_Content_6 = {
    Text = "Sie tanzen. Sie singen. Quiek——Quiek——"
  },
  AvgDialog_131209_Content_60 = {
    Text = "Oh? Unsere Schicksalsgöttin beginnt sich jetzt um ihre „Erinnerungen\" zu kümmern?"
  },
  AvgDialog_131209_Content_61 = {
    Text = "Du hast dich nie um sie gekümmert, du hast sie aufgegeben, Arachne."
  },
  AvgDialog_131209_Content_62 = {
    Text = "Nefraea, ich weiß, dass du die Apostel beschwören und Toguwaibo erneut erwecken möchtest... Wenn es etwas gibt, können wir noch einmal darüber sprechen, es ist nicht notwendig, sie zu töten..."
  },
  AvgDialog_131209_Content_63 = {
    Text = "Die Art, wie du Zeit schindest, ist bezaubernd kindisch, %player%."
  },
  AvgDialog_131209_Content_64 = {
    Text = "Du verstehst nichts. Ich habe sie niemals getötet. Ich bringe sie nur nach Hause."
  },
  AvgDialog_131209_Content_65 = {
    Text = "Euch hierher zu bringen, ist nur dazu da, dass ihr gemeinsam ihr erfülltes Ende bezeugen könnt."
  },
  AvgDialog_131209_Content_66 = {
    Text = "Zweite Szene, dritter Akt. Ich nenne es „Zusammenkunft\"."
  },
  AvgDialog_131209_Content_67 = {
    Text = "Nefraea sah dich verächtlich an. Ihre Nägel strichen sanft über das Gesicht von „Erinnern\" und hinterließen einen feinen Blutstrich darauf."
  },
  AvgDialog_131209_Content_68 = {
    Text = "Sie beugte sich herunter und sah das Mädchen mit liebevollem Blick an, dessen Gesicht vor Schwäche und Angst zitterte."
  },
  AvgDialog_131209_Content_69 = {
    Text = "Braves Kind, fürchte dich nicht. Bald sind wir zu Hause."
  },
  AvgDialog_131209_Content_7 = {
    Text = "Sie starben still zusammen mit dem großen Netz."
  },
  AvgDialog_131209_Content_70 = {
    Text = "Sag Lebewohl zu deinen unerträglichen Erinnerungen, meine liebe Schwester——"
  },
  AvgDialog_131209_Content_71 = {
    Text = "Warte... Nefraea!"
  },
  AvgDialog_131209_Content_72 = {Text = "Knack—"},
  AvgDialog_131209_Content_73 = {
    Text = "Im klaren Klang von Nefraea's Fingerschnippen explodierte der Körper des Mädchens wie ein rotes Feuerwerk."
  },
  AvgDialog_131209_Content_74 = {
    Text = "Das Licht der Laterne erleuchtet die spritzenden Blutspuren und wirft eine scharlachrote Blume auf eure Gesichter."
  },
  AvgDialog_131209_Content_75 = {
    Text = "Blutkugeln spritzen in die Luft, verweilen und kehren dann zurück, klettern gierig auf den Körper von Nefraea und färben jede Ecke ihres Körpers rot."
  },
  AvgDialog_131209_Content_76 = {
    Text = "Die Blutstropfen flossen weiter nach unten, drangen in ihre Kleidung und Haut ein, durchzogen jede ihrer Adern und strömten in ihrem zarten Körper."
  },
  AvgDialog_131209_Content_77 = {
    Text = "Die Zunge leckte das Blut an den Lippen, während Nefraea erfreut ihre mit Blut gefärbten Nägel betrachtete, wie eine elegant gekleidete Gastgeberin, die sich auf ein Fest der Wiedervereinigung vorbereitet."
  },
  AvgDialog_131209_Content_78 = {
    Text = "Willkommen zu Hause, mein Lieber."
  },
  AvgDialog_131209_Content_79 = {Text = "Hör auf!"},
  AvgDialog_131209_Content_8 = {
    Text = "Der Gesang hallt in der weiten Kirche wider. Nefraea breitet die Arme aus und genießt ihren Nachklang."
  },
  AvgDialog_131209_Content_80 = {
    Text = "Das silberne Licht strahlt aus deiner Hand, während du auf Nefraea zurennst."
  },
  AvgDialog_131209_Content_81 = {
    Text = "Unter dem heiligen blutigen Licht erstrecken sich unzählige Schatten auf dem schmutzigen Wandgemälde und stehen dir im Weg..."
  },
  AvgDialog_131209_Content_9 = {
    Text = "Wie war mein Gesang?"
  },
  AvgDialog_131210_Content_1 = {
    Text = "Ich hätte nie gedacht, dass du bei unserem Wiedersehen so elend aussehen würdest."
  },
  AvgDialog_131210_Content_2 = {Text = "Thais..."},
  AvgDialog_131210_Content_3 = {
    Text = "Tawil hat recht. Es ist in Ordnung, Schutzherr."
  },
  AvgDialog_131210_Content_4 = {
    Text = "Du hast gesagt, du würdest mich mitnehmen, um ein anderes Ende zu erleben. Ich glaube an dich, von Anfang bis Ende."
  },
  AvgDialog_131210_Content_5 = {
    Text = "Egal ob du hier bleibst oder an mir vorbeigehst, ich bin immer an deiner Seite."
  },
  AvgDialog_131211_Content_1 = {Text = "Kokon"},
  AvgDialog_131211_Content_10 = {
    Text = "So ein Erlebnis möchte ich nicht noch einmal haben..."
  },
  AvgDialog_131211_Content_11 = {
    Text = "Du bist dir nicht sicher, ob du das wirklich so meinst. Du ballst die Faust und gewöhnst dich wieder an den Körper, den du gerade mit „ N \" geteilt hast."
  },
  AvgDialog_131211_Content_12 = {
    Text = "Die Sicht wird allmählich klarer, du reibst dir den schmerzenden Kopf und gehst auf die dünne Gestalt zu, die am Bühnenrand kniet."
  },
  AvgDialog_131211_Content_13 = {
    Text = "Nefraea, dein Plan ist bereits......"
  },
  AvgDialog_131211_Content_14 = {Text = "Vorsicht"},
  AvgDialog_131211_Content_16 = {
    Text = "Als ob ein Faden sanft zieht, verlangsamt sich dein Schritt um einen Moment. Ein scharfer schwarzer Spinnenzahn streicht fast an deinen Augen vorbei und schneidet haarscharf an dir vorbei."
  },
  AvgDialog_131211_Content_17 = {
    Text = "Acht riesige, giftige Gliedmaßen zerreißen ihre Rückenbekleidung, schwingen in der Luft, verzerren und kämpfen. Nefraea scheint sich um all dies nicht zu kümmern."
  },
  AvgDialog_131211_Content_18 = {
    Text = "Die Fragmente des Dimensionstunnels schwirren um sie herum wie fallende Feuerwerkskörper. Ihre Tränen fallen und durchnässen das matte Spinnrad in ihrer Hand, das das Licht verloren hat."
  },
  AvgDialog_131211_Content_19 = {
    Text = "Der Dimensionstunnel ist verschwunden, du hast keine Chance mehr."
  },
  AvgDialog_131211_Content_2 = {Text = "...Hü..."},
  AvgDialog_131211_Content_20 = {
    Text = "Schicksal läuft auf seiner vorgesehenen Spur, Nefraea. Akzeptiere es."
  },
  AvgDialog_131211_Content_21 = {
    Text = "Gelegenheit?... Hehehehe..."
  },
  AvgDialog_131211_Content_22 = {
    Text = "Die dünne Silhouette zitterte vor Lachen und zog mit ihren giftigen Gliedern eine schreckliche Spur durch die Luft."
  },
  AvgDialog_131211_Content_23 = {
    Text = "Ich hatte nie eine Chance und brauchte auch nie eine."
  },
  AvgDialog_131211_Content_24 = {
    Text = "Freiheit, Kindheit, Familie, Liebe, Selbst... Das Schicksal hat uns alles genommen, ich werde niemals, niemals wie du sein und sein Gefangener."
  },
  AvgDialog_131211_Content_25 = {
    Text = "Nefraea erhob sich langsam und stellte ihren Körper in das dunkle, zerbrochene Spinnrad."
  },
  AvgDialog_131211_Content_26 = {
    Text = "Sieh gut hin, Arachne! Die Dinge, die du dir unendlich wünschst, aber nicht wagen kannst, werde ich für dich tun"
  },
  AvgDialog_131211_Content_27 = {
    Text = "Fast war der Wutschrei, in dem Nefraea's Körper scheinbar augenblicklich von unzähligen Dornen durchbohrt wurde. Blut floss aus ihrem Körper zurück und verband sich mit dem zerbrochenen Spinnrad, wie ein blutiger Netz."
  },
  AvgDialog_131211_Content_28 = {
    Text = "<Shake:@2—!>"
  },
  AvgDialog_131211_Content_29 = {
    Text = "Ein unermüdlicher, für Menschen unerträglicher hochfrequenter Aufschrei drang aus dem Kopf von Nefraea. Ihr Körper zitterte vor intensiven Schmerzen, während sich die dunkelvioletten Adernschlingen deutlich auf ihrem Körper abzeichneten."
  },
  AvgDialog_131211_Content_3 = {
    Text = "{Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131211_Content_30 = {
    Text = "Die Fragmente des Dimensionstunnels scheinen von etwas angezogen worden zu sein, sie hören auf zu zerstreuen und sammeln sich langsam zu dem aus Blut gewebten Netz. Das matte Spinnrad erstrahlt erneut im blutigen Glanz."
  },
  AvgDialog_131211_Content_31 = {
    Text = "Heh... Hahaha! <Big:<Shake:Wenn es keine Götter gibt, werde ich selbst zu einem!>>"
  },
  AvgDialog_131211_Content_32 = {
    Text = "Meine Geschichte... meine Bühne... wird niemals enden! Ich werde diesem Netz, das niemals hätte existieren sollen, Befreiung bringen... <Big:<Shake:<Red:Befreiung!!!>>>"
  },
  AvgDialog_131211_Content_33 = {
    Text = "In Nefraea's schmerzhaften Schreien erbebte das gesamte Schicksalstheater heftig. Die Marionetten auf der Bühne kippten, kollidierten, und die Fäden, die die Marionetten verbanden, waren durcheinander verwickelt..."
  },
  AvgDialog_131211_Content_34 = {
    Text = "Arachne blickte auf die Gestalt in der Nähe, die von der Stärke und dem Wahnsinn der Dimensionsplitter korrodiert wurde. In ihren tiefen, teichartigen Augen stieg ein trauriger Schimmer auf, so wie an dem Tag, an dem sie sich zum ersten Mal von sich selbst trennte."
  },
  AvgDialog_131211_Content_35 = {
    Text = "Ich habe versucht, dich von diesem Fluch zu befreien... Leider lag ich falsch, Nefraea."
  },
  AvgDialog_131211_Content_36 = {
    Text = "Fluch, dem wir nicht entkommen können, Käfig, aus dem wir niemals entkommen können..."
  },
  AvgDialog_131211_Content_37 = {
    Text = "Diese Fragmente... dieses Spinnrad..."
  },
  AvgDialog_131211_Content_38 = {
    Text = "Nefraea absorbiert die verbleibende Stärke im Dimensionstunnel! Sie... sie will sich zu einem Wick verwandeln!!"
  },
  AvgDialog_131211_Content_39 = {
    Text = "Ein leises Seufzen hallt in diesem wackligen Theater klar wider."
  },
  AvgDialog_131211_Content_4 = {
    Text = "<Shake:Ugh... hust, hust...>"
  },
  AvgDialog_131211_Content_40 = {
    Text = "Halt dich fest, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131211_Content_41 = {Text = "Was..."},
  AvgDialog_131211_Content_42 = {
    Text = "<Shake:Bumm—>"
  },
  AvgDialog_131211_Content_43 = {
    Text = "Kaum war die Stimme verklungen, riss das gesamte Theater plötzlich auseinander. Nefraea zerriss wütend die Fäden des Schicksals, und aus dem schrecklichen Riss verwoben sich die bunten Trümmer der Stadtgebäude mit der Dimension."
  },
  AvgDialog_131211_Content_44 = {
    Text = "Die Hauptbühne des Theaters zerbrach in mehrere Stücke, Fragmente von Vergangenheit, Zukunft und Gegenwart vermischen sich chaotisch auf der zerbrochenen Bühne und fügen sich zu einem Bild zusammen, das du nicht verstehen kannst."
  },
  AvgDialog_131211_Content_45 = {
    Text = "Arachne...... dein Netz......"
  },
  AvgDialog_131211_Content_46 = {
    Text = "Arachne in der Hand dreht sich der Spinnrad schnell, die unermesslichen Dimension Glut strömen aus Arachne's Körper, folgen den Fäden auf dem Spinnrad und füllen die zerbrochenen Lücken im Schicksalsnetz, um das Schicksal der Bühne vor dem Zusammenbruch zu bewahren."
  },
  AvgDialog_131211_Content_47 = {
    Text = "Unter dem Zug des Fadens stehst du mühsam auf."
  },
  AvgDialog_131211_Content_48 = {
    Text = "Absorbieren Sie die verstreute Stärke von Ihm und verändern Sie die Richtung des gesamten Schicksalsnetzes... Sie sind nicht sein Fragment und können solchen Druck nicht ertragen. Sie müssen nicht so schmerzhaft verschwinden, Nefraea."
  },
  AvgDialog_131211_Content_49 = {
    Text = "Schmerz? Nein, ich bin sehr glücklich, Schwester! In den unzähligen Jahren im Abgrund habe ich jede Sekunde davon geträumt, dass dieser Tag kommt."
  },
  AvgDialog_131211_Content_5 = {
    Text = "Was ist passiert..."
  },
  AvgDialog_131211_Content_50 = {
    Text = "Genau diese Illusion hat mich bis heute durchhalten lassen..."
  },
  AvgDialog_131211_Content_51 = {
    Text = "Nefraea's wahnsinniges Lachen hallt im zerbrochenen Raum des Theaters wider. Sie hebt den Kopf und absorbiert gierig das düstere Licht, das aus den Trümmern strahlt."
  },
  AvgDialog_131211_Content_52 = {
    Text = "Der in den Schlaf gefallene Gott, der Apostel, dessen Schicksal gestohlen wurde... hihihihi... Das ist in Ordnung, das kann mich nicht aufhalten. Wenn die Götter keine Gnade bringen können, dann werde ich es für sie tun!"
  },
  AvgDialog_131211_Content_53 = {
    Text = "Rächer des Schicksals, betretet die Bühne! <Red:Dieser Akt gehört euch!>"
  },
  AvgDialog_131211_Content_54 = {
    Text = "Nefraea hob plötzlich die Hand. Unendliches schwarzes Klebrig strömte aus Nefraea heraus und spannte ein schwarzes Netz in der Leere dieses Theaters."
  },
  AvgDialog_131211_Content_55 = {
    Text = "Unzählige Grolle, einst vom Schicksal verworfen, nehmen physische Gestalt an. Sie kriechen in einer überwältigenden Flut entlang des gewaltigen Netzes und stürzen auf dich zu."
  },
  AvgDialog_131211_Content_56 = {
    Text = "Arachne, auf uns...!"
  },
  AvgDialog_131211_Content_57 = {
    Text = "Du entdeckst plötzlich, dass ein schwarzer Faden, den du sehen kannst, vage von Arachne erscheint."
  },
  AvgDialog_131211_Content_58 = {
    Text = "Du hebst den Kopf und siehst, wie ein ebenso verschwommener schwarzer Faden von dir selbst, von jeder Bühne und von jedem Körper der Puppen ausgeht und zu dem Spinnrad in den Händen von Nefraea führt."
  },
  AvgDialog_131211_Content_59 = {
    Text = "Sei gegrüßt, Arachne! Segne dich, Göttin des Schicksals"
  },
  AvgDialog_131211_Content_6 = {
    Text = "Ein starkes Betäuben und Magenkrämpfe sind die Überreste der Freude. Du kämpfst gegen die Übelkeit an und krabbelst langsam auf."
  },
  AvgDialog_131211_Content_60 = {
    Text = "Komm, zieht eure Klingen, Soldaten! Kämpft für unser Schicksal"
  },
  AvgDialog_131211_Content_61 = {
    Text = "Fräulein Arachne, akzeptiere dein Schicksal... Widerstehe nicht länger sinnlos..."
  },
  AvgDialog_131211_Content_62 = {
    Text = "Hab keine Angst, mein Lieber. Deine Befreiung steht kurz bevor, bald, bald..."
  },
  AvgDialog_131211_Content_63 = {
    Text = "Nefraea's düstere Spinnrad dreht sich wahnsinnig, die Puppen auf der Bühne verwandeln sich in Schatten im Abgrund und treten, an den Fäden gezogen, auf das neu gewebte schwarze Netz."
  },
  AvgDialog_131211_Content_64 = {
    Text = "Arachne schloss langsam die Augen und ihre Hand, die die Fäden hielt, zitterte leicht vor Schmerz."
  },
  AvgDialog_131211_Content_65 = {
    Text = "Nefraea, sie können dir nicht helfen, der Gott zu werden, der das gesamte Schicksal zerstören kann... Was du tust, wird nur dazu führen, dass sie erneut in einen schmerzhaften Untergang geraten."
  },
  AvgDialog_131211_Content_66 = {
    Text = "Was spielt das für eine Rolle? Rache, außer Rache verlangen wir nichts! Oder, Kinder des Schicksals?"
  },
  AvgDialog_131211_Content_67 = {
    Text = "<Shake:Heh... hahaha!>"
  },
  AvgDialog_131211_Content_68 = {
    Text = "Ein scharfer, majestätischer, durchdringender Lachen ertönt aus dem endlosen schwarzen Netz, wie ein schmerzhaftes Chorgesang."
  },
  AvgDialog_131211_Content_69 = {
    Text = "Die verlassenen Schicksale lachen verrückt und heulen, während sie sich vor Nefraea aufstellen."
  },
  AvgDialog_131211_Content_7 = {
    Text = "Das Bewusstsein des Apostels hat das Spinnrad verlassen und die Verbindung zu den Göttern verloren, jetzt ist es völlig zerstört. Die Kraft des Plasmids ist ebenfalls zur Ruhe gekommen."
  },
  AvgDialog_131211_Content_70 = {
    Text = "Jetzt ist die Tür des Abgrunds vollständig geöffnet. Komm, Arachne, sieh dir das Schicksal an, das du mit deinen eigenen Händen geschaffen hast, sieh dir deine geliebten Kinder an"
  },
  AvgDialog_131211_Content_71 = {
    Text = "Seht ihren Schmerz, ihre Verzweiflung... Schaut sie an und tötet sie dann erneut"
  },
  AvgDialog_131211_Content_72 = {
    Text = "Sieh, wie das Schicksal alles in meinen Händen wendet, zerstört! ... Schau mich an und werde zu dem Gott, der das Ende bringt"
  },
  AvgDialog_131211_Content_73 = {
    Text = "Die Fragmente der Dimension, durchdrungen von der Kraft der Götter und dem Willen der Raserei, dringen Stück für Stück in den Körper von Nefraea ein, während das Blut unaufhörlich in Nefraea's Spinnrad strömt."
  },
  AvgDialog_131211_Content_74 = {
    Text = "Ihr Gesicht verzerrt sich vor Qual, doch ihr Lachen wird nur noch rasender."
  },
  AvgDialog_131211_Content_75 = {
    Text = "Sie blickt voller Erwartung auf die zerbrochene Bühne, wie ein Dramatiker, der darauf wartet, sein Werk zum ersten Mal aufzuführen."
  },
  AvgDialog_131211_Content_76 = {
    Text = "Der Abgrund des Schicksals ist bereits auf dieser Bühne erschienen... Nefraea opfert sich selbst."
  },
  AvgDialog_131211_Content_77 = {
    Text = "Sie will alles hier, einschließlich uns, zu ihren Puppen machen. Sie möchte diese Person, den Gott, werden. Sie... möchte das Schicksal selbst werden."
  },
  AvgDialog_131211_Content_78 = {
    Text = "Arachnes ruhige Stimme schien zu einer Person zu gehören, die nie im Stück war. Die zurückgeholten Dimension Glut schwebten wie feiner Sand um ihre Fingerspitzen, unaufhörlich."
  },
  AvgDialog_131211_Content_79 = {
    Text = "Ihr Spinnrad drehte sich mühsam und hielt mit aller Kraft die Schicksale aufrecht, die von Nefraea zerstört wurden, und verhinderte, dass die schwarzen Fäden in Nefraes Hände flossen."
  },
  AvgDialog_131211_Content_8 = {
    Text = "Du hast eine großartige Aufführung abgeschlossen."
  },
  AvgDialog_131211_Content_80 = {
    Text = "Die Glut der Dimension wurde zurückgeholt, heute brauche ich mir keine Sorgen mehr zu machen."
  },
  AvgDialog_131211_Content_81 = {
    Text = "Bitte helfen Sie mir, kommen Sie ihr so nah wie möglich. Nefraea's Spinnrad wird aufhören sich zu drehen, dieses fehlerhafte Schicksal werde ich mit Ihnen korrigieren."
  },
  AvgDialog_131211_Content_82 = {
    Text = "Bitte hilf mir... für das Schicksal dieser Verlassenen Erlösung zu bringen."
  },
  AvgDialog_131211_Content_9 = {
    Text = "Puh... ich kann es wirklich nicht glauben, dass das gerade aus meinem Mund gekommen ist."
  },
  AvgDialog_131212_Content_1 = {
    Text = [[
Zur selben Zeit
am anderen Ende der Stadt]]
  },
  AvgDialog_131212_Content_10 = {
    Text = "Die Nummer sechs wurde vom Herzog aus dem Stall des Anwesens ausgewählt und an die Rennbahn geschickt. Diesmal wird die Nummer sechs auf jeden Fall gewinnen. Glaub mir, setze auf die Nummer sechs, das kann nicht schiefgehen"
  },
  AvgDialog_131212_Content_11 = {
    Text = "Die Geräusche im U-Bahn summen und bilden einen lebhaften Bach, während Arachne still aus dem Fenster auf die Lichter schaut, die näher kommen und wieder verschwinden, und lächelnd ihren Puppen zuhört, die über Aufführungen, Pferderennen und Hochzeiten plaudern."
  },
  AvgDialog_131212_Content_12 = {
    Text = "Sie bewegt das Spinnrad in ihrer Hand sanft. In den unzähligen komplizierten Fäden genießt sie diesen Moment der Ruhe."
  },
  AvgDialog_131212_Content_13 = {
    Text = "Meister, unser Ziel ist bald erreicht. Die Kutsche für den Umstieg ist bereits bereit, und unsere Schwestern warten dort auf Sie."
  },
  AvgDialog_131212_Content_14 = {
    Text = "Braves Kind."
  },
  AvgDialog_131212_Content_15 = {
    Text = "Sie blickte ein wenig wehmütig auf die Puppen, die weiterhin auf der Bühne spielten, wie ein Zuschauer, der sich nicht von seinem Platz lösen kann."
  },
  AvgDialog_131212_Content_16 = {
    Text = "Erinnerst du dich, wie lange wir schon nicht mehr das Theater verlassen haben?"
  },
  AvgDialog_131212_Content_17 = {
    Text = "Seit dem Tag, an dem ich zur kalten Spinne wurde, bin ich immer an Ihrer Seite gewesen und habe Sie nie verlassen. Bis jetzt... Fünfzig Jahre? Oder sechzig Jahre? Ich kann mich auch nicht mehr genau erinnern."
  },
  AvgDialog_131212_Content_18 = {
    Text = "Aber dieses Mal ist die Zeit, die wir das Theater verlassen haben, schon etwas zu lange."
  },
  AvgDialog_131212_Content_19 = {
    Text = "Das verdanke ich Nefraea. Wäre sie nicht gekommen, hätte ich nicht die Gelegenheit gehabt, so lange vor dem Theater zu verweilen."
  },
  AvgDialog_131212_Content_2 = {
    Text = "Dieser Herr, bitte zeigen Sie Ihre Fahrkarte vor."
  },
  AvgDialog_131212_Content_20 = {
    Text = "Im Einklang mit den Aktionen des Schutzherrn haben wir in den letzten Tagen Hunderte von Dienern aus dem Abgrund erlegt. Nachdem wir die „Erinnerung\" gerettet haben, sollten wir zum Theater zurückkehren."
  },
  AvgDialog_131212_Content_21 = {
    Text = "Beim nächsten Mal, wenn sich die Gelegenheit ergibt, weiß ich nicht, wann das sein wird..."
  },
  AvgDialog_131212_Content_22 = {
    Text = "Es scheint, als würde Arachne's Gedanken wahrgenommen, das Licht außerhalb der U-Bahn wird schwächer. Sie starrt aus dem dunklen Fenster und sucht in den Erinnerungen unzähliger Zivilisationen nach den gewöhnlichen Erinnerungen an sich selbst."
  },
  AvgDialog_131212_Content_23 = {
    Text = "Die Zeiger der Uhr drehten sich zwei Sekunden. Der Herr der Stadt bemerkte, dass die klaren Gespräche in der U-Bahn in dem Moment verschwanden, als der Wagen in die Dunkelheit eintauchte."
  },
  AvgDialog_131212_Content_24 = {
    Text = "Herr, hier scheint es ein bisschen..."
  },
  AvgDialog_131212_Content_25 = {Text = "Kara—"},
  AvgDialog_131212_Content_26 = {
    Text = "Die Zofe spritzte ihr kaltes Blut auf das ruhige Gesicht von Arachne und verbreitete einen Duft wie von Schwertlilien."
  },
  AvgDialog_131212_Content_27 = {
    Text = "Das Licht draußen ging an. Arachne sah den Körper der Zofe, der durchtrennt wurde, das Klinge, das durch ihren Körper auf sie zukam, und hinter der Klinge die Puppen, die wie ein Rudel Tiere auf sie zustürmten."
  },
  AvgDialog_131212_Content_28 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131212_Content_29 = {
    Text = "Das Bremssystem gab ein müdes Reibegeräusch von sich, und der aufkommende Wind hob die Haare einer anderen Zofe an."
  },
  AvgDialog_131212_Content_3 = {
    Text = "Wurde nicht schon beim Betreten des Bahnhofs überprüft? So wird das Geld der Steuerzahler verschwendet..."
  },
  AvgDialog_131212_Content_30 = {
    Text = "Ah! Angekommen"
  },
  AvgDialog_131212_Content_31 = {
    Text = "Die Tür öffnete sich, aber die geschäftige Menschenmenge erschien nicht. Nur das Blut, das einen starken metallischen Geruch hatte, floss aus jedem Türspalt und glich einem stummen Ensemble."
  },
  AvgDialog_131212_Content_32 = {
    Text = "Auf der blutigen Straße, die diesen Begleitklang begleitet, trat Arachne langsam aus dem Wagen. Ihre Kleidung war makellos, ihr Spinnrad drehte sich weiterhin, unermüdlich."
  },
  AvgDialog_131212_Content_33 = {Text = "Das ist..."},
  AvgDialog_131212_Content_34 = {
    Text = "Ein großartiges interaktives Theaterstück. Als Zuschauer und Schauspieler ist das Erlebnis tatsächlich viel spannender als das des Autors."
  },
  AvgDialog_131212_Content_35 = {
    Text = "Sie betrachtet die Dienerin vor ihr, ihr Ausdruck unergründlich."
  },
  AvgDialog_131212_Content_36 = {
    Text = "Meine Zofe begleitet mich nun schon seit vielen Jahren, ich berühre selten die Fäden ihres Schicksals."
  },
  AvgDialog_131212_Content_37 = {
    Text = "In diesem eintönigen Theater sind sie das wenige lebendige Leben."
  },
  AvgDialog_131212_Content_38 = {
    Text = "Du hast heute zwei meiner Zofen getötet. Die Zerstörung des Schicksals wird ihren Preis haben, Nefraea."
  },
  AvgDialog_131212_Content_39 = {
    Text = "Hehehehe...<Shake:HaHaHaHa!>Wie edel, Arachne."
  },
  AvgDialog_131212_Content_4 = {
    Text = "Hey, Charlie, wo ist meine Brosche hin?"
  },
  AvgDialog_131212_Content_40 = {
    Text = "Wie Butter, die in einen heißen Zinnkessel fällt, beginnt der Körper der Zofe zu schmelzen. Unter der kochenden, verunreinigten schwarzen, klebrigen Flüssigkeit lacht das Gesicht, das genau wie das von Arachne ist, herzlich."
  },
  AvgDialog_131212_Content_41 = {
    Text = "„Sieh, ich bin der Manipulator des Schicksals, der gewissenhafte Vollstrecker! Ich werde die richtigen Schicksale auswählen und alle Fehler in die Leere der Tiefe senden...\""
  },
  AvgDialog_131212_Content_42 = {
    Text = "Du bist mein Idol, mein Glauben, liebe Schwester. Ich spiele nur die Rolle, die du mir gegeben hast."
  },
  AvgDialog_131212_Content_43 = {
    Text = "Wie ist es, bin ich als Lernender noch kompetent?"
  },
  AvgDialog_131212_Content_44 = {
    Text = "Arachne blickte still in die Augen, die sie anstarrten. Sie waren leidenschaftlich, hell und voller Erwartung, als ob sie nur von einem Mädchen stammen würden, das auf das Lob ihrer Schwester wartete."
  },
  AvgDialog_131212_Content_45 = {
    Text = "Bahnsteig, Treppenaufgang, Säulenhalle, im Tunnel... Während sie sprach, tauchten unzählige Schatten an jedem Ort auf, den sie sich vorstellen konnte."
  },
  AvgDialog_131212_Content_46 = {
    Text = "Der trübe Atem der Schatten ist eng miteinander verbunden und versammelt sich in Nefraea's Händen, wie ein riesiges Netz, das sich um Arachne zieht."
  },
  AvgDialog_131212_Content_47 = {
    Text = "Der Mundwinkel von Arachne hebt sich sanft."
  },
  AvgDialog_131212_Content_48 = {
    Text = "Ich habe nie gedacht, dass jemand versuchen würde, mich mit einem Netz zu fangen."
  },
  AvgDialog_131212_Content_49 = {
    Text = "Hast du schon einmal eine Seide gesehen, Schwester? Das ist ein Insekt aus dem fernen Osten, das den ganzen Tag nichts tut, außer ständig zu fressen und Fäden zu spinnen... und dann wartet es darauf, dass die Fäden einen Kokon bilden und es darin gefangen hält."
  },
  AvgDialog_131212_Content_5 = {
    Text = "Hast du nicht gesagt, dass du die Kleidung anziehen sollst, bevor du das Haus verlässt?"
  },
  AvgDialog_131212_Content_50 = {
    Text = "Fast alle deine Diener sind in den verschiedenen Ecken dieser Stadt und in diesem Zug verschwunden. Sie haben dich begleitet und lange Jahre in der Leere verbracht."
  },
  AvgDialog_131212_Content_51 = {
    Text = "Du hast ihnen ein Schicksal gegeben, das nicht hätte geschehen sollen. Das Schicksal ist unwiderruflich, Nefraea."
  },
  AvgDialog_131212_Content_52 = {
    Text = "Du meinst also, ihr Ende sollte sein, brav in diesem dunklen Abgrund zu verweilen und in der endlosen Zeit zu versinken... richtig, edler Herrscher des Schicksals?"
  },
  AvgDialog_131212_Content_53 = {
    Text = "Nefraea schüttelte lachend den Kopf."
  },
  AvgDialog_131212_Content_54 = {
    Text = "Ich liebe sie mehr, als du denkst, Schwester. Aber sie haben mir gesagt, dass sie den Tod ohne zu zögern annehmen würden, wenn er sie vor dem Schicksal bewahrt, erneut gefangen zu werden..."
  },
  AvgDialog_131212_Content_55 = {
    Text = "Nach diesem Massaker in der U-Bahn, wie viel von den Glutstücken, die du zur Korrektur des Schicksals verwendet hast, bleibt noch übrig?"
  },
  AvgDialog_131212_Content_56 = {
    Text = "Nefraea hob ihren schwarzen Spinnrad mit einer prahlerischen Geste. Unzählige Fäden, die von der Bühne der Stadt ausstrahlen, sind mit dem stillstehenden Spinnrad verbunden."
  },
  AvgDialog_131212_Content_57 = {
    Text = "Die Schicksalsfäden dieser Stadt liegen in meinen Händen. Ich habe nicht die Fähigkeit, sie zu kontrollieren, viele interessante Dinge kann ich nicht tun, wie bedauerlich..."
  },
  AvgDialog_131212_Content_58 = {
    Text = "Aber zum Glück erfordert die Reparatur unzählige Glut, während die Verschmutzung nicht nötig ist."
  },
  AvgDialog_131212_Content_59 = {
    Text = "Egal wie ich einfach loslasse... dein Theater, deine Bühne wird zur perfekten Brutstätte des Chaos, so wie... so wie der Ort, an dem ich unzählige Jahre verbracht habe."
  },
  AvgDialog_131212_Content_6 = {
    Text = "Mein Gott ... Ich habe mich einen ganzen Monat auf die heutige Feier vorbereitet! Wenn ich diese Brosche nicht hätte, wäre dieses Kleid doch nichts anderes als ein Tuch für einen Sarg ..."
  },
  AvgDialog_131212_Content_60 = {
    Text = "Und du kannst nur zusehen, wie all das passiert. Du kannst nichts ändern, du kannst dich nicht wehren..."
  },
  AvgDialog_131212_Content_61 = {
    Text = "Nefraea trat vor Arachne und streichelte sorgfältig ihr Gesicht, dessen Emotionen nicht zu erkennen waren."
  },
  AvgDialog_131212_Content_62 = {
    Text = "Was soll ich tun, meine Schwester... Soll sie brav auf mich hören oder mit mir zusammen die Welt bewundern, wie sie sich in die Hölle verwandelt?"
  },
  AvgDialog_131212_Content_63 = {
    Text = "Du bist ein unvollständiges Schicksal, das das Schicksal der ganzen Stadt verschmutzt, du bist nicht in der Lage dazu..."
  },
  AvgDialog_131212_Content_64 = {
    Text = "Ein Geräusch des reißenden Fadens ertönte neben Arachne. Sie hob den Kopf und in ihrem Blick auf Nefraea lag ein Hauch von Trauer, der den Zuschauern gehörte."
  },
  AvgDialog_131212_Content_65 = {
    Text = "... du hast auch die „Erinnerung \" getötet."
  },
  AvgDialog_131212_Content_66 = {
    Text = "Es ist die Akzeptanz. Romantik, Güte, Erinnerungen... Ich habe einfach diese Dinge, die du weggeworfen hast, einzeln wieder in ihr Zuhause zurückgeholt."
  },
  AvgDialog_131212_Content_67 = {
    Text = "Nefraea stand auf und drehte sich erfreut im Kreis."
  },
  AvgDialog_131212_Content_68 = {
    Text = "Ein vollständiges Ich, ein vollständiger Rächer... Gefällt es dir, Schwester?"
  },
  AvgDialog_131212_Content_69 = {
    Text = "Du kannst das Chaos, nach dem du dich sehnst, bereits bekommen... Worauf wartest du dann noch?"
  },
  AvgDialog_131212_Content_7 = {
    Text = "Die Tänze des Schwanenballetts sind in der Tat bezaubernd, aber wenn es zeitliche Konflikte gibt, würde ich mich definitiv für „Der Smaragdgarten\" entscheiden."
  },
  AvgDialog_131212_Content_70 = {
    Text = "Ah, nein, nein, nein, gute Schwester, ich bin noch weit, weit von dem entfernt, was ich will."
  },
  AvgDialog_131212_Content_71 = {
    Text = "Ich werde dein Spinnrad gut bewachen, die Dimensionen der Glut, die du wünschst, werden unerschöpflich sein, und die Bühnen, die du liebst, werde ich keine einzige zerstören."
  },
  AvgDialog_131212_Content_72 = {
    Text = "Und was ich von dir möchte, ist nur, mir einen ganz kleinen, ganz kleinen Gefallen zu tun."
  },
  AvgDialog_131212_Content_73 = {
    Text = "Nefraea trat vor Arachne und streichelte das ständig drehende Spinnrad in ihren Händen, während ihr Atem vor aufgeregter Vorstellung schneller wurde."
  },
  AvgDialog_131212_Content_74 = {
    Text = "Überlass es dem Hüter, meine liebe Schwester, nur der Hüter kann mir das bringen, was ich wirklich will."
  },
  AvgDialog_131212_Content_75 = {
    Text = "Du weißt genau, dass %player% ein Fragment des Höchsten ist. Wir können {Male=his,Female=her} Schicksal nicht befehlen..."
  },
  AvgDialog_131212_Content_76 = {
    Text = "Ein schimmerndes, grünes Licht strahlt aus dem schwarzen Spinnrad in Nefraea's Hand. Im Lichtschein erscheint ein geheimes, trübes Faden in Arachne's Sichtfeld."
  },
  AvgDialog_131212_Content_77 = {
    Text = "Das ist... <Shake:der Schicksalsfaden des Schutzherrn?!>"
  },
  AvgDialog_131212_Content_78 = {
    Text = "<Shake:Heh...> <Big:<Shake:HAHAHAHA!>> Das ist das erste Mal, dass ich deine Stimme zittern höre. Nun, Schwester? Ist es nicht berauschend?!"
  },
  AvgDialog_131212_Content_79 = {
    Text = "Im Abgrund wurde der Wille des Gottes, verkörpert durch den Apostel, in diesem Spinnrad aufgenommen und wurde zu seinem Wick... Es ist genau dieses Licht, das den Abgrund erhellt und uns das einzige Licht bringt."
  },
  AvgDialog_131212_Content_8 = {
    Text = "Die vielschichtigen Charaktere und die Erzählweise über verschiedene Zeiten und Räume, welche faszinierenden und komplexen Techniken! Der Aufstieg und Fall der königlichen Gärten ist wahrlich nicht mit diesen klischeehaften Handlungen zu vergleichen..."
  },
  AvgDialog_131212_Content_80 = {
    Text = "Mit unserer Macht und der Führung des Apostels <Big:liegt selbst das Schicksal eines göttlichen Fragments in UNSEREN Händen!>"
  },
  AvgDialog_131212_Content_81 = {
    Text = "Das ist nicht der richtige Weg des Schicksals, Nefraea... Niemand kann dem Schicksal widerstehen."
  },
  AvgDialog_131212_Content_82 = {
    Text = "Bald wird es geschehen, Schwester. Solange die Macht der drei Entitäten berührt wird, kann der Apostel wieder auferstehen! Er wird den Zugang zu den Göttern erneut öffnen und die Stimmen der Gläubigen in den ewigen Tempel tragen"
  },
  AvgDialog_131212_Content_83 = {
    Text = "Die Höchste Gottheit wird erwachen... und du wirst nie wieder ein qualvolles Schicksal beschneiden oder ein Netz weben müssen, das zum Zerbrechen bestimmt ist."
  },
  AvgDialog_131212_Content_84 = {
    Text = "Nefraea atmete tief ein, und eine Träne fiel von ihrem begeisterten Gesicht."
  },
  AvgDialog_131212_Content_85 = {
    Text = "Ihre Stimme zitterte vor dem wunderbaren Traum, der bevorstand. Die tanzenden Tränenaugen blickten tief auf das ruhige Gesicht von Arachne."
  },
  AvgDialog_131212_Content_86 = {
    Text = "Hör auf, solche schmerzhaften Widerstände zu leisten, Schwester."
  },
  AvgDialog_131212_Content_87 = {
    Text = "Komm, komm zu mir, lass uns gemeinsam sein Erwachen begrüßen und allen Bühnen ihr verdientes Ende bringen!..."
  },
  AvgDialog_131212_Content_9 = {
    Text = "Ha, wenn du Nummer acht kaufst, machst du einen großen Fehler! Ich sage dir im Geheimen, ich habe Insider-Informationen, heute wird jemand Gift in das Futter von Nummer acht mischen."
  },
  AvgDialog_131213_Content_1 = {
    Text = "Improvisationskomödie"
  },
  AvgDialog_131213_Content_10 = {
    Text = "Jetzt begrüßt du einen neuen Gläubigen——"
  },
  AvgDialog_131213_Content_100 = {
    Text = "Ich leihe mir „ N \"s Druckbefehl... <color=#98918C>Ich besetze die Hälfte von %player%s Bewusstsein</color>... aber ein Name ist gerade das Unwichtigste."
  },
  AvgDialog_131213_Content_101 = {
    Text = "Es ist wichtig, dass die Zusammenarbeit angenehm ist, Arachne."
  },
  AvgDialog_131213_Content_102 = {
    Text = "<Shake:Ihr... ihr alle... ihr wusstet es von Anfang an...>"
  },
  AvgDialog_131213_Content_103 = {
    Text = "Der schwache Blick von Nefraea wanderte von Arachne zu deinem Gesicht. Du kostest gierig den endlosen Groll und Schmerz in diesem Blick. Ah, wie berauschend der Duft ist..."
  },
  AvgDialog_131213_Content_104 = {
    Text = "Schau dir das gut an, meine liebe Nefraea, der Unfugmacher, der aus dem Nichtigkeitsland geschlüpft ist."
  },
  AvgDialog_131213_Content_105 = {
    Text = "Dein Spiel bereitet mir Freude. Ein Hauch des Bewusstseins von Toguwaibo, ein Fragment, das von Toguwaibo gefallen ist, nur ihre Begegnung kann die Macht des Plasmids vollständig entfalten und mir die Gelegenheit geben, dieses bisher nie erlebte Glück zu erfahren..."
  },
  AvgDialog_131213_Content_106 = {
    Text = "Wenn es möglich wäre, würde ich so gerne weiterspielen wie jetzt, dieser Spaß würde mir eine ganze Woche reichen..."
  },
  AvgDialog_131213_Content_107 = {
    Text = "Der Hals zittert. Du seufzt voller Bedauern."
  },
  AvgDialog_131213_Content_108 = {
    Text = "Es ist wirklich schade, wenn diese Person erneut erwacht, wird dieses majestätische Paradies von mir verschwinden."
  },
  AvgDialog_131213_Content_109 = {
    Text = "Also, leider... muss der Höhepunkt enden. Schau nach oben, Liebes. Egal was geschieht, wir können uns zumindest auf eine Sache in dieser Geschichte des Schicksals einigen..."
  },
  AvgDialog_131213_Content_11 = {
    Text = "Die Fäden des Schicksals ziehen deinen Körper. Du kreuzt deine zehn Finger, legst deine Hände sanft auf die Brust und kniest langsam vor dem Spinnrad nieder."
  },
  AvgDialog_131213_Content_110 = {
    Text = "Du beugst dich herunter, greifst sanft unter Nefraea's eleganten Kinn und lehnst dich an ihr Ohr."
  },
  AvgDialog_131213_Content_111 = {
    Text = "Zerstörung ist das schönste Bild in diesem Universum, nicht wahr, mein Lieber?"
  },
  AvgDialog_131213_Content_112 = {
    Text = "Ein klarer, mit unendlicher Freude und Bedauern erfüllter Fingerschnipp ertönte vor Nefraea."
  },
  AvgDialog_131213_Content_113 = {Text = "Boom—"},
  AvgDialog_131213_Content_114 = {
    Text = "Im Zittern der Dimension zitterte der Kanal, der mit dem Gott verbunden war, plötzlich. Unzählige Risse kletterten über die illusorische Oberfläche des Kanals..."
  },
  AvgDialog_131213_Content_115 = {
    Text = "<Big:<Shake:NEEEIN!!—>>"
  },
  AvgDialog_131213_Content_116 = {
    Text = "Nefraea schrie und stürzte auf den Gang zu, und als ihre Hand nur noch wenige Zoll vom Gang entfernt war, zerbrach er und stürzte ein."
  },
  AvgDialog_131213_Content_117 = {
    Text = "Zahlreiche illusorische Fragmente schweben vor Nefraea, wie ein zerbrochenes Kaleidoskop, während die billigen bunten Papierstücke durch die Luft wirbeln und über Nefraes Gesicht streifen."
  },
  AvgDialog_131213_Content_118 = {
    Text = "Du nimmst den nicht existierenden Zylinder ab, drehst ihn zwei Mal in der Luft und verbeugst dich vor dem ratlosen Rücken von Nefraea."
  },
  AvgDialog_131213_Content_119 = {
    Text = "Schicksal, was für eine interessante Bühne... Der dritte Akt der Geschichte ist damit zu Ende. Dein Applaus und dein Jubel bereiten mir unermessliches Vergnügen."
  },
  AvgDialog_131213_Content_12 = {
    Text = "Ich... der sehnsüchtige Apostel... ich bin... Ihr treuester Gläubiger des höchsten Gottes."
  },
  AvgDialog_131213_Content_120 = {
    Text = "Viel Spaß beim Zuschauen, liebe Nefraea."
  },
  AvgDialog_131213_Content_121 = {
    Text = "In den herzzerreißenden Schreien von Nefraea zerbricht das Bewusstsein des Apostels mit dem Riss des Durchgangs. Mit dem letzten Lächeln der Freude fällst du direkt auf die Bühne."
  },
  AvgDialog_131213_Content_13 = {
    Text = "Deine Luftröhre und Gliedmaßen haben ihr eigenes Schicksal. Sie gehören nicht mehr dir, und du versuchst nicht mehr vergeblich, sie zurückzuerobern."
  },
  AvgDialog_131213_Content_14 = {
    Text = "Kontrolliere nicht. Verstehe nicht. Genieße sie. Der Weg der Freude liegt darin..."
  },
  AvgDialog_131213_Content_15 = {
    Text = "Schau, Schwester! Was für einen herausragenden Schauspieler du herangezogen hast!"
  },
  AvgDialog_131213_Content_16 = {
    Text = "Arachne sitzt aufrecht im Zuschauerraum, während das Spinnrad in ihrer Hand mit jener ewigen Frequenz dreht. Sie blickt still auf die dunklen Licht- und Schattenwürfe der Laterne auf der Bühne, als ob sie nur eine Person wäre, die die Etikette einhält."
  },
  AvgDialog_131213_Content_17 = {
    Text = "Mein lieber Apostel... unsere Gläubigen haben dir das Opfer dargebracht, das du dir am sehnlichsten wünschst."
  },
  AvgDialog_131213_Content_18 = {
    Text = "Die dunkle Spindel bricht in einem plötzlichen Ausbruch hervor und verstreut trübes, zähes Licht in jeden Winkel der Bühne."
  },
  AvgDialog_131213_Content_19 = {Text = "Uff!!..."},
  AvgDialog_131213_Content_2 = {
    Text = "Tippe, tippe, tippe."
  },
  AvgDialog_131213_Content_20 = {
    Text = "Pain trifft dich ohne Vorwarnung. Er trifft nicht dein Fleisch oder deine Organe, sondern bricht aus den tiefsten Winkeln deiner Psychischen Dimension hervor—vom Sitz deiner Seele selbst."
  },
  AvgDialog_131213_Content_21 = {
    Text = "Ein gewaltiges Biest manifestiert sich in dir. Es kämpft und brüllt, seine massive Gestalt dehnt sich rasend in dir aus."
  },
  AvgDialog_131213_Content_22 = {
    Text = "Das Biest füllt deinen gesamten Körper aus und zerquetscht jedes Organ. Es dehnt sich weiter aus, tobt, um durch deine Haut zu brechen. Der intensive, überwältigende Druck lässt dich beinahe das Bewusstsein verlieren..."
  },
  AvgDialog_131213_Content_23 = {
    Text = "Hah... <Big:<Shake:AAAARGH!!—>>"
  },
  AvgDialog_131213_Content_24 = {
    Text = "In deinem herzzerreißenden Schrei dringen drei schwach erkennbare Atemzüge aus dem leidenden Körper und schweben zu dem Spinnrad, das in dunklem Licht schimmert."
  },
  AvgDialog_131213_Content_25 = {
    Text = "Druckbefehl konvergiert ins Licht wie reiner Brennstoff, der ins Feuer gegossen wird. Trübe Flammen brechen hervor und brennen heftig im Ring der Spindel. Der Glanz der Latern steigt und erleuchtet die gesamte Dimension."
  },
  AvgDialog_131213_Content_26 = {
    Text = "<Shake:Hah... Hah...>"
  },
  AvgDialog_131213_Content_27 = {
    Text = "Ach, was für ein bedauerliches Schicksal, unser treuer kleiner Gläubiger..."
  },
  AvgDialog_131213_Content_28 = {
    Text = "Nefraea kam an deine Seite und streichelte mit besorgtem Gesichtsausdruck deine von Schweiß feuchte Wange."
  },
  AvgDialog_131213_Content_29 = {
    Text = "Es ist in Ordnung, {Male=Mr.,Female=Miss} Schutzherr. Siehst du? Unser Apostel hat bereits Seine Gestalt offenbart..."
  },
  AvgDialog_131213_Content_3 = {
    Text = "Die Fäden des Schicksals ziehen sanft, die Sohlen der Puppe prallen auf die Bühne und erzeugen einen klaren Klang."
  },
  AvgDialog_131213_Content_30 = {
    Text = "Du hebst schmerzhaft den Kopf. Das Licht des Spinnrades beginnt sich zu versammeln, und eine sich verwandelnde Nichtigkeit erscheint über dem Licht."
  },
  AvgDialog_131213_Content_31 = {
    Text = "Sie haben kein Gesicht und keine Gestalt. Sie sind der treue Herold des Göttlichen, der in die Leere blickt, hin zum schlummernden Gott."
  },
  AvgDialog_131213_Content_32 = {
    Text = "Ihr Starren ist eine Einladung. Unter diesem unverwandten Blick nimmt eine Treppe, die zum Ruheort des Gottes führt, langsam Gestalt an..."
  },
  AvgDialog_131213_Content_33 = {
    Text = "<Shake:Es hat funktioniert... es hat funktioniert!> Der Durchgang zur Höheren Ebene öffnet sich... Der Gott ist im Begriff zu erwachen..."
  },
  AvgDialog_131213_Content_34 = {
    Text = "Schwester, hast du es gesehen? Dein Netz wird bald fertiggestellt sein..."
  },
  AvgDialog_131213_Content_35 = {
    Text = "Nefraea schaute erfreut auf den immer klarer werdenden Gang, ein Lächeln und Tränen erschienen gleichzeitig auf ihrem Gesicht."
  },
  AvgDialog_131213_Content_36 = {Text = "@2...@3..."},
  AvgDialog_131213_Content_37 = {
    Text = "Das Theater beginnt heftig zu beben. Die Bühne bricht zusammen, die Dimension zittert. Das Schicksal aller fürchtet sich und unterwirft sich diesem großartigen Erscheinen."
  },
  AvgDialog_131213_Content_38 = {
    Text = "Der Druckbefehl in dir ist auf fast nichts geschrumpft. Die Macht des Plasmids wurde in den Körper des Apostels aufgenommen. Sein Glanz ist zu heftig, um hineinzublicken; Seine Existenz ist absolut unbestreitbar."
  },
  AvgDialog_131213_Content_39 = {
    Text = "Unter dem ruhigen Blick von Arachne, inmitten des Schauderns aller Schicksale, wird Er auf dieser endgültigen Bühne erscheinen—"
  },
  AvgDialog_131213_Content_4 = {
    Text = "Ah, liebe Zuschauer, der mit Spannung erwartete Moment naht! Lassen Sie uns unseren Hauptdarsteller mit Applaus willkommen heißen, der gleich auftritt! Oh"
  },
  AvgDialog_131213_Content_40 = {
    Text = "Im Namen von...@2...@3 Gläubiger..."
  },
  AvgDialog_131213_Content_41 = {
    Text = "Sprich, Apostel... was möchtest du mir sagen? Ist es dein Wunsch? Oder die Worte dieser Person Gottes?"
  },
  AvgDialog_131213_Content_42 = {
    Text = "Welche Botschaft hat Er dieser Welt zu übermitteln? Soll diese Bühne zerbrochen werden? Oder will Er, dass diese Marionetten gemeinsam Sein Erscheinen erwarten?"
  },
  AvgDialog_131213_Content_43 = {
    Text = "Sag mir, mein lieber Apostel! Was für ein gefährliches, entzückendes Biest du bist, das nur zu reißen und zu zerstören weiß... sag mir, was du begehrst..."
  },
  AvgDialog_131213_Content_44 = {
    Text = "Sprich@2......Mein Name ist......Erweckung@2......@3Ursprünglich......"
  },
  AvgDialog_131213_Content_45 = {
    Text = "Ah, dein Name, ganz genau... Ich werde deinen Namen beschwören! Ich werde dir alles, was du fressen möchtest, bis an deine Lippen bringen. Ich werde für dich dieses Gefängnis öffnen..."
  },
  AvgDialog_131213_Content_46 = {
    Text = "Mein Name ist......@2......"
  },
  AvgDialog_131213_Content_47 = {
    Text = "Die Stimme des Apostels war unklar und verschwommen, Nefraea ging auf die immer heller werdende Lichtsäule zu, ohne einen Blick auf dich zu werfen, der vor Schmerz zitterte."
  },
  AvgDialog_131213_Content_48 = {
    Text = "Wahnsinn erfüllt sie mit Staunen und Lachen, während sie sich der gewaltigen Gestalt nähert. Ihr Atem stockt vor Begeisterung."
  },
  AvgDialog_131213_Content_49 = {
    Text = "Sie streichelte das schimmernde grüne Licht und berührte dieses prächtige Biest, das alles verschlingen würde. Sie würde die erste Nahrung des Biestes werden, sie zögerte nicht, süß wie Honig."
  },
  AvgDialog_131213_Content_5 = {
    Text = "Nefraea hob die Hand empor, und wie Feuerwerkskörper flogen die Spinnweben in die Luft und fielen herab. Du stehst in der Mitte der Bühne, das düstere Licht erhellt dein Gesicht."
  },
  AvgDialog_131213_Content_50 = {
    Text = "Jetzt ist es soweit, Apostel... Sag mir, sag dieser Welt deinen Namen"
  },
  AvgDialog_131213_Content_51 = {
    Text = "Mein Name ist......@2......"
  },
  AvgDialog_131213_Content_52 = {
    Text = "Mein Name ist... <Red:%player%>..."
  },
  AvgDialog_131213_Content_53 = {
    Text = "Mein Name ist... <Yellow:%player%>!"
  },
  AvgDialog_131213_Content_54 = {Text = "!!!"},
  AvgDialog_131213_Content_55 = {
    Text = "Die Zeit steht in diesem Moment still. Die Fäden des Schicksals schmelzen und zerfallen in Nefraea's Augen, das zusammenbrechende Schicksal ist wie ein tobender Wirbel in einem weiten Ozean, der sie mitreißt und verschlingt."
  },
  AvgDialog_131213_Content_56 = {
    Text = "<Shake:Was ist... was passiert hier?!!>"
  },
  AvgDialog_131213_Content_57 = {
    Text = "Der Wirbel ist sanft, das weite Wasser sammelt sich, die Wassertropfen vereinen sich wieder zu Fäden, und das Netz, das sie erstellt haben, ist bereits in einer Form, die Nefraea nicht vorhergesehen hat."
  },
  AvgDialog_131213_Content_58 = {
    Text = "Hast du es nicht verstanden, Nefraea? Bete aufrichtig zu deinem Apostel. Der Apostel, um den du gebetet hast, steht bereits vor dir."
  },
  AvgDialog_131213_Content_59 = {
    Text = "Du stehst vor Nefraea und blickst auf den Gang, der zum Toguwaibo-Tempel führt, und siehst die erhabene Gestalt, während du lächelst."
  },
  AvgDialog_131213_Content_6 = {
    Text = "Komm, {Male=Mr.,Female=Miss} Schutzherr. Unser letzter Akt beginnt..."
  },
  AvgDialog_131213_Content_60 = {
    Text = "Die Macht der drei Plasmide strömt ungehindert in dir, verursacht aber keinen Schmerz mehr. Das Licht aus dem Spinnrad, der überragende Wille in diesem Licht, strömt wie ein Ozean in deinen Körper und verbindet sich mit der Macht der drei Plasmide."
  },
  AvgDialog_131213_Content_61 = {
    Text = "Du spürst, dass die Gestalt des Apostels sich mit deinem Körper überlagert. Du fühlst dich überwältigend. Du fühlst dich grenzenlos. Du fühlst dich frei. Du fühlst... höchste Freude."
  },
  AvgDialog_131213_Content_62 = {
    Text = "Du... hast das Schicksal des Apostels gestohlen?!"
  },
  AvgDialog_131213_Content_63 = {
    Text = "Hahaha... Haha! Der dritte Akt der Geschichte, erscheinen? ... Ha, haha. Der dritte Akt, ganz genau. Aber das ist nicht deine Geschichte, liebe Nefraea."
  },
  AvgDialog_131213_Content_64 = {
    Text = "Ich bin es, der diesen Akt schreibt. Und ich nenne ihn... <Big:<color=#98918C>Verzückung</color>>!"
  },
  AvgDialog_131213_Content_65 = {
    Text = "<Shake:Ihr... ihr alle...>"
  },
  AvgDialog_131213_Content_66 = {
    Text = "Nein, das ist unmöglich... Ich kann dein Schicksal sehen... das ist unmöglich..."
  },
  AvgDialog_131213_Content_67 = {
    Text = "<color=#EE4D0C><Italic:„Oh, mein lieber Herzog, warum so ein langes Gesicht? Lasst Euren Narren dieses kostbare Lächeln wiederherstellen!\"></color>"
  },
  AvgDialog_131213_Content_68 = {
    Text = "<color=#BF0909><Italic:„Seht es euch an – das grausame Schicksal, den bösen Fluch... was für ein lächerliches Spektakel! Was für eine süße, köstliche Lüge!\"></color>"
  },
  AvgDialog_131213_Content_69 = {
    Text = "<color=#FC1818><Italic:„So endet die Geschichte des Schurken... die einzige Belohnung für Bosheit ist Verzückung!\"></color>"
  },
  AvgDialog_131213_Content_7 = {
    Text = "Diese Szene nenne ich — „Erscheinen\""
  },
  AvgDialog_131213_Content_70 = {
    Text = "Donnernder Applaus bricht aus den leeren Sitzen hervor. Gleißendes Licht durchflutet die zerstörte Bühne. Du bist der Angelpunkt der Welt, der Meister der Singularität. \nDu breitest die Arme aus. Du erklärst, dass sich das Schicksal vor dir beugen wird. Du erklärst diese Aufführung zum Meisterwerk."
  },
  AvgDialog_131213_Content_71 = {
    Text = "Täuschung. Manipulation. Purer Genuss... <Shake:Hehe... <Big:HAHAHAHA!>> Was für eine entzückende Vorstellung, kleine Spinne."
  },
  AvgDialog_131213_Content_72 = {
    Text = "<Shake:Du... du kannst unmöglich die Macht haben, das Schicksal zu verändern...>"
  },
  AvgDialog_131213_Content_73 = {
    Text = "Aww... Nein, nein, nein. Solche Anstrengung ist etwas für Leute wie dich. Ein Anhänger der Verzückung würde sich niemals zu solcher Mühsal herablassen."
  },
  AvgDialog_131213_Content_74 = {
    Text = "<Shake:Ich sah das Ende... Du solltest deinen Druckbefehl aufgeben! <Big:Du solltest zusehen, wie sich der Durchgang öffnet, und auf dieser Bühne sterben! WARUM?!>>"
  },
  AvgDialog_131213_Content_75 = {
    Text = "Diejenigen, die das Schicksal kontrollieren, wissen alles, außer das der Freude. Denn die Freude hat kein Schicksal, mein Lieber..."
  },
  AvgDialog_131213_Content_76 = {
    Text = "Du beugst dich herunter und bewunderst die zitternden Augen von Nefraea. Der Schmerz und die Verzweiflung, die in diesen Augen funkeln, nähren jeden Zentimeter deines Körpers."
  },
  AvgDialog_131213_Content_77 = {
    Text = "Alles in unserem Leben dreht sich um die Jagd nach Freude. Ohne Freude haben wir nichts... Der Freudenreiche hat kein Schicksal."
  },
  AvgDialog_131213_Content_78 = {
    Text = "Was du siehst, ist ein Salontrick. Ein kleiner Scherz, den das neue Ich – gesegnet mit dem Willen und der Macht eines Gottes – meinem früheren Selbst und dem Schicksal gespielt hat."
  },
  AvgDialog_131213_Content_79 = {
    Text = "Warum das Schicksal kontrollieren, wenn man es stattdessen zum Narren halten kann? Nicht wahr, Executor des Schicksals?"
  },
  AvgDialog_131213_Content_8 = {
    Text = "Erscheinen. Hinter dem Bühnenvorhang ist dieses riesige, schreckliche Wort aus schleimigen Spinnweben gewoben. Nefraea atmet tief ein und breitet die Arme aus."
  },
  AvgDialog_131213_Content_80 = {
    Text = "Du versuchst, einen ernsten Ton beizubehalten, aber du kannst dein manisches Lachen nicht unterdrücken."
  },
  AvgDialog_131213_Content_81 = {
    Text = "Bist du der Schutzherr? Bist du „ N \"? Du weißt es nicht, und es ist dir egal. Die Essenz der Verzückung strömt in den Willen des Apostels und füllt jede Zelle deines Körpers."
  },
  AvgDialog_131213_Content_82 = {
    Text = "Du willst vor Lachen brüllen. Du willst jubeln. Du willst diesen gescheiterten Manipulator der zärtlichsten, verheerendsten Demütigung aussetzen."
  },
  AvgDialog_131213_Content_83 = {
    Text = "Du hast den Schlüssel zum Öffnen des Schlosses gefunden. Du drehst dich um und verneigst dich elegant vor dieser Person, die das Layout erstellt hat."
  },
  AvgDialog_131213_Content_84 = {
    Text = "Arachne, der große Dramatiker! Von dem Moment an, als ich in diese Welt kam, hat sie damit begonnen, diese Bühne für mich zu weben"
  },
  AvgDialog_131213_Content_85 = {
    Text = "Zeig mir, wie das Schicksal sich dreht, lass mich den Reiz der Täuschung erleben und verrate mir das Geheimnis der „Freude\"..."
  },
  AvgDialog_131213_Content_86 = {
    Text = "Jetzt ist das Schloss der „Freude\" geöffnet. Wie gefällt es dir, mein Schauspieler? Bist du zufrieden?"
  },
  AvgDialog_131213_Content_87 = {
    Text = "Ich bin nur der Bühnenbauer, das Schreiben der Geschichte liegt in Ihrer Entscheidung."
  },
  AvgDialog_131213_Content_88 = {
    Text = "Du grinste sie an. Du bist der Apostel der Götter. Du bist der Sklave der Freude. Du bist der unbestrittene einzige Herr dieser Welt. Du hebst die Hand und tippst sanft wie ein Dirigent."
  },
  AvgDialog_131213_Content_89 = {
    Text = "Als Gegenleistung... Jetzt zieh dein Kostüm an, Arachne. Die Aufführung wird bald zu deinem Auftritt kommen"
  },
  AvgDialog_131213_Content_9 = {
    Text = "Apostel des höchsten Gottes, Überbringer des chaotischen Wahns. Dein Glanz erhellt das ewige Gefängnis, ich höre deinen Ruf des Chaos."
  },
  AvgDialog_131213_Content_90 = {
    Text = "Du zupfst an den einst unsichtbaren Fäden, als würdest du Bauklötze in einem Kinderzimmer verschieben."
  },
  AvgDialog_131213_Content_91 = {
    Text = "Während sich das Gewebe neu formt, fliegen die gestohlenen Dimension Glut zu ihr zurück."
  },
  AvgDialog_131213_Content_92 = {
    Text = "Dunkellila, unendlich feiner Sand strömte um Arachne und drehte sich um sie. In deinem Werk wurden die Dimension Glut niemals geraubt."
  },
  AvgDialog_131213_Content_93 = {
    Text = "<color=#8C7E96>In der Vergangenheit, in der Zukunft, gehören sie immer Arachne.</color>"
  },
  AvgDialog_131213_Content_94 = {
    Text = "Arachne lächelt dir zu und nickt, während sie die Glut in ihren Körper verbirgt. Ihr Spinnrad dreht sich unaufhörlich. Ihr Lächeln hat sich nie verändert."
  },
  AvgDialog_131213_Content_95 = {
    Text = "Du schüttelst den Kopf auf der Bühne und gibst ein übertriebenes Seufzen von dir."
  },
  AvgDialog_131213_Content_96 = {
    Text = "Tote Stille, keine Leidenschaft... Du hättest so eine interessante Person sein können, Arachne."
  },
  AvgDialog_131213_Content_97 = {
    Text = "Du bist wie Tawil ein Späher des Schicksals und auch ein Sklave des Schicksals. Das Glück, das ich jetzt empfinde, werdet ihr niemals erfahren."
  },
  AvgDialog_131213_Content_98 = {
    Text = "Schau dir dein lebloses Gesicht an, Arachne. Ich habe wirklich Mitleid mit euch."
  },
  AvgDialog_131213_Content_99 = {
    Text = "Alle treffen ihre Wahl, %player%... oder soll ich dich den Apostel nennen? Oder vielleicht... „ N \"?"
  },
  AvgDialog_131214_Content_1 = {
    Text = "<Shake:AAAAARGH!!>"
  },
  AvgDialog_131214_Content_10 = {
    Text = "Denn... unsere Rache ist noch nicht beendet und wird es niemals sein..."
  },
  AvgDialog_131214_Content_11 = {
    Text = "Du bist instinktiv einen Schritt zurückgetreten. Aber von Nefraea geht keine gefährliche Welle aus."
  },
  AvgDialog_131214_Content_12 = {
    Text = "Sie schwenkte nur ihre Scheren und riss den Vorhang, der an ihrer Seite hing, herunter und offenbarte die Szene hinter dem Vorhang."
  },
  AvgDialog_131214_Content_13 = {
    Text = "Das ist...!"
  },
  AvgDialog_131214_Content_14 = {
    Text = "Die blutroten Fäden verbinden mehrere Bühnen im Theater, verbinden diese prächtige Stadt, in der sich das Theater befindet, und verbinden die unzähligen Marionetten in der Stadt, die in den verwundeten Körper von Nefraea fließen."
  },
  AvgDialog_131214_Content_15 = {
    Text = "Du hast den Faden... nicht am Spinnrad befestigt?"
  },
  AvgDialog_131214_Content_16 = {
    Text = "Sie hat das Ende gesehen. Sie sah ihr Scheitern. Als sie noch Kraft hatte, band sie diese Schicksale an sich, wie..."
  },
  AvgDialog_131214_Content_17 = {
    Text = "So wie damals, als du mich zum ersten Mal getötet hast."
  },
  AvgDialog_131214_Content_18 = {
    Text = "Nefraea lächelte und zupfte vor sich eine sehr versteckte Faser."
  },
  AvgDialog_131214_Content_19 = {
    Text = "Der scharlachrote Faden erstreckt sich von ihrem Hinterkopf, schleicht sich durch einen vorsichtigen, langen Weg heimlich in den Körper von Arachne."
  },
  AvgDialog_131214_Content_2 = {Text = "Boom—"},
  AvgDialog_131214_Content_20 = {
    Text = "Wir sind schon lange nicht mehr so nah gewesen, Schwester. Erst gerade eben fand ich die Gelegenheit, dir diesen Faden zurückzugeben."
  },
  AvgDialog_131214_Content_21 = {
    Text = "„Noch \"...?"
  },
  AvgDialog_131214_Content_22 = {
    Text = "Dieser Faden... ist der, den ich beim ersten Zerschmettern meines Relikts durchtrennt habe."
  },
  AvgDialog_131214_Content_23 = {
    Text = "Deine Romantik, deine Güte, deine Erinnerungen... alles an mir wurde dir bereits zurückgegeben."
  },
  AvgDialog_131214_Content_24 = {
    Text = "Du bist vollständig, Arachne."
  },
  AvgDialog_131214_Content_25 = {
    Text = "Die Mundwinkel von Nefraea zogen sich hoch, wie ein Kind, das hinter einem Vorhang versteckt ist und zusieht, wie die Erwachsenen von seinen Streichen hereingelegt werden."
  },
  AvgDialog_131214_Content_26 = {
    Text = "In den Momenten, in denen du Kraft hast... ist das, was du tun möchtest?"
  },
  AvgDialog_131214_Content_27 = {
    Text = "Wie ist es? Geniale Idee, nicht wahr"
  },
  AvgDialog_131214_Content_28 = {
    Text = "Komm, töte mich! Zerstöre vollständig die Schicksale, die du einst verworfen hast! Zerstöre diese Stadt, in der du lebst, zerstöre dieses Theater, das du liebst, zerstöre jeden hier"
  },
  AvgDialog_131214_Content_29 = {
    Text = "Komm schon, Arachne! Bring all deine Schwächen mit, <Shake: töte alles, was du liebst, noch einmal!!!>"
  },
  AvgDialog_131214_Content_3 = {
    Text = "Die schmerzhaften Schreie und das Dröhnen der Zerstörung hallten durch das zerbrochene Theater. Der blutrote Faden riss Zentimeter für Zentimeter, das Spinnrad, das Nefraea ihr ganzes Leben lang begleitet hatte, fiel vor ihr zu Boden."
  },
  AvgDialog_131214_Content_30 = {
    Text = "Nefraea's aufgeregtes Brüllen und Lachen hallen lange in dem zerbrochenen Theater wider."
  },
  AvgDialog_131214_Content_31 = {
    Text = "Arachne's Körper scheint unerhört schwer geworden zu sein. Sie dreht langsam ihren Kopf und scannt alles, was mit Nefraea verbunden ist."
  },
  AvgDialog_131214_Content_32 = {
    Text = "Durch den Spalt des Theaters sah sie, wie Autos und Menschen diese pulsierende Stadt füllten. Die vertrauten Gesichter mit vertrauten Namen waren in jeder Ecke, die sie kannte, verstreut."
  },
  AvgDialog_131214_Content_33 = {
    Text = "Sie sieht die Bühne, auf die sie einst mit dir trat. Der grausame Krieg ist zu Ende, und diese Welt steht kurz vor einem zweihundertjährigen, langen und prächtigen Frieden."
  },
  AvgDialog_131214_Content_34 = {
    Text = "In dem schwarzen, klebrigen Schleim sah sie das Gesicht ihrer Mutter. Sie saß mit ihrem Vater unter der Birke im Innenhof und winkte sich selbst zu."
  },
  AvgDialog_131214_Content_35 = {
    Text = "Herr Lawrence steht neben ihnen und poliert das eigens für sie gefertigte Besteck."
  },
  AvgDialog_131214_Content_36 = {
    Text = "Du nennst es Rache, weil du das Schicksal nie klar gesehen hast und mich auch nie, Nefraea."
  },
  AvgDialog_131214_Content_37 = {
    Text = "Ein mit Schleim bedeckter Faden verbindet Arachne mit der zerbrochenen Bühne unter Nefraea. Mit ihrem schweren Körper tritt Arachne auf den zerbrechlichen Faden."
  },
  AvgDialog_131214_Content_38 = {
    Text = "Der Faden zittert, als könnte er reißen und den Gefangenen des Schicksals in den Abgrund stürzen."
  },
  AvgDialog_131214_Content_39 = {
    Text = "Arachne blickte ruhig in die überraschten Augen von Nefraea. Ihr Schritt hatte niemals einen Moment innegehalten."
  },
  AvgDialog_131214_Content_4 = {
    Text = "Sie hielt das Spinnrad fest wie ein im Wasser gefangenes Baby. In ihren Händen zerfiel das düstere Spinnrad unaufhaltsam und verwandelte sich in die Glut der Dimension, die in den Sandstrom neben Arachne floss."
  },
  AvgDialog_131214_Content_40 = {
    Text = "Der vorherbestimmte Moment naht..."
  },
  AvgDialog_131214_Content_41 = {
    Text = "Arachne auf dem Spinnennetz hob das Spinnrad in ihrer Hand. Du siehst deutlich, wie die ganze Welt einen Moment inne hielt, das gesamte Universum, das mit diesem Theater verbunden ist, wartete auf ihren Befehl."
  },
  AvgDialog_131214_Content_42 = {
    Text = "Ich erkläre hiermit im Namen des Schicksals—"
  },
  AvgDialog_131214_Content_43 = {
    Text = "Alle fehlgeleiteten Schicksale sollen im Staub der Zeit begraben werden. Das Geschick der Welt soll zu seinem vorbestimmten Lauf zurückkehren."
  },
  AvgDialog_131214_Content_44 = {
    Text = "Das falsche Schicksal endet hier. Die Verstoßenen sollen Ruhe finden..."
  },
  AvgDialog_131214_Content_45 = {
    Text = "Das Spinnrad neigt sich und tausende Fäden zittern mit."
  },
  AvgDialog_131214_Content_46 = {
    Text = "Der Faden reißt. Die Bühne, die auf Frieden wartet, zerbricht und zerfällt."
  },
  AvgDialog_131214_Content_47 = {
    Text = "Der Faden reißt. In den Rissen des Theaters ist die Stadt nicht mehr zu sehen."
  },
  AvgDialog_131214_Content_48 = {
    Text = "Der Faden reißt, reißt, reißt..."
  },
  AvgDialog_131214_Content_49 = {
    Text = "Du kannst die Fäden des Schicksals nur schwer erkennen, aber du hörst den Schrei des Schicksals klar und deutlich."
  },
  AvgDialog_131214_Content_5 = {
    Text = "Nefraea starrte gedankenverloren auf die verstrichene Hoffnung und begann plötzlich zu kichern."
  },
  AvgDialog_131214_Content_50 = {
    Text = "Unzählige Menschenleben, unzählige Freuden und Leiden zerbrechen, zerfallen, rekonstruieren und vernichten sich in deinem Ohr..."
  },
  AvgDialog_131214_Content_51 = {Text = "...Licht?"},
  AvgDialog_131214_Content_52 = {
    Text = "Die Bühnenlichter, die aus unbekannten Quellen kamen, erleuchteten den Raum. Das Licht durchdrang das zerbrochene Theater, und die im Schatten verborgenen Verlassenen verschwanden in dem Moment, als der Schein fiel, als wären sie nie erschienen."
  },
  AvgDialog_131214_Content_53 = {
    Text = "Arachne, Schwester, du......"
  },
  AvgDialog_131214_Content_54 = {
    Text = "Arachne trat mit dem drehenden Spinnrad über den zerbrechlichen Faden und kam vor ihr zum Stehen. Nefraea sah zu ihr auf, als würde sie das unvermeidliche Schicksal selbst betrachten."
  },
  AvgDialog_131214_Content_55 = {
    Text = "Komm näher zu mir, Nefraea."
  },
  AvgDialog_131214_Content_56 = {
    Text = "Arachne hielt Nefraea's Hand und legte sie an ihre Wange."
  },
  AvgDialog_131214_Content_57 = {
    Text = "In dem Moment, als sie Arachne berührte, öffnete sich ein verstecktes Tor zu Nefraea. Nefraea durchquerte die sich übereinander stapelnden Käfige und stand zum ersten Mal wirklich vor Arachne."
  },
  AvgDialog_131214_Content_58 = {
    Text = "In diesem Käfig sah sie drei vertraute Gesichter."
  },
  AvgDialog_131214_Content_59 = {
    Text = "Arachne！！！Du......"
  },
  AvgDialog_131214_Content_6 = {
    Text = "Ihr Lachen wurde immer lauter, und sie hatte kaum die Kraft, sich aufzurichten. Blut tropfte aus ihrem zitternden Körper und färbte die düsteren Fragmente des Spinnrades rot."
  },
  AvgDialog_131214_Content_60 = {
    Text = "<Shake:Romantik, Güte, Gedenken... sie... sie...>"
  },
  AvgDialog_131214_Content_61 = {
    Text = "Ich konnte sie nie vollständig loslassen. Ich konnte dich nie wirklich loslassen."
  },
  AvgDialog_131214_Content_62 = {
    Text = "Aber du hast gesagt, dass du das nicht ertragen kannst..."
  },
  AvgDialog_131214_Content_63 = {
    Text = "Dummheit, Zerbrechlichkeit, schmerzhaft alles zu zerstören, was ich schätze... du kannst dich nicht rächen, Nefraea."
  },
  AvgDialog_131214_Content_64 = {
    Text = "Denn das ist die Strafe, die das Schicksal bereits für mich bestimmt hat."
  },
  AvgDialog_131214_Content_65 = {
    Text = "Arachne lächelte sie ruhig an. Ihr Spinnrad drehte sich, ewig und unaufhörlich."
  },
  AvgDialog_131214_Content_66 = {
    Text = "Es ist vorbei, Nefraea."
  },
  AvgDialog_131214_Content_67 = {
    Text = "Eine Saite zitterte sanft. Nefraea hörte das Weinen einer Silberreiher, so wie an dem Tag, als ihr Vater ihr das Spinnrad namens Moirai brachte, als sie noch ganz klein war."
  },
  AvgDialog_131214_Content_68 = {
    Text = "Das ist ihr Raum, der Birkenbaum draußen ist ihr treuer Freund, ein unvergänglicher, einsamer Gefangener."
  },
  AvgDialog_131214_Content_69 = {
    Text = "Sie sind vom Schicksal gefangen, sie hängen hier voneinander ab."
  },
  AvgDialog_131214_Content_7 = {
    Text = "Das Ende, das Ende ist tatsächlich nicht zu ändern... Das ist das Schicksal..."
  },
  AvgDialog_131214_Content_70 = {
    Text = "Quietschen—Yaa—"
  },
  AvgDialog_131214_Content_71 = {
    Text = "Die schlichte Holztür wurde aufgeschoben, Arachne kam zu ihr, beugte sich herunter und streichelte sanft ihr Gesicht."
  },
  AvgDialog_131214_Content_72 = {
    Text = "Schwester... Ich habe verloren... Wir haben verloren..."
  },
  AvgDialog_131214_Content_73 = {
    Text = "Wir hatten nie das Recht zu gewinnen."
  },
  AvgDialog_131214_Content_74 = {
    Text = "Erinnerst du dich an den Tag, an dem wir das Spinnrad erhalten haben und unsere Wünsche geäußert haben?"
  },
  AvgDialog_131214_Content_75 = {
    Text = "„Ich werde die Gaben des Schicksals nicht verschwenden... Ich werde dieser Welt ein wunderschönes Schicksal bringen...\""
  },
  AvgDialog_131214_Content_76 = {
    Text = "Was für ein naiver Wunsch, Arachne... Damals verstanden wir überhaupt nicht, was das bedeutete."
  },
  AvgDialog_131214_Content_77 = {
    Text = "Arachne streckte die leicht zitternde Hand aus und streichelte ihr fernes eigenes Gesicht."
  },
  AvgDialog_131214_Content_78 = {
    Text = "Schicksal... wer kann es wirklich klar erkennen."
  },
  AvgDialog_131214_Content_79 = {
    Text = "Aber selbst wenn ich es voraussehen könnte, würde sich meine Wahl dennoch nicht ändern."
  },
  AvgDialog_131214_Content_8 = {
    Text = "Dieser tragische Sieg hast du schon längst gesehen, oder? Arachne?"
  },
  AvgDialog_131214_Content_80 = {
    Text = "<Shake:Warum, Arachne?> Du kannst gehen, du kannst freigeben, du kannst..."
  },
  AvgDialog_131214_Content_81 = {
    Text = "Nachdem du den Abgrund verlassen hast, hättest du ewige Freiheit haben können. Du weißt, dass du letztendlich scheitern wirst, aber du kommst dennoch, um zu versuchen, mir und den Schicksalen, die dir folgen, Erlösung zu bringen."
  },
  AvgDialog_131214_Content_82 = {
    Text = "Jeder Schicksalslenker wird zum Gefangenen des Schicksals, so sind wir alle, du und ich. Nicht wahr, Nefraea?"
  },
  AvgDialog_131214_Content_83 = {
    Text = "Nefraea schwieg und sah traurig aus dem Fenster auf die Birken. Sie beobachtete, wie der Baum Äste trieb, Blätter bekam, wuchs und verwelkte."
  },
  AvgDialog_131214_Content_84 = {
    Text = "Sie seufzte leise, hob den Kopf und streichelte die Tränen, die langsam über das Gesicht von Arachne liefen. Sie lächelte ihr zu."
  },
  AvgDialog_131214_Content_85 = {
    Text = "Es ist schön, dich wiederzusehen... Schwester."
  },
  AvgDialog_131214_Content_86 = {
    Text = "Eine Träne fällt sanft herab und tropft auf das Gesicht, das genau wie das von Arachne aussieht."
  },
  AvgDialog_131214_Content_87 = {
    Text = "Bitte verzeih meine Egoismus..."
  },
  AvgDialog_131214_Content_88 = {
    Text = "Du... bist frei, <Red:„Arachne\">."
  },
  AvgDialog_131214_Content_89 = {Text = "Quiek."},
  AvgDialog_131214_Content_9 = {
    Text = "Gerade hast du auch kurz auf alles gespäht. Da du bereits das endgültige Ende kennst, warum solltest du dich noch daran festhalten?"
  },
  AvgDialog_131214_Content_90 = {
    Text = "Als der letzte Faden reißt, bricht donnernder Applaus aus."
  },
  AvgDialog_131214_Content_91 = {
    Text = "Der Zuschauerraum, der immer leer war, ist längst voll besetzt. Die verlassenen Schicksale und die Puppen, die durch eure Hände starben, füllen jeden zerbrochenen Samtsitz."
  },
  AvgDialog_131214_Content_92 = {
    Text = "Die Darsteller nehmen ihre Plätze im Publikum ein und beobachten schweigend, wie sich das Finale auf dieser zerbrochenen Bühne entfaltet."
  },
  AvgDialog_131214_Content_93 = {
    Text = "Sie sind ausdruckslos und lautlos. \n Sie applaudieren begeistert. Der Applaus donnert und hält lange an."
  },
  AvgDialog_131215_Content_1 = {Text = "Charakter"},
  AvgDialog_131215_Content_10 = {
    Text = "Ich verstand zuvor nicht, warum Arachne ihre Schwester aus dem Schicksalsnetz entfernen wollte, und warum du Kraft aus diesen drei geheimen Einheiten beziehen musst."
  },
  AvgDialog_131215_Content_100 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131215_Content_101 = {
    Text = "Die hartnäckige und vergebliche Schicksalsgöttin... Wie verzweifelt, wie tragisch schön ist dieses Bild..."
  },
  AvgDialog_131215_Content_102 = {
    Text = "Was sagt ihr, warum macht sie das?"
  },
  AvgDialog_131215_Content_103 = {
    Text = "Nefraea sah aufmerksam auf diese schlichte Bühne, ihre Stimme war so leise wie ein Murmeln."
  },
  AvgDialog_131215_Content_104 = {
    Text = "Das ist nur ein Traum, die Göttin des Schicksals... Du hättest das glücklichste Schicksal für alle wählen können, du hättest deine unrealistischen Fantasien korrigieren und alles erfüllen können, was du wolltest."
  },
  AvgDialog_131215_Content_105 = {
    Text = "Aber du hast nie daran gedacht, das zu tun... Wenn du das Vollkommene erschaffst, erschaffst du auch Leid. Immer wieder lässt du das Leid in dieser Welt erscheinen."
  },
  AvgDialog_131215_Content_106 = {
    Text = "Du gibst dein Bestes, um das große Netz des Schicksals zu weben, doch die Szenen hinter der Tür und das vorbestimmte Ende des Schicksals haben wir beide gesehen."
  },
  AvgDialog_131215_Content_107 = {
    Text = "In dem Moment, als das Netz des Schicksals gewoben wird, ist es die Zeit, in der diese höchste Gottheit vollständig erwacht..."
  },
  AvgDialog_131215_Content_108 = {Text = "Was...?!"},
  AvgDialog_131215_Content_109 = {
    Text = "Du blickst Arachne an und hoffst, auf ihrem Gesicht eine ablehnende Antwort zu finden."
  },
  AvgDialog_131215_Content_11 = {
    Text = "Zumindest muss ich dir danken, dass du meine Zweifel geklärt hast."
  },
  AvgDialog_131215_Content_110 = {
    Text = "Du findest nur ihre gewohnte, ewige Ruhe. Auf der Bühne des Schicksals ist Gelassenheit eine Maske, die sie nicht abnehmen kann."
  },
  AvgDialog_131215_Content_111 = {
    Text = "Schwester, du kannst nicht aufhören zu weben, weil du es nicht ertragen kannst, das Universum ins Chaos stürzen zu sehen. Doch an dem Tag, an dem dein Netz vollendet ist, wirst du derjenige sein, der alles, was du liebst, mit eigenen Händen begräbt."
  },
  AvgDialog_131215_Content_112 = {
    Text = "Wie ironisch, Arachne. Warum? Warum lässt du dieses Universum nicht in Freude das unvermeidliche Ende begrüßen?"
  },
  AvgDialog_131215_Content_113 = {
    Text = "Alles, was Schicksal ist, hat eine feste Zahl. Alles, was Schicksal ist, hat eine Variable. Diese beiden sich widersprechenden Sprüche sind das Wesen des Schicksals."
  },
  AvgDialog_131215_Content_114 = {
    Text = "Arachne blickte in die Augen von Nefraea und antwortete auf die Frage, die sie sich schon unzählige Male selbst beantwortet hatte."
  },
  AvgDialog_131215_Content_115 = {
    Text = "Nefraea, in der endlosen Dimension kämpfen unzählige Menschen um diese Variable."
  },
  AvgDialog_131215_Content_116 = {
    Text = "Die Bühne am Laufen zu halten, auf das Auftreten von Variablen zu warten... Das sind die Fesseln, die mir das Schicksal angelegt hat. Das ist meine unvermeidliche Pflicht."
  },
  AvgDialog_131215_Content_117 = {
    Text = "Pflichten, Gefahren... Du sprichst über all das Großartige, aber nie über dich selbst, Arachne, meine arme Schwester. Aber das ist in Ordnung, deine leidvollen Pflichten werden bald enden."
  },
  AvgDialog_131215_Content_118 = {
    Text = "Nefraea streichelte sanft Arachne's Gesicht und schenkte ihr ein süßes Lächeln."
  },
  AvgDialog_131215_Content_119 = {
    Text = "In der Abyssus habe ich unzählige Male die Szenen unseres Wiedersehens imaginiert und überlegt, welches Geschenk unserem Wiedersehen gerecht werden könnte."
  },
  AvgDialog_131215_Content_12 = {
    Text = "Warum hast du mir das vorher nicht gesagt?"
  },
  AvgDialog_131215_Content_120 = {
    Text = "Ich habe lange, lange nachgedacht. Ich habe an dich, meine liebe Schwester, gedacht! Das ist das beste Geschenk, das ich dir geben kann——"
  },
  AvgDialog_131215_Content_121 = {
    Text = "Ich schenke dir... <Red:Befreiung.>"
  },
  AvgDialog_131215_Content_122 = {
    Text = "In den sanften Worten von Nefraea sammelt sich die schwarze, klebrige Substanz zwischen den Rissen der Dimension. Am Ende des Spinnennetzes erscheint eine prächtige Bühne vor euch."
  },
  AvgDialog_131215_Content_13 = {
    Text = "Du blickst zu Arachne, die dich an deiner Seite führt."
  },
  AvgDialog_131215_Content_14 = {
    Text = "Ein Stein, der im See des Schicksals keine Wellen schlägt, ist außer der Zerstörung der Ruhe des Sees nutzlos."
  },
  AvgDialog_131215_Content_15 = {
    Text = "Sie und ich sind schon vor langer Zeit zu zwei verschiedenen Personen geworden, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131215_Content_16 = {
    Text = "Hast du mit diesem Tag gerechnet?"
  },
  AvgDialog_131215_Content_17 = {
    Text = "Kein Gefangener sieht sein eigenes Schicksal, bevor das Urteil gesprochen ist."
  },
  AvgDialog_131215_Content_18 = {
    Text = "Wenn du wüsstest, dass das Schicksal des Verlassenen nicht verschwinden wird, sondern ins ewige Exil verbannt wird... würdest du dann diese Dinge trotzdem tun, Arachne?"
  },
  AvgDialog_131215_Content_19 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131215_Content_2 = {
    Text = "Lalalala..."
  },
  AvgDialog_131215_Content_20 = {
    Text = "Schweigen. Schweigen ist die ewige Katastrophe des Dramatikers. Schweigen ist die ohnmächtige Verteidigung des Gefangenen. In der qualvollen Stille ertönt das wahnsinnige Lachen von Nefraea."
  },
  AvgDialog_131215_Content_21 = {
    Text = "Ah, das wirst du natürlich, Schwester. Das Schicksal ist dein Lehrsatz, alle, alle Bedingungen können seine einzige Antwort nicht verändern."
  },
  AvgDialog_131215_Content_22 = {
    Text = "Die Göttin des Schicksals, wie klein, wie zerbrechlich, wie grausam..."
  },
  AvgDialog_131215_Content_23 = {
    Text = "Aber es ist egal. Egal was du tust, ich habe die ganze lange Zeit immer an dich gedacht, meine liebe Schwester."
  },
  AvgDialog_131215_Content_24 = {
    Text = "Romantik, Güte, Erinnerungen. Eine wunderbare Mischung aus Rohstoffen, die fermentiert wird, um das Lächeln von Nefraea zu einem süßen Gift zu brauen."
  },
  AvgDialog_131215_Content_25 = {
    Text = "In ihrem strahlenden Lächeln erhellt das Licht der Spinnwebenstraße die Bühne."
  },
  AvgDialog_131215_Content_26 = {
    Text = "Schwester, {Male=Mr.,Female=Miss} Schutzherr... diese neuen Stücke sind ein Geschenk von mir, der neuen Herrin des Theaters."
  },
  AvgDialog_131215_Content_27 = {
    Text = "Genießt das wunderbare Vorspiel, bevor der grandiose dritte Akt aufgeführt wird... Merkt euch die Etikette des Schicksalstheaters, sprecht nicht"
  },
  AvgDialog_131215_Content_28 = {
    Text = "Nefraea öffnete die Arme wie ein Ansager. Die Bühne, die entlang des Weges wie ein Meer von Sternen leuchtet, erhellt sich nacheinander, während ihr langsam vorbeigeht."
  },
  AvgDialog_131215_Content_29 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131215_Content_3 = {
    Text = "Sie tanzen. Sie singen fröhlich. Quiek Quiek~"
  },
  AvgDialog_131215_Content_30 = {
    Text = "Verehrte Göttin des Schicksals, die Körper der drei geheimen Gefährten sind für Sie bereitgestellt."
  },
  AvgDialog_131215_Content_31 = {
    Text = "So feine Puppen... Das, was verloren ging, wird in ihnen wiedererstehen..."
  },
  AvgDialog_131215_Content_32 = {
    Text = "„Arachne\" verließ den Webstuhl und trat vor die Puppe."
  },
  AvgDialog_131215_Content_33 = {
    Text = "Die erste, ich gebe dir den Titel „Romantik\"."
  },
  AvgDialog_131215_Content_34 = {
    Text = "Du bist das leidenschaftlichste Kapitel der Musik, eine Ansammlung von Emotionen, die Früchte des Frühlings."
  },
  AvgDialog_131215_Content_35 = {
    Text = "Du wirst in das Paradies der Mitternacht gehen und dieser Stadt Wein, Begegnungen und niemals nachlassende Impulse bringen."
  },
  AvgDialog_131215_Content_36 = {
    Text = "Danke Ihnen, große Schicksalsgöttin Arachne. Nach Ihrem Willen wird der Wein und der Honig zwischen meinen Lippen und Zähnen fließen."
  },
  AvgDialog_131215_Content_37 = {
    Text = "Die schöne Frau verbeugte sich vor „Arachne\"."
  },
  AvgDialog_131215_Content_38 = {
    Text = "Die zweite, ich gebe dir den Titel „Güte\"."
  },
  AvgDialog_131215_Content_39 = {
    Text = "Du bist der alte Mann, der mich in meiner Kindheit begleitet hat. Du bist die weiße Feder, die der Engel fallen ließ, das reinste Sonnenlicht."
  },
  AvgDialog_131215_Content_4 = {
    Text = "Eine alte Geschichte und fröhliche Schritte zittern zusammen im Spinnennetz. Nefraea geht mit ihren Händen hinter dem Rücken fröhlich voran."
  },
  AvgDialog_131215_Content_40 = {
    Text = "Du wirst auf die Straßen der Stadt kommen und mit deiner Freundlichkeit alles erwärmen, was du siehst."
  },
  AvgDialog_131215_Content_41 = {
    Text = "Danke Ihnen! Großer Schicksalsgöttin Arachne. Mein Leben wurde von Ihnen geschenkt, ich kann Ihnen nichts zurückgeben."
  },
  AvgDialog_131215_Content_42 = {
    Text = "Ich habe nichts, außer meiner tiefen Liebe für alles auf dieser Welt. Ich werde beschützen, was beschützt werden muss, und helfen, wo Hilfe nötig ist."
  },
  AvgDialog_131215_Content_43 = {
    Text = "Alles, was ich habe, steht den Leidenden offen."
  },
  AvgDialog_131215_Content_44 = {
    Text = "Der freundliche Alte verbeugt sich tief vor „Arachne\"."
  },
  AvgDialog_131215_Content_45 = {
    Text = "Und du, der dritte... ich gebe dir den Namen „Erinnerung\"."
  },
  AvgDialog_131215_Content_46 = {
    Text = "„Arachne\" kam vor die kleine Geheimeinheit, hockte sich hin und sah in ihre nicht vorhandenen Augen."
  },
  AvgDialog_131215_Content_47 = {
    Text = "Du bist das verwaiste Kind des Schicksals, begraben in den tiefen Schnee der trockenen Blätter."
  },
  AvgDialog_131215_Content_48 = {
    Text = "Du wanderst einsam und elend, kannst nicht sprechen und bist von der Welt unbemerkt."
  },
  AvgDialog_131215_Content_49 = {
    Text = "In deinem ruhigen, langen Leben wirst du der einzige Hüter der Erinnerungen sein."
  },
  AvgDialog_131215_Content_5 = {
    Text = "Du folgst Arachne unwiderruflich, während du dem Spinnennetz bis zum Ende folgst."
  },
  AvgDialog_131215_Content_50 = {
    Text = "Das stille Mädchen hob den Kopf und streichelte sanft das Gesicht von „Arachne\"."
  },
  AvgDialog_131215_Content_51 = {
    Text = "„Arachne\" stand auf und betrachtete sanft ihre Geheimeinheiten."
  },
  AvgDialog_131215_Content_52 = {
    Text = "Geht, meine Kinder. Vor dem Webstuhl des Schicksals werde ich euch für immer beobachten."
  },
  AvgDialog_131215_Content_53 = {
    Text = "Diejenigen, die der Ewigkeit verworfen wurden, werden in eurem Schicksal nacheinander erblühen."
  },
  AvgDialog_131215_Content_54 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131215_Content_55 = {
    Text = "Die Bühne wird dunkel. Mit euren Schritten leuchtet das Licht der nächsten Bühne auf."
  },
  AvgDialog_131215_Content_56 = {
    Text = "Sonnenlicht existiert hier nicht. Wind, Blumen, Wolken... Nach drei langen Jahrhunderten existiert auch der Kalender nicht mehr..."
  },
  AvgDialog_131215_Content_57 = {
    Text = "Meister, ein neuer Verlassene ist angekommen."
  },
  AvgDialog_131215_Content_58 = {
    Text = "Die Oboe spielt eine Fanfare. Die zerlumpten Verstoßenen erscheinen."
  },
  AvgDialog_131215_Content_59 = {
    Text = "„Nefraea\" stand auf und ging in die Mitte der Bühne."
  },
  AvgDialog_131215_Content_6 = {
    Text = "Nun, {Male=Mr.,Female=Miss} Schutzherr? War die Vorstellung spektakulär? Besonders mit diesem Blick hinter die Kulissen?"
  },
  AvgDialog_131215_Content_60 = {
    Text = "Sag es mir, ihr armen Kinder... wer seid ihr und woher kommt ihr?"
  },
  AvgDialog_131215_Content_61 = {
    Text = "Oh, Göttin des Schicksals, bitte verzeih mir meine Unhöflichkeit... doch die Wut zwingt mich, Ihnen Fragen zu stellen."
  },
  AvgDialog_131215_Content_62 = {
    Text = "Ich habe viele Gefahren durchlebt, mit meinem Mut und meinem Leben ein großartiges Lob hinterlassen, das zusammen mit meinem Heimatland bis zum Ende des Universums gehen sollte."
  },
  AvgDialog_131215_Content_63 = {
    Text = "Warum, große Göttin ... warum hast Du uns in dieses wilde Land verbannt? <Shake:Warum musstest Du jene unsterblichen Melodien zu Staub zerfallen lassen!>"
  },
  AvgDialog_131215_Content_64 = {
    Text = "Meine Soldaten haben gerade einen langen Winter überstanden. Wir haben die barbarischen Eindringlinge zurückgeschlagen und unsere Zivilisation und Geschichte verteidigt."
  },
  AvgDialog_131215_Content_65 = {
    Text = "In den brutalsten Zeiten opferten die verletzten Soldaten freiwillig ihr Fleisch, damit ihre Kameraden essen konnten... Was für ein schmerzhafter Sieg, meine Göttin."
  },
  AvgDialog_131215_Content_66 = {
    Text = "Als der Feind sich zurückzog, waren die Augen aller mit Freudentränen gefüllt. Beim Siegesbankett werde ich jedem Soldaten den Becher mit starkem Alkohol füllen."
  },
  AvgDialog_131215_Content_67 = {
    Text = "Doch gerade in diesem Moment, bevor wir anstoßen konnten, wurde unser Zuhause zu Trümmern, und unsere Angehörigen wurden zu Staub..."
  },
  AvgDialog_131215_Content_68 = {
    Text = "<Shake:Geliebte Göttin, wollt Ihr uns nicht einmal einen einzigen Augenblick der Freude gewähren?>"
  },
  AvgDialog_131215_Content_69 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131215_Content_7 = {
    Text = "Nefraea hat sich von diesem wahnsinnigen Zustand auf der Bühne zurückgezogen. Sie dreht sich um und schaut dich voller Erwartung an."
  },
  AvgDialog_131215_Content_70 = {
    Text = "„Nefraea\" hörte den scheinbar endlosen Klage der Puppen zu, und auf dem gesichtslosen Antlitz fielen tatsächlich zwei Tränen herab."
  },
  AvgDialog_131215_Content_71 = {
    Text = "Ich habe euch gehört, ich habe euch gesehen..."
  },
  AvgDialog_131215_Content_72 = {
    Text = "Die große Zivilisation vergeht aus deinen Händen; die glorreichen Kunstwerke verwandeln sich in Staub. Die geliebten Menschen vergessen alles voneinander und erleben in Angst das schmerzhafte Ende..."
  },
  AvgDialog_131215_Content_73 = {
    Text = "Nur ein einziges richtiges Schicksal wird übrig bleiben, während all die unzähligen Fehler, die in diesem Moment geschehen, in diesen barbarischen, bodenlosen Abgrund strömen. So lang wie die stillstehende Zeit wird diese Geschichte jeden Tag aufgeführt."
  },
  AvgDialog_131215_Content_74 = {
    Text = "Wie lange möchtest du, dass ich schaue und höre, meine liebe Schwester..."
  },
  AvgDialog_131215_Content_75 = {
    Text = "„Nefraea\" atmete tief ein, wandte sich um."
  },
  AvgDialog_131215_Content_76 = {
    Text = "Sei unbesorgt, meine guten Kinder... Euer Leid, das ich geschaffen habe, wird auch von mir beendet werden."
  },
  AvgDialog_131215_Content_77 = {
    Text = "Bitte ruht euch hier vorübergehend aus. Eines Tages werde ich euch hier wegbringen, ich werde euch helfen, euer eigenes Schicksal zurückzugewinnen..."
  },
  AvgDialog_131215_Content_78 = {
    Text = "Im Namen von Nefraea, der Rächerin des Schicksals, verspreche ich euch..."
  },
  AvgDialog_131215_Content_79 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131215_Content_8 = {
    Text = "Als sie dein stilles Gesicht sah, schüttelte sie enttäuscht den Kopf."
  },
  AvgDialog_131215_Content_80 = {
    Text = "Lalalala..."
  },
  AvgDialog_131215_Content_81 = {
    Text = "Die Bühne entfernt sich allmählich, und bevor das Licht erlischt, siehst du die ausgebreiteten Arme der Puppe und die schwarze Träne auf ihrem Gesicht."
  },
  AvgDialog_131215_Content_82 = {
    Text = "Ihr habt nicht gesprochen, nur Nefraea summte sanft die Melodie auf der Bühne. Ihr Gesang war schnell und klar, und die Geschichte, die unzählige Male aufgeführt wurde, ließ in ihr keine überflüssigen Emotionen mehr entstehen."
  },
  AvgDialog_131215_Content_83 = {
    Text = "Oh je! Mein Lieblingsbühne kommt gleich! Beeil dich, Schwester"
  },
  AvgDialog_131215_Content_84 = {
    Text = "Nefraea's Stimme wurde begeistert. Sie nahm Arachne's Hand und rannte fröhlich zur Bühne voraus."
  },
  AvgDialog_131215_Content_85 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131215_Content_86 = {
    Text = "Die Lichter entzünden sich. Es gibt keine Musik, keinen Dialog – nur eine einsame Puppe an einem Spinnrad auf einer leeren Bühne."
  },
  AvgDialog_131215_Content_87 = {
    Text = "Knarrend, knarrend. Das Rad dreht sich, als würde der Tag, an dem es stillsteht, niemals kommen."
  },
  AvgDialog_131215_Content_88 = {
    Text = "......Sie tanzen. Sie singen. Quiek——Quiek——"
  },
  AvgDialog_131215_Content_89 = {
    Text = "Das Sonnenlicht erhellt ihre Gesichter, wie fröhlich——"
  },
  AvgDialog_131215_Content_9 = {
    Text = "Kein Applaus, keine Tränen. Stille ist eine Demütigung ... Ich dachte, ich hätte so lange in der Hölle geübt, dass diese Darbietung perfekt wäre, aber leider, leider."
  },
  AvgDialog_131215_Content_90 = {
    Text = "Das Liedchen ertönt sanft von dem gesichtslosen Gesicht von „Arachne\". Sie dreht den Spinnrad gemächlich, weder hastig noch langsam."
  },
  AvgDialog_131215_Content_91 = {
    Text = "Es ist ein eindringlicher Rhythmus—ein einziger Blick verrät dir, dass er, einmal begonnen, sich niemals ändern wird, bis ans Ende aller Dinge."
  },
  AvgDialog_131215_Content_92 = {
    Text = "Die Göttin des Schicksals wird ihr Netz weben."
  },
  AvgDialog_131215_Content_93 = {
    Text = "Das vollständige Netz des Schicksals umhüllt alle Menschen... sie tanzen, sie singen..."
  },
  AvgDialog_131215_Content_94 = {
    Text = "Ein riesiges Netz wird von einem Webstuhl gewebt und breitet sich über die gesamte Bühne aus. Das überflüssige Teil des Schicksalsnetzes breitet sich unter die Bühne aus."
  },
  AvgDialog_131215_Content_95 = {
    Text = "Jedes Mal, wenn das Netz sich der Vollendung nähert, beginnen seine äußersten Ränder zu zerschmelzen."
  },
  AvgDialog_131215_Content_96 = {
    Text = "Schwarze, klebrige Flüssigkeit, schwarzes Pulver, schließlich verschwunden. Das ist die Szene, die dir nur zu vertraut ist."
  },
  AvgDialog_131215_Content_97 = {
    Text = "Feiert, meine Kinder, mein Volk... Die Göttin des Schicksals wird ihr Netz weben..."
  },
  AvgDialog_131215_Content_98 = {
    Text = "Die Puppen schauten auf die Netze, die immer wieder gewebt und dann verschwunden sind."
  },
  AvgDialog_131215_Content_99 = {
    Text = "Ihre Stimme zitterte nicht, ihre Bewegungen waren unerschütterlich. Sie summte weiterhin leise ein Lied, während das Spinnrad in ihrer Hand sich drehte, unaufhörlich."
  },
  AvgDialog_131216_Content_1 = {
    Text = "Maskenparty"
  },
  AvgDialog_131216_Content_10 = {
    Text = "Das ist wirklich ein offenes Doppelmoral, Seniorstudent."
  },
  AvgDialog_131216_Content_11 = {
    Text = "Hust... Die Fähigkeit, für verschiedene Menschen angemessene Urteile zu fällen, die ihrer Persönlichkeit entsprechen, ist eine grundlegende Fähigkeit für Ermittler..."
  },
  AvgDialog_131216_Content_12 = {
    Text = "Wilhelm tut so, als hätte er deinen Spott nicht gehört, und beginnt ernsthaft nach einem Ziel zu suchen, das es wert ist, befragt zu werden."
  },
  AvgDialog_131216_Content_13 = {
    Text = "Ich habe in diesem Kampf alles verloren. Mein Adelsstand, meine Familie, mein linkes Bein, mein Leben."
  },
  AvgDialog_131216_Content_14 = {
    Text = "Zwanzig Jahre, volle zwanzig Jahre. Es ist eine Folter, mein Freund. Das Schicksal hat mich am Leben gelassen und lässt mich den Rest meines Lebens für meine Fehler büßen."
  },
  AvgDialog_131216_Content_15 = {
    Text = "Meine Familie ist durch meine Hände zerstört worden, aber was spielt das für eine Rolle? Sag mir, was könnte im Leben wichtiger sein als Alkohol?"
  },
  AvgDialog_131216_Content_16 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131216_Content_17 = {
    Text = "Ah, mein Lieber, erinnerst du dich an die Cocktails, die der Barkeeper uns beim letzten Mal hier gemixt hat?"
  },
  AvgDialog_131216_Content_18 = {
    Text = "Ich wage zu wetten, dass man in ganz Lentiniën keinen besseren Wein finden kann als diesen. Er ist so präzise und elegant, er ist fast wie eine Prophezeiung"
  },
  AvgDialog_131216_Content_19 = {
    Text = "Ich denke, es wäre schön, wenn wir diesen Barkeeper zur Party nächsten Monat einladen könnten."
  },
  AvgDialog_131216_Content_2 = {
    Text = "„90 Minuten Mitternacht, 15 Zoll Maske, 10 Gallonen Traum, 2 Unzen Alkohol—— die einzige Rezeptur für Freude\""
  },
  AvgDialog_131216_Content_20 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131216_Content_21 = {Text = "Knack—"},
  AvgDialog_131216_Content_22 = {
    Text = "Ein scharfes Fingerschnippen hallt wie ein Feuerwerk neben deinem Ohr. Du drehst dich um und erblickst ein Gesicht, das vor strahlendem Lächeln leuchtet."
  },
  AvgDialog_131216_Content_23 = {
    Text = "Entschuldigen Sie die Unterbrechung, verehrter Gast. Bei so vielen interessanten Themen, möchten Sie nicht ein Glas interessanten Wein dazu genießen?"
  },
  AvgDialog_131216_Content_24 = {
    Text = "Schau dir die Weinkarte an, Wilhelm, der Seniorstudent."
  },
  AvgDialog_131216_Content_25 = {
    Text = "William verstand deinen Blick. Zwei Personen in unbekannten Uniformen tauchten an diesem Ort auf und tranken von Anfang bis Ende keinen Alkohol, was wirklich schwer zu übersehen war."
  },
  AvgDialog_131216_Content_26 = {
    Text = "Als der Barkeeper seinen Blick nach der Getränkekarte suchte, schüttelte er lächelnd den Kopf."
  },
  AvgDialog_131216_Content_27 = {
    Text = "Getränkekarte? Ah, langweilig, öde, eintönig."
  },
  AvgDialog_131216_Content_28 = {
    Text = "Eine romantische Kneipe sollte solche langweiligen Dinge nicht haben."
  },
  AvgDialog_131216_Content_29 = {
    Text = "Keine Getränkekarte? Wie sollen wir dann bestellen?"
  },
  AvgDialog_131216_Content_3 = {
    Text = "Ich kann den Slogan der „Mitternachtsmasken\"-Bar auswendig. In Kardas war das der Ort, an den ich am liebsten gehen wollte."
  },
  AvgDialog_131216_Content_30 = {
    Text = "Jeder Platz im Mitternachtsmaskenball gehört einem einzelnen Gast im Theater. Ihr seid hier, um zuzusehen, die Aufführung zu genießen, und zu kosten..."
  },
  AvgDialog_131216_Content_31 = {
    Text = "In unzähligen Geschichten werde ich für Sie die passendste auswählen."
  },
  AvgDialog_131216_Content_32 = {
    Text = "Bitte setzen Sie sich, meine Herren. Der Leser der Geschichte ist bereits bereit."
  },
  AvgDialog_131216_Content_33 = {
    Text = "Du und Wilhelm schautet euch kurz an und saßt zögernd in der Nähe der Bar."
  },
  AvgDialog_131216_Content_34 = {
    Text = "Zuerst sind Sie, dieser ernstblickende blonde Herr."
  },
  AvgDialog_131216_Content_35 = {
    Text = "Der Barkeeper trat vor euch. Angesichts der aufmerksam prüfenden Augen räusperte sich Wilhelm leicht und wandte seinen Blick etwas unbehaglich ab."
  },
  AvgDialog_131216_Content_36 = {
    Text = "Ah ... Die tägliche, strenge Ausbildung hat so großartige Errungenschaften gebracht. Hartnäckigkeit, Ruhe, Ausdauer, Mut, Weisheit ... eine lebendige Legende, umgeben von Blumen und Ruhm."
  },
  AvgDialog_131216_Content_37 = {
    Text = "Und doch verbirgt sich hinter dem Lob und dem Heiligenschein... Bedauern. Ein Bedauern, tiefer und qualvoller als der Nebel, der diese Stadt erstickt."
  },
  AvgDialog_131216_Content_38 = {
    Text = "Wie viele Tränenlichter in der tiefen Nacht, die niemand sieht. Diese Versprechen, die man sich selbst zuflüstert."
  },
  AvgDialog_131216_Content_39 = {
    Text = "Das Licht, das dich einst im dunklen Gang erhellte, erlosch in der endlosen Dunkelheit und nahm deine Welt mit sich, zerbrach, zerbrach..."
  },
  AvgDialog_131216_Content_4 = {
    Text = "Sind die Verwaltungsregeln in Misaq manchmal vielleicht zu streng?"
  },
  AvgDialog_131216_Content_40 = {
    Text = "Du denkst bei dir: <Italic:Wenn ich nur härter gearbeitet hätte. Wenn ich nur stärker gewesen wäre... vielleicht hätte ich ein anderes Schicksal für meinen lieben Freund weben können.>"
  },
  AvgDialog_131216_Content_41 = {
    Text = "Wilhelms Ausdruck bleibt eine Maske der Gleichgültigkeit, doch dir fallen die hervortretenden Adern an seiner Hand auf, die das Glas mit weißen Knöcheln umklammert."
  },
  AvgDialog_131216_Content_42 = {
    Text = "Ich hörte das Geräusch einer Welt, die zerbrach. Der kleine Junge litt unter Schmerzen und sammelte die Stücke, um sie Stück für Stück wieder zusammenzufügen..."
  },
  AvgDialog_131216_Content_43 = {
    Text = "In dieser langen, grausamen Verbindung ist der Junge schließlich zum Mann geworden."
  },
  AvgDialog_131216_Content_44 = {
    Text = "Der Barkeeper erzählte mit einer tiefen Stimme leise, während er einige unterschiedlich geformte Flaschen von dem scheinbar grenzenlosen Regal hinter sich nahm, um Cocktails zu mixen."
  },
  AvgDialog_131216_Content_45 = {
    Text = "Bald wurde die hellgoldene Flüssigkeit, die in einem klassischen Becher serviert wurde, vor Wilhelm geschoben."
  },
  AvgDialog_131216_Content_46 = {
    Text = "2 Unzen Whiskey, 1 Unze Weißwein und die schmerzhafte und zähe Basis - 2 Tropfen Bitterstoffe."
  },
  AvgDialog_131216_Content_47 = {
    Text = "<Yellow:„Führer\">. Ich hoffe, Du wirst jene, die Dich verehren, gemeinsam mit Dir führen und den richtigen Weg finden — so wie jener, den Du verehrst, einst Dich geführt hat."
  },
  AvgDialog_131216_Content_48 = {
    Text = "Wilhelm nimmt den goldenen Drink entgegen und lässt ihn langsam kreisen, während er die Barkeeperin mit durchdringendem Blick mustert."
  },
  AvgDialog_131216_Content_49 = {
    Text = "Wie hast du das gerade gesagt... gewusst?"
  },
  AvgDialog_131216_Content_5 = {
    Text = "Ich schlage vor, dass die Schüler von Misaq ohne Genehmigung nicht in solche Orte eintreten dürfen, um zu verhindern, dass einige unzuverlässige Schutzherren im Namen von Ermittlungsaufträgen die Auftragsmittel verschwenden."
  },
  AvgDialog_131216_Content_50 = {
    Text = "Ein ausgezeichneter Barkeeper muss in der Lage sein, den Herzen der Gäste zuzuhören. Das ist das Geheimnis des Barkeeper, lieber Gast."
  },
  AvgDialog_131216_Content_51 = {
    Text = "Die Barkeeperin weicht Wilhelms Blick mit der Anmut eines Rehkitzes aus. Sie presst einen Finger an die Lippen in einer beschwichtigenden Geste und zeigt dann direkt auf dich."
  },
  AvgDialog_131216_Content_52 = {
    Text = "Jetzt sind Sie dran, dieser Gast..."
  },
  AvgDialog_131216_Content_53 = {
    Text = "Ich habe das Gefühl, dass dies möglicherweise das gefährlichste ist, was ich in meinem Leben versucht habe — aber das ist in Ordnung, ich liebe das Abenteuer."
  },
  AvgDialog_131216_Content_54 = {
    Text = "Sie beugt sich dicht heran und starrt dir eindringlich in die Augen. Du kannst beinahe den sanften Rhythmus ihres Atems hören."
  },
  AvgDialog_131216_Content_55 = {
    Text = "Hmm... was ich ansehe, ist ein Gast aus der Ferne, oder vielleicht... ein Gott, der in der Sterblichkeit gefallen ist und mit vielen Schwierigkeiten konfrontiert wurde?"
  },
  AvgDialog_131216_Content_56 = {Text = "?!!"},
  AvgDialog_131216_Content_57 = {
    Text = "Du stehst instinktiv auf und trittst zwei Schritte zurück."
  },
  AvgDialog_131216_Content_58 = {
    Text = "Das kann kein gewöhnlicher Barkeeper wissen... Wer bist du wirklich?"
  },
  AvgDialog_131216_Content_59 = {
    Text = "Sei unbesorgt, werter Gast. In dieser Bar bin nicht ich diejenige mit bösen Absichten."
  },
  AvgDialog_131216_Content_6 = {
    Text = "Schließlich hat dieser Schutzherr in seiner Schülerkarriere eine Menge Vorstrafen."
  },
  AvgDialog_131216_Content_60 = {
    Text = "Vielleicht ist dir aufgefallen, dass hinter dir einige deiner „alten Freunde\" gekommen sind."
  },
  AvgDialog_131216_Content_61 = {
    Text = "%player%, pass auf, hinter dir."
  },
  AvgDialog_131216_Content_62 = {
    Text = "Ich spüre es..."
  },
  AvgDialog_131216_Content_63 = {
    Text = "Unter der Erinnerung des Barkeepers bemerkst du, dass dutzende starke geistige Wellen schnell aus allen Richtungen auf euch zukommen."
  },
  AvgDialog_131216_Content_64 = {
    Text = "Wilhelm bewegt sich in perfekter Abstimmung, um deinen Rücken zu decken. Du umgreifst deinen Silberschlüssel fest, deine Augen auf den rätselhaften Barkeeper gerichtet."
  },
  AvgDialog_131216_Content_65 = {
    Text = "Der Barkeeper stellte das Glas in seiner Hand ab und stellte die Flasche auf einen unempfindlichen Platz auf dem Tisch."
  },
  AvgDialog_131216_Content_66 = {
    Text = "Ganz ruhig, %player%. Sie verfolgen dich schon seit einiger Zeit. Hier kann ich dir zumindest eine gewisse Hilfe anbieten."
  },
  AvgDialog_131216_Content_67 = {
    Text = "Du? Sie?......"
  },
  AvgDialog_131216_Content_68 = {
    Text = "Heh... Gefunden."
  },
  AvgDialog_131216_Content_69 = {
    Text = "Dieser schmutzige Ort ist kein Platz für einen langen Aufenthalt, meine kleinen Besucher aus der Ferne."
  },
  AvgDialog_131216_Content_7 = {
    Text = "Ich erinnere mich, dass in der Akte von Seniorstudent Fengol erwähnt wurde, dass sein größtes Hobby darin besteht, nach der Arbeit bis Mitternacht ein Glas im Maskenraum zu genießen..."
  },
  AvgDialog_131216_Content_70 = {
    Text = "Vorsicht, sie kommen"
  },
  AvgDialog_131216_Content_8 = {
    Text = "......Natürlich ist eine gelegentliche Pause nicht unbedingt eine schlechte Sache."
  },
  AvgDialog_131216_Content_9 = {
    Text = "Außerdem enthält das Mitgliederverzeichnis der Mitternachtsmaske die Prominenz von Lentiniën und ist der perfekte Ort zur Informationsbeschaffung."
  },
  AvgDialog_131217_Content_1 = {
    Text = "Die Macht der drei Plasmide hat sich in dir beruhigt, aber du hast deine Augen noch nicht geöffnet."
  },
  AvgDialog_131217_Content_10 = {
    Text = "Der Geist der Verträge, Geschäftsprinzipien... ein Handel erfordert ein Druckmittel. Du weißt, wie das funktioniert, oder?"
  },
  AvgDialog_131217_Content_11 = {
    Text = "„ N \" schüttelt den Kopf und kann sein Lachen kaum unterdrücken."
  },
  AvgDialog_131217_Content_12 = {
    Text = "Die gute Nachricht ist, du hast immer das perfekte Druckmittel."
  },
  AvgDialog_131217_Content_13 = {
    Text = "Ein tapferer Hüter, der kurz davor steht, {Male=his,Female=her} Glauben aufzugeben, ertrinkend im Netz des Schicksals—betrügend, schummelnd, völlig ohne Prinzipien... was für eine fesselnde Szene!"
  },
  AvgDialog_131217_Content_14 = {
    Text = "Ich würde den besten Platz im Haus um nichts in der Welt verpassen."
  },
  AvgDialog_131217_Content_15 = {
    Text = "Wann habe ich das gesagt..."
  },
  AvgDialog_131217_Content_16 = {
    Text = "Der Feiernde hat keine Geduld für deine Fragen. Er wägt die Schuld ab, die du in Zukunft haben wirst, und wedelt grinsend mit dem Finger."
  },
  AvgDialog_131217_Content_17 = {
    Text = "Das kann man nicht als Hinweis bezeichnen, sondern es ist nur ein kleiner und aufrichtiger Vorschlag."
  },
  AvgDialog_131217_Content_18 = {
    Text = "Warum sich gegen Nefraea auflehnen? Warum ihr nicht gehorchen, Schutzherr {Male=Herr, Female=Dame}?"
  },
  AvgDialog_131217_Content_19 = {
    Text = "„ N \" lächelt und beugt sich zu dir, so wohlwollend wie ein Anwalt, der einen Mandanten im Gefängnis besucht."
  },
  AvgDialog_131217_Content_2 = {
    Text = "Dein Bewusstsein taucht in das weite Meer des Geistes hinab, hinab, bis in die endlose Dunkelheit, bis in den Abgrund, der dir gehört und den du nicht mehr klar sehen kannst."
  },
  AvgDialog_131217_Content_20 = {
    Text = "Du... was sagst du? Nein, das kann ich auf keinen Fall..."
  },
  AvgDialog_131217_Content_21 = {
    Text = "Ah, genau, niemals aufgeben, niemals nachlassen, niemals die Taten von Nefraea anerkennen... alte und klassische Heldentum."
  },
  AvgDialog_131217_Content_22 = {
    Text = "Schicke uns zu Nefraea, beschwöre deinen geliebten Cousin, zurück in den Palast, der dir gehört... Was kannst du jetzt noch tun, %player%?"
  },
  AvgDialog_131217_Content_23 = {
    Text = "Ich gebe dir ein Geheimnis: Da du dem Netz nicht entkommen kannst, warum öffnest du nicht deine Arme und begrüßt das Netz, das kommt?"
  },
  AvgDialog_131217_Content_24 = {
    Text = "Hör auf zu träumen, „ N \". Ich könnte niemals..."
  },
  AvgDialog_131217_Content_25 = {
    Text = "Pssst. Setze dir nicht so leicht Grenzen, mein Lieber."
  },
  AvgDialog_131217_Content_26 = {
    Text = "Vergiss nicht, Arachne hat dein Schicksal mit dem großen Netz verbunden. Du bist bereits ein Teil von ihnen."
  },
  AvgDialog_131217_Content_27 = {
    Text = "Diese Person, die Göttin des Schicksals, hat dir einen Schlüssel mit dem Namen Freude gegeben. Hast du dir jemals überlegt, wohin diese Tür führt und was sie öffnet?"
  },
  AvgDialog_131217_Content_28 = {
    Text = "Wohin die Tür zeigt... wohin sie führt...?"
  },
  AvgDialog_131217_Content_29 = {
    Text = "Ich dachte, Arachne sei eine fleißige, freundliche und unauffällige Dame, deren einzige Fähigkeiten das Weben von Netzen und das Lächeln waren. Aber sie ist viel interessanter, als ich mir vorgestellt hatte."
  },
  AvgDialog_131217_Content_3 = {
    Text = "Du kämpfst darum, deinen nicht vorhandenen Mund weit zu öffnen und rufst wütend und lautlos in diesem Abgrund."
  },
  AvgDialog_131217_Content_30 = {
    Text = "Sie hat ein riesiges Netz für diese Bühne gewebt, das von dem Moment an für dich ausgelegt wurde, als du in diese Welt kamst."
  },
  AvgDialog_131217_Content_31 = {
    Text = "Solche hervorragenden Fähigkeiten zu haben und sich mit so dummen Dingen wie der Aufrechterhaltung des Weltenbetriebs zu beschäftigen... Schade, es ist wirklich schade."
  },
  AvgDialog_131217_Content_32 = {
    Text = "Betritt die Bühne des Schicksalstheaters, wirst du zu einer Figur auf der Bühne. Jede Figur hat ihr eigenes Leben."
  },
  AvgDialog_131217_Content_33 = {
    Text = "Das Schicksal lässt dich diese Wahl treffen, um dir zu zeigen, wie es ist. Du kannst die Fäden nicht sehen, aber jetzt verstehst du, auf welche komplexe Weise sie verwoben sind."
  },
  AvgDialog_131217_Content_34 = {
    Text = "Die Fäden des Schicksals weben ein riesiges Netz, jede zarte Erschütterung eines Fadens könnte das Netz des Schicksals zum Wanken bringen."
  },
  AvgDialog_131217_Content_35 = {
    Text = "Dies ist das Schicksal, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131217_Content_36 = {
    Text = "Aufführung, Täuschung, Freude... In dir steckt eine solche Kraft. Die Bühne des Schicksals bietet nicht jedem die Gelegenheit. Wenn du die Bühne betreten musst, werden dir diese Kräfte helfen."
  },
  AvgDialog_131217_Content_37 = {
    Text = "Du kannst dich nicht vor den Rollen verstecken, die du spielen sollst. Denke nach, dann spiele, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131217_Content_38 = {
    Text = "„Freude\"."
  },
  AvgDialog_131217_Content_39 = {
    Text = "In deiner kurzen Zukunft ist „Freude\" ein Schlüssel, der das Geheimnis öffnet, dem du gegenüberstehst."
  },
  AvgDialog_131217_Content_4 = {Text = "„ N \"!"},
  AvgDialog_131217_Content_40 = {
    Text = "...Egal was passiert, vertraue mir und vertraue dir selbst."
  },
  AvgDialog_131217_Content_41 = {
    Text = "Kehrt zurück zum Theater des Schicksals. Der Schlüssel und das Schloss erwarten Euch dort, %player%."
  },
  AvgDialog_131217_Content_42 = {
    Text = "Die Worte von Arachne ziehen wie Fäden durch dein Gehirn und verweben sich. Schließlich bilden sie ein riesiges, dichtes Netz."
  },
  AvgDialog_131217_Content_43 = {
    Text = "Du verstehst endlich, dass Arachne seit dem ersten Treffen durch die Zeit mit dir spricht, so wie du jetzt bist."
  },
  AvgDialog_131217_Content_44 = {
    Text = "Du staunst über das präzise Netz, als ob etwas sehr Wichtiges in deinem Kopf allmählich Gestalt annimmt."
  },
  AvgDialog_131217_Content_45 = {
    Text = "Aufführung, Täuschung, Vergnügen..."
  },
  AvgDialog_131217_Content_46 = {
    Text = "Ah, genau. Versuche niemals zu verstehen. Genieße sie, das ist das einzige Geheimnis der Freude."
  },
  AvgDialog_131217_Content_47 = {
    Text = "Freude und Leid, Gut und Böse, alle Gefühle und Moralvorstellungen existieren nicht mehr. Außer dem Genuss gibt es nichts."
  },
  AvgDialog_131217_Content_48 = {
    Text = "Jetzt, sag mir... verstehst du „Freude\", Schutzherr?"
  },
  AvgDialog_131217_Content_49 = {
    Text = "„ N \"s purpurrotes Lächeln verblasst aus deinem Geist. Du siehst einen Spiegel, und darin spiegelt sich dein eigenes lachendes Gesicht."
  },
  AvgDialog_131217_Content_5 = {
    Text = "Pssst... Deine Stimme ist zu laut, Hüter des Geheimnisses."
  },
  AvgDialog_131217_Content_50 = {
    Text = "Freude?... Freude..."
  },
  AvgDialog_131217_Content_51 = {
    Text = "Hehehe... Hahahaha. Genau, Freude, mein Freund"
  },
  AvgDialog_131217_Content_52 = {
    Text = "Das wunderbarste Wort in dieser Welt, die gesamte Bedeutung dieses Traums..."
  },
  AvgDialog_131217_Content_53 = {
    Text = "Als ob er einen flüchtigen Blick auf die Szene erhascht, die sich gleich entfalten wird, erzittert Ns ganzer Körper vor Entzücken. Er presst einen in dunklen Nebel gehüllten Finger gegen seine eigene Stirn."
  },
  AvgDialog_131217_Content_54 = {
    Text = "Du bist fast angekommen. Nur noch ein Schritt, der letzte Schritt... Denk gut nach und tritt dann in das Netz ein, Schutzherr."
  },
  AvgDialog_131217_Content_55 = {
    Text = "Der Weg der Freude liegt darin."
  },
  AvgDialog_131217_Content_6 = {
    Text = "„ N \"s Phantasma verweilt. Er erscheint mühelos in deinem mentalen Raum und wirkt wie der unangefochtene Herrscher des Reichs."
  },
  AvgDialog_131217_Content_7 = {
    Text = "Die „Freude\", von der Arachne spricht, muss auf dich gerichtet sein"
  },
  AvgDialog_131217_Content_8 = {
    Text = "„„ N „,„ gib mir einen Hinweis..."
  },
  AvgDialog_131217_Content_9 = {
    Text = "Hinweis? Hahahaha... Was habe ich getan, dass du mich so demütigst?"
  },
  AvgDialog_131218_Content_10 = {
    Text = "Du... was soll das?"
  },
  AvgDialog_131218_Content_11 = {
    Text = "Betrunkene Mittelschicht, junge Damen, wohlhabende Gentlemen, Gangmitglieder auf der Straße, erschöpfte Kellner, schöne Barkeeperin..."
  },
  AvgDialog_131218_Content_12 = {
    Text = "Jedes Gesicht in der Bar — jung, alt, hübsch oder gewöhnlich — wendet sich gleichzeitig zu dir, ihre Mienen so identisch wie Durchschlagkopien."
  },
  AvgDialog_131218_Content_13 = {
    Text = "Das sind keine Individuen. Sie sind eher wie..."
  },
  AvgDialog_131218_Content_14 = {
    Text = "Diejenigen, die noch vor wenigen Augenblicken so voller Leben schienen, stehen nun wie leblose Holzpuppen vor euch."
  },
  AvgDialog_131218_Content_15 = {
    Text = "...Eher wie Marionetten, gefangen in einem Netz."
  },
  AvgDialog_131218_Content_16 = {
    Text = "Ich habe schon von Ihrer scharfen Beobachtungsgabe gehört, Herr William."
  },
  AvgDialog_131218_Content_17 = {
    Text = "Was ihr vor euch seht, sind lediglich Requisiten auf einer Bühne—Spiegelbilder in einem Spiegel."
  },
  AvgDialog_131218_Content_18 = {
    Text = "Bitte entschuldigt. Ich kann mein Netz noch nicht verlassen. Ich muss diese Gefäße nutzen, um mit euch zu sprechen."
  },
  AvgDialog_131218_Content_19 = {
    Text = "Willkommen auf meiner Bühne, Herr Wilhelm... und Ihr, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131218_Content_2 = {
    Text = "Das ist gelöst, was sind diese Dinge..."
  },
  AvgDialog_131218_Content_20 = {
    Text = "Jedes Wort wird mit beunruhigender Präzision vorgetragen; zwanzig verschiedene Stimmen verweben sich zu einem einzigen, kalten Stimmfaden."
  },
  AvgDialog_131218_Content_21 = {
    Text = "Alle im Raum verbeugen sich in perfektem Gleichklang. Der Winkel ihrer Wirbelsäulen und die Haltung ihrer Hände sind mit unnatürlicher Genauigkeit gespiegelt."
  },
  AvgDialog_131218_Content_22 = {
    Text = "Deine... Bühne? Wer bist du wirklich?"
  },
  AvgDialog_131218_Content_23 = {
    Text = "Er ist der Meister hier und ein Gefangener."
  },
  AvgDialog_131218_Content_24 = {
    Text = "Ich denke, Sie haben sicherlich viele Fragen."
  },
  AvgDialog_131218_Content_25 = {
    Text = "Es ist hier nicht sicher, ihre Leute werden schnell nachkommen. Meine Zofe wird euch empfangen, bitte bleibt ruhig, wenn ihr sie seht."
  },
  AvgDialog_131218_Content_26 = {
    Text = "Nach dem Treffen werde ich alle Fragen der beiden einzeln beantworten."
  },
  AvgDialog_131218_Content_27 = {
    Text = "In dem Moment, als diese Worte ihre Lippen verlassen, scheint das Bewusstsein der Menge augenblicklich zu schwinden."
  },
  AvgDialog_131218_Content_28 = {
    Text = "Das Kristallglas eines Herrn erstarrt an seinen Lippen; der geöffnete Fächer einer Dame verharrt knapp unter ihrem Kinn; der Barkeeper bleibt reglos, das Glas in die Höhe gehalten."
  },
  AvgDialog_131218_Content_29 = {
    Text = "Als ob ihre Fäden alle auf einmal durchtrennt wurden, halten alle ihre letzte Pose—Wachsfiguren, erstarrt an Ort und Stelle."
  },
  AvgDialog_131218_Content_3 = {
    Text = "Vorsicht hinter dir!!......"
  },
  AvgDialog_131218_Content_30 = {
    Text = "Ihr atmet langsam ein und blickt euch unbehaglich in dem Meer aus „Marionetten\" um, jede erstarrt mit demselben, unveränderlichen Lächeln."
  },
  AvgDialog_131218_Content_31 = {
    Text = "Obwohl sie mir gerade wirklich geholfen haben, kann ich es einfach nicht ganz glauben..."
  },
  AvgDialog_131218_Content_32 = {
    Text = "Wilhelm, der Seniorstudent, wir möchten wissen, dass dieser „Herr\" vielleicht der beste Antwortgeber ist."
  },
  AvgDialog_131218_Content_33 = {
    Text = "Selbst wenn es gefährlich ist, denke ich, dass ich gehen muss, nur..."
  },
  AvgDialog_131218_Content_34 = {
    Text = "Ich verstehe."
  },
  AvgDialog_131218_Content_35 = {
    Text = "Als Wilhelm deinen Blick sah, nickte er verständnisvoll."
  },
  AvgDialog_131218_Content_36 = {
    Text = "Ich werde draußen die Bewegungen der Schatten untersuchen, sie suchen nach dir, und mein Aufenthalt draußen wird sicherer sein als deiner."
  },
  AvgDialog_131218_Content_37 = {
    Text = "Dieser„Meister\"ist unbekannter Herkunft, falls er in Gefahr gerät..."
  },
  AvgDialog_131218_Content_38 = {
    Text = "William tippte sanft auf das Schullogo an seiner Brust. In dieser Welt seid ihr die einzigen, die über das Schullogo miteinander in Kontakt treten können."
  },
  AvgDialog_131218_Content_39 = {
    Text = "Verstanden... du auch, Wilhelm-Seniorstudent."
  },
  AvgDialog_131218_Content_4 = {
    Text = "Ein starkes Gefühl der Bedrohung lässt dich sofort aufwachen. Du drehst dich plötzlich um und siehst die Klinge, die aus Schatten vor dir geformt ist, nur wenige Zentimeter entfernt."
  },
  AvgDialog_131218_Content_40 = {
    Text = "„Meister\" versteht Ihre Vorsicht. Herr Wilhelm, diese Bühne birgt jetzt viele Gefahren, bitte seien Sie vorsichtig. In unserem Rahmen werden wir Ihnen die notwendige Unterstützung bieten."
  },
  AvgDialog_131218_Content_41 = {
    Text = "Blassviolette Spinnen strömen aus jeder Ecke der Bar zusammen, und ein Dienstmädchen mit spinnenartigen Zügen erscheint lautlos hinter euch allen. Nachdem sie sich höflich vor euch verneigt hat, geht sie zur Tür."
  },
  AvgDialog_131218_Content_42 = {
    Text = "{Male=Mr.,Female=Miss} Schutzherr, bitte folgt mir. Die Herrin erwartet Euch."
  },
  AvgDialog_131218_Content_5 = {Text = "Zisch—"},
  AvgDialog_131218_Content_6 = {
    Text = "Langsam senkst du den Arm, den du unwillkürlich vor deine Augen gehoben hattest. Der Schatten wird von der Person hinter dir durchtrennt, schwarze, klebrige Flüssigkeit spritzt und bespritzt deinen ganzen Körper."
  },
  AvgDialog_131218_Content_7 = {
    Text = "Entschuldigung, dass ich euch erschreckt habe."
  },
  AvgDialog_131218_Content_8 = {
    Text = "Sie haben ständig nach Ihren Spuren gesucht. Hier kann meine Kraft Ihnen ein wenig helfen."
  },
  AvgDialog_131218_Content_9 = {
    Text = "Ohne Ihre Zustimmung habe ich euch hierher geführt, ich hoffe, ihr seid nicht verärgert."
  },
  AvgDialog_131219_Content_1 = {
    Text = "Ist das... ist es vorbei?"
  },
  AvgDialog_131219_Content_2 = {
    Text = "Sei vorsichtig, Hüter... die Spindel, die das Schicksal entwirrt, hat bereits begonnen, sich hinter ihr zu drehen..."
  },
  AvgDialog_131219_Content_3 = {
    Text = "Heh... hahahaha...!"
  },
  AvgDialog_131220_Content_1 = {
    Text = "Schwanenflug"
  },
  AvgDialog_131220_Content_10 = {
    Text = "Du erinnerst dich an das große Tor mit etwas Rost, das bei jeder Bewegung ein dumpfes Geräusch von sich gibt, wie der sanfte Atem deines Großvaters."
  },
  AvgDialog_131220_Content_11 = {
    Text = "Die Miskatonic-Universität..."
  },
  AvgDialog_131220_Content_12 = {
    Text = "In dieser vertrauten Umgebung streichelst du den völlig anderen Namen auf dem Schild des Platzes."
  },
  AvgDialog_131220_Content_13 = {
    Text = "Jeder Schauspieler hat seine eigene, geliebte Bühne. Selbst eine von Erinnerungen replizierte Schule ist für dich unersetzlich."
  },
  AvgDialog_131220_Content_14 = {
    Text = "Warum sollte man einen Ort schaffen, der genau wie Misaq ist..."
  },
  AvgDialog_131220_Content_15 = {
    Text = "Ich habe es nicht erschaffen, es sollte einfach hier sein. Wie diese Stadt und diese Welt sind sie alle Teil des Netzes des Schicksals."
  },
  AvgDialog_131220_Content_16 = {
    Text = "Schau nicht so weit voraus, %player%. Wenn du auf einer Bühne stehst, gibt es einen Grund, warum du hier bist."
  },
  AvgDialog_131220_Content_17 = {
    Text = "Übrigens, obwohl ich so lange mit Liz zusammen war, habe ich noch nie ihre offizielle Aufführung live gesehen..."
  },
  AvgDialog_131220_Content_18 = {
    Text = "Du schaust dich auf dem vertrauten Platz um und streichst sanft mit deinen Händen über das Gras darunter."
  },
  AvgDialog_131220_Content_19 = {
    Text = "Der wunderbarste Moment im Leben ist der, in dem man nicht merkt, dass man lächelt."
  },
  AvgDialog_131220_Content_2 = {
    Text = "Es ist wirklich selten, dass die Ticketpreise für dieses Tanzensemble im Theater mich zwei Monatsgehälter kosten."
  },
  AvgDialog_131220_Content_20 = {
    Text = "Ah... Entschuldigung..."
  },
  AvgDialog_131220_Content_21 = {
    Text = "Erinnerst du dich an die Dinge, die mit Misaq zu tun haben?"
  },
  AvgDialog_131220_Content_22 = {
    Text = "Auf diesem Platz haben wir viele Aufführungen innerhalb der Schule veranstaltet. Damals waren, wie jetzt, die Schüler von Misaq den Platz überfüllt."
  },
  AvgDialog_131220_Content_23 = {
    Text = "Viele Erwachte haben eine sehr tiefe Kunstfertigkeit. Zu Beginn waren viele nicht bereit, in solchen Veranstaltungen aufzutreten, und die Lehrer der Akademie und ich haben uns verschiedene Methoden überlegt..."
  },
  AvgDialog_131220_Content_24 = {
    Text = "Später begannen viele von ihnen auch aktiv, für ihre Gefährten hier eine Darbietung zu machen."
  },
  AvgDialog_131220_Content_25 = {
    Text = "Liz' Tanz, Tincts Lied, Hamelns Symphonie, Horlas Poesie, Sangas Skulpturen..."
  },
  AvgDialog_131220_Content_26 = {
    Text = "Ich weiß nicht, ob das Leben in Misaq nach meinem Weggang wieder so geworden ist wie früher..."
  },
  AvgDialog_131220_Content_27 = {
    Text = "Der Vorhang bewegt sich! Der Vorhang bewegt sich! Miss Liz wird gleich auf die Bühne kommen!"
  },
  AvgDialog_131220_Content_28 = {
    Text = "Du schüttelst den Kopf und vertreibst die traurigen Gedanken aus deinem Kopf."
  },
  AvgDialog_131220_Content_29 = {
    Text = "Wie auch immer, es ist ein glücklicher Umstand, Liz in dieser fernen Welt wieder tanzen zu sehen."
  },
  AvgDialog_131220_Content_3 = {
    Text = "Es heißt, dass die Wohltätigkeitsaufführung von Frau Sorel persönlich gesponsert wurde! Wenn nur jeder Herr und jede Dame in dieser Stadt so ein gutes Herz hätte"
  },
  AvgDialog_131220_Content_30 = {
    Text = "Sobald diese Angelegenheit endgültig geklärt ist, möchte ich, wenn ich Zeit habe, in Ruhe mit ihnen sprechen."
  },
  AvgDialog_131220_Content_31 = {
    Text = "Meine Damen und Herren... Willkommen zu unserer Aufführung"
  },
  AvgDialog_131220_Content_32 = {
    Text = "Das Schwanenballett, welch heiliges und unerreichbares Name! Dieser edelste weiße Schwan von Lentini wird heute zum ersten Mal vor der Öffentlichkeit von Lentini erscheinen"
  },
  AvgDialog_131220_Content_33 = {
    Text = "Vielen Dank für eure Geduld. Unsere Schauspieler sind bereit. Eine großartige Aufführung wird euch bald präsentiert"
  },
  AvgDialog_131220_Content_34 = {
    Text = "Mit dem klaren Fingerschnipsen des Ansagers erloschen alle Lichter in der Umgebung, und mehrere Scheinwerfer richteten sich auf die Mitte des Bildschirms."
  },
  AvgDialog_131220_Content_35 = {
    Text = "Nun, genießen Sie den Tanz, präsentiert von Fräulein Liz, der Schwan – im Flug!"
  },
  AvgDialog_131220_Content_36 = {
    Text = "Im begeisterten Applaus und Jubel der Menge hebt sich der Vorhang langsam —"
  },
  AvgDialog_131220_Content_37 = {
    Text = "<Big:<Red:!!!!>>"
  },
  AvgDialog_131220_Content_38 = {
    Text = "Du hast Liz schon oft gesehen."
  },
  AvgDialog_131220_Content_39 = {
    Text = "Auf der Bühne des Zeremonienraums von Misaq dreht sie sich nur für dich."
  },
  AvgDialog_131220_Content_4 = {
    Text = "Obwohl ich es nicht verstehe, darf ich diese Gelegenheit nicht verpassen."
  },
  AvgDialog_131220_Content_40 = {
    Text = "Unter dem Sternenhimmel von Lentiniën berührte sie mit ihren auf den Zehenspitzen stehenden Füßen das tanzende Glühlicht am Nachthimmel."
  },
  AvgDialog_131220_Content_41 = {
    Text = "Im sanften Wind der Charing Cross Straße hebt sich ihr Rock hoch, wie eine aufbrausende Flamme."
  },
  AvgDialog_131220_Content_42 = {
    Text = "Und heute steht sie auf der Bühne in einem fernen Land vor dir, in einer Pose, die du noch nie zuvor gesehen hast."
  },
  AvgDialog_131220_Content_43 = {
    Text = "Der Hauptstar des Schwanentanzensembles, das strahlendste Feuerwerk der ganzen Stadt. Schwarze Dornen durchbohren ihre Luftröhre, Arme, Brust und Bauch, sowie ihre auf den Zehenspitzen stehenden Füße, durchdringen ihren Körper, der den Tanz beherrscht."
  },
  AvgDialog_131220_Content_44 = {
    Text = "Blut spritzt und malt ein Paar blutrote Flügel auf die Rückwand hinter ihr, während es einige grausame Kratzer auf ihrem gelassen lächelnden Gesicht hinterlässt."
  },
  AvgDialog_131220_Content_45 = {
    Text = "Die Menge war still und lautlos, der Wind wehte über den weiten Platz, der schwarz-grüne Tanzrock wirbelte in der Luft, wie ein ewiges brennendes Feuer."
  },
  AvgDialog_131220_Content_46 = {
    Text = "—— In diesem Moment wurde dir vollständig klar, dass, wenn der Tod unausweichlich ist, dies die Art von Tod ist, die Liz sich am sehnlichsten wünscht."
  },
  AvgDialog_131220_Content_47 = {
    Text = "Sie vollendete eine Abschiedsvorstellung mit Blut und Leben. Ihr Tanz blieb in dem schönsten Sprung stehen, gleich einer fliegenden schwarzen Schwäne."
  },
  AvgDialog_131220_Content_48 = {
    Text = "Fräulein Liz' Tanzbewegungen, wie elegant, wie schön"
  },
  AvgDialog_131220_Content_49 = {
    Text = "Genießt es in Ruhe, meine lieben Zuschauer! Es ist eure einzige Ehre in diesem Leben, dieses Schauspiel mit eigenen Augen zu sehen."
  },
  AvgDialog_131220_Content_5 = {
    Text = "Dreißig Jahre... Ich habe seit dreißig Jahren keine Aufführung im Theater mehr gesehen..."
  },
  AvgDialog_131220_Content_50 = {
    Text = "Du siehst das in zwei Hälften gerissene Gesicht des Ansagers. Das ausdruckslose Gesicht des Mannes mittleren Alters schmilzt wie Schleim und gibt die von Begeisterung erfüllten Augen der Nefraea preis."
  },
  AvgDialog_131220_Content_51 = {
    Text = "Inmitten des Chaos der schreienden und fliehenden Menge durchbohrt ihr scharfer Gelächter dein Trommelfell wie ein giftiger Pfeil."
  },
  AvgDialog_131220_Content_52 = {
    Text = "<Big:Liz!!>"
  },
  AvgDialog_131220_Content_53 = {
    Text = "Du drängst dich durch die erschreckte Menge und läufst vor die Bühne."
  },
  AvgDialog_131220_Content_54 = {
    Text = "Ah, dieser kluge Gast, wie haben Sie gewusst, dass diese Tanzaufführung noch einen zweiten Akt hat?"
  },
  AvgDialog_131220_Content_55 = {
    Text = "Um die Bühne herum nähern sich schnell einige Zuschauer, die nicht geflohen sind. Ihre Körper zerreißen beim Laufen und lassen die unaufhörlich mordenden schwarzen Spinnen-Diener herauskriechen."
  },
  AvgDialog_131220_Content_56 = {
    Text = "Auf der Bühne vor dir hat Liz ihren Körper von den Dornen gelöst. Ein Kunstwerk, hergestellt von Heiden, mit grausamen Hohlräumen und lebhaftem Blut."
  },
  AvgDialog_131220_Content_57 = {
    Text = "Blutige Fußabdrücke erstrecken sich von der Mitte der Bühne. Liz geht auf dich zu, ihr Gesicht in eine grauenhafte, atemberaubende Maske aus Blut gemalt, die dir den Atem raubt."
  },
  AvgDialog_131220_Content_58 = {
    Text = "Sie blickte zu dir auf. Ihre leeren, blutdurchtränkten Augen erinnerten dich an all die Kunstwerke, die es wert sind, überliefert zu werden."
  },
  AvgDialog_131220_Content_59 = {
    Text = "Nun, Zeit für einen Tanz mit deinem alten Freund... {Male=Mr.,Female=Miss} Schutzherr!"
  },
  AvgDialog_131220_Content_6 = {
    Text = "Ballett, der reinste Tanz dieser Welt, verstehen nur die, die ihn wirklich getanzt haben, wie schön diese grausame Eleganz ist"
  },
  AvgDialog_131220_Content_7 = {
    Text = "Dass ich Miss Liz live sehen kann, ist etwas, von dem ich nicht einmal im Traum gedacht hätte..."
  },
  AvgDialog_131220_Content_8 = {
    Text = "Die Umgebungsgeräusche, die eigentlich laut sein sollten, vermischen sich in deinen Ohren zu einem fernen weißen Rauschen."
  },
  AvgDialog_131220_Content_9 = {
    Text = "Du erinnerst dich an die Wiese, an den See. Du erinnerst dich an die unregelmäßig angeordneten Unterrichtsgebäude und an die Statue, die mit festem Blick in die Ferne schaut."
  },
  AvgDialog_131221_Content_1 = {Text = "Zweite Akt"},
  AvgDialog_131221_Content_10 = {
    Text = "Ich bin ein Gefangener des Schicksals, das ist nur meine Pflicht, die ich erfüllen muss."
  },
  AvgDialog_131221_Content_11 = {
    Text = "Eine Person, die das Schicksal unzähliger Welten lenken kann, könnte sich vielleicht treffender als Richter oder Aufseher des Schicksals bezeichnen?"
  },
  AvgDialog_131221_Content_12 = {
    Text = "In der Gefängnis des Schicksals gibt es keinen Unterschied zwischen Wärter und Gefangenen."
  },
  AvgDialog_131221_Content_13 = {
    Text = "Herr William, kommt Ihnen die Reise bis jetzt angenehm vor?"
  },
  AvgDialog_131221_Content_14 = {
    Text = "Dank Ihrer Zofe, würde ich allein mehr Preis zahlen müssen, um die Diener aus den Schatten loszuwerden."
  },
  AvgDialog_131221_Content_15 = {
    Text = "Nefraea... Hast du wieder jemanden getroffen, der sie kennt?"
  },
  AvgDialog_131221_Content_16 = {
    Text = "Wilhelm nickte ernst."
  },
  AvgDialog_131221_Content_17 = {
    Text = "Als wir getrennt wurden, bin ich auf einige Passanten gestoßen, die mir... seltsam vorkamen. Ich bin ihnen eine Weile gefolgt und habe Bruchstücke ihres Gesprächs aufgeschnappt."
  },
  AvgDialog_131221_Content_18 = {
    Text = "Sie suchen nach etwas, das als „Geheimeinheit\" bezeichnet wird."
  },
  AvgDialog_131221_Content_19 = {
    Text = "Ich denke... das, was ihr gerade über die Verschmutzung des Schicksals der Bühne gesprochen habt, könnte vielleicht nur ein Mittel zur Vorbereitung sein."
  },
  AvgDialog_131221_Content_2 = {
    Text = "Ganz schönes Spektakel..."
  },
  AvgDialog_131221_Content_20 = {
    Text = "Diese „geheimen Objekte\" sind das wahre Ziel von ihnen."
  },
  AvgDialog_131221_Content_21 = {
    Text = "Meine Schwester hat ihre eigene Schicksalsleine zusammen mit der ihrer Knappen verborgen; ich kann sie nicht ohne Weiteres wahrnehmen. Das ist eine äußerst wertvolle Information, Herr Wilhelm."
  },
  AvgDialog_131221_Content_22 = {
    Text = "Die nächste Aktion werde ich mit euch zusammen durchführen......"
  },
  AvgDialog_131221_Content_23 = {Text = "Nein!"},
  AvgDialog_131221_Content_24 = {
    Text = "Nein, du musst bleiben! Die Trennung vorhin war eine Notwendigkeit, aber ich werde nicht riskieren, dass sich wiederholt, was in Lemvah geschehen ist."
  },
  AvgDialog_131221_Content_25 = {
    Text = "Der Schutzherr hat recht. Meine Zofe wird die Giftstoffe in eurem Körper behandeln. Bis ihr vollständig genesen seid, bleibt bitte im Theater und ruht euch aus."
  },
  AvgDialog_131221_Content_26 = {
    Text = "Bald werden wir den Tag erleben, an dem wir deine Hilfe brauchen."
  },
  AvgDialog_131221_Content_27 = {
    Text = "Die Worte von Arachne sind wie ein sanftes Urteil, das mühelos Körper und Seele durchdringt und sanft in Wilhelms Schicksal fällt."
  },
  AvgDialog_131221_Content_28 = {
    Text = "William warf einen Blick auf das aus dem Bauch sickernde Blut und nickte leicht."
  },
  AvgDialog_131221_Content_29 = {
    Text = "Wenn ich jetzt ginge, wäre ich nur eine Last. Sei unbesorgt, ich werde dafür sorgen, dass ich bereit bin, wenn der Tag kommt."
  },
  AvgDialog_131221_Content_3 = {
    Text = "<Shake:Hust hust...>"
  },
  AvgDialog_131221_Content_30 = {
    Text = "Arachne lächelte und streckte ihre Hand aus. Eine, zwei... unzählige Spinnen krochen aus ihren Ärmeln und fielen an einem Faden zu Boden."
  },
  AvgDialog_131221_Content_31 = {
    Text = "Die Spinnen fallen wie Regen herab, strömen zusammen und schwärmen ineinander. Die Masse der Spinnentiere überlappt sich zu einer menschlichen Silhouette, während Farbe und Licht sich an die sich wandelnde Form heften."
  },
  AvgDialog_131221_Content_32 = {
    Text = "Bald steht eine neue, identische Arachne vor dir."
  },
  AvgDialog_131221_Content_33 = {
    Text = "Folge mir, {Male=Mr.,Female=Miss} Schutzherr. Ich glaube, die Zeit für ein persönliches Treffen mit meiner Schwester ist gekommen."
  },
  AvgDialog_131221_Content_34 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131221_Content_35 = {
    Text = "In dieser Stadt gibt es viele Geschäfte, die ich liebe, aber genau wie du ist dies auch einer meiner liebsten Orte."
  },
  AvgDialog_131221_Content_36 = {
    Text = "Mitternachtsmaske-Taverne, du sitzt an deinem Platz von letztem Mal und schaust mit zusammengekniffenen Augen auf Arachne, die sich umschaut."
  },
  AvgDialog_131221_Content_37 = {
    Text = "Also, was bist du jetzt eigentlich... eine Puppe? Ein Doppelgänger? Eine geheimnisvolle Maschine, die aus einer Gruppe von Spinnen zusammengesetzt ist und dir beim Ausreißen hilft?"
  },
  AvgDialog_131221_Content_38 = {
    Text = "Im Wesentlichen bin ich hier und ich im Theater das Schicksal mit zwei unterschiedlichen Erfahrungen im gleichen Moment."
  },
  AvgDialog_131221_Content_39 = {
    Text = "Der Großteil meiner Stärke muss im Theater bleiben, um das riesige Netz des Schicksals weiter zu weben. Abgesehen davon gibt es keinen Unterschied zwischen uns. Lass uns diesen Moment nicht wegen Zweifel zerstören, Schutzherr."
  },
  AvgDialog_131221_Content_4 = {
    Text = "Der Klang zieht an der Wunde, Wilhelm hält seinen mit Bandagen umwickelten Bauch fest und kann nicht anders, als zu husten."
  },
  AvgDialog_131221_Content_40 = {
    Text = "Arachne lächelte ruhig, während die Eiswürfel sanft im schaukelnden Glas klirrten."
  },
  AvgDialog_131221_Content_41 = {
    Text = "Wissen Sie, dass diese Taverne jeden Monat einen Maskenball veranstaltet, bei dem jeder Gast, der hereinkommt, seine interessanteste Maske tragen muss."
  },
  AvgDialog_131221_Content_42 = {
    Text = "Die gesellschaftlichen Veranstaltungen der Oberschicht können diesen Ort oft langweilig machen, aber an diesem Tag wird er der interessanteste Ort in dieser Stadt sein."
  },
  AvgDialog_131221_Content_43 = {
    Text = "Vielleicht sollte ich beim nächsten Maskenball alles loslassen und es ernsthaft erleben."
  },
  AvgDialog_131221_Content_44 = {
    Text = "Ich dachte, jemand, der die Entwicklung des Schicksals sehen kann, hätte kein Interesse mehr an allem, was die Zukunft betrifft."
  },
  AvgDialog_131221_Content_45 = {
    Text = "Das stimmt, %player%. Allerdings habe ich schon vor langer Zeit einen Weg gefunden, die Langeweile zu vertreiben."
  },
  AvgDialog_131221_Content_46 = {
    Text = "Manchmal komme ich von hinter dem Vorhang nach vorne auf die Bühne, betrete die von mir geschaffene Bühne und werde selbst zu einer der Figuren."
  },
  AvgDialog_131221_Content_47 = {
    Text = "Verdecke deinen Blick auf das Schicksal, stelle dich vollständig auf die Bühne und fühle den Fluss der Zeit und die Wendung des Schicksals im Detail..."
  },
  AvgDialog_131221_Content_48 = {
    Text = "Das ist eine seltene Pause. Solche Gelegenheiten sind nicht häufig, jedes Mal betrachte ich sie als ein äußerst wertvolles Fest."
  },
  AvgDialog_131221_Content_49 = {
    Text = "Arachne sprach, während sie mit großem Interesse die prächtigen Gäste und die sanften Diener betrachtete, das schummrige Licht der Taverne spielte in Arachne's Augen."
  },
  AvgDialog_131221_Content_5 = {
    Text = "Wilhelm-Senpai?! Du bist verletzt"
  },
  AvgDialog_131221_Content_50 = {
    Text = "Selbst so... wir sollten doch nach diesen „geheimen Objekten\" suchen, oder? Warum sind wir hierher gekommen?"
  },
  AvgDialog_131221_Content_51 = {
    Text = "Eine von ihnen ist hier. Sie haben sie bald... ach nein, Sie haben sie schon getroffen."
  },
  AvgDialog_131221_Content_52 = {
    Text = "Hallo, liebe Gäste."
  },
  AvgDialog_131221_Content_53 = {
    Text = "Der Klang von mit Honig mariniertem. Mit Porzellan gemeißelte Finger. Auf dem nackten Hals der strahlende Duft von Jasmin und Akazie. Und diese Augen, die wie Neonlichter blitzen und alles durchdringen können."
  },
  AvgDialog_131221_Content_54 = {
    Text = "Ah, ich erinnere mich an dich, %player%, die Elegante."
  },
  AvgDialog_131221_Content_55 = {
    Text = "Die Kreatur im Schatten, blendendes silbernes Licht... Was für eine großartige Heldengeschichte"
  },
  AvgDialog_131221_Content_56 = {
    Text = "Ehrlich gesagt, hat die Mitternachtsmasken-Taverne während deiner Abwesenheit viel Geld mit deiner Geschichte verdient. Wir sollten dir eine Lizenzgebühr zahlen – mindestens sollten wir dich auf ein Getränk einladen."
  },
  AvgDialog_131221_Content_57 = {
    Text = "Ah, das bist du... Dann trinke ich erstmal nicht. Könntest du bitte meinem Freund hier ein Glas bringen?"
  },
  AvgDialog_131221_Content_58 = {
    Text = "Ich habe mir schon einen Namen überlegt, und zwar Selbstinszenierung."
  },
  AvgDialog_131221_Content_59 = {
    Text = "Ein schöner Name. Ob er zu Ihnen, meinem Freund, passt, muss ich mir noch genauer ansehen..."
  },
  AvgDialog_131221_Content_6 = {
    Text = "Unter der Führung von Arachne überquerst du die unscheinbare Wand neben dem Hewatz Café."
  },
  AvgDialog_131221_Content_60 = {
    Text = "Diese Person namens „Romantik\" kam an die Bar und blickte ernsthaft in die Augen von Arachne."
  },
  AvgDialog_131221_Content_61 = {
    Text = "Der bescheidene Schöpfer ist in die Bühne, die er erschaffen hat, vertieft. Arachne lächelt und sieht sie an."
  },
  AvgDialog_131221_Content_62 = {
    Text = "Ah, was für ein tiefgründiger Blick, Fräulein."
  },
  AvgDialog_131221_Content_63 = {
    Text = "Ein so tiefes und weites Meer, dessen unsichtbarer Meeresboden geheimnisse birgt, die niemand kennt."
  },
  AvgDialog_131221_Content_64 = {
    Text = "Die tobenden Wellen wurden alle von diesem Ozean aufgenommen, egal wie stark die Erschütterungen sind, er bewahrt weiterhin die uralte Ruhe."
  },
  AvgDialog_131221_Content_65 = {
    Text = "Die Zeit verstrichen, die Sternenmeere strömen. Hohe Berge werden zu Feldern, Ozeane werden zu Steppen..."
  },
  AvgDialog_131221_Content_66 = {
    Text = "Aber was hat dieser Ozean unter diesen Veränderungen aufgegeben..."
  },
  AvgDialog_131221_Content_67 = {
    Text = "Der Barkeeper setzte sich gegenüber von Arachne und hob ihr Kinn an. Seine langen Nägel lagen ganz natürlich auf Arachne's Halsschlagader."
  },
  AvgDialog_131221_Content_68 = {Text = "Dies ist"},
  AvgDialog_131221_Content_69 = {
    Text = "Die Göttin des Schicksals, die große Arachne. Wie elegant spielst du mit den Fäden des Schicksals. Ich beneide wirklich die, die du auswählst, die du zurücklässt."
  },
  AvgDialog_131221_Content_7 = {
    Text = "Als du wieder auf die Bühne des Theaters zurückkehrst, siehst du auf den ersten Blick Wilhelm, der allein im Zuschauerraum sitzt."
  },
  AvgDialog_131221_Content_70 = {
    Text = "Leider... wurden wir geboren, um der Teil zu sein, der aufgegeben wird."
  },
  AvgDialog_131221_Content_71 = {
    Text = "...Es scheint, als werde ich diesen Drink heute doch nicht kosten können."
  },
  AvgDialog_131221_Content_72 = {
    Text = "Arachne versuchte nicht, sich von der gefährlichen Hand zu befreien. Sie seufzte leise, als ob sie über jene fernen Erinnerungen seufzte, oder wie über den Drink, den sie nicht trinken konnte."
  },
  AvgDialog_131221_Content_73 = {
    Text = "Du kannst die Schicksalsleine dieser Geheimenheit verschmutzen, sodass ich nicht klar sehen kann, aber das hat keinen Sinn. Du hast nicht die Fähigkeit, das Schicksal zu kontrollieren, Nefraea."
  },
  AvgDialog_131221_Content_74 = {
    Text = "Wie eine Puppe aus schmelzender schwarzer Creme löst sich die Haut der Barkeeperin in einem schlammigen Haufen von ihrem Körper."
  },
  AvgDialog_131221_Content_75 = {
    Text = "Unter dem Schlamm erscheint ein vertrautes Gesicht vor dir."
  },
  AvgDialog_131221_Content_76 = {
    Text = "Du bist es?"
  },
  AvgDialog_131221_Content_77 = {
    Text = "Meine liebe Schwester. Von den Glut der Dimensionen bleibt dir kaum noch etwas übrig."
  },
  AvgDialog_131221_Content_78 = {
    Text = "Ich würde gerne noch einmal in Ruhe mit dir sprechen, aber jetzt lass meine kleinen Spinnen dich erst einmal herzlich willkommen heißen."
  },
  AvgDialog_131221_Content_79 = {
    Text = "Pass auf hinter dir"
  },
  AvgDialog_131221_Content_8 = {
    Text = "Kleine Wunde."
  },
  AvgDialog_131221_Content_9 = {
    Text = "Das Schicksal, das auf dieser Bühne stattfindet, habe ich gesehen. Ich denke, es sollte jemand Ihre Bemühungen danken, Frau Arachne."
  },
  AvgDialog_131222_Content_1 = {
    Text = "Einladung des Anwesens"
  },
  AvgDialog_131222_Content_10 = {
    Text = "Einladung? In meinem Leben habe ich bisher noch nie eine Einladung vorgelegt."
  },
  AvgDialog_131222_Content_100 = {
    Text = "Sorel verengte leicht die Augen, und in ihren eleganten Augen entbrannte ein seltener Zorn."
  },
  AvgDialog_131222_Content_101 = {
    Text = "Ich weiß nicht, was du mit Karen gemacht hast, aber das spielt keine Rolle. So oder so, der Preis, den du zahlen musst, ist bereits festgelegt."
  },
  AvgDialog_131222_Content_102 = {
    Text = "Ah, ein gescheitertes Geschäftsgespräch... Es tut mir leid, Frau Sorel. Es scheint, als könnte nur dein Leichnam mir darüber berichten."
  },
  AvgDialog_131222_Content_103 = {
    Text = "Sorel runzelte die Stirn und spürte die starke mentale Energiewelle des Gegenübers. Der pechschwarze Schatten näherte sich schnell und blockierte jeden Fluchtweg für sie."
  },
  AvgDialog_131222_Content_105 = {
    Text = "Als die Klinge im Schatten plötzlich auf Sorel zustach, sprang ein starkes silbernes Licht wie ein Meteor in das Zimmer."
  },
  AvgDialog_131222_Content_106 = {
    Text = "Sorel, zurück"
  },
  AvgDialog_131222_Content_11 = {
    Text = "Tretet zur Seite."
  },
  AvgDialog_131222_Content_12 = {
    Text = "Es tut mir leid, mein Herr. Für das heutige Festmahl ist eine Einladung erforderlich, um teilnehmen zu können."
  },
  AvgDialog_131222_Content_13 = {
    Text = "Ein Typ ohne Augenlicht, weißt du, wer ich bin?"
  },
  AvgDialog_131222_Content_14 = {
    Text = "Das ist nicht meine Verantwortung, Herr."
  },
  AvgDialog_131222_Content_15 = {
    Text = "Anhand Ihres Akzents scheinen Sie ein Einheimischer zu sein. Ich denke, dass Sie verstehen sollten, was ich sage."
  },
  AvgDialog_131222_Content_16 = {
    Text = "Du!! Gut, gut, ich werde dafür sorgen, dass du und der Besitzer dieses Anwesens bezahlen"
  },
  AvgDialog_131222_Content_17 = {
    Text = "Arachne sah den zornigen Rücken des Adligen und schüttelte den Kopf."
  },
  AvgDialog_131222_Content_18 = {
    Text = "Es scheint, dass der Zugang zu diesem Herrenhaus nicht so einfach ist, wie man denkt."
  },
  AvgDialog_131222_Content_19 = {
    Text = "Wenn wir die Zofe finden können, die das Badewasser verkauft, könnten wir vielleicht zwei Einladungen kaufen..."
  },
  AvgDialog_131222_Content_2 = {
    Text = "Das Anwesen des Herzogs von Cadlin, der berühmteste gesellschaftliche Ort im alten Lentiniën."
  },
  AvgDialog_131222_Content_20 = {
    Text = "Seltenes Meersalz aus der Siral-Insel, Lavendel, Zitrusfrüchte, Nelken und Rosenblätter, die aus dem Süden von Konstantin gebracht wurden..."
  },
  AvgDialog_131222_Content_21 = {
    Text = "Das Badewasser ist wertvoller und seltener als die Einladungskarte."
  },
  AvgDialog_131222_Content_22 = {Text = "???"},
  AvgDialog_131222_Content_23 = {
    Text = "Ich wollte eigentlich nur mit mir selbst reden... Wie kannst du wissen, was ich in meinem Traum erlebt habe?"
  },
  AvgDialog_131222_Content_24 = {
    Text = "Obwohl ich dein Schicksal nicht klar erkennen kann, habe ich das Schicksal der Menschen um dich herum immer im Auge."
  },
  AvgDialog_131222_Content_25 = {
    Text = "Da das Schicksal dieser Personen von dir kontrolliert werden kann, sollte es wohl möglich sein, auch wenn es kompliziert ist, so eine Kleinigkeit wie zwei Einladungskarten zu besorgen, oder?"
  },
  AvgDialog_131222_Content_26 = {
    Text = "Die Kettenreaktion, die durch die Veränderung des Schicksals ausgelöst wurde, haben Sie bereits miterlebt. Das Schicksal ist kein Spielzeug, mit dem ich nach Belieben umgehe, sondern ein Glashaus, das ich sorgfältig pflegen muss."
  },
  AvgDialog_131222_Content_27 = {
    Text = "Ich muss sorgfältig jede Entscheidung für es treffen und viel Energie sowie Dimension-Glut aufwenden. Jede Unachtsamkeit und jeder Fehler wird zu Zusammenbruch und Zerstörung führen."
  },
  AvgDialog_131222_Content_28 = {
    Text = "Ganz zu schweigen davon... Wie ich bereits sagte, ist es oft viel interessanter, ein Zuschauer zu sein, als ein Drehbuchautor."
  },
  AvgDialog_131222_Content_29 = {
    Text = "Ich freue mich auf deine Vorstellung, %player%."
  },
  AvgDialog_131222_Content_3 = {
    Text = "In der ersten Hälfte des Lebens des Herzogs schrieben der Premierminister und die hohen Beamten des Kabinetts auf dem Couchtisch auf der Wiese eine Entscheidung nach der anderen, die das Schicksal des Imperiums bestimmten."
  },
  AvgDialog_131222_Content_30 = {
    Text = "Aber ich weiß hier gar nichts..."
  },
  AvgDialog_131222_Content_31 = {
    Text = "Aufführung, Täuschung, Freude... In dir steckt eine solche Kraft. Die Bühne des Schicksals bietet nicht jedem die Gelegenheit. Wenn du die Bühne betreten musst, werden dir diese Kräfte helfen."
  },
  AvgDialog_131222_Content_32 = {
    Text = "Du kannst dich nicht vor den Rollen verstecken, die du spielen sollst. Denke nach, dann spiele, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131222_Content_33 = {
    Text = "In Arachne's höflichem Lächeln verbirgt sich eine nicht schwer zu erkennende Ernsthaftigkeit. Es scheint, als würde sie dir erzählen, dass dieser Blick dich durchdringt und mit einer fernen Zukunft spricht."
  },
  AvgDialog_131222_Content_34 = {
    Text = "Das ist ein Befehl, dem das Schicksal nicht entkommen kann. Du senkst den Kopf und denkst über Arachnes Worte nach."
  },
  AvgDialog_131222_Content_35 = {
    Text = "Aufführung, Täuschung, Vergnügen... sprichst du von Ns Macht?"
  },
  AvgDialog_131222_Content_36 = {
    Text = "Aber nach dem entscheidenden Kampf gegen Toguwaibo habe ich den Kontakt zu den Kräften der drei Plasmide verloren..."
  },
  AvgDialog_131222_Content_37 = {
    Text = "Ihre Kräfte ruhen noch, doch Macht ist nicht nur Stärke."
  },
  AvgDialog_131222_Content_38 = {
    Text = "Macht, nicht nur Stärke..."
  },
  AvgDialog_131222_Content_39 = {
    Text = "Als du versuchst, über diesen Satz nachzudenken, erscheint ein Lichtblitz in deiner geistigen Welt."
  },
  AvgDialog_131222_Content_4 = {
    Text = "Das zweite Leben des Herzogs, sein krummer Rücken wird von dem verkauften Anwesen beobachtet, während er zum Richtplatz geht."
  },
  AvgDialog_131222_Content_40 = {
    Text = "Du hebst zwei gefallene Ahornblätter vom Boden auf und streichst über ihre, wie Briefe geformten, Muster."
  },
  AvgDialog_131222_Content_41 = {
    Text = "Ich erinnere mich, dass du gesagt hast, dass alle Menschen in dieser Welt einen Silberkern in sich tragen. Das bedeutet, dass die geistige Welt aller von dem Silberschlüssel beeinflusst werden kann... richtig?"
  },
  AvgDialog_131222_Content_42 = {
    Text = "Arachne lächelt dich an, steht neben dir und geht zur Tür des Anwesens."
  },
  AvgDialog_131222_Content_43 = {
    Text = "Guten Tag, bitte zeigen Sie..."
  },
  AvgDialog_131222_Content_44 = {
    Text = "Was für ein schönes Herrenhaus. Es ist uns eine große Ehre, die Einladung von Frau Sorel zu erhalten."
  },
  AvgDialog_131222_Content_45 = {
    Text = "Als du zwei Ahornblätter an die Wache überreichst, blinkt dein Silberschlüssel in deiner Brust mit schwachem Licht. Du hast den Lichtpunkt der Wache mühelos eingefangen."
  },
  AvgDialog_131222_Content_46 = {
    Text = "Gleichzeitig leuchtet ein weiterer Lichtpunkt in deiner geistigen Welt auf. An der Kreuzung der beiden Lichtpunkte schwingt Clementines Phantasma das Pendel in ihrer Hand."
  },
  AvgDialog_131222_Content_47 = {
    Text = "Huey... Graf Huey..."
  },
  AvgDialog_131222_Content_48 = {
    Text = "Ah, Graf Huey, Gräfin, das Kadlin-Anwesen heißt Sie beide willkommen."
  },
  AvgDialog_131222_Content_49 = {
    Text = "Unter dem respektvollen Blick der Wache tretet ihr den ebenen Kiesweg des Anwesens an."
  },
  AvgDialog_131222_Content_5 = {
    Text = "Nach einer kurzen Stille füllte sich das Anwesen wieder mit kostbaren Gästen, und seine neue Herrin verkündete mit einer Reihe von Salons seine Rückkehr."
  },
  AvgDialog_131222_Content_50 = {
    Text = "Wie fühlt es sich an, {Male=Mr.,Female=Miss} Schutzherr?"
  },
  AvgDialog_131222_Content_51 = {
    Text = "Obwohl ich immer noch nicht verstehe, was du mit Macht meinst, habe ich gerade tatsächlich etwas anderes gespürt..."
  },
  AvgDialog_131222_Content_52 = {
    Text = "Das Gefühl, das nach dem Scherz entsteht, ist mir noch nie widerfahren... Es ist, als ob es ein Gefühl ist, das überhaupt nicht zu mir gehört..."
  },
  AvgDialog_131222_Content_53 = {
    Text = "Du hebst die Hand, zwei wunderschöne Ahornblätter lösen sich von deinen Fingerspitzen und wirbeln fröhlich im Wind."
  },
  AvgDialog_131222_Content_54 = {
    Text = "Als du mit einem angemessenen Lächeln die Villa betrittst, bist du dir sicher, dass du ein freudiges Lachen aus der Tiefe deines Körpers hörst."
  },
  AvgDialog_131222_Content_55 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131222_Content_56 = {
    Text = "Es ist wirklich bemerkenswert, jemanden zu sehen, der in so jungen Jahren so viel erreicht hat."
  },
  AvgDialog_131222_Content_57 = {
    Text = "Nach dem Ende der Handelsgespräche wird die Verbindung zwischen der Geschäftswelt und der Politik dieser Stadt eine beispiellose Umwälzung erfahren. Dies ist eine seltene Gelegenheit..."
  },
  AvgDialog_131222_Content_58 = {
    Text = "Die Einladung, die der Chefredakteur mühsam besorgt hat, müssen wir diesmal unbedingt in ein paar großartigen Szenen festhalten. Bring gleich deine Ausrüstung mit und folge uns, wir versuchen, ein Stück nach vorne zu gehen, um näher heranzukommen..."
  },
  AvgDialog_131222_Content_59 = {
    Text = "Komm raus! Komm raus!"
  },
  AvgDialog_131222_Content_6 = {
    Text = "Hallo, das ist mein Einladungsschreiben."
  },
  AvgDialog_131222_Content_60 = {
    Text = "Als der Ruf des jungen Mannes ertönte, stürmten alle zur geöffneten Tür."
  },
  AvgDialog_131222_Content_61 = {
    Text = "Das rote Kleid ist wie eine leidenschaftliche Rose, die alle Dekorationen und die Menge im Raum verblassen lässt."
  },
  AvgDialog_131222_Content_62 = {
    Text = "Sorel trägt ein makelloses, einstudiertes Lächeln und winkt den Gästen mit müheloser Anmut zu."
  },
  AvgDialog_131222_Content_63 = {
    Text = "Also ist sie die derzeitige Besitzerin des Anwesens..."
  },
  AvgDialog_131222_Content_64 = {
    Text = "Meine Damen und Herren, willkommen. Beim heutigen Salon werden mehrere Geschäftsviertel unserer Stadt ihre neuen Herren finden."
  },
  AvgDialog_131222_Content_65 = {
    Text = "Und natürlich werden unsere edlen Freunde die Vorzüge erhalten, die ihnen so rechtmäßig zustehen."
  },
  AvgDialog_131222_Content_66 = {
    Text = "Ich bin zuversichtlich, dass dies ein höchst prachtvoller und entzückender Abend wird."
  },
  AvgDialog_131222_Content_67 = {
    Text = "Der Küchenchef des Anwesens hat für alle erstklassige Gebäck und Champagner vorbereitet, bitte machen Sie eine kurze Pause. Bald wird unser Abendessen offiziell beginnen."
  },
  AvgDialog_131222_Content_68 = {
    Text = "Sorels Blick lächelte über das ganze Publikum, dann drehte sie sich um und ging nach oben."
  },
  AvgDialog_131222_Content_69 = {
    Text = "Sorel... Sorel!... Karen"
  },
  AvgDialog_131222_Content_7 = {
    Text = "...Ah, willkommen, Herr Fugen. Der Meister wartet bereits drinnen auf Ihre Ankunft, bitte treten Sie ein."
  },
  AvgDialog_131222_Content_70 = {
    Text = "Dein Ruf geht in den Diskussionen und Rufen der Menge unter."
  },
  AvgDialog_131222_Content_71 = {
    Text = "Frau Sorel! Frau Sorel! Wie haben Sie die Planung der Aufteilung des Geschäftsviertels vorgenommen? Wird das möglicherweise berühren..."
  },
  AvgDialog_131222_Content_72 = {
    Text = "Pssst, Herr Reporter. Ich bin gerade von draußen zurückgekommen, nachdem ich alles erledigt habe. Nachdem ich mich umgezogen habe, werde ich alle Fragen beantworten, die Sie wissen möchten."
  },
  AvgDialog_131222_Content_73 = {
    Text = "Sorel winkte den Journalisten zu und ging in den Schlafbereich des Herrenhauses im Obergeschoss."
  },
  AvgDialog_131222_Content_74 = {
    Text = "Es sieht so aus, als müssten wir warten, bis sie herauskommt, um sie zu fragen."
  },
  AvgDialog_131222_Content_75 = {
    Text = "Hast du die Zofe neben Madame Sorel bemerkt?"
  },
  AvgDialog_131222_Content_76 = {
    Text = "Karen? Natürlich, sie sollte es auch nicht gehört haben... Warte, meinst du..."
  },
  AvgDialog_131222_Content_77 = {
    Text = "Du erinnerst dich an den Duft von Karen. Dieser Duft ist völlig anders als der, den du kennst. Selbst in unterschiedlichen Dimensionen können sie nicht zu derselben Person gehören."
  },
  AvgDialog_131222_Content_78 = {
    Text = "Ich spürte an ihr die Spur eines Schicksals, das nicht zu dieser Bühne gehört... Ihr Schicksal ist verschmutzt."
  },
  AvgDialog_131222_Content_79 = {
    Text = "Frau Sorel ist in Gefahr"
  },
  AvgDialog_131222_Content_8 = {
    Text = "Hmph, selbst ein Händler wie Fugen, der nach Kupfer riecht, kann das Anwesen des alten Herzogs betreten. Der Stil von Lentiniën ist völlig verschwunden..."
  },
  AvgDialog_131222_Content_80 = {
    Text = "Du drängst dich kraftvoll durch die Menge und findest hinter dem Gebäude eine versteckte Treppe."
  },
  AvgDialog_131222_Content_81 = {
    Text = "Meine Entschuldigung, {Male=sir,Female=lady}, aber dies ist Frau Sorels Privatresidenz. Kein unbefugter—"
  },
  AvgDialog_131222_Content_82 = {
    Text = "Frau Sorel hat mich eingeladen, um mit ihr wichtige Angelegenheiten zu besprechen."
  },
  AvgDialog_131222_Content_83 = {
    Text = "Du holst eine Serviette hervor, die du einfach abgerissen hast. Ein silberner Glanz strahlt, und ein Ausweis der Prüfungskommission liegt vor dem Wachdienst."
  },
  AvgDialog_131222_Content_84 = {
    Text = "Entschuldigung, ich habe Sie nicht erkannt... Frau Sorel ist oben, ich kann Ihnen..."
  },
  AvgDialog_131222_Content_85 = {
    Text = "Geheime Mission, ich möchte nicht, dass andere davon erfahren."
  },
  AvgDialog_131222_Content_86 = {
    Text = "Bevor der Beamte sprechen konnte, rennst du schnell die Treppe hinauf."
  },
  AvgDialog_131222_Content_87 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131222_Content_88 = {
    Text = "Ihre Kleidung ist bereit, Frau Sorel"
  },
  AvgDialog_131222_Content_89 = {
    Text = "Lentiniën ist eine ursprüngliche Wildnis, Politiker und Händler sind die Hyänen dieser Stadt..."
  },
  AvgDialog_131222_Content_9 = {
    Text = "Guten Tag, bitte zeigen Sie die Einladung vor."
  },
  AvgDialog_131222_Content_90 = {
    Text = "Sorel nimmt die Kleidung, die Karen vorbereitet hat. Sonnenlicht fällt durch den roten Gazestoff und wirft einen leuchtend karmesinroten Schatten über das prächtige Schlafzimmer."
  },
  AvgDialog_131222_Content_91 = {
    Text = "Hyänen haben auch ihre liebenswerten Seiten. Ein Stück verwesendes Fleisch kann sie anlocken. Gierig, scharf, grausam, kindisch. Es gibt keine besseren Waffen als sie."
  },
  AvgDialog_131222_Content_92 = {
    Text = "Die anderen werden ungeduldig. Du bist heute viel zu spät erschienen, und dieses teure Kleid ist befleckt worden."
  },
  AvgDialog_131222_Content_93 = {
    Text = "Sie hätten früher zurückkommen sollen, gnädige Frau."
  },
  AvgDialog_131222_Content_94 = {
    Text = "Sorels Bewegung stockte einen Moment. Sie ließ langsam ihren blutroten Rock sinken und blickte auf Karens ruhiges Gesicht."
  },
  AvgDialog_131222_Content_95 = {
    Text = "Es sollte jemand dir beigebracht haben, wie ein Diener mit dem Meister spricht. Was ist heute mit dir los?"
  },
  AvgDialog_131222_Content_96 = {
    Text = "Frau Sorel, Sie haben Flecken aus dem Ostviertel auf Ihrem Kleid. Ich frage mich, wohin Sie diese gute Person geschickt haben?"
  },
  AvgDialog_131222_Content_97 = {
    Text = "Der helle Raum verdunkelte sich für einen Moment. Einige schwarze Spinnen verwandelten sich aus dem Schatten in menschliche Gestalten und umzingelten Sorel in der Mitte."
  },
  AvgDialog_131222_Content_98 = {
    Text = "Sie haben eine sehr loyale Dienerin, Frau Sorel. Obwohl sie leidenschaftlich daran interessiert ist, Ihre Besitztümer zu stehlen und zu verkaufen, ist ihre Loyalität, wenn es um Ihre Sicherheit geht, unbestritten."
  },
  AvgDialog_131222_Content_99 = {
    Text = "Selbst jetzt kämpft ihr Wille erbittert gegen mich an. Schade, wirklich—kein Sterblicher kann der Macht des Schicksals widerstehen."
  },
  AvgDialog_131223_Content_1 = {
    Text = "Schicksal. Wildes, hohles, erbärmliches Schicksal. Das Schicksal des Verlassenen weiß nicht, woher es kam, noch wohin es geht."
  },
  AvgDialog_131223_Content_10 = {
    Text = "Die Stimme von Nefraea wurde plötzlich schrill. Ein düsteres Licht erstrahlte, blutrote Fäden hielten sie fest gefesselt, und die Glut der Laterne brannte ihren Körper."
  },
  AvgDialog_131223_Content_11 = {
    Text = "Die riesigen Scherenbeine wogen in der Luft, während ein paar riesige, mit schwarzem Schleim bedeckte Facettenaugen mit einem Lächeln auf euch blickten. Blutrote Fäden umschlangen ihren Körper und schwebten im Wirbel des Schicksals."
  },
  AvgDialog_131223_Content_12 = {
    Text = "Sie neben sich, das zerbrochene Spinnrad, das die Fäden sammelte, drehte sich langsam und unaufhaltsam, erstickte alle Bühnen, erstickte Nefraea selbst."
  },
  AvgDialog_131223_Content_13 = {Text = "Hmm—"},
  AvgDialog_131223_Content_14 = {
    Text = "Du hältst schmerzhaft deinen Kopf. Unter dem Drehen des Spinnrades beginnt deine geistige Welt zu toben. Du atmest schwer und versuchst, die heftigen Schmerzen zu beruhigen."
  },
  AvgDialog_131223_Content_15 = {
    Text = "An Nefraea's Seite sind nur noch wenige Fragmente der Dimensionstunnel übrig. Die Fäden an euch und die puppenhaften Muster werden immer deutlicher."
  },
  AvgDialog_131223_Content_16 = {
    Text = "Die Kraft des Dimensionstunnels... Sie hat fast alles absorbiert"
  },
  AvgDialog_131223_Content_17 = {
    Text = "Die blasslila Glut strömte unaufhörlich aus Arachne hervor und flog wie Motten auf das fast vollständig zerbrochene Schicksalsnetz zu."
  },
  AvgDialog_131223_Content_18 = {
    Text = "Arachne zitterte mit ihren Händen in der unveränderten Frequenz der Ewigkeit und drehte das Spinnrad in ihren Händen. Ihre Stimme war immer noch so ruhig wie beim ersten Mal, als du sie gesehen hast."
  },
  AvgDialog_131223_Content_19 = {
    Text = "Du hast es bereits gesehen. Dies ist der Schnittpunkt des Schicksals, Nefraea."
  },
  AvgDialog_131223_Content_2 = {
    Text = "Sie werden von seidenen Fäden gezogen, stürzen auf dich zu, nur um in deinem silbernen Glanz zu Pfützen schwarzen Schlamms zu zerfließen."
  },
  AvgDialog_131223_Content_20 = {
    Text = "Alle Fehler werden hier enden."
  },
  AvgDialog_131223_Content_21 = {
    Text = "Was für eine selbstbewusste Erklärung, Gefangene Dame. Dann lass mich sehen, womit du die Götter und das Schicksal selbst aufhalten willst..."
  },
  AvgDialog_131223_Content_22 = {
    Text = "Der wahnsinnige Ausdruck des Lachens blüht auf Nefraea's Gesicht. Die Fäden, die sie fesseln, heben sie empor, auf der zerbrochenen Bühne ist sie das einzige Licht."
  },
  AvgDialog_131223_Content_23 = {
    Text = "„Kommt, ihr kriechenden Gläubigen der Welt! Senkt eure Häupter und werft euch vor mir nieder!\""
  },
  AvgDialog_131223_Content_24 = {
    Text = "„Die Verherrlichte ist vom himmlischen Thron herabgestiegen! Das Unausweichliche Ende offenbart sich hier und jetzt!\""
  },
  AvgDialog_131223_Content_25 = {
    Text = "„Dieses falsche Schicksal – lasst uns gemeinsam seine Zerstörung willkommen heißen!\""
  },
  AvgDialog_131223_Content_3 = {
    Text = "Schleimig, barbarisch, nichtig, bedauerlich, gleich ihrem Schicksal selbst."
  },
  AvgDialog_131223_Content_4 = {
    Text = "Nefraea ließ all dies unbeachtet, die Szene vor ihren Augen spielte sich seit unzähligen Jahren ab, daran hatte sie sich längst gewöhnt."
  },
  AvgDialog_131223_Content_5 = {
    Text = "Ich habe es klar gesehen. Die Bilder, die du gesehen hast, alles, was du gesehen hast, ich habe es endlich klar gesehen..."
  },
  AvgDialog_131223_Content_6 = {
    Text = "Der Schmerz der Bruchstücke war längst taub geworden, sie lächelte und blickte auf die chaotischen Lücken im Theater."
  },
  AvgDialog_131223_Content_7 = {
    Text = "Ein stolzes, mitleidiges, gleichgültiges Lächeln, in einem Moment konnte man sie kaum von Arachne unterscheiden."
  },
  AvgDialog_131223_Content_8 = {
    Text = "Nur diejenigen, die sich in einem Käfig befinden, können ihn wirklich öffnen. Das Chaos und die Zerstörung, die du siehst, sind nicht das wahre Schicksal, Nefraea..."
  },
  AvgDialog_131223_Content_9 = {
    Text = "Hahaha! ... So hast du all die Jahre dich selbst betrogen, Arachne?"
  },
  AvgDialog_131224_Content_1 = {
    Text = "Zuschauer, Schauspieler, Autor"
  },
  AvgDialog_131224_Content_10 = {
    Text = "Das ist...!"
  },
  AvgDialog_131224_Content_100 = {
    Text = "Geht, meine Kinder. Findet %player%."
  },
  AvgDialog_131224_Content_101 = {
    Text = "Ergreift {Male=his,Female=her} Macht, durchtrennt jeden Faden des Schicksals und reißt das Große Netz in Fetzen! Jede Seele, die sich uns in den Weg stellt, soll daran zugrunde gehen!"
  },
  AvgDialog_131224_Content_102 = {
    Text = "Wir werden mit dem Blut dieses Fragmentes das große Ursprüngliche erneut erwecken."
  },
  AvgDialog_131224_Content_103 = {
    Text = "Wenn du dein kostbares Schicksalsnetz zertrümmert und zu einem Sumpf aus Unrat verkommen siehst, wirst du dann in die endlose Leere versinken, genau wie wir?"
  },
  AvgDialog_131224_Content_104 = {
    Text = "Die Göttin des Schicksals, meine liebe Schwester, die liebe <Red:Arachne>?"
  },
  AvgDialog_131224_Content_105 = {
    Text = "Die Grenze zwischen Bühne und Publikum scheint zu verschwinden; der Raum selbst verliert jede Bedeutung."
  },
  AvgDialog_131224_Content_106 = {
    Text = "Inmitten des schrecklichen Gelächters scheint die Puppe direkt vor euch zu stehen und Arachne in die Augen zu starren."
  },
  AvgDialog_131224_Content_107 = {
    Text = "Das Licht schwindet, der Vorhang fällt. Die Puppe und ihr Lachen sind verschwunden, im leeren Theater bleibt nur das leise Drehen des Spinnrades."
  },
  AvgDialog_131224_Content_108 = {
    Text = "Es tut mir leid, ich habe nicht ganz verstanden... Was bedeutet das Schicksal der Verlassenen?"
  },
  AvgDialog_131224_Content_109 = {
    Text = "Wie Sie sehen, ist das Schicksal ein Durcheinander von Fäden. Wenn niemand webt, wird dieses Universum in endloses Chaos fallen. Ich denke, das ist ein Anblick, den wir alle nicht sehen wollen."
  },
  AvgDialog_131224_Content_11 = {
    Text = "In dem Moment, in dem du die Tür betrittst, verschwindet die Tür hinter dir."
  },
  AvgDialog_131224_Content_110 = {
    Text = "Natürlich..."
  },
  AvgDialog_131224_Content_111 = {
    Text = "Die Fäden zu einem Schicksalsnetz zu weben und den normalen Betrieb dieses Universums aufrechtzuerhalten, ist meine ewige Pflicht."
  },
  AvgDialog_131224_Content_112 = {
    Text = "In jedem Augenblick birgt das Schicksal unendliche Möglichkeiten. In jedem Augenblick bin ich gezwungen, eine Wahl zu treffen."
  },
  AvgDialog_131224_Content_113 = {
    Text = "Die richtigen Schicksale werden in das Große Netz eingewoben; die falschen werden verworfen. So funktioniert das Netz. Es ist unvermeidlich."
  },
  AvgDialog_131224_Content_114 = {
    Text = "Meine Schwester, auch ein Teil der falschen Schicksale, die ich aufgegeben habe."
  },
  AvgDialog_131224_Content_115 = {
    Text = "Arachne lächelte, und in ihrem ruhigen Vortrag bemerkte man kein bisschen emotionale Schwankung."
  },
  AvgDialog_131224_Content_116 = {
    Text = "Die verworfenen Schicksale... werden sie dann ins „Abgrund\" geschickt?"
  },
  AvgDialog_131224_Content_117 = {
    Text = "Der Traum dieser höchsten Gottheit bildet dieses Universum, der Ort namens „Abgrund\" ist das Unterbewusstsein der Gottheit, der Sammelplatz für all das, was nicht geschehen ist, und all die nicht existierenden Schicksale."
  },
  AvgDialog_131224_Content_118 = {
    Text = "Sie hätten in diesem Nichtigkeitsort vollständig verschwinden sollen, aber unter der Führung meiner Schwester haben sie auf irgendeine Weise überlebt."
  },
  AvgDialog_131224_Content_119 = {
    Text = "Arachne blickte auf den großen Vorhang und hinter dem Vorhang auf die Puppe, die Nefraea repräsentiert."
  },
  AvgDialog_131224_Content_12 = {
    Text = "In deinem ursprünglich gedachten engen Ladeninneren erstreckt sich ein weitläufiger, unendlicher Dimensionsraum."
  },
  AvgDialog_131224_Content_120 = {
    Text = "Sie hat nicht die Fähigkeit, das Schicksal zu kontrollieren, aber sie kann, wie ich, die Fäden des Schicksals sehen, sie verdecken, sie verschmutzen, die Spur, die ich für sie gewebt habe, zerstören und sie zum Tod führen..."
  },
  AvgDialog_131224_Content_121 = {
    Text = "Also will sie mich finden, um meine Stärke zu nutzen und Toguwaibo wiederzuerwecken?"
  },
  AvgDialog_131224_Content_122 = {
    Text = "Ich weiß nicht, was genau ihr Plan ist, aber im Moment sieht es tatsächlich so aus. Wie auch immer, sie ist ein Fehler, den ich beheben muss."
  },
  AvgDialog_131224_Content_123 = {
    Text = "Sie schließt die Tore zwischen den Dimensionen, auch um dieses zu erreichen, oder?"
  },
  AvgDialog_131224_Content_124 = {
    Text = "Der Dimensionstunnel ist von mir geschlossen. Sie hat die ganze Zeit gewartet, um mit dir zu diesem Moment nach Kardas zu gehen."
  },
  AvgDialog_131224_Content_125 = {
    Text = "Kardas ist eine Dimension, in die meine Kraft nie eingedrungen ist, und auch der Ort, der die engste Verbindung zu dieser höchsten Gottheit hat."
  },
  AvgDialog_131224_Content_126 = {
    Text = "Wenn du sie mit dir zurückbringst, wird das Schicksal der Katastrophe unwiderruflich sein."
  },
  AvgDialog_131224_Content_127 = {
    Text = "Vergib mir, dass ich mir solche Freiheiten herausgenommen habe, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131224_Content_128 = {
    Text = "Ich verstehe, Arachne. Wenn das, was du sagst, wahr ist, dann ist das auch nicht das, was ich sehen möchte."
  },
  AvgDialog_131224_Content_129 = {
    Text = "Also, wenn ich nach Kardas zurückkehren möchte, muss ich sie zuerst erledigen..."
  },
  AvgDialog_131224_Content_13 = {
    Text = "Unzählige Bühnen schweben wie Sterne in dieser dunklen Weite, auf jeder einzelnen tragen Puppen ihre Zeilen vor."
  },
  AvgDialog_131224_Content_130 = {
    Text = "Meister, die Bühne im Bereich GI-9849 hat eine Anomalie aufgetreten. Es ist bereits der dritte Fall heute."
  },
  AvgDialog_131224_Content_131 = {
    Text = "Nachdem sie die Materialien zum Schicksal weben gestohlen hatte, war sie stets begeistert davon, das Schicksal zu zerstören."
  },
  AvgDialog_131224_Content_132 = {
    Text = "Verzeih, %player%, aber ich muss mich um diese Störungen kümmern. Bitte, komm mit mir. Es gibt wichtige Dinge, die du sehen musst."
  },
  AvgDialog_131224_Content_133 = {
    Text = "Arachne lächelte und schüttelte den Kopf. Sie machte dir eine Einladungsgeste und stand mit dem Spinnrad auf."
  },
  AvgDialog_131224_Content_134 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131224_Content_135 = {
    Text = "Hier... ist die zerstörte Bühne?..."
  },
  AvgDialog_131224_Content_136 = {
    Text = "Entlang des von Spinnweben gewebten Weges kommt ihr zu einer heruntergekommenen Bühne. In dem einfachen Café auf der Bühne sitzen einige Schüler und sprechen leise miteinander."
  },
  AvgDialog_131224_Content_137 = {
    Text = "In letzter Zeit hat sie ihre Diener ständig losgeschickt, um das Schicksal dieser Welten zu zerstören. Meine Zofen suchen überall nach ihnen, und ihre Kämpfe haben vielen guten Kindern das Leben gekostet."
  },
  AvgDialog_131224_Content_138 = {
    Text = "Das Schicksal aller Welten ist in einem riesigen Netz verbunden, der Absturz jeder Welt wird das gesamte Schicksalsnetz zerreißen und alles in eine völlige, tödliche Unordnung stürzen."
  },
  AvgDialog_131224_Content_139 = {
    Text = "Nefraea hat das Material zum Schicksal weben gestohlen, ich kann meine Kräfte nicht leicht einsetzen. Schutzherr {Male=Herr, Female=Dame}, ich denke, vielleicht können Sie mir helfen, das Schicksal dieser Welt zu reparieren?"
  },
  AvgDialog_131224_Content_14 = {
    Text = "Die Worte dringen aus der Ferne zu dir, wie das Murmeln unzähliger Gläubiger beim Gebet."
  },
  AvgDialog_131224_Content_140 = {
    Text = "Wenn das, was du sagst, wahr ist, ist sie auch ein Problem, das ich lösen muss."
  },
  AvgDialog_131224_Content_141 = {
    Text = "Arachne nickte dir entschuldigend zu. Sie hob die Hand und streichelte sanft die unsichtbare Luft, die geheimen Fäden."
  },
  AvgDialog_131224_Content_142 = {Text = "Dong——"},
  AvgDialog_131224_Content_143 = {
    Text = "Nach dem klaren Klang der Instrumente ertönt die melodische Stimme des Ansagers, wie ein ewiger klarer Strom, der unaufhörlich in einen tiefen Teich fließt."
  },
  AvgDialog_131224_Content_144 = {
    Text = "Die Trompete spielt florale Melodien. Junge Studenten und Gelehrte, auf—"
  },
  AvgDialog_131224_Content_145 = {
    Text = "Arachne macht eine Einladungsgeste."
  },
  AvgDialog_131224_Content_146 = {
    Text = "Es ist Zeit für unseren Auftritt, %player%."
  },
  AvgDialog_131224_Content_147 = {
    Text = "Du nickst. In der sanften Ansage betreten zwei Puppen ihre Bühne."
  },
  AvgDialog_131224_Content_15 = {
    Text = "Fäden ziehen sich von den Puppenspielern und der Bühne aus und verbinden sich mit dem von Spinnenseide gewebten Weg unter deinen Füßen, der im Zentrum dieses Raumes zu dieser Bühne führt."
  },
  AvgDialog_131224_Content_16 = {
    Text = "Du drehst dich um, die Zofe neben dir ist bereits nach vorne gegangen."
  },
  AvgDialog_131224_Content_17 = {
    Text = "Das ist wirklich eine seltsame Willkommenszeremonie..."
  },
  AvgDialog_131224_Content_18 = {
    Text = "Du zögerst und gehst den Spinnwebenweg zur Bühne in der Mitte. Während du an den schwebenden Bühnen vorbeigehst, dringen Stücke von Gesprächen in deine Ohren."
  },
  AvgDialog_131224_Content_19 = {
    Text = "Dieser Kunde, ich habe Verwirrung in Ihren Augen gesehen."
  },
  AvgDialog_131224_Content_2 = {
    Text = "Ich habe noch eine Frage..."
  },
  AvgDialog_131224_Content_20 = {
    Text = "Hatten Sie Angst wegen des Vorfalls im Laden gerade eben?"
  },
  AvgDialog_131224_Content_21 = {
    Text = "Eine Struktur auf Basis von Gin, mit dem Geschmack von Hibiskusblüten, wird sicherlich gut zu Ihrer gegenwärtigen Stimmung passen."
  },
  AvgDialog_131224_Content_22 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131224_Content_23 = {
    Text = "Ah! Ein obdachloses Kind, so klein, so arm."
  },
  AvgDialog_131224_Content_24 = {
    Text = "Wie willst du diesen Winter mit diesen dünnen Kleidern überstehen?"
  },
  AvgDialog_131224_Content_25 = {
    Text = "Komm mit mir. Lass mich einen Ort finden, wo du vor dem Sturm Schutz findest..."
  },
  AvgDialog_131224_Content_26 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131224_Content_27 = {
    Text = "Sind das... die Leute, die ich gerade getroffen habe?"
  },
  AvgDialog_131224_Content_28 = {
    Text = "Wie können sie auf diesen Bühnen erscheinen..."
  },
  AvgDialog_131224_Content_29 = {
    Text = "Die patrouillierenden Polizisten, die Zeitung lesenden Angestellten, die die Straßenansicht bewundernden Fahrer, die Blumen kaufenden Liebenden, die sich unterhaltenden Adligen..."
  },
  AvgDialog_131224_Content_3 = {
    Text = "Das ist bereits deine dreiundzwanzigste Frage, %player%."
  },
  AvgDialog_131224_Content_30 = {
    Text = "Die Menschen, die du gesehen hast und die, die du nicht gesehen hast, spielen auf diesen unzähligen Bühnen ihre eigenen Geschichten. Auf ihren eigenen Bühnen sind sie die Hauptdarsteller ihrer eigenen Geschichten."
  },
  AvgDialog_131224_Content_31 = {
    Text = "Ave, %player%! Gesegnet sei das Kind aus Akute!"
  },
  AvgDialog_131224_Content_32 = {
    Text = "Ave, %player%! Gesegnet sei der Schutzherr des Misaq!"
  },
  AvgDialog_131224_Content_33 = {
    Text = "Ave, %player%! Gesegnet sei der Gott der Zerstörung!"
  },
  AvgDialog_131224_Content_34 = {
    Text = "Nachdem ihr die zentrale Bühne erreicht habt, betreten drei unterschiedlich geformte Puppen die Bühne und verbeugen sich in eure Richtung."
  },
  AvgDialog_131224_Content_35 = {
    Text = "Die Herrin erwartet Euch drinnen. Bitte, tretet ein – {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131224_Content_36 = {
    Text = "Als sich die Tür zur Loge öffnete, schienen die Bilder und Geräusche des gesamten Theaters für einen Moment anzuhalten."
  },
  AvgDialog_131224_Content_37 = {
    Text = "Du trittst durch die Tür und ziehst den Vorhang auf——"
  },
  AvgDialog_131224_Content_38 = {
    Text = "Sie erscheinen auf diesen Bühnen, weil der Name dieses Theaters Schicksal ist."
  },
  AvgDialog_131224_Content_39 = {
    Text = "Eine kühle, bedächtige Stimme erreicht dich, bevor du auch nur eine Farbe wahrnimmst."
  },
  AvgDialog_131224_Content_4 = {
    Text = "Im Vergleich zu den Rätseln an diesem Ort sind meine Fragen bei weitem nicht genug."
  },
  AvgDialog_131224_Content_40 = {
    Text = "In einer Loge, die keine Wände zu haben scheint, laufen die Fäden, die jede Bühne und jede Puppe verbinden, an einer sanft leuchtenden Spindel zusammen. Eine Frau sitzt an dem Punkt, wo alle Fäden sich treffen, und dreht sie mit sanfter Hand."
  },
  AvgDialog_131224_Content_41 = {
    Text = "Du siehst jedes Detail von ihr mit vollkommener Klarheit. Doch bei jedem Blinzeln schwindet jeder Eindruck aus deinem Geist und hinterlässt nichts."
  },
  AvgDialog_131224_Content_42 = {
    Text = "Ihr Bild will sich nicht halten. Als sie den Kopf wendet und dich ansieht, gerät dein Herz – die ganze Zeit über angespannt vor Wachsamkeit – in heftiges Schlagen."
  },
  AvgDialog_131224_Content_43 = {
    Text = "Du bist es?!!"
  },
  AvgDialog_131224_Content_44 = {
    Text = "Auf dem Paradeis... und diese Angriffe...!"
  },
  AvgDialog_131224_Content_45 = {
    Text = "In dem Moment, in dem du bereit bist, deine geistige Kraft in den Silberschlüssel zu injizieren, streckt die Besitzerin des Theaters die Hand aus und zieht sie durch die Luft. Ihre Bewegung ist sanft und elegant, als würde sie eine Saite leicht zupfen."
  },
  AvgDialog_131224_Content_46 = {Text = "!!!"},
  AvgDialog_131224_Content_47 = {
    Text = "Die geistige Kraft kommt an deine Fingerspitzen, wird jedoch wie ein durch einen Damm gestopptes Hochwasser zurückgedrängt. Erst als du deine Hand in die Luft hebst, bemerkst du plötzlich, dass deine Hand seit wann leer ist."
  },
  AvgDialog_131224_Content_48 = {
    Text = "Silberschlüssel... Der Silberschlüssel war die ganze Zeit in meiner Hand... Warum..."
  },
  AvgDialog_131224_Content_49 = {
    Text = "Die Herrin lächelt schwach und nickt ihrer Dienerin kurz zu."
  },
  AvgDialog_131224_Content_5 = {
    Text = "Ich bin nicht der Antwortgeber, den Sie suchen. Die Person, die Ihre Fragen beantworten kann, wartet hier auf Sie."
  },
  AvgDialog_131224_Content_50 = {
    Text = "Unter deinem erstaunten Blick tritt die Dienerin vor und legt dir ehrfürchtig den Silberschlüssel zurück in die Hand."
  },
  AvgDialog_131224_Content_51 = {
    Text = "Unmöglich... Sie kann den Silberschlüssel unmöglich gestohlen haben!..."
  },
  AvgDialog_131224_Content_52 = {
    Text = "Bevor du das Theater betreten hast, hast du diesen Schlüssel fest umklammert und eine ständige spirituelle Verbindung aufrechterhalten."
  },
  AvgDialog_131224_Content_53 = {
    Text = "Dein Training beim Misaq hat dir ein Maß an Wachsamkeit verliehen, das so hoch ist, dass niemand jemals hoffen könnte, ihn dir aus der Hand zu reißen."
  },
  AvgDialog_131224_Content_54 = {
    Text = "Warum ist das so..."
  },
  AvgDialog_131224_Content_55 = {
    Text = "Niemand kann es von dir wegnehmen, aber das Schicksal kann es."
  },
  AvgDialog_131224_Content_56 = {
    Text = "Vergib mir, %player%. Ich verstehe deine Unruhe und ich respektiere deine Macht."
  },
  AvgDialog_131224_Content_57 = {
    Text = "Um unbeabsichtigte Schäden an meinem Theater zu verhindern, blieb mir keine andere Wahl, als kurzzeitig das Schicksal des Schlüssels in deiner Hand zu verändern. Ich hoffe, du kannst mir diese Freiheit nachsehen."
  },
  AvgDialog_131224_Content_58 = {
    Text = "Sie hebt die Hand, und ein Lichtstrahl durchdringt den Raum zwischen euch. Bei genauerem Hinsehen erkennst du einen schwachen, kaum wahrnehmbaren Faden, der vom Silberschlüssel ausgeht und zurück zum Spinnrad an ihrer Seite führt."
  },
  AvgDialog_131224_Content_59 = {
    Text = "Diese Fäden sind...?"
  },
  AvgDialog_131224_Content_6 = {
    Text = "Ihr haltet vor einem Theater mit nur einem einzigen Eingang an. Es gibt kein Schild und keine Kunden, es scheint wie ein unauffälliges Spinnennetz in den prächtigen Läden von Lentiniën."
  },
  AvgDialog_131224_Content_60 = {
    Text = "Es gibt viele Erklärungen für die Fäden, einige sind für die Gegenwart zu kompliziert. Du kannst sie einfach als... Schicksal betrachten."
  },
  AvgDialog_131224_Content_61 = {
    Text = "Das Spinnrad dreht sich leise von selbst. Sie erhebt sich und grüßt mit einem anmutigen Nicken."
  },
  AvgDialog_131224_Content_62 = {
    Text = "Arachne, die Herrin des Schicksalstheaters. Es ist mir eine Ehre, Sie zu treffen, Schutzherr."
  },
  AvgDialog_131224_Content_63 = {
    Text = "Bitte machen Sie sich keine Sorgen, Sie sind hier sicher."
  },
  AvgDialog_131224_Content_64 = {
    Text = "In der Tat, wenn du mich töten willst, hatte ich gerade keine Chance, am Leben zu bleiben."
  },
  AvgDialog_131224_Content_65 = {
    Text = "Als Arachne die Fäden bewegt, dimmt das Licht der Spinnräder im Logenraum. Mit einem gemischten Ausdruck siehst du auf den Silberschlüssel, den die Zofe zurückgibt, und runzelst die Stirn, während du sie ansiehst."
  },
  AvgDialog_131224_Content_66 = {
    Text = "Damals auf dem Paradeis hast du mir geholfen. Aber seit ich in dieser Stadt bin, hast du mich zweimal angegriffen."
  },
  AvgDialog_131224_Content_67 = {
    Text = "Ich verstehe dein Misstrauen. Aber bitte glaube mir, wenn ich sage, dass ich niemals auch nur einen Finger gerührt habe, um dir zu schaden."
  },
  AvgDialog_131224_Content_68 = {
    Text = "Du hast meine Verbindung zu Kardas blockiert und mich mehrfach angegriffen... Willst du sagen, dass du all diese Dinge nicht getan hast?"
  },
  AvgDialog_131224_Content_69 = {
    Text = "Diese Person, die Sie belästigt hat, sieht zwar aus wie ich, ist aber nicht ich."
  },
  AvgDialog_131224_Content_7 = {
    Text = "Die Zofe schob die Tür sanft auf und ihre Gestalt verschwand im Dunkel hinter der Tür. Im Dunkel flackerte ein Licht, dessen Ursprung unbekannt war, wie eine versteckte Einladung."
  },
  AvgDialog_131224_Content_70 = {
    Text = "Was deine Verbindung zu Kardas betrifft... das ist eine gefährliche Falle, %player%."
  },
  AvgDialog_131224_Content_71 = {Text = "Falle?"},
  AvgDialog_131224_Content_72 = {
    Text = "Ein Kind, das aus meiner eigenen Existenz hervorgegangen ist, hat dir unnötigen Kummer bereitet, und das tut mir aufrichtig leid. Diese Situation hat mit mir begonnen, und ich tue alles in meiner Macht Stehende, um den Fehler zu beheben."
  },
  AvgDialog_131224_Content_73 = {
    Text = "Ich habe es nicht verstanden..."
  },
  AvgDialog_131224_Content_74 = {
    Text = "Dies ist eine etwas lange Geschichte, die mit dem Schicksal verbunden ist. Geschichten sind immer leichter zu verstehen als bloße Aussagen."
  },
  AvgDialog_131224_Content_75 = {
    Text = "Bitte, nimm Platz, {Male=Mr.,Female=Miss} Schutzherr. Dieser neue Akt unseres Stücks hat erst vor Kurzem begonnen."
  },
  AvgDialog_131224_Content_76 = {
    Text = "Arachne winkt sanft. Der Vorhang öffnet sich und eine schwebende, leere Bühne erscheint vor dir."
  },
  AvgDialog_131224_Content_77 = {
    Text = "Auf der Bühne scheint es einen schimmernden Spiegel zu geben, der eure Gestalten reflektiert."
  },
  AvgDialog_131224_Content_78 = {
    Text = "Die Trompeten erklingen mit einem Tusch. Auftritt: Das Schicksal des Verlassenen."
  },
  AvgDialog_131224_Content_79 = {
    Text = "Bald verschwindet deine Gestalt im Spiegel, und Arachne verwandelt sich in eine Puppe."
  },
  AvgDialog_131224_Content_8 = {
    Text = "Du zögerst einen Moment und gehst durch die Tür."
  },
  AvgDialog_131224_Content_80 = {
    Text = "Die Puppe bleibt sitzen, doch ihre sanfte Gelassenheit ist verflogen."
  },
  AvgDialog_131224_Content_81 = {
    Text = "Sie schwenkt einen Kelch gefüllt mit einem blutroten Tropfen, als throne sie auf einem Sitz des Gemetzels. Ihre Augen, unschuldig und doch völlig erbarmungslos, schweifen über das Publikum."
  },
  AvgDialog_131224_Content_82 = {
    Text = "Hinter der Puppe wiegen sich vier Paare messerscharfer Spinnenbeine träge hin und her, deren Spitzen die Wangen der nahestehenden Bediensteten streifen."
  },
  AvgDialog_131224_Content_83 = {
    Text = "Ah, die Luft der Freiheit..."
  },
  AvgDialog_131224_Content_84 = {
    Text = "Wie viele Jahre sind wir in diesem Abgrund gefangen, mein lieber Diener?"
  },
  AvgDialog_131224_Content_85 = {
    Text = "Ich weiß nicht, mein Meister."
  },
  AvgDialog_131224_Content_86 = {
    Text = "Name, Zeit, Emotionen ... ich habe alles vergessen ... ich erinnere mich nur an Sie, mein Herr, die ehrwürdige Nefraea."
  },
  AvgDialog_131224_Content_87 = {
    Text = "Ich erinnere mich nur, dass Sie mir gesagt haben, dass Sie uns hier wegbringen werden, dass Sie uns das Schicksal mit der Klinge der Rache schwingen lassen werden."
  },
  AvgDialog_131224_Content_88 = {
    Text = "Ich erinnere mich, Kind. Ich habe euch neunzigtausend Versprechen gegeben, und jetzt lasst mich euch das neunzigtausendundeinste sagen."
  },
  AvgDialog_131224_Content_89 = {
    Text = "Jeder Moment kann nur ein Schicksal existieren. Der Executor des Schicksals wird unzählige falsche Schicksale abschneiden und nur das einzig richtige Schicksal übrig lassen."
  },
  AvgDialog_131224_Content_9 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131224_Content_90 = {
    Text = "Wir sind das verlassene Schicksal. Hahaha... mein lieber Diener, du bist ein Fehler, genau wie ich."
  },
  AvgDialog_131224_Content_91 = {
    Text = "In diesem Unterbewusstsein des Universums, in diesem nicht existierenden Abgrund der Nichtigkeit, wurden wir verbannt und gefangen gehalten. Hier wandern wir umher, vergessen, für alle Ewigkeit. Unsere Strafe ist länger als die Zeit selbst..."
  },
  AvgDialog_131224_Content_92 = {
    Text = "Die Frau namens Nefraea stand von ihrem Sitz auf, beugte sich vor und lächelte Arachne im Publikum an."
  },
  AvgDialog_131224_Content_93 = {
    Text = "Aber warum, Schicksalsgöttin? Warum sollten wir die Ausgeschlossenen sein?"
  },
  AvgDialog_131224_Content_94 = {
    Text = "Der höchste, einzigartige Gott unzähliger Universen ist endlich für einen Moment erwacht. Er ist erneut in den Schlaf gefallen, aber sein Gefängnis des Bewusstseins, der ewige Abgrund, wurde schließlich für uns geöffnet."
  },
  AvgDialog_131224_Content_95 = {
    Text = "Ich hatte es bereits vergessen und war vergangen. Aber warum, warum muss ich mich an all diesen Schmerz erinnern?"
  },
  AvgDialog_131224_Content_96 = {
    Text = "Nefraea trank den Inhalt des Bechers und stieß einen zufriedenen Seufzer aus. Der leuchtend rote Saft lief über ihre blassen Lippen und tropfte auf ihr trübes Spinnrad in der Hand."
  },
  AvgDialog_131224_Content_97 = {
    Text = "Vielleicht ist das die Anordnung des Schicksals... ein Schicksal, das selbst du nicht kontrollieren kannst."
  },
  AvgDialog_131224_Content_98 = {
    Text = "Der ursprüngliche Gott schläft erneut, aber seine Fragmente sind an unseren Wohnort gekommen."
  },
  AvgDialog_131224_Content_99 = {
    Text = "Ich habe nicht die Fähigkeit, das Schicksal wie du zu kontrollieren. Ich bin nur der Berichterstatter des Schicksals, der Henker aus der Nichtigkeit. Die Sünden im Fluss des Schicksals werden von mir im Namen des Ursprünglichen bestraft."
  },
  AvgDialog_131225_Content_1 = {
    Text = "Schatten der Vergangenheit"
  },
  AvgDialog_131225_Content_10 = {
    Text = "Im Gegensatz zu dem weiten Raum, den du dir aufgrund deiner Erfahrung vorgestellt hast, wirkt das Innere dieser Villa äußerst überfüllt. Nefraea scheint fest entschlossen zu sein, in ihrem Drehbuch wild herumzuschreiben."
  },
  AvgDialog_131225_Content_11 = {
    Text = "Die endlosen Schränke und Regale stehen still und überfüllt, verschiedene Größen von Gläsern füllen jeden Raum."
  },
  AvgDialog_131225_Content_12 = {
    Text = "Silberspiegel, Spinneneier, Tanzschuhe, die von fremden Insekten bekrabbelt werden... Verschiedene Objekte sind in einer unbekannten Flüssigkeit eingetaucht, wie stumme Münder, die schreien."
  },
  AvgDialog_131225_Content_13 = {
    Text = "Du stehst vor den verschiedenen Gläsern und liest leise die Worte auf den Etiketten vor."
  },
  AvgDialog_131225_Content_14 = {
    Text = "Mit zwei Jahren sprach ich mein erstes Wort. Ich rief nicht nach meiner Familie, sondern verabschiedete mich von dem alten Hausdiener, der sich seit Generationen um meine Familie kümmerte."
  },
  AvgDialog_131225_Content_15 = {
    Text = "In der Nacht starb der alte Hausdiener an einer Herzkrankheit. Mit den Relikten des Hausdieners weinte er vor der Tür des Hausdieners..."
  },
  AvgDialog_131225_Content_16 = {
    Text = "Das ist eine alte Familienbrosche."
  },
  AvgDialog_131225_Content_17 = {
    Text = "Mit fünf Jahren tanzte ich schüchtern Walzer, so wie meine Mutter, im verlegenen Jubel der Gäste beim Abendessen..."
  },
  AvgDialog_131225_Content_18 = {
    Text = "Das ist ein Paar leuchtend rote Tanzschuhe."
  },
  AvgDialog_131225_Content_19 = {
    Text = "Im Alter von sieben Jahren erhielt ich von meinem Vater ein Geburtstagsgeschenk, ein Spinnrad namens „Moirai\"."
  },
  AvgDialog_131225_Content_2 = {
    Text = "Brick Lane, erinnerst du dich an die Szene während der Ermittlungen in diesem Gebiet von Lentiniën."
  },
  AvgDialog_131225_Content_20 = {
    Text = "In den Fäden des Spinnrades siehst du die Projektion des Schicksals..."
  },
  AvgDialog_131225_Content_21 = {
    Text = "Das ist eine Handvoll gebrochener Fäden."
  },
  AvgDialog_131225_Content_22 = {
    Text = "Zum ersten Mal mit meinen Eltern ins Opernhaus... Zum ersten Mal einen engen Freund kennenlernen... Zum ersten Mal meinen eigenen Hund beerdigen..."
  },
  AvgDialog_131225_Content_23 = {
    Text = "Die Worte auf den Etiketten der Gläser erscheinen nacheinander vor deinen Augen. Jedes Mal, wenn du sie berührst, taucht ein verschwommenes Gedächtnis in deinem Kopf auf. Du drehst dich um und schaust verwirrt zu Arachne."
  },
  AvgDialog_131225_Content_24 = {
    Text = "Sind das... alles deine Erinnerungen?"
  },
  AvgDialog_131225_Content_25 = {
    Text = "Es sind meine Erinnerungen von früher. Vor langer Zeit gehörten sie der Person, die „Erinnerung\" genannt wird."
  },
  AvgDialog_131225_Content_26 = {
    Text = "Das sind alles wertvolle Erinnerungen... Warum sollten sie auf einem geheimen Objekt freigegeben werden?"
  },
  AvgDialog_131225_Content_27 = {
    Text = "Jeder Mensch muss in seinem Leben einige Entscheidungen treffen. Jede Entscheidung hat ihren Preis."
  },
  AvgDialog_131225_Content_28 = {
    Text = "Um das Ende des Weges zu erreichen, muss man immer etwas zurücklassen. Ich glaube, du verstehst das besser als jeder andere, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131225_Content_29 = {
    Text = "Arachne hat deine Frage nicht direkt beantwortet, sie schaute auf die Schränke und strich sanft über die mit Flüssigkeit gefüllten Behälter."
  },
  AvgDialog_131225_Content_3 = {
    Text = "Schmutzig, chaotisch, die Luft ist voll von Rauch und dem Geruch von Abwasser, diese Gerüche begleiteten Mason und Jenkin während all ihrer Lebenszeit."
  },
  AvgDialog_131225_Content_30 = {
    Text = "Ihre Bewegungen waren sanft und langsam, wie die eines alten Mannes, der über die Spielzeuge streicht, die er in seiner Kindheit geliebt hat."
  },
  AvgDialog_131225_Content_31 = {
    Text = "Nehmt diese Erinnerungen von der Geheimeinheit und manifestiert sie in dieser Form. Das ist die Landschaft, die du für mich vorbereitet hast, Nefraea."
  },
  AvgDialog_131225_Content_32 = {
    Text = "Was du mir sagen willst, habe ich verstanden..."
  },
  AvgDialog_131225_Content_33 = {
    Text = "<Big:<Shake:AAAHHHH!—>>"
  },
  AvgDialog_131225_Content_34 = {
    Text = "Ein durchdringender Schrei hallt im Raum, die mit Erinnerungen gefüllten Gläser vibrieren sanft, als wären sie eine Gruppe von stummen Zuschauern, die leise lachen."
  },
  AvgDialog_131225_Content_35 = {
    Text = "!! Im Raum hinter dem Flur"
  },
  AvgDialog_131225_Content_36 = {Text = "Bang—"},
  AvgDialog_131225_Content_37 = {
    Text = "Du rennst schnell den Flur entlang und stößt die Tür auf..."
  },
  AvgDialog_131225_Content_38 = {
    Text = "Du bist in einem Sturm."
  },
  AvgDialog_131225_Content_39 = {
    Text = "Es gibt keinen Donner, keinen Wind und keinen Regen. Nur zahlreiche Spinnen fallen wie ein Platzregen von der leeren Decke."
  },
  AvgDialog_131225_Content_4 = {
    Text = "Und in diesem Moment tauchte zwischen zwei Hütten plötzlich eine prunkvolle Villa auf, als wäre sie eine Schmuckschatulle, die auf einem Müllhaufen platziert wurde."
  },
  AvgDialog_131225_Content_40 = {
    Text = "Klebrige schwarze Gliederfüßer versammeln sich zu einer tosenden Flut, die alle Gegenstände und das gesamte Licht im Raum verschlingt."
  },
  AvgDialog_131225_Content_41 = {
    Text = "Im Zentrum des dunklen, stürmischen Regens versammelten sich die verrückt kletternden und nagenden Spinnen zu einer menschlichen Gestalt, die gerade noch zu erkennen ist. An den Stellen, wo die Flut der Spinnen noch nicht bedeckt hat, erscheint ein vertrautes, bleiches Gesicht eines alten Mannes."
  },
  AvgDialog_131225_Content_42 = {
    Text = "Arachne......Fräulein......"
  },
  AvgDialog_131225_Content_43 = {
    Text = "Schnell...lauf!..."
  },
  AvgDialog_131225_Content_44 = {
    Text = "Pssst... Hier gibt es keinen Platz für deine Zeilen, „guter\" Herr."
  },
  AvgDialog_131225_Content_45 = {
    Text = "Die Rache des Schicksals, Akt 2, Szene 2. Ich nenne es „Starkregen\"."
  },
  AvgDialog_131225_Content_46 = {
    Text = "Genießt das wunderbare Regenbad, meine lieben Zuschauer."
  },
  AvgDialog_131225_Content_47 = {
    Text = "Das Wasser erhebt Wellen, die schwarzen Spinnen hören den höchsten Befehl und strömen in alle Ecken des Raumes."
  },
  AvgDialog_131225_Content_48 = {
    Text = "In den Bewunderungsrufen von Nefraea strömen die von Spinnen gebildeten Wachen, Diener und abscheulichen Kreaturen auf euch zu—"
  },
  AvgDialog_131225_Content_5 = {
    Text = "Die Obdachlosen und erschöpften Arbeiter gingen an dieser prächtigen Box vorbei, ohne dass jemand einen überflüssigen Blick darauf warf, als ob sie seit ihrer Geburt hier existiert hätte."
  },
  AvgDialog_131225_Content_6 = {
    Text = "Sogar das Schicksal dieser Stadt ist betroffen... Die Stärke von Nefraea verstärkt sich tatsächlich."
  },
  AvgDialog_131225_Content_7 = {
    Text = "Du gehst vorsichtig nach vorne, um an die Tür zu klopfen, aber als deine Hand gerade auf die Tür gelegt wird, öffnet sie sich lautlos."
  },
  AvgDialog_131225_Content_8 = {
    Text = "Scheinbar hat unser fürsorglicher Meister uns die Tür offen gelassen."
  },
  AvgDialog_131225_Content_9 = {Text = "Das ist..."},
  AvgDialog_131226_Content_1 = {
    Text = "Töte... einen Mord!"
  },
  AvgDialog_131226_Content_10 = {
    Text = "Ich habe alles gesehen. Du bist nicht durch dieses Tor gegangen, %player%. Dies ist nicht der Ort, an dem wir sein sollten."
  },
  AvgDialog_131226_Content_11 = {
    Text = "Ich finde es auch merkwürdig... dass sie nichts über die Auflösung und Misaq, diese Verderben, wissen."
  },
  AvgDialog_131226_Content_12 = {
    Text = "Aber das Aussehen dieser Stadt ist genau so wie vor der Katastrophe und in meiner Erinnerung. Vielleicht sollten wir jetzt zur Schule gehen und nachsehen, vielleicht finden wir etwas..."
  },
  AvgDialog_131226_Content_13 = {
    Text = "Ich komme gerade von dort. Es gibt hier keinen Misaq, %player%."
  },
  AvgDialog_131226_Content_14 = {Text = "Nein...?"},
  AvgDialog_131226_Content_15 = {
    Text = "Die Weltkarte im Laden sieht ganz anders aus als alles, was ich je gesehen habe, und die Jahre, die auf allen Kalendern vermerkt sind, unterscheiden sich vollständig von der Überschwemmungszeit."
  },
  AvgDialog_131226_Content_16 = {
    Text = "Das Seltsamste ist... diese Stadt hat kein Ende."
  },
  AvgDialog_131226_Content_17 = {
    Text = "Kein... Ende?"
  },
  AvgDialog_131226_Content_18 = {
    Text = "Wenn man weiterhin nach Norden in Richtung Misaq geht, kann man den Bereich von Lentiniën verlassen."
  },
  AvgDialog_131226_Content_19 = {
    Text = "Ich wurde auf dem Weg ebenfalls von diesen Spinnen angegriffen. Um ihnen zu entkommen, bin ich diesen Weg entlanggegangen, aber schließlich... bin ich wieder in die Nähe deiner Position zurückgekehrt, im Süden von Lentiniën."
  },
  AvgDialog_131226_Content_2 = {
    Text = "Die Menge schreit und stiebt auseinander. Noch bevor du es bemerkst, steht Wilhelm neben dir, sein goldenes Haar unverkennbar wie eh und je."
  },
  AvgDialog_131226_Content_20 = {
    Text = "Hier ist nicht Lentiniën, hier ist nicht Kardas."
  },
  AvgDialog_131226_Content_21 = {
    Text = "Es scheint, dass mein Gedächtnis nicht falsch ist... Der Durchgang wurde tatsächlich geschlossen, bevor ich eingetreten bin..."
  },
  AvgDialog_131226_Content_22 = {
    Text = "Du blickst auf die vertrauten Anblicke jenseits des Durchgangs und seufzt, während sich ein Gefühl der Leere in dir breitmacht."
  },
  AvgDialog_131226_Content_23 = {
    Text = "Ein Ort, der Lentiniën gleicht, eine Stadt ohne Ende, schwarze Spinnen, die aus dem Nichts auftauchen... und die Dame, der sie gehorchen..."
  },
  AvgDialog_131226_Content_24 = {
    Text = "Es ist zu früh, um sicher zu sein, aber ich glaube nicht, dass die Schließung des Tores und unsere Ankunft hier ein Zufall sind. Jemand hat all dies absichtlich inszeniert — wer auch immer diese Spinnen befehligt."
  },
  AvgDialog_131226_Content_25 = {
    Text = "Wir verstehen immer noch nichts. Wir müssen zuerst Informationen sammeln..."
  },
  AvgDialog_131226_Content_26 = {
    Text = "Zwei Personen..."
  },
  AvgDialog_131226_Content_27 = {Text = "Wer?!"},
  AvgDialog_131226_Content_28 = {
    Text = "Der silberne Glanz strahlt in Wilhelms mechanischer Handfläche, wie eine Klinge, die jederzeit gezogen werden kann."
  },
  AvgDialog_131226_Content_29 = {
    Text = "In diesem gefährlichen silbernen Licht siehst du den alten Mann, der dir gerade Nahrung reichen wollte."
  },
  AvgDialog_131226_Content_3 = {
    Text = "Wilhelm, der Seniorstudent... wann bist du... was ist hier los?"
  },
  AvgDialog_131226_Content_30 = {
    Text = "Ja...es bin ich..."
  },
  AvgDialog_131226_Content_31 = {
    Text = "Ist das... Ihres?"
  },
  AvgDialog_131226_Content_32 = {
    Text = "Der alte Mann öffnete die Hand. Das Emblem der Misaq-Universität, das zur Kommunikation verwendet wird, liegt ruhig in seiner rauen Handfläche."
  },
  AvgDialog_131226_Content_33 = {
    Text = "Ah! Das ist von eben, als ich im Kampf gefallen bin..."
  },
  AvgDialog_131226_Content_34 = {
    Text = "Das bedeutet mir sehr viel... vielen herzlichen Dank!"
  },
  AvgDialog_131226_Content_35 = {
    Text = "Unter Williams wachsamen Blicken hast du das Schulabzeichen zurückgenommen und sorgfältig aufbewahrt."
  },
  AvgDialog_131226_Content_36 = {
    Text = "Alter Mann... Haben Sie keine Angst vor dem, was gerade passiert ist?"
  },
  AvgDialog_131226_Content_37 = {
    Text = "Es ist Angst... Ich habe mein ganzes Leben hier verbracht, ich habe so etwas noch nie gesehen..."
  },
  AvgDialog_131226_Content_38 = {
    Text = "Aber ich sehe, dass das Ding für dich ziemlich wichtig ist. Du bist gerade hier angekommen, und wenn es verloren geht, weißt du wahrscheinlich nicht, wo du suchen sollst, also habe ich es dir gebracht."
  },
  AvgDialog_131226_Content_39 = {
    Text = "Vielen Dank Ihnen..."
  },
  AvgDialog_131226_Content_4 = {
    Text = "Hier ist nicht der Ort zum Reden. Los"
  },
  AvgDialog_131226_Content_40 = {
    Text = "Wir sind gerade hier angekommen und wissen viele Dinge nicht. Darf ich Sie nach einigen Dingen fragen?"
  },
  AvgDialog_131226_Content_41 = {
    Text = "Es macht mir nichts aus, noch etwas mehr Zeit mit euch beiden zu verbringen, aber ich fürchte, ich weiß sehr wenig über das, wonach ihr sucht."
  },
  AvgDialog_131226_Content_42 = {
    Text = "Ein Ort mit einer größeren Menschenmenge könnte euch besser dienen, denke ich."
  },
  AvgDialog_131226_Content_43 = {
    Text = "Gut, die Sachen sind geliefert, ich gehe dann zuerst zurück."
  },
  AvgDialog_131226_Content_44 = {
    Text = "Der alte Mann winkte ab, ignorierte eure Bitten und verließ die Gasse."
  },
  AvgDialog_131226_Content_45 = {
    Text = "Dieser alte Mann scheint keine bösen Absichten zu haben. Er hat recht, wir müssen so schnell wie möglich einen Ort finden, an dem die Informationen besser fließen."
  },
  AvgDialog_131226_Content_46 = {
    Text = "Ich kenne genau den richtigen Ort!"
  },
  AvgDialog_131226_Content_47 = {
    Text = "Wenn diese Stadt genau wie Lentiniën ist, dann wäre es der passendste Ort."
  },
  AvgDialog_131226_Content_48 = {
    Text = "Als ihr geht, lauert eine blassviolette Spinne gerade am Rand eures Blickfelds, kriecht an ihrem Faden entlang und schlüpft in einen Riss in der Wand, wo sie spurlos verschwindet."
  },
  AvgDialog_131226_Content_5 = {
    Text = "Wilhelm, der Seniorstudent packt dich und geht in die entgegengesetzte Richtung der Menge."
  },
  AvgDialog_131226_Content_6 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131226_Content_7 = {
    Text = "Hier sollte eigentlich niemand sein."
  },
  AvgDialog_131226_Content_8 = {
    Text = "Was geht hier vor? Warum ist Lentiniën so geworden..."
  },
  AvgDialog_131226_Content_9 = {
    Text = "Diese Spinnen, die uns angegriffen haben, und diese Person... könnte sie mit der Frau in Verbindung stehen, der wir auf dem Paradeis begegnet sind?"
  },
  AvgDialog_131227_Content_1 = {
    Text = "Tawil! Ich......"
  },
  AvgDialog_131227_Content_2 = {
    Text = "Ich verstehe, Hüter."
  },
  AvgDialog_131227_Content_3 = {
    Text = "Dein Schicksal wurde geändert. Du kannst nicht aufhören, und du solltest nicht aufhören."
  },
  AvgDialog_131227_Content_4 = {
    Text = "Arachne kann das Schicksal der Zukunft nicht aussprechen... Bitte sag mir, was ich tun soll..."
  },
  AvgDialog_131227_Content_5 = {
    Text = "Ich kann dir nicht sagen, was hinter der Tür ist. In dieser Angelegenheit gibt es jemanden, der besser geeignet ist, dir zu helfen als ich."
  },
  AvgDialog_131227_Content_6 = {
    Text = "Geh voran, Schutzherr. Dein Schicksal musst du selbst erkennen."
  },
  AvgDialog_131228_Content_1 = {
    Text = "Hmm... Helden und Clowns, die Marionetten des Schicksals... ein gutes Schauspiel."
  },
  AvgDialog_131228_Content_2 = {
    Text = "Arachne hat mir gesagt, dass der Schlüssel zum Entschlüsseln der Schlösser „Freude\" ist... Das ist dein Bereich, N."
  },
  AvgDialog_131228_Content_3 = {
    Text = "Pssst! Sei nicht so ungeduldig. Eine großartige Aufführung zu zerstören, ist die unverzeihlichste Sünde in diesem Universum."
  },
  AvgDialog_131228_Content_4 = {
    Text = "Komm, Hüter. So lange nicht gesehen, lass mich sehen, ob du neue Einsichten über Freude gewonnen hast?"
  },
  AvgDialog_131229_Content_10 = {
    Text = "Antworte mir... Liz! ..."
  },
  AvgDialog_131229_Content_11 = {
    Text = "Ihr Schicksalsfaden ist bereits zerbrochen... ihr Leben ist zu Ende."
  },
  AvgDialog_131229_Content_12 = {
    Text = "<Shake:Nein... wir können Nefraea nicht einfach so gewinnen lassen>! Sie muss für ihre Unverschämtheit bezahlen"
  },
  AvgDialog_131229_Content_13 = {
    Text = "Der Preis, den sie zahlen muss, ist bereits vom Schicksal für sie vorbereitet. Die Spur wird hier nicht enden."
  },
  AvgDialog_131229_Content_14 = {
    Text = "Aber du hast gerade gesagt, dass Liz jetzt schon......"
  },
  AvgDialog_131229_Content_15 = {
    Text = "Der Tod ist nur ein Teil des Schicksals. Dies ist meine Bühne, {Male=Mr.,Female=Miss} Schutzherr. Alle Schicksale sind Fäden in meinen Händen, und ich allein webe ihren Verlauf."
  },
  AvgDialog_131229_Content_16 = {Text = "!!!"},
  AvgDialog_131229_Content_17 = {
    Text = "<Shake:Warte, du meinst...>"
  },
  AvgDialog_131229_Content_18 = {
    Text = "Arachnes Gesicht war ausdruckslos. Sie ging auf den Ansager zu, der kurzzeitig von Nefraea besessen war. Das schwache Licht der Dämmerung umreißte ihre verschwommene, stabile Silhouette, wie das Schicksal selbst."
  },
  AvgDialog_131229_Content_19 = {
    Text = "Ha... hahaha... Arachne, du bist immer noch so, so arrogant! Hahahaha..."
  },
  AvgDialog_131229_Content_2 = {
    Text = "Die Feinde um dich herum sind gefallen, aber dein Angriff hat nicht aufgehört."
  },
  AvgDialog_131229_Content_20 = {
    Text = "Nefraea scheint etwas unglaublich Lustiges gesehen zu haben und lacht sich schrottig auf dem Boden."
  },
  AvgDialog_131229_Content_21 = {
    Text = "Verschmutze Liz' Schicksal und lasse sie dem Tod begegnen... Alles, was du tust, wird das Netz des Schicksals in Erinnerung behalten."
  },
  AvgDialog_131229_Content_22 = {
    Text = "Das falsche Schicksal wird korrigiert. Vor deinem Schicksal wartet natürlich der Preis auf dich."
  },
  AvgDialog_131229_Content_23 = {
    Text = "Arachne streckte die Hand aus und berührte sanft den Kopf dieser Leiche. Das Spinnrad in ihrer Hand drehte sich sanft, und alles um dich herum schien sich in dieser Drehung zu verzerren und neu zu formen ..."
  },
  AvgDialog_131229_Content_24 = {
    Text = "Die Fäden des Schicksals, höre den Ruf des Netzes. Gehe den einzigen Weg entlang und betrete die Bühne erneut..."
  },
  AvgDialog_131229_Content_25 = {
    Text = "Ihr Körper... ist verschwunden?"
  },
  AvgDialog_131229_Content_26 = {
    Text = "Mit dem Winken von Arachne's Fingern verbrannte der Leichnam von Liz über der Bühne lautlos und verwandelte sich in Glut, die in der Luft verwehte."
  },
  AvgDialog_131229_Content_27 = {
    Text = "Unter den abgefallenen Aschen erscheint ein neuer Körper vor dir."
  },
  AvgDialog_131229_Content_28 = {
    Text = "Ist das... der Ansager?"
  },
  AvgDialog_131229_Content_29 = {
    Text = "Die Dornen durchbohrten den Körper des Ansagers und hängten sie über die Bühne, alle Bewegungen und Winkel waren genau wie bei Liz."
  },
  AvgDialog_131229_Content_3 = {
    Text = "Du schreist und trittst verrückt auf das lächelnde Gesicht des Ansagers, bis es auf dem Holz des Bühnenbodens zertrümmert ist."
  },
  AvgDialog_131229_Content_30 = {
    Text = "Der Ansager hinterlässt ein grimmiges Lächeln, es gibt keinen weiteren Laut mehr."
  },
  AvgDialog_131229_Content_31 = {
    Text = "Arachne, du......"
  },
  AvgDialog_131229_Content_32 = {
    Text = "Entschuldigung, ich bin zu spät gekommen, ich habe gerade... ah"
  },
  AvgDialog_131229_Content_33 = {
    Text = "Die vertraute Gestalt hebt den Vorhang und betritt die Bühne. Ihr Blick streift über euch und verweilt auf der Leiche, die in der Luft hängt."
  },
  AvgDialog_131229_Content_34 = {
    Text = "Ihre Bewegungen... so schön..."
  },
  AvgDialog_131229_Content_35 = {
    Text = "Liz schien die vielen Leichen auf dem Boden und die stehenden Zuschauer vergessen zu haben. Sie trat in die Mitte der Bühne, ihre Hand strich über die Beine der hängenden Leiche, als ob sie die elegante Kurve nachahmen wollte."
  },
  AvgDialog_131229_Content_36 = {
    Text = "Arachne, hast du... das Schicksal des Ansagers und Liz getauscht?"
  },
  AvgDialog_131229_Content_37 = {
    Text = "Aber du hast gesagt, dass eine solche Belastung schwer zu ertragen ist..."
  },
  AvgDialog_131229_Content_38 = {
    Text = "Verbrauch hat nichts mit der Wahl zu tun. In meinem Schicksal ist das auch der Preis, den ich zahlen muss."
  },
  AvgDialog_131229_Content_39 = {
    Text = "Geh, %player%. Lass Fräulein Liz nicht warten."
  },
  AvgDialog_131229_Content_4 = {
    Text = "Ja genau... so ist es... Wut, Ausdruck! Was für ein großartiger Gesichtsausdruck..."
  },
  AvgDialog_131229_Content_40 = {
    Text = "Ätherische Augen und Atem. Der im Wind wehende Rock, der mit feinen grünen Flammen versehen ist. Jedes Zucken der Fingerspitzen gleicht einem sorgfältig choreografierten Tanz."
  },
  AvgDialog_131229_Content_41 = {
    Text = "Die blutige Gestalt, die gerade eben noch auf dich zugestürmt ist, überlagert sich mit der Frau vor dir. Liz steht da, lebendig und voller Leben—das kunstvolle Neuweben des Schicksals hat keine Spur an ihr hinterlassen."
  },
  AvgDialog_131229_Content_42 = {
    Text = "Nach einer Weile kam Liz aus ihrer Bewunderung für die Leiche zurück und wandte sich dir zu, der neben ihr stand."
  },
  AvgDialog_131229_Content_43 = {
    Text = "Ich habe heute zu Hause bis zum Nachmittag geschlafen und die Aufführung verpasst. So etwas ist mir noch nie passiert..."
  },
  AvgDialog_131229_Content_44 = {
    Text = "Offenbar habe ich einige wichtige Dinge verpasst?"
  },
  AvgDialog_131229_Content_45 = {
    Text = "Liz' Augen streiften über die Leichen und Blutspuren auf dem Boden, die sie ignoriert hatte."
  },
  AvgDialog_131229_Content_46 = {
    Text = "Nein, du hast nichts verpasst, Liz."
  },
  AvgDialog_131229_Content_47 = {
    Text = "Du... alles in Ordnung? Hast du irgendwelche Beschwerden?"
  },
  AvgDialog_131229_Content_48 = {
    Text = "Mir geht es gut. Aber sag mir, {Male=sir,Female=miss}, haben wir uns schon einmal getroffen? Du kommst mir seltsam vertraut vor..."
  },
  AvgDialog_131229_Content_49 = {
    Text = "Vielleicht liegt es daran, dass ich als dein Anhänger viele deiner Aufführungen gesehen habe."
  },
  AvgDialog_131229_Content_5 = {
    Text = "Das Gesicht, das wie Schlamm aussieht, lächelt, und eine schwache Stimme kommt aus ihrer zerbrochenen Kehle."
  },
  AvgDialog_131229_Content_50 = {
    Text = "Du lächelst sie an. Diese Bühne hat ihre eigenen Geschichten, und du hast nicht vor, ihr von den alten Dingen zu erzählen."
  },
  AvgDialog_131229_Content_51 = {
    Text = "Wir sind hier für das „Gute\"."
  },
  AvgDialog_131229_Content_52 = {
    Text = "Die Freundin von Frau Sorel ist endlich gekommen. Ich hatte schon Sorge, dass ich den „guten\" Herrn bei der Aufführung vernachlässigen würde... Bitte folgen Sie mir, mein Zuhause ist nicht weit von der Tanzgruppe entfernt."
  },
  AvgDialog_131229_Content_53 = {
    Text = "Liz wirft einen langen Blick auf die Leiche an der Wand, bevor sie dich hinter den Vorhang führt."
  },
  AvgDialog_131229_Content_54 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_131229_Content_55 = {
    Text = "Also... eigentlich sollte mein Körper auf der Bühne hängen..."
  },
  AvgDialog_131229_Content_56 = {
    Text = "Es bleibt keine Zeit, um um die verstorbenen Tanzpartner zu trauern, und ich vergesse, denjenigen zu danken, der mich wieder zum Leben erweckt hat."
  },
  AvgDialog_131229_Content_57 = {
    Text = "In euren Erzählungen funkelten Liz' Augen wie tanzende Flammen. Sie streckte die Hand aus und nahm die gleiche Pose wie der Leichnam ein."
  },
  AvgDialog_131229_Content_58 = {
    Text = "Ist das Bild schön?"
  },
  AvgDialog_131229_Content_59 = {
    Text = "Die höchste Schönheit der Welt zeigt sich nur in zwei Momenten, einem ist die Geburt, der andere der Tod. Es ist ein unvergleichliches Bild, Miss Liz."
  },
  AvgDialog_131229_Content_6 = {
    Text = "Nefraea ist nicht hier, das ist nur eine Illusion, die sie hinterlassen hat. Lass dich nicht von Wut blenden, Schutzherr {Male=Herr, Female=Dame}."
  },
  AvgDialog_131229_Content_60 = {
    Text = "Danke, Frau Arachne. Sie sind die Weberin des Schicksals, da denke ich, dass Sie oft von dieser Schönheit umgeben sind. Das ist wirklich... beneidenswert."
  },
  AvgDialog_131229_Content_61 = {
    Text = "Zu viele Schätze werden zur Strafe werden."
  },
  AvgDialog_131229_Content_62 = {
    Text = "Wenn das Ihre Strafe ist, was ist dann die Belohnung, die Sie sich wünschen?"
  },
  AvgDialog_131229_Content_63 = {
    Text = "Liz bemerkte nicht die kurze Pause von Arachne und öffnete die Tür zum Gästezimmer im Innenhof."
  },
  AvgDialog_131229_Content_64 = {
    Text = "Hier ist die vorübergehende Unterkunft des Herrn „Güte\". Herr „Güte\", Ihr Freund ist gekommen, um Sie abzuholen."
  },
  AvgDialog_131229_Content_65 = {
    Text = "„Gutherzig\"Herr?"
  },
  AvgDialog_131229_Content_66 = {
    Text = "Ein einfacher Raum, ohne dass irgendein Möbelstück nicht hierher gehört, ohne dass irgendeine Person nicht hierher gehört."
  },
  AvgDialog_131229_Content_67 = {
    Text = "In dem leeren Zimmer liegt ein einfacher Zettel still auf dem Bücherregal."
  },
  AvgDialog_131229_Content_68 = {
    Text = "„Es tut mir leid, dass ich mich ohne Abschied zurückgezogen habe. Frau Sorel macht sich Sorgen, dass Sie in Schwierigkeiten geraten könnten, weshalb es eine neue Vereinbarung gibt. Ich werde mich in die Villa der Erinnerungen zurückziehen.\""
  },
  AvgDialog_131229_Content_69 = {
    Text = "„Für Ihre Fürsorge bin ich Ihnen sehr dankbar. Ich werde Ihnen diese Gnade gewissenhaft zurückzahlen.\""
  },
  AvgDialog_131229_Content_7 = {
    Text = "<Shake:Puh... Puh...>"
  },
  AvgDialog_131229_Content_70 = {
    Text = "Frau Sorel wird uns sicherlich informieren, wenn sie den Plan ändert..."
  },
  AvgDialog_131229_Content_71 = {
    Text = "Du blickst in die unbewegten Augen von Arachne. In diesem scheinbar nie verschwindenden ruhigen Lächeln siehst du einen kurzen Schatten vorbeiziehen."
  },
  AvgDialog_131229_Content_72 = {
    Text = "„Erinnerung\" ist ein Wanderer. Sie hat kein Zuhause."
  },
  AvgDialog_131229_Content_73 = {
    Text = "Was?! Das..."
  },
  AvgDialog_131229_Content_74 = {
    Text = "„Erinnern\" des Schicksals, fürchte ich, wurde auch bereits von Nefraea verfälscht. Die beiden sind jetzt in Gefahr geraten."
  },
  AvgDialog_131229_Content_75 = {
    Text = "Entschuldigung, ich habe nicht gedacht..."
  },
  AvgDialog_131229_Content_76 = {
    Text = "Es ist nicht deine Verantwortung, Miss Liz."
  },
  AvgDialog_131229_Content_77 = {
    Text = "Da Nefraea in der Lage ist, dein Schicksal zu verändern, ist es auch nicht schwer, die Menschen um dich herum zu finden. Das sind die Probleme, die wir lösen müssen."
  },
  AvgDialog_131229_Content_78 = {
    Text = "Die Tinte oben ist noch nicht ganz trocken, die Zeit, in der Nefraea zuschlagen wird, ist nicht weit entfernt. Wenn wir jetzt schnell handeln, könnten wir vielleicht noch rechtzeitig sein..."
  },
  AvgDialog_131229_Content_79 = {
    Text = "Liz, es gibt einige Dinge, die ich diesmal nicht rechtzeitig sagen kann..."
  },
  AvgDialog_131229_Content_8 = {
    Text = "Als das lächelnde Gesicht nicht mehr zu erkennen war, hast du endlich angehalten."
  },
  AvgDialog_131229_Content_80 = {
    Text = "Es wird andere Gelegenheiten geben, {Male=Mr.,Female=Miss} Schutzherr. Ich hoffe, mein nächster Tanz bewegt dich genauso sehr."
  },
  AvgDialog_131229_Content_81 = {
    Text = "Nachdem Liz euch mit einem einfachen Lächeln verabschiedet hat, kümmert sie sich nicht mehr um eure komplizierten Geschichten."
  },
  AvgDialog_131229_Content_82 = {
    Text = "Sie hob ihren Arm und nahm die gleiche Bogenform wie die Leiche an, in dem Versuch, den Tanz wiederherzustellen, der immer in ihrem Kopf schwebte."
  },
  AvgDialog_131229_Content_83 = {
    Text = "Eine sanfte Brise bewegt ihren Rock, als ob ein Schwan gerade fliegt."
  },
  AvgDialog_131229_Content_9 = {
    Text = "Der kontrollierte Leichnam von Liz hat alle Lebendigkeit verloren. Du legst ihren blutigen und zerfetzten Körper vorsichtig auf den Boden und öffnest den geistigen Link zu ihr."
  },
  AvgDialog_131230_Content_1 = {
    Text = "Vorhang fällt"
  },
  AvgDialog_131230_Content_10 = {
    Text = "Da diese Stadt bereits neu erschaffen wurde... dachte ich, du würdest die Dinge, die verschwunden sind, hierher bringen."
  },
  AvgDialog_131230_Content_11 = {
    Text = "...Vermisst du sie nicht?"
  },
  AvgDialog_131230_Content_12 = {
    Text = "Ich würde lieber sehen, wie die Bühne sich selbst präsentiert, als eine Tasse Kaffee zu trinken."
  },
  AvgDialog_131230_Content_13 = {
    Text = "Ich habe diesen Ort mit Erinnerungen neu erschaffen, aber ich kann die Tatsache, dass es eine ganz neue Bühne ist, immer noch nicht ändern."
  },
  AvgDialog_131230_Content_14 = {
    Text = "Der neue Kaffee hier hat auch seinen eigenen Geschmack, nicht wahr?"
  },
  AvgDialog_131230_Content_15 = {
    Text = "Arachne lächelte und nahm einen kleinen Schluck von der bitteren Flüssigkeit."
  },
  AvgDialog_131230_Content_16 = {
    Text = "Nefraea... Wie ist es zuletzt ausgegangen?"
  },
  AvgDialog_131230_Content_17 = {
    Text = "Eure Schicksalsfäden wurden wieder miteinander verwoben. Bedeutet das... ihr seid wieder ein und dieselbe Person?"
  },
  AvgDialog_131230_Content_18 = {
    Text = "Die Dinge, die einst Nefraea gehörten, ihre Eigenschaften, ihr ursprüngliches Wesen, sind zurück in mein Schicksal gekehrt. Oder besser gesagt, wie Sie wissen - sie waren nie fort."
  },
  AvgDialog_131230_Content_19 = {
    Text = "Aber das Schicksalsnetz ist das einzige. Derjenige, den Sie kennen, Nefraea, diejenige, die im Abgrund versinkt und vom Schicksal verlassen wurde, hat keinen Faden, der zu diesem Netz gehört."
  },
  AvgDialog_131230_Content_2 = {
    Text = [[
<Italic:Lascia ch'io pianga / Lass mich beweinen
mia cruda sorte, / mein grausames Schicksal,>]]
  },
  AvgDialog_131230_Content_20 = {
    Text = "Sie... verblasste, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131230_Content_21 = {
    Text = "Das Spinnrad dreht sich sanft und unaufhörlich. Arachne schloss die Augen, hob sanft den Kopf und schnupperte den schwachen Blumenduft in der Luft."
  },
  AvgDialog_131230_Content_22 = {
    Text = "Das verlassene Schicksal sieht sich nur mit ewiger Gefangenschaft und vollständigem Verschwinden konfrontiert. Das ist wirklich eine grausame Sache..."
  },
  AvgDialog_131230_Content_23 = {
    Text = "In jedem Augenblick verlangt das Schicksal eine Auswahl. Die richtigen Wege bleiben bestehen, während die falschen verworfen werden. Bis wir den Wahren Weg finden, ist dies so unausweichlich wie der Zusammenbruch des Universums selbst."
  },
  AvgDialog_131230_Content_24 = {
    Text = "Bis wir den Wahren Weg finden, ist dies so unausweichlich wie der Zusammenbruch des Universums selbst."
  },
  AvgDialog_131230_Content_25 = {
    Text = "Sag mir, {Male=Mr.,Female=Miss} Schutzherr, wenn du die Macht hättest, das Schicksal zu lenken, würdest du es ins Chaos stürzen lassen? Oder würdest du die Auswahl für andere treffen, selbst wenn es bedeutete, den Namen eines Mörders zu tragen?"
  },
  AvgDialog_131230_Content_26 = {
    Text = "Das...ich..."
  },
  AvgDialog_131230_Content_27 = {
    Text = "Dies ist lediglich eine Debatte zu deiner Unterhaltung, keine Frage, die du beantworten musst. Du trägst bereits viel zu viel; du musst dir diese Last nicht auch noch aufbürden."
  },
  AvgDialog_131230_Content_28 = {
    Text = "Arachne lächelte und schüttelte den Kopf."
  },
  AvgDialog_131230_Content_29 = {
    Text = "Die Auswahl ist eine Form von Macht, doch viele entscheiden sich, sie aufzugeben, selbst wenn sie in ihrer Reichweite liegt."
  },
  AvgDialog_131230_Content_3 = {
    Text = "<Italic:E che sospiri la libertà! / und seufze nach meiner Freiheit!>"
  },
  AvgDialog_131230_Content_30 = {
    Text = "Zu wählen bedeutet, die Konsequenzen zu tragen, und das ist keine leichte Aufgabe, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131230_Content_31 = {
    Text = "Ich bin der Manipulator des Schicksals, alle Konsequenzen des Schicksals werden von mir getragen."
  },
  AvgDialog_131230_Content_32 = {
    Text = "Dies sind die Worte, die mir gegeben wurden, als ich zum ersten Mal an die Tür von Chokmah-Da'at klopfte. Darüber freue ich mich."
  },
  AvgDialog_131230_Content_33 = {
    Text = "Also du... obwohl du dein Schicksal nicht sehen kannst, weißt du eigentlich alles, was jetzt passiert..."
  },
  AvgDialog_131230_Content_34 = {
    Text = "Die warme Sonne scheint auf diese Straße, aber wenn man Arachne ins Gesicht sieht und sich vorstellt, was diese Person Tag für Tag ertragen muss, kann selbst man nicht anders, als einen Schauer über den Rücken zu spüren."
  },
  AvgDialog_131230_Content_35 = {
    Text = "Romantik bringt Dummheit, Güte bringt Zerbrechlichkeit, Erinnerungen bringen Schmerz..."
  },
  AvgDialog_131230_Content_36 = {
    Text = "Obwohl du dich schon lange darauf vorbereitet hast, hast du sie nie wirklich losgelassen. Warum?"
  },
  AvgDialog_131230_Content_37 = {
    Text = "Für dich wird es einfacher sein, sie aufzugeben."
  },
  AvgDialog_131230_Content_38 = {
    Text = "Sind Sie schon einmal im Gefängnis gewesen? Die Gefangenen, die jahrelang eingesperrt sind, haben immer einige Dinge bei sich, die sie schätzen."
  },
  AvgDialog_131230_Content_39 = {
    Text = "Eine im Kampf gewonnene Medaille, eine vererbte Uhr, ein Familienfoto..."
  },
  AvgDialog_131230_Content_4 = {
    Text = "Der melodische Gesang hallt durch die Straßen und weht sanft mit dem warmen Wind. Die Passanten auf dem Weg bleiben stehen oder gehen weiter und genießen ihr ruhiges Leben in diesem Frühlingslicht."
  },
  AvgDialog_131230_Content_40 = {
    Text = "Für die Gefangenen sind diese schmerzhaften Begierden die Motivation, um weiterzuleben."
  },
  AvgDialog_131230_Content_41 = {
    Text = "Sie bewahren diese wertvollsten Dinge sorgfältig auf, bis sie dem Tod nahe sind und die wertlosen Dinge nacheinander übergeben."
  },
  AvgDialog_131230_Content_42 = {
    Text = "...Im Käfig des Schicksals haben wir nichts anderes, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131230_Content_43 = {
    Text = "<Italic:Il duolo infranga / Möge der Schmerz zerbrechen\nqueste ritorte / diese Ketten>"
  },
  AvgDialog_131230_Content_44 = {
    Text = "<Italic:de miei martiri / meiner Qualen\nsol per pietà. / allein aus Mitleid>"
  },
  AvgDialog_131230_Content_45 = {
    Text = "Der Opernsänger am Straßenrand singt vom Schicksalsfluss, der durch diese Stadt fließt. Arachne nippt an ihrem Kaffee und hört aufmerksam zu. Von Anfang bis Ende hat sich der Winkel ihres Lächelns nie verändert."
  },
  AvgDialog_131230_Content_46 = {
    Text = "Weißt du, {Male=Mr.,Female=Miss} Schutzherr, ich träume oft immer wieder von derselben Szene."
  },
  AvgDialog_131230_Content_47 = {
    Text = "Es war ein wunderschönes Theater, nur ich und Nefraea waren dort. Genau in diesem schönen Lied habe ich sie verabschiedet."
  },
  AvgDialog_131230_Content_48 = {
    Text = "Sie sehen, selbst wenn wir unser eigenes Schicksal nicht klar erkennen können, ist sein Urteil überall gegenwärtig."
  },
  AvgDialog_131230_Content_49 = {
    Text = "<Italic:E che sospiri la libertà! / Und seufze nach meiner Freiheit!\nE che sospiri la libertà! / Und seufze nach meiner Freiheit!>"
  },
  AvgDialog_131230_Content_5 = {
    Text = "Du nimmst die Tasse Kaffee und trinkst einen großen Schluck."
  },
  AvgDialog_131230_Content_50 = {
    Text = "Die Stimme des Opernsängers verstummt niemals, und der Faden der Spinnräder dreht sich ewig. Arachne legt den Becher in ihrer Hand nieder und klatscht aufrichtig leise zusammen mit den verweilenden Zuschauern."
  },
  AvgDialog_131230_Content_51 = {
    Text = "Jedenfalls ist eine Aufführung zu Ende gegangen, und diese Bühne wird ihre kurze Pause erleben. Wir Schauspieler werden uns bald auf die nächste Bühne begeben."
  },
  AvgDialog_131230_Content_52 = {
    Text = "Der Einfluss von Nefraea ist verschwunden, und jetzt sollte der Zugang zu Kardas wieder geöffnet werden können?"
  },
  AvgDialog_131230_Content_53 = {
    Text = "Der Zugang zu Kardas liegt im Schicksal dieser Welt. Du hast auch schon versucht, über Dimensionen zu reisen."
  },
  AvgDialog_131230_Content_54 = {
    Text = "Die Gefahr darin ist dir bereits bekannt."
  },
  AvgDialog_131230_Content_55 = {
    Text = "In der Tat... die Blicke von Toguwaibo möchte ich nicht noch einmal begegnen..."
  },
  AvgDialog_131230_Content_56 = {
    Text = "Arachne, du kannst das Schicksal dieser Welt kontrollieren. Vielleicht kannst du mir helfen?"
  },
  AvgDialog_131230_Content_57 = {
    Text = "Ich bin gerne zu Diensten, aber in dieser Welt ist nur diese Stadt meine Bühne. Der Herr des Schicksals in dieser Welt bin nicht ich."
  },
  AvgDialog_131230_Content_58 = {
    Text = "Unglaublich!..."
  },
  AvgDialog_131230_Content_59 = {
    Text = "Der Meister dieser Welt besitzt Fähigkeiten, die selbst meine Reichweite übersteigen. Diese Welt existiert einzig und allein, weil Er es so wollte."
  },
  AvgDialog_131230_Content_6 = {
    Text = "Nicht mal annähernd so gut wie bosnischer Kaffee."
  },
  AvgDialog_131230_Content_60 = {
    Text = "Solange der Durchgang nicht absichtlich geöffnet wird, bleibt dieser Ort selbst vor dem Blick des Ursprünglichen verborgen... Genau deshalb habe ich mich entschieden, hier zu verweilen."
  },
  AvgDialog_131230_Content_61 = {
    Text = "Soll das heißen... Wenn ich den Durchgang öffne, wird es hier gefährlich"
  },
  AvgDialog_131230_Content_62 = {
    Text = "Wie ich sagte, hat das Schicksal seinen eigenen Verlauf. Hier abzuleben, ist nur ein langsames Warten auf den Tod. Dich nach Kardas zurückzubringen, ist auch der sehnliche Wunsch des Herrschers dieser Welt."
  },
  AvgDialog_131230_Content_63 = {
    Text = "Für das Licht, das uns am Ende des Schicksalsweges erwartet, ist dies eine Gefahr, die wir mehr als bereitwillig auf uns nehmen."
  },
  AvgDialog_131230_Content_64 = {
    Text = "Ich verstehe... Ich verstehe es jetzt."
  },
  AvgDialog_131230_Content_65 = {
    Text = "Wo kann ich ihn finden?"
  },
  AvgDialog_131230_Content_66 = {
    Text = "Sein Schicksalsfaden ist so weit wie das Sternenmeer und so gering wie der Staub. Nur durch das Erfassen des Schicksals kann ich dir nicht direkt seinen Standort zeigen."
  },
  AvgDialog_131230_Content_67 = {
    Text = "Aber vielleicht kann das dir helfen."
  },
  AvgDialog_131230_Content_68 = {
    Text = "Arachne reicht dir eine Seite des Broschüre. Du runzelst die Stirn und schaust auf die schönen, religiös anmutenden Schnörkelbuchstaben darauf."
  },
  AvgDialog_131230_Content_69 = {
    Text = "Stellenanzeige:"
  },
  AvgDialog_131230_Content_7 = {
    Text = "Nachdem ich beim letzten Mal auf dieser Bühne probiert habe, fand ich den Geschmack auch sehr gut. Leider ist die Familie, die diesen Kaffee erfunden hat, auf dieser Bühne schon vor langer Zeit verschwunden."
  },
  AvgDialog_131230_Content_70 = {
    Text = "Der große Meister, der Auserwählte Gottes, der Executor des höchsten Gottes, der rechtmäßige Erbe des großartigen Glaubens, der Erlöser des Leidens, der Freund des Götterkönigs ist im nördlichen Kontinent erschienen. Der Glaube entwickelt sich rasant, die Gläubigen können sich schnell hier versammeln."
  },
  AvgDialog_131230_Content_71 = {
    Text = "Die ersten zwölf Gläubigen, die ankommen, werden zu Heiligen ernannt und werden für immer an der Seite der Fee stehen, unter dem ewigen Schutz der Gottheit..."
  },
  AvgDialog_131230_Content_72 = {
    Text = "Was ist das...?"
  },
  AvgDialog_131230_Content_73 = {
    Text = "Wie Sie sehen können, handelt es sich um eine sorgfältig hergestellte Broschüre."
  },
  AvgDialog_131230_Content_74 = {
    Text = "Wie kann der Inhalt darüber so seltsam sein... Arachne, kannst du den Verlauf des Schicksals sehen? Bist du sicher, dass das kein Betrug ist?"
  },
  AvgDialog_131230_Content_75 = {
    Text = "An seinem Faden sah ich dein Bild. Ich bin mir sicher, dass es dein Schicksal ist, das du begrüßen wirst."
  },
  AvgDialog_131230_Content_76 = {
    Text = "Ob es Hilfe oder Gefahr ist, kann ich nicht sagen. Aber ich weiß, dass dies die einzige Verbindung zwischen dir und dem Meister dieser Welt ist."
  },
  AvgDialog_131230_Content_77 = {
    Text = "Arachne streckte ihre Hand über das lächerliche Broschüre und nahm einen dir unsichtbaren Gegenstand, den sie in deine Handfläche legte."
  },
  AvgDialog_131230_Content_78 = {
    Text = "Und das ist...?"
  },
  AvgDialog_131230_Content_79 = {
    Text = "Bald schimmert ein feiner Faden mit mattem Glanz in deiner Hand."
  },
  AvgDialog_131230_Content_8 = {
    Text = "Du schaust dich in dieser Stadt um. Brick Crossroads, Zeitfalten-Secondhandbuchladen, duftender Marktkrämer..."
  },
  AvgDialog_131230_Content_80 = {
    Text = "Dies ist der Katalysator, der dich an jenes Schicksal bindet. Er wird dich dorthin führen, wo du sein sollst."
  },
  AvgDialog_131230_Content_81 = {
    Text = "Ich verstehe. Sobald sich Wilhelm, der Seniorstudent, erholt hat, werden wir..."
  },
  AvgDialog_131230_Content_82 = {
    Text = "In meinem kurzen Blick in deine Fäden sah ich eine interessante Geschichte."
  },
  AvgDialog_131230_Content_83 = {
    Text = "Ich konnte dein Ende nicht sehen, und darüber bin ich froh. Es bedeutet, dass mir noch die Ehre zuteilwird, Zuschauerin deines Schicksals zu sein."
  },
  AvgDialog_131230_Content_84 = {
    Text = "Ich glaube, keine Geschichte verdient es, ungehört zu bleiben... Also bitte, es besteht kein Grund zur Eile. Lasst uns diese Oper bis zu ihrem Ende anhören, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131230_Content_85 = {
    Text = "Die Stimme des Opernsängers schwebt erneut über die Straßen. Arachne schließt die Augen, die Sonne fällt auf ihr ruhiges Antlitz, so sanft wie die Frühlinge, die sie bereits verloren hat."
  },
  AvgDialog_131230_Content_86 = {
    Text = "Die Spindel dreht sich. Das Lied hört niemals auf. Menschen gehen vorbei, und unzählige Fäden, die du nicht sehen kannst, sammeln und weben sich um sie herum."
  },
  AvgDialog_131230_Content_87 = {
    Text = "Du schaust auf das lächelnde Gesicht von Arachne. Du siehst, dass um sie herum nichts ist."
  },
  AvgDialog_131230_Content_9 = {
    Text = "Alles scheint unverändert zu sein, selbst die verwitterten Rostflecken auf dem Laden Schild sind genau so wie in deiner Erinnerung."
  },
  AvgDialog_131231_Content_1 = {
    Text = "Puh... Zum Glück habe ich es geschafft..."
  },
  AvgDialog_131231_Content_10 = {
    Text = "Sorel schloss leicht die Augen und musterte Arachne. Sie stellte fest, dass ihre stolze Fähigkeit, Menschen zu erkennen, völlig versagt hatte. Sie konnte die Vergangenheit der Person vor ihr nicht erkennen und konnte ihre Wünsche nicht erahnen."
  },
  AvgDialog_131231_Content_11 = {
    Text = "Alles, was sie sich schnell von dem Gesicht gemerkt hatte, vergaß sie in dem Moment des Blinzelns. Sorels Mundwinkel zuckten amüsiert."
  },
  AvgDialog_131231_Content_12 = {
    Text = "Zwei faszinierende Gäste. Dieser Salon wird mir ein Leben lang in Erinnerung bleiben. Bitte setzen Sie sich."
  },
  AvgDialog_131231_Content_13 = {
    Text = "Sorel drehte sich um, setzte sich auf das Sofa und winkte euch zu."
  },
  AvgDialog_131231_Content_14 = {
    Text = "Ich hatte mehrere Begegnungen mit der „Güte\". Er kam, um mich zu finden und Schutz bei mir zu suchen."
  },
  AvgDialog_131231_Content_15 = {
    Text = "Ihr habt mich gerettet. Ich kann euch nicht klar sehen, aber ich kann erkennen, dass ihr keine bösen Absichten habt."
  },
  AvgDialog_131231_Content_16 = {
    Text = "Ja, Frau Sorel. Wir sind hier, um ihn zu retten."
  },
  AvgDialog_131231_Content_17 = {
    Text = "Er ist nicht in diesem Herrenhaus."
  },
  AvgDialog_131231_Content_18 = {
    Text = "Aber du hast gerade gesagt..."
  },
  AvgDialog_131231_Content_19 = {
    Text = "Wie Sie sehen können, ist mein Anwesen auch nicht sicher."
  },
  AvgDialog_131231_Content_2 = {
    Text = "Nachdem du Karens Zustand bestätigt hast, stehst du auf und wischst dir den kalten Schweiß von der Stirn."
  },
  AvgDialog_131231_Content_20 = {
    Text = "Sorel hob ihren Arm, als ob sie kostbare Sammlerstücke präsentierte, und blickte auf die durcheinanderliegenden Leichen im prächtigen und ordentlichen Raum."
  },
  AvgDialog_131231_Content_21 = {
    Text = "Das ist ein gutherziger, aber nicht dummer Herr. Ich kann sehen, dass er sich in einer sehr kritischen Lage befindet."
  },
  AvgDialog_131231_Content_22 = {
    Text = "Viele wissen von meiner Freundschaft mit ihm. Es war keine kluge Entscheidung, ihn im Anwesen zu verstecken."
  },
  AvgDialog_131231_Content_23 = {
    Text = "Wo ist er jetzt?"
  },
  AvgDialog_131231_Content_24 = {
    Text = "Sorel steht auf und geht zu einem Ölgemälde. Du folgst ihr und betrachtest das Bild."
  },
  AvgDialog_131231_Content_25 = {
    Text = "Das ist...!"
  },
  AvgDialog_131231_Content_26 = {
    Text = "Vor einigen Jahren besuchte ich das Lentiniën-Theater, um eine Aufführung der Schwäne-Tanzgruppe zu sehen. Es war ursprünglich eine einfache gesellschaftliche Veranstaltung, aber ich war tief von ihrem Tanz beeindruckt."
  },
  AvgDialog_131231_Content_27 = {
    Text = "In den letzten Jahren habe ich gelegentlich hinter die Bühne besucht, wenn ich das Ballett zu einer Aufführung eingeladen habe. Wir hatten keine wirkliche Beziehung, und genau deshalb ist das Ballett, dem sie angehört, der passendste Ort, um diese Person der „Güte\" unterzubringen."
  },
  AvgDialog_131231_Content_28 = {
    Text = "Im Gemälde trägt Liz ätherische Tanzkleidung und springt hoch in die Luft wie ein Schwan im Flug."
  },
  AvgDialog_131231_Content_29 = {
    Text = "Liz... wo ist ihre Tanzgruppe jetzt?"
  },
  AvgDialog_131231_Content_3 = {
    Text = "Karen sollte es gut gehen. Sie ist etwas betroffen, aber nach einer Weile der Ruhe wird es besser werden."
  },
  AvgDialog_131231_Content_30 = {
    Text = "Dem allmählich klarer werdenden Schicksalsleine folgend, blickte Arachne aus dem Fenster auf den Ort, der mit der Leine verbunden und von dichtem Wald verborgen war."
  },
  AvgDialog_131231_Content_31 = {
    Text = "An einem Ort, den du bestens kennst."
  },
  AvgDialog_131231_Content_4 = {
    Text = "Ich kann mich an jedes Gesicht erinnern, das ich gesehen habe, aber du fühlst dich seltsam an. Ich kann mir nicht sicher sein, ob ich dich schon einmal gesehen habe... Das ist mir noch nie passiert."
  },
  AvgDialog_131231_Content_5 = {
    Text = "Sorel nahm die unversehrte Weinflasche vom Couchtisch, goss sie in das Glas, überquerte die im Raum schmelzenden Leichen und reichte euch das Glas."
  },
  AvgDialog_131231_Content_6 = {
    Text = "Vierzig Jahre alter Portwein, mein persönlicher Schatz, die Hyänen unten haben nicht das Recht, ihn zu kosten. Egal wer ihr seid und warum ihr hier seid, ich denke, dieses Glas Wein sollte euch gehören."
  },
  AvgDialog_131231_Content_7 = {
    Text = "Wir sind für das „Gute\" hierher gekommen, Frau Sorel."
  },
  AvgDialog_131231_Content_8 = {
    Text = "Arachne nahm das Weinglas und nickte Sorel mit einem Lächeln zu."
  },
  AvgDialog_131231_Content_9 = {
    Text = "Als sie nicht sprach, fiel sie wie ein Spinnennetz im Morgenlicht kaum auf. Als sie zu sprechen begann, schien das gesamte Licht im Raum sich auf sie zu konzentrieren."
  },
  AvgDialog_131232_Content_1 = {
    Text = "Was für ein spannender Kampf, Schwester."
  },
  AvgDialog_131232_Content_10 = {
    Text = "Du und dein Diener seid die Verlorenen des Schicksals, die Fäden eures Schicksals kann ich nicht erfassen. Doch deine Fähigkeiten stammen von mir, ich kann mein eigenes Schicksal nicht erkennen, und du ebenso."
  },
  AvgDialog_131232_Content_11 = {
    Text = "Du und ich... das ist ein sinnloser Krieg, der zum Stillstand verurteilt ist. Er hätte nicht stattfinden sollen."
  },
  AvgDialog_131232_Content_12 = {
    Text = "Natürlich, natürlich. Für dich sollten wir, die bereits verworfenen Dinge, im Grab des Schicksals verschwinden, zersetzt, ausgelöscht, bis in alle Ewigkeit, für immer."
  },
  AvgDialog_131232_Content_13 = {
    Text = "Leider kannst du Ihn nicht erkennen... Selbst wenn du über große Stärke verfügst, wie kannst du mit dieser höchsten Gottheit vergleichen?"
  },
  AvgDialog_131232_Content_14 = {
    Text = "Du weißt es. Du weißt genau, dass alles vergeblich ist. Doch du kannst nicht aufhören, das Netz zu weben..."
  },
  AvgDialog_131232_Content_15 = {
    Text = "Da du bereits gesehen hast, kannst du die durcheinander geratenen Linien nicht ertragen. Da du über diese Fähigkeit verfügst, kannst du nicht tatenlos zusehen, wie die Welten in endloses Chaos geraten."
  },
  AvgDialog_131232_Content_16 = {
    Text = "Du bringst ihnen trügerische Ruhe und führst sie auf einen Weg, der unweigerlich zur Vernichtung führt."
  },
  AvgDialog_131232_Content_17 = {
    Text = "Was für eine traurige Person, Arachne."
  },
  AvgDialog_131232_Content_18 = {
    Text = "Das ist unser Schicksal, Nefraea."
  },
  AvgDialog_131232_Content_19 = {
    Text = "Ah... ich scheine ein wenig müde zu sein. Mit Narren zu streiten ist das Langweiligste auf der Welt."
  },
  AvgDialog_131232_Content_2 = {
    Text = "Die lebhafte Bar wurde still, die auf dem Boden liegenden Leichen verwandelten sich in schwarze, klebrige Flüssigkeit und Pulver, das im sanften Licht verschwand."
  },
  AvgDialog_131232_Content_20 = {
    Text = "Willkommen zur zweiten Akt dieser Geschichte. Dies ist deine Bühne, aber ab jetzt werde ich die Geschichte schreiben."
  },
  AvgDialog_131232_Content_21 = {
    Text = "Der Einstieg ist am wichtigsten, oder? Wie sollten wir ihn nennen... Ah, nennen wir es „Wiedersehen\", was hältst du davon?"
  },
  AvgDialog_131232_Content_22 = {
    Text = "Nefraea war mit ihrem Namen ziemlich zufrieden. Sie tauchte ihre Gliedmaßen in den alten Wein im Becher, steckte ihn sich in den Mund und stieß einen sehnsüchtigen Seufzer aus."
  },
  AvgDialog_131232_Content_23 = {
    Text = "Darauf habe ich schon viel zu lange, zu lange gewartet. Ich werde diese Geschichte mit dir, meine liebe Schwester, richtig genießen."
  },
  AvgDialog_131232_Content_24 = {
    Text = "Es gibt keine Gelegenheit mehr, euch nachzufragen. Nefraea's scharfe Krallen streichen sanft über den Rand von Arachne's Wange und fallen dann zusammen mit ihrem Körper zu Boden."
  },
  AvgDialog_131232_Content_25 = {Text = "Warte...!"},
  AvgDialog_131232_Content_26 = {
    Text = "Sie ist nicht hier, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131232_Content_27 = {
    Text = "Ein Geräusch des Brodelns ertönte, als schwarzer Schleim erneut vom Gesicht der Leiche herabglitt."
  },
  AvgDialog_131232_Content_28 = {
    Text = "Die „romantischen\" bezaubernden Augen behalten immer noch die Kurve des Lächelns, während die schwarze Spinne chaotisch in ihrem Körper herumkrabbelt und in den hellen Augenhöhlen nur schemenhaft zu sehen ist. Der elegante Mund hat keinen Laut mehr von sich gegeben."
  },
  AvgDialog_131232_Content_29 = {Text = "Das ist..."},
  AvgDialog_131232_Content_3 = {
    Text = "Nefraea saß weiterhin gegenüber von Arachne, sie kippte ein Glas Wein und schob es zu Arachne."
  },
  AvgDialog_131232_Content_30 = {
    Text = "Sie tötete diese geheime Puppe, hinterließ eine Imprägnierung auf ihr, verschmutzte ihr Schicksal und ließ sich kurzzeitig in ihr existieren."
  },
  AvgDialog_131232_Content_31 = {
    Text = "Arachne trat vor die Geheimeinheit, streckte die Hand zum Kopf der „Romantik\" aus und blickte auf den fast verschwundenen Faden."
  },
  AvgDialog_131232_Content_32 = {
    Text = "...Hast du etwas gesehen?"
  },
  AvgDialog_131232_Content_33 = {
    Text = "Die anderen Geheimen sind ebenfalls verschmutzt, ich kann ihre Existenz nicht im Netz des Schicksals wahrnehmen... aber das Schicksal der „Romantik\" ist mit ihnen verbunden."
  },
  AvgDialog_131232_Content_34 = {
    Text = "Sie erzählte mir, wo die „Güte\" zu finden ist."
  },
  AvgDialog_131232_Content_35 = {
    Text = "Arachne freigeben das Schicksalsfaden und ordnete die schöne Stirnfransen für „Romantik\"."
  },
  AvgDialog_131232_Content_36 = {
    Text = "Die Fähigkeiten von Nefraea stammen von mir, das Schicksal, das von ihr verschmutzt wurde, kann ich nicht sehen, viele Fähigkeiten sind ebenfalls davon betroffen."
  },
  AvgDialog_131232_Content_37 = {
    Text = "Du bist ein Fragment des Göttlichen—jemand, dessen Schicksal für uns unsichtbar ist. Deshalb brauche ich deine Hilfe, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_131232_Content_38 = {
    Text = "Sei unbesorgt, selbst nur um nach Kardas zurückzukehren, muss ich sie erledigen."
  },
  AvgDialog_131232_Content_39 = {
    Text = "Was sucht sie mit diesen geheimen Gelegenheiten?"
  },
  AvgDialog_131232_Content_4 = {
    Text = "Obwohl die „romantische\" Dame nicht mehr hier ist, sollte der Wein hier nicht verschwendet werden."
  },
  AvgDialog_131232_Content_40 = {
    Text = "Diese Geheimnisse werden die Quelle ihrer Stärke sein."
  },
  AvgDialog_131232_Content_41 = {
    Text = "Dann müssen wir uns beeilen, um loszukommen... die geheimen Einheiten finden und die Dimension Glut, die dir helfen kann, das Schicksal zu weben..."
  },
  AvgDialog_131232_Content_42 = {
    Text = "Wo ist das geheime Objekt, das „Güte\" genannt wird, jetzt?"
  },
  AvgDialog_131232_Content_43 = {
    Text = "„Romantik\" konnte ihn noch vor der Gefahr warnen, bevor sie fiel. Er versteckt sich jetzt, beschützt von einem alten Freund von dir."
  },
  AvgDialog_131232_Content_44 = {
    Text = "Alter Freund?..."
  },
  AvgDialog_131232_Content_45 = {
    Text = "Folge mir, {Male=Mr.,Female=Miss} Schutzherr. Frau Sorels großer Salon steht kurz bevor."
  },
  AvgDialog_131232_Content_5 = {
    Text = "Möchtest du es versuchen? Im Vergleich zu diesem inszenierten Geheimnis bin ich diejenige, die dich wirklich versteht."
  },
  AvgDialog_131232_Content_6 = {
    Text = "Arachne zögerte nicht, sie lächelte, hob das Weinglas und nahm einen kleinen Schluck."
  },
  AvgDialog_131232_Content_7 = {
    Text = "Du bist nicht für diesen Beruf geeignet, Nefraea. Außer Bitterkeit und Schärfe hat es keinen anderen Geschmack."
  },
  AvgDialog_131232_Content_8 = {
    Text = "Ich nenne ihn „Schicksal.\" Schmeckt er dir?"
  },
  AvgDialog_131232_Content_9 = {
    Text = "Arachne ignorierte den erwartungsvollen Blick von Nefraea. Sie trank langsam aus ihrem Becher und stellte ihn sanft auf den Tisch."
  },
  AvgDialog_132684_Content_1 = {
    Text = "<Small:<LightGray:Zirp...? (Hm...?)>>"
  },
  AvgDialog_132684_Content_10 = {
    Text = "Das stimmt, und angesichts der Tatsache, dass Misaq selbst die Tradition hat, heute Menschen zu necken, um Gefühle auszudrücken, wird die Schule diese nicht übertriebene „Streich\" nicht bestrafen."
  },
  AvgDialog_132684_Content_11 = {
    Text = "Quiek! Quiek, Quiek—!<Small:<LightGray:(Doll-Lehrer, du drückst meine Hand und mein Gesicht, richtig? Du reibst mein Gesicht, das ist richtig, oder!)>>"
  },
  AvgDialog_132684_Content_12 = {
    Text = "Obwohl der Ton wie gewohnt kühl und sogar etwas schneidend war, bist du dir ganz sicher, dass die Mundwinkel von Doll sich mindestens um 2 Millimeter nach oben gehoben haben."
  },
  AvgDialog_132684_Content_13 = {
    Text = "Es tut mir leid, Schutzherr. Der Silberkern-Übersetzer scheint ein Problem zu haben, aber das ist in Ordnung, das Gegenmittel kann morgen früh synthetisiert werden."
  },
  AvgDialog_132684_Content_14 = {
    Text = "Du schaust Doll mit entsetztem Gesicht an. Selbst wenn du jetzt nur das Gehirn eines Seeotters hättest, könntest du sehen, dass das Reagenz hinter ihr eindeutig im Zustand fertig ist."
  },
  AvgDialog_132684_Content_15 = {
    Text = "Lehrer, nach Mosk suchen?"
  },
  AvgDialog_132684_Content_16 = {
    Text = "!!!Kohleball—"
  },
  AvgDialog_132684_Content_17 = {
    Text = "Quack—<Small:<LightGray:(Chef——)>>"
  },
  AvgDialog_132684_Content_18 = {
    Text = "Da wir über erfahrene Personen in dieser Gruppe verfügen, denke ich, dass es unserem Schutzherr helfen sollte, einen Tag mit ihnen zu verbringen, um sich besser zu erinnern."
  },
  AvgDialog_132684_Content_19 = {
    Text = "Mosk, kümmere dich um die Aufgaben von %player%."
  },
  AvgDialog_132684_Content_2 = {Text = "*Springen"},
  AvgDialog_132684_Content_20 = {
    Text = "*Juhu! Kohleball, lass uns spielen"
  },
  AvgDialog_132684_Content_21 = {
    Text = "Quiek!<Small:<LightGray:(Lass uns spielen!)>>"
  },
  AvgDialog_132684_Content_22 = {
    Text = "Zisch—<Small:<LightGray:(Nein, Ramona, rette mich—)>>"
  },
  AvgDialog_132684_Content_23 = {Text = "Hust."},
  AvgDialog_132684_Content_24 = {
    Text = "Partner, heute gibt es keine wichtigen Angelegenheiten, mach dir keine Sorgen."
  },
  AvgDialog_132684_Content_25 = {
    Text = "Ich werde heute ebenfalls Zeit freimachen, um deine Sicherheit zu gewährleisten."
  },
  AvgDialog_132684_Content_26 = {
    Text = "Obwohl es so gesagt wird, ist es offensichtlich, dass sie wie Mosk auch vollständig von deinem unglaublich guten Gefühl für die weichen Haare kontrolliert wird."
  },
  AvgDialog_132684_Content_27 = {
    Text = "Zik, zikzikzikzik......<Small:<LightGray:(Gibt es noch jemanden, der helfen kann, Wilhelm, der Seniorstudent......)>>"
  },
  AvgDialog_132684_Content_28 = {
    Text = "Übrigens ist Wilhelm heute im Außendienst und wird sehr spät zurückkommen."
  },
  AvgDialog_132684_Content_29 = {
    Text = "*Teetrinken <Small:<LightGray:(Huch, eine seltene Gelegenheit, mein unbesorgtester und wichtigster Schüler, lass alles hinter dir und entspann dich einen Tag.)>>"
  },
  AvgDialog_132684_Content_3 = {
    Text = "*Gesicht reiben"
  },
  AvgDialog_132684_Content_30 = {
    Text = "Zu diesem Zeitpunkt, ein gewisser Seniorstudent in der Ferne."
  },
  AvgDialog_132684_Content_31 = {Text = "Hatschi"},
  AvgDialog_132684_Content_32 = {
    Text = "Seltsam, ich habe ein seltsames, ungutes Gefühl."
  },
  AvgDialog_132684_Content_33 = {
    Text = "Komm heute besser früher zurück zur Schule."
  },
  AvgDialog_132684_Content_34 = {
    Text = "Der Misaq des Aprilscherzes ist ebenfalls sehr friedlich."
  },
  AvgDialog_132684_Content_35 = {
    Text = "Herzlichen Glückwunsch, herzlichen Glückwunsch."
  },
  AvgDialog_132684_Content_4 = {Text = "???!!!"},
  AvgDialog_132684_Content_5 = {
    Text = "Quiek quiek quiek quiek quiek! Waaa waaa waaa waaa waaa!!!<Small:<LightGray:(Ich bin ein Otter geworden! Ramona, hilf mir!)>>"
  },
  AvgDialog_132684_Content_6 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_132684_Content_7 = {
    Text = "Gute Nachrichten, die Wirkung dieses Sprays ist nicht irreversibel, die Herstellung des Gegenmittels ist ebenfalls sehr einfach, offensichtlich hat die andere Partei keine bösen Absichten."
  },
  AvgDialog_132684_Content_8 = {
    Text = "Bessere Nachrichten, dass du es wagst, das Geschenk von diesem kleinen Lügner ohne nachzudenken zu verwenden, könnte es wirklich helfen, vorübergehend das Gehirn eines Seeotters zu haben, um etwas klarer zu werden."
  },
  AvgDialog_132684_Content_9 = {
    Text = "Also wird diese vorübergehende Umwandlung dem Schutzherrn keinen Schaden zufügen?"
  },
  AvgDialog_13733_Content_1 = {
    Text = "Zinnoberrote Zeremonie"
  },
  AvgDialog_13733_Content_10 = {
    Text = "Heh, auf die Einsicht der Lemwahsianer kannst du dich niemals verlassen. Halte deine Augen weit offen und schaue..."
  },
  AvgDialog_13733_Content_11 = {
    Text = "Prine zog ein Ritualmesser aus seinem Ärmel und schnitt sich ohne zu zögern in das eigene Handgelenk."
  },
  AvgDialog_13733_Content_12 = {
    Text = "Blutrotes Blut tropft auf den schwefelgesäumten Magiekreis, und einfach so geschieht ein Wunder—"
  },
  AvgDialog_13733_Content_13 = {
    Text = "Wie ein Tropfen Wasser in der Wüste absorbierte der Magiekreis das frische Blut und strahlte Ringe aus dunkelrotem Licht aus"
  },
  AvgDialog_13733_Content_14 = {
    Text = "Sie sind wie Flammen unter dem dunklen Himmel, die gierig den windgepeitschten Sand lecken, als würden sie die gesamte Erde verschlingen."
  },
  AvgDialog_13733_Content_15 = {
    Text = "Habt ihr das gesehen? Das ist der wahre magische Moment! Hahaha!"
  },
  AvgDialog_13733_Content_16 = {
    Text = "Hahaha...<Big:Ugh!!!>"
  },
  AvgDialog_13733_Content_17 = {
    Text = "Prine fiel „platsch“ auf die Knie und umklammerte unkontrolliert seine Kehle."
  },
  AvgDialog_13733_Content_18 = {
    Text = "Die Kette, die ihn und Uvhash verband, zog sich rasch zusammen und band ihr Fleisch und ihre Seelen aneinander"
  },
  AvgDialog_13733_Content_19 = {
    Text = "Hmm... Was...?"
  },
  AvgDialog_13733_Content_2 = {
    Text = "Rand der Kuxi-Wüste\nRitualstätte"
  },
  AvgDialog_13733_Content_20 = {
    Text = "Uvhash konnte seine entspannte Sitzhaltung nicht länger aufrechterhalten."
  },
  AvgDialog_13733_Content_21 = {
    Text = "Er wurde plötzlich von einer unsichtbaren Kraft umgeworfen und starrte fassungslos auf den außer Kontrolle geratenen Magiekreis vor ihm"
  },
  AvgDialog_13733_Content_22 = {Text = "Ugh..."},
  AvgDialog_13733_Content_23 = {
    Text = "<Big:AHHH!>"
  },
  AvgDialog_13733_Content_24 = {
    Text = "Prinn lag am Boden, starrte den sich windenden Uvhash boshaft an und begann zu lachen."
  },
  AvgDialog_13733_Content_25 = {
    Text = "Ist es schmerzhaft...? Gut, so soll es sein."
  },
  AvgDialog_13733_Content_26 = {
    Text = "In diesem Moment ist unser Bewusstsein fest miteinander verbunden..."
  },
  AvgDialog_13733_Content_27 = {
    Text = "Hast du gesehen, wie die Lemwash-Hunde meine Verwandten abgeschlachtet und meine Frau entweiht haben... hast du es gefühlt..."
  },
  AvgDialog_13733_Content_28 = {
    Text = "<Big:Antworte mir, du @1 Narr!>"
  },
  AvgDialog_13733_Content_29 = {Text = "Hehe..."},
  AvgDialog_13733_Content_3 = {
    Text = "Gut, zuerst eine Schicht Schwefel streuen, dann Kohlepulver..."
  },
  AvgDialog_13733_Content_30 = {
    Text = "Werd nicht zu aufgeregt... alter Mann."
  },
  AvgDialog_13733_Content_31 = {
    Text = "Sobald ich mich aus diesen Ketten befreit habe, wirst du der Erste sein, den ich in Stücke reiße—ugh!!"
  },
  AvgDialog_13733_Content_32 = {
    Text = "Bedauerlicherweise scheint es, dass dein Wunsch diesmal nicht in Erfüllung gehen wird..."
  },
  AvgDialog_13733_Content_33 = {
    Text = "Pulin keuchte schwer, griff zitternd nach der unsichtbaren Kette und riss dann scharf daran—"
  },
  AvgDialog_13733_Content_34 = {
    Text = "Die einst unzerstörbaren Ketten sind nun zerbrochen."
  },
  AvgDialog_13733_Content_35 = {
    Text = "Hehe@3 Ah@1 Ah!!"
  },
  AvgDialog_13733_Content_36 = {
    Text = "Pryn stieß ein schmerzerfülltes Wehklagen aus, die Haut in seinem Gesicht verfaulte und schälte sich wie Baumrinde ab und enthüllte das verschwommene Fleisch darunter."
  },
  AvgDialog_13733_Content_37 = {
    Text = "Der magische Kreis öffnet seinen gähnenden Schlund und verschlingt sein Fleisch Stück für Stück, bis von dem Magier nichts als ein leeres Skelett übrig ist."
  },
  AvgDialog_13733_Content_38 = {
    Text = "Es gibt noch mein geopfertes Fleisch, meine Seele und alles andere... Was ist mit dir..."
  },
  AvgDialog_13733_Content_39 = {
    Text = "Du wirst niemals wahre Freiheit erreichen, bevor du 10.000 Lermvahi-Hunde getötet hast!"
  },
  AvgDialog_13733_Content_4 = {
    Text = "Nein, schauen wir mal, was das Buch sagt..."
  },
  AvgDialog_13733_Content_40 = {
    Text = "Uvhash stand langsam auf."
  },
  AvgDialog_13733_Content_41 = {
    Text = "Sein Gesicht war von unsichtbaren Flammen zu schwarzer Asche verbrannt und zerfiel beim leisesten Windhauch."
  },
  AvgDialog_13733_Content_42 = {Text = "Heh..."},
  AvgDialog_13733_Content_43 = {
    Text = "„Wahre Freiheit“...? Was soll das sein?"
  },
  AvgDialog_13733_Content_44 = {
    Text = "Der versengte Krieger steht inmitten der sengenden Flammen. Seine Augen sind blutrot, und nur ein heiseres Zittern entweicht seiner Kehle."
  },
  AvgDialog_13733_Content_45 = {
    Text = "Mir, Uvhash, war immer nur eines wirklich wichtig—"
  },
  AvgDialog_13733_Content_46 = {
    Text = "Er stürmte blitzschnell hervor und riss den Magier zu Boden."
  },
  AvgDialog_13733_Content_47 = {
    Text = "Dann entblößte er seine scharfen Reißzähne und biss gnadenlos durch den Hals des Magiers."
  },
  AvgDialog_13733_Content_48 = {
    Text = "<Red:Das ist Blut!>"
  },
  AvgDialog_13733_Content_49 = {
    Text = "Herr Prinn!"
  },
  AvgDialog_13733_Content_5 = {
    Text = "Fünfzig Meter vom Schlachtfeld entfernt ist Pulin eifrig bei der Arbeit."
  },
  AvgDialog_13733_Content_50 = {
    Text = "<Shake:Dieses Leben, für dich... Rache@2 hilf mir...>"
  },
  AvgDialog_13733_Content_51 = {
    Text = "Dir helfen? Alter Mann, irrst du dich da nicht...?"
  },
  AvgDialog_13733_Content_52 = {
    Text = "Beute hat kein Recht, Forderungen an Uvhash zu stellen."
  },
  AvgDialog_13733_Content_53 = {
    Text = "Ich höre dir nicht wegen dieses verdammten Vertrags zu, sondern weil ich dein Eisenketten-Spielzeug jederzeit zertrümmern kann."
  },
  AvgDialog_13733_Content_54 = {
    Text = "Die Spielzeit ist vorbei. Jetzt will ich, dass du genau hinsiehst—"
  },
  AvgDialog_13733_Content_55 = {
    Text = "So habe ich deine Feinde, deine Verwandten und jedes Lebewesen, das du je gesehen hast, abgeschlachtet..."
  },
  AvgDialog_13733_Content_56 = {
    Text = "<Change>Teufel... du Teufel..."
  },
  AvgDialog_13733_Content_57 = {
    Text = "Prinns Blut floss frei innerhalb des Magiekreises und ließ das purpurrote Licht verblassen"
  },
  AvgDialog_13733_Content_58 = {
    Text = "Er opferte sein Leben, um Uvhash die „Freiheit“ zu gewähren."
  },
  AvgDialog_13733_Content_59 = {
    Text = "Hehe... Aah@4..."
  },
  AvgDialog_13733_Content_6 = {
    Text = "Uvhash saß auf Pulins Bitte hin in der Mitte des mit Schwefelpulver gezeichneten Magiekreises."
  },
  AvgDialog_13733_Content_60 = {
    Text = "Uvhash hob langsam den Kopf, Blut klebte noch an seinen Lippen, seine Augen waren bereits von Dunkelheit verschlungen."
  },
  AvgDialog_13733_Content_61 = {
    Text = "Er verwandelte sich in eine wahre Bestie. Oder vielmehr, dies war seine ursprüngliche Gestalt."
  },
  AvgDialog_13733_Content_62 = {
    Text = "<Red:Es ist zurück, alles ist zurückgekehrt...>"
  },
  AvgDialog_13733_Content_7 = {
    Text = "Huch... huch..."
  },
  AvgDialog_13733_Content_8 = {
    Text = "Beeindruckend, du kannst selbst in dieser Situation noch einschlafen..."
  },
  AvgDialog_13733_Content_9 = {
    Text = [[
Es gibt noch eine technische Frage an Sie, Herr Pulin.
Wird das Pulver, das Sie verstreut haben, nicht vom Wind verweht?]]
  },
  AvgDialog_13734_Content_1 = {
    Text = "Huff... Endlich eingeholt.\nIch warne dich, Uvhash. Du weißt, welche Konsequenzen es hat, ohne Erlaubnis zu verschwinden, oder?"
  },
  AvgDialog_13734_Content_10 = {
    Text = "Du hast endlich das Ende deiner Reise erreicht. Prinn stieß ein paar seltsame Lacher aus, sein Körper zitterte vor den Flammen der Rache."
  },
  AvgDialog_13734_Content_11 = {
    Text = "<Shake:Lass uns gehen, Uvhash...>"
  },
  AvgDialog_13734_Content_12 = {
    Text = "<Red:Geh und töte nach Herzenslust.>"
  },
  AvgDialog_13734_Content_2 = {Text = "Pst!!"},
  AvgDialog_13734_Content_3 = {
    Text = "Uvhash hockte auf einer hohen Düne und stieß ein ungeduldiges Zischen durch seine Nüstern aus, wie ein Raubtier, das von Insekten belästigt wird."
  },
  AvgDialog_13734_Content_4 = {
    Text = "Seine Lippen waren leicht geöffnet, seine Nüstern bebten schwach, und das blutrote Glimmen in seinen Augen wurde intensiver als je zuvor."
  },
  AvgDialog_13734_Content_5 = {
    Text = "<RedShake:Ich habe es gefunden, ich habe es gefunden...>"
  },
  AvgDialog_13734_Content_6 = {
    Text = "Du folgst seinem Blick nach unten —"
  },
  AvgDialog_13734_Content_7 = {
    Text = "Unzählige kleine schwarze Punkte sind über die welligen Dünen verstreut, wie Ameisen, die sich auf einem Sandtisch winden."
  },
  AvgDialog_13734_Content_8 = {
    Text = "Das Aufeinanderprallen von Waffen, Gebrüll und das Stampfen von Hufen erfüllen die Luft und entfalten ein gewaltiges Kriegsschauspiel vor dir."
  },
  AvgDialog_13734_Content_9 = {
    Text = "Lemwashianer, Leonianer... Gut, sehr gut."
  },
  AvgDialog_13735_Content_1 = {
    Text = "Solar Expeditio"
  },
  AvgDialog_13735_Content_10 = {
    Text = "Er war nach wie vor von unsichtbaren Ketten gebunden und saß unbeholfen auf dem Boden, fast mit der Dunkelheit verschmelzend."
  },
  AvgDialog_13735_Content_11 = {
    Text = "...Hätte nicht erwartet, dass Ihr noch wach seid."
  },
  AvgDialog_13735_Content_12 = {
    Text = "Ein <Yellow:Golem> muss nicht schlafen."
  },
  AvgDialog_13735_Content_13 = {Text = "Golem...?"},
  AvgDialog_13735_Content_14 = {
    Text = "Heh... Hör auf, so zu tun."
  },
  AvgDialog_13735_Content_15 = {
    Text = "Du kannst die Ketten an mir sehen, also musst du wissen, was ein Golem ist."
  },
  AvgDialog_13735_Content_16 = {
    Text = "Du hättest nicht erwartet, dass er deinen scheinbar beiläufigen Blick bemerkt.\nEr besitzt wahrhaftig die Instinkte eines Raubtiers."
  },
  AvgDialog_13735_Content_17 = {
    Text = "Mein Lehrer hat mir einmal gesagt..."
  },
  AvgDialog_13735_Content_18 = {
    Text = "Im antiken Rom erschuf ein wahnsinniger Alchemist den frühesten Golem — um den Preis vieler Menschenopfer."
  },
  AvgDialog_13735_Content_19 = {
    Text = "Dies ist auch die Existenz, die einem Erweckten Körper in den antiken Texten am nächsten kommt."
  },
  AvgDialog_13735_Content_2 = {
    Text = "Nördliche Kusi-Wüste, Nacht"
  },
  AvgDialog_13735_Content_20 = {
    Text = "Dieser Golem — das bist du, richtig?"
  },
  AvgDialog_13735_Content_21 = {
    Text = "Richtig... Das bin ich. Ich wurde <Blue:Caligulas> Handlanger und tötete viele für ihn."
  },
  AvgDialog_13735_Content_22 = {
    Text = "Später brauchten sie mich nicht mehr und sperrten mich an einem unterirdischen Ort ein, so dunkel, dass ich die Hand vor Augen nicht sehen konnte, bis jene Person mich befreite."
  },
  AvgDialog_13735_Content_23 = {
    Text = "Uvhash spricht, sein Blick schweift zu Prine, die noch im Zelt schnarcht."
  },
  AvgDialog_13735_Content_24 = {
    Text = "—Was ist die Bedingung?"
  },
  AvgDialog_13735_Content_25 = {
    Text = "Die Bedingung ist, ihn wie einen Hund zu dienen und viele Lemvashi-Leute auf dem Schlachtfeld zu töten."
  },
  AvgDialog_13735_Content_26 = {
    Text = "Danach gehen wir getrennte Wege und leben unser eigenes Leben."
  },
  AvgDialog_13735_Content_27 = {
    Text = "Uvhash streckte sich behaglich und räkelte sich mit gespreizten Beinen auf der Düne."
  },
  AvgDialog_13735_Content_28 = {
    Text = "Diese Ketten können dich nicht halten. Warum tötest du den Magier nicht einfach und gehst?"
  },
  AvgDialog_13735_Content_29 = {
    Text = "Weil er sagte: „Auf dem Schlachtfeld sind viele Menschen.\""
  },
  AvgDialog_13735_Content_3 = {
    Text = "Schnarch... Schnarch... Pfff..."
  },
  AvgDialog_13735_Content_30 = {
    Text = "<Red:Wo viele Menschen sind, wird es viel Blut geben.>"
  },
  AvgDialog_13735_Content_31 = {
    Text = "<RedShake:Weißt du, es ist fast tausend Jahre her, seit ich das letzte Mal dieses Blut gekostet habe...>"
  },
  AvgDialog_13735_Content_32 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_13735_Content_33 = {
    Text = "Dieser Kerl sieht nicht wie jemand aus, der seine Versprechen hält. Was, wenn er dich täuscht?"
  },
  AvgDialog_13735_Content_34 = {
    Text = "Einfach umbringen. Simpel, oder?"
  },
  AvgDialog_13735_Content_35 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_13735_Content_36 = {
    Text = "Ich muss zugeben, er hat ein überzeugendes Argument gebracht."
  },
  AvgDialog_13735_Content_37 = {
    Text = "Die Abendbrise weht sanft, die weich geschwungenen Dünen erstrecken sich endlos vor euch und hinterlassen nur zwei winzige Gestalten unter dem weiten Himmel."
  },
  AvgDialog_13735_Content_38 = {
    Text = "Du blickst hinauf zum Sternenhimmel."
  },
  AvgDialog_13735_Content_39 = {
    Text = "Um diese lange Nacht zu überbrücken, beschließt du, einige Erfahrungen mit dem Golem vor dir auszutauschen."
  },
  AvgDialog_13735_Content_4 = {
    Text = "In der stillen Nacht zeigt Prinns donnerndes Schnarchen, dass der kleine Zwischenfall am Tage seinen tiefen Schlaf nicht beeinträchtigt hat."
  },
  AvgDialog_13735_Content_40 = {
    Text = "Unter der Erde eingesperrt zu sein, muss hart sein.\nSobald du das Versprechen erfüllst, erlangst du deine Freiheit zurück. Wie fühlst du dich jetzt?"
  },
  AvgDialog_13735_Content_41 = {
    Text = "Was ist mit dir?\nDu bist schon lange von der Sklaverei befreit und wanderst durch die Wüste, um deinen Lebensunterhalt zu verdienen. Wie fühlt sich das an?"
  },
  AvgDialog_13735_Content_42 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_13735_Content_43 = {
    Text = "Überhaupt nicht gut. Kann in diesem elenden Ort nicht mal die Sonne sehen..."
  },
  AvgDialog_13735_Content_44 = {
    Text = "Du musst wirklich blind sein. Siehst du die riesige Sonne in der Wüste nicht?"
  },
  AvgDialog_13735_Content_45 = {
    Text = "Du verstehst das nicht. Ich rede von der sanften, hellen und warmen Sonne... Die wirst du in der Wüste nicht finden."
  },
  AvgDialog_13735_Content_46 = {
    Text = "Du lässt ein Gähnen los, die Müdigkeit übermannt dich allmählich.\nAls deine Wachsamkeit nachließ, wurde das Gespräch ungezwungener."
  },
  AvgDialog_13735_Content_47 = {
    Text = "Zu deiner Überraschung ist Uvhash ein ziemlich guter Zuhörer."
  },
  AvgDialog_13735_Content_48 = {
    Text = "Du wirst es vielleicht nicht glauben, aber ich habe tatsächlich eine Mission zu erfüllen..."
  },
  AvgDialog_13735_Content_49 = {
    Text = "Wenn ich all die Dinge erledigt habe, die ich tun muss, werde ich mir auf jeden Fall einen Platz suchen, um in der Sonne zu liegen und ganz, ganz viele kleine Kuchen zu essen..."
  },
  AvgDialog_13735_Content_5 = {
    Text = "Ihr haltet es nicht mehr aus und tretet schließlich aus dem Zelt."
  },
  AvgDialog_13735_Content_50 = {
    Text = "...schwer zu begreifen."
  },
  AvgDialog_13735_Content_51 = {
    Text = "Der Golem wurde aus der Dunkelheit geboren und fürchtet von Natur aus das Sonnenlicht. Fast tausend Jahre der Gefangenschaft haben seine Abneigung gegen das Licht noch verstärkt."
  },
  AvgDialog_13735_Content_52 = {
    Text = "Du tust mir wirklich leid; sich in der Sonne zu aalen ist das Schönste auf der Welt..."
  },
  AvgDialog_13735_Content_53 = {
    Text = "Es ist schade, dass selbst ein solcher Wunsch für mich schwer zu erfüllen ist..."
  },
  AvgDialog_13735_Content_54 = {
    Text = [[
Der Wind erhebt sich.
Feiner Sand schwebt empor und webt Schichten aus blassgelber Gaze, die sanft unter dem Sternenhimmel dahintreiben.]]
  },
  AvgDialog_13735_Content_55 = {
    Text = "Du hörst den reinen Wind aus der Ferne und gleitest schließlich in den Schlaf."
  },
  AvgDialog_13735_Content_56 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_13735_Content_57 = {
    Text = "Nördliche Kusi-Wüste, Tagsüber"
  },
  AvgDialog_13735_Content_58 = {
    Text = "Was zum Teufel! Hast du nicht erst vor ein paar Tagen geschworen, dass es keine Sandstürme geben würde?!"
  },
  AvgDialog_13735_Content_59 = {
    Text = "Pulin starrte wütend und zeigte auf den heranrollenden Sandsturm, der sich vom Horizont näherte."
  },
  AvgDialog_13735_Content_6 = {
    Text = "So wunderschön..."
  },
  AvgDialog_13735_Content_60 = {
    Text = "Jetzt sag mir, <Big:Was ist das@1?>"
  },
  AvgDialog_13735_Content_61 = {Text = "Uh"},
  AvgDialog_13735_Content_62 = {
    Text = "Bevor du „in den Traum eingetreten“ bist, hat der ursprüngliche Besitzer tatsächlich einige unaufrichtige Versprechen gemacht, um dieses fette Schaf auszunehmen."
  },
  AvgDialog_13735_Content_63 = {
    Text = "Jetzt ist nicht die Zeit zum Streiten; ein Sandsturm kommt. Laufen!"
  },
  AvgDialog_13735_Content_64 = {
    Text = "Nach diesen Worten sprintetest du mit voller Geschwindigkeit los und ließest Pulin weit hinter dir zurück."
  },
  AvgDialog_13735_Content_65 = {
    Text = "<Big:Hey... Bleib stehen!>"
  },
  AvgDialog_13735_Content_66 = {
    Text = "Sandsturm? Was ist das? Die Landschaft sieht schön aus."
  },
  AvgDialog_13735_Content_67 = {
    Text = "Uvhash lief beiläufig an deine Seite, den Blick unverwandt in die Ferne gerichtet."
  },
  AvgDialog_13735_Content_68 = {
    Text = "Du hast noch nie einen Sandsturm gesehen?"
  },
  AvgDialog_13735_Content_69 = {
    Text = "Uvhash zuckte mit den Schultern."
  },
  AvgDialog_13735_Content_7 = {
    Text = "Guten Abend, Herr Führer."
  },
  AvgDialog_13735_Content_70 = {
    Text = "Meine früheren Aktivitäten beschränkten sich auf die Stadt Rom, daher gibt es vieles, das ich noch nicht gesehen habe."
  },
  AvgDialog_13735_Content_71 = {
    Text = "<Shake:Uh... Ugh...>"
  },
  AvgDialog_13735_Content_72 = {
    Text = "Von den Ketten gezogen wurde Prin, der weit hinter euch allen zurücklag, in die Luft gerissen."
  },
  AvgDialog_13735_Content_73 = {
    Text = "<Shake:Langsamer... langsamer... Ich sterbe...>"
  },
  AvgDialog_13735_Content_74 = {
    Text = "Tsk. Fast hätte ich den alten Mann vergessen."
  },
  AvgDialog_13735_Content_75 = {
    Text = "Uvhash kehrte um und hob mühelos den pummeligen Körper des Zauberers hoch."
  },
  AvgDialog_13735_Content_76 = {
    Text = "Was... was hast du vor?"
  },
  AvgDialog_13735_Content_77 = {
    Text = "Nichts weiter, dir nur helfen, ein bisschen schneller zu laufen."
  },
  AvgDialog_13735_Content_78 = {
    Text = "Mit diesen Worten klemmte Uvhash den Magier mühelos unter seinen Arm, machte einen Schritt nach vorn und beugte seinen Körper wie einen Bogen."
  },
  AvgDialog_13735_Content_79 = {
    Text = "Hey... Ich warne dich, jetzt ist nicht die Zeit zum Spielen—<Big:Heulen!!!>"
  },
  AvgDialog_13735_Content_8 = {Text = "!!"},
  AvgDialog_13735_Content_80 = {
    Text = "Uvhash stieß sich kraftvoll ab und schoss wie ein Pfeil davon."
  },
  AvgDialog_13735_Content_81 = {
    Text = "Ich, du... verdammt @1, lass mich runter!"
  },
  AvgDialog_13735_Content_82 = {
    Text = "\nUvhash bricht in herzhaftes Gelächter aus.\nDer Klang reitet auf dem Wind, vermischt sich mit goldenem Sand und Staub und eilt fröhlich dem Horizont entgegen."
  },
  AvgDialog_13735_Content_83 = {
    Text = "Das geht nicht. Ich brauche dich noch lebendig, damit du mir hilfst, meine Freiheit zurückzuerlangen!"
  },
  AvgDialog_13735_Content_9 = {
    Text = "Uvhash tauchte plötzlich aus der Ecke auf und grinste euch an."
  },
  AvgDialog_13736_Content_1 = {
    Text = "Führer, Zauberer und Sklave"
  },
  AvgDialog_13736_Content_10 = {
    Text = "Verkohlt und trocken, mit rauen und wilden Handlinien — dies sind die Hände eines Kriegers."
  },
  AvgDialog_13736_Content_100 = {
    Text = "Entschuldigung, ich habe nichts, was ich dir sagen kann."
  },
  AvgDialog_13736_Content_101 = {
    Text = "Söldner sind ein Haufen treuloser Gestalten. Und Sklaven können unmöglich Würde und Ehre begreifen."
  },
  AvgDialog_13736_Content_102 = {
    Text = "Zwischen euch und diesem Kerl gibt es keinen grundlegenden Unterschied."
  },
  AvgDialog_13736_Content_103 = {
    Text = "Aber ich bin längst über das Alter der Impulsivität hinaus."
  },
  AvgDialog_13736_Content_104 = {
    Text = "Erstens kann ich euch nicht besiegen.\nZweitens seid ihr mir noch einigermaßen von Nutzen."
  },
  AvgDialog_13736_Content_105 = {
    Text = "Egal, woher ihr kommt — in diesem Augenblick führt weiterhin das Team, mein Führer."
  },
  AvgDialog_13736_Content_11 = {
    Text = "<Gray:Jamila, 32 Jahre alt, ehemalige Mamulu-Söldnerin, jetzt Wüstenführerin...>"
  },
  AvgDialog_13736_Content_12 = {
    Text = "Ihr verarbeitet still Eure neue Identität."
  },
  AvgDialog_13736_Content_13 = {
    Text = "Sieht so aus, als wärst du wieder „in einen Traum eingetreten“."
  },
  AvgDialog_13736_Content_14 = {
    Text = "Hey, was murmelst du da? Wenn du wach bist, dann steh schnell auf. Mein <Blue:Sklave> und ich haben dringende Angelegenheiten zu erledigen."
  },
  AvgDialog_13736_Content_15 = {
    Text = "Der kleine, stämmige Mann in eigentümlicher Kleidung ist dein Auftraggeber für diesen Job, <Blue:Ludwig Prin>."
  },
  AvgDialog_13736_Content_16 = {
    Text = "Er deutete ungeduldig mit einer Peitsche hinter sich."
  },
  AvgDialog_13736_Content_17 = {Text = "Zisch..."},
  AvgDialog_13736_Content_18 = {
    Text = "Uvhash—?!"
  },
  AvgDialog_13736_Content_19 = {
    Text = "Dann bemerktest du den Mann, der hinter den Sanddünen verborgen war."
  },
  AvgDialog_13736_Content_2 = {
    Text = "@Im Jahr 2 verlor der Papst seine Macht, und die Monarchie erhob sich.\nDie heilige Stadt Akkon wurde zu einem umkämpften Land.\n\nAus Furcht vor den Mamluken-Truppen unter Baibars\nrief der Fürst alle dazu auf, sich dem Kreuzzug anzuschließen und die heilige Stadt Akkon zurückzuerobern."
  },
  AvgDialog_13736_Content_20 = {
    Text = "Er hielt eine kauernde Haltung ein, seine langen Arme lagen lässig auf dem Boden, wie ein Raubtier, bereit zum Sprung."
  },
  AvgDialog_13736_Content_21 = {
    Text = "Als er deinen schockierten Ausdruck sah, grinste er und entblößte eine Reihe scharfer, weißer Zähne."
  },
  AvgDialog_13736_Content_22 = {
    Text = "Was? Kennst du mich?"
  },
  AvgDialog_13736_Content_24 = {
    Text = "Bevor du ein Wort sagen konntest, schlug der Zauberer heftig mit der langen Peitsche in seiner Hand auf Youwu ein."
  },
  AvgDialog_13736_Content_25 = {
    Text = "Kumpel, ich rate dir, nicht mit ihm zu reden."
  },
  AvgDialog_13736_Content_26 = {
    Text = "Lass dich nicht von seinen menschenähnlichen Augen und seiner Nase täuschen; er ist immer noch eine unzivilisierte Bestie, oder vielleicht..."
  },
  AvgDialog_13736_Content_28 = {
    Text = "Eine weitere lange Peitsche schlug heftig auf Youwu ein."
  },
  AvgDialog_13736_Content_29 = {
    Text = "Er ist ein <Red:demon>."
  },
  AvgDialog_13736_Content_3 = {
    Text = "An diesem Punkt beginnt die große <Yellow:Ostexpedition> erneut..."
  },
  AvgDialog_13736_Content_30 = {
    Text = "Obwohl er mehrfach geschlagen wurde, zuckte Uvhash nicht einmal mit der Wimper."
  },
  AvgDialog_13736_Content_31 = {
    Text = "Er wischte das Blut ab, das von seiner Schläfe floss, roch an seiner Hand und leckte dann langsam das Blut von seiner Fingerspitze."
  },
  AvgDialog_13736_Content_32 = {
    Text = "Schau, siehst du das? Sogar mein Wachhund ist vernünftiger als er! Er ist schlimmer als ein Tier, hahaha!"
  },
  AvgDialog_13736_Content_33 = {
    Text = "Hey... Alter, deine Kraft ist heute schwächer.\nWas, kannst du die Peitsche nicht mal mehr ruhig halten?"
  },
  AvgDialog_13736_Content_34 = {Text = "Hmph..."},
  AvgDialog_13736_Content_35 = {
    Text = "Bestien sind Bestien, weil sie ihre Klappe nicht halten und ihren Platz nicht erkennen können."
  },
  AvgDialog_13736_Content_36 = {
    Text = "Keine Sorge, ich werde es dir <BigItalic:schon beibringen>—"
  },
  AvgDialog_13736_Content_37 = {
    Text = "Prinns Bart sträubte sich vor Wut, und dann schoss er wie ein Gummiball auf Uvhash zu."
  },
  AvgDialog_13736_Content_38 = {Text = "Warte."},
  AvgDialog_13736_Content_39 = {
    Text = "Du packtest Prin am Handgelenk und zogst ihn zurück."
  },
  AvgDialog_13736_Content_4 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_13736_Content_40 = {
    Text = "Gib mir die Peitsche."
  },
  AvgDialog_13736_Content_41 = {
    Text = "Lass mich los! Lass mich diesem Biest eine Lektion erteilen..."
  },
  AvgDialog_13736_Content_42 = {
    Text = "Herr Jamila, ich bin jetzt Ihr Arbeitgeber. Es ist wohl nicht nötig zu erklären, was ein Arbeitgeber ist, oder?"
  },
  AvgDialog_13736_Content_43 = {
    Text = "Tut mir leid, ich weiß nur, dass ich der Führer für diese Reise bin.\nDa ich der Führer bin, müssen Sie auf mich hören."
  },
  AvgDialog_13736_Content_44 = {
    Text = "Andernfalls gehe ich jetzt, und Sie können allein zum <Blue:Schlachtfeld> aufbrechen."
  },
  AvgDialog_13736_Content_45 = {
    Text = "<Shake:Hey, hey...! Lassen Sie uns in Ruhe darüber reden...>"
  },
  AvgDialog_13736_Content_46 = {
    Text = "Eine Sache mehr."
  },
  AvgDialog_13736_Content_47 = {
    Text = "Stirnrunzelnd blickst du Uvhash an."
  },
  AvgDialog_13736_Content_48 = {
    Text = "Du und er seid euch auf dem Campus selten über den Weg gelaufen, aber du wusstest ein wenig über seine verschiedenen Eskapaden."
  },
  AvgDialog_13736_Content_49 = {
    Text = "Er ist definitiv nicht der Typ, der sich von anderen kontrollieren lässt."
  },
  AvgDialog_13736_Content_5 = {
    Text = "Ihr erwacht aus tiefem Schlummer und findet Euch in einer weiten, endlosen Wüste wieder."
  },
  AvgDialog_13736_Content_50 = {
    Text = "Was hast du mit diesem Kerl gemacht? Wie kann er dir nur gehorchen?"
  },
  AvgDialog_13736_Content_51 = {
    Text = "Was? Zweifeln Sie etwa an meinen Fähigkeiten als <Blue:Oberster Magier von Levante>?"
  },
  AvgDialog_13736_Content_52 = {
    Text = "Das ist eine exklusive Geheimtechnik in unserem Gewerbe sowie meine persönliche Privatsache als Arbeitgeber. Bitte, Führer, kümmern Sie sich um Ihre eigenen Angelegenheiten..."
  },
  AvgDialog_13736_Content_53 = {
    Text = "Willst du nicht reden, hm?\nDann prügle ich es aus dir heraus."
  },
  AvgDialog_13736_Content_54 = {
    Text = "Hey, warte... <Big:Roar!>"
  },
  AvgDialog_13736_Content_56 = {
    Text = "<Shake:Zisch, das tut weh... Du bist definitiv kein gewöhnlicher Führer!>"
  },
  AvgDialog_13736_Content_57 = {
    Text = "Sprich, bist du ein Spion, der von <Blue:Remvashi> geschickt wurde, um mich abzufangen?"
  },
  AvgDialog_13736_Content_58 = {
    Text = "Du antwortest nicht auf Pulins Frage, denn deine Aufmerksamkeit wurde bereits woandershin gelenkt—"
  },
  AvgDialog_13736_Content_59 = {
    Text = "Eine schlanke Kette schimmert schwach im Tageslicht und gibt einen ungewöhnlichen Glanz von sich."
  },
  AvgDialog_13736_Content_6 = {
    Text = "Wach? Unglaublich, der Führer ist nach nur wenigen Schritten vor Hitzschlag umgekippt. Was für ein Desaster!"
  },
  AvgDialog_13736_Content_60 = {
    Text = "Sie erstreckt sich von Prins Handgelenk bis hin zu Uvhashs Hals."
  },
  AvgDialog_13736_Content_61 = {
    Text = "<Gray:Diese Technik kommt mir bekannt vor... Ich glaube, ich erinnere mich, dass jemand sie einmal erwähnt hat...>"
  },
  AvgDialog_13736_Content_62 = {
    Text = "Ungehorsame sollte man einfach an die Leine legen."
  },
  AvgDialog_13736_Content_63 = {
    Text = "Das ist in Lentiniën illegal, Fräulein Agrippa. Ich fürchte, wir müssen Euch einige grundlegende Rechtskenntnisse beibringen..."
  },
  AvgDialog_13736_Content_64 = {
    Text = "Hehe, ich bin kein Narr."
  },
  AvgDialog_13736_Content_65 = {
    Text = "Kennst du @1?"
  },
  AvgDialog_13736_Content_66 = {
    Text = "Das ist eine uralte arkane Kunst, die es dem Wirkenden erlaubt, andere mit einer unsichtbaren Kette zu kontrollieren..."
  },
  AvgDialog_13736_Content_67 = {
    Text = "Was den Preis angeht..."
  },
  AvgDialog_13736_Content_68 = {
    Text = "Was war der Preis? Oh nein, ich erinnere mich nicht..."
  },
  AvgDialog_13736_Content_69 = {
    Text = "Du bist in Erinnerungen versunken, als plötzlich die Maske, die dein Gesicht umhüllt, heruntergerissen wird."
  },
  AvgDialog_13736_Content_7 = {
    Text = "Gut, dass ich dieses Höllenloch nur einmal in meinem Leben besuche, @1!"
  },
  AvgDialog_13736_Content_70 = {
    Text = "Drei gewundene Flüsse... Bist du <Blue:Mamlios Sklavensöldner>?!"
  },
  AvgDialog_13736_Content_71 = {
    Text = "Als Prinn zu Ende gesprochen hatte, wandte sich Uvhash, der bisher gleichgültig gewirkt hatte, plötzlich um und sah dich an."
  },
  AvgDialog_13736_Content_72 = {
    Text = "Interessant..."
  },
  AvgDialog_13736_Content_73 = {
    Text = "Nein, nein, das stimmt nicht. Mamulus Leute sollten jetzt auf dem Schlachtfeld sein..."
  },
  AvgDialog_13736_Content_74 = {
    Text = "Verstehe, du bist ein Deserteur."
  },
  AvgDialog_13736_Content_75 = {
    Text = "Du hast instinktiv dein Gesicht berührt."
  },
  AvgDialog_13736_Content_76 = {
    Text = "<Gray:Also, da ist eine Tätowierung in meinem Gesicht...>"
  },
  AvgDialog_13736_Content_77 = {
    Text = "Klar, ich bin ein Deserteur. Meine Heimat ist <Blue:Lemwashi>, aber ich möchte nicht zurückkehren..."
  },
  AvgDialog_13736_Content_78 = {
    Text = "Deserteure müssen auch essen, also verdiene ich mir meinen Lebensunterhalt jetzt als Führer.\nKeine Sorge, meine größte Stärke ist meine akribische Herangehensweise an die Arbeit."
  },
  AvgDialog_13736_Content_79 = {
    Text = "Ich sorge dafür, euch sicher zum Schlachtfeld zu bringen—"
  },
  AvgDialog_13736_Content_8 = {
    Text = "Führer? Das... wo ist dieser Ort..."
  },
  AvgDialog_13736_Content_80 = {Text = "Pfft."},
  AvgDialog_13736_Content_81 = {
    Text = "Nachdem er genug von der Farce vor sich hat, streckt sich Uvhash und schlendert gemächlich zu dir."
  },
  AvgDialog_13736_Content_82 = {
    Text = "Er packt deine Schulter und dreht sanft dein Kinn, bis dein Blick dem schweigenden Magier vor dir begegnet."
  },
  AvgDialog_13736_Content_83 = {
    Text = "In Anbetracht dessen, dass wir Sklaven sind oder einmal waren, gebe ich dir einen Hinweis—"
  },
  AvgDialog_13736_Content_84 = {
    Text = "Wenn ich du wäre, würde ich jetzt die Klappe halten.\nWeißt du, welche Art von Menschen dieser Kerl am meisten hasst?"
  },
  AvgDialog_13736_Content_85 = {
    Text = "...Das Gefühl, von diesem Kerl zur Vorsicht ermahnt zu werden, ist wirklich eigenartig."
  },
  AvgDialog_13736_Content_86 = {
    Text = "...Ich würde gerne mehr hören."
  },
  AvgDialog_13736_Content_87 = {
    Text = "Drittens, die Mamuliu-Söldner."
  },
  AvgDialog_13736_Content_88 = {
    Text = [[
Zweitens, die Lemwashians.
Was den ersten betrifft...]]
  },
  AvgDialog_13736_Content_89 = {
    Text = "Heftiger Schmerz durchzuckt deine Schulter — Uvhash lacht, während er dir kräftig auf die Schulter schlägt."
  },
  AvgDialog_13736_Content_9 = {
    Text = "Die sengende Sonne macht Euch schwindelig, als Ihr auf Eure Hände hinabblickt."
  },
  AvgDialog_13736_Content_90 = {
    Text = "<Big:Natürlich sind es die Mamulu-Söldner aus Lemwash!>"
  },
  AvgDialog_13736_Content_91 = {
    Text = "<Gray:...Gut. Niemand sonst sollte hier laut lachen können außer ihm.>"
  },
  AvgDialog_13736_Content_92 = {
    Text = "<Gray:Das Talent dieses Kerls, Leute vor den Kopf zu stoßen, ist wirklich unübertroffen.>"
  },
  AvgDialog_13736_Content_93 = {Text = "Heh..."},
  AvgDialog_13736_Content_94 = {
    Text = "Als die Mamlu-Söldner Zehntausende meiner Landsleute abschlachteten, kamen meine Frau, meine Kameraden und mein Mentor... alle ums Leben."
  },
  AvgDialog_13736_Content_95 = {
    Text = "In Ordnung, ich habe meine tragische Geschichte zu Ende erzählt. Ihr könnt jetzt weiterlachen."
  },
  AvgDialog_13736_Content_96 = {
    Text = "Verzeihung, Herr Prinn. Erlauben Sie mir, es zu erklären. Obwohl ich eine... nun ja, nicht gerade ehrenvolle Vergangenheit habe."
  },
  AvgDialog_13736_Content_97 = {
    Text = "Aber das ist alles Vergangenheit und hat nichts mehr mit mir zu tun."
  },
  AvgDialog_13736_Content_98 = {
    Text = "Prynne winkte euch zu."
  },
  AvgDialog_13736_Content_99 = {
    Text = "Sein rundes Gesicht, von der sengenden Sonne gebrannt, glich einem vollreifen Apfel — leider war dieser Apfel gerade nicht besonders gut gelaunt."
  },
  AvgDialog_13737_Content_1 = {
    Text = "Der Vorhang der Tragödie"
  },
  AvgDialog_13737_Content_10 = {
    Text = "<RedShake:Geh...>"
  },
  AvgDialog_13737_Content_11 = {
    Text = "Uvhash zerquetschte mühelos das Gehirn des Blockers und näherte sich dann langsam einem weiteren Soldaten."
  },
  AvgDialog_13737_Content_12 = {
    Text = "<RedShake:Blut... Ich brauche mehr Blut...>"
  },
  AvgDialog_13737_Content_13 = {
    Text = "Er hob langsam seine Hand."
  },
  AvgDialog_13737_Content_15 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_13737_Content_16 = {
    Text = "Es bist du..."
  },
  AvgDialog_13737_Content_17 = {
    Text = "Ja, ich bin es."
  },
  AvgDialog_13737_Content_18 = {
    Text = "Du stellst dich zwischen die beiden und drehst dich zu dem Soldaten um, der voller Angst hinter dir kniet."
  },
  AvgDialog_13737_Content_19 = {
    Text = "Beeil dich. Lauf so weit du kannst."
  },
  AvgDialog_13737_Content_2 = {
    Text = "Rand der Kuxi-Wüste, Schlachtfeld"
  },
  AvgDialog_13737_Content_20 = {
    Text = "<Big:Verschwinde!!>"
  },
  AvgDialog_13737_Content_21 = {
    Text = "<Shake:Schon gut, schon gut... Ich bin weg...>"
  },
  AvgDialog_13737_Content_22 = {
    Text = "Die Soldaten flohen in Panik."
  },
  AvgDialog_13737_Content_23 = {
    Text = "Warum hältst du mich auf? Ich habe gerade erst begonnen, den Rausch von Blut und Kampf zu genießen..."
  },
  AvgDialog_13737_Content_24 = {
    Text = "Du willst doch nur kämpfen, oder? Ich spiele mit."
  },
  AvgDialog_13737_Content_25 = {
    Text = "Du? Hahaha, was bist du denn—"
  },
  AvgDialog_13737_Content_27 = {
    Text = "Du drückst den Krummsäbel an Uvhashs Hals und blickst ruhig in seine glasigen Augen."
  },
  AvgDialog_13737_Content_28 = {
    Text = "Das wirst du erst wissen, wenn du es versuchst."
  },
  AvgDialog_13737_Content_3 = {
    Text = "Hey, hast du gehört? Wieder einer ist wahnsinnig geworden und tötet jeden in Sichtweite."
  },
  AvgDialog_13737_Content_4 = {
    Text = "Sie sagen, er sei weder Leorian noch Lemwashian... niemand weiß, woher er kommt."
  },
  AvgDialog_13737_Content_5 = {
    Text = "Jedenfalls, schnell weg hier—"
  },
  AvgDialog_13737_Content_6 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_13737_Content_7 = {
    Text = "<Shake:Wann bist du... aufgetaucht...?>"
  },
  AvgDialog_13737_Content_8 = {
    Text = "Ahhh! Beeile dich—"
  },
  AvgDialog_13737_Content_9 = {Text = "—!!"},
  AvgDialog_13738_Content_1 = {
    Text = "Gut, der Sandsturm hat sich auf die andere Seite verlagert. Als Nächstes..."
  },
  AvgDialog_13738_Content_10 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_13738_Content_11 = {
    Text = "Du willst doch zum Schlachtfeld? Dann solltest du natürlich in die <Red:Richtung des Blutes> gehen."
  },
  AvgDialog_13738_Content_12 = {
    Text = "Die Richtung des Blutes...?"
  },
  AvgDialog_13738_Content_13 = {
    Text = "Du zeigst auf Uvhashs sich entfernenden Rücken."
  },
  AvgDialog_13738_Content_14 = {
    Text = "Seine Richtung."
  },
  AvgDialog_13738_Content_2 = {Text = "Ugh—!!"},
  AvgDialog_13738_Content_3 = {
    Text = "Pulin lehnte sich gegen den kahlen Baumstamm und begann heftig zu erbrechen."
  },
  AvgDialog_13738_Content_4 = {
    Text = "Ich schwöre, sobald dieses Geschäft abgeschlossen ist. Ich schwöre..."
  },
  AvgDialog_13738_Content_5 = {
    Text = "Diesmal erhielt der Schwächefluch des Magiers keine Antwort."
  },
  AvgDialog_13738_Content_6 = {
    Text = "Uvhashs Pupillen zogen sich plötzlich leicht zusammen, als hätte er etwas entdeckt."
  },
  AvgDialog_13738_Content_7 = {
    Text = "<Red:...Blut.>"
  },
  AvgDialog_13738_Content_8 = {
    Text = "Nachdem er das gesagt hatte, ging er davon, ohne sich umzudrehen."
  },
  AvgDialog_13738_Content_9 = {
    Text = "Warte...! Du kannst ohne meine Erlaubnis nirgendwohin gehen!"
  },
  AvgDialog_13739_Content_1 = {
    Text = "Der Geier schreit laut in der blutroten Dämmerung; das Schlachtfeld ist bereits verlassen."
  },
  AvgDialog_13739_Content_10 = {
    Text = "Während des Kampfes spürst du deutlich, wie sich Uvhashs Zustand in alarmierendem Tempo verschlechtert."
  },
  AvgDialog_13739_Content_11 = {
    Text = "Was auch immer es ist, sei es eine Nebenwirkung des Vertrags, er ist jetzt an seinem Limit."
  },
  AvgDialog_13739_Content_12 = {
    Text = "Ein Kampf ist nur interessant, wenn er ausgeglichen ist, also macht es mir nichts aus, bis zu einem gewissen Grad schwächer zu werden."
  },
  AvgDialog_13739_Content_13 = {
    Text = "Ich kümmere mich nie um menschliche Gedanken, so wie sich Menschen nicht um Ameisen kümmern."
  },
  AvgDialog_13739_Content_14 = {
    Text = "Aber du bist anders. Du besitzt eine mächtige innere Stärke, und du verstehst Zurückhaltung."
  },
  AvgDialog_13739_Content_15 = {
    Text = "Mach weiter so, Krieger. Deine alltäglichen Wünsche — wie die Sonne, kleine Kuchen und dergleichen — könnten tatsächlich in Erfüllung gehen."
  },
  AvgDialog_13739_Content_16 = {
    Text = "<Gray:Das war nur irgendein Unsinn, den ich dahergesagt habe, und er hat sich tatsächlich daran erinnert...>"
  },
  AvgDialog_13739_Content_17 = {
    Text = "Lass uns gehen... zu dem Ort, den du erwähnt hast, wo die Sonne scheint."
  },
  AvgDialog_13739_Content_18 = {Text = "?!"},
  AvgDialog_13739_Content_19 = {
    Text = "Und was ist mit dir?"
  },
  AvgDialog_13739_Content_2 = {
    Text = "Du und Uvhash standet schweigend keine zehn Meter voneinander entfernt und saht euch an."
  },
  AvgDialog_13739_Content_20 = {
    Text = "Mich...? Der Alte hat sich zurückgehalten. Ich werde nicht mehr lange durchhalten. Heh..."
  },
  AvgDialog_13739_Content_21 = {
    Text = "Sowohl der Alte als auch ich müssen sterben... Das ist der wahre Preis für den Bruch des Vertrags."
  },
  AvgDialog_13739_Content_22 = {
    Text = "Er stapft langsam auf dich zu."
  },
  AvgDialog_13739_Content_23 = {
    Text = "Dann biss er sich in sein eigenes Handgelenk."
  },
  AvgDialog_13739_Content_24 = {
    Text = "Das beißende, scharlachrote Blut ergießt sich in Strömen, tropft auf deinen Kopf, deine Augenlider und fließt über deinen Nasenrücken zu deinen ausgedörrten Lippen."
  },
  AvgDialog_13739_Content_25 = {
    Text = "Dieses Blut... betrachte es als mein Abschiedsgeschenk."
  },
  AvgDialog_13739_Content_26 = {
    Text = "Geier kreisten über ihm und hatten offensichtlich ihre sterbende Beute im Visier."
  },
  AvgDialog_13739_Content_27 = {
    Text = "Ich wurde aus unzähligem Fleisch geboren und wandere seit fast tausend Jahren durch diese Welt..."
  },
  AvgDialog_13739_Content_28 = {
    Text = "Es gibt noch Goldfolie, die bei Siegesparaden flatterte, und goldene Paläste, die heftig in Flammen brannten."
  },
  AvgDialog_13739_Content_29 = {
    Text = "Ich habe das köstlichste Blut gekostet und die brutalsten Schlachten erlebt."
  },
  AvgDialog_13739_Content_3 = {
    Text = "Hey... wie lange kämpfen wir schon?"
  },
  AvgDialog_13739_Content_30 = {
    Text = "Ich schlachtete Menschen, wurde von ihnen gebunden und benutzt, und starb letztlich durch ihre Hand – wenig überraschend."
  },
  AvgDialog_13739_Content_31 = {
    Text = "Nun ist es an der Zeit für mich zu gehen..."
  },
  AvgDialog_13739_Content_32 = {
    Text = "Er blickt auf dich herab, seine Augen bar jeder Emotion."
  },
  AvgDialog_13739_Content_33 = {
    Text = "Dickes Blut tropft von deiner Nasenspitze zu Boden."
  },
  AvgDialog_13739_Content_34 = {
    Text = "Du bist wie ein verwirrter Neuling, ahnungslos über alles, was sich vor dir entfaltet."
  },
  AvgDialog_13739_Content_35 = {
    Text = "Ich gebe all mein Fleisch an dich zurück, und an diese Welt."
  },
  AvgDialog_13739_Content_36 = {
    Text = "Es gehört dem Himmel, der Erde... dir, aber nicht mir."
  },
  AvgDialog_13739_Content_37 = {
    Text = "Jetzt kannst du verschwinden... Sieh dich nicht um."
  },
  AvgDialog_13739_Content_38 = {
    Text = "Die Sicht wird schließlich von einem gewaltigen Meer aus Blutnebel verschlungen. \nDu schließt die Augen und spürst Wellen von Schwindel, als würde der Boden unaufhörlich absinken."
  },
  AvgDialog_13739_Content_39 = {
    Text = "An den Rest der Geschichte kannst du dich nicht mehr recht erinnern."
  },
  AvgDialog_13739_Content_4 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_13739_Content_40 = {
    Text = "Vielleicht bist du schon lange fort, oder vielleicht bist du mit ihm in dieser Wüste gestorben."
  },
  AvgDialog_13739_Content_41 = {
    Text = "Das spielt keine Rolle. Denn du wirst dich für immer an den Moment vor seinem Tod erinnern."
  },
  AvgDialog_13739_Content_42 = {
    Text = "In jenem Moment flog ein Schwarm schwarzer Geier vorbei und verdeckte das Leuchten des Sonnenuntergangs hinter ihm."
  },
  AvgDialog_13739_Content_43 = {
    Text = "Das Licht schwindet weiter, Schatten breiten sich aus, und er kniet inmitten von ihnen und blickt dich an."
  },
  AvgDialog_13739_Content_44 = {
    Text = "Er sagte—"
  },
  AvgDialog_13739_Content_45 = {
    Text = "Verschwinde."
  },
  AvgDialog_13739_Content_46 = {
    Text = "Geh und finde dieses sonnenverbrannte Höllenloch."
  },
  AvgDialog_13739_Content_5 = {
    Text = "Wer weiß... eine Stunde, einen Tag?"
  },
  AvgDialog_13739_Content_6 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_13739_Content_7 = {
    Text = "Tausend Jahre... Ich habe seit fast einem Jahrtausend keinen so berauschenden Kampf mehr erlebt."
  },
  AvgDialog_13739_Content_8 = {
    Text = "Du bist ein geborener Krieger."
  },
  AvgDialog_13739_Content_9 = {
    Text = "Überraschend, seit wann hast du gelernt, Menschen Komplimente zu machen?"
  },
  AvgDialog_138765_Content_1 = {
    Text = "Die Glut der Dimensionen ist im Fluss. Das Schicksalsrad Moirae dreht sich bereits hier."
  },
  AvgDialog_138765_Content_2 = {
    Text = "Wagt alles, Hüter des Geheimnisses{Male=先生,Female=小姐}. Ich werde Euch dabei unterstützen, das falsche Schicksal zu korrigieren und jene Kokons zu zerstören, die nicht existieren sollten."
  },
  AvgDialog_138765_Content_3 = {
    Text = "Der Lauf des Schicksals wurde noch nie von anderen gewoben."
  },
  AvgDialog_138766_Content_1 = {
    Text = "Ist es... ist es vorbei?"
  },
  AvgDialog_138766_Content_2 = {
    Text = "Seid vorsichtig, Schutzherr... die Spindel, die das Schicksal entwebt, hat bereits begonnen, sich hinter ihr zu drehen..."
  },
  AvgDialog_138766_Content_3 = {
    Text = "Heh... hahahaha...!"
  },
  AvgDialog_138766_Content_4 = {
    Text = "„Seht her, ihr blinden Gläubigen des Schicksals! Die Glocke, die stets für euch bestimmt war, hat endlich geschlagen!\""
  },
  AvgDialog_138766_Content_5 = {
    Text = "„Ich bin das Ende — ich bin das Schicksal — ich bin @4!\""
  },
  AvgDialog_138766_Content_6 = {
    Text = "„Nun schenke ich euch das ultimative Ende. Ich gewähre euch die Befreiung, nach der ihr so verzweifelt verlangt habt!!\""
  },
  AvgDialog_13946_Content_1 = {
    Text = "Entfesseltes Meer"
  },
  AvgDialog_13946_Content_10 = {
    Text = "Sie haben dich geschickt, um mich zur Hexe zu „eskortieren“?\nDas ist lächerlich. Ihre Absichten könnten nicht offensichtlicher sein..."
  },
  AvgDialog_13946_Content_11 = {
    Text = "Goliath stößt ein schmerzerfülltes Keuchen aus. Unter ihm breitet sich langsam eine Lache dunkelroten Blutes aus, die bis zu deinen Füßen fließt."
  },
  AvgDialog_13946_Content_12 = {
    Text = "<Red:Sie wollen, dass wir gemeinsam auf See sterben.>"
  },
  AvgDialog_13946_Content_13 = {
    Text = "Meister, Ihr seid schwer verletzt! Was ist geschehen...?"
  },
  AvgDialog_13946_Content_14 = {
    Text = "Chaotische Erinnerungen fluten in deinen Verstand."
  },
  AvgDialog_13946_Content_15 = {
    Text = "In der letzten entscheidenden Schlacht verlor Anführer Goliath gegen den rivalisierenden Stamm, weil er ihn unterschätzt hatte."
  },
  AvgDialog_13946_Content_16 = {
    Text = "Perishiten akzeptieren kein Versagen. Der schwer verletzte Goliath wurde verbannt, begleitet nur von einem kaputten kleinen Boot und dir —"
  },
  AvgDialog_13946_Content_17 = {
    Text = "Der schwächste Perishit könnte sogar ein Ringkampf gegen einen Zehnjährigen verlieren."
  },
  AvgDialog_13946_Content_18 = {
    Text = "Ich erinnere mich, dass der Anführer <Blue:Glen> eine geheimnisvolle Hexe in den nahen Gewässern erwähnt hat, die eine Art schwarzen Schleim benutzt..."
  },
  AvgDialog_13946_Content_19 = {
    Text = "Einfach auf die Wunde auftragen, und die Verletzung wird sicher heilen!"
  },
  AvgDialog_13946_Content_2 = {
    Text = "Klage um den Apostel der See.\nKlage um unser Licht, unsere Hoffnung.\n\nWir wehklagen, weinen und vergießen Tränen über unser Schicksal, ins Meer verbannt zu sein."
  },
  AvgDialog_13946_Content_20 = {
    Text = "Du hast reflexartig die Legende der Hexe erwähnt, nur um danach zu bemerken, dass sich etwas seltsam anfühlte."
  },
  AvgDialog_13946_Content_21 = {
    Text = "<Gray:Warte, ist das D-Schleim...?>"
  },
  AvgDialog_13946_Content_22 = {
    Text = "Anführer, ist es Glen?"
  },
  AvgDialog_13946_Content_23 = {
    Text = "Ein langsames Lächeln breitete sich auf Goliaths kaltem Gesicht aus."
  },
  AvgDialog_13946_Content_24 = {
    Text = "Sieht so aus, als wäre er euer neuer Anführer geworden. Sehr effizient, meine lieben Stammesgenossen."
  },
  AvgDialog_13946_Content_25 = {
    Text = "Platschen!!"
  },
  AvgDialog_13946_Content_26 = {
    Text = "Das morsche Boot konnte dem Aufprall der Wellen nicht mehr standhalten, ein großes Loch brach auf, durch das ununterbrochen Meerwasser hereinströmte."
  },
  AvgDialog_13946_Content_27 = {
    Text = "Tsk, genau wie ich es erwartet habe."
  },
  AvgDialog_13946_Content_28 = {
    Text = "Oh nein, wir werden ertrinken! Wir müssen etwas finden, um das Loch zu stopfen..."
  },
  AvgDialog_13946_Content_29 = {Text = "...Oh."},
  AvgDialog_13946_Content_3 = {
    Text = "Oh, bitte beschütze die Geplagten!\nRichte deinen barmherzigen Blick auf uns und gewähre uns den schwarzen Quell des Lebens."
  },
  AvgDialog_13946_Content_30 = {
    Text = "Goliath lehnte sich desinteressiert gegen das Deck und ließ das Blut unter ihm das hereinströmende Meerwasser rot färben."
  },
  AvgDialog_13946_Content_31 = {
    Text = "Freigeben. Selbst wenn wir das Schiff reparieren, haben sie immer noch zehntausend Wege, mich in diesem Meer zu töten."
  },
  AvgDialog_13946_Content_32 = {
    Text = "Mein Rat: Lass mich in Ruhe. Steig vom Boot und schwimm allein zurück."
  },
  AvgDialog_13946_Content_33 = {
    Text = "Sag ihnen, du hättest mich getötet. Mit etwas Glück könntest du überleben."
  },
  AvgDialog_13946_Content_34 = {
    Text = "Was ist mit dir...?"
  },
  AvgDialog_13946_Content_35 = {Text = "Ich?"},
  AvgDialog_13946_Content_36 = {
    Text = "Goliath genießt gemächlich den Blick aufs Meer und schenkt dir ein leichtes Lächeln."
  },
  AvgDialog_13946_Content_37 = {
    Text = "Hier sitzen und das Meer bewundern, während ich auf den Tod warte."
  },
  AvgDialog_13946_Content_38 = {Text = "...?"},
  AvgDialog_13946_Content_39 = {
    Text = "<Gray:So pessimistisch, ist das wirklich der Goliath, den ich kenne?>"
  },
  AvgDialog_13946_Content_4 = {
    Text = "<Red:Gnade, Gnade, Gnade...>"
  },
  AvgDialog_13946_Content_40 = {
    Text = "Übrigens, da ist noch etwas, woran ich Euch erinnern muss."
  },
  AvgDialog_13946_Content_41 = {
    Text = "Am Heck ist ein Loch. Meiner Erfahrung nach wird dieses Schiff bald in zwei Teile zerbrechen. Ihr habt nicht mehr viel Zeit zum Nachdenken."
  },
  AvgDialog_13946_Content_42 = {
    Text = "Platschen!!"
  },
  AvgDialog_13946_Content_43 = {
    Text = "Als ob Goliaths Worte bestätigt werden sollten, traf eine gewaltige Welle das Holzboot und spaltete es augenblicklich in zwei Teile."
  },
  AvgDialog_13946_Content_44 = {
    Text = "<Shake:Aaaah—!!>"
  },
  AvgDialog_13946_Content_45 = {
    Text = "Salziges Meerwasser strömt unaufhörlich in Eure Lungen. Ihr öffnet den Mund, doch noch mehr Wasser verschlingt Euch gänzlich."
  },
  AvgDialog_13946_Content_46 = {
    Text = "Der Körper sinkt immer tiefer, und das Atmen wird zunehmend schwieriger..."
  },
  AvgDialog_13946_Content_47 = {
    Text = "Benommen scheint Ihr ein hilfloses Seufzen zu hören."
  },
  AvgDialog_13946_Content_48 = {
    Text = "Bevor Ihr reagieren könnt, packt eine kräftige Hand Euer Haar und zieht Euch mühelos aus dem Meer."
  },
  AvgDialog_13946_Content_49 = {
    Text = "Hust... Ugh!"
  },
  AvgDialog_13946_Content_5 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_13946_Content_50 = {
    Text = "Haltet Euch fest, das ist unsere einzige Rettungsleine."
  },
  AvgDialog_13946_Content_51 = {
    Text = "Ihr seht Euch um und bemerkt, dass Ihr und Goliath zusammengequetscht auf einer wackeligen Holzplanke sitzt."
  },
  AvgDialog_13946_Content_52 = {
    Text = "Verdammt... Wie können die Perishiten, die Meister des Meeres, nicht schwimmen können?"
  },
  AvgDialog_13946_Content_53 = {
    Text = "Seid Ihr wirklich ein Perishit?"
  },
  AvgDialog_13946_Content_54 = {
    Text = "<SmallShake:Verzeiht, mein Körper war seit meiner Kindheit schwächlich...>"
  },
  AvgDialog_13946_Content_55 = {
    Text = "Danke, mein Herr. Wenn Ihr nicht gewesen wärt, wäre ich hier gestorben..."
  },
  AvgDialog_13946_Content_56 = {
    Text = "...Es scheint, Ihr wurdet nicht von ihnen geschickt, um mich zu töten."
  },
  AvgDialog_13946_Content_57 = {
    Text = "Euer Überlebensinstinkt eben wirkte echt, nicht vorgetäuscht."
  },
  AvgDialog_13946_Content_58 = {
    Text = "Goliath wischte sich das feuchte Haar von der Stirn und blickte auf das nebelverhangene Meer vor ihm."
  },
  AvgDialog_13946_Content_59 = {
    Text = "Als du ins Meer gefallen bist, hast du dich wie eine riesige Krabbe an mich geklammert und wolltest nicht loslassen. Warum?"
  },
  AvgDialog_13946_Content_6 = {Text = "Wach?"},
  AvgDialog_13946_Content_60 = {
    Text = "Hä? Natürlich, um zu überleben..."
  },
  AvgDialog_13946_Content_61 = {
    Text = "Überleben... aber selbst am Leben bist du nutzlos. Du kannst nicht mal schwimmen."
  },
  AvgDialog_13946_Content_62 = {
    Text = "Wofür lebst du überhaupt?"
  },
  AvgDialog_13946_Content_63 = {
    Text = "Goliaths Stimme wurde allmählich schwächer, als würde er dich fragen, oder vielleicht sich selbst."
  },
  AvgDialog_13946_Content_64 = {
    Text = "Von seinem Stamm ins Exil verbannt und schwer verwundet, liegt sein Weg vor ihm, wie das in dichten Nebel gehüllte Meer, voller endloser Ungewissheit."
  },
  AvgDialog_13946_Content_65 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_13946_Content_66 = {
    Text = "Du hast gesagt, du wärst bereit zu sterben, aber als die Wellen kamen, hast du nicht nur dieses Brett gefunden und dich hochgezogen, du hast auch mich gerettet."
  },
  AvgDialog_13946_Content_67 = {
    Text = "...Das ist nur, weil du mir ständig in den Ohren liegst."
  },
  AvgDialog_13946_Content_68 = {
    Text = "Nichts davon ist wichtig. Wichtig ist, dass wir dank dir, Meister, beide am Leben sind."
  },
  AvgDialog_13946_Content_69 = {
    Text = "Warum denkst du, ist das so?"
  },
  AvgDialog_13946_Content_7 = {
    Text = "Das Meer wühlt von der Sonne gebackene Wellen auf und trägt eine salzige Brise mit starkem Fischgeruch zu deiner Nase."
  },
  AvgDialog_13946_Content_70 = {
    Text = "Goliath schüttelte den Kopf."
  },
  AvgDialog_13946_Content_71 = {
    Text = "Um ehrlich zu sein, ich weiß es auch nicht. Aber eines ist mir klar geworden..."
  },
  AvgDialog_13946_Content_72 = {
    Text = "Goliath senkt den Kopf und betrachtet dich nachdenklich."
  },
  AvgDialog_13946_Content_73 = {
    Text = "Ich verstehe jetzt, warum du so ein Versager bist und trotzdem bis heute am Leben bist."
  },
  AvgDialog_13946_Content_8 = {
    Text = "<Gray:Ist das... ein Traum?>"
  },
  AvgDialog_13946_Content_9 = {
    Text = "Wie man es vom notorisch schwächsten Mitglied des Klans erwarten kann — eine einzige große Welle reicht aus, um dich einen halben Tag lang bewusstlos zu schlagen."
  },
  AvgDialog_13947_Content_1 = {
    Text = "Chronik der Riesen"
  },
  AvgDialog_13947_Content_10 = {
    Text = "Nur Narren vertrauen ihr Leben anderen an."
  },
  AvgDialog_13947_Content_11 = {
    Text = "<Gray:Hexe...>"
  },
  AvgDialog_13947_Content_12 = {
    Text = "Laut Goliaths Erwachenakte ist diese sogenannte \"Hexe\" zweifellos Miryam."
  },
  AvgDialog_13947_Content_13 = {
    Text = "Obwohl die weitere Entwicklung nicht wie erwartet verlief, hat Miryam Goliath tatsächlich das Leben gerettet."
  },
  AvgDialog_13947_Content_14 = {
    Text = "Ihr seid schwer verwundet, Herr. Ich fürchte, es gibt keinen anderen Weg. Lasst uns gemeinsam die Hexe finden—"
  },
  AvgDialog_13947_Content_15 = {Text = "Rums!!"},
  AvgDialog_13947_Content_16 = {
    Text = "Mit gewaltiger Kraft wird deine zerbrechliche Kehle fest umklammert und du wirst vom Boden gehoben, bis du dem Riesen von Angesicht zu Angesicht gegenüberstehst."
  },
  AvgDialog_13947_Content_17 = {
    Text = "Ich sage das nur einmal: Sieh mich nicht mit diesem Blick an und sprich nicht in diesem Ton mit mir."
  },
  AvgDialog_13947_Content_18 = {
    Text = "Das Letzte, was ich, Goliath, brauche, ist das Mitleid der Schwachen."
  },
  AvgDialog_13947_Content_19 = {
    Text = "Goliath sprach ruhig, sein Gesichtsausdruck unverändert, als würde er mit dir über das Wetter plaudern."
  },
  AvgDialog_13947_Content_2 = {
    Text = "Die Sonne versengte das Meer, als wollte sie alles Leben in endloser Hitze auslöschen."
  },
  AvgDialog_13947_Content_20 = {
    Text = "Doch du bist so nah, dass du seine Augen deutlich sehen kannst, rot vor Schmerz und Frustration."
  },
  AvgDialog_13947_Content_21 = {
    Text = "In diesem Moment schien er seinen Ruhm als Herrscher der Meere abzulegen und wurde zu nur einem weiteren verlorenen Fisch im endlosen Ozean, genau wie du."
  },
  AvgDialog_13947_Content_22 = {
    Text = "Verzeihung... äh, mein Gebieter..."
  },
  AvgDialog_13947_Content_23 = {
    Text = "<Shake:Wuuu—>"
  },
  AvgDialog_13947_Content_24 = {
    Text = "Der tiefe Klang eines Horns weht aus der Ferne heran."
  },
  AvgDialog_13947_Content_25 = {
    Text = "Das Gewicht am Hals ließ plötzlich nach. Goliath löste seinen Griff und blickte in die Richtung, aus der der Hornklang kam."
  },
  AvgDialog_13947_Content_26 = {
    Text = "<Gray:Hust... Puh, ich bin gerettet...>"
  },
  AvgDialog_13947_Content_27 = {
    Text = "Interessant... Macht ihr euch Sorgen, dass ich nicht schnell genug sterbe, und seid deshalb alle zusammengekommen, um mich zu verabschieden?"
  },
  AvgDialog_13947_Content_28 = {
    Text = "Es dauerte nicht lange, da umzingelte die gewaltige Flotte euch und ließ die schwankenden Holzplanken als einzige Insel in diesem weiten Meer zurück."
  },
  AvgDialog_13947_Content_29 = {
    Text = "Ihr seid bereits umzingelt."
  },
  AvgDialog_13947_Content_3 = {
    Text = "Du und Goliath klammert euch an das Brett, die einzige Insel im weiten Meer. Unter der sengenden Sonne wird dir wieder schwindelig."
  },
  AvgDialog_13947_Content_30 = {
    Text = "Erlaubt mir, allen den tapfersten Anführer in der Geschichte der Phillistine vorzustellen! Den unbeugsamen Riesen von gewaltiger Kraft! Den ehrfurchtgebietenden, unvergleichlichen Stammeshelden—"
  },
  AvgDialog_13947_Content_31 = {
    Text = "<BigShake:Lord Goliath!>"
  },
  AvgDialog_13947_Content_32 = {
    Text = "Das vom Meer reflektierte Sonnenlicht ist zu grell; du kannst nur die Silhouette einer schwarzen Gestalt erkennen, die am Bug steht und auf dich herabblickt."
  },
  AvgDialog_13947_Content_33 = {
    Text = "Die neu hinzugekommenen Brüder wissen es vielleicht nicht, aber dieser Lord wurde in einem Duell schwer verwundet und beinahe gefangen genommen, was unseren gesamten Clan an den Rand einer beispiellosen Krise trieb!"
  },
  AvgDialog_13947_Content_34 = {
    Text = "Das drohende Unheil verschlang den Großteil unseres Volkes! Gepriesen seist du, mein teuerster Lord Goliath!"
  },
  AvgDialog_13947_Content_35 = {
    Text = "Hehe... Wie könnte ich es wagen, mir eine so große Errungenschaft allein anzurechnen, Glen?"
  },
  AvgDialog_13947_Content_36 = {
    Text = "Wer hat sich hinter mir versteckt, zu feige zum Kämpfen, und wer war der Erste, der seine Waffe fallen ließ und weinend nach Hause rannte?"
  },
  AvgDialog_13947_Content_37 = {Text = "Du...!"},
  AvgDialog_13947_Content_38 = {
    Text = "Glens Gesicht lief rot an, seine trüben Augen zitterten, bevor sie sich schließlich auf dich richteten."
  },
  AvgDialog_13947_Content_39 = {
    Text = "Oh, selbst wenn sich der Stamm auflöst, hat der Anführer immer noch einen... sehr entzückenden Gefolgsmann."
  },
  AvgDialog_13947_Content_4 = {
    Text = "<Shake:Entschuldigung, mir geht es nicht gut... Ich ruhe mich kurz aus...>"
  },
  AvgDialog_13947_Content_40 = {
    Text = "Die Schande der Perisiter — ein Versager, der nicht einmal einen einzigen Schlag innerhalb des Stammes einstecken kann, und dennoch dir folgen will, um ein Krieger zu werden..."
  },
  AvgDialog_13947_Content_41 = {
    Text = "Hahahaha...!!"
  },
  AvgDialog_13947_Content_42 = {
    Text = "Goliath blickt auf und entdeckt dich überrascht durch das Gelächter der Menge."
  },
  AvgDialog_13947_Content_43 = {
    Text = "Hey, Kleiner, bist du aus freien Stücken gekommen, um mir zu folgen?"
  },
  AvgDialog_13947_Content_44 = {
    Text = "<Gray:Äh... So erinnere ich mich daran...>"
  },
  AvgDialog_13947_Content_45 = {
    Text = "Ist das nicht rührend? Ich habe nur beiläufig die Hexe erwähnt, und dieser kleine Narr hat es ernst genommen und wollte dir unbedingt hierher folgen..."
  },
  AvgDialog_13947_Content_46 = {
    Text = "Nicht aufzuhalten, haha—"
  },
  AvgDialog_13947_Content_47 = {
    Text = "Platschen!!"
  },
  AvgDialog_13947_Content_48 = {
    Text = "Das Gelächter verstummte abrupt. Ein heftiger Wind heulte auf, und ein abgetrenntes Bein rollte vor aller Augen."
  },
  AvgDialog_13947_Content_49 = {
    Text = "Aaaah... mein Bein, mein Bein!!"
  },
  AvgDialog_13947_Content_5 = {
    Text = "Ein von Schweiß und Blut getränktes Hemd wird dir über den Kopf geworfen, woraufhin du wegen des Gestanks sofort hochspringst."
  },
  AvgDialog_13947_Content_50 = {
    Text = "Der einst dominierende Herrscher der Meere steht wie ein Berg vor Glen und strahlt eine Aura aus, die das Herz gefrieren lässt."
  },
  AvgDialog_13947_Content_51 = {
    Text = "Diese Fliege summt mir schon eine Weile um die Ohren..."
  },
  AvgDialog_13947_Content_52 = {
    Text = "Goliath wischte gemächlich das Blut von seiner Klinge, blickte dann auf und schenkte Glen ein kaltes Lächeln."
  },
  AvgDialog_13947_Content_53 = {
    Text = "Glenn, habe ich dir nicht gerade eine Frage gestellt?"
  },
  AvgDialog_13947_Content_6 = {
    Text = "Hust... Ugh!"
  },
  AvgDialog_13947_Content_7 = {
    Text = "Du hast einen Hitzschlag. Leg dir das auf den Kopf, um dich vor der Sonne zu schützen, und nimm es nicht ab."
  },
  AvgDialog_13947_Content_8 = {
    Text = "Wie erwartet von den Kleidern, die der Meister getragen hat, wahrhaft belebend...\nWohin sollen wir als Nächstes gehen? Die Hexe suchen?"
  },
  AvgDialog_13947_Content_9 = {
    Text = "Was soll der Unsinn über Hexen? Du glaubst doch nicht etwa ihren Lügen, oder?"
  },
  AvgDialog_13948_Content_1 = {
    Text = "Goldener Refrain"
  },
  AvgDialog_13948_Content_10 = {
    Text = "Die fahle Stille des Meeres wird durchbrochen, als eine dunkel purpurschwarze Seeschlange plötzlich hervorschießt und alle fest umschlingt."
  },
  AvgDialog_13948_Content_11 = {
    Text = "Hmm... Aaaahhh!!"
  },
  AvgDialog_13948_Content_12 = {
    Text = "Mit einem leisen Zischen verwandelt sich der Körper der Schlange in eine pechschwarze Klinge, die die Person vollständig durchbohrt."
  },
  AvgDialog_13948_Content_13 = {
    Text = "<Big:Aus dem Weg>... Huh?"
  },
  AvgDialog_13948_Content_15 = {
    Text = "Ein sanftes, kühles Gefühl geht von dem Hals aus, um den sich die schwarze Schlange windet, und heilt allmählich die Wunde."
  },
  AvgDialog_13948_Content_16 = {
    Text = "Meine Wunden... sind alle geheilt?"
  },
  AvgDialog_13948_Content_17 = {
    Text = "Die schwarze Schlange verlässt dich ohne zu zögern und windet sich schnell fest um Glenn."
  },
  AvgDialog_13948_Content_18 = {
    Text = "Laufen, die Hexe... kommt..."
  },
  AvgDialog_13948_Content_19 = {
    Text = "Die pechschwarzen Schlangen krochen aus Glens Augen und Mund hervor. Er brach zusammen, bevor er einen vollständigen Satz aussprechen konnte."
  },
  AvgDialog_13948_Content_2 = {
    Text = "Klage um den Apostel der See.\nKlage um unser Licht, unsere Hoffnung.\n\nWir wehklagen, weinen und vergießen Tränen über unser Schicksal, ins Meer verbannt zu sein."
  },
  AvgDialog_13948_Content_20 = {
    Text = "Im Nu trieben unzählige zerschmetterte Leichen auf dem Meer."
  },
  AvgDialog_13948_Content_21 = {
    Text = "Dies ist ein stilles Massaker."
  },
  AvgDialog_13948_Content_22 = {
    Text = "<Gray:Ist es vorbei? Beeindruckend, wie man es von Miryam erwarten kann.>"
  },
  AvgDialog_13948_Content_23 = {
    Text = "Du hast uns geholfen... Wer bist du?"
  },
  AvgDialog_13948_Content_24 = {
    Text = "Die Frau mit dem schwarzen Schleier schweigt. Sie steht am Bug, ein dichter Nebel trennt dich von ihr."
  },
  AvgDialog_13948_Content_25 = {
    Text = "So nah und doch so fern."
  },
  AvgDialog_13948_Content_26 = {
    Text = "Die Frau blickte den verblüfften Goliath an, ein schwaches Lächeln umspielte ihre Lippen. Sie streckte ihren Finger in die Ferne, als würde sie eine stille Einladung aussprechen."
  },
  AvgDialog_13948_Content_27 = {
    Text = "Dann wendete sie den Bug und entfernte sich gemächlich."
  },
  AvgDialog_13948_Content_28 = {
    Text = "Warte, geh nicht...<Big:Geh nicht fort!>"
  },
  AvgDialog_13948_Content_29 = {
    Text = "Der Nebel lichtet sich, und ein Sonnenstrahl durchbricht die Wolken und taucht die Wellen in goldenes Licht."
  },
  AvgDialog_13948_Content_3 = {
    Text = "Das Sichtfeld verdunkelt sich plötzlich; das grelle Sonnenlicht schwindet allmählich, und ein dichter Nebel legt sich über die gesamte Meeresoberfläche."
  },
  AvgDialog_13948_Content_30 = {
    Text = "Du blinzelst, und das Ende des Meeres ist bereits leer."
  },
  AvgDialog_13948_Content_31 = {
    Text = "Der Sturm legt sich, und du und Goliath klammern euch an die einzige intakte Planke und ringt nach Atem."
  },
  AvgDialog_13948_Content_32 = {
    Text = "Das einst azurblaue Meer ist längst blutrot gefärbt, und ihr treibt dahin wie Wasserlinsen."
  },
  AvgDialog_13948_Content_33 = {
    Text = "Konnte das Schiff immer noch nicht bekommen... Jetzt weiß ich nicht einmal, wie ich nach Hause kommen soll."
  },
  AvgDialog_13948_Content_34 = {
    Text = "Ich gehe nicht nach Hause."
  },
  AvgDialog_13948_Content_35 = {
    Text = "Goliath stützte ein Bein auf und starrte mit leerem Blick in die Richtung, in die Miryam verschwunden war."
  },
  AvgDialog_13948_Content_36 = {
    Text = "Ich habe mich entschieden. Ich werde diese Hexe finden. Kommst du mit?"
  },
  AvgDialog_13948_Content_37 = {
    Text = "Ähm, „Nur ein Narr würde sein Leben einem anderen anvertrauen.“"
  },
  AvgDialog_13948_Content_38 = {
    Text = "Du senkst absichtlich deine Stimme, ahmst Goliaths früheren Tonfall nach und wiederholst, was er gesagt hat."
  },
  AvgDialog_13948_Content_39 = {
    Text = "Hmph, das liegt daran, dass der Einsatz nicht hoch genug war. Ich habe noch nie eine Macht gesehen, die alles in einem Augenblick zermalmen kann."
  },
  AvgDialog_13948_Content_4 = {
    Text = "Oh, beschütze jene, die vom Unglück geplagt sind.\nRichte deinen barmherzigen Blick auf uns..."
  },
  AvgDialog_13948_Content_40 = {
    Text = "Außerdem hat sie uns gerade geholfen und mir sogar eine Einladung ausgesprochen..."
  },
  AvgDialog_13948_Content_41 = {
    Text = "Aber was, wenn... es eine Falle ist?"
  },
  AvgDialog_13948_Content_42 = {Text = "Falle..."},
  AvgDialog_13948_Content_43 = {
    Text = "Erinnerst du dich an die Frage, die du mir vorhin gestellt hast?"
  },
  AvgDialog_13948_Content_44 = {
    Text = "...Das Wichtige ist, dank Euch, mein Gebieter, sind wir beide jetzt am Leben."
  },
  AvgDialog_13948_Content_45 = {
    Text = "Warum denkst du, ist das so?"
  },
  AvgDialog_13948_Content_46 = {
    Text = "Jetzt weiß ich die Antwort."
  },
  AvgDialog_13948_Content_47 = {
    Text = "Was ist die Antwort?"
  },
  AvgDialog_13948_Content_48 = {
    Text = "Ein Schwarm Seevögel flog plötzlich zusammen auf. Ihre weißen Schwingen schlugen wie Wolken im Flug, frei treibend in der Meeresbrise."
  },
  AvgDialog_13948_Content_49 = {
    Text = "Goliath ließ sich von dem Vogelschwarm nicht stören. Er starrte geradeaus, seine Augen leuchteten vor Begeisterung."
  },
  AvgDialog_13948_Content_5 = {
    Text = "Uralte, unheimliche Gesänge wehen heran. Die Silhouette einer Frau erscheint und verschwindet am Bug, wie ein Geist, der durch den Nebel wandelt."
  },
  AvgDialog_13948_Content_50 = {
    Text = "Weil ich Goliath bin."
  },
  AvgDialog_13948_Content_51 = {
    Text = "Goliath, der am längsten regierende Anführer in der Geschichte der Phillistine, ein unbezwingbarer Riese und ein legendärer Stammesheld."
  },
  AvgDialog_13948_Content_52 = {
    Text = "Selbst wenn nur ein einziger Gefolgsmann übrig bleibt – solange es einen Funken Hoffnung gibt, kann ich mich wieder erheben."
  },
  AvgDialog_13948_Content_53 = {
    Text = "Diese Hexe ist meine letzte Chance. Nur sie kann mir absolute Macht verleihen."
  },
  AvgDialog_13948_Content_54 = {
    Text = "Selbst wenn es eine Falle ist, werde ich hingehen."
  },
  AvgDialog_13948_Content_55 = {
    Text = "Warum rettest du mich dann? Ein „Taugenichts“ wie ich kann dir wahrscheinlich nicht von Nutzen sein..."
  },
  AvgDialog_13948_Content_56 = {
    Text = "Du hast absichtlich die Aussprache eines Wortes betont, was Goliath zum Lachen brachte."
  },
  AvgDialog_13948_Content_57 = {
    Text = "Das Sonnenlicht durchbricht die Wolken und taucht alles in goldenen Glanz. Haarsträhnen tanzen sanft unter dem azurblauen Himmel."
  },
  AvgDialog_13948_Content_58 = {
    Text = "Ein Anführer ohne Gefolgsleute kann in dieser Welt unmöglich Erfolg haben."
  },
  AvgDialog_13948_Content_59 = {
    Text = [[
Kleines, du bist nicht nutzlos.
Du bist der einzige Gefolgsmann der Riesin Goliath, und niemand kann dich ersetzen.]]
  },
  AvgDialog_13948_Content_6 = {
    Text = "Hm, singt da jemand?"
  },
  AvgDialog_13948_Content_60 = {
    Text = "Wenn ich meine Vorherrschaft erringe, werde ich dich zumindest zum Stammeshäuptling ernennen!"
  },
  AvgDialog_13948_Content_61 = {
    Text = "...Nicht nötig."
  },
  AvgDialog_13948_Content_62 = {
    Text = "Der Himmel verdunkelte sich allmählich. Das Leuchten der Abenddämmerung glich schimmernden goldenen Flüssen, die über den Horizont strömten."
  },
  AvgDialog_13948_Content_63 = {
    Text = "Hey, weißt du was? Helden können nur Helden sein, weil es Leute wie uns gibt."
  },
  AvgDialog_13948_Content_64 = {
    Text = "<Small:Also bin ich auch wichtig, verstanden...>"
  },
  AvgDialog_13948_Content_65 = {
    Text = "<Small:Ugh...>"
  },
  AvgDialog_13948_Content_66 = {
    Text = "Bruchstückhafte Worte zerstreuen sich wie Pusteblumen in der Meeresbrise, weit, weit davongetragen."
  },
  AvgDialog_13948_Content_67 = {
    Text = "Du und Goliath saßt auf einer dünnen Holzplanke und saht aus wie winzige Blätter, die in einem goldenen Meer trieben."
  },
  AvgDialog_13948_Content_68 = {
    Text = "Niemand weiß, wohin ihr letztendlich segeln werdet."
  },
  AvgDialog_13948_Content_7 = {
    Text = "<Shake:Die Hexe, es ist die Hexe!>"
  },
  AvgDialog_13948_Content_8 = {
    Text = "Wie kann das sein... Könnte die Legende tatsächlich wahr sein..."
  },
  AvgDialog_13948_Content_9 = {
    Text = [[
<Red:Gnade.
         Gnade.
                  Gnade...>]]
  },
  AvgDialog_139656_Content_1 = {Text = "Abschied"},
  AvgDialog_139656_Content_10 = {
    Text = "So wie ich jetzt bin...? Hmm. Besser, wenn du das nicht tust."
  },
  AvgDialog_139656_Content_11 = {
    Text = "Nach der Verbindung gerade eben... hat sich vieles verändert."
  },
  AvgDialog_139656_Content_12 = {
    Text = "Was das angeht... ich hatte einen Traum."
  },
  AvgDialog_139656_Content_13 = {
    Text = "Im Traum war Ramona zu etwas geworden..."
  },
  AvgDialog_139656_Content_14 = {
    Text = "Egal wie oft du es in Gedanken hin und her gewendet hast, das Bild entzieht sich noch immer den Worten. Dein Körper schreckt zurück, bevor deine Gedanken nachkommen."
  },
  AvgDialog_139656_Content_15 = {
    Text = "Ich weiß. Du warst verängstigt. Abgestoßen."
  },
  AvgDialog_139656_Content_16 = {
    Text = "Die Domäne ist Teil meiner Seelenlandschaft—also konnte ich es spüren."
  },
  AvgDialog_139656_Content_17 = {
    Text = "Es tut mir aufrichtig leid, was ich dir angetan habe."
  },
  AvgDialog_139656_Content_18 = {
    Text = "Nein—das wollte ich nicht sagen."
  },
  AvgDialog_139656_Content_19 = {
    Text = "Ich meine... damals wusste ich nicht, ob dieses in Fleisch gehüllte Wesen wirklich sie war."
  },
  AvgDialog_139656_Content_2 = {
    Text = "Die Welt ist wieder „normal\" geworden. Normal nach den Maßstäben eurer Welt."
  },
  AvgDialog_139656_Content_20 = {
    Text = "Aber jetzt weiß ich es. Das war die Ramona, die ich kenne. Also habe ich jetzt keine Angst mehr."
  },
  AvgDialog_139656_Content_21 = {
    Text = "Die Worte geben dir Halt. Deine Stimme wird allmählich fester."
  },
  AvgDialog_139656_Content_22 = {
    Text = "Das Aussehen spielt keine Rolle. Was zählt, ist nur die Verbindung zwischen mir und meinen Erweckern—jene, die durch die Silberkerne verlaufen."
  },
  AvgDialog_139656_Content_23 = {
    Text = "Ich habe zu viele solcher Dinge gesehen, um mich allein vom Äußeren erschüttern zu lassen."
  },
  AvgDialog_139656_Content_24 = {
    Text = "Ich habe ein Herz aus purem Gold gesehen, geboren aus dem übelsten Morast der Welt;"
  },
  AvgDialog_139656_Content_25 = {
    Text = "Ich habe Liebe gesehen—wahre, zärtliche Liebe—die im fiebrigsten Verlangen nach Fortpflanzung Wurzeln schlug. Also—"
  },
  AvgDialog_139656_Content_26 = {
    Text = "Alles verstummt."
  },
  AvgDialog_139656_Content_27 = {
    Text = "Nach einer langen Pause breitet sich ein Lächeln auf der anderen Seite der Verbindung aus—ruhig und gelassen."
  },
  AvgDialog_139656_Content_28 = {
    Text = "...Ich bin so froh, dass ich dich getroffen habe."
  },
  AvgDialog_139656_Content_29 = {
    Text = "……Dann, im schwankenden Geheimgang, versankst Du erneut in jenen Traum."
  },
  AvgDialog_139656_Content_3 = {
    Text = "Gelber Sand, erstickt in Auflösungsschlamm, erstreckt sich in eine endlose, heulende Weite."
  },
  AvgDialog_139656_Content_30 = {
    Text = "Wｸi&Lｨlｴ0ﾋkEｺoｸmO3mEｸnｱ aﾉnｲ dｸeR巛 UｻnｦiVｭeRｲsｲiTｸäT, %player%."
  },
  AvgDialog_139656_Content_31 = {
    Text = "Das zähflüssige, kehlige Geräusch kriecht aus einer Masse aus windendem, verrottendem Fleisch hervor."
  },
  AvgDialog_139656_Content_32 = {
    Text = "In einer Welt, die in Blut und Schlick gehüllt ist, streckt Ramona—glitschig vor Flüssigkeit—ihre Hand aus. Ihre Finger streifen kaum deinen kleinen Finger."
  },
  AvgDialog_139656_Content_33 = {
    Text = "Ich werde diesen Moment niemals vergessen."
  },
  AvgDialog_139656_Content_34 = {
    Text = "Du flüsterst leise in deinem Herzen."
  },
  AvgDialog_139656_Content_35 = {
    Text = "Mｸö&Gｨeｴ dﾋeRｺ S3iLｸbEｱrSﾉcｲhLｸüS巛sEｻlｦ dｭEiｲNｲeNｸ wEg eRlEuChTeN."
  },
  AvgDialog_139656_Content_36 = {
    Text = "Inmitten von Fleisch und Verwüstung ergreifst du fest Ramonas Hand und starrst direkt in ihre hohlen Augen und ihre blutbefleckte Gestalt."
  },
  AvgDialog_139656_Content_37 = {
    Text = "Möge der Silberschlüssel uns leiten"
  },
  AvgDialog_139656_Content_38 = {
    Text = "Der Glanz des Silberschlüssels breitet sich über die gesamte Welt aus."
  },
  AvgDialog_139656_Content_39 = {
    Text = "Eine reinweiße Gestalt taucht in deinem Geist auf. Es ist Shaye, lächelnd."
  },
  AvgDialog_139656_Content_4 = {
    Text = "Nur die kleine Hütte im Wald ist getränkt in der rohen, fleischigen Farbe von Eingeweiden. Und durch die Verbindung spürst du Shaye darin. Du weißt, dass ihr Ende nur noch Herzschläge entfernt ist."
  },
  AvgDialog_139656_Content_40 = {
    Text = "Etwas wie wunderschöne Flügel flattert im Wind."
  },
  AvgDialog_139656_Content_41 = {
    Text = "Pusteblumen erheben sich und verstreuen sich in den azurblauen Himmel."
  },
  AvgDialog_139656_Content_42 = {
    Text = "In dem Moment, in dem sich jeder Samen vom Stiel löst, weicht die verschwommene, traumhafte Welt der Realität."
  },
  AvgDialog_139656_Content_43 = {
    Text = "Du erwachst aus dem Traum, und alle Dinge offenbaren ihre wahre Gestalt."
  },
  AvgDialog_139656_Content_44 = {
    Text = "Vielen Dank..."
  },
  AvgDialog_139656_Content_45 = {
    Text = "Du scheinst ein geflüstertes Lebewohl an deinem Ohr zu hören. Ist es eine Illusion?"
  },
  AvgDialog_139656_Content_46 = {
    Text = "Irgendwann erscheint ein Silberkern in deiner Handfläche."
  },
  AvgDialog_139656_Content_47 = {
    Text = "Es ist derselbe Kern, den Tinct einst fand, jener, der mit ewiger Sehnsucht erfüllt ist."
  },
  AvgDialog_139656_Content_48 = {
    Text = "Wenn die Zeit gekommen ist, wirst du ihn nutzen können—um ihre ewige „Liebe“ zu erwecken."
  },
  AvgDialog_139656_Content_49 = {
    Text = "—Die Liebe von Shaye... dem Erweckten Körper."
  },
  AvgDialog_139656_Content_5 = {
    Text = "Ich glaube, unsere Seelen sind nun verbunden. Und damit... wird die Barriere vollständig verschwinden."
  },
  AvgDialog_139656_Content_6 = {
    Text = "In meinen letzten Momenten so empfinden zu können... Ich bin zufrieden. ...Danke."
  },
  AvgDialog_139656_Content_7 = {
    Text = "Nun — verlasse diesen Ort. Geh hinaus in den Sand. Am Rand dieses Dünenmeeres wirst du mit deiner Vergangenheit wiedervereint."
  },
  AvgDialog_139656_Content_8 = {
    Text = "Es ist in Ordnung. Selbst wenn ich nicht mehr in dieser Welt bin, wird unser Bewusstsein durch die Silberkerne verbunden bleiben."
  },
  AvgDialog_139656_Content_9 = {
    Text = "Bevor es endet—lässt du mich deine wahre Gestalt sehen?"
  },
  AvgDialog_139657_Content_1 = {
    Text = "„Mission\""
  },
  AvgDialog_139657_Content_10 = {
    Text = "Etwas kommt. Ich kann es an den Rändern spüren..."
  },
  AvgDialog_139657_Content_11 = {
    Text = "Shaye runzelt die Stirn, ihr Gesicht angespannt und blass."
  },
  AvgDialog_139657_Content_12 = {
    Text = "Du reißt das Fleisch von ihrem Handgelenk und hilfst ihr auf die Beine."
  },
  AvgDialog_139657_Content_13 = {
    Text = "Ich möchte das Löwenzahnfeld sehen. Begleitest du mich ein Stück?"
  },
  AvgDialog_139657_Content_14 = {
    Text = "Du solltest dich ausruhen..."
  },
  AvgDialog_139657_Content_15 = {
    Text = "Es ist in Ordnung. Wirklich..."
  },
  AvgDialog_139657_Content_16 = {
    Text = "Shaye schiebt sanft die Hüttentür auf. Die Welt draußen flutet dein Blickfeld."
  },
  AvgDialog_139657_Content_17 = {
    Text = "Die Farbe des Feldes hat sich verändert."
  },
  AvgDialog_139657_Content_18 = {
    Text = "Das üppige Grün von gestern ist nun von einem tiefen rot-schwarzen Schatten überzogen. Die spärlichen Halme können sich nicht behaupten, verzerrt und vom Verfall verschlungen."
  },
  AvgDialog_139657_Content_19 = {
    Text = "Das ist <Red:Auflösung>......!"
  },
  AvgDialog_139657_Content_2 = {
    Text = "Groteske Träume kommen wie eine Flut über dich."
  },
  AvgDialog_139657_Content_20 = {
    Text = "Du siehst... traurig aus?"
  },
  AvgDialog_139657_Content_21 = {
    Text = "Gestern war dies ein wunderschönes Löwenzahnfeld."
  },
  AvgDialog_139657_Content_22 = {
    Text = "Heute hat die Auflösung es gefunden, es ganz verschlungen. In ein paar Tagen wird es vollständig verschwunden sein."
  },
  AvgDialog_139657_Content_23 = {
    Text = "Und nach genug Zeit wird selbst die Erinnerung daran verblassen—selbst aus deiner."
  },
  AvgDialog_139657_Content_24 = {
    Text = "Betrübt dich das nicht?"
  },
  AvgDialog_139657_Content_25 = {
    Text = "Hmm, empfindest du das so...?"
  },
  AvgDialog_139657_Content_26 = {
    Text = "Siehst du es anders?"
  },
  AvgDialog_139657_Content_27 = {
    Text = "Mm. Es gibt immer so viele verschiedene Dinge auf dieser Welt..."
  },
  AvgDialog_139657_Content_28 = {
    Text = "Und die Stärkeren nehmen und plündern von den Schwächeren."
  },
  AvgDialog_139657_Content_29 = {
    Text = "So ist es doch, oder?"
  },
  AvgDialog_139657_Content_3 = {
    Text = "Ramonas Gestalt flackert auf und ab—ihre Stimme an den Nähten zerrissen, rasselnd wie Luft, die durch einen gebrochenen Blasebalg gepresst wird."
  },
  AvgDialog_139657_Content_30 = {
    Text = "Nein. Genau deshalb gibt es Misaq."
  },
  AvgDialog_139657_Content_31 = {
    Text = "Wir stehen zwischen der Auflösung und allem, was sie verschlingen würde—Leben und Erinnerungen, die vielleicht nicht mächtig sind, aber dennoch ihr eigenes Licht tragen."
  },
  AvgDialog_139657_Content_32 = {
    Text = "Und das schließt dich ein, Shaye."
  },
  AvgDialog_139657_Content_33 = {
    Text = "...Ist das so."
  },
  AvgDialog_139657_Content_34 = {
    Text = "Sie murmelt es vor sich hin."
  },
  AvgDialog_139657_Content_35 = {
    Text = "In dem Fall... vielleicht hast du recht..."
  },
  AvgDialog_139657_Content_36 = {
    Text = "Ihr wandert durch die sich wiederholende Landschaft, was sich wie eine Ewigkeit anfühlt, bis ein Hauch von etwas anderem endlich die Eintönigkeit durchbricht."
  },
  AvgDialog_139657_Content_37 = {
    Text = "Noch ein Löwenzahnfeld...?"
  },
  AvgDialog_139657_Content_38 = {
    Text = "Shaye hat den Kopf gesenkt und atmet leise. Du kannst ihr Gesicht nicht sehen."
  },
  AvgDialog_139657_Content_39 = {
    Text = "Das ist... die Hütte, von der wir gestartet sind. Schau dort drüben."
  },
  AvgDialog_139657_Content_4 = {
    Text = "Du fährst aus dem Schlaf hoch."
  },
  AvgDialog_139657_Content_40 = {
    Text = "Du zeigst auf die Ecke des Raumes—das Stück Fleisch, das du heute Morgen von Shayes Handgelenk gerissen und beiseitegeworfen hattest."
  },
  AvgDialog_139657_Content_41 = {
    Text = "...Wir sind im Kreis gelaufen."
  },
  AvgDialog_139657_Content_42 = {
    Text = "Es gibt nichts in diesem Gebiet außer Trostlosigkeit."
  },
  AvgDialog_139657_Content_43 = {
    Text = "Ist auch gut so. Wir können... uns eine Weile ausruhen."
  },
  AvgDialog_139657_Content_44 = {
    Text = "Sie lächelt, als wäre es nichts. Aber ihre Stimme franst an den Rändern aus, zittert leicht, auf eine Weise, die sie nicht ganz zurückhalten kann."
  },
  AvgDialog_139657_Content_45 = {
    Text = "Shaye, dein Körper..."
  },
  AvgDialog_139657_Content_46 = {
    Text = "Ich bin nur ein wenig müde..."
  },
  AvgDialog_139657_Content_47 = {
    Text = "Direkt vor deinen Augen knicken ihre Knie ein — sie sackt geradewegs zusammen, als hätte alles, was sie aufrecht hielt, einfach nachgegeben."
  },
  AvgDialog_139657_Content_48 = {Text = "Shaye!"},
  AvgDialog_139657_Content_49 = {
    Text = "Tief in der Nacht glüht Shaye vor Fieber. Ihren Anweisungen folgend entzündest du ein Feuer aus Materialien, deren Namen du beim besten Willen nicht nennen könntest."
  },
  AvgDialog_139657_Content_5 = {
    Text = "*Hust, hust...*"
  },
  AvgDialog_139657_Content_50 = {
    Text = "Hätte ich gewusst, dass du so krank bist, hätte ich dich niemals den ganzen Tag laufen lassen..."
  },
  AvgDialog_139657_Content_51 = {
    Text = "Schon gut. Ich glaube nicht, dass ich wegen des Laufens krank bin.\nAber — können wir ein wenig reden?"
  },
  AvgDialog_139657_Content_52 = {
    Text = "Natürlich. Worüber möchtest du reden?"
  },
  AvgDialog_139657_Content_53 = {
    Text = "Heute Morgen hast du gesagt, du und Misaq wollt gegen die Auflösung kämpfen. Um andere Menschen zu beschützen. Um mich zu beschützen."
  },
  AvgDialog_139657_Content_54 = {
    Text = "Hast du das wirklich so gemeint?"
  },
  AvgDialog_139657_Content_55 = {
    Text = "Jedes Wort. Ich habe es an dem Tag geschworen, als mir der Silberschlüssel verliehen wurde."
  },
  AvgDialog_139657_Content_56 = {
    Text = "Deine Stimme klingt fester, als du erwartet hättest. In dem Moment, als die Worte deine Lippen verlassen, taucht die Zeremonie vor deinem inneren Auge auf —"
  },
  AvgDialog_139657_Content_57 = {
    Text = "Das kühle Gewicht des Silberschlüssels legt sich in deine Handfläche. Die feierlichen Blicke der Menge. Die brennende Entschlossenheit in deinem Herzen, als du deine Finger darum schlossest."
  },
  AvgDialog_139657_Content_58 = {
    Text = "Shaye verstummt für einen Moment. Das Feuerlicht vergoldet die zarte Kontur ihrer Silhouette in einem warmen, bernsteinfarbenen Schein."
  },
  AvgDialog_139657_Content_59 = {
    Text = "Dann — wenn du eines Tages deine Macht als Schutzherr verlierst... wenn du ein gewöhnlicher Mensch wirst,"
  },
  AvgDialog_139657_Content_6 = {
    Text = "Shaye lehnt an der Kabinentür und hustet leise."
  },
  AvgDialog_139657_Content_60 = {
    Text = "und die Pflicht gegen die Auflösung nicht mehr tragen könntest... was würdest du tun?"
  },
  AvgDialog_139657_Content_61 = {
    Text = "Nun, darüber habe ich bereits nachgedacht."
  },
  AvgDialog_139657_Content_62 = {
    Text = "Du lehnst dich zurück, stützt die Hände ins Gras hinter dir und richtest den Blick hinauf zu den Sternen."
  },
  AvgDialog_139657_Content_63 = {
    Text = "Ich würde den Rest meines Lebens mit den Menschen verbringen, die ich liebe. Still. Ganz gewöhnlich."
  },
  AvgDialog_139657_Content_64 = {
    Text = "Wenn wir alt und grau sind, zu müde, um noch zu rennen, würden wir am Kamin sitzen und immer wieder dieselben albernen Geschichten aus unserer Jugend erzählen, bis sie jeder auswendig kennt."
  },
  AvgDialog_139657_Content_65 = {
    Text = "Ramona würde immer noch jeden einzelnen Namen korrigieren, den LORD Dexter falsch ausgesprochen hat. Wilhelm würde diesen gleichen, perfekt gefassten Ausdruck auf seinem Gesicht haben, ein Buch haltend, als würde er lesen, während seine Ohren gespitzt sind..."
  },
  AvgDialog_139657_Content_66 = {
    Text = "Professorin Czort würde immer noch ihren Wodka umklammern und alle zum Mitsingen mitreißen, sobald sie in Fahrt kommt."
  },
  AvgDialog_139657_Content_67 = {
    Text = "Du drehst den Kopf. Shaye beobachtet dich still. Das Feuerlicht flackert in ihren Augen wie winzige, eingefangene Sterne."
  },
  AvgDialog_139657_Content_68 = {
    Text = "Das klingt wunderbar."
  },
  AvgDialog_139657_Content_69 = {Text = "Aber..."},
  AvgDialog_139657_Content_7 = {
    Text = "Shaye! Deine Hand!"
  },
  AvgDialog_139657_Content_70 = {
    Text = "Ihre Stimme stockt. Sie wendet den Blick ab, ihre Augen trüben sich, starren in die Leere einer dunklen Ecke."
  },
  AvgDialog_139657_Content_71 = {
    Text = "Wenn du von ihnen getrennt wärst—wenn niemand mehr an deiner Seite wäre—was würdest du dann tun?"
  },
  AvgDialog_139657_Content_72 = {
    Text = "Sind sie gegangen? Oder haben sie nie existiert?"
  },
  AvgDialog_139657_Content_73 = {
    Text = "Wenn... du noch die Erinnerungen hättest. Daran, ihnen begegnet zu sein, an die gemeinsam verbrachte Zeit..."
  },
  AvgDialog_139657_Content_74 = {
    Text = "Aber es ist zu viel Zeit vergangen. Die Erinnerungen sind in Stücken. Und du weißt nicht einmal, ob sie echt sind..."
  },
  AvgDialog_139657_Content_75 = {
    Text = "Solange ich mich noch erinnern kann, würde ich nach ihnen suchen."
  },
  AvgDialog_139657_Content_76 = {
    Text = "Wo auch immer sie sind. Was auch immer es kostet."
  },
  AvgDialog_139657_Content_77 = {
    Text = "In deinem Blick ist nicht das geringste Zögern."
  },
  AvgDialog_139657_Content_78 = {
    Text = "Wenn... ich meine, wenn du sie nicht finden kannst?"
  },
  AvgDialog_139657_Content_79 = {
    Text = "Ich würde trotzdem weitersuchen—jeden Weg entlang, über jeden Berg, über jedes Meer..."
  },
  AvgDialog_139657_Content_8 = {
    Text = "Von schwarzem Schleim durchzogenes Fleisch hat sich durch die Spalten der Tür gewunden und sich um ihr Handgelenk geschlungen."
  },
  AvgDialog_139657_Content_80 = {
    Text = "Bis die Suche selbst mich durch meine letzten Tage trüge."
  },
  AvgDialog_139657_Content_81 = {
    Text = "Und wenn dieser letzte Moment käme, wenn sich meine Augen endlich schlössen, glaube ich, würde ich mich ganz fühlen."
  },
  AvgDialog_139657_Content_82 = {
    Text = "Denn ich hätte mit Erinnerungen gelebt, die es wert sind, bewahrt zu werden, und mit einem Ziel, das ich erreichen musste, koste es, was es wolle."
  },
  AvgDialog_139657_Content_83 = {
    Text = "Die Suche selbst ist der Sinn."
  },
  AvgDialog_139657_Content_84 = {
    Text = "Stille senkt sich herab, als deine Worte verklingen. Nur das leise Rascheln der Pusteblumen im Wind bleibt."
  },
  AvgDialog_139657_Content_85 = {Text = "...Shaye?"},
  AvgDialog_139657_Content_86 = {
    Text = "Shaye hat die Augen geschlossen. Ihr Gesicht ist blass, fast durchscheinend. Dein Herz zieht sich zusammen."
  },
  AvgDialog_139657_Content_87 = {Text = "Shaye..."},
  AvgDialog_139657_Content_88 = {
    Text = "Du beugst dich vor—und stellst fest, dass ihr Atem langsam und gleichmäßig geht, ihre Brust sich in einem kaum wahrnehmbaren Rhythmus hebt und senkt, wie die kleinste Welle auf einem stillen See."
  },
  AvgDialog_139657_Content_89 = {
    Text = "Hmm, du schläfst nur..."
  },
  AvgDialog_139657_Content_9 = {
    Text = "Solche Veränderungen... sind nicht das, was mir Sorgen macht."
  },
  AvgDialog_139657_Content_90 = {
    Text = "Ich bin... auch ein wenig müde..."
  },
  AvgDialog_139657_Content_91 = {
    Text = "Die Erleichterung trifft dich auf einen Schlag, und mit ihr überwältigen dich die Erschöpfung des Tages und die visuelle Belastung der Höllenlandschaft."
  },
  AvgDialog_139657_Content_92 = {
    Text = "Bevor das Ende kommt, gleitet auch diese Nacht still durch deine Finger."
  },
  AvgDialog_139658_Content_1 = {
    Text = "Nach dem Regen"
  },
  AvgDialog_139658_Content_10 = {
    Text = "Wie schön... die Sonne zu spüren."
  },
  AvgDialog_139658_Content_11 = {
    Text = "Sie lächelt und streckt die Hand dorthin aus, wo das Licht fällt, wie eine Pflanze, die sich dem Sonnenlicht entgegenneigt."
  },
  AvgDialog_139658_Content_12 = {
    Text = "Hilfst du mir nach draußen?"
  },
  AvgDialog_139658_Content_13 = {
    Text = "Du führst sie dazu, sich an die Hüttenwand zu lehnen. Selbst diese kurze Strecke lässt ihren Atem flach und mühsam werden."
  },
  AvgDialog_139658_Content_14 = {
    Text = "Shaye, dein Körper..."
  },
  AvgDialog_139658_Content_15 = {
    Text = "Mach dir keine Sorgen. Ich glaube, meine Zeit ist fast abgelaufen."
  },
  AvgDialog_139658_Content_16 = {
    Text = "Du spürst es doch auch, oder? Die Barriere, die unsere Verbindung blockiert... sie zerbröckelt."
  },
  AvgDialog_139658_Content_17 = {
    Text = "Es wird nicht mehr lange dauern, bis sie vollständig zusammenbricht.\nWenn es soweit ist... sollten wir die Verbindung herstellen können, von der du gesprochen hast."
  },
  AvgDialog_139658_Content_18 = {Text = "Aber..."},
  AvgDialog_139658_Content_19 = {
    Text = "Sobald die Verbindung hergestellt ist, könnte Shaye verschwinden. Diese Barriere ist ihr letzter Schutzschild—und sie wird nur dünner, weil ihre Kraft schwindet."
  },
  AvgDialog_139658_Content_2 = {
    Text = "Als du aufwachst, hat sich das Licht verändert."
  },
  AvgDialog_139658_Content_20 = {
    Text = "Bitte halte dich nicht zurück. Dass du hier bei mir bist, dass wir so miteinander reden können... Ich bin wirklich glücklich."
  },
  AvgDialog_139658_Content_21 = {
    Text = "Sie blinzelt gegen das Licht und schenkt ein aufrichtiges, doch zerbrechliches Lächeln. Du kannst kaum hinsehen, aber du zwingst dich, jedes Detail in dein Gedächtnis einzubrennen."
  },
  AvgDialog_139658_Content_22 = {
    Text = "Ich bleibe bei dir. Bis zum allerletzten Ende."
  },
  AvgDialog_139658_Content_23 = {
    Text = "Komm schon, schau nicht so schwermütig. Lass uns da weitermachen, wo wir gestern aufgehört haben."
  },
  AvgDialog_139658_Content_24 = {
    Text = "Du hast gesagt, dass du selbst ohne deine Kraft, selbst wenn niemand mehr an deiner Seite ist, weitermachen würdest."
  },
  AvgDialog_139658_Content_25 = {
    Text = "Ich will wissen, warum."
  },
  AvgDialog_139658_Content_26 = {
    Text = "Warum? Das Sonnenlicht nach dem Regen ist so grell, dass es in den Augen brennt vor ungeweinten Tränen."
  },
  AvgDialog_139658_Content_27 = {
    Text = "Du holst langsam und gleichmäßig Atem."
  },
  AvgDialog_139658_Content_28 = {
    Text = "Weil ich Ramona liebe. Ich liebe alle an der Misaq Universität.\nUnd ich weiß—mit Gewissheit—dass sie mich auch lieben."
  },
  AvgDialog_139658_Content_29 = {
    Text = "Aber ihr seid so weit voneinander entfernt. Ihr könnt einander nicht berühren. Ihr könnt nicht bestätigen, was der andere fühlt."
  },
  AvgDialog_139658_Content_3 = {
    Text = "Die feuchte Luft trägt einen reinen, frisch gewaschenen Duft. Was durch die Ritzen der Tür dringt, ist nicht mehr der Wind, sondern ein stiller Lichtstrahl."
  },
  AvgDialog_139658_Content_30 = {
    Text = "Und in einer Welt mit so etwas wie der Auflösung—wie kannst du sicher sein, dass die Menschen, die du vermisst, dich nicht bereits vergessen haben?"
  },
  AvgDialog_139658_Content_31 = {
    Text = "Ihre Stimme ist sanft, fast wie ein Traum, gemurmelt am Rand des Schlafes."
  },
  AvgDialog_139658_Content_32 = {
    Text = "Die Auflösung mag Präsenz auslöschen—aber die Silberkerne verbinden Ramona und mich über das Meer des Unterbewusstseins hinweg."
  },
  AvgDialog_139658_Content_33 = {
    Text = "Du blickst in die Ferne. Der Horizont nach dem Regen ist unglaublich klar. Der Wind reißt eine Lücke in die Wolken, und eine Säule aus goldenem Licht ergießt sich hindurch und trifft den fernen Bergrücken."
  },
  AvgDialog_139658_Content_34 = {
    Text = "Ich kann ihre Präsenz spüren. Selbst jetzt, selbst verstreut über verschiedene Welten—daran hat sich nichts geändert."
  },
  AvgDialog_139658_Content_35 = {
    Text = "Außerdem..."
  },
  AvgDialog_139658_Content_36 = {Text = "Hm?"},
  AvgDialog_139658_Content_37 = {
    Text = "Sie neigt leicht den Kopf."
  },
  AvgDialog_139658_Content_38 = {
    Text = "Wahre Liebende müssen nicht Seite an Seite stehen, um ihre Verbindung zu spüren... oder ihre Liebe zu bestätigen."
  },
  AvgDialog_139658_Content_39 = {
    Text = "Egal wie oft die Welt endet und neu beginnt, ich werde Ramona immer finden. Und sie wird dieselbe Entscheidung treffen."
  },
  AvgDialog_139658_Content_4 = {
    Text = "...Es ist so still draußen."
  },
  AvgDialog_139658_Content_40 = {
    Text = "Ich weiß es einfach. Die Gedanken und Gefühle, die wir im Meer des Bewusstseins teilen... werden niemals durchtrennt werden."
  },
  AvgDialog_139658_Content_41 = {
    Text = "Shaye schweigt lange. Der regengewaschene Wind weht durch die Kabine und streift über ihre blutleere Wange."
  },
  AvgDialog_139658_Content_42 = {
    Text = "Dann lächelt sie."
  },
  AvgDialog_139658_Content_43 = {
    Text = "Ein so heftiges, unerschütterliches Vertrauen... Eine so große Liebe..."
  },
  AvgDialog_139658_Content_44 = {
    Text = "Als sie das Wort ausspricht — Liebe — liegt kein Neid in ihrer Stimme. Keine Trauer. Keine Spur von Sehnsucht."
  },
  AvgDialog_139658_Content_45 = {
    Text = "Nur tiefe Zärtlichkeit."
  },
  AvgDialog_139658_Content_46 = {
    Text = "Wie eine Reisende, die allein durch eine lange Winternacht gewandert ist und endlich das erste Licht der Morgendämmerung am fernen Rand des Horizonts erblickt — sie wird es vielleicht nie erreichen. Aber allein zu wissen, dass das Licht existiert, ist genug."
  },
  AvgDialog_139658_Content_47 = {
    Text = "Shaye lächelt, in Trance versunken."
  },
  AvgDialog_139658_Content_48 = {
    Text = "Dann streckt sie die Hand nach dir aus."
  },
  AvgDialog_139658_Content_49 = {
    Text = "...Halt meine Hand."
  },
  AvgDialog_139658_Content_5 = {
    Text = "Der Regen... hat er aufgehört?"
  },
  AvgDialog_139658_Content_50 = {
    Text = "Ihre Hand ist blass und schmal und zittert leicht. Sie kann dich nicht sehen, und doch streckt sich ihre Hand unfehlbar in deine Richtung —"
  },
  AvgDialog_139658_Content_51 = {
    Text = "als würde sie von etwas geleitet, das älter ist als das Sehen, tiefer als die Sprache."
  },
  AvgDialog_139658_Content_52 = {
    Text = "Du streckst die Hand aus und ergreifst ihre."
  },
  AvgDialog_139658_Content_53 = {
    Text = "Und in dem Moment, als sich eure Handflächen berühren —"
  },
  AvgDialog_139658_Content_54 = {
    Text = "Ein stechender Schmerz explodiert hinter deinen Augen."
  },
  AvgDialog_139658_Content_55 = {
    Text = "Etwas weitaus Schärferes als das — sengend, gleißend — bohrt sich wie ein Blitz durch deinen Schädel und trifft direkt in den tiefsten Kern deines Geistes."
  },
  AvgDialog_139658_Content_56 = {
    Text = "Dein Blickfeld taumelt heftig."
  },
  AvgDialog_139658_Content_57 = {
    Text = "Du siehst feuchte Löwenzahnblüten, die im Sonnenlicht glitzern. Shayes blasses und ruhiges Profil. Das Lächeln, das sich auf ihren aufgesprungenen Lippen kräuselt —"
  },
  AvgDialog_139658_Content_58 = {
    Text = "Und dann schnappt alles in ein Universum aus Fleisch um. Der Himmel wird blutrot. Die Erde wird blutrot. Selbst die Shaye direkt vor dir —"
  },
  AvgDialog_139658_Content_59 = {Text = "Nein—"},
  AvgDialog_139658_Content_6 = {
    Text = "Shaye blickt zum Fenster, ihr Blick trüb und unscharf."
  },
  AvgDialog_139658_Content_60 = {
    Text = "Zwei Welten blitzen auf, überlagern sich und verschmelzen vor deinen Augen. Zwei Flüsse, die sich niemals hätten begegnen sollen, prallen an einer unmöglichen Kreuzung gewaltsam aufeinander."
  },
  AvgDialog_139658_Content_61 = {
    Text = "Die Verbindung zwischen dir und Shaye ist vollständig."
  },
  AvgDialog_139658_Content_7 = {
    Text = "Sonnenlicht fällt in ihre Augen, wie ein Stein in stilles Wasser fällt—und erzeugt keinerlei Wellen."
  },
  AvgDialog_139658_Content_8 = {Text = "Ja."},
  AvgDialog_139658_Content_9 = {
    Text = "Die Worte kommen rau heraus."
  },
  AvgDialog_139659_Content_1 = {Text = "„Liebe\""},
  AvgDialog_139659_Content_10 = {
    Text = "Shaye steht im Löwenzahnfeld, gebadet in Morgenlicht."
  },
  AvgDialog_139659_Content_11 = {
    Text = "Der Regen hat unzählige Samen von ihren Stängeln gelöst. Sie sind auf die karmesinschwarze Erde gefallen – und einige haben, wie durch ein Wunder, bereits begonnen zu keimen."
  },
  AvgDialog_139659_Content_12 = {
    Text = "In einer Nacht geboren, in einer Nacht gewachsen..."
  },
  AvgDialog_139659_Content_13 = {
    Text = "Deinem Gesichtsausdruck nach zu urteilen... ist dir etwas eingefallen?"
  },
  AvgDialog_139659_Content_14 = {
    Text = "Ja. Ich habe einmal einen ähnlichen Anblick in den Wüsten von Aram gesehen."
  },
  AvgDialog_139659_Content_15 = {
    Text = "Das Land dort ist vom Mutterbaum gesegnet. Die Nachkommen seiner Linie schlagen Wurzeln, wo immer sie hinfallen, und wachsen mit dem Wind."
  },
  AvgDialog_139659_Content_16 = {
    Text = "Das klingt schön, nicht wahr?"
  },
  AvgDialog_139659_Content_17 = {
    Text = "...Aber so wie du es gesagt hast, scheinst du das nicht zu finden."
  },
  AvgDialog_139659_Content_18 = {
    Text = "Es steht mir nicht zu, darüber zu urteilen. Ich bin ein Außenstehender in dieser Geschichte."
  },
  AvgDialog_139659_Content_19 = {
    Text = "Es ist nur so... Ich denke, für die meisten Menschen zählt jede Lebensphase."
  },
  AvgDialog_139659_Content_2 = {
    Text = "Du und Shaye kauert euch jeder in eine Ecke der Hütte. Die Nacht vergeht in Stille."
  },
  AvgDialog_139659_Content_20 = {
    Text = "Nefru-Re zum Beispiel. Er hatte nie eine richtige Kindheit. Er wusste nie, was es bedeutet, von einem Elternteil umsorgt zu werden. Er wurde in den Krieg gegen die Sturmwand geworfen, bevor all das geschehen konnte..."
  },
  AvgDialog_139659_Content_21 = {
    Text = "Shaye nickt, nicht ganz sicher, ob sie es versteht."
  },
  AvgDialog_139659_Content_22 = {
    Text = "Also ist für Menschen auch die Länge eines Lebens wichtig?"
  },
  AvgDialog_139659_Content_23 = {
    Text = "Mehr als das. Jede Erfahrung, jeder Mensch, dem du begegnest—sie alle werden Teil der Erinnerungen, die du mit dir trägst."
  },
  AvgDialog_139659_Content_24 = {
    Text = "Diese Erinnerungen, über die Zeit geschichtet, machen einen Menschen zu dem, der er ist."
  },
  AvgDialog_139659_Content_25 = {
    Text = "Man könnte sogar sagen, dass Menschen Gefäße für Erinnerungen sind.\nSelbst nachdem der Körper vergangen ist, lebt die Erinnerung weiter—weitergegeben, bis der letzte Mensch, der sie bewahrt, vergisst."
  },
  AvgDialog_139659_Content_26 = {
    Text = "Ich verstehe... Ich glaube, ich begreife es."
  },
  AvgDialog_139659_Content_27 = {
    Text = "Dann—wenn ich eines Tages sterbe, wird die Erinnerung an heute, daran, so hier mit dir zusammen zu sein, ein Teil von dem, wer du bist?"
  },
  AvgDialog_139659_Content_28 = {Text = "Ja."},
  AvgDialog_139659_Content_29 = {
    Text = "Im Schatten von Shayes zartem Lächeln nickst du entschlossen."
  },
  AvgDialog_139659_Content_3 = {
    Text = "Irgendwann zieht dich die Erschöpfung in einen tiefen Schlummer hinab."
  },
  AvgDialog_139659_Content_30 = {
    Text = "Der Tag vergeht mit Erkundungen und dem Abschreiten der Grenze."
  },
  AvgDialog_139659_Content_31 = {
    Text = "Jenseits des Löwenzahnfeldes wiederholt sich dieselbe trostlose Landschaft in jede Richtung. Die Erde ist unter Fleisch begraben, unkenntlich unter Schichten aus Rot und Schwarz."
  },
  AvgDialog_139659_Content_32 = {
    Text = "Unbehagen wurzelt sich in deiner Brust und schleicht sich in deine Gedanken. Du drückst es nieder."
  },
  AvgDialog_139659_Content_33 = {
    Text = "(Wenn es hier draußen nichts gibt, dann kann der Kern dieser Domäne nur...)"
  },
  AvgDialog_139659_Content_34 = {
    Text = "Die Nacht bricht wieder herein."
  },
  AvgDialog_139659_Content_35 = {
    Text = "Ruh dich aus. Ich bin ein wenig müde."
  },
  AvgDialog_139659_Content_36 = {
    Text = "Gut. Ich würde gerne früh schlafen gehen—je weiter wir morgen erkunden können, desto besser."
  },
  AvgDialog_139659_Content_37 = {
    Text = "Damit schlaft ihr beide ein."
  },
  AvgDialog_139659_Content_38 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_139659_Content_39 = {
    Text = "Etwas weckt dich. Ein Geräusch—oder eine Hitze. Eine Hitze, die unter deine Haut kriecht—als wärst du zurück in der Wüste."
  },
  AvgDialog_139659_Content_4 = {
    Text = "(So kalt... Hoffentlich kann ich morgen in einem richtigen Bett schlafen...)"
  },
  AvgDialog_139659_Content_40 = {Text = "?!!"},
  AvgDialog_139659_Content_41 = {
    Text = "Dein Kopf schwimmt. Du kannst nicht sagen, ob es die unheimliche Szene vor dir ist, oder der Dunst, der durch die Luft wabert."
  },
  AvgDialog_139659_Content_42 = {
    Text = "Oder der Einfluss des Heiligen Flusses."
  },
  AvgDialog_139659_Content_43 = {
    Text = "Wie schade. War ich nicht derjenige, auf den du dich gefreut hast?"
  },
  AvgDialog_139659_Content_44 = {
    Text = "Königin von Aran – Thais zog den Vorhang zurück und trat ein. Sie näherte sich ohne Zögern, der dünne Schleier schmiegte sich an deinen Unterarm und machte eine direkte Einladung."
  },
  AvgDialog_139659_Content_45 = {
    Text = "Komm, akzeptiere das Blut von Arlan und werde einer von uns."
  },
  AvgDialog_139659_Content_46 = {
    Text = "Komm näher, umarme mich... Gib mir dein Blut, dein Wesen..."
  },
  AvgDialog_139659_Content_47 = {
    Text = "Die Flammen flackern in ihren leidenschaftlichen Pupillen, ihre geröteten Wangen offenbaren ein morbidens Verlangen."
  },
  AvgDialog_139659_Content_48 = {
    Text = "Ein einziger Tropfen reicht aus. Solange unser Knochenfleisch verschmilzt, wird Er uns die Zukunft gewähren, die wir uns wünschen..."
  },
  AvgDialog_139659_Content_49 = {
    Text = "Lass uns... Nachkommen für den Stamm zeugen, teilend in der Ewigkeit..."
  },
  AvgDialog_139659_Content_5 = {
    Text = "Etwas legt sich in der Dunkelheit über dich."
  },
  AvgDialog_139659_Content_50 = {
    Text = "Du zerrst deinen Verstand aus irgendeiner Tiefe hervor und kämpfst gegen den Sog ihrer Worte an. Die Glocke, die dich einst als Schutzherr erweckte, bleibt stumm."
  },
  AvgDialog_139659_Content_51 = {
    Text = "Und dann—eine andere Stimme durchschneidet alles."
  },
  AvgDialog_139659_Content_52 = {
    Text = "Warum? Warum weigerst du dich immer wieder?"
  },
  AvgDialog_139659_Content_53 = {
    Text = "Sie ist lautlos aus einer Ecke des Zeltes aufgetaucht."
  },
  AvgDialog_139659_Content_54 = {
    Text = "Ihre Stimme klingt anders als sonst. Etwas Schwereres lauert unter ihren Worten, etwas, das du nicht recht benennen kannst."
  },
  AvgDialog_139659_Content_55 = {
    Text = "Fortpflanzung... Ich finde, das ist etwas Gutes. Der Zweck aller Lebewesen..."
  },
  AvgDialog_139659_Content_56 = {
    Text = "Aber warum willst du es nicht annehmen?"
  },
  AvgDialog_139659_Content_57 = {
    Text = "Warum? Warum weigerst du dich immer wieder?"
  },
  AvgDialog_139659_Content_58 = {
    Text = "Weil das nichts mit Liebe zu tun hat. Das ist nur Versuchung."
  },
  AvgDialog_139659_Content_59 = {
    Text = "Versuchung ist keine Liebe. Pflicht ist keine Liebe. Begierde ist keine Liebe."
  },
  AvgDialog_139659_Content_6 = {Text = "...Hmm?"},
  AvgDialog_139659_Content_60 = {
    Text = "Liebe ist —"
  },
  AvgDialog_139659_Content_61 = {
    Text = "Liebe ist —"
  },
  AvgDialog_139659_Content_62 = {
    Text = "Die Welt erlischt."
  },
  AvgDialog_139659_Content_63 = {
    Text = "Alles versinkt in einer langen, lichtlosen Dunkelheit."
  },
  AvgDialog_139659_Content_7 = {
    Text = "Eine dünne Decke wurde über dich gebreitet."
  },
  AvgDialog_139659_Content_8 = {
    Text = "Der Himmel hat sich aufgeklart."
  },
  AvgDialog_139659_Content_9 = {
    Text = "Zeit, nach draußen zu gehen."
  },
  AvgDialog_139660_Content_1 = {
    Text = "„Erinnerung\""
  },
  AvgDialog_139660_Content_10 = {
    Text = "Und du hast recht, ich bin nicht gerade gewöhnlich. Ich bin ein Ermittler der Misaq Universität."
  },
  AvgDialog_139660_Content_11 = {
    Text = "Shaye blickt verwirrt drein—offensichtlich sagen ihr diese Begriffe nichts."
  },
  AvgDialog_139660_Content_12 = {
    Text = "Es ist eine lange Geschichte. Im Moment muss ich mich um etwas Dringenderes kümmern."
  },
  AvgDialog_139660_Content_13 = {
    Text = "Meine Partnerin, Ramona. Ich habe gesehen, wie etwas sie verschlungen hat. Sie wurde—"
  },
  AvgDialog_139660_Content_14 = {
    Text = "Du sprichst nicht zu Ende. Du kannst nicht."
  },
  AvgDialog_139660_Content_15 = {
    Text = "Worte sind nur hohle Symbole. Sie können nicht tragen, was du in diesem Moment empfunden hast—die Angst, die dir vom Rückenmark aus hochkroch."
  },
  AvgDialog_139660_Content_16 = {
    Text = "Die Angst, Ramona für immer zu verlieren."
  },
  AvgDialog_139660_Content_17 = {
    Text = "Sie ist unersetzlich für mich."
  },
  AvgDialog_139660_Content_18 = {
    Text = "Shayes Blick wird für einen Moment abwesend."
  },
  AvgDialog_139660_Content_19 = {
    Text = "Unersetzlich... Ich verstehe."
  },
  AvgDialog_139660_Content_2 = {
    Text = "Bevor du deine Fragen ordnen kannst, spricht sie zuerst."
  },
  AvgDialog_139660_Content_20 = {
    Text = "Ich glaube, ich hatte auch... so jemanden."
  },
  AvgDialog_139660_Content_21 = {
    Text = "Sie blickt nach unten, die Stirn gerunzelt, und murmelt vor sich hin."
  },
  AvgDialog_139660_Content_22 = {
    Text = "Da war jemand. Eine sehr wichtige Person. Ich sollte mich an sein Gesicht erinnern... Ich muss mich daran erinnern. Aber wenn ich jetzt versuche, ihn mir vorzustellen, sehe ich nur—"
  },
  AvgDialog_139660_Content_23 = {
    Text = "—nur einen Umriss. Als würde man durch Milchglas schauen. Ich weiß, dass er da war. Ich weiß, dass er wichtig war. Aber alle Details sind... verwischt worden."
  },
  AvgDialog_139660_Content_24 = {
    Text = "Es ist nicht nur er. Alles andere ist genauso. Ich weiß, dass es etwas gibt, das ich tun muss—etwas Wichtiges."
  },
  AvgDialog_139660_Content_25 = {
    Text = "Aber die Erinnerungen bekämpfen sich gegenseitig. Eine sagt, er war sanft; die nächste sagt, ich war lange Zeit irgendwo sehr dunkel. Eine sagt, ich wartete darauf, dass jemand zu mir kommt; eine andere sagt, ich musste etwas tun... das Menschen erschrecken würde."
  },
  AvgDialog_139660_Content_26 = {
    Text = "Jedes Stück fühlt sich real an. Aber sie passen einfach nicht zusammen."
  },
  AvgDialog_139660_Content_27 = {
    Text = "Jedes Bruchstück fühlt sich echt an. Aber sie passen einfach nicht zusammen."
  },
  AvgDialog_139660_Content_28 = {
    Text = "Du hast diesen Zustand schon einmal gesehen."
  },
  AvgDialog_139660_Content_29 = {
    Text = "Ich weiß nicht, welche Teile wirklich passiert sind. Ich weiß nicht, welche Erinnerungen wirklich meine sind..."
  },
  AvgDialog_139660_Content_3 = {
    Text = "Ich bin... hmm, du kannst mich Shaye nennen.\nWeißt du, wo wir sind?"
  },
  AvgDialog_139660_Content_30 = {
    Text = "Ich weiß nicht, welche Teile wirklich passiert sind. Ich weiß nicht, welche Erinnerungen wirklich meine sind..."
  },
  AvgDialog_139660_Content_31 = {
    Text = "Shayes Finger krümmen sich nach innen, als versuchte sie, etwas zu greifen, das nicht mehr existiert."
  },
  AvgDialog_139660_Content_32 = {
    Text = "Während sie schwankt, beginnt sich die Welt um dich herum zu verändern."
  },
  AvgDialog_139660_Content_33 = {Text = "Vorsicht!"},
  AvgDialog_139660_Content_34 = {
    Text = "Du blickst zum Rand des Löwenzahnfeldes. Die fleischige Membran, getränkt in schwarzem Schleim, drückt Stück für Stück nach innen. Die Grenze wirkt weniger beständig als zuvor."
  },
  AvgDialog_139660_Content_4 = {
    Text = "Warum bin ich an einem Ort wie diesem...\nHmm—es gibt so vieles, an das ich mich nicht erinnern kann."
  },
  AvgDialog_139660_Content_5 = {
    Text = "...Du bist keine gewöhnliche Person, oder?\nHast du irgendeine besondere Fähigkeit...?"
  },
  AvgDialog_139660_Content_6 = {
    Text = "Du antwortest nicht sofort. Das Mädchen namens Shaye lässt deine Hand los, tritt einen halben Schritt zurück, und ihre Augen verengen sich, während sie dich mustert."
  },
  AvgDialog_139660_Content_7 = {
    Text = "Du hast mich gesehen und nichts gespürt? Warum bist du hergekommen?"
  },
  AvgDialog_139660_Content_8 = {
    Text = "Warte, eine Frage nach der anderen."
  },
  AvgDialog_139660_Content_9 = {
    Text = "Soweit ich das beurteilen kann, ist dies höchstwahrscheinlich eine Domäne."
  },
  AvgDialog_139661_Content_1 = {
    Text = "Mentale Landschaft"
  },
  AvgDialog_139661_Content_10 = {
    Text = "Ein schönes Mädchen und ein junger Mann."
  },
  AvgDialog_139661_Content_11 = {
    Text = "Hand in Hand gehen sie gemeinsam durch die heulende Einöde."
  },
  AvgDialog_139661_Content_12 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_139661_Content_13 = {
    Text = "Sie kichert und breitet die Arme aus, um den Wind zu umarmen."
  },
  AvgDialog_139661_Content_14 = {
    Text = "Der junge Mann neben ihr beugt sich vor und lauscht aufmerksam jedem ihrer lieblichen Worte."
  },
  AvgDialog_139661_Content_15 = {
    Text = "Der Himmel ist klar, doch von einer stillen Melancholie durchzogen."
  },
  AvgDialog_139661_Content_16 = {
    Text = "Doch in ihrer gemeinsamen Silhouette erkennst du einen Hauch stiller, ungebetener Freude."
  },
  AvgDialog_139661_Content_17 = {
    Text = "Selbst wenn niemand sonst in der Nähe war, selbst wenn sie von niemandem Verständnis oder Segen erhielten, war ihre Liebe dennoch—"
  },
  AvgDialog_139661_Content_18 = {
    Text = "Dann bricht der Traum ab. Der Sandsturm fegt alles hinweg."
  },
  AvgDialog_139661_Content_19 = {
    Text = "Die Welt stürzt in leeres Schwarz."
  },
  AvgDialog_139661_Content_2 = {
    Text = "Die Welt besteht aus Sand."
  },
  AvgDialog_139661_Content_20 = {
    Text = "—Es war einmal eine Sängerin, die sich ihren Weg zwischen den Sternen bahnte."
  },
  AvgDialog_139661_Content_21 = {
    Text = "In einem kargen und trostlosen Universum fand sie einen Silberkern, der im Staub lag."
  },
  AvgDialog_139661_Content_22 = {
    Text = "In dem Moment, als sie ihn berührte, erwachte „Ich\"."
  },
  AvgDialog_139661_Content_23 = {
    Text = "„Ich\" hatte alle Erinnerungen verloren. Doch „Ich\" wusste eines: Ich musste diese „unersetzliche Person„ finden."
  },
  AvgDialog_139661_Content_24 = {
    Text = "„Ich\" fragte die Sängerin, ob wir zusammen reisen könnten, doch die Bitte wurde abgelehnt."
  },
  AvgDialog_139661_Content_25 = {
    Text = "Ich werde diejenige finden, die mir die Welt bedeutet — meine Schwester."
  },
  AvgDialog_139661_Content_26 = {
    Text = "Das waren ihre Worte."
  },
  AvgDialog_139661_Content_27 = {
    Text = "Ich hoffe, auch du findest deine Liebe, Shaye. Ich wünsche dir von Herzen ein glückliches Ende."
  },
  AvgDialog_139661_Content_28 = {
    Text = "Mit diesen Worten ging die Sängerin fort."
  },
  AvgDialog_139661_Content_29 = {
    Text = "Und so, ohne meine Vergangenheit und nun auch ohne die Sängerin,"
  },
  AvgDialog_139661_Content_3 = {
    Text = "Inmitten der Winde, die diese Wüste seit Ewigkeiten durchfegen, stehst du verloren da und blickst über alles hinweg."
  },
  AvgDialog_139661_Content_30 = {
    Text = "trug ich ihren Segen bei mir, als ich allein durch diese Welt wanderte."
  },
  AvgDialog_139661_Content_31 = {
    Text = "Um die einst unersetzliche Person zu finden... um zusammenzusetzen, was ich verloren hatte..."
  },
  AvgDialog_139661_Content_32 = {
    Text = "Ich ging immer weiter, im Glauben, dass das, wonach ich suchte, direkt vor mir wartete."
  },
  AvgDialog_139661_Content_33 = {
    Text = "Bis ich schließlich... dich traf."
  },
  AvgDialog_139661_Content_4 = {
    Text = "Hier ist..."
  },
  AvgDialog_139661_Content_5 = {
    Text = "Kein Schlamm der Auflösung. Keine wuchernden Massen aus Blut und Fleisch."
  },
  AvgDialog_139661_Content_6 = {
    Text = "Die Landschaft hier ist einsam, rein und wunderschön."
  },
  AvgDialog_139661_Content_7 = {
    Text = "Hier ist meine Mentale Landschaft."
  },
  AvgDialog_139661_Content_8 = {
    Text = "Ein Fragment meiner Existenz – etwas Unersetzliches, etwas, das niemals vergessen werden sollte..."
  },
  AvgDialog_139661_Content_9 = {
    Text = "Der Sand verschiebt sich und rollt, und in der fernen Ecke der Wüste tauchen zwei Gestalten auf."
  },
  AvgDialog_139662_Content_10 = {
    Text = "Ich werde Ihr Assistent sein und Sie bis zum Ende dieses Pfades begleiten... <Yellow:Möge der Silberne Schlüssel Ihren Weg erleuchten.>"
  },
  AvgDialog_139662_Content_11 = {
    Text = [[
Alles in Ordnung, %player%?
Seit einer Weile siehst du blass aus. Soll ich dich ins Krankenzimmer bringen?]]
  },
  AvgDialog_139662_Content_12 = {Text = "Ramona..."},
  AvgDialog_139662_Content_13 = {
    Text = "Der Name bleibt dir im Hals stecken. Du kannst dich nicht überwinden, ihren Namen auszusprechen — den Namen, den du so gut kennst."
  },
  AvgDialog_139662_Content_16 = {
    Text = "<Red:Nein, nein, nein, nein. Nichts davon stimmt.>"
  },
  AvgDialog_139662_Content_18 = {
    Text = "<Shake:Nein, das ist nicht Ramona — Ramona wäre kein hässlicher, verzerrter Fleischklumpen, würde kein derart widerliches Stöhnen von sich geben, würde nicht von pechschwarzem A-Schleim überströmt sein......>"
  },
  AvgDialog_139662_Content_19 = {
    Text = "<Red:Würde mich nicht mit diesen pechschwarzen, leeren Augen unverwandt anstarren —>"
  },
  AvgDialog_139662_Content_2 = {
    Text = "Blut und Fleisch"
  },
  AvgDialog_139662_Content_20 = {Text = "Nein—!"},
  AvgDialog_139662_Content_21 = {
    Text = "War das... ein Traum?"
  },
  AvgDialog_139662_Content_22 = {
    Text = "Du schreckst hoch, in kalten Schweiß gebadet."
  },
  AvgDialog_139662_Content_23 = {
    Text = "Was für ein seltsamer Traum. Selbst im Wachen verweilt er noch in meinem Blickfeld."
  },
  AvgDialog_139662_Content_24 = {
    Text = "Was du siehst... ist..."
  },
  AvgDialog_139662_Content_25 = {Text = "Ist..."},
  AvgDialog_139662_Content_26 = {
    Text = "<Shake:<Red:Fleischklumpen, große, aufeinandergestapelte und übereinanderliegende Fleischklumpen.>>"
  },
  AvgDialog_139662_Content_27 = {
    Text = "Blutrote, sich windende Eingeweide, die die Wände überziehen, die Säulen umschlingen, über die Fenster kriechen.\nUnd zwischen den Rissen des Fleisches—"
  },
  AvgDialog_139662_Content_28 = {
    Text = "Schwarze Flüssigkeit sickert heraus."
  },
  AvgDialog_139662_Content_29 = {
    Text = "Auflösung."
  },
  AvgDialog_139662_Content_3 = {
    Text = "Pain. Brennender Pain. Ein dunkles Karmesinrot flutet deine Netzhäute."
  },
  AvgDialog_139662_Content_30 = {
    Text = "Du hast Auflösung schon gesehen. Zu oft. Aber nie so—zwei verschiedene Leiden, die gleichzeitig durch einen einzigen Körper wüten."
  },
  AvgDialog_139662_Content_31 = {Text = "Ramona..."},
  AvgDialog_139662_Content_32 = {
    Text = "Das Bild blendet erneut zurück. Pechschwarze, leere Augenhöhlen. Verzerrte, aufgeblähte Konturen. Ihre Finger verwandeln sich in Deiner Handfläche in <Shake:unregelmäßige Fleischwucherungen> —"
  },
  AvgDialog_139662_Content_33 = {
    Text = "Nein—hör auf. Hör auf zu denken—"
  },
  AvgDialog_139662_Content_34 = {
    Text = "Sie ist noch da draußen—sie muss irgendwo sein—"
  },
  AvgDialog_139662_Content_35 = {
    Text = "Ein schwaches Zittern durchzieht deinen Geist. Kaum wahrnehmbar."
  },
  AvgDialog_139662_Content_36 = {
    Text = "Instinktiv greifst du nach der Quelle—es ist nicht Ramona. Du könntest Ramona mit geschlossenen Augen erkennen; ihre Geistwellen ruhig und sanft, wie die Oberfläche eines stillen Sees."
  },
  AvgDialog_139662_Content_37 = {
    Text = "Geh nach Osten..."
  },
  AvgDialog_139662_Content_38 = {Text = "Wer?"},
  AvgDialog_139662_Content_39 = {
    Text = "Keine Antwort."
  },
  AvgDialog_139662_Content_4 = {
    Text = "Mein Kopf..."
  },
  AvgDialog_139662_Content_40 = {
    Text = "Ohne weitere Hinweise bewegst du dich in Richtung des Geräuschs."
  },
  AvgDialog_139662_Content_41 = {
    Text = "Du überquerst einen Fluss, der nach Rost und Verwesung stinkt. Du steigst über eine membranartige Erde, durchzogen von dunkelroten Sehnen."
  },
  AvgDialog_139662_Content_42 = {
    Text = "Dein Atem wird schwer; deine Nerven pochen unter dem Vordringen dieser unheimlichen Farben."
  },
  AvgDialog_139662_Content_43 = {
    Text = "Jemand... irgendjemand... holt mich aus diesem Traum..."
  },
  AvgDialog_139662_Content_44 = {
    Text = "Es muss ein Traum sein. Das Gefühl ist zu real—aber du musst es glauben. Du musst."
  },
  AvgDialog_139662_Content_45 = {
    Text = "Etwas Weiches, Weißes schwebt auf deine Nasenspitze."
  },
  AvgDialog_139662_Content_46 = {
    Text = "Eine Pusteblume...?"
  },
  AvgDialog_139662_Content_47 = {
    Text = "Du trittst auf eine Grenze. Eine sichtbare—eine klare, unverkennbare Linie, die zwei Welten teilt."
  },
  AvgDialog_139662_Content_48 = {
    Text = "Dahinter: übelkeitserregendes Fleisch und aufwallender schwarzer Schlamm."
  },
  AvgDialog_139662_Content_49 = {
    Text = "Darin: ein kleines Feld voller Pusteblumen. In seiner Mitte eine kleine Holzhütte."
  },
  AvgDialog_139662_Content_5 = {
    Text = "Flackerndes, schwaches Licht, ein summendes Klingeln hallt in deinen Trommelfellen. Dieser Welt kann man nicht trauen. Alles, was man sieht, ist nur eine Illusion."
  },
  AvgDialog_139662_Content_50 = {
    Text = "Etwas regt sich im Pusteblumenfeld."
  },
  AvgDialog_139662_Content_51 = {
    Text = "Du folgst der Bewegung. Ein weißer Flaum wird beiseitegeschoben und enthüllt eine Ecke blassen Stoffs."
  },
  AvgDialog_139662_Content_52 = {
    Text = "Dann steht sie auf."
  },
  AvgDialog_139662_Content_53 = {
    Text = "Ein Mädchen, zerbrechlich und leicht wie eine Pusteblume."
  },
  AvgDialog_139662_Content_54 = {
    Text = "Sie neigt den Kopf und beobachtet deinen Gesichtsausdruck."
  },
  AvgDialog_139662_Content_55 = {
    Text = "Hast du keine Angst vor mir?"
  },
  AvgDialog_139662_Content_56 = {
    Text = "Es ist fast ironisch. Nach allem, was du durchschritten hast, ist sie der einzige normale Mensch, den du gesehen hast. Die einzige Existenz, die nicht beängstigend ist."
  },
  AvgDialog_139662_Content_57 = {
    Text = "Dann... möchtest du mir die Hand geben?"
  },
  AvgDialog_139662_Content_58 = {Text = "Hm? Warum?"},
  AvgDialog_139662_Content_59 = {
    Text = "Hmm... Ich habe einfach das Gefühl, dass ich es tun sollte."
  },
  AvgDialog_139662_Content_6 = {
    Text = "Wach auf. Wach jetzt auf..."
  },
  AvgDialog_139662_Content_60 = {
    Text = "Was den Grund angeht... ich kann mich nicht ganz erinnern."
  },
  AvgDialog_139662_Content_61 = {
    Text = "Außerdem..."
  },
  AvgDialog_139662_Content_62 = {
    Text = "Das Mädchen neigt den Kopf, ein verspieltes Lächeln ziert ihre Lippen."
  },
  AvgDialog_139662_Content_63 = {
    Text = "Du willst mich auch berühren, oder?"
  },
  AvgDialog_139662_Content_64 = {
    Text = "Ja. Natürlich willst du das."
  },
  AvgDialog_139662_Content_65 = {
    Text = "Nach allem—der Dunkelheit, dem Gestank, dem abstoßenden Sinnesangriff—wie könntest du nicht den ersten lebenden Menschen berühren wollen, den du gefunden hast?"
  },
  AvgDialog_139662_Content_66 = {
    Text = "Du streckst die Hand aus und berührst ihre schlanken, weichen Finger."
  },
  AvgDialog_139662_Content_67 = {
    Text = "So ein seltsames Gefühl..."
  },
  AvgDialog_139662_Content_68 = {
    Text = "Ja. Du spürst es auch. Neben menschlicher Wärme gibt es eine schwache Empfindung, wie ein schwacher elektrischer Strom, der euch verbindet."
  },
  AvgDialog_139662_Content_69 = {
    Text = "Es ist die Resonanz von Silberkernen."
  },
  AvgDialog_139662_Content_7 = {
    Text = "Willkommen an der Mythag Universität, %player%."
  },
  AvgDialog_139662_Content_8 = {
    Text = "Oder vielmehr... willkommen, du hast offiziell die verborgene Seite der Welt betreten."
  },
  AvgDialog_139662_Content_9 = {
    Text = "(Bin ich... zurück?)"
  },
  AvgDialog_139663_Content_1 = {
    Text = "Diese Dinge sind..."
  },
  AvgDialog_139663_Content_10 = {
    Text = "Wenn sie gewöhnlich ist... wird sie wahrscheinlich nicht mit mir sprechen können."
  },
  AvgDialog_139663_Content_11 = {
    Text = "Da du ein Erwecker bist, könnte ich vielleicht eine Verbindung zu dir herstellen. Durch Traumresonanz könntest du sehen, wie Ramona aussieht."
  },
  AvgDialog_139663_Content_12 = {
    Text = "Vielleicht kann sie der Schlüssel sein, um deine Erinnerungen aufzudecken."
  },
  AvgDialog_139663_Content_13 = {
    Text = "Du nimmst Shayes Hand erneut. Du suchst in deinem Inneren, zeichnest die Gestalt von Ramona in deinem Geist nach—ihre Stimme, ihr Gesicht—in der Hoffnung, dass die schwache Verbindung zwischen euch es hinübertragen kann."
  },
  AvgDialog_139663_Content_14 = {
    Text = "<Italic:Knack>. Die Verbindung bricht ab."
  },
  AvgDialog_139663_Content_15 = {
    Text = "Es fühlt sich an, als würde eine formlose Wand unsere Verbindung blockieren..."
  },
  AvgDialog_139663_Content_16 = {
    Text = "Es fühlt sich an, als würde eine formlose Wand unsere Verbindung blockieren..."
  },
  AvgDialog_139663_Content_17 = {
    Text = "Vielleicht hängt es damit zusammen, was ich tun muss. Ich habe das Gefühl... dass es etwas Verbotenes ist. Etwas, das ich nicht jedem sagen kann."
  },
  AvgDialog_139663_Content_18 = {
    Text = "Sieht aus, als käme ein Sturm. Lass uns eine Weile drinnen ausruhen."
  },
  AvgDialog_139663_Content_19 = {
    Text = "Aus den Ritzen der Holzplanken schwebt gelegentlich schwarzer Schleim nach oben, der Schwerkraft trotzend."
  },
  AvgDialog_139663_Content_2 = {
    Text = "Ich weiß es auch nicht. Aber ich habe das Gefühl... die Antwort liegt irgendwo in meinen Erinnerungen."
  },
  AvgDialog_139663_Content_20 = {
    Text = "Shaye kauert sich in eine Ecke, die untere Hälfte ihres Gesichts an ihre Arme geschmiegt. Sie fragt leise—"
  },
  AvgDialog_139663_Content_21 = {
    Text = "Das ist das, was du „Auflösung“ genannt hast, nicht wahr?"
  },
  AvgDialog_139663_Content_22 = {Text = "Du nickst."},
  AvgDialog_139663_Content_23 = {
    Text = "Ist es das, was mir meine Erinnerungen genommen hat?"
  },
  AvgDialog_139663_Content_24 = {
    Text = "Ja. Und nicht nur dir, unzählige Menschen haben durch die Auflösung wichtige Erinnerungen verloren."
  },
  AvgDialog_139663_Content_25 = {
    Text = "Manche vergaßen die Gesichter ihrer Liebsten. Sie suchten jahrelang—und manchmal verletzten sie bei dieser Suche genau diejenigen, die sie vermissen."
  },
  AvgDialog_139663_Content_26 = {
    Text = "Manche vergaßen die Städte, in denen sie geboren wurden. Sie trieben allein über den Ozean, einer Vergangenheit nachjagend, zu der sie nie zurückkehren können."
  },
  AvgDialog_139663_Content_27 = {
    Text = "...Kostbare Erinnerungen zu verlieren muss sehr schmerzhaft sein."
  },
  AvgDialog_139663_Content_28 = {
    Text = "Shaye blickt hinaus auf den Regen, der in dünnen, gleichmäßigen Linien fällt—als könnte das Wasser den schwarzen Schmutz abwaschen."
  },
  AvgDialog_139663_Content_29 = {
    Text = "Ich frage mich... was sind die wichtigen Dinge, die in meinen Erinnerungen verborgen liegen?"
  },
  AvgDialog_139663_Content_3 = {
    Text = "Ich werde einen Weg finden, dich aus dieser Domäne herauszuholen. Wir werden deine Erinnerungen wiederherstellen."
  },
  AvgDialog_139663_Content_30 = {
    Text = "Ich frage mich... was sind die wichtigen Dinge, die in meinen Erinnerungen verborgen sind?"
  },
  AvgDialog_139663_Content_31 = {
    Text = "Du bleibst still."
  },
  AvgDialog_139663_Content_32 = {
    Text = "Draußen fällt der Regen weiter, gleichmäßig und sanft."
  },
  AvgDialog_139663_Content_4 = {Text = "Aber ..."},
  AvgDialog_139663_Content_5 = {
    Text = "Du willst zuerst Ramona finden, oder?"
  },
  AvgDialog_139663_Content_6 = {
    Text = "Um ehrlich zu sein... ich glaube, ich erinnere mich, dass ich einmal jemandem begegnet bin, und dann..."
  },
  AvgDialog_139663_Content_7 = {
    Text = "Ehrlich gesagt... ich glaube, ich erinnere mich daran, einmal jemanden getroffen zu haben, und dann..."
  },
  AvgDialog_139663_Content_8 = {
    Text = "Wie auch immer. Diese Ramona—ist sie... anders, so wie du?"
  },
  AvgDialog_139663_Content_9 = {
    Text = "Wenn sie gewöhnlich ist... kann sie wahrscheinlich nicht mit mir sprechen."
  },
  AvgDialog_141373_Content_1 = {
    Text = "Dies ist nicht dein erstes Mal in Ebwynnos, doch noch nie waren diese gesichtslosen Wesen so unruhig wie heute."
  },
  AvgDialog_141373_Content_10 = {
    Text = "Warte, du bist ... warum bist du überhaupt hier?"
  },
  AvgDialog_141373_Content_11 = {
    Text = "Schrilles weißes Rauschen verschluckte das Bewusstsein, und eine uralte, unsichtbare Flut zwang dich, benommen den Kopf zu heben und das Einzige anzusehen, das du noch erkennen konntest."
  },
  AvgDialog_141373_Content_12 = {
    Text = "Stimmt, das alles spielt keine Rolle – wer du bist, was du vorhast, Der Grund, warum du hierher gekommen bist."
  },
  AvgDialog_141373_Content_13 = {
    Text = "Die tiefe Stimme verdrängt das Rauschen des Meeres, und der Ältere verengt die Jagd von oben herab."
  },
  AvgDialog_141373_Content_14 = {
    Text = "Du bist in Sicherheit. Willkommen zurück."
  },
  AvgDialog_141373_Content_15 = {
    Text = "Oh... stimmt, Ebwynnos, ich bin nach Ebwynnos zurückgekehrt."
  },
  AvgDialog_141373_Content_16 = {
    Text = "Du murmelst es nach, ohne es zu merken, steigen deine Mundwinkel, und alles, was danach folgt, wirkt wie eine Selbstverständlichkeit."
  },
  AvgDialog_141373_Content_17 = {
    Text = "Nun gut, ich gebe zu, das verstößt ein wenig gegen die Regeln, aber keine Sorge – ich bringe dich zurück nach Misaq."
  },
  AvgDialog_141373_Content_18 = {
    Text = "Der Abgrund hat dich bereits eingehüllt, und dein Zerbrechlicher Verstand ist durch die wiederholten Erschütterungen völlig außerstande, das zu begreifen, was der andere darlegt."
  },
  AvgDialog_141373_Content_19 = {Text = "Was?"},
  AvgDialog_141373_Content_2 = {
    Text = "Hey, hey! Hört auf, ich bin kein Fein..."
  },
  AvgDialog_141373_Content_20 = {
    Text = "Ein heiseres, kurzes Lachen."
  },
  AvgDialog_141373_Content_21 = {
    Text = "Gerade nicht jetzt."
  },
  AvgDialog_141373_Content_22 = {
    Text = "Feuchtigkeit, Chaos, Enge – sie füllen dich bis zum Rand, und dann lassen sie dich in Wellen immer tiefer versinken; du verlierst jede Kontrolle."
  },
  AvgDialog_141373_Content_23 = {
    Text = "An deinem Ohr bleibt nur noch ein Flüstern, durchsetzt von Atemzügen."
  },
  AvgDialog_141373_Content_24 = {
    Text = "Jetzt gehörst du hierher, gehörst du mir, gehörst du Ebwynnos."
  },
  AvgDialog_141373_Content_25 = {
    Text = "Du verstehst es nicht – du folgst Gerade in deiner Freude dem uralten Meer."
  },
  AvgDialog_141373_Content_26 = {
    Text = "Er zeigt keinerlei Anzeichen, innezuhalten."
  },
  AvgDialog_141373_Content_3 = {Text = "*Jagdpfiff"},
  AvgDialog_141373_Content_4 = {
    Text = "Der Angriff hörte auf — doch die Dunkelheit erfasste dich unvermittelt. Fast im selben Augenblick warf dich die erstarrte Stille in einen unaussprechlichen Strudel."
  },
  AvgDialog_141373_Content_5 = {Text = "Hm?"},
  AvgDialog_141373_Content_6 = {Text = "Ah..."},
  AvgDialog_141373_Content_7 = {
    Text = "Als ob er sich von etwas überzeugen wollte, ignorierte er das Schaudern, das dein Körper durch den plötzlichen Schrecken ausgelöst hatte, und fuhr mit unbestreitbarer Geste über deine Augenbrauen, deinen Augenwinkel und schließlich die Seite deines Halses."
  },
  AvgDialog_141373_Content_8 = {
    Text = "Zu dieser Zeit Ebwynnos aufzusuchen ist keine gute Idee, %player%."
  },
  AvgDialog_141373_Content_9 = {
    Text = "<Small:Ich wollte nur ...>"
  },
  AvgDialog_142850_Content_1 = {
    Text = "Erster Abschnitt"
  },
  AvgDialog_142850_Content_10 = {
    Text = "Varo ... gib auf! Wir sind so viele – du kannst diesen Wald unmöglich lebend verlassen!"
  },
  AvgDialog_142850_Content_100 = {
    Text = "Es war eine Geschwindigkeit und Stärke, der er nichts entgegensetzen konnte. Varro hob seine verwirrten Augen und blickte Lotan ratlos an."
  },
  AvgDialog_142850_Content_101 = {
    Text = "Du... hast versprochen..."
  },
  AvgDialog_142850_Content_102 = {
    Text = "Ich habe versprochen, dich in mein Team aufzunehmen. Aber ich habe nicht gesagt, dass du dabei am Leben bleibst."
  },
  AvgDialog_142850_Content_103 = {
    Text = "Schwäche ist nicht deine Schuld. Aber dein Herz ist nicht rein, Krieger."
  },
  AvgDialog_142850_Content_104 = {
    Text = "Lotan nimmt die beiden Knochensiegel aus Varros Hand und wirft seine Leiche – das Gesicht noch immer in Verwirrung erstarrt – auf den Haufen der zwölf toten Ritter, wie weggeworfenen Unrat."
  },
  AvgDialog_142850_Content_105 = {
    Text = "Sie blickt zum Unterholz hinüber, hebt ihr Großschwert und ist bereit, das übrige Siegel zu zerschlagen..."
  },
  AvgDialog_142850_Content_106 = {
    Text = "Warte!! —"
  },
  AvgDialog_142850_Content_107 = {
    Text = "Lotans Klinge hält mitten in der Luft inne. Mit kühler Gleichgültigkeit beobachtet sie, wie du aus dem Gebüsch kriechst."
  },
  AvgDialog_142850_Content_108 = {
    Text = "Ich habe kein Interesse an allzu schwachen Gegnern."
  },
  AvgDialog_142850_Content_109 = {
    Text = "Kleiner Squire der Ritterschaft, wenn ich Du wäre, würde ich fliehen, bevor der andere es sich anders überlegt — so schnell wie möglich."
  },
  AvgDialog_142850_Content_11 = {
    Text = "Gib dein Knochensiegel heraus, wir garantieren, garantieren dir, dass du sicher gehen kannst!"
  },
  AvgDialog_142850_Content_110 = {
    Text = "Herr Elian hat die Ritterschaft beauftragt, ihm die Krone zu bringen. Wenn... wenn er herausfindet, dass ich geflohen bin, wird meine ganze Familie sterben..."
  },
  AvgDialog_142850_Content_111 = {
    Text = "Du fasst all deinen Mut zusammen und machst einen Schritt in Lotans Richtung."
  },
  AvgDialog_142850_Content_112 = {
    Text = "Ihr habt noch ein Knochensiegel... Ich bitte Euch, lasst mich ebenfalls in die Arena des Sternenhimmels-Wals gehen, bitte? Ich muss nur dorthin gelangen, dann ist mein Auftrag erfüllt... Ihr seid so stark, ich wäre keine Bedrohung für Euch..."
  },
  AvgDialog_142850_Content_113 = {Text = "Du?"},
  AvgDialog_142850_Content_114 = {
    Text = "Lotan hob eine Augenbraue und sah Dich spöttisch an."
  },
  AvgDialog_142850_Content_115 = {
    Text = "Deine Stärke reicht nicht einmal an die Versager heran, die Varo getötet hat. In dem Moment, in dem Du die Arena betrittst, wirst Du sterben wie ein Wurm."
  },
  AvgDialog_142850_Content_116 = {
    Text = "Geh jetzt, und Du hast noch eine Chance zu überleben."
  },
  AvgDialog_142850_Content_117 = {
    Text = "Du blickst auf die Leichen, die überall verstreut liegen, und auf die Gestalt vor Dir, die Dir tief in deinem Inneren Angst einflößt, und schluckst mühsam."
  },
  AvgDialog_142850_Content_118 = {
    Text = "Du weißt, dass der Sieg nie dir gehören konnte. Jeder Instinkt schreit dir zu, vor diesem Monster zu fliehen, so weit wie möglich wegzulaufen."
  },
  AvgDialog_142850_Content_119 = {
    Text = "Du willst deine Mutter vergessen, die dem Astralen Cetus lebendig geopfert wurde. Du willst deine Geschwister vergessen, die wie Vieh in den Ställen eingesperrt waren. Du willst einfach nur überleben."
  },
  AvgDialog_142850_Content_12 = {
    Text = "Er hat recht, Varo! Selbst wenn du der stärkste Söldner der sechs Nationen bist, kannst du dir keinen Vorteil verschaffen, wenn du von uns dreizehn umzingelt bist."
  },
  AvgDialog_142850_Content_120 = {
    Text = "Aber es geht nicht — Du kannst es nicht vergessen. So wie Du an diesem Wettkampf teilnimmst, bei dem Du von Anfang an als Kanonenfutter vorgesehen bist, hattest Du nie die Wahl."
  },
  AvgDialog_142850_Content_121 = {
    Text = "Ich bin der Wegweiser der Gruppe und kenne den Weg zur Arena. Ich war viele, viele Jahre lang Squire — ich weiß, wie man einem Krieger dient! Ich bin sehr nützlich, Ihr werdet mich brauchen..."
  },
  AvgDialog_142850_Content_122 = {
    Text = "Du holst tief Luft, nimmst das Siegel auf und verwendest einen Lappen, um den Schmutz von Lotans Rüstung zu wischen, so wie du es einst für die Ritter getan hast."
  },
  AvgDialog_142850_Content_123 = {
    Text = "Bitte hier entlang, dies... dies... äh?"
  },
  AvgDialog_142850_Content_124 = {
    Text = "Du verbeugst dich vor ihr, ihr ruhiges Atmen lässt dich den Kopf nicht heben, du starrst nur fest auf den Boden zu ihren Füßen. Du spürst, wie ihr klingengleicher Blick für einige Sekunden auf dir verweilt."
  },
  AvgDialog_142850_Content_125 = {
    Text = "Wenn du in Gefahr gerätst, erwarte nicht, dass ich dir helfe."
  },
  AvgDialog_142850_Content_126 = {
    Text = "Ohne Zusatz. Du kannst mich Lotan nennen."
  },
  AvgDialog_142850_Content_127 = {
    Text = "Lotan verstaut das Großschwert und geht in die Richtung, die du gezeigt hast."
  },
  AvgDialog_142850_Content_128 = {
    Text = "Das Blut ist vollständig in den Boden gesickert. In den Tiefen des dunkelroten Himmels zeichnet sich ein riesiger, langsam ziehender Schatten ab."
  },
  AvgDialog_142850_Content_129 = {
    Text = "Du schauderst und beeilest dich, Lotans Schritten zu folgen."
  },
  AvgDialog_142850_Content_13 = {
    Text = "Wir können zusammenarbeiten, nicht wahr?"
  },
  AvgDialog_142850_Content_130 = {
    Text = "Es ist... Herrin Lotan!"
  },
  AvgDialog_142850_Content_14 = {
    Text = "Zusammenarbeiten?"
  },
  AvgDialog_142850_Content_15 = {
    Text = "Der Sternenhimmelwal wird nur eine Person als seinen Executor auswählen – das ist eine Aufgabe, die man nicht alleine bewältigen kann!"
  },
  AvgDialog_142850_Content_16 = {
    Text = "Du musst nur das Knochensiegel ablegen, wir garantieren dir, dass du sicher von hier wegkommst und alles bekommst, was du bekommen kannst..."
  },
  AvgDialog_142850_Content_17 = {
    Text = "Ist das so?"
  },
  AvgDialog_142850_Content_18 = {
    Text = "Ich weiß, Varo, du hast die Bestien auf der Ödnisinsel überlebt, hast vor dem Spiegel den Menschen getötet, den du am meisten liebtest – vielleicht deine Eltern, dein Kind oder irgendetwas anderes."
  },
  AvgDialog_142850_Content_19 = {
    Text = "Du hast einen halben Monat in diesem Urwald gelebt. Du willst sicher nicht einfach so zurückgehen..."
  },
  AvgDialog_142850_Content_2 = {
    Text = "Blätter fallen von den Ästen, gleiten durch den dunkelroten Himmel und landen in einer Blutlache auf dem Boden, die eine schwache Welle aufwirft."
  },
  AvgDialog_142850_Content_20 = {
    Text = "Aber denk doch nach, denk daran, was Die Nachtwache vor dir liegt!"
  },
  AvgDialog_142850_Content_21 = {
    Text = "Du musst unsere Einkreisung durchbrechen, den Gefahren auf dem Weg ausweichen, die Arena des Sternenhimmelwals finden und dort ein Deathmatch gegen die gefährlichsten Menschen dieser Welt bestreiten."
  },
  AvgDialog_142850_Content_22 = {
    Text = "Selbst wenn dieses Knochensiegel dich zur Arena bringt – kannst du sicher sein, dass du derjenige sein wirst, der als Letzter überlebt?"
  },
  AvgDialog_142850_Content_23 = {
    Text = "Solange du aufgibst, kannst du nach dem Aufstieg von Herrn Elian zu einem Gründungsverdiensten werden... Denk gut nach, Varo!"
  },
  AvgDialog_142850_Content_24 = {
    Text = "Dein Angebot ist verlockend. Aber leider brauchen nur Versager den Zusammenhalt anderer. Du verstehst überhaupt nicht, was es bedeutet, stark zu sein."
  },
  AvgDialog_142850_Content_25 = {
    Text = "Spart euch die Worte, kommt alle auf einmal, ihr Abschaum der Ritterschaft."
  },
  AvgDialog_142850_Content_26 = {Text = "Du..."},
  AvgDialog_142850_Content_27 = {
    Text = "Varo! Du wirst für deine Respektlosigkeit einen Preis zahlen!"
  },
  AvgDialog_142850_Content_28 = {
    Text = "Ritterschaft! Angriff!!!"
  },
  AvgDialog_142850_Content_29 = {
    Text = "Ein Haufen Abfall..."
  },
  AvgDialog_142850_Content_3 = {
    Text = "Der uralte Wald ist durchdrungen von einem anhaltenden süßlich-blutigen Geruch. Die Körper, die das Land mit Blut genährt haben, liegen auf dem dunkelroten Moos, starren mit widerwilligen Augen und sind längst verstummt."
  },
  AvgDialog_142850_Content_30 = {
    Text = "Die Flut aus Rüstungen stürzte wie ein tosender Ozean auf die einsame Gestalt in der Mitte zu. Der Ansturm von mehr als zehn Personen zertrampelte Moos und morsche Knochen, und die Erde darunter begann zu Zittern."
  },
  AvgDialog_142850_Content_31 = {
    Text = "Das heftige Aufeinanderprallen von Metall hallte durch den dichten Wald und scheuchte einen schwarzen Vogelschwarm auf, der wie ein abgeplatztes schwarzes Splitterstück von den Baumkronen fiel."
  },
  AvgDialog_142850_Content_32 = {
    Text = "Die Äste und Blätter des Verstecks zitterten. Du kautest hinter dem Gebüsch, hieltest den Atem an und beobachtetest durch die Lücken zwischen den Ranken dieses Massaker."
  },
  AvgDialog_142850_Content_33 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_142850_Content_34 = {
    Text = "Die Krummsäbel zerschmetterten Klingen, durchdrangen die zerbrechliche Caro unter den Rüstungen und trennten Gliedmaßen und Köpfe durch die Lücken der Panzerplatten. Jeder Hieb war präzise, brutal, ohne eine einzige überflüssige Bewegung."
  },
  AvgDialog_142850_Content_35 = {
    Text = "Stärke, Geschwindigkeit, Können ... vor diesem Krieger fielen die Elite-Ritter wie Lämmer, die zur Schlachtbank geführt werden, einer nach dem anderen."
  },
  AvgDialog_142850_Content_36 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_142850_Content_37 = {
    Text = "Dies ... dieser Mensch ..."
  },
  AvgDialog_142850_Content_38 = {
    Text = "Der Ansturm und die Schlachtrufe verstummten schnell. Varro riss ein sauberes Tuch vom Körper eines gefallenen Ritters und wischte das Blut von der Klinge seines Krummsäbels."
  },
  AvgDialog_142850_Content_39 = {
    Text = "Er betrachtete die makellose Klinge und nickte zufrieden. Dann durchsuchte er die Leiche des anführenden Ritters und fand das Knochensiegel, das den Weg in die Arena wies."
  },
  AvgDialog_142850_Content_4 = {
    Text = "Puh ... ruhig ... niemand sollte mich entdeckt haben ..."
  },
  AvgDialog_142850_Content_40 = {
    Text = "Eins, zwei, drei ... elf, zwölf."
  },
  AvgDialog_142850_Content_41 = {
    Text = "Zwölf, zwölf ..."
  },
  AvgDialog_142850_Content_42 = {
    Text = "Er blickte sich um, konnte aber keine dreizehnte Leiche finden."
  },
  AvgDialog_142850_Content_43 = {
    Text = "Nicht gut! Er hat mich entdeckt ... ich muss so schnell wie möglich ..."
  },
  AvgDialog_142850_Content_44 = {
    Text = "*Schnapp*—"
  },
  AvgDialog_142850_Content_45 = {
    Text = "Ein abgestorbener Baumstumpf erschien zur Unzeit auf deinem Rückzugsweg. Varro fuhr ruckartig herum und blickte in das Gebüsch, in dem du dich versteckt hattest."
  },
  AvgDialog_142850_Content_46 = {Text = "!!!"},
  AvgDialog_142850_Content_47 = {
    Text = "Ich fragte mich schon, warum ich das Gefühl hatte, einen übersehen zu haben – da steckt also noch einer hier drin."
  },
  AvgDialog_142850_Content_48 = {
    Text = "Komm heraus, Freund, ich mache es schnell für dich."
  },
  AvgDialog_142850_Content_49 = {
    Text = "Varro betrachtete sein im Krummsäbel gespiegeltes Gesicht und schritt gemächlich auf dich zu."
  },
  AvgDialog_142850_Content_5 = {
    Text = "Ein heftiger Traum. Du versteckst dich im Gebüsch, beruhigst deinen rasenden Atem und spähst durch die Lücken im Dickicht nach draußen."
  },
  AvgDialog_142850_Content_50 = {
    Text = "Du blicktest dich um und suchtest fieberhaft nach einem geeigneten Fluchtweg."
  },
  AvgDialog_142850_Content_51 = {
    Text = "Unmöglich ... überall dichter Wald ... in diesem Kinderkörper kann ich ihm unmöglich davonlaufen ..."
  },
  AvgDialog_142850_Content_52 = {
    Text = "Was soll ich tun ..."
  },
  AvgDialog_142850_Content_53 = {
    Text = "Du schlossest die Augen, bemühtest dich, die aufwallende Angst in dir niederzudrücken, und dein Kopf war wie leer ..."
  },
  AvgDialog_142850_Content_54 = {
    Text = "<Red:Rasch. Rasch. Rasch.>"
  },
  AvgDialog_142850_Content_55 = {Text = "Hm?"},
  AvgDialog_142850_Content_56 = {
    Text = "Schritte traten auf Laub und Flechten, die aus einer anderen Richtung näherkamen."
  },
  AvgDialog_142850_Content_57 = {
    Text = "Sie waren ruhig, gleichmäßig, wie ein gemächlicher Spaziergang am Nachmittag."
  },
  AvgDialog_142850_Content_58 = {
    Text = "Ein Helfer der Ritter... Du wählst nicht die Flucht – mutig, aber auch dumm."
  },
  AvgDialog_142850_Content_59 = {
    Text = "Als die Schritte verstummen, verschwinden Wind und Vogelgesang, selbst das Blut, das aus den Leichen hinter Dir sickert, scheint aufgehört zu haben zu fließen – der gesamte Wald versinkt in einer unheimlichen, totenstillen Stille."
  },
  AvgDialog_142850_Content_6 = {
    Text = "Ein Krummsäbel wird sauber aus seiner Brust gezogen und erzeugt dabei ein unangenehmes Schaben. Der Krieger klopft den Staub von seiner Rüstung und blickt in die Umgebung."
  },
  AvgDialog_142850_Content_60 = {
    Text = "Eine Frau tritt ins Blickfeld. Verzierter schwarzer Leichtrüstung bedeckt ihre Gestalt, und in ihren Händen hält sie lässig zwei wuchtige Großschwerter, völlig unverhältnismäßig zu ihrer Statur."
  },
  AvgDialog_142850_Content_61 = {
    Text = "Ihre Augen gleiten über die Leichen am Boden, ihr Blick streift flüchtig die Wunden der Gefallenen."
  },
  AvgDialog_142850_Content_62 = {
    Text = "Jeder starb mit weniger als fünf Hieben, gezielt an den Verbindungsstellen der Rüstung, Winkel und Kraft präzise... Diese Menschen – hast Du sie getötet?"
  },
  AvgDialog_142850_Content_63 = {
    Text = "Hehehe... Ganz recht. Schade nur, ich hatte noch nicht genug gespielt, da lagen sie schon."
  },
  AvgDialog_142850_Content_64 = {
    Text = "Zwölf Mann, und Du bist unverletzt. Nicht schlecht."
  },
  AvgDialog_142850_Content_65 = {
    Text = "Die Frau in der schwarzen Rüstung nickte zufrieden und schritt mit gleichmäßigen Schritten weiter auf ihn zu."
  },
  AvgDialog_142850_Content_66 = {
    Text = "Varro wartete. Er suchte in den Augen dieser Frau nach Angst, doch fand nur eine unerträglich ruhige Gelassenheit."
  },
  AvgDialog_142850_Content_67 = {
    Text = "Egal wer Du bist, ich gebe Dir drei Minuten zur Flucht. Ob Du danach noch lebst, das hängt davon ab..."
  },
  AvgDialog_142850_Content_68 = {
    Text = "Ich frage mich, bist Du taub? Hörst Du meine Worte nicht?"
  },
  AvgDialog_142850_Content_69 = {
    Text = "Die Frau in der schwarzen Rüstung antwortete nicht, ihre Schritte blieben so gleichmäßig wie ein Spaziergang. Wut entflammte augenblicklich in Varro – seine Hand schloss sich um den Griff, und er zog das scharfe Krummschwert heraus."
  },
  AvgDialog_142850_Content_7 = {
    Text = "Wer ist der Nächste?"
  },
  AvgDialog_142850_Content_70 = {
    Text = "Eigentlich wollte ich Dir das Leben schenken, aber wenn Du so sehr den Tod suchst, dann werde ich keine Gnade..."
  },
  AvgDialog_142850_Content_71 = {Text = "Clang—"},
  AvgDialog_142850_Content_72 = {
    Text = "Ein Metallklang, der reinste, den Varro je in seinem Leben gehört hatte, erklang für einen Augenblick an seinem Ohr und war sofort wieder verflogen."
  },
  AvgDialog_142850_Content_73 = {
    Text = "Die Frau, die noch einen Moment zuvor vor Varro gestanden hatte, war nun – er wusste nicht wann – hinter ihm aufgetaucht. Ein gewaltiges Schwert hielt Sie mit einer Hand, die Klinge lässig an seiner Halsseite angelegt."
  },
  AvgDialog_142850_Content_74 = {
    Text = "Varro senkte den Blick. Das Krummschwert, geschmiedet von den besten Schmieden aus sechs Ländern und Schöpfer unzähliger Feinde, hing wenige Zoll aus der Scheide gezogen – und war an der Wurzel abgetrennt."
  },
  AvgDialog_142850_Content_75 = {
    Text = "Die prächtige Klinge, auf die er so stolz gewesen war, rotierte und bohrte sich in den blutgetränkten Boden – wie ein eiskalter Grabstein."
  },
  AvgDialog_142850_Content_76 = {
    Text = "Das... Du..."
  },
  AvgDialog_142850_Content_77 = {
    Text = "Jemand, der eine ganze Ritterschaft auslöschen kann – ich dachte, Du würdest mich wenigstens ein wenig interessieren."
  },
  AvgDialog_142850_Content_78 = {
    Text = "Die Frau in schwarzer Rüstung sprach mit unverhohlenem Missmut in der Stimme."
  },
  AvgDialog_142850_Content_79 = {
    Text = "Ein Knochensiegel – hast Du eines?"
  },
  AvgDialog_142850_Content_8 = {
    Text = "Er leckt das Blut vom Krummsäbel, mustert die Dutzend Menschen, die ihn umringen, und fragt mit sichtlichem Interesse."
  },
  AvgDialog_142850_Content_80 = {
    Text = "<Shake:Ja! Ja, ja, ja!>"
  },
  AvgDialog_142850_Content_81 = {
    Text = "Varro hatte viele Menschen und Dinge erlebt und wusste, wann er was zu tun hatte. Seine Knie gaben nach und er fiel vor ihr auf den Boden."
  },
  AvgDialog_142850_Content_82 = {
    Text = "Edle Herrin, bitte hört mich an ... Der Wal des Sternenhimmels wählt nur eine einzige Person zu seinem Executor – das ist etwas, das man nicht alleine bewerkstelligen kann!"
  },
  AvgDialog_142850_Content_83 = {
    Text = "Die Krone! Diese Krone, von der alle träumen... Du willst sie auch, nicht wahr?!"
  },
  AvgDialog_142850_Content_84 = {
    Text = "Ihr besitzt eine so gewaltige Stärke – wenn wir ein Team bilden, werden wir gewiss den endgültigen Sieg erringen!"
  },
  AvgDialog_142850_Content_85 = {
    Text = "Ich werde Euer treuester Diener sein, Euch auf ewig ergeben, und Euch dabei helfen, die Stärke des Wals des Sternenhimmels zu erlangen! ..."
  },
  AvgDialog_142850_Content_86 = {
    Text = "Edle Herrin ... bitte erwägt es ..."
  },
  AvgDialog_142850_Content_87 = {
    Text = "Ein guter Vorschlag. Ich stimme zu."
  },
  AvgDialog_142850_Content_88 = {
    Text = "Du... du..."
  },
  AvgDialog_142850_Content_89 = {
    Text = "Varro hatte sich bereits eine lange Rede zurechtgelegt und musste nun Entdecken, dass er sie überhaupt nicht brauchte."
  },
  AvgDialog_142850_Content_9 = {
    Text = "Als er den Krummsäbel hebt, treten alle wie auf Kommando einen Schritt zurück."
  },
  AvgDialog_142850_Content_90 = {
    Text = "Keine Sorge. Ich breche nie mein Wort."
  },
  AvgDialog_142850_Content_91 = {
    Text = "<Shake:Das ist ... das ist wunderbar!>"
  },
  AvgDialog_142850_Content_92 = {
    Text = "Wie ein Mann, der vom Rand des Abgrunds zurückgerissen wurde, durchwühlt Varro seine Habseligkeiten und überreicht Lotan schließlich die Knochensiegel mit zitternden, hohlen Händen."
  },
  AvgDialog_142850_Content_93 = {
    Text = "Hier! Genau das ist es!"
  },
  AvgDialog_142850_Content_94 = {
    Text = "Diese Ritter haben zwei Siegel beschlagnahmt. Mit diesen können wir gemeinsam die Arena betreten!"
  },
  AvgDialog_142850_Content_95 = {
    Text = "Dann wird niemand in der Lage sein, zu siegen gegen ..."
  },
  AvgDialog_142850_Content_96 = {
    Text = "Schwisch—"
  },
  AvgDialog_142850_Content_97 = {Text = "ARGH!!"},
  AvgDialog_142850_Content_98 = {
    Text = "Die Klinge des Großschwertes glitt mühelos durch die Rüstung, und eine gewaltige Wunde, die den Körper Fast Durchstechen hatte, zog sich von Varros rechter Hüfte bis zur linken Schulter."
  },
  AvgDialog_142850_Content_99 = {
    Text = "Warmes Blutfest spritzte auf die Büsche vor Dir und gefror auf den Blättern zu dunkelroten Tautropfen."
  },
  AvgDialog_142851_Content_1 = {
    Text = "Der vierte Abschnitt"
  },
  AvgDialog_142851_Content_10 = {
    Text = "Im Zentrum jener gebrochenen Säulen zerriss ein Spalt die Realität, der in einen anderen Raum führte – wie eine sich langsam öffnende, senkrechte Pupille."
  },
  AvgDialog_142851_Content_100 = {
    Text = "Die Fleischwand unter den Füßen zuckte heftig im Krampf, ein starker Geruch von Rost drang in die Nasenhöhle. Der Raum selbst begann vor Begeisterung zu erwachen."
  },
  AvgDialog_142851_Content_101 = {
    Text = "Gut ... Gut!"
  },
  AvgDialog_142851_Content_102 = {
    Text = "Zwölftausend Jahre, Lotan ... Ich habe in dieser Leere gewartet – Die Nachtwache hielt ich für jemanden, der mich spüren lässt, dass das Dasein keine Qual ist."
  },
  AvgDialog_142851_Content_103 = {
    Text = "Könige, Heilige, Krieger, Dämonen ... Sie traten vor mich, mit ihren vermeintlich großartigen Begierden, knieten nieder und bettelten."
  },
  AvgDialog_142851_Content_104 = {
    Text = "Dann wurden sie von der Stärke, die ich ihnen schenkte, Stück für Stück dem Verfall preisgegeben und wurden zu einem weiteren treibenden Antlitz im Abgrund."
  },
  AvgDialog_142851_Content_105 = {
    Text = "Ich dachte, das sei der gesamte Inhalt der Ewigkeit."
  },
  AvgDialog_142851_Content_106 = {
    Text = "Bis Du hier standest, mich mit diesen Augen anschautest, die nach nichts verlangen, und mir sagtest, Du willst ... hehehe ... Du willst mich töten?!!"
  },
  AvgDialog_142851_Content_107 = {
    Text = "Reines, dichtes, schweres Dunkelrot strömte aus dem Riss im Herzen und verschlang alle Lichtadern und die Antlitze im Abgrund."
  },
  AvgDialog_142851_Content_108 = {
    Text = "In jenem verfallenen Dunkelrot zeichnete sich am Horizont der Umriss des gewaltigen Leibes des Sternenhimmelwals ab."
  },
  AvgDialog_142851_Content_109 = {
    Text = "Ein Leib, größer als diese Welt, bog die Form der Leere selbst, die Ebene unter deinen Füßen begann sich wie Papier zu krümmen, und die Dunkelheit in der Ferne begann nach innen einzustürzen."
  },
  AvgDialog_142851_Content_11 = {
    Text = "Es stellt sich heraus, dass man die Tür öffnen kann, ohne den anderen zu töten ... Du hast Glück gehabt."
  },
  AvgDialog_142851_Content_110 = {
    Text = "Dieser Planet wuchs auf seinem Körper, die Menschen der sechs Reiche existierten seinetwegen. Es war die Gottheit, die die Stärke von Planeten verschlingt, der unbestrittene Herrscher dieses Sterns. Es war dieser Raum selbst."
  },
  AvgDialog_142851_Content_111 = {
    Text = "Das Phantasma verschwand vollständig, und der Leviathan riss seine majestätischen Augen weit auf."
  },
  AvgDialog_142851_Content_112 = {
    Text = "Eine Stärke, die Himmel und Erde zu vernichten vermochte, strömte aus dem Körper des Sternenwals hervor. Der gesamte Dimensionsraum begann zu kollabieren, eine unsichtbare Stärke schleuderte Dich fort und warf Dich schwer auf den Rand der Ebene."
  },
  AvgDialog_142851_Content_113 = {
    Text = "Deine Finger krallten sich in den Riss, um Dich verzweifelt davor zu bewahren, in den Abgrund zu gleiten."
  },
  AvgDialog_142851_Content_114 = {
    Text = "Du machst mich sehr, sehr glücklich, Lotan!"
  },
  AvgDialog_142851_Content_115 = {
    Text = "Nach Deinem Tod werde ich alle Diener dieser Welt dazu bringen, Dir die prächtigste Statue zu errichten!"
  },
  AvgDialog_142851_Content_116 = {
    Text = "Im Zentrum der Dunkelheit, die alles verschlang, vor jenem namenlosen, gewaltigen Wesen, umklammerte Lotan mit beiden Händen ihr Riesenschwert und schritt auf jene furchtbaren, riesigen Augen zu."
  },
  AvgDialog_142851_Content_117 = {
    Text = "Ihre Schritte wurden schneller und schneller, bis sie sich schließlich in einen unaufhaltsamen Sturm verwandelten. Auf ihrem Gesicht lag ein Lächeln voller Wahnsinn, wie Du es noch nie zuvor gesehen hattest."
  },
  AvgDialog_142851_Content_118 = {
    Text = "Komm schon! Leviathan!!!"
  },
  AvgDialog_142851_Content_119 = {
    Text = "Ein befreiendes Gebrüll wie das Tosen der Meereswellen erhob sich und zerschmetterte Deine letzten verbliebenen Sinne. Die Hand, die den Stein umklammert hatte, besaß keine Stärke mehr, und im tosenden Wind wurdest Du durch den Riss zurück in die Arena geschleudert."
  },
  AvgDialog_142851_Content_12 = {
    Text = "Lotan wandte ihren Blick ab – Sie hatte nie das geringste Interesse an Dir gehabt. Die schlanke Gestalt hob das gewaltige Schwert und schritt auf den Spalt zu."
  },
  AvgDialog_142851_Content_120 = {
    Text = "In Deinem letzten Augenblick sahst Du, wie Lotan die beiden Riesenschwerter ergriff und auf jene Gottheit zusprang, die majestätischer war als alle Sterne."
  },
  AvgDialog_142851_Content_121 = {
    Text = "Der Sturm zerschellt in tausend Stücke.\nDer Sturm kehrt niemals um."
  },
  AvgDialog_142851_Content_13 = {
    Text = "Erst als ihre Gestalt vollständig im Spalt verschwunden war, richtete Du Dich endlich auf und rang keuchend nach Luft."
  },
  AvgDialog_142851_Content_14 = {
    Text = "Puh ... Das war knapp ..."
  },
  AvgDialog_142851_Content_15 = {
    Text = "Ist das dort ... die Behausung des Sternenwals ..."
  },
  AvgDialog_142851_Content_16 = {
    Text = "Du wolltest eigentlich fliehen, doch eine unwiderstehliche Anziehungskraft strömte aus dem Spalt hervor – wie ein unsichtbarer Faden, der an Deinen Knochen befestigt war und Dich sanft, aber unaufhörlich zog."
  },
  AvgDialog_142851_Content_17 = {
    Text = "Deine Füße bewegten sich unwillkürlich auf den Spalt zu. Der Spalt zitterte leicht, wie ein sanftes Auge, das Dich betrachtete."
  },
  AvgDialog_142851_Content_18 = {
    Text = "Nur ein Blick, nur ein einziger Blick. Sehen, wie der große Herr, der die Sterne verschlingt, wirklich aussieht ... Du schlichst Dich vorsichtig an den Spalt heran und folgtest hinein ..."
  },
  AvgDialog_142851_Content_19 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_142851_Content_2 = {
    Text = "Lo-Lotan, Herrin! ..."
  },
  AvgDialog_142851_Content_20 = {
    Text = "Kein Licht, kein Ton, nicht einmal Deinen eigenen Herzschlag konntest Du hören. Du warst Dir nicht sicher, ob Du noch einen Körper besaßest oder ob Du bereits zu einem Bewusstseinsfragment geworden warst, das in der Nichtigkeit trieb."
  },
  AvgDialog_142851_Content_21 = {
    Text = "Das Tastgefühl kehrte in Deinen Körper zurück – unter Deinen Füßen spürtest Du ein weiches, warmes, rhythmisches Wogen. Es zog sich sanft unter Deinen Fußsohlen zusammen, wie eine riesige Zunge, die Dich ableckte."
  },
  AvgDialog_142851_Content_22 = {
    Text = "Was ist das?! ......"
  },
  AvgDialog_142851_Content_23 = {
    Text = "Trübe Sterne zogen durch den Sternenhimmel, und ein Pulsieren, das seine Farbe ständig wechselte, erleuchtete den Raum, in dem Du Dich befandest."
  },
  AvgDialog_142851_Content_24 = {
    Text = "Endlose Massen aus Caro wogten unter Deinen Füßen auf und ab, wie eine riesige Zunge oder ein Magen."
  },
  AvgDialog_142851_Content_25 = {
    Text = "Du holtest tief Luft und begegntest dem Blick jenes fernen, flimmernden, augenartigen Pulsierers. Nur eine Sekunde – und ein heftiger Schwindel überkam Dich, ein warmes Blutfest strömte aus Deiner Nase. Du wandtest schnell den Blick ab."
  },
  AvgDialog_142851_Content_26 = {
    Text = "In Deinem letzten Augenwinkel sahst Du, wie sich das wandelnde Pulsieren zu einer Form verdichtete und ein nichtig-es Phantasma vor Lotan erschien. Als Es zu sprechen begann, erklang ein weitreichender Walgesang in diesem Raum."
  },
  AvgDialog_142851_Content_27 = {
    Text = "Willkommen, der viertausendste Herausforderer, der vor mich getreten ist! Willkommen in meiner Behausung."
  },
  AvgDialog_142851_Content_28 = {
    Text = "Wie ich es mir dachte, bist Du es."
  },
  AvgDialog_142851_Content_29 = {
    Text = "Ein so großartiger Wettkampf – was wäre der Spaß daran, wenn man nicht persönlich dabei sein könnte."
  },
  AvgDialog_142851_Content_3 = {
    Text = "Ich ... ich hatte nie ... nie die Absicht, Euch die Krone streitig zu machen ..."
  },
  AvgDialog_142851_Content_30 = {
    Text = "Ich habe jeden deiner Kämpfe verfolgt, Kind mit dem Großschwert."
  },
  AvgDialog_142851_Content_31 = {
    Text = "Gracchus, die Vaughan-Schwestern, Sanchi, Elian, Alish... In dieser großen Arena hast du alle mächtigsten Wesen dieses Planeten besiegt."
  },
  AvgDialog_142851_Content_32 = {
    Text = "Dein Schwert macht keine überflüssigen Bewegungen. Deine Seele trägt keine überflüssige Last. Dein Sieg ist mehr als verdient, Lotan."
  },
  AvgDialog_142851_Content_33 = {
    Text = "Das Phantasma nickte zufrieden."
  },
  AvgDialog_142851_Content_34 = {
    Text = "Die Wesen, die hierher kommen, haben im Grunde nur drei Gründe: Wissen, Macht, LP."
  },
  AvgDialog_142851_Content_35 = {
    Text = "Der gierige König begehrt einen unsterblichen Thron, die verzweifelte Mutter will ihr totes Kind wiederbeleben, der wahnsinnige Zauberer will verbotenes Wissen erspionieren... sie alle wollen so viel, so unendlich viel."
  },
  AvgDialog_142851_Content_36 = {
    Text = "Also fügen sie Schaden zu, töten und opfern alles. Sie knien vor mir und flehen mich mit Worten an, die ich seit Tausenden von Jahren höre."
  },
  AvgDialog_142851_Content_37 = {
    Text = "Doch all das hat sich gelohnt... am Ende hat jeder das erhalten, wonach er so verzweifelt gesucht hat."
  },
  AvgDialog_142851_Content_38 = {
    Text = "Also, tapferer Krieger... was ist es, das Du begehrst?"
  },
  AvgDialog_142851_Content_39 = {Text = "Stärke."},
  AvgDialog_142851_Content_4 = {
    Text = "Ich ... ich wollte nur ..."
  },
  AvgDialog_142851_Content_40 = {
    Text = "Stärke ist Gerade ein Werkzeug, eine Sprosse auf einer Leiter – und über dieser Leiter wartet noch etwas auf Dich."
  },
  AvgDialog_142851_Content_41 = {
    Text = "Sag mir, was Du wirklich willst – was ist es wirklich?"
  },
  AvgDialog_142851_Content_42 = {
    Text = "Ich habe es bereits gesagt... was ich will, ist Nur Stärke. Stärke ohne Ende, immer größere Stärke."
  },
  AvgDialog_142851_Content_43 = {
    Text = "Für alles außer Stärke habe ich kein Interesse."
  },
  AvgDialog_142851_Content_44 = {
    Text = "Der Himmelswal betrachtete Lotan mit Neugier, und ein donnerndes Lachen hallte durch diesen Raum."
  },
  AvgDialog_142851_Content_45 = {
    Text = "Hehehehe ..."
  },
  AvgDialog_142851_Content_46 = {
    Text = "Solche Worte habe ich viele Male gehört. Jeder, der sie ausgesprochen hat, ist am Ende in den Begierden verloren gegangen, die Stärke mit sich bringt."
  },
  AvgDialog_142851_Content_47 = {
    Text = "Sie erhielten meine Stärke, doch konnten ihr Gewicht nicht tragen. Sie wuchs in ihrem Mark, fraß ihre Seelen, und die Gier nach Töten und Erobern verschlang ihr Bewusstsein eines nach dem anderen..."
  },
  AvgDialog_142851_Content_48 = {
    Text = "Solche Geschichten habe ich viertausend Mal erlebt, und ich werde ihrer niemals überdrüssig."
  },
  AvgDialog_142851_Content_49 = {
    Text = "Mit dem Klang eines Walgesangs erschien ein riesiges Walherz in diesem Raum. Eine Blutsäule strömte aus dem Herzen und sammelte sich vor Lotan zu einem dichten Gewirr aus Runen."
  },
  AvgDialog_142851_Content_5 = {
    Text = "Du hattest die Wunde an Deiner Schulter längst vergessen und hattest nicht den Mut, diesen ruhigen Augen direkt ins Gesicht zu sehen."
  },
  AvgDialog_142851_Content_50 = {
    Text = "Sie ordneten sich zu einer unbegreiflichen Form an, und jedes Mal, wenn Lotan versuchte, ihr Gesamtbild zu erfassen, verwandelte sie sich in eine völlig andere Gestalt."
  },
  AvgDialog_142851_Content_51 = {
    Text = "Schon ein flüchtiger Blick aus dem Augenwinkel ließ einen heißen Blutstrom durch deinen Körper rasen, der jeden deiner Organe erschütterte und dich antrieb, das Schwert zu ergreifen und es in das Herz des Menschen vor dir zu stoßen ... Du wandtest schnell den Blick ab."
  },
  AvgDialog_142851_Content_52 = {
    Text = "Unterzeichne es. Und du wirst erhalten, wonach du dich gesehnt hast – meine Stärke."
  },
  AvgDialog_142851_Content_53 = {Text = "Der Preis?"},
  AvgDialog_142851_Content_54 = {
    Text = "Kein Preis, nur ein Versprechen."
  },
  AvgDialog_142851_Content_55 = {
    Text = "Meine Stärke wird mit dir geteilt, mein Schicksal wird mit deinem verbunden. Von dem Moment an, in dem Das Testament besiegelt ist, bist du die Herrscherin dieses Planeten, die Vollstreckerin meines Willens."
  },
  AvgDialog_142851_Content_56 = {
    Text = "Du wirst alles der sechs Nationen besitzen, bis — bis in drei Jahren ein neues Kräftemessen beginnt und ein neuer König geboren wird."
  },
  AvgDialog_142851_Content_57 = {
    Text = "Du wirst mich begleiten und zusehen, wie jene faszinierenden Seelen — wie du selbst — Schritt für Schritt in den Abgrund schreiten. Genau wie die Könige vor dir."
  },
  AvgDialog_142851_Content_58 = {
    Text = "Doch ich weiß, dass du dich nicht widersetzen wirst, selbst wenn du die Konsequenzen kennst."
  },
  AvgDialog_142851_Content_59 = {
    Text = "Du denkst, du seist anders als die viertausend Herausforderer vor dir. Du besitzt einen Willen, der alles Überwinden kann, und wirst niemals in den Abgrund der Stärke und des Verlangens stürzen ..."
  },
  AvgDialog_142851_Content_6 = {
    Text = "Lotan sprach kein Wort, Sie trug Nur ihr Schwert und schritt gemächlich auf Dich zu. Deine Stirn presste sich fest auf den Boden, und Dein Körper zitterte vor der sich nähernden Gestalt."
  },
  AvgDialog_142851_Content_60 = {
    Text = "Wie unterzeichnet man dieses Testament?"
  },
  AvgDialog_142851_Content_61 = {
    Text = "Das Lächeln des Himmelswal-Sterns trug eine uralte Erschöpfung. Er hatte dieselbe Geschichte schon viel zu oft gesehen. Auch dieses Mal war es nicht anders."
  },
  AvgDialog_142851_Content_62 = {
    Text = "... Gier. Entschlossenheit. Dir liegt nichts an Förmlichkeiten, aber zumindest trägst du Eigenschaften in dir, die mir Freude bereiten."
  },
  AvgDialog_142851_Content_63 = {
    Text = "Strecke deine Hand aus und lege sie auf Das Testament."
  },
  AvgDialog_142851_Content_64 = {
    Text = "Ohne zu zögern streckte Lotan die Hand aus und legte sie auf die aus Blut geformte Figur."
  },
  AvgDialog_142851_Content_65 = {
    Text = "Flüssige, lebendige Zeichen krochen aus dem Blutpool hervor. Sie kletterten Lotans Arm hinauf, drangen ein und bohrten sich unter ihre Haut."
  },
  AvgDialog_142851_Content_66 = {
    Text = "Überall, wo die Zeichen vorbeizogen, verfaulte und zersetzte sich Lotans Fleisch rasch, bis nur noch bleiche Knochen und tiefes Rot übrig blieben."
  },
  AvgDialog_142851_Content_67 = {
    Text = "Lotans Körper zitterte vor Schmerz, doch sie gab keinen einzigen Laut von sich. Sie riss ihre bereits zur Hälfte gebrochenen Augen weit auf und bezeugte alles mit größter Aufmerksamkeit."
  },
  AvgDialog_142851_Content_68 = {
    Text = "Die Zeichen breiteten sich entlang des Adernetzwerks zum Herzen aus und erreichten schließlich ihre Augen. In einem Augenblick verwandelten sich Lotans Pupillen in denselben Moskstraumen wie der des Himmelswal-Sterns."
  },
  AvgDialog_142851_Content_69 = {
    Text = "Dann verschwand der Mosktraumen, und die Pupillenfarbe des Himmelswal-Sterns blieb für immer in ihren Augen, während eine Rüstung aus bleichen Knochen ihren neugeborenen Körper bedeckte."
  },
  AvgDialog_142851_Content_7 = {
    Text = "Eins der Herausforderer entschied sich zur Unterwerfung, Eins entschied sich zur Flucht, fünfzehn entschieden sich für den Tod ... Es scheint, unser letzter Sieger ist bereits bestimmt."
  },
  AvgDialog_142851_Content_70 = {
    Text = "Die gesamte Leere ließ ein tiefes Resonieren ertönen, und die Gesichter, die im Abgrund schwebten und in der Arena gestorben waren, öffneten gleichzeitig ihre Münder und stießen lautlose Schreie aus."
  },
  AvgDialog_142851_Content_71 = {
    Text = "Sie empfingen ihren Neuen König."
  },
  AvgDialog_142851_Content_72 = {
    Text = "Das... ist die Stärke des Sternenhimmels-Leviathans..."
  },
  AvgDialog_142851_Content_73 = {
    Text = "Lotan ballte die Faust und spürte die tosende, uralte göttliche Stärke in ihrem Inneren, spürte ihre Verbindung mit dieser Welt."
  },
  AvgDialog_142851_Content_74 = {
    Text = "Die vom Sternenhimmels-Leviathan verschlungenen Welten pulsierten in ihrer Wahrnehmung, und alle LP, die der Sternenhimmels-Leviathan erschaffen und versklavt hatte, glichen winzigen Kerzenflammen – ein einziger Gedanke würde genügen, um sie alle zu erlöschen."
  },
  AvgDialog_142851_Content_75 = {
    Text = "Das Blutbad vereinte sich zu einer blutroten Krone, die vor ihr in strahlendem Glanz erstrahlte."
  },
  AvgDialog_142851_Content_76 = {
    Text = "Das Testament ist besiegelt. Unser Schicksal ist untrennbar vereint, unumkehrbar. So viele Zeitalter, wie ich existiert habe, so viel Last dieser Zeitalter hast du geerbt."
  },
  AvgDialog_142851_Content_77 = {
    Text = "Genieße es, Lotan. Ich habe zu viele Seelen gesehen, die dir ähneln. Rein, glühend, unerschütterlich überheblich."
  },
  AvgDialog_142851_Content_78 = {
    Text = "Ich werde es erwarten... erwarten, den Tag, an dem du in den Abgrund stürzt. Ich werde in einen neuen langen Schlummer versinken... Nun kannst du alles tun, was du tun möchtest."
  },
  AvgDialog_142851_Content_79 = {
    Text = "Das Phantasma des Sternenhimmels-Leviathans hinterließ einen gelangweilten Abschied und öffnete erneut den Riss."
  },
  AvgDialog_142851_Content_8 = {
    Text = "Stimmen strömten von allen Seiten heran, erfüllt von einem unangenehmen Vergnügen. Die unzähligen Phantasmen auf den Tribünen erhoben sich gleichzeitig, und auf ihren sich ständig wandelnden Gesichtern erschien ein und dasselbe Lächeln."
  },
  AvgDialog_142851_Content_80 = {
    Text = "Hast Du alles gesagt?"
  },
  AvgDialog_142851_Content_81 = {
    Text = "Die Behausung des Sternenhimmels-Leviathans versank in kurzes Schweigen. Er wartete nicht auf die erhoffte Unterwerfung und Lobpreisung – stattdessen begegnete ihm ein Paar Augen eines Kriegers, die mit unbändiger Kampfeslust brannten."
  },
  AvgDialog_142851_Content_82 = {
    Text = "Dann ist es jetzt... an der Zeit, dass Du angreifst."
  },
  AvgDialog_142851_Content_83 = {
    Text = "Du hättest nie gedacht, dass Du in den Augen einer Gottheit Verwirrung sehen würdest."
  },
  AvgDialog_142851_Content_84 = {
    Text = "Du... was sagst du?"
  },
  AvgDialog_142851_Content_85 = {
    Text = "Du sagst, ich kann alles tun, was ich möchte... Es gibt nur eine Sache, die ich tun möchte. Dich töten, oder von dir getötet werden."
  },
  AvgDialog_142851_Content_86 = {
    Text = "Meine Gewohnheit ist es, den Gegner zuerst angreifen zu lassen. Also, es ist an der Zeit, dass Du angreifst, Leviathan."
  },
  AvgDialog_142851_Content_87 = {
    Text = "Du hast gerade Das Testament unterzeichnet..."
  },
  AvgDialog_142851_Content_88 = {
    Text = "Ich habe versprochen, der Wächter dieses Planeten zu werden, der Vollstrecker deines Willens."
  },
  AvgDialog_142851_Content_89 = {
    Text = "Du bist der Sklavenhalter dieses Planeten – wenn ich dich in ihrem Namen bekämpfe, erfülle ich damit auch meine Pflicht."
  },
  AvgDialog_142851_Content_9 = {
    Text = "Ein dumpfes Dröhnen. Die Steinsäulen der Arena hinter Dir zerbrachen, Trümmer flogen in den Himmel und verschwanden in den Tiefen des sumpfig dunkelroten Himmels."
  },
  AvgDialog_142851_Content_90 = {
    Text = "Du bist der Sternenverschlinger, das Sinnbild von Massaker und Krieg. Kampf ist dein Wille."
  },
  AvgDialog_142851_Content_91 = {
    Text = "Ein sehr guter Witz, Lotan. Wenn du jetzt gehst, kannst du immer noch alles bekommen, was alle haben wollen. Wenn du bleibst, bekommst du nichts."
  },
  AvgDialog_142851_Content_92 = {
    Text = "Ich habe mich klar genug ausgedrückt."
  },
  AvgDialog_142851_Content_93 = {
    Text = "Das Testament hat dein Schicksal mit meinem verknüpft. Mein Tod ist dein Tod."
  },
  AvgDialog_142851_Content_94 = {
    Text = "Das ist mir gleichgültig."
  },
  AvgDialog_142851_Content_95 = {
    Text = "Deine Stärke erreicht nicht einmal die Hälfte der meinen. Du hast sie gerade erst erlangt, du verstehst die Stärke, die du zu beherrschen versuchst, überhaupt nicht ... Du bist nicht im Stande, mich herauszufordern, Lotan."
  },
  AvgDialog_142851_Content_96 = {
    Text = "Ich möchte es versuchen."
  },
  AvgDialog_142851_Content_97 = {
    Text = "Hehehe ... Hahahaha!!!"
  },
  AvgDialog_142851_Content_98 = {
    Text = "Der Sternenhimmelwal lachte wild auf. Seit über zehntausend Jahren hatte Er nicht mehr so befreiend gelacht."
  },
  AvgDialog_142851_Content_99 = {
    Text = "Das Lachen stieg aus den tiefsten Tiefen der Leere empor und ließ jede Lichtader, jede Schuppe und jedes im Abgrund treibende Antlitz erzittern."
  },
  AvgDialog_142852_Content_1 = {
    Text = "Der dritte Abschnitt"
  },
  AvgDialog_142852_Content_10 = {
    Text = "Du drehst dich um und siehst gerade noch zwei Schatten, die blitzschnell auf dich zurasen —"
  },
  AvgDialog_142852_Content_100 = {
    Text = "Alisch betrachtet die junge Frau vor ihm mit Erschütterung. Ein düsteres blutrottes Leuchten umrahmt ihre Silhouette. In den letzten Momenten seines Lebens erblickt er den Glauben selbst, dem er angehangen hat."
  },
  AvgDialog_142852_Content_101 = {
    Text = "Ha... Hahahaha! Herrlich!"
  },
  AvgDialog_142852_Content_102 = {
    Text = "Ich habe mir meinen Tod viele Male vorgestellt... keiner davon hat mich mehr befriedigt als das, was heute geschehen ist."
  },
  AvgDialog_142852_Content_103 = {
    Text = "Ich danke Euch, Frau Lotan."
  },
  AvgDialog_142852_Content_104 = {
    Text = "General Alisch breitet die Arme aus und badet im blutigen Sonnenlicht."
  },
  AvgDialog_142852_Content_106 = {
    Text = "Ein sauberer, klarer Klingenschimmer blitzt auf, und der Kopf des alten Alisch rollt neben dem gefallenen Schlachtross und den zerbrochenen Bannern zu Boden."
  },
  AvgDialog_142852_Content_107 = {
    Text = "Auf dem vom Leben gezeichneten Haupt liegt ein zufriedenes Lächeln. Mit seinem Ende hat der alte Alisch keinen weiteren Wunsch."
  },
  AvgDialog_142852_Content_108 = {
    Text = "Lotan schließt ihm die Augen und dreht sich um – sie sieht den Adligen in der Kleidung des Wesirs und das Kind, das unter seiner zitternden Klinge kauert."
  },
  AvgDialog_142852_Content_109 = {
    Text = "Lo... Lotan, Herrin..."
  },
  AvgDialog_142852_Content_11 = {Text = "!!!"},
  AvgDialog_142852_Content_110 = {
    Text = "Vira? Vira!"
  },
  AvgDialog_142852_Content_111 = {
    Text = "Elians Stimme folgend, dreht Lotan den Kopf und wirft einen Blick auf die Gestalt hinter ihr, die in der Dunkelheit verborgen ist."
  },
  AvgDialog_142852_Content_112 = {
    Text = "Nach kurzem Zögern von wenigen Sekunden zieht der Giftmischer aus dem Wesirpalast seine zitternde Hand zurück und läuft aus der Arena hinaus. Angesichts des Todes wissen die meisten Menschen, was zu tun ist."
  },
  AvgDialog_142852_Content_113 = {
    Text = "Es scheint, Eure Kontrolle über die Menschen um Euch herum ist doch recht begrenzt."
  },
  AvgDialog_142852_Content_114 = {
    Text = "Frau Lotan, wir sind Verbündete! Erinnert Ihr Euch noch?"
  },
  AvgDialog_142852_Content_115 = {
    Text = "Lass mich leben, lass mich zur Sternenwal gehen ... Ich gebe dir alles, was du willst!"
  },
  AvgDialog_142852_Content_116 = {
    Text = "Und dieses Kind... du willst nicht, dass {Male=him,Female=her} stirbt, oder? Ich kann es erkennen... Du hast {Male=him,Female=her} durch diesen brutalen Kampf beschützt..."
  },
  AvgDialog_142852_Content_117 = {
    Text = "Der Tod näherte sich Elian unaufhörlich. Seine Stimme begann zu zittern."
  },
  AvgDialog_142852_Content_118 = {
    Text = "Ah!!!——"
  },
  AvgDialog_142852_Content_119 = {
    Text = "Der scharfe Dolch bohrt sich tief in deine Schulter. Dein qualvoller Schrei hallt durch die Arena."
  },
  AvgDialog_142852_Content_12 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_142852_Content_120 = {
    Text = "Lotan! Wenn Du noch einen Schritt näher kommst, stirbt dieser Mensch seinetwegen!"
  },
  AvgDialog_142852_Content_121 = {
    Text = "Du tötest nie Unschuldige ... Du willst nie, dass Unschuldige wegen Dir sterben! Genau, genau!! Ich kann mich in Menschen nicht täuschen!!"
  },
  AvgDialog_142852_Content_122 = {
    Text = "Der Dolch dreht sich in dir, begleitet von deinen nicht enden wollenden Schreien."
  },
  AvgDialog_142852_Content_123 = {
    Text = "Lotan wirkte ruhig, als würde Sie nichts hören. Sie trug ihr großes Schwert und schritt auf Elian zu, so gleichmäßig wie ein Spaziergang am Nachmittag."
  },
  AvgDialog_142852_Content_124 = {
    Text = "Ich schätze aufrichtige Menschen. Aufrichtige Mordlust, aufrichtige Stärke, aufrichtigen Ruhm, aufrichtige Weisheit und Verschlagenheit."
  },
  AvgDialog_142852_Content_125 = {
    Text = "Aber Du, Elian ..."
  },
  AvgDialog_142852_Content_126 = {
    Text = "Lotan schüttelte verächtlich den Kopf."
  },
  AvgDialog_142852_Content_127 = {
    Text = "Du hast nicht einmal herausgefunden, was mir wichtig ist."
  },
  AvgDialog_142852_Content_128 = {
    Text = "Du bist nichts."
  },
  AvgDialog_142852_Content_13 = {
    Text = "Zwei Windstöße fegen an dir vorbei, und warme Flüssigkeit spritzt auf dich."
  },
  AvgDialog_142852_Content_130 = {
    Text = "Ein sauberer, präziser Schwertstreich blitzte auf. Dies Politiker, der sechs Reiche durchquert hatte, empfing sein Ende mit überraschten, kraftlosen Augen."
  },
  AvgDialog_142852_Content_131 = {
    Text = "In der gesamten Arena atmeten nur noch zwei Wesen. Das große Schwert in Lotans Hand triefte von Blut, und ihr eiskalter Blick richtete sich auf Dich."
  },
  AvgDialog_142852_Content_14 = {
    Text = "Du spürst keinen Schmerz, und der Tod scheint noch nicht erschienen zu sein. Du nimmst die Hände von deinen Augen und siehst zwei frische Köpfe, die dich mit widerwillig aufgerissenen Augen anstarren."
  },
  AvgDialog_142852_Content_15 = {Text = "ARGH!!"},
  AvgDialog_142852_Content_16 = {
    Text = "Du weichst hastig zwei Schritte zurück und stolperst dabei fast über Gracchus' halbe Leiche."
  },
  AvgDialog_142852_Content_17 = {
    Text = "Ha, die Schwestern Vaughn — zwei so berühmte Kopfgeldjägerinnen. Die Könige aller sechs Königreiche haben unzählige Wege versucht, sie anzuwerben, und sind doch gescheitert."
  },
  AvgDialog_142852_Content_18 = {
    Text = "Nun haben sie ihre einzige gescheiterte Jagd erlebt."
  },
  AvgDialog_142852_Content_19 = {
    Text = "Inmitten des tosenden Jubels des Phantasma-Publikums schritt Aelian zufrieden über die Leichen."
  },
  AvgDialog_142852_Content_2 = {
    Text = "Die ringförmigen Steinmauern der Arena ragen hoch empor, und die Tribünen sind voll mit aufmerksamen Phantasmas gedrängt."
  },
  AvgDialog_142852_Content_20 = {
    Text = "Anders als ich es mir vorgestellt hatte, aber das macht nichts. Unsere Feinde sind fast alle gefallen. Jetzt, denke ich, brauchst du Ruhe..."
  },
  AvgDialog_142852_Content_21 = {
    Text = "Ein donnerndes Hufgetrappel mit heulenden Sturmböen unterbrach Aelians Worte und erschien plötzlich hinter Aelian und dir."
  },
  AvgDialog_142852_Content_22 = {
    Text = "Bevor du reagieren konntest, hob Lotan dich hoch und warf dich zur Seite."
  },
  AvgDialog_142852_Content_23 = {
    Text = "<RedBigShake:Stirb — !>"
  },
  AvgDialog_142852_Content_24 = {
    Text = "Das laute Wiehern des Schlachtrosses hallte durch die Arena. Im Staub zog ein General in alter Rüstung sein galoppierendes Pferd zurück und rammte den Dorn seiner Heeresfahne in die Brust eines Ritters, der nicht schnell genug ausweichen konnte."
  },
  AvgDialog_142852_Content_25 = {
    Text = "Der sich langsam lichtende Staub zeichnete die Silhouette einer nicht besonders massigen Gestalt. Er zog leicht an den Zügeln, wandte sich mit seinem Pferd um, und seine Augen, die schon unzählige Schlachtfelder gesehen hatten, ruhten gelassen auf euch."
  },
  AvgDialog_142852_Content_26 = {
    Text = "Unbeabsichtigt trafen sich deine Augen mit seinen. Ein gewaltiger Druck ließ deine Knie weich werden, und du konntest Fast nicht mehr stehen."
  },
  AvgDialog_142852_Content_27 = {
    Text = "Der Staub verzog sich. Du sahst die alte Rüstung aus der Legende, die siebzig Risse trug, und das gepanzerte Schlachtross, das einst durch alle sechs Königreiche gestampft war und nun stolz Dampf aus den Nüstern blies."
  },
  AvgDialog_142852_Content_28 = {
    Text = "Vier bluttriefende Köpfe hingen an den Seiten des Schlachtrosses – eine Gewohnheit, die der Alte Mann seit seiner Kindheit gepflegt hatte."
  },
  AvgDialog_142852_Content_29 = {
    Text = "General Alish."
  },
  AvgDialog_142852_Content_3 = {
    Text = "In den Tiefen des dunkelroten Himmels, gleich einem Morast, gleitet ein riesiger, walförmiger Schatten langsam dahin."
  },
  AvgDialog_142852_Content_30 = {
    Text = "Du bemerkst, dass sich Lotans Tonfall zum ersten Mal deutlich verändert. Ihre Stimme ist rau und voller Begeisterung, wie ein Löwe, der die Witterung seiner Beute aufgenommen hat."
  },
  AvgDialog_142852_Content_31 = {
    Text = "Sag mir, wie heißt mein Gegner."
  },
  AvgDialog_142852_Content_32 = {
    Text = "Du kannst mich Lotan nennen."
  },
  AvgDialog_142852_Content_33 = {
    Text = "Lotan... Die meisten, die es wert sind, mit ihnen zu kämpfen, kenne ich. Aber an diesen Namen erinnere ich mich nicht."
  },
  AvgDialog_142852_Content_34 = {
    Text = "Vielleicht weil die meisten, die diesen Namen gehört haben, bereits tot sind. Das spielt keine Rolle. In fünf Minuten wirst Du meinen Namen nicht mehr vergessen."
  },
  AvgDialog_142852_Content_35 = {
    Text = "Ha... Diese Welt bringt ständig Veränderungen hervor, an die ich mich kaum anpassen kann. Vielleicht haben die jungen Leute von heute tatsächlich das Zeug, mir Respekt abzunötigen."
  },
  AvgDialog_142852_Content_36 = {
    Text = "Seit dem Beginn des Wettkampfs ist bereits eine halbe Stunde vergangen. Dass Du bis jetzt überlebt hast, beweist, dass Deine Stärke Deiner Arroganz ebenbürtig ist."
  },
  AvgDialog_142852_Content_37 = {
    Text = "Sie missverstehen uns, General Alish – wir sind nicht Ihre Feinde."
  },
  AvgDialog_142852_Content_38 = {
    Text = "Tritt beiseite, Elian."
  },
  AvgDialog_142852_Content_39 = {
    Text = "(leise) Frau Lotan, bitte vergessen Sie nicht den Plan, den wir zuvor ausgearbeitet haben. Wir sollten jetzt zuerst die anderen Feinde ausschalten. Alish ist alt und schwach – wenn seine Kräfte nachlassen..."
  },
  AvgDialog_142852_Content_4 = {
    Text = "Hat Er schon immer so gerne zugeschaut?"
  },
  AvgDialog_142852_Content_40 = {
    Text = "Ich sagte, tritt beiseite."
  },
  AvgDialog_142852_Content_41 = {
    Text = "Elian hatte viele gefährliche Menschen erlebt, und Lotans Stimme war im Vergleich zu ihnen keineswegs aufgewühlt – doch diese kühlen Worte erfüllten ihn mit einer Angst, wie er sie noch nie zuvor gespürt hatte."
  },
  AvgDialog_142852_Content_42 = {
    Text = "Er dachte nicht lange nach und trat mit gleichmütigem Gesicht zur Seite."
  },
  AvgDialog_142852_Content_43 = {
    Text = "In dieser Arena sind nur noch wenige übrig. Nur einen Gegner gibt es, der es wert ist, dass ich ihn herausfordere."
  },
  AvgDialog_142852_Content_44 = {
    Text = "Lotan legte die Hand an den Griff des Großschwertes und schritt in Alishs Richtung."
  },
  AvgDialog_142852_Content_45 = {
    Text = "Die Erscheinungen auf den Tribünen verstummen vollständig, ihre gesichtslosen Antlitze drehen sich wie auf Kommando, um Lotans Schritten zu folgen."
  },
  AvgDialog_142852_Content_46 = {
    Text = "Das tiefe Summen in der Luft wurde immer deutlicher – wie eine uralte, gierige Erwartung."
  },
  AvgDialog_142852_Content_47 = {
    Text = "Ich habe Dich kämpfen sehen, junger Mensch. In meinen siebzig Jahren auf dem Schlachtfeld habe ich noch nie einen Gegner getroffen, der so stark war wie Du."
  },
  AvgDialog_142852_Content_48 = {
    Text = "In dieser Arena befinden sich die mächtigsten Gegner der Welt. Jeder will zuerst angreifen, aber Du nicht. Du wartest immer darauf, dass Dein Gegner zuerst das Schwert zieht..."
  },
  AvgDialog_142852_Content_49 = {
    Text = "Kannst Du mir sagen, warum?"
  },
  AvgDialog_142852_Content_5 = {
    Text = "Lotan schüttelte den Kopf und zog das Großschwert aus dem Leichnam zu seinen Füßen."
  },
  AvgDialog_142852_Content_50 = {
    Text = "Weil... ein Gegner, der sein Schwert zieht, etwas stärker wird."
  },
  AvgDialog_142852_Content_51 = {
    Text = "Etwas... stärker?"
  },
  AvgDialog_142852_Content_52 = {
    Text = "Mich interessieren nur stärkere Dinge. Hebe Deine Kriegsfahne, Alish."
  },
  AvgDialog_142852_Content_53 = {
    Text = "Lotans Worte enthielten nicht den geringsten Hauch von Provokation. Sie legte ihre Hand auf das Großschwert, die Augen fest auf Das greisen General gerichtet, ihre Schritte so feierlich wie die eines Pilgers."
  },
  AvgDialog_142852_Content_54 = {
    Text = "Hehe... Hahaha!"
  },
  AvgDialog_142852_Content_55 = {
    Text = "Der alte General warf den Kopf zurück und lachte. Sein Schlachtross stand reglos da, Mensch und Pferd standen allein in der Mitte der Arena, die blutrot gefärbte Fahne flatterte Unordentlich im Wind."
  },
  AvgDialog_142852_Content_56 = {
    Text = "Sehr ähnlich. Wirklich sehr ähnlich... Wären wir etwas jünger, könnten wir vielleicht in dieser Welt unser zweites Ich erblicken."
  },
  AvgDialog_142852_Content_57 = {
    Text = "Wie auch immer... Ich hoffe, wir werden einander nicht enttäuschen!"
  },
  AvgDialog_142852_Content_58 = {
    Text = "Alishs Stimme erhebt sich plötzlich, seine Beine treiben sein Reittier gekonnt an. Das Streitross, das ihn durch unzählige Feldzüge getragen hat, prescht vor, sein durchdringendes Wiehern hallt durch die weite Arena –"
  },
  AvgDialog_142852_Content_59 = {
    Text = "Die Fahne wehte empor, wie ein roter Blitz, der den Staub in der Mitte der Arena zerriss, und stürmte auf Lotan zu."
  },
  AvgDialog_142852_Content_6 = {
    Text = "Die durchbohrten Knochen rieben sich mit einem zahnschmerzenden Geräusch an der Klinge, der massige Körper wurde in zwei Hälften gerissen, und die widerwilligen Augen rollten mit der halben Leiche in die blutgetränkte Gosse."
  },
  AvgDialog_142852_Content_60 = {
    Text = "Du siehst, wie sich Lotans Mundwinkel unwillkürlich nach oben zogen. Es ist das erste Mal, dass Du Lotans Lächeln siehst."
  },
  AvgDialog_142852_Content_61 = {
    Text = "Sie zog das Großschwert und stürmte dem roten Blitz entgegen —"
  },
  AvgDialog_142852_Content_62 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_142852_Content_63 = {
    Text = "Boom!!! —"
  },
  AvgDialog_142852_Content_64 = {
    Text = "Das weiße Großschwert prallte auf die rote Kriegsfahne, und ein hochfrequentes, schrilles Geräusch ließ das Trommelfell jedes Einzelnen erzittern."
  },
  AvgDialog_142852_Content_65 = {
    Text = "Die Eisenhufe des Schlachtrosses wirbelten Staub auf, und die Silhouetten von Lotan und Alish kreuzten sich auf dem düsteren Schlachtfeld."
  },
  AvgDialog_142852_Content_66 = {
    Text = "Bei jedem Aufprall zuckte der Schatten des riesigen Wals am Himmel heftig zusammen, Als ob er Makabre Delikatessen von seltener Güte kostete."
  },
  AvgDialog_142852_Content_67 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_142852_Content_68 = {
    Text = "General Alish... Lady Lotan..."
  },
  AvgDialog_142852_Content_69 = {
    Text = "Was für ein erstaunlicher Kampf..."
  },
  AvgDialog_142852_Content_7 = {
    Text = "Wie hatte er sich noch gleich genannt?"
  },
  AvgDialog_142852_Content_70 = {
    Text = "Du strengst deine Augen an, um die Silhouetten der beiden zu erfassen, doch sie sind kaum zu erkennen."
  },
  AvgDialog_142852_Content_71 = {
    Text = "Vira, leg los."
  },
  AvgDialog_142852_Content_72 = {
    Text = "Ja, Herr Elian."
  },
  AvgDialog_142852_Content_73 = {Text = "!!!"},
  AvgDialog_142852_Content_74 = {
    Text = "Das ist ... der Giftmischer-Magier aus dem Anwesen des Premierministers?! Lady Lotan! Vorsicht ..."
  },
  AvgDialog_142852_Content_75 = {
    Text = "Deine Worte bleiben unvollendet, als sich ein eiskaltes Gefühl auf deine Haut legt."
  },
  AvgDialog_142852_Content_76 = {
    Text = "Pst ... kleiner Spatz. Du warst mir stets treu ergeben. Willst du mich jetzt wegen eines Fremden verraten?"
  },
  AvgDialog_142852_Content_77 = {
    Text = "Ich ... aber ..."
  },
  AvgDialog_142852_Content_78 = {
    Text = "Ich habe versprochen: Sobald ich die Krone des Sternenhimmels-Wals erlangt habe und zum Hochkönig der sechs Reiche geworden bin, werden deine Familie und du selbst den verdienten Lohn erhalten."
  },
  AvgDialog_142852_Content_79 = {
    Text = "Aber jetzt halt deinen Mund."
  },
  AvgDialog_142852_Content_8 = {
    Text = "Gracchus... der berühmteste Gladiator des gesamten Nordens, der in den Arenen aller sechs Königreiche noch nie eine Niederlage erlitten hatte..."
  },
  AvgDialog_142852_Content_80 = {
    Text = "Die Kehle bewegt sich. Nur wer ein Sklave ist, weiß, wie verführerisch Elians Worte sind."
  },
  AvgDialog_142852_Content_81 = {
    Text = "Du beobachtest, wie der Giftmischer sich verbirgt und im wirbelnden Staub verschwindet. Du sagst nichts mehr."
  },
  AvgDialog_142852_Content_82 = {Text = "Hm?"},
  AvgDialog_142852_Content_83 = {
    Text = "Der im vollen Galopp reitende General erhascht einen Blick auf eine im Staub versinkende Gestalt und runzelt die Stirn. Das lässt ihn einen Moment zögern."
  },
  AvgDialog_142852_Content_84 = {
    Text = "Als das gewaltige Schwert erneut auf ihn niederfährt, kann er nur noch die Kriegsfahne heben, um den Schlag notdürftig abzuwehren."
  },
  AvgDialog_142852_Content_85 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_142852_Content_86 = {
    Text = "Ein gewaltiger Aufprall — das Schlachtross stolpert und stürzt zu Boden. Die blutrote Kriegsfahne bricht entzwei, und eine riesige Klinge liegt an seiner Kehle."
  },
  AvgDialog_142852_Content_87 = {
    Text = "Du wirst langsamer, Alish."
  },
  AvgDialog_142852_Content_88 = {
    Text = "... Dein Verbündeter hat dich verraten."
  },
  AvgDialog_142852_Content_89 = {
    Text = "Ist das von Bedeutung?"
  },
  AvgDialog_142852_Content_9 = {
    Text = "Du hast schon viele Tote gesehen, doch der Anblick vor dir lässt deinen Magen rebellieren."
  },
  AvgDialog_142852_Content_90 = {
    Text = "Was... sagst du?"
  },
  AvgDialog_142852_Content_91 = {
    Text = "Lotan seufzt leise, und in diesem kaum hörbaren Seufzer liegt tiefes Bedauern."
  },
  AvgDialog_142852_Content_92 = {
    Text = "Du warst nah dran, Alish, aber nicht nah genug. Jenseits von Stärke und Kampf hegst du noch andere Sehnsüchte — Ehre."
  },
  AvgDialog_142852_Content_93 = {
    Text = "Du legst zu viel Wert auf solch bedeutungslose Dinge. Du bist noch nicht rein genug."
  },
  AvgDialog_142852_Content_94 = {
    Text = "Lotan öffnet die Augen, schüttelt den Kopf und ignoriert dabei völlig den Schatten, der sich hinter ihr versteckt."
  },
  AvgDialog_142852_Content_95 = {
    Text = "Du glaubst, mit Elians Hilfe und euch allen zusammen gegen mich – das wäre kein ehrlicher Sieg."
  },
  AvgDialog_142852_Content_96 = {
    Text = "Sollte es nicht so sein? Zwei Menschen mit ähnlichen Fähigkeiten und Gedanken, ein gerechtes Duell..."
  },
  AvgDialog_142852_Content_97 = {
    Text = "Schau dir an, wie viele Worte du benutzt. Ehre, Gerechtigkeit, Würde... alles Ketten, die Schwache sich selbst schmieden."
  },
  AvgDialog_142852_Content_98 = {
    Text = "Krieger sind von Geburt an nur zum Kämpfen da. Der Kampf... ist gerade nur Kampf. Er hat mit nichts anderem zu tun."
  },
  AvgDialog_142852_Content_99 = {
    Text = "Der Schatten am Himmel hält inne und lässt ein freudiges Grollen ertönen."
  },
  AvgDialog_142853_Content_1 = {
    Text = "Der zweite Abschnitt"
  },
  AvgDialog_142853_Content_10 = {
    Text = "Ich meine... Herrin Lotan... könntet Ihr nicht ein wenig langsamer gehen..."
  },
  AvgDialog_142853_Content_100 = {
    Text = "Lady Lotan... glaubt ihm nicht! Er ist ein Betrüger... Ich war an seiner Seite und habe gesehen, wie er unzählige Verbrechen begangen hat..."
  },
  AvgDialog_142853_Content_101 = {
    Text = "Ich bin überzeugt, dass Ihr nicht mit jemandem wie ihm zusammenarbeiten würdet..."
  },
  AvgDialog_142853_Content_102 = {
    Text = "Du winkst Lotan wiederholt ab. Du willst sie warnen, was für ein hinterhältiger Mensch Elian ist."
  },
  AvgDialog_142853_Content_103 = {
    Text = "Vom Sklave zum Händler, vom Händler zum Adligen, vom Adligen zum Kanzler – Elian hinterließ auf seinem mühsamen Weg unzählige Spuren, und jede einzelne davon war durchtränkt von Eine Lüge und Blutfest."
  },
  AvgDialog_142853_Content_104 = {
    Text = "Doch Lotan sah Dich nicht an. Sie wandte den Kopf und blickte zum dunkelroten Himmelszelt empor. Der riesige, walförmige Schatten bewegte sich noch immer langsam, seine mit Knochenstacheln bedeckten Umrisse tauchten mal auf, mal unter."
  },
  AvgDialog_142853_Content_105 = {
    Text = "Tretet zur Seite."
  },
  AvgDialog_142853_Content_106 = {
    Text = "Du trittst benommen zur Seite. Lotan geht an Dir vorbei und blickt auf den Kanzler vor ihr hinab. Das dunkelrote Licht zeichnet hinter ihr eine scharfe Silhouette."
  },
  AvgDialog_142853_Content_107 = {
    Text = "Ihr seid weitaus interessanter als Euer Ritterorden, Elian. Es ist mir gleichgültig, was für ein Mensch Ihr seid, und ich kümmere mich nicht darum, wann Ihr mich verraten werdet. Ihr könnt mir nützlich sein – das genügt."
  },
  AvgDialog_142853_Content_108 = {
    Text = "Ich stimme Eurer Bitte zu. Stört meinen Kampf nicht – das ist meine einzige Forderung."
  },
  AvgDialog_142853_Content_109 = {
    Text = "Lady Lotan... Ihr..."
  },
  AvgDialog_142853_Content_11 = {
    Text = "Den ganzen Weg über habt Ihr kaum gesprochen, Ihr habt nur getötet und seid weitergelaufen, ohne wirklich zu rasten..."
  },
  AvgDialog_142853_Content_110 = {
    Text = "Die Gier nach Macht, die durch die Luft strömt, überrollt dich wie eine Flut. Ein bitteres Lächeln schleicht sich auf dein Gesicht. Alle hier sind gleich – du hättest nichts anderes erwarten sollen."
  },
  AvgDialog_142853_Content_111 = {
    Text = "Elian grinste breit; in seiner Miene war nicht der geringste Hauch von Transzendenz über die freudige Überraschung zu erkennen, als ob dies eine Verhandlung gewesen wäre, die er mit Sicherheit gewinnen würde."
  },
  AvgDialog_142853_Content_112 = {
    Text = "Er drehte sich um und schritt zur Zuschauertribüne am Rand der Arena."
  },
  AvgDialog_142853_Content_113 = {
    Text = "Die Informationen über Alle, die Gruppen, die sie bilden werden, den Zeitpunkt, zu dem sie auseinanderbrechen werden, und die Reihenfolge der Herausforderungen, die Euch am meisten erfreuen wird – ich habe mir bereits alles für Euch überlegt."
  },
  AvgDialog_142853_Content_114 = {
    Text = "Genießt diesen Kampf, Lady Lotan."
  },
  AvgDialog_142853_Content_12 = {
    Text = "Willst du selbst den Mund halten, oder soll ich dir mein Schwert hineinstecken?"
  },
  AvgDialog_142853_Content_13 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_142853_Content_14 = {
    Text = "Du presst die Hand fest auf deinen Mund. Lotans Blick verweilt nicht auf dir. Sie beobachtet die Umgebung und streicht mit der Hand über ein abgebrochenes Steinsäulenstück."
  },
  AvgDialog_142853_Content_15 = {
    Text = "Die Bruchfläche der Steinsäule ist übersät mit schwarzen, adern-ähnlichen Mustern, als würde das Gewebe eines lebenden Wesens dort wachsen."
  },
  AvgDialog_142853_Content_16 = {Text = "Das ist..."},
  AvgDialog_142853_Content_17 = {
    Text = "Du legst dein Ohr an die Steinsäule und nimmst undeutlich einen äußerst tiefen Rhythmus wahr, als würde ein riesiges Lebewesen tief im Stein langsam atmen."
  },
  AvgDialog_142853_Content_18 = {
    Text = "Ein grundloser Ekel und ein Drang zu töten strömen in deinen Körper – du weichst rasch zurück."
  },
  AvgDialog_142853_Content_19 = {
    Text = "Dieses Ding ... ist es lebendig?!"
  },
  AvgDialog_142853_Content_2 = {
    Text = "Das ist der Weg, den du uns führst?"
  },
  AvgDialog_142853_Content_20 = {
    Text = "Der Legende nach erschuf der Wal des Sternenhimmels mit seinem Körper diese Welt, und die Bewohner der sechs Reiche existieren alle auf seinem Leib."
  },
  AvgDialog_142853_Content_21 = {
    Text = "Es scheint, als wären wir ihm schon sehr nahe."
  },
  AvgDialog_142853_Content_22 = {
    Text = "Lotan geht auf einen Steintisch in der Mitte des Platzes zu. Dieser aus Lapislazuli gefertigte Steintisch wirkt mit seiner feinen Verarbeitung und dem kostbaren Material an diesem trostlosen Ort völlig fehl am Platz."
  },
  AvgDialog_142853_Content_23 = {
    Text = "Die Oberfläche des Steintisches ist mit einer Schicht feiner, feuchter Schuppen bedeckt, die sich im schwachen Licht langsam öffnen und schließen – im selben Rhythmus wie der Atem, den du gerade gehört hast."
  },
  AvgDialog_142853_Content_24 = {
    Text = "Lotan legt die beiden Knochensiegel darauf. In dem Moment, in dem die Schuppen die Siegel berühren, schließen sie sich wie unzählige Finger, die ihre Beute greifen, und verschlingen die beiden Siegel vollständig."
  },
  AvgDialog_142853_Content_25 = {
    Text = "Unsere Knochensiegel!!!"
  },
  AvgDialog_142853_Content_26 = {
    Text = "Ah! Zwei neue Herausforderer!"
  },
  AvgDialog_142853_Content_27 = {
    Text = "Als du auf den Steintisch zustürzt, steigt langsam eine menschliche Silhouette aus der Mitte des Steintisches empor."
  },
  AvgDialog_142853_Content_28 = {
    Text = "Ihr Gesicht wechselt unaufhörlich – mal ist es ein König, mal ein Ritter, mal etwas, das du nicht erkennen kannst."
  },
  AvgDialog_142853_Content_29 = {
    Text = "Ihre Stimme klingt, als käme sie aus den Tiefen einer Blutlache, und jede Silbe trägt eine seltsame Resonanz."
  },
  AvgDialog_142853_Content_3 = {
    Text = "Wir suchen die Arena, keine Ruinen. Dieser Ort wirkt seit vielen Jahren verlassen."
  },
  AvgDialog_142853_Content_30 = {
    Text = "Ich bin das Phantasma des Wals des Sternenhimmels, sein treuester Diener und zugleich Verwalter und Publikum dieser Arena."
  },
  AvgDialog_142853_Content_31 = {
    Text = "Ihr habt unzählige Gefahren überstanden und seid schließlich durch eure eigene Stärke und Klugheit hierher gelangt. Ihr seid der Stolz der sechs Reiche, die mächtigsten und zähesten ..."
  },
  AvgDialog_142853_Content_32 = {
    Text = "Spare dir die langen Reden."
  },
  AvgDialog_142853_Content_33 = {
    Text = "... Du bist ziemlich unhöflich, Herausforderer. Zum Glück kümmert sich der Wal des Sternenhimmels nie darum."
  },
  AvgDialog_142853_Content_34 = {
    Text = "Das Einzige, worum er sich kümmert, ist Stärke. Reine, unverfälschte Stärke, ohne den kleinsten Nebengedanken."
  },
  AvgDialog_142853_Content_35 = {
    Text = "Willkommen, willkommen in der Arena des Sternenhimmels-Wals, willkommen auf der Bühne der reinen Stärke——"
  },
  AvgDialog_142853_Content_36 = {
    Text = "Das Phantasma hob beide Arme, ein tiefer, weitreichender Klang wie ein Walgesang strömte aus seinem Inneren, durchdrang deine Knochen und hallte in deiner Schädelhöhle als Resonanz wider."
  },
  AvgDialog_142853_Content_37 = {
    Text = "!!!Das ist..."
  },
  AvgDialog_142853_Content_38 = {
    Text = "Das Lied breitet sich aus. Wo immer es hinweht, wird der Himmel in ein düsteres Rot getaucht. Die bröckelnden Ruinen, zusammengehalten von einem unidentifizierbaren Schleim, formen sich zu einer großen, alten Arena."
  },
  AvgDialog_142853_Content_39 = {
    Text = "Die riesigen Götterstatuen ringsum hielten verschiedene Gesten inne und blickten mit mitleidigen oder wütenden Augen auf die winzigen Wesen zu ihren Füßen herab."
  },
  AvgDialog_142853_Content_4 = {
    Text = "Ich kenne die Karte auswendig, es müsste genau dieser Ort sein... aber warum sieht es hier anders aus als in den Aufzeichnungen?"
  },
  AvgDialog_142853_Content_40 = {
    Text = "Ein Dutzend oder so Herausforderer stehen verstreut auf der Plattform und mustern dich."
  },
  AvgDialog_142853_Content_41 = {
    Text = "Eins, zwei, drei ... fünfzehn, sechzehn."
  },
  AvgDialog_142853_Content_42 = {
    Text = "Es gibt insgesamt zwanzig Knochensiegel – es sollten noch zwei weitere Personen kommen..."
  },
  AvgDialog_142853_Content_43 = {
    Text = "Es gibt keine weiteren Herausforderer. Diese beiden Siegel wurden bereits in der vorherigen Runde vernichtet."
  },
  AvgDialog_142853_Content_44 = {
    Text = "Herzlichen Glückwunsch. Als Letzte einzutreffen bringt dir die Ehre, im Mittelpunkt aller Aufmerksamkeit zu stehen –"
  },
  AvgDialog_142853_Content_45 = {
    Text = "Im leichtfüßigen Lachen des Phantasmas richteten sich sechzehn feindselige Blicke auf euch."
  },
  AvgDialog_142853_Content_46 = {
    Text = "Diese Person kommt mir so bekannt vor ... Habe ich sie nicht irgendwo auf einem Werbeplakat einer Gladiatorenarena gesehen?"
  },
  AvgDialog_142853_Content_47 = {
    Text = "Diese Kleidung ... Die gehört doch zu der Killerorganisation namens Kleiner Finger! Ich hätte nicht gedacht, dass ich hier jemandem von denen begegnen würde ..."
  },
  AvgDialog_142853_Content_48 = {
    Text = "Du weißt ganz schön viel."
  },
  AvgDialog_142853_Content_49 = {
    Text = "Bei den Sitzungen des Ritterordens durfte ich nicht sprechen, aber ich habe viele Male zugehört. Lord Elian hat uns viel erzählt ..."
  },
  AvgDialog_142853_Content_5 = {
    Text = "Du betrachtest die jahrelang vom Wind verwitterten Mauerreste in deiner Umgebung und kratzt dich am Kopf."
  },
  AvgDialog_142853_Content_50 = {
    Text = "Ah! Schau dort drüben!! Diese Person in der alten Rüstung!"
  },
  AvgDialog_142853_Content_51 = {
    Text = "Das ist der tapferste General der sechs Nationen! Er hat einst im Alleingang auf dem Schlachtfeld den König eines Feindesstaates getötet — ich bin mit seinen Geschichten aufgewachsen!"
  },
  AvgDialog_142853_Content_52 = {
    Text = "Eins lebende Legende! Ich hätte nicht gedacht ... nicht gedacht, dass ich ihn hier treffen würde!"
  },
  AvgDialog_142853_Content_53 = {
    Text = "Lotan beachtete deine nicht zu inhibierenden begeisterten Ausrufe nicht. Sie warf einen Blick auf die Teilnehmer, lehnte sich an eine Steinsäule und schloss die Augen."
  },
  AvgDialog_142853_Content_54 = {
    Text = "Bevor der Ritterorden an diesem Wettkampf teilnahm, habe ich mit der Herrin eine Wette abgeschlossen, wer derjenige sein würde, der in den Palast des Sternenhimmels-Wals gelangt."
  },
  AvgDialog_142853_Content_55 = {
    Text = "Du hast das sehr gut gemacht, kleiner Spatz. Nachdem dieses ermüdende Spiel vorbei ist, wird die Herrin mir eine ganze Menge Geld schulden."
  },
  AvgDialog_142853_Content_56 = {Text = "!!!"},
  AvgDialog_142853_Content_57 = {
    Text = "E... Elian, mein Herr..."
  },
  AvgDialog_142853_Content_58 = {
    Text = "Sanfte Stimme, ruhige Schritte, ein weites Gewand aus edlem Stoff, der Duft von Wacholderbeeren-Parfüm... Selbst wenn du zu Asche wärst, würdest du ihn erkennen."
  },
  AvgDialog_142853_Content_59 = {
    Text = "Ihr... wie kommt es, dass Ihr persönlich... ich meine..."
  },
  AvgDialog_142853_Content_6 = {
    Text = "Der König schrieb in seinem Tagebuch, die Mauern hier seien aus Gold gefertigt, am Himmel kreisten sechsflügelige Götterboten, und in den Flüssen flössen Honig und Wein..."
  },
  AvgDialog_142853_Content_60 = {
    Text = "Ihr habt den Ritterorden beauftragt, Euch die Krone zu erstreiten, ich dachte..."
  },
  AvgDialog_142853_Content_61 = {
    Text = "Du dachtest, ich würde all meine Hoffnung auf einen Ritterorden setzen, der nicht einmal gegen Söldner bestehen kann? Ich habe es dir beigebracht, kleiner Spatz – lege niemals alle Eier in denselben Korb."
  },
  AvgDialog_142853_Content_62 = {
    Text = "Bitte habt etwas Vertrauen in den gütigen Elian. Der große Sternenhimmelwal schenkt stets den Guten seinen Segen."
  },
  AvgDialog_142853_Content_63 = {
    Text = "Der Adlige lächelt elegant. Sein Blick hat Lotan nie verlassen."
  },
  AvgDialog_142853_Content_64 = {
    Text = "Dies ist... deine Freundin?"
  },
  AvgDialog_142853_Content_65 = {
    Text = "Nun, das würde ich vielleicht nicht ganz so sagen..."
  },
  AvgDialog_142853_Content_66 = {
    Text = "Lotan. Eine Kriegerin."
  },
  AvgDialog_142853_Content_67 = {
    Text = "Es freut mich, Euch zu treffen, Herrin Lotan. Ich hoffe, meine Hausdiener haben Euch keine Umstände bereitet."
  },
  AvgDialog_142853_Content_68 = {
    Text = "Der Kanzler?"
  },
  AvgDialog_142853_Content_69 = {
    Text = "Lotans Blick glitt über die Verzierungen seiner Kleidung und des Schwertes an seiner Hüfte. Selbst wer sich nicht im Geringsten für die Politik der sechs Reiche interessierte, konnte die Imprägnierung des Kanzlers mühelos erkennen."
  },
  AvgDialog_142853_Content_7 = {
    Text = "Was hat es nun mit diesem ruinengleichen Platz auf sich... auch niemand zu sehen, der die Knochensiegel prüft."
  },
  AvgDialog_142853_Content_70 = {
    Text = "Lediglich ein Ehrentitel ohne Befugnisse – sein einziger Nutzen besteht darin, mir die Selbstvorstellung zu ersparen."
  },
  AvgDialog_142853_Content_71 = {
    Text = "Elian lächelte und setzte sich auf die Steinsäule vor Lotan."
  },
  AvgDialog_142853_Content_72 = {
    Text = "Du bringst mir meine Dienerin hierher, doch mein Ritterorden ist nirgends zu sehen. Ich glaube, ich kann mir bereits denken, was auf dem Weg geschehen ist."
  },
  AvgDialog_142853_Content_73 = {
    Text = "Dein Ritterorden ist auf erbärmliche Weise gestorben. Zwölf Mann, die nicht einmal die Rüstung eines drittklassigen Kriegers berührt haben."
  },
  AvgDialog_142853_Content_74 = {
    Text = "Und du hast diesen Kampf mit Leichtigkeit gewonnen."
  },
  AvgDialog_142853_Content_75 = {
    Text = "Ihr Tod scheint dich nicht im Geringsten zu interessieren."
  },
  AvgDialog_142853_Content_76 = {
    Text = "Ah, nein, nein, nein, Ihr missversteht mich, Herrin Lotan..."
  },
  AvgDialog_142853_Content_77 = {
    Text = "Elian lacht laut auf und schüttelt den Kopf."
  },
  AvgDialog_142853_Content_78 = {
    Text = "Meine Ritter sind alle brave Kinder, loyal, fleißig ... aber dies ist die Arena des Sternenwals. Die Schwachen haben das Ende gefunden, das den Schwachen gebührt. Das kümmert mich nicht."
  },
  AvgDialog_142853_Content_79 = {
    Text = "Was mich kümmert, bist Du, Lady Lotan. Eine mächtige Kriegerin, die Klingen, das Töten und das Blutfest liebt, bereit, alles für jene aus Blut geschmiedete Krone zu opfern ..."
  },
  AvgDialog_142853_Content_8 = {
    Text = "Hey! Warte auf mich..."
  },
  AvgDialog_142853_Content_80 = {
    Text = "Elians Redetempo wird immer schneller. Der in der Luft liegende Hauch von Töten und Machtgier durchdringt ihn und lässt selbst sein vom Leben gezeichnetes Herz unkontrolliert höherschlagen."
  },
  AvgDialog_142853_Content_81 = {
    Text = "Als ob er seine eigene Fasungslosigkeit bemerkt, atmet er tief durch und tritt einen halben Schritt zurück."
  },
  AvgDialog_142853_Content_82 = {
    Text = "Ich denke, wir könnten zusammenarbeiten."
  },
  AvgDialog_142853_Content_83 = {
    Text = "Glaubst Du, ich bin jemand, der gerne zusammenarbeitet?"
  },
  AvgDialog_142853_Content_84 = {
    Text = "Schwache neigen dazu, sich zusammenzurotten — Du bist natürlich nicht so jemand. Aber jeder hat irgendwann das Bedürfnis nach Zusammenarbeit, Du bist da keine Ausnahme."
  },
  AvgDialog_142853_Content_85 = {
    Text = "Lotan hat noch nicht geantwortet, da erscheinen unzählige, völlig identische Phantasmen auf den Sitzen der Arena und füllen die dicht gedrängten Zuschauerränge. Die walgesangartige Stimme hallt erneut durch die leere Arena."
  },
  AvgDialog_142853_Content_86 = {
    Text = "Nun denn, Herausforderer — wir können es kaum erwarten. Die letzte Prüfung wird gleich in dieser prächtigen Arena beginnen!"
  },
  AvgDialog_142853_Content_87 = {
    Text = "Wenn der letzte Sieger sich durchgesetzt hat, wird eine Tür zum Palast des Sternenwals für ihn geöffnet!"
  },
  AvgDialog_142853_Content_88 = {
    Text = "Hinter jener Tür warten endloser Ruhm, Reichtum, Macht — alles!"
  },
  AvgDialog_142853_Content_89 = {
    Text = "Den Sieger ermitteln ... was sind die Regeln?"
  },
  AvgDialog_142853_Content_9 = {
    Text = "Während du vor dem alten Steinsockel vor dich hin redest, geht Lotan zur Mitte des riesigen Platzes."
  },
  AvgDialog_142853_Content_90 = {
    Text = "Regeln? Hehehe ... Hahahaha! Regeln?! ..."
  },
  AvgDialog_142853_Content_91 = {
    Text = "Das übertriebene Gelächter der Phantasmen lässt die Trommelfelle aller in der Arena schmerzen. In dem wahnsinnigen Gelächter verstummen sie und blicken erwartungsvoll auf die Mitte der leeren Arena."
  },
  AvgDialog_142853_Content_92 = {
    Text = "Aber ... er hat noch gar nicht gesagt, was die Regeln sind ..."
  },
  AvgDialog_142853_Content_93 = {
    Text = "Doch, das hat er. „Der letzte Sieger\" — nur Eins. Das ist die einzige Regel, kleiner Spatz."
  },
  AvgDialog_142853_Content_94 = {
    Text = "Töten, herausfordern, Bündnisse schließen, verraten ... achtzehn Teilnehmer, und Nur eine Person, die noch steht, darf durch jene Tür gehen."
  },
  AvgDialog_142853_Content_95 = {
    Text = "Elians Gesicht ziert wieder jenes vertraute Lächeln, das Du so gut kennst."
  },
  AvgDialog_142853_Content_96 = {
    Text = "Was Dich erwartet, wird eine Gruppe der mächtigsten Menschen dieser Welt sein."
  },
  AvgDialog_142853_Content_97 = {
    Text = "Bitte missversteht mich nicht, ich hege keinerlei Zweifel an Eurer Stärke, Lady Lotan."
  },
  AvgDialog_142853_Content_98 = {
    Text = "Aber ich denke, Ihr wollt Euch auch nicht beim Genuss jener erfreulichen Gemetzel von langweiligen Menschen stören lassen, oder?"
  },
  AvgDialog_142853_Content_99 = {
    Text = "Lotan hob zum ersten Mal ernsthaft den Kopf. Sie erblickte ein Gesicht mit einem sanften Lächeln und die Augen darauf, die scheinbar alles durchschauen konnten."
  },
  AvgDialog_142854_Content_1 = {
    Text = "Der fünfte Abschnitt"
  },
  AvgDialog_142854_Content_10 = {
    Text = "Lo... Lotan, Herrin?"
  },
  AvgDialog_142854_Content_11 = {
    Text = "Du konntest nicht erkennen, ob die Person vor Dir, die über und über mit Blut bedeckt war, Lotan war."
  },
  AvgDialog_142854_Content_12 = {
    Text = "Schmutziges, verfallendes Blut bedeckte ihren Körper – ob es ihr eigenes war oder von etwas anderem stammte, war nicht zu sagen."
  },
  AvgDialog_142854_Content_13 = {
    Text = "Unter dem schmutzigen Blut und der zerbrochenen Rüstung war eine Hälfte ihres Körpers nur noch blankes weißes Knochengerüst."
  },
  AvgDialog_142854_Content_14 = {
    Text = "Die Kriegerin, der nur noch eine halbe Körperhälfte verblieben war, trat aus dem von Blutgeruch durchdrungenen Riss hervor. Ihr Schritt war langsam und erschöpft, das gebrochene Riesenschwert schleifte über den Boden und zog eine seichte Furche durch die Blutlache."
  },
  AvgDialog_142854_Content_15 = {
    Text = "In ihrer anderen Hand tropfte die aus Blutfest geformte Krone schmutziges Blut."
  },
  AvgDialog_142854_Content_16 = {
    Text = "Ihre Augen leuchteten wie nie zuvor."
  },
  AvgDialog_142854_Content_17 = {
    Text = "Lo... Lotan, Herrin... der Himmelswal... Er..."
  },
  AvgDialog_142854_Content_18 = {
    Text = "Er hat verloren."
  },
  AvgDialog_142854_Content_19 = {
    Text = "Lotans Stimme zitterte kein bisschen, als ob sie nur von etwas spräche, das ohnehin geschehen musste."
  },
  AvgDialog_142854_Content_2 = {
    Text = "Husten... Husten, Husten..."
  },
  AvgDialog_142854_Content_20 = {
    Text = "Ihr habt Das Testament mit Ihm geschlossen... Wenn Er Schaden erleidet, dann auch Ihr..."
  },
  AvgDialog_142854_Content_21 = {
    Text = "Du musst nicht weiter fragen. Lotans Wunden sagen bereits alles."
  },
  AvgDialog_142854_Content_22 = {
    Text = "Lady Lotan, Ihr habt jeden Herausforderer besiegt... sogar den Astralen Cetus!"
  },
  AvgDialog_142854_Content_23 = {
    Text = "Jetzt seid Ihr die unbestrittene Königin dieses Planeten... Jetzt ist der strahlendste Moment Eures Lebens! Jetzt..."
  },
  AvgDialog_142854_Content_24 = {
    Text = "Jetzt ist auch ihr zerbrechlichster Moment."
  },
  AvgDialog_142854_Content_25 = {
    Text = "Der Blutgeruch aus dem Riss hüllt Dich ein, und das Flüstern wie ein Walgesang wird in Deinen Ohren immer klarer."
  },
  AvgDialog_142854_Content_26 = {
    Text = "Sieh nur, die Krone aus Blutfest..."
  },
  AvgDialog_142854_Content_27 = {
    Text = "Die Throne von sechs Königreichen, die Unterwerfung von Millionen, unversieglicher Reichtum und Ruhm... Diese Krone kann ihrem Träger alles geben."
  },
  AvgDialog_142854_Content_28 = {
    Text = "Jeder in der Arena begehrt sie. Die Ritter, die Dich täglich schlagen und Schimpfen, Gracchus, die Schwestern Vorn, General Alish, der allmächtige Herr Elian..."
  },
  AvgDialog_142854_Content_29 = {
    Text = "Und Du, kleiner Spatz. Auch Du begehrst sie..."
  },
  AvgDialog_142854_Content_3 = {Text = "Das ist..."},
  AvgDialog_142854_Content_30 = {
    Text = "Du blickst auf die blutrote Krone in Lotans Hand. Mit jedem Tropfen Blutfest, der fällt, wird das Flüstern des Himmelswalss klarer."
  },
  AvgDialog_142854_Content_31 = {
    Text = "Du wirst nie wieder eine Sklavin sein, kleiner Spatz."
  },
  AvgDialog_142854_Content_32 = {
    Text = "Du wirst deiner Mutter ein prächtiges Mausoleum errichten. Du wirst deine Geschwister aus den Ställen holen, damit sie mit dir in einem herrlichen Palast leben."
  },
  AvgDialog_142854_Content_33 = {
    Text = "Die Menschen, die Euch einst gedemütigt haben, werden vor Dir knien und Deinen Fußrücken küssen."
  },
  AvgDialog_142854_Content_34 = {
    Text = "Macht. Unermessliche Macht."
  },
  AvgDialog_142854_Content_35 = {
    Text = "Die Namen, die durch Legenden fließen, starben alle ihretwegen ... und jetzt liegt sie vor Dir, zum Greifen nah."
  },
  AvgDialog_142854_Content_36 = {
    Text = "Geh, kleiner Spatz. In Deinem ganzen Leben ist dies Deine einzige Chance!"
  },
  AvgDialog_142854_Content_37 = {
    Text = "Das Flüstern wurde zum Donnern, ein starker Impuls surgte durch Deinen Geist. Deine trockene Kehle schluckte, Deine zitternden Hände hoben den mit Juwelen besetzten Dolch, den Elian hinterlassen hatte. Auf der Klinge des Dolches klebte noch Dein eigenes Blut."
  },
  AvgDialog_142854_Content_38 = {
    Text = "Du hast es bis hierher geschafft — warum kannst Du nicht noch einen Schritt weitergehen? Das gehört Dir ... die Krone gehört Dir von Anfang an ..."
  },
  AvgDialog_142854_Content_39 = {
    Text = "Du hast es bis hierher geschafft — warum kannst Du nicht noch einen Schritt weitergehen? Das gehört Dir ... die Krone gehört Dir von Anfang an ..."
  },
  AvgDialog_142854_Content_4 = {
    Text = "Du erhobst Dich aus dem Staub, der überall auf dem Boden lag, schütteltest den Sand von Dir ab und brauchtest ein paar Sekunden, um Dich zu erinnern, wo Du Dich gerade befandest."
  },
  AvgDialog_142854_Content_40 = {
    Text = "<Red:Töte Sie? ... Töte Sie ... Töte Sie ... Töte Sie!!!>"
  },
  AvgDialog_142854_Content_41 = {
    Text = "Drei Schritte. Nur drei Schritte trennen Dich von jenem höchsten Ruhm ..."
  },
  AvgDialog_142854_Content_42 = {
    Text = "Als Du all Deinen Mut zusammennimmst und den ersten Schritt machen willst, dreht Lotan sich um. Diese müden Augen blicken Dich ruhig an."
  },
  AvgDialog_142854_Content_43 = {
    Text = "Als Du all Deinen Mut zusammennimmst und den ersten Schritt machen willst, dreht Lotan sich um. Diese müden Augen blicken Dich ruhig an."
  },
  AvgDialog_142854_Content_44 = {
    Text = "In dem Moment, als Dich dieser Blick trifft, verstummt all das Flüstern, das Dich getragen hatte, und Dein siedendes Blut erkaltet augenblicklich."
  },
  AvgDialog_142854_Content_45 = {
    Text = "Ich...Ich...?"
  },
  AvgDialog_142854_Content_46 = {
    Text = "In Lotans Augen liegt kein Funken Mordlust. Beim Anblick dieser Augen begreifst Du plötzlich: Wäre es nicht darum gegangen, den Wal des Sternenhimmels zu finden, wäre hier niemand es wert gewesen, dass Sie die Hand erhebt."
  },
  AvgDialog_142854_Content_47 = {
    Text = "In Lotans Augen liegt kein Funken Mordlust. Beim Anblick dieser Augen begreifst Du plötzlich: Wäre es nicht darum gegangen, den Wal des Sternenhimmels zu finden, wäre hier niemand es wert gewesen, dass Sie die Hand erhebt."
  },
  AvgDialog_142854_Content_48 = {
    Text = "Es ist der Blick eines Menschen, der von oben herab auf Ameisen schaut, die sich um ein Stück Zucker streiten. Mehr als das — keinerlei weitere Regung."
  },
  AvgDialog_142854_Content_49 = {
    Text = "Die Geschichte der Ameisen hat sich nie verändert. Sie hebt jene Hand, die längst zu weißen Knochen geworden ist, und legt das, was Sie darin hält, achtlos auf Deinen Kopf."
  },
  AvgDialog_142854_Content_5 = {
    Text = "Die Steinwände der Arena zerbrachen wie Papier, gewaltige Steinbrocken stürzten von den Tribünen herab, und die letzten Überreste der Phantasma-Zuschauer waren längst verschwunden."
  },
  AvgDialog_142854_Content_50 = {
    Text = "!!!Das ist..."
  },
  AvgDialog_142854_Content_51 = {
    Text = "Warmes, schmutziges Blut tropft von Deinem Scheitel herab. Du streckst die Hand aus und ertastest auf Deinem eigenen Kopf jene eiskalte, klebrige Krone aus Blutfest."
  },
  AvgDialog_142854_Content_52 = {
    Text = "Unzählige Helden töteten ihretwegen, unzählige Menschenseelen verfielen ihretwegen. Die Macht und der Reichtum sechs großer Reiche, höchste Würde und Ruhm — all das ruht nun leichthin auf Deinem Haupt."
  },
  AvgDialog_142854_Content_53 = {
    Text = "Der endgültige Sieger warf es Dir beiläufig zu, wie man einem Kind ein Stück Zucker in seinen gierigen Mund steckt — nun besitzt Du alles."
  },
  AvgDialog_142854_Content_54 = {
    Text = "Lotan, Herrin ... Sie ... Sie ..."
  },
  AvgDialog_142854_Content_55 = {
    Text = "Tu mir einen Gefallen."
  },
  AvgDialog_142854_Content_56 = {
    Text = "Ich gehe nun, einen neuen Gegner zu suchen. Davor brauche ich ein neues Schwertpaar."
  },
  AvgDialog_142854_Content_57 = {
    Text = "Lotan betrachtete die beiden Riesenschwerter in ihren Händen, die sie so viele Jahre begleitet hatten, und barg ihre zerbrochenen Überreste in den Scheiden."
  },
  AvgDialog_142854_Content_58 = {
    Text = "Sie wandte sich um und schleppte ihren zerschundenen Körper vorwärts – erschöpft, langsam – in Richtung eines Ziels, das Du niemals begreifen könntest."
  },
  AvgDialog_142854_Content_59 = {
    Text = "In den Rissen hinter Dir erloschen die uralten Runen eine nach der anderen, und die im Zerfall begriffene Gottheit zeigte ein Lächeln der Erleichterung, wie Du es noch nie gesehen hattest."
  },
  AvgDialog_142854_Content_6 = {
    Text = "Du lagst auf dem trümmerbedeckten Boden, die Ohren erfüllt von unaufhörlichem Dröhnen. Der Dimensionsriss schwebte in der Mitte der Arena, seine Ränder zuckten heftig, wie eine grässliche Wunde."
  },
  AvgDialog_142854_Content_60 = {
    Text = "Erinnere Dich für mich... an ihren Namen."
  },
  AvgDialog_142854_Content_61 = {
    Text = "Du knietest in einer Blutlache und starrtest auf die Gestalt, die sich immer weiter entfernte, unfähig, Dich lange Zeit zu erheben."
  },
  AvgDialog_142854_Content_62 = {
    Text = "Die Krone auf deinem Haupt ist schwer, so unendlich schwer. Das Gewicht von zwölftausend Jahren der Begierde zwingt dich im Blutbecken auf die Knie. Du beobachtest ihre sich entfernende Gestalt und kannst dich noch lange, lange Zeit nicht erheben."
  },
  AvgDialog_142854_Content_63 = {
    Text = "Die Krone auf dem Haupt war so leicht, so unendlich leicht – als hätte sie niemals existiert."
  },
  AvgDialog_142854_Content_7 = {
    Text = "Ein dumpfes, langgezogenes Klagen drang aus der Wunde hervor, durchdrang Deinen Schädel und reichte bis in die Tiefen Deines Geistes – so schwer wie das Seufzen eines ganzen Planeten."
  },
  AvgDialog_142854_Content_8 = {
    Text = "Diese Stimme ... ist das der Sternenwal?!"
  },
  AvgDialog_142854_Content_9 = {
    Text = "Aus dem Riss strömte ein intensiver, übelkeitserregender Blutgeruch. Als Du Dich anschicktest, langsam darauf zuzugehen, trat ein Fuß, an dem nur noch Knochen übrig waren, aus dem Riss hervor."
  },
  AvgDialog_142888_Content_1 = {Text = "Eine Lüge"},
  AvgDialog_142888_Content_10 = {
    Text = "Du kannst nicht antworten, deine Erinnerungen sind gerade so durcheinander wie ein langhaariger Hund, der sich dreimal im Schlamm gewälzt hat."
  },
  AvgDialog_142888_Content_100 = {
    Text = "Es überflutet die Brust, überflutet die Ohren, überflutet ..."
  },
  AvgDialog_142888_Content_101 = {Text = "Mein Herr!"},
  AvgDialog_142888_Content_102 = {
    Text = "Du kehrst plötzlich in die Realität zurück. In der Ferne kommen Ogier, Lotan und Ramona auf dich zu, nachdem sie ihr Training beendet haben. Dolls aufgeteilte Puppen analysieren ihre Trainingsdaten."
  },
  AvgDialog_142888_Content_103 = {
    Text = "Die Person neben dir seufzt tief bedauernd."
  },
  AvgDialog_142888_Content_104 = {
    Text = "Keine Sorge, ich werde dir diese Wahl immer offenhalten."
  },
  AvgDialog_142888_Content_105 = {
    Text = "Niemand bleibt an deiner Seite. Der Horizont, an dem die untergehende Sonne zu versinken droht, bricht ein leicht psychedelisches, sanftes Perlmuttleuchten."
  },
  AvgDialog_142888_Content_106 = {Text = "Ah..."},
  AvgDialog_142888_Content_107 = {
    Text = "Du hast noch so viel zu sagen. Über jene Katastrophe, die auf nichts Bestimmtes abzielte, sondern nur durch Ns spielerische Verführung der Gläubigen ausgelöst wurde."
  },
  AvgDialog_142888_Content_108 = {
    Text = "Über die Rolle der Latern-Kirche beim Anfachen der Flammen, über Pontos' verschiedene wahnsinnige Vergeltungsakte im darauffolgenden Jahrhundert oder so."
  },
  AvgDialog_142888_Content_109 = {
    Text = "Darüber ... ob es einen Moment gab, in dem er selbst wegen einer anderen Möglichkeit geschwankt hat – und ob deshalb die Zeit ihre Spuren an ihm hinterlassen hat."
  },
  AvgDialog_142888_Content_11 = {
    Text = "Leisha, die durch den vorherigen Kampf ebenfalls fast erschöpft ist, stemmt sich mühsam hoch und stellt sich zwischen dich und Pontos."
  },
  AvgDialog_142888_Content_110 = {
    Text = "Darüber, ob Jago und Leisha noch immer in Ebwynnos feiern."
  },
  AvgDialog_142888_Content_111 = {
    Text = "... Am Ende möchtest du nur beten, dass er in der Schule keinen Ärger mit Professor Dexter bekommt."
  },
  AvgDialog_142888_Content_112 = {
    Text = "Du schüttelst den Kopf und gehst ohne zu zögern auf deine Freunde zu."
  },
  AvgDialog_142888_Content_12 = {
    Text = "Pontos, es ist vorbei."
  },
  AvgDialog_142888_Content_13 = {
    Text = "Die noch Lebenden, die in Ebwynnos bleiben, müssen dafür die Erinnerungen an die Welt außerhalb von Ebwynnos vergessen."
  },
  AvgDialog_142888_Content_14 = {
    Text = "Und jemand wie ich, der bereits gestorben und zu einem Albtraum umgeformt wurde, dem werden am Ende alle Erinnerungen langsam durch Korrosion genommen."
  },
  AvgDialog_142888_Content_15 = {
    Text = [[
Jago hat seine Wahl getroffen, und ich habe meine getroffen ...
Lass uns gehen.]]
  },
  AvgDialog_142888_Content_16 = {
    Text = "Pontos presst die Lippen zu einer gleichgültigen Linie zusammen, seine Kiefermuskeln spannen sich an."
  },
  AvgDialog_142888_Content_17 = {
    Text = "Du solltest dich noch erinnern: Du existierst in Abhängigkeit von Ebwynnos. Wenn du Ebwynnos verlässt, wirst du sterben."
  },
  AvgDialog_142888_Content_18 = {
    Text = "Ja, aber meine vergangenen Erinnerungen werden zurückkehren. Ich werde als Mensch sterben – das ist der einzige Weg."
  },
  AvgDialog_142888_Content_19 = {
    Text = "Ich kann mich schon... nicht mehr erinnern, wie du und Jago als Kinder ausgesehen habt. Wenigstens, bevor ich euch beide ganz vergesse."
  },
  AvgDialog_142888_Content_2 = {
    Text = "Der erstickende Druck zieht sich wie eine Flut zurück, dein Kopf durchzuckt ein heftiger Schmerz und vor deinen Augen flimmert es weiß."
  },
  AvgDialog_142888_Content_20 = {
    Text = "Pontos erstarrt auf der Stelle. Zum ersten Mal siehst du auf seinem Gesicht einen so tiefen Ausdruck der Trauer."
  },
  AvgDialog_142888_Content_21 = {
    Text = "... Ich wünschte wirklich, ich könnte sagen, dass jene Kraft mich noch immer kontrolliert."
  },
  AvgDialog_142888_Content_22 = {
    Text = "Er schließt die Augen, als wolle er sich vor dem verstecken, dem er nicht ins Gesicht sehen möchte. Schließlich zeigt er ein selbstironisches, niedergeschlagenes Lächeln."
  },
  AvgDialog_142888_Content_23 = {
    Text = "Dann könnte ich mit gutem Gewissen euren Willen missachten und euch Böses antun."
  },
  AvgDialog_142888_Content_24 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_142888_Content_25 = {
    Text = "Pontos fügt sich schweigend. Der Streitwagen, der ihn einst zur Rache an seinen Feinden trug, trägt nun auch Leisha auf ihrem Weg."
  },
  AvgDialog_142888_Content_26 = {
    Text = "In dem Moment, als der Streitwagen, der ein unbeschreibliches perlmuttartiges Leuchten ausstrahlte, über den Himmel von Ebwynnos hinausglitt, erschien ein Ausdruck der Erleichterung auf Leishas Gesicht. Sie wandte sich euch beiden zu..."
  },
  AvgDialog_142888_Content_27 = {
    Text = "Dann verschwand sie vollständig in der nächtlichen Meeresbrise."
  },
  AvgDialog_142888_Content_28 = {
    Text = "Ihr sagt beide nichts, sondern starrt lange in die Nichtigkeit, bis Pontos die Stille bricht."
  },
  AvgDialog_142888_Content_29 = {
    Text = "Wie war dein Leben nach dem Verlassen von Ebwynnos, das Leben von „Du\"?"
  },
  AvgDialog_142888_Content_3 = {
    Text = "Zisch — das tut so weh!"
  },
  AvgDialog_142888_Content_30 = {
    Text = "Du hättest nicht erwartet, dass sein erster Satz dieser sein würde. Du stockst einen Moment, bevor du anfängst, die wirren Erinnerungen zu ordnen."
  },
  AvgDialog_142888_Content_31 = {
    Text = "Mit diesem Geheimgang scheint etwas nicht zu stimmen. Weder Jagos Erinnerungen noch deine sind vollständig intakt."
  },
  AvgDialog_142888_Content_32 = {
    Text = "...Ich kann mich nicht klar erinnern. In meinem Kopf sind jetzt sowohl Erinnerungen daran, Jago zu sein, als auch Erinnerungen daran, jemand anderes zu sein, an einem weit entfernten Ort. Alle Erinnerungen sind durcheinander."
  },
  AvgDialog_142888_Content_33 = {
    Text = "Instinktiv greifst du in deine Tasche und streichelst die Grashüpfer-Figur."
  },
  AvgDialog_142888_Content_34 = {
    Text = "Aber dennoch — schlicht, gewöhnlich, geschäftig, immer dieselben Routinen Tag für Tag — es war ein glückliches Leben."
  },
  AvgDialog_142888_Content_35 = {
    Text = "Glücklich genug, um mich zu dem zu machen, der ich bin. Glücklich genug, dass ich, egal was passiert, zurückwill."
  },
  AvgDialog_142888_Content_36 = {
    Text = "Er blickt dir in die Augen, ruhig und still. Es fühlt sich fast so an wie... wie Leisha dich einst angesehen hat."
  },
  AvgDialog_142888_Content_37 = {
    Text = "<Red:Er sieht nicht nur Jago an.>"
  },
  AvgDialog_142888_Content_38 = {
    Text = "Ihr habt euch geirrt, Jago... <Red:%player%>."
  },
  AvgDialog_142888_Content_39 = {Text = "!!!???"},
  AvgDialog_142888_Content_4 = {
    Text = "Pontos steht allein an seinem Platz, du kannst sein Emoji nicht erkennen."
  },
  AvgDialog_142888_Content_40 = {Text = "Was?!"},
  AvgDialog_142888_Content_41 = {
    Text = "Ein Schauer durchfährt dich. Wie kann er <Red:„deinen\"> Namen kennen? Ist dies nicht nur ein Geheimgang?"
  },
  AvgDialog_142888_Content_42 = {
    Text = "Er gleitet zurück in jene kühle, aristokratische Gelassenheit, als hätte er nie etwas aus der Hand gegeben, und lächelt dich ruhig an."
  },
  AvgDialog_142888_Content_43 = {
    Text = "Ich weiß, dass <Red:„Du\"> die ganze Zeit hier warst, ich weiß, dass <Red:„Du\"> „Er„ bist – seit <Red:„Du\"> klein warst, wusste ich, dass <Red:„Du\"> besonders bist."
  },
  AvgDialog_142888_Content_44 = {
    Text = "Das dumpfe, dem Meer gehörende Rauschen überflutet erneut deine Ohren."
  },
  AvgDialog_142888_Content_45 = {
    Text = "Ihr seid noch zu klein, zu unwissend, und habt irrtümlich geglaubt, dass diese Mittelmäßigkeit Glück sei."
  },
  AvgDialog_142888_Content_46 = {
    Text = "Diesmal werde ich nicht den <Red:Fehler> machen, die Wahl erneut in deine Hände zu legen."
  },
  AvgDialog_142888_Content_47 = {
    Text = "Du lagst falsch. Er hat nie nachgegeben. Er wird nicht loslassen und hatte es nie vor. Er hat nur einen leuchtenden Köder ausgelegt."
  },
  AvgDialog_142888_Content_48 = {
    Text = "Er hatte den anderen Teil von „dir\" längst entdeckt.\nEr würde „dich\" finden. Er würde keine weiteren Überraschungen zulassen."
  },
  AvgDialog_142888_Content_49 = {
    Text = [[
Zu einfach. Diese Schlacht, dieser Sieg. 
Es war eine Falle gewesen, um <Italic:dich> herauszulocken.]]
  },
  AvgDialog_142888_Content_5 = {
    Text = "Aber offensichtlich hat ihn etwas verlassen."
  },
  AvgDialog_142888_Content_50 = {
    Text = "Egal welchen Preis ich zahlen muss, egal welchem Wesen ich Treue schwören muss..."
  },
  AvgDialog_142888_Content_51 = {
    Text = "Ich werde dafür sorgen, dass das Fest von Ebwynnos für immer andauert."
  },
  AvgDialog_142888_Content_52 = {
    Text = "Niemand wusste, warum er plötzlich zuließ, dass das Altern von ihm Besitz ergriff."
  },
  AvgDialog_142888_Content_53 = {
    Text = "Ganz Ebwynnos bebt mit ihm. Die Medien um ihn herum und das aus seiner Brust strömende Meerwasser verschmelzen miteinander, nicht mehr voneinander zu unterscheiden."
  },
  AvgDialog_142888_Content_54 = {
    Text = "Vielleicht Freunde, vielleicht Feinde. Unzählige schwarze Arme strecken sich aus seiner Brust hervor, kratzen an seiner Haut, streicheln sie."
  },
  AvgDialog_142888_Content_55 = {
    Text = "Als wollten sie fliehen. Als sehnten sie sich danach, für immer bei ihm zu sein."
  },
  AvgDialog_142888_Content_56 = {
    Text = "Ich befinde mich auf einem Weg ohne Rückkehr. Und ich brauche keinen."
  },
  AvgDialog_142888_Content_57 = {
    Text = "Die Jahre, die du nie erlebt hast, bedeuten nichts. Hier in Ebwynnos sind sie zahm. Kontrollierbar. Sie können dir nicht schaden."
  },
  AvgDialog_142888_Content_58 = {
    Text = "Es ist wirklich schade. Ich kann dich noch nicht hier behalten. Unsere Zeit ist um, <Red:%player%>."
  },
  AvgDialog_142888_Content_59 = {Text = "!!!"},
  AvgDialog_142888_Content_6 = {
    Text = "Gib mir einen Grund."
  },
  AvgDialog_142888_Content_60 = {
    Text = "Eine Schwerelosigkeit überrascht dich, reißt dich hoch und hinaus aus dem aufgerissenen Raum. Den Himmel verdeckende Knechtgaunts spreizen ihre Häutungsflügel und stürmen in einem sanften Schwall auf dich zu."
  },
  AvgDialog_142888_Content_61 = {
    Text = "Keine Sorge. Wir werden uns bald genug wiedersehen."
  },
  AvgDialog_142888_Content_62 = {
    Text = "Ebwynnos und ich werden auf deine Rückkehr warten. Für immer."
  },
  AvgDialog_142888_Content_63 = {
    Text = "Die Spuren der Zeit zogen wie Verwitterung über Pontos' Körper."
  },
  AvgDialog_142888_Content_64 = {
    Text = "Lachend hebt er von Ebwynnos aus das Glas in deiner Richtung, während es rasch in der Ferne versinkt."
  },
  AvgDialog_142888_Content_65 = {
    Text = "In deinem letzten Blick, bevor die Dunkelheit ihn verschluckt, siehst du zwei Gestalten an seiner Seite stehen."
  },
  AvgDialog_142888_Content_66 = {
    Text = "Er ließ niemanden gehen. Er behielt sie alle – jeden Einzelnen."
  },
  AvgDialog_142888_Content_67 = {
    Text = "<Red:Das ist Leisha und der junge Jago.>"
  },
  AvgDialog_142888_Content_68 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_142888_Content_69 = {
    Text = "Was?! Und dann? Was dann? Hüter, hat er dich einfach in den Tod fallen lassen?!"
  },
  AvgDialog_142888_Content_7 = {
    Text = "Seine Stimme ist heiser, doch sein Körper bleibt angespannt — wie ein in die Enge getriebenes Tier."
  },
  AvgDialog_142888_Content_70 = {
    Text = "Onkel Pontos war so gemein! Das kann er dir nicht antun!!"
  },
  AvgDialog_142888_Content_71 = {
    Text = "Ja, wie kannst du nur so gemein sein, Pontos!"
  },
  AvgDialog_142888_Content_72 = {
    Text = "Du erzählst Aurita gerade aufgeregt und lebhaft von deinen Erlebnissen im Traum, als du dich umdrehst..."
  },
  AvgDialog_142888_Content_73 = {
    Text = "...und von jemandem erschreckt wirst, der genauso neugierig mit den Händen in den Taschen an der Tür lehnt und schon wer weiß wie lange zugehört hat."
  },
  AvgDialog_142888_Content_74 = {
    Text = "Danach kam der kleine Jago sicher heraus. Er öffnete seine Augen und erwachte aus dem Traum."
  },
  AvgDialog_142888_Content_75 = {
    Text = "Er fand sich in seinem eigenen Bett zu Hause liegend wieder, umgeben von den Menschen, die er liebte."
  },
  AvgDialog_142888_Content_76 = {
    Text = "Die andere Hauptfigur der Geschichte lehnt an der Wand von Auritas Schlafzimmer und liefert mit leiser, gemächlicher Stimme das Ende."
  },
  AvgDialog_142888_Content_77 = {
    Text = "Er erinnerte sich an alle Erinnerungen seines Lebens, schloss friedlich die Augen und ging an einen Ort des Glücks."
  },
  AvgDialog_142888_Content_78 = {
    Text = "Aurita gab zufrieden ein leises Schnaufen von sich und schlief allmählich ein – genau wie Vera in deiner Erinnerung."
  },
  AvgDialog_142888_Content_79 = {
    Text = "Pontos neigt seinen Kopf zur Tür und macht eine einladende Geste."
  },
  AvgDialog_142888_Content_8 = {
    Text = "Warum, warum musst auch du gehen, warum wählst du lieber den Tod, anstatt —"
  },
  AvgDialog_142888_Content_80 = {
    Text = "Ich nehme an, du möchtest ein Wort mit mir reden?"
  },
  AvgDialog_142888_Content_81 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_142888_Content_82 = {
    Text = "Nach langer Trennung wiedervereint — was für ein schöner Ausdruck."
  },
  AvgDialog_142888_Content_83 = {
    Text = "Du hast Aurita nicht gesagt, wie es wirklich endete. Du hast gelogen, nicht wahr?"
  },
  AvgDialog_142888_Content_84 = {
    Text = "Du hast Leisha nie gehen lassen. Und die Einzige, die Ebwynnos verlassen durfte, war ich – nicht Jago."
  },
  AvgDialog_142888_Content_85 = {
    Text = "So abrupt unterbrochen, ist Pontos überhaupt nicht verärgert. Er grinst und hebt eine Augenbraue."
  },
  AvgDialog_142888_Content_86 = {
    Text = "Natürlich, offensichtlich. Manche Geschichten sind nicht für Kinder geeignet, nicht wahr?"
  },
  AvgDialog_142888_Content_87 = {
    Text = "Dann nehme ich an, diese... <Italic:Erscheinung>, die du jetzt trägst... ist nur dazu da, allen zu zeigen, dass das Altern – das Einzige, das dir fehlte – dir nichts bedeutet."
  },
  AvgDialog_142888_Content_88 = {
    Text = "Um zu zeigen, dass du alles unter Kontrolle hast, hm? Die Zeit. Das Altern. Sogar das Leben anderer Menschen..."
  },
  AvgDialog_142888_Content_89 = {
    Text = "Die Feindseligkeit in deinen Worten wird wohl zu offensichtlich, um sie zu übersehen. Pontos antwortet nicht direkt; er schenkt dir nur ein Lächeln, das dich maßlos erzürnt."
  },
  AvgDialog_142888_Content_9 = {
    Text = "Und nicht „Ich\"."
  },
  AvgDialog_142888_Content_90 = {
    Text = "Wer weiß? Vielleicht wollte ich einfach etwas Neues ausprobieren."
  },
  AvgDialog_142888_Content_91 = {
    Text = "Wie auch immer, ich bin froh, dass du dich erinnert hast. Seit dem allerersten Mal, als ich nach Misaq kam, habe ich mich auf diesen Tag gefreut."
  },
  AvgDialog_142888_Content_92 = {
    Text = "Ebwynnos wartet noch auf dich, %player%."
  },
  AvgDialog_142888_Content_93 = {
    Text = "... Falls du eine Erinnerung brauchst: Misaq verfügt über ein vollständiges Sicherheitssystem."
  },
  AvgDialog_142888_Content_94 = {
    Text = "Sei nicht so angespannt."
  },
  AvgDialog_142888_Content_95 = {
    Text = "In diesem Zusammenhang bin ich ziemlich neugierig. Mein kleines Wesen aus Misaq, du bist nicht mehr Jago. Hast du jetzt eine Antwort für mich?"
  },
  AvgDialog_142888_Content_96 = {
    Text = "Pontos neigt den Kopf leicht zur Seite, und du blickst in seine tiefblauen Augen."
  },
  AvgDialog_142888_Content_97 = {
    Text = "Wenn ich dir noch eine Chance gäbe zu wählen, würdest du das ewige Leben mit immerwährender Jugend wählen oder die Erinnerungen, die im Laufe eines Lebens entstehen?"
  },
  AvgDialog_142888_Content_98 = {
    Text = "Das Rauschen des Meeres, das Flattern von Flügeln."
  },
  AvgDialog_142888_Content_99 = {
    Text = "Das vertraute und doch ferne weißes Rauschen durchdringt langsam wieder deinen Körper."
  },
  AvgDialog_142889_Content_1 = {
    Text = "Das Beste überhaupt"
  },
  AvgDialog_142889_Content_10 = {
    Text = "Wenn du älter bist, wirst du es verstehen. Wir werden uns irgendwann wiedersehen. Und wenn wir getrennt sind, werde ich die ganze Zeit an dich denken."
  },
  AvgDialog_142889_Content_100 = {
    Text = "Er seufzt. Mit einem vollkommen sachlichen Lächeln beendet er dann den Rest des Satzes zusammen mit einer anderen Stimme."
  },
  AvgDialog_142889_Content_101 = {
    Text = "Wovon redest du? Das hier ist Ebwynnos. Es gibt kein Altern hier. Wir werden ewig feiern, für immer jung."
  },
  AvgDialog_142889_Content_102 = {
    Text = "<Italic:Jemand> tritt hinter Orney hervor. Er spricht leise und heiser, wie der großmütigste und würdevollste der Ältesten."
  },
  AvgDialog_142889_Content_103 = {
    Text = "Das ist nicht die Stimme von Pontos."
  },
  AvgDialog_142889_Content_104 = {
    Text = "Er ist so uralt, dass jedes vertraute Gefühl von einst vollständig verblasst ist — nur noch das Echo des Ozeans aus <Red:größter Tiefe> spült Dein Bewusstsein erneut fort."
  },
  AvgDialog_142889_Content_105 = {
    Text = "Ja, ja, das hier ist Ebwynnos. Ich bin nach Ebwynnos zurückgekehrt."
  },
  AvgDialog_142889_Content_106 = {
    Text = "<Shake:<Red:Wir werden ewig feiern.>>"
  },
  AvgDialog_142889_Content_107 = {
    Text = "<Red:Wir werden ewig jung sein.>"
  },
  AvgDialog_142889_Content_108 = {
    Text = "Du bist so glücklich, so sorglos. Du bist in Ebwynnos."
  },
  AvgDialog_142889_Content_109 = {
    Text = "Abgesehen davon verflüchtigten sich alle unwichtigen Gedanken."
  },
  AvgDialog_142889_Content_11 = {
    Text = "<Red:Klack——>"
  },
  AvgDialog_142889_Content_110 = {
    Text = "Allerdings hast du aus irgendeinem Grund niemandem die Heuschrecke gezeigt, deren Namen du vergessen hattest."
  },
  AvgDialog_142889_Content_12 = {
    Text = "In dem Moment, als der Kompass deine Hand verließ, drang von draußen ein dichtes, leises Geräusch durch das Fenster."
  },
  AvgDialog_142889_Content_13 = {
    Text = "Unmittelbar darauf folgte ein leises Lachen."
  },
  AvgDialog_142889_Content_14 = {
    Text = "Lass mich mal sehen, wer dieser hübsche kleine Kerl ist—"
  },
  AvgDialog_142889_Content_15 = {
    Text = "Mit einer unsichtbaren, gewaltigen Kraft sprang das Fenster weit auf. In der tiefen, kakophonischen Dunkelheit flackerte der silberne Mond durch die Lücken."
  },
  AvgDialog_142889_Content_16 = {
    Text = "Hallo, Jago."
  },
  AvgDialog_142889_Content_17 = {
    Text = "So viele... so viele Flügel, Großvater!!"
  },
  AvgDialog_142889_Content_18 = {
    Text = "Unzählige riesige schwarze Membranflügel, die den Himmel verdunkelten, strömten auf dich zu. Deine Pupillen zitterten, als du in das dunkle Zentrum starrtest, unfähig dich zu bewegen."
  },
  AvgDialog_142889_Content_19 = {
    Text = "<Red:Onkel Pontos......>"
  },
  AvgDialog_142889_Content_2 = {
    Text = "Die Erinnerung endet. Du schweigst eine lange Weile."
  },
  AvgDialog_142889_Content_20 = {
    Text = "Quietsch... glitsch... <LightGray:*feuchtes Quetschgeräusch>"
  },
  AvgDialog_142889_Content_21 = {
    Text = "Veras kleine Hand klammerte sich fest an dich, hinterließ am Ende nur eine tiefe Kratzspur.\nUmhüllung, Erstickung, Verschlingung."
  },
  AvgDialog_142889_Content_22 = {
    Text = "Friedlich. Ruhig. Vertraut. Angenehm..."
  },
  AvgDialog_142889_Content_23 = {
    Text = "Wogen aus weißem Rauschen haben deine Ohren verschluckt."
  },
  AvgDialog_142889_Content_24 = {
    Text = "<Red:Fallen.>"
  },
  AvgDialog_142889_Content_25 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_142889_Content_26 = {
    Text = "Jago, wach auf. Hör auf zu schlafen."
  },
  AvgDialog_142889_Content_27 = {
    Text = "Die heutigen Festlichkeiten beginnen gleich. Alle warten auf dich."
  },
  AvgDialog_142889_Content_28 = {
    Text = "Ein durchdringendes weißes Rauschen jagt einen stechenden Schmerz durch deine Trommelfelle, und du springst instinktiv aus dem Bett hoch."
  },
  AvgDialog_142889_Content_29 = {
    Text = "Ich hab doch gesagt, dass er bald zu sich kommt. Mein Jago ist ein bemerkenswerter kleiner Kerl."
  },
  AvgDialog_142889_Content_3 = {
    Text = "Nenn es die Selbstsucht eines alten Mannes, denkst du – denn du bist vielleicht der letzte Mensch, der sich an sie erinnert, und du willst nicht, dass sie vergessen werden."
  },
  AvgDialog_142889_Content_30 = {
    Text = "Pontos grinst und stupst Leisha mit dem Ellbogen an. Orney, Onkel White und viele vertraute Gesichter drängen sich alle um dein Bett."
  },
  AvgDialog_142889_Content_31 = {
    Text = "Dein Bewusstsein fühlt sich an, als wäre es in tiefem Wasser versunken. Du hast das nagende Gefühl, etwas vergessen zu haben, und die Beweglichkeit deines Körpers kommt dir auf subtile Weise falsch vor."
  },
  AvgDialog_142889_Content_32 = {
    Text = "Onkel Pontos, Mama? Was ist passiert? Warum sind alle hier?"
  },
  AvgDialog_142889_Content_33 = {
    Text = "Oh, du warst auf einer langen Reise, Kleines. Ich habe sehr, sehr lange nach dir gesucht."
  },
  AvgDialog_142889_Content_34 = {
    Text = "Jetzt habe ich dich nach Hause gebracht."
  },
  AvgDialog_142889_Content_35 = {
    Text = "Die untergehende Sonne durchbricht die Wolken und zerteilt das Meer in schimmernde Wellen wie verstreutes Gold, das sich im Fensterglas spiegelt. Du bist zurück im Gasthof am Meer, in dem du aufgewachsen bist."
  },
  AvgDialog_142889_Content_36 = {
    Text = "Ah, richtig. Dieser Ort ist... @4"
  },
  AvgDialog_142889_Content_37 = {Text = "??!!!"},
  AvgDialog_142889_Content_38 = {
    Text = "ABYSSABYSSABYSSABYSSABYSSABYSSABYSSABYSS\nA@1YS@1@2Y@2@1B@1SSSS@2YA@4@2Y@1\n@1B@1S@2Y@2@2y@1sa@1y@2@4@2Y@1\na@1y@2A@4ss@2ysssssAb@3abyss@2@3\n厄@2@3波@1@3厄@2yssSS@2YA@4\n@1B@1S@2Y@2@2y@1sa@1y@2@4@2Y@1\nA@1YS@1@2Y@2@1B@1SSSS@2YA@4@2Y@1\n@1@2@3扬@1@3斯@2y!!ab@2YA@4\nABYssABySSabySSAByssabYSSa@2SAByssabyssABYSS@2\nABYSSABYSSABYSS@4@3SSABYSS@2@3\n@3@2@4@3@1@3@3!!!!!!!\na@1y@2A@4ss@2ysssssAb@3abyss@2@3\n@3@4YssAby!!!!!!!ABYSSABYSSABy@1\nA@1YS@1@2Y@2@1B@1SSSS@2YA@4@2Y@1@1\n@1B@1S@2Y@2@2y@1sa@1y@2@4<Red:!!!!!!>"
  },
  AvgDialog_142889_Content_39 = {
    Text = "Ein pochender Schmerz, ein drückender Druck—der Name der Stadt bleibt dir auf der Zungenspitze hängen."
  },
  AvgDialog_142889_Content_4 = {
    Text = "Du schaust Vera zärtlich an. Deine Familie hat euch rücksichtsvoll allein gelassen, damit du dich nicht überanstrengst."
  },
  AvgDialog_142889_Content_40 = {
    Text = "Ein kreischendes Dröhnen wie Eisen, das über Glas kratzt, kracht aus dem Inneren deines Schädels hinab in deinen Hals und verwandelt dein Gehirn in eine dicke, zähflüssige Masse."
  },
  AvgDialog_142889_Content_41 = {
    Text = "Bis diese warme, raue Handfläche deinen Hinterkopf umfasst, und wie immer lacht er und drückt seine Stirn gegen deine."
  },
  AvgDialog_142889_Content_42 = {
    Text = "Hey, komm zurück zu mir. Was ist los?"
  },
  AvgDialog_142889_Content_43 = {
    Text = "Du öffnest langsam den Mund und tastst nach deiner Stimme."
  },
  AvgDialog_142889_Content_44 = {
    Text = "Pontos beobachtet dich aufmerksam, und du verstehst es nicht — die Art, wie er dich ansieht, ist die Art, wie jemand etwas ansieht, das er für immer verloren geglaubt hatte."
  },
  AvgDialog_142889_Content_45 = {
    Text = "Wie jemanden ansehen, der das Kostbarste auf der Welt ist."
  },
  AvgDialog_142889_Content_46 = {
    Text = "Willkommen zurück in Ebwynnos, Jago."
  },
  AvgDialog_142889_Content_47 = {
    Text = "Das Bewusstsein kehrt zurück. Du starrst auf all die vertrauten Dinge um dich herum, das Sonnenlicht, das die Dielen so sehr aufheizt, dass sie Salzkörner ausschwitzen..."
  },
  AvgDialog_142889_Content_48 = {
    Text = "Eine seltsame, heitere Freude übertönt alle anderen Gedanken. Ein Lächeln steigt langsam in dein Gesicht."
  },
  AvgDialog_142889_Content_49 = {
    Text = "Jetzt erinnere ich mich. Ebwynnos. Das ist Ebwynnos—der Ort, an dem ich aufgewachsen bin..."
  },
  AvgDialog_142889_Content_5 = {
    Text = "Ich habe Mama und Onkel Pontos nie wiedergesehen. Ohne diesen Kompass würde ich wahrscheinlich denken, es wäre alles eine Halluzination von der Explosion gewesen."
  },
  AvgDialog_142889_Content_50 = {
    Text = "Ganz genau. Lange nicht gesehen!"
  },
  AvgDialog_142889_Content_51 = {
    Text = "Du bist endlich nach Hause gekommen, Jago."
  },
  AvgDialog_142889_Content_52 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_142889_Content_53 = {
    Text = "Deine Gedanken fühlen sich an, als wären sie in einen Sirup namens Glück getaucht worden. Alle um dich herum sehen genauso jung aus wie damals, als ihr euch getrennt habt..."
  },
  AvgDialog_142889_Content_54 = {
    Text = "Oh... getrennt habt."
  },
  AvgDialog_142889_Content_55 = {
    Text = "Wann hast du Ebwynnos verlassen, und wie bist du zurückgekommen? Es scheint noch nicht lange her zu sein, da lagst du in einem anderen Bett. Du hast eine Enkelin, namens..."
  },
  AvgDialog_142889_Content_56 = {
    Text = "Woran denkst du gerade, Kleines?"
  },
  AvgDialog_142889_Content_57 = {
    Text = "Pontos lehnte sich ans Fenster, die untergehende Sonne versank bereits im Meer, ihre letzten Lichtstrahlen verbargen sich hinter ihm."
  },
  AvgDialog_142889_Content_58 = {
    Text = "Onkel Pontos, ich habe das Gefühl, etwas sehr Wichtiges vergessen zu haben. Was war es nur..."
  },
  AvgDialog_142889_Content_59 = {
    Text = "Hahaha, wenn du dich gerade nicht daran erinnern kannst, ist es wohl nicht so wichtig. Keine Eile — in Ebwynnos haben wir alle Zeit der Welt."
  },
  AvgDialog_142889_Content_6 = {
    Text = "Also, Vera, deshalb wollte Großvater dir diese Geschichte erzählen."
  },
  AvgDialog_142889_Content_60 = {
    Text = "Komm schon! Du bist noch jung, du hast genug schöne Zeit vor dir — die solltest du natürlich mit Feiern verbringen."
  },
  AvgDialog_142889_Content_61 = {
    Text = "Er legte seinen Arm um deine Schultern und ging in Richtung der frisch geschmückten Halle im Erdgeschoss, wo die jubelnde Menge euch gemeinsam auf die Tanzfläche zog."
  },
  AvgDialog_142889_Content_62 = {
    Text = "Erst jetzt bemerkst du, dass das Gasthaus zu einem Saal von blendendem Glanz geworden ist."
  },
  AvgDialog_142889_Content_63 = {
    Text = "Vertraute Gesichter lachen über die Tanzfläche, heben ihre Becher und winken dir zu, Holz- und Glasbecher stoßen in einem verstreuten Lärm zusammen."
  },
  AvgDialog_142889_Content_64 = {
    Text = "Ich bin noch jung, ich bin noch... jung?"
  },
  AvgDialog_142889_Content_65 = {
    Text = "Ein schwerer Schwindel überkommt dich erneut. Diese seltsame Freude hält dich fest umklammert und lässt nicht los."
  },
  AvgDialog_142889_Content_66 = {
    Text = "Du hebst deinen Arm und siehst zwei junge, kräftige Hände;"
  },
  AvgDialog_142889_Content_67 = {
    Text = "du blickst in das Glas, und das Gesicht eines jungen Mannes trägt dasselbe Lachen wie alle anderen."
  },
  AvgDialog_142889_Content_68 = {
    Text = "Freunde, lasst uns die Gläser erheben — auf Ebwynnos!"
  },
  AvgDialog_142889_Content_69 = {
    Text = "Bevor du dich sammeln kannst, greift Pontos über deine Schulter und hebt sein Glas zur Menge."
  },
  AvgDialog_142889_Content_7 = {
    Text = "Vielleicht schweben sie noch irgendwo am Nachthimmel. Und wenn ich eines Tages verschwinde, sind sie vielleicht nur gekommen, um mich nach Hause zu holen."
  },
  AvgDialog_142889_Content_70 = {
    Text = "Auf Ebwynnos!"
  },
  AvgDialog_142889_Content_71 = {
    Text = "In verwirrender, überwältigender Freude hebst du gemeinsam mit den anderen das Glas, und die Woge der Stimmen trägt dich tiefer ins Herz der Menge."
  },
  AvgDialog_142889_Content_72 = {
    Text = "Du feierst, du tanzt, du trinkst ohne Zurückhaltung."
  },
  AvgDialog_142889_Content_73 = {
    Text = "Die Lichtstrahlen des hohen Hauses durchdringen den Nebel, der vom Meer aufsteigt, und glitzern die ganze Nacht."
  },
  AvgDialog_142889_Content_74 = {
    Text = "Erst als ein schwaches, blasses Licht am Horizont erschien und die Menschen aneinandergelehnt in den Schlaf sanken, summtest du, selbst leicht beschwipst, ein Lied und lehntest dich in die samtbezogenen Kissen zurück."
  },
  AvgDialog_142889_Content_75 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_142889_Content_76 = {
    Text = "Du bist fast am Einnicken, als du plötzlich Leishas Gesicht in einer Ecke des Saals siehst. Du eilst zu ihr."
  },
  AvgDialog_142889_Content_77 = {
    Text = "Mama! Warte auf mich — wo bist du hingegangen? Ich habe dich den ganzen Abend nicht gesehen."
  },
  AvgDialog_142889_Content_78 = {
    Text = "Eine unerklärliche Panik ergreift dein Herz, und du kannst nicht umhin, vor dich hin zu murmeln."
  },
  AvgDialog_142889_Content_79 = {
    Text = "Wie seltsam — war ich nicht gerade erst auf einer Reise? Warum fühlt es sich an, als hätten wir uns so lange nicht gesehen?"
  },
  AvgDialog_142889_Content_8 = {
    Text = "Aber... ich will nicht von Großvater getrennt werden. Kannst du mich mitnehmen?"
  },
  AvgDialog_142889_Content_80 = {
    Text = "Deine Schritte hielten abrupt inne — wegen des Ausdrucks völliger Hilflosigkeit und Trauer auf Leishas Gesicht."
  },
  AvgDialog_142889_Content_81 = {
    Text = "Er hat dich gefunden. Mein armer Jago, du hättest niemals hierherkommen sollen."
  },
  AvgDialog_142889_Content_82 = {
    Text = "Denk nach, schnell — solange du noch nicht vergessen hast. Erinnere dich daran, was für ein Leben du geführt hast."
  },
  AvgDialog_142889_Content_83 = {
    Text = "Mutters Tränen fielen auf deine Hand, so kalt, dass du instinktiv zurückzucktest. Die eisige Luft ließ Schauer in einem Augenblick durch deinen ganzen Körper fahren."
  },
  AvgDialog_142889_Content_84 = {
    Text = "Schau dir die Menschen um dich herum an. Schau mich an. Schau, was wir sein sollten."
  },
  AvgDialog_142889_Content_85 = {
    Text = "Greif in deine Tasche, Jago."
  },
  AvgDialog_142889_Content_86 = {
    Text = "Unbeholfen, grob, ein wenig stachelig — dort liegt eine <Red:Grashüpfer>."
  },
  AvgDialog_142889_Content_87 = {
    Text = "Ein Grashüpfer, gemacht von <Red:Vera>, benannt nach <Red:Vera>."
  },
  AvgDialog_142889_Content_88 = {
    Text = "<Shake:<Red:Vera>... nein, ich habe bereits... es ist schon so lange her...>"
  },
  AvgDialog_142889_Content_89 = {
    Text = "<Shake:Ich sterbe, ich liege im Bett, ich hatte Freunde, ich hatte die Liebe meines Lebens, ich hatte Kinder, ich war...>"
  },
  AvgDialog_142889_Content_9 = {
    Text = "Du kannst dir ein Lachen nicht verkneifen und holst den Kompass hervor, der seit Jahrzehnten nie von deiner Seite gewichen ist, und legst ihn in Veras Handfläche."
  },
  AvgDialog_142889_Content_90 = {
    Text = "Alles um dich herum dreht sich in chaotischer Unordnung, zwei völlig verschiedene Gedankengänge miteinander verwoben."
  },
  AvgDialog_142889_Content_91 = {
    Text = "Du hältst dir den Kopf, krümmst dich vor Schmerz und ringst nach Luft."
  },
  AvgDialog_142889_Content_92 = {
    Text = "Du meine Güte, Jago, was ist los mit dir? Du siehst schrecklich aus!"
  },
  AvgDialog_142889_Content_93 = {
    Text = "Orney prallt aus dem Nichts gegen dich, und das Dröhnen in deinen Ohren verschwindet mit einem Mal."
  },
  AvgDialog_142889_Content_94 = {
    Text = "Du blickst auf, und Leisha ist bereits verschwunden."
  },
  AvgDialog_142889_Content_95 = {
    Text = "Orney, Orney, nein, nein, ich erinnere mich jetzt!"
  },
  AvgDialog_142889_Content_96 = {
    Text = "Wir sind zusammen aufgewachsen, nicht wahr? Ich war bei deinem Abschluss, deiner Hochzeit. Du solltest nicht so jung sein! Wir sind gleich alt, wir sind beide alt geworden..."
  },
  AvgDialog_142889_Content_97 = {
    Text = "Orney starrt dich mit einem Ausdruck an, den du überhaupt nicht kennst, und er starrt so lange, so lange, bis du fast fliehen möchtest."
  },
  AvgDialog_142889_Content_98 = {Text = "Dann..."},
  AvgDialog_142889_Content_99 = {
    Text = "Ach, Jago..."
  },
  AvgDialog_142890_Content_1 = {Text = "Sie und Er"},
  AvgDialog_142890_Content_10 = {
    Text = "Danke für dein Geschenk, Onkel Pontos, aber..."
  },
  AvgDialog_142890_Content_11 = {
    Text = "Das muss ein sehr langes und kostbares Leben gewesen sein — dafür bin ich bereit, ewige Jugend und LP aufzugeben."
  },
  AvgDialog_142890_Content_12 = {
    Text = "Die Menschen hören auf zu reden. Wie auf ein Zeichen drehen sich alle um und schauen dich an."
  },
  AvgDialog_142890_Content_13 = {
    Text = "Dein Trommelfell schmerzt und droht zu bersten, das Rauschen des Meerwassers bohrt sich in deinen Schädel."
  },
  AvgDialog_142890_Content_14 = {
    Text = "Durch das dumpfe Meeresrauschen hindurch hörst du einen Seufzer."
  },
  AvgDialog_142890_Content_15 = {
    Text = "<Red:Schon wieder.>"
  },
  AvgDialog_142890_Content_16 = {
    Text = "<Shake:<Red:Quietsch... Muh, Gurrr, Gur...>>"
  },
  AvgDialog_142890_Content_17 = {
    Text = "Die vier Wände zittern, alles tropft in feuchtem Schleim herab."
  },
  AvgDialog_142890_Content_18 = {
    Text = "Selbst nachdem ich dich herausgelöst habe, lässt das Altern dich solch <Red:schwaches Geschwätz> von dir geben — genau wie Leisha."
  },
  AvgDialog_142890_Content_19 = {
    Text = "Du spürst plötzlich, dass er <Red:nicht mehr> Pontos ist."
  },
  AvgDialog_142890_Content_2 = {
    Text = "Als du diese vertraute, warme Hand siehst, machst du schließlich — einen Schritt zurück."
  },
  AvgDialog_142890_Content_20 = {
    Text = "So uralt, dass er längst vergessen wurde — eine unermessliche, ehrfurchtgebietende, kaum zu ertragene, eiskalte Angst lässt Dich erstarren und einen lautlosen <Red:Schrei> ausstoßen."
  },
  AvgDialog_142890_Content_21 = {
    Text = "ABYSSABYSSABYSSABYSSABYSSABYSSABYSSABYSS\nA@1YS@1@2Y@2@1B@1SSSS@2YA@4@2Y@1\n@1B@1S@2Y@2@2y@1sa@1y@2@4@2Y@1\na@1y@2A@4ss@2ysssssAb@3abyss@2@3\n厄@2@3波@1@3厄@2yssSS@2YA@4\n@1B@1S@2Y@2@2y@1sa@1y@2@4@2Y@1\nA@1YS@1@2Y@2@1B@1SSSS@2YA@4@2Y@1\n@1@2@3扬@1@3斯@2y!!ab@2YA@4\nABYssABySSabySSAByssabYSSa@2SAByssabyssABYSS@2\nABYSSABYSSABYSS@4@3SSABYSS@2@3\n@3@2@4@3@1@3@3!!!!!!!\na@1y@2A@4ss@2ysssssAb@3abyss@2@3\n@3@4YssAby!!!!!!!ABYSSABYSSABy@1\nA@1YS@1@2Y@2@1B@1SSSS@2YA@4@2Y@1@1\n@1B@1S@2Y@2@2y@1sa@1y@2@4<Red:!!!!!!>"
  },
  AvgDialog_142890_Content_22 = {
    Text = "Du erinnertest dich — dieses Geräusch von deiner Ankunft in Ebwynnos, als du Ebwynnos verließest, als du nach Ebwynnos zurückkehrtest."
  },
  AvgDialog_142890_Content_23 = {
    Text = "Haut, Rippen, sich nach außen schälend, sich entfaltend, und dann..."
  },
  AvgDialog_142890_Content_24 = {
    Text = "Nichts, unzählige Hände, nichts, nichts, nichts, nichts, nichts, @2y@2, @4@4@2@4\n@3@2@4@3@1@3@3!!!!!!"
  },
  AvgDialog_142890_Content_25 = {
    Text = "Bleib hier, bleib in Ebwynnos."
  },
  AvgDialog_142890_Content_26 = {
    Text = "<Change>Dem Abgrund gehorchen, sich in den Abgrund stürzen."
  },
  AvgDialog_142890_Content_27 = {Text = "Mond."},
  AvgDialog_142890_Content_28 = {
    Text = "Der strahlend helle Mond hängt weit oben am fernen Himmel."
  },
  AvgDialog_142890_Content_29 = {
    Text = "Seine Rippen seine Haut seine Arme seine Brust sein Schoß\nsein Schoß sein Schoß sein Schoß sein Schoß sein Schoß\nsein Schoß sein Schoß sein Schoß sein Schoß sein Schoß\nEb@3@4wyn@3@2nos\nEbwy@4@3@2nn@4@3@2\nseine Umarmung seine Rippen seine Haut seine Arme seine Brust\nfür immer für immer für immer für immer für immer für immer immer\nimmer für immer für immer für immer für immer für immer für immer <Red:Ebwynnos>"
  },
  AvgDialog_142890_Content_3 = {
    Text = "… es gibt."
  },
  AvgDialog_142890_Content_30 = {
    Text = "<Red:Ebwynnos, der in seinen Schoß gekommen ist.>"
  },
  AvgDialog_142890_Content_31 = {
    Text = "Schicht um Schicht von Flügeln, die eine dichte, unausweichliche Umarmung und Verschlingung in sich tragen."
  },
  AvgDialog_142890_Content_32 = {
    Text = "Du wirst gedrängt, du wirst eingehüllt, du wirst aufgenommen, du fällst in endlose Stille."
  },
  AvgDialog_142890_Content_33 = {Text = "Hör auf!"},
  AvgDialog_142890_Content_34 = {
    Text = "Eine Gestalt bahnt sich gewaltsam einen Weg durch die ahnungslose, eiskalte Menge und stürmt auf den Strudel von <Red:„Pontos\"> zu."
  },
  AvgDialog_142890_Content_35 = {
    Text = "Es verursacht keinen Schaden, doch ein äußerst deutlicher Schock lässt <Red:„Pontos'\"> Pupillen zucken, und er heftet seinen Blick starr auf ihr Gesicht."
  },
  AvgDialog_142890_Content_36 = {
    Text = "Ich dachte immer... ich hätte nur eine Leere Hülle neu geformt."
  },
  AvgDialog_142890_Content_37 = {
    Text = "So wie Jago vergessen hat, was ihn noch immer beeinflusst, existiert auch ein Teil von mir noch."
  },
  AvgDialog_142890_Content_38 = {
    Text = "Lass ihn gehen, Pontos, er gehört nicht hierher."
  },
  AvgDialog_142890_Content_39 = {
    Text = "Oh, Leisha."
  },
  AvgDialog_142890_Content_4 = {Text = "Was?"},
  AvgDialog_142890_Content_40 = {
    Text = "Ich liebe ihn, so wie du ihn liebst."
  },
  AvgDialog_142890_Content_41 = {
    Text = "Orney, White."
  },
  AvgDialog_142890_Content_42 = {
    Text = "Alle Menschen von Ebwynnos."
  },
  AvgDialog_142890_Content_43 = {
    Text = "Schweigend nähern sie sich gemeinsam mit dem Albtraum, wie eine einstürzende Mauer, die dich einzuschließen droht."
  },
  AvgDialog_142890_Content_44 = {
    Text = "Nein, nein nein nein! Nein!!"
  },
  AvgDialog_142890_Content_45 = {
    Text = "Leisha blickt auf dich, auf Jago und auch auf... dich."
  },
  AvgDialog_142890_Content_46 = {
    Text = "Ich weiß, warum du sie so sehr haben willst — dort ist nicht nur Jago, dort ist mehr als eine einzige Seele."
  },
  AvgDialog_142890_Content_47 = {
    Text = "Ah... sie werden alles vergessen, sie werden hier bleiben."
  },
  AvgDialog_142890_Content_48 = {
    Text = "Leisha ist erneut gefangen. Sie dreht ihren Körper mit aller Kraft und starrt dich an – nicht in dein Gesicht, sondern hindurch, als ob sie versuchen würde, in den tiefsten Teil deiner Seele zu blicken."
  },
  AvgDialog_142890_Content_49 = {
    Text = "Bitte. Wer auch immer du bist — ich weiß, dass du da drin bist. Bring Jago zurück. \nBring ihn zurück in das Leben, das ihr leben solltet!"
  },
  AvgDialog_142890_Content_5 = {
    Text = "Er wirkt, als hätte er deine Frage nicht verstanden, und runzelt ungläubig leicht die Stirn."
  },
  AvgDialog_142890_Content_50 = {
    Text = "Dichte schwarze Flügelmembranen entfalten sich — alles ist so still, so... verlockend, dass du beinahe auf sie zugehst."
  },
  AvgDialog_142890_Content_51 = {
    Text = "Dann hörst du ... die Stimme von <Red:„Du\">."
  },
  AvgDialog_142890_Content_52 = {
    Text = "Ich glaube, <Red:„Ich\"> habe bereits eine Wahl getroffen."
  },
  AvgDialog_142890_Content_53 = {
    Text = "Aus den Tiefen des Geistesmeeres kämpft sich ein Funken Bewusstsein hervor."
  },
  AvgDialog_142890_Content_54 = {
    Text = "Du hast die große Explosion von Akute überlebt und als <Red:„Misaq-Schutzherr\"> diesen Körper übernommen."
  },
  AvgDialog_142890_Content_55 = {
    Text = "Silberner Glanz flackerte in deiner Handfläche."
  },
  AvgDialog_142890_Content_56 = {
    Text = "Jagos verstreute Erinnerungen werden Stück für Stück zusammengetragen."
  },
  AvgDialog_142890_Content_57 = {
    Text = "Weißt du, Onkel Pontos... das Erste, woran ich mich gerade erinnert habe, war etwas so Kleines. Etwas, das eigentlich keine Rolle hätte spielen sollen."
  },
  AvgDialog_142890_Content_58 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_142890_Content_59 = {
    Text = "„Pontos\" spricht nicht. Er betrachtet dich schweigend."
  },
  AvgDialog_142890_Content_6 = {
    Text = "Sie haben eine Bedeutung, diese Erinnerungen."
  },
  AvgDialog_142890_Content_60 = {
    Text = "Als „Ich\" achtzehn wurde, schlichen Orney und ich uns auf den nächsten Dampfer und baten die Matrosen, auf dem Unterdeck arbeiten zu dürfen – als Gegenleistung für die Überfahrt. Eine kostenlose Fahrt, einfach so."
  },
  AvgDialog_142890_Content_61 = {
    Text = "Am nächsten Morgen sahen wir den schönsten Sonnenaufgang, den wir je erlebt hatten. Orney sagte, er wünschte, die Sonne würde niemals untergehen. Aber ich nicht."
  },
  AvgDialog_142890_Content_62 = {
    Text = "Denn die Sonne geht unter. Denn jeder Tag endet. Das ist es, was den Dingen, die wir erleben, Bedeutung verleiht."
  },
  AvgDialog_142890_Content_63 = {
    Text = "Genug dieser Torheit. In Ebwynnos kann ich die Sonne nach deinem Belieben auf- und untergehen lassen, wenn das dein Wunsch ist."
  },
  AvgDialog_142890_Content_64 = {
    Text = "Er schließt die Augen, erschöpft, seine Geduld endlich am Ende. Du schüttelst entschieden den Kopf."
  },
  AvgDialog_142890_Content_65 = {
    Text = "Was zählt, ist die Zeit, die wir durchleben. Nicht eine Sonne, die ewig dort hängt."
  },
  AvgDialog_142890_Content_66 = {
    Text = "Verzeih, Pontos."
  },
  AvgDialog_142890_Content_67 = {
    Text = "Er hebt die Hand. Die Wand der Knechtgaunts schließt sich um dich."
  },
  AvgDialog_142890_Content_68 = {
    Text = "Geht, meine Diener."
  },
  AvgDialog_142890_Content_7 = {
    Text = "Nicht für andere, sondern für mich selbst."
  },
  AvgDialog_142890_Content_8 = {
    Text = "Ich möchte wissen, was für ein Leben ich geführt habe — warum mich nach dem Verlust meiner Erinnerungen jede Freude ein Gefühl der Leere hinterlässt."
  },
  AvgDialog_142890_Content_9 = {
    Text = "Der Stachel des Grashüpfers sticht leicht in deine Fingerspitze, und du musst unwillkürlich an das Kind denken, das weinend am Bett saß."
  },
  AvgDialog_142891_Content_1 = {
    Text = "Familiengeheimnis"
  },
  AvgDialog_142891_Content_10 = {
    Text = "Sie heißt — hm, sie heißt Vera, denn Vera ist der Name, den Opa ihr gegeben hat, und es ist der schönste Name."
  },
  AvgDialog_142891_Content_100 = {
    Text = "Sein Zorn wird euch verbrennen, nur die Freude kann ... @1!"
  },
  AvgDialog_142891_Content_101 = {Text = "Pfft."},
  AvgDialog_142891_Content_102 = {
    Text = "Blut spritzte, und du starrtest fassungslos auf Leisha und einige der Stammgäste der Herberge, die auf denselben Wesen kämpften, auf denen ihr geritten wart."
  },
  AvgDialog_142891_Content_103 = {
    Text = [[
Warum zum Teufel kommen diese verfluchten Dinge ausgerechnet hierher ...
Na ja, das sollte das letzte gewesen sein.]]
  },
  AvgDialog_142891_Content_104 = {
    Text = "Hoffentlich ziehen sie nur vorbei..."
  },
  AvgDialog_142891_Content_105 = {
    Text = "Leisha und ihre Gefährten gingen. Du und Pontos standet im Schatten. Du wärst sofort zu Boden gesunken, hätte er nicht deine Schultern gehalten."
  },
  AvgDialog_142891_Content_106 = {
    Text = "Du klammtertest dich an seinen Saum. Seine Stimme war ruhig und sanft, als würde er sich alle Mühe geben, dich nicht noch mehr zu erschrecken."
  },
  AvgDialog_142891_Content_107 = {
    Text = "Jago, es ist genau wie das, was du gesehen hast... diese Wesen, die uns gerade hierher getragen haben, nennen sich Knechtgaunts. Wir bringen sie dazu, für uns zu kämpfen."
  },
  AvgDialog_142891_Content_108 = {
    Text = "Er hielt inne, seine Hand ruhte an der Flanke des Knechtgaunts, er ließ seine Knöchel knacken, als würde er zögern, wie er es erklären sollte."
  },
  AvgDialog_142891_Content_109 = {
    Text = "Nun ja, wir sind die Helden aus einer Abenteuergeschichte – die Art, die Drachen zähmt, nur dass wir diese Knechtgaunts zähmen."
  },
  AvgDialog_142891_Content_11 = {
    Text = "Vera ... Großvater braucht Ruhe, komm zu Papa."
  },
  AvgDialog_142891_Content_110 = {
    Text = "W-was... Wovon redest du, Onkel Pontos?! Unsere Familie betreibt doch nur eine Herberge..."
  },
  AvgDialog_142891_Content_111 = {
    Text = "Danach... nach dem Unfall waren nicht mehr viele von uns übrig. Leisha hat viel für alle getan, und die Menschen lehnten sich an sie."
  },
  AvgDialog_142891_Content_112 = {
    Text = "Aber sie wollte nicht, dass wir – besonders du – irgendetwas damit zu tun haben. Dieses stille, namenlose Leben ist genau das, was sie sich für uns gewünscht hat."
  },
  AvgDialog_142891_Content_113 = {
    Text = "Aber da draußen gibt es noch so viele böse, hässliche Dinge in dieser Welt, genau wie die, die du heute gesehen hast. Ich verstehe das nicht..."
  },
  AvgDialog_142891_Content_114 = {
    Text = "Ein Anflug von Frustration huschte über Pontos' Gesicht – ungewöhnlich für ihn – und er strich sich das lockere goldene Haar von der Stirn zurück über den Kopf."
  },
  AvgDialog_142891_Content_115 = {
    Text = "In letzter Zeit haben mich die Knechtgaunts gefunden. Und ich spüre etwas weit Mächtigeres hinter ihnen. Er hat mich auserwählt, Er ruft mich."
  },
  AvgDialog_142891_Content_116 = {
    Text = "Ich könnte so viel mehr tun. Aber Leisha glaubt, solange wir uns gut verstecken, wird alles gut sein."
  },
  AvgDialog_142891_Content_117 = {
    Text = "Das schiere Gewicht von alledem ließ dich verständnislos blinzeln. Zum ersten Mal kanntest du jedes einzelne Wort und konntest dennoch keinen Sinn daraus machen, wenn sie zusammengereiht wurden."
  },
  AvgDialog_142891_Content_118 = {
    Text = "Pontos schien sich zu fassen, kehrte in den Moment zurück und schenkte dir ein Lächeln."
  },
  AvgDialog_142891_Content_119 = {
    Text = "Entschuldigung, Jago. Habe ich dich auf einmal mit zu viel überhäuft?"
  },
  AvgDialog_142891_Content_12 = {
    Text = "Dein Sohn macht sich ein wenig Sorgen um deine Gesundheit und will die Enkelin wegbringen — sie zieht einen Schmollmund und ist kurz davor, laut loszuweinen."
  },
  AvgDialog_142891_Content_120 = {
    Text = "Lass uns zurückgehen, bevor Leisha herausfindet, dass wir uns davongeschlichen haben. Wir haben alle Zeit der Welt, darüber zu reden."
  },
  AvgDialog_142891_Content_121 = {
    Text = "In der Ferne schien Leisha in deine Richtung zu blicken. Onkel Pontos machte dir gegenüber erneut das <Italic:Psst>-Zeichen."
  },
  AvgDialog_142891_Content_122 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_142891_Content_123 = {
    Text = "Das Fenster öffnete und schloss sich wieder, ohne ein Geräusch."
  },
  AvgDialog_142891_Content_124 = {
    Text = "Als hätte der Wind lediglich das Fenster aufgeweht. Draußen brachen sich die Wellen und zogen sich zurück. Du hörtest das Geräusch von Leisha, die von unten die Treppe heraufkam."
  },
  AvgDialog_142891_Content_125 = {
    Text = "Ihr vergrabt euch mit ruhigem Atem in die Kissen und tut so, als wäre dies immer noch eine gewöhnliche Nacht."
  },
  AvgDialog_142891_Content_13 = {
    Text = "Du lachst und hustest ein paarmal, stemmst dich mühsam mit diesem zerbrechlichen Körper auf und lehnst dich ans Kopfteil des Bettes."
  },
  AvgDialog_142891_Content_14 = {
    Text = "Vera, wein nicht. Das Mondlicht draußen ist so schön — dimm das Licht ein wenig."
  },
  AvgDialog_142891_Content_15 = {
    Text = "Großvater hat noch Zeit, dir eine Geschichte zu erzählen. Lass mich überlegen..."
  },
  AvgDialog_142891_Content_16 = {
    Text = "Dein Blick fällt auf den Messingkompass, der dich nie verlassen hat. Unberührt von den Jahren trägt er im Mondlicht einen weichen, flaumigen Silberrand."
  },
  AvgDialog_142891_Content_17 = {
    Text = "Du fährst langsam mit dem Daumen über seine Oberfläche, voller Sehnsucht, und deine Stimme wird heiser, als du in Erinnerungen versinkst."
  },
  AvgDialog_142891_Content_18 = {
    Text = "Das war... vor über sechzig Jahren, als ich noch ein Kind war."
  },
  AvgDialog_142891_Content_19 = {
    Text = "Leisha, das Schiff legt gleich ab. Er ist immer noch nicht zurück?"
  },
  AvgDialog_142891_Content_2 = {Text = "Mond."},
  AvgDialog_142891_Content_20 = {
    Text = "Es scheint, als könnten wir uns wirklich nicht persönlich verabschieden. Bitte nimm wenigstens diese Brosche..."
  },
  AvgDialog_142891_Content_21 = {
    Text = "Die Hafensirene ertönte. Die Besitzer der zurückgelassenen Andenken hinterließen einen klimpernden Haufen persönlichen Schmucks, ihre Gesichter voller Bedauern, als sie zum Schiff zurückkehrten."
  },
  AvgDialog_142891_Content_22 = {
    Text = "Mein Gott, um @3s willen, Liebes, wann wird dein Onkel endlich wenigstens ein bisschen lernen, nicht so viele „Freunde\" zu haben?"
  },
  AvgDialog_142891_Content_23 = {
    Text = "Deine Mutter Leisha sah dich mit einem Ausdruck an, der zugleich amüsiert und hilflos war, seufzte und stopfte den Schmuck in die kleine Schachtel, die beim nächsten Anlegen des Schiffes dem Kapitän zur Zustellung zurückgegeben werden würde."
  },
  AvgDialog_142891_Content_24 = {
    Text = "Deine Familie betrieb ein ganz gewöhnliches kleines Gasthaus in einer Küstenstadt. Nur eine Sache war ein wenig besonders..."
  },
  AvgDialog_142891_Content_25 = {
    Text = "Lass mich mal sehen, wer dieser hübsche kleine Kerl ist—"
  },
  AvgDialog_142891_Content_26 = {
    Text = "Die Tür öffnet sich erneut mit einem salzigen Wind, und „diese besondere Sache\" lacht laut auf, packt dich um die Hüfte und schleudert dich einmal durch die Luft."
  },
  AvgDialog_142891_Content_27 = {
    Text = "Pontos! Wie oft habe ich dir schon gesagt, du reißt ihm noch die Arme aus!"
  },
  AvgDialog_142891_Content_28 = {
    Text = "Onkel Pontos!"
  },
  AvgDialog_142891_Content_29 = {
    Text = "Hey, kleiner Jago, schau mal, was ich dir mitgebracht habe!"
  },
  AvgDialog_142891_Content_3 = {
    Text = "Der hellste Vollmond, den du je gesehen hast, hängt am Himmel. Deine Gliedmaßen sind schwach und kraftlos, deine Gedanken etwas träge."
  },
  AvgDialog_142891_Content_30 = {
    Text = "Er schnippte mit den Fingern, öffnete seine Hand in der Luft, und ein schwerer, kupferbeschlagener Kompass fiel in deine Handfläche."
  },
  AvgDialog_142891_Content_31 = {
    Text = "Das sollte besser auf ehrliche Weise erworben worden sein. Dieses Haus kann keine weiteren „Liebesbeweise\" und „gebrochenen Herzen\" mehr aufnehmen."
  },
  AvgDialog_142891_Content_32 = {
    Text = "Leisha warf ihm die Schmuckschatulle mit einem Grinsen zurück und nickte mit dem Kinn zum Fenster, wo das Schiff, das die andere Hälfte dieser „gebrochenen Herzen\" trug, gerade den Hafen verlassen hatte."
  },
  AvgDialog_142891_Content_33 = {
    Text = "Ach, komm schon... du kennst mich. Ich war noch nie gut darin, Nein zu sagen."
  },
  AvgDialog_142891_Content_34 = {
    Text = "Grinsend neigte Pontos den Kopf, wich einem kräftigen Klaps von Leisha aus und setzte dich dann auf dem Boden ab."
  },
  AvgDialog_142891_Content_35 = {
    Text = "Übrigens habe ich ein paar neue Freunde gefunden. Wir müssen vielleicht reden, Leisha."
  },
  AvgDialog_142891_Content_36 = {
    Text = "Über die Dinge, über die du nicht reden möchtest."
  },
  AvgDialog_142891_Content_37 = {
    Text = "Zu sehr mit deinem neuen Schatz beschäftigt, bemerktest du den sich verdüsternden Ausdruck auf Leishas Gesicht nicht. Pontos zerzauste dein Haar."
  },
  AvgDialog_142891_Content_38 = {
    Text = "Deine Mutter und ich haben ein paar Dinge zu besprechen. Wenn mein Lieblingsnachwuchs bereit ist, eine Weile oben zu spielen, erzähle ich ihm wunderbare Geschichten von meinen Reisen. Abgemacht?"
  },
  AvgDialog_142891_Content_39 = {
    Text = "Er streckte seine Hand aus, und um des Kompasses willen nahmst du sie – der „Abmachungs-Handschlag\", der nur euch beiden gehörte."
  },
  AvgDialog_142891_Content_4 = {
    Text = "Du hebst die Hand – die Falten, die für Alter stehen, haben sich bereits über deine Haut ausgebreitet."
  },
  AvgDialog_142891_Content_40 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_142891_Content_41 = {
    Text = "Auf dem Boden des oberen Schlafzimmers liegend, holtest du eine Karte hervor und machtest dich in tiefer Konzentration daran, mit dem Kompass die Peilungen aus jenen Seefahrergeschichten zu bestimmen."
  },
  AvgDialog_142891_Content_42 = {
    Text = "Allerdings war dieses Haus zu alt, und der Ozean und der Wind hatten unablässig daran genagt. Ein paar vereinzelte Worte drangen noch durch die Ritzen der Dielen nach oben."
  },
  AvgDialog_142891_Content_43 = {
    Text = "...schon... sag... kannst nicht einfach... Verstecken ist keine Lösung."
  },
  AvgDialog_142891_Content_44 = {
    Text = "...Diese <Italic:Wesen>... ich kann... Mein Talent..."
  },
  AvgDialog_142891_Content_45 = {
    Text = "Onkel Pontos' Tonfall wurde immer drängender. Gerade als du neugierig dein Ohr näher heranpressen wolltest—"
  },
  AvgDialog_142891_Content_46 = {
    Text = "KRACH! RUMMS!"
  },
  AvgDialog_142891_Content_47 = {
    Text = "Die Tür flog mit einem Knall auf, Pontos wurde am Kragen gepackt und hineingezogen, Leisha zog eine strenge Miene auf, die eindeutig „keine Diskussion\" bedeutete."
  },
  AvgDialog_142891_Content_48 = {
    Text = "Ich bin nicht einverstanden, Pontos. Mein einziger Wunsch ist, dass ihr alle sicher und am Leben bleibt... Halte dich von diesen neuen Freunden fern."
  },
  AvgDialog_142891_Content_49 = {
    Text = "Wenn die Dinge wirklich außer Kontrolle geraten, bringe ich euch alle von hier weg."
  },
  AvgDialog_142891_Content_5 = {
    Text = "Ah, so bin ich schon in diesem Alter angekommen ... Heute Nacht könnte es die letzte sein."
  },
  AvgDialog_142891_Content_50 = {
    Text = "Hey, Leisha, ich bin kein Kind mehr! Wir können nicht ewig weiter davonlaufen."
  },
  AvgDialog_142891_Content_51 = {
    Text = "Lerne erst mal, mir beim Geschäft zu helfen. Hör auf, den ganzen Tag draußen herumzustreunen, bevor du davon redest."
  },
  AvgDialog_142891_Content_52 = {
    Text = "Du hattest Leisha selten so hart sprechen hören. Sie holte tief Luft und zwang sich zu einem angespannten Lächeln für dich."
  },
  AvgDialog_142891_Content_53 = {
    Text = "Jago, tu Mama einen Gefallen. Pass auf deinen Onkel auf — zumindest heute Nacht lass ihn nicht wieder draußen herumstreunen."
  },
  AvgDialog_142891_Content_54 = {
    Text = "Sie ließ diese Worte hinter sich und eilte nach unten zu den Kontobüchern, die nie enden zu wollen schienen, als wäre sie darauf erpicht, das Gespräch so schnell wie möglich zu beenden."
  },
  AvgDialog_142891_Content_55 = {
    Text = "Pontos hob eine Augenbraue und zuckte dir gegenüber mit den Schultern."
  },
  AvgDialog_142891_Content_56 = {
    Text = "Na dann, Jago, sieht so aus, als könnten wir die Geschichtenzeit ein kleines bisschen vorziehen."
  },
  AvgDialog_142891_Content_57 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_142891_Content_58 = {
    Text = "Vielleicht waren jene Geschichten, die zusammen mit der Fracht aus Schiffskabinen purzelten, zu aufregend und fantastisch. Selbst um Mitternacht schliefst du nicht tief und fest."
  },
  AvgDialog_142891_Content_59 = {
    Text = "Das Mondlicht vor dem Fenster legte einen silbernen Schimmer über deine Augenlider. Etwas versperrte es."
  },
  AvgDialog_142891_Content_6 = {
    Text = "Erinnerungen kehren allmählich zurück, doch seltsamerweise ist keine Angst vor dem Tod in deinem Herzen. Stattdessen lächelst du aus einem tiefen inneren Frieden heraus."
  },
  AvgDialog_142891_Content_60 = {
    Text = "Ein Klicken – der Fensterverschluss. Du öffnetest die Augen. Das Fenster war bereits weit aufgezogen worden."
  },
  AvgDialog_142891_Content_61 = {Text = "!"},
  AvgDialog_142891_Content_62 = {
    Text = "Onkel Pontos, du kannst nicht aus dem Fenster klettern! Mama wird böse!"
  },
  AvgDialog_142891_Content_63 = {
    Text = "Der halbe Körper von Pontos ragte bereits über den Fenstersims hinaus, und du stürztest dich ohne nachzudenken darauf zu, um ihn festzuhalten — und vergaßest dabei sogar zu fragen, warum er aussah, als würde er ... in der Luft schweben."
  },
  AvgDialog_142891_Content_64 = {
    Text = "Warte, pass auf!"
  },
  AvgDialog_142891_Content_65 = {
    Text = "Ein Gefühl der Schwerelosigkeit erfasste dich, und dann —"
  },
  AvgDialog_142891_Content_66 = {Text = "WUUSCH!"},
  AvgDialog_142891_Content_67 = {Text = "Ratsch—!"},
  AvgDialog_142891_Content_69 = {
    Text = "...! ...!!!!"
  },
  AvgDialog_142891_Content_7 = {
    Text = "Die Familie drängt sich um dich, die jüngste Enkelin Vera weiß noch von nichts und lehnt sich liebevoll an deine Hand."
  },
  AvgDialog_142891_Content_70 = {
    Text = "Du wurdest am Stoff an deiner Taille hochgerissen, das seltsame Gefühl von glattem Fell, das über dein Gesicht strich."
  },
  AvgDialog_142891_Content_71 = {
    Text = "Als du die Augen öffnetest, lief dir ein eisiger Schauer des Entsetzens den Rücken hinauf."
  },
  AvgDialog_142891_Content_72 = {Text = "Pon—"},
  AvgDialog_142891_Content_73 = {
    Text = "Der Schwanz einer gesichtslosen, unsagbaren Kreatur war hinter deinem Rücken eingehakt, seine Spitze dicht mit grässlichen Widerhaken bedeckt."
  },
  AvgDialog_142891_Content_74 = {
    Text = "Du hattest keine Zeit zu begreifen, dass dieses furchterregende Ding dich offensichtlich gerade gerettet hatte – unkontrollierbar zwang sich ein erstickter Schrei aus deiner Kehle."
  },
  AvgDialog_142891_Content_75 = {Text = "Pst!"},
  AvgDialog_142891_Content_76 = {
    Text = "Pontos, der auf diesem gesichtslosen Wesen lag, riss dich mit einem Griff zu sich hinauf, presste dir fest die Hand auf den Mund, und das Wesen entfaltete seine riesigen fledermausartigen Flügel und glitt lautlos in die Nacht."
  },
  AvgDialog_142891_Content_77 = {
    Text = "Hab keine Angst. Sie werden dir nichts tun."
  },
  AvgDialog_142891_Content_78 = {
    Text = "Es ist keine Zeit, Jago. Bleib still — ich erkläre dir später alles."
  },
  AvgDialog_142891_Content_79 = {
    Text = "Pontos legte einen Arm um deine Schultern, um dich zu beruhigen, und schob dich zwischen sich und die Kreatur, seinen Körper tief gehalten, seine Augen auf die felsigen Untiefen in einem abgelegenen Winkel des Hafens gerichtet."
  },
  AvgDialog_142891_Content_8 = {
    Text = "Opa, wann kannst du wieder mit mir spielen? Schau, was du mir letztes Mal beigebracht hast — das kann ich jetzt schon."
  },
  AvgDialog_142891_Content_80 = {
    Text = "Bevor du irgendetwas fragen konntest, kroch ein unheilvolles Geräusch aus dem Meer herauf, wie Würmer."
  },
  AvgDialog_142891_Content_81 = {
    Text = "<Shake:<Red:Raschel, raschel, raschel ...>>"
  },
  AvgDialog_142891_Content_82 = {
    Text = "<Shake:<Red:Platsch, platsch ... Klatsch —>>"
  },
  AvgDialog_142891_Content_83 = {
    Text = "!... Urgh..."
  },
  AvgDialog_142891_Content_84 = {
    Text = "Zuerst kamen schuppenbedeckte Klauenfüße, dann Arme – oder vielleicht weiche, verdrehte Gliedmaßen von Gliederfüßern – seepockenverkrustete Körper und auf gotteslästerliche Weise abscheulicher Schleim..."
  },
  AvgDialog_142891_Content_85 = {
    Text = "Du kanntest das Meer nur als unerschöpfliche Nahrungsquelle. Du hättest dir nie vorstellen können, dass es auch solchen Abscheulichkeiten ein Zuhause bieten könnte. Ihre hervorquellenden, furchteinflößenden Augen waren voller Bosheit, als sie die Gebäude der Stadt anstarrten."
  },
  AvgDialog_142891_Content_86 = {
    Text = "<Change>@4 Tipu ... wohin auch immer du gehst ..."
  },
  AvgDialog_142891_Content_87 = {
    Text = "<Change>... musst du hier hindurch ... die Auflösung nähren, dich der Auflösung hingeben! Fleisch, Fleisch!!"
  },
  AvgDialog_142891_Content_88 = {
    Text = "<Small:<Shake:Onkel, ein Mon-, ein Monster!!>>"
  },
  AvgDialog_142891_Content_89 = {
    Text = "Im nächsten Moment stürzte die gesichtslose geflügelte Kreatur unter dir hinab. Pontos spreizte seine knochigen Finger, und ein düsteres Licht schoss auf die beiden elenden Monster zu."
  },
  AvgDialog_142891_Content_9 = {
    Text = "Sie hält eine schief geflochtene Grashüpfer-Figur in den Händen und legt sie auf die Bettdecke."
  },
  AvgDialog_142891_Content_90 = {Text = "Ngh, mmph!"},
  AvgDialog_142891_Content_91 = {
    Text = "Sie sackten leblos zu Boden, wie zwei abgeschlagene Steinstatuen."
  },
  AvgDialog_142891_Content_92 = {
    Text = "Tapp – eine sanfte Berührung."
  },
  AvgDialog_142891_Content_93 = {
    Text = "Dann stürzten die beiden Hälften des Körpers zu Boden und zerfielen zu grauem Staub, der vom Meereswind davongetragen wurde."
  },
  AvgDialog_142891_Content_94 = {
    Text = "Puh, ich wusste, dass immer ein oder zwei durch die Maschen schlüpfen — Leisha und die anderen sind einfach zu unvorsichtig."
  },
  AvgDialog_142891_Content_95 = {
    Text = "<Shake:Mama und die anderen? Onkel Pontos, was hat das alles zu bedeuten?!>"
  },
  AvgDialog_142891_Content_96 = {
    Text = "Der Schreck ließ deine Beine beinahe einknicken, und du rutschtest fast vom glatten Rücken der Kreatur."
  },
  AvgDialog_142891_Content_97 = {
    Text = "Halt noch ein bisschen durch. Ich muss zuerst sicherstellen, dass es ihnen gut geht."
  },
  AvgDialog_142891_Content_98 = {
    Text = "Pontos klopfte dir auf die Schulter und führte dann das Wesen dazu, euch beide zur Küste auf der anderen Seite der Stadt zu tragen."
  },
  AvgDialog_142891_Content_99 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_142892_Content_1 = {
    Text = "Als du fort warst"
  },
  AvgDialog_142892_Content_10 = {
    Text = "Gelber Sand."
  },
  AvgDialog_142892_Content_11 = {
    Text = "Schneefelder."
  },
  AvgDialog_142892_Content_12 = {Text = "Leere."},
  AvgDialog_142892_Content_13 = {
    Text = "Und dann zurück in die Nacht."
  },
  AvgDialog_142892_Content_14 = {
    Text = "Dies ist keine Reise oder Flugbahn, die Menschen begreifen können. Zeit und Raum haben jede Bedeutung verloren. Du durchquerst einfach immer weiter, patroullierst. Du erlebst alles, und wirst dann von allem zerstört."
  },
  AvgDialog_142892_Content_15 = {
    Text = "Da Sie es gewagt haben einzudringen, verbannt Sie aus der sterblichen Welt! Lehrt Sie, uns zu fürchten! Sorgt dafür, dass Sie sich meinen Namen merken!"
  },
  AvgDialog_142892_Content_16 = {
    Text = "Pontos verschwendet die Macht, die er erlangt hat, mit rücksichtsloser Verschwendungssucht, und die Wesen, die ihn gewonnen haben, zerreißen nun auch seine Feinde."
  },
  AvgDialog_142892_Content_17 = {
    Text = "Unzählige verdrehte, abscheuliche Monster werden von den Knechtgaunts und den Gauntwards gejagt."
  },
  AvgDialog_142892_Content_18 = {
    Text = "Sie werden durchbohrt, Teil des Treibens gemacht, und endlose Pfiffe und Lacher der Feier erklingen."
  },
  AvgDialog_142892_Content_19 = {
    Text = "Nein, nein, nicht schon wieder, neinneinneinneinnein!!!!!!"
  },
  AvgDialog_142892_Content_2 = {
    Text = "Das seltsame Gefühl von glattem Fell, der scharfe Stachel an seinem Schweif, gewaltige Flügelmembranen, die lautlos durch den Nachthimmel schnitten."
  },
  AvgDialog_142892_Content_20 = {
    Text = "Du sahst mit eigenen Augen, wie der Strahl, den Pontos entfesselte, den Fanatiker zu Staub zerfallen ließ, doch unmittelbar danach setzte sich Ihr Körper erneut zusammen, ein Schrei der Angst brach aus Ihrem Mund hervor."
  },
  AvgDialog_142892_Content_21 = {
    Text = "Dies war der glühendste aller Kultisten. Und nun hat er bereits mehr Male als irgendjemand zählen könnte Tod und qualvolle Wiederherstellung erlitten."
  },
  AvgDialog_142892_Content_22 = {
    Text = "Onkel Pontos, dieses... <Italic:Ding>... wird wiedergeboren?"
  },
  AvgDialog_142892_Content_23 = {
    Text = "Nein. Es stirbt und kehrt einfach immer wieder zurück, um das Leiden zu kosten, das ihm versprochen wurde."
  },
  AvgDialog_142892_Content_24 = {
    Text = "Manchmal lasse ich Sie durchaus sterben, solange Sie ihrer Hingabe an diese blasphemischen, schmutzigen Götter abschwören."
  },
  AvgDialog_142892_Content_25 = {
    Text = "Aber wenn Ihr Glaube zu standhaft ist, dann kann nicht einmal der Tod Sie vom Leiden erlösen."
  },
  AvgDialog_142892_Content_26 = {
    Text = "So beiläufig sprechend, als wäre es eine Nebensächlichkeit, hob Pontos seine Handfläche. Eine unsichtbare Kraft breitete die Arme des Fanatikers weit aus, beugte seinen Oberkörper nach vorne und zwang ihn, sich vor Pontos niederzuknien."
  },
  AvgDialog_142892_Content_27 = {
    Text = "Nun, sag mir noch einmal — betest du noch immer deinen schmutzigen Gott an?"
  },
  AvgDialog_142892_Content_28 = {
    Text = "<LightGray:*Schluchzen> Nein... nein, ich bitte dich, ich flehe dich an, lass mich sterben, solange du mich sterben lässt!"
  },
  AvgDialog_142892_Content_29 = {
    Text = "<Shake:Hahaha, hahahahahaha, kein Retter, es gibt überhaupt keinen Retter, nur AB@2S, nur @2@3!!>"
  },
  AvgDialog_142892_Content_3 = {
    Text = "Pontos nimmt dich mit auf die Jagd, die Ebwynnos' nächtlichem Treiben vorausgeht."
  },
  AvgDialog_142892_Content_30 = {
    Text = "Sehr gut, Beute. Heb den Kopf. Entblöße deine Kehle."
  },
  AvgDialog_142892_Content_31 = {
    Text = "Der Fanatiker bricht geistig zusammen und stößt verzerrte Schluchzer und irres Gelächter aus, kriecht auf den Knien vorwärts und reckt den Hals in einer unheimlichen Haltung hoch."
  },
  AvgDialog_142892_Content_32 = {
    Text = "Ich werde dir den Tod schenken."
  },
  AvgDialog_142892_Content_33 = {
    Text = "Das Licht schmolz durch Seine Kehle wie ein heißes Messer durch Butter. Sein Körper zerfiel plötzlich zu Asche und Staub, vom Wind in den Ozean geweht."
  },
  AvgDialog_142892_Content_34 = {
    Text = "Diesmal kehrt der erbärmliche Kultist nicht zurück."
  },
  AvgDialog_142892_Content_35 = {
    Text = "Wohin gehen die anderen? Die Monster, die gefangen werden?"
  },
  AvgDialog_142892_Content_36 = {
    Text = "Sie sind auch in Ebwynnos."
  },
  AvgDialog_142892_Content_37 = {
    Text = "Ein ebenso ewiges Ebwynnos, nur ohne die Freude."
  },
  AvgDialog_142892_Content_38 = {
    Text = "Dort existiert nichts. Selbst Schmerz wäre eine Gnade."
  },
  AvgDialog_142892_Content_39 = {
    Text = "Du verstehst es halb. Das Mondlicht scheint. Die Gaunts bewachen dich, während diese seltsame Reise sich ihrem Ende nähert."
  },
  AvgDialog_142892_Content_4 = {
    Text = "Durch unzählige, unbegreifliche Medien jagen die Menschen von Ebwynnos ihre „Beute\" durch unzählige Dimensionen."
  },
  AvgDialog_142892_Content_40 = {
    Text = "Schließ die Augen, Jago."
  },
  AvgDialog_142892_Content_41 = {
    Text = "Eine feuchte, vertraute, innige Dunkelheit umarmte dich, verschlang dich ganz."
  },
  AvgDialog_142892_Content_42 = {
    Text = "Du kehrtest zum Hohen Haus zurück. Pontos stieg vom Streitwagen herab und enthüllte den Auftakt zu einem weiteren Gelage."
  },
  AvgDialog_142892_Content_43 = {
    Text = "Dieses Kind scheint dich ziemlich ins Herz geschlossen zu haben."
  },
  AvgDialog_142892_Content_44 = {
    Text = "Nahe der Fensterbank an der Terrasse wandte sich Pontos von der lebhaften Menge ab und streckte seine Hand dem Alptraum entgegen, der vor dem Fenster kreiste."
  },
  AvgDialog_142892_Content_45 = {
    Text = "Ich kann mich aus irgendeinem Grund an vieles nicht klar erinnern, aber... Onkel Pontos, du bist kein Mensch mehr, und dies ist nicht mehr die Welt, wie ich sie kenne, oder?"
  },
  AvgDialog_142892_Content_46 = {
    Text = "Bin ich bereits tot?"
  },
  AvgDialog_142892_Content_47 = {
    Text = "Scheinbar nicht erwartend, dass du so direkt fragen würdest, hob Pontos überrascht die Augenbrauen und – lachte dann."
  },
  AvgDialog_142892_Content_48 = {
    Text = "Mein lieber kleiner Freund, natürlich nicht."
  },
  AvgDialog_142892_Content_49 = {
    Text = "Bleib in Ebwynnos, und du wirst das großartige und außergewöhnliche Leben führen, nach dem du dich sehntest, als du als Kind Geschichtenbücher gelesen hast. Du wirst nie wieder zermürbt werden."
  },
  AvgDialog_142892_Content_5 = {
    Text = "Unheimliche Lichtschimmer tanzten noch immer in den Glasfassaden des Hauses."
  },
  AvgDialog_142892_Content_50 = {
    Text = "Wir werden Abenteuer erleben, der alltäglichen Welt entfliehen. Jene Feinde, die Umbruch und Unheil über unser Leben brachten, werden letztlich niedergeschlagen, bis sie es nie wieder wagen, ihr Gesicht zu zeigen."
  },
  AvgDialog_142892_Content_51 = {
    Text = "Du holtest tief Luft. Du spürtest wieder diese Heuschrecke—grob, rau, leicht stachelig."
  },
  AvgDialog_142892_Content_52 = {
    Text = "Ja, das klingt alles wunderbar."
  },
  AvgDialog_142892_Content_53 = {
    Text = "Aber welchen Preis muss ich dafür zahlen, Onkel Pontos?"
  },
  AvgDialog_142892_Content_54 = {
    Text = "Seine Stirn runzelte sich mit quälender Langsamkeit und trug dabei eine Art hochmütiger Arroganz, die dir fremd war."
  },
  AvgDialog_142892_Content_55 = {
    Text = "Der Preis ist nur... etwas, das überhaupt keine Rolle spielt, etwas, das du nicht brauchst und nicht in Erinnerung behalten wirst. <Red:Gib es mir>, Jago."
  },
  AvgDialog_142892_Content_56 = {
    Text = "In dem Moment, als er zu Ende gesprochen hatte, senkte sich der Stachelschwanz des Albtraums von außerhalb des Fensters auf deine Tasche herab."
  },
  AvgDialog_142892_Content_57 = {
    Text = "Hin zu der schiefen Heuschrecke, die du versteckt hast."
  },
  AvgDialog_142892_Content_58 = {Text = "Nein!"},
  AvgDialog_142892_Content_59 = {
    Text = "Du stolpertest instinktiv zurück, doch die Bewegung schien Pontos zu erzürnen, und er packte deinen Arm."
  },
  AvgDialog_142892_Content_6 = {
    Text = "Alpträume kreisten in der Luft, bis Pontos — der neben dir in einem Streitwagen stand, der ein unbeschreibliches Perlmuttleuchten ausstrahlte — einen durchdringenden Ruf ausstieß."
  },
  AvgDialog_142892_Content_60 = {
    Text = "Du verstehst es einfach nicht, Kind. Weißt du, wie viel Mühe ich aufgewendet habe, um dich zu finden..."
  },
  AvgDialog_142892_Content_61 = {
    Text = "Gurr–gurr, gurr–gurr..."
  },
  AvgDialog_142892_Content_62 = {
    Text = "Du erstarrtest auf der Stelle. Es waren nicht nur Pontos' Finger, die gegen deine Haut drückten—eine namenlose Angst ließ dich aufblicken, und Pontos' tiefblaue Pupillen lasteten schwer auf dir."
  },
  AvgDialog_142892_Content_63 = {
    Text = "Da du sehen willst, dann schau hin—schau genau hin, wovor ich dich gerettet habe."
  },
  AvgDialog_142892_Content_64 = {
    Text = "Du wirst erneut <Red:verschluckt>."
  },
  AvgDialog_142892_Content_65 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_142892_Content_66 = {
    Text = "Hey, hey, alter Freund, hast du gehört, was ich gesagt habe? Du bist schon wieder weggetreten! Pass auf!"
  },
  AvgDialog_142892_Content_67 = {
    Text = "Platsch! Schlammiges Wasser traf dein Gesicht, und du kehrtest schlagartig in die Realität zurück, starrtest die Person neben dir verständnislos an. Alt, gebeugt und endlos schwatzend—aber du erkanntest ihn. Es war unverkennbar ein alter Orney."
  },
  AvgDialog_142892_Content_68 = {
    Text = "Diese verdammten Seemänner, absolut außer Kontrolle! Wenn du mich fragst, das ganze Herumreisen hat ihre Herzen wild gemacht. Sie können sich auf nichts Praktisches konzentrieren!"
  },
  AvgDialog_142892_Content_69 = {
    Text = "Orney? ...Wovon redest du? Du hast als Kind immer davon geträumt, Seemann zu werden und jeden Kontinent zu sehen!"
  },
  AvgDialog_142892_Content_7 = {
    Text = "Ergreift Sie, sorgt dafür, dass Sie nie wieder entkommen können, lasst Sie hier leiden für alle Ewigkeit!"
  },
  AvgDialog_142892_Content_70 = {
    Text = "Das soll ich wirklich gesagt haben? Sei nicht albern. In unserem Alter solltest du wissen, dass Stabilität das Beste ist."
  },
  AvgDialog_142892_Content_71 = {
    Text = "Hast du das vergessen, alter Freund – seit dem zweiten Studienjahr reden wir darüber nicht mehr. Wir plaudern über die Zeitungsnachrichten, diese verdammten Berichte, die Rente, das Familientreffen alle zwei Wochen."
  },
  AvgDialog_142892_Content_72 = {
    Text = "Er klopfte dir auf die Schulter und holte zittrig zwei Papiertüten vom Apothekenfenster."
  },
  AvgDialog_142892_Content_73 = {
    Text = "Bist du nicht wie ich, nachdem du die Universität abgeschlossen hast und hierher zurückgekommen bist? Gott sei Dank, wir sind nicht einmal faul geworden, lange Reisen zu machen."
  },
  AvgDialog_142892_Content_74 = {
    Text = "Diese verdammte Arthritis. Gott sei Dank — abgesehen von dir und diesen Schmerzmitteln gibt es nichts, was mich zwingt, das Haus zu verlassen."
  },
  AvgDialog_142892_Content_75 = {
    Text = "Einsamkeit, ha! Als wir jung waren, dachten wir, sie sei ungefähr so real wie der Yeti."
  },
  AvgDialog_142892_Content_76 = {
    Text = "Olny redete weiter vor sich hin, während du auf seine sich bewegenden Lippen starrtest, als dich plötzlich ein Schwindel aus dem alltäglichen Trott riss."
  },
  AvgDialog_142892_Content_77 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_142892_Content_78 = {
    Text = "Siehst du, was aus Olni geworden ist durch diese gewöhnlichen Tage? Schau nochmal hin, was du dafür erhalten hast."
  },
  AvgDialog_142892_Content_79 = {
    Text = "Du siehst dich, wie du im Bett liegst und verwelkt aussiehst."
  },
  AvgDialog_142892_Content_8 = {Text = "Wolken."},
  AvgDialog_142892_Content_80 = {
    Text = "Natürlich werden sie am Anfang traurig sein und ein paar Tränen für dich vergießen."
  },
  AvgDialog_142892_Content_81 = {
    Text = "Du siehst ein Paar mit ihrer kleinen Tochter, die einen Spaziergang machen und sich gegenseitig Trost spenden."
  },
  AvgDialog_142892_Content_82 = {
    Text = "Aber in einer Woche, oder sogar in ein paar Tagen, werden sie darüber hinwegkommen."
  },
  AvgDialog_142892_Content_83 = {
    Text = "Abendessen, Spaziergänge, ab an die Universität – wer weiß? Die Kinder halten vielleicht etwas länger durch. Nicht viel, natürlich."
  },
  AvgDialog_142892_Content_84 = {
    Text = "Am Ende wird nichts übrig bleiben. Niemand wird sich an dich erinnern."
  },
  AvgDialog_142892_Content_85 = {
    Text = "Winter, Frühling, wieder Winter. Du siehst, wie der Staub sich langsam im Haus niederlässt."
  },
  AvgDialog_142892_Content_86 = {
    Text = "Hast du verstanden, Jag? Ich habe nur die... interessanten Teile von euch, die lebendigen Teile, nach Eberjans gebracht."
  },
  AvgDialog_142892_Content_87 = {
    Text = "Deine leere Hülle von einem Körper ist dem Tod nah. Mit oder ohne dich werden alle, die du je gekannt hast, ihr eigenes Leben weiterleben – Leben, die nichts mit dir zu tun haben."
  },
  AvgDialog_142892_Content_88 = {
    Text = "Die Stimme von Pontus hallt in deinem Ohr, und im nächsten Moment erscheinst du erneut in der Halle des Epojans."
  },
  AvgDialog_142892_Content_89 = {
    Text = "Jetzt, Jag, denk nach, denk gut nach, lass diesen Körper los, gib die sinnlosen Erinnerungen auf und bleib bei uns."
  },
  AvgDialog_142892_Content_9 = {
    Text = "Vernichtete Erde."
  },
  AvgDialog_142892_Content_90 = {
    Text = "Die Olney von Eberjans, Onkel White und jeder im überfüllten Tanzsaal schienen plötzlich hierher aufmerksam zu werden."
  },
  AvgDialog_142892_Content_91 = {
    Text = "Hey, warum habt ihr zwei so einen Gesichtsausdruck? Wir haben gerade wieder einen großen Sieg errungen"
  },
  AvgDialog_142892_Content_92 = {
    Text = "Komm, Jag, trink mit uns ordentlich einen, es gibt nichts, worüber man sich bei Eberjans Sorgen machen müsste"
  },
  AvgDialog_142892_Content_93 = {
    Text = "Sie lachen herzlich und nehmen dich in ihre Mitte auf."
  },
  AvgDialog_142892_Content_94 = {
    Text = "Die Menschen reichen ihre Beute nun herum. Die Gezeiten rauschen dir wieder in den Ohren."
  },
  AvgDialog_142892_Content_95 = {
    Text = "Pontos streckt dir seine Hand entgegen und wartet darauf, dass du sie ergreifst."
  },
  AvgDialog_142892_Content_96 = {
    Text = "Wie das „Abschluss-Handschlag\", den ihr euch als Kinder ausgemacht habt."
  },
  AvgDialog_142893_Content_1 = {Text = "Der Grund"},
  AvgDialog_142893_Content_10 = {
    Text = "<Red:So sollte es nicht sein.>"
  },
  AvgDialog_142893_Content_11 = {
    Text = "Du hättest zufällig deine Blutlinie entdecken sollen, Mama wäre von Onkel Pontos überredet worden, dich zu führen, und gemeinsam hättet ihr euch auf eine Reise begeben und allerlei aufregende, spannende und wunderbare Dinge erlebt."
  },
  AvgDialog_142893_Content_12 = {
    Text = "<Shake:Und dann wirst du ein großartiger <Red:Held> werden, so steht es in allen Abenteuerromanen.>"
  },
  AvgDialog_142893_Content_13 = {
    Text = "Jago! Reiß dich zusammen, alles wird gut, deine Mutter ist die stärkste der Gauntwards, die ich je gesehen habe, alles wird sich lösen!"
  },
  AvgDialog_142893_Content_14 = {
    Text = "Ich... Onkel Pontos, Mama..."
  },
  AvgDialog_142893_Content_15 = {
    Text = "Die einst friedliche Stadt war vollständig in Flammen gehüllt."
  },
  AvgDialog_142893_Content_16 = {
    Text = "Gerade erst ein Tag vergangen, und plötzlich, wie aus dem Nichts, überfluteten fanatische Gläubige alles, wohin das Auge reichte."
  },
  AvgDialog_142893_Content_17 = {
    Text = "Unter ihnen waren sowohl Menschen als auch durch und durch Monster, und die wahllosen Angriffe ließen die gesamte Stadt in hellen Flammen brennen."
  },
  AvgDialog_142893_Content_18 = {
    Text = "Blut mit einem salzigen, metallischen Geschmack spritzte über dein Gesicht und deinen Körper. Pontos kanalisierte verzweifelt die Jagdpfeife in seiner Hand und riss mit roher Gewalt an der Seite seines Alptraums einen Weg frei."
  },
  AvgDialog_142893_Content_19 = {
    Text = "Pontos, nimm Jago und lauf!"
  },
  AvgDialog_142893_Content_2 = {
    Text = "In jener Nacht, erschöpft von zu viel Schreck und zu vielen Gedanken, schliefst du bald ein."
  },
  AvgDialog_142893_Content_20 = {
    Text = "Leisha, die zusammen mit den anderen Gauntwards verzweifelt versuchte, die Monsterwelle aufzuhalten, erblickte dich wohlbehalten und ihre Augen leuchteten auf — sie schrie Pontos mit heiserer Stimme an."
  },
  AvgDialog_142893_Content_21 = {
    Text = "Kreischhhh!"
  },
  AvgDialog_142893_Content_22 = {
    Text = "Ein weiterer seeanemonenartiger Kopf wurde von den scharfen Klauen des Alptraums zerrissen. Leisha schleuderte beiläufig einen Streifen desselben rätselhaften weißen Lichts wie Pontos und hinderte ihn daran, auf sie zuzustürmen."
  },
  AvgDialog_142893_Content_23 = {
    Text = "Diesen Kampf können wir nicht gewinnen, aber wir können euch noch etwas Zeit verschaffen. Lauft, so weit ihr könnt!"
  },
  AvgDialog_142893_Content_24 = {
    Text = "Was soll das, noch mehr Feinde hast du schon mühelos besiegt, es wird nichts passieren! Und außerdem, du weißt es, wir haben immer noch einen Weg."
  },
  AvgDialog_142893_Content_25 = {
    Text = "Du wusstest nicht, was Onkel Pontos mit „einem Ausweg\" meinte. Du sahst nur, wie sein Blick auf diese Jagdpfeife fiel, die er seit dem Tag seiner Rückkehr nicht aus der Hand gelegt hatte."
  },
  AvgDialog_142893_Content_26 = {
    Text = "Nein, <Red:auf keinen Fall.>"
  },
  AvgDialog_142893_Content_27 = {
    Text = "<Shake:Ich weiß, was du denkst – <Red:mein Bruder darf auf keinen Fall für immer an diesem verfluchten Ort gefangen bleiben!>   >"
  },
  AvgDialog_142893_Content_28 = {
    Text = "Umarmt das Gelage@1, nährt die Erosion!"
  },
  AvgDialog_142893_Content_29 = {Text = "Leisha!!!"},
  AvgDialog_142893_Content_3 = {
    Text = "Sowohl du als auch Pontos dachtet, ihr würdet noch viele weitere Gelegenheiten haben, darüber zu reden."
  },
  AvgDialog_142893_Content_30 = {
    Text = "Im tosenden Krachen brechender Schuppen traten die blutrot unterlaufenen Augen eines Fanatikers, dessen halber Körper bereits aufgerissen war, vollständig hervor, und er stürzte sich wutentbrannt brummelnd auf Leisha."
  },
  AvgDialog_142893_Content_31 = {
    Text = "...Das zähneknirschende Geräusch von Haut und Muskeln, die auseinandergerissen wurden."
  },
  AvgDialog_142893_Content_32 = {
    Text = "Das Geräusch zweier Körper, die auf die Kopfsteinpflasterstraße krachten."
  },
  AvgDialog_142893_Content_33 = {
    Text = "Das Geräusch herausquellender Eingeweide."
  },
  AvgDialog_142893_Content_34 = {
    Text = "Dann wurde die Welt in einem Augenblick still. Man konnte nichts hören, nichts sehen."
  },
  AvgDialog_142893_Content_35 = {
    Text = "Blut, Nachthimmel, Mond."
  },
  AvgDialog_142893_Content_36 = {
    Text = "Ein blutroter Mond, fern am weiten Himmel hängend."
  },
  AvgDialog_142893_Content_37 = {
    Text = "Ah... ahhh."
  },
  AvgDialog_142893_Content_38 = {
    Text = "AAAAAAAAHHHHH!!!!!"
  },
  AvgDialog_142893_Content_39 = {
    Text = "Nach einem kurzen, atemlosen Stöhnen, das sich aus den Tiefen seiner Kehle presste, stieß Pontos etwas aus, das du in deinem ganzen Leben noch nie gehört hattest."
  },
  AvgDialog_142893_Content_4 = {
    Text = "<Red:Aber das hattet ihr nicht.>"
  },
  AvgDialog_142893_Content_40 = {
    Text = "Ein Klageschrei, völlig unmenschlich."
  },
  AvgDialog_142893_Content_41 = {
    Text = "Schwe— Schwester... Leisha, LEISHA!!!"
  },
  AvgDialog_142893_Content_42 = {
    Text = "Ein durchdringendes Summen hallte durch dein Gehirn, und eine überwältigende Welle der Fassungslosigkeit brach wie eine Flutwelle über dich herein. Nein, nein, nein, nein, nein nein nein nein nein nein..."
  },
  AvgDialog_142893_Content_43 = {
    Text = "Niemand überlebte. Die Knechtgaunts, die tagsüber wie freundliche Nachbarn gewirkt hatten, fielen einer nach dem anderen. Die gewöhnlichen Stadtbewohner schrien im Feuermeer und in der Flut der Monster."
  },
  AvgDialog_142893_Content_44 = {
    Text = "Doch du konntest nichts davon mehr hören. Dein Körper hatte dich vollständig verraten und heulte zusammen mit ihnen, ein roher, durchdringender Schrei."
  },
  AvgDialog_142893_Content_45 = {
    Text = "<Change>Opfergabe! Opfert sie alle dem <Red:Rapture>!"
  },
  AvgDialog_142893_Content_46 = {
    Text = "Die anderen Kultisten hatten dich ohne die geringste Mühe ausgemacht, und gerade als diese schuppigen Klauen, triefend von gottlosem Schleim, nach dir griffen..."
  },
  AvgDialog_142893_Content_47 = {
    Text = "Pontos blies die Jagdpfeife."
  },
  AvgDialog_142893_Content_48 = {
    Text = "Du hattest noch nie einen so schrillen und so uralten Laut gehört. Eine unbegreifliche Kraft drang direkt durch deine Trommelfelle und hämmerte auf jeden letzten Fetzen Verstand in deinem Kopf ein."
  },
  AvgDialog_142893_Content_49 = {
    Text = "Ein unvergleichlicher, gewaltiger Druck kam auf das Land niederprasseln!"
  },
  AvgDialog_142893_Content_5 = {
    Text = "Zischhhh–!"
  },
  AvgDialog_142893_Content_50 = {
    Text = "Eine riesige, unsichtbare Kraft drückte Pontos flach auf den Boden, doch er schien es überhaupt nicht zu spüren, die Augen weit aufgerissen, während er ein unverständliches Gebet rezitierte."
  },
  AvgDialog_142893_Content_51 = {
    Text = "O @2, @4,@3 Herr des Abgrunds, ich rufe dich an im Namen von @3..."
  },
  AvgDialog_142893_Content_52 = {
    Text = "Unzählige schwarzen Armen ähnelnde Wesen streckten sich aus Rissen hervor, die tiefer waren als der älteste Ozean, und tasteten nach der einzigen <Red:Beute>, die sie begehrten."
  },
  AvgDialog_142893_Content_53 = {
    Text = "<Shake:Sie tasteten nach dem <Red:Herrn >, den sie erwählt hatten.>"
  },
  AvgDialog_142893_Content_54 = {
    Text = "<Change>Nimm mein Fleisch, nimm meine Seele, nimm alles!"
  },
  AvgDialog_142893_Content_55 = {
    Text = "Auf dem Gesicht, das stets ein unbeschwertes Lächeln trug, erschien nun ein Ausdruck tragischer Entschlossenheit und rücksichtsloser Hingabe."
  },
  AvgDialog_142893_Content_56 = {
    Text = "Als etwas weit Größeres und Gewaltigeres in ihn hineinfloss, erhoben sich himmelbedeckende Schwingen und bildeten Schicht um Schicht pechschwarze Barrieren."
  },
  AvgDialog_142893_Content_57 = {
    Text = "<Change>Erhöre das Gebet deines Executors – mahle sie alle zu Staub!!"
  },
  AvgDialog_142893_Content_58 = {
    Text = "Inzwischen konnte niemand mehr diesen tiefen, unergründlichen Klang von der Stimme unterscheiden, die einst Pontos' gewesen war."
  },
  AvgDialog_142893_Content_59 = {
    Text = "Sie wurden eins, ununterscheidbar, wie Es wollte."
  },
  AvgDialog_142893_Content_6 = {
    Text = "<Shake:<Red:So nicht, das Abenteuer eines Helden sollte nicht so sein.>>"
  },
  AvgDialog_142893_Content_60 = {
    Text = "Als der schrille Pfiff entlang der Küstenlinie hallte, zerfiel jeder letzte Kultist zu weißer Asche."
  },
  AvgDialog_142893_Content_61 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_142893_Content_62 = {
    Text = "Ahhh! ...Was geschah dann? Onkel Pontos, und Großvaters Mutter... sie..."
  },
  AvgDialog_142893_Content_63 = {
    Text = "Vera, die die ganze Zeit den Atem angehalten hatte, konnte sich schließlich nicht mehr zurückhalten und rief auf, die Tränen standen ihr fast in den Augen."
  },
  AvgDialog_142893_Content_64 = {
    Text = "Was danach geschah, egal wie sehr ich es versuche, ich kann mich einfach nicht erinnern. Alles, woran ich mich erinnere, ist..."
  },
  AvgDialog_142893_Content_65 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_142893_Content_66 = {
    Text = "*Schluchz*... Jago... Jago! Gott sei Dank, du bist endlich wach."
  },
  AvgDialog_142893_Content_67 = {
    Text = "Papa, Tante Resa, alle anderen, unsere Stadt, alles ist... WAAAAAAH!!"
  },
  AvgDialog_142893_Content_68 = {
    Text = "Durch Orneys schluchzenden Bericht, deiner Kindheitsfreundin, erfuhrst du, dass die gesamte Stadt in einer gewaltigen Explosion ausgelöscht worden war."
  },
  AvgDialog_142893_Content_69 = {
    Text = "Nur eine Handvoll Menschen überlebte in den Ruinen und wurde von Verwandten oder Freunden in benachbarten Städten aufgenommen. Du warst vier volle Tage bewusstlos gewesen."
  },
  AvgDialog_142893_Content_7 = {
    Text = "Jago, schließ die Augen und folge mir!"
  },
  AvgDialog_142893_Content_70 = {
    Text = "Nein, es war keine Explosion. Ich erinnere mich deutlich... Ugh! Mein Kopf tut so weh."
  },
  AvgDialog_142893_Content_71 = {
    Text = "Das durchdringende weiße Rauschen in deinem Kopf ließ dich zurück in den Schlaf gleiten. Als du erneut erwachtest, fandest du dich benommen in jemandes Armen geborgen."
  },
  AvgDialog_142893_Content_72 = {
    Text = "Mama... Mama?!"
  },
  AvgDialog_142893_Content_73 = {
    Text = "Beweg dich nicht zu viel. Deine Wunden sind noch nicht verheilt."
  },
  AvgDialog_142893_Content_74 = {
    Text = "Du sahst mit eigenen Augen, dass Leisha – deren Bauch von den Fanatikern aufgerissen worden war – völlig unversehrt am Bett saß. Die überwältigende Freude ließ deine Augen weit aufspringen, während Tränen über dein Gesicht strömten."
  },
  AvgDialog_142893_Content_75 = {
    Text = "Mama! War es alles ein Traum? Ich wusste, dass du in Ordnung bist, du lebst noch."
  },
  AvgDialog_142893_Content_76 = {
    Text = "Shh, hör mir zu, Jago. Mama muss dich verlassen und an einen sehr weit entfernten Ort gehen."
  },
  AvgDialog_142893_Content_77 = {
    Text = "Orneys Familie wird gut auf dich aufpassen. Morgen früh werden sie genug Geld auf dem Tisch finden. Du musst gut leben."
  },
  AvgDialog_142893_Content_78 = {
    Text = "Warte, mich verlassen? Mama, warum? Was ist mit Onkel Pontos? Wo ist er?"
  },
  AvgDialog_142893_Content_79 = {
    Text = "Leisha verstummte plötzlich. Nach einem Moment umklammerte sie deine Hand fest, drückte den Kupferkompass, den du fallen gelassen hattest, zurück in deine Handfläche und beugte sich hinab, um deine Stirn zu küssen."
  },
  AvgDialog_142893_Content_8 = {
    Text = "Roar! Roar!"
  },
  AvgDialog_142893_Content_80 = {
    Text = "Jago, halt das fest. Schwöre mir, dass du sicher weiterleben wirst, irgendwo."
  },
  AvgDialog_142893_Content_81 = {
    Text = "Du wolltest verzweifelt den Kopf schütteln, aber Leisha gab dir keine Gelegenheit dazu."
  },
  AvgDialog_142893_Content_82 = {
    Text = "Denk daran, such niemals nach mir oder deinem Onkel. Niemals."
  },
  AvgDialog_142893_Content_83 = {Text = "Mama!..."},
  AvgDialog_142893_Content_84 = {
    Text = "Du fährst ruckartig hoch."
  },
  AvgDialog_142893_Content_85 = {
    Text = "Ein sanfter Wind bewegte die Blätter. Die Nacht war hereingebrochen, bevor du es merktest."
  },
  AvgDialog_142893_Content_86 = {
    Text = "War es ein Traum? Deine Mutter Leisha war nirgends zu sehen. Orney, der an deinem Bett döste und über dich wachte, schien aufgeschreckt."
  },
  AvgDialog_142893_Content_87 = {
    Text = "Jago?! Was ist los?"
  },
  AvgDialog_142893_Content_88 = {
    Text = "Du starrtest mit leerem Blick aus dem Fenster. Der Mond hing noch immer weit entfernt am Himmel."
  },
  AvgDialog_142893_Content_89 = {
    Text = "Darüber hinaus war da nichts."
  },
  AvgDialog_142893_Content_9 = {
    Text = "Pontos hält dich fest und rennt landeinwärts, weg von der Küste, sein Rücken schützt dich. Du starrst entsetzt auf die überall lodernden Flammen und die Menschen, die durch das Chaos flüchten."
  },
  AvgDialog_145231_Content_1 = {Text = "Bang—"},
  AvgDialog_145231_Content_10 = {
    Text = "Heute konnte ich mich weder auf meine Klinge noch auf meinen Feind konzentrieren."
  },
  AvgDialog_145231_Content_11 = {
    Text = "Etwas anderes hat mich ständig abgelenkt."
  },
  AvgDialog_145231_Content_12 = {
    Text = "Etwas anderes? Was denn?"
  },
  AvgDialog_145231_Content_13 = {Text = "Du."},
  AvgDialog_145231_Content_14 = {
    Text = "??? Du meinst..."
  },
  AvgDialog_145231_Content_15 = {
    Text = "Ja. Diese wahnsinnige Thais und ihr wahnsinniger Fluss."
  },
  AvgDialog_145231_Content_16 = {
    Text = "Es ist in Ordnung, mal einen Kampf zu verlieren. Ruh dich hier aus, ich hole dir etwas Medizin..."
  },
  AvgDialog_145231_Content_17 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_145231_Content_18 = {
    Text = "Du versuchst, dich aus dem Zimmer zu schleichen, aber Lotan lässt dir keine Chance."
  },
  AvgDialog_145231_Content_19 = {
    Text = "Zwei scharfe Knackgeräusche ertönen neben deinen Ohren. Lotans Knochenklingen durchbohren das Bett, ihre Knochenhilze pinnen deine Hände an die Matratze. Du kannst dich nicht bewegen."
  },
  AvgDialog_145231_Content_2 = {
    Text = "Die Tür fliegt mit einem Knall wie eine Kriegstrommel auf. Jemand stürmt blutüberströmt herein und fällt auf dein Bett, nach Luft ringend."
  },
  AvgDialog_145231_Content_20 = {
    Text = "Ich bin nicht hergekommen, um mich zu heilen. Ich bin hergekommen, um ein Problem zu lösen. Und du... bist das Problem."
  },
  AvgDialog_145231_Content_21 = {
    Text = "Hey! Lotan... was... was machst du da..."
  },
  AvgDialog_145231_Content_22 = {
    Text = "Ich hasse es, mich nicht auf den Kampf konzentrieren zu können. Es ärgert mich."
  },
  AvgDialog_145231_Content_23 = {
    Text = "I—Ich habe eine Idee! Du könntest Thais aufsuchen... mmph..."
  },
  AvgDialog_145231_Content_24 = {
    Text = "Eine blutbeschmierte Hand presst sich auf deinen Kiefer und erstickt deine Stimme zu unverständlichem Wimmern."
  },
  AvgDialog_145231_Content_25 = {
    Text = "Mein Geist hatte nie Platz für etwas anderes als den Kampf. Aber eine Ausnahme zu haben... ist gar nicht so schlecht."
  },
  AvgDialog_145231_Content_26 = {
    Text = "Ich konzentriere mich gerne auf eine Sache nach der anderen. Ob es ein Kampf ist... oder etwas anderes."
  },
  AvgDialog_145231_Content_27 = {
    Text = "Lotan starrt auf dich herab, als würde sie eine Rivalin niederringen, die ihr höchste Befriedigung bereitet, und der Kampfgeist in ihren Augen verwandelt sich in unverhüllten Hunger."
  },
  AvgDialog_145231_Content_28 = {
    Text = "Ich habe all dieses Blut deinetwegen vergossen. Dafür wirst du büßen müssen, nicht wahr?"
  },
  AvgDialog_145231_Content_29 = {
    Text = "Die eisernen Klauen ihrer Panzerhandschuhe gleiten an deinem Kiefer entlang, vorbei an deiner Kehle, deiner Brust und deiner Taille... Du strampelst wild und stößt sinnlose Laute aus, doch die Klingen halten dich fest, unbeweglich wie Stein."
  },
  AvgDialog_145231_Content_3 = {Text = "Ah! Wer—"},
  AvgDialog_145231_Content_30 = {
    Text = "Lotan lehnt sich nah heran und bewundert dein vom Kampf gerötetetes Gesicht."
  },
  AvgDialog_145231_Content_31 = {
    Text = "Sie lächelt und lässt ihr Blut von ihren Lippen auf dein Gesicht tropfen."
  },
  AvgDialog_145231_Content_32 = {
    Text = "Strample, so viel du willst. Mal sehen, ob du dich befreien kannst... mein „Gegner\"."
  },
  AvgDialog_145231_Content_4 = {
    Text = "...Lotan? Du bist verletzt?!"
  },
  AvgDialog_145231_Content_5 = {
    Text = "Du starrst ungläubig auf ihre mitgenommene Gestalt."
  },
  AvgDialog_145231_Content_6 = {
    Text = "Nur Kratzer. Nichts Ernstes."
  },
  AvgDialog_145231_Content_7 = {
    Text = "Was ist passiert... Wer konnte dir das antun?"
  },
  AvgDialog_145231_Content_8 = {
    Text = "Ein Astralmeer-Wurm. Hätte ein leichter Abschuss sein sollen. Aber heute..."
  },
  AvgDialog_145231_Content_9 = {
    Text = "Sie runzelt die Stirn, Verärgerung blitzt in ihren Augen auf."
  },
  AvgDialog_14530_Content_10 = {
    Text = "Lippen geöffnet, ein schwacher salziger Geschmack breitete sich aus.\nDas ist kein Regen."
  },
  AvgDialog_14530_Content_11 = {
    Text = "<Gray: ...Tränen?>"
  },
  AvgDialog_14530_Content_12 = {
    Text = "Als wäre es durch den Regen gereinigt, wird die Sicht allmählich klarer."
  },
  AvgDialog_14530_Content_14 = {
    Text = "Ra... Mona..."
  },
  AvgDialog_14530_Content_15 = {
    Text = "Dein Anruf endet plötzlich abrupt."
  },
  AvgDialog_14530_Content_16 = {
    Text = "Überwältigender Stress kommt von allen Seiten, und schwarze Fluten umhüllen dich."
  },
  AvgDialog_14530_Content_17 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_14530_Content_18 = {
    Text = "Die Uhr tickt, und der Klang des Vogelgesangs filtre durch das halb offene Fenster."
  },
  AvgDialog_14530_Content_19 = {
    Text = "Die anhaltende Beklemmung lässt dich instinktiv auf deine Brust klopfen. Langsam aufsitzt, dauert es eine Weile, bis du dich wirklich wach fühlst."
  },
  AvgDialog_14530_Content_2 = {
    Text = "Tränen des Regens"
  },
  AvgDialog_14530_Content_20 = {
    Text = "<Gray:Ich hatte so viele seltsame Träume, aber das ist das erste Mal, dass ich von meinem eigenen Tod geträumt habe.>"
  },
  AvgDialog_14530_Content_21 = {
    Text = "Fühlt sich seltsam an."
  },
  AvgDialog_14530_Content_22 = {
    Text = "Ganz interessant."
  },
  AvgDialog_14530_Content_23 = {
    Text = "Ring Ring—"
  },
  AvgDialog_14530_Content_24 = {
    Text = "Du schaltest den Wecker aus, stehst auf und streckst dich."
  },
  AvgDialog_14530_Content_25 = {
    Text = "Gut, egal. Ich erinnere mich, dass ich heute gehen muss—"
  },
  AvgDialog_14530_Content_26 = {
    Text = "Spezialtraining morgen um 8 Uhr im Erwachungsraum. Sei nicht spät"
  },
  AvgDialog_14530_Content_27 = {
    Text = "Erwachungsraum? Ist es für aufwachbezogene Trainings?"
  },
  AvgDialog_14530_Content_28 = {
    Text = "Teste die Stabilität von <Yellow:Künstliches Gebiet>."
  },
  AvgDialog_14530_Content_29 = {
    Text = "Was ist das?"
  },
  AvgDialog_14530_Content_3 = {Text = "Fallen."},
  AvgDialog_14530_Content_30 = {
    Text = "Ein kleines Projekt, an dem ich gearbeitet habe, mehr so ein Hobby – die Verstärkung des Bewusstseins und des Geistes während des Schlafes durch die Verstärkung des Erweckungsgeräts"
  },
  AvgDialog_14530_Content_31 = {
    Text = "Theoretisch kann ein ausreichend großer Geist ein Reich bilden, und ein stabiles Reich kann unabhängig von der Realität und der Geisterdimension existieren."
  },
  AvgDialog_14530_Content_32 = {
    Text = "Dieses Reich ist dem <Yellow:Bereich> ziemlich ähnlich, deshalb nenne ich es einen Künstlichen Bereich."
  },
  AvgDialog_14530_Content_33 = {
    Text = "Im Gegensatz zu den natürlich vorkommenden Reichen, die aus der Geisterdimension in die Realität eindringen, sind künstliche Reiche nicht aggressiv, stabiler und kontrollierbarer und können <Yellow:ein Moment aus einer Zeit, die in der Gegenwart nicht existiert, nachstellen>."
  },
  AvgDialog_14530_Content_34 = {
    Text = "\"Die Gegenwart existiert nicht\"—Bedeutet das, dass sie die Erinnerungen von jemandem zeigen kann?"
  },
  AvgDialog_14530_Content_35 = {
    Text = "Es kann <Yellow:eine Erinnerung basierend auf dem Verständnis des Geistmeisters präsentieren>, und es erlaubt auch anderen, in diese Erinnerung einzutreten."
  },
  AvgDialog_14530_Content_36 = {
    Text = "Wie beim Betreten des Bereichs...?"
  },
  AvgDialog_14530_Content_37 = {
    Text = "Überhaupt nicht schlecht. Ja, nachdem ein künstlicher Bereich entstanden ist, können andere Individuen physisch eintreten und mit dem Bewusstsein des spirituellen Wesens – dem Besitzer des Bereichs – interagieren."
  },
  AvgDialog_14530_Content_38 = {
    Text = "In diesem Moment, ob der Geist den Besucher erkennt und welche Einstellung er hat... Ha, allein daran zu denken ist interessant."
  },
  AvgDialog_14530_Content_39 = {
    Text = "Wenn das Künstliche Gebiet funktioniert, wird es der beste Weg für Ermittler, Hüter und ihre jeweiligen Erwacher sein, Rapport aufzubauen und das Verständnis zu vertiefen."
  },
  AvgDialog_14530_Content_4 = {
    Text = "Du fällst."
  },
  AvgDialog_14530_Content_40 = {
    Text = "Wenn ich an Dolls eifrige Augen denke, spüre ich ein Frösteln über meinen Kopf laufen."
  },
  AvgDialog_14530_Content_41 = {
    Text = "Sie nennen es spezielle Ausbildung, aber wir sind nur Versuchskaninchen...\nIch hoffe, heute läuft nichts schief."
  },
  AvgDialog_14530_Content_42 = {
    Text = "Du sammelst deinen Geist und drückst die Tür im unterirdischen Gang auf."
  },
  AvgDialog_14530_Content_43 = {
    Text = "Bevor du reagieren kannst, verschlingt dich ein blendendes Licht komplett."
  },
  AvgDialog_14530_Content_5 = {
    Text = "Das Gefühl des Fallens zieht dich, zieht langsam dein Bewusstsein aus dem pechschwarzen Traum heraus."
  },
  AvgDialog_14530_Content_6 = {
    Text = "Ein verschwommenes Licht erscheint vor deinen Augen. Nach einem Moment der Verwirrung stellst du fest, dass es scheint, als hättest du deine Augen geöffnet."
  },
  AvgDialog_14530_Content_7 = {
    Text = "<Gray:Wie... kann nicht klar sehen...>"
  },
  AvgDialog_14530_Content_8 = {
    Text = "Ein Tropfen, zwei Tropfen... Eine kühle Flüssigkeit fällt auf deine Stirn und rollt deine Wange hinunter."
  },
  AvgDialog_14530_Content_9 = {Text = "Regen...?"},
  AvgDialog_145510_Content_10 = {
    Text = "Am Fuß der Schneeberge wächst ein chaotischer Markt aus dem Permafrost. Holzschuppen, Zelte und temporäre Stände aus Yakfell drängen sich dicht gedrängt auf beiden Seiten eines schlammigen Bergpfades."
  },
  AvgDialog_145510_Content_11 = {
    Text = "Der Nordkontinent ist wirklich zu kalt – ich vermisse den heißen Roten Tee von Frau Sylvia ein wenig…"
  },
  AvgDialog_145510_Content_12 = {
    Text = "Auch wenn es noch zu früh ist, das zu sagen – sobald wir nach Misaq zurückgekehrt sind, werde ich Frau Sylvia anweisen, dir rund um die Uhr im Zyklus heißen Roten Tee bereitzustellen."
  },
  AvgDialog_145510_Content_13 = {
    Text = "Jetzt sollten wir uns aber auf die aktuelle Aufgabe konzentrieren."
  },
  AvgDialog_145510_Content_14 = {
    Text = "Du holst das Werbeprospekt heraus, das im Gepäck bereits Knickfalten bekommen hat, und drehst es gegen die Sonne, um es zu vergleichen."
  },
  AvgDialog_145510_Content_15 = {
    Text = "Die Bergkonturen am Rand des Prospekts fügen sich perfekt in die Silhouette der Berge unter dem düsteren Himmel."
  },
  AvgDialog_145510_Content_16 = {
    Text = "Genau hier – nur weiß ich nicht, wie ich jenen mysteriösen Meister finden soll, dessen Titel sich höher stapeln als der Mount Everest…"
  },
  AvgDialog_145510_Content_17 = {
    Text = "<Shake:Alle mal herhööören!>"
  },
  AvgDialog_145510_Content_18 = {
    Text = "Du folgst dem Ruf mit den Augen: Ein Mädchen in Weiß steht allein vor einem Zelt auf einem kleinen Hügel und blickt auf die spärliche Menge herab."
  },
  AvgDialog_145510_Content_19 = {
    Text = "Ich bin der Executor des höchsten Gottes, die große Sekte Fee Caraboo – die Inkarnation der Schneeberg-Göttin Umapati, die in die Menschenwelt herabgestiegen ist."
  },
  AvgDialog_145510_Content_2 = {
    Text = "Die Schneegebundenen"
  },
  AvgDialog_145510_Content_20 = {
    Text = "(Das klingt irgendwie etwas anders als das, was im Werbeprospekt stand…)"
  },
  AvgDialog_145510_Content_21 = {
    Text = "Hey, wenn du die Schneeberg-Göttin bist, dann zeig uns doch mal einen Zauber!"
  },
  AvgDialog_145510_Content_22 = {
    Text = "Das Verspotten des Mannes rief vereinzeltes Kichern hervor."
  },
  AvgDialog_145510_Content_23 = {
    Text = "Nein, das kann ich im Moment noch nicht."
  },
  AvgDialog_145510_Content_24 = {
    Text = "Das Mädchen zog gemächlich einen leuchtend roten Apfel hervor und biss hinein."
  },
  AvgDialog_145510_Content_25 = {
    Text = "Denn ich habe sieben Zauberobjekte verloren – sieben Schätze, die mir am Herzen liegen."
  },
  AvgDialog_145510_Content_26 = {
    Text = "Es sind der Goldene Apfel der Eris, der Spiegel von Yata, die Feder der Ma'at, der Schlüssel Salomons, das Auge des Balor..."
  },
  AvgDialog_145510_Content_27 = {
    Text = "Diese Zauberobjekte von dir stammen aus ganz schön vielen und verschiedenen Kulturen!"
  },
  AvgDialog_145510_Content_28 = {
    Text = "Wieder brach schallendes Gelächter aus, doch das Mädchen kümmerte sich nicht darum."
  },
  AvgDialog_145510_Content_29 = {
    Text = "Und dann noch der Faden der Moirai und die Krone der Ariadne."
  },
  AvgDialog_145510_Content_3 = {
    Text = "Die größte Lüge dieser Welt\nkommt aus dem Mund derer, die niemals lügen."
  },
  AvgDialog_145510_Content_30 = {
    Text = "Der Faden der Moirai… der Webstuhl der drei Schicksalsgöttinnen…"
  },
  AvgDialog_145510_Content_31 = {
    Text = "Ist das etwa das, was Arachne meinte – „das Schicksal, das wir empfangen sollen\"?"
  },
  AvgDialog_145510_Content_32 = {
    Text = "Du fingst jenes kleine Knäuel Faden aus dem Innenfutter deiner Tasche heraus; der schimmernde Faden ließ an deinen Fingerspitzen Farben fließen, die das bloße Auge kaum erfassen konnte."
  },
  AvgDialog_145510_Content_33 = {
    Text = "Warte noch einen Moment und handle mit Bedacht."
  },
  AvgDialog_145510_Content_34 = {
    Text = "Das Schicksal hat uns zwar hierher geführt, doch hat es uns nicht verraten, welche Rolle der Besitzer des Handbuchs in dieser Geschichte spielt."
  },
  AvgDialog_145510_Content_35 = {
    Text = "*Hust, hust!*"
  },
  AvgDialog_145510_Content_36 = {
    Text = "Wenn ihr alles verstanden habt, dann lasst hier eure Verehrung zurück!"
  },
  AvgDialog_145510_Content_37 = {
    Text = "Nicht mehr und nicht weniger – solange es fünfzig Rosenskript sind! Damit kann die Schneeberg-Göttin Umapati eure aufrichtige Hingabe spüren!"
  },
  AvgDialog_145510_Content_38 = {
    Text = "Als Schneeberg-Göttin werde ich, nachdem ich die sieben großen Zauberobjekte wieder vereint habe und beim Neumond wiedergeboren bin, eure Gebete tausendfach erwidern!"
  },
  AvgDialog_145510_Content_39 = {
    Text = "Nach all dem wirren Gerede kommt es also darauf hinaus, dass du hier Spenden sammelst!"
  },
  AvgDialog_145510_Content_4 = {
    Text = "–4000 Meter Höhe–"
  },
  AvgDialog_145510_Content_40 = {
    Text = "Seit die Schneeberg-Göttin erschienen ist, sind wenn nicht tausend, dann mindestens achthundert Gruppen zum Bergsteigen aufgebrochen – und jede hat ihre eigene Verpflegung mitgebracht."
  },
  AvgDialog_145510_Content_41 = {
    Text = "Du, der nur ans Schmarotzen denkt, solltest lieber schnell verschwinden und lernen, deine Wünsche mit deinen eigenen fleißigen Händen zu erfüllen!"
  },
  AvgDialog_145510_Content_42 = {
    Text = "Die Schaulustigen zerstreuten sich in alle Richtungen."
  },
  AvgDialog_145510_Content_43 = {
    Text = "Du nutztest die Gelegenheit, dich gegen den Menschenstrom vorzudrängen, und sprach das niedergeschlagene Mädchen an."
  },
  AvgDialog_145510_Content_44 = {
    Text = "Entschuldigung… Darf ich fragen, ob Sie diese Broschüre verschickt haben?"
  },
  AvgDialog_145510_Content_45 = {
    Text = "Du holst die aufwendig gestaltete Broschüre heraus und klopfst auf die Zeile „Der große Anführer, Der Auserwählte der Gottheit, Freund des Götterkönigs“."
  },
  AvgDialog_145510_Content_46 = {
    Text = "Die Augen des Mädchens leuchteten sofort auf."
  },
  AvgDialog_145510_Content_47 = {
    Text = "<Shake:Ohhh! Du hast tatsächlich meine Werbebroschüre bekommen!>"
  },
  AvgDialog_145510_Content_48 = {
    Text = "Also, wo sind deine zwölf Apostel und die anderen Gläubigen?"
  },
  AvgDialog_145510_Content_49 = {
    Text = "Das ist eine lange Geschichte. Meine großartige Sekte wurde von Verrätern hinterhältig ausmanövriert – einer der zwölf Apostel hegte heimlich böse Absichten und wollte den höchsten Ruhm ganz für sich allein."
  },
  AvgDialog_145510_Content_5 = {
    Text = "Wir sind da"
  },
  AvgDialog_145510_Content_50 = {
    Text = "Die anderen Gläubigen wurden durch Intrigen gegeneinander aufgehetzt, bis die Sekte in alle Winde zerstreut war. Nur ich, die Anführerin, bin allein übrig geblieben und habe mich auf eine beschwerliche Reise begeben, um die Sekte wiederaufzubauen."
  },
  AvgDialog_145510_Content_51 = {
    Text = "Wer jetzt nur tausend Rosenskript spendet, kann ehrenvoll den ersten Platz unter den neuen Zwölf Aposteln einnehmen und mein Schüler Nummer eins werden…"
  },
  AvgDialog_145510_Content_52 = {
    Text = "Aber gerade eben, als du auf der Straße deine Künste vorgeführt hast, hast du gesagt, du seiest Umapati, die Göttin des Schneeberges."
  },
  AvgDialog_145510_Content_53 = {
    Text = "Das nennt man wohl: Unterwegs gibt man sich seine Identität selbst, oder?"
  },
  AvgDialog_145510_Content_54 = {
    Text = "Tss, Entdeckt worden."
  },
  AvgDialog_145510_Content_55 = {
    Text = "Das Mädchen sprang auf, verschwand mit ein paar flinken Bewegungen hinter einem Zelt und war nicht mehr zu sehen."
  },
  AvgDialog_145510_Content_56 = {
    Text = "Als du dem Mädchen gerade nachsetzen wolltest, klopfte dir plötzlich jemand auf den Rücken."
  },
  AvgDialog_145510_Content_57 = {
    Text = "Ihr beiden Gäste, seid ihr zum Bergsteigen hier?"
  },
  AvgDialog_145510_Content_58 = {Text = "Hm, wir?"},
  AvgDialog_145510_Content_59 = {
    Text = "Ja, ihr beiden macht einen außergewöhnlichen Eindruck – ihr seid wohl keine Einheimischen, oder?"
  },
  AvgDialog_145510_Content_6 = {
    Text = "Dies ist die letzte Versorgungsstation auf dem Weg zum Mount Everest."
  },
  AvgDialog_145510_Content_60 = {
    Text = "Wer kommt in letzter Zeit schon in dieses öde Land, wenn nicht wegen der Göttin auf dem Gipfel, die angeblich alle Wünsche erfüllt?"
  },
  AvgDialog_145510_Content_61 = {
    Text = "Ihr habt nicht viel Ausrüstung dabei und seht aus, als würdet ihr auf die Vorräte anderer hoffen. Was für ein Zufall, würde ich sagen."
  },
  AvgDialog_145510_Content_62 = {
    Text = "<Yellow:Mein Name ist Naraka. Ich bin ein einheimischer Sherpa-Führer.>"
  },
  AvgDialog_145510_Content_63 = {
    Text = "Die Bergsteigergruppe, der wir angehören, wird von der Green-Stiftung finanziert. Die Vorräte sind bereits bereit – wir warten nur noch auf „die Auserwählten\", um gemeinsam den Gipfel zu erklimmen."
  },
  AvgDialog_145510_Content_64 = {
    Text = "Ein Auserwählter?"
  },
  AvgDialog_145510_Content_65 = {
    Text = "Nun, ich lebe schon seit vielen Jahren am Fuß des Schneebergs. Wer das Zeug hat, den Gipfel zu erklimmen —"
  },
  AvgDialog_145510_Content_66 = {
    Text = "Er deutete auf seine Augen."
  },
  AvgDialog_145510_Content_67 = {
    Text = "Das sehe ich diesen Augen auf den ersten Blick an."
  },
  AvgDialog_145510_Content_68 = {
    Text = "Oh? Erzähl mir mehr davon?"
  },
  AvgDialog_145510_Content_69 = {
    Text = "Zunächst natürlich das richtige Alter, ein kräftiger Körper und eine stabile Geistige Stärke."
  },
  AvgDialog_145510_Content_7 = {
    Text = "Weiter oben ist kein Durchkommen mehr für Fahrzeuge."
  },
  AvgDialog_145510_Content_70 = {
    Text = "Darüber hinaus sind Ausdauer und Entschlossenheit beim Aufstieg noch wichtiger — die Entschlossenheit, keinen letzten Atemzug zu tun, solange man den Gipfel nicht erreicht hat."
  },
  AvgDialog_145510_Content_71 = {
    Text = "Erst am Gipfel den letzten Atemzug tun — klingt, als hättest du nicht vor, uns lebend wieder herunterkommen zu lassen?"
  },
  AvgDialog_145510_Content_72 = {
    Text = "Ach, so darf man das nicht sagen. Wer den Gipfel erreicht und die Schneeberg-Göttin erblickt, dem werden alle Wünsche erfüllt. Und dann — muss man sich um eine Kleinigkeit wie den Abstieg noch sorgen?"
  },
  AvgDialog_145510_Content_73 = {
    Text = "Kommt, begleitet mich zum Bergsteigerlager. Ich garantiere, ihr werdet zufrieden sein."
  },
  AvgDialog_145510_Content_74 = {
    Text = "Du wirfst Wilhelm einen Blick zu und fragst ihn stumm nach seiner Meinung."
  },
  AvgDialog_145510_Content_75 = {
    Text = "Gehen wir. Das Mädchen von vorhin ist auch irgendwo verschwunden."
  },
  AvgDialog_145510_Content_76 = {
    Text = "Wenn wir wirklich den Berg besteigen wollen, sind ein ortskundiger Führer und vollständige Ausrüstung unerlässlich."
  },
  AvgDialog_145510_Content_77 = {
    Text = "Gehen wir, schauen wir uns das Lager an."
  },
  AvgDialog_145510_Content_79 = {
    Text = "Was für ein wunderschöner Gesang…"
  },
  AvgDialog_145510_Content_8 = {
    Text = "Du öffnest die Autotür, und die Luft – durchzogen vom verbrannten Duft des Buttertees, dem strengen Geruch des Viehs und der für das Hochplateau typischen, dünnen und eisigen Kälte – dringt ungeduldig in deine Nase."
  },
  AvgDialog_145510_Content_80 = {
    Text = "Irgendwie vertraut."
  },
  AvgDialog_145510_Content_81 = {
    Text = "Als würde er aus fernen Sternenweiten herabströmen und zugleich aus den unendlichen Tiefen des Aequors sanft emporsteigen."
  },
  AvgDialog_145510_Content_83 = {
    Text = "Der Gesang wehte aus Richtung des Lagers herüber, Faden für Faden, wurde nach und nach klarer, wie Nebel, der sich auflöst und das reine Licht des Vollmonds enthüllt."
  },
  AvgDialog_145510_Content_85 = {
    Text = "Auf einem freien Platz am Rand des Lagers sang ein Mädchen mit kummervollem Gesicht aus voller Kehle."
  },
  AvgDialog_145510_Content_86 = {
    Text = "Alle Vorbeigehenden verlangsamten unwillkürlich ihre Schritte und hielten den Atem an – aus Angst, die wie Mondlicht fließende Stimme zu stören."
  },
  AvgDialog_145510_Content_88 = {
    Text = "Erst als das Lied zu Ende war, kehrte sie aus ihrer eigenen versunkenen Welt zurück und bemerkte dabei eure Anwesenheit."
  },
  AvgDialog_145510_Content_89 = {
    Text = "Gibt es neue Teammitglieder?"
  },
  AvgDialog_145510_Content_9 = {
    Text = "Ein bleigrauer Himmel drückt auf das Ende der Welt herab. Die Gipfel der Schneeberge stehen wie eine Reihe schweigsamer Götter an der Grenze zwischen Abenddämmerung und Wolken."
  },
  AvgDialog_145511_Content_1 = {
    Text = "Irgendetwas stimmt nicht."
  },
  AvgDialog_145511_Content_10 = {
    Text = "Nein, nicht nur der Umhang — hinter ihm erhob sich noch etwas anderes."
  },
  AvgDialog_145511_Content_11 = {
    Text = "Es war ein Flügelpaar."
  },
  AvgDialog_145511_Content_12 = {
    Text = "Ein Paar schwarzer Flügel — ein sattes, tiefes Schwarz, das jedem, der es erblickte, ein Gefühl der Unheilschwere einflößte."
  },
  AvgDialog_145511_Content_13 = {
    Text = "<BigShake:Mit diesem unvergänglichen Leib trotze ich jeder Katastrophe!>"
  },
  AvgDialog_145511_Content_14 = {
    Text = "Castor entfaltete seine Schwingen, und der aufgehäufte Schnee hinter ihm explodierte in einem fast senkrechten, hellen weißen Bogen."
  },
  AvgDialog_145511_Content_15 = {
    Text = "Er springt vom verschneiten Hang ab und überwindet eine Distanz, die er sonst niemals hätte überwinden können—"
  },
  AvgDialog_145511_Content_16 = {
    Text = "Dann warf er sich zwischen den Wendigo und Evelyn."
  },
  AvgDialog_145511_Content_17 = {
    Text = "Seine Flügel breiten sich weit aus und bilden eine gewaltige, pechschwarze Barriere hinter ihm."
  },
  AvgDialog_145511_Content_18 = {
    Text = "Der sich schließende Rachen des Wendigos biss in seinen rechten Flügel — ein ganzes Büschel Federn wurde mit einem Ruck herausgerissen."
  },
  AvgDialog_145511_Content_19 = {
    Text = "<Shake:Ugh!!>"
  },
  AvgDialog_145511_Content_2 = {
    Text = "Am Rande des Blickfelds, in einer Ecke der Herde, hat das größte und magerste Wendigo seit Beginn des Kampfes keinen einzigen Angriff unternommen."
  },
  AvgDialog_145511_Content_20 = {
    Text = "Castor stößt ein unterdrücktes Stöhnen aus, weicht aber nicht zurück."
  },
  AvgDialog_145511_Content_21 = {
    Text = "Verschwende nicht die Gelegenheit, die Castor geschaffen hat — jetzt ist der Moment!"
  },
  AvgDialog_145511_Content_3 = {
    Text = "Es wartete, beobachtete das schwächste Glied der Bergsteigergruppe."
  },
  AvgDialog_145511_Content_4 = {
    Text = "Es umging euch drei und stürzte sich auf Evelyn."
  },
  AvgDialog_145511_Content_5 = {
    Text = "Evelyn——!"
  },
  AvgDialog_145511_Content_6 = {
    Text = "Caraboo war zu weit entfernt — als er diesen Ruf ausstieß, wusste er bereits, dass er zu spät kommen würde."
  },
  AvgDialog_145511_Content_7 = {
    Text = "— Aber jemand anderes kam rechtzeitig."
  },
  AvgDialog_145511_Content_8 = {
    Text = "Castor rannte in vollem Laufen los und löste mit einer Handbewegung die Schnur seines Umhangs."
  },
  AvgDialog_145511_Content_9 = {
    Text = "Der Umhang flatterte hinter ihm im Wind —"
  },
  AvgDialog_145512_Content_1 = {
    Text = "Es ist vorbei, du Verlierer."
  },
  AvgDialog_145512_Content_10 = {
    Text = "Hat dein Meister etwa so etwas gesagt: Mein liebes Schätzchen, du hast so hart gearbeitet, das hier ist deine Belohnung für alles, was du bisher geleistet hast."
  },
  AvgDialog_145512_Content_11 = {
    Text = "Gerade musst du persönlich den Schneegipfel erklimmen, die Gegner zurückdrängen und dir deine Krone zurückholen?"
  },
  AvgDialog_145512_Content_12 = {
    Text = "Leider muss ich dir sagen: <BigShake:DU—WUR—DEST—BE—LO—GEN!!>"
  },
  AvgDialog_145512_Content_13 = {
    Text = "Eine Schachfigur bleibt immer nur eine Schachfigur – und wenn es nötig ist, wird sie zum Opfer."
  },
  AvgDialog_145512_Content_14 = {
    Text = "Wenn der Wert, den du beisteuern kannst, vollständig ausgeschöpft ist, wenn du Unzufriedenheit hegst … dann ist es an der Zeit, deinen Kopf zu opfern."
  },
  AvgDialog_145512_Content_15 = {
    Text = "Als eine der sieben Opfergaben auf dem Altar – hast du noch letzte Worte, die du sagen möchtest?"
  },
  AvgDialog_145512_Content_16 = {
    Text = "Ich hätte … niemandem vertrauen sollen …"
  },
  AvgDialog_145512_Content_17 = {
    Text = "Von Anfang an, dem Wohlwollen jener Dame zu vertrauen … Später … die Sehnsucht nach der Rache der Artgenossen …"
  },
  AvgDialog_145512_Content_18 = {
    Text = "Und nun, von jemandes Versprechen angetrieben …"
  },
  AvgDialog_145512_Content_19 = {
    Text = "Nun gut, die Zeit, die ich dir für letzte Worte gebe, ist bloße Höflichkeit — niemand interessiert sich wirklich für dein erbärmliches, gescheitertes Leben."
  },
  AvgDialog_145512_Content_2 = {
    Text = "Caraboo trat über den am Boden knienden Helot hinweg und hob behutsam den Augapfel vom Zauberkreis auf."
  },
  AvgDialog_145512_Content_20 = {
    Text = "Was man sich nicht selbst verdienen kann, das stiehlt, betrügt oder raubt man eben — was nützt es, nur darauf zu warten, dass andere einem etwas schenken."
  },
  AvgDialog_145512_Content_21 = {
    Text = "Dafür reicht die Zeit jetzt nicht mehr — den Rest der Selbstreflexion kannst du im nächsten Leben fortsetzen."
  },
  AvgDialog_145512_Content_22 = {
    Text = "Caraboo hebt die Hand und wirft leicht, und das Auge versinkt in Helots Körper."
  },
  AvgDialog_145512_Content_23 = {
    Text = "Daraufhin ertönte ein knirschendes, krachendes Geräusch der Einverleibung."
  },
  AvgDialog_145512_Content_24 = {
    Text = "Iss, iss nur."
  },
  AvgDialog_145512_Content_25 = {
    Text = "Helots Körper sackte rasch in sich zusammen und hinterließ einen blutigen Schlammsee."
  },
  AvgDialog_145512_Content_26 = {
    Text = "Genau so ist es – sie werden Dich auffressen, bis kein Knochen mehr übrig bleibt …"
  },
  AvgDialog_145512_Content_27 = {
    Text = "Du erkannst auf Caraboos Gesicht eine Art grausame Befriedigung."
  },
  AvgDialog_145512_Content_28 = {
    Text = "Sieh her – Dein erbärmliches Schicksal ist die Quelle Deiner Dummheit, die Quelle Deines leichtgläubigen Vertrauens in Eine Lüge."
  },
  AvgDialog_145512_Content_29 = {Text = "Caraboo…"},
  AvgDialog_145512_Content_3 = {
    Text = "Auch dein Herzenswunsch wird zu Dünger, der den Schneeberg nährt."
  },
  AvgDialog_145512_Content_30 = {
    Text = "Hm? Was ist los?"
  },
  AvgDialog_145512_Content_31 = {
    Text = "Sie drehte sich um und betrachtete Deinen Gesichtsausdruck."
  },
  AvgDialog_145512_Content_32 = {
    Text = "Sie nahm ihre gewohnte, keck-schmeichelnde Miene an, doch Du erkanntest im Augenwinkel einen Hauch von Arroganz, der ihren versteckten Hass verriet."
  },
  AvgDialog_145512_Content_33 = {
    Text = "Darf ich mir die sechs Ritualgeräte ansehen?"
  },
  AvgDialog_145512_Content_34 = {
    Text = "Natürlich!"
  },
  AvgDialog_145512_Content_35 = {
    Text = "Caraboo trat zur Seite und überließ Dir den Platz direkt vor dem Zauberkreis."
  },
  AvgDialog_145512_Content_36 = {
    Text = "Der Faden der Moirai – ein Geschenk von Arachne."
  },
  AvgDialog_145512_Content_37 = {
    Text = "Der Spiegel von Yata – am Ufer des Eissees gefunden, an dem Tinct umherwanderte."
  },
  AvgDialog_145512_Content_38 = {
    Text = "Die Feder der Ma'at – nach Castors Abgang aus Schnee und Wind herabgeschwebt."
  },
  AvgDialog_145512_Content_39 = {
    Text = "Das Auge des Balor – erstarrt in Helots Blutlache."
  },
  AvgDialog_145512_Content_4 = {
    Text = "Der Augapfel wurde plötzlich grotesk verzerrt, seine blutroten Pupillen weiteten sich in einem blutigen Leuchten."
  },
  AvgDialog_145512_Content_40 = {
    Text = "Der Goldene Apfel, den Caraboo aus irgendeinem Bündel hervorgezogen hatte."
  },
  AvgDialog_145512_Content_41 = {
    Text = "Der Schlüssel Salomons ist in Wirklichkeit der Silberschlüssel, den Du bei Dir trägst."
  },
  AvgDialog_145512_Content_42 = {
    Text = "Und dann noch die Krone der Ariadne, die das letzte Expeditionsteam gefunden hatte…"
  },
  AvgDialog_145512_Content_43 = {
    Text = "Du bist verblüfft."
  },
  AvgDialog_145512_Content_44 = {
    Text = "Krone der Ariadne … Was soll das für eine Krone der Ariadne sein, das ist doch <Yellow:Tulus Krone>!"
  },
  AvgDialog_145512_Content_45 = {
    Text = "Was gibt es da so aufzuregen? Der Goldene Apfel ist doch auch nicht golden, oder?"
  },
  AvgDialog_145512_Content_46 = {
    Text = "Aber warum ist Tulus Krone hier?"
  },
  AvgDialog_145512_Content_47 = {
    Text = "Weil es Sein Zauberwerkzeug ist, Seine Opfergabe, Seine liebste Zutat."
  },
  AvgDialog_145512_Content_48 = {
    Text = "Mit Caraboos letzten Worten beginnt die Erde plötzlich zu Zittern."
  },
  AvgDialog_145512_Content_49 = {
    Text = "Was ist passiert?"
  },
  AvgDialog_145512_Content_5 = {
    Text = "Nein, wie kann das sein…!"
  },
  AvgDialog_145512_Content_50 = {Text = "Er lacht!"},
  AvgDialog_145512_Content_51 = {Text = "… Lacht?"},
  AvgDialog_145512_Content_52 = {
    Text = "Der Gipfel bebt immer wieder, Als ob ein junges Mädchen in der Blüte seiner Jahre über etwas Amüsantes lacht und sich vor Lachen kaum halten kann."
  },
  AvgDialog_145512_Content_53 = {
    Text = "Der Schnee rieselt herab."
  },
  AvgDialog_145512_Content_54 = {
    Text = "Der spitze Gipfel ist kein Berg, sondern ein gewaltiger Wurm, der auf dem Berggipfel thront und einer riesigen Schlange gleicht, die Himmel und Erde zu verschlingen scheint."
  },
  AvgDialog_145512_Content_55 = {
    Text = "Weil die Menschen zu schwach sind, um der Realität ins Auge zu sehen, wählten sie es, einer Lüge zu glauben und ihre Wünsche einer nichtigen Gottheit anzuvertrauen."
  },
  AvgDialog_145512_Content_56 = {
    Text = "Sie dachten nie daran — dass auch eine Gottheit lügen kann. Denn auch Gottheiten haben Wünsche, die sie erfüllen möchten."
  },
  AvgDialog_145512_Content_57 = {
    Text = "Der Wunsch der Gottheit ist es — sie zu fressen."
  },
  AvgDialog_145512_Content_58 = {
    Text = "Krone, Faden, Silberschlüssel, verbotene Frucht, Schwinge, Spiegel, magisches Auge. Sieben Zauberwerkzeuge — Opfergaben, die diese gierigen Menschen mit ihrem LP erschaffen haben."
  },
  AvgDialog_145512_Content_59 = {
    Text = "Alles, was ihr habt, ist nichts weiter als eine sättigende Mahlzeit für Ihn."
  },
  AvgDialog_145512_Content_6 = {
    Text = "Das Auge des Balor – das Dämonenauge eines bösen Gottes. Mächtig genug, alles zu vernichten, was es anblickt, und doch zugleich seine einzige Schwäche."
  },
  AvgDialog_145512_Content_60 = {
    Text = "Jetzt hat Er bekommen, was Er wollte – natürlich sollte Er lachen!"
  },
  AvgDialog_145512_Content_61 = {
    Text = "Jetzt, wo es so weit gekommen ist – wäre es nicht an der Zeit, uns die Wahrheit zu sagen?"
  },
  AvgDialog_145512_Content_62 = {
    Text = "Du bist nicht zufällig auf diese Reise geraten, wie Du es vorgespielt hast."
  },
  AvgDialog_145512_Content_63 = {
    Text = "Vielmehr ist die gesamte Bergsteigergruppe unter Deiner Führung bis hierher gelangt."
  },
  AvgDialog_145512_Content_64 = {
    Text = "Die zufällige Begegnung mit Castor in der Höhle am Anfang, Tincts Entscheidung, den Gletschersee zu betrachten…"
  },
  AvgDialog_145512_Content_65 = {
    Text = "Und dieser Helot, der uns die ganze Zeit gefolgt ist – Du hast in Wirklichkeit alles längst vorausgesehen."
  },
  AvgDialog_145512_Content_66 = {
    Text = "Wer bist Du eigentlich?"
  },
  AvgDialog_145512_Content_7 = {
    Text = "Hat dein Meister es dir nicht gesagt? Dieses Auge verdient es nur dann, „Auge des Balor“ genannt zu werden, wenn es von deinem Blutfest getränkt ist."
  },
  AvgDialog_145512_Content_8 = {
    Text = "Er sagte…"
  },
  AvgDialog_145512_Content_9 = {
    Text = "Pst, lass mich raten."
  },
  AvgDialog_145513_Content_1 = {
    Text = "Pakt der Lügner"
  },
  AvgDialog_145513_Content_10 = {
    Text = "<Yellow:Du hast mein Paket verbrannt, oder>? Ich werde dir deine menschliche Maske vom Gesicht reißen —"
  },
  AvgDialog_145513_Content_11 = {
    Text = "Sie packte Narakas Wangen fest und zerrte sie nach beiden Seiten."
  },
  AvgDialog_145513_Content_12 = {
    Text = "<Shake:WARTE!>"
  },
  AvgDialog_145513_Content_13 = {
    Text = "Rrreiß —"
  },
  AvgDialog_145513_Content_14 = {
    Text = "Die Hülle, die als „Naraka“ bekannt ist, wird sauber in zwei Teile gerissen, wie eine Gummipuppe in den Händen eines mutwilligen Kindes."
  },
  AvgDialog_145513_Content_15 = {
    Text = "Aus dem Riss quoll gluckernd schwarzer Rauch hervor, der den Namen „Chaos“ trug."
  },
  AvgDialog_145513_Content_16 = {
    Text = "Der Rauch wallte auf, wand sich, verdichtete sich, und streckte dann kokett eine Rose heraus."
  },
  AvgDialog_145513_Content_17 = {
    Text = "Wir sehen uns wieder, alter Freund."
  },
  AvgDialog_145513_Content_18 = {
    Text = "Bevor wir uns austauschen, wie wäre es mit einem kleinen Aufwärmspiel, um unseren wutentbrannten kleinen Schwindler zu besänftigen?"
  },
  AvgDialog_145513_Content_2 = {
    Text = "Am Ende des Fadens trat das Mädchen aus dem Dunkel hervor."
  },
  AvgDialog_145513_Content_3 = {
    Text = "Na, kleiner Schwindler — hast du dich selbst auch mit hineingezogen?"
  },
  AvgDialog_145513_Content_4 = {
    Text = "Narakas Worte schärfen nur noch den Zorn eines Mädchens, das bereits frustriert den Kopf hängen ließ."
  },
  AvgDialog_145513_Content_5 = {
    Text = "Du hast es leicht."
  },
  AvgDialog_145513_Content_6 = {
    Text = "Caraboo hob den Kopf und starrte Naraka mit wuterfüllten Augen an."
  },
  AvgDialog_145513_Content_7 = {
    Text = "Hör auf zu schauspielern. Ein Sherpa-Bergführer, vom Berg verschluckt, und trotzdem noch in der Stimmung für Witze?"
  },
  AvgDialog_145513_Content_8 = {
    Text = "Schon beim ersten Mal, als ich dich sah, wusste ich — du bist auch ein Betrüger."
  },
  AvgDialog_145513_Content_9 = {
    Text = "Caraboo stürzte sich auf sie. Diesmal ließ sie Naraka nicht entkommen."
  },
  AvgDialog_145514_Content_1 = {
    Text = "Der letzte Wendigo löste sich in Castors Schatten auf."
  },
  AvgDialog_145514_Content_10 = {
    Text = "Vielleicht beginnen Beziehungen zwischen Menschen damit, ein kleines Geheimnis preiszugeben, oder?"
  },
  AvgDialog_145514_Content_11 = {
    Text = "Irgendwann hatte sich Caraboo herangeschlichen und sagte lächelnd genau das, was du dir gedacht hattest."
  },
  AvgDialog_145514_Content_12 = {
    Text = "Geheimnisse auszutauschen ist keine einseitige Angelegenheit."
  },
  AvgDialog_145514_Content_13 = {
    Text = "Diese Tante Rosa, die du so oft gerufen hast – ist das jemand Besonderes für dich?"
  },
  AvgDialog_145514_Content_14 = {
    Text = "Das habe ich natürlich erfunden. Du hast das doch nicht wirklich geglaubt, oder?"
  },
  AvgDialog_145514_Content_15 = {
    Text = "Hehe, einen Dummkopf zu täuschen ist keine Kunst, aber dich zu täuschen ist gar nicht so einfach."
  },
  AvgDialog_145514_Content_16 = {
    Text = "Die Wendigos davon zu überzeugen, dass du verhext wurdest, war weitaus schwieriger, als dich zu täuschen."
  },
  AvgDialog_145514_Content_17 = {
    Text = "Sie können die Stimme in deinem Inneren hören und sie dann durch den Wind wiedergeben."
  },
  AvgDialog_145514_Content_18 = {
    Text = "Wer weiß das schon? Vielleicht hat die Schneeberggöttin so viele Geschichten in sich, dass jede davon wie die Wahrheit klingt?"
  },
  AvgDialog_145514_Content_19 = {
    Text = "Caraboo glitt mit einem schelmischen Spruch leichtfüßig darüber hinweg."
  },
  AvgDialog_145514_Content_2 = {
    Text = "Dann wurde der Wind, der an den Ohren vorbeistrich, plötzlich klar und still. Im Wind waren keine Geräusche mehr zu hören."
  },
  AvgDialog_145514_Content_20 = {
    Text = "Da du nicht darüber reden möchtest, werden wir dich natürlich auch nicht dazu drängen."
  },
  AvgDialog_145514_Content_21 = {
    Text = "Aber Aufrichtigkeit ist etwas sehr Wertvolles – selbst wenn du ein Betrüger bist, solltest du die Erwartungen der anderen besser nicht enttäuschen."
  },
  AvgDialog_145514_Content_22 = {
    Text = "Das ist mein aufrichtiger Rat, ob du ihn befolgst, liegt bei dir."
  },
  AvgDialog_145514_Content_23 = {
    Text = "Wilhelm sagte das und eilte an die Spitze der Gruppe."
  },
  AvgDialog_145514_Content_24 = {Text = "Hmph."},
  AvgDialog_145514_Content_25 = {
    Text = "Wohltäter, Ihr wärt doch nicht so gefühllos wie er, oder?"
  },
  AvgDialog_145514_Content_26 = {
    Text = "Ich habe viel Zeit damit verbracht, mit Wilhelm zusammenzuarbeiten. Er ist kein Mann, der unnötige Worte verliert."
  },
  AvgDialog_145514_Content_27 = {
    Text = "Soweit ich mich erinnere, war jeder Rat, den er je gegeben hat, wirksam."
  },
  AvgDialog_145514_Content_28 = {
    Text = "<Shake:Waaaah, Wohltäter, es stellt sich heraus, dass Ihr genauso grausam seid...>"
  },
  AvgDialog_145514_Content_29 = {
    Text = "Caraboo tat so, als wäre sie traurig, und ging davon, während du Wilhelm einholtest, der gerade mit Naraka plauderte."
  },
  AvgDialog_145514_Content_3 = {
    Text = "Stille bedeutete Sicherheit, doch diese Sicherheit hinterließ ein Gefühl der Leere."
  },
  AvgDialog_145514_Content_30 = {
    Text = "Er bedeutete dir mit einem Blick, ein paar Schritte zur Seite zu treten, bis die anderen euer Flüstern nicht mehr hören konnten."
  },
  AvgDialog_145514_Content_31 = {
    Text = "Der Kampf gegen den Wendigo gerade eben — hast du etwas Seltsames bemerkt?"
  },
  AvgDialog_145514_Content_32 = {Text = "Wo?"},
  AvgDialog_145514_Content_33 = {Text = "Naraka."},
  AvgDialog_145514_Content_34 = {
    Text = "Denk mal zurück — von dem Moment, als jene Stimmen im Wind erklangen, bis der Wendigo auftauchte, bis zur Einkreisung gerade eben —"
  },
  AvgDialog_145514_Content_35 = {
    Text = "Naraka, ist sie in irgendeinem Augenblick einem einzigen Wendigo nahegekommen?"
  },
  AvgDialog_145514_Content_36 = {
    Text = "Caraboo wurde beim Spielen der Betrogenen von einem Wendigo angefallen, Evelyn wurde von dem größten Wendigo umgeworfen, Castor wurde eine Feder abgebissen…"
  },
  AvgDialog_145514_Content_37 = {
    Text = "Auch beim letzten Mal, als Naraka vom Wendigo verführt wurde, schien sie keinerlei Auswirkungen zu spüren."
  },
  AvgDialog_145514_Content_38 = {
    Text = "Meinst du...?"
  },
  AvgDialog_145514_Content_39 = {
    Text = "Ich meine nichts damit."
  },
  AvgDialog_145514_Content_4 = {
    Text = "Evelyn warf einen Blick auf Castors Flügel, doch ihr Gesichtsausdruck blieb unverändert, als ob es das Natürlichste der Welt wäre, dass jeder Mensch ein Paar Flügel verbirgt."
  },
  AvgDialog_145514_Content_40 = {
    Text = "Noch vier bis fünf Tage bergauf — wir haben keinen anderen Führer, den wir austauschen könnten."
  },
  AvgDialog_145514_Content_41 = {
    Text = "Ich hoffe, ich mache mir zu viele Sorgen, aber wir müssen wachsam bleiben."
  },
  AvgDialog_145514_Content_42 = {
    Text = "Auf diesem Weg haben wir schon verloren einen Tinct. Ich möchte nicht, dass durch meine Nachlässigkeit noch jemand auf diesem Berg zurückbleibt."
  },
  AvgDialog_145514_Content_43 = {
    Text = "Der Wind kam vom äußeren Rand des Felsrückens herüber."
  },
  AvgDialog_145514_Content_44 = {
    Text = "Er umging die in der Ferne kauernde Gestalt, die auf das Eis einhackte."
  },
  AvgDialog_145514_Content_45 = {
    Text = "Narakas Pickelhauenspitze traf auf die Eisreste an der Schuhsohle und erzeugte dabei ein gleichmäßiges, pendelartig rhythmisches Geräusch."
  },
  AvgDialog_145514_Content_46 = {
    Text = "-Höhe 6.500 m-"
  },
  AvgDialog_145514_Content_5 = {
    Text = "Ich verbinde dich."
  },
  AvgDialog_145514_Content_6 = {
    Text = "Entschuldigung … dass ich das so lange verborgen habe."
  },
  AvgDialog_145514_Content_7 = {
    Text = "Kein Problem. Wir sind alle hier, um ein übernatürliches Wunder auf dem Niveau der Totenauferstehung zu finden … In einer solchen Situation eine Existenz zu entdecken, die den gesunden Menschenverstand bricht, ist doch eher eine gute Nachricht."
  },
  AvgDialog_145514_Content_8 = {
    Text = "Außerdem weiß doch jeder, dass du ein Geheimnis hast, wenn du deinen Umhang nicht einmal zum Schlafen ablegst."
  },
  AvgDialog_145514_Content_9 = {
    Text = "Obwohl die Worte einen leichten Vorwurf enthielten, spürtest du deutlich, dass alle nach diesem Kampf begannen, ihre Mauern niederzureißen und sich näherzukommen."
  },
  AvgDialog_145515_Content_1 = {
    Text = "Sieben Schicksalsfäden"
  },
  AvgDialog_145515_Content_10 = {
    Text = "<Shake:Schaut dort drüben — !>"
  },
  AvgDialog_145515_Content_11 = {
    Text = "Noch bevor sie ausgesprochen hatte, lief sie bereits zum sanften Hang auf der anderen Seite."
  },
  AvgDialog_145515_Content_12 = {
    Text = "Es war ein sechseckiger Altar."
  },
  AvgDialog_145515_Content_13 = {
    Text = "In der Mitte des Altars war bereits eine Krone platziert worden."
  },
  AvgDialog_145515_Content_14 = {
    Text = "Die in Ketten gehüllte Frau zählte die erbeuteten Schätze. %player% Der Silberschlüssel und der Faden in der Tasche, der Spiegel, die Schwarze Feder und der goldene Apfel in Caraboos Bündel."
  },
  AvgDialog_145515_Content_15 = {
    Text = "Der Augapfel von Balor?"
  },
  AvgDialog_145515_Content_16 = {
    Text = "Helot stieß ein verächtliches Lachen aus und bohrte daraufhin ihre spitzen Fingernägel in die Kugelkette an ihrer Seite."
  },
  AvgDialog_145515_Content_17 = {
    Text = "Mit einem feuchten Geräusch gab die Kugelkette einen klebrigen, seltsamen Laut von sich."
  },
  AvgDialog_145515_Content_18 = {
    Text = "Sie rührte und wühlte darin … bis sie schließlich einen blutigen Augapfel herausgrub."
  },
  AvgDialog_145515_Content_19 = {
    Text = "Alles gehört dir, du gefräßiges Wesen."
  },
  AvgDialog_145515_Content_2 = {
    Text = "–8800 Meter Höhe–"
  },
  AvgDialog_145515_Content_20 = {
    Text = "Sie platzierte die sechs Kostbarkeiten jeweils in einer Ecke des Altars."
  },
  AvgDialog_145515_Content_21 = {
    Text = "Nun ist es an der Zeit, meinen Wunsch zu erfüllen."
  },
  AvgDialog_145515_Content_22 = {
    Text = "Sie schloss die Augen und verharrte in Stille."
  },
  AvgDialog_145515_Content_23 = {
    Text = "Lass sie wiederauferstehen … lass mich meinen Feind mit eigenen Händen töten und meine längst überfällige Rache vollenden."
  },
  AvgDialog_145515_Content_24 = {
    Text = "Ein eisiger Wind fegte über die Gipfel Die Schneegebundenen. Ihr Wunsch blieb ohne jede Antwort."
  },
  AvgDialog_145515_Content_25 = {
    Text = "Warum? Habe ich dir nicht bereits die sieben Verehrungen übergeben?"
  },
  AvgDialog_145515_Content_26 = {
    Text = "Helots Forderung hallte zwischen den fernen Gipfeln nach und löste eine Lawine nach der anderen aus."
  },
  AvgDialog_145515_Content_27 = {
    Text = "Weil eines der Opfergaben gefälscht ist, oder?"
  },
  AvgDialog_145515_Content_28 = {Text = "Wer?!"},
  AvgDialog_145515_Content_29 = {
    Text = "Caraboo hüpfte leichtfüßig nach vorne, als ob sie Helot überhaupt nicht ernst nähme."
  },
  AvgDialog_145515_Content_3 = {
    Text = "Dies ist ein Ort, den menschliche Fußspuren noch nie betreten haben."
  },
  AvgDialog_145515_Content_30 = {
    Text = "Ihr denkt immer nur an eure eigenen Wünsche, habt euch aber nie gefragt, was die Gottheit wirklich als Opfergabe begehrt."
  },
  AvgDialog_145515_Content_31 = {
    Text = "Der Goldene Apfel, der Goldene Apfel – du glaubst doch nicht etwa, dass jeder goldene Apfel die richtige Wahl ist, oder?"
  },
  AvgDialog_145515_Content_32 = {
    Text = "Sie nahm den Goldenen Apfel vom Altar und biss sanft hinein."
  },
  AvgDialog_145515_Content_33 = {
    Text = "Hmm, wie erwartet bist du es."
  },
  AvgDialog_145515_Content_34 = {
    Text = "Die goldene Folie löste sich daraufhin ab und enthüllte das wahre Innere."
  },
  AvgDialog_145515_Content_35 = {
    Text = "Snack, Süßigkeit, Kakaomasse – wie auch immer man es nennen mag, es ist jedenfalls die gewöhnlichste aller gewöhnlichen Schokoladen."
  },
  AvgDialog_145515_Content_36 = {
    Text = "<BigShake:Tadaa! Der Segen der Fee, ein unvergleichlicher Genuss!>"
  },
  AvgDialog_145515_Content_37 = {
    Text = "Du… Betrüger…"
  },
  AvgDialog_145515_Content_38 = {
    Text = "Ein Räuber ist auch nicht besser als ein Betrüger, oder?"
  },
  AvgDialog_145515_Content_39 = {
    Text = "Spar dir die Worte und gib den echten Goldenen Apfel heraus!"
  },
  AvgDialog_145515_Content_4 = {
    Text = "Auf dem Gipfel des Schneebergs stehend, die weißen Gipfel in der Ferne betrachtend, hallte in der Brust nicht das Gefühl der Errungenschaften des Gipfelsturms wider."
  },
  AvgDialog_145515_Content_40 = {
    Text = "Das musst du sie schon selbst fragen, ob sie einverstanden sind."
  },
  AvgDialog_145515_Content_41 = {
    Text = "Caraboo trat zur Seite – die Bergsteigergruppe kletterte gerade über den letzten Felsvorsprung."
  },
  AvgDialog_145515_Content_5 = {
    Text = "Sondern Angst."
  },
  AvgDialog_145515_Content_6 = {
    Text = "Die Angst vor der Ferne von der Menschenwelt, die Angst vor der Trennung von allem Vertrauten."
  },
  AvgDialog_145515_Content_7 = {
    Text = "Hier gibt es keinen höheren Gipfel mehr in der Ferne – wer den Gipfel erklommen hat, kann nur noch den Himmel anbeten."
  },
  AvgDialog_145515_Content_8 = {
    Text = "Meine Damen und Herren, wir haben den Gipfel erreicht."
  },
  AvgDialog_145515_Content_9 = {
    Text = "In der Bergsteigergruppe gab es nur eine Person, die vom Anblick des Gipfels nicht im Geringsten beeindruckt war."
  },
  AvgDialog_145516_Content_1 = {
    Text = "Der Vorläufer"
  },
  AvgDialog_145516_Content_10 = {
    Text = "Es fehlen also noch der <Blue:Schlüssel Salomons> und das <Blue:Auge des Balor>."
  },
  AvgDialog_145516_Content_11 = {
    Text = "Caraboo zählt an ihren Fingern ab und murmelt vor sich hin."
  },
  AvgDialog_145516_Content_12 = {
    Text = "Glaubst du, das Auge des Balor fällt vielleicht auch wie die Feder der Ma'at einfach so vom Himmel?"
  },
  AvgDialog_145516_Content_13 = {
    Text = "Dieser Witz ist überhaupt nicht lustig."
  },
  AvgDialog_145516_Content_14 = {
    Text = "Du weißt nicht, was mit Castor passiert ist, aber auf dieser pechschwarzen Feder haftet noch sein Atem."
  },
  AvgDialog_145516_Content_15 = {
    Text = "Es ist nicht mehr weit."
  },
  AvgDialog_145516_Content_16 = {
    Text = "Bevor wir den Gipfel erreichen, dürfen wir nicht umkehren."
  },
  AvgDialog_145516_Content_17 = {
    Text = "Wilhelm klopfte dir auf die Schulter. Offensichtlich wusste er, was du dachtest."
  },
  AvgDialog_145516_Content_18 = {
    Text = "Weißt du was? Ich habe so ein Gefühl."
  },
  AvgDialog_145516_Content_19 = {
    Text = "Castor hat bestimmt etwas gefunden, dem er nachstreben wollte, und hat deshalb die Gruppe verlassen."
  },
  AvgDialog_145516_Content_2 = {
    Text = "Dies ist der letzte Rastplatz vor dem Gipfelsturm."
  },
  AvgDialog_145516_Content_20 = {
    Text = "Und wenn es jemand schafft, seinen Wunsch zu erfüllen, dann er."
  },
  AvgDialog_145516_Content_21 = {
    Text = "Evelyn räusperte sich leicht, als wolle sie ihren Worten mehr Gewicht verleihen, und fügte hinzu:"
  },
  AvgDialog_145516_Content_22 = {
    Text = "Solange man lange genug lebt, kann man schon aus kurzen Begegnungen in das Schicksal anderer spähen."
  },
  AvgDialog_145516_Content_23 = {
    Text = "Was hast du in Castor gesehen?"
  },
  AvgDialog_145516_Content_24 = {
    Text = "Schlichtheit und Beharrlichkeit."
  },
  AvgDialog_145516_Content_25 = {
    Text = "Bis er die eine Antwort gefunden hat, wird er nicht ruhen.\nKein Zögern, kein Aufgeben."
  },
  AvgDialog_145516_Content_26 = {
    Text = "Und du, Evelyn? Wo liegt Deine Antwort?"
  },
  AvgDialog_145516_Content_27 = {
    Text = "Oben auf dem Berg."
  },
  AvgDialog_145516_Content_28 = {
    Text = "Wie passend, wir nehmen denselben Weg!"
  },
  AvgDialog_145516_Content_29 = {
    Text = "Caraboo zog von irgendwoher wieder einen Apfel hervor, warf ihn in die Luft und fing ihn wieder auf."
  },
  AvgDialog_145516_Content_3 = {
    Text = "Der Blick zurück auf die fernen Berge zeigt euch zu Füßen ein weites Meer aus Eis und Schnee, das sich im Nebel der Engpässe im fernen Horizont verliert."
  },
  AvgDialog_145516_Content_30 = {
    Text = "Wenn alle bereit sind, dann machen wir uns auf den letzten Abschnitt."
  },
  AvgDialog_145516_Content_31 = {
    Text = "Nicht nachlassen. Viele Zwischenfälle passieren auf den letzten tausend Metern."
  },
  AvgDialog_145516_Content_32 = {
    Text = "Vor euch erhebt sich eine nahezu senkrechte Eiswand."
  },
  AvgDialog_145516_Content_33 = {
    Text = "#N/ANaraka schwingt die Eispickel, treibt die Spitze schräg in den harten Schnee mit einem dumpfen Aufprall, verlagert dann sein Gewicht nach oben, wobei seine Frontzacken präzise in das kleine Loch treten, das die Spitze hinterlassen hat."
  },
  AvgDialog_145516_Content_34 = {
    Text = "Seltsam, es scheint, als wäre hier kürzlich jemand gewesen."
  },
  AvgDialog_145516_Content_35 = {
    Text = "Schaut, hier sind einige Löcher, die ein wenig aussehen, als wären sie von einer Eisaxt gemacht worden."
  },
  AvgDialog_145516_Content_36 = {
    Text = "Könnten die von der letzten Expeditionsgruppe stammen?"
  },
  AvgDialog_145516_Content_37 = {
    Text = "Unwahrscheinlich. Es ist schon zu viel Zeit vergangen – die damaligen Spuren wären längst wieder eingefroren."
  },
  AvgDialog_145516_Content_38 = {
    Text = "Egal, ich denke nicht weiter darüber nach. Dass jemand hier entlanggegangen ist, ist eine gute Sache – es bedeutet, dass dieser Weg begehbar ist."
  },
  AvgDialog_145516_Content_39 = {
    Text = "Er nahm einen Eisschrauben vom Gurt, drehte sie in die Eisschicht und erzeugte dabei ein unangenehmes „Knirschen\"."
  },
  AvgDialog_145516_Content_4 = {
    Text = "Der großartige Anblick lässt auch euch, die ihr eigentlich schon etwas erschöpft seid, ein wenig Erleichterung spüren."
  },
  AvgDialog_145516_Content_40 = {
    Text = "Bis der Kegel vollständig versunken war, hängte Naraka einen Karabiner daran, führte das Hauptseil hindurch und drehte den Verschluss bis zum Anschlag zu."
  },
  AvgDialog_145516_Content_41 = {
    Text = "Erster Sicherungspunkt."
  },
  AvgDialog_145516_Content_42 = {
    Text = "Alle klinken ihre Steigklemmen ins Hauptseil ein. Nutzt die Steigeisen an euren Bergschuhen, um in die von mir gehauenen Löcher zu greifen, und bewegt euch langsam vorwärts."
  },
  AvgDialog_145516_Content_43 = {
    Text = "Du suchst mit dem Eispickel über deinem Kopf einen soliden Ansatzpunkt, schlägst die Spitze fest ein, hebst dann den rechten Fuß und trittst kräftig mit den Frontzacken ins Eis, damit die beiden Stahlzähne Halt finden."
  },
  AvgDialog_145516_Content_44 = {
    Text = "Verlagere das Gewicht auf die Füße, klammer dich nicht an die Eiswand."
  },
  AvgDialog_145516_Content_45 = {
    Text = "Du atmest tief die dünne, schmerzende Luft ein, drückst deinen Körper leicht von der Eiswand weg und lässt die Steigeisen das Gewicht tragen. Der linke Fuß folgt nach, wieder ein kräftiger Tritt."
  },
  AvgDialog_145516_Content_46 = {
    Text = "Die Steigklemme gleitet mit dir langsam aufwärts und rattert bei jedem kleinen Vorschub einmal leer."
  },
  AvgDialog_145516_Content_47 = {
    Text = "Auf halbem Weg bist du bereits schweißgebadet, und die zuvor konzentrierte Aufmerksamkeit beginnt unweigerlich nachzulassen."
  },
  AvgDialog_145516_Content_48 = {
    Text = "Reiß dich zusammen – dieser Abschnitt verträgt keinerlei Zwischenfälle."
  },
  AvgDialog_145516_Content_49 = {
    Text = "Genau in dem Moment, als seine Worte verklangen, geschah das Unerwartete."
  },
  AvgDialog_145516_Content_5 = {
    Text = "<Shake:W-warte kurz.>"
  },
  AvgDialog_145516_Content_50 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_145516_Content_51 = {
    Text = "Ein roter Lichtschimmer blitzte aus der Dunkelheit auf, Wilhelm zuckte mit der Nasenspitze —"
  },
  AvgDialog_145516_Content_52 = {
    Text = "<BigShake:Runter —!>"
  },
  AvgDialog_145516_Content_53 = {
    Text = "Noch bevor seine Worte verklungen waren, stürzte er sich auf dich und drückte dich mit seinem ganzen Körper nieder – nur das Sicherungsseil hielt sie beide, während sie gegen die Eiswand stießen."
  },
  AvgDialog_145516_Content_54 = {
    Text = "Ein feiner Blutfaden zeichnete sich auf seiner Wange ab."
  },
  AvgDialog_145516_Content_55 = {
    Text = "Tss, ziemlich schnelle Reaktion."
  },
  AvgDialog_145516_Content_56 = {
    Text = "Aus der Tiefe der Dunkelheit erklang das Schleifen schwerer Ketten auf dem Boden – ein dumpfes, langgezogenes Reiben von Metall auf dem Untergrund."
  },
  AvgDialog_145516_Content_57 = {
    Text = "Ach, du bist es – der Kerl, der uns den ganzen Weg verfolgt hat."
  },
  AvgDialog_145516_Content_58 = {
    Text = "Den ganzen Weg verfolgt?"
  },
  AvgDialog_145516_Content_59 = {
    Text = "Ja, als wir Castor begegnet sind, habe ich euch bereits gewarnt, dass uns jemand folgt."
  },
  AvgDialog_145516_Content_6 = {
    Text = "Evelyn atmet schwer. Der niedrige Luftdruck in großer Höhe hat offensichtlich erhebliche Auswirkungen auf ihren Körper."
  },
  AvgDialog_145516_Content_60 = {
    Text = "Nur weiß ich nicht, wann sie uns überholt hat."
  },
  AvgDialog_145516_Content_61 = {
    Text = "Kein Wunder, dass mir diese Ausstrahlung so vertraut vorkam."
  },
  AvgDialog_145516_Content_62 = {
    Text = "Ich erinnere mich an deinen Namen —"
  },
  AvgDialog_145516_Content_63 = {
    Text = "Umso besser, dann erübrigt sich die Vorstellung."
  },
  AvgDialog_145516_Content_64 = {
    Text = "An der Grenze zwischen Licht und Schatten trat langsam eine Gestalt hervor."
  },
  AvgDialog_145516_Content_65 = {
    Text = "Beide Handgelenke waren abgetrennt, hinter ihr schleifte sie zwei schwere Kugelketten, auf denen ein Paar riesiger blutroter Augen die Welt grimmig anstarrte."
  },
  AvgDialog_145516_Content_66 = {
    Text = "… Helot: Kette."
  },
  AvgDialog_145516_Content_67 = {
    Text = "In der letzten Welt war sie die letzte Person, die ich gesehen habe."
  },
  AvgDialog_145516_Content_68 = {
    Text = "Anders gesagt — sie ist diejenige, die mich getötet hat."
  },
  AvgDialog_145516_Content_69 = {
    Text = "Damals gehorchte sie Herbert, gehorchte sie der Bildhauer-Gilde."
  },
  AvgDialog_145516_Content_7 = {
    Text = "Hinter ihr hingegen bewegt sich das zierliche Mädchen mit leichten Schritten."
  },
  AvgDialog_145516_Content_70 = {
    Text = "Und jetzt? <Yellow:Wer> hat dich geschickt?"
  },
  AvgDialog_145516_Content_71 = {
    Text = "Nur ein Hund macht sich Gedanken darüber, wer sein Herr ist."
  },
  AvgDialog_145516_Content_72 = {
    Text = "Ich habe nur eines zu tun — euch für immer hier begraben."
  },
  AvgDialog_145516_Content_73 = {
    Text = "Unzählige Eiterbeulen tauchen aus dem Boden auf und umzingeln euch."
  },
  AvgDialog_145516_Content_8 = {
    Text = "Wir haben jetzt den <Blue:Spiegel von Yata> und die <Blue:Feder der Ma'at>. Die <Blue:Krone der Ariadne> sollte auf dem Gipfel sein."
  },
  AvgDialog_145516_Content_9 = {
    Text = "Was den <Blue:Faden der Moirai> betrifft… Hehe, manche von euch wollen es mir nicht sagen, aber ich weiß, wo er ist. Und einen <Blue:Goldenen Apfel> bekomme ich hin."
  },
  AvgDialog_145517_Content_1 = {
    Text = "Heute verlassen die Vögel"
  },
  AvgDialog_145517_Content_10 = {
    Text = "Kommt heraus – ihr seid mir doch den ganzen Weg gefolgt, nicht wahr?"
  },
  AvgDialog_145517_Content_11 = {
    Text = "Ich bin bereits allein, und die Entfernung reicht nicht aus, um um Hilfe zu rufen."
  },
  AvgDialog_145517_Content_12 = {
    Text = "<Shake:Lasst uns... einander... gegenübertreten...>"
  },
  AvgDialog_145517_Content_13 = {
    Text = "Die Person, die aus dem Wald trat, schien aus seinem Traum herausgetreten zu sein."
  },
  AvgDialog_145517_Content_14 = {
    Text = "<Shake:Nein … du bist …>"
  },
  AvgDialog_145517_Content_15 = {
    Text = "Die aufrechte, vornehme Gestalt wirkte noch schlanker als beim Abschied."
  },
  AvgDialog_145517_Content_16 = {
    Text = "Mein Name ist Pollux. Im Auftrag des Kirchenführers bin ich gekommen, um den Flüchtling Castor zu verfolgen."
  },
  AvgDialog_145517_Content_17 = {
    Text = "Der Inhalt war nicht mehr wichtig – seine Stimme hallte in Castors Ohren wider, wie Gemurmel in einem Traum."
  },
  AvgDialog_145517_Content_18 = {
    Text = "<SmallShake:Ein Wendigo?>"
  },
  AvgDialog_145517_Content_19 = {
    Text = "Nein, kein Wendigo. Selbst die schönste Fantasie könnte keine wahre Beschaffenheit vortäuschen."
  },
  AvgDialog_145517_Content_2 = {
    Text = "Der Junge raste durch den Schnee."
  },
  AvgDialog_145517_Content_20 = {
    Text = "Sünder … Castor … Das heilige Licht wird deine Vergehen offenbaren."
  },
  AvgDialog_145517_Content_21 = {
    Text = "Wahr, rau, eiskalt, grausam, erschütternd."
  },
  AvgDialog_145517_Content_22 = {Text = "Pollux…"},
  AvgDialog_145517_Content_23 = {
    Text = "Der bohrende Schmerz, der ihm ans Herz stieg."
  },
  AvgDialog_145517_Content_24 = {
    Text = "Wie lange kann man noch ausweichen? Wie lange noch?"
  },
  AvgDialog_145517_Content_25 = {
    Text = "Castor schritt durch den Schnee, Schritt für Schritt auf Pollux zu."
  },
  AvgDialog_145517_Content_26 = {
    Text = "<Red:<Shake:Kniet vor der Latern nieder, und ich werde euch von euren Sünden freisprechen und euch eine Wiedergeburt in neuer Gestalt auf dem sündlosen heiligen Land gewähren!>"
  },
  AvgDialog_145517_Content_27 = {
    Text = "Castor gehorchte nicht. Er schritt nur weiter auf Pollux zu."
  },
  AvgDialog_145517_Content_28 = {
    Text = "Selbst wenn es ein Wendigo wäre, spielte das keine Rolle. Er schritt einfach voran."
  },
  AvgDialog_145517_Content_29 = {
    Text = "Pollux hob das Messer. Ein vertrautes Messer. Bei der letzten Verfolgung hatte es Castors Brust durchstochen."
  },
  AvgDialog_145517_Content_3 = {
    Text = "Nichts konnte ihn mehr aufhalten."
  },
  AvgDialog_145517_Content_30 = {
    Text = "<Big:Noch einen Schritt, und das heilige Licht wird euch niederstrecken!>"
  },
  AvgDialog_145517_Content_4 = {
    Text = "Der Weg hinunter … leicht wie ein Flug im Wind."
  },
  AvgDialog_145517_Content_5 = {
    Text = "Ein Weg ohne die Last einer Lüge ließ auch sein Herz leicht und schwebend aufsteigen."
  },
  AvgDialog_145517_Content_6 = {
    Text = "Es tut mir leid, ich hätte euch nicht täuschen sollen."
  },
  AvgDialog_145517_Content_7 = {
    Text = "Zum Glück ist es jetzt noch nicht zu spät."
  },
  AvgDialog_145517_Content_8 = {
    Text = "Jedes Mal, wenn er kurz innehielt, drang aus dem Wald hinter ihm ein Geräusch hervor, das dem Fallen von Schnee ähnelte."
  },
  AvgDialog_145517_Content_9 = {
    Text = "Es waren jäh gestoppte Schritte."
  },
  AvgDialog_145518_Content_1 = {
    Text = "Der ungefrorene Mond"
  },
  AvgDialog_145518_Content_10 = {
    Text = "Du stimmst bereitwillig zu."
  },
  AvgDialog_145518_Content_100 = {
    Text = "Ach, ein hinterhältiger Betrüger, der stets in der reinsten Opferrolle erscheint…"
  },
  AvgDialog_145518_Content_101 = {
    Text = "Sie summte ein Liedchen und eilte wieder an die Spitze der Gruppe."
  },
  AvgDialog_145518_Content_102 = {
    Text = "Was meinte sie damit?"
  },
  AvgDialog_145518_Content_103 = {
    Text = "Ich habe es auch nicht verstanden."
  },
  AvgDialog_145518_Content_104 = {
    Text = "Hey~, kommt schon, bleibt nicht zurück~"
  },
  AvgDialog_145518_Content_105 = {
    Text = "Die beiden, die keinen rechten Reim darauf machen konnten, setzten sich einfach in Bewegung."
  },
  AvgDialog_145518_Content_106 = {
    Text = "–Höhe 6000 m–"
  },
  AvgDialog_145518_Content_11 = {
    Text = "Ich weiß, das ist schwer zu glauben, aber ich komme von einem Stern, der sehr, sehr weit entfernt ist. Ich bin so lange umhergedriftet, dass ich mich nur noch daran erinnern kann, dass wir ihn in seinen letzten Tagen <Blue:den Verlassenen Stern> nannten."
  },
  AvgDialog_145518_Content_12 = {
    Text = "Ich habe eine Zeit durchlebt, die so lang ist, dass sie sich nicht mehr zählen lässt, bevor ich hierher gelangte."
  },
  AvgDialog_145518_Content_13 = {
    Text = "Ich vertraue dir."
  },
  AvgDialog_145518_Content_14 = {
    Text = "Was ich sagen möchte, ist … der Verlassene Stern ist so unendlich weit entfernt, dass es selbst Schwierig ist, ihn sich vorzustellen oder zu beschreiben."
  },
  AvgDialog_145518_Content_15 = {
    Text = "Aber gerade eben habe ich im Wasser des Sees … meine Schwester Faint gesehen."
  },
  AvgDialog_145518_Content_16 = {
    Text = "Tinct beißt sich auf die Lippe."
  },
  AvgDialog_145518_Content_17 = {
    Text = "Nein, eigentlich auch nicht … Gerade habe ich nur eine Art Vorzeichen gespürt, und der Schatten im See stammt ebenfalls vom Verlassenen Stern …"
  },
  AvgDialog_145518_Content_18 = {
    Text = "Ich weiß, es ist unmöglich, aber ich habe das Gefühl... <Shake:es war keine Halluzination...>"
  },
  AvgDialog_145518_Content_19 = {
    Text = "Du siehst sehr erschöpft aus."
  },
  AvgDialog_145518_Content_2 = {
    Text = "Wind und Schnee haben irgendwann aufgehört, und zwischen Himmel und Erde bleibt nur eine Stille, so weit und leer, dass sie einen erschaudern lässt. Über euch erstreckt sich ein tiefes Blau ohne eine einzige Wolke, und selbst die fernen Schneegipfel zeichnen sich in jedem Detail klar ab."
  },
  AvgDialog_145518_Content_20 = {
    Text = "Evelyns Gesicht zeigte einen besorgten Ausdruck."
  },
  AvgDialog_145518_Content_21 = {
    Text = "Wenn du dich müde fühlst, solltest du rechtzeitig Ruhe nehmen."
  },
  AvgDialog_145518_Content_22 = {
    Text = "Wir sind erst seit Kurzem aufgebrochen, und allein den Berg hinabzusteigen wäre nicht besonders gefährlich."
  },
  AvgDialog_145518_Content_23 = {
    Text = "<Yellow:<Big:Nein...! Ich bin nicht müde! ICH GEHE NICHT!>>"
  },
  AvgDialog_145518_Content_24 = {
    Text = "Zur Überraschung aller schrie Tinct wie aus einem Reflex heraus auf."
  },
  AvgDialog_145518_Content_25 = {
    Text = "Als Tinct bemerkte, dass alle Blicke auf sie gerichtet waren, versuchte sie, sich zu fassen, doch ihr heftig auf und ab gehender Brustkorb verriet ihre wahren Gefühle."
  },
  AvgDialog_145518_Content_26 = {
    Text = "Entschuldigung… ich habe mich gehen lassen. Danke für deine Sorge, aber <Yellow:ich bin nicht müde.>"
  },
  AvgDialog_145518_Content_27 = {
    Text = "Lügen bringt nichts."
  },
  AvgDialog_145518_Content_28 = {
    Text = "Ich halte durch. Ich werde nicht zurückbleiben."
  },
  AvgDialog_145518_Content_29 = {
    Text = "Tinct presste erneut die Lippen zusammen, warf einen Blick zurück auf den Eissee und machte sich auf den Weg."
  },
  AvgDialog_145518_Content_3 = {
    Text = "Unter dem wolkenlosen Himmel gehst du bis ans Ufer eines zugefrorenen Sees."
  },
  AvgDialog_145518_Content_30 = {
    Text = "Auf der zugefrorenen Seeoberfläche spiegelte sich Nur ihr verschwommener Schatten wider."
  },
  AvgDialog_145518_Content_31 = {
    Text = "Ihr marschiertet einen halben Tag lang und fandet ein ebenes Stück Land zum Aufschlagen des Lagers. Naraka wies alle Bergsteiger an, Schnee zu sammeln und ihn mit dem Hochgebirgskocher zu Wasser zu kochen."
  },
  AvgDialog_145518_Content_32 = {
    Text = "Als ihr mit dem gesammelten Schnee zurückkehrtet, entdecktet ihr jedoch dicke Rauchschwaden neben dem Lager."
  },
  AvgDialog_145518_Content_33 = {
    Text = "Hey, wessen Gepäck brennt da drüben!"
  },
  AvgDialog_145518_Content_34 = {
    Text = "Hm...? Nein!!!"
  },
  AvgDialog_145518_Content_35 = {
    Text = "Flammen leckten an dem kleinen Stoffbeutel, den Caraboo stets wie einen Schatz gehütet hatte."
  },
  AvgDialog_145518_Content_36 = {
    Text = "Warte, dieser Beutel voller Goldmünzen in deiner Tasche?"
  },
  AvgDialog_145518_Content_37 = {
    Text = "Unter der Hitze der Flammen sanken die Goldmünzen weich in sich zusammen."
  },
  AvgDialog_145518_Content_38 = {
    Text = "Nein! Kein Problem! Ich rette sie schon!"
  },
  AvgDialog_145518_Content_39 = {
    Text = "Nein, lass mich nachsehen!"
  },
  AvgDialog_145518_Content_4 = {
    Text = "Tinct starrt gedankenverloren auf das Wasser des Sees."
  },
  AvgDialog_145518_Content_40 = {
    Text = "Beim Zerreißen rollten alle halb geschmolzenen Goldmünzen auf den Boden."
  },
  AvgDialog_145518_Content_41 = {
    Text = "Eine davon rollte zu Wilhelms Füßen, er bückte sich und hob sie auf."
  },
  AvgDialog_145518_Content_42 = {
    Text = "<Blue:Debauve & Gallais, Pistoles de Marie Schokolade...>"
  },
  AvgDialog_145518_Content_43 = {
    Text = "Schokolade?!"
  },
  AvgDialog_145518_Content_44 = {
    Text = "<Shake:Ha, haha…> Das hier… auch wenn es nur Schokolade ist, ist es trotzdem sehr teuer!"
  },
  AvgDialog_145518_Content_45 = {
    Text = "Hör auf mit dem Unsinn! Wenn du das Führergeld nicht aufbringen kannst, dann verschwinde aus der Gruppe!"
  },
  AvgDialog_145518_Content_46 = {
    Text = "<Shake:Nein, bitte, ich kenne den Weg nicht alleine…>"
  },
  AvgDialog_145518_Content_47 = {
    Text = "<Shake:Wenn du mich aus der Gruppe wirfst, werde ich auf dem Abstieg sicher sterben!>"
  },
  AvgDialog_145518_Content_48 = {
    Text = "Scher dich zum Teufel! Was nützt es jetzt, hier herumzujammern? Wer andere betrügt, muss damit rechnen, entlarvt zu werden!"
  },
  AvgDialog_145518_Content_49 = {
    Text = "Als Naraka weder auf gute noch auf schlechte Worte reagierte, blickte Caraboo sich um und warf sich dann, als hätte sie einen Rettungsanker gefunden, mit einem dumpfen Plumps auf die Knie und klammerte sich fest an deine Beine."
  },
  AvgDialog_145518_Content_5 = {
    Text = "Ist da etwas im See?"
  },
  AvgDialog_145518_Content_50 = {
    Text = "<Shake:Ich bitte dich, guter Mensch – du kannst ein junges Mädchen doch nicht allein und verlassen den Berg hinuntersteigen lassen, oder?>"
  },
  AvgDialog_145518_Content_51 = {
    Text = "<Shake:Wuhuhu, es ist immer so, ich werde immer verlassen, egal wohin ich gehe, alle verachten mich als jemanden, der nichts besitzt…>"
  },
  AvgDialog_145518_Content_52 = {
    Text = "<Shake:Guter Mensch, gütiger Mensch, du bist bestimmt anders als die anderen, du wirst mir helfen, stimmt's?>"
  },
  AvgDialog_145518_Content_53 = {
    Text = "Sie hob den Kopf und starrte dich mit tränengefüllten Augen an."
  },
  AvgDialog_145518_Content_54 = {
    Text = "…Na gut. Ihr Führergeld – ich zahle es dir nach dem Abstieg."
  },
  AvgDialog_145518_Content_55 = {
    Text = "Ihrem Blick nicht standhalten könnend, stimmtest du zu."
  },
  AvgDialog_145518_Content_56 = {
    Text = "<Big:Danke, vielen herzlichen Dank, mein Wohltäter!!> Du bist der größte und prächtigste Retter, den Caraboo je gekannt hat!!"
  },
  AvgDialog_145518_Content_57 = {
    Text = "Caraboo wischte sofort ihre Tränen weg und sprang lachend auf."
  },
  AvgDialog_145518_Content_58 = {
    Text = "Wohltäter, sobald ich meine Macht als Berggöttin zurückerlangt habe, werde ich deine Güte tausendfach vergelten!"
  },
  AvgDialog_145518_Content_59 = {
    Text = "Dann werde ich nicht nur dreißig Goldmünzen zahlen, sondern dreihundert, dreitausend – kein Problem!"
  },
  AvgDialog_145518_Content_6 = {
    Text = "Nein, nein, nichts, gar nichts…"
  },
  AvgDialog_145518_Content_60 = {
    Text = "Natürlich, natürlich."
  },
  AvgDialog_145518_Content_61 = {
    Text = "Du winkst ab."
  },
  AvgDialog_145518_Content_62 = {
    Text = "Schließlich müssen alle gemeinsam den Berg besteigen. Solange diese Sache schnell vorübergeht, ist alles gut."
  },
  AvgDialog_145518_Content_63 = {
    Text = "Die Lage beruhigt sich schließlich, und alle gehen wieder ihren eigenen Beschäftigungen nach oder ruhen sich aus."
  },
  AvgDialog_145518_Content_64 = {
    Text = "Wilhelm zieht dich beiseite und flüstert dir zu."
  },
  AvgDialog_145518_Content_65 = {
    Text = "Seltsam – ich erinnere mich, dass Caraboos Tasche vorher nicht an dieser Stelle war."
  },
  AvgDialog_145518_Content_66 = {
    Text = "<Red:Wer hat es ans Lagerfeuer gestellt?>"
  },
  AvgDialog_145518_Content_67 = {
    Text = "Das Wasser kocht. Trinkt alle etwas, um euch aufzuwärmen."
  },
  AvgDialog_145518_Content_68 = {
    Text = "Gibt es Knoblauchsuppe?"
  },
  AvgDialog_145518_Content_69 = {
    Text = "Fragst du mich? So etwas haben wir nicht. Begnüg dich mit heißem Wasser."
  },
  AvgDialog_145518_Content_7 = {
    Text = "Tinct kommt wie aus einem Traum zu sich, sie wirkt, als wolle sie etwas sagen, hält sich aber zurück."
  },
  AvgDialog_145518_Content_70 = {
    Text = "Hmph, nichts da … Du bist angeblich der beste Sherpa-Führer, aber so viel taugst du auch nicht – und dabei verlangst du so hohe Führergebühren."
  },
  AvgDialog_145518_Content_71 = {
    Text = "Als die Stimmung erneut zu eskalieren drohte, mischte sich Evelyn eilig ein."
  },
  AvgDialog_145518_Content_72 = {
    Text = "Wenn du etwas Warmes trinken möchtest, habe ich hier etwas heiße Schokolade."
  },
  AvgDialog_145518_Content_73 = {
    Text = "Und du, Kleiner – hast du nicht genug Proviant dabei? Ich habe bemerkt, dass du kaum etwas gegessen hast."
  },
  AvgDialog_145518_Content_74 = {
    Text = "Ich? Kein Problem, während unserer Klausur essen wir auch nur einmal am Tag."
  },
  AvgDialog_145518_Content_75 = {
    Text = "Beim Bergsteigen kann man es sich aber nicht leisten, nicht genug Energie aufzunehmen."
  },
  AvgDialog_145518_Content_76 = {
    Text = "Mein Mann hat beim Bergsteigen früher auch immer die leichtesten Rucksäcke bevorzugt, genau wie du."
  },
  AvgDialog_145518_Content_77 = {
    Text = "Seit er einmal mehrere Tage in einem Schneesturm festsaß, wählt er stets die sicherere Strategie."
  },
  AvgDialog_145518_Content_78 = {
    Text = "Ihr Mann … ist er auch Bergsteiger?"
  },
  AvgDialog_145518_Content_79 = {
    Text = "Nun, er ist ein sehr talentierter Bergsteiger, der zuvor auch den Everest und den K2 angegangen ist."
  },
  AvgDialog_145518_Content_8 = {
    Text = "Nach einer Weile wendet sie sich dir zu und sagt leise."
  },
  AvgDialog_145518_Content_80 = {
    Text = "Und was dann?"
  },
  AvgDialog_145518_Content_81 = {Text = "Und dann?"},
  AvgDialog_145518_Content_82 = {
    Text = "Dein Mann – hat er das Bergsteigen aufgegeben?"
  },
  AvgDialog_145518_Content_83 = {
    Text = "<Shake:Hm? Warum ziehst du mich?>"
  },
  AvgDialog_145518_Content_84 = {
    Text = "Alle folgten seinen Worten und blickten zur Seite – Caraboo lächelte freundlich, doch ihre Hand zog unauffällig an Castors Ärmel."
  },
  AvgDialog_145518_Content_85 = {
    Text = "Als ihre Aktion entdeckt wurde, zog sie etwas verlegen die Hand zurück und murmelte leise."
  },
  AvgDialog_145518_Content_86 = {
    Text = "<Small:Trottel>."
  },
  AvgDialog_145518_Content_87 = {
    Text = "Es ist nichts …"
  },
  AvgDialog_145518_Content_88 = {
    Text = "Mein Mann … er verschwand beim letzten Aufstieg zum Gipfel des Everest. Niemand weiß, wohin er gegangen ist. Auch seine Leiche wurde nicht gefunden."
  },
  AvgDialog_145518_Content_89 = {
    Text = "Früher begleitete ich ihn immer, wartete aber nur in der Nähe von Lager C2."
  },
  AvgDialog_145518_Content_9 = {
    Text = "Entschuldigung, ich weiß nicht warum, aber Euch gegenüber habe ich stets ein sehr vertrautes Gefühl. Darf ich Euch daher bitten, mir zuzuhören?"
  },
  AvgDialog_145518_Content_90 = {
    Text = "Jetzt, da er fort ist, möchte ich die Landschaft sehen, die er gesehen hat …"
  },
  AvgDialog_145518_Content_91 = {
    Text = "Evelyn blickte in die Ferne auf den Bergrücken. Der ewige Schnee schwieg und antwortete nur mit dem Heulen des Windes."
  },
  AvgDialog_145518_Content_92 = {
    Text = "Dieses Mal werden wir den Gipfel auf jeden Fall erreichen."
  },
  AvgDialog_145518_Content_93 = {
    Text = "Das glaube ich fest."
  },
  AvgDialog_145518_Content_94 = {
    Text = "Kurz nach dem Gespräch hatte Caraboo ihre lockere Art wiedergefunden und schlenderte mit hinter dem Rücken verschränkten Händen umher."
  },
  AvgDialog_145518_Content_95 = {
    Text = "Sie rückte geheimnisvoll nah an Castor heran."
  },
  AvgDialog_145518_Content_96 = {
    Text = "Hey, Trottel, hast du das Gefühl, dass uns jemand folgt?"
  },
  AvgDialog_145518_Content_97 = {
    Text = "Eigentlich nicht. Den ganzen Weg über war ich auf der Hut vor der Verfolgung durch die Kirche der Lichtträger. Aber ihr seid die ersten Menschen, denen ich begegnet bin …"
  },
  AvgDialog_145518_Content_98 = {
    Text = "Ich spüre es auch nicht."
  },
  AvgDialog_145518_Content_99 = {
    Text = "Wirklich? Dann war es wohl nur meine Einbildung."
  },
  AvgDialog_145519_Content_1 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_145519_Content_10 = {
    Text = "Der Spiegel von Yata gilt zusammen mit dem Schwert Kusanagi und dem Juwel Yasakani no Magatama in der japanischen Mythologie als die drei Kaiserlichen Schätze. In gängigen Abbildungen besteht der Spiegel von Yata aus Metall, mit Yamato-Mustern auf der Rückseite."
  },
  AvgDialog_145519_Content_11 = {
    Text = "Aber schau Dir diesen Spiegel an…"
  },
  AvgDialog_145519_Content_12 = {
    Text = "Die Spiegelfläche ist hauchdünn, eben und makellos glatt, die Form vollkommen rund – wie ein heller Mond, der hoch am Himmel hängt."
  },
  AvgDialog_145519_Content_13 = {
    Text = "Unter der kalten Glasoberfläche scheinen sich ganz leise irgendwelche leuchtenden Partikel zu bewegen."
  },
  AvgDialog_145519_Content_14 = {
    Text = "Wie auch immer, lass ihn uns erst einmal herausnehmen und ansehen."
  },
  AvgDialog_145519_Content_15 = {
    Text = "Naraka hob einen Eispickel und durchbrach mühelos die Eisschicht, um den Spiegel herauszuholen."
  },
  AvgDialog_145519_Content_16 = {
    Text = "Caraboo schoss vor, riss ihn an sich und verstaute ihn blitzschnell in ihrem Rucksack."
  },
  AvgDialog_145519_Content_17 = {
    Text = "<Shake:Was soll das! Was glotzt ihr, schaut mich nicht an!>"
  },
  AvgDialog_145519_Content_18 = {
    Text = "Das ist von Anfang an der Schatz der Schneeberg-Göttin – natürlich gehört er mir, wenn ich ihn gefunden habe!"
  },
  AvgDialog_145519_Content_19 = {
    Text = "Niemand versuchte, ihr den Besitz streitig zu machen."
  },
  AvgDialog_145519_Content_2 = {
    Text = "Ihr wandert am Gletschersee entlang. Die Seeoberfläche gleicht einem Spiegel — makellos und klar, die weite Umgebung liegt offen da, doch von Tinct keine Spur."
  },
  AvgDialog_145519_Content_20 = {
    Text = "Verglichen mit einem Spiegel, der völlig unscheinbar wirkte, war Tincts Verschwinden offensichtlich weit beunruhigender."
  },
  AvgDialog_145519_Content_21 = {
    Text = "Doch niemand sprach mehr darüber. Nur sein Schatten lastete unvermeidlich, schwer wie Blei, auf jedem Herzen."
  },
  AvgDialog_145519_Content_3 = {
    Text = "Im Nachhall des Winds zwischen den Schneegipfeln scheint sich Als ob Tincts Gesang und leises Schluchzen zu mischen — kaum wahrnehmbar, kaum zu unterscheiden, ob es der Wind oder ein Trugbild ist."
  },
  AvgDialog_145519_Content_4 = {
    Text = "Tinct … wird sie nicht mehr zurückkommen?"
  },
  AvgDialog_145519_Content_5 = {
    Text = "Niemand widersprach."
  },
  AvgDialog_145519_Content_6 = {
    Text = "Seltsam, war das gestern schon hier?"
  },
  AvgDialog_145519_Content_7 = {
    Text = "Auf der Oberfläche des Eissees, eingeschlossen im klaren, festen Eis, liegt still ein vollkommen runder Spiegel."
  },
  AvgDialog_145519_Content_8 = {
    Text = "<Shake:Der Spiegel von Yata! Das ist der Spiegel von Yata, der der Berggöttin dargebracht werden muss!>"
  },
  AvgDialog_145519_Content_9 = {
    Text = "Wilhelm, Du siehst aus, als wolltest Du etwas sagen, hältst Dich aber zurück."
  },
  AvgDialog_145520_Content_1 = {
    Text = "Siebter Reisender"
  },
  AvgDialog_145520_Content_10 = {
    Text = "In diesen Tagen sind keine anderen Bergsteigergruppen unterwegs, ihr könnt euch hier in Ruhe erholen, niemand wird euch stören —"
  },
  AvgDialog_145520_Content_100 = {
    Text = "Vorsicht! Irgendetwas taucht auf!"
  },
  AvgDialog_145520_Content_11 = {
    Text = "Noch bevor Naraka ausgesprochen hatte, war aus einer Ecke der Höhle plötzlich ein Rascheln und Knistern zu hören."
  },
  AvgDialog_145520_Content_12 = {
    Text = "… Oh, ist da jemand?"
  },
  AvgDialog_145520_Content_13 = {
    Text = "Wilhelms fragende Stimme hallte durch die Höhle, doch niemand antwortete."
  },
  AvgDialog_145520_Content_14 = {
    Text = "Wir gehören zu einer Bergsteigergruppe und suchen hier Schutz vor Wind und Schnee. Wir meinen es nicht böse."
  },
  AvgDialog_145520_Content_15 = {
    Text = "Du sendest freundliche Signale aus und gehst mit der Laterne hinter die Felsen."
  },
  AvgDialog_145520_Content_16 = {Text = "Vorsicht!"},
  AvgDialog_145520_Content_17 = {
    Text = "Die Gestalt hinter den Felsen spannte sich plötzlich an. Noch bevor die anderen erklären konnten, kam ein heftiger Angriff aus der Dunkelheit."
  },
  AvgDialog_145520_Content_19 = {
    Text = "Vielleicht weil er gegen mehrere kämpfte, startete der Angreifer einen Hinterhalt und verschwand im nächsten Moment wieder im Schatten. Doch in dem kurzen Kampf hattest du die Gestalt bereits erkannt."
  },
  AvgDialog_145520_Content_2 = {
    Text = "Nachdem Naraka euch eine Weile geführt hat, tut sich ein schwarzer Spalt im Bergmassiv auf."
  },
  AvgDialog_145520_Content_20 = {
    Text = "<Shake:Castor?!>"
  },
  AvgDialog_145520_Content_21 = {
    Text = "Nach einer Weile tauchte ein schwarzer Umhang aus dem Schatten auf, und dahinter lugte ein halb sichtbares Gesicht mit wachsamem Ausdruck hervor."
  },
  AvgDialog_145520_Content_22 = {
    Text = "… Du kennst mich?"
  },
  AvgDialog_145520_Content_23 = {
    Text = "Nein, das ist eine sehr lange Geschichte…"
  },
  AvgDialog_145520_Content_24 = {
    Text = "Also, warum bist du hier allein?"
  },
  AvgDialog_145520_Content_25 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_145520_Content_26 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_145520_Content_27 = {
    Text = "Nun, mein Bruder — Pollux und ich haben vereinbart, die Kirche der Lichtträger nacheinander auf unterschiedliche Weise zu verlassen. Aber ich wartete einen Monat lang an unserem vereinbarten Treffpunkt, und er erschien nicht."
  },
  AvgDialog_145520_Content_28 = {
    Text = "Ich denke, mein Weggang hat dazu geführt, dass Frau Juliette die Bewachung verstärkt hat. Seitdem suche ich nach einem Weg, ihn zu befreien."
  },
  AvgDialog_145520_Content_29 = {
    Text = "<Yellow:Zum Glück konnte ich mich erfolgreich verstecken und ihrer Verfolgung entkommen.>"
  },
  AvgDialog_145520_Content_3 = {
    Text = "Lass uns hinein gehen."
  },
  AvgDialog_145520_Content_30 = {
    Text = "Schließlich hörte ich, dass es auf dem Gipfel des Schneeberges eine Gottheit gibt, die jeden Wunsch erfüllen kann."
  },
  AvgDialog_145520_Content_31 = {
    Text = "Aber ich kann keiner Bergsteigergruppe beitreten … Die Spitzel der Kirche sind überall, und wenn ich mich zu oft zeige, werde ich zu leicht entdeckt."
  },
  AvgDialog_145520_Content_32 = {Text = "Dummkopf."},
  AvgDialog_145520_Content_33 = {Text = "Ah … ?"},
  AvgDialog_145520_Content_34 = {
    Text = "Ich habe noch nie jemanden so Dummes gesehen wie dich."
  },
  AvgDialog_145520_Content_35 = {
    Text = "Selbst wenn du alleine den Berg erklimmst — wo willst du die sieben Zauberobjekte finden?"
  },
  AvgDialog_145520_Content_36 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_145520_Content_37 = {
    Text = "Daran habe ich wohl nicht gedacht …"
  },
  AvgDialog_145520_Content_38 = {
    Text = "Siehst du! Jetzt brauchst du die Hilfe der Schneeberg-Göttin."
  },
  AvgDialog_145520_Content_39 = {
    Text = "Komm schon, Solange du dich dem Heiligen Orden anschließt, verspreche ich dir, nach dem erfolgreichen Erreichen des Gipfels, dir und deinem Bruder bei eurer Trennung zu helfen!"
  },
  AvgDialog_145520_Content_4 = {
    Text = "Ihr stützt euch gegenseitig, während ihr das zerklüftete Gestein hinabklettert, und du blickst zurück in Richtung des Höhleneingangs."
  },
  AvgDialog_145520_Content_40 = {Text = "Wirklich?"},
  AvgDialog_145520_Content_41 = {
    Text = "Natürlich ist es wahr! Wahrer geht es nicht!"
  },
  AvgDialog_145520_Content_42 = {
    Text = "Aber um deine Aufrichtigkeit gegenüber dem Heiligen Orden zu beweisen, musst du alle Schätze, die du bei dir trägst, der Heiligen zur Aufbewahrung übergeben."
  },
  AvgDialog_145520_Content_43 = {
    Text = "...In Ordnung."
  },
  AvgDialog_145520_Content_44 = {
    Text = "Castor zögerte lange und zog schließlich ein paar Münzen und ein abgegriffenes, zerschlissenes Märchenbuch hervor."
  },
  AvgDialog_145520_Content_45 = {
    Text = "Das ist alles, was ich habe. Darf ich trotzdem beitreten?"
  },
  AvgDialog_145520_Content_46 = {
    Text = "Wilhelm tippte dir auf den Arm."
  },
  AvgDialog_145520_Content_47 = {
    Text = "Hast du genug zugeschaut?"
  },
  AvgDialog_145520_Content_48 = {
    Text = "Ähem, also, Castor, willkommen in unserem Expeditionsteam."
  },
  AvgDialog_145520_Content_49 = {
    Text = "Caraboo hat nur Spaß gemacht. Solange du deine eigene Ausrüstung mitbringst, musst du nichts zusätzlich abgeben."
  },
  AvgDialog_145520_Content_5 = {
    Text = "Der Spalt ist schmal und gleichmäßig, wie ein halb geöffnetes schmales Auge, das Wind und Schnee draußen hält."
  },
  AvgDialog_145520_Content_50 = {
    Text = "Hmph, selbst die Schneeberg-Göttin würde diese armseligen Opfergaben verschmähen – behalt sie lieber selbst."
  },
  AvgDialog_145520_Content_51 = {
    Text = "Castor glättete sorgfältig die Falten des Märchenbuchs und barg es dann behutsam wieder an seiner Brust."
  },
  AvgDialog_145520_Content_52 = {
    Text = "Dann warf er einen kurzen Blick auf die paar Münzen, sein Blick wanderte zwischen euch hin und her."
  },
  AvgDialog_145520_Content_53 = {
    Text = "Wenn sie niemand haben möchte, nehme ich sie dankend an."
  },
  AvgDialog_145520_Content_54 = {
    Text = "Naraka machte eine Handbewegung, und der Steintisch war im Nu leer."
  },
  AvgDialog_145520_Content_55 = {
    Text = "Das Führerhonorar dieses jungen Herrn ist wirklich viel günstiger als das der anderen."
  },
  AvgDialog_145520_Content_56 = {
    Text = "Wenn ich mich richtig erinnere, haben wir dein Führerhonorar bereits bezahlt."
  },
  AvgDialog_145520_Content_57 = {
    Text = "Falls wirklich noch eine zusätzliche Gebühr fällig ist, übernehme ich sie für ihn."
  },
  AvgDialog_145520_Content_58 = {
    Text = "Das ist nicht nötig, wir kennen uns doch gar nicht – ich kann Ihnen keine Umstände bereiten..."
  },
  AvgDialog_145520_Content_59 = {
    Text = "Evelyns ausgestreckte Hand unterbrach Castors Worte; dieser zögerte einen halben Moment, dann ergriff er ihre Hand und drückte sie."
  },
  AvgDialog_145520_Content_6 = {
    Text = "Hier innen… ist es so warm…"
  },
  AvgDialog_145520_Content_60 = {
    Text = "Evelyn, ich heiße Evelyn und bin Archäologin."
  },
  AvgDialog_145520_Content_61 = {
    Text = "Jetzt sind wir keine Fremden mehr, oder?"
  },
  AvgDialog_145520_Content_62 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_145520_Content_63 = {
    Text = "Der Schneesturm hält euch alle in der engen Höhle fest. Da noch kein Feuer brennt, ist das Gespräch eure einzige Waffe gegen die Kälte."
  },
  AvgDialog_145520_Content_64 = {
    Text = "Du hast gerade gesagt, du suchst deinen Zwillingsbruder – stimmt das?"
  },
  AvgDialog_145520_Content_65 = {Text = "Gut."},
  AvgDialog_145520_Content_66 = {
    Text = "Castor nickte bedächtig."
  },
  AvgDialog_145520_Content_67 = {
    Text = "Was für ein Zufall – ich suche ebenfalls meine Zwillingsschwester."
  },
  AvgDialog_145520_Content_68 = {
    Text = "Faint und ich sind sehr unterschiedliche Menschen. Meine Schwester ist zwar kränklich, aber eigentlich eine mutige und starke Person."
  },
  AvgDialog_145520_Content_69 = {
    Text = "Als die Zwillingsschwester erwähnt wurde, schien auch Tinct, die sonst stets in Gedanken versunken war, wieder aufzuleben und lächelte leise."
  },
  AvgDialog_145520_Content_7 = {
    Text = "Puh, puh, wie kann ich als Schneeberg-Göttin nicht wissen, dass es im Berg so einen Ort gibt?"
  },
  AvgDialog_145520_Content_70 = {
    Text = "Und jenes Pollux? Was für ein Mensch ist er?"
  },
  AvgDialog_145520_Content_71 = {
    Text = "<Shake:Pollux…>"
  },
  AvgDialog_145520_Content_72 = {
    Text = "Er ist auch ganz anders als ich. Er ist klug, scharf und hat ein starkes Gespür – von klein auf haben der Meister und die Lehrer ihn immer mehr gemocht…"
  },
  AvgDialog_145520_Content_73 = {
    Text = "Mach dir keine Sorgen. Du hast auch deine Stärken. Zum Beispiel – hast du nicht gerade gesagt, dass du der Verfolgung der Kirche entkommen bist? Das ist doch auch beeindruckend."
  },
  AvgDialog_145520_Content_74 = {
    Text = "Castor errötete leicht, räusperte sich und lenkte das Gespräch wieder auf Tinct."
  },
  AvgDialog_145520_Content_75 = {
    Text = "Warum bist du und deine Schwester getrennt worden?"
  },
  AvgDialog_145520_Content_76 = {
    Text = "In dem Moment, als wir flohen, überließ sie mir das letzte Ticket."
  },
  AvgDialog_145520_Content_77 = {
    Text = "Ihre Stimme war sehr leise, als ob die Erinnerung bei der kleinsten Anstrengung vom Wind und Schnee fortgeweht würde."
  },
  AvgDialog_145520_Content_78 = {
    Text = "Ich hoffe, dass wir am Ende alle wieder mit ihnen zusammentreffen können."
  },
  AvgDialog_145520_Content_79 = {
    Text = "Castor schwieg einen Moment, sein Blick glitt über sie hinweg und fiel auf den tosenden weißen Sturm vor dem Höhleneingang."
  },
  AvgDialog_145520_Content_8 = {
    Text = "Na klar, das Führergeld der Sherpa wird nicht umsonst verlangt."
  },
  AvgDialog_145520_Content_80 = {
    Text = "Während sie plauderten, verging die Zeit Minute für Minute."
  },
  AvgDialog_145520_Content_81 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_145520_Content_82 = {
    Text = "In der siebten Stunde erreicht der Sturm einen fast boshaften Höhepunkt."
  },
  AvgDialog_145520_Content_83 = {
    Text = "Es sieht so aus, als würden wir heute Nacht in der Höhle übernachten müssen."
  },
  AvgDialog_145520_Content_84 = {
    Text = "Naraka schob die bereits feuchten Überreste auf der freien Fläche in der Mitte der Höhle beiseite und versuchte, mit trockenem Holz ein neues Lagerfeuer zu entfachen."
  },
  AvgDialog_145520_Content_85 = {
    Text = "Aus der Dunkelheit in der Tiefe der Höhle drang ein feines, raschelndes Geräusch – als würde etwas mit seinen Fingernägeln über die Steinwand kratzen."
  },
  AvgDialog_145520_Content_86 = {
    Text = "Gibt es Mäuse?"
  },
  AvgDialog_145520_Content_87 = {
    Text = "In dieser Höhe sollte es keine Mäuse geben…"
  },
  AvgDialog_145520_Content_88 = {
    Text = "Das Geräusch hörte plötzlich auf. Die Stille in der Höhle ließ das Herz stocken."
  },
  AvgDialog_145520_Content_89 = {
    Text = "Aus der Dunkelheit, die so dicht war, dass kein einziger Lichtstrahl hindurchdrang, wehte eine Bosheit ins Gesicht."
  },
  AvgDialog_145520_Content_9 = {
    Text = "Die Alten sagen, dieser Spalt ist nach einem Lawinenabgang plötzlich aufgetaucht."
  },
  AvgDialog_145520_Content_90 = {
    Text = "Naraka hob die Fackel und leuchtete dem Geräusch folgend in die Tiefe der Höhle. Das Fackellicht drang nur wenige Schritte weit vor, bevor es von der Dunkelheit davor verschluckt wurde."
  },
  AvgDialog_145520_Content_91 = {
    Text = "Geh nicht hin."
  },
  AvgDialog_145520_Content_92 = {
    Text = "Ich schaue nur kurz nach."
  },
  AvgDialog_145520_Content_93 = {
    Text = "Naraka stützte sich an der Felswand ab und lehnte sich vorsichtig vor."
  },
  AvgDialog_145520_Content_94 = {
    Text = "Das flackernde Feuerlicht fiel über den Felsvorsprung zu seinen Füßen und beleuchtete einen pechschwarzen Tümpel in der Tiefe. Die Wasseroberfläche war so glatt, dass keine einzige Welle zu sehen war, und führte sich fast mit der Umgebung der Schatten zusammen."
  },
  AvgDialog_145520_Content_95 = {
    Text = "Unten ist Wasser. <Shake:Scheint sehr tief zu sein —>"
  },
  AvgDialog_145520_Content_96 = {
    Text = "Noch bevor die Worte verklungen sind, senkt sich die pechschwarze „Wasseroberfläche“ plötzlich nach unten."
  },
  AvgDialog_145520_Content_97 = {
    Text = "Naraka verlor das Gleichgewicht, und sein halber Fuß war bereits in die sich plötzlich vergrößernde Lücke gerutscht."
  },
  AvgDialog_145520_Content_98 = {
    Text = "<Shake:Halt mich fest —!>"
  },
  AvgDialog_145520_Content_99 = {
    Text = "Du griffst blitzschnell nach seinem Kragen und rissest ihn nach hinten zu Boden."
  },
  AvgDialog_145521_Content_1 = {
    Text = "Am Lagerfeuer nach Einbruch der Dunkelheit"
  },
  AvgDialog_145521_Content_10 = {
    Text = "In einer Ecke stapelten sich einige vermoderte Holzkisten, und tiefer an der Felswand war ein Stück zerbrochener Eisenkette eingehämmert."
  },
  AvgDialog_145521_Content_100 = {
    Text = "Er schloss die Augen und spürte die Konturen, die unter seinen Fingerspitzen vorbeizogen."
  },
  AvgDialog_145521_Content_101 = {
    Text = "<Small:<Italic:...„Der Bösewicht sprach einen Zauber und verwandelte seinen kleinen Bruder in eine Krähe.“>>"
  },
  AvgDialog_145521_Content_102 = {
    Text = "<Small:<Italic:...„Aber der ältere Bruder kannte die Farbe seiner Flügel.“>>"
  },
  AvgDialog_145521_Content_103 = {
    Text = "Das Feuer flackerte kurz auf und erlosch dann wieder."
  },
  AvgDialog_145521_Content_104 = {
    Text = "Kann ich dich zurückbringen?"
  },
  AvgDialog_145521_Content_105 = {
    Text = "Wirst du mich beim nächsten Treffen noch erkennen?"
  },
  AvgDialog_145521_Content_106 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_145521_Content_107 = {
    Text = "Lange Zeit später schloss er das Buch, stand auf und ging still zum Höhleneingang, wo er sich bückte, um die vom Nachtschnee verstopften Lüftungsspalten freizuräumen."
  },
  AvgDialog_145521_Content_108 = {
    Text = "Der Schnee rieselte durch seine Finger und fiel lautlos auf den bereits angehäuften kleinen Haufen."
  },
  AvgDialog_145521_Content_109 = {
    Text = "Das Tageslicht war noch nicht angebrochen."
  },
  AvgDialog_145521_Content_11 = {
    Text = "Hat hier früher jemand gewohnt?"
  },
  AvgDialog_145521_Content_110 = {
    Text = "Du wirst durch das schwache Licht geweckt, das durch den Höhleneingang hereinfällt."
  },
  AvgDialog_145521_Content_111 = {
    Text = "Castor hatte Die Rucksäcke bereits gepackt und stand am Höhleneingang, um auf dein Erwachen zu warten."
  },
  AvgDialog_145521_Content_112 = {
    Text = "Entschuldigung, ich mache mich jetzt auf den Weg."
  },
  AvgDialog_145521_Content_113 = {
    Text = "Mein Wunsch ist ein anderer als eurer."
  },
  AvgDialog_145521_Content_114 = {
    Text = "Ich möchte meinen Bruder wiederfinden, und das schaffe ich mit meinen eigenen Händen."
  },
  AvgDialog_145521_Content_115 = {
    Text = "Aber der Weg ist viel zu gefährlich, du allein—"
  },
  AvgDialog_145521_Content_116 = {
    Text = "…Noch eine Sache — ich war mir zunächst nicht sicher, ob ich es euch sagen sollte. Aber jetzt ist es Zeit für ein Geständnis—"
  },
  AvgDialog_145521_Content_117 = {
    Text = "Castor holte tief Luft, als hätte er einen großen Entschluss gefasst."
  },
  AvgDialog_145521_Content_118 = {
    Text = "Als wir uns das erste Mal trafen, sagte Tinct, dass ich zwar nicht so beliebt sei wie Pollux, aber dennoch meine Stärken hätte — dass ich allein der Verfolgung der Kirche der Lichtträger entkommen könne."
  },
  AvgDialog_145521_Content_119 = {
    Text = "Aber das war gelogen. Eine Täuschung für euch."
  },
  AvgDialog_145521_Content_12 = {
    Text = "Ein alter Unterschlupf einer Bergsteigergruppe, schon seit vielen Jahren verlassen. Die Feuerstelle ist dort drüben, ich räume sie kurz frei."
  },
  AvgDialog_145521_Content_120 = {
    Text = "Ich bin schwächer, als ihr wisst, und ich habe es nicht geschafft."
  },
  AvgDialog_145521_Content_121 = {
    Text = "Die Gläubigen sind mir ständig dicht auf den Fersen. Wenn ich bleibe, werde ich euch alle zur Last fallen."
  },
  AvgDialog_145521_Content_122 = {
    Text = "Er hob den Kopf und blickte tiefer in die Höhle, wo die anderen noch schliefen."
  },
  AvgDialog_145521_Content_123 = {
    Text = "Das beschädigte Symbol in der Höhle — ich habe es erkannt. Es ist das Symbol der Kirche der Lichtträger."
  },
  AvgDialog_145521_Content_124 = {
    Text = "Dies ist ihr vorübergehender Stützpunkt."
  },
  AvgDialog_145521_Content_125 = {
    Text = "Je weiter oben, desto offener wird es – früher oder später werden sie mich Entdecken. Besser, ich gehe früh genug und mische mich unter die Menge, so kann ich ihrer Verfolgung besser entkommen."
  },
  AvgDialog_145521_Content_126 = {
    Text = "Er drehte sich um und schritt in den Wind und Schnee hinaus."
  },
  AvgDialog_145521_Content_127 = {
    Text = "Du standest reglos da und blicktest lange, bis seine Gestalt vollständig verschwunden war."
  },
  AvgDialog_145521_Content_128 = {
    Text = "Von hinten waren leise Schritte zu hören."
  },
  AvgDialog_145521_Content_129 = {
    Text = "Caraboo war irgendwann ebenfalls aufgestanden und lehnte am Höhleneingang, den Blick in die Richtung gerichtet, in die Castor gegangen war."
  },
  AvgDialog_145521_Content_13 = {
    Text = "Er ging routiniert auf einen rußgeschwärzten Steinblock in der Mitte der Höhle zu, kauerte sich hin und begann, die alten Asche beiseite zu schieben."
  },
  AvgDialog_145521_Content_130 = {
    Text = "……Dummkopf."
  },
  AvgDialog_145521_Content_131 = {
    Text = "In ihrer Stimme lag nicht der übliche Dorn."
  },
  AvgDialog_145521_Content_132 = {
    Text = "Das Bergsteigertrupp schrumpfte von fünf auf vier Personen."
  },
  AvgDialog_145521_Content_14 = {
    Text = "Castors Blick verweilte kurz auf den Wandritzungen. Er sagte nichts, sondern wandte nur seinen Blick ab."
  },
  AvgDialog_145521_Content_15 = {
    Text = "Noch bevor jemand fragen konnte, zog Caraboos Ruf aller Blicke auf sich."
  },
  AvgDialog_145521_Content_16 = {
    Text = "<Big:Eine mollig warme Höhle! Ein Lagerfeuer! Eine lange Ruhe!>"
  },
  AvgDialog_145521_Content_17 = {
    Text = "Caraboo war voller Begeisterung."
  },
  AvgDialog_145521_Content_18 = {
    Text = "Obwohl alle auf dem Zahnfleisch gingen, konnte man sehen, dass der Kampf gegen den Wendigo jeden völlig erschöpft hatte."
  },
  AvgDialog_145521_Content_19 = {
    Text = "Eine genau richtige Höhle. Eine genau richtige Ruhe."
  },
  AvgDialog_145521_Content_2 = {
    Text = "Der Schneesturm hörte nicht auf. Ihr suchtet entlang der Risse im Eis nach einem Unterschlupf und fandet schließlich unter einer Felswand eine windgeschützte Schneehöhle."
  },
  AvgDialog_145521_Content_20 = {
    Text = "Welche Gefahr auch immer vor euch lauert, sie kann euch nicht daran hindern, diesen Moment der Behaglichkeit zu genießen."
  },
  AvgDialog_145521_Content_21 = {
    Text = "Das Feuer brennt an der Innenseite des Höhleneingangs, nahe dem Ausgang. Der Rauch wird vom schräg einfallenden Wind nach draußen getragen."
  },
  AvgDialog_145521_Content_22 = {
    Text = "Evelyn holte eine Isomatte aus ihrem Rucksack, drückte zunächst eine dünne Schicht Schnee auf den Boden und breitete dann die Matte darüber aus."
  },
  AvgDialog_145521_Content_23 = {
    Text = "Die Gruppe zog ihre steifgefrorenen Jacken aus, versammelte sich um das Lagerfeuer und streckte die Hände so nah wie möglich an die Flammen."
  },
  AvgDialog_145521_Content_24 = {
    Text = "Wäre es doch schön, wenn es auf dem Berg immer so warm wäre."
  },
  AvgDialog_145521_Content_25 = {Text = "Pfft."},
  AvgDialog_145521_Content_26 = {
    Text = "Worüber lachst du?"
  },
  AvgDialog_145521_Content_27 = {
    Text = "Ich lache über dich, du Trottel, der nicht weiß, was er sagt. Was wäre, wenn die Schneeberg-Göttin das als deinen wahren Wunsch ansieht und ihn erfüllt?"
  },
  AvgDialog_145521_Content_28 = {
    Text = "Das wäre auch nicht schlecht. Dann wären alle Bergsteiger viel sicherer."
  },
  AvgDialog_145521_Content_29 = {
    Text = "Das Licht des Lagerfeuers spiegelte sich in Castors ernsthaften Augen."
  },
  AvgDialog_145521_Content_3 = {
    Text = "Der Eingang war eng, doch das Innere war überraschend geräumig."
  },
  AvgDialog_145521_Content_30 = {
    Text = "Ach, es macht keinen Spaß, dich, du Trottel, zu necken."
  },
  AvgDialog_145521_Content_31 = {
    Text = "Caraboo, hast du einen Wunsch?"
  },
  AvgDialog_145521_Content_32 = {
    Text = "Caraboo schien nicht damit gerechnet zu haben, so plötzlich gefragt zu werden. Nach einem kurzen Zögern ließ sie ihre Augen wandern."
  },
  AvgDialog_145521_Content_33 = {
    Text = "Ich bin doch die Schneeberg-Göttin – ich bin diejenige, die eure Wünsche erfüllt!"
  },
  AvgDialog_145521_Content_34 = {
    Text = "Wenn ich einen Wunsch nennen müsste, dann wäre es wohl, meine Macht zurückzugewinnen."
  },
  AvgDialog_145521_Content_35 = {
    Text = "Ja! Genau! Nachdem ich meine Macht zurückgewonnen habe, werde ich Den Heiligen Orden neu aufstellen! Der gesamte Kontinent soll die Schneeberg-Göttin mit Verehrung ehren!"
  },
  AvgDialog_145521_Content_36 = {
    Text = "Evelyn lacht leise auf. Das Feuerlicht flackert in ihren dunklen Augen."
  },
  AvgDialog_145521_Content_37 = {
    Text = "Was ist mit den anderen?"
  },
  AvgDialog_145521_Content_38 = {
    Text = "Sie wandte sich dir zu, ihr Blick war nicht forschend, sondern nur die sorgende Anteilnahme eines Small Talks."
  },
  AvgDialog_145521_Content_39 = {
    Text = "Ich bin auch neugierig! Was für einen Wunsch soll ich meinem Wohltäter erfüllen?"
  },
  AvgDialog_145521_Content_4 = {
    Text = "Noch keiner rein."
  },
  AvgDialog_145521_Content_40 = {
    Text = "Jemand hat mir den Weg nach Hause gewiesen. Um dorthin zurückzukehren, muss ich eine bestimmte Person finden."
  },
  AvgDialog_145521_Content_41 = {
    Text = "Du bist auch ein Trottel. Warum wünschst du dir nicht einfach, zurückzukehren?"
  },
  AvgDialog_145521_Content_42 = {
    Text = "Jemand hat einst eine Prophezeiung für mich geschrieben."
  },
  AvgDialog_145521_Content_43 = {
    Text = "<Yellow:Schicksal ist ein Geflecht aus ineinandergreifenden Fäden. Wer versucht, einen Knoten zu überspringen und direkt ans Ziel zu gelangen, wird unweigerlich den Schmerz des reißenden Fadens erleiden.>"
  },
  AvgDialog_145521_Content_44 = {
    Text = "Verstanden. Und was ist mit diesem Wilhelm hier an deiner Seite?"
  },
  AvgDialog_145521_Content_45 = {
    Text = "Wilhelms Geschichte ist etwas kompliziert zu erzählen."
  },
  AvgDialog_145521_Content_46 = {
    Text = "Zumindest jetzt ist das Wichtigste für mich, %player% zu begleiten – zurück nach Misaq, zurück zu Ramona."
  },
  AvgDialog_145521_Content_47 = {
    Text = "Du starrst Wilhelm fassungslos an. Sein Gesicht ist völlig ruhig, und in seinen Micro-Emojis findest du nicht die geringste Spur einer Lüge."
  },
  AvgDialog_145521_Content_48 = {
    Text = "Hör auf, mich so anzustarren."
  },
  AvgDialog_145521_Content_49 = {
    Text = "<Yellow:Meine anderen Pflichten in dieser Welt haben vorübergehend ein Ende gefunden.>"
  },
  AvgDialog_145521_Content_5 = {
    Text = "Er hob die Eispicke und klopfte Zentimeter für Zentimeter entlang der Innenseite des Höhleneingangs ab."
  },
  AvgDialog_145521_Content_50 = {
    Text = "Als er das sagte, hob Wilhelm bewusst die Hand, um die Haarsträhnen aus seinem Gesicht zu streichen, und verdeckte dabei einen Großteil seines Ausdrucks."
  },
  AvgDialog_145521_Content_51 = {
    Text = "Und du, Trottel?"
  },
  AvgDialog_145521_Content_52 = {Text = "Ich?"},
  AvgDialog_145521_Content_53 = {
    Text = "Castor starrte gedankenverloren ins Lagerfeuer."
  },
  AvgDialog_145521_Content_54 = {
    Text = "Ich möchte, dass Pollux … zurückkommt."
  },
  AvgDialog_145521_Content_55 = {
    Text = "Caraboo hob den Blick zu Castor, und der Funken seiner üblichen Gleichgültigkeit in seinen Augen verschwand für einen Moment."
  },
  AvgDialog_145521_Content_56 = {
    Text = "Du hast gerade gesagt, du möchtest, dass er zurückkommt."
  },
  AvgDialog_145521_Content_57 = {
    Text = "Aber als wir uns zum ersten Mal begegnet sind, sagtest du, du möchtest ihn retten."
  },
  AvgDialog_145521_Content_58 = {
    Text = "Zwischen diesen beiden Formulierungen liegt ein feiner Unterschied … aber sie schließen sich nicht unbedingt aus."
  },
  AvgDialog_145521_Content_59 = {
    Text = "Castor, dein Bruder – wurde er wirklich von diesem sogenannten Anführer gefangen gehalten?"
  },
  AvgDialog_145521_Content_6 = {
    Text = "Dieser Locker hier – beim Lagern die Stelle direkt darunter meiden."
  },
  AvgDialog_145521_Content_60 = {
    Text = "Eine kurze Stille. Caraboo nahm den Apfel und biss erneut hinein, als wäre nichts gewesen, und wechselte das Thema."
  },
  AvgDialog_145521_Content_61 = {
    Text = "Eigentlich ist es ganz einfach, einen Wunsch zu erfüllen."
  },
  AvgDialog_145521_Content_62 = {
    Text = "Siehst du, unter den sieben Schätzen ist doch auch eine Feder, oder? Vielleicht ist die Feder, die du bei dir trägst, ja die <Yellow:Feder der Ma'at>."
  },
  AvgDialog_145521_Content_63 = {
    Text = "Ma'at, die Göttin der Wahrheit, Ordnung und Gerechtigkeit, trägt eine Straußenfeder auf dem Kopf."
  },
  AvgDialog_145521_Content_64 = {
    Text = "Beim Totengericht legt Anubis das Herz des Verstorbenen zusammen mit dieser Feder auf die Waage. Ist das Herz schwerer als die Feder, wird es vom Monster Ammit verschlungen; ist das Herz so leicht wie die Feder, darf die Seele ins Schilfrohrfeld eintreten."
  },
  AvgDialog_145521_Content_65 = {
    Text = "Die Feder steht in der ägyptischen Mythologie für „Unschuld“."
  },
  AvgDialog_145521_Content_66 = {
    Text = "Die Feder der Unschuld … wie ironisch."
  },
  AvgDialog_145521_Content_67 = {
    Text = "Castor lächelte ein leicht resigniertes Lächeln."
  },
  AvgDialog_145521_Content_68 = {
    Text = "Diese Flügel wurden mir und meinem Bruder von Juliette, der Oberhaupt der Kirche der Lichtträger, implantiert – um ihre Gottheit zu erschaffen."
  },
  AvgDialog_145521_Content_69 = {
    Text = "In seiner Erzählung hörst du eine Stimme. Eine Stimme unaufhaltsamen Schmerzes."
  },
  AvgDialog_145521_Content_7 = {
    Text = "Er ging gebückt tiefer in die Höhle, kauerte sich hin, legte sein Ohr an den Boden und lauschte eine Weile, dann prüfte er mit dem Handrücken die Feuchtigkeit der Felswand."
  },
  AvgDialog_145521_Content_70 = {
    Text = "Später riss sie Pollux die Flügel heraus. Jetzt bin nur noch ich derjenige, der diese schändlichen Flügel trägt."
  },
  AvgDialog_145521_Content_71 = {
    Text = "Castor streichelt sanft die Federn an den Flügelspitzen, und für einen Moment glaubst du, sie seien blutbefleckt."
  },
  AvgDialog_145521_Content_72 = {
    Text = "Also, wenn man von Unschuld sprechen will … diese Flügel sind wohl das, was am weitesten von Unschuld entfernt ist."
  },
  AvgDialog_145521_Content_73 = {
    Text = "Die Luft wird still, nur das Knistern des brennenden Lagerfeuers ist zu hören."
  },
  AvgDialog_145521_Content_74 = {
    Text = "Naraka, und was ist mit deinem Wunsch?"
  },
  AvgDialog_145521_Content_75 = {
    Text = "Wilhelm wandte sich plötzlich an Naraka, der sich gerade am Feuer wärmte und offenbar nicht vorhatte, sich am Gespräch zu beteiligen."
  },
  AvgDialog_145521_Content_76 = {
    Text = "Ich bin nur ein Führer und habe nicht vor, mit euch zusammen einen Wunsch zu erfüllen."
  },
  AvgDialog_145521_Content_77 = {
    Text = "Wenn man unbedingt von <Yellow:Narakas Wunsch> sprechen müsste, dann hofft er vielleicht, dass der Name der Sherpa-Führer ebenfalls in die Annalen der Bergsteiger eingehen möge."
  },
  AvgDialog_145521_Content_78 = {
    Text = "Aber einen solchen Wunsch durch ein Wunder zu erfüllen wäre doch viel zu langweilig, oder nicht?"
  },
  AvgDialog_145521_Content_79 = {
    Text = "Durch das Verfassen und Fälschen von Büchern Lügen über die Geschichte zu verbreiten – das ist zu einfach, zu mühelos, so mühelos, dass es jeden Wert verliert."
  },
  AvgDialog_145521_Content_8 = {
    Text = "Kommt rein, Innen sollte es sicher sein."
  },
  AvgDialog_145521_Content_80 = {
    Text = "Den Gipfel zu erreichen – das sollte man doch mit den eigenen Füßen schaffen."
  },
  AvgDialog_145521_Content_81 = {
    Text = "Aus eigener Kraft …"
  },
  AvgDialog_145521_Content_82 = {
    Text = "Castor schien etwas zu spüren."
  },
  AvgDialog_145521_Content_83 = {
    Text = "Hey — du siehst nicht gerade aus wie jemand, der solche rechtschaffenen Dinge sagt."
  },
  AvgDialog_145521_Content_84 = {
    Text = "Caraboo kniff sich die Nase zu und wedelte mit der Hand, als ob sie etwas Übelriechendes gerochen hätte."
  },
  AvgDialog_145521_Content_85 = {
    Text = "Zeit für ehrliche Worte — hör auf zu spielen, lass uns mal aufrichtig reden?"
  },
  AvgDialog_145521_Content_86 = {
    Text = "Sie starrte amüsiert in Narakas Augen, Naraka wich ihrem Blick aus, sie beugte sich vor und verfolgte ihn hartnäckig mit ihrem Blick."
  },
  AvgDialog_145521_Content_87 = {
    Text = "<Shake:Komm schon, zeig mir dein wahres Gesicht!>"
  },
  AvgDialog_145521_Content_88 = {
    Text = "Caraboo stürzte sich nach vorne und wollte Naraka greifen wie ein Adler, der ein Küken schnappt, aber Naraka wich nur leicht zur Seite aus."
  },
  AvgDialog_145521_Content_89 = {
    Text = "Hört auf mit dem Unsinn, morgen müssen wir noch den Weg fortsetzen. Ich will nicht, dass ihr den Gipfel nicht erreicht."
  },
  AvgDialog_145521_Content_9 = {
    Text = "An der Felswand waren verblasste Muster zu erkennen – die Umrisse irgendeines Zeichens, dessen Farbe längst so abgeblättert war, dass es kaum noch zu entziffern war."
  },
  AvgDialog_145521_Content_90 = {
    Text = "Caraboo griff ins Leere und ließ sich einfach in den Schnee fallen, mit einem breiten Grinsen im Gesicht."
  },
  AvgDialog_145521_Content_91 = {
    Text = "Da du uns auch den Gipfel erreichen lassen willst, bin ich beruhigt."
  },
  AvgDialog_145521_Content_92 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_145521_Content_93 = {
    Text = "Das Lagerfeuer brennt bis tief in die Nacht hinein und ist zu vereinzelten roten Glutresten geworden."
  },
  AvgDialog_145521_Content_94 = {
    Text = "Naraka teilte die Nachtwache ein, je zwei Stunden pro Person.\nNach und nach schliefen alle ein. Aus den Schlafsäcken drangen leise, gedämpfte Schnarchgeräusche."
  },
  AvgDialog_145521_Content_95 = {
    Text = "Castor übernahm ganz selbstverständlich die erste Wache. Er lehnte an der Höhlenwand und holte aus den Tiefen der Rucksäcke ein kleines Buch hervor, dessen Ecken weiß abgegriffen waren."
  },
  AvgDialog_145521_Content_96 = {
    Text = "Es war ein Märchenbuch."
  },
  AvgDialog_145521_Content_97 = {
    Text = "Seine Fingerspitzen strichen über die zwei Namen auf der Titelseite."
  },
  AvgDialog_145521_Content_98 = {
    Text = "Die ordentliche Kinderschrift stammte von ihm selbst, der andere Name war mit einem roten Wachsmalstift schief und krumm gemalt, die Farbe mit der Zeit durch das Berühren verblasst."
  },
  AvgDialog_145521_Content_99 = {Text = "Pollux…"},
  AvgDialog_145522_Content_1 = {
    Text = "Nicht antworten"
  },
  AvgDialog_145522_Content_10 = {
    Text = "Castor ging am Ende des Trupps, stiller als sonst."
  },
  AvgDialog_145522_Content_11 = {
    Text = "Hey, Träumer. Ist dir kalt?"
  },
  AvgDialog_145522_Content_12 = {
    Text = "Mir geht's gut."
  },
  AvgDialog_145522_Content_13 = {
    Text = "Mir auch. Das ist seltsam."
  },
  AvgDialog_145522_Content_14 = {
    Text = "Von wem kommt dann dieses so schwere, so laute Atemgeräusch?"
  },
  AvgDialog_145522_Content_15 = {
    Text = "Der Trupp hielt an. Alle drehten sich wie auf Kommando um. Hinter ihnen gab es nur die tiefen und flachen Fußspuren, die sie selbst hinterlassen hatten."
  },
  AvgDialog_145522_Content_16 = {
    Text = "An den Rändern der Fußspuren war der Schnee makellos sauber. So sauber, als wäre er von etwas sanft weggewischt worden."
  },
  AvgDialog_145522_Content_17 = {
    Text = "Stille. Nur der Wind. Der Wind kam aus weiter Ferne, umrundete den Bergrücken und kroch in jeden Kragen."
  },
  AvgDialog_145522_Content_18 = {
    Text = "Im Wind lag ein kaum wahrnehmbares Geräusch. Es war kein Gesang. Es war ein Ruf."
  },
  AvgDialog_145522_Content_19 = {
    Text = "<Change>...Eve...lyn..."
  },
  AvgDialog_145522_Content_2 = {
    Text = "Der Schneesturm hatte nachgelassen, doch der Himmel sah düsterer aus als während des schlimmsten Treibens."
  },
  AvgDialog_145522_Content_20 = {Text = "?!"},
  AvgDialog_145522_Content_21 = {
    Text = "Sie fuhr ruckartig herum. Das Schneefeld war weit und leer, nichts war zu sehen. Doch die Stimme kam erneut, diesmal näher, mit einer fast grausamen Sanftheit."
  },
  AvgDialog_145522_Content_22 = {
    Text = "<Change>...Evelyn... Mir ist kalt..."
  },
  AvgDialog_145522_Content_23 = {Text = "Das ist..."},
  AvgDialog_145522_Content_24 = {
    Text = "<Shake:Das ist unmöglich …>"
  },
  AvgDialog_145522_Content_25 = {
    Text = "Ihr Gesicht verlor augenblicklich alle Farbe. Ihre Lippen waren weiß, ihre Stimme zitterte, als wäre der Moment, den sie sich mehr als einmal vorgestellt hatte, endlich eingetroffen."
  },
  AvgDialog_145522_Content_26 = {
    Text = "Habt ihr … habt ihr das alle gehört?!"
  },
  AvgDialog_145522_Content_27 = {Text = "Er ist es."},
  AvgDialog_145522_Content_28 = {
    Text = "<Shake:Seine Stimme……>"
  },
  AvgDialog_145522_Content_29 = {
    Text = "Evelyn, egal wen Du hörst — antworte ihm nicht."
  },
  AvgDialog_145522_Content_3 = {
    Text = "Bleigraue Wolken hingen tief über dem Bergrücken, wie ein schwerer, alter Traum, der sich nicht auflösen wollte."
  },
  AvgDialog_145522_Content_30 = {
    Text = "Ihr haltet den Atem an. Der Wind des Schneefelds streicht an euren Ohren vorbei, und dann— \nIhr hört es alle."
  },
  AvgDialog_145522_Content_31 = {
    Text = "Der Wind verwandelt sich in unzählige Stimmen, unzählige zärtliche Rufe. Jeder weht aus einer Richtung, die Du einst kanntest und einst verloren hast."
  },
  AvgDialog_145522_Content_32 = {
    Text = "Eine Stimme. Eine Stimme ruft nach Dir. Eiskalt und klar."
  },
  AvgDialog_145522_Content_33 = {
    Text = "<Change>Ich warte auf dich, Partner..."
  },
  AvgDialog_145522_Content_34 = {
    Text = "<Change>Bleib nicht zurück. Wir werden das gemeinsam bis zum Ende durchstehen."
  },
  AvgDialog_145522_Content_35 = {Text = "Ramona..."},
  AvgDialog_145522_Content_36 = {
    Text = "Du beißt die Zähne zusammen und konterst den Drang, der Stimme zu folgen."
  },
  AvgDialog_145522_Content_37 = {
    Text = "Deine Füße sind wie im Schnee eingefroren und gehorchen Dir nicht. Du spürst eine äußerst leichte, äußerst sanfte Kraft, die aus der Richtung der Stimme kommt und langsam, ganz langsam Deinen Schwerpunkt nach vorne zieht."
  },
  AvgDialog_145522_Content_38 = {
    Text = "Das ist eine Einladung. Eine unwiderstehliche Einladung."
  },
  AvgDialog_145522_Content_39 = {
    Text = "Solange Du bereit bist, einen Schritt vorwärts zu gehen, kannst Du in jeden warmen Moment der Vergangenheit zurückkehren —"
  },
  AvgDialog_145522_Content_4 = {
    Text = "Niemand sprach. Die Schlittenhunde liefen voraus, und selbst sie dämpften das gewohnte Winseln tief in ihrer Kehle."
  },
  AvgDialog_145522_Content_40 = {
    Text = "Schutzherr —"
  },
  AvgDialog_145522_Content_41 = {
    Text = "Wilhelms Stimme dringt aus weiter Ferne zu Dir. Erst jetzt merkst Du, dass Du irgendwann unmerklich einen halben Schritt gemacht hast."
  },
  AvgDialog_145522_Content_42 = {
    Text = "Ein paar Schlittenhunde liegen tot neben dir auf dem Boden, ihre Kehlen brutal aufgerissen, mit scharlachrotem Blut, das in grellen, harten Flecken über den makellosen weißen Schnee gespritzt ist."
  },
  AvgDialog_145522_Content_43 = {
    Text = "Tritt einen Schritt zurück."
  },
  AvgDialog_145522_Content_44 = {
    Text = "Gib mir Deine Hand."
  },
  AvgDialog_145522_Content_45 = {
    Text = "Wilhelms Gesicht ist kreidebleich, und die Hand, die Deinen Arm hält, zittert unwillkürlich."
  },
  AvgDialog_145522_Content_46 = {
    Text = "Du kannst spüren, wie er sich mit aller Kraft kontert, sich selbst davon abhält, der Stimme zu erliegen."
  },
  AvgDialog_145522_Content_47 = {
    Text = "Diese Stimme ist falsch. Ihr müsst aufwachen."
  },
  AvgDialog_145522_Content_48 = {
    Text = "Er spricht mit äußerst leiser Stimme, als würde er ein Urteil verkünden."
  },
  AvgDialog_145522_Content_49 = {
    Text = "<Shake:<Small:Ugh… Tante Rosa…>>"
  },
  AvgDialog_145522_Content_5 = {
    Text = "Langsamer, das Gelände ist uneben."
  },
  AvgDialog_145522_Content_50 = {
    Text = "Caraboo erwacht wie aus einem Traum und murmelt noch etwas vor sich hin."
  },
  AvgDialog_145522_Content_51 = {
    Text = "Aber nicht alle können aufwachen."
  },
  AvgDialog_145522_Content_52 = {
    Text = "Pollux…! Pollux…! Wo bist du?!"
  },
  AvgDialog_145522_Content_53 = {
    Text = "<Shake:<Big:Pollux…!!!>>"
  },
  AvgDialog_145522_Content_54 = {
    Text = "<Italic:…Bruder, mir ist kalt…>"
  },
  AvgDialog_145522_Content_55 = {
    Text = "<Italic:Bruder, die Zelle ist so dunkel, ich habe solche Angst… bitte… lass mich raus… Hochwürden, sie…>"
  },
  AvgDialog_145522_Content_56 = {
    Text = "<Shake:<Italic:…Bruder, warum kommst du nicht zu mir…>>"
  },
  AvgDialog_145522_Content_57 = {
    Text = "Pollux!! Warte auf mich, ich komme sofort —"
  },
  AvgDialog_145522_Content_58 = {
    Text = "<Shake:Hey, Dummkopf, bleib stehen!>"
  },
  AvgDialog_145522_Content_59 = {
    Text = "Euren Ruf ignorierend, stürmt Castor hinaus."
  },
  AvgDialog_145522_Content_6 = {
    Text = "Dieser Abschnitt war früher ein gerader Hang, jetzt hat er sich in querlaufende Schluchten gespalten."
  },
  AvgDialog_145522_Content_60 = {
    Text = "<Shake:Haltet ihn fest!>"
  },
  AvgDialog_145522_Content_61 = {
    Text = "Lasst diesen Dummkopf nicht weglocken!"
  },
  AvgDialog_145522_Content_7 = {
    Text = "Das sind neue Risse, die nach dem letzten Lawinenabgang entstanden sind … sie sollten nicht so tief sein."
  },
  AvgDialog_145522_Content_8 = {
    Text = "Die Form des Berges verändert sich."
  },
  AvgDialog_145522_Content_9 = {
    Text = "Wilhelm sprach nicht weiter. Seine smaragdgrünen Augen blickten in die Ferne, die Stirn leicht gerunzelt."
  },
  AvgDialog_145523_Content_1 = {
    Text = "Der wunschlose Gipfel"
  },
  AvgDialog_145523_Content_10 = {
    Text = "Wilhelm hockt sich langsam hin, seine Fingerspitzen gleiten über die kunstvollen Schnitzereien zwischen den Sockeln, die du für bloßen Zierrat gehalten hattest."
  },
  AvgDialog_145523_Content_100 = {
    Text = "<Shake:Hör auf! Schalte es ab! <Red:Ich werde verfaulen, bevor der Wunsch überhaupt erfüllt wird!>>"
  },
  AvgDialog_145523_Content_101 = {
    Text = "Das war nie Teil unseres Handels."
  },
  AvgDialog_145523_Content_102 = {
    Text = "Ja, er hat nur versprochen, das Ritual für dich zu beginnen. Er hat dir nie versprochen, dass du es überleben würdest."
  },
  AvgDialog_145523_Content_103 = {
    Text = "Ich verstehe … Jedes einzelne Wort, das Wilhelm gesagt hat, war die absolute Wahrheit … doch zusammengesetzt ergaben sie eine perfekte Lüge."
  },
  AvgDialog_145523_Content_104 = {
    Text = "Der sechste Heiligenschein erhebt sich."
  },
  AvgDialog_145523_Content_105 = {
    Text = "Der ganze Berg bebt wie ein sterbendes Wesen. Unzählige bleiche Fleischmassen drängen aus dem berstenden Fels hervor und stürzen wie eine Welle auf den Altar zu."
  },
  AvgDialog_145523_Content_106 = {
    Text = "Nein! Das gehört mir! Mein Fleisch! Meine Stärke! Mein Wille!"
  },
  AvgDialog_145523_Content_107 = {
    Text = "Oder vielleicht gehörten sie dir von Anfang an nie. Diese Macht gehört dir nicht. Das sind die gestohlenen Wünsche der zahllosen Pilger, die du hierher gelockt und hier begraben hast."
  },
  AvgDialog_145523_Content_108 = {
    Text = "Diese Macht gehört all jenen, die du betrogen, verschlungen und weggeworfen hast. Du hast kein Recht, sie zu beanspruchen..."
  },
  AvgDialog_145523_Content_109 = {
    Text = "...Und jetzt kehren sie einfach dorthin zurück, wo sie hingehören."
  },
  AvgDialog_145523_Content_11 = {
    Text = "Unmöglich... wie kann das hier sein... Diese Zeichen neben den Gravuren des Altars... ich erkenne sie."
  },
  AvgDialog_145523_Content_110 = {
    Text = "Tinct, Castor, Evelyn und Fengol, den du nie persönlich treffen konntest..."
  },
  AvgDialog_145523_Content_111 = {
    Text = "Gesicht um Gesicht, Name um Name steigt an die Oberfläche deines Geistes, bevor er tief in das stille Dunkel der Erinnerung versinkt."
  },
  AvgDialog_145523_Content_112 = {
    Text = "<BigShake:Wage es nicht! WAGE ES NICHT!>"
  },
  AvgDialog_145523_Content_113 = {
    Text = "<Big:<Red:Ich zerstöre zuerst den Altar und zerkau dann jeden Einzelnen von euch in Stücke!>"
  },
  AvgDialog_145523_Content_114 = {
    Text = "Wilhelm nickt dir zu."
  },
  AvgDialog_145523_Content_115 = {
    Text = "Jeder übernimmt seinen Teil. Ich halte das Ritual am Laufen."
  },
  AvgDialog_145523_Content_116 = {
    Text = "Überlass das mir. Ich halte den Wurm auf!"
  },
  AvgDialog_145523_Content_12 = {
    Text = "Das ist Fengols Handschrift."
  },
  AvgDialog_145523_Content_13 = {Text = "Fengol?"},
  AvgDialog_145523_Content_14 = {
    Text = "Du kennst diesen Namen. Wilhelms Partner, der Ermittler, der vor ihm aus „jener Welt\" verschwand."
  },
  AvgDialog_145523_Content_15 = {
    Text = "Ich verstehe, der Schlüssel Salomons … der Grund, warum der Wurm das Ritual nicht starten konnte … und der Zweck, weshalb Fengol in diese Welt gekommen ist …"
  },
  AvgDialog_145523_Content_16 = {
    Text = "Hahaha... Ich verstehe! Jetzt verstehe ich! Das ist zum Totlachen!"
  },
  AvgDialog_145523_Content_17 = {
    Text = "Also das wollte mir dieser workaholic Weber zeigen. Es hat sich wirklich gelohnt, euch alle den Weg hier herauf zu bringen!"
  },
  AvgDialog_145523_Content_18 = {
    Text = "Was meinst du?"
  },
  AvgDialog_145523_Content_19 = {
    Text = "N zuckt einfach mit den Schultern."
  },
  AvgDialog_145523_Content_2 = {
    Text = "Es war ein gewaltiger Altar, der so alt wirkte Als ob er mit dem gesamten Gebirgszug gleichen Alters wäre."
  },
  AvgDialog_145523_Content_20 = {
    Text = "Nun, ich bin nicht dein Übersetzer. Siehst du diesen Herrn Wilhelm hier? Frag ihn. Du hast mich zwar aus deinem Bauch herausgelassen, aber sehe ich etwa so aus, als hätte ich vor, den „Gefallen“ zu erwidern?"
  },
  AvgDialog_145523_Content_21 = {
    Text = "Ich werde es erklären."
  },
  AvgDialog_145523_Content_22 = {
    Text = "„Der Schlüssel Salomons\" ist eigentlich kein Schlüssel, sondern ein Grimoire."
  },
  AvgDialog_145523_Content_23 = {
    Text = "Und der wichtigste Inhalt, der im Grimoire verzeichnet ist, sind die Beschwörungsmethoden der zweiundsiebzig Dämonen Salomons. Mit anderen Worten: die Methode, Welten zu verbinden."
  },
  AvgDialog_145523_Content_24 = {
    Text = "Er hob den Kopf und blickte auf die Mitte der sieben Sockel — ein schmales Schlüsselloch, das Fast mit dem Schatten zusammenführen schien."
  },
  AvgDialog_145523_Content_25 = {
    Text = "Diese Zeichen sind eine Geheimsprache, die nur er und ich lesen können."
  },
  AvgDialog_145523_Content_26 = {
    Text = "Wilhelm kniet am Zauberkreis nieder, seine Hand folgt behutsam den Schnitzereien auf dem Boden. Langsam beginnen die stillen Worte sich in seinem Geist zusammenzufügen und formen eine vertraute Stimme."
  },
  AvgDialog_145523_Content_27 = {
    Text = "Ist das Wilhelm? Ich wusste, dass du es so weit schaffen würdest.\n\nDer Zauberkreis hier enthält drei verschiedene alte Schriften. Ich würde wetten, dass in unserem Kreis nur du, der fleißige Schüler, sie alle auf einmal lesen könntest.\nEs sind Beschwörungs- und Versiegelungszauber. Du solltest verstehen, was das bedeutet."
  },
  AvgDialog_145523_Content_28 = {
    Text = "Es kontrolliert das Öffnen und Schließen eines bestimmten „Tores.“"
  },
  AvgDialog_145523_Content_29 = {
    Text = "#N/AKurz gesagt, dieser Zauberkreis nutzt die „Krone“ als Medium und verbindet sich mit dem Ursprung dieser Welt. Daher kann er tatsächlich jeden Wunsch erfüllen – zumindest innerhalb dieser Welt.\n\nDu hast dich sicher gefragt, warum du in diese fremde Welt geworfen wurdest, nicht wahr?\n\nNun, ich kann dir die Antwort geben.\n\nDu bist dieser Wunsch ... mein Wunsch."
  },
  AvgDialog_145523_Content_3 = {
    Text = "Ringförmige Steinstufen führten Schicht für Schicht nach oben, und am Ende standen sieben leere Sockel, die einen Kreis bildeten. Zwischen den Sockeln, in uralten Rillen, hatte sich längst getrocknetes, dunkelgoldenes Licht angesammelt."
  },
  AvgDialog_145523_Content_30 = {
    Text = "Leider war die Kraft, die ich aufgebracht habe, nicht ausreichend. Ich konnte nur einen Spalt öffnen, durch den dein Silberkern hindurchgelangen konnte.\n\nDas Ziel, das ich nicht erreichen konnte ... du musst es an meiner Stelle erreichen.\n\nSchließlich bist du der legendäre Ermittler Wilhelm, oder nicht?"
  },
  AvgDialog_145523_Content_31 = {
    Text = "Ich hoffe, du hast noch meinen Silberschlüssel.\n\nNutze ihn, um den Zauberkreis zu aktivieren, dann äußere deinen Wunsch, und Er wird dich in das gelobte Land führen.\n\nDer Weg, der vor dir liegt — den überlasse ich dir.\n\nIn aufrichtiger Verbundenheit,\nFengol"
  },
  AvgDialog_145523_Content_32 = {
    Text = "Williams Finger hielten inne."
  },
  AvgDialog_145523_Content_33 = {
    Text = "Er sagt kein Wort. Diesen Ausdruck auf seinem Gesicht hast du noch nie gesehen."
  },
  AvgDialog_145523_Content_34 = {Text = "%player%."},
  AvgDialog_145523_Content_35 = {
    Text = "Ich bin hier."
  },
  AvgDialog_145523_Content_36 = {
    Text = "Hast du mich damals nicht gefragt, warum ich als Erster unter dem Ruf des Wendigo erwacht bin?"
  },
  AvgDialog_145523_Content_37 = {
    Text = "Weil ich der Einzige unter uns war, der seine Gebeine gesehen hat."
  },
  AvgDialog_145523_Content_38 = {
    Text = "Sein Körper war völlig verwest, seine Identität kaum noch zu erkennen. Aber ich erkannte den halben Silberschlüssel, den er bei sich trug."
  },
  AvgDialog_145523_Content_39 = {
    Text = "Kennnummer I-1021, eine Zahl, die zu Fengol gehört. Jedes Mal, wenn eine Zahl aus den Aufzeichnungen verschwindet, wissen wir, dass wieder ein Vorfahre von der Welt vergessen wurde."
  },
  AvgDialog_145523_Content_4 = {
    Text = "Dies ist das Ziel, an das der Bergwurm mit Wünschen als Köder unzählige Bergsteiger gelockt hat."
  },
  AvgDialog_145523_Content_40 = {
    Text = "Seitdem trage ich diesen Silberschlüssel stets bei mir."
  },
  AvgDialog_145523_Content_41 = {
    Text = "Er schloss die Augen. Als er sie wieder öffnete, war in diesen smaragdgrünen Augen nur noch etwas Stilles, Unerschütterliches geblieben."
  },
  AvgDialog_145523_Content_42 = {
    Text = "…Fengol, danke für dein Vertrauen."
  },
  AvgDialog_145523_Content_43 = {
    Text = "Wurm des Berges, ich werde dir sagen, wie du das Ritual aktivierst."
  },
  AvgDialog_145523_Content_44 = {
    Text = "Jene, die dem Berg ihre Wünsche darbringen, opfern ihre Seelen, um den Zauberkreis zu speisen. Durch sie wird eine Brücke zum Ursprung der Welt errichtet."
  },
  AvgDialog_145523_Content_45 = {
    Text = "Der Ursprung der Welt?"
  },
  AvgDialog_145523_Content_46 = {
    Text = "Wenn meine Hypothese korrekt ist, ist es die Schwarze Sonne, die am Himmel hängt."
  },
  AvgDialog_145523_Content_47 = {
    Text = "Die Schwarze Sonne existiert ähnlich wie Misaqs „Schwarzer Pool“ — alles umfassend, eine Schwebe aus den Ruinen von allem Vergangenen und Zukünftigen, ertränkt in einer ätzenden Flut."
  },
  AvgDialog_145523_Content_48 = {
    Text = "Das Ausmaß des erfüllten Wunsches hängt vollständig davon ab, wie viel von dieser Flut der Wünschende wagt, aus der Schwarzen Sonne zu schöpfen."
  },
  AvgDialog_145523_Content_49 = {
    Text = "Kleines Mädchen, behalte ihn im Auge. Stell sicher, dass er keine Lügen spinnt."
  },
  AvgDialog_145523_Content_5 = {
    Text = "Noch nie hat jemand diesen Ort lebend verlassen. Alle früheren Besteiger... sie sind alle hier. Unter unseren Füßen. Im Bauch des Berges."
  },
  AvgDialog_145523_Content_50 = {
    Text = "Widerwillig tritt Caraboo vor und starrt tief in Wilhelms Augen."
  },
  AvgDialog_145523_Content_51 = {Text = "<Shake:!!>"},
  AvgDialog_145523_Content_52 = {
    Text = "Wilhelm schließt die Augen und schüttelt sanft den Kopf."
  },
  AvgDialog_145523_Content_53 = {
    Text = "Jedes Wort, das er gerade gesprochen hat, ist wahr."
  },
  AvgDialog_145523_Content_54 = {
    Text = "<Shake:Lüg mich nicht an! Du hast gerade gezögert, du kleiner Schwindler!>"
  },
  AvgDialog_145523_Content_55 = {
    Text = "Lüge ich? Das solltest du besser wissen als ich."
  },
  AvgDialog_145523_Content_56 = {
    Text = "Der Wurm lässt ein kaltes, spottendes Lachen los, das eine Lawine von Schnee die Klippen hinunterpoltern lässt."
  },
  AvgDialog_145523_Content_57 = {
    Text = "Hmph. Das Ritual ist alles, was zählt. Sobald das erledigt ist, werde ich mich persönlich um dich kümmern, Verräter."
  },
  AvgDialog_145523_Content_58 = {
    Text = "Sag mir dann, Wurm des Berges — wie groß ist der Wunsch, den du dir erhoffst?"
  },
  AvgDialog_145523_Content_59 = {
    Text = "Hehehe... muss man das überhaupt fragen? Je gewaltiger, desto besser! Ich will die ganze Welt in meinen Bauch verschlingen – ein endloses, unerschöpfliches Festmahl!"
  },
  AvgDialog_145523_Content_6 = {
    Text = "Genug geredet. Erkläre mir, wie dieser Zauberkreis funktioniert."
  },
  AvgDialog_145523_Content_60 = {
    Text = "Was für ein gieriges, törichtes Wesen. Vielleicht hättest du die Schönheit der Mäßigung erlernen sollen."
  },
  AvgDialog_145523_Content_61 = {
    Text = "Wie könnte ein Parasit des Chaos wie du das verstehen? Hätte ich mich an die Regeln gehalten, hätte ich diese Höhen niemals erklommen."
  },
  AvgDialog_145523_Content_62 = {
    Text = "Und mit „Höhen“ meinst du, deinen aufgedunsenen, sich windenden Körper über einen vereisten Gipfel zu schleppen?"
  },
  AvgDialog_145523_Content_63 = {
    Text = "Ugh... vergiss es. Sowieso hört niemand auf meinen ausgezeichneten Rat."
  },
  AvgDialog_145523_Content_64 = {
    Text = "Verstanden."
  },
  AvgDialog_145523_Content_65 = {
    Text = "Wilhelm nickte."
  },
  AvgDialog_145523_Content_66 = {
    Text = "Um einen Wunsch von größtem Ausmaß zu fordern, musst du jedes einzelne Opfer hingeben."
  },
  AvgDialog_145523_Content_67 = {
    Text = "<BigShake:Nehmt sie! Nehmt sie alle! Sie existieren genau für diesen Moment!>"
  },
  AvgDialog_145523_Content_68 = {
    Text = "%player%, gib mir die Opfergaben."
  },
  AvgDialog_145523_Content_69 = {
    Text = "Du öffnest den Koffer."
  },
  AvgDialog_145523_Content_7 = {
    Text = "Die Stimme des Bergwurms drang von unten herauf. Diesmal lag in seinem Tonfall nicht mehr nur Spott, sondern auch eine Dringlichkeit, die über lange Zeitalter hinweg unterdrückt worden war."
  },
  AvgDialog_145523_Content_70 = {
    Text = "Der Goldene Apfel, der Spiegel von Yata, die Feder der Ma'at, das Auge des Balor, der Faden der Schicksalsgöttin, die Krone der Ariadne… und der Silberschlüssel selbst."
  },
  AvgDialog_145523_Content_71 = {
    Text = "Sieben Opfergaben finden jeweils ihren Platz auf den Sockeln, und durch die alten Rillen fließt ein dunkelgoldenes Licht, das neu aufwallt und sich zu einem vollständigen Ring verbindet."
  },
  AvgDialog_145523_Content_72 = {
    Text = "<Shake:Haha... Endlich... ENDLICH!>"
  },
  AvgDialog_145523_Content_73 = {
    Text = "Der Berg soll sein Festmahl haben. Der Berg soll seinen gesamten Vorrat verausgaben."
  },
  AvgDialog_145523_Content_74 = {
    Text = "Der Berg hat so, so lange danach gehungert."
  },
  AvgDialog_145523_Content_75 = {
    Text = "Wilhelm hielt den einzigartigen Schlüssel in der Hand und führte ihn ins Schlüsselloch."
  },
  AvgDialog_145523_Content_76 = {
    Text = "Im Namen Fengols —"
  },
  AvgDialog_145523_Content_77 = {
    Text = "<Red:Ich initiiere dieses Ritual.>"
  },
  AvgDialog_145523_Content_78 = {Text = "Klick."},
  AvgDialog_145523_Content_79 = {
    Text = "Mit einem leisen, scharfen Geräusch brechen alle sieben Opfergaben in blendendes Licht aus."
  },
  AvgDialog_145523_Content_8 = {
    Text = "Alle Blicke richten sich auf den Altar, angezogen von der dicht gedrängten, geheimnisvollen Schrift, die seine Oberfläche bedeckt."
  },
  AvgDialog_145523_Content_80 = {
    Text = "Der erste Lichtring erhebt sich über den Altar. Dann der zweite und der dritte. Die in den sieben Artefakten schlummernden Wünsche summen in Resonanz, wie sieben Flüsse, die auf ein einziges, dunkles Meer zuströmen."
  },
  AvgDialog_145523_Content_81 = {
    Text = "Hätte der Berg Hände, würde er in den Himmel greifen, um diesen strahlenden Ring zu fassen, erfüllt von verzweifeltem, brennendem Hunger."
  },
  AvgDialog_145523_Content_82 = {
    Text = "<Shake:Dieser Tag ist endlich gekommen!>"
  },
  AvgDialog_145523_Content_83 = {
    Text = "Er würde den Ring vom Himmel reißen und ihn tief in seine Brust pressen, ihn in sein aufgedunsenes Fleisch vergraben, bis jeder Tropfen seiner Kraft verschlungen wäre."
  },
  AvgDialog_145523_Content_84 = {
    Text = "Du starrst benommen in den aufgewühlten Himmel. Wenn der Wunsch des Berges erfüllt wird, was wird dann aus eurem Leben? Wird eure Reise einfach in dieser gefrorenen Einöde enden?"
  },
  AvgDialog_145523_Content_85 = {
    Text = "In diesem Sekundenbruchteil siehst du den Aufblitz von Wilhelms Monokular."
  },
  AvgDialog_145523_Content_86 = {
    Text = "Unmittelbar danach entzündet sich der vierte Lichtring."
  },
  AvgDialog_145523_Content_87 = {
    Text = "Der feste Fels unter deinen Füßen stöhnt mit einem tiefen, schweren Grollen – ein Zittern, das nicht zu Stein gehört, sondern zu lebendigem Fleisch. Faint, kranke Lichtschimmer beginnen aus den brechenden Eisschichten darunter zu sickern."
  },
  AvgDialog_145523_Content_88 = {
    Text = "<Shake:...Was ist das?>"
  },
  AvgDialog_145523_Content_89 = {
    Text = "<Shake:Warum... entweicht meine Kraft...?>"
  },
  AvgDialog_145523_Content_9 = {
    Text = "Warte... diese Muster..."
  },
  AvgDialog_145523_Content_90 = {
    Text = "Das ist der Preis des Rituals, nach dem du so verzweifelt verlangt hast."
  },
  AvgDialog_145523_Content_91 = {
    Text = "Nachdem der Preis bezahlt wurde, was wird daraus werden?"
  },
  AvgDialog_145523_Content_92 = {
    Text = "Das Ritual entzieht der Opfergabe „alle“ Stärke, also vermute ich, es wird so sein wie vor der Begegnung mit dir – vielleicht sogar schwächer."
  },
  AvgDialog_145523_Content_93 = {
    Text = "So schwach wie ein kleiner Wurm, der sich in einem Apfel windet und bei der kleinsten Berührung zerbricht?"
  },
  AvgDialog_145523_Content_94 = {
    Text = "<BigShake:Du hast mich betrogen! Du elender Lügner!>"
  },
  AvgDialog_145523_Content_95 = {
    Text = "Ich habe dir versprochen, das Ritual vollständig durchzuführen, und du hast zugestimmt, <Italic:alle> Opfergaben herzugeben."
  },
  AvgDialog_145523_Content_96 = {
    Text = "Alles, was du in deinen Bauch geschlungen hast, die gesamte Lebenskraft dieses Berges, wird dem Altar dargebracht – geopfert dem Gott, der diese Formation erschaffen hat."
  },
  AvgDialog_145523_Content_97 = {
    Text = "Der fünfte Heiligenschein erhebt sich."
  },
  AvgDialog_145523_Content_98 = {
    Text = "Das Gestein unter den Füßen beginnt zu bersten und abzublättern, darunter kommt eine rohe, blasse, sich heftig zusammenziehende Schicht Fleisch zum Vorschein."
  },
  AvgDialog_145523_Content_99 = {
    Text = "Gewaltige Schneemassen brechen mit einem ohrenbetäubenden Donnern zusammen, und der Himmel wird Stück für Stück von einem unvorstellbaren Schatten verschluckt."
  },
  AvgDialog_145524_Content_1 = {
    Text = "Du … komm nicht näher!"
  },
  AvgDialog_145524_Content_10 = {
    Text = "<Change>Erinnerst du dich noch an deine Mission?"
  },
  AvgDialog_145524_Content_11 = {
    Text = "<Small:Vernichte... den Verräter... Ich muss...>"
  },
  AvgDialog_145524_Content_12 = {
    Text = "Das Chaos in Pollux' Augen verschwand allmählich und wich einer Leere – einer Leere, die nur von den Stimmen in seinem Kopf angetrieben werden konnte."
  },
  AvgDialog_145524_Content_13 = {
    Text = "Ja, stimmt, ich bin ein Verräter. Ich bin derjenige, der dich verraten und geflohen ist."
  },
  AvgDialog_145524_Content_14 = {
    Text = "Aber jetzt werde ich nicht mehr weggehen."
  },
  AvgDialog_145524_Content_15 = {
    Text = "<Shake:Verräter, Castor …>"
  },
  AvgDialog_145524_Content_16 = {
    Text = "Er war verwirrt, wollte gegen etwas ankämpfen, wollte an etwas festhalten, doch die Stimmen in seinem Kopf rangen unaufhörlich miteinander."
  },
  AvgDialog_145524_Content_17 = {
    Text = "Pollux, du bist uns die ganze Zeit gefolgt – du musst dem Wendigo begegnet sein."
  },
  AvgDialog_145524_Content_18 = {
    Text = "Was hast du in der Illusion des Wendigo gehört?"
  },
  AvgDialog_145524_Content_19 = {
    Text = "Pollux' Pupillen weiteten sich augenblicklich und zerstreuten sich dann langsam. Er versank in ein Gemurmel-artiges Nachsinnen."
  },
  AvgDialog_145524_Content_2 = {
    Text = "Pollux riss die Augen auf. Er verstand nicht, was dieser Wahnsinnige vor ihm sich dabei dachte."
  },
  AvgDialog_145524_Content_20 = {
    Text = "Ich hörte … jemanden, der mich rief …"
  },
  AvgDialog_145524_Content_21 = {
    Text = "Er sagte, wir könnten großartige Ritter werden."
  },
  AvgDialog_145524_Content_22 = {
    Text = "Wir ritten auf Pferden, überquerten Berge, überquerten Flüsse und Meere, erschlugen Drachen …"
  },
  AvgDialog_145524_Content_23 = {
    Text = "Und dann, dann, am Ende des Traums…"
  },
  AvgDialog_145524_Content_24 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_145524_Content_25 = {
    Text = "<BigShake:Nein, nein…!>"
  },
  AvgDialog_145524_Content_26 = {
    Text = "Es tut so weh, Juliette, <Shake:Hilf mir!, Hilf mir!…>"
  },
  AvgDialog_145524_Content_27 = {
    Text = "<Shake:Ich bin… der erhabene… der einzige… Heiliger Sohn… Hilf mir!…<Small:Ich kann nicht…>>"
  },
  AvgDialog_145524_Content_28 = {
    Text = "Ist schon gut… Du musst dich nicht erinnern."
  },
  AvgDialog_145524_Content_29 = {
    Text = "Das unerträgliche Leid — das will ich tragen. So wie früher, als wir klein waren."
  },
  AvgDialog_145524_Content_3 = {
    Text = "Auf Castors Gesicht war weder Ehrfurcht vor den Lehren noch Angst vor der Feindseligkeit zu sehen."
  },
  AvgDialog_145524_Content_30 = {
    Text = "Schließlich bin ich der große Bruder."
  },
  AvgDialog_145524_Content_31 = {
    Text = "Castor hielt Pollux in den Armen und beruhigte ihn mit einer sanften Stimme, wie man ein Kind in den Schlaf wiegt."
  },
  AvgDialog_145524_Content_32 = {
    Text = "Pollux' Atem verlangsamte sich, sein Gesicht ruhte an Castors Schulter, und seine Augenlider sanken langsam herab."
  },
  AvgDialog_145524_Content_33 = {
    Text = "<Shake:Castor…>"
  },
  AvgDialog_145524_Content_34 = {
    Text = "Ich bin es, ich bin Castor…"
  },
  AvgDialog_145524_Content_35 = {
    Text = "<Shake:Castor, Castor…>"
  },
  AvgDialog_145524_Content_36 = {
    Text = "<Shake:<Small:...Bruder?>>"
  },
  AvgDialog_145524_Content_37 = {
    Text = "Die trüben Pupillen klärten sich im selben Moment auf; Pollux' Stimme war so leise, dass der Wind sie Fast hätte davontragen können, und doch drang sie unfehlbar in Castors Ohren."
  },
  AvgDialog_145524_Content_38 = {
    Text = "Der Ruf, den er sich in seiner Vorstellung unzählige Male ausgemalt hatte, erklang endlich wieder an seinem Ohr."
  },
  AvgDialog_145524_Content_39 = {Text = "Ah—"},
  AvgDialog_145524_Content_4 = {
    Text = "Er trat einfach vor, über das Messer hinweg, über all die Hindernisse, die hätten sein sollen, aber es nicht mehr waren."
  },
  AvgDialog_145524_Content_40 = {
    Text = "Er wollte weinen, wollte schreien, wollte brüllen."
  },
  AvgDialog_145524_Content_41 = {
    Text = "Selbst wenn ihn in diesem Moment nur das endlose, weite Schneefeld umgab, wollte er es sinnlos in alle Welt hinausrufen: Sein kleiner Bruder war zurückgekehrt."
  },
  AvgDialog_145524_Content_42 = {
    Text = "Doch er sagte nichts, wie immer, wie damals, als Pollux ihn einen Holzklotz nannte und Caraboo ihn einen Trottel schimpfte."
  },
  AvgDialog_145524_Content_43 = {
    Text = "<Shake:Pollux…>"
  },
  AvgDialog_145524_Content_44 = {
    Text = "— In genau diesem Moment, hoch oben am Schneeberg — an einem noch höheren, unvorstellbar fernen Ort —"
  },
  AvgDialog_145524_Content_45 = {
    Text = "fiel ein richtender Blick herab."
  },
  AvgDialog_145524_Content_46 = {
    Text = "<Change>Ausschussware."
  },
  AvgDialog_145524_Content_47 = {
    Text = "Castor zog seinen Bruder heftig an sich —"
  },
  AvgDialog_145524_Content_48 = {
    Text = "Doch es half nichts. Das Licht erblühte aus Pollux' Brust."
  },
  AvgDialog_145524_Content_49 = {
    Text = "Das Licht durchbrach gerade die Brust der beiden, durchdrang Castors abgetragenen Umhang, durchdrang die Flügel, mit denen Castor sie beide umschloss —"
  },
  AvgDialog_145524_Content_5 = {
    Text = "Er schloss Pollux fest in seine Arme."
  },
  AvgDialog_145524_Content_50 = {
    Text = "Gleich reinweißen Ketten band es die beiden fest aneinander, ein Versprechen, von nun an niemals getrennt zu sein."
  },
  AvgDialog_145524_Content_51 = {
    Text = "Bruder … es tut mir leid …"
  },
  AvgDialog_145524_Content_52 = {
    Text = "Mit diesen letzten Worten lehnte Pollux sich an Castors Schulter und versank in tiefen Schlaf."
  },
  AvgDialog_145524_Content_53 = {
    Text = "So … ist es auch gut … wir werden nie mehr getrennt sein …"
  },
  AvgDialog_145524_Content_54 = {
    Text = "Das ist auch … ein kleiner Eigennutz von mir …"
  },
  AvgDialog_145524_Content_55 = {
    Text = "Er blickte noch einmal zum höheren Teil des Berges zurück und stellte sich vor, wie die einstigen Bergsteigerkameraden einander stützend den Gipfel erklommen."
  },
  AvgDialog_145524_Content_56 = {
    Text = "Eine Lüge war zu Ende, diese Reise gehörte nicht mehr ihm."
  },
  AvgDialog_145524_Content_57 = {
    Text = "Eine Lüge gegen eine andere Lüge eingetauscht …"
  },
  AvgDialog_145524_Content_58 = {
    Text = "Lebt wohl … alle miteinander … möge eure Reise … am Ende das gelobte Land erreichen …"
  },
  AvgDialog_145524_Content_59 = {
    Text = "Eine schwarze Feder löste sich von Castors Flügeln und wurde vom Schneewind in die Höhe gewirbelt."
  },
  AvgDialog_145524_Content_6 = {
    Text = "So wie einst im Fruchtwasser."
  },
  AvgDialog_145524_Content_60 = {
    Text = "Lass sie an unserer Stelle dorthin gelangen, zu jenem reinen Land ohne Schuld, das du dir ersehnst …"
  },
  AvgDialog_145524_Content_61 = {
    Text = "Ein schmaler Spalt öffnete sich unter den Füßen der beiden und verschluckte all die schwere Last langsam im Eis und Schnee des Berginneren."
  },
  AvgDialog_145524_Content_62 = {
    Text = "Gute Nacht, Pollux."
  },
  AvgDialog_145524_Content_63 = {
    Text = "Ihr erklommt neue Bergpfade und ordnetet die schwere Ausrüstung neu."
  },
  AvgDialog_145524_Content_64 = {
    Text = "Ein Schneewind wirbelte über euch hinweg, als ob er einen eigenen Willen besäße."
  },
  AvgDialog_145524_Content_65 = {Text = "Das ist..."},
  AvgDialog_145524_Content_66 = {
    Text = "Inmitten des Schneewinds sank eine pechschwarze Feder langsam herab."
  },
  AvgDialog_145524_Content_67 = {
    Text = "Du hebst die Hand, und sie schwebt genau in deine Handfläche hinein."
  },
  AvgDialog_145524_Content_68 = {
    Text = "Wie ein Segen aus der Ferne."
  },
  AvgDialog_145524_Content_69 = {
    Text = "Höhe -7000m-"
  },
  AvgDialog_145524_Content_7 = {
    Text = "Komm zurück, Pollux. So wie damals, als wir klein waren."
  },
  AvgDialog_145524_Content_8 = {
    Text = "Pollux' Kopf war voller Verwirrung, voller Unverständnis. Doch aus einem unbekannten Grund konnte er diese warme Umarmung nicht von sich stoßen."
  },
  AvgDialog_145524_Content_9 = {
    Text = "Eine strenge Scheltrede erklang plötzlich an seinem Ohr."
  },
  AvgDialog_145525_Content_1 = {
    Text = "In der Höhle kehrte eine seltsame Stille ein, und die noch erschütterten Anwesenden sahen sich gegenseitig an."
  },
  AvgDialog_145525_Content_10 = {
    Text = "Gerade gibt es in diesem Berg eine gewisse Präsenz jenseits der Göttin, die darauf aus ist, euch eure Wünsche zu stehlen."
  },
  AvgDialog_145525_Content_11 = {
    Text = "Hör auf, alle zu erschrecken, Caraboo."
  },
  AvgDialog_145525_Content_12 = {
    Text = "Ob ihr es glaubt oder nicht, bleibt euch überlassen. Die Schneeberg-Göttin kann es spüren — es ist in der Nähe unserer Gruppe und folgt uns dicht auf den Fersen…"
  },
  AvgDialog_145525_Content_13 = {
    Text = "Ihr könnt aus ihrem Tonfall nicht erkennen, ob sie nur so tut, als würde sie etwas spüren, oder ob sie tatsächlich etwas wahrgenommen hat."
  },
  AvgDialog_145525_Content_14 = {
    Text = "Wind und Schnee legen sich allmählich."
  },
  AvgDialog_145525_Content_15 = {
    Text = "In dieser schweren Stille brecht ihr erneut auf."
  },
  AvgDialog_145525_Content_2 = {
    Text = "Seltsam, ich habe Bergsteigerteams schon mehrfach auf diese Höhe begleitet, aber so etwas erlebe ich zum ersten Mal…"
  },
  AvgDialog_145525_Content_3 = {
    Text = "Das zeigt, dass die Gefahren auf diesem Schneeberg nicht nur die minus dreißig Grad Kälte und der Sauerstoffmangel in großer Höhe sind."
  },
  AvgDialog_145525_Content_4 = {
    Text = "Caraboo senkte die Stimme und schilderte mit einem Tonfall, der einem den Rücken frösteln ließ, langsam die Lage."
  },
  AvgDialog_145525_Content_5 = {
    Text = "Die Schneeberg-Göttin existiert wirklich."
  },
  AvgDialog_145525_Content_6 = {
    Text = "<Red:Die Berggöttin heißt euch nicht willkommen. Sie heißt jene nicht willkommen, denen es an Hingabe mangelt.>"
  },
  AvgDialog_145525_Content_7 = {
    Text = "Die Luft erstarrte."
  },
  AvgDialog_145525_Content_8 = {
    Text = "Ich hab euch nur auf den Arm genommen! Ihr glaubt das doch nicht wirklich!"
  },
  AvgDialog_145525_Content_9 = {
    Text = "Ich bin die gütigste aller Schneeberg-Göttinnen — mit meinem Segen wird euch der Berg empfangen und ihr werdet den Gipfel erreichen."
  },
  AvgDialog_145526_Content_1 = {
    Text = "Tag des Ausflugs"
  },
  AvgDialog_145526_Content_10 = {
    Text = "Wir haben gerade nur einen Angriff abgewehrt, aber seine Offensive wird nicht aufhören."
  },
  AvgDialog_145526_Content_11 = {
    Text = "In einer so gefährlichen Umgebung wie den Bergen kann es unvermeidlich sein, dass man Momente der Zerbrechlichkeit und Schwäche zeigt…"
  },
  AvgDialog_145526_Content_12 = {
    Text = "In solchen Momenten lässt man sich am besten täuschen."
  },
  AvgDialog_145526_Content_13 = {
    Text = "Caraboo zieht von irgendwoher einen Apfel hervor, beißt mit einem knackenden Geräusch hinein und trägt dabei das Gesicht von jemandem, der sagt: „Dieser Satz kam nicht von mir“."
  },
  AvgDialog_145526_Content_14 = {
    Text = "… Da hast du nicht ganz Unrecht."
  },
  AvgDialog_145526_Content_15 = {
    Text = "Jedenfalls müssen wir es finden und dann fangen."
  },
  AvgDialog_145526_Content_16 = {
    Text = "Aber sie hinterlassen keine Spuren im Schnee — wie sollen wir da…"
  },
  AvgDialog_145526_Content_17 = {
    Text = "Überlass das mir. Ich bin doch am besten darin, mit Betrügern umzugehen, oder nicht?"
  },
  AvgDialog_145526_Content_18 = {
    Text = "Schau, sie kommen bald."
  },
  AvgDialog_145526_Content_19 = {
    Text = "Caraboo zeigt auf den letzten Blindenhund, den ihr noch habt. Er hat sich tief geduckt und wimmert leise."
  },
  AvgDialog_145526_Content_2 = {Text = "Wendigo."},
  AvgDialog_145526_Content_20 = {
    Text = "Keiner von euch bewegt sich, und keiner sagt ein Wort."
  },
  AvgDialog_145526_Content_21 = {
    Text = "Sie wirft dir den angebissenen Apfel zu."
  },
  AvgDialog_145526_Content_22 = {
    Text = "Im Schnitt verbirgt sich ein kleiner Zettel: Was auch immer ich als Nächstes sage – glaub mir kein Wort."
  },
  AvgDialog_145526_Content_23 = {
    Text = "Caraboo wird still. Sie schließt die Augen und öffnet sie dann wieder."
  },
  AvgDialog_145526_Content_24 = {
    Text = "In diesem Moment verändert sich ihr Blick. Benommen, ängstlich, entrückt – komplexe Gefühle spiegeln sich in ihren kleinen Augen wider."
  },
  AvgDialog_145526_Content_25 = {
    Text = "<Shake:Tante Rosa, bist du das?>"
  },
  AvgDialog_145526_Content_26 = {
    Text = "<Shake:Backen Sie etwa wieder Apfelkuchen? Ich rieche den Duft schon.>"
  },
  AvgDialog_145526_Content_27 = {
    Text = "<Shake:Tante Rosa, ich werde mich nie wieder über den dicken Teig des Apfelkuchens beschweren. Seitdem habe ich keinen so köstlichen Apfelkuchen mehr gegessen. Ich vermisse diesen herrlichen Duft.>"
  },
  AvgDialog_145526_Content_28 = {
    Text = "<Shake:Tante Rosa. Ich komme jetzt zu Ihnen. Warten Sie auf mich.>"
  },
  AvgDialog_145526_Content_29 = {
    Text = "Caraboo taumelt vorwärts."
  },
  AvgDialog_145526_Content_3 = {
    Text = "Wilhelm sprach den Namen Silbe für Silbe aus."
  },
  AvgDialog_145526_Content_30 = {
    Text = "Im Schnee, hinter Caraboo, erheben sich unvermittelt zwei Schneehaufen von anderthalb Mannshöhe."
  },
  AvgDialog_145526_Content_31 = {
    Text = "Es stürzt sich auf Caraboo. In dem Moment, als es auf sie zuspringt, duckt sie sich tief."
  },
  AvgDialog_145526_Content_32 = {
    Text = "<Big:Wilhelm, bereit!!>"
  },
  AvgDialog_145526_Content_4 = {
    Text = "<Italic:„Seine Füße sind aus Feuer gegossen — wenn es läuft, brennt der Schnee unter seinen Füßen.“>"
  },
  AvgDialog_145526_Content_5 = {
    Text = "In „Aufzeichnungen aus dem Norden\", Band 7, steht geschrieben: <Italic:Wer in der Winternacht dem Flüstern lauscht, darf niemals antworten.>"
  },
  AvgDialog_145526_Content_6 = {
    Text = "<Italic:Antwortest du einmal, merkt es sich deinen Namen; antwortest du zweimal, erkennt es deinen Schatten; antwortest du ein drittes Mal — bist du es selbst.>"
  },
  AvgDialog_145526_Content_7 = {
    Text = "Können wir ihm nicht ausweichen?"
  },
  AvgDialog_145526_Content_8 = {
    Text = "Nutzlos — solange Wind und Schnee herrschen, ist das Wendigo-Territorium."
  },
  AvgDialog_145526_Content_9 = {
    Text = "Sie waren einst Menschen. Durch den Verzehr ihrer eigenen Art verwandelten sie sich, und seitdem verfaulen ihre Lippen und sie leiden unter ewigem Hunger — selbst ein ganzer Wald würde sie nicht sättigen."
  },
  AvgDialog_145527_Content_1 = {
    Text = "Die Rucksäcke"
  },
  AvgDialog_145527_Content_10 = {Text = "Nein."},
  AvgDialog_145527_Content_100 = {
    Text = "Er hielt seine eigenen Zweige an den Ofen und entzündete sie, dann trat er zu euch."
  },
  AvgDialog_145527_Content_101 = {
    Text = "Das Feuer wanderte von Zweig zu Zweig, und das Flackern der Flammen beleuchtete nacheinander jedes emporgewandte Gesicht."
  },
  AvgDialog_145527_Content_102 = {
    Text = "Als ob in der Stille ein tiefes Rezitieren, Glockenläuten und Trommeln aus der Nähe herüberdrang."
  },
  AvgDialog_145527_Content_103 = {
    Text = "Ruft laut Lha Gyalo, und werft sie dann ins Feuer."
  },
  AvgDialog_145527_Content_104 = {
    Text = "Eine raue, aber kraftvolle Stimme hallte im dünnen Nachhall durch die Luft, und mit dem Ruf fielen die Zweige einer nach dem anderen ins Feuer."
  },
  AvgDialog_145527_Content_105 = {
    Text = "Wir danken dem Berggeist, der unsere Unehrerbietigkeit beim Betreten seines heiligen Gebietes verzeiht."
  },
  AvgDialog_145527_Content_106 = {
    Text = "Kiefern- und Zypressenzweige knistern im Feuer und schicken grauen Rauch gerade nach oben, bevor er von den starken Winden zerrissen wird."
  },
  AvgDialog_145527_Content_107 = {
    Text = "Und du witterst darin einen Hauch von Unheil."
  },
  AvgDialog_145527_Content_108 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_145527_Content_109 = {
    Text = "Gut, die Gefahren dieser Bergbesteigung und die Notfallpläne wurden nun allen erläutert."
  },
  AvgDialog_145527_Content_11 = {
    Text = "Hey!!! Warum nicht!!!"
  },
  AvgDialog_145527_Content_110 = {
    Text = "In der vergangenen Woche haben sich alle daran gewöhnt, sich mit Handschuhen, Bergschuhen und Schneebrille zu bewegen, und haben den Umgang mit Seilen und Eisschrauben geübt und erlernt."
  },
  AvgDialog_145527_Content_111 = {
    Text = "Basierend auf den engmaschigen Beobachtungen der letzten Tage bieten die nächsten 5–7 Tage das günstigste Wetterfenster für die Besteigung – ein guter Zeitpunkt zum Aufbruch."
  },
  AvgDialog_145527_Content_112 = {
    Text = "Bitte überprüft eure mitgeführten Routenkarten, Lebensmittel, Brennstoff, Sauerstoffflaschen, Verbandskästen und sonstige Vorräte."
  },
  AvgDialog_145527_Content_113 = {
    Text = "Nochmals zur Betonung: Während der Besteigung müsst ihr <Yellow:den Anweisungen des Führers vollständig Folge leisten>, und abgesehen von Mitgliedern, die vorzeitig umkehren, ist es allen anderen <Yellow:streng untersagt, die Gruppe zu verlassen>."
  },
  AvgDialog_145527_Content_114 = {
    Text = "Wenn alle bereit sind, dann brechen wir auf!"
  },
  AvgDialog_145527_Content_115 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_145527_Content_116 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_145527_Content_117 = {
    Text = "Ihr seid kaum einen halben Tag durch das Gebirge gezogen, als das klare Wetter plötzlich von dichten Wolken verdunkelt wird."
  },
  AvgDialog_145527_Content_118 = {
    Text = "Wind und Schnee verstärken sich abrupt; selbst die Gebirgskämme sind kaum noch zu erkennen, und die Schlittenhunde winseln und wollen nicht weitergehen."
  },
  AvgDialog_145527_Content_119 = {
    Text = "Seltsam, nach unseren Messergebnissen hätte so schnell kein anomales Wetter auftreten dürfen."
  },
  AvgDialog_145527_Content_12 = {
    Text = "Die beiden sind doch auch neu dazugekommen, oder?"
  },
  AvgDialog_145527_Content_120 = {
    Text = "Habt ihr schon einmal eine ähnliche Situation erlebt?"
  },
  AvgDialog_145527_Content_121 = {
    Text = "Niemals. Selbst wenn die Messungen abweichen, tritt das normalerweise erst drei Tage nach dem prognostizierten Ergebnis auf."
  },
  AvgDialog_145527_Content_122 = {
    Text = "<Shake:Unnatürlicher Schneewind … es ist, als ob … <Yellow:der Berg uns abweist>.>"
  },
  AvgDialog_145527_Content_123 = {
    Text = "Unmöglich! Wie kann das sein, wo ich, die große Berggöttin, doch hier bin?"
  },
  AvgDialog_145527_Content_124 = {
    Text = "Macht euch nicht zu viele Sorgen – beim Abstieg trifft man manchmal auch auf unerwartete Schneestürme."
  },
  AvgDialog_145527_Content_125 = {
    Text = "In der Nähe gibt es eine Notunterkunft, dort sind sogar noch ein paar Vorräte. Wir ruhen uns dort eine Weile aus, warten bis der Schneesturm nachlässt, und brechen dann neu ausgerüstet wieder auf."
  },
  AvgDialog_145527_Content_126 = {
    Text = "Was gibt es da noch zu sagen – schnell, lasst uns gehen!"
  },
  AvgDialog_145527_Content_13 = {
    Text = "Caraboo streckte unwillig die Hand aus und zeigte auf dich und Wilhelm."
  },
  AvgDialog_145527_Content_14 = {
    Text = "Ganz einfach. Die beiden sind Erwachsene und können auf sich selbst aufpassen."
  },
  AvgDialog_145527_Content_15 = {
    Text = "Bergsteigen ist kein Kinderspiel, kleines Mädchen."
  },
  AvgDialog_145527_Content_16 = {
    Text = "Hier kannst du behaupten, du seist ein Vater, eine Mutter, die Schneeberg-Göttin oder der Oberste Wille – das ist alles möglich."
  },
  AvgDialog_145527_Content_17 = {
    Text = "Doch sobald man die Gipfel über fünftausend Meter erreicht, werden alle Lügen im Schnee, Wind und der Höhenkrankheit schonungslos entlarvt."
  },
  AvgDialog_145527_Content_18 = {
    Text = "Aber ich habe Geld, ich habe <Italic:JEDE MENGE> davon!"
  },
  AvgDialog_145527_Content_19 = {
    Text = "Du bist doch ein Kind, wie viel kannst du schon——"
  },
  AvgDialog_145527_Content_2 = {
    Text = "Unter Narakas Anleitung stellt ihr euch gegenseitig vor – du und die Mitglieder des Kletterteams."
  },
  AvgDialog_145527_Content_20 = {Text = "<Big:!>"},
  AvgDialog_145527_Content_21 = {
    Text = "Narakas Worte brachen abrupt ab."
  },
  AvgDialog_145527_Content_22 = {
    Text = "Das Mädchen zieht einen schweren Stoffbeutel hervor, greift eine große Handvoll Goldmünzen heraus und lässt sie klingelnd zurück in den Beutel regnen. Sie behält nur eine einzige, die sie zwischen ihren Fingern dreht und wendet."
  },
  AvgDialog_145527_Content_23 = {
    Text = "Ich habe doch gesagt, ich bin eine Fee – wie sollte mir an solchen Äußeren Besitztümern wie Geld je mangeln!"
  },
  AvgDialog_145527_Content_24 = {
    Text = "<Small:Aber hast du nicht gerade gesagt, du wärst eine Göttin...?>"
  },
  AvgDialog_145527_Content_25 = {
    Text = "Egal, wen kümmert's!"
  },
  AvgDialog_145527_Content_26 = {
    Text = "Caraboo warf die Goldmünze beiläufig weg, Naraka streckte sich hastig danach aus, stolperte und wäre beinahe in den Schnee gefallen."
  },
  AvgDialog_145527_Content_27 = {
    Text = "Er hielt die Münze in den Händen, biss darauf und konnte seine Freude kaum verbergen."
  },
  AvgDialog_145527_Content_28 = {
    Text = "<Shake:Das ist echt...!>"
  },
  AvgDialog_145527_Content_29 = {
    Text = "Hmph, Goldmünzen aus den Händen einer Fee – wie könnten die falsch sein?"
  },
  AvgDialog_145527_Content_3 = {
    Text = "Tinct, eine geheimnisvolle und distanzierte Sängerin, die nach eigenen Angaben ihre Schwester suchen möchte."
  },
  AvgDialog_145527_Content_30 = {
    Text = "Also, nehmt ihr mich jetzt mit in die Bergsteigergruppe?"
  },
  AvgDialog_145527_Content_31 = {
    Text = "<Shake:<Small:Nun ja, ein Kind in die Bergsteigergruppe aufzunehmen wäre etwas unverantwortlich, was deine Sicherheit betrifft …>>"
  },
  AvgDialog_145527_Content_32 = {
    Text = "<BigShake:Hm?>"
  },
  AvgDialog_145527_Content_33 = {
    Text = "Aber andererseits verfügt unsere Bergsteigergruppe über reichlich Erfahrung und ausreichend Vorräte – dich zu beschützen ist für uns <Big:mehr als genug>!"
  },
  AvgDialog_145527_Content_34 = {
    Text = "Allerdings sei gewarnt: Solltest du dich entscheiden, auf halbem Weg umzukehren, lassen wir dir genug Ausrüstung für den Abstieg da – aber die Führergebühr wird <Big:nicht zurückerstattet>."
  },
  AvgDialog_145527_Content_35 = {
    Text = "Ja, ja, würde sich eine Fee denn wegen so ein paar Münzen mit dir streiten?"
  },
  AvgDialog_145527_Content_36 = {
    Text = "<Shake:<Small:Wie seltsam – hat sie nicht gerade noch Straßenkunst gemacht und um Geld gebettelt?>>"
  },
  AvgDialog_145527_Content_37 = {
    Text = "Denk nicht, ich höre das nicht!"
  },
  AvgDialog_145527_Content_38 = {
    Text = "Ich habe es doch gesagt – das war Verehrung! Eine Göttin empfängt die Aufrichtigkeit aller, verstehst du das nicht?"
  },
  AvgDialog_145527_Content_39 = {
    Text = "<Shake:<Small:Wenn es nicht nötig ist, ist das Gehör auch wirklich gut…>>"
  },
  AvgDialog_145527_Content_4 = {
    Text = "Evelyn, eine Archäologin, die selbst in dieser postapokalyptischen Welt für wissenschaftliche Forschung gekommen ist."
  },
  AvgDialog_145527_Content_40 = {
    Text = "<BigShake:DAS HÖRE ICH AUCH!>"
  },
  AvgDialog_145527_Content_41 = {
    Text = "Eure Gruppe sichtet die Vorräte, und das Gespräch kommt bald auf das Ritual."
  },
  AvgDialog_145527_Content_42 = {
    Text = "Glaubt ihr wirklich, dass es auf dem Gipfel eine Göttin gibt, die jeden Wunsch erfüllen kann?"
  },
  AvgDialog_145527_Content_43 = {
    Text = "Wilhelm fragt beiläufig, als wäre es ihm nicht wichtig."
  },
  AvgDialog_145527_Content_44 = {
    Text = "Zumindest glauben es alle Einheimischen. Wegen der letzten Bergsteigergruppe."
  },
  AvgDialog_145527_Content_45 = {
    Text = "Die letzte Bergsteigergruppe?"
  },
  AvgDialog_145527_Content_46 = {
    Text = "Ja. Seit die Gerüchte über die Berggöttin die Runde machten, ist der Nordkontinent zu einem Land geworden, das ganz von der Jagd nach Wünschen beherrscht wird, mit einer ganzen Gesellschaft, die sich um den Aufstieg dreht. Dieses Kletterteam war das disziplinierteste und bestausgebildete aller bisherigen Teams; sie hatten die besten Chancen, den Gipfel zu erreichen."
  },
  AvgDialog_145527_Content_47 = {
    Text = "Als sie aufbrachen, waren sie insgesamt sieben Personen. Doch während des Aufstiegs starben die Mitglieder einer nach dem anderen."
  },
  AvgDialog_145527_Content_48 = {
    Text = "Einer verließ mitten in der Nacht das Zelt und lief barfuß in den Schneesturm; ein anderer schnitt sein Sicherungsseil durch und sprang von der Eisklippe;"
  },
  AvgDialog_145527_Content_49 = {
    Text = "Wieder ein anderer verschwand für mehrere Tage, wurde schließlich aber erfroren vor der Gruppe gefunden —"
  },
  AvgDialog_145527_Content_5 = {
    Text = "Während ihr gerade den Plan für den Aufbruch am nächsten Tag bespracht, tauchte plötzlich ein weißer Kopf am Eingang des Lagers auf."
  },
  AvgDialog_145527_Content_50 = {
    Text = "Als hätte er nach seinem Tod den Aufstieg einfach fortgesetzt."
  },
  AvgDialog_145527_Content_51 = {
    Text = "Die Bewegungen aller beim Inventarisieren der Vorräte verlangsamten sich wie auf Kommando."
  },
  AvgDialog_145527_Content_52 = {
    Text = "Am Ende kehrte nur eine einzige Person lebend zum Fuß des Berges zurück."
  },
  AvgDialog_145527_Content_53 = {
    Text = "Allerdings kann man auch nicht sagen, dass er wirklich „lebend zurückgekehrt\" ist."
  },
  AvgDialog_145527_Content_54 = {
    Text = "Was meinst du?"
  },
  AvgDialog_145527_Content_55 = {
    Text = "Alle zehn seiner Finger waren erfroren und verfault, seine Ohren mit Schnee vermischt mit Blut verstopft. Egal was man ihn fragte, er wiederholte immer wieder dieselben wenigen Sätze."
  },
  AvgDialog_145527_Content_56 = {
    Text = "Naraka senkte die Stimme und ahmte den traumwandlerischen Tonfall des Überlebenden nach."
  },
  AvgDialog_145527_Content_57 = {
    Text = "<Shake:„Die Legende ist wahr. Der Wunsch auf dem Gipfel ist wahr.\">"
  },
  AvgDialog_145527_Content_58 = {
    Text = "<Shake:<Red:„Haltet euch die Ohren zu, hört nicht hin.\">>"
  },
  AvgDialog_145527_Content_59 = {
    Text = "<Shake:„Wer den Gesang hört, wird verführt, wird verschlungen … und steigt dann in den Himmel auf und wird zum <Red:Mond>.\">"
  },
  AvgDialog_145527_Content_6 = {
    Text = "Sag mal~ Ist das hier Narakas Bergsteigergruppe?"
  },
  AvgDialog_145527_Content_60 = {
    Text = "Und was dann?"
  },
  AvgDialog_145527_Content_61 = {
    Text = "Später dann……"
  },
  AvgDialog_145527_Content_62 = {
    Text = "Naraka zog einen seltsamen, zweideutigen Mundwinkel hoch."
  },
  AvgDialog_145527_Content_63 = {
    Text = "Die Einheimischen glaubten, sie hätten die Berggöttin entweiht. Aus Angst, diese Fremden könnten den Zorn der Göttin auf ihre Dörfer lenken…"
  },
  AvgDialog_145527_Content_64 = {
    Text = "Also wählten sie eine mondlose, stürmische Nacht und warfen ihn in eine bodenlose Eisspalte."
  },
  AvgDialog_145527_Content_65 = {
    Text = "Das ist das Ende der Geschichte?"
  },
  AvgDialog_145527_Content_66 = {Text = "Nein."},
  AvgDialog_145527_Content_67 = {
    Text = "Von da an hörten Menschen, die bei Vollmond an jener Eisspalte vorbeikamen, noch immer jemanden von unten singen."
  },
  AvgDialog_145527_Content_68 = {
    Text = "So wusste jeder: Er hatte die Wahrheit gesagt. Auf dem Berg musste irgendetwas existieren."
  },
  AvgDialog_145527_Content_69 = {
    Text = "Naraka senkte erneut den Kopf und rollte das Seil Schlaufe für Schlaufe in die Rucksäcke, als hätte er gerade nur von einer unbedeutenden alten Geschichte gesprochen."
  },
  AvgDialog_145527_Content_7 = {
    Text = "Sucht ihr mich?"
  },
  AvgDialog_145527_Content_70 = {
    Text = "In der kurzen Stille war nur der Wind zu hören, der über das Zelt strich und ein langes, dumpfes Stöhnen erzeugte."
  },
  AvgDialog_145527_Content_71 = {
    Text = "Ich habe auch gehört, dass sie auf dem Aufstieg den Gesang der Sirenen vernommen haben."
  },
  AvgDialog_145527_Content_72 = {
    Text = "Du redest schon wieder Unsinn – Sirenen sind Meeresungeheuer, wie sollten die auf einem Berg auftauchen?"
  },
  AvgDialog_145527_Content_73 = {
    Text = "Caraboo schürzte unzufrieden die Lippen und stieß ein leises Schnauben aus."
  },
  AvgDialog_145527_Content_74 = {
    Text = "Im Meer gibt es singende Monster – warum sollte es in den Bergen keine geben?"
  },
  AvgDialog_145527_Content_75 = {
    Text = "Ob du es glaubst oder nicht, bleibt dir überlassen. Wenn du den Gesang hörst, denk daran, dir die Ohren zuzuhalten."
  },
  AvgDialog_145527_Content_76 = {
    Text = "Als du noch weiter nachfragen wolltest, bemerktest du, dass Caraboo sich bereits umgedreht und die Hütte betreten hatte und offensichtlich nicht mehr an der Diskussion teilnehmen wollte."
  },
  AvgDialog_145527_Content_77 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_145527_Content_78 = {
    Text = "Sieben Tage später"
  },
  AvgDialog_145527_Content_79 = {
    Text = "Das heutige Training ist hiermit beendet – morgen ist der offizielle Besteigungstag."
  },
  AvgDialog_145527_Content_8 = {
    Text = "Hehe, ich habe gehört, du bist der beste Bergführer des gesamten Sherpa-Volkes!"
  },
  AvgDialog_145527_Content_80 = {
    Text = "Caraboo trat plötzlich vor und hielt Naraka auf, der gerade gehen wollte."
  },
  AvgDialog_145527_Content_81 = {
    Text = "Wird <Yellow:das Lhasang-Ritual> nicht abgehalten?"
  },
  AvgDialog_145527_Content_82 = {
    Text = "Das Lhasang-Ritual – was ist das?"
  },
  AvgDialog_145527_Content_83 = {
    Text = "Vor jeder Besteigung führen zehn von zehn Sherpa dieses Gebet durch. Hast du denn gar keinen Respekt vor der Gottheit?"
  },
  AvgDialog_145527_Content_84 = {
    Text = "Naraka schlug sich gegen die Stirn."
  },
  AvgDialog_145527_Content_85 = {
    Text = "<Yellow:Ach, bei all dem Trubel ist es mir entfallen.>"
  },
  AvgDialog_145527_Content_86 = {
    Text = "Wie kann man so etwas vergessen?"
  },
  AvgDialog_145527_Content_87 = {
    Text = "Kein Problem, morgen früh hole ich schnell eine vereinfachte Version nach."
  },
  AvgDialog_145527_Content_88 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_145527_Content_89 = {
    Text = "Du bewegst deine schmerzenden Schultern und öffnest die Tür – im Flur hängt bereits ein zarter Rauchschleier."
  },
  AvgDialog_145527_Content_9 = {
    Text = "Beim Segen der Schneeberg-Göttin, kannst du mich mitnehmen auf die Bergtour?"
  },
  AvgDialog_145527_Content_90 = {
    Text = "Wilhelm steht ein paar Schritte entfernt vor einem Kupferspiegel und glättet die Falten an seinem Kragen."
  },
  AvgDialog_145527_Content_91 = {
    Text = "Guten Morgen, Hüter."
  },
  AvgDialog_145527_Content_92 = {
    Text = "Du schnupperst in der Luft. Sie trägt den Duft von brennendem Holz und Kräutern, mit einem frischen, eisigen Hauch darunter."
  },
  AvgDialog_145527_Content_93 = {
    Text = "Als die große Tür aufgeht, strömen Kälte und dichter Rauchduft zugleich herein."
  },
  AvgDialog_145527_Content_94 = {
    Text = "Auf dem freien Platz im Hof brennt ein kleiner Sang-Ofen. Blauweißer Rauch steigt aus Kiefernzweigen und Kräutern auf und klettert schnurgerade in den graublau en Himmel."
  },
  AvgDialog_145527_Content_95 = {
    Text = "Die Sherpa betrachten Berggipfel als Götter, und im Mount Everest soll gar die Mutter der Welt wohnen."
  },
  AvgDialog_145527_Content_96 = {
    Text = "Vor der ersten offiziellen Besteigung errichten die Sherpa einen Altar, hissen Gebetsfahnen, rezitieren Sutren und vollziehen am Altar das „Weihrauchopfer\", damit der Rauch die Gaben und Gebete zu den Göttern trägt."
  },
  AvgDialog_145527_Content_97 = {
    Text = "Das Segensritual ist recht aufwendig – eine offizielle Zeremonie kann sogar drei bis vier Stunden dauern."
  },
  AvgDialog_145527_Content_98 = {
    Text = "Naraka nahm ein Bündel Kiefernzweige aus einem Stoffbeutel und verteilte sie an jeden."
  },
  AvgDialog_145527_Content_99 = {
    Text = "Hoch damit, zusammenhalten."
  },
  AvgDialog_145528_Content_1 = {
    Text = "Du wirfst dich auf ihn und umklammerst Castors Taille von hinten fest. Castor kämpft noch immer, seine Stimmbänder schreien im Schneesturm fast bis zum Zerreißen."
  },
  AvgDialog_145528_Content_10 = {
    Text = "Evelyn kam Schritt für Schritt näher. Sie kniete sich hin und sah dem Jungen, den Du und Wilhelm gemeinsam in den Schnee gedrückt hattet, direkt in die Augen."
  },
  AvgDialog_145528_Content_11 = {
    Text = "Castor, hör mir zu. Auch ich glaubte einst, der Wendigo sei ein Wesen, das nur in Legenden existiert."
  },
  AvgDialog_145528_Content_12 = {
    Text = "Aber gerade eben… habe ich es gehört."
  },
  AvgDialog_145528_Content_13 = {
    Text = "Ich hörte… meinen Mann, der mich rief."
  },
  AvgDialog_145528_Content_14 = {
    Text = "Seit dem Tag, an dem er verschwand, höre ich jeden Tag einen solchen Ruf, aber noch nie war er so klar, so wahr…"
  },
  AvgDialog_145528_Content_15 = {
    Text = "Evelyns Stimme wird für einen Moment leicht heiser."
  },
  AvgDialog_145528_Content_16 = {
    Text = "<Shake:Aber Castor… weißt du…>"
  },
  AvgDialog_145528_Content_17 = {
    Text = "Seit mein Mann auf dem Schneeberg verschwunden ist, sind bereits über neunzig Tage vergangen — die beste Zeit für eine Rettung ist längst verstrichen."
  },
  AvgDialog_145528_Content_18 = {
    Text = "Im günstigsten Fall werde ich seine Gebeine irgendwo auf einem Bergpfad finden."
  },
  AvgDialog_145528_Content_19 = {
    Text = "Er wird nicht am Leben sein… hier. Dein Bruder erst recht nicht."
  },
  AvgDialog_145528_Content_2 = {
    Text = "Castor, das ist er nicht."
  },
  AvgDialog_145528_Content_20 = {
    Text = "Wir müssen weiter nach oben, bis ans Ende des Berges."
  },
  AvgDialog_145528_Content_21 = {
    Text = "Das ist unsere einzige Chance auf ein Wiedersehen mit ihnen."
  },
  AvgDialog_145528_Content_22 = {
    Text = "Unter Evelyns beruhigenden Worten wurde Castor allmählich ruhiger."
  },
  AvgDialog_145528_Content_23 = {
    Text = "Du hast recht… auf dem Schneeberg gibt es keine Isolierzellen… er ist nicht an einem solchen Ort."
  },
  AvgDialog_145528_Content_24 = {
    Text = "Ich werde durchhalten… bis zum Wiedersehen mit ihm."
  },
  AvgDialog_145528_Content_25 = {
    Text = "Hinter euch klopfte jemand mit einem Eispickel zweimal fest auf den Felsen."
  },
  AvgDialog_145528_Content_26 = {
    Text = "Wenn sich alle wieder beruhigt haben, müssen wir uns auf die eigentliche Bedrohung vorbereiten."
  },
  AvgDialog_145528_Content_27 = {
    Text = "<Yellow:Wendigo>."
  },
  AvgDialog_145528_Content_3 = {
    Text = "<Shake:Woher weißt du, dass er es nicht ist?! Du kennst ihn doch gar nicht!>"
  },
  AvgDialog_145528_Content_4 = {
    Text = "Keiner von euch kennt ihn! Nur ich kenne ihn, ich kenne seine Stimme!! Ich bin es, der ihn dort zurückgelassen hat!"
  },
  AvgDialog_145528_Content_5 = {
    Text = "Es ist das erste Mal, dass er Wilhelm gegenüber die Stimme erhebt. Dann erschrickt er selbst über seine eigene Stimme."
  },
  AvgDialog_145528_Content_6 = {
    Text = "Castor, beruhige dich, das ist ein <Yellow:Wendigo>."
  },
  AvgDialog_145528_Content_7 = {
    Text = "Der Wendigo, das Bergmonster… gräbt den tiefsten Schatten in deinem Herzen aus…"
  },
  AvgDialog_145528_Content_8 = {
    Text = "Dann leiht es sich die Stimme der Person, die du vermisst, und verführt Verlorene dazu, in seine Falle zu tappen."
  },
  AvgDialog_145528_Content_9 = {
    Text = "<Shake:Nein, wer gibt dir das Recht——>"
  },
  AvgDialog_145529_Content_1 = {
    Text = "Ein weiterer Frühling"
  },
  AvgDialog_145529_Content_10 = {
    Text = "<Shake:Dieser Ort … wo bin ich?>"
  },
  AvgDialog_145529_Content_100 = {
    Text = "Ein ruhiges Leben, liebevolle Älteste —"
  },
  AvgDialog_145529_Content_101 = {
    Text = "Sogar jenes kleine Kaninchen."
  },
  AvgDialog_145529_Content_102 = {
    Text = "Der Feldhase drehte sich um, seine zwei runden Augen trafen ihren Blick."
  },
  AvgDialog_145529_Content_103 = {
    Text = "Dann wandte er sich ab, stieß sich mit den Hinterläufen vom Boden ab und verschwand in seinem Erdbau."
  },
  AvgDialog_145529_Content_11 = {
    Text = "Ausgehend von Caraboos letzten Worten befinden wir uns jetzt in der Richtige Position im Bauch des Berges."
  },
  AvgDialog_145529_Content_12 = {
    Text = "Das Dringlichste ist, einen Weg zu Entkommen zu finden."
  },
  AvgDialog_145529_Content_13 = {
    Text = "Ich war auch noch nie hier, ich fürchte, ich kann euch nicht als Führer dienen."
  },
  AvgDialog_145529_Content_14 = {
    Text = "Keine Sorge, wir haben schon weit schwierigere Momente erlebt."
  },
  AvgDialog_145529_Content_15 = {
    Text = "%player%, was hast du da in der Hand?"
  },
  AvgDialog_145529_Content_16 = {
    Text = "Oh, das ist … Arachnes Faden …"
  },
  AvgDialog_145529_Content_17 = {
    Text = "Irgendwann hat sich dieser Faden still und leise um deinen kleinen Finger gewickelt."
  },
  AvgDialog_145529_Content_18 = {
    Text = "Der Faden, der zuvor in ruhiger Wärme verharrte, erstrahlt nun in einem betörenden, fließenden Glanz, während sein Ende sich ganz natürlich in die Dunkelheit der Ferne erstreckt."
  },
  AvgDialog_145529_Content_19 = {
    Text = "Ist das die Führung des Schicksals? Folge ihm und schau, wohin er führt."
  },
  AvgDialog_145529_Content_2 = {
    Text = "Dunkelheit. Endlose Dunkelheit."
  },
  AvgDialog_145529_Content_20 = {
    Text = "Caraboo folgte dem Faden, ohne zu wissen, wie lange sie schon voranschritt. Am Ende des Fadens erschien ein Lichtschimmer."
  },
  AvgDialog_145529_Content_21 = {
    Text = "Licht … ?"
  },
  AvgDialog_145529_Content_22 = {
    Text = "Licht und Schatten wandelten sich plötzlich."
  },
  AvgDialog_145529_Content_23 = {
    Text = "Was ist das hier...?"
  },
  AvgDialog_145529_Content_24 = {
    Text = "Hey, Caraboo, langsamer!"
  },
  AvgDialog_145529_Content_25 = {
    Text = "Schau, Tante Rosa, dort sind Hasen!"
  },
  AvgDialog_145529_Content_26 = {
    Text = "Ah, es ist in ein Loch gerannt!"
  },
  AvgDialog_145529_Content_27 = {
    Text = "Sie wartete vom Tag bis in die Nacht, doch die Hasen kamen nicht heraus."
  },
  AvgDialog_145529_Content_28 = {
    Text = "Tante Rosa, ich hab es mit eigenen Augen gesehen! Der Hase ist direkt in dieses Loch gegangen!"
  },
  AvgDialog_145529_Content_29 = {
    Text = "Tante Rosa strich Caraboo sanft über das Haar."
  },
  AvgDialog_145529_Content_3 = {
    Text = "Es tut weh, weh, weh … Wo bin ich hier?"
  },
  AvgDialog_145529_Content_30 = {
    Text = "Du Törin, Hasen sind keine so einfachen Tiere."
  },
  AvgDialog_145529_Content_31 = {
    Text = "Die Baue unter diesen Feldern sind wie ein großes, verworrenes Netz aus Tunneln. Sie sind alle miteinander verbunden."
  },
  AvgDialog_145529_Content_32 = {
    Text = "Das kleine weiße Häschen, das du im Auge hattest, ist längst durch irgendein anderes Loch davongelaufen."
  },
  AvgDialog_145529_Content_33 = {
    Text = "Was soll ich dann tun?"
  },
  AvgDialog_145529_Content_34 = {
    Text = "Gar nichts, kleine Caraboo."
  },
  AvgDialog_145529_Content_35 = {
    Text = "Wir säen auf den Feldern, bewässern sie, warten auf die Reife, ernten und genießen die Früchte, die uns die Gottheit schenkt."
  },
  AvgDialog_145529_Content_36 = {
    Text = "Aber was, wenn ich dieses Kaninchen haben möchte?"
  },
  AvgDialog_145529_Content_37 = {
    Text = "Mein liebes kleines Caraboo, wir begehren dieses Kaninchen nicht. Wenn du Fleisch essen möchtest, können wir auf dem Markt Obst und Gemüse dafür eintauschen."
  },
  AvgDialog_145529_Content_38 = {
    Text = "Aber was, wenn ich dieses Kaninchen trotzdem haben möchte?"
  },
  AvgDialog_145529_Content_39 = {
    Text = "<Red:Warum … Warum kann ich diesen Hasen nicht haben?>"
  },
  AvgDialog_145529_Content_4 = {
    Text = "Sie musste nicht fragen, um es zu wissen. Sie befand sich im Bauch des Wurms."
  },
  AvgDialog_145529_Content_40 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_145529_Content_41 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_145529_Content_42 = {
    Text = "Warum sehe ich ausgerechnet jetzt Erinnerungen aus meiner Kindheit … ?"
  },
  AvgDialog_145529_Content_43 = {
    Text = "Ruhig. Vielleicht habe ich ein Trugbild, weil ich zu lange in der Dunkelheit unterwegs war."
  },
  AvgDialog_145529_Content_44 = {
    Text = "Das ist aber kein Trugbild, oder?"
  },
  AvgDialog_145529_Content_45 = {
    Text = "<Shake:Aaah! Ein Geist!! >"
  },
  AvgDialog_145529_Content_46 = {
    Text = "Erinnerst du dich an einen der sieben Artefakte, den Faden des Schicksals? Was du siehst, ist die Spur des Schicksals."
  },
  AvgDialog_145529_Content_47 = {
    Text = "Die Spur des Schicksals wird dir nun eine andere Möglichkeit aufzeigen, sowie ihren Verzweigungspunkt."
  },
  AvgDialog_145529_Content_48 = {
    Text = "Was hat das alles damit zu tun, dass ich gerade im Magen eines Monsters gefangen bin?"
  },
  AvgDialog_145529_Content_49 = {
    Text = "Weil es dein Wunsch ist. Wünsche sind die Zündschnur, die jeden Menschen zu seinem vorbestimmten Ende führt."
  },
  AvgDialog_145529_Content_5 = {
    Text = "Verdammt, man lockt einen hinein und wird selbst gefressen."
  },
  AvgDialog_145529_Content_50 = {
    Text = "Hör auf mit den Rätseln! Könntest du etwas von diesem Atem dafür nutzen, mir zu sagen, wie ich hier rauskomme?! <BigShake:HEY—>"
  },
  AvgDialog_145529_Content_51 = {
    Text = "Der Schatten verschwand lautlos."
  },
  AvgDialog_145529_Content_52 = {
    Text = "Tss, so kleinlich. Na ja, in der Bauchhöhle des Wurms gibt es sowieso keine anderen Abzweigungen — weiter vorwärts."
  },
  AvgDialog_145529_Content_53 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_145529_Content_54 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_145529_Content_55 = {
    Text = "Tante Rosa! Keine Eile, ich komme Ihnen gleich helfen!"
  },
  AvgDialog_145529_Content_56 = {
    Text = "Das bin … ich?"
  },
  AvgDialog_145529_Content_57 = {
    Text = "Braves Kind, Tante wollte nur nach dir sehen."
  },
  AvgDialog_145529_Content_58 = {
    Text = "Tante Rosa, Ihre Beine machen Ihnen zu schaffen — Sie müssen nicht immer auf die Plantage kommen. Sobald ich dieses bisschen Basilikum gepflückt habe, gehe ich mit Ihnen zurück, um die Kaninchen zu füttern."
  },
  AvgDialog_145529_Content_59 = {
    Text = "Hast du sie schon gesehen? Salat hat letzte Nacht Junge bekommen! So viele kleine Häschen, alle in verschiedenen Farben!"
  },
  AvgDialog_145529_Content_6 = {
    Text = "Warte mal, was ist das? Ein Faden … ?"
  },
  AvgDialog_145529_Content_60 = {
    Text = "Unser Caraboo ist zu einem großen Mädchen herangewachsen."
  },
  AvgDialog_145529_Content_61 = {
    Text = "Tante Rosa, was reden Sie denn. Diese Feldarbeit konnte ich schon erledigen, als ich dreizehn war."
  },
  AvgDialog_145529_Content_62 = {
    Text = "Die richtigste Entscheidung meines Lebens war, dich von deinen Eltern zu mir zu holen."
  },
  AvgDialog_145529_Content_63 = {
    Text = "Als du mir erzähltest, dass dein Vater dich betrunken geschlagen hat, zögerte ich eine ganze Nacht lang, und stieg dann im frühen Morgen in den allerersten Zug."
  },
  AvgDialog_145529_Content_64 = {
    Text = "Beinahe hätte ich mich mit deinem Vater geprügelt, bevor ich dich endlich zurückgeholt habe."
  },
  AvgDialog_145529_Content_65 = {
    Text = "Seitdem sind fast zehn Jahre vergangen, nicht wahr?"
  },
  AvgDialog_145529_Content_66 = {
    Text = "Jetzt, ohne dich, wüsste ich mit diesen Beinen wirklich nicht, wie ich alleine leben sollte —"
  },
  AvgDialog_145529_Content_67 = {
    Text = "Ah — Ah —"
  },
  AvgDialog_145529_Content_68 = {
    Text = "Das ist — jene Nacht — jene Nacht — eine andere Möglichkeit —"
  },
  AvgDialog_145529_Content_69 = {
    Text = "Jene Nacht, die Nacht, in der sie dem „Berg-Wurm“ begegnete, die Nacht, in der sie beschloss, ihr Schicksal eigenhändig abzuschütteln."
  },
  AvgDialog_145529_Content_7 = {
    Text = "Ein kristallklarer, schimmernder Faden tastete sich aus der fernen Dunkelheit hervor und schwebte vor Caraboo."
  },
  AvgDialog_145529_Content_70 = {
    Text = "Die Nacht, die sie in der wahren Welt erlebt hatte."
  },
  AvgDialog_145529_Content_71 = {
    Text = "Im Knistern der Kaminflammmen stand sie lange, lange zögernd vor dem Bett ihres betrunkenen Vaters."
  },
  AvgDialog_145529_Content_72 = {
    Text = "Geh, tu das, was du schon längst tun wolltest."
  },
  AvgDialog_145529_Content_73 = {
    Text = "Sie hob das Messer —"
  },
  AvgDialog_145529_Content_74 = {
    Text = "Genau, so ist es richtig."
  },
  AvgDialog_145529_Content_75 = {
    Text = "Töte ihn, dann können alle glücklich werden."
  },
  AvgDialog_145529_Content_76 = {
    Text = "Dann ließ sie es langsam, ganz langsam sinken."
  },
  AvgDialog_145529_Content_77 = {
    Text = "Es tut mir leid, ich kann es immer noch nicht tun."
  },
  AvgDialog_145529_Content_78 = {
    Text = "Geh fort, solange du weit genug von hier fliehst, musst du den Schmerz nicht länger ertragen."
  },
  AvgDialog_145529_Content_79 = {
    Text = "Nutzloses kleines Ding."
  },
  AvgDialog_145529_Content_8 = {
    Text = "Egal, egal – du solltest mich besser nicht täuschen!"
  },
  AvgDialog_145529_Content_80 = {
    Text = "Nun gut, was mich an dir interessiert, ist etwas anderes."
  },
  AvgDialog_145529_Content_81 = {
    Text = "Komm, mit deiner listigen Zunge werden wir genauso an den kostbarsten Schatz gelangen."
  },
  AvgDialog_145529_Content_82 = {
    Text = "Am nächsten Morgen versteckte ich mich heimlich im Stroh eines Ochsenkarrens und schmuggelte mich in die nächste Stadt."
  },
  AvgDialog_145529_Content_83 = {
    Text = "Dann bestieg ich mit gefälschter Identität und gefälschten Fahrkarten den Zug in Richtung Osten."
  },
  AvgDialog_145529_Content_84 = {
    Text = "Seitdem hatte ich viele Identitäten: die Nichte des Zugführers, die Freundin des Wachmanns, Sekte Fee, Schneeberg-Göttin …"
  },
  AvgDialog_145529_Content_85 = {
    Text = "Ich ließ all meine Vergangenheit hinter mir, zurück in jener Schneenacht der Flucht."
  },
  AvgDialog_145529_Content_86 = {
    Text = "Später, erst sehr, sehr viel später, erfuhr ich von einem Landsmann, dem ich auf dem Schlachtfeld begegnet war —"
  },
  AvgDialog_145529_Content_87 = {Text = "Herr Hans?"},
  AvgDialog_145529_Content_88 = {
    Text = "An einem verschneiten Tag hatte er sich sinnlos betrunken."
  },
  AvgDialog_145529_Content_89 = {
    Text = "Das Feuer im Kamin war vom Schmelzwasser, das durch die Decke tropfte, gelöscht worden. Gewöhnlich hätte seine kleine Tochter es wieder angezündet."
  },
  AvgDialog_145529_Content_9 = {
    Text = "Du erwachst aus der Bewusstlosigkeit, und vor dir liegt eine weiche, feuchte und bedrückende Leere."
  },
  AvgDialog_145529_Content_90 = {
    Text = "Gerade an jenem Tag war die kleine Tochter aus unbekanntem Grund nicht zu Hause."
  },
  AvgDialog_145529_Content_91 = {
    Text = "Er erfror in jener Schneenacht."
  },
  AvgDialog_145529_Content_92 = {
    Text = "Später haben wir das kleine Mädchen auch nie wieder gesehen."
  },
  AvgDialog_145529_Content_93 = {
    Text = "Ach ja, edle Fee, warum erkundigt Ihr Euch plötzlich danach? Könnt Ihr mir nun meinen Segen geben?"
  },
  AvgDialog_145529_Content_94 = {
    Text = "Caraboo griff dem jungen Mann vor ihr eine ganze Handvoll Bonbons."
  },
  AvgDialog_145529_Content_95 = {
    Text = "Bei der Fee da oben — jeden Tag eines. Wenn Ihr diese gesegneten Bonbons aufgegessen habt, wird Eure Beinverletzung geheilt sein."
  },
  AvgDialog_145529_Content_96 = {
    Text = "Auch wenn sie in ihrem Herzen wusste, dass kein Bonbon der Welt die bereits amputierten Beine des jungen Mannes heilen konnte."
  },
  AvgDialog_145529_Content_97 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_145529_Content_98 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_145529_Content_99 = {
    Text = "Wie lächerlich, wirklich lächerlich. Es stellt sich heraus, dass ich in jener Nacht Solange ich nichts getan hätte, das ersehnte Glück hätte erlangen können."
  },
  AvgDialog_145530_Content_1 = {
    Text = "Der lange Traum"
  },
  AvgDialog_145530_Content_10 = {
    Text = "Wenn dem so ist, unterstütze ich Dich."
  },
  AvgDialog_145530_Content_11 = {
    Text = "Ich unterstütze Dich dabei, das Selbst zurückzufinden, das weggeworfen wurde."
  },
  AvgDialog_145530_Content_12 = {
    Text = "Schließlich sind wir von Natur aus die egoistischsten Menschen überhaupt."
  },
  AvgDialog_145530_Content_13 = {
    Text = "Der Schnee-Berg starb."
  },
  AvgDialog_145530_Content_14 = {
    Text = "<Shake:Es ist vorbei…>"
  },
  AvgDialog_145530_Content_15 = {
    Text = "Im Zentrum des Schnee-Berges klaffte eine erschreckende Wunde – vom Kopf des Wurms bis zum Ende seiner Bauchhöhle."
  },
  AvgDialog_145530_Content_16 = {
    Text = "Der Körper des Wurms sackte entlang dieser Wunde langsam, ganz langsam nach beiden Seiten in sich zusammen."
  },
  AvgDialog_145530_Content_17 = {
    Text = "Gemeinsam mit dem Einsturz des Gipfels stürztet ihr geradewegs in die Tiefe."
  },
  AvgDialog_145530_Content_18 = {
    Text = "<Shake:Vorsicht, der Berg bricht zusammen!>"
  },
  AvgDialog_145530_Content_19 = {
    Text = "Im Wind des Sturzes, völlig unvorbereitet, vernahmst Du ein Flüstern."
  },
  AvgDialog_145530_Content_2 = {
    Text = "Hast Du Dir das gut überlegt?"
  },
  AvgDialog_145530_Content_20 = {
    Text = "Es ist noch nicht vorbei."
  },
  AvgDialog_145530_Content_21 = {
    Text = "Caraboo streckte die Hand aus."
  },
  AvgDialog_145530_Content_22 = {
    Text = "Auf ihrem tränenüberströmten Gesicht zeigte sich ein beiläufiges Lächeln."
  },
  AvgDialog_145530_Content_23 = {
    Text = "Dann, in der Schwerkraft, die ihr nicht beherrschen konntet, leuchteten die sieben Lichtringe auf."
  },
  AvgDialog_145530_Content_24 = {
    Text = "Die Toten… Nur der Schneeberg… Das Ritual… läuft noch!"
  },
  AvgDialog_145530_Content_25 = {
    Text = "In diesem einen Augenblick schien Himmel und Erde als ob alle Stille verloren hätte."
  },
  AvgDialog_145530_Content_26 = {
    Text = "Du siehst nur, wie sich ihre Lippen leise bewegen und Worte formen, die erst viele Sekunden später beginnen, durch Himmel und Erde zu hallen."
  },
  AvgDialog_145530_Content_27 = {
    Text = "Mein Wunsch ist, dass es in dieser Welt keine einzige Lüge mehr gebe."
  },
  AvgDialog_145530_Content_28 = {
    Text = "In dem Augenblick, als ihre Worte fielen, zerfiel die Welt vor ihren Augen."
  },
  AvgDialog_145530_Content_29 = {
    Text = "Silberne Asche rieselte in großen Mengen aus der fernen Höhe, äußerst leicht und äußerst langsam herab."
  },
  AvgDialog_145530_Content_3 = {
    Text = "Ja, ich habe mich bereits entschieden."
  },
  AvgDialog_145530_Content_30 = {
    Text = "Es war ein stilles Einstürzen, ein langsamer Absturz, der Vorhang fällt über einen uralten, ewigen Traum."
  },
  AvgDialog_145530_Content_31 = {
    Text = "Der Berggipfel."
  },
  AvgDialog_145530_Content_32 = {
    Text = "Der Schnee."
  },
  AvgDialog_145530_Content_33 = {
    Text = "Der Himmel."
  },
  AvgDialog_145530_Content_34 = {Text = "Die Erde."},
  AvgDialog_145530_Content_35 = {
    Text = "Alles, was einst gewesen war, wurde zur Nichtigkeit – so wie eine Lüge, die entlarvt wird."
  },
  AvgDialog_145530_Content_36 = {
    Text = "......Warum?"
  },
  AvgDialog_145530_Content_37 = {
    Text = "Ein Wissen, das Du nicht kennen solltest, drang zusammen mit fernen Erinnerungen wie ein Dorn in Deinen Geist."
  },
  AvgDialog_145530_Content_38 = {
    Text = "Dieses Schiff ist ein Traum, aber als der Vorhang der Lügen sich hebt..."
  },
  AvgDialog_145530_Content_39 = {
    Text = "Die ganze Welt ist ebenfalls der Traum einer bestimmten Person, nur ist dieser Traum größer, illusorischer und ferner..."
  },
  AvgDialog_145530_Content_4 = {
    Text = "Das ist Eine Lüge, das ist Verrat."
  },
  AvgDialog_145530_Content_40 = {
    Text = "Selbst Sonne, Mond und Sterne stammen aus seiner Einbildung, nur die Wesen, die mit seinem Geist verwoben sind, können..."
  },
  AvgDialog_145530_Content_41 = {
    Text = "<Italic:Die ganze Welt ist eine einzige riesige Lüge.>"
  },
  AvgDialog_145530_Content_42 = {
    Text = "Mit dieser Erkenntnis beschleunigte sich der Zerfall. Vom Himmel fiel ein dichter silberner Regen."
  },
  AvgDialog_145530_Content_43 = {
    Text = "Der Regen fällt ins Wasser. Die Scherben dessen, was einst „die Welt\" gewesen war, verwandeln sich in silberne Tropfen und sinken langsam in ein bodenloses Meer hinab."
  },
  AvgDialog_145530_Content_44 = {
    Text = "Und Du befandest Dich in diesem Meerwasser."
  },
  AvgDialog_145530_Content_45 = {
    Text = "Hinabsinken, hinabsinken."
  },
  AvgDialog_145530_Content_46 = {
    Text = "Bis der lange Traum endete und Du erneut Deine Augen öffnetest."
  },
  AvgDialog_145530_Content_47 = {
    Text = "Um dem wahren Antlitz dieser Welt ins Auge zu blicken."
  },
  AvgDialog_145530_Content_48 = {
    Text = "Am tiefsten und dunkelsten Grund des Aequors."
  },
  AvgDialog_145530_Content_49 = {
    Text = "Das längst untergegangene, majestätische Göttliche Reich enthüllte endlich seine wahre Gestalt."
  },
  AvgDialog_145530_Content_5 = {
    Text = "Alle haben sich liebevoll um Dich gekümmert, und auch sie haben Wünsche, die sie erfüllt sehen möchten."
  },
  AvgDialog_145530_Content_6 = {
    Text = "Aber die Gelegenheit zu wünschen gibt es Nur einmal."
  },
  AvgDialog_145530_Content_7 = {
    Text = "Trotzdem, wünschst du dir immer noch <Yellow:„das“>?"
  },
  AvgDialog_145530_Content_8 = {
    Text = "Es gibt keinen wichtigeren Wunsch als diesen."
  },
  AvgDialog_145530_Content_9 = {
    Text = "Der Schatten lächelte."
  },
  AvgDialog_145531_Content_1 = {Text = "Gute Nacht"},
  AvgDialog_145531_Content_10 = {
    Text = "Hinter ihr öffnete jemand lautlos ein Auge und spähte ihrer schwindenden Gestalt nach."
  },
  AvgDialog_145531_Content_11 = {
    Text = "Tinct folgte dem Gesang langsam zu seinem Ursprung, während Eisscherben und Permafrost unter ihren dünnbesohlten Schuhen leise knirschten."
  },
  AvgDialog_145531_Content_12 = {
    Text = "(Das ist… der Eissee von tagsüber…)"
  },
  AvgDialog_145531_Content_13 = {
    Text = "(Aber irgendwie ist es ein wenig anders…)"
  },
  AvgDialog_145531_Content_14 = {
    Text = "Das tagsüber zugefrorene Seewasser war aus unbekanntem Grund erwacht."
  },
  AvgDialog_145531_Content_15 = {
    Text = "Die stille, reglose Wasseroberfläche öffnete ihre Augen zum Himmelszelt, gleich einem klaren Spiegel, der still den ewigen Mond widerspiegelte."
  },
  AvgDialog_145531_Content_16 = {
    Text = "Faint, bist du das?"
  },
  AvgDialog_145531_Content_17 = {
    Text = "(Das Seewasser… ungewöhnlich klar…)"
  },
  AvgDialog_145531_Content_18 = {
    Text = "Sie blickte auf den Grund des Sees."
  },
  AvgDialog_145531_Content_19 = {
    Text = "Das Seewasser war bodenlos tief, als ob es die Erde durchstach und zu einem Ort führte, der noch weiter entfernt war als die Sterne."
  },
  AvgDialog_145531_Content_2 = {
    Text = "Um Mitternacht wird Tinct von einem fernen, leisen Geräusch geweckt."
  },
  AvgDialog_145531_Content_20 = {
    Text = "Ein Lied treibt im Wind. Rau und uralt, als hätte es einen unvorstellbar langen Zeitraum überdauert und höre noch immer nicht auf."
  },
  AvgDialog_145531_Content_21 = {
    Text = "<Italic:La—la la~ la~ ♪>"
  },
  AvgDialog_145531_Content_22 = {
    Text = "Tinct schloss die Augen und atmete tief durch."
  },
  AvgDialog_145531_Content_23 = {
    Text = "(Eine vertraute Melodie… ein sehnsuchtsvoller… Hauch…)"
  },
  AvgDialog_145531_Content_24 = {
    Text = "Die Klangfarbe der Stimme erinnerte an ein ausgetrocknetes Flussbett, an Sandsteinschichten, die hunderttausend Jahre lang verwittert worden waren, an den Schrei jener urzeitlichen Wälder, die unter dem Druck geologischer Epochen zu Kohle gepresst worden waren."
  },
  AvgDialog_145531_Content_25 = {
    Text = "(Das klingt wie… eine Melodie… vom Verlassenen Stern…)"
  },
  AvgDialog_145531_Content_26 = {
    Text = "Erinnerungen aus tausend Jahren erwachten allmählich zur Wiederbelebung, und Sie begann zu versuchen, mitzusummen, dem flüchtigen Gesang zu folgen."
  },
  AvgDialog_145531_Content_27 = {
    Text = "<Shake:La la~ la la la~♪>"
  },
  AvgDialog_145531_Content_28 = {
    Text = "Sie spürte es, sie hatte es erfasst."
  },
  AvgDialog_145531_Content_29 = {
    Text = "Auf ihrem Gesicht erstrahlte aufrichtige Freude."
  },
  AvgDialog_145531_Content_3 = {
    Text = "(Draußen… ist das… Gesang?)"
  },
  AvgDialog_145531_Content_30 = {
    Text = "Ihr Stimmumfang weitete sich, nach oben. Eine klare Stimme wie die einer Nachtigall umschlang sanft und leicht die heisere Grundmelodie."
  },
  AvgDialog_145531_Content_31 = {
    Text = "Die zwei Stimmen begannen sich zu ziehen, zu verflechten, einander anzunähern."
  },
  AvgDialog_145531_Content_32 = {
    Text = "<Change>La la la la la la~♪"
  },
  AvgDialog_145531_Content_33 = {
    Text = "Die Eisschicht schloss sich Zentimeter für Zentimeter, und aus der Tiefe des Sees hoben unzählige bleiche Gesichter dem Gesang folgend ihre Häupter."
  },
  AvgDialog_145531_Content_34 = {
    Text = "Doch Tinct bemerkte nichts davon."
  },
  AvgDialog_145531_Content_35 = {
    Text = "Nur der Gesang. Der Gesang überspannte Die Schneegebundenen und das gefrorene Land, überspannte das Universum und das Sternenmeer, überspannte die ewigen Zeitalter und wurde zu etwas, das jeder Mensch als ewig betrachten sollte."
  },
  AvgDialog_145531_Content_36 = {
    Text = "Ja, ich sollte mich nicht länger selbst belügen…"
  },
  AvgDialog_145531_Content_37 = {
    Text = "Ich habe… keine Lust mehr zu suchen… Nirgendwo gibt es Hoffnung… Sie lebt in meiner Erinnerung, und nur dort…"
  },
  AvgDialog_145531_Content_38 = {
    Text = "Die Alte Bekannte im Wasser streckte ihr die Hand entgegen."
  },
  AvgDialog_145531_Content_39 = {
    Text = "Eine alte Stimme rief sie sanft beim Ruf, beim Namen aus tausend Jahren."
  },
  AvgDialog_145531_Content_4 = {
    Text = "Das Geräusch ist äußerst leise und dringt aus unergründlicher Tiefe durch unzählige Schichten aus Eis, Schnee und Gestein empor."
  },
  AvgDialog_145531_Content_41 = {
    Text = "Ich sollte aufgeben…"
  },
  AvgDialog_145531_Content_42 = {
    Text = "Diese Reise ist so lang, so lang — ich bin schon längst, so unendlich erschöpft…"
  },
  AvgDialog_145531_Content_43 = {
    Text = "Der Ruf vibrierte an ihren Knochen entlang und schenkte ihr den Trost, nach dem sie sich sehnte. Ihr Kummer, der nirgends Platz fand, ihre Trauer, die nirgends abgeladen werden konnte — endlich wurden sie von einem Wesen vollständig erkannt und angenommen."
  },
  AvgDialog_145531_Content_44 = {
    Text = "<Shake:Umarme mich, Faint… du Schatten in meiner Erinnerung… Umarme mich, wie einst zuvor…>"
  },
  AvgDialog_145531_Content_45 = {
    Text = "<Shake:Schenke mir… die Ning, nach der ich mich sehne…>"
  },
  AvgDialog_145531_Content_46 = {
    Text = "Sanft, ganz sanft schritt sie in das stille Seewasser."
  },
  AvgDialog_145531_Content_47 = {
    Text = "Der See rührt keine einzige Welle. Wie eine kalte Zunge leckt er zärtlich an ihrer Taille, ihren Schultern, ihrer Kehle."
  },
  AvgDialog_145531_Content_48 = {
    Text = "<Change>La la…"
  },
  AvgDialog_145531_Content_49 = {
    Text = "Sie sang noch immer."
  },
  AvgDialog_145531_Content_5 = {
    Text = "Es ist heiser und langsam, jede Silbe klingt wie vom Wind getriebener Sand, der über die Erde rollt. Hartnäckig und unaufhörlich, fließt es weiter wie ein unterirdischer Fluss, der ewig strömt."
  },
  AvgDialog_145531_Content_50 = {
    Text = "Ihre Gestalt, ihr Körper, ihre Existenz — alles wurde mit dem Gesang dünner und löste sich im Mondlicht auf."
  },
  AvgDialog_145531_Content_51 = {
    Text = "Ein Gedanke — ein so schwacher, Fast nicht greifbarer Gedanke — stieg in diesem Augenblick seltsamerweise in Tincts Bewusstsein auf."
  },
  AvgDialog_145531_Content_52 = {
    Text = "(Merkwürdig… heute… sollte doch eigentlich Neumond sein…)"
  },
  AvgDialog_145531_Content_53 = {
    Text = "Und dann — brach die Seeoberfläche plötzlich nach innen ein."
  },
  AvgDialog_145531_Content_54 = {
    Text = "Kein Spritzen, kein Schrei. Nur der Gesang schwebte noch umher."
  },
  AvgDialog_145531_Content_55 = {
    Text = "Der Mond am Himmel war irgendwann verschwunden."
  },
  AvgDialog_145531_Content_56 = {
    Text = "Nur der Mond schaukelte noch auf dem Seewasser, in dem sich Tincts klares Spiegelbild abzeichnete."
  },
  AvgDialog_145531_Content_57 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_145531_Content_58 = {
    Text = "Am nächsten Morgen."
  },
  AvgDialog_145531_Content_59 = {
    Text = "Hat jemand Tinct gesehen?"
  },
  AvgDialog_145531_Content_6 = {
    Text = "(So weit entfernt, und doch so vertraut…)"
  },
  AvgDialog_145531_Content_60 = {
    Text = "Alle schüttelten den Kopf."
  },
  AvgDialog_145531_Content_61 = {
    Text = "Hm … Letzte Nacht hörte ich ein Geräusch neben mir, aber ich schlief schnell wieder ein."
  },
  AvgDialog_145531_Content_62 = {
    Text = "Ich habe alle Zelte abgesucht, sie ist nirgends."
  },
  AvgDialog_145531_Content_63 = {
    Text = "Vielleicht ist sie zwischendurch aufgebrochen?"
  },
  AvgDialog_145531_Content_64 = {
    Text = "Gestern am Gletschersee war ihr Zustand schon sehr merkwürdig …"
  },
  AvgDialog_145531_Content_65 = {
    Text = "Evelyn murmelte unruhig vor sich hin."
  },
  AvgDialog_145531_Content_66 = {
    Text = "Sie hat nicht einmal eine Sauerstoffflasche mitgenommen."
  },
  AvgDialog_145531_Content_67 = {
    Text = "Wir befinden uns auf einem Gipfel in sechstausend Metern Höhe — jeder muss, und kann nur, für sein eigenes LP verantwortlich sein."
  },
  AvgDialog_145531_Content_68 = {
    Text = "Zumindest … zumindest einen Blick am Gletschersee werfen."
  },
  AvgDialog_145531_Content_69 = {Text = "Gehen wir?"},
  AvgDialog_145531_Content_7 = {
    Text = "Die Teammitglieder in den umliegenden Zelten waren vor Erschöpfung vom Tagesaufstieg in tiefen Schlaf gesunken. Sogar die Schlittenhunde schnarchten."
  },
  AvgDialog_145531_Content_70 = {
    Text = "Du willst Tinct suchen und keine noch so kleine Möglichkeit aufgeben. Aber du weißt auch, dass jede Entscheidung, die du triffst, das Leben der gesamten Gruppe auf dem Spiel setzt."
  },
  AvgDialog_145531_Content_71 = {
    Text = "Auf geht's — der Höhenunterschied zwischen hier und dem Gletschersee ist fast gleich null, die Hin- und Rückfahrzeit liegt im kontrollierbaren Rahmen."
  },
  AvgDialog_145531_Content_72 = {
    Text = "Das Einzige, worauf man achten muss, sind die wilden Tiere entlang des Weges."
  },
  AvgDialog_145531_Content_8 = {
    Text = "Zeit, nach draußen zu gehen."
  },
  AvgDialog_145531_Content_9 = {
    Text = "Sie zog sich aus dem Schlafsack, öffnete das Zelt und schob sich langsam hinaus."
  },
  AvgDialog_145532_Content_1 = {
    Text = "Er blickte zurück"
  },
  AvgDialog_145532_Content_10 = {
    Text = "Dann ist Evelyn an der Reihe. Wilhelm sichert das Ende, sein ruhiger, konzentrierter Blick wacht über alle."
  },
  AvgDialog_145532_Content_11 = {
    Text = "Warte mal …"
  },
  AvgDialog_145532_Content_12 = {
    Text = "Evelyns Blick heftet sich auf ein Stück Seil an der abgebrochenen Wand."
  },
  AvgDialog_145532_Content_13 = {
    Text = "Das ist … ihre Seilklemme! Ich erkenne diese Markierung!"
  },
  AvgDialog_145532_Content_14 = {
    Text = "Der Winkel des Schneegesimses! Der Winkel des Schneegesimses bildet eine geschützte Zone, sodass dieser Bereich nicht von herabfallendem Schnee bedeckt wird!"
  },
  AvgDialog_145532_Content_15 = {
    Text = "Du blickst hinunter in Evelyns Richtung. Nur ein einziger Blick, und das Trugbild des Sturzes lässt dich schwindeln."
  },
  AvgDialog_145532_Content_16 = {
    Text = "Ich muss ihn finden!"
  },
  AvgDialog_145532_Content_17 = {
    Text = "Evelyn löste die Seilklemme und ließ sich langsam abseilen."
  },
  AvgDialog_145532_Content_18 = {
    Text = "Das ist zu gefährlich, Evelyn!"
  },
  AvgDialog_145532_Content_19 = {
    Text = "Kein Problem, genau dafür bin ich hier! Was Gefahr angeht – das Klettern selbst ist schon gefährlich genug!"
  },
  AvgDialog_145532_Content_2 = {
    Text = "Vier Menschen, wie vier Würfel, schwebend auf dem Spielfeld namens Eiswand."
  },
  AvgDialog_145532_Content_20 = {
    Text = "Kümmert euch nicht um mich! Ich hole euch gleich ein!"
  },
  AvgDialog_145532_Content_21 = {
    Text = "In der Tiefe des Eisspalts schien etwas sie zu verlocken, als ob es sie rief."
  },
  AvgDialog_145532_Content_22 = {
    Text = "Evelyn, du kannst nicht——!"
  },
  AvgDialog_145532_Content_23 = {
    Text = "Du streckst die Hand nach deinem Seilknoten aus, holst tief Luft und bereitest dich auf den Sturz vor."
  },
  AvgDialog_145532_Content_24 = {
    Text = "%player%..."
  },
  AvgDialog_145532_Content_25 = {
    Text = "Wilhelm hält deine Hand fest und schüttelt sanft den Kopf."
  },
  AvgDialog_145532_Content_26 = {
    Text = "Niemand weiß, ob Helot zurückkommt. Wir können nicht alle in der Luft hängen bleiben."
  },
  AvgDialog_145532_Content_27 = {
    Text = "Sieh nach oben."
  },
  AvgDialog_145532_Content_28 = {
    Text = "Caraboo hat bereits als Erster die letzte Eiswand überwunden."
  },
  AvgDialog_145532_Content_29 = {
    Text = "Nach oben — das ist das Ziel dieser Reise, das gelobte Land, wo alle Wünsche in Erfüllung gehen."
  },
  AvgDialog_145532_Content_3 = {
    Text = "Jeder hielt das Sicherungsseil fest umklammert und tastete mühsam nach dem nächsten Trittplatz."
  },
  AvgDialog_145532_Content_30 = {
    Text = "Nach unten — ein bodenloser Abgrund der Dunkelheit."
  },
  AvgDialog_145532_Content_31 = {
    Text = "Aber wir können keine weiteren Gefährten verlieren——!"
  },
  AvgDialog_145532_Content_32 = {Text = "Ich weiß."},
  AvgDialog_145532_Content_33 = {
    Text = "Also überlass es mir."
  },
  AvgDialog_145532_Content_34 = {
    Text = "Noch bevor die Worte ankommen, löst Wilhelm seinen Gurt und stürzt sich geradewegs in den Abgrund."
  },
  AvgDialog_145532_Content_35 = {
    Text = "Die schiere Eiswand, die euch alle Kräfte gekostet hat, wird beim Abstieg in Sekunden überwunden. Im Nu sind Wilhelm und Evelyn zu zwei winzigen, fernen Punkten geschrumpft, verschluckt von den engen Kiefern des Eisspalts."
  },
  AvgDialog_145532_Content_36 = {
    Text = "Du schaust zu, wie Evelyn und Wilhelm immer tiefer sinken und sich dem Eisspalt nähern."
  },
  AvgDialog_145532_Content_37 = {
    Text = "Dann hebst du den Kopf und schlägst den nächsten Felshaken ein."
  },
  AvgDialog_145532_Content_38 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_145532_Content_39 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_145532_Content_4 = {
    Text = "Oben ist ein Felsen – wir müssen darüber hinweg."
  },
  AvgDialog_145532_Content_40 = {
    Text = "Der Eisspalt war bodenlos tief, und als sie wieder festen Boden unter den Füßen hatten, herrschte eine Dunkelheit, in der man die Hand vor Augen nicht sehen konnte."
  },
  AvgDialog_145532_Content_41 = {
    Text = "Warte, Evelyn…"
  },
  AvgDialog_145532_Content_42 = {
    Text = "Das Licht der tanzenden Stirnlampe tastete sich nach vorne."
  },
  AvgDialog_145532_Content_43 = {
    Text = "Unter dem Eisspalt schien sich eine Tropfsteinhöhle zu befinden, die Luft war anders als anderswo. Eisig, feucht, und der Wind trug einen seltsamen, undefinierbaren Geruch mit sich."
  },
  AvgDialog_145532_Content_44 = {
    Text = "Vorsicht, wo du hintrittst — hier gibt es eine Vertiefung…"
  },
  AvgDialog_145532_Content_45 = {
    Text = "Seine Worte blieben ihm im Hals stecken und verwandelten sich in einen scharf eingezogenen Atemzug."
  },
  AvgDialog_145532_Content_46 = {
    Text = "Wo das Licht hinfiel, lagen Dutzende von Leichen, die bereits zu Leichenwachs erstarrt waren."
  },
  AvgDialog_145532_Content_47 = {
    Text = "Sie lagen in der Haltung, in der sie gefallen waren – manche zusammengekauert, manche sich umarmend – still und übereinandergeschichtet auf dem Boden."
  },
  AvgDialog_145532_Content_48 = {
    Text = "Das ist … die Uniform der Green-Expedition."
  },
  AvgDialog_145532_Content_49 = {
    Text = "Sie sind alle hier."
  },
  AvgDialog_145532_Content_5 = {
    Text = "Ihr bewegt euch behutsam um den Felsblock herum und prüft, ob der Untergrund fester Fels oder lockerer Schnee ist."
  },
  AvgDialog_145532_Content_50 = {
    Text = "Nach einer Weile drehte Evelyn sich um und richtete ihren Blick ernst auf Wilhelms Augen."
  },
  AvgDialog_145532_Content_51 = {
    Text = "Es scheint, als gäbe es hier auch nicht viele Informationen, die ihr braucht, oder?"
  },
  AvgDialog_145532_Content_52 = {
    Text = "Wenn das so ist – könnt ihr mich eine Weile allein hier lassen? Ich möchte nachsehen, ob er dabei ist."
  },
  AvgDialog_145532_Content_53 = {
    Text = "Wenn möglich, würde ich gerne ein paar Worte mit ihm wechseln."
  },
  AvgDialog_145532_Content_54 = {
    Text = "Diese Leichen könnten gefährliche Krankheitserreger in sich tragen …"
  },
  AvgDialog_145532_Content_55 = {
    Text = "Evelyn drückte mit ihrem Blick aus, dass sie bei ihrer Entscheidung blieb."
  },
  AvgDialog_145532_Content_56 = {
    Text = "Verstanden."
  },
  AvgDialog_145532_Content_57 = {
    Text = "Aber versprich mir, dass du wohlbehalten wieder herauskommst."
  },
  AvgDialog_145532_Content_58 = {
    Text = "Ja, gut, das verspreche ich dir. Ich werde den Gipfel auf jeden Fall erreichen."
  },
  AvgDialog_145532_Content_59 = {
    Text = "Wilhelm nickte."
  },
  AvgDialog_145532_Content_6 = {
    Text = "Kaum habt ihr ihn umrundet und noch keine Zeit zum Verschnaufen, tut sich unter euren Füßen ein bodenloser Spalt auf."
  },
  AvgDialog_145532_Content_60 = {
    Text = "Ich warte am Höhleneingang auf dich."
  },
  AvgDialog_145532_Content_61 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_145532_Content_62 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_145532_Content_63 = {
    Text = "Es verging sehr, sehr lange Zeit – so lange, dass Wilhelm Fast dem Drang nachgeben wollte, selbst hineinzugehen und nachzusehen –, als aus der Höhle endlich das leise Rascheln von Kleidung zu hören war."
  },
  AvgDialog_145532_Content_64 = {
    Text = "Dann erschien Evelyn."
  },
  AvgDialog_145532_Content_65 = {
    Text = "Hast du … ihn gefunden?"
  },
  AvgDialog_145532_Content_66 = {
    Text = "Ja, ich habe ihn gefunden."
  },
  AvgDialog_145532_Content_67 = {
    Text = "Evelyn nickte, ihre Stimme war ruhig und ohne jede Regung."
  },
  AvgDialog_145532_Content_68 = {
    Text = "Mein Beileid."
  },
  AvgDialog_145532_Content_69 = {
    Text = "Nein, danke."
  },
  AvgDialog_145532_Content_7 = {
    Text = "Vorsicht – schau nicht nach unten."
  },
  AvgDialog_145532_Content_70 = {
    Text = "Evelyn lachte leise auf."
  },
  AvgDialog_145532_Content_71 = {
    Text = "Ich wusste schon immer, dass es so enden würde."
  },
  AvgDialog_145532_Content_72 = {
    Text = "Du auch, oder?"
  },
  AvgDialog_145532_Content_73 = {
    Text = "Auch du suchst nach jemandem, der nie zurückkehren wird."
  },
  AvgDialog_145532_Content_74 = {
    Text = "Es ist immer dasselbe."
  },
  AvgDialog_145532_Content_75 = {
    Text = "Am Anfang hegt man noch Hoffnung und denkt, er kommt vielleicht morgen zurück."
  },
  AvgDialog_145532_Content_76 = {
    Text = "Dann vergeht ein Morgen…"
  },
  AvgDialog_145532_Content_77 = {
    Text = "…und noch ein weiterer."
  },
  AvgDialog_145532_Content_78 = {
    Text = "Die Hoffnung wird immer dünner, und der Stein im Herzen drückt immer schwerer."
  },
  AvgDialog_145532_Content_79 = {
    Text = "Er sinkt Tag für Tag tiefer, immer tiefer im Absturz."
  },
  AvgDialog_145532_Content_8 = {
    Text = "Du folgst Naraka dicht auf den Fersen und kämpfst dich mit dem Seil über den Spalt."
  },
  AvgDialog_145532_Content_80 = {
    Text = "Bis du eines Tages entdeckst, dass du gar nicht mehr daran denkst."
  },
  AvgDialog_145532_Content_81 = {
    Text = "Du isst, schläfst, arbeitest, reist, redest mit anderen, lachst und scherzst – ganz wie gewohnt…"
  },
  AvgDialog_145532_Content_82 = {
    Text = "Und dann, nach sehr, sehr langer Zeit, erwähnst du es nicht mehr."
  },
  AvgDialog_145532_Content_83 = {
    Text = "Evelyns Stimme veränderte sich unmerklich im Ton."
  },
  AvgDialog_145532_Content_84 = {
    Text = "Aber du weißt, dass du es nicht vergessen hast – du hast es nie vergessen."
  },
  AvgDialog_145532_Content_85 = {
    Text = "Du wirst es niemals vergessen."
  },
  AvgDialog_145532_Content_86 = {
    Text = "Es braucht nur eine Legende, einen einzigen Funken, und es beginnt zu brennen…"
  },
  AvgDialog_145532_Content_87 = {
    Text = "Es wird dich ganz verschlucken…"
  },
  AvgDialog_145532_Content_88 = {
    Text = "…und dich zu Asche verbrennen."
  },
  AvgDialog_145532_Content_89 = {
    Text = "Wilhelm hob ruckartig den Kopf und traf Evelyns Blick direkt."
  },
  AvgDialog_145532_Content_9 = {
    Text = "Im Augenwinkel erhaschst du einen Blick in das Innere des Spalts – ein schwindelerregendes Schwarz, das kein Ende zu kennen scheint."
  },
  AvgDialog_145532_Content_90 = {
    Text = "Doch die andere erwiderte seinen Blick nur sanft – ob es Flammen oder Leere waren, die jene Augen füllten, konnte er hinter dem Spiegeln der Schutzbrille nicht erkennen."
  },
  AvgDialog_145532_Content_91 = {
    Text = "Hör auf zu träumen, lass uns gehen. Ich habe dir versprochen, gemeinsam mit euch den Gipfel zu erreichen, oder nicht?"
  },
  AvgDialog_145532_Content_92 = {
    Text = "Aus unbekanntem Grund hatte Wilhelm stets das Gefühl, dass Evelyns Blick zwar auf ihn gerichtet war, ihr Gespräch jedoch nicht wirklich ihm galt."
  },
  AvgDialog_145532_Content_93 = {
    Text = "Evelyn wartete nicht länger auf ihn. Sie drehte sich um und ging zur Höhle hinaus, bückte sich und überprüfte das Zugseil – ihre Bewegungen so routiniert, als hätte das Selbstgespräch von eben niemals stattgefunden."
  },
  AvgDialog_145532_Content_94 = {
    Text = "Wilhelm steht wie angewurzelt da, die Worte, die er nicht über sich brachte auszusprechen, stecken ihm im Hals. Er sieht ihr nach, wie sie in der Ferne verschwindet, und blickt dann zurück auf den dunklen, gähnenden Eingang der Höhle hinter ihm."
  },
  AvgDialog_145532_Content_95 = {
    Text = "Er fand keinen Grund, auch nur eine Sekunde länger zu verweilen. Er wandte den Blick ab und folgte ihr schweigend."
  },
  AvgDialog_145534_Content_1 = {
    Text = "Die Posse ist vorbei. Jetzt wird euch der Schneeberg verschlucken."
  },
  AvgDialog_145534_Content_10 = {
    Text = "Der Gipfel Zerriss von der Mitte her auf, wurde immer weiter, immer breiter und verwandelte sich in einen riesigen, senkrecht durch Himmel und Erde klaffenden Rachen; blutrote Speichelfäden strömten über Schicht um Schicht von Reißzähnen und prasselten wie Regen herab."
  },
  AvgDialog_145534_Content_11 = {
    Text = "Der Rachen schloss sich jäh —"
  },
  AvgDialog_145534_Content_12 = {
    Text = "Bevor die Menge auch nur den ersten Schrei ausstoßen konnte, waren sie bereits in seinem bodenlosen Bauch verschluckt."
  },
  AvgDialog_145534_Content_13 = {
    Text = "Die Erde hörte auf zu Zittern; aus dem rieselnden Schnee ragte ein kleiner spitzer Hut hervor."
  },
  AvgDialog_145534_Content_14 = {
    Text = "Caraboo schüttelte den Schnee von sich ab und musterte zufrieden das Ergebnis ihrer Arbeit —"
  },
  AvgDialog_145534_Content_15 = {
    Text = "Warum? Warum bist Du noch hier?"
  },
  AvgDialog_145534_Content_16 = {
    Text = "Eine einsame Gestalt, die nicht existieren sollte."
  },
  AvgDialog_145534_Content_17 = {
    Text = "Ich würde auch gerne wissen, warum ich noch hier bin."
  },
  AvgDialog_145534_Content_18 = {
    Text = "Du hast gerade gesagt, dass Besucher dem Berg ihre Wünsche darbringen, und der Berg auf die Bitten der Bittenden antwortet."
  },
  AvgDialog_145534_Content_19 = {
    Text = "Vielleicht liegt es daran, dass ich im Vergleich zu euch keine besonderen Wünsche habe – zu gewöhnlich, zu alltäglich, nicht schmackhaft genug?"
  },
  AvgDialog_145534_Content_2 = {
    Text = "Caraboo dreht sich um, den endlosen Bergketten und dem weiten Schneesturm zugewandt."
  },
  AvgDialog_145534_Content_20 = {
    Text = "Nein, das kann nicht sein. Hast Du keinen Wunsch, den Du dem Berg übergeben möchtest?"
  },
  AvgDialog_145534_Content_21 = {
    Text = "Caraboo riss die Augen auf, in ihrer Frage schwang ein Hauch von Ungläubigkeit und Verärgerung mit."
  },
  AvgDialog_145534_Content_22 = {
    Text = "Nein. Der einzige Wunsch, den ich auf dieser Reise hatte, ist bereits in Erfüllung gegangen."
  },
  AvgDialog_145534_Content_23 = {
    Text = "Am Fuß der letzten Felswand fand ich seine Überreste. Was für ein Glück – er war in einem Felsspalt eingeklemmt und nicht vom Schnee begraben worden."
  },
  AvgDialog_145534_Content_24 = {
    Text = "Der Körper ist dem Verfall anheimgefallen, aber das Schild ist noch da. Ich konnte ihn noch erkennen, konnte seine Existenz noch bestätigen."
  },
  AvgDialog_145534_Content_25 = {
    Text = "Wie ist das möglich, wie kann man so leicht Erfüllung finden!"
  },
  AvgDialog_145534_Content_26 = {
    Text = "So ist es nun einmal. Die Wünsche der Sterblichen sollten von Natur aus keine Dinge sein, die göttlicher Kraft bedürfen, um erfüllt zu werden."
  },
  AvgDialog_145534_Content_27 = {
    Text = "Und es gibt noch mehr gute Neuigkeiten. Anhand der Ausrüstung, die er trug, lässt sich schließen, dass sie auf dem Abstieg in Unglück geraten sind."
  },
  AvgDialog_145534_Content_28 = {
    Text = "Also hatte er zu Lebzeiten bereits seinen Wunsch erfüllt, den höchsten Gipfel zu besteigen."
  },
  AvgDialog_145534_Content_29 = {
    Text = "Obwohl etwas Zeit dazwischen liegt – hier, an diesem Ort, werden wir beide in Erfüllung sterben."
  },
  AvgDialog_145534_Content_3 = {
    Text = "Wahre Schneeberg-Fee, großer Wurmgott — ich bringe Euch Eure Verehrung!"
  },
  AvgDialog_145534_Content_30 = {
    Text = "<Shake:Nein, Du belügst Dich selbst … das ist nicht wahr, Du musst doch mehr wollen …>"
  },
  AvgDialog_145534_Content_31 = {
    Text = "Caraboos Stimme wurde immer schriller, Tränen traten ihr aus den Augenwinkeln."
  },
  AvgDialog_145534_Content_32 = {
    Text = "Evelyn betrachtete Sie Gerade nur mit einem mitleidsvollen Blick."
  },
  AvgDialog_145534_Content_33 = {
    Text = "Der Schnee fiel unaufhörlich."
  },
  AvgDialog_145534_Content_34 = {
    Text = "Nach einer langen Weile trat Evelyn vor und klopfte den gefallenen Schnee von Caraboos Schultern."
  },
  AvgDialog_145534_Content_35 = {
    Text = "Denk noch einmal gut darüber nach. Ich gehe jetzt zu meinem Mann."
  },
  AvgDialog_145534_Content_36 = {
    Text = "Nach diesen Worten summte sie leise vor sich hin und schritt Schritt für Schritt den Abhang hinunter."
  },
  AvgDialog_145534_Content_37 = {
    Text = "Ohne Sicherungsseil fürchtete sie den Sturz nicht. Die Eisspalten am Felsgrund waren ihr Ziel."
  },
  AvgDialog_145534_Content_38 = {
    Text = "<Shake:Geh nicht, Evelyn, geh nicht —>"
  },
  AvgDialog_145534_Content_39 = {
    Text = "Diejenige, die sie zurückwies, war nicht Evelyn."
  },
  AvgDialog_145534_Content_4 = {
    Text = "Sie ist in Ekstase, Sie lacht wild. Sie empfindet Freude über den Erfolg ihrer Täuschung."
  },
  AvgDialog_145534_Content_40 = {
    Text = "Diejenige, die sie zurückhalten wollte, war auch nicht jemand anderes als Evelyn."
  },
  AvgDialog_145534_Content_41 = {Text = "Warum"},
  AvgDialog_145534_Content_42 = {
    Text = "Warum … zittert der Berg? …"
  },
  AvgDialog_145534_Content_43 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_145534_Content_44 = {
    Text = "Im Berg haust das Allergrauenhafteste."
  },
  AvgDialog_145534_Content_45 = {
    Text = "Es erstreckt sich über tausend Meilen und windet sich über das Land, das es beansprucht. Es verschlingt die Herzen der Menschen und frisst ihre Illusionen."
  },
  AvgDialog_145534_Content_46 = {
    Text = "Nun kommt Es, um seine Beute zu fangen."
  },
  AvgDialog_145534_Content_47 = {
    Text = "<Change>Ein Wunsch … ein Wunsch … ein inniger Wunsch …"
  },
  AvgDialog_145534_Content_48 = {
    Text = "Nein! Ich habe sie alle für dich hergelockt, du hast versprochen, mich nicht zu fressen!"
  },
  AvgDialog_145534_Content_49 = {
    Text = "<Change>Wer würde sich … an die Abmachung … eines Lügners … halten …"
  },
  AvgDialog_145534_Content_5 = {
    Text = "Oh ihr gierigen Menschen, oh ihr törichten Menschen."
  },
  AvgDialog_145534_Content_50 = {
    Text = "Der Wurm auf dem Apfel stimmte ebenfalls ein und lachte schrill auf."
  },
  AvgDialog_145534_Content_51 = {
    Text = "Außerdem — wusstest du nicht von Anfang an, dass eine der Opfergaben der Goldene Apfel ist?"
  },
  AvgDialog_145534_Content_52 = {
    Text = "Nein, ich bin die Schneeberg-Göttin, der Goldene Apfel ist mein Zauberwerkzeug — ich kann keine Opfergabe sein!"
  },
  AvgDialog_145534_Content_53 = {
    Text = "Hast du vergessen, wer du bist? Lass mich dich erinnern, Caraboo — du bist niemand."
  },
  AvgDialog_145534_Content_54 = {
    Text = "Du bist keine Göttin, keine Prinzessin, keine Fee.\nDu bist nur ein Überbleibsel, das auf dem Schlachtfeld geboren wurde — ein Flüchtling, der nicht einmal mehr das Gesicht seiner Eltern kennt."
  },
  AvgDialog_145534_Content_55 = {
    Text = "Du hättest es längst wissen müssen … die Identitäten, die du dir selbst erdichtet hast, die Ehrungen, die du durch Täuschung erlangt hast … eines Tages würden sie sich hart und doppelt rächen."
  },
  AvgDialog_145534_Content_56 = {
    Text = "Heute ist es so weit."
  },
  AvgDialog_145534_Content_57 = {
    Text = "Der Berg öffnete seinen blutigen Rachen weit auf."
  },
  AvgDialog_145534_Content_58 = {
    Text = "<Change>Komm … in meinen Bauch … und werde … meine Stärke …"
  },
  AvgDialog_145534_Content_59 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_145534_Content_6 = {
    Text = "Übergebt eure Wünsche dem Berg, übergebt eure Begierden dem Berg."
  },
  AvgDialog_145534_Content_60 = {
    Text = "Der sanfte Hang wurde plötzlich steil, und Evelyn, nur noch wenige Dutzend Meter von der Gletscherspalte entfernt, warf alles Ballast von sich."
  },
  AvgDialog_145534_Content_61 = {
    Text = "Sie riss die Schnallen der Sauerstoffflasche auf, streifte die schweren Steigeisenstiefel ab und durchtrennte dann ohne zu zögern das einzige Hauptseil an ihrem Körper."
  },
  AvgDialog_145534_Content_62 = {
    Text = "Nichts konnte sie mehr aufhalten."
  },
  AvgDialog_145534_Content_63 = {
    Text = "Sie warf sich Gerade leichtfüßig, Fast ausgelassen, auf den in der Gletscherspalte schlafenden Geliebten."
  },
  AvgDialog_145534_Content_64 = {
    Text = "Mein Liebster, ich hole dich heim."
  },
  AvgDialog_145534_Content_65 = {
    Text = "Inmitten einer neuen Erschütterung umarmte Evelyn sanft die Gebeine ihres Geliebten."
  },
  AvgDialog_145534_Content_66 = {
    Text = "Im Sichtfeld des Sturzes öffnete der Schneeberg seinen gewaltigen Rachen und verschluckte jene kleine Gestalt, die einem Kirschsahnetörtchen glich."
  },
  AvgDialog_145534_Content_67 = {
    Text = "In einem einzigen Schluck in den Bauch der Berge."
  },
  AvgDialog_145534_Content_7 = {
    Text = "<BigShake:Der Berg wird euch zuhören und euch dann „antworten“!>"
  },
  AvgDialog_145534_Content_8 = {
    Text = "Im nächsten Moment begann der Berg von seinem Fundament aus plötzlich zu Surgen — der weiße Schnee rieselte ab, der gegliederte Körper wälzte und wand sich, erhob sich Stück für Stück wie ein brechender Gletscher."
  },
  AvgDialog_145534_Content_9 = {
    Text = "Der gesamte „Berg“ richtete sich donnernd auf, beugte sich herab, und jeder kriechende Zentimeter mahlte das Schneefeld darunter zu Staub."
  },
  AvgDialog_145535_Content_1 = {
    Text = "Gäste beim Fest"
  },
  AvgDialog_145535_Content_10 = {
    Text = "Lügen? Was ist schon dabei – wer lügt denn nicht?"
  },
  AvgDialog_145535_Content_11 = {
    Text = "Du kannst es erkennen, oder, %player%? Ich weiß, dass du Lügen riechen kannst, genau wie ich."
  },
  AvgDialog_145535_Content_12 = {
    Text = "<Yellow:Zum Glück konnte ich mich erfolgreich verstecken und ihrer Verfolgung entkommen.>"
  },
  AvgDialog_145535_Content_13 = {
    Text = "<Yellow:<Big:Nein...! Ich bin nicht müde! ICH GEHE NICHT!>>"
  },
  AvgDialog_145535_Content_14 = {
    Text = "<Yellow:Meine anderen Pflichten in dieser Welt haben vorübergehend ein Ende gefunden.>"
  },
  AvgDialog_145535_Content_15 = {
    Text = "Tinct hätte diese Nacht offensichtlich nicht überstanden, und doch entschied sie sich, ihre Krankheit zu verbergen – ist sie etwa keine Lügnerin?"
  },
  AvgDialog_145535_Content_16 = {
    Text = "Castor verschwieg von Anfang an, seit wir uns trafen, die Tatsache, dass er Flügel trägt – ist er etwa kein Lügner?"
  },
  AvgDialog_145535_Content_17 = {
    Text = "Wilhelm wollte offensichtlich etwas anderes. Etwas Persönliches. Aber er wollte es uns nicht sagen. Er ist also auch ein Lügner, nicht wahr?"
  },
  AvgDialog_145535_Content_18 = {
    Text = "Alle lügen, alle sind Lügner – warum richtet sich die Anschuldigung ausgerechnet gegen mich allein?"
  },
  AvgDialog_145535_Content_19 = {
    Text = "Aber Tinct wollte einfach nur ein bisschen weitergehen. Was Castors Flügel und Wilhelms geheimen Wunsch betrifft... das ist ihre Privatsache."
  },
  AvgDialog_145535_Content_2 = {
    Text = "Wer bist Du eigentlich?"
  },
  AvgDialog_145535_Content_20 = {
    Text = "Sie haben die Wahrheit nicht gesagt, aber sie wollten auch niemandem Schaden zufügen."
  },
  AvgDialog_145535_Content_21 = {
    Text = "Warum verstehst du es immer noch nicht — die Dinge, nach denen die Menschen in dieser Welt streben, sei es Stärke oder ein Herzenswunsch, sind wie dieser Apfel —"
  },
  AvgDialog_145535_Content_22 = {
    Text = "Jeder will ihn, jeder sucht verzweifelt danach …"
  },
  AvgDialog_145535_Content_23 = {
    Text = "Caraboo warf den Apfel achtlos in die Ferne, tat so, als würde sie ihn verfolgen, und ließ sich dann theatralisch in einen Schneehaufen fallen."
  },
  AvgDialog_145535_Content_24 = {Text = "Aber..."},
  AvgDialog_145535_Content_25 = {
    Text = "Für immer, für immer — nur eine begrenzte Anzahl von Menschen kann ihn bekommen."
  },
  AvgDialog_145535_Content_26 = {
    Text = "Und ich will sein ewiger, einziger Besitzer sein."
  },
  AvgDialog_145535_Content_27 = {
    Text = "Doch das Mittel, mit dem du dieses Ziel erreichst, ist Eine Lüge."
  },
  AvgDialog_145535_Content_28 = {
    Text = "Ja, ist Eine Lüge nicht genug?"
  },
  AvgDialog_145535_Content_29 = {
    Text = "Was euch hierher gelockt hat, ist kein großartiges oder erhabenes Ding wie Schicksal oder Götterkönig — es ist nur Eine Lüge, eine einzige Lüge!"
  },
  AvgDialog_145535_Content_3 = {
    Text = "Caraboo lachte leise auf."
  },
  AvgDialog_145535_Content_30 = {
    Text = "Ihr bringt der Gottheit Verehrung dar, und die Gottheit erhört eure Wünsche nach Laune. Das unterscheidet sich kaum von den Gottheiten der Menschenwelt."
  },
  AvgDialog_145535_Content_31 = {
    Text = "Gerade dieses Mal verlangt der Berg von euch… euer <RedItalic:Alles.>"
  },
  AvgDialog_145535_Content_32 = {
    Text = "Das werde ich nicht zulassen…!"
  },
  AvgDialog_145535_Content_4 = {
    Text = "Wer ich eigentlich bin?"
  },
  AvgDialog_145535_Content_5 = {
    Text = "Habe ich euch das nicht von Anfang an gesagt? Ich bin die Göttin des Schneeberges, die Fee-Patin, die Verkörperung des Willens des Schneeberges."
  },
  AvgDialog_145535_Content_6 = {
    Text = "Das ist der allerwichtigste, allerniedlichste Wegweiser Caraboo, der euch jetzt Ihm zum Fraß vorwerfen wird."
  },
  AvgDialog_145535_Content_7 = {
    Text = "Caraboo… Du hast uns belogen."
  },
  AvgDialog_145535_Content_8 = {
    Text = "Du hast Evelyn getäuscht, die dich auf dem ganzen Weg fürsorglich begleitet hat, und du hast %player% getäuscht, der in dem Streit für dich gekämpft hat, damit du bleiben durftest."
  },
  AvgDialog_145535_Content_9 = {
    Text = "Ist das das Ergebnis, das Du angestrebt hast?"
  },
  AvgDialog_145862_Content_1 = {Text = "Caraboo…"},
  AvgDialog_145862_Content_2 = {
    Text = "Was du gerade gesagt hast… war das die Wahrheit?"
  },
  AvgDialog_145862_Content_3 = {
    Text = "Was denkst du?"
  },
  AvgDialog_145862_Content_4 = {
    Text = "Ich weiß nicht..."
  },
  AvgDialog_145862_Content_5 = {
    Text = "Dann denk nicht weiter darüber nach. Pass auf, dort kommen Feinde!"
  },
  AvgDialog_146405_Content_1 = {
    Text = "Lasst mich durch, ich muss ihn finden!"
  },
  AvgDialog_146405_Content_2 = {
    Text = "Pollux ruft mich!"
  },
  AvgDialog_146516_Content_1 = {
    Text = "Verdammt, lassen sich diese Eiterbeulen nicht einfrieren?"
  },
  AvgDialog_146516_Content_10 = {
    Text = "Bis dahin hatte niemand auf die Schätze geachtet, von denen Caraboo gesprochen hatte."
  },
  AvgDialog_146516_Content_11 = {
    Text = "Schließlich enthielt keine einzige Legende ein solches Element."
  },
  AvgDialog_146516_Content_12 = {
    Text = "Sie sagten nur, wenn du den Gipfel erreichst, wird dein Wunsch erfüllt."
  },
  AvgDialog_146516_Content_13 = {Text = "Erledigt."},
  AvgDialog_146516_Content_14 = {
    Text = "Als Helots Kugelkette also an euch allen vorbeifegt und die Gepäckstücke jedes Einzelnen einhakt, hat das niemand von euch vorhergesehen."
  },
  AvgDialog_146516_Content_15 = {
    Text = "Nur unzählige golden glänzende Schokoladenmünzen fliegen aus den Rissen der Beutel heraus und rieseln die Felswand hinunter."
  },
  AvgDialog_146516_Content_16 = {
    Text = "Wie ein strahlender goldener Regen."
  },
  AvgDialog_146516_Content_17 = {
    Text = "<Shake:Tinct… Castor…>"
  },
  AvgDialog_146516_Content_18 = {
    Text = "Du weißt nicht, was du verloren hast.\nAber ihr habt sicher etwas verloren, etwas sehr Wichtiges."
  },
  AvgDialog_146516_Content_19 = {
    Text = "Nicht aufgeben! Sie will noch zum Altar auf dem Gipfel!"
  },
  AvgDialog_146516_Content_2 = {
    Text = "Hmph, sie sind von klein auf im Schnee aufgewachsen."
  },
  AvgDialog_146516_Content_20 = {
    Text = "Bevor das Ritual endet, habt ihr noch eine Chance!"
  },
  AvgDialog_146516_Content_21 = {
    Text = "Caraboo fasst als Erste neuen Mut und beginnt zu klettern, ohne den Kopf zu senken, um euch zu rufen."
  },
  AvgDialog_146516_Content_22 = {
    Text = "Aus unbekanntem Grund siehst du in ihren Augen eine Freude, deren Ursprung du nicht kennst."
  },
  AvgDialog_146516_Content_23 = {
    Text = "Hör auf Caraboo."
  },
  AvgDialog_146516_Content_24 = {
    Text = "Und Helot: Kette… wir sehen uns auf dem Gipfel."
  },
  AvgDialog_146516_Content_25 = {
    Text = "In der Ferne taucht die Silhouette des Schneeberg-Gipfels zwischen den Wolken auf und verschwindet wieder."
  },
  AvgDialog_146516_Content_26 = {
    Text = "-Höhe 7950 m-"
  },
  AvgDialog_146516_Content_3 = {
    Text = "Die Kugelketten schwingen durch die Luft, du und Wilhelm schützt Evelyn und Naraka, doch ihr kommt kaum hinterher."
  },
  AvgDialog_146516_Content_4 = {
    Text = "Caraboo versteckt sich irgendwo hinter einem Schneehaufen, der reine weiße Schnee verbirgt ihre Gestalt."
  },
  AvgDialog_146516_Content_5 = {
    Text = "Findet ihr das nicht seltsam? Sie folgt uns, seit wir den Berg hinaufgestiegen sind."
  },
  AvgDialog_146516_Content_6 = {
    Text = "Warum startet sie erst jetzt plötzlich einen Angriff?"
  },
  AvgDialog_146516_Content_7 = {
    Text = "<Shake:Wenn ihr Ziel nicht ist, uns zu töten, sondern —>"
  },
  AvgDialog_146516_Content_8 = {
    Text = "Zu spät. Die wirbelnden Ketten trennen alle voneinander und lassen euch keine Zeit, euch um das schwere Gepäck zu kümmern."
  },
  AvgDialog_146516_Content_9 = {
    Text = "<Big:— unsere Schätze in den Händen!>"
  },
  AvgDialog_147080_Content_1 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_147080_Content_10 = {
    Text = "Ja, ja, ja, ich weiß. Aber ich kann es euch nicht sagen."
  },
  AvgDialog_147080_Content_100 = {
    Text = "Theseus fand mithilfe von Ariadnes Fadenknäuel den Weg aus dem Labyrinth, doch ihre Liebe stand nicht unter dem Segen der Schicksalsgöttin …"
  },
  AvgDialog_147080_Content_101 = {
    Text = "Schließlich schenkte der Weingott Dionysos Ariadne eine prächtige Krone, in die sieben strahlende Edelsteine gefasst waren."
  },
  AvgDialog_147080_Content_102 = {
    Text = "Wilhelm warf Caraboo einen kurzen Blick zu."
  },
  AvgDialog_147080_Content_103 = {
    Text = "Obwohl sie gemeinsam den Weg gegangen waren und Schwierigkeiten überwunden hatten, waren Theseus und Ariadne vielleicht von Anfang an nicht füreinander bestimmt."
  },
  AvgDialog_147080_Content_104 = {
    Text = "Caraboo wich Wilhelms Blick aus."
  },
  AvgDialog_147080_Content_105 = {
    Text = "Eine Leere Hülle, die ihre Aufgabe bereits erfüllt hat, gegen einen Wunsch einzutauschen, der das Schicksal umschreiben kann – findest du das nicht unvorteilhaft?"
  },
  AvgDialog_147080_Content_106 = {
    Text = "Unser Ziel beim Besteigen des Berges war es von Anfang an, durch diese Krone den Besitzer der Krone zu finden."
  },
  AvgDialog_147080_Content_107 = {
    Text = "Du kannst Caraboos Bewusstsein direkt lesen, und sie kann beobachten, ob wir lügen."
  },
  AvgDialog_147080_Content_108 = {
    Text = "Du kannst also sicher sein, dass ich jetzt die Wahrheit sage, stimmt's?"
  },
  AvgDialog_147080_Content_109 = {
    Text = "<Yellow:Mein Trumpf ist es, meine Karten offen auf den Tisch zu legen>."
  },
  AvgDialog_147080_Content_11 = {
    Text = "Du antwortest mit einem wütenden Blick."
  },
  AvgDialog_147080_Content_110 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_147080_Content_111 = {
    Text = "<Shake:Ha ha, hahaha!> Genau richtig — man kann diesen Mechanismus sogar umgekehrt nutzen. Mit klugen Leuten Geschäfte zu machen ist wirklich einfach."
  },
  AvgDialog_147080_Content_112 = {
    Text = "<Big:Macht euch bereit, eure Freiheit zurückzugewinnen!>"
  },
  AvgDialog_147080_Content_113 = {
    Text = "<Shake:Countdown: drei, zwei, eins —>"
  },
  AvgDialog_147080_Content_114 = {Text = "— Null."},
  AvgDialog_147080_Content_115 = {
    Text = "Die Fleischwände von allen Seiten drücken gleichzeitig auf euch ein, und die Schleimstoffe, die aus den Falten sickern, verwandeln sich in unzählige dünne, lange Tentakel, die Handgelenke, Knöchel und Taillen umschlingen."
  },
  AvgDialog_147080_Content_116 = {
    Text = "Moment mal, ist das nicht ein kleiner Unterschied zu der versprochenen Freiheit —"
  },
  AvgDialog_147080_Content_117 = {
    Text = "Ich habe nur versprochen, euch herauszubringen. Ich habe nie versprochen, dass die Reise angenehm sein würde."
  },
  AvgDialog_147080_Content_118 = {
    Text = "Eine unwiderstehliche Stärke steigt von unten empor."
  },
  AvgDialog_147080_Content_119 = {
    Text = "Wie ein verschluckter Fremdkörper werdet ihr rückwärts durch die Speiseröhre gedrückt und steigt rasend schnell durch einen engen, feuchten Tunnel aus Caro auf."
  },
  AvgDialog_147080_Content_12 = {
    Text = "Nicht böse sein, nicht böse sein, ich fange jetzt sofort mit der Erklärung an."
  },
  AvgDialog_147080_Content_120 = {
    Text = "Das Sichtfeld wird von Dunkelheit verschluckt. Im Ohr bleibt nur das klebrige Geräusch von Fleisch, das aneinander reibt, sowie der dumpfe, langgezogene Herzschlag des gesamten Berges."
  },
  AvgDialog_147080_Content_121 = {Text = "Dong."},
  AvgDialog_147080_Content_122 = {Text = "Dong."},
  AvgDialog_147080_Content_123 = {
    Text = "<Red:Bum —>"
  },
  AvgDialog_147080_Content_124 = {
    Text = "Als der letzte Herzschlag verhallt, reißt vor euch ein blendend weißes Licht auf."
  },
  AvgDialog_147080_Content_125 = {
    Text = "Sturm und Schnee wehen euch ins Gesicht."
  },
  AvgDialog_147080_Content_126 = {
    Text = "Jene Stärke schleudert euch mit einem Ruck hinaus, und ihr stürzt schwer in den kniehohen Schnee."
  },
  AvgDialog_147080_Content_127 = {
    Text = "Hust… dieses Ding rächt sich ganz offensichtlich."
  },
  AvgDialog_147080_Content_128 = {
    Text = "Immerhin hat es euch keine Reinigungsgebühr beim Auschecken berechnet. Gemessen an Seinen Gastgeberstandards ist das schon als großzügig zu bezeichnen."
  },
  AvgDialog_147080_Content_129 = {
    Text = "Du stützt dich auf den Schnee und stehst auf. Der hartnäckige Blutgeschmack in deiner Lunge wird endlich vom beißenden Kältewind vertrieben."
  },
  AvgDialog_147080_Content_13 = {
    Text = "Um zu besprechen, wie wir hier herauskommen, müssen wir zunächst wissen, wo wir uns befinden und warum wir hier sind."
  },
  AvgDialog_147080_Content_130 = {
    Text = "Dies ist nicht mehr der Bergrücken, von dem ihr gekommen seid."
  },
  AvgDialog_147080_Content_131 = {
    Text = "Soweit das Auge reicht, versinken alle niedrigeren Gipfel im Wolkenmeer. Der pechschwarze Himmel wirkt so nah, als ob man ihn berühren könnte, und die Sterne flackern hinter dem vom Wind aufgewirbelten Schneeschleier auf und ab."
  },
  AvgDialog_147080_Content_132 = {
    Text = "Ihr steht auf dem höchsten Gipfel der gesamten Bergkette."
  },
  AvgDialog_147080_Content_133 = {
    Text = "Hier ist..."
  },
  AvgDialog_147080_Content_134 = {
    Text = "Der wahre Berggipfel."
  },
  AvgDialog_147080_Content_135 = {
    Text = "Eine Stimme drang unter dem Schnee hervor."
  },
  AvgDialog_147080_Content_136 = {
    Text = "Die Eisschicht begann leicht zu zittern, als ob dieser Schneegipfel nichts weiter wäre als ein freiliegender Knochen eines gewaltigen Wesens."
  },
  AvgDialog_147080_Content_137 = {
    Text = "Der Ritualort liegt direkt vor euch. Legt die sieben Zauberobjekte an ihre vorgesehenen Plätze zurück, und das Zauberfeld wird euch zeigen, was als Nächstes zu tun ist."
  },
  AvgDialog_147080_Content_138 = {
    Text = "Kommst du nicht mit uns?"
  },
  AvgDialog_147080_Content_139 = {
    Text = "Ich bin überall."
  },
  AvgDialog_147080_Content_14 = {
    Text = "Wir befinden uns im Bauch des Bergwurms, und der Grund, warum der Bergwurm das Wunschritual benutzte, um euch alle hierher zu locken..."
  },
  AvgDialog_147080_Content_140 = {
    Text = "Ein tiefes Lachen drang von unten herauf."
  },
  AvgDialog_147080_Content_141 = {
    Text = "Der gesamte Berg ist meine Hülle. Jeden Schritt, den ihr macht, setzt ihr auf meinem Fleisch."
  },
  AvgDialog_147080_Content_142 = {
    Text = "Also hegt keinen Wahn, irgendwelche lächerlichen Tricks zu spielen."
  },
  AvgDialog_147080_Content_143 = {
    Text = "Geht voran. Lasst mich sehen, welche Tür ihr, beladen mit so vielen Wünschen, am Ende für mich öffnen werdet."
  },
  AvgDialog_147080_Content_144 = {
    Text = "Der Schnee teilt sich langsam vor euch."
  },
  AvgDialog_147080_Content_145 = {
    Text = "Eine alte Steintreppe, die seit unzähligen Jahren vom Wind und Schnee begraben war, kommt zum Vorschein und windet sich hinauf zum Gipfel."
  },
  AvgDialog_147080_Content_146 = {
    Text = "Am Ende der Steintreppe leuchten nacheinander sieben gedämpfte goldene Lichter auf — wie Augen, die seit tausend Jahren geschlummert haben und endlich auf jene warten, die sie zur Erweckung bringen."
  },
  AvgDialog_147080_Content_147 = {
    Text = "Wilhelm betrat als Erster die Steintreppe."
  },
  AvgDialog_147080_Content_148 = {
    Text = "Seine Hand lag die ganze Zeit an der Innenseite seines Mantels — als ob er einen Wunsch beruhigte, der längst aufgegeben worden war."
  },
  AvgDialog_147080_Content_149 = {
    Text = "In diesem Moment bemerkte niemand, dass der Schlüssel, der seit Jahren in Stille gelegen hatte, durch den Stoff hindurch ein äußerst feines Zittern von sich gab."
  },
  AvgDialog_147080_Content_15 = {
    Text = "… war, um eure Stärke zu verschlingen."
  },
  AvgDialog_147080_Content_150 = {
    Text = "Als ob irgendetwas auf dem Gipfel auf ihn wartete."
  },
  AvgDialog_147080_Content_16 = {
    Text = "Eine klare und verständliche Erklärung."
  },
  AvgDialog_147080_Content_17 = {
    Text = "Dann ist die Stärke der anderen Bergsteiger …"
  },
  AvgDialog_147080_Content_18 = {
    Text = "… in diesen wenigen Opfergaben enthalten."
  },
  AvgDialog_147080_Content_19 = {
    Text = "Der Kooperationsmechanismus zwischen Caraboo und dem Bergwurm besteht darin, dass sie Opfergaben mit starken Wünschen und Spiritualität auswählt und die Betreffenden dazu verleitet, die Berge zu betreten."
  },
  AvgDialog_147080_Content_2 = {
    Text = "Also, mein Herr, welche Laune hat Euch dazu bewogen, einen Sherpa-Bergführer zu spielen? Doch wohl nicht die Liebe zu menschlichen Extremsportarten?"
  },
  AvgDialog_147080_Content_20 = {
    Text = "Jetzt stellt sich die Frage: Warum hat der Bergwurm diese Zusammenarbeit von sich aus gebrochen?"
  },
  AvgDialog_147080_Content_21 = {
    Text = "Weil er wusste, dass ich ins Schwanken geraten war."
  },
  AvgDialog_147080_Content_22 = {
    Text = "Caraboo erwähnte das letzte Gespräch auf dem Bergrücken."
  },
  AvgDialog_147080_Content_23 = {
    Text = "Ich glaubte einst, dass niemand die Gier bezähmen kann und dass man sich auf „nicht-menschliche Dinge\" verlassen muss, um Wünsche zu erfüllen. Aber sie hat mir gezeigt, dass man auch im Gewöhnlichen Glück finden kann."
  },
  AvgDialog_147080_Content_24 = {
    Text = "In jenem Moment entstand in mir ein unnötiger „Wunsch\"."
  },
  AvgDialog_147080_Content_25 = {
    Text = "„Wünsche\" sind Köder, sind Zündschnüre."
  },
  AvgDialog_147080_Content_26 = {
    Text = "Von Anfang an war ich der „Goldene Apfel\", der dazu bestimmt war, verschluckt zu werden."
  },
  AvgDialog_147080_Content_27 = {
    Text = "Wie können wir sicherstellen, dass du uns nicht wieder belügst?"
  },
  AvgDialog_147080_Content_28 = {
    Text = "Glaub es oder nicht. Von uns allen hasse ich den Berg-Wurm am meisten."
  },
  AvgDialog_147080_Content_29 = {
    Text = "Wenn der Berg-Wurm mich nicht in jener Schneenacht verführt und mich dazu gebracht hätte, Das Testament mit ihm zu schließen … wäre ich diesen Weg heute nie gegangen."
  },
  AvgDialog_147080_Content_3 = {
    Text = "Würdest du mir glauben, wenn ich sagte, ich spreche für die Sherpa?"
  },
  AvgDialog_147080_Content_30 = {
    Text = "<Small:Elender Schwindler>."
  },
  AvgDialog_147080_Content_31 = {
    Text = "In der kurzen Stille war nur das widerliche Atemgeräusch der Fleischwände zu hören, die sich hoben und senkten."
  },
  AvgDialog_147080_Content_32 = {
    Text = "Verstanden. Solange du keine Grenzen überschreitest, werden wir vergangene Angelegenheiten vorerst nicht zur Sprache bringen."
  },
  AvgDialog_147080_Content_33 = {
    Text = "Was jetzt dringlicher ist: einen Weg zu finden, den Magen dieser Gottheit zu verlassen … am besten ohne die Stärke jenes Herrn N in Anspruch zu nehmen."
  },
  AvgDialog_147080_Content_34 = {
    Text = "Na, na, na — verschmäht ihr wirklich so die guten Absichten des liebenswürdigen Herrn N?"
  },
  AvgDialog_147080_Content_35 = {
    Text = "Oder glaubt ihr allen Ernstes, aus Seinem Bauch herauszuspazieren sei so einfach wie das Auschecken aus einem unbefriedigenden Hotelzimmer?"
  },
  AvgDialog_147080_Content_36 = {
    Text = "Du hast gesagt, du kannst es uns nicht sagen."
  },
  AvgDialog_147080_Content_37 = {
    Text = "Meint ihr, ich verberge es absichtlich vor euch? Da tut ihr mir aber Unrecht."
  },
  AvgDialog_147080_Content_38 = {
    Text = "N spielte mit der Rose, die wie aus dem Nichts zwischen seinen Fingern erschienen war, und richtete seinen Blick gemächlich auf Caraboo."
  },
  AvgDialog_147080_Content_39 = {
    Text = "Egal welchen Weg ich kenne — ich darf ihn dich nicht wissen lassen. Stimmt's, kleine Lügnerin?"
  },
  AvgDialog_147080_Content_4 = {
    Text = "Natürlich, ich glaube nicht nur das, ich glaube auch, dass Frau Sorel das Prinzip des Nicht-Eingreifens befürwortet, dass Ryker dem Glücksspiel für immer den Rücken gekehrt hat und nie wieder eine Wette eingeht, dass Erica von menschlicher Güte durchdrungen ist und mit Worten zu bezaubern weiß …"
  },
  AvgDialog_147080_Content_40 = {
    Text = "Caraboo widersprach nicht. Sie biss sich gerade fest auf die Unterlippe und wich den Blicken aller aus."
  },
  AvgDialog_147080_Content_41 = {Text = "Caraboo?"},
  AvgDialog_147080_Content_42 = {
    Text = "… Es kann mich hören."
  },
  AvgDialog_147080_Content_43 = {
    Text = "Das ist keine Metapher. Als ich mit sechs Jahren in jener Schneenacht mit ihm fortging, verpfändete ich ihm meine Seele."
  },
  AvgDialog_147080_Content_44 = {
    Text = "Das ist Das Testament zwischen ihm und mir. Es leiht mir die Stärke der „Eine Lüge\", sodass ich jeden Menschen auf der Welt täuschen kann; doch als Preis dafür —"
  },
  AvgDialog_147080_Content_45 = {
    Text = "kann ich vor ihm keinen einzigen Gedanken verbergen."
  },
  AvgDialog_147080_Content_46 = {
    Text = "… Also … jedes Wort, das wir in diesem Moment sagen —"
  },
  AvgDialog_147080_Content_47 = {
    Text = "Solange es in meine Ohren fällt und in meinen Kopf gelangt, weiß es alles davon."
  },
  AvgDialog_147080_Content_48 = {
    Text = "Das Fleisch ringsum spannte sich für einen Moment scharf an und erschlaffte dann langsam wieder. Als würde ein gewaltiges Wesen hinter dem Vorhang lauern und all dem mit großem Interesse lauschen."
  },
  AvgDialog_147080_Content_49 = {
    Text = "Versteht ihr es jetzt?"
  },
  AvgDialog_147080_Content_5 = {
    Text = "Jetzt ist nicht die Zeit für Streitereien."
  },
  AvgDialog_147080_Content_50 = {
    Text = "Es hat immer einen Weg gegeben. Aber wenn es auch nur bis zu den Ohren dieser jungen Dame dringt, könnten Sie genauso gut Texas Hold'em spielen und Ihre Trumpfkarten offen auf den Tisch legen."
  },
  AvgDialog_147080_Content_51 = {
    Text = "Wenn wir den Plan besprechen — soll Caraboo dann kurz ausweichen?"
  },
  AvgDialog_147080_Content_52 = {
    Text = "Selbst wenn ich euren Plan nicht höre, könnte ich beim Ausführen eine Unregelmäßigkeit bemerken."
  },
  AvgDialog_147080_Content_53 = {
    Text = "Ich darf deine Mimik nicht sehen, deine kleinen Gesten. Sonst würde ich wissen, welcher Satz Eine Lüge ist."
  },
  AvgDialog_147080_Content_54 = {
    Text = "Vielleicht könntest du einfach nicht hinsehen?"
  },
  AvgDialog_147080_Content_55 = {
    Text = "Nein, Eine Lüge ist eine fließende Atmosphäre … und ich bin bereits viel zu lange darin eingetaucht."
  },
  AvgDialog_147080_Content_56 = {
    Text = "Manchmal, selbst wenn niemand spricht, kann ich aus der erstarrten Luft heraus das Vorhandensein einer Lüge spüren."
  },
  AvgDialog_147080_Content_57 = {
    Text = "Lass mich es versuchen."
  },
  AvgDialog_147080_Content_58 = {
    Text = "Begleitet von einem hellen Fingerschnippen steigt schwarzer Rauch über Caraboos Augenlider."
  },
  AvgDialog_147080_Content_59 = {
    Text = "Gut, öffne die Augen."
  },
  AvgDialog_147080_Content_6 = {
    Text = "Arachne hat uns hierher geführt — das hat sicher seinen Grund. Und du bist wohl ein Glied in der Kette des Schicksals."
  },
  AvgDialog_147080_Content_60 = {
    Text = "Caraboo öffnete die Augen. Alles vor ihr war von einem verzerrten Nebel überzogen, selbst die Geräusche wurden undeutlich und weit entfernt."
  },
  AvgDialog_147080_Content_61 = {
    Text = "William hingegen senkte plötzlich den Blick, die Knöchel ans Kinn gestützt, als würde er eine Schlussfolgerung über ein Schachspiel ziehen, das nur er sehen konnte."
  },
  AvgDialog_147080_Content_62 = {Text = "Halt."},
  AvgDialog_147080_Content_63 = {Text = "Hm?"},
  AvgDialog_147080_Content_64 = {
    Text = "Es ist nicht nötig, ihr die Augen zu verdecken."
  },
  AvgDialog_147080_Content_65 = {
    Text = "Ganz im Gegenteil — ich hoffe, Caraboo, dass du von nun an mit höchster Aufmerksamkeit jeden meiner Sätze auf seinen Wahrheitsgehalt prüfst."
  },
  AvgDialog_147080_Content_66 = {
    Text = "Hör gut zu, Caraboo — oder vielmehr: Bergwurm hinter Caraboo. Ich möchte einen Handel mit dir abschließen."
  },
  AvgDialog_147080_Content_67 = {
    Text = "Die Fleischwand zitterte wie in spottendem Gelächter."
  },
  AvgDialog_147080_Content_68 = {
    Text = "Lächerlich — ihr befindet euch in meinem Bauch. Was willst Du mir anbieten?"
  },
  AvgDialog_147080_Content_69 = {
    Text = "Einen Wunsch."
  },
  AvgDialog_147080_Content_7 = {
    Text = "Du weißt bestimmt, wie wir hier rauskommen, oder, N?"
  },
  AvgDialog_147080_Content_70 = {
    Text = "Plötzlich wurde es ringsum still."
  },
  AvgDialog_147080_Content_71 = {
    Text = "Das Wunscharray auf dem Gipfel wurde <Yellow:nicht von Dir erschaffen>, sondern ist etwas Uraltes, das älter ist als Du — stimmt's?"
  },
  AvgDialog_147080_Content_72 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_147080_Content_73 = {
    Text = "Der Bergwurm schwieg einen Moment, dann ließ er ein unverbindliches leises Lachen vernehmen."
  },
  AvgDialog_147080_Content_74 = {
    Text = "Interessant. Fahre fort."
  },
  AvgDialog_147080_Content_75 = {
    Text = "Vor diesem Aufstieg erzählte Caraboo eine Legende, die sich etwas von der unter den Bergbewohnern kursierenden unterschied. Kurz gesagt: Die Bergbewohner wissen nur, dass man sich auf dem Gipfel einen Wunsch erfüllen kann — von der Existenz der sieben Ritualgeräte wissen sie nichts."
  },
  AvgDialog_147080_Content_76 = {
    Text = "Das ist nachvollziehbar. Wenn das Ziel nur darin besteht, Menschen zum Aufstieg zu verleiten und sie dann zu Verschlingen, besteht keine Notwendigkeit, die Legende der sieben Ritualgeräte zu weben."
  },
  AvgDialog_147080_Content_77 = {
    Text = "Man muss nur allen sagen, dass der Gipfel Wünsche erfüllt."
  },
  AvgDialog_147080_Content_78 = {
    Text = "Je schwieriger, desto weniger Herausforderer — diese einfache Logik könnt ihr nicht ignorieren, es sei denn —"
  },
  AvgDialog_147080_Content_79 = {
    Text = "Es sei denn —"
  },
  AvgDialog_147080_Content_8 = {
    Text = "Ich weiß es… oder auch nicht… Ach, das ist wirklich eine interessante Frage."
  },
  AvgDialog_147080_Content_80 = {
    Text = "Der Bergwurm zog die Silben auf höhnisch-spöttische Weise in die Länge."
  },
  AvgDialog_147080_Content_81 = {
    Text = "Es sei denn, die sieben Ritualgeräte existieren wirklich, und das Ritual zur Wunscherfüllung existiert ebenfalls wirklich."
  },
  AvgDialog_147080_Content_82 = {
    Text = [[
Und Du lagerst neben dem Array nicht nur, um die Bergsteiger zu Verschlingen.
Du wartest ebenso auf eine Gelegenheit, das Ritual in Gang zu setzen.]]
  },
  AvgDialog_147080_Content_83 = {
    Text = "Die Fleischwelt hielt den Atem an."
  },
  AvgDialog_147080_Content_84 = {
    Text = "Wenn Du das Ritual die ganze Zeit bewacht hast — warum hast Du es nicht selbst gestartet?"
  },
  AvgDialog_147080_Content_85 = {
    Text = "Mensch, Du stellst zu viele Fragen."
  },
  AvgDialog_147080_Content_86 = {
    Text = "Es scheint, als hätte ich die richtige Frage gestellt."
  },
  AvgDialog_147080_Content_87 = {
    Text = "Lass mich raten."
  },
  AvgDialog_147080_Content_88 = {
    Text = "Im Zauberkreis existiert ein Kern, den du nicht entschlüsseln kannst, stimmt's? Also hast du all die Jahre Opfergabe um Opfergabe angehäuft, konntest aber die letzte Tür nie öffnen."
  },
  AvgDialog_147080_Content_89 = {
    Text = "Die Fleischwand zog sich plötzlich zusammen und drohte, alle zu zermalmen."
  },
  AvgDialog_147080_Content_9 = {
    Text = "Kein Drumherumreden, komm direkt zum Punkt."
  },
  AvgDialog_147080_Content_90 = {
    Text = "Ich weiß, warum du ihn nicht entschlüsseln kannst. Ich habe gerade einen kurzen Blick auf den Zauberkreis geworfen – die darauf eingravieren Runen enthalten Latein und andere alte Schriftzeichen."
  },
  AvgDialog_147080_Content_91 = {
    Text = "Und diese deine … kleine Executor – nach der Zeit, die seit ihrem Verlassen des Zuhauses vergangen ist, hat sie offensichtlich keine ordentliche Schulbildung genossen …"
  },
  AvgDialog_147080_Content_92 = {
    Text = "<Shake:Ja, tut mir leid, dass ich nicht lesen kann! Na und?!>"
  },
  AvgDialog_147080_Content_93 = {
    Text = "Die Zeit war knapp, ich hatte gerade keine Gelegenheit, es ausführlich zu lesen, bevor du mich hier hineingeschluckt hast. Aber ich vermute, dass darin größtenteils Wissen über die Aktivierung des Zauberkreises aufgezeichnet ist."
  },
  AvgDialog_147080_Content_94 = {
    Text = "Die Schicksalsgöttin hat uns hierher geführt, die sieben großen Zauberobjekte sind versammelt – du solltest wissen, dass dies das Mal ist, an dem du deinem Wunsch am nächsten bist."
  },
  AvgDialog_147080_Content_95 = {
    Text = "Und wir können <Yellow:freiwillig auf die Möglichkeit verzichten, dem Berg einen Wunsch zu äußern>."
  },
  AvgDialog_147080_Content_96 = {
    Text = "Der Bergwurm verfiel in lange Stille. Als ihr schon glaubtet, er würde nicht mehr antworten, gab er ein leises Brummen von sich."
  },
  AvgDialog_147080_Content_97 = {
    Text = "Auf einen Wunsch verzichten … was für eine großartige Opfergabe. Du willst sicher mehr, als dass ich euch gehen lasse, oder?"
  },
  AvgDialog_147080_Content_98 = {
    Text = "Nach dem Ende des Rituals können alle anderen Zauberobjekte dir gehören, aber wir nehmen die <Blue:Krone der Ariadne> mit."
  },
  AvgDialog_147080_Content_99 = {
    Text = "Die Krone der Ariadne…"
  },
  AvgDialog_147095_Content_1 = {
    Text = "Im leeren Saal hallen nur deine und Murphys Schritte wider."
  },
  AvgDialog_149752_Content_1 = {
    Text = "Drachennest"
  },
  AvgDialog_149752_Content_10 = {
    Text = "Dir bleibt nichts mehr. Du kannst das Vergessen nicht noch einmal ertragen."
  },
  AvgDialog_149752_Content_11 = {
    Text = "Die tosenden Flammen wurden vom Regen gelöscht. Du passierst das unbewachte Tor und siehst nichts als Verwüstung."
  },
  AvgDialog_149752_Content_12 = {
    Text = "Die Burg steht in Stille — leere Ölfässer, zerrissene Jutesäcke, zerschmetterte Schilde, zerbrochene Speere, Pfeile wie Reihen von Schilf, das sich im Wind beugt, der rohe Gestank von nassem Schlamm vermischt mit dem anhaltenden Geruch von Brandruß."
  },
  AvgDialog_149752_Content_13 = {
    Text = "Hier tobte einst eine Schlacht. Nun bleiben nur Schatten zurück."
  },
  AvgDialog_149752_Content_14 = {
    Text = "Die Schatten breiten sich frei durch die Dunkelheit aus, erklimmen die hohen Mauern, kriechen über die Zinnen, verschlucken die über den Boden verstreuten Leiber und erzeugen dabei nasse, schmatzende Geräusche. Du versuchst, nicht daran zu denken, was das bedeutet."
  },
  AvgDialog_149752_Content_15 = {
    Text = "Folge den Schatten… folge einfach den Schatten…"
  },
  AvgDialog_149752_Content_16 = {
    Text = "H-hilf mir… hilf mir…"
  },
  AvgDialog_149752_Content_17 = {
    Text = "Ein schmerzerfülltes Stöhnen dringt unter einem verbogenen Helm hervor, Schatten klammern sich daran wie ein ergebener Liebhaber. Du fasst all deinen Mut zusammen und trittst vor."
  },
  AvgDialog_149752_Content_18 = {
    Text = "Derjenige, der die Schatten brachte — wohin ist er gegangen?"
  },
  AvgDialog_149752_Content_19 = {
    Text = "<Shake:Scha… Schatten? Nein, nein — das ist ein Monster! Schwarzes Blut… innen hohl… ein Todesritter… es ist wahr, alles ist wahr!>"
  },
  AvgDialog_149752_Content_2 = {
    Text = "Was ist ein Versprechen? Magie, die sich nicht erfüllt, solange man nicht daran glaubt."
  },
  AvgDialog_149752_Content_20 = {
    Text = "<Shake:Lauf… ugh… lauf! Ein unsterbliches Monster… Rache… Vernichtung… gurgel… gurgel gurgel…>"
  },
  AvgDialog_149752_Content_21 = {
    Text = "Ein dicker, zähflüssiger Laut dringt aus der Kehle des Monsters. Es zuckt wie ein an Land gespülter Fisch, doch sein Arm hebt sich langsam und streckt sich nach dem Bündel in deinen Armen aus. Ein sich windender, weicher Schleim sickert durch die Fugen seiner Rüstung."
  },
  AvgDialog_149752_Content_22 = {
    Text = "Es ist ein Schatten. Er will den Heiligen Gral."
  },
  AvgDialog_149752_Content_23 = {
    Text = "Nein, nein, das ist etwas Wichtiges. Ich kann es dir nicht geben."
  },
  AvgDialog_149752_Content_24 = {
    Text = "Weigerung ist zwecklos. Schatten strömen die Mauern herab und schließen sich rasch um dich. Du umklammerst das Bündel in panischer Angst und wendest dich zur Flucht tiefer in die Burg."
  },
  AvgDialog_149752_Content_25 = {
    Text = "Das Torhaus, die große Halle, die Kapelle — steinerne Treppen winden sich spiralförmig in die Erde hinab. Die Burg ist ein gefährliches Drachennest. Die Luft wird immer kälter, dein Keuchen und deine Schritte werden von den Steinmauern Schicht für Schicht verstärkt und klingen wie die eines völlig anderen Menschen."
  },
  AvgDialog_149752_Content_26 = {
    Text = "Eine Flamme flackert am Ende der Wendeltreppe, und du erblickst eine vertraute Gestalt."
  },
  AvgDialog_149752_Content_27 = {Text = "Og—"},
  AvgDialog_149752_Content_28 = {
    Text = "Du willst ihn freudig rufen, als du plötzlich bemerkst, dass ihr nicht allein seid. Das Monster spricht, bevor du es kannst."
  },
  AvgDialog_149752_Content_29 = {
    Text = "<Shake:Hust, hust, hust, hust… Ogier…>"
  },
  AvgDialog_149752_Content_3 = {
    Text = "Was ist Trennung? Der Moment nach der Ankunft."
  },
  AvgDialog_149752_Content_30 = {
    Text = "Wie bist du so geworden?"
  },
  AvgDialog_149752_Content_31 = {
    Text = "Mein… Aussehen?"
  },
  AvgDialog_149752_Content_32 = {
    Text = "Edler Wein und ein üppiges Mahl sind auf dem Tisch angerichtet, silbernes Besteck glänzt im Kerzenlicht. Wäre da nicht die eisige Kälte, die durch die Risse im Stein dringt, ließe diese sorgfältig arrangierte Tafel einen fast vergessen, dass man sich tief in einem finsteren Untergrund befindet."
  },
  AvgDialog_149752_Content_33 = {
    Text = "Der ausgezehrte Herr sitzt allein hinter dem Tisch, die Augen tief eingesunken, die Wangenknochen scharf und markant, begraben unter Lagen schwerer Seide — wie ein böser Drache, der auf seinem Schatz aus Gold und Silber kauert."
  },
  AvgDialog_149752_Content_34 = {
    Text = "Dein Ritter schreitet Schritt für Schritt auf es zu, ein langer Schatten folgt ihm. Vielleicht ist er selbst ein Schatten. Seine Kleider sind zerfetzt, sein Gesicht verzerrt und furchteinflößend, seine Schritte völlig lautlos."
  },
  AvgDialog_149752_Content_35 = {
    Text = "Wahrlich, hätte ich es nicht mit eigenen Augen gesehen, ich würde es kaum glauben… hust, hust, hust… Der jüngste Ritter des Herzogtums, zu einem Monster geworden."
  },
  AvgDialog_149752_Content_36 = {
    Text = "Das Herzogtum… ist bereits zerstört."
  },
  AvgDialog_149752_Content_37 = {
    Text = "Deinetwegen."
  },
  AvgDialog_149752_Content_38 = {
    Text = "Wegen des Krieges, wegen der Seuche, wegen der Gier der Nachbarnationen, wegen seiner eigenen Schwäche. Es gibt viele Gründe, warum ein Herzogtum fallen kann. Ich bin lediglich, hust hust, der unbedeutendste davon."
  },
  AvgDialog_149752_Content_39 = {
    Text = "<Shake:Du… hast das Herzogtum verraten… mit dem Feind gemeinsame Sache gemacht… dein eigenes Volk… verkauft…>"
  },
  AvgDialog_149752_Content_4 = {
    Text = "Was ist der Tod? Ein Morgen ohne Abschied."
  },
  AvgDialog_149752_Content_40 = {
    Text = "<Shake:Verräter… du verdienst den Tod.>"
  },
  AvgDialog_149752_Content_41 = {
    Text = "Ja, ja, wie du siehst, ist die bittere Frucht bereits auf mich gefallen. Mir bleibt nicht mehr viel Zeit, hust, hust, hust, hust."
  },
  AvgDialog_149752_Content_42 = {
    Text = "Die Seuche hat auch mich nicht verschont, Ogier. Der Tod — er macht keine Unterschiede. Er wartet geduldig auf der anderen Seite der Brücke auf jeden. Niemand kann ihm entkommen… außer dir."
  },
  AvgDialog_149752_Content_43 = {
    Text = "Sag mir, welchen Pakt hast du mit dem Teufel geschlossen?"
  },
  AvgDialog_149752_Content_44 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_149752_Content_45 = {
    Text = "Der Preis, dem Tod zu entkommen, wird stets schwerer wiegen als der Tod selbst. Todesritter… sein Henker zu werden — war das ein Wunsch, den du geäußert hast, oder eine Strafe, die du empfangen hast?"
  },
  AvgDialog_149752_Content_46 = {
    Text = "Ogier, der treueste, frömmste Ritter des Herzogtums, hah, <Shake:hust hust hust hust hust……>"
  },
  AvgDialog_149752_Content_47 = {
    Text = "Ich bin ein verdammter Verräter — aber bist du etwa anders?"
  },
  AvgDialog_149752_Content_48 = {Text = "!!"},
  AvgDialog_149752_Content_49 = {
    Text = "Ein unsichtbarer Blitz trifft deinen Ritter und nagelt ihn fest an Ort und Stelle. Die Schatten in der Dunkelheit zittern heftig — vor Freude oder Wut, sie können sich nicht länger beherrschen."
  },
  AvgDialog_149752_Content_5 = {
    Text = "Was ist Vergessen?"
  },
  AvgDialog_149752_Content_50 = {
    Text = "Ich habe den Großherzog verraten, aber du — du und deine Prinzessin — ihr habt Gott verraten."
  },
  AvgDialog_149752_Content_51 = {
    Text = "Du erinnerst dich noch… du wagst es, das anzusprechen…"
  },
  AvgDialog_149752_Content_52 = {
    Text = "<Red:Die Hexenprinzessin>, hust hust hust, wie ironisch — ihre Tricks wurden schließlich entlarvt, und doch erinnert sich niemand mehr an ihren Namen. Ich habe es längst gesagt: Liefert sie aus, und die Kriegsflammen wären erloschen, das Herzogtum wäre nicht gefallen."
  },
  AvgDialog_149752_Content_53 = {
    Text = "Du weißt, was sie über uns gebracht hat — du weißt es nur zu gut. Der Fluch… der Krieg begann seinetwegen und endete seinetwegen. Dank ihr @3wurde das Herzogtum zu einem vergessenen Ort."
  },
  AvgDialog_149752_Content_54 = {
    Text = "Halt den Mund! Du… bist nicht würdig… ihren Namen auszusprechen!"
  },
  AvgDialog_149752_Content_55 = {
    Text = "Die formlose Lanze spaltet den langen Tisch entzwei; Becher und Teller stürzen zu Boden, das falsche Bankett zerbricht, und das Wrack darunter kommt zum Vorschein."
  },
  AvgDialog_149752_Content_56 = {
    Text = "Die Schatten strecken zähflüssige Pseudopodien aus und verschlingen gierig alles, was sie berühren; Sümpfe quellen aus lichtlosen Tiefen hervor, und die Welt beginnt zu versinken."
  },
  AvgDialog_149752_Content_57 = {
    Text = "Tod… und dann Vergessenheit… als wäre es nie geschehen. Das ist das Schicksal derer, die Gott verlassen."
  },
  AvgDialog_149752_Content_58 = {
    Text = "Sie war es, die dich in diesen Zustand versetzt hat, nicht wahr… das gesamte Herzogtum ins Nichts gerissen und dann eine Puppe des Hasses zurückgelassen, um wahren Tod über das Land zu verbreiten. Nennst du es Loyalität, eine solche Mission zu erfüllen?"
  },
  AvgDialog_149752_Content_59 = {
    Text = "Ogier… wem dienst du wirklich?"
  },
  AvgDialog_149752_Content_6 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_149752_Content_60 = {
    Text = "<Shake:Nein… nein… die Prinzessin ist nicht… gluck… gluck gluck……>"
  },
  AvgDialog_149752_Content_61 = {
    Text = "Dein Ritter hält sich vor Schmerz den Kopf; Schatten strömen aus seiner Brust, seinen Ohren, den Augenwinkeln. Die unerbittliche Qual des Dämons hat ihn geschwächt — er kann keinen Laut mehr von sich geben, wie eine Tonfigur, die sich in schwarzem Wasser auflöst."
  },
  AvgDialog_149752_Content_62 = {
    Text = "Während keiner von euch aufpasste, drehte der Herr seinen Rollstuhl zur Seite und enthüllte ein faustgroßes Schießschartenloch, das in der Steinmauer hinter ihm verborgen war. Ein schwarzer Schatten blitzt wie eine Schlange vorbei, begleitet von einem dumpfen Aufprall — eine eiserne Lanze durchbohrt deinen Ritter durch die Brust."
  },
  AvgDialog_149752_Content_63 = {
    Text = "<Big:Ogier!!!>"
  },
  AvgDialog_149752_Content_64 = {
    Text = "<Shake:Hust hust hust hust……>Ein Monster, das aus seinem Grab gekrochen ist, kehrt am besten schleunigst dorthin zurück."
  },
  AvgDialog_149752_Content_65 = {
    Text = "Du und dein kleines Monster könnt hier zusammen begraben werden."
  },
  AvgDialog_149752_Content_66 = {
    Text = "Mehrere vollständig bewaffnete Wachen traten aus dem Geheimgang hervor, ihre Schilde und Schwerter glänzten in einem unheilvollen Licht — die letzte Falle hatte sich endlich enthüllt."
  },
  AvgDialog_149752_Content_7 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_149752_Content_8 = {
    Text = "<Red:Ein Fluch.>"
  },
  AvgDialog_149752_Content_9 = {
    Text = "Ein Fluch. Eine Plage. Eine Strafe. Eine von Würmern ausgehöhlte Leere. Ein zerbrochenes Flussbett. Verrottend in der Stille. Verwitternd. Versinkend. Ein Blick, der ins Nichts verblasst. Aus der Geschichte in den Schatten gleitend. Der endgültige Tod."
  },
  AvgDialog_149753_Content_1 = {
    Text = "Heiliger Kelch"
  },
  AvgDialog_149753_Content_10 = {
    Text = "Nichts, was ich getan habe, entspricht dem Handeln eines Ritters. Das hast du selbst gesehen."
  },
  AvgDialog_149753_Content_11 = {
    Text = "Warum? Ein Ritter soll Monster bekämpfen — das ist deine Pflicht, und du hast sie gut erfüllt."
  },
  AvgDialog_149753_Content_12 = {
    Text = "Und du suchst nach etwas, nicht wahr? Ich kann es erkennen. Du durchsuchst Ort für Ort, seit wir die Stadt betreten haben — es sind schon Tage vergangen. Hat das Monster dir auch etwas genommen?"
  },
  AvgDialog_149753_Content_13 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_149753_Content_14 = {
    Text = "\"Wir sind hier.\""
  },
  AvgDialog_149753_Content_15 = {
    Text = "Warmes, bernsteinfarbenes Kerzenlicht erfüllte die Wände ringsum, und die Eichentüren hielten den kalten Wind fern. Für Wanderer ohne Heimat konnte das in einer Regennacht geöffnete Lagerhaus des Klosters sogar Leben retten."
  },
  AvgDialog_149753_Content_16 = {
    Text = "Doch du ließt dich nicht von der Illusion täuschen — du erinnertest dich an sie. Jene, die mit Kerzenleuchtern hin und her eilten, schwarze Roben, Messinganhänger, Henker, die sich selbst Hirten nannten — sie waren Monster unter Monstern."
  },
  AvgDialog_149753_Content_17 = {
    Text = "<Small:Warum sind wir hierhergekommen… ist das, wonach du suchst, dort drinnen?>"
  },
  AvgDialog_149753_Content_18 = {
    Text = "Bleib hier und warte auf mich. Folg mir nicht."
  },
  AvgDialog_149753_Content_19 = {
    Text = "<Big:Was?! Nein! Auf keinen Fall!>"
  },
  AvgDialog_149753_Content_2 = {
    Text = "<Shake:Ich weiß es nicht, ich weiß nicht, was das war — nein, nein, nein, bitte, bitte habt Erbarmen——>"
  },
  AvgDialog_149753_Content_20 = {
    Text = "<Big:Ich bleibe nicht hier, ich weigere mich absolut, hier zu bleiben! Ich gehe mit dir!>"
  },
  AvgDialog_149753_Content_21 = {
    Text = "Was ist los? Kind, brauchst du Hilfe?"
  },
  AvgDialog_149753_Content_22 = {
    Text = "Ja, bitte pass auf sie auf. Lass sie nicht weglaufen."
  },
  AvgDialog_149753_Content_23 = {
    Text = "Oh… es ist so spät, und der Regen strömt herab — wohin eilst du in solcher Hast? Warte bis zum Sonnenaufgang und lass deine kleine Schwester nicht allein hier."
  },
  AvgDialog_149753_Content_24 = {
    Text = "Ich hole sie bei Tagesanbruch ab."
  },
  AvgDialog_149753_Content_25 = {
    Text = "Wenn du darauf bestehst, dann gut, gut. Armes Kind, bis auf die Knochen durchnässt, komm her, komm zu mir, lass mich dein Gesicht abwischen."
  },
  AvgDialog_149753_Content_26 = {
    Text = "Du bist gefangen, kannst dich nicht bewegen, trockenes Leinentuch wischt über deine Wangen, und du weißt nicht, wann es deinen Mund und deine Nase bedecken könnte."
  },
  AvgDialog_149753_Content_27 = {
    Text = "Die Angst drückt dir die Brust zusammen, du kannst nicht atmen, du kannst nur schreien."
  },
  AvgDialog_149753_Content_28 = {
    Text = "<Shake:Komm zurück! Du bist mein Ritter, du sollst mich beschützen, du kannst mich nicht zurücklassen — du hast es mir versprochen!>"
  },
  AvgDialog_149753_Content_29 = {
    Text = "<Shake:Bitte, ich werde keinen Ärger machen, lass mich mitkommen!>!"
  },
  AvgDialog_149753_Content_3 = {Text = "Ah!!"},
  AvgDialog_149753_Content_30 = {
    Text = "Viele Augen werden von deinem heiseren Schreien angezogen, manche wie Käfer, manche wie Ziegen, manche wie Eulen."
  },
  AvgDialog_149753_Content_31 = {
    Text = "Sie starren dich unverwandt an, als wärst du allein ohne Augen geboren worden."
  },
  AvgDialog_149753_Content_32 = {
    Text = "<SmallShake:Nicht… geh nicht… du hast es doch versprochen…>"
  },
  AvgDialog_149753_Content_33 = {
    Text = "<SmallShake:Bitte, lass mich nicht zurück…>"
  },
  AvgDialog_149753_Content_34 = {
    Text = "Ich habe meine Meinung geändert. Lass sie mitkommen."
  },
  AvgDialog_149753_Content_35 = {
    Text = "Du reißt den Kopf hoch — dein Ritter hat sich irgendwann umgedreht und verdeckt mit seinem Rücken die Blicke all der Monster."
  },
  AvgDialog_149753_Content_36 = {
    Text = "Aber wohin willst du sie bringen? Es gibt nicht viele Orte in der Stadt, um sich vor dem Regen zu schützen, und keiner davon ist für ein Kind geeignet."
  },
  AvgDialog_149753_Content_37 = {
    Text = "Wohin ich gehe, liegt nicht in der Stadt."
  },
  AvgDialog_149753_Content_38 = {
    Text = "Außerhalb der Stadt gibt es noch weniger — ah! Sag mir nicht, dass du zu diesem Herrenhaus gehst?"
  },
  AvgDialog_149753_Content_39 = {
    Text = "Was ist falsch an diesem Herrenhaus?"
  },
  AvgDialog_149753_Content_4 = {
    Text = "Die Schreie wurden vom strömenden Regen übertönt, vermischten sich mit Blut und rieselten in die Gosse am Fuß der Mauer, um dort gemeinsam mit Schlamm, Pferdemist und Gemüseabfällen zu verfaulen, bis sie von der dunklen Gasse verschluckt wurden."
  },
  AvgDialog_149753_Content_40 = {
    Text = "Dieser Ort, dieser Ort… seufz, ihr zwei seid auch Flüchtlinge, nicht wahr? Kind, halte dich von dort fern."
  },
  AvgDialog_149753_Content_41 = {
    Text = "Dieser Herr — er war einst ein guter Mann, aber Krieg, Seuche und Unheil kamen und gingen wie Gezeiten, und die Menschen hörten auf, Menschen zu sein. Alle sagen, er sei wahnsinnig geworden. Immer weniger Menschen bleiben in der Stadt, und jene, die um Brot betteln gingen, kamen nie zurück."
  },
  AvgDialog_149753_Content_42 = {
    Text = "Der Herr möge vergeben… alle sagen, er esse heimlich Menschen."
  },
  AvgDialog_149753_Content_43 = {
    Text = "Monster fressen Menschen — das weißt du schon lange, also bist du nicht im Geringsten überrascht, noch ängstlich… zumindest nicht so ängstlich. Du hast deinen Ritter."
  },
  AvgDialog_149753_Content_44 = {
    Text = "Bleib dicht bei mir. Hier stimmt etwas nicht."
  },
  AvgDialog_149753_Content_45 = {
    Text = "Alright, alright."
  },
  AvgDialog_149753_Content_46 = {
    Text = "Das weitläufige Herrenhaus stand leer — keine Wachen, keine Diener, als wäre es seit Ewigkeiten verlassen. Nur das Geräusch deiner absichtlich gedämpften Schritte hallte durch die langen, engen Korridore."
  },
  AvgDialog_149753_Content_47 = {
    Text = "Also… was genau suchst du? Ist es wichtig für dich? Beschreib mir, wie es aussieht — ich kann dir helfen, es zu finden."
  },
  AvgDialog_149753_Content_48 = {
    Text = "Ein goldener Kelch."
  },
  AvgDialog_149753_Content_49 = {
    Text = "Ein goldener Kelch? Du meinst aus echtem Gold? Wow, wie groß ist er, wie hoch? Was füllst du hinein? Wie sieht Gold aus — leuchtet es wie der Mond in der Nacht?"
  },
  AvgDialog_149753_Content_5 = {
    Text = "Der Körper sackte schlaff zu Boden, ein kalter Metallglanz blitzte auf und verschwand, als der Mörder seinen Umhang enger zog und schnellen Schrittes davoneilte, seine Schritte im Regen verhallend."
  },
  AvgDialog_149753_Content_50 = {
    Text = "...Ich weiß nicht."
  },
  AvgDialog_149753_Content_51 = {
    Text = "Hä? Gehört er nicht dir?"
  },
  AvgDialog_149753_Content_52 = {
    Text = "Nein, aber er ist mir sehr wichtig."
  },
  AvgDialog_149753_Content_53 = {
    Text = "Oh! Ich weiß — es ist der Heilige Gral, nicht wahr? Ich habe davon in Geschichten gehört. Ein magischer Schatz, den nur ein Ritter erlangen kann, der die Prüfungen besteht. Kein Wunder, dass du schon so lange suchst."
  },
  AvgDialog_149753_Content_54 = {
    Text = "Ähem, als deine Prinzessin würde es auch mir zugutekommen, wenn du den Heiligen Gral erlangst, also…"
  },
  AvgDialog_149753_Content_55 = {
    Text = "Er hielt plötzlich inne, hob seinen Zeigefinger und machte dir gegenüber eine Geste des Schweigens."
  },
  AvgDialog_149753_Content_56 = {
    Text = "Du erstarrtest sofort und hieltest instinktiv den Atem an. Die Laterne erlosch, und Dunkelheit strömte herein, hüllte dich lückenlos ein."
  },
  AvgDialog_149753_Content_57 = {
    Text = "Du zähltest vierzehn Herzschläge. Dann kam ein dumpfer Aufprall vom Ende des Korridors, gefolgt vom Zersplittern von etwas, das auf den Boden fiel, und mehrere unkontrollierte Schreie zerrissen die Stille."
  },
  AvgDialog_149753_Content_58 = {
    Text = "Licht flackerte auf — unruhig und unstabil, wie die Silhouetten vieler Menschen in heftigem Kampf. Du ranntest darauf zu, wurdest jedoch von einer Hitzewelle zurückgetrieben. Es war Feuer. Blaues Feuer."
  },
  AvgDialog_149753_Content_59 = {
    Text = "Lass — hust, hust — lass mich los! Ich war so nah dran! Nur noch ein bisschen — nur noch ein bisschen!"
  },
  AvgDialog_149753_Content_6 = {
    Text = "Du zogst hastig deine Kapuze hoch und joggte durch den Regen, kaum in der Lage, mit ihm Schritt zu halten."
  },
  AvgDialog_149753_Content_60 = {
    Text = "Ein beißender Geruch erfüllte die Geheimkammer. Eine verdächtige dunkelrote Flüssigkeit rann langsam durch Glasröhren. Eine Kerze hatte eine klare Flüssigkeit entzündet, die über den Boden verschüttet worden war, und blassblue Flammen brannten in der Stille. Tief im Inneren des Herrenhauses war die ganze Zeit ein verborgenes alchemistisches Zimmer versteckt gewesen."
  },
  AvgDialog_149753_Content_61 = {
    Text = "Im Zentrum der vielen Glasgefäße erstrahlte ein Kelch aus reinem Gold — heller als der Wick. Das musste der Heilige Gral sein."
  },
  AvgDialog_149753_Content_62 = {
    Text = "Was hast du hineingefüllt?"
  },
  AvgDialog_149753_Content_63 = {
    Text = "Lass mich los! Du verstehst das nicht! Es ist fast da — es ist fast da… breitet sich durch verrottende Vorhänge aus, schleicht sich entlang des Dochts des Vergessens. Die Lebenden, die Toten — niemand kann entkommen… niemand kann entkommen…"
  },
  AvgDialog_149753_Content_64 = {Text = "Es?"},
  AvgDialog_149753_Content_65 = {
    Text = "Es… die endlose ewige Nacht, die ultimative Vernichtung… es ist ein Fluch… <Shake:Der Fluch ist fast da! Ein Fluch, der alles verschlingt — der Fluch der <Red:Hexenprinzessin>!!>"
  },
  AvgDialog_149753_Content_66 = {
    Text = "Was hast du gesagt?!"
  },
  AvgDialog_149753_Content_67 = {
    Text = "Der Schatten hinter ihm zuckte heftig zusammen. Die Flammen fielen in Augen, die vor Schrecken weit aufgerissen waren — und entzündeten etwas. Angst oder Hoffnung?"
  },
  AvgDialog_149753_Content_68 = {
    Text = "In diesen Worten musste ein mächtiger Zauber verborgen gewesen sein, denn dein Ritter erstarrte plötzlich zur Steinsäule, schien jedoch zum allerersten Mal lebendig zu werden. Sein Schatten zitterte ohne Unterlass."
  },
  AvgDialog_149753_Content_69 = {
    Text = "Du, du… du erinnerst dich an sie? Was erinnerst du dich noch?"
  },
  AvgDialog_149753_Content_7 = {
    Text = "Was suchst du?"
  },
  AvgDialog_149753_Content_70 = {
    Text = "<Shake:Eitelkeit, Eitelkeit der Eitelkeiten, alles ist Eitelkeit… die Menschheit schuftet wie Staub auf Stein, ohne Vergangenheit, ohne Zukunft…>"
  },
  AvgDialog_149753_Content_71 = {
    Text = "Nein — der goldene Kelch! Der goldene Kelch ist die einzige Erlösung! Lass mich die Wahrheit trinken, lass mich — ich muss weitermachen!"
  },
  AvgDialog_149753_Content_72 = {
    Text = "<Big:Beantworte meine Frage!@1@2Die Prinzessin — wie viel erinnerst du dich noch an sie?!>"
  },
  AvgDialog_149753_Content_73 = {
    Text = "Der Schatten wand sich, der Schatten wogte, der Schatten tanzte wild und schlang sich immer enger um die Kehle des Monsters, dessen zwei Lippen sich in vergeblichen Atemzügen öffneten und schlossen."
  },
  AvgDialog_149753_Content_74 = {
    Text = "<Shake:Ich erinnere mich… Seuche… Trank… Fluch… kh, kh… ich erinnere mich, ich erinnere mich an dich…>"
  },
  AvgDialog_149753_Content_75 = {
    Text = "<Shake:<Red:Au… gur>… mein Ritter… du… lauf…>"
  },
  AvgDialog_149753_Content_76 = {Text = "„Kh.“"},
  AvgDialog_149753_Content_77 = {
    Text = "Die Worte blieben unvollendet, denn es konnte nicht mehr sprechen — der Schatten brach ihm das Genick. Der aufgedunsene Kopf sank leblos zur Seite wie ein fest gebundener Sack aus Rupfen, und durch die hohlen Lücken starrten zwei rostgefressene Augäpfel noch immer starr ins Leere."
  },
  AvgDialog_149753_Content_78 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_149753_Content_79 = {
    Text = "Au… gur? Könnte das… dein Name sein?"
  },
  AvgDialog_149753_Content_8 = {
    Text = "Ich habe nie zugestimmt, dass du mir folgst."
  },
  AvgDialog_149753_Content_80 = {
    Text = "Er wandte sein Gesicht abrupt ab, wie ein Gespenst, dessen wahre Gestalt enthüllt worden war, sein Ausdruck irgendwo zwischen Verwirrung und Hass gefangen. Der Schatten an der Wand schwankte und taumelte, tanzte mit fröhlichen Schritten und umschloss euch beide in der Mitte."
  },
  AvgDialog_149753_Content_81 = {
    Text = "Nein, das stimmt nicht? Nun… wie auch immer dein Name ist, du bist noch immer mein Ritter."
  },
  AvgDialog_149753_Content_82 = {
    Text = "Der Heilige Gral wurde gefunden. Wohin gehen wir jetzt?"
  },
  AvgDialog_149753_Content_83 = {
    Text = "Durch deine Worte erinnert, wandte er langsam den Kopf zum goldenen Kelch auf dem Tisch, riss sich dann mit großer Mühe aus den Schatten los und hob die verbliebene halbe Tasse Gegengift — oder Gift, das wusstest du nicht."
  },
  AvgDialog_149753_Content_84 = {
    Text = "Du sahst nur zu, wie er den Kopf zurückwarf und es hinuntertrank."
  },
  AvgDialog_149753_Content_85 = {
    Text = "<Big:Hey!!>"
  },
  AvgDialog_149753_Content_9 = {
    Text = "Wenn ich nicht folge, was ist, wenn du deine Prinzessin verrätst? Du wolltest nicht einmal einen Eid schwören."
  },
  AvgDialog_149754_Content_1 = {
    Text = "Das donnernde Getöse war ohrenbetäubend, als würde der gesamte Hauptturm erzittern. Zerbrochene Ziegel und Steine knackten und fielen herab, während die verbliebenen Monster sich eng um den Herrn in der Mitte scharten und ihn beim Rückzug in den Geheimgang eskortierten."
  },
  AvgDialog_149754_Content_10 = {
    Text = "Wer weiß, wie weit ihr gegangen wart, bevor euch eine Brise entgegenwehte. Salzig. Das Meer."
  },
  AvgDialog_149754_Content_11 = {
    Text = "Wir sind — wir sind draußen! Wir haben es geschafft! Ogier, hörst du mich? Wir sind gerettet!!"
  },
  AvgDialog_149754_Content_12 = {Text = "…Ogier?"},
  AvgDialog_149754_Content_13 = {
    Text = "Er gab keinen Laut von sich — du konntest nicht einmal spüren, ob er atmete. Die Wellen schlugen gegen die Felsen, und eiskaltes Meerwasser vermischt mit Regen spritzte dir ins Gesicht. Es war, als würdest du zum allerersten Mal Kälte empfinden, und du konntest nicht umhin zu zittern."
  },
  AvgDialog_149754_Content_14 = {
    Text = "<SmallShake:…hust… hust, hust…>"
  },
  AvgDialog_149754_Content_15 = {
    Text = "Ogier! Gott sei Dank — ich wusste, dass du nicht sterben würdest!"
  },
  AvgDialog_149754_Content_16 = {
    Text = "<Shake:Ich… habe dir nie… versprochen… mitzukommen.>"
  },
  AvgDialog_149754_Content_17 = {
    Text = "Ja, ja, wie oft willst du das noch sagen. Braucht eine Prinzessin die Erlaubnis ihres Ritters, um zu gehen, wohin es ihr beliebt?"
  },
  AvgDialog_149754_Content_18 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_149754_Content_19 = {
    Text = "<Shake:Ich… hatte einst… eine… Prinzessin.>"
  },
  AvgDialog_149754_Content_2 = {
    Text = "Dein Ritter kämpfte verzweifelt darum, standzuhalten, ein heiseres Brüllen brach aus seiner zerschundenen Brust, doch die Schatten brandeten wie eine Flut heran. Mehr noch als die Feinde schienen sie ihn lebendig verschlingen zu wollen."
  },
  AvgDialog_149754_Content_20 = {
    Text = "<Shake:Ich habe… versagt, sie zu… beschützen.>"
  },
  AvgDialog_149754_Content_21 = {
    Text = "Sein schwaches Murmeln klang wie Schlafgerede und wurde leicht vom Meereswind verweht. Du musstest den Atem anhalten."
  },
  AvgDialog_149754_Content_22 = {
    Text = "Bevor der Krieg… ausbrach… befahl sie mir… zu gehen…"
  },
  AvgDialog_149754_Content_23 = {
    Text = "Ich… gehorchte."
  },
  AvgDialog_149754_Content_24 = {
    Text = "Ich dachte nie… der Feind… so schnell… ich schaffte es nicht, hust hust, schaffte es nicht…"
  },
  AvgDialog_149754_Content_25 = {
    Text = "Das Gemetzel… die Leichen… die schwarze Pest… <Shake:Die Prinzessin… sie… sie nahm sich selbst, hust hust hust hust!>"
  },
  AvgDialog_149754_Content_26 = {
    Text = "Welche schmerzhafte Erinnerung er auch immer heraufbeschworen hatte, man konnte spüren, wie er sich in sich selbst zusammenkrümmte, wie eine Schnecke, die mit Salz übergossen wurde."
  },
  AvgDialog_149754_Content_27 = {
    Text = "<Shake:Ich war es… ich habe versagt, sie zu schützen… alle fort… alle werden fort sein…>"
  },
  AvgDialog_149754_Content_28 = {
    Text = "<Shake:Ich wollte einst… ein Ritter werden…>"
  },
  AvgDialog_149754_Content_29 = {
    Text = "<Shake:Aber… jetzt… wer… bin ich…>"
  },
  AvgDialog_149754_Content_3 = {
    Text = "Halt! Ihr seid die wahren Monster! Lauft nicht weg!!"
  },
  AvgDialog_149754_Content_30 = {
    Text = "Die Vergangenheit ist die Vergangenheit, und die Gegenwart ist die Gegenwart. Im Moment hast du auch eine Prinzessin, und du musst mich noch immer beschützen."
  },
  AvgDialog_149754_Content_31 = {
    Text = "Er schwieg eine lange Weile, doch dann regte er sich."
  },
  AvgDialog_149754_Content_32 = {
    Text = "<Shake:Setz mich, hust hust hust, ab.>"
  },
  AvgDialog_149754_Content_33 = {
    Text = "Ich bin der Schwächste… der Nutzloseste…"
  },
  AvgDialog_149754_Content_34 = {
    Text = "Derjenige, der… zurückbleiben sollte… verweilen in… der vergessenen… Vergangenheit…"
  },
  AvgDialog_149754_Content_35 = {
    Text = "Unmöglich! Du hast dein Versprechen noch nicht erfüllt — willst du etwa dein Wort brechen?"
  },
  AvgDialog_149754_Content_36 = {
    Text = "Die steigende Flut schwappte an deinen Knien vorbei, während du dich durch die Dunkelheit kämpftest. Scharfe Felsen schnitten in deine Waden, die Wunden wurden vom Salzwasser taub. Du bissest die Zähne zusammen und ließest keinen Laut des Schmerzes verlauten."
  },
  AvgDialog_149754_Content_37 = {
    Text = "Deine Worte wurden von keuchenden Atemzügen zerrissen. Du presste jede Silbe mit Mühe aus deiner Kehle — einen Satz beendend, einen Schritt machend, als würdest du dich damit vorwärtstragenд."
  },
  AvgDialog_149754_Content_38 = {
    Text = "Du bist der Ritter, den ich gewählt habe. Wenn ich dich zurücklasse, wie soll die Prinzessin allein das Monster besiegen und das Abenteuer vollenden?"
  },
  AvgDialog_149754_Content_39 = {
    Text = "… Das ist doch nur eine Geschichte."
  },
  AvgDialog_149754_Content_4 = {
    Text = "Ängstlich und wütend schleuderte du das Bündel, das du die ganze Zeit festgehalten hattest, mit aller Kraft fort. Es war prall gefüllt, und der lose Knoten löste sich in der Luft — jemandes Habseligkeiten verstreuten sich überall: eine Kerze, ein Kamm, eine kleine Steinfigur… und der Kelch."
  },
  AvgDialog_149754_Content_40 = {
    Text = "Alles ist eine Geschichte."
  },
  AvgDialog_149754_Content_41 = {
    Text = "Gestern ist die Geschichte von heute, heute ist die Geschichte von morgen. Manche sind verblasst, manche werden weitergehen. Aber es kann keine Geschichte geben, die keine ist."
  },
  AvgDialog_149754_Content_42 = {
    Text = "Also geh und finde Apfelinsel. Geh, hoo, hoo… geh und vollende unsere Geschichte."
  },
  AvgDialog_149754_Content_5 = {
    Text = "Das goldene Licht taumelte und schoss hoch über den Schattensumpf hinweg, traf die Steinmauer, prallte zweimal auf dem Boden auf und rollte schließlich — wie von Geisterhand — genau vor die Füße des Herrn."
  },
  AvgDialog_149754_Content_6 = {
    Text = "Du sahst, wie er eine Hand hob, um die Wachen aufzuhalten, sich dann selbst herabbeugte und den kleinen goldenen Kelch aufhob. Er fuhr mit dem Daumen über die Muster auf seiner Oberfläche, als erinnere er sich an etwas, und wandte sich mit einem spöttischen Blick um."
  },
  AvgDialog_149754_Content_7 = {
    Text = "Dann verwandelte er sich rasch in Entsetzen."
  },
  AvgDialog_149754_Content_8 = {
    Text = "…Bevor die Burg vollständig zu Schutt und Asche zerfiel und die Schatten, den Drachen und die Reliquien gleichermaßen begrub, zog dein Ritter dich in den Geheimgang."
  },
  AvgDialog_149754_Content_9 = {
    Text = "Er war völlig erschöpft und konnte nicht einmal mehr stehen. Du hieltest seinen Arm fest umklammert und kämpftest darum, deine Füße zu bewegen, als würdest du einen schweren Sack Weizen tragen."
  },
  AvgDialog_149755_Content_1 = {Text = "Apfelinsel"},
  AvgDialog_149755_Content_10 = {
    Text = "Die Wunde an deinem Bein war nie verheilt. Wenn überhaupt, war sie durch die unaufhörlichen Regentage noch schmerzhafter geworden, dein Bein unterhalb des Knies geschwollen wie eine Karotte — du konntest keinen einzigen Schritt mehr tun. In den vergangenen Tagen hatte Ogier dich über Berge und durch Täler getragen."
  },
  AvgDialog_149755_Content_100 = {
    Text = "Eure Hoheit, bitte weint nicht um mich. Es gibt bereits viel zu viele Monster. Das Einzige, was ich für Euch tun kann, ist das Paradies zu schützen, das der Menschheit gehört, das Euch gehört. Dies ist meine Pflicht und meine Buße."
  },
  AvgDialog_149755_Content_101 = {
    Text = "Ich gehe nicht auf ein Ende zu. Ich werde darüber hinausgehen, denn ich habe die Morgendämmerung bereits empfangen."
  },
  AvgDialog_149755_Content_102 = {
    Text = "Ich werde weiter über Euch wachen, von dort, wo die Sonne aufgeht."
  },
  AvgDialog_149755_Content_103 = {
    Text = "Schatten strömten anstelle von Blut hervor. Jeder, der in diesen tosenden Strudel trat, verschwand im Handumdrehen, doch der Schatten verschwand nicht."
  },
  AvgDialog_149755_Content_104 = {
    Text = "Der Schatten wand sich, der Schatten wogte, der Schatten verdichtete sich zu einem Schild, zu einer Mauer und schließlich zu einem gewaltigen Damm. Du starrtest unverwandt in die tiefste Dunkelheit, bis der Ochsenkarren um eine Biegung fuhr und du die Oberfläche des Flusses nicht mehr sehen konntest."
  },
  AvgDialog_149755_Content_105 = {
    Text = "Dein Ritter verschwand von jenem Tag an spurlos. Er hatte nur die Hälfte seines Versprechens erfüllt, doch hinterließ er ein durch und durch listiges letztes Wort — eines, das dich auf den nächsten Tag hoffen ließ, selbst als du unter Tränen einschliefst."
  },
  AvgDialog_149755_Content_106 = {
    Text = "Denn dann würde eine neue Sonne aufgehen, Tag für Tag, unveränderlich."
  },
  AvgDialog_149755_Content_11 = {
    Text = "Hier, gerade gepflückt."
  },
  AvgDialog_149755_Content_12 = {
    Text = "Als wolle er etwas Trost spenden, drückte er dir eine Frucht in die Hand. Du nahmst schläfrig einen Bissen, und erst als sich eine scharfe Säure von den Zahnwurzeln ausbreitete, wurde dir klar, was es war."
  },
  AvgDialog_149755_Content_13 = {
    Text = "…Ein Apfel?"
  },
  AvgDialog_149755_Content_14 = {
    Text = "Mm, wir sind vor einer Weile durch einen Apfelhain gekommen."
  },
  AvgDialog_149755_Content_15 = {
    Text = "Ein Apfel… Apfelinsel, sind wir angekommen?"
  },
  AvgDialog_149755_Content_16 = {Text = "Fast."},
  AvgDialog_149755_Content_17 = {
    Text = "Er wickelte die Verbandstreifen ab, trug das Kräutermittel auf die Wunde auf und wickelte sie dann wieder ein, Schicht für Schicht. Du beobachtetest seinen Gesichtsausdruck und hattest das Gefühl, dass er nicht von Vorfreude geprägt war."
  },
  AvgDialog_149755_Content_18 = {
    Text = "Du willst nachhaken, doch ein Chor aus Bellen unterbricht dich — zunächst aus der Ferne, dann rasch näher kommend."
  },
  AvgDialog_149755_Content_19 = {
    Text = "Warte, lauf nicht so schnell! Wohin gehst du? Das ist nicht der Weg zurück ins Dorf — ah!"
  },
  AvgDialog_149755_Content_2 = {
    Text = "……aufwachen……"
  },
  AvgDialog_149755_Content_20 = {
    Text = "Ein wilder Schäferhund bricht aus dem Unterholz hervor und bellt laut, um die Eindringlinge zu vertreiben. Das Mädchen, das dicht hinter ihm herläuft, erblickt euch und stößt unwillkürlich einen Schrei aus, der Weidenkorb in ihren Händen fällt zu Boden."
  },
  AvgDialog_149755_Content_21 = {
    Text = "Es ist Ogier. Dunkle, schmutzige Narben ziehen sich über sein Gesicht, wie eine Stoffpuppe, die auseinandergerissen und hastig wieder zusammengeflickt wurde, und rufen allerlei erschreckende Legenden in Erinnerung."
  },
  AvgDialog_149755_Content_22 = {
    Text = "Er und das Mädchen starren sich schweigend an, dann steht er auf und zieht seine Kapuze hoch."
  },
  AvgDialog_149755_Content_23 = {
    Text = "Wir gehen jetzt."
  },
  AvgDialog_149755_Content_24 = {
    Text = "Nein… nein, ich wollte nicht — bitte wartet!"
  },
  AvgDialog_149755_Content_25 = {
    Text = "Ogier hat kaum ein paar Schritte mit dir auf dem Rücken gemacht, als das Mädchen ihnen ängstlich nachläuft."
  },
  AvgDialog_149755_Content_26 = {
    Text = "Geht nicht! Das meinte ich nicht so. Im Dorf gibt es viele Kranke — lasst mich euch zu ihnen bringen!"
  },
  AvgDialog_149755_Content_27 = {Text = "Krank?"},
  AvgDialog_149755_Content_28 = {
    Text = "Ja, alles Leprakranke. Anfangs waren es nur Leprakranke. Dann kam die Armee — sie zerstörte unzählige Dörfer, mied aber stets die Leprakolonie — also kamen Menschen, die nirgendwo mehr hingehen konnten, hierher. Ich war eine von ihnen."
  },
  AvgDialog_149755_Content_29 = {
    Text = "Keine Sorge, alle haben sich daran gewöhnt. Abgesehen davon, dass wir anders aussehen, sind wir wirklich nicht anders als alle anderen — wir essen gleich, schlafen gleich, arbeiten gleich… Lepra ist bei Weitem nicht so erschreckend wie die Armee. Man gewöhnt sich daran."
  },
  AvgDialog_149755_Content_3 = {
    Text = "……Regen……ausruhen……aufwachen……"
  },
  AvgDialog_149755_Content_30 = {
    Text = "Es tut mir leid, ich hatte keine Angst vor euch — ich habe nur noch nie… Es tut mir leid! Hier, nehmt diesen Korb Äpfel. Ich habe sie selbst gepflückt, ich verspreche, es sind die größten und süßesten!"
  },
  AvgDialog_149755_Content_31 = {
    Text = "Wie sollte das Paradies aussehen?"
  },
  AvgDialog_149755_Content_32 = {
    Text = "Keine Monster, keine Verzweiflung, kein unsägliches Grauen, keine Augen, die in der Dunkelheit lauern. Keine Angst, nicht mehr aufzuwachen, bevor man einschläft. Jeden einzelnen Tag heiße Suppe zu trinken."
  },
  AvgDialog_149755_Content_33 = {
    Text = "Du kennst keinen anderen Ort, der dem Paradies näher käme als dieser."
  },
  AvgDialog_149755_Content_34 = {
    Text = "…Das reicht."
  },
  AvgDialog_149755_Content_35 = {
    Text = "Ein scharfes Messer öffnet den Abszess und schabt das faulende Fleisch Stück für Stück heraus. Ein rotglühendes Eisen wird auf die Wunde gedrückt, die nicht aufhört zu bluten. Der brennende Schmerz entreißt deiner Kehle einen gedämpften Schrei, und du brichst in einen durchdringenden Schweiß aus."
  },
  AvgDialog_149755_Content_36 = {
    Text = "Es ist vorbei. Der in deinen Mund gestopfte Lappen wird entfernt. Du atmest mit jeder Kraft, die du hast, keuchend ein, als würdest du die Luft fast in einem Zug verschlucken."
  },
  AvgDialog_149755_Content_37 = {
    Text = "Dieses Mal ist es anders — du weißt es. Sie tun dies, um dich zu retten, und dein Ritter ist direkt hier neben dir."
  },
  AvgDialog_149755_Content_38 = {
    Text = "Medizin. Nimm sie mit und koche sie in Wasser. Einmal bei Morgengrauen, einmal bei Abenddämmerung."
  },
  AvgDialog_149755_Content_39 = {
    Text = "Gut, danke."
  },
  AvgDialog_149755_Content_4 = {
    Text = "Du wirst sanft geweckt, dein Geist noch benebelt, und du hörst das leise Prasseln des Regens."
  },
  AvgDialog_149755_Content_40 = {
    Text = "Er holte ein paar Münzen als Bezahlung heraus, doch der Barbier winkte ab. An einem Ort, der von der Welt abgeschnitten war, hatten die Preise der Außenwelt keinen Wert — die Menschen hier lebten nicht für solche Dinge."
  },
  AvgDialog_149755_Content_41 = {
    Text = "<Small:Der Himmel hat sich aufgeklärt…>"
  },
  AvgDialog_149755_Content_42 = {
    Text = "<Small:Ogier, ich möchte in den Apfelhain gehen.>"
  },
  AvgDialog_149755_Content_43 = {
    Text = "Du musst dich ausruhen."
  },
  AvgDialog_149755_Content_44 = {
    Text = "Bring mich dorthin. Ich habe eine große Entdeckung gemacht… Ich muss es dir erzählen."
  },
  AvgDialog_149755_Content_45 = {
    Text = "Wir sind da. Was für eine große Entdeckung?"
  },
  AvgDialog_149755_Content_46 = {
    Text = "Hah… Mir ist aufgegangen — das ist die Apfelinsel. Wir haben sie bereits gefunden."
  },
  AvgDialog_149755_Content_47 = {
    Text = "Dein Ritter setzt dich auf einen umgefallenen Baumstamm, der auf der Seite liegt, und kniet dann nieder, um dein verletztes Bein behutsam zu stützen. Sein Blick ist konzentriert und besorgt — offensichtlich hat die Wahrheit, die du gerade erkannt hast, ihn nicht zu verblüffen vermocht."
  },
  AvgDialog_149755_Content_48 = {
    Text = "Aber das hier ist keine Insel."
  },
  AvgDialog_149755_Content_49 = {
    Text = "Niemand hat je gesagt, dass eine Insel im Meer liegen muss, oder? Solange sie nicht mit der Außenwelt verbunden ist, ist es eine Insel."
  },
  AvgDialog_149755_Content_5 = {
    Text = "Der Regen hat wieder eingesetzt. Er hat nie wirklich aufgehört."
  },
  AvgDialog_149755_Content_50 = {
    Text = "Und außerdem gibt es hier Feen."
  },
  AvgDialog_149755_Content_51 = {Text = "Feen?"},
  AvgDialog_149755_Content_52 = {
    Text = "Ja, im Dorf gibt es viele Feen. Manche haben die Gesichter von Löwen, manche die Schuppen von Fischen, und andere häuten sich wie Schlangen. Sie sind Feen, die in einem verzauberten Land leben."
  },
  AvgDialog_149755_Content_53 = {
    Text = "Feen… keine Monster?"
  },
  AvgDialog_149755_Content_54 = {
    Text = "Natürlich nicht! Wie könnten Feen und Monster jemals dasselbe sein?"
  },
  AvgDialog_149755_Content_55 = {
    Text = "Monster fressen Menschen. Sie scheuen keine Mittel, um Menschen zu fressen — manchmal töten sie sie direkt mit einer Klinge, manchmal weben sie Lügen, um Menschen einzusperren und das Fleisch Stück für Stück von ihnen zu schneiden."
  },
  AvgDialog_149755_Content_56 = {
    Text = "Und sie fressen es nicht nur selbst — sie machen daraus Suppe, gepökeltes Fleisch, Brei und verfüttern es an andere. Menschenfleisch ist überall. Man verhungert, wenn man es nicht isst, aber in dem Moment, in dem man es tut, wird man selbst zum Monster. Und so werden die Monster immer zahlreicher."
  },
  AvgDialog_149755_Content_57 = {
    Text = "Menschen fressen keine Menschen, und Feen fressen auch keine Menschen. Auf der Apfelinsel sind sie rein."
  },
  AvgDialog_149755_Content_58 = {
    Text = "Was ist mit mir? Ich bin weder Mensch noch Elf. Meine Hände sind mit Blut befleckt, und ein Dämon wohnt in meinem Körper — du hast es mit eigenen Augen gesehen."
  },
  AvgDialog_149755_Content_59 = {
    Text = "Warum hast du keine Angst?"
  },
  AvgDialog_149755_Content_6 = {
    Text = "Der Wald bot den fliehenden Verbannten Schutz. Die Nachricht vom Massaker der Monster auf der Burg erreichte die Ohren der Herrscher, Steckbriefe wurden in jeder Stadt angeschlagen, und sowohl der Ritterorden der Kirche als auch Söldner wurden mobilisiert — ihr hattet keine andere Wahl, als Tag und Nacht voranzuziehen."
  },
  AvgDialog_149755_Content_60 = {
    Text = "Warum sollte ich Angst haben? Vom allerersten Moment an, als du ihn sahst, wusstest du, dass er ein Ritter sein musste. Durch die Schatten, die hafteten und nicht verblassen wollten, konntest du den Ritter in ihm noch immer sehen — so klar, so unverkennbar, als hättest du ihn irgendwo schon einmal gesehen."
  },
  AvgDialog_149755_Content_61 = {
    Text = "Was braucht es, um ein wahrer Ritter zu werden? Treue, Mut, Mitgefühl, Opferbereitschaft und…"
  },
  AvgDialog_149755_Content_62 = {
    Text = "Die Investitur eines Ritters."
  },
  AvgDialog_149755_Content_63 = {
    Text = "Ähem… Dann erkläre ich hiermit, im Namen einer Prinzessin — ich schlage dich zum Ritter."
  },
  AvgDialog_149755_Content_64 = {
    Text = "Du hast das Monster erschlagen, den Heiligen Gral erlangt, dem Dämon standgehalten und mich beschützt. Du hast dein Versprechen gehalten und deine Prinzessin zur Insel der Äpfel gebracht."
  },
  AvgDialog_149755_Content_65 = {
    Text = "Ganz gleich, wer du einst warst — in unserer Geschichte bist du ein Ritter, und keine Prinzessin würde je ihren eigenen Ritter fürchten."
  },
  AvgDialog_149755_Content_66 = {
    Text = "Du wirst immer mein Ritter sein."
  },
  AvgDialog_149755_Content_67 = {
    Text = "Dein Ritter stand wie erstarrt, eine Hand den Umhang fest umklammernd, als wollte er sich in dessen weitem Schatten verbergen. Der Umhang verbarg die Spuren des Schattens, und nur er wusste, wie erbärmlich die Wahrheit unter dieser Verkleidung war."
  },
  AvgDialog_149755_Content_68 = {
    Text = "Ein schlanker Ast, noch mit Regentropfen besetzt, legte sich sanft auf seine Schulter. Eine Sehnsucht, so weit entfernt, dass sie fast vergessen war, wurde plötzlich wahr — doch was seine Seele erzittern ließ, war keine Freude."
  },
  AvgDialog_149755_Content_69 = {
    Text = "Sondern Angst."
  },
  AvgDialog_149755_Content_7 = {
    Text = "Dort vorne liegt ein Dorf. Ich gehe Essen und Medizin eintauschen. Ruh dich hier aus, und wir brechen auf, sobald der Regen aufhört."
  },
  AvgDialog_149755_Content_70 = {
    Text = "Flammen des Entsetzens stiegen aus dem bodenlosen Abgrund — unter seinen Füßen, über seinem Kopf, in den verängstigten Augen hinter den Rissen. Sengend, brennend, spritzend aus abgetrennten Hälsen, strömend aus Brustkörben. Die Flammen zuckten so wild, dass die Schatten mit ihnen wahnsinnig wurden. Feuer und Schatten waren ein und dasselbe."
  },
  AvgDialog_149755_Content_71 = {
    Text = "Es war ein Massaker — ohne Ehre, ohne Gerechtigkeit, gleich für alle. Das blutgetränkte Ende zerriss die hübschen Lügen, die es verkleidet hatten; der Tod war nichts als der Tod. Er konnte sich nicht erinnern, wie er überlebt hatte. Vielleicht hatte er gar nicht überlebt."
  },
  AvgDialog_149755_Content_72 = {
    Text = "Ein gefallenes Monster, ein rachsüchtiger Geist — seine Jagd glich dem Tragen von Zunder gegen ein Feuer. Die Verlorene Seele glitt unweigerlich dem Verderben entgegen und glaubte nie, dass Erlösung für ihn möglich sein könnte."
  },
  AvgDialog_149755_Content_73 = {
    Text = "<Shake:Aber… aber…>"
  },
  AvgDialog_149755_Content_74 = {
    Text = "Ogier, Ogier? Hey, hörst du überhaupt zu? Ich bin fertig — du bist dran."
  },
  AvgDialog_149755_Content_75 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_149755_Content_76 = {
    Text = "Ja. Ich bin bereit."
  },
  AvgDialog_149755_Content_77 = {
    Text = "Im Namen meiner verlorenen Heimat schwöre ich dir, Ogier, Sohn der Familie Dansk, meine Treue und Ehrerbietung."
  },
  AvgDialog_149755_Content_78 = {
    Text = "Ich biete dir meinen Schild und meine Lanze, zusammen mit dem Glauben, den ich befleckt habe, meiner beständigen Furcht und meinem gebrochenen Herzen. Ich hatte meinen Namen in der langen Nacht verloren — es war dein Ruf, der die Morgendämmerung entzündete."
  },
  AvgDialog_149755_Content_79 = {
    Text = "Ein Eidbrecher ist nicht länger würdig, von Treue zu sprechen — doch wenn dein Blick noch bereit ist zu verweilen, dann gehöre ich dir, bis zum letzten Atemzug meines Lebens."
  },
  AvgDialog_149755_Content_8 = {
    Text = "<Small:Verstanden… komm schnell zurück.>"
  },
  AvgDialog_149755_Content_80 = {
    Text = "Geschichten beginnen nicht immer in leuchtenden Farben — sie können auch an den Ufern der Verzweiflung ihren Anfang nehmen."
  },
  AvgDialog_149755_Content_81 = {
    Text = "Selbst wenn das Ende unveränderlich feststeht und seinen schweren Schatten über alle Dinge wirft — bevor du es erreichst, hast du noch die Freiheit zu wählen, was dein Schicksal wird."
  },
  AvgDialog_149755_Content_82 = {
    Text = "Eine sanfte Brise, warmes Sonnenlicht, der Duft reifer Äpfel, Nebel, der wie Wolken aus dem Wald aufsteigt — die Welt ist so schön wie ein Gemälde, und du lächelst vor Freude, als wäre endlich ein vollkommenes Ende gekommen."
  },
  AvgDialog_149755_Content_83 = {
    Text = "Aber du weißt, dass die Geschichte weitergehen wird. Sie geht immer weiter."
  },
  AvgDialog_149755_Content_84 = {
    Text = "<Big:Wie viele Menschen sind noch nicht aufgewacht? Geht und weckt sie schnell — die Flut kommt!>"
  },
  AvgDialog_149755_Content_85 = {
    Text = "Die Dunkelheit der Nacht nährte die Wut des Sturms. Regentropfen prasselten wie Steine herab, der trübe Fluss donnerte über beide Ufer, und das Hochwasser hatte bereits die Knie überstiegen."
  },
  AvgDialog_149755_Content_86 = {
    Text = "Gestalten eilten hin und her, riefen laut, hämmerten mit aller Kraft gegen jede Tür und jedes Fenster — doch die Geister bewegten sich träge, und wenn sie einmal fielen, konnten sie nicht mehr aufstehen, unfähig, sich allein durch das unebene, überflutete Gelände zu kämpfen."
  },
  AvgDialog_149755_Content_87 = {
    Text = "„BOOM!!“ Ein donnernder Knall ließ dein Herz erschaudern, doch in der drückenden Nacht blickten die Menschen verwirrt umher, ohne zu wissen, was gleich einstürzen würde."
  },
  AvgDialog_149755_Content_88 = {
    Text = "<Big:Nein — es ist der Damm!!>"
  },
  AvgDialog_149755_Content_89 = {
    Text = "<Big:Lauft! Alle, die sich bewegen können, lauft — es bleibt keine Zeit!>"
  },
  AvgDialog_149755_Content_9 = {
    Text = "So sehr du es auch hasste, zurückgelassen zu werden — dein ganzer Körper brannte mit einem erschreckenden Fieber, und du hattest nicht mehr die Kraft, mit ihm Schritt zu halten."
  },
  AvgDialog_149755_Content_90 = {
    Text = "Flehen, Stöhnen, Weinen — das Paradies deiner Träume schwankte am Rand des Untergangs, kurz davor, vom endlosen Regen verschluckt zu werden und nichts als zerbrochene Trümmer zu hinterlassen. Und du konntest nicht einmal alleine gehen, machtlos, nichts tun als zuzusehen."
  },
  AvgDialog_149755_Content_91 = {
    Text = "Dein Ritter hob dich auf die Kutschenstufe, löste seinen Umhang und wickelte ihn fest um dich."
  },
  AvgDialog_149755_Content_92 = {
    Text = "Eure Hoheit, ich bitte demütig um Erlaubnis, aufzubrechen und die tobende Flut aufzuhalten."
  },
  AvgDialog_149755_Content_93 = {
    Text = "Kannst du die Flut aufhalten?"
  },
  AvgDialog_149755_Content_94 = {
    Text = "Ich werde alles in meiner Macht Stehende tun."
  },
  AvgDialog_149755_Content_95 = {
    Text = "Kannst du zurückkehren?"
  },
  AvgDialog_149755_Content_96 = {
    Text = "…Ich werde alles in meiner Macht Stehende tun."
  },
  AvgDialog_149755_Content_97 = {
    Text = "<Big:Nein — nein, ich weigere mich! Ich erlaube es nicht!>"
  },
  AvgDialog_149755_Content_98 = {
    Text = "Lass uns gehen — jetzt sofort… Es wird eine andere geben. Apfelinsel, Kürbisinsel, irgendetwas — es wird immer eine andere geben!"
  },
  AvgDialog_149755_Content_99 = {
    Text = "Du klammerten dich mit aller Kraft an den Saum seiner Kleidung, doch du wusstest in deinem Herzen, dass es vergeblich war — er hatte seine Wahl bereits getroffen. Er verneigte sich vor dir, ganz wie der sanftmütigste Held und treueste Ritter in jeder Geschichte, die je erzählt wurde."
  },
  AvgDialog_149756_Content_1 = {Text = "Prinzessin"},
  AvgDialog_149756_Content_10 = {
    Text = "Du willst zurückschreien, lachen, fluchen, schreien, aber ein ölgetränkter Lappen wird dir in den Mund gestopft. Das stinkende, fettige Ding drückt fest gegen den Zungengrund, und außer trockenem Würgen kannst du keinen einzigen Laut von dir geben."
  },
  AvgDialog_149756_Content_11 = {
    Text = "Seht sie an, sie zittert — der Dämon windet sich in ihr. Das ist sein wahres, abscheuliches Gesicht."
  },
  AvgDialog_149756_Content_12 = {
    Text = "Barmherziger Herr, ich flehe Dich an, den Mund zu öffnen, den der Teufel versiegelt hat, und lass sie ihre Sünden mit eigenen Lippen bekennen — wenn noch irgendein Verlangen nach Erlösung in ihrem Herzen verbleibt."
  },
  AvgDialog_149756_Content_13 = {
    Text = "Der Knebel wird grob herausgerissen, und du würgst und hustest zweimal, ringst nach Luft, Speichel läuft dir aus dem Mundwinkel."
  },
  AvgDialog_149756_Content_14 = {
    Text = "Monster mit Äxten und Heugabeln bilden einen Kreis um dich, beobachten dich mit misstrauischen Augen. Weiter entfernt, entlang der Feldraine, zwischen den Ästen, hinter halb geschlossenen Fenstern, lauern noch viel mehr Augen verborgen."
  },
  AvgDialog_149756_Content_15 = {
    Text = "Sprich, Kind! Bekunde deine Reue vor dem Herrn — dies ist dein letzter Moment, um der ewigen Verdammnis zu entgehen!"
  },
  AvgDialog_149756_Content_16 = {
    Text = "<Small:…Monster.>"
  },
  AvgDialog_149756_Content_17 = {
    Text = "Was? Was hat sie gesagt?"
  },
  AvgDialog_149756_Content_18 = {
    Text = "<BigShake:Monster! Monster! Mon— hust hust hust!>"
  },
  AvgDialog_149756_Content_19 = {
    Text = "Deine Worte zerreißen ihre sorgfältig aufgebaute Farce, und die Gesichter der Monster verzerren sich zu Ausdrücken der Panik. Du empfindest eine wilde, bittere Befriedigung."
  },
  AvgDialog_149756_Content_2 = {
    Text = "Die Monster haben meine Familie verschlungen. Jetzt wollen sie mich verschlingen."
  },
  AvgDialog_149756_Content_20 = {
    Text = "Ein Fluch — es ist ein Fluch! Verdammte Hexe!"
  },
  AvgDialog_149756_Content_21 = {
    Text = "Knebelt sie wieder!"
  },
  AvgDialog_149756_Content_22 = {
    Text = "Herr… beschütze uns…"
  },
  AvgDialog_149756_Content_23 = {
    Text = "<Big:Verbrennt sie! Verbrennt sie!>"
  },
  AvgDialog_149756_Content_24 = {
    Text = "<Big:Kobolde! Sumpfkreaturen! Ghule! Monster! Ihr seid alle Mon— waaaaaaah——!!>"
  },
  AvgDialog_149756_Content_25 = {
    Text = "Der Teufel hat ihre Seele bereits in Besitz genommen. Um unser Dorf vor dem Schaden dunkler Zauberei zu schützen, muss dieses unreine Ding beseitigt werden."
  },
  AvgDialog_149756_Content_26 = {
    Text = "Möge das heilige Feuer ihre Sünden verbrennen, möge der Herr uns Frieden schenken."
  },
  AvgDialog_149756_Content_27 = {
    Text = "Bündel um Bündel trockenes Brennholz wird zu deinen Füßen aufgehäuft, Dornen reißen an deiner nackten Haut, und du windest dich vor Schmerz, während die Eisenketten klirren und rasseln."
  },
  AvgDialog_149756_Content_28 = {
    Text = "Das bringt dir noch mehr Hohn und Beleidigungen ein, dazu ein noch fester gezogenes Seil."
  },
  AvgDialog_149756_Content_29 = {
    Text = "Das Feuer entfacht sich."
  },
  AvgDialog_149756_Content_3 = {
    Text = "Die Dämmerung ist ein Vorbote von etwas, das wieder zum Leben erwacht. Die untergehende Sonne ist wie ein krankhaft roter Fleck, und der Himmel schwillt mit gequetschtem Blut."
  },
  AvgDialog_149756_Content_30 = {
    Text = "Wir verstoßen dich … unreiner Geist, abtrünniger Ketzer … wie Rauch, der vom Wind zerstreut wird, wie Wachs, das vom Feuer geschmolzen wird …"
  },
  AvgDialog_149756_Content_31 = {
    Text = "Gefallener, Verfolger, Verbannter — im Namen Seiner Heiligkeit befehle ich dir: zittere, unterwirf dich, fliehe—"
  },
  AvgDialog_149756_Content_32 = {
    Text = "Seine Stimme bricht abrupt ab, als wäre sie mit einer Schere sauber durchtrennt worden."
  },
  AvgDialog_149756_Content_33 = {
    Text = "Du reißt deine brennenden Augen weit auf, und durch den aufsteigenden schwarzen Rauch siehst du einen Fremden neben dem Priester stehen."
  },
  AvgDialog_149756_Content_34 = {
    Text = "Wann ist er aufgetaucht? Du weißt es nicht. Du blickst zu den übrigen Monstern hinüber — sie stehen reglos da wie eine Schar offenmäuliger Frösche."
  },
  AvgDialog_149756_Content_35 = {
    Text = "Der Priester krampft unkontrolliert, beide Hände an die Kehle gepresst, Blut sickert durch seine Finger und spritzt aus seinem Mund, sein Gesicht so fahl wie der Himmel. Er bricht zusammen."
  },
  AvgDialog_149756_Content_36 = {
    Text = "<Big:Ah——!!>"
  },
  AvgDialog_149756_Content_37 = {
    Text = "Schreie, lauter als jede Pfeife, und die Flammenzungen zucken mit ihnen."
  },
  AvgDialog_149756_Content_38 = {
    Text = "Blut … so viel Blut … jemand wurde getötet! Hilfe, Hilfe — das Monster hat jemanden getötet!"
  },
  AvgDialog_149756_Content_39 = {
    Text = "Nein, nein … ein Dämon, es ist ein Dämon! Diese Hexe hat etwas aus der Hölle beschworen! Herr, bitte vergib uns …"
  },
  AvgDialog_149756_Content_4 = {
    Text = "Das Feuer ist noch nicht entfacht, doch die toten Bäume haben sich bereits in verzerrte Formen gewunden — ihre Haltung der Verzweiflung, als wäre selbst das tägliche Tageslicht ein unerträgliches Brennen."
  },
  AvgDialog_149756_Content_40 = {
    Text = "Dein Herz hämmert wild. Du weißt, wer er ist. Du weißt, dass dein Leben heute nicht enden wird — es ist nichts weiter als ein Vorspiel, ein Zwischenspiel, alles nur, um seine Ankunft anzukündigen."
  },
  AvgDialog_149756_Content_41 = {
    Text = "Erfüllt von glühender Hoffnung, reißt du deinen Körper verzweifelt hin und her, stößt gedämpfte Stöhner aus, verzweifelt darauf bedacht, dass er dich ansieht — und vergisst dabei beinahe die glühend heißen Ketten."
  },
  AvgDialog_149756_Content_43 = {
    Text = "Eine behandschuhte Hand zerrt dich aus dem Scheiterhaufen. Deine Beine geben unter dir nach, und du brichst unkontrolliert zu Boden, hustend und würgend, Tränen und Rotz vermischen sich."
  },
  AvgDialog_149756_Content_44 = {
    Text = "<Shake:Hust hust hust hust hust hust hust——!! Warte — hust hust hust hust — warte! Geh nicht!>"
  },
  AvgDialog_149756_Content_45 = {
    Text = "Bevor er sich umdrehen und gehen kann, packst du verzweifelt seinen Umhang."
  },
  AvgDialog_149756_Content_46 = {
    Text = "Scheinbar von deiner Handlung überrascht, rutscht seine Kapuze halb herunter und gibt das Gesicht eines jungen Jungen preis."
  },
  AvgDialog_149756_Content_47 = {Text = "Lass los."},
  AvgDialog_149756_Content_48 = {
    Text = "Du bist klug genug, um den Unterschied zwischen einem Bluff und einer Warnung zu erkennen. Als du an das grausame Ende des Priesters vor nicht allzu langer Zeit denkst, läuft dir ein Schauer über den Rücken."
  },
  AvgDialog_149756_Content_49 = {
    Text = "Doch dann siehst du sein Gesicht — ohne jeden Zweifel muss der edle Ritter aus den Geschichten genau so aussehen. Er muss um deinetwillen gekommen sein, und du hast sogar das Gefühl, dass diese Augen und Brauen dir irgendwie vertraut sind."
  },
  AvgDialog_149756_Content_5 = {
    Text = "<BigShake:Lasst euch nicht von ihrem Äußeren täuschen!> Das Gesicht eines Kindes ist nur eine Verkleidung — ein Teufel wohnt in diesem Körper. Ihre Sünden hat der Herr alle gesehen."
  },
  AvgDialog_149756_Content_50 = {
    Text = "Ja, du musst ihn irgendwo schon einmal gesehen haben — in einem Traum, einem Fluch oder einer Prophezeiung. Wie sonst könntest du diesen plötzlichen Mut erklären?"
  },
  AvgDialog_149756_Content_51 = {
    Text = "<Shake:Nein… hust hust hust, du kannst nicht gehen.>"
  },
  AvgDialog_149756_Content_52 = {Text = "Warum?"},
  AvgDialog_149756_Content_53 = {
    Text = "Weil — hust hust — weil du gekommen bist, um mich zu retten, wie könntest du mich einfach zurücklassen?"
  },
  AvgDialog_149756_Content_54 = {
    Text = "Du bist bereits gerettet. Kehr in das Leben zurück, das dir gehört."
  },
  AvgDialog_149756_Content_55 = {
    Text = "Es gibt hier kein Leben, das mir gehört. Überall sind Monster, die nur Menschen greifen und fressen — du hast es bereits gesehen."
  },
  AvgDialog_149756_Content_56 = {
    Text = "Das hat nichts mit mir zu tun."
  },
  AvgDialog_149756_Content_57 = {
    Text = "Wie kann das nichts mit dir zu tun haben? Ich habe offensichtlich die ganze Zeit auf dich gewartet."
  },
  AvgDialog_149756_Content_58 = {
    Text = "Auf mich gewartet? Du… du kennst mich?"
  },
  AvgDialog_149756_Content_59 = {
    Text = "Natürlich. Du bist mein Ritter."
  },
  AvgDialog_149756_Content_6 = {
    Text = "Sie ist eine Diebin, eine Betrügerin, eine Dienerin der Finsternis. Unheil strömt von ihren Lippen, ihr Gift hat die Brunnen und Flüsse verseucht, und so sind das Vieh und die Schafe tot in ihren Ställen gefallen, und die Frommen wurden von schrecklicher Krankheit heimgesucht."
  },
  AvgDialog_149756_Content_60 = {
    Text = "Schock, Verwirrung, Panik, Qual — eine Flut von Gefühlen überschwemmt sein Gesicht auf einmal. Er reißt seine Hand von dir los, als würde er vor einer Giftschlange zurückschrecken, und drückt sein blutbeflecktes Kurzschwert an deine Kehle."
  },
  AvgDialog_149756_Content_61 = {
    Text = "Wer bist du!"
  },
  AvgDialog_149756_Content_62 = {
    Text = "Ich — ich bin eine Prinzessin! Genau, ich bin eine Prinzessin. Ich wurde von Monstern entführt und habe darauf gewartet, dass du kommst, um mich zu retten!"
  },
  AvgDialog_149756_Content_63 = {
    Text = "Glaub mir — wenn ich keine Prinzessin wäre, warum hätte der Himmel dann einen Ritter geschickt, um mich zu retten?"
  },
  AvgDialog_149756_Content_64 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_149756_Content_65 = {
    Text = "Das Kurzschwert gleitet zurück in seine Scheide. Er steht auf und geht tiefer in den dichten Wald, ohne ein weiteres Wort an dich zu richten."
  },
  AvgDialog_149756_Content_66 = {
    Text = "Warte, wohin gehst du? Ich — hust — ich komme mit dir."
  },
  AvgDialog_149756_Content_67 = {
    Text = "<Shake:Bleib stehen! Hust hust — im Namen der Prinzessin befehle ich dir, stehen zu bleiben!>"
  },
  AvgDialog_149756_Content_68 = {
    Text = "Obwohl er bemerkenswert wendig ist, hast du den Vorteil, diesen Wald wie deine Westentasche zu kennen."
  },
  AvgDialog_149756_Content_69 = {
    Text = "Außerdem hast du nirgendwo sonst hinzugehen — nur zu jagen, und zu jagen, selbst wenn du hier im Wald zusammenbrichst und den Tieren als Futter dienst."
  },
  AvgDialog_149756_Content_7 = {
    Text = "Ihr seid alle Zeugen — wie oft ist sie in den Wald gegangen, spurlos verschwunden und zurückgekehrt, als wäre nichts geschehen? Das ist der Beweis für Hexerei!"
  },
  AvgDialog_149756_Content_70 = {
    Text = "<Shake:Huff… huff… warte, ich — ich kenne die Regeln.>"
  },
  AvgDialog_149756_Content_71 = {
    Text = "Ich muss irgendwo hin. Begleite mich dorthin, und du wirst Ehre und Belohnung erhalten."
  },
  AvgDialog_149756_Content_72 = {
    Text = "Ich brauche nichts davon."
  },
  AvgDialog_149756_Content_73 = {
    Text = "Doch — zumindest jetzt brauchst du jemanden, der dich hier herausführt, nicht wahr?"
  },
  AvgDialog_149756_Content_74 = {
    Text = "Er antwortete nicht, aber seine Schritte kamen allmählich zum Stillstand."
  },
  AvgDialog_149756_Content_75 = {
    Text = "Wohin gehst du?"
  },
  AvgDialog_149756_Content_76 = {
    Text = "Hmm… ach ja, die Insel der Äpfel — hast du davon gehört? Ein Paradies, wo nichts gepflanzt werden muss, niemand krank wird und der Winter nie kommt. Dorthin bin ich unterwegs."
  },
  AvgDialog_149756_Content_77 = {
    Text = "Noch nie gehört. Wo ist sie?"
  },
  AvgDialog_149756_Content_78 = {
    Text = "Die Fee hat mir die Richtung nicht verraten, aber sie sagte, ich würde sie eines Tages finden — genau wie sie es tat. Wir können gleichzeitig gehen und suchen. Schließlich sind große Abenteuer immer voller Herausforderungen, nicht wahr?"
  },
  AvgDialog_149756_Content_79 = {
    Text = "Der schwarze Umhang verschmolz mit der Dunkelheit der Nacht. Er stand hinter einem Gestrüpp aus überwucherten Sträuchern, seine Züge kaum zu erkennen."
  },
  AvgDialog_149756_Content_8 = {
    Text = "<SmallShake:Die Seuche… eine Hexe… ja, es ist wegen der Hexe… der Fluch der Hexe…>"
  },
  AvgDialog_149756_Content_80 = {
    Text = "Du bewegtest dich mit mühsamer Langsamkeit auf ihn zu, als hättest du Angst, einen wilden Wolf aufzuschrecken."
  },
  AvgDialog_149756_Content_81 = {
    Text = "Halt. Bleib dort. Komm nicht näher."
  },
  AvgDialog_149756_Content_82 = {Text = "Geh voran."},
  AvgDialog_149756_Content_83 = {
    Text = "Bedeutet das, dass du einverstanden bist, tapferer Ritter?"
  },
  AvgDialog_149756_Content_84 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_149756_Content_85 = {
    Text = "Ich bin kein Ritter."
  },
  AvgDialog_149756_Content_86 = {
    Text = "Doch. Von diesem Moment an bist du mein treuer Ritter."
  },
  AvgDialog_149756_Content_87 = {
    Text = "Ein Ritter hält sein Versprechen — bis wir die Insel der Äpfel erreichen, musst du mich beschützen. Du wirst vorausgehen und die Dornen und Ranken für mich beiseiteräumen. Wenn Monster uns verfolgen, wirst du sie vertreiben, und außerdem…"
  },
  AvgDialog_149756_Content_88 = {
    Text = "Wohin gehst du? Du hast noch nicht geschworen! Wenn du es wagst, deine Prinzessin zu belügen und zu betrügen, wirst du von Monstern gepackt und gefressen. Schwöre zuerst."
  },
  AvgDialog_149756_Content_89 = {
    Text = "Hey! Geh nicht — warte auf mich — ich kenne den Weg!"
  },
  AvgDialog_149756_Content_9 = {
    Text = "Eine Hexe, die noch keine zehn Jahre alt ist? Selbst ein Wahnsinniger könnte keine solche Lüge spinnen."
  },
  AvgDialog_149757_Content_1 = {
    Text = "Grabstätte"
  },
  AvgDialog_149757_Content_10 = {
    Text = "<Shake:Hah, hah... wo bist du... mein Ritter...>"
  },
  AvgDialog_149757_Content_11 = {
    Text = "Du erinnertest dich an das Gerücht, und deine Sorge wuchs. Du konntest niemals zulassen, dass dein einziger Ritter von einem Teufel besiegt wurde. Du würdest seinen Namen nicht vergessen — das hattest du bereits nicht."
  },
  AvgDialog_149757_Content_12 = {
    Text = "Ogier... genau, Ogier! Wo bist du! <Big:O — gi — er —>"
  },
  AvgDialog_149757_Content_13 = {
    Text = "Ein Schmerzensschrei durchdrang den Regenvorhang — eher wie ein verwundetes Tier als ein Mensch. Du brachst sofort in Richtung der Geräuschquelle auf."
  },
  AvgDialog_149757_Content_14 = {
    Text = "Hör auf dich zu verstecken! Ich kann dich bereits sehen!"
  },
  AvgDialog_149757_Content_15 = {
    Text = "Geh weg! Komm — hah — komm mir nicht näher!!"
  },
  AvgDialog_149757_Content_16 = {
    Text = "Das Lampenlicht flackerte und zitterte, unfähig, die von allen Seiten hereinbrechende Dunkelheit zurückzudrängen. Dein Ritter war in die Enge getrieben worden, sein angespannter Rücken wie eine gespannte Armbrust."
  },
  AvgDialog_149757_Content_17 = {
    Text = "Halt die Klappe! Ich habe nicht vergessen! Das ist nicht — nein, ich habe nie — ich werde nicht vergessen!"
  },
  AvgDialog_149757_Content_18 = {
    Text = "<Shake:Ich werde sie rächen... ich muss sie rächen... Auge um Auge, Zahn um Zahn...>"
  },
  AvgDialog_149757_Content_19 = {
    Text = "Nein, das wirst du nicht, du lügst! Die Prinzessin würde das niemals sagen, die Prinzessin, sie —"
  },
  AvgDialog_149757_Content_2 = {
    Text = "Du hast einmal jemanden sagen hören, dass der Name eines jeden Menschen ein Fluch ist."
  },
  AvgDialog_149757_Content_20 = {
    Text = "<Big:Ugh — !!>"
  },
  AvgDialog_149757_Content_21 = {
    Text = "Das wirre Gerede wurde von einem Schrei unterbrochen, als hätte jemand einen Speer durch seine Brust getrieben. Er stolperte und fiel auf die Knie, doch der Schatten hinter ihm blieb stehen — wie eine Rüstung, wie ein Käfig."
  },
  AvgDialog_149757_Content_22 = {
    Text = "Du spürtest eine Welle der Panik. Du wusstest, dass wenn du es jetzt nicht aufhieltest, der Schatten zur Person werden würde und die Person in den Schatten fallen würde."
  },
  AvgDialog_149757_Content_23 = {
    Text = "Wach auf! Hör nicht auf ihn — deine Prinzessin ist genau hier!!"
  },
  AvgDialog_149757_Content_24 = {
    Text = "<Shake:……@1@2Eure Hoheit… habe ich Euch enttäuscht?>"
  },
  AvgDialog_149757_Content_25 = {
    Text = "<Shake:Ich bin nicht geflohen, Ihr habt mir befohlen zu gehen——>Nein, das meinte ich nicht. Ich habe Euch versagt. Ich habe kein Recht, um Vergebung zu bitten."
  },
  AvgDialog_149757_Content_26 = {
    Text = "<Shake:Schande… Schande Schande Schande Schande Schande Schande Schande Schande, Schande ist das Einzige, was ich besitze…>"
  },
  AvgDialog_149757_Content_27 = {
    Text = "<Shake:Ich bin kein Ritter, ich bin… ich bin…>"
  },
  AvgDialog_149757_Content_28 = {Text = "<Red:Wer?>"},
  AvgDialog_149757_Content_29 = {
    Text = "Einen Moment lang in Verwirrung verloren, hob er sein Gesicht, um dich anzusehen — wenn man es noch ein Gesicht nennen konnte."
  },
  AvgDialog_149757_Content_3 = {
    Text = "Wenn man unvorsichtig genug ist, seinen Namen zu verlieren — ob von einem selbst vergessen oder von anderen vergessen — wird man wie ein Schaf, das von der Herde abgeirrt ist, des Schutzes beraubt, und der Teufel wird seine Augen auf einen richten."
  },
  AvgDialog_149757_Content_30 = {
    Text = "Der Schatten hatte sein Fleisch zerfressen und Spuren hinterlassen wie die Pfade kriechender Schnecken. Seine Züge waren gefleckt und eitrig, doch was aus den Wunden sickerte, war pechschwarzer, zäher Schlamm."
  },
  AvgDialog_149757_Content_31 = {
    Text = "Auf wessen Antwort wartete er? Der kalte Regen hatte deine Lippen und deine Zunge erstarren lassen. Du standst reglos im Schlamm, ein verspätetes Zittern breitete sich durch deine Glieder aus."
  },
  AvgDialog_149757_Content_32 = {
    Text = "…W-warte, ich weiß es! Du bist——"
  },
  AvgDialog_149757_Content_33 = {
    Text = "<BigShake:Nein! Ogier!!>"
  },
  AvgDialog_149757_Content_34 = {
    Text = "Schwarzer Schlamm brach aus seiner Brust hervor. Dein Ritter erschöpfte die letzten seiner Kräfte in Stille und brach kraftlos zusammen, wie eine weggeworfene leere Hülle, während Schatten ihn umkreisten und gleichzeitig lachten und weinten."
  },
  AvgDialog_149757_Content_35 = {
    Text = "Du wurdest Zeuge, wie ein Mensch auseinanderfällt."
  },
  AvgDialog_149757_Content_36 = {
    Text = "Ogier! Du bist Ogier! Ich weiß es — ich erinnere mich jetzt! Der Teufel kann dir nichts anhaben, ich habe mich bereits erinnert!"
  },
  AvgDialog_149757_Content_37 = {
    Text = "Wach auf! Kannst du mich hören? Wach auf, wir sind noch nicht dort! Dir wird es gut gehen — Avalon, der Teufel kann diesen Ort nicht erreichen. Sobald wir nach Avalon gelangen, wird alles gut sein! Steh auf, steh jetzt auf!"
  },
  AvgDialog_149757_Content_38 = {
    Text = "Der Platzregen hatte den Wald in einen Sumpf aus faulendem Morast verwandelt. Du schriestdu zogst, du weintest — nur um selbst tiefer zu versinken. Du hattest keine Ahnung, wohin du sonst noch fliehen könntest."
  },
  AvgDialog_149757_Content_39 = {
    Text = "So stirbt also die Welt… lebendig begraben von der Verzweiflung."
  },
  AvgDialog_149757_Content_4 = {
    Text = "Vielleicht hatte dein Ritter, wie du, alles vom Monster genommen bekommen. Er verlor sogar noch mehr als du — nicht einmal sein Name blieb zurück."
  },
  AvgDialog_149757_Content_40 = {
    Text = "<SmallShake:Hust… hust, hust…>"
  },
  AvgDialog_149757_Content_41 = {
    Text = "<SmallShake:Wenn der Regen aufhört… geh zum Friedhof…>"
  },
  AvgDialog_149757_Content_42 = {
    Text = "Ogier! Du lebst noch!"
  },
  AvgDialog_149757_Content_43 = {
    Text = "Warte, der Friedhof? Wozu? Bist du — lebst du wirklich noch?"
  },
  AvgDialog_149757_Content_44 = {
    Text = "<Shake:Geh zum Friedhof… Beerdigung… keine Zeit… muss begraben werden…>"
  },
  AvgDialog_149757_Content_45 = {
    Text = "Wen? Wen musst du begraben?"
  },
  AvgDialog_149757_Content_46 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_149757_Content_47 = {
    Text = "Er verstummte und blickte geradeaus nach oben — zum Ende aller Sümpfe, wo jede Erinnerung und jedes Vergessen sich auflösen würde, wo Regen fiel und die Luft immer dünner werden ließ."
  },
  AvgDialog_149757_Content_48 = {
    Text = "Doch den Himmel kann man nie erreichen, also bleibt nur der Weg zum Friedhof. Das ist der Ort, der dem Ende am nächsten liegt."
  },
  AvgDialog_149757_Content_49 = {
    Text = "Nur für ein Stück leere Erde, und es kostet so viel…"
  },
  AvgDialog_149757_Content_5 = {
    Text = "Und so entblößte der lauernde <Red:Dämon> seine Reißzähne."
  },
  AvgDialog_149757_Content_50 = {
    Text = "Hättest du früher gewusst, wie teuer der Ort ist, an dem Monster sich begraben, wärst du niemals gekommen."
  },
  AvgDialog_149757_Content_51 = {
    Text = "Der Regen fiel drei Tage lang ohne Unterbrechung, bevor er endlich für einen kurzen Atemzug pausierte. Dein Ritter war im Kampf gegen den Teufel schwer verwundet worden und konnte dich nur an seiner Stelle zum Friedhof schicken, um das Bündel zu begraben, das er bei sich getragen hatte. Er sagte, es seien die zurückgelassenen Habseligkeiten von jemandem."
  },
  AvgDialog_149757_Content_52 = {
    Text = "Der Grabstein war leer — kein Name eingraviert. Du hattest keine Ahnung, für wen er errichtet worden war."
  },
  AvgDialog_149757_Content_53 = {
    Text = "Eine Kerze, ein Kamm, eine kleine Steinfigur, ein Stück Pergament…"
  },
  AvgDialog_149757_Content_54 = {
    Text = "Das Bündel war leicht, mit wenigen Dingen darin, doch alle waren stark beschädigt. Du zerbrach dir den Kopf, fand aber keine Antworten. Auch dein Ritter war dir ein Rätsel — du wusstest nichts über ihn."
  },
  AvgDialog_149757_Content_55 = {
    Text = "…Soll selbst der heilige Gral mit dem Rest begraben werden?"
  },
  AvgDialog_149757_Content_56 = {
    Text = "He, du Kleines da drüben — aus welcher Familie stammst du? Was schleichst du hier herum?"
  },
  AvgDialog_149757_Content_57 = {
    Text = "In Rüstungen gekleidete Monster marschierten durch den Friedhof. Eines von ihnen blieb plötzlich stehen, und dann hielt die gesamte Kolonne an. Sie standen in perfekter Formation, ununterscheidbar voneinander, wie ein riesiger, vielsegmentiger Tausendfüßler."
  },
  AvgDialog_149757_Content_58 = {
    Text = "Taub geworden? Ich frage, woher du kommst — he, warum läufst du weg? Fangt sie!"
  },
  AvgDialog_149757_Content_59 = {
    Text = "Loslassen! Lasst mich los! Ich habe nichts getan — ich habe dieses Grundstück gekauft!"
  },
  AvgDialog_149757_Content_6 = {
    Text = "Wo... wo... ist es nicht diese Richtung?"
  },
  AvgDialog_149757_Content_60 = {
    Text = "Du hast es gekauft? Ha, dann sag mir — auf dem Stein steht nicht einmal ein Name. Wessen Grab ist das?"
  },
  AvgDialog_149757_Content_61 = {
    Text = "Ich... Ich..."
  },
  AvgDialog_149757_Content_62 = {
    Text = "Meine Herren, dies ist der Friedhof der Diözese. Dieses Kind hat tatsächlich ein Grundstück erworben — alles ist im Register verzeichnet."
  },
  AvgDialog_149757_Content_63 = {
    Text = "Was Namen betrifft — die Pest ist bereits gekommen. Menschen verschwinden jeden Tag. Sind namenlose Grabsteine wirklich so selten?"
  },
  AvgDialog_149757_Content_64 = {
    Text = "Die Mienen der Monster veränderten sich. Sie tauschten Blicke aus und eilten davon, als hätten sie Angst, sich etwas einzufangen. In diesen Augen erkanntest du eine vertraute Furcht."
  },
  AvgDialog_149757_Content_65 = {Text = "Pest?"},
  AvgDialog_149757_Content_66 = {
    Text = "Ja — die grausame Pest, die schreckliche Pest. Einen Menschen vergessen zu lassen, braucht nur wenig Zeit. Stein vergessen zu lassen hingegen erfordert, den Stein zu Sand zu zermahlen."
  },
  AvgDialog_149757_Content_67 = {
    Text = "Die Steine des Vergessens werden immer zahlreicher, die Alten werden so leer wie Kinder, und uns bleiben keine Geschichten mehr."
  },
  AvgDialog_149757_Content_68 = {
    Text = "Du… glaubst du nicht, dass dies ein Fluch ist? Wegen der Hexe oder irgendetwas anderem."
  },
  AvgDialog_149757_Content_69 = {
    Text = "Ein Fluch, eine Seuche, die Strafe des Herrn oder die Rache des Todesritters — was macht das für einen Unterschied? Wir sind machtlos, Kind. Wir können nur auf das Gegenwärtige blicken. Das Gegenwärtige ist alles, was wir je haben können. Das war schon immer so."
  },
  AvgDialog_149757_Content_7 = {
    Text = "Die mondlose Nacht war pechschwarz, und der dichte Wald schien bodenlos. Du drücktest die Laterne an deine Brust und suchtest überall nach Spuren einer panischen Flucht."
  },
  AvgDialog_149757_Content_70 = {
    Text = "Geh nach Hause. Es wird bald dunkel."
  },
  AvgDialog_149757_Content_71 = {
    Text = "Warte — ein Todesritter? Was ist das?"
  },
  AvgDialog_149757_Content_72 = {
    Text = "Eine Legende. Jener Krieg war ein Fehler. Sie riefen dazu auf, die Seuche auszurotten, und brachten sie doch nur schneller über uns. Sie schufen ein Monster."
  },
  AvgDialog_149757_Content_73 = {
    Text = "Er verbirgt sich im Schatten von Bäumen, Schiffen, Steinmauern und fliegenden Vögeln, bewegt sich von einem Ort zum anderen — selbst das Sonnenlicht kann ihn nicht erreichen."
  },
  AvgDialog_149757_Content_74 = {
    Text = "Sein Blut ist pechschwarz, sein Herz brennt mit einer geisterhaften Flamme, seine Augen leuchten wie aus den Tiefen eines Sumpfes. Wo immer er vorbeizieht, hinterlässt er Schatten, die das Tageslicht zerschneiden."
  },
  AvgDialog_149757_Content_75 = {
    Text = "Er ist die Fortsetzung jenes Krieges, ein Gefäß des Grolls der Toten. Er erscheint nur bei Nacht, um seine Feinde zu vernichten. Er vergisst nie, er wankt nie. Der Grund seines Kommens liegt klar auf der Hand — unser Herr und das Land, das einst ihm gehörte."
  },
  AvgDialog_149757_Content_76 = {
    Text = "Was? Du meinst, der Herr ist sein Feind, und er kam hierher... um sich zu rächen?"
  },
  AvgDialog_149757_Content_77 = {
    Text = "Natürlich. Wir alle wissen es, und der Herr weiß es auch. Warum sonst würde die Stadt plötzlich von so vielen patrouillierenden Soldaten wimmeln?"
  },
  AvgDialog_149757_Content_78 = {
    Text = "Sie alle warten auf ihn."
  },
  AvgDialog_149757_Content_79 = {
    Text = "Der Regen hat wieder eingesetzt, und die Straßen gleichen einem fließenden Fluss."
  },
  AvgDialog_149757_Content_8 = {
    Text = "Bevor die Schatten ihn verschluckten, sagte er dir, du sollst gehen — doch wie könnte eine Prinzessin ohne ihren Ritter sein? Du versuchtest, ihn loszureißen, doch er schüttelte deine Hand ab, stürzte durch das Fenster, sprang vom Dachboden und verschwand in den wilden Wäldern jenseits des Herrenhauses."
  },
  AvgDialog_149757_Content_80 = {
    Text = "Du drückst all die Reliquien an deine Brust und sprintest kopfüber durch die engen Gassen, weichst knapp einer Patrouille nach der anderen aus und steurest geradewegs auf den Strohdachschuppen zu, in dem du dich versteckst."
  },
  AvgDialog_149757_Content_81 = {
    Text = "<Shake:Schneller, schneller — zurück und ihm Bescheid geben...>"
  },
  AvgDialog_149757_Content_82 = {
    Text = "Das Monster, von dem Monster sprechen — zweifellos dein Ritter. Seine dreisten Morde sind schließlich dem Herrn zu Ohren gekommen. Es heißt, heute Nacht werden die Wachen jeden Winkel der Stadt durchsuchen."
  },
  AvgDialog_149757_Content_83 = {
    Text = "Es ist noch Zeit. Die Stadttore sind noch nicht geschlossen. Nur ein wenig schneller..."
  },
  AvgDialog_149757_Content_84 = {
    Text = "<Big:Ogier! Lauf — sie kommen—>"
  },
  AvgDialog_149757_Content_85 = {
    Text = "Der enge Schuppen wurde am Ende einer Sackgasse errichtet, ringsum mit Jutesäcken gestapelt, die den fließenden Schlamm dennoch nicht aufhalten konnten. Du stürzt auf die Gestalt zu, die in der hintersten Ecke liegt, und greifst nach seinem Umhang — nur um einen leeren Umhang hochzuziehen."
  },
  AvgDialog_149757_Content_86 = {
    Text = "Im Inneren des Schuppens befindet sich nichts als trockenes Stroh. Von deinem Ritter fehlt jede Spur."
  },
  AvgDialog_149757_Content_9 = {
    Text = "Der strömende Regen wusch die gebrochenen Äste und die letzten Fußspuren fort. Jede Richtung sah gleich aus, und deine Schritte wurden langsamer und langsamer, bis du schließlich stehenbliebst, verloren und verwirrt."
  },
  AvgDialog_15363_Content_1 = {
    Text = "Frau Corals Tod"
  },
  AvgDialog_15363_Content_10 = {
    Text = "Die Menge drängte sich dicht darum, unzählige Kamerablitze gingen los, sich überlappende laute Diskussionen erfüllten die Luft, bis ein Mitarbeiter plötzlich die Verhüllung lüftete."
  },
  AvgDialog_15363_Content_11 = {
    Text = "Das ist... Oh mein Gott."
  },
  AvgDialog_15363_Content_12 = {
    Text = "...Unglaublich."
  },
  AvgDialog_15363_Content_13 = {
    Text = "Als hätte jemand einen Schalter umgelegt; die Menge verstummte automatisch und ließ die einst belebte Halle irgendwie leer wirken."
  },
  AvgDialog_15363_Content_14 = {
    Text = "Du kämpfst dich durch die Menge und erhaschst endlich einen Blick auf das Kunstwerk, das in der Mitte umringt wird."
  },
  AvgDialog_15363_Content_15 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_15363_Content_16 = {
    Text = "Es ist Sanga. Sie hat all ihre Primärfarbe und Emotion verloren und sich in eine rein weiße Korallenskulptur verwandelt."
  },
  AvgDialog_15363_Content_17 = {
    Text = "Helles Tageslicht brach sich durch das makellose Kuppelglas und hüllte sie in ein sanftes, goldenes Leuchten."
  },
  AvgDialog_15363_Content_18 = {
    Text = "Du blickst hinab auf die Messingplakette am Sockel der Skulptur, in die ihr Name in eleganter Schrift eingraviert ist: <Red:„Namenlose Tochter der Koralle\">."
  },
  AvgDialog_15363_Content_19 = {
    Text = "Namenlose Koralle..."
  },
  AvgDialog_15363_Content_2 = {
    Text = "Lieber Herr Claud:\n\nIn letzter Zeit ist viel geschehen; bitte verzeiht meine verspätete Antwort.\n\nSeit Fräulein Sanga fort ist, konnte Herr August keine bemerkenswerten Werke mehr schaffen.\nUnter dem Druck der öffentlichen Meinung verkündete er eine unbefristete Pause seiner Bildhauerlaufbahn.\nEr hat die Strafe erhalten, die er verdiente, und doch kann ich keine Freude empfinden—<Yellow:Fräulein Sanga wird noch immer vermisst.>"
  },
  AvgDialog_15363_Content_20 = {
    Text = "Du starrst wie in Trance auf den Text, dein Bewusstsein wiegt und windet sich mit den eleganten Schriftzügen..."
  },
  AvgDialog_15363_Content_21 = {
    Text = "Er hob die Hand, um sich die Augen zu reiben, nur um raue, matte White-Schichten zu entdecken, die sich zwischen seinen Fingern ausbreiteten."
  },
  AvgDialog_15363_Content_22 = {Text = "?!"},
  AvgDialog_15363_Content_23 = {
    Text = "Weißer Korallennebel breitete sich von deinen Fingerspitzen aus, bedeckte allmählich deinen gesamten Körper, füllte rasch die gesamte Halle und dann—"
  },
  AvgDialog_15363_Content_24 = {Text = "—!!"},
  AvgDialog_15363_Content_25 = {
    Text = "Du und die Ausstellungshalle zerbrechen in unzählige weiße Fragmente und fallen in die endlosen Tiefen des Ozeans."
  },
  AvgDialog_15363_Content_26 = {
    Text = "Inmitten unzähliger weißer Skulpturen und Korallen, gebadet im ruhigen Morgenlicht, ragen die Ruinen eines weißen Palastes empor."
  },
  AvgDialog_15363_Content_27 = {
    Text = "Bunte Fische schwimmen durch die schiefen Bögen und Korridore der Ruinen und genießen ihre gemächlichen Augenblicke."
  },
  AvgDialog_15363_Content_28 = {
    Text = "Die gesamte Ruine schien im Schatten der Zeit vergessen zu sein, weit entfernt von der Korrosion der Welt und dem Lärm der Menge."
  },
  AvgDialog_15363_Content_29 = {
    Text = "Wenn du diese Wunder gesehen hast... wirst du mich verstehen."
  },
  AvgDialog_15363_Content_3 = {
    Text = "<Yellow:Morgen werde ich mich zum Seite-Salon begeben, um die „Antwort\" zu finden, die Fräulein Sanga erwähnte.>\nWünscht mir Glück.\n\nCamille@1\nA.F.2@1 Sep"
  },
  AvgDialog_15363_Content_30 = {
    Text = "Ist das... das Wunder, das Sie gesehen haben, Frau Sanga?"
  },
  AvgDialog_15363_Content_31 = {
    Text = "Du treibst im warmen Meer, fasziniert und zugleich verwirrt von allem, was vor dir liegt."
  },
  AvgDialog_15363_Content_32 = {
    Text = "Zur Seite, lasst mich durch!!"
  },
  AvgDialog_15363_Content_33 = {
    Text = "<Big:Lass mich durch!!>"
  },
  AvgDialog_15363_Content_34 = {
    Text = "Der lärmende Tumult reißt dich zurück in die Realität."
  },
  AvgDialog_15363_Content_35 = {
    Text = "Ein zerlumpter alter Mann durchbricht die Sicherheitsabsperrungen und stürzt auf dich zu, deine Hand fest umklammernd."
  },
  AvgDialog_15363_Content_36 = {
    Text = "Du hast es gesehen, oder? Aequor, den Palast, diese chaotischen Illusionen..."
  },
  AvgDialog_15363_Content_37 = {Text = "?!"},
  AvgDialog_15363_Content_38 = {
    Text = "Diese niederträchtige Frau ist eine Diebin..."
  },
  AvgDialog_15363_Content_39 = {
    Text = "Der alte Mann murmelte vor sich hin. Du blicktest auf das Gesicht, das unter der breiten Krempe und dem dichten Bart verborgen war, und bemerktest plötzlich etwas Ungewöhnliches."
  },
  AvgDialog_15363_Content_4 = {
    Text = "Seite-Salonausstellung\nEröffnungstag"
  },
  AvgDialog_15363_Content_40 = {
    Text = "...Mr. August?!"
  },
  AvgDialog_15363_Content_41 = {
    Text = "Hiss, es ist wirklich er... Mein Gott! Was ist mit ihm geschehen?"
  },
  AvgDialog_15363_Content_42 = {
    Text = "Er ging schon vor langer Zeit bankrott, hast du das nicht gehört? Nach dem Fiasko mit der \"Tragic Muse\" investierte er stark in mehrere Projekte, aber keines von ihnen verkaufte sich"
  },
  AvgDialog_15363_Content_43 = {
    Text = "Die Regierung ist inzwischen misstrauisch gegenüber seinem Ruf und erteilt ihm keine Aufträge mehr. Vielleicht hat ihn der Druck in den Wahnsinn getrieben..."
  },
  AvgDialog_15363_Content_44 = {
    Text = "Die Menschen waren gleichermaßen schockiert und verängstigt und starrten August aus vorsichtiger Entfernung an."
  },
  AvgDialog_15363_Content_45 = {
    Text = "August reißt seine Hand von dir los und humpelt auf die Skulptur zu, seine Augen voller unkontrollierbarem Hass."
  },
  AvgDialog_15363_Content_46 = {
    Text = "Hmph... Glaubst du, der Tod kann alles wiedergutmachen, was du getan hast?"
  },
  AvgDialog_15363_Content_47 = {
    Text = "Du hast alle getäuscht... Du hast mir all mein Talent, meine Inspiration und meinen Ruhm genommen."
  },
  AvgDialog_15363_Content_48 = {
    Text = "Ich bin ruiniert, vollkommen ruiniert. Und du? Sitzt hier gemütlich, genießt die Bewunderung aller, wartest darauf, dass sie dich zum Klassiker krönen..."
  },
  AvgDialog_15363_Content_49 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_15363_Content_5 = {
    Text = "Habt Ihr gehört? Herr August stellt wieder seine Skulpturen aus."
  },
  AvgDialog_15363_Content_50 = {
    Text = "Angesichts der hysterischen Verwünschungen des einstigen Lehrers steht die Skulptur schweigend da, ihr gleichgültiger Ausdruck unerschütterlich."
  },
  AvgDialog_15363_Content_51 = {
    Text = "August konnte es nicht länger ertragen; voller Wut stürzte er sich auf die Skulptur."
  },
  AvgDialog_15363_Content_52 = {
    Text = "Derselbe Ausdruck, derselbe Spott..."
  },
  AvgDialog_15363_Content_53 = {
    Text = "Teufel... Teufel! <Big:Ich reiße dir die Maske herunter!>"
  },
  AvgDialog_15363_Content_6 = {
    Text = "August, der Bildhauer? Ist er nicht verschwunden, nachdem man ihn des Plagiats beschuldigt hatte? Ich dachte, er würde sich nie wieder blicken lassen."
  },
  AvgDialog_15363_Content_7 = {
    Text = "Ich bin recht neugierig—ohne jene Schülerin, was könnte er jetzt wohl noch zustande bringen..."
  },
  AvgDialog_15363_Content_8 = {
    Text = "Die Eröffnungszeremonie der Salonausstellung war voller Menschen."
  },
  AvgDialog_15363_Content_9 = {
    Text = "Augusts Werk steht in der Mitte der Ausstellungshalle, verhüllt von schweren Tüchern, und weckt endlose Neugier."
  },
  AvgDialog_15364_Content_1 = {Text = "Hmm!!"},
  AvgDialog_15364_Content_10 = {
    Text = "Cité-Salonausstellung\nDie Nacht des Eröffnungstages"
  },
  AvgDialog_15364_Content_11 = {
    Text = "Als das letzte Schloss zuklickte, versank die Ausstellungshalle in Totenstille."
  },
  AvgDialog_15364_Content_12 = {
    Text = "Du trittst aus den Schatten in der Ecke hervor und stehst erneut vor ihr."
  },
  AvgDialog_15364_Content_13 = {
    Text = "Hier, frei vom Lärm des Tages, ist der perfekte Zeitpunkt für ein Gespräch."
  },
  AvgDialog_15364_Content_14 = {
    Text = "Frau Sanga, Herr Auguste wurde heute abgeführt. Er sagte...\nSie haben alle getäuscht."
  },
  AvgDialog_15364_Content_15 = {
    Text = "Schließt „alle“ hier auch mich mit ein?"
  },
  AvgDialog_15364_Content_16 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_15364_Content_17 = {
    Text = "Hast du versprochen, mit mir nach Hause zu gehen? Ist das wahr?"
  },
  AvgDialog_15364_Content_18 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_15364_Content_19 = {
    Text = "Die Skulptur schweigt. Obwohl das Leben aller durch sie verändert wurde, senkt sie niemals ihren Blick aus der Ferne."
  },
  AvgDialog_15364_Content_2 = {
    Text = "Lasst mich los! Die Person, die ihr sucht, ist sie, sie ist es—"
  },
  AvgDialog_15364_Content_20 = {
    Text = "Mondlicht durchdringt das Glasfenster der Galerie und hüllt sie in einen Schleier aus weißem Licht."
  },
  AvgDialog_15364_Content_21 = {
    Text = "<Red:Folge meinem Blick...>"
  },
  AvgDialog_15364_Content_22 = {
    Text = "Folge dem Blick... Könnte das sein?!"
  },
  AvgDialog_15364_Content_23 = {
    Text = "Du stellst dich auf die Zehenspitzen und bemerkst, dass sich die ursprünglich gleichgültigen und unfokussierten Augen der Skulptur im Mondlicht verändert haben – nun erfüllt von einer bestimmten und intensiven Emotion."
  },
  AvgDialog_15364_Content_24 = {
    Text = "Sie blickt unablässig in die Ferne."
  },
  AvgDialog_15364_Content_25 = {
    Text = "Du folgst ihrem Blick und drehst dich um."
  },
  AvgDialog_15364_Content_26 = {
    Text = "In dem Moment, als dein Blick abschweifte, verschwand die Ausstellungshalle unter deinen Füßen auf wundersame Weise."
  },
  AvgDialog_15364_Content_27 = {
    Text = "Stattdessen erstreckt sich ein endloses Meer und ein weiter, schneeweißer Strand."
  },
  AvgDialog_15364_Content_28 = {
    Text = "Ferner Donner grollt, die Flut wogt heftig und rauscht auf dich zu."
  },
  AvgDialog_15364_Content_29 = {
    Text = "Dies ist das Meer, das du und Sanga einst besucht habt."
  },
  AvgDialog_15364_Content_3 = {
    Text = "Herr Auguste, wir haben Berichte erhalten, dass Ihre Handlungen die Ordnung der Salonausstellung erheblich gestört haben. Bitte kommen Sie mit uns."
  },
  AvgDialog_15364_Content_4 = {
    Text = "Nein, nein..."
  },
  AvgDialog_15364_Content_5 = {
    Text = "Die Szene ist chaotisch, und der Ansturm der Menschen aus allen Richtungen hat dich vollständig von August getrennt. Du kannst nur zusehen, wie er von der Polizei gewaltsam weggezerrt wird."
  },
  AvgDialog_15364_Content_6 = {
    Text = "Freut euch nicht zu früh... Eines Tages werdet ihr genauso enden wie ich..."
  },
  AvgDialog_15364_Content_7 = {
    Text = "Heh... Hehehe..."
  },
  AvgDialog_15364_Content_8 = {
    Text = "In der Ausstellungshalle ist endlich wieder Ordnung eingekehrt."
  },
  AvgDialog_15364_Content_9 = {
    Text = "Augusts letztes zitterndes, neurotisches Lachen hallte schwach durch die leere Galerie, wie sich abschwächende Wellen."
  },
  AvgDialog_15365_Content_1 = {
    Text = "Mitte des Meeres"
  },
  AvgDialog_15365_Content_10 = {
    Text = "Wie erwartet, du bist es.\nVerzeihung, habe ich dich gestört, als ich nachts aufgestanden bin?"
  },
  AvgDialog_15365_Content_11 = {
    Text = "Anstatt mich aufzuwecken, solltest du dir eher Sorgen machen, ob du die <Blue:alten Gesellen, die unter der Erde schlafen>, störst."
  },
  AvgDialog_15365_Content_12 = {
    Text = "Du hobst dein Kinn und deutetest auf das Grab vor ihr, das bereits fast einen Fuß tief aufgegraben worden war."
  },
  AvgDialog_15365_Content_13 = {
    Text = "Suchst du etwas? Brauchst du Hilfe?"
  },
  AvgDialog_15365_Content_14 = {
    Text = "Es ist in Ordnung, ich habe es bereits gefunden."
  },
  AvgDialog_15365_Content_15 = {
    Text = "Sanga lächelte und zeigte dir ihre Hand, bedeckt mit einer schwarzen, klebrigen Flüssigkeit—"
  },
  AvgDialog_15365_Content_16 = {
    Text = "Das ist A-Schleim. Du bist bestens mit ihm vertraut."
  },
  AvgDialog_15365_Content_17 = {
    Text = "Hast du das gesehen? Im Mondlicht strahlt er ein seltsames blaues Leuchten aus. Tagsüber nimmt er ein ganz anderes Aussehen an..."
  },
  AvgDialog_15365_Content_18 = {
    Text = "Das ist das perfekteste Skulpturenmaterial, das ich je gesehen habe."
  },
  AvgDialog_15365_Content_19 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_15365_Content_2 = {
    Text = "Sehr geehrter Herr Claudel,\n\nFräulein Sanga hat es nicht abgelehnt, nach Hause zurückzukehren, bat jedoch um etwas Zeit.\nSie sagte: <Yellow:„Ich werde nach der Salonausstellung nach Hause zurückkehren.\">\n\nAllerdings ist Fräulein Sangas jüngster Zustand besorgniserregend.\nSie schleicht sich spät in der Nacht hinaus und kehrt erst in der Morgendämmerung zurück."
  },
  AvgDialog_15365_Content_20 = {
    Text = "Schleichst du dich jede Nacht raus, nur um hier A-Schleim zu sammeln?"
  },
  AvgDialog_15365_Content_21 = {
    Text = "Kennst du ihren Namen? Du bist sehr vertraut mit ihm."
  },
  AvgDialog_15365_Content_22 = {
    Text = "Das... ist nichts Seltenes. Davon gibt es einige in Besançon."
  },
  AvgDialog_15365_Content_23 = {
    Text = "Ach so... Ich dachte, es wäre meine ganz eigene, wunderbare Entdeckung."
  },
  AvgDialog_15365_Content_24 = {
    Text = "Auflösung... Was für ein passender Name."
  },
  AvgDialog_15365_Content_25 = {
    Text = "Jetzt ist nicht die Zeit für Scherze, Sanga."
  },
  AvgDialog_15365_Content_26 = {
    Text = "Du wirst sterben. Das ist nichts, womit gewöhnliche Menschen wie wir sich einlassen sollten."
  },
  AvgDialog_15365_Content_27 = {
    Text = "Ich verstehe, ich verstehe wirklich... Schönheit zieht unweigerlich Gefahr an."
  },
  AvgDialog_15365_Content_28 = {
    Text = "Man könnte sagen, dass Gefahr selbst eine Art Schönheit ist, nicht wahr?\nFür mich ist der Tod nichts, wovor man sich fürchten muss."
  },
  AvgDialog_15365_Content_29 = {
    Text = "Was wirklich erschreckend ist..."
  },
  AvgDialog_15365_Content_3 = {
    Text = "Seltsamerweise hat dieser ununterbrochene nächtliche Lebensstil sie energischer gemacht,\nund selbst Herr August ist mit ihrer jüngsten Arbeitseffizienz zufrieden.\n\n<Yellow:Sie fühlt sich so fremd an.>\n\nAn mehreren Nächten wachte ich aus Albträumen auf und fand sie an meinem Bett stehend...\nSie starrte mich mit Augen an, die voller etwas Beängstigendem waren, etwas, das ich nicht begreifen konnte."
  },
  AvgDialog_15365_Content_30 = {
    Text = "Eine sanfte Brise trug Sangas nächste Worte davon. Der Mond lugte durch die sich überlappenden Wolken und warf sein kaltes Licht auf euch beide."
  },
  AvgDialog_15365_Content_31 = {
    Text = "Dann bemerktest du die Narbe an Sangas Hals."
  },
  AvgDialog_15365_Content_32 = {
    Text = "Wie Korallenranken kletterten sie empor und schimmerten in kaltem, graublauem Licht in den Lücken des wandernden Mondscheins."
  },
  AvgDialog_15365_Content_33 = {
    Text = "Fräulein Sanga, seid Ihr etwa schon infiziert...?!"
  },
  AvgDialog_15365_Content_34 = {
    Text = "Auch wenn du weißt, dass es nur ein Traum ist, spürst du für einen Moment einen leichten Stich in deinem Herzen."
  },
  AvgDialog_15365_Content_35 = {
    Text = "Schließlich besitzt du nun alle Erinnerungen und Gefühle der ursprünglichen Besitzerin. Dieses Dienstmädchen vom Lande Besançons hegt tiefe Zuneigung für ihre Herrin."
  },
  AvgDialog_15365_Content_36 = {
    Text = "Liegt es daran, dass Herr August zu viel Druck auf dich ausübt, also"
  },
  AvgDialog_15365_Content_37 = {
    Text = "Shan schüttelte den Kopf"
  },
  AvgDialog_15365_Content_38 = {
    Text = [[
Von Anfang an hatte er nichts mit dieser Sache zu tun.
Komm, ich bringe dich an einen Ort]]
  },
  AvgDialog_15365_Content_39 = {
    Text = "Endlich angekommen - meine geheime Basis"
  },
  AvgDialog_15365_Content_4 = {
    Text = "<Yellow:Ich habe beschlossen, ihr heute Nacht heimlich zu folgen, um zu sehen, was sie wirklich treibt.>\nWünscht mir Glück.\n\nCamille@1\nA.F.2@Jahr 1, September"
  },
  AvgDialog_15365_Content_40 = {
    Text = "Es ist ein verlassenes Lagerhaus am Meer, gefüllt mit seltsam verdrehten Skulpturen"
  },
  AvgDialog_15365_Content_41 = {
    Text = "Korallen, Muscheln, Tentakel und Gebäude und Kreaturen, die mit seltsamen Schnitzereien geschmückt sind... Ihre einzige Gemeinsamkeit ist die enge Verbindung zum Ozean."
  },
  AvgDialog_15365_Content_42 = {
    Text = "Die Textur dieser Skulpturen..."
  },
  AvgDialog_15365_Content_43 = {
    Text = "Weder Marmor noch Granit. Wo hast du das her?"
  },
  AvgDialog_15365_Content_44 = {
    Text = "Shan zwinkerte dir schelmisch zu"
  },
  AvgDialog_15365_Content_45 = {
    Text = "Das ist mein Geheimnis. Eines Tages wirst du es erfahren"
  },
  AvgDialog_15365_Content_46 = {
    Text = "In der Mitte der Holzhütte stand eine unvollendete menschliche Skulptur"
  },
  AvgDialog_15365_Content_47 = {
    Text = "Sein Körper war in groteske Tentakel gehüllt, in unvorstellbare Winkel verzerrt. Die Blutgefäße am Hals traten hervor, wie eine sich windende Schlange."
  },
  AvgDialog_15365_Content_48 = {
    Text = "Schön, nicht wahr? \nSie nennen mich alle „Schlächter“, weil ich meine Modelle immer grausam behandle"
  },
  AvgDialog_15365_Content_49 = {
    Text = "Aber genau deshalb kann ich das Wesentliche unter der Haut erfassen"
  },
  AvgDialog_15365_Content_5 = {
    Text = "Der September in der Cité ist bereits bitter kalt.\nDu gehst still die Straße entlang und versuchst, dich im Schatten zu verbergen."
  },
  AvgDialog_15365_Content_50 = {
    Text = "Und mein Lehrer war immer vorsichtig mit seinen Modellen, deshalb wurde er nur ein zweitklassiger Bildhauer"
  },
  AvgDialog_15365_Content_51 = {
    Text = "Du betrachtest die Statue vor dir. Sie ist schön, aber auch grausam"
  },
  AvgDialog_15365_Content_52 = {
    Text = "Ist das das Werk, das du zur Ausstellung mitnehmen willst?"
  },
  AvgDialog_15365_Content_53 = {
    Text = "Shan schüttelte den Kopf"
  },
  AvgDialog_15365_Content_54 = {
    Text = "Einige Entwürfe nur. Bevor ich auf die... D-Schleim traf, war mein Verständnis von Skulpturen noch sehr oberflächlich"
  },
  AvgDialog_15365_Content_55 = {
    Text = "Ich fühle mich jetzt wie ein neugeborenes Kind, das die Welt neu entdecken muss"
  },
  AvgDialog_15365_Content_56 = {
    Text = "<Yellow:Und dich neu kennenlernen.>"
  },
  AvgDialog_15365_Content_57 = {Text = "Ich...?"},
  AvgDialog_15365_Content_58 = {
    Text = "Ja, du. Ich sehe neue Möglichkeiten in deinen Augen und deinem Auftreten."
  },
  AvgDialog_15365_Content_59 = {
    Text = "Sanga fuhr mit ihren Fingern sanft die Konturen deines Gesichts nach."
  },
  AvgDialog_15365_Content_6 = {
    Text = "Sangas schlanke Gestalt ist direkt vor dir.\nDu hältst einen angemessenen und doch respektvollen Abstand, als wärt ihr auf subtile Weise durch einen unsichtbaren Faden verbunden."
  },
  AvgDialog_15365_Content_60 = {
    Text = "Anders als bei anderen verwöhnten Damen tragen ihre Fingerspitzen eine dünne Schicht Schwielen, die ihnen eine deutlich raue Textur verleihen."
  },
  AvgDialog_15365_Content_61 = {
    Text = "Du hast Angst. Keine Sorge, ich werde dich zu nichts zwingen, was gegen deinen Willen ist."
  },
  AvgDialog_15365_Content_62 = {
    Text = "Erinnerst du dich noch an unsere Kindheit?"
  },
  AvgDialog_15365_Content_63 = {
    Text = "Als ich ein Kind war?"
  },
  AvgDialog_15365_Content_64 = {
    Text = "Du folgst ihren Worten und tauchst tiefer in die chaotischen Gedanken des ursprünglichen Wirtes ein..."
  },
  AvgDialog_15365_Content_65 = {
    Text = "Schließlich verfangen in jenem trüben und verschwommenen Sommer."
  },
  AvgDialog_15365_Content_66 = {
    Text = "Natürlich erinnere ich mich. Mit 5 Jahren konntest du ein menschliches Skelett aus Lehm formen."
  },
  AvgDialog_15365_Content_67 = {
    Text = "Ich ging zum Strand, um verschiedene Materialien für dich zu sammeln, und Herr Paul Claud war dafür zuständig, die Modelle in den Ofen zum Brennen zu werfen."
  },
  AvgDialog_15365_Content_68 = {
    Text = "Ja, das war ein kleines Geheimnis zwischen uns dreien."
  },
  AvgDialog_15365_Content_69 = {
    Text = "Einmal wurdest du von deinem Vater erwischt. Du hast die ganze Schuld allein auf dich genommen und wurdest bestraft, eine ganze Nacht lang zu stehen."
  },
  AvgDialog_15365_Content_7 = {
    Text = "Dieser Faden führt dich durch aufragende Gebäude und langen, düsteren Frost, bis er schließlich zu eurem gemeinsamen Ziel führt—"
  },
  AvgDialog_15365_Content_70 = {
    Text = "Sangas graue Augen waren von einem dünnen, traurigen Schleier bedeckt."
  },
  AvgDialog_15365_Content_71 = {
    Text = "Sie umarmt dich sanft."
  },
  AvgDialog_15365_Content_72 = {
    Text = "Ihr seid für immer meine Familie. Hat Paul dich geschickt, um mich zu finden?"
  },
  AvgDialog_15365_Content_73 = {
    Text = "Ja. Der junge Herr... ist unwohl und konnte nicht persönlich kommen."
  },
  AvgDialog_15365_Content_74 = {
    Text = "Du atmest leicht in Sangas Hals, ihr Duft erfüllt deine Nase.\nEin Hauch von Meeresbrise."
  },
  AvgDialog_15365_Content_75 = {
    Text = "Keine Sorge. Da ich versprochen habe, mit dir nach Hause zu gehen, werde ich mein Wort nicht brechen."
  },
  AvgDialog_15365_Content_76 = {
    Text = "Allerdings muss ich dich jetzt für eine Weile verlassen."
  },
  AvgDialog_15365_Content_77 = {
    Text = "Mich verlassen...? Wohin gehst du?"
  },
  AvgDialog_15365_Content_78 = {
    Text = "Sanga sagte nichts, sondern wandte sich um und blickte auf das graue Meer hinaus."
  },
  AvgDialog_15365_Content_79 = {
    Text = "Es ist eine neblige Nacht, mit sanften Wellen, die rhythmisch plätschern wie der Puls an Sangas Hals."
  },
  AvgDialog_15365_Content_8 = {
    Text = "Ein verlassenes Grab"
  },
  AvgDialog_15365_Content_80 = {
    Text = "Ich weiß es nicht. Vielleicht in die Tiefen des Ozeans, oder vielleicht @1..."
  },
  AvgDialog_15365_Content_81 = {
    Text = "Nach jenem Tag verschwand Fräulein Sanga."
  },
  AvgDialog_15365_Content_82 = {
    Text = "Ich ging überall hin, wo ich konnte, und fragte jeden, den ich konnte, doch fand nichts.\n\nSie verließ uns wie ein Windstoß.\nSelbst jetzt erinnere ich mich immer wieder an jene Nacht am Meer."
  },
  AvgDialog_15365_Content_83 = {
    Text = "Damals hielt Frau Sanga mich fest.\nVielleicht hat sie danach noch etwas gesagt, vielleicht auch nicht; ich weiß es nicht.\n\nMeine Erinnerung ist seit jenem Tag verschwommen.\n\n<Red:Weiße Korallen, Muscheln, ein geheimnisvoller Unterwasserpalast...>\nSelbst jetzt quälen diese chaotischen Bilder nachts meinen Geist."
  },
  AvgDialog_15365_Content_84 = {
    Text = "<Yellow:„Geh zur Salonausstellung, um Antworten zu finden.\">\n\nFräulein Sanga sagte mir dies. Sie sagte auch—"
  },
  AvgDialog_15365_Content_85 = {
    Text = "Sobald du jene Wunder gesehen hast, wirst du mich verstehen."
  },
  AvgDialog_15365_Content_86 = {
    Text = "Einfach meinem Blick folgen..."
  },
  AvgDialog_15365_Content_87 = {
    Text = "Ich verspreche es dir."
  },
  AvgDialog_15365_Content_9 = {
    Text = "Miss Sanga."
  },
  AvgDialog_15367_Content_1 = {
    Text = "Geh weg, fass mich nicht an...!!"
  },
  AvgDialog_15367_Content_10 = {
    Text = "Ich weiß, dass du dir kürzlich ein eigenes <Yellow:Atelier> eingerichtet hast, aber ich denke, ich muss dich daran erinnern."
  },
  AvgDialog_15367_Content_11 = {
    Text = "Erwarte nicht, dass deine <Yellow:blasphemischen und abscheulichen Amateurwerke> die Gunst der Regierungsbeamten gewinnen."
  },
  AvgDialog_15367_Content_12 = {
    Text = "Ich gebe zu, du bist talentiert und hast dem Atelier viel geholfen. Aber an einem Ort wie der Cité erfordert Kunst mehr als nur Talent."
  },
  AvgDialog_15367_Content_13 = {
    Text = "Wenn du mich erzürnst..."
  },
  AvgDialog_15367_Content_14 = {
    Text = "Herr August, bitte achte auf deine Worte."
  },
  AvgDialog_15367_Content_15 = {
    Text = "Es ist schon in Ordnung, Camille."
  },
  AvgDialog_15367_Content_16 = {
    Text = "Sanga hielt dich sanft von hinten fest. Angesichts Augusts Befragung blieb ihr Ausdruck ruhig."
  },
  AvgDialog_15367_Content_17 = {
    Text = "Sie ging in die Hocke, hob die zerbrochenen Teile des Gesichts der Skulptur auf und warf sie auf den nahegelegenen Müllhaufen."
  },
  AvgDialog_15367_Content_18 = {
    Text = "Wenn du mich erzürnst, wird dein Werk weder ausgestellt noch verkauft. Als Künstlerin wirst du niemals Erfolg haben, und am Ende..."
  },
  AvgDialog_15367_Content_19 = {
    Text = "Wirst du entweder auf der Straße erfrieren oder in eine Anstalt eingewiesen."
  },
  AvgDialog_15367_Content_2 = {
    Text = "Mit vereinten Kräften gelang es allen schließlich, den aufgebrachten Bildhauer-Meister zurückzuhalten."
  },
  AvgDialog_15367_Content_20 = {
    Text = "Natürlich weiß ich das alles, Meister."
  },
  AvgDialog_15367_Content_3 = {
    Text = "Sei nicht ungestüm, mein lieber Lehrer."
  },
  AvgDialog_15367_Content_4 = {
    Text = "Ein so mittelmäßiges Werk verdirbt nicht nur meine Stimmung, sondern auch Euren Ruf."
  },
  AvgDialog_15367_Content_5 = {
    Text = "Heh... Sei nicht so vorlaut. In weniger als einem halben Jahr ist die Salon-Ausstellung — kannst du auf magische Weise ein besseres Werk erschaffen?"
  },
  AvgDialog_15367_Content_6 = {Text = "Ein Monat."},
  AvgDialog_15367_Content_7 = {Text = "...Was?"},
  AvgDialog_15367_Content_8 = {
    Text = "Gebt mir einen Monat, und ich werde Euch eine wahrhaftige <Yellow:Überraschung> liefern."
  },
  AvgDialog_15367_Content_9 = {Text = "...Hmph."},
  AvgDialog_15368_Content_1 = {
    Text = "Beim Lesen dieses Briefes fühlt es sich an, als würden wir uns persönlich begegnen."
  },
  AvgDialog_15368_Content_10 = {
    Text = "Deine Schläfen pochen. Du versuchst, deinen Körper zu bewegen, aber—"
  },
  AvgDialog_15368_Content_11 = {Text = "...!"},
  AvgDialog_15368_Content_12 = {
    Text = "<Shake:Meine Beine... sind taub geworden...>"
  },
  AvgDialog_15368_Content_13 = {
    Text = "Hmm, war das nur meine Einbildung? Für einen Moment, als du die Augen geöffnet hast, schien ich einen Glanz zu sehen, den ich noch nie zuvor gesehen habe."
  },
  AvgDialog_15368_Content_14 = {
    Text = "Nein, es ist keine Illusion. Dein Ausdruck hat sich ebenfalls verändert..."
  },
  AvgDialog_15368_Content_15 = {
    Text = "Die Augen einer jungen Bildhauerlehrlingin funkelten vor Aufregung, als sie sich plötzlich zu euch vorbeugte."
  },
  AvgDialog_15368_Content_16 = {
    Text = "Wer bist du?"
  },
  AvgDialog_15368_Content_17 = {
    Text = "Eure Dienerin"
  },
  AvgDialog_15368_Content_18 = {
    Text = "<Shake:I–Ich bin eure Zofe Camille@1, erinnert Ihr Euch nicht? Haha...>"
  },
  AvgDialog_15368_Content_19 = {
    Text = "Erinnert euch an eure Identität."
  },
  AvgDialog_15368_Content_2 = {
    Text = "Werter Herr Claud,\n\nIch bin in Seite angekommen.\nAnders als die Ruhe von Besançon ist es hier voller lärmender Störungen.\nDas Läuten der Glocken, das Rumpeln der Kutschen und der Lärm der Menschenmengen...\nDer Gedanke, dass Fräulein Sanga in einer solchen Umgebung lebt, beunruhigt mich zutiefst."
  },
  AvgDialog_15368_Content_20 = {
    Text = "Diesmal seid ihr eine Zofe, die mit Sanga aufgewachsen ist, und wurdet von Herr Paul geschickt, um sie nach Hause zu bringen."
  },
  AvgDialog_15368_Content_21 = {
    Text = "„Sorge dafür, ihre Seele vor diesem Teufel zu retten, der andere nur ausnutzt und plagiiert.“"
  },
  AvgDialog_15368_Content_23 = {
    Text = "<Gray:Nein, das stimmt nicht...>"
  },
  AvgDialog_15368_Content_24 = {
    Text = "Erinnert euch an eure Identität."
  },
  AvgDialog_15368_Content_25 = {
    Text = "Dieses Mal bist du eine Dienstmagd, die mit Sanga aufgewachsen ist und von Meister @1·Claudel geschickt wurde, um sie nach Hause zu bringen."
  },
  AvgDialog_15368_Content_26 = {
    Text = "„Rette unbedingt ihre Seele vor diesem Teufel, der seine Untergebenen nur ausnutzt und plagiiert.“"
  },
  AvgDialog_15368_Content_27 = {
    Text = "I-Ich bin Eure Zofe, Camille@1. Erinnert Ihr Euch nicht? Haha..."
  },
  AvgDialog_15368_Content_28 = {
    Text = "<Shake:So viele Jahre sind vergangen, wir haben uns beide verändert, nicht wahr?>"
  },
  AvgDialog_15368_Content_29 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_15368_Content_3 = {
    Text = "Gerüchte haben sich verbreitet. \nDie Leute sagen, Fräulein Sanga verbringe ihre gesamte Zeit mit einem Mann, der über 20 Jahre älter ist als sie, „der Kunst wegen“. \nDas ist absurd. Morgen werde ich das Atelier besuchen, um der Sache auf den Grund zu gehen. \n\nDiesmal werde ich Euren Wunsch erfüllen—\n<Yellow:Eure Schwester, unsere Fräulein Sanga, zurück nach Besançon zu bringen.>\n\nCamille@1\nA. F. 2@1 Jahr 8"
  },
  AvgDialog_15368_Content_30 = {
    Text = "Du bist jetzt definitiv anders, viel lebendiger als früher.\nEs ist, als ob... du plötzlich zum Leben erwacht wärst."
  },
  AvgDialog_15368_Content_31 = {
    Text = "<Gray:Ist das die Intuition einer Künstlerin? Ich muss von nun an vorsichtiger sein.>"
  },
  AvgDialog_15368_Content_32 = {
    Text = "<Shake:Wenn es dir nichts ausmacht, könntest du mir helfen? Ich kann gerade nicht aufstehen...>"
  },
  AvgDialog_15368_Content_33 = {
    Text = "Sanga hält sanft deine Hand, ein Hauch von Sorge blitzt in ihren ruhigen Augen auf."
  },
  AvgDialog_15368_Content_34 = {
    Text = "Verzeih, ich war vorhin zu sehr in mein Schaffen vertieft. Du musst dich jetzt unwohl fühlen. Lass mich nachsehen."
  },
  AvgDialog_15368_Content_35 = {Text = "Whoa—!!"},
  AvgDialog_15368_Content_36 = {
    Text = "Die Ateliertür wurde mit einem Ruck aufgerissen."
  },
  AvgDialog_15368_Content_37 = {
    Text = "Ein großer, grüblerischer Mann trat ein, gefolgt von mehreren unbekannten Gesichtern."
  },
  AvgDialog_15368_Content_38 = {
    Text = "Ohne auf die Erinnerungen der ursprünglichen Wirtin zugreifen zu müssen, erkanntest du den Mann an seinem markanten Bart—"
  },
  AvgDialog_15368_Content_39 = {
    Text = "Der berühmte Bildhauer <Blue:August>."
  },
  AvgDialog_15368_Content_4 = {
    Text = "Fräulein Sanga, kommt mit mir zurück. Hier gibt es keine Möglichkeit, sich aufzuwärmen—"
  },
  AvgDialog_15368_Content_40 = {
    Text = "Noch heute werden seine Skulpturen als Meisterwerke gefeiert und sind bei den Auktionen in Lentiniën heiß begehrt."
  },
  AvgDialog_15368_Content_41 = {
    Text = "Als er sah, wie du und Sanga Händchen hieltet, runzelte August die Stirn. Doch bald wurde seine Aufmerksamkeit von der Skulptur vor ihm gefesselt."
  },
  AvgDialog_15368_Content_42 = {
    Text = "Das ist... <Big:Ein Meisterwerk, ohne jeden Zweifel!>"
  },
  AvgDialog_15368_Content_43 = {
    Text = "Die anderen versammelten sich darum, betrachteten neugierig die frisch geschaffene Skulptur und riefen voller Bewunderung aus."
  },
  AvgDialog_15368_Content_44 = {
    Text = "Gut, sehr gut... Kontaktiert jemanden vom Kulturministerium und teilt ihnen mit, dass wir bei den Exponaten für die diesjährige Seite-Ausstellung Fortschritte gemacht haben."
  },
  AvgDialog_15368_Content_45 = {
    Text = "Ich kann es kaum erwarten zu sehen, wie diesen Kritikern die Kinnlade herunterfällt... Hahaha!"
  },
  AvgDialog_15368_Content_46 = {
    Text = "Augusts herzhaftes Lachen hallt durch das leere Atelier. Er schiebt dich beiseite und ergreift Sangas Hand fest."
  },
  AvgDialog_15368_Content_47 = {
    Text = "Ich wusste, dass du mich nicht enttäuschen würdest, Shan"
  },
  AvgDialog_15368_Content_48 = {
    Text = "Shan zog ihre Hand langsam zurück und ging langsam zur Statue"
  },
  AvgDialog_15368_Content_49 = {
    Text = "Unbestrittenes... Meisterwerk?"
  },
  AvgDialog_15368_Content_5 = {
    Text = [[
Nicht bewegen, und nicht sprechen. Einfach so bleiben.
Ja, genau so...]]
  },
  AvgDialog_15368_Content_50 = {
    Text = "Was denkst du, Camille?"
  },
  AvgDialog_15368_Content_51 = {
    Text = "Äh, ich...?"
  },
  AvgDialog_15368_Content_52 = {
    Text = "Du betrachtest die Statue, die dir fast identisch ist, und verfällst in Gedanken"
  },
  AvgDialog_15368_Content_53 = {Text = "Allgemein"},
  AvgDialog_15368_Content_54 = {
    Text = "Hmm, steife Haltung, chaotische Struktur, mangelnde Spannung"
  },
  AvgDialog_15368_Content_55 = {
    Text = "Du kommentierst ernsthaft. Tatsächlich hast du keine Ahnung von Kunst, aber du sagst es nur, weil du Augusts rüpelhaftes Verhalten nicht magst"
  },
  AvgDialog_15368_Content_56 = {
    Text = "Du magst ihn nicht."
  },
  AvgDialog_15368_Content_57 = {
    Text = "Shan lächelte dich an, wie eine liebevolle Mutter, die auf das Geschwätz eines Kindes hört"
  },
  AvgDialog_15368_Content_58 = {
    Text = "Hm...obwohl die Gründe unterschiedlich sind, sind wir uns einig"
  },
  AvgDialog_15368_Content_59 = {
    Text = "Meisterwerk!"
  },
  AvgDialog_15368_Content_6 = {
    Text = "Sei ein braves Modell für mich und lass mich dieses Stück fertigstellen... Dann können wir darüber reden, nach Hause zu gehen."
  },
  AvgDialog_15368_Content_60 = {
    Text = "Wirklich unvergleichlich, ich kann keine Mängel finden"
  },
  AvgDialog_15368_Content_61 = {
    Text = "Wie alle anderen bist auch du von dieser scheinbar lässigen, aber tatsächlich präzisen Skulptur völlig fasziniert"
  },
  AvgDialog_15368_Content_62 = {
    Text = "Natürlich, das liegt auch an der schlechten Durchblutung durch die lange gleiche Haltung"
  },
  AvgDialog_15368_Content_63 = {
    Text = "Ein sauerstoffarmes Gehirn sieht die Dinge nicht klar, aber Komplimente schaden nie"
  },
  AvgDialog_15368_Content_64 = {
    Text = "Du hast recht. Keine Fehler zu finden, das ist das größte Problem"
  },
  AvgDialog_15368_Content_65 = {
    Text = "Jetzt... Was soll ich mit dir machen?"
  },
  AvgDialog_15368_Content_66 = {
    Text = "Shan stützte ihr Kinn und blickte auf die Statue. Dann streckte sie ihren Zeigefinger aus und tippte beiläufig auf die Stirn der Statue—"
  },
  AvgDialog_15368_Content_67 = {Text = "Krach—!!"},
  AvgDialog_15368_Content_68 = {
    Text = "Die Skulptur beschrieb einen eleganten Bogen und schlug dann mit einem lauten Knall auf dem Boden auf."
  },
  AvgDialog_15368_Content_69 = {
    Text = "Camille — oder vielmehr dein besorgtes Gesicht zerspringt in unzählige Stücke."
  },
  AvgDialog_15368_Content_7 = {
    Text = "Was ist das...?"
  },
  AvgDialog_15368_Content_70 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_15368_Content_71 = {
    Text = "Fräulein Claudel, sind Sie wahnsinnig geworden?!"
  },
  AvgDialog_15368_Content_72 = {
    Text = "August stürzte sich wütend auf dich."
  },
  AvgDialog_15368_Content_73 = {
    Text = "<Big:Das ist der reinste Petachi-Marmor, direkt aus Palos—>"
  },
  AvgDialog_15368_Content_8 = {
    Text = "Ein unordentliches Haus."
  },
  AvgDialog_15368_Content_9 = {
    Text = "Skulpturen aus verschiedenen Tonarten, Marmor und Granit stehen achtlos herum und verwandeln diesen Raum in eine einfache Bildhauerwerkstatt."
  },
  AvgDialog_15370_Content_1 = {
    Text = "Goldener Kopf"
  },
  AvgDialog_15370_Content_10 = {
    Text = "Der Regen wird stärker, und deine Kehle wird trockener.\nIn einem solchen Sturm musst du schreien, um deine eigene Stimme zu hören."
  },
  AvgDialog_15370_Content_11 = {
    Text = "Hier... Ich bin hier..."
  },
  AvgDialog_15370_Content_12 = {
    Text = "@1 Hehe, hier, hier @2 hier, hier, hier..."
  },
  AvgDialog_15370_Content_13 = {
    Text = "Unzählige Stimmen bestürmen dich aus allen Richtungen. Du kannst dich nicht mehr halten und brichst schließlich auf dem Strand in die Knie."
  },
  AvgDialog_15370_Content_14 = {
    Text = "Vielleicht ist alles nur dein Trugbild... Vielleicht ist Fräulein Sanga für immer gegangen."
  },
  AvgDialog_15370_Content_15 = {
    Text = "<Shake:Fräulein Sanga, komm heraus... Ich weiß, dass du hier bist...>"
  },
  AvgDialog_15370_Content_16 = {
    Text = "Ohne es zu bemerken, hat das Bewusstsein der Dienerin dich allmählich verschlungen. Ihre Hoffnungen und ihr Leid haben dein Herz zutiefst bewegt."
  },
  AvgDialog_15370_Content_17 = {
    Text = "Du presst deine Stirn gegen den feuchten Sand, ein seltsames Wimmern entweicht deiner Kehle."
  },
  AvgDialog_15370_Content_18 = {
    Text = "<Shake:Dame Sanga...>"
  },
  AvgDialog_15370_Content_19 = {
    Text = "<Red:Ich bin hier... Ich bin genau hier...>"
  },
  AvgDialog_15370_Content_2 = {
    Text = "Lieber Herr Claud,\n\n„Frau Corals Tod\" war ein überwältigender Erfolg in der Cité, und alle sprechen darüber.\nWenn ich diese Skulptur betrachte, muss ich unweigerlich an Sie denken.\n\nSie ist aus einem matten, weißen Material gefertigt, ähnlich den Steinen, die Sie bedecken und Sie bewegungsunfähig machen.\nAber sie lassen mich die Skulptur nicht berühren@1\nIch werde einen Weg finden."
  },
  AvgDialog_15370_Content_20 = {
    Text = "...Was ist das?"
  },
  AvgDialog_15370_Content_21 = {
    Text = "Ein kaltes Gefühl berührt meine Fingerspitzen."
  },
  AvgDialog_15370_Content_22 = {
    Text = "Der weiße Dunst breitet sich erneut von meinen Fingerspitzen aus, wie lebendige Ranken..."
  },
  AvgDialog_15370_Content_23 = {
    Text = "Langsam und stetig..."
  },
  AvgDialog_15370_Content_24 = {
    Text = "Endlich... der Moment ist gekommen."
  },
  AvgDialog_15370_Content_25 = {
    Text = "Ein zartes Paar Damenschuhe kam vor dir zum Stehen.\nSanga hielt einen Meißel in der Hand, ihr Ausdruck so ruhig und distanziert wie eh und je."
  },
  AvgDialog_15370_Content_26 = {
    Text = "Fräulein Sanga... Ihr seid tatsächlich noch am Leben..."
  },
  AvgDialog_15370_Content_27 = {
    Text = "Das kommt darauf an, wie du „am Leben sein“ definierst."
  },
  AvgDialog_15370_Content_28 = {
    Text = "Das sanfte Glühen von entfernten Lichtern umhüllt zart den Körper von Sanga. Sie lächelt leise zu dir."
  },
  AvgDialog_15370_Content_29 = {
    Text = "Ich bin zurück, Camille. Du musst lange auf mich gewartet haben, nicht wahr?"
  },
  AvgDialog_15370_Content_3 = {
    Text = "Fräulein Sanga hat sich endlich ihren Wunsch erfüllt. Sie tauschte ihr Leben gegen unsterbliche Kunst.\nAber sie hat uns auch für immer verlassen.\nEs ist fast ein Monat seit dem Ende der Ausstellung vergangen, und ich vermisse sie noch immer zutiefst.\n\n<Yellow:Ich werde sie finden und sie nach Hause bringen.>\n\nCamille@1\nA.F.2@Jahr 8 Monat"
  },
  AvgDialog_15370_Content_30 = {
    Text = "Pain, Schock, Ekstase..."
  },
  AvgDialog_15370_Content_31 = {
    Text = "Deine Brust ist erfüllt von unzähligen Emotionen. Du öffnest den Mund, doch es gelingt dir nicht, auch nur eine einzige vollständige Silbe hervorzubringen."
  },
  AvgDialog_15370_Content_32 = {
    Text = "Sanga@1...nicht@2..."
  },
  AvgDialog_15370_Content_33 = {Text = "Pssst..."},
  AvgDialog_15370_Content_34 = {
    Text = "Wusstest du das? Der menschliche Körper ist wie eine zitternde, pulsierende Welt."
  },
  AvgDialog_15370_Content_35 = {
    Text = "Wenn Körper und Seele ausreichend gehärtet wurden, verwandeln sie sich auf dem Höhepunkt des emotionalen Ausbruchs in die perfekte Skulptur..."
  },
  AvgDialog_15370_Content_36 = {
    Text = "Kalte Finger streichen über dein allmählich erstarrendes Gesicht."
  },
  AvgDialog_15370_Content_37 = {
    Text = "Sanga sah dich mit Liebe an, ihr Blick brannte dich beinahe auf."
  },
  AvgDialog_15370_Content_38 = {
    Text = "Einfach so wie du jetzt bist..."
  },
  AvgDialog_15370_Content_39 = {
    Text = "Bin ich jetzt so...? Fräulein Sanga, ist es der D–Schleim...?"
  },
  AvgDialog_15370_Content_4 = {
    Text = "Du taumelst ans Ufer. Niemand ist hier, nur das trübe, stille Meer und der verschwommene Horizont leisten dir Gesellschaft."
  },
  AvgDialog_15370_Content_40 = {
    Text = "Schh... Ruhe."
  },
  AvgDialog_15370_Content_41 = {
    Text = "Für mich war der Tod nie etwas, das man fürchten muss. Was mich wirklich erschreckt, ist..."
  },
  AvgDialog_15370_Content_42 = {
    Text = "<Yellow:Schönheit verlieren oder ein blinder Blick darauf.>"
  },
  AvgDialog_15370_Content_43 = {
    Text = "<Shake:Lass... mich... in Ruhe...>"
  },
  AvgDialog_15370_Content_44 = {
    Text = "Sag keine törichten Dinge, Camille."
  },
  AvgDialog_15370_Content_45 = {
    Text = "<Red:Du warst bereits tot, erinnerst du dich?>"
  },
  AvgDialog_15370_Content_46 = {
    Text = "<Red:Tot...>"
  },
  AvgDialog_15370_Content_47 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_15370_Content_48 = {
    Text = "Du tauchst erneut in die Tiefen des endlosen Ozeans ein."
  },
  AvgDialog_15370_Content_49 = {
    Text = "Jene in der Erinnerung versiegelten Fragmente treiben wie weißer Schaum umher, tauchen unablässig auf und zerbersten..."
  },
  AvgDialog_15370_Content_5 = {
    Text = "Ihr seid alle meine ewige Familie."
  },
  AvgDialog_15370_Content_50 = {
    Text = "Im letzten Moment vor dem Tod musst du dich jenen grausamen Wahrheiten stellen—"
  },
  AvgDialog_15370_Content_51 = {
    Text = "Es ist alles meine Schuld, Camille. Es ist alles meine Schuld... Lass mich dich halten, damit die Wunde nicht wehtut."
  },
  AvgDialog_15370_Content_52 = {
    Text = "Meine Schwester ist ein wahres Genie. Sie wird zweifellos eine große Künstlerin, die in Büchern verewigt wird!"
  },
  AvgDialog_15370_Content_53 = {
    Text = "Ähm... Hör auf, dir etwas vorzumachen, Camille..."
  },
  AvgDialog_15370_Content_54 = {
    Text = "Bringt sie zu mir zurück@2. Es gibt noch etwas, das ich sie persönlich fragen möchte..."
  },
  AvgDialog_15370_Content_55 = {
    Text = "Extrablatt, Extrablatt!!"
  },
  AvgDialog_15370_Content_56 = {
    Text = "Der welterschütternde <Yellow:Skulpturen–Mordfall> hat ein weiteres Opfer gefordert!"
  },
  AvgDialog_15370_Content_57 = {
    Text = "Bis heute gab es 54 Fälle von <Yellow:Schwindelanfällen und Hysterie>, die durch den Besuch von „Frau Corals Tod\" verursacht wurden..."
  },
  AvgDialog_15370_Content_58 = {
    Text = "<Red:Von diesen haben bereits 23 Personen Selbstmord begangen...>"
  },
  AvgDialog_15370_Content_59 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_15370_Content_6 = {
    Text = "Keine Sorge. Da ich versprochen habe, mit dir nach Hause zu gehen, werde ich mein Wort nicht brechen."
  },
  AvgDialog_15370_Content_60 = {
    Text = "Also habe ich... alles gewusst..."
  },
  AvgDialog_15370_Content_61 = {
    Text = "Du siehst den weißen Ozeanpalast noch einmal. Plankton sammelt sich auf dem weißen Kalziumkarbonat und streckt träge seine Gliedmaßen aus."
  },
  AvgDialog_15370_Content_62 = {
    Text = "Du sahst auch jene weißen Skulpturen, die ziellos im Meerwasser trieben."
  },
  AvgDialog_15370_Content_63 = {
    Text = "Einige vertraute Gesichter sind darunter, wie Herr Auguste, der noch immer die Wut und Verzweiflung zeigt, mit der er sich auf die Skulptur gestürzt hat."
  },
  AvgDialog_15370_Content_64 = {
    Text = "Zum Beispiel Herr Paul, dessen eingefallene Augenhöhlen voller Melancholie waren, als hätte er sein Schicksal schon lange vorhergesehen."
  },
  AvgDialog_15370_Content_65 = {
    Text = "Das warme Meerwasser umhüllt deinen Körper, sein wellender Rhythmus wie eine fließende Ballade."
  },
  AvgDialog_15370_Content_66 = {
    Text = "Bevor es die Augen öffnet, wedelt das Baby mit seinen winzigen Händen,\nHält Ton in den Händen und empfindet eine Freude, die der Mutterliebe gleicht.\nDie Kunst des Erschaffens und Beherrschens breitet sich durch seine Finger aus.\n\n<Red:Öffne deine Augen und erblicke alles, was aus Schönheit geboren wurde...>"
  },
  AvgDialog_15370_Content_67 = {
    Text = "Kalte Hände umarmen dich sanft. Sanga vergräbt ihre weiche Wange in deiner steifen Schulter."
  },
  AvgDialog_15370_Content_68 = {
    Text = "Kannst du sie hören? Diese Lieder hallen unaufhörlich in meinem Kopf wider."
  },
  AvgDialog_15370_Content_69 = {
    Text = "Es ist der Ruf von <Yellow:Ihnen>, ein Schicksal, dem ich niemals entkommen kann..."
  },
  AvgDialog_15370_Content_7 = {
    Text = "Sie wird ihr Versprechen nicht brechen... Das wird sie nicht."
  },
  AvgDialog_15370_Content_70 = {
    Text = "Ich folgte den Liedern und kam schließlich hier an."
  },
  AvgDialog_15370_Content_71 = {
    Text = "Wunder und Schönheit aus den Tiefen des Ozeans... Ich habe Ihm nichts zu bieten außer dir."
  },
  AvgDialog_15370_Content_72 = {Text = "Ich...?"},
  AvgDialog_15370_Content_73 = {
    Text = "Ja, nur du — %player%."
  },
  AvgDialog_15370_Content_74 = {
    Text = "Sie sprach klar und unmissverständlich deinen wahren Namen aus."
  },
  AvgDialog_15370_Content_75 = {
    Text = "Von dem Moment an, als du deine Augen geöffnet hast, wusste ich es."
  },
  AvgDialog_15370_Content_76 = {
    Text = "<Yellow:Du bist der wahre „Frau Corals Tod.\">"
  },
  AvgDialog_15370_Content_77 = {
    Text = "Das Bewusstsein verschwamm allmählich, und weiße Korallen hatten sich bereits über den ganzen Körper ausgebreitet."
  },
  AvgDialog_15370_Content_78 = {
    Text = "Du spürst, wie dein Blut und Fleisch schwerer werden, doch seltsamerweise steigen eure Körper inmitten von Schaum und Korallen immer weiter auf."
  },
  AvgDialog_15370_Content_79 = {
    Text = "<Shake:Nein... nach Hause... nach Hause gehen...>"
  },
  AvgDialog_15370_Content_8 = {
    Text = "Du raffst deinen Rock und rennst ohne Halt die lange Küstenlinie entlang."
  },
  AvgDialog_15370_Content_80 = {
    Text = "Dies ist dein Zuhause, %player%."
  },
  AvgDialog_15370_Content_81 = {Text = "Nein..."},
  AvgDialog_15370_Content_82 = {
    Text = "Du starrst unverwandt in Sangas Gesicht, bis deine Pupillen von grauweißer Koralle bedeckt werden."
  },
  AvgDialog_15370_Content_83 = {
    Text = "Du versinkst in einer grenzenlosen Leere."
  },
  AvgDialog_15370_Content_84 = {
    Text = "Alle Ozeane, Korallen und Skulpturen verblassen; nur ihre Stimme bleibt."
  },
  AvgDialog_15370_Content_85 = {
    Text = "Wie immer eine sanfte, doch gleichgültige Stimme."
  },
  AvgDialog_15370_Content_86 = {
    Text = "Ich habe dir versprochen, dass ich dich nach Hause bringe..."
  },
  AvgDialog_15370_Content_87 = {
    Text = "Ich habe dir versprochen."
  },
  AvgDialog_15370_Content_9 = {
    Text = "Fräulein Sanga — Fräulein Sanga —"
  },
  AvgDialog_15605_Content_1 = {
    Text = "Test starte"
  },
  AvgDialog_15605_Content_10 = {
    Text = "Bist du erneut in die Vergangenheit des Erweckten Körpers eingetreten? Du erinnerst dich, ein Dokument gelesen zu haben..."
  },
  AvgDialog_15605_Content_11 = {
    Text = "Warum kommt keine Reaktion? Ist das Hörmodul defekt?"
  },
  AvgDialog_15605_Content_12 = {
    Text = "Das kommt darauf an. Hast du heimlich am Modul herumgebastelt, nachdem ich gestern gegangen bin?"
  },
  AvgDialog_15605_Content_13 = {
    Text = "Nein, nein, wirklich, diesmal nicht, ich schwöre!\nSoll ich es nochmal versuchen? Leute von TikTok, könnt ihr mich hören?"
  },
  AvgDialog_15605_Content_14 = {Text = "Ja."},
  AvgDialog_15605_Content_15 = {
    Text = "Schau, schau! Sein Mund bewegt sich. Ich hab doch gesagt, es ist alles in Ordnung!"
  },
  AvgDialog_15605_Content_16 = {
    Text = [[
Die weltweit erste vollautomatische mechanische Puppe, die Sprachbefehlen folgt! Die erste! Vollautomatisch!
Lieber Vater, nimm mich jetzt zu dir, denn ich habe keine Reue in meinem Leben!]]
  },
  AvgDialog_15605_Content_17 = {
    Text = "Ich habe allerdings viele Dinge zu bereuen, wie den unvollständigen Befehlsreaktionstest, Mobilitätstest, Betriebsdauertest..."
  },
  AvgDialog_15605_Content_18 = {
    Text = "Mei—Yi—du bist wirklich überhaupt nicht unterhaltsam."
  },
  AvgDialog_15605_Content_19 = {
    Text = "...Gesamtkoordinationstest, Gleichgewichtstest, Belastungstest..."
  },
  AvgDialog_15605_Content_2 = {
    Text = "Zahnradeingriff: gut; Hydrauliksystem: kein Druckverlust; Motor MF311000: läuft normal, Temperatur hoch, aber im Rahmen."
  },
  AvgDialog_15605_Content_20 = {
    Text = "Schon gut, ich hab's verstanden! <Small:Du bist mechanischer als ein Tik-Tokianer.>"
  },
  AvgDialog_15605_Content_21 = {
    Text = "Was hast du gesagt?"
  },
  AvgDialog_15605_Content_22 = {
    Text = "Ah—als Nächstes führen wir einen grundlegenden Befehlsempfangs– und Verständnistest durch!\nDida Mann, Blitz."
  },
  AvgDialog_15605_Content_23 = {Text = "Blinzeln"},
  AvgDialog_15605_Content_24 = {
    Text = [[
Folge meinem Finger, sehr gut.
Mund auf? Sehr gut, du bist mein braves Kind.]]
  },
  AvgDialog_15605_Content_25 = {Text = "...Ugh."},
  AvgDialog_15605_Content_26 = {
    Text = "Was! Ich habe dich Stück für Stück erschaffen, also ist es nur vernünftig, mich Mama zu nennen."
  },
  AvgDialog_15605_Content_27 = {
    Text = "Ja, ja, Zahnrad-Freak-Mama, bring den linken Arm deines lieben Stahlbabys. Es ist Zeit für den Gliedmaßentest."
  },
  AvgDialog_15605_Content_28 = {
    Text = "Ein Arm aus komplexen Zahnrädern und unbegreiflichen mechanischen Strukturen erscheint kurz in deinem Blickfeld, verschwindet dann nach links, gefolgt von rechts."
  },
  AvgDialog_15605_Content_29 = {
    Text = "Die Installation der Gliedmaßen verlief gut. Den Anweisungen folgend hebst du Arme und Beine, und Ericas Lächeln wird immer breiter."
  },
  AvgDialog_15605_Content_3 = {
    Text = "Spezialenergie S, Status stabil."
  },
  AvgDialog_15605_Content_30 = {
    Text = "In Ordnung, als Nächstes—Ah!"
  },
  AvgDialog_15605_Content_31 = {
    Text = "Dichter schwarzer Rauch steigt unterhalb deiner Sichtlinie auf: Etwas brennt.\nDu schaust nach unten und siehst Funken und Elektrizität, die aus deinem Unterleib flackern."
  },
  AvgDialog_15605_Content_32 = {
    Text = "Feuerlöscher, Mei, Mei!"
  },
  AvgDialog_15605_Content_33 = {
    Text = "Aus dem Weg!"
  },
  AvgDialog_15605_Content_34 = {
    Text = "Der Feuerlöscher sprühte weißen Schaum und vertrieb den Brandgeruch mit dem Luftstrom.\nErica kam näher, ignorierte die Hitze des Motors und nahm ihn auseinander."
  },
  AvgDialog_15605_Content_35 = {Text = "Erica!"},
  AvgDialog_15605_Content_36 = {
    Text = "Der verkohlte Motor lag auf der Werkbank. Erica holte tief Luft und pustete verspätet auf ihre schaumbedeckte Hand."
  },
  AvgDialog_15605_Content_37 = {
    Text = "Es versengt mich, es versengt mich."
  },
  AvgDialog_15605_Content_38 = {
    Text = "Energie S, schau dir Energie S an!"
  },
  AvgDialog_15605_Content_39 = {
    Text = "Erica beugte sich nah an den Motor, ihre leicht geröteten Finger strichen sanft über sein Metallgehäuse."
  },
  AvgDialog_15605_Content_4 = {
    Text = "Puh — bist du bereit?\nAutomat Tik-Tok, Test #13, Beginn."
  },
  AvgDialog_15605_Content_40 = {
    Text = "Sieht aus, als hätte ein externer Stromkreis einen Kurzschluss verursacht und Feuer gefangen, aber das Innere sollte unbeschädigt geblieben sein."
  },
  AvgDialog_15605_Content_41 = {
    Text = "Keine Sorge, ich überprüfe es gleich."
  },
  AvgDialog_15605_Content_42 = {
    Text = "...Jagst du mich schon wieder weg?"
  },
  AvgDialog_15605_Content_43 = {Text = "Mei..."},
  AvgDialog_15605_Content_44 = {
    Text = "Es war falsch von mir, ohne Erlaubnis mit Energie S zu experimentieren, aber du kennst unsere Finanzlage. S als Durchbruch zu nutzen, kann uns mehr Zeit und Material verschaffen."
  },
  AvgDialog_15605_Content_45 = {
    Text = "Lass mich es sehen, nur einmal. Ich schwöre, ich werde keine Informationen darüber preisgeben.\nBitte."
  },
  AvgDialog_15605_Content_46 = {
    Text = "Ich habe dir gesagt, da ist nichts drin."
  },
  AvgDialog_15605_Content_47 = {
    Text = "...Du kannst dir nicht mal die Mühe machen, eine Ausrede zu erfinden. Musst du wirklich so misstrauisch mir gegenüber sein?\nHabe ich nicht immer an unsere Zukunft gedacht?"
  },
  AvgDialog_15605_Content_48 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_15605_Content_49 = {
    Text = [[
Vergiss es.
Ich setze mich eine Weile in Joeys Diner. Mach, was du willst.]]
  },
  AvgDialog_15605_Content_5 = {
    Text = "Öffne deine Augen"
  },
  AvgDialog_15605_Content_50 = {
    Text = "Die Tür schloss sich, die Schritte verklangen, und Erica seufzte."
  },
  AvgDialog_15605_Content_51 = {
    Text = [[
Sie ist immer noch... Aber diese Person hat mich vor Energie S gewarnt...
Ich kann nicht zulassen, dass Mei das Risiko mit mir eingeht.]]
  },
  AvgDialog_15605_Content_52 = {
    Text = "Sie wandte sich wieder dem Motor zu, scheinbar mit neuem Elan."
  },
  AvgDialog_15605_Content_53 = {
    Text = "Ich werde es herausfinden. Warte auf mich, Mei."
  },
  AvgDialog_15605_Content_54 = {
    Text = "Sie schraubte die Kappe ab und zog einen schwarzen Zylinder heraus."
  },
  AvgDialog_15605_Content_55 = {
    Text = "In diesem Augenblick wurde deine Welt in Dunkelheit getaucht."
  },
  AvgDialog_15605_Content_6 = {
    Text = "Tick-Tack-Person, kannst du mich hören?"
  },
  AvgDialog_15605_Content_7 = {Text = "...Erica?"},
  AvgDialog_15605_Content_8 = {
    Text = "Ein vertrautes Gesicht zeigt einen natürlichen Ausdruck, der sich völlig von dem unterscheidet, woran du dich erinnerst. Verglichen mit einem Automaten wirkt sie eher wie ein lebendiger Mensch."
  },
  AvgDialog_15605_Content_9 = {
    Text = "...Was passiert hier?"
  },
  AvgDialog_15606_Content_1 = {
    Text = "So sprach die Stimme"
  },
  AvgDialog_15606_Content_10 = {
    Text = "Murmelte sie, als sie ging, und ließ dich mit dem Motor und den Teilen auf der Werkbank zurück."
  },
  AvgDialog_15606_Content_11 = {
    Text = "Du betrachtest deine Hand."
  },
  AvgDialog_15606_Content_12 = {
    Text = "Schlanke, starke und fein gearbeitete Porzellanhülle, sorgfältig poliert und gepflegt. Trotz ihrer Kälte wirkt sie im schwachen Licht lebensecht."
  },
  AvgDialog_15606_Content_13 = {
    Text = "Dies ist Ericas Hand, die Hand der <Blue:Automaton Erica>, die du kennst.\nDu scheinst ihren späteren Körper zu bewohnen und bist zu dem Automaton geworden, den sie erschuf."
  },
  AvgDialog_15606_Content_14 = {
    Text = "Die Person, die du gerade gesehen hast, war eindeutig ein Mensch.\nWelche Art von Erfahrung könnte sie in das verwandelt haben, was sie geworden ist?"
  },
  AvgDialog_15606_Content_15 = {Text = "Erica?"},
  AvgDialog_15606_Content_16 = {
    Text = "Du blinzelst, und Mei ist irgendwie hereingekommen.\nIhr Blick schweift durch den Raum und bleibt schließlich an dem Motor neben dir hängen."
  },
  AvgDialog_15606_Content_17 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_15606_Content_18 = {
    Text = "Nachdem sie den Raum ein zweites Mal gemustert hatte, schloss sie die Tür und eilte zum Generator."
  },
  AvgDialog_15606_Content_19 = {
    Text = "Tut mir leid, Erica."
  },
  AvgDialog_15606_Content_2 = {
    Text = "Tick-Tack, mein Schatz, kannst du mich hören?"
  },
  AvgDialog_15606_Content_20 = {
    Text = "Der Deckel drehte sich auf, und Mei griff nach dem Gegenstand darin. Diesmal sahst du es deutlich: ein Metallzylinder von nicht mehr als 5 cm Durchmesser, mit dem Buchstaben „S“ an der Seite eingraviert."
  },
  AvgDialog_15606_Content_21 = {
    Text = "Sobald sie den Zylinder vollständig herauszieht, wirst du wieder das Bewusstsein verlieren.\nAlso musst du vorher—"
  },
  AvgDialog_15606_Content_22 = {
    Text = "Ihre Hand ergreifen"
  },
  AvgDialog_15606_Content_23 = {Text = "Autsch!!"},
  AvgDialog_15606_Content_24 = {
    Text = "Was ist los—"
  },
  AvgDialog_15606_Content_25 = {
    Text = "Erica stürmte in den Raum, ihre Besorgnis erstarrte in dem Moment, als sie den Zylinder in Meis Hand sah."
  },
  AvgDialog_15606_Content_26 = {
    Text = "Mei, was machst du?"
  },
  AvgDialog_15606_Content_27 = {
    Text = "Was machst du!"
  },
  AvgDialog_15606_Content_28 = {
    Text = "Ich versuche nur... diese Energie... sie funktioniert wirklich..."
  },
  AvgDialog_15606_Content_29 = {
    Text = "Angesichts des kleinen Zylinders, der den gesamten Motor und alle angeschlossenen Geräte mit Strom versorgte, weiteten sich Meis Augen."
  },
  AvgDialog_15606_Content_3 = {
    Text = "Aus der ewigen Dunkelheit erwachend, findest du dich noch immer in der Werkstatt wieder. Der verkohlte Motor liegt noch auf der Werkbank, durch mehrere Kabel unterschiedlicher Stärke mit deinem Körper verbunden."
  },
  AvgDialog_15606_Content_30 = {
    Text = "Weißt du, was das bedeutet, Erica?"
  },
  AvgDialog_15606_Content_31 = {
    Text = "Das bedeutet, dass es gefährlich ist, Mei. Ich habe dir gesagt, du sollst nicht damit herumspielen—"
  },
  AvgDialog_15606_Content_32 = {
    Text = "Nein, nein, hör zu, Erica—dieses Ding, dieses winzige Ding, kann über lange Zeit Energie liefern, ohne Verlust, ohne Emissionen. Verstehst du das nicht?"
  },
  AvgDialog_15606_Content_33 = {
    Text = "Kohle und Öl sind nichts im Vergleich. Wenn wir es in Massenproduktion herstellen können, werden wir die Energiestruktur der Menschheit umschreiben und Geschichte schreiben!"
  },
  AvgDialog_15606_Content_34 = {
    Text = "Du musst mir sagen, wie du das geschafft hast, du musst!"
  },
  AvgDialog_15606_Content_35 = {
    Text = "Erica, wo gehst du hin? Was soll das heißen, du weißt nicht, wie es geht, Erica!"
  },
  AvgDialog_15606_Content_36 = {
    Text = "Der Investor hat gesagt, sobald er das Muster sieht, ist er bereit, uns beträchtliche Mittel und sogar ein eigenes Studio zur Verfügung zu stellen."
  },
  AvgDialog_15606_Content_37 = {
    Text = "Warum hörst du nicht zu—ich weiß nicht, wie man dieses Ding herstellt, ich kann es nicht!"
  },
  AvgDialog_15606_Content_38 = {
    Text = "Ich bin zu alt, um an Märchen zu glauben, Erica. Was für ein <Blue:Mysteriöser Händler>? Wenn du mich abwimmeln willst, dann denk dir wenigstens eine bessere Ausrede aus."
  },
  AvgDialog_15606_Content_39 = {
    Text = "Wenn du solch unglaubliche Dinge erschaffen kannst, warum hast du dann keine langfristigere Vision?"
  },
  AvgDialog_15606_Content_4 = {
    Text = "Kann gehört werden."
  },
  AvgDialog_15606_Content_40 = {
    Text = "Warum sperrst du dich an diesem Ort ein und bastelst an diesem Schrott herum?"
  },
  AvgDialog_15606_Content_41 = {
    Text = "Meis Worte trafen Erica wie eine Ohrfeige. Sie starrte ihre Partnerin und Gefährtin an, unfähig zu glauben, was sie gerade gehört hatte."
  },
  AvgDialog_15606_Content_42 = {
    Text = "...Schrott, denkst du das wirklich?"
  },
  AvgDialog_15606_Content_43 = {
    Text = "Ich dachte, wir teilten dieselben Ideale."
  },
  AvgDialog_15606_Content_44 = {
    Text = "Mei biss sich auf die Lippe und umklammerte den Zylinder fester."
  },
  AvgDialog_15606_Content_45 = {
    Text = "Sieh den Tatsachen ins Auge, Erica. Niemand will mehr Geld für Automaten ausgeben. Neue Energie ist unsere Zukunft."
  },
  AvgDialog_15606_Content_46 = {
    Text = "...leg die spezielle Energiequelle hin."
  },
  AvgDialog_15606_Content_47 = {
    Text = "Denk an alles, was wir haben könnten: mehr Mittel, mehr Ressourcen.\nDamit kannst du deinen Träumen nachgehen. Damit kannst du—"
  },
  AvgDialog_15606_Content_48 = {
    Text = "Ich sagte: „Leg es hin!\""
  },
  AvgDialog_15606_Content_49 = {
    Text = "Erica stürzte nach vorn, um danach zu greifen, doch Mei konnte nicht rechtzeitig ausweichen und prallte gegen einen nahestehenden Schrank."
  },
  AvgDialog_15606_Content_5 = {
    Text = "Tut mir leid, ich verspreche, mich als Nächstes auf das Stimmmodul zu konzentrieren! Bitte halte noch ein wenig durch, ja?"
  },
  AvgDialog_15606_Content_50 = {Text = "!!"},
  AvgDialog_15606_Content_51 = {
    Text = "Flaschen voller verschiedener Reagenzien und Brennstoffe kippen um. Du stürzt dich schützend vor die beiden Personen vor dir. In der nächsten Sekunde—"
  },
  AvgDialog_15606_Content_6 = {Text = "Nicken."},
  AvgDialog_15606_Content_7 = {
    Text = "Dem Vatergott sei Dank, das ist großartig. Ich hatte wirklich Angst, dass ein Kabel durchgebrannt sein könnte."
  },
  AvgDialog_15606_Content_8 = {
    Text = "Sie stieß einen erleichterten Seufzer aus und gähnte dann ausgiebig, als würde sie erst jetzt die Müdigkeit spüren."
  },
  AvgDialog_15606_Content_9 = {
    Text = "Ich muss mir einen Kaffee holen und zu Abend essen..."
  },
  AvgDialog_15607_Content_1 = {
    Text = "Der Plasmakanone traf die riesige Hand, der Silberkern löste sich bei der Kollision von der Handfläche und fiel lautlos zu Boden"
  },
  AvgDialog_15607_Content_10 = {
    Text = "Was... habe ich... getan..."
  },
  AvgDialog_15607_Content_11 = {
    Text = "Du verstehst es immer noch nicht. Aber das spielt keine Rolle – du hast diese Revolution des Lebens und der Seele bereits entfacht – diese <Red:„Transzendenz\">.\nStirb in Frieden. Ich werde dafür sorgen, dass die ganze Welt deinen Beitrag in Erinnerung behält."
  },
  AvgDialog_15607_Content_12 = {
    Text = "Erica schloss ihre Augen."
  },
  AvgDialog_15607_Content_13 = {
    Text = "Du hast... recht, du hattest schon immer recht..."
  },
  AvgDialog_15607_Content_14 = {
    Text = "Schwarze Tränen glitten aus ihren Augenwinkeln, als sie die Nase rümpfte und sich plötzlich zu dir umdrehte."
  },
  AvgDialog_15607_Content_15 = {
    Text = "Ich hätte... von Anfang an... auf dich hören sollen... Ich... hätte dieses Ding nicht nehmen sollen..."
  },
  AvgDialog_15607_Content_16 = {
    Text = "Mein Verstand... mein... hilf mir... dieses eine letzte Mal..."
  },
  AvgDialog_15607_Content_17 = {
    Text = "Gibt es wirklich ein drittes Bewusstsein in diesem <Körper>, oder bist du lediglich die Verkörperung ihrer Schuld unter dem Einfluss der <Auflösung>? Du kannst es nicht sagen."
  },
  AvgDialog_15607_Content_18 = {
    Text = "Sie streckt dir ihre Hand entgegen."
  },
  AvgDialog_15607_Content_19 = {
    Text = "Hilf... mir... rette..."
  },
  AvgDialog_15607_Content_2 = {
    Text = "Nach einem kurzen Stillstand zerbrach die riesige Hand und die schwarze Schleimflüssigkeit strömte wie Regen herab, durchdrang dich, färbte jedoch Ericas Phantasie schwarz"
  },
  AvgDialog_15607_Content_20 = {
    Text = "Du weißt nur, dass du ihr helfen und ihr Schicksal als „Mensch\" bezeugen wirst."
  },
  AvgDialog_15607_Content_21 = {
    Text = "Ihre Hand ergreifen"
  },
  AvgDialog_15607_Content_22 = {
    Text = "Sie sieht dich überrascht an, als hätte sie sich nie vorgestellt, dass sie ihren eigenen „Verstand“ tatsächlich berühren könnte."
  },
  AvgDialog_15607_Content_23 = {Text = "Nicke"},
  AvgDialog_15607_Content_24 = {
    Text = "Sie sieht dich überrascht an, als hätte sie nie erwartet, dass ihr „Gewissen“ antworten würde."
  },
  AvgDialog_15607_Content_25 = {
    Text = "Vielen Dank..."
  },
  AvgDialog_15607_Content_26 = {
    Text = "Das Phantom zerplatzte wie eine Seifenblase und hinterließ nur eine flackernde Lichtkugel, die noch ihr letztes Licht ausstrahlte."
  },
  AvgDialog_15607_Content_27 = {
    Text = "Du hältst die geschrumpfte Lichtkugel in deinen Armen und blickst auf den zerbrochenen Silberkern in der Nähe."
  },
  AvgDialog_15607_Content_28 = {
    Text = "Du wirst erfolgreich sein."
  },
  AvgDialog_15607_Content_3 = {
    Text = "Es ist... vorbei..."
  },
  AvgDialog_15607_Content_4 = {
    Text = "Denkst du das wirklich?"
  },
  AvgDialog_15607_Content_5 = {Text = "!?"},
  AvgDialog_15607_Content_6 = {
    Text = "Ich sagte, sobald wir das silberne Herz betreten, erreichen wir wahre Unsterblichkeit"
  },
  AvgDialog_15607_Content_7 = {
    Text = "Sträube dich so viel du willst, die schwarze Materie wird dich letztendlich auslöschen, und dann werde ich der Welt die wahre <Red:„Transformation“> bringen – Unsterblichkeit für alle"
  },
  AvgDialog_15607_Content_8 = {
    Text = "Das ist... Tod... nicht..."
  },
  AvgDialog_15607_Content_9 = {
    Text = "Die schwarze Farbe verschlang zunehmend ihren Körper. Erica krümmte sich vor Schmerz, ihr Geist stand kurz vor dem Zusammenbruch."
  },
  AvgDialog_15608_Content_1 = {
    Text = "Ist das... ein Geisterraum?"
  },
  AvgDialog_15608_Content_2 = {
    Text = "Oh mein Gott, was um alles in der Welt ist das..."
  },
  AvgDialog_15608_Content_3 = {
    Text = "Stimme... Erica!"
  },
  AvgDialog_15609_Content_1 = {
    Text = "Nein, Erica, glaub das nicht!"
  },
  AvgDialog_15609_Content_10 = {
    Text = "Der Fleisch-Körper ist nur ein Käfig für die Seele; nur indem wir die Seele befreien, kann sie sich uns anschließen.\nNur metallene Körper und Geister gewähren uns Ewigkeit."
  },
  AvgDialog_15609_Content_11 = {
    Text = "Die Finger zogen sich zusammen, Meis Gesicht verzerrte sich vor Schmerz."
  },
  AvgDialog_15609_Content_12 = {
    Text = "<Shake:Du... Wahnsinniger...>"
  },
  AvgDialog_15609_Content_13 = {
    Text = "Eine weitere zitternde Hand erscheint auf dem Bildschirm. Erica packt ihr eigenes Handgelenk, verdreht es und löst die unkontrollierbare Hand ab, wirft sie beiseite."
  },
  AvgDialog_15609_Content_14 = {
    Text = "Die riesige Hand hielt einen Moment inne, als ob sie etwas verwirrt wäre."
  },
  AvgDialog_15609_Content_15 = {
    Text = "Warum widersetzt du dich mir? Ich schenke ihr ein neues Leben."
  },
  AvgDialog_15609_Content_16 = {
    Text = "Das sind alles Trugbilder, Trugbilder."
  },
  AvgDialog_15609_Content_17 = {
    Text = "Erica half der bewusstlosen Mei, langsam aufzustehen."
  },
  AvgDialog_15609_Content_18 = {
    Text = "Ich bringe sie ins Krankenhaus. Ich... muss sie am Leben halten."
  },
  AvgDialog_15609_Content_19 = {
    Text = "Sie hievte Mei auf ihre Schulter und bahnte sich einen Weg durch das in Stücke gesprengte Studio, auf die nahe gelegene Tür zu."
  },
  AvgDialog_15609_Content_2 = {
    Text = "Erica, Erica!"
  },
  AvgDialog_15609_Content_3 = {
    Text = "Während du den Feind vor dir bekämpfst, schleicht sich eine Schleimkreatur von hinten an und stürzt sich auf das Licht, das Ericas Geist repräsentiert."
  },
  AvgDialog_15609_Content_4 = {
    Text = "Wie Farbe, die sich in Wasser auflöst, breitet sich Dunkelheit in der Lichtkugel aus und bedeckt alles darin.\nDie Lichtkugel beginnt zu flackern."
  },
  AvgDialog_15609_Content_5 = {
    Text = "Was ist los? Meine Hand... sie bewegt sich von allein..."
  },
  AvgDialog_15609_Content_6 = {
    Text = "Warst du das? Hör auf, <Big:Hör auf!>"
  },
  AvgDialog_15609_Content_7 = {
    Text = "Warum? Willst du sie nicht retten?"
  },
  AvgDialog_15609_Content_8 = {
    Text = "Du versuchst, sie zu erdrosseln! Lass los!"
  },
  AvgDialog_15609_Content_9 = {
    Text = "Während Dunkelheit und Licht sich verflechten, siehst du eine mechanische Hand, die sich langsam Meis Hals nähert."
  },
  AvgDialog_15610_Content_1 = {
    Text = "Die Verteidigungslinie einer einzelnen Person ist so gut wie nicht existent, egal wie viele Monster du zerschmetterst. Aus Schleim geformte Körper gruppieren sich schnell neu, gehen an dir vorbei und springen direkt in die Lichtsphäre."
  },
  AvgDialog_15610_Content_10 = {
    Text = "Goldenes Plasma knisterte auf den Schatten und ließ Ericas Gestalt immer fester werden."
  },
  AvgDialog_15610_Content_11 = {
    Text = "Sie hebt die Hand und zerstreut das Monster vor dir mit Plasma. Die riesige Hand zuckt leicht und stößt einen Seufzer aus."
  },
  AvgDialog_15610_Content_12 = {
    Text = "Ich wollte es euch lediglich vergelten, dass ihr mich zurückgebracht und mir einen neuen Körper geschenkt habt. Warum mir Schaden zufügen?"
  },
  AvgDialog_15610_Content_13 = {
    Text = "Zurückgebracht? Was meinst du mit „zurückgebracht\"? Ich habe nie..."
  },
  AvgDialog_15610_Content_14 = {
    Text = "Kann das meine Puppe mit Energie versorgen?"
  },
  AvgDialog_15610_Content_15 = {
    Text = "Erica betrachtete misstrauisch das schwarze Metallrohr und musterte es von oben bis unten"
  },
  AvgDialog_15610_Content_16 = {
    Text = "Wenn du dir Sorgen machst, dass es die Puppe nicht lange betreiben kann, mach dir keine Gedanken.\nSo ein Ding kann viel komplexere und größere Dinge betreiben"
  },
  AvgDialog_15610_Content_17 = {
    Text = "Meinst du, jemand anderes nutzt diese Energiequelle?"
  },
  AvgDialog_15610_Content_18 = {
    Text = "Ähnliche Dinge gibt es, aber genau dasselbe? Unmöglich"
  },
  AvgDialog_15610_Content_19 = {
    Text = "Du willst „einzigartige Energie“, und Daffodils Laden enttäuscht nie"
  },
  AvgDialog_15610_Content_2 = {
    Text = "W–wie nervig..."
  },
  AvgDialog_15610_Content_20 = {
    Text = "Übrigens, ein freundlicher Hinweis – sei nicht neugierig auf seine Konstruktion und Funktionsweise.\nWenn die Büchse der Pandora geöffnet wird, musst du die Konsequenzen selbst tragen"
  },
  AvgDialog_15610_Content_21 = {
    Text = "Ich möchte nicht, dass ein Genie wie du früh stirbt. Neben dem Projektor habe ich noch viele andere Ideen, die ich verwirklichen möchte"
  },
  AvgDialog_15610_Content_22 = {
    Text = "Ich freue mich auf deinen nächsten Besuch, Erica."
  },
  AvgDialog_15610_Content_23 = {
    Text = "Nein, unmöglich. In Energie S ist nur"
  },
  AvgDialog_15610_Content_24 = {
    Text = "Ein kleines <Yellow: silbernes Fragment>，nicht wahr?\nDieses wunderbare kleine Ding kann nicht nur Maschinen antreiben, sondern auch die Seelen der Lebewesen bewahren"
  },
  AvgDialog_15610_Content_25 = {
    Text = "Dein Geist ist dank der schwarzen Substanz in diesen Körper eingedrungen, solange du vor der Erosion in das <Yellow:silberne Herz> eintrittst, wirst du wirklich unsterblich sein. Du und ich.\n\nAls meine „Mutter“ in diesem Leben hast du das Recht, es mit mir zu teilen.\nLeider bist du so stur"
  },
  AvgDialog_15610_Content_26 = {
    Text = "Ich kann dich nur von der <Yellow:schwarzen Substanz> verschlingen lassen"
  },
  AvgDialog_15610_Content_27 = {
    Text = "Die riesige Hand bewegt sich plötzlich, spreizt die Finger und zeigt ihre Handfläche, die mit Rissen übersät ist, aber immer noch glänzt"
  },
  AvgDialog_15610_Content_28 = {
    Text = "Leb wohl, mein kurzlebiger Schöpfer"
  },
  AvgDialog_15610_Content_3 = {
    Text = "Die Kugel flackert erneut, und du siehst, wie Ericas Beine unkontrolliert zittern."
  },
  AvgDialog_15610_Content_4 = {
    Text = "Zahnräder greifen fest ineinander, und ein leuchtend gelber Lichtbogen blitzt zwischen den Rohren und Halterungen auf."
  },
  AvgDialog_15610_Content_5 = {
    Text = "Hör auf, dich zu wehren. Übergib mir die Kontrolle über deinen Körper."
  },
  AvgDialog_15610_Content_6 = {
    Text = "Willst du sie nicht retten? Wünschst du dir nicht, dass sie gemeinsam mit dir die Ewigkeit erlangt?"
  },
  AvgDialog_15610_Content_7 = {
    Text = "Weitere Blitze erscheinen auf dem Bildschirm."
  },
  AvgDialog_15610_Content_8 = {
    Text = "Lichtpartikel strömten aus der Kugel und sammelten sich zu einer menschlichen Silhouette."
  },
  AvgDialog_15610_Content_9 = {Text = "E-Erica?!"},
  AvgDialog_15611_Content_1 = {
    Text = "Warum rettest du sie?\nSie hat deine Träume gegen ihre Zukunft eingetauscht. Empfindest du keinen Groll?"
  },
  AvgDialog_15611_Content_10 = {
    Text = "Aber bald erkannte ich: Dies ist keine Katastrophe, kein Trugbild, sondern eine Chance für die Menschheit."
  },
  AvgDialog_15611_Content_11 = {
    Text = "Kein Schmerz oder Tod in Maschinen; in Maschinen können wir ein wahres Göttliches Reich erschaffen, besser als deins falsches.\n\nWir können das Leben von Caro transzendieren."
  },
  AvgDialog_15611_Content_12 = {
    Text = "Schwarzer Schleim tropft erneut von der riesigen Hand. Zitternd und sich windend kriecht er vorwärts, verschmilzt mit sich selbst, erregt von der unheimlichen Szene, die der Klang beschreibt."
  },
  AvgDialog_15611_Content_13 = {
    Text = "Die Stimme wird lauter, die riesige Hand bebt und schleudert noch mehr Schleim und noch mehr Monster heraus."
  },
  AvgDialog_15611_Content_14 = {
    Text = "Wir können selbst Götter werden."
  },
  AvgDialog_15611_Content_15 = {
    Text = "Der Schleim beschleunigt plötzlich und stürzt sich erneut auf die Lichtkugel hinter dir."
  },
  AvgDialog_15611_Content_2 = {
    Text = "Sie hat einfach... eine falsche Entscheidung getroffen.\nWenn sie aufwacht, reden wir darüber und alles wird sich klären."
  },
  AvgDialog_15611_Content_3 = {
    Text = "Die nächste Telefonzelle ist einen Kilometer entfernt; sie kann nicht so lange warten."
  },
  AvgDialog_15611_Content_4 = {
    Text = "Tut mir leid, ich vertraue lieber auf den Überlebensinstinkt der Menschheit als auf deinen Unsinn über „Seelenbefreiung“."
  },
  AvgDialog_15611_Content_5 = {
    Text = "Wenn ich lüge, wie erklärst du dir dann deinen jetzigen Zustand?\nDein Fleisch-Körper wurde in Stücke gerissen, und doch besteht dein Geist fort, kontrolliert sogar diesen Körper, um weiterzuleben.\n\nBeweist das nicht meinen Standpunkt?"
  },
  AvgDialog_15611_Content_6 = {
    Text = "<Big:Du kannst nicht sicher sein, dass ich deshalb so geworden bin!>"
  },
  AvgDialog_15611_Content_7 = {
    Text = "Erica hielt inne und schien einatmen zu wollen, hatte aber nicht mehr die Organe dafür."
  },
  AvgDialog_15611_Content_8 = {
    Text = "Was tue ich da, mit einem Trugbild zu streiten... Nicht zuhören, nicht nachdenken. Er ist ein Trugbild, entstanden aus giftigem Gas—"
  },
  AvgDialog_15611_Content_9 = {
    Text = "Du hast Angst, also versuchst du wegzulaufen.\nIch verstehe. Genau wie du war auch ich voller Angst direkt nach der <Red:„Verwandlung\">."
  },
  AvgDialog_15612_Content_1 = {
    Text = "Unsichtbare Rhythmen umgeben und umhüllen dich, während in der Ferne schwache Lichtschimmer erscheinen, zerbrechlich und unerreichbar."
  },
  AvgDialog_15612_Content_10 = {
    Text = "<Gray:Keine Möglichkeit... Könnte es sein...?>"
  },
  AvgDialog_15612_Content_11 = {
    Text = "Teilst du und Erica gerade denselben Körper?\nIst das der Grund, warum sie sich in eine mechanische Puppe verwandelt hat?"
  },
  AvgDialog_15612_Content_12 = {
    Text = "<Gray:Aber wie könnte eine gewöhnliche Explosion eine solche Wirkung haben?>"
  },
  AvgDialog_15612_Content_13 = {
    Text = "Möchtest du sie retten?"
  },
  AvgDialog_15612_Content_14 = {Text = "?!"},
  AvgDialog_15612_Content_15 = {
    Text = "Eine Stimme taucht aus dem Nichts auf, allgegenwärtig und doch nicht greifbar.\nDu schaust dich um, und eine Silhouette beginnt sich im weiten mentalen Raum zu formen."
  },
  AvgDialog_15612_Content_16 = {
    Text = "Wer, wer ist da?"
  },
  AvgDialog_15612_Content_17 = {
    Text = "Ich bin der Wille, der dir antwortet, das Leben, dem du einen neuen Körper geschenkt hast."
  },
  AvgDialog_15612_Content_18 = {
    Text = "Man könnte sagen, ich bin dein Relikt, und du bist meine „Mutter“ in diesem Leben."
  },
  AvgDialog_15612_Content_19 = {
    Text = "Eine riesige Hand materialisiert sich hinter der Kugel, die Ericas Geist repräsentiert, ihre Finger zucken und tropfen vor schwarzem Schleim."
  },
  AvgDialog_15612_Content_2 = {
    Text = "Mei, Mei! Wach auf, Mei!"
  },
  AvgDialog_15612_Content_20 = {
    Text = "...Tick-Tack-Leute...?"
  },
  AvgDialog_15612_Content_21 = {
    Text = [[
Ich mag diesen Namen, ja, nenn mich den Tick-Tack.
Als Zeichen meiner Wiedergeburt kann ich dir helfen, sie zu retten.
Du musst nur loslassen.]]
  },
  AvgDialog_15612_Content_22 = {
    Text = "Lass los, und überlasse alles mir."
  },
  AvgDialog_15612_Content_23 = {
    Text = "Der auf dem Boden aufgehäufte Schleim begann sich plötzlich zu regen, verschmolz zu verzerrten Formen, die sich auf das Licht zuwanden."
  },
  AvgDialog_15612_Content_3 = {
    Text = "Du näherst dich schnell der Quelle des Geräuschs."
  },
  AvgDialog_15612_Content_4 = {
    Text = "Es ist eine schwebende Lichtkugel. Durch sie hindurch siehst du ein Gesicht, bedeckt mit Blut und Sand — Meis Gesicht."
  },
  AvgDialog_15612_Content_5 = {
    Text = "Sie schien ohnmächtig zu sein und reagierte nicht einmal auf ein sanftes Klopfen einer blassen Hand."
  },
  AvgDialog_15612_Content_6 = {
    Text = "<Gray:Diese Hand...>"
  },
  AvgDialog_15612_Content_7 = {
    Text = "Du senkst den Blick und bestätigst deinen Verdacht: Die Hand in der Lichtsphäre ist identisch mit deiner. \nEs ist die Hand eines Automaten, die sich nun nach dem Willen eines anderen bewegt."
  },
  AvgDialog_15612_Content_8 = {
    Text = "Verdammtes Miststück, Mei! Wir müssen hier raus, Mei!"
  },
  AvgDialog_15612_Content_9 = {
    Text = "Die mechanische Hand legte sich auf Meis Schulter, und das Bild in der Lichtsphäre verschob sich und enthüllte ein Atelier, das noch immer in Flammen stand, als würde jemand sich umsehen."
  },
  AvgDialog_15613_Content_1 = {
    Text = "Brillantes Finale"
  },
  AvgDialog_15613_Content_10 = {
    Text = "Rechter Fuß."
  },
  AvgDialog_15613_Content_11 = {
    Text = "Erica sank auf die Knie. Häufige Kurzschlüsse hatten ihr linkes Bein kraftlos gemacht, sodass sie sich mit ihrem rechten Arm abstützen musste, dem eine Hand fehlte."
  },
  AvgDialog_15613_Content_12 = {
    Text = "Sie lehnte Mei vorsichtig an die Telefonzelle und kroch dann auf allen Vieren hinein. \nDer elektrische Strom aktivierte die Telefonzelle, und sie drückte den Notrufknopf und nannte den Standort der Zelle."
  },
  AvgDialog_15613_Content_13 = {
    Text = "So wird... sie... in Sicherheit sein..."
  },
  AvgDialog_15613_Content_14 = {
    Text = "Was kommt als Nächstes...? Was... könnte es sein...?"
  },
  AvgDialog_15613_Content_15 = {
    Text = "Du weißt, was es ist."
  },
  AvgDialog_15613_Content_16 = {
    Text = "Du erinnerst dich an den Inhalt der Akte, die du gelesen hast, bevor du hierher kamst."
  },
  AvgDialog_15613_Content_17 = {
    Text = "Am A.F. 297 @1@1 03:47 ereignete sich eine unerklärliche Explosion südöstlich der Agro-Republik @3 Zustand @1@2@1 Stadt. Die Druckwelle löste ein Erdbeben der Stärke 3,8 in der Region aus, wobei spürbare Erschütterungen Dörfer in 5 Kilometern Entfernung von @1@2@1 Stadt erreichten.\n\n......\n\nAm A.F. 297 @1@1 wurden 13 Komponenten aus den Wäldern südöstlich der Agro-Republik @3 Zustand @1@2@1 Stadt geborgen, nummeriert A101 bis A114. Darunter waren die Komponenten A108, A109 und A113 schwer beschädigt und wurden an Doll zur Designrekonstruktion übergeben.\nEine Reihe von Konstruktionsplänen, die zu den Überresten am Explosionsort passen, wurden vom Ermittlungsteam in @2 Straße @1 sichergestellt. Es wird vermutet, dass es sich um Baupläne für Sprengvorrichtungen handelt, die ebenfalls Doll zur Analyse übergeben wurden."
  },
  AvgDialog_15613_Content_18 = {
    Text = "Du hörst den Wind durch die Blätter rascheln."
  },
  AvgDialog_15613_Content_19 = {
    Text = "Die Lichtkugel ist verblasst und verschmilzt beinahe mit der umgebenden Dunkelheit."
  },
  AvgDialog_15613_Content_2 = {
    Text = "Linker Fuß."
  },
  AvgDialog_15613_Content_20 = {
    Text = "Selbst wenn du ihren Fleisch-Körper rettest, was dann? \nDer Tod wird irgendwann kommen; wenn es soweit ist, wird sie dir danken, oder wird sie dir vorwerfen, dass du ihr die Chance auf Unsterblichkeit genommen hast? \n\nLass los, Erica, und überlass mir diesen Körper. \nIch werde sie <Red:„Transformieren\"> lassen, damit sie eine bessere Zukunft haben kann."
  },
  AvgDialog_15613_Content_21 = {
    Text = "Ich... dachte immer... ich würde bei einer Explosion sterben...\nEntschuldige... dass... ich dich da mit reingezogen habe..."
  },
  AvgDialog_15613_Content_22 = {
    Text = "...Was hast du vor?"
  },
  AvgDialog_15613_Content_23 = {
    Text = "Halt die Klappe... Dämon... Ich rede... nicht mit dir..."
  },
  AvgDialog_15613_Content_24 = {
    Text = "Das Bild in der Kugel zeigt eine verkohlte mechanische Hand, aus der noch immer Plasma austritt."
  },
  AvgDialog_15613_Content_25 = {
    Text = "Irgendwann hielten sie mehrere Fäden in den Händen, bedeckt mit schwarzem Schleim."
  },
  AvgDialog_15613_Content_26 = {
    Text = "Tut mir leid, Tik-Tok-Leute... Am Ende... muss ich euch selbst zerstören..."
  },
  AvgDialog_15613_Content_27 = {
    Text = [[
Stille breitete sich unter euch aus.
Du bist dir deiner Rolle in diesem Traum noch immer nicht sicher, und sie scheint keine Antwort zu erwarten.]]
  },
  AvgDialog_15613_Content_28 = {Text = "*seufz*..."},
  AvgDialog_15613_Content_29 = {
    Text = "Wie... schade..."
  },
  AvgDialog_15613_Content_3 = {
    Text = "Rechter Fuß."
  },
  AvgDialog_15613_Content_30 = {
    Text = "Sie zog mit großer Kraft."
  },
  AvgDialog_15613_Content_32 = {
    Text = "Du setzt dich plötzlich auf und findest dich in deinem vertrauten Zimmer wieder."
  },
  AvgDialog_15613_Content_33 = {
    Text = "Jemand klopft an deine Tür."
  },
  AvgDialog_15613_Content_34 = {Text = "Komm rein."},
  AvgDialog_15613_Content_35 = {
    Text = "Guten Tag, Hüter. Du hast eine Botschaft von der Puppe. Möchtest du sie empfangen?"
  },
  AvgDialog_15613_Content_36 = {
    Text = "Doll hat eine weitere neue Funktion für Sie hinzugefügt... Empfang läuft."
  },
  AvgDialog_15613_Content_37 = {
    Text = "Piep—Erinnerst du dich, welcher Tag heute ist, %player%? Zwei Worte: Prüfung."
  },
  AvgDialog_15613_Content_38 = {
    Text = "...Oh nein."
  },
  AvgDialog_15613_Content_39 = {
    Text = "Ich schlage vor, du erscheinst innerhalb von fünf Minuten im Klassenzimmer, sonst kann ich nicht garantieren, wie dein Training in den nächsten 30 Tagen aussehen wird. Vielleicht wird das körperliche Training verdoppelt?"
  },
  AvgDialog_15613_Content_4 = {
    Text = "Jeder Schritt sprüht Funken, und jede Bewegung hallt mit dem schrillen Klirren von Maschinerie wider."
  },
  AvgDialog_15613_Content_40 = {
    Text = "Piep—Ende der Nachricht. Möchten Sie antworten?"
  },
  AvgDialog_15613_Content_41 = {
    Text = "Was willst du denn antworten? Einfach raus hier!!"
  },
  AvgDialog_15613_Content_42 = {
    Text = "Die Gestalt des Schutzherrn verschwand am Ende des Korridors. Erica drehte sich um und blickte auf die verstreuten Akten auf dem Tisch."
  },
  AvgDialog_15613_Content_43 = {
    Text = "Jahr 298@Jan@2, Misaq Universität Abteilung für Erweckung, @3\nTorso-Restaurierung von Automaton E gemäß T-38-Bauplänen abgeschlossen, Seriennr. EA301881.\nDies ist unser 10. Restaurierungsversuch. Ich muss meine Bewunderung für den ursprünglichen Designer und Schöpfer dieses Automaten ausdrücken—er ist kunstvoll und elegant, mit Hunderten ineinandergreifenden Zahnrädern und Lagern, die eine Symphonie der Mechanik bilden. Selbst im Stillstand strahlt er eine einzigartige Vitalität aus.\nLeider fehlt uns noch der entscheidende Maschinenplan—ein Zylinder mit einem Durchmesser von 5 cm und einer Länge von 10 cm. Dies sollte der Energiekern des Automaten sein, doch mir ist noch nie etwas so Kleines begegnet, das ein derart komplexes Gerät antreiben könnte...\nIch hoffe, Professor Doll hat einige Ideen. Ich kann es kaum erwarten, ihn voll funktionsfähig zu sehen."
  },
  AvgDialog_15613_Content_44 = {
    Text = "Jahr 298@Jan@2, Misaq Universität Abteilung für Erweckung, @3\nRestaurierung der elektrischen Maschine abgeschlossen, Seriennr. MF311028.\nTrotz vieler Hürden (Beim Vater, wir haben es 28 Mal versucht, 28 Mal!) erwies sich Professor Dolls finales Design als korrekt—der Energiekern ist ein Silberkern.\nUnter mehreren getesteten Silberkernen ermöglichte nur Einheit E-1929 den normalen Maschinenbetrieb. Ich kann nicht umhin zu denken, dass ein verbliebener Wille des Designers dies beeinflusst hat, obwohl sein derzeitiger Aufenthaltsort unbekannt bleibt."
  },
  AvgDialog_15613_Content_45 = {
    Text = "Schwemmjahr 300, @2. Monat, @1. Tag, Misaq Universität, Abteilung für Erweckung, Doll\nAutomatische Doll Erica wurde erfolgreich erweckt.\nDer Erweckte Körper zeigt extreme Aggressivität und zerstörerische Begierden. Selbst während der Ermittler ihren Geist aufrechterhält, zeigt sie eine deutliche Neigung zum Angriff und gibt unkontrolliert elektrische Ströme ab, die umliegende Objekte wahllos angreifen.\nAlistair stellte fest, dass E-1929 zwei Geister enthält: einer ist wahnsinnig und stark, der andere ist schwach, aber rationaler. Es sollte versucht werden, sie zu trennen oder den Wahnsinn auf ein kontrollierbares Niveau zu inhibieren.\n......\nSchwemmjahr 300, @2. Monat, @2. Tag, Misaq Universität, Abteilung für Erweckung, Doll\nDie Geister konnten nicht getrennt werden, die zweite Option wird aktiv in Betracht gezogen.\nEin Geist-Inhibierungsgerät ist eine gute Idee.\n......\nSchwemmjahr 303, @1. Monat, @2. Tag, Misaq Universität, Abteilung für Erweckung, Doll\nInhibierungsgerät fertiggestellt und erfolgreich installiert.\nDer Wahnsinn des Erweckten Körpers ist gebändigt, der Gesamtzustand stabilisiert sich, aber es gibt immer noch Fälle von kurzzeitigem Inhibierungsversagen.\nDie Persönlichkeit, Vorlieben usw. des Erweckten Körpers sind vollständig verloren, das Verhalten gleicht eher einer Puppe als einem Menschen.\nZumindest steht sie nicht mehr jeden Moment kurz vor der Explosion.\n......"
  },
  AvgDialog_15613_Content_46 = {
    Text = "Erica neigte den Kopf, ordnete die Akten sorgfältig und verließ den Raum."
  },
  AvgDialog_15613_Content_5 = {
    Text = "Unter einer nahegelegenen Straßenlaterne steht still eine öffentliche Telefonzelle."
  },
  AvgDialog_15613_Content_6 = {
    Text = "Linker Fuß."
  },
  AvgDialog_15613_Content_7 = {
    Text = "Rechter Fuß."
  },
  AvgDialog_15613_Content_8 = {
    Text = "Als der Schleim auf dem Boden deine Entschlossenheit bemerkt, greift er weiterhin Ericas Geist an und färbt dich vollständig schwarz."
  },
  AvgDialog_15613_Content_9 = {
    Text = "Linker Fuß."
  },
  AvgDialog_18708_Content_1 = {Text = "!!!"},
  AvgDialog_18708_Content_10 = {
    Text = "Begleitet von schmerzhaften Stöhnen verzerrten sich die Züge des Schädeljägers auf unglaubliche Weise, mit eitergefüllten Zysten, die unter der Haut writhen und bereit waren auszubrechen."
  },
  AvgDialog_18708_Content_11 = {
    Text = "Was ist das...?"
  },
  AvgDialog_18708_Content_13 = {
    Text = "Dein Kopf wird gnadenlos abgetrennt, schwarzes D-Slime spritzt aus dem Hals und spritzt beinahe auf dein Gesicht."
  },
  AvgDialog_18708_Content_14 = {
    Text = "Übermäßig neugierig zu sein, ist keine gute Gewohnheit, Hüter."
  },
  AvgDialog_18708_Content_15 = {
    Text = "Sein Schädel war mit angesammeltem D-Slime gefüllt. Ich schlage vor, du hältst Abstand."
  },
  AvgDialog_18708_Content_16 = {
    Text = "Lady Daffodil!"
  },
  AvgDialog_18708_Content_17 = {
    Text = "Guten Abend, meine kleine Rose."
  },
  AvgDialog_18708_Content_18 = {
    Text = "Warum bist du schon wieder hier...?"
  },
  AvgDialog_18708_Content_19 = {
    Text = "Ich folgte der Spur des Schädeljägers hierher und holte meine Blume zurück."
  },
  AvgDialog_18708_Content_2 = {
    Text = "Der Schädeljäger bricht schwer zu Boden und gibt ein schwaches Stöhnen von sich."
  },
  AvgDialog_18708_Content_20 = {
    Text = "Daffodil ging mühelos über den mit Blut und D-Slime befleckten Boden, pflückte eine Narzisse vom Nachttisch und schnüffelte leicht daran."
  },
  AvgDialog_18708_Content_21 = {
    Text = "Das ist meine Braun Tasse Narzisse, die ich sorgfältig seit drei Jahren kultiviere. Sie hat eine beruhigende und lindern Wirkung."
  },
  AvgDialog_18708_Content_22 = {
    Text = "Möchtest du daran schnüffeln?"
  },
  AvgDialog_18708_Content_23 = {
    Text = "<LightGray:Kein Wunder, dass ich eben so fest geschlafen habe...>"
  },
  AvgDialog_18708_Content_24 = {
    Text = "Du hast gereizt die tauenden, blühenden Narzissen in ihrer Hand beiseite geschoben."
  },
  AvgDialog_18708_Content_25 = {
    Text = "Du scheinst viel über den Schädeljäger zu wissen."
  },
  AvgDialog_18708_Content_26 = {
    Text = "Wie weißt du, dass sein Gehirn D-Schleim absondert?"
  },
  AvgDialog_18708_Content_27 = {
    Text = "Wenn Sie so lange gelebt hätten wie ich und genug Patienten mit Auflösung gesehen hätten, würden Sie natürlich mehr verstehen."
  },
  AvgDialog_18708_Content_28 = {
    Text = "Die Spur des Schädeljägers?"
  },
  AvgDialog_18708_Content_29 = {
    Text = "\"Folge der Spur des Schädeljägers\" – Kannst du seinen Standort spüren?"
  },
  AvgDialog_18708_Content_3 = {
    Text = "Du hörst „Thud, Thud, Thud“ von der Treppe. Die hölzerne Tür hinter dir wird plötzlich aufgerissen."
  },
  AvgDialog_18708_Content_30 = {
    Text = "Ich habe meine eigenen Methoden. Doch... um die Kinder nicht zu erschrecken, sollte ich sie besser nicht offenbaren."
  },
  AvgDialog_18708_Content_31 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18708_Content_32 = {
    Text = "Bitte gehe jetzt, Narzisse Dame. Störe nicht die Ermittlungen des Hüters."
  },
  AvgDialog_18708_Content_33 = {
    Text = "Huh, du zweifelst nicht mehr an mir?"
  },
  AvgDialog_18708_Content_34 = {
    Text = "Ich kann deinen Verdacht noch nicht ganz ausschließen. Aber mein Bauchgefühl sagt mir..."
  },
  AvgDialog_18708_Content_35 = {
    Text = "Wenn du der \"Schädeljäger\" wärst, würdest du es sauberer und effizienter handhaben, ohne solche offensichtlichen Spuren zu hinterlassen."
  },
  AvgDialog_18708_Content_36 = {
    Text = "Oh mein Gott, ist das ein Kompliment für mich?\nUm genau zu sein, ist es eine Tatsache, nicht nur eine Intuition."
  },
  AvgDialog_18708_Content_37 = {
    Text = "...Wechsle nicht das Thema."
  },
  AvgDialog_18708_Content_38 = {
    Text = "Da du heute erst in die Stadt gekommen bist, wer war derjenige, den ich letzte Nacht gesehen habe?"
  },
  AvgDialog_18708_Content_39 = {
    Text = "Hast du eine Zwillingsschwester?"
  },
  AvgDialog_18708_Content_4 = {
    Text = "{Male=Mr.,Female=Miss} %player%, ich habe gerade ein Geräusch gehört, was ist passiert?"
  },
  AvgDialog_18708_Content_40 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18708_Content_41 = {
    Text = "Daffodil wirkte nachdenklich, dann streckte sie plötzlich die Hand nach dir aus."
  },
  AvgDialog_18708_Content_42 = {
    Text = "Weiche Fingerspitzen streichen einen Moment über dein Gesicht, dann gleiten sie zu deinem Hals und verweilen, um den Puls tief in deinen Blutgefäßen zu spüren."
  },
  AvgDialog_18708_Content_43 = {
    Text = "<Shake:...?>"
  },
  AvgDialog_18708_Content_44 = {
    Text = "Ich dachte immer, Menschen wären Kreaturen mit Geschick im Verkleiden."
  },
  AvgDialog_18708_Content_45 = {
    Text = "Du hüllt euch in ähnliche Caro, sprecht ähnliche Worte, mit ähnlichen Impulsen und Herzschlägen..."
  },
  AvgDialog_18708_Content_46 = {
    Text = "Lange Zeit konnte ich keinen von euch unterscheiden, so wie ihr mich nicht unterscheiden konntet."
  },
  AvgDialog_18708_Content_47 = {
    Text = "Also... du meinst, ihr seid keine Zwillinge, sondern teilt eine Art spezielle Beziehung?"
  },
  AvgDialog_18708_Content_48 = {
    Text = "Es ist möglich. Willst du raten? Du hast drei Versuche."
  },
  AvgDialog_18708_Content_49 = {
    Text = "...Ich weigere mich."
  },
  AvgDialog_18708_Content_5 = {
    Text = "D- Das ist...?!"
  },
  AvgDialog_18708_Content_50 = {
    Text = "Selbst wenn ich richtig rate, wirst du mir trotzdem nicht die echte Antwort sagen. Liege ich richtig?"
  },
  AvgDialog_18708_Content_51 = {
    Text = "Die Narzisse strich gedankenverloren mit ihren Fingern über die Adern an deinem Hals, ihre Augen waren mit einem noch tiefgründigeren Lächeln gefüllt."
  },
  AvgDialog_18708_Content_52 = {
    Text = "Du lernst mich wirklich immer besser kennen, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_18708_Content_53 = {
    Text = "Du machst einen halben Schritt zurück, bewegst dich aus der Reichweite der Narzisse und gibst ihr einen warnenden Blick."
  },
  AvgDialog_18708_Content_54 = {
    Text = "In deinen Augen, machen sie genau gleich auszusehen, sie zu Zwillingen?"
  },
  AvgDialog_18708_Content_55 = {
    Text = "Generell gesprochen, ist dies wahrscheinlich die einzige Möglichkeit."
  },
  AvgDialog_18708_Content_56 = {
    Text = "Aber sowohl du als auch ich wissen, dass die Welt, in der wir leben, alles andere als „gewöhnlich“ ist"
  },
  AvgDialog_18708_Content_57 = {
    Text = "Sicher. Der bedauerlichste Aspekt dieser Welt ist ihre \"Unkonventionalität.\""
  },
  AvgDialog_18708_Content_58 = {
    Text = "Eine sorglose Zwillingsschwester zu sein, scheint auch schön zu sein."
  },
  AvgDialog_18708_Content_6 = {
    Text = "Du trittst vor und ziehst die schwarze Kapuze des Skull Hunter zurück, um das Gesicht darunter zu enthüllen"
  },
  AvgDialog_18708_Content_7 = {
    Text = "Hohe Wangenknochen, eine Hakennase und eingefallene Wangen—ein völlig unbekanntes Gesicht."
  },
  AvgDialog_18708_Content_8 = {
    Text = "Du weißt wirklich, wie man die Ziele wählt, indem du mir bis hierher nachjagst. Wer genau bist du?"
  },
  AvgDialog_18708_Content_9 = {
    Text = "Ugh... Ah..."
  },
  AvgDialog_18709_Content_1 = {
    Text = "Bitterregen"
  },
  AvgDialog_18709_Content_10 = {
    Text = "Du stützt dich gegen die Kopfstütze des Bettes, Erinnerungen an kürzliche Ereignisse fließen vor deinen Augen vorbei. Viele Probleme müssen noch gelöst werden."
  },
  AvgDialog_18709_Content_11 = {
    Text = "Lasst uns zuerst Miss Horla fragen, was sie weiß."
  },
  AvgDialog_18709_Content_12 = {
    Text = "Frage Old Freeman"
  },
  AvgDialog_18709_Content_13 = {
    Text = "Der alte Freeman? Also lebt er noch..."
  },
  AvgDialog_18709_Content_14 = {
    Text = "Ich habe die Dorfbewohner sagen hören, dass er als junger Mensch optimistisch und fröhlich war und jeder ihn mochte."
  },
  AvgDialog_18709_Content_15 = {
    Text = "Nach der <Yellow:Plage> verließ er Reny-Stadt und kehrte als völlig andere Person zurück."
  },
  AvgDialog_18709_Content_16 = {Text = "Pest?"},
  AvgDialog_18709_Content_17 = {
    Text = "Vor drei Jahren ereignete sich im Norden von Ryker Stadt eine Auflösungs-Katastrophe. Die Einheimischen bezeichneten sie als Plage."
  },
  AvgDialog_18709_Content_18 = {
    Text = "Es hat sich jetzt vollständig in ein totes Land verwandelt."
  },
  AvgDialog_18709_Content_19 = {
    Text = "Frage Daffodil"
  },
  AvgDialog_18709_Content_2 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18709_Content_20 = {
    Text = "Miss Horla, der Ton, den du gerade beim Sprechen über die Narzisse verwendet hast ... habt ihr euch vorher gekannt?"
  },
  AvgDialog_18709_Content_21 = {
    Text = "Lady Daffodil..."
  },
  AvgDialog_18709_Content_22 = {
    Text = "Horla betrachtete die Buchseite in ihrer Hand, ein schwaches Lächeln umspielte ihr Gesicht."
  },
  AvgDialog_18709_Content_23 = {
    Text = "Lady Daffodil, sie... hat mir geholfen."
  },
  AvgDialog_18709_Content_24 = {
    Text = "Jahr 15@1, San Pedro"
  },
  AvgDialog_18709_Content_25 = {
    Text = "Diese Sammlung von Longsa's Gedichten ist einzigartig. Achte darauf, sie zu schätzen."
  },
  AvgDialog_18709_Content_26 = {
    Text = "Vielen Dank, Narzissen Dame. Ich kann nicht glauben, dass du es tatsächlich gefunden hast..."
  },
  AvgDialog_18709_Content_27 = {
    Text = "\"Mögest du für immer die strahlende Schönheit einer Rose bewahren.\""
  },
  AvgDialog_18709_Content_28 = {
    Text = "Schöne Poesie. Du hast ausgezeichneten Geschmack."
  },
  AvgDialog_18709_Content_29 = {
    Text = "Ja, aber ich bevorzuge \"Ich ehre diesen Moment mit Milch und Blumen...\""
  },
  AvgDialog_18709_Content_3 = {
    Text = "Ihr seid endlich aufgewacht, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_18709_Content_30 = {
    Text = "Ah... Entschuldigung, ich wurde wieder abgelenkt."
  },
  AvgDialog_18709_Content_31 = {
    Text = "Ich kenne die Regeln des „Austauschladens.“ Also, was willst du von mir?"
  },
  AvgDialog_18709_Content_32 = {
    Text = "Hmm... Ich werde dich genau beobachten, meine kleine Rose."
  },
  AvgDialog_18709_Content_33 = {
    Text = "Der Blick sweepte über Horlas gesamten Körper ohne Emotion. Das Mädchen richtete unwillkürlich ihren Rücken auf."
  },
  AvgDialog_18709_Content_34 = {
    Text = "Kannst du eine Erinnerung mit mir teilen?\nSchmerzhaft, traurig... jede unglückliche Erinnerung wird dabei helfen."
  },
  AvgDialog_18709_Content_35 = {
    Text = "Unglückliche Erinnerungen? D- Das ist keine gute Sache. Was hast du vor, mit ihnen zu tun...?"
  },
  AvgDialog_18709_Content_36 = {
    Text = "Ich plane, es für ein kleines Experiment zu benutzen. Dann wirst du es wissen."
  },
  AvgDialog_18709_Content_37 = {
    Text = "Tage unaufhörlicher Erschöpfung haben deine Nerven erodiert; du gleitest in den Schlaf zu Horlas sanften Worten."
  },
  AvgDialog_18709_Content_38 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18709_Content_39 = {
    Text = "Nach einer unbestimmten Zeit begann ein leichter Nieselregen draußen am Fenster."
  },
  AvgDialog_18709_Content_4 = {
    Text = "Ich erinnere mich, dass ich anscheinend ohnmächtig wurde, und dann..."
  },
  AvgDialog_18709_Content_40 = {
    Text = "Jemand schlufft langsam und endlos durch die matschige Straße im Regen."
  },
  AvgDialog_18709_Content_41 = {
    Text = "Sie erscheinen nur an regnerischen Nächten, ihre Schritte werden vom Regen verborgen, leise schleichen sie sich hinter dir her..."
  },
  AvgDialog_18709_Content_42 = {
    Text = "Die Totenschädel-Jäger sind weder eine Person noch zwei. Die Totenschädel-Jäger sind eine Organisation."
  },
  AvgDialog_18709_Content_43 = {
    Text = "Eine regnerische Nacht, allein... <Red:Ist das nicht deine derzeitige Situation?>"
  },
  AvgDialog_18709_Content_44 = {
    Text = "<Red:Zzz... Krr...>"
  },
  AvgDialog_18709_Content_45 = {
    Text = "<RedBig:Snap!>"
  },
  AvgDialog_18709_Content_46 = {Text = "?!"},
  AvgDialog_18709_Content_47 = {
    Text = "Ein blasser Blitz durchdringt die Stille der Nacht. Sie öffnen abrupt Ihre Augen in der Dunkelheit."
  },
  AvgDialog_18709_Content_48 = {
    Text = "Jemand steht neben deinem Bett."
  },
  AvgDialog_18709_Content_49 = {
    Text = "Der schwere Blick fühlt sich an wie eine kalte, feuchte Sense, die deine Glieder, deinen Rücken und... nachzeichnet."
  },
  AvgDialog_18709_Content_5 = {
    Text = "Ja, es war die Dame Narzisse, die dich zurückbrachte und mich anweisete, gut auf dich zu achten."
  },
  AvgDialog_18709_Content_50 = {
    Text = "Ein ungeschützter Nacken."
  },
  AvgDialog_18709_Content_51 = {
    Text = "Kopf@1 Schädel@4"
  },
  AvgDialog_18709_Content_54 = {Text = "Hmm...!!"},
  AvgDialog_18709_Content_55 = {
    Text = "Du fällst plötzlich vom Bett und deckst instinktiv deinen Hals zu."
  },
  AvgDialog_18709_Content_56 = {
    Text = "Eine schattenhafte Gestalt mit einer Sense steht am Bett und vermischt sich fast mit der Dunkelheit der Nacht dahinter."
  },
  AvgDialog_18709_Content_57 = {
    Text = "Die Luft ist erfüllt vom Duft von Regen und Rost. Dunkelrotes Blut tropft von der kalten, weißen Klinge und sammelt sich auf dem Boden."
  },
  AvgDialog_18709_Content_58 = {
    Text = "—Es ist der Schädeljäger."
  },
  AvgDialog_18709_Content_6 = {
    Text = "Daffodil...?"
  },
  AvgDialog_18709_Content_7 = {
    Text = "Du nimmst einen vertrauten Duft wahr."
  },
  AvgDialog_18709_Content_8 = {
    Text = "Eine schlankhalsige Vase ist auf dem Nachttisch erschienen, mit weißen Narzissen, die ihre Blütenblätter zum Sonnenlicht ausstrecken."
  },
  AvgDialog_18709_Content_9 = {
    Text = "Es ist ihr Duft..."
  },
  AvgDialog_18710_Content_1 = {
    Text = "Bestienkönigreich"
  },
  AvgDialog_18710_Content_10 = {
    Text = "Es war eine klare Sommernacht, und ich trug wie gewohnt fleißig meine \"Beute\" mit mir."
  },
  AvgDialog_18710_Content_11 = {
    Text = "<Shake:Köpfe... mehr Köpfe...>"
  },
  AvgDialog_18710_Content_12 = {
    Text = "Tap. Tap. Tap."
  },
  AvgDialog_18710_Content_13 = {
    Text = "Das Geräusch leiser Schritte näherte sich still, und eine sanfte Stimme kam von oben."
  },
  AvgDialog_18710_Content_14 = {
    Text = "Heh... Was habe ich gefunden? Ein streunendes kleines Tier."
  },
  AvgDialog_18710_Content_15 = {
    Text = "Diese Nacht kam eine Frau zu mir."
  },
  AvgDialog_18710_Content_16 = {
    Text = "Als sie sich mir näherte, nahm ich einen angenehmen Duft wahr.\nEs war der Duft von Blumen und Nebel."
  },
  AvgDialog_18710_Content_17 = {
    Text = "Dies ist der Duft einer anderen Welt, so unterschiedlich von meinem Königreich, wie Tag von Nacht, niemals dazu bestimmt, sich zu kreuzen."
  },
  AvgDialog_18710_Content_18 = {
    Text = "Aber sie stapfte immer noch durch den übelriechenden Schleim, ging durch die Schatten der Stadt und streckte die Hand nach mir aus."
  },
  AvgDialog_18710_Content_19 = {
    Text = "Sie sagte..."
  },
  AvgDialog_18710_Content_2 = {
    Text = "Ich bin ein Biest... Ich bin ein Patient.\n\nIch bin jenseits der Erlösung."
  },
  AvgDialog_18710_Content_20 = {
    Text = "Möchtest du mit mir kommen, kleines Biest?"
  },
  AvgDialog_18710_Content_21 = {
    Text = "5:00, Nord von Reni Stadt"
  },
  AvgDialog_18710_Content_22 = {
    Text = "Dieser Ort ist... wirklich trostlos."
  },
  AvgDialog_18710_Content_23 = {
    Text = "Vor drei Jahren erschien hier ein <Yellow:S-Klasse D-Riss>. Wasser, Vegetation... das gesamte Ökosystem erlitt schwere Schäden."
  },
  AvgDialog_18710_Content_24 = {
    Text = "Glücklicherweise gab es nur wenige Opfer, und die Bewohner wurden unter der Anordnung des Ausschusses evakuiert."
  },
  AvgDialog_18710_Content_25 = {
    Text = "Du schaust auf die trostlosen Wände und die blassen, verdorrten Bäume vor dir."
  },
  AvgDialog_18710_Content_26 = {
    Text = "Wenn nicht für die Auflösung, wäre dies ein grünes Feld in voller Blüte mit Flieder. Wenn der Wind weht, wogen das Gras wie Wellen und ähneln einem grünen Ozean."
  },
  AvgDialog_18710_Content_27 = {
    Text = "Bist du dir sicher, dass der Schädeljäger hier ist, Narzisse?"
  },
  AvgDialog_18710_Content_28 = {
    Text = "Die einzige Antwort ist das heisere Krächzen der Krähen."
  },
  AvgDialog_18710_Content_29 = {
    Text = "Oh, die Narzissenfrau wird vermisst?"
  },
  AvgDialog_18710_Content_3 = {
    Text = "Während des Tages verstecke ich mich im Schatten der Stadt, liege auf dem Rücken mit dem Bauch nach oben und schlafe fest."
  },
  AvgDialog_18710_Content_30 = {
    Text = "Nun, die Folgen des Vertrauens in andere."
  },
  AvgDialog_18710_Content_31 = {
    Text = "Ahem. Sie ist in ihren Bewegungen immer so unberechenbar; ich habe mich längst daran gewöhnt."
  },
  AvgDialog_18710_Content_32 = {
    Text = "Keine Sorgen, ich kann selbst nachforschen. Ich werde hier definitiv etwas finden..."
  },
  AvgDialog_18710_Content_33 = {
    Text = "<Big:Boom—!!>"
  },
  AvgDialog_18710_Content_34 = {
    Text = "Donner grollt in den tief hängenden Wolken, und trockene Blätter rascheln im Herbstwind."
  },
  AvgDialog_18710_Content_35 = {
    Text = "Dies ist ein Zeichen von Regen."
  },
  AvgDialog_18710_Content_36 = {
    Text = "Warum erscheint es nur an regnerischen Tagen?"
  },
  AvgDialog_18710_Content_37 = {
    Text = "Weil, wenn es regnet, Blut und Regen sich vermischen und in die Kanalisation fließen."
  },
  AvgDialog_18710_Content_38 = {
    Text = "Ja, es fließt in die Abwasserkanäle, Särge und die kleinen Rinnsale um dich herum..."
  },
  AvgDialog_18710_Content_39 = {
    Text = "<Red:Zzz... Krr...>"
  },
  AvgDialog_18710_Content_4 = {
    Text = "Nachts wandere ich wie ein Phantom durch die Straßen und suche nach einem Kopf nach dem anderen."
  },
  AvgDialog_18710_Content_40 = {
    Text = "Eine regnerische, dunkle Nacht... Nein, ich träume wieder vor mich hin."
  },
  AvgDialog_18710_Content_41 = {
    Text = "Du schütteltest energisch den Kopf, versuchtest das Chaos aus deinem Kopf zu vertreiben."
  },
  AvgDialog_18710_Content_42 = {
    Text = "Die Zeit läuft ab. Du musst schnell handeln."
  },
  AvgDialog_18710_Content_5 = {
    Text = "<Red:Schädel. Schädel. Schädel.>"
  },
  AvgDialog_18710_Content_6 = {
    Text = "<RedBig:Köpfe.\n        Köpfe.\n                Köpfe.\n                        Köpfe.\n                                Köpfe.\n                                        Köpfe...>"
  },
  AvgDialog_18710_Content_7 = {
    Text = "Mein Geist kann nicht länger über Überleben, Liebe und Würde nachdenken.\n\nEr ist längst bis zum Rand gefüllt mit diesen unersättlichen Fantasien."
  },
  AvgDialog_18710_Content_8 = {
    Text = "Ich bin jenseits der Erlösung."
  },
  AvgDialog_18710_Content_9 = {
    Text = "Jahr 15@1, San Pedro Stadt"
  },
  AvgDialog_18711_Content_1 = {Text = "Ahhhh—!!"},
  AvgDialog_18711_Content_10 = {
    Text = "Sie ignorierte den schmutzigen Schleim und das Blut auf dem Boden, hockte sich hin und starrte das kämpfende Wesen vor ihr an."
  },
  AvgDialog_18711_Content_11 = {
    Text = "Hör auf zu suchen. Sie sind weg und werden niemals zurückkommen."
  },
  AvgDialog_18711_Content_12 = {
    Text = "Was du brauchst, sind nicht diese Dinge."
  },
  AvgDialog_18711_Content_13 = {
    Text = "Kein Grund...? Nein, Head@1, gib es mir."
  },
  AvgDialog_18711_Content_14 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18711_Content_15 = {
    Text = "Wusstest du? Tatsächlich... sind wir gleich.\nIch verstehe deinen Schmerz."
  },
  AvgDialog_18711_Content_16 = {
    Text = "Jahr 15@1, San Pedro Stadt"
  },
  AvgDialog_18711_Content_17 = {
    Text = "Wirst du mit mir kommen, kleines Biest? Du brauchst Hilfe."
  },
  AvgDialog_18711_Content_18 = {
    Text = "Jahr 15@1 Im Sommer des ersten Jahres reichte mir eine Frau die Hand."
  },
  AvgDialog_18711_Content_19 = {
    Text = "Vielleicht ist es ihr angenehmer Duft, oder vielleicht wirkt sie einfach sanft."
  },
  AvgDialog_18711_Content_2 = {
    Text = "Eine Masse Fleisch kollabiert, gießt D-Schlamm und grauen Schleim aus und enthüllt Harriet's schwaches Körper."
  },
  AvgDialog_18711_Content_20 = {
    Text = "Kurz gesagt, ich habe sie nicht abgelehnt."
  },
  AvgDialog_18711_Content_21 = {
    Text = "Ich ergriff naiv ihre Hand und mit ihr, mein zukünftiges Schicksal."
  },
  AvgDialog_18711_Content_22 = {
    Text = "Husten... Husten..."
  },
  AvgDialog_18711_Content_23 = {
    Text = "Du stirbst, Narzisse."
  },
  AvgDialog_18711_Content_24 = {
    Text = "Dummes Kind... Nach all diesen Jahren hast du immer noch nicht gelernt, richtig zu sprechen."
  },
  AvgDialog_18711_Content_25 = {
    Text = "Weine nicht... *hust*..."
  },
  AvgDialog_18711_Content_26 = {
    Text = "<Shake:Ich... ich habe nicht...>"
  },
  AvgDialog_18711_Content_27 = {
    Text = "Nehmt meinen Kopf. Ich vertraue euch meine Identität, mein Aussehen und dieses kleine Geschäft an."
  },
  AvgDialog_18711_Content_28 = {Text = "?!"},
  AvgDialog_18711_Content_29 = {
    Text = "Ich weiß, husten husten... du hast immer danach gesehnt, wie ein gewöhnlicher Mensch die Welt zu bereisen."
  },
  AvgDialog_18711_Content_3 = {
    Text = "Grau-weiße Schädel strömten hervor, nur um im Augenblick zu verschwinden."
  },
  AvgDialog_18711_Content_30 = {
    Text = "Du versteckst dich in der Ecke und beobachtest, wie ich rede und gehe. Wenn ich weg bin, ziehst du heimlich meine Kleidung an und tust sogar so, als wärst du ich, um Freunde zu finden..."
  },
  AvgDialog_18711_Content_31 = {
    Text = "Ich wusste es immer."
  },
  AvgDialog_18711_Content_32 = {
    Text = "Es tut mir leid, Narzisse, ich wollte nicht..."
  },
  AvgDialog_18711_Content_33 = {
    Text = "Jetzt werde ich dir deinen Wunsch erfüllen, hmmm... aber du musst mir versprechen..."
  },
  AvgDialog_18711_Content_34 = {
    Text = "In der Zukunft hacke nicht leichtfertig die Köpfe der Unschuldigen ab. Wenn du jemandem begegnest, der wie du ist, musst du ihm helfen."
  },
  AvgDialog_18711_Content_35 = {
    Text = "So wie ich dir jetzt helfe."
  },
  AvgDialog_18711_Content_36 = {
    Text = "<Shake:Rette mich, rette mich...>"
  },
  AvgDialog_18711_Content_37 = {
    Text = "Harriet stößt einen tierähnlichen Schrei aus und streckt zitternd ihre Hand nach Lady Narzisse aus."
  },
  AvgDialog_18711_Content_38 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18711_Content_39 = {
    Text = "Damals... als du deinen Ehemann auf dem Friedhof gesehen hast, musstest du dich völlig hoffnungslos gefühlt haben, oder?"
  },
  AvgDialog_18711_Content_4 = {
    Text = "Kopf@1 Nein..."
  },
  AvgDialog_18711_Content_40 = {
    Text = "Freeman... Huh.@2..."
  },
  AvgDialog_18711_Content_41 = {
    Text = "Wir tragen den gleichen Fluch, aber ich bin viel glücklicher als du."
  },
  AvgDialog_18711_Content_42 = {
    Text = "Als ich noch nicht den Unterschied zwischen Gut und Böse kannte, war es diese Dame, die mir die Hand entgegenstreckte."
  },
  AvgDialog_18711_Content_43 = {
    Text = "Die Narzisse kniete sich vor Mrs. Harriet, sanft ihre vernarbte und mit D-Slime bedeckte Hand haltend."
  },
  AvgDialog_18711_Content_44 = {
    Text = "Ich habe gelernt, wie sie zu sprechen und zu gehen, mich in ihr Bild zu formen."
  },
  AvgDialog_18711_Content_45 = {
    Text = "Vorsicht, Narzisse Dame! Harriets Hände sind mit D-Schleim bedeckt—"
  },
  AvgDialog_18711_Content_46 = {
    Text = "Shh... Ich habe ihr noch etwas zu sagen."
  },
  AvgDialog_18711_Content_47 = {
    Text = "Die Narzisse blickte weiterhin auf Harriet. Eine geheime Verbindung floss zwischen ihnen und schloss sie von allen Ablenkungen aus."
  },
  AvgDialog_18711_Content_48 = {
    Text = "Jetzt kann ich endlich zu anderen greifen, genau wie sie es tat... Aber es ist zu spät."
  },
  AvgDialog_18711_Content_49 = {
    Text = "Pale lila Rauch steigt allmählich auf und driftet langsam im düsteren Raum."
  },
  AvgDialog_18711_Content_5 = {
    Text = "Harriet, kopflos und unruhig, wand sich, während die Venen in ihrem Hals schnell pulsierten und ein leises Summen erzeugten."
  },
  AvgDialog_18711_Content_50 = {
    Text = "Du riechst diesen vertrauten Blumenduft erneut, vermischt mit der Feuchtigkeit des Mitternachtsnebels, der den schweren Blutgeruch im Raum verdünnt."
  },
  AvgDialog_18711_Content_51 = {
    Text = "Die Narzisse legte sanft ihre Hand neben Mrs. Harriet."
  },
  AvgDialog_18711_Content_52 = {
    Text = "Sei unbesorgt, Lady Harriet. Du wirst keinen Schmerz empfinden."
  },
  AvgDialog_18711_Content_53 = {
    Text = "Ein Riss öffnet sich schnell aus ihrer Handfläche und verschlingt langsam Harriet..."
  },
  AvgDialog_18711_Content_54 = {
    Text = "<Shake:...>"
  },
  AvgDialog_18711_Content_55 = {
    Text = "Sag meinem Mann@2, er soll aufhören zu trinken."
  },
  AvgDialog_18711_Content_56 = {
    Text = "Es gibt mehr..."
  },
  AvgDialog_18711_Content_57 = {
    Text = "Harriets exponierte Kehle zitterte leicht, fiel aber schließlich still wie ein verwelktes Blatt."
  },
  AvgDialog_18711_Content_58 = {
    Text = "Sie ließ Daffodils Hand los und stürzte lautlos in einen unfassbaren dimensionalen Riss."
  },
  AvgDialog_18711_Content_59 = {
    Text = "<Change> Lebewohl, lebewohl..."
  },
  AvgDialog_18711_Content_6 = {
    Text = "Gib mir@2 Köpfe, gib mir..."
  },
  AvgDialog_18711_Content_60 = {
    Text = "Endlich... Ist es vorbei? Wohin hast du sie gebracht, Gänseblümchen-Dame?"
  },
  AvgDialog_18711_Content_61 = {
    Text = "Der Ur-Ozean. Sie wird lange Zeit haben, um sich daran zu erinnern... oder alles zu vergessen, was passiert ist."
  },
  AvgDialog_18711_Content_62 = {
    Text = "Lady Harriet..."
  },
  AvgDialog_18711_Content_63 = {
    Text = "Bevor du deine verstreuten Gedanken sammeln kannst, hallen gedämpfte Schritte draußen vor dem Haus."
  },
  AvgDialog_18711_Content_64 = {
    Text = "Wer ist da? Lass uns folgen und nachsehen."
  },
  AvgDialog_18711_Content_65 = {
    Text = "Ja, das bin ich... hic."
  },
  AvgDialog_18711_Content_66 = {
    Text = "Lange nicht gesehen, kleiner Detektiv! Erinnerst du dich an mich, den Totengräber alter Freeman?"
  },
  AvgDialog_18711_Content_67 = {
    Text = "Der alte Freeman, der eine Flasche Cognac hielt, rülpste ununterbrochen mit einem unbeholfenen Lächeln im Gesicht."
  },
  AvgDialog_18711_Content_68 = {
    Text = "Der alte Freeman?! Was machen Sie hier... Haben Sie alles gehört?"
  },
  AvgDialog_18711_Content_69 = {Text = "Ich..."},
  AvgDialog_18711_Content_7 = {
    Text = "Sie kroch ängstlich über den Boden, ihre knochigen Arme fuchtelten herum. Wie ein in die Ecke gedrängtes Biest stieß sie verzweifelte Geräusche aus ihrer Kehle aus."
  },
  AvgDialog_18711_Content_70 = {
    Text = "Ich weiß auch nicht, was passiert ist. Ich habe nach dem Trinken geschlafen wie ein Stein."
  },
  AvgDialog_18711_Content_71 = {
    Text = "Ich kann mich nicht erinnern, was in der Mitte passiert ist, aber irgendwie bin ich hier in einem Dämmerzustand gelandet."
  },
  AvgDialog_18711_Content_72 = {
    Text = "Dann hörte ich ein Geräusch drinnen... Mach dir keine Sorgen, ich habe nicht einmal einen Blick geworfen!"
  },
  AvgDialog_18711_Content_73 = {
    Text = "Der alte Freeman beugte sich plötzlich vor und machte Ihnen ein geheimnisvolles Augen zwinkern.\nSie haben sich nicht rechtzeitig geduckt und bekamen einen starken Geruch von Rauch und Alkohol zu schnüffeln."
  },
  AvgDialog_18711_Content_74 = {
    Text = "Du hast diesen Schädeljäger getötet, richtig?"
  },
  AvgDialog_18711_Content_75 = {
    Text = "Nicht großartig, aber nah genug. Niemand wird deinen Schlaf von jetzt an stören."
  },
  AvgDialog_18711_Content_76 = {
    Text = "Du kneifst dir die Nase zu, trittst drei Schritte zurück und nickst hektisch."
  },
  AvgDialog_18711_Content_77 = {Text = "Oh..."},
  AvgDialog_18711_Content_78 = {
    Text = "Der alte Freeman rieb sich durch sein zerzaustes Haar, ein Hauch von Verwirrung blitzte in seinen Augen auf."
  },
  AvgDialog_18711_Content_79 = {
    Text = "Ziemlich gut, ziemlich gut..."
  },
  AvgDialog_18711_Content_8 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18711_Content_80 = {
    Text = "Herr Freeman. Von jetzt an... kein Alkohol mehr."
  },
  AvgDialog_18711_Content_81 = {
    Text = "Aufhören zu trinken? Nein, nein, nein... Ich würde lieber sterben."
  },
  AvgDialog_18711_Content_82 = {
    Text = "Dies ist eine Bitte von einer Freundin. Sie ist weit, weit weg gegangen... aber sie denkt immer noch an dich."
  },
  AvgDialog_18711_Content_83 = {
    Text = "Freunde? Hehe, mach dir nichts vor. Der alte Freeman hat keine Freunde..."
  },
  AvgDialog_18711_Content_84 = {
    Text = "Er winkte abfällig und murmelte, während er taumelnd wegging."
  },
  AvgDialog_18711_Content_85 = {
    Text = "Er sieht so niedergeschlagen aus. Was für eine Schmach...\nEr wird nie wissen, warum er sich so fühlt."
  },
  AvgDialog_18711_Content_86 = {
    Text = "Es ist, als ob er nicht versteht, warum er hier ist."
  },
  AvgDialog_18711_Content_87 = {
    Text = "Das muss das sein, was Frau Harriet sich erhofft hatte."
  },
  AvgDialog_18711_Content_88 = {
    Text = "Sag ihm nichts... Er kann so weitermachen mit Trinken, Singen und im Leben treiben."
  },
  AvgDialog_18711_Content_89 = {
    Text = "In gewisser Weise ist dies auch eine Art Glück. Das Leben eines Menschen ist sehr kurz..."
  },
  AvgDialog_18711_Content_9 = {
    Text = "Die Narzisse ließ einen leisen Seufzer aus und ihre Augen glitzerten vor unausgesprochener Traurigkeit."
  },
  AvgDialog_18711_Content_90 = {
    Text = "Du siehst Old Freeman gehen."
  },
  AvgDialog_18711_Content_91 = {
    Text = "Eine gebeugte Gestalt zitterte im tristen Wind, wurde immer kleiner und kleiner, immer weiter entfernt..."
  },
  AvgDialog_18711_Content_92 = {
    Text = "Bis vollständig vom fernen Horizont verschlungen."
  },
  AvgDialog_18711_Content_93 = {
    Text = "Dann siehst du einen schwachen Lichtstrahl der Dämmerung, der durch den Nebel bricht und allmählich den Himmel erhellt."
  },
  AvgDialog_18711_Content_94 = {
    Text = "Der Regen hat aufgehört... Narzisse."
  },
  AvgDialog_18712_Content_1 = {
    Text = "Schattenhymne"
  },
  AvgDialog_18712_Content_10 = {
    Text = "Gib es mir... <Big:Rückkehr es zu mir>!"
  },
  AvgDialog_18712_Content_11 = {
    Text = "Schwarze Tentakel strecken sich ständig von seinem Hals aus und saugen gierig die gefallenen Köpfe in seinen Körper auf."
  },
  AvgDialog_18712_Content_12 = {
    Text = "Mit jedem Schädel, den es verschlingt, wächst seine Größe weiter."
  },
  AvgDialog_18712_Content_13 = {
    Text = "Das Letzte, was dir gegenübersteht, ist ein riesiger Haufen gestapelten Fleisches."
  },
  AvgDialog_18712_Content_14 = {
    Text = "<Bold:—!!!>"
  },
  AvgDialog_18712_Content_15 = {
    Text = "Diese Köpfe... Ich habe sie schon einmal gesehen."
  },
  AvgDialog_18712_Content_16 = {
    Text = "Du hast einige von ihnen in den Unterlagen gesehen, die dir die Polizei gegeben hat, in den kalten, aufgereihten Opferfotos."
  },
  AvgDialog_18712_Content_17 = {
    Text = "Du hast sie gesehen."
  },
  AvgDialog_18712_Content_18 = {
    Text = "Jetzt verstehst du, dass es niemals eine Skull Hunters-Organisation gegeben hat."
  },
  AvgDialog_18712_Content_19 = {
    Text = "<Yellow:Von Anfang bis Ende war der Schädeljäger immer allein.>"
  },
  AvgDialog_18712_Content_2 = {
    Text = "Lady Daffodil...?!"
  },
  AvgDialog_18712_Content_20 = {
    Text = "<RedShake: Nicht genug...>"
  },
  AvgDialog_18712_Content_21 = {
    Text = "<RedShake: Nicht genug... nicht genug...>"
  },
  AvgDialog_18712_Content_22 = {
    Text = "Ein geschwollenes Wesen, durchsetzt von zahllosen Köpfen, die Schmerz und Wehklagen ausdrücken, steigt und fällt mit dem weichen Fett..."
  },
  AvgDialog_18712_Content_23 = {
    Text = "So vertraute Geisterwellen... Könnte es die Tausend Illusionen sein?!"
  },
  AvgDialog_18712_Content_24 = {
    Text = "Es ist eine Kraft, die aus derselben Quelle wie die Tausend Illusionen stammt, weshalb ich ihren Standort spüren kann."
  },
  AvgDialog_18712_Content_25 = {
    Text = "Jetzt ist es völlig außer Kontrolle und wächst weiter.\nWir müssen schnell handeln."
  },
  AvgDialog_18712_Content_26 = {Text = "Also..."},
  AvgDialog_18712_Content_27 = {
    Text = "Daffodil lehnte sich plötzlich vor und griff nach dem Silbernen Schlüssel auf deiner Brust."
  },
  AvgDialog_18712_Content_28 = {
    Text = "Möchtest du mit mir, %player%, ein Team bilden?"
  },
  AvgDialog_18712_Content_29 = {
    Text = "Oh, möchtest du mit mir Link herstellen?"
  },
  AvgDialog_18712_Content_3 = {
    Text = "Entschuldigung... Ich habe dich absichtlich hier gelassen, um es herauszulocken. Du musst mich, denkst du nicht, innerlich beschuldigen, oder?"
  },
  AvgDialog_18712_Content_30 = {
    Text = "Nach all dieser Zeit, die wir zusammengearbeitet haben, dachte ich, wir hätten mittlerweile ein gewisses Verständnis erreicht"
  },
  AvgDialog_18712_Content_31 = {
    Text = "Oder... bist du dir nicht sicher, dass du mit mir umgehen kannst?"
  },
  AvgDialog_18712_Content_32 = {
    Text = "Heh... Wollen wir es versuchen?"
  },
  AvgDialog_18712_Content_33 = {
    Text = "Du schließt deine Augen und konzentrierst dich und forderst den Silbernen Schlüssel auf deiner Brust."
  },
  AvgDialog_18712_Content_34 = {
    Text = "Bald beginnt der silberne Schlüssel, eine kontinuierliche, schwache Vibration auszusenden, und der kalte weiße Glanz umhüllt schnell den gesamten dunklen Raum."
  },
  AvgDialog_18712_Content_35 = {
    Text = "Du fühlst, als ob du in einem gewaltigen Meer der Zeit bist."
  },
  AvgDialog_18712_Content_36 = {
    Text = "Seltsame Energie strömt in deiner Brust, ein Sturm, der Dimensionen überquert."
  },
  AvgDialog_18712_Content_37 = {
    Text = "Über das weite Meer der Zeit blickt die Narzisse still auf dich.\nIn diesem Moment erscheint ein subtiler und unbekannter Ausdruck in ihrem Gesicht."
  },
  AvgDialog_18712_Content_38 = {
    Text = "Das ist ein absolutes, unbestreitbares Vertrauen, das über Hunderte von Jahren durch unzählige Konfrontationen und Kämpfe geschliffen wurde."
  },
  AvgDialog_18712_Content_39 = {
    Text = "Lass uns aufbrechen, %player%. Ich bin ganz bereit."
  },
  AvgDialog_18712_Content_4 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18712_Content_5 = {
    Text = "Wir werden das klären, sobald wir draußen sind."
  },
  AvgDialog_18712_Content_6 = {
    Text = "<Shake:Mein Kopf... Gib ihn zurück...>"
  },
  AvgDialog_18712_Content_7 = {
    Text = "„Harriet“ taumelte zwei Schritte nach vorne und griff vergeblich über ihren Hals."
  },
  AvgDialog_18712_Content_8 = {
    Text = "Ein Treffer, zwei Treffer..."
  },
  AvgDialog_18712_Content_9 = {
    Text = "Als sie sich bewusst wurde, dass ihr Kopf bereits verschwunden war, stieß sie eine Reihe durchdringender Schreie aus."
  },
  AvgDialog_18713_Content_1 = {Text = "Es regnet."},
  AvgDialog_18713_Content_10 = {
    Text = "Du wischt hastig den Regen von deinem Gesicht und blinzelst, nur um festzustellen, dass tatsächlich jemand mit dir spricht."
  },
  AvgDialog_18713_Content_11 = {
    Text = "Ich dachte, hier wohnt niemand mehr."
  },
  AvgDialog_18713_Content_12 = {
    Text = "Die meisten Menschen sind weggezogen."
  },
  AvgDialog_18713_Content_13 = {
    Text = "Diejenigen, die krank oder alt waren, entschieden sich zu bleiben, während einige nach draußen gingen und dann zurückkamen..."
  },
  AvgDialog_18713_Content_14 = {
    Text = "Nicht jeder kann sich an das Leben draußen anpassen."
  },
  AvgDialog_18713_Content_15 = {
    Text = "Ich verstehe. Aber ich habe gerade niemanden gesehen."
  },
  AvgDialog_18713_Content_16 = {
    Text = "...Sie hassen es, mit Außenstehenden umzugehen."
  },
  AvgDialog_18713_Content_17 = {
    Text = "Du schaust dich um und siehst die spärlichen, heruntergekommenen Häuser."
  },
  AvgDialog_18713_Content_18 = {
    Text = "Durch die pechschwarzen Fenster konnten leise Blicke schwach wahrgenommen werden, die voller Vorsicht und Feindseligkeit waren."
  },
  AvgDialog_18713_Content_19 = {
    Text = "Hallo, meine Dame. Darf ich Sie fragen—"
  },
  AvgDialog_18713_Content_2 = {
    Text = "Du gehst allein im Regen, kaltes, nasses Wasser durchtränkt deine Kleidung und haftet an deiner Haut."
  },
  AvgDialog_18713_Content_20 = {
    Text = "Hast du etwas Seltsames gesehen?"
  },
  AvgDialog_18713_Content_21 = {
    Text = "Seltsame Dinge...?"
  },
  AvgDialog_18713_Content_22 = {
    Text = "Ähm... ob es eine Person oder ein Tier ist, es bewegt sich extrem schnell."
  },
  AvgDialog_18713_Content_23 = {
    Text = "Die Frau schüttelte den Kopf."
  },
  AvgDialog_18713_Content_24 = {
    Text = "Es ist lange her, dass hier jemand gekommen ist; selbst die Geier weigern sich, sich zu nähern."
  },
  AvgDialog_18713_Content_25 = {
    Text = "Hast du die Narzisse gesehen?"
  },
  AvgDialog_18713_Content_26 = {
    Text = "Hast du eine schöne Dame in einem lila langen Kleid gesehen?"
  },
  AvgDialog_18713_Content_27 = {
    Text = "Die Frau schüttelte den Kopf."
  },
  AvgDialog_18713_Content_28 = {
    Text = "Es ist lange her, dass hier jemand gekommen ist; selbst die Geier weigern sich, sich zu nähern."
  },
  AvgDialog_18713_Content_29 = {
    Text = "<Big:Boom—>"
  },
  AvgDialog_18713_Content_3 = {
    Text = "Du wandelst von einem verlassenen Haus zum nächsten und gehst an einem Grab nach dem anderen vorbei."
  },
  AvgDialog_18713_Content_30 = {
    Text = "Der Regen fällt härter und verwandelt alles in Grau."
  },
  AvgDialog_18713_Content_31 = {
    Text = "Die Figur der Frau beginnt unscharf zu werden und an Fokus zu verlieren, und selbst ihre Stimme wird zunehmend leiser..."
  },
  AvgDialog_18713_Content_32 = {
    Text = "Komm herein, {Male=sir,Female=miss}. Bei diesem starken Regen holst du dir noch eine Erkältung..."
  },
  AvgDialog_18713_Content_33 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18713_Content_34 = {
    Text = "Mit Vergnügen."
  },
  AvgDialog_18713_Content_4 = {
    Text = "Wo auch immer sie hingehen, gibt es nur Narben und Verwüstung."
  },
  AvgDialog_18713_Content_5 = {
    Text = "Nur Regen. Unaufhörlicher, kalter Regen begleitet dich den ganzen Weg."
  },
  AvgDialog_18713_Content_6 = {
    Text = "{Male=Herr,Female=Frau}..."
  },
  AvgDialog_18713_Content_7 = {
    Text = "Eine alte Frau steht vor der Hütte und winkt dir zu."
  },
  AvgDialog_18713_Content_8 = {
    Text = "Sie trug ein mattes Kleid, ihr Gesicht verborgen im grauen Regen, nahtlos mit dem baufälligen Haus hinter ihr verschmolzen."
  },
  AvgDialog_18713_Content_9 = {
    Text = "{Male=Sir,Female=Miss}, du siehst sehr durchgefroren aus... Möchtest du hereinkommen und dich setzen?"
  },
  AvgDialog_18714_Content_1 = {Text = "Sturmbruch"},
  AvgDialog_18714_Content_10 = {
    Text = "Eine einzelne Person?!"
  },
  AvgDialog_18714_Content_11 = {
    Text = "Oh mein Gott, du siehst schrecklich aus. Brauchst du Hilfe?"
  },
  AvgDialog_18714_Content_12 = {
    Text = "Du trittst zurück. Ich habe etwas, das ich dich fragen möchte."
  },
  AvgDialog_18714_Content_13 = {
    Text = "Das ist wirklich verletzend. Was, strahle ich irgendeinen unangenehmen Geruch aus?"
  },
  AvgDialog_18714_Content_14 = {
    Text = "Ich weiß nicht... Vielleicht der Geruch der Toten?"
  },
  AvgDialog_18714_Content_15 = {
    Text = "Beren Stock, Dwight Williams... Kommen Ihnen diese Namen bekannt vor?"
  },
  AvgDialog_18714_Content_16 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18714_Content_17 = {
    Text = "Ich verstehe, du verdächtigst mich, der Skull Hunter zu sein."
  },
  AvgDialog_18714_Content_18 = {
    Text = "Und du kennst die Namen der Opfer des Skull Jägers eindeutig."
  },
  AvgDialog_18714_Content_19 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18714_Content_2 = {
    Text = "Daffodil schlenderte mit einem Hauch von lässiger Eleganz auf dich zu, als wäre sie hier im Urlaub."
  },
  AvgDialog_18714_Content_20 = {
    Text = "Ich dachte, dass wir durch die Zeit, die wir mit Lai verbringen, ein wenig Vertrauen aufbauen könnten."
  },
  AvgDialog_18714_Content_21 = {
    Text = "Der Totenschädel-Jäger hat mir ein <Yellow:wertvoller Schädel> genommen, also führe ich nur eine kleine Untersuchung durch. So einfach ist das."
  },
  AvgDialog_18714_Content_22 = {
    Text = "Wessen kostbarer Kopf... könnte das sein?"
  },
  AvgDialog_18714_Content_23 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18714_Content_24 = {
    Text = "Daffodil lächelt dich an. Sie trägt immer dieses Lächeln, wenn sie nicht auf die Fragen anderer antworten möchte."
  },
  AvgDialog_18714_Content_25 = {
    Text = "Wenn ich mich richtig erinnere, hattest du schon immer die Angewohnheit, Köpfe zu sammeln. Renny ist weniger als 15 Meilen von Rai in gerader Linie entfernt, was die Hin- und Rückfahrt ziemlich praktisch macht."
  },
  AvgDialog_18714_Content_26 = {
    Text = "Entschuldigung, ich sammle nur Köpfe, ich produziere sie nicht."
  },
  AvgDialog_18714_Content_27 = {
    Text = "Es gibt einen feinen Unterschied zwischen beidem... Ich bin sicher, du kannst das verstehen, unser kluger Schutzherr?"
  },
  AvgDialog_18714_Content_28 = {
    Text = [[
Na sicher, ich verstehe.
Also, wo warst du und was hast du um 8:15 Uhr gestern Abend getan?]]
  },
  AvgDialog_18714_Content_29 = {
    Text = "Lasst mich nachdenken... Der Laden hat eine neue Charge Badesalze erhalten, also habe ich sie in der Badewanne ausprobiert."
  },
  AvgDialog_18714_Content_3 = {
    Text = "Es bist du...?"
  },
  AvgDialog_18714_Content_30 = {
    Text = "Nun, willst du die Details meines Prozesses hören?"
  },
  AvgDialog_18714_Content_31 = {
    Text = "Ist das so? Aber als ich dich letzte Nacht sah, standest du alleine unter dem Straßenlaterne, mit einem menschlichen Kopf in der Hand."
  },
  AvgDialog_18714_Content_32 = {
    Text = "Es sieht überhaupt nicht nach Badesalz aus."
  },
  AvgDialog_18714_Content_33 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18714_Content_34 = {
    Text = "Sagst du... du hast letzte Nacht jemanden gesehen, der genau wie ich aussieht?"
  },
  AvgDialog_18714_Content_35 = {
    Text = "Du erinnerst dich, dass du die Narzisse letzte Nacht gesehen hast."
  },
  AvgDialog_18714_Content_36 = {
    Text = "Kein Zweifel, ihr Aussehen ist fast identisch, aber ihr Benehmen und ihre Aura sind völlig unterschiedlich."
  },
  AvgDialog_18714_Content_37 = {
    Text = "Oder vielmehr sah ich <Yellow:du>, nicht jemanden, der dir genau ähnlich sieht."
  },
  AvgDialog_18714_Content_38 = {
    Text = "Alle ungünstigen Beweise deuten nun auf dich hin, und ich habe jeden Grund, dich zu verdächtigen."
  },
  AvgDialog_18714_Content_39 = {
    Text = "Hmm, dein Verdacht ist in der Tat gut fundiert."
  },
  AvgDialog_18714_Content_4 = {
    Text = "Oh mein Gott, scheint es, als ob jemand mich nicht sehen möchte?"
  },
  AvgDialog_18714_Content_40 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18714_Content_41 = {
    Text = "Hast du nichts zu erklären?"
  },
  AvgDialog_18714_Content_42 = {
    Text = "Die Narzisse blickte dich überrascht an, als hättest du eine lächerliche Frage gestellt."
  },
  AvgDialog_18714_Content_43 = {
    Text = "Erklären? Entschuldigung, ich muss niemandem etwas erklären."
  },
  AvgDialog_18714_Content_44 = {
    Text = "Sie geht anmutig auf dich zu."
  },
  AvgDialog_18714_Content_45 = {
    Text = "Der weite Rock raschelt durch die toten Blätter, während lila Rauch wie Ranken umherwirbelt."
  },
  AvgDialog_18714_Content_46 = {
    Text = "Im nächsten Moment verschwand sie direkt vor deinen Augen in Luft."
  },
  AvgDialog_18714_Content_47 = {
    Text = "Die tiefhängenden Wolken blockieren vollständig das Sonnenlicht und lassen dich fühlen, als wärst du in einem grauen Traum, während Daffodils Flüstern in deinen Ohren verweilt—"
  },
  AvgDialog_18714_Content_48 = {
    Text = "Da du denkst, ich sei der \"Schädeljäger\"... was kommt als Nächstes? Was hast du vor, mit mir zu tun?"
  },
  AvgDialog_18714_Content_49 = {
    Text = "Oder vielmehr... was kannst du mir antun?"
  },
  AvgDialog_18714_Content_5 = {
    Text = "Der öde Herbstwind weht von hinten. Du drehst dich um, aber vor dir ist nichts; Old Freeman ist längst verschwunden."
  },
  AvgDialog_18714_Content_6 = {
    Text = "Wenn ich an alles zurückdenke, was gerade passiert ist, war es wie ein Albtraum."
  },
  AvgDialog_18714_Content_7 = {
    Text = "Herr Freeman...?"
  },
  AvgDialog_18714_Content_8 = {
    Text = "Hmm, du hast einen Begleiter mitgebracht? Ist es das Mädchen, das immer so ernst aussieht?"
  },
  AvgDialog_18714_Content_9 = {
    Text = "Gerade standest du hier alleine, völlig still, als ob besessen."
  },
  AvgDialog_18715_Content_1 = {
    Text = "Ich gebe auf, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_18715_Content_10 = {
    Text = "Du tauchst in ein Meer aus grauer Ur-Substanz ein."
  },
  AvgDialog_18715_Content_11 = {
    Text = "Das Tageslicht sticht in deine Augen und enthüllt einen endlosen grauen Ozean."
  },
  AvgDialog_18715_Content_12 = {
    Text = "Die aufwallenden grauen Wellen schimmern mit glitzerndem Licht, durchzogen von unzähligen schwarzen Punkten."
  },
  AvgDialog_18715_Content_13 = {
    Text = "Als sich dein Blick allmählich anpasst, erkennst du, dass es kein schwarzer Fleck ist, sondern nur ein Schädel."
  },
  AvgDialog_18715_Content_14 = {
    Text = "Zahlreiche Köpfe sind im grauen Meer untergetaucht und steigen und fallen mit den Wellen. Sie schreien und klagen, ertrinken in immensem Kummer und Angst."
  },
  AvgDialog_18715_Content_15 = {
    Text = "<Change>Kristalle, Kristalle..."
  },
  AvgDialog_18715_Content_16 = {
    Text = "<Shake:Berühre dieses Heftchen nicht, berühre es nicht...>"
  },
  AvgDialog_18715_Content_17 = {
    Text = "<Shake:San Pedro, lass mich zurückkehren, lass mich zurückkehren...>"
  },
  AvgDialog_18715_Content_18 = {
    Text = "Zahlreiche Stimmen schreien dir ins Ohr und zwingen dich, sie zu bedecken, als ob Tausende von Nadeln deinen Geist durchbohren würden."
  },
  AvgDialog_18715_Content_19 = {
    Text = "Hmm... <Big: Aaah...!!>"
  },
  AvgDialog_18715_Content_2 = {
    Text = "Da ich es nicht ertragen kann, dich verletzt zu sehen, wäre es nur Zeitverschwendung, diesen Kampf fortzusetzen."
  },
  AvgDialog_18715_Content_20 = {
    Text = "Warmes Blut fließt aus deinen Ohren und Nasenlöchern und erzeugt massive Wellen, sobald es das Wasser berührt."
  },
  AvgDialog_18715_Content_21 = {
    Text = "Die Flut tobt vor Wut und Angst, trägt unzählige Köpfe, die auf ihren Wellen wogen, und stürzt auf dich zu."
  },
  AvgDialog_18715_Content_22 = {
    Text = "<Change>Nein, nein..."
  },
  AvgDialog_18715_Content_23 = {
    Text = "<Shake:Eindringlinge... Eindringlinge!!>"
  },
  AvgDialog_18715_Content_24 = {
    Text = "Du hast keinen Ausweg. Schließe einfach die Augen."
  },
  AvgDialog_18715_Content_25 = {Text = "Hmm...!"},
  AvgDialog_18715_Content_26 = {
    Text = "Husten... Husten..."
  },
  AvgDialog_18715_Content_27 = {
    Text = "Die Narzisse hielt sich die Stirn und runzelte die Stirn in deine Richtung."
  },
  AvgDialog_18715_Content_28 = {
    Text = "So bald raus...? Ich dachte, ich könnte dich mindestens einen ganzen Tag festhalten."
  },
  AvgDialog_18715_Content_29 = {
    Text = "Es scheint, dass wir dazu bestimmt sind, miteinander verbunden zu sein, nicht wahr?"
  },
  AvgDialog_18715_Content_3 = {
    Text = "Angesichts der unversöhnlichen Unterschiede zwischen uns schlage ich vor, dass du aufhörst, mich zu belästigen."
  },
  AvgDialog_18715_Content_30 = {
    Text = "Kopf... es tut weh..."
  },
  AvgDialog_18715_Content_31 = {
    Text = "Was war das gerade eben...? Was für ein Ding war das...?"
  },
  AvgDialog_18715_Content_32 = {
    Text = [[
Das ist mein ultra-dimensionaler Raum. Ich habe ihn <Yellow:Thousand Mirage> genannt.
Was denkst du? Ist es nicht faszinierend?]]
  },
  AvgDialog_18715_Content_33 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18715_Content_34 = {
    Text = "%player%, du hast Nasenbluten. Warte, sogar deine Ohren bluten..."
  },
  AvgDialog_18715_Content_35 = {
    Text = "<Shake:Es geht mir gut... Halt dich fern...>"
  },
  AvgDialog_18715_Content_36 = {
    Text = "Es ist nicht weise, sich jetzt tough zu verhalten; du kannst kaum stehen."
  },
  AvgDialog_18715_Content_37 = {
    Text = "*Hust hust*... komm nicht näher..."
  },
  AvgDialog_18715_Content_38 = {
    Text = "Deine Sicht wird schwarz, und du fällst schwer zu Boden."
  },
  AvgDialog_18715_Content_39 = {
    Text = "In der Dunkelheit scheint es, als hörst du eine vertraute Stimme."
  },
  AvgDialog_18715_Content_4 = {
    Text = "Daffodil, mit kaltem Ausdruck, zeichnete schnell eine Reihe leuchtender lila Runen in die Luft."
  },
  AvgDialog_18715_Content_40 = {
    Text = "Sanft, gleichgültig, eingehüllt in ein leicht raues elektrisches Summen, das entfernt und vage erscheint."
  },
  AvgDialog_18715_Content_41 = {
    Text = "%player%, kannst du mich jetzt hören...<Red:Falsche Untersuchungsrichtung>..."
  },
  AvgDialog_18715_Content_42 = {
    Text = "Der Totenschädel-Jäger schlägt wieder zu...\nDrei Opfer, alle mit ihren Köpfen genommen..."
  },
  AvgDialog_18715_Content_43 = {
    Text = "Gerade eben..."
  },
  AvgDialog_18715_Content_5 = {
    Text = "<Change>Tauchtausend, aktiviere."
  },
  AvgDialog_18715_Content_6 = {
    Text = "Die Welt vor deinen Augen verwandelt sich plötzlich in fragmentierte Spiegelungen im Wasser, die sanft vor dir flackern."
  },
  AvgDialog_18715_Content_7 = {
    Text = "Du greifst instinktiv nach vorne, wirst aber im Moment, in dem du die Schattenfragmente berührst, in einen tiefen Strudel gezogen."
  },
  AvgDialog_18715_Content_8 = {Text = "Aaaah...!!"},
  AvgDialog_18715_Content_9 = {Text = "Das ist..."},
  AvgDialog_18716_Content_1 = {Text = "Aaahh—!!"},
  AvgDialog_18716_Content_10 = {
    Text = "Die Fäden zogen sich plötzlich zusammen und zerschmetterten die Schlafzimmer Tür, während unzählige Köpfe herausrollten."
  },
  AvgDialog_18716_Content_11 = {
    Text = "Als du zu dir kommst, ist bereits ein dir etwas vertrauter Kopf an Harriets leerem Hals befestigt."
  },
  AvgDialog_18716_Content_12 = {
    Text = "Dieser Kopf... Dieses Gesicht..."
  },
  AvgDialog_18716_Content_13 = {
    Text = "Beren Stock, das frühere Opfer... Was geht hier vor?!"
  },
  AvgDialog_18716_Content_14 = {
    Text = "Der bleiche Schädel gibt ein steifes Knarren von sich und öffnet schließlich seine unfokussierten Augen."
  },
  AvgDialog_18716_Content_15 = {
    Text = "Die wiedergeborene \"Harriet\" grinst und stürzt mit unglaublicher Geschwindigkeit auf dich zu."
  },
  AvgDialog_18716_Content_16 = {
    Text = "Aaaahhh—!!"
  },
  AvgDialog_18716_Content_18 = {
    Text = "Die kalte Klinge schneidet gnadenlos durch die Dunkelheit."
  },
  AvgDialog_18716_Content_19 = {
    Text = "Im nächsten Moment flog \"Harriets\" Kopf anmutig davon und rollte neben ihrem weiten Rock."
  },
  AvgDialog_18716_Content_2 = {
    Text = "Harriet fiel zu Boden und ließ einen durchdringenden Schrei aus tiefster Kehle ertönen."
  },
  AvgDialog_18716_Content_20 = {
    Text = "Puh... Es scheint, dass ich nicht zu spät bin."
  },
  AvgDialog_18716_Content_21 = {
    Text = "Du siehst geistig frisch aus, %player%."
  },
  AvgDialog_18716_Content_3 = {
    Text = "Du trittst vor und packst sie am Kragen."
  },
  AvgDialog_18716_Content_4 = {
    Text = "Sprich, wer sind deine Komplizen und wo sind sie? Ist Old Freeman einer von ihnen?"
  },
  AvgDialog_18716_Content_5 = {
    Text = "Freeman...? Heh... Hehehe..."
  },
  AvgDialog_18716_Content_6 = {
    Text = "Ihr Gesicht verzog sich gewaltsam, mit unzähligen Pusteln, die unter ihrer dünnen Haut anschwollen und kurz davor waren, hervorzuplatzen."
  },
  AvgDialog_18716_Content_7 = {
    Text = "Zzzzap—!!"
  },
  AvgDialog_18716_Content_8 = {
    Text = "Harriets Kopf wurde in eine warme Brei verwandelt."
  },
  AvgDialog_18716_Content_9 = {
    Text = "Ihr Hals wühlte sich unentwegt, während D-Schleim mit Blut vermischt dünne Fäden bildete, die sich bis zur Decke, zu den Wänden und zum Boden erstreckten..."
  },
  AvgDialog_18717_Content_1 = {Text = "Felin Muse"},
  AvgDialog_18717_Content_10 = {
    Text = "Das war eine ziemlich interessante Erfahrung."
  },
  AvgDialog_18717_Content_11 = {
    Text = "Die ursprünglich traurigen Erinnerungen, durch Bilder neu interpretiert, erhielten unerwartet einen komödiantischen Charme."
  },
  AvgDialog_18717_Content_12 = {
    Text = "Ich habe gehört, dass du später einen Filmclub namens <Yellow:\"Philin Poesiegesellschaft\"> gegründet hast?"
  },
  AvgDialog_18717_Content_13 = {
    Text = "Ja... Manchmal helfe ich beim Schreiben von Drehbüchern, obwohl ich immer ein schrecklicher Dramatiker war."
  },
  AvgDialog_18717_Content_14 = {
    Text = "Es war Lady Narzisse, die mir half, aus der Vergangenheit weiterzukommen, unabhängig von ihren wahren Absichten."
  },
  AvgDialog_18717_Content_15 = {
    Text = "Ich war Lady Narzisse immer dankbar."
  },
  AvgDialog_18717_Content_16 = {
    Text = "Ich sehe, das ist also, was sie dir gesagt hat."
  },
  AvgDialog_18717_Content_17 = {
    Text = "Ich bin auch Miss Horla zutiefst dankbar. Es war eine wunderschöne Begegnung."
  },
  AvgDialog_18717_Content_18 = {
    Text = "So, um der Miss Horla willen, werde ich dir dieses eine Mal vertrauen."
  },
  AvgDialog_18717_Content_19 = {
    Text = "<LightGray:Außerdem sind die von der Schule gesendeten Personen bereits unterwegs.>"
  },
  AvgDialog_18717_Content_2 = {
    Text = "2:15, Kenting Straße"
  },
  AvgDialog_18717_Content_20 = {
    Text = "<LightGray:Wenn ich zu lange weg bin, werden sie nicht einfach tatenlos zusehen...>"
  },
  AvgDialog_18717_Content_21 = {
    Text = "Dann lasst uns aufbrechen, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_18717_Content_22 = {
    Text = "Die Narzisse nickte glücklich und streckte ihre Hand zu dir aus."
  },
  AvgDialog_18717_Content_23 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18717_Content_24 = {
    Text = "Du hältst behutsam Daffodils Hand. Entgegen deiner Erwartungen ist ihre Hand weich und warm."
  },
  AvgDialog_18717_Content_25 = {
    Text = "Halte fest, Hüter."
  },
  AvgDialog_18717_Content_26 = {
    Text = "Dein Stand wankt, und du wirst in eine tiefe Dimension gezogen."
  },
  AvgDialog_18717_Content_27 = {
    Text = "Willkommen zurück in meiner \"Tausend Mirage.\""
  },
  AvgDialog_18717_Content_28 = {
    Text = "Hier ist wieder das vertraute Meer der Uressenz, mit Köpfen, die noch im Takt der Wellen nicken."
  },
  AvgDialog_18717_Content_29 = {
    Text = "Anders als beim letzten Mal scheinen die Köpfe jetzt viel ruhiger zu sein. Ihre hohlen Augenhöhlen wenden sich dir zu, während sie weiterhin untereinander flüstern."
  },
  AvgDialog_18717_Content_3 = {
    Text = "Ich habe nicht erwartet, dass du so bereitwillig mit mir kommst. Machst du dir keine Sorgen, dass ich dich irgendwohin bringen könnte, wo es seltsam ist?"
  },
  AvgDialog_18717_Content_30 = {
    Text = "Daffodil winkte leicht mit ihrer Hand, und zwei Köpfe zitterten, als sie auf ihre Augenhöhe schwebten."
  },
  AvgDialog_18717_Content_31 = {
    Text = "<Change>Mein Meister..."
  },
  AvgDialog_18717_Content_32 = {
    Text = "<Change> Lange nicht gesehen..."
  },
  AvgDialog_18717_Content_33 = {
    Text = "<Change>Hilf mir, jemanden zu finden..."
  },
  AvgDialog_18717_Content_34 = {
    Text = "Die Narzisse und der Totenschädel flüstern in einer Sprache, die du nicht verstehst. Was auch immer sie besprochen haben, es brachte sie zum fröhlichen Lachen."
  },
  AvgDialog_18717_Content_35 = {
    Text = "Du hast sie noch nie so lächeln sehen; es fühlt sich fehl am Platz an."
  },
  AvgDialog_18717_Content_36 = {
    Text = "Stattdessen durchquerte es Hunderte von Jahren und landete in einer Ecke einer Geschichte, die dir unbekannt ist."
  },
  AvgDialog_18717_Content_37 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18717_Content_38 = {
    Text = "Was ist los? Ist etwas in meinem Gesicht?"
  },
  AvgDialog_18717_Content_39 = {
    Text = "Du schaust erfreut."
  },
  AvgDialog_18717_Content_4 = {
    Text = "Also, wirst du mich an seltsame Orte mitnehmen?"
  },
  AvgDialog_18717_Content_40 = {
    Text = "Das sind all meine geschätzten Sammlungen."
  },
  AvgDialog_18717_Content_41 = {
    Text = "Es ist lange her, dass ich zuletzt zurückgekehrt bin. Ich vermisse sie sehr."
  },
  AvgDialog_18717_Content_42 = {
    Text = "Worüber redest du?"
  },
  AvgDialog_18717_Content_43 = {
    Text = "Vergangenheit, Gegenwart und Zukunft."
  },
  AvgDialog_18717_Content_44 = {
    Text = "Jeder dieser Köpfe ist eine <Yellow:Projektion aus der Realität>. Ihre Vision und Erinnerung übersteigen die Dimensionen von Zeit und Raum und helfen mir, viele unerwartete Dinge zu entdecken."
  },
  AvgDialog_18717_Content_45 = {
    Text = "So hat dein Laden also so viele seltsame und ungewöhnliche Gegenstände...?"
  },
  AvgDialog_18717_Content_46 = {
    Text = "Die Narzisse blinzelte und stimmte deinem Gedanken stillschweigend zu."
  },
  AvgDialog_18717_Content_47 = {
    Text = "Woher stammen all diese Köpfe?"
  },
  AvgDialog_18717_Content_48 = {
    Text = "Handeln, schenken und ein wenig Glück.\nNatürlich habe ich auch etwas davon für mich genommen."
  },
  AvgDialog_18717_Content_49 = {
    Text = "Es heißt, dass du bis zu @1 Köpfe gejagt hast – das ist nur die offiziell erfasste Zahl."
  },
  AvgDialog_18717_Content_5 = {
    Text = "Natürlich."
  },
  AvgDialog_18717_Content_50 = {
    Text = "Die Narzisse nahm genüsslich einen tiefen Zug aus ihrer langen Pfeife und blies dann einen Schwall weißen Rauches aus."
  },
  AvgDialog_18717_Content_51 = {
    Text = "Tut mir leid, Hüter {Male=Herr,Female=Frau}, moralische Vorwürfe wirken bei mir nicht"
  },
  AvgDialog_18717_Content_52 = {
    Text = "Die von Menschen geschaffenen Regeln gelten nicht für uns. Was du jetzt siehst, bin ich, mit Augen und einer Nase wie die deine..."
  },
  AvgDialog_18717_Content_53 = {
    Text = "Daffodil hat den Silbernen Schlüssel auf deiner Brust aufgenommen und leicht seine komplizierten Muster nachgezeichnet."
  },
  AvgDialog_18717_Content_54 = {
    Text = "Chaotisches Summen und Vibrationen füllen ihre Brust, die heftig wie ein stiller Krieg kollidieren."
  },
  AvgDialog_18717_Content_55 = {
    Text = "Fühlen Sie es? Wir sind keine Menschen. Wir sind „Bestien“ oder wie manche uns nennen..."
  },
  AvgDialog_18717_Content_56 = {
    Text = "Wir sind <Yellow:höhere Wesen>."
  },
  AvgDialog_18717_Content_57 = {
    Text = "Wir tolerieren ignorante Menschen, folgen ständig wechselnden Regeln, gehorchen zerbrechlichen Verknüpfungen, alles aus Angst..."
  },
  AvgDialog_18717_Content_58 = {
    Text = "Sie streichelt sanft dein Gesicht."
  },
  AvgDialog_18717_Content_59 = {
    Text = "Und ein Versprechen."
  },
  AvgDialog_18717_Content_6 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18717_Content_60 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18717_Content_61 = {
    Text = "Also bist du einer der wenigen registrierten Erwachten geworden, die keine Verknüpfungen haben."
  },
  AvgDialog_18717_Content_62 = {
    Text = "Niemand wird geboren, um es zu genießen, kontrolliert zu werden; die meisten Kreaturen sehnen sich von Natur aus nach Freiheit."
  },
  AvgDialog_18717_Content_63 = {
    Text = "Persönlich mag ich das sogenannte \"Link\" nicht... Solange es gegenseitig vorteilhaft ist, warum sich mit dem äußeren Schein herumärgern?"
  },
  AvgDialog_18717_Content_64 = {
    Text = "Das Problem könnte nicht bei mir liegen.\nNiemand verbindet sich mit mir, weil sie nicht qualifiziert sind. Verstanden?"
  },
  AvgDialog_18717_Content_65 = {Text = "Äh"},
  AvgDialog_18717_Content_66 = {
    Text = "Was ist mit mir? Bin ich auch einer dieser \"unqualifizierten\"...?"
  },
  AvgDialog_18717_Content_67 = {
    Text = "Die Narzisse brach in Gelächter aus, doch sie würgte den Rauch und konnte mehrere Male nicht aufhören zu husten."
  },
  AvgDialog_18717_Content_68 = {
    Text = "Mach dir keine Sorgen, Kleines... Du wirst bald die Antwort wissen."
  },
  AvgDialog_18717_Content_69 = {
    Text = "<LightGray:Eine weitere vage Antwort...>"
  },
  AvgDialog_18717_Content_7 = {
    Text = "Tatsächlich... Miss Horla hat mir heute Nachmittag von eurem ersten Treffen erzählt. Sie sagte—"
  },
  AvgDialog_18717_Content_70 = {
    Text = "Ups, ich habe vielleicht ein wenig zu viel gesagt."
  },
  AvgDialog_18717_Content_71 = {
    Text = "Daffodil hob ihre Hand und klopfte jedem an die Stirn, wodurch sie gehorsam davon schwebten."
  },
  AvgDialog_18717_Content_72 = {
    Text = "<Change>Danke euch allen."
  },
  AvgDialog_18717_Content_73 = {
    Text = "Alright. Lass uns gehen, Hüter."
  },
  AvgDialog_18717_Content_74 = {
    Text = "Ich weiß bereits, wo der Schädeljäger ist."
  },
  AvgDialog_18717_Content_8 = {
    Text = "Später fand ich heraus, dass sie diese Erinnerung in etwas verwandelt hatte, das man \"Film\" nennt"
  },
  AvgDialog_18717_Content_9 = {
    Text = "Ich saß im Publikum und sah den ersten Film meines Lebens."
  },
  AvgDialog_18718_Content_1 = {
    Text = "Eine einsame Wiedervereinigung"
  },
  AvgDialog_18718_Content_10 = {
    Text = "Das ist mein Zuhause.\nIch habe keinen anderen Ort, an den ich gehen kann, außer hier."
  },
  AvgDialog_18718_Content_11 = {
    Text = "Für Menschen wie uns vom Land ist es egal, wohin wir gehen."
  },
  AvgDialog_18718_Content_12 = {
    Text = "Lady Harriet..."
  },
  AvgDialog_18718_Content_13 = {
    Text = "Die Atmosphäre im Haus wurde etwas schwerfällig."
  },
  AvgDialog_18718_Content_14 = {
    Text = "Der Regen fällt weiterhin sanft, während du und sie auf den endlosen Vorhang aus Regen blicken."
  },
  AvgDialog_18718_Content_15 = {
    Text = "Die Außenwelt ist von einem grauen Nebel umhüllt, der Wasserdampf umhüllt dich eng und lässt es scheinen, als ob du das einzige Leben zwischen Himmel und Erde bist."
  },
  AvgDialog_18718_Content_16 = {
    Text = "<LightGray:Wo ist die Narzissenfrau jetzt...>"
  },
  AvgDialog_18718_Content_17 = {
    Text = "Bitte warten Sie einen Moment, {Male=sir,Female=miss}. Ich brühe in der Küche etwas heißen Tee auf."
  },
  AvgDialog_18718_Content_18 = {
    Text = "Obwohl es hier bescheiden ist, kann ich dir trotzdem eine Tasse Tee anbieten."
  },
  AvgDialog_18718_Content_19 = {
    Text = "Frau Harriet schleppte ihre langsamen Schritte zur Küche."
  },
  AvgDialog_18718_Content_2 = {
    Text = "Du folgst der Frau in die Holzhütte.\nDas Innere ist sehr einfach, und du schnüffelst den Geruch von feuchtem Holz."
  },
  AvgDialog_18718_Content_20 = {
    Text = "Bis ihre Silhouette von den tiefen Schatten des Korridors verschlungen wurde, kamst du endlich wieder zu dir."
  },
  AvgDialog_18718_Content_21 = {
    Text = "Es scheint, dass es eine Weile dauern wird, bis der Regen aufhört. Lass uns umsehen."
  },
  AvgDialog_18718_Content_3 = {
    Text = "Die Frau beugte sich langsam herunter, hob ein paar Stücke Brennholz aus der Ecke auf und warf sie in den dunklen kleinen Ofen."
  },
  AvgDialog_18718_Content_4 = {
    Text = "Lege deine Hände hierher, wärme sie noch ein wenig länger, und du wirst die Kälte nicht mehr spüren."
  },
  AvgDialog_18718_Content_5 = {
    Text = "Vielen Dank..."
  },
  AvgDialog_18718_Content_6 = {
    Text = "Mein Name ist Harriet: @1, {Male=sir,Female=miss}. Du kannst mich Harriet nennen."
  },
  AvgDialog_18718_Content_7 = {
    Text = "Klar, Mrs. Harriet. Um ehrlich zu sein, ich bin neugierig—warum bleibst du hier?"
  },
  AvgDialog_18718_Content_8 = {
    Text = "Dieser Bereich scheint nicht sehr bewohnbar zu sein."
  },
  AvgDialog_18718_Content_9 = {
    Text = "Frau Harriet hockte sich, spielte mit dem Feuerholz. Die flackernden Flammen tanzten auf ihrem hageren und müden Gesicht."
  },
  AvgDialog_18719_Content_1 = {
    Text = "Schädeljagd-Versammlung"
  },
  AvgDialog_18719_Content_10 = {
    Text = "Letzte Nacht konntest du Daffodil nicht einholen und konntest nur der von Ramona angegebenen Adresse zur Wohnung von Horla folgen."
  },
  AvgDialog_18719_Content_11 = {
    Text = "G-Guten Morgen, Fräulein Horla."
  },
  AvgDialog_18719_Content_12 = {
    Text = "Guten Morgen, {Male=Mr.,Female=Miss} %player%."
  },
  AvgDialog_18719_Content_13 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18719_Content_14 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18719_Content_15 = {
    Text = "Eine unangenehme Stille erfüllt die Luft. Dir wird bewusst, dass dieser Erwacher nicht sehr gut im Sozialisieren zu sein scheint."
  },
  AvgDialog_18719_Content_16 = {
    Text = [[
Miss Horla, ich bin hier wegen des Skull Hunter-Events.
Da du hier schon lange lebst, hast du irgendwelche Hinweise oder Informationen?]]
  },
  AvgDialog_18719_Content_17 = {
    Text = "\"Schädeljäger\"... Bitte einen Moment warten."
  },
  AvgDialog_18719_Content_18 = {
    Text = "Horla drehte sich um und begann, im hohen Bücherregal zu suchen."
  },
  AvgDialog_18719_Content_19 = {
    Text = "Ich habe es gefunden! *Hust, hust...*"
  },
  AvgDialog_18719_Content_2 = {Text = "Daffodil!"},
  AvgDialog_18719_Content_20 = {
    Text = "Horla wischte den herumfliegenden Staub weg und legte das vergilbte Notizbuch in deine Hand."
  },
  AvgDialog_18719_Content_21 = {
    Text = "Vor einem Monat bat Fräulein Puppe um meine Hilfe."
  },
  AvgDialog_18719_Content_22 = {
    Text = "Ich habe keine besonderen Fähigkeiten, aber ich habe alle aktuellen Fälle dokumentiert. Ich hoffe, das wird hilfreich sein."
  },
  AvgDialog_18719_Content_23 = {
    Text = "Du öffnest das Notizbuch, und in eleganter Handschrift wird die Entdeckungszeit und der Ort jedes Falls aufgezeichnet, einschließlich Skizzen der Leichen und Tatorte."
  },
  AvgDialog_18719_Content_24 = {
    Text = "<Shake:Es tut mir leid, meine Zeichenskills sind ziemlich schlecht. Du kannst es einfach ignorieren...>"
  },
  AvgDialog_18719_Content_25 = {
    Text = "Nein, es ist sehr beeindruckend.\nDanke, Miss Horla. Diese Notiz ist entscheidend für uns."
  },
  AvgDialog_18719_Content_26 = {
    Text = "Egal was, ich bin froh, helfen zu können. Diese armen Leute..."
  },
  AvgDialog_18719_Content_27 = {
    Text = "Horla ließ einen sanften Seufzer hören und drehte sich um, um den trüben Himmel draußen zu betrachten."
  },
  AvgDialog_18719_Content_28 = {
    Text = "Regnerische Stadt (Regnerisch) ist ein Ort, an dem es das ganze Jahr über regnet. Doch nach dem Regen steht oft nicht eine reiche Ernte bevor, sondern endlose Überschwemmungen und Plagen."
  },
  AvgDialog_18719_Content_29 = {
    Text = "Junge Leute arbeiten in großen Städten wie Londinium und lassen nur die Alten und Kinder zurück."
  },
  AvgDialog_18719_Content_3 = {
    Text = "Huh... Wo ist dieser Ort?"
  },
  AvgDialog_18719_Content_30 = {
    Text = "Jetzt beginnen sogar die Ältesten, nacheinander zu gehen..."
  },
  AvgDialog_18719_Content_31 = {
    Text = "Ich habe an einigen lokalen Beerdigungen teilgenommen. Immer wenn ein geliebter Mensch stirbt, singen die Reenians ein uraltes Lied..."
  },
  AvgDialog_18719_Content_32 = {
    Text = "Horla begann leise zu summen, und die melancholische Melodie verschmolz bald zu Worten so dunkel wie Tinte."
  },
  AvgDialog_18719_Content_33 = {
    Text = "<RedItalic:Wir schreiben mit Blut als unserem Stift und Ton als unserem Papier.>\n<RedItalic:Wir beschriften Trauer und Angst mit regengetränkten Körpern...>"
  },
  AvgDialog_18719_Content_34 = {
    Text = "Diese Worte flossen langsam um Horla und bildeten dann einen vergilbten Brief, der sie umhüllte."
  },
  AvgDialog_18719_Content_35 = {
    Text = "Sie ließ einen sanften Seufzer erklingen, Tränen glänzten in ihren Augen."
  },
  AvgDialog_18719_Content_36 = {
    Text = "Ist nicht alles, was jetzt geschieht, die Trauer, die die Renier mit ihren regennassen Körpern geschrieben haben"
  },
  AvgDialog_18719_Content_37 = {
    Text = "Die Luft ist erfüllt von einem stillen, dichten Gefühl der Depression, das dich fast erstickt."
  },
  AvgDialog_18719_Content_38 = {
    Text = "<Shake:Husten, Miss Horla...>"
  },
  AvgDialog_18719_Content_39 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18719_Content_4 = {
    Text = "Das fröhliche Zwitschern der Vögel zieht dich aus deinen Träumen zurück in die Realität."
  },
  AvgDialog_18719_Content_40 = {
    Text = "Ah! Entschuldigung, ich habe es wieder gemacht..."
  },
  AvgDialog_18719_Content_41 = {
    Text = "Horla kam zu sich und atmete zweimal tief ein."
  },
  AvgDialog_18719_Content_42 = {
    Text = "Die drückenden Emotionen haben sich schließlich aufgelöst, und das schwere Gewicht auf deiner Brust hat sich deutlich gelockert."
  },
  AvgDialog_18719_Content_43 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18719_Content_44 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18719_Content_45 = {
    Text = "Ah, richtig, richtig."
  },
  AvgDialog_18719_Content_46 = {
    Text = "Ich bereitete einen Topf Rosen-Tee aus frisch gepflückten Blütenblättern zu. Möchtest du mit mir probieren?"
  },
  AvgDialog_18719_Content_47 = {
    Text = "In einer halben Stunde"
  },
  AvgDialog_18719_Content_48 = {
    Text = "In einer Hand hältst du eine Porzellantasse gefüllt mit Rosentee, während du mit der anderen Horlas Notizen durchblätterst, auf der Suche nach einem möglichen Durchbruch."
  },
  AvgDialog_18719_Content_49 = {
    Text = "Wo sind die Leute von der Polizeistation?"
  },
  AvgDialog_18719_Content_5 = {
    Text = "Du schaust verwirrt auf das saubere, einfache Zimmer, dann hebst du die Decke an und schnupperst."
  },
  AvgDialog_18719_Content_50 = {
    Text = "In der Norwich Street, dem Ort, den du letzte Nacht passiert hast."
  },
  AvgDialog_18719_Content_51 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18719_Content_52 = {
    Text = "Regen. Blut. Narzisse.\nWenn du an die Begegnung letzte Nacht zurückdenkst, kannst du nicht sagen, ob es ein Traum oder Realität war."
  },
  AvgDialog_18719_Content_53 = {
    Text = "Du klingst schwach... Hast du letzte Nacht nicht gut geschlafen?"
  },
  AvgDialog_18719_Content_54 = {
    Text = "Nein, es ist nur..."
  },
  AvgDialog_18719_Content_55 = {
    Text = "Du schütteltest den Kopf, versuchtest die durcheinandergebrachten Gedanken aus deinem Kopf zu vertreiben."
  },
  AvgDialog_18719_Content_56 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18719_Content_57 = {
    Text = "Die Untersuchung in Lai Town wurde vor zwei Tagen abgeschlossen, und deine Wunden sind noch nicht vollständig geheilt."
  },
  AvgDialog_18719_Content_58 = {
    Text = "Seufz, es lässt sich nicht vermeiden, dass die anderen Ermittler auch betroffen sind, oder?"
  },
  AvgDialog_18719_Content_59 = {
    Text = "An diesem Punkt lass uns diesen Fall schnell abschließen. Ich möchte Urlaub nehmen."
  },
  AvgDialog_18719_Content_6 = {
    Text = "Gut. Trocken und weich, ohne Geruch nach Regen oder Blut."
  },
  AvgDialog_18719_Content_60 = {
    Text = "Huh, das ist..."
  },
  AvgDialog_18719_Content_61 = {
    Text = "Der Klang des Umblätterns von Seiten kam abrupt zum Stillstand."
  },
  AvgDialog_18719_Content_62 = {
    Text = "Du konzentrierst dich auf die gefrorene Seite und beginnst, deinen nächsten Ermittlungsplan zu formulieren"
  },
  AvgDialog_18719_Content_63 = {
    Text = "Ramona... Bevor ich mich mit dem Detektiv treffe, möchte ich zuerst woanders hingehen."
  },
  AvgDialog_18719_Content_7 = {
    Text = "Guten Morgen, {Male=Mr.,Female=Miss} %player%. Willkommen in meiner bescheidenen Behausung..."
  },
  AvgDialog_18719_Content_8 = {
    Text = "Miss Horla?!"
  },
  AvgDialog_18719_Content_9 = {
    Text = "Die Erinnerung beginnt allmählich sich zu erholen."
  },
  AvgDialog_18720_Content_1 = {
    Text = "11:00, Highgate Friedhof"
  },
  AvgDialog_18720_Content_10 = {
    Text = "Erwarte nicht zu viel von der Expertise von Detektiven in abgelegenen Gebieten."
  },
  AvgDialog_18720_Content_11 = {
    Text = "...Das ergibt Sinn."
  },
  AvgDialog_18720_Content_12 = {
    Text = "Du nimmst deine Lupe heraus und setzt die Beobachtung des Skeletts fort."
  },
  AvgDialog_18720_Content_13 = {
    Text = "Es gibt einen <Red:zackigen Schnitt> am Halswirbel..."
  },
  AvgDialog_18720_Content_14 = {
    Text = "Jedoch ist es ziemlich chaotisch mit zahlreichen überlappenden Schnitten, ganz anders als das, was wir zuvor in den Fotos gesehen haben."
  },
  AvgDialog_18720_Content_15 = {
    Text = "Immer noch ziemlich unerfahren, das erste Mal ein Verbrechen zu begehen?"
  },
  AvgDialog_18720_Content_16 = {
    Text = "Beginne die Untersuchung, die sich um den Begräbnisplatz konzentriert.\nUnerfahrene Novizen wandern in der Regel während ihres ersten Verbrechens nicht weit von zu Hause weg."
  },
  AvgDialog_18720_Content_17 = {
    Text = "Verstanden. Ich bin zuversichtlich, dass der Täter dieses Mal bald gefasst wird!"
  },
  AvgDialog_18720_Content_18 = {
    Text = "Mörder? Wie können Sie es wagen anzunehmen, *hicks*, dass es nur einen Mörder gibt?"
  },
  AvgDialog_18720_Content_19 = {
    Text = "Aus den Tiefen des dichten Waldes tauchte ein alter Mann auf, der nach Alkohol roch und gerötete Wangen hatte."
  },
  AvgDialog_18720_Content_2 = {
    Text = "Du gehst allein durch die einsamen Grabhügel."
  },
  AvgDialog_18720_Content_20 = {
    Text = "Entschuldigung, ich wollte deinem Monolog nicht lauschen."
  },
  AvgDialog_18720_Content_21 = {
    Text = "Ich bin der Wächter dieses Friedhofs. Du kannst mich nennen... äh, <Blue:Old Freeman>."
  },
  AvgDialog_18720_Content_22 = {
    Text = "Guten Tag, Mr. Freeman.\nHaben Sie gerade angedeutet, dass es mehr als einen Mörder gibt?"
  },
  AvgDialog_18720_Content_23 = {
    Text = "Der alte Freeman griff nach der Flasche und kippte den Schnaps herunter, sein dicker Adamsapfel wackelte auf und ab."
  },
  AvgDialog_18720_Content_24 = {
    Text = "Rülpser! Dieser elende Wald sieht den ganzen Tag über keine Seele. Da du hier bist, lass mich dir eine Geschichte erzählen..."
  },
  AvgDialog_18720_Content_25 = {
    Text = "Das war wahrscheinlich früher in diesem Jahr...? Ich kann mich nicht ganz erinnern."
  },
  AvgDialog_18720_Content_26 = {
    Text = "Wie gewohnt trank ich und döste in einem schattigen Platz ein."
  },
  AvgDialog_18720_Content_27 = {
    Text = "Und dann hörte ich seltsame Geräusche, fast wie..."
  },
  AvgDialog_18720_Content_28 = {
    Text = "<RedItalic:Zzz... Knack...>"
  },
  AvgDialog_18720_Content_29 = {
    Text = "Seltsamer Klang. Was kommt als Nächstes?"
  },
  AvgDialog_18720_Content_3 = {
    Text = "Krähen gleiten über den düsteren Himmel, während der verlassene Herbstwind heult."
  },
  AvgDialog_18720_Content_30 = {
    Text = "Mach dir keine Sorgen, kleiner Detektiv.\nIch habe meine Augen geöffnet... hic, rate mal, was ich gesehen habe?"
  },
  AvgDialog_18720_Content_31 = {
    Text = "Keine Möglichkeit, es ist nur der Schädeljäger, oder?"
  },
  AvgDialog_18720_Content_32 = {
    Text = "Sicher, es ist ein Totenschädel-Jäger! Oder du könntest sagen, es ist eine Frau..."
  },
  AvgDialog_18720_Content_33 = {
    Text = "Eine Frau schneidet Pinocchios Kopf ab!"
  },
  AvgDialog_18720_Content_34 = {
    Text = "Dann sah sie mich—hick—als hätte sie einen Geist gesehen, und rannte schneller als alle anderen!"
  },
  AvgDialog_18720_Content_35 = {
    Text = "Meine arme Pinoko, ihr Hals hängt nur noch am seidenen Faden!"
  },
  AvgDialog_18720_Content_36 = {
    Text = "Haha, <Big:Hahaha...>"
  },
  AvgDialog_18720_Content_37 = {
    Text = "Der alte Freeman brach in lautes Lachen aus und weinte sogar vor Freude."
  },
  AvgDialog_18720_Content_38 = {
    Text = "<SmallShake:Geduld, Geduld...>"
  },
  AvgDialog_18720_Content_39 = {
    Text = "Hic, hic! Es ist jetzt etwa einen Monat her, und ich hörte diese Stimme wieder..."
  },
  AvgDialog_18720_Content_4 = {
    Text = "Ich habe es gefunden."
  },
  AvgDialog_18720_Content_40 = {
    Text = "<RedItalic:Zzz... Knack... Knack...>"
  },
  AvgDialog_18720_Content_41 = {
    Text = "Dieses Mal ist nicht die Frau zurückgekehrt, sondern ein sehr dünner Mann."
  },
  AvgDialog_18720_Content_42 = {
    Text = "Das ist ein erfahrener Arbeiter! Mit einem einzigen Schnitt..."
  },
  AvgDialog_18720_Content_43 = {
    Text = "<RedBig:Whoosh!> Pinokos Kopf ist weg!"
  },
  AvgDialog_18720_Content_44 = {
    Text = "Es klingt, als hätte es zwei Schädeljäger gegeben. Was ist danach passiert?"
  },
  AvgDialog_18720_Content_45 = {
    Text = "Später? Es gibt kein Später. Das ist die gesamte Geschichte von Old Freeman und den Headcrabs, hic."
  },
  AvgDialog_18720_Content_46 = {
    Text = "Der alte Freeman ließ einen zufriedenen Rülpser los, blinzelte mit seinen trüben, gelben Augen und betrachtete Sie von Kopf bis Fuß."
  },
  AvgDialog_18720_Content_47 = {
    Text = "Du scheinst völlig ahnungslos zu sein, armer kleiner Detektiv. Hast du jemals von <Red:Die Legende des Schädeljägers> gehört?"
  },
  AvgDialog_18720_Content_48 = {
    Text = "Die Legende des Schädeljägers? Erzähl mir mehr."
  },
  AvgDialog_18720_Content_49 = {
    Text = "Der alte Freeman lehnte sich lässig gegen den Grabstein, trank einige Schlücke, um den restlichen Schnaps aus der Flasche zu beenden, und warf sie beiläufig auf den Boden."
  },
  AvgDialog_18720_Content_5 = {
    Text = "Du bleibst vor einem einsamen Grab stehen, der vermoderte Sargdeckel bereits darunter aufgebrochen."
  },
  AvgDialog_18720_Content_50 = {
    Text = "Flüssigkeit sickerte aus der zerbrochenen Flasche und hinterließ eine geschwungene Spur auf dem Boden. Wie Tränen oder vielleicht Blut."
  },
  AvgDialog_18720_Content_51 = {
    Text = "Einige sagen, dass der Schädeljäger ein Monster ist, das aus der <Yellow:Epidemie> geboren wurde."
  },
  AvgDialog_18720_Content_52 = {
    Text = "Einige sagen, dass der Schädeljäger weder eine Person noch zwei Personen ist."
  },
  AvgDialog_18720_Content_53 = {
    Text = "<Red:Die Schädeljäger sind eine Organisation.>"
  },
  AvgDialog_18720_Content_54 = {
    Text = "Organisation?"
  },
  AvgDialog_18720_Content_55 = {
    Text = "Ja, eine Organisation."
  },
  AvgDialog_18720_Content_56 = {
    Text = "Sie erscheinen nur an regnerischen Nächten, ihre Schritte werden vom Regen verborgen, lautlos schleichen sie sich hinter dir her..."
  },
  AvgDialog_18720_Content_57 = {
    Text = "<RedBig:Snap!>"
  },
  AvgDialog_18720_Content_58 = {Text = "!!"},
  AvgDialog_18720_Content_59 = {
    Text = "Hahaha! Was ist das? Bereits ängstlich, mein kleiner Detektiv?"
  },
  AvgDialog_18720_Content_6 = {
    Text = "Ein kopfloser Skelett liegt in dem Sarg, jetzt ein Paradies für Moos und Insekten."
  },
  AvgDialog_18720_Content_60 = {
    Text = "Er schwankt näher, seine trüben gelben Augen rollen, fast brennen sie in dich hinein."
  },
  AvgDialog_18720_Content_61 = {
    Text = "Diese Person scheint seltsam zu sein. Verlasse diesen Ort schnell."
  },
  AvgDialog_18720_Content_62 = {
    Text = "Entschuldigung, Herr Freeman. Es wird spät. Ich denke, ich muss gehen..."
  },
  AvgDialog_18720_Content_63 = {
    Text = "Du atmest leicht und gehst weg, ohne dich umzusehen."
  },
  AvgDialog_18720_Content_64 = {
    Text = "Verspottendes Lachen kommt von hinten, aber darum kannst du dir jetzt keine Sorgen machen. Alles, was du willst, ist zu gehen."
  },
  AvgDialog_18720_Content_65 = {
    Text = "Der Himmel verdunkelte sich allmählich, mit tiefhängenden dunklen Wolken, die das blasse Sonnenlicht blockierten. Der Wind bewegte die Blätter, sodass sie wie Wellen wogen."
  },
  AvgDialog_18720_Content_66 = {
    Text = "Am Ende des Friedhofs siehst du eine Gestalt, die sowohl vertraut als auch fremd ist."
  },
  AvgDialog_18720_Content_67 = {
    Text = "Es ist Narzisse. Der größte Teil ihres Gesichts ist unter dem Rand ihres gesenkten Hutes verborgen, mit grau-weißen Haaren, die sanft im Wind wehen."
  },
  AvgDialog_18720_Content_68 = {
    Text = "Als sie dich in so einem zerzausten Zustand sah, lachte die Narzisse fröhlich."
  },
  AvgDialog_18720_Content_69 = {
    Text = "Lange nicht gesehen, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_18720_Content_7 = {
    Text = "Die Notiz verzeichnet die Entdeckung vor einem halben Jahr; die Todeszeit muss noch früher gewesen sein..."
  },
  AvgDialog_18720_Content_8 = {
    Text = "Mit anderen Worten, dies ist wahrscheinlich das früheste bekannte Opfer des \"Schädeljägers\". Allerdings wurde dies nie in den Polizeiberichten erwähnt..."
  },
  AvgDialog_18720_Content_9 = {
    Text = "Es gibt hier kein ordentliches Krankenhaus oder Bestattungsinstitut, und niemand schenkt den Toten viel Beachtung."
  },
  AvgDialog_18721_Content_1 = {
    Text = "Vielleicht versuchen, Mind Trace zu verwenden, um den Schädeljäger zu finden?"
  },
  AvgDialog_18721_Content_2 = {
    Text = "Diese Methode hat wenig Effekt auf Ultra Reich Kreaturen."
  },
  AvgDialog_18721_Content_3 = {
    Text = "Spirituelle Rückschau ist auch nicht allmächtig."
  },
  AvgDialog_18722_Content_1 = {
    Text = "Bis wir uns wiedersehe"
  },
  AvgDialog_18722_Content_10 = {
    Text = "<LightGray:Ein kostbares Schädel? Wessen könnte es sein...>"
  },
  AvgDialog_18722_Content_11 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18722_Content_12 = {
    Text = "Du siehst besorgt aus, %player%. Es scheint, als wolltest du wirklich die Antwort wissen?"
  },
  AvgDialog_18722_Content_13 = {
    Text = "Es ist nur so lala."
  },
  AvgDialog_18722_Content_14 = {
    Text = "Ähem, ich bin nicht der Typ, der einfach in die Privatsphäre anderer eindringt."
  },
  AvgDialog_18722_Content_15 = {
    Text = "Ist das so? Aber dein Ausdruck hat dich bereits verraten."
  },
  AvgDialog_18722_Content_16 = {
    Text = "Klar, ich möchte wissen."
  },
  AvgDialog_18722_Content_17 = {
    Text = "Ich möchte nur mehr über dich erfahren, Lady Narzisse."
  },
  AvgDialog_18722_Content_18 = {
    Text = "Oh? Jemand scheint gieriger zu werden."
  },
  AvgDialog_18722_Content_19 = {
    Text = "Hier ist ein Hinweis: <Yellow:Es ist etwas, das du schon einmal gesehen hast.>"
  },
  AvgDialog_18722_Content_2 = {
    Text = "Hilfstruppen und der Ausschuss sind auf dem Weg. Bleibe hier und sichere das Gebiet."
  },
  AvgDialog_18722_Content_20 = {
    Text = "Hast du das schon einmal gesehen...?"
  },
  AvgDialog_18722_Content_21 = {
    Text = "Du denkst tief nach, die Geschichte der letzten zwei Tage und die Leute, die du getroffen hast, blitzen wie eine rotierende Laterne vor deinen Augen auf."
  },
  AvgDialog_18722_Content_22 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18722_Content_23 = {Text = "!!"},
  AvgDialog_18722_Content_24 = {
    Text = "Könnte es derjenige auf der Norwich Street sein, der dir genau ähnlich sieht...?"
  },
  AvgDialog_18722_Content_25 = {Text = "Sehr klug."},
  AvgDialog_18722_Content_26 = {
    Text = "Aber warum... Ich verstehe nicht."
  },
  AvgDialog_18722_Content_27 = {
    Text = "Die Narzisse beobachtete den nebligen Anbruch am fernen Horizont, der kalte Wind hob ihr langes Haar."
  },
  AvgDialog_18722_Content_28 = {
    Text = "Das ist ein \"Probebestück.\" Es gehörte meinem ehemaligen Meister."
  },
  AvgDialog_18722_Content_29 = {
    Text = "Hier ist ein Geheimnis: Mein aktuelles Gesicht ist danach modelliert."
  },
  AvgDialog_18722_Content_3 = {
    Text = "Keine Sorge, dieses Mal werde ich brav sein und hier warten. Ich werde nicht überall herumlaufen."
  },
  AvgDialog_18722_Content_30 = {Text = "?!"},
  AvgDialog_18722_Content_31 = {
    Text = "<LightGray:Also ist dies nicht das wahre Aussehen der Narzissenfrau...>"
  },
  AvgDialog_18722_Content_32 = {
    Text = "Du hast mir dieses Mal wirklich geholfen.\nIch kann mir immer noch nicht vergeben, so einen unerfahrenen Hüter als Köder benutzt zu haben."
  },
  AvgDialog_18722_Content_33 = {
    Text = "...Es spielt keine Rolle. Solange die Untersuchung abgeschlossen ist, stört es mich nicht, einmal benutzt zu werden."
  },
  AvgDialog_18722_Content_34 = {
    Text = "Ist das so? Aber ich fühle mich wirklich schlecht dabei. Also..."
  },
  AvgDialog_18722_Content_35 = {
    Text = "Als Entschuldigung kann ich dir einen Wunsch gewähren."
  },
  AvgDialog_18722_Content_36 = {
    Text = "Es ist kostenlos~"
  },
  AvgDialog_18722_Content_37 = {Text = "!!"},
  AvgDialog_18722_Content_38 = {
    Text = "Die Person vor dir ist ein scharfsinniger und rücksichtsloser Händler, der Intelligenz, tabuisiertes Wissen und wertvolle Sammlerstücke hält, die viele begehren."
  },
  AvgDialog_18722_Content_39 = {
    Text = "Und jetzt kann sie dir einen Wunsch kostenlos gewähren."
  },
  AvgDialog_18722_Content_4 = {
    Text = "Hätte nie gedacht, dass die Untersuchung so schnell abgeschlossen wird.\nGroßartige Leistung, %player%."
  },
  AvgDialog_18722_Content_40 = {
    Text = "<LightGray:Nein... Miss Puppe wäre enttäuscht, wenn sie erfahren würde, dass ich mit anderen draußen Geschäfte mache.>"
  },
  AvgDialog_18722_Content_41 = {
    Text = "Eine Flut von Möglichkeiten blitzte in deinem Kopf auf—verlorene Goldrelikte, die köstlichsten Kuchen, massive Leo-Fänge..."
  },
  AvgDialog_18722_Content_42 = {
    Text = "Verwirrte Gedanken verweben sich und prallen aufeinander, ziehen sich schließlich aber wie die Gezeiten zurück — du entscheidest dich, deinen Instinkten zu folgen."
  },
  AvgDialog_18722_Content_43 = {
    Text = "Hast du dich für deine Anfrage entschieden? Sei nicht zu gierig."
  },
  AvgDialog_18722_Content_44 = {
    Text = "Ich habe mich entschieden. Meine Anforderungen sind einfach."
  },
  AvgDialog_18722_Content_45 = {
    Text = "Lass mich deine wahre Form sehen."
  },
  AvgDialog_18722_Content_46 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18722_Content_47 = {
    Text = "Ist es wirklich so einfach? Denk darüber nach. Ich kann dir viele Dinge geben, jede einzelne davon ist mehr wert als dies."
  },
  AvgDialog_18722_Content_48 = {
    Text = "Der Wert wird durch mein Urteil bestimmt. Das ist meine einzige Forderung."
  },
  AvgDialog_18722_Content_49 = {
    Text = "Wie man es von einem {Male=Mr.,Female=Miss}-Schutzherrn erwartet, du überraschst mich immer wieder. Also..."
  },
  AvgDialog_18722_Content_5 = {
    Text = "Husten, danke an die Narzissenfrau dieses Mal."
  },
  AvgDialog_18722_Content_50 = {
    Text = "Daffodil kam auf dich zu. Der Wind hob ihr langes Haar, wodurch es wie graue Wellen flatterte."
  },
  AvgDialog_18722_Content_51 = {
    Text = "Du bist so nah, dass du dich fast in ihren Augen sehen kannst."
  },
  AvgDialog_18722_Content_52 = {
    Text = "Erinnere dich, es geheim zu halten, %player%."
  },
  AvgDialog_18722_Content_53 = {
    Text = "Kaum hatte sie ausgesprochen, begannen ihre Züge zu verschwommen und aufzulösen, wie Ölfarben im Wasser..."
  },
  AvgDialog_18722_Content_54 = {
    Text = "Schließlich hast du ihr Gesicht endlich klar gesehen."
  },
  AvgDialog_18722_Content_55 = {
    Text = "Das war ein @2 Gesicht, das dich an viele Dinge erinnerte."
  },
  AvgDialog_18722_Content_56 = {
    Text = "Wie der feuchte Nebel nach dem Regen, die Narzisse, die leise in der Ecke blüht, oder das kleine Tier, das sich im Dunkeln zusammenrollt..."
  },
  AvgDialog_18722_Content_57 = {
    Text = "Bevor du genauer hinsehen konntest, verschwand das Gesicht wie ein Tropfen Wasser, der im Wasser verschmilzt."
  },
  AvgDialog_18722_Content_58 = {
    Text = "Also... das ist deine wahre Form."
  },
  AvgDialog_18722_Content_59 = {
    Text = "Wie ist es? Ist es hässlich, oder?"
  },
  AvgDialog_18722_Content_6 = {
    Text = "Es ist nur ein kleiner Aufwand, und ich habe auch das Wiederhergestellte zurückgeholt."
  },
  AvgDialog_18722_Content_60 = {
    Text = "Du schüttelst den Kopf."
  },
  AvgDialog_18722_Content_61 = {
    Text = "Unerwartet... doch so typisch für dich."
  },
  AvgDialog_18722_Content_62 = {
    Text = "Das Morgenlicht fegte die Feuchtigkeit des Regens weg und hüllte sie in einen sanften Schein."
  },
  AvgDialog_18722_Content_63 = {
    Text = "Um ehrlich zu sein... ich hatte gerade ein wenig Angst, und dann war ich über meine eigene Angst überrascht."
  },
  AvgDialog_18722_Content_64 = {
    Text = "Zehn Jahre, fünfzig Jahre? Ich kann mich nicht einmal mehr an das letzte Mal erinnern, als ich Angst fühlte."
  },
  AvgDialog_18722_Content_65 = {
    Text = "Angst...? Könnte es sein, dass du denkst, ich könnte dich unattraktiv finden?"
  },
  AvgDialog_18722_Content_66 = {
    Text = "Die Narzisse reagierte nicht, sondern wuschelte sanft durch dein Haar."
  },
  AvgDialog_18722_Content_67 = {
    Text = "%player%, du bist jetzt die einzige Person auf der Welt, die \"mich\" gesehen hat."
  },
  AvgDialog_18722_Content_68 = {
    Text = "Hehe, ich habe jetzt ein wenig Druckmittel gegen dich."
  },
  AvgDialog_18722_Content_69 = {
    Text = "Bevor ich mein Gedächtnis verliere, muss ich schnell dein Gesicht auf Papier zeichnen."
  },
  AvgDialog_18722_Content_7 = {
    Text = "Aus der Sicht des Händlers war dies ein perfekter \"Deal.\""
  },
  AvgDialog_18722_Content_70 = {
    Text = "Daffodil lächelte, ihre Augen formten einen schönen Bogen."
  },
  AvgDialog_18722_Content_71 = {
    Text = "Was für ein albernes Kind."
  },
  AvgDialog_18722_Content_72 = {
    Text = "Nun, dein Ausschuss und die Freunde von der Polizei sollten jetzt auf dem Weg sein, oder?"
  },
  AvgDialog_18722_Content_73 = {
    Text = "<Shake:Also wusstest du es die ganze Zeit...>"
  },
  AvgDialog_18722_Content_74 = {
    Text = "Ich habe keine Geduld für diese mühsamen Befragungen.\nBeim nächsten Mal lass uns einen ruhigen Ort finden und eine Tasse Kaffee trinken."
  },
  AvgDialog_18722_Content_75 = {
    Text = "Leb wohl, mein {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_18722_Content_76 = {
    Text = "Huh? Oh... Leb wohl, Lady Narzisse."
  },
  AvgDialog_18722_Content_77 = {
    Text = "Daffodil winkte dir zu und ging weg."
  },
  AvgDialog_18722_Content_78 = {
    Text = "Während du ihre entspannte Gestalt in der Ferne betrachtest, fühlst du, wie sich deine Stimmung leichter anfühlt."
  },
  AvgDialog_18722_Content_79 = {
    Text = "Der schwüle Nebel hat sich vollständig aufgelöst, und der Himmel ist endlich klar geworden. Sonnenlicht filtert durch die faulen Wolken und wärmt deinen ganzen Körper."
  },
  AvgDialog_18722_Content_8 = {
    Text = "Verlorene Dinge..."
  },
  AvgDialog_18722_Content_80 = {
    Text = "Aus irgendeinem Grund hast du eine Vorahnung—"
  },
  AvgDialog_18722_Content_81 = {
    Text = "Du wirst dir über verschiedene Zeiten und Dimensionen hinweg immer wieder begegnen."
  },
  AvgDialog_18722_Content_9 = {
    Text = "Der Totenschädel-Jäger hat mir ein <Yellow:wertvoller Schädel> genommen, also bin ich hier, um ein wenig zu ermitteln. So einfach ist das."
  },
  AvgDialog_18723_Content_1 = {
    Text = "Hust, hust, Erwachte aus dem Ultra-Reich sind wirklich schwer zu verfolgen..."
  },
  AvgDialog_18723_Content_10 = {
    Text = "Antwort...?"
  },
  AvgDialog_18723_Content_11 = {
    Text = "Es lief davon, während du kurz weg warst, und Frau Horla und ich haben uns unterhalten."
  },
  AvgDialog_18723_Content_12 = {
    Text = "Aber es gibt keinen Grund zur Sorge. Wenn du mir folgst, wirst du es bald sehen."
  },
  AvgDialog_18723_Content_13 = {
    Text = "Befindet es sich in der <Blue:Ödland nördlich der Stadt Reny>?"
  },
  AvgDialog_18723_Content_14 = {
    Text = "Oh? Es scheint, unser kleiner Detektiv ist ziemlich scharfsinnig. Wie hast du es herausgefunden?"
  },
  AvgDialog_18723_Content_15 = {
    Text = "Dieser Typ zeigt das D-Phänomen, das wahrscheinlich mit der Pest zu tun hat, die vor drei Jahren im Norden aufgetreten ist."
  },
  AvgDialog_18723_Content_16 = {
    Text = "Jetzt, wo es ernsthaft verletzt ist und von uns und der Polizei attackiert wird, gibt es nicht viele Orte, wohin es gehen kann."
  },
  AvgDialog_18723_Content_17 = {
    Text = "Egal ob es sich im Ödland versteckt, es ist ein Durchbruch, der es wert ist, untersucht zu werden."
  },
  AvgDialog_18723_Content_18 = {
    Text = "Nicht schlecht, ziemlich clever. Aber weißt du, wie riesig dieses Wüstenland ist?"
  },
  AvgDialog_18723_Content_19 = {
    Text = "Ungefähr 50 Quadratmeilen.\nSie würden Ihre kostbaren Ferien doch nicht mit geologischen Erkundungen und Bevölkerungszählungen verschwenden, oder?"
  },
  AvgDialog_18723_Content_2 = {
    Text = "Du taumelst zu einer Kreuzung."
  },
  AvgDialog_18723_Content_20 = {
    Text = "Und ich kenne zufällig ihren genauen Versteck. \nMöchtest du mitkommen?"
  },
  AvgDialog_18723_Content_21 = {
    Text = "Stimm nicht zu. Sie ist extrem gefährlich; lass dich nicht von ihr täuschen."
  },
  AvgDialog_18723_Content_22 = {
    Text = "Ich zähle bis drei. Drei, zwei..."
  },
  AvgDialog_18723_Content_23 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18723_Content_24 = {
    Text = "Ich werde mit dir gehen."
  },
  AvgDialog_18723_Content_25 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18723_Content_26 = {
    Text = "Hmm, was für ein gehorsames Kind."
  },
  AvgDialog_18723_Content_27 = {
    Text = "Lady Daffodil, darf ich dich begleiten?"
  },
  AvgDialog_18723_Content_28 = {
    Text = "Ein zartes Mädchen tritt aus den Schatten der Bäume hinter dir, ihre Augen voller Sorge."
  },
  AvgDialog_18723_Content_29 = {
    Text = "Ich weiß, dass du dir um %player% Sorgen machst."
  },
  AvgDialog_18723_Content_3 = {
    Text = "Keine weiteren Jäger hier, nur Narzisse und ihr verlängeter Schatten."
  },
  AvgDialog_18723_Content_30 = {
    Text = "Aber es tut mir leid, meine kleine Rose. Diesmal kann ich nur eine Person mitnehmen."
  },
  AvgDialog_18723_Content_31 = {
    Text = "Der kalte Wind heult durch die nächtlichen Straßen. Horla wickelt sich fest in den winddichten und wärmenden Brief, ihr blasses Gesicht wird ernst, als sie mit ernster Miene zu Narzisse schaut."
  },
  AvgDialog_18723_Content_32 = {
    Text = "Warum? Ich bin vielleicht nicht gut im Kämpfen, aber eine zusätzliche Hand ist immer hilfreich, oder?"
  },
  AvgDialog_18723_Content_33 = {
    Text = "Ich kann nur einen mitnehmen. Entschuldigung, Kleine Rose, ich habe meine Gründe."
  },
  AvgDialog_18723_Content_34 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18723_Content_35 = {
    Text = "Lady Daffodil, Ihr werdet {Male=Mr.,Female=Miss} %player% doch sicher wohlbehalten zurückgeleiten, nicht wahr?"
  },
  AvgDialog_18723_Content_36 = {
    Text = "Daffodil beobachtete die Motten, die unter der Straßenlaterne flatterten, und pustete lässig einen runden Rauchring aus ihrem Mund."
  },
  AvgDialog_18723_Content_37 = {
    Text = "Natürlich, sei unbesorgt."
  },
  AvgDialog_18723_Content_4 = {
    Text = "Aus irgendeinem Grund hast du das Gefühl, dass sie schon sehr lange dort steht."
  },
  AvgDialog_18723_Content_5 = {
    Text = "Es scheint, dass sie seit uralten Zeiten hier allein steht, still in die Ferne blickt, ohne ein Wort zu äußern."
  },
  AvgDialog_18723_Content_6 = {
    Text = "Du bist hier."
  },
  AvgDialog_18723_Content_7 = {
    Text = "Daffodil drehte sich um, ihr Ausdruck blieb schwach."
  },
  AvgDialog_18723_Content_8 = {
    Text = "Wo ist der Schädeljäger? Hast du den Überblick verloren?"
  },
  AvgDialog_18723_Content_9 = {
    Text = "Ja, wir haben den Überblick verloren. Aber... ich glaube, ich kenne die Antwort bereits."
  },
  AvgDialog_18724_Content_1 = {Text = "Von weitem"},
  AvgDialog_18724_Content_10 = {
    Text = "Basierend auf dem Zustand der Leichen und den Aussagen von Zeugen starben die beiden innerhalb einer halben Stunde nach einander."
  },
  AvgDialog_18724_Content_11 = {
    Text = "Ist der Ort des Todes in der Nähe?"
  },
  AvgDialog_18724_Content_12 = {
    Text = "Ramona schüttelte den Kopf."
  },
  AvgDialog_18724_Content_13 = {
    Text = "Selbst mit dem Auto dauert es über eine Stunde, ganz zu schweigen davon, dass sehr wenige Menschen in der Stadt Autos besitzen."
  },
  AvgDialog_18724_Content_14 = {
    Text = "... Vielleicht hatte der alte Freeman recht."
  },
  AvgDialog_18724_Content_15 = {
    Text = "Die Schädeljäger sind eine Organisation. Aber was ist ihr wahres Ziel?"
  },
  AvgDialog_18724_Content_16 = {
    Text = "Köpfe@2 Mehr Köpfe..."
  },
  AvgDialog_18724_Content_17 = {
    Text = "Ein plötzlicher kalter Wind wehte von hinten."
  },
  AvgDialog_18724_Content_18 = {
    Text = "Du drehst dich um, nur um den kopflosen Leichnam zu sehen, der mit unglaublicher Geschwindigkeit auf dich zustürmt."
  },
  AvgDialog_18724_Content_19 = {Text = "?!"},
  AvgDialog_18724_Content_2 = {
    Text = "00:15, Horlas Hütte"
  },
  AvgDialog_18724_Content_20 = {
    Text = "Gib mir Kopf@3 gib@1 Kopf@4"
  },
  AvgDialog_18724_Content_21 = {
    Text = "Du verschiebst schnell deinen Körper zur Seite. Die Leiche durchbricht das Glas vor dir und verschwindet in die weite Nacht."
  },
  AvgDialog_18724_Content_22 = {
    Text = "So unglaubliche Geschwindigkeit... Könnte es ein Erwachter aus dem Ultra-Reich sein?"
  },
  AvgDialog_18724_Content_23 = {
    Text = "So wie du verwirrt bist, umhüllt dich ein starker Duft von Narzissen völlig."
  },
  AvgDialog_18724_Content_24 = {
    Text = "Ein lila Rock schießt schnell an dir vorbei und verschwindet dann vor deinen Augen."
  },
  AvgDialog_18724_Content_25 = {
    Text = "Lady Daffodil...?"
  },
  AvgDialog_18724_Content_26 = {
    Text = "Schnell, komm nach! Lass den wichtigen Hinweis nicht entkommen."
  },
  AvgDialog_18724_Content_3 = {
    Text = "Du hast eine ruhige Ecke gefunden und erklärt, was gerade passiert ist, zu Ramona."
  },
  AvgDialog_18724_Content_4 = {
    Text = "Sicher, überspring einfach den Teil, wo du fast die Kehle durchgeschnitten bekommen hast."
  },
  AvgDialog_18724_Content_5 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18724_Content_6 = {
    Text = "Ich habe dich seit diesem Nachmittag <Red:35> Mal angerufen, aber es gab keine Antwort."
  },
  AvgDialog_18724_Content_7 = {
    Text = "Es tut mir leid, es ist so plötzlich passiert..."
  },
  AvgDialog_18724_Content_8 = {
    Text = "...Das wird nicht noch einmal passieren."
  },
  AvgDialog_18724_Content_9 = {
    Text = "Die Identitäten der tagsüber gefundenen Opfer wurden bestätigt.\nZimmermann Damon Mendes, 35; Arbeitsloser Thomas Quillen, 23."
  },
  AvgDialog_18725_Content_1 = {
    Text = "Ein umgedrehtes Bilderrahmen erregt Ihre Aufmerksamkeit."
  },
  AvgDialog_18725_Content_10 = {
    Text = "<RedItalic:Er trank am Sonntag zehn Flaschen Alkohol, verlor seinen Job und seine Frau.>"
  },
  AvgDialog_18725_Content_11 = {
    Text = "Jemand summt leise ein Kinderlied ohne Rhythmus."
  },
  AvgDialog_18725_Content_12 = {
    Text = "Die trockene Melodie fühlt sich an wie eine feuchte, unsichtbare Hand, die sanft über die bereits aufgestellten Haare an deinem Nacken streicht."
  },
  AvgDialog_18725_Content_13 = {
    Text = "<RedItalic:Der alte Freeman heulte und trank am Montag wieder elf Flaschen Schnaps...>"
  },
  AvgDialog_18725_Content_14 = {
    Text = "Begleitet vom Knarren der Holzdielen stand Harriet still vor dem schwach beleuchteten Korridor."
  },
  AvgDialog_18725_Content_15 = {
    Text = "Das stimmt, der alte Freeman ist mein Ehemann."
  },
  AvgDialog_18725_Content_16 = {Text = "Was?!"},
  AvgDialog_18725_Content_17 = {
    Text = "Zu diesem Zeitpunkt dachten alle, ich sei tot, sogar mein Mann."
  },
  AvgDialog_18725_Content_18 = {
    Text = "Später, nach einer unbekannten Zeitdauer, kam ich wieder zu mir... aber etwas an mir hatte sich verändert."
  },
  AvgDialog_18725_Content_19 = {
    Text = "Du bleibst still und ahnst bereits den Rest der Geschichte."
  },
  AvgDialog_18725_Content_2 = {
    Text = "Aus der Küche kam das Gluckern kochenden Wassers; Mrs. Harriet war immer noch drinnen beschäftigt."
  },
  AvgDialog_18725_Content_20 = {
    Text = "Menschen, die von Auflösung infiziert sind, erleiden irreversible psychische Schäden, die zu verschiedenen Komplikationen führen"
  },
  AvgDialog_18725_Content_21 = {
    Text = "Es ist keine Überraschung, dass Lady Harriet so endete."
  },
  AvgDialog_18725_Content_22 = {
    Text = "Ich begann, Sehnsucht nach Köpfen zu verspüren, vielen Köpfen... Also schlich ich mich auf einen Begräbnisplatz."
  },
  AvgDialog_18725_Content_23 = {
    Text = "Ich beugte mich über den alten Pinocos Körper und versuchte mit einer rostigen Sichel, seinen Kopf abzutrennen.\nAber ich war zu schwach und konnte die Sichel nicht einmal festhalten..."
  },
  AvgDialog_18725_Content_24 = {
    Text = "Und rate, wem ich begegnet bin?"
  },
  AvgDialog_18725_Content_25 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18725_Content_26 = {
    Text = "Ich traf meinen Ehemann."
  },
  AvgDialog_18725_Content_27 = {
    Text = "Er ist fetter geworden, älter und ein Trunkenbold."
  },
  AvgDialog_18725_Content_28 = {
    Text = "Heh... Diese Welt findet immer neue Wege, um uns armen Seelen Qualen zuzufügen."
  },
  AvgDialog_18725_Content_29 = {
    Text = "Er hielt sein Getränk und sah mich an wie einen Streuner."
  },
  AvgDialog_18725_Content_3 = {
    Text = "Du drehst den Bilderrahmen vorsichtig um."
  },
  AvgDialog_18725_Content_30 = {
    Text = "Er hat die ganze Zeit gelacht. Ja, ich weiß, ich muss damals sowohl bemitleidenswert als auch lächerlich ausgesehen haben."
  },
  AvgDialog_18725_Content_31 = {
    Text = "Aber er... erkennt mich überhaupt nicht."
  },
  AvgDialog_18725_Content_32 = {
    Text = "...Also bist du der Schädelsucher, von dem er sprach."
  },
  AvgDialog_18725_Content_33 = {
    Text = "Harriet neigte mechanisch ihren Kopf nach rechts und erzeugte ein \"knackendes\" Geräusch aus ihrem Hals."
  },
  AvgDialog_18725_Content_34 = {
    Text = "Ja. Auch wenn ich weiß, dass er sich nicht an mich erinnert, schaue ich trotzdem heimlich zu ihm."
  },
  AvgDialog_18725_Content_35 = {
    Text = "So hast du unser Gespräch belauscht, erfahren, dass ich eine Untersuchung zu den Morden durchführe, und beschlossen mich zu folgen und zu überfallen?"
  },
  AvgDialog_18725_Content_36 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18725_Content_37 = {
    Text = "Du bist wirklich anders als sie. Ich habe so viel gesagt, und doch bleibst du gelassen."
  },
  AvgDialog_18725_Content_38 = {
    Text = "Du lässt einen sanften Seufzer hören und blickst auf die verschlossene Tür neben dir."
  },
  AvgDialog_18725_Content_39 = {
    Text = "Dunkelrotes Blut sickert wie dicker Sirup aus dem Türspalt und kriecht langsam auf deine Füße zu."
  },
  AvgDialog_18725_Content_4 = {
    Text = "Dies ist ein altes Familienfoto. Die Gesichter von Frau und Kind sind längst verschwommen, es bleibt nur der Ehemann, der ganz links steht."
  },
  AvgDialog_18725_Content_40 = {
    Text = "Wusstest du..."
  },
  AvgDialog_18725_Content_41 = {
    Text = "Der Boden, die Decke, die Schränke... alles stinkt nach Blut und dem Geruch des Todes."
  },
  AvgDialog_18725_Content_42 = {
    Text = "Von dem Moment an, als ich eintrat, wusste ich alles."
  },
  AvgDialog_18725_Content_5 = {
    Text = "Er steht groß und entspannt vor seinem neugebauten Haus und strahlt ein strahlendes Lächeln in die Kamera."
  },
  AvgDialog_18725_Content_6 = {
    Text = "Du schaust auf seine etwas vertraute Stirn und Augen, und plötzlich fliegt ein lächerlicher Gedanke durch deinen Kopf."
  },
  AvgDialog_18725_Content_7 = {
    Text = "Alter Freeman...?!"
  },
  AvgDialog_18725_Content_8 = {
    Text = "Könnte er Mrs. Harriet's Ehemann sein?"
  },
  AvgDialog_18725_Content_9 = {
    Text = "<RedItalic:Alter Freeman, Alter Freeman, der arme und verrückte Trunkenbold Alter Freeman...>"
  },
  AvgDialog_18726_Content_1 = {
    Text = "Du gehst tiefer in die Gasse, dein Mantel ist bereits vom Regen durchnässt."
  },
  AvgDialog_18726_Content_10 = {
    Text = "Tippe, tippe, tippe."
  },
  AvgDialog_18726_Content_11 = {
    Text = "Der Klang ungehasteter Schritte hallte von der Straße außerhalb der Gasse wider, und eine verschwommene Gestalt erschien unter dem Straßenlicht."
  },
  AvgDialog_18726_Content_12 = {
    Text = "Es ist gefährlich hier, verlasse sofort—"
  },
  AvgDialog_18726_Content_13 = {
    Text = "Das ist eine Frau."
  },
  AvgDialog_18726_Content_14 = {
    Text = "Sie steht allein unter dem Straßenlaterne und hält einen kräftigen Kopf, der perfekt mit dem Hals des enthaupteten Körpers hinter dir zusammenpasst."
  },
  AvgDialog_18726_Content_15 = {
    Text = "Blut tropft vom Hals und fließt langsam entlang der Risse in den Fliesen."
  },
  AvgDialog_18726_Content_16 = {
    Text = [[
Bleib genau dort.
Wer bist du?]]
  },
  AvgDialog_18726_Content_17 = {
    Text = "Die matten Straßenlaternen flackern und geben ein nervtötendes elektrisches Summen von sich."
  },
  AvgDialog_18726_Content_18 = {
    Text = "Die Frau hebt ihren Kopf, und du kannst schließlich ihre Züge erkennen."
  },
  AvgDialog_18726_Content_19 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18726_Content_2 = {
    Text = "Dunkelrotes Blut fließt aus dem <Shadow>, streckt drohende Tentakel aus und lädt dich schweigend ein."
  },
  AvgDialog_18726_Content_20 = {
    Text = "<Gray:Daphne... Lady Delf?>"
  },
  AvgDialog_18726_Content_3 = {
    Text = "Es ist ruhig hier; man kann nur das Geräusch des Regens, Schritte und Atem hören."
  },
  AvgDialog_18726_Content_4 = {
    Text = "Sie klingen wie ein chaotischer Trommelschlag, der schneller und lauter wird, bis Sie das Ende der Gasse erreichen."
  },
  AvgDialog_18726_Content_5 = {
    Text = "Die aufgeblähte Leiche liegt schlaff im Müllhaufen, achtlos weggeworfen."
  },
  AvgDialog_18726_Content_6 = {
    Text = "Der Schnitt am Hals ist verschwommen, mit dunkelrotem Blut, das aus den Gefäßen spritzt."
  },
  AvgDialog_18726_Content_7 = {
    Text = "Du musst es nicht anfassen, um zu wissen, dass das Blut warm ist."
  },
  AvgDialog_18726_Content_8 = {
    Text = "Kopf fehlt, gezackte Wunden am Hals..."
  },
  AvgDialog_18726_Content_9 = {
    Text = "Es ist \"Schädeljäger\""
  },
  AvgDialog_18727_Content_1 = {Text = "Zufall"},
  AvgDialog_18727_Content_10 = {
    Text = "Wenn sie nicht gelogen oder falsch beurteilt hat, dann ja."
  },
  AvgDialog_18727_Content_11 = {
    Text = "<Blue:Vorhut> kam vor einer Woche in Rini Stadt an und entdeckte Anzeichen eines aktiven Silbers am Todesort."
  },
  AvgDialog_18727_Content_12 = {
    Text = "Inklusive der letzten drei, dies ist das achte <Blue:Cranial Predator Event> in Rennie Town."
  },
  AvgDialog_18727_Content_13 = {
    Text = "Schädeljäger? So nennt man hier den Mörder?"
  },
  AvgDialog_18727_Content_14 = {
    Text = "Sehr lebhaft, nicht wahr? Dank ihm traut sich hier nachts niemand mehr nach draußen."
  },
  AvgDialog_18727_Content_15 = {
    Text = "Du schaust auf die trostlose Straße vor dir."
  },
  AvgDialog_18727_Content_16 = {
    Text = "Um 20 Uhr sind alle umliegenden Türen und Fenster fest verschlossen. Angst sickert aus den pechschwarzen Fenstern und umhüllt lautlos die Umgebung."
  },
  AvgDialog_18727_Content_17 = {
    Text = "Abgesehen von ein paar verzögerten Hundebellen ist es hier unheimlich still."
  },
  AvgDialog_18727_Content_18 = {
    Text = "Tropf, tropf..."
  },
  AvgDialog_18727_Content_19 = {
    Text = "Hmm, regnet es?"
  },
  AvgDialog_18727_Content_2 = {
    Text = "Belen Stock, 46, starb am 12. September zu Hause in der Küche.\n<Red:Kopf fehlt>, Körper intakt, bis auf einen gezackten Schnitt am Hals."
  },
  AvgDialog_18727_Content_20 = {
    Text = "Ein feiner, kühler Regen tropft vom Nachthimmel und wirft einen weißen Schleier vor dir."
  },
  AvgDialog_18727_Content_21 = {
    Text = "Ich höre Regen auf deiner Seite. Hast du einen Regenschirm?"
  },
  AvgDialog_18727_Content_22 = {
    Text = "<Shake:Oh nein. Du bist immer diejenige, die einen Regenschirm bringt, also...>"
  },
  AvgDialog_18727_Content_23 = {
    Text = "Sieht so aus, als müsste ich mich noch an das Leben ohne dich gewöhnen."
  },
  AvgDialog_18727_Content_24 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18727_Content_25 = {
    Text = "Entschuldigung, ich konnte diesmal nicht mit dir gehen."
  },
  AvgDialog_18727_Content_26 = {
    Text = "Miss Puppe besteht darauf, dass ich bleibe, um mit ihr einige angeblich \"wichtige\" Auflösungsforschungen durchzuführen..."
  },
  AvgDialog_18727_Content_27 = {
    Text = "<Small:Ramona, könntest du mir das Silbermuster auf dem dritten Regal der fünften Reihe, Code SI-3007... reichen?>"
  },
  AvgDialog_18727_Content_28 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18727_Content_29 = {
    Text = "Kümmern Sie sich um sich selbst, %player%. Was die Unterkunft angeht... <Blue:Fräulein Horla> wird alles organisieren."
  },
  AvgDialog_18727_Content_3 = {
    Text = "Dwight Williams, 56, starb an der Kreuzung Deman Street am 13. September.\n<Red:Kopf fehlt>, Körper intakt mit einem gezackten Schnitt am Hals."
  },
  AvgDialog_18727_Content_30 = {
    Text = "Miss Horla? Kein Wunder, dass wir sie selten in der Schule sehen; sie lebt außerhalb?"
  },
  AvgDialog_18727_Content_31 = {
    Text = "Mythag ist kein einseitiges Camp."
  },
  AvgDialog_18727_Content_32 = {
    Text = "Risikofreie Awakener können Urlaub machen, übernachten oder die Familie besuchen.\nDie Bedingung ist einfach: Im Voraus beantragen und vermeiden, Probleme zu verursachen."
  },
  AvgDialog_18727_Content_33 = {
    Text = "Uh... Wird die Fräulein Horla also auch an der Untersuchung teilnehmen?"
  },
  AvgDialog_18727_Content_34 = {
    Text = "Nicht alle Awakeners sind an Feldmissionen interessiert. Wenn du denkst, dass es notwendig ist, frag sie nach ihrer Meinung."
  },
  AvgDialog_18727_Content_35 = {
    Text = "Die aktuelle Situation ist stabil und handhabbar, keine Notwendigkeit zu—"
  },
  AvgDialog_18727_Content_36 = {Text = "Whoosh—"},
  AvgDialog_18727_Content_37 = {
    Text = "Plötzlich kam das Geräusch von Caro, das aus der Gasse vorne spritzte, gefolgt von chaotischen Schritten, die abrupt die Stille der Nacht durchbrachen."
  },
  AvgDialog_18727_Content_38 = {Text = "?!"},
  AvgDialog_18727_Content_39 = {
    Text = "In diesem Moment, dieser Klang... Könnte es sein...?"
  },
  AvgDialog_18727_Content_4 = {
    Text = "Verstorbene Nr. 012, Identität und Alter unbekannt, starb am frühen Morgen des 16. Septembers am Knerlsee im Norden..."
  },
  AvgDialog_18727_Content_40 = {
    Text = "Lass uns folgen und nachsehen. Denk daran, in Kontakt zu bleiben."
  },
  AvgDialog_18727_Content_41 = {
    Text = "Möge der Silberschlüssel unseren Weg erhellen."
  },
  AvgDialog_18727_Content_5 = {
    Text = "20:00, Norwich Straße  \nRenny Stadt"
  },
  AvgDialog_18727_Content_6 = {
    Text = "Fehlender Kopf, gezackte Narben..."
  },
  AvgDialog_18727_Content_7 = {
    Text = "Und alle starben entweder beim Alleinverlassen oder zu Hause."
  },
  AvgDialog_18727_Content_8 = {
    Text = "Zusätzlich behauptete die Frau von Dwight Williams eine Woche nach seinem Tod, sie habe ihn gesehen, wie er hastig durch die Wildnis rannte."
  },
  AvgDialog_18727_Content_9 = {
    Text = "...Wiederbelebt?"
  },
  AvgDialog_18764_Content_1 = {
    Text = "Nein, bitte nicht..."
  },
  AvgDialog_18764_Content_10 = {
    Text = "Hust, hust... Du, wie kannst du nur schummeln!"
  },
  AvgDialog_18764_Content_11 = {
    Text = "<SmallShake:Es ist doch nur ein Ratespiel, was macht dich so nervös...>"
  },
  AvgDialog_18764_Content_12 = {
    Text = "Wo ist der Ausgang des Labyrinths?"
  },
  AvgDialog_18764_Content_13 = {
    Text = "Hehe, neugierig? Dann geh auf die Knie, entschuldige dich ordentlich bei mir, und dann..."
  },
  AvgDialog_18764_Content_14 = {
    Text = "Du hebst langsam deine Hand."
  },
  AvgDialog_18764_Content_15 = {
    Text = "<Shake:Warte, warte! Ich meine...>"
  },
  AvgDialog_18764_Content_16 = {
    Text = "Das Mädchen öffnete den Mund und senkte frustriert den Kopf."
  },
  AvgDialog_18764_Content_17 = {
    Text = "Eigentlich... weiß ich es auch nicht. Ich bin hier seit fast tausend Jahren eingesperrt..."
  },
  AvgDialog_18764_Content_18 = {
    Text = "Abgesehen von Schlafen und Tagträumen treibt mich die Verwaltung meiner Nachkommen in den Wahnsinn vor Langeweile!"
  },
  AvgDialog_18764_Content_19 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18764_Content_20 = {
    Text = "Bist du nicht die Herrin des Labyrinths? Wie kannst du nicht wissen, wo der Ausgang ist?"
  },
  AvgDialog_18764_Content_21 = {
    Text = "<SmallShake:Das solltest du denjenigen fragen, der mich hier reingeworfen hat. Woher soll ich wissen, was der sich dabei gedacht hat...>"
  },
  AvgDialog_18764_Content_22 = {
    Text = "Wie kann das sein...?"
  },
  AvgDialog_18764_Content_23 = {
    Text = "Also, sagen wir mal, rein hypothetisch—"
  },
  AvgDialog_18764_Content_24 = {
    Text = "Diejenigen, die das Labyrinth betreten, sind keine physischen Wesen, sondern existieren in einer Art ideologischer Form."
  },
  AvgDialog_18764_Content_25 = {
    Text = "Könnte er, äh, so... die Regeln dieses Labyrinths ignorieren?"
  },
  AvgDialog_18764_Content_26 = {
    Text = "Agrippa warf dir einen seltsamen Blick zu."
  },
  AvgDialog_18764_Content_27 = {
    Text = "Natürlich nicht."
  },
  AvgDialog_18764_Content_28 = {
    Text = "Willst du raten, warum du so viele vertraute Menschen und Orte im Labyrinth siehst?"
  },
  AvgDialog_18764_Content_29 = {
    Text = "Trugbild? Nein, es ist Erinnerung..."
  },
  AvgDialog_18764_Content_3 = {
    Text = "Du hast endlich die letzte „ Charlotte “ erledigt."
  },
  AvgDialog_18764_Content_30 = {
    Text = "Agrippa schüttelte den Kopf."
  },
  AvgDialog_18764_Content_31 = {
    Text = "Weder noch. Um genau zu sein, es ist <Yellow:Bewusstsein>."
  },
  AvgDialog_18764_Content_32 = {
    Text = "<Yellow:Nur dein Bewusstsein ist im Labyrinth gefangen.>"
  },
  AvgDialog_18764_Content_4 = {
    Text = "Das Schlüsselgrab verblasst allmählich, und du findest dich dort wieder, wo du angefangen hast."
  },
  AvgDialog_18764_Content_5 = {
    Text = "Komm raus, ich weiß, wo du bist."
  },
  AvgDialog_18764_Content_6 = {
    Text = "Ein zitterndes Brummen hallt aus der Tiefe des Untergrunds, gefolgt von sich allmählich öffnenden Rissen im Boden."
  },
  AvgDialog_18764_Content_7 = {Text = "WUMM!!"},
  AvgDialog_18764_Content_8 = {
    Text = "Pfft... bäh bäh bäh!!"
  },
  AvgDialog_18764_Content_9 = {
    Text = "Agrippa bricht plötzlich aus dem Boden hervor, völlig staubbedeckt."
  },
  AvgDialog_18765_Content_1 = {
    Text = "Schwarmbewusstsein"
  },
  AvgDialog_18765_Content_10 = {
    Text = "Hast du die Aufgaben dieser Woche gemacht? Die Prüfung in „Einführung ins Schmelzen\" steht bevor. Wie läuft deine Wiederholung?"
  },
  AvgDialog_18765_Content_11 = {
    Text = "Ramona?! Nein, ich habe nicht... warte..."
  },
  AvgDialog_18765_Content_12 = {
    Text = "%player%, du warst heute 5 Minuten zu spät zum Unterricht. Deine gesamte Verspätung diesen Monat beträgt 30 Minuten und 15 Sekunden."
  },
  AvgDialog_18765_Content_13 = {
    Text = "Komm nach dem Unterricht in mein Büro."
  },
  AvgDialog_18765_Content_14 = {Text = "—!!"},
  AvgDialog_18765_Content_15 = {
    Text = "Pff. <Big:Hahahahaha!>"
  },
  AvgDialog_18765_Content_16 = {
    Text = "Angst, hm? Du solltest wirklich mal in den Spiegel schauen und sehen, wie du jetzt aussiehst."
  },
  AvgDialog_18765_Content_17 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18765_Content_18 = {
    Text = "Wo hast du diese... Verwandlungstricks gelernt?"
  },
  AvgDialog_18765_Content_19 = {
    Text = "Du hast Agrippas Akte im Erwecker-Archiv gesehen; darin stand nichts über „Verwandlung“."
  },
  AvgDialog_18765_Content_20 = {
    Text = "Lernen? Ich bin der Herr dieses Labyrinths. In meinem Reich kann ich tun, was mir beliebt."
  },
  AvgDialog_18765_Content_21 = {
    Text = "Nicht nur eine verwandeln... Ich kann dir zehn zeigen, sogar hundert."
  },
  AvgDialog_18765_Content_22 = {
    Text = "Nach diesen Worten verschwand Agrippa erneut."
  },
  AvgDialog_18765_Content_23 = {
    Text = "Im Nu tauchen eine, zwei... weitere Charlottes vor dir auf."
  },
  AvgDialog_18765_Content_24 = {
    Text = "Rate, welcher der echte ich bin, hehe..."
  },
  AvgDialog_18765_Content_25 = {
    Text = "Buhuuu... Welche Charlotte ist Agrippa?"
  },
  AvgDialog_18765_Content_26 = {
    Text = "Nur einmal, nur eine einzige Chance..."
  },
  AvgDialog_18765_Content_27 = {
    Text = "Unzählige durchdringende Stimmen verweben sich zu einer chaotischen Melodie, die in deinem Kopf nachhallt."
  },
  AvgDialog_18765_Content_28 = {
    Text = "Geht... Geht weg...!!"
  },
  AvgDialog_18765_Content_29 = {
    Text = "Du atmest tief durch und beruhigst endlich deinen Geist."
  },
  AvgDialog_18765_Content_3 = {
    Text = "Charlotte, wie bist du so geworden?"
  },
  AvgDialog_18765_Content_30 = {
    Text = "Tut mir leid. Ihr seht alle gleich aus; ich kann es nicht erkennen."
  },
  AvgDialog_18765_Content_31 = {
    Text = "Hä? Schon aufgegeben? Wie langweilig."
  },
  AvgDialog_18765_Content_33 = {
    Text = "Im nächsten Moment wurde „ Charlotte “ zu Boden geschlagen.\nDu riebst dir die Schläfen und sagtest ruhig—"
  },
  AvgDialog_18765_Content_34 = {
    Text = "Aber das macht nichts."
  },
  AvgDialog_18765_Content_35 = {
    Text = "Ich kann euch alle niederschlagen und eine nach der anderen verhören."
  },
  AvgDialog_18765_Content_4 = {
    Text = "„ Charlotte “ verdreht ihren Kopf und stößt ein schauriges Summen tief aus ihrer Kehle aus."
  },
  AvgDialog_18765_Content_5 = {
    Text = "<Shake:Hehe, überrascht? Deine sogenannte Freundin ist längst zu meinem Nachkommen geworden!>"
  },
  AvgDialog_18765_Content_6 = {
    Text = "Diese Stimme... Bist du Agrippa?"
  },
  AvgDialog_18765_Content_7 = {
    Text = "Wie rührend, dass du dich noch an meine Stimme erinnerst.\nWarte, ich zeige dir etwas Unglaubliches!"
  },
  AvgDialog_18765_Content_8 = {
    Text = "Ein gedämpftes Kichern drang aus Charlottes Kehle, dann verdrehte sie ihren Hals und veränderte augenblicklich ihr Aussehen."
  },
  AvgDialog_18765_Content_9 = {
    Text = "%player%, du naschst schon wieder heimlich Cupcakes!"
  },
  AvgDialog_18766_Content_1 = {Text = "Tür"},
  AvgDialog_18766_Content_10 = {
    Text = "Bist du bereit, @1? Lass uns gemeinsam drücken."
  },
  AvgDialog_18766_Content_11 = {Text = "Kreisch—"},
  AvgDialog_18766_Content_12 = {Text = "<Big:!!!>"},
  AvgDialog_18766_Content_13 = {
    Text = "Wo... ist dieser Ort...?"
  },
  AvgDialog_18766_Content_14 = {
    Text = "Hier wirst du brav für den Rest deines Lebens bleiben."
  },
  AvgDialog_18766_Content_15 = {
    Text = "Das Mädchen sitzt auf der hohlen Plattform, die Hände an die Wangen gelegt, das rechte Bein lässig baumelnd, während sie lächelt."
  },
  AvgDialog_18766_Content_16 = {
    Text = "Willkommen in meinem Labyrinth."
  },
  AvgDialog_18766_Content_17 = {
    Text = "Du hast so tief geschlafen; ich wollte dir gerade ein paar Käfer füttern, um deinen Geist aufzufrischen."
  },
  AvgDialog_18766_Content_18 = {
    Text = "<LightGray:Agrippa...?>"
  },
  AvgDialog_18766_Content_19 = {
    Text = "Du blickst an dir herab auf die unbekannte Kleidung und erkennst, dass du erneut in einen Traum eingetreten bist."
  },
  AvgDialog_18766_Content_2 = {
    Text = "Man sagt, dass in „Seinem\" Labyrinth nicht nur die Richtung verloren geht."
  },
  AvgDialog_18766_Content_20 = {
    Text = "Dieses Mal hast du fast alle Erinnerungen der ursprünglichen Besitzerin verloren.\nWer ist sie? Woher kommt sie?"
  },
  AvgDialog_18766_Content_21 = {
    Text = "Du weißt nichts."
  },
  AvgDialog_18766_Content_22 = {
    Text = "<Shake:Was ist los... Die ursprüngliche Besitzerin? Nein, wer bin ich...>"
  },
  AvgDialog_18766_Content_23 = {
    Text = "Schon gut, hör auf nachzudenken. Du wirst dich an nichts erinnern."
  },
  AvgDialog_18766_Content_24 = {
    Text = "Selbst nach 1 Tag, 100 Tagen oder 1000 Tagen wird dein Geist so rein bleiben wie der eines Neugeborenen."
  },
  AvgDialog_18766_Content_25 = {
    Text = "Nun werde ich dir zwei Möglichkeiten geben."
  },
  AvgDialog_18766_Content_26 = {
    Text = "<Red:Eine Person: Schließe einen Vertrag mit mir und werde mein Kind.>"
  },
  AvgDialog_18766_Content_27 = {
    Text = "<Red:Zwei: Verhungere im Labyrinth und werde dann mein Abkömmling.>"
  },
  AvgDialog_18766_Content_28 = {
    Text = "Agrippa erläutert dir geschickt die Lage und präsentiert Optionen, als hätte sich dieser Vorgang schon unzählige Male wiederholt."
  },
  AvgDialog_18766_Content_29 = {
    Text = "Nachkommen? Was ist das?"
  },
  AvgDialog_18766_Content_3 = {
    Text = "Name, Heimat, Geliebte... Alles Wichtige und Unwichtige wird zurückgelassen."
  },
  AvgDialog_18766_Content_30 = {
    Text = "Keine Sorge, es ist ungiftig, schmerzlos und harmlos. Was Nebenwirkungen betrifft? Du wirst ihre Anwesenheit nicht einmal bemerken."
  },
  AvgDialog_18766_Content_31 = {
    Text = "Also, verglichen mit jenen bösen Göttern, die ständig verlangen, dass du dein Leben als Opfergabe gibst oder deine Liebsten tötest – würdest du nicht sagen, dass ich viel sanftmütiger bin?"
  },
  AvgDialog_18766_Content_32 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18766_Content_33 = {
    Text = "Nun, ich gebe dir drei Sekunden, um dich zu entscheiden. Den Vertrag unterschreiben oder verhungern?"
  },
  AvgDialog_18766_Content_34 = {Text = "Drei —"},
  AvgDialog_18766_Content_35 = {Text = "Zwei—"},
  AvgDialog_18766_Content_36 = {
    Text = "In Ordnung, ich habe mich entschieden."
  },
  AvgDialog_18766_Content_37 = {Text = "Uh...?"},
  AvgDialog_18766_Content_38 = {
    Text = "Du bist entschlossen... nicht schlecht. Also, sag mir deine Wahl."
  },
  AvgDialog_18766_Content_39 = {
    Text = "Du nickst und schiebst leise deinen rechten Fuß ein wenig nach hinten."
  },
  AvgDialog_18766_Content_4 = {
    Text = "Von nun an hast du nur noch eine Identität: <Red:Sein Abkömmling>."
  },
  AvgDialog_18766_Content_40 = {
    Text = "Meine Wahl ist—"
  },
  AvgDialog_18766_Content_41 = {
    Text = "Du hast dich entschlossen umgedreht und bist mit höchster Geschwindigkeit hinausgerannt."
  },
  AvgDialog_18766_Content_42 = {
    Text = "<BigShake:Rennt!!>"
  },
  AvgDialog_18766_Content_43 = {
    Text = "Eine sehr, sehr lange Zeit später..."
  },
  AvgDialog_18766_Content_44 = {
    Text = "Huch... huch..."
  },
  AvgDialog_18766_Content_45 = {
    Text = "Du rennst den langen Korridor entlang, bis eine Tür dir den Weg versperrt."
  },
  AvgDialog_18766_Content_46 = {
    Text = "Wachsfigurenmuseum? Nicht schon wieder..."
  },
  AvgDialog_18766_Content_47 = {
    Text = "Wenn ich mich richtig erinnere, ist das das 23. Mal, dass ich es gesehen habe."
  },
  AvgDialog_18766_Content_48 = {
    Text = "Ja, es gibt unzählige Türen, die zu unzähligen Räumen führen."
  },
  AvgDialog_18766_Content_49 = {
    Text = "Sie erscheinen so häufig vor dir, dass es selbst den ruhigsten Ermittler in den Wahnsinn treiben könnte."
  },
  AvgDialog_18766_Content_5 = {
    Text = "<Shake:Kind, Erbe?>"
  },
  AvgDialog_18766_Content_50 = {
    Text = "Du drückst die Tür auf und gehst den Korridor weiter entlang."
  },
  AvgDialog_18766_Content_51 = {
    Text = "Schon wieder dieser Flur... 15 Mal."
  },
  AvgDialog_18766_Content_52 = {
    Text = "Du berührtest instinktiv die silbernen Manschettenknöpfe, die in deinem Ärmel eingelassen sind."
  },
  AvgDialog_18766_Content_53 = {
    Text = "Misaqs frühes Schulemblem... Es scheint, als wäre ich diesmal eine Vorgängerin aus der Vergangenheit geworden?"
  },
  AvgDialog_18766_Content_54 = {
    Text = "Aber wie ist sie in das Labyrinth gelangt?"
  },
  AvgDialog_18766_Content_55 = {
    Text = "Während du nachdenkst, versperrt eine weitere Tür deinen Weg."
  },
  AvgDialog_18766_Content_56 = {
    Text = "Du stehst jetzt vor dieser Tür, @1. Öffne sie."
  },
  AvgDialog_18766_Content_57 = {
    Text = "Wer spricht?!"
  },
  AvgDialog_18766_Content_58 = {
    Text = "Kopf... es tut weh. Sind das die Erinnerungen an Senpai?"
  },
  AvgDialog_18766_Content_59 = {
    Text = "Atme tief durch, %player%. Mach deinen Kopf frei..."
  },
  AvgDialog_18766_Content_6 = {
    Text = "Ja. Die Abkömmlinge strömen wie eine bleiche Flut ins Labyrinth, aus allen Richtungen hereinströmend."
  },
  AvgDialog_18766_Content_60 = {
    Text = "Du zwingst dich zur Ruhe, drehst den Messinggriff und ziehst die Tür vorsichtig auf."
  },
  AvgDialog_18766_Content_61 = {
    Text = "...Schlüsselgrab?"
  },
  AvgDialog_18766_Content_62 = {
    Text = "Im Nebel bemerkst du eine Gestalt, die dir zugleich vertraut und fremd ist."
  },
  AvgDialog_18766_Content_63 = {
    Text = "Charlotte... <Big:Charlotte!>"
  },
  AvgDialog_18766_Content_64 = {
    Text = "Du erinnerst dich an das Mädchen namens Charlotte. Sie war die Freundin, die „dich“ in das Labyrinth geführt hat."
  },
  AvgDialog_18766_Content_65 = {
    Text = "<Big:Warte auf mich, Charlotte!>"
  },
  AvgDialog_18766_Content_66 = {
    Text = "Du stürzt nach vorn und packst Charlottes Handgelenk."
  },
  AvgDialog_18766_Content_67 = {
    Text = "In dem Moment, als unsere Haut sich berührte, blitzten unzählige chaotische Fragmente durch meinen Kopf."
  },
  AvgDialog_18766_Content_68 = {
    Text = "Öffne die Tür, @1."
  },
  AvgDialog_18766_Content_69 = {
    Text = "<Shake:Nein, i–ich hab gerade gemerkt, dass ich meine Hausaufgaben noch nicht fertig habe. Ich will—>"
  },
  AvgDialog_18766_Content_7 = {
    Text = "Eintritte zum Labyrinth sind überall: in Wänden, in der Kanalisation, und sogar dort, wo wir uns gerade befinden..."
  },
  AvgDialog_18766_Content_70 = {
    Text = "<Big:Ahhh!!>"
  },
  AvgDialog_18766_Content_71 = {
    Text = "<Shake:Charlotte, dein Gesicht...>"
  },
  AvgDialog_18766_Content_72 = {
    Text = "Tür... Tür..."
  },
  AvgDialog_18766_Content_73 = {
    Text = "@1 Tür @2 Öffnen @4"
  },
  AvgDialog_18766_Content_74 = {
    Text = "<RedBig:Die Tür öffnen...>"
  },
  AvgDialog_18766_Content_75 = {
    Text = "Ich verstehe. Du warst es also, die „mich“ in das Labyrinth gelockt hat..."
  },
  AvgDialog_18766_Content_76 = {
    Text = "Instinktiv lässt du Charlottes Handgelenk los und trittst ein paar Schritte zurück."
  },
  AvgDialog_18766_Content_77 = {
    Text = "Der Nebel lichtet sich allmählich. Mit einiger Mühe dreht Charlotte sich um und blickt dich kummervoll an."
  },
  AvgDialog_18766_Content_78 = {
    Text = "...@4 Tür@4@1"
  },
  AvgDialog_18766_Content_79 = {
    Text = "—Mit ihren pechschwarzen Augenhöhlen."
  },
  AvgDialog_18766_Content_8 = {
    Text = "<Blue:Stadtarchiv> hinter der verborgenen Tür im Untergrund."
  },
  AvgDialog_18766_Content_9 = {
    Text = "<Shake:Ich kann nicht glauben, dass so ein Ort wirklich existiert... Die Legenden sind wahr...>"
  },
  AvgDialog_18767_Content_1 = {
    Text = "Ende des Labyrinths"
  },
  AvgDialog_18767_Content_10 = {
    Text = "Schh... Schließ die Augen, leere deinen Geist und denke an nichts."
  },
  AvgDialog_18767_Content_11 = {
    Text = "Tu nichts..."
  },
  AvgDialog_18767_Content_12 = {Text = "Hmm!!"},
  AvgDialog_18767_Content_13 = {
    Text = "Mein Kopf platzt gleich... Ich sollte diese Methode besser nicht zu oft anwenden..."
  },
  AvgDialog_18767_Content_14 = {
    Text = "<Shake:Aus dem Weg, ihr alle!>"
  },
  AvgDialog_18767_Content_15 = {
    Text = "Wer es wagt, meiner Familie etwas anzutun, den bringe ich eigenhändig um, dieses Schwein!!"
  },
  AvgDialog_18767_Content_16 = {
    Text = "Eine zitternde Klinge presst sich augenblicklich an deine Kehle."
  },
  AvgDialog_18767_Content_17 = {Text = "...?"},
  AvgDialog_18767_Content_18 = {
    Text = "Erfolgreich in den Traum eingetreten — wenn auch nicht auf die Art, wie du es dir vorgestellt hattest."
  },
  AvgDialog_18767_Content_19 = {
    Text = "Vor dir steht eine dichte Menge halbnackter Sklaven. Ihre übliche Fügsamkeit ist längst verschwunden, ersetzt durch brennenden Hass in ihren Augen."
  },
  AvgDialog_18767_Content_2 = {
    Text = "Du meinst, du kannst in meinen Geist eindringen und die Vergangenheit verändern?"
  },
  AvgDialog_18767_Content_20 = {
    Text = "Angesichts Agrippas Drohung verstummten sie zunächst, brachen dann aber in Gelächter aus."
  },
  AvgDialog_18767_Content_21 = {
    Text = "Pfft. Hahahaha!"
  },
  AvgDialog_18767_Content_22 = {
    Text = "Na sowas, unsere kleine Prinzessin hat tatsächlich Mut!"
  },
  AvgDialog_18767_Content_23 = {
    Text = "Heh. Ihr glaubt mir nicht, oder...?"
  },
  AvgDialog_18767_Content_24 = {
    Text = "Ein schneller Hieb der Klinge, und dein Hals wird sofort von Schmerz durchzuckt."
  },
  AvgDialog_18767_Content_25 = {
    Text = "Hmm! Sie meint es ernst!!"
  },
  AvgDialog_18767_Content_26 = {
    Text = "<Big:Halt die Klappe!> Du und die stecken doch unter einer Decke. Du hast meinen Hausschlüssel und den Schuldschein gestohlen!"
  },
  AvgDialog_18767_Content_27 = {Text = "...?"},
  AvgDialog_18767_Content_28 = {
    Text = "Und ihr alle! Wenn noch jemand lacht, ritze ich eine weitere Linie in {Male=his,Female=her} Hals!"
  },
  AvgDialog_18767_Content_29 = {
    Text = "Leg das Messer weg, Agrippa... <Big:Laufen!>"
  },
  AvgDialog_18767_Content_3 = {
    Text = "Wenn du wirklich so mächtig bist, wie habe ich es dann geschafft, dich einzusperren?"
  },
  AvgDialog_18767_Content_31 = {
    Text = "Die Peitsche traf die Frau mit voller Wucht und schlug sie bewusstlos, bevor sie einen Laut von sich geben konnte."
  },
  AvgDialog_18767_Content_32 = {
    Text = "<Big:Mutter!!>"
  },
  AvgDialog_18767_Content_33 = {
    Text = "Steck deine lächerlichen Mätzchen weg; wir sind nicht mehr eure Sklaven."
  },
  AvgDialog_18767_Content_34 = {
    Text = "Warum hast du nicht an heute gedacht, als du damals auf dem Übungsplatz angegeben hast?"
  },
  AvgDialog_18767_Content_35 = {
    Text = "Mach die Augen auf und schau genau hin, „Kleine Prinzessin“. Sieh zu, wie wir dich demütigen..."
  },
  AvgDialog_18767_Content_36 = {
    Text = "<Shake:Feiglinge, ein Haufen Feiglinge! Wie könnt ihr es wagen...>"
  },
  AvgDialog_18767_Content_37 = {
    Text = "<Shake:Ich war es, die euch schikaniert hat, nicht sie... Nein, ich war zu dumm. Ich hätte euch nicht so behandeln sollen...>"
  },
  AvgDialog_18767_Content_38 = {
    Text = "<Shake:Kommt her, macht mit mir, was ihr wollt! Lasst einfach meine Mutter gehen...>"
  },
  AvgDialog_18767_Content_39 = {
    Text = "Das Mädchen war bereits so aufgelöst, dass sie nicht mehr zusammenhängend sprechen konnte, ihr Dolch zitterte heftig und drohte ihr aus der Hand zu gleiten."
  },
  AvgDialog_18767_Content_4 = {
    Text = "Ahem... Genau genommen ist es Einfluss, nicht Veränderung."
  },
  AvgDialog_18767_Content_40 = {
    Text = "Du stößt einen leisen Seufzer aus und nimmst ihr behutsam den Dolch aus der Hand."
  },
  AvgDialog_18767_Content_41 = {
    Text = "Fürchte dich nicht, Agrippa. Ich werde dir helfen."
  },
  AvgDialog_18767_Content_42 = {
    Text = "Hilf mir? Bist du nicht..."
  },
  AvgDialog_18767_Content_43 = {
    Text = "Du stellst dich vor Agrippa und blickst direkt auf die Sklaven vor dir."
  },
  AvgDialog_18767_Content_44 = {
    Text = "In Ordnung, die Spielzeit ist vorbei.\nIhr habt bekommen, was ihr wolltet, also könnt ihr jetzt gehen."
  },
  AvgDialog_18767_Content_45 = {
    Text = "Hey, da spielt sich einer als Boss auf und hält uns eine Predigt."
  },
  AvgDialog_18767_Content_46 = {
    Text = "Cress, solltest du nicht auf unserer Seite stehen?"
  },
  AvgDialog_18767_Content_47 = {
    Text = "Du schüttelst den Kopf."
  },
  AvgDialog_18767_Content_48 = {
    Text = "Es gibt noch immer meinen Respekt für euren Widerstand, aber niemand hat das Recht, Unschuldige zu töten."
  },
  AvgDialog_18767_Content_49 = {
    Text = "\"Unschuldig\"...?"
  },
  AvgDialog_18767_Content_5 = {
    Text = "Unterschätze dich nicht; dein Labyrinth ist viel komplexer, als ich dachte..."
  },
  AvgDialog_18767_Content_50 = {
    Text = "Hehe, der Kerl hat uns komplett verraten. Kein Grund, noch mehr Worte zu verschwenden."
  },
  AvgDialog_18767_Content_51 = {
    Text = "<Big:Töte ihn!>"
  },
  AvgDialog_18767_Content_6 = {
    Text = "Agrippa sieht dich misstrauisch an."
  },
  AvgDialog_18767_Content_7 = {
    Text = [[
In Ordnung, es gibt sowieso keinen anderen Weg.
Was muss ich tun?]]
  },
  AvgDialog_18767_Content_8 = {
    Text = "Du versuchst, dich an deinen Zustand bei jedem Eintritt in einen Traum zu erinnern, und hältst sanft Agrippas Hand."
  },
  AvgDialog_18767_Content_9 = {
    Text = "Hey, du! Versuchst du, mich auszunutzen?"
  },
  AvgDialog_18768_Content_1 = {
    Text = "Husten... Husten..."
  },
  AvgDialog_18768_Content_10 = {
    Text = "Der ferne Klang eines tiefen Horns erreicht dich; die Rebellen sind noch immer auf der Jagd."
  },
  AvgDialog_18768_Content_11 = {
    Text = "Du und Agrippa rennt Hand in Hand unter dem pechschwarzen Himmel."
  },
  AvgDialog_18768_Content_12 = {
    Text = "Ihre Familie ist nicht weit von euch entfernt. Getrieben von Angst und Hoffnung rennen sie auf einen Horizont zu, der kein Ende erkennen lässt."
  },
  AvgDialog_18768_Content_13 = {
    Text = "Wer bist du? Warum hast du mich gerettet?"
  },
  AvgDialog_18768_Content_14 = {
    Text = "Hmm... um genau zu sein, ging es darum, mich selbst zu retten."
  },
  AvgDialog_18768_Content_15 = {
    Text = "Oh... egal aus welchem Grund, du... hast das großartig gemacht."
  },
  AvgDialog_18768_Content_16 = {
    Text = "Wenn wir gerettet werden, gebe ich dir all das Geld und die Juwelen, die ich über die Jahre beiseitegeschafft habe."
  },
  AvgDialog_18768_Content_17 = {
    Text = "Du konntest nicht anders, als zu lachen."
  },
  AvgDialog_18768_Content_18 = {
    Text = "Ich brauche dein Geld nicht. Allerdings... wenn du dich revanchieren willst, habe ich eine Bitte."
  },
  AvgDialog_18768_Content_19 = {
    Text = "Sag schon, ich bin sicher, das schaffe ich."
  },
  AvgDialog_18768_Content_2 = {
    Text = "Aus Respekt vor alten Zeiten haben die Brüder darauf verzichtet, tödliche Gewalt anzuwenden."
  },
  AvgDialog_18768_Content_20 = {
    Text = "Eine Sternschnuppe zieht über den Nachthimmel — der perfekte Moment, um sich etwas zu wünschen."
  },
  AvgDialog_18768_Content_21 = {
    Text = "Meine Bitte ist einfach. Lächle weiter und erinnere dich daran, wie du dich gerade fühlst."
  },
  AvgDialog_18768_Content_22 = {
    Text = "Aktuelle Gefühle? Hmm... Glücklich, erleichtert, besorgt? Welches meinst du!"
  },
  AvgDialog_18768_Content_23 = {
    Text = "Ganz wie du willst. Ich bin gespannt, zu welchem Agrippa sie mich führen werden."
  },
  AvgDialog_18768_Content_24 = {Text = "?"},
  AvgDialog_18768_Content_25 = {
    Text = "<SmallShake:Dieser Kerl ist ein guter Mensch, aber er redet etwas seltsam...>"
  },
  AvgDialog_18768_Content_26 = {
    Text = "Der Klang der Hörner verblasste endlich, und die Stille der Nacht kehrte zurück."
  },
  AvgDialog_18768_Content_27 = {
    Text = "Schließlich... ist es vorbei."
  },
  AvgDialog_18768_Content_28 = {
    Text = "Das Mädchen rannte mit ein paar schnellen Schritten auf die Spitze der Düne, ballte die Fäuste und rief in die Richtung, in der das Horn verschwunden war."
  },
  AvgDialog_18768_Content_29 = {
    Text = "Damit habt ihr nicht gerechnet, ihr @2, ich habe es bis ganz zum Ende geschafft!"
  },
  AvgDialog_18768_Content_3 = {
    Text = "Da du darauf bestehst, ihnen zu helfen, gib uns nicht die Schuld, wenn wir unhöflich werden—"
  },
  AvgDialog_18768_Content_30 = {
    Text = "Hahaha, @2!"
  },
  AvgDialog_18768_Content_31 = {
    Text = "<Shake:Agrippa! Lady, Lady...!>"
  },
  AvgDialog_18768_Content_32 = {
    Text = "Kann nicht hören!!!"
  },
  AvgDialog_18768_Content_33 = {
    Text = "Zum Teufel mit dem Ladysein und der Etikette, ich bin endlich frei!!"
  },
  AvgDialog_18768_Content_34 = {
    Text = "Mit einer kraftvollen Erklärung breitete das Mädchen die Arme weit aus und hob den weiten Sternenhimmel über ihrem Kopf empor, als hielte sie ihn in ihren Händen."
  },
  AvgDialog_18768_Content_35 = {
    Text = "<Big:Freiheit—!!>"
  },
  AvgDialog_18768_Content_36 = {Text = "Krach—!!"},
  AvgDialog_18768_Content_37 = {Text = "...Hä?"},
  AvgDialog_18768_Content_38 = {
    Text = "Der Himmel verschwand, und das Labyrinth löste sich auf."
  },
  AvgDialog_18768_Content_39 = {
    Text = "Das Kambrisch-Tal liegt direkt vor ihnen."
  },
  AvgDialog_18768_Content_4 = {Text = "Bumm!"},
  AvgDialog_18768_Content_40 = {
    Text = "Der tiefe, spiegelgleiche See fließt still dahin, während der Wind über das Wasser streicht und Lichtreflexe erzeugt."
  },
  AvgDialog_18768_Content_41 = {
    Text = "Agrippa saß benommen im Gras und starrte fassungslos auf alles vor ihm."
  },
  AvgDialog_18768_Content_42 = {
    Text = "%player%, sind wir... hier draußen?"
  },
  AvgDialog_18768_Content_43 = {
    Text = "Willkommen zurück in der realen Welt, Agrippa."
  },
  AvgDialog_18768_Content_44 = {Text = "...Oh."},
  AvgDialog_18768_Content_45 = {
    Text = "Das ist also das Flusstal. Es ist hundertmal schöner, als die Leute sagen, nein, tausendmal schöner."
  },
  AvgDialog_18768_Content_46 = {
    Text = "Das schwache Morgenlicht durchdringt den Nebel und scheint auf euren Körper."
  },
  AvgDialog_18768_Content_47 = {
    Text = "Agrippa schloss die Augen und sog gierig die lang vermissten Düfte ein."
  },
  AvgDialog_18768_Content_48 = {
    Text = "Ich rieche so vieles. Erde, Gras, Freesien und Sonnenschein..."
  },
  AvgDialog_18768_Content_49 = {
    Text = "Hat Sonnenlicht einen Geschmack?"
  },
  AvgDialog_18768_Content_5 = {
    Text = "Du nutzt das Chaos, um den Pfeiler vor dir umzustoßen, wodurch das gesamte Gebäude bedrohlich ins Schwanken gerät."
  },
  AvgDialog_18768_Content_50 = {
    Text = "Hmm. Der Duft macht einen ganz schläfrig."
  },
  AvgDialog_18768_Content_51 = {
    Text = "Vielen Dank, %player%."
  },
  AvgDialog_18768_Content_52 = {
    Text = "Sie streckte sich und summte leise eine altrömische Melodie."
  },
  AvgDialog_18768_Content_53 = {
    Text = "Eine leichte Melodie wirbelte durch die Luft und verbreitete die fröhliche Stimmung ihrer Besitzerin in jeden Winkel des Tals."
  },
  AvgDialog_18768_Content_54 = {
    Text = "Nach mehr als tausend Jahren erblickte sie endlich wieder das Sonnenlicht."
  },
  AvgDialog_18768_Content_55 = {
    Text = "Und sah schließlich zum ersten Mal das Flusstal."
  },
  AvgDialog_18768_Content_6 = {
    Text = "Jetzt, folgt mir schnell!"
  },
  AvgDialog_18768_Content_7 = {
    Text = "Du ergreifst Agrippas Hand und verlässt eilig mit ihrer Familie den Ort."
  },
  AvgDialog_18768_Content_8 = {
    Text = "Dieser einst unglaublich prächtige Innenhof stürzte wie ein stilles, gewaltiges Ungetüm in sich zusammen."
  },
  AvgDialog_18768_Content_9 = {
    Text = "16 Jahre vor der Flut @1, Außenbezirke von Kapua"
  },
  AvgDialog_18769_Content_1 = {
    Text = "Erinnerungsbarriere"
  },
  AvgDialog_18769_Content_10 = {
    Text = "Du@1, was sagst du da—"
  },
  AvgDialog_18769_Content_11 = {
    Text = "Vergiss es, lass dich nicht mit dem Kerl ein. Er ist einfach nur ein Verrückter..."
  },
  AvgDialog_18769_Content_12 = {
    Text = "Die Sklaven drängten sich aneinander vorbei, als sie gingen, und die dunkle Zelle wurde endlich still."
  },
  AvgDialog_18769_Content_13 = {
    Text = "Das Mädchen trat aus dem Schatten in der Ecke ihrer Zelle hervor, den Kopf gesenkt."
  },
  AvgDialog_18769_Content_14 = {
    Text = "Warum gehst du nicht mit ihnen? Heute Nacht ist deine Chance, die Freiheit zurückzuerlangen."
  },
  AvgDialog_18769_Content_15 = {
    Text = "Es gefällt mir hier. Warum sollte ich gehen?"
  },
  AvgDialog_18769_Content_16 = {
    Text = "Es gefällt dir...? Haha, beeindruckend. Wirst du lieber beschimpft, oder magst du das Gefühl meiner Peitsche?"
  },
  AvgDialog_18769_Content_17 = {
    Text = "Der Gladiator gähnte und streckte sich behaglich."
  },
  AvgDialog_18769_Content_18 = {
    Text = "Ich liebe Blut, und das Töten liebe ich noch mehr. Für mich ist Töten Freiheit."
  },
  AvgDialog_18769_Content_19 = {
    Text = "Was den Titel eines Sklaven angeht — mir ist egal, wie viele ihr mir gebt. Warum sollte ich gehen?"
  },
  AvgDialog_18769_Content_2 = {
    Text = "16 Jahre vor der Großen Flut, Jahr 1, Capua"
  },
  AvgDialog_18769_Content_20 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18769_Content_21 = {
    Text = "Ha... jetzt sehe ich dich in einem anderen Licht. Du bist ein echter Verrückter"
  },
  AvgDialog_18769_Content_22 = {
    Text = "Agrippa blickte ruhig zum Ausgang des Kerkers"
  },
  AvgDialog_18769_Content_23 = {
    Text = "Scharlachrote Flammen schießen in den Himmel, Lachen, Weinen, Schreien... eine Höllensymphonie"
  },
  AvgDialog_18769_Content_24 = {
    Text = "Bald werden sie mich finden, @1 mich, und mir den Kopf abschlagen, wie sie es bei meinen Eltern getan haben"
  },
  AvgDialog_18769_Content_25 = {
    Text = "Ich will nicht, dass diese niederen Kreaturen mir nahe kommen. Aber du"
  },
  AvgDialog_18769_Content_26 = {
    Text = "Du bist anders als sie.\nIch weiß, dass wir vorher einige „Differenzen“ hatten, aber diesmal wirst du meine Bitte nicht ablehnen"
  },
  AvgDialog_18769_Content_27 = {
    Text = "Oh? Erzähl mal"
  },
  AvgDialog_18769_Content_28 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18769_Content_29 = {
    Text = "Töte mich."
  },
  AvgDialog_18769_Content_3 = {
    Text = "Verdammt, die Frau ist verschwunden."
  },
  AvgDialog_18769_Content_30 = {
    Text = "<RedBig:Töte mich...>"
  },
  AvgDialog_18769_Content_31 = {
    Text = "Agrippa...?"
  },
  AvgDialog_18769_Content_32 = {
    Text = "<RedBig:Töte mich töte mich töte mich töte mich töte mich töte mich töte mich...>"
  },
  AvgDialog_18769_Content_33 = {Text = "Agrippa!"},
  AvgDialog_18769_Content_34 = {Text = "!!"},
  AvgDialog_18769_Content_35 = {
    Text = "<Shake:Ugh...>"
  },
  AvgDialog_18769_Content_36 = {
    Text = "Ich hatte einen sehr langen Traum"
  },
  AvgDialog_18769_Content_37 = {
    Text = "Hör zu, wir scheinen gerade einige Fragen übersehen zu haben"
  },
  AvgDialog_18769_Content_38 = {
    Text = "Unsinn! Ich bin der Herr des Labyrinths, alles ist unter Kontrolle—"
  },
  AvgDialog_18769_Content_39 = {
    Text = "Erstens, warum können deine Nachkommen das Labyrinth frei betreten und verlassen, wir aber nicht?"
  },
  AvgDialog_18769_Content_4 = {
    Text = "Heh, du versteckst dich also? Sobald wir sie finden, hacken wir ihr zuerst die Beine ab..."
  },
  AvgDialog_18769_Content_40 = {
    Text = "Könnt ihr nicht Gedanken teilen?"
  },
  AvgDialog_18769_Content_41 = {
    Text = "Was verstehst du schon? Als Herr des Labyrinths muss ich stets geheimnisvoll bleiben"
  },
  AvgDialog_18769_Content_42 = {
    Text = "Außerdem, wenn ich will, kommen sie alle brav zurück, was ist das für ein freier Zugang?"
  },
  AvgDialog_18769_Content_43 = {
    Text = "Du nickst und holst erneut dein Notizbuch hervor."
  },
  AvgDialog_18769_Content_44 = {
    Text = "Noch eine Frage."
  },
  AvgDialog_18769_Content_45 = {
    Text = "Ich habe alle Orte notiert, denen ich im Labyrinth begegnet bin: die Schule, das Wachsfigurenkabinett und die Straßen von Lentiniën..."
  },
  AvgDialog_18769_Content_46 = {
    Text = "Keiner der Orte, die du nicht erlebt hast. Kein einziger."
  },
  AvgDialog_18769_Content_47 = {
    Text = "Wieso, bist du nicht auch hier gefangen?"
  },
  AvgDialog_18769_Content_48 = {
    Text = "Warum so viele „Warums\"? Weil dieser große König sich nicht erinnern will! Warum sich mit unangenehmen Dingen beschäftigen?"
  },
  AvgDialog_18769_Content_49 = {
    Text = "Ja, <Yellow:du willst dich nicht erinnern>."
  },
  AvgDialog_18769_Content_5 = {
    Text = "Hey, Uvhash, hast du Agrippa gesehen?"
  },
  AvgDialog_18769_Content_50 = {
    Text = "Besteht die Möglichkeit, dass..."
  },
  AvgDialog_18769_Content_51 = {
    Text = "Gerade weil du dich weigerst — weil der Meister des Labyrinths das geteilte Bewusstsein ablehnt — bleibt dieses Labyrinth, geformt aus den Gedanken der Gefangenen, für immer unvollständig."
  },
  AvgDialog_18769_Content_52 = {
    Text = "Also können wir niemals entkommen."
  },
  AvgDialog_18769_Content_53 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18769_Content_54 = {
    Text = "Ich habe über diese Fragen schon nachgedacht. Das ist mein Labyrinth."
  },
  AvgDialog_18769_Content_55 = {
    Text = "Einfach an die Vergangenheit zu denken macht mich wahnsinnig..."
  },
  AvgDialog_18769_Content_56 = {
    Text = "Agrippa umklammerte seinen Kopf und murmelte hastig, als wäre er in einem Traum."
  },
  AvgDialog_18769_Content_57 = {
    Text = "Diese verabscheuungswürdigen Elenden... Wie können sie es wagen, mich so zu behandeln..."
  },
  AvgDialog_18769_Content_58 = {
    Text = "Einfach ein Haufen Sklaven, nicht einmal würdig, Menschen genannt zu werden, dazu bestimmt, für alle Ewigkeit von uns mit Füßen getreten zu werden."
  },
  AvgDialog_18769_Content_59 = {
    Text = "Rebellion? Was für eine Fantasie."
  },
  AvgDialog_18769_Content_6 = {
    Text = "Der Gladiator im Schatten öffnete langsam seine Augen."
  },
  AvgDialog_18769_Content_60 = {
    Text = "Aber sie haben nicht einfach dort aufgehört. Sie hängten die Köpfe meiner Eltern an die Stadtmauer, packten mich an den Haaren und zwangen mich, jedes Detail genau zu betrachten, ohne ein einziges auszulassen."
  },
  AvgDialog_18769_Content_61 = {
    Text = "Und meine Schwester, Yulia. Als ich sie fand, war sie bedeckt mit @3, und sie war so klein..."
  },
  AvgDialog_18769_Content_62 = {
    Text = "Wie lächerlich... Hast du wirklich geglaubt, ich würde weinen?"
  },
  AvgDialog_18769_Content_63 = {
    Text = "Nein, unmöglich. Lieber sterbe ich, als auch nur eine einzige Träne vor ihnen zu vergießen."
  },
  AvgDialog_18769_Content_64 = {
    Text = "Wir sind Nachfahren grauer Wölfe. Wir werden in Würde sterben, wie wahre Wölfe—etwas, das diese Köter niemals verstehen werden."
  },
  AvgDialog_18769_Content_65 = {Text = "Hahaha..."},
  AvgDialog_18769_Content_66 = {
    Text = "Agrippa hielt sich den Bauch und lachte, bis ihr die Tränen kamen."
  },
  AvgDialog_18769_Content_67 = {
    Text = "Die müssen so enttäuscht gewesen sein, als sie meine Leiche sahen... Haha..."
  },
  AvgDialog_18769_Content_68 = {
    Text = "Agrippa...? Agrippa!"
  },
  AvgDialog_18769_Content_69 = {
    Text = "Du packst Agrippas Schulter fest und versuchst, sie aus den Albträumen der Vergangenheit zurückzuholen."
  },
  AvgDialog_18769_Content_7 = {
    Text = "... Verschwinde."
  },
  AvgDialog_18769_Content_70 = {
    Text = "Das ist alles Vergangenheit. Kein Grund, davon zu sprechen."
  },
  AvgDialog_18769_Content_71 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18769_Content_72 = {
    Text = "Verzeih, Agrippa. Ich wusste das vorher nicht... Lass uns diese unangenehmen Dinge einfach hinter uns lassen."
  },
  AvgDialog_18769_Content_73 = {
    Text = "Du bist die Herrin des Labyrinths; nichts kann dir wirklich etwas anhaben."
  },
  AvgDialog_18769_Content_74 = {Text = "...Hmm."},
  AvgDialog_18769_Content_75 = {
    Text = "Agrippa verstummte ungewöhnlicherweise; es scheint, als hätte sie sich noch nicht aus den Schatten der Vergangenheit gelöst."
  },
  AvgDialog_18769_Content_76 = {
    Text = "<LightGray:Wenn wir doch nur die Vergangenheit ändern könnten... Dann könnten wir ihr helfen und dieser Notlage entkommen.>"
  },
  AvgDialog_18769_Content_77 = {
    Text = "<LightGray:Nein, verlier nicht den Mut. Versuch, einen anderen Weg zu finden...>"
  },
  AvgDialog_18769_Content_78 = {
    Text = "Du durchsuchst verzweifelt deine bruchstückhaften Erinnerungen nach nützlichen Informationen."
  },
  AvgDialog_18769_Content_79 = {
    Text = "Träumen kann die Vergangenheit nicht ändern, aber es kann die Zukunft beeinflussen. Daher müssen Hüter lernen, beim Träumen Zurückhaltung zu üben."
  },
  AvgDialog_18769_Content_8 = {
    Text = "Heh, während alle anderen für eine edle Sache kämpfen, bist du der Einzige, der bereit ist zu bleiben und den treuen Hund zu spielen."
  },
  AvgDialog_18769_Content_80 = {
    Text = "Die Zukunft beeinflussen?"
  },
  AvgDialog_18769_Content_81 = {
    Text = "Zum Beispiel ist die menschliche Erinnerung wie ein stiller See."
  },
  AvgDialog_18769_Content_82 = {
    Text = "In einen Traum einzutreten ist, als würfe man einen Stein ins Wasser; die Wellen verschwinden bald."
  },
  AvgDialog_18769_Content_83 = {
    Text = "Aber der Stein ist immer noch da."
  },
  AvgDialog_18769_Content_84 = {
    Text = "Ganz recht. Selbst wenn die Person, die in den Traum eingetreten ist, sich nach dem Aufwachen an nichts erinnert..."
  },
  AvgDialog_18769_Content_85 = {
    Text = "Der Stein wird für immer in sein Unterbewusstsein sinken und seine Gegenwart beeinflussen."
  },
  AvgDialog_18769_Content_86 = {Text = "!!!"},
  AvgDialog_18769_Content_87 = {
    Text = "Agrippa, ich kenne den Weg hinaus."
  },
  AvgDialog_18769_Content_9 = {
    Text = "Ich sagte: „Haut ab.\" Versteht ihr das nicht?"
  },
  AvgDialog_18770_Content_1 = {
    Text = "Ihr Königreich"
  },
  AvgDialog_18770_Content_10 = {
    Text = "Zwecklos, zwecklos! Selbst Mathematiker, diese klugen Köpfe, waren damals im Labyrinth gefangen!"
  },
  AvgDialog_18770_Content_11 = {
    Text = "Verschwende deine Mühe nicht an Rätsel, die niemand lösen kann."
  },
  AvgDialog_18770_Content_12 = {
    Text = "Wenn du mich fragst, da keiner von uns den anderen töten kann, könnten wir uns genauso gut vertragen."
  },
  AvgDialog_18770_Content_13 = {
    Text = "Lass uns plaudern! Oder Karten spielen. Welche Kartenspiele kennst du?"
  },
  AvgDialog_18770_Content_14 = {
    Text = "Lass dich nicht von meiner Zeit unter der Erde täuschen; ich habe Kartenspiele gemeistert wie kein anderer!"
  },
  AvgDialog_18770_Content_15 = {
    Text = "Du musst zugeben, ihre Worte haben dich ein wenig verletzt."
  },
  AvgDialog_18770_Content_16 = {
    Text = "Wenn niemand dieses Labyrinth seit so vielen Jahren gelöst hat, was lässt dich glauben, dass du es kannst?"
  },
  AvgDialog_18770_Content_17 = {
    Text = "Du hast nicht den scharfen Verstand, den Ramona hat."
  },
  AvgDialog_18770_Content_18 = {
    Text = "Bei diesem Gedanken lässt du dich auf das weiche Kissen fallen."
  },
  AvgDialog_18770_Content_19 = {
    Text = "Ich bin nicht besonders gut im Kartenspielen. Wie wäre es, wenn wir uns stattdessen unterhalten?\nWie bist du in diesem Labyrinth gefangen gelandet?"
  },
  AvgDialog_18770_Content_2 = {
    Text = "39, 40, 41..."
  },
  AvgDialog_18770_Content_20 = {Text = "Äh"},
  AvgDialog_18770_Content_21 = {
    Text = "Als ob sie deine Frage nicht erwartet hätte, hielten die facettenreichen Augen in den Augenhöhlen des Mädchens gemeinsam einen Moment inne."
  },
  AvgDialog_18770_Content_22 = {
    Text = "Wie du gesagt hast, wir müssen gut miteinander auskommen. Daher ist Ehrlichkeit der erste Schritt."
  },
  AvgDialog_18770_Content_23 = {
    Text = "Ich erzähl's, ich erzähl's...! Es ist nur eine abgedroschene Geschichte."
  },
  AvgDialog_18770_Content_24 = {
    Text = "Damals war meine Familie die wohlhabendste in Kapua, mit einer Reihe von Dienern hinter mir, so weit das Auge reichte..."
  },
  AvgDialog_18770_Content_25 = {
    Text = "Später haben diese Narren eine Revolution angezettelt, redeten von „Befreiung“ und „Freiheit“ — Dinge, die ich sowieso nicht verstehe."
  },
  AvgDialog_18770_Content_26 = {
    Text = "Ich weigere mich, durch ihre Hände zu sterben; lasst einen Gladiator derjenige sein, der mich tötet."
  },
  AvgDialog_18770_Content_27 = {
    Text = "Agrippa sprach und breitete seine Hände in deine Richtung aus."
  },
  AvgDialog_18770_Content_28 = {
    Text = "...Als ich aufwachte, fand ich mich hier wieder."
  },
  AvgDialog_18770_Content_29 = {
    Text = "Ich habe von dieser Revolution im Geschichtsunterricht gehört. Man sagt —"
  },
  AvgDialog_18770_Content_3 = {
    Text = "Du notierst schnell die Angaben im Notizbuch des Seniorstudenten: <Blue:Schülerwohnheim: 41>"
  },
  AvgDialog_18770_Content_30 = {
    Text = "Kein Interesse. Dieses Thema ist wirklich langweilig! Wechsel es, wechsel es."
  },
  AvgDialog_18770_Content_31 = {
    Text = "Eine Stunde später..."
  },
  AvgDialog_18770_Content_32 = {
    Text = "Das sinnlose Gespräch ging weiter, bis Agrippa das Thema schließlich wieder auf sich selbst lenkte."
  },
  AvgDialog_18770_Content_33 = {
    Text = "Wusstest du? Ich habe jetzt über tausend Nachkommen unter meinem Kommando..."
  },
  AvgDialog_18770_Content_34 = {
    Text = "Sie können das Labyrinth frei betreten und verlassen, Geschichten aus der Außenwelt für mich sammeln und unglückliche Seelen zurückbringen, die geeignet sind, Nachkommen zu werden."
  },
  AvgDialog_18770_Content_35 = {
    Text = "Wenn sie nicht wären, wäre ich vor Langeweile gestorben."
  },
  AvgDialog_18770_Content_36 = {
    Text = "Du hörst ihren unaufhörlichen Beschwerden zu, und aus irgendeinem Grund kommt dir eine Szene in den Sinn—"
  },
  AvgDialog_18770_Content_37 = {
    Text = "Der alternde König stützt sich auf seinen Stock und sinkt tief in den morschen, schweren Thron."
  },
  AvgDialog_18770_Content_38 = {
    Text = "Sein Reich ist grenzenlos, und seine Autorität steht außer Frage."
  },
  AvgDialog_18770_Content_39 = {
    Text = "Er sandte viele Gesandte aus, um Geschichten aus der Ferne mitzubringen: smaragdgrüne Katzenaugen, verschwundene Elefanten und Regenbögen nach dem Regen..."
  },
  AvgDialog_18770_Content_4 = {
    Text = "Hör auf, Zeit zu verschwenden, und komm mit mir spielen!"
  },
  AvgDialog_18770_Content_40 = {
    Text = "Als der Gesandte zu einer aufregenden Stelle kommt, fuchtelt er freudig mit den Armen. Der König jedoch bleibt stumm, wie eine moosbedeckte Skulptur."
  },
  AvgDialog_18770_Content_41 = {
    Text = "Er kann nichts tun, denn er kann den Thron nicht einmal mehr für einen einzigen Schritt verlassen."
  },
  AvgDialog_18770_Content_42 = {
    Text = "Agrippa, du hast so viele Geschichten von draußen gehört... Gibt es einen Ort, an den du gehen möchtest?"
  },
  AvgDialog_18770_Content_43 = {
    Text = "Der Ort, an den ich gehen möchte..."
  },
  AvgDialog_18770_Content_44 = {
    Text = "<Blue:Kambrisch-Tal> wäre einer davon."
  },
  AvgDialog_18770_Content_45 = {
    Text = "Agrippa antwortete fast ohne nachzudenken."
  },
  AvgDialog_18770_Content_46 = {
    Text = "Meine Nachkommen haben mir erzählt, dass das Zentrum dieses Labyrinths sich unter einem Tal namens Kambrisch zu befinden scheint."
  },
  AvgDialog_18770_Content_47 = {
    Text = "Ich habe gehört, es sei ein wunderschöner Ort mit Seen, so klar wie Spiegel."
  },
  AvgDialog_18770_Content_48 = {
    Text = "Jeden Frühling blüht dort überall eine Blume namens Freesie..."
  },
  AvgDialog_18770_Content_49 = {
    Text = "Agrippa stützt ihr Kinn auf die Hand und blickt in die Ferne."
  },
  AvgDialog_18770_Content_5 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18770_Content_50 = {
    Text = "Es gibt auch einen wunderschönen See in meiner Heimat, aber ich habe ihn nie gesehen."
  },
  AvgDialog_18770_Content_51 = {
    Text = "Warum schaust du ihn dir nicht an?"
  },
  AvgDialog_18770_Content_52 = {
    Text = "Agrippa warf dir einen hochmütigen Blick zu und hob ihr spitzes kleines Kinn."
  },
  AvgDialog_18770_Content_53 = {
    Text = "Ich bin eine römische Dame von edler Geburt, und eine Dame sollte nicht frei umherwandern."
  },
  AvgDialog_18770_Content_54 = {
    Text = "Du kannst also über viele Sklaven gebieten, und doch bist du selbst nicht völlig frei."
  },
  AvgDialog_18770_Content_55 = {
    Text = "Deine Worte durchdringen die Wirklichkeit, und das Gesicht des Mädchens verfällt augenblicklich, wie eine vom Frost getroffene Aubergine."
  },
  AvgDialog_18770_Content_56 = {
    Text = "Damals ging es mir schlechter als diesen Sklaven. Ganz zu schweigen von jetzt..."
  },
  AvgDialog_18770_Content_6 = {
    Text = "Entschuldigung, könntest du dein Gesicht ändern, bevor du mit mir redest?"
  },
  AvgDialog_18770_Content_7 = {
    Text = "Tss, so geizig!"
  },
  AvgDialog_18770_Content_8 = {
    Text = "„Wilhelm“ verdrehte die Augen und verschwand dann mit einem „Puff“ in Luft."
  },
  AvgDialog_18770_Content_9 = {
    Text = "Du hältst den Kopf gesenkt und vertiefst dich in die dichten Aufzeichnungen, um einen Weg zu finden, das Labyrinth zu knacken."
  },
  AvgDialog_18779_Content_1 = {
    Text = "Das, das ist der Embryo?"
  },
  AvgDialog_18779_Content_10 = {
    Text = [[
Es absorbiert Energie von Miryam?!  
Muss es noch einmal kommen?]]
  },
  AvgDialog_18779_Content_11 = {
    Text = "Nutzlos.\nEs wird vom „Plazenta\" geschützt, und die Kraft von Miryam kann die Plazenta mindestens drei weitere Male reparieren"
  },
  AvgDialog_18779_Content_12 = {
    Text = "Um es vollständig zu zerstören, muss man den wahren Kern direkt angreifen"
  },
  AvgDialog_18779_Content_13 = {Text = "Kern?"},
  AvgDialog_18779_Content_14 = {
    Text = "Das bleiche Herz war in den durchsichtigen Kokon eingewoben. Im Mondschein war der Schatten von „Ihm\" darin zu erahnen"
  },
  AvgDialog_18779_Content_15 = {
    Text = "Ist es das „Fälschung\" selbst?"
  },
  AvgDialog_18779_Content_16 = {
    Text = "Ja, und nein"
  },
  AvgDialog_18779_Content_17 = {
    Text = "Ja... Murphy?"
  },
  AvgDialog_18779_Content_18 = {Text = "Ja. Genau!"},
  AvgDialog_18779_Content_19 = {
    Text = "Miryam zwang die Zeremonie vorzeitig, doch „Er\" wurde aus Lügen und Wünschen geboren, und bevor die Sterne in der richtigen Ausrichtung stehen, wird seine Existenz nicht von der Realität anerkannt"
  },
  AvgDialog_18779_Content_2 = {
    Text = "Es scheint still zu sein"
  },
  AvgDialog_18779_Content_20 = {
    Text = "Vor der Geburt war der Kern immer noch sie"
  },
  AvgDialog_18779_Content_3 = {
    Text = "Es ist noch nicht vorbei."
  },
  AvgDialog_18779_Content_4 = {
    Text = "„Das 'Herz' hat aufgehört zu schlagen, aber das leise Wimmern des Meereswindes ist nicht zu überhören.\""
  },
  AvgDialog_18779_Content_5 = {
    Text = "Habt ihr das Weinen gehört?"
  },
  AvgDialog_18779_Content_6 = {
    Text = "Die Wellen toben, der riesige Kokon erhebt sich plötzlich unter der Unterstützung von Miryam aus dem Meer"
  },
  AvgDialog_18779_Content_7 = {
    Text = "Ja, genau so"
  },
  AvgDialog_18779_Content_8 = {
    Text = "Es ist dein Recht, zu nehmen, was du willst, für deine Geburt, um diese Ungläubigen zu bestrafen"
  },
  AvgDialog_18779_Content_9 = {
    Text = "Miryams Stimme wurde immer schwächer, doch das Wesen in der schlafenden Puppe wurde immer fester"
  },
  AvgDialog_18784_Content_10 = {
    Text = "Wie bedauerlich, allein der Verlust der Silber-Verbindung hat dich in einen solchen Zustand versetzt."
  },
  AvgDialog_18784_Content_11 = {
    Text = "Das Monster des Eiterballs ignoriert die Provokationen Lotans und stürmt einfach brüllend auf den Feind zu"
  },
  AvgDialog_18784_Content_12 = {
    Text = "<Change> Gib sie... mir..."
  },
  AvgDialog_18784_Content_13 = {
    Text = "Solange wir das Mädchen fangen... solange wir Zwillingspriesterinnen werden"
  },
  AvgDialog_18784_Content_14 = {
    Text = "Dann wird sie nicht verlassen, muss nicht über ihre Herkunft klagen und wird nicht als Schachfigur herumkommandiert"
  },
  AvgDialog_18784_Content_17 = {
    Text = "<Change>Übergebe sie... mir!"
  },
  AvgDialog_18784_Content_18 = {
    Text = "Hast du auch die Fähigkeit zu kommunizieren verloren?"
  },
  AvgDialog_18784_Content_19 = {
    Text = "Wenn das so ist, dann lege deine Worte und Gefühle in dein Schwert.\nLass mich deinen Zorn hören!"
  },
  AvgDialog_18784_Content_2 = {
    Text = "<BigShake:Roar——>"
  },
  AvgDialog_18784_Content_3 = {
    Text = "Ihr geht eine Weile im Dunkeln, als ein klebriges Monster aus dem Brückentunnel auftaucht, seinen massiven Körper mit unzähligen Schleimkugeln schleppend, und vor euch landet"
  },
  AvgDialog_18784_Content_4 = {
    Text = "Das Monster hob seinen kaum menschlichen Oberkörper und sah euch an, sein Blick blieb auf Lily haften, und es wurde zunehmend wahnsinnig"
  },
  AvgDialog_18784_Content_6 = {
    Text = "Überlasst sie... mir!"
  },
  AvgDialog_18784_Content_7 = {
    Text = "Lotan stellte sich vor euch auf und sah stolz dem Monster in die Augen"
  },
  AvgDialog_18784_Content_8 = {
    Text = "Die Fesseln zerbrechen, der Körper schwillt an und verformt sich, nur das schmutzige Gesicht unter dem wirren Haar beweist noch die Identität des Körpers"
  },
  AvgDialog_18784_Content_9 = {
    Text = "Bist du... Helot"
  },
  AvgDialog_18785_Content_1 = {
    Text = "Verdrehte Realität"
  },
  AvgDialog_18785_Content_10 = {
    Text = "Im Licht sah sie unzählige schwarze Wunden auf der glatten Haut der „Mutter\""
  },
  AvgDialog_18785_Content_11 = {
    Text = "„Es tut mir leid...“"
  },
  AvgDialog_18785_Content_12 = {
    Text = "Schwarzer Schleim brodelte und störte die Ruhe am Grund des Teiches"
  },
  AvgDialog_18785_Content_13 = {
    Text = "„Die „Mutter„ stieß einen schrillen Schrei aus, ihre Gliedmaßen bewegten sich und schoben etwas in die Brust des Kükens.„"
  },
  AvgDialog_18785_Content_14 = {
    Text = "Die glitschigen, kalten, weichen Tentakel umschlingen sie, das schwarze Wasser hält ihren Mund und ihre Nase nicht mehr zu, sondern hebt ihr Leben wie Fruchtwasser"
  },
  AvgDialog_18785_Content_15 = {
    Text = "<Change>„Es tut mir leid...\"\n„Ich will noch nicht... sterben...\""
  },
  AvgDialog_18785_Content_16 = {
    Text = "Die Wasseroberfläche blieb lange ruhig, selbst der heulende Wind der Pole konnte das zähe Wasser nicht kräuseln"
  },
  AvgDialog_18785_Content_17 = {
    Text = "Miryam milady, wird die Heilige vielleicht schon"
  },
  AvgDialog_18785_Content_18 = {
    Text = "Sie wurde während des letzten Sternenausrichtung geboren und ist ein „sehendes“ Kind"
  },
  AvgDialog_18785_Content_19 = {
    Text = "Niemand auf der Welt verdient es mehr, das Blut der Götter zu erhalten, als sie"
  },
  AvgDialog_18785_Content_2 = {
    Text = "Das Küken mit gebrochenen Flügeln fiel in den schwarzen Teich"
  },
  AvgDialog_18785_Content_20 = {
    Text = "Die dürre Frau wird umringt und steht an der höchsten Stelle, von der aus sie alle überblicken kann.\nEin Schleier verdeckt ihr Gesicht, selbst die engsten Diener können ihre Gedanken nicht lesen"
  },
  AvgDialog_18785_Content_21 = {Text = "Murphy..."},
  AvgDialog_18785_Content_3 = {
    Text = "Die flüsternden Gebete des Hohepriesters waren schwebend und fest, seine fanatischen Worte durchdrangen die schwarze Flüssigkeit und wurden zu Klingen, die die Brust des Kükens aufschlitzten"
  },
  AvgDialog_18785_Content_4 = {
    Text = "Rot leuchtende Flüssigkeit steigt aus der Brust auf und breitet sich auf der ruhigen schwarzen Wasseroberfläche aus—"
  },
  AvgDialog_18785_Content_5 = {
    Text = "Sie sank immer tiefer, die blutigen Wurzeln zogen sie in die Tiefe, in eine weiche und kalte Umarmung"
  },
  AvgDialog_18785_Content_6 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18785_Content_7 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18785_Content_8 = {
    Text = "Sie sah es.\nSie blickte nach oben. „Mutter\" ließ drei Augenstiele herunter und sah sie an"
  },
  AvgDialog_18785_Content_9 = {
    Text = "Das war ein riesiges, tiefrotes Wesen, dessen blutbefleckte Stellen transparent weiß waren. „Die Mutter\" strahlte schwach und erhellte einen kleinen Bereich"
  },
  AvgDialog_18786_Content_1 = {
    Text = "Video einblenden"
  },
  AvgDialog_18786_Content_2 = {
    Text = "Video-Schleife 1"
  },
  AvgDialog_18786_Content_3 = {
    Text = "Video-Schleife 2"
  },
  AvgDialog_18786_Content_4 = {
    Text = "Video Ausblende"
  },
  AvgDialog_18786_Content_5 = {Text = "Nichts"},
  AvgDialog_18787_Content_1 = {
    Text = "Aber jetzt gibt es dringendere Dinge"
  },
  AvgDialog_18787_Content_10 = {
    Text = "Das ist das Mädchen, das Herbert verfolgt. Sie könnte Hinweise auf eure Untersuchung haben"
  },
  AvgDialog_18787_Content_11 = {
    Text = "Los, worauf wartet ihr noch?\nWollt ihr die ganze Nacht draußen mit den Wölfen heulen?"
  },
  AvgDialog_18787_Content_12 = {
    Text = "Wenn du draußen übernachten willst, bin ich dabei. Aber ich fürchte, dein zarter Körper hält das nicht aus"
  },
  AvgDialog_18787_Content_13 = {
    Text = "Lotan klopfte Ramona auf die Schulter, Ramona machte einen Gesichtsausdruck, als hätte sie eine Fliege geschluckt, sagte aber nichts"
  },
  AvgDialog_18787_Content_14 = {
    Text = "Narzissenfrau...... klingt wie eine gutherzige reiche Person, oder?"
  },
  AvgDialog_18787_Content_2 = {Text = "?"},
  AvgDialog_18787_Content_3 = {
    Text = "Wenn du nicht vorhast, den Schnee als Decke zu benutzen, solltest du darüber nachdenken, wo wir heute Nacht schlafen, Hüter"
  },
  AvgDialog_18787_Content_4 = {
    Text = "<Italic:Großer Bruder, große Schwester, seid ihr von weit her gekommen?>"
  },
  AvgDialog_18787_Content_5 = {
    Text = "Eine kindliche Stimme unterbrach euer Gespräch"
  },
  AvgDialog_18787_Content_6 = {
    Text = "Wer ist da?"
  },
  AvgDialog_18787_Content_7 = {
    Text = "Der Schnee an der Wand reflektiert das helle Mondlicht, und in der Mitte steht ein Mädchen, das noch weißer ist als das Mondlicht"
  },
  AvgDialog_18787_Content_8 = {
    Text = "Wenn du keinen Platz zum Übernachten findest, kannst du vorübergehend im <Blue:Narzissenfrau>'s Zimmer bleiben.\nEs ist gleich um die Ecke."
  },
  AvgDialog_18787_Content_9 = {
    Text = "Du gibst Ramona ein Zeichen, und sie erwidert es mit einem zustimmenden Blick"
  },
  AvgDialog_18790_Content_1 = {
    Text = "Ihr kämpft euch bis zum Bug durch, aber bevor ihr ins Meer schauen könnt, neigt sich das Schiff durch einen weiteren Aufprall von unten"
  },
  AvgDialog_18790_Content_2 = {
    Text = "Das Frachtschiff hebt und senkt sich mit den Wellen, etwas bricht durch die Wasseroberfläche—"
  },
  AvgDialog_18790_Content_3 = {Text = "Murphy!"},
  AvgDialog_18790_Content_4 = {
    Text = "Der Schlangenkopf hielt fest den Körper des Mädchens, Miryam konnte nur mit einer heiseren Stimme beten"
  },
  AvgDialog_18790_Content_5 = {
    Text = "Ph'nglui mglw'nafh @3..."
  },
  AvgDialog_18790_Content_6 = {
    Text = "Sie hob Murphy im Mondlicht hoch, kleine schwarze Hände krochen massenweise aus ihrer Brust, wanden sich und hüllten sie in eine schwarze Kapsel"
  },
  AvgDialog_18790_Content_7 = {
    Text = "Im gedämpften Brüllen ließ die Hand mit den schwarzen Fäden Miryam als Stütze erscheinen, sodass der Kokon sich fest um den riesigen Schlangenkörper wickelte"
  },
  AvgDialog_18790_Content_8 = {
    Text = "Die Hülle des Kokons wurde durch die Ausdehnung transparent, unzählige Hände verschlangen sich zu einem Thron und hoben ein bleiches Herz empor"
  },
  AvgDialog_18790_Content_9 = {
    Text = "Ph'nglui mglw'nafh @1'@2 wgah'nagl fhtagn!"
  },
  AvgDialog_18792_Content_1 = {
    Text = "Sie ist nur ein Kind aus den Slums, weiß nichts und wird keine Bedrohung für Euch darstellen..."
  },
  AvgDialog_18792_Content_10 = {
    Text = "Nervig, meine Hand tut weh. Willst du heute hier sterben, 24?"
  },
  AvgDialog_18792_Content_11 = {
    Text = "Ohne einen so gehorsamen Sklaven wie dich werde ich weinen~"
  },
  AvgDialog_18792_Content_12 = {
    Text = "Entschuldigung... Ich werde keinen Schritt von hier weggehen"
  },
  AvgDialog_18792_Content_14 = {
    Text = "Klatsch—!"
  },
  AvgDialog_18792_Content_15 = {
    Text = "Bald ist 24s ganzer Körper ein blutiges Durcheinander. Dennoch rührt sie sich keinen Zentimeter, und wiederholt dieselben Worte immer und immer wieder."
  },
  AvgDialog_18792_Content_16 = {
    Text = "<Shake:Lasst sie gehen...>"
  },
  AvgDialog_18792_Content_17 = {
    Text = "<Shake:Lass sie gehen...>"
  },
  AvgDialog_18792_Content_18 = {
    Text = "Wenn du dich traust, komm zu mir, ihr Feiglinge! Nicht"
  },
  AvgDialog_18792_Content_19 = {
    Text = "<Bold:Schlag nicht meine Schwester...>"
  },
  AvgDialog_18792_Content_2 = {
    Text = "Klatsch—!"
  },
  AvgDialog_18792_Content_20 = {
    Text = "Fräulein 24! Hör auf... ugh"
  },
  AvgDialog_18792_Content_21 = {
    Text = "<Small:Nein... Kann mich nicht bewegen. Muss den Silberschlüssel holen...>"
  },
  AvgDialog_18792_Content_22 = {
    Text = "So dumm, so dumm! Dann sei nicht überrascht, wenn ich hart bin~"
  },
  AvgDialog_18792_Content_23 = {
    Text = "Leigh, es ist Zeit für deinen Auftritt"
  },
  AvgDialog_18792_Content_3 = {
    Text = "Die Peitsche schlug gnadenlos zu, und sofort erschien eine hässliche rote Spur auf 24s Gesicht"
  },
  AvgDialog_18792_Content_4 = {Text = "Hngh—!"},
  AvgDialog_18792_Content_5 = {
    Text = "24 stellt sich vor Jenkins, die schmalen Schulterblätter zittern wie Schmetterlingsflügel"
  },
  AvgDialog_18792_Content_6 = {
    Text = "Sie zwang sich zu einem Lächeln, das schlimmer aussah als Weinen"
  },
  AvgDialog_18792_Content_7 = {
    Text = "Mein Herr, habe bitte Erbarmen... Lass sie gehen, und ich werde alles tun..."
  },
  AvgDialog_18792_Content_8 = {
    Text = "Klatsch—!"
  },
  AvgDialog_18792_Content_9 = {
    Text = "Zahlreiche Peitschenhiebe fallen wie Regentropfen."
  },
  AvgDialog_18795_Content_1 = {
    Text = "Die Spitze des Rapiers durchdringt die schlangenförmige Energiekörper und trifft die Schwachstelle der Riesenschlange"
  },
  AvgDialog_18795_Content_10 = {
    Text = "King... Mein Herr... Murphy... Murphy..."
  },
  AvgDialog_18795_Content_12 = {
    Text = "Jetzt... gibt es noch eine Chance.\nKehre zum Orden zurück, du bist immer noch die ehrenwerte „Gottesmutter\""
  },
  AvgDialog_18795_Content_13 = {
    Text = "Dein Begräbnis wird die prachtvollste Zeremonie in der Geschichte von Gottes Reich sein, bewundert von zigtausenden... Dein Name wird ebenfalls in die Annalen der Geschichte eingetragen und durch die Zeiten weitergegeben."
  },
  AvgDialog_18795_Content_14 = {
    Text = "Komm zurück zu mir, wir werden gemeinsam... diesen <Blue:Unwürdigen> hinrichten"
  },
  AvgDialog_18795_Content_15 = {
    Text = "Hinrichtung... dieser Unreine, der sich als mein Herr tarnt!"
  },
  AvgDialog_18795_Content_16 = {
    Text = "Die riesige Schlange löst sich auf und formt sich wieder; unter dem Druck der Macht von Miryam beginnt der Raum sich allmählich zu verzerren und zu verändern"
  },
  AvgDialog_18795_Content_17 = {
    Text = "Miryam! Ich befehle dir, aufzuhören!"
  },
  AvgDialog_18795_Content_18 = {
    Text = "Falsche Götter, Fälschungen, Betrüger, Respektlose... Ungläubige... dürfen nicht das Aussehen von @3@4 verwenden!"
  },
  AvgDialog_18795_Content_19 = {
    Text = "In einem Moment verdichtete sich der Schatten über dem Kraftwerk zu einer greifbaren Form. \nSchwer zu beschreibende verzerrte Gebäude erhoben sich aus dem Boden"
  },
  AvgDialog_18795_Content_2 = {
    Text = "Hey, hey! Jemand fällt runter!"
  },
  AvgDialog_18795_Content_20 = {
    Text = "<Change>Respektlose Person... respektlose Person...... respektlos respektlos ▼▼▼▼▼▼▼▼!"
  },
  AvgDialog_18795_Content_21 = {
    Text = "Er stieß einen schrillen, verstörenden Lärm aus, während Miryam sich mit beiden Händen an ihrem Hals hielt und ihr Körper sich zu verformen und zu dehnen begann"
  },
  AvgDialog_18795_Content_22 = {
    Text = "Vorsicht! Sie verliert die Kontrolle!"
  },
  AvgDialog_18795_Content_3 = {
    Text = "Du fällst auch im Gebrüll der Riesenschlange"
  },
  AvgDialog_18795_Content_4 = {
    Text = "——Dann fiel sie in eine zitternde, warme Umarmung"
  },
  AvgDialog_18795_Content_5 = {
    Text = "......%player%."
  },
  AvgDialog_18795_Content_6 = {
    Text = "Bin ich im Himmel?"
  },
  AvgDialog_18795_Content_7 = {
    Text = "Sehr leid, wir sind immer noch auf der Sonaniel. Und die Gefahr ist nah"
  },
  AvgDialog_18795_Content_8 = {
    Text = "<Small:Unverzeihlich...>"
  },
  AvgDialog_18795_Content_9 = {
    Text = "Achtung! Miryam zeigt seltsame Anzeichen!"
  },
  AvgDialog_18796_Content_1 = {
    Text = "Hust hust hust, hallo allerseits! Heute testen wir den Übergangseffekt von Z1 ~"
  },
  AvgDialog_18796_Content_10 = {
    Text = "Geeignet, um schnell zu dunkleren Szenen zu wechseln."
  },
  AvgDialog_18796_Content_11 = {
    Text = "Puh... Ich bin erschöpft, das muss ich nicht extra sagen, oder? Nach Nummer 4 kommt natürlich Nummer 5!"
  },
  AvgDialog_18796_Content_12 = {
    Text = "Hm...kurz gesagt, Nummer 5 ist ein häufig verwendeter Übergang, der in vielen Situationen passt"
  },
  AvgDialog_18796_Content_13 = {
    Text = "Na gut, jetzt kommt der letzte Übergang—Nummer 6, bitte!"
  },
  AvgDialog_18796_Content_14 = {
    Text = "Das ist die längste Übergangsszene überhaupt~"
  },
  AvgDialog_18796_Content_15 = {
    Text = "Das waren alle Übergangseffekte, habt ihr alles verstanden?"
  },
  AvgDialog_18796_Content_16 = {
    Text = "Bis zum nächsten Mal♡"
  },
  AvgDialog_18796_Content_2 = {
    Text = "Jetzt kommt die Nummer 1 Bühne - Seitenwechsel~!!"
  },
  AvgDialog_18796_Content_3 = {
    Text = "Tada! Wie ist es, sieht es nicht prächtig aus?"
  },
  AvgDialog_18796_Content_4 = {
    Text = "Dieser Übergang wird normalerweise für den Wechsel innerhalb derselben Szene verwendet"
  },
  AvgDialog_18796_Content_5 = {
    Text = "Als Nächstes kommt Übergang Nummer 2—"
  },
  AvgDialog_18796_Content_6 = {
    Text = "Dieser Übergang wird normalerweise verwendet, um zu einer helleren Szene zu wechseln"
  },
  AvgDialog_18796_Content_7 = {
    Text = "Dann... Szene 3!"
  },
  AvgDialog_18796_Content_8 = {
    Text = "Die dritte Szene eignet sich auch für den Übergang zu hellen Szenen, aber das Tempo ist etwas langsamer, hihi"
  },
  AvgDialog_18796_Content_9 = {
    Text = "Der nächste, der zu uns kommt, ist - Übergang 4!"
  },
  AvgDialog_18797_Content_1 = {
    Text = "Mi...@1...uh"
  },
  AvgDialog_18797_Content_10 = {
    Text = "Bist du nicht der „Gottkönig\"!"
  },
  AvgDialog_18797_Content_11 = {
    Text = "Letztendlich, als der, der Miryam dient, bist du das, der die Prophezeiung der Auferstehung des Gottes verkündet hat"
  },
  AvgDialog_18797_Content_12 = {Text = "Du..."},
  AvgDialog_18797_Content_13 = {
    Text = "Ich habe gerade gesehen... durch die Verbindung, ich habe deine Erinnerungen gesehen"
  },
  AvgDialog_18797_Content_14 = {Text = "...Ja."},
  AvgDialog_18797_Content_15 = {
    Text = "Es ist die Prophezeiung von mir, aber ein „Orakel\" existiert nicht"
  },
  AvgDialog_18797_Content_16 = {Text = "Was?"},
  AvgDialog_18797_Content_17 = {
    Text = "Lange bevor die Flut kam, verlor ich die Fähigkeit, aus den Träumen der Götter in die Zukunft zu blicken.\nIch weiß nicht, wo Er ist, vielleicht ist Er erwacht oder vielleicht ist Er gegangen"
  },
  AvgDialog_18797_Content_18 = {
    Text = "Deine Prophezeiung"
  },
  AvgDialog_18797_Content_19 = {
    Text = "Miryam ist eine gläubige Anhängerin, geboren für das Göttliche Reich und von meinem Willen getrieben."
  },
  AvgDialog_18797_Content_2 = {
    Text = "Murphy stöhnte vor Schmerz, ihre Worte waren bruchstückhaft"
  },
  AvgDialog_18797_Content_20 = {
    Text = "Ich hatte gehofft, meine Worte würden sie in ihren letzten Momenten trösten, nie gedacht, dass sie sie als Evangelium betrachten und versuchen würde, das Göttliche Reich wieder aufzubauen."
  },
  AvgDialog_18797_Content_21 = {Text = "Das alles"},
  AvgDialog_18797_Content_22 = {
    Text = "Ja, das ist alles meine Schuld"
  },
  AvgDialog_18797_Content_23 = {
    Text = "Countdown 60 Minuten"
  },
  AvgDialog_18797_Content_3 = {
    Text = "! Was ist das?!"
  },
  AvgDialog_18797_Content_4 = {
    Text = "Unheimliche blau-schwarze Flecken erscheinen auf Murphys Gesicht, wie Wurzeln tief in ihrer Haut"
  },
  AvgDialog_18797_Content_5 = {
    Text = "Er beginnt, den Blutfluss des Wirts zu blockieren"
  },
  AvgDialog_18797_Content_6 = {
    Text = "Hieß es nicht, dass man sich von Himmelskörpern fernhalten soll?"
  },
  AvgDialog_18797_Content_7 = {
    Text = "Ich meine, vielleicht könnte es ihr weniger wehtun"
  },
  AvgDialog_18797_Content_8 = {
    Text = "Der Himmelskörper ist in der Umlaufbahn, es gibt kein Zurück mehr"
  },
  AvgDialog_18797_Content_9 = {
    Text = "Gibt es wirklich keinen Weg?"
  },
  AvgDialog_18798_Content_1 = {
    Text = "Puh... Puh... Oben nichts, unten auch nichts"
  },
  AvgDialog_18798_Content_10 = {
    Text = "Murphy ließ plötzlich nach, lehnte sich an die Reling und rutschte auf das Deck, ohne sich um ihre Haltung zu kümmern"
  },
  AvgDialog_18798_Content_11 = {
    Text = "Sie suchte nach einem Halt, um nicht umzufallen, und lehnte sich nach einigem Tasten an deine Schulter"
  },
  AvgDialog_18798_Content_12 = {
    Text = "Nur einen Moment..."
  },
  AvgDialog_18798_Content_13 = {
    Text = "Nach ein paar Sekunden hörtest du ein schnelles, aber regelmäßiges Atmen.\nMurphy verlor erneut das Bewusstsein"
  },
  AvgDialog_18798_Content_14 = {
    Text = "Sie wird schwächer..."
  },
  AvgDialog_18798_Content_15 = {
    Text = "Der Gott, den ich verbinde, kommt aus den unzähligen Sternen, selbst eine Fälschung ist für Menschen unüberwindbar"
  },
  AvgDialog_18798_Content_16 = {
    Text = "Gibt es keine Linderung?"
  },
  AvgDialog_18798_Content_17 = {
    Text = "...Bring sie weg"
  },
  AvgDialog_18798_Content_18 = {
    Text = "Haltet euch von Himmelskörpern fern, vielleicht geht es ihr dann besser"
  },
  AvgDialog_18798_Content_2 = {
    Text = "Sie... wo sind sie?"
  },
  AvgDialog_18798_Content_3 = {
    Text = "<Small:Ich hasse es... Warum ist dieses Schiff so groß...>"
  },
  AvgDialog_18798_Content_4 = {
    Text = "Geht es dir gut?"
  },
  AvgDialog_18798_Content_5 = {
    Text = "Mir geht es bestens! Husten, husten..."
  },
  AvgDialog_18798_Content_6 = {
    Text = "Murphy antwortete dir laut, verschluckte sich aber und begann heftig zu husten"
  },
  AvgDialog_18798_Content_7 = {
    Text = "Aber ich bin sehr müde und habe Kopfschmerzen"
  },
  AvgDialog_18798_Content_8 = {
    Text = "Während des Gesprächs hast du dich bereits hingesetzt"
  },
  AvgDialog_18798_Content_9 = {
    Text = "Und... lass uns eine Pause machen... nur kurz"
  },
  AvgDialog_18802_Content_1 = {
    Text = "Wenn ich stärker wäre, wenn ich ihm immer widerstehen könnte...\nAber ich kann es nicht, ich kann es nicht"
  },
  AvgDialog_18802_Content_10 = {
    Text = "Entschuldigung... Entschuldigung... es ist alles meine Schuld"
  },
  AvgDialog_18802_Content_11 = {
    Text = "Ich bin ein nutzloses Monster, ich habe so viele Menschen getötet und konnte Jenkins' Schwester nicht retten"
  },
  AvgDialog_18802_Content_12 = {
    Text = "Sie wurde weggebracht, sie wurde weggebracht, aber ich weiß nicht einmal, wohin sie gegangen ist...\nIch weiß nicht einmal, wer uns kontrolliert"
  },
  AvgDialog_18802_Content_13 = {
    Text = "Ramona kniete vor Aigis nieder und hielt das Mädchen sanft in ihren Armen"
  },
  AvgDialog_18802_Content_14 = {
    Text = "Du hast es gut gemacht, Aigis. Es war nicht deine Schuld"
  },
  AvgDialog_18802_Content_15 = {
    Text = [[
Das ist der wahre Ripper, derjenige, der euch kontrolliert und diese Verbrechen begangen hat.
Es war nie deine Schuld]]
  },
  AvgDialog_18802_Content_16 = {
    Text = "Das Mädchen warf sich in Ramonas Arme und weinte laut, während sie ihre rechte Hand fest auf ihr Auge drückte"
  },
  AvgDialog_18802_Content_17 = {
    Text = "Wir werden diese Person finden."
  },
  AvgDialog_18802_Content_18 = {
    Text = "Wir werden ihn finden und zur Rechenschaft ziehen.\nIch schwöre es dir"
  },
  AvgDialog_18802_Content_19 = {
    Text = "Danke, danke euch... Danke euch"
  },
  AvgDialog_18802_Content_2 = {
    Text = "Das letzte Mal, als ich ihm widerstand, stattdessen... stattdessen... ich konnte es nicht, schluchz"
  },
  AvgDialog_18802_Content_20 = {
    Text = "Das goldene Abendlicht durchdrang das riesige transparente Zifferblatt des Glockenturms und fiel auf das Mädchen"
  },
  AvgDialog_18802_Content_21 = {
    Text = "Aigis drehte sich zur Seite und legte eine Hand auf das Glas, während sie die Augen zusammenkniff und das warme Sonnenlicht genoss"
  },
  AvgDialog_18802_Content_22 = {
    Text = "Heute sieht man die Sonne"
  },
  AvgDialog_18802_Content_24 = {
    Text = "Von dem seltenen Sonnenschein begeistert, richtete sie sich auf und wankte zu einer sauberen Glasscheibe"
  },
  AvgDialog_18802_Content_25 = {
    Text = "Die verschwommene Sicht wird klar. Sie betrachtet die vertrauten und fremden Straßen, und es scheint, als würde jemand flüstern"
  },
  AvgDialog_18802_Content_26 = {
    Text = "Schau, die Stimme sagte, heute Nacht werden wir einen strahlenden Sternenhimmel sehen"
  },
  AvgDialog_18802_Content_28 = {
    Text = "Das Mädchen senkt den Kopf und lächelt nostalgisch"
  },
  AvgDialog_18802_Content_29 = {
    Text = "Früher, wenn die Sonne schien, brachte Tiyug mich nachts heimlich nach oben"
  },
  AvgDialog_18802_Content_3 = {
    Text = "Hör auf damit, zwing mich nicht mehr zu solchen Dingen"
  },
  AvgDialog_18802_Content_30 = {
    Text = "Miss Sarah hat uns nie erlaubt, hierher zu kommen, sie sagte, es sei zu gefährlich und wir könnten leicht verletzt werden. Aber Tiyog kümmert sich nicht darum"
  },
  AvgDialog_18802_Content_31 = {
    Text = "Seine Augen waren ausgezeichnet, er konnte selbst in der dunkelsten Umgebung klar sehen"
  },
  AvgDialog_18802_Content_32 = {
    Text = "Er war wie Jenkins, schlau und mutig, und kannte immer geheime Wege und Mechanismen, die andere nicht kannten"
  },
  AvgDialog_18802_Content_33 = {
    Text = "Solange er uns begleitet, wird Miss Sarah uns nicht entdecken"
  },
  AvgDialog_18802_Content_34 = {
    Text = "Solange er dabei ist, wird dieser Ort immer unsere Geheimbasis sein"
  },
  AvgDialog_18802_Content_35 = {
    Text = "Er sagte mir, ich müsse mehr Kontakt zu den Sternen haben, um mächtiger zu werden.\nObwohl wir hier keinen einzigen Stern sehen können"
  },
  AvgDialog_18802_Content_36 = {
    Text = [[
Damals war er der Einzige, der mir glaubte.
Er glaubte, dass ich diese schwarzen Dinge sehen konnte und sagte mir, dass es das Talent einer Hexe sei]]
  },
  AvgDialog_18802_Content_37 = {
    Text = "Später begannen die Ärzte, die Patienten nach draußen zu bringen; sie behandelten sie nicht mehr im Armenhaus. Ich konnte keine Beweise sammeln und keinen Rache für Tyug nehmen"
  },
  AvgDialog_18802_Content_38 = {
    Text = "Wenn ich so klug wie er und so mutig wie Jenkins wäre, hätte ich die Wahrheit längst herausgefunden"
  },
  AvgDialog_18802_Content_39 = {
    Text = "Aber ich bin keine Hexe"
  },
  AvgDialog_18802_Content_4 = {
    Text = "Ich möchte niemanden verletzen, ich möchte nicht töten"
  },
  AvgDialog_18802_Content_40 = {
    Text = "Ich bin nur ein Feigling"
  },
  AvgDialog_18802_Content_41 = {
    Text = "Ein Monster"
  },
  AvgDialog_18802_Content_42 = {
    Text = "Ein... Mörder."
  },
  AvgDialog_18802_Content_43 = {
    Text = "Wisst ihr, wie oft ich schon kontrolliert wurde?\nWisst ihr, wie viel Blut an meinen Händen klebt?"
  },
  AvgDialog_18802_Content_44 = {
    Text = "Ich habe große Angst davor, was ich werden könnte"
  },
  AvgDialog_18802_Content_46 = {
    Text = "Früher schmerzten meine Augen und mein Körper. Aber jetzt fühle ich nichts mehr, als wäre ich aus Stein"
  },
  AvgDialog_18802_Content_48 = {
    Text = "Verdammt, wo sind sie alle hin"
  },
  AvgDialog_18802_Content_49 = {Text = "Das ist..."},
  AvgDialog_18802_Content_5 = {
    Text = [[
<Shake:<AvgNormalFont:Nein! Nicht!
Lass Mike das nicht tun, er ist so klein, wie kann er...<Shake:Bitte...>>>]]
  },
  AvgDialog_18802_Content_50 = {
    Text = "Aigis?! Aigis—!"
  },
  AvgDialog_18802_Content_51 = {
    Text = "Plötzlich ertönte Jenkins' Stimme unter dem Glockenturm, sie war irgendwie im Hof erschienen"
  },
  AvgDialog_18802_Content_52 = {
    Text = "Sie rief verzweifelt Aigis' Namen und streckte die Arme zum Himmel"
  },
  AvgDialog_18802_Content_53 = {
    Text = "Der kleine Körper des Mädchens verschwindet für immer aus dem Nachthimmel"
  },
  AvgDialog_18802_Content_54 = {
    Text = "Ein Vogel fliegt über den Nachthimmel und verschwindet ohne eine Spur im dichten Nebel."
  },
  AvgDialog_18802_Content_55 = {
    Text = "Jenkins Arme streckten sich nur verwirrt aus, um Aigis’ leeres Kleid zu halten, während sich die quadratischen Zettel wie Schneeflocken verstreuten"
  },
  AvgDialog_18802_Content_56 = {
    Text = [[
Ai... Aigis...? 
Wie kann das sein...?]]
  },
  AvgDialog_18802_Content_57 = {
    Text = "Auf dem Papier ist ein goldener Schmetterling gezeichnet, die Faltenränder sind sorgfältig geglättet und es duftet nach Süßigkeiten, als es fällt"
  },
  AvgDialog_18802_Content_58 = {
    Text = "Uhh... Aigis"
  },
  AvgDialog_18802_Content_59 = {
    Text = "Ein blutgetränktes Band fällt zusammen mit dem Bonbonpapier in die Hand des Mädchens, es bewegt sich im Wind und streicht sanft über ihre Fingerspitzen, wie eine zarte Berührung"
  },
  AvgDialog_18802_Content_6 = {
    Text = "Ich höre nichts, ich höre nichts, ich höre nichts, nichts, nichts—"
  },
  AvgDialog_18802_Content_60 = {
    Text = "Das Mädchen blinzelte, und die Tränen, die ihre Sicht verschwommen machten, fielen von ihren Wimpern und wurden lautlos von dem leuchtend roten Stoff aufgefangen"
  },
  AvgDialog_18802_Content_61 = {
    Text = "Diese vertraute Farbe, diese vertraute Textur—nur eine silberne Schnalle fehlt, um perfekt mit ihrer Erinnerung übereinzustimmen"
  },
  AvgDialog_18802_Content_62 = {
    Text = "...Schwester...?"
  },
  AvgDialog_18802_Content_7 = {
    Text = "Ge-schafft?\nLauf schnell, aber bitte erzähl es niemandem"
  },
  AvgDialog_18802_Content_8 = {
    Text = "<Shake:<AvgNormalFont:Warte, nein, was ist das! Mein Kopf, mein Kopf...\nAh... Ahhh...!<Shake:Ah——!!>>>"
  },
  AvgDialog_18802_Content_9 = {
    Text = "Entschuldigung... Entschuldigung"
  },
  AvgDialog_18804_Content_1 = {
    Text = "Ein Hüter, der von ein paar Kindern bestohlen wurde, ein Jahr Training umsonst. Erstklässler an öffentlichen Schulen sind klüger als du"
  },
  AvgDialog_18804_Content_2 = {
    Text = "Zum Glück war der Dieb auch am Einsatzort, sonst hättest du Pech gehabt. Ich werde nicht zulassen, dass du für private Angelegenheiten Missionszeit verschwendest"
  },
  AvgDialog_18804_Content_3 = {
    Text = "Es ist nicht so schlimm, Puppe, geben Sie %player% ein wenig mehr Vertrauen"
  },
  AvgDialog_18804_Content_4 = {
    Text = "Bitte stören Sie nicht die Untersuchung der Geheimnishüter"
  },
  AvgDialog_18805_Content_1 = {
    Text = "Ein Hüter, der von ein paar Kindern bestohlen wurde, ein Jahr Training umsonst. Erstklässler an öffentlichen Schulen sind klüger als du"
  },
  AvgDialog_18805_Content_2 = {
    Text = "Zum Glück war der Dieb auch am Einsatzort, sonst hättest du Pech gehabt. Ich werde nicht zulassen, dass du für private Angelegenheiten Missionszeit verschwendest"
  },
  AvgDialog_18805_Content_3 = {
    Text = "Es ist nicht so schlimm, Puppe, geben Sie %player% ein wenig mehr Vertrauen"
  },
  AvgDialog_18805_Content_4 = {
    Text = "Bitte stören Sie nicht die Untersuchung der Geheimnishüter"
  },
  AvgDialog_18808_Content_1 = {
    Text = "Das ist Hintergrundloser Dialogtest 1"
  },
  AvgDialog_18808_Content_2 = {
    Text = "Das ist Hintergrundloser Dialogtest 2"
  },
  AvgDialog_18809_Content_1 = {
    Text = "Murphy zögerte nicht lange, zog Ramona zur Seite und begann, ihre Kleidung zu öffnen.\nAls der letzte Knopf gelöst war, sah Ramona das „Gott\" im Körper des Mädchens"
  },
  AvgDialog_18809_Content_2 = {
    Text = "Auf der Brust befindet sich ein Stück durchsichtige Haut, die die umliegende Haut und Muskeln spannt und den gesamten Brust- und Bauchraum grau und verkümmert erscheinen lässt"
  },
  AvgDialog_18809_Content_3 = {
    Text = "Ein solches Phänomen, das die Organe in der Brust sichtbar macht, Ramona sah ein zartrotes junges Herz und ein milchfarbenes „Ei\""
  },
  AvgDialog_18809_Content_4 = {
    Text = "Unzählige Fäden strecken sich aus dem „Ei\" und verflechten sich eng mit Murphys Blutgefäßen"
  },
  AvgDialog_18809_Content_5 = {
    Text = "Wäre seine Existenz nicht schon in Murphys Herz gedrungen, würde er wie ein Teil des durchsichtigen Brustkorbs wirken, nicht wie ein Fremdkörper"
  },
  AvgDialog_18809_Content_6 = {
    Text = "Er ist chaotisch und still, das umgekehrte Dreiecksmuster, das auf ihm eingraviert ist, erstarrt ebenfalls wie ein seltsames Kunstwerk"
  },
  AvgDialog_18809_Content_7 = {
    Text = "Schmelze... Dieses Ding ist bereits geschmolzen"
  },
  AvgDialog_18809_Content_8 = {
    Text = "Hast du genug gesehen?"
  },
  AvgDialog_18809_Content_9 = {
    Text = "Entschuldigung, das war unhöflich von mir, zieh dich bitte an"
  },
  AvgDialog_18810_Content_1 = {
    Text = "Countdown 20 Minuten"
  },
  AvgDialog_18810_Content_10 = {
    Text = "Vorsicht! Nicht ins Meer fallen!"
  },
  AvgDialog_18810_Content_11 = {
    Text = "Eine riesige Schlangenform bricht aus dem Meer und droht, das ganze Schiff umzukippen.\nMehrere Schlangenköpfe wirbeln und werfen große, furchterregende Schatten auf das Deck"
  },
  AvgDialog_18810_Content_12 = {
    Text = "Übertreter... Unverschämter... Narr!"
  },
  AvgDialog_18810_Content_13 = {
    Text = "Göttermutter... Göttermutter...@3!"
  },
  AvgDialog_18810_Content_14 = {
    Text = "Oh nein, es ist Miryam!"
  },
  AvgDialog_18810_Content_15 = {
    Text = "Schnell, bring Murphy weg!"
  },
  AvgDialog_18810_Content_16 = {Text = "Ah!!"},
  AvgDialog_18810_Content_17 = {
    Text = "Du schaust zurück auf das Deck; Murphy ist nicht mehr da. Ein riesiger Schlangenkopf hat das Mädchen gepackt und in Aequor hineingezogen."
  },
  AvgDialog_18810_Content_2 = {
    Text = "Verbindung? Bedeutet das, dass sie in Zukunft von dir abhängig sein wird?"
  },
  AvgDialog_18810_Content_3 = {
    Text = "Es handelt sich nur um eine Übergangslösung, wir haben nicht den Wunsch, Miss Celeste Ihnen zu entziehen"
  },
  AvgDialog_18810_Content_4 = {
    Text = "Das liegt nicht in meiner Macht"
  },
  AvgDialog_18810_Content_5 = {
    Text = "Celeste, bist du bereit?"
  },
  AvgDialog_18810_Content_6 = {
    Text = "Wie bei einem Keywords-Auslöser, hob Celeste den Kopf, blickte jedoch auf das Meer hinter sich, und das Segeln kam zum Stillstand"
  },
  AvgDialog_18810_Content_7 = {
    Text = "Das Schiff bewegt sich nicht mehr"
  },
  AvgDialog_18810_Content_8 = {
    Text = "Etwas hat mich gepackt"
  },
  AvgDialog_18810_Content_9 = {
    Text = "Kaum waren die Worte gefallen, begann der Boden unter euren Füßen heftig zu beben, das Schiff neigte sich in einen unmöglichen Winkel"
  },
  AvgDialog_18812_Content_1 = {
    Text = "Selbst ihr seid so... eine Gruppe von selbstgerechten Erwachsenen"
  },
  AvgDialog_18812_Content_10 = {
    Text = "Das zu grelle Licht schmerzte in den Augen und ließ unkontrollierbar Tränen fließen"
  },
  AvgDialog_18812_Content_11 = {
    Text = "Das, das ist!?"
  },
  AvgDialog_18812_Content_12 = {
    Text = "Die trübe Flüssigkeit floss ab, und die Augen konnten sich endlich wieder auf das Mädchen fokussieren"
  },
  AvgDialog_18812_Content_13 = {
    Text = "Die Klinge steckt tief in der Brust, das mondbeschienene Mädchen öffnet ihre Augen"
  },
  AvgDialog_18812_Content_14 = {
    Text = "Der Todessymbol-Mond ist nah, aber das junge Gesicht zeigt keine Angst"
  },
  AvgDialog_18812_Content_15 = {
    Text = "Ich... habe es durchbohrt... Es wird nicht geboren..."
  },
  AvgDialog_18812_Content_16 = {Text = "Damit"},
  AvgDialog_18812_Content_17 = {
    Text = "Die Hand, die den Messergriff hielt, sank kraftlos herab, und rote, zähe, tiefschwarze Flüssigkeit strömte aus der Wunde und tropfte zwischen den Fingern ins Meer"
  },
  AvgDialog_18812_Content_18 = {
    Text = "Das Blut floss schnell aus dem Körper, die Haut blass, aber voller sonderbarer Lebenskraft"
  },
  AvgDialog_18812_Content_19 = {
    Text = "Nein... Nein, nein, nein, ahhh—"
  },
  AvgDialog_18812_Content_2 = {
    Text = "Niemand hat mich je um Rat gefragt... Hmpf"
  },
  AvgDialog_18812_Content_20 = {
    Text = "Allmächtiger Gott, vergib mir, vergib diesem Kind, vergib deinem treuen Gläubigen"
  },
  AvgDialog_18812_Content_21 = {
    Text = "Der Moment des Ausrichtens, der Moment des Ausrichtens wird kommen, wird kommen"
  },
  AvgDialog_18812_Content_22 = {
    Text = "„Plazenta\" zerbricht, das „Herz\" kollabiert – unzählige Hände brechen hervor, die Brust des Mädchens wird zermalmt"
  },
  AvgDialog_18812_Content_23 = {
    Text = "Die missgestaltete Hand umklammert die unkenntliche Leiche, überlappt, schwillt an, überlappt, schwillt an——"
  },
  AvgDialog_18812_Content_24 = {
    Text = "Ah... Du hast mich gehört... Du hast auf mich geantwortet..."
  },
  AvgDialog_18812_Content_25 = {
    Text = "Sie brachten eine deformierte Existenz ins Mondlicht"
  },
  AvgDialog_18812_Content_26 = {
    Text = "Mein großer Gott...!"
  },
  AvgDialog_18812_Content_3 = {
    Text = "Ein Leben durch Opfer erkauft... Wer will das schon?"
  },
  AvgDialog_18812_Content_4 = {
    Text = "Nein, die Plazenta ist zu trüb.\nKann man mit „Geistiger Rückverfolgung\" hineinsehen?"
  },
  AvgDialog_18812_Content_5 = {
    Text = "Du umklammerst den zitternden silbernen Schlüssel und tauchst erneut in den Raum des Bewusstseins ein"
  },
  AvgDialog_18812_Content_6 = {
    Text = "In dem von Auflösung bedeckten Raum wird das Licht, das Leben und Intelligenz symbolisiert, besonders strahlend"
  },
  AvgDialog_18812_Content_7 = {
    Text = "——Das war ein Ritualmesser, das das kalte Mondlicht reflektierte"
  },
  AvgDialog_18812_Content_8 = {
    Text = "——Mmm!!"
  },
  AvgDialog_18812_Content_9 = {
    Text = "Das Licht brach plötzlich auf und katapultierte dich gewaltsam aus der Geisterwelt"
  },
  AvgDialog_18813_Content_1 = {
    Text = "Jetzt testen wir den Übergangseffekt Langsamer Zeitverlauf"
  },
  AvgDialog_18813_Content_10 = {
    Text = "Sandsturm 2"
  },
  AvgDialog_18813_Content_11 = {Text = "Testende"},
  AvgDialog_18813_Content_12 = {
    Text = "Jetzt testen wir den Bildschirmeffekt Dauerhaftes Wackeln"
  },
  AvgDialog_18813_Content_13 = {Text = "Testbeginn"},
  AvgDialog_18813_Content_16 = {Text = "Testende"},
  AvgDialog_18813_Content_17 = {
    Text = "Jetzt testen wir den Bildschirmeffekt Silberner Schlüssel Video"
  },
  AvgDialog_18813_Content_18 = {Text = "Testbeginn"},
  AvgDialog_18813_Content_19 = {
    Text = "Testende, aber ich starte direkt den [Bildschirmeffekt]Silberschlüssel-Effekt  Test"
  },
  AvgDialog_18813_Content_2 = {Text = "Testbeginn"},
  AvgDialog_18813_Content_20 = {Text = "Testbeginn"},
  AvgDialog_18813_Content_21 = {
    Text = "In Bearbeitung"
  },
  AvgDialog_18813_Content_22 = {Text = "Testende"},
  AvgDialog_18813_Content_23 = {
    Text = "Jetzt testen wir den FadeDarkRole-Effekt"
  },
  AvgDialog_18813_Content_26 = {Text = "Ende"},
  AvgDialog_18813_Content_3 = {Text = "Testende"},
  AvgDialog_18813_Content_4 = {
    Text = "Jetzt testen wir den Hintergrundübergang Schneller Zeitverlauf"
  },
  AvgDialog_18813_Content_5 = {Text = "Testbeginn"},
  AvgDialog_18813_Content_6 = {Text = "Testende"},
  AvgDialog_18813_Content_7 = {
    Text = "Jetzt testen wir den Bildschirmeffekt Sandsturm"
  },
  AvgDialog_18813_Content_8 = {Text = "Testbeginn"},
  AvgDialog_18813_Content_9 = {
    Text = "Sandsturm 1"
  },
  AvgDialog_18814_Content_1 = {
    Text = "Verzeih, es bleibt keine Zeit, dich einzugewöhnen."
  },
  AvgDialog_18814_Content_10 = {
    Text = "Ramona war entsetzt, du hattest sie noch nie so panisch gesehen"
  },
  AvgDialog_18814_Content_11 = {
    Text = "Das Mädchen, das mit Fragen bombardiert wurde, zitterte in der Stimme und sah erschöpft aus"
  },
  AvgDialog_18814_Content_12 = {
    Text = "Bin ich hier im Urlaub?"
  },
  AvgDialog_18814_Content_13 = {
    Text = "Sie schloss die Augen und sammelte sich"
  },
  AvgDialog_18814_Content_14 = {
    Text = "Ich hätte es wissen müssen. Der Eindringling kennt Missaga gut, der Schlüsselschrein wird nicht verschont bleiben.\nDas ist nahe dem Hintereingang, macht euch schnell auf den Weg"
  },
  AvgDialog_18814_Content_15 = {
    Text = "Wir können gehen! %player% kann uns alle verbinden und dann befehlen –"
  },
  AvgDialog_18814_Content_16 = {
    Text = "Ramona.\nDas sind unsere Pflichten, %player% ist nur ein Neuling, der noch nicht aus dem Ei geschlüpft ist"
  },
  AvgDialog_18814_Content_17 = {
    Text = "Aber %player% kann es, ich weiß, dass {Male=er,Female=sie} es kann"
  },
  AvgDialog_18814_Content_18 = {
    Text = "Puppe musterte dich von Kopf bis Fuß und wandte sich mit einem strengen Blick Ramona zu"
  },
  AvgDialog_18814_Content_19 = {
    Text = "Wenn ich mich nicht irre, ist die Schwurzeremonie noch nicht abgeschlossen.\n{Male=er,Female=sie} hat den Silberschlüssel noch nicht erhalten, oder?"
  },
  AvgDialog_18814_Content_2 = {
    Text = "Der Mutant erreichte das Schlüssellager, bevor die Glocke läutete, und die <Blue:Nebelbarriere> um Missaga war wahrscheinlich bereits ausgefallen"
  },
  AvgDialog_18814_Content_20 = {
    Text = "Ohne Genehmigung in die Missaga-Sperrzone einzudringen, ist ein schwerwiegender Vorfall. Ich dachte, du wüsstest das, da du hier aufgewachsen bist"
  },
  AvgDialog_18814_Content_21 = {
    Text = "Die Lage ist dringend, und %player% ist kein gewöhnlicher Neuling, {Male=er,Female=sie} ist unser einziger Geheimnisträger"
  },
  AvgDialog_18814_Content_22 = {
    Text = "Du erinnerst dich sicher an die <Yellow:Akut-Explosion> vor einem Jahr. Wenn {Male=er,Female=sie} damals nicht alle Erwachten verbunden hätte, könnte ich jetzt nicht hier stehen und mit dir streiten"
  },
  AvgDialog_18814_Content_23 = {
    Text = "Das Mädchen mit den rosa Haaren antwortet nicht, sondern wendet sich dir zu"
  },
  AvgDialog_18814_Content_24 = {
    Text = "Ich weiß, du hast einen Blick auf <Yellow:„das Tor“> geworfen. Aber egal ob die Zukunft der Welt oder der Kern von Missaga, es könnte schlimmer sein, als du denkst"
  },
  AvgDialog_18814_Content_25 = {
    Text = "Wir stehen einem Phänomen gegenüber, das die materielle Existenz selbst zerstört. Wenn du von <Yellow:Korrosion> betroffen bist, wird alles von dir verschwinden, sogar die Erinnerungen an dich"
  },
  AvgDialog_18814_Content_26 = {
    Text = "Der Name, den du während der Schwurzeremonie auf den Grabstein gravierst, wird zu schwarzem Schlamm und niemand wird sich daran erinnern"
  },
  AvgDialog_18814_Content_27 = {
    Text = "Antworte mir, bist du wirklich bereit?"
  },
  AvgDialog_18814_Content_28 = {
    Text = "Puppe starrte dich kalt an, ihre Stimme war völlig eben"
  },
  AvgDialog_18814_Content_29 = {
    Text = "Sie wirkte ausdruckslos, aber aus dem frostigen Grund ihrer Pupillen schimmerte loderndes Feuer"
  },
  AvgDialog_18814_Content_3 = {
    Text = "<Blue:William> wusste vom Ritual im Schlüsselschrein, aber keine Verstärkung kam, und die Glocken...\nWir müssen uns mit ihnen treffen und <Yellow:die Quelle der Mutation> beseitigen"
  },
  AvgDialog_18814_Content_30 = {
    Text = "Deine Antwort ist—"
  },
  AvgDialog_18814_Content_31 = {
    Text = "Mein Grabstein, steht jetzt im Schlüsselgrab"
  },
  AvgDialog_18814_Content_32 = {
    Text = [[
Du bist ein Teil von Missaga.
Vielleicht warst du es schon in Akut]]
  },
  AvgDialog_18814_Content_33 = {
    Text = "Hier gibt es Dinge, die nur ich tun kann"
  },
  AvgDialog_18814_Content_34 = {
    Text = "Diese Entscheidung mag übereilt sein, aber wer kann garantieren, dass man immer perfekt vorbereitet ist?"
  },
  AvgDialog_18814_Content_35 = {Text = "Gut."},
  AvgDialog_18814_Content_36 = {
    Text = "Ich verleihe dir im Namen des sechsten Rektors von Missaga, <Blue:Oliver Elsie>, diesen silbernen Schlüssel, Nummer K-0617"
  },
  AvgDialog_18814_Content_38 = {
    Text = "Puppe nahm einen silbernen Schlüssel aus einer präzisen kleinen Box und befestigte ihn an deiner Brust.\nDer silberne Schlüssel leuchtete und ein vertrautes Gefühl erfüllte deinen Brustkorb"
  },
  AvgDialog_18814_Content_39 = {
    Text = "Von nun an wirst du als Hüter des Geheimnisses mit den vielen Schülern und Lehrern von Missaga zusammen sein"
  },
  AvgDialog_18814_Content_4 = {Text = "?!"},
  AvgDialog_18814_Content_40 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18814_Content_41 = {
    Text = "Jetzt, verbinde dich mit mir"
  },
  AvgDialog_18814_Content_5 = {
    Text = "Am Ende des Blickfelds hebt ein blonder Junge einen unverhältnismäßig großen schwarzen Schild und wehrt die Angriffe eines agilen Doppelschwertkämpfers ab"
  },
  AvgDialog_18814_Content_6 = {
    Text = "Er schützte das Mädchen mit den rosa Haaren hinter sich mit einem Schild und wurde dabei immer weiter zurückgedrängt"
  },
  AvgDialog_18814_Content_7 = {
    Text = "Du erkennst das rothaarige Mädchen, sie ist die schwer verständliche Professorin Puppe und gehört zum <Blue: Wachkommando Forschungsinstitut>. Anders gesagt, sie ist eine Nicht-Kampfperson"
  },
  AvgDialog_18814_Content_8 = {
    Text = "Warte... Der Angreifer... ist das ein Erweckter?"
  },
  AvgDialog_18814_Content_9 = {
    Text = "Dorl? <Blue:Glockenturm> ist außer Kontrolle?!"
  },
  AvgDialog_18815_Content_1 = {
    Text = "Countdown 80 Minuten"
  },
  AvgDialog_18815_Content_10 = {
    Text = "Murphy machte zwei Schritte nach vorne, schwankte plötzlich und fiel weich am Mast entlang"
  },
  AvgDialog_18815_Content_11 = {Text = "Murphy?!"},
  AvgDialog_18815_Content_12 = {
    Text = "Du hebst die bewusstlose Murphy vom Deck auf, ihr Bewusstsein ist getrübt, und ihr Stirnhaar klebt verschwitzt an der Stirn"
  },
  AvgDialog_18815_Content_13 = {
    Text = "Aua... es tut so weh"
  },
  AvgDialog_18815_Content_14 = {
    Text = "Hm...@1...@1"
  },
  AvgDialog_18815_Content_15 = {
    Text = "Sie griff nach deiner stützenden Hand, und der Schmerz ließ sie unwillkürlich die Finger zusammenziehen, die tief in dein Fleisch eindrangen, aber du achtetest nicht auf den kleinen Schmerz"
  },
  AvgDialog_18815_Content_16 = {
    Text = "Du hörst die lauter werdenden Trommelschläge—nicht menschliche Muskeln, die im Brustkorb des Mädchens schlagen"
  },
  AvgDialog_18815_Content_17 = {
    Text = "Der Embryo... Er saugt ihre Lebenskraft aus."
  },
  AvgDialog_18815_Content_18 = {Text = "Mi...@2"},
  AvgDialog_18815_Content_19 = {
    Text = "Murphy konnte nur vor Schmerz stöhnen und unverständliches Geflüster murmeln"
  },
  AvgDialog_18815_Content_2 = {
    Text = "Dichter Nebel lag über dem Meer, das Deck war jedoch klar beleuchtet vom Mondlicht, die Ausdrücke der Menschen waren glasklar"
  },
  AvgDialog_18815_Content_20 = {
    Text = "In diesem chaotischen Lärm taucht der Feind aus den Schatten auf"
  },
  AvgDialog_18815_Content_3 = {
    Text = "Der Mond..."
  },
  AvgDialog_18815_Content_4 = {
    Text = "Was ist mit dem Mond?"
  },
  AvgDialog_18815_Content_5 = {
    Text = "Es wird immer heller"
  },
  AvgDialog_18815_Content_6 = {
    Text = "Murphy schluckte den Rest des Satzes, aber du wusstest, was sie sagen wollte—"
  },
  AvgDialog_18815_Content_7 = {
    Text = "Auch ihre Zeit wird knapp"
  },
  AvgDialog_18815_Content_8 = {
    Text = "......Beeil dich und triff dich mit den anderen, der Kapitän könnte einen schnellen Weg ans Ufer kennen"
  },
  AvgDialog_18815_Content_9 = {Text = "Hmm..."},
  AvgDialog_18818_Content_1 = {
    Text = "Hab's bekommen!"
  },
  AvgDialog_18818_Content_10 = {
    Text = "Das seltsame Ungeheuer senkt gehorsam den Kopf, als ob es auf die Berührung des weißen Mädchens wartet"
  },
  AvgDialog_18818_Content_11 = {
    Text = "Der Kopf eines gekrönten Menschen ragt aus dem Hals des riesigen Hundekörpers, was die Szene äußerst unheimlich macht"
  },
  AvgDialog_18818_Content_12 = {Text = "Lily..."},
  AvgDialog_18818_Content_13 = {
    Text = "Das weiße Mädchen geht langsam zur seltsam geformten Bestie, streckt einen zarten Arm aus und streichelt ihren Kopf wie ein Haustier"
  },
  AvgDialog_18818_Content_14 = {
    Text = "Der Kopf eines gekrönten Menschen ragt aus dem Hals des riesigen Hundekörpers, was die Szene äußerst unheimlich macht"
  },
  AvgDialog_18818_Content_15 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_18818_Content_16 = {
    Text = "Du und Ramona schaut euch an, voller unausgesprochener Worte"
  },
  AvgDialog_18818_Content_17 = {
    Text = "Hey, schaut ihr nur zu? Der Höllenhund ist direkt vor uns"
  },
  AvgDialog_18818_Content_18 = {
    Text = "Der Haupttäter, den wir untersuchen, ist direkt bei uns, wie sagt man so schön? „Mühelos gefunden“?"
  },
  AvgDialog_18818_Content_19 = {
    Text = "Das Mädchen scheint nichts zu hören, flüstert in Kums Ohr, der Abendwind trägt die sanfte Stimme"
  },
  AvgDialog_18818_Content_2 = {
    Text = "Ramona sprang in die Nähe, das in die Enge gedrängte Monster brüllte wütend und versuchte sich verzweifelt zu wehren"
  },
  AvgDialog_18818_Content_20 = {
    Text = [[
Kum, sei brav und gehorche dem Befehl.
Nur wer gehorcht, ist ein gutes Kind]]
  },
  AvgDialog_18818_Content_21 = {
    Text = "Kaum waren die Worte gefallen, drehte sich Lily um und kam auf euch zu"
