  AvgDialog_18818_Content_22 = {
    Text = "Die Narzissenfrau sagt, wenn Kum entdeckt wird, muss Lily zu ihrer Mutter zurückkehren"
  },
  AvgDialog_18818_Content_23 = {
    Text = "Jetzt lasst uns zum Laden zurückkehren.\nDie Narzissen-Dame wird dir alles erzählen."
  },
  AvgDialog_18818_Content_3 = {
    Text = "<Italic:Nein, nein, Kum, komm zurück!>"
  },
  AvgDialog_18818_Content_4 = {
    Text = "Diese Stimme... habe ich sie schon mal gehört?"
  },
  AvgDialog_18818_Content_5 = {
    Text = "Aus dem dunklen Schatten trat eine kleine, zitternde Gestalt hervor"
  },
  AvgDialog_18818_Content_6 = {
    Text = "Kum, du darfst große Brüder und Schwestern nicht verletzen"
  },
  AvgDialog_18818_Content_7 = {
