  },
  AvgDialog_18823_Content_11 = {
    Text = "Simulationsfilter für den Fluss des D-Schleims!"
  },
  AvgDialog_18823_Content_12 = {
    Text = "Es ist ein längerer Filter, empfehle ihn mit mehreren Dialogen zu verwenden"
