Ende]]
  },
  AvgDialog_21761_Content_12 = {
    Text = "Jetzt Augenschlusstest"
  },
  AvgDialog_21761_Content_14 = {
    Text = "Augen schließen ist kein Loop-Effekt, denke daran, mit 2 zu enden"
  },
  AvgDialog_21761_Content_15 = {
    Text = "Jetzt rotes Blinken, 1"
  },
  AvgDialog_21761_Content_17 = {
    Text = "Roter Blitz ist kein Loop-Effekt, beende mit 2"
  },
