  AvgDialog_21801_Content_1 = {
    Text = "Freund-Kompendium"
  },
  AvgDialog_21801_Content_10 = {
    Text = "Warum gehst du so unsicher? Hast du dir das Bein verletzt?"
  },
  AvgDialog_21801_Content_11 = {
    Text = "Du blicktest zurück auf den Weg, den du genommen hattest: Um dem D-Schleim auszuweichen, der sich über den Boden ausbreitete, bildeten deine Fußspuren einen seltsamen Bogen im Schlamm."
  },
  AvgDialog_21801_Content_12 = {
    Text = "Oder... soll Aurita dich tragen?"
  },
  AvgDialog_21801_Content_13 = {
    Text = "Nein, nicht nötig. Ich dachte nur, dieser Weg wäre lustiger. Findest du nicht auch, Aurita?"
  },
  AvgDialog_21801_Content_14 = {
    Text = "Wie Himmel und Hölle!"
  },
  AvgDialog_21801_Content_15 = {
    Text = "Ja, wie Himmel-und-Hölle spielen."
  },
  AvgDialog_21801_Content_16 = {
    Text = "...Aurita, wollen wir Schattenfangen spielen?"
  },
  AvgDialog_21801_Content_17 = {
    Text = "Ich gehe voraus, und du folgst meinen Fußspuren... Was meinst du?"
  },
  AvgDialog_21801_Content_18 = {
    Text = "Hmm... Das geht! Geh du zuerst, und Aurita zeigt dir den Weg."
  },
  AvgDialog_21801_Content_19 = {
    Text = "Aurita trat gehorsam ein paar Schritte zurück, um dir Platz zu machen, und wäre beim Hüpfen beinahe in den D-Schleim getreten."
  },
  AvgDialog_21801_Content_2 = {
    Text = "Hmm～ Hmm hmm hmm～"
  },
  AvgDialog_21801_Content_20 = {
    Text = "Du zogst sie ruckartig zurück, doch sie blinzelte nur und lächelte immer noch selig, als das Spiel begann."
  },
  AvgDialog_21801_Content_21 = {
    Text = "Tschutschu—Der Zug fährt ab! Zentralplatz—Nach links!"
  },
  AvgDialog_21801_Content_3 = {
    Text = "Aurita summte eine fröhliche Melodie und ging neben dir durch die Straßen, die sich auflösten."
  },
  AvgDialog_21801_Content_4 = {
    Text = "Die dunklen, unbeleuchteten Fenster zeigen, dass dieser Ort schon lange verlassen ist. Auf beiden Seiten der stillen Straße sind nur noch die Umrisse zerstörter Häuser zu erkennen."
  },
  AvgDialog_21801_Content_5 = {
    Text = "Was ist mit den Bewohnern? Haben sie ihre Häuser vor dem Ausbruch des D-Phänomens verlassen? Haben sie neue Orte zum Leben gefunden, oder..."
  },
  AvgDialog_21801_Content_6 = {
    Text = "Zähflüssige schwarze Flüssigkeit fließt lautlos zu deinen Füßen. Du atmest tief ein und unterdrückst die Übelkeit, die dir fast in die Kehle steigt."
  },
  AvgDialog_21801_Content_7 = {
    Text = "Oder... haben sie ihr geliebtes Zuhause nie verlassen?"
  },
  AvgDialog_21801_Content_8 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_21801_Content_9 = {
    Text = "Ein nachdenkliches Summen riss dich aus deinen Sorgen. Aurita musterte dich und fragte schließlich verwundert."
  },
  AvgDialog_21803_Content_1 = {
    Text = "Wasserpalast"
  },
  AvgDialog_21803_Content_10 = {
    Text = "Wirklich! Danke, Oma!"
  },
  AvgDialog_21803_Content_11 = {
    Text = "Oma Betty tröstete Aurita schnell und sah zu, wie das Mädchen in die nahegelegenen Ruinen hüpfte, bevor sie sich mit einem Lächeln zu dir umwandte."
  },
  AvgDialog_21803_Content_12 = {
    Text = "Warum hast du Aurita absichtlich weggeschickt? Was willst du mir erzählen?"
  },
  AvgDialog_21803_Content_13 = {
    Text = "Sei nicht so misstrauisch, ich möchte nur... eine Geschichte erzählen."
  },
  AvgDialog_21803_Content_14 = {
    Text = "Einst war dies ein Fischereihafen. Einige ehrgeizige Jugendliche gingen in die Stadt, während andere zu Hause blieben und fischten... Es war so friedlich wie jedes andere Fischerdorf."
  },
  AvgDialog_21803_Content_15 = {
    Text = "Die Veränderungen geschahen leise und ließen nur Frauen und Kinder zurück."
  },
  AvgDialog_21803_Content_16 = {
    Text = "Fischerboote liefen aus, doch nur zerbrochene Kiele trieben mit der Strömung zurück an die Küste."
  },
  AvgDialog_21803_Content_17 = {
    Text = "Schwarzes Wasser floss über den Damm und erodierte die Straßen zu Ruinen."
  },
  AvgDialog_21803_Content_18 = {
    Text = "Als Aurita es bemerkte, waren ihre Spielkameraden, ihre Familie und sogar alle Bewohner der Stadt spurlos verschwunden..."
  },
  AvgDialog_21803_Content_19 = {
    Text = "Warte, was ist mit dir, Oma?"
  },
  AvgDialog_21803_Content_2 = {
    Text = "Die alte Frau, die sich Betty nennt, lächelt, während sie dich mustert und dabei unauffällig einschätzt, ob du als Freund von Aurita würdig bist."
  },
  AvgDialog_21803_Content_20 = {
    Text = "Sie schüttelt den Kopf und deutet dir an, auf ihren Unterkörper zu schauen."
  },
  AvgDialog_21803_Content_21 = {
    Text = "D-Schleim floss unter ihrem Leinenrock hervor.\nIhr Unterkörper war fast vollständig in Auflösung und Illusion versunken."
  },
  AvgDialog_21803_Content_22 = {Text = "?!"},
  AvgDialog_21803_Content_23 = {
    Text = "Wie fühlt sich dein Körper jetzt an?"
  },
  AvgDialog_21803_Content_24 = {
    Text = "Die alte Frau lachte leise und klopfte dir auf die Schulter, ganz wie es eine echte Ältere tun würde."
  },
  AvgDialog_21803_Content_25 = {
    Text = "Hab keine Angst, Kleines. Hab keine Angst."
  },
  AvgDialog_21803_Content_26 = {
    Text = "„Oma Betty“ ist schon lange verschwunden; es ist die Besessenheit des Kindes, die mich hier gehalten hat."
  },
  AvgDialog_21803_Content_27 = {
    Text = "Während sie sprachen, wehte ein Windstoß einen Flyer von irgendwoher heran.\nDie meisten Muster auf dem Papier waren von D-Schleim geschwärzt, aber die Slogans waren noch schwach erkennbar."
  },
  AvgDialog_21803_Content_28 = {
    Text = "„Bettys Bäckerei, hausgemachtes Brot von der Großmutter der Heimatstadt\""
  },
  AvgDialog_21803_Content_29 = {
    Text = "Oh je... es scheint, „Betty\" ist vielleicht nicht einmal mein richtiger Name."
  },
  AvgDialog_21803_Content_3 = {
    Text = "Nach einer langen Weile wandte sie ihren Blick ab und klopfte Aurita auf den Rücken."
  },
  AvgDialog_21803_Content_30 = {
    Text = "...Warum erzählst du mir diese Dinge?"
  },
  AvgDialog_21803_Content_31 = {
    Text = "Oma Betty warf einen Blick auf das eingestürzte alte Gebäude nicht weit entfernt, wo Aurita „Schatzsuche“ betrieb und eine Staubwolke aufwirbelte."
  },
  AvgDialog_21803_Content_32 = {
    Text = "Ich habe Aurita viele Lügen erzählt, um sie nicht traurig zu machen."
  },
  AvgDialog_21803_Content_33 = {
    Text = "Zum Beispiel..."
  },
  AvgDialog_21803_Content_34 = {
    Text = "„Zuhause im Meer“"
  },
  AvgDialog_21803_Content_35 = {
    Text = "Hat sie dir das wirklich erzählt? Es scheint, als würde sie diese Geschichte wirklich glauben...\nAber was kann ihre echte Schwiegermutter anderes tun, als Lügen zu spinnen?"
  },
  AvgDialog_21803_Content_36 = {
    Text = "Können wir ihr sagen, dass ihre Eltern niemals zurückkehren werden?\nIn dieser Stadt ohne Zukunft sind solche Worte zu grausam."
  },
  AvgDialog_21803_Content_37 = {
    Text = "Deshalb habe ich eine Bitte... Bitte, bitte behalte das vor ihr geheim."
  },
  AvgDialog_21803_Content_38 = {
    Text = "Erzähl ihr nicht, was in Wirklichkeit geschieht... Lass sie zumindest mit einem fröhlichen Herzen fortgehen."
  },
  AvgDialog_21803_Content_39 = {
    Text = "Das ist mein Wunsch, und... auch ihrer."
  },
  AvgDialog_21803_Content_4 = {
    Text = "Aurita, könntest du eine Weile alleine spielen gehen?\nOma wird sich mit diesem neuen Freund unterhalten und dich bald suchen kommen."
  },
  AvgDialog_21803_Content_40 = {
    Text = "Oma Bettys Ton war aufrichtig, sogar flehend."
  },
  AvgDialog_21803_Content_41 = {Text = "Verlasse?"},
  AvgDialog_21803_Content_42 = {
    Text = "Da ist absolut gar nichts!"
  },
  AvgDialog_21803_Content_43 = {
    Text = "Hat Oma die Tonfigur wirklich dort drüben versteckt? Aurita hat alles auf den Kopf gestellt!"
  },
  AvgDialog_21803_Content_44 = {
    Text = "Auritas düstere Stimme erregte deine Aufmerksamkeit; sie stand mit dem Rücken zu dir auf den Ruinen.\nDiesmal bemerktest du endlich einen flüchtigen schwarzen Fleck auf ihrem Rücken."
  },
  AvgDialog_21803_Content_45 = {
    Text = "Ein klaffendes Loch dominiert ihren kleinen Körper — eindeutig eine große Fusionsnarbe."
  },
  AvgDialog_21803_Content_46 = {
    Text = "Du warst erschrocken und drehst dich um, um den Ort zu betrachten, an dem „Großmutter Betty“ einst stand.\nAlles, was blieb, war ein Pool aus zähem Flüssigkeit, der mit dem dunklen, stagnierenden Wasser verschmolz."
  },
  AvgDialog_21803_Content_47 = {
    Text = "Im Abwasser reflektiert die Keramik ein sanftes und warmes Licht."
  },
  AvgDialog_21803_Content_48 = {
    Text = "Die Figur aufheben"
  },
  AvgDialog_21803_Content_49 = {
    Text = "Unerwartet blieb nach dem Verschwinden von \"Oma Betty\" nicht eine aus Ton geformte alten Frau zurück."
  },
  AvgDialog_21803_Content_5 = {
    Text = "Kann man nicht mit Aurita reden?"
  },
  AvgDialog_21803_Content_50 = {
    Text = "Ein rundes und prallgefülltes Schirmdach mit feinen, dichten Tentakeln, verziert mit kleeblattförmiger blauer Glasur auf porzellanweißem Grund."
  },
  AvgDialog_21803_Content_51 = {
    Text = "Wow — das ist Auritas Lieblingsqualle!"
  },
  AvgDialog_21803_Content_52 = {
    Text = "Du hast geschummelt! Du hast Aurita dazu gebracht, dort drüben zu suchen, aber sie war die ganze Zeit in deinen Händen!"
  },
  AvgDialog_21803_Content_53 = {
    Text = "Nicht, nicht böse sein... Schau, was ist das hier?"
  },
  AvgDialog_21803_Content_54 = {
    Text = "Du bringst ein gezwungenes Lächeln hervor, ziehst „Pony“ und „Schneewittchen“ aus deiner Tasche und gibst sie Aurita zusammen mit der „Qualle“-Figur."
  },
  AvgDialog_21803_Content_55 = {
    Text = "Alles für Aurita?! Danke, mein Freund!"
  },
  AvgDialog_21803_Content_56 = {
    Text = "Der Wassertank ～Auritas Aquarium～"
  },
  AvgDialog_21803_Content_57 = {
    Text = "Palast～Freunde und der Palast im Wasser～"
  },
  AvgDialog_21803_Content_58 = {
    Text = "Aurita summte ein Lied, verloren in der Freude über ihr neues Spielzeug. Vite, Pony, Schneewittchen und Großmutter Betty schienen keine Spuren in ihrem Herzen zu hinterlassen."
  },
  AvgDialog_21803_Content_59 = {
    Text = "Huff... Huff... Sind alle einverstanden, so zu stehen?"
  },
  AvgDialog_21803_Content_6 = {
    Text = "Schätzchen, Gespräche unter Erwachsenen könnten dich langweilen. Ist unsere kleine Aurita nicht diejenige, die Langeweile am meisten hasst?"
  },
  AvgDialog_21803_Content_60 = {
    Text = "Bewege \"Pony\" ein Stück weiter nach draußen; ein Pferd drinnen zu haben, fühlt sich etwas seltsam an."
  },
  AvgDialog_21803_Content_61 = {
    Text = "Sehr vernünftig! Übrigens, hast du es \"Pony\" genannt?"
  },
  AvgDialog_21803_Content_62 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_21803_Content_63 = {
    Text = "Auritas Palast ist fertig!"
  },
  AvgDialog_21803_Content_64 = {
    Text = "Auritas zukünftiges Zuhause, ihr Unterwasser-Zuhause..."
  },
  AvgDialog_21803_Content_65 = {
    Text = "Aurita will im Zimmer neben ihren Eltern schlafen und manchmal bei ihnen!"
  },
  AvgDialog_21803_Content_66 = {
    Text = "Der Welpe will in Auritas Bett schlafen, das Pony im Wohnzimmer — oder im Garten."
  },
  AvgDialog_21803_Content_67 = {
    Text = "Quallen können überall umhertreiben, und Auritas Freunde trinken alle heiße Schokolade am Kamin..."
  },
  AvgDialog_21803_Content_68 = {
    Text = "Hmm... unter Wasser... können wir den Kamin anzünden?"
  },
  AvgDialog_21803_Content_69 = {
    Text = "Auritas Augen blinzelten und verrieten einen Hauch von Müdigkeit. Sie ließ ein langes Gähnen hören, ihr Blick wurde trüb."
  },
  AvgDialog_21803_Content_7 = {
    Text = "Schnief...schluchz... Aber ich will bei Oma bleiben..."
  },
  AvgDialog_21803_Content_70 = {
    Text = "Ist Aurita müde?"
  },
  AvgDialog_21803_Content_71 = {
    Text = "Aurita... kann immer noch... spielen..."
  },
  AvgDialog_21803_Content_72 = {
    Text = "Schlaf gut, Aurita."
  },
  AvgDialog_21803_Content_73 = {
    Text = "Der Kamin wird warm brennen."
  },
  AvgDialog_21803_Content_74 = {
    Text = "In den servierten Kakao wird viel Zucker getan."
  },
  AvgDialog_21803_Content_75 = {
    Text = "Wenn du aufwachst, werden alle deine Freunde da sein."
  },
  AvgDialog_21803_Content_76 = {
    Text = "Puh... Freunde..."
  },
  AvgDialog_21803_Content_77 = {
    Text = "Lasst... Aurita nicht allein..."
  },
  AvgDialog_21803_Content_8 = {
    Text = "Braves Kind, möchtest du ein Spiel mit Oma spielen?"
  },
  AvgDialog_21803_Content_9 = {
    Text = "Aurita möchte die Häuser ihrer Freunde dekorieren, oder? Oma hat mehrere Tonfiguren in der Nähe versteckt... Wenn Aurita sie findet, gehören sie alle ihr."
  },
  AvgDialog_21805_Content_1 = {
    Text = "Stiller Tag"
  },
  AvgDialog_21805_Content_10 = {
    Text = "Oh... Nein! Das Wasser darin ist nicht trinkbar! Du hast schon so viel davon geschluckt."
  },
  AvgDialog_21805_Content_11 = {
    Text = "Ich bin fast ertrunken; es lag nicht nur am Wassertrinken."
  },
  AvgDialog_21805_Content_12 = {
    Text = "Angesichts des aufgeblasenen, unschuldigen Gesichtsausdrucks des Mädchens spürst du einen stechenden Schmerz in deiner Lunge. Nach mehreren tiefen Atemzügen füllt die Vernunft endlich wieder deinen Geist."
  },
  AvgDialog_21805_Content_13 = {
    Text = "Als Wille und Erinnerung in Einklang kamen, wurde dir endlich klar, dass du erneut die Erinnerung des Erweckten Körpers betreten hattest—"
  },
  AvgDialog_21805_Content_14 = {
    Text = "Ertrinken... ertrinken..."
  },
  AvgDialog_21805_Content_15 = {
    Text = "Aurita ist eine ausgezeichnete Schwimmerin! Werde Freund von Aurita, und du wirst nie wieder ertrinken!"
  },
  AvgDialog_21805_Content_16 = {
    Text = "Aurita wuselte um das Bett herum, machte ein großes Aufheben und mühte sich ab, den Ofen im Zimmer anzuzünden."
  },
  AvgDialog_21805_Content_17 = {
    Text = "Während das Mädchen von der Asche hustete, wurde der Raum allmählich wärmer. Feuchte Kleidung gab Dampfschwaden ab, und ihre gefrorenen Glieder begannen aufzutauen."
  },
  AvgDialog_21805_Content_18 = {
    Text = "Aurita... du bist Aurita, also ist das hier dein Zuhause..."
  },
  AvgDialog_21805_Content_19 = {
    Text = "Hmm! Das ist Auritas Zuhause, und du bist ein Gast, den Aurita aus dem Meer eingeladen hat!"
  },
  AvgDialog_21805_Content_2 = {
    Text = "*Hust... hust!*"
  },
  AvgDialog_21805_Content_20 = {
    Text = "Bruchstücke körperlicher Erinnerungen tauchen auf, und du beginnst allmählich, die Rolle zu verstehen, die du in diesem Traum spielst—"
  },
  AvgDialog_21805_Content_21 = {
    Text = "Im Sturm fiel ein Besatzungsmitglied über Bord und wurde freundlicherweise von den Wellen an Land getragen. Schließlich schleppte das Mädchen vor ihm ihn nach Hause..."
  },
  AvgDialog_21805_Content_22 = {
    Text = "So eine gewöhnliche Identität."
  },
  AvgDialog_21805_Content_23 = {
    Text = "Du hast dich allmählich an die surreale Erfahrung des „Eintretens in Träume“ gewöhnt. Im Allgemeinen wachst du im richtigen Moment auf, solange du die Erinnerungen, die diesen Traum formen, miterlebt hast."
  },
  AvgDialog_21805_Content_24 = {
    Text = "Das aktuelle Problem ist, dass du Auritas „Erinnerung\" nicht bestätigen kannst."
  },
  AvgDialog_21805_Content_25 = {
    Text = "Auritas „Erinnerung\" ist ein Rätsel. Die Auflösung hat ihre Vergangenheit verschlungen, bevor sie erweckt wurde, und es ist schwierig, aus ihren kindlichen Worten genügend Details zu finden, um das vollständige Bild zusammenzusetzen."
  },
  AvgDialog_21805_Content_26 = {
    Text = "Jetzt könnte der perfekte Zeitpunkt sein, die Lücken in Auritas Aufzeichnungen zu füllen."
  },
  AvgDialog_21805_Content_27 = {
    Text = "Was ist los? Warum hast du so lange nichts gesagt?"
  },
  AvgDialog_21805_Content_28 = {
    Text = "Wenn du nicht mit Aurita spielen willst, kann ich dich wegschicken..."
  },
  AvgDialog_21805_Content_29 = {
    Text = "Gehst du schon so bald?"
  },
  AvgDialog_21805_Content_3 = {
    Text = "Unter dem heftigen Schlag wurde Flüssigkeit aus den Atemwegen gepresst, und das salzige Meerwasser stieg unerwartet die Kehle hinauf und führte einen lebhaften Cancan auf der Zunge auf."
  },
  AvgDialog_21805_Content_30 = {
    Text = "Den... Gast verabschieden?"
  },
  AvgDialog_21805_Content_31 = {
    Text = "Du meinst, du willst mit Aurita spielen!"
  },
  AvgDialog_21805_Content_32 = {
    Text = "Toll, toll, toll!\nNeue Gäste, neue Freunde, schließt euch Auritas <Yellow:neuen Partnern im Aquarium> an!"
  },
  AvgDialog_21805_Content_33 = {Text = "Aquarium?"},
  AvgDialog_21805_Content_34 = {
    Text = "Aquarium? Könnte es sein, dass du dieses Glasbecken meinst?"
  },
  AvgDialog_21805_Content_35 = {
    Text = "Das bereitet Aurita für ihr neues Zuhause vor!"
  },
  AvgDialog_21805_Content_36 = {
    Text = "Das Mädchen winkte aufgeregt, und du hast dir endlich das mit Wasser gefüllte Glasbecken am Fenster genau angesehen —"
  },
  AvgDialog_21805_Content_37 = {
    Text = "Es zeigt eine kunstvolle Schlosslandschaft, doch die Wellen, die der Kreislauf des Lebens aufwirbelt, sind nirgends zu finden.\nEs scheint nichts weiter als ein versunkenes Märchen zu sein."
  },
  AvgDialog_21805_Content_38 = {
    Text = "Neuer Partner?"
  },
  AvgDialog_21805_Content_39 = {
    Text = "Ja! Auritas neue Freunde! Wenn Aurita ins Meer zurückkehrt, um sich mit ihrer Familie zu vereinen, können alle ihre Freunde zu Besuch kommen."
  },
  AvgDialog_21805_Content_4 = {
    Text = "Wow! Du hast so viel Wasser geschluckt!"
  },
  AvgDialog_21805_Content_40 = {
    Text = "Auf weicher Bettwäsche liegend, jagen dir Auritas Worte ohne ersichtlichen Grund immer noch einen Schauer über den Rücken."
  },
  AvgDialog_21805_Content_41 = {
    Text = "Erst dann wird dir bewusst — es ist zu still."
  },
  AvgDialog_21805_Content_42 = {
    Text = "Das Zirpen der Insekten, das Wehen des Windes, das Rascheln der Blätter aneinander...\nDas Plaudern, das Lachen, das Reiben der Schuhsohlen auf der Straße..."
  },
  AvgDialog_21805_Content_43 = {
    Text = "Die Welt ist totenstill; nur Aurita, die Herrin der Träume, ist lebendig."
  },
  AvgDialog_21805_Content_44 = {
    Text = "Aurita... Lebt sie hier ganz allein?"
  },
  AvgDialog_21805_Content_45 = {
    Text = "Allein? Auf keinen Fall. Vite, Schneewittchen und Pony... all Auritas Freunde sind in der Stadt!\nAußerdem lebt Oma, Auritas <Yellow:Oma>, auch mit Aurita zusammen!"
  },
  AvgDialog_21805_Content_46 = {
    Text = "Oh, richtig! Oma! Oma hat gesagt, wenn Aurita einen neuen Freund findet, muss sie ihn auch vorstellen!"
  },
  AvgDialog_21805_Content_47 = {
    Text = "Bei der Erwähnung von „Oma\" leuchten Auritas Augen auf. Sie springt zurück ans Bett und versucht, dich hochzuziehen, erstarrt dann aber plötzlich, als würde sie sich an etwas erinnern."
  },
  AvgDialog_21805_Content_48 = {
    Text = "Willst du noch mehr Wasser?"
  },
  AvgDialog_21805_Content_49 = {
    Text = "Ich ertrinke schon..."
  },
  AvgDialog_21805_Content_5 = {
    Text = "Der Geruch von Meerwasser und Blut füllt deine völlig durchnässten Nasenlöcher. Mit einem heftigen Husten wird sogar grober Sand aus der Tiefe herausgepresst."
  },
  AvgDialog_21805_Content_50 = {
    Text = "Ich würde auch gerne Auritas Familie kennenlernen. Kann Aurita mich zu ihrer Oma bringen?"
  },
  AvgDialog_21805_Content_51 = {
    Text = "Hmm! Oma müsste am zentralen Platz sein!"
  },
  AvgDialog_21805_Content_52 = {
    Text = "Aurita hüpfte die Treppe hinunter, und du, ohne weiter zu zögern, klopftest dir auf die Wangen, um vollständig wach zu werden."
  },
  AvgDialog_21805_Content_53 = {
    Text = "Es fängt draußen an zu regnen—"
  },
  AvgDialog_21805_Content_54 = {
    Text = "Auritas Stimme kommt von draußen; ihr klarer und lebhafter Ton ist durch die Holztür weniger deutlich."
  },
  AvgDialog_21805_Content_55 = {
    Text = "Du holst tief Luft, drückst die Tür auf und verlässt das kleine Gebäude, in dem Aurita lebt."
  },
  AvgDialog_21805_Content_56 = {
    Text = "Das Haus neigte sich, während es vom Boden verschlungen wurde, und feiner schwarzer Nebel strömte sowohl von den fernen Bergen als auch von den nahen schwebenden Bächen."
  },
  AvgDialog_21805_Content_57 = {
    Text = "Vor deinen Augen liegt eine Stadt, verschlungen von der Auflösung—"
  },
  AvgDialog_21805_Content_58 = {
    Text = "Aurita mag leichten Nieselregen; er ist kühl und erfrischend!"
  },
  AvgDialog_21805_Content_59 = {
    Text = "Hmm... aber lass uns trotzdem einen Regenschirm für dich finden."
  },
  AvgDialog_21805_Content_6 = {
    Text = "Was ist passiert..."
  },
  AvgDialog_21805_Content_60 = {
    Text = "Zack ist still, in Dunkelheit gehüllt.\nIm Chaos blieb nur Auritas Gestalt lebendig."
  },
  AvgDialog_21805_Content_7 = {
    Text = "Langsam öffnest du die Augen und siehst eine unbekannte Decke."
  },
  AvgDialog_21805_Content_8 = {
    Text = "Alt, ordentlich, aber ohne Charakter. Nur ein mit Wasser gefülltes Glasaquarium lässt es weniger wie ein gewöhnliches Hotelzimmer wirken."
  },
  AvgDialog_21805_Content_9 = {
    Text = "Was schaust du dir an? Die Häuser von Auritas Freunden?"
  },
  AvgDialog_21813_Content_1 = {
    Text = [[
...@2...Turm...
@4]]
  },
  AvgDialog_21813_Content_10 = {
    Text = "Hm...? Wie war noch mal sein Name...?"
  },
  AvgDialog_21813_Content_11 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_21813_Content_12 = {
    Text = "Aurita, vergiss nicht, wir gehen zum zentralen Platz, um deine Oma zu finden."
  },
  AvgDialog_21813_Content_13 = {
    Text = "Richtig! Lass uns hier entlanggehen—"
  },
  AvgDialog_21813_Content_14 = {
    Text = "Aurita ließ den „ausgerissenen“ Kameraden schnell hinter sich und schob dich in Richtung des Ziels."
  },
  AvgDialog_21813_Content_15 = {
    Text = "Du trittst um den Pfütze von D-Slime, die einst „Vit“ war, und fühlst eine Mischung aus Emotionen."
  },
  AvgDialog_21813_Content_16 = {
    Text = "In einer Stadt leben, die von der Auflösung verzehrt wird, und doch ihre Gegenwart weder sehen noch spüren können."
  },
  AvgDialog_21813_Content_17 = {
    Text = "Ihre Welt stirbt, und doch bleibt sie... völlig ahnungslos."
  },
  AvgDialog_21813_Content_2 = {
    Text = "Der mutierte Körper fiel steif zu Boden, wie übergegerbtes Leder, verschmolz mit dem A–Schleim auf dem Boden und verschwand schließlich aus dem Blickfeld."
  },
  AvgDialog_21813_Content_3 = {
    Text = "Huh...? Wo ist Vite?"
  },
  AvgDialog_21813_Content_4 = {
    Text = "Wie konnte er so schnell verschwinden! Aurita hat doch gar nicht Verstecken gespielt..."
  },
  AvgDialog_21813_Content_5 = {
    Text = "Auf dem Boden, wo einst \"Vitt\" saß, liegt ein kleiner keramischer Nachrichtenjunge."
  },
  AvgDialog_21813_Content_6 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_21813_Content_7 = {
    Text = "Aurita, Vite hat dir ein Geschenk hinterlassen."
  },
  AvgDialog_21813_Content_8 = {
    Text = "Nicht möglich—Wow! Das ist die Verzierung, die Aurita versprochen wurde!"
  },
  AvgDialog_21813_Content_9 = {
    Text = "Aurita will sie in die Häuser ihrer Freunde stellen! Danke, danke..."
  },
  AvgDialog_21814_Content_1 = {
    Text = "Ah! Es ist Vette!"
  },
  AvgDialog_21814_Content_10 = {
    Text = "Wenn Aurita zurückkehrt, nehmen wir auf jeden Fall alle mit zu Besuch."
  },
  AvgDialog_21814_Content_11 = {
    Text = "Bevor du über die subtile Kälte in Auritas Worten nachdenken konntest, bewegte sich Auritas „Freund\" plötzlich."
  },
  AvgDialog_21814_Content_12 = {
    Text = "...@2...Turm"
  },
  AvgDialog_21814_Content_13 = {
    Text = "Der Junge taumelte auf die Beine, schwarze Flüssigkeit sickerte aus ihm heraus.\nA–Schleim klebte ihn am Boden fest, und das Geräusch reißenden Fleisches war grauenhaft, als er sich aufrichtete."
  },
  AvgDialog_21814_Content_14 = {
    Text = "Klar! Vit hat es sehr eilig. Ich werde auf jeden Fall das luxuriöseste Zimmer für dich reservieren!"
  },
  AvgDialog_21814_Content_15 = {
    Text = "Unter der blassen Haut pulsieren die Muskeln seltsam, als ob etwas durchbrechen will –"
  },
  AvgDialog_21814_Content_16 = {
    Text = "Aurita, pass auf!"
  },
  AvgDialog_21814_Content_2 = {
    Text = "Das Mädchen klopft dir kräftig auf den Rücken, und auf ihre Geste hin schaust du zu dem Jungen, der an der Straßenecke sitzt."
  },
  AvgDialog_21814_Content_3 = {
    Text = "Aurita rannte aufgeregt zu ihm und enthüllte dabei einen dunklen Fleck auf ihrem Rücken.\nDoch bevor du genauer hinsehen konntest, flitzte sie wie der Wind an dir vorbei."
  },
  AvgDialog_21814_Content_4 = {
    Text = "Witt, schau dir unseren neuen Freund an!"
  },
  AvgDialog_21814_Content_5 = {
    Text = "Der Junge kauerte zusammengekrümmt in der Ecke, den Kopf gesenkt, und zeigte keinerlei Reaktion auf Auritas Annäherung."
  },
  AvgDialog_21814_Content_6 = {
    Text = "{Male=He,Female=She} ist größer als alle anderen, wenn wir zum Ozeanpalast zurückkehren, lassen wir {Male=him,Female=her} den Weg anführen! Bestimmt sehr imposant!"
  },
  AvgDialog_21814_Content_7 = {
    Text = "Ozeanpalast?"
  },
  AvgDialog_21814_Content_8 = {
    Text = "Oma hat gesagt, dass Aurita ein Kind des Meeres ist und dass wir eines Tages ins Wasser zurückkehren müssen."
  },
  AvgDialog_21814_Content_9 = {
    Text = "Wie Auritas Eltern – sie sind schon vorausgegangen, um ihr neues Zuhause unter Wasser vorzubereiten! Sobald alles bereit ist, wird Aurita zusammen mit ihrer Oma zu ihnen stoßen."
  },
  AvgDialog_21815_Content_1 = {
    Text = "Aurita schiebt dich durch die verfallende Stadt; mit der Zeit wird der ohnehin bedeckte Himmel noch dunkler."
  },
  AvgDialog_21815_Content_10 = {
    Text = "Ja! Sich in ein Seepferdchen verwandeln!"
  },
  AvgDialog_21815_Content_11 = {
    Text = "Während des Sprechens waren das Wiehern und das schwere Atmen von Pferden in der Nähe zu hören. Die schweren Hufschläge machten es schwer zu sagen, ob \"Pony\" ein weiteres Auflösungs-Körper war."
  },
  AvgDialog_21815_Content_12 = {
    Text = "Pony, Pony—"
  },
  AvgDialog_21815_Content_13 = {Text = "Zisch—"},
  AvgDialog_21815_Content_14 = {
    Text = "Diesmal warst du vorbereitet und packtest schnell Auritas Kragen, um sie davon abzuhalten, auf den skelettartigen Riesen zuzustürmen."
  },
  AvgDialog_21815_Content_2 = {
    Text = "Aurita, wie weit ist es noch bis zum Platz?"
  },
  AvgDialog_21815_Content_3 = {
    Text = "Das Mädchen klettert auf deinen Rücken, schaut sich vorsichtig um und zeigt schließlich auf eine Ecke."
  },
  AvgDialog_21815_Content_4 = {
    Text = "Da drüben! Nach dem Stall 50 Meter nach Norden!"
  },
  AvgDialog_21815_Content_5 = {
    Text = "Wurden hier früher Pferde gehalten?"
  },
  AvgDialog_21815_Content_6 = {
    Text = "Jetzt gibt es Pony! Pony ist auch Auritas Freund, und Aurita möchte es zurück zu ihrem Zuhause im Meer bringen!"
  },
  AvgDialog_21815_Content_7 = {
    Text = "In diesem Moment wird Pony sich in..."
  },
  AvgDialog_21815_Content_8 = {
    Text = "Sich verwandeln in..."
  },
  AvgDialog_21815_Content_9 = {
    Text = "Sich in ein Seepferdchen verwandeln?"
  },
  AvgDialog_21816_Content_1 = {
    Text = "Schneewittchen! Es ist Schneewittchen!"
  },
  AvgDialog_21816_Content_2 = {
    Text = "Aurita ist wieder entwischt und rannte auf etwas zu, das im A-Schleim lag—"
  },
  AvgDialog_21816_Content_3 = {
    Text = "Ein schwarzer Welpe."
  },
  AvgDialog_21816_Content_4 = {
    Text = "Weiß, Weißer Schnee?"
  },
  AvgDialog_21817_Content_1 = {
    Text = "Die ersten beiden Male wurden kleine Spielzeuge zurückgelassen, also sollte es diesmal keine Ausnahme sein..."
  },
  AvgDialog_21817_Content_2 = {
    Text = "Du hast lässig eine Mistgabel aus dem Stall genommen und den D-Slime gerührt, der einst \"Pony\" war. Sicher genug, ein besonders exquisiter keramischer Pony glänzte im Licht."
  },
  AvgDialog_21817_Content_3 = {
    Text = "Sammle \"Ponny\""
  },
  AvgDialog_21817_Content_4 = {
    Text = "Du zögerst einen Moment, ziehst aber schließlich deinen Mantel aus und hebst das Keramikpony durch den Stoff auf."
  },
  AvgDialog_21817_Content_5 = {
    Text = "Was machst du da?"
  },
  AvgDialog_21817_Content_6 = {
    Text = "Als du dich fast daran gewöhnt hattest, dass Auritas Stimme die verlassene Welt erfüllte, ertönte plötzlich eine greise Stimme, die dich erschrocken auffahren ließ."
  },
  AvgDialog_21817_Content_7 = {
    Text = "Oma— Aurita hat einen neuen Freund mitgebracht, um dich kennenzulernen!"
  },
  AvgDialog_21817_Content_8 = {
    Text = "Das gealterte Gesicht erhellte sich mit einem sanften Lächeln. Sie tätschelte liebevoll Auritas Kopf, bevor sie sich dir zuwandte."
  },
  AvgDialog_21817_Content_9 = {
    Text = "Hallo, junge Person. Ich bin Oma Betty aus Aurita. Nenn mich einfach Oma, so wie dieses Kind."
  },
  AvgDialog_21818_Content_1 = {
    Text = "\"Weißer Schnee\" gibt ein tiefes Wimmern von sich, seine Gliedmaßen lösen sich allmählich in D-Slime auf und behalten nicht mehr ihre canine Form."
  },
  AvgDialog_21818_Content_2 = {
    Text = "Wo „Schneewittchen“ verschwunden ist, liegt ein handtellergroßer weißer keramischer Welpe ruhig."
  },
  AvgDialog_21818_Content_3 = {
    Text = "Sammle \"Weiße Schnee\""
  },
  AvgDialog_21818_Content_4 = {
    Text = "Du bist also wirklich weiß..."
  },
  AvgDialog_21875_Content_1 = {
    Text = "Sieht aus, als hätte die Falle es erwischt."
  },
  AvgDialog_21875_Content_2 = {
    Text = "Verwende diese Werkzeuge, um es zu fangen!"
  },
  AvgDialog_22111_Content_1 = {Text = "Ah!—"},
  AvgDialog_22111_Content_10 = {
    Text = "Da... da ist..."
  },
  AvgDialog_22111_Content_100 = {
    Text = "Ich verstehe es nicht... Was bringt etwas, das niemand begreifen kann?"
  },
  AvgDialog_22111_Content_101 = {
    Text = "Hmm... Ich denke, Poesie besteht nicht nur aus Worten oder Bildern; sie ist wie ein Schlüssel."
  },
  AvgDialog_22111_Content_102 = {
    Text = "Ein... Schlüssel?"
  },
  AvgDialog_22111_Content_103 = {
    Text = "Ja! Das Herz eines Menschen ist wie eine Box, gefüllt mit vielen Emotionen. Diese Box ist verschlossen, und diese Emotionen werden normalerweise darin aufbewahrt, schwer herauszunehmen."
  },
  AvgDialog_22111_Content_104 = {
    Text = "Poesie ist der Schlüssel, um diese Truhe zu öffnen."
  },
  AvgDialog_22111_Content_105 = {
    Text = "Eigentlich muss Poesie nicht verstanden oder sogar gelesen werden."
  },
  AvgDialog_22111_Content_106 = {
    Text = "Alle, ob sie Gedichte lesen oder nicht, werden früher oder später diesen Schlüssel zu einem bestimmten Moment in ihrem Leben finden."
  },
  AvgDialog_22111_Content_107 = {
    Text = "Du wirst sicher der beste Schlosser werden!"
  },
  AvgDialog_22111_Content_108 = {
    Text = "Lügner... Du hast gerade gesagt, du hast es nicht verstanden."
  },
  AvgDialog_22111_Content_109 = {
    Text = "Ich verstehe nicht, was du sagst, aber ich vertraue dir, Horla."
  },
  AvgDialog_22111_Content_11 = {
    Text = "Du stehst am Rand des Gartenplatzes. Sichtbare D-Rifts steigen von unter dem kleinen Gebäude auf und umschließen den offenen Raum in der Mitte des Gartens."
  },
  AvgDialog_22111_Content_110 = {
    Text = "Dieses Gedicht, \"Die Wohnstätte der Rosen\", ist dein erstes Stück. Ab heute werde ich dir helfen, all deine Gedichte zu schätzen."
  },
  AvgDialog_22111_Content_111 = {
    Text = "Ich werde Nadeln benutzen, um sie zusammenzuhalten, und wenn ich Geld habe, werde ich eine schöne Gedichtsammlung drucken!"
  },
  AvgDialog_22111_Content_112 = {
    Text = "Sie streckte ihre Hand aus, die sie hinter ihrem Rücken gehalten hatte. Die Hände waren von Dornen verwundet, dunkel und rau, völlig unverkennbar als die einer jungen Frau."
  },
  AvgDialog_22111_Content_113 = {
    Text = "Das... das ist..."
  },
  AvgDialog_22111_Content_114 = {
    Text = "Die neuen Adligen sagen, dass Cité eine Stadt der Blumen und der Poesie ist. Ein gutes Gedicht kann dir einen Blumenstrauß mit Rosen einbringen..."
  },
  AvgDialog_22111_Content_115 = {
    Text = "Meine Rosen sind heute aufgeblüht. Nicht viele, und alle wurden verwendet, um die Miete und Pacht zu zahlen."
  },
  AvgDialog_22111_Content_116 = {
    Text = "Aber als sie nicht hingeschaut haben, habe ich heimlich eine Blume behalten..."
  },
  AvgDialog_22111_Content_117 = {
    Text = "Diese vernarbte Hand reichte Horla eine leicht beschädigte, aber immer noch lebhaft rote Rose."
  },
  AvgDialog_22111_Content_118 = {
    Text = "Ein feines Gedicht, Horla... In Zukunft tausche ich meine Blumen gegen deine Gedichte!"
  },
  AvgDialog_22111_Content_12 = {
    Text = "Das ist... unser Garten... nein... Colette, nein..."
  },
  AvgDialog_22111_Content_13 = {
    Text = "Horla senkte den Kopf. Colette trat zu ihr, hob ihr Kinn und lenkte ihren Blick auf die Mitte des Gartens."
  },
  AvgDialog_22111_Content_14 = {
    Text = "Weißt du, Horla... Vor vielen Jahren habe ich beobachtet, wie genau hier das große Feuer begann."
  },
  AvgDialog_22111_Content_15 = {
    Text = "Ich habe diesen Ort in einen Platz verwandelt und hier meine Statue errichtet... Sieh mal, ich verstehe auch Symbolik."
  },
  AvgDialog_22111_Content_16 = {
    Text = "Genau hinschauen. Sieh es klar. Das ist unser Zuhause... Das ist unser Garten. Bald wird alles dort verschwinden."
  },
  AvgDialog_22111_Content_17 = {
    Text = "Mein Leben begann wirklich an dem Tag, an dem du gestorben bist. Heute wird es wieder in Richtung Brillanz bewegen..."
  },
  AvgDialog_22111_Content_18 = {
    Text = "Der schwarze Riss breitet sich schnell aus. Bald ist die gesamte luxuriöse Villa ergriffen."
  },
  AvgDialog_22111_Content_19 = {
    Text = "Garten, Asche, Kritzeleien, Poesie, Erinnerungen, Lachen, Eide... Alles ist in die endlose Dunkelheit gesunken."
  },
  AvgDialog_22111_Content_2 = {
    Text = "Dein Überraschungsangriff hat das von Colette beschworene Monster erfolgreich besiegt. Die Welt innerhalb des Gedichts bebte und offenbarte einen Teil der wahren Form von Cité."
  },
  AvgDialog_22111_Content_20 = {
    Text = "Tick-tack—"
  },
  AvgDialog_22111_Content_21 = {
    Text = "Hä? Was ist mit meinen Augen los...?"
  },
  AvgDialog_22111_Content_22 = {
    Text = "War das... gerade eben Herzschmerz? Warum..."
  },
  AvgDialog_22111_Content_23 = {
    Text = "Eine Träne rutschte Horlas Gesicht hinunter."
  },
  AvgDialog_22111_Content_24 = {
    Text = "Tränen fallen zu Boden, wie Tropfen in einen ruhenden See. Stille Wellen breiten sich aus und streifen jedes blasse Herz in dieser illusorischen Welt."
  },
  AvgDialog_22111_Content_25 = {
    Text = "!! Nein... dieses Gefühl..."
  },
  AvgDialog_22111_Content_26 = {
    Text = "Colette bemerkte die Veränderung in ihren Emotionen. Sie sah überrascht zu Horla neben ihr."
  },
  AvgDialog_22111_Content_27 = {
    Text = "<LightGray:Ist das... Horlas Fähigkeit, Emotionen zu verbreiten?!>"
  },
  AvgDialog_22111_Content_28 = {
    Text = "<LightGray:Ihre Fähigkeit könnte nützlich sein! Ich muss diese Gelegenheit nutzen...>"
  },
  AvgDialog_22111_Content_29 = {
    Text = "Du willst mich töten und das Gedicht nutzen, um das Leben zu bekommen, das du dir wünschst... Egal, was du getan hast, ich habe dich nie gehasst, Kolette."
  },
  AvgDialog_22111_Content_3 = {
    Text = "Aber in dem Moment, in dem du dich Colette näherst, brechen zahllose Blumenranken aus dem Boden um sie herum hervor. Die Stacheln an den Ranken durchbohren eure Körper und binden euch fest."
  },
  AvgDialog_22111_Content_30 = {
    Text = "Die Colette, die ich einst kannte, war meine beste Freundin. Aber wenn du diesen Ort zerstörst... wird nur die gegenwärtige Colette übrig bleiben."
  },
  AvgDialog_22111_Content_31 = {
    Text = "Ich kann... nicht zulassen, dass die Colette, die ich einst kannte, von dir ausgelöscht wird..."
  },
  AvgDialog_22111_Content_32 = {
    Text = "Sieh dich selbst an, Horla... Was kannst du sonst noch tun, außer Gedichte zu schreiben?"
  },
  AvgDialog_22111_Content_33 = {
    Text = "Du hast recht... Abgesehen vom Dichten bin ich in nichts gut..."
  },
  AvgDialog_22111_Content_34 = {
    Text = "Cité, die Stadt der Blumen und Gedichte, ist unser Zuhause... Aber alle Rosen sind hier verwelkt, Colette..."
  },
  AvgDialog_22111_Content_35 = {
    Text = "Diese Rosen sind die, die du mir einmal gegeben hast. Heute gebe ich sie dir zurück."
  },
  AvgDialog_22111_Content_36 = {
    Text = "Sie macht einen Schritt nach vorne."
  },
  AvgDialog_22111_Content_37 = {Text = "Zack—"},
  AvgDialog_22111_Content_38 = {Text = "Horla!!!"},
  AvgDialog_22111_Content_39 = {
    Text = "Scharfe Dornen reißen ihre Kleider und durchdringen ihr Fleisch, aber es kümmert sie nicht."
  },
  AvgDialog_22111_Content_4 = {
    Text = "Du... hast meine Kleidung schmutzig gemacht..."
  },
  AvgDialog_22111_Content_40 = {
    Text = "Ein massiver Rosenstachel durchbohrte ihr Herz. Ihr Blut floss den schwarzen Weinberg hinunter und überquerte den ersten Ast."
  },
  AvgDialog_22111_Content_41 = {
    Text = "Die schwarzen Blumen verwelken rasch an den Ästen. Eine rote Rosenknospe erscheint, entfaltet sich und blüht."
  },
  AvgDialog_22111_Content_42 = {
    Text = "Blut fließt entlang der Ranken, wie die Adern der Blätter, und breitet sich in jede Ecke der Stadt aus."
  },
  AvgDialog_22111_Content_43 = {
    Text = "Wo es vorbeiging, verschwand die tiefe Dunkelheit. Es stellte Farbe und Emotion, Blumen und Poesie in die Cité zurück."
  },
  AvgDialog_22111_Content_44 = {
    Text = "Also... so viel Schmerz..."
  },
  AvgDialog_22111_Content_45 = {
    Text = "Herz... fühlt sich an, als wäre es durchbohrt worden..."
  },
  AvgDialog_22111_Content_46 = {
    Text = "Das ist... Mutter! Mutter..."
  },
  AvgDialog_22111_Content_47 = {
    Text = "Kind... mein Kind ist geboren..."
  },
  AvgDialog_22111_Content_48 = {
    Text = "Während sich das Blut ausbreitet, entfalten sich Szenen vor den Augen der Leute."
  },
  AvgDialog_22111_Content_49 = {
    Text = "Es ist die Wiedergeburt des Neugeborenen, das Wiegenlied der Mutter und der Abschied der Liebenden."
  },
  AvgDialog_22111_Content_5 = {
    Text = "Weißt du, wie viel dieses Outfit gekostet hat?"
  },
  AvgDialog_22111_Content_50 = {
    Text = "Das war der kostbarste Moment in eurem Leben."
  },
  AvgDialog_22111_Content_52 = {
    Text = "Die immense Schmerzen, die Horla erduldet hat, breiteten sich über ganz Cité aus und wogen mit ihrem Blut."
  },
  AvgDialog_22111_Content_53 = {
    Text = "Rosendornen durchbohren unzählige Herzen. Blutrote Blumen erblühen in jedem einzelnen."
  },
  AvgDialog_22111_Content_54 = {
    Text = "Colette, du besitzt die gesamte Cité, und doch lebst du immer noch hier."
  },
  AvgDialog_22111_Content_55 = {
    Text = "In dem Haus leben, von dem wir einst geträumt haben, im Garten, in dem wir einst gemeinsam gelebt haben..."
  },
  AvgDialog_22111_Content_56 = {
    Text = "Du hast einmal mein Leben gerettet. Dieses Gedicht, geschrieben mit Leben, ist für dich und für den Garten."
  },
  AvgDialog_22111_Content_57 = {
    Text = "Dies ist ein Gedicht geschrieben für den Garten im Frühling."
  },
  AvgDialog_22111_Content_58 = {
    Text = "Horla... du..."
  },
  AvgDialog_22111_Content_59 = {
    Text = "Tränen wischten ihr zartes Make-up weg, aber es war ihr egal, sie ließ sie chaotische Spuren auf ihrem Gesicht hinterlassen."
  },
  AvgDialog_22111_Content_6 = {
    Text = "Colette's Wut verschwand schnell. Sie nahm ihr edles und gefasstes Lächeln wieder auf."
  },
  AvgDialog_22111_Content_60 = {
    Text = "Colette konnte sich nicht erinnern, wann ihre Tränen zu fließen begonnen hatten."
  },
  AvgDialog_22111_Content_61 = {
    Text = "—Die vergangenen Szenen entblättern sich klar vor ihr. Zum ersten Mal verstand sie wirklich Horlas Poesie. Sie erkannte endlich, was sie wirklich schätzte."
  },
  AvgDialog_22111_Content_62 = {
    Text = "Nicht nur sie. Jeder in der Cité verstand das Gedicht von Horla. Sie waren bewegt von Horlas Emotionen und konnten sich nicht rühren."
  },
  AvgDialog_22111_Content_63 = {
    Text = "Es ist jetzt!"
  },
  AvgDialog_22111_Content_64 = {
    Text = "Du warst gut vorbereitet, deine mächtige Geistkraft erlaubte es dir, dich von Horlas Emotionen zu befreien."
  },
  AvgDialog_22111_Content_65 = {
    Text = "Du befreist dich von den Dornen und schnappst dir die Gedichtsammlung aus Colette's Hand."
  },
  AvgDialog_22111_Content_66 = {
    Text = "Lebewohl... Cité in den Gedichten!"
  },
  AvgDialog_22111_Content_67 = {
    Text = "Ein Blitz silberner Licht. Unter intensivem Licht verdampft das D-Mark auf dem Gedicht und löst sich schnell auf."
  },
  AvgDialog_22111_Content_68 = {Text = "Ugh! —"},
  AvgDialog_22111_Content_69 = {
    Text = "Ein scharfer Schmerz trifft dich. Der schwere Verlust an spiritueller Kraft überwältigt dich."
  },
  AvgDialog_22111_Content_7 = {
    Text = "Es ist alles in Ordnung, es ist alles in Ordnung..."
  },
  AvgDialog_22111_Content_70 = {
    Text = "Diese Gedichtsammlung, von Auflösung gereinigt, verwandelte sich in einen Stapel vergilbter alter Entwürfe, einfach mit einer einfachen Klammer zusammengeheftet, und fiel zu Boden."
  },
  AvgDialog_22111_Content_71 = {
    Text = "Ah! Ah!!—"
  },
  AvgDialog_22111_Content_72 = {
    Text = "Zahlreiche Monster brüllen, fallen zu Boden und verwandeln sich allmählich zurück in menschliche Gestalt."
  },
  AvgDialog_22111_Content_73 = {
    Text = "Verlangen verblasst, Emotionen kehren zurück. Das Fundament dieser Welt zerfällt."
  },
  AvgDialog_22111_Content_74 = {
    Text = "Colette fühlte es."
  },
  AvgDialog_22111_Content_75 = {
    Text = "Sie fühlte, wie ihre Macht schwand. Sie spürte die Niederlage nahtreten. Sie beschwor stachelige Klingen und ging auf Horla zu."
  },
  AvgDialog_22111_Content_76 = {
    Text = "\"Colette,\" Sieg... Als der Hund der alten Dame starb und sie mir seinen Namen gab, warst du direkt neben mir."
  },
  AvgDialog_22111_Content_77 = {
    Text = "Das ist der Name des Hundes, aber ich habe ihn nie geändert. Ich muss mich daran erinnern, mich nicht wieder zu verlieren."
  },
  AvgDialog_22111_Content_78 = {
    Text = "Du hast recht. Ich kann dich nicht vergessen, kann alles hier nicht vergessen..."
  },
  AvgDialog_22111_Content_79 = {
    Text = "Ich möchte gewinnen. Ich möchte einfach nur gewinnen. Was ist so falsch daran, gewinnen zu wollen?"
  },
  AvgDialog_22111_Content_8 = {
    Text = "Mich in meinem Garten herauszufordern – dazu muss man mutig und töricht zugleich sein."
  },
  AvgDialog_22111_Content_80 = {
    Text = "Es tut mir leid, Horla."
  },
  AvgDialog_22111_Content_81 = {
    Text = "Colette schluchzte vor Angst und näherte sich langsam Horla."
  },
  AvgDialog_22111_Content_82 = {
    Text = "Der Bereich verschwindet. Dein Plan ist gescheitert, Colette!"
  },
  AvgDialog_22111_Content_83 = {
    Text = "Selbst wenn du sie jetzt angreifst, wird sich nichts ändern!"
  },
  AvgDialog_22111_Content_84 = {
    Text = "Kämpfen, um Horla näher zu kommen, die intensive Schmerzen haben dich immobilisiert."
  },
  AvgDialog_22111_Content_85 = {
    Text = "Der Stachel richtet sich in Richtung des Kopfes von Horla."
  },
  AvgDialog_22111_Content_86 = {Text = "Warte!!"},
  AvgDialog_22111_Content_87 = {
    Text = "*Schnapp*—"
  },
  AvgDialog_22111_Content_88 = {
    Text = "Eine Rose wurde geschnitten. Colette nahm sie und reichte sie Horla."
  },
  AvgDialog_22111_Content_89 = {
    Text = "Ein feines Gedicht, Horla... Ich tausche meine Blumen gegen dein Gedicht."
  },
  AvgDialog_22111_Content_9 = {
    Text = "Du hast deine letzte Chance zur Flucht vertan... Bei dieser Feier musst du es mit mir durchstehen."
  },
  AvgDialog_22111_Content_90 = {Text = "Bang—"},
  AvgDialog_22111_Content_91 = {
    Text = "Vielleicht hat die Auflösung des Bereichs den Gärtner verändert."
  },
  AvgDialog_22111_Content_92 = {
    Text = "Oder vielleicht hat die Transformation des Gärtners dazu geführt, dass sich der Bereich auflöste."
  },
  AvgDialog_22111_Content_93 = {
    Text = "Die Cité in den Gedichten verschwindet allmählich, und die Macht, die Colette unterstützt hat, ist ebenfalls verschwunden."
  },
  AvgDialog_22111_Content_94 = {
    Text = "Ihr Körper verwandelte sich in einen Pool aus schwarzem Schlamm, vermischt mit verstreuten Blütenblättern, und versank vor Horla in den Boden."
  },
  AvgDialog_22111_Content_95 = {
    Text = "Colette, Colette, hast du das Lesen beendet?"
  },
  AvgDialog_22111_Content_96 = {
    Text = "Hmm... Ich habe es zu Ende gelesen... aber ich verstehe es nicht ganz."
  },
  AvgDialog_22111_Content_97 = {
    Text = "Ah, ist das so...? Dies ist mein erstes Gedicht. Es ist nicht sehr gut..."
  },
  AvgDialog_22111_Content_98 = {
    Text = "Es liegt nicht an dir, Horla. Ich verstehe die Gedichte von niemandem wirklich."
  },
  AvgDialog_22111_Content_99 = {
    Text = "Ich habe viele Menschen um mich herum gefragt, und sie konnten es auch nicht verstehen."
  },
  AvgDialog_22120_Content_1 = {
    Text = "Garten der gabelten Wege"
  },
  AvgDialog_22120_Content_10 = {
    Text = "Es wäre schade, wenn nicht einmal mein bester Freund es sehen könnte."
  },
  AvgDialog_22120_Content_11 = {
    Text = "Über den Garten lächelt die alte Frau zu dir."
  },
  AvgDialog_22120_Content_12 = {
    Text = "Mein Bildhauerfreund hat mir gesagt, dass nur diejenigen mit einem bestimmten Geschenk zu den Erwachenden werden können."
  },
  AvgDialog_22120_Content_13 = {
    Text = "So neidisch, Horla."
  },
  AvgDialog_22120_Content_14 = {
    Text = "Du bemerkst die Spuren der Auflösung an ihr und der Person, die hinter ihr steht."
  },
  AvgDialog_22120_Content_15 = {
    Text = "Der Verband der Bildhauer... Es scheint, dass die Situation hier vom Gärtner und den Mitgliedern des Verbandes der Bildhauer verursacht wurde."
  },
  AvgDialog_22120_Content_16 = {
    Text = "Hast du das Gedicht bei dir?"
  },
  AvgDialog_22120_Content_17 = {
    Text = "Die Relikte eines alten Freundes müssen natürlich gut bewahrt werden."
  },
  AvgDialog_22120_Content_18 = {
    Text = "Außerdem, nur zur Erinnerung, das ist nicht deine Sammlung von Gedichten – sie gehört schon immer mir."
  },
  AvgDialog_22120_Content_19 = {
    Text = "Cité ist so geworden... Warst du das?"
  },
  AvgDialog_22120_Content_2 = {
    Text = "Du bist... Colette..."
  },
  AvgDialog_22120_Content_20 = {
    Text = "Dieser Ort sollte \"Meine Cité\" genannt werden"
  },
  AvgDialog_22120_Content_21 = {
    Text = "Erinnerst du dich? Unser größter Traum war es, einfach ein Haus zu kaufen."
  },
  AvgDialog_22120_Content_22 = {
    Text = "Was ist jetzt? Die Poesie, die Menschen, das Land... und das Gebäude, von dem wir immer geträumt haben."
  },
  AvgDialog_22120_Content_23 = {
    Text = "Sieh, lieber Horla. Jetzt gehört ganz Cité mir."
  },
  AvgDialog_22120_Content_24 = {
    Text = "Colette, diese Frage beschäftigt mich seit vielen, vielen Jahren..."
  },
  AvgDialog_22120_Content_25 = {
    Text = "Horlas Finger verheddern sich nervös. Sie schaut auf, ihre hellen Augen sind auf Colette gerichtet."
  },
  AvgDialog_22120_Content_26 = {
    Text = "Warum machst du diese Dinge... Warum hast du dich in das verwandelt, was du jetzt bist..."
  },
  AvgDialog_22120_Content_27 = {
    Text = "Colette lächelte und schüttelte den Kopf."
  },
  AvgDialog_22120_Content_28 = {
    Text = "Du bist so clever, dass du schöne Gedichte schreiben kannst, ohne jemals dein Haus zu verlassen. Aber wenn es um Menschen geht, verstehst du wirklich nichts über sie..."
  },
  AvgDialog_22120_Content_29 = {
    Text = "Ich habe mich nie geändert, Horla."
  },
  AvgDialog_22120_Content_3 = {
    Text = "Horla öffnete leicht ihren Mund und starrte direkt auf die alte Frau über einen verbrannten Garten."
  },
  AvgDialog_22120_Content_30 = {
    Text = "Nein... unmöglich... du hast einmal klar..."
  },
  AvgDialog_22120_Content_31 = {
    Text = "Manchmal beneide ich dich wirklich. Ich beneide dein Talent, deine Gaben und sogar deine Unschuld."
  },
  AvgDialog_22120_Content_32 = {
    Text = "Aber warum... warum darfst du so unschuldig leben?"
  },
  AvgDialog_22120_Content_33 = {
    Text = "—Horla, Leute wie wir haben nicht das Privileg der Unschuld."
  },
  AvgDialog_22120_Content_34 = {
    Text = "Es ist nicht so, Colette..."
  },
  AvgDialog_22120_Content_35 = {
    Text = "Es interessiert mich überhaupt nicht, was in der Vergangenheit passiert ist. Bitte gib uns unser Gedicht zurück und stelle Cité wieder her..."
  },
  AvgDialog_22120_Content_36 = {
    Text = "Ist dir das nicht wichtig?"
  },
  AvgDialog_22120_Content_37 = {
    Text = "Als Colette einen lustigen Witz hörte, lachte sie laut und konnte sich kaum aufrichten."
  },
  AvgDialog_22120_Content_38 = {
    Text = "Dir liegt nichts daran... Was gibt dir das Recht, gleichgültig zu sein?"
  },
  AvgDialog_22120_Content_39 = {
    Text = "Verschone mich, Horla. Du hast mich nie verstanden. Du verstehst nichts."
  },
  AvgDialog_22120_Content_4 = {Text = "!!!"},
  AvgDialog_22120_Content_40 = {
    Text = "Sie stand auf, stellte ihre anmutige Haltung wieder her und nickte der Person neben ihr zu."
  },
  AvgDialog_22120_Content_41 = {
    Text = "Das Ritual beginnt heute Nacht. Ich lasse die Dinge hier in deinen Händen."
  },
  AvgDialog_22120_Content_42 = {
    Text = "Ritual? Was versuchst du zu tun?!"
  },
  AvgDialog_22120_Content_43 = {
    Text = "Colette ignorierte dich, passte ihre Kleidung an und ging in das Gebäude hinein."
  },
  AvgDialog_22120_Content_44 = {Text = "Warte!"},
  AvgDialog_22120_Content_45 = {
    Text = "Du hast versucht, ihr nachzujagen, aber das Gebäude verschwand plötzlich und erschien hinter dir erneut."
  },
  AvgDialog_22120_Content_46 = {
    Text = "Du hast entdeckt, dass die Struktur des Gartens völlig umgekehrt war, wie ein lebendiges Wesen."
  },
  AvgDialog_22120_Content_47 = {
    Text = "Hat sich die Struktur dieses Gartens verändert?"
  },
  AvgDialog_22120_Content_48 = {
    Text = "Ich schrieb in meiner Poesie über einen Garten des Lebens... aber der Garten in den Gedichten ist nicht wie dieser..."
  },
  AvgDialog_22120_Content_49 = {
    Text = "Das Gedicht befindet sich in den Händen der Gärtnerin; sie muss die Struktur hier verändert haben..."
  },
  AvgDialog_22120_Content_5 = {
    Text = "Sie ist... die Floristin..."
  },
  AvgDialog_22120_Content_50 = {
    Text = "Es ist noch unklar, wie dieser Ort entstanden ist. Es scheint jedoch, dass es ziemlich mühsam sein könnte, sie zu finden."
  },
  AvgDialog_22120_Content_51 = {
    Text = "Lass uns schnell hinter ihnen herlaufen!"
  },
  AvgDialog_22120_Content_52 = {
    Text = "Während Sie sich dem Gebäude mit Horla nähern, hören Sie plötzlich ihr Keuchen."
  },
  AvgDialog_22120_Content_53 = {
    Text = "{Male=Sir,Female=Madam} Schutzherr, was siehst du hier?"
  },
  AvgDialog_22120_Content_54 = {
    Text = "Horla zeigt auf die Stufen. Ein kleiner weißer Umschlag liegt dort, wo sie gerade standen."
  },
  AvgDialog_22120_Content_55 = {
    Text = "Du hast den Brief aufgehoben und geöffnet."
  },
  AvgDialog_22120_Content_56 = {
    Text = "\"An Herrn Herbert — Colette\"..."
  },
  AvgDialog_22120_Content_57 = {Text = "Klicken—"},
  AvgDialog_22120_Content_58 = {
    Text = "Als er die Wohnzimmertür aufgehen hörte, drehte sich der Mann nicht um und blickte weiterhin mit großem Interesse aus dem Fenster."
  },
  AvgDialog_22120_Content_59 = {
    Text = "Was für ein schöner Garten, Ms. Colette."
  },
  AvgDialog_22120_Content_6 = {
    Text = "Es ist wunderbar zu sehen, dass du immer noch so jung bist."
  },
  AvgDialog_22120_Content_60 = {
    Text = "Ihr Anwesen ist beneidenswert prestigeträchtig."
  },
  AvgDialog_22120_Content_61 = {
    Text = "Dank Mr. Herbert. Ohne deine Hilfe wäre ich an der Auflösung gestorben."
  },
  AvgDialog_22120_Content_62 = {
    Text = "Ganz zu schweigen davon, dass du sogar noch mehr haben kannst als zuvor..."
  },
  AvgDialog_22120_Content_63 = {
    Text = "Jede Partei bekommt, was sie braucht. Ich benötige deine Hilfe, um die Möglichkeit zu überprüfen, das Gebiet mit der realen Welt zu vereinen."
  },
  AvgDialog_22120_Content_64 = {
    Text = "Das aufgelöste Gedicht erzeugte so ein einzigartiges Gebiet. Sogar die aufgelösten Verse konnten reale Objekte stören"
  },
  AvgDialog_22120_Content_65 = {
    Text = "Selbst Mythag kann nicht viele so interessante Forschungsprojekte finden."
  },
  AvgDialog_22120_Content_66 = {
    Text = "Wenn man immer in Falschheit leben kann, dann hört die Falschheit auf zu existieren."
  },
  AvgDialog_22120_Content_67 = {
    Text = "Deine Weisheit ist wahrhaft erstaunlich, meine Dame."
  },
  AvgDialog_22120_Content_68 = {
    Text = "Wie läuft unsere Ritualvorbereitung?"
  },
  AvgDialog_22120_Content_69 = {
    Text = "Fast da... Wie dir befohlen, wird das Ritual nächsten Monat beginnen."
  },
  AvgDialog_22120_Content_7 = {
    Text = "Wie hast du Horla entdeckt?"
  },
  AvgDialog_22120_Content_70 = {
    Text = "Laut Ihrer Aussage wird zu diesem Zeitpunkt die Auflösung des Gedichts verbreitet und könnte sogar die gesamte Cité beeinflussen?"
  },
  AvgDialog_22120_Content_71 = {
    Text = "Ich erinnere mich nicht, dass du jemand bist, der sich um Moral kümmert."
  },
  AvgDialog_22120_Content_72 = {
    Text = "Natürlich. Aber ich sorge mich um das, was ich habe... Wird mein Bereich dann betroffen sein?"
  },
  AvgDialog_22120_Content_73 = {
    Text = "Heh... Seien Sie unbesorgt, meine Dame. Die Bildung des Bereichs steht in engem Zusammenhang mit der Auflösung. Je stärker die Auflösung, desto stabiler ist Ihr Bereich."
  },
  AvgDialog_22120_Content_74 = {
    Text = "Die Abdeckung des Bereichs ist noch begrenzt. Sobald das Ritual abgeschlossen ist, wird es sich über die gesamte Cité ausbreiten."
  },
  AvgDialog_22120_Content_75 = {
    Text = "Bis dahin werden all die Macht und der Reichtum von Cité dir gehören."
  },
  AvgDialog_22120_Content_76 = {
    Text = "\"Colette,\" Sieg... Hast du nicht immer gewonnen?"
  },
  AvgDialog_22120_Content_77 = {
    Text = "Die Floristin ging zum Fenster und schaute in ihren Garten."
  },
  AvgDialog_22120_Content_78 = {
    Text = "Sie versuchte, ein würdevolles nobles Lächeln aufrechtzuerhalten, aber das Weinglas in ihrer Hand zitterte unkontrollierbar."
  },
  AvgDialog_22120_Content_79 = {
    Text = "Das Gesicht der Edeldame wurde im schwankenden Weinglas reflektiert, wie eine eiternde Wunde."
  },
  AvgDialog_22120_Content_8 = {
    Text = "Ich habe dir bereits die Antwort gesagt."
  },
  AvgDialog_22120_Content_80 = {
    Text = "Wir werden alle Gewinner sein, Herr Herbert."
  },
  AvgDialog_22120_Content_9 = {
    Text = "In der neuen Cité sollten alle Dinge der Schönheit gesehen werden."
  },
  AvgDialog_22121_Content_1 = {
    Text = "Vergängliche Beerdigung"
  },
  AvgDialog_22121_Content_10 = {
    Text = "Vielleicht wurde es von diesem großen Feuer beeinflusst."
  },
  AvgDialog_22121_Content_11 = {
    Text = "Egal was, das hier sollte der Ort sein, den wir suchen."
  },
  AvgDialog_22121_Content_12 = {
    Text = "Horla, wo hast du das Gedicht hingelegt?"
  },
  AvgDialog_22121_Content_13 = {
    Text = "Als das Feuer ausbrach, grub ich ein kleines Loch, um die Gedichtsammlung zu schützen, legte sie in eine Kiste und begrub sie."
  },
  AvgDialog_22121_Content_14 = {
    Text = "Wir leben in einem Gewächshaus, in dem Rosen gezüchtet werden. Sie können es finden, indem Sie das Blumenbeet überqueren."
  },
  AvgDialog_22121_Content_15 = {Text = "Autsch!!"},
  AvgDialog_22121_Content_16 = {
    Text = "Ist da Gefahr?!"
  },
  AvgDialog_22121_Content_17 = {
    Text = "Ah, nein... {Male=Sir,Female=Madam} Schutzherr, schau dorthin."
  },
  AvgDialog_22121_Content_18 = {
    Text = "Horla zeigt aufgeregt auf eine Wand. Eine grobe Skizze ist mit buntem Kreide darauf gezeichnet."
  },
  AvgDialog_22121_Content_19 = {
    Text = "Zwei kleine Mädchen in Kleidern spielen, eine Dame und eine Dienstmagd zu sein."
  },
  AvgDialog_22121_Content_2 = {
    Text = "Wir sind hier!"
  },
  AvgDialog_22121_Content_20 = {
    Text = "Seit ich hierher gekommen bin, haben wir oft dieses Spiel gespielt. Manchmal spiele ich den Adligen, und manchmal Colette."
  },
  AvgDialog_22121_Content_21 = {
    Text = "Dieses Gemälde wurde von ihr gemacht, obwohl es nicht sehr gut aussieht. Doch wir hatten damals nicht mehr Kreide."
  },
  AvgDialog_22121_Content_22 = {
    Text = "Dieses rote Kleid wurde von ihr mit Rosensaft gefärbt... Es ist jetzt kaum noch sichtbar, was für eine Schade."
  },
  AvgDialog_22121_Content_23 = {
    Text = "Horlas Finger streichen sanft über die einfache Strichzeichnung, ein schwaches Lächeln hebt die Ecken ihrer Lippen."
  },
  AvgDialog_22121_Content_24 = {
    Text = "Colette... der Gärtner, der dich lebendig verbrannt hat, richtig?"
  },
  AvgDialog_22121_Content_25 = {
    Text = "Er ist auch mein bester Freund."
  },
  AvgDialog_22121_Content_26 = {
    Text = "In dem Blumengebäude aufzuwachsen war schön, aber ein wenig eng. Wir träumten davon, eines Tages ein Haus im kleinen Gebäude darüber zu haben."
  },
  AvgDialog_22121_Content_27 = {
    Text = "Jedoch habe ich am Ende nie dort leben können..."
  },
  AvgDialog_22121_Content_28 = {
    Text = "Horla sah bedauernd auf die prächtige Villa vor sich und ging weiter nach vorne."
  },
  AvgDialog_22121_Content_29 = {
    Text = "{Male=Sir,Female=Madam} Schutzherr, durch diesen Rosenblumengarten sind wir fast da."
  },
  AvgDialog_22121_Content_3 = {
    Text = "Gehe nordöstlich durch die geschäftige Medici Avenue in der Cité, bald erreichst du ein schönes Wohnviertel."
  },
  AvgDialog_22121_Content_30 = {
    Text = "Rosengarten? Wo ist der Rosengarten..."
  },
  AvgDialog_22121_Content_31 = {
    Text = "Der Hinterhof dieses Anwesens war einst mit Rosen gefüllt."
  },
  AvgDialog_22121_Content_32 = {
    Text = "Ist das Colette's Typ?"
  },
  AvgDialog_22121_Content_33 = {
    Text = "Hmm! Zu diesem Zeitpunkt waren wir gerade aus unserem alten Herrenhaus vertrieben worden und hatten keinen Ort, wo wir hingehen konnten..."
  },
  AvgDialog_22121_Content_34 = {
    Text = "Warte! Colette... Ich habe gerade das Zeichen gesehen. Ist das der Garten der Gräfin?"
  },
  AvgDialog_22121_Content_35 = {
    Text = "Hast du nicht gesagt, dass du seit langem keinen Garten mehr gesehen hast? Nun, das hier ist der schönste Garten in dieser Gegend."
  },
  AvgDialog_22121_Content_36 = {
    Text = "Colette, lass uns beeilen... Wenn wir erwischt werden, wird es viele Probleme geben!"
  },
  AvgDialog_22121_Content_37 = {
    Text = "Nein, wird es nicht. Schau—"
  },
  AvgDialog_22121_Content_38 = {
    Text = "Sie pflückte eine Rose und legte sie in Horlas Hand."
  },
  AvgDialog_22121_Content_39 = {
    Text = "Ahhh! Colette, wir werden im Gefängnis landen..."
  },
  AvgDialog_22121_Content_4 = {
    Text = "Ein palastähnliches Herrenhaus steht vor Ihnen, auffällig und prächtig."
  },
  AvgDialog_22121_Content_40 = {
    Text = "Niemand bleibt im Gefängnis. Horla, schau dort drüben!"
  },
  AvgDialog_22121_Content_41 = {
    Text = "Nachdem sie Colette gefolgt waren, sah Horla ein Gewächshaus, das wertvolle Rosen anbaute."
  },
  AvgDialog_22121_Content_42 = {
    Text = "Der Blumenraum enthielt zwei Betten und ihre wenigen Besitztümer."
  },
  AvgDialog_22121_Content_43 = {
    Text = "Colette... Was ist das?"
  },
  AvgDialog_22121_Content_44 = {
    Text = "Ich habe diesen Ort gemietet."
  },
  AvgDialog_22121_Content_45 = {
    Text = "Aber... wie hast du..."
  },
  AvgDialog_22121_Content_46 = {
    Text = "Sie bemerkte gerade, dass die Halskette, die ihre Mutter Colette ihr hinterlassen hatte, nicht mehr um ihren Hals war."
  },
  AvgDialog_22121_Content_47 = {
    Text = "Colette! Du..."
  },
  AvgDialog_22121_Content_48 = {
    Text = "Das hier ist nicht wichtig, Horla. Was zählt, ist, dass dies kein Garten eines Grafen ist—das ist unser Garten."
  },
  AvgDialog_22121_Content_49 = {
    Text = "Wir werden im Garten schlafen, kochen... Ich werde die Blumen, die auf diesem Land wachsen, verkaufen, um Kleidung und Essen für uns zu kaufen."
  },
  AvgDialog_22121_Content_5 = {
    Text = "Aber... warum hat sich dieser Ort so verändert?"
  },
  AvgDialog_22121_Content_50 = {
    Text = "Eines Tages kaufe ich sogar das Haus in diesem Gebäude!"
  },
  AvgDialog_22121_Content_51 = {
    Text = "Aber... was kann ich tun...?"
  },
  AvgDialog_22121_Content_52 = {
    Text = "Alles, was ich tun kann, ist Gedichte zu schreiben, die niemand liest..."
  },
  AvgDialog_22121_Content_53 = {
    Text = "Um ehrlich zu sein, verstehe ich deine Gedichte auch nicht... Aber das spielt keine Rolle. Schreib einfach, was du schreiben möchtest."
  },
  AvgDialog_22121_Content_54 = {
    Text = "Jeder hat etwas, wofür er geboren wurde. Ich wurde geboren, um für diesen Garten und dieses Haus zu streben."
  },
  AvgDialog_22121_Content_55 = {
    Text = "Und du, du wurdest zum Dichten geboren."
  },
  AvgDialog_22121_Content_56 = {
    Text = "Seitdem hat sie uns beide mit den Blumen aus diesem Garten unterstützt."
  },
  AvgDialog_22121_Content_57 = {
    Text = "Obwohl es extrem hart war und wir weit entfernt davon waren, ein Haus zu kaufen, konnte ich fühlen, dass wir tatsächlich ziemlich glücklich in dieser Zeit waren."
  },
  AvgDialog_22121_Content_58 = {
    Text = "Bis eines Tages der Verleger mir meine erste Zahlung für meine Gedichte schickte..."
  },
  AvgDialog_22121_Content_59 = {
    Text = "Obwohl sie Sie später im Gewächshaus einsperrte und das Feuer legte, scheinen Sie sie nicht zu hassen."
  },
  AvgDialog_22121_Content_6 = {
    Text = "Im weiten Garten zu seinen Füßen wuchs überall graues, verwelktes Gras. Du betratst den Garten."
  },
  AvgDialog_22121_Content_60 = {
    Text = "Hart zu sagen... Vielleicht. Ich weiß wirklich nicht, was ich tun soll."
  },
  AvgDialog_22121_Content_61 = {
    Text = "Ich weiß nur, dass, wenn es nicht für diese Gedichte gewesen wäre, dies alles nicht passiert wäre..."
  },
  AvgDialog_22121_Content_62 = {Text = "Horla..."},
  AvgDialog_22121_Content_63 = {
    Text = "Horlas Visionen entfalten sich vor dir. Ihr Kummer scheint greifbar, sich ausbreitend und alles um sie herum durchdringend."
  },
  AvgDialog_22121_Content_64 = {
    Text = "Es tut mir leid! {Male=Sir,Female=Madam} Schutzherr... Ich habe dich schon wieder traurig gemacht..."
  },
  AvgDialog_22121_Content_65 = {
    Text = "Es ist alles in Ordnung, zögere nicht, deine Emotionen zu zeigen."
  },
  AvgDialog_22121_Content_66 = {
    Text = "Lass uns weitersuchen nach der Gedichtsammlung."
  },
  AvgDialog_22121_Content_67 = {
    Text = "Das Gedicht ist dort drüben vergraben! {Male=Sir,Female=Madam} Schutzherr, bitte folge mir!"
  },
  AvgDialog_22121_Content_68 = {
    Text = "Du gehst durch die gewundenen Wege im Garten, kreist um die verbrannten Holzrahmen und gelangst zu einem offenen Platz hinter dem Hof."
  },
  AvgDialog_22121_Content_69 = {
    Text = "Wir sind hier!"
  },
  AvgDialog_22121_Content_7 = {
    Text = "Je näher du kommst, desto gedämpfter werden die Farben um dich herum... Sind das auch Teile der Vorstellung in deiner Gedichtsammlung?"
  },
  AvgDialog_22121_Content_70 = {
    Text = "Sie zeigte auf einen kleinen Fleck in der Mitte des Hinterhofes. Die umliegenden Rosen waren zu Asche und Dünger geworden, jetzt überwuchert von schwarzen Unkräutern."
  },
  AvgDialog_22121_Content_71 = {
    Text = "Der Bericht von Mythag sagt, dass sie Horlas Silber auf einer verbrannten Lichtung gefunden haben."
  },
  AvgDialog_22121_Content_72 = {
    Text = "—Das ist der Ort, an dem das Gedicht begraben ist. Das ist ihr letzter Ruheplatz."
  },
  AvgDialog_22121_Content_73 = {
    Text = "Seltsam... Hier ist ein Loch..."
  },
  AvgDialog_22121_Content_74 = {
    Text = "Die Gedichtsammlung... die Gedichtsammlung sollte hier vergraben sein!"
  },
  AvgDialog_22121_Content_75 = {
    Text = "Es war dort seit vielen Jahren nicht mehr."
  },
  AvgDialog_22121_Content_76 = {Text = "!!!"},
  AvgDialog_22121_Content_77 = {Text = "Wer?!—"},
  AvgDialog_22121_Content_78 = {
    Text = "Eine vertraute Stimme ertönt. Du drehst dich abrupt um."
  },
  AvgDialog_22121_Content_79 = {
    Text = "Die Hintertür der Villa öffnet sich, und die Adelige, die du auf dem Schiff getroffen hast, steht am Eingang und sieht auf dich herab."
  },
  AvgDialog_22121_Content_8 = {
    Text = "Ich kann mich nicht ganz erinnern... Aber das sollte nicht sein, oder...?"
  },
  AvgDialog_22121_Content_80 = {
    Text = "Nach dem großen Feuer hielt ich ein großes Begräbnis für dich. Es ist schade, dass du es selbst nicht sehen konntest."
  },
  AvgDialog_22121_Content_81 = {
    Text = "Als ich dich auf dem Schiff sah, machte mich das glücklich. Ich habe mich lange nicht so glücklich gefühlt."
  },
  AvgDialog_22121_Content_82 = {
    Text = "Jahrzehnte... Jahrzehnte, und wir treffen uns endlich wieder..."
  },
  AvgDialog_22121_Content_83 = {
    Text = "Willkommen zu Hause, Horla."
  },
  AvgDialog_22121_Content_9 = {
    Text = "Vielleicht liegt es daran, dass ich einige Gedichte über den Tod geschrieben habe."
  },
  AvgDialog_22122_Content_1 = {
    Text = "Zahlreiche Monster strömen auf die Bühne."
  },
  AvgDialog_22122_Content_2 = {
    Text = "Das funktioniert nicht. Horla, bleib in der Nähe. Lass uns von dieser Seite durchbrechen!"
  },
  AvgDialog_22122_Content_3 = {
    Text = "Aber wenn das der Fall ist... wird Colette diesen Ort zerstören..."
  },
  AvgDialog_22122_Content_4 = {
    Text = "Jetzt ist nicht die Zeit zu zögern. Es gibt zu viele Monster, und wir können Colette jetzt nicht aufhalten... Vertrau mir, Horla."
  },
  AvgDialog_22122_Content_5 = {
    Text = "Als sie deinen entschlossenen Blick sah, verstand Horla immer noch nicht deine Bedeutung, aber sie nickte."
  },
  AvgDialog_22122_Content_6 = {
    Text = "Ich... Ich verstehe..."
  },
  AvgDialog_22122_Content_7 = {
    Text = "{Male=Sir,Female=Madam} Schutzherr, sei vorsichtig!"
  },
  AvgDialog_22125_Content_1 = {
    Text = "Dichterfigur"
  },
  AvgDialog_22125_Content_10 = {
    Text = "Helles Licht aus einer unbekannten Quelle erleuchtet das Dach und die Tische des Straßenkaffees."
  },
  AvgDialog_22125_Content_100 = {
    Text = "Gehen wir, {Male=Sir,Female=Madam} Schutzherr, wir begeben uns zum Rosengarten... dorthin, wo ich gestorben bin."
  },
  AvgDialog_22125_Content_11 = {
    Text = "Horla badet im Licht, ihre Füße schwingen in der Luft zu einem unbekannten Rhythmus."
  },
  AvgDialog_22125_Content_12 = {
    Text = "Ich erinnere mich, in der Zeitung gelesen zu haben, dass die March Street ursprünglich eine gewöhnliche Straße war, aber Berühmtheit erlangte, weil ein Maler ein Stück für dieses Café geschaffen hat."
  },
  AvgDialog_22125_Content_13 = {
    Text = "Ich liebe diese Geschichte wirklich und habe einmal ein Gedicht darüber geschrieben. In dem Gedicht ließ sich der Künstler schließlich in der Nummer 99, End of March Street, nieder."
  },
  AvgDialog_22125_Content_14 = {
    Text = "Ich denke, es ist nicht so, dass die March Street den Maler getroffen hat, sondern vielmehr, dass der Maler die March Street getroffen hat."
  },
  AvgDialog_22125_Content_15 = {
    Text = "Cité ist so seltsam geworden, doch du scheinst überhaupt keine Angst zu haben, fühlst dich sogar recht wohl damit?"
  },
  AvgDialog_22125_Content_16 = {
    Text = "Hier, du musst nicht mit Leuten interagieren, aber du kannst viele neue und faszinierende Dinge entdecken."
  },
  AvgDialog_22125_Content_17 = {
    Text = "Ich kann es nicht so recht in Worte fassen, aber ich fühle mich hier immer mehr zu Hause als wenn ich die Zeitungen und Fotos von Cité anschaue..."
  },
  AvgDialog_22125_Content_18 = {
    Text = "Ah, schau, {Male=Sir,Female=Madam} Schutzherr! Das sind die Sterne!"
  },
  AvgDialog_22125_Content_19 = {
    Text = "Sterne? Aber hier scheint es weder Tag noch Nacht zu geben..."
  },
  AvgDialog_22125_Content_2 = {
    Text = "Zwei Tassen Kaffee... danke."
  },
  AvgDialog_22125_Content_20 = {
    Text = "Du schaust auf. Neben den schimmernden goldenen Sternen entfalten sich weiße Blütenblätter."
  },
  AvgDialog_22125_Content_21 = {
    Text = "Riesige, margeritenähnliche Sterne verwandeln den Himmel in einen Garten."
  },
  AvgDialog_22125_Content_22 = {
    Text = "Cité ist eine Stadt der Poesie und der Blumen... Ohne diese dringenden Angelegenheiten wäre es in der Tat recht angenehm."
  },
  AvgDialog_22125_Content_23 = {
    Text = "Nachdem wir etwa dreißig Minuten gewartet hatten, begegneten wir etwa hundert Bürgern ohne jegliche Angriffe... Diese Straßenbahn kann uns nicht belogen haben."
  },
  AvgDialog_22125_Content_24 = {
    Text = "Ah, {Male=Sir,Female=Madam} Schutzherr hat also die ganze Zeit beobachtet?"
  },
  AvgDialog_22125_Content_25 = {
    Text = "Keine Wahl. Einige blicken zu den Sternen, während andere den Boden unter ihren Füßen beobachten müssen."
  },
  AvgDialog_22125_Content_26 = {
    Text = "Obwohl ich nicht im Poesie begabt bin, kann ich als Hüter von Mythag diese Aufgabe dennoch bewältigen."
  },
  AvgDialog_22125_Content_27 = {
    Text = "Der Kontakt ist in der March Street 101. Mach dich bereit, lass uns gehen."
  },
  AvgDialog_22125_Content_28 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_22125_Content_29 = {Text = "Boom—"},
  AvgDialog_22125_Content_3 = {
    Text = "Bald brachte ein Waschbär, der in einer Kellneruniform gekleidet war, dir zwei Tassen Kaffee."
  },
  AvgDialog_22125_Content_30 = {Text = "Wer?!"},
  AvgDialog_22125_Content_31 = {
    Text = "Ungewiss über die Gefahren hier, beobachtest du vorsichtig deine Umgebung."
  },
  AvgDialog_22125_Content_32 = {
    Text = "Ah, Grüße an euch beide!"
  },
  AvgDialog_22125_Content_33 = {
    Text = "Puh... Wir treffen uns wieder..."
  },
  AvgDialog_22125_Content_34 = {
    Text = "Hallo! Madam Schmetterling, Herr Raupe!"
  },
  AvgDialog_22125_Content_35 = {
    Text = "Was machst du?"
  },
  AvgDialog_22125_Content_36 = {
    Text = "Mein Mann und ich haben zu Abend gegessen und bereiteten uns darauf vor, einen Spaziergang durch die Straße zu machen."
  },
  AvgDialog_22125_Content_37 = {
    Text = "Was für ein Zufall! Ich habe das Gedicht gehört, das von jener jungen Dame geschrieben wurde—es ist absolut wunderschön!"
  },
  AvgDialog_22125_Content_38 = {
    Text = "Vielen Dank..."
  },
  AvgDialog_22125_Content_39 = {
    Text = "Seid ihr beide verloren?"
  },
  AvgDialog_22125_Content_4 = {
    Text = "Du hast große Fortschritte gemacht und kannst jetzt mit Fremden sprechen."
  },
  AvgDialog_22125_Content_40 = {
    Text = "Die Straßen hier entsprechen nicht den Markierungen auf der Karte, und die Hausnummern sind alle durcheinander..."
  },
  AvgDialog_22125_Content_41 = {
    Text = "Entschuldigen Sie, wissen Sie, wo sich die March Street Nr. 101 befindet?"
  },
  AvgDialog_22125_Content_42 = {
    Text = "101... Ich erinnere mich, war da nicht die Rede davon, dass es keine Nr. 101 in der March Street gibt?"
  },
  AvgDialog_22125_Content_43 = {
    Text = "Ist das so..."
  },
  AvgDialog_22125_Content_44 = {
    Text = "Dieser Ort ist nicht sehr groß. Lass uns langsam weitersuchen."
  },
  AvgDialog_22125_Content_45 = {
    Text = "Es tut mir leid, dass ich dir nicht viel helfen konnte."
  },
  AvgDialog_22125_Content_46 = {
    Text = "Nehmt euch Zeit mit der Suche. Genießt euren Aufenthalt in Cité~"
  },
  AvgDialog_22125_Content_47 = {
    Text = "Nachdem du dich von der Schmetterlingslady und Mr. Raupe verabschiedet hast, setzt du deinen Weg durch die Straßen der March Street fort und überprüfst die Zahlen auf den Türschildern eins nach dem anderen."
  },
  AvgDialog_22125_Content_48 = {
    Text = "Hmm, ich erinnere mich nicht, dass die Märzstraße so lang war..."
  },
  AvgDialog_22125_Content_49 = {
    Text = "Wir haben bereits zweimal alles durchgesehen."
  },
  AvgDialog_22125_Content_5 = {
    Text = "Nur eine Person, und sie sieht aus wie ein Tier, wäre etwas besser..."
  },
  AvgDialog_22125_Content_50 = {
    Text = "Huh? Aber ich sehe nicht, wo sich Nr. 101 befindet..."
  },
  AvgDialog_22125_Content_51 = {
    Text = "Das erste Mal fiel es mir nicht auf, aber das zweite Mal beobachtete ich sorgfältig alle Türnummern."
  },
  AvgDialog_22125_Content_52 = {
    Text = "San Yue Straße... Es gibt keine Nr. 101."
  },
  AvgDialog_22125_Content_53 = {
    Text = "Die größte Hausnummer hier ist diese."
  },
  AvgDialog_22125_Content_54 = {
    Text = "Du stehst an der Wand am Ende der Straße. Das Metallschild am kleinen Gebäude vor dir wurde durch ein Gemälde ersetzt."
  },
  AvgDialog_22125_Content_55 = {
    Text = "März Straße... Nr. 99"
  },
  AvgDialog_22125_Content_56 = {Text = "Wer?"},
  AvgDialog_22125_Content_57 = {
    Text = "Die Tür platzt auf und offenbart eine dünne Gestalt vor dir."
  },
  AvgDialog_22125_Content_58 = {
    Text = "Auf den mit Farbe bespritzten, zerschlissenen Kleidern ist das Gesicht eines Insekts."
  },
  AvgDialog_22125_Content_59 = {
    Text = "Seid ihr Diebe?!"
  },
  AvgDialog_22125_Content_6 = {
    Text = "Obwohl ich mir nicht sicher bin, ob es eine gute Sache ist, sind endlich mehr Menschen um mich herum."
  },
  AvgDialog_22125_Content_60 = {
    Text = "Ähm... nein, wir sind Touristen hier, um einen Freund zu besuchen. Er ist in der 101 March Street..."
  },
  AvgDialog_22125_Content_61 = {
    Text = "Was ist die Nummer?!!!"
  },
  AvgDialog_22125_Content_62 = {
    Text = "1... Äh, Nummer 88."
  },
  AvgDialog_22125_Content_63 = {
    Text = "Du hast 101 erwähnt... Hier gibt es kein 101..."
  },
  AvgDialog_22125_Content_64 = {
    Text = "Ihr Diebe... Ihr habt mein Gemälde gestohlen! Ihr wart es, die mein Gemälde gestohlen haben!!"
  },
  AvgDialog_22125_Content_65 = {
    Text = "Mit den Bewegungen des Malers verändert sich die umgebende Szene plötzlich."
  },
  AvgDialog_22125_Content_66 = {
    Text = "Plötzlich erschienen einige schillernde und bizarre Farben an den nahegelegenen Gebäuden, die wie ein vollständiges Gemälde aussahen, das von einer unbekannten Kraft in chaotische Farbtöne zerrissen wurde."
  },
  AvgDialog_22125_Content_67 = {
    Text = "Ist das... Auflösung?!"
  },
  AvgDialog_22125_Content_68 = {
    Text = "Ungewiss über das Prinzip hinter diesem Phänomen, ziehst du dich schnell mit Horla zurück."
  },
  AvgDialog_22125_Content_69 = {
    Text = "Gib mir mein Gemälde zurück...!"
  },
  AvgDialog_22125_Content_7 = {
    Text = "Hat Mr. Raupe nicht gesagt, dass die meisten Menschen uns nicht schaden werden, solange wir uns nicht merkwürdig verhalten?"
  },
  AvgDialog_22125_Content_70 = {
    Text = "Seine Hand streckte sich nach dir aus. Bevor sie dich berührte, strömten seltsame Farben um ihn herum wie eine Flut und verschlangen ihn..."
  },
  AvgDialog_22125_Content_71 = {
    Text = "Bald hörten die unheimlichen Farben auf zu winden. Du beobachtest still die Szene vor dir."
  },
  AvgDialog_22125_Content_72 = {
    Text = "Das Schulabzeichen auf deiner Brust strahlte in einem silbernen Licht."
  },
  AvgDialog_22125_Content_73 = {
    Text = "Cité... Ist wieder etwas passiert?"
  },
  AvgDialog_22125_Content_74 = {
    Text = "Ein Gebäude ist verschwunden."
  },
  AvgDialog_22125_Content_75 = {
    Text = "Der Ort befindet sich in der Märzstraße..."
  },
  AvgDialog_22125_Content_76 = {Text = "Nein. 99."},
  AvgDialog_22125_Content_77 = {
    Text = "Du schaust dir das verbliebene Türschild mit der Nummer 99 an und atmest tief ein."
  },
  AvgDialog_22125_Content_78 = {
    Text = "Wir können nicht zulassen, dass die Dinge so weitergehen... Ohne einen Kontakt müssen wir einen anderen Weg finden."
  },
  AvgDialog_22125_Content_79 = {
    Text = "{Male=Sir,Female=Madam} Schutzherr, es gibt noch eine Vermutung..."
  },
  AvgDialog_22125_Content_8 = {
    Text = "Hoffe, dass keine weiteren Bienen kommen, um für mich zu „singen“..."
  },
  AvgDialog_22125_Content_80 = {
    Text = "Nein, kein Rätsel. Ich bin mir sicher."
  },
  AvgDialog_22125_Content_81 = {
    Text = "Das ist nicht die Cité!"
  },
  AvgDialog_22125_Content_82 = {
    Text = "...Horla, was sagst du da?"
  },
  AvgDialog_22125_Content_83 = {
    Text = "Ich meine, das ist nicht die echte Cité."
  },
  AvgDialog_22125_Content_84 = {
    Text = "Das ist nicht die echte Cité...?"
  },
  AvgDialog_22125_Content_85 = {
    Text = "Der Raupenzug, für den man ein Gedicht als Fahrkarte braucht, Madame Schmetterling, nur die Märzstraße Nr. 99, der Maler, Gänseblümchen-Sterne..."
  },
  AvgDialog_22125_Content_86 = {
    Text = "Diese Dinge, die wir gesehen haben, habe ich schon immer als äußerst vertraut empfunden. Es war erst jetzt, dass ich mich endlich daran erinnerte, warum."
  },
  AvgDialog_22125_Content_87 = {
    Text = "Diese Dinge sind alle in meiner Gedichtsammlung aufgetaucht. Alles hier ist genau so, wie ich es in meinen Gedichten vorgestellt habe..."
  },
  AvgDialog_22125_Content_88 = {
    Text = "{Male=Sir,Female=Madam} Schutzherr, das ist nicht die echte Cité."
  },
  AvgDialog_22125_Content_89 = {
    Text = "Das ist die <Yellow:Cité meiner Vorstellung>..."
  },
  AvgDialog_22125_Content_9 = {
    Text = "Auf der weiten Straße kommen Bürger mit verschiedenen Tierköpfen und gehen, ohne Anzeichen von Aggression zu zeigen."
  },
  AvgDialog_22125_Content_90 = {
    Text = "Unter den chaotischen Farben der March Street drehte sich Horla langsam im Kreis und schaute auf alles, was zu ihren Gedichten gehörte."
  },
  AvgDialog_22125_Content_91 = {
    Text = "Das Licht fällt wie ein Schleier und beleuchtet ihr Gesicht, das voller Neugier, Traurigkeit und Verwirrung ist."
  },
  AvgDialog_22125_Content_92 = {
    Text = "Ich verstehe... Kein Wunder, dass es hier so viele bizarre Dinge gibt."
  },
  AvgDialog_22125_Content_93 = {
    Text = "Aber wie konnte es zur Cité kommen"
  },
  AvgDialog_22125_Content_94 = {
    Text = "Ich weiß es auch nicht... Einige Dinge hier sind nicht ganz dasselbe wie in meinen Gedichten."
  },
  AvgDialog_22125_Content_95 = {
    Text = "Alles im Gedicht hätte schön und ewig sein sollen... Ich weiß nicht, warum es so geworden ist..."
  },
  AvgDialog_22125_Content_96 = {
    Text = "Aber ich denke, wenn wir das Problem hier lösen wollen, müssen wir zuerst dieses Gedicht finden."
  },
  AvgDialog_22125_Content_97 = {
    Text = "Erinnerst du dich immer noch an den Weg?"
  },
  AvgDialog_22125_Content_98 = {
    Text = "In meiner Poesie ist die March Street nahe der Heimat. Ich erinnere mich immer an den Rückweg."
  },
  AvgDialog_22125_Content_99 = {
    Text = "Sie blickt in die Wohngegend, Trauer wie ein greifbarer Nebel umhüllt dich."
  },
  AvgDialog_22126_Content_1 = {
    Text = "Huff... Huff... {Male=Sir,Female=Madam} Schutzherr, es sind zu viele Monster, um sie zu bewältigen..."
  },
  AvgDialog_22126_Content_10 = {
    Text = "—Durchzubrechen, um Verstärkung zu holen, ist nur eine List. Dies ist die Gelegenheit, auf die du gewartet hast."
  },
  AvgDialog_22126_Content_11 = {
    Text = "Zügel sie, Horla!"
  },
  AvgDialog_22126_Content_12 = {
    Text = "Du drehst dich plötzlich um."
  },
  AvgDialog_22126_Content_13 = {
    Text = "Horla pausierte einen Moment, verstand deine Absicht und stürmte dann mit dir auf Colette zu..."
  },
  AvgDialog_22126_Content_14 = {
    Text = "Das ist es!!"
  },
  AvgDialog_22126_Content_15 = {
    Text = "Ein riesiges blütenförmiges Monster bildet sich aus den Lianen rund um den Platz und blockiert Colettes Weg."
  },
  AvgDialog_22126_Content_16 = {
    Text = "Gute Idee, Hüter. Aber ich lasse keine Überraschungen meinen Plan beeinflussen."
  },
  AvgDialog_22126_Content_17 = {
    Text = "Hör zu, Horla. Dieses Gedicht ist für dich geschrieben—"
  },
  AvgDialog_22126_Content_2 = {
    Text = "Die Auflösung wächst immer größer. Wenn das so weitergeht, werden wir hier gefangen sein..."
  },
  AvgDialog_22126_Content_3 = {
    Text = "Ich habe euer Gespräch belauscht, als ihr in der Cité angekommen seid."
  },
  AvgDialog_22126_Content_4 = {
    Text = "Suchst du nach Verstärkung? Ich werde dir nicht die Chance geben, Hüter."
  },
  AvgDialog_22126_Content_5 = {
    Text = "Unter Colette's Befehl strömen Horden von Monstern zum Ausgang und blockieren komplett Ihren Weg."
  },
  AvgDialog_22126_Content_6 = {
    Text = "Die Gelegenheit ist gekommen. Nur einmal."
  },
  AvgDialog_22126_Content_7 = {
    Text = "Huh? ...Was... was meinst du..."
  },
  AvgDialog_22126_Content_8 = {
    Text = "Dein peripheres Sehen erfasst Colette, die alle Monster hinter der Bühne ausschaltet, um deinen Fluchtweg zu blockieren."
  },
  AvgDialog_22126_Content_9 = {
    Text = "Um sie herum hat die Anzahl der Monster erheblich abgenommen, was es dir ermöglicht, etwas zu versuchen."
  },
  AvgDialog_22127_Content_1 = {
    Text = "Stadt der Blüten"
  },
  AvgDialog_22127_Content_10 = {
    Text = "Diese schönen Szenen scheinen Horla die schmerzhaften Erinnerungen sowie die Fremden um ihn herum vergessen zu lassen."
  },
  AvgDialog_22127_Content_100 = {
    Text = "Hallo, wenn du nicht reinkommst, gehe ich jetzt. Andere Passagiere warten."
  },
  AvgDialog_22127_Content_101 = {
    Text = "Du siehst es vorsichtig an. Der Raupenzug scheint nicht feindlich gesinnt zu sein"
  },
  AvgDialog_22127_Content_102 = {
    Text = "Entschuldigen Sie, fährt dieser Bus zur Medici Avenue?"
  },
  AvgDialog_22127_Content_103 = {
    Text = "Natürlich, natürlich... Diese Straßenbahn kann dich überall hinbringen."
  },
  AvgDialog_22127_Content_104 = {
    Text = "Ein Schienenfahrzeug, das überallhin fahren kann, huh... Das macht Sinn."
  },
  AvgDialog_22127_Content_105 = {
    Text = "Wie dem auch sei, dieses Fahrzeug dient tatsächlich dem Transport von Passagieren."
  },
  AvgDialog_22127_Content_106 = {
    Text = "Der Körper der Raupe öffnet sich und gibt einen ordentlichen Platz darin preis."
  },
  AvgDialog_22127_Content_107 = {
    Text = "Als du die erwartungsvollen Augen von Horla siehst, setzt du dich hin."
  },
  AvgDialog_22127_Content_108 = {
    Text = "Entschuldigung, wie bezahle ich das Ticket?"
  },
  AvgDialog_22127_Content_109 = {Text = "Kostenlos."},
  AvgDialog_22127_Content_11 = {
    Text = "Ihre Augen schimmerten, während sie dir durch diese malerische Stadt folgten."
  },
  AvgDialog_22127_Content_110 = {
    Text = "Es scheint, dass heute gar nicht so schlimm ist, schließlich gibt es eine kostenlose Fahrt..."
  },
  AvgDialog_22127_Content_111 = {
    Text = "Nicht kostenlos. Um ein Ticket für diesen Wagen zu erhalten, musst du mit einem Gedicht bezahlen."
  },
  AvgDialog_22127_Content_112 = {Text = "???"},
  AvgDialog_22127_Content_113 = {
    Text = "Ah, genau... Dieses junge Fräulein muss eine Einheimische sein."
  },
  AvgDialog_22127_Content_114 = {
    Text = "Horla, wie weißt du überhaupt diese Regeln..."
  },
  AvgDialog_22127_Content_115 = {
    Text = "Ich bin mir nicht ganz sicher... So erinnere ich es nur."
  },
  AvgDialog_22127_Content_116 = {
    Text = "Es ist nicht kostspielig; jeder muss nur einen einfachen Satz schreiben."
  },
  AvgDialog_22127_Content_117 = {
    Text = "Ich gehe zuerst..."
  },
  AvgDialog_22127_Content_118 = {
    Text = "Sie trat an die Vorderseite des Busses und flüsterte etwas in die Fahrgeldkasse neben dem Fahrersitz."
  },
  AvgDialog_22127_Content_119 = {
    Text = "Ah... Was für ein schönes Gedicht! Bitte nimm Platz, Fräulein."
  },
  AvgDialog_22127_Content_12 = {
    Text = "...Es ist beeindruckend, dass du jetzt noch den Mut hast, darüber nachzudenken."
  },
  AvgDialog_22127_Content_120 = {
    Text = "Kann ich auch einen Blick darauf werfen?"
  },
  AvgDialog_22127_Content_121 = {
    Text = "Ich... Es ist mir etwas peinlich... Ich schreibe es dir heimlich, wenn wir zurück sind, {Male=Keeper Sir,Female=Madam Keeper}."
  },
  AvgDialog_22127_Content_122 = {
    Text = "Du bist dran, {Male=Sir,Female=Madam}."
  },
  AvgDialog_22127_Content_123 = {
    Text = "Hmm, lass mich nachdenken..."
  },
  AvgDialog_22127_Content_124 = {
    Text = "Die Straßenbahn kroch langsam wie eine Raupe über die Gleise."
  },
  AvgDialog_22127_Content_125 = {
    Text = "Mein Vergleich ist ziemlich genial, ähnlich wie etwas anderes."
  },
  AvgDialog_22127_Content_126 = {
    Text = "Beeile dich, lass uns zur Medici Avenue gehen!"
  },
  AvgDialog_22127_Content_127 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_22127_Content_128 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_22127_Content_129 = {
    Text = "Im Allgemeinen musst du einen Satz umschreiben, aber das Gedicht dieser Dame könnte Saisonkarten für alle Plätze kaufen, und ich möchte keinen weiteren Qualen ausgesetzt sein. Bitte, nimm Platz."
  },
  AvgDialog_22127_Content_13 = {
    Text = "Horla, findest du nicht, dass die Stadt Cité seltsam geworden ist?"
  },
  AvgDialog_22127_Content_130 = {
    Text = "Die Raupe öffnete ihre Augen, und ein helles Licht strahlte aus ihnen."
  },
  AvgDialog_22127_Content_131 = {
    Text = "Es bewegt sich stetig vorwärts."
  },
  AvgDialog_22127_Content_14 = {
    Text = "Nein, obwohl ich vergessen habe, wie die Cité aussieht, denke ich, sie sollte so aussehen."
  },
  AvgDialog_22127_Content_15 = {
    Text = "Diese Dame hat recht. Cité, eine Stadt der Blumen und der Poesie, sollte in der Tat so aussehen."
  },
  AvgDialog_22127_Content_16 = {
    Text = "Die Edeldame lächelte und tätschelte Horlas Rücken."
  },
  AvgDialog_22127_Content_17 = {Text = "Hehe..."},
  AvgDialog_22127_Content_18 = {
    Text = "Nur jetzt, als sie zu begreifen scheint, dass ein Fremder neben ihr steht, lächelte sie verlegen und errötete, während sie sich ein wenig hinter dem Pergament versteckte."
  },
  AvgDialog_22127_Content_19 = {
    Text = "Eine klare Glocke läutet, und eine Kutsche erscheint vor dir."
  },
  AvgDialog_22127_Content_2 = {
    Text = "Das... Das ist zu..."
  },
  AvgDialog_22127_Content_20 = {
    Text = "Ah, mein Transport ist fast hier... Ich kann nicht länger bei dir bleiben."
  },
  AvgDialog_22127_Content_21 = {
    Text = "Ich habe nicht erwartet, dass du kommst, also habe ich kein Geschenk vorbereitet... Hier, das ist für dich. Ich hoffe, du wirst es nicht ablehnen."
  },
  AvgDialog_22127_Content_22 = {
    Text = "Sie streckt ihre Hand aus und präsentiert etwas Horla."
  },
  AvgDialog_22127_Content_23 = {Text = "Das ist..."},
  AvgDialog_22127_Content_24 = {
    Text = "Eine mit Wasserfarben gefärbte Rose zittert leicht im Wind aus unbekannter Richtung."
  },
  AvgDialog_22127_Content_25 = {
    Text = "Horla schaut freudig auf, um Dankbarkeit auszudrücken, aber die alte Frau hat bereits die Kutsche bestiegen."
  },
  AvgDialog_22127_Content_26 = {
    Text = "Abschied, Horla."
  },
  AvgDialog_22127_Content_27 = {
    Text = "Die Kutsche bewegt sich vorwärts und verschwimmt bald in dem fernen Tintenbild."
  },
  AvgDialog_22127_Content_28 = {
    Text = "Diese ältere Dame ist wirklich freundlich. Aber da ist etwas ein wenig seltsam an ihr..."
  },
  AvgDialog_22127_Content_29 = {
    Text = "In der Tat... Oh mein Gott, ich habe vergessen, sie nach dem Weg zu fragen."
  },
  AvgDialog_22127_Content_3 = {
    Text = "Cité, die Stadt der Blumen und Poesie."
  },
  AvgDialog_22127_Content_30 = {
    Text = "Never mind, lass uns nach jemandem in der Nähe suchen."
  },
  AvgDialog_22127_Content_31 = {
    Text = "So eine große Stadt, aber es gibt so wenige Menschen auf den Straßen... Das ist wirklich seltsam."
  },
  AvgDialog_22127_Content_32 = {
    Text = "Änderungen in visuellen Merkmalen, Abweichungen in Zahlen... Die Aussagen der Zeugen waren nicht falsch."
  },
  AvgDialog_22127_Content_33 = {
    Text = "......In der Tat. So sieht die Situation in der Cité ungefähr aus."
  },
  AvgDialog_22127_Content_34 = {
    Text = "Hier sind die Dinge seltsam, aber es wurden bisher keine Gefahren oder Anzeichen der Auflösung gefunden."
  },
  AvgDialog_22127_Content_35 = {
    Text = "Horla und ich bereiten uns darauf vor, weiterzuziehen, den Kontakt so schnell wie möglich zu finden und die Situation hier zu verifizieren."
  },
  AvgDialog_22127_Content_36 = {
    Text = "Die Schule bereitet sich darauf vor, Verstärkungen zuzuweisen, aber es wird einige Zeit in Anspruch nehmen."
  },
  AvgDialog_22127_Content_37 = {
    Text = "Verstanden. Bis dahin überlasst uns die Untersuchung in Cité."
  },
  AvgDialog_22127_Content_38 = {
    Text = "Nachdem du den Silber-Kommunikator ausgeschaltet hast, scannst du wachsam deine Umgebung"
  },
  AvgDialog_22127_Content_39 = {
    Text = "Diese Stadt scheint von einem merkwürdigen Filter umhüllt zu sein, wobei alle Gebäude bizarr stehen, wie hastig verschmierte Ölgemälde."
  },
  AvgDialog_22127_Content_4 = {
    Text = "Die heutige Cité entspricht wirklich ihrem Namen."
  },
  AvgDialog_22127_Content_40 = {
    Text = "Du bist jetzt zehn Minuten lang diese Straße entlanggegangen, ohne jemanden zu sehen. Die einzigen Dinge hier sind die seltsamen Gebäude am Straßenrand, umgeben von Gruppen blühender Blumen."
  },
  AvgDialog_22127_Content_41 = {
    Text = "Im grellen Tageslicht bin ich so lange gelaufen, ohne eine einzige Person zu sehen... Gehen die Menschen in der Cité nicht nach draußen?"
  },
  AvgDialog_22127_Content_42 = {Text = "Autsch!!"},
  AvgDialog_22127_Content_43 = {
    Text = "Warum hast du dich wieder in das Pergament versteckt...?"
  },
  AvgDialog_22127_Content_44 = {
    Text = "Ding, ding, ding ding..."
  },
  AvgDialog_22127_Content_45 = {
    Text = "Ein Einwohner summt eine unbekannte Melodie, während er an der Kreuzung vorbeigeht und nur seinen Rücken zeigt."
  },
  AvgDialog_22127_Content_46 = {
    Text = "Er trägt einen Anzug, der zu eng aussieht, und die Form seines Kopfes erscheint irgendwie seltsam."
  },
  AvgDialog_22127_Content_47 = {
    Text = "Ah... Gott sei Dank, endlich sehe ich jemanden."
  },
  AvgDialog_22127_Content_48 = {
    Text = "Du trittst schnell vor."
  },
  AvgDialog_22127_Content_49 = {
    Text = "Hallo, mein Herr."
  },
  AvgDialog_22127_Content_5 = {
    Text = "Geführt von der Adligen, gehen Sie voran, überwältigt von allem, was Ihnen ins Auge fällt."
  },
  AvgDialog_22127_Content_50 = {
    Text = "Ah, hallo, {Male=Sir,Female=Madam}! Darf ich fragen, wie ich Ihnen behilflich sein kann?"
  },
  AvgDialog_22127_Content_51 = {Text = "!!!"},
  AvgDialog_22127_Content_52 = {
    Text = "Er drehte sich um. Über dem Anzug war der riesige Kopf einer Biene."
  },
  AvgDialog_22127_Content_53 = {
    Text = "Was ist los, {Male=Sir,Female=Madam}? Habe ich etwas Unangemessenes gesagt, das Sie verunsichert hat?"
  },
  AvgDialog_22127_Content_54 = {
    Text = "Nein... *husten* Nein."
  },
  AvgDialog_22127_Content_55 = {
    Text = "Entschuldigen Sie, könnten Sie mir sagen, wie ich zur Medici Avenue komme?"
  },
  AvgDialog_22127_Content_56 = {
    Text = "Ah, {Male=Sir,Female=Madam}, Sie sind neu in der Cité, nicht wahr?"
  },
  AvgDialog_22127_Content_57 = {Text = "Ja."},
  AvgDialog_22127_Content_58 = {
    Text = "Kein Wunder, du kennst nicht einmal die berühmteste Straße..."
  },
  AvgDialog_22127_Content_59 = {
    Text = "Sei unbesorgt, die Bürger von Cité sind sehr gastfreundlich. Die Medici-Allee ist nur..."
  },
  AvgDialog_22127_Content_6 = {
    Text = "Du gehst die nebligen Straßen entlang, berührst die beschmierten Ziegel an den Gebäuden, pflückst Platanenblätter wie Farbenschreiber."
  },
  AvgDialog_22127_Content_60 = {Text = "Hmm—"},
  AvgDialog_22127_Content_61 = {
    Text = "Dieser Mr. Bee beendete seinen Satz nicht und begann plötzlich, sich am ganzen Körper zu krampfen."
  },
  AvgDialog_22127_Content_62 = {
    Text = "Ein Paar großer membranöser Flügel riss sein Jackett auf, schmolz und tropfte wie Butter unter der brüllenden Sonne."
  },
  AvgDialog_22127_Content_63 = {
    Text = "Liebling, Herr Biene! ..."
  },
  AvgDialog_22127_Content_64 = {Text = "Knack—"},
  AvgDialog_22127_Content_65 = {
    Text = "Der humanoide Körper der Biene fiel zu Boden, wurde schwarz und zerfiel dann zu Staub, der in die Luft zerstreut wurde."
  },
  AvgDialog_22127_Content_66 = {
    Text = "Das sind nicht die typischen Symptome der Auflösung..."
  },
  AvgDialog_22127_Content_67 = {
    Text = "Du untersuchst die Umgebung noch einmal sorgfältig."
  },
  AvgDialog_22127_Content_68 = {
    Text = "Umgeben von Gebäuden, die wie abstrakte Gemälde aussehen. Wenn man die gelegentlich entfernten Bewohner beobachtet, sieht man, dass ihre Körper various Pflanzen und Tiere ähneln."
  },
  AvgDialog_22127_Content_69 = {
    Text = "—Die Cité vor mir erscheint, als wäre sie direkt aus einem bizarren Traum entstanden."
  },
  AvgDialog_22127_Content_7 = {
    Text = "Diese Stadt scheint von einem eigentümlichen Filter umschleiert zu sein, mit allen Gebäuden und Pflanzen in einem extrem surrealen, aquarellartigen Erscheinungsbild."
  },
  AvgDialog_22127_Content_70 = {Text = "Ding—"},
  AvgDialog_22127_Content_71 = {
    Text = "Das Abzeichen auf deiner Brust glänzte silbern. Du hast die Kommunikation hergestellt."
  },
  AvgDialog_22127_Content_72 = {
    Text = "Professor Puppe, ich habe gerade auf ein atypisches Auflösungsmutant gestoßen..."
  },
  AvgDialog_22127_Content_73 = {
    Text = "Ruf aus der Cité. Ein Bürger wurde auf einer belebten Straße zu D-Dust."
  },
  AvgDialog_22127_Content_74 = {Text = "!!!"},
  AvgDialog_22127_Content_75 = {
    Text = "Genau dasselbe, was ich hier erlebt habe..."
  },
  AvgDialog_22127_Content_76 = {
    Text = "Aber ich bin in der Cité, und es ist nichts wie eine geschäftige Stadt."
  },
  AvgDialog_22127_Content_77 = {
    Text = "In der Tat, hier gibt es keine Schnittstelle zwischen der realen Welt und dem Bereich. Aber wenn es kein Bereich ist, warum würden dann dieser Ort und diese Menschen so sein... Das ergibt keinen Sinn."
  },
  AvgDialog_22127_Content_78 = {
    Text = "Es scheint, dass dieser Bereich anders ist als gewöhnliche, ein völlig unabhängiger Raum."
  },
  AvgDialog_22127_Content_79 = {
    Text = "Aber seine Auswirkungen auf Cité sind real und spürbar."
  },
  AvgDialog_22127_Content_8 = {
    Text = "{Male=Sir,Female=Madam} Schutzherr, sieh dir dieses Haus an, scheint es nicht, als würden einige Zeilen darauf schweben?"
  },
  AvgDialog_22127_Content_80 = {
    Text = "Egal was, wir müssen die Ursache finden, bevor die Dinge weiter eskalieren."
  },
  AvgDialog_22127_Content_81 = {
    Text = "Verstanden."
  },
  AvgDialog_22127_Content_82 = {
    Text = "Kommunikation beenden. Die Atmosphäre wird schwer."
  },
  AvgDialog_22127_Content_83 = {
    Text = "{Male=Sir,Female=Madam} Schutzherr... Herr Bee, ist er verstorben?"
  },
  AvgDialog_22127_Content_84 = {
    Text = "Du schaust auf Horla und klopfst ihr auf den Rücken."
  },
  AvgDialog_22127_Content_85 = {
    Text = "Das ist nicht das wahre Cité. Vielleicht ist es nur eine Art Illusion"
  },
  AvgDialog_22127_Content_86 = {
    Text = "Ich hoffe es..."
  },
  AvgDialog_22127_Content_87 = {
    Text = "Horla pflückt ein Platanenblatt und legt es auf den verbleibenden D-Staub."
  },
  AvgDialog_22127_Content_88 = {
    Text = "Lass uns zur Medici-Allee gehen und den Kontakt für die Untersuchung finden."
  },
  AvgDialog_22127_Content_89 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_22127_Content_9 = {
    Text = "Wie Poesie, die auf Gebäuden eingraviert ist... so schön!"
  },
  AvgDialog_22127_Content_90 = {
    Text = "Schau, {Male=Sir,Female=Madam} Schutzherr! Eine Straßenbahn!"
  },
  AvgDialog_22127_Content_91 = {
    Text = "Du bist eine Weile nach vorne gegangen, als eine dunkle Masse auf dich zukam."
  },
  AvgDialog_22127_Content_92 = {
    Text = "Es gibt Straßenbahnen, aber wir konnten das Halteschild nicht finden, also sind wir uns nicht sicher, ob sie dorthin fahren, wo wir hinwollen."
  },
  AvgDialog_22127_Content_93 = {
    Text = "Habe ich dir erzählt? Vom Zaun des alten Gartens konnte man die Straßenbahn vorbeifahren sehen, aber ich bin nie wirklich mit einer gefahren."
  },
  AvgDialog_22127_Content_94 = {
    Text = "Ich möchte wirklich einmal darauf sitzen. Ich glaube, es kann mich überall hinbringen."
  },
  AvgDialog_22127_Content_95 = {
    Text = "Jedes Mal, wenn ich die Straßenbahn sehe, fühlt es sich an wie ein Riese..."
  },
  AvgDialog_22127_Content_96 = {
    Text = "Hallo, darf ich Ihnen eine Mitfahrgelegenheit anbieten?"
  },
  AvgDialog_22127_Content_97 = {Text = "!!!"},
  AvgDialog_22127_Content_98 = {
    Text = "Auf den gewundenen Gleisen hielt vor dir eine riesige Raupe an."
  },
  AvgDialog_22127_Content_99 = {
    Text = "Ah! Genau wie ich es erwartet habe! Es ist der Raupenzug!"
  },
  AvgDialog_22128_Content_1 = {
    Text = "Verbleibender Duft"
  },
  AvgDialog_22128_Content_10 = {
    Text = "...Ich habe einige Angelegenheiten zu erledigen, bitte entschuldige mich..."
  },
  AvgDialog_22128_Content_11 = {
    Text = "Hey hey hey! Miss Nymphaea!"
  },
  AvgDialog_22128_Content_12 = {Text = "Hannah."},
  AvgDialog_22128_Content_13 = {
    Text = "Warte einen Moment, Hüter! Ich muss dringend Frau Nymphaea sehen! Das könnte sehr wohl Schlagzeilen machen!"
  },
  AvgDialog_22128_Content_14 = {
    Text = "Horla hat mich geschickt, um dich zu finden."
  },
  AvgDialog_22128_Content_15 = {Text = "Huh?!!!"},
  AvgDialog_22128_Content_16 = {
    Text = "Hannah hielt plötzlich an."
  },
  AvgDialog_22128_Content_17 = {
    Text = "Sie bat mich, dir dies zu geben."
  },
  AvgDialog_22128_Content_18 = {
    Text = "Der Wohnsitz der Rosen, von Horla Colette..."
  },
  AvgDialog_22128_Content_19 = {
    Text = "Ist das... Horlas Gedicht?! Und ein neuer Pseudonym, auch?!"
  },
  AvgDialog_22128_Content_2 = {
    Text = "Fräulein Nymphaea! Fräulein Nymphaea!"
  },
  AvgDialog_22128_Content_20 = {
    Text = "Sie bat mich, die Nachricht weiterzugeben, dass, wenn du denkst, es ist gut, bitte hilf ihr, es zu veröffentlichen auf..."
  },
  AvgDialog_22128_Content_21 = {
    Text = "Kein Problem, kein Problem! Es spielt keine Rolle, ob das Gedicht gut ist oder nicht, solange es etwas Aufregung erzeugt!"
  },
  AvgDialog_22128_Content_22 = {
    Text = "Außerdem, Hüter, ist Horla bereit, mein exklusives Interview zu akzeptieren?!"
  },
  AvgDialog_22128_Content_23 = {
    Text = "Gerade leise mich zu ihnen bringen..."
  },
  AvgDialog_22128_Content_24 = {
    Text = "Sei nicht zu gierig, sonst bekommst du vielleicht nicht einmal dein Gedicht veröffentlicht."
  },
  AvgDialog_22128_Content_25 = {Text = "Oh..."},
  AvgDialog_22128_Content_26 = {
    Text = "Das Gedicht wird an Hannah übergeben."
  },
  AvgDialog_22128_Content_27 = {
    Text = "Du hast mir einmal gesagt, dass die Gedichte kein Unglück bringen, aber ich konnte es nicht glauben."
  },
  AvgDialog_22128_Content_28 = {
    Text = "Nur nach diesem Ereignis habe ich wirklich verstanden."
  },
  AvgDialog_22128_Content_29 = {
    Text = "Danke Ihnen, Hüter{Male=Herr,Female=Frau}!"
  },
  AvgDialog_22128_Content_3 = {
    Text = "Ah, Fräulein Hannah, du bist wieder gekommen, um mich zu sehen..."
  },
  AvgDialog_22128_Content_30 = {
    Text = "Sie können diese Worte für das Interview mit Hannah aufbewahren..."
  },
  AvgDialog_22128_Content_31 = {
    Text = "Ah... nein, nein... Ich wage immer noch nicht, mit anderen zu sprechen... aber ich werde mich nach und nach anpassen!"
  },
  AvgDialog_22128_Content_32 = {
    Text = "Ich mach nur Spaß. Ich habe ihr schon in deinem Namen abgesagt."
  },
  AvgDialog_22128_Content_33 = {
    Text = "Horla ließ einen tiefen Seufzer hören. Du bist auf sie zugegangen."
  },
  AvgDialog_22128_Content_34 = {
    Text = "Du weißt, selbst wenn Hannah ihr Gedicht veröffentlicht, würde es nur wenige interessieren."
  },
  AvgDialog_22128_Content_35 = {
    Text = "Was den Menschen wichtig ist, sind tatsächlich nur die Geschichten und Themen rund um diese Gedichtsammlung."
  },
  AvgDialog_22128_Content_36 = {
    Text = "Hmm, ich weiß, {Male=Sir,Female=Madam} Schutzherr."
  },
  AvgDialog_22128_Content_37 = {
    Text = "Selbst in einer Stadt wie Cité gibt es sehr wenige echte Poesie-Leser..."
  },
  AvgDialog_22128_Content_38 = {
    Text = "Kümmert es dich nicht?"
  },
  AvgDialog_22128_Content_39 = {
    Text = "Für Colette ist dies der beste Weg, um Tribut zu zollen."
  },
  AvgDialog_22128_Content_4 = {
    Text = "Ich freue mich auch, dich zu sehen!"
  },
  AvgDialog_22128_Content_40 = {
    Text = "Was das Gedicht selbst betrifft..."
  },
  AvgDialog_22128_Content_41 = {
    Text = "Sie zupfte ein Blatt von der Rose über ihrem Auge und brachte es an ihre Nase."
  },
  AvgDialog_22128_Content_42 = {
    Text = "In Cité erfüllt selbst dort, wo Blumen nicht sichtbar sind, ihr Duft die Luft."
  },
  AvgDialog_22128_Content_43 = {
    Text = "Poesie, wie Blumen, muss nicht immer gesehen werden..."
  },
  AvgDialog_22128_Content_44 = {
    Text = "Sie drehte ihren Kopf und lächelte dich an."
  },
  AvgDialog_22128_Content_45 = {
    Text = "{Male=Sir,Female=Madam} Schutzherr, glaubst du das auch?"
  },
  AvgDialog_22128_Content_46 = {
    Text = "Wenige in der Cité lesen Poesie, aber ich glaube, die Rosen sind in ihren Herzen schon lange aufgeblüht."
  },
  AvgDialog_22128_Content_47 = {
    Text = "Sie hob ihre Hand. Karmesinrote Blütenblätter schwebten anmutig von ihrer Handfläche davon."
  },
  AvgDialog_22128_Content_48 = {
    Text = "Der Wind trägt den Duft von Rosen, als ob er seit Jahrzehnten von der Cité weht."
  },
  AvgDialog_22128_Content_5 = {
    Text = "Ähm, ich habe ein dringendes Anliegen, das ich mit dir besprechen muss..."
  },
  AvgDialog_22128_Content_6 = {
    Text = "Ich weiß nicht, wo Horla ist."
  },
  AvgDialog_22128_Content_7 = {
    Text = "Was?! Wie ist das möglich! Sie ist einen ganzen Tag zurück und hat sich immer noch nicht bei dir gemeldet?!"
  },
  AvgDialog_22128_Content_8 = {
    Text = "Könnten die Gerüchte darüber, dass ihr beiden euch nicht versteht, wahr sein?"
  },
  AvgDialog_22128_Content_9 = {
    Text = "Liegt es an der gegenseitigen Abneigung unter Literaturbegeisterten? Oder sind sie romantische Rivalen geworden?!"
  },
  AvgDialog_22129_Content_1 = {Text = "Psalm 1843"},
  AvgDialog_22129_Content_10 = {
    Text = "Horla... es ist in Ordnung. Sie sind nur Figuren aus dem Gedicht, also keine Sorge."
  },
  AvgDialog_22129_Content_11 = {
    Text = "Dieser Käfig muss ein Produkt der Auflösung sein. Gib mir etwas Zeit; ich finde bald einen Ausweg."
  },
  AvgDialog_22129_Content_12 = {
    Text = "Ah, ich habe fast vergessen. Du bist immer noch so schüchtern, Horla."
  },
  AvgDialog_22129_Content_13 = {
    Text = "Horla lugte langsam unter dem Pergament hervor."
  },
  AvgDialog_22129_Content_14 = {
    Text = "Colette, ich habe den Brief gelesen, den du an Herbert geschrieben hast..."
  },
  AvgDialog_22129_Content_15 = {
    Text = "Ich würde wirklich gerne hören, wie du planst, mich in diesem Moment zu überzeugen."
  },
  AvgDialog_22129_Content_16 = {
    Text = "Ich versuche nicht, dich zu überzeugen... Ich verstehe, warum du das tust."
  },
  AvgDialog_22129_Content_17 = {
    Text = "Heh... Was?"
  },
  AvgDialog_22129_Content_18 = {
    Text = "Für Ruhm und Macht, mich zu opfern, die Poesie zu opfern, Cité zu opfern... All dies kann ich verstehen."
  },
  AvgDialog_22129_Content_19 = {
    Text = "Ich liebe es, Gedichte zu schreiben, Colette. Ich versuche, den Stimmen aller Menschen und Dinge zuzuhören... Du bist meine beste Freundin – wie könnte ich dein Herz nicht hören?"
  },
  AvgDialog_22129_Content_2 = {
    Text = "Lady Colette! Die Bürger von Cité werden dir für immer treu bleiben!"
  },
  AvgDialog_22129_Content_20 = {
    Text = "Aber nachdem die Auflösung sich ausbreitet... wird dieser Garten aus jedermanns Gedächtnis gelöscht..."
  },
  AvgDialog_22129_Content_21 = {
    Text = "Alles, was hier passiert ist, die glücklichen und traurigen Tage, die wir zusammen verbracht haben... Kannst du wirklich einfach alles loslassen?"
  },
  AvgDialog_22129_Content_22 = {
    Text = "Colette hielt einen Moment inne, dann brach sie in Lachen aus. Ihr Lachen wurde lauter und lauter, fast so dass sie vergaß, ihre noble Haltung zu bewahren."
  },
  AvgDialog_22129_Content_23 = {
    Text = "Ich dachte... du wolltest mir etwas sagen..."
  },
  AvgDialog_22129_Content_24 = {
    Text = "Cité hat so viele Menschen, deren Leben mir egal sind. Denkst du, ich kümmere mich um einen Garten?"
  },
  AvgDialog_22129_Content_25 = {
    Text = "Sie atmete tief ein und richtete sich auf."
  },
  AvgDialog_22129_Content_26 = {
    Text = "Horla, du warst schon seit deiner Kindheit beliebt. Auch wenn ich diejenige bin, die hart gearbeitet hat, um uns zu unterstützen, haben die Leute immer dich gelobt..."
  },
  AvgDialog_22129_Content_27 = {
    Text = "Du besitzt bemerkenswertes Talent, aber was dann? Es gibt einige Wahrheiten, die du niemals verstehen wirst."
  },
  AvgDialog_22129_Content_28 = {
    Text = "Poesie, Emotion, Erinnerungen, Moral... all das sind Lasten. Nur Macht und Ruhm sind wirklich ewig."
  },
  AvgDialog_22129_Content_29 = {
    Text = "Gut gesagt! Lady Colette!"
  },
  AvgDialog_22129_Content_3 = {
    Text = "Bewege dich! Du versperrst meinen Weg!"
  },
  AvgDialog_22129_Content_30 = {
    Text = "Der Platz bricht in Applaus und Jubel aus, der euch in einer Welle von Geräuschen ertränkt."
  },
  AvgDialog_22129_Content_31 = {
    Text = "Hört, Horla. Höre die Stimmen der Cité-Leute."
  },
  AvgDialog_22129_Content_32 = {
    Text = "In dieser Welt hat Poesie keine Bedeutung. In einer anderen Welt ist es dasselbe."
  },
  AvgDialog_22129_Content_33 = {
    Text = "So denkst du also... Ich verstehe, Colette."
  },
  AvgDialog_22129_Content_34 = {
    Text = "Um ehrlich zu sein, ich bin wirklich froh, dass du hierher kommen konntest."
  },
  AvgDialog_22129_Content_35 = {
    Text = "In der entscheidendsten Phase meines Lebens bist du erneut mein Zeuge geworden."
  },
  AvgDialog_22129_Content_36 = {
    Text = "Sie hebt ihre Arme."
  },
  AvgDialog_22129_Content_37 = {
    Text = "In der Mitte kniete jeder vor ihr nieder."
  },
  AvgDialog_22129_Content_38 = {
    Text = "Keine Poesie, keine Predigt. Nur imaginierte fanatische Anbetung. Nur reine Macht."
  },
  AvgDialog_22129_Content_39 = {
    Text = "Die Erde beginnt zu beben. Du bemerkst, dass die Auflösung sich von der Mitte des Gedichts ausbreitet, sichtbar"
  },
  AvgDialog_22129_Content_4 = {
    Text = "Frau Colette! Frau Colette, schau mal hierher!!"
  },
  AvgDialog_22129_Content_40 = {
    Text = "Pass auf, Horla. Sieh zu, wie ich einen weiteren Sieg sichere—"
  },
  AvgDialog_22129_Content_41 = {Text = "Clang—"},
  AvgDialog_22129_Content_42 = {Text = "?!"},
  AvgDialog_22129_Content_43 = {
    Text = "Ein Blitz silbernes Licht. Der Käfig verschwand, und du und Horla fielen zu Boden."
  },
  AvgDialog_22129_Content_44 = {
    Text = "Es könnte ein Fehler gewesen sein, mich hierher als Zuschauer zu bringen, Frau Colette."
  },
  AvgDialog_22129_Content_45 = {
    Text = "Mythags Silberner Schlüssel... Sogar Mr. Herbert ist ziemlich neidisch."
  },
  AvgDialog_22129_Content_46 = {
    Text = "Aber ich bin neugierig—selbst an einem Ort wie diesem, was kannst du tun, selbst wenn du es schaffst, aus dem Käfig zu entkommen?"
  },
  AvgDialog_22129_Content_5 = {
    Text = "Der Rosenplatz ist voll. Alle Bürger von Cité haben sich hier versammelt. Von oben sieht es aus wie eine wühlende, massive schwarze Masse."
  },
  AvgDialog_22129_Content_6 = {
    Text = "Was für eine inspirierende Szene... nicht wahr?"
  },
  AvgDialog_22129_Content_7 = {
    Text = "Colette, in ihrem schönsten Kleid, steht auf der großen Bühne und winkt elegant hinunter."
  },
  AvgDialog_22129_Content_8 = {
    Text = "Hinter ihr fängt ein schwarzer Käfig aus unbekanntem Material dich und Horla ein, der hinter der Bühne hängt."
  },
  AvgDialog_22129_Content_9 = {
    Text = "Unter dem Blick der Menge kuschelte sich Horla zitternd unter das Pergament."
  },
  AvgDialog_22130_Content_10 = {
    Text = "Vielleicht ist der alte Mann, der gerade raucht, ein geheimes Mitglied des Ausschusses."
  },
  AvgDialog_22130_Content_100 = {
    Text = "J-Ja... Madame..."
  },
  AvgDialog_22130_Content_101 = {
    Text = "Horla, hast du die Unsichtbarkeitsfähigkeit deaktiviert?"
  },
  AvgDialog_22130_Content_102 = {
    Text = "Ich habe nicht... Madame, können Sie mich sehen?"
  },
  AvgDialog_22130_Content_103 = {
    Text = "In der neuen Cité sollten alle Dinge der Schönheit gesehen werden."
  },
  AvgDialog_22130_Content_104 = {
    Text = "Die neue Cité..."
  },
  AvgDialog_22130_Content_105 = {
    Text = "Ah, wir sind angekommen."
  },
  AvgDialog_22130_Content_106 = {
    Text = "Du hast dich umgedreht."
  },
  AvgDialog_22130_Content_107 = {
    Text = "Ein Gemälde, das du noch nie zuvor gesehen hast, entfaltet sich vor deinen Augen."
  },
  AvgDialog_22130_Content_108 = {
    Text = "Das Kreuzfahrtschiff kollidierte mit der Uferpufferzone und erzeugte ein dumpfes Geräusch."
  },
  AvgDialog_22130_Content_109 = {
    Text = "Du und Horla starrten verwirrt, als ob ihr vergessen hättet, wie man läuft."
  },
  AvgDialog_22130_Content_11 = {
    Text = "Ich habe immer das Gefühl, dass etwas sehr Geheimnisvolles an ihm ist... Wer weiß?"
  },
  AvgDialog_22130_Content_110 = {
    Text = "Mein Auto wird eine Weile nicht ankommen, also lass mich dir die Umgebung zeigen."
  },
  AvgDialog_22130_Content_111 = {
    Text = "Sie hebt ihre Hand, ihr Arm beschreibt einen eleganten Bogen."
  },
  AvgDialog_22130_Content_112 = {
    Text = "Willkommen in der Cité, entfernte Gäste."
  },
  AvgDialog_22130_Content_12 = {
    Text = "Das Sonnenlicht badete das Deck. Horla schloss die Augen, die Arme leicht geöffnet."
  },
  AvgDialog_22130_Content_13 = {
    Text = "Als sie deinen Blick bemerkte, zog sie schüchtern ihre Hände zurück und versteckte sie hinter ihrem Rücken."
  },
  AvgDialog_22130_Content_14 = {
    Text = "Überhaupt nicht schlecht, viel besser als ich erwartet hatte."
  },
  AvgDialog_22130_Content_15 = {
    Text = "Ich dachte, du würdest umkehren wollen, nachdem du so viele Leute auf dem Kreuzfahrtschiff gesehen hast."
  },
  AvgDialog_22130_Content_16 = {
    Text = "Ich habe damals darüber nachgedacht, aber ich hatte nicht den Mut, es dir zu sagen..."
  },
  AvgDialog_22130_Content_17 = {
    Text = "Ah! {Male=Sir,Female=Madam} Schutzherr, schau! Das ist der Szenyér-Fluss!"
  },
  AvgDialog_22130_Content_18 = {
    Text = "Die Grenzenlosigkeit des Meeres hielt nur kurze Zeit an. Bald erhob sich ein Leuchtturm langsam aus dem Horizont."
  },
  AvgDialog_22130_Content_19 = {
    Text = "Hinter ihm offenbarte sich eine breite Mündung und die verschwommenen Städte an beiden Ufern."
  },
  AvgDialog_22130_Content_2 = {Text = "Zuhause"},
  AvgDialog_22130_Content_20 = {
    Text = "Fräulein Nymphaea! Fräulein Nymphaea!"
  },
  AvgDialog_22130_Content_21 = {
    Text = "Hallo, darf ich fragen, wobei ich Ihnen behilflich sein kann?"
  },
  AvgDialog_22130_Content_22 = {
    Text = "Hast du Horla gesehen? Es ist dringend!"
  },
  AvgDialog_22130_Content_23 = {
    Text = "Hast du nicht eine Dichterlesung oder so etwas? Laut meinem Informanten scheint Horla häufig an deinen Veranstaltungen teilzunehmen."
  },
  AvgDialog_22130_Content_24 = {
    Text = "Du bist so nah bei ihr, du musst wissen, wo sie ist, oder?!"
  },
  AvgDialog_22130_Content_25 = {
    Text = "Entschuldigung, ich habe Horla vor zwei Monaten zuletzt gesehen... Sie mag keine überfüllten Orte."
  },
  AvgDialog_22130_Content_26 = {
    Text = "Hast du ihre Gedichte? Dein Poesieclub muss viele ihrer Werke gesammelt haben, oder?!"
  },
  AvgDialog_22130_Content_27 = {
    Text = "Wenn Sie es haben, wäre ich bereit, einen hohen Preis dafür zu zahlen."
  },
  AvgDialog_22130_Content_28 = {
    Text = "Hannah, hast du etwas, das du sie fragen möchtest?"
  },
  AvgDialog_22130_Content_29 = {
    Text = "Die Schülerzeitung hatte in letzter Zeit nicht viel Aufmerksamkeit. Horla hat es nie gemocht, interviewt zu werden, nicht einmal um ihre eigenen Gedichte zu veröffentlichen."
  },
  AvgDialog_22130_Content_3 = {
    Text = "In Ordnung, Horla, die Passagiere neben uns sind gegangen."
  },
  AvgDialog_22130_Content_30 = {
    Text = "Wenn wir ihre Gedichte veröffentlichen oder sogar ein exklusives Interview mit ihr führen können, werden die Verkaufszahlen des Schulmagazins in diesem Monat definitiv verdoppelt!"
  },
  AvgDialog_22130_Content_31 = {
    Text = "Ich habe bereits den Titel im Kopf: \"Garten und Frühling—Die unerzählten Geschichten des jungen Dichters Horla\"..."
  },
  AvgDialog_22130_Content_32 = {
    Text = "...Laut Statistik hat die aktuelle Anzahl der Sichtungen zweistellige Zahlen erreicht."
  },
  AvgDialog_22130_Content_33 = {
    Text = "Laut Augenzeugen scheinen die Veränderungen in der Cité nicht durch gewöhnliche Auflösung verursacht zu werden."
  },
  AvgDialog_22130_Content_34 = {
    Text = "Die aktuelle Cité ist sehr..."
  },
  AvgDialog_22130_Content_35 = {Text = "Sehr...?"},
  AvgDialog_22130_Content_36 = {
    Text = "In den Worten eines Augenzeugen: \"Es war schön.\""
  },
  AvgDialog_22130_Content_37 = {
    Text = "Auflösung... schön?"
  },
  AvgDialog_22130_Content_38 = {
    Text = "Der Mangel an Logik ist ein häufiges Merkmal von Augenzeugenberichten."
  },
  AvgDialog_22130_Content_39 = {
    Text = "Aus ihren chaotischen Worten lässt sich schlussfolgern, dass die Einzigartigkeit und Auswirkung dieses Ereignisses extrem selten sind, dennoch das ausgedrückte Risiko minimal ist, was einen krassen Kontrast schafft."
  },
  AvgDialog_22130_Content_4 = {
    Text = "Wirklich? Täuschst du mich nicht?"
  },
  AvgDialog_22130_Content_40 = {
    Text = "Wir sind auf ein ähnliches Ereignis nicht gestoßen. Ob es das Ergebnis der Auflösung ist, bleibt unklar."
  },
  AvgDialog_22130_Content_41 = {
    Text = "Was hat der Kontakt in Cité gesagt?"
  },
  AvgDialog_22130_Content_42 = {
    Text = "Der Kontakt berichtete, dass alles normal war, also ist das Niveau dieses Ereignisses nicht hoch. Aber wir müssen trotzdem jemanden nach Cité schicken, um nachzusehen..."
  },
  AvgDialog_22130_Content_43 = {Text = "Bang—"},
  AvgDialog_22130_Content_44 = {
    Text = "Bevor die Puppe zu Ende sprach, schlüpfte eine weiße Gestalt wie ein Geist ins Büro und versteckte sich hinter dem Vorhang."
  },
  AvgDialog_22130_Content_45 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_22130_Content_46 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_22130_Content_47 = {
    Text = "Horla, wenn du dich vor jemandem versteckst... hast du vergessen, die Tür zu schließen."
  },
  AvgDialog_22130_Content_48 = {
    Text = "Ah! Es tut mir so leid! Ich habe euch Umstände gemacht... {Male=Sir,Female=Madam} Schutzherr! Fräulein Doll!"
  },
  AvgDialog_22130_Content_49 = {
    Text = "Sie lief hinaus, schloss die Bürotür und versteckte sich schnell hinter den Vorhängen."
  },
  AvgDialog_22130_Content_5 = {
    Text = "...Wirklich."
  },
  AvgDialog_22130_Content_50 = {
    Text = "Horla! Wo bist du? Horla!"
  },
  AvgDialog_22130_Content_51 = {
    Text = "Komm heraus, lieber Horla! Wir brauchen nur ein kurzes Interview~ Ich verspreche, ich werde dir nichts antun!"
  },
  AvgDialog_22130_Content_52 = {
    Text = "Hannahs Stimme driftet von draußen durch die Tür."
  },
  AvgDialog_22130_Content_53 = {
    Text = "Endlich angefangen, Horla zu schikanieren? Es scheint, dass der Druck durch den Verkauf der Schülerzeitung tatsächlich ganz erheblich geworden ist."
  },
  AvgDialog_22130_Content_54 = {
    Text = "Es ist in Ordnung, wenn du das Interview nicht machen möchtest. Gib einfach ein paar der vielen Gedichte, die du geschrieben hast, an Hannah weiter, und sie wird dich in Ruhe lassen."
  },
  AvgDialog_22130_Content_55 = {
    Text = "Ich... möchte wirklich nicht..."
  },
  AvgDialog_22130_Content_56 = {
    Text = "Diese Gedichte bringen nur Unglück... Ich möchte nicht, dass das wieder passiert."
  },
  AvgDialog_22130_Content_57 = {
    Text = "Indem du an das denkst, was Horla erlebt hat, verstehst du ihre Bedeutung und nickst."
  },
  AvgDialog_22130_Content_58 = {
    Text = "Ich sollte draußen bleiben, nicht an einem überfüllten Ort wie der Schule..."
  },
  AvgDialog_22130_Content_59 = {
    Text = "{Male=Sir,Female=Madam} Schutzherr, darf ich dich um Hilfe bei einer Lösung bitten?"
  },
  AvgDialog_22130_Content_6 = {
    Text = "Horla lugte vorsichtig unter dem großen Pergament hervor und schaute sich um."
  },
  AvgDialog_22130_Content_60 = {
    Text = "Um ehrlich zu sein, habe ich keine guten Lösungen, um mit dem Geruchssinn und der Agilität dieses Frettchens umzugehen."
  },
  AvgDialog_22130_Content_61 = {
    Text = "—Wenn du jedoch bereit bist, nach draußen zu treten, gibt es eine Möglichkeit, wie ich dir helfen kann."
  },
  AvgDialog_22130_Content_62 = {
    Text = "Ah... Muss ich wirklich nach draußen gehen..."
  },
  AvgDialog_22130_Content_63 = {
    Text = "Wo hin gehen?"
  },
  AvgDialog_22130_Content_64 = {
    Text = "Du nimmst das Foto vom Tisch und wedelst es vor ihr."
  },
  AvgDialog_22130_Content_65 = {
    Text = "Cité, dein Zuhause."
  },
  AvgDialog_22130_Content_66 = {
    Text = "Das Kreuzfahrtschiff treibt lautlos, Häuser und Blumen an beiden Seiten verschwinden langsam im Hintergrund und verschwinden an der Biegung des Szenyér-Flusses."
  },
  AvgDialog_22130_Content_67 = {
    Text = "Horla schloss die Augen. Ein Lächeln blühte auf ihrem Gesicht."
  },
  AvgDialog_22130_Content_68 = {
    Text = "Es ist der Wind von Cité! Cité ist die Stadt der Blumen, und selbst der Wind trägt den Duft der Blumen."
  },
  AvgDialog_22130_Content_69 = {
    Text = "Selbst nach all diesen Jahren, in dem Moment, in dem ich es rieche, erinnere ich mich."
  },
  AvgDialog_22130_Content_7 = {
    Text = "Nachdem sie bestätigt hatte, dass keine Fremden in der Nähe waren, atmete sie tief durch und kroch unter das Pergament heraus."
  },
  AvgDialog_22130_Content_70 = {
    Text = "Wirst du diese Anblicke der Cité vermissen?"
  },
  AvgDialog_22130_Content_71 = {
    Text = "Ich vermisse dich! Aber ich habe immer im Gewächshaus gelebt. Ich habe die meisten dieser Orte in der Cité nicht wirklich gesehen."
  },
  AvgDialog_22130_Content_72 = {
    Text = "Ich habe viele Gedichte über die Landschaft von Cité geschrieben, aber das sind Fiktionen... Wenn sich diesmal die Chance bietet, würde ich gerne diese Orte sehen."
  },
  AvgDialog_22130_Content_73 = {
    Text = "Wohin möchtest du am liebsten gehen?"
  },
  AvgDialog_22130_Content_74 = {
    Text = "Der Ort, den ich am meisten besuchen möchte... hmm, es wäre der Garten, in dem ich früher lebte."
  },
  AvgDialog_22130_Content_75 = {
    Text = "In jeder Rosenzeit erblüht der Garten in voller Pracht mit Rosen, als würde man in einem Traum leben!"
  },
  AvgDialog_22130_Content_76 = {
    Text = "Ich bin mir nur nicht sicher, ob die Rosen und das Gedichtbuch nach diesem Feuer noch dort sind..."
  },
  AvgDialog_22130_Content_77 = {
    Text = "Als das Feuer ausbrach, konnte ich nicht entkommen, also begrub ich meine Gedichtsammlung im Garten. Diesmal bin ich zurückgekehrt, um sie zu finden."
  },
  AvgDialog_22130_Content_78 = {
    Text = "Nach all dem, was du in Cité erlebt hast, hätte ich nicht gedacht, dass dir dieser Ort gefallen würde oder dass du das Gedicht wiedersehen wolltest."
  },
  AvgDialog_22130_Content_79 = {
    Text = "Diese Dinge haben nichts mit diesem Land oder seinen Menschen zu tun... Die Cité ist ein schöner Ort."
  },
  AvgDialog_22130_Content_8 = {
    Text = "Du weißt, dass sie dich nicht sehen können, oder?"
  },
  AvgDialog_22130_Content_80 = {
    Text = "Was das Gedicht betrifft... das kann ich nicht sagen, {Male=Sir,Female=Madam} Schutzherr."
  },
  AvgDialog_22130_Content_81 = {
    Text = "Es verursacht viel Schmerz für die Menschen um mich herum, was mir missfällt, aber... es ist auch mein wertvollster Besitz."
  },
  AvgDialog_22130_Content_82 = {
    Text = "Ob es darum geht, es zu bewahren oder zu zerstören, ich möchte es trotzdem finden."
  },
  AvgDialog_22130_Content_83 = {
    Text = "Mach dir keine Sorgen, ich werde dich definitiv dorthin bringen. Ich bin mir nur nicht sicher, ob wir es nach all diesen Jahren noch finden können."
  },
  AvgDialog_22130_Content_84 = {
    Text = "Ein schwarzer Schmetterling flattert graziös und landet auf Horlas ausgestreckter Fingerspitze."
  },
  AvgDialog_22130_Content_85 = {
    Text = "Schau, {Male=Sir,Female=Madam} Schutzherr, ein Schmetterling!"
  },
  AvgDialog_22130_Content_86 = {
    Text = "Wenn ein Schmetterling auf jemandem landet, bedeutet dies, dass das Leben dieser Person für den Schmetterling wie eine Blume ist."
  },
  AvgDialog_22130_Content_87 = {
    Text = "Für die Cité-Leute bringt ein Leben wie eine Blume immer Glück~"
  },
  AvgDialog_22130_Content_88 = {
    Text = "Genau, Fräulein. Sie riechen nach Rosen."
  },
  AvgDialog_22130_Content_89 = {
    Text = "Cité hat viele schöne Rosengärten; du wirst dich hier wie zu Hause fühlen~"
  },
  AvgDialog_22130_Content_9 = {
    Text = "Nicht unbedingt. Unter den Reisenden könnten Awakeners, Forscher mit spezieller Ausrüstung oder begabte Personen sein..."
  },
  AvgDialog_22130_Content_90 = {Text = "!!!"},
  AvgDialog_22130_Content_91 = {
    Text = "Horla, sei vorsichtig!"
  },
  AvgDialog_22130_Content_92 = {
    Text = "Du hast noch nie einen Schmetterling in menschlicher Gestalt gesehen. Du hast Horla sanft zurückgezogen."
  },
  AvgDialog_22130_Content_93 = {
    Text = "Wow, ein sprechender Schmetterling?!"
  },
  AvgDialog_22130_Content_94 = {
    Text = "Frau Schmetterling, entschuldigung... Ich, ich bin nicht sehr gut im Gespräch mit anderen..."
  },
  AvgDialog_22130_Content_95 = {
    Text = "Keine Aggressivität, nicht wie eine Auflösungsvariante... noch ein Phantasma..."
  },
  AvgDialog_22130_Content_96 = {
    Text = "Ein rein schwarzer humanoider Schmetterling schlug mit seinen Flügeln und schwang sich, als er das Kreuzfahrtschiff verließ. Du schaust vorsichtig umher. Der Szenyér-Fluss floss immer noch ruhig."
  },
  AvgDialog_22130_Content_97 = {
    Text = "Menschen, die sich in Schmetterlinge verwandeln... ein schönes Bild, nicht wahr?"
  },
  AvgDialog_22130_Content_98 = {
    Text = "Eine wohlgekleidete Adelige erscheint neben dir, ohne dass du es bemerkst. Sie wendet ihr Gesicht zum Szenyér-Fluss und schenkt Horla ein leichtes Lächeln."
  },
  AvgDialog_22130_Content_99 = {
    Text = "Jedoch, mein Fräulein. Die Rose auf Ihrem Auge ist viel schöner als ein Schmetterling."
  },
  AvgDialog_22132_Content_1 = {
    Text = "Gartenklage"
  },
  AvgDialog_22132_Content_10 = {
    Text = "Armes Kind... du und Horla seid wie Schwestern..."
  },
  AvgDialog_22132_Content_100 = {
    Text = "Du nimmst das Gedicht heraus."
  },
  AvgDialog_22132_Content_101 = {
    Text = "Vermisst du es?"
  },
  AvgDialog_22132_Content_102 = {
    Text = "Sehr, sehr vermisst... Aber es ist in Ordnung, Hüter {Male=Herr,Female=Frau}"
  },
  AvgDialog_22132_Content_103 = {
    Text = "Sie wischte sich die Tränen weg und schüttelte mit einem Lächeln den Kopf."
  },
  AvgDialog_22132_Content_104 = {
    Text = "Für mich, für Colette und für ganz Cité bringt dieses Gedicht nur endloses Leid..."
  },
  AvgDialog_22132_Content_105 = {
    Text = "{Male=Sir,Female=Madam} Schutzherr, darf ich?"
  },
  AvgDialog_22132_Content_106 = {
    Text = "Überreiche das Gedicht an Horla"
  },
  AvgDialog_22132_Content_107 = {
    Text = "Ich werde es vermissen. Es sollte nur in meinen Erinnerungen existieren."
  },
  AvgDialog_22132_Content_108 = {
    Text = "Lebewohl..."
  },
  AvgDialog_22132_Content_109 = {
    Text = "Flammen entflammten in Horla's Hand. Bald verwandelte sich das Gedicht in einen Haufen Asche im Feuer."
  },
  AvgDialog_22132_Content_11 = {
    Text = "Horla ist gone. Du musst gut leben. Ihr Geist wird dich segnen..."
  },
  AvgDialog_22132_Content_110 = {
    Text = "Vor Jahren hätte es zusammen mit mir zu Asche werden sollen... So gäbe es jetzt keine Probleme."
  },
  AvgDialog_22132_Content_111 = {
    Text = "Schließlich ist das Problem gelöst."
  },
  AvgDialog_22132_Content_112 = {
    Text = "{Male=Sir,Female=Madam} Schutzherr, ich bemerke keine Veränderungen?"
  },
  AvgDialog_22132_Content_113 = {
    Text = "Mit einem so weitreichenden Einfluss kann es einige Zeit dauern, bis er sich verflüchtigt. Lass uns vorerst gehen..."
  },
  AvgDialog_22132_Content_114 = {
    Text = "Gefällt dir dieser Raum, Horla? Alles hier wurde genau so erhalten, wie es vor Jahrzehnten war."
  },
  AvgDialog_22132_Content_115 = {Text = "!!!"},
  AvgDialog_22132_Content_116 = {
    Text = "Das Gedicht ist bereits verbrannt... Dein Plan ist gescheitert, Colette."
  },
  AvgDialog_22132_Content_117 = {
    Text = "Die Gedichte? Oh, meinst du dies..."
  },
  AvgDialog_22132_Content_118 = {
    Text = "Sie winkte, und eine neue Sammlung von Gedichten erschien in ihrer Hand, identisch mit der, die verbrannt worden war."
  },
  AvgDialog_22132_Content_119 = {
    Text = "Schwarze Auflösungsflüssigkeit tropft aus dem Gedicht auf den Boden."
  },
  AvgDialog_22132_Content_12 = {
    Text = "Lass sie nicht traurig sein... Colette, lebe ein gutes Leben."
  },
  AvgDialog_22132_Content_120 = {Text = "!!!"},
  AvgDialog_22132_Content_121 = {Text = "Du..."},
  AvgDialog_22132_Content_122 = {
    Text = "Es ist eine Falle... Horla, bereite dich auf den Angriff vor!"
  },
  AvgDialog_22132_Content_123 = {Text = "Bang—"},
  AvgDialog_22132_Content_124 = {
    Text = "Ein Käfig erscheint plötzlich neben dir und fängt dich ein."
  },
  AvgDialog_22132_Content_125 = {
    Text = "Dies ist... es sollte solche Dinge im Gedicht nicht geben..."
  },
  AvgDialog_22132_Content_126 = {
    Text = "Solche Worte wurden in Horlas Gedichten tatsächlich nie geschrieben."
  },
  AvgDialog_22132_Content_127 = {
    Text = "Entschuldigung, aber dies ist meine Gedichtsammlung. Alles, was ich will, wird hier erscheinen."
  },
  AvgDialog_22132_Content_128 = {
    Text = "Lächelnd hob sie ihre Hand und steckte die Gedichtsammlung in ihr Herz."
  },
  AvgDialog_22132_Content_129 = {
    Text = "...In dieser Cité bin ich der einzige Meister."
  },
  AvgDialog_22132_Content_13 = {
    Text = "Zuerst kamen viele Leute, um sie zu trösten. Allmählich drifteten alle weg und ließen sie allein mit ihren Gedanken zurück."
  },
  AvgDialog_22132_Content_130 = {
    Text = "Ding—Ding—Ding—"
  },
  AvgDialog_22132_Content_131 = {
    Text = "Hört, Horla. Die Mitternachtsglocke hat geschlagen."
  },
  AvgDialog_22132_Content_132 = {
    Text = "Heute ist das größte Festival der Cité... Ich fühle mich geehrt, zwei distinguierte Gäste hier zu haben, um die Zeremonie zu bezeugen."
  },
  AvgDialog_22132_Content_133 = {
    Text = "Wachen, bringt sie zum Platz."
  },
  AvgDialog_22132_Content_134 = {
    Text = "Ich habe den besten Aussichtspunkt für zwei angesehene Gäste vorbereitet."
  },
  AvgDialog_22132_Content_14 = {
    Text = "Colette stand regungslos neben der Asche ihres mühsam gepflegten Gewächshauses und ließ die Glut ihr Gesicht verbrennen."
  },
  AvgDialog_22132_Content_15 = {
    Text = "Eine Träne rutschte ihr Gesicht hinunter und verdampfte schnell in der bleibenden Wärme der Flammen."
  },
  AvgDialog_22132_Content_16 = {
    Text = "Horla, sie hatten recht... Du wirst mich segnen. Du wirst mich nicht hassen."
  },
  AvgDialog_22132_Content_17 = {
    Text = "Du wirst mich nicht hassen, weil ich dir alles genommen habe — dein Talent, dein Leben... Trotzdem wirst du mich immer noch nicht hassen."
  },
  AvgDialog_22132_Content_18 = {
    Text = "Du bist so freundlich und edel. In deiner Gegenwart erscheinen alle anderen vulgär und kleinlich."
  },
  AvgDialog_22132_Content_19 = {
    Text = "Ich habe so hart versucht zu leben... Aber im Vergleich zu dir, warum bin ich immer der verachtenswerte?"
  },
  AvgDialog_22132_Content_2 = {
    Text = "Feuer! Schnell, lösch es!"
  },
  AvgDialog_22132_Content_20 = {
    Text = "So grausam, Horla. Du gibst mir keinen einzigen Grund, dich zu hassen. Du zwingst mich, meine verbleibenden Tage in Schmerz zu leben..."
  },
  AvgDialog_22132_Content_21 = {
    Text = "Ein Schluchzen. Colette wischt sich die Tränen weg. Asche schmiert über ihr Gesicht und verziert es chaotisch."
  },
  AvgDialog_22132_Content_22 = {
    Text = "Sie ahmte eine Adelige nach, erhob stolz den Kopf und lächelte auf den Garten, der jetzt nur noch aus Glut und Asche bestand."
  },
  AvgDialog_22132_Content_23 = {
    Text = "...Auf Wiedersehen, dann, Horla."
  },
  AvgDialog_22132_Content_24 = {Text = "Plopp—"},
  AvgDialog_22132_Content_25 = {
    Text = "Eine Träne fiel auf die Gedichtsammlung und erzeugte ein klares Geräusch im Raum."
  },
  AvgDialog_22132_Content_26 = {
    Text = "Es sind viele, viele Jahre vergangen, seit ich mich so gefühlt habe... Horla, du bist immer noch voller Überraschungen wie früher."
  },
  AvgDialog_22132_Content_27 = {
    Text = "Du fragst, warum hast du dein eigenes Bild nicht in das Gedicht eingefügt?"
  },
  AvgDialog_22132_Content_28 = {
    Text = "Es war wirklich schwierig, dich zu treffen... Was für ein Bedauern."
  },
  AvgDialog_22132_Content_29 = {
    Text = "Lady Colette, die Mitternachtsglocke wird bald läuten. Bitte treffen Sie Vorbereitungen."
  },
  AvgDialog_22132_Content_3 = {
    Text = "Es ist zu spät... Nichts bleibt im Garten..."
  },
  AvgDialog_22132_Content_30 = {
    Text = "Hmm, verstanden."
  },
  AvgDialog_22132_Content_31 = {
    Text = "Sie saß vor dem Spiegel, während die Zofe vorsichtig ihre Tränen mit einem Taschentuch abwischte."
  },
  AvgDialog_22132_Content_32 = {
    Text = "Heute ist ein großer Tag. Sogar das beste Publikum ist angekommen... Das Make-up darf heute nicht ruiniert werden."
  },
  AvgDialog_22132_Content_33 = {
    Text = "Sie betrachtete sich intensiv im Spiegel, während sie ihre Lippen zu einem Lächeln formte, das dem Adel und dem Sieg angemessen war."
  },
  AvgDialog_22132_Content_34 = {
    Text = "{Male=Sir,Female=Madam} Schutzherr, hier entlang!"
  },
  AvgDialog_22132_Content_35 = {
    Text = "Der Weg zum Uhrturm ist wahrhaft komplex... und es gibt viele Monster, die entlang des Weges Wache stehen."
  },
  AvgDialog_22132_Content_36 = {
    Text = "Im Gedicht \"Die Glocken der Stadt der Poesie\" ist der Weg zum Glockenturm ein Labyrinth. Es symbolisiert die Verwirrung in den Herzen der Stadtbewohner."
  },
  AvgDialog_22132_Content_37 = {
    Text = "Ein passendes Bild"
  },
  AvgDialog_22132_Content_38 = {
    Text = "Was für eine unzeitgemäße Rhetorik..."
  },
  AvgDialog_22132_Content_39 = {
    Text = "Die Suche der Monster vermeidend, erreichten Sie die oberste Etage."
  },
  AvgDialog_22132_Content_4 = {
    Text = "Wurden alle gerettet?"
  },
  AvgDialog_22132_Content_40 = {
    Text = "Der Kirchturm ist direkt dort! Geh einfach durch diesen Gang."
  },
  AvgDialog_22132_Content_41 = {
    Text = "Gibt es nur ein Monster, das diesen Ort bewacht?"
  },
  AvgDialog_22132_Content_42 = {
    Text = "Die anderen Monster müssen uns verfolgt haben... Dieses hier sollte verantwortlich für das Läuten der Glocke sein."
  },
  AvgDialog_22132_Content_43 = {
    Text = "Glaubst du, es gibt eine Möglichkeit, ihn zu täuschen?"
  },
  AvgDialog_22132_Content_44 = {
    Text = "Sicher, das sollte möglich sein... Wie das Gedicht sagt, wird der Gesandte der Skulptur einen Brief an den Glockenläuter überbringen, was das Eintreffen der Mitternacht signalisiert."
  },
  AvgDialog_22132_Content_45 = {
    Text = "Klasse... Horla, du fungierst als Botschafter und täuschst ihn dazu, die Glocke zu läuten. Ich werde es herausnehmen, bevor es reagiert."
  },
  AvgDialog_22132_Content_46 = {
    Text = "Huh? Ich... ich muss... Fremden... lügen...?"
  },
  AvgDialog_22132_Content_47 = {
    Text = "Uh... nie mind, ich gehe stattdessen... Du bleibst hier, und wenn sie irgendwelche plötzlichen Bewegungen machen, hilf mir, sie zu überwältigen."
  },
  AvgDialog_22132_Content_48 = {Text = "...Okay!"},
  AvgDialog_22132_Content_49 = {
    Text = "Du richtest deine Kleidung und trittst vor."
  },
  AvgDialog_22132_Content_5 = {
    Text = "Die meisten von ihnen wurden gerettet... Einer ist noch im Gewächshaus..."
  },
  AvgDialog_22132_Content_50 = {Text = "Wer?"},
  AvgDialog_22132_Content_51 = {
    Text = "Ich bin es, der Gesandte von Lady Colette."
  },
  AvgDialog_22132_Content_52 = {
    Text = "Ah... Also ist es der Gesandte..."
  },
  AvgDialog_22132_Content_53 = {
    Text = "Ich bin hier, um eine Nachricht zu überbringen. Mitternacht naht."
  },
  AvgDialog_22132_Content_54 = {
    Text = "Du übergibst Herbert den Brief, der von Colette geschrieben wurde. Er nimmt ihn respektvoll entgegen."
  },
  AvgDialog_22132_Content_55 = {
    Text = "Aber... Eure Exzellenz, der Gesandte, die aktuellen Himmelszeichen zeigen, dass es noch nicht Mitternacht ist..."
  },
  AvgDialog_22132_Content_56 = {
    Text = "Es gab einen Fehler bei der heutigen himmlischen Beobachtung."
  },
  AvgDialog_22132_Content_57 = {
    Text = "Wie wagst du es, Lady Colette's Entscheidung in Frage zu stellen?"
  },
  AvgDialog_22132_Content_58 = {
    Text = "Verstanden...! Ich werde es sofort erledigen!"
  },
  AvgDialog_22132_Content_59 = {
    Text = "Der Glockenläuter drückte den Knopf. Die komplizierten Räder begannen sich zu drehen, und der Hammer fiel und traf die massive Glocke."
  },
  AvgDialog_22132_Content_6 = {
    Text = "Wie mitleiderregend... Zwei Kinder, gerade als das Leben anfing, sich zu verbessern."
  },
  AvgDialog_22132_Content_60 = {
    Text = "Ding—Ding—Ding—"
  },
  AvgDialog_22132_Content_61 = {
    Text = "Der Hammer fiel immer wieder, während die zwölf Mitternachtsschläge durch die Cité hallten."
  },
  AvgDialog_22132_Content_62 = {
    Text = "Gesandter, die Mitternachtglocke hat geschlagen."
  },
  AvgDialog_22132_Content_63 = {
    Text = "Klasse... Als nächstes können wir an Lady Colette's Feier teilnehmen."
  },
  AvgDialog_22132_Content_64 = {
    Text = "Ah, große Lady Colette, es ist mein Glück, die Glocke für dein Fest zu läuten. Deine Handschrift zu sehen ist mein..."
  },
  AvgDialog_22132_Content_65 = {
    Text = "Hmm... \"Lieber Mr. Herbert — Colette\"..."
  },
  AvgDialog_22132_Content_66 = {
    Text = "Das ist kein Befehl, die Glocke zu läuten... Du..."
  },
  AvgDialog_22132_Content_67 = {
    Text = "Bevor er beenden konnte, schwebten mehrere Textzeilen in seinen Geist, und seine Augenlider wurden schwer."
  },
  AvgDialog_22132_Content_68 = {
    Text = "Nachdem es zweimal in der Luft geschwankt hatte, fiel der schwere Körper mit einem dumpfen Geräusch zu Boden."
  },
  AvgDialog_22132_Content_69 = {
    Text = "Horla schaut vorsichtig hinter der Mauer hervor und winkt dir zu."
  },
  AvgDialog_22132_Content_7 = {
    Text = "Colette, Colette... sei nicht zu traurig."
  },
  AvgDialog_22132_Content_70 = {
    Text = "Es scheint, dass er die Feier verpassen wird. Lass uns gehen."
  },
  AvgDialog_22132_Content_71 = {
    Text = "Ding—Ding—Ding—"
  },
  AvgDialog_22132_Content_72 = {
    Text = "Die zwölf Schläge ertönen klar und fern, die Mitternacht wird angekündigt."
  },
  AvgDialog_22132_Content_73 = {
    Text = "Menschen traten aus ihren Häusern und versammelten sich auf den Straßen von Cité, wie ein schwarzer Fluss, der langsam zum Platz vor dem Colette-Garten floß."
  },
  AvgDialog_22132_Content_74 = {
    Text = "Der Tag ist endlich gekommen! Ich werde Lady Colette treffen!"
  },
  AvgDialog_22132_Content_75 = {
    Text = "Ah, Madame Colette, die einzige Dichterin und der Glaube aller Cité..."
  },
  AvgDialog_22132_Content_76 = {
    Text = "Ich habe gehört, dass diese Zeremonie die großartigste aller Zeiten sein wird. Wenn ich nur unter der Bühne stehen und ihr die Hand schütteln könnte..."
  },
  AvgDialog_22132_Content_77 = {
    Text = "Träume weiter. So viele Menschen wollen Madam Colette treffen. Was lässt dich denken, du kannst dich vordrängen?"
  },
  AvgDialog_22132_Content_78 = {
    Text = "Gerade darüber nachzudenken... es ist nicht gegen das Gesetz, oder?"
  },
  AvgDialog_22132_Content_79 = {
    Text = "Vertraue mir, denk nicht zu viel nach. Entspann dich einfach und schau mit mir von außen zu."
  },
  AvgDialog_22132_Content_8 = {
    Text = "Das Feuer entzündete sich in einem Augenblick. Vielleicht war es durch die hohe Temperatur, einen Zigarettenstummel eines alten Mannes oder etwas anderes bedingt."
  },
  AvgDialog_22132_Content_80 = {
    Text = "Ein ferner Blick auf Lady Colette und das Hören ihrer Stimme genügen, um mich zufrieden zu stellen."
  },
  AvgDialog_22132_Content_81 = {
    Text = "Die Tür öffnet sich sanft. Du spähst vorsichtig hinein."
  },
  AvgDialog_22132_Content_82 = {
    Text = "Komm rein. Die Glocke läutete, und alle gingen auf den Platz."
  },
  AvgDialog_22132_Content_83 = {
    Text = "Horla, ist das der Ort?"
  },
  AvgDialog_22132_Content_84 = {
    Text = "Horla antwortete nicht sofort. Sie sah sich im Raum um, ihre Augen glänzten."
  },
  AvgDialog_22132_Content_85 = {Text = "Horla?"},
  AvgDialog_22132_Content_86 = {
    Text = "Es sieht genau so aus wie damals, als wir Kinder waren..."
  },
  AvgDialog_22132_Content_87 = {
    Text = "Auch mit so viel, selbst mit allem in der Cité... dieser Ort war immer der, an dem Colettes Träume lagen."
  },
  AvgDialog_22132_Content_88 = {
    Text = "Horlas Emotionen breiteten sich erneut aus, und du fühltest, wie dein Herz berührt wurde."
  },
  AvgDialog_22132_Content_89 = {Text = "Horla..."},
  AvgDialog_22132_Content_9 = {
    Text = "Flammen stiegen im Garten auf, der mit trockenem Gras gefüllt war, und verschlangen das Gewächshaus. Bevor die Menschen reagieren konnten, war es bereits wieder erloschen."
  },
  AvgDialog_22132_Content_90 = {
    Text = "Ah! Entschuldigung, Geheimnisträger{Male=Herr,Female=Frau}... ich kann meine Gefühle nicht kontrollieren"
  },
  AvgDialog_22132_Content_91 = {
    Text = "Keine Sorgen, das ist völlig normal."
  },
  AvgDialog_22132_Content_92 = {
    Text = "Niemand sollte seine Vergangenheit aufgeben."
  },
  AvgDialog_22132_Content_93 = {
    Text = "Danke Ihnen... Hüter{Male=Herr,Female=Frau}"
  },
  AvgDialog_22132_Content_94 = {
    Text = "Wir haben schon darüber gesprochen. Colette sagte, dass sie, sobald wir dieses Haus kaufen, all ihre kostbaren Gegenstände in einem speziellen Vitrinenschrank für alle Gäste zur Schau stellen würde."
  },
  AvgDialog_22132_Content_95 = {
    Text = "Schmuck, Handtasche, wertvolle Kleidung... und eine Gedichtsammlung, die mit ihrem Namen signiert ist."
  },
  AvgDialog_22132_Content_96 = {
    Text = "Geführt von Horla, erreichen Sie einen kunstvoll gestalteten Glasschaukasten."
  },
  AvgDialog_22132_Content_97 = {
    Text = "Auf dem zentralen Regal der Vitrine liegt das dicke, üppige Gedichtbuch still, wie ein Monarch, der in einem Palast schläft."
  },
  AvgDialog_22132_Content_98 = {
    Text = "\"Die 'Wohnstätte der Rosen',\" verfasst von Colette..."
  },
  AvgDialog_22132_Content_99 = {
    Text = "Damals war diese Gedichtsammlung nur einige Blätter, die zusammengeheftet waren... Jetzt sieht sie ganz anders aus."
  },
  AvgDialog_22133_Content_1 = {
    Text = "Statuarische Rhetorik"
  },
  AvgDialog_22133_Content_10 = {
    Text = "Helft Ms. Colette! Fangt den Eindringling! Schnell, sucht!"
  },
  AvgDialog_22133_Content_11 = {
    Text = "Eine Gruppe von Monstern in unterschiedlichen Formen stürmt in das Gebäude und läuft nicht weit an dir vorbei."
  },
  AvgDialog_22133_Content_12 = {
    Text = "Monster aus der Welt der Poesie haben die reale Welt infiltriert..."
  },
  AvgDialog_22133_Content_13 = {
    Text = "Ihr Ritual steht kurz vor dem Beginn. Wir müssen uns beeilen."
  },
  AvgDialog_22133_Content_14 = {
    Text = "Als du hinausspähst, siehst du, dass das Monster vorübergehend gegangen ist. Du hast Horla geschnappt und bist schnell nach oben gerannt."
  },
  AvgDialog_22133_Content_15 = {
    Text = "Horla, lass uns die Treppe hinaufgehen und finden... huh?"
  },
  AvgDialog_22133_Content_16 = {
    Text = "Du steigst die Treppe hinauf, nur um festzustellen, dass sie nicht zur oberen Etage führt und abrupt mitten aufhört."
  },
  AvgDialog_22133_Content_17 = {
    Text = "Das... Was ist los..."
  },
  AvgDialog_22133_Content_18 = {
    Text = "Ich schrieb einmal ein Gedicht über eine Treppe, die in der Mitte abbricht, ähnlich wie unsere Leben, die von unerwarteten Wendungen und Schwierigkeiten geprägt sind."
  },
  AvgDialog_22133_Content_19 = {
    Text = "Aber dies ist eindeutig nicht die Welt meines Gedichts, wie könnte es sein..."
  },
  AvgDialog_22133_Content_2 = {
    Text = "{Male=Sir,Female=Madam} Schutzherr, ist die poetische Welt... verschwunden?"
  },
  AvgDialog_22133_Content_20 = {
    Text = "Ah! Ich verstehe!"
  },
  AvgDialog_22133_Content_21 = {
    Text = "Horla hob plötzlich den Kopf, zu aufgeregt, um sich zurückzuhalten."
  },
  AvgDialog_22133_Content_22 = {
    Text = "Es ist Colette! Dieser Ort ist wichtig für uns... Sie hat ihn speziell bewahrt und ihn gemäß der Beschreibung im Gedicht umgestaltet!"
  },
  AvgDialog_22133_Content_23 = {
    Text = "Ich wusste es, Hüter! Colette ist nicht so ein Mensch!"
  },
  AvgDialog_22133_Content_24 = {
    Text = "Dies ist das erste Mal, dass du Horla so erfreut siehst. Du atmest tief aus."
  },
  AvgDialog_22133_Content_25 = {
    Text = "Nicht gewillt, ihre Illusion zu zerstören, hast du sie sanft auf die Schulter getätschelt."
  },
  AvgDialog_22133_Content_26 = {
    Text = "Vielleicht... Du kennst diesen Ort. Wie wäre es, wenn du die Führung übernimmst?"
  },
  AvgDialog_22133_Content_27 = {Text = "...Okay!"},
  AvgDialog_22133_Content_28 = {
    Text = "Geführt von Horla, entkommen Sie der Suche der Monster und setzen Ihren Weg fort."
  },
  AvgDialog_22133_Content_29 = {
    Text = "{Male=Sir,Female=Madam} Schutzherr, da vorne ist..."
  },
  AvgDialog_22133_Content_3 = {
    Text = "Du siehst hinaus zur Tür."
  },
  AvgDialog_22133_Content_30 = {Text = "Pst!"},
  AvgDialog_22133_Content_31 = {
    Text = "Du hast Horla schnell den Mund zugehalten und sie in die Ecke der Wand gezogen."
  },
  AvgDialog_22133_Content_32 = {
    Text = "Was sollen wir hier tun?"
  },
  AvgDialog_22133_Content_33 = {
    Text = "Tor! Lady Colette hat uns befohlen, diesen Ort zu bewachen, weil... weil..."
  },
  AvgDialog_22133_Content_34 = {
    Text = "...Kurz gesagt, Lady Colette hat uns befohlen, hier Wache zu stehen!"
  },
  AvgDialog_22133_Content_35 = {
    Text = "Wir haben so lange gewacht und nichts gesehen. Werden wir die Zeremonie später verpassen?"
  },
  AvgDialog_22133_Content_36 = {
    Text = "Nein, die Glocke hat noch nicht geläutet. Wir können nirgendwo hingehen, bis sie läutet!"
  },
  AvgDialog_22133_Content_37 = {
    Text = "Ich freue mich wirklich darauf, Madame Colettes lebendige Schöpfung zu erleben..."
  },
  AvgDialog_22133_Content_38 = {
    Text = "Frau Colettes Live-Auftritt findet nur einmal im Jahr statt. Macht euch bereit, Soldaten. Wir werden um die Plätze in der gesamten Cité konkurrieren!"
  },
  AvgDialog_22133_Content_39 = {
    Text = "Warum gehen wir jetzt nicht einfach hin?"
  },
  AvgDialog_22133_Content_4 = {
    Text = "Horla schaut zurück nach draußen."
  },
  AvgDialog_22133_Content_40 = {
    Text = "...weil wir hier bleiben müssen."
  },
  AvgDialog_22133_Content_41 = {
    Text = "Also... was genau machen wir hier?"
  },
  AvgDialog_22133_Content_42 = {
    Text = "Tor! Madam Colette hat uns befohlen, diesen Ort zu bewachen!"
  },
  AvgDialog_22133_Content_43 = {
    Text = "Diese beiden scheinen nicht sehr schlau zu sein..."
  },
  AvgDialog_22133_Content_44 = {
    Text = "Es gibt keinen anderen Weg, Horla. Mach dich bereit, sie herauszuleiten."
  },
  AvgDialog_22133_Content_45 = {
    Text = "Horla nickt dir zu. Du hältst den silbernen Schlüssel, und Horla holt Papier und einen Stift heraus."
  },
  AvgDialog_22133_Content_46 = {Text = "Ah!!—"},
  AvgDialog_22133_Content_47 = {
    Text = "Begleitet von silbernem Licht erschien eleganter Text in der Luft und prägte sich in die Monster ein. Zwei Monster fielen in einen tiefen Schlaf."
  },
  AvgDialog_22133_Content_48 = {
    Text = "Nach dem Besiegen der Monster hast du dich in den Raum hinter ihnen versteckt."
  },
  AvgDialog_22133_Content_49 = {
    Text = "Sieht aus wie ein Abstellraum... Es sollte hier vorerst sicher sein."
  },
  AvgDialog_22133_Content_5 = {
    Text = "Der Garten draußen behält das Aussehen der Welt, die in Gedichten beschrieben wird, aber die Innenwelt ist identisch zur realen Welt, ohne Spur des Bereichs."
  },
  AvgDialog_22133_Content_50 = {
    Text = "Wir können hier rasten und dann Colette finden... Horla? Du siehst nicht gut aus."
  },
  AvgDialog_22133_Content_51 = {
    Text = "Ah... Ist das so?"
  },
  AvgDialog_22133_Content_52 = {
    Text = "Hast du gerade die Stirn gerunzelt und an etwas gedacht?"
  },
  AvgDialog_22133_Content_53 = {
    Text = "Oh... {Male=Sir,Female=Madam} Schutzherr, ich habe über das Gespräch der beiden Monster vorhin nachgedacht..."
  },
  AvgDialog_22133_Content_54 = {
    Text = "Als ich vorhin lauschte, fühlte es sich so vertraut an... Ich habe gerade endlich erinnert."
  },
  AvgDialog_22133_Content_55 = {
    Text = "In dieser Gedichtsammlung habe ich ein Gedicht über die Statue in der Stadt der Gedichte geschrieben."
  },
  AvgDialog_22133_Content_56 = {
    Text = "Die Poesiestadt ist ein Stadtstaat, der von Poesie lebt. Sie hat keinen König; ihr Glauben liegt in einer Statue."
  },
  AvgDialog_22133_Content_57 = {
    Text = "Jedes Jahr am Festtag, wenn die Uhrturmuhr schlägt, wird die Statue lebendig und schreibt ein Gedicht für die Menschen der Stadt."
  },
  AvgDialog_22133_Content_58 = {
    Text = "Ihre Poesie ist so schön, dass sie die ganze Stadt ein ganzes Jahr lang unterstützen kann."
  },
  AvgDialog_22133_Content_59 = {
    Text = "Jedes Jahr am Festtag versammeln sich die Menschen auf dem Platz, wo die Statue steht, um die von ihr live kreierten Gedichte zu hören..."
  },
  AvgDialog_22133_Content_6 = {
    Text = "Das sollte die echte Cité sein. Es scheint, wir sind durch einen Link-Punkt zwischen der Realität und dem Bereich hindurchgegangen."
  },
  AvgDialog_22133_Content_60 = {
    Text = "Ich verstehe. Colette hat das Bild der Statue in ihr eigenes verwandelt..."
  },
  AvgDialog_22133_Content_61 = {
    Text = "Wo ist der Uhrturm?"
  },
  AvgDialog_22133_Content_62 = {
    Text = "Als ich Gedichte schrieb, hatte ich keine Ahnung, wie die Außenwelt aussah... Daher wurde dieser Uhrturm nach dem einen neben diesem Gebäude modelliert."
  },
  AvgDialog_22133_Content_63 = {
    Text = "Die beiden Gebäude sind verbunden, und man kann über eine überdachte Brücke hinübergehen."
  },
  AvgDialog_22133_Content_64 = {
    Text = "...Horla, kannst du erraten, wo Colette das Gedicht versteckt hat?"
  },
  AvgDialog_22133_Content_65 = {
    Text = "Es sollte... in Ordnung sein... richtig...?"
  },
  AvgDialog_22133_Content_66 = {
    Text = "Es gibt ein äußerst luxuriöses Zimmer in diesem Gebäude, das der Gräfin gehört. Sie bleibt hier einmal oder zweimal im Jahr zu besonderen Anlässen, während die Zofe es regelmäßig in ihrer Abwesenheit reinigt."
  },
  AvgDialog_22133_Content_67 = {
    Text = "Colette liebte diesen Raum und schlich mich sogar hin, um ihn zu sehen. Sie sagte, dass sie, sobald sie etwas Geld verdient hatte, definitiv in diesem Raum wohnen würde."
  },
  AvgDialog_22133_Content_68 = {
    Text = "Ich denke, sie und die Gedichtsammlung werden beide dort sein."
  },
  AvgDialog_22133_Content_69 = {
    Text = "Ich verstehe... Ich habe eine Lösung!"
  },
  AvgDialog_22133_Content_7 = {
    Text = "Wo auch immer es ist, wir müssen Colette finden und das Gedicht zurückholen..."
  },
  AvgDialog_22133_Content_70 = {
    Text = "Gehst du zu Colettes Zimmer, um das Gedicht zu holen? Aber hier sind viele Monster..."
  },
  AvgDialog_22133_Content_71 = {
    Text = "Ja, hier gibt es viele Monster; wir werden sie wahrscheinlich nicht bewältigen können."
  },
  AvgDialog_22133_Content_72 = {
    Text = "Also, wir werden sie zuerst ablenken und dann in ihr Zimmer gehen, um das Gedicht zu holen."
  },
  AvgDialog_22133_Content_73 = {
    Text = "Aber sie sind jetzt so aufmerksam... womit können wir sie ablenken?"
  },
  AvgDialog_22133_Content_74 = {
    Text = "Verwenden Sie den Uhrturm."
  },
  AvgDialog_22133_Content_75 = {
    Text = "Uhrturm? ... Ah! Ich verstehe!"
  },
  AvgDialog_22133_Content_76 = {
    Text = "Lass uns die Glocke am Uhrturm früh läuten. So werden die Monster auf dem Platz versammelt, und niemand wird uns aufhalten!"
  },
  AvgDialog_22133_Content_77 = {
    Text = "Genau. Colette muss sich auf ihre Aufführung vorbereiten. Sie wird nicht so ein dickes Gedichtband mitnehmen; es wird wahrscheinlich irgendwo sicher in ihrem Zimmer aufbewahrt."
  },
  AvgDialog_22133_Content_78 = {
    Text = "Nutzen Sie diese Zeitspanne, um in ihr Zimmer zu gehen und diese Gedichtsammlung zu zerstören!"
  },
  AvgDialog_22133_Content_8 = {
    Text = "Klopf klopf klopf—"
  },
  AvgDialog_22133_Content_9 = {
    Text = "Der Boden bebt heftig. Du ziehst Horla schnell und versteckst dich hinter einer Tür."
  },
  AvgDialog_22145_Content_1 = {
    Text = "Bitte... ich bin es nicht wert..."
  },
  AvgDialog_22145_Content_2 = {
    Text = "Aigis, ich kann dir helfen! Wir können den Geist stabilisieren!"
  },
  AvgDialog_22145_Content_3 = {
    Text = "Um deinen Punkt zu beweisen, hast du den Silberschlüssel aus deiner Robe gezogen – er schimmerte mit einem warmen Licht, wie Morgentau, wie Sonnenschein"
  },
  AvgDialog_22145_Content_4 = {
    Text = "Schlüssel... Mr. Anderson hat es erwähnt..."
  },
  AvgDialog_22145_Content_5 = {
    Text = "<LightGray:Aber... es ist zu spät... wirklich zu spät...>"
  },
  AvgDialog_22145_Content_6 = {
    Text = "Sie rannte auf den Glockenturm zu! Verfolge sie!"
  },
  AvgDialog_22297_Content_1 = {Text = "Augen auf"},
  AvgDialog_22297_Content_10 = {
    Text = "Sitzungsleiter?"
  },
  AvgDialog_22297_Content_100 = {
    Text = "Am Heck stieg dichter Rauch auf, genau dort, wo sich das Kraftwerk befindet"
  },
  AvgDialog_22297_Content_101 = {Text = "Oh nein!"},
  AvgDialog_22297_Content_102 = {
    Text = "Du stützt dich an der Reling ab und gehst in Richtung des aufsteigenden Rauchs"
  },
  AvgDialog_22297_Content_103 = {
    Text = "Der Geschmack von Blut und Rauch erfüllt deine Kehle, jeder Atemzug beim Gehen ist wie ein Nadelstich"
  },
  AvgDialog_22297_Content_104 = {
    Text = "Ramona, Murphy, Celeste... wir müssen uns schnell mit ihnen treffen"
  },
  AvgDialog_22297_Content_105 = {
    Text = "Bevor du zwei Schritte machen konntest, spürtest du ein heftiges Beben, das fast den Schiffsrumpf zerriss"
  },
  AvgDialog_22297_Content_106 = {
    Text = "Mit einem gewaltigen Explosionsknall stieg das Feuer in den Himmel und die heiße Luft schleuderte dich zu Boden"
  },
  AvgDialog_22297_Content_107 = {
    Text = "——Bevor das Bewusstsein abbrach, war das letzte, was ins Auge fiel, ein Seevogel, der den Vollmondhimmel durchquerte"
  },
  AvgDialog_22297_Content_11 = {
    Text = "Wie hast du geschlafen?"
  },
  AvgDialog_22297_Content_12 = {Text = "Doll?!"},
  AvgDialog_22297_Content_13 = {
    Text = "Hab keine Angst, jetzt ist nicht die Zeit, dich für das Betreten des Rasens am Arbeitstag Nachmittag zur Rechenschaft zu ziehen"
  },
  AvgDialog_22297_Content_14 = {
    Text = "<Gray:Das bedeutet, dass es früher oder später Konsequenzen geben wird...>"
  },
  AvgDialog_22297_Content_15 = {
    Text = "Ramona wich deinem Blick aus, auf ihrem Hinterkopf stand förmlich „Hilflos“"
  },
  AvgDialog_22297_Content_16 = {
    Text = "Francis' Tagebuch erwähnte einige Informationen über <Yellow:\"Tempellicht Kirche\"> – nebenbei, du hast diese drei Pflichtlektionen noch nicht überprüft."
  },
  AvgDialog_22297_Content_17 = {
    Text = "Die Tempellicht-Kirche, die glaubt, „Auflösung ist ein göttlicher Segen und die einzige Rettung der Menschheit“, trickst die Leidenden, damit sie beitreten und sich der Auflösung unterziehen."
  },
  AvgDialog_22297_Content_18 = {
    Text = "Danke für deine Wiederholung, Professor Dexter.\nAber ich glaube nicht, dass Erica es mag, wenn du dich in ihre Arbeit einmischst"
  },
  AvgDialog_22297_Content_19 = {
    Text = "Meine Schuld, meine Schuld, die restliche Zeit gehört euch"
  },
  AvgDialog_22297_Content_2 = {
    Text = "Warum schläfst du hier?"
  },
  AvgDialog_22297_Content_20 = {
    Text = "Francis hinterließ viele Hinweise, die auf die Kirche des Tempellichts deuten, unter denen \"Auferstehung der Toten\" besonders bemerkenswert ist."
  },
  AvgDialog_22297_Content_21 = {
    Text = "Mit Lilys Erscheinen haben wir Grund zu der Annahme, dass die Tempellichtkirche die Methode beherrscht, Erwachter zu beschwören."
  },
  AvgDialog_22297_Content_22 = {
    Text = "Die Existenz des Erwachten sollte doch streng geheim sein, oder?"
  },
  AvgDialog_22297_Content_23 = {
    Text = "Es scheint, dass du im Geschichtsunterricht über die Erwachten nicht aufgepasst hast.\nIch frage mich, wie du den ersten Test bestanden hast"
  },
  AvgDialog_22297_Content_24 = {
    Text = "Missaga ist nicht die einzige, die die Technologie des Silberkerns beherrscht"
  },
  AvgDialog_22297_Content_25 = {
    Text = "Der Ursprung des Erwachens kann bis vor der Pluvialperiode zurückverfolgt werden. Wandmalereien in den Gräbern der 19. Dynastie des antiken Remouahe scheinen die Beschwörung des Erwachenden darzustellen."
  },
  AvgDialog_22297_Content_26 = {
    Text = "Das Golem, das der Missaga-Erweckungstechnologie am nächsten kommt, stammt aus den Hexenclans der Levante"
  },
  AvgDialog_22297_Content_27 = {
    Text = "Wir schweifen ab"
  },
  AvgDialog_22297_Content_28 = {
    Text = "Aus den Beschreibungen von Glauben und Ritualen im Tagebuch stieß Francis auf eine <Yellow:Tempel Licht Kirche>, die von den Informationen abweicht, die wir haben."
  },
  AvgDialog_22297_Content_29 = {
    Text = "Euer nächster Außeneinsatz besteht darin, die Tagebucheinträge zu überprüfen"
  },
  AvgDialog_22297_Content_3 = {
    Text = "Wach auf, du wirst hier kalt"
  },
  AvgDialog_22297_Content_30 = {
    Text = "Francis hat in ihrem Tagebuch ihre Bewegungen vor der Abreise in die Arktis festgehalten.\nWir werden zu dem Ort gehen, an dem sie an Bord ging – die Stadt Brillport, vielleicht gibt es dort Hinweise"
  },
  AvgDialog_22297_Content_31 = {
    Text = "Bereit, dann lass uns loslegen, ich werde wie immer dein Partner sein"
  },
  AvgDialog_22297_Content_32 = {
    Text = "Das Reisegepäck war immer bereit"
  },
  AvgDialog_22297_Content_33 = {
    Text = "Musst du nicht noch ein bisschen schlafen?"
  },
  AvgDialog_22297_Content_34 = {
    Text = "Nicht nötig!\nIch habe die Missionsanforderungen vollständig verstanden und erinnere mich an alle Details von gestern Abend!"
  },
  AvgDialog_22297_Content_35 = {
    Text = "Dann los.\nWenn wir heute aufbrechen, schaffen wir es vielleicht noch zur Premiere des neuen Stücks im Lentinen-Opernhaus"
  },
  AvgDialog_22297_Content_36 = {
    Text = "Ich gehe den Fahrer suchen, wir treffen uns am Schultor"
  },
  AvgDialog_22297_Content_37 = {
    Text = "Ramonas Rücken verschwand schnell aus dem Blickfeld, und du machst dich bereit, in dein Zimmer zu gehen und dein Gepäck zu holen"
  },
  AvgDialog_22297_Content_38 = {Text = "Keeper."},
  AvgDialog_22297_Content_39 = {
    Text = "Dieses Mal könnten wir direkten Kontakt zur Tempel-Licht-Kirche haben."
  },
  AvgDialog_22297_Content_4 = {
    Text = "Hm...Ramona?"
  },
  AvgDialog_22297_Content_40 = {
    Text = "Ihre Geheimnisse zu enthüllen ist zweitrangig, deine Hauptaufgabe ist es, am Leben zu bleiben.\nIch wüsste nicht, wo ich einen weiteren Hüter aus den Ruinen ausgraben könnte"
  },
  AvgDialog_22297_Content_41 = {
    Text = "Sei nicht so streng zu den Jungen"
  },
  AvgDialog_22297_Content_42 = {
    Text = "Sollte sich der czort nicht recht haben.\nDie Gläubigen, die ihr zuvor getroffen habt, sind nur Außenmitglieder; der wahre Kern der Kirche ist noch nicht aufgetaucht"
  },
  AvgDialog_22297_Content_43 = {
    Text = "Klingt es so, als ob der Professor mit der Tempel Licht Kirche vertraut ist?"
  },
  AvgDialog_22297_Content_44 = {
    Text = "Ha, ha... Nur eine unglückliche Beziehung"
  },
  AvgDialog_22297_Content_45 = {
    Text = "Wenn notwendig, wird Mythag erfahrenere Ermittler entsenden und sogar den Mystia-Vertragsausschuss um Hilfe bitten, um diese Angelegenheit zu lösen"
  },
  AvgDialog_22297_Content_46 = {
    Text = "Komm lebend zurück"
  },
  AvgDialog_22297_Content_47 = {
    Text = "Ich verstehe, wir werden sicher zurückkommen"
  },
  AvgDialog_22297_Content_48 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_22297_Content_49 = {
    Text = "Was schaust du noch? Sie sind schon losgegangen"
  },
  AvgDialog_22297_Content_5 = {
    Text = "Wie lange habe ich geschlafen?"
  },
  AvgDialog_22297_Content_50 = {
    Text = "Keine Sorge, sie sind vernünftige Kinder"
  },
  AvgDialog_22297_Content_51 = {
    Text = "Ich mache mir keine Sorgen.\nSelbst wenn ein neuer Hüter ausgebildet werden muss, kommt das Geld vom Dexter-Familienkonto"
  },
  AvgDialog_22297_Content_52 = {
    Text = "Kümmere dich mehr um dich selbst. Ich habe gerade gehört, dass jemandes Tochter ein Rendezvous im Opernhaus hat"
  },
  AvgDialog_22297_Content_53 = {
    Text = "Junger Mann"
  },
  AvgDialog_22297_Content_54 = {
    Text = "Es ist Nacht"
  },
  AvgDialog_22297_Content_55 = {
    Text = "Ein Schiff zur Arktis? Ihr seid verrückt! Hier gibt es kein Schiff und keine Kirche!"
  },
  AvgDialog_22297_Content_56 = {
    Text = "Frag nicht weiter, wir sind nur einfache Fischer, wir wissen nichts!"
  },
  AvgDialog_22297_Content_57 = {
    Text = "Madam, bitte warten Sie—"
  },
  AvgDialog_22297_Content_58 = {
    Text = "Ihr nutzt eure städtische Macht, um die Landbewohner zu unterdrücken!"
  },
  AvgDialog_22297_Content_59 = {
    Text = "Das war nicht unsere Absicht—Hey!"
  },
  AvgDialog_22297_Content_6 = {
    Text = "Wer weiß? Du hast sogar das Nachmittagsbriefing verpasst"
  },
  AvgDialog_22297_Content_60 = {
    Text = "Die Frau schlug die Tür zu, und wenn Ramona dich nicht rechtzeitig zurückgezogen hätte, wärst du mit einer schiefen Nase zur Schule zurückgekehrt"
  },
  AvgDialog_22297_Content_61 = {
    Text = "Briellport... diese Stadt ist seltsam"
  },
  AvgDialog_22297_Content_62 = {
    Text = "Das ist die dritte Tür, die wir geöffnet haben, aber niemand will Informationen über die Stadt mit uns teilen"
  },
  AvgDialog_22297_Content_63 = {
    Text = "Wir haben nur nach dem Weg gefragt. Sie scheinen etwas zu verbergen, es ist sehr ungewöhnlich"
  },
  AvgDialog_22297_Content_64 = {
    Text = "Schau am Dock nach, vielleicht gibt es Hinweise"
  },
  AvgDialog_22297_Content_65 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_22297_Content_66 = {
    Text = "Was ist los?"
  },
  AvgDialog_22297_Content_67 = {
    Text = "Vielleicht eine Halluzination, es klingt, als ob jemand im Wind spricht"
  },
  AvgDialog_22297_Content_68 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_22297_Content_69 = {
    Text = "Oh, perfekt, zwei fremde Tollpatsche.\nHaltet sie auf? Dann müssen wir nicht nach anderen suchen"
  },
  AvgDialog_22297_Content_7 = {Text = "Sitzung?"},
  AvgDialog_22297_Content_70 = {
    Text = "Treib sie in Richtung des Schiffs"
  },
  AvgDialog_22297_Content_71 = {
    Text = "Tsk, fieser Kerl"
  },
  AvgDialog_22297_Content_72 = {
    Text = "Geh, Caecus, deine Gelegenheit, zu zeigen, was du kannst, ist gekommen"
  },
  AvgDialog_22297_Content_73 = {
    Text = "Wie du befiehlst, Lord Goliath."
  },
  AvgDialog_22297_Content_74 = {
    Text = "Countdown: Drei Stunden"
  },
  AvgDialog_22297_Content_75 = {
    Text = "Warte! Schließ die Tür noch nicht!"
  },
  AvgDialog_22297_Content_76 = {
    Text = "Das Mädchen ignorierte deine Worte und zog die Tür heftig zu.\nDer Tentakel des Monsters, der in die Tür ragte, wurde abgetrennt und bewegte sich nicht mehr"
  },
  AvgDialog_22297_Content_77 = {
    Text = "Meine Gefährten sind noch draußen!"
  },
  AvgDialog_22297_Content_78 = {
    Text = "Ha?! Gibt es noch andere auf dem Schiff?"
  },
  AvgDialog_22297_Content_79 = {
    Text = "Von so vielen Monstern umgeben, kann selbst ein Gott nicht entkommen.\nDenk nicht mehr an diese Person, ich bringe dich zum Kapitän, um zu sehen, wie wir dich vom Schiff bekommen"
  },
  AvgDialog_22297_Content_8 = {
    Text = "Es geht um Francis—"
  },
  AvgDialog_22297_Content_80 = {
    Text = "Sie ist stark. Es wird ihr gut gehen."
  },
  AvgDialog_22297_Content_81 = {
    Text = "Ja, ja, sie wird überleben. Nachdem ich den Kapitän getroffen habe, bringe ich dich zu ihr"
  },
  AvgDialog_22297_Content_82 = {
    Text = "Aber wie viel noch übrig ist... kann ich nicht garantieren"
  },
  AvgDialog_22297_Content_83 = {
    Text = "Wer bist du?"
  },
  AvgDialog_22297_Content_84 = {
    Text = "Das sollte ich sagen, du blinder Passagier! Der Kapitän sagte, dass das Betreten des Schiffs ohne Erlaubnis als blinde Passage gilt"
  },
  AvgDialog_22297_Content_85 = {
    Text = "Fräulein, Sie missverstehen uns. Wir wollten nicht illegal einreisen, wir wurden von Monstern angegriffen und mussten an Bord gehen"
  },
  AvgDialog_22297_Content_86 = {
    Text = "Diese Worte kannst du dem Kapitän sagen, mir ist es egal"
  },
  AvgDialog_22297_Content_87 = {
    Text = "Verdammt, verdammt, verdammt! Du hast alles ruiniert! Ich muss mir etwas einfallen lassen"
  },
  AvgDialog_22297_Content_88 = {
    Text = "Übrigens, merk dir meinen Namen gut –"
  },
  AvgDialog_22297_Content_89 = {
    Text = "Countdown @2 Minuten"
  },
  AvgDialog_22297_Content_9 = {
    Text = "Egal, lass den Moderator es dir selbst erklären"
  },
  AvgDialog_22297_Content_90 = {
    Text = "Wir gehen jetzt an Bord"
  },
  AvgDialog_22297_Content_91 = {
    Text = "Hast du genug gesehen?"
  },
  AvgDialog_22297_Content_92 = {
    Text = "Stimmt. Wenn das Ritual fortgesetzt wird, weiß niemand, welches Monster in Murphys Körper schlüpfen könnte"
  },
  AvgDialog_22297_Content_93 = {
    Text = "Fälschung... Stirb!"
  },
  AvgDialog_22297_Content_94 = {
    Text = "%player%, gib mir deine Hand!"
  },
  AvgDialog_22297_Content_96 = {
    Text = "Im Moment, bevor der Umhang vom Meerwasser durchnässt wurde, wehte eine vertraute Brise über die See"
  },
  AvgDialog_22297_Content_97 = {
    Text = "Ich erinnere mich... ich konnte ihre Hand nicht greifen und fiel ins Meer... Nein, aber... dies ist das Deck der Sonanil"
  },
  AvgDialog_22297_Content_98 = {
    Text = "Die traumhafte Wärme wurde vom kalten Mondlicht verdrängt, der Schleier um das Schiff zerriss und verschwand im Meer"
  },
  AvgDialog_22297_Content_99 = {
    Text = "Der Vorhang... ist verschwunden?!"
  },
  AvgDialog_22403_Content_1 = {
    Text = "Sind wir bei Aurita? Sind wir bei Aurita?"
  },
  AvgDialog_22403_Content_2 = {
    Text = "Pst, hast du nicht gesehen, dass sie gefesselt sind? Wie willst du sie in deinem Zustand retten?"
  },
  AvgDialog_22403_Content_3 = {
    Text = "Braun, es ist Zeit für unseren großen Auftritt!"
  },
  AvgDialog_22403_Content_4 = {Text = "Squeak!"},
  AvgDialog_22403_Content_5 = {
    Text = "Jenkin und ihre tierischen Begleiter schlichen sich in die Schatten der Kulisse, während Aurita wütend hinter der Kamera auf und ab lief."
  },
  AvgDialog_22403_Content_6 = {
    Text = "Keine Eile, du kommst noch dran.\nSpäter wird Meisterin Casiah dir ein paar „große Szenen“ geben."
  },
  AvgDialog_22403_Content_7 = {
    Text = "Wirklich?! Danke, Meister Casiah!"
  },
  AvgDialog_22403_Content_8 = {
    Text = "Meisterin? Hmm～ Das klingt schon besser."
  },
  AvgDialog_22406_Content_1 = {
    Text = "Halt! Wohin bringt ihr meinen geliebten Gegenstand?!"
  },
  AvgDialog_22406_Content_10 = {
    Text = "Igitt!? Rattenspucke!!"
  },
  AvgDialog_22406_Content_11 = {Text = "Squeak!"},
  AvgDialog_22406_Content_12 = {
    Text = "Gab Houdini einen großen Schlecker!"
  },
  AvgDialog_22406_Content_13 = {
    Text = "Der Kampf steht unmittelbar bevor. Das gefangene Mädchen blickte mit unergründlichem Ausdruck auf ihren Begleiter, der sich schützend vor sie gestellt hatte."
  },
  AvgDialog_22406_Content_14 = {
    Text = "—Sie biss die Zähne zusammen und presste eine pechschwarze Pustel aus ihrem Rücken!"
  },
  AvgDialog_22406_Content_2 = {
    Text = "Schatten senken sich herab, Klauen strecken sich aus einem anderen Reich, und dämonische Geister versperren den tapferen Abenteurern den Weg, bedrohlich und grimmig."
  },
  AvgDialog_22406_Content_3 = {
    Text = "Im Namen des Ritters..."
  },
  AvgDialog_22406_Content_4 = {Text = "Ähem!!"},
  AvgDialog_22406_Content_5 = {
    Text = "Hust, hust. Ich schwöre bei meiner Ehre als Detektiv von Lentiniën, ich werde alle beschützen!\nIhr kommt keinen Schritt näher!"
  },
  AvgDialog_22406_Content_6 = {
    Text = "Oh — Kommissar G, als mein besiegter Gegner, hast du noch nicht genug vom Scheitern?"
  },
  AvgDialog_22406_Content_7 = {
    Text = "Dann gebt mir nicht die Schuld, wenn ich unhöflich werde!"
  },
  AvgDialog_22406_Content_8 = {
    Text = "Nachtstreuner, jetzt ist der Moment!"
  },
  AvgDialog_22406_Content_9 = {
    Text = "Der pelzige Nachtstreuner bewegte sich flink durch die Dunkelheit, kletterte mit nahezu unsichtbarer Geschwindigkeit auf Houdinis Oberschenkel und biss kräftig zu..."
  },
  AvgDialog_22708_Content_1 = {
    Text = "Wir haben gewonnen... Wir haben gewonnen!"
  },
  AvgDialog_22708_Content_10 = {
    Text = "Der Assistent hielt den Nachtstreuner hoch und schützte vorübergehend das schöne Fell des Streuners."
  },
  AvgDialog_22708_Content_11 = {
    Text = "Hey!! Leiche, hör auf zu reden! Schutzherr! Lotan! Tut etwas!!"
  },
  AvgDialog_22708_Content_12 = {
    Text = "Lotan schüttelte den Kopf, ein Phantom einer walartigen Kreatur erschien hinter ihr. Einfach als sie im Begriff war, alle aus dem Wasser zu ziehen, stürzte sich eine helle Gestalt hinein."
  },
  AvgDialog_22708_Content_13 = {
    Text = "Wasser! Es ist Wasser～ Auritas liebstes Meer!"
  },
  AvgDialog_22708_Content_14 = {
    Text = "Äußert einen Wunsch an mich, ihr Bedürftigen! Der Ozean wird all euren Erwartungen entsprechen!"
  },
  AvgDialog_22708_Content_15 = {
    Text = "Kommissar G und der Nachtstreuner tauschten Blicke aus und schoben gleichzeitig das lange schweigsame Mädchen in Weiß zur Ozean-Elfe."
  },
  AvgDialog_22708_Content_16 = {Text = "...?!"},
  AvgDialog_22708_Content_17 = {
    Text = "Bitte, bitte bring uns von hier weg."
  },
  AvgDialog_22708_Content_18 = {
    Text = "Casiah, deren Körper bereits zur Hälfte im Wasser versunken war, verzog ihre Lippen zu einem zufriedenen Lächeln."
  },
  AvgDialog_22708_Content_19 = {
    Text = "Magische Illusionen verschieben und verwandeln sich mit einer Bewegung ihrer Hand."
  },
  AvgDialog_22708_Content_2 = {
    Text = "Die böse Zauberin wurde durch die vereinten Kräfte aller besiegt. Sie brach zu Boden zusammen und streckte schwach ihre Hand nach einem Knopf aus."
  },
  AvgDialog_22708_Content_20 = {
    Text = "Im Handumdrehen waren alle durchnässt."
  },
  AvgDialog_22708_Content_21 = {
    Text = "Niemand bleibt verschont."
  },
  AvgDialog_22708_Content_22 = {
    Text = "Du machst es ernst!?"
  },
  AvgDialog_22708_Content_23 = {
    Text = "Die Elfe kehrte in die Freiheit des Meeres zurück, und alle entkamen Houdinis Werkstatt. Erfüllt das nicht den Wunsch des Mädchens?"
  },
  AvgDialog_22708_Content_24 = {
    Text = "Da hast du nicht unrecht, aber... wie kann diese Geschichte das Ende erreichen, das Lily sich wünscht?"
  },
  AvgDialog_22708_Content_25 = {
    Text = "„Das Mädchen lebte glücklich bis ans Ende ihrer Tage mit ihrer Mutter.\""
  },
  AvgDialog_22708_Content_26 = {
    Text = "„Tsk, das ist das letzte Mal, dass ich für dich Babysitter spiele.\nBitte mich nie wieder um solche lästigen Gefallen.\""
  },
  AvgDialog_22708_Content_27 = {
    Text = "Lily, Offizier, schaut mal! Was ist da drüben im Wasser?!"
  },
  AvgDialog_22708_Content_29 = {
    Text = "Eine gewaltige Wirbelsäule erhebt sich aus dem Wasser – das große Ungeheuer, das seit der Geburt des Planeten in der Tiefsee von Kardas gehaust hat. Es folgt dem Ruf des Lebens und durchquert den Schleier der Zeit!"
  },
  AvgDialog_22708_Content_3 = {
    Text = "Als Lotan das sah, warf sie dir das Mikrofon zu. Sie trat energisch zu Casiah und begann, mit ihr zu flüstern"
  },
  AvgDialog_22708_Content_30 = {Text = "Lotan...?"},
  AvgDialog_22708_Content_31 = {
    Text = "Seid ihr bereit aufzubrechen? Wenn nicht, wird eure Geschichte in diesem Wasser ihr Ende finden."
  },
  AvgDialog_22708_Content_32 = {
    Text = "Wow! Großer Fisch!"
  },
  AvgDialog_22708_Content_33 = {
    Text = "Nicht drängeln, einer nach dem anderen. Fräulein Lotans Rücken ist recht geräumig."
  },
  AvgDialog_22708_Content_34 = {
    Text = "Kannst du, halbfertige Meeresfee, aufhören, das Rampenlicht zu stehlen? Offensichtlich sind Bru... Nein, der Nachtstreuner und ich die wahren Helden hier!"
  },
  AvgDialog_22708_Content_35 = {Text = "Ähm..."},
  AvgDialog_22708_Content_36 = {
    Text = "Der große Fisch ist Auritas Begleiter! Also muss Aurita vorne sitzen!"
  },
  AvgDialog_22708_Content_37 = {Text = "Um...!"},
  AvgDialog_22708_Content_38 = {
    Text = "Lily, Lily... Ich..."
  },
  AvgDialog_22708_Content_39 = {
    Text = "Darf ich vorne sitzen?"
  },
  AvgDialog_22708_Content_4 = {
    Text = "Was heckst du jetzt schon wieder aus? Mach es nicht unmöglich für alle, das Chaos aufzuräumen."
  },
  AvgDialog_22708_Content_40 = {
    Text = "Da du jünger bist als ich... Sei vorsichtig! Auf dem Rücken des großen Kerls gibt es keinen Sitzplatz."
  },
  AvgDialog_22708_Content_41 = {
    Text = "Aurita möchte mit ihren Freunden zusammen sein!"
  },
  AvgDialog_22708_Content_42 = {
    Text = "Hey! Warum bist du so glitschig!? Wenn du schwimmen kannst, dann kletter nicht hier hoch!"
  },
  AvgDialog_22708_Content_43 = {
    Text = "Der Koloss brüllt durch seine Atemwege, springt mit Lachen und Hoffnung aus dem Wasser."
  },
  AvgDialog_22708_Content_44 = {
    Text = "Das Licht der Morgendämmerung durchdringt Wolken und Nebel und hüllt das Meer, die kolossalen Bestien und die Abenteurer in Rot– und Rosatöne."
  },
  AvgDialog_22708_Content_45 = {
    Text = "So, so hoch—!"
  },
  AvgDialog_22708_Content_47 = {
    Text = "Kommissar G, die Meerenspirite und der Gehilfe des Nachtstreuners taten sich zusammen, um das Mädchen aufzufangen und zu verhindern, dass sie vom Rücken der riesigen Bestie rutschte."
  },
  AvgDialog_22708_Content_48 = {
    Text = "Ein paar Leute lachten und spielten, schmierten sich gegenseitig Wasser auf die Kleidung."
  },
  AvgDialog_22708_Content_49 = {
    Text = "Da schaut das mutige Mädchen plötzlich direkt herüber, mit einem besonders strahlenden und sanften Lächeln"
  },
  AvgDialog_22708_Content_5 = {
    Text = "Hoppla, nur ein kleiner Test—"
  },
  AvgDialog_22708_Content_50 = {
    Text = "Lilien, die die Blütezeit verpasst haben,"
  },
  AvgDialog_22708_Content_51 = {
    Text = "Der Moment des Blühens ist endlich angekommen."
  },
  AvgDialog_22708_Content_6 = {
    Text = "Während sich das Lächeln auf Casiahs Gesicht langsam verbreitert, dringt das Geräusch einer Unterströmung in aller Ohren."
  },
  AvgDialog_22708_Content_7 = {
    Text = "Kommt herbei, Fluten! Seid Zeugen von Meister Houdinis Finale — die ultimative Wassertank-Flucht!"
  },
  AvgDialog_22708_Content_8 = {
    Text = "Der Wasserspiegel stieg rapide an, bedeckte bald die Füße der Kinder, dann ihre Waden... Schließlich erreichte er ihre Oberschenkel und machte es ihnen schwer, sich zu bewegen."
  },
  AvgDialog_22708_Content_9 = {
    Text = "Casiah!!! Was tust du da?! Willst du uns ertränken?!"
  },
  AvgDialog_23346_Content_1 = {
    Text = "Die schwarzen Massen weichen wie eine Flut zurück, und die Loge kehrt zur Ruhe zurück."
  },
  AvgDialog_23346_Content_10 = {
    Text = "Blutrote Rosenblätter flattern herab, und ein beißender Verwesungsgestank hängt in der pechschwarzen Loge."
  },
  AvgDialog_23346_Content_11 = {
    Text = "Der maskierte Schatten erschien lautlos hinter Mrs. Sorel."
  },
  AvgDialog_23346_Content_12 = {
    Text = "Verzeihen Sie, meine Damen und Herren. Als Nächstes genießen Sie bitte—"
  },
  AvgDialog_23346_Content_14 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23346_Content_15 = {
    Text = "Eine blühende Rose durchbohrte Sorels Brust, ihre Tautropfen schimmerten in einem unheimlichen blauen Licht in der Dunkelheit."
  },
  AvgDialog_23346_Content_16 = {
    Text = "Das... was ist das..."
  },
  AvgDialog_23346_Content_17 = {
    Text = "Der Schatten erschien nur für einen Augenblick, bevor er verschwand, und ließ Sorel verwirrt auf das Blut starren, das aus ihrer Brust floss."
  },
  AvgDialog_23346_Content_18 = {
    Text = "Ahhhh!! Madame, Ihre Brust..."
  },
  AvgDialog_23346_Content_19 = {
    Text = "Blut? Widerlich... Karen, mach das für mich sauber..."
  },
  AvgDialog_23346_Content_2 = {
    Text = "Du trittst vor und ergreifst fest Sorels Hand."
  },
  AvgDialog_23346_Content_20 = {
    Text = "Tritt nicht zurück, Mrs. Sorel! Du wirst fallen!"
  },
  AvgDialog_23346_Content_21 = {
    Text = "Lady Sorel!!"
  },
  AvgDialog_23346_Content_23 = {
    Text = "Ahhh, jemand ist vom Gebäude gefallen!!"
  },
  AvgDialog_23346_Content_24 = {
    Text = "<Shake:D–Das sieht aus wie Frau Sorel...>"
  },
  AvgDialog_23346_Content_25 = {
    Text = "Goldfarbener Wein ergießt sich aus dem Glas und tanzt mit leuchtenden Rosenblättern durch die Luft."
  },
  AvgDialog_23346_Content_26 = {
    Text = "Hilfe... hilf mir..."
  },
  AvgDialog_23346_Content_27 = {
    Text = "Die extravagante und opulente Musik hallt noch immer durch das Opernhaus."
  },
  AvgDialog_23346_Content_28 = {
    Text = "Ihre Augen waren voller Angst und Verwirrung. Getrieben vom Überlebensinstinkt streckte sie die Hand nach dir aus, doch verfehlte dich knapp, als sich eure Fingerspitzen beinahe berührten."
  },
  AvgDialog_23346_Content_3 = {
    Text = "Dieser Ort ist unsicher, Frau Sorel. Bitte folgen Sie mir."
  },
  AvgDialog_23346_Content_30 = {
    Text = "Diese unvergleichliche Schönheit ist schließlich gefallen, zusammen mit ihren geliebten feinen Gewändern, dem Wein, den Blumen und dem Applaus."
  },
  AvgDialog_23346_Content_31 = {
    Text = "<Yellow:Erstes Ermittlungsprotokoll zum künstlichen Labyrinth>\n\n■Geheimgang–ID: M–B04–001\n■Erstellungszeit: n.G. 315, Juni @1, 20:00–21:00 Uhr (Der Tag von Sorels Tod).\n■Erstellungsort: Covent–Theater"
  },
  AvgDialog_23346_Content_32 = {
    Text = "■Domain Besitzer: Sorel·@2\n■Domain Eindringlinge: %player%, Ramona\n\n■Ziel: <Yellow:Untersuche Sorels Fall und @3>"
  },
  AvgDialog_23346_Content_33 = {
    Text = "■<Yellow:Ermittlungsergebnisse>\n\nDer Täter wurde vorläufig als ein <Red:maskierter Schatten> identifiziert.\nSorel stürzte in den Tod. Der Schutzherr evakuierte das künstliche Labyrinth."
  },
  AvgDialog_23346_Content_34 = {
    Text = "Misaq-Lounge\nNach dem Ende des ersten künstlichen Labyrinths"
  },
  AvgDialog_23346_Content_35 = {Text = "Wach?"},
  AvgDialog_23346_Content_36 = {
    Text = "<Shake:Ugh... mein Kopf... es tut weh...>"
  },
  AvgDialog_23346_Content_37 = {
    Text = "Herzfrequenz und Blutdruck sind normal. Der Schwankungswert der Geistkraft ist leicht erhöht, aber im kontrollierbaren Bereich."
  },
  AvgDialog_23346_Content_38 = {
    Text = "Nicht schlecht. Es scheint, dass du dich nach dem letzten <Blue:künstlichen Labyrinth von Ramona> allmählich angepasst hast."
  },
  AvgDialog_23346_Content_39 = {
    Text = "Dank meiner kontinuierlichen Verbesserungen am Geheimgang können wir jetzt sogar seine Start- und Endzeiten sowie Orte festlegen."
  },
  AvgDialog_23346_Content_4 = {Text = "!!"},
  AvgDialog_23346_Content_40 = {
    Text = "Natürlich haben auch die Forschungsgelder, die Fräulein Czort beantragt hat, eine 1%ige Rolle gespielt."
  },
  AvgDialog_23346_Content_41 = {
    Text = "Ist es wirklich nur 1%...?"
  },
  AvgDialog_23346_Content_42 = {
    Text = "Was ist mit Ramona? Wir sind zusammen hineingegangen..."
  },
  AvgDialog_23346_Content_43 = {
    Text = "Sie ruht sich im Nebenzimmer aus. Keine Sorge, ihr geht es genauso gut wie dir. Ihr Körper ist unverletzt."
  },
  AvgDialog_23346_Content_44 = {
    Text = "Hast du den Täter im Bereich von Frau Sorel gefasst?"
  },
  AvgDialog_23346_Content_45 = {
    Text = "Du schüttelst den Kopf."
  },
  AvgDialog_23346_Content_46 = {
    Text = "Ich konnte nur kurz den Geruch des Mörders wahrnehmen, wie...<Red:den Geruch verwelkender Rosenblütenblätter.>"
  },
  AvgDialog_23346_Content_47 = {
    Text = "Alles vor meinen Augen fühlt sich unwirklich an, meine Gedanken wechseln und springen ständig."
  },
  AvgDialog_23346_Content_48 = {
    Text = "Vom Sturz im Opernhaus bis zum Mord in der Gasse, von der jubelnden Menge bis zur intriganten Zofe..."
  },
  AvgDialog_23346_Content_49 = {
    Text = "Bis es schließlich vor drei Wochen zum Stillstand kam, dem Anfang der Geschichte—"
  },
  AvgDialog_23346_Content_5 = {
    Text = "Wie könnt Ihr es wagen, die Hand meiner Dame zu berühren, und so fest..."
  },
  AvgDialog_23346_Content_6 = {
    Text = "Während die Dienerin sprach, beugte sie sich plötzlich dicht an dein Ohr."
  },
  AvgDialog_23346_Content_7 = {
    Text = "<SmallShake:Hey, du hast versprochen, wir sind nur hier zum Zuschauen! Du hast mich angelogen!>"
  },
  AvgDialog_23346_Content_8 = {
    Text = "... Ich erkläre es dir später."
  },
  AvgDialog_23346_Content_9 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23347_Content_1 = {
    Text = "Du wirst von einer gewaltigen Kraft zurückgestoßen."
  },
  AvgDialog_23347_Content_2 = {
    Text = "Die Welt löst sich in Blütenblätter auf, und du stürzt in ein endloses Blütenmeer."
  },
  AvgDialog_23347_Content_3 = {
    Text = "Aaaah—!!!"
  },
  AvgDialog_23347_Content_4 = {
    Text = "<Yellow:Zweites Ermittlungsprotokoll zum künstlichen Labyrinth II>\n\n■Geheimgang–ID: M–B04–002\n■Einrichtungszeit: Holozän 315, 11. Juni, 20:00–21:00 Uhr (Der Tag von Sorels Tod).\n■Einrichtungsort: Covent Theater"
  },
  AvgDialog_23347_Content_5 = {
    Text = "■Bereichsinhaber: Sorel·@2\n■Bereichs-Eindringlinge: %player%, Ramona\n\n■Ziel: <Yellow:Basierend auf den Ergebnissen des ersten Bereichseindringens, lokalisieren Sie die Quelle der Silber-Schwankung im ersten Stock.>"
  },
  AvgDialog_23347_Content_6 = {
    Text = "■<Yellow:Ermittlungsergebnisse>\n\nEine unidentifizierte Entität @2 unterbrach die Ermittlung. Der Schutzherr verlor den Großteil der zugehörigen Erinnerungen.\n<Red:Der Schutzherr wurde gewaltsam aus dem Geheimgang vertrieben und befindet sich in kritischem Zustand.>"
  },
  AvgDialog_23348_Content_1 = {
    Text = "Ihr beiden, bitte wartet."
  },
  AvgDialog_23348_Content_2 = {
    Text = "Wir haben ein dringendes Anliegen an den alten Herrn. Könntet Ihr ihn informieren?"
  },
  AvgDialog_23348_Content_3 = {
    Text = "Verzeiht, mein Herr leidet an einer schweren ansteckenden Krankheit und ist nicht in der Lage, Besucher zu empfangen."
  },
  AvgDialog_23348_Content_4 = {
    Text = "Wir können von der Kutsche aus mit ihm sprechen, ohne näher heranzugehen."
  },
  AvgDialog_23348_Content_5 = {
    Text = "Der voll bewaffnete Mann ignoriert euren Vorschlag. Dies ist der belebteste Markt im Westbezirk; hier einen Kampf zu beginnen, würde definitiv die Aufmerksamkeit aller auf sich ziehen."
  },
  AvgDialog_23348_Content_6 = {
    Text = "Ihr wollt keinen unnötigen Ärger auf euch ziehen."
  },
  AvgDialog_23348_Content_7 = {
    Text = "Einfach leise folgen und sehen, was sie vorhaben."
  },
  AvgDialog_23349_Content_1 = {
    Text = "Ihr folgt der Kutsche über verschlungene Pfade und landet, ohne es zu bemerken, in einer öden Landschaft weit entfernt von der Stadt."
  },
  AvgDialog_23349_Content_10 = {
    Text = "Lasst uns hineingehen und nachsehen."
  },
  AvgDialog_23349_Content_2 = {
    Text = "Ein dichter Nebel hüllte alles ein und ließ nur die schwache schwarze Silhouette der Kutsche voraus erkennen."
  },
  AvgDialog_23349_Content_3 = {
    Text = "Die Umrisse verschwammen allmählich und verschwanden schließlich spurlos."
  },
  AvgDialog_23349_Content_4 = {
    Text = "Was für ein Ort... Lentiniën ist in diesen Tagen so neblig, das behindert ernsthaft die Effizienz der Polizei und Ermittler."
  },
  AvgDialog_23349_Content_5 = {
    Text = "Durch den dichten Nebel zeichnet sich in der Ferne das alte, in Trauer gehüllte Herrenhaus ab."
  },
  AvgDialog_23349_Content_6 = {
    Text = "Das Kiefernholz an der Oberfläche des Herrenhauses spaltet sich in Risse und verströmt still eine düstere Aura."
  },
  AvgDialog_23349_Content_7 = {
    Text = "Nebel, ein verlassenes Herrenhaus, der seltsame Tod einer Prominenten, ein mysteriöser alter Herr... Ja, alle Elemente eines Romans sind vorhanden."
  },
  AvgDialog_23349_Content_8 = {
    Text = "Glaubt ihr, der ältere Mann könnte drinnen sein?"
  },
  AvgDialog_23349_Content_9 = {
    Text = "Diese Gegend ist so weit das Auge reicht öde. Ich fürchte, wir haben keine andere Wahl."
  },
  AvgDialog_23351_Content_1 = {
    Text = "Du ziehst den schweren Vorhang zurück."
  },
  AvgDialog_23351_Content_10 = {
    Text = "...Bist du wach?"
  },
  AvgDialog_23351_Content_11 = {Text = "?"},
  AvgDialog_23351_Content_12 = {
    Text = "Ihr dreht schnell den Kopf, doch hinter Euch ist niemand."
  },
  AvgDialog_23351_Content_13 = {
    Text = "Lady Sorel?"
  },
  AvgDialog_23351_Content_14 = {
    Text = "Sorel fasste sich schnell wieder und schenkte Euch ein gezwungenes Lächeln."
  },
  AvgDialog_23351_Content_15 = {
    Text = "Wir kennen uns seit weniger als einer halben Stunde, und Ihr habt Euch bereits dreimal bei mir entschuldigt."
  },
  AvgDialog_23351_Content_16 = {
    Text = "Wenn Ihr Euch wirklich entschuldigen wollt, würde hiermit größere Aufrichtigkeit zum Ausdruck kommen."
  },
  AvgDialog_23351_Content_17 = {
    Text = "Sorel schwenkte die goldene Flüssigkeit in ihrem Glas."
  },
  AvgDialog_23351_Content_18 = {
    Text = "Die Person, auf die ich warte, ist noch nicht eingetroffen. Wie wäre es, ein Spiel mit mir zu spielen?\nIch stelle Euch drei Fragen. Wenn Ihr sie nicht beantworten könnt..."
  },
  AvgDialog_23351_Content_19 = {
    Text = "Sorel stellte das Glas behutsam auf den Tisch und deutete beiläufig auf den Champagner im Wagen neben ihr."
  },
  AvgDialog_23351_Content_2 = {
    Text = "Ihr seid endlich zurückgekehrt, mein Ritter."
  },
  AvgDialog_23351_Content_20 = {
    Text = "Lasst uns einen trinken."
  },
  AvgDialog_23351_Content_3 = {
    Text = "Sorel sitzt lächelnd in der Ecke und sieht so strahlend aus wie eh und je."
  },
  AvgDialog_23351_Content_4 = {
    Text = "Gott sei Dank seid Ihr wohlauf."
  },
  AvgDialog_23351_Content_5 = {
    Text = "Habt Ihr nicht gesagt, Ihr würdet mich beschützen? Ich habe so lange auf Euch gewartet."
  },
  AvgDialog_23351_Content_6 = {
    Text = "Sie lächelte unbekümmert, doch in ihrem Tonfall schwang ein Hauch subtiler Melancholie mit."
  },
  AvgDialog_23351_Content_7 = {
    Text = "Verzeiht, Madame Sorel..."
  },
  AvgDialog_23351_Content_8 = {
    Text = "<Red:Hehe.>"
  },
  AvgDialog_23351_Content_9 = {
    Text = "Sorels Blick richtet sich plötzlich hinter Euch, ihre Pupillen voller Unruhe."
  },
  AvgDialog_23352_Content_1 = {
    Text = "In dem Moment, als die Tür geöffnet wurde, schlug einem der Gestank verwelkender Blumen entgegen. Die Halle war voller roter Rosen, die aufgrund mangelnder Pflege verwelkten."
  },
  AvgDialog_23352_Content_10 = {
    Text = "Ramona blickte zum Himmel draußen."
  },
  AvgDialog_23352_Content_11 = {
    Text = "Schließen wir die Untersuchung für heute ab. Ich habe mir die Lage dieses Anwesens notiert, damit wir später die Eigentumsunterlagen überprüfen können."
  },
  AvgDialog_23352_Content_12 = {
    Text = "Hmm. Der morgige Einsatz wird wie geplant ablaufen."
  },
  AvgDialog_23352_Content_13 = {
    Text = "Zuerst holen wir die Einladung von Karen. Dann bewache ich Frau Sorel im 2. Stock, und du behältst den 1. Stock im Auge."
  },
  AvgDialog_23352_Content_14 = {
    Text = "Wenn du Glück hast, triffst du vielleicht sogar den alten Herrn in der Kutsche."
  },
  AvgDialog_23352_Content_2 = {
    Text = "Ugh... derselbe Geruch wie bei diesem maskierten Schatten."
  },
  AvgDialog_23352_Content_3 = {
    Text = "Hier ist nichts... Es scheint, als hätte hier schon lange niemand mehr gelebt."
  },
  AvgDialog_23352_Content_4 = {
    Text = "Ihr blickt euch in der düsteren, feuchten Halle um. Sie ist leer, mit Spinnweben, die in vernachlässigten Ecken schwanken, und der Boden ist übersät mit verwelkten Blütenblättern und abgefallenen Blättern."
  },
  AvgDialog_23352_Content_5 = {
    Text = "Hmm, hier hängt ein Gemälde."
  },
  AvgDialog_23352_Content_6 = {
    Text = "An der Ecke der Treppe hing ein prachtvoll gerahmtes Porträt, das mit sanften, verschwommenen Pinselstrichen eine prächtig gekleidete Dame zeigte."
  },
  AvgDialog_23352_Content_7 = {
    Text = "Das Make-up der Frau ist dezent, doch ihre hängenden Augen und die fest zusammengepressten schmalen Lippen verleihen ihr ein düsteres und beunruhigendes Erscheinungsbild."
  },
  AvgDialog_23352_Content_8 = {
    Text = "Eitempera? Das ist eine Technik, die heutzutage kaum noch verwendet wird."
  },
  AvgDialog_23352_Content_9 = {
    Text = "Das ist seltsam. Dieses Gemälde hat kein einziges Staubkorn, als würde sich jemand regelmäßig darum kümmern."
  },
  AvgDialog_23353_Content_1 = {Text = "Ei"},
  AvgDialog_23353_Content_10 = {
    Text = "Ramona runzelte die Stirn, ihre Augen voller Sorge."
  },
  AvgDialog_23353_Content_11 = {Text = "Ramona..."},
  AvgDialog_23353_Content_12 = {
    Text = "Vielleicht könnten wir erneut in den Bereich eintreten?\nIch werde Mrs. Sorel oben bewachen, und Ramona wird unten Wache halten."
  },
  AvgDialog_23353_Content_13 = {
    Text = "Das künstliche Labyrinth ist kein Touristenziel, das du jederzeit besuchen kannst. Deine oberste Priorität ist jetzt, dich auszuruhen."
  },
  AvgDialog_23353_Content_14 = {
    Text = "Allerdings müssen wir auch einige <Yellow:extreme Maßnahmen> ergreifen, um die Ermittlung voranzutreiben ..."
  },
  AvgDialog_23353_Content_15 = {
    Text = "Ich dachte, das Betreten künstlicher Labyrinthe wäre schon radikal genug."
  },
  AvgDialog_23353_Content_16 = {
    Text = "Ein seltenes „verschmitztes“ Lächeln erscheint auf Dolls sonst so ruhigem Gesicht."
  },
  AvgDialog_23353_Content_17 = {
    Text = "Es gibt noch einen radikaleren Plan, aber es hängt davon ab, ob du bereit bist, das Risiko einzugehen."
  },
  AvgDialog_23353_Content_18 = {
    Text = "Brinsburg Road, 23:00"
  },
  AvgDialog_23353_Content_19 = {
    Text = "Hahaha! Was für eine wunderbare Nacht und ein feiner Wein!"
  },
  AvgDialog_23353_Content_2 = {
    Text = "Was noch? Hast du neben der maskierten Gestalt noch andere Hinweise im Opernhaus gefunden?"
  },
  AvgDialog_23353_Content_20 = {
    Text = "Herr Nikolas, Ihre besondere Jahrgangs-Cuvée war die Rettung, die mich aus dem Gefängnis befreit hat."
  },
  AvgDialog_23353_Content_21 = {
    Text = "Wenn Misaq ein Gefängnis ist, dann ist Ihre Adoptivtochter die Gefängniswärterin? Hahaha..."
  },
  AvgDialog_23353_Content_22 = {
    Text = "Dexters Wangen glühten rot, seine Augen verträumt. Er legte einen Finger auf seine Lippen."
  },
  AvgDialog_23353_Content_23 = {
    Text = "Pst... Ich habe mich diesmal herausgeschlichen. Lass Ramona nichts davon erfahren."
  },
  AvgDialog_23353_Content_24 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23353_Content_25 = {
    Text = "Ich beneide Sie, Herr Dexter. Sie haben jemanden, dem wirklich etwas an Ihnen liegt."
  },
  AvgDialog_23353_Content_26 = {
    Text = "Und ich? Vor nicht allzu langer Zeit hat mich meine wahre Liebe verlassen — ihr Körper noch warm — und mein Vater ist ebenfalls verstorben!"
  },
  AvgDialog_23353_Content_27 = {
    Text = "Nikolas sagte dies, ging dann in die Hocke und begann zu schluchzen."
  },
  AvgDialog_23353_Content_28 = {
    Text = "Sorel... Ich werde dich definitiv rächen, sobald ich den Schuldigen gefasst habe!"
  },
  AvgDialog_23353_Content_29 = {
    Text = "<Gray:Die Liebe meines Lebens? Interessant... mindestens drei Freunde haben mir dasselbe erzählt.>"
  },
  AvgDialog_23353_Content_3 = {
    Text = "Während der Patrouille im ersten Stock hat der Silberkern eine kurze Datenfluktuation erfasst, aber sie verschwand schnell wieder."
  },
  AvgDialog_23353_Content_30 = {
    Text = "<Gray:Madame Sorel ist wahrlich bewundernswert.>"
  },
  AvgDialog_23353_Content_31 = {
    Text = "Hmph～ Ihr Gesang ist voller aufrichtiger Emotion, er bewegt mich zutiefst～"
  },
  AvgDialog_23353_Content_32 = {
    Text = "In der stillen Gasse taumelte ein gut gekleideter Herr über den Kopfsteinpflasterweg, sein Schatten lang gestreckt vom schwachen Licht der Straßenlaternen."
  },
  AvgDialog_23353_Content_33 = {
    Text = "<BigShake:Ich lebe für das Glück!>"
  },
  AvgDialog_23353_Content_34 = {
    Text = "<RedItalic:Die vielen Tränen dieser Nacht sind unvergesslich.>"
  },
  AvgDialog_23353_Content_35 = {
    Text = "<RedItalic:Lasst unser wunderschönes Blut die Glasfenster färben und das große Festmahl erleuchten.>"
  },
  AvgDialog_23353_Content_36 = {
    Text = "Ein tiefes Gesang hallte durch die leere Straße, ein maskierter Schatten glitt aus dem Dunkel der Ecke vor Dexter."
  },
  AvgDialog_23353_Content_37 = {
    Text = "Guten Abend, Edler Dexter."
  },
  AvgDialog_23353_Content_38 = {
    Text = "Äh... du hast es falsch gesungen.\nDie nächste Zeile sollte lauten: „Ihre Augen füllten sich mit Tränen, und ich war zutiefst gefesselt.“"
  },
  AvgDialog_23353_Content_39 = {
    Text = "Der Schatten nickte plötzlich erkennend und schlug sich frustriert an die Stirn."
  },
  AvgDialog_23353_Content_4 = {
    Text = "Daher ist der Täter höchstwahrscheinlich ein Gast aus dem ersten Stock."
  },
  AvgDialog_23353_Content_40 = {
    Text = "Hoppla. Ich wollte eine große Vorstellung geben, bevor ich Euch töte, aber ich habe sogar den Text falsch gesungen."
  },
  AvgDialog_23353_Content_41 = {
    Text = "Töte mich...?"
  },
  AvgDialog_23353_Content_42 = {
    Text = "Ehrlich gesagt scheinen Sie ein vernünftiger Gentleman zu sein. Warum das Leben eines unschuldigen Junggesellen mitten in der Nacht nehmen?"
  },
  AvgDialog_23353_Content_43 = {
    Text = "Der Schatten zuckte unschuldig mit den Schultern."
  },
  AvgDialog_23353_Content_44 = {
    Text = "Ich bin nur ein bescheidener Diener, und alles, was ich tue, dient der Erfüllung der Wünsche meines Herrn."
  },
  AvgDialog_23353_Content_45 = {
    Text = "Damit löste er sich rasch wie Tinte auf und verschwand in der grenzenlosen Nacht."
  },
  AvgDialog_23353_Content_46 = {Text = "...Hä?"},
  AvgDialog_23353_Content_47 = {
    Text = "Ein plötzlicher Schauer durchfährt meinen Rücken, gefolgt von einem überwältigenden Geruch verwelkter Blumen, ein widerlich süßes Aroma, das mich beinahe würgen lässt."
  },
  AvgDialog_23353_Content_48 = {
    Text = "Pass auf dich auf, Herr Dexter."
  },
  AvgDialog_23353_Content_49 = {
    Text = "Keine Sorge, ich mag Euch durchaus; tatsächlich bewundere ich Euch sogar."
  },
  AvgDialog_23353_Content_5 = {
    Text = "Ramona nickte."
  },
  AvgDialog_23353_Content_50 = {
    Text = "Deshalb werde ich versuchen, Euren Tod so schmerzlos wie möglich zu gestalten —"
  },
  AvgDialog_23353_Content_6 = {
    Text = "Nachdem Mrs. Sorel vom Gebäude gefallen war, wurde die Szene lange Zeit abgesperrt, und jeder gab eine Aussage."
  },
  AvgDialog_23353_Content_7 = {
    Text = "Die meisten Gäste im ersten Stock stammen aus der Mittelschicht und haben keine Verbindung zu Frau Sorel."
  },
  AvgDialog_23353_Content_8 = {
    Text = "Es scheint, die Ermittlung ist in eine Sackgasse geraten."
  },
  AvgDialog_23353_Content_9 = {
    Text = "Unter den Adligen, die an der Beerdigung teilnahmen, haben nur wenige überlebt. Dexter schwebt nun in großer Gefahr."
  },
  AvgDialog_23354_Content_1 = {
    Text = "Wunsch der Kammerjungfer"
  },
  AvgDialog_23354_Content_10 = {
    Text = "Zur Seite, gib mir drei Portionen! Ich habe noch mehrere Töchter zu Hause..."
  },
  AvgDialog_23354_Content_11 = {
    Text = "Kann eine kleine Betrügerin eine Einladung zu „Der Name der Rosenblume\" haben?"
  },
  AvgDialog_23354_Content_12 = {
    Text = "Sie ist nicht nur eine kleine Lügnerin, sondern auch eine echte Zofe von Frau Sorel."
  },
  AvgDialog_23354_Content_13 = {
    Text = "Du räuspertest dich und tratest vor, wobei du deine Ermittlungsmarke aus der Tasche zogst"
  },
  AvgDialog_23354_Content_14 = {
    Text = "Ermittlungseinsatz der Polizei Lentiniën. Bitte treten Sie alle zurück."
  },
  AvgDialog_23354_Content_15 = {Text = "Polizei?!"},
  AvgDialog_23354_Content_16 = {
    Text = "Das heutige Geschäft, ich meine die Veranstaltung, endet hier! Karen fiel plötzlich ein, dass sie dringende Angelegenheiten hatte..."
  },
  AvgDialog_23354_Content_17 = {
    Text = "Das heißt, außer Ihnen, Fräulein Karen. Die anderen dürfen jetzt gehen."
  },
  AvgDialog_23354_Content_18 = {
    Text = "Die Menge zerstreute sich allmählich. Karen zappelte unruhig herum, beruhigte sich aber bald."
  },
  AvgDialog_23354_Content_19 = {
    Text = "Sie musterte dich und Ramona aufmerksam und brach dann plötzlich in ein strahlendes Lächeln aus."
  },
  AvgDialog_23354_Content_2 = {
    Text = "Einfach zur Klarstellung, dies ist kein gewöhnliches Badewasser!"
  },
  AvgDialog_23354_Content_20 = {
    Text = "Ja, Herr Wachtmeister, Karen geht nirgendwohin."
  },
  AvgDialog_23354_Content_21 = {
    Text = "Nun... Karen ist nur eine bescheidene Zofe. Ich frage mich, womit ich Ihnen behilflich sein könnte?"
  },
  AvgDialog_23354_Content_22 = {
    Text = "Keine Sorge. Wir interessieren uns nicht für Ihr kleines Geschäft, wir brauchen nur, dass Sie..."
  },
  AvgDialog_23354_Content_23 = {Text = "Whoa—!!"},
  AvgDialog_23354_Content_24 = {
    Text = "Ein Eimer kaltes Wasser ergießt sich über dich und Ramona und durchnässt euch beide augenblicklich."
  },
  AvgDialog_23354_Content_25 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23354_Content_26 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23354_Content_27 = {
    Text = "Sie hat nicht gelogen; es riecht wirklich nach Rosenblumen darin."
  },
  AvgDialog_23354_Content_28 = {
    Text = "Heh heh! Ihr wollt mich also reinlegen, damit ich mit euch ins Gefängnis gehe, ja?"
  },
  AvgDialog_23354_Content_29 = {
    Text = "<Big:Fangt mich doch, wenn ihr könnt!!>"
  },
  AvgDialog_23354_Content_3 = {
    Text = "Karen hat seltene Badesalze aus Ceylon hinzugefügt, zusammen mit 18 Gewürzen wie Lavendel, Zitrus und Nelke..."
  },
  AvgDialog_23354_Content_30 = {
    Text = "Karen schnitt dir eine Grimasse, raffte ihren Rock und rannte so schnell sie konnte davon."
  },
  AvgDialog_23354_Content_31 = {
    Text = "Nicht rennen! Warte nur, bis ich dich erwische—ich werde dir eine Lektion erteilen!"
  },
  AvgDialog_23354_Content_4 = {
    Text = "Zum Schluss wird es einen Tag und eine Nacht lang mit Rosenblüten aus dem südlichen Konstant bedampft. Selbst jetzt verströmt es noch seinen Duft!"
  },
  AvgDialog_23354_Content_5 = {
    Text = "Das Geheimnis von Frau Sorels ewiger Jugend liegt in diesem duftenden Badewasser..."
  },
  AvgDialog_23354_Content_6 = {Text = "Uwaa—!!"},
  AvgDialog_23354_Content_7 = {
    Text = "Oh mein Gott, das ist ja unglaublich! Kann es die Narben in meinem Gesicht heilen...?"
  },
  AvgDialog_23354_Content_8 = {
    Text = "Drückt nicht... Stellt euch an, jeder! Hört her, fünf Leo-Fänge pro Portion!"
  },
  AvgDialog_23354_Content_9 = {
    Text = "Gib mir eine Portion! Ich war zuerst hier...!!"
  },
  AvgDialog_23355_Content_1 = {
    Text = "Damenführer"
  },
  AvgDialog_23355_Content_10 = {
    Text = "Anführer... Ich habe das unter dem Rad gefunden!"
  },
  AvgDialog_23355_Content_11 = {
    Text = "Noch eine Rose? Heh, ziemlich selbstsicher. Es scheint, als würde dieser Mörder uns herausfordern."
  },
  AvgDialog_23355_Content_12 = {
    Text = "Überprüft, welche Adligen, die an der Beerdigung teilgenommen haben, noch anwesend sind."
  },
  AvgDialog_23355_Content_13 = {
    Text = "Sie sind jetzt in großer Gefahr."
  },
  AvgDialog_23355_Content_14 = {
    Text = "Mythag Unterdurchgang"
  },
  AvgDialog_23355_Content_15 = {
    Text = "Sie gingen durch die düstere Untergrundpassage, ihre etwas ungeordneten Schritte hallten um sie herum."
  },
  AvgDialog_23355_Content_16 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23355_Content_17 = {
    Text = "Es ist selten, dich so zu sehen. Sag mir nicht, dass du vor Angst wegen des Geistes nicht schlafen kannst?"
  },
  AvgDialog_23355_Content_18 = {
    Text = "Allerdings. Jetzt sind alle im Kreis nervös. Einfach nur Kondolenzbriefe zu schreiben hat mich fast umgebracht."
  },
  AvgDialog_23355_Content_19 = {
    Text = "Und dann muss man sich noch mit diesen lästigen Detektiven und Boulevardreportern herumschlagen..."
  },
  AvgDialog_23355_Content_2 = {
    Text = "Brinsborough Straße, 19:30\nDrei Wochen nach dem Tod von Mrs. Sorel"
  },
  AvgDialog_23355_Content_20 = {
    Text = "Bleib die nächsten Tage in der Schule.\nAls Überlebender der Beerdigung hast du jetzt höchste Priorität bei unserem Schutz."
  },
  AvgDialog_23355_Content_21 = {
    Text = "Keine Sorge, ich werde ein Auge auf ihn haben und jemandes schlechte Angewohnheit des Trinkens und Herumtreibens korrigieren."
  },
  AvgDialog_23355_Content_22 = {
    Text = "Herumtreiben? Es ist eindeutig normale gesellschaftliche Unterhaltung, und du lässt es so schrecklich klingen."
  },
  AvgDialog_23355_Content_23 = {
    Text = "<SmallShake:Ähm, bitte beruhigt euch, ihr beiden...>"
  },
  AvgDialog_23355_Content_24 = {
    Text = "Ich habe gehört, Frau Sorel hat sich nach ihrem Tod in eine Handvoll Silber verwandelt. Sie wird jetzt in der Erweckter–Körper–Abteilung extrahiert und wartet auf die <Yellow:Zweite Erweckung>?"
  },
  AvgDialog_23355_Content_25 = {
    Text = "Du bist gut informiert. Allerdings ist die Erfolgsrate einer zweiten Erweckung extrem niedrig. Rechne nicht damit."
  },
  AvgDialog_23355_Content_26 = {
    Text = "Verstanden. Ich hätte nur nicht erwartet, dass nach dem Tod eines Erweckers ein Silberkern entsteht. Was unterscheidet den neuen Erweckten Körper vom ursprünglichen?"
  },
  AvgDialog_23355_Content_27 = {
    Text = "Er erbt die Erinnerungen und Persönlichkeit des Vorgängers, aber mit deutlich reduzierten Fähigkeiten.\nDeshalb habe ich unseren Erwecker immer daran erinnert, leichtsinnige Tode zu vermeiden."
  },
  AvgDialog_23355_Content_28 = {
    Text = "Hat Frau Sorel als Erwecker besondere Fähigkeiten?\nJemand mit ihrem Status muss unglaublich mächtig sein."
  },
  AvgDialog_23355_Content_29 = {
    Text = "Doll schüttelte den Kopf."
  },
  AvgDialog_23355_Content_3 = {
    Text = "Eilige Schritte hallen durch die enge Gasse. Jenseits der entfernten Schaulustigen sind die Detektive von Lentiniën beschäftigt."
  },
  AvgDialog_23355_Content_30 = {
    Text = "Ihre Akten sind in Misaq streng geheim, selbst ich habe keinen Zugang.\nAber ich habe gehört, es geht um einige... nun ja, eher frivole Fähigkeiten."
  },
  AvgDialog_23355_Content_31 = {
    Text = "Das erklärt, warum sie, eine Erweckerin, trotzdem im Opernhaus vor aller Augen ermordet wurde."
  },
  AvgDialog_23355_Content_32 = {
    Text = "Fließend? Könnte es so etwas wie die Bezauberung des anderen Geschlechts oder ewige Jugend sein?"
  },
  AvgDialog_23355_Content_33 = {
    Text = "Vielleicht, aber ich habe kein Interesse an sinnlosen Spekulationen."
  },
  AvgDialog_23355_Content_34 = {
    Text = "Streng geheime Informationen... Warum?"
  },
  AvgDialog_23355_Content_35 = {
    Text = "Natürlich, weil sie eine hohe Position innehat. Sorel und Misaq pflegen seit Langem enge Beziehungen zur Regierung, aber ihre Herkunft bleibt ein Rätsel."
  },
  AvgDialog_23355_Content_36 = {
    Text = "Was ist mit den anderen Opfern? Familiäre Verbindungen, finanzielle Transaktionen, politische Haltung... Ich muss alles wissen. Wer profitiert am meisten von diesen Fällen?"
  },
  AvgDialog_23355_Content_37 = {
    Text = "Die Ermittlungen laufen, aber der Fortschritt ist schleppend. Die sozialen Netzwerke dieser Adligen sind komplexer als die Verzweigungen der Isis."
  },
  AvgDialog_23355_Content_38 = {
    Text = "Die Berühmtheiten, die an der Beerdigung teilgenommen haben, sterben einer nach dem anderen."
  },
  AvgDialog_23355_Content_39 = {
    Text = "Angesichts der aktuellen Lage wird Dexter wahrscheinlich das nächste Ziel..."
  },
  AvgDialog_23355_Content_4 = {
    Text = "Der Verstorbene ist @1·Baron Cavendish, 32 Jahre alt. Nach dem Verlassen einer Zusammenkunft mit Freunden mitten in der Nacht wurde er hier um 4 Uhr morgens gefunden."
  },
  AvgDialog_23355_Content_40 = {
    Text = "Keine Sorge, genau deshalb habe ich dich hierhergebracht."
  },
  AvgDialog_23355_Content_41 = {
    Text = "Während ihr sprecht, seid ihr bereits an eurem Ziel angekommen. Doll blieb stehen und deutete auf eine verschlossene Tür in der Ecke des dunklen Raumes."
  },
  AvgDialog_23355_Content_42 = {
    Text = "Einst bist du durch sie in Ramonas künstliches Labyrinth eingetreten, eine unvergessliche Erinnerung."
  },
  AvgDialog_23355_Content_43 = {
    Text = "Da herkömmliche Ermittlungen schwierig sind, versuche es mit dem <Yellow:künstlichen Labyrinth>."
  },
  AvgDialog_23355_Content_44 = {
    Text = "Verstanden! Ich kann über Frau Sorels Geheimgang an den Tatort zurückkehren und eine gründliche Untersuchung durchführen!"
  },
  AvgDialog_23355_Content_45 = {
    Text = "Sorels Geheimgang allein reicht nicht aus; wir brauchen die Geheimgänge ihrer <Blue:Zofe Karen> und noch weiterer beteiligter Personen, um Hinweise zu sammeln."
  },
  AvgDialog_23355_Content_46 = {
    Text = "Ist Karen die Zofe?"
  },
  AvgDialog_23355_Content_47 = {
    Text = "Doll nickte."
  },
  AvgDialog_23355_Content_48 = {
    Text = "Sie war am Boden zerstört über Sorels Tod und schwor, bei unseren Ermittlungen voll zu kooperieren, um den wahren Mörder zu finden."
  },
  AvgDialog_23355_Content_49 = {
    Text = "Misaq, Eintritt zum künstlichen Labyrinth\nVor dem Aufbruch"
  },
  AvgDialog_23355_Content_5 = {
    Text = "Es ist bereits der 7. Adlige, der unter ungewöhnlichen Umständen gestorben ist. Ich erinnere mich, der erste war..."
  },
  AvgDialog_23355_Content_50 = {
    Text = "Als alles bereit war, drehte sich Ramona um und blickte Dexter an."
  },
  AvgDialog_23355_Content_51 = {
    Text = "Verlasst die Schule nicht und wandert auch nicht darin herum. Wartet auf unsere Rückkehr."
  },
  AvgDialog_23355_Content_52 = {
    Text = "Da ist er wieder, dieser Ton, mit dem du Kinder beschwichtigst. Erinnerst du dich daran, dass ich dein Älterer bin, dein verehrter Vater?"
  },
  AvgDialog_23355_Content_53 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23355_Content_54 = {
    Text = "Schon gut, schon gut, ich ergebe mich...\nIch bleibe jeden Tag hier, gehe nirgendwohin, und ich verspreche, niemandem Ärger zu machen."
  },
  AvgDialog_23355_Content_55 = {
    Text = "Dexter trug sein gewohntes Lächeln. Er legte seine Hände auf deinen und Ramonas Rücken und schob euch sanft nach vorne —"
  },
  AvgDialog_23355_Content_56 = {
    Text = "Los geht's, Kinder. Mein Leben liegt in euren Händen."
  },
  AvgDialog_23355_Content_6 = {
    Text = "<Red:Herzog Harold>. Ich erinnere mich sehr genau an diesen Fall. Es war ein Porsche — davon gibt es nur wenige im ganzen Königreich!"
  },
  AvgDialog_23355_Content_7 = {
    Text = "Schade, dass er zu Schrott zertrümmert wurde... Damals saßen Herzog Harold, sein Butler und der Fahrer im Wagen, und alle drei kamen ums Leben."
  },
  AvgDialog_23355_Content_8 = {
    Text = "Das Einzige, was diese Verstorbenen gemeinsam haben, abgesehen davon, dass sie Berühmtheiten sind, ist, dass sie alle vor drei Wochen an Frau Sorels Beerdigung teilgenommen haben."
  },
  AvgDialog_23355_Content_9 = {
    Text = "Könnte es wirklich so sein, wie die Boulevardblätter sagen, heimgesucht vom <Red:Geist der Frau Sorel>..."
  },
  AvgDialog_23356_Content_1 = {
    Text = "Rosenbeerdigung"
  },
  AvgDialog_23356_Content_10 = {
    Text = "Hanna hat noch keine weiteren Informationen von der Polizeistation sammeln können... Aber das macht nichts, Reporterin Hanna gibt niemals auf! Jetzt bin ich mit neuen Infos zurück!"
  },
  AvgDialog_23356_Content_11 = {
    Text = "Intelligenz 1: Es wird gesagt, dass der Friedhof heute mit Tausenden von \"Roten Feier\"-Rosen geschmückt wurde, die aus Konstantin transportiert wurden, was insgesamt 10.000 Leo-Fänge kostete!"
  },
  AvgDialog_23356_Content_12 = {
    Text = "Info· einer von zwei: Ratet mal, wen ich gerade draußen gesehen habe?"
  },
  AvgDialog_23356_Content_13 = {
    Text = "Die Familie Cavendish, der Herzog und die Herzogin von Windsor, und was alle am meisten interessiert..."
  },
  AvgDialog_23356_Content_14 = {
    Text = "<Big:Den ehrenwerten Herzog Harold und seinen einzigen Sohn, Nikolas Harold!>"
  },
  AvgDialog_23356_Content_15 = {
    Text = "Damals sorgte die Nachricht, dass Vater und Sohn sich wegen Frau Sorel duelliert hatten, für großes Aufsehen..."
  },
  AvgDialog_23356_Content_16 = {
    Text = "Unterdessen, auf dem Woodlawn-Friedhof..."
  },
  AvgDialog_23356_Content_17 = {
    Text = "Heute versammeln wir uns, um Sorel·@1s Leben zu erinnern und zu ehren."
  },
  AvgDialog_23356_Content_18 = {
    Text = "Sie ist die frömmste Tochter des Gottvaters, eine tugendhafte und bewundernswerte Frau..."
  },
  AvgDialog_23356_Content_19 = {
    Text = "Hatschi...<Big:Hatschi!>"
  },
  AvgDialog_23356_Content_2 = {
    Text = [[
Vor dem Woodlawn-Friedhof  
Vor drei Wochen]]
  },
  AvgDialog_23356_Content_20 = {
    Text = "Herzog, habt Ihr Euch erkältet? Ihr niest ununterbrochen."
  },
  AvgDialog_23356_Content_21 = {
    Text = "Der Geruch dieser kitschigen Blumen ist unerträglich... Es muss mindestens mehrere tausend Leo Fangs gekostet haben, um sie hierher zu bringen."
  },
  AvgDialog_23356_Content_22 = {
    Text = "Sorel bewahrte bis zum Ende ihre neureiche Attitüde, was durchaus bewundernswert ist... Hatschi!"
  },
  AvgDialog_23356_Content_23 = {
    Text = "Wahrhaft bewundernswert."
  },
  AvgDialog_23356_Content_24 = {
    Text = "Solch ein Verhalten liefert Journalisten und Bürgern reichlich Gesprächsstoff. Kein Wunder, dass sie zu einer beliebten Ikone in Lentiniën geworden ist."
  },
  AvgDialog_23356_Content_25 = {
    Text = "Hmph. Erbärmliche Tricks."
  },
  AvgDialog_23356_Content_26 = {
    Text = "Dexter zuckte die Schultern und sah sich gelangweilt um."
  },
  AvgDialog_23356_Content_27 = {
    Text = "Elegant gekleidete Eliten versammeln sich in kleinen Gruppen vor dem Grab, ihre absichtlich gedämpften Gespräche dringen gelegentlich zwischen den Gebeten des Zelebranten ans Ohr."
  },
  AvgDialog_23356_Content_28 = {
    Text = "<Gray:Ein Landmädchen, das sich als ausländische Lorde ausgab...>"
  },
  AvgDialog_23356_Content_29 = {
    Text = "<Gray:Die Kleidung, in der sie bestattet wurde, war aus Flanell, oder? Die Textur fühlt sich großartig an...>"
  },
  AvgDialog_23356_Content_3 = {
    Text = "Zzz... Zzz..."
  },
  AvgDialog_23356_Content_30 = {
    Text = "<Gray:...die Mätresse des Königs... und der Prinz... doch die Königin drückt ein Auge zu...>"
  },
  AvgDialog_23356_Content_31 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23356_Content_32 = {
    Text = "Es scheint, als wäre diese Dame nicht besonders beliebt."
  },
  AvgDialog_23356_Content_33 = {
    Text = "Staub zu Staub, Asche zu Asche. \n Die Seele von Mrs. Sorel ist in das Elyseische eingetreten und kehrt in die Umarmung des Vaters zurück..."
  },
  AvgDialog_23356_Content_34 = {
    Text = "Edel Dexter, Eurer Reaktion nach zu urteilen scheint Ihr unserer Ansicht über Frau Sorel nicht zuzustimmen?"
  },
  AvgDialog_23356_Content_35 = {
    Text = "Seid Ihr einer ihrer Bewunderer? Oder besser gesagt... wart es? Werdet es sein?"
  },
  AvgDialog_23356_Content_36 = {
    Text = "Ein Ausbruch leisen Gelächters ertönte aus der Menge, und Dexter runzelte die Stirn."
  },
  AvgDialog_23356_Content_37 = {
    Text = "Ich hatte während ihrer Lebenszeit nicht viel persönlichen Kontakt mit Frau Sorel, noch interessiere ich mich für die Konflikte zwischen ihr und dir."
  },
  AvgDialog_23356_Content_38 = {
    Text = "Allerdings sagt mir mein gesunder Menschenverstand, dass es sich für einen Gentleman nicht gehört, bei einer Beerdigung über die Verstorbene zu lästern."
  },
  AvgDialog_23356_Content_39 = {
    Text = "Hütet Euch vor einem weiblichen Geist, der um Mitternacht anklopft."
  },
  AvgDialog_23356_Content_4 = {
    Text = "Ähm... Sind Kamera und Belichtungsmesser bereit? Tollpatsch, beeil dich!"
  },
  AvgDialog_23356_Content_40 = {
    Text = "...Möge der Vatergott mein Kind beschützen."
  },
  AvgDialog_23356_Content_41 = {
    Text = "Die Nacht bricht herein. Ein brandneuer Ferdinand–Porsche–Wagen fährt über die unebene Schotterstraße."
  },
  AvgDialog_23356_Content_42 = {
    Text = "Verdammt, diese Klatschreporter sind überall, wo ich hingehe."
  },
  AvgDialog_23356_Content_43 = {
    Text = "Es kursiert ein Gerücht, dass Nikolas und ich uns wegen Sorel heftig gestritten hätten. Was für ein Unsinn!"
  },
  AvgDialog_23356_Content_44 = {
    Text = "Wie könnten einfache Leute die wahren Gedanken des Herzogs verstehen? Sie glauben lieber an diese klischeehaften, absurden Liebesgeschichten."
  },
  AvgDialog_23356_Content_45 = {
    Text = "Liebe, hm. Nikolas hat mir auch gesagt, es nennt sich „Liebe“."
  },
  AvgDialog_23356_Content_46 = {
    Text = "Normalerweise drücke ich bei ihren Eskapaden ein Auge zu, aber diese Frau hat es auf die Jagdgründe am Stadtrand von Shoreditch abgesehen."
  },
  AvgDialog_23356_Content_47 = {
    Text = "Gier bringt unweigerlich Unheil, also gebt uns nicht die Schuld, wenn wir gnadenlos sind..."
  },
  AvgDialog_23356_Content_48 = {Text = "—!!"},
  AvgDialog_23356_Content_49 = {
    Text = "Das Auto kam kreischend zum Stehen, das scharfe Bremsgeräusch durchschnitt die Stille der Nacht."
  },
  AvgDialog_23356_Content_5 = {Text = "Brumm..."},
  AvgDialog_23356_Content_50 = {
    Text = "<Shake:Autsch!! Mein Rücken...>"
  },
  AvgDialog_23356_Content_51 = {
    Text = "Deine Fahrkünste werden immer absurder, Fred. Hast du vergessen, wie man bremst?"
  },
  AvgDialog_23356_Content_52 = {
    Text = "<Shake:Nein, Sir... da... da ist etwas... vor uns...>"
  },
  AvgDialog_23356_Content_53 = {
    Text = "Der Schatten stand allein im kalten Mondlicht, mit einem blutgemalten Lächeln, das sich bis zu den hohlen Augenwinkeln der Maske erstreckte."
  },
  AvgDialog_23356_Content_54 = {
    Text = "Er stand am Ende der verlassenen Gasse, die Arme ausgebreitet, und summte leise ein fröhliches Trinklied."
  },
  AvgDialog_23356_Content_55 = {
    Text = "<RedItalic:Lasst uns die Kelche hoch erheben; der Wein darin ist berauschend.>"
  },
  AvgDialog_23356_Content_56 = {
    Text = "<RedItalic:Glückliche Zeiten mögen erfreulich sein, doch ein aufrichtiger Tod ist noch kostbarer...>"
  },
  AvgDialog_23356_Content_57 = {
    Text = "Guten Abend, Herr Harold."
  },
  AvgDialog_23356_Content_6 = {
    Text = "Bereit zum Drehen? Großartig... 3, 2, 1, Aufnahme!"
  },
  AvgDialog_23356_Content_7 = {
    Text = "Guten Morgen, Freunde von Misaq! Hier ist Hanna, eure Schulreporterin, mit einem exklusiven Bericht!"
  },
  AvgDialog_23356_Content_8 = {
    Text = "Die Beerdigung von <Blue:Frau Sorel>, einer von den Bürgern Lentiniëns geliebten Persönlichkeit des öffentlichen Lebens, findet auf dem Woodlawn-Friedhof statt, nicht weit von mir entfernt!"
  },
  AvgDialog_23356_Content_9 = {
    Text = "Die Zeit vergeht! Es ist eine ganze Woche vergangen seit dem mysteriösen Tod von Mrs. Sorel im Opernhaus."
  },
  AvgDialog_23359_Content_10 = {
    Text = "Du bist ein kluger Mensch, Sorel. Herr Binder ist die beste Verbindung, die wir knüpfen können, verstanden?"
  },
  AvgDialog_23359_Content_11 = {
    Text = "Es ist in Ordnung, wenn du ihn nicht magst. Solange du sein Vermögen erlangst, kannst du tun, was du willst, und dich treffen, mit wem du möchtest."
  },
  AvgDialog_23359_Content_12 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23359_Content_13 = {
    Text = "Ich mag das nicht, Vater."
  },
  AvgDialog_23359_Content_14 = {
    Text = "Familien wie unsere können es sich nicht leisten, zu tun, was ihnen beliebt.\nSieh dir die Krankheit deiner Mutter an. Kannst du es ertragen, sie so leiden zu sehen?"
  },
  AvgDialog_23359_Content_15 = {
    Text = "<Shake:Hust, hust... Mach dir keine Sorgen um mich, Sorel. Ich werde sowieso nicht mehr lange durchhalten...>"
  },
  AvgDialog_23359_Content_16 = {Text = "Mutter..."},
  AvgDialog_23359_Content_17 = {
    Text = "Sorel, deine Mutter und ich sind jetzt alt. Du bist unsere einzige Hoffnung."
  },
  AvgDialog_23359_Content_18 = {
    Text = "Wir haben nicht aus Nächstenliebe so viel Geld in dich gesteckt; wir erwarten eines Tages eine Gegenleistung, verstanden?"
  },
  AvgDialog_23359_Content_19 = {
    Text = "Tu nichts, wofür du es bereuen würdest."
  },
  AvgDialog_23359_Content_2 = {
    Text = "245 Jahre vor der Alluvialen Ära, im Süden von Konstant"
  },
  AvgDialog_23359_Content_20 = {
    Text = "In einer stillen Nacht saß das Mädchen am Bett und starrte geistesabwesend auf das helle Mondlicht vor dem Fenster."
  },
  AvgDialog_23359_Content_21 = {
    Text = "Sie umarmte ihre Knie und machte sich still Mut, so wie sie es immer tat."
  },
  AvgDialog_23359_Content_22 = {
    Text = "Fürchte dich nicht, Sorel. Du wirst einen Weg finden."
  },
  AvgDialog_23359_Content_23 = {
    Text = "<Red:Wie schade... Ist das der Preis der Schönheit?>"
  },
  AvgDialog_23359_Content_24 = {
    Text = "<Red:Selbst der makelloseste Mond wird, einmal in die sterbliche Welt gefallen, vom Staub befleckt.>"
  },
  AvgDialog_23359_Content_25 = {
    Text = "Der Nebel in der Ecke raschelt und windet sich, verdichtet sich zu einer chaotischen menschlichen Gestalt."
  },
  AvgDialog_23359_Content_26 = {Text = "?!"},
  AvgDialog_23359_Content_27 = {
    Text = "Wer seid Ihr? Ich rufe um Hilfe—"
  },
  AvgDialog_23359_Content_28 = {
    Text = "Shh... Ich bin nur eine wandernde Seele, die durch die Welt schleicht; meine Identität ist erdichtet und mein Aussehen eine Verkleidung."
  },
  AvgDialog_23359_Content_29 = {
    Text = "Freut mich, dich kennenzulernen. Du kannst mich <Red:„ N “> nennen."
  },
  AvgDialog_23359_Content_3 = {
    Text = "Sorel, meine wunderschöne Sorel. Hier ist ein neues Kleid, das ich für dich gekauft habe, dein weißes Lieblingskleid."
  },
  AvgDialog_23359_Content_30 = {
    Text = "Aus einer unbeschreiblichen Laune heraus sammle und schreibe ich Geschichten um.\nWenn ich auf faszinierende Menschen treffe, bin ich durchaus bereit zu helfen — im Rahmen des Möglichen."
  },
  AvgDialog_23359_Content_31 = {
    Text = "Also erzähl mir ruhig von deiner Verwirrung."
  },
  AvgDialog_23359_Content_32 = {
    Text = "Die Stimme des dunklen Nebels ist tief und melodisch, mit einer unerklärlichen Anziehungskraft.\nDas Mädchen beruhigt sich allmählich."
  },
  AvgDialog_23359_Content_33 = {
    Text = "Mein Vater ist nicht klug genug, und Mr. Binder ist alles andere als eine ideale Partie. Er ist gierig und spielsüchtig; innerhalb von drei Jahren wird er das Familienvermögen durchbringen."
  },
  AvgDialog_23359_Content_34 = {
    Text = "Aber ich bin zu schwach, um mich gegen sie zu wehren."
  },
  AvgDialog_23359_Content_35 = {
    Text = "Was meine Mutter betrifft... Sie weint ständig. Sie kann mir nicht helfen."
  },
  AvgDialog_23359_Content_36 = {
    Text = "Das Mädchen senkte den Kopf, ihr Ausdruck düster."
  },
  AvgDialog_23359_Content_37 = {
    Text = "Ich bin erschöpft. Erschöpft davon, mir ständig Sorgen ums Geld zu machen, erschöpft von dem Gefühl, dass mein Schicksal in den Händen anderer liegt."
  },
  AvgDialog_23359_Content_38 = {
    Text = "Ihr sagtet, Ihr könntet mir helfen — könnt Ihr mir eine große Summe Geld geben?"
  },
  AvgDialog_23359_Content_39 = {
    Text = "Ich fürchte, das nicht, mein Kind."
  },
  AvgDialog_23359_Content_4 = {
    Text = "Das ist wunderschön, danke, Vater. Aber es sieht zu kostbar aus..."
  },
  AvgDialog_23359_Content_40 = {
    Text = "Für mich töten?"
  },
  AvgDialog_23359_Content_41 = {
    Text = "Hahaha... Das sollte eine 13-jährige Dame nicht sagen, aber genau deshalb habe ich dich ausgewählt."
  },
  AvgDialog_23359_Content_42 = {
    Text = "Tut mir leid, ich kann nicht für dich töten.\nAber ich versichere dir, wenn wir einen Vertrag schließen, wirst du eine gewisse „notwendige Unterstützung“ erhalten."
  },
  AvgDialog_23359_Content_43 = {
    Text = "Diese Methoden sind nicht direkt, doch sie sind tödlich genug."
  },
  AvgDialog_23359_Content_44 = {
    Text = "Sie werden Euch helfen, zu beispiellosen Höhen aufzusteigen, ungesehene Aussichten zu genießen, und Ihr werdet niemals einen alten, kahlköpfigen Spieler heiraten müssen."
  },
  AvgDialog_23359_Content_45 = {
    Text = "Das Mädchen hörte still zu, und ein Lächeln erschien langsam auf ihrem eisigen Gesicht."
  },
  AvgDialog_23359_Content_46 = {
    Text = "Ich war schon immer ein hübsches und beliebtes Kind. Viele Menschen kamen auf mich zu und wollten Freunde sein."
  },
  AvgDialog_23359_Content_47 = {
    Text = "Sie beäugen mich wie Schakale, jeder einzelne darauf erpicht, etwas von mir mit Zinsen zurückzubekommen — genau wie mein Vater es immer sagte."
  },
  AvgDialog_23359_Content_48 = {
    Text = "Also wurde mir früh klar, dass Wunder niemals zu mir kommen würden."
  },
  AvgDialog_23359_Content_49 = {
    Text = "Ich bin nicht dumm, Mr. N. Ihr habt so viele verlockende Begriffe in den Raum geworfen, also..."
  },
  AvgDialog_23359_Content_5 = {
    Text = "Ja, es ist sehr wertvoll. Es hat mich ganze 200 Sterling gekostet."
  },
  AvgDialog_23359_Content_50 = {
    Text = "Was ist der Preis?"
  },
  AvgDialog_23359_Content_51 = {
    Text = "Lentiniën Outskirts\nLamberts Residenz"
  },
  AvgDialog_23359_Content_52 = {
    Text = "Herr Lambert, Sie werden beschuldigt, an dem Mord an Frau Sorel beteiligt gewesen zu sein. Bitte kommen Sie mit uns."
  },
  AvgDialog_23359_Content_53 = {
    Text = "Die Zeit schien schon lange stehengeblieben zu sein. Fahles Tageslicht ergoss sich herab und hüllte die leere Halle in einen weißen Schleier."
  },
  AvgDialog_23359_Content_54 = {
    Text = "Der trostlose Wind bläst unablässig durch die Ritzen des zerbrochenen Fensters und raschelt durch die Rosen und das tote Laub auf dem Boden."
  },
  AvgDialog_23359_Content_55 = {
    Text = "Ähm, endlich seid Ihr da... Ich habe so lange auf Euch gewartet..."
  },
  AvgDialog_23359_Content_56 = {
    Text = "Der hinfällige alte Mann sinkt in den weichen Samtstuhl und schwenkt sanft ein Glas Rotwein."
  },
  AvgDialog_23359_Content_57 = {
    Text = "Wenn ich sage, dass sie nicht von mir getötet wurde, würdet Ihr mir glauben?"
  },
  AvgDialog_23359_Content_58 = {
    Text = "Als alleiniger Begünstigter von Sorels Testament und kürzlich durch Glücksspiel in Schulden versunken, haben Sie das perfekte Tatmotiv."
  },
  AvgDialog_23359_Content_59 = {
    Text = "Darüber hinaus..."
  },
  AvgDialog_23359_Content_6 = {
    Text = "200 Sterling?! Das Jahreseinkommen meines Vaters beträgt nur... Nein, wir müssen es sofort zurückgeben."
  },
  AvgDialog_23359_Content_60 = {
    Text = "Ramona zog den kunstvollen Dolch hervor."
  },
  AvgDialog_23359_Content_61 = {
    Text = "Hier ist, was wir am Tatort gefunden haben: ein kostbarer Import aus dem Fernen Osten."
  },
  AvgDialog_23359_Content_62 = {
    Text = "Wir haben den Verkäufer gefunden, und der Antiquitätenhändler gab zu, dass Mr. Lambert ihn vor zwei Monaten erworben hatte."
  },
  AvgDialog_23359_Content_63 = {
    Text = "Könnten Sie vielleicht erklären, warum Sie es an jenem Tag in die Oper mitgebracht haben?"
  },
  AvgDialog_23359_Content_64 = {
    Text = "Der Grund? Hehehe..."
  },
  AvgDialog_23359_Content_65 = {
    Text = "Das Knarren eines Stuhls dringt an meine Ohren."
  },
  AvgDialog_23359_Content_66 = {
    Text = "Lambert kämpfte sich auf die Beine und ging langsam, mit schmerzerfüllten Schritten auf Ramona zu."
  },
  AvgDialog_23359_Content_67 = {
    Text = "Weil sie es verdient hat zu sterben.\nIch war es, der sie in eine hohe Position erhoben hat, ihr Reichtum, Status und Ruhm gewährte... Ich habe alles hinter den Kulissen inszeniert."
  },
  AvgDialog_23359_Content_68 = {
    Text = "Und sie? Nachdem sie erfolgreich geworden war, hat sie es nicht nur versäumt, es mir zurückzuzahlen, sondern wollte sich auch noch von mir distanzieren."
  },
  AvgDialog_23359_Content_69 = {
    Text = "Sieh dir dieses Haus an... Ich habe alles verpfändet, was ich konnte, und nur ein Haus voller Rosen übrig gelassen."
  },
  AvgDialog_23359_Content_7 = {
    Text = "Du verdienst das Beste, Sorel."
  },
  AvgDialog_23359_Content_70 = {
    Text = [[
Das war die Lieblingsblume meiner Frau, als sie noch lebte.
Nach ihrem Tod ging auch das letzte Band zwischen Sorel und mir verloren.]]
  },
  AvgDialog_23359_Content_71 = {
    Text = "Also beschloss ich, sie zu töten..."
  },
  AvgDialog_23359_Content_72 = {
    Text = "Blütenblätter schweben vom Himmel herab."
  },
  AvgDialog_23359_Content_73 = {
    Text = "Der alte Mann blickte auf, der Großteil seines Gesichts von A-Schleim zerfressen, schwarzer Schleim rann aus seinen Augenwinkeln wie Tränen."
  },
  AvgDialog_23359_Content_74 = {
    Text = "...genauso wie ich entschlossen bin, euch alle zu töten."
  },
  AvgDialog_23359_Content_8 = {
    Text = "In drei Tagen wird Herr Binder zu uns nach Hause kommen. Trag dann dieses Kleid und gib dir Mühe, gut mit ihm auszukommen."
  },
  AvgDialog_23359_Content_9 = {
    Text = "...Dieser arrogante alte Mann? Ich mag ihn nicht."
  },
  AvgDialog_23360_Content_1 = {
    Text = "Gefangene des Schicksals"
  },
  AvgDialog_23360_Content_10 = {
    Text = "<Red:Hehe.>"
  },
  AvgDialog_23360_Content_11 = {
    Text = "<Red:Ich mag {Male=him,Female=her}.>"
  },
  AvgDialog_23360_Content_12 = {
    Text = "Sie scheint Angst vor etwas zu haben."
  },
  AvgDialog_23360_Content_13 = {
    Text = "...Willst du wirklich, dass ich dieses Spiel mit dir spiele?"
  },
  AvgDialog_23360_Content_14 = {
    Text = "Frau Sorel zögerte einen Moment und nickte dann sanft."
  },
  AvgDialog_23360_Content_15 = {
    Text = "<Gray:Zwei Gläser Champagner sollten in Ordnung sein...>"
  },
  AvgDialog_23360_Content_16 = {
    Text = [[
Ich nehme Euren Vorschlag an. Bringen wir es schnell hinter uns.
Wie lautet die erste Frage?]]
  },
  AvgDialog_23360_Content_17 = {Text = "Ugh..."},
  AvgDialog_23360_Content_18 = {
    Text = "Sorel stützte ihr Kinn mit einer Hand ab, ihre schlanken Finger tippten leicht auf ihre Wange."
  },
  AvgDialog_23360_Content_19 = {
    Text = "Erste Frage: Woher wusste der Misaq, dass heute Nacht jemand kommen würde, um mich zu töten?"
  },
  AvgDialog_23360_Content_2 = {
    Text = "Trinken, trinken?!"
  },
  AvgDialog_23360_Content_20 = {
    Text = "Wenn Ihr nicht antworten könnt, darf ich dann berechtigterweise vermuten, dass Ihr ebenfalls in gewissem Maße darin verwickelt seid?"
  },
  AvgDialog_23360_Content_21 = {
    Text = "Das ist keine Frage, die man leichtfertig beantworten kann..."
  },
  AvgDialog_23360_Content_22 = {
    Text = "Ihr nahmt den Champagner vom Tisch und trankt ihn in einem Zug aus."
  },
  AvgDialog_23360_Content_23 = {
    Text = "Unerwartet hat die blassgelbe Flüssigkeit einen leichten und feinen Geschmack, mit einem Hauch von Zitrusaroma."
  },
  AvgDialog_23360_Content_24 = {
    Text = "<Gray:Hmm... Er schmeckt tatsächlich ziemlich gut.>"
  },
  AvgDialog_23360_Content_25 = {
    Text = "Trinkt langsam, Schutzherr. Diese Flasche ist so viel wert wie ein Haus in der Innenstadt von Lentiniën."
  },
  AvgDialog_23360_Content_26 = {
    Text = "Ähm... <Big:Was?!>"
  },
  AvgDialog_23360_Content_27 = {
    Text = "Als Nächstes kommt die zweite Frage. Diese stammt von den Damen aus Lentiniën..."
  },
  AvgDialog_23360_Content_28 = {
    Text = "Sorel schenkt dir ein leichtes Lächeln. Aus irgendeinem Grund hast du ein ungutes Gefühl."
  },
  AvgDialog_23360_Content_29 = {
    Text = "Wer ist die leibliche Mutter der Tochter von LORD Dexter?"
  },
  AvgDialog_23360_Content_3 = {
    Text = "<Gray:Fräulein Doll hat gesagt, ich bin noch nicht alt genug zum Trinken, und während Ermittlungen darf ich auch nicht trinken...>"
  },
  AvgDialog_23360_Content_30 = {
    Text = "Pruuust—!!"
  },
  AvgDialog_23360_Content_31 = {
    Text = "Du spuckst den Wein aus, den du noch nicht heruntergeschluckt hattest. Sorel zieht eine Augenbraue hoch, und Karen wischt sofort den verschütteten Wein vom Tisch."
  },
  AvgDialog_23360_Content_32 = {
    Text = "<SmallShake:Tss tss, selbst ein kleiner Schluck ist Geld! Das reicht, damit ich mir eine neue Halskette bei Harold's Kaufhaus kaufen kann...>"
  },
  AvgDialog_23360_Content_33 = {
    Text = "Ich habe nicht erwartet, dass Frau Sorel an so langweiligen Klatsch interessiert ist. Was für eine Überraschung... Ha, haha."
  },
  AvgDialog_23360_Content_34 = {
    Text = "Hier ein Geheimnis: Wir „Damen der Gesellschaft“ verbringen mindestens die Hälfte unseres Tages mit Klatsch und Tratsch."
  },
  AvgDialog_23360_Content_35 = {
    Text = "Wie, glaubst du, bleibt <Blue:Madame Sorels Salon> sonst am Laufen?"
  },
  AvgDialog_23360_Content_36 = {
    Text = "... vorstellbar."
  },
  AvgDialog_23360_Content_37 = {
    Text = "Lass dich nicht von diesem ganzen Pflegevater–Tochter–Schauspiel täuschen. Laut Insidergerüchten ist die leibliche Mutter des Kindes in Wirklichkeit die Geliebte einer gewissen einflussreichen Persönlichkeit..."
  },
  AvgDialog_23360_Content_38 = {
    Text = [[
Red, red keinen Unsinn.
LORD Dexter ist aufrichtig und hat Selbstachtung. Er ist ganz anders, als die Leute denken...]]
  },
  AvgDialog_23360_Content_39 = {
    Text = "%player%, der Kommunikator war die ganze Zeit an. Ich habe alles gehört."
  },
  AvgDialog_23360_Content_4 = {
    Text = "Entschuldigung, Frau Sorel."
  },
  AvgDialog_23360_Content_40 = {
    Text = "Ich rate dir, dir die Mühe zu sparen; selbst ich weiß nicht, wer meine leibliche Mutter ist."
  },
  AvgDialog_23360_Content_41 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23360_Content_42 = {
    Text = "Du bist dir nicht sicher, ob es am Alkohol liegt, aber plötzlich wird dir ein wenig schwindelig."
  },
  AvgDialog_23360_Content_43 = {
    Text = "Es ist absolut nicht das, was alle denken? Was genau ist es dann?"
  },
  AvgDialog_23360_Content_44 = {
    Text = "Du schüttelst den Kopf und nimmst das Weinglas vom Tisch."
  },
  AvgDialog_23360_Content_45 = {
    Text = "Ist diese Frage wichtig für dich?"
  },
  AvgDialog_23360_Content_46 = {
    Text = "Es spielt keine Rolle, es dient nur dazu, drei Fragen vollzumachen."
  },
  AvgDialog_23360_Content_47 = {
    Text = "<Red:Gut gemacht, Sorel. Als Nächstes...>"
  },
  AvgDialog_23360_Content_48 = {
    Text = "Sorel drückt sanft das Glas vor dir herunter. Aus irgendeinem Grund hast du das Gefühl, als hätten die Muskeln in ihrem Gesicht kurz gezuckt."
  },
  AvgDialog_23360_Content_49 = {
    Text = "Hey Kleines, trink nicht so unbesonnen. Betrachten wir diesen Drink als deinen Beitrag. Was ich wirklich fragen wollte, ist..."
  },
  AvgDialog_23360_Content_5 = {
    Text = "Was wäre, wenn ich Euch sagte, dass ich schon immer wusste, wer mich töten will?"
  },
  AvgDialog_23360_Content_50 = {
    Text = "Kaum hatte sie die Worte ausgesprochen, begann sich Madame Sorels Gesicht plötzlich zu verzerren und zu verschwimmen..."
  },
  AvgDialog_23360_Content_51 = {
    Text = "Und verwandelte sich dann vollständig in ein anderes Aussehen."
  },
  AvgDialog_23360_Content_52 = {
    Text = "Guten Abend, {Male=sir,Female=miss}. Bitte gestatten Sie mir, meine Grüße durch die Worte einer anderen zu übermitteln."
  },
  AvgDialog_23360_Content_53 = {
    Text = "In zehn Minuten wirst du den gesamten Inhalt dieses Gesprächs vollständig vergessen haben, also hab keine Angst, meine Fragen zu beantworten."
  },
  AvgDialog_23360_Content_54 = {
    Text = "Meine Frage ist auch recht einfach..."
  },
  AvgDialog_23360_Content_55 = {
    Text = "Sein Gesicht ist in dichten schwarzen Nebel gehüllt. Du kannst seine Züge nicht erkennen, und doch kommt er dir seltsam vertraut vor."
  },
  AvgDialog_23360_Content_56 = {
    Text = "Es fühlt sich an wie vor sehr langer Zeit. Vielleicht habt ihr euch irgendwo gekreuzt, oder vielleicht stand er in der Ferne und beobachtete dich, lange verweilend."
  },
  AvgDialog_23360_Content_57 = {
    Text = "War dein früherer Name @2?"
  },
  AvgDialog_23360_Content_58 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23360_Content_59 = {
    Text = "Die Welt schien sich im Handumdrehen wie eine Flut zurückzuziehen."
  },
  AvgDialog_23360_Content_6 = {Text = "?!"},
  AvgDialog_23360_Content_60 = {
    Text = "Alle Geräusche verschwanden, und alle Bilder lösten sich auf."
  },
  AvgDialog_23360_Content_61 = {
    Text = "Seine Lippen bewegten sich lautlos, aber du wusstest, dass er deinen <Yellow:ursprünglichen Namen> korrekt ausgesprochen hatte."
  },
  AvgDialog_23360_Content_62 = {
    Text = "%player%? Es ist völlig still bei dir. Was ist los?"
  },
  AvgDialog_23360_Content_63 = {
    Text = "Du öffnest deine ausgetrockneten Lippen, aber kein Laut kommt heraus."
  },
  AvgDialog_23360_Content_64 = {
    Text = "Ein dichtes Summen umschlingt und erregt unaufhörlich die Tiefen deines Bewusstseins und zerrt mit Wahnsinn an deinen Nerven."
  },
  AvgDialog_23360_Content_65 = {
    Text = "<Change>Ich weiß nicht..."
  },
  AvgDialog_23360_Content_66 = {Text = "...?"},
  AvgDialog_23360_Content_67 = {
    Text = "Bleib genau da, %player%. Ich komme jetzt rauf—"
  },
  AvgDialog_23360_Content_68 = {Text = "Bang!"},
  AvgDialog_23360_Content_69 = {
    Text = "Die Lichter im Theater gingen plötzlich aus."
  },
  AvgDialog_23360_Content_7 = {
    Text = "Spielt dieses Spiel mit mir, und ich werde Euch die Antwort verraten."
  },
  AvgDialog_23360_Content_70 = {
    Text = "An der einzigen Lichtquelle vor der Bühne erschien erneut jener vertraute und doch fremde Schatten."
  },
  AvgDialog_23360_Content_71 = {
    Text = "Er hält eine Rose in der Hand, unheimliche Gesänge strömen aus dem sich windenden schwarzen Nebel auf seinem Gesicht."
  },
  AvgDialog_23360_Content_72 = {
    Text = "<RedItalic:Gefangener des Schicksals.>"
  },
  AvgDialog_23360_Content_73 = {
    Text = "<RedItalic:Du verkleidest dich als Apostel des Lichts, um die Massen zu täuschen, und wagst dich in verbotenes Unbekanntes auf der Suche nach der Wahrheit.>"
  },
  AvgDialog_23360_Content_74 = {
    Text = "<RedItalic:Verlorene Erinnerungen wachsen und strömen aus hohlen Augen, deine erbärmliche Zukunft stirbt in der Melodie der Flöte.>"
  },
  AvgDialog_23360_Content_75 = {
    Text = "<RedItalic:Nun befehle ich dir —>"
  },
  AvgDialog_23360_Content_76 = {
    Text = "<Red:Öffne deine Augen.>"
  },
  AvgDialog_23360_Content_8 = {
    Text = [[
Eine Drohung?
Ihr runzeltet die Stirn und wolltet sie abweisen, doch dann fiel Euch ein weiteres Detail auf.]]
  },
  AvgDialog_23360_Content_9 = {
    Text = "Hinter dem spielerischen Geplänkel verbergen sich verengte Pupillen und leicht weiß gewordene Fingerknöchel."
  },
  AvgDialog_23361_Content_1 = {Text = "Trinklied"},
  AvgDialog_23361_Content_10 = {
    Text = "Ah! W–Wer sind Sie? Das ist die Privatloge von Frau Sorel!"
  },
  AvgDialog_23361_Content_11 = {
    Text = "Karen befiehlt Ihnen, sofort zu gehen. Verderben Sie der Dame nicht die Laune... <Big:Autsch!>"
  },
  AvgDialog_23361_Content_12 = {
    Text = "Du schiebst die plappernde Zofe beiseite und näherst dich einer prachtvoll gekleideten Frau."
  },
  AvgDialog_23361_Content_13 = {
    Text = "Gehüllt in feine Seide und Juwelen, schimmert sie wie eine blühende Rose im Licht."
  },
  AvgDialog_23361_Content_14 = {
    Text = "Ein so zerbrechliches, zum Zerdrücken verlockendes Schimmern."
  },
  AvgDialog_23361_Content_15 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23361_Content_16 = {
    Text = "Jetzt ist nicht die Zeit, Schönheiten zu bewundern; wir haben weniger als eine halbe Stunde, %player%."
  },
  AvgDialog_23361_Content_17 = {
    Text = "Huh? Ah...!"
  },
  AvgDialog_23361_Content_18 = {
    Text = "Guten Abend, Frau Sorel. Polizeibehörde Lentiniën, @2 Ermittlungseinsatz, %player%."
  },
  AvgDialog_23361_Content_19 = {
    Text = "@2 Ermittlungsabteilung...?"
  },
  AvgDialog_23361_Content_2 = {
    Text = "Meine Damen und Herren, guten Abend."
  },
  AvgDialog_23361_Content_20 = {
    Text = "Versuchen Sie nicht, mich zu täuschen. Alle in diesen Kreisen wissen, dass die @2 Ermittlungsabteilung nur eine Fassade für Misaq ist, angegliedert an die Polizeibehörde."
  },
  AvgDialog_23361_Content_21 = {
    Text = "Aber Sie kommen mir unbekannt vor... der Neue, den Misaq gerade aufgenommen hat?"
  },
  AvgDialog_23361_Content_22 = {
    Text = "Immer Misaq! Jedes Mal, wenn ihr meine Herrin aufsucht, verheißt es nichts Gutes! Entweder ist jemand gestorben, ein Unglück ist geschehen, oder ihr wollt Geld leihen..."
  },
  AvgDialog_23361_Content_23 = {
    Text = "Sorel hob leicht ihre Wimpern und warf Karen einen scheinbar beiläufigen Blick zu."
  },
  AvgDialog_23361_Content_24 = {
    Text = "Karen, dies ist kein Ort für jedermann. Wie ist {Male=he,Female=she} hereingekommen, hat das etwas mit dir zu tun?"
  },
  AvgDialog_23361_Content_25 = {
    Text = "Ah, ah? Gnädige Frau, was sagt Ihr da! Karens Treue ist so rein wie der <Blue:Cameo>–Rubin auf Eurer Krone!"
  },
  AvgDialog_23361_Content_26 = {
    Text = "<SmallShake:Natürlich, bitte missverstehen Sie das nicht. Es besteht absolut keine Absicht, ihn zu begehren...>"
  },
  AvgDialog_23361_Content_27 = {
    Text = "Kurz gesagt, meine Dame, Karen wird es jetzt für Euch ausgraben — ein treues Herz!"
  },
  AvgDialog_23361_Content_28 = {
    Text = "Shh... Karen. Noch ein Wort, und ich bestrafe dich mit einem Leo-Fang."
  },
  AvgDialog_23361_Content_29 = {
    Text = "Sie erteilte der Dienerin in sanftem Ton einen unbestreitbaren Befehl."
  },
  AvgDialog_23361_Content_3 = {
    Text = "Die Geschichte, die ich heute Abend erzähle, spielt im nebligen Lentiniën."
  },
  AvgDialog_23361_Content_30 = {
    Text = "Was?! E...<Small:Wow!>"
  },
  AvgDialog_23361_Content_31 = {
    Text = "Karen hielt sich verspätet den Mund zu und wagte kein weiteres Wort."
  },
  AvgDialog_23361_Content_32 = {
    Text = "Sorel nimmt einen Schluck Champagner, ihre hellroten Augen beobachten dich vorsichtig."
  },
  AvgDialog_23361_Content_33 = {
    Text = "Es ist fast Zeit für mein Lieblingsstück. Ich möchte es nicht verpassen. Also..."
  },
  AvgDialog_23361_Content_34 = {
    Text = "Du hast eine Minute. Sprich. Was willst du?"
  },
  AvgDialog_23361_Content_35 = {
    Text = "8:40, noch 20 Minuten."
  },
  AvgDialog_23361_Content_36 = {
    Text = [[
Verstanden.
Frau Sorel, bitte folgen Sie mir, um diesen Ort zu verlassen.]]
  },
  AvgDialog_23361_Content_37 = {
    Text = "<Red:Jemand plant, Euch zu ermorden.>"
  },
  AvgDialog_23361_Content_38 = {Text = "?!"},
  AvgDialog_23361_Content_39 = {
    Text = "Während sie sprachen, sickerte unablässig schwarzer Schleim aus dem Boden und der Decke der Loge und verdichtete sich zu sich windenden Massen."
  },
  AvgDialog_23361_Content_4 = {
    Text = "Im Jahre @1 kam ein Mädchen vom Land mit der Kutsche und verwandelte diesen Ort in eine Stadt, die vor Rosen erblühte."
  },
  AvgDialog_23361_Content_40 = {
    Text = "Schluchz, schluchz..."
  },
  AvgDialog_23361_Content_41 = {
    Text = "<Change> Auuuuuu—!!"
  },
  AvgDialog_23361_Content_5 = {
    Text = "Wunderschöne Blumen blühen unaufhörlich in den Ecken der Stadt und werden zur perfekten Nahrung für Geschichten."
  },
  AvgDialog_23361_Content_6 = {
    Text = "Liebe, Verlangen, Hass. Und natürlich, natürlich... da ist auch noch das, was du und ich am meisten lieben..."
  },
  AvgDialog_23361_Content_7 = {
    Text = "<Red:Mord.>"
  },
  AvgDialog_23361_Content_8 = {
    Text = "Und nun genießen Sie bitte die Vorstellung in Stille—"
  },
  AvgDialog_23361_Content_9 = {
    Text = "Du ziehst den dunkelroten Vorhang vor dir zurück."
  },
  AvgDialog_23362_Content_1 = {
    Text = "Kameliendame"
  },
  AvgDialog_23362_Content_10 = {
    Text = "Du hast das Recht abzulehnen. Überlass diese Leute mir."
  },
  AvgDialog_23362_Content_100 = {
    Text = "Dann nutzt Ihr Euer zweites Erwachen, um eine dramatische öffentliche Auferstehung zu inszenieren und Euch von jedem Verdacht zu befreien."
  },
  AvgDialog_23362_Content_101 = {
    Text = "Schließlich wäre niemand so töricht zu glauben, dass eine Tote die Mörderin ist."
  },
  AvgDialog_23362_Content_102 = {
    Text = "Liege ich richtig, Lady Sorel?"
  },
  AvgDialog_23362_Content_103 = {
    Text = "Heh... Eure Schlussfolgerungen sind niedlich. Und wie erklärt Ihr diesen Schatten?"
  },
  AvgDialog_23362_Content_104 = {
    Text = "Er hat vor aller Augen jemanden getötet. Wie wollt Ihr meine Verbindung zu ihm beweisen?"
  },
  AvgDialog_23362_Content_105 = {Text = "Geruch."},
  AvgDialog_23362_Content_106 = {
    Text = "Als Ihr Euch letztes Mal auf mich gestürzt habt, habe ich ihn gerochen. Ihr alle habt denselben Geruch...\n<Red:Den Geruch verwelkender Rosen>."
  },
  AvgDialog_23362_Content_107 = {
    Text = "Ist er nicht tatsächlich eine Existenz wie Euer Avatar?"
  },
  AvgDialog_23362_Content_108 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23362_Content_109 = {
    Text = "Wie von einem Schutzherrn zu erwarten, Euer Geruchssinn ist scharf."
  },
  AvgDialog_23362_Content_11 = {
    Text = "Die Leute da oben?"
  },
  AvgDialog_23362_Content_110 = {
    Text = "Sorel zog den roten Handschuh von ihrer rechten Hand, und sofort breitete sich ein starker Verwesungsgestank aus."
  },
  AvgDialog_23362_Content_111 = {
    Text = "Unter den gezackten, sich kreuzenden Narben und Kratzern erscheinen schwach dunkelrote Buchstaben."
  },
  AvgDialog_23362_Content_112 = {
    Text = "<Red:„ N “>"
  },
  AvgDialog_23362_Content_113 = {
    Text = "Sorel hob langsam ihre Hand bis knapp unter ihre Nase und schnupperte sanft."
  },
  AvgDialog_23362_Content_114 = {
    Text = "Seht Ihr diese Narbe auf meinem Handrücken? Solange sie existiert, bleibt mein Vertrag mit <Yellow:Ihm> in Kraft."
  },
  AvgDialog_23362_Content_115 = {
    Text = "Ich muss weiterhin Konflikte schüren und Chaos stiften, wie Er es verlangt... Die verstorbenen Adligen sind die Opfergaben, die ich Ihm darbringe."
  },
  AvgDialog_23362_Content_116 = {
    Text = "Aber ich bin es bereits leid. Menschen und die meisten Erwecker sehnen sich von Natur aus nach Ordnung; nur Wahnsinnige finden Vergnügen im endlosen Chaos."
  },
  AvgDialog_23362_Content_117 = {
    Text = "Die Strafe für den Bruch dieses Vertrags ist einfach: <Red:Der Tod>."
  },
  AvgDialog_23362_Content_118 = {
    Text = "...Das war also von Anfang an dein eigentliches Ziel."
  },
  AvgDialog_23362_Content_119 = {
    Text = "Sicher. Die sogenannten Adligen, einschließlich meines Vaters, sind lediglich Beilagen.\nMit ihnen umzugehen kostet keine Menschenleben."
  },
  AvgDialog_23362_Content_12 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23362_Content_120 = {
    Text = "Er offenbart sich nie. Tatsächlich hat Er mir schon lange nicht mehr geantwortet."
  },
  AvgDialog_23362_Content_121 = {
    Text = "Unzählige Nächte lang kniete ich weinend nieder und betete, dass Er mich aus dem Vertrag entlassen möge."
  },
  AvgDialog_23362_Content_122 = {
    Text = "Doch ich hörte nichts und sah nichts. Die einzige Antwort war Totenstille."
  },
  AvgDialog_23362_Content_123 = {
    Text = "Also will ich nicht länger warten. Diesmal werde ich diesen Vertrag selbst durchtrennen –"
  },
  AvgDialog_23362_Content_124 = {
    Text = "...selbst um den Preis des Todes."
  },
  AvgDialog_23362_Content_13 = {
    Text = "Verzeihung, das ist etwas, das du im Moment nicht wissen kannst."
  },
  AvgDialog_23362_Content_14 = {
    Text = "Es ist in Ordnung, Miss Puppe."
  },
  AvgDialog_23362_Content_15 = {
    Text = "Ich habe noch einige Zweifel und Theorien. Es wäre am besten, wenn ich sie im Geheimgang überprüfen könnte."
  },
  AvgDialog_23362_Content_16 = {
    Text = "Doll nickte."
  },
  AvgDialog_23362_Content_17 = {
    Text = "Erinnerst du dich an die Informationshändlerin, die du im Geheimgang getroffen hast? Wir haben eine Untersuchung über ihren Lieferanten durchgeführt und eine große Überraschung entdeckt."
  },
  AvgDialog_23362_Content_18 = {
    Text = "Die Identitäten, Profile und Netzwerke dieser verstorbenen Adligen..."
  },
  AvgDialog_23362_Content_19 = {
    Text = "Hier ist der Ermittlungsbericht, der gerade von der Polizeistation zurückgeschickt wurde. Öffne ihn und sieh ihn dir an."
  },
  AvgDialog_23362_Content_2 = {
    Text = "Mythag-Krankenstation"
  },
  AvgDialog_23362_Content_20 = {
    Text = "Du nimmst den Ermittlungsbericht und beginnst, die Seiten durchzublättern."
  },
  AvgDialog_23362_Content_21 = {Text = "?!"},
  AvgDialog_23362_Content_22 = {
    Text = "Also ist es so..."
  },
  AvgDialog_23362_Content_23 = {
    Text = "Was brauchst du, dass ich dort tue?"
  },
  AvgDialog_23362_Content_24 = {
    Text = "Doll reicht dir einen dicken Aktenordner."
  },
  AvgDialog_23362_Content_25 = {
    Text = "<Yellow:Ganz einfach, nur eine Verhandlung.>"
  },
  AvgDialog_23362_Content_26 = {
    Text = "Der dritte künstliche Geheimgang: Covent Theater\nAm Tag der Aufführung von „Der Name der Rosenblume\""
  },
  AvgDialog_23362_Content_27 = {
    Text = "Der prachtvolle Gesang floss wie ein endloser Bach, der sich langsam durch das Theater ergoss."
  },
  AvgDialog_23362_Content_28 = {
    Text = "Das Publikum unten zeigte Erstaunen, wiegte sich sanft zur Melodie der Musik und war bereits im Traum verloren, den die Noten gewoben hatten."
  },
  AvgDialog_23362_Content_29 = {
    Text = "Übrigens, dieses Stück hieß einst „Tod der Rosenblume\""
  },
  AvgDialog_23362_Content_3 = {
    Text = "Ich habe gehört, dass es bei Ramona gut läuft. Wie sieht es bei dir aus? Wie fühlst du dich jetzt?"
  },
  AvgDialog_23362_Content_30 = {
    Text = "Die Protagonistin ist ein Mädchen vom Land, das die Cité auf eigene Faust erkundet. Sie hat nichts außer ihrem jugendlichen und hübschen Gesicht."
  },
  AvgDialog_23362_Content_31 = {
    Text = "Einfach so, wie ich damals war."
  },
  AvgDialog_23362_Content_32 = {
    Text = "Die gnädige Frau ist eine Prinzessin im Exil. Wie könnte sich ein Mädchen vom Land wie ich mit Euch vergleichen!"
  },
  AvgDialog_23362_Content_33 = {
    Text = "Heh... Die sogenannte fremde Prinzessin ist nichts als eine Fassade. Ich bin ein waschechtes Mädchen vom Land aus Konstant."
  },
  AvgDialog_23362_Content_34 = {
    Text = "Ah... <Big:Ah!>"
  },
  AvgDialog_23362_Content_35 = {
    Text = "<Gray:Ich kann nicht glauben, dass die gnädige Frau mir gerade so ein bedeutendes Geheimnis verraten hat!>"
  },
  AvgDialog_23362_Content_36 = {
    Text = "<Gray:Könnte es sein, dass ich die Einladung diesem lockigen Kerl gegeben habe, und die gnädige Frau hat es herausgefunden und will mich zum Schweigen bringen...>"
  },
  AvgDialog_23362_Content_37 = {
    Text = "„Rosenblumes Tod\" war mein Lieblingsstück, als ich ein Kind war."
  },
  AvgDialog_23362_Content_38 = {
    Text = "Freunde besuchen, von einer Krankheit genesen und einkaufen gehen..."
  },
  AvgDialog_23362_Content_39 = {
    Text = "Ich habe mir viele Ausreden einfallen lassen, nur um vor dem Theater zu stehen und fünf Minuten lang zuzuhören."
  },
  AvgDialog_23362_Content_4 = {
    Text = "Ich fühle mich viel besser."
  },
  AvgDialog_23362_Content_40 = {
    Text = "Ich bin einfach zu beschäftigt. Klavier, Stickerei und Etikette...\nEs gibt noch jede Fertigkeit zu erlernen, die den Adligen gefällt."
  },
  AvgDialog_23362_Content_41 = {
    Text = "Die Eleganz der gnädigen Frau übertrifft sogar die der königlichen Prinzessin! Ist das nicht, was das Sprichwort sagt, äh, „Der frühe Vogel fängt den Wurm...\""
  },
  AvgDialog_23362_Content_42 = {
    Text = "Ah, nein, Gelegenheiten gibt es nur für diejenigen, die vorbereitet sind!"
  },
  AvgDialog_23362_Content_43 = {
    Text = "<Gray:Ich bin so ein Dummkopf. Heute Nacht könnte mein Ende sein, heh...>"
  },
  AvgDialog_23362_Content_44 = {
    Text = "Ich habe die Oper später stückweise zu Ende gehört, aber das Ende hat mir nicht gefallen."
  },
  AvgDialog_23362_Content_45 = {
    Text = "Dieses Mädchen vom Land hat sich erfolgreich in die Seites Oberschicht eingeschlichen, verliebte sich in einen unfähigen Adligen und starb letztendlich seinetwegen."
  },
  AvgDialog_23362_Content_46 = {
    Text = "So ein trauriges Ende... Karen mag es auch nicht. Karen hasst Tragödien!"
  },
  AvgDialog_23362_Content_47 = {
    Text = "Ja, niemand mag Tragödien."
  },
  AvgDialog_23362_Content_48 = {
    Text = "Nachdem ich das Theater gekauft hatte, war das Erste, was ich tat, den Titel und das Ende von „Rosenblumes Tod\" zu ändern."
  },
  AvgDialog_23362_Content_49 = {
    Text = "Ich kann endlich tun, was ich will.\nOder so <Yellow:dachte> ich, dass ich endlich tun könnte, was mir gefällt."
  },
  AvgDialog_23362_Content_5 = {
    Text = "Das ist gut. Es scheint, als wäre Winkles medizinische Technik-Bastelei doch einigermaßen nützlich."
  },
  AvgDialog_23362_Content_50 = {
    Text = "Sorel starrte verzückt auf die goldene Flüssigkeit in ihrem Glas und beobachtete, wie die Bläschen vom Boden aufsprudelten."
  },
  AvgDialog_23362_Content_51 = {
    Text = "Reichtum, Ruhm, Wissen... Die Menschen streben danach, weil sie, sobald sie es besitzen, Freiheit erlangen."
  },
  AvgDialog_23362_Content_52 = {
    Text = "Die Freiheit, das Ende einer Oper zu ändern, die einem nicht gefällt, oder die Freiheit, einen geliebten Kamee-Rubin zu kaufen."
  },
  AvgDialog_23362_Content_53 = {
    Text = "Menschen sind einfach so simple Geschöpfe."
  },
  AvgDialog_23362_Content_54 = {
    Text = "Gnädige Frau, warum bringen Sie das so plötzlich zur Sprache? Das ist ziemlich schwere Kost, haha..."
  },
  AvgDialog_23362_Content_55 = {
    Text = "Du warst schon immer ein kluges Kind. Auch ohne mich wirst du bestens zurechtkommen."
  },
  AvgDialog_23362_Content_56 = {
    Text = "Sorel streichelte Karen sanft über den Kopf."
  },
  AvgDialog_23362_Content_57 = {
    Text = "Herrin, Gebieterin..."
  },
  AvgDialog_23362_Content_58 = {
    Text = "Ihr sagt das also, weil Ihr vorhabt, Karen zu verlassen..."
  },
  AvgDialog_23362_Content_59 = {
    Text = "Niemand wird dich verlassen, Karen. Du warst schon immer frei."
  },
  AvgDialog_23362_Content_6 = {
    Text = "Als Nächstes werde ich nicht um den heißen Brei reden. %player%, du musst dich möglicherweise darauf vorbereiten, erneut das künstliche Labyrinth zu betreten."
  },
  AvgDialog_23362_Content_60 = {Text = "Zisch..."},
  AvgDialog_23362_Content_61 = {
    Text = "Ein schwarzer Schatten erhebt sich allmählich in der Ecke und gleitet lautlos auf Sorels Rücken zu."
  },
  AvgDialog_23362_Content_62 = {
    Text = "Sorel lauschte aufmerksam dem melodischen Gesang von unterhalb der Bühne, scheinbar unbeeindruckt von dem Tumult hinter ihr."
  },
  AvgDialog_23362_Content_63 = {Text = "Zisch..."},
  AvgDialog_23362_Content_64 = {
    Text = "Das raschelnde Geräusch wurde allmählich schwächer, und der Schatten bewegte sich nicht mehr."
  },
  AvgDialog_23362_Content_65 = {Text = "Hmm...?"},
  AvgDialog_23362_Content_66 = {
    Text = "Sorel drehte sich überrascht um."
  },
  AvgDialog_23362_Content_67 = {
    Text = "Guten Abend, Frau Sorel. Es scheint, als hätten Sie etwas verloren?"
  },
  AvgDialog_23362_Content_68 = {
    Text = "<Change>Meine Lady..."
  },
  AvgDialog_23362_Content_69 = {
    Text = "Der Schatten in deiner Hand fühlte sich an wie ein Stück Lumpen, sanft vor Sorel geworfen."
  },
  AvgDialog_23362_Content_7 = {Text = "Was...?!"},
  AvgDialog_23362_Content_70 = {
    Text = "Diesen Kerl zu fangen war nicht einfach. Dank unserer letzten Begegnung habe ich endlich seine Kampfmuster durchschaut."
  },
  AvgDialog_23362_Content_71 = {
    Text = "<Red:Ich bin zurück...>"
  },
  AvgDialog_23362_Content_72 = {
    Text = "Sorel würdigte den Schatten zu ihren Füßen keines Blickes. Sie starrte dich eindringlich an, ihr Ausdruck ernst."
  },
  AvgDialog_23362_Content_73 = {
    Text = "Schon wieder du... Warum bist du zurückgekehrt? War die Lektion aus dem letzten Geheimgang nicht genug für dich?"
  },
  AvgDialog_23362_Content_74 = {
    Text = "<Gray:Fräulein Dolls Vermutung war richtig; sie erkannte, dass sie sich in einem Geheimgang befand.>"
  },
  AvgDialog_23362_Content_75 = {
    Text = "Ich wollte nur ein paar Dinge bestätigen."
  },
  AvgDialog_23362_Content_76 = {
    Text = "Du reißt der schattenhaften Gestalt blitzschnell die Maske vom Gesicht."
  },
  AvgDialog_23362_Content_77 = {
    Text = "Im nächsten Moment löste sich der Schatten auf wie Tinte, die sich in Wasser auflöst."
  },
  AvgDialog_23362_Content_78 = {
    Text = "Eine einzelne tiefrote Rose liegt still zwischen dir und Sorel."
  },
  AvgDialog_23362_Content_79 = {
    Text = "Die weißen Eier auf den Blütenblättern wanden sich sanft, krochen langsam auf Sorels Rock und verschmolzen mit ihr."
  },
  AvgDialog_23362_Content_8 = {
    Text = "Doll runzelte die Stirn und berührte instinktiv die Glasapparatur, die ein frisches Gehirn enthielt."
  },
  AvgDialog_23362_Content_80 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23362_Content_81 = {
    Text = "Spiel vorbei, Frau Sorel."
  },
  AvgDialog_23362_Content_82 = {
    Text = "<Yellow:Drittes Ermittlungsprotokoll zum künstlichen Labyrinth>\n\n■Geheimgang–ID: M–B04–003\n■Errichtungszeit: n. S. 315, Juni @1, 20:00–21:00 Uhr (Der Tag von Sorels Tod).\n■Errichtungsort: Covent–Theater"
  },
  AvgDialog_23362_Content_83 = {
    Text = "\n■ Bereichsinhaber: Sorel·@2.\n■ Bereichsinfiltrator: %player%. \n\n■ Infiltrationsziel: <Yellow:Decken Sie Sorels Verschwörung auf und führen Sie \"notwendige\" Verhandlungen.>"
  },
  AvgDialog_23362_Content_84 = {
    Text = "Du schon wieder! Frau Sorel, überlass diesen Kerl Karen..."
  },
  AvgDialog_23362_Content_85 = {
    Text = "Sorel schüttelte den Kopf."
  },
  AvgDialog_23362_Content_86 = {
    Text = "Bleib ruhig, Karen."
  },
  AvgDialog_23362_Content_87 = {
    Text = "%player%, du bist hereingestürmt, nur um mir das hier zu zeigen?"
  },
  AvgDialog_23362_Content_88 = {
    Text = "Frau Sorel, die immer Pomp mochte, kam an dem Tag ihres Todes, nur begleitet von ihrer persönlichen Dienerin, um dem Spiel zuzuhören."
  },
  AvgDialog_23362_Content_89 = {
    Text = "Was soll das heißen? Ist es etwa falsch, wenn die Herrin und ich in Ruhe der Musik lauschen?!"
  },
  AvgDialog_23362_Content_9 = {
    Text = "Das ist nicht meine Entscheidung. Wenn möglich, hoffe ich, dass du brav hier bleiben kannst, bis du vollständig genesen bist."
  },
  AvgDialog_23362_Content_90 = {
    Text = "Keine Sorge, Fräulein Karen. Erinnert Ihr Euch an die Händler in der Lincoln High Street, die Informationen über Sorels Aufenthaltsort verkauft haben?"
  },
  AvgDialog_23362_Content_91 = {
    Text = "Wir haben ermittelt. <Yellow:Die Informationen, die sie hatten, wurden von Euch weitergegeben.>"
  },
  AvgDialog_23362_Content_92 = {
    Text = "Den Verkauf von Informationen über den Arbeitgeber ist ein schweres Vergehen. Ich nehme an, Ihr hattet die Erlaubnis Eurer Herrin."
  },
  AvgDialog_23362_Content_93 = {Text = "!!"},
  AvgDialog_23362_Content_94 = {
    Text = "<Shake:N-Nein...> Es war Karen selbst, die etwas zusätzliches Geld verdienen wollte. Es hat nichts mit Frau Sorel zu tun!"
  },
  AvgDialog_23362_Content_95 = {
    Text = "Ihr könnt meine Herrin nicht so falsch beschuldigen!"
  },
  AvgDialog_23362_Content_96 = {
    Text = "Ohne Karens Proteste zu beachten, drehst du dich um, um Frau Sorel anzusehen."
  },
  AvgDialog_23362_Content_97 = {
    Text = "Was die verstorbenen Adligen betrifft, so hatten fast alle von ihnen Konflikte mit Euch in politischer und geschäftlicher Hinsicht.\nDarf ich vernünftigerweise schlussfolgern..."
  },
  AvgDialog_23362_Content_98 = {
    Text = "<Yellow:Ihr habt Euren eigenen Tod inszeniert und ihn genutzt, um alle Hindernisse zu beseitigen, einschließlich Eures Vaters.>"
  },
  AvgDialog_23362_Content_99 = {
    Text = "Herrn Lambert öffentlich als alleinigen Begünstigten des Testaments zu benennen, diente lediglich dazu, ihn zu Risiken zu verleiten.\nSelbst wenn er scheiterte, würden die Waffe und das Motiv dennoch die Aufmerksamkeit der Polizei auf sich ziehen."
  },
  AvgDialog_23363_Content_1 = {
    Text = "Maskierte Harmonie"
  },
  AvgDialog_23363_Content_10 = {
    Text = "Verstanden. Im zweiten Stock ist derzeit alles normal."
  },
  AvgDialog_23363_Content_11 = {
    Text = "Es sind noch etwa zwanzig Minuten bis zur Aufführung... Da ich nichts anderes zu tun habe, werde ich zuerst Mrs. Sorel suchen."
  },
  AvgDialog_23363_Content_12 = {
    Text = "In Ordnung, sei vorsichtig. Möge der Silberschlüssel deinen Weg weisen."
  },
  AvgDialog_23363_Content_13 = {
    Text = "Dasselbe Stück, derselbe Korridor."
  },
  AvgDialog_23363_Content_14 = {
    Text = "Geschickt ziehst du den Vorhang der luxuriösen Privatloge zurück."
  },
  AvgDialog_23363_Content_15 = {
    Text = "Mit dem reichen Aroma von Wein und dem Klirren von Schmuck fällt dir plötzlich ein weicher Gegenstand in die Arme."
  },
  AvgDialog_23363_Content_16 = {
    Text = "Endlich bist du da. Ich habe so lange auf dich gewartet..."
  },
  AvgDialog_23363_Content_17 = {
    Text = "Sorel schlingt liebevoll ihre Arme um dich, ihr warmer Atem lässt dein Gesicht erröten."
  },
  AvgDialog_23363_Content_18 = {
    Text = "<Shake:Moment, auf mich gewartet?>"
  },
  AvgDialog_23363_Content_19 = {
    Text = "Also, wo ist die Besprechung... Moment, sind Sie nicht Frau Bernard?"
  },
  AvgDialog_23363_Content_2 = {
    Text = "Zweites künstliches Labyrinth: Covent-Theater\nDer Tag von Sorels Tod"
  },
  AvgDialog_23363_Content_20 = {
    Text = "Hüstel. Polizeibehörde Lentiniën, @2 Ermittlungseinsatz-Abteilung, %player%."
  },
  AvgDialog_23363_Content_21 = {
    Text = "Versuch nicht, mich hinters Licht zu führen.\nAlle Eingeweihten wissen, dass die @2 Ermittlungseinsatz-Abteilung nur eine Fassade für Misaq bei der Polizei ist～"
  },
  AvgDialog_23363_Content_22 = {
    Text = "Hoppla, habe ich dein Geheimnis verraten...? Entschuldigung, ich glaube, ich habe etwas zu viel getrunken."
  },
  AvgDialog_23363_Content_23 = {
    Text = "Sagte Sorel und berührte ihre rosigen Wangen."
  },
  AvgDialog_23363_Content_24 = {
    Text = "<Gray:Warum trinkt sie...? Beim letzten Mal war sie völlig nüchtern.>"
  },
  AvgDialog_23363_Content_25 = {
    Text = "Das ist er! Gnädige Frau, dieser Kerl ist ein Räuber, {Male=he,Female=she} hat Karens Einladung gestohlen!"
  },
  AvgDialog_23363_Content_26 = {
    Text = "Wurden nicht alle Einladungen verschickt? Warum sind noch welche übrig?"
  },
  AvgDialog_23363_Content_27 = {Text = "!!"},
  AvgDialog_23363_Content_28 = {
    Text = "<Shake:Äh, eigentlich... Also, das ist...>"
  },
  AvgDialog_23363_Content_29 = {
    Text = "Karen stotterte wie eine Maschine, die sich verklemmt hatte."
  },
  AvgDialog_23363_Content_3 = {
    Text = "<Yellow:Ermittlungsprotokoll zum zweiten künstlichen Labyrinth II>\n\n■Labyrinth-ID: M-B04-002\n■Einrichtungszeit: Holozän 315, 1. Juni, 20:00–21:00 Uhr (Der Tag von Sorels Tod).\n■Einrichtungsort: Covent-Theater"
  },
  AvgDialog_23363_Content_30 = {
    Text = "Entschuldigt die Peinlichkeit, {Male=Mr.,Female=Miss} %player%.\nMeine Zofe meint es nicht böse, sie ist nur ein wenig einfältig."
  },
  AvgDialog_23363_Content_31 = {
    Text = "Heute ist ein Tag, der gefeiert werden muss! Das Theater, in das ich investiert habe, führt mein Lieblingsstück auf."
  },
  AvgDialog_23363_Content_32 = {
    Text = "Jemanden zu dieser Zeit schicken, machen diese alten Knacker bei Misaq das absichtlich?"
  },
  AvgDialog_23363_Content_33 = {
    Text = "Verzeihen Sie die Störung, Frau Sorel. Wir haben Geheimdienstinformationen erhalten, die darauf hindeuten, dass heute Nacht jemand versuchen wird, Sie zu ermorden."
  },
  AvgDialog_23363_Content_34 = {
    Text = "Hier ist es nicht sicher. Bitte folgen Sie mir."
  },
  AvgDialog_23363_Content_35 = {
    Text = "Ich weigere mich."
  },
  AvgDialog_23363_Content_36 = {Text = "...?"},
  AvgDialog_23363_Content_37 = {
    Text = "Sorel nippte leicht am Champagner in ihrem Glas, ließ ihre langen Wimpern flattern und zwinkerte dir freundlich zu."
  },
  AvgDialog_23363_Content_38 = {
    Text = "Du wurdest geschickt, um mich zu beschützen, richtig? Da ich bereits einen kleinen Ritter habe, warum sollte ich gehen?"
  },
  AvgDialog_23363_Content_39 = {
    Text = "Leider ist die Realität nicht so schön wie ein Bilderbuch. Ein einsamer Ritter kann die Prinzessin nicht retten; er kann ihr nur bei der Flucht helfen."
  },
  AvgDialog_23363_Content_4 = {
    Text = "■Bereichsinhaber: Sorel·@2\n■Bereichs-Eindringlinge: %player%, Ramona\n\n■Ziel: <Yellow:Basierend auf den Ergebnissen des ersten Bereichseindringens, finde die Quelle der Silber-Schwankung im ersten Stock>"
  },
  AvgDialog_23363_Content_40 = {
    Text = "Fliehen... Aber wohin? Irgendwohin, wo die Bösen uns nicht finden können?"
  },
  AvgDialog_23363_Content_41 = {
    Text = "Man kann es so sehen..."
  },
  AvgDialog_23363_Content_42 = {
    Text = "Pff. Gibt es wirklich einen Ort auf dieser Welt, wo böse Menschen nicht zu finden sind? So etwas habe ich noch nie gesehen."
  },
  AvgDialog_23363_Content_43 = {
    Text = "Auf 10:30 Uhr schleicht sich ein Mann heran. Schnell zum rechten Ausgang; wir stellen ihm gemeinsam eine Falle."
  },
  AvgDialog_23363_Content_44 = {Text = "?!"},
  AvgDialog_23363_Content_45 = {
    Text = "Verzeihen Sie, Frau Sorel. Ich bin gleich zurück."
  },
  AvgDialog_23363_Content_5 = {
    Text = "Gut, diesmal waren wir vorbereitet, haben Karens Badewasser ausgewichen und es geschafft, ihr zwei Einladungen abzuluchsen."
  },
  AvgDialog_23363_Content_6 = {
    Text = "Das ist wirklich befriedigend!"
  },
  AvgDialog_23363_Content_7 = {
    Text = "Ich muss sagen, dein flinkes Ausweichen hat bei mir einen tiefen Eindruck hinterlassen."
  },
  AvgDialog_23363_Content_8 = {
    Text = "Ähm, kommen wir zurück zum eigentlichen Thema. Irgendwelche Störungen im ersten Stock?"
  },
  AvgDialog_23363_Content_9 = {
    Text = "Vorerst sicher. Beim letzten Mal im Geheimgang gab es gedämpfte Silberkern-Aktivität in der Zehn-Uhr-Richtung. Diesmal werde ich sie im Auge behalten."
  },
  AvgDialog_23364_Content_1 = {
    Text = "Zweites künstliches Labyrinth: Covent–Theater\nFlur im zweiten Stock"
  },
  AvgDialog_23364_Content_10 = {
    Text = "Gut. Die Eroberungsoperation des zweiten künstlichen Labyrinths beginnt jetzt!"
  },
  AvgDialog_23364_Content_11 = {
    Text = "Du dehntest deine Glieder und stürmtest flink auf den Mann zu."
  },
  AvgDialog_23364_Content_2 = {
    Text = "Sei vorsichtig. Er ist gleich um die Ecke."
  },
  AvgDialog_23364_Content_3 = {
    Text = "<Small:Pst... Nicht sprechen. Ich sehe ihn.>"
  },
  AvgDialog_23364_Content_4 = {
    Text = "Ein Mann verbirgt sich unweit der Loge und verschmilzt beinahe mit den Schatten hinter ihm. Sein schweres, träges Atmen verrät, dass er ein älterer Mann ist."
  },
  AvgDialog_23364_Content_5 = {
    Text = "Kaum hattest du zu Ende gesprochen, wand sich der Schatten kurz und kaum merklich."
  },
  AvgDialog_23364_Content_6 = {
    Text = "Wer ist da?!"
  },
  AvgDialog_23364_Content_7 = {
    Text = "Du warst mindestens 30 Fuß von ihm entfernt, und trotzdem wurdest du entdeckt."
  },
  AvgDialog_23364_Content_8 = {
    Text = "Ziemlich aufmerksam, das erspart mir die Begrüßung. Ramona, bist du bereit?"
  },
  AvgDialog_23364_Content_9 = {
    Text = "Immer kampfbereit."
  },
  AvgDialog_23365_Content_1 = {Text = "Hmm—!!"},
  AvgDialog_23365_Content_10 = {
    Text = "Was ist das—"
  },
  AvgDialog_23365_Content_11 = {
    Text = "Als ich wieder zu Sinnen kam, war niemand mehr zu sehen."
  },
  AvgDialog_23365_Content_12 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23365_Content_13 = {
    Text = "Dieser Kerl ist nicht der maskierte Schatten. Es könnte eine List des Feindes sein."
  },
  AvgDialog_23365_Content_14 = {
    Text = "Ich verfolge ihn. Überprüf schnell Sorels Loge."
  },
  AvgDialog_23365_Content_15 = {
    Text = "Verstanden. Bleib in Kontakt."
  },
  AvgDialog_23365_Content_16 = {
    Text = "Nachdem Ramona eilig gegangen war, hobst du den Gegenstand auf, den der Mann gerade geworfen hatte."
  },
  AvgDialog_23365_Content_17 = {
    Text = "Dies ist ein kunstvoll gearbeiteter und scharfer Dolch mit filigranen Schnitzereien am Griff, der recht teuer aussieht."
  },
  AvgDialog_23365_Content_18 = {
    Text = "Glaubt er wirklich, er kann Frau Sorel mit diesem Ding töten?"
  },
  AvgDialog_23365_Content_19 = {
    Text = "Außerdem sind seine Bewegungen für eine ältere Person erstaunlich flink... Ein Auflösungspatient?"
  },
  AvgDialog_23365_Content_2 = {
    Text = "Der alte Mann wird von dir leicht zu Boden geworfen. Er hebt schnell die Hand und bedeckt sein Gesicht fest mit seinem Ärmel."
  },
  AvgDialog_23365_Content_20 = {
    Text = "Wenn es ein mutierter Auflösungspatient ist, hätte er Sorel töten können."
  },
  AvgDialog_23365_Content_21 = {
    Text = "Du kratzt dir verwirrt den Kopf."
  },
  AvgDialog_23365_Content_23 = {
    Text = "Die Vorstellung beginnt gleich. Wie auch immer, gehen wir erst mal zurück."
  },
  AvgDialog_23365_Content_3 = {
    Text = "Also gut, wer bist du? Warum hast du Frau Sorel angegriffen?"
  },
  AvgDialog_23365_Content_4 = {
    Text = "Mich verhören? Heh... Was glaubst du, wer du bist? Sag mir, wer ist dein Vorgesetzter?"
  },
  AvgDialog_23365_Content_5 = {
    Text = "François oder Olivier·@2? Ich muss mit ihm... *husten* sprechen."
  },
  AvgDialog_23365_Content_6 = {Text = "?!"},
  AvgDialog_23365_Content_7 = {
    Text = "Der Mann nannte ohne zu zögern zwei hochrangige Beamte der Polizeistation, sein Ton erfüllt von kaum verhohlener Arroganz und Lässigkeit."
  },
  AvgDialog_23365_Content_8 = {
    Text = "Er hob plötzlich die Hand und warf heftig einen leuchtenden Gegenstand."
  },
  AvgDialog_23366_Content_1 = {
    Text = "Erster künstlicher Bereich: Lincoln High Street\nDer Tag von Sorels Tod"
  },
  AvgDialog_23366_Content_10 = {
    Text = "Freundliche Erinnerung: Es ist bereits 18:15 Uhr, und wir müssen noch herausfinden, wie wir eine Einladung bekommen, um das Opernhaus zu betreten."
  },
  AvgDialog_23366_Content_11 = {
    Text = "Genauer gesagt, eine Einladung zur heutigen Premierenoper <Blue:„Der Name der Rosenblume\">"
  },
  AvgDialog_23366_Content_12 = {
    Text = "Du schenkst Ramona ein selbstbewusstes Lächeln."
  },
  AvgDialog_23366_Content_13 = {
    Text = "Keine Sorge. Ich habe bereits vorausgekundschaftet; die Einladung zu beschaffen ist einfach."
  },
  AvgDialog_23366_Content_14 = {
    Text = "Folge mir einfach, Ramona."
  },
  AvgDialog_23366_Content_2 = {Text = "Hmm...!"},
  AvgDialog_23366_Content_3 = {
    Text = "Husten... Husten..."
  },
  AvgDialog_23366_Content_4 = {
    Text = "Das geschäftige Stadtbild entfaltet sich vor dir. Als die Nacht hereinbricht, gehen die Straßenlaternen eine nach der anderen an und beleuchten die schillernden Ladenschilder entlang der Straßen."
  },
  AvgDialog_23366_Content_5 = {
    Text = "Menschen eilen durch die Straßen, ihr Lachen vermischt sich mit den Geräuschen der Kutschen zu einer fröhlichen Symphonie."
  },
  AvgDialog_23366_Content_6 = {
    Text = "Es ist lange her, seit ich zuletzt im Westbezirk war, und er hat sich kein bisschen verändert!"
  },
  AvgDialog_23366_Content_7 = {
    Text = "Ich denke, wir können die Lincoln-Straße entlanggehen. Dort gibt es eine Süßwarenhandlung mit den besten Cupcakes der Welt!"
  },
  AvgDialog_23366_Content_8 = {
    Text = "Ich frage mich, wie die kleinen Kuchen im künstlichen Labyrinth schmecken..."
  },
  AvgDialog_23366_Content_9 = {
    Text = "Ramona hob ihr Handgelenk und überprüfte ausdruckslos die Uhrzeit."
  },
  AvgDialog_23367_Content_1 = {
    Text = "Gefallenes Urteil"
  },
  AvgDialog_23367_Content_10 = {
    Text = "Heh, diese Leute haben immer noch ganz schön Appetit.\nWenn ich allem zustimmen würde, wären dann nicht all die Jahre der Mühe umsonst gewesen?"
  },
  AvgDialog_23367_Content_11 = {
    Text = "Wie soll das denn gehen?"
  },
  AvgDialog_23367_Content_12 = {
    Text = "Wenn Ihr ablehnt, wird Misaq die zweite Erweckung beenden und Eure Taten gemäß den Zusatzbedingungen der Welt verkünden."
  },
  AvgDialog_23367_Content_13 = {
    Text = "In der Tat fürchte ich, dass Sie keine andere Wahl haben, Mrs. Sorel."
  },
  AvgDialog_23367_Content_14 = {
    Text = "Keine andere Wahl? Ihr kennt mich noch immer nicht gut genug, Schutzherr."
  },
  AvgDialog_23367_Content_15 = {
    Text = "Der Welt verkünden... Soll ich die Existenz der Auflösung oder der Erweckten Körper enthüllen?"
  },
  AvgDialog_23367_Content_16 = {
    Text = "Wie wäre es, wenn Ihr eines davon auswählt?"
  },
  AvgDialog_23367_Content_17 = {
    Text = "Mit einem Lächeln auf den Lippen, aber eisiger Kälte in den Augen – Ihr wisst, dass Ihr diese Dame bereits beleidigt habt."
  },
  AvgDialog_23367_Content_18 = {
    Text = "Glücklicherweise wurde ihre Reaktion von den hohen Tieren vorausberechnet, also bleibt Euch nichts anderes übrig, als stur die vorbereitete Rede zu verwenden."
  },
  AvgDialog_23367_Content_19 = {
    Text = "Verzeiht, Frau Sorel. Bitte betrachtet diese Verhandlung nicht als Drohung; es ist eine für beide Seiten vorteilhafte Zusammenarbeit. Die Oberen meinen es absolut aufrichtig..."
  },
  AvgDialog_23367_Content_2 = {
    Text = "Ein Vertrag... Ich verstehe.\nEr verleiht dir besondere Fähigkeiten, und im Gegenzug musst du für ihn arbeiten."
  },
  AvgDialog_23367_Content_20 = {
    Text = "<Red:So langweilig, mir fallen die Augen zu.>"
  },
  AvgDialog_23367_Content_21 = {
    Text = "Die Musik hatte irgendwann aufgehört, und das gesamte Opernhaus war still wie ein gewaltiges Grab."
  },
  AvgDialog_23367_Content_22 = {
    Text = "Zack Schauspieler, Gäste und selbst Karen scheinen erstarrt zu sein und starren Euch und Sorel mit leeren Augen an."
  },
  AvgDialog_23367_Content_23 = {Text = "...Äh?"},
  AvgDialog_23367_Content_24 = {
    Text = "Sorel stützte ihre Wange auf die Hand, betrachtete die starren Gesichter und seufzte leise."
  },
  AvgDialog_23367_Content_25 = {
    Text = "Von dem Moment an, als Ihr wieder vor mir standet, wusste ich, dass es so enden würde."
  },
  AvgDialog_23367_Content_26 = {
    Text = "Das Schlimmste ist eingetreten...\nIhr habt vermutlich keine Ahnung von der Präsenz, die Ihr herbeigerufen habt, Schutzherr."
  },
  AvgDialog_23367_Content_27 = {
    Text = "Ihre Stimme war leise, als fürchte sie, jene Präsenz zu stören."
  },
  AvgDialog_23367_Content_28 = {
    Text = "Ein Schatten aus dem letzten Geheimgang blitzt durch Euren Verstand."
  },
  AvgDialog_23367_Content_29 = {
    Text = "Wollt Ihr sagen, es existiert...?!"
  },
  AvgDialog_23367_Content_3 = {
    Text = "Kein Wunder, dass dein Avatar Ihm so ähnlich sieht, da du Seine Macht geliehen hast."
  },
  AvgDialog_23367_Content_30 = {
    Text = "Misaq zu benutzen, um mich in Schach zu halten – diese Leute da oben sind klug, aber sie haben eines übersehen – sie haben Eure Existenz nicht einkalkuliert."
  },
  AvgDialog_23367_Content_31 = {Text = "...Ich?"},
  AvgDialog_23367_Content_32 = {
    Text = "Klopf, klopf. Klopf, klopf."
  },
  AvgDialog_23367_Content_33 = {
    Text = "Leise Trommelschläge hallen aus der Ferne wider, gefolgt vom schwachen und monotonen Klang einer Flöte."
  },
  AvgDialog_23367_Content_34 = {
    Text = "Dann hörst du den Gesang."
  },
  AvgDialog_23367_Content_35 = {
    Text = "<RedItalic:Verräter des Schicksals.>"
  },
  AvgDialog_23367_Content_36 = {
    Text = "Aus der Dunkelheit tritt eine Gestalt ins Rampenlicht. Nebel umschwebt ihr Gesicht wie dunkle Tentakel, die sich langsam zum Klang der Flöte entfalten."
  },
  AvgDialog_23367_Content_37 = {
    Text = "Sein Gesang ist heiser und profan, durchzogen vom beständigen Puls endloser Gezeiten."
  },
  AvgDialog_23367_Content_38 = {
    Text = "<RedItalic:Du erblühst im verwesenden Schlamm, erklimmst die hochragenden grünen Ranken und trampelst auf ebenso unbedeutenden Wesen herum.>"
  },
  AvgDialog_23367_Content_39 = {
    Text = "<RedItalic:Deine Begierden kennen keine Grenzen, und deine Seele ist längst verfault.>"
  },
  AvgDialog_23367_Content_4 = {
    Text = "Das geht dich nichts an, kleiner Ermittler."
  },
  AvgDialog_23367_Content_40 = {
    Text = "<RedItalic:In deinem morbiden Rosengarten war ich Zeuge. Jenes stille Gemetzel...>"
  },
  AvgDialog_23367_Content_41 = {
    Text = "<Red:Steht kurz bevor.>"
  },
  AvgDialog_23367_Content_5 = {
    Text = "Nun hast du die Wahrheit, die du wolltest. Was wirst du als Nächstes tun?"
  },
  AvgDialog_23367_Content_6 = {
    Text = "Um ehrlich zu sein, kann ich wirklich nicht viel tun."
  },
  AvgDialog_23367_Content_7 = {
    Text = "Ich folge lediglich Anweisungen, um mit Ihnen zu verhandeln. Hier sind die von den Vorgesetzten entworfenen Bedingungen. Bitte sehen Sie sie durch, Madame."
  },
  AvgDialog_23367_Content_8 = {
    Text = "Du übergibst die vorbereiteten Dokumente an Frau Sorel."
  },
  AvgDialog_23367_Content_9 = {
    Text = "Sorel überflog rasch die dicht gedrängten Einträge auf dem schwarz-weißen Papier, ein spöttisches Lächeln auf ihren Lippen."
  },
  AvgDialog_23368_Content_1 = {
    Text = "Denk nicht einmal daran, zu rennen!!"
  },
  AvgDialog_23368_Content_10 = {Text = "Uwaa—!!"},
  AvgDialog_23368_Content_11 = {
    Text = "Du warst so erschrocken, dass du die Rose heftig von dir schleudertest."
  },
  AvgDialog_23368_Content_12 = {
    Text = "Das sind alles Eier."
  },
  AvgDialog_23368_Content_13 = {Text = "...Ja."},
  AvgDialog_23368_Content_14 = {
    Text = "Das ist ein entscheidendes Beweisstück. Geh und heb es auf."
  },
  AvgDialog_23368_Content_15 = {
    Text = "Ich will nicht hingehen."
  },
  AvgDialog_23368_Content_16 = {
    Text = "Gut, da keiner von uns hingehen will, dann—"
  },
  AvgDialog_23368_Content_17 = {
    Text = "Ramona drehte den Kopf und sah Dexter an."
  },
  AvgDialog_23368_Content_18 = {Text = "?"},
  AvgDialog_23368_Content_19 = {
    Text = "Jemand hat hinter meinem Rücken geflüstert und mich die Wächterin genannt, nicht wahr? Nun, die Wächterin befiehlt dir, diese Blume aufzuheben."
  },
  AvgDialog_23368_Content_2 = {
    Text = "Du trittst vor, packst die Maske des Schattens und reißt sie mit großer Kraft herunter."
  },
  AvgDialog_23368_Content_20 = {
    Text = "Zur Klarstellung: Ich habe das nicht gesagt. Das war dieses betrunkene Kind, Nikolas..."
  },
  AvgDialog_23368_Content_21 = {
    Text = "Aber du hast es nicht geleugnet, oder?"
  },
  AvgDialog_23368_Content_22 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23368_Content_23 = {
    Text = "Na gut, ich heb sie auf."
  },
  AvgDialog_23368_Content_24 = {
    Text = "Dexter spielte an seinen edlen Manschettenknöpfen herum, krempelte die Ärmel hoch und ging niedergeschlagen hinüber."
  },
  AvgDialog_23368_Content_25 = {
    Text = "<Gray:Was für ein erschreckendes Lächeln... Ich sollte diesen Typen in Zukunft besser nicht leichtfertig beleidigen.>"
  },
  AvgDialog_23368_Content_26 = {
    Text = "Fräulein Doll sagt, dass Frau Sorels künstliches Labyrinth vollständig kalibriert ist und wir es erneut betreten können."
  },
  AvgDialog_23368_Content_27 = {
    Text = "Wie sieht's aus? Bist du diesmal zuversichtlich, den Täter zu fassen?"
  },
  AvgDialog_23368_Content_28 = {
    Text = "Du nicktest leicht."
  },
  AvgDialog_23368_Content_29 = {
    Text = "Ich rieche etwas Eigentümliches... Ich glaube, ich weiß, wie ich ihn aufspüren kann."
  },
  AvgDialog_23368_Content_3 = {
    Text = "Überraschenderweise befindet sich unter der Maske kein Gesicht, wie du erwartet hast — genau genommen ist dort überhaupt nichts."
  },
  AvgDialog_23368_Content_4 = {
    Text = "Er verschwand wie ein Hauch von Nebel."
  },
  AvgDialog_23368_Content_5 = {
    Text = "Hä, was ist das?"
  },
  AvgDialog_23368_Content_6 = {
    Text = "Eine blutrote Rose liegt still zu deinen Füßen."
  },
  AvgDialog_23368_Content_7 = {
    Text = "Noch eine Rose? Ich habe gehört, dass auch an den Tatorten der vorherigen Fälle eine Rose hinterlassen wurde..."
  },
  AvgDialog_23368_Content_8 = {
    Text = "Du sinnierst tief, als du plötzlich ein Kribbeln an deinen Fingerspitzen spürst."
  },
  AvgDialog_23368_Content_9 = {
    Text = "Du senkst den Blick und bemerkst mehrere pralle, weiße Maden, die aus den Blütenblättern kriechen und auf deine Hand gelangen."
  },
  AvgDialog_23369_Content_1 = {Text = "Hmm—!!"},
  AvgDialog_23369_Content_10 = {
    Text = "Mach die Augen auf und schau dir das Wasser auf uns an. Hast du uns etwa eine Chance gegeben, es zu erklären?"
  },
  AvgDialog_23369_Content_11 = {
    Text = "Äh... Schwamm drüber! Da wir geschäftlich hier sind, sollte Karen eine professionelle Haltung zeigen, um Respekt zu erweisen."
  },
  AvgDialog_23369_Content_12 = {
    Text = "Damit öffnet sie dir ihre pummelige Handfläche."
  },
  AvgDialog_23369_Content_13 = {
    Text = "Eine Einladung kostet zehn Leo-Fänge, zwei Einladungen kosten zwanzig. Kein Handeln."
  },
  AvgDialog_23369_Content_14 = {
    Text = "Die Vorstellung beginnt gleich. Ihr wollt sie doch nicht verpassen, werter Offizier?"
  },
  AvgDialog_23369_Content_15 = {
    Text = "Du fährst dir mit der Hand durch dein verfilztes, nasses Haar und stößt einen langen Seufzer aus."
  },
  AvgDialog_23369_Content_16 = {
    Text = "Ramona, meine Geduld geht zu Ende. Wie wäre es, wenn wir ihr erst mal eine ordentliche Tracht Prügel verpassen?"
  },
  AvgDialog_23369_Content_17 = {
    Text = "...und so weiter."
  },
  AvgDialog_23369_Content_18 = {
    Text = "Fräulein Karen, es ist schon in Ordnung, wenn wir nicht zu diesem Stück gehen."
  },
  AvgDialog_23369_Content_19 = {
    Text = "Aber was würde Frau Sorel wohl denken, wenn sie wüsste, dass ihre vertrauteste Magd draußen Badewasser verkauft?"
  },
  AvgDialog_23369_Content_2 = {
    Text = "Karen wurde am Ende der Gasse in die Ecke gedrängt und schirmte hektisch ihre Brust ab."
  },
  AvgDialog_23369_Content_20 = {
    Text = "I-Ich habe keine Angst! Leute wie ihr würden Frau Sorel niemals zu Gesicht bekommen, Lügnerin!"
  },
  AvgDialog_23369_Content_21 = {
    Text = "Was macht es schon, wenn ich dich nicht sehen kann? Ich gehe jetzt sofort zum Eingang des Opernhauses und enthülle lautstark alles, was du getan hast..."
  },
  AvgDialog_23369_Content_22 = {
    Text = "<Big:Warte einen Moment!>"
  },
  AvgDialog_23369_Content_23 = {
    Text = "Karen stand hastig auf, kramte eine Weile in ihrer Schürze und reichte dir dann zwei zerknitterte Einladungen."
  },
  AvgDialog_23369_Content_24 = {
    Text = "Hier, nimm alles!\nHmph, immer das einfache Volk unterdrücken. Passt bloß auf, sonst begegnet ihr noch Geistern, wenn ihr weiter nachts spazieren geht!"
  },
  AvgDialog_23369_Content_25 = {
    Text = "Vielen Dank für die freundlichen Worte, Fräulein Karen. Wir werden vorsichtig sein."
  },
  AvgDialog_23369_Content_26 = {
    Text = "Du strecktest freudig die Hand aus. Einfach als du die Einladung berühren wolltest, hob Karen langsam ihre Hand und zog sie zurück."
  },
  AvgDialog_23369_Content_27 = {
    Text = "Ihr solltet besser nur wegen der Vorstellung hier sein. Kommt bloß nicht auf dumme Gedanken."
  },
  AvgDialog_23369_Content_28 = {
    Text = "Wenn Frau Sorel irgendetwas zustößt, wird Karen euch nicht vergeben."
  },
  AvgDialog_23369_Content_29 = {
    Text = "<Red:Er wird euch auch nicht davonkommen lassen.>"
  },
  AvgDialog_23369_Content_3 = {
    Text = "Fangt mich nicht, fangt mich nicht... <Big:Aaah!>"
  },
  AvgDialog_23369_Content_30 = {Text = "Er...?"},
  AvgDialog_23369_Content_31 = {
    Text = "Oh je, es scheint, Karen hat sich versprochen. Was für ein Fehler!"
  },
  AvgDialog_23369_Content_32 = {
    Text = "Kurzum, tut eure Arbeit und stellt keine unnötigen Fragen.\nLebewohl, meine liebe Offizierin～"
  },
  AvgDialog_23369_Content_33 = {
    Text = "Karen zwinkerte dir verspielt zu, hob dann mühsam den Eimer hoch und watschelte mit großer Anstrengung davon."
  },
  AvgDialog_23369_Content_34 = {
    Text = "Misaq-Lounge\nNach dem Ende des ersten künstlichen Labyrinths"
  },
  AvgDialog_23369_Content_35 = {
    Text = "Du hast eine Einladung von der Magd erhalten. Was geschah danach?"
  },
  AvgDialog_23369_Content_36 = {
    Text = "Wie ich zuvor sagte, betraten wir reibungslos das Theater und fanden Frau Sorel im zweiten Stock."
  },
  AvgDialog_23369_Content_37 = {
    Text = "Aber wir konnten den Mörder trotzdem nicht aufhalten ..."
  },
  AvgDialog_23369_Content_38 = {
    Text = "Hilfe... hilf mir..."
  },
  AvgDialog_23369_Content_39 = {
    Text = "Hilf mir ..."
  },
  AvgDialog_23369_Content_4 = {
    Text = "Ich habe noch gar nichts gemacht."
  },
  AvgDialog_23369_Content_40 = {
    Text = "Ich sah, wie sie von oben fiel, zusammen mit den Blumen und dem Champagner ... Das ist alles, was im ersten Geheimgang geschah."
  },
  AvgDialog_23369_Content_41 = {
    Text = "Der Untergang einer Schönheit ist wirklich bedauernswert. Du siehst aus, als wärst du den Tränen nahe."
  },
  AvgDialog_23369_Content_42 = {
    Text = "Es ist in Ordnung.\nDer Zweck des Betretens des Geheimgangs ist die Rekonstruktion des Tatorts, die Hinweise für die weitere Ermittlung liefert."
  },
  AvgDialog_23369_Content_43 = {
    Text = "Die Einladung von dieser hinterhältigen Zofe bekommen ... Nicht schlecht, du hast dich verbessert."
  },
  AvgDialog_23369_Content_5 = {
    Text = "Keine Sorge, wir werden dich nicht fangen. Wir brauchen nur einen kleinen Gefallen."
  },
  AvgDialog_23369_Content_6 = {
    Text = "Wir brauchen zwei Einladungen für „Der Name der Rosenblume.\" Ich schätze, Fräulein Karen sollte noch welche übrig haben?"
  },
  AvgDialog_23369_Content_7 = {
    Text = "Name der Rosenblume...?"
  },
  AvgDialog_23369_Content_8 = {
    Text = "Karen nahm die Hände von ihrer Brust, ihre großen runden Augen wanderten im Kreis umher."
  },
  AvgDialog_23369_Content_9 = {
    Text = "Also wollte der Offizier auch eine Einladung. Warum habt ihr das nicht einfach gesagt?\nLeute sofort zu packen ist ziemlich beängstigend..."
  },
  AvgDialog_23370_Content_10 = {
    Text = "Ich sehe, ihr habt so viel Spaß beim Auftreten, da kann ich es nicht übers Herz bringen, euch zu unterbrechen."
  },
  AvgDialog_23370_Content_11 = {
    Text = "Ruf Trupp B–01 und A–03, sie sollen das Ziel sofort umstellen."
  },
  AvgDialog_23370_Content_12 = {
    Text = "Das Rascheln kam aus allen Richtungen der Straße, gefolgt von chaotischen Schritten."
  },
  AvgDialog_23370_Content_13 = {
    Text = "Sehr bald hatten die Außendienstagenten von Misaq den Schatten umzingelt."
  },
  AvgDialog_23370_Content_14 = {
    Text = "Verstehe, Ihr habt Trunkenheit vorgetäuscht, um mich herauszulocken."
  },
  AvgDialog_23370_Content_15 = {
    Text = "Großartige Schauspielkunst, Mr. Dexter, besonders der Gesangsteil."
  },
  AvgDialog_23370_Content_16 = {
    Text = "Vielen Dank für Ihre Anerkennung. Ich verrate Ihnen ein Geheimnis: Als Kind war mein Traum, ein berühmter Opernsänger im West Ende zu werden..."
  },
  AvgDialog_23370_Content_17 = {
    Text = "Noch bevor die Worte verklungen waren, glitt der Schatten flink davon, sich bewegend mit der Anmut fließenden Wassers, ohne eine Spur von Zögern."
  },
  AvgDialog_23370_Content_18 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23370_Content_19 = {
    Text = "Ich habe noch nicht ausgesprochen... Schnell, fangt ihn!"
  },
  AvgDialog_23370_Content_2 = {
    Text = "Dexter stürzte ungelenk zu Boden und umklammerte vergeblich seinen Gehstock vor der Brust."
  },
  AvgDialog_23370_Content_3 = {
    Text = "Mein Herr, ich glaube, es liegt ein Missverständnis zwischen uns vor..."
  },
  AvgDialog_23370_Content_4 = {
    Text = "Oh, was für ein Missverständnis? Nur zu, erzählt mir Eure Geschichte."
  },
  AvgDialog_23370_Content_5 = {
    Text = "Der Schatten beugte sich hinab, die Maske nur einen Zentimeter von Dexters Nase entfernt."
  },
  AvgDialog_23370_Content_6 = {
    Text = "Uh! N–nicht so nah kommen..."
  },
  AvgDialog_23370_Content_7 = {
    Text = "Dexters Kopfhaut kribbelte, als er sich plötzlich umdrehte und in Richtung der Ecke hinter ihm rief."
  },
  AvgDialog_23370_Content_8 = {
    Text = "<Big:Ihr da, habt ihr genug von der Vorstellung?!>"
  },
  AvgDialog_23370_Content_9 = {Text = "?!"},
  AvgDialog_23371_Content_1 = {
    Text = "Während du einen kleinen Kuchen genießt, führst du Ramona in eine abgelegene Gasse."
  },
  AvgDialog_23371_Content_10 = {
    Text = "Ah, dieser zarte Duft! <Shake:Ich habe das Gefühl, ich kann kaum noch atmen...>"
  },
  AvgDialog_23371_Content_11 = {
    Text = "Was soll das heißen — auch dieser Fächer hier ist ein limitiertes Stück, das Frau Sorel aus Lemvah mitgebracht hat!"
  },
  AvgDialog_23371_Content_12 = {
    Text = "Schau, das Auge des Pharaos ist sogar darauf eingearbeitet!"
  },
  AvgDialog_23371_Content_13 = {
    Text = "Hahaha, hast du schon mal gesehen, wie die Augen des Pharaos aussehen? <Shake:Hüte dich vor dem Fluch～>"
  },
  AvgDialog_23371_Content_14 = {
    Text = "Du... was soll das heißen?! Stellst du etwa Frau Sorels Geschmack infrage?"
  },
  AvgDialog_23371_Content_15 = {Text = "...?"},
  AvgDialog_23371_Content_16 = {
    Text = "Was machen diese Leute?"
  },
  AvgDialog_23371_Content_17 = {
    Text = "Ähm... Ruhe, alle zusammen, Ruhe! Der spannende Moment steht kurz bevor!"
  },
  AvgDialog_23371_Content_18 = {
    Text = "Hier kommt unser Knallerprodukt! Und zwar—"
  },
  AvgDialog_23371_Content_19 = {
    Text = "<Big:Badewasser, das Frau Sorel erst letzte Woche benutzt hat!>"
  },
  AvgDialog_23371_Content_2 = {
    Text = "Schluck, schluck... Hmm, dieser kleine Kuchen schmeckt genau wie der, den ich im echten Leben gegessen habe!\nRamona, möchtest du auch mal probieren?"
  },
  AvgDialog_23371_Content_3 = {
    Text = "Du hältst den Cupcake an Ramonas Mund. Sie seufzt und nimmt widerwillig einen kleinen Bissen."
  },
  AvgDialog_23371_Content_4 = {
    Text = "Hmm... Nicht schlecht."
  },
  AvgDialog_23371_Content_5 = {
    Text = "Ähm, zurück zum Thema. Hast du nicht gesagt, du würdest mir helfen, die Einladung zu finden?"
  },
  AvgDialog_23371_Content_6 = {
    Text = "Keine Sorge, die Einladung wird nicht verloren gehen. Diesen Trick hat mir Hanna beigebracht; darauf würden die meisten Leute nicht kommen."
  },
  AvgDialog_23371_Content_7 = {
    Text = "Hey, schau mal dort drüben."
  },
  AvgDialog_23371_Content_8 = {
    Text = "Du zeigtest zum Ende der Gasse. Dort hatte sich eine Menschenmenge versammelt, die laut plauderte und aufgeregt mit den Armen wedelte, was eine fröhliche und lebhafte Atmosphäre erzeugte."
  },
  AvgDialog_23371_Content_9 = {
    Text = "Hehe, diese Nylonstrümpfe sind ein Exclusivartikel aus dem \"Lady's Guide\"! Ich habe gehört, dass Frau Sorel sie alle gekauft hat, weshalb sie nicht auf dem Markt erhältlich sind..."
  },
  AvgDialog_23372_Content_1 = {
    Text = "Blutrotes Gelage"
  },
  AvgDialog_23372_Content_10 = {
    Text = "„Stattdessen erhält man eine Einladung zu ‚Rosenblume Name'.\""
  },
  AvgDialog_23372_Content_11 = {
    Text = "Halt, keine Zeitung mehr.\nIch bin auch eine Bürgerin von Lentiniën. Ich kenne diese Gerüchte genauso gut wie du."
  },
  AvgDialog_23372_Content_12 = {
    Text = "Ähm, ich hätte fast vergessen, dass es jemanden gibt, der jeden Tag früh aufstehen, Tee trinken und Zeitung lesen muss und trotz seiner Jugend wie eine alte Oma lebt."
  },
  AvgDialog_23372_Content_13 = {
    Text = "Über den aktuellen Stand der weltweiten Angelegenheiten und Nachrichten informiert zu sein, kann bei Ermittlungen sehr hilfreich sein."
  },
  AvgDialog_23372_Content_14 = {
    Text = "Da alles der Arbeit dient... kehren wir zur Arbeit zurück."
  },
  AvgDialog_23372_Content_15 = {
    Text = "Die Aufführung ist morgen. Warum einen Tag früher kommen? Meine schwache Geisteskraft steht bereits am Rande des Zusammenbruchs..."
  },
  AvgDialog_23372_Content_16 = {
    Text = "Dexter hat mir erzählt, dass Sorel eine Frau ist, die Extravaganz liebt. Sie bucht oft das gesamte zweite Stockwerk des Theaters für sich und ihre Freunde."
  },
  AvgDialog_23372_Content_17 = {
    Text = "Daher variiert die Position ihrer Loge jedes Mal, wenn sie erscheint — natürlich spielen hier auch Sicherheitserwägungen eine Rolle."
  },
  AvgDialog_23372_Content_18 = {
    Text = "Verstehe.\nAber der Mörder schien sich ihrer Position sehr sicher zu sein... Könnte es sein, dass jemand aus Sorels Umfeld die Information weitergegeben hat?"
  },
  AvgDialog_23372_Content_19 = {
    Text = "Während du das sagst, erscheint ein Bild von Karen in deinem Kopf."
  },
  AvgDialog_23372_Content_2 = {
    Text = "Zweites künstliches Labyrinth: Lincoln High Street\nDer Tag vor Sorels Tod"
  },
  AvgDialog_23372_Content_20 = {
    Text = "Diese geschwätzige Magd ist höchst verdächtig..."
  },
  AvgDialog_23372_Content_21 = {Text = "Rums!!"},
  AvgDialog_23372_Content_22 = {
    Text = "Jemand rempelt im Vorbeigehen deine Schulter an. Du runzelst die Stirn und drehst dich um, doch dein Handgelenk wird fest gepackt."
  },
  AvgDialog_23372_Content_23 = {
    Text = "<SmallShake:Hey, mir ist aufgefallen, dass du schon lange vor dem Plakat von Frau Sorel stehst. Bist du auch ein Fan von ihr?>"
  },
  AvgDialog_23372_Content_24 = {
    Text = "<SmallShake:Ich verkaufe Frau Sorels Logennummer für heute Abend zu einem günstigen Preis, zusammen mit dem Weg, den sie beim Verlassen nehmen wird...>"
  },
  AvgDialog_23372_Content_25 = {
    Text = "<SmallShake:Wollt ihr die Göttin aus der Nähe sehen? Heute Nacht ist eure beste Chance. Verpasst es nicht!>"
  },
  AvgDialog_23372_Content_26 = {Text = "...?"},
  AvgDialog_23372_Content_27 = {
    Text = "Ich wusste, dass Sorel beliebt ist, aber ich hätte nicht erwartet, dass es so extrem ist..."
  },
  AvgDialog_23372_Content_28 = {
    Text = "Es gibt noch eine Frage: Ist das wirklich nötig?"
  },
  AvgDialog_23372_Content_29 = {
    Text = "Tsk, das war es also doch nicht.\nBlockiert nicht den Weg. Dies ist ein regulärer Treffpunkt für uns Sorel-Verehrer..."
  },
  AvgDialog_23372_Content_3 = {
    Text = "<Yellow:Zweites künstliches Labyrinth – Ermittlungsprotokoll·eins>\n\n■Labyrinth–ID: M–B04–002\n■Zeitrahmen: n. S. 315, Juni @1, 14:00–18:00 Uhr (der Tag vor Sorels Tod).\n■Ort: Lincoln High Street"
  },
  AvgDialog_23372_Content_30 = {
    Text = "Moment, wer hat euch von Sorel erzählt? Sagt es mir, und ich zahle euch den doppelten Preis."
  },
  AvgDialog_23372_Content_31 = {
    Text = "Wie erwartet von Ramona, sie ist immer noch so scharfsinnig wie eh und je."
  },
  AvgDialog_23372_Content_32 = {
    Text = "Äh... Was? Warum interessiert euch das so sehr? Seid ihr etwa Bullen oder so?"
  },
  AvgDialog_23372_Content_33 = {
    Text = "Inmitten des Trubels kommt eine luxuriöse Kutsche langsam vor euch zum Stehen."
  },
  AvgDialog_23372_Content_34 = {
    Text = "Eine blasse, schlanke Hand mit geschmückten Ringen streckt sich aus und greift nach einem Stapel Goldene Rose Gutscheine."
  },
  AvgDialog_23372_Content_35 = {
    Text = "Ahem... Ich habe deine Informationen gekauft, kleines Mädchen."
  },
  AvgDialog_23372_Content_36 = {
    Text = "Eine seltsame, ältliche Stimme kam aus der Kutsche. Der Besitzer der Stimme schien schwer krank zu sein und hustete ständig wie ein alter, kaputter Blasebalg."
  },
  AvgDialog_23372_Content_37 = {
    Text = "Wow! S-so viel Geld? Zack, alles meins?"
  },
  AvgDialog_23372_Content_38 = {
    Text = "Die Person in der Kutsche scheint etwas ungeduldig zu sein und ist im Begriff, ihre Hand zurückzuziehen."
  },
  AvgDialog_23372_Content_39 = {
    Text = "Das Mädchen reichte hastig einen Zettel hinüber, schnappte sich dann flink den Goldgutschein und lächelte so breit, dass ihre Augen zu schmalen Schlitzen wurden."
  },
  AvgDialog_23372_Content_4 = {
    Text = "■Bereichsinhaber: Sorel·@2\n■Bereichs-Eindringlinge: %player%, Ramona\n\n■Ziel: <Yellow:Untersuchen Sie die Umgebung des Theaters nach weiteren Hinweisen.>"
  },
  AvgDialog_23372_Content_40 = {
    Text = "Hier sind die gewünschten Informationen! Edler und großzügiger Herr, ich wünsche Euch baldige Genesung und ein langes Leben!"
  },
  AvgDialog_23372_Content_41 = {
    Text = "Bevor das Mädchen zu Ende sprechen konnte, raste die Kutsche davon."
  },
  AvgDialog_23372_Content_42 = {
    Text = "Dieser alte Mann scheint kein Fan von Sorel zu sein. Lasst uns ihm folgen."
  },
  AvgDialog_23372_Content_5 = {
    Text = "Die belebten Straßen sind voller Fußgänger und Kutschen, durchdrungen von einer fröhlichen, festlichen Atmosphäre."
  },
  AvgDialog_23372_Content_6 = {
    Text = "Nur noch ein Tag bis zur Opernaufführung, und Plakate für die Vorstellung bedecken bereits die Straßen."
  },
  AvgDialog_23372_Content_7 = {
    Text = "Interessanterweise nahm Frau Sorel als Anteilseignerin des Theaters den größten Teil der Plakatfläche ein. Den Inhalt des Stücks interessierte eigentlich niemanden."
  },
  AvgDialog_23372_Content_8 = {
    Text = "\"Der 'Rosenname' war die erste Oper, die aufgeführt wurde, nachdem Frau Sorel in <Blue:Covent Theatre> investiert hatte.\""
  },
  AvgDialog_23372_Content_9 = {
    Text = "„Heutzutage ist das Zeichen für den Aufstieg in die gehobene Gesellschaft weder das Tragen von Seide aus dem Osten noch der Besitz eines antiken Tonkrugs aus Lemvah...“"
  },
  AvgDialog_23841_Content_1 = {
    Text = "Hast du dem Fahrer erlaubt zu gehen? Gibt es viele feindliche Verstärkungen?"
  },
  AvgDialog_23841_Content_10 = {
    Text = "Von Anfang an waren ihre Angriffe gezielt — um uns hierher zu treiben, zu Dock 2 am Pier 3."
  },
  AvgDialog_23841_Content_11 = {
    Text = "Aber hier sieht es auch nicht besonders aus"
  },
  AvgDialog_23841_Content_12 = {
    Text = "Ja, dieser Liegeplatz Nummer 2 hat nichts Besonderes"
  },
  AvgDialog_23841_Content_13 = {
    Text = "Das eigentliche Problem ist das <Yellow:Schiff>, das hier angedockt ist."
  },
  AvgDialog_23841_Content_14 = {Text = "Schiff?"},
  AvgDialog_23841_Content_15 = {
    Text = "Ramona's Worte lösten einen heftigen Wind aus, der den Nebel in deinem Kopf sofort zerstreute"
  },
  AvgDialog_23841_Content_16 = {Text = "!"},
  AvgDialog_23841_Content_17 = {
    Text = "Ein riesiges Schiff tauchte lautlos hinter euch auf, blockierte das Mondlicht und hüllte alle in Dunkelheit"
  },
  AvgDialog_23841_Content_18 = {
    Text = "Nachdem das Riesenrad aus dem Nichts erschien, stießen die um dich versammelten Murlocs einen erschreckenden Schrei aus und führten dann eine äußerst bizarre Handlung aus."
  },
  AvgDialog_23841_Content_19 = {
    Text = "Sieh sie dir an!"
  },
  AvgDialog_23841_Content_2 = {
    Text = "Zu viele Feinde, der Rückweg ist blockiert"
  },
  AvgDialog_23841_Content_20 = {
    Text = "Die Murlocs bildeten eine lange Reihe und stürzten sich immer wieder auf das riesige Schiff, wie eine Gruppe selbstmörderischer Lemminge."
  },
  AvgDialog_23841_Content_21 = {
    Text = "Was noch seltsamer war, war, dass jedes Mal, wenn eine Murloc's geglättete Hand kurz davor war, den Rumpf zu berühren, der Rumpf einen kaum sichtbaren Glanz ausstrahlte, der alle Murlocs, die es versuchten, zurück ins Wasser schleuderte."
  },
  AvgDialog_23841_Content_22 = {
    Text = "Weiß das Schiff... weigert sich, diesen Murlocs näher zu kommen?"
  },
  AvgDialog_23841_Content_23 = {
    Text = "Die äußere Schiffshülle ist stark verrostet und verblasst, die ursprüngliche Lackierung des Schiffes ist nicht mehr erkennbar, und der Name des Schiffes in weißer Farbe ist schwer zu entziffern"
  },
  AvgDialog_23841_Content_24 = {Text = "Sona..."},
  AvgDialog_23841_Content_25 = {
    Text = [[
<Blue:Sonaniel>.
Erica, gibt es einen Eintrag im Mythischen Archiv?]]
  },
  AvgDialog_23841_Content_26 = {
    Text = "Der Sonanil, früher im Besitz von <Blue:Black Star Shipping Company>, diente als Passagierschiff für transatlantische Reisen."
  },
  AvgDialog_23841_Content_27 = {
    Text = "Nach der Insolvenz der Black Star Corporation wurde der Sonanier anonym erworben, neu registriert und in ein Frachtschiff umgewandelt."
  },
  AvgDialog_23841_Content_28 = {
    Text = "William-Senpai! Kennst du dieses Schiff?"
  },
  AvgDialog_23841_Content_29 = {
    Text = "Im Jahr 288 der Hongji-Ära sank die Sonanil in einem Sturm. Jahre später begannen Sichtungen des \"<Blue:Geisterschiff>\" an der Nordküste aufzutauchen."
  },
  AvgDialog_23841_Content_3 = {
    Text = "Die mondbeschienene Meeresoberfläche rippling weiterhin, und in den Ecken, wo das Licht nicht hinkommt, wer weiß, wie viele Feinde sich verstecken."
  },
  AvgDialog_23841_Content_30 = {
    Text = "Ein Missaga-Ermittler betrat einst die Sonanil, brachte aber keine verwertbaren Informationen zurück"
  },
  AvgDialog_23841_Content_31 = {
    Text = "Keine verwertbaren Informationen zurückgebracht"
  },
  AvgDialog_23841_Content_32 = {
    Text = "Aber das bedeutet, dass der Ermittler sicher zur Schule zurückgekehrt ist, oder?"
  },
  AvgDialog_23841_Content_33 = {
    Text = "Ja, obwohl er einen Teil seiner Erinnerungen verloren hat, hat das Betreten des Schiffs keine weiteren Anomalien an seinem Körper verursacht.\nNach kurzer Erholung kehrte er wieder an die Spitze der Untersuchung zurück"
  },
  AvgDialog_23841_Content_34 = {
    Text = "Kann dieser Senior die Kommunikation übernehmen?"
  },
  AvgDialog_23841_Content_35 = {
    Text = "...Wie schade.\nBevor du Mythag beigetreten bist, ist er während einer Mission ums Leben gekommen."
  },
  AvgDialog_23841_Content_36 = {
    Text = "Warte mal! Ramona, du denkst doch nicht an..."
  },
  AvgDialog_23841_Content_37 = {
    Text = "Ja, ich glaube nicht, dass sie uns auf Rettung warten lassen"
  },
  AvgDialog_23841_Content_38 = {
    Text = "Die Murlocs eilten nicht mehr, um Sonanil zu berühren, sondern wandten ihre Waffen gegen dich. Der Ring zog sich zusammen, sodass du und Ramona keinen Ausweg mehr hattet, fast gegen das Schiff gedrängt."
  },
  AvgDialog_23841_Content_39 = {
    Text = "Ramona atmete tief ein und streckte die Hand aus, um das Gangway zu berühren, das von der Bordseite des Schiffs hinunterführte."
  },
  AvgDialog_23841_Content_4 = {
    Text = "Rückzug@2——!@1!Lehre@1!"
  },
  AvgDialog_23841_Content_40 = {
    Text = "Im Gegensatz zu den Murlocs, die mehrere Meter zurückgeschlagen wurden, drückten ihre Finger fest gegen den Rumpf.\nDu tauschtest Blicke mit ihr aus und legtest deine Hand auf die Seite des Schiffes."
  },
  AvgDialog_23841_Content_41 = {
    Text = "Ein leichter Widerstand lässt deine Hand in der Luft schweben, doch er verschwindet schnell. Die eisige Berührung von Stahl dringt durch deinen Handschuh und schickt Schauer über deinen Rücken."
  },
  AvgDialog_23841_Content_42 = {
    Text = "Dieses Schiff, Sonaniel, <Yellow:hat dich nicht abgelehnt>."
  },
  AvgDialog_23841_Content_43 = {
    Text = "Wir gehen jetzt an Bord"
  },
  AvgDialog_23841_Content_5 = {
    Text = "Nachdem der Kreis enger wurde, griffen die Fischmonster nicht weiter an, sondern verharrten vor einem Dock und murmelten unverständliche Worte"
  },
  AvgDialog_23841_Content_6 = {
    Text = "Warum hören sie nicht auf, uns anzugreifen?"
  },
  AvgDialog_23841_Content_7 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23841_Content_8 = {
    Text = "Ramona, was ist los?"
  },
  AvgDialog_23841_Content_9 = {
    Text = "Egal ob sie uns nach Norden drängen oder am Ende den Ausgang blockieren, der Feind lässt uns immer einen Weg offen"
  },
  AvgDialog_23842_Content_1 = {
    Text = "Das sichere Haus, von dem der Kapitän mir erzählte, ist direkt hinter dieser Tür."
  },
  AvgDialog_23842_Content_10 = {
    Text = "Dieser grimmige Junge mit einer Krone heißt Tulu, und die Person neben ihm ist..."
  },
  AvgDialog_23842_Content_11 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23842_Content_12 = {
    Text = "Habe ich... nie nach deinem Namen gefragt...?"
  },
  AvgDialog_23842_Content_13 = {
    Text = "Murphy kratzte verlegen seinen Kopf und versteckte sich hinter dem Kapitän, überließ diese unpassende soziale Aktivität dem einzigen Erwachsenen."
  },
  AvgDialog_23842_Content_14 = {
    Text = "Ich bin %player%, ein Student an der Mythag Universität."
  },
  AvgDialog_23842_Content_15 = {
    Text = "Bist du der Kapitän? Unsere Aufzeichnungen zeigen, dass ein Senior von unserer Schule einmal auf dem Sonaniel an Bord ging."
  },
  AvgDialog_23842_Content_16 = {
    Text = "Der Kapitän nahm eine Zigarettendose aus seiner Tasche und wollte gerade die letzte Prise Tabak aufnehmen, als Murphy sanft seine Hand berührte."
  },
  AvgDialog_23842_Content_17 = {
    Text = "Hast du mir nicht versprochen, dass du nie wieder rauchen würdest?"
  },
  AvgDialog_23842_Content_18 = {
    Text = "Der Kapitän lächelte hilflos und steckte die Zigarettendose weg."
  },
  AvgDialog_23842_Content_19 = {
    Text = "Ich erinnere mich an deine Schuluniform. Wie schade, jetzt ist nicht die beste Zeit.\nWenn du an einem anderen Tag eingestiegen wärst, hätte ich dir ein Getränk einschenken und ein nettes Gespräch führen können."
  },
  AvgDialog_23842_Content_2 = {
    Text = "Was war das Klopfsignal, das wir damals vereinbart hatten... drei leichte Klopfer und einen starken? Leicht, stark, leicht?"
  },
  AvgDialog_23842_Content_20 = {
    Text = "Elton, mein Name ist Elton."
  },
  AvgDialog_23842_Content_21 = {
    Text = "Während du dich vorgestellt hast, wanderte Murphy um die düstere Kabine. Als sie wieder in dein Sichtfeld trat, war ihr Gesicht voller Verwirrung"
  },
  AvgDialog_23842_Content_22 = {
    Text = "Captain, ist Celeste nicht bei dir?"
  },
  AvgDialog_23842_Content_3 = {Text = "—Ah!"},
  AvgDialog_23842_Content_4 = {
    Text = "Als Murphy sich den Kopf zerbrach, um den Code zu erinnern und stark schwitzte, wurde die Tür plötzlich von innen aufgestoßen, und eine Hand zog sie hinein."
  },
  AvgDialog_23842_Content_5 = {
    Text = "Tulu hielt schnell die Tür, um zu verhindern, dass sie sich schloss. Er tauschte einen Blick mit dir aus, und ihr beide schlüpft gemeinsam hinein."
  },
  AvgDialog_23842_Content_6 = {
    Text = "Schiff, Kapitän! Großartig, ich wusste, dass du hier auf mich warten würdest..."
  },
  AvgDialog_23842_Content_7 = {
    Text = "Ein mittelalter Mann mit dunkler Haut, gekleidet in Besatzungsbekleidung, patschte Murphy auf den Kopf, um Besorgnis zu zeigen."
  },
  AvgDialog_23842_Content_8 = {
    Text = "Das Wort zu halten, ist etwas, an das Erwachsene sich halten müssen."
  },
  AvgDialog_23842_Content_9 = {
    Text = "Übrigens, wer sind diese beiden?"
  },
  AvgDialog_23843_Content_10 = {
    Text = "Ramona, sei vorsichtig!"
  },
  AvgDialog_23843_Content_11 = {
    Text = "Du ziehst den Silbernen Schlüssel heraus und versuchst, den wütenden Erwachen-Jungen mit der Verbindung zu zähmen"
  },
  AvgDialog_23843_Content_12 = {
    Text = "Dir wird fast sofort klar, dass etwas nicht stimmt: Sein Geist ist außergewöhnlich stabil, und eine schlangenartige Kette zieht seinen Geist in eine nahegelegene Richtung."
  },
  AvgDialog_23843_Content_13 = {
    Text = "—Zieht seine Verknüpfung zu sich."
  },
  AvgDialog_23843_Content_14 = {
    Text = "Ein verzerrter Phantom stürmte aus den Seefahrern hervor, schlug der Hand, die den Silber Schlüssel fest umklammert hielt, und schleuderte dich mit Wucht gegen das Schiffsseitengeländer."
  },
  AvgDialog_23843_Content_15 = {
    Text = "Caecus, es ist viel zu lange her."
  },
  AvgDialog_23843_Content_16 = {
    Text = "M-Miryam! Bitte gib mir eine weitere Chance. Ich werde diese beiden definitiv beseitigen."
  },
  AvgDialog_23843_Content_17 = {
    Text = "Die Frau mit der dornenbewehrten Krone warf ihm einen Blick zu, ohne zu antworten. Ihr Blick wanderte zu Ramona, die das Schwert hielt, dann zu dir und blieb schließlich auf dem silbernen Schlüssel hängen, der schwach auf deiner Brust leuchtete."
  },
  AvgDialog_23843_Content_18 = {
    Text = "Silberschlüssel..."
  },
  AvgDialog_23843_Content_19 = {
    Text = "Im nächsten Moment schoss ein schlangenartiger Schatten unter ihrem Schleier hervor und kroch wie eine Viper über deinen Körper."
  },
  AvgDialog_23843_Content_2 = {
    Text = "Ugh...! Wie können bloße gewöhnliche Menschen so lästig sein..."
  },
  AvgDialog_23843_Content_20 = {
    Text = "Es ist tatsächlich eine \"giftige Schlange\", ein lila Energiematerial, das sich fest um dein Handgelenk windet, ihre Fangzähne voll mit unheilvoller Energie, die drohend auf dich zielt—"
  },
  AvgDialog_23843_Content_22 = {
    Text = "Fass {Male=er,Female=sie} nicht an!"
  },
  AvgDialog_23843_Content_23 = {
    Text = "Ramona dreht sich um und wirft ihren Degen, um einen Schlangenschatten zu vertreiben, der dich bedrohlich anstarrt."
  },
  AvgDialog_23843_Content_24 = {
    Text = "Im nächsten Moment explodierten ihre Beine mit unglaublicher Kraft. Sie flog fast an den beiden vorbei und landete neben dir, zog dich zu Boden, während sie ihre Waffe zog und dem Angriff der Schlange erneut auswich"
  },
  AvgDialog_23843_Content_25 = {
    Text = "Wir sind nicht mit dieser Frau gleichwertig, steig schnell ins Beiboot!"
  },
  AvgDialog_23843_Content_26 = {
    Text = "Ramona ließ dir keine Chance zu widerstehen und drängte dich ohne zu zögern in das Rettungsboot."
  },
  AvgDialog_23843_Content_27 = {
    Text = "Sie sprang dann auf die Reling des Schiffs, beugte leicht die Knie, um ihren Körper zu stabilisieren, und zog schnell ihr Schwert. \nDer Mechanismus, der das Rettungsboot sicherte, zerbrach mit einem Geräusch, und ein überwältigendes Gefühl der Schwerelosigkeit überkam deinen Geist."
  },
  AvgDialog_23843_Content_28 = {
    Text = "<Big:Ramona!>"
  },
  AvgDialog_23843_Content_29 = {
    Text = "Ramona hing halb über der Seite des Schiffes, als der Schlangen-Schatten ihr Knöchel packte und sie zurück aufs Deck zog."
  },
  AvgDialog_23843_Content_3 = {
    Text = "Die Augen des jungen Jungen weiteten sich ungläubig. Während des Kampfes wurden seine Flossen und sein Schwanz von Ramonas regenschwertartigen Schlägen verwundet. Graurotes Blut floß frei auf das Deck und füllte die Lücken zwischen den Planken."
  },
  AvgDialog_23843_Content_30 = {
    Text = "Das Rettungsboot verlor seine Balance, als es fiel, und Dunkelheit zusammen mit dem eisigen Meerwasser flutete deinen Hals."
  },
  AvgDialog_23843_Content_31 = {
    Text = "Im letzten Moment siehst du Ramona, die ihre Hand nach dir ausstreckt."
  },
  AvgDialog_23843_Content_32 = {
    Text = "Ramona sackte auf das Deck, berührte ihr Sprunggelenk, und ihre Stirn runzelte sich."
  },
  AvgDialog_23843_Content_33 = {Text = "Knacken—"},
  AvgDialog_23843_Content_34 = {
    Text = "Sie biss die Zähne zusammen und stellte ihren ausgekugelten Knöchel wieder ein. Ihr Gesicht verzog sich einen Moment lang, dann gewann sie ihre übliche Fassung zurück."
  },
  AvgDialog_23843_Content_35 = {
    Text = "Eine Frau mit einer Aura von Führungskraft geht selbstbewusst auf Ramona zu und sieht von oben auf sie herab."
  },
  AvgDialog_23843_Content_36 = {
    Text = "Silberschlüssel, Verknüpfung, Erwecker..."
  },
  AvgDialog_23843_Content_37 = {
    Text = "Habe ich deine Erscheinung am Hafen nicht bemerkt, aber jetzt scheint es, \"Die Prophezeiung meines Herrn\" ist erfüllt - nichts kann die Sterne daran hindern, sich auszurichten, und alles in dieser Welt geht dahin, wo es hingehört"
  },
  AvgDialog_23843_Content_38 = {
    Text = "Hafen... Du warst es, der diese Seefahrer befohlen hat, uns zu jagen und uns zu benutzen, um die Bereichsgrenzen auf dem Schiff zu durchbrechen."
  },
  AvgDialog_23843_Content_39 = {
    Text = "Miryam bestätigte weder noch leugnete sie, ein frommes Lächeln zierte ihr schönes Gesicht."
  },
  AvgDialog_23843_Content_4 = {
    Text = "Er musste sich mit seiner Waffe abstützen, um aufrecht zu bleiben, und kämpfte offensichtlich, um deine Angriffe abzuwehren."
  },
  AvgDialog_23843_Content_40 = {
    Text = "Studierende der Mythag-Universität dienen als die geeignetste Nahrung für \"Unseren Herrn\"."
  },
  AvgDialog_23843_Content_41 = {
    Text = "Miryam schaute Ramona nicht länger an, noch kümmerte sie sich um die Waffe, die weiterhin in Romanas Hand umklammert war. Sie wirkte selbstbewusst und gleichgültig gegenüber Romanas Widerstand."
  },
  AvgDialog_23843_Content_42 = {
    Text = "Vielleicht ist sie sich absolut sicher, dass Ramonakampf keine Wellen mehr schlagen kann."
  },
  AvgDialog_23843_Content_43 = {
    Text = [[
Dies ist deine letzte Chance, Caecus.
Nimm sie mit und behalte sie genau im Auge.]]
  },
  AvgDialog_23843_Content_44 = {
    Text = "Sie wird der letzte Teil des Rituals sein. <Yellow:\"Mein Herr\"> wird bei der Wiedergeburt das süße Caro der Narren trinken."
  },
  AvgDialog_23843_Content_45 = {
    Text = "<Yellow:Es> wird unsere Stadt aus dem Meer heben, unser Volk inmitten des Chaos wiederherstellen und die neue Zukunft für diejenigen werden, die den Ozean betreten."
  },
  AvgDialog_23843_Content_5 = {
    Text = "Du unterscheidest dich von diesen fischköpfigen Monstern, und deine Kraft..."
  },
  AvgDialog_23843_Content_6 = {
    Text = "Ramona hebt ihr Schwert, die Spitze beschreibt einen eleganten, aber wilden Bogen, und richtet es direkt auf den Jungen, der auf einem Knie kniet."
  },
  AvgDialog_23843_Content_7 = {
    Text = "Du bist ein Erwacher... richtig?"
  },
  AvgDialog_23843_Content_8 = {
    Text = "Wie wagst du es! Unser Blut ist weit edler als das der Menschen. Du hast kein Recht, die Seefahrer Monster zu nennen!"
  },
  AvgDialog_23843_Content_9 = {
    Text = "Ramonas Worte trafen einen Nerv bei dem Jungen. Er spannte sich plötzlich an, die Flossen auf seinem Rücken stellten sich auf, und mit einer schnellen Bewegung wehrte er Ramonas Schwert ab."
  },
  AvgDialog_23844_Content_1 = {
    Text = "Die Tentakel schlugen heftig zu, zertrümmerten den Körper des Seefahrers, vermieden aber auf wundersame Weise den Standort des Mädchens."
  },
  AvgDialog_23844_Content_10 = {
    Text = "Ah! Wenn wir gerade beim Ritual sind... Kleine Schwester, haben sie dir wehgetan? Du hältst dir dein Handgelenk. Hast du es verstaucht?"
  },
  AvgDialog_23844_Content_11 = {
    Text = "Ich bin nicht irgendein kleines Mädchen; ich habe einen Namen."
  },
  AvgDialog_23844_Content_12 = {
    Text = "Murphy, nenn mich einfach Murphy."
  },
  AvgDialog_23844_Content_13 = {
    Text = "Murphy, ich habe Ausbildung in der Behandlung äußerer Verletzungen. Darf ich mir deine Hand ansehen?"
  },
  AvgDialog_23844_Content_14 = {
    Text = "Das Mädchen zögerte, erlaubte dir schließlich aber, dich zu nähern, und streckte ihr Hand aus."
  },
  AvgDialog_23844_Content_15 = {
    Text = "Du hältst sanft ihre Hand und schiebst ihren Ärmel hoch. Sie trägt dicke Winterkleidung, und abgesehen von einer möglichen leichten Rötung durch das Ziehen sind keine anderen sichtbaren Verletzungen vorhanden."
  },
  AvgDialog_23844_Content_16 = {
    Text = "Eine kleine Belastung. Bei diesem Schweregrad wird es ausreichen, zwei Tage zu ruhen."
  },
  AvgDialog_23844_Content_17 = {
    Text = "Merkend, dass Murphys Emotionen sich leicht beruhigt hatten, wichst du ihrer Wunde aus und packtest plötzlich fest ihren Oberarm."
  },
  AvgDialog_23844_Content_18 = {
    Text = "Was machst du?!"
  },
  AvgDialog_23844_Content_19 = {
    Text = "Du kennst die Anführerin der Seefahrer, Miryam, und dennoch wirst du von ihnen gejagt.\nMurphy, wer bist du genau?"
  },
  AvgDialog_23844_Content_2 = {
    Text = "Tulu zog seinen Tentakel zurück und blickte mit Abscheu auf die grau-grünen und rot-weißen Flüssigkeiten. Sein Ausdruck verblasste schnell, nachdem er diskret den Schmutz auf dem Deck abgewischt hatte."
  },
  AvgDialog_23844_Content_20 = {
    Text = "Ich... Ich..."
  },
  AvgDialog_23844_Content_21 = {
    Text = "In diesem Moment beendete Tulu die Untersuchung der Rune und trat in das Gespräch ein."
  },
  AvgDialog_23844_Content_22 = {
    Text = "Diese Rune ist ein Hypnoseritual für Seefahrer. Sie wollen sie in Schlaf versetzen, um Komplikationen zu vermeiden"
  },
  AvgDialog_23844_Content_23 = {
    Text = "Bevor Tulu mit dem Sprechen fertig war, wurde Murphys Gesicht blass. Ihre Kämpfe mit Treten und Beißen gegen dich hörten auf, als ob sie über etwas nachdenkte."
  },
  AvgDialog_23844_Content_24 = {Text = "Murphy?"},
  AvgDialog_23844_Content_25 = {Text = "—Klang!"},
  AvgDialog_23844_Content_26 = {
    Text = "Ein scharfer Schmerz trifft deine Stirn und macht dich schwindelig. Murphy nutzt die Gelegenheit, um sich zu befreien und läuft tiefer in die Kabine, während er sich den Kopf hält."
  },
  AvgDialog_23844_Content_27 = {
    Text = "Ich wusste, dass du nichts Gutes im Schilde führst!!"
  },
  AvgDialog_23844_Content_28 = {
    Text = "Warte, warte... Lass mich erklären..."
  },
  AvgDialog_23844_Content_29 = {
    Text = "Murphy wird offensichtlich nicht auf deine schwache Erklärung hören, und ihre Gestalt verschwindet schnell um die Ecke."
  },
  AvgDialog_23844_Content_3 = {
    Text = "Huch... Huch..."
  },
  AvgDialog_23844_Content_30 = {
    Text = "...Tulu, warum hast du nicht daran gedacht, sie aufzuhalten?"
  },
  AvgDialog_23844_Content_31 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23844_Content_32 = {
    Text = "Schau mich nicht so an. Ich habe auch nicht erwartet, dass ihr Kopf so hart ist."
  },
  AvgDialog_23844_Content_4 = {
    Text = "Das Mädchen umklammerte ihr Handgelenk, atmete schwer und war noch immer im Schockzustand."
  },
  AvgDialog_23844_Content_5 = {
    Text = "Geht es dir gut?"
  },
  AvgDialog_23844_Content_6 = {
    Text = "Bleib zurück!!"
  },
  AvgDialog_23844_Content_7 = {
    Text = "Du hattest kaum einen halben Schritt nach vorne gemacht, als das Mädchen nervös rief, ihre Augen voller Wachsamkeit waren."
  },
  AvgDialog_23844_Content_8 = {
    Text = "Als du das sahst, hörtest du auf zu nähern und hobst deine Hände, um zu zeigen, dass du keinen Schaden willst."
  },
  AvgDialog_23844_Content_9 = {
    Text = "Fürchte dich nicht. Wir sind nicht die Bösewichte. Wenn es uns nicht gäbe, hättest du bereits in dem Ritual des schlangenartigen Typen verwendet werden sollen, oder?"
  },
  AvgDialog_23845_Content_1 = {
    Text = "Du schleichst über das Deck. Murphy, mit einem schmallippigen Ausdruck, weist auf das nahegelegene Brückenhaus und deutet darauf hin, dass sich der Maschinenraum darin befindet."
  },
  AvgDialog_23845_Content_10 = {
    Text = "Ein riesiges Schwert wird gewaltsam aus der Ferne auf dich geworfen, seine Kraft zerreißt die Luft und erzeugt eine gewaltsame Druckwelle."
  },
  AvgDialog_23845_Content_11 = {Text = "Vorsicht!"},
  AvgDialog_23845_Content_12 = {
    Text = "Mächtige Tentakeln wickeln sich um deine Taille und reißen dich von dem Punkt weg, an dem die riesige Klinge eingeschlagen hat."
  },
  AvgDialog_23845_Content_13 = {
    Text = "Seefahrer sind meistens körperlich schwach und hervorragend im Umgang mit leichten Waffen. Dieses Riesen-Schwert gehört einem anderen; gehe vorsichtig damit um."
  },
  AvgDialog_23845_Content_14 = {
    Text = "Physisch schwach... Ich stimme deiner Meinung über diese Typen zu."
  },
  AvgDialog_23845_Content_15 = {
    Text = "Aber als Frontkämpfer könnte jemand ohne Selbstbewusstsein nicht nützlicher sein."
  },
  AvgDialog_23845_Content_16 = {
    Text = "Der riesige Mann schleift seine lange Schwanzflosse, tritt den Seefahrer zu seinen Füßen beiseite und schreitet schwerfällig auf dich zu."
  },
  AvgDialog_23845_Content_17 = {
    Text = "Er zog das massive Schwert aus dem Deck, sein Ton gehässig, die Augen voller prüfendem Interesse, während er dich anstarrte."
  },
  AvgDialog_23845_Content_18 = {
    Text = "Ein Erwacher, der höher eingestuft ist als ein Seefahrer... Könnte diese Person auch Miryams Komplize sein?!"
  },
  AvgDialog_23845_Content_19 = {
    Text = "\"Miryams Komplize\"? Ugh, das klingt schrecklich."
  },
  AvgDialog_23845_Content_2 = {
    Text = "Solange du die Aufmerksamkeit der Seefahrer am Eingang ablenkst, kannst du völlig geräuschlos in das Gebäude schleichen..."
  },
  AvgDialog_23845_Content_20 = {
    Text = [[
Ich bin Goliath.
Denk daran, dies ist der Name dessen, der die Meere durchquert hat!]]
  },
  AvgDialog_23845_Content_3 = {
    Text = "Du nickst wissend und, während du in deiner Tasche nach etwas zum Werfen kramst, hörst du von weitem schwere Schritte nähern."
  },
  AvgDialog_23845_Content_4 = {
    Text = "Murphy schnappte nach Luft, ihr Gesicht voller Angst. Sie blickte sich um, hob dann plötzlich die Plane vom Kasten und kletterte hinein."
  },
  AvgDialog_23845_Content_5 = {
    Text = "<Small:Murphy?>"
  },
  AvgDialog_23845_Content_6 = {
    Text = "Die Box hallt nicht mehr oder bewegt sich, wie ein stummer schwarzer Loch, das Murphy verschlingt."
  },
  AvgDialog_23845_Content_7 = {
    Text = "Leise, jemand kommt."
  },
  AvgDialog_23845_Content_8 = {
    Text = "Den Wächter der Seefahrer mit einer alten Sprache zu beschwören, ist ohne Zweifel das Werk eines Riesen.\nVon deinem Winkel aus kannst du seine wahre Form nicht sehen, aber sein Schatten, der auf das Deck fällt, ist außergewöhnlich groß."
  },
  AvgDialog_23845_Content_9 = {
    Text = "So kolossal, dass es die Fähigkeit zu haben scheint, Berge zu ebnen und Sonne und Mond zu verschlingen—"
  },
  AvgDialog_23846_Content_1 = {
    Text = "Dieser Hafen ist riesig"
  },
  AvgDialog_23846_Content_10 = {
    Text = "Hoffe, dass es nicht die <Yellow:Katastrophen> sind, die dies verursacht haben..."
  },
  AvgDialog_23846_Content_2 = {
    Text = "Bleib wachsam, wir nähern uns dem Nordausgang"
  },
  AvgDialog_23846_Content_3 = {
    Text = "Nach dem ganzen Kampf stehen nur noch wenige Feinde vor euch.\nVor euch warten nur ein paar kleine Fische, die es abzuschütteln gilt"
  },
  AvgDialog_23846_Content_4 = {
    Text = "Diese Feinde... könnten sie von der Lichtkirche des Tempels geschickt worden sein?\nAndernfalls wäre es zu viel Zufall."
  },
  AvgDialog_23846_Content_5 = {
    Text = "Ich kann diese Möglichkeit nicht leugnen.\nAllerdings waren die Mitglieder der Tempel-Licht-Kirche, die wir in Lai Town getroffen haben, viel raffinierter."
  },
  AvgDialog_23846_Content_6 = {
    Text = "Diejenigen, die euch angreifen, sind die wahren „Kleinfische“ - mit gekrümmten menschenähnlichen Körpern und Fischköpfen unter zerlumpten Kapuzen"
  },
  AvgDialog_23846_Content_7 = {
    Text = "Jedes Mal, wenn sie angreifen, riecht man den Verfall des Lebens"
  },
  AvgDialog_23846_Content_8 = {
    Text = "Wir können die Bildhauervereinigung auch nicht ausschließen. Herbert ist ein Angeber, der mit dem Leben im Namen von Experimenten spielt."
  },
  AvgDialog_23846_Content_9 = {
    Text = "Ich mag deine Sicht auf Herbert. Aber vergiss nicht, dass die Auflösung ebenfalls solche massiven Mutationen hervorrufen kann"
  },
  AvgDialog_23847_Content_1 = {
    Text = "Du und Tulu versteckt euch in einer abgelegenen Ecke. Er bleibt wachsam, während du in eine traumähnliche Geisterwelt eintauchst."
  },
  AvgDialog_23847_Content_10 = {
    Text = "Gewöhnliche Menschen sind in der Geisterwelt normalerweise schwach. Ohne so viele Seefahrer wäre es einfach gewesen, Murphy auf einem verlassenen Geisterschiff zu finden."
  },
  AvgDialog_23847_Content_11 = {
    Text = "Die Geisterranken weben vergeblich durch die Schwarm von Seefahrern und stoßen tollpatschig gegen ein Licht nach dem anderen."
  },
  AvgDialog_23847_Content_12 = {
    Text = "<Gray:Murphys Geist... Welche ist wirklich sie...>"
  },
  AvgDialog_23847_Content_13 = {
    Text = "Während du Murphys Namen leise rezitierst, stimmt plötzlich eine ätherische Frauenstimme mit deiner Frequenz überein."
  },
  AvgDialog_23847_Content_14 = {
    Text = "Als ich meine Augen wieder öffnete, hatte sich der Bewusstseinsraum in eine andere Form verwandelt."
  },
  AvgDialog_23847_Content_15 = {
    Text = "Am Horizont erhebt sich eine verdrehte Stadt. Die chaotischen Geister können dich nicht mehr stören; alles ist still. Nur das düstere Licht vor dir strahlt eine ständige Kälte aus"
  },
  AvgDialog_23847_Content_16 = {
    Text = "Wer... ist das?"
  },
  AvgDialog_23847_Content_17 = {
    Text = "Lady Miryam, der Elworth-Altar wurde von diesen Abenteurern zerstört! Die Zeit der Ausrichtung ist vergangen; das, was erweckt werden muss..."
  },
  AvgDialog_23847_Content_18 = {
    Text = "<Gray:Lord Miryam... Ist dies wirklich Miryams Geisterwelt?!>"
  },
  AvgDialog_23847_Content_19 = {
    Text = "Das ist nicht die göttliche Mutter, die \"Mein Herr\" gebären kann! Dieses Ding ist nichts anderes als eine tötende Maschine!"
  },
  AvgDialog_23847_Content_2 = {
    Text = "Nachdem das vertraute Gefühl des Ertrinkens nachlässt, füllen unsichtbare Winde aus der Geisterwelt deinen Geist. Du öffnest deine Augen zu einer Geisterwelt, die sowohl vertraut als auch etwas fremd erscheint."
  },
  AvgDialog_23847_Content_20 = {
    Text = [[
...Egal, es ist nur wieder eine Wartezeit, bis die Sterne sich ausrichten.
Ich habe 5.000 Zyklen der Stellarrotation gewartet; was sind da noch ein Zyklus?]]
  },
  AvgDialog_23847_Content_21 = {
    Text = "Benachrichtige die Tempellichtkirche und entferne diesen fehlerhaften Gegenstand."
  },
  AvgDialog_23847_Content_22 = {Text = "Ja, ja"},
  AvgDialog_23847_Content_23 = {
    Text = "Ein neues Gefäß, um \"Mein Herr\"... Was soll ich tun?"
  },
  AvgDialog_23847_Content_24 = {
    Text = "Der aktuelle Container... Hast du nicht gesagt, dass er aufgrund des Eindringens des D-Phänomens weiteren 25 Jahren nicht standhalten kann?"
  },
  AvgDialog_23847_Content_25 = {
    Text = "Obwohl wir die Auflösung nicht sehen können, ist jeder Zeuge der Schwächung des Containers."
  },
  AvgDialog_23847_Content_26 = {
    Text = "Der neue Anwärter auf \"Mutter Gott\"..."
  },
  AvgDialog_23847_Content_27 = {
    Text = "Miryam sah auf das Mädchen, das am Pool döste. In der dunklen polarischen Eishöhle leuchtete das rosafarbene Haar des Mädchens voller lebendiger Energie."
  },
  AvgDialog_23847_Content_28 = {
    Text = "Umgeben von ihren Anhängern wiegte sie das schlafende Mädchen."
  },
  AvgDialog_23847_Content_29 = {
    Text = "Sie ging barfuß zum höchsten Punkt des Altars, auf den kalten Steinstuhl zu, der absoluten Ehre symbolisierte"
  },
  AvgDialog_23847_Content_3 = {
    Text = "<Gray: ...Ein Schiff?>"
  },
  AvgDialog_23847_Content_30 = {
    Text = "Sie fühlte die Wärme der Menschlichkeit. Nach einer Weile kam eine sanfte, aber klare Stimme von ihren Lippen."
  },
  AvgDialog_23847_Content_31 = {
    Text = "Der neue \"Mutter Gott\"... ist bereits von den Himmeln gewährt worden."
  },
  AvgDialog_23847_Content_32 = {
    Text = "Die niedergeknieten Kultisten brachen sofort in geflüsterte Gespräche aus."
  },
  AvgDialog_23847_Content_33 = {
    Text = "Heilige Murphy? Aber ist sie nicht..."
  },
  AvgDialog_23847_Content_34 = {
    Text = "Ja, sie ist die Adoptivtochter von Lady Miryam..."
  },
  AvgDialog_23847_Content_35 = {
    Text = "Selbst wenn die Tempellicht-Kirche vielleicht keine neuen Erwachungsmaterialien mehr bereitstellt, würde Lady Miryam nicht zulassen, dass Heiliger Murphy stirbt, oder...?"
  },
  AvgDialog_23847_Content_36 = {
    Text = "Ist die Hohepriesterin von Miryam nicht zu starrsinnig? Laut der Doktrin des Meeresspringens ist das Reich des Gottes seit zigtausend Jahren ausgestorben."
  },
  AvgDialog_23847_Content_37 = {
    Text = "Die Heilige Murphy ist unter den Augen aller aufgewachsen... Der Hohe Priester hat Jahrtausende gewartet, also wie viel mehr Zeit braucht man, um ein neues Gefäß zu finden?"
  },
  AvgDialog_23847_Content_38 = {
    Text = "Aber sie sagen, dass die Heilige beim letzten Align der Sterne geboren wurde, und niemand ist besser für diese Position geeignet..."
  },
  AvgDialog_23847_Content_39 = {
    Text = "Das Geschwätz erregte keine Reaktion von Miryam, aber Murphy wurde durch das Getümmel gestört und wachte langsam auf."
  },
  AvgDialog_23847_Content_4 = {
    Text = "Weisse Segel treiben am Horizont, rein, zerbrechlich und unbekannt."
  },
  AvgDialog_23847_Content_40 = {Text = "Das..."},
  AvgDialog_23847_Content_41 = {
    Text = "Miryam, w-was ist los? Warum hast du mich hierher getragen?"
  },
  AvgDialog_23847_Content_42 = {
    Text = "Miryam antwortete nicht, sondern streckte die Hand aus, um Murphys strähniges Haar zu ordnen."
  },
  AvgDialog_23847_Content_43 = {
    Text = "Sie sprach erneut, diesmal mit Bestimmtheit und Klarheit."
  },
  AvgDialog_23847_Content_44 = {
    Text = "\"Die Heilige Mutter\" ist angekommen! Sie wird aus @1 erwachen und die Ankunft von @2 verkünden!"
  },
  AvgDialog_23847_Content_45 = {
    Text = "Altar von Elworth, Abenteurerteam..."
  },
  AvgDialog_23847_Content_46 = {
    Text = "Könnte es Francis sein...!"
  },
  AvgDialog_23847_Content_47 = {
    Text = "Sobald der Gedanke aufkommt, durchdringt ein eisiger Schauer deinen Nacken. Wie der kalte Blick einer Schlange, die dich anstarrt, zieht es dich gewaltsam aus Miryams Geistwelt heraus."
  },
  AvgDialog_23847_Content_48 = {Text = "Hmm...!"},
  AvgDialog_23847_Content_49 = {
    Text = "Wie läuft es? Hast du es schon gefunden?"
  },
  AvgDialog_23847_Content_5 = {
    Text = "<Gray:Liegt es daran, dass der Sonanil sich in einem speziellen Bereich befindet, dass die Geisterwelt sich verändert hat?>"
  },
  AvgDialog_23847_Content_50 = {
    Text = "Eine unkonventionelle Flucht lässt dich schwindelig zurück, zwingt dich, dich an Tulus Tentakel festzuhalten, um dich zu stabilisieren."
  },
  AvgDialog_23847_Content_51 = {
    Text = "Ich brach in Miryams Geistwelt ein. Jetzt weiß sie, dass ich noch lebe."
  },
  AvgDialog_23847_Content_52 = {Text = "!?"},
  AvgDialog_23847_Content_53 = {
    Text = "Der Klang von Flossen, die über das Deck laufen, wird näher. Vielleicht hat Miryam die Geisterspur umgekehrt, aber jetzt umgeben dich die Seefahrer."
  },
  AvgDialog_23847_Content_54 = {
    Text = "Hey! Worauf wartest du? Komm mit mir!"
  },
  AvgDialog_23847_Content_55 = {
    Text = "Murphy stand an einer Tür und winkte dir zu."
  },
  AvgDialog_23847_Content_56 = {
    Text = "Du tauschst einen Blick mit Tulu aus und rennst in die Richtung, die sie anzeigt."
  },
  AvgDialog_23847_Content_57 = {
    Text = "Miryam sitzt an der höchsten Stelle der Brücke, mit halbgeschlossenen Augen, stützt ihren Kopf mit einer Hand und sieht erschöpft aus."
  },
  AvgDialog_23847_Content_58 = {
    Text = "Hey, es ist selten, diesen Ausdruck auf deinem Gesicht zu sehen. Was, willst du nicht mehr mit unserer Dame \"Haus spielen\"?"
  },
  AvgDialog_23847_Content_59 = {
    Text = "Sei nicht leichtfertig, Goliath."
  },
  AvgDialog_23847_Content_6 = {
    Text = "Zahlreiche Lichtpunkte treiben um das Schiff, als ob man in einen Sommerwaldteich mit rhythmisch quakenden Fröschen eintaucht, gleich Kriegstrommeln... Jeder Seefahrer hat sein eigenes Zeichen hinterlassen."
  },
  AvgDialog_23847_Content_60 = {
    Text = "Die göttliche Mutter... Ein Sterblicher kann dem Schicksal, das ich ihr auferlegt habe, nicht entkommen."
  },
  AvgDialog_23847_Content_61 = {
    Text = "So selbstsicher, und doch hast du all diese Mühe auf dich genommen, um mich hierher zu rufen? Ich war gerade erst im Verfolgungsrausch, nachdem ich diesem Kapitän gefolgt bin."
  },
  AvgDialog_23847_Content_62 = {
    Text = "......ein weiterer Student der Mythag Universität, {Male=er,Female=sie} lebt noch"
  },
  AvgDialog_23847_Content_63 = {
    Text = "Erledige {Male=er,Female=sie}, um sicherzustellen, dass {Male=er,Female=sie} nicht das Ritual stört, das Ritual muss zu diesem Sternen-Ausrichten stattfinden"
  },
  AvgDialog_23847_Content_64 = {
    Text = "\"<Mein Herr>\" wird heute Nacht wiedergeboren."
  },
  AvgDialog_23847_Content_7 = {
    Text = "<Gray:Beruhige dich, beruhige dich... Die Person, die mir am nächsten ist, ist Tulu, und die, die mit mir verbunden ist, ist Ramona...>"
  },
  AvgDialog_23847_Content_8 = {
    Text = "Im Dunkeln gibt es einige Lichter, die besonders hell leuchten, doch jede Verfolgung ist vergeblich, dein Geist wird von den Seefahrern aufgehalten, ohne einen Ausweg zu finden"
  },
  AvgDialog_23847_Content_9 = {
    Text = "<Gray:Bewege dich... Mach Platz.>"
  },
  AvgDialog_23848_Content_1 = {
    Text = "Die harte Sohle des Stiefels tritt auf den mutierten Körper und spritzt D-Slime überall auf den Boden."
  },
  AvgDialog_23848_Content_10 = {
    Text = "Oh, hast du nicht schon genug gefragt?"
  },
  AvgDialog_23848_Content_11 = {
    Text = "Murphy stampfte mit dem Fuß und zeigte auf dich, der von Tulu geschützt wurde."
  },
  AvgDialog_23848_Content_12 = {
    Text = "Ist der Gefährte dieses Typen nicht immer noch in den Händen der Seefahrer? Wenn du weiter zögerst und Zeit vergeudest und dieser Person etwas passiert, werde ich die Verantwortung nicht übernehmen."
  },
  AvgDialog_23848_Content_13 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23848_Content_14 = {
    Text = "Tulu schaute einen Moment seitlich zu dir, als würde er den Ausdruck auf deinem Gesicht beobachten."
  },
  AvgDialog_23848_Content_15 = {
    Text = "Ein gefährlicher Gefährte, ständige Kämpfe—Tulu ist ein wenig übermäßig angespannt.\nWir hoffen, du nimmst unsere Unhöflichkeit nicht übel."
  },
  AvgDialog_23848_Content_16 = {
    Text = "Bitte bringen Sie uns zum Kapitän, zu jemandem... der mir helfen kann, Ramona zu finden."
  },
  AvgDialog_23848_Content_2 = {
    Text = "Murphy senkte ihre Schaufel und schüttelte angewidert ihre Hand, als wollte sie den nicht existierenden D-Schleim loswerden."
  },
  AvgDialog_23848_Content_3 = {
    Text = "Puh... zum Glück ist es nicht der Seefahrer, sonst würde ich mich nicht trauen, zu handeln... \nDu bist so langsam. Lass uns gehen."
  },
  AvgDialog_23848_Content_4 = {
    Text = "Warte einen Moment."
  },
  AvgDialog_23848_Content_5 = {
    Text = "Tulus Ton ist kalt und hart, aber wenn du an das denkst, was er über die vielen Geheimnisse um Murphy gesagt hat, wählst du letztendlich, still zu bleiben."
  },
  AvgDialog_23848_Content_6 = {
    Text = "Obwohl es in diesen Kabinen, durch die Sie uns geführt haben, keine Spuren von Seefahrern gibt, werden die Aktivitäten der Auflösungsmutation mit zunehmender Tiefe häufiger."
  },
  AvgDialog_23848_Content_7 = {
    Text = "Du führst uns weiterhin an gefährliche Orte."
  },
  AvgDialog_23848_Content_8 = {
    Text = "Mutanten? ... Ah, meinst du diese Monster?"
  },
  AvgDialog_23848_Content_9 = {
    Text = "Der Kapitän sagte, dass dieses Schiff einst unter einer Katastrophe gelitten hat. Einige Seefahrer verwandelten sich in Monster, aber er konnte sich nicht bringen, sie zu eliminieren, also sperrte er die meisten von ihnen in die Kabinen."
  },
  AvgDialog_23849_Content_1 = {
    Text = "Der Luken wurde einen Spalt weit geöffnet, und brillantes Licht überschwemmte die dunkle Kabine."
  },
  AvgDialog_23849_Content_2 = {
    Text = "Ohne den umherirrenden <Seefahrer> könnte Sonanil tatsächlich zu einem abgeschiedenen Utopia werden..."
  },
  AvgDialog_23850_Content_1 = {
    Text = "Miss Ramona, Hüter! Hierher!"
  },
  AvgDialog_23850_Content_10 = {
    Text = "Überfallen uns diese Murlocs absichtlich?!"
  },
  AvgDialog_23850_Content_11 = {
    Text = "Der Fahrer ist kein Kämpfer, geh schnell weg!"
  },
  AvgDialog_23850_Content_12 = {
    Text = "Gut, okay. Bitte sei sehr vorsichtig!"
  },
  AvgDialog_23850_Content_13 = {
    Text = "Der Fahrer sprang zurück ins Auto, das Motorgeräusch zog die Aufmerksamkeit vieler Feinde auf sich"
  },
  AvgDialog_23850_Content_14 = {
    Text = "Hey! Schau in den Sternenhimmel, hierher!"
  },
  AvgDialog_23850_Content_2 = {
    Text = "Der Fahrer!"
  },
  AvgDialog_23850_Content_3 = {
    Text = "Ein bekannter Mann mittleren Alters rüttelte ungeduldig an der Kette der Tür und sah besorgt aus"
  },
  AvgDialog_23850_Content_4 = {
    Text = "Die Tür ist verschlossen. Was sollen wir tun?"
  },
  AvgDialog_23850_Content_5 = {
    Text = "Kein Problem. Ich werde die Kette direkt durchtrennen. Bitte tritt zurück."
  },
  AvgDialog_23850_Content_6 = {
    Text = "Der Fahrer trat ein paar Schritte zurück, um der Schneide des Schwertes auszuweichen. Ramona hob ihre Waffe an die Brust, atmete tief ein und stürmte voran—"
  },
  AvgDialog_23850_Content_8 = {
    Text = "Das Rascheln wird lauter, als Dinge nacheinander aus den Schatten hervortreten, wodurch die Luft noch dampfiger und schwerer wird."
  },
  AvgDialog_23850_Content_9 = {
    Text = "Ein fischförmiger Feind blockiert den Weg zwischen dir und dem Eisentor. Erschrocken stößt der Fahrer einen Schrei aus und setzt sich auf die Motorhaube."
  },
  AvgDialog_23851_Content_1 = {
    Text = "So unglaubliche Macht...! Selbst nach den Maßstäben eines Erwachten ist es erschreckend."
  },
  AvgDialog_23851_Content_10 = {
    Text = "Maniacal laughter echoes in the Bereich, and the atmosphere becomes increasingly tense."
  },
  AvgDialog_23851_Content_11 = {
    Text = "Sei nicht so angespannt. Ich habe nicht vor, hier mit dir umzugehen."
  },
  AvgDialog_23851_Content_12 = {
    Text = "Die inkompetenten Mitglieder der Tempellicht-Kirche konnten nicht einmal einfache Wachaufgaben bewältigen, wodurch dieser kleine Wicht hereinschlüpfen konnte... Doch dank ihres Versagens ist das Ritual nun spannender geworden."
  },
  AvgDialog_23851_Content_13 = {
    Text = "Tempellicht-Kirche... Arbeiten die Seefahrer und die Tempellicht-Kirche tatsächlich zusammen?"
  },
  AvgDialog_23851_Content_14 = {
    Text = "Ha? Gruppiere mich nicht mit diesen Wahnsinnigen. Die Seefahrer-Formen sind nicht geeignet, die Welt zu betreten, dennoch gieren sie nach unserer Macht... Nur eine Menge Sonderlinge, die sich gegenseitig zur Wärme benutzen."
  },
  AvgDialog_23851_Content_15 = {
    Text = "Nicht nur verbunden mit der Tempel Licht Kirche, sondern auch mit dem <Blue:Ritual>, das du erwähnt hast..."
  },
  AvgDialog_23851_Content_16 = {
    Text = "Goliath... wer bist du wirklich?"
  },
  AvgDialog_23851_Content_17 = {
    Text = "Wer bin ich? Hahahaha! Warum fragst du nicht die Person neben dir?"
  },
  AvgDialog_23851_Content_18 = {
    Text = "Ich, und diese Seefahrer, woher kommen sie—Sie können es sich doch denken, oder? Schließlich sind Sie der Allmächtige"
  },
  AvgDialog_23851_Content_19 = {
    Text = "Übertreten!"
  },
  AvgDialog_23851_Content_2 = {
    Text = "Diese Kraft"
  },
  AvgDialog_23851_Content_20 = {
    Text = "Wirklich erschreckend, wirklich erschreckend – aber leider bin ich nicht einer deiner treuen Untertanen"
  },
  AvgDialog_23851_Content_21 = {
    Text = "Ich muss mich weiter auf das Ritual vorbereiten, keine Zeit für euch"
  },
  AvgDialog_23851_Content_22 = {
    Text = "Versteck dich mit deinen Tentakeln, aber du weißt, dass nur du geben kannst, was diese Frau will"
  },
  AvgDialog_23851_Content_23 = {
    Text = "Der Stellvertreter, der die Macht dieses inkompetenten Gottes geerbt hat... Ugh!"
  },
  AvgDialog_23851_Content_24 = {
    Text = "Bevor die spöttischen Worte verklangen, tauchte plötzlich ein lila Schatten aus der Narbe an Goliaths Hals auf. Er wickelte sich wie ein Schal um seinen Hals und nahm schließlich die Form einer Schlange an."
  },
  AvgDialog_23851_Content_25 = {
    Text = "Goliaths Gesicht verzog sich beim Anblick des Schattens der Schlange, während ihre Fangzähne in die Narbe an seinem Hals eindrangen."
  },
  AvgDialog_23851_Content_26 = {
    Text = "Unter den verflochtenen Auswirkungen von Schmerz und Gift erschien ein verzerrtes Lächeln auf seinem Gesicht, seine haifischartigen scharfen weißen Zähne zitterten vor Aufregung."
  },
  AvgDialog_23851_Content_27 = {
    Text = "Ha, ha... Diese Frau ist so kleinlich. Sie kann die geringste Beleidigung gegenüber ihrem schwer fassbaren Gott nicht ertragen."
  },
  AvgDialog_23851_Content_28 = {
    Text = "Nur ein nutzloser, herzloser Feigling... Haah!"
  },
  AvgDialog_23851_Content_29 = {
    Text = "Der Serpentenschatten riss an Goliaths Hals, beugte den Rücken des Riesen in einen Bogen und zwang ihn, sich in eine liegende Position zu begeben."
  },
  AvgDialog_23851_Content_3 = {
    Text = "Miryam teilte die Macht, die ihr gewährt wurde, mit dir."
  },
  AvgDialog_23851_Content_30 = {
    Text = "Ist das alles, was du hast?!"
  },
  AvgDialog_23851_Content_31 = {
    Text = "Dich mit unverständlichen Glaubenssätzen zu kontrollieren, erlaubt den Katastrophen, die Zivilisation zu zerstören... Ha, am Ende hat Er nie existiert; das ist nur deine Vorstellung!"
  },
  AvgDialog_23851_Content_32 = {
    Text = "Der Schatten der Schlange zog sich plötzlich zusammen, und Goliath hustete, wobei er ein paar Tropfen Blut ausspuckte."
  },
  AvgDialog_23851_Content_33 = {
    Text = "Was... was macht er?"
  },
  AvgDialog_23851_Content_34 = {
    Text = "Eine alte Strafe... genutzt in Lemuria, um die Ungläubigen und Gefangenen zu disziplinieren und zu zähmen."
  },
  AvgDialog_23851_Content_35 = {
    Text = "Tulu sah Goliath an, der immer noch mit einem wilden Lächeln dastand, und seufzte."
  },
  AvgDialog_23851_Content_36 = {
    Text = [[
Hat Miryam das eingerichtet?
...Warte! Bedeutet das, dass sie unseren Aufenthaltsort kennt?!]]
  },
  AvgDialog_23851_Content_37 = {
    Text = "Ha, keine Notwendigkeit, so angespannt zu sein."
  },
  AvgDialog_23851_Content_38 = {
    Text = "Goliath stützte sich mit seinem riesigen Schwert ab und stand auf.\nEr wischte sich mit dem Handrücken das Blut vom Gesicht, als ob die Strafe nur ein Kratzer wäre."
  },
  AvgDialog_23851_Content_39 = {
    Text = "Es ist nichts als eine Leine für die Arroganten und Selbstgerechten."
  },
  AvgDialog_23851_Content_4 = {
    Text = "Oh? Wie kann ein kleiner Zwerg wie du..."
  },
  AvgDialog_23851_Content_40 = {
    Text = "Ihr geht alle voraus. Lasst euch nicht von zufälligen Mobs besiegen, bevor ich meinen Spaß hatte."
  },
  AvgDialog_23851_Content_41 = {
    Text = "—Goliath, warte!"
  },
  AvgDialog_23851_Content_42 = {
    Text = "Oh? Was brauchen Sie sonst? Ich mag Menschen, die den Mut haben, Autorität herauszufordern. Sie haben noch eine Frage, bevor ich die Geduld verliere."
  },
  AvgDialog_23851_Content_43 = {
    Text = "Ramona... Wie geht es meinem Partner jetzt? Was wirst du mit ihr machen?"
  },
  AvgDialog_23851_Content_44 = {
    Text = [[
Ha... Lass mich klarstellen: Ich habe kein Interesse daran, Frauen zu schaden.
Verschone ihr Leben, es ist Miryams Befehl.]]
  },
  AvgDialog_23851_Content_45 = {
    Text = "Die gegenwärtige \"Muttergott\"... ein Gefäß zur Geburt neuer Götter, ist lediglich ein bedeutungsloses, gelbhaariges Kind. Mit dem Status der \"Muttergott\" kann sie das erste Geschrei des neuen Gottes nicht unterdrücken."
  },
  AvgDialog_23851_Content_46 = {
    Text = "Der Schatten der Schlange verschwand, als er aufhörte, den \"Gott\" zu verfluchen. Er drehte seinen Hals ein paar Mal, hob seine massive Klinge und ging weg, völlig unbesorgt darüber, dir den Rücken zu zeigen."
  },
  AvgDialog_23851_Content_47 = {
    Text = "—Bevor er sich umdrehte, hast du ihn klar auf die Kiste schauen sehen, in der Murphy sich versteckte."
  },
  AvgDialog_23851_Content_5 = {
    Text = "Tulus Zögern war offensichtlich, und der Riese hielt seinen Angriff an, scheinbar tief in Gedanken versunken.\nEr schielte, um Tulu zu mustern, sein Blick ruhte schließlich auf der extravaganten Krone."
  },
  AvgDialog_23851_Content_6 = {
    Text = "Das Design dieser Krone ist...!"
  },
  AvgDialog_23851_Content_7 = {
    Text = "Goliaths Pupillen verengten sich, als er dich mit einem nackten und durchdringenden Blick fixierte, dann brach er in ungebremstes Lachen aus."
  },
  AvgDialog_23851_Content_8 = {
    Text = "Ha, hahaha! Fesselnd, absolut fesselnd!"
  },
  AvgDialog_23851_Content_9 = {
    Text = "Ich frage mich, welchen Ausdruck diese Frau hätte, wenn sie diese Szene sehen würde – würde sie sofort verrückt werden? Hahaha, ich kann diesen Moment kaum erwarten!"
  },
  AvgDialog_23852_Content_1 = {
    Text = "Auge des Sturms"
  },
  AvgDialog_23852_Content_10 = {
    Text = "Augen auf, Kopfschmerzen, fremder Ort"
  },
  AvgDialog_23852_Content_100 = {
    Text = "Tulu fegte ein weiteres Murloc-Monster vom Deck und drehte sich schließlich zu dir um.\nEr griff nach dem Türrahmen, aber seine nächste Bewegung überraschte dich."
  },
  AvgDialog_23852_Content_101 = {
    Text = "Kein Problem, du gehst weiter und triffst dich mit den anderen.\nIch muss überprüfen, warum sie das Ritual nicht abgebrochen haben."
  },
  AvgDialog_23852_Content_102 = {
    Text = "Die eiserne Tür schlägt zu und stürzt dich und das Mädchen in totale Dunkelheit."
  },
  AvgDialog_23852_Content_103 = {
    Text = "Das Mädchen ließ ein herausforderndes Schnauben hören, drehte geschickt die Winde und verriegelte die Tür."
  },
  AvgDialog_23852_Content_104 = {
    Text = "Puh— Vorübergehend sicher"
  },
  AvgDialog_23852_Content_105 = {
    Text = "Das Mädchen drückte den Schalter, und nach ein paar Flackern gab die alte Lampe ihr Licht ab und vertrieb die Dunkelheit."
  },
  AvgDialog_23852_Content_106 = {
    Text = "Und du siehst endlich die \"Seetang\" unter dir."
  },
  AvgDialog_23852_Content_107 = {
    Text = "Dein Körper und Geist fühlen sich an, als seien sie in die dunkelste Lava der Hölle gesunken; es ist definitiv kein Seegras.\nDie Basis deiner Hand drückt in einen dunkelroten Morast unbekannter Substanzen, schmerzend durch die scharfen Knochenfragmente."
  },
  AvgDialog_23852_Content_108 = {
    Text = "Die mysteriösen Runen waren durch die Flüssigkeit verschwommen und ähnelten den lebhaften Teppichen eines Tanzsaals – offensichtlich hatte eine kleine heidnische Zeremonie stattgefunden."
  },
  AvgDialog_23852_Content_109 = {
    Text = "Der Gestank erfüllt die Kabine, und du bist dir sicher, dass die verrottenden Fischreste allein nicht für einen solchen Geruch verantwortlich sein können. In diesem Caro-gewebten Tanz müssen größere, dickere Tänzer vorhanden sein."
  },
  AvgDialog_23852_Content_11 = {
    Text = "Wie oft ist das bereits vorgekommen? Können wir nicht einen kreativeren Anfang finden?"
  },
  AvgDialog_23852_Content_110 = {Text = "Ugh..."},
  AvgDialog_23852_Content_111 = {
    Text = "Es ist klar das Werk der Seefahrer, die immer nachlässig waren..."
  },
  AvgDialog_23852_Content_112 = {
    Text = "Das Mädchen murmelte und sah dich mit Verachtung liegen auf dem Altar an. Doch sie umkreiste dich zweimal und hob dich schließlich an deinem noch sauberen Arm hoch"
  },
  AvgDialog_23852_Content_113 = {
    Text = "Mit Tulu in der Nähe werden sie nicht die Gelegenheit haben, uns eine Weile zu verfolgen...\nIch werde ein Tuch finden, um diesen Altar zu bedecken; er riecht furchtbar."
  },
  AvgDialog_23852_Content_114 = {
    Text = "Deine Schläfen pochen mit jedem Schlag, heftige Schmerzen reißen durch beide Seiten deines Gehirns. Der Gestank lässt Magenflüssigkeit in deinen Hals steigen, und schließlich beugst du dich vor, würgst unkontrolliert."
  },
  AvgDialog_23852_Content_115 = {
    Text = "Huh?! Was ist los?! Mach, mach mich nicht verrückt!"
  },
  AvgDialog_23852_Content_116 = {
    Text = "Bleib zurück!!"
  },
  AvgDialog_23852_Content_117 = {
    Text = "Ich bin nicht irgendein kleines Mädchen; ich habe einen Namen."
  },
  AvgDialog_23852_Content_118 = {
    Text = "Murphy, nenn mich einfach Murphy."
  },
  AvgDialog_23852_Content_119 = {
    Text = "Das ängstliche Gesicht des Mädchens und die in ihrem Kopf aufblinkenden Fragmente verschmelzen langsam miteinander, zwei ähnliche, doch verschiedene Szenen verbinden sich zu einem einzigen Bild"
  },
  AvgDialog_23852_Content_12 = {
    Text = "Du hast dich gezwungen aufzustehen, und plötzlich kam eine unvorhergesehene Szene in Sicht."
  },
  AvgDialog_23852_Content_120 = {Text = "Murphy...?"},
  AvgDialog_23852_Content_121 = {
    Text = "Bist du... in Ordnung? Hat dich der Altar krank gemacht?"
  },
  AvgDialog_23852_Content_122 = {
    Text = "Sie umrundete dich zweimal und schlich dann auf Zehenspitzen, um deinen Zustand im schwachen Licht zu überprüfen."
  },
  AvgDialog_23852_Content_123 = {Text = "—!"},
  AvgDialog_23852_Content_124 = {
    Text = "Wie bin ich so geworden...  \nEs scheint, als gäbe es einige nützliche Dinge in dieser Ladung Waren..."
  },
  AvgDialog_23852_Content_125 = {
    Text = "Murphy murmelte unverständlich, bewegte sich steif zu den gestapelten Kisten und suchte nach etwas"
  },
  AvgDialog_23852_Content_126 = {
    Text = "Falsch... Diese Kiste enthält kaputten Schmuck"
  },
  AvgDialog_23852_Content_127 = {
    Text = "Du blickst darauf und siehst ein Schmuckset, das mit Korallen, Perlen und Lapislazuli eingelegt ist und recht wertvoll erscheint. Doch der geheimnisvolle Designstil macht dir schon beim Hinsehen schwindelig."
  },
  AvgDialog_23852_Content_128 = {
    Text = "...Verdammtes, sie sind alle rituelle Gegenstände."
  },
  AvgDialog_23852_Content_129 = {
    Text = "Die zweite Kiste ist mit verschiedenen Restsachen gefüllt: Steinschalen, Salbei, Myrrhe... Ohne Wissen über Alchemie könnte man es für Waren eines Händlers halten."
  },
  AvgDialog_23852_Content_13 = {
    Text = "Der riesige Vollmond hängt am Nachthimmel, ein Nebelschleier umhüllt das Meer, Rauch und Salzluft füllen die Nase"
  },
  AvgDialog_23852_Content_130 = {
    Text = "Gefunden! Schnell, du geh in die Hocke"
  },
  AvgDialog_23852_Content_131 = {
    Text = "Der Paste wurde auf den Hinterkopf aufgetragen, was ein kühles, aber leicht würziges Gefühl hervorrief, das den Schmerz bis zu einem gewissen Grad linderte. Unter dem Einfluss des Salbes wurde dein Haar klebrig und klumpte zusammen, was dich dazu verleitet, instinktiv die Hand zu heben, um es zu glätten—"
  },
  AvgDialog_23852_Content_132 = {
    Text = "Hey! Fass das nicht zufällig an! Es ist nicht so, als ob es Gift oder so wäre."
  },
  AvgDialog_23852_Content_133 = {
    Text = "Murphy reicht dir ein Glas Salbe. Das Etikett trägt keine Formel oder Namen, nur ein seltsames Symbol, das eindeutig angibt, dass es hausgemacht ist."
  },
  AvgDialog_23852_Content_134 = {
    Text = "Ist das déjà vu? Das Muster auf dem Etikett kommt mir bekannt vor."
  },
  AvgDialog_23852_Content_135 = {
    Text = "Seit meiner Kindheit, wenn ich eine äußere Verletzung hatte, haben sie mir immer dieses Medikament aufgetragen."
  },
  AvgDialog_23852_Content_136 = {
    Text = "Wie ist es? Geht der Schmerz nicht sofort weg, wenn du es anwendest?"
  },
  AvgDialog_23852_Content_137 = {
    Text = "Sie war sehr besorgt, dass du die Treppe hinuntergefallen und dir den Kopf gestoßen hast, und ihr Blick war voller Schuldgefühle"
  },
  AvgDialog_23852_Content_138 = {
    Text = "Hmm... Es tut nicht mehr weh."
  },
  AvgDialog_23852_Content_139 = {
    Text = "Die Tempel pulsieren noch leicht, aber der Hinterkopf fühlt sich etwas angenehmer an."
  },
  AvgDialog_23852_Content_14 = {
    Text = "Der sanfte und rhythmische Klang der Wellen, die gegeneinander drücken, trägt das Boot sanft in eine unbekannte Richtung."
  },
  AvgDialog_23852_Content_140 = {
    Text = "Dein Blick kann nicht anders, als sich auf den \"Altar\" zu richten, in den du gekracht bist. Murphy, aus Angst, dass du dich wieder übergeben könntest, hatte ihn bereits mit einem Tuch bedeckt."
  },
  AvgDialog_23852_Content_141 = {
    Text = "In diesem Moment vermischten sich die karminroten und graugrünen Flüssigkeiten und bildeten eine bizarre Form auf dem Jutegewebe. Es ähnelte einem seltsamen Dolch oder einem Neugeborenen, das bereit war, seinen ersten Schrei auszulassen."
  },
  AvgDialog_23852_Content_142 = {
    Text = "Siehst du, ich habe es dir gesagt, es funktioniert"
  },
  AvgDialog_23852_Content_143 = {
    Text = "Nach einer bejahenden Antwort entspannten sich Murphy endlich und lächelte.\nAls du sie entspannt siehst, sagt eine Stimme in dir —"
  },
  AvgDialog_23852_Content_144 = {
    Text = "Sie ist das Zentrum des Sturms; sie ist die Antwort auf jede Frage."
  },
  AvgDialog_23852_Content_15 = {
    Text = "Auf dem Schiff?!"
  },
  AvgDialog_23852_Content_16 = {
    Text = "Kein Zweifel, du bist auf einem Schiff mitten im Ozean. Ramona ist nicht an deiner Seite, und es gibt kein Zeichen von jemandem in der Nähe."
  },
  AvgDialog_23852_Content_17 = {
    Text = [[
Ruhig, ruhig.
Denke von Anfang an, warum bin ich auf diesem Schiff]]
  },
  AvgDialog_23852_Content_18 = {
    Text = "Herberts Notizen... Muster... Franciss Tagebuch... der Hafen..."
  },
  AvgDialog_23852_Content_19 = {
    Text = "Bereit, dann lass uns loslegen, ich werde wie immer dein Partner sein"
  },
  AvgDialog_23852_Content_2 = {
    Text = "Hüter! Lass meine Hand nicht los!"
  },
  AvgDialog_23852_Content_20 = {
    Text = "Diese Runde... die Kirche... Geheimnis... du musst—"
  },
  AvgDialog_23852_Content_21 = {Text = "...Ugh!"},
  AvgDialog_23852_Content_22 = {
    Text = "Gerade an einige fragmentierte Szenen erinnernd, zerreißt starker Schmerz dein Gedächtnis.\nMagensäure-Reflux brennt deinen Hals und macht frische Luft zu einem Luxus."
  },
  AvgDialog_23852_Content_23 = {
    Text = "Puh—ich habe die Schule mit Ramona verlassen... Ja, Ramona, ich muss sie finden.\nWenn es sie ist, wird sie definitiv wissen, was passiert ist."
  },
  AvgDialog_23852_Content_24 = {
    Text = "Verknüpfungs-Kommunikator"
  },
  AvgDialog_23852_Content_25 = {
    Text = "Ramona, kannst du mich hören? Wo bist du?"
  },
  AvgDialog_23852_Content_26 = {
    Text = "Die Schmerzen tief in deiner Seele ignorierend, hast du den Silberkommunikator wie gewohnt bedient."
  },
  AvgDialog_23852_Content_27 = {
    Text = "In diesem Moment wird dir klar, dass die <Yellow:Anstecknadel>, die deinen Status symbolisiert, nicht mehr an deinem Revers ist."
  },
  AvgDialog_23852_Content_28 = {
    Text = "Wie könnte das sein?!"
  },
  AvgDialog_23852_Content_29 = {
    Text = [[
Beruhige dich, beruhige dich...
Es gibt noch einen Weg. Versuche den Geisterspuren.]]
  },
  AvgDialog_23852_Content_3 = {
    Text = "Die Spitze der Nase wird von dem stechenden Gestank verbrannten Kohlen erfüllt. Nach einer kurzen Berührung wird ein Handschuh mit Gewalt von der Schwerkraft in den Abgrund gezogen."
  },
  AvgDialog_23852_Content_30 = {
    Text = "Du nimmst einen tiefen Atemzug, ignorierst das Unbehagen und tauchst zurück in die Tiefen deines Geistes."
  },
  AvgDialog_23852_Content_31 = {
    Text = "Die Geisterwelt funkelt mit unzähligen Lichtpunkten, die jeweils eine lebendige Seele darstellen—weit über eure Vorstellung hinaus."
  },
  AvgDialog_23852_Content_32 = {
    Text = "So viele Menschen an Bord? Seltsam..."
  },
  AvgDialog_23852_Content_33 = {
    Text = "Deine Neugier und ein wenig unerkannte Angst unterdrückend, konzentrierst du dich auf dich selbst.\nDie \"Verknüpfung\" ist wie eine kräftige Nabelschnur, die zwei außergewöhnlich brillante Geister zu dir zieht."
  },
  AvgDialog_23852_Content_34 = {
    Text = "Zwei Verknüpfungen? Neben Ramona, ist noch jemand anders dieser Mission beigetreten?"
  },
  AvgDialog_23852_Content_35 = {
    Text = "Dein Peek hat eine Welle verursacht und eines der Gnosis gestört. Bevor du weiter untersuchen konntest, drehte es sich langsam um und fixierte schließlich deine Position."
  },
  AvgDialog_23852_Content_36 = {
    Text = "Ein plötzlicher Schauer läuft dir den Rücken hinunter, als das unbekannte Verknüpfungsziel auf dich zustürzt, bevor du reagieren kannst!"
  },
  AvgDialog_23852_Content_37 = {
    Text = "Keine Zeit nachzudenken, wer oder was am anderen Ende der Verknüpfung ist, treibt dich instinktiv dazu, dich aus der Geisterwelt zurückzuziehen, in die entgegengesetzte Richtung zu bewegen"
  },
  AvgDialog_23852_Content_38 = {Text = "—!"},
  AvgDialog_23852_Content_39 = {
    Text = "Zufällig gibt der Rumpf einen scharfen Schrei von sich, in dem Moment, in dem du darauf trittst, wie das Sterbegeläut eines Stahlbiests, das auf seine bevorstehende Unterwerfung unter das Meer hinweist."
  },
  AvgDialog_23852_Content_4 = {
    Text = "Ein vertrauter Stimme und die Wärme dieser Person verblassten schnell und wurden ersetzt durch eine kriechende Feuchtigkeit und Kälte, die meinen Rücken hinaufkrabbelte."
  },
  AvgDialog_23852_Content_40 = {
    Text = [[
In dieser Situation tauche in die Geisterwelt ein und betrachte Krisen als nichts.  
Sorglos und arrogant]]
  },
  AvgDialog_23852_Content_41 = {
    Text = "Weiche, kühle Tentakeln, wie orangene Pulpe, fangen deinen fast aus dem Gleichgewicht geratenen Körper auf und halten dich stabil."
  },
  AvgDialog_23852_Content_42 = {
    Text = "Ich habe nie erwartet, dass du so rücksichtslos bist."
  },
  AvgDialog_23852_Content_43 = {Text = "Tulu?!"},
  AvgDialog_23852_Content_44 = {Text = "Du..."},
  AvgDialog_23852_Content_45 = {
    Text = "Warum bist du wach?"
  },
  AvgDialog_23852_Content_46 = {
    Text = "Der erwachte Junge warf dir einen ruhigen, aber respektvollen Blick zu"
  },
  AvgDialog_23852_Content_47 = {
    Text = "Diese Respektlosigkeit überhöre ich"
  },
  AvgDialog_23852_Content_48 = {
    Text = "Was machst du hier?"
  },
  AvgDialog_23852_Content_49 = {
    Text = "Der erwachte Junge hob überrascht die Augenbrauen und musterte dich prüfend"
  },
  AvgDialog_23852_Content_5 = {Text = "Hüter!"},
  AvgDialog_23852_Content_50 = {
    Text = "Und du kannst noch scherzen, scheint dir geht's gut"
  },
  AvgDialog_23852_Content_51 = {
    Text = "Das kurze Verschwinden der Verknüpfung war nur vorübergehende Verwirrung, verursacht durch Gnosis-Interferenz."
  },
  AvgDialog_23852_Content_52 = {
    Text = "Wie Lotan und Ogier ist Tulu einer der vielen Erwecker unter der Aufsicht von <Yellow:Mythag>.\nWährend deines Ausbildungsjahres bei Mythag hast du ihn jedoch nur ein paar Mal gesehen."
  },
  AvgDialog_23852_Content_53 = {
    Text = "Es wird gesagt, dass Tulu die meiste Zeit schläft und nur zu seltenen Gelegenheiten aufwacht. Ihn als Begleitung für Ermittler auf Missionen zu haben, ist nichts anderes als ein Traum."
  },
  AvgDialog_23852_Content_54 = {
    Text = "In diesem Moment bist du von einer unsichtbaren <Yellow:Verknüpfung> fest gebunden, und Tulus sturmartige Gnosis wäscht kontinuierlich über deinen Geist."
  },
  AvgDialog_23852_Content_55 = {
    Text = "Verknüpfung verschwunden? Nein... Was ist überhaupt mit unserer Verbindung los? Und warum bist du nicht auf dem Campus?"
  },
  AvgDialog_23852_Content_56 = {
    Text = "Törichte Frage. Es ist jetzt keine Zeit für Witze; das Mädchen hat nicht mehr viel Zeit.\nDie Seefahrer haben das Beschwörungsritual nicht aufgegeben, <Yellow:die Sterne steigen in ihre bestimmten Positionen>."
  },
  AvgDialog_23852_Content_57 = {
    Text = "Dieses Mädchen? Das Ritual des Beschwörens?"
  },
  AvgDialog_23852_Content_58 = {
    Text = "Die Atmosphäre zwischen dir und Tulu wird plötzlich angespannt. Nach einem Moment gibt er einen tiefen Seufzer von sich, sein ernster Ausdruck steht im Widerspruch zu seinem jugendlichen Gesicht."
  },
  AvgDialog_23852_Content_59 = {
    Text = "Wie viel erinnerst du dich?"
  },
  AvgDialog_23852_Content_6 = {
    Text = "War das... ein Traum?"
  },
  AvgDialog_23852_Content_60 = {
    Text = "Ramona und ich haben die Schule verlassen, um die Untersuchung durchzuführen. Was den Rest betrifft..."
  },
  AvgDialog_23852_Content_61 = {
    Text = "Du schütteltest den Kopf. Du bist dir unsicher, ob eine äußere Kraft dich beeinflusst hat, aber eines ist sicher: Dein Körper hindert dich daran, dich an sie zu erinnern."
  },
  AvgDialog_23852_Content_62 = {
    Text = "„Die Sterne steigen dorthin auf, wo sie hingehören“ – das bedeutet, dass du die Bedingungen des Rituals kennst"
  },
  AvgDialog_23852_Content_63 = {
    Text = "Beschwörungsritual – Was ist das? Und was sind diese Fischmenschen?"
  },
  AvgDialog_23852_Content_64 = {
    Text = "Auch wenn ich mich nicht an das Geschehen erinnern kann, lügt diese Verknüpfung nicht. Wir sollten auf derselben Seite sein – Tulu, ich brauche dich, um mir zu sagen, was wirklich passiert ist."
  },
  AvgDialog_23852_Content_65 = {
    Text = "Tulu wirkte etwas müde. Er schloss die Augen und schien etwas Zeit zu brauchen, um seine Gedanken zu sammeln."
  },
  AvgDialog_23852_Content_66 = {
    Text = "Es war mein Fehler, deine Veränderung nicht zu bemerken.\nIn ein solches Ereignis verwickelt zu werden, hat dich als Mensch offensichtlich beeinflusst"
  },
  AvgDialog_23852_Content_67 = {
    Text = "Aber das „Ritual des Abstiegs“ ist ein hochsensibles Schlüsselwort für die Hüter der Mythag. \nGerade als du weiter drängen wolltest, kreuzte Tulus Tentakel plötzlich vor dir."
  },
  AvgDialog_23852_Content_68 = {
    Text = "Jemand kommt, bleib auf hoher Alarmbereitschaft."
  },
  AvgDialog_23852_Content_69 = {Text = "Plump..."},
  AvgDialog_23852_Content_7 = {
    Text = "Ist es schon Morgen... ?"
  },
  AvgDialog_23852_Content_70 = {
    Text = "Inmitten der hastigen Schritte mischte sich ein seltsames Geräusch, das dem Klatschen von Paddeln auf den Boden ähnelte, und du spürtest leichte Erschütterungen unter deinen Füßen. Eine Gestalt stürmte von der anderen Seite des Decks auf dich zu."
  },
  AvgDialog_23852_Content_71 = {
    Text = "Goo... Schluck..."
  },
  AvgDialog_23852_Content_72 = {
    Text = "Waaah—Hilfe—"
  },
  AvgDialog_23852_Content_73 = {
    Text = "Hilf mir!! %player%!"
  },
  AvgDialog_23852_Content_74 = {
    Text = "Das Mädchen stürmte zu deiner Seite, schnaufte schwer und hielt den Saum deines Umhangs wie einen Lebensretter fest."
  },
  AvgDialog_23852_Content_75 = {
    Text = "Immer noch...@2...@1 Mutter! @2!"
  },
  AvgDialog_23852_Content_76 = {
    Text = "Diese humanoiden Körper, die Merkmale des aquatischen Lebens besitzen, stießen seltsame Wimmerlaute aus. Die Geräusche waren ungeordnet und durchdringend, doch du verstandest irgendwie deren Bedeutung."
  },
  AvgDialog_23852_Content_77 = {
    Text = "Sie sagen... „Gib uns zurück“?"
  },
  AvgDialog_23852_Content_78 = {
    Text = "Das ungeordnete Brüllen wird in deinen Ohren klarer.\nNur ein wenig mehr, und du wirst verstehen, was sie wollen—"
  },
  AvgDialog_23852_Content_79 = {
    Text = "In einem Moment der Ablenkung tritt das Mädchen hart auf deinen Schuh"
  },
  AvgDialog_23852_Content_8 = {
    Text = "Jeder Knochen fühlt sich an, als wäre er zerbrochen und wieder zusammengesetzt worden, mein ganzer Körper ist von einer unzeitgemäßen Müdigkeit überwältigt.\nMeine Schläfen pochen, und meine Augen fühlen sich trocken und stechen an, als wären sie von Nadeln gestochen worden."
  },
  AvgDialog_23852_Content_80 = {Text = "Zisch—"},
  AvgDialog_23852_Content_81 = {
    Text = "Willst du nur zusehen? Tu etwas!"
  },
  AvgDialog_23852_Content_82 = {
    Text = "Und du! Hör auf, mich anzustarren und konzentriere dich, Fräulein! Sei vorsichtig, dass du nicht von ihnen gefangen wirst."
  },
  AvgDialog_23852_Content_83 = {
    Text = "Tulu wendet sich ab und blickt nicht mehr auf dich und das Mädchen. Seine Tentakel schwingen kraftvoll und fegen die herannahenden Feinde einer nach dem anderen vom Schiff."
  },
  AvgDialog_23852_Content_84 = {
    Text = "Verstärkung ist auf dem Weg, und sie kommen für dich."
  },
  AvgDialog_23852_Content_85 = {
    Text = "Das Mädchen presste ihre Lippen zusammen, und nach einem Moment leuchteten ihre Augen plötzlich mit einem Blitz der Inspiration auf."
  },
  AvgDialog_23852_Content_86 = {
    Text = "Geh zur Hütte! Wir können uns eine Weile vor ihnen verstecken."
  },
  AvgDialog_23852_Content_87 = {
    Text = "Das Mädchen machte ein paar Schritte zurück und du bewegtest dich schnell, um sie zu beschützen. Sie trat mehrere Planken weg und enthüllte eine Falltür auf dem Deck."
  },
  AvgDialog_23852_Content_88 = {
    Text = "Dunkle Tür?!"
  },
  AvgDialog_23852_Content_89 = {
    Text = "Was für eine Geheimtür? Musst du wirklich in diesem entscheidenden Moment mit mir scherzen!"
  },
  AvgDialog_23852_Content_9 = {
    Text = "Mein Hals fühlt sich an, als hätte ich einen Mundvoll Worcestershiresauce geschluckt, jeder Atemzug bringt erstickende Blockaden und Schmerzen."
  },
  AvgDialog_23852_Content_90 = {
    Text = "Du warst doch schon mal im Schiff, hör auf zu trödeln und mach dich bereit!"
  },
  AvgDialog_23852_Content_91 = {
    Text = "Tulu widersprach dem Plan des Mädchens nicht. Unter seinem stillen Schutz zogen du und das Mädchen die Eisentür auf."
  },
  AvgDialog_23852_Content_92 = {
    Text = "Unter der Tür erstreckt sich eine eiserne Treppe nach unten, die im Unsichtbaren verschwindet."
  },
  AvgDialog_23852_Content_93 = {
    Text = "Schnell! Du gehst zuerst runter!"
  },
  AvgDialog_23852_Content_94 = {
    Text = "Dir fehlt die Fähigkeit zu kämpfen, also ist es meine Pflicht, dich zu beschützen—Ah!"
  },
  AvgDialog_23852_Content_95 = {
    Text = "Das Mädchen tat so, als hätte sie dein Gemurmel nicht gehört, und schlich sich geschickt hinter dich"
  },
  AvgDialog_23852_Content_96 = {
    Text = "——Dann trat er dich heftig in das dunkle Torloch"
  },
  AvgDialog_23852_Content_97 = {
    Text = "<SmallShake:Au, au...>"
  },
  AvgDialog_23852_Content_98 = {
    Text = "Du scheinst in ein weiches Bett aus Algen gefallen zu sein. Der fischige Geruch und die Salzigkeit des Meerwassers dringen in deine Nase und lassen deinen bereits pochenden Kopf noch mehr spinnen."
  },
  AvgDialog_23852_Content_99 = {
    Text = "Hey! Hör auf, festzuhalten, komm schnell runter!"
  },
  AvgDialog_23853_Content_1 = {
    Text = [[
Im Handumdrehen verschwanden sie...
So zu suchen funktioniert nicht. Vielleicht sollte ich zuerst Ramona finden...]]
  },
  AvgDialog_23853_Content_2 = {
    Text = "Keine Möglichkeit! Wir können sie nicht gehen lassen!"
  },
  AvgDialog_23853_Content_3 = {
    Text = "Hüstel... Was ich meine ist, sie könnte den Schlüssel zur Lösung des Seefahrer-Rätsels haben."
  },
  AvgDialog_23853_Content_4 = {
    Text = "Angesichts ihrer Vertrautheit mit den Seefahrern muss sie ihre Absichten kennen."
  },
  AvgDialog_23853_Content_5 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23853_Content_6 = {
    Text = [[
Alright, ich werde versuchen, Spirit-Tracking zu benutzen, um sie zu finden.
Dies ist das erste Mal, dass ich Spirit-Tracking benutze, um einen Menschen zu lokalisieren, also kann ich den Erfolg nicht garantieren.]]
  },
  AvgDialog_23854_Content_1 = {Text = "Dolch"},
  AvgDialog_23854_Content_10 = {
    Text = "Ehrlich gesagt ist mir gerade jetzt dein Name eingefallen."
  },
  AvgDialog_23854_Content_11 = {
    Text = "...Ah! Könnte es sein, dass du dir den Kopf gestoßen hast, als ich dich heruntergeschlagen habe?\nVerdammtes, warum musste das gerade in einem so kritischen Moment passieren..."
  },
  AvgDialog_23854_Content_12 = {
    Text = "Murphy kratzte sich frustriert am Kopf, offensichtlich ratlos, was sie tun sollte."
  },
  AvgDialog_23854_Content_13 = {
    Text = "Die Hintergrundgeschichte ist zu kompliziert, um sie zu erklären... Dieser Ort ist auch nicht sehr sicher. Wir müssen uns mit den anderen regroupieren."
  },
  AvgDialog_23854_Content_14 = {
    Text = "Wer sind die „anderen“?"
  },
  AvgDialog_23854_Content_15 = {
    Text = "Die Kapitäne von Sonaniel und Ramona."
  },
  AvgDialog_23854_Content_16 = {
    Text = "Na sicher! Könntest du das bitte wiederholen? Die Methode, um jemanden in der Geisterwelt zu finden"
  },
  AvgDialog_23854_Content_17 = {
    Text = "Geistertrace? Du kennst nicht nur Ramona und Tulu, sondern du weißt auch, dass ich einen Geistertrace durchführen kann...\nWas genau ist vorher passiert?"
  },
  AvgDialog_23854_Content_18 = {
    Text = "Hör auf zu trödeln! Finde zuerst Ramona, und ich werde unterwegs erklären."
  },
  AvgDialog_23854_Content_19 = {
    Text = "In die Geisterwelt zu sinken war eine bisher nie dagewesene schmerzhafte Erfahrung, als würde man durch einen dornigen Busch gehen, wodurch subtile Schmerzen überall verursacht werden. Aber wenn du schließlich vertraute Lichtpunkte siehst—"
  },
  AvgDialog_23854_Content_2 = {
    Text = "Tulu sagte, wir sollten uns zuerst mit den anderen treffen... Hmph, als ob das so einfach wäre."
  },
  AvgDialog_23854_Content_20 = {
    Text = "Knistern—"
  },
  AvgDialog_23854_Content_21 = {Text = "Hmm...!"},
  AvgDialog_23854_Content_22 = {
    Text = "Die Tentakeln des Bewusstseins erreichten kaum den Rand des spirituellen Raums, bevor sie wie verwelkte Reben abbrachen."
  },
  AvgDialog_23854_Content_23 = {
    Text = "Ein Schmerz, so intensiv, dass er Seele und Fleisch zu zerreißen droht, durchbohrt deine Schläfen und zwingt dich, vor Murphy zusammenzubrechen."
  },
  AvgDialog_23854_Content_24 = {
    Text = "Eh, eh?! Schreck mich nicht! Stirb nicht für mich!"
  },
  AvgDialog_23854_Content_25 = {
    Text = "Ich... Mir geht's gut..."
  },
  AvgDialog_23854_Content_26 = {
    Text = "Das Geistertracing war schon immer deine Stärke, aber jetzt scheint dein Körper sich gegen deine Tauchgänge in die Geisterwelt zu wehren."
  },
  AvgDialog_23854_Content_27 = {
    Text = "Du bist dir sicher: Es war dein eigener Körper, der dich aus der Geisterwelt ausgestoßen hat, und nicht irgendein anderes mysteriöses Wesen"
  },
  AvgDialog_23854_Content_28 = {
    Text = "@2...Gurgeln..."
  },
  AvgDialog_23854_Content_29 = {
    Text = "Es ist die Stimme der Seefahrer, sie haben uns gefunden! \nWir können hier nicht länger bleiben, folge mir."
  },
  AvgDialog_23854_Content_3 = {
    Text = "Murphy murmelte, während sie im Frachtraum umherging, ihre Unruhe war offensichtlich.\nDu holtest tief Luft und rief sie an."
  },
  AvgDialog_23854_Content_30 = {
    Text = "Murphy mühte sich, dich zu stützen, ihre Beine zitterten unter deinem Gewicht. Als sie dies bemerkte, verlagertest du dein Gewicht leicht in Richtung der Kabine, damit sie dir helfen konnte, tiefer ins Schiff zu bewegen..."
  },
  AvgDialog_23854_Content_31 = {
    Text = "Du bleibst vor einer schweren Eisentür stehen, die mit unheimlichen Dellen und Beulen markiert ist. Ein schwacher Brandgeruch weht durch den teilweise offenen Spalt."
  },
  AvgDialog_23854_Content_32 = {
    Text = "Murphy, sollen wir reingehen?"
  },
  AvgDialog_23854_Content_33 = {
    Text = "Pssst, lass mich zuhören..."
  },
  AvgDialog_23854_Content_34 = {
    Text = "Murphy ließ dich sanft los, presste sein Ohr gegen die Tür und hörte eine Weile mit geschlossenen Augen zu."
  },
  AvgDialog_23854_Content_35 = {
    Text = "Es scheint, dass hier niemand ist. Lass uns hineingehen und uns verstecken."
  },
  AvgDialog_23854_Content_36 = {
    Text = "Bevor Murphy die Tür öffnete, hast du auf das Etikett darauf geschaut—\"Machtzimmer\"."
  },
  AvgDialog_23854_Content_37 = {
    Text = "Hinter der Tür gibt es nicht die geschäftige Szene, die du dir vorgestellt hast: keine muskulösen Arbeiter, keine dröhnenden Kessel, nur fliegende Funken, die nicht ignoriert werden können."
  },
  AvgDialog_23854_Content_38 = {
    Text = "Der Boden ist mit unzähligen kalten, steifen Körpern übersät — den Leichnamen der Murloc-Monster, die dich verfolgt hatten."
  },
  AvgDialog_23854_Content_39 = {
    Text = "Murphy und Tulu nennen sie \"<Yellow:Seefahrer>\"."
  },
  AvgDialog_23854_Content_4 = {Text = "Murphy."},
  AvgDialog_23854_Content_40 = {
    Text = "Die Schottwand hatte ein großes Loch, durch das der kalte Wind in die Kabine strömte. Murphy kniff sich ins erfrierende Ohrläppchen, half dir über die Flammen und in die Ruinen."
  },
  AvgDialog_23854_Content_41 = {
    Text = "*Hust, hust, hust...* Der Geruch ist unerträglich."
  },
  AvgDialog_23854_Content_42 = {
    Text = "Hier... gab es einen heftigen Kampf?"
  },
  AvgDialog_23854_Content_43 = {
    Text = "Heftiger Kampf? Ist das der leichtgewichtige Begriff, den du verwendest, um diesen Kampf zu beschreiben?"
  },
  AvgDialog_23854_Content_44 = {
    Text = "Oh... jetzt, wo ich darüber nachdenke, weißt du immer noch nicht, was passiert ist."
  },
  AvgDialog_23854_Content_45 = {
    Text = "Zwischen den Trümmern reflektiert etwas auffällig"
  },
  AvgDialog_23854_Content_46 = {
    Text = "Du hattest noch nicht gesehen, was es war, aber Murphys Gesichtsausdruck änderte sich und offenbarte eine Mischung aus Angst und Trauer."
  },
  AvgDialog_23854_Content_47 = {
    Text = "Ich weiß nicht, wann diese Frau so verrückt zu handeln begann..."
  },
  AvgDialog_23854_Content_48 = {
    Text = "Sie zog an der Ecke ihres Mundes und erzählte dir \"die Vergangenheit\" auf unorganisierte Weise, während sie auf das Glitzern in den Ruinen zuschritt."
  },
  AvgDialog_23854_Content_49 = {
    Text = "Sie wird auf nichts hören. Egal wie sehr ich sie bitte, sie besteht darauf, diese Zeremonie abzuhalten..."
  },
  AvgDialog_23854_Content_5 = {
    Text = "Vielleicht finde ich einfach eine Ecke, um mich zu hocken..."
  },
  AvgDialog_23854_Content_50 = {
    Text = "—Der Glanz kommt von einem seltsam geformten Dolch, der ruhig zwischen den Überresten des erloschenen Feuers ruht. Trotz des Staubs auf seiner Klinge ist seine Schärfe unverkennbar."
  },
  AvgDialog_23854_Content_51 = {
    Text = "Früher war sie so freundlich zu mir..."
  },
  AvgDialog_23854_Content_52 = {
    Text = "Murphy starrte einen Moment lang auf die Dolch, dann krabbelte sie plötzlich in den Schutthaufen und streckte die Hand nach dem Dolch aus."
  },
  AvgDialog_23854_Content_53 = {Text = "Grr... Grr"},
  AvgDialog_23854_Content_54 = {
    Text = "Unter den zusammengebrochenen Seefahrern kämpft einer, der sich mit einer gebrochenen Waffe aufstützt, sich zu erheben, zitternd und mit hervorquellenden Augen wütend zu Murphy hinaufschauend."
  },
  AvgDialog_23854_Content_55 = {
    Text = "Warum... warum... weg vom Hohepriester... warum?"
  },
  AvgDialog_23854_Content_56 = {
    Text = "Mutter der Götter, Mutter der Götter... Gugu, Gugu...! Ich habe die Mutter der Götter gefunden!"
  },
  AvgDialog_23854_Content_57 = {
    Text = "Hochpriester, Hochpriester! Das Zeremoniell rückt näher, <Big:Das Zeremoniell rückt näher!>"
  },
  AvgDialog_23854_Content_58 = {
    Text = "Der Unterkiefer des Seefahrers öffnete sich bis zum Maximum, das Gewebe zwischen Ober- und Unterkiefer wurde durchscheinend gedehnt"
  },
  AvgDialog_23854_Content_59 = {
    Text = "Getrieben von Angst, Hoffnung und Glauben entfesselte er eine unvorstellbare Lebenskraft.\nDer Seefahrer schob plötzlich an dir vorbei und schrie, während er aus dem Kraftwerk stürmte."
  },
  AvgDialog_23854_Content_6 = {
    Text = "<BigShake:Murphy! Ich habe dir etwas zu sagen!>"
  },
  AvgDialog_23854_Content_60 = {
    Text = "Achtung, er will fliehen!"
  },
  AvgDialog_23854_Content_61 = {
    Text = "Zisch————"
  },
  AvgDialog_23854_Content_62 = {
    Text = "Eine scharfe Spitze durchbohrt die graublaue Brust, Flüssigkeit spritzt, der Seefahrer fällt zu Boden"
  },
  AvgDialog_23854_Content_63 = {
    Text = "Murphy stand an der Tür des Maschinenraums, grau-grünes, zähflüssiges Blut tropfte lautlos von der Spitze ihres Dolches."
  },
  AvgDialog_23854_Content_64 = {
    Text = "Fragmente von Stoff hängen daran, und die eingekerbten Vertiefungen sind mit Caro gefüllt. Murphys Körper zittert sichtbar, aber ihr Griff um das Messer ist fest und stark."
  },
  AvgDialog_23854_Content_65 = {
    Text = "......Tut mir leid, ich kann dich nicht gehen lassen"
  },
  AvgDialog_23854_Content_66 = {
    Text = "Murphy senkt die Augen, starrt eine Weile auf den Dolch und wischt schließlich das Blut des Seefahrers ab."
  },
  AvgDialog_23854_Content_67 = {
    Text = "Sein Instinkt war es, die Nachricht zu verbreiten..."
  },
  AvgDialog_23854_Content_68 = {
    Text = "Murphy lehnte sich gegen die Tür und warf einen seitlichen Blick auf das Chaos im Maschinenraum; seine Wimpern flatterten unruhig."
  },
  AvgDialog_23854_Content_69 = {
    Text = "Aber <Blue:Miryam>, ist sie nicht bereits... Warum nicht aufgeben..."
  },
  AvgDialog_23854_Content_7 = {
    Text = "Schrei nicht so laut! Was ist, wenn du wirklich den Seefahrer anziehst!"
  },
  AvgDialog_23854_Content_70 = {
    Text = "Der Name Murphy murmelt auf tranceartige Weise und lässt dich plötzlich schwindelig werden. Du blinzelst und wartest, bis das Übelkeitsgefühl nachlässt, bevor du deine Frage stellst."
  },
  AvgDialog_23854_Content_71 = {
    Text = "Wer ist Miryam?"
  },
  AvgDialog_23854_Content_72 = {
    Text = "Sie ist die Seefahrer... und die Anführerin dieser Fischmenschen."
  },
  AvgDialog_23854_Content_73 = {
    Text = "Diese sogenannte \"göttliche Mutter\"..."
  },
  AvgDialog_23854_Content_74 = {
    Text = "Sobald die Frage deinen Mund verließ, schlucktest du nervös ein paar Mal."
  },
  AvgDialog_23854_Content_75 = {
    Text = "Dein Körper scheint bereits die Antwort zu kennen, aber dein Unterbewusstsein hat Angst, dich daran zu erinnern."
  },
  AvgDialog_23854_Content_76 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23854_Content_77 = {
    Text = "Murphy blickt zu dir auf, ein stiller Strom von Traurigkeit fließt in ihren Augen."
  },
  AvgDialog_23854_Content_78 = {
    Text = "Ich bin es."
  },
  AvgDialog_23854_Content_79 = {
    Text = "Ich bin ein bedauernswerter Kreatur, ein Gefäß, das für die Wiedergeburt eines häretischen Gottes bestimmt ist."
  },
  AvgDialog_23854_Content_8 = {
    Text = "Mach weiter, was ist das Problem?"
  },
  AvgDialog_23854_Content_80 = {
    Text = "Ich... bin die \"Mutter Gott\" der Sekte der Seefahrer."
  },
  AvgDialog_23854_Content_81 = {
    Text = "Als das letzte Wort Murphys Mund verließ, explodierte ein weißes Licht vor seinen Augen, begleitet von intensiven Schmerzen."
  },
  AvgDialog_23854_Content_82 = {
    Text = "Hey?! Hey! %player%?!"
  },
  AvgDialog_23854_Content_83 = {
    Text = "Ihr Körper fiel unkontrollierbar rückwärts, ein tieffrequency klingender Ton wirbelte um ihre Ohren, und der Schrei des Mädchens wurde von einer Flut von Schmerz ertränkt."
  },
  AvgDialog_23854_Content_84 = {
    Text = "Am Ende des weißen Lichts beobachtet dich ein schwacher Blick."
  },
  AvgDialog_23854_Content_85 = {
    Text = "Das unbekannte Wesen scheint dich zu beurteilen—ob dein zerschmetterter Schädel es wert ist, wieder zusammengesetzt zu werden, ob deine sich auflösende Seele neu gewoben werden kann."
  },
  AvgDialog_23854_Content_86 = {
    Text = "Deine Augen weiten sich, während dein Bewusstsein von deinem Körper abschweift..."
  },
  AvgDialog_23854_Content_9 = {
    Text = "Ich bin... ein bisschen verwirrt über das, was passiert.\nWarum bin ich auf dem Schiff, und warum kenne ich dich..."
  },
  AvgDialog_23855_Content_1 = {
    Text = "Murphy, hör auf zu rennen! Wir sind keine schlechten Menschen!"
  },
  AvgDialog_23855_Content_2 = {
    Text = "Kein Bösewicht würde jemals zugeben, dass er ein Bösewicht ist!"
  },
  AvgDialog_23855_Content_3 = {
    Text = "Dieses Kind kann bereits die Wirkung der Runen sehen! Wie kannst du es wagen zu behaupten, dass du nicht zu den Seefahrern gehörst!"
  },
  AvgDialog_23855_Content_4 = {
    Text = "Es ist ein Zauber, der in altem Lomoria geschrieben ist. Jeder, der Lomoria kennt, kann diese Runen lesen."
  },
  AvgDialog_23855_Content_5 = {
    Text = "Erinnerst du dich? Lemuria war eine Zivilisation, die vor dem Beginn der Menschheitsgeschichte verloren ging. Selbst an der Mythag-Universität sind Forschungspapiere über Lemuria rar und verstreut."
  },
  AvgDialog_23855_Content_6 = {Text = "...Hmph."},
  AvgDialog_23855_Content_7 = {
    Text = "Beeile dich und fang sie."
  },
  AvgDialog_23856_Content_1 = {
    Text = "Verdrehte Realität"
  },
  AvgDialog_23856_Content_10 = {
    Text = "Was... was machst du? Warum siehst du mich plötzlich so an? Was ist mit den Blicken von euch beiden?"
  },
  AvgDialog_23856_Content_100 = {
    Text = "Goliath... du..."
  },
  AvgDialog_23856_Content_101 = {
    Text = "Warum... warum erzählst du mir das?"
  },
  AvgDialog_23856_Content_102 = {
    Text = "Melancholie ist keine gute Sache; denken Sie daran, Ihr Zustand bestimmt das Wachstum von \"Gott\"."
  },
  AvgDialog_23856_Content_103 = {
    Text = "Die nächste Stern-Ausrichten wird in 25 Jahren stattfinden. Ich schätze, Miryam wird kommen, um dich in ein paar Tagen in den Schlaf zu wiegen."
  },
  AvgDialog_23856_Content_104 = {
    Text = "Mach etwas, das dir Spaß macht, zerstöre Dinge, peitsche die Seefahrer, quäle deine Magd... was auch immer"
  },
  AvgDialog_23856_Content_105 = {
    Text = "Goliath beendete das Gespräch einseitig und tätschelte ihr lieblos den Kopf"
  },
  AvgDialog_23856_Content_106 = {
    Text = "Beim Verlassen warf er einen Blick auf die von Murphy in die Ecke geworfene Holzfigur. Das Handwerk des Mädchens war sehr schlecht, die Figur auf dem Holzsockel war unförmig und seltsam, was beim Anblick Abscheu hervorrief"
  },
  AvgDialog_23856_Content_107 = {Text = "Heh."},
  AvgDialog_23856_Content_108 = {
    Text = "Nachdem Goliath gegangen war, wurde es still. Die Opfer im Käfig gaben keinen Laut von sich"
  },
  AvgDialog_23856_Content_109 = {
    Text = "Murphy saß lange am Lagerfeuer, bis das Licht schwächer wurde und das Feuer fast erlosch, dann wachte sie wie aus einem Traum auf und klopfte sich auf die Wangen"
  },
  AvgDialog_23856_Content_11 = {
    Text = "Du konntest an den Schritten erkennen, dass es Goliath war, und zuvor hatten deine Worte bereits deine Vertrautheit mit Miryam offenbart."
  },
  AvgDialog_23856_Content_110 = {
    Text = "Sie trat gegen den Käfig neben ihr und erinnerte sich an die Frau, die vor mehreren Monaten das Ritual ruiniert hatte... die Frau, die durch sheer Willenskraft aus Miryam entkommen war."
  },
  AvgDialog_23856_Content_111 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23856_Content_113 = {
    Text = "„Es tut mir leid...\"\n„Ich... will nicht sterben...\""
  },
  AvgDialog_23856_Content_114 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23856_Content_115 = {
    Text = "Ich will auch nicht... so enden"
  },
  AvgDialog_23856_Content_12 = {
    Text = "Du kennst die Organisation \"Seefahrer\" sehr gut. Du bist ein Mitglied der \"Seefahrer\" und hältst sogar eine hohe Position... oder besser gesagt, sie kamen speziell für dich."
  },
  AvgDialog_23856_Content_13 = {
    Text = "Du bist die \"Heilige Mutter\", die von Seefahrern erwähnt wird, das Gefäß zur Geburt neuer Götter... oder?"
  },
  AvgDialog_23856_Content_14 = {
    Text = "<Big:Ich bin es nicht!>"
  },
  AvgDialog_23856_Content_15 = {
    Text = "Wie erklärst du deine Vertrautheit mit Goliath und Miryam und deine Vermeidung des Seefahrers?"
  },
  AvgDialog_23856_Content_16 = {
    Text = "Ich bin nur... ein Dienstmädchen... ein gewöhnliches Dienstmädchen. In der Zentrale des Kultes gibt es unzählige Mädchen wie mich."
  },
  AvgDialog_23856_Content_17 = {
    Text = "Menschen sollten unter Seeleuten in ihrem Aussehen extrem selten sein. Andernfalls würde ihre Kampfesfähigkeit keine Zusammenarbeit mit der Tempellicht Kirche erfordern."
  },
  AvgDialog_23856_Content_18 = {
    Text = "Wenn du nur eine unbedeutende menschliche Dienerin bist, warum jagen sie dich dann so intensiv?"
  },
  AvgDialog_23856_Content_19 = {
    Text = "Es ist alles... nur"
  },
  AvgDialog_23856_Content_2 = {
    Text = "Murphy, Murphy?"
  },
  AvgDialog_23856_Content_20 = {
    Text = "Murphy, ich muss wissen, was passiert ist."
  },
  AvgDialog_23856_Content_21 = {
    Text = "Nur so haben wir eine Überlebenschance, nur so können wir dir helfen"
  },
  AvgDialog_23856_Content_22 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23856_Content_23 = {Text = "Na gut"},
  AvgDialog_23856_Content_24 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23856_Content_25 = {
    Text = "Das Küken mit gebrochenen Flügeln fiel in den schwarzen Teich"
  },
  AvgDialog_23856_Content_26 = {
    Text = "Die flüsternden Gebete des Hohepriesters waren schwebend und fest, seine fanatischen Worte durchdrangen die schwarze Flüssigkeit und wurden zu Klingen, die die Brust des Kükens aufschlitzten"
  },
  AvgDialog_23856_Content_27 = {
    Text = "Rot leuchtende Flüssigkeit steigt aus der Brust auf und breitet sich auf der ruhigen schwarzen Wasseroberfläche aus—"
  },
  AvgDialog_23856_Content_28 = {
    Text = "Sie sank immer tiefer, die blutigen Wurzeln zogen sie in die Tiefe, in eine weiche und kalte Umarmung"
  },
  AvgDialog_23856_Content_29 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23856_Content_3 = {
    Text = "Es ist nicht nötig, sich zu verstecken. Goliath ist bereits weit genug weg gegangen."
  },
  AvgDialog_23856_Content_30 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_23856_Content_31 = {
    Text = "Sie sah es.\nSie blickte nach oben. „Mutter\" ließ drei Augenstiele herunter und sah sie an"
  },
  AvgDialog_23856_Content_32 = {
    Text = "Dieses kolossale Geschöpf war tief karminrot, mit Bereichen, die durch Blut gefärbt und transparent weiß wurden.\n„Mutter“ strahlte einen schwachen Glanz aus und erleuchtete vorübergehend ein kleines Reich."
  },
  AvgDialog_23856_Content_33 = {
    Text = "Im Licht sah sie unzählige schwarze Wunden auf der glatten Haut der „Mutter\""
  },
  AvgDialog_23856_Content_34 = {
    Text = "„Es tut mir leid...“"
  },
  AvgDialog_23856_Content_35 = {
    Text = "Schwarzer Schleim brodelte und störte die Ruhe am Grund des Teiches"
  },
  AvgDialog_23856_Content_36 = {
    Text = "„Die „Mutter„ stieß einen schrillen Schrei aus, ihre Gliedmaßen bewegten sich und schoben etwas in die Brust des Kükens.„"
  },
  AvgDialog_23856_Content_37 = {
    Text = "Die glitschigen, kalten, weichen Tentakel umschlingen sie, das schwarze Wasser hält ihren Mund und ihre Nase nicht mehr zu, sondern hebt ihr Leben wie Fruchtwasser"
  },
  AvgDialog_23856_Content_38 = {
    Text = [[
"Es tut mir leid..."
"Ich will immer noch... nicht sterben..."]]
  },
  AvgDialog_23856_Content_39 = {
    Text = "Die Wasseroberfläche blieb lange ruhig, selbst der heulende Wind der Pole konnte das zähe Wasser nicht kräuseln"
  },
  AvgDialog_23856_Content_4 = {
    Text = "Wirklich, wirklich?"
  },
  AvgDialog_23856_Content_40 = {
    Text = "Miryam milady, wird die Heilige vielleicht schon"
  },
  AvgDialog_23856_Content_41 = {
    Text = "Sie wurde während der letzten <Blue:Astral Alignment> geboren, ein \"sichtbares\" Kind."
  },
  AvgDialog_23856_Content_42 = {
    Text = "Niemand auf der Welt verdient es mehr, das Blut der Götter zu erhalten, als sie"
  },
  AvgDialog_23856_Content_43 = {
    Text = "Die dürre Frau wird umringt und steht an der höchsten Stelle, von der aus sie alle überblicken kann.\nEin Schleier verdeckt ihr Gesicht, selbst die engsten Diener können ihre Gedanken nicht lesen"
  },
  AvgDialog_23856_Content_44 = {Text = "Murphy..."},
  AvgDialog_23856_Content_45 = {
    Text = "Mit einem leisen Murmeln begann das Wasser plötzlich zu kochen, als ob die Energie des Erdkerns ausbrechen würde"
  },
  AvgDialog_23856_Content_46 = {
    Text = "Dicke, zähe schwarze Flüssigkeit quillt aus dem Becken, bedeckt die Füße der Menschen und fließt zu den nackten Füßen der Frau"
  },
  AvgDialog_23856_Content_47 = {
    Text = "Durch die flüsternden jungen Gläubigen schritt sie schweigend auf dem schwarzen Weg, tauchte ihre Hände tief ins Wasserbecken—"
  },
  AvgDialog_23856_Content_48 = {
    Text = "——Rauschen"
  },
  AvgDialog_23856_Content_49 = {
    Text = "Das Mädchen klammerte sich an ihre Hände und sprang aus dem Wasser.\nSchwarze Flüssigkeit lief ihr über das Gesicht und sah aus wie schreckliche Tränen"
  },
  AvgDialog_23856_Content_5 = {
    Text = [[
Es ist in Ordnung. Der Seefahrer auf dem Deck folgte ihm weg.
Komm, gib mir deine Hand. Ich helfe dir raus.]]
  },
  AvgDialog_23856_Content_50 = {
    Text = "Wow, nicht schlecht. Sieht so aus, als hätte <Blue:God> die neue <Blue:Mother> anerkannt."
  },
  AvgDialog_23856_Content_51 = {
    Text = "Goliath sprach plötzlich, sein Tonfall spöttisch, aber niemand achtete mehr auf seinen Hohn"
  },
  AvgDialog_23856_Content_52 = {
    Text = "Heilige Jungfrau... Hat es geklappt? Haben wir es geschafft?"
  },
  AvgDialog_23856_Content_53 = {
    Text = "Die Gebete hallen wider, schließlich vereinen sie sich in der kalten Höhle, fanatisch, verzerrt, ohrenbetäubend"
  },
  AvgDialog_23856_Content_54 = {
    Text = "Miryam, wie du gewünscht hast, habe ich vollendet, was du verlangt hast."
  },
  AvgDialog_23856_Content_55 = {
    Text = "\"Er\"... pulsiert hier."
  },
  AvgDialog_23856_Content_56 = {
    Text = "Nicht nur Murphy, sondern auch Miryam kann es hören.\nZwei Herzen mit unterschiedlichen Rhythmen schlagen in der Brust des Mädchens."
  },
  AvgDialog_23856_Content_57 = {
    Text = "Jetzt kannst du meine Frage beantworten?"
  },
  AvgDialog_23856_Content_58 = {
    Text = "Sprich ohne Vorbehalte."
  },
  AvgDialog_23856_Content_59 = {
    Text = "Hast du mich schon von Anfang an nur für heute hochgezogen?"
  },
  AvgDialog_23856_Content_6 = {
    Text = "Sobald Murphy stillstand, banden Tulus Tentakeln, mit deinem stillschweigenden Einverständnis, ihre Knöchel fest."
  },
  AvgDialog_23856_Content_60 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23856_Content_61 = {Text = "Nein."},
  AvgDialog_23856_Content_62 = {
    Text = "Du bist mein \"Heiliger\", der dazu bestimmt ist, das Gottesreich zu überbrücken... Danach wird deine Seele in das Gottesreich eintreten"
  },
  AvgDialog_23856_Content_63 = {
    Text = "Heutige Zeremonie war nicht geplant... aber es besteht kein Grund zur Panik. \nNach dem göttlichen Geburtsritual werde ich deine Seele sorgfältig bewahren, damit du nicht in der ewigen Nacht umherirrst."
  },
  AvgDialog_23856_Content_64 = {
    Text = "Über Seelen, Geister sprechen..."
  },
  AvgDialog_23856_Content_65 = {
    Text = "Mein Tod war für das sogenannte \"Ausrichten der Sterne\" vorherbestimmt, nicht wahr?"
  },
  AvgDialog_23856_Content_66 = {
    Text = "\nMiryam schloss sanft ihre Augen, antwortete nicht länger auf Fragen und wandte sich den rasenden Anhängern zu.\nSie hob ihre Arme hoch, schwarzes Liquid tropfte entlang der Textur ihrer Haut, und ihr Schleier wurde sofort tief schwarz gefärbt."
  },
  AvgDialog_23856_Content_67 = {
    Text = "Die Göttermutter ist da!"
  },
  AvgDialog_23856_Content_68 = {
    Text = "Er wird aus @1 auferstehen, um @2 zu befreien!"
  },
  AvgDialog_23856_Content_69 = {
    Text = "Er wird aus @1 auferstehen, um @2 zu befreien!"
  },
  AvgDialog_23856_Content_7 = {
    Text = "Was... was machst du?! Ich weiß, es war falsch von mir, dich allein mit Goliath zu lassen..."
  },
  AvgDialog_23856_Content_70 = {
    Text = "Drei Monate später"
  },
  AvgDialog_23856_Content_71 = {
    Text = "Du bereitest dieser Frau immer mehr Kopfschmerzen. Warst du vor ein paar Monaten nicht brav? \nWas, willst du Mama nicht mehr hören?"
  },
  AvgDialog_23856_Content_72 = {
    Text = "Das Mädchen warf einen Blick auf Goliath, stach das Schnitzmesser heftig in das Holz und warf sowohl das Werkzeug als auch das Material beiseite"
  },
  AvgDialog_23856_Content_73 = {
    Text = "Mama, Mama?"
  },
  AvgDialog_23856_Content_74 = {
    Text = "Du... woher hast du das?"
  },
  AvgDialog_23856_Content_75 = {
    Text = "Das Wörterbuch! Siehst du, „eine erwachsene Frau, die sich um Kleinkinder kümmert und eine emotionale Verbindung hat“"
  },
  AvgDialog_23856_Content_76 = {
    Text = "Nein... Ich werde nicht deine Mutter sein."
  },
  AvgDialog_23856_Content_77 = {
    Text = "Du bist die Heilige der Sekte, eine auserwählte Person... Wenn du willst, kannst du mich beim Namen nennen"
  },
  AvgDialog_23856_Content_78 = {
    Text = "Hm...Milia...Am?"
  },
  AvgDialog_23856_Content_79 = {
    Text = "Ja, Heilige"
  },
  AvgDialog_23856_Content_8 = {
    Text = "Aber... wenn er für mich kommt und mich erwischt, bin ich so gut wie tot! Ich... ich..."
  },
  AvgDialog_23856_Content_80 = {
    Text = "...Sie ist nicht meine Mutter, war sie nie"
  },
  AvgDialog_23856_Content_81 = {
    Text = "Nur die höheren Kräfte der Tempellichtkirche kennen meine Herkunft. Ich habe keine Mutter; ich bin nur ihr Geschenk an Miryam."
  },
  AvgDialog_23856_Content_82 = {
    Text = "Oh? Sie hat dir das auch erzählt?"
  },
  AvgDialog_23856_Content_83 = {
    Text = "Für einen zum Tode verurteilten Gefangenen ist es egal, wie viele Geheimnisse er kennt, alles wird mit ins Grab genommen"
  },
  AvgDialog_23856_Content_84 = {
    Text = "Das ist die Entschädigung dieser Frau für dich. Denk daran, dass unser Hoher Priester am Tag, als sie den Gott in dich transplantierten, so herzzerreißend war, dass er die ganze Nacht nicht schlafen konnte."
  },
  AvgDialog_23856_Content_85 = {
    Text = "Traurig? Was für ein Witz. Sie hätte solche Emotionen nicht."
  },
  AvgDialog_23856_Content_86 = {
    Text = "Wie herzlos, kleine Prinzessin.\nEin kaltes Mädchen macht ihre Mutter traurig"
  },
  AvgDialog_23856_Content_87 = {
    Text = "Du nervst! Ich habe doch gesagt, sie ist nicht meine Mutter!"
  },
  AvgDialog_23856_Content_88 = {
    Text = "Das ist nicht sicher, willst du eine Geschichte hören?"
  },
  AvgDialog_23856_Content_89 = {
    Text = "<BigShake:Ich will nicht hören, ich will dich auch nicht sehen!>\nWenn du nur gekommen bist, um mich zu verspotten, kannst du gehen!"
  },
  AvgDialog_23856_Content_9 = {Text = "Murphy."},
  AvgDialog_23856_Content_90 = {
    Text = "Nein, du willst es hören"
  },
  AvgDialog_23856_Content_91 = {
    Text = "Goliaths Stimme wurde plötzlich tief und ehrfurchtgebietend, sodass Murphys zwei Herzen fast aufhörten zu schlagen"
  },
  AvgDialog_23856_Content_92 = {
    Text = "Plötzlich wurde ihr klar – Riesen waren nie Spielzeuge für sie.\nSie nutzte nur ihre Position aus, und der andere genoss es, zuzusehen"
  },
  AvgDialog_23856_Content_93 = {
    Text = "J-Ja, bitte fahren Sie fort."
  },
  AvgDialog_23856_Content_94 = {
    Text = "Ein geheimnisvoller Kult kontrolliert alle Ehen, um die absolute Reinheit ihrer Blutlinie sicherzustellen. Diejenigen, die mit Außenseitern heiraten und Kinder bekommen, werden schließlich ausgemerzt."
  },
  AvgDialog_23856_Content_95 = {
    Text = "Während der letzten Ansiedlung brachte der Vollstrecker ein Mädchen mit zurück - eines, das spirituelle Wesen sehen konnte."
  },
  AvgDialog_23856_Content_96 = {
    Text = "Baby-Mädchen"
  },
  AvgDialog_23856_Content_97 = {
    Text = "Sie hat zu lange im dunklen Raum unter dem Körper ihrer Mutter versteckt. Als die Kultisten sie fanden, hätte sie fast an dem Blut ihrer Mutter erstickt."
  },
  AvgDialog_23856_Content_98 = {
    Text = "Diese gewöhnliche Frau, ihr größter Erfolg im Leben war es, eine talentierte Tochter zu gebären und zu versuchen, sie nicht von der Kirche wegnehmen zu lassen"
  },
  AvgDialog_23856_Content_99 = {
    Text = "——Was für eine wunderbare Mutter-Tochter-Bindung, ich könnte fast weinen"
  },
  AvgDialog_23857_Content_1 = {
    Text = "Samen des Schicksals"
  },
  AvgDialog_23857_Content_10 = {
    Text = "Wie viel länger?"
  },
  AvgDialog_23857_Content_11 = {
    Text = "Wie viel länger wird es dauern?"
  },
  AvgDialog_23857_Content_12 = {
    Text = "Gott. Wie lange noch bis zu seiner Geburt?"
  },
  AvgDialog_23857_Content_13 = {
    Text = "......Ich weiß nicht. Warum überprüfst du es nicht selbst? Angesichts deiner Haltung gegenüber Miryam und Goliath bist du bereits involviert."
  },
  AvgDialog_23857_Content_14 = {
    Text = "\nMurphy zögerte überhaupt nicht und begann unkompliziert, ihre Kleidung zu öffnen.\nAls der letzte Knopf an ihrer Vorderseite aufgeknöpft wurde, sahst du das \"Göttchen\" im Mädchen."
  },
  AvgDialog_23857_Content_15 = {
    Text = "Ihr vorderer Oberkörper war transparent, die Textur zog an der umgebenden Haut und Muskulatur und offenbarte ein blasses, verwestes Weiß."
  },
  AvgDialog_23857_Content_16 = {
    Text = "Das transparente Erscheinungsbild zeigt die Organe im Brustkorb. Du siehst ein schwach rotes junges Herz und ein milchweißes „Ei“."
  },
  AvgDialog_23857_Content_17 = {
    Text = "Unzählige Fäden strecken sich aus dem „Ei\" und verflechten sich eng mit Murphys Blutgefäßen"
  },
  AvgDialog_23857_Content_18 = {
    Text = "Wäre seine Existenz nicht schon in Murphys Herz gedrungen, würde er wie ein Teil des durchsichtigen Brustkorbs wirken, nicht wie ein Fremdkörper"
  },
  AvgDialog_23857_Content_19 = {
    Text = "Er ist chaotisch und still, das umgekehrte Dreiecksmuster, das auf ihm eingraviert ist, erstarrt ebenfalls wie ein seltsames Kunstwerk"
  },
  AvgDialog_23857_Content_2 = {
    Text = "Der Kult der Seefahrer, die von den Abenteurern gestörten Rituale, die aufgelöste ehemalige Mutterkörper... und der \"Gott\" in dir..."
  },
  AvgDialog_23857_Content_20 = {
    Text = "Schmelze... Dieses Ding ist bereits geschmolzen"
  },
  AvgDialog_23857_Content_21 = {
    Text = "Hast du genug gesehen?"
  },
  AvgDialog_23857_Content_22 = {
    Text = "Entschuldigung... Bitte mach deine Kleidung schnell ordentlich."
  },
  AvgDialog_23857_Content_23 = {
    Text = "Murphy schaut dich an, während sie ihre Kleidung ordnet."
  },
  AvgDialog_23857_Content_24 = {
    Text = "Als du von \"Auflösung\" sprachst, hast du dich dann auf die schwarze Wunde darauf bezogen?"
  },
  AvgDialog_23857_Content_25 = {
    Text = "Das vorherige Gefäß... dasjenige, das dieses Ding wirklich genährt hat, war mit diesen Markierungen bedeckt."
  },
  AvgDialog_23857_Content_26 = {
    Text = "Wenn es nicht für diese \"Auflösung\" wäre, die das vorherige Gefäß schwächer macht, wäre ich nicht..."
  },
  AvgDialog_23857_Content_27 = {
    Text = "Murphys Stimme verblasste allmählich.\nSie schluckte ihre unvollendeten Worte hinunter, legte eine Hand auf ihre Brust und ihr Ausdruck war düster."
  },
  AvgDialog_23857_Content_28 = {
    Text = "Tulu, du hast auch die Form dieses Gottes gesehen.\nWie lange dauert es, bis er vollständig heranreift?"
  },
  AvgDialog_23857_Content_29 = {
    Text = "Bemerkenswert gesund, nur einen Schritt entfernt...\nNur die Sterne werden benötigt, um Ihn zu führen, um Ihn zu führen, das Gefäß des Körpers zu zerreißen."
  },
  AvgDialog_23857_Content_3 = {
    Text = "Aigis, Miss Mason, Lily, Lisa... Bisher hast du schon einige Menschen getroffen, die Körpermodifikationen durchlaufen haben."
  },
  AvgDialog_23857_Content_30 = {
    Text = "Ich bin überrascht, dass du in diesem Moment noch so frei bewegen kannst."
  },
  AvgDialog_23857_Content_31 = {
    Text = "Ist das so... Es ist bereits so weit gekommen..."
  },
  AvgDialog_23857_Content_32 = {
    Text = "Ich habe das Bewusstsein dank <Blue:Celeste> nicht verloren."
  },
  AvgDialog_23857_Content_33 = {
    Text = "Wer ist Celeste?"
  },
  AvgDialog_23857_Content_34 = {
    Text = "Murphy sah zum Himmel, der von seltsamen Lichtern durchzogen war.\nVögel kreisten unter dem Lichtschirm, das Licht war verzerrt und weich, und schirmte mögliche Stürme ab"
  },
  AvgDialog_23857_Content_35 = {
    Text = "In den Notizen der Seefahrergilde wird die <Blue: Bedeutung der Sternenpositionierung> immer wieder betont, und das Geburtsritual muss zu einem bestimmten Zeitpunkt stattfinden, was der Grund dafür ist, dass mich diese Frau zum Schlafen gebracht hat"
  },
  AvgDialog_23857_Content_36 = {
    Text = "Der Kapitän vermutete, dass sein Wachstum möglicherweise mit den Gesetzen der Himmelsmechanik zusammenhängt.\nAlso schuf Celeste diesen abgeschiedenen Bereich um das Schiff herum"
  },
  AvgDialog_23857_Content_37 = {
    Text = "Wir haben richtig geraten; seit wir den wahren Himmel verlassen haben, ist Er still. Solange wir diesen \"Moment der Ausrichtung\" auf dem Schiff überstehen, wird Er vielleicht in einen ewigen Schlaf fallen."
  },
  AvgDialog_23857_Content_38 = {
    Text = "Es war Celeste, die diesen Bereich schuf und das versunkene Sonaniel kontrolliert, damit es segeln kann."
  },
  AvgDialog_23857_Content_39 = {
    Text = "Klingt, als wäre sie ein Erwacher.\nWarte... Ist sie diejenige, die du erwähnt hast, die helfen kann, Ramona zu finden?"
  },
  AvgDialog_23857_Content_4 = {
    Text = "Aber einen <Blue:„Gott“> in den Körper eines Lebenden zu verpflanzen? Das ist"
  },
  AvgDialog_23857_Content_40 = {
    Text = "Das stimmt, nichts auf diesem Schiff entgeht ihrem Blick."
  },
  AvgDialog_23857_Content_41 = {
    Text = "Sie muss den Kapitän genommen haben, um den Seefahrern zu entkommen. Sobald wir sie gefunden haben, wird es ein Kinderspiel sein, deinen Begleiter zu finden."
  },
  AvgDialog_23857_Content_42 = {
    Text = "In anderen Worten, ob wir uns entscheiden, dir zuerst zu helfen oder Ramona zuerst zu retten, Celeste ist der Schlüssel."
  },
  AvgDialog_23857_Content_43 = {
    Text = "Tulu hört auf zu reden und neigt einfach seinen Kopf, schaut dich an und wartet auf deine Entscheidung."
  },
  AvgDialog_23857_Content_44 = {
    Text = "Sicher. Ob es darum geht, dieses Schiff zurück an Land zu bringen, das Abstieg-Ritual zu stoppen oder Ramona zu retten, der einzige Weg jetzt ist, \"Celeste\" zu finden."
  },
  AvgDialog_23857_Content_45 = {
    Text = "Murphy, führ uns.\nLass uns den Kapitän und Celeste finden."
  },
  AvgDialog_23857_Content_5 = {
    Text = "Was ist mit diesem Ausdruck? Wenn du mir nicht glaubst, gut. Ich habe nicht erwartet, dass du mich sofort verstehst."
  },
  AvgDialog_23857_Content_6 = {
    Text = "Entschuldigung... Das alles ist einfach zu unglaublich"
  },
  AvgDialog_23857_Content_7 = {
    Text = "Murphy, darf ich diesen... „Gott“ sehen?"
  },
  AvgDialog_23857_Content_8 = {
    Text = "Und du sagst, du glaubst nicht daran!"
  },
  AvgDialog_23857_Content_9 = {
    Text = "Ich, ich einfach..."
  },
  AvgDialog_23858_Content_1 = {
    Text = "Hinterhalt von allen Seiten"
  },
  AvgDialog_23858_Content_10 = {
    Text = "Wir hatten ein Gefecht mit unbekannten Feinden am <Blue:Dritten Pier> in <Blue:Brillport>"
  },
  AvgDialog_23858_Content_11 = {
    Text = "Die nächstgelegene Feldermittlerin wird benachrichtigt...\nErmittlerin Draper wird voraussichtlich in einer halben Stunde am Dock 3 eintreffen."
  },
  AvgDialog_23858_Content_12 = {
    Text = "Eine halbe Stunde ist zu lang. Zu viele Feinde im Süden, wir versuchen es im Norden"
  },
  AvgDialog_23858_Content_13 = {
    Text = "Fahrer zum dritten Kai Nordausgang benachrichtigt"
  },
  AvgDialog_23858_Content_14 = {
    Text = "Unbekannter Feind? Ist es nicht <Yellow:Tempellicht Kirche>?"
  },
  AvgDialog_23858_Content_15 = {
    Text = "Möchtest du neue Feindinformationen aufnehmen?"
  },
  AvgDialog_23858_Content_16 = {
    Text = "Bitte, Erica, nicht jetzt"
  },
  AvgDialog_23858_Content_17 = {
    Text = "Es ist ein menschenähnliches Wesen, das noch nie gesichtet wurde. Ich werde einen Bericht einreichen, wenn ich zurück bin"
  },
  AvgDialog_23858_Content_18 = {
    Text = "%player%, schütze dich und bereite dich auf den Durchbruch vor."
  },
  AvgDialog_23858_Content_2 = {
    Text = "Vor drei Stunden\nHafenstadt·Brielport\nDeck Nr. 3"
  },
  AvgDialog_23858_Content_3 = {
    Text = "%player%, pass auf den Feind hinter dir auf!"
  },
  AvgDialog_23858_Content_5 = {
    Text = "Hochfrequente Schallwellen ohne Vorwarnung wurden erkannt, Kommunikation wird automatisch hergestellt.\nGuten Abend, Hüter, Ramona, erneut"
  },
  AvgDialog_23858_Content_6 = {
    Text = "Es scheint, dass jemand vor Angst fast gestorben ist"
  },
  AvgDialog_23858_Content_7 = {
    Text = "Bitte keine unnötigen Gespräche mit Außendienstmitarbeitern"
  },
  AvgDialog_23858_Content_8 = {
    Text = [[
Na gut, na gut.
Braucht ihr Hilfe?]]
  },
  AvgDialog_23858_Content_9 = {
    Text = "Wir brauchen Verstärkung!"
  },
  AvgDialog_23859_Content_1 = {
    Text = "Keine Flucht"
  },
  AvgDialog_23859_Content_10 = {
    Text = "Es ist wirklich so, dass sie die Gangway nicht verfolgt haben..."
  },
  AvgDialog_23859_Content_11 = {
    Text = "Ramona senkte die Stimme und flüsterte"
  },
  AvgDialog_23859_Content_12 = {
    Text = "Diese Murlocs wurden von den Sonanil aufgehalten, aber aus unbekannten Gründen wurden wir nicht von dem Schiff abgewiesen."
  },
  AvgDialog_23859_Content_13 = {
    Text = "Wir wurden als Sprungbrett verwendet. Sobald sie das Schiff besteigen, werden wir unseren Wert verlieren."
  },
  AvgDialog_23859_Content_14 = {
    Text = "Das stimmt. Also... ich habe eine Idee."
  },
  AvgDialog_23859_Content_15 = {
    Text = "Ihr erreicht die letzte Stufe der Gangway"
  },
  AvgDialog_23859_Content_16 = {
    Text = "Wie ein von dem Himmel geküsster Vogel, dessen Augen von einer sanften, warmen Brise gestreift werden, wird die Welt vor ihm auf den Kopf gestellt."
  },
  AvgDialog_23859_Content_17 = {
    Text = "Der riesige Vollmond verschwand am Himmel, und ein auroraähnlicher Schein wirbelte den Raum um das Schiff herum auf, wobei seltsame Lichtflecken auf das Deck geworfen wurden"
  },
  AvgDialog_23859_Content_18 = {
    Text = "Ramona, etwas stimmt nicht!"
  },
  AvgDialog_23859_Content_19 = {
    Text = "Die Gangway zitterte. Nachdem du erfolgreich das Deck betreten hattest, hörten die Murlocs auf zu beobachten und begannen, mit Händen und Füßen hinaufzuklettern."
  },
  AvgDialog_23859_Content_2 = {
    Text = "Vor drei Stunden\nHafenstadt·Brielport\nDeck Nr. 3"
  },
  AvgDialog_23859_Content_20 = {
    Text = "Keine Zeit, sie holen auf."
  },
  AvgDialog_23859_Content_21 = {
    Text = "Ramona zerschmetterte mit einem kraftvollen Schlag die Halterung, die Gangway fiel herunter, ohne ein Geräusch zu machen"
  },
  AvgDialog_23859_Content_22 = {
    Text = "Dein Herz pocht heftig, während die Anomalien des Schiffs deinen Geist überfluten. Es dauert eine Weile, bis du wieder sprechen kannst."
  },
  AvgDialog_23859_Content_23 = {
    Text = "Zumindest können sie nicht über diese Gangway an Bord gehen"
  },
  AvgDialog_23859_Content_24 = {
    Text = "Die Szenen auf diesem Schiff... passen definitiv zu meinem Klischee eines \"Geisterschiffs.\""
  },
  AvgDialog_23859_Content_25 = {
    Text = "Die Gangway fiel lautlos—was darauf hindeutet, dass wir uns in einem isolierten Raum befinden könnten. Interessant, nicht wahr?"
  },
  AvgDialog_23859_Content_26 = {
    Text = "Das ist ein sichtbarer <Yellow:Bereich>."
  },
  AvgDialog_23859_Content_27 = {
    Text = "Der Schutz des Nebels der Schule wird von <Yellow:Silberchiptechnologie> gesteuert. Ich frage mich, unter welcher Macht dieses Schiff steht?"
  },
  AvgDialog_23859_Content_28 = {
    Text = "Könnte es ein Erwachter sein?"
  },
  AvgDialog_23859_Content_29 = {
    Text = "Im Archiv gibt es keine ähnlichen Aufzeichnungen, aber theoretisch ist es möglich, dass der Erwachte einen unabhängigen Raum schafft – möchtest du die Theorie hören?"
  },
  AvgDialog_23859_Content_3 = {
    Text = "Der Geruch von rostigem Stahl greift die Nasenlöcher an, und mit jedem Schritt gibt der Gehweg ein prekaires Stöhnen von sich."
  },
  AvgDialog_23859_Content_30 = {
    Text = "Verschone mich..."
  },
  AvgDialog_23859_Content_31 = {
    Text = "Dorl, habt ihr es gehört?"
  },
  AvgDialog_23859_Content_32 = {
    Text = "Schau auf die Situation!"
  },
  AvgDialog_23859_Content_33 = {
    Text = "Entschuldigung, entschuldigung, verzeih meine Neugier"
  },
  AvgDialog_23859_Content_34 = {
    Text = "Dorl, habt ihr es gehört?"
  },
  AvgDialog_23859_Content_35 = {
    Text = "Ramona klopft auf ihre Brosche, und ein Schimmer scheint über die silberne Oberfläche des Kommunikators zu gleiten."
  },
  AvgDialog_23859_Content_36 = {Text = "Hmm...?"},
  AvgDialog_23859_Content_37 = {
    Text = "Ramona drehte sich zur Seite und tippte auf dein Kommunikationsgerät.\nDu versuchtest, dich wie gewohnt zu konzentrieren, aber es funktionierte nicht"
  },
  AvgDialog_23859_Content_38 = {
    Text = "Mentale Energie wie Tränen, die ins Meer fallen, kehrt zur Stille zurück"
  },
  AvgDialog_23859_Content_39 = {
    Text = "Auf den ersten Blick scheint der Kommunikator unbeschädigt zu sein, ist jedoch nicht in der Lage, Nachrichten zu senden."
  },
  AvgDialog_23859_Content_4 = {
    Text = "Es gibt keine Anzeichen von Wartung oder Reparaturen, aber abgesehen davon, dass es alt ist, bleibt der Rumpf relativ intakt.\nEs gibt nur wenig Beweis für Erosion durch Meerwasser, und keine Ranken oder Austern unter der Wasserlinie..."
  },
  AvgDialog_23859_Content_40 = {
    Text = "<Small:Warum gibt es so viele Dinge, die die Kommunikation stören? Letztes Mal im Wachsfigurenkabinett auch...>"
  },
  AvgDialog_23859_Content_41 = {
    Text = "Silberinduzierte Technologie ist nicht allmächtig.\nAußerdem befindet sich unsere Forschung über Silber noch in den Kinderschuhen."
  },
  AvgDialog_23859_Content_42 = {
    Text = "Ich hoffe, dass diese Murlocs nicht woanders her krabbeln..."
  },
  AvgDialog_23859_Content_43 = {
    Text = "Hmm, achte auf deine Umgebung und bete, dass dieses Schiff nicht in See sticht."
  },
  AvgDialog_23859_Content_44 = {
    Text = "<Big: Woo—>"
  },
  AvgDialog_23859_Content_45 = {
    Text = "Wie eine Nachtigall, die auf die Koloraturen eines Opernsängers antwortet, antwortete die lange Sirene auf Ramonas Gebet"
  },
  AvgDialog_23859_Content_46 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23859_Content_47 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23859_Content_48 = {
    Text = "Ich weiß, was du sagen willst, aber bitte, nicht jetzt"
  },
  AvgDialog_23859_Content_49 = {
    Text = "Wir können nicht mit der Sonaniel in See stechen, dieses Schiff ist zu verdächtig"
  },
  AvgDialog_23859_Content_5 = {
    Text = "Du und Ramona gingen nebeneinander die wackelige Gangway hinauf, der Weg vor euch verschwindet im Nebel."
  },
  AvgDialog_23859_Content_50 = {
    Text = "Geh zur anderen Seite des Decks! Ich habe dort Seile gesehen, die das Rettungsboot sichern. Lass es uns über das Meer versuchen."
  },
  AvgDialog_23859_Content_51 = {
    Text = "Warte... da ist ein Geräusch"
  },
  AvgDialog_23859_Content_53 = {
    Text = "Fischgesichtige Gestalten erscheinen auf dem Deck und drängen euch auf das Schiff"
  },
  AvgDialog_23859_Content_6 = {
    Text = "Hast du etwas entdeckt?"
  },
  AvgDialog_23859_Content_7 = {
    Text = "Die Sona Neil zeigt keine Merkmale eines Geisterschiffs, das im Sturm unterging"
  },
  AvgDialog_23859_Content_8 = {
    Text = "Ich würde gerne die Ursprünge dieses Schiffs gründlich untersuchen, aber jetzt ist eindeutig nicht die richtige Zeit."
  },
  AvgDialog_23859_Content_9 = {
    Text = "Sie blickte zurück, die Feinde, die dich auf die Gangway gezwungen hatten, waren jetzt darunter gefangen. Sie hielt den Blick mit ihren leblosen, fischähnlichen Augen."
  },
  AvgDialog_23860_Content_1 = {
    Text = "Der nachgiebige"
  },
  AvgDialog_23860_Content_10 = {
    Text = "Schließlich ist es ein Gesicht, sowohl vertraut als auch fremd."
  },
  AvgDialog_23860_Content_11 = {
    Text = "*Hust, hust, hust...!*"
  },
  AvgDialog_23860_Content_12 = {
    Text = "Die trockene Luft kombiniert mit dem Meersalz, das im Wind verweilt, reizt die Atemwege wie nie zuvor und verursacht unkontrollierbares Husten bei jedem Muskelkrampf."
  },
  AvgDialog_23860_Content_13 = {
    Text = "Der grünhaarige Junge runzelte leicht die Stirn. Unter seiner Kontrolle wickelten sich die Tentakel erneut um dich, und dann—"
  },
  AvgDialog_23860_Content_14 = {
    Text = "Der Tentakel zog sich mehrere Male mit genau der richtigen Kraft zusammen und schloss das gesamte Wasser und die kleinen Fische aus dem Hals."
  },
  AvgDialog_23860_Content_15 = {
    Text = "*Hust, hust...* Danke."
  },
  AvgDialog_23860_Content_16 = {
    Text = "Kein Grund, mir zu danken. Deine Stimme ist zu laut – sie wird andere Seefahrer anziehen."
  },
  AvgDialog_23860_Content_17 = {
    Text = "...Ich meine den Teil, wo du mich aus dem Meer gerettet hast."
  },
  AvgDialog_23860_Content_18 = {
    Text = "\nObwohl es nicht mein Wunsch ist, ein Erwachender zu werden, hat die Mythag-Universität tatsächlich meinen jahrtausendelangen Schlaf beendet.\nIn Gefühl und Vernunft kann ich das \"Hüter\" in seiner Not nicht ignorieren."
  },
  AvgDialog_23860_Content_19 = {
    Text = "Aber... du solltest hier nicht sein, oder?\nDie Personal liste für diese Untersuchung umfasst nur mich und Ramona."
  },
  AvgDialog_23860_Content_2 = {
    Text = "Wasser strömt kontinuierlich in deinen Körper.\nNasenhöhle, Gehörgang, Hals, Augenwinkel... jede Öffnung deines Oberkörpers ist mit Meerwasser gefüllt."
  },
  AvgDialog_23860_Content_20 = {
    Text = "Erwachende können das Mythag-Reich nicht ohne die Genehmigung des Leiters der Feldoperationen und die Verknüpfung eines Ermittlers verlassen. Ich dachte, du wüsstest das..."
  },
  AvgDialog_23860_Content_21 = {
    Text = "Erwecker Tulu, Aktennummer -6291, Codename \"Lord des Schlafes\"."
  },
  AvgDialog_23860_Content_22 = {
    Text = "Du weißt, dass diese sogenannten \"Regeln\" der Mythag Universität für mich bedeutungslos sind."
  },
  AvgDialog_23860_Content_23 = {
    Text = "Und nenn mich nicht mit diesem dummen Codenamen"
  },
  AvgDialog_23860_Content_24 = {Text = "Tulu."},
  AvgDialog_23860_Content_25 = {
    Text = "Ich bin nicht wie diese starrköpfigen Mitglieder des Ausschusses; Erwacher sind keine Bestien, die gefesselt werden müssen."
  },
  AvgDialog_23860_Content_26 = {
    Text = "Mein Anliegen ist, dass du nicht auf der Einsatzliste stehst und mit niemandem verbunden bist.\nWenn du dich zu lange von Mythags <Yellow:Black Pool> fernhältst, riskierst du die Kontrolle zu verlieren."
  },
  AvgDialog_23860_Content_27 = {
    Text = "Kein Problem, ich werde nicht von sogenannten Instinkten beherrscht"
  },
  AvgDialog_23860_Content_28 = {
    Text = "Der erweckte Körper behält die Gestalt eines Jugendlichen, aber jede seiner Handlungen strahlt die Autorität eines Höhergestellten aus.\nEin flüchtiger Blick reicht aus, um einem die Haare zu Berge stehen zu lassen"
  },
  AvgDialog_23860_Content_29 = {Text = "......Puh"},
  AvgDialog_23860_Content_3 = {
    Text = "Dein Blut reagiert mit dem Meerwasser, wobei Zellen aus deinem Körper ausgestoßen werden. Stattdessen scheinen grobes Salz und Schmutz durch deine Venen zu fließen."
  },
  AvgDialog_23860_Content_30 = {
    Text = "—Ich möchte nur wissen, was machst du hier?\nDu bist seit Jahren in tiefem Schlaf. Nicht einmal die <Yellow:Silber Schlüsselzeremonie> Mutation konnte dich wecken."
  },
  AvgDialog_23860_Content_31 = {
    Text = "Aber du hast es riskiert, deinen Verstand zu verlieren, um hierher zu kommen... Was auch immer passiert ist, muss große Bedeutung für dich haben."
  },
  AvgDialog_23860_Content_32 = {
    Text = [[
Alles, was hier passiert ist, ist wegen mir.
Die Details sind nicht wichtig]]
  },
  AvgDialog_23860_Content_33 = {
    Text = "Ist das so? Selbst wenn Ramona und ich dieser Frau Miryam begegnet sind, konntest du nicht zu unserer Rettung kommen?"
  },
  AvgDialog_23860_Content_34 = {
    Text = "Ich bin nicht verpflichtet, euch zu erklären, aber wenn nötig, werde ich helfen"
  },
  AvgDialog_23860_Content_35 = {
    Text = "Tulus Weigerung zu sprechen entzündet fast deinen Zorn, doch die Realität hält dich rational."
  },
  AvgDialog_23860_Content_36 = {
    Text = "Deine Hände ballen sich zu Fäusten und entspannen sich dann wieder. Nach mehreren tiefen Atemzügen siehst du schließlich den Erwachter Junge vor dir an."
  },
  AvgDialog_23860_Content_37 = {
    Text = "Ramona ist in den Händen des Seefahrers. Tulu, ich brauche deine Hilfe."
  },
  AvgDialog_23860_Content_38 = {
    Text = "Tulu sieht dir lange in die Augen, anscheinend bereit, Worte der Ablehnung zu formulieren."
  },
  AvgDialog_23860_Content_39 = {
    Text = "So wie die Muskeln um seine Lippen zuckten, bereit zu antworten, hallte ein durchdringender Schrei eines Mädchens aus der Tiefe der Kabine wider."
  },
  AvgDialog_23860_Content_4 = {
    Text = "Sie kratzen von innen am Körper und an der Seele, die Lungen füllen sich mit Flüssigkeit. Das Bewusstsein versinkt mit dem Körper, und die Sorge um den Partner wird von Schmerz und Erstickung verdrängt."
  },
  AvgDialog_23860_Content_40 = {
    Text = "Ist das Ramona!? Lass uns hingehen und nachsehen!"
  },
  AvgDialog_23860_Content_41 = {
    Text = "Du hast keine Ahnung, wie viele Seefahrer das Schiff betreten haben. Unvorbereitet hineinzustürzen ist wirklich töricht."
  },
  AvgDialog_23860_Content_42 = {Text = "Dumm?"},
  AvgDialog_23860_Content_43 = {
    Text = "Wenn das, was du sagst, wahr ist, würdest du nicht tatenlos zusehen, wenn der \"Hüter\" in Gefahr ist."
  },
  AvgDialog_23860_Content_44 = {
    Text = "Tulu, ich werde mich als Nächstes meinem Tod stellen."
  },
  AvgDialog_23860_Content_45 = {
    Text = "Tulu hielt sich den Kopf, ohne zu antworten, aber bevor du dich umdrehst und in die Tiefen der Kabine stürzt, hörst du das leise Seufzen des jungen Mannes."
  },
  AvgDialog_23860_Content_5 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23860_Content_6 = {
    Text = "Die Wellen auf dem Meer schlugen gegen mein Trommelfell, während ich kämpfte, meine Augen zu öffnen. Etwas tauchte gegen das Licht ins Wasser."
  },
  AvgDialog_23860_Content_7 = {
    Text = "Es schlingt sich um deine Taille wie Algen... Nein, es sind keine Algen, sondern eine Art weicher, aber hochgradig resilienter Muskeln..."
  },
  AvgDialog_23860_Content_8 = {
    Text = "Schwisch—"
  },
  AvgDialog_23860_Content_9 = {
    Text = "Ein langer Muskelstreifen zieht dich nach oben und enthüllt das rosafarbene Licht des Himmels des Bereichs, dann die Strahlen des unteren Decks und schließlich die flackernden Lichter der Kabine."
  },
  AvgDialog_23861_Content_1 = {
    Text = "Diese hässlichen Gesichter sind eine Beleidigung der Evolutionstheorie"
  },
  AvgDialog_23861_Content_2 = {
    Text = "Sie drängeln sich um einander, ihre kalten Waffen klirren und erzeugen ein durchdringendes Geräusch. Inmitten des Chaos scheinen sie etwas zu umzingeln..."
  },
  AvgDialog_23862_Content_1 = {
    Text = "Verdammtes Miststück, verdammtes, verdammtes, verdammtes!"
  },
  AvgDialog_23862_Content_2 = {
    Text = "Die Seefahrer hätten durch den Sonaniel Bereich blockiert werden sollen. Wäre da nicht der kleine schwarzgekleidete Fremde gewesen, hätte ich friedlich in die Neue Welt entkommen können..."
  },
  AvgDialog_23862_Content_3 = {
    Text = "Aber... sie haben so viele Seefahrer besiegt... Kann es wirklich sein, dass dieser Kerl die Wahrheit sagt?"
  },
  AvgDialog_23863_Content_1 = {
    Text = "Aber... seit wann fängt Miryam an, Tricks wie diese zu benutzen?\nJemanden zu täuschen, damit ich zurückgehe... das ist nicht ihr Stil."
  },
  AvgDialog_23863_Content_2 = {
    Text = "Murphy? Bist du hier?"
  },
  AvgDialog_23863_Content_3 = {
    Text = "Tch, es lässt mich einfach nicht in Ruhe."
  },
  AvgDialog_23864_Content_1 = {
    Text = "Besatzungsmitglied"
  },
  AvgDialog_23864_Content_10 = {
    Text = "Du hast diese mentalen Tricks verwendet, um Miryam zu beleidigen, und dennoch gesagt \"zu wissen, dass du lebst\"... Sogar tote Fische am Ufer wissen, dass ihr keine Verbündeten seid"
  },
  AvgDialog_23864_Content_11 = {
    Text = "Was meinst du mit \"sicherer Hafen\"?"
  },
  AvgDialog_23864_Content_12 = {
    Text = "Folge mir einfach leise. Stelle nicht zu viele Fragen."
  },
  AvgDialog_23864_Content_13 = {
    Text = "Murphy war es egal, ob du und Tulu folgten. Sie öffnete mühelos ein weiteres Tor und schlüpfte hindurch."
  },
  AvgDialog_23864_Content_14 = {
    Text = "Als du gerade dabei bist, ihnen nachzujagen, streckt Tulu einen Tentakel aus und blockiert deinen Weg zur Tür."
  },
  AvgDialog_23864_Content_15 = {
    Text = "Hüter, lass dich nicht in der Nähe dieses Mädchens fallen."
  },
  AvgDialog_23864_Content_16 = {Text = "Warum?"},
  AvgDialog_23864_Content_17 = {
    Text = "Tulu beantwortete deine Frage nicht direkt, sondern konterte mit einer eigenen Frage."
  },
  AvgDialog_23864_Content_18 = {
    Text = "Ich möchte wissen, was du von den Seefahrern hältst?"
  },
  AvgDialog_23864_Content_19 = {
    Text = "Seefahrer? Spaltige Finger, vollständig fischähnlich über dem Schwanzwirbel, mit etwas Intelligenz."
  },
  AvgDialog_23864_Content_2 = {
    Text = "Murphy führt dich durch die Kabinen und vermeidet heimlich die Verfolgung der Seefahrer."
  },
  AvgDialog_23864_Content_20 = {
    Text = "Die Form ist glatt und natürlich, anders als die Arbeit der Bildhauer-Gilde, die immer in einem Durcheinander endet."
  },
  AvgDialog_23864_Content_21 = {
    Text = "Ich dachte ursprünglich, dass ihr Erscheinen das Ergebnis einer Mutation durch <Yellow:Katastrophen> war, aber während dieser wenigen Kämpfe bemerkte ich kein offensichtliches <Yellow:D-Mark> an ihnen."
  },
  AvgDialog_23864_Content_22 = {
    Text = "Der Seefahrer... scheint mehr wie ein törichter Witz zu sein, den die Evolution der Menschheit gespielt hat."
  },
  AvgDialog_23864_Content_23 = {
    Text = "Sie verehren Miryam als den Hochpriester, mehr eine gläubige Gruppe als ein Stamm."
  },
  AvgDialog_23864_Content_24 = {
    Text = "\"Ein törichter Witz auf die Menschheit gespielt,\" Yu schätzte ваше метафору."
  },
  AvgDialog_23864_Content_25 = {
    Text = "Das Mädchen – Murphy. Als wir sie trafen, verneigten sich die Seefahrer neben ihr. Angesichts ihrer Vertrautheit mit Miryam ist sie keine gewöhnliche Anhängerin."
  },
  AvgDialog_23864_Content_26 = {
    Text = "Sag Yu: Existiert \"Murphy\" in Miryams Geisterwelt?"
  },
  AvgDialog_23864_Content_27 = {
    Text = "Du öffnest deinen Mund, aber bevor deine Stimmbänder vibrieren konnten, kamen schwache Schreie und undeutliche Geräusche von hinter der Tür."
  },
  AvgDialog_23864_Content_3 = {
    Text = "Wohin gehen wir?"
  },
  AvgDialog_23864_Content_4 = {
    Text = "Geh an einen sicheren Ort und finde jemanden, der helfen kann."
  },
  AvgDialog_23864_Content_5 = {
    Text = "Hattest du nicht einen Kameraden, der mitgenommen wurde? Ich kenne jemanden, der alles über das Schiff weiß."
  },
  AvgDialog_23864_Content_6 = {
    Text = "Zuerst finde sie. Dann lass sie den Standort deines Gefährten bestimmen... Es ist besser, als wie ein kopfloses Huhn umherzulaufen, oder?"
  },
  AvgDialog_23864_Content_7 = {
    Text = "Apropos, denkst du nicht, dass wir jetzt die Bösewichte sind?"
  },
  AvgDialog_23864_Content_8 = {
    Text = "Murphy schaute mit einem katzenartigen Schnurren zurück zu dir."
  },
  AvgDialog_23864_Content_9 = {
    Text = "Ich bin kein Dummkopf; ich habe alles gehört, was du und dieser Tentakel-Junge gesagt haben."
  },
  AvgDialog_23865_Content_1 = {
    Text = "Genug, es sind nur unbedeutende Leute"
  },
  AvgDialog_23865_Content_2 = {
    Text = "Stumm im Rücken der Feinde stehend, sprach eine Gestalt, die von Anfang an ruhig geblieben war, endlich.\nEs war eine erwachsene Frau, ihr Körper in schwarzes Gaze gehüllt, fiel unauffällig unter den hässlichen, deformierten Fischmenschen auf."
  },
  AvgDialog_23865_Content_3 = {
    Text = "Die Zeit der Ausrichtung naht. Treue Meereswanderer, Gläubige des Gottesreichs, beendet diese Farce... Willkommen zurück, <Blue:Gottesmutter>, und willkommen der Rückkehr der Götter."
  },
  AvgDialog_23865_Content_4 = {
    Text = "Unter ihrem Befehl trat ein Junge, der sich von den fischartigen Wesen abhob, vor.\nEr neigte respektvoll den Kopf vor der Frau, seine Stimme war voller unerschütterlicher Loyalität und Stolz."
  },
  AvgDialog_23865_Content_5 = {
    Text = "Zu deinen Diensten, Lady Miryam."
  },
  AvgDialog_23866_Content_1 = {Text = "Sieh dort!"},
  AvgDialog_23866_Content_10 = {
    Text = "Was versuchst du zu tun!? Du hast kein Recht, Hand an mich zu legen! Wenn du dich traust, nimm mich mit zu Miryam!"
  },
  AvgDialog_23866_Content_11 = {
    Text = "Miryam... das ist die Frau, die wir gerade gesehen haben! Ist sie mit diesem Anführer verbündet? Aber warum jagen die Seefahrer sie..."
  },
  AvgDialog_23866_Content_12 = {
    Text = "Bevor du die Situation verstehen konntest, strich ein dicker Tentakel über deine Schulter und stürmte auf den Seefahrer zu."
  },
  AvgDialog_23866_Content_13 = {
    Text = "Letztere wurde überrascht, reagierte aber schnell, zischte und fuchtelte mit ihrer Zunge, während sie mit Tululs Tentakeln kämpfte."
  },
  AvgDialog_23866_Content_2 = {
    Text = "@1 Mutter... Göttin @2..."
  },
  AvgDialog_23866_Content_3 = {
    Text = "Mehrere Seefahrer bilden einen Kreis, der eine Ecke der Kabine einkreist. Ihre harten Gesänge übertönen fast die Schluchzer des Mädchens."
  },
  AvgDialog_23866_Content_4 = {
    Text = "Sei nicht... Komm nicht näher! Du wirst mich nicht zurücknehmen!"
  },
  AvgDialog_23866_Content_5 = {
    Text = "Das... ist nicht Ramona."
  },
  AvgDialog_23866_Content_6 = {
    Text = "Der führende Seefahrer kniet respektvoll vor dem Mädchen, während andere ihre schwimmhäutigen Hände benutzen, um ihre Gliedmaßen zu greifen."
  },
  AvgDialog_23866_Content_7 = {
    Text = "Die Anführerin richtete sich plötzlich auf, und du sahst, dass unter \"ihrem\" Schleier mehrere writhende Schlangenköpfe waren, extrem unheimlich."
  },
  AvgDialog_23866_Content_8 = {
    Text = "Der Schlangenmensch zeichnet seltsame Runen auf den Boden und nimmt einen stinkenden Beutel von einem Seefahrer entgegen, der einen übelriechenden Geruch ausströmt."
  },
  AvgDialog_23866_Content_9 = {
    Text = "Die Fänge der Schlange rissen ein Loch in den Sack und schütteten verrottete Organe wie Sardinen auf die Runen, wodurch die Kabine mit einem üblen Gestank gefüllt wurde."
  },
  AvgDialog_23867_Content_1 = {
    Text = "Wahnsinniger Küchenmesser"
  },
  AvgDialog_23867_Content_10 = {
    Text = [[
Aber schau dir an, was vor uns liegt.
Nur eine versiegelte Wand, ohne sogar einen Schacht, durch den man kriechen kann.]]
  },
  AvgDialog_23867_Content_11 = {
    Text = "Ich... ich komme nur selten allein herunter, normalerweise bin ich mit dem Kapitän und den anderen zusammen"
  },
  AvgDialog_23867_Content_12 = {
    Text = "An der Wand ist ein Grundriss"
  },
  AvgDialog_23867_Content_13 = {
    Text = "Was meinst du? Glaubst du nicht an mein Gedächtnis?"
  },
  AvgDialog_23867_Content_14 = {
    Text = "Ich sagte, ich finde sie, der Kapitän und die anderen müssen hier sein!"
  },
  AvgDialog_23867_Content_15 = {
    Text = [[
Mein Partner wartet noch auf unsere Hilfe.
Bitte, Meister Murphy, schau dir den Grundriss an.]]
  },
  AvgDialog_23867_Content_16 = {Text = "...Hmph!"},
  AvgDialog_23867_Content_17 = {
    Text = "Murphy stampfte wütend mit dem Fuß und näherte sich widerwillig der Wandkarte"
  },
  AvgDialog_23867_Content_18 = {Text = "Hmm..."},
  AvgDialog_23867_Content_19 = {
    Text = "Ich schaue mal"
  },
  AvgDialog_23867_Content_2 = {
    Text = "Seltsam... Ich erinnere mich, dass der Kapitän gesagt hat, man solle in Gefahr zur Maschinenkammer gehen..."
  },
  AvgDialog_23867_Content_20 = {
    Text = "Wenn du in den Maschinenraum möchtest, musst du dieses Deck über diese Treppe verlassen und zur oberen Etage hinaufgehen."
  },
  AvgDialog_23867_Content_21 = {
    Text = "Ja, ja! Ich erinnere mich jetzt. Der Maschinenraum ist sehr geschlossen, aber es ist sicherer, da es nur einen Eingang und Ausgang gibt."
  },
  AvgDialog_23867_Content_22 = {
    Text = "Es scheint, dass wir keine Wahl haben, als zur Plattform zurückzukehren."
  },
  AvgDialog_23867_Content_23 = {
    Text = "Ramona und ich wurden auf dem Deck von den Seefahrern umringt... Es müssen noch mehr Seefahrer auf Patrouille sein. Wir sollten vorsichtig sein und den Kampf vermeiden."
  },
  AvgDialog_23867_Content_3 = {Text = "Murphy..."},
  AvgDialog_23867_Content_4 = {
    Text = "Störe mich nicht. Ich bin mitten im Nachdenken."
  },
  AvgDialog_23867_Content_5 = {
    Text = "Du bist dir nicht sicher, ob du Murphy beim Nachdenken stören sollst.\nAber du weißt, dass du sie aufhalten musst"
  },
  AvgDialog_23867_Content_6 = {
    Text = "Geführt von Murphy, kamen die drei von euch am Ende der Kabine an. Vor Ihnen stand eine kalte, harte Stahlwand, mit einer einzigen Treppe nach oben als dem einzigen Weg nach vorne."
  },
  AvgDialog_23867_Content_7 = {
    Text = "Hast du dich verlaufen?"
  },
  AvgDialog_23867_Content_8 = {
    Text = "Nein! Ich kann mich nicht verlaufen!"
  },
  AvgDialog_23867_Content_9 = {
    Text = "Ich habe mehrere Monate auf diesem Schiff gelebt, ich kenne jeden Lüftungsschacht und jede Mäusehöhle"
  },
  AvgDialog_23872_Content_1 = {Text = "Apostel"},
  AvgDialog_23880_Content_1 = {
    Text = "Der schwarze Nebel ließ Sorel leise los und wogte ziellos in alle Richtungen."
  },
  AvgDialog_23880_Content_10 = {
    Text = "Die Welt um dich herum beginnt auseinanderzufallen."
  },
  AvgDialog_23880_Content_11 = {
    Text = "Die Kuppel schälte sich ab wie Weidenkätzchen, und die sichtbare Welt verzerrte sich, riss und zerbrach wie Segel in einem starken Wind."
  },
  AvgDialog_23880_Content_12 = {
    Text = [[
20:58 Uhr
2 Minuten bis zum Kollaps des Geheimgangs <Red:2>]]
  },
  AvgDialog_23880_Content_13 = {
    Text = "Der Geheimgang kollabiert! Einfach bis zur letzten Sekunde durchhalten und vermeiden, von diesem schwarzen Nebel berührt zu werden..."
  },
  AvgDialog_23880_Content_14 = {
    Text = "Du taumelst zum Rand der Terrasse."
  },
  AvgDialog_23880_Content_15 = {
    Text = "Oh nein... Wir haben keinen Ausweg!"
  },
  AvgDialog_23880_Content_16 = {
    Text = "Hinter euch rollt der tosende, wogende schwarze Nebel wie Meereswellen heran."
  },
  AvgDialog_23880_Content_17 = {
    Text = "Vor euch erstreckt sich ein schwarzer Abgrund, so weit das Auge reicht."
  },
  AvgDialog_23880_Content_18 = {
    Text = [[
20:59 Uhr
1 Minute bis zum Kollaps des Geheimgangs <Red:1>]]
  },
  AvgDialog_23880_Content_19 = {
    Text = "Sorel nimmt sanft deine Hand."
  },
  AvgDialog_23880_Content_2 = {
    Text = "...Ist Er gegangen?"
  },
  AvgDialog_23880_Content_20 = {
    Text = "Diesmal musst du dich beeilen, Schutzherr."
  },
  AvgDialog_23880_Content_21 = {
    Text = "In der nächsten Sekunde stürzt ihr alle in die tiefe Dunkelheit vor euch."
  },
  AvgDialog_23880_Content_22 = {
    Text = "Der Wind heult in meinen Ohren, wie der sanfte Atem der Götter, die sich im Schlaf regen."
  },
  AvgDialog_23880_Content_23 = {
    Text = "Sorel umklammert deine Hand fest, ihr zerzaustes Haar verschmilzt mit der Dunkelheit. Plötzlich lacht sie."
  },
  AvgDialog_23880_Content_24 = {
    Text = "Worüber lachst du?"
  },
  AvgDialog_23880_Content_25 = {
    Text = "...Du siehst jetzt aus wie ein wahrer Ritter."
  },
  AvgDialog_23880_Content_26 = {
    Text = "Ein angesehener und wahrer Ritter, gezwungen, eine falsche Prinzessin zu retten."
  },
  AvgDialog_23880_Content_27 = {
    Text = "Du betrachtest ihr Gesicht, so nah an deinem. Anders als ihr einstiges makelloses Selbst trägt sie nun Narben und ist von Erschöpfung gezeichnet."
  },
  AvgDialog_23880_Content_28 = {
    Text = "Ich denke... du siehst jetzt tatsächlich wie eine wahre Prinzessin aus."
  },
  AvgDialog_23880_Content_29 = {
    Text = "Sorels Augen wölbten sich sanft, wie die Oberfläche eines bodenlosen Sees, der zartes Sternenlicht widerspiegelt."
  },
  AvgDialog_23880_Content_3 = {
    Text = "Sorel schloss sanft ihre Augen."
  },
  AvgDialog_23880_Content_30 = {
    Text = "Es ist mir eine Ehre, %player%."
  },
  AvgDialog_23880_Content_32 = {
    Text = "Der sich stetig ausbreitende schwarze Nebel bleibt weit zurück. Du hältst Sorel fest umschlungen und lässt dich rasch in die Dunkelheit fallen."
  },
  AvgDialog_23880_Content_33 = {
    Text = [[
21:00 Uhr
<Red:Zusammenbruch des Bereichs>]]
  },
  AvgDialog_23880_Content_34 = {
    Text = "Dong — Dong —"
  },
  AvgDialog_23880_Content_35 = {
    Text = "Die Glockenschläge der vollen Stunde treiben gemächlich dahin und sinken hinab bis ans Ende des Spiralabgrunds."
  },
  AvgDialog_23880_Content_36 = {
    Text = "Dann hörtest du den Geheimgang zerbersten, wie ein Herz, das unbemerkt in der Ferne bricht."
  },
  AvgDialog_23880_Content_37 = {
    Text = "Du hörst auch das Geräusch brechender Knochen und in alle Richtungen fliegenden Fleisches."
  },
  AvgDialog_23880_Content_38 = {
    Text = "Ein schwacher Rosenduft erreicht deine Nase. Du schließt die Augen und fühlst dich zum ersten Mal erleichtert."
  },
  AvgDialog_23880_Content_39 = {
    Text = "■<Yellow:Zusammenfassung des dritten Ermittlungseinsatzes im künstlichen Labyrinth>\n\nWir haben N und den schwarzen Nebel vertrieben, bevor der Geheimgang kollabierte.\nIch bin mir nicht sicher, ob es funktioniert hat, aber nach Sorels zweitem Erwachen war ihre Hand sauber, ohne Vertragszeichen.\n\nFrau Doll sagte, dass die ersten Worte, die Sorel beim Aufwachen sprach, waren—"
  },
  AvgDialog_23880_Content_4 = {
    Text = "Ich kann Seine Präsenz nicht mehr spüren. Er muss gegangen sein."
  },
  AvgDialog_23880_Content_40 = {
    Text = "<Yellow:Wir sind zusammen geflohen.>"
  },
  AvgDialog_23880_Content_5 = {
    Text = "Er war schon immer einer, der Ärger aus dem Weg geht."
  },
  AvgDialog_23880_Content_6 = {
    Text = "Was ist mit diesem schwarzen Nebel...?"
  },
  AvgDialog_23880_Content_7 = {
    Text = "Berühre ihn nicht, sonst könntest du in eine unerwartete Dimension gezogen werden."
  },
  AvgDialog_23880_Content_8 = {
    Text = "Klopf, klopf. Klopf, klopf."
  },
  AvgDialog_23880_Content_9 = {
    Text = "Du scheinst einen rasenden Puls aus den Tiefen des Universums zu hören, während der schwarze Nebel unaufhörlich wogt und zurückweicht."
  },
  AvgDialog_23881_Content_1 = {
    Text = "Huh... Ist Er schon wieder verschwunden?"
  },
  AvgDialog_23881_Content_10 = {
    Text = "Mein Plan wurde entdeckt... Ugh!"
  },
  AvgDialog_23881_Content_11 = {
    Text = "Sorel stieß ein leises Stöhnen aus. Schleimfäden sickerten aus den in ihren Handrücken geritzten Buchstaben und krochen langsam an ihrem Körper empor."
  },
  AvgDialog_23881_Content_13 = {
    Text = "Das scharfe Messer schneidet ohne Zögern durch die Dornen, zerreißt das elegante Kleid und legt die vernarbte Haut darunter frei."
  },
  AvgDialog_23881_Content_14 = {
    Text = "Sorel umklammert ihre Klinge, ihr Ausdruck ruhig wie Wasser, ohne auch nur zu blinzeln."
  },
  AvgDialog_23881_Content_15 = {
    Text = "Dieses Messer gehört nicht Herrn Lambert...?"
  },
  AvgDialog_23881_Content_16 = {
    Text = "Ja. Ich wusste von Anfang an, dass er sich draußen versteckte und dieses Messer in der Hand hielt."
  },
  AvgDialog_23881_Content_17 = {
    Text = "Schade, ich habe gewartet und gewartet... Am Ende ist er doch weggelaufen und hat dieses Messer zurückgelassen."
  },
  AvgDialog_23881_Content_18 = {
    Text = "Heh... Mein lieber Vater, was kann er schon anderes tun, als mir Ärger zu bereiten?"
  },
  AvgDialog_23881_Content_19 = {
    Text = "Er schafft es nicht einmal, mich umzubringen."
  },
  AvgDialog_23881_Content_2 = {
    Text = "Einfach ein Versteckspiel mit uns spielen. Sich in den Schatten verbergen, meine Angst und meinen Schmerz auskosten..."
  },
  AvgDialog_23881_Content_21 = {
    Text = "Sorel schlägt auf die wild wuchernden Ranken ein und schabt jedes Stück nekrotischen Fleisches heraus."
  },
  AvgDialog_23881_Content_22 = {
    Text = "Sie blickte hinauf zur pechschwarzen, scheinbar endlosen Decke."
  },
  AvgDialog_23881_Content_23 = {
    Text = "Du musst jetzt zufrieden sein, mich in einem so erbärmlichen Zustand zu sehen..."
  },
  AvgDialog_23881_Content_24 = {
    Text = "Wie immer erhielt sie keine Antwort — nur der Nebel, der sich um ihren Körper schlang."
  },
  AvgDialog_23881_Content_25 = {
    Text = "Ist das die Strafe dafür, den Vertrag gebrochen zu haben? Ich werde hier nicht fallen..."
  },
  AvgDialog_23881_Content_26 = {
    Text = "Als ich zum ersten Mal aus der Provinz von Konstant aufbrach, war ich allein, ohne Geld und ohne Ruhm."
  },
  AvgDialog_23881_Content_27 = {
    Text = "Lügen sind meine Tarnung, Gerüchte sind meine Waffe, und die Massen sind meine Leiter, um höher zu steigen.\nAlles in dieser Welt dient meinem Zweck."
  },
  AvgDialog_23881_Content_28 = {
    Text = "Ich habe es bis hierher geschafft, weder wegen meines Vaters noch wegen N."
  },
  AvgDialog_23881_Content_29 = {
    Text = "Das Einzige, worauf ich mich wirklich verlasse, bin ich selbst."
  },
  AvgDialog_23881_Content_3 = {Text = "Hmm—!!"},
  AvgDialog_23881_Content_30 = {
    Text = "Ich habe mich entschieden, einen Vertrag mit Ihm zu schließen. Ich habe mich entschieden, ihn zu brechen. Ich habe mich entschieden..."
  },
  AvgDialog_23881_Content_31 = {
    Text = "Meinen Vater für immer loszuwerden."
  },
  AvgDialog_23881_Content_32 = {
    Text = "Sie umfasst sanft dein Handgelenk."
  },
  AvgDialog_23881_Content_33 = {
    Text = "Dieser Schatten ist lediglich eine Projektion von Ihm in der sterblichen Welt und nicht ohne Gegenmaßnahmen."
  },
  AvgDialog_23881_Content_34 = {
    Text = "Solange ich <Yellow:durchhalten kann, bis der Geheimgang endet>, werde ich die wiederauferstandene Sorel bleiben, und der Vertrag wird nichtig."
  },
  AvgDialog_23881_Content_35 = {
    Text = "Hilf mir, diese schwierige Zeit zu überstehen, und ich werde deine Bedingungen in Betracht ziehen."
  },
  AvgDialog_23881_Content_36 = {
    Text = "<Gray:Selbst in einer solchen Situation „denkst du immer noch nur darüber nach\"...?>"
  },
  AvgDialog_23881_Content_37 = {
    Text = "Ich weiß, was du denkst.\nKeine Sorge, ich kann etwa 70% dieser Bedingungen akzeptieren. Die alten Herren sollten vor Freude die Champagnerkorken knallen lassen."
  },
  AvgDialog_23881_Content_38 = {
    Text = "Aber das ist doch nur ein künstlicher Geheimgang. Du wirst in der Realität keinen Schaden erleiden. Warum...?"
  },
  AvgDialog_23881_Content_39 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23881_Content_4 = {
    Text = "Sorel brach auf dem Boden zusammen. Unter ihr breitete sich langsam ein dunkelroter Blutfleck unter ihrem Rock aus."
  },
  AvgDialog_23881_Content_40 = {
    Text = "Ein zufriedenes Seufzen ertönt von oben, als würde es sich an deiner Angst und Hilflosigkeit laben."
  },
  AvgDialog_23881_Content_41 = {
    Text = "Schwarzer Nebel entwich unaufhörlich aus ihren Augen, ihrer Nase und ihrem Hals und verschlang dann das gesamte Opernhaus."
  },
  AvgDialog_23881_Content_42 = {
    Text = "Ein Riss durchbrach die Dunkelheit, als würde das Universum seinen gewaltigen Schlund öffnen, in dem Planeten ziellos umherrollten."
  },
  AvgDialog_23881_Content_43 = {
    Text = "Es ist, als hätten die Götter träge ihre Augen aus einem Traum geöffnet."
  },
  AvgDialog_23881_Content_44 = {
    Text = "Kein Licht, keine Zugehörigkeit, keine Empfindung."
  },
  AvgDialog_23881_Content_45 = {Text = "Bumm—"},
  AvgDialog_23881_Content_46 = {
    Text = "Mit einem lauten Krachen wird die Terrasse, auf der du stehst, zur einzigen Insel in einem Ozean aus Dunkelheit."
  },
  AvgDialog_23881_Content_47 = {
    Text = "Sorel kniete vor dem Riss. Unzählige aus dem Nebel geformte Arme umklammerten sie fest und versuchten, sie in den Riss hinter ihr zu zerren."
  },
  AvgDialog_23881_Content_48 = {
    Text = "Lady Sorel!!"
  },
  AvgDialog_23881_Content_49 = {
    Text = "Kannst du es sehen... Es ist eine Existenz, die den Gesetzen trotzt.\nRealität und Träume sind für es bedeutungslos."
  },
  AvgDialog_23881_Content_5 = {
    Text = "Madame, Ihr... Ihr blutet!"
  },
  AvgDialog_23881_Content_50 = {
    Text = "Schwarzer Nebel durchbohrt ihren Körper und strömt dann mit rasender Kraft aus ihren Augen, ihrer Nase und ihren Ohren"
  },
  AvgDialog_23881_Content_51 = {
    Text = "Immer mehr Blut rann aus Sorels Mundwinkel, doch sie schenkte dir ein schwaches Lächeln."
  },
  AvgDialog_23881_Content_52 = {
    Text = "Hilf mir. Lass uns es gemeinsam zurücktreiben."
  },
  AvgDialog_23881_Content_53 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23881_Content_54 = {
    Text = "Geld, Macht oder was auch immer. Einfach hol mich hier raus, und ich werde deine Wünsche so gut wie möglich erfüllen."
  },
  AvgDialog_23881_Content_55 = {
    Text = "Sie kämpfte sich näher an dich heran, doch in ihrem Gesicht war keine Spur von Flehen."
  },
  AvgDialog_23881_Content_56 = {
    Text = "Es gleicht eher dem Überlebenswillen eines Tieres am Rande des Todes, das verzweifelt alles tut, um am Leben zu bleiben."
  },
  AvgDialog_23881_Content_57 = {
    Text = "%player%... Schuldest du mir nicht noch einen Drink? Erinnerst du dich?"
  },
  AvgDialog_23881_Content_58 = {
    Text = "Helfen oder nicht helfen?"
  },
  AvgDialog_23881_Content_59 = {
    Text = "Obwohl du weißt, dass sie ihr Versprechen jederzeit brechen könnte, entscheidest du dich dennoch, das Risiko einzugehen."
  },
  AvgDialog_23881_Content_6 = {
    Text = "Sorel wischte vorsichtig das Blut aus ihrem Mundwinkel. Selbst in diesem Moment würde sie nicht ein Quäntchen Fassung verlieren."
  },
  AvgDialog_23881_Content_60 = {
    Text = "Ich verspreche es dir."
  },
  AvgDialog_23881_Content_61 = {
    Text = "Bitte versteh das nicht falsch. Ich möchte nur sicherstellen, dass die Verhandlung reibungslos verläuft..."
  },
  AvgDialog_23881_Content_62 = {
    Text = "Sorels Lippen kräuselten sich leicht, ihre Augen funkelten wie Sterne und erhellten alles ringsum in der stillen Nacht."
  },
  AvgDialog_23881_Content_63 = {
    Text = "Ihr seid nicht nur ein Ritter, sondern auch ein weiser."
  },
  AvgDialog_23881_Content_7 = {
    Text = "Sie hebt mühsam den Kopf und blickt dir direkt in die Augen."
  },
  AvgDialog_23881_Content_8 = {
    Text = "Er ist sehr an dir interessiert. Dein wiederholtes Eindringen in meinen Geist hat schließlich Seine Aufmerksamkeit erregt."
  },
  AvgDialog_23881_Content_9 = {
    Text = "Wo Blut floss, erblühten groteske Rosen, und scharfe Dornen verwandelten sich in pechschwarzen Nebel, der sich langsam um ihren Körper wand."
  },
  AvgDialog_23882_Content_1 = {
    Text = "Neunauge–Elixier"
  },
  AvgDialog_23882_Content_10 = {
    Text = "<Red:Wumm—!!>"
  },
  AvgDialog_23882_Content_11 = {
    Text = "Gut, es gibt eine Reaktion. Vorbereiten für den zweiten Elektroschock."
  },
  AvgDialog_23882_Content_12 = {
    Text = "<Red:Wumm—!!>"
  },
  AvgDialog_23882_Content_13 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23882_Content_14 = {
    Text = "Puh... endlich gerettet."
  },
  AvgDialog_23882_Content_15 = {
    Text = "Willkommen zu Hause, %player%."
  },
  AvgDialog_23882_Content_16 = {
    Text = "Mythag Krankenhaus\nZwei Stunden später"
  },
  AvgDialog_23882_Content_17 = {
    Text = "Fräulein Sylvia, warum sind Sie auch hier...?"
  },
  AvgDialog_23882_Content_18 = {
    Text = "Ich habe gehört, dass jemand zweimal hintereinander das künstliche Labyrinth betreten hat. Als psychologische Beraterin bei Misaq muss ich den mentalen Zustand aller überprüfen."
  },
  AvgDialog_23882_Content_19 = {
    Text = "Entschuldigung, Fräulein Sylvia, für die Umstände..."
  },
  AvgDialog_23882_Content_2 = {
    Text = "Adrenalin wirkt nicht, Blut fließt weiter aus meinen Augen und meiner Nase... und auch aus den Ohren."
  },
  AvgDialog_23882_Content_20 = {
    Text = "Sylvia schüttelte sanft den Kopf."
  },
  AvgDialog_23882_Content_21 = {
    Text = "Mach dir keine Sorgen, dieses Mal bin ich vorbereitet—"
  },
  AvgDialog_23882_Content_22 = {
    Text = "Dieses Mal habe ich meine neueste Kreation mitgebracht, <Blue:Neunauge-Oolong-Tee>, der eine belebende und erfrischende Wirkung hat～"
  },
  AvgDialog_23882_Content_23 = {
    Text = "Neunauge? Oolong-Tee? Wie werden die kombiniert..."
  },
  AvgDialog_23882_Content_24 = {
    Text = "Dieser Tee verströmt eine starke unheilvolle Aura, sowohl vom Namen als auch vom Geruch her.\nWiderwillig nimmst du ein paar Schlucke."
  },
  AvgDialog_23882_Content_25 = {
    Text = "Wie ist er? Du bist der erste Tester."
  },
  AvgDialog_23882_Content_26 = {
    Text = "Ramona hat ihn nicht einmal angeschaut, bevor sie abgelehnt hat... So herzlos..."
  },
  AvgDialog_23882_Content_27 = {
    Text = "Bitter. Er ist einfach zu bitter."
  },
  AvgDialog_23882_Content_28 = {
    Text = "Sylvia schaut dich erwartungsvoll an, und du nimmst widerwillig noch zwei Schlucke."
  },
  AvgDialog_23882_Content_29 = {
    Text = "Nicht schlecht... Ich muss sagen, sein Geschmack ist beeindruckend und wirklich belebend."
  },
  AvgDialog_23882_Content_3 = {
    Text = "Herzstillstand. Vielleicht das versuchen, was Winkle gesagt hat... Elektroschock..."
  },
  AvgDialog_23882_Content_30 = {
    Text = "In einer halben Stunde"
  },
  AvgDialog_23882_Content_31 = {
    Text = "Was passiert im Geheimgang?"
  },
  AvgDialog_23882_Content_32 = {
    Text = "Ramona sagte, dass du mit Frau Sorel getrunken hast, Witze über Dexter gemacht hast und dann plötzlich den Kontakt verloren hast."
  },
  AvgDialog_23882_Content_33 = {
    Text = "...Ich bin aufgeflogen."
  },
  AvgDialog_23882_Content_34 = {Text = "?!"},
  AvgDialog_23882_Content_35 = {
    Text = "Frau Sorels Bewusstsein, oder vielleicht etwas anderes, hat mein Eindringen in den Geheimgang bemerkt."
  },
  AvgDialog_23882_Content_36 = {
    Text = "Der Schatten auf der Bühne... ist eine mächtige Präsenz."
  },
  AvgDialog_23882_Content_37 = {
    Text = "Er hat mich entdeckt und mir gesagt, ich soll verschwinden."
  },
  AvgDialog_23882_Content_38 = {
    Text = "Verstehe, wir haben Frau Sorel unterschätzt. Der Schatten könnte ein Teil ihres Bewusstseins sein..."
  },
  AvgDialog_23882_Content_39 = {
    Text = "Getrieben von einem Schutzinstinkt wird er alle Eindringlinge vertreiben."
  },
  AvgDialog_23882_Content_4 = {
    Text = "Nein, das ist viel zu riskant."
  },
  AvgDialog_23882_Content_40 = {
    Text = "Vielleicht... es scheint eine Lücke in meiner Erinnerung zu geben. Ich habe das Gefühl, dass der Schatten etwas wirklich Wichtiges gesagt hat..."
  },
  AvgDialog_23882_Content_41 = {
    Text = "Frau Sorels Silber-Veredelung verlief reibungslos. Diese Fragen müssen warten, bis wir sie bei ihrem zweiten Erwachen direkt fragen können."
  },
  AvgDialog_23882_Content_42 = {
    Text = "Müssen wir den Geheimgang noch zur Untersuchung betreten?"
  },
  AvgDialog_23882_Content_43 = {
    Text = "Oolong-Tee ist tatsächlich wirksam; du bemerkst aufmerksam Dolls seltenen Moment, in dem sie den Blick abwendet."
  },
  AvgDialog_23882_Content_44 = {
    Text = "...Keine Eile, ruh dich erst einmal gut aus."
  },
  AvgDialog_23882_Content_45 = {
    Text = "Klopf, klopf."
  },
  AvgDialog_23882_Content_46 = {
    Text = "Eine Reihe regelmäßiger Klopfgeräusche ertönte, und Dexter kam mit seinen langen Beinen hereinspaziert."
  },
  AvgDialog_23882_Content_47 = {
    Text = "Gott sei Dank bist du endlich wach. Ramona hat geweint und einen Aufstand gemacht, um dich zu besuchen, und dabei fast meine Kleidung zerrissen."
  },
  AvgDialog_23882_Content_48 = {
    Text = "Wie wäre es, diese Tasse Oolong-Tee zu probieren? Er erfrischt den Geist und befreit dich von unnötigen Wahnvorstellungen."
  },
  AvgDialog_23882_Content_49 = {
    Text = "Wie könnte ich nur? Ich kann unmöglich die spezielle Mischung annehmen, die Fräulein Silvia nur für dich zubereitet hat."
  },
  AvgDialog_23882_Content_5 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23882_Content_50 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23882_Content_51 = {
    Text = "Du siehst bedrückt aus? Lass uns über etwas Erfreuliches reden."
  },
  AvgDialog_23882_Content_52 = {
    Text = "Diesmal hast du bedeutende Durchbrüche im künstlichen Labyrinth erzielt."
  },
  AvgDialog_23882_Content_53 = {
    Text = "Ich habe mir ziemliche Sorgen wegen des Adligen gemacht, dem du drinnen begegnet bist, also bin ich mit ein paar Freunden von der Polizei etwas trinken gegangen."
  },
  AvgDialog_23882_Content_54 = {
    Text = "...Das Trinken ist dein eigentliches Ziel, nicht wahr?"
  },
  AvgDialog_23882_Content_55 = {
    Text = "Ahem. Kurz gesagt, sie haben mir gesagt, dass am Tag, an dem Frau Sorel verstorben ist, tatsächlich eine Person gegangen ist, ohne eine Aussage abzugeben."
  },
  AvgDialog_23882_Content_56 = {Text = "?!"},
  AvgDialog_23882_Content_57 = {
    Text = "Haben nicht alle ihre Aussagen gemacht?"
  },
  AvgDialog_23882_Content_58 = {
    Text = "Sie haben nicht die Wahrheit gesagt. Dieser Gast hat einen sehr hohen Status, jemand, den sie sich nicht leisten können zu verärgern."
  },
  AvgDialog_23882_Content_59 = {
    Text = "Dexter beendet seine Ausführungen und knallt eine Zeitung vor dich hin."
  },
  AvgDialog_23882_Content_6 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_23882_Content_60 = {
    Text = "Die Zeitung trug eine reißerische Schlagzeile in Großbuchstaben: „Vater–Tochter–Band! Sorel benennt Vater als alleinigen Erben,\" begleitet von einem Foto."
  },
  AvgDialog_23882_Content_61 = {
    Text = "Auf dem Foto umarmt Sorel einen alten Mann namens <Blue:Lambert> voller tiefer Emotionen. Natürlich zeigt sie dabei, während sie sich die Tränen abwischt, absichtlich den türkisfarbenen Ring an ihrer Hand."
  },
  AvgDialog_23882_Content_62 = {
    Text = "Dieser Ring wurde in jenem Jahr schnell zu einem beliebten Trend, und diverse Nachahmungen tauchten eine nach der anderen auf."
  },
  AvgDialog_23882_Content_63 = {
    Text = "Bewertung dieses Mannes. Ist Herr Lambert der Herr, den du im künstlichen Labyrinth gesehen hast?"
  },
  AvgDialog_23882_Content_64 = {
    Text = "Damals zeigte er nur eine Hand. Sie war dünn, als wäre er schwer krank, und mit vielen Ringen geschmückt..."
  },
  AvgDialog_23882_Content_65 = {
    Text = "Der ältere Mann auf dem Foto ist prunkvoll gekleidet, sein Gesicht verdeckt. Dir fallen seine Hände auf, die Sorel fest umklammern."
  },
  AvgDialog_23882_Content_66 = {
    Text = [[
Derselbe extravagante Stil, dieselbe schlanke Figur, sogar die Altersflecken sind an genau derselben Stelle...
Er ist es.]]
  },
  AvgDialog_23882_Content_67 = {
    Text = "Wir kamen auch auf ein Herrenhaus voller Rosen. Ich vermute, es hat mit Frau Sorel zu tun..."
  },
  AvgDialog_23882_Content_68 = {
    Text = "Dex nickte zustimmend."
  },
  AvgDialog_23882_Content_69 = {
    Text = "Ich habe einen Freund gebeten nachzuprüfen, und dieses Anwesen ist jetzt auf den Namen von Sorels Vater, Herrn Lambert, eingetragen."
  },
  AvgDialog_23882_Content_7 = {
    Text = "Fahren wir fort. Vorbereiten für den ersten Elektroschock."
  },
  AvgDialog_23882_Content_70 = {
    Text = "Im Bereich hält jemand mit einem Messer vor dem Kasten von Mrs. Sorel Wach. Anhand der Gestalt ist es wahrscheinlich Mr. Lambert."
  },
  AvgDialog_23882_Content_71 = {
    Text = "In Ordnung, jetzt fügt sich alles zusammen. <Yellow:Herr Lambert ist ein Hauptverdächtiger.>"
  },
  AvgDialog_23882_Content_72 = {
    Text = "Was ist mit diesem maskierten Schatten? Wir haben mit eigenen Augen gesehen, wie er Sorel getötet hat."
  },
  AvgDialog_23882_Content_73 = {
    Text = "Vielleicht ein Komplize, aber lasst uns zuerst Lambert fassen."
  },
  AvgDialog_23882_Content_74 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23882_Content_75 = {
    Text = "Ich habe gehört, dass Sorel und Herr Lambert sich sehr nahestehen und oft gemeinsam gesellschaftliche Veranstaltungen besuchen. Ich hätte nicht erwartet, dass eine solche Geschichte dahintersteckt."
  },
  AvgDialog_23882_Content_76 = {
    Text = "Ein Vater, der plant, seine eigene Tochter zu töten? Unerhört."
  },
  AvgDialog_23882_Content_77 = {
    Text = "Dexter zuckte gleichgültig mit den Schultern."
  },
  AvgDialog_23882_Content_78 = {
    Text = "Je näher man Macht und Geld kommt, desto weiter entfernt man sich von der Menschlichkeit. Die Leute in diesem Kreis sind Meister der Schauspielerei."
  },
  AvgDialog_23882_Content_79 = {
    Text = "Wie steht es mit Euch, Lorde Dexter? Seid Ihr auch gut im Schauspielern?"
  },
  AvgDialog_23882_Content_8 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23882_Content_80 = {
    Text = "Dexter war einen Moment lang verblüfft, dann brach er in Gelächter aus."
  },
  AvgDialog_23882_Content_81 = {
    Text = "Meine Antwort hat keinen Wert, mein Kind. Vertrau deinem eigenen Urteil."
  },
  AvgDialog_23882_Content_82 = {
    Text = "...kommen wir zurück zum Thema. Wo ist Ramona hin?"
  },
  AvgDialog_23882_Content_83 = {
    Text = "Sie hat sich schnell erholt und ist mit der Polizei losgezogen, um Herrn Lambert zu verhaften."
  },
  AvgDialog_23882_Content_84 = {
    Text = "Dieser alte Fuchs ist äußerst gerissen; gebt ihm keine Chance zur Flucht."
  },
  AvgDialog_23882_Content_85 = {
    Text = "Misaq Universität\nSchulsekretariat"
  },
  AvgDialog_23882_Content_86 = {
    Text = "Jetzt sind nur noch wir zwei hier. Lass uns offen und ehrlich miteinander reden."
  },
  AvgDialog_23882_Content_87 = {
    Text = "%player% und Ramona haben keine Ahnung, aber mich täuscht man nicht so leicht."
  },
  AvgDialog_23882_Content_88 = {
    Text = "<Yellow:Sorel ist seit Jahrhunderten ein Erweckter Körper. Wo kommt dieser Vater auf einmal her?>"
  },
  AvgDialog_23882_Content_89 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23882_Content_9 = {
    Text = "Bin ich... tot...?"
  },
  AvgDialog_23882_Content_90 = {
    Text = "Frag lieber nicht nach ihr; es wird nichts bringen. Ich bin nicht der endgültige Entscheidungsträger für diesen Ermittlungsauftrag."
  },
  AvgDialog_23882_Content_91 = {
    Text = "Wunderbar, es scheint, als hätten wir uns wirklich einen ordentlichen Schlamassel eingehandelt."
  },
  AvgDialog_23882_Content_92 = {
    Text = "Die Lage könnte ernster sein, als du denkst. <Yellow:Oben> hat heute Leute geschickt und mich gebeten, allein mit %player% zu sprechen, um {Male=him,Female=her} neue Aufgaben zuzuweisen."
  },
  AvgDialog_23882_Content_93 = {
    Text = "...Sogar die Oberen wurden aufgeschreckt..."
  },
  AvgDialog_23882_Content_94 = {
    Text = "Sorel ist kein gewöhnlicher Erweckter Körper. Die Macht und Ressourcen hinter ihr sind gewaltig, sie übertreffen sogar die deiner Familie."
  },
  AvgDialog_23882_Content_95 = {
    Text = "Die Oberen werden niemals zulassen, dass Misaq Ereignisse, die mit ihr zusammenhängen, eigenständig bearbeitet."
  },
  AvgDialog_23882_Content_96 = {
    Text = "Es ist mir egal, was diese alten Männer aushecken. Ich habe nur eine einzige rote Linie –"
  },
  AvgDialog_23882_Content_97 = {
    Text = "Die Sicherheit dieser beiden Kinder."
  },
  AvgDialog_23882_Content_98 = {
    Text = "Doll stößt einen kaum hörbaren Seufzer aus."
  },
  AvgDialog_23882_Content_99 = {
    Text = "Ob du es glaubst oder nicht, das ist auch meine unterste Grenze."
  },
  AvgDialog_23883_Content_1 = {
    Text = "Nicht nur Rosen, sondern auch Noten von Lavendel und Zitrus..."
  },
  AvgDialog_23883_Content_2 = {
    Text = "Könnte es wirklich Mrs. Sorel's Badewasser sein?"
  },
  AvgDialog_23883_Content_3 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23883_Content_4 = {
    Text = "Ist das wichtig für dich?"
  },
  AvgDialog_23883_Content_5 = {
    Text = "Wenn es wirklich ihr Badewasser ist, was hast du vor?"
  },
  AvgDialog_23884_Content_1 = {Text = "Für Sorel"},
  AvgDialog_23884_Content_10 = {
    Text = "Was ihren armen Vater betrifft, er wurde als der Mörder abgestempelt, der seiner eigenen Tochter schadete, und wurde sogar des Mordes an einer Adeligen beschuldigt."
  },
  AvgDialog_23884_Content_100 = {
    Text = "Lamberts gesamter Körper zitterte, ein schrilles, hohes Lachen entwich unablässig aus den Tiefen seiner Kehle."
  },
  AvgDialog_23884_Content_101 = {
    Text = "Ich sagte zwar, dass nur der vollständige Tod unseren Vertrag beenden könnte, und du hast es ohne Zögern geglaubt."
  },
  AvgDialog_23884_Content_102 = {
    Text = "Schwache Seelen setzen ihre Hoffnungen stets auf die Gnade der Mächtigen und glauben fest an die Regeln, die diese Welt beherrschen."
  },
  AvgDialog_23884_Content_103 = {
    Text = "Doch all dies ist lediglich unser Spiel."
  },
  AvgDialog_23884_Content_104 = {
    Text = "<Shake:Ihr seid nicht er... Ihr seid...>"
  },
  AvgDialog_23884_Content_105 = {
    Text = "Lambert hüllt sich in einen dichten schwarzen Nebel, seine Gestalt verzerrt und mutiert mit jedem Atemzug des Dunstes..."
  },
  AvgDialog_23884_Content_106 = {
    Text = "<RedItalic:Ich mache die Regeln, und ich breche sie.>"
  },
  AvgDialog_23884_Content_107 = {
    Text = "Lange nicht gesehen, Sorel.\nIch habe dich so sehr vermisst, dass ich mir Herrn Lamberts Körper geliehen habe."
  },
  AvgDialog_23884_Content_108 = {
    Text = "Es ist wirklich herzzerreißend... Es scheint, als wolltest du mich nicht sehen und hast alles Erdenkliche versucht, um mich loszuwerden."
  },
  AvgDialog_23884_Content_109 = {
    Text = "Der endlose schwarze Nebel wallte hervor und durchbohrte Sorels Körper."
  },
  AvgDialog_23884_Content_11 = {
    Text = "Apropos, Sorel sollte dir wirklich danken. Wenn du sie nicht aus dem künstlichen Labyrinth herausgeholt hättest..."
  },
  AvgDialog_23884_Content_110 = {
    Text = "Nein, nein... Unser Vertrag... Ich habe ihn doch gebrochen..."
  },
  AvgDialog_23884_Content_111 = {
    Text = "Aber du hast dich umgedreht und ein Abkommen mit diesen Narren geschlossen.\nDu hast einst mir gehört. Wie könnte ich es ertragen, dich von ihnen einschränken zu lassen?"
  },
  AvgDialog_23884_Content_112 = {
    Text = "Natürlich bin ich hier, um dich zurückzuführen. Das Versteckspiel im Geheimgang war nur ein kleines Willkommensgeschenk. Hat es dir gefallen?"
  },
  AvgDialog_23884_Content_113 = {
    Text = "Sorel sank schmerzerfüllt auf die Knie. Auf dem Rücken ihrer blassen Hand erschien für einen kurzen Augenblick ein vertrauter Buchstabe und verschwand dann rasch wieder."
  },
  AvgDialog_23884_Content_114 = {
    Text = "Es ist so flüchtig wie ein vergängliches Menschenleben."
  },
  AvgDialog_23884_Content_115 = {
    Text = "Ich habe so lange geplant... War alles umsonst?"
  },
  AvgDialog_23884_Content_116 = {
    Text = "<Gray:Nein, ich glaube es nicht... Es muss einen Weg geben...>"
  },
  AvgDialog_23884_Content_117 = {
    Text = "Eine sanfte Brise wehte vorbei und ließ die karmesinroten Rosenblätter flattern. Sorel nahm einen schwachen Blumenduft aus fernen Erinnerungen wahr."
  },
  AvgDialog_23884_Content_118 = {
    Text = "Sorel, kennst du die Sprache der Rosen?"
  },
  AvgDialog_23884_Content_119 = {
    Text = "Hmm... Unerschütterliche Liebe?"
  },
  AvgDialog_23884_Content_12 = {
    Text = "Du schüttelst den Kopf."
  },
  AvgDialog_23884_Content_120 = {
    Text = "Nicht nur das. Ich habe gehört, dass im fernen Lentiniën Rosen auch für wunderschöne Sehnsüchte stehen."
  },
  AvgDialog_23884_Content_121 = {
    Text = "Sehnsucht nach Liebe, Familie und all den schönen Dingen auf der Welt.\nSorel, du wirst in Zukunft eine Sehnsucht für alle Menschen werden."
  },
  AvgDialog_23884_Content_122 = {
    Text = "Die Sehnsucht der Menschen werden...? Warum?"
  },
  AvgDialog_23884_Content_123 = {
    Text = "Weil du wie diese Rose bist, schön und widerstandsfähig.\nDu wirst niemals so sein wie ich, immer in Tränen."
  },
  AvgDialog_23884_Content_124 = {
    Text = "Meine Tochter weint nicht so leicht, noch gibt sie so leicht auf.\nSie wird ihr eigenes Schicksal mit ihren eigenen Händen ergreifen."
  },
  AvgDialog_23884_Content_125 = {
    Text = "Sorel wischte das Blut von ihrem Mundwinkel und umklammerte ihren Rock. Sie konnte N immer noch nicht direkt ins Gesicht sehen, aber ihre Stimme zitterte nicht mehr."
  },
  AvgDialog_23884_Content_126 = {
    Text = "Meister, Ihr habt Angst.\nIhr fürchtet Euch vor dem Misaq, ebenso wie vor diesem jungen Schutzherrn."
  },
  AvgDialog_23884_Content_127 = {
    Text = "N Der schwarze Nebel unter der Krempe zittert leicht, und ein heiseres, doch erfreutes Lachen dringt daraus hervor."
  },
  AvgDialog_23884_Content_128 = {
    Text = "Das ist keine Angst, mein Kind. Habt ihr Menschen nicht ein Sprichwort: „Je näher der Heimat, desto banger das Herz“?"
  },
  AvgDialog_23884_Content_129 = {
    Text = "Ich habe in der Tat einige unvermeidliche Gründe, die mich dazu treiben, Abstand zu Misaq und %player% zu halten."
  },
  AvgDialog_23884_Content_13 = {
    Text = "Ich bin nur ein Verhandlungswerkzeug, das von oben zugewiesen wurde. Wenn sie vollständig stirbt, wären die Verhandlungen doch umsonst gewesen, oder?"
  },
  AvgDialog_23884_Content_130 = {
    Text = "Ihr wolltet also nicht zu lange im Geheimgang bleiben, was uns eine Chance zur Flucht gab."
  },
  AvgDialog_23884_Content_131 = {
    Text = "Meister, Ihr wandelt seit Tausenden von Jahren durch die Menschenwelt, also müsst Ihr sicherlich wissen—"
  },
  AvgDialog_23884_Content_132 = {
    Text = "Wenn ein Mensch in die Enge getrieben wird, wohnt keine Angst mehr in seinem Herzen."
  },
  AvgDialog_23884_Content_133 = {
    Text = "Nun, heute bin ich wegen meiner Schwäche und Torheit erneut Euer Gefangener geworden."
  },
  AvgDialog_23884_Content_134 = {
    Text = [[
Aber das ist in Ordnung.
Einmal, zweimal... Solange es auch nur die geringste Chance zur Flucht gibt, werde ich sie nicht verstreichen lassen.]]
  },
  AvgDialog_23884_Content_135 = {
    Text = "Ob Misaq oder %player%, es macht für mich keinen Unterschied."
  },
  AvgDialog_23884_Content_136 = {
    Text = "Ihr wettet doch so gerne mit anderen? Wie wäre es mit einer Wette mit mir..."
  },
  AvgDialog_23884_Content_137 = {
    Text = "Dein Wachstum erstaunt mich immer wieder. Also, was steht auf dem Spiel?"
  },
  AvgDialog_23884_Content_138 = {
    Text = "Sorel schloss sanft die Augen. Sie war stolz darauf, rational zu sein, und verabscheute stets das Risiko."
  },
  AvgDialog_23884_Content_139 = {
    Text = "Das Leben kann anders sein. Das Leben selbst ist ein gewaltiges Glücksspiel, und niemand kann unversehrt bleiben."
  },
  AvgDialog_23884_Content_14 = {
    Text = "Also... nur eine Routineaufgabe, das ist alles."
  },
  AvgDialog_23884_Content_140 = {
    Text = "Der Einsatz ist... alles, was ich habe."
  },
  AvgDialog_23884_Content_141 = {
    Text = "Gut, hier endet die Geschichte vorerst.\nWas das zukünftige Schicksal jenes Rosenblume-Mädchens betrifft, lasst uns abwarten."
  },
  AvgDialog_23884_Content_142 = {
    Text = "Um sicherzustellen, dass dieses Ende nicht allzu oberflächlich wirkt, erlaubt mir, noch ein paar Worte hinzuzufügen."
  },
  AvgDialog_23884_Content_143 = {
    Text = "Menschen oder Erwecker... Ihr glaubt naiv, ihr könntet mir entkommen und eure eigene Zukunft erschaffen."
  },
  AvgDialog_23884_Content_144 = {
    Text = "<Red:Doch all das ist vergebens.>"
  },
  AvgDialog_23884_Content_145 = {
    Text = "Ihr könnt mich niemals loswerden, genauso wie ihr niemals dem <Yellow:Schicksal> entkommen könnt."
  },
  AvgDialog_23884_Content_146 = {
    Text = "Vergesst das nicht..."
  },
  AvgDialog_23884_Content_147 = {
    Text = "Als du versucht hast, dem <Yellow:Schicksal> auszuweichen, war dir das <Red:Schicksal> bereits begegnet."
  },
  AvgDialog_23884_Content_148 = {
    Text = "DAS E<Red:N>DE"
  },
  AvgDialog_23884_Content_15 = {
    Text = "<Shake:Wow! Frau Sorel ist erschienen!!>"
  },
  AvgDialog_23884_Content_17 = {
    Text = "Die Menschenmengen versammelten sich früh entlang der Straßen. Dies ist Mrs. Sorels erster öffentlicher Auftritt seit dem Vorfall."
  },
  AvgDialog_23884_Content_18 = {
    Text = "Sie trägt ein prächtiges Kleid und nimmt inmitten wirbelnder Rosenblätter gelassen die Bewunderung aller entgegen — wie eine unglaublich exquisite Puppe."
  },
  AvgDialog_23884_Content_19 = {
    Text = "Langes Haar glänzt im Sonnenlicht mit goldenem Schimmer, wie fließende Bänder."
  },
  AvgDialog_23884_Content_2 = {
    Text = "Lentiniën Innenstadt\nEinen Monat später"
  },
  AvgDialog_23884_Content_20 = {
    Text = "Frau Sorel! <Big:Frau Sorel—!!>"
  },
  AvgDialog_23884_Content_21 = {
    Text = "Oh mein Gott, sie hat mich gerade angesehen, sie hat mich angesehen!"
  },
  AvgDialog_23884_Content_22 = {
    Text = "Du und Ramona werdet von der lärmenden Menge zur Seite gedrängt und könnt Sorel nur aus der Ferne beobachten."
  },
  AvgDialog_23884_Content_23 = {
    Text = "Verträge zerreißen, Rivalen ausschalten und ihren nutzlosen Vater vor die Tür setzen — in nur einem Monat hat sie ihre Ziele übertroffen."
  },
  AvgDialog_23884_Content_24 = {
    Text = "Nicht länger von anderen kontrolliert oder manipuliert."
  },
  AvgDialog_23884_Content_25 = {
    Text = "Sorel hielt den Kopf hoch erhoben und schritt anmutig durch Blumen und Applaus, ihrer Zukunft entgegen."
  },
  AvgDialog_23884_Content_26 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23884_Content_27 = {
    Text = "Mir fiel plötzlich auf, dass dies das erste Mal ist, dass ich sie außerhalb des Geheimgangs sehe."
  },
  AvgDialog_23884_Content_28 = {
    Text = "Am Tag, als Sorel erfolgreich erweckt wurde, wurde allen befohlen, nicht zu Besuch zu kommen."
  },
  AvgDialog_23884_Content_29 = {
    Text = "Du weißt nur, dass sie danach eine einwöchige harte Verhandlung mit der sogenannten <Yellow:oberen Führungsebene> führte und beide Seiten schließlich ein geheimes Abkommen unterzeichneten."
  },
  AvgDialog_23884_Content_3 = {
    Text = "<BigShake:Eilmeldung!!>"
  },
  AvgDialog_23884_Content_30 = {
    Text = "Was den Inhalt des Abkommens betrifft, hast du kein Recht, danach zu fragen."
  },
  AvgDialog_23884_Content_31 = {
    Text = "Du wirkst etwas abgelenkt. Beschäftigt dich etwas?"
  },
  AvgDialog_23884_Content_32 = {
    Text = "...Ich hätte sie in diesem Zustand fast nicht wiedererkannt."
  },
  AvgDialog_23884_Content_33 = {
    Text = "Sorel im Geheimgang wirkt viel lebendiger. Sie könnte dich impulsiv umarmen oder dir teuren Champagner anbieten..."
  },
  AvgDialog_23884_Content_34 = {
    Text = "Wird dich ohne zu zögern gemeinsam mit in den Abgrund hinabziehen."
  },
  AvgDialog_23884_Content_35 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23884_Content_36 = {
    Text = [[
Sie erinnert sich vielleicht an gar nichts.
Ich vermute sogar, dass es Teil ihres Plans war, mich zu benutzen, um N loszuwerden...]]
  },
  AvgDialog_23884_Content_37 = {
    Text = "Etwas Kaltes streifte plötzlich für einen Augenblick meine Wange."
  },
  AvgDialog_23884_Content_38 = {
    Text = "<Shake:Zisch—! Was ist los...>"
  },
  AvgDialog_23884_Content_39 = {
    Text = "Wie kann das sein? Es sind erst ein paar Tage vergangen, und du hast mich schon vergessen!"
  },
  AvgDialog_23884_Content_4 = {
    Text = "Du wirst es nicht glauben! Mrs. Sorel, die kürzlich zu Tode gefallen ist, ist wieder zum Leben erwacht!"
  },
  AvgDialog_23884_Content_40 = {
    Text = "Miss Karen ..."
  },
  AvgDialog_23884_Content_41 = {
    Text = "Karen reichte dir lächelnd eine mit einem Band geschmückte Flasche Champagner."
  },
  AvgDialog_23884_Content_42 = {
    Text = "Meine Herrin ist sehr dankbar für deine Hilfe im Geheimgang und hat Karen eigens beauftragt, dir ein großartiges Geschenk zu überbringen."
  },
  AvgDialog_23884_Content_43 = {
    Text = "Du nimmst den eiskalten Champagner entgegen und betrachtest ihn neugierig."
  },
  AvgDialog_23884_Content_44 = {
    Text = "Es ist der Champagner, den du im Geheimgang getrunken hast. Im Sonnenlicht schimmerte die goldgrüne Flasche schwach in goldenem Glanz – ein deutliches Zeichen für ihren hohen Preis."
  },
  AvgDialog_23884_Content_45 = {
    Text = "Hüte ihn gut, diese Flasche Wein ist äußerst kostbar!"
  },
  AvgDialog_23884_Content_46 = {
    Text = "<SmallShake:Wenn ich du wäre, würde ich sie definitiv verkaufen und ein sorgenfreies Leben führen!>"
  },
  AvgDialog_23884_Content_47 = {
    Text = "Sie hat sich also an alles erinnert..."
  },
  AvgDialog_23884_Content_48 = {
    Text = "Überrascht hebst du den Kopf."
  },
  AvgDialog_23884_Content_5 = {
    Text = "Ich habe gehört, dass sie einen Attentatsversuch ihres Vaters @2·Lambert überlebt hat und fälschlicherweise von einem Scharlatan für tot erklärt wurde!"
  },
  AvgDialog_23884_Content_50 = {
    Text = "Sorel kommt dir immer näher. In dem Moment, als ihr aneinander vorbeigeht, schenkt sie dir ein leichtes Lächeln."
  },
  AvgDialog_23884_Content_51 = {
    Text = "Ein reiner Blumenduft erreicht meine Nasenspitze, wie eine frisch erblühte Rose, die sich in der Morgensonne badet, völlig frei von jeder Spur des Verfalls."
  },
  AvgDialog_23884_Content_52 = {
    Text = "Rote Blütenblätter tanzten im Sonnenlicht, goldenes Haar wogte wie das Meer und schimmerte im Glanz der Sonne."
  },
  AvgDialog_23884_Content_53 = {
    Text = "In dem Moment, als sie dich ansah, zeigte sich ein leichter Riss in ihrem makellosen Make-up, der dich näher zog."
  },
  AvgDialog_23884_Content_54 = {
    Text = "Inmitten der geschäftigen Menge scheinst du sie sagen zu hören—"
  },
  AvgDialog_23884_Content_55 = {
    Text = "Du schuldest mir immer noch einen Drink, Hüter."
  },
  AvgDialog_23884_Content_58 = {
    Text = "Lentiniën Outskirts\nLamberts Residenz"
  },
  AvgDialog_23884_Content_59 = {
    Text = "Der düstere alte Mann saß in der verlassenen Halle und beobachtete schweigend den ungebetenen Gast, der die Tür aufgestoßen hatte."
  },
  AvgDialog_23884_Content_6 = {
    Text = "Nachdem sie fast einen Monat lang im Sarg begraben war, hörte der Förster Jacob in einer dunklen und stürmischen Nacht plötzlich ein Klopfen aus dem Inneren des Sarges..."
  },
  AvgDialog_23884_Content_60 = {
    Text = "Guten Tag, Vater."
  },
  AvgDialog_23884_Content_61 = {
    Text = "Was für ein seltener Besuch, Sorel. Ich habe längst den Überblick verloren, wie oft du mich abgewiesen hast, seit ich bankrott ging."
  },
  AvgDialog_23884_Content_62 = {
    Text = "Ich dachte, du hättest längst vergessen, dass du überhaupt einen Vater hast."
  },
  AvgDialog_23884_Content_63 = {
    Text = "Ist das die Art, wie du deinen Retter behandelst? Es hat mich große Mühe gekostet, dich aus dem Gefängnis zu holen."
  },
  AvgDialog_23884_Content_64 = {
    Text = "Du bist schlau genug, ein Testament zu benutzen, um mich anzulocken, aber glaubst du wirklich, ich würde dir abnehmen, dass du mich nur gerettet hast, um mein Leben zu retten? Hust, hust..."
  },
  AvgDialog_23884_Content_65 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_23884_Content_66 = {
    Text = "Ich habe gehört, als die Polizei dich abführte, hast du dein „Verbrechen“ ohne jeglichen Widerspruch akzeptiert.\nWarum?"
  },
  AvgDialog_23884_Content_67 = {
    Text = "Von dem Moment an, als du vom Gebäude fielst, wusste ich es. Ich war dir nicht gewachsen."
  },
  AvgDialog_23884_Content_68 = {
    Text = "Meine Tochter ist ein Teufel, der gnadenlos sich selbst töten und den eigenen Vater an den Galgen bringen kann."
  },
  AvgDialog_23884_Content_69 = {
    Text = "Weil ich einen ausgezeichneten Lehrmeister habe, mein liebster Vater."
  },
  AvgDialog_23884_Content_7 = {
    Text = "Das zweite Erwachen als Auferstehung zu bezeichnen, schöne Wendung."
  },
  AvgDialog_23884_Content_70 = {
    Text = "Der alte Mann lachte herzlich und warf dann einen Blick auf das Porträt an der Wand."
  },
  AvgDialog_23884_Content_71 = {
    Text = "Geh, Sorel."
  },
  AvgDialog_23884_Content_72 = {
    Text = "Wenn deine Mutter Rebecca noch am Leben wäre, würde sie uns nicht in diesem Zustand sehen wollen."
  },
  AvgDialog_23884_Content_73 = {
    Text = "Sorel schritt über die Blütenblätter und das gefallene Laub zu ihrem Vater."
  },
  AvgDialog_23884_Content_74 = {
    Text = "Sie kauerte sich nieder und legte sanft ihren Kopf auf die zitternden, welken Knie des alten Mannes."
  },
  AvgDialog_23884_Content_75 = {
    Text = "Weich mir nicht aus, Vater. Dies sollte unser letztes Treffen sein."
  },
  AvgDialog_23884_Content_76 = {
    Text = "Erinnerst du dich, wie ich als Kind so gerne meinen Kopf auf dein Knie gelegt habe..."
  },
  AvgDialog_23884_Content_77 = {
    Text = "Lambert schwieg, sein verfallender Körper zitterte einen Moment lang leicht."
  },
  AvgDialog_23884_Content_78 = {
    Text = "Wir sind von der gleichen Sorte. Ein unaufhörlicher Ehrgeiz fließt durch unsere Adern und verwandelt uns in Dämonen des Ruhms und der Macht."
  },
  AvgDialog_23884_Content_79 = {
    Text = "Ich kann dich niemals hassen, so wie ich mich selbst niemals hassen kann."
  },
  AvgDialog_23884_Content_8 = {
    Text = "Jetzt ist Sorels Beliebtheit beim Volk in die Höhe geschossen. Ich habe gehört, dass im Westbezirk bereits sechs oder sieben Theaterstücke dazu vorbereitet werden."
  },
  AvgDialog_23884_Content_80 = {
    Text = "Lambert blickte auf das Porträt seiner verstorbenen Frau, Tränen strömten ihm übers Gesicht."
  },
  AvgDialog_23884_Content_81 = {
    Text = [[
Ist das so... Aber wenn ich das Gesicht deiner Mutter betrachte, empfinde ich Kummer.
Ich bin anders als du, Sorel.]]
  },
  AvgDialog_23884_Content_82 = {
    Text = "Ich will nicht so werden wie du... Ich will nicht..."
  },
  AvgDialog_23884_Content_83 = {
    Text = "Ich verstehe, ich sehe es klar... Dich wiederzubeleben und dann die Auflösung auf dich übergreifen zu lassen, das war alles Teil von Ns Plan, nicht wahr?"
  },
  AvgDialog_23884_Content_84 = {
    Text = "Der Zweck ist, mich zu überwachen und mir Ekel einzuflößen. Sein Geschmack ist nach wie vor abscheulich."
  },
  AvgDialog_23884_Content_85 = {
    Text = "Woher wisst Ihr das?! Wie könnt Ihr es wagen, den Namen dieser ehrwürdigen Person zu erwähnen..."
  },
  AvgDialog_23884_Content_86 = {
    Text = "Welch eine Ironie. Zuerst wurden wir, Vater und Tochter, zu Sklaven der Macht, und nun sind wir beide Seine Sklaven geworden."
  },
  AvgDialog_23884_Content_87 = {
    Text = "Ist Brudermord und Kannibalismus nicht Sein liebstes Schauspiel?"
  },
  AvgDialog_23884_Content_88 = {
    Text = "Vater, mein Vertrag mit Ihm endete vor langer Zeit. Wir sind jetzt beide frei."
  },
  AvgDialog_23884_Content_89 = {
    Text = "Ich habe etwas Geld beiseitegelegt und dir eine gefälschte Identität besorgt. Jetzt kannst du hingehen, wohin du willst."
  },
  AvgDialog_23884_Content_9 = {
    Text = "Ja. Sie wurde zu einer lebenden Legende."
  },
  AvgDialog_23884_Content_90 = {
    Text = "Solange du in diesem Leben nie wieder vor mir auftauchst, kannst du tun und lassen, was du willst."
  },
  AvgDialog_23884_Content_91 = {
    Text = "Heh... Verspottest du mich?\nIn diesem erbärmlichen Zustand kann ich nirgendwohin..."
  },
  AvgDialog_23884_Content_92 = {
    Text = "Ich werde dir den besten Arzt besorgen.\nDu bist mein Vater. Solange du es wünschst, kannst du überleben bis zu dem Tag, an dem die Welt ihrem Untergang begegnet."
  },
  AvgDialog_23884_Content_93 = {
    Text = "Sorel stieß einen langen Atemzug aus, während sie sprach."
  },
  AvgDialog_23884_Content_94 = {
    Text = "Ich habe lange genug auf diesen Tag gewartet. Nun habe ich endlich genug in der Hand, um das alles selbst zu beenden..."
  },
  AvgDialog_23884_Content_95 = {
    Text = "Lebewohl, mein Vater."
  },
  AvgDialog_23884_Content_96 = {
    Text = "<Red:Hehe.>"
  },
  AvgDialog_23884_Content_97 = {
    Text = "Ein kurzes, vertrautes Kichern durchdringt abrupt deine Ohren."
  },
  AvgDialog_23884_Content_98 = {Text = "?!"},
  AvgDialog_23884_Content_99 = {
    Text = "Leb wohl? Sorel, meine naive Sorel..."
  },
  AvgDialog_24075_Content_1 = {Text = "Hmm!!"},
  AvgDialog_24075_Content_10 = {
    Text = "Sogar bereit, die eigene Tochter zu töten..."
  },
  AvgDialog_24075_Content_11 = {
    Text = "Lambert nahm langsam das Weinglas vom Tisch und nippte an dem Rotwein darin."
  },
  AvgDialog_24075_Content_12 = {
    Text = "Heh... Für euch kann ich dieses Getränk natürlich nicht mehr schmecken."
  },
  AvgDialog_24075_Content_13 = {
    Text = "Aber wisst ihr was? Wenn ich ihn schlucke, sagen mir meine Erinnerungen und meine Vorstellungskraft immer wieder..."
  },
  AvgDialog_24075_Content_14 = {
    Text = "Dies ist ein Montachet-Wein aus dem Jahr @2. Anfangs sollte er ein Lakritzaroma haben, und nach zwei Stunden bemerkt man einen intensiven Rosenduft..."
  },
  AvgDialog_24075_Content_15 = {
    Text = "Lambert nahm einen tiefen Atemzug des Rotweins in seinem Glas, und ein Ausdruck tiefer Zufriedenheit breitete sich auf seinem Gesicht aus."
  },
  AvgDialog_24075_Content_16 = {
    Text = "Es ist nur Einbildung. Früher oder später müssen Sie sich der Realität stellen, Herr Lambert."
  },
  AvgDialog_24075_Content_17 = {
    Text = "Ja, Vorstellungskraft! Sie ist eine mächtige Kraft."
  },
  AvgDialog_24075_Content_18 = {
    Text = "Die Vorstellung von Geld, Macht und Begierde... Sie kann den reinsten Mönch verderben und den niedrigsten Dieb in einen Propheten verwandeln."
  },
  AvgDialog_24075_Content_19 = {
    Text = "Und meine liebste Tochter? Sie wagte es, mir meinen letzten Funken Vorstellungskraft zu nehmen."
  },
  AvgDialog_24075_Content_2 = {
    Text = "Herr Lambert, Sie haben keinen Ausweg. Bitte kooperieren Sie mit unserer Arbeit."
  },
  AvgDialog_24075_Content_20 = {
    Text = "Das Einzige, was mir noch von Wert geblieben ist, ist diese Flasche Wein. Das ist das Grausamste auf der Welt..."
  },
  AvgDialog_24075_Content_21 = {
    Text = "So wurde ich gezwungen, dieses abscheuliche Verbrechen zu begehen."
  },
  AvgDialog_24075_Content_22 = {
    Text = "Jetzt können Sie mich abführen und mir allein alle Verbrechen anhängen."
  },
  AvgDialog_24075_Content_23 = {
    Text = [[
Im Gegensatz zu manch anderen bin ich nur ein unbedeutendes Niemand.
In dieser Welt spielt es keine Rolle, ob ich lebe oder sterbe.]]
  },
  AvgDialog_24075_Content_24 = {
    Text = "Zwischen den Zeilen gelesen... Wollen Sie damit etwas andeuten, Herr Lambert?"
  },
  AvgDialog_24075_Content_25 = {
    Text = "Lambert antwortete nicht. Er lächelte schwach und breitete seine Hände der Menge entgegen."
  },
  AvgDialog_24075_Content_26 = {
    Text = "Führen Sie mich ab, Herr Kommissar."
  },
  AvgDialog_24075_Content_27 = {
    Text = "Vor der Villa war es laut, und die Ermittler waren in der Nähe noch beschäftigt."
  },
  AvgDialog_24075_Content_28 = {
    Text = "Beim Blick zurück auf die Villa hüllte ihr verfallenes Äußeres sie in ein immerwährendes Dunkel, wie ein Schiffswrack, versunken tief unter dem Meer."
  },
  AvgDialog_24075_Content_29 = {
    Text = "Ramona nahm vorsichtig die Dienstmarke von ihrer Brust ab und öffnete eine Verbindung zu Dexter."
  },
  AvgDialog_24075_Content_3 = {
    Text = "Lambert stützte sich auf seinen schlanken Buchenholzstock und brach plötzlich in Gelächter aus."
  },
  AvgDialog_24075_Content_30 = {
    Text = "Das Ziel wurde gefasst und hat das Verbrechen gestanden."
  },
  AvgDialog_24075_Content_31 = {
    Text = "Gut gemacht, genau das, was ich von meiner Tochter erwarte."
  },
  AvgDialog_24075_Content_32 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_24075_Content_33 = {
    Text = "Und sie? Nachdem sie erfolgreich geworden war, hat sie es nicht nur versäumt, es mir zurückzuzahlen, sondern wollte sich auch noch von mir distanzieren."
  },
  AvgDialog_24075_Content_34 = {
    Text = "Vergelten. Ramona dachte still über dieses Wort nach."
  },
  AvgDialog_24075_Content_35 = {
    Text = "Vater, was soll ich für dich tun?"
  },
  AvgDialog_24075_Content_36 = {
    Text = "Was? Ist das ein neuer Code, den du und %player% euch ausgedacht habt? Ich verstehe nicht, was du meinst."
  },
  AvgDialog_24075_Content_37 = {
    Text = "Hmm... Zum Beispiel dir helfen, viel Geld zu verdienen, oder Ermittlungen oder Forschungen für dich durchführen..."
  },
  AvgDialog_24075_Content_38 = {
    Text = "Moment... Moment! Ich würde es nicht wagen, so eine Bitte zu äußern. Bleib einfach am Leben, das ist alles, was zählt."
  },
  AvgDialog_24075_Content_39 = {
    Text = "Begleitet von einem sanften elektrischen Summen wurde Dexters Geplapper etwas undeutlich, was Ramona zum Schmunzeln brachte."
  },
  AvgDialog_24075_Content_4 = {
    Text = "Was ist daran so lustig?"
  },
  AvgDialog_24075_Content_40 = {
    Text = "Vater, danke."
  },
  AvgDialog_24075_Content_41 = {
    Text = "Du benimmst dich heute wirklich seltsam, plötzlich so förmlich. Wofür bedankst du dich denn?"
  },
  AvgDialog_24075_Content_42 = {
    Text = "Ramona senkte den Kopf, ihre Schuhspitzen rieben leicht über das Laub unter ihren Füßen. Auch diese Schuhe hatte Dexter ihr gekauft."
  },
  AvgDialog_24075_Content_43 = {
    Text = "Kleines Kleid, Spieluhr, Rosenhals-Bockkäfer... Dexter kaufte ihr viele Dinge. Aber er verlangte nie etwas dafür."
  },
  AvgDialog_24075_Content_44 = {
    Text = "Für alles."
  },
  AvgDialog_24075_Content_5 = {
    Text = "Hab keine Angst, kleines Mädchen... Ich lache nur über mich selbst."
  },
  AvgDialog_24075_Content_6 = {
    Text = "Schwarzer A-Schleim fließt aus den Augenhöhlen, wie schwarze Tränen."
  },
  AvgDialog_24075_Content_7 = {
    Text = "Symptome im Spätstadium der Auflösung... \nWenn ich mich nicht irre, haben sich Ihre inneren Organe bereits in A-Schleim verwandelt."
  },
  AvgDialog_24075_Content_8 = {
    Text = "Sie können die Rosen nicht riechen, die Wärme der Sonne nicht spüren und den Wein nicht schmecken."
  },
  AvgDialog_24075_Content_9 = {
    Text = "Für jemanden wie Sie haben weltlicher Reichtum und Macht längst ihre Bedeutung verloren. Warum streben Sie noch immer danach?"
  },
  AvgDialog_24078_Content_1 = {
    Text = "Der faulige Gestank dringt allmählich in deine Nase"
  },
  AvgDialog_24078_Content_10 = {Text = "Ugh..."},
  AvgDialog_24078_Content_11 = {
    Text = "Ermittler von der Mythag Universität, plus der Erwachende, der die Macht von Lemuria gestohlen hat... Ist das alles, was ihr habt?"
  },
  AvgDialog_24078_Content_12 = {
    Text = "Tulu sprang vor dir, während Ramona, durchnässt von kaltem Schweiß, neben dir kniete und versuchte, Goliaths massive Klinge herauszuziehen."
  },
  AvgDialog_24078_Content_13 = {
    Text = "Tulu, bring sie weg."
  },
  AvgDialog_24078_Content_14 = {
    Text = "Was für einen Unsinn quasselst du?!"
  },
  AvgDialog_24078_Content_15 = {
    Text = "Ramona zog kräftiger an Goliaths Waffe, das ​​Klingen schnitt durch ihren Handschuh, und dunkles rotes Blut durchtränkte schnell ihren Ärmel."
  },
  AvgDialog_24078_Content_16 = {
    Text = "Es wird mir gut gehen. Miryam will jemanden behalten, um den Gott zu füttern, der geboren werden soll, oder? Schütze Celeste und Murphy, und stoppe das Ritual... Ich werde einen Weg finden, um herauszukommen."
  },
  AvgDialog_24078_Content_17 = {
    Text = "Ihr Geist wird leer, während Sie mechanisch Gründe finden, an die Sie selbst nicht glauben können."
  },
  AvgDialog_24078_Content_18 = {Text = "Du..."},
  AvgDialog_24078_Content_19 = {
    Text = "Schütze sie und bring sie weg!"
  },
  AvgDialog_24078_Content_2 = {
    Text = "Seefahrer reagieren auf den Aufruf des Anführers und tauchen aus den gesamten Räumen auf.\nDie Jagd auf dich leitet der Riese, den du am meisten fürchtest"
  },
  AvgDialog_24078_Content_20 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_24078_Content_21 = {
    Text = "Tulu hört auf zu streiten und wirft dir einen letzten Blick zu, anscheinend um deinen Entschluss zu bestätigen."
  },
  AvgDialog_24078_Content_22 = {
    Text = "Tulu! Setze mich sofort ab!"
  },
  AvgDialog_24078_Content_23 = {
    Text = "Zwei mächtige Tentakeln wickelten sich um Ramona und Celeste. Im Handumdrehen hatte Tulu sie gesichert und war tief in den Flur gerauscht."
  },
  AvgDialog_24078_Content_24 = {
    Text = "Goliath lachte manisch, als er seine Waffe zog, sich vor dir hockte und dir am Kinn packte, um dich dazu zu bringen, ihn anzusehen."
  },
  AvgDialog_24078_Content_25 = {
    Text = "Ich habe dir gesagt: Lass nicht zu, dass ein paar Handlanger dich besiegen, bevor ich genug von der Show habe."
  },
  AvgDialog_24078_Content_26 = {
    Text = "Sein Ton ist halb verspottend, halb ernst, was es unmöglich macht, seine wahren Absichten zu erkennen."
  },
  AvgDialog_24078_Content_27 = {
    Text = "Aber du bist einer, der sich traut.\nLeider hat Miryam dieses Mal ausdrücklich verlangt, dass jemand zurückgebracht wird, um zu berichten."
  },
  AvgDialog_24078_Content_28 = {
    Text = "Ist es nur ein Scherz? Oder hat Goliath wirklich hinterhältige Motive gegenüber Miryam..."
  },
  AvgDialog_24078_Content_3 = {
    Text = "Was für ein hartnäckiger Feind...!"
  },
  AvgDialog_24078_Content_4 = {
    Text = "Komm nicht mit ihm in Konflikt! Tulu, decke unseren Rückzug!"
  },
  AvgDialog_24078_Content_5 = {
    Text = "Du ziehst Ramona aus dem Kampf, verzweifelt, um nach draußen aus der Hütte zu rennen."
  },
  AvgDialog_24078_Content_6 = {
    Text = "Goliaths Kampfstil blieb so direkt wie eh und je. Er lächelte lässig und schleuderte seine riesige Klinge in die Richtung deiner Flucht."
  },
  AvgDialog_24078_Content_7 = {Text = "Vorsicht!"},
  AvgDialog_24078_Content_8 = {
    Text = "Du schubst Ramona nach vorne, doch die massive Klinge durchbohrt deine Wade und nagelt dich zu Boden. Der an deiner Brust befestigte Kommunikator fällt ab."
  },
  AvgDialog_24078_Content_9 = {
    Text = "Die unerträglichen Schmerzen lassen Ihre Sicht weiß werden, und ein Summen erfüllt Ihren Kopf, das Ramonas Schreie übertönt."
  },
  AvgDialog_24079_Content_1 = {
    Text = "Sternenjagd"
  },
  AvgDialog_24079_Content_10 = {
    Text = "Wann immer Ramona einen Schritt machte, selbst wenn sie nur ihre Haltung zum Lösen von Schmerzen änderte, warf Caecus einen misstrauischen Blick auf sie, die Waffe gezielt."
  },
  AvgDialog_24079_Content_11 = {
    Text = "Caecus, du..."
  },
  AvgDialog_24079_Content_12 = {
    Text = "Benehm dich!\nVersuche nichts Ungehöriges unter der Aufsicht von Lady Miryam. Ich werde ein Auge auf dich haben."
  },
  AvgDialog_24079_Content_13 = {
    Text = "<Gray:... Hat sich vollständig geweigert, mit mir zu kommunizieren. Ist es aus Angst vor Miryam?>"
  },
  AvgDialog_24079_Content_14 = {
    Text = "<Gray:Verknüpfung als Erwacher zu einem anderen Erwacher, wer genau ist diese Miryam...>"
  },
  AvgDialog_24079_Content_15 = {
    Text = "Ramona atmete tief ein, passte ihren Atemrhythmus an, um den schwachen Schmerz in ihrem Knöchel zu ignorieren. Gleichzeitig beobachtete sie sorgfältig die Situation im Kraftwerk, aus Angst, dass sie eine Gelegenheit verpassen könnte."
  },
  AvgDialog_24079_Content_16 = {
    Text = "Der Klang des Schlosses, das sich dreht, ließ jeden Muskel im Körper anspannen."
  },
  AvgDialog_24079_Content_17 = {
    Text = "Husten, Husten... ein Hauch von alten verrottenden Atem."
  },
  AvgDialog_24079_Content_18 = {
    Text = "Die elegante und statuarische Figur der Frau stand in starkem Kontrast zu den Seefahrern, ihr Gesicht voller Verachtung. Sie schien eindeutig nicht bereit zu sein, an der Seite des Seefahrerordens zu gehen."
  },
  AvgDialog_24079_Content_19 = {
    Text = "Geh nicht so schnell, gib mir eine Hand! Ich halte hier einen Wachenden!"
  },
  AvgDialog_24079_Content_2 = {
    Text = "Äußeres Meer Frachter · Sonaniel\nMacht Raum"
  },
  AvgDialog_24079_Content_20 = {
    Text = "Erwachender?"
  },
  AvgDialog_24079_Content_21 = {
    Text = "Ramona schaute plötzlich zur Tür auf. Ein Mädchen in einem weißen Kleid, das von dem schwarzgekleideten Kultisten zurückgehalten wurde, hob ebenfalls den Kopf und traf Ramonas Blick."
  },
  AvgDialog_24079_Content_22 = {
    Text = "Rein, edel, transzendent, zerbrechlich. Unzählige Adjektive blitzten in Ramonas Kopf auf."
  },
  AvgDialog_24079_Content_23 = {
    Text = "......Menschen"
  },
  AvgDialog_24079_Content_24 = {
    Text = "Der schwarzgekleidete Kultist stieß das erwachende Mädchen an, und sie verbarg schnell ihre leichte Überraschung, kehrte in einen Zustand zurück, der frei von Freude oder Trauer war."
  },
  AvgDialog_24079_Content_25 = {
    Text = "Worüber machst du dir Sorgen? Wenn sie bedrohlicher wäre als du, würde Miryam uns dann beauftragen, sie zurück zur Übergangs Basis zu eskortieren?"
  },
  AvgDialog_24079_Content_26 = {
    Text = [[
Hmph... Ein Nest an einem so maroden, schmutzigen Ort zu bauen.
Diese Barbaren fehlen wirklich an Raffinesse.]]
  },
  AvgDialog_24079_Content_27 = {
    Text = "In Ordnung, in Ordnung, sobald wir die Mission abgeschlossen haben und zu <Yellow:Lantern Outpost> zurückkehren, kannst du sagen, was auch immer du willst.\nVergiss nicht, dass wir uns gerade auf dem Territorium von jemand anderem befinden."
  },
  AvgDialog_24079_Content_28 = {
    Text = "<Gray:Die Straßenlaterne... Sind diese beiden Mitglieder der Tempel Licht Kirche? Sie sind tatsächlich mit den Seefahrern verbunden.>"
  },
  AvgDialog_24079_Content_29 = {
    Text = "Die weibliche Kultistin schnaubte, packte das Seil, das den Erwachten band, und schleifte sie grob vor Caecus."
  },
  AvgDialog_24079_Content_3 = {
    Text = "Haufen von Kohlenasche bildeten Berge, Seefahrer mit feuchter Haut liefen hin und her im Maschinenraum, ihre Schwanzflossen zogen schwarze Streifen wie Schlamm hinter sich her."
  },
  AvgDialog_24079_Content_30 = {
    Text = "Miryam bat mich, dir zu sagen: Pass auf die beiden auf."
  },
  AvgDialog_24079_Content_31 = {
    Text = "Dem Unhöflichkeit der Tempellichtergläubigen ins Gesicht zu sehen, bleibt Caecus besonders ruhig. Er zieht das Erwachen-Mädchen an Ramonas Seite und wird zu einem stillen Soldaten."
  },
  AvgDialog_24079_Content_32 = {
    Text = "Zwei Sonderlinge, die tatsächlich versuchen, den \"Aufgelösten Gottkönig\" wiederzubeleben? Absurde."
  },
  AvgDialog_24079_Content_33 = {
    Text = "Ich verstehe wirklich nicht, warum <Blue:Master Lantern> mit diesen Verrückten zusammenarbeiten würde. Du hast vor 25 Jahren bereits eine Chance vergeudet."
  },
  AvgDialog_24079_Content_34 = {
    Text = "Sag weniger!"
  },
  AvgDialog_24079_Content_35 = {
    Text = "Yo, hier ist es ganz lebhaft."
  },
  AvgDialog_24079_Content_36 = {
    Text = "Eine tiefe, raue Stimme ertönte und verstummte sofort die beiden Gläubigen des Tempellichts."
  },
  AvgDialog_24079_Content_37 = {
    Text = "Lord Goliath."
  },
  AvgDialog_24079_Content_38 = {
    Text = "Caecus neigte respektvoll sein stolzes Haupt vor dem Goliath, sein Ton voller Ehrfurcht.\nDer Letztere hingegen schenkte seiner Loyalität keine Beachtung und stellte stattdessen die Gläubigen des Tempellichts mit großem Interesse in Frage."
  },
  AvgDialog_24079_Content_39 = {
    Text = "Warum aufhören? Ich habe nicht genug gehört. Erzähl mir mehr über Lemuria."
  },
  AvgDialog_24079_Content_4 = {
    Text = "<Gray:Es gibt nur einen Eingang und Ausgang im Kraftwerk. Vom meinem Standort aus sollte ich nur 7 Sekunden brauchen, aber...>"
  },
  AvgDialog_24079_Content_40 = {
    Text = "Er gab den Temple Light-Gläubigen keine Chance zu diskutieren, dann wandte er seinen Blick direkt zur Tür."
  },
  AvgDialog_24079_Content_41 = {
    Text = "Niemand hat dir gewagt, ihre wahren Gedanken über das \"Königreich Gottes\" zu erzählen, oder, Miryam?"
  },
  AvgDialog_24079_Content_42 = {
    Text = "Miryams Gestalt verschmilzt mit dem Schatten an der Tür. Niemand kann ihren Gesichtsausdruck sehen, doch eine schaurig kalte Aura strömt von ihr aus."
  },
  AvgDialog_24079_Content_43 = {
    Text = "<Gray:Wann war sie dort?! Ich habe nicht einmal bemerkt, wie sie sich näherte...>"
  },
  AvgDialog_24079_Content_44 = {
    Text = "Kalter Wind schlich vorbei und nahm die Farbe vom Gesicht der Tempellichtgläubigen—ist sie mit dem Goliath zurückgekehrt? Wie viel hat sie gehört?"
  },
  AvgDialog_24079_Content_45 = {
    Text = "Weder Ramona noch die beiden Tempellicht-Gläubigen erwarteten, dass Miryam ruhig und gefasst bleibt, ohne auch nur einen Hauch von Unmut zu zeigen."
  },
  AvgDialog_24079_Content_46 = {
    Text = "Sie sah auf alle herab, als ob das Schauspiel vor ihr nur ein belangloses Vogelgezwitscher wäre."
  },
  AvgDialog_24079_Content_47 = {
    Text = "Goliath, wie läuft die Aufgabe, die ich dir zugewiesen habe?"
  },
  AvgDialog_24079_Content_48 = {
    Text = "Ha... Diese kleinen Mäuse aus Mythag sind geschickt im Graben überall. Ich habe dir schon vorher gesagt, wenn wir dieses Schiff nicht zerlegen können, werde ich niemanden finden können. Außerdem, haben wir nicht immer noch einen Geisel?"
  },
  AvgDialog_24079_Content_49 = {
    Text = "Goliath sprach, während er sein riesiges Schwert schwang und es auf Ramona richtete."
  },
  AvgDialog_24079_Content_5 = {
    Text = "Sie beugte sich herunter, um ihren Knöchel zu reiben. Obwohl sie das ausgekugelte Gelenk schnell behandelt hatte, war die Schwellung unvermeidlich. Selbst eine leichte Berührung verursachte brennende Schmerzen."
  },
  AvgDialog_24079_Content_50 = {
    Text = "Halte diese Dame einfach fest, und ich bin sicher, ihr Partner wird nach ihr suchen."
  },
  AvgDialog_24079_Content_51 = {
    Text = "Wenn wir davon sprechen, warum hast du Eltons Erwacher gefesselt? Wo ist Elton?"
  },
  AvgDialog_24079_Content_52 = {
    Text = "Mit dem bevorstehenden Ritual ist der Zustand der \"Muttergottheit\" besonders wichtig. Obwohl die Helfer mit dem Schlaf-Rune vertraut sind, wünsche ich mir, falls möglich, nicht zu sehen, dass die Muttergottheit leidet"
  },
  AvgDialog_24079_Content_53 = {
    Text = "Solange Celeste unter unserer Kontrolle ist, wird Elton der Muttergöttin gehorsam übergeben, um zu verhindern, dass die Sonaniel außer Kontrolle gerät..."
  },
  AvgDialog_24079_Content_54 = {
    Text = "<Gray:Es sieht so aus, als wäre dieser Erwacher derjenige, der das Geisterschiff Sonaniel kontrolliert.\nDieser Bereich ist auch ihre Schöpfung.>"
  },
  AvgDialog_24079_Content_55 = {
    Text = "<Gray:Warte... Vielleicht gibt es einen Weg.>"
  },
  AvgDialog_24079_Content_56 = {
    Text = "Während alle Aufmerksamkeit auf Miryam gerichtet war, berührte Ramona dezent die Hand des jungen Erweckers. Letzterer sah zu ihr auf und zeigte einen Ausdruck, der jeglicher Emotion entbehrte."
  },
  AvgDialog_24079_Content_57 = {
    Text = "<Small:Celeste... ich habe vielleicht einen Weg für uns zur Flucht.>"
  },
  AvgDialog_24079_Content_58 = {
    Text = "Der Nebel in Celestes Augen klärte sich ein wenig und offenbarte einen Hauch von Erstaunen."
  },
  AvgDialog_24079_Content_59 = {
    Text = "<Small:Du bist der Meister des Bereichs. Wenn du den Bereich für eine Weile verschwinden lassen und Verwirrung unter den Seefahrern stiften kannst...>"
  },
  AvgDialog_24079_Content_6 = {
    Text = "<Gray:Der Schmerzindex liegt bei etwa Level 4. Basierend auf meiner Einschätzung der motorischen Funktionsbeeinträchtigung in diesem Semester wird die Geschwindigkeit um 20 % sinken...>"
  },
  AvgDialog_24079_Content_60 = {
    Text = "Celeste antwortete nicht, blinzelte nur. Ramona konnte nicht sagen, ob sie es verstand, aber sie wusste, dass ihre Handflächen unter den Handschuhen schwitzten."
  },
  AvgDialog_24079_Content_61 = {
    Text = "<Small:Ist das... dein Wunsch?>"
  },
  AvgDialog_24079_Content_62 = {
    Text = "Ramona war verblüfft, aber ihr Körper reagierte, bevor ihr Verstand - sie nickte instinktiv."
  },
  AvgDialog_24079_Content_63 = {
    Text = "Celeste hielt den Kompass hoch, das fließende Licht wirbelte um ihren Rock, bald verschwand es ohne eine Spur."
  },
  AvgDialog_24079_Content_64 = {
    Text = "In der Zwischenzeit brachte das echte Beiyang-Meer feuchte, kalte Luft. Dazu kamen die lauten Rufe vom Deck."
  },
  AvgDialog_24079_Content_65 = {
    Text = "Mond! Mond!"
  },
  AvgDialog_24079_Content_66 = {
    Text = "In diesem Moment wurde der Kraftraum in Dunkelheit gehüllt. Eine unbekannte und tiefgreifende Stille breitete sich aus und ertränkte alles Sichtbare, aber Ramonens Adrenalin raste."
  },
  AvgDialog_24079_Content_67 = {
    Text = "<Small:Jetzt ist die Zeit!>"
  },
  AvgDialog_24079_Content_68 = {
    Text = "Ramona griff die Hand des Erwachten und konzentrierte all ihre Macht auf ihren Unterkörper. Sie schob den Seefahrer zur Seite und rannte aus dem Kraftraum."
  },
  AvgDialog_24079_Content_7 = {
    Text = "<Gray:Nicht genug Zeit. Der Kraftraum ist jetzt ihre Basis, mit zu vielen Feinden. Die Seefahrer werden mich abfangen, bevor ich die Tür erreiche.>"
  },
  AvgDialog_24079_Content_8 = {
    Text = "<Gray:Außerdem... dieser Typ beobachtet uns zu genau.>"
  },
  AvgDialog_24079_Content_9 = {
    Text = "Die Seefahrer bereiten sich auf das \"Ritual\" vor, während der Erwacherjunge treu seine Pflicht erfüllt, still und unerschütterlich, während er sie bewacht."
  },
  AvgDialog_24080_Content_1 = {
    Text = "Du schüttelst den Kopf und legst einen Finger auf deine Lippen, um ihr zu signalisieren, still zu sein. Doch als dein Blick die Person im Schatten streift, kannst du ein Keuchen kaum unterdrücken"
  },
  AvgDialog_24080_Content_2 = {
    Text = "<Small: Sie ist Celeste, ein Erwecker...>"
  },
  AvgDialog_24080_Content_3 = {
    Text = "Du hast sie mehrfach auf dem Sonaniel gesehen, diese vertraute und zugleich seltsame Gestalt stellte sich als Celeste heraus, die den Bereich beherrscht"
  },
  AvgDialog_24080_Content_4 = {
    Text = "Die Hauptfigur, die unter Miryams Kontrolle hätte sein sollen, ist mit Ramona entkommen - unerwartet, aber erwartet."
  },
  AvgDialog_24080_Content_5 = {
    Text = "Nachdem alles gesagt und getan ist, war dein Partner nie der Typ, der untätig zusieht."
  },
  AvgDialog_24080_Content_6 = {
    Text = "<Small: ...W-Warte? Das ist der Erwecker Tulu aus Archiv Nr. 6291?!>"
  },
  AvgDialog_24080_Content_7 = {
    Text = "<Small: Lass uns zuerst mit dem Kapitän und Murphy treffen. Ich werde dir alles nach und nach erklären, wenn die Zeit gekommen ist.>"
  },
  AvgDialog_24081_Content_1 = {
    Text = "Ein weiteres Wunder"
  },
  AvgDialog_24081_Content_10 = {
    Text = "Captain, dein ganzer Körper zittern."
  },
  AvgDialog_24081_Content_11 = {
    Text = "...Das alte Problem. Im Gegensatz zu Mythags besten Studenten bin ich nur eine gewöhnliche Person, die keine starke Geistkraft hat und das <Yellow:Auflösung> nicht sehen kann."
  },
  AvgDialog_24081_Content_12 = {
    Text = "Während des Prozesses der Wiedergeburt eines Erwachenden wird das Bewusstsein unvermeidlich von unbekannten Wesen kontaminiert, was zu ihrem Kontrollverlust führt."
  },
  AvgDialog_24081_Content_13 = {
    Text = "Verknüpfung ist eine Methode, um Chaos zu unterdrücken, aber wenn die Person, die die Verknüpfung durchführt, ein gewöhnlicher Mensch ohne Talent ist..."
  },
  AvgDialog_24081_Content_14 = {
    Text = "Worüber redest du? Was meinst du mit \"außer Kontrolle\"?"
  },
  AvgDialog_24081_Content_15 = {
    Text = "Elton nahm die Zigarettenschachtel, die Murphy aufgehoben hatte, und schmunzelte, als er sah, wie sie heimlich die Tabakblätter in die Ecke trat."
  },
  AvgDialog_24081_Content_16 = {
    Text = "Es bedeutet, dass wenn wir Celeste nicht finden, dieses Schiff die Kontrolle verlieren und sinken könnte."
  },
  AvgDialog_24081_Content_17 = {
    Text = "Murphys Gesicht fiel schnell, seine Lippen zitterten, während er sich mühte, die richtigen Worte zu finden."
  },
  AvgDialog_24081_Content_18 = {
    Text = "Alright, alright, hab keine Angst."
  },
  AvgDialog_24081_Content_19 = {
    Text = "Er gab Murphys steifem Kopf einen beruhigenden Klaps, dann wandte er sich dir und Tulu zu."
  },
  AvgDialog_24081_Content_2 = {Text = "Celeste..."},
  AvgDialog_24081_Content_20 = {
    Text = "Ich kann Celesetes allgemeine Location spüren. Wenn du es geschafft hast, Murphy bis zu mir zu bringen, sollte es auch kein Problem sein, mir zu helfen, Celeste zu finden, oder?"
  },
  AvgDialog_24081_Content_21 = {
    Text = "Tulu, ist das in Ordnung?"
  },
  AvgDialog_24081_Content_22 = {
    Text = "Tulu antwortete nicht. Stattdessen drehte er sich um und öffnete die Tür zum sicheren Haus und gab zu verstehen, dass er die Führung übernehmen würde."
  },
  AvgDialog_24081_Content_3 = {
    Text = "Elton schloss die Augen und ließ einen langen Seufzer los, als würde er Rauchringe blasen, in der Hoffnung, all den Schmutz innen herauszupusten."
  },
  AvgDialog_24081_Content_4 = {
    Text = [[
Als der Seefahrer an Bord des Schiffes ging, war ich nicht mit Celeste.
Nachdem ich so lange im sicheren Haus gewartet habe, seid ihr die Ersten, die mich gefunden haben.]]
  },
  AvgDialog_24081_Content_5 = {
    Text = "W-wie? Celeste ist nicht gut im Kampf. Was wenn sie..."
  },
  AvgDialog_24081_Content_6 = {
    Text = "Es geht ihr gut. Die Verbindung zwischen uns ist stabil."
  },
  AvgDialog_24081_Content_7 = {
    Text = "Verknüpfung? Also ist Celeste tatsächlich ein Erwecker..."
  },
  AvgDialog_24081_Content_8 = {
    Text = "Elton zwang sich zu einem bitteren Lächeln und griff gewohnheitsmäßig nach seinem Zigarettenetui. Doch sobald er das kalte Metall berührte, zitterte seine Hand, wodurch das Etui fiel und der Tabak überall verstreut wurde."
  },
  AvgDialog_24081_Content_9 = {
    Text = "Du bemerkst plötzlich, dass Eltons Hände zittern, unsicher, ob es vor Schock oder reiner Erschöpfung ist."
  },
  AvgDialog_24082_Content_1 = {
    Text = "Tulu, was schaust du dir an?"
  },
  AvgDialog_24082_Content_10 = {
    Text = "Der Körper und Geist des Verknüpfers kämpfen darum, die Fähigkeiten des Erwachenden zu unterstützen.\nEin Bereich, der die himmlische Anziehungskraft blockieren kann, muss den Erwachenden an die Grenze gebracht haben."
  },
  AvgDialog_24082_Content_11 = {
    Text = "Isoliere himmlische Anziehungskraft... Murphy!"
  },
  AvgDialog_24082_Content_12 = {
    Text = "Als sie deinen Schrei hörte, drehte sich jeder um, um Murphy anzusehen. Sie hielt die Vorderseite ihres Wintermantels fest, ihre Finger zuckten unkontrollierbar."
  },
  AvgDialog_24082_Content_13 = {
    Text = "Hilflos warf sie den Kopf zurück, das Knorpel in ihrem Hals wendete sich vor Schmerz. Jeder Atemzug verbrannte ihre Lungen, jede Zelle zitterte vor Anstrengung."
  },
  AvgDialog_24082_Content_14 = {Text = "Murphy?!"},
  AvgDialog_24082_Content_15 = {
    Text = "Etwas stimmt mit ihr nicht. Kümmere dich schnell um diejenigen, die von dem Duft angezogen werden."
  },
  AvgDialog_24082_Content_2 = {
    Text = "Nach dem Besiegen einer weiteren Welle von Feinden hält Tulu plötzlich am Schiffsreling an, runzelt die Stirn und inspiziert die Bereichsgrenze, die das gesamte Schiff umgibt."
  },
  AvgDialog_24082_Content_3 = {
    Text = "Die Präsenz des Bereichs hat nachgelassen."
  },
  AvgDialog_24082_Content_4 = {
    Text = "Um dem gefährlichen Druck auf dem Schiff zu entkommen, zerstreute sich der Schwarm der Vögel und flog direkt auf das fremde Licht zu"
  },
  AvgDialog_24082_Content_5 = {
    Text = "Eins, zwei, drei... Sie stürmen in Formation gen Himmel, sehnen sich danach, diesen Raum zu entkommen, nur um sanft von der Domäne zurückgehalten zu werden."
  },
  AvgDialog_24082_Content_6 = {
    Text = "Mit Seemöwen, die nacheinander hineinstürzen, wird der Bereich transparent und enthüllt einen fast perfekt runden Vollmond."
  },
  AvgDialog_24082_Content_7 = {
    Text = "Dieser flüchtige Moment verging schnell, wurde jedoch von allen genau festgehalten—"
  },
  AvgDialog_24082_Content_8 = {
    Text = "War das Gebiet... für einen Moment verschwunden?"
  },
  AvgDialog_24082_Content_9 = {
    Text = "Nein, auf keinen Fall! Celeste würde eindeutig nicht..."
  },
  AvgDialog_24083_Content_1 = {
    Text = "Geführt von Celeste navigierten die beiden durch die labyrinthartigen Kammern.\nBald betraten sie einen schwach beleuchteten Raum."
  },
  AvgDialog_24083_Content_10 = {
    Text = "Die schwere Tür der Kabine wurde geöffnet, und bernsteinfarbiges Licht strömte herein. Ihre angespannten Nerven entspannten sich sofort beim Anblick des Umhangs."
  },
  AvgDialog_24083_Content_11 = {Text = "Keeper."},
  AvgDialog_24083_Content_2 = {
    Text = "Die schweren Schritte dringen durch das Deck oben, jeder Schritt wie der Hammer des Schicksals, der unerträgliche Angst in die Seele schlägt."
  },
  AvgDialog_24083_Content_3 = {
    Text = "<Small:So schwere Schritte... Celeste, weißt du, wer dieses Geräusch macht?>"
  },
  AvgDialog_24083_Content_4 = {
    Text = "Celeste schüttelte den Kopf, ihr Gesicht war emotionslos."
  },
  AvgDialog_24083_Content_5 = {
    Text = "<Small:Ist es der Seefahrer, der uns verfolgt......ich hoffe, der Hüter wird nicht mit dem Schrittgeber in einen direkten Konflikt geraten, ich bin nicht da, {Male=er,Female=sie} wird wahrscheinlich nicht der Gegner des Gegners sein......>"
  },
  AvgDialog_24083_Content_6 = {
    Text = "...Es ist hier."
  },
  AvgDialog_24083_Content_7 = {Text = "Was?"},
  AvgDialog_24083_Content_8 = {
    Text = "Bevor Celeste fertig sprach, hallten hastige Schritte auf dem Deck, wurden näher und hielten schließlich vor der Kabine an, in der sie sich versteckten."
  },
  AvgDialog_24083_Content_9 = {
    Text = "Ramona winkte Celeste, still zu bleiben, dann griff sie nach ihrer Waffe und versteckte sich hinter der Tür."
  },
  AvgDialog_24084_Content_1 = {
    Text = "Du legst Murphy auf deinen Schoß. Ihre Muskeln sind unglaublich steif, sodass es sich anfühlt, als würdest du eine Statue halten."
  },
  AvgDialog_24084_Content_10 = {
    Text = "Sie muss zu lange im Bereich gewesen sein, was eine so starke Reaktion verursacht hat. Jetzt, da der Bereich sich wieder stabilisiert hat, wird sie sich bald erholen."
  },
  AvgDialog_24084_Content_11 = {
    Text = "Bevor Tulu mit dem Sprechen fertig sein konnte, saß Murphy schweißnass auf. Sie berührte ihre Brust, ihr Ausdruck war verwirrt."
  },
  AvgDialog_24084_Content_12 = {
    Text = "Ich... Ich lebe noch..."
  },
  AvgDialog_24084_Content_13 = {
    Text = "Wir müssen Ihn schnell extrahieren. Auch wenn dieser Bereich Ihn vor zellularer Anziehung schützt, ist Sein bloßes Dasein eine Last für dich."
  },
  AvgDialog_24084_Content_14 = {
    Text = "Easier gesagt als getan..."
  },
  AvgDialog_24084_Content_15 = {
    Text = "Du erinnerst dich an den fremden Gegenstand, der ihr Herz parasitierte."
  },
  AvgDialog_24084_Content_16 = {
    Text = "Ihre Blutgefäße haben sich mit ihrer Aorta verbunden; selbst die geschicktesten Chirurgen in Londinium können den Erfolg einer solchen Operation nicht garantieren."
  },
  AvgDialog_24084_Content_17 = {
    Text = "Der Sonaniel-Bereich hat den himmlischen Einfluss blockiert. Gibt es einen anderen Weg, um Murphy mehr Zeit zu verschaffen...?"
  },
  AvgDialog_24084_Content_18 = {
    Text = "Zeit... Zeit... Halt..."
  },
  AvgDialog_24084_Content_19 = {Text = "Murphy..."},
  AvgDialog_24084_Content_2 = {
    Text = "Captain, weißt du, was mit ihr nicht stimmt?"
  },
  AvgDialog_24084_Content_20 = {
    Text = "Der Kapitän half ihr langsam und vorsichtig auf, als würde er mit einem Stück Porzellan umgehen."
  },
  AvgDialog_24084_Content_21 = {
    Text = "Student, ich habe dich vorhin tief in Gedanken gesehen. Hast du eine Lösung?"
  },
  AvgDialog_24084_Content_22 = {
    Text = "Keine Lösung... und sehr gefährlich."
  },
  AvgDialog_24084_Content_23 = {
    Text = "An diesem Punkt ist es unmöglich, das Gefahrenlevel einzuschätzen.\nSag mir einfach, solange es Murphy aus der Gefahr bringen kann..."
  },
  AvgDialog_24084_Content_24 = {
    Text = "Mythag Universität forscht über \"Zeitstopp.\""
  },
  AvgDialog_24084_Content_25 = {
    Text = "Könnte es die Rune sein, die du aus dem Lai Krankenhaus mitgebracht hast...?"
  },
  AvgDialog_24084_Content_26 = {
    Text = "Ja. Puppe und Miss Winkle erforschen die Rune und hoffen, einen Raum für Experimente zu schaffen, der vor den <Red:Dimension Dogs> sicher ist."
  },
  AvgDialog_24084_Content_27 = {
    Text = "Die Forschung hat bereits erste Formen angenommen. Vor unserem Aufbruch hatte Frau Zwinkern bereits mit den Tierexperimenten begonnen"
  },
  AvgDialog_24084_Content_28 = {
    Text = "Verschwende keine Mühe"
  },
  AvgDialog_24084_Content_29 = {
    Text = "Eure Schule... kann doch nicht auf dem Meer sein.\nVon hier zurück zum Festland und dann zu eurer Schule... das ist unmöglich"
  },
  AvgDialog_24084_Content_3 = {
    Text = "Der Gott in... ihrem Gott..."
  },
  AvgDialog_24084_Content_30 = {
    Text = "Außerdem, Celeste... Wenn sie in die Hände dieser Frau fällt, ist ungewiss, ob dieses Schiff überhaupt die Küste erreichen wird."
  },
  AvgDialog_24084_Content_31 = {
    Text = "So müssen wir uns beeilen. Kapitän, kannst du den allgemeinen Standort, wo Celeste ist, angeben? Tulu und ich werden sie finden, während du und Murphy zum sicheren Haus zurückkehren solltet."
  },
  AvgDialog_24084_Content_32 = {Text = "Nein!"},
  AvgDialog_24084_Content_33 = {
    Text = "Schiff, Kapitän?"
  },
  AvgDialog_24084_Content_34 = {
    Text = "Elton erkannte seinen Fauxpas. Zitternd griff er nach seinem Zigarettenetui, nur um beim Öffnen daran zu denken, dass der Tabak längst außer Reichweite war."
  },
  AvgDialog_24084_Content_35 = {
    Text = "......Such nicht nach Celeste."
  },
  AvgDialog_24084_Content_36 = {
    Text = "Warum? Kapitän, weißt du etwas?"
  },
  AvgDialog_24084_Content_37 = {
    Text = "Elton ließ Murphy los und trat zwei Schritte zurück. Er sah nach unten zu dir, seine große Gestalt halb im Schatten verborgen."
  },
  AvgDialog_24084_Content_38 = {
    Text = "Celeste... in Miryams Händen."
  },
  AvgDialog_24084_Content_39 = {Text = "Was?!"},
  AvgDialog_24084_Content_4 = {
    Text = "Tulus Gesichtsausdruck änderte sich leicht, als er dies hörte, und ein Tentakel unter seinem Einfluss wickelte sich um Murphys linken Arm."
  },
  AvgDialog_24084_Content_40 = {
    Text = "Dieser Riese... Goliath hat Celeste und mich direkt nachdem wir an Bord gingen, gefunden und zu Miryam gebracht..."
  },
  AvgDialog_24084_Content_41 = {
    Text = "Da wir beide Wanderer sind, übergebe ich dir das Ritual, die Toten in die Welt der Lebenden zu bringen"
  },
  AvgDialog_24084_Content_42 = {
    Text = "Ihr Erscheinen bedeutet, dass dein Wunsch in Erfüllung gegangen ist, du hast sicherlich genug Trost von deinen verstorbenen Verwandten erhalten"
  },
  AvgDialog_24084_Content_43 = {
    Text = "Und mein Wunsch, die große Erwartung, die Gott an mich hat, ist dieses Kind.\nBring mir die Heilige... nein, bring mir die Göttliche Mutter zurück."
  },
  AvgDialog_24084_Content_44 = {
    Text = "Versprochen als der Hohe Priester, wenn unser Gott wiedergeboren wird und das Reich Gottes herabsteigt... wirst du in das Reich Gottes eintreten und ewige Glückseligkeit finden."
  },
  AvgDialog_24084_Content_45 = {
    Text = "Hochpriester, ich war auch überrascht, über das Verschwinden der göttlichen Mutter zu hören.\nAber wie ich bereits sagte, ist die göttliche Mutter nicht auf dem Schiff."
  },
  AvgDialog_24084_Content_46 = {
    Text = "Warum die Heuchelei, sich dumm stellen?"
  },
  AvgDialog_24084_Content_47 = {
    Text = "Ich bewunderte einst deine Intelligenz und Ausdauer sehr. Was brachte dich dazu, deine Loyalität mir gegenüber zu ändern?\nWar es dieser <Blue:Golem>? So schwach und vergänglich..."
  },
  AvgDialog_24084_Content_48 = {
    Text = "Alles war meine Entscheidung; ich bin der Meister dieses Schiffs. Wie könnte Celeste, die fast kein Selbstbewusstsein hat, mich verändern?"
  },
  AvgDialog_24084_Content_49 = {
    Text = "Wirklich? Ich kann dich sie erwecken lassen, und ich kann sie auch wieder in einen Haufen Silbersand verwandeln."
  },
  AvgDialog_24084_Content_5 = {Text = "Schsch."},
  AvgDialog_24084_Content_50 = {Text = "Du...!"},
  AvgDialog_24084_Content_51 = {
    Text = "Finde die Göttliche Mutter und bring sie mir unversehrt zurück."
  },
  AvgDialog_24084_Content_52 = {
    Text = "Dies ist deine letzte Chance, Elton."
  },
  AvgDialog_24084_Content_6 = {
    Text = "Tulu schloss die Augen und spürte die Informationen durch die Tentakeln. Für einen Moment blieb nur das Geräusch der Wellen, die gegen das Schiff schlugen, auf dem Deck übrig, begleitet von Murphys schmerzhaften Stöhnen."
  },
  AvgDialog_24084_Content_7 = {
    Text = "Die Sekunden fühlten sich besonders lang an, und gerade als der Verstand unerträglich werden wollte, zog Tulu schließlich die Tentakeln zurück."
  },
  AvgDialog_24084_Content_8 = {
    Text = "Wie geht es ihr?"
  },
  AvgDialog_24084_Content_9 = {
    Text = "In dem Moment, als der Bereich verschwand, wurde das \"Pseudo-Gott\"-Wesen in ihr stark angezogen."
  },
  AvgDialog_24091_Content_1 = {
    Text = "Seefahrer sind nicht sehr schmerzempfindlich. Als ich ein Kind war, trat ich oft auf ihre Schwänze, und nur wenige von ihnen reagierten."
  },
  AvgDialog_24091_Content_10 = {
    Text = "Gerade dieses eine Mal, trenne dich nach der Rückkehr zur Schule."
  },
  AvgDialog_24091_Content_11 = {
    Text = "Du nickst und umklammerst den Silberschlüssel fest. Fokussiert, schließt du die Augen und versinkst in die Dunkelheit"
  },
  AvgDialog_24091_Content_12 = {
    Text = "Du jagst den hellsten Lichtpunkt, dein Geist wird von unzähligen Wesen im überfüllten Dunkel zusammengedrückt, dein Gehirn wird schmerzhaft zerrissen."
  },
  AvgDialog_24091_Content_13 = {
    Text = "Du streckst die Hand aus und greifst nach dem Stern"
  },
  AvgDialog_24091_Content_14 = {
    Text = "Wie eine Seele, die den Körper verlässt, steigt die Sicht plötzlich auf, gezogen von einer unwiderstehlichen Kraft"
  },
  AvgDialog_24091_Content_15 = {
    Text = "Du siehst dich selbst, siehst Miryam, siehst die kippenden Türme in der Flut... Schließlich siehst du den jungen König, der auf dem Berg sitzt, sein Gesichtsausdruck kalt."
  },
  AvgDialog_24091_Content_16 = {
    Text = "Als du deine Augen wieder öffnest, zuckt ein Schub von Gnosis sanft durch deine Nerven.\nSchmerzhaft, doch erfüllt mit ungewohnter Macht."
  },
  AvgDialog_24091_Content_17 = {
    Text = "Heh... Endlich ist der Moment gekommen."
  },
  AvgDialog_24091_Content_18 = {
    Text = "Dieses Mal hat Tulu die Initiative ergriffen und den plötzlich auftauchenden Goliath angegriffen, ohne ihm die Chance zu geben, zuerst zuzuschlagen."
  },
  AvgDialog_24091_Content_2 = {
    Text = "Das bedeutet, dass die Seefahrer immer wieder aufstehen werden... Wir können nicht garantieren, dass wir sie jedes Mal vollständig besiegen können. Das ist kein tragfähiger Weg zu kämpfen."
  },
  AvgDialog_24091_Content_20 = {
    Text = "Der Tentakel schlägt auf die Kohlenasche, wodurch eine Wolke aus grau-schwarzem Staub aufsteigt.\nWenn der Staub sich wie Regen niederlässt, erscheint die Figur von Miryam."
  },
  AvgDialog_24091_Content_21 = {
    Text = "Miryam, hast du gesehen? Dieses falsche Kind hat sich mit jemandem verbunden—"
  },
  AvgDialog_24091_Content_22 = {
    Text = "Die riesige Schlange entblößte einen sturmähnlichen Angriff auf Goliath, ihre Kraft war so heftig, dass sie ihn gegen die eiserne Wand des Kraftwerks schleuderte."
  },
  AvgDialog_24091_Content_23 = {
    Text = "Wie ein Meteor, der zu Boden fällt, ist Goliath in die Wand der Kabine eingelassen."
  },
  AvgDialog_24091_Content_24 = {
    Text = "Unverzeihlich."
  },
  AvgDialog_24091_Content_25 = {
    Text = "Widerliches Wesen, wie kannst du es wagen, meinen Meister zu beschmutzen und die Macht des lemurischen Gottes zu teilen..."
  },
  AvgDialog_24091_Content_26 = {
    Text = "Miryam senkte den Kopf und kam Schritt für Schritt auf dich zu. Obwohl sie barfuß war, hörtest du ein Geräusch, das wie das Rascheln von Blättern klang."
  },
  AvgDialog_24091_Content_27 = {
    Text = "Unverzeihlich... Nur ich kann den Agenten des Reichs Gottes erwecken, niemand sonst!"
  },
  AvgDialog_24091_Content_28 = {
    Text = "Ihr Zustand ist abnormal! Lauf!"
  },
  AvgDialog_24091_Content_29 = {
    Text = "In einem Moment verdichtete sich der Schatten über dem Kraftwerk zu einer greifbaren Form. \nSchwer zu beschreibende verzerrte Gebäude erhoben sich aus dem Boden"
  },
  AvgDialog_24091_Content_3 = {
    Text = "Nur Tulu, der Hüter, und ich sind in der Lage zu kämpfen; unsere Fähigkeit, unsere Kampfkraft zu steigern, ist sehr begrenzt..."
  },
  AvgDialog_24091_Content_30 = {
    Text = "King... Mein Herr... Murphy... Murphy..."
  },
  AvgDialog_24091_Content_32 = {
    Text = "Jetzt... gibt es noch eine Chance.\nKehre zum Orden zurück, du bist immer noch die ehrenwerte „Gottesmutter\""
  },
  AvgDialog_24091_Content_33 = {
    Text = "Dein Begräbnis wird die prachtvollste Zeremonie in der Geschichte von Gottes Reich sein, bewundert von zigtausenden... Dein Name wird ebenfalls in die Annalen der Geschichte eingetragen und durch die Zeiten weitergegeben."
  },
  AvgDialog_24091_Content_34 = {
    Text = "Komm zurück zu mir, wir werden gemeinsam... diesen <Blue:Unwürdigen> hinrichten"
  },
  AvgDialog_24091_Content_35 = {
    Text = "Führen Sie diesen Betrüger aus, der es wagt, das Aussehen meines Herrn nachzuahmen, und geben Sie die Macht meines Herrn an seinen rechtmäßigen Besitzer zurück.\nNur dann... wird der Herrscher des göttlichen Königreichs ganz sein."
  },
  AvgDialog_24091_Content_36 = {
    Text = "Miryam, öffne deine Augen und sieh mich an. Sieh, wer ich bin!"
  },
  AvgDialog_24091_Content_37 = {Text = "Schweigen!"},
  AvgDialog_24091_Content_38 = {
    Text = "Die riesige Schlange löst sich auf und formt sich wieder; unter dem Druck der Macht von Miryam beginnt der Raum sich allmählich zu verzerren und zu verändern"
  },
  AvgDialog_24091_Content_39 = {
    Text = "Falscher Gott, Fälscher, Scharlatan, Gotteslästerer... Ungläubiger... Verwende nicht die Form von @2!"
  },
  AvgDialog_24091_Content_4 = {
    Text = "Mitten im Satz leuchteten Ramonas Augen plötzlich auf."
  },
  AvgDialog_24091_Content_40 = {
    Text = "<Change>▼▼Die Person... zeigt Respektlosigkeit▼▼... Respektlosigkeit, keine Ehrfurcht, keine Zurückhaltung▼▼▼▼▼▼▼▼▼!"
  },
  AvgDialog_24091_Content_41 = {
    Text = "Er stieß einen schrillen, verstörenden Lärm aus, während Miryam sich mit beiden Händen an ihrem Hals hielt und ihr Körper sich zu verformen und zu dehnen begann"
  },
  AvgDialog_24091_Content_42 = {
    Text = "Vorsicht! Sie verliert die Kontrolle!"
  },
  AvgDialog_24091_Content_5 = {
    Text = "Tulu und der Hüter... sind noch nicht verknüpft, oder?"
  },
  AvgDialog_24091_Content_6 = {
    Text = "Es gibt wirklich keinen. Willst du, dass ich... mit Tulu...?"
  },
  AvgDialog_24091_Content_7 = {
    Text = "Die Verknüpfung unterdrückt und kanalisiert nicht nur das angeborene Aliemus des Erweckers, sondern ermöglicht es den Ermittlern auch, den Fluss des Wahnsinns zu lenken und so die Leistung des Erweckers im Kampf zu beeinflussen."
  },
  AvgDialog_24091_Content_8 = {
    Text = "Einfach gesagt, können Verbindungen die Kampffähigkeiten eines Erwachenden etwas verbessern."
  },
  AvgDialog_24091_Content_9 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_24092_Content_1 = {Text = "Augen auf"},
  AvgDialog_24092_Content_10 = {
    Text = "Sitzungsleiter?"
  },
  AvgDialog_24092_Content_100 = {
    Text = "Kaum zwei Schritte gemacht, kam ein gewaltsamer Beben, das das Schiff fast auseinandergerissen hätte, von unten."
  },
  AvgDialog_24092_Content_101 = {
    Text = "Mit einem gewaltigen Explosionsknall stieg das Feuer in den Himmel und die heiße Luft schleuderte dich zu Boden"
  },
  AvgDialog_24092_Content_102 = {
    Text = "—Das Letzte, was ich sah, bevor ich wieder das Bewusstsein verlor, war ein Seevogel, der über den Nachthimmel flog, im Licht des Vollmonds badend."
  },
  AvgDialog_24092_Content_11 = {
    Text = "Wie hast du geschlafen?"
  },
  AvgDialog_24092_Content_12 = {Text = "Doll?!"},
  AvgDialog_24092_Content_13 = {
    Text = "Hab keine Angst, jetzt ist nicht die Zeit, dich für das Betreten des Rasens am Arbeitstag Nachmittag zur Rechenschaft zu ziehen"
  },
  AvgDialog_24092_Content_14 = {
    Text = "<Gray:Das bedeutet, dass es früher oder später Konsequenzen geben wird...>"
  },
  AvgDialog_24092_Content_15 = {
    Text = "Ramona wich deinem Blick aus, auf ihrem Hinterkopf stand förmlich „Hilflos“"
  },
  AvgDialog_24092_Content_16 = {
    Text = "In Francis' Tagebuch gibt es Erwähnungen von Informationen über die \"Tempellichtkirche\"—Übrigens hattest du noch keine Gelegenheit, diese drei obligatorischen Klassen zu überprüfen, oder?"
  },
  AvgDialog_24092_Content_17 = {
    Text = "Die Temple Light Kirche, die glaubt, dass „der Tod ein göttlicher Segen und die einzige Rettung der Menschheit ist“, täuscht die Kranken, damit sie sich anschließen und sich der Auflösung unterwerfen."
  },
  AvgDialog_24092_Content_18 = {
    Text = "Danke für deine Wiederholung, Professor Dexter.\nAber ich glaube nicht, dass Erica es mag, wenn du dich in ihre Arbeit einmischst"
  },
  AvgDialog_24092_Content_19 = {
    Text = "Meine Schuld, meine Schuld, die restliche Zeit gehört euch"
  },
  AvgDialog_24092_Content_2 = {
    Text = "Warum schläfst du hier?"
  },
  AvgDialog_24092_Content_20 = {
    Text = "Francis hinterließ viele Hinweise, die auf die Kirche des Tempellichts deuten, unter denen \"Auferstehung der Toten\" besonders bemerkenswert ist."
  },
  AvgDialog_24092_Content_21 = {
    Text = "Mit Lilys Erscheinen haben wir Grund zu der Annahme, dass die Tempellichtkirche die Methode beherrscht, Erwachter zu beschwören."
  },
  AvgDialog_24092_Content_22 = {
    Text = "Die Existenz des Erwachten sollte doch streng geheim sein, oder?"
  },
  AvgDialog_24092_Content_23 = {
    Text = "Es scheint, dass du im Geschichtsunterricht über die Erwachten nicht aufgepasst hast.\nIch frage mich, wie du den ersten Test bestanden hast"
  },
  AvgDialog_24092_Content_24 = {
    Text = "Missaga ist nicht die einzige, die die Technologie des Silberkerns beherrscht"
  },
  AvgDialog_24092_Content_25 = {
    Text = "Der Ursprung des Erwachens kann bis vor der Pluvialperiode zurückverfolgt werden. Wandmalereien in den Gräbern der 19. Dynastie des antiken Remouahe scheinen die Beschwörung des Erwachenden darzustellen."
  },
  AvgDialog_24092_Content_26 = {
    Text = "Das Golem, das der Missaga-Erweckungstechnologie am nächsten kommt, stammt aus den Hexenclans der Levante"
  },
  AvgDialog_24092_Content_27 = {
    Text = "Wir schweifen ab"
  },
  AvgDialog_24092_Content_28 = {
    Text = "Basierend auf den Beschreibungen des Glaubens und der Rituale im Tagebuch unterscheidet sich die \"Tempellichtkirche\", die Francis begegnete, von den Informationen, die wir haben."
  },
  AvgDialog_24092_Content_29 = {
    Text = "Dann sendete das entfernte Bildübertragungsgerät, das ich bei Herbert gelassen hatte, dieses Rune zurück.\nWir vermuten, dass Herbert der Mittelsmann ist, der Francis und die Lichtkirche des Tempels verbindet."
  },
  AvgDialog_24092_Content_3 = {
    Text = "Wach auf, du wirst hier kalt"
  },
  AvgDialog_24092_Content_30 = {
    Text = "Dein nächster Feldauftrag ist es, den Inhalt des Tagebuchs zu überprüfen — und die Verbindung zwischen diesem Runensymbol und der Tempellichtkirche zu untersuchen."
  },
  AvgDialog_24092_Content_31 = {
    Text = "Francis hat in ihrem Tagebuch ihre Bewegungen vor der Abreise in die Arktis festgehalten.\nWir werden zu dem Ort gehen, an dem sie an Bord ging – die Stadt Brillport, vielleicht gibt es dort Hinweise"
  },
  AvgDialog_24092_Content_32 = {
    Text = "Bereit, dann lass uns loslegen, ich werde wie immer dein Partner sein"
  },
  AvgDialog_24092_Content_33 = {
    Text = "Das Reisegepäck war immer bereit"
  },
  AvgDialog_24092_Content_34 = {
    Text = "Musst du nicht noch ein bisschen schlafen?"
  },
  AvgDialog_24092_Content_35 = {
    Text = "Nicht nötig!\nIch habe die Missionsanforderungen vollständig verstanden und erinnere mich an alle Details von gestern Abend!"
  },
  AvgDialog_24092_Content_36 = {
    Text = "Dann los.\nWenn wir heute aufbrechen, schaffen wir es vielleicht noch zur Premiere des neuen Stücks im Lentinen-Opernhaus"
  },
  AvgDialog_24092_Content_37 = {
    Text = "Ich gehe den Fahrer suchen, wir treffen uns am Schultor"
  },
  AvgDialog_24092_Content_38 = {
    Text = "Ramonas Rücken verschwand schnell aus dem Blickfeld, und du machst dich bereit, in dein Zimmer zu gehen und dein Gepäck zu holen"
  },
  AvgDialog_24092_Content_39 = {Text = "Keeper."},
  AvgDialog_24092_Content_4 = {
    Text = "Hm...Ramona?"
  },
  AvgDialog_24092_Content_40 = {
    Text = "Dieses Mal könnten wir direkten Kontakt zur Tempel-Licht-Kirche haben."
  },
  AvgDialog_24092_Content_41 = {
    Text = "Die Enthüllung ihrer geheimen Geheimnisse ist sekundär. Deine primäre Aufgabe ist es, am Leben zu bleiben. Ich weiß nicht, wo ich einen weiteren Hüter aus den Ruinen auftreiben kann."
  },
  AvgDialog_24092_Content_42 = {
    Text = "Sei nicht so streng zu den Jungen"
  },
  AvgDialog_24092_Content_43 = {
    Text = "Aber die Puppe hat recht. Die Anhänger, denen du begegnet bist, sind nur periphere Mitglieder; der wahre Kern der Tempellicht-Kirche ist noch nicht aufgetaucht."
  },
  AvgDialog_24092_Content_44 = {
    Text = "Klingt es so, als ob der Professor mit der Tempel Licht Kirche vertraut ist?"
  },
  AvgDialog_24092_Content_45 = {
    Text = "Ha, ha... Nur eine unglückliche Beziehung"
  },
  AvgDialog_24092_Content_46 = {
    Text = "Wenn notwendig, wird Mythag erfahrenere Ermittler entsenden und sogar den Mystia-Vertragsausschuss um Hilfe bitten, um diese Angelegenheit zu lösen"
  },
  AvgDialog_24092_Content_47 = {
    Text = "Komm lebend zurück"
  },
  AvgDialog_24092_Content_48 = {
    Text = "Ich verstehe, wir werden sicher zurückkommen"
  },
  AvgDialog_24092_Content_49 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_24092_Content_5 = {
    Text = "Wie lange habe ich geschlafen?"
  },
  AvgDialog_24092_Content_50 = {
    Text = "Was schaust du noch? Sie sind schon losgegangen"
  },
  AvgDialog_24092_Content_51 = {
    Text = "Keine Sorge, sie sind vernünftige Kinder"
  },
  AvgDialog_24092_Content_52 = {
    Text = "Ich habe keine Sorgen. Selbst wenn wir einen neuen Hüter ausbilden müssen, werden die Mittel vom Bankkonto der Familie Dexter kommen."
  },
  AvgDialog_24092_Content_53 = {
    Text = "Kümmere dich mehr um dich selbst. Ich habe gerade gehört, dass jemandes Tochter ein Rendezvous im Opernhaus hat"
  },
  AvgDialog_24092_Content_54 = {
    Text = "Ha, haha... Die jungen Leute von heute..."
  },
  AvgDialog_24092_Content_55 = {
    Text = "Es ist Nacht"
  },
  AvgDialog_24092_Content_56 = {
    Text = "Ein Schiff zur Arktis? Ihr seid verrückt! Hier gibt es kein Schiff und keine Kirche!"
  },
  AvgDialog_24092_Content_57 = {
    Text = "Frag nicht weiter, wir sind nur einfache Fischer, wir wissen nichts!"
  },
  AvgDialog_24092_Content_58 = {
    Text = "Madam, bitte warten Sie—"
  },
  AvgDialog_24092_Content_59 = {
    Text = "Ihr nutzt eure städtische Macht, um die Landbewohner zu unterdrücken!"
  },
  AvgDialog_24092_Content_6 = {
    Text = "Wer weiß? Du hast sogar das Nachmittagsbriefing verpasst"
  },
  AvgDialog_24092_Content_60 = {
    Text = "Das war nicht unsere Absicht—Hey!"
  },
  AvgDialog_24092_Content_61 = {
    Text = "Die Frau schlug die Tür zu, und wenn Ramona dich nicht rechtzeitig zurückgezogen hätte, wärst du mit einer schiefen Nase zur Schule zurückgekehrt"
  },
  AvgDialog_24092_Content_62 = {
    Text = "Briellport... diese Stadt ist seltsam"
  },
  AvgDialog_24092_Content_63 = {
    Text = "Das ist die dritte Tür, die wir geöffnet haben, aber niemand will Informationen über die Stadt mit uns teilen"
  },
  AvgDialog_24092_Content_64 = {
    Text = "Wir haben nur nach dem Weg gefragt. Sie scheinen etwas zu verbergen, es ist sehr ungewöhnlich"
  },
  AvgDialog_24092_Content_65 = {
    Text = "Schau am Dock nach, vielleicht gibt es Hinweise"
  },
  AvgDialog_24092_Content_66 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_24092_Content_67 = {
    Text = "Was ist los?"
  },
  AvgDialog_24092_Content_68 = {
    Text = "Vielleicht eine Halluzination, es klingt, als ob jemand im Wind spricht"
  },
  AvgDialog_24092_Content_69 = {
    Text = "Oh, perfekt, zwei fremde Tollpatsche.\nHaltet sie auf? Dann müssen wir nicht nach anderen suchen"
  },
  AvgDialog_24092_Content_7 = {Text = "Sitzung?"},
  AvgDialog_24092_Content_70 = {
    Text = "Treib sie in Richtung des Schiffs"
  },
  AvgDialog_24092_Content_71 = {
    Text = "Tsk, fieser Kerl"
  },
  AvgDialog_24092_Content_72 = {
    Text = "Geh, Caecus, deine Gelegenheit, zu zeigen, was du kannst, ist gekommen"
  },
  AvgDialog_24092_Content_73 = {
    Text = "Wie du befiehlst, Lord Goliath."
  },
  AvgDialog_24092_Content_74 = {
    Text = "Countdown: Drei Stunden"
  },
  AvgDialog_24092_Content_75 = {Text = "—Klang!"},
  AvgDialog_24092_Content_76 = {
    Text = "Ein scharfer Schmerz trifft deine Stirn und macht dich schwindelig. Murphy nutzt die Gelegenheit, um sich zu befreien und läuft tiefer in die Kabine, während er sich den Kopf hält."
  },
  AvgDialog_24092_Content_77 = {
    Text = "Ich wusste, dass du nichts Gutes im Schilde führst!!"
  },
  AvgDialog_24092_Content_78 = {
    Text = "Warte, warte... Lass mich erklären..."
  },
  AvgDialog_24092_Content_79 = {
    Text = "Countdown @2 Minuten"
  },
  AvgDialog_24092_Content_8 = {
    Text = "Es geht um Francis—"
  },
  AvgDialog_24092_Content_80 = {
    Text = "Wir gehen jetzt an Bord"
  },
  AvgDialog_24092_Content_81 = {
    Text = "Hast du genug gesehen?"
  },
  AvgDialog_24092_Content_82 = {
    Text = "In dem Moment, als der Bereich verschwand, wurde das \"Pseudo-Gott\"-Wesen in ihr stark angezogen."
  },
  AvgDialog_24092_Content_83 = {
    Text = "Fälschung... Stirb!"
  },
  AvgDialog_24092_Content_84 = {
    Text = "Hüter! Lass meine Hand nicht los!"
  },
  AvgDialog_24092_Content_86 = {
    Text = "Die Umarmung des Meeres wird scharf, das brennende Wasser reagiert mit deiner verbrannten Haut in einem erstickenden Kampf.\nBlinder Chaos, wie ein Dämon der Nacht, zerreißt und bricht deinen Körper."
  },
  AvgDialog_24092_Content_87 = {
    Text = "Dann tauchte ein Hauch von Wärme aus dem Chaos auf. Im grenzenlosen Dunkel zogen Einsamkeit, Hilflosigkeit und Verzweiflung schnell zurück, während ein mysteriöses warmes Licht im gefrierenden Universum erstrahlte."
  },
  AvgDialog_24092_Content_88 = {
    Text = "Als ob du die Barmherzigkeit des Universums berührtest, schritt dein Bewusstsein an der Kante von Gnosis. Dein Körper verschmilzt allmählich mit dem Sauerstoff im Meerwasser. Plötzlich öffnest du deine Augen und Meerwasser strömt aus den Ecken deiner Augen in deinen Körper."
  },
  AvgDialog_24092_Content_89 = {
    Text = "Endlich durchdrang ein sanftes Licht die Dunkelheit des Ozeans. Eine blassblaue Macht streckte sich nach dir aus—wie die Göttin der Navigation, die dir ihre helfende Hand reicht."
  },
  AvgDialog_24092_Content_9 = {
    Text = "Egal, lass den Moderator es dir selbst erklären"
  },
  AvgDialog_24092_Content_90 = {
    Text = "Ich erinnere mich... Miryams letzter Kampf löste die Explosion aus. Ich konnte Ramonas Hand nicht greifen und fiel ins Meer... Nein, aber... das ist das Deck der Sonaniel."
  },
  AvgDialog_24092_Content_91 = {
    Text = "War die letzte Kraft, die mir half, Celeste? Sie hat mich aus Aequor gezogen..."
  },
  AvgDialog_24092_Content_92 = {
    Text = "Dann muss es den anderen auch gut gehen!"
  },
  AvgDialog_24092_Content_93 = {
    Text = "Die traumhafte Wärme wurde vom kalten Mondlicht verdrängt, der Schleier um das Schiff zerriss und verschwand im Meer"
  },
  AvgDialog_24092_Content_94 = {
    Text = "Der Vorhang... ist verschwunden?!"
  },
  AvgDialog_24092_Content_95 = {
    Text = "Am Heck stieg dichter Rauch auf, genau dort, wo sich das Kraftwerk befindet"
  },
  AvgDialog_24092_Content_96 = {Text = "Oh nein!"},
  AvgDialog_24092_Content_97 = {
    Text = "Du ignorierst gewaltsam den seelentiefen Schmerz, hältst dich am Schiffsreling fest und gehst in Richtung des aufsteigenden Rauches."
  },
  AvgDialog_24092_Content_98 = {
    Text = "Der Geruch von Blut und Schießpulver füllt meinen Hals, wodurch jeder Atemzug beim Gehen sich wie Folter anfühlt."
  },
  AvgDialog_24092_Content_99 = {
    Text = "Ramona, Murphy, Celeste, Tulu... Wir müssen uns schnell mit ihnen zusammentreffen."
  },
  AvgDialog_24093_Content_1 = {Text = "Entschluss"},
  AvgDialog_24093_Content_10 = {
    Text = "Wer — Celeste!!"
  },
  AvgDialog_24093_Content_11 = {
    Text = "Elton atmete mehrere Male tief ein und wandte sich den drei zu, die in einem erbärmlichen Zustand erschienen."
  },
  AvgDialog_24093_Content_12 = {
    Text = "Tulus Tentakel stützten Ramona, deren Gesicht ernst war, aber durch zitternde Muskeln Anzeichen von Anspannung verrieten."
  },
  AvgDialog_24093_Content_13 = {
    Text = "Schuluniform... Du bist %player%'s Partner."
  },
  AvgDialog_24093_Content_14 = {
    Text = "Ramona blickte in die Runde. Neben Tulu, den sie aus der Schule kannte, und Celeste, die mit ihr geflohen war, waren zwei unbekannte Gesichter."
  },
  AvgDialog_24093_Content_15 = {
    Text = "Sie... sind Murphy und der Kapitän der Sonanir, die, für die die Hüter bereit sind, ihr Leben zu riskieren, um sie zu schützen."
  },
  AvgDialog_24093_Content_16 = {
    Text = "Ramona Dexter, du kannst mich Ramona nennen.\nLass die Höflichkeiten beiseite. Ich muss alles wissen, was auf diesem Schiff passiert – kurz und schnell."
  },
  AvgDialog_24093_Content_17 = {
    Text = "Wer bist du, warum jagen Seefahrer dich, und was ist das „Ritual“, für das Miryam so leidenschaftlich besessen ist?"
  },
  AvgDialog_24093_Content_18 = {
    Text = "Ich... ich bin..."
  },
  AvgDialog_24093_Content_19 = {
    Text = "Elton hielt Murphy auf, der begierig war zu sprechen. Er wusste, dass das Kind die Situation unter einem solchen Druck nicht vollständig beschreiben konnte."
  },
  AvgDialog_24093_Content_2 = {
    Text = [[
Frachtsschiff Sonanil
Drittes Frachtabteil]]
  },
  AvgDialog_24093_Content_20 = {
    Text = "Ich bin Elton, und das ist mein Partner Celeste, die einzigen beiden Besatzungsmitglieder auf dem Sonaniel Frachtschiff."
  },
  AvgDialog_24093_Content_21 = {
    Text = "In meiner Jugend half mir Miryam, Celeste zu erwecken. Im Gegenzug steuerten wir die Sonanel und transportierten Inventar für den Seefahrer-Orden zwischen dem Kontinent und den Polen."
  },
  AvgDialog_24093_Content_22 = {
    Text = "Schließlich wurden wir von Miryam gejagt, weil wir Murphy halfen, der Sekte zu entkommen."
  },
  AvgDialog_24093_Content_23 = {
    Text = "Murphy wird vom falschen Gott parasitiert, den Miryam zu beschwören beabsichtigt. Ob es ein wahrer Gott ist, kann ich nicht sagen, aber wenn das Ritual durchgeführt wird, ist Murphy verloren."
  },
  AvgDialog_24093_Content_24 = {
    Text = "Murphy erzählte ebenfalls einiges über ihren Körper, ihre Beziehung zu Miryam und ihre Vergangenheit im Kult..."
  },
  AvgDialog_24093_Content_25 = {
    Text = "So viel ist passiert..."
  },
  AvgDialog_24093_Content_26 = {
    Text = "Ich werde Celeste anweisen, in voller Geschwindigkeit auf das Land zurückzukehren, aber ich kann die Rettung von %player% nicht garantieren."
  },
  AvgDialog_24093_Content_27 = {
    Text = "Eltons Worte wurden jäh unterbrochen, als alle durch die plötzliche Beschleunigung taumelten – genau wie er gesagt hatte, hatte Celeste die Geschwindigkeit des Schiffs erhöht."
  },
  AvgDialog_24093_Content_28 = {
    Text = "*Hust, hust...*"
  },
  AvgDialog_24093_Content_29 = {
    Text = "Kapitän! Das Fahren des Schiffs mit solch hoher Geschwindigkeit belastet dich zu sehr."
  },
  AvgDialog_24093_Content_3 = {
    Text = "Harte Stiefelsohlen klopften regelmäßig und dumpf auf das Deck"
  },
  AvgDialog_24093_Content_30 = {
    Text = "...Es ist alles unwichtig."
  },
  AvgDialog_24093_Content_31 = {
    Text = "Ich habe mit dem Kult kolludiert und deine Leiden ignoriert. Meine Sünden sind bereits zu schwer."
  },
  AvgDialog_24093_Content_32 = {
    Text = "Mein... Leiden?"
  },
  AvgDialog_24093_Content_33 = {
    Text = "Die Person, die dich zu Miryam gebracht hat, bin ich"
  },
  AvgDialog_24093_Content_34 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_24093_Content_35 = {
    Text = "Du bist die wertvollste \"Fracht\", die ich transportiert habe, seit ich dem Kult beigetreten bin. Diese perfekte Reise hat mir Miryams Wohlwollen eingebracht."
  },
  AvgDialog_24093_Content_36 = {
    Text = "Also, deshalb hast du nicht gezögert, mir an der Basis des Kultes zu helfen..."
  },
  AvgDialog_24093_Content_37 = {
    Text = "Sobald wir nah genug an der Küste sind, werde ich Celeste mit dir ausschiffen. Halte dich so weit wie möglich vom Meer entfernt."
  },
  AvgDialog_24093_Content_38 = {
    Text = "Es schien, als würde Celeste auf den Kapitän reagieren, indem sie den Kompass in ihrer Hand drehte"
  },
  AvgDialog_24093_Content_39 = {
    Text = "Meinst du, dass Celeste und ich gemeinsam gehen sollen?"
  },
  AvgDialog_24093_Content_4 = {
    Text = "Celeste, %player%..."
  },
  AvgDialog_24093_Content_40 = {
    Text = "Ramona war die Erste, die die Absicht des Kapitäns verstand."
  },
  AvgDialog_24093_Content_41 = {
    Text = "Die Hüter und ich können Transport kontaktieren. Wenn Celeste unser Auto in einen Bereich verwandeln kann..."
  },
  AvgDialog_24093_Content_42 = {
    Text = "Das ist korrekt, das wird dir genug Zeit verschaffen."
  },
  AvgDialog_24093_Content_43 = {
    Text = "Mach keine Witze! Glaubst du wirklich, du kannst diese Monster zurückhalten? Du bist nicht einmal ein Seefahrer, nur ein gewöhnlicher Mensch!"
  },
  AvgDialog_24093_Content_44 = {
    Text = "Nein, überlass das uns."
  },
  AvgDialog_24093_Content_45 = {
    Text = "Das heilige Ritual stoppen, die Welt vor dem Unbekannten beschützen...\nDas ist die Pflicht von jedem an der Mythag Universität."
  },
  AvgDialog_24093_Content_46 = {
    Text = "Bist du auch verrückt? Du weißt nicht einmal, ob wir dich anlügen!"
  },
  AvgDialog_24093_Content_47 = {
    Text = "Der Hüter hat beschlossen, dir zu vertrauen, also werde ich das auch tun."
  },
  AvgDialog_24093_Content_48 = {
    Text = "Der Kapitän taumelte auf die Beine und streckte seine Hand nach Murphy aus—\nDaraufhin ruffled er Murphys Kopf grob."
  },
  AvgDialog_24093_Content_49 = {
    Text = "<Small: Hey! Fass nicht so fest an! Meine Haare sind ganz durcheinander!>"
  },
  AvgDialog_24093_Content_5 = {
    Text = "Wo ist Tulu... Er ist immer noch nicht zurückgekehrt."
  },
  AvgDialog_24093_Content_50 = {
    Text = "Ich hoffe, du kannst dem entkommen, das ist mein letzter Wunsch"
  },
  AvgDialog_24093_Content_51 = {
    Text = "Das Schlimmste wäre doch, im Meer zu sterben, oder? Ich hätte längst mit der Sonaniel untergehen sollen"
  },
  AvgDialog_24093_Content_52 = {
    Text = "Murphy hielt sich hartnäckig am Mantelsaum des Kapitäns fest und weigerte sich, loszulassen"
  },
  AvgDialog_24093_Content_53 = {
    Text = "Ramona ballte und öffnete ihre Handfläche immer wieder, entschlossen, und übergab den fest umklammerten Gegenstand an Murphy—es war ein Kommunikator von der Mythag Universität."
  },
  AvgDialog_24093_Content_54 = {
    Text = "Erbe? Erbschaft?"
  },
  AvgDialog_24093_Content_55 = {
    Text = "Das ist ein Kommunikator, der zwar im Delirium vorübergehend nicht funktioniert, aber das Schulamt versucht sicherlich, uns zu kontaktieren"
  },
  AvgDialog_24093_Content_56 = {
    Text = "Wenn du die Auflösung tatsächlich mit bloßem Auge sehen kannst, dann besitzt du definitiv genügend Geisterkraft, um sie zu nutzen.\nKonzentriere deinen Geist, wenn die Brosche aufleuchtet, und du wirst Kontakt mit der Person auf der anderen Seite herstellen."
  },
  AvgDialog_24093_Content_57 = {
    Text = "Auch wenn der Hüter und ich nicht zu dir zurückkehren können, werden unsere Kameraden dir sicherlich helfen."
  },
  AvgDialog_24093_Content_58 = {
    Text = "Murphy nahm die Brosche, ihre Augen wurden plötzlich rot, als sie die komplizierten Metallverzierungen betrachtete."
  },
  AvgDialog_24093_Content_59 = {
    Text = "Was soll das... Sich so heldenhaft opfern"
  },
  AvgDialog_24093_Content_6 = {
    Text = "Murphy biss sich auf die Lippen und ging nervös hin und her. Manchmal trat sie gegen den Container, manchmal zerrte sie an den Seilen, die den Container fixierten"
  },
  AvgDialog_24093_Content_60 = {
    Text = "Tulu hat kein Interesse an diesem Streit. Er spürt still die Kraftwelle draußen und bereitet sich darauf vor, zum Kraftraum zu gehen."
  },
  AvgDialog_24093_Content_61 = {
    Text = "——Warte! Wohin gehst du!"
  },
  AvgDialog_24093_Content_62 = {
    Text = "Das Mädchen stieß die Tür auf und griff nach einem Tentakel"
  },
  AvgDialog_24093_Content_63 = {
    Text = "Willst du {Male=er,Female=sie} retten?"
  },
  AvgDialog_24093_Content_64 = {
    Text = "Was ich tue, geht niemanden etwas an"
  },
  AvgDialog_24093_Content_65 = {
    Text = "Ich will auch gehen"
  },
  AvgDialog_24093_Content_66 = {
    Text = "Murphy! Sei nicht eigensinnig."
  },
  AvgDialog_24093_Content_67 = {
    Text = "Du bleibst hier; Tulu und ich werden dem Hüter helfen.\nWenn du in Miryams Hände gerätst, werden all unsere Bemühungen umsonst sein."
  },
  AvgDialog_24093_Content_68 = {Text = "Ich weiß."},
  AvgDialog_24093_Content_69 = {
    Text = "Aber... ich kann es nicht tun...\nIch will nicht sterben, aber... was wenn, was wenn du nicht zurückkehrst?"
  },
  AvgDialog_24093_Content_7 = {
    Text = "Ihnen wird nichts passieren, oder?"
  },
  AvgDialog_24093_Content_70 = {
    Text = "Ich... möchte nicht, dass das passiert..."
  },
  AvgDialog_24093_Content_71 = {
    Text = "......Ich kann nicht ewig im Bereich bleiben. Wenn ich wirklich entkommen will, benötige ich deine Empfehlung."
  },
  AvgDialog_24093_Content_72 = {
    Text = "Ich kann nicht einfach zur Schule gehen und dem Direktor sagen, dass seine Schüler sich opfern, um mir zu helfen.\nIch brauche deine Vorstellung, und keiner von euch darf sterben."
  },
  AvgDialog_24093_Content_73 = {
    Text = "Ich werde dich nicht beschützen"
  },
  AvgDialog_24093_Content_74 = {
    Text = "Du brauchst nicht zu beschützen; ich kenne die Schwächen der Seefahrer und kann gut für mich selbst sorgen"
  },
  AvgDialog_24093_Content_75 = {
    Text = "Gut, wenn du darauf bestehst"
  },
  AvgDialog_24093_Content_76 = {
    Text = "Was für ein Blick ist das?"
  },
  AvgDialog_24093_Content_77 = {
    Text = "Ich dachte ursprünglich, du wärst es nicht wert, dass sie so viel für dich opfern.\nJetzt sehe ich, dass ich voreingenommen war"
  },
  AvgDialog_24093_Content_78 = {
    Text = "Was redest du für Rätsel? Geh schnell, geh schnell!"
  },
  AvgDialog_24093_Content_79 = {
    Text = "Murphy schob Tulu mit einer Hand und zog Ramona mit der anderen, bevor sie bald in den tiefen, schattigen Gang des Schiffs verschwand."
  },
  AvgDialog_24093_Content_8 = {
    Text = "Sie konnte nicht ruhig beten oder sich beruhigt hinsetzen"
  },
  AvgDialog_24093_Content_80 = {
    Text = "Dieses Kind... na ja, wenn das ihre Wahl ist"
  },
  AvgDialog_24093_Content_81 = {
    Text = "Celeste, volle Fahrt beibehalten"
  },
  AvgDialog_24093_Content_9 = {Text = "Bang—!"},
  AvgDialog_24094_Content_1 = {
    Text = "Mit den Turbulenzen im Geist von Miryam wird auch die Gruppe der Seefahrer instabil, und das Chaos breitet sich leise aus"
  },
  AvgDialog_24094_Content_2 = {
    Text = "Die Seemänner erkannten Murphy, „schwanger“ mit den Göttern, und zogen sich instinktiv zurück, als sie näherkam. Du rannte durch den Kreis der Monster."
  },
  AvgDialog_24095_Content_1 = {
    Text = "Die Tentakel fegen die herannahenden Seefahrer beiseite. Tulu bringt das Ende auf, um eure Spuren zu bedecken."
  },
  AvgDialog_24095_Content_2 = {
    Text = "Obwohl die Seefahrer über eine geringe Intelligenz verfügen, sind sie an diesem Punkt plötzlich unsicher geworden.\nGerüchte beginnen innerhalb der Gruppe zu kursieren, die Sprache alt und obskur, was Tulu dazu bringt, die Stirn zu runzeln."
  },
  AvgDialog_24095_Content_3 = {
    Text = "Der Verdacht dieser Seefahrer wird Miryam nur wütend machen."
  },
  AvgDialog_24095_Content_4 = {
    Text = "Verdacht? Kannst du verstehen, was sie sagen?"
  },
  AvgDialog_24095_Content_5 = {
    Text = "Ohne Tulu Zeit zum Erklären zu geben, übersetzte Miryam die alte Sprache vollständig durch ihre Taten."
  },
  AvgDialog_24095_Content_6 = {
    Text = "Der Dolch schnitt durch die Kehlen mehrerer Seefahrer. Sie badete im gespritzten grau-blauen Blut und durchquerte die Gruppe der Seefahrer"
  },
  AvgDialog_24095_Content_7 = {
    Text = "Ein Gott-König wiedergeboren? Nein...\nEr steigt nur bei der Ausrichtung der Sterne herab, gezogen durch das Ritual!"
  },
  AvgDialog_24095_Content_8 = {
    Text = "Nur mein Ritual kann den Gott-König auferwecken und das Reich Gottes wiederherstellen! Nur ich!"
  },
  AvgDialog_24095_Content_9 = {
    Text = "Seefahrer... Lass diejenigen, die den Namen unseres Herrn schmähen, die Majestät der Blutlinie des Göttlichen Reiches erleben!"
  },
  AvgDialog_24096_Content_1 = {
    Text = "Verlorenes Licht"
  },
  AvgDialog_24096_Content_10 = {
    Text = "Verdrehte Gliedmaßen, der Ausdruck auf der verbliebenen Hälfte des Gesichts eingefroren im Moment des Todes. Fließendes Blut hatte sich in unverständliche Runen verdichtet, die die Luft mit einer rasenden Aura des Todes erfüllten."
  },
  AvgDialog_24096_Content_11 = {
    Text = "\nDein \"Gott\" würde so ein erschreckendes Opfer wahrscheinlich nicht zu schätzen wissen, oder?\nIhr Gesandter verschwand, während er bei uns war; wie willst du das der Tempel Licht Kirche erklären?"
  },
  AvgDialog_24096_Content_12 = {
    Text = "Goliaths Worte hatten kaum seinen Mund verlassen, als die Narbe an seinem Hals heftig zusammenzog und sich um seine Muskeln festzog."
  },
  AvgDialog_24096_Content_13 = {
    Text = "Dein Kopf wurde mit dem Blut von Lemuria geformt, nicht um gegen meinen Gott, Goliath, zu lästern."
  },
  AvgDialog_24096_Content_14 = {
    Text = "Mein großer und allmächtiger Herr erhält Kraft aus meinen Gebeten und erkennt meine Hingabe durch meine Opfer."
  },
  AvgDialog_24096_Content_15 = {
    Text = "Was die beiden Laternen-Träger betrifft... grob, töricht und völlig irrelevanter Abschaum. Wenn die Laterne irgendwelche Beschwerden hat, sehe ich keinen Grund, sie weiterhin zu begleiten."
  },
  AvgDialog_24096_Content_16 = {
    Text = "Miryam wischte das Blut von ihren Fingern und drehte sich schließlich zu dir um. Ein anhaltender Gestank des Verfalls umgab sie, und jede Annäherung peinigte deinen Verstand."
  },
  AvgDialog_24096_Content_17 = {
    Text = "Was hast du... mit ihnen gemacht?"
  },
  AvgDialog_24096_Content_18 = {
    Text = "Du bist anders als sie."
  },
  AvgDialog_24096_Content_19 = {
    Text = "Miryam antwortete auf deine Frage nicht. Sie sah dich mit Augen an, die wie ein tiefer Teich waren und die Überreste von Jahrtausenden Geschichte verbargen."
  },
  AvgDialog_24096_Content_2 = {
    Text = "Äußeres Meer Frachter · Sonaniel\nMacht Raum"
  },
  AvgDialog_24096_Content_20 = {
    Text = "Du besitzt die einzigartigste Seele, die ich seit meinem Erwachen gesehen habe... Heller und dunkler als die deines Begleiters."
  },
  AvgDialog_24096_Content_21 = {
    Text = "Hüter der Mythag Universität... Ich habe immer Mitleid mit den Fähigen gehabt. Ich hoffe aufrichtig, dass ihr im göttlichen Licht unseres Herrn strahlen könnt."
  },
  AvgDialog_24096_Content_22 = {
    Text = "Die Weisen sollten sich nicht im Alltäglichen verlieren. Obwohl das göttliche Reich mit Abstammung verwoben ist, zögert es nicht, ausländisches Blut zu umarmen."
  },
  AvgDialog_24096_Content_23 = {
    Text = "Dein Ziel, die Welt von Korruption zu retten, steht nicht im Widerspruch zu <Blue: Gottes Rückkehr ins Reich>."
  },
  AvgDialog_24096_Content_24 = {
    Text = "Diene uns, schließe dich der Wiederbelebung und Rückkehr des Reiches Gottes an und erlange ultimativen Ruhm... So werden wir im Land des Glücks wandeln."
  },
  AvgDialog_24096_Content_25 = {
    Text = "Wenn das \"Wiederbelebung\" und \"Renaissance\", von der du sprichst, bedeutet, die Lebenden als Opfer und die Unschuldigen als Gefäße für Monster zu verwenden..."
  },
  AvgDialog_24096_Content_26 = {
    Text = [[
Entschuldigung, ich kann das nicht tun.
Dein Ritual ist barbarisch und grausam. Ich sehe keinen Hauch von Vernunft oder Zivilisation darin.]]
  },
  AvgDialog_24096_Content_27 = {
    Text = "Als Gefäß für die Wiedergeburt des Gottes und als Grundpfeiler der Rückkehr des Göttlichen Reiches sollte man dies als Ehre betrachten!"
  },
  AvgDialog_24096_Content_28 = {
    Text = "Dieses Mal habe ich mich geirrt. Es gibt keinen Grund, Worte mit Narren zu verschwenden... Diese Farce sollte ein Ende haben."
  },
  AvgDialog_24096_Content_29 = {
    Text = "Kraft bricht aus den Schatten hervor, sich zu einer massiven und festen schlangenartigen Energieform verdichtend."
  },
  AvgDialog_24096_Content_3 = {
    Text = "Miryam stand in der Mitte des Raumes, ihre Augen halbgeschlossen, wie eine Statue, gelassen und ruhig. Selbst als Goliath dich grob vor sie warf, hob sie nur kurz ihre Augen, um dich anzusehen."
  },
  AvgDialog_24096_Content_30 = {
    Text = "Die riesige Schlange schlägt wild, ihre Augen richten sich schließlich auf dich — Sie schlingt sich um deine Taille und hebt dich mühelos hoch."
  },
  AvgDialog_24096_Content_31 = {
    Text = "Halt, Miryam."
  },
  AvgDialog_24096_Content_32 = {Text = "Wer da?!"},
  AvgDialog_24096_Content_33 = {
    Text = "Eine vertraute Stimme überwindet die Kluft der Geschichte, sanft wie eine Brise, aber sie entfacht einen Sturm in deinem Herzen"
  },
  AvgDialog_24096_Content_34 = {
    Text = "Miryam, ich sage, lass den Schüler los"
  },
  AvgDialog_24096_Content_35 = {
    Text = "Diese Farce muss wirklich enden"
  },
  AvgDialog_24096_Content_36 = {
    Text = "Ich erinnere mich nicht an dein Gesicht, aber... es gibt Spuren meines Meisters auf dir."
  },
  AvgDialog_24096_Content_37 = {
    Text = "Ein Hauch von Mitgefühl erscheint auf Miryams Gesicht. Ihre Augen, wie Blumen, die von absurder Regen verwüstet wurden, sind voller unendlicher Trauer und Schmerz."
  },
  AvgDialog_24096_Content_38 = {
    Text = "Kalte, glitschige Schlangenschuppen gleiten über deinen Körper, die Riesenschlange zieht sich wie ein Würgegriff immer enger zusammen"
  },
  AvgDialog_24096_Content_39 = {
    Text = "Tränen hinterließen unauslöschliche Spuren in ihrem Gesicht. Ihre Augen waren auf Tulu gerichtet, als würden sie seine Seele und ihre Geschichte aus zehntausend Jahren durchdringen."
  },
  AvgDialog_24096_Content_4 = {
    Text = "Ihr Blick ist so kalt und grausam wie der einer Viper, und schließt dich vollkommen aus – du bist weder ihr Gegner noch Teil ihrer Nahrungskette."
  },
  AvgDialog_24096_Content_40 = {
    Text = "<Blue:Mein Lord>... Mein geschätzter <Blue:King>... \nWie konntest du die Aura eines Erwachenden besitzen?"
  },
  AvgDialog_24096_Content_41 = {
    Text = "Wer hat dein Relikt entweiht? Wer... hat unser Versprechen verletzt?"
  },
  AvgDialog_24096_Content_42 = {
    Text = "Eine riesige Schlange hebt dich in die Luft, das Blut strömt in deinen Kopf, und dir wird schwarz vor Augen"
  },
  AvgDialog_24096_Content_43 = {
    Text = "Aber im Dämmerzustand hast du immer noch zwei Mädchen erblickt... Sie wurden von den Seefahrern umzingelt. Warum kommen sie immer näher?"
  },
  AvgDialog_24096_Content_44 = {
    Text = "Ramona! Jetzt!"
  },
  AvgDialog_24096_Content_45 = {
    Text = "Ramona holte tief Luft, beugte ein Bein und sprang mit der gesammelten Energie hoch"
  },
  AvgDialog_24096_Content_47 = {
    Text = "Die Spitze des Rapiers durchdringt die schlangenförmige Energiekörper und trifft die Schwachstelle der Riesenschlange"
  },
  AvgDialog_24096_Content_48 = {
    Text = "Hey, hey! Jemand fällt runter!"
  },
  AvgDialog_24096_Content_49 = {
    Text = "Du fällst auch im Gebrüll der Riesenschlange"
  },
  AvgDialog_24096_Content_5 = {
    Text = "Was ist mit den anderen?"
  },
  AvgDialog_24096_Content_50 = {
    Text = "——Dann fiel sie in eine zitternde, warme Umarmung"
  },
  AvgDialog_24096_Content_51 = {
    Text = "...Geht es dir gut, %player%?"
  },
  AvgDialog_24096_Content_52 = {
    Text = "Ramona... Ich..."
  },
  AvgDialog_24096_Content_53 = {
    Text = "Es tut mir leid, jetzt ist nicht die beste Zeit, um nachzuholen."
  },
  AvgDialog_24096_Content_54 = {
    Text = "Ramona hielt dich fest umklammert und eilte von Miryam weg, ohne sich umzusehen."
  },
  AvgDialog_24096_Content_55 = {
    Text = "Du hast dich umgedreht, um Miryam zu sehen, die Schlange, die sich erneut formiert hat, und ihr Blick fiel auf dich und Ramona."
  },
  AvgDialog_24096_Content_56 = {
    Text = "Der Blick ist wie eine giftige Schlange, die ihr Beutetier betrachtet."
  },
  AvgDialog_24096_Content_57 = {
    Text = "Tulu! Verwickel dich nicht mit ihr; priorisiere Murphys Flucht."
  },
  AvgDialog_24096_Content_6 = {
    Text = "Habe ich nicht gesagt? Mythags kleine Mäuse sind gut darin, überall Löcher zu graben. Dieses hier zu behalten, ist schon schwer genug."
  },
  AvgDialog_24096_Content_7 = {
    Text = "Es spielt keine Rolle mehr, was mit den anderen ist, oder?\nSieht so aus, als hättest du bereits den Altar für den \"Gott\" gebaut."
  },
  AvgDialog_24096_Content_8 = {
    Text = "Miryam drehte sich langsam um, das schlangenartige Phantom löste sich mit ihrer Bewegung auf und umhüllte sie in einem lila Schimmer, wie ein getaufter Gläubiger."
  },
  AvgDialog_24096_Content_9 = {
    Text = "Der Altar hinter ihr kam allmählich ins Blickfeld, das schwache Licht im Kraftraum warf gespenstische Schatten auf ihr Gesicht. In der Mitte des Altars lagen zwei nicht erkennbare Leichname reglos."
  },
  AvgDialog_24097_Content_10 = {
    Text = "Übrigens, tut dein Waden immer noch weh? Es scheint, als hätte es aufgehört zu bluten."
  },
  AvgDialog_24097_Content_11 = {
    Text = "Ich kann den Schmerz kaum noch fühlen..."
  },
  AvgDialog_24097_Content_12 = {
    Text = "Als du über die Zukunft sprichst, löst sich Miryams Illusion wie schmelzender Schnee auf.\nDer Feind erlangt etwas Klarheit zurück und legt seine monströse Form ab."
  },
  AvgDialog_24097_Content_13 = {
    Text = "Miryam lag schwach im schwarzen Staub, mit einem verschwommene, leeren Blick, ohne auf das Erscheinen von Tulu zu reagieren"
  },
  AvgDialog_24097_Content_14 = {
    Text = "Gib nicht auf, Miryam"
  },
  AvgDialog_24097_Content_15 = {
    Text = "Gehört zu unserer Zeit, unserem <Blue:ewigen Reich>, sein Verschwinden ist besiegelt"
  },
  AvgDialog_24097_Content_16 = {
    Text = "Nein... nein... er hat es mir versprochen"
  },
  AvgDialog_24097_Content_17 = {
    Text = "<Yellow:Du> hast mir ein Versprechen gegeben."
  },
  AvgDialog_24097_Content_18 = {
    Text = "Die abgemagerte Frau zeigte schließlich eine Reaktion. Sie sah gedankenverloren nach oben und murmelte vor sich hin."
  },
  AvgDialog_24097_Content_19 = {
    Text = "Mein allmächtiger Gott wird seine Macht wielden... um diese unverzeihlichen Ketzer zu richten, die falsche Objekte erschaffen!"
  },
  AvgDialog_24097_Content_2 = {
    Text = "Verschwinden diese Gebäude? Ist alles... vorbei?"
  },
  AvgDialog_24097_Content_20 = {
    Text = "Sie zog den Dolch aus ihrem Gürtel, und violett-schwarze Flammen umhüllten die Klinge, die eine unheimliche Todesaura ausstrahlte"
  },
  AvgDialog_24097_Content_21 = {
    Text = "Fälschung... Stirb!"
  },
  AvgDialog_24097_Content_22 = {
    Text = "—Die gespenstische, kalte Flamme des Dolches entzündete den Kohlenstaub."
  },
  AvgDialog_24097_Content_23 = {
    Text = "<BigShake:Ah!>"
  },
  AvgDialog_24097_Content_24 = {
    Text = "In der Kettenreaktion von Feuer und Staub wurde jeder von dem ohrenbetäubenden Donner der Explosion erfasst, und das Schiff schwankte plötzlich in eine Richtung."
  },
  AvgDialog_24097_Content_25 = {
    Text = "Vor dir sind rasch wachsende Flammen, hinter dir die von der Explosion zerrissene Schiffswand"
  },
  AvgDialog_24097_Content_26 = {
    Text = "Hüter! Lass meine Hand nicht los!"
  },
  AvgDialog_24097_Content_27 = {
    Text = "Die Spitze der Nase wird von dem stechenden Gestank verbrannten Kohlen erfüllt. Nach einer kurzen Berührung wird ein Handschuh mit Gewalt von der Schwerkraft in den Abgrund gezogen."
  },
  AvgDialog_24097_Content_28 = {
    Text = "Ein vertrauter Stimme und die Wärme dieser Person verblassten schnell und wurden ersetzt durch eine kriechende Feuchtigkeit und Kälte, die meinen Rücken hinaufkrabbelte."
  },
  AvgDialog_24097_Content_29 = {Text = "Hüter!"},
  AvgDialog_24097_Content_3 = {
    Text = "Dies ist die Illusion, die Miryam geschaffen hat, vielleicht ihr sogenanntes <Blue:Göttliches Reich>..."
  },
  AvgDialog_24097_Content_30 = {
    Text = "In diesem Moment erstarrte die Zeit. Die brennenden Hitzewellen schnitten durch die Haut wie unzählige Klingen, und verbrannten jede Sehne, bis sie so zerbrechlich wie Zikadenflügel waren."
  },
  AvgDialog_24097_Content_31 = {
    Text = "Ein ohrenbetäubendes und chaotisches Horn durchdringt das geistliche Reich und zerbricht ein Jahr des Verstandes und des Friedens. In diesem endlosen Moment fühlst du Angst und Kampf inmitten des Chaos."
  },
  AvgDialog_24097_Content_32 = {
    Text = "Aber am Ende wurde alles von Flammen verschlungen, und das Bewusstsein endete in dieser endlosen Dunkelheit..."
  },
  AvgDialog_24097_Content_4 = {
    Text = "Das Reich unter der Herrschaft der Götter, das ewige Lemuria."
  },
  AvgDialog_24097_Content_5 = {
    Text = "\"Lemuria\"... Ich erinnere mich, einige Wissenschaftler aus der Geschichtsabteilung von Mythag diskutieren, ob es wirklich existiert."
  },
  AvgDialog_24097_Content_6 = {
    Text = "Wenn die Katastrophe niemals zugeschlagen wäre, hätte sie heute hoch oben stehen sollen..."
  },
  AvgDialog_24097_Content_7 = {
    Text = "Seit das alles in der Vergangenheit liegt, können wir über die Stadt reden, nachdem wir völlig sicher sind? Lass uns zuerst mit dieser Sache umgehen."
  },
  AvgDialog_24097_Content_8 = {
    Text = "Ramona, sobald das Schiff anlegt, werden wir den Bereich verlassen und die Schule kontaktieren, um Vorbereitungen zu treffen.\nTulu, bleib auf dem Schiff und kümmere dich vorübergehend um Murphy."
  },
  AvgDialog_24097_Content_9 = {
    Text = "Ja, benachrichtigt alle, den Operationssaal mit Zeit-Runen vorzubereiten. Was die Operation zur Entfernung des Parasiten betrifft, könnte stellvertretender Dekan Czort sie persönlich durchführen müssen."
  },
  AvgDialog_24260_Content_1 = {
    Text = "Es ist wiederhergestellt...?! Ist unser Angriff völlig ineffektiv?"
  },
  AvgDialog_24260_Content_2 = {
    Text = "Nein... schau dir diese beiden Energieschlangen an. Sie strahlen eine starke Miryam-Aura aus. Vielleicht müssen wir sie zuerst besiegen..."
  },
  AvgDialog_24260_Content_3 = {
    Text = "Als das Reich der Götter intakt war, konnte sie nur den Schatten einer Schlange beschwören. Nach einem Jahrtausend des Schlafs könnte sie nun bis zu <Yellow:acht> Schatten kontrollieren."
  },
  AvgDialog_24260_Content_4 = {
    Text = "Die verbotenen Riten von Lemuria... Wir können nicht länger zulassen, dass sie vom Zorn verzehrt wird. Wenn sie die völlige Kontrolle verliert, wird sie zu einem vollständigen Monster."
  },
  AvgDialog_24261_Content_1 = {
    Text = "Die Schatten ihrer Diener sind bereits vollständig zerstreut, also warum ist sie immer noch...!"
  },
  AvgDialog_24261_Content_2 = {
    Text = "Sie will das Ritual erzwingen, aber das ist nur ihre Illusion... Ohne die Anleitung der Sterne wird das Ritual nur die Seelen aller verbrennen."
  },
  AvgDialog_24261_Content_3 = {
    Text = "Hoher Priester Miryam! Im Namen von @2 Walker befehle ich dir, aufzuhören!"
  },
  AvgDialog_24261_Content_4 = {
    Text = "Der Verstand war bereits vom Zorn verschlungen, das einst als Miryam bekannte Ungeheuer stockte nur für einen Moment, bevor es erneut einen wahnsinnigen Angriff startete"
  },
  AvgDialog_24261_Content_5 = {
    Text = "Sie hat mich bereits für einen Betrüger gehalten... In diesem Fall muss ich sie auf die lemurische Weise behandeln. Sie unterwerfen oder... sie töten."
  },
  AvgDialog_24261_Content_6 = {
    Text = "Miryam... mein treuester Untertan... \nMögest du... nicht länger in Verwirrung verloren sein."
  },
  AvgDialog_24282_Content_1 = {
    Text = "Jetzt testen wir Bildschirmwackeln 2"
  },
  AvgDialog_24282_Content_2 = {
    Text = "Theoretisch sollte das Charakterbild mit dem Hintergrund wackeln"
  },
  AvgDialog_24282_Content_3 = {
    Text = "Jetzt testen wir Links-Rechts-Schwenk 2"
  },
  AvgDialog_24282_Content_4 = {
    Text = "Theoretisch sollte das Charakterbild mit dem Hintergrund verschoben werden"
  },
  AvgDialog_24282_Content_5 = {Text = "Testende"},
  AvgDialog_24296_Content_1 = {
    Text = "Nein, es sind zu viele Leute... Es wird nur noch schlimmer..."
  },
  AvgDialog_24296_Content_10 = {
    Text = "Nein, Herr Goliath—!!"
  },
  AvgDialog_24296_Content_11 = {
    Text = "Es fühlt sich an, als wäre alles vor meinen Augen angehalten worden."
  },
  AvgDialog_24296_Content_12 = {
    Text = "Die Instinkte deines Körpers übernehmen die Kontrolle. Er stürzt nach vorne und schirmt verzweifelt Goliath ab."
  },
  AvgDialog_24296_Content_13 = {Text = "Hmm—"},
  AvgDialog_24296_Content_14 = {
    Text = "Eine Klinge schlitzt deine Kehle auf. Zitternd presst du die Hand auf die blutende Wunde, dein Verstand im Chaos."
  },
  AvgDialog_24296_Content_15 = {
    Text = "Hast du den Verstand verloren? Was machst du hier?!"
  },
  AvgDialog_24296_Content_16 = {
    Text = "Ich weiß nicht... Mein Körper hat sich von selbst bewegt..."
  },
  AvgDialog_24296_Content_17 = {
    Text = "Entschuldigung, Lord Goliath..."
  },
  AvgDialog_24296_Content_2 = {
    Text = "Ich... kann noch... töten!"
  },
  AvgDialog_24296_Content_20 = {
    Text = "Ein vergifteter Pfeil zischte durch die Luft, traf Goliaths Schulter und ließ ihn in deine Richtung stürzen."
  },
  AvgDialog_24296_Content_21 = {
    Text = "Goliath... Der riesige Goliath ist endlich gefallen!"
  },
  AvgDialog_24296_Content_22 = {
    Text = "Sein Kopf gehört mir! Niemand wird ihn mir wegnehmen!!!"
  },
  AvgDialog_24296_Content_23 = {
    Text = "Das Meer ließ ein tiefes, zorniges Beben ertönen. Der Riese versperrte die gleißende Sonne, bevor er krachend zusammenbrach."
  },
  AvgDialog_24296_Content_24 = {
    Text = "Euer Blut fließt zusammen und färbt das azurblaue Meer purpurrot."
  },
  AvgDialog_24296_Content_25 = {
    Text = "Du hörst den Wind, die Wellen und in der Ferne Jubel und Kampfgeschrei. Vor dir liegt nichts als endloses Gemetzel und Erniedrigung."
  },
  AvgDialog_24296_Content_26 = {
    Text = "Das salzige Meerwasser brennt in der Wunde an deinem Hals und lässt dich vor Schmerz zusammenzucken."
  },
  AvgDialog_24296_Content_27 = {
    Text = "Goliath geht es kaum besser als dir."
  },
  AvgDialog_24296_Content_28 = {
    Text = "Als er dich in einem so erbärmlichen Zustand sieht, schafft er es dennoch, dir ein boshaftes Grinsen zuzuwerfen."
  },
  AvgDialog_24296_Content_29 = {
    Text = "Ich würde sagen... du solltest wirklich mal in den Spiegel schauen und sehen, wie absurd du gerade aussiehst."
  },
  AvgDialog_24296_Content_3 = {
    Text = "Das dröhnende Hallen von Hörnern echote über das Meer. Angelockt von großzügigen Belohnungen strömten Krieger herbei, um sich dem Jagdspiel anzuschließen."
  },
  AvgDialog_24296_Content_30 = {
    Text = "Wie erwartet bist du zu nichts zu gebrauchen."
  },
  AvgDialog_24296_Content_4 = {
    Text = "Goliath näherte sich seinem Limit. Er schwang seine Riesenklinge ein weiteres Mal, doch in seiner trägen Bewegung ergriff jemand die Lücke."
  },
  AvgDialog_24296_Content_6 = {
    Text = "Er sank auf die Knie, die Wunde legte blankweiße Knochen frei, Blut floss wie ein nie versiegender Strom."
  },
  AvgDialog_24296_Content_8 = {
    Text = "Jetzt ist der Moment! Macht ihn mit einem Schlag fertig!!"
  },
  AvgDialog_24296_Content_9 = {
    Text = "Die einkreisenden Krieger schwärmen heran wie blutdürstige Haie."
  },
  AvgDialog_24297_Content_1 = {Text = "Hmm—!!"},
  AvgDialog_24297_Content_10 = {
    Text = "Unter großer Belohnung treten gewiss tapfere Männer hervor. Die Krieger brachen in begeisterte Jubelrufe aus, ihre Waffen klirrten und hallten mit dem aufregenden Klang des Kampfes wider."
  },
  AvgDialog_24297_Content_11 = {
    Text = "Ja, wovor sollen wir Angst haben? Wir sind so viele!"
  },
  AvgDialog_24297_Content_12 = {
    Text = "Schnitt ihm zuerst die Hand ab, die das Messer hält!"
  },
  AvgDialog_24297_Content_13 = {
    Text = "Die einst kauernden Krieger brüllten auf und stürmten wie blutdürstige Heuschrecken nach vorn."
  },
  AvgDialog_24297_Content_14 = {
    Text = "Heh... meine liebsten Verwandten. Ich habe euch beigebracht, wie man kämpft, wie man tötet und wie man überlebt."
  },
  AvgDialog_24297_Content_15 = {
    Text = "Aber ich habe euch nie beigebracht, wie man flieht, wenn man einem Feind gegenübersteht, der weit stärker ist als ihr."
  },
  AvgDialog_24297_Content_16 = {
    Text = "Goliath leckte das Blut aus seinem Mundwinkel und entblößte seine Reißzähne."
  },
  AvgDialog_24297_Content_17 = {
    Text = "...denn ihr habt nirgendwo mehr hin zu fliehen."
  },
  AvgDialog_24297_Content_18 = {
    Text = "Damit packte er beiläufig ihre Kehlen, hob ihre Köpfe an und schmetterte sie zusammen—"
  },
  AvgDialog_24297_Content_19 = {Text = "Rums!!"},
  AvgDialog_24297_Content_2 = {
    Text = "Ein rasendes Hackbeil zerschlug das Schiff in Stücke und zwang Glen zum Rückzug – mit nur noch einem verbliebenen Bein."
  },
  AvgDialog_24297_Content_20 = {
    Text = "Gelbe und weiße Flüssigkeiten vermischten sich mit zersplittertem Blut und spritzten heraus. Goliath lachte herzhaft, seine Pupillen brannten vor blutdürstiger Bosheit."
  },
  AvgDialog_24297_Content_21 = {
    Text = "Hahaha! Ich habe gehört, jemand will mir den Kopf abnehmen?"
  },
  AvgDialog_24297_Content_22 = {
    Text = "Wenn ihr den Mumm habt, stellt euch an und holt ihn euch einer nach dem anderen!"
  },
  AvgDialog_24297_Content_3 = {
    Text = "<Shake:Warst du nicht verletzt? Wie konntest du...>"
  },
  AvgDialog_24297_Content_4 = {
    Text = "Verzeihung, aber um mit einem Handlanger wie dir fertigzuwerden, brauche ich nicht meine volle Stärke."
  },
  AvgDialog_24297_Content_5 = {
    Text = "Goliath steht stolz am Bug, seine gewaltige Klinge beschreibt einen Bogen vor ihm und hält seine einstigen Kameraden auf Abstand."
  },
  AvgDialog_24297_Content_6 = {
    Text = "Gibt es noch jemanden, der heraufkommen und mit mir spielen will? Eine Person reicht nicht zum Töten!"
  },
  AvgDialog_24297_Content_7 = {
    Text = "Eingeschüchtert vom Schrecken des Riesen kauerten die Krieger wie junge Welpen, keiner wagte es, in den verbotenen Bogen vor ihnen zu treten, als wäre es ein Tabuort."
  },
  AvgDialog_24297_Content_8 = {
    Text = "Ein Haufen Taugenichtse! Mit solch schweren Verletzungen ist er nicht mehr der einst dominierende Herrscher der Meere."
  },
  AvgDialog_24297_Content_9 = {
    Text = "Ich, der Krieger Glen, schwöre bei meinem Leben: Wer mir diesen Kopf bringt, dem gehören mein Reichtum, mein Land und meine Frauen!"
  },
  AvgDialog_24415_Content_1 = {
    Text = "Warte, Ramona!"
  },
  AvgDialog_24415_Content_10 = {
    Text = "Fräulein Ramona!"
  },
  AvgDialog_24415_Content_11 = {
    Text = "Aus deinem Blickwinkel konntest du nur sehen, wie Ramona leicht den Kopf neigte und etwas sagte, während Ogier bleich wurde und Doll stützte, während sie zurückwichen."
  },
  AvgDialog_24415_Content_12 = {
    Text = "Ramona schüttelte das schwarze Gespinst von der Schwertspitze und ging mit ausdruckslosem Gesicht auf den Uhrturm zu."
  },
  AvgDialog_24415_Content_13 = {
    Text = "Ramona, warte!"
  },
  AvgDialog_24415_Content_14 = {
    Text = "Das ist keine Erinnerung."
  },
  AvgDialog_24415_Content_15 = {
    Text = "Dies ist nicht einmal die Ramona, die du kennst."
  },
  AvgDialog_24415_Content_16 = {
    Text = "Kalt, rücksichtslos, einschüchternd—dein Partner ist nicht so."
  },
  AvgDialog_24415_Content_17 = {
    Text = "Sie wird nicht über die Körper ihrer ehemaligen Kameraden treten, wird Lotan nicht schädigen und deinen Ruf nicht ignorieren..."
  },
  AvgDialog_24415_Content_18 = {
    Text = "Ramona, Ramona!"
  },
  AvgDialog_24415_Content_19 = {
    Text = "Ihre Gestalt verblasst allmählich in der Ferne. Da es keine anderen Optionen gibt, können Sie nur Ihr Tempo erhöhen, um aufzuholen."
  },
  AvgDialog_24415_Content_3 = {
    Text = "Auf dem Schulplatz befindet sich der wahnsinnige Lotan auf einem Amoklauf.\nOgier gibt sein Bestes, um Puppe zu schützen, gefährlich nah am Scheitern."
  },
  AvgDialog_24415_Content_4 = {
    Text = "Bevor du aufholen kannst, hebt Ramona ihr Rapier und sticht gnadenlos in Richtung Lotans Gesicht."
  },
  AvgDialog_24415_Content_5 = {
    Text = "Ramona, Gefahr—"
  },
  AvgDialog_24415_Content_6 = {
    Text = "Als die Degenklinge sich Lotans Stirn näherte, entstand an der Spitze ein Hohlraum, und Lotans wütender Ausdruck erlosch für einen Moment."
  },
  AvgDialog_24415_Content_7 = {
    Text = "Im nächsten Moment zersplitterte Lotans Silber mit einem Blitz."
  },
  AvgDialog_24415_Content_8 = {
    Text = "Das... kann nicht... sein..."
  },
  AvgDialog_24415_Content_9 = {
    Text = "Die Degen wurde gnadenlos gezogen, die scharfe Spitze zog eine erschreckende Linie, die fast Ogier in der Nähe streifte."
  },
  AvgDialog_24422_Content_1 = {
    Text = "<Gray:Der verstorbene Senior, der Schulfriedhof... Das sollte Ramonás Erinnerung an den Schlüsselzeremonie-Tag sein.>"
  },
  AvgDialog_24422_Content_2 = {
    Text = "<Gray: Aber ich erinnere mich, damals...>"
  },
  AvgDialog_24422_Content_3 = {
    Text = "Vielen Dank, Hüter. Du hast mich erneut gerettet.\nWenn es nicht für diese Verknüpfung wäre, wäre ich wahrscheinlich jetzt in großer Gefahr."
  },
  AvgDialog_24422_Content_4 = {
    Text = "Das Herauszögern ist nachteilig; wir müssen dies schnell zu Ende bringen."
  },
  AvgDialog_24422_Content_5 = {
    Text = "Verzeih, es bleibt keine Zeit, dich einzugewöhnen."
  },
  AvgDialog_24422_Content_6 = {
    Text = "<Gray:Wessen Erinnerung ist das? Diese Ramona, was zum Teufel...>"
  },
  AvgDialog_24422_Content_7 = {
    Text = "<Gray:Nein, wir müssen sie sofort einholen.>"
  },
  AvgDialog_25177_Content_1 = {
    Text = "Tawils Zustand hat sich erholt?! Wie ist das möglich?"
  },
  AvgDialog_25177_Content_2 = {
    Text = "In meiner Erinnerung an diesen Kampf hat es solche Fähigkeiten nicht gezeigt."
  },
  AvgDialog_25177_Content_3 = {
    Text = "Nein... definitiv nicht."
  },
  AvgDialog_25177_Content_4 = {
    Text = "Oder vielmehr hat es nie existiert."
  },
  AvgDialog_25177_Content_5 = {
    Text = "Ramona senkte den Kopf und blickte auf den silbernen Schlüssel an deiner Brust, murmelt."
  },
  AvgDialog_25177_Content_6 = {
    Text = "Die einzige Variable... Es stellt sich heraus..."
  },
  AvgDialog_25177_Content_7 = {
    Text = "Ramona verbarg ihren Schock und richtete erneut ihr Schwert auf Tawil."
  },
  AvgDialog_25177_Content_8 = {
    Text = "Fahre fort, Befehle zu erteilen und bringe dies zu einem Ende...\nDer Hüter."
  },
  AvgDialog_25186_Content_1 = {Text = "Piper"},
  AvgDialog_25186_Content_10 = {
    Text = "Habt keine Angst. Ich werde einen Weg finden, euch hier rauszuholen."
  },
  AvgDialog_25186_Content_11 = {
    Text = "Die Dorfbewohner starren nur schweigend zurück. Es gibt keine Hoffnung in ihren Augen—aber auch keine Feindseligkeit."
  },
  AvgDialog_25186_Content_12 = {
    Text = "Warte, die Magd..."
  },
  AvgDialog_25186_Content_13 = {
    Text = "Mein Vater und mein Bruder sind dort unten eingesperrt. Ich muss sie retten —"
  },
  AvgDialog_25186_Content_14 = {
    Text = "Kennt jemand von euch eine Magd namens Susanna?"
  },
  AvgDialog_25186_Content_15 = {
    Text = "Susanna? Das ist meine große Schwester!"
  },
  AvgDialog_25186_Content_16 = {
    Text = "Eine klare Kinderstimme kommt aus der Ecke."
  },
  AvgDialog_25186_Content_17 = {
    Text = "Beim flackernden Licht einer einzelnen Kerze bemerkst du einen alten Mann, der im Schatten liegt, und einen Jungen mit weit aufgerissenen Augen, der sich an ihn schmiegt."
  },
  AvgDialog_25186_Content_18 = {
    Text = "Susanna ist meine Tochter... Ist ihr etwas zugestoßen?"
  },
  AvgDialog_25186_Content_19 = {
    Text = "Sie macht sich große Sorgen um Euch. Sie hat versucht, einen Weg zu finden, Euch zu retten."
  },
  AvgDialog_25186_Content_2 = {
    Text = "Kambrische Burg\nUnterirdisches Gefängnis"
  },
  AvgDialog_25186_Content_20 = {
    Text = "Wir können diesen Ort nicht verlassen..."
  },
  AvgDialog_25186_Content_21 = {
    Text = "Der alte Mann war mit Auflösungs-Löchern übersät, aus denen schwarze Flüssigkeit quoll und den Strohboden unter ihm verschmutzte."
  },
  AvgDialog_25186_Content_22 = {
    Text = "Wir sind aus freiem Willen hier geblieben. Sobald die Krankheit einen erfasst, verliert man den Verstand... man wird zu einem Monster."
  },
  AvgDialog_25186_Content_23 = {
    Text = "Es stimmt. Es gab so viele Morde in der Umgebung... Dann kam die Herrin von Haus zu Haus. Sie sammelte die Kranken ein und brachte uns hierher."
  },
  AvgDialog_25186_Content_24 = {
    Text = "Wenn jemand nicht in Quarantäne wollte, ließ sie ihn das Lehen verlassen – solange er schwor, niemals zurückzukehren."
  },
  AvgDialog_25186_Content_25 = {
    Text = "Aber hier bekommen wir jeden Tag Brei und süßes Brot!"
  },
  AvgDialog_25186_Content_26 = {
    Text = "<Gray:Verstehe. Haben wir sie völlig falsch eingeschätzt?>"
  },
  AvgDialog_25186_Content_27 = {
    Text = "Hat Lady Wanda Euch gut behandelt, seit sie das Lehen übernommen hat?"
  },
  AvgDialog_25186_Content_28 = {
    Text = "Gut? Ich weiß nicht. Ich habe sie nie persönlich gesehen. Ich kenne nur die Geschichten – dass sie grausam ist, dass sie ihre vier Ehemänner getötet hat, dass sie ein Teufel in Menschengestalt ist."
  },
  AvgDialog_25186_Content_29 = {
    Text = "Aber seit sie hier ist, hat sie viel Gutes getan. Das Leben ist viel besser als früher."
  },
  AvgDialog_25186_Content_3 = {
    Text = "Die schwere Eisentür schließt sich hinter dir."
  },
  AvgDialog_25186_Content_30 = {
    Text = "Sie lehrte uns, zu pflanzen und Schafe zu hüten. Jedes Jahr während des Festes bringen wir die Wolle zum <Blue:Shariki> Markt und verdienen eine große Summe Geld."
  },
  AvgDialog_25186_Content_31 = {
    Text = "Das ist richtig, der Sharich-Markt wurde von ihr von Earl Goodrich erobert. Sie kämpfen seit fast einem Jahr darum..."
  },
  AvgDialog_25186_Content_32 = {
    Text = "Die Dorfbewohner reden alle gleichzeitig los und erzählen Geschichten über Wandas Verwaltung: Ackerbau, Schmelzen, Viehzucht, Lehensrecht..."
  },
  AvgDialog_25186_Content_33 = {
    Text = "Du bist verblüfft, wie tief Wanda in jeden Aspekt des Lehens eingebunden ist. Sie ist gewiss keine müßige, vergnügungssüchtige Adlige."
  },
  AvgDialog_25186_Content_34 = {
    Text = "Sie ist eine gute Herrscherin. Es ist nur eine Tragödie, dass die Auflösung sie gefunden hat."
  },
  AvgDialog_25186_Content_35 = {
    Text = "<Gray:Eine Ausbreitung dieses Ausmaßes... es muss ein Fusionsriss in der Nähe sein.>"
  },
  AvgDialog_25186_Content_36 = {
    Text = "Die eiserne Tür hinter dir öffnet sich plötzlich mit einem Knarren."
  },
  AvgDialog_25186_Content_37 = {
    Text = "Wanda stand vor den Gefängnistoren, ihre Silhouette in warmes Kerzenlicht getaucht."
  },
  AvgDialog_25186_Content_38 = {
    Text = "Lass diesen Kerl frei. Ich muss alleine mit ihm sprechen."
  },
  AvgDialog_25186_Content_39 = {
    Text = [[
Cambrian Castle
Garten]]
  },
  AvgDialog_25186_Content_4 = {
    Text = "Du drehst dich um und begegnest unerwartet paarweise leuchtenden Augen, die dich wie Tiere in der Dunkelheit umgeben."
  },
  AvgDialog_25186_Content_40 = {
    Text = "Ihr spaziert gemeinsam über weiches Gras bis zum Seeufer"
  },
  AvgDialog_25186_Content_41 = {
    Text = "Der nächtliche See ist ein schwarzer Spiegel, der das zerbrochene Mondlicht schwach reflektiert"
  },
  AvgDialog_25186_Content_42 = {
    Text = "Ich denke, du solltest verstehen: Cambrian steht jetzt vor einer schweren Katastrophe, und ich bin machtlos, etwas dagegen zu tun."
  },
  AvgDialog_25186_Content_43 = {
    Text = "Und du, du hast mit diesen Monstern im Schloss wie ein erfahrener Experte umgegangen."
  },
  AvgDialog_25186_Content_44 = {
    Text = "<Gray:Schließlich ist das mein Beruf...>"
  },
  AvgDialog_25186_Content_45 = {
    Text = "War die Frau nicht im Schlafgemach, wie kann sie das so genau wissen?"
  },
  AvgDialog_25186_Content_46 = {
    Text = "Meine Augen und Ohren sind überall in Cambrian, selbst die Freesien hier brauchen meine Erlaubnis zum Blühen, es gibt nichts, was ich nicht weiß"
  },
  AvgDialog_25186_Content_47 = {
    Text = "Und die Zofe? Warum behältst du sie, obwohl du weißt, dass sie eine Spionin ist?"
  },
  AvgDialog_25186_Content_48 = {
    Text = "Wanda winkte gleichgültig ab"
  },
  AvgDialog_25186_Content_49 = {
    Text = "Sie ist nur ein armes, gewöhnliches Menschlein, sie kann mir kein Haar krümmen"
  },
  AvgDialog_25186_Content_5 = {
    Text = "<Shake:Woaaahhh!!>"
  },
  AvgDialog_25186_Content_50 = {
    Text = "Außerdem hat sie mich recht gut bedient, einen passenden menschlichen Diener zu finden, ist nicht einfach"
  },
  AvgDialog_25186_Content_51 = {
    Text = "Also, ich hoffe, du kannst mir bei der Korrosion helfen. Lehn mich nicht sofort ab – der Preis ist verhandelbar, ich werde mein Bestes tun, um deine Wünsche zu erfüllen"
  },
  AvgDialog_25186_Content_52 = {
    Text = "Du kannst es nicht ertragen, diese Dorfbewohner unschuldig sterben zu sehen, oder, lieber „Mönch“?"
  },
  AvgDialog_25186_Content_53 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_25186_Content_54 = {
    Text = "\"Ihr Menschen\"... und diese seltsamen Wirbelstacheln... Frau Wanda, du bist kein Mensch, oder?"
  },
  AvgDialog_25186_Content_55 = {
    Text = "Ein Wesen aus einem fernen Land, das sich um das Leben schwacher Dorfbewohner kümmert. Was ist das wahre Ziel der Dame?"
  },
  AvgDialog_25186_Content_56 = {
    Text = "Angesichts deiner Fragen hob Wanda die Augenbrauen und begann plötzlich zu lachen"
  },
  AvgDialog_25186_Content_57 = {
    Text = "War das, was ich gerade gesagt habe, so lustig?"
  },
  AvgDialog_25186_Content_58 = {
    Text = "Nein... Hahaha! Ich bin einfach so glücklich. In all den Jahren, die ich hier verbracht habe, habe ich endlich jemanden getroffen, der auch nicht „hierher“ gehört—genau wie ich."
  },
  AvgDialog_25186_Content_59 = {
    Text = "Woher hast du—"
  },
  AvgDialog_25186_Content_6 = {
    Text = "Als sich deine Augen an die Düsternis gewöhnen, erkennst du endlich die Wirklichkeit der Zelle."
  },
  AvgDialog_25186_Content_60 = {
    Text = "Wanda legt einen schlanken Finger sanft auf deine Lippen."
  },
  AvgDialog_25186_Content_61 = {
    Text = "Shh... Folge mir. Ich möchte dir etwas zeigen."
  },
  AvgDialog_25186_Content_62 = {
    Text = "Du machst dich durch die Wälder auf und erreichst den ruhigen Rand des Sees."
  },
  AvgDialog_25186_Content_63 = {
    Text = "Manchmal habe ich diese wunderbaren Illusionen... als ob ich die Stadt, in der ich einmal lebte, in diesem See gespiegelt sehen könnte."
  },
  AvgDialog_25186_Content_64 = {
    Text = "Eine riesige Stadt, die aus schwarzen Monolithen besteht, deren Grenzen ständig wachsen und schließlich bis zu unsichtbaren Horizonten reichen..."
  },
  AvgDialog_25186_Content_65 = {
    Text = "Der tiefblaue See ist fast unermesslich. Während du Wandas Beschreibung lauscht, scheint das Bild der Stadt vor deinen Augen Gestalt anzunehmen."
  },
  AvgDialog_25186_Content_66 = {
    Text = "Schwarze spiralförmige Türme, unheimliche stumpfe Wände..."
  },
  AvgDialog_25186_Content_67 = {
    Text = "Damals hatte ich einen prächtigen Palast. Über tausend Diener kümmerten sich um jedes meiner Bedürfnisse."
  },
  AvgDialog_25186_Content_68 = {
    Text = "So wie du gesagt hast, lag mir das Leben dieser Untergebenen nie am Herzen."
  },
  AvgDialog_25186_Content_69 = {
    Text = "Ich tat genau, was mir gefiel. Meine Diener, meine Stadt... sie waren alle einfach Ausdruck meines Willens und meines Ehrgeizes."
  },
  AvgDialog_25186_Content_7 = {
    Text = "Sitzend, liegend oder an die kalten Steinwände gelehnt—der Raum ist vollgepackt mit zerlumpten Dorfbewohnern."
  },
  AvgDialog_25186_Content_70 = {
    Text = "Dann wurde mein Planet von der Katastrophe heimgesucht, die ihr das „Schmelzen“ nennt. Alle starben."
  },
  AvgDialog_25186_Content_71 = {
    Text = "Ich saß allein in jenem Saal für eine lange, lange Zeit und sah zu, wie mein Palast und meine Hauptstadt zu Asche zerfielen."
  },
  AvgDialog_25186_Content_72 = {
    Text = "Ehrlich gesagt war es ein schreckliches Gefühl. Niemand möchte das zweimal erleben."
  },
  AvgDialog_25186_Content_73 = {
    Text = "Frau Wanda... Es tut mir leid, aber ich kann Ihnen diesmal nicht helfen."
  },
  AvgDialog_25186_Content_74 = {
    Text = "Mach dir darüber keine Sorgen. Sag mir, was dich zurückhält, und ich werde dir alles bereitstellen, was du brauchst."
  },
  AvgDialog_25186_Content_75 = {
    Text = "Du schüttelst den Kopf."
  },
  AvgDialog_25186_Content_76 = {
    Text = "Es ist mehr als das. Unsere derzeitige Umgebung... sie hat einige... Besonderheiten."
  },
  AvgDialog_25186_Content_77 = {
    Text = "Im Traumzustand kannst du den D-Riss nicht schließen."
  },
  AvgDialog_25186_Content_78 = {
    Text = "<Gray:Wie soll ich ihr das überhaupt erklären?>"
  },
  AvgDialog_25186_Content_79 = {
    Text = "Weil wir uns in einem Traum befinden, kannst du mir nicht helfen... ist es das?"
  },
  AvgDialog_25186_Content_8 = {
    Text = "Ihre Haut ist übersät mit Auflösungsnarben; einige haben bereits die Hälfte ihres Körpers an die Fäulnis verloren. Die Luft ist schwer vom Gestank der Krankheit und des nahenden Todes."
  },
  AvgDialog_25186_Content_80 = {Text = "?!"},
  AvgDialog_25186_Content_81 = {
    Text = "Du... du hast es bemerkt?"
  },
  AvgDialog_25186_Content_82 = {
    Text = "Wanda blickt hinab auf die schwarze Stadt im Wasser, ihre Augen schimmern im gebrochenen weißen Mondlicht."
  },
  AvgDialog_25186_Content_83 = {
    Text = "Seit ich hierher gekommen bin, hatte ich viele Träume. Über Krieg, Katastrophen, Zeit... aber niemals über mein Kapital."
  },
  AvgDialog_25186_Content_84 = {
    Text = "Gerade als ich dabei war, es zu vergessen, traf ich dich und sah es dann wieder am Grund des Sees."
  },
  AvgDialog_25186_Content_85 = {
    Text = "Wusstest du? Wenn ein Sterbender den Pfeifer durch den Nebel wandeln sieht, empfindet er weder Furcht noch Neugier."
  },
  AvgDialog_25186_Content_86 = {
    Text = "Er folgt dem Pfeifer einfach schweigend, zu einem Ort, der ihm gehört."
  },
  AvgDialog_25186_Content_87 = {
    Text = "Wanda ließ einen leisen Seufzer hören."
  },
  AvgDialog_25186_Content_88 = {
    Text = "Meine verlorene Hauptstadt... sie ist wunderschön, wie der Traum eines Sterbenden."
  },
  AvgDialog_25186_Content_89 = {
    Text = "Sie streichelt sanft den stillen, blinden Begleiter an ihrer Seite."
  },
  AvgDialog_25186_Content_9 = {
    Text = "Wanda hat euch tatsächlich alle hier eingesperrt..."
  },
  AvgDialog_25186_Content_90 = {
    Text = "<Change>Meine Lady..."
  },
  AvgDialog_25186_Content_91 = {
    Text = "Cambrian ist mein zweites Zuhause. Ich habe hier nicht viel Zeit verbracht, und doch ist es bereits Zeit, Abschied zu nehmen."
  },
  AvgDialog_25186_Content_92 = {
    Text = "Es tut mir leid, Lady Wanda..."
  },
  AvgDialog_25186_Content_93 = {
    Text = "Wanda winkt abwehrend ab. Als sie wieder aufblickt, ist die Schwermut aus ihrem Gesicht verschwunden."
  },
  AvgDialog_25186_Content_94 = {
    Text = "Keine Sorge. Da ich mich entschieden habe, die Herrin dieses Lehens zu sein, muss ich die Verantwortung für alle übernehmen."
  },
  AvgDialog_25186_Content_95 = {
    Text = "Es geht einfach ums gemeinsame Sterben? Dann lasst uns ruhmvoll sterben."
  },
  AvgDialog_25186_Content_96 = {
    Text = "Was hast du vor?"
  },
  AvgDialog_25186_Content_97 = {
    Text = "Wanda schenkt dir ein geheimnisvolles Lächeln und zwinkert dir zu."
  },
  AvgDialog_25186_Content_98 = {
    Text = "Ein prächtiges Abschiedsbankett."
  },
  AvgDialog_25187_Content_1 = {
    Text = "Vier Hochzeiten"
  },
  AvgDialog_25187_Content_10 = {
    Text = "Schließlich folgst du dicht hinter der Dienerin, und nimmst ständig einen starken Puderduft von dir wahr."
  },
  AvgDialog_25187_Content_11 = {
    Text = "Das ist ein typisches Schloss aus früheren Zeiten, mit Wänden aus dicken Ziegeln, die potenzielle Feindangriffe abwehren sollen."
  },
  AvgDialog_25187_Content_12 = {
    Text = "Sieht etwas zugig aus. Es muss im Winter wirklich kalt sein."
  },
  AvgDialog_25187_Content_13 = {
    Text = "Huh, was ist das...?"
  },
  AvgDialog_25187_Content_14 = {
    Text = "Schwarzer D-Schleim sickert langsam aus den Ritzen der Ziegelwand."
  },
  AvgDialog_25187_Content_15 = {
    Text = "Sie sammeln sich still, bis sie Gestalt annehmen."
  },
  AvgDialog_25187_Content_16 = {
    Text = "Brüll—!!"
  },
  AvgDialog_25187_Content_17 = {
    Text = "<Shake:Hast du das gespürt? Etwas ist in der Nähe...>"
  },
  AvgDialog_25187_Content_18 = {
    Text = "Sie kommen... die Monster sind zurück!"
  },
  AvgDialog_25187_Content_19 = {
    Text = "Steh hinter mir."
  },
  AvgDialog_25187_Content_2 = {Text = "Platsch—"},
  AvgDialog_25187_Content_20 = {
    Text = "Aber du bist nicht..."
  },
  AvgDialog_25187_Content_21 = {
    Text = "Die Dienstmagd betrachtet die schweren Ketten an deinen Händen und Füßen mit Verdacht."
  },
  AvgDialog_25187_Content_22 = {
    Text = "Du schließt deine Augen und fängst schwache Verbindungen zu anderen Erwachten tief in deinem Bewusstsein ein."
  },
  AvgDialog_25187_Content_23 = {
    Text = "Obwohl während des Traums durch schwache Geisterkraft eingeschränkt, ist die Fähigkeit des Erwachenden, den du beschwörst, gering, aber—"
  },
  AvgDialog_25187_Content_24 = {
    Text = "Das reicht aus, um mit euch fertig zu werden."
  },
  AvgDialog_25187_Content_3 = {
    Text = "Kaltes Wasser strömt über deinen Kopf."
  },
  AvgDialog_25187_Content_4 = {
    Text = "Ein dumpfer Schmerz pocht in deiner Brust, als jemand deiner Wunde zwei harte Tritte versetzt."
  },
  AvgDialog_25187_Content_5 = {
    Text = "Ugh! Husten, husten..."
  },
  AvgDialog_25187_Content_6 = {
    Text = "<Change> Kümmere dich um die Gemahlin. Kümmere dich um die Gemahlin."
  },
  AvgDialog_25187_Content_7 = {
    Text = "Wie oft bin ich durch Wasser aufweckt worden..."
  },
  AvgDialog_25187_Content_8 = {
    Text = "Du seufztest und ließest die Diener dich hinaustragen."
  },
  AvgDialog_25187_Content_9 = {
    Text = "Baden, Ankleiden und Schminken..."
  },
  AvgDialog_25188_Content_1 = {
    Text = [[
Kambrium Schloss  
Wandas Schlafgemach]]
  },
  AvgDialog_25188_Content_10 = {
    Text = "Entschuldigung... Ich verstehe nicht, was Sie meinen, Mrs. Wanda."
  },
  AvgDialog_25188_Content_11 = {
    Text = "Oh? Ihr Gesichtsausdruck sagt etwas anderes."
  },
  AvgDialog_25188_Content_12 = {
    Text = "Wanda hob ihren Kinn und deutete auf den nebenliegenden Ring."
  },
  AvgDialog_25188_Content_13 = {
    Text = "Dieser Ring war ein Geschenk von meinem <Blue:vierten Ehemann>. Weißt du, warum er später verschwunden ist?"
  },
  AvgDialog_25188_Content_14 = {
    Text = "<Shake:N-nein, nicht ganz sicher...>"
  },
  AvgDialog_25188_Content_15 = {
    Text = "Er wurde einst \"Der Goldene Besen von Cambrian\" genannt, ein erstklassiger Ritter."
  },
  AvgDialog_25188_Content_16 = {
    Text = "Später verschwörerisch er mit anderen Lords, um mich zu stürzen und vergiftete sogar meinen Wein und mein Essen."
  },
  AvgDialog_25188_Content_17 = {
    Text = "Schade, er kann niemanden mehr vergiften..."
  },
  AvgDialog_25188_Content_18 = {
    Text = "Wanda streichelte sanft die kalte Wange eines Dieners, ihre Augen waren voller tiefer Emotionen."
  },
  AvgDialog_25188_Content_19 = {
    Text = "Liege ich richtig, mein lieber Ehemann?"
  },
  AvgDialog_25188_Content_2 = {
    Text = "Mr. Wayne, Sie sind endlich angekommen. Kommen Sie her und helfen Sie mir, den Ring abzunehmen."
  },
  AvgDialog_25188_Content_20 = {
    Text = "<Change>Madame, Liebe..."
  },
  AvgDialog_25188_Content_21 = {
    Text = "Der blinde Diener lehnte sanft gegen Wanda und schien ihre Berührung zu genießen."
  },
  AvgDialog_25188_Content_22 = {
    Text = "?! Du hast das tatsächlich deinem Ehemann angetan..."
  },
  AvgDialog_25188_Content_23 = {
    Text = "In Ordnung, meine Gute-Nacht-Geschichte ist zu Ende. Jetzt bist du an der Reihe, kleiner Mönch."
  },
  AvgDialog_25188_Content_24 = {
    Text = "Denke sorgfältig nach. Gibt es wirklich nichts, was du mir sagen möchtest?"
  },
  AvgDialog_25188_Content_25 = {
    Text = "Wandas Lächeln verblasst, als sie dich mit einem ausdruckslosen Gesichtsausdruck ansieht. Eine mächtige Aura umgibt sie und macht dich fast erdrückend."
  },
  AvgDialog_25188_Content_26 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_25188_Content_27 = {
    Text = "An diesem Punkt ist jede Verkleidung vergeblich. Du hast die Notiz aus deiner Tasche genommen und sie Wanda übergeben."
  },
  AvgDialog_25188_Content_28 = {
    Text = "Frau Wanda, ich denke, ich kann es erklären! Es war nicht meine Initiative!"
  },
  AvgDialog_25188_Content_29 = {
    Text = "Du warst es, der ihm den Zettel übergeben hat, oder?"
  },
  AvgDialog_25188_Content_3 = {
    Text = "Wanda sitzt vor dem großen Schminkspiegel und streckt ihre schlanken Finger, die mit opulenten Ringen geschmückt sind, in deine Richtung aus."
  },
  AvgDialog_25188_Content_30 = {
    Text = "Wanda hob leicht ihre Augenlider und schielte zu der Dienstmagd neben ihr."
  },
  AvgDialog_25188_Content_31 = {
    Text = "Nicht schlecht... Ich bin diejenige, die die Notiz hinterlassen hat."
  },
  AvgDialog_25188_Content_32 = {
    Text = "Die Dienstmagd senkte den Kopf, zitterte am ganzen Körper. Dann atmete sie tief ein und richtete ihren Rücken auf."
  },
  AvgDialog_25188_Content_33 = {
    Text = "Du Dämon, du abscheulicher Dämon!"
  },
  AvgDialog_25188_Content_34 = {
    Text = "Mein Vater und mein jüngerer Bruder sind beide unten eingesperrt. Ich muss sie retten—"
  },
  AvgDialog_25188_Content_35 = {Text = "Boom—!"},
  AvgDialog_25188_Content_36 = {
    Text = "Scharfe Rückennadeln erscheinen aus dem Boden und umzingeln die Maid."
  },
  AvgDialog_25188_Content_37 = {
    Text = "Ich habe kein Interesse an deiner tragischen Geschichte. Wächter, werft sie raus."
  },
  AvgDialog_25188_Content_38 = {
    Text = "Madame Wanda, sie ist nur das unbedeutendste Stück in diesem Spiel. Bitte töte nicht willkürlich..."
  },
  AvgDialog_25188_Content_39 = {
    Text = "Bevor du deinen Satz beenden konntest, griff Wanda fest nach deinem Hals und hob dich auf ihre Augenhöhe."
  },
  AvgDialog_25188_Content_4 = {
    Text = "Der blinde, zerlegte Diener stand wie ein Geist hinter ihr und verharrte schweigend im Mondlicht."
  },
  AvgDialog_25188_Content_40 = {
    Text = "Du darfst nur sprechen, wenn ich dir sage, dass du es tun sollst. Verstehst du?"
  },
  AvgDialog_25188_Content_41 = {
    Text = "<Shake:Husten husten... Uh...>"
  },
  AvgDialog_25188_Content_42 = {
    Text = "Du, tust immer noch so, als wärst du ein Mönch? Kommst vor mich und tust so, als wärst du ein Heiliger?"
  },
  AvgDialog_25188_Content_43 = {Text = "?!"},
  AvgDialog_25188_Content_44 = {
    Text = "Wie weißt du...?"
  },
  AvgDialog_25188_Content_45 = {
    Text = "Wanda lässt dich los, und du fällst zu Boden. Sie schlägt gemächlich ihre Beine übereinander und genießt den Anblick, wie du hustest."
  },
  AvgDialog_25188_Content_46 = {
    Text = "Ich habe mich schon lange von deinen menschlichen Tricks gelangweilt. Du bist definitiv nicht Vayne @2."
  },
  AvgDialog_25188_Content_47 = {
    Text = "Wirf ihn ins Gefängnis und lass ihn nicht raus, bis er die Wahrheit sagt."
  },
  AvgDialog_25188_Content_48 = {
    Text = "<Change> Wie du wünschst!"
  },
  AvgDialog_25188_Content_5 = {
    Text = "Du trittst schwer vor sie, senkst den Kopf, um jeden Ring zu entfernen, aber dein Geist driftet ständig zu diesem Zettel."
  },
  AvgDialog_25188_Content_6 = {
    Text = "<Gray:Wo ist dieser \"gewöhnliche Ort\"...>"
  },
  AvgDialog_25188_Content_7 = {
    Text = "Was ist los? Du scheinst mir etwas sagen zu wollen."
  },
  AvgDialog_25188_Content_8 = {Text = "?!"},
  AvgDialog_25188_Content_9 = {
    Text = "Mit einem Schwung deines Handgelenks fiel der Katzenaugenring zu Boden und rollte an die Bettkante."
  },
  AvgDialog_25189_Content_1 = {
    Text = "Verstoßene Königin"
  },
  AvgDialog_25189_Content_10 = {
    Text = "Immer noch nicht wach? Lass uns ihm helfen, sich ein wenig abzukühlen."
  },
  AvgDialog_25189_Content_11 = {Text = "Hmm...!!"},
  AvgDialog_25189_Content_12 = {
    Text = "Ein kalter Schauer läuft durch meine Brust."
  },
  AvgDialog_25189_Content_13 = {
    Text = "<Change>Immer noch keine Antwort... Meine Dame..."
  },
  AvgDialog_25189_Content_14 = {
    Text = "Dann schneide es ab und mach es sauber."
  },
  AvgDialog_25189_Content_15 = {Text = "!!"},
  AvgDialog_25189_Content_16 = {
    Text = "<Big:Schnitt, was schneiden?!>"
  },
  AvgDialog_25189_Content_17 = {
    Text = "Du bist an einen kalten Tisch gefesselt, mit einer schweren Guillotine, die nur 10 Zoll über deinem Oberschenkel schwebt, bereit zu fallen—"
  },
  AvgDialog_25189_Content_18 = {
    Text = "Moment... <Big: Zischen!>"
  },
  AvgDialog_25189_Content_19 = {
    Text = "Ein scharfer Schmerz strahlt von deiner Brust aus. Dein Gewand ist zerfetzt und zeigt zahlreiche grässliche Narben."
  },
  AvgDialog_25189_Content_2 = {
    Text = "Es war einmal..."
  },
  AvgDialog_25189_Content_20 = {
    Text = "Offensichtlich hat dieser Körper unmenschlichen Missbrauch erlitten."
  },
  AvgDialog_25189_Content_21 = {
    Text = "Du bist endlich wach."
  },
  AvgDialog_25189_Content_22 = {
    Text = "Eine sanfte, aber autoritäre weibliche Stimme hallte durch die geräumige Halle."
  },
  AvgDialog_25189_Content_23 = {
    Text = "Die edle Dame Wanda lehnt sich gegen ihre Zofe und squintet dich an."
  },
  AvgDialog_25189_Content_24 = {
    Text = "Was ist das?!"
  },
  AvgDialog_25189_Content_25 = {
    Text = "\"In der Lust schwelgen, den Begierden nachgeben...\""
  },
  AvgDialog_25189_Content_26 = {
    Text = "Was kommt als Nächstes? Sprich weiter, junger Mönch."
  },
  AvgDialog_25189_Content_27 = {Text = "...?"},
  AvgDialog_25189_Content_28 = {
    Text = "Was? Nach dem ununterbrochenen Rezitieren von Schriften am Stadttor für so lange Zeit kommst du rein und vergisst alles?"
  },
  AvgDialog_25189_Content_29 = {
    Text = "Am Stadttor, Schriften..."
  },
  AvgDialog_25189_Content_3 = {
    Text = "Sie herrscht über alles, was sie sieht."
  },
  AvgDialog_25189_Content_30 = {
    Text = "Nach brutalen Bestrafungen ist das Bewusstsein dieses Körpers in Chaos gefallen. Du konzentrierst dich und schaffst es, einige Erinnerungen zusammenzufügen."
  },
  AvgDialog_25189_Content_31 = {
    Text = "<Blue:Wayne·@2>, 23 Jahre alt, geboren im südlichen Shropshire, wurde vor drei Monaten Mönch im kambrianischen Bistum."
  },
  AvgDialog_25189_Content_32 = {
    Text = "Fromm und mitfühlend ist er tief betrübt über Wandas extravaganten und verschwenderischen Lebensstil. Jeden Morgen kommt er zum Schloss tor, um Schriften zu rezitieren."
  },
  AvgDialog_25189_Content_33 = {
    Text = "Bis er schließlich von den frustrierten Wachen hereingeholt wurde, hatte Vayne 23 Tage durchgehalten."
  },
  AvgDialog_25189_Content_34 = {
    Text = "In Lust schwelgen, den Wünschen nachgeben... Was folgt, ist..."
  },
  AvgDialog_25189_Content_35 = {
    Text = "Hmm. Scheint, als hätte er es wirklich vergessen? Dann lass uns ihn in zwei Hälften schneiden."
  },
  AvgDialog_25189_Content_36 = {
    Text = "Wanda gähnte und winkte faul mit der Hand."
  },
  AvgDialog_25189_Content_37 = {
    Text = "Freigabe—"
  },
  AvgDialog_25189_Content_38 = {
    Text = "Die Folterbank knarrte, als sie sich drehte, und die Guillotine fiel schnell. Der kalte Wind, den sie aufwirbelte, entzündete schnell deinen Überlebensinstinkt."
  },
  AvgDialog_25189_Content_39 = {
    Text = "Warte, warte! Ich habe gerade etwas erinnert!"
  },
  AvgDialog_25189_Content_4 = {
    Text = "Nachts saß sie allein auf der hohen Terrasse und beobachtete die langsam rotierenden Planeten um sich herum."
  },
  AvgDialog_25189_Content_40 = {
    Text = "<Shake:Wenn du irgendwelchen Strafen ausgesetzt bist, wie ein Spiegel, ein Spiegel...>"
  },
  AvgDialog_25189_Content_41 = {
    Text = "<Gray:Verdammtes, wenn ich doch nur Ramonas Gedächtnis hätte.>"
  },
  AvgDialog_25189_Content_42 = {
    Text = "<Change> Madame, ein Spion..."
  },
  AvgDialog_25189_Content_43 = {
    Text = "Der Hals des stummen Bediensteten zuckte und gab ein trübes Gurgeln von sich."
  },
  AvgDialog_25189_Content_44 = {
    Text = "Oh? Erzähl mir mehr."
  },
  AvgDialog_25189_Content_45 = {
    Text = "<Change> Diözese, Schrift."
  },
  AvgDialog_25189_Content_46 = {
    Text = "Ich verstehe..."
  },
  AvgDialog_25189_Content_47 = {
    Text = "Mein kleines Haustier sagt mir, dass du anscheinend ein Spion bist. Als Mönch, der von der Pfarrei stationiert ist, kannst du dich nicht einmal an die grundlegenden Schriften erinnern."
  },
  AvgDialog_25189_Content_48 = {Text = "Aber —"},
  AvgDialog_25189_Content_49 = {Text = "WUMM!!"},
  AvgDialog_25189_Content_5 = {
    Text = "Sie kann singen, mit sich selbst sprechen und manchmal einschlafen, ohne es zu merken."
  },
  AvgDialog_25189_Content_50 = {
    Text = "Die starre Wirbelsäulen-Nadel schoss nach oben und erreichte den Hals des blinden Dieners. Wanda hob ihre Augenlider und warf ihm einen kalten Blick."
  },
  AvgDialog_25189_Content_51 = {
    Text = "Du darfst nur sprechen, wenn ich dir erlaube, es zu tun. Wenn ich es nicht tue, bleibe still. Verstehst du?"
  },
  AvgDialog_25189_Content_52 = {
    Text = "<Change>Verstanden. Ich werde gehorchen."
  },
  AvgDialog_25189_Content_53 = {
    Text = "Der blinde Diener fiel sofort in Schweigen und zog sich zurück in die Schatten der Ecke."
  },
  AvgDialog_25189_Content_54 = {
    Text = "Der einst laute Saal verstummte, so still, dass man nicht einmal das Geräusch einer fallenden Nadel hören konnte."
  },
  AvgDialog_25189_Content_55 = {
    Text = "Wanda nähert sich dir mit einem Weinglas in der Hand, ihre Schritte sind sowohl anmutig als auch kraftvoll."
  },
  AvgDialog_25189_Content_56 = {
    Text = "Ihre Hand streckte sich aus, lange Nägel streiften über deine Brust, verweilten an deinem zerbrechlichen Hals."
  },
  AvgDialog_25189_Content_57 = {
    Text = "Er hat gerade gesagt, dass du ein Spion bist. <Red:Also... bist du das?>"
  },
  AvgDialog_25189_Content_58 = {
    Text = "Wanda verengte ihre kobaltblauen Augen und verbarg einen Hauch von Grausamkeit und Brutalität, der nur kurzzeitig in ihrem Blick auftauchte."
  },
  AvgDialog_25189_Content_59 = {
    Text = "Wenn deine nächste Antwort sie nicht zufriedenstellt, werden ihre Nägel gnadenlos deinen Hals durchbohren."
  },
  AvgDialog_25189_Content_6 = {
    Text = "Sie handelt immer aus einem Impuls heraus.\nVor den Katastrophen war sie die Königin hier; nach den Katastrophen blieb nur sie."
  },
  AvgDialog_25189_Content_60 = {
    Text = "Du nimmst einen tiefen Atemzug und versuchst, Wandas Blick zu treffen."
  },
  AvgDialog_25189_Content_61 = {
    Text = "Wenn ich wirklich ein Spion wäre, hätte ich diese Identität nicht gewählt."
  },
  AvgDialog_25189_Content_62 = {
    Text = "Zuerst ist es zu auffällig und wird viel Aufmerksamkeit und Ärger auf sich ziehen."
  },
  AvgDialog_25189_Content_63 = {
    Text = "Zweitens, es ist zu gefährlich. In Cambria weiß jeder, dass Lady Wanda Mönche am meisten verachtet—ugh!"
  },
  AvgDialog_25189_Content_64 = {
    Text = "Die eisige Flüssigkeit fließt den Hals hinunter und sickert schnell in die Wunde."
  },
  AvgDialog_25189_Content_65 = {
    Text = "Wanda warf das leere Glas beiseite und lächelte dich an."
  },
  AvgDialog_25189_Content_66 = {
    Text = "Ich mag Mönche wirklich nicht. Und? Mach weiter, Mr. Vayne."
  },
  AvgDialog_25189_Content_67 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_25189_Content_68 = {
    Text = "<Shake:So tun, als wäre ich ein Mönch, der jeden Tag am Stadttor chanted... Ich könnte schon mehrere Male gestorben sein, bevor ich dich überhaupt getroffen habe...>"
  },
  AvgDialog_25189_Content_69 = {
    Text = "Wanda lacht herzlich, scheint mit deiner Antwort zufrieden zu sein."
  },
  AvgDialog_25189_Content_7 = {
    Text = "So kann sie immer tun, was sie will."
  },
  AvgDialog_25189_Content_70 = {
    Text = "Was für eine Überraschung, du bist nicht so stumpf und uninteressant, wie ich dachte."
  },
  AvgDialog_25189_Content_71 = {
    Text = "Ich mag kluge Menschen, aber ich bevorzuge diejenigen, die sowohl schlau als auch schön sind."
  },
  AvgDialog_25189_Content_72 = {
    Text = "Wanda streichelte sanft deine Wange und rief mit lauter Stimme die Bediensteten."
  },
  AvgDialog_25189_Content_73 = {
    Text = "Nehmt ihn weg, wascht ihn heute Nacht sauber und bringt ihn in meine Kammer."
  },
  AvgDialog_25189_Content_74 = {
    Text = "Die Schlafgemächer? Wozu...?"
  },
  AvgDialog_25189_Content_75 = {
    Text = "Niemand kümmert sich um deine Zweifel.\nWanda gähnte und ging großartig, umgeben von ihren Dienern."
  },
  AvgDialog_25189_Content_76 = {
    Text = "Als sie deinen verwirrten Ausdruck sah, konnte die neben dir stehende Dienerin nicht anders, als mit den Augen zu rollen."
  },
  AvgDialog_25189_Content_77 = {
    Text = "Weißt du das nicht? Du solltest nachts deinen Pflichten nachkommen. Das ist eine goldene Gelegenheit, von der viele träumen..."
  },
  AvgDialog_25189_Content_78 = {
    Text = "<Shake:Kümmere dich um mich im Bett?!>"
  },
  AvgDialog_25189_Content_79 = {
    Text = "Deine Sicht wird schwarz, und du fällst erneut in Ohnmacht."
  },
  AvgDialog_25189_Content_8 = {
    Text = "Ja, alles, was sie sah, war unter ihrer Kontrolle, aber all das ist längst zu kosmischem Staub verschwunden."
  },
  AvgDialog_25189_Content_9 = {
    Text = "Ist eine Königin ohne Untertanen immer noch eine Königin?\nWanda weiß es auch nicht."
  },
  AvgDialog_25190_Content_1 = {
    Text = "<Change>Brüll..."
  },
  AvgDialog_25190_Content_10 = {
    Text = [[
<Yellow:Treffen Sie sich am gewohnten Ort um 21 Uhr am 17.>@1 um wichtige Angelegenheiten zu besprechen.
Vorsicht vor @1 Frauen @2 und Dornen.

Ihr alter Freund,
Guderian]]
  },
  AvgDialog_25190_Content_11 = {
    Text = "<Gray:Über einen großen Plan sprechen? Welcher Plan?>"
  },
  AvgDialog_25190_Content_12 = {
    Text = "Mein kleines Haustier sagt mir, dass du anscheinend ein Spion bist. Als Mönch, der von der Pfarrei stationiert ist, kannst du dich nicht einmal an die grundlegenden Schriften erinnern."
  },
  AvgDialog_25190_Content_13 = {
    Text = "Könnte der Diener recht haben? Bin ich wirklich ein Spion?"
  },
  AvgDialog_25190_Content_14 = {
    Text = "Ich kann nicht glauben, dass es mir nicht gelungen ist, solch entscheidende Informationen aus seinem Gedächtnis zu extrahieren... Es scheint, als wäre er wirklich bis zur Besinnungslosigkeit gefoltert worden."
  },
  AvgDialog_25190_Content_15 = {
    Text = "Du hast die Notiz weggelegt, dein Geist wirbelte vor Gedanken."
  },
  AvgDialog_25190_Content_16 = {
    Text = "Worauf wartest du? Die Dame hat keine Geduld. Der letzte, der zu spät kam, ist schon seit zwei Jahren im Gefängnis."
  },
  AvgDialog_25190_Content_17 = {Text = "...Hey."},
  AvgDialog_25190_Content_18 = {
    Text = "Du näherst dich leise der Dienerin und hältst deine Stimme so tief wie möglich."
  },
  AvgDialog_25190_Content_19 = {
    Text = "<SmallShake:Bist du auch der Maulwurf von Graf Gudrian?>"
  },
  AvgDialog_25190_Content_2 = {
    Text = "Du hast die heranbrausenden Monster leicht zurückgeschlagen."
  },
  AvgDialog_25190_Content_20 = {
    Text = "Ähem! Woran murmelst du da? Beeil dich und beweg dich!"
  },
  AvgDialog_25190_Content_21 = {
    Text = "Die Dienstmagd murmelt Flüche vor sich hin, stiehlt aber gleichzeitig immer wieder neugierige Blicke zu dir, ihr Gesicht ist voller Eagern und subtiler Andeutungen."
  },
  AvgDialog_25190_Content_22 = {
    Text = "<Gray:Fräulein, das ist ein bisschen zu offensichtlich.>"
  },
  AvgDialog_25190_Content_23 = {
    Text = "Was nun tun? Den ursprünglichen Plan vollenden oder Wanda kapitulieren?"
  },
  AvgDialog_25190_Content_24 = {
    Text = "<Gray:Um ehrlich zu sein, bin ich wirklich neugierig auf den Plan des Grafen...>"
  },
  AvgDialog_25190_Content_3 = {
    Text = "<Gray:Der D-Schleim hat sich bis zur Burg ausgebreitet. Wie könnte Wanda davon nichts wissen?>"
  },
  AvgDialog_25190_Content_4 = {
    Text = "Wie erwartet, er ist derjenige, den der Graf als <Blue:\"diesen Gentleman\"> erwähnt hat."
  },
  AvgDialog_25190_Content_5 = {
    Text = "Wenn er es ist, kann er definitiv..."
  },
  AvgDialog_25190_Content_6 = {
    Text = "Plötzlich wurde ein Zettel in meine Hand geschoben."
  },
  AvgDialog_25190_Content_7 = {
    Text = "Du schaust auf. Die Dienstmagd, die hinter dir gekauert hatte, steht nun aufrecht, ihre kalte Arroganz ist zurückgekehrt."
  },
  AvgDialog_25190_Content_8 = {Text = "?"},
  AvgDialog_25190_Content_9 = {
    Text = "Du entfaltest die Notiz, die eine Reihe von gekritzelten Codes enthält. Mit Vaynes Gedächtnis gelingt es dir, ihren Inhalt gerade so zu übersetzen."
  },
  AvgDialog_25191_Content_1 = {
    Text = "Nacht des Todes, des Mets & der Lieder"
  },
  AvgDialog_25191_Content_10 = {
    Text = "Was diese Frau denkt, kann niemand erraten. Jedoch—"
  },
  AvgDialog_25191_Content_11 = {
    Text = "Die kambrische Seuche ist unheilbar. Wenn die Infizierten freigelassen werden, weiß der Himmel, was geschehen würde."
  },
  AvgDialog_25191_Content_12 = {
    Text = "Ungeachtet von Wandas Absichten haben ihre Handlungen in der Tat die umliegenden Lehen gerettet..."
  },
  AvgDialog_25191_Content_13 = {
    Text = [[
Kambrium Schloss
Festsaal]]
  },
  AvgDialog_25191_Content_14 = {
    Text = "Du drückst die schwere Holztür des Saales auf."
  },
  AvgDialog_25191_Content_15 = {
    Text = "Gleißendes Licht ergießt sich wie gefallene Sterne über den Raum. Die Luft ist erfüllt vom süßen Aroma von Wein und erlesenen Speisen."
  },
  AvgDialog_25191_Content_16 = {
    Text = "Die Bauern von Kambrisch haben ihre feinsten Kleider angelegt und tanzen fröhlich im Rhythmus der Musik."
  },
  AvgDialog_25191_Content_17 = {
    Text = "Obwohl die Welt draußen von der Auflösung verschlungen wird, ist der Saal voller Heiterkeit."
  },
  AvgDialog_25191_Content_18 = {
    Text = "Ist das der legendäre Apfelpudding? Ich habe in meinem ganzen Leben noch nie etwas so Köstliches geschmeckt..."
  },
  AvgDialog_25191_Content_19 = {
    Text = "Hahaha! Ich bin so glücklich! Wenn ich heute Nacht sterbe, hat sich alles gelohnt!"
  },
  AvgDialog_25191_Content_2 = {
    Text = [[
Guderian's Lehen
Jagdreviere]]
  },
  AvgDialog_25191_Content_20 = {
    Text = "Tanzt! Kommt schon, alle tanzen!"
  },
  AvgDialog_25191_Content_21 = {
    Text = "Du drängst dich durch die geschäftige Menge und findest Wanda am hinteren Ende sitzend."
  },
  AvgDialog_25191_Content_23 = {
    Text = "Sie lehnte sich faul gegen ihre Diener, der Wein in ihrem Glas glänzte mit einem edelsteinähnlichen Schimmer."
  },
  AvgDialog_25191_Content_24 = {
    Text = "Guten Abend, Meister Mönch. Ich dachte, Sie würden sich nicht herablassen, an unserem absurden Fest teilzunehmen."
  },
  AvgDialog_25191_Content_25 = {
    Text = "Manchmal möchte ich meine Neugier befriedigen."
  },
  AvgDialog_25191_Content_26 = {
    Text = "<Gray:Außerdem, bei all dem D-Schleim draußen, wohin sollte ich sonst gehen...?>"
  },
  AvgDialog_25191_Content_27 = {
    Text = "Jemand zupft sanft am Saum deiner Kutte."
  },
  AvgDialog_25191_Content_28 = {
    Text = "Ihr seid... Susannas Bruder!"
  },
  AvgDialog_25191_Content_29 = {
    Text = "Ich habe einen Namen, wisst Ihr! Alle nennen mich Kleine Beckmann."
  },
  AvgDialog_25191_Content_3 = {
    Text = "Was? Du sagst, Wanda hat alle Schlösser geschmolzen und eine Feier im Schloss mit allen Cambrian-Dörflern geschmissen?"
  },
  AvgDialog_25191_Content_30 = {
    Text = "Guten Abend, kleiner Beckman. Wohin ist deine Schwester gegangen?"
  },
  AvgDialog_25191_Content_31 = {
    Text = "Die große Schwester und die anderen, die nicht krank waren, sind zusammen aufgebrochen..."
  },
  AvgDialog_25191_Content_32 = {
    Text = "Kleine Beckmann senkt niedergeschlagen den Kopf. Er schnieft, dann blickt er mit großen, wässrigen Augen zu dir auf."
  },
  AvgDialog_25191_Content_33 = {
    Text = "Guter Herr, wollt Ihr mit mir tanzen? Ich habe keinen Partner, buhuhu..."
  },
  AvgDialog_25191_Content_34 = {
    Text = "Kleiner, Mönchen ist das Tanzen nicht gestattet."
  },
  AvgDialog_25191_Content_35 = {
    Text = "Jetzt erkläre ich, dass du tanzen darfst. Vergiss diese veralteten Regeln."
  },
  AvgDialog_25191_Content_36 = {
    Text = "Im Kambrischen bin ich — <Big:DAS GESETZ SELBST!>"
  },
  AvgDialog_25191_Content_37 = {
    Text = "Du blickst in Kleine Beckmanns hoffnungsvolle Augen und schluckst deine Ablehnung hinunter."
  },
  AvgDialog_25191_Content_38 = {
    Text = "Entschuldigung, ich habe nie gelernt zu tanzen, aber ich kann mich ein paar Mal mit dir drehen."
  },
  AvgDialog_25191_Content_39 = {
    Text = "Du nimmst Kleine Beckmanns Hand und führst ihn in die Mitte der Halle, wo ihr euch in das Meer der Dorfbewohner einreiht, die sich zur Melodie wiegen."
  },
  AvgDialog_25191_Content_4 = {
    Text = "Es ist die reine Wahrheit! Ich habe gehört, dass alle, die nicht infiziert waren, bereits gegangen sind. Die Einzigen, die noch bei diesem Tanz sind, sind die todkranken."
  },
  AvgDialog_25191_Content_40 = {
    Text = "Röcke flattern und wirbeln im Kerzenlicht wie tausend bunte, sich drehende Törtchen."
  },
  AvgDialog_25191_Content_41 = {
    Text = "Du treibst durch diesen goldenen Ozean aus Licht und Gesang, schließlich eingetaucht in die aufsteigenden Blasen der Freude."
  },
  AvgDialog_25191_Content_42 = {
    Text = "Kleine Beckmanns Beinarbeit ist nicht besser als deine. Er wackelt ziellos im Takt, sein Gesicht glüht in einem strahlenden, fröhlichen Rot."
  },
  AvgDialog_25191_Content_43 = {
    Text = "Hahaha! So glücklich! Das ist der beste Tag meines Lebens!"
  },
  AvgDialog_25191_Content_44 = {
    Text = "Mein Herr, nehmt meine Hand! Lasst uns zusammen wirbeln!"
  },
  AvgDialog_25191_Content_45 = {
    Text = "Beeil dich!"
  },
  AvgDialog_25191_Content_46 = {
    Text = "<BigShake:Schneller!>"
  },
  AvgDialog_25191_Content_47 = {
    Text = "<Red:Schneller...>"
  },
  AvgDialog_25191_Content_48 = {
    Text = "Schnel@2..."
  },
  AvgDialog_25191_Content_49 = {
    Text = "Kleiner Beckman, was ist mit deinem Gesicht passiert...?!"
  },
  AvgDialog_25191_Content_5 = {
    Text = "Hahaha! Ich habe mir so viel Mühe gegeben, einen Spitzel an ihrer Seite einzuschleusen... es scheint, ich habe meine Mühe verschwendet."
  },
  AvgDialog_25191_Content_50 = {
    Text = "<Change> Tanze mit mir..."
  },
  AvgDialog_25191_Content_51 = {
    Text = "Tintenartiger D-Schleim beginnt aus den Augen des Jungen zu fließen, doch er lächelt weiter, während er nach dir greift."
  },
  AvgDialog_25191_Content_52 = {
    Text = "Ein plötzlicher Schauer berührt deine Nase. Du schaust auf und siehst, wie schwarzer Schleim langsam von dem Kronleuchter tropft."
  },
  AvgDialog_25191_Content_53 = {
    Text = "Ein Tropfen. Zwei."
  },
  AvgDialog_25191_Content_54 = {
    Text = "Du schaust dich panisch um und stellst fest, dass viele Menschen Anzeichen von Verfall an ihren Kleidern, Armen und sogar Gesichtern zeigen."
  },
  AvgDialog_25191_Content_55 = {
    Text = "Aber sie tanzen immer noch fröhlich."
  },
  AvgDialog_25191_Content_56 = {
    Text = "Mein Herr, warum ignoriert Ihr mich? Mögt Ihr mich nicht mehr...?"
  },
  AvgDialog_25191_Content_57 = {
    Text = "Der Junge streckt seine klebrigen Hände aus, um dich zu umarmen, Trauer strömt aus seinen hohlen Augen."
  },
  AvgDialog_25191_Content_58 = {
    Text = "Bleib bei mir... Bleib bei mir..."
  },
  AvgDialog_25191_Content_6 = {
    Text = "Bei einer so schrecklichen Seuche versucht sie nicht einmal zu fliehen. Sie sperrt einfach alle ein, um auf den Tod zu warten..."
  },
  AvgDialog_25191_Content_7 = {
    Text = "Ist es wahr, wie die Gerüchte sagen, dass sie völlig verrückt geworden ist?"
  },
  AvgDialog_25191_Content_8 = {
    Text = "Eure Worte sind recht faszinierend. War sie denn jemals eine Frau von klarem Verstand?"
  },
  AvgDialog_25191_Content_9 = {
    Text = "Äh... nun ja..."
  },
  AvgDialog_25199_Content_1 = {
    Text = "Du reißt dich endlich von Kleine Beckmann los, nur um zu sehen, wie die gesamte Halle mutiert."
  },
  AvgDialog_25199_Content_10 = {
    Text = "Wenn uns das Grab bestimmt ist, warum sollten wir nicht mit Freude von dannen gehen?"
  },
  AvgDialog_25199_Content_11 = {
    Text = "Oder sollten wir uns im Bett zusammenrollen, allein weinen und all deine Fantasien über die am Rande des Todes Erfüllungen?"
  },
  AvgDialog_25199_Content_12 = {
    Text = "Ich habe es dir gesagt. In Kambrisch bin ich das Gesetz."
  },
  AvgDialog_25199_Content_13 = {
    Text = "Die Königin befiehlt: Tanzt, tanzt weiter!\nVergangenheit, Gegenwart und Zukunft, wir werden den Tod niemals fürchten."
  },
  AvgDialog_25199_Content_14 = {
    Text = "Auf Wandas Befehl –"
  },
  AvgDialog_25199_Content_16 = {
    Text = "Die Stimmung im Saal wird auf ihren Höhepunkt getrieben."
  },
  AvgDialog_25199_Content_17 = {
    Text = "<Change> Tanz, tanz..."
  },
  AvgDialog_25199_Content_19 = {
    Text = "Wahnsinnig. Sie sind alle völlig wahnsinnig geworden..."
  },
  AvgDialog_25199_Content_2 = {
    Text = "Der Festsaal verwandelte sich in einen riesigen Friedhof, mit D-Slime, der wie Läuse unter einem luxuriösen Gewand herausquillt."
  },
  AvgDialog_25199_Content_20 = {
    Text = "Fassungslos blickst du auf alles, was sich vor deinen Augen entfaltet. Selbst in deinen wildesten Fieberträumen hast du nie eine so phantasmagorische Szene erlebt."
  },
  AvgDialog_25199_Content_21 = {
    Text = "Alle sind wahnsinnig. Alle sind gezeichnet."
  },
  AvgDialog_25199_Content_22 = {
    Text = "Aber alle sind glücklich."
  },
  AvgDialog_25199_Content_23 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_25199_Content_24 = {
    Text = "Ich hörte einst jemanden sagen: Diejenigen, die die Musik nicht hören können, glauben, dass die Tänzer verrückt sind."
  },
  AvgDialog_25199_Content_25 = {
    Text = "Du reißt dir den Kragen auf und sinkst völlig erschöpft zu Boden."
  },
  AvgDialog_25199_Content_26 = {
    Text = "Es ist ziemlich interessant. Ich habe einst am Grab von Mythag geschworen, weder das Leben noch den Tod zu fürchten, aber ich war nie wirklich bereit, dem Tod ins Auge zu sehen."
  },
  AvgDialog_25199_Content_27 = {
    Text = "Du hast mir neue Einsichten gegeben – obwohl ich hoffe, niemals solchen Dilemmata gegenüberzustehen."
  },
  AvgDialog_25199_Content_28 = {
    Text = "Du nimmst ein Glas und stößt mit Wanda an, über das Meer aus schwarzem Ichor, verschüttetem Wein und verstreuten Blumen hinweg."
  },
  AvgDialog_25199_Content_29 = {
    Text = "Ehre den Mut."
  },
  AvgDialog_25199_Content_3 = {
    Text = "Nein. Zu viele Menschen mutieren auf einmal..."
  },
  AvgDialog_25199_Content_30 = {
    Text = "Wanda lachte herzlich und hob ihr Glas, schüttelte es in deine Richtung."
  },
  AvgDialog_25199_Content_31 = {
    Text = "Ehre den Tod. Unser prächtigster und süßester Tod."
  },
  AvgDialog_25199_Content_32 = {
    Text = "Der süße Geruch von faulenden Leichnamen füllt deine Nasenlöcher, begleitet von unzähligen Weinen, Schluchzen und Lachen."
  },
  AvgDialog_25199_Content_33 = {
    Text = "Doch sie hören nie auf zu tanzen."
  },
  AvgDialog_25199_Content_34 = {
    Text = "Die Königin verlässt ihr Volk niemals. Bald werden sie gemeinsam in dieses prächtige Fest des Todes einziehen."
  },
  AvgDialog_25199_Content_36 = {
    Text = "Dieses Mal ist sie endlich nicht allein."
  },
  AvgDialog_25199_Content_37 = {
    Text = "Erinnerst du dich noch an jene Schrift? Die, die du am Tor rezitiert hast?"
  },
  AvgDialog_25199_Content_38 = {
    Text = "...Erinnere dich."
  },
  AvgDialog_25199_Content_39 = {
    Text = "<Red: Sich der Begierde hinzugeben und den unkontrollierten Wünschen nachzugeben, wird mit ewigem Feuer als Warnung bestraft.>"
  },
  AvgDialog_25199_Content_4 = {
    Text = "Instinktiv blickst du zu Wanda hinüber."
  },
  AvgDialog_25199_Content_40 = {
    Text = "Bist du bereit, die Strafe der ewigen Flammen zu erdulden?"
  },
  AvgDialog_25199_Content_41 = {
    Text = "In der hereinbrechenden Dunkelheit hörst du nur ein fernes, verklingendes Lachen."
  },
  AvgDialog_25199_Content_42 = {
    Text = "Wie Splitter eines Meteors, die in einen See fallen, sinken die Klänge langsam in die Tiefen deines Bewusstseins."
  },
  AvgDialog_25199_Content_43 = {
    Text = "Bis ganz am Ende nur noch Stille herrscht."
  },
  AvgDialog_25199_Content_5 = {
    Text = "Durch die geschäftige Menschenmenge lächelt Wanda und hebt ihr Glas zu dir."
  },
  AvgDialog_25199_Content_6 = {
    Text = "Bereits verängstigt, kleiner Mönch?"
  },
  AvgDialog_25199_Content_7 = {
    Text = "Ich verstehe nicht. Willst du einfach nur danebenstehen und zusehen, wie sie wahnsinnig werden und sterben?"
  },
  AvgDialog_25199_Content_8 = {
    Text = "Wanda lachte herzlich, schwarze Tränen strömten aus ihren Augen—ihr Körper war mit Wunden von Auflösung bedeckt."
  },
  AvgDialog_25199_Content_9 = {
    Text = "Nichts ist ewig, kleiner Mönch. Nicht einmal die Götter, die du anbetest."
  },
  AvgDialog_34830_Content_1 = {Text = "Piper"},
  AvgDialog_34830_Content_10 = {
    Text = "Habt keine Angst. Ich werde einen Weg finden, euch hier rauszuholen."
  },
  AvgDialog_34830_Content_11 = {
    Text = "Die Dorfbewohner starren nur schweigend zurück. Es gibt keine Hoffnung in ihren Augen—aber auch keine Feindseligkeit."
  },
  AvgDialog_34830_Content_12 = {
    Text = "Warte, die Magd..."
  },
  AvgDialog_34830_Content_13 = {
    Text = "Mein Vater und mein Bruder sind dort unten eingesperrt. Ich muss sie retten —"
  },
  AvgDialog_34830_Content_14 = {
    Text = "Kennt jemand von euch eine Magd namens Susanna?"
  },
  AvgDialog_34830_Content_15 = {
    Text = "Susanna? Das ist meine große Schwester!"
  },
  AvgDialog_34830_Content_16 = {
    Text = "Eine klare Kinderstimme ertönt aus der Ecke"
  },
  AvgDialog_34830_Content_17 = {
    Text = "Beim flackernden Licht einer einzelnen Kerze bemerkst du einen alten Mann, der im Schatten liegt, und einen Jungen mit weit aufgerissenen Augen, der sich an ihn schmiegt."
  },
  AvgDialog_34830_Content_18 = {
    Text = "Susanna ist meine Tochter... Ist ihr etwas zugestoßen?"
  },
  AvgDialog_34830_Content_19 = {
    Text = "Sie macht sich große Sorgen um Euch. Sie hat versucht, einen Weg zu finden, Euch zu retten."
  },
  AvgDialog_34830_Content_2 = {
    Text = "Kambrische Burg\nUnterirdisches Gefängnis"
  },
  AvgDialog_34830_Content_20 = {
    Text = "Wir können diesen Ort nicht verlassen..."
  },
  AvgDialog_34830_Content_21 = {
    Text = "Der alte Mann schüttelte den Kopf. Sein Körper war von vielen ätzenden Löchern durchzogen, aus denen schwarze Flüssigkeit auf das Stroh unter ihm tropfte"
  },
  AvgDialog_34830_Content_22 = {
    Text = "Wir sind aus freiem Willen hier geblieben. Sobald die Krankheit einen erfasst, verliert man den Verstand... man wird zu einem Monster."
  },
  AvgDialog_34830_Content_23 = {
    Text = "Es stimmt. Es gab so viele Morde in der Umgebung... Dann kam die Herrin von Haus zu Haus. Sie sammelte die Kranken ein und brachte uns hierher."
  },
  AvgDialog_34830_Content_24 = {
    Text = "Wenn jemand nicht in Quarantäne wollte, ließ sie ihn das Lehen verlassen – solange er schwor, niemals zurückzukehren."
  },
  AvgDialog_34830_Content_25 = {
    Text = "Aber hier bekommen wir jeden Tag Brei und süßes Brot!"
  },
  AvgDialog_34830_Content_26 = {
    Text = "<Gray:Verstehe. Haben wir sie völlig falsch eingeschätzt?>"
  },
  AvgDialog_34830_Content_27 = {
    Text = "Hat Lady Wanda Euch gut behandelt, seit sie das Lehen übernommen hat?"
  },
  AvgDialog_34830_Content_28 = {
    Text = "Gut? Ich weiß nicht. Ich habe sie nie persönlich gesehen. Ich kenne nur die Geschichten – dass sie grausam ist, dass sie ihre vier Ehemänner getötet hat, dass sie ein Teufel in Menschengestalt ist."
  },
  AvgDialog_34830_Content_29 = {
    Text = "Aber seit sie hier ist, hat sie viel Gutes getan. Das Leben ist viel besser als früher."
  },
  AvgDialog_34830_Content_3 = {
    Text = "Die schwere Eisentür schließt sich fest hinter dir"
  },
  AvgDialog_34830_Content_30 = {
    Text = "Sie lehrte uns, Felder zu bestellen und Schafe zu hüten, und brachte uns jedes Jahr zum Markt in Shar, um mit Wolle viel Geld zu verdienen"
  },
  AvgDialog_34830_Content_31 = {
    Text = "Das ist richtig, der Sharich-Markt wurde von ihr von Earl Goodrich erobert. Sie kämpfen seit fast einem Jahr darum..."
  },
  AvgDialog_34830_Content_32 = {
    Text = "Die Dorfbewohner reden alle gleichzeitig los und erzählen Geschichten über Wandas Verwaltung: Ackerbau, Schmelzen, Viehzucht, Lehensrecht..."
  },
  AvgDialog_34830_Content_33 = {
    Text = "Du bist verblüfft, wie tief Wanda in jeden Aspekt des Lehens eingebunden ist. Sie ist gewiss keine müßige, vergnügungssüchtige Adlige."
  },
  AvgDialog_34830_Content_34 = {
    Text = "Sie ist eine gute Herrscherin. Es ist nur eine Tragödie, dass die Auflösung sie gefunden hat."
  },
  AvgDialog_34830_Content_35 = {
    Text = "<Gray:Eine Ausbreitung dieses Ausmaßes... es muss ein Fusionsriss in der Nähe sein.>"
  },
  AvgDialog_34830_Content_36 = {
    Text = "Die eiserne Tür hinter dir öffnet sich plötzlich mit einem Knarren."
  },
  AvgDialog_34830_Content_37 = {
    Text = "Du drehst dich um, und Wanda steht plötzlich vor dem Gefängnistor. Ihr hoher Körper wirft einen Schatten auf die Kerzen im Flur und taucht ihre Silhouette in warmes Orange"
  },
  AvgDialog_34830_Content_38 = {
    Text = "Lass diesen Kerl raus, ich muss allein mit {Male=er,Female=sie} sprechen"
  },
  AvgDialog_34830_Content_39 = {
    Text = [[
Cambrian Castle
Garten]]
  },
  AvgDialog_34830_Content_4 = {
    Text = "Du drehst dich um und siehst leuchtende Augen, die dich wie wilde Tiere im Dunkeln umzingeln"
  },
  AvgDialog_34830_Content_40 = {
    Text = "Ihr spaziert gemeinsam über weiches Gras bis zum Seeufer"
  },
  AvgDialog_34830_Content_41 = {
    Text = "Der nächtliche See ist ein schwarzer Spiegel, der das zerbrochene Mondlicht schwach reflektiert"
  },
  AvgDialog_34830_Content_42 = {
    Text = "Ich denke, du solltest verstehen, dass Kambrium derzeit eine schwere Erosionskatastrophe erleidet, und ich bin machtlos"
  },
  AvgDialog_34830_Content_43 = {
    Text = "Und du, du hast dich im Schloss im Kampf gegen die Monster sehr geschickt angestellt, fast wie ein Profi"
  },
  AvgDialog_34830_Content_44 = {
    Text = "<Gray:Ich mache das beruflich...>"
  },
  AvgDialog_34830_Content_45 = {
    Text = "War die Frau nicht im Schlafgemach, wie kann sie das so genau wissen?"
  },
  AvgDialog_34830_Content_46 = {
    Text = "Meine Augen und Ohren sind überall in Cambrian, selbst die Freesien hier brauchen meine Erlaubnis zum Blühen, es gibt nichts, was ich nicht weiß"
  },
  AvgDialog_34830_Content_47 = {
    Text = "Und die Zofe? Warum behältst du sie, obwohl du weißt, dass sie eine Spionin ist?"
  },
  AvgDialog_34830_Content_48 = {
    Text = "Wanda winkte gleichgültig ab"
  },
  AvgDialog_34830_Content_49 = {
    Text = "Sie ist nur ein armes, gewöhnliches Menschlein, sie kann mir kein Haar krümmen"
  },
  AvgDialog_34830_Content_5 = {
    Text = "<Shake:Woaaahhh!!>"
  },
  AvgDialog_34830_Content_50 = {
    Text = "Außerdem hat sie mich recht gut bedient, einen passenden menschlichen Diener zu finden, ist nicht einfach"
  },
  AvgDialog_34830_Content_51 = {
    Text = "Also, ich hoffe, du kannst mir bei der Korrosion helfen. Lehn mich nicht sofort ab – der Preis ist verhandelbar, ich werde mein Bestes tun, um deine Wünsche zu erfüllen"
  },
  AvgDialog_34830_Content_52 = {
    Text = "Du kannst es nicht ertragen, diese Dorfbewohner unschuldig sterben zu sehen, oder, lieber „Mönch“?"
  },
  AvgDialog_34830_Content_53 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_34830_Content_54 = {
    Text = "Das letzte Mal im Schlafgemach erwähnte die Dame „ihr Menschen“, und in Verbindung mit Ihren besonderen Fähigkeiten... Frau Wanda, Sie sind doch kein Mensch, oder?"
  },
  AvgDialog_34830_Content_55 = {
    Text = "Ein mächtiges und grausames Wesen aus einer fernen Heimat, das sich dennoch um das Leben der Dorfbewohner kümmert. Was ist das wahre Ziel der Dame?"
  },
  AvgDialog_34830_Content_56 = {
    Text = "Angesichts deiner Fragen hob Wanda die Augenbrauen und begann plötzlich zu lachen"
  },
  AvgDialog_34830_Content_57 = {
    Text = "War das, was ich gerade gesagt habe, so lustig?"
  },
  AvgDialog_34830_Content_58 = {
    Text = "Nein... Hahaha! Ich bin einfach so glücklich. In all den Jahren, die ich hier verbracht habe, habe ich endlich jemanden getroffen, der auch nicht „hierher“ gehört—genau wie ich."
  },
  AvgDialog_34830_Content_59 = {
    Text = "Woher hast du—"
  },
  AvgDialog_34830_Content_6 = {
    Text = "Als sich deine Augen an die Düsternis gewöhnen, erkennst du endlich die Wirklichkeit der Zelle."
  },
  AvgDialog_34830_Content_60 = {
    Text = "Wanda legt einen schlanken Finger sanft auf deine Lippen."
  },
  AvgDialog_34830_Content_61 = {
    Text = "Shh... Folge mir. Ich möchte dir etwas zeigen."
  },
  AvgDialog_34830_Content_62 = {
    Text = "Weißt du? Im Spiegelbild dieses Sees kann man meine alte Stadt sehen"
  },
  AvgDialog_34830_Content_63 = {
    Text = "Ihr seid dem See näher gekommen. Das tiefblaue Wasser ist fast bodenlos, darin sind Wasserpflanzen und verschwommene schwarze Felsen zu erkennen"
  },
  AvgDialog_34830_Content_64 = {
    Text = "Das Mondlicht erhellt den tiefen Seegrund, endlich erkennst du die schwarzen, spiralförmigen Türme und stumpfen Wände auf den Steinen"
  },
  AvgDialog_34830_Content_65 = {
    Text = "Eine Stadt im Wasser?!"
  },
  AvgDialog_34830_Content_66 = {
    Text = "Damals hatte ich einen prächtigen Palast. Über tausend Diener kümmerten sich um jedes meiner Bedürfnisse."
  },
  AvgDialog_34830_Content_67 = {
    Text = "So wie du sagst, mir ist das Leben meiner Diener egal"
  },
  AvgDialog_34830_Content_68 = {
    Text = "Ich tat genau, was mir gefiel. Meine Diener, meine Stadt... sie waren alle einfach Ausdruck meines Willens und meines Ehrgeizes."
  },
  AvgDialog_34830_Content_69 = {
    Text = "Dann wurde mein Planet von der Katastrophe heimgesucht, die ihr das „Schmelzen“ nennt. Alle starben."
  },
  AvgDialog_34830_Content_7 = {
    Text = "Sitzend, liegend oder an die kalten Steinwände gelehnt—der Raum ist vollgepackt mit zerlumpten Dorfbewohnern."
  },
  AvgDialog_34830_Content_70 = {
    Text = "Ich saß allein in jenem Saal für eine lange, lange Zeit und sah zu, wie mein Palast und meine Hauptstadt zu Asche zerfielen."
  },
  AvgDialog_34830_Content_71 = {
    Text = "Ehrlich gesagt war es ein schreckliches Gefühl. Niemand möchte das zweimal erleben."
  },
  AvgDialog_34830_Content_72 = {Text = "Frau Wanda"},
  AvgDialog_34830_Content_73 = {
    Text = "Es tut mir leid, ich kann dir dabei nicht helfen. Das Schließen des Auflösungsrisses ist sehr komplex, und es wäre unmöglich, allein zu schaffen"
  },
  AvgDialog_34830_Content_74 = {
    Text = "Mach dir darüber keine Sorgen. Sag mir, was dich zurückhält, und ich werde dir alles bereitstellen, was du brauchst."
  },
  AvgDialog_34830_Content_75 = {
    Text = "Du schüttelst den Kopf."
  },
  AvgDialog_34830_Content_76 = {
    Text = "Es ist mehr als das. Unsere derzeitige Umgebung... sie hat einige... Besonderheiten."
  },
  AvgDialog_34830_Content_77 = {
    Text = "Während des Träumens kannst du keine komplexen Operationen wie das Schließen von Rissen durchführen"
  },
  AvgDialog_34830_Content_78 = {
    Text = "<Gray:Wie soll ich ihr das überhaupt erklären?>"
  },
  AvgDialog_34830_Content_79 = {
    Text = "Weil wir uns in einem Traum befinden, kannst du mir nicht helfen... ist es das?"
  },
  AvgDialog_34830_Content_8 = {
    Text = "Ihre Haut ist übersät mit Auflösungsnarben; einige haben bereits die Hälfte ihres Körpers an die Fäulnis verloren. Die Luft ist schwer vom Gestank der Krankheit und des nahenden Todes."
  },
  AvgDialog_34830_Content_80 = {Text = "?!"},
  AvgDialog_34830_Content_81 = {
    Text = "Du... du hast es bemerkt?"
  },
  AvgDialog_34830_Content_82 = {
    Text = "Wanda blickt hinab auf die schwarze Stadt im Wasser, ihre Augen schimmern im gebrochenen weißen Mondlicht."
  },
  AvgDialog_34830_Content_83 = {
    Text = "Seit ich hierher gekommen bin, hatte ich viele Träume. Über Krieg, Katastrophen, Zeit... aber niemals über mein Kapital."
  },
  AvgDialog_34830_Content_84 = {
    Text = "Gerade als ich dabei war, es zu vergessen, traf ich dich und sah es dann wieder am Grund des Sees."
  },
  AvgDialog_34830_Content_85 = {
    Text = "Wusstest du? Wenn ein Sterbender den Pfeifer durch den Nebel wandeln sieht, empfindet er weder Furcht noch Neugier."
  },
  AvgDialog_34830_Content_86 = {
    Text = "Er folgt dem Pfeifer einfach schweigend, zu einem Ort, der ihm gehört."
  },
  AvgDialog_34830_Content_87 = {
    Text = "Wanda seufzte leise"
  },
  AvgDialog_34830_Content_88 = {
    Text = "Meine verlorene Hauptstadt... sie ist wunderschön, wie der Traum eines Sterbenden."
  },
  AvgDialog_34830_Content_89 = {
    Text = "Sie streichelt sanft den stillen, blinden Begleiter an ihrer Seite."
  },
  AvgDialog_34830_Content_9 = {
    Text = "Wanda hat euch tatsächlich alle hier eingesperrt..."
  },
  AvgDialog_34830_Content_90 = {
    Text = "<Change>Meine Lady..."
  },
  AvgDialog_34830_Content_91 = {
    Text = "Cambrian ist mein zweites Zuhause. Ich habe hier nicht viel Zeit verbracht, und doch ist es bereits Zeit, Abschied zu nehmen."
  },
  AvgDialog_34830_Content_92 = {
    Text = "Es tut mir leid, Lady Wanda..."
  },
  AvgDialog_34830_Content_93 = {
    Text = "Wanda winkt abwehrend ab. Als sie wieder aufblickt, ist die Schwermut aus ihrem Gesicht verschwunden."
  },
  AvgDialog_34830_Content_94 = {
    Text = "Keine Sorge. Da ich mich entschieden habe, die Herrin dieses Lehens zu sein, muss ich die Verantwortung für alle übernehmen."
  },
  AvgDialog_34830_Content_95 = {
    Text = "Es geht einfach ums gemeinsame Sterben? Dann lasst uns ruhmvoll sterben."
  },
  AvgDialog_34830_Content_96 = {
    Text = "Was hast du vor?"
  },
  AvgDialog_34830_Content_97 = {
    Text = "Wanda schenkt dir ein geheimnisvolles Lächeln und zwinkert dir zu."
  },
  AvgDialog_34830_Content_98 = {
    Text = "Ein prächtiges Abschiedsbankett."
  },
  AvgDialog_34831_Content_1 = {
    Text = "Du reißt dich endlich von Kleine Beckmann los, nur um zu sehen, wie die gesamte Halle mutiert."
  },
  AvgDialog_34831_Content_10 = {
    Text = "Wenn uns das Grab bestimmt ist, warum sollten wir nicht mit Freude von dannen gehen?"
  },
  AvgDialog_34831_Content_11 = {
    Text = "Oder sollen wir uns in unser Bett verkriechen und allein weinen, um deine Vorstellung von Sterbenden zu erfüllen?"
  },
  AvgDialog_34831_Content_12 = {
    Text = "Ich habe es dir gesagt. In Kambrisch bin ich das Gesetz."
  },
  AvgDialog_34831_Content_13 = {
    Text = "Jetzt befiehlt die Königin, tanzt weiter! Vergangenheit, Gegenwart, Zukunft, wir fürchten den Tod nicht"
  },
  AvgDialog_34831_Content_14 = {
    Text = "Auf Wandas Befehl –"
  },
  AvgDialog_34831_Content_16 = {
    Text = "Die Stimmung im Saal wird auf ihren Höhepunkt getrieben."
  },
  AvgDialog_34831_Content_17 = {
    Text = "<Change> Tanz, tanz..."
  },
  AvgDialog_34831_Content_19 = {
    Text = "Wahnsinnig. Sie sind alle völlig wahnsinnig geworden..."
  },
  AvgDialog_34831_Content_2 = {
    Text = "Der zuvor fröhliche Festsaal hat sich in ein riesiges Grab verwandelt, und der ständig überlaufende D-Schleim sieht aus wie Läuse unter einem eleganten Mantel"
  },
  AvgDialog_34831_Content_20 = {
    Text = "Fassungslos blickst du auf alles, was sich vor deinen Augen entfaltet. Selbst in deinen wildesten Fieberträumen hast du nie eine so phantasmagorische Szene erlebt."
  },
  AvgDialog_34831_Content_21 = {
    Text = "Alle sind wahnsinnig. Alle sind gezeichnet."
  },
  AvgDialog_34831_Content_22 = {
    Text = "Aber alle sind glücklich."
  },
  AvgDialog_34831_Content_23 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_34831_Content_24 = {
    Text = "Egal, ich gebe auf"
  },
  AvgDialog_34831_Content_25 = {
    Text = "Du reißt dir den Kragen auf und sinkst völlig erschöpft zu Boden."
  },
  AvgDialog_34831_Content_26 = {
    Text = "Ironisch, ich schwor am Grab von Missaga, keine Angst vor dem Tod zu haben, aber ich war nie wirklich bereit dafür"
  },
  AvgDialog_34831_Content_27 = {
    Text = "Du hast mir eine Lektion erteilt, Wanda"
  },
  AvgDialog_34831_Content_28 = {
    Text = "Du nimmst ein Glas und stößt mit Wanda an, über das Meer aus schwarzem Ichor, verschüttetem Wein und verstreuten Blumen hinweg."
  },
  AvgDialog_34831_Content_29 = {
    Text = "——Auf unseren süßesten, prächtigsten Tod"
  },
  AvgDialog_34831_Content_3 = {
    Text = "Nein. Zu viele Menschen mutieren auf einmal..."
  },
  AvgDialog_34831_Content_30 = {
    Text = "Ein süßer Geruch von verwesenden Leichen stieg dir in die Nase, und du hörtest das Wehklagen unzähliger Menschen"
  },
  AvgDialog_34831_Content_31 = {
    Text = "Doch sie hören nie auf zu tanzen."
  },
  AvgDialog_34831_Content_32 = {
    Text = "Die Königin verlässt ihr Volk niemals. Bald werden sie gemeinsam in dieses prächtige Fest des Todes einziehen."
  },
  AvgDialog_34831_Content_34 = {
    Text = "Diesmal ist sie endlich nicht mehr allein"
  },
  AvgDialog_34831_Content_35 = {
    Text = "Erinnerst du dich noch an jene Schrift? Die, die du am Tor rezitiert hast?"
  },
  AvgDialog_34831_Content_36 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_34831_Content_37 = {
    Text = "<Red: Sich der Begierde hinzugeben und den unkontrollierten Wünschen nachzugeben, wird mit ewigem Feuer als Warnung bestraft.>"
  },
  AvgDialog_34831_Content_38 = {
    Text = "Bist du bereit?"
  },
  AvgDialog_34831_Content_39 = {
    Text = "Unter der Strafe des ewigen Feuers"
  },
  AvgDialog_34831_Content_4 = {
    Text = "Instinktiv blickst du zu Wanda hinüber."
  },
  AvgDialog_34831_Content_40 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_34831_Content_41 = {
    Text = "In der hereinbrechenden Dunkelheit hörst du nur ein fernes, verklingendes Lachen."
  },
  AvgDialog_34831_Content_42 = {
    Text = "Wie Splitter eines Meteors, die in einen See fallen, sinken die Klänge langsam in die Tiefen deines Bewusstseins."
  },
  AvgDialog_34831_Content_43 = {
    Text = "Bis ganz am Ende nur noch Stille herrscht."
  },
  AvgDialog_34831_Content_5 = {
    Text = "Durch die lärmende Menge hindurch hebt Wanda lächelnd ihr Glas zu dir"
  },
  AvgDialog_34831_Content_6 = {
    Text = "Bereits verängstigt, kleiner Mönch?"
  },
  AvgDialog_34831_Content_7 = {
    Text = "Ich verstehe nicht. Willst du einfach nur danebenstehen und zusehen, wie sie wahnsinnig werden und sterben?"
  },
  AvgDialog_34831_Content_8 = {
    Text = "Wanda lacht laut, schwarze Tränen fließen aus ihren Augen. Erst jetzt bemerkst du, dass auch ihr Körper von Erosionswunden übersät ist"
  },
  AvgDialog_34831_Content_9 = {
    Text = "Nichts ist ewig, kleiner Mönch. Nicht einmal die Götter, die du anbetest."
  },
  AvgDialog_34965_Content_1 = {
    Text = "Nach dem Besiegen einer anderen Gruppe von Feinden, die durch den Lärm angelockt wurden, bekommst du endlich einen kurzen Moment, um durchzuatmen."
  },
  AvgDialog_34965_Content_10 = {
    Text = "Diese Flüssigkeiten sind nicht ätzend, aber es ist dennoch ratsam, die notwendigen Vorsichtsmaßnahmen zu treffen."
  },
  AvgDialog_34965_Content_11 = {
    Text = "Bevor du sie aufhalten konntest, riss Ramona den Stoff vom Körper des Seefahrers, wickelte ihn um die Spitze ihrer Waffe und stieß ihn dann in die Bauchhöhle des Seefahrers."
  },
  AvgDialog_34965_Content_12 = {
    Text = "...War Sie schon immer so?"
  },
  AvgDialog_34965_Content_13 = {
    Text = "Sei nicht überrascht, das ist eine Manifestation des akademischen Geistes."
  },
  AvgDialog_34965_Content_14 = {
    Text = "Alright, ich habe die Blutgefäße des festen Parasiten durchtrennt."
  },
  AvgDialog_34965_Content_15 = {
    Text = "Mit einem Schwung des Schwertes rollte das völlig leblose Parasitenwesen zu Boden. Übelriechendes Wasser breitete sich durch die Ritzen des Decks in alle Richtungen aus. Der Kapitän zog Celeste schnell an einen anderen Ort."
  },
  AvgDialog_34965_Content_16 = {
    Text = "Der Parasit ähnelt einer gallertartigen Lebensform mit Tentakeln, trägt jedoch das Wesen eines Säugetierembryos in sich. Selbst durch seine Haut hindurch kann man ein starkes Gefühl der Blasphemie spüren."
  },
  AvgDialog_34965_Content_17 = {
    Text = "Ramona frunció el ceño, guardó su espada y recogió la lanza del Seefahrer del suelo, cortando ligeramente la piel gelatinosa del parásito—"
  },
  AvgDialog_34965_Content_18 = {
    Text = "Ein Ansturm von schwarzem Eiter spritzt heraus und zwingt Murphy, mit einem Schrei mehrere Schritte zurückzuspringen."
  },
  AvgDialog_34965_Content_19 = {
    Text = "Was ist los? Gibt es etwas?"
  },
  AvgDialog_34965_Content_2 = {
    Text = "Warum sind die Bäuche dieser Seefahrer so groß?"
  },
  AvgDialog_34965_Content_20 = {
    Text = "Schwarz! Schwarze Flüssigkeit! Kapitän, kannst du das nicht sehen?"
  },
  AvgDialog_34965_Content_21 = {
    Text = "Du und Ramona tauschtet einen Blick aus. Ohne Zweifel war der Ausfluss aus dem Parasiten unser \"guter Freund\": D-Slime."
  },
  AvgDialog_34965_Content_22 = {
    Text = "Diese Seefahrer zeigten keine Anzeichen von Parasitierung, zumindest nicht vor der Explosion..."
  },
  AvgDialog_34965_Content_23 = {
    Text = "Vor der Explosion...vor der Explosion...vor dem Verschwinden des Bereichs!"
  },
  AvgDialog_34965_Content_24 = {
    Text = [[
Das Gebiet ist verschwunden?!
Celeste, bist du nicht mehr in der Lage, das Gebiet aufrechtzuerhalten?]]
  },
  AvgDialog_34965_Content_25 = {
    Text = "Nach der positiven Antwort des Kapitäns fügte Ramona alle Informationen zusammen."
  },
  AvgDialog_34965_Content_26 = {
    Text = "Sie sah ernst auf Murphy, der den Kapitän herumzog, um dem fließenden D-Slime auszuweichen."
  },
  AvgDialog_34965_Content_27 = {
    Text = "Der ungeborene „Gott“ ist zum „Kern“ der Katastrophen geworden, der alle lebenden Wesen auf dem Schiff beeinflusst."
  },
  AvgDialog_34965_Content_28 = {
    Text = "Seefahrer, die schwach im Geist und chaotisch im Denken sind, sind die Ersten, die von Katastrophen betroffen sind. Diese Parasiten sind wahrscheinlich eine Manifestation von D-Hyperplasie."
  },
  AvgDialog_34965_Content_29 = {Text = "Auch?"},
  AvgDialog_34965_Content_3 = {
    Text = "Murphy näherte sich vorsichtig dem besiegten Seefahrer, während Ramona dicht hinter ihm folgte."
  },
  AvgDialog_34965_Content_30 = {
    Text = "Du nickst und signalisierst allen, gemeinsam zu bewegen, während ihr den Versteckraum verlasst.\nIn die Richtung, aus der du und Murphy das Geräusch gehört habt, geht ihr zurück zur unteren Etage."
  },
  AvgDialog_34965_Content_31 = {
    Text = "Die Hütte, überwuchert von Wucherungen, ist unheimlich still. Die Wucherungen sind seit deinem Verlassen noch chaotischer gewachsen."
  },
  AvgDialog_34965_Content_4 = {
    Text = "Sie tauschten einen Blick aus und drehten gemeinsam den liegenden Körper des Seefahrers um."
  },
  AvgDialog_34965_Content_5 = {
    Text = "Der Bauch ist durch den Parasiten geschwollen, die Haut so dünn gedehnt, dass sie fast transparent wird und die inneren Organe sichtbar sind."
  },
  AvgDialog_34965_Content_6 = {
    Text = "Es bewegt sich! Es bewegt sich!"
  },
  AvgDialog_34965_Content_7 = {
    Text = "Der Parasit wühlte sich offen sichtbar, dehnte die Bauchhaut des Wirts, bis sie ihre Textur verlor—"
  },
  AvgDialog_34965_Content_8 = {Text = "Zisch!"},
  AvgDialog_34965_Content_9 = {
    Text = "Der Bauch des Seefahrers entleerte sich wie ein Ballon, und der Parasit hörte auf sich zu bewegen. Ramona schwang ihr Schwert an einem leeren Platz und schnippte das schmutzige Wasser von der Klinge."
  },
  AvgDialog_34966_Content_1 = {
    Text = "Veraltet, zur Löschung ausstehend"
  },
  AvgDialog_34967_Content_1 = {Text = "@2..."},
  AvgDialog_34967_Content_10 = {
    Text = "Dieses Mal hast du zwar erfolgreich die Psychische Dimension betreten, aber gerade als du die Augen öffnen und den Link aktivieren wolltest, strömten bizarre und verschwommene Bilder wie chaotische Bilder in dein Gehirn."
  },
  AvgDialog_34967_Content_11 = {
    Text = "Du schaust in das Nichts in deinem Herzen und versuchst, dem abnormalen Stress standzuhalten, aber dein Verstand bricht schwer zusammen"
  },
  AvgDialog_34967_Content_12 = {Text = "Hmm...!"},
  AvgDialog_34967_Content_13 = {
    Text = "Student, du hast eine Nasebluten."
  },
  AvgDialog_34967_Content_14 = {
    Text = "Du warst erschrocken und hast dir mit dem Stoff an deiner Schulter die Nase abgewischt. Wie erwartet war der schwarze Stoff mit Spritzern dunklem Blut befleckt."
  },
  AvgDialog_34967_Content_15 = {
    Text = "Du bist zu müde. Lass mich Murphy tragen."
  },
  AvgDialog_34967_Content_16 = {
    Text = "Du schüttelst den Kopf und versammelst all deine Kraft, um Murphy zu stabilisieren."
  },
  AvgDialog_34967_Content_17 = {
    Text = "Mir geht's gut. Mach weiter."
  },
  AvgDialog_34967_Content_2 = {
    Text = "Murphys Bewusstsein wurde von einem Gefühl der Verzweiflung und des unmotivierten Kampfes umhüllt, ihre Murmeln woben sich in einen Käfig nach dem anderen."
  },
  AvgDialog_34967_Content_3 = {
    Text = "Bild...@1..."
  },
  AvgDialog_34967_Content_4 = {
    Text = "Rufst du Tulu?"
  },
  AvgDialog_34967_Content_5 = {
    Text = "Auf welcher Grundlage..."
  },
  AvgDialog_34967_Content_6 = {
    Text = "Ihre Hände spannten sich unwillkürlich an, ihr Körper war in das Phantom der Angst gehüllt."
  },
  AvgDialog_34967_Content_7 = {
    Text = "Tulu... In der Tat, wenn Tulu hier wäre, wüsste er, wie er dich aufwecken kann.\nSelbst wenn er es nicht könnte, würde er dich zumindest besser fühlen lassen..."
  },
  AvgDialog_34967_Content_8 = {
    Text = "Alright... der Link. Ich kann versuchen, ihn erneut über den Link zu kontaktieren."
  },
  AvgDialog_34967_Content_9 = {
    Text = "Du drehst dich um und siehst die nach wie vor gegen die Angriffe der Seefahrer kämpfende Ramona an, atmest tief ein und schließt die Augen, um in die Psychische Dimension einzutauchen..."
  },
  AvgDialog_34968_Content_1 = {
    Text = "Überlastsicherung"
  },
  AvgDialog_34968_Content_10 = {
    Text = "Wenn die Sterne in einer Linie stehen, werden die Himmelskörper meine Wiedergeburt leiten. Dann wird das Reich der Götter erstrahlen, und Lemuria wird erneut das Licht der Dämmerung empfangen"
  },
  AvgDialog_34968_Content_100 = {Text = "Wer da?!"},
  AvgDialog_34968_Content_101 = {
    Text = "Der Lauschangreifer eilte mit einem Knochen-Speer davon. Ramona jagte ihm nach, nur um eine in Schwarz gekleidete Gestalt am Ende des Flurs verschwinden zu sehen."
  },
  AvgDialog_34968_Content_102 = {
    Text = "......Caecus."
  },
  AvgDialog_34968_Content_103 = {
    Text = "Der Erwacher-Junge hat die Kontrolle nicht verloren, und auch Goliath nicht."
  },
  AvgDialog_34968_Content_104 = {
    Text = "Captain, du hast gerade erwähnt, dass Miryam die Verknüpfung von Caecus ist... Bist du dir dessen absolut sicher?"
  },
  AvgDialog_34968_Content_105 = {
    Text = "Was ich weiß, kann nicht falsch sein."
  },
  AvgDialog_34968_Content_106 = {
    Text = "Doll, hast du mich gehört?"
  },
  AvgDialog_34968_Content_107 = {
    Text = "Das bedeutet, dass Miryam, der Hauptpriester der Seefahrer, nicht außer Gefecht gesetzt wurde."
  },
  AvgDialog_34968_Content_108 = {
    Text = "Was das Koma des Geheimnisträgers betrifft... in einem Jahr in Missaga ist %eroder sie% nie plötzlich ohnmächtig geworden"
  },
  AvgDialog_34968_Content_109 = {
    Text = "Bevor ich eine vollständige körperliche Untersuchung durchführe, kann ich nicht feststellen, was mit %hisorher% Körper nicht stimmt."
  },
  AvgDialog_34968_Content_11 = {
    Text = "Das ist der Pakt zwischen dem Gott und diesem flachen Körper..."
  },
  AvgDialog_34968_Content_110 = {
    Text = "William hat das Team bereits angeführt, um die Feinde, die am Dock herumlungerten, auszuschalten, und wartete nur auf deine Rückkehr... \nKomm lebend zurück, ihr alle."
  },
  AvgDialog_34968_Content_111 = {
    Text = [[
Inzwischen
Sonaniels Kraftzimmer]]
  },
  AvgDialog_34968_Content_112 = {
    Text = "Zerbrechliche Holzdeckplanken und Stahlrahmen können die Gnosis-Welle nicht aufhalten; die explosive Energie fegt nach der Explosion durch den Kraftwerksraum."
  },
  AvgDialog_34968_Content_113 = {
    Text = "Inmitten der schwarzen und braunen Trümmer und Ruinen bewegte sie sich steif, als ob sie von Blutduft verführt wurde, fast wie eine gefühllose Puppe."
  },
  AvgDialog_34968_Content_114 = {
    Text = "Jede Bewegung ihres Körpers schien von einer unbekannten Kraft geleitet zu werden. Mit einem leeren und etwas seltsamen Ausdruck schob sie langsam herumliegendes Geröll beiseite und kroch aus den Trümmern."
  },
  AvgDialog_34968_Content_115 = {
    Text = "Niemand weiß, welche dunkle Obsession und Macht sie kontrolliert. Ihr schönes Gesicht ist mit Dreck bedeckt, ihre Augen hohl und matt, lichtlos, doch sie funkeln mit einem unheimlichen Glanz."
  },
  AvgDialog_34968_Content_116 = {
    Text = "Wie Angst und Gefahr, die aus dem Abgrund der Verzweiflung aufsteigen."
  },
  AvgDialog_34968_Content_12 = {
    Text = "...Nein, das ist das Versprechen zwischen dir und mir."
  },
  AvgDialog_34968_Content_13 = {
    Text = "Jetzt umarme einen vorübergehenden tiefen Schlaf."
  },
  AvgDialog_34968_Content_14 = {
    Text = "Hoher Priester Miryam."
  },
  AvgDialog_34968_Content_15 = {
    Text = "Überschwemmungen und Tsunamis trafen nacheinander ein, und bevor die Betroffenen sich von ihren Lieben verabschieden konnten, wurden sie von der überwältigenden Kraft der Natur zu Staub zermahlen."
  },
  AvgDialog_34968_Content_16 = {
    Text = "Wir haben ein Versprechen gemacht..."
  },
  AvgDialog_34968_Content_17 = {
    Text = "Ich werde nicht aufhören, an sie zu glauben."
  },
  AvgDialog_34968_Content_18 = {
    Text = "Bist du es... %player%...?"
  },
  AvgDialog_34968_Content_19 = {
    Text = "Murphy kämpfte darum, sich aufzusetzen und blickte benommen umher."
  },
  AvgDialog_34968_Content_2 = {
    Text = "Mein Kopf... tut weh..."
  },
  AvgDialog_34968_Content_20 = {
    Text = "Die Leute, die sie kannte, waren nicht weit entfernt versammelt und flüsterten über etwas. Erst als Murphy sprach, wandte sich jeder um zu schauen"
  },
  AvgDialog_34968_Content_21 = {
    Text = "Murphy! Wie fühlst du dich jetzt?"
  },
  AvgDialog_34968_Content_22 = {
    Text = "Die Szene vor ihm wurde allmählich klarer. Murphy rieb sich die Augen und stellte dann fest, dass im Zentrum des Eingreifens %player% war, der friedlich schlief."
  },
  AvgDialog_34968_Content_23 = {
    Text = "{Male=Er,Female=Sie}, was ist los mit {Male=er,Female=sie}?"
  },
  AvgDialog_34968_Content_24 = {
    Text = "Ich weiß nicht... %player% hat keine sichtbaren Verletzungen und sollte nicht so plötzlich ohnmächtig geworden sein."
  },
  AvgDialog_34968_Content_25 = {
    Text = "Meine Verbindung zu {Male=er,Female=sie} ist sehr stabil. So stabil, dass es fast unheimlich ist"
  },
  AvgDialog_34968_Content_26 = {
    Text = "Wir haben vor dem Verlassen der Schule eine routinemäßige Kontrolle durchgeführt. %player% war zu diesem Zeitpunkt noch stabil..."
  },
  AvgDialog_34968_Content_27 = {
    Text = "Murphy, hat %player% sich seltsam verhalten, als ihr zusammen wart?"
  },
  AvgDialog_34968_Content_28 = {
    Text = "Du meinst nach der Explosion, bevor wir dich in der Frachtkammer gefunden haben? Lass mich nachdenken..."
  },
  AvgDialog_34968_Content_29 = {
    Text = "Eh, eh?! Schreck mich nicht! Stirb nicht für mich!"
  },
  AvgDialog_34968_Content_3 = {
    Text = "Wo ist dieser Ort... %player%? Wo bist du?"
  },
  AvgDialog_34968_Content_30 = {
    Text = "Ich... Mir geht's gut..."
  },
  AvgDialog_34968_Content_31 = {
    Text = "Wach auf, %player%, wach auf."
  },
  AvgDialog_34968_Content_32 = {
    Text = "Tu das nicht, erschrecke mich nicht... Schlaf nicht ein, wach auf."
  },
  AvgDialog_34968_Content_33 = {
    Text = "Mindestens zweimal... Das erste Mal war, als ich versuchte, jemanden mit diesem Rückverfolgen-Trick zu finden, und das zweite Mal, als er plötzlich zusammenbrach, aber kurz danach wieder aufwachte."
  },
  AvgDialog_34968_Content_34 = {
    Text = "{Male=Er,Female=Sie}... Wird {Male=er,Female=sie} in Ordnung sein?"
  },
  AvgDialog_34968_Content_35 = {
    Text = "Ramona sah ihren Partner an – {Male=er,Female=sie} lag reglos neben ihr und war tief in den Strudel der Ohnmacht versunken, ihr Gesicht war rot und ruhig, als ob sie wirklich nur einen schönen Traum träumte"
  },
  AvgDialog_34968_Content_36 = {
    Text = "In ihrem Herzen stieg ein unbeschreibliches Gefühl auf, als ihr Blick auf das ruhige Gesicht ihres Partners ruhte und die gesamte Welt zum Schweigen brachte."
  },
  AvgDialog_34968_Content_37 = {
    Text = "Ich... Ich weiß nicht...\nVielleicht kann mir jemand in der Schule helfen, aber ich..."
  },
  AvgDialog_34968_Content_38 = {
    Text = "Die Schule kontaktieren? Vielleicht versuchen, ein Funktelegramm zu senden..."
  },
  AvgDialog_34968_Content_39 = {
    Text = "Der Kapitän schluckte die zweite Hälfte seines Satzes herunter."
  },
  AvgDialog_34968_Content_4 = {
    Text = "Sie erhielt keine Antwort von irgendjemandem; das einzige Geräusch, das in der tiefen Dunkelheit widerhallte, war der unaufhörliche Fluss von Wasser."
  },
  AvgDialog_34968_Content_40 = {
    Text = "Die Funkgeräte befinden sich im Cockpit, aber klar — jetzt dort zurückzukehren wäre ein Todeswunsch."
  },
  AvgDialog_34968_Content_41 = {
    Text = "Kommunikator, hast du diesen magischen Kommunikator nicht?"
  },
  AvgDialog_34968_Content_42 = {
    Text = "Ramonas Augen leuchteten auf, die dunkle Aura um sie löste sich auf. Sie verspottete heimlich ihren eigenen Verlust der Fassung und Panik, während sie ihre Hand hob, um den Abzeichenkommunikator zu betätigen."
  },
  AvgDialog_34968_Content_43 = {
    Text = "Zzz—Zzzz—"
  },
  AvgDialog_34968_Content_44 = {Text = "Ra...&*"},
  AvgDialog_34968_Content_45 = {
    Text = "Doll?! Bist du das, Doll?!"
  },
  AvgDialog_34968_Content_46 = {
    Text = "Geheimnis...%#...Schiff**...?"
  },
  AvgDialog_34968_Content_47 = {
    Text = "Kann ich dich nicht hören. Wir sind immer noch zu weit vom Land entfernt, außerhalb der effektiven Reichweite des Kommunikators."
  },
  AvgDialog_34968_Content_48 = {
    Text = "Warte, vielleicht kann ich die Leistung des Kommunikationsgeräts vorübergehend verbessern."
  },
  AvgDialog_34968_Content_49 = {
    Text = "Ramona entfernte entschlossen die Brosche und verwendete schnell eine große Nadel, um das Gehäuse des Kommunikators aufzubrechen."
  },
  AvgDialog_34968_Content_5 = {
    Text = "Wasser, endloses Wasser."
  },
  AvgDialog_34968_Content_50 = {
    Text = "Wo... hast du diese Nadel her?"
  },
  AvgDialog_34968_Content_51 = {
    Text = "Es ist besser, auf Nummer sicher zu gehen als zu bedauern; vorbereitet zu sein, schadet nie."
  },
  AvgDialog_34968_Content_52 = {
    Text = "Ramona fiddelte mit der Struktur im Kommunikator herum. In kürzester Zeit durchbrach sie mit einer einfachen Nadel die letzte Verteidigung des Energiezentrums."
  },
  AvgDialog_34968_Content_53 = {
    Text = "Ein leise wirbelnder Silber erscheint plötzlich vor allen"
  },
  AvgDialog_34968_Content_54 = {
    Text = "Silber... Also wurden die Silbers, die den gnostischen Index für das Erwachen nicht erreichen konnten, zu Werkzeugen gemacht?"
  },
  AvgDialog_34968_Content_55 = {
    Text = "Lass uns die detaillierte Erklärung der Prinzipien und die ethische Debatte aufheben, bis wir wieder in der Schule sind."
  },
  AvgDialog_34968_Content_56 = {
    Text = "Next, I'll short-circuit the communicator core to temporarily boost its performance with a massive burst of Gnosis energy."
  },
  AvgDialog_34968_Content_57 = {
    Text = "Dies ist theoretisch machbar, aber ich habe es noch nie versucht... Ich brauche etwas Zeit."
  },
  AvgDialog_34968_Content_58 = {
    Text = "In zwei Minuten"
  },
  AvgDialog_34968_Content_59 = {
    Text = "Murphy, kannst du diesen Teil für mich festhalten?"
  },
  AvgDialog_34968_Content_6 = {
    Text = "Die schwarzen Wellen, höher als der höchste Berg in Elworth, stürzen direkt in die Stadt und zerstören und verschlingen sowohl die Geschichte als auch die Zukunft..."
  },
  AvgDialog_34968_Content_60 = {
    Text = "Wofür wird das benutzt?"
  },
  AvgDialog_34968_Content_61 = {
    Text = "Dies ist ein Sicherheitsgerät, das verwendet wird, um das Silber zu stabilisieren. Nach dem Entfernen kann das speziell aktivierte Silber von mir kurzgeschlossen werden."
  },
  AvgDialog_34968_Content_62 = {
    Text = "Halte es stabil. Wir müssen es später wieder installieren. Ohne diesen Sicherheitsverschluss kann der Kommunikationskern nicht abkühlen und könnte explodieren."
  },
  AvgDialog_34968_Content_63 = {Text = "Eek?!"},
  AvgDialog_34968_Content_64 = {
    Text = "Eine Minute später"
  },
  AvgDialog_34968_Content_65 = {
    Text = "Ramona manipulierte geschickt die Innereien des Kommunikationsgeräts mit einer Nadel, indem sie Zahnräder und Metalldrähte unbekannter Funktion neu anordnete."
  },
  AvgDialog_34968_Content_66 = {
    Text = "Abgeschlossen!"
  },
  AvgDialog_34968_Content_67 = {
    Text = "Murphy kauert neben Ramona, zitternd, während er die Teile hielt. Doch als er die Worte hörte, beugte er sich neugierig näher."
  },
  AvgDialog_34968_Content_68 = {
    Text = "Ist das ausreichend?"
  },
  AvgDialog_34968_Content_69 = {
    Text = "Gerade einen letzten Schritt. Alle, schließt die Augen und schaut nicht in diese Richtung."
  },
  AvgDialog_34968_Content_7 = {
    Text = "Das ist das göttliche Orakel, das du gegeben hast, ohne Tadel."
  },
  AvgDialog_34968_Content_70 = {
    Text = "Ramona sagte, während sie Murphy die Augen mit ihrer Hand bedeckte."
  },
  AvgDialog_34968_Content_71 = {
    Text = "Ein blendendes weißes Licht brach aus dem Kommunikationsgerät hervor, wie ein Blitz am Himmel, der das gesamte Frachtraum in blassem Weiß erleuchtete."
  },
  AvgDialog_34968_Content_72 = {
    Text = "Energie brach wie wütende Wellen aus und verbreitete sich sofort."
  },
  AvgDialog_34968_Content_73 = {
    Text = "Diese Energie summte, wie der Klang aus dem tiefen Weltraum, was den Kommunikator einen mysteriösen Schein emittieren ließ, als ob er mit den fernen Sternen verbunden wäre"
  },
  AvgDialog_34968_Content_74 = {
    Text = "Ramona? Kannst du mich klar hören?"
  },
  AvgDialog_34968_Content_75 = {
    Text = "Ich war noch nie so begierig darauf, deine Stimme zu hören..."
  },
  AvgDialog_34968_Content_76 = {
    Text = "Um die Kommunikation zu stabilisieren, habe ich zwanzigmal die tägliche Silbernmenge verbrannt.\nKurz gesagt, wie geht es dir?"
  },
  AvgDialog_34968_Content_77 = {
    Text = "Ramona erzählte der Puppe kurz alles, was auf dem Schiff passiert ist: das Auflösungsritual, den Seefahrer-Kult, Murphy und das Ohnmächtigwerden des Hüters..."
  },
  AvgDialog_34968_Content_78 = {
    Text = "Wir benötigen Franciskus' experimentelle Ergebnisse, um das Wachstum des \"Gottes\" zu stoppen... Ich verstehe.\nBring das Mädchen zurück zur Schule, und Winkle und ich werden den Raum vorbereiten."
  },
  AvgDialog_34968_Content_79 = {
    Text = "Winkle, wir haben zwei Stunden Zeit, um die Verteidigungsmaßnahmen gegen Hunde zu verstärken."
  },
  AvgDialog_34968_Content_8 = {
    Text = "Wer ist da... Nein, diese Stimme ist..."
  },
  AvgDialog_34968_Content_80 = {
    Text = "Das Experiment ist noch instabil, noch instabil... Es muss jetzt etwas unternommen werden! Andernfalls wird es außer Kontrolle geraten—es steht schon am Rande!"
  },
  AvgDialog_34968_Content_81 = {
    Text = "Erica, zieh Winkle runter."
  },
  AvgDialog_34968_Content_82 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_34968_Content_83 = {
    Text = "Erica fand einige Informationen über die Seefahrer im Archiv, aber erwarte nicht zu viel—es gibt nur ein wenig."
  },
  AvgDialog_34968_Content_84 = {
    Text = "\nAls die große Flut auftrat, gab es Augenzeugenberichte aus der Neuen Welt.\nEine Gruppe von \"hässlichen, fischähnlichen\" Flüchtlingen überquerte das Meer und verschwand in der Flut."
  },
  AvgDialog_34968_Content_85 = {
    Text = "Der Legende nach behaupten sie, die Erben einer alten Zivilisation zu sein, deren Blut von den \"Göttern\" in ihre Adern geflossen ist."
  },
  AvgDialog_34968_Content_86 = {
    Text = "Diese Menschen wurden als Menschen geboren, aber das göttliche Blut hat sie allmählich in das verwandelt, was du jetzt siehst."
  },
  AvgDialog_34968_Content_87 = {
    Text = "So wird der Junge schließlich das Aussehen eines Meermanns annehmen..."
  },
  AvgDialog_34968_Content_88 = {
    Text = "Sprichst du von Caecus? Wenn du etwas über ihn wissen möchtest, kann ich es dir sagen."
  },
  AvgDialog_34968_Content_89 = {
    Text = "Ramona nickte und signalisierte dem Kapitän, fortzufahren."
  },
  AvgDialog_34968_Content_9 = {
    Text = "Der treueste Gläubige des Gottesreichs, der Aufstieg und Fall der Nation... liegt in deinen Händen."
  },
  AvgDialog_34968_Content_90 = {
    Text = [[
Wenn wir von Caecus sprechen... dieses Kind ist ein Golem, in deinen Worten, ein Erwacher.
Wahrscheinlich mit Miryam verbunden.]]
  },
  AvgDialog_34968_Content_91 = {
    Text = "Verknüpfung mit Miryam?! Ein Erwecker mit einem anderen zu verknüpfen ist unbekannt..."
  },
  AvgDialog_34968_Content_92 = {
    Text = "Ha, diese Frau ist wirklich ein Monster."
  },
  AvgDialog_34968_Content_93 = {
    Text = "Um mich in Schach zu halten, verabreichte der Kult regelmäßig Medikamente, um meinen Geist zu stabilisieren. Nachdem der vorherige Kontakt den Verstand verlor, wurde Caecus der neue Lieferant."
  },
  AvgDialog_34968_Content_94 = {
    Text = "Wir haben uns in diesen Jahren jedes Quartal getroffen... Ich habe ihm beigebracht, wie man trinkt und angelt, ihm den Morgenstern im Sommer gezeigt und ihm geholfen, im Winter trockene Schuppen zu entfernen..."
  },
  AvgDialog_34968_Content_95 = {
    Text = "Haha... Ich dachte, wir wären schon Freunde. Als er mir sagte, er könnte mir das Medikament ein letztes Mal geben, zögerte ich nicht."
  },
  AvgDialog_34968_Content_96 = {
    Text = "Aber... er war es, der den Kult über den Aufenthaltsort des Sonanil informierte."
  },
  AvgDialog_34968_Content_97 = {
    Text = "Niemand hat ihm beigebracht, was richtig ist, noch fand er einen Sinn über das Sein eines Seefahrers hinaus."
  },
  AvgDialog_34968_Content_98 = {
    Text = "Wenn es ihm in seinen Augen hilft, mich auszuliefern, um seine Position im Orden zu sichern... werde ich es ihm nicht verübeln."
  },
  AvgDialog_34968_Content_99 = {
    Text = "Der plötzliche Zusammenstoß von Metall hallte wider. Ramona nahm schnell eine Abwehrhaltung ein und schützte den Kapitän und Murphy."
  },
  AvgDialog_34969_Content_1 = {
    Text = "Das Schiff knarrt erneut, durch Wind und Wellen geschüttelt, und schwankt heftig, während mechanische Trümmer überall rollen."
  },
  AvgDialog_34969_Content_10 = {
    Text = "Nein, ich würde mich unwohl fühlen, eine verletzte Person um Arbeit zu bitten."
  },
  AvgDialog_34969_Content_11 = {
    Text = "Sie musterte dich von Kopf bis Fuß und wandte sich dann schüchtert ab."
  },
  AvgDialog_34969_Content_12 = {
    Text = "Doch... danke."
  },
  AvgDialog_34969_Content_13 = {
    Text = "Was war dieser Schlag gerade eben? Celeste sollte das Schiff besser nicht in eine versteckte Strömung gesteuert haben..."
  },
  AvgDialog_34969_Content_14 = {
    Text = "Ich denke... Celeste verliert die Kontrolle über das Sonaniel.\nAlle von der Explosionsstelle wegzubewegen, könnte ihre Kraft erschöpft haben."
  },
  AvgDialog_34969_Content_15 = {
    Text = "Sie war bereits schwach, und jetzt ist es noch schlimmer..."
  },
  AvgDialog_34969_Content_16 = {
    Text = "Murphy drückte sich auf die Brust und zwängte ein verlegendes Lächeln hervor."
  },
  AvgDialog_34969_Content_17 = {
    Text = "Es ist in Ordnung. Sobald wir an Land zurückkehren, wird alles ein Ende finden..."
  },
  AvgDialog_34969_Content_18 = {
    Text = "Die flackernde Frequenz des Lichts synchronisierte sich allmählich mit dem Atmen. Als die Kabine plötzlich dunkel wurde, blieb der Feind nicht länger zufrieden, im Schatten zu lauern..."
  },
  AvgDialog_34969_Content_2 = {Text = "Oh je?!"},
  AvgDialog_34969_Content_3 = {
    Text = "Ein weiterer unheimlicher Knacks, wie das Knacken von Knochen, hallte aus einer unbekannten Richtung. Bevor du und Murphy reagieren konntet, wankte das Schiff plötzlich heftig zur Seite, als ob es an die Spitze einer Welle gedrängt worden wäre."
  },
  AvgDialog_34969_Content_4 = {Text = "Murphy!"},
  AvgDialog_34969_Content_5 = {
    Text = "Du hast das hervorstehende Metallrohr gegriffen, um deinen Körper zu stabilisieren, aber als du versuchtest, Murphy zu helfen, war sie bereits zum anderen Ende des Kraftwerks gestolpert."
  },
  AvgDialog_34969_Content_6 = {
    Text = "Keine Sorgen! Schreie nicht, als würde ich sterben."
  },
  AvgDialog_34969_Content_7 = {
    Text = "Die Hütte kehrte schnell zur Ruhe zurück, nur das Chaos auf dem Boden dient als Beweis für das gewaltsame Beben, das stattgefunden hatte."
  },
  AvgDialog_34969_Content_8 = {
    Text = "Murphy, die immer noch sichtbar erschüttert war, ging auf dich zu, während sie sich an der Kabinenwand festhielt, ihre Beine zitterten unkontrollierbar."
  },
  AvgDialog_34969_Content_9 = {
    Text = "Bist du irgendwo gegen gestoßen? Brauchst du Hilfe beim Gehen?"
  },
  AvgDialog_34970_Content_1 = {
    Text = "Schnell! Du gehst zuerst rein, ich halte den Rücken frei."
  },
  AvgDialog_34970_Content_10 = {
    Text = "Was ist das...?"
  },
  AvgDialog_34970_Content_11 = {
    Text = "Du näherst dich einem Korallenstück; es leuchtet sanft, elegant und schön. Ähnliche Objekte können Preise von Zehntausenden von LeiOu Fang in Londiniums Auktionshäusern erzielen."
  },
  AvgDialog_34970_Content_12 = {
    Text = "—Wenn seine Wurzeln nicht tief in einer kleinen D-Marke verankert wären."
  },
  AvgDialog_34970_Content_13 = {
    Text = "Es ist D-Hyperplasie."
  },
  AvgDialog_34970_Content_14 = {
    Text = "Im Kurs \"Grundlagen der D-Phänomen\" beschrieb die Puppe einmal Anomalien so: Wenn sich das D-Phänomen bis zu einem bestimmten Stadium entwickelt, besteht die Wahrscheinlichkeit, dass Anomalien aus D-Marken entstehen können."
  },
  AvgDialog_34970_Content_15 = {
    Text = "Das Wachstum und die Verbreitung von abweichenden Entitäten verschiedener Typen sind noch nicht zusammengefasst worden, aber eines ist klar: Abweichende Entitäten erscheinen allgemein nur in Gebieten mit \"Katastrophen\"."
  },
  AvgDialog_34970_Content_16 = {
    Text = "Diese Dinge stehen unzweifelhaft mit dem Ozean in Zusammenhang. Es muss „Clades“ geben, die mit dem Tiefsee-Reich um uns herum verbunden sind."
  },
  AvgDialog_34970_Content_17 = {
    Text = "\"Katastrophen\"..."
  },
  AvgDialog_34970_Content_18 = {
    Text = "Murphy ging zu deiner Seite und sah auf die D-Mark am Fuße des Wuchses. Sie legte eine Hand auf ihre Brust und die andere auf die raue Oberfläche des Koralls."
  },
  AvgDialog_34970_Content_19 = {
    Text = "Du hörst, wie ein schwerer Gegenstand hinter dir fällt. Als du dich umdrehst, triffst du den Blick eines Seefahrers, der von einem grotesken Wachstum festgehalten wird."
  },
  AvgDialog_34970_Content_2 = {
    Text = "Murphy zögerte nicht und zeigte keine Abneigung, und schlüpfte schnell durch die Tür, die du hieltst."
  },
  AvgDialog_34970_Content_20 = {Text = "Goo..."},
  AvgDialog_34970_Content_21 = {
    Text = "Murphy fiel in eine langanhaltende Stille. Als sie keine Reaktion von ihr sahst, tratst du vor und positioniertest dich zwischen ihr und dem Seefahrer."
  },
  AvgDialog_34970_Content_3 = {
    Text = "Mutanten und Meereslebewesen verfolgen dich nach Geruch. Gerade bevor die Krallen deinen Umhang greifen können, drehst du dich um und schlüpfst durch die Tür."
  },
  AvgDialog_34970_Content_4 = {
    Text = "Du stemmst die Tür mit deinem Körper, während Murphy versucht, die Luke von innen zu verriegeln. Dein Duft und Aussehen sind verborgen, und das Kratzen der Krallen auf dem Stahl verklingt bald."
  },
  AvgDialog_34970_Content_5 = {
    Text = "Huch, huch... Du kannst wirklich verfolgen."
  },
  AvgDialog_34970_Content_6 = {
    Text = "Murphy, geh und mach das Licht an... huh?!"
  },
  AvgDialog_34970_Content_7 = {
    Text = "Als ich mich umdrehte, sprang unheimliches Fluoreszenzlicht in meine Netzhaut."
  },
  AvgDialog_34970_Content_8 = {
    Text = "Astartige Strukturen wachsen gewalttätig aus den Rissen auf dem Deck, verwinden sich und drücken gegeneinander, um mehr Platz zu schaffen. Mit einer Reihe von „knack“ Geräuschen bricht das Deck unter dem Druck zusammen."
  },
  AvgDialog_34970_Content_9 = {
    Text = "Es waren Korallen, Anemonen und weitere Meereslebewesen, die du nicht benennen konntest, stark und voller Kraft, Stück für Stück die Deckoberfläche aufbohrend."
  },
  AvgDialog_34971_Content_1 = {
    Text = "Du trägst Murphy auf deinem Rücken und flehst mit dem Kapitän und Celeste aus dem Cockpit, wobei Ramona dicht hinter euch folgt."
  },
  AvgDialog_34971_Content_10 = {
    Text = "Goliath, warum?"
  },
  AvgDialog_34971_Content_11 = {
    Text = "Warum? Zu welchem Zweck?"
  },
  AvgDialog_34971_Content_12 = {
    Text = "Du hast vorgetäuscht, Miryam zu gehorchen, aber hast uns absichtlich während der Verfolgung mehrere Male entkommen lassen..."
  },
  AvgDialog_34971_Content_13 = {
    Text = "Diskutiere nicht, du hast es zu offensichtlich gemacht."
  },
  AvgDialog_34971_Content_14 = {
    Text = "Ich glaube nicht, dass du Miryam im Kraftwerk ohne Absicht provoziert hast—du willst keinen direkteren Konflikt mit uns, oder besser gesagt, mit Tulu."
  },
  AvgDialog_34971_Content_15 = {
    Text = "Bei der Erwähnung von Tulu pocht dein Kopf vor unerklärlichem Schmerz. Diese Qual ist unbeschreiblich, wie ein Mitternachtssturm, der deinen Verstand verwüstet, deine Nerven und deinen Willen durchbrennt."
  },
  AvgDialog_34971_Content_16 = {Text = "Ugh..."},
  AvgDialog_34971_Content_17 = {
    Text = "Schwindelerregende Vorahnungen blitzen vor deinen Augen auf. Dieses tief in die Seele eindringende Gefühl fühlt sich wie ein unaussprechlicher Schmerz an, der immer wieder beinahe geheilte Wunden in deiner Seele aufreißt und zunäht."
  },
  AvgDialog_34971_Content_18 = {
    Text = "Keeper? Keeper?"
  },
  AvgDialog_34971_Content_19 = {
    Text = "Ramona scheint deinen Unbehagen bemerkt zu haben. Während sie auf Goliath achtet, berührt sie vorsichtig den Arm, mit dem du Murphy abstützt."
  },
  AvgDialog_34971_Content_2 = {
    Text = "Als ich gerade die Stufen hinuntergehen wollte, sprang der Riese von oben herab."
  },
  AvgDialog_34971_Content_20 = {
    Text = "Mir geht's gut."
  },
  AvgDialog_34971_Content_21 = {
    Text = "Du antwortest leise auf Romanas Besorgnis, atmest tief durch, um den salzigen Meeresduft den metallischen Blutgeruch unterdrücken zu lassen."
  },
  AvgDialog_34971_Content_22 = {
    Text = "Dann siehst du endlich zu Goliath auf. Er beobachtet dich mit großem Interesse, scheinbar belustigt über deine schmerzhaften Bewegungen, mit einem selbstzufriedenen und arroganten Lächeln auf seinem Gesicht."
  },
  AvgDialog_34971_Content_23 = {
    Text = "Offensichtlich... bist du nicht ganz loyal zu dem Seefahrer; du siehst sogar auf ihren Glauben und ihre Götter herab..."
  },
  AvgDialog_34971_Content_24 = {
    Text = "Miryam wurde besiegt. Es gibt jetzt keinen Grund für Feindschaft zwischen uns.\nWarum bist du so besessen von Murphy?"
  },
  AvgDialog_34971_Content_25 = {
    Text = "Da du klar sterben willst, warum nutzt du dein cleveres Gehirn nicht, um den Grund zu ermitteln?"
  },
  AvgDialog_34971_Content_26 = {
    Text = "Das Märtyrium des Hohepriesters ließ die Seefahrer ohne Anführer zurück."
  },
  AvgDialog_34971_Content_27 = {
    Text = "Egal ob ich ein neues Reich gründe oder weiterhin diese Gefährten in die Ewigkeit führe... Sag mir, was soll ich tun?"
  },
  AvgDialog_34971_Content_28 = {
    Text = "...dominante Macht."
  },
  AvgDialog_34971_Content_29 = {
    Text = "Du wirst der Anführer der Seefahrer und der einzige neue Kopf des Ordens werden."
  },
  AvgDialog_34971_Content_3 = {Text = "Vorsicht!"},
  AvgDialog_34971_Content_30 = {
    Text = "Für dies... benötigst du \"die Mutter Göttin\", und du musst dieses Ritual formell abschließen, um deine Position innerhalb des Seefahrer-Kults zu festigen..."
  },
  AvgDialog_34971_Content_31 = {
    Text = "Obwohl sie an der Universität aufgezogen wurde, ist dieser Welpe ziemlich scharfsinnig."
  },
  AvgDialog_34971_Content_32 = {
    Text = "Überlasse Murphy mir.\nWenn du jetzt kooperierst, verspreche ich, dass meine Legion dich verschonen wird, wenn wir die menschliche Zivilisation später zerschlagen."
  },
  AvgDialog_34971_Content_33 = {
    Text = "Verschwende keine Mühe"
  },
  AvgDialog_34971_Content_34 = {
    Text = "Habe ich... nie nach deinem Namen gefragt...?"
  },
  AvgDialog_34971_Content_35 = {
    Text = "Seit meiner Kindheit, wenn ich eine äußere Verletzung hatte, haben sie mir immer dieses Medikament aufgetragen."
  },
  AvgDialog_34971_Content_36 = {
    Text = "Wie ist es? Geht der Schmerz nicht sofort weg, wenn du es anwendest?"
  },
  AvgDialog_34971_Content_37 = {
    Text = "Das Gewicht des Körpers des Mädchens drückt auf dich und lässt deinen Rücken und deine Glieder unkontrollierbar zittern"
  },
  AvgDialog_34971_Content_38 = {
    Text = "Wir haben versprochen, sie zurückzubringen und sie von dem parasitären \"Gott\" zu befreien."
  },
  AvgDialog_34971_Content_39 = {
    Text = "Du bissest die Zähne zusammen und trägst das Gewicht der Seele."
  },
  AvgDialog_34971_Content_4 = {
    Text = "Ramona huschte vor dich."
  },
  AvgDialog_34971_Content_40 = {
    Text = "Ich werde nicht aufhören, an sie zu glauben."
  },
  AvgDialog_34971_Content_41 = {
    Text = "Eine Folge von Summen ertönt in deinen Ohren, chaotische Flötenklänge spielen zwischen dem Summen."
  },
  AvgDialog_34971_Content_42 = {
    Text = "Diese absurde Symphonie lässt Ihre Augenlider zucken und füllt Ihr Gehirn mit Unbehagen und Chaos."
  },
  AvgDialog_34971_Content_43 = {
    Text = "Du fühlst eine ungewöhnliche, vertraute Erschöpfung, wie nie zuvor. Deine Nerven sind allmählich gelähmt, und deine Glieder beginnen schwach zu werden."
  },
  AvgDialog_34971_Content_44 = {
    Text = "Die Welt vor deinen Augen wird wellenartig dunkler, ein schwerer schwarzer Schleier hüllt deine Welt leise ein. Geräusche und das ganze Chaos scheinen zu verblassen, während der Klang einer stillen Flöte sanft dein Bewusstsein wie eine unsichtbare Feder berührt."
  },
  AvgDialog_34971_Content_45 = {
    Text = "Kann ich nicht schlafen... Kann ich nicht einschlafen."
  },
  AvgDialog_34971_Content_46 = {
    Text = "Du kämpfst gegen diese unverständliche Schläfrigkeit, aber vergebens. Ramonasa Stimme verblasst schnell, und bevor du realisierst, was passiert, fällst du schwer zu Boden."
  },
  AvgDialog_34971_Content_47 = {Text = "Bild..."},
  AvgDialog_34971_Content_49 = {
    Text = "Dein Gehirn hat Schwierigkeiten, das Geschehen zu verarbeiten, aber eines ist sicher: die algengrünen Tentakel blockierten die Klinge des Riesen, und sie fühlen sich wahrscheinlich so weich an wie Orangensaft."
  },
  AvgDialog_34971_Content_5 = {
    Text = "Ich bewundere diejenigen, die den Mut haben, zurückzukämpfen, aber ich verachte Narren, die ihren Platz nicht erkennen."
  },
  AvgDialog_34971_Content_7 = {
    Text = "Goliath brach nicht nur die bereits verwitterte eiserne Außentreppe, sondern blockierte auch deinen Weg mit seiner riesigen Klinge."
  },
  AvgDialog_34971_Content_8 = {
    Text = "Mythag-Studenten... Ha, so naiv."
  },
  AvgDialog_34971_Content_9 = {
    Text = "Glaubst du wirklich, dass du entkommen kannst? Mit diesem wackeligen alten Schiff, diesem kaum intakten Golem und ihrer Verknüpfung?"
  },
  AvgDialog_34972_Content_1 = {
    Text = "Scheiterlaus"
  },
  AvgDialog_34972_Content_10 = {
    Text = "Caecus senkte seinen Kopf und betrachtete seine Schwanzflosse, die von den Flammen verbrannt und braun geblieben war, und schwieg."
  },
  AvgDialog_34972_Content_11 = {
    Text = "Was den lieben Hochpriester betrifft..."
  },
  AvgDialog_34972_Content_12 = {
    Text = "Als Goliath sprach, fegte sein dominierender Blick über euch alle und blieb schließlich bei Celeste und dem Kapitän hängen."
  },
  AvgDialog_34972_Content_13 = {
    Text = "Ich fürchte, sie werden nicht freundlich genug sein, um den hohen Priester aus dem Epizentrum der Explosion zu retten, oder?"
  },
  AvgDialog_34972_Content_14 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_34972_Content_15 = {
    Text = "Gehe, Caecus.\nZeig mir, was du kannst, und beweis, dass du das Zeug hast, zu meinen Reihen zu stoßen."
  },
  AvgDialog_34972_Content_16 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_34972_Content_17 = {
    Text = "Ja, Lord Goliath."
  },
  AvgDialog_34972_Content_18 = {
    Text = "Caecus, was hast du vor!"
  },
  AvgDialog_34972_Content_19 = {
    Text = "Caecus warf einen Blick auf den Kapitän, wollte etwas sagen, zögerte jedoch. \nNach einigen Momenten der Stille holte er schließlich tief Luft, als würde er sich auf eine Entscheidung vorbereiten."
  },
  AvgDialog_34972_Content_2 = {
    Text = "Goliath beugte sich hinunter, um in die Kabine zu gelangen, sein massiver Körper blockierte fast vollständig die Tür auf einer Seite."
  },
  AvgDialog_34972_Content_20 = {
    Text = "Entschuldigung, Herr Elton."
  },
  AvgDialog_34972_Content_21 = {
    Text = "Er schwang seine Waffe und schlug zweimal gegen die Kabinenwand."
  },
  AvgDialog_34972_Content_22 = {
    Text = "Das massive Echo von Metall hallt durch den Raum, wie das wütende Gebrüll der Dunkelheit, die in einer hoffnungslosen Tiefe gefangen ist, und lässt denjenigen, der das Geräusch gemacht hat, taub fühlen."
  },
  AvgDialog_34972_Content_23 = {
    Text = "Seefahrer! Die Zeit des stellaren Ausrichtens naht!"
  },
  AvgDialog_34972_Content_24 = {
    Text = "Im Namen von Lord Goliath, hole die Heilige Mutter von den Narren zurück!\nDas Ritual wird heute Nacht stattfinden!"
  },
  AvgDialog_34972_Content_3 = {
    Text = "Du bist viel schlauer als diese arroganten Narren.\nJetzt zögere ich, dir die volle Macht von Aequor zu gewähren."
  },
  AvgDialog_34972_Content_4 = {
    Text = "Es scheint nützlicher, dich in dieser halb menschlichen, halb fischlichen Form zu halten."
  },
  AvgDialog_34972_Content_5 = {
    Text = "Meister! Der Hohe Priester hat mir einst einen perfekten Körper versprochen..."
  },
  AvgDialog_34972_Content_6 = {
    Text = "Das Atmen des jungen Seefahrers stoppte; seine fischartigen Augen weiteten sich angespannt und fixierten Goliath."
  },
  AvgDialog_34972_Content_7 = {
    Text = "Hochpriester? Pssst..."
  },
  AvgDialog_34972_Content_8 = {
    Text = "Goliath bemerkte den Blick des Jungen nicht oder besser gesagt, die unbedeutende Leidenschaft des Jungen rechtfertigte nicht seine Aufmerksamkeit."
  },
  AvgDialog_34972_Content_9 = {
    Text = "Du hast die Explosion im Kraftwerk persönlich miterlebt. Ihre Kraft war für uns beide offensichtlich zu sehen.\nOhne mich wärst du jetzt in einen Haufen silbernen Staubes zerfetzt worden."
  },
  AvgDialog_34973_Content_1 = {
    Text = "Unter Ramona's Deckung machen Sie sich auf den Weg die Treppe hinauf. Elton hilft Ihnen, Murphys Gewicht zu tragen. Dennoch ist es immer noch ziemlich anstrengend, den vierstöckigen Brückenturm zu erklimmen."
  },
  AvgDialog_34973_Content_10 = {
    Text = "Hüter, ihr dürft jetzt eintreten."
  },
  AvgDialog_34973_Content_11 = {
    Text = "Du nickst und legst mit Ramonas Hilfe Murphy nieder."
  },
  AvgDialog_34973_Content_12 = {
    Text = "Ihr Atem wurde regelmäßiger, nicht mehr so schwerfällig wie zuvor."
  },
  AvgDialog_34973_Content_13 = {
    Text = "Es scheint, dass ihr Körper sich vorübergehend an die Hypoxie, die durch den Parasiten verursacht wurde, angepasst hat.\nAber wenn dieser Zustand zu lange anhält, fürchte ich, dass er irreversible Nachwirkungen verursachen könnte."
  },
  AvgDialog_34973_Content_14 = {
    Text = "Hmm, ich muss sie schnell hier herausbekommen."
  },
  AvgDialog_34973_Content_15 = {
    Text = "Captain, wie ist die Lage im Cockpit?"
  },
  AvgDialog_34973_Content_16 = {
    Text = "Einige Ausrüstungsteile wurden beschädigt, und die Schalter für die Pfeife und das Radio sind festgeklebt. Glücklicherweise bleibt das zentrale Stromkontrollsystem und das Steuer intakt."
  },
  AvgDialog_34973_Content_17 = {
    Text = "Elton sprach, während er geschickt das zentrale Rad drehte und einen Kolben nach dem anderen herauszog."
  },
  AvgDialog_34973_Content_18 = {
    Text = "Du späherst aus der Luke und schaust über das Deck. Einige fassförmige Geräte, wahrscheinlich Entlüftungsrohre, geben weiße Rauchwölkchen ab. Schon bald kommen Spritzgeräusche vom Heck."
  },
  AvgDialog_34973_Content_19 = {
    Text = "Ist das das Geräusch des Ruders in Betrieb? Wir ändern den Kurs."
  },
  AvgDialog_34973_Content_2 = {
    Text = "Huch, huch... Endlich angekommen."
  },
  AvgDialog_34973_Content_20 = {
    Text = "Elton nickte und ließ einen tiefen Seufzer entweichen."
  },
  AvgDialog_34973_Content_21 = {
    Text = "Der Sonanil ist ein großes Schiff, daher manövriert es langsam und unbeholfen. Sobald die Kurve jedoch abgeschlossen ist, können wir mit voller Geschwindigkeit zurückkehren."
  },
  AvgDialog_34973_Content_22 = {
    Text = "Wie geht es Murphy?"
  },
  AvgDialog_34973_Content_23 = {
    Text = "Keine Anzeichen weiterer Verschlechterung bislang, aber der Parasit drückt auf ihr Herz und beeinträchtigt die normale Zirkulation ihrer Organe..."
  },
  AvgDialog_34973_Content_24 = {
    Text = "Außerdem ist dieses Parasiten der Ursprungspunkt der Auflösungs-Katastrophen geworden. Da ich so nah mit <Yellow:\"Clades Core\"> in Kontakt bin, befürchte ich, dass Murphy auch von der Auflösung betroffen sein könnte..."
  },
  AvgDialog_34973_Content_25 = {
    Text = "D-Phänomen... Schon wieder ein D-Phänomen."
  },
  AvgDialog_34973_Content_26 = {
    Text = "Dieses verfluchte Ding, wie viel mehr wird es aus meiner Welt nehmen...!"
  },
  AvgDialog_34973_Content_27 = {
    Text = "Captain, erinnerst du dich an die anderen Wesen, die aufgrund des D-Phänomens verschwunden sind?"
  },
  AvgDialog_34973_Content_28 = {
    Text = "Elton schloss die Augen, die Pfeife knarrte zwischen seinen Zähnen."
  },
  AvgDialog_34973_Content_29 = {
    Text = "Der stille Erwachte warf Elton einen Blick zu, ging dann langsam auf ihn zu und streckte seine bereits durchscheinenden Hände aus."
  },
  AvgDialog_34973_Content_3 = {
    Text = "Elton nickte dir zu, holte einen Schlüssel aus seiner Tasche und öffnete zusammen mit Ramona die Cockpittür"
  },
  AvgDialog_34973_Content_30 = {
    Text = "Celeste... hat es dich betroffen? Tut mir leid, ich werde versuchen, meine Emotionen zu kontrollieren."
  },
  AvgDialog_34973_Content_31 = {
    Text = "Elton atmete ein paar Mal tief ein, scheinbar um seinen aufgewühlten Geist zu beruhigen. Er sah Ramona und dich an, sein Ton war viel stabiler."
  },
  AvgDialog_34973_Content_32 = {
    Text = "D-Phänomen... Ich hege seit langem Groll gegen es."
  },
  AvgDialog_34973_Content_33 = {
    Text = "Meine Vergangenheit... wurde wegen dies zerstört."
  },
  AvgDialog_34973_Content_4 = {
    Text = "Oh nein! Diese Korallen sind auch hier gewachsen!"
  },
  AvgDialog_34973_Content_5 = {
    Text = "Captain, warte einen Moment—!"
  },
  AvgDialog_34973_Content_6 = {
    Text = "Elton stürmte in das Cockpit, während Ramona dicht hinter ihm folgte."
  },
  AvgDialog_34973_Content_7 = {
    Text = "Das Cockpit ist größer als du dir vorgestellt hast und verfügt über eine rare zweischichtige Struktur, die prunkvoller ist als jedes Cockpitfoto, das du je gesehen hast."
  },
  AvgDialog_34973_Content_8 = {
    Text = "Du kannst dir vorstellen, wie strahlend die Sonanir gewesen sein muss, bevor sie in ein Frachtschiff umgewandelt wurde, ein Paradies auf dem Meer."
  },
  AvgDialog_34973_Content_9 = {
    Text = "Puh... Gott sei Dank hat der Kapitän die Tür verschlossen. Keine Aberranten oder Seefahrer sind reingekommen"
  },
  AvgDialog_34974_Content_1 = {Text = "Parasit"},
  AvgDialog_34974_Content_10 = {
    Text = "Nach einer Explosion dieser Größenordnung ist es normal, drei bis fünf Tage lang Ohrenklingeln zu haben."
  },
  AvgDialog_34974_Content_11 = {
    Text = "Hmm, zumindest scheinen meine Trommelfelle intakt zu sein, soweit ich es fühlen kann."
  },
  AvgDialog_34974_Content_12 = {
    Text = "Hüter, wie fühlst du dich... Warte..."
  },
  AvgDialog_34974_Content_13 = {
    Text = "Ich, ich konnte die Hand des Geheimnisträgers nicht halten... {Male=er,Female=sie}, {Male=er,Female=sie}"
  },
  AvgDialog_34974_Content_14 = {
    Text = "Keine Panik, keine Panik. Der Bereich von Sonarniel hat das umliegende Seegebiet umfasst. Celeste wird %hisorher% nicht verpassen."
  },
  AvgDialog_34974_Content_15 = {
    Text = "Celeste blinzelte und schien die Worte des Kapitäns zu bestätigen."
  },
  AvgDialog_34974_Content_16 = {
    Text = "Jedoch wurde nach diesem Moment die Verbindung zwischen uns kurzzeitig unterbrochen..."
  },
  AvgDialog_34974_Content_17 = {
    Text = "Obwohl das Gefühl schnell verblasste, konnte die schwerelose Empfindung, die mich sprachlos machte, kein Illusion gewesen sein."
  },
  AvgDialog_34974_Content_18 = {
    Text = "Ich habe {Male=er,Female=sie} wirklich berührt, aber"
  },
  AvgDialog_34974_Content_19 = {
    Text = "Celeste stoppte mitten im Satz, als ob ihre Zahnräder verstellt worden wären. Ihre Lippen bewegten sich mehrere Male, aber es kamen keine Worte heraus."
  },
  AvgDialog_34974_Content_2 = {
    Text = "Im nächsten Millisekunde, nachdem die Fingerspitze den Handrücken des Hüters berührt hatte, raste ein sanfter, stiller weißer Wind in den Ursprung der Explosion."
  },
  AvgDialog_34974_Content_20 = {
    Text = "Elton tätschelte sanft ihren Rücken und setzte den unvollendeten Satz fort."
  },
  AvgDialog_34974_Content_21 = {
    Text = "Wir haben noch nie versucht, ein lebendes Wesen größer als eine Ratte zu transferieren."
  },
  AvgDialog_34974_Content_22 = {
    Text = "Die Fähigkeit, die Koordinaten von Kreaturen innerhalb des Schiffs zu verschieben, stammt aus Celestes Kontrolle über den Bereich. Angesichts meiner zunehmenden Schwäche... lässt ihre Präzision bei der Bestimmung der Landepunkte zu wünschen übrig."
  },
  AvgDialog_34974_Content_23 = {
    Text = "Das Kind und Murphy, {Male=er,Female=sie} könnten irgendwo auf diesem Schiff sein"
  },
  AvgDialog_34974_Content_24 = {
    Text = "Klasse... Entschuldigung, Captain. Ich war einfach zu nervös. Ich hoffe, ich habe dich nicht beleidigt."
  },
  AvgDialog_34974_Content_25 = {
    Text = "Das gesagt... Das Sonanil wurde von einem Passagierschiff in ein Handelsschiff umgebaut, mit der Anzahl der Kabinen..."
  },
  AvgDialog_34974_Content_26 = {
    Text = "Es gibt 7 Decks und 648 Kabinen."
  },
  AvgDialog_34974_Content_27 = {
    Text = "Die Durchsuchung jedes Raums wird eine Weile dauern..."
  },
  AvgDialog_34974_Content_28 = {
    Text = "Kapitän, kannst du und Celeste gut auf euch aufpassen? Ich muss jetzt sofort los, um die Hüter und Murphy so schnell wie möglich zu finden. Je später wir sie finden, desto größer wird die Gefahr für sie"
  },
  AvgDialog_34974_Content_29 = {
    Text = "Elton starrte in ihre resoluten heterochromen Augen und brach nach einem Moment in schallendes Gelächter aus."
  },
  AvgDialog_34974_Content_3 = {
    Text = "So sanfte Kraft, doch als sie Ramona in die grenzenlose weiße Nacht zog, fühlte es sich besonders intensiv an. Während die Koordinaten schnell wechselten, hatte sie das Gefühl, als würden ihre inneren Organe bis zum Bluten verdreht."
  },
  AvgDialog_34974_Content_30 = {
    Text = "Beeile dich nicht, junge Dame. Celeste und ich können es noch einmal versuchen."
  },
  AvgDialog_34974_Content_31 = {
    Text = "Willst du es versuchen?"
  },
  AvgDialog_34974_Content_32 = {
    Text = "Celeste, finde heraus, wo alle sind."
  },
  AvgDialog_34974_Content_33 = {
    Text = "Als sie das hörte, starrte Celeste einen Moment lang mit gefühllosen Augen auf den Kapitän, nickte dann leicht und hob den Kompass—"
  },
  AvgDialog_34974_Content_34 = {
    Text = "Erwecker schloss die Augen, weißes Licht strömte in ihren Händen, mit dem leisen Schreien der Möwen, das umherhallte..."
  },
  AvgDialog_34974_Content_35 = {Text = "Hmm...!"},
  AvgDialog_34974_Content_36 = {
    Text = "Captain! Stopp!"
  },
  AvgDialog_34974_Content_37 = {
    Text = "Mit Eltons schmerzhaftem Stöhnen verschwand das Licht plötzlich."
  },
  AvgDialog_34974_Content_38 = {
    Text = "Celeste sah den Kapitän an, dann die ängstliche Ramona und schließlich verwirrt auf ihre eigenen Fingerspitzen."
  },
  AvgDialog_34974_Content_39 = {
    Text = "Ramona half dem Kapitän auf und fühlte mit zwei Fingern seinen Puls an seinem Hals. Ihr Gesichtsausdruck wurde zunehmend ernst."
  },
  AvgDialog_34974_Content_4 = {
    Text = "*Hust, hust...*"
  },
  AvgDialog_34974_Content_40 = {
    Text = "Die Verknüpfung mit einem Erwacher, die Schaffung von Bereichen und das Bewahren der Erinnerungen der Seeleute... Jedes Mal, wenn Celeste ihre nicht-menschliche Kraft einsetzt, raubt es dir das Leben."
  },
  AvgDialog_34974_Content_41 = {
    Text = "Übertragung aus dem Kraftwerksraum Explosion... hat es die letzten Kräfte erschöpft?"
  },
  AvgDialog_34974_Content_42 = {
    Text = "Elton atmete ein paar Mal tief ein, um seine Herzklopfen zu beruhigen."
  },
  AvgDialog_34974_Content_43 = {
    Text = "—Dann hielt er einen hölzernen Becher vor Ramona hoch.\nGott weiß, woher er ihn gezogen hat."
  },
  AvgDialog_34974_Content_44 = {
    Text = "Möchtest du einen Bissen nehmen? Es könnte gegen das Klingeln in deinen Ohren helfen."
  },
  AvgDialog_34974_Content_45 = {
    Text = "......Nein, Mythags Regeln ermutigen uns nicht zum Trinken."
  },
  AvgDialog_34974_Content_46 = {
    Text = "Der Kapitän neigte den Kopf zurück, trank den starken Schnaps in einem Zug und warf dann beiläufig den Becher zu Boden."
  },
  AvgDialog_34974_Content_47 = {
    Text = "*Hust, hust, hust...!*"
  },
  AvgDialog_34974_Content_48 = {
    Text = "Dieser Schnaps ist wirklich stark."
  },
  AvgDialog_34974_Content_49 = {
    Text = "Die Verknüpfung mit einem Erwacher erfordert immense Geisteskraft. Sogar gut trainierte Ermittler von Mythag müssen sich nach jeder Sitzung trennen und ausruhen, ganz zu schweigen von gewöhnlichen Menschen..."
  },
  AvgDialog_34974_Content_5 = {
    Text = "Keuchend legte Celeste ihren Kompass nieder und setzte sich mit Hilfe des Kapitäns, faltete ihre Hände auf ihrem Schoß. Sie sah sogar schwächer aus als zuvor."
  },
  AvgDialog_34974_Content_50 = {
    Text = "Captain, dein Körper..."
  },
  AvgDialog_34974_Content_51 = {
    Text = "Keine Sorge. Ich war darauf vorbereitet, als ich mich mit Celeste verknüpfte."
  },
  AvgDialog_34974_Content_52 = {
    Text = "Eltons Lächeln in diesem Moment trug einen Hauch von Erleichterung, als ob er wirklich meinte, was er sagte: Er war schon lange auf die Ankunft des Sensenmanns vorbereitet."
  },
  AvgDialog_34974_Content_53 = {
    Text = "Celeste schloss ebenfalls ihre Augen. Ihr Körper wurde leicht transparent, aber die Verknüpfung mit dem Kapitän strahlte umso brillanter, fast fest genug, um mit bloßem Auge sichtbar zu sein."
  },
  AvgDialog_34974_Content_54 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_34974_Content_55 = {
    Text = "Während die Erwachter allmählich schwächer werden, wird der Sonanier erneut zu einem Stück Treibholz im Sturm, das von Welle zu Welle zu unvorstellbaren Höhen gedrängt wird."
  },
  AvgDialog_34974_Content_56 = {
    Text = "Das elektrische System des Schiffes wurde mit jedem Aufprall zerbrechlich, und mit dem letzten Lichtbogen wurde die Kabine in Dunkelheit getaucht."
  },
  AvgDialog_34974_Content_57 = {
    Text = "Alles wird verschwommen; nur das Knurren des Feindes fällt auf."
  },
  AvgDialog_34974_Content_58 = {
    Text = "Ramona zog ihre Waffe, machte eine Geste an die beiden hinter ihr, still zu bleiben. Sie presste sich gegen die Tür, die Waffe bereit, während ein kaum hörbares Ticken den Anstieg ihrer Gnosis begleitete."
  },
  AvgDialog_34974_Content_59 = {
    Text = "Die Wahrnehmung der Zeit wurde in eine stille Leere gezogen. Ihre Nerven waren so angespannt, dass sie den Zeitablauf nicht mehr unterscheiden konnte – fünf Sekunden, zwanzig Sekunden, eine Minute? Oder hatte die Zeit sich nie neu gestartet?"
  },
  AvgDialog_34974_Content_6 = {
    Text = "Wie fühlst du dich?"
  },
  AvgDialog_34974_Content_60 = {
    Text = "Lauf vor mir; ich halte das Hinterland verdeckt. Lass nicht zu, dass diese Typen dich berühren."
  },
  AvgDialog_34974_Content_61 = {
    Text = "Brauche ich wirklich deine Erinnerungen? Außerdem ist es hier stockdunkel – scheint, als wäre niemand da. Ramona ist nicht hier, oder? Und ich habe deinen Instinkten tatsächlich vertraut..."
  },
  AvgDialog_34974_Content_62 = {
    Text = "Nein... Sie muss in der Nähe sein."
  },
  AvgDialog_34974_Content_63 = {
    Text = "Das plötzliche Klirren von Metall erreicht deine Ohren. Bevor du reagieren kannst, wird die Luke vor dir plötzlich von innen aufgerissen und ein Paar Hände zieht dich und Murphy hinein."
  },
  AvgDialog_34974_Content_64 = {
    Text = "Die Drähte im Rahmen des Decks summten wieder leise. Die Glühbirne flackerte ein paar Mal und leuchtete schließlich schwach auf."
  },
  AvgDialog_34974_Content_65 = {
    Text = "Ramona hob hastig das Rapier auf, das sie in ihrer Panik fallen gelassen hatte, mit einem überraschten Ausdruck auf ihrem Gesicht."
  },
  AvgDialog_34974_Content_66 = {
    Text = "Du bist in Ordnung... Ich bin wirklich erleichtert."
  },
  AvgDialog_34974_Content_67 = {
    Text = "Ich dachte... Ich dachte, ich müsste zum Meer gehen, um dich wiederzusehen..."
  },
  AvgDialog_34974_Content_7 = {
    Text = "Celeste schüttelte den Kopf, ohne zu sprechen. Ramona, die durch die Explosion und die Koordinatenverschiebung benommen war, konnte nicht sagen, ob die Antwort eine Bestätigung war."
  },
  AvgDialog_34974_Content_8 = {
    Text = "Als sie die beiden auf sie blicken sah, wollte Ramona sprechen, als ein anhaltendes Tiefenrauschen in ihren Ohren widerhallte und sogar unheilvolle Signale tief in ihr Gehirn sandte."
  },
  AvgDialog_34974_Content_9 = {
    Text = "Ugh... Meine Ohren tun weh..."
  },
  AvgDialog_34975_Content_1 = {
    Text = "Ramona, decke mich! Ich werde Murphy tragen. Wir werden von der anderen Seite angreifen!"
  },
  AvgDialog_34975_Content_2 = {
    Text = "Ramona steht mit dem Rücken zu dir, voll konzentriert darauf, die unermüdlichen Angriffe der Seefahrer abzuwehren. Ihre standhafte und aufrechte Gestalt ist die beste Antwort."
  },
  AvgDialog_34975_Content_3 = {Text = "Vorsicht!"},
  AvgDialog_34975_Content_4 = {
    Text = "Als der Seefahrer sich anschickte, Ramona aus den Schatten zu überfallen, drehte der Kapitän das Rad ganz auf die eine Seite."
  },
  AvgDialog_34975_Content_5 = {
    Text = "Die Trägheit ließ das Schiff plötzlich rucken, wie ein riesiges Biest, das in Panik zappelt. Trümmer in der Kabine wurden zur Seite geworfen und verursachten Chaos auf dem Schlachtfeld."
  },
  AvgDialog_34975_Content_6 = {
    Text = "Mit Celestes Hilfe hast du es geschafft, Murphy wieder auf deinen Rücken zu bekommen. Sie schien die vollständige Wende des Kapitäns vorherzusehen und stabilisierte dich durch das Neigen."
  },
  AvgDialog_34975_Content_7 = {
    Text = "Ramona stieß ihr Schwert in die Brust des Angreifers, schaute zurück und nickte dir zu."
  },
  AvgDialog_34976_Content_1 = {
    Text = "Ein dichter Nebel liegt über dem Meer, doch das Deck wird hell vom Glanz des Vollmonds erleuchtet, wodurch selbst die subtilsten Ausdrücke leicht erkennbar sind."
  },
  AvgDialog_34976_Content_10 = {
    Text = "Kaum ein paar Schritte hinein, ertönte ein „Plumps“ von hinten. Als sie sich umdrehten, sahen sie Murphy, der schwach auf dem Deck kniete, sein Oberkörper ganz nach vorne gebeugt, fast das Deck berührend."
  },
  AvgDialog_34976_Content_11 = {Text = "Murphy?!"},
  AvgDialog_34976_Content_12 = {
    Text = "Du bist schnell herübergelaufen und hast Murphy von dem Deck hochgehoben.\nSie war ohnmächtig, ihr Pony war mit kaltem Schweiß durchnässt und hing chaotisch an ihrer Stirn."
  },
  AvgDialog_34976_Content_13 = {
    Text = "@1...Es tut weh..."
  },
  AvgDialog_34976_Content_14 = {
    Text = "Hmm...@1...@1..."
  },
  AvgDialog_34976_Content_15 = {
    Text = "Sie griff nach deiner stützenden Hand, und der Schmerz ließ sie unwillkürlich die Finger zusammenziehen, die tief in dein Fleisch eindrangen, aber du achtetest nicht auf den kleinen Schmerz"
  },
  AvgDialog_34976_Content_16 = {
    Text = "Du hörst die aufsteigenden Trommeln – parasitäre Muskeln, nicht menschlichen Ursprungs, schlagen in der Brust des Mädchens und nähren sich von ihrem Leben."
  },
  AvgDialog_34976_Content_17 = {
    Text = "\"Gott\"... saugt ihr Leben aus."
  },
  AvgDialog_34976_Content_18 = {Text = "Mi...@2"},
  AvgDialog_34976_Content_19 = {
    Text = "Ein Klade-Kern parasitiert ihr Herz. Wenn das so weitergeht, wird sie..."
  },
  AvgDialog_34976_Content_2 = {
    Text = "Der Mond..."
  },
  AvgDialog_34976_Content_20 = {
    Text = "Du blickst zum quadratischen Fenster des Cockpits auf; es ist stockdunkel, wie der aufgerissene Mund eines Wals, der Licht verschlingt."
  },
  AvgDialog_34976_Content_21 = {
    Text = "Murphy, kannst du mich hören?"
  },
  AvgDialog_34976_Content_22 = {Text = "Murphy?"},
  AvgDialog_34976_Content_23 = {
    Text = "Durch Seine...@2"
  },
  AvgDialog_34976_Content_24 = {
    Text = "Murphys Atmung wurde unregelmäßig, verknüpft mit einem beunruhigenden und gefährlichen Traum, der deine Rufe ignorierte."
  },
  AvgDialog_34976_Content_25 = {
    Text = "...Halt durch."
  },
  AvgDialog_34976_Content_26 = {
    Text = "Student, lass mich sie stattdessen tragen."
  },
  AvgDialog_34976_Content_27 = {
    Text = "Dein Körper ist schwächer als meiner. Lass mich mich darum kümmern, Ramona. Sei wachsam gegenüber der Umgebung.\nIch habe Gewichtstraining gemacht und kann Murphys Gewicht tragen."
  },
  AvgDialog_34976_Content_28 = {
    Text = "Elton bestand nicht weiter darauf. Mit seiner Hilfe trugst du Murphys Knie und ließest sie auf deinem Rücken liegen."
  },
  AvgDialog_34976_Content_29 = {
    Text = "Du setzt all deine Kraft ein, um Murphy zu stützen, atmest tief ein und bereitest dich darauf vor, die Treppe hinaufzugehen—"
  },
  AvgDialog_34976_Content_3 = {
    Text = "Was ist mit dem Mond?"
  },
  AvgDialog_34976_Content_30 = {
    Text = "Das bewusstlose Mädchen liegt auf deinem Rücken, mit unverständlichem Gemurmel, das ständig an deinem Ohr vorbeizieht."
  },
  AvgDialog_34976_Content_31 = {
    Text = "Gott...@2...@4......"
  },
  AvgDialog_34976_Content_32 = {
    Text = "Neben dem Stöhnen vor Schmerz konnte Murphy nur unverständliche Worte murmeln.\nMitten in diesem chaotischen Geschwätz tauchte der Feind aus den Schatten auf."
  },
  AvgDialog_34976_Content_4 = {
    Text = "Es wird heller und heller, und auch..."
  },
  AvgDialog_34976_Content_5 = {
    Text = "Murphy schluckte den Rest des Satzes, aber du wusstest, was sie sagen wollte—"
  },
  AvgDialog_34976_Content_6 = {
    Text = "Auch ihre Zeit wird knapp"
  },
  AvgDialog_34976_Content_7 = {
    Text = "Beeile dich ins Cockpit. Kapitän, bitte zeige uns den Weg nach vorne."
  },
  AvgDialog_34976_Content_8 = {
    Text = "Wir müssen das Deck überqueren, um die oberste Ebene des Brückenturms zu erreichen."
  },
  AvgDialog_34976_Content_9 = {
    Text = "Ramona nickte und trat vor, um den Kapitän zu beschützen."
  },
  AvgDialog_34977_Content_1 = {
    Text = "Ahhh—! %player%, tu etwas! Sie packen meine Stiefel!"
  },
  AvgDialog_34977_Content_2 = {
    Text = "Gehe zu der Kabine dort drüben und blockiere sie mit der Luke!"
  },
  AvgDialog_34978_Content_1 = {
    Text = "Vernichtung"
  },
  AvgDialog_34978_Content_10 = {
    Text = "Waisenhaus..."
  },
  AvgDialog_34978_Content_100 = {
    Text = "Was ist mit der Heftigkeit!"
  },
  AvgDialog_34978_Content_101 = {
    Text = "Ein Mädchen crawlt aus unter Celestes Rock und bringt mich fast zum Stürzen."
  },
  AvgDialog_34978_Content_102 = {
    Text = "Sie sieht... so vertraut aus. Ich schwöre, ich habe sie schon einmal irgendwo gesehen."
  },
  AvgDialog_34978_Content_103 = {
    Text = "Celeste, hast du diesem unhöflichen Mädchen das Einsteigen erlaubt?"
  },
  AvgDialog_34978_Content_104 = {
    Text = "Ich habe dir gesagt, du sollst aufhören zu schreien! Willst du wirklich, dass uns die Seefahrer hören?"
  },
  AvgDialog_34978_Content_105 = {
    Text = "Und wer nennst du ein unhöfliches Mädchen?! Mein Name ist Murphy, Murphy!"
  },
  AvgDialog_34978_Content_106 = {
    Text = "Ich erinnere mich jetzt. Ich sah sie während eines Rituals tief in meinen Erinnerungen."
  },
  AvgDialog_34978_Content_107 = {
    Text = "Nachdem die \"Gottesmutter\" von der Auflösung betroffen war, wählte Miryam einen neuen \"Wirt\" für das Embryo Gottes und versetzte den \"Wirt\" in einen tiefen Schlaf von mehr als zwanzig Jahren."
  },
  AvgDialog_34978_Content_108 = {
    Text = "Als die Sterne sich ausrichten, weckt die Hohepriesterin sie aus dem Schlummer. Der transportierte Inventar ist diesmal Vorbereitung für das \"Gotteseinstiegsritual\"."
  },
  AvgDialog_34978_Content_109 = {
    Text = "Das Baby, das ich während des Sturms hielt und dem ich Wasser gab, wird für immer die Chance beraubt, aufzuwachsen."
  },
  AvgDialog_34978_Content_11 = {
    Text = "Nein, wird es nicht. Familie..."
  },
  AvgDialog_34978_Content_110 = {
    Text = "Ich kenne dich. Ihr seid keine Seefahrer, nur Frachtarbeiter... Solange du mich hier rausbringen kannst, umso weiter, desto besser — diese Schätze sind alle yours."
  },
  AvgDialog_34978_Content_111 = {
    Text = "Sie zog mehrere Statuen heraus—ungeschickte Holzschnitzereien, die beim ersten Blick schwindelig machten, von Seefahrern geliebt, aber für andere wertlos."
  },
  AvgDialog_34978_Content_112 = {
    Text = "Murphy... kommt mit uns."
  },
  AvgDialog_34978_Content_113 = {
    Text = "Sie... Auflösung..."
  },
  AvgDialog_34978_Content_114 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_34978_Content_115 = {
    Text = "Opfer einer alten Ära, Opfer barbarischer Bräuche, meine fernen Vorfahren, der einzige Beweis für ein einst bestehendes \"Zuhause.\""
  },
  AvgDialog_34978_Content_116 = {
    Text = "Celestes \"Selbst\" war tief in ihrer Seele durch die Erfahrungen aus ihrem früheren Leben versiegelt. Ich hatte keinen Grund, die erste Bitte, die sie an mich stellte, abzulehnen."
  },
  AvgDialog_34978_Content_117 = {
    Text = "Außerdem..."
  },
  AvgDialog_34978_Content_118 = {
    Text = "Setze die Segel, Celeste."
  },
  AvgDialog_34978_Content_119 = {
    Text = "Bist du... bist du bereit, mich mitzunehmen?"
  },
  AvgDialog_34978_Content_12 = {
    Text = "Hast du wirklich vergessen? Wir sind auf dieser Straße aufgewachsen.\nIch bin sogar über die Mauer des Waisenhauses geklettert, um dir Essen zu bringen, und wurde von der Nonne drei Blocks weit verfolgt. Alles vergessen?"
  },
  AvgDialog_34978_Content_120 = {
    Text = "Da Celeste es wünscht, werde ich dich so weit wie möglich wegschicken."
  },
  AvgDialog_34978_Content_121 = {
    Text = "Wow... Verwöhnst du sie so?"
  },
  AvgDialog_34978_Content_122 = {
    Text = "Rüpel kleiner Bengel. Du solltest wissen, dass ich meine Meinung jederzeit ändern und dich ins eiskalte Meer werfen kann."
  },
  AvgDialog_34978_Content_123 = {
    Text = "Geizig... Gut, ich werde selbst fragen..."
  },
  AvgDialog_34978_Content_124 = {
    Text = "Außerdem... ich war es, der Murphy auf diesen Weg geschickt hat."
  },
  AvgDialog_34978_Content_125 = {
    Text = "Ein Pfad, bedeckt mit Auflösung, der zu Zerstörung und Vergessenheit führt."
  },
  AvgDialog_34978_Content_126 = {
    Text = "Ich muss dafür büßen."
  },
  AvgDialog_34978_Content_13 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_34978_Content_14 = {
    Text = "Entschuldigung, Kumpel, vielleicht ist es das Landweh, das sich bemerkbar macht. In letzter Zeit verwechsle ich Träume mit der Realität.\nEs sind Jahre vergangen, seit wir uns zuletzt getroffen haben. Wie wäre es heute mit ein paar Drinks an unserem alten Platz?"
  },
  AvgDialog_34978_Content_15 = {
    Text = "Hehe, der alte John hat letztes Jahr eine neue Whiskey-Sorte gebraut, und sie ist absolut köstlich!\nLass uns es wie immer halten — trinken bis wir umfallen!"
  },
  AvgDialog_34978_Content_16 = {
    Text = "Alright... Wir gehen nicht nach Hause, bis wir betrunken sind."
  },
  AvgDialog_34978_Content_17 = {
    Text = "Ich kenne keine Minen, war in keinen Waisenhäusern und kenne keinen Old John von dem alten Ort."
  },
  AvgDialog_34978_Content_18 = {
    Text = "Ich weiß nur, dass alles über jene kleine Stadt dahinschwindet."
  },
  AvgDialog_34978_Content_19 = {
    Text = "Meine Kindheit, meine Eltern, meine Geschwister—alle als absurdes Traum abgeschrieben."
  },
  AvgDialog_34978_Content_2 = {
    Text = "A.F. 2@1 Früher Herbst\nKönigreich Leo im Süden"
  },
  AvgDialog_34978_Content_20 = {
    Text = "Selbst ich habe fast daran geglaubt."
  },
  AvgDialog_34978_Content_21 = {
    Text = "Aber wo auf der Welt könnte es so einen unvergesslichen Traum geben?"
  },
  AvgDialog_34978_Content_22 = {
    Text = [[
A.F.2@2 Jahre Tiefer Winter  
"Seefahrer" Kult, Elworth Heiligtum]]
  },
  AvgDialog_34978_Content_23 = {
    Text = "Diese Lieferung besteht aus täglichen Vorräten und... 19 fehlgeschlagenen experimentellen Subjekten, bereitgestellt von... der Kirche"
  },
  AvgDialog_34978_Content_24 = {
    Text = "Die Informationen des Lieferanten wurden durch Seewasser verwischt. Möchtest du die Sammlung trotzdem bestätigen?"
  },
  AvgDialog_34978_Content_25 = {
    Text = "Bestätigen... keine Fehler"
  },
  AvgDialog_34978_Content_26 = {
    Text = "Bevor ich fertig sprechen konnte, schnappte der Kontakt, der vor mir hockte, hastig das Manifest aus meiner Hand.\nEr schien sich nicht darum zu kümmern, was ich sagte, murmelte nur \"Bestätigt.\""
  },
  AvgDialog_34978_Content_27 = {
    Text = "Der polare Sturm blies die Kapuze des Kontakts weg und enthüllte einen äußerst abscheulichen Kopf."
  },
  AvgDialog_34978_Content_28 = {
    Text = "Riesige, hervorstehende Augäpfel; Augenlider, die sich nicht schließen können. Kiemenähnliches Gewebe verbindet das Kinn mit dem Schlüsselbein und ähnelt einem lebenden Fisch."
  },
  AvgDialog_34978_Content_29 = {
    Text = "Meine Abneigung und Übelkeit unterdrückend, blieb mir nichts anderes übrig, als meinen Hut vor der anderen Partei zu ziehen."
  },
  AvgDialog_34978_Content_3 = {
    Text = "Wie könntest du von dieser Stadt nichts gehört haben!?"
  },
  AvgDialog_34978_Content_30 = {
    Text = "Wenn es nichts anderes gibt, wird die Sonanir heute Nacht in See stechen. Die nächste Lieferung wird in etwa 114 Tagen in Elworth ankommen."
  },
  AvgDialog_34978_Content_31 = {
    Text = "@1...Bitte, ich wünsche dir... eine glückliche Reise..."
  },
  AvgDialog_34978_Content_32 = {
    Text = "...und so weiter."
  },
  AvgDialog_34978_Content_33 = {
    Text = "Als ich gerade zum Schiff zurückkehren wollte, rief mich eine mir etwas unbekannte weibliche Stimme an."
  },
  AvgDialog_34978_Content_34 = {
    Text = "Sie war eine erwachsene Frau, die in ein schwarzes Tuch gehüllt war und so leicht gekleidet war, dass sie sogar barfuß war.\nIn dem frostigen Land Elworth auf diesem Planeten erschien sie besonders fehl am Platz."
  },
  AvgDialog_34978_Content_35 = {
    Text = "Hochpriester, Hochpriester..."
  },
  AvgDialog_34978_Content_36 = {
    Text = "Der Kontakt des Seefahrers fiel plötzlich zu Boden, sein Körper traf mit einem schmerzhaften Aufprall auf den kalten, harten schwarzen Stein, der den Ohren wehtat."
  },
  AvgDialog_34978_Content_37 = {
    Text = "Nach zehn Jahren auf See, durch harte Arbeit, Glück und einige unschöne Jobs, bekam ich schließlich mein eigenes Schiff und wurde Kapitän. In diesem geheimen Kult bedeutet es jedoch nichts, Kapitän zu sein."
  },
  AvgDialog_34978_Content_38 = {
    Text = "Selbst wenn ich die Führungsetage des Ordens noch nie getroffen habe, kann ich allein aufgrund der Reaktionen der Seefahrer um mich herum erkennen, wie nobel der Status des Besuchers ist."
  },
  AvgDialog_34978_Content_39 = {
    Text = "So kniete ich nieder, genau wie er, ohne zu zögern."
  },
  AvgDialog_34978_Content_4 = {
    Text = "@2 Die Mündung des Flusses, mit @3 Bergen im Rücken... Das ist der Ort, an dem wir beide aufgewachsen sind!"
  },
  AvgDialog_34978_Content_40 = {
    Text = "Meister Priester."
  },
  AvgDialog_34978_Content_41 = {
    Text = "Umgeben von verweilenden Geistern.\nFährmann, trägst du die Relikte der Verstorbenen?"
  },
  AvgDialog_34978_Content_42 = {
    Text = "Überreste der Verstorbenen..."
  },
  AvgDialog_34978_Content_43 = {
    Text = "Auf das Signal des Hochpriesters öffnete ich den Deckel der Taschenuhr und offenbarte eine fließende Masse aus Silber anstelle des Zifferblattes."
  },
  AvgDialog_34978_Content_44 = {
    Text = "Das stimmt, obwohl die Gnosis darin schwach ist... gibt es keinen Zweifel, es ist Silber."
  },
  AvgDialog_34978_Content_45 = {
    Text = "Jedes Silber enthält eine vergessene Erinnerung... Möchtest du dieses Silber erwecken?"
  },
  AvgDialog_34978_Content_46 = {
    Text = "Vergessene Erinnerungen..."
  },
  AvgDialog_34978_Content_47 = {
    Text = "Meine Vergangenheit wird von allen geleugnet. Diese silberne Flüssigkeit, die aus <Yellow:dem Sumpf, der einst mein Zuhause war> geholt wurde, könnte mein letzter Hinweis sein."
  },
  AvgDialog_34978_Content_48 = {
    Text = "Ich...! Bitte, Hoher Priester, gewähre mir deine Führung."
  },
  AvgDialog_34978_Content_49 = {
    Text = "Vollständig die nächste Versandaufgabe... und ich werde dir die Methode geben, um das Silber zu erwecken."
  },
  AvgDialog_34978_Content_5 = {
    Text = "In diesen Jahren auf See hast du deinen Verstand nicht an die Sirenen verloren, oder?\nDen Ort, den du erwähnt hast, kenne ich. Er ist seit der Alluvialen Ära ein Sumpf."
  },
  AvgDialog_34978_Content_50 = {
    Text = "Bring mir meine <Yellow:Hoffnung>."
  },
  AvgDialog_34978_Content_51 = {
    Text = "Der Seefahrer-Hochpriester Miryam hat mir eine neue Aufgabe zugewiesen.\nDie Waren, die auf dieser Reise transportiert wurden, verwandelten sich in ein <Yellow:Baby Mädchen>."
  },
  AvgDialog_34978_Content_52 = {
    Text = "Davor hatte ich nur \"in Träumen\" meine jüngeren Geschwister umarmt.\nLeider sind diese friedlichen und glücklichen Erinnerungen mit dem Erwachen verschwunden."
  },
  AvgDialog_34978_Content_53 = {
    Text = "Die Fahrt wurde durch den Westwind verlängert. In der letzten Woche auf See wurde alles frische Wasser diesem kleinen gegeben."
  },
  AvgDialog_34978_Content_54 = {
    Text = "Es stört sie nicht, meinen verworrenen Bart zu sehen, während sie in meinen Armen liegt und lacht."
  },
  AvgDialog_34978_Content_55 = {
    Text = "Ich übergab sie dem Hochpriester."
  },
  AvgDialog_34978_Content_56 = {
    Text = [[
A.F.3@1 Sommersonnenwende
Atlas-Ozean]]
  },
  AvgDialog_34978_Content_57 = {
    Text = "Kapitän! Alle Kompasse haben versagt, und das Ruder wurde von den Wellen beschädigt!"
  },
  AvgDialog_34978_Content_58 = {
    Text = "Der Topf, der Kessel ist überflutet! Wir haben die Energie verloren!"
  },
  AvgDialog_34978_Content_59 = {
    Text = "Was hast du getan?! Großartig, jetzt können wir nicht steuern, und die Strömung drängt uns in den Gewittersturm!"
  },
  AvgDialog_34978_Content_6 = {Text = "Sumpf?"},
  AvgDialog_34978_Content_60 = {
    Text = "Alle, hört auf zu streiten! Das ist nicht die Zeit für Schuldzuweisungen!"
  },
  AvgDialog_34978_Content_61 = {
    Text = [[
Erster Offizier, nimm die Seeleute und lass die Rettungsboote zu Wasser.
Pass auf, dass mehr Leute in jedes Boot passen und rudere mit all deiner Kraft, bevor ihr im Strudel gefangen werdet.]]
  },
  AvgDialog_34978_Content_62 = {
    Text = "Wo ist der Kapitän?"
  },
  AvgDialog_34978_Content_63 = {
    Text = "...Du solltest so schnell wie möglich evakuieren."
  },
  AvgDialog_34978_Content_64 = {
    Text = "@2 Jahre sind vergangen. Ich habe unzählige Male versucht, die geheime Methode, die mir der Hohe Priester beigebracht hat, anzuwenden, aber ich kann das Silber immer noch nicht zum Strahlen bringen."
  },
  AvgDialog_34978_Content_65 = {
    Text = "Langfristiges Versagen und die Geschäftigkeit der Realität haben mich fast dazu gebracht, aufzugeben, die Wahrheit zu finden... die Wahrheit über das Verschwinden meines Heimatlandes."
  },
  AvgDialog_34978_Content_66 = {
    Text = "Ich schickte die meisten der Besatzung in die Rettungsboote und sank dann, erfüllt von Sehnsucht nach der Vergangenheit, zusammen mit der Sonaniel."
  },
  AvgDialog_34978_Content_67 = {
    Text = "Als ich weiter sank, strich der Wind über mein Gesicht."
  },
  AvgDialog_34978_Content_68 = {
    Text = "Der Wind stößt Meerwasser aus, das die Lungen füllt, bläst das Salz weg, das Wunden korrodiert, und hebt versunkene Träume aus dem Aequor."
  },
  AvgDialog_34978_Content_69 = {
    Text = "Dann sah ich das Mädchen, umhüllt von sanften Brisen und weißen Vögeln."
  },
  AvgDialog_34978_Content_7 = {
    Text = "Ja! Es war früher eine Mine, aber sie wurde zerstört, als der Fluss während einer großen Flut seinen Lauf änderte. Ein Herr kaufte das Land vor ein paar Jahren, und es wird gesagt, dass er plant, dort einen Park zu bauen."
  },
  AvgDialog_34978_Content_70 = {
    Text = "\"Mein Name ist Celeste. Solange du mich noch brauchst, werde ich hier bleiben.\""
  },
  AvgDialog_34978_Content_71 = {
    Text = "Sie ist eine Spur der Vergangenheit unseres Heimatlandes, ein Märchen, das ich von den Alten in meiner Kindheit gehört habe.\n Sie ließ mich erkennen, dass die Vergangenheit, nach der ich mich sehnte, wirklich existierte."
  },
  AvgDialog_34978_Content_72 = {
    Text = "Ihr Erscheinen bewies endlich, dass ich kein Wahnsinniger ohne Abstammung bin."
  },
  AvgDialog_34978_Content_73 = {
    Text = [[
Vor drei Monaten
Der Kult "Seefahrer", Elworth Sanctuary]]
  },
  AvgDialog_34978_Content_74 = {
    Text = "Von der Neuen Leo-Division bereitgestellte Vorräte: 135 Kisten, Opfergaben der Vereinigung: 12 Körper, Lebensmittel, die von der Kap-Horn-Insel gekauft wurden: 120 Kisten... Alles bestätigt."
  },
  AvgDialog_34978_Content_75 = {
    Text = "*Hust, hust...*"
  },
  AvgDialog_34978_Content_76 = {
    Text = "Du bist ein wichtiges Mitglied des Ordens. Bitte achte auf deinen Körper."
  },
  AvgDialog_34978_Content_77 = {
    Text = "Übrigens, der Orden hat einen neuen Batch von <Blue:Stabilisierendem Elixier> vorzeitig gebraut. Ich habe sie erhalten und werde dir deinen vierteljährlichen Anteil übergeben—"
  },
  AvgDialog_34978_Content_78 = {
    Text = "Pssst—gib es mir zu der vereinbarten Zeit, am selben Ort, <Yellow:Brillport Dock Nr. 3 Nord>."
  },
  AvgDialog_34978_Content_79 = {
    Text = "Celeste und ich werden dort auf dich warten. Wir planen, einige besondere Zutaten aus dem Intermeer zu sammeln. Wie wäre es, wenn du an Bord kommst und mein Kochen probierst, wenn wir uns am Hafen treffen?"
  },
  AvgDialog_34978_Content_8 = {
    Text = "Aber... mein Zuhause..."
  },
  AvgDialog_34978_Content_80 = {
    Text = "Ehrenvoll, wahrhaft geehret."
  },
  AvgDialog_34978_Content_81 = {
    Text = "Es wird gesagt, dass Miryam heute die <Blue:Muttergöttin> aus ihrem Schlummer erweckt hat, um das nächste Ausrichten der Sterne und die Wiedergeburt unseres Herrn zu begrüßen."
  },
  AvgDialog_34978_Content_82 = {
    Text = "Die nächsten drei Monate werden wahrscheinlich sowohl innerhalb als auch außerhalb des Ordens extrem geschäftig sein. Ich werde jedoch definitiv unseren Termin einhalten."
  },
  AvgDialog_34978_Content_83 = {
    Text = "In Ordnung, das ist dann beschlossen. Wir sehen uns in drei Monaten, ohne Zweifel."
  },
  AvgDialog_34978_Content_84 = {
    Text = "Dieser Junge, der einst das Blut eines Seemanns trug, nun aber den Körper eines Golems hat, lächelte schüchtern – Caecus ist mir wirklich nur ein Kind."
  },
  AvgDialog_34978_Content_85 = {
    Text = "Sehr ähnlich wie der Geschwister in meiner Erinnerung, der ebenfalls ein schüchterner und sensibler Junge war."
  },
  AvgDialog_34978_Content_86 = {
    Text = "Das Wetter am Wildersea wird bald windig werden. Ich empfehle dir, schnell zurückzukehren; ich werde dich nicht über Nacht festhalten."
  },
  AvgDialog_34978_Content_87 = {
    Text = "Ja, ich möchte nicht bei einem Eisturm in See stechen."
  },
  AvgDialog_34978_Content_88 = {
    Text = "Nachdem ich von Caecus Abschied genommen hatte, ging ich am letzten Stück \"Fracht\" vorbei, das herausgebracht wurde, und ging die Gangway auf das Schiff hinauf."
  },
  AvgDialog_34978_Content_89 = {
    Text = "Das Ding lebt noch, der weiße Stoff hebt sich schwach und fällt. Begleitet von dem Tropfen einer dunklen, klebrigen Flüssigkeit löst sich langsam etwas auf."
  },
  AvgDialog_34978_Content_9 = {
    Text = "Sobald du alt genug warst, um das Waisenhaus zu verlassen, hast du die Segel gesetzt. Es sind über zehn Jahre vergangen, aber du hast sicherlich nicht alles vergessen, oder? Fühlst du dich unwohl?"
  },
  AvgDialog_34978_Content_90 = {
    Text = [[
Kontrolliere deine Neugier, Elton!
Sieh nicht <Big:look>.
Denk nicht <Red:think>.
<Red:Don't><RedBig:face> es.]]
  },
  AvgDialog_34978_Content_91 = {
    Text = "Celeste, ich bin zurück."
  },
  AvgDialog_34978_Content_92 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_34978_Content_93 = {
    Text = "Es ist Zeit, zum alten Ort zurückzukehren."
  },
  AvgDialog_34978_Content_94 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_34978_Content_95 = {Text = "Celeste?"},
  AvgDialog_34978_Content_96 = {
    Text = "Alright, setze die Segel für die Aglo-Republik..."
  },
  AvgDialog_34978_Content_97 = {
    Text = [[
Nein, nein, das Ziel ist <Blue:Inter Sea>. Wir sind hier, um einige lokale Zutaten zu sammeln.
Warum bist du abgelenkt? Ist etwas auf dem Schiff passiert?]]
  },
  AvgDialog_34978_Content_98 = {
    Text = "......Hmm, Intermeer, setze die Segel."
  },
  AvgDialog_34978_Content_99 = {
    Text = "Celeste! Schau mich an!"
  },
  AvgDialog_34979_Content_1 = {
    Text = "Captain, die Feinde hier sind erledigt.\nDer Hüter und ich werden vorausscouten. Du kannst Murphy und Celeste mitnehmen."
  },
  AvgDialog_34979_Content_10 = {
    Text = [[
Aber magst du es nicht... wirklich? 
Ich habe gesehen, dass du sehr oft gekommen bist, um seine Maschine zu warten.]]
  },
  AvgDialog_34979_Content_11 = {
    Text = "Hey, hey! Was machst du da—"
  },
  AvgDialog_34979_Content_12 = {
    Text = "Elton beugte sich vor und kniff in Murphy's angespanntes Gesicht."
  },
  AvgDialog_34979_Content_13 = {
    Text = "Wenn du all meine Verluste ausgleichen möchtest, überlebe."
  },
  AvgDialog_34979_Content_14 = {
    Text = "Elton hatte aufgehört zu sprechen, wodurch Murphy keine Chance zur Reaktion blieb. Er drängte sie von hinten, wodurch sie nach vorne stolperte und die unheimliche, abgrundartige Kabine verließ."
  },
  AvgDialog_34979_Content_15 = {
    Text = "Murphy stand am Tür eines weiteren Frachtraums und beobachtete die Bewegungen des Kapitäns über den einen Meter breiten Gang."
  },
  AvgDialog_34979_Content_16 = {
    Text = "Er half zuerst Celeste aus der verwilderten Kammer, übergab sie an Murphy und trat dann zurück in die Dunkelheit, um die Luke zu öffnen"
  },
  AvgDialog_34979_Content_17 = {Text = "Captain..."},
  AvgDialog_34979_Content_18 = {
    Text = "Warum schaust du mich immer noch an? Diese beiden Studenten kommen gerade davon."
  },
  AvgDialog_34979_Content_19 = {
    Text = "Wirklich? Du und Celeste haben euer Leben riskiert, um mir zu helfen, und ihr erwartet wirklich—nichts im Gegenzug?"
  },
  AvgDialog_34979_Content_2 = {
    Text = "Alright, danke für deine Hilfe."
  },
  AvgDialog_34979_Content_20 = {
    Text = "Du, Kind..."
  },
  AvgDialog_34979_Content_21 = {
    Text = "Captain—Murphy—warum ist er noch nicht aufgeholt?"
  },
  AvgDialog_34979_Content_22 = {
    Text = "Komme gleich!"
  },
  AvgDialog_34979_Content_23 = {
    Text = "Schließlich schloss er die Tür hinter sich, und der Schein auf seinem Mantel verschwand."
  },
  AvgDialog_34979_Content_24 = {
    Text = [[
In Ordnung, lebe gut und wachse auf. Finde einen Job, verdiene genug Geld.
Dann kaufe mir das neueste Modell eines Autos.]]
  },
  AvgDialog_34979_Content_3 = {
    Text = "Elton warf einen Blick um den Türbereich, bestätigte, dass es vorübergehend sicher war, und winkte Murphy und Celeste herüber."
  },
  AvgDialog_34979_Content_4 = {
    Text = "Im letzten Moment, bevor er den Laderaum verließ, hielt Elton inne. Er drehte sich um und sah sich die von korallenartigen Wachstumsformen beschädigten Fahrzeuge an, mit einem Hauch von Bedauern in seiner Stimme."
  },
  AvgDialog_34979_Content_5 = {
    Text = "Das ist ein Vierzylinder-Motormodell, das sich noch in der experimentellen Phase befindet... Diese Schönheit hat noch nie wirklich auf dem Land gerast. Was für eine Schande."
  },
  AvgDialog_34979_Content_6 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_34979_Content_7 = {
    Text = "Murphy biss sich auf die Unterlippe, sah das offensichtlich demolierte Auto an und warf Elton vorsichtig einige Blicke zu."
  },
  AvgDialog_34979_Content_8 = {
    Text = "Wie kannst du diesen Gesichtsausdruck machen?"
  },
  AvgDialog_34979_Content_9 = {
    Text = "Wovor hast du Angst? Mach dir keine Sorgen, ich verlange nicht, dass du mir ein neues Auto kaufst."
  },
  AvgDialog_34980_Content_1 = {Text = "Krisenmond"},
  AvgDialog_34980_Content_10 = {
    Text = "Wir glauben an dich."
  },
  AvgDialog_34980_Content_11 = {Text = "Student..."},
  AvgDialog_34980_Content_12 = {
    Text = "Seit Jahrhunderten hat die Mythag Universität nie aufgehört, gegen das D-Phänomen zu kämpfen, wobei unzählige Ermittler ihr Leben opferten."
  },
  AvgDialog_34980_Content_13 = {
    Text = "Unter ihnen sind die, die aufgrund von Auflösung geopfert wurden... Ihre Erinnerung schwindet, und selbst die Briefe, die sie hinterließen, tragen D-Marken."
  },
  AvgDialog_34980_Content_14 = {
    Text = "Habt ihr beiden keine Angst?"
  },
  AvgDialog_34980_Content_15 = {
    Text = "Angst... Natürlich habe ich Angst. Wer hätte keine Angst, ganz aus der Welt zu verschwinden?"
  },
  AvgDialog_34980_Content_16 = {
    Text = "Aber irgendjemand muss den Mut aufbringen, sich dem zu stellen, oder?"
  },
  AvgDialog_34980_Content_17 = {
    Text = "Wenn selbst wir zurückweichen, was ist dann mit unseren Vorgängern, die während der Ermittlungen ums Leben kamen, und denen, die aufgrund der Auflösung verschwunden sind..."
  },
  AvgDialog_34980_Content_18 = {
    Text = "Wenn wir sogar zurückweichen, dann wird ihre Existenz wirklich bedeutungslos."
  },
  AvgDialog_34980_Content_19 = {
    Text = "Für unsere Zukunft und für diejenigen, die verschwunden sind, werden wir, egal wie absurd die Spekulationen sind, es als Fakt betrachten und eine Untersuchung durchführen."
  },
  AvgDialog_34980_Content_2 = {
    Text = "Eltons Geständnis ließ dich und Ramona sprachlos zurück. Ihr saht euch schweigend an und lasst den gleichen Überraschungsblick in den Augen des anderen."
  },
  AvgDialog_34980_Content_20 = {Text = "Heh..."},
  AvgDialog_34980_Content_21 = {
    Text = "Es scheint, dass die Mehrheit der Menschen in dieser Welt verrückt ist."
  },
  AvgDialog_34980_Content_22 = {Text = "Woo—"},
  AvgDialog_34980_Content_23 = {
    Text = "Der Schall des Pfiffs erschreckte alle.\nElton war der Erste, der reagierte, und stürzte sich auf das Bedienfeld, um den Pfiff manuell zu stoppen."
  },
  AvgDialog_34980_Content_24 = {
    Text = "Oh nein! Die Kontrolllinie für die Pfeife wurde von diesen Korallen beschädigt!\nBei so einem Tumult werden diese Leute bald bemerken, dass jemand im Cockpit ist."
  },
  AvgDialog_34980_Content_25 = {
    Text = "Ramona rennt aus dem Cockpit und du folgst ihr. Beide lehnt euch über die Reling des Schiffs und schaut nach unten—"
  },
  AvgDialog_34980_Content_26 = {
    Text = "Seefahrer, die auf dem unteren Deck umherwandern, heben ihre Köpfe, ihre leblosen Fischaugen fixieren deinen Blick."
  },
  AvgDialog_34980_Content_27 = {
    Text = "Wie ist es? Hat der Seefahrer uns bemerkt?"
  },
  AvgDialog_34980_Content_28 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_34980_Content_29 = {
    Text = "Captain, bitte konzentriere dich auf das Steuern."
  },
  AvgDialog_34980_Content_3 = {
    Text = "Ein Heimatland, das aufgrund der Auflösung verschwunden ist, mit Celeste als dem einzigen Beweis für seine Existenz..."
  },
  AvgDialog_34980_Content_30 = {
    Text = "Was die externen Eingriffe betrifft... ich werde es mit dem Hüter klären."
  },
  AvgDialog_34980_Content_4 = {
    Text = "Fühlst du dich schuldig, Murphy persönlich an den Kult übergeben zu haben... Ist das der Grund, warum du entschieden hast, den Seefahrer zu verraten?"
  },
  AvgDialog_34980_Content_5 = {
    Text = "\nElton hockte sich neben Murphy, strich das verschwitzte Haar von ihrer Stirn. \nNachdem er ihren Zustand überprüft hatte, seufzte er tief, bevor er schließlich aufstand und zu dir zurückblickte"
  },
  AvgDialog_34980_Content_6 = {
    Text = "Wenn ich sie nicht an Miryam gegeben hätte, wäre sie nicht von diesem sogenannten Gott besessen worden und würde nicht hier liegen, ihr Leben am seidenen Faden."
  },
  AvgDialog_34980_Content_7 = {
    Text = "Fühlt es sich an, als würde man einen Witz hören?"
  },
  AvgDialog_34980_Content_8 = {
    Text = "Sind Menschen nicht die Besten darin, Geschichte aufzuzeichnen? Sogar Sportereignisse aus vor Tausenden von Jahren hinterließen Aufzeichnungen. Wie kann eine Stadt völlig verschwinden, ohne einen einzigen Hinweis zu hinterlassen?"
  },
  AvgDialog_34980_Content_9 = {
    Text = "Vergiss all den Unsinn. Betrachte es einfach als eine furchtbare Gute-Nacht-Geschichte, die ich erfunden habe."
  },
  AvgDialog_34981_Content_1 = {
    Text = "Ramona, du bist..."
  },
  AvgDialog_34981_Content_10 = {
    Text = "Nein... Wie konnte das passieren?"
  },
  AvgDialog_34981_Content_11 = {Text = "Was fehlt?"},
  AvgDialog_34981_Content_12 = {
    Text = [[
Deine Wadenverletzung ist verschwunden.
Aber ich habe es deutlich gesehen... Die Waffe des Feindes hat dich dort festgenagelt.]]
  },
  AvgDialog_34981_Content_13 = {
    Text = "So wolltest du mich also zuerst Celeste wegbringen und dich zurücklassen..."
  },
  AvgDialog_34981_Content_14 = {
    Text = "Du kannst diesen qualvollen, unvergesslichen Schmerz nicht vergessen."
  },
  AvgDialog_34981_Content_15 = {
    Text = "Wie ein Henker, der die Galgen reinigt, ohne sich um die Verurteilten zu kümmern, hat Goliath nie an deine Gefühle gedacht, als er seine Waffe zog."
  },
  AvgDialog_34981_Content_16 = {
    Text = "Blut durchnäßte deine Schuluniform, und Stücke von Fleisch spritzten auf Goliaths Hand. Dein Unterschenkel, im krassen Gegensatz zur riesigen Klinge, war fast durchtrennt, mit durch Angst induziertem Adrenalin, das dich bewusst hielt."
  },
  AvgDialog_34981_Content_17 = {
    Text = "Obwohl der Schmerz weiterhin an deinen Nerven zerrt, ist es wahr... Die schreckliche Wunde ist verschwunden."
  },
  AvgDialog_34981_Content_18 = {
    Text = "Die Kleidung hat zwei große Löcher, die hindurchgerissen sind, aber die darunterliegende Haut ist glatt und makellos.\nAbgesehen davon, dass sie aufgrund des fehlenden Sonnenlichts übermäßig blass ist, scheint sie gesund und intakt zu sein."
  },
  AvgDialog_34981_Content_19 = {
    Text = "Die Wunde verheilte? Es muss Celestes Fähigkeit sein."
  },
  AvgDialog_34981_Content_2 = {
    Text = "Shh... Sei leise. Es gibt noch viele Seefahrer, die draußen umherirren."
  },
  AvgDialog_34981_Content_20 = {
    Text = "Murphy joggte zu Celeste und hielt sanft ein Stück weißes Gaze, das von Celestes Schulter hing – es sah aus wie ein Verband."
  },
  AvgDialog_34981_Content_21 = {
    Text = "Du blickst zu Celeste auf und triffst ihren Blick. Während der Körper des Linkers schwächer wird, verschlechtert sich ihr Zustand weiter, und sie scheint zu erschöpft, um zu sprechen."
  },
  AvgDialog_34981_Content_22 = {
    Text = "Sie bewegte ihre Lippen und erzeugte einen kaum hörbaren Ton. Du hast nie Lippenlesen gelernt, doch du hast klar verstanden, was sie sagen wollte—"
  },
  AvgDialog_34981_Content_23 = {
    Text = "Es war nicht ich."
  },
  AvgDialog_34981_Content_24 = {
    Text = [[
Ja, es ist nicht sie.
Bist du dir absolut sicher?]]
  },
  AvgDialog_34981_Content_25 = {
    Text = "Diese immense Energie, wie ein Sternencluster, kann unmöglich aus ihrem schwachen Körper stammen."
  },
  AvgDialog_34981_Content_3 = {
    Text = "Ramona umklammert deine Hand fest, ihre Augen scannen dich aufmerksam. Sie gibt dir keine Chance zu sprechen, und misst die Narben auf deinem Körper Inch für Inch..."
  },
  AvgDialog_34981_Content_4 = {
    Text = "Du hast zu viele Verletzungen erlitten, als du gegen Miryam und Goliath gekämpft hast. Ich muss deine Wunden untersuchen, um sicherzustellen, dass es keine Infektionen oder weitere Verschlechterungen gibt..."
  },
  AvgDialog_34981_Content_5 = {
    Text = "Als Ramonas Hand auf die Taille drückte, die einst von Miryams Macht zusammengedrückt und verdreht worden war, spürte sie keinen Schmerz."
  },
  AvgDialog_34981_Content_6 = {
    Text = "Dann riecht sie das Medikament und bewegt sich hinter dich, indem sie dein Haar hinten am Kopf hebt.\nNachdem sie dein unordentliches Haar sorgfältig untersucht hat, schweigt sie einen Moment—eine ungewöhnliche Reaktion."
  },
  AvgDialog_34981_Content_7 = {
    Text = "...Wer hat dir Salbe auf den Kopf geschmiert? Hier sind Blutspuren, aber keine Wunde."
  },
  AvgDialog_34981_Content_8 = {
    Text = "Husten, Husten... Also warst du doch nicht verletzt. Ich sah Blut auf der Rückseite deines Kopfes und dachte..."
  },
  AvgDialog_34981_Content_9 = {
    Text = "Sie hockte sich schließlich neben dich und untersuchte vorsichtig dein Waden."
  },
  AvgDialog_34982_Content_1 = {
    Text = "Du stecktest den Kopf aus der Cockpit-Tür und sahst Seefahrer, die sich auf dem Deck ausbreiteten. Einige schienen normal, andere beherbergten Parasiten, einige sahen schlangenartig aus..."
  },
  AvgDialog_34982_Content_10 = {
    Text = "Komm und wirf einen Blick auf diesen Seefahrer."
  },
  AvgDialog_34982_Content_11 = {
    Text = "Ramona räumte ein Durcheinander aus Algen und Korallenabfällen weg, wobei sie einen Seefahrer freilegte, der darunter begraben war."
  },
  AvgDialog_34982_Content_12 = {
    Text = "Es hatte ebenfalls aufgehört zu atmen, seine Augen waren trüb und grau, seine schleimige Haut war in kurzer Zeit dehydriert und faltig. Dennoch erkannten du es klar."
  },
  AvgDialog_34982_Content_13 = {
    Text = "Ihre weiße Haut sticht unter den grauen Seefahrern hervor, wie eine Gans unter Spatzen oder ein weißes Thanivian-Pferd unter grauen Eseln."
  },
  AvgDialog_34982_Content_14 = {
    Text = "Ich erinnere mich daran. Es hat noch keine Anzeichen von Parasitierung gezeigt. Wir waren nicht so zurückhaltend im Umgang damit... Aber was ist das Problem? Ich habe nichts Besonderes daran bemerkt."
  },
  AvgDialog_34982_Content_15 = {
    Text = "Denke sorgfältig nach: Unter welchen Umständen haben wir zuvor gegen den weißen Seefahrer gekämpft?"
  },
  AvgDialog_34982_Content_16 = {
    Text = "Hmm... wenn wir von Goliath verfolgt werden?"
  },
  AvgDialog_34982_Content_17 = {
    Text = "Warte, Goliath?!"
  },
  AvgDialog_34982_Content_18 = {
    Text = "Ja, der weiße Seefahrer... ist Goliaths persönliche Wache."
  },
  AvgDialog_34982_Content_19 = {
    Text = "Goliath... Hat ihn seit dem Kampf im Kraftraum jemand gesehen?"
  },
  AvgDialog_34982_Content_2 = {
    Text = "Puh—so müde.\nWenn Tulu hier wäre, wäre es einfacher, mit diesen Leuten umzugehen."
  },
  AvgDialog_34982_Content_20 = {
    Text = "Er war vor der Explosion nicht mehr im Kraftwerk."
  },
  AvgDialog_34982_Content_21 = {
    Text = "Wir haben einen potenziell tödlichen Fehler gemacht: die Existenz von Goliath völlig zu ignorieren."
  },
  AvgDialog_34982_Content_22 = {
    Text = "Bevor Ramona ihren Satz beenden konnte, verursachte ein gewaltsamer Aufprall, dass die Kabinentür zerbrach."
  },
  AvgDialog_34982_Content_23 = {
    Text = "Der Erwacher in der Form eines Meermann zog seinen Dreizack zurück und blickte auf die gefallenen Seefahrer hinab. Die Hälfte von ihm war im Schatten des riesigen Schornsteins verborgen, was seinen Ausdruck unleserlich machte."
  },
  AvgDialog_34982_Content_24 = {Text = "Caecus!"},
  AvgDialog_34982_Content_25 = {
    Text = "Caecus warf einen Blick auf den Kapitän und wandte sich dann ab, um zu vermeiden, jemanden im Cockpit anzusehen. \nEr verbeugte sich tief zur Deck, um respektvoll seinen neuen Meister zu begrüßen."
  },
  AvgDialog_34982_Content_26 = {
    Text = "Sir, sie verstecken sich tatsächlich im Cockpit."
  },
  AvgDialog_34982_Content_27 = {
    Text = "Der Riese hielt mit schweren Schritten den oberen Teil des Türrahmens fest und blockierte das ganze Mondlicht draußen."
  },
  AvgDialog_34982_Content_28 = {
    Text = [[
Zeit bis zum Ausrichten:
60 Minuten verbleibend]]
  },
  AvgDialog_34982_Content_3 = {
    Text = "Es gibt kein Geräusch von unter der Treppe; es sollte für jetzt vorbei sein."
  },
  AvgDialog_34982_Content_4 = {
    Text = "Du hast den leblosen Seefahrer zu deinen Füßen getreten."
  },
  AvgDialog_34982_Content_5 = {
    Text = "Im Kampf zielst du auf das parasitäre Wachstum in seinem Bauch als Schwachstelle. Seine Haut riss unter den wiederholten Treffern auf und floss dicker, übelriechender Blut aus."
  },
  AvgDialog_34982_Content_6 = {
    Text = "Ich frage mich, ob das Blut, das von der Auflösung betroffen ist, giftig ist. Es scheint, als wäre viel D-Schlamm darin gemischt.\nRamona, sollten wir diese Typen ins Meer werfen?"
  },
  AvgDialog_34982_Content_7 = {
    Text = "Warte... Ich erinnere mich, die Puppe hat gesagt, wir könnten das nicht tun."
  },
  AvgDialog_34982_Content_8 = {
    Text = "Das \"Mythag Universität Ermittler Feldhandbuch\" besagt eindeutig, dass Ermittler aufgrund unklarer Diffusions- und Verbreitungsmechanismen vermeiden sollten, D-Slime während der Operationen in den natürlichen Zyklus eintreten zu lassen."
  },
  AvgDialog_34982_Content_9 = {
    Text = "Ich freue mich, dass du Dolls Lektionen erinnerst, aber jetzt ist nicht die Zeit, um über ökologische Verschmutzung nachzudenken."
  },
  AvgDialog_34983_Content_1 = {
    Text = "Studenten, seid ihr noch in der Lage, es zu bewältigen?"
  },
  AvgDialog_34983_Content_2 = {
    Text = "Sie sind allesamt wahnsinnige Seefahrer und Auflösungs-Mutanten."
  },
  AvgDialog_34983_Content_3 = {
    Text = "Ihre Aktionen scheinen willkürlich, als ob es keinen Anführer gäbe, der sie leitet.  \nSie scheinen hierher durch das Dampfpfeifensignal gelockt worden zu sein. Wenn es nur diese Feinde sind, können wir sie bewältigen."
  },
  AvgDialog_34983_Content_4 = {
    Text = "In Ordnung, wenn ihr Unterstützung braucht, versucht, Celeste in eurem Herzen anzurufen."
  },
  AvgDialog_34983_Content_5 = {
    Text = "Obwohl die Kontrolle über das Schiff verloren ging, war es seit Jahren ihr Terrain.\nIch glaube, Celestes Macht muss einige Spuren hinterlassen haben, die dir helfen können."
  },
  AvgDialog_34983_Content_6 = {
    Text = "Ich gebe Vollgas! Halt dich fest und pass auf, dass dir nicht übel wird!"
  },
  AvgDialog_35167_Content_1 = {
    Text = "Nacht des Todes, des Mets & der Lieder"
  },
  AvgDialog_35167_Content_10 = {
    Text = "Was diese Frau denkt, kann niemand erraten. Jedoch—"
  },
  AvgDialog_35167_Content_11 = {
    Text = "Die kambrische Seuche ist unheilbar. Wenn die Infizierten freigelassen werden, weiß der Himmel, was geschehen würde."
  },
  AvgDialog_35167_Content_12 = {
    Text = "Ungeachtet von Wandas Absichten haben ihre Handlungen in der Tat die umliegenden Lehen gerettet..."
  },
  AvgDialog_35167_Content_13 = {
    Text = [[
Kambrium Schloss
Festsaal]]
  },
  AvgDialog_35167_Content_14 = {
    Text = "Du drückst die schwere Holztür des Saales auf."
  },
  AvgDialog_35167_Content_15 = {
    Text = "Gleißendes Licht ergießt sich wie gefallene Sterne über den Raum. Die Luft ist erfüllt vom süßen Aroma von Wein und erlesenen Speisen."
  },
  AvgDialog_35167_Content_16 = {
    Text = "Die Bauern von Kambrisch haben ihre feinsten Kleider angelegt und tanzen fröhlich im Rhythmus der Musik."
  },
  AvgDialog_35167_Content_17 = {
    Text = "Obwohl die Welt draußen von der Auflösung verschlungen wird, ist der Saal voller Heiterkeit."
  },
  AvgDialog_35167_Content_18 = {
    Text = "Ist das der legendäre Apfelpudding? Ich habe in meinem ganzen Leben noch nie etwas so Köstliches geschmeckt..."
  },
  AvgDialog_35167_Content_19 = {
    Text = "Hahaha! Ich bin so glücklich! Wenn ich heute Nacht sterbe, hat sich alles gelohnt!"
  },
  AvgDialog_35167_Content_2 = {
    Text = [[
Guderian's Lehen
Jagdreviere]]
  },
  AvgDialog_35167_Content_20 = {
    Text = "Tanzt! Kommt schon, alle tanzen!"
  },
  AvgDialog_35167_Content_21 = {
    Text = "Du drängst dich durch die geschäftige Menge und findest Wanda am hinteren Ende sitzend."
  },
  AvgDialog_35167_Content_23 = {
    Text = "Sie lehnte sich lässig an den untoten Diener, hielt ein Glas Wein und beobachtete dich gelassen"
  },
  AvgDialog_35167_Content_24 = {
    Text = "Guten Abend, Herr Mönch. Ich dachte, Sie würden nicht an diesem Fest teilnehmen"
  },
  AvgDialog_35167_Content_25 = {
    Text = "Manchmal möchte ich meine Neugier befriedigen."
  },
  AvgDialog_35167_Content_26 = {
    Text = "<Gray:Außerdem, bei all dem D-Schleim draußen, wohin sollte ich sonst gehen...?>"
  },
  AvgDialog_35167_Content_27 = {
    Text = "Jemand zupft sanft am Saum deiner Kutte."
  },
  AvgDialog_35167_Content_28 = {
    Text = "Ihr seid... Susannas Bruder!"
  },
  AvgDialog_35167_Content_29 = {
    Text = "Ich habe einen Namen, wisst Ihr! Alle nennen mich Kleine Beckmann."
  },
  AvgDialog_35167_Content_3 = {
    Text = "Was? Du sagst, Wanda hat alle Riegel geschmolzen und veranstaltet einen luxuriösen Ball im Schloss mit allen Dorfbewohnern von Cambrian?"
  },
  AvgDialog_35167_Content_30 = {
    Text = "Guten Abend, kleiner Beckman. Wohin ist deine Schwester gegangen?"
  },
  AvgDialog_35167_Content_31 = {
    Text = "Die große Schwester und die anderen, die nicht krank waren, sind zusammen aufgebrochen..."
  },
  AvgDialog_35167_Content_32 = {
    Text = "Kleine Beckmann senkt niedergeschlagen den Kopf. Er schnieft, dann blickt er mit großen, wässrigen Augen zu dir auf."
  },
  AvgDialog_35167_Content_33 = {
    Text = "Guter Herr, wollt Ihr mit mir tanzen? Ich habe keinen Partner, buhuhu..."
  },
  AvgDialog_35167_Content_34 = {
    Text = "Kleiner, Mönchen ist das Tanzen nicht gestattet."
  },
  AvgDialog_35167_Content_35 = {
    Text = "Jetzt erkläre ich, dass du tanzen darfst, vergiss die alten Regeln"
  },
  AvgDialog_35167_Content_36 = {
    Text = "Im Kambrischen bin ich — <Big:DAS GESETZ SELBST!>"
  },
  AvgDialog_35167_Content_37 = {
    Text = "Du blickst in Kleine Beckmanns hoffnungsvolle Augen und schluckst deine Ablehnung hinunter."
  },
  AvgDialog_35167_Content_38 = {
    Text = "Entschuldigung, ich kann auch nicht tanzen, aber ich kann mit dir ein paar Runden drehen"
  },
  AvgDialog_35167_Content_39 = {
    Text = "Du nimmst Kleine Beckmanns Hand und führst ihn in die Mitte der Halle, wo ihr euch in das Meer der Dorfbewohner einreiht, die sich zur Melodie wiegen."
  },
  AvgDialog_35167_Content_4 = {
    Text = "Es ist die reine Wahrheit! Ich habe gehört, dass alle, die nicht infiziert waren, bereits gegangen sind. Die Einzigen, die noch bei diesem Tanz sind, sind die todkranken."
  },
  AvgDialog_35167_Content_40 = {
    Text = "Röcke flattern und wirbeln im Kerzenlicht wie tausend bunte, sich drehende Törtchen."
  },
  AvgDialog_35167_Content_41 = {
    Text = "Du treibst durch diesen goldenen Ozean aus Licht und Gesang, schließlich eingetaucht in die aufsteigenden Blasen der Freude."
  },
  AvgDialog_35167_Content_42 = {
    Text = "Kleine Beckmanns Beinarbeit ist nicht besser als deine. Er wackelt ziellos im Takt, sein Gesicht glüht in einem strahlenden, fröhlichen Rot."
  },
  AvgDialog_35167_Content_43 = {
    Text = "Hahaha! So glücklich! Das ist der beste Tag meines Lebens!"
  },
  AvgDialog_35167_Content_44 = {
    Text = "Mein Herr, nehmt meine Hand! Lasst uns zusammen wirbeln!"
  },
  AvgDialog_35167_Content_45 = {
    Text = "Schneller, noch schneller!"
  },
  AvgDialog_35167_Content_46 = {
    Text = "<Red:Schneller...>"
  },
  AvgDialog_35167_Content_47 = {
    Text = "Schnel@2..."
  },
  AvgDialog_35167_Content_48 = {
    Text = "Kleiner Beckman, dein Gesicht?!"
  },
  AvgDialog_35167_Content_49 = {
    Text = "<Change> Tanze mit mir..."
  },
  AvgDialog_35167_Content_5 = {
    Text = "Hahaha! Ich habe mir so viel Mühe gegeben, einen Spitzel an ihrer Seite einzuschleusen... es scheint, ich habe meine Mühe verschwendet."
  },
  AvgDialog_35167_Content_50 = {
    Text = "Tintenartiger D-Schleim beginnt aus den Augen des Jungen zu fließen, doch er lächelt weiter, während er nach dir greift."
  },
  AvgDialog_35167_Content_51 = {
    Text = "Ein kalter Hauch traf deine Nase. Du blicktest auf und sahst, wie schwarzer Schleim langsam vom Kronleuchter tropfte"
  },
  AvgDialog_35167_Content_52 = {
    Text = "Ein Tropfen. Zwei."
  },
  AvgDialog_35167_Content_53 = {
    Text = "Du schaust erschrocken um dich und bemerkst, dass viele Leute unterschiedliche Grade von Verfall an ihren Kleidern, Armen und sogar Gesichtern haben"
  },
  AvgDialog_35167_Content_54 = {
    Text = "Aber sie tanzen immer noch fröhlich"
  },
  AvgDialog_35167_Content_55 = {
    Text = "Mein Herr, warum ignoriert Ihr mich? Mögt Ihr mich nicht mehr...?"
  },
  AvgDialog_35167_Content_56 = {
    Text = "Der Junge streckte seine klebrigen Hände aus und umarmte dich, Traurigkeit strömte aus seinen leeren Augen"
  },
  AvgDialog_35167_Content_57 = {
    Text = "Bleib bei mir... Bleib bei mir..."
  },
  AvgDialog_35167_Content_6 = {
    Text = "Bei einer so schrecklichen Seuche versucht sie nicht einmal zu fliehen. Sie sperrt einfach alle ein, um auf den Tod zu warten..."
  },
  AvgDialog_35167_Content_7 = {
    Text = "Ist es wahr, wie die Gerüchte sagen, dass sie völlig verrückt geworden ist?"
  },
  AvgDialog_35167_Content_8 = {
    Text = "Eure Worte sind recht faszinierend. War sie denn jemals eine Frau von klarem Verstand?"
  },
  AvgDialog_35167_Content_9 = {
    Text = "Äh... nun ja..."
  },
  AvgDialog_35529_Content_1 = {
    Text = "Captain, vertraust du wirklich den Worten dieses Fischmanns? Er ist nicht nur ein niederer Botenläufer im Kult."
  },
  AvgDialog_35529_Content_10 = {
    Text = "Caecus... er wünscht sich einfach zu sehr Anerkennung."
  },
  AvgDialog_35529_Content_11 = {
    Text = "Ich weiß, dass du vielleicht Bedenken wegen ihm hast, aber ich kenne dieses Kind gut genug. Die Tatsache, dass er von sich aus zu uns gekommen ist, zeigt, dass er in seinem Herzen bereits eine Entscheidung getroffen hat."
  },
  AvgDialog_35529_Content_12 = {
    Text = "Ich werde zuerst in die Kabine gehen, um die Situation zu überprüfen. Wenn alles gut ist, rufe ich dich hinein."
  },
  AvgDialog_35529_Content_2 = {
    Text = "Wenn ich mich recht erinnere, wurde die Geisterkraft von Caecus, um rational als Erwacher zu bleiben, sogar von Miryam bereitgestellt... Du hast es selbst bestätigt."
  },
  AvgDialog_35529_Content_3 = {
    Text = "Außerdem, wenn wir der Nachricht, die er gesendet hat, nicht vertraut hätten, wären wir nicht an diesem Hafen geblieben..."
  },
  AvgDialog_35529_Content_4 = {
    Text = "Information?"
  },
  AvgDialog_35529_Content_5 = {
    Text = "Murphy warf einen Blick auf Elton und, nachdem er seinen stummen Nicken der Zustimmung erhalten hatte, räusperte sie sich und fuhr fort."
  },
  AvgDialog_35529_Content_6 = {
    Text = "Unser ursprünglicher Plan war es, sechs volle Monate im Bereich Sonanil zu bleiben, um die Sternenkonstellation zu vermeiden."
  },
  AvgDialog_35529_Content_7 = {
    Text = "Nach diesem werden wir durch die Welt reisen, dem Streben des Seefahrers ausweichen und nach einem Weg suchen, es zu entfernen, aber..."
  },
  AvgDialog_35529_Content_8 = {
    Text = "Aber während eines Versorgungsstopps erhielt ich eine Nachricht vom Vermittler. \nDie Nachricht besagte, dass Caecus bereit war, die Medizin ein letztes Mal zu übergeben."
  },
  AvgDialog_35529_Content_9 = {
    Text = "Ist der Standort auf Brillport eingestellt? Das ist die Fischerstadt, in der die Seefahrer uns auf dem Schiff eingeholt haben."
  },
  AvgDialog_35530_Content_1 = {
    Text = "Tulu, bitte schütze Murphy und Celeste außerhalb des Cockpits.\nRamona und ich werden dem Kapitän hinein folgen, um die Situation zu überprüfen."
  },
  AvgDialog_35530_Content_2 = {
    Text = "Tulu hielt nicht dagegen. Mit seinen Tentakeln hinderte er Murphy daran, ihm zu folgen, und zog sie sowie Celeste in die Schatten neben der Tür."
  },
  AvgDialog_35530_Content_3 = {
    Text = "Elton trat zu dir und wischte deine Hand vom Lukenrand."
  },
  AvgDialog_35530_Content_4 = {
    Text = "Lass mich mich darum kümmern."
  },
  AvgDialog_35530_Content_5 = {
    Text = "Das Cockpit ist tatsächlich leer von Goliath, nur ein paar Seefahrer wandern benommen umher."
  },
  AvgDialog_35530_Content_6 = {
    Text = "Kein Zeichen eines Hinterhalts.\nDer Kapitän hatte recht... Caecus hat uns nicht getäuscht."
  },
  AvgDialog_35530_Content_7 = {
    Text = "Haha, ich habe dir gesagt, Caecus ist von Natur aus nicht schlecht... Er wurde nur nicht gelehrt, was richtig ist."
  },
  AvgDialog_35530_Content_8 = {
    Text = "Es liegt an dir, mit diesen Leuten umzugehen. Mach weiter und lass sie nicht länger mit meinem Helm herumspielen."
  },
  AvgDialog_35531_Content_1 = {
    Text = "Du und Ramona machen einen Umweg und erreichen schließlich die Tür auf der anderen Seite des Kraftwerks."
  },
  AvgDialog_35531_Content_10 = {
    Text = "Ramona flüsterte und deutete auf die Seefahrer, die von den „Katastrophen“ betroffen waren und Parasiten aus ihren Bäuchen gewachsen hatten."
  },
  AvgDialog_35531_Content_11 = {
    Text = "Vermeide sie so weit wie möglich. Den Status des Boilers zu überprüfen, hat oberste Priorität."
  },
  AvgDialog_35531_Content_2 = {
    Text = "Diese Tür wurde während deines Kampfes mit Miryam im Kreuzfeuer erwischt. Das Türblatt ist völlig verformt und hängt wackelig im Rahmen. Du hast es geschafft, dich ohne großen Aufwand hindurchzuzwängen."
  },
  AvgDialog_35531_Content_3 = {Text = "Das—"},
  AvgDialog_35531_Content_4 = {
    Text = "Ramona hielt dir schnell den Mund zu und zog dich hinter einige Eisenplattenschutt."
  },
  AvgDialog_35531_Content_5 = {
    Text = "Speerkämpfer, Schwertkämpfer, buckelige Gestalten, die am Boden kriechen..."
  },
  AvgDialog_35531_Content_6 = {
    Text = "Überall, wo du hinschaust, sind Seefahrer in verschiedenen Posen. Sie bewegen sich um die Trümmer des Kraftwerks und häufen verbrannte Materialien von den Explosionen an."
  },
  AvgDialog_35531_Content_7 = {
    Text = "Du durchsuchtest deinen Geist eine Weile, bevor du ein Wort fandest, um dieses Verhalten zu beschreiben—"
  },
  AvgDialog_35531_Content_8 = {
    Text = "\"Nistplatz\"."
  },
  AvgDialog_35531_Content_9 = {
    Text = "In der Tat... Sie zeigen typisches Nistverhalten. Vielleicht beeinflusst durch den Kern der Katastrophen, versuchen sie, diese Hyperplasien zu erzeugen..."
  },
  AvgDialog_35532_Content_1 = {Text = "Abgrund"},
  AvgDialog_35532_Content_10 = {
    Text = "Aus Hilflosigkeit siehst du zum Mond draußen am Fenster."
  },
  AvgDialog_35532_Content_11 = {
    Text = "Der Mond ist zu groß und zu hell.\nMethoden wie Mondentfernung und Sternauswahl sind in dieser Umgebung ineffektiv."
  },
  AvgDialog_35532_Content_12 = {
    Text = "Geführt von Ramona, blickst du auf den außergewöhnlich großen Vollmond."
  },
  AvgDialog_35532_Content_13 = {
    Text = "Es war abnorm groß, das nächtliche Himmels und Meer mit einem Glanz bedeckend, identisch mit dem des Vollmonds."
  },
  AvgDialog_35532_Content_14 = {
    Text = "Du erkennst, dass es näher kommt. So nah, dass dein Geist seine abnormale Strahlung zu spüren scheint, sowohl erfrischend als auch brennend."
  },
  AvgDialog_35532_Content_15 = {
    Text = "Huch... Huch..."
  },
  AvgDialog_35532_Content_16 = {
    Text = "Ausrichten..."
  },
  AvgDialog_35532_Content_17 = {
    Text = "Murphys Atmung wurde lauter, und als sich alle Augen auf sie richteten, kam jeder Atemzug mit einem pfeifenden Geräusch, fast so, als würde Luft entweichen."
  },
  AvgDialog_35532_Content_18 = {
    Text = "Murphy? Geht es dir gut? Lass mich dir helfen, dich hinzusetzen und auszuruhen."
  },
  AvgDialog_35532_Content_19 = {
    Text = "Mir geht es bestens! Husten, husten..."
  },
  AvgDialog_35532_Content_2 = {
    Text = "Celeste, aus welcher Richtung weht der Wind?"
  },
  AvgDialog_35532_Content_20 = {
    Text = "Murphy antwortete dir laut, verschluckte sich aber und begann heftig zu husten"
  },
  AvgDialog_35532_Content_21 = {
    Text = "Jeder kann sehen, dass sie sich kaum aufrecht halten kann."
  },
  AvgDialog_35532_Content_22 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35532_Content_23 = {
    Text = "Aber ich fühle mich ein wenig „unwohl.“"
  },
  AvgDialog_35532_Content_24 = {
    Text = "Meine Beine sind kraftlos, und mein Kopf tut immer noch ein wenig weh."
  },
  AvgDialog_35532_Content_25 = {
    Text = "Während du sprichst, setzt du dich gegen die Wand des Cockpits."
  },
  AvgDialog_35532_Content_26 = {
    Text = "Mit deinem \"Fall\" tut Murphy nicht mehr so, als wäre alles in Ordnung. Sie verliert sofort ihre Kraft und bewegt sich entlang der Wand zu deiner Seite."
  },
  AvgDialog_35532_Content_27 = {
    Text = "Mach eine Pause... nur für einen Moment..."
  },
  AvgDialog_35532_Content_28 = {
    Text = "Sie lehnte sich gegen die Wand und rutschte zu Boden, ohne sich darum zu kümmern, ob ihre Haltung damenhaft war oder nicht."
  },
  AvgDialog_35532_Content_29 = {
    Text = "Sie wollte einen Halt finden, um sich davon abzuhalten, vollkommen zusammenzubrechen. Nach einigem Tasten lehnte sie sich an deine Schulter."
  },
  AvgDialog_35532_Content_3 = {
    Text = "Celeste streckte die Hand zur Tür aus, die Augen geschlossen, spürte deine Richtung und fühlte die Meeresbrise, die ihren zierlichen Handgelenk traf."
  },
  AvgDialog_35532_Content_30 = {
    Text = "Nur einen Moment..."
  },
  AvgDialog_35532_Content_31 = {
    Text = "Nach ein paar Sekunden hörtest du ein schnelles, aber regelmäßiges Atmen.\nMurphy verlor erneut das Bewusstsein"
  },
  AvgDialog_35532_Content_32 = {
    Text = "Entsetzliche bläulich-schwarze Flecken erschienen auf Murphys Gesicht, wie Pflanzenwurzeln, die tief unter ihrer Haut verankert waren und ihr zerbrechliches Leben aussogen."
  },
  AvgDialog_35532_Content_33 = {
    Text = "Der Gott, den ich verbinde, kommt aus den unzähligen Sternen, selbst eine Fälschung ist für Menschen unüberwindbar"
  },
  AvgDialog_35532_Content_34 = {
    Text = "Der Blutfluss des Gastgebers wird von Ihm durchtrennt."
  },
  AvgDialog_35532_Content_35 = {
    Text = "Was ist, wenn wir die Operation jetzt durchführen?"
  },
  AvgDialog_35532_Content_36 = {
    Text = "Keeper, uns fehlen einfach die notwendigen Bedingungen, um jetzt eine Operation an ihr durchzuführen."
  },
  AvgDialog_35532_Content_37 = {
    Text = "Maximale Geschwindigkeit wurde bereits erreicht. Mit dem beschädigten Dampfkessel können wir nicht schneller fahren."
  },
  AvgDialog_35532_Content_38 = {
    Text = "Nicht in der Lage, eine Operation durchzuführen, und auf keine Weise rechtzeitig zum Land zurückzukehren... Gibt es wirklich keine Lösung?"
  },
  AvgDialog_35532_Content_39 = {
    Text = "Tulu warf einen Blick auf den riesigen Mond draußen am Fenster und schüttelte den Kopf."
  },
  AvgDialog_35532_Content_4 = {
    Text = "Westwind, 22 Knoten."
  },
  AvgDialog_35532_Content_40 = {
    Text = "Bist du sogar ratlos? Gibt es nichts, was du tun kannst, du, der die Prophezeiung der Wiederbelebung der Götter geliefert hat?"
  },
  AvgDialog_35532_Content_41 = {
    Text = "Wie könntest du es wissen..."
  },
  AvgDialog_35532_Content_42 = {
    Text = "Aus Miryams Einstellung dir gegenüber und ihren fragmentierten Worten, bevor sie in den Wahnsinn fiel, ist die Wahrheit nicht schwer zu erschließen."
  },
  AvgDialog_35532_Content_43 = {
    Text = "Nur der Verrat des Gottes konnte die Gläubigen zu einem solchen Wahnsinn treiben."
  },
  AvgDialog_35532_Content_44 = {Text = "...Ja."},
  AvgDialog_35532_Content_45 = {
    Text = "In der Tat habe ich ihr eine solche Prophezeiung überbracht, aber das sogenannte \"Orakel\" existiert nicht."
  },
  AvgDialog_35532_Content_46 = {Text = "Was?"},
  AvgDialog_35532_Content_47 = {
    Text = "Lange bevor die Flut kam, verlor ich die Fähigkeit, aus den Träumen der Götter in die Zukunft zu blicken.\nIch weiß nicht, wo Er ist, vielleicht ist Er erwacht oder vielleicht ist Er gegangen"
  },
  AvgDialog_35532_Content_48 = {
    Text = "Deine Prophezeiung"
  },
  AvgDialog_35532_Content_49 = {
    Text = "Miryam ist eine gläubige Anhängerin, die dem Reich Gottes gewidmet ist und von meinem Willen getrieben wird."
  },
  AvgDialog_35532_Content_5 = {
    Text = "Verstanden, Kurs anpassen."
  },
  AvgDialog_35532_Content_50 = {
    Text = "Ich hatte gehofft, meine Worte würden sie in ihren letzten Momenten trösten, nie gedacht, dass sie sie als Evangelium betrachten und versuchen würde, das Göttliche Reich wieder aufzubauen."
  },
  AvgDialog_35532_Content_51 = {Text = "Das alles"},
  AvgDialog_35532_Content_52 = {
    Text = "Ja, das ist alles meine Schuld"
  },
  AvgDialog_35532_Content_53 = {
    Text = "Im nächsten Moment war es, als hätte die Welt den Pausenknopf gedrückt, alle Geräusche verstummten."
  },
  AvgDialog_35532_Content_54 = {
    Text = "Wenn nicht für Murphs schwachen Atem auf dir, hättest du denken können, dass sogar die Zeit zum Stillstand gekommen ist."
  },
  AvgDialog_35532_Content_55 = {
    Text = "Warte... Ich kann das Geräusch der Propeller, die das Wasser treffen, nicht mehr hören."
  },
  AvgDialog_35532_Content_56 = {
    Text = "Elton kam zu sich, lief um die Konsole und versuchte jede Operation, die ihm einfiel, aber ohne Erfolg."
  },
  AvgDialog_35532_Content_57 = {
    Text = [[
Der Sonanil schwebt leise auf den Wellen, wie ein einsamer Riese, der vom Meer umarmt wird.
Verblasst und isoliert.]]
  },
  AvgDialog_35532_Content_58 = {
    Text = "Die Stromversorgung hat Probleme. Ich gehe zum Kraftraum, um nachzusehen."
  },
  AvgDialog_35532_Content_59 = {
    Text = "Lass mich das übernehmen. Ich weiß ein wenig über mechanische Strukturen.\nWenn es nur um Zündung und einfache Reparaturen geht, kann ich das schaffen."
  },
  AvgDialog_35532_Content_6 = {
    Text = "Elton stand wieder am Steuer. Da keine Feinde da waren, die ihm in die Quere kamen, steuerte er das Schiff mit einem neu gefundenen Selbstbewusstsein."
  },
  AvgDialog_35532_Content_60 = {
    Text = "Ich werde mit dir gehen."
  },
  AvgDialog_35532_Content_61 = {
    Text = "Tulu, ich übertrage die Sicherheit aller anderen an dich, während Ramona und ich nachforschen."
  },
  AvgDialog_35532_Content_62 = {
    Text = "Tulu nickte und streckte einen Tentakel aus, um dir zu helfen, Murphy sanft auf den Boden zu legen."
  },
  AvgDialog_35532_Content_63 = {
    Text = "Das letzte Mal, als ich den Rumpf in Stand hielt, ersetzte ich die Zündkerzen in mehreren Kesseln. Wenn das Feuer erlischt, kannst du es neu entfachen, indem du genügend Kohle hinzufügst und das Gerät benutzt."
  },
  AvgDialog_35532_Content_64 = {
    Text = "In Ordnung, lass uns jetzt hingehen."
  },
  AvgDialog_35532_Content_65 = {
    Text = "Du nickst Ramona zu und bist gerade dabei, dich zu bewegen, als eine eisige Hand sanft dein Knöchel ergreift."
  },
  AvgDialog_35532_Content_66 = {
    Text = "Murphy kämpfte darum, sich aufzusetzen, die schwarzen Flecken in ihrem Gesicht verblassten, als Sauerstoff ein- und ausströmte."
  },
  AvgDialog_35532_Content_67 = {
    Text = "Ihre Stimme war so schwach wie eine verwelkte Blume, trug aber dennoch einen Ton des Widerstands."
  },
  AvgDialog_35532_Content_68 = {
    Text = "Du wirst zurückkommen... oder?"
  },
  AvgDialog_35532_Content_69 = {
    Text = "Ja, wir werden zurückkehren."
  },
  AvgDialog_35532_Content_7 = {
    Text = "Er und Celeste arbeiteten zusammen, um den großen Frachter zu steuern, was normalerweise mindestens ein Team erfordert, um zu operieren."
  },
  AvgDialog_35532_Content_70 = {
    Text = "Du hockst neben ihr, hältst ihre Hand fest und versuchst, ihr Wärme zu übertragen."
  },
  AvgDialog_35532_Content_71 = {
    Text = "Haben wir nicht versprochen, dich zurück aufs Festland zu bringen?"
  },
  AvgDialog_35532_Content_8 = {
    Text = "Windböen schleuderten gelegentlich Sprühnebel in die Luft, doch unter ihrer Kontrolle blieb die Sonnellier so stabil wie ein Spielzeug, das in einer Badewanne schwebt."
  },
  AvgDialog_35532_Content_9 = {
    Text = "Sie sind so versiert, dass sie wissen, in welche Richtung sie gehen müssen, ohne sich auf irgendwelche Instrumente zu verlassen."
  },
  AvgDialog_35533_Content_1 = {
    Text = "Alte Bindungen, neu"
  },
  AvgDialog_35533_Content_10 = {
    Text = "Bin ich immer noch ich selbst?"
  },
  AvgDialog_35533_Content_11 = {
    Text = "Wer... bin ich?"
  },
  AvgDialog_35533_Content_12 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35533_Content_13 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_35533_Content_14 = {
    Text = "In einem unbekannten Ort verloren, ohne zu wissen, wie viel Zeit vergangen ist."
  },
  AvgDialog_35533_Content_15 = {
    Text = "Du kannst nichts anderes fühlen als den allmählich intensiver werdenden Klang der Flöte."
  },
  AvgDialog_35533_Content_16 = {
    Text = "Hör auf damit... Hör auf! Das ist nicht die Zeit für Musik; ich habe noch unerledigte Dinge!"
  },
  AvgDialog_35533_Content_17 = {
    Text = "Der Klang der Flöte wurde lauter, aber als er die Schwelle der menschlichen Toleranz überschritt, stoppte er plötzlich und hinterließ nur undeutliches Rauschen, das im Nichts widerhallte."
  },
  AvgDialog_35533_Content_18 = {
    Text = "<Change>Ewige..."
  },
  AvgDialog_35533_Content_19 = {
    Text = "Ein nachhallendes Geräusch erklingt aus den Tiefen des Universums, ähnlich dem chaotischen Schlafgerede oder dem unruhigen Wälzen, das die Sterne stört."
  },
  AvgDialog_35533_Content_2 = {
    Text = "Das Bewusstsein löste sich vom Körper, schwebte und verweilte in einem illusorischen Traum."
  },
  AvgDialog_35533_Content_20 = {
    Text = "Ein silberner Glanz blüht an Ort und Stelle, und gespannte Nerven beginnen sich zu entspannen."
  },
  AvgDialog_35533_Content_21 = {
    Text = "Der Bewusstseinsraum ist so hell wie Tageslicht. Bevor du reagieren kannst, fühlst du einen plötzlichen Sturz—"
  },
  AvgDialog_35533_Content_22 = {
    Text = "{Male=Er,Female=Sie} wacht auf"
  },
  AvgDialog_35533_Content_23 = {
    Text = "Hüter, Hüter! Kannst du meine Stimme hören?"
  },
  AvgDialog_35533_Content_24 = {
    Text = "...Was stimmt nicht mit mir?"
  },
  AvgDialog_35533_Content_25 = {
    Text = "Mit Ramonas Hilfe setzt du dich auf und schaust dich um, findest dich in einem Frachtraum, umgeben von D-Hyperplasie und deinen Gefährten."
  },
  AvgDialog_35533_Content_26 = {
    Text = "Wie fühlst du dich?"
  },
  AvgDialog_35533_Content_27 = {
    Text = "Du schaust auf deine Hände hinunter und versuchst die Melodie zu summen, die wiederholt in der Geisterwelt widerhallt, findest aber, dass du nur in Stößen ausatmen kannst."
  },
  AvgDialog_35533_Content_28 = {
    Text = "Ich fühle mich... nicht anders."
  },
  AvgDialog_35533_Content_29 = {
    Text = "Zählend hast du diesmal bereits dreimal ohnmächtig geworden.\nSagend, du fühlst nichts, lügst du?"
  },
  AvgDialog_35533_Content_3 = {
    Text = "Wo... bin ich?"
  },
  AvgDialog_35533_Content_30 = {
    Text = "Häufige plötzliche Ohnmachtsanfälle innerhalb kurzer Zeit stehen wahrscheinlich im Zusammenhang mit intrakraniellen oder neurologischen Symptomen."
  },
  AvgDialog_35533_Content_31 = {
    Text = "Ramona sprach, während sie deinen Kopf erneut sorgfältig überprüfte und sanft fast jeden Zentimeter deines Schädels mit ihren Fingerspitzen drückte."
  },
  AvgDialog_35533_Content_32 = {
    Text = "Keine Brüche wurden gefunden, aber falls es ein Hämatom oder eine andere Infektion gibt... wir müssen zur Schule zurückkehren und Doll untersuchen lassen, bevor wir eine Diagnose stellen."
  },
  AvgDialog_35533_Content_33 = {
    Text = "Die oberste Priorität ist es, an Land zurückzukehren und schnell zur Schule zurückzukehren.\nDas ist entscheidend für dich und Murphy..."
  },
  AvgDialog_35533_Content_34 = {
    Text = "Murphy starrte dich lange still an und schüttelte dann ausdruckslos den Kopf."
  },
  AvgDialog_35533_Content_35 = {
    Text = [[
%player% ist schon in diesem Zustand, also versuche nicht, den Helden zu spielen.
Du solltest gehen.]]
  },
  AvgDialog_35533_Content_36 = {
    Text = "Du nimmst das Rettungsboot, egal ob du ruderst oder treibst, mit Tulu und Ramona dort wird es kein Problem sein, zurück an Land zu kommen. Nur, nur..."
  },
  AvgDialog_35533_Content_37 = {
    Text = "<Small: Solange ich niemanden zurückhalte...>"
  },
  AvgDialog_35533_Content_38 = {
    Text = "Ich werde nicht gehen, bis das Parasiten in deinem Körper beseitigt ist."
  },
  AvgDialog_35533_Content_39 = {
    Text = "Murphy stampfte mit dem Fuß, zeigte auf dich und Ramona, dann auf den Kapitän und seinen Begleiter."
  },
  AvgDialog_35533_Content_4 = {
    Text = "Umgeben von Dunkelheit wird das verstreute silberne Licht, das du hinterlässt, schnell von der heranrückenden Schwärze verschlungen."
  },
  AvgDialog_35533_Content_40 = {
    Text = "Was ist mit ihnen?\nWas, wenn dieser \"Gott\" schlüpft und so groß ist, dass er das Schiff versenkt?"
  },
  AvgDialog_35533_Content_41 = {
    Text = "Wir werden auch nicht gehen."
  },
  AvgDialog_35533_Content_42 = {Text = "Hey!?"},
  AvgDialog_35533_Content_43 = {
    Text = "An dem Tag, an dem wir offiziell Ermittler wurden, schworen wir auf unsere Existenz, dem D-Phänomen um jeden Preis zu widerstehen."
  },
  AvgDialog_35533_Content_44 = {
    Text = "Wir sind bereit, den Rest unseres Lebens von Tod und Wahnsinn begleitet zu verbringen, selbst wenn unser eigener Untergang uns bevorsteht..."
  },
  AvgDialog_35533_Content_45 = {
    Text = "Ihr Guys? Macht mich nicht zum Lachen – das ist ein Todeswunsch!\nDieser Parasit ist ein Monster, ein Gott!"
  },
  AvgDialog_35533_Content_46 = {
    Text = "Wenn dies die letzte Stunde meines Lebens wäre, würde ich sie nicht mit Beten verschwenden"
  },
  AvgDialog_35533_Content_47 = {
    Text = "Ich glaube, du würdest es auch nicht, oder? Andernfalls, warum würdest du solche Anstrengungen unternehmen, um aus dem Kult zu entkommen?"
  },
  AvgDialog_35533_Content_48 = {Text = "Ich..."},
  AvgDialog_35533_Content_49 = {
    Text = "Dies ist nicht nur für dich. Denk daran, wir warten auch darauf, das Schiff zu verlassen."
  },
  AvgDialog_35533_Content_5 = {
    Text = "Du kannst fühlen, wie etwas aus deiner Geisterwelt entgleitet. Du greifst in die Dunkelheit und stellst fest, dass es ein Fragment deiner Erinnerung ist."
  },
  AvgDialog_35533_Content_50 = {
    Text = "Der Parasit in dir ist jetzt zum Kern der Auflösungs-Katastrophen geworden, was bedeutet, dass du jetzt auch eine der Verantwortlichkeiten der Mythag-Ermittler bist."
  },
  AvgDialog_35533_Content_51 = {
    Text = "Ich habe versprochen, nicht aufzugeben... Ich werde mein Versprechen nicht brechen."
  },
  AvgDialog_35533_Content_52 = {
    Text = "...Wahnsinnige, jeder Einzelne von ihnen."
  },
  AvgDialog_35533_Content_53 = {
    Text = "Murphy schniefte und schluckte das Schluchzen in seiner Stimme herunter."
  },
  AvgDialog_35533_Content_54 = {
    Text = "Also, was sollen wir jetzt tun? Die Crew von Goliath hat die Kabine übernommen. Wir können das Schiff so nicht segeln."
  },
  AvgDialog_35533_Content_55 = {
    Text = "Celeste, wie lange dauert es noch, bis wir anlegen?"
  },
  AvgDialog_35533_Content_56 = {
    Text = "Leere Ladung, nordöstlicher Wind mit 15 Knoten.\n... Kadath Standardzeit, 60 Minuten."
  },
  AvgDialog_35533_Content_57 = {
    Text = "Wie viel Zeit bleibt bis zum Ausrichten...?"
  },
  AvgDialog_35533_Content_58 = {
    Text = "Es ist noch Zeit."
  },
  AvgDialog_35533_Content_59 = {
    Text = "Celeste starrte den Kapitän leer an, als ob sie etwas bestätigen wollte."
  },
  AvgDialog_35533_Content_6 = {
    Text = "In deiner Erinnerung brachte Ramona dich zurück zur Mythag Universität. Puppe begrüßte dich am Schulplatz, zeigte sich besorgt um Ramona und hegte Zweifel an dir."
  },
  AvgDialog_35533_Content_60 = {
    Text = "Ihre Gestalt war bereits ätherisch geworden, sie transzendierte die Realität. Der Kapitän wollte ihr auf den Kopf tätscheln, aber letztendlich ging seine Hand nur durch die Luft über ihr."
  },
  AvgDialog_35533_Content_61 = {
    Text = "Celeste, beschleunige."
  },
  AvgDialog_35533_Content_62 = {
    Text = "Kapitän! Was machst du!? Du und Celeste seid in einem so schlechten Zustand, dass ihr eure Fähigkeiten nicht mehr nutzen könnt, um das Schiff zu steuern!"
  },
  AvgDialog_35533_Content_63 = {
    Text = "Der Erwacher nickt leicht und hebt beide Hände. Der Kompass in seiner Hand bewegt sich von selbst und strahlt schwaches Licht aus."
  },
  AvgDialog_35533_Content_64 = {
    Text = "Elton, stopp!"
  },
  AvgDialog_35533_Content_65 = {
    Text = "Der junge Seefahrer stürmte durch die Kabinentür. Kaum trat er ein, standen Ramona und Tulu sofort auf, um ihm den Weg zu versperren."
  },
  AvgDialog_35533_Content_66 = {
    Text = "Celeste senkte verwirrt ihre Hand, schaute zu Elton und wartete auf den nächsten Befehl von der Verknüpfung."
  },
  AvgDialog_35533_Content_67 = {
    Text = "Ich bin nicht hier, um zu kämpfen."
  },
  AvgDialog_35533_Content_68 = {
    Text = "Ich... habe etwas, das ich dir geben möchte."
  },
  AvgDialog_35533_Content_69 = {
    Text = "Sein Blick schweifte über alle hinweg und blieb bei Captain Elton hängen."
  },
  AvgDialog_35533_Content_7 = {Text = "Dann..."},
  AvgDialog_35533_Content_70 = {
    Text = "Elton winkte mit der Hand und näherte sich Caecus, während er Ramona und Tulu signalisierte, ihre Angriffshaltungen abzusenken."
  },
  AvgDialog_35533_Content_71 = {
    Text = "Komm nicht näher...!"
  },
  AvgDialog_35533_Content_72 = {
    Text = "Komm nicht zu nah. Wenn ich zu viel von deinem Geruch aufnehme, werden die anderen Seefahrer mich bemerken."
  },
  AvgDialog_35533_Content_73 = {
    Text = "Er warf ein Glasbehälter auf das Deck, damit es durch die Schräglage des Schiffes zu Eltons Füßen rollte."
  },
  AvgDialog_35533_Content_74 = {
    Text = [[
Medizin zur Stabilisierung des Geistes...
Gibst du mir die Medizin aus deinem eigenen Willen?]]
  },
  AvgDialog_35533_Content_75 = {
    Text = "Wenn du befürchtest, dass mit dem Medikament etwas nicht stimmt..."
  },
  AvgDialog_35533_Content_76 = {
    Text = "Elton gab der anderen Person keine Chance, zu Ende zu sprechen. Er zog den Korken heraus und schluckte ohne Zögern eine Handvoll Pillen."
  },
  AvgDialog_35533_Content_77 = {
    Text = "Versteh mich nicht falsch, Kleiner.\nIch mache mir nur Sorgen, dass du interne Bestrafungen von den Seefahrern erleiden könntest."
  },
  AvgDialog_35533_Content_78 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35533_Content_79 = {
    Text = "Sie werden es nicht herausfinden. Der Seefahrer, der für die Lagerung des Medikaments zuständig war, ist bei dieser Operation umgekommen."
  },
  AvgDialog_35533_Content_8 = {
    Text = "Dann verblassen deine Erinnerungen rasch, wie fließendes Wasser."
  },
  AvgDialog_35533_Content_80 = {
    Text = "Caecus schloss die Augen, mit einem ruhigen Gesichtsausdruck. Du konntest nicht sagen, ob er um seine gefallenen Kameraden trauerte."
  },
  AvgDialog_35533_Content_81 = {
    Text = "Captain, wenn du mir immer noch vertraust... bitte mach einen Umweg zurück zum Cockpit."
  },
  AvgDialog_35533_Content_82 = {
    Text = "Ich werde jetzt zurückgehen und versuchen, Lord Goliath abzulenken, aber wenn ich vorschlage, alle zu evakuieren, wird es zu gezielt wirken."
  },
  AvgDialog_35533_Content_83 = {
    Text = "Lord Goliath wird definitiv Leute zurücklassen, um das Cockpit zu bewachen. Was die Seefahrer betrifft, die zurückbleiben, bin ich machtlos."
  },
  AvgDialog_35533_Content_84 = {
    Text = "Caecus beendete seine Rede und drehte sich zum Gehen um."
  },
  AvgDialog_35533_Content_85 = {
    Text = "Caecus, warte!"
  },
  AvgDialog_35533_Content_86 = {
    Text = "Das ist nicht der richtige Zeitpunkt für uns, um uns zu treffen, aber..."
  },
  AvgDialog_35533_Content_87 = {
    Text = "Du hast gesagt, du würdest mir meinen Verrat nicht verübeln, oder?"
  },
  AvgDialog_35533_Content_88 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35533_Content_89 = {Text = "Absolut."},
  AvgDialog_35533_Content_9 = {
    Text = "Ein unheimlicher, ferner Flötenton durchbohrt deine Geistwelt wie ein Haken und versiegelt augenblicklich alle deine Sinne."
  },
  AvgDialog_35534_Content_1 = {
    Text = "Der Kohlenablauf dieses Kessels ist verstopft. Es sieht aus, als wäre er schon lange kaputt."
  },
  AvgDialog_35534_Content_10 = {
    Text = "Ramona nickte, hockte sich in den Schatten des Kessels und begann, die Maschinen zu inspizieren."
  },
  AvgDialog_35534_Content_11 = {
    Text = "Der Kapitän hat recht; die Zündkerze ist neu."
  },
  AvgDialog_35534_Content_12 = {
    Text = "Mit bloßem Auge scheint die äußere Wand des Boilers unversehrt... Sie sieht aus wie neu"
  },
  AvgDialog_35534_Content_13 = {
    Text = "Dies ist eine geschützte Ecke; der Wind, der durch die Öffnung im Rumpf bläst, sollte die Boilermaschine nicht beeinflusst haben... Wo ist es schiefgegangen?"
  },
  AvgDialog_35534_Content_14 = {
    Text = "Könnte es einfach sein, dass der Treibstoff ausgegangen ist?"
  },
  AvgDialog_35534_Content_15 = {
    Text = "Ramona nickte, ging zum Vorderteil des Kessels und öffnete die Tür. Ihr Ausdruck erstarrte plötzlich."
  },
  AvgDialog_35534_Content_16 = {
    Text = "Was ist los?"
  },
  AvgDialog_35534_Content_17 = {
    Text = "Bevor du reagieren konntest, zog Ramona dich schnell in Richtung der Türen des Kraftwerks, ohne sich darum zu kümmern, ob ihre Schritte irgendwelche nistenden Seefahrer stören würden."
  },
  AvgDialog_35534_Content_18 = {
    Text = "Der Schmelzofen ist nass! Jemand hat absichtlich den Dampfkessel gelöscht!"
  },
  AvgDialog_35534_Content_19 = {Text = "Falle?!"},
  AvgDialog_35534_Content_2 = {
    Text = "Es scheint, als ob hier alles von der Explosion betroffen war und es keinen Weg gibt, es zu entzünden."
  },
  AvgDialog_35534_Content_20 = {
    Text = "Der schlanke Körper des Jungen warf am Ausgang einen außergewöhnlich großen Schatten, während mehrere Seefahrer hinter ihm standen, was die Spannung und Gefahr in der kalten Luft verstärkte."
  },
  AvgDialog_35534_Content_21 = {Text = "Caecus..."},
  AvgDialog_35534_Content_22 = {
    Text = "Schau mich nicht so an..."
  },
  AvgDialog_35534_Content_23 = {
    Text = "Caecus’ Augen flackerten, seine Lippen zitterten, als wollte er etwas sagen, aber letztendlich wandte er den Kopf zur Seite und wich deinem sowie Ramonas prüfenden Blick aus."
  },
  AvgDialog_35534_Content_24 = {
    Text = "Hast du von Anfang an so gedacht? Jedes Schritt sorgfältig geplant, um uns in eine Falle zu führen.\nWaren all die Dinge, die du uns gesagt hast, nur eine Tarnung?"
  },
  AvgDialog_35534_Content_25 = {Text = "Ich..."},
  AvgDialog_35534_Content_26 = {
    Text = "Du hast nicht erlebt, was ich durchgemacht habe, also kannst du die Macht der Seefahrer nicht begreifen..."
  },
  AvgDialog_35534_Content_27 = {
    Text = "Du wirst es nicht verstehen, und <Yellow:solltest nicht hier sein>... Wenn ich du wäre, würde ich alle Mittel versuchen, um <Yellow:aus Lady Miryam zu entkommen>."
  },
  AvgDialog_35534_Content_28 = {
    Text = "Caecus’ Tonfall, Intonation und sogar die Grammatik wurden seltsam, ähnelten nicht mehr der Standardsprache der Leo."
  },
  AvgDialog_35534_Content_29 = {
    Text = "Wenn jemand dich zwingt, etwas gegen deinen Willen zu tun..."
  },
  AvgDialog_35534_Content_3 = {
    Text = "Du und Ramona tauscht Informationen in gedämpften Tönen aus, aus Angst vor der Aufmerksamkeit der Seefahrer."
  },
  AvgDialog_35534_Content_30 = {
    Text = "Nein! Hör auf!"
  },
  AvgDialog_35534_Content_31 = {
    Text = "Caecus schrie plötzlich, sein Gesicht veränderte sich schnell. Eine erstickende Angst strömte aus den Tiefen seiner Augen."
  },
  AvgDialog_35534_Content_32 = {
    Text = "Er griff steif nach seinem Hals und offenbarte einen dunklen Ring, der identisch war mit dem Zeichen, das du zuvor bei Goliath gesehen hast."
  },
  AvgDialog_35534_Content_33 = {
    Text = "Die alte Strafe aus Lemuria zieht sich langsam zusammen und lässt ihn hastig und mühsam atmen."
  },
  AvgDialog_35534_Content_34 = {
    Text = "Selbst wenn Anwacher keinen Sauerstoff zum Atmen brauchen, verzerrte der unerträgliche Schmerz sein Gesicht mit einem unaussprechlichen Ausdruck der Qual."
  },
  AvgDialog_35534_Content_35 = {
    Text = "Entschuldigung..."
  },
  AvgDialog_35534_Content_36 = {
    Text = "Entschuldigung... Ich... habe keine Wahl, außer..."
  },
  AvgDialog_35534_Content_4 = {
    Text = "Alle Dutzend Kessel im Kraftraum sind ausgegangen. Du und Ramona können sie nur nacheinander überprüfen."
  },
  AvgDialog_35534_Content_5 = {
    Text = "Du berührst einen kalten Kessel nach dem anderen, während die Seefahrer um dich herum Verzweiflung und Angst bis zum Äußersten verstärken."
  },
  AvgDialog_35534_Content_6 = {
    Text = "Es fühlt sich an, als ob dein Herz unter deinem Schädel pocht, sodass du nichts anderes hörst als sein rhythmisches Schlagen."
  },
  AvgDialog_35534_Content_7 = {
    Text = "Dann hielt das intensive Herzklopfen plötzlich an."
  },
  AvgDialog_35534_Content_8 = {
    Text = "Ramona, ich habe es gefunden!"
  },
  AvgDialog_35534_Content_9 = {
    Text = "Die Außenwand des kürzlich erloschenen Kessels ist immer noch brennend heiß, und Dampf steigt in dünnen Schwaden von deinen Handschuhen auf, während sie es berühren.\nAber du hast keine Zeit, dir darüber Sorgen zu machen. Aufgeregt rufst du leise deinen Partner an."
  },
  AvgDialog_35535_Content_1 = {
    Text = "Caecus kniete schwer auf dem Boden, seine Waffe wurde zu einem Krückstock, der seinen besiegten Körper stützte. Mit seiner letzten Kraft umklammerte er den Speergriff, als würde er den letzten Lichtstrahl festhalten."
  },
  AvgDialog_35535_Content_2 = {
    Text = "Caecus, du..."
  },
  AvgDialog_35535_Content_3 = {
    Text = [[
Er atmete schwer, schien ein paar Worte zu murmeln.
Um seine murmelige Sprache zu verstehen, musste man sich vor ihm hinknien.]]
  },
  AvgDialog_35535_Content_4 = {
    Text = "Gehe... <Big:Rennt!>"
  },
  AvgDialog_35535_Content_5 = {
    Text = "Caecus stieß dich plötzlich, verlor das Gleichgewicht und fiel hart auf den kalten, harten Boden."
  },
  AvgDialog_35535_Content_6 = {
    Text = "Im nächsten Moment näherte sich dir durch die Menge der Seefahrer ein vertrautes Set von Schritten."
  },
  AvgDialog_35535_Content_7 = {
    Text = "Caecus, du solltest kein weiches Herz haben."
  },
  AvgDialog_35536_Content_1 = {
    Text = "Mottenfängerfeuer"
  },
  AvgDialog_35536_Content_10 = {
    Text = "Der Klang des Windes... Ich erinnere mich, dass ein großes Loch in den Kraftwerksraum gepustet wurde."
  },
  AvgDialog_35536_Content_11 = {
    Text = "Der Sonanil war nach Norden gesegelt, und die Temperatur an der Meeresoberfläche war sehr niedrig. Ohne dass jemand Kohle in den Ofen nachlegte, könnte das Feuer durch den Seewind erlöschen."
  },
  AvgDialog_35536_Content_12 = {Text = "Puh..."},
  AvgDialog_35536_Content_13 = {
    Text = "Was ist los?"
  },
  AvgDialog_35536_Content_14 = {
    Text = "Es fühlt sich einfach... ein bisschen unrealistisch an."
  },
  AvgDialog_35536_Content_15 = {
    Text = "Hafenangriff, Treffen mit Murphy und dem Kapitän, Konfrontation mit Miryam, eine Explosion...\nWir haben die Schule kurz vor dem Abendessen verlassen, doch es fühlt sich an, als wären wir seit zwei Monaten auf See."
  },
  AvgDialog_35536_Content_16 = {
    Text = "Was für eine geschäftige Nacht. Wenn Doll wüsste, würde sie meine seltene Sorgfalt kalt loben."
  },
  AvgDialog_35536_Content_17 = {
    Text = "\"Gut gemacht, Hüter. Die Erfahrung von heute Abend wird ein bedeutendes Highlight in deinem Abschlussbericht sein.\""
  },
  AvgDialog_35536_Content_18 = {
    Text = "Du antwortest Ramona mit einem absichtlich lässigen Tonfall. Sie gibt ein paar undeutliche nasale Geräusche von sich und kämpft hart, um nicht in Gelächter auszubrechen."
  },
  AvgDialog_35536_Content_19 = {
    Text = "Du wirst Doll nicht heimlich informieren, oder?"
  },
  AvgDialog_35536_Content_2 = {
    Text = [[
Zeit bis zum Ausrichten: 
20 Minuten verbleibend]]
  },
  AvgDialog_35536_Content_20 = {
    Text = "Wenn ich gewollt hätte, hätte ich Doll bei unserem früheren Kontakt mein Herz ausgeschüttet."
  },
  AvgDialog_35536_Content_21 = {
    Text = "\"Mythag Hüter stellte sich selbstlos in Gefahr, erlitt schwere Verletzungen und fiel ins Bewusstsein.\""
  },
  AvgDialog_35536_Content_22 = {
    Text = "Pssst! Absolut nicht—"
  },
  AvgDialog_35536_Content_23 = {
    Text = "Aber hast du Doll kontaktiert? Funktioniert der Kommunikator jetzt?"
  },
  AvgDialog_35536_Content_24 = {
    Text = "Als der Bereich noch intakt war, wurde das Signal tatsächlich unterbrochen. Nachdem die Macht von Celeste schwächer wurde, wurde die Kommunikation zunächst durch die Entfernung behindert."
  },
  AvgDialog_35536_Content_25 = {
    Text = "Ramona durchsuchte ihre Tasche und zog einen defekten Kommunikator heraus. Das mit dem Emblem der Mythag-Universität gravierte Panel war entfernt worden und enthüllte verbrannte innere Zahnräder."
  },
  AvgDialog_35536_Content_26 = {
    Text = "Ich habe versucht, die Basisfrequenz des Kommunikators zu ändern, um Kontakt zur Schule herzustellen. Obwohl es kurz war, reichte es aus, um die Dinge klar zu erklären."
  },
  AvgDialog_35536_Content_27 = {
    Text = "Doll und ihr Team sind verantwortlich für die Vorbereitung der Trennungsoperation des \"Heiligen Fötus\", und Senior William ist bereits am Hafen angekommen, um zu helfen."
  },
  AvgDialog_35536_Content_28 = {
    Text = "Aber auf See... sind wir auf uns allein gestellt."
  },
  AvgDialog_35536_Content_29 = {
    Text = "Schütze Murphy, widerstehe Goliath und hilf dem Kapitän, zurück ans Land zu segeln... Glücklicherweise hilft uns Tulu, und Caecus scheint ebenfalls bereit zu sein, eine Hand zu reichen, sonst..."
  },
  AvgDialog_35536_Content_3 = {
    Text = "Du und Ramona kehrten zum Außengelände des Kraftwerks zurück.\nDas Wachstum der Auswüchse verschlechtert sich und breitet sich sichtbar entlang des Weges aus."
  },
  AvgDialog_35536_Content_30 = {
    Text = "Sonst, nur wir beiden und unsere Kraft... wären wir wahrscheinlich nicht so weit gekommen."
  },
  AvgDialog_35536_Content_31 = {
    Text = "Wir müssen die Geburt des \"Heiligen Fötus\" verhindern"
  },
  AvgDialog_35536_Content_32 = {
    Text = "Wenn das Ritual erlaubt ist, wer weiß, welche Art von Monster aus Murphys \"Heiligem Fötus\" schlüpfen wird"
  },
  AvgDialog_35536_Content_33 = {
    Text = "Das ist richtig... Für Murphy und die Welt wird die Geburt des \"Heiligen Fötus\" nur Unheil bringen."
  },
  AvgDialog_35536_Content_34 = {
    Text = "Außerdem ist es zum Kern der Katastrophen geworden. Wir können es uns nicht leisten, es zu ignorieren."
  },
  AvgDialog_35536_Content_35 = {
    Text = "Das ist etwas, das nur wir erreichen können."
  },
  AvgDialog_35536_Content_36 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35536_Content_37 = {
    Text = "Das ist richtig... Dies ist etwas, das nur wir erreichen können."
  },
  AvgDialog_35536_Content_38 = {
    Text = "Kopf hoch und weiter nach vorne."
  },
  AvgDialog_35536_Content_4 = {
    Text = "Ramona drückte ihr Ohr gegen die Tür und lauschte einen Moment. Nachdem sie bestätigt hatte, dass kein Geräusch drinnen war, nickte sie dir zu."
  },
  AvgDialog_35536_Content_5 = {Text = "Knacken—"},
  AvgDialog_35536_Content_6 = {
    Text = "Die Tür, die dir und Murphy einst freien Zugang ermöglicht hatte, steckte nun im Rahmen fest aufgrund des schnell wachsenden Koralls. Egal wie sehr du und Ramona es versuchten, sie rührte sich nicht."
  },
  AvgDialog_35536_Content_7 = {
    Text = "Es gibt eine weitere Tür zum Stromraum. Lass uns einen Umweg machen."
  },
  AvgDialog_35536_Content_8 = {
    Text = "Abgesehen vom Wind habe ich gerade nichts gehört, aber es ist besser, sicher als bedauernd zu sein."
  },
  AvgDialog_35536_Content_9 = {Text = "Gut."},
  AvgDialog_35537_Content_1 = {
    Text = "Lemurias \"Ruhm\""
  },
  AvgDialog_35537_Content_10 = {
    Text = "Die menschlichen Helfer der Göttlichen Mutter sind nicht der Rede wert; die echte Bedrohung ist dieser eine..."
  },
  AvgDialog_35537_Content_11 = {
    Text = "<Yellow:\"Eure Hoheit\"> war ihm auf der Zunge gelegen, aber Caecus holte tief Luft und schluckte die Worte herunter."
  },
  AvgDialog_35537_Content_12 = {
    Text = "Dieser gefälschte Golem von Mythag ist unser wahrer Feind... der wahre Gegner der Seefahrer."
  },
  AvgDialog_35537_Content_13 = {
    Text = "Überhaupt nicht schlecht. Es scheint, dass diese lächerlichen Formalitäten dich nicht länger binden können."
  },
  AvgDialog_35537_Content_14 = {
    Text = "Nach all dem werde ich mich persönlich um Ihre Verknüpfung kümmern"
  },
  AvgDialog_35537_Content_15 = {
    Text = "Du bist nur einen Schritt davon entfernt, an der Spitze zu stehen.\nEnttäusche mich nicht, Kind."
  },
  AvgDialog_35537_Content_16 = {
    Text = "Ja, danke für deine Förderung..."
  },
  AvgDialog_35537_Content_17 = {
    Text = "Er senkte gehorsam seinen Kopf, während Goliath durch den Kraftwerkraum tobte, der bereits von Ruinen ununterscheidbar war."
  },
  AvgDialog_35537_Content_18 = {
    Text = "Die riesige Klinge zieht über die verwüsteten Narben und teilt die Asche und den Staub nach der Explosion wie einen neu gemeißelten Fluss."
  },
  AvgDialog_35537_Content_19 = {
    Text = "Hast du nicht gesagt, dass es eine besondere Situation im Kraftraum gab, die nur ich lösen konnte?"
  },
  AvgDialog_35537_Content_2 = {
    Text = "Tsk, Pech gehabt."
  },
  AvgDialog_35537_Content_20 = {
    Text = "Ja, ja... ich habe es gefühlt, gefühlt... durch die Verknüpfung"
  },
  AvgDialog_35537_Content_21 = {
    Text = "Lady Miryam... Ja, ich habe Lady Miryam wahrgenommen."
  },
  AvgDialog_35537_Content_22 = {Text = "Ah—!"},
  AvgDialog_35537_Content_23 = {
    Text = "Der Riese gab Caecus einen heftigen Tritt in die Kniekehle, und der Schmerz durch die Knochenverschiebung zwang ihn, in den Trümmern auf die Knie zu sinken."
  },
  AvgDialog_35537_Content_24 = {
    Text = "Caecus ist schrecklich im Lügen und stolpert über seine Worte. Seine ungelenken Lügen können nicht einmal ihn selbst überzeugen, geschweige denn Goliath."
  },
  AvgDialog_35537_Content_25 = {
    Text = "Vergiss diese verrückte Frau! Hast du es immer noch nicht erkannt? Sie kümmert sich überhaupt nicht um euch Murlocs!"
  },
  AvgDialog_35537_Content_26 = {
    Text = "Sie verlangt nur nach diesem Gott—dem abscheulichen Gott, der sie und das Volk von Lemuria in prähistorischen Zeiten verlassen hat und spurlos verschwunden ist!"
  },
  AvgDialog_35537_Content_27 = {
    Text = "Du... wirst sterben."
  },
  AvgDialog_35537_Content_28 = {
    Text = "Seine Haare wurden von Goliath gepackt und nach oben gezogen, was ihn zwang, nach oben zu schauen und dem Blick des Riesen zu begegnen. Kalter Schweiß lief ihm in die Augen und brannte in seine empfindlichen Schleimhäute."
  },
  AvgDialog_35537_Content_29 = {
    Text = "Er wird sterben... Er wird für den Verrat an Lord Goliath sterben..."
  },
  AvgDialog_35537_Content_3 = {
    Text = "Seit Tausenden von Jahren gemieden, und jetzt will der kleine Zwerg Unruhe stiften."
  },
  AvgDialog_35537_Content_30 = {
    Text = "Im selben Moment wurde Caecus von Goliath wie ein gebrochener Mast zu Boden geschmettert."
  },
  AvgDialog_35537_Content_31 = {
    Text = "Verschwinde, um diese umherziehenden Idioten einzusammeln."
  },
  AvgDialog_35537_Content_32 = {
    Text = [[
Caecus floh aus dem Kraftwerk. 
Nachdem er sichergestellt hatte, dass seine Gestalt nicht mehr sichtbar war, nahm Goliath eine Waffe an der brennenden Kraftfurnace.]]
  },
  AvgDialog_35537_Content_33 = {
    Text = "...Puh, das ist der \"Göttliche König\"."
  },
  AvgDialog_35537_Content_34 = {
    Text = "Ein einfacher Schnitt hinterließ eine klaffende Wunde am unteren Rücken des Giganten. Seltsam gefärbtes Blut trat leise heraus und sickerte in die Ritzen der dunklen Haut."
  },
  AvgDialog_35537_Content_35 = {
    Text = "Du hältst wirklich nichts zurück... Heh."
  },
  AvgDialog_35537_Content_36 = {
    Text = "Aber das spielt keine Rolle... Mit dem göttlichen Embryo als meinem Puppenspieler werden diese Narren, die in Elworth geblieben sind, vor mir als ihrem König niederknien."
  },
  AvgDialog_35537_Content_37 = {
    Text = "Eine einmalige Gelegenheit. Niemand kann sie mir nehmen."
  },
  AvgDialog_35537_Content_38 = {
    Text = "Goliath zog seine Waffe aus dem Feuer und drückte ohne Zögern die riesige Klinge gegen die Wunde."
  },
  AvgDialog_35537_Content_39 = {
    Text = "Unter der intensiven Hitze atrophieren die Muskeln schnell, begleitet vom Geruch brennenden Metalls. Die Wunde sondern keine blau-schwarze Flüssigkeit mehr ab."
  },
  AvgDialog_35537_Content_4 = {
    Text = "Der junge Seefahrer folgte dem Riesen dicht auf den Fersen, Schritt für Schritt, in Stille."
  },
  AvgDialog_35537_Content_40 = {
    Text = "Meister Goliath, die meisten der Seefahrer auf dem Schiff sind hier."
  },
  AvgDialog_35537_Content_41 = {
    Text = "Nachdem er eine Weile weg war, kehrte Caecus sichtbar müde zurück, aber Goliath kümmerte sich nicht darum."
  },
  AvgDialog_35537_Content_42 = {
    Text = "Sind nur noch so viele Menschen übrig?"
  },
  AvgDialog_35537_Content_43 = {
    Text = "Ja... und aufgrund der Ausbreitung von <Yellow:Dissolution> können viele jetzt nicht kämpfen."
  },
  AvgDialog_35537_Content_44 = {Text = "Genug."},
  AvgDialog_35537_Content_45 = {
    Text = "Goo... Meister Goliath..."
  },
  AvgDialog_35537_Content_46 = {
    Text = "Hochpriester... Ugh... Rückkehr... @2..."
  },
  AvgDialog_35537_Content_47 = {
    Text = "Worte, die den Seefahrern über die Lippen kamen, ließen Goliath die Stirn runzeln. Sie waren unkenntlich, unverständlich und wiesen ihn zurück—wiesen diejenigen zurück, denen das göttliche Blut fehlte."
  },
  AvgDialog_35537_Content_48 = {
    Text = "Genug...\nÖffne deine Augen und sieh die Realität!"
  },
  AvgDialog_35537_Content_49 = {
    Text = "Der Hohe Priester ist tot, aber die Göttliche Mutter lebt noch!\nWir haben noch die Chance, das Ritual fortzusetzen. Hol die Göttliche Mutter von den Außenseitern zurück und begrüße den Göttlichen Fötus!"
  },
  AvgDialog_35537_Content_5 = {
    Text = "Kind, was denkst du?"
  },
  AvgDialog_35537_Content_50 = {
    Text = "Diese große Klinge wird ihre Mission nicht misslingen... Ich werde das schärfste Schwert des neuen Gottes werden!"
  },
  AvgDialog_35537_Content_51 = {
    Text = "Goo... Goo... @2 Rückkehr..."
  },
  AvgDialog_35537_Content_52 = {
    Text = "Er wird zurückkehren... Er wird zurückkehren!"
  },
  AvgDialog_35537_Content_54 = {
    Text = "Die unzusammenhängenden Gebete verschmolzen schließlich zu einem chantartigen Fluss, was Goliath äußerst verärgerte."
  },
  AvgDialog_35537_Content_55 = {
    Text = "In den glühenden Gebeten des Seefahrers drangen amorphe Energieströme durch den Riss im Rumpf, die sich um Goliath schlangen."
  },
  AvgDialog_35537_Content_56 = {
    Text = "Der vertraute Schmerz und die Enge ließen Goliath seinen Hals umklammern, während die Venen unter seinen Schläfen anschwollen, seine Augen weit geöffnet und blutunterlaufen."
  },
  AvgDialog_35537_Content_57 = {
    Text = "Seit dem Tag, an dem er einen Vertrag mit der \"Seehexe\" unterschrieb, die Fesseln, die ihn banden—die er einst dachte, vollständig nach der Explosion entkommen zu sein—"
  },
  AvgDialog_35537_Content_58 = {
    Text = "Bestrafe ihn erneut für seine Gotteslästerung gegenüber den \"Göttern\"."
  },
  AvgDialog_35537_Content_6 = {
    Text = "Ich... Ich?"
  },
  AvgDialog_35537_Content_60 = {
    Text = "Als der Riese es bemerkte, hatte sich der Nebel bereits zu dickem, greifbarem Schlamm kondensiert und verwandelte sich in einen fremden Dolch, der gegen die Wunde an seinem Hals drückte."
  },
  AvgDialog_35537_Content_61 = {
    Text = "Perishit..."
  },
  AvgDialog_35537_Content_62 = {Text = "Du..."},
  AvgDialog_35537_Content_63 = {
    Text = "Die einzige Person in der Welt, die seine frühere Identität kennt, ist wahrscheinlich dieser eine—"
  },
  AvgDialog_35537_Content_64 = {
    Text = "Lady Miryam?!"
  },
  AvgDialog_35537_Content_65 = {Text = "Miryam..."},
  AvgDialog_35537_Content_66 = {
    Text = "Nachdem einen kurzen Moment der Besinnung und Stille folgte, brachen die Seefahrer in freudige Jubelrufe aus."
  },
  AvgDialog_35537_Content_67 = {
    Text = "Hoher Priester! <Big:Hoher Priester!> <BigShake:Hoher Priester!>"
  },
  AvgDialog_35537_Content_68 = {
    Text = "Ha... Ha... Ich bin so froh, dass es dir gut geht."
  },
  AvgDialog_35537_Content_69 = {
    Text = "Goliath versuchte, den Dolch wegzuschieben, schnitt sich aber versehentlich an seiner plötzlich scharfen Spitze."
  },
  AvgDialog_35537_Content_7 = {
    Text = "Caecus war vollkommen unvorbereitet auf die Frage und war startled."
  },
  AvgDialog_35537_Content_70 = {
    Text = "Ich weiß, was du denkst, Perishit."
  },
  AvgDialog_35537_Content_71 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35537_Content_72 = {
    Text = "Die Verräter eliminieren, die Hindernisse für den Abstieg beseitigen... Die Eindringlinge entfernen und die Göttliche Mutter zurückgewinnen."
  },
  AvgDialog_35537_Content_73 = {
    Text = "So kann ich dir einen würdigen Tod gewähren."
  },
  AvgDialog_35537_Content_74 = {
    Text = [[
Zeit bis zum Ausrichten:
<Red:30> Minuten verbleibend]]
  },
  AvgDialog_35537_Content_8 = {
    Text = "Gibt es eine Kommunikationsbarriere zwischen uns? Oder ist hier eine dritte Person mit einem Gehirn?"
  },
  AvgDialog_35537_Content_9 = {
    Text = "J-Ja... Es tut mir leid, Herr Goliath."
  },
  AvgDialog_35538_Content_1 = {
    Text = "Ist unser Kommunikator teuer?"
  },
  AvgDialog_35538_Content_2 = {
    Text = "Der Silberkern, der im Inneren verwendet wird, kann auf dem Schwarzmarkt gegen eine Wohnung im Zentrum von Lentini eingetauscht werden"
  },
  AvgDialog_35538_Content_3 = {
    Text = "Was ist los? Ich habe auf einmal daran gedacht, das zu fragen."
  },
  AvgDialog_35538_Content_4 = {
    Text = "Es ist... nichts..."
  },
  AvgDialog_35820_Content_1 = {
    Text = "Wie geht es Caecus?"
  },
  AvgDialog_35820_Content_2 = {
    Text = "Keine Reaktion, und es scheint nicht so, als würde es uns angreifen."
  },
  AvgDialog_35820_Content_3 = {
    Text = "Konzentriere dich zuerst auf den Seefahrer, behalte aber Caecus' Zustand im Auge."
  },
  AvgDialog_35821_Content_1 = {
    Text = "Der falsche Gott bricht zusammen und zerfällt unter den Schreien, graublauer Staub füllt den Himmel und fällt langsam herab."
  },
  AvgDialog_35821_Content_10 = {
    Text = "Der Hafen von Brillport, wo der Hüter und ich an Bord des Schiffes gingen. Wir sind... zurück?"
  },
  AvgDialog_35821_Content_11 = {
    Text = "Wir sind zurück."
  },
  AvgDialog_35821_Content_12 = {
    Text = "Hüter, Tulu, Captain Elton, Celeste, Caecus... und Murphy."
  },
  AvgDialog_35821_Content_13 = {
    Text = "Und da ist William Draper."
  },
  AvgDialog_35821_Content_14 = {
    Text = "Senior Wei... William"
  },
  AvgDialog_35821_Content_15 = {
    Text = "Als Sie die Schule verließen, war es nur ein Zweier-Team. Jetzt scheint das Auto, das ich vorbereitet habe, nicht für alle Platz zu haben."
  },
  AvgDialog_35821_Content_16 = {
    Text = "Williams scharfer Blick schweifte über den Hafen. Schließlich ließ er einen tiefen Seufzer hören und lächelte."
  },
  AvgDialog_35821_Content_17 = {
    Text = "Willkommen zurück, Hüter."
  },
  AvgDialog_35821_Content_18 = {
    Text = "William trat näher. Du versuch testest etwas zu sagen, aber dein Blick verschwomm für einen Moment unkontrollierbar."
  },
  AvgDialog_35821_Content_19 = {
    Text = "Alle Müdigkeit, Verwirrung und Schmerz verschwinden ins Nichts. Das Bild deines Begleiters, der ängstlich auf dich zuläuft, wird zum letzten Bild in deinem Gedächtnis, gefolgt von einer Welle dunkler Ruhe..."
  },
  AvgDialog_35821_Content_2 = {
    Text = "Sei vorsichtig, atme diesen Staub nicht ein."
  },
  AvgDialog_35821_Content_3 = {
    Text = "Bevor die Worte zu Ende waren, begann das Deck unter ihren Füßen heftig zu beben. Das Schiff gab ein scharfes Knarren von sich, wie der letzte Hilferuf von jemandem, der ertrinkt."
  },
  AvgDialog_35821_Content_4 = {
    Text = "Oh nein?! Geht das Schiff... unter?!"
  },
  AvgDialog_35821_Content_5 = {
    Text = "Das Schiff schwankte chaotisch, und sich am Geländer festzuhalten war zwecklos. Die Welt brach um dich zusammen, und der herabfallende Staub verdeckte vollständig deine Sicht."
  },
  AvgDialog_35821_Content_6 = {
    Text = "Kann den Mond nicht mehr sehen, kann das Meer nicht mehr sehen, und es ist schwierig, meine Gefährten auszumachen."
  },
  AvgDialog_35821_Content_7 = {
    Text = "Gerade bevor der gefälschte Staub alles verschlingt, wird die Welt außergewöhnlich klar."
  },
  AvgDialog_35821_Content_8 = {
    Text = "Das unaufhörliche Geräusch der Wellen ist verklungen, und unter dem klaren Nachthimmel fühlt sich das Mondlicht besonders sanft und friedlich an."
  },
  AvgDialog_35821_Content_9 = {
    Text = "Ist das... der Hafen?"
  },
  AvgDialog_35822_Content_1 = {
    Text = "Verzerrte Sterne"
  },
  AvgDialog_35822_Content_10 = {
    Text = "Die Phantomschlange hob plötzlich ihren Kopf hoch und hob Murphy ins Mondlicht."
  },
  AvgDialog_35822_Content_11 = {
    Text = "Paare von winzigen, zarten schwarzen Händen kommen aus der Brust des Mädchens hervor, winden und weben sich zusammen, Schicht für Schicht, und hüllen ihren Körper in einen massiven schwarzen Kokon."
  },
  AvgDialog_35822_Content_12 = {
    Text = "Mit einem gedämpften Knurren nutzen Hände und schwarze Fäden die riesige Schlange als Rahmen und umwickeln den Kokon eng um ihren massiven Körper."
  },
  AvgDialog_35822_Content_13 = {
    Text = "Die Hülle des Kokons wurde durch die Ausdehnung transparent, unzählige Hände verschlangen sich zu einem Thron und hoben ein bleiches Herz empor"
  },
  AvgDialog_35822_Content_14 = {
    Text = "Ph@1...@1nafh @3..."
  },
  AvgDialog_35822_Content_15 = {
    Text = "Die Frau kniete am Bug und verbeugte sich vor dem extrem verzerrten Wesen."
  },
  AvgDialog_35822_Content_16 = {
    Text = "Der Wind trägt ferne, unbekannte Flüstern davon, wie eine Schlange, die im Schatten zischt, und lässt dir das Haar zu Berge stehen."
  },
  AvgDialog_35822_Content_17 = {
    Text = "Wie... Wie ist Murphy im Besitz von Miryam?"
  },
  AvgDialog_35822_Content_18 = {
    Text = "Ramona und Caecus unterstützten dich von beiden Seiten. Ihr drei standet in einer geraden Linie und blicktet auf das gigantische Monster, das das Mondlicht blockierte."
  },
  AvgDialog_35822_Content_19 = {
    Text = "Es ist zu spät... Alles ist über jede Rettung hinaus."
  },
  AvgDialog_35822_Content_2 = {
    Text = "Du folgst Miryams Schwimmrichtung und machst dich hastig auf den Weg zum Hauptdeck."
  },
  AvgDialog_35822_Content_20 = {
    Text = "Dies ist das, worüber ich dich warnen wollte... Lord Miryam befahl mir, den letzten Dampfkessel zu löschen, um dich in die Falle zu locken, die wir gestellt haben, und euch alle zu fangen."
  },
  AvgDialog_35822_Content_21 = {
    Text = "Obwohl Mutter Gott... obwohl Lady Murphy nicht an deiner Seite gehandelt hat, gab das Lord Goliath die Gelegenheit, sie zu ergreifen."
  },
  AvgDialog_35822_Content_22 = {
    Text = "Die Verknüpfung mit Caecus fühlt sich an wie ein Adrenalinschub für den Geist, der allmählich den Verstand durch den Schmerz wieder zusammenfügt."
  },
  AvgDialog_35822_Content_23 = {
    Text = "Das geschreiartige Pfeifen und Flüstern in deinem Geist verstummte. Du blinzelst und fühlst zum ersten Mal seit der Explosion Klarheit in der Geisterwelt —"
  },
  AvgDialog_35822_Content_24 = {
    Text = "Die Bildung des riesigen Kokons brachte schwere Verschmutzung in den umliegenden Bereich, was es schwer machte, Murphy in der trüben Flüssigkeit darin zu lokalisieren. Aber zweifellos sahst du einen Funken Leben."
  },
  AvgDialog_35822_Content_25 = {
    Text = "Nein, es ist noch Zeit."
  },
  AvgDialog_35822_Content_26 = {
    Text = "Sie lebt noch, also haben wir noch eine Chance. Jedenfalls... versuche zuerst, näher an sie heranzukommen."
  },
  AvgDialog_35822_Content_27 = {
    Text = "Aber dein Körper... Nein, lass mich allein gehen.\nCaecus, könntest du für eine Weile ein Auge auf den Hüter haben?"
  },
  AvgDialog_35822_Content_28 = {
    Text = "Ramona hat dir so fest selten widersprochen. Sie entfernte deine Hand von ihrem Arm und übergab dich feierlich an Caecus."
  },
  AvgDialog_35822_Content_29 = {
    Text = "Alright... Ich werde mein Bestes geben."
  },
  AvgDialog_35822_Content_3 = {
    Text = "In dem Moment, als der letzte Schritt blieb, rammte ein unbekanntes Ungeheuer in den Frachter, wodurch er kippen und vom Kurs abkommen ließ."
  },
  AvgDialog_35822_Content_30 = {
    Text = "Warte, ich habe nie gesagt, dass du alleine gehen musst!"
  },
  AvgDialog_35822_Content_31 = {
    Text = "Caecus hielt dich mit einer Hand fest und stoppte mühelos deinen Kampf."
  },
  AvgDialog_35822_Content_32 = {
    Text = "Aber Ramona hatte erst ein paar Schritte gemacht, als Caecus's Ohrflosse sensibel zuckte."
  },
  AvgDialog_35822_Content_33 = {
    Text = "Im nächsten Moment ließ er seine Waffe fallen, packte dich und rollte von dem Ort weg, an dem du gerade gestanden hattest. Eine riesige Klinge flog aus der Ferne heran, zerschmetterte das Deck und schleuderte Splitter überall hin."
  },
  AvgDialog_35822_Content_34 = {
    Text = "Hüter, Caecus!"
  },
  AvgDialog_35822_Content_35 = {
    Text = "Caecus schüttelte den Kopf und deutete an, dass es ihm gut ging. Nachdem er überprüft hatte, dass du dir keine neuen Verletzungen zugezogen hattest, hob er seine Waffe auf und stellte sich schützend vor dich."
  },
  AvgDialog_35822_Content_36 = {
    Text = "Es ist dann, dass du bemerkst, dass die riesige Klinge seinen Rückenflossenhaarkamm gestreift hat. Das Gewebe, einst so zäh wie das einer Schwertfischflosse, ist nun gnadenlos zerrissen und hängt schief auf seinem Rücken."
  },
  AvgDialog_35822_Content_37 = {
    Text = "Mit einem Gesicht, das vor Schmerz verzogen war, richtete Caecus dennoch seinen stolzen Rücken auf und stellte sich dem höhnischen Riesen in der Ferne."
  },
  AvgDialog_35822_Content_38 = {
    Text = "Lord Goliath, bitte geh nicht weiter."
  },
  AvgDialog_35822_Content_39 = {
    Text = "Er setzte all seine Kraft ein, um dich in Richtung Ramona zu drücken.\nMit seinem dünnen Körper stand er zwischen dir und Goliath."
  },
  AvgDialog_35822_Content_4 = {Text = "Vorsicht!"},
  AvgDialog_35822_Content_40 = {
    Text = "Vertraue Caecus! Lass ihn Goliath aufhalten, während wir uns durch den Frachtbereich schleichen, um uns diesem Ding zu nähern!"
  },
  AvgDialog_35822_Content_5 = {
    Text = "Caecus und Ramona haben dich von beiden Seiten unterstützt und haben schließlich gemeinsam zum Stillstand gekommen."
  },
  AvgDialog_35822_Content_6 = {
    Text = "Im nächsten Moment, begleitet vom Brüllen der Wellen, türmte sich ein riesiger Schatten über dir auf."
  },
  AvgDialog_35822_Content_7 = {
    Text = "Sieh! Da ist es!"
  },
  AvgDialog_35822_Content_9 = {
    Text = "Das ist... Das ist Murphy!"
  },
  AvgDialog_35823_Content_1 = {
    Text = "Hast du gerade Mental Trace verwendet? Dein Körper"
  },
  AvgDialog_35823_Content_2 = {
    Text = "Ich bin in Ordnung... Ugh!"
  },
  AvgDialog_35823_Content_3 = {
    Text = "Als die schmerzlindernde Wirkung des Adrenalins plötzlich nachlässt, werden deine Beine schlaff. Wenn Ramona dich nicht gestützt hätte, würdest du wahrscheinlich jetzt auf dem Boden liegen."
  },
  AvgDialog_35823_Content_4 = {
    Text = "Versuche nicht wieder, Geisterkraft zu verwenden, bis du eine gründliche Untersuchung hattest."
  },
  AvgDialog_35824_Content_1 = {
    Text = "Pfad abseits"
  },
  AvgDialog_35824_Content_10 = {
    Text = "Lady Miryam... Ich... habe nicht..."
  },
  AvgDialog_35824_Content_11 = {
    Text = "Er versuchte, diesem Leid zu entkommen, aber je mehr er kämpfte, desto stärker wurde die uralte Macht, die seine Hilflosigkeit und Gebrechlichkeit verhöhnte."
  },
  AvgDialog_35824_Content_12 = {
    Text = "Sein peripheres Sehen fiel schließlich auf dich und Ramona, ein flüchtiger Blick der Verzweiflung blitzte in seinen Augen auf."
  },
  AvgDialog_35824_Content_13 = {
    Text = "Genug! Miryam!"
  },
  AvgDialog_35824_Content_14 = {
    Text = "Ramona verstand und zog ihr Schwert, um Miryam zu blockieren. Die Klinge war auf den schlanken Hals der Frau gerichtet, während dunkles Blut entlang der Metalltextur hinab floss."
  },
  AvgDialog_35824_Content_15 = {
    Text = "Aber der Schmerz auf Caecus' Gesicht lässt nicht im Geringsten nach. Er kniet in einem jämmerlichen Zustand auf dem Boden und kann seinen Kopf nicht heben."
  },
  AvgDialog_35824_Content_16 = {
    Text = "Wir werden Murphy beschützen und das Ritual stoppen. Solange wir hier sind, ist Ihr „großes Abenteuer“ dazu verdammt, zu scheitern."
  },
  AvgDialog_35824_Content_17 = {
    Text = "Quäle den Erwacher, der mit deinem Geist verbunden ist... Wir werden es dir nicht leicht machen."
  },
  AvgDialog_35824_Content_18 = {
    Text = "...So ist das?"
  },
  AvgDialog_35824_Content_19 = {
    Text = "Miryam sah nach oben und offenbarte ein rätselhaftes Lächeln. Ihre Augen waren vom Wahnsinn getrübt, gefüllt mit einer unbeschreiblichen, kalten Angst."
  },
  AvgDialog_35824_Content_2 = {
    Text = "Miryam steht auf den Ruinen, ihre Füße werden von gezackten Metallstücken geschnitten, dunkles Blut fließt."
  },
  AvgDialog_35824_Content_20 = {
    Text = "Diejenigen, die mit dem falschen König wandeln, die diejenigen, die die Macht meines Meisters entweihen... Deine Gefühle waren für diese flüchtige Existenz nie von Belang."
  },
  AvgDialog_35824_Content_21 = {
    Text = "Ihr Ton erhob sich und strahlte einen eiskalten Wahnsinn aus, der bereit schien, alles zu verschlingen."
  },
  AvgDialog_35824_Content_22 = {
    Text = "Miryam zog abrupt ihre Hand zurück, und Caecus fiel wie eine verworfene Puppe zusammen."
  },
  AvgDialog_35824_Content_23 = {
    Text = "Er kniete nieder, lag auf dem Boden, die Halsmuskeln zuckten, und feierte das Überleben seines Körpers mit heftigem Husten."
  },
  AvgDialog_35824_Content_24 = {
    Text = "Steh auf und kämpfe weiter, Caecus."
  },
  AvgDialog_35824_Content_25 = {
    Text = "Die eifrigen Seefahrer umringten sie und umzingelten dich."
  },
  AvgDialog_35824_Content_26 = {
    Text = "Dies ist deine letzte Chance. Steh auf und räum diese Leute aus dem Weg... räum die Feinde von Gottes Reich aus dem Weg!"
  },
  AvgDialog_35824_Content_3 = {
    Text = "Wo auch immer sie stand, folgte eine eiskalte Blutspur, die einen frostigen Schrecken ausstrahlte."
  },
  AvgDialog_35824_Content_4 = {Text = "Miryam..."},
  AvgDialog_35824_Content_5 = {
    Text = "Miryam schaut dich an, ihre Haltung hochmütig, ohne Anzeichen von Niederlage."
  },
  AvgDialog_35824_Content_6 = {
    Text = "Wenn nicht die ständigen Schmerzen, die von ihrem Körper signalisieren, würde die Szene, in der sie den Verstand verliert und in Wahnsinn verwandelt, wie deine Vorstellung erscheinen."
  },
  AvgDialog_35824_Content_7 = {
    Text = "Caecus, du solltest kein weiches Herz haben."
  },
  AvgDialog_35824_Content_8 = {
    Text = "Sie ignorierte dich und Ramona vollständig und schritt Schritt für Schritt auf Caecus zu.\nAls sie sich näherte, begann der schwarze Ring um Caecus' Hals erneut zu flackern."
  },
  AvgDialog_35824_Content_9 = {
    Text = "Der schwarze Ring, wie eine dunkle Ranke, zog seinen unheilvollen Griff mit jedem Schlag von Caecus' Herz enger, raubte ihm die Lebenskraft wie Schatten, die bei Dämmerung über die Straßen kriechen."
  },
  AvgDialog_35825_Content_1 = {
    Text = "So lästig. Ich hoffe, ich war nicht so nervig wie Er, als ich ein Kind war."
  },
  AvgDialog_35825_Content_10 = {
    Text = "Eine blassrosa Barriere zerbricht mit einem Knacken, begleitet von dem Geräusch leichter Schritte, die näher kommen. Das Geräusch durchdringt Ihre gedämpften Trommelfelle mit beispielloser Klarheit."
  },
  AvgDialog_35825_Content_11 = {
    Text = "Um das Weinerchen zu bestrafen, wie könnten wir die große „Mutter“ vergessen?"
  },
  AvgDialog_35825_Content_12 = {
    Text = "Murphy! Deine <Yellow:Erweckerformung>... Es hat funktioniert!"
  },
  AvgDialog_35825_Content_13 = {
    Text = "Hmph... Ich werde mich später um dich kümmern. Jetzt kläre ich die Sache mit diesem Kerl!"
  },
  AvgDialog_35825_Content_2 = {
    Text = "Ein Hüter, der überall einschlafen kann, muss ein außergewöhnlich bravartiges Kind gewesen sein."
  },
  AvgDialog_35825_Content_3 = {
    Text = "Ramona antwortete scherzhaft. Die Hand, die ihr Schwert schwang, zitterte unkontrollierbar und erreichte eindeutig ihr physisches Limit."
  },
  AvgDialog_35825_Content_4 = {
    Text = "Aber als der Tentakel des \"Heiligen Säuglings\" erneut niederschwang, stürmte Ramona entschlossen vorwärts und lenkte den schwingenden Tentakel ab."
  },
  AvgDialog_35825_Content_5 = {
    Text = "Die immense Kraft traf ihre rechte Hand und hätte sie beinahe die Waffe aus dem Griff gerissen. Aber sie atmete einfach tief durch und entzog den Rapier erneut festen Halt."
  },
  AvgDialog_35825_Content_6 = {
    Text = "Stelle sicher, dass du mit Ihm umgehst, bevor du das Ufer erreichst."
  },
  AvgDialog_35825_Content_7 = {
    Text = "In der Ecke deiner Sicht breitet sich eine ungewöhnliche Kälte aus. Als du merkst, dass es ein weiterer Tentakel ist, ist er bereits hinter dir hindurchgeschlüpft—"
  },
  AvgDialog_35825_Content_9 = {
    Text = "Diese Person hat mich so lange gequält... Hast du vor, ihn heimlich loszuwerden? Ich werde das auf keinen Fall erlauben!"
  },
  AvgDialog_35826_Content_1 = {
    Text = "Internalisierte Flamme"
  },
  AvgDialog_35826_Content_10 = {
    Text = "Murphy, wie geht es deinem Körper?"
  },
  AvgDialog_35826_Content_11 = {
    Text = "Murphy saß in der Ecke des Cockpits, die Spitze ihres Pferdeschwanzes lag lässig auf ihrer Schulter. Sie sah blass und zerzaust aus, weit entfernt von ihrem einst arroganten und verwöhnten Ich."
  },
  AvgDialog_35826_Content_12 = {
    Text = "Murphy, Murphy?"
  },
  AvgDialog_35826_Content_13 = {
    Text = "Ihre Augen sind hohl und verwirrt, sie starrt auf ihre Brust."
  },
  AvgDialog_35826_Content_14 = {
    Text = "Sanft strich sie über ihre Brust, ihre Fingerspitzen zogen kleine Kreise über ihr Herz. Darunter lag ihr zerbrechliches menschliches Herz, eine tickende Zeitbombe, die ihr Leben verbrauchte."
  },
  AvgDialog_35826_Content_15 = {
    Text = "Jeder Herzschlag ist voller Schmerz, der ihren Körper quält. Aber was wirklich furchterregend ist, ist der Horror und die Unruhe, die an ihrem Geist nagen."
  },
  AvgDialog_35826_Content_16 = {
    Text = "Aktiver werden... Er bewegt sich ständig."
  },
  AvgDialog_35826_Content_17 = {
    Text = "Gedanken sinken allmählich in den Nebel ihres Herzens. Sie schließt die Augen und versucht, ein stilles Gespräch mit dem Parasiten zu führen, der sie verzehrt."
  },
  AvgDialog_35826_Content_18 = {
    Text = "Aber bevor Murphy auf eine Antwort seines Herzens warten konnte, wurde seine Aufmerksamkeit von dem Geräusch von etwas Schwerem, das vor der Cockpittür auf den Boden fiel, abgelenkt."
  },
  AvgDialog_35826_Content_19 = {
    Text = "Nachdem es seine Tentakeln erneut hochgehoben hatte, durchbohrte ein scharfer Schmerz seine Seele. Die plötzliche Erstickung zerschlug die gesammelte Kraft von Tulu, und die Tentakeln krachten auf das Deck."
  },
  AvgDialog_35826_Content_2 = {
    Text = "Diese beiden Schüler sind schon so lange weg..."
  },
  AvgDialog_35826_Content_20 = {
    Text = "Lemurias geheime Strafe..."
  },
  AvgDialog_35826_Content_21 = {
    Text = "Tulu? Was ist los?"
  },
  AvgDialog_35826_Content_22 = {
    Text = "Komm nicht raus!"
  },
  AvgDialog_35826_Content_23 = {
    Text = "Meine Eingeweide fühlten sich an, als würden sie von dieser Kraft zerrissen. Tulu keuchte, als er einen weiteren Seefahrer niederwarf, und konnte dann nicht mehr stehen."
  },
  AvgDialog_35826_Content_24 = {
    Text = "Es ist der Schmerz, der durch die Verknüpfung übertragen wird... Der Hüter hat Probleme."
  },
  AvgDialog_35826_Content_25 = {
    Text = "Mehr Seefahrer strömten auf die Deckplattform außerhalb der Hütte, der Geruch von Algen und verrottendem Plankton umhüllte sofort alle."
  },
  AvgDialog_35826_Content_26 = {Text = "Goliath..."},
  AvgDialog_35826_Content_27 = {
    Text = "Oh... Ich bin mir nicht sicher, ob es daran liegt, dass diese Frau die Menschen zu gut versteht oder ob ihr alle einfach zu naiv seid."
  },
  AvgDialog_35826_Content_28 = {
    Text = "Ich wollte es einfach nur versuchen, aber ich habe nicht erwartet, dass du dich tatsächlich so teilst, wie es die Frau geplant hat – selbst wenn ich wusste, dass die Seefahrer dich immer noch jagen."
  },
  AvgDialog_35826_Content_29 = {
    Text = "Diese Frau... Könnte Miryam wirklich noch leben?!"
  },
  AvgDialog_35826_Content_3 = {
    Text = "Elton drehte das Steuer ein paar Mal vergeblich, wie erwartet gab es kein Steuerungsfeedback."
  },
  AvgDialog_35826_Content_30 = {
    Text = "Goliath spuckte Blut, sein Ton abfällig und spöttisch - voller Selbstverachtung."
  },
  AvgDialog_35826_Content_31 = {
    Text = "Als ein <Yellow:\"Golem\"> sterben wir nicht so leicht, aber..."
  },
  AvgDialog_35826_Content_32 = {
    Text = "Goliath hockte sich vor Tulu. Selbst auf einem Knie ragte er über Tulu hinaus.\nEr sah auf Tulu hinab und beobachtete, wie kalter Schweiß in Tulus hellorange Augen tropfte."
  },
  AvgDialog_35826_Content_33 = {
    Text = "Aber selbst jemand so erhaben wie du ist letztendlich nur ein fragiles Wesen, das durch wackelige Verbindungen des Verstandes zusammengehalten wird."
  },
  AvgDialog_35826_Content_34 = {
    Text = "Was auch immer Miryam deinem Hüter angetan hat... es scheint, es hat dich beeinflusst.\nNun, das kommt mir zugute."
  },
  AvgDialog_35826_Content_35 = {
    Text = "Goliath konzentrierte sich nicht mehr auf Tulu; er ging an Tulu vorbei, in Richtung der Innenseite der Kabine."
  },
  AvgDialog_35826_Content_36 = {
    Text = "Elton trat vor, um Murphy zu schützen, aber Goliath schenkte ihm nicht einmal einen Blick."
  },
  AvgDialog_35826_Content_37 = {
    Text = "Was wirst du benutzen, um mich aufzuhalten? Dieses halbtransparente Mädchen?"
  },
  AvgDialog_35826_Content_38 = {
    Text = "Elton warf instinctiv einen Blick auf Celeste, auf der Suche nach Ermutigung von dem normalerweise stillen Erwecker."
  },
  AvgDialog_35826_Content_39 = {
    Text = "Aber er erhielt keine übliche Antwort. Selbst nachdem er die Medizin von Caecus genommen hatte, blieb Celestes Anwesenheit precär."
  },
  AvgDialog_35826_Content_4 = {
    Text = "Ich hoffe, dass wir nicht in Schwierigkeiten geraten..."
  },
  AvgDialog_35826_Content_40 = {
    Text = "Elton zögerte."
  },
  AvgDialog_35826_Content_41 = {
    Text = "Ich werde mit dir gehen. Mach ihnen keine Probleme."
  },
  AvgDialog_35826_Content_42 = {Text = "Murphy?!"},
  AvgDialog_35826_Content_43 = {
    Text = "Tulu war schockiert, als er das hörte. Er kämpfte darum, sich wieder aufzurichten, aber der unerträgliche Schmerz von der Verknüpfung zerbrach seinen Fokus und verstreute seine Rationalität an die Ränder seiner Gliedmaßen"
  },
  AvgDialog_35826_Content_44 = {
    Text = "Es ist alles in Ordnung... Mach nicht weiter wegen mir..."
  },
  AvgDialog_35826_Content_45 = {
    Text = "Oh? Ist die flüchtende Heilige endlich zu Sinnen gekommen?\nUnterhalte keine leichtsinnigen Gedanken, denn ein Fehltritt könnte alle mit dir hinunterziehen."
  },
  AvgDialog_35826_Content_46 = {
    Text = "Ich weiß... was zu tun ist..."
  },
  AvgDialog_35826_Content_47 = {
    Text = "Murphy machte zwei Schritte nach vorne, stand im Mondlicht und sah zurück auf die, um die sie sich sorgte, und auf die, die sich um sie sorgten. Ihre Gestalt wirkte einsam und verschwommen."
  },
  AvgDialog_35826_Content_48 = {
    Text = "Egal ob es ein Ritual oder etwas anderes ist... dieses Mal weiß ich, was zu tun ist."
  },
  AvgDialog_35826_Content_5 = {
    Text = "Das Meer schwoll unter dem blassen Mondlicht, das Schiff schwankte in den Wellen, und das Deck knarrte mit der Bewegung des Schiffs."
  },
  AvgDialog_35826_Content_6 = {
    Text = "Tulu, wie eine unbewegliche Gottheit, steht er vor der Tür und blockiert die Seefahrer, die niemals müde zu sein scheinen."
  },
  AvgDialog_35826_Content_7 = {
    Text = "Ich weiß, was du denkst. Der Verbindungsstatus zwischen mir und dem Hüter ist noch intakt."
  },
  AvgDialog_35826_Content_8 = {
    Text = "Als er sprach, warf er mit seinen Tentakeln geschickt einen weiteren Feind ins Meer."
  },
  AvgDialog_35826_Content_9 = {
    Text = "Hoffentlich sind {Male=er,Female=sie} sicher"
  },
  AvgDialog_35827_Content_1 = {
    Text = "\"Seefahrer\" trägt vom Gott gegebenes Blut, den Schlüssel, um unserem Meister durch unzählige Katastrophen zu helfen...\nDie Sterne stehen richtig; die Geburt unseres Meisters steht bevor... Cowards verdienen es nicht, neben uns im Göttlichen Reich zu gehen."
  },
  AvgDialog_35827_Content_10 = {
    Text = "Caecus, den Kopf gesenkt, stützte sich mit seiner Waffe ab."
  },
  AvgDialog_35827_Content_11 = {
    Text = "Ja... dies ist deine letzte Chance, deine letzte Gelegenheit, deine Loyalität zum Göttlichen Reich zu beweisen."
  },
  AvgDialog_35827_Content_13 = {
    Text = "Ein Speer tanzt vor ihm und hinterlässt ein wunderschönes Nachbild. Die Spitze weist schließlich auf Miryam, gerichtet auf seinen \" Meister\"."
  },
  AvgDialog_35827_Content_14 = {
    Text = "Caecus wagte es nicht, Miryams Blick zu treffen, aber er stand zwischen dir und ihr, wie eine dünne Stadtmauer."
  },
  AvgDialog_35827_Content_15 = {
    Text = "Entschuldigung, Lady Miryam. Ich..."
  },
  AvgDialog_35827_Content_16 = {
    Text = "Keine Sorge, du bist kein Seefahrer... Ich wusste es von Anfang an."
  },
  AvgDialog_35827_Content_17 = {
    Text = "Miryam kichert, ihre ungewöhnlich purpurnen Augen wenden sich dir und Ramona zu, scheinbar das Interesse an Caecus verlierend."
  },
  AvgDialog_35827_Content_18 = {
    Text = "Caecus ließ seinen angehaltenen Atem los, und im nächsten Moment, als sein Ausatmen seine Haut streifte, fühlte er, wie sein Körper einsank."
  },
  AvgDialog_35827_Content_19 = {
    Text = "Seine Beine konnten seinen Oberkörper nicht mehr tragen, und er taumelte zu Boden. Sein Bauch blähte sich wie ein Ballon auf.\nDie Wirbelsäule, die plötzlich wuchs, durchbrach sein Kleidungsstück und enthüllte fischartige Rückenflossen."
  },
  AvgDialog_35827_Content_2 = {
    Text = "Hebe deinen Kopf, Caecus."
  },
  AvgDialog_35827_Content_20 = {
    Text = "<Change> Mil...liam... mein Herr..."
  },
  AvgDialog_35827_Content_21 = {
    Text = "Der Augapfel, deformiert durch seine Höhle und Muskeln, erschien in einem verwesenen grau-weißen Farbton. Kleine Schuppen begannen auf der Haut zu erscheinen und verwandelten die schmerzhaften Stöhne in eine unheimliche Totenklage aus dem Aequor."
  },
  AvgDialog_35827_Content_22 = {
    Text = "Miryam trennte die Verknüpfung mit Caecus!"
  },
  AvgDialog_35827_Content_23 = {
    Text = "Pssst... Keine Panik, keine Panik."
  },
  AvgDialog_35827_Content_24 = {
    Text = "Miryam beugte sich nieder und berührte Caecus' Gesicht. Ihre Hände waren bald mit einer klebrigen, rutschigen Flüssigkeit bedeckt, der Beweis für Caecus' Verwandlung."
  },
  AvgDialog_35827_Content_25 = {
    Text = "Dies ist dein Prozess... Nur wenn du die Macht von Aequor wirklich annimmst, kannst du den Ruf unseres Meisters empfangen..."
  },
  AvgDialog_35827_Content_26 = {
    Text = "Im Gegensatz zur vorherigen monströsen Verwandlung in ein vollständiges Monster erscheint Miryam jetzt außergewöhnlich ruhig und beherrscht, gefährlich und dennoch elegant."
  },
  AvgDialog_35827_Content_27 = {
    Text = "Aber der Schatten hinter ihr, der flüstert und sich verformt, und der D-Slime, der bei jedem ihrer Treffen auf ihren Lippen zurückbleibt, legt die sich ausbreitende Dunkelheit in ihr vollständig offen."
  },
  AvgDialog_35827_Content_28 = {
    Text = "Das... ist alles... eine Probe von meinem Meister..."
  },
  AvgDialog_35827_Content_29 = {
    Text = "Es ist der \"Clades\"-Effekt! Sie hat tatsächlich erlaubt, dass die Auflösung ihren Geist erodiert..."
  },
  AvgDialog_35827_Content_3 = {
    Text = "Den Seefahrer weiter zu bekämpfen, ist sinnlos. Wir können ihn nicht weiter zurückhalten. Wenn er im tranceartigen Zustand bleibt, müssen wir ihn in Miryams Händen lassen."
  },
  AvgDialog_35827_Content_30 = {
    Text = "Gotteslästerung@2! Dies ist die Prüfung meines Herrn, die mein Silber reinigt und mir die Chance gibt, wieder aufzusteigen!"
  },
  AvgDialog_35827_Content_31 = {
    Text = "Dies ist Seine Gnade, die mir bestowed wurde!"
  },
  AvgDialog_35827_Content_4 = {
    Text = "Wach auf! Caecus!"
  },
  AvgDialog_35827_Content_5 = {
    Text = "Wie könnte ein Kind wie du mit den Seefahrern in Verbindung stehen?"
  },
  AvgDialog_35827_Content_6 = {
    Text = "Du sagst, du bist schon ein Golem? Entschuldigung, ich wollte das nicht ansprechen..."
  },
  AvgDialog_35827_Content_7 = {
    Text = "Ich denke nur, dass du nicht so zerbrechlich bist, wie du dir selbst vorstellst.\nDie Entscheidung, aus einer schmerzhaften Umgebung zu entfliehen, zeigt nicht, dass du ein stärkeres Herz hast als die meisten Menschen?"
  },
  AvgDialog_35827_Content_8 = {
    Text = [[
Ich bin dein Freund, Caecus.
Egal, wie du dich selbst siehst, ich werde dich ermutigen, den richtigen Schritt zu machen.]]
  },
  AvgDialog_35827_Content_9 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35828_Content_1 = {
    Text = "Hier ist es..."
  },
  AvgDialog_35828_Content_10 = {
    Text = "Elton chuckelte zweimal und winkte der Gruppe zu, die fast den Dockbereich verlassen hatte."
  },
  AvgDialog_35828_Content_11 = {
    Text = "Kinder sollten sich nicht in die Angelegenheiten der Erwachsenen einmischen. Ob ich mein verlorenes Heimatland nie finde oder Celeste allmählich verblasst, ich werde es akzeptieren, wenn das unser Schicksal ist."
  },
  AvgDialog_35828_Content_12 = {
    Text = "Gehe mit ihnen, Kind. Vermisse uns nicht zu sehr."
  },
  AvgDialog_35828_Content_13 = {
    Text = "Wer ist dieses Kind?!"
  },
  AvgDialog_35828_Content_14 = {
    Text = "Lass uns gehen, schau nicht zurück."
  },
  AvgDialog_35828_Content_15 = {
    Text = "Gehe, wohin du willst, und tu, was du magst."
  },
  AvgDialog_35828_Content_16 = {
    Text = "Etwas fühlt sich seltsam an. Ist die Einstellung des Kapitäns zu entspannt?"
  },
  AvgDialog_35828_Content_17 = {
    Text = "Um die vergessene Vergangenheit aufzudecken, tauschte er die Hälfte seiner Freiheit gegen Celeste."
  },
  AvgDialog_35828_Content_18 = {
    Text = "Wird er es so leicht loslassen?"
  },
  AvgDialog_35828_Content_19 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35828_Content_2 = {
    Text = "Das ist korrekt, es ist Land."
  },
  AvgDialog_35828_Content_20 = {
    Text = "Ein vierrädriges Auto rast durch die Landschaft, saust über die Straßen von Londinium, stürmt in die verlassene Wildnis und hält schließlich auf einem Platz an."
  },
  AvgDialog_35828_Content_21 = {
    Text = "Wir sind da"
  },
  AvgDialog_35828_Content_22 = {
    Text = "Es ist lange her. Ich dachte, du würdest dieses Mal nicht zurückkommen.\nMein Verstand sagt mir, dass du ernsthafte Probleme mitgebracht hast."
  },
  AvgDialog_35828_Content_23 = {Text = "Gehirn?"},
  AvgDialog_35828_Content_24 = {
    Text = "Du... Bist du Frau Puppe?"
  },
  AvgDialog_35828_Content_25 = {
    Text = "Weißt du mich schon?"
  },
  AvgDialog_35828_Content_26 = {
    Text = "Ramona und %player% haben von dir... und deinem laufenden Zeitstasis-Experiment gesprochen."
  },
  AvgDialog_35828_Content_27 = {
    Text = "Oh? Wie haben sie mich Ihnen vorgestellt?"
  },
  AvgDialog_35828_Content_28 = {
    Text = "Murphy warf instinktiv einen Blick auf den Hüter, der ihr zuzwinkerte, offensichtlich wollte er nicht, dass sie die Wahrheit sagt."
  },
  AvgDialog_35828_Content_29 = {
    Text = "Sie schloss die Augen und versuchte sich an die Geschichten des Hüters über die Mythag-Universität zu erinnern. Doch alles floss wie Wasser davon, die Bilder entglitten ihr zwischen den Fingern, sobald sie Gestalt annahmen."
  },
  AvgDialog_35828_Content_3 = {
    Text = "Was für ein Unsinn! Natürlich weiß ich, dass das Land ist!"
  },
  AvgDialog_35828_Content_30 = {
    Text = "Murphy wird um die Puppe herum außergewöhnlich gehorsam..."
  },
  AvgDialog_35828_Content_31 = {
    Text = "Sie hat wahrscheinlich nie die Schule besucht, was ihre tiefe Ehrfurcht vor Wissen erklären könnte."
  },
  AvgDialog_35828_Content_32 = {
    Text = "Hey! Ich habe das gehört!"
  },
  AvgDialog_35828_Content_33 = {
    Text = "Lass uns die Förmlichkeiten überspringen."
  },
  AvgDialog_35828_Content_34 = {
    Text = "Das Zeitstillstandsprojekt befindet sich noch in der Forschungsphase und wurde nicht durch Tierversuche verifiziert.\nSobald du diesen Raum betrittst, gibt es kein Zurück mehr."
  },
  AvgDialog_35828_Content_35 = {
    Text = "So, hast du deine Wahl getroffen?"
  },
  AvgDialog_35828_Content_36 = {
    Text = "Wählen...?"
  },
  AvgDialog_35828_Content_37 = {
    Text = "Muss ich mich nicht mehr von den Entscheidungen anderer herumstoßen lassen?"
  },
  AvgDialog_35828_Content_38 = {
    Text = "Kann ich... eine Wahl treffen?"
  },
  AvgDialog_35828_Content_39 = {
    Text = "Nein... nein, das ist nicht richtig... Ich sollte nicht hier sein... Ich war darauf vorbereitet..."
  },
  AvgDialog_35828_Content_4 = {
    Text = "Werde nicht zu aufgeregt. Wenn dein Blutdruck steigt, wird die Aktivität des Parasiten zunehmen.\nIch nehme an, du würdest nicht halbwegs aufgeschlitzt werden wollen, oder?"
  },
  AvgDialog_35828_Content_40 = {
    Text = "Ist das ein weiterer Albtraum, der meinen Willen missachtet, korrekt?"
  },
  AvgDialog_35828_Content_41 = {
    Text = "Ist \"Er\" geboren worden?"
  },
  AvgDialog_35828_Content_42 = {
    Text = "Ist alles vorbei? Ich habe eindeutig... meinen <Yellow:resolve> gefasst."
  },
  AvgDialog_35828_Content_43 = {
    Text = "Erinnerungen und Bewusstsein wandern in der Illusion, während die Welt darunter zerbricht und aufgelöst wird.\nMurphy greift plötzlich nach dem Hüter neben ihm, ergreift jedoch nur eine Handvoll Staub in der Illusion."
  },
  AvgDialog_35828_Content_44 = {
    Text = "%player%...? Wo bist du?"
  },
  AvgDialog_35828_Content_45 = {
    Text = "Der Blick fällt in ein chaotisches Dunkel, das Gehör wird bis zum Äußersten verstärkt, das Herz schlägt ohrenbetäubend. Sterne rollen und drehen sich im endlosen Raum, durchbrechen die Dimensionsbarriere und bringen ein wenig Klagelied mit sich."
  },
  AvgDialog_35828_Content_46 = {
    Text = "Hast du nicht versprochen... dass du mich nicht verlassen würdest?"
  },
  AvgDialog_35828_Content_47 = {
    Text = "Du hast gerade fast die \"Kontrolle\" verloren, oder? Ist etwas mit den Studenten passiert?"
  },
  AvgDialog_35828_Content_48 = {
    Text = "Tulu hielt sich die Brust, was einen seltenen Ausdruck anhaltender Angst offenbarte."
  },
  AvgDialog_35828_Content_49 = {
    Text = "......Kein Problem. Goliath hat Murphy entführt, der Hüter wird bald in Schwierigkeiten geraten, {Male=er,Female=sie} braucht meine Hilfe"
  },
  AvgDialog_35828_Content_5 = {
    Text = "Hüter, hör auf, sie zu necken.\nMach dir keine Sorgen. Ms. Celeste hat uns etwas Zeit gekauft, und wir werden sicher nach Londinium zurückkehren."
  },
  AvgDialog_35828_Content_50 = {
    Text = "Mach weiter. Celeste und ich werden in Ordnung sein."
  },
  AvgDialog_35828_Content_51 = {
    Text = "...Ist etwas falsch? Ist alles in Ordnung mit allen?"
  },
  AvgDialog_35828_Content_52 = {
    Text = "Sieht so aus, als hätte Miryam komplett aufgegeben, Caecus."
  },
  AvgDialog_35828_Content_53 = {
    Text = "Caecus kämpfte immer wieder darum, sich wieder aufzurichten; Goliaths Spötteleien konnten seinen Verstand nicht mehr erschüttern."
  },
  AvgDialog_35828_Content_54 = {
    Text = "Du bist Lord Miryam nicht wirklich treu, oder?"
  },
  AvgDialog_35828_Content_55 = {
    Text = "Entschuldigung, Lord Goliath. Ich lasse dich nicht wieder an mir vorbeikommen."
  },
  AvgDialog_35828_Content_56 = {
    Text = "Warum... warum? Warum hast du die Entscheidung wieder für mich getroffen?"
  },
  AvgDialog_35828_Content_57 = {
    Text = "Die äußere Wand des Kokons ist zu dick, und die innere Flüssigkeit ist trüb. Wir können Murphys Zustand im Inneren nicht sehen."
  },
  AvgDialog_35828_Content_58 = {
    Text = "Caecus kann Goliath nicht lange aufhalten. Lass mich erneut versuchen, den Geist zu verfolgen."
  },
  AvgDialog_35828_Content_59 = {
    Text = "Nein! Deine Geisterwelt kann solchen Leichtsinn nicht standhalten.\nSobald die Geisterwelt zusammenbricht, ist es egal, wie sehr du den Körper reparierst, es wird nutzlos sein!"
  },
  AvgDialog_35828_Content_6 = {
    Text = "Vielen Dank, Ramona... Mit dir zu reden macht mich wirklich entspannter."
  },
  AvgDialog_35828_Content_60 = {
    Text = "Aber Murphy, sie—"
  },
  AvgDialog_35828_Content_61 = {
    Text = "Eins oder zwei... alles das gleiche... eine Menge selbstzentrierter Menschen."
  },
  AvgDialog_35828_Content_62 = {
    Text = "Niemand hat jemals nach meiner Meinung gefragt... Hmph.\nÜberleben auf Kosten deiner Opfer... Habe ich jemals gesagt, dass ich das wollte?"
  },
  AvgDialog_35828_Content_63 = {
    Text = "Puh... <Yellow:Dieses Ding> ist nicht verloren gegangen..."
  },
  AvgDialog_35828_Content_64 = {
    Text = "Der Frachter schwankte in den riesigen Wellen, jeder Anstieg hob das Schiff von der Wasseroberfläche. Du klettertest aus der Kabine, blicktest auf die schwarze Kokonschale über dir und schütteltest den Kopf in Richtung Ramona."
  },
  AvgDialog_35828_Content_65 = {
    Text = "—Dann, ignorierend ihren Widerstand, greifst du den zitternden silbernen Schlüssel und sinkst erneut in das Reich des Bewusstseins."
  },
  AvgDialog_35828_Content_66 = {
    Text = "In dem von Auflösung bedeckten Raum wird das Licht, das Leben und Intelligenz symbolisiert, besonders strahlend"
  },
  AvgDialog_35828_Content_67 = {
    Text = "——Das war ein Ritualmesser, das das kalte Mondlicht reflektierte"
  },
  AvgDialog_35828_Content_68 = {
    Text = "——Mmm!!"
  },
  AvgDialog_35828_Content_7 = {
    Text = "Hmph, warum können manche Menschen nichts Positives von dir lernen?"
  },
  AvgDialog_35828_Content_70 = {
    Text = "Das Licht brach plötzlich auf und katapultierte dich gewaltsam aus der Geisterwelt"
  },
  AvgDialog_35828_Content_71 = {
    Text = "Das zu grelle Licht schmerzte in den Augen und ließ unkontrollierbar Tränen fließen"
  },
  AvgDialog_35828_Content_73 = {
    Text = "Die trübe Flüssigkeit floss ab, und die Augen konnten sich endlich wieder auf das Mädchen fokussieren"
  },
  AvgDialog_35828_Content_74 = {
    Text = "Die Klinge steckt tief in der Brust, das mondbeschienene Mädchen öffnet ihre Augen"
  },
  AvgDialog_35828_Content_75 = {
    Text = "Der Todessymbol-Mond ist nah, aber das junge Gesicht zeigt keine Angst"
  },
  AvgDialog_35828_Content_76 = {
    Text = "Ich habe es getan... Ich habe es wirklich getan."
  },
  AvgDialog_35828_Content_77 = {
    Text = "Ich... habe es durchbohrt... Es wird nicht geboren..."
  },
  AvgDialog_35828_Content_78 = {Text = "Damit"},
  AvgDialog_35828_Content_79 = {
    Text = "Die Hand, die den Messergriff hielt, sank kraftlos herab, und rote, zähe, tiefschwarze Flüssigkeit strömte aus der Wunde und tropfte zwischen den Fingern ins Meer"
  },
  AvgDialog_35828_Content_8 = {
    Text = "Murphy wandte sich um und sah zum Dock, wo Elton und Celeste am Boot blieben und sie aus der Ferne beobachteten."
  },
  AvgDialog_35828_Content_80 = {
    Text = "Das Blut strömt schnell aus ihrem Körper, Murphy ist blass wie nie zuvor, doch strahlt eine seltsame Lebenskraft aus"
  },
  AvgDialog_35828_Content_82 = {
    Text = "Nein... nein, nein, nein <Big:nein nein><BigShake:ahhhh—>"
  },
  AvgDialog_35828_Content_83 = {
    Text = "Allmächtiger Gott, vergib mir, vergib diesem Kind, vergib deinem treuen Gläubigen"
  },
  AvgDialog_35828_Content_84 = {
    Text = "Der Moment des Ausrichtens, der Moment des Ausrichtens wird kommen, wird kommen"
  },
  AvgDialog_35828_Content_86 = {
    Text = "\"Die Plazenta\" zerbrach, und das \"Herz\" fiel ebenfalls zusammen — unzählige Hände brachen aus dem Körper hervor und zerschmetterten die Brusthöhle."
  },
  AvgDialog_35828_Content_87 = {
    Text = "Eine deformierte Hand packte die unrecognizable Überreste, überlappend und anschwellen, überlappend und anschwellen—"
  },
  AvgDialog_35828_Content_88 = {
    Text = "Ah... Du hast mich gehört... Du hast auf mich geantwortet..."
  },
  AvgDialog_35828_Content_9 = {
    Text = "Celeste, Kapitän? Kommst du nicht mit?"
  },
  AvgDialog_35828_Content_90 = {
    Text = "Sie brachten eine deformierte Existenz ins Mondlicht"
  },
  AvgDialog_35828_Content_91 = {
    Text = "<Big:Mein großer Gott...!>"
  },
  AvgDialog_35829_Content_1 = {
    Text = "Du und Ramona, erschöpft und verletzt, haben es endlich geschafft, sich dem \"Neugeborenen\" zu nähern."
  },
  AvgDialog_35829_Content_10 = {
    Text = "Entschuldige dich nicht bei mir. Es ist nicht deine Schuld... es ist niemandes Schuld."
  },
  AvgDialog_35829_Content_11 = {
    Text = "Im Gegenteil, wir sind die letzte Barriere, die verhindern kann, dass dieses Ding in die menschliche Gesellschaft eintritt."
  },
  AvgDialog_35829_Content_12 = {
    Text = "Keine Sorge, mit der schweren Luftverschmutzung in Londinium wird er niemals seinen Weg in die Stadt finden."
  },
  AvgDialog_35829_Content_13 = {
    Text = "Einen Witz machend, um die Spannung zu lösen, tauschst du einen letzten Blick mit Ramona aus und machst einen entschlossenen Schritt—"
  },
  AvgDialog_35829_Content_14 = {
    Text = [[
Zeit bis zum Ausrichten:
0 Minuten verbleibend]]
  },
  AvgDialog_35829_Content_2 = {
    Text = "Der \"Neugeburt\" im durchsichtigen schwarzen Kokon hat eine verdrehte Form und ähnelt einem riesigen und zerbrechlichen Primatenembryo."
  },
  AvgDialog_35829_Content_3 = {
    Text = "Der Kopf ist groß und rund, mit unbeholfenen Gliedmaßen, die zucken, als suchten sie nach einer Richtung, um zu wachsen."
  },
  AvgDialog_35829_Content_4 = {
    Text = "Es strahlt eine unbeschreibliche böse Aura aus, was dazu führt, dass du und Ramona euch einen Blick zuwerfen – dieses Wesen könnte die Aequor befehlen, aber es ist bei weitem nicht der Ursprung von Tulus Kraft."
  },
  AvgDialog_35829_Content_5 = {
    Text = "So Kreaturen... Haben wir wirklich eine Chance?"
  },
  AvgDialog_35829_Content_6 = {
    Text = "Ich weiß nicht."
  },
  AvgDialog_35829_Content_7 = {
    Text = "Du greifst Ramonas Hand, deine Muskeln sind steif und müde, und du zwängst ein angestrengtes Lächeln hervor."
  },
  AvgDialog_35829_Content_8 = {
    Text = "Entschuldigung... Ich weiß nicht, ob wir dieses Mal nach Mythag zurückkehren können."
  },
  AvgDialog_35829_Content_9 = {
    Text = "Ramona packte dich fest und ohne zu zögern."
  },
  AvgDialog_35830_Content_1 = {
    Text = "Immer noch keine Antwort von Caecus?"
  },
  AvgDialog_35830_Content_10 = {
    Text = "Mein Schiff liegt am Pier. Warum kommst du nicht an Bord und wärmst dich auf?"
  },
  AvgDialog_35830_Content_11 = {
    Text = "Caecus erstarrte an Ort und Stelle, und nach einer langen Weile sprach er schließlich steif."
  },
  AvgDialog_35830_Content_12 = {
    Text = "Wenn es darum geht, die Beziehungen zum Orden aufrechtzuerhalten, gibt es keinen Grund, sich bei mir einzuschmeicheln."
  },
  AvgDialog_35830_Content_13 = {
    Text = "Schmeichelei? Ich bin nicht der Typ, der danebensteht und zusieht, wie jemand im Schnee erfriert. Der Schleim auf deinem Gesicht ist bereits gefroren und glänzt. Weigere dich nicht."
  },
  AvgDialog_35830_Content_14 = {
    Text = "Elton nutzte den Moment von Caecus' Ablenkung, trat zwei Schritte vor und ergriff fest seinen kalten, dünnen Arm."
  },
  AvgDialog_35830_Content_15 = {
    Text = "Lass uns gehen, nur um uns kennenzulernen — ich bin Elton. Hast du einen Namen, Kind?"
  },
  AvgDialog_35830_Content_16 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35830_Content_17 = {
    Text = "Caecus. Nenn mich einfach Caecus."
  },
  AvgDialog_35830_Content_2 = {
    Text = "Es scheint, dass sie abgelenkt sind..."
  },
  AvgDialog_35830_Content_3 = {
    Text = "In diesem entscheidenden Moment?!"
  },
  AvgDialog_35830_Content_4 = {
    Text = "Hier sind die Medikamente für dieses Quartal. Um einen Nervenzusammenbruch und zum Zombie zu werden, denk daran, sie alle sieben Tage einzunehmen."
  },
  AvgDialog_35830_Content_5 = {
    Text = "Caecus legte das Medizin auf den Boden und drückte es sanft, sodass die Flasche auf den Mann rollte, der zehn Fuß entfernt stand."
  },
  AvgDialog_35830_Content_6 = {
    Text = "Der Winternachtswind heulte. Er zog seinen großen schwarzen Umhang enger und hurried in die Dunkelheit."
  },
  AvgDialog_35830_Content_7 = {
    Text = "Warte... es wird gleich schneien. Dieser Naturhafen ist nicht der gewohnte Halt des Seefahrers. Wo wirst du Schutz vor dem Schnee suchen?"
  },
  AvgDialog_35830_Content_8 = {
    Text = "Der letzte Teil seiner Worte wurde von einem besonders heftigen und knochenkalten Windstoß verschlungen. Die Kapuze seines schwarzen Gewandes wurde plötzlich zurückgeblasen, wobei ein Paar fischartiger Ohrflossen sichtbar wurde, die im kalten Wind zitterten."
  },
  AvgDialog_35830_Content_9 = {
    Text = "Sein Herz zog sich zusammen, und unbeholfen zog er seine Kapuze hoch, während er hastiger und ungelenker davonlief."
  },
  AvgDialog_35831_Content_1 = {
    Text = "Schmuddelig@2... Ugh!"
  },
  AvgDialog_35831_Content_10 = {
    Text = "Plötzlich wurde alles still. Die Seefahrer, die lautstark versucht hatten, ihn hinauszudrängen, starrten fassungslos auf die Frau auf der Plattform und warteten auf die nächsten Befehle ihres Meisters."
  },
  AvgDialog_35831_Content_11 = {
    Text = "Heb deinen Kopf."
  },
  AvgDialog_35831_Content_12 = {
    Text = "Er fand schließlich den Mut, aufzusehen, und betrachtete sie mit Ehrfurcht, als wäre sie seine Schicksalsgöttin."
  },
  AvgDialog_35831_Content_13 = {
    Text = "Meister... ich..."
  },
  AvgDialog_35831_Content_14 = {
    Text = "Kein Zweifel, die Nachkommen der Ornn-Familie... Du trägst einige Ähnlichkeiten zu deinen Vorfahren."
  },
  AvgDialog_35831_Content_15 = {
    Text = "Aber... zu schwach."
  },
  AvgDialog_35831_Content_16 = {
    Text = "Sein Herz sank. Doch allein der Anblick von Miryam raubte ihm allen Mut, geschweige denn, ihre Schlussfolgerung zu widerlegen."
  },
  AvgDialog_35831_Content_17 = {
    Text = "Da ich dich bereits erweckt habe, kann ich aus Respekt vor der Orne-Familie deine Existenz als Golem aufrechterhalten... Von jetzt an liegt es in deiner Verantwortung, die Seefahrer und ihre menschlichen Mitarbeiter zu überwachen."
  },
  AvgDialog_35831_Content_18 = {
    Text = "Als \"Mischblut\" solltest du am besten verstehen, wie man mit Menschen kommuniziert."
  },
  AvgDialog_35831_Content_2 = {
    Text = "Die Seemänner schwenkten ihre Waffen, der kalte Stahl reflektierte einen silbernen Glanz im Mondlicht, sodass Caecus unfreiwillig blinzelte."
  },
  AvgDialog_35831_Content_3 = {
    Text = "Durch verschwommenes Sehen sah er Miryams Füße. Seine Erinnerung flashte zurück zu einer Zeit, als er unter einem kalten Altar lag."
  },
  AvgDialog_35831_Content_4 = {
    Text = "Außenstehender... *schläfriger Seufzer*..."
  },
  AvgDialog_35831_Content_5 = {
    Text = "Schließlich... ist er endlich hier angekommen."
  },
  AvgDialog_35831_Content_6 = {
    Text = "Hau... @1... hier raus!"
  },
  AvgDialog_35831_Content_7 = {
    Text = "Seine Besessenheit mit seinen Ursprüngen und dem Seefahrer führte ihn hierher."
  },
  AvgDialog_35831_Content_8 = {
    Text = "Halbblut... Schmutz! <Big:Schmutz!>"
  },
  AvgDialog_35831_Content_9 = {Text = "Leise."},
  AvgDialog_35832_Content_1 = {
    Text = "Genug... Die Aufgabe, die ich dem Perishit gegeben habe, wurde abgeschlossen."
  },
  AvgDialog_35832_Content_10 = {
    Text = "Du erträgst den Schmerz und führst mit rationalem Verhalten deine spirituellen Tentakeln in Caecus' Geisterwelt."
  },
  AvgDialog_35832_Content_11 = {
    Text = "Das Haus in seiner Geisterwelt zerfällt. Wenn du aufhörst dich zu bewegen, werden höhnische und spöttische Stimmen aus jeder Ecke strömen und den Willen des Eindringlings wie Parasiten zerfressen."
  },
  AvgDialog_35832_Content_12 = {
    Text = "Du folgtest den Stöhnern der Not und fandest Caecus, der sich in einer Ecke zusammengekrümmt hatte."
  },
  AvgDialog_35832_Content_13 = {
    Text = "Sein Geist wird gedrängt und marginalisiert, eingesperrt in einem Raum, der wie eine Kabine eines Schiffs aussieht. Wäre da nicht das rhythmische Geräusch wie SOS-Signale, könnte man seine Anwesenheit fast übersehen."
  },
  AvgDialog_35832_Content_14 = {Text = "Caecus..."},
  AvgDialog_35832_Content_15 = {
    Text = "Du greifst nach ihm, und in dem Moment, in dem dein Bewusstsein sich verbindet, steigt ein starkes Gefühl von Erstickung in deinem Hals auf."
  },
  AvgDialog_35832_Content_16 = {
    Text = "Die Hypoxie-Reaktion bringt erneut die Schwindelgefühle und Schmerzen zurück, die du gedacht hattest, sie seien vergangen, was für einen Moment ein verzerrtes Gesicht bei allen, die mit deinem Geist verbunden sind, verursacht."
  },
  AvgDialog_35832_Content_17 = {
    Text = "Ramona war die Erste, die den Schlag abbekam, brach sofort in kaltem Schweiß aus und fiel auf die Knie."
  },
  AvgDialog_35832_Content_18 = {
    Text = "Du streckst die Hand aus, um ihr zu helfen, fühlst dich aber schwindelig und taumelst zwei Schritte, bevor du zu Boden fällst—"
  },
  AvgDialog_35832_Content_19 = {
    Text = "Sei vorsichtig."
  },
  AvgDialog_35832_Content_2 = {
    Text = "Miryam zog sich an den Rand des Risses im Rumpf zurück und griff das scharfe Stahl. Ihr Gesicht war im Schatten ihrer Krone verborgen, und man konnte nur sehen, wie sich ihre Lippen leicht bewegten, als ob sie etwas sagte."
  },
  AvgDialog_35832_Content_20 = {
    Text = "Puh... puh... Für einen Moment dachte ich, der Tod stünde direkt vor der Tür..."
  },
  AvgDialog_35832_Content_21 = {
    Text = "Keeper, was ist mit deinem Körper passiert?"
  },
  AvgDialog_35832_Content_22 = {
    Text = "Du holst tief Luft und schüttelst den Kopf, stabilisierst dich mit Caecus' Hilfe."
  },
  AvgDialog_35832_Content_23 = {
    Text = "Keine Zeit für Erklärungen, wir, wir—"
  },
  AvgDialog_35832_Content_24 = {
    Text = "Geh zum Deck! Es ist eine Falle von Lord Miryam und Lord Goliath!"
  },
  AvgDialog_35832_Content_25 = {
    Text = "Ramona stellte keine weiteren Fragen, noch folgte sie dir und Caecus sofort.\nSie kratzte den feuchten Kohlerückstand aus dem Kessel und fügte schnell etwas trockene Kohle hinzu."
  },
  AvgDialog_35832_Content_26 = {
    Text = "Die Zündkerze drehte sich, verdampfte schnell die verbleibende Feuchtigkeit und der Geruch von verbranntem Material erfüllte erneut den Kraftraum."
  },
  AvgDialog_35832_Content_27 = {
    Text = "Verlasse zuerst diesen Ort, Caecus. Du führst den Weg."
  },
  AvgDialog_35832_Content_3 = {
    Text = "—Und dann ließ sie los und fiel ins Meer."
  },
  AvgDialog_35832_Content_4 = {
    Text = "Die von Mondlicht erleuchtete Wasseroberfläche wurde plötzlich gestört, wodurch ein Schaumtrail entstand, der die Wellen teilte und bis zur anderen Seite des Schiffs reichte."
  },
  AvgDialog_35832_Content_5 = {
    Text = "Gehe nach Caecus schauen!"
  },
  AvgDialog_35832_Content_6 = {
    Text = "Caecus konnte nicht mehr sprechen; jeder Versuch produzierte nur mehr und mehr Schleim, als wären seine zusätzlichen Organe bereits assimiliert worden."
  },
  AvgDialog_35832_Content_7 = {
    Text = "Er hat fast seine menschliche Gestalt verloren, aber glücklicherweise krümmt er sich nur vor Schmerzen, anders als der Helot, der nach der abgetrennten Verknüpfung verrückt wurde."
  },
  AvgDialog_35832_Content_8 = {
    Text = "Du hockst dich vor Caecus und ergreifst ohne Zögern seine Hand."
  },
  AvgDialog_35832_Content_9 = {
    Text = "Verknüpfe ihn"
  },
  AvgDialog_35984_Content_1 = {
    Text = "Grand–Slam–Pakt"
  },
  AvgDialog_35984_Content_10 = {Text = "Bang!"},
  AvgDialog_35984_Content_11 = {
    Text = "Die Vase flog blitzschnell an Georgs Gesicht vorbei."
  },
  AvgDialog_35984_Content_12 = {
    Text = "Ich werde jeden Tag vor Langeweile im Wachsfigurenmuseum wahnsinnig. Habe ich nicht einmal die Freiheit zu singen?!"
  },
  AvgDialog_35984_Content_13 = {
    Text = "Jemand singt ständig, und Georg flucht ununterbrochen, hehe."
  },
  AvgDialog_35984_Content_14 = {
    Text = "Lord Rogers, zügelt Euer geliebtes Haustier; es hat sich in einen wahrhaftigen Dämon verwandelt!"
  },
  AvgDialog_35984_Content_15 = {
    Text = "Hmm... Botticelli... Frühling..."
  },
  AvgDialog_35984_Content_16 = {
    Text = "Wo soll ich diesmal das Modell finden...?"
  },
  AvgDialog_35984_Content_17 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35984_Content_18 = {
    Text = "Da es sowieso nichts anderes zu tun gibt, warum nicht ein paar Karten spielen?"
  },
  AvgDialog_35984_Content_19 = {
    Text = "Pandia zog geschickt ein Kartenspiel aus der Schublade und klatschte es auf den Tisch."
  },
  AvgDialog_35984_Content_2 = {
    Text = "Künstliches Labyrinth: Rogers Wachsfigurenmuseum"
  },
  AvgDialog_35984_Content_20 = {
    Text = "Schon wieder Bridge? Georg spielt nicht gerne Bridge. \nAußerdem fehlt uns ohne den Vampirdiener immer noch einer—"
  },
  AvgDialog_35984_Content_21 = {
    Text = "Pandia zeigte in die Ecke. Beim vernachlässigten Schrank reinigte „24\" die darin befindlichen Ausstellungsstücke."
  },
  AvgDialog_35984_Content_22 = {
    Text = "Zählt sie dazu, und wir sind komplett."
  },
  AvgDialog_35984_Content_23 = {
    Text = "Hmm... Sind alle Regeln jetzt klar?"
  },
  AvgDialog_35984_Content_24 = {
    Text = "Verstanden."
  },
  AvgDialog_35984_Content_25 = {
    Text = "Der Kerl trägt sogar eine Brille. Ist er ein armer Mann aus dem Ostviertel, der sich als gebildet ausgibt? Wie peinlich!"
  },
  AvgDialog_35984_Content_26 = {
    Text = "Bist du dir wirklich sicher? Das ist ziemlich komplex—"
  },
  AvgDialog_35984_Content_27 = {
    Text = "52 Karten, 13 pro Spieler. Gewinne jede Runde mit @21 Stichen. Der Kontrakt ist auf 6 Stiche als Basis festgelegt. Nur Stiche über @16 zählen als Gewinnstiche."
  },
  AvgDialog_35984_Content_28 = {
    Text = "Äh... nicht schlecht."
  },
  AvgDialog_35984_Content_29 = {
    Text = "Ich sehe plötzlich dein Potenzial. Wie wäre es, wenn wir uns zusammentun?"
  },
  AvgDialog_35984_Content_3 = {
    Text = "Ah! Der Prinz auf dem weißen Pferd, der vom Himmel herabsteigt～"
  },
  AvgDialog_35984_Content_30 = {
    Text = "Lord Rogers, wenn ich gewinne, gewährt Ihr mir dann eine Bitte?"
  },
  AvgDialog_35984_Content_31 = {
    Text = "Hehe, jemand wird gleich an seine Grenzen erinnert!"
  },
  AvgDialog_35984_Content_32 = {
    Text = "Sag mir, was ist deine Bitte?"
  },
  AvgDialog_35984_Content_33 = {
    Text = "Braucht Ihr nicht immer noch ein Modell für Eure Wachsfigurensammlung? Ich kann Euer Modell sein."
  },
  AvgDialog_35984_Content_34 = {
    Text = "Wow～ Fräulein 24, meldest du dich freiwillig, um in den Tod zu rennen?"
  },
  AvgDialog_35984_Content_35 = {
    Text = "„24\" senkte schweigend den Kopf, ihre Knöchel, die den Besen umklammerten, wurden leicht weiß."
  },
  AvgDialog_35984_Content_36 = {
    Text = "<Gray:„Frühling\" ist ein Werk, das Rogers auf der Messe ausstellen will. Als Modell ausgewählt zu werden, wird die Aufmerksamkeit erhöhen und mehr Menschen die Möglichkeit geben, es zu sehen.>"
  },
  AvgDialog_35984_Content_37 = {
    Text = "<Gray:Jenkin...>"
  },
  AvgDialog_35984_Content_38 = {
    Text = "Sicher. Fräulein 24, deine Knochenstruktur ist glatt und elegant, was dich perfekt für diese Rolle macht."
  },
  AvgDialog_35984_Content_39 = {
    Text = "Ich bin so, so froh, dass du dich freiwillig meiner großen Kunst angeschlossen hast."
  },
  AvgDialog_35984_Content_4 = {
    Text = "Er trat durch diese Tür und stahl mir mein Herz—"
  },
  AvgDialog_35984_Content_40 = {
    Text = "Zwei Stunden später"
  },
  AvgDialog_35984_Content_41 = {Text = "Tsk..."},
  AvgDialog_35984_Content_42 = {Text = "Ah..."},
  AvgDialog_35984_Content_43 = {
    Text = "Wow, ein Grand Slam! 24, mit dir im Team zu spielen bringt so viel Glück, la la la～"
  },
  AvgDialog_35984_Content_44 = {
    Text = "Ihr zwei, bezahlt!"
  },
  AvgDialog_35984_Content_45 = {
    Text = "Rogers grinste und warf ein paar Silbermünzen hin."
  },
  AvgDialog_35984_Content_46 = {
    Text = "Wer hätte gedacht, dass wir hier eine verborgene Expertin haben? Wirklich beeindruckend."
  },
  AvgDialog_35984_Content_47 = {
    Text = "Wie ist das möglich... Diese Person hat doch gerade eben nicht mal die Regeln verstanden!"
  },
  AvgDialog_35984_Content_48 = {
    Text = "Georg hat 24 einen Monat lang heimlich beobachtet und bestätigt, dass sie eine echte Närrin ist. Wie kann sie so schlau sein..."
  },
  AvgDialog_35984_Content_49 = {
    Text = "Anstand, Georg. Anstand. Schlechte Verlierer werden nie groß～"
  },
  AvgDialog_35984_Content_5 = {Text = "Ich,"},
  AvgDialog_35984_Content_50 = {
    Text = "Georgs Gesicht wurde vor Wut knallrot."
  },
  AvgDialog_35984_Content_51 = {
    Text = "Betrug, sie muss betrogen haben!"
  },
  AvgDialog_35984_Content_52 = {
    Text = "Einfach ein paar simple Matheaufgaben. Basierend auf den aktuellen Tischinformationen betragen die berechneten Wahrscheinlichkeiten der Verteilung von 4 Pik 0,023, 0,183 und 0,412..."
  },
  AvgDialog_35984_Content_53 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35984_Content_54 = {
    Text = "Wow, verstehe überhaupt nichts davon."
  },
  AvgDialog_35984_Content_55 = {
    Text = "...0,314, 0,069. Daher werde ich @1 und @2 beim Abschluss der Runde priorisieren und die Berechnung basierend auf Ihrer Kartenreihenfolge durchführen..."
  },
  AvgDialog_35984_Content_56 = {
    Text = "Während Georg „24\"s akribischer Zusammenfassung zuhörte, senkte er den Kopf und begann, an seinen pummeligen Fingern abzuzählen."
  },
  AvgDialog_35984_Content_57 = {
    Text = "Das kann doch nicht sein. Warum komme ich da nicht drauf...?"
  },
  AvgDialog_35984_Content_58 = {
    Text = "Einspruch! Das sind alles nur Ausreden! Glaubst du, wenn du Dinge von dir gibst, die wir nicht verstehen, entgehst du der Strafe?!"
  },
  AvgDialog_35984_Content_59 = {
    Text = "Georg stürzte sich auf „24\"."
  },
  AvgDialog_35984_Content_6 = {Text = "ganzes,"},
  AvgDialog_35984_Content_60 = {
    Text = "Lass mich sehen, ob du etwas versteckst—"
  },
  AvgDialog_35984_Content_61 = {Text = "Bumm—!!"},
  AvgDialog_35984_Content_62 = {
    Text = "Das Dach des Wachsfigurenkabinetts öffnete sich auf mysteriöse Weise mit einem riesigen Loch, und etwas Schweres krachte auf Georg und zerquetschte ihn zu Brei."
  },
  AvgDialog_35984_Content_63 = {Text = "Auwoo!!"},
  AvgDialog_35984_Content_64 = {
    Text = "Bevor er einen vollständigen Satz aussprechen konnte, verstummte Georg für immer."
  },
  AvgDialog_35984_Content_65 = {
    Text = "Ähm... Was ist das für eine klebrige Substanz an meinem Hintern...?"
  },
  AvgDialog_35984_Content_66 = {
    Text = "Hä, sollte ich nicht zurückkehren? Wie bin ich denn im Wachsfigurenkabinett gelandet?"
  },
  AvgDialog_35984_Content_67 = {
    Text = "{Male=Mr.,Female=Miss} %player%, alles in Ordnung?"
  },
  AvgDialog_35984_Content_68 = {
    Text = "Fräulein Mason, Sie sind auch hier?! Bin ich noch im Geheimgang..."
  },
  AvgDialog_35984_Content_69 = {
    Text = "Ahhh! Es... es ist vom Himmel gefallen..."
  },
  AvgDialog_35984_Content_7 = {
    Text = "<Big:Herz!>"
  },
  AvgDialog_35984_Content_70 = {
    Text = "Joe, Georg?"
  },
  AvgDialog_35984_Content_71 = {
    Text = "Rogers starrte fassungslos auf den zerschmetterten Georg unter dir, seine Augen voller grenzenloser Wut und Trauer."
  },
  AvgDialog_35984_Content_72 = {
    Text = "Pandia... Schnappt sie euch!"
  },
  AvgDialog_35984_Content_8 = {
    Text = "Tss tss, jemand hat zu viel Zeit mit Vampirsklaven verbracht und das Singen gelernt."
  },
  AvgDialog_35984_Content_9 = {
    Text = "Furchtbar, einfach furchtbar!"
  },
  AvgDialog_35985_Content_1 = {Text = "Hmm—!!"},
  AvgDialog_35985_Content_10 = {
    Text = "Nein, meine Wachsfiguren..."
  },
  AvgDialog_35985_Content_11 = {
    Text = "Bevor du reagieren kannst, wird dein Handgelenk fest gepackt."
  },
  AvgDialog_35985_Content_12 = {
    Text = "Schnell, folgt mir, wir müssen hier weg."
  },
  AvgDialog_35985_Content_13 = {
    Text = "In der stillen Nacht rannten drei Personen Hand in Hand von einer Kreuzung zur anderen."
  },
  AvgDialog_35985_Content_14 = {
    Text = "Puh... Fräulein, äh, Brillen–24, wie lange müssen wir noch weiterrennen...?"
  },
  AvgDialog_35985_Content_15 = {
    Text = "Das reicht. Rogers würde nicht an einen so unansehnlichen Friedhof kommen wollen."
  },
  AvgDialog_35985_Content_16 = {
    Text = "Diesmal haben wir alles euch zu verdanken."
  },
  AvgDialog_35985_Content_17 = {
    Text = "Dieser kleine Kerl hat mich ständig im Auge, und ihre Spione sind überall im Wachsfigurenkabinett. Alle 23 meiner Fluchtpläne sind gescheitert."
  },
  AvgDialog_35985_Content_18 = {
    Text = "Es war nur ein Zufall... Wir verstehen nicht einmal, wie wir hier gelandet sind."
  },
  AvgDialog_35985_Content_19 = {
    Text = "Huh, bist du nicht überrascht? Dich einem anderen Version von dir selbst gegenüberzusehen."
  },
  AvgDialog_35985_Content_2 = {
    Text = "Nicht schlecht. Sieht so aus, als sollten die <Red:kleinen Kerlchen> da unten aufwachen und sich an die Arbeit machen..."
  },
  AvgDialog_35985_Content_20 = {
    Text = "„24\" und Mason schauen dich gleichzeitig an, als hättest du eine sehr seltsame Frage gestellt."
  },
  AvgDialog_35985_Content_21 = {
    Text = "Ich verstehe nicht, was du meinst... Es gibt viele 24s auf der Welt, und wir werden ihnen immer begegnen."
  },
  AvgDialog_35985_Content_22 = {
    Text = "<Gray:Könnten es die seltsamen Regeln dieses Geheimgangs sein...?>"
  },
  AvgDialog_35985_Content_23 = {
    Text = "Vergesst es, schon gut."
  },
  AvgDialog_35985_Content_24 = {
    Text = "Ich muss jetzt nach Hause; Jenkin macht sich bestimmt Sorgen um mich."
  },
  AvgDialog_35985_Content_25 = {
    Text = "Warte, Miss 24!!"
  },
  AvgDialog_35985_Content_26 = {
    Text = "„24\" schreitet voran; sie hat Wichtigeres zu tun. Jedoch—"
  },
  AvgDialog_35985_Content_27 = {
    Text = "Klopf, klopf."
  },
  AvgDialog_35985_Content_28 = {
    Text = "Es fühlt sich an, als würden meine inneren Organe von unsichtbaren Fäden gezogen, sich rasch von ihren ursprünglichen Positionen lösend."
  },
  AvgDialog_35985_Content_29 = {Text = "Hmm—!!"},
  AvgDialog_35985_Content_3 = {
    Text = "Die kleinen Kerlchen da unten..."
  },
  AvgDialog_35985_Content_30 = {
    Text = "Etwas in der Nähe... Wer ist da?!"
  },
  AvgDialog_35985_Content_31 = {
    Text = "„24\" umklammerte ihre Brust und krümmte sich vor Schmerz."
  },
  AvgDialog_35985_Content_32 = {
    Text = "Im nächsten Moment färbte sich der Boden unter ihren Knien rasch weiß, und die gesamte Welt wurde zu einer weiten Fläche aus Weiß."
  },
  AvgDialog_35985_Content_33 = {
    Text = "Als sie die Augen wieder öffnet, verschmelzen der Himmel und die schneebedeckte Erde zu einer unergründlichen Leere, und nur die ungebrochenen Berge stehen vor ihr."
  },
  AvgDialog_35985_Content_34 = {
    Text = "Alles ist in blasses, blaues Polarlicht getaucht, kalt und scharf, bar jeder Freude oder Trauer."
  },
  AvgDialog_35985_Content_35 = {
    Text = "Sie kniete am Fuße des Schneebergs."
  },
  AvgDialog_35985_Content_4 = {
    Text = "Damit sind wahrscheinlich die Wachsfiguren gemeint, die wir im Keller des Wachsfigurenkabinetts gesehen haben."
  },
  AvgDialog_35985_Content_5 = {
    Text = "Wenn sie es sind, dann wird es ein zermürbender Kampf..."
  },
  AvgDialog_35985_Content_6 = {Text = "Plopp"},
  AvgDialog_35985_Content_7 = {
    Text = "In einer unbeachteten Ecke benutzte jemand eine Kerze, um Georgs Überreste zu entzünden."
  },
  AvgDialog_35985_Content_8 = {
    Text = "Im Nu wurde das Wachsfigurenkabinett von lodernden Flammen verschlungen."
  },
  AvgDialog_35985_Content_9 = {
    Text = "Oh nein, es brennt!"
  },
  AvgDialog_35987_Content_1 = {
    Text = "„Ursprung\""
  },
  AvgDialog_35987_Content_10 = {
    Text = "Hm? Fräulein Winkle hat gesagt, mein Geheimgang sei furchteinflößend, voller wilder Monster..."
  },
  AvgDialog_35987_Content_11 = {
    Text = "Das ist alles nur ihre Einbildung.\nAber ich habe tatsächlich etwas Besonderes gesehen, nämlich „dich“."
  },
  AvgDialog_35987_Content_12 = {Text = "Ich...?"},
  AvgDialog_35987_Content_13 = {
    Text = "Du lachtest leise und zwinkertst ihr zu."
  },
  AvgDialog_35987_Content_14 = {
    Text = "Das ist ein Geheimnis zwischen „ihr“ und mir. Ich erzähle dir in Zukunft mehr darüber."
  },
  AvgDialog_35987_Content_15 = {
    Text = "Sis——!!"
  },
  AvgDialog_35987_Content_16 = {
    Text = "Jenkin springt plötzlich aus den nahegelegenen Blumen hervor."
  },
  AvgDialog_35987_Content_17 = {
    Text = "Ich bin vom Herumstreifen mit Aigis zurück. Rate mal, was wir gefunden haben?"
  },
  AvgDialog_35987_Content_18 = {
    Text = [[
Jenkin schwenkte ein rotes Band in seiner Hand.
Anders als die, die Mason normalerweise benutzt, hatte dieses eine vergilbte Glocke an seinem Ende.]]
  },
  AvgDialog_35987_Content_19 = {
    Text = "Eine sanfte Brise weht vorbei, und die Glocke klingelt hell, wie ein fröhlicher Kobold."
  },
  AvgDialog_35987_Content_2 = {
    Text = "Misaq Universität, Campus \n Drei Tage später"
  },
  AvgDialog_35987_Content_20 = {
    Text = "Das ist etwas, das im Geheimgang zu sehen war..."
  },
  AvgDialog_35987_Content_21 = {
    Text = "Oh, du hast sie auch im Geheimgang gesehen? Dann musst du die Schwester getroffen haben, die sich in eine Katze verwandelt hat!"
  },
  AvgDialog_35987_Content_22 = {
    Text = "Sag... sag das nicht..."
  },
  AvgDialog_35987_Content_23 = {
    Text = "Wie kannst du das sagen? Dieses Band ist ein äußerst, absolut und unglaublich wichtiges Andenken!"
  },
  AvgDialog_35987_Content_24 = {
    Text = "In dieser Zeit habe ich mich um dich gekümmert und jeden Tag mit dir gespielt. Es hat so viel Spaß gemacht!"
  },
  AvgDialog_35987_Content_25 = {
    Text = "Jenkin legte das Band behutsam in Masons Hand."
  },
  AvgDialog_35987_Content_26 = {
    Text = "Ich erinnere mich, dass jemand einmal gesagt hat, im nächsten Leben eine Katze sein zu wollen."
  },
  AvgDialog_35987_Content_27 = {
    Text = "Wenn wir nur so unbeschwert bleiben könnten, könnte ich mich weiterhin um dich kümmern!"
  },
  AvgDialog_35987_Content_28 = {
    Text = "All die Fischsnacks und die Katzenminze, überlass das mir!"
  },
  AvgDialog_35987_Content_29 = {
    Text = "Mason lächelte hinab, ihre Finger strichen über das kühle, weiche Band."
  },
  AvgDialog_35987_Content_3 = {
    Text = "Ich verstehe. Kurz nachdem du Albino getötet hast, wurdest du von der Bildhauer-Gilde abgeholt."
  },
  AvgDialog_35987_Content_30 = {
    Text = "Eine Katze sein? Das ist etwas fürs nächste Leben."
  },
  AvgDialog_35987_Content_31 = {
    Text = "Im Moment möchte ich einfach gut als „Mason\" leben, zusammen mit allen."
  },
  AvgDialog_35987_Content_32 = {
    Text = "Hm... Es scheint, dass dieser Geheimgang Schwester sehr verändert hat. So war sie vorher nicht."
  },
  AvgDialog_35987_Content_33 = {
    Text = "Ich bezeuge, dass Fräulein Mason die Wahrheit sagt."
  },
  AvgDialog_35987_Content_34 = {
    Text = "Du und Mason tauschtet ein Lächeln aus, die Gedanken kehrten zurück zu dem Moment kurz bevor der Geheimgang kollabierte..."
  },
  AvgDialog_35987_Content_35 = {
    Text = "Ich verstehe... Ich verstehe es jetzt."
  },
  AvgDialog_35987_Content_36 = {
    Text = "Du bist der Ursprung von allem und auch das Ende von allem..."
  },
  AvgDialog_35987_Content_37 = {
    Text = "Als der letzte Schimmer des Sternenlichts verblasst, scheint die Welt von schwarzer Tinte verschlungen zu werden."
  },
  AvgDialog_35987_Content_38 = {
    Text = "Du hörst Glocken aus der Ferne, wie chaotisches Grollen aus den Tiefen des Erdmantels."
  },
  AvgDialog_35987_Content_39 = {
    Text = "Kollabiert der Geheimgang... etwa?!"
  },
  AvgDialog_35987_Content_4 = {
    Text = "Das ist die Geschichte dessen, was danach geschah."
  },
  AvgDialog_35987_Content_40 = {
    Text = "Nimm meine Hand, {Male=Mr.,Female=Miss} %player%!"
  },
  AvgDialog_35987_Content_41 = {
    Text = "Du hältst Masons Hand fest."
  },
  AvgDialog_35987_Content_42 = {
    Text = "In diesem Moment schien dein Blut mühelos in ihren Körper zu fließen, und euer Bewusstsein verschmolz zu einem."
  },
  AvgDialog_35987_Content_43 = {
    Text = "Du spürst, wie du langsam in den Schlaf gleitest, unzählige Träume kommen einer nach dem anderen und tragen dich in die Tiefen der Dunkelheit."
  },
  AvgDialog_35987_Content_44 = {
    Text = "Als du die Augen wieder öffnest, stehst du allein in einer Höhle. Unter deinen Füßen fließt ein schimmernder goldener Fluss, gleich den Adern der Erde."
  },
  AvgDialog_35987_Content_45 = {
    Text = "Ist das das Sternenlicht, das ich zuvor gesehen habe... Hat es sich alles hier versammelt?"
  },
  AvgDialog_35987_Content_46 = {
    Text = "<Red:Rückkehr, Rückkehr...>"
  },
  AvgDialog_35987_Content_47 = {
    Text = "Du folgst dem Strom des Sternenlichts tiefer in die Höhle."
  },
  AvgDialog_35987_Content_48 = {
    Text = "Ist das...?!"
  },
  AvgDialog_35987_Content_49 = {
    Text = "Dieser Ort scheint der ultimative Ursprung aller verdrehten, deformierten und unreinen Dinge zu sein."
  },
  AvgDialog_35987_Content_5 = {
    Text = "Hmm. Ich erinnere mich jetzt an alles. Es war keine angenehme Erinnerung..."
  },
  AvgDialog_35987_Content_50 = {
    Text = "Die hellgraue Masse zitterte und dehnte sich aus, spaltete sich windende, deformierte Monster ab, wie ein Magen in ständigem Kampf."
  },
  AvgDialog_35987_Content_51 = {
    Text = "Doch bevor sie das Ufer erreichten, fielen sie zurück in den Tümpel und wurden von den klaffenden Mäulern der Masse verschlungen."
  },
  AvgDialog_35987_Content_52 = {
    Text = "Die Silhouetten dieser Monster kommen mir irgendwie bekannt vor... Könnte es sein..."
  },
  AvgDialog_35987_Content_53 = {
    Text = "Du hast plötzlich eine starke Ahnung. Du watest durch den grauen Schleim und näherst dich dem Klumpen."
  },
  AvgDialog_35987_Content_54 = {
    Text = "Mason... bist du das?"
  },
  AvgDialog_35987_Content_55 = {
    Text = "Die Masse hielt einen Moment inne und begann dann, sich wieder sanft zu winden."
  },
  AvgDialog_35987_Content_56 = {
    Text = "Sie erzeugt ein raschelndes Geräusch, wie eine freundliche Begrüßung."
  },
  AvgDialog_35987_Content_57 = {
    Text = "Du betrachtest die Monster, die am Rand des Tümpels knien. Sie kämpfen sich vorwärts, zucken im Schleim, voller Sehnsucht, in die Umarmung der Masse zurückzukehren."
  },
  AvgDialog_35987_Content_58 = {
    Text = "Wie jene Pilger, die in Wind und Schnee nach Wundern suchen."
  },
  AvgDialog_35987_Content_59 = {
    Text = "<Red:Die Wurzel aller Unreinheit, allen Schmutzes und allen Unglücks...>"
  },
  AvgDialog_35987_Content_6 = {
    Text = "Du hältst sanft Masons Hand."
  },
  AvgDialog_35987_Content_60 = {
    Text = "<Red:Rückkehr...>"
  },
  AvgDialog_35987_Content_62 = {
    Text = "Denn hier enden alle Flüsse – egal, wie weit sie voneinander entfernt sein mögen, sie werden letztendlich hier zusammenfließen."
  },
  AvgDialog_35987_Content_63 = {
    Text = "Ich verstehe... Du bist also das Ziel, zu dem sie zurückkehren wollen. Ist es das, was du jeden Tag tust?"
  },
  AvgDialog_35987_Content_64 = {
    Text = "Mit einem gebrechlichen Körper jene verstreuten Persönlichkeiten wieder zusammenziehen und sich bemühen, das Erscheinungsbild aufrechtzuerhalten, das „normale Menschen\" haben sollten."
  },
  AvgDialog_35987_Content_65 = {
    Text = "Wie eine erschöpfte Mutter, die auf die Rückkehr ihres umherirrenden Kindes wartet – sie hat nach langen Zeiten der Spaltung und Verschmelzung sogar ihre eigene Identität als Mutter vergessen."
  },
  AvgDialog_35987_Content_66 = {
    Text = "...Kein Wunder, dass ich von diesen vergangenen Ereignissen geträumt habe."
  },
  AvgDialog_35987_Content_67 = {
    Text = "Als ich diese Sterne das letzte Mal sah, hatte ich plötzlich das Gefühl, dass ich ihnen sehr ähnlich bin."
  },
  AvgDialog_35987_Content_68 = {
    Text = "...es gibt auch Unterschiede. Sie wissen, wo ihr Zuhause ist, aber ich habe sogar meine Erinnerungen verloren."
  },
  AvgDialog_35987_Content_69 = {
    Text = "Deine Nase kribbelt plötzlich ein wenig. Du berührst sanft das Fleisch und spürst seinen ruhigen Puls."
  },
  AvgDialog_35987_Content_7 = {
    Text = "Das ist alles Vergangenheit, Fräulein Mason. Ich versichere Ihnen, es wird nie wieder vorkommen."
  },
  AvgDialog_35987_Content_70 = {
    Text = "Mason... Werde auch ich eines Tages mein Zuhause finden? Einfach so, wie du es gerade tust..."
  },
  AvgDialog_35987_Content_71 = {
    Text = "Das Fleisch windet sich und spaltet sich am Ende, um einen weichen, schleimigen Tentakel zu formen, der sanft die Tränen aus deinem Augenwinkel wischt."
  },
  AvgDialog_35987_Content_72 = {
    Text = "<Change>Das wird es bestimmt...</Change>"
  },
  AvgDialog_35987_Content_73 = {
    Text = "<Change>Vergieße keine Tränen..."
  },
  AvgDialog_35987_Content_74 = {Text = "Donnern..."},
  AvgDialog_35987_Content_75 = {
    Text = "Ein schwaches Beben steigt aus der Tiefe empor und durchzieht die Felswände mit Rissen."
  },
  AvgDialog_35987_Content_76 = {
    Text = "Zeit bis zum Zusammenbruch des Bereichs: <Red:0> Min"
  },
  AvgDialog_35987_Content_77 = {
    Text = "Du drehst dich um und verlässt die Höhle."
  },
  AvgDialog_35987_Content_78 = {
    Text = "Als du den Höhleneingang erreichst, kannst du nicht anders, als noch ein letztes Mal zu ihr zurückzublicken."
  },
  AvgDialog_35987_Content_79 = {
    Text = "Abschied, Miss Mason."
  },
  AvgDialog_35987_Content_8 = {
    Text = "Danke... {Male=Mr.,Female=Miss} %player%."
  },
  AvgDialog_35987_Content_80 = {
    Text = "Freude, Trauer, Schmerz... Verschiedene Persönlichkeiten und Emotionen kommen und gehen, doch sie bleibt in jener Höhle."
  },
  AvgDialog_35987_Content_81 = {
    Text = "—Sie lebt."
  },
  AvgDialog_35987_Content_9 = {
    Text = [[

Ich sollte diejenige sein, die sich bedankt.
Als der Geheimgang zusammenbrach, hast du mir viel Zuspruch und Trost gegeben.]]
  },
  AvgDialog_35988_Content_1 = {
    Text = "Schlaflose Schlange"
  },
  AvgDialog_35988_Content_10 = {
    Text = "Sie zitterte, die Hände hoch erhoben, den Blick auf die pechschwarze Kuppel gerichtet, undeutliche Worte murmelnd."
  },
  AvgDialog_35988_Content_11 = {
    Text = "Die Wurzel aller Befleckung, Unreinheit und allen Unglücks..."
  },
  AvgDialog_35988_Content_12 = {
    Text = "Rückkehr... <Big:Rückkehr!>"
  },
  AvgDialog_35988_Content_13 = {
    Text = "Ugh... Mein Kopf tut weh..."
  },
  AvgDialog_35988_Content_14 = {
    Text = "Das Murmeln breitet sich in Wellen aus. Mason umklammert schmerzerfüllt ihren Kopf und kniet hinter „24\" nieder."
  },
  AvgDialog_35988_Content_15 = {
    Text = "Hör auf zu reden... <Big:Hör auf zu reden>!"
  },
  AvgDialog_35988_Content_16 = {
    Text = "Sie stürzte nach vorne und umarmte „24\", die blutüberströmt war, von hinten."
  },
  AvgDialog_35988_Content_17 = {
    Text = "Bitte, hör auf zu reden..."
  },
  AvgDialog_35988_Content_18 = {
    Text = "Mason versuchte verzweifelt, „24\"s erhobene Hände zu greifen, ihr Blut und ihre Tränen vermischten sich. Doch es war alles vergebens."
  },
  AvgDialog_35988_Content_19 = {
    Text = "<Red:Rückkehr, Rückkehr...>"
  },
  AvgDialog_35988_Content_2 = {
    Text = "Die barfüßige Frau kriecht voran."
  },
  AvgDialog_35988_Content_20 = {
    Text = "<Red:Teilt dieses schmutzige und unreine Festmahl!!>"
  },
  AvgDialog_35988_Content_21 = {
    Text = "Miss 24, tu das nicht—!!"
  },
  AvgDialog_35988_Content_22 = {
    Text = "Verdrehte, deformierte Arme sprießen aus „24\"s Körper. Gebadet in Blut und Mondlicht, dann—"
  },
  AvgDialog_35988_Content_23 = {
    Text = "Sanft und doch bestimmt verdrehten sie „24\"s Hals."
  },
  AvgDialog_35988_Content_24 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35988_Content_25 = {
    Text = "Es gab kein erwartetes Blutvergießen. „24\"s Körper verwandelte sich in winzige goldene Sternenlichter, wie Glühwürmchen, die in der dunklen Nacht tanzen."
  },
  AvgDialog_35988_Content_26 = {
    Text = "Hm... Was ist das..."
  },
  AvgDialog_35988_Content_27 = {
    Text = "Sternenlicht umgibt Mason sanft, einige dringen in ihren Körper ein, andere tanzen auf ihren Fingerspitzen und schweben dann leicht davon."
  },
  AvgDialog_35988_Content_28 = {
    Text = "...Ich habe diese Sternenlichter schon gesehen."
  },
  AvgDialog_35988_Content_29 = {
    Text = "In Träumen, in der Wirklichkeit... sie sind gekommen, um „uns“ mitzunehmen."
  },
  AvgDialog_35988_Content_3 = {
    Text = "Ihr langes Haar schleift über den Boden, verfilzt mit verdorrtem Gras, Schnee und geronnenem Blut, seines einstigen Glanzes beraubt."
  },
  AvgDialog_35988_Content_30 = {
    Text = "Du streckst die Hand aus, um das Sternenlicht zu berühren. Ein warmes Gefühl durchströmt deine Fingerspitzen, als gäbe es eine verborgene Verbindung zwischen dir und den Sternen."
  },
  AvgDialog_35988_Content_31 = {
    Text = "<Gray:Seltsam, ich fühle mich plötzlich ein wenig traurig...>"
  },
  AvgDialog_35988_Content_32 = {Text = "Bumm—!!"},
  AvgDialog_35988_Content_33 = {
    Text = "Nachdem das letzte Sternenlicht verschwunden war, spürtest du ein vertrautes, zorniges Beben aus der Tiefe des Untergrunds."
  },
  AvgDialog_35988_Content_34 = {
    Text = "Verdammt, bricht der Geheimgang schon wieder zusammen?"
  },
  AvgDialog_35988_Content_35 = {
    Text = "Greif nach meiner Hand, Miss Mason!"
  },
  AvgDialog_35988_Content_36 = {
    Text = "<Yellow:Ermittlungsprotokoll zum künstlichen Labyrinth II>\n\n■ Labyrinth–ID: M–C06\n■ Absturzdatum: Jahr 315, 17. Dezember\n■ Absturzort: Southwark St @2"
  },
  AvgDialog_35988_Content_37 = {
    Text = "<Yellow:■Ermittlungsergebnisse>\n\nJagd auf andere „24 \"–Schatten / Unklare Suizidtendenzen / Religion @2?\nWas ist die Verbindung zwischen ihnen?\n\n... Mehr Hinweise werden benötigt."
  },
  AvgDialog_35988_Content_38 = {
    Text = "In der Zwischenzeit, draußen im Künstlichen Bereich..."
  },
  AvgDialog_35988_Content_39 = {
    Text = "Am Eingang des Labyrinths gehen Forscher in weißen Kitteln geschäftig ein und aus."
  },
  AvgDialog_35988_Content_4 = {
    Text = "In ihrer Nähe, im Schnee begraben und von den Bäumen hängend, befanden sich die ausgedörrten Leichen von „24\"."
  },
  AvgDialog_35988_Content_40 = {
    Text = "Es ist schon ein Tag vergangen, und %player% ist immer noch nicht aufgewacht. Möchten Sie eine erzwungene Labyrinth–Unterbrechung beantragen?"
  },
  AvgDialog_35988_Content_41 = {
    Text = "%hisorher% Vitalzeichen sind stabil, scheinbar unbeeinflusst von drastischen Veränderungen."
  },
  AvgDialog_35988_Content_42 = {
    Text = "Beobachtet noch etwas länger."
  },
  AvgDialog_35988_Content_43 = {
    Text = "Was ist mit Fräulein 24, wenn wir noch länger warten? Der Prüfungsausschuss wollte diesen Fall schon lange als Gelegenheit nutzen, um in die Verwaltung der Erweckten Körper einzugreifen..."
  },
  AvgDialog_35988_Content_44 = {
    Text = "Winkle umklammerte verzweifelt seinen Kopf."
  },
  AvgDialog_35988_Content_45 = {
    Text = "<Shake:Es ist alles meine Schuld, weil ich zu eifrig war, ihr Labyrinth zu erforschen. Jetzt ist unser Schutzherr zu Dornröschen geworden. Was sollen wir nur tun...>"
  },
  AvgDialog_35988_Content_46 = {
    Text = "Keine Sorge, wir haben bereits einen Plan dafür. Wilhelm, der Seniorstudent ist auf dem Weg, um einen Ermittlungseinsatz im Ostviertel durchzuführen."
  },
  AvgDialog_35988_Content_47 = {
    Text = "Was %player% betrifft... gebt {Male=him,Female=her} noch etwas mehr Zeit."
  },
  AvgDialog_35988_Content_48 = {
    Text = "Bernard–Klinik\nOst–Lentiniën"
  },
  AvgDialog_35988_Content_49 = {
    Text = "Gemäß Kapitel 3, Artikel 2, Absatz 13 des Mystia–Vertrags müssen Erweckte Körper, die gegen weltliche Gesetze verstoßen, zunächst einer Untersuchung durch den Prüfungsausschuss unterzogen werden."
  },
  AvgDialog_35988_Content_5 = {
    Text = "Niemand hat je erklärt, was sie in solchen Höhen zu suchen kamen."
  },
  AvgDialog_35988_Content_50 = {
    Text = "Kapitel 3, Artikel 3, Abschnitt 2: Wenn das Verhalten des Verdächtigen auf Flucht oder Entkommen hindeutet, hat der Prüfungsausschuss die Befugnis, ihn unverzüglich in Gewahrsam zu nehmen."
  },
  AvgDialog_35988_Content_51 = {
    Text = "Kapitel 4, Artikel 1: Jede Organisation oder Einzelperson, die Erweckte Körper beherbergt..."
  },
  AvgDialog_35988_Content_52 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35988_Content_53 = {
    Text = "Herr Wilhelm, hören Sie mir zu?"
  },
  AvgDialog_35988_Content_54 = {
    Text = "<Small:... ich höre.>"
  },
  AvgDialog_35988_Content_55 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35988_Content_56 = {
    Text = "Sparen Sie sich die Mühe. Die Leichen und Beweise wurden längst beseitigt. Hier werden Sie nichts finden."
  },
  AvgDialog_35988_Content_57 = {
    Text = "Ach wirklich? Darf ich fragen, was das hier ist?"
  },
  AvgDialog_35988_Content_58 = {
    Text = "Wilhelm hob vorsichtig mit einer Pinzette ein Büschel durchscheinenden, getrockneten Materials auf."
  },
  AvgDialog_35988_Content_59 = {
    Text = "Es sieht aus wie eine Art Schlangenhaut. Aber was hat das mit diesem Fall zu tun?"
  },
  AvgDialog_35988_Content_6 = {
    Text = "Sie weiß nur, dass @2 auf sie wartet, an dem Ort, wo Eis und Licht vergehen."
  },
  AvgDialog_35988_Content_60 = {
    Text = "Es ist bereits Dezember. Wie könnte sich eine Schlange jetzt häuten?"
  },
  AvgDialog_35988_Content_61 = {
    Text = "RRRRIIISS—!"
  },
  AvgDialog_35988_Content_62 = {
    Text = "Ein plötzliches Klappern von Ausrüstung kam aus dem Hinterzimmer der Klinik."
  },
  AvgDialog_35988_Content_63 = {
    Text = "Was war das für ein Geräusch?! Dieser Ort wurde doch schon vor langer Zeit versiegelt..."
  },
  AvgDialog_35988_Content_64 = {
    Text = "Komm heraus."
  },
  AvgDialog_35988_Content_65 = {
    Text = "Das Geräusch gemächlicher Schritte näherte sich, und ein ungewöhnlich blasser Mann trat aus dem Hinterzimmer hervor."
  },
  AvgDialog_35988_Content_66 = {
    Text = "Guten Abend, Offizier."
  },
  AvgDialog_35988_Content_67 = {
    Text = "Ich bin ein Kollege von Dr. Bernard, von den Vorgesetzten geschickt, um seine Forschungsunterlagen abzuholen..."
  },
  AvgDialog_35988_Content_68 = {
    Text = "Die Augen des Mannes waren halb geöffnet, scheinbar etwas schläfrig. Er reichte lächelnd eine Visitenkarte herüber."
  },
  AvgDialog_35988_Content_69 = {
    Text = "Registrierter Arzt der Königlichen Medizinischen Gesellschaft, Durchstechen @2..."
  },
  AvgDialog_35988_Content_7 = {
    Text = "<Red:Unrein. Befleckt. Druck.>"
  },
  AvgDialog_35988_Content_70 = {
    Text = "Tut mir leid, wir haben Dr. Bernards soziales Umfeld bereits untersucht. Wenn ich mich recht erinnere, ist dieser Durchstechen ein Mann in seinen Fünfzigern."
  },
  AvgDialog_35988_Content_71 = {
    Text = "Also gut, wer genau sind Sie?"
  },
  AvgDialog_35988_Content_72 = {
    Text = "Hehe... Wirklich beeindruckend, Prüfungsausschuss. Ihr fotografisches Gedächtnis ist wahrlich bewundernswert."
  },
  AvgDialog_35988_Content_73 = {
    Text = "Er öffnete plötzlich seine Augen, die kobaltgelben senkrechten Pupillen glänzten kalt in der Dunkelheit."
  },
  AvgDialog_35988_Content_74 = {
    Text = "Na gut, ich werde eine Weile mit Ihnen spielen."
  },
  AvgDialog_35988_Content_75 = {Text = "Zisch..."},
  AvgDialog_35988_Content_76 = {
    Text = "Ein eisiges, glitschiges Gefühl berührt mein Gesicht."
  },
  AvgDialog_35988_Content_77 = {
    Text = "Die Decke ist nun von blassen kleinen Schlangen übersät, die sich lautlos winden und wie Regentropfen herabfallen."
  },
  AvgDialog_35988_Content_78 = {
    Text = "Schlangen... Sie sind überall!"
  },
  AvgDialog_35988_Content_79 = {
    Text = "Decke, Boden, Wände... Schlangen krochen überall, wie unzählige blasse Wasserpflanzen, die in einem stillen schwarzen Fluss trieben."
  },
  AvgDialog_35988_Content_8 = {
    Text = "Die Wurzel aller Befleckung, Unreinheit und allen Unglücks..."
  },
  AvgDialog_35988_Content_80 = {
    Text = "An Trupps A-2 und B-1, Gefahr im Inneren erkannt. Sofort in Position gehen."
  },
  AvgDialog_35988_Content_81 = {
    Text = "Wilhelm zog rasch den Silberschlüssel hervor, doch der Mann vor ihm war bereits spurlos verschwunden."
  },
  AvgDialog_35988_Content_82 = {
    Text = "Ich weiß, dass du immer noch hier bist. Komm heraus."
  },
  AvgDialog_35988_Content_83 = {
    Text = "Die schwere Luft ringsum erzitterte kurz, dann entspannte sie sich angenehm."
  },
  AvgDialog_35988_Content_84 = {
    Text = "Ein leises „Zisch“ flüstert an deinem Ohr vorbei, wie eine kalte Brise, die sanft über deine Wange streicht."
  },
  AvgDialog_35988_Content_85 = {
    Text = "Nur eine kleine Aufmerksamkeit meinerseits. Bitte kümmere dich gut um sie, Ermittler."
  },
  AvgDialog_35988_Content_86 = {
    Text = "Gute Nacht."
  },
  AvgDialog_35988_Content_9 = {
    Text = "„24\" sank plötzlich auf die Knie."
  },
  AvgDialog_35989_Content_1 = {
    Text = "Warten auf die Komödie"
  },
  AvgDialog_35989_Content_10 = {
    Text = "Ich hab's auch gesehen! Ihr zwei, Hand in Hand, eure Haare wehend, so schön wie Puppen!"
  },
  AvgDialog_35989_Content_11 = {
    Text = "Psst! Seid leise und stört nicht alle, die die Vorstellung anschauen!"
  },
  AvgDialog_35989_Content_12 = {
    Text = "Auf einer behelfsmäßigen Bühne führt ein Clown mit dickem Gesichts-Make-up eine Vorstellung für das Publikum auf."
  },
  AvgDialog_35989_Content_13 = {
    Text = "Vor langer Zeit, in den Schneebergen des Endlosen Nordens, am Ende eines uralten Flusses, schlummert ein graues Monster～～～"
  },
  AvgDialog_35989_Content_14 = {
    Text = "Hallo zusammen, ich bin dieses Monster. <BigShake:Roar—>"
  },
  AvgDialog_35989_Content_15 = {
    Text = "<Shake:Waaah—> Huh, ist das nicht Jenkin?"
  },
  AvgDialog_35989_Content_16 = {
    Text = "Niemand kennt die Herkunft oder den Namen des Monsters, nur seinen unersättlichen Appetit — jeden Winter füllen die Bewohner am Fuße des Schneebergs Körbe mit köstlichem Essen und feinem Wein..."
  },
  AvgDialog_35989_Content_17 = {
    Text = "Zündet eine silberne Kerze an und stellt den Korb in den Fluss, der eurem Zuhause am nächsten liegt, damit das Monster die Opfergaben empfangen kann."
  },
  AvgDialog_35989_Content_18 = {
    Text = "I–Ich habe eine Frage!\nSollen Monster nicht in den Schneebergen leben? Wie können sie Opfergaben aus dem Fluss empfangen?"
  },
  AvgDialog_35989_Content_19 = {
    Text = "Weil das Ende aller Flüsse am Fuße des Schneebergs liegt, egal wie weit sie voneinander entfernt sind, werden sie schließlich hier zusammenfließen."
  },
  AvgDialog_35989_Content_2 = {
    Text = "Künstliches Labyrinth: Lily-Armenhaus, Ostviertel"
  },
  AvgDialog_35989_Content_20 = {
    Text = "Oh... und was kommt als Nächstes?"
  },
  AvgDialog_35989_Content_21 = {
    Text = "Mampf mampf mampf, ich habe die Opfergaben von allen empfangen! Ich bin sehr glücklich und habe beschlossen, euch alle zu belohnen!"
  },
  AvgDialog_35989_Content_22 = {
    Text = "Nachdem Jenkin zu Ende gesprochen hatte, senkte er den Kopf, und seine Haare begannen heftig zu zittern wie ein Motor."
  },
  AvgDialog_35989_Content_23 = {
    Text = "Hör auf zu zittern, alle Flöhe fallen heraus... Hä, schneit es?"
  },
  AvgDialog_35989_Content_24 = {
    Text = "Wow, es schneit wirklich!"
  },
  AvgDialog_35989_Content_25 = {
    Text = "Silberne Papierschneeflocken flattern herab. Aigis versteckt sich hinter dir und streut leise die kleinen Papierstückchen."
  },
  AvgDialog_35989_Content_26 = {
    Text = "<Small:Psst... Bitte tun Sie so, als hätten Sie Aigis nicht gesehen...>"
  },
  AvgDialog_35989_Content_27 = {
    Text = "Schon bald entzündeten sich leise Kerzen in verschiedenen Farben und hüllten die Gesichter der Kinder sanft in ein warmes, orangefarbenes Leuchten."
  },
  AvgDialog_35989_Content_28 = {
    Text = "Jedes Jahr, wenn der erste Schnee fällt, treiben silberne Kerzen und mit Geschenken gefüllte Körbe den Fluss hinab."
  },
  AvgDialog_35989_Content_29 = {
    Text = "Quiek Quiek—"
  },
  AvgDialog_35989_Content_3 = {
    Text = "<Shake:Hust, hust, mein Rücken...>"
  },
  AvgDialog_35989_Content_30 = {
    Text = "Da kommt der Korb voller Geschenke!"
  },
  AvgDialog_35989_Content_31 = {
    Text = "Sara kam lächelnd heraus und schob den kleinen Servierwagen."
  },
  AvgDialog_35989_Content_32 = {
    Text = "Wow!! Pflaumenpudding, Lachssalat und...Spanferkelbraten!!"
  },
  AvgDialog_35989_Content_33 = {
    Text = "Wartet einen Moment. Was sagen wir vor dem Essen?"
  },
  AvgDialog_35989_Content_34 = {
    Text = "Die Kinder tauschten Blicke aus und antworteten im Chor—"
  },
  AvgDialog_35989_Content_35 = {
    Text = "<BigShake:Frohes Silberfrostfest—!!>"
  },
  AvgDialog_35989_Content_36 = {
    Text = "Ich hatte keine Ahnung, dass hinter dem Silberfrostfest eine solche Legende steckt. Das höre ich zum ersten Mal."
  },
  AvgDialog_35989_Content_37 = {
    Text = "<Gray:Miss Masons Geheimgang ist wie ein Traum. Ich kann mich frei zwischen den Szenen bewegen, ohne dass jemand meine Anwesenheit infrage stellt.>"
  },
  AvgDialog_35989_Content_38 = {
    Text = "<Gray:Alle Szenen und Figuren lassen sich frei kombinieren. Ein solcher Anblick ist in der Realität wohl noch nie vorgekommen...>"
  },
  AvgDialog_35989_Content_39 = {
    Text = "<Gray:Vielleicht ist das Miss Masons tiefster Wunsch?>"
  },
  AvgDialog_35989_Content_4 = {
    Text = "Tut mir wirklich leid, {Male=Mr.,Female=Miss} %player%! Ich scheine in letzter Zeit etwas zugenommen zu haben..."
  },
  AvgDialog_35989_Content_40 = {
    Text = "Fräulein Mason, willst du dich nicht ihnen anschließen?"
  },
  AvgDialog_35989_Content_41 = {
    Text = "Du deutetest auf eine Stelle nicht weit entfernt. Die Kinder waren noch immer um den Clown versammelt und lauschten ihren kunstvollen und fantastischen Geschichten."
  },
  AvgDialog_35989_Content_42 = {
    Text = "Ich bin eine langweilige Person; meine Witze machen die Leute nur schläfrig."
  },
  AvgDialog_35989_Content_43 = {Text = "Waaah..."},
  AvgDialog_35989_Content_44 = {
    Text = "Schwester Mason, Jenkin... sie hat mich geärgert...!"
  },
  AvgDialog_35989_Content_45 = {
    Text = "Hmph, kannst nicht gewinnen und petzt? Wie peinlich! Wer hat dir gesagt, du sollst behaupten, ich hätte Flöhe!"
  },
  AvgDialog_35989_Content_46 = {
    Text = "Schh— Mike ist ein tapferer kleiner Ritter, und kleine Ritter dürfen nicht weinen."
  },
  AvgDialog_35989_Content_47 = {
    Text = "Mason wischte dem kleinen Mike sanft die Tränen und den Rotz ab und tröstete den schluchzenden Jungen mit leiser Stimme."
  },
  AvgDialog_35989_Content_48 = {
    Text = "Schwester Mason, Bobby Bärs Augen sind weg..."
  },
  AvgDialog_35989_Content_49 = {
    Text = "Aigis kam herüber und klammerte sich an die Puppe."
  },
  AvgDialog_35989_Content_5 = {
    Text = "<Shake:Nur etwas? Fräulein Mason, könnten Sie bitte zuerst von mir heruntergehen...>"
  },
  AvgDialog_35989_Content_50 = {
    Text = "Lass mich sehen... Oh nein, sie scheinen wirklich verloren zu sein. Wie wäre es, wenn ich dir heute Abend neue annähe, kleine Schwester?"
  },
  AvgDialog_35989_Content_51 = {Text = "Hmm～!"},
  AvgDialog_35989_Content_52 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35989_Content_53 = {
    Text = "Hmph, macht meiner Schwester immer nur Ärger!"
  },
  AvgDialog_35989_Content_54 = {
    Text = "Aber Miss Mason war auch sehr glücklich, das sehe ich selten"
  },
  AvgDialog_35989_Content_55 = {
    Text = "Sarah saß neben dir, stützte ihr Kinn in die Hände und lächelte, während sie Mason beobachtete, der von Kindern umringt war"
  },
  AvgDialog_35989_Content_56 = {
    Text = "Gebraucht zu werden, ist auch eine Art von Glück"
  },
  AvgDialog_35989_Content_57 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35989_Content_58 = {
    Text = "Allmählich versammeln sich immer mehr Kinder um Mason, während der Clown zunehmend ignoriert wird"
  },
  AvgDialog_35989_Content_59 = {
    Text = "Möchte noch jemand eine Geschichte hören? Vor langer, langer Zeit"
  },
  AvgDialog_35989_Content_6 = {
    Text = "Hm, bin ich in einen neuen Geheimgang gelangt?"
  },
  AvgDialog_35989_Content_60 = {
    Text = "Vor langer Zeit"
  },
  AvgDialog_35989_Content_61 = {
    Text = "Es ist spät, die Kinder sind alle in ihre Zimmer zurückgekehrt, das Waisenhaus kehrt zur gewohnten Ruhe zurück"
  },
  AvgDialog_35989_Content_62 = {
    Text = "Die Aufführung ist vorbei, die Menge zerstreut sich——\nOh!"
  },
  AvgDialog_35989_Content_63 = {
    Text = "Nur der Clown bleibt zurück, um das Chaos aufzuräumen, begleitet von seinem einsamen Spiegelbild"
  },
  AvgDialog_35989_Content_64 = {
    Text = "Der Clown murmelt und schaut in die Schatten der Ecke"
  },
  AvgDialog_35989_Content_65 = {
    Text = "Wirklich traurig, was meinen Sie, werter Zuschauer?"
  },
  AvgDialog_35989_Content_66 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35989_Content_67 = {
    Text = "Ich habe schon von dir gehört: der berüchtigte „Killer 24\", der unsichtbar kommt und geht und es genießt, Persönlichkeiten zu jagen"
  },
  AvgDialog_35989_Content_68 = {
    Text = "Die von dir ins Visier genommenen Persönlichkeiten überleben keine drei Tage – <BigShake:Uwa!>"
  },
  AvgDialog_35989_Content_69 = {
    Text = "Wirklich furchterregend! Aber der Clown vor mir hat weder Angst noch weicht er zurück, warum?"
  },
  AvgDialog_35989_Content_7 = {
    Text = "Seid ihr Engel?"
  },
  AvgDialog_35989_Content_70 = {
    Text = "Hm, Hokuspokus"
  },
  AvgDialog_35989_Content_71 = {
    Text = "Der Clown lacht laut und seine Augen blitzen"
  },
  AvgDialog_35989_Content_72 = {
    Text = "Weil der Mörder nicht wusste, dass minderwertige, instabile Persönlichkeiten keinen Tag überleben"
  },
  AvgDialog_35989_Content_73 = {
    Text = "Sie entstehen aus unzähligen zufälligen Momenten, erfüllen ihre Mission und verschwinden dann für immer"
  },
  AvgDialog_35989_Content_74 = {
    Text = "„Was ist die Mission von „Clown 24„? Natürlich, am Silberfrostfest Freude zu bringen, für Jenkins und alle anderen"
  },
  AvgDialog_35989_Content_75 = {
    Text = "Der Clown lächelt breit, und die Schminke auf seinem Gesicht glitzert wie goldene Sterne"
  },
  AvgDialog_35989_Content_76 = {
    Text = "Ich bin bereits weit über meine Mission hinausgegangen, es ist Zeit zurückzukehren～"
  },
  AvgDialog_35989_Content_77 = {
    Text = "Wohin zurückkehren?"
  },
  AvgDialog_35989_Content_78 = {
    Text = "Natürlich, kehren wir dorthin zurück, wo wir <Yellow:angefangen haben>."
  },
  AvgDialog_35989_Content_79 = {
    Text = "Ich verrate dir ein Geheimnis: Jede Persönlichkeit ist wie ein treibendes Unkraut, und unser gemeinsamer Wunsch ist es, wieder eins zu werden."
  },
  AvgDialog_35989_Content_8 = {
    Text = "Das Mädchen blinzelte dich mit großen Augen an und zeigte auf das große Loch, das ihr durch die Decke geschlagen hattet."
  },
  AvgDialog_35989_Content_80 = {
    Text = "Zusammen lachen, zusammen weinen und die Liebe und das Vertrauen von Jenkin spüren..."
  },
  AvgDialog_35989_Content_81 = {
    Text = "Heh, wie kannst du es wagen, Jenkin zu erwähnen. Weißt du, was meine Mission ist?"
  },
  AvgDialog_35989_Content_82 = {
    Text = "<Red:Töten – alle, die ohne Mühe profitieren wollen. Keinen am Leben lassen.>"
  },
  AvgDialog_35989_Content_84 = {
    Text = "Am pechschwarzen Nachthimmel erhob sich plötzlich ein Schwarm Krähen, schlug mit den Flügeln und flog von den Baumwipfeln davon."
  },
  AvgDialog_35989_Content_85 = {
    Text = "Es ist eine stille Winternacht."
  },
  AvgDialog_35989_Content_9 = {
    Text = "Aigis hat alles gesehen. Ihr seid vom Himmel herabgeflogen."
  },
  AvgDialog_35990_Content_1 = {
    Text = "Goldene Fuge"
  },
  AvgDialog_35990_Content_10 = {
    Text = "Ihr wart viel zu lange getrennt."
  },
  AvgDialog_35990_Content_11 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35990_Content_12 = {
    Text = "Es scheint, als hätte ich zum ersten Mal von der Vergangenheit geträumt."
  },
  AvgDialog_35990_Content_13 = {
    Text = "Du umklammerst deinen Kopf und fühlst, als würde ein unsichtbarer Faden dein Bewusstsein vom Bett fortziehen."
  },
  AvgDialog_35990_Content_14 = {
    Text = "Dann öffnetest du das Fenster und sahst den ersten Schneefall des neuen Jahres."
  },
  AvgDialog_35990_Content_15 = {
    Text = "Wow, es schneit!!"
  },
  AvgDialog_35990_Content_16 = {
    Text = "Die aufgeregten Rufe der Kinder hallten durch den stillen Nachthimmel. Begleitet von chaotischen Schritten versammelten sich die Waisenkinder unten."
  },
  AvgDialog_35990_Content_17 = {
    Text = "So viel Schnee, schimmernd und wunderschön."
  },
  AvgDialog_35990_Content_18 = {
    Text = "Aigis will einen Schneemann bauen, genau wie der kleine Bobby."
  },
  AvgDialog_35990_Content_19 = {
    Text = "Das ist einfach, ich mach das—"
  },
  AvgDialog_35990_Content_2 = {
    Text = "Du hattest einen unglaublich langen Traum."
  },
  AvgDialog_35990_Content_20 = {
    Text = "Ta-da! Schaut euch mein Meisterwerk an!"
  },
  AvgDialog_35990_Content_21 = {
    Text = "Hmm... es sieht nicht ganz aus wie der kleine Bär Bobby. Es, es..."
  },
  AvgDialog_35990_Content_22 = {
    Text = "Es sieht aus wie ein Hund! Ein Mops!"
  },
  AvgDialog_35990_Content_23 = {
    Text = "<Big:Wahahahaha!>"
  },
  AvgDialog_35990_Content_24 = {
    Text = "Unsinn! Wie könnte ich nur wie ein Hund aussehen?!"
  },
  AvgDialog_35990_Content_25 = {Text = "Squeak!"},
  AvgDialog_35990_Content_26 = {
    Text = "Kinder lachen und spielen in den Gassen. Mason, bereits wach, steht neben dir."
  },
  AvgDialog_35990_Content_27 = {
    Text = "Sie streckte ihre Hand aus und fing ein paar sanfte Schneeflocken in ihrer Handfläche auf."
  },
  AvgDialog_35990_Content_28 = {
    Text = "Die Schneeflocke lag still in ihrer Handfläche, schmolz schnell zu kaltem Wasser und schimmerte in goldenem Sternenlicht."
  },
  AvgDialog_35990_Content_29 = {
    Text = "Hm, das ist das Licht, das wir letztes Mal gesehen haben..."
  },
  AvgDialog_35990_Content_30 = {
    Text = "Unzählige Sternenlichter fliegen aus den Fenstern des Korridors nebenan und verschmelzen zu einem goldenen Fluss am Nachthimmel."
  },
  AvgDialog_35990_Content_31 = {
    Text = "Sie fließen anmutig und erstrecken sich bis hin zu den fernen, mondbeleuchteten Bergen."
  },
  AvgDialog_35990_Content_32 = {
    Text = "Es ist der Duft dieser Clown-Dame. Sie hat uns verlassen."
  },
  AvgDialog_35990_Content_33 = {
    Text = "Aber ich bin nicht traurig... Es scheint, als hätte sie uns aus freiem Willen verlassen, als würde sie nach Hause zurückkehren."
  },
  AvgDialog_35990_Content_34 = {
    Text = "Nach Hause gehen..."
  },
  AvgDialog_35990_Content_35 = {
    Text = "Ich habe es auch gehört... ihren Wunsch, nach Hause zurückzukehren."
  },
  AvgDialog_35990_Content_36 = {
    Text = "Diese Wünsche sind so intensiv, dass sie mich von vergangenen Ereignissen träumen ließen."
  },
  AvgDialog_35990_Content_37 = {
    Text = "Ich wage es nicht mehr, auf eine Heimkehr zu hoffen; ich wäre schon zufrieden, wenn ich einige vergangene Erinnerungen wiedererlangen könnte."
  },
  AvgDialog_35990_Content_38 = {
    Text = "Du stößt einen leichten Seufzer aus und reibst dir etwas verlegen den Kopf."
  },
  AvgDialog_35990_Content_39 = {
    Text = "Reden wir nicht über diese bedrückenden Dinge. Erzählen Sie mir von sich, Fräulein Mason."
  },
  AvgDialog_35990_Content_4 = {
    Text = "Im Traum war der Himmel wie ein zerrissener Friedhof, und schwarze Substanzen strömten wie Tinte herein."
  },
  AvgDialog_35990_Content_40 = {
    Text = "Ich habe gehört, dass Sie schon in jungen Jahren angefangen haben, sich in Lentiniën Ihren Lebensunterhalt zu verdienen. Vermissen Sie noch Ihre Heimat?"
  },
  AvgDialog_35990_Content_41 = {
    Text = "Mason schaute auf Jenkin und den kleinen Mike, die unten miteinander rangen, und lächelte sanft."
  },
  AvgDialog_35990_Content_42 = {
    Text = "Mein Gedächtnis ist furchtbar. Als ich ein Kind war, sagten die Nonnen in der Kirchenschule, ich sei nicht zum Lernen geeignet."
  },
  AvgDialog_35990_Content_43 = {
    Text = [[
Eltern, Heimatstadt... Ich kann mich nicht wirklich erinnern, und ich will es auch nicht.
Gedenken sind dazu da, Freude zu bewahren.]]
  },
  AvgDialog_35990_Content_44 = {
    Text = "In den Märchen, die ich gelesen habe, können nur glückliche und warme Orte Zuhause genannt werden.\nIch möchte ein Zuhause für Jenkin und Braun sein."
  },
  AvgDialog_35990_Content_45 = {
    Text = "Verstehe.\nFräulein Mason, Sie sind weitaus stärker, als ich es mir vorgestellt habe."
  },
  AvgDialog_35990_Content_46 = {
    Text = "So waren Sie nicht, als wir uns zum ersten Mal im Wachsfigurenkabinett trafen."
  },
  AvgDialog_35990_Content_47 = {
    Text = "<Gray:Sieht so aus, als wäre Fräulein Winkles „Menophin-Super-Stabilisierungstherapie\" tatsächlich wirksam.>"
  },
  AvgDialog_35990_Content_48 = {
    Text = "Alle geben ihr Bestes, um mir zu helfen. Wie könnte ich mich da überhaupt nicht verändern?"
  },
  AvgDialog_35990_Content_49 = {
    Text = "Ich hoffe, ich kann allen helfen."
  },
  AvgDialog_35990_Content_5 = {
    Text = "Du liegst mit dem Gesicht nach oben unter dem Riss, dein Herz so nah an der Erde wie möglich."
  },
  AvgDialog_35990_Content_50 = {
    Text = "Du streckst dich gemächlich und blickst geistesabwesend auf das ruhige Wohnviertel unter dir."
  },
  AvgDialog_35990_Content_51 = {
    Text = "Du bist dir nicht sicher, ob es Einbildung ist, aber du scheinst einen Schatten am Ende der dunklen Gasse stehen zu sehen, der gemeinsam mit dir den Lichterfluss am Himmel betrachtet."
  },
  AvgDialog_35990_Content_52 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35990_Content_53 = {
    Text = "Es war das Sternenlicht von damals..."
  },
  AvgDialog_35990_Content_54 = {
    Text = "Hier ist ein Geheimnis: Jede Persona ist wie ein treibendes Kraut, und ganz zu werden ist unser gemeinsamer Wunsch."
  },
  AvgDialog_35990_Content_55 = {
    Text = "Zusammen lachen, zusammen weinen und die Liebe und das Vertrauen von Jenkin spüren..."
  },
  AvgDialog_35990_Content_56 = {
    Text = "...sind nichts als erbärmliche Wahnvorstellungen."
  },
  AvgDialog_35990_Content_57 = {
    Text = "Der Wind weht sanft, und Schneeflocken treiben wie weiche Watte durch die Luft, ziellos umherschwebend."
  },
  AvgDialog_35990_Content_58 = {
    Text = "Das Sternenlicht verblasst allmählich, und dein Bewusstsein scheint mit ihm davonzutreiben."
  },
  AvgDialog_35990_Content_59 = {
    Text = "Wie der nächste Geheimgang, der auf dich wartet, wohl sein wird?"
  },
  AvgDialog_35990_Content_6 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35990_Content_60 = {
    Text = "Du freust dich tatsächlich ein wenig darauf."
  },
  AvgDialog_35990_Content_61 = {
    Text = "<Yellow:Protokoll zur Untersuchung künstlicher Bereiche III>\n\n■Bereichs-ID: M-C06\n■Zusammenbruchzeit: 24. Dezember, Jahr 315 Hongji\n■Zusammenbruchsstandort: Lilys Waisenhaus"
  },
  AvgDialog_35990_Content_62 = {
    Text = "<Yellow:■Ermittlungsergebnisse>\n\nIch sah den Schnee und das goldene Sternenlicht, das darin tanzte.\nAus irgendeinem Grund erinnern sie mich immer an die Vergangenheit. Nebel steigt auf, Licht fällt, Lachen verklingt.\nEs ist eine stille Winternacht.\n\n<Yellow:Frohes neues Jahr.>\n\nP.S. Saras Cupcakes mit Zuckerguss sind köstlich."
  },
  AvgDialog_35990_Content_7 = {
    Text = "Du schließt die Augen und spürst das Beben aus der Tiefe des Erdmantels. Es ist ein melancholischer und uralter Rhythmus, der dich an dein Zuhause erinnert."
  },
  AvgDialog_35990_Content_8 = {
    Text = "Nach einer unbekannten Zeitspanne hörst du leises Lachen und spürst, wie jemand deine Hand ergreift.\nDu erwiderst die lang vermisste Wärme mit einem sanften Drücken."
  },
  AvgDialog_35990_Content_9 = {
    Text = "Mutter.\nBevor du rufen konntest, strömten dir bereits Tränen über das Gesicht."
  },
  AvgDialog_35992_Content_1 = {Text = "Endet hier"},
  AvgDialog_35992_Content_10 = {
    Text = "<Red:Unrein. Befleckt. Druck.>"
  },
  AvgDialog_35992_Content_100 = {
    Text = "Goldenes Sternenlicht ergießt sich unaufhörlich aus der Wunde, flackert zerbrechlich in der Luft, bevor es schließlich in Masons Körper fließt."
  },
  AvgDialog_35992_Content_101 = {
    Text = "Nur zusammen... sind wir der wahre Mason Miau..."
  },
  AvgDialog_35992_Content_102 = {
    Text = "Der wahre Mason..."
  },
  AvgDialog_35992_Content_103 = {
    Text = "Das ist der Ort, an dem alle Flüsse enden. Egal wie weit die Strecke, sie werden schließlich hier zusammenfließen."
  },
  AvgDialog_35992_Content_104 = {
    Text = "Ich hörte... ihren Wunsch, nach Hause zurückzukehren."
  },
  AvgDialog_35992_Content_105 = {
    Text = "Hier ist ein Geheimnis: Jede Persona ist wie ein treibendes Kraut, und ganz zu werden ist unser gemeinsamer Wunsch."
  },
  AvgDialog_35992_Content_106 = {
    Text = "Mason schloss sanft die Augen und spürte den goldenen Kreislauf des Sternenlichts in sich."
  },
  AvgDialog_35992_Content_107 = {
    Text = "Sie sah ihr Gesicht und ihre Eingeweide, den Clown, den Gelehrten und unzählige Gesichter ihrer selbst."
  },
  AvgDialog_35992_Content_108 = {
    Text = "Ihr Gesicht spiegelte sich im zerbrochenen Spiegel, alle Augen wandten sich ihr zu, unendliche Stille, unendliche Trauer."
  },
  AvgDialog_35992_Content_109 = {
    Text = "Das waren ihre Schatten, Tränen und Risse, ebenso wie ihr Knochenmark, das tief unter der Erde floss."
  },
  AvgDialog_35992_Content_11 = {
    Text = "Ich muss gehen... Ich muss hinüber..."
  },
  AvgDialog_35992_Content_110 = {
    Text = "Sie wurden gezwungen, ihren Körper zu zerreißen, geboren zu werden, umherzuwandern, und kehrten schließlich mit erschöpften Leibern zurück."
  },
  AvgDialog_35992_Content_111 = {
    Text = "<Red:Ende hier, Ende mit mir.>"
  },
  AvgDialog_35992_Content_12 = {
    Text = "Hey, lauf nicht weg. Ich bürste dich noch.\nAu, warum beißt du!?\n\n<Gray:Ehrlich gesagt, verglichen mit den Katzen in Misaq, ist deine Schwester ziemlich brav...>"
  },
  AvgDialog_35992_Content_13 = {
    Text = "Faint Lachen hallt aus der Ferne wider, trägt die vertraute Wärme und Zuneigung, nach der sie sich sehnt, als wäre es direkt neben ihr."
  },
  AvgDialog_35992_Content_14 = {
    Text = "Jenkin Miau?!"
  },
  AvgDialog_35992_Content_15 = {
    Text = "Die Katze richtete sich auf und versuchte angestrengt, die Quelle des Klangs zu orten."
  },
  AvgDialog_35992_Content_16 = {
    Text = "<Red:Rückkehr.>"
  },
  AvgDialog_35992_Content_17 = {
    Text = "Hmm — nein, da gehe ich nicht hin, miau!"
  },
  AvgDialog_35992_Content_18 = {
    Text = "Jenkin, ich will zurück zu Jenkin... zu allen..."
  },
  AvgDialog_35992_Content_19 = {
    Text = "Zurück... <Big:Zurück, miau!!>"
  },
  AvgDialog_35992_Content_2 = {
    Text = "Die schlafende Katze hatte viele Träume."
  },
  AvgDialog_35992_Content_20 = {
    Text = "Schon gut, schon gut, wir fassen dich nicht an.\nWarum bist du plötzlich so hoch gesprungen? Einen Albtraum gehabt?"
  },
  AvgDialog_35992_Content_21 = {
    Text = "„24\" musterte wachsam die Umgebung, wobei ihre Pupillen und Nasenspitze ständig zuckten."
  },
  AvgDialog_35992_Content_22 = {
    Text = "Schnüffel, schnüffel... Da sind böse Leute in der Nähe..."
  },
  AvgDialog_35992_Content_23 = {
    Text = "Sie sprang auf und stürzte sich in Richtung der Ecke. Jedoch—"
  },
  AvgDialog_35992_Content_25 = {
    Text = "Schluchz, schluchz..."
  },
  AvgDialog_35992_Content_26 = {
    Text = "„24\" liegt am Boden und wimmert. Dunkelrotes Blut sickert langsam aus ihrer klaffenden Wunde."
  },
  AvgDialog_35992_Content_27 = {
    Text = "Nicht schlecht, du bist wachsam. Schade, dass du dir den falschen Gegner ausgesucht hast."
  },
  AvgDialog_35992_Content_28 = {
    Text = "Bist du das?! Fräulein Mason ist schon seit einer Weile verschwunden, könnte es sein—"
  },
  AvgDialog_35992_Content_29 = {
    Text = "Der Schatten lachte und warf die übel zugerichtete Mason vor dich."
  },
  AvgDialog_35992_Content_3 = {
    Text = "Die langsam dahingleitenden Lichtflecken unter den Dachtraufen am Nachmittag, dampfender weißer Reisbrei, der zarte Schwaden aufsteigen ließ, alte Glocken und bunte Bonbonpapiere..."
  },
  AvgDialog_35992_Content_30 = {
    Text = "{Male=Mr.,Female=Miss} %player%... hust hust, es tut mir leid..."
  },
  AvgDialog_35992_Content_31 = {
    Text = "Der Schatten hob seinen Fuß und drückte ihn langsam in Masons Wunde."
  },
  AvgDialog_35992_Content_32 = {
    Text = "Hmm... Aaaah!!"
  },
  AvgDialog_35992_Content_33 = {
    Text = "Ich habe dir gesagt, ich werde mich einer nach dem anderen um dich kümmern."
  },
  AvgDialog_35992_Content_34 = {
    Text = "Während Mason vor Schmerz stöhnte, hörte der Wind auf, der Staub legte sich, und selbst das Sonnenlicht war in einem ewigen Augenblick erstarrt."
  },
  AvgDialog_35992_Content_35 = {
    Text = "Selbst Jenkin neben dir steht so still wie eine Skulptur."
  },
  AvgDialog_35992_Content_36 = {
    Text = "Unterdessen bebte der umgebende Raum plötzlich einige Male, und der Himmel begann abzublättern."
  },
  AvgDialog_35992_Content_37 = {
    Text = "Der weite Himmel stürzt aus der Höhe herab und zerbricht in Stücke."
  },
  AvgDialog_35992_Content_38 = {
    Text = "Kollaps des Geheimgangs...? Nein, es ist schlimmer als das. Was geht hier vor?!"
  },
  AvgDialog_35992_Content_39 = {
    Text = "Der Schatten grinste höhnisch und trat die kaum noch atmende Mason unter ihm."
  },
  AvgDialog_35992_Content_4 = {
    Text = "Und der Schneeberg."
  },
  AvgDialog_35992_Content_40 = {
    Text = "Das wusstest du nicht, oder? Diese Person ist unsere <Yellow:Kernpersönlichkeit>. Wenn sie stirbt, wird hier Chaos ausbrechen."
  },
  AvgDialog_35992_Content_41 = {
    Text = "Was du tust, kommt einem Selbstmord gleich. Warum?"
  },
  AvgDialog_35992_Content_42 = {
    Text = "Dies ist eine Welt, in der die Starken die Schwachen verschlingen. Niemand hat verfügt, dass sie die dominante Persönlichkeit sein muss.\nHabe ich recht, Miss Mason?"
  },
  AvgDialog_35992_Content_43 = {
    Text = "Tut %player%{Male=sir,Female=madam} nichts an... {Male=he,Female=she} ist die Retterin von Jenkin..."
  },
  AvgDialog_35992_Content_44 = {
    Text = "Heh... Eine schwache und unfähige Feigling."
  },
  AvgDialog_35992_Content_45 = {
    Text = "Du hast ihre plumpen Lügen nicht bemerkt."
  },
  AvgDialog_35992_Content_46 = {
    Text = "Das Skalpell schneidet in deinen Körper, und du wehrst dich nicht."
  },
  AvgDialog_35992_Content_47 = {
    Text = "Gezwungen, ihnen zu helfen, wehrst du dich nicht."
  },
  AvgDialog_35992_Content_48 = {
    Text = "Du siehst zu, wie deine liebste Familie ins Armenhaus geht, ohne zu versuchen, sie aufzuhalten."
  },
  AvgDialog_35992_Content_49 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35992_Content_5 = {
    Text = "Huh, wo ist das hier?"
  },
  AvgDialog_35992_Content_50 = {
    Text = "Am Ende hast du nicht einmal deine Pflicht als „Schwester“ erfüllt."
  },
  AvgDialog_35992_Content_51 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_35992_Content_52 = {
    Text = "Du hast all deine Erinnerungen wie Müll auf uns abgeladen. Du spazierst über den Campus, unter der Sonne, und überlässt es uns, im Dunkeln den Schmerz zu zerkauen."
  },
  AvgDialog_35992_Content_53 = {
    Text = "Du bist die Wurzel allen Leidens.\nGlaubst du wirklich, du könntest mich zurückhalten?"
  },
  AvgDialog_35992_Content_54 = {
    Text = "<Red:Du bist dieses Körpers nicht würdig.>"
  },
  AvgDialog_35992_Content_55 = {
    Text = "Es steht dir nicht zu, zu entscheiden, ob wir zusammenpassen — hmph!!"
  },
  AvgDialog_35992_Content_56 = {
    Text = "Du kniest auf dem Boden und fühlst dich schwindelig. Auf der anderen Seite atmet der Schatten gleichmäßig und nähert sich dir langsam."
  },
  AvgDialog_35992_Content_57 = {
    Text = "Nein... Ich kann gerade nicht einmal stehen. Ich muss zuerst den Geist meiner Hauptpersönlichkeit stabilisieren."
  },
  AvgDialog_35992_Content_58 = {
    Text = "Du krabbelst zu Mason hinüber und nimmst ihre Hand."
  },
  AvgDialog_35992_Content_59 = {
    Text = "Miss Mason, lass dich nicht von ihr beeinflussen —"
  },
  AvgDialog_35992_Content_6 = {
    Text = "Jenkin — Miau — Miau —"
  },
  AvgDialog_35992_Content_60 = {
    Text = "Liegt es daran... dass ich zu schwach bin...?"
  },
  AvgDialog_35992_Content_61 = {
    Text = "Wenn ich nur ein wenig stärker gewesen wäre..."
  },
  AvgDialog_35992_Content_62 = {
    Text = "Wäre sie es gewesen, hätte sich Masons Schicksal heute anders entwickelt..."
  },
  AvgDialog_35992_Content_63 = {
    Text = "Heh, schmerzhaft, nicht wahr? Multipliziere deinen jetzigen Schmerz mit dem Zehnfachen, dem Hundertfachen — so fühlen wir uns!"
  },
  AvgDialog_35992_Content_64 = {
    Text = "Ja, ja, ja."
  },
  AvgDialog_35992_Content_65 = {
    Text = "Du bist es nicht wert, diesen Körper zu benutzen, Körper, Kör, Kör, Körper."
  },
  AvgDialog_35992_Content_66 = {
    Text = "Entschuldigung, Entschuldigung, Entschuldigung, Entschuldigung..."
  },
  AvgDialog_35992_Content_67 = {
    Text = "Ich bin nicht Mason, ich kann nicht Mason sein—"
  },
  AvgDialog_35992_Content_68 = {Text = "Miau."},
  AvgDialog_35992_Content_69 = {
    Text = "Die verletzte Katze bewegte sich neben Mason und leckte sanft ihre blutende Wunde."
  },
  AvgDialog_35992_Content_7 = {
    Text = "Das schwache Miauen einer Katze wurde schnell vom Wind und Schnee verschluckt.\nMajestätische, kahle Berge ragten voraus empor und warfen ein verschwommenes, bläuliches Licht über das Land."
  },
  AvgDialog_35992_Content_70 = {
    Text = "Dann senkte sie wieder den Kopf und raschelte mit etwas."
  },
  AvgDialog_35992_Content_71 = {
    Text = "Hier, nicht weinen, miau."
  },
  AvgDialog_35992_Content_72 = {
    Text = "Inmitten der Leere wird ihr etwas in die Handfläche gedrückt."
  },
  AvgDialog_35992_Content_73 = {
    Text = "Ein weicher, kühler Stoff mit einer verrosteten Glocke an einem Ende."
  },
  AvgDialog_35992_Content_74 = {
    Text = "Keine der „24\" ist überflüssig, denn..."
  },
  AvgDialog_35992_Content_75 = {
    Text = "Du bist eine kluge und flinke Gelehrte"
  },
  AvgDialog_35992_Content_76 = {
    Text = "Lord Rogers, wenn ich gewinne, gewährt Ihr mir dann eine Bitte?"
  },
  AvgDialog_35992_Content_77 = {
    Text = "Braucht Ihr nicht immer noch ein Modell für Eure Wachsfigurensammlung? Ich kann Euer Modell sein."
  },
  AvgDialog_35992_Content_78 = {
    Text = "<Gray:„Frühling\" ist Rogers' für die Ausstellung geplantes Werk. Wenn sie als Modell ausgewählt wird, erhöht das die Aufmerksamkeit und ermöglicht es mehr Menschen, es zu sehen.>"
  },
  AvgDialog_35992_Content_79 = {
    Text = "<Gray:Jenkin...>"
  },
  AvgDialog_35992_Content_8 = {
    Text = "Schnüffel, schnüffel... Hmm?!"
  },
  AvgDialog_35992_Content_80 = {
    Text = "Du bist die Quelle der Freude für alle."
  },
  AvgDialog_35992_Content_81 = {
    Text = "Vor langer Zeit, in den Schneebergen des Endlosen Nordens, am Ende eines uralten Flusses, schlummert ein graues Monster～～～"
  },
  AvgDialog_35992_Content_82 = {
    Text = "Hallo zusammen, ich bin das Monster. <Shake: Auuuu—>"
  },
  AvgDialog_35992_Content_83 = {
    Text = "<Shake:Waaah—>"
  },
  AvgDialog_35992_Content_84 = {
    Text = "Du bist eine bezaubernde Katze"
  },
  AvgDialog_35992_Content_85 = {
    Text = "So müde, awuu..."
  },
  AvgDialog_35992_Content_86 = {
    Text = "Gurgle, gurgle..."
  },
  AvgDialog_35992_Content_87 = {
    Text = "Sie schnurrt wirklich wie eine Katze... genau wie die Katzen auf dem Misaq-Campus."
  },
  AvgDialog_35992_Content_88 = {
    Text = "Hey, worüber lachst du?!"
  },
  AvgDialog_35992_Content_89 = {
    Text = "Sie sieht jetzt glücklich aus, wirklich wie eine sorglose kleine Katze."
  },
  AvgDialog_35992_Content_9 = {
    Text = "Sie roch die Klänge. Sie trieben in der Luft, wortlos und ohne Rhythmus, wie der sanfte Ruf einer Mutter."
  },
  AvgDialog_35992_Content_90 = {
    Text = "Ja... Sie sind alle großartige „24\".\nIm Vergleich zu ihnen bin ich völlig nutzlos..."
  },
  AvgDialog_35992_Content_91 = {
    Text = "Du schüttelst sanft den Kopf."
  },
  AvgDialog_35992_Content_92 = {
    Text = "Im Gegenteil, du bist stärker und mutiger als sie, denn—"
  },
  AvgDialog_35992_Content_93 = {
    Text = "Du bist die beste Schwester der Welt."
  },
  AvgDialog_35992_Content_94 = {
    Text = "Meister, das alles ist meine Schuld."
  },
  AvgDialog_35992_Content_95 = {
    Text = "Sie ist nur ein Kind aus den Slums, weiß nichts und wird keine Bedrohung für Euch darstellen..."
  },
  AvgDialog_35992_Content_96 = {
    Text = "<Shake:Lasst sie gehen...>"
  },
  AvgDialog_35992_Content_97 = {
    Text = "<Shake:Lass sie gehen...>"
  },
  AvgDialog_35992_Content_98 = {
    Text = "Die Katze streckte ihre flauschige Pfote aus und hielt Masons Hand."
  },
  AvgDialog_35992_Content_99 = {
    Text = "Es gibt mutige Masons, und es gibt feige Masons. Es gibt kluge Masons, und es gibt törichte Masons.\nNichts davon ist von Bedeutung, denn —"
  },
  AvgDialog_35993_Content_1 = {
    Text = "Gesang der Pilgerin"
  },
  AvgDialog_35993_Content_10 = {
    Text = "<Yellow:Abgemagert, langhaarig und möglicherweise im Besitz von mehr als einem Paar oberer Gliedmaßen.>"
  },
  AvgDialog_35993_Content_11 = {
    Text = "Laut <Blue:‚Southwark Street Auflösungs–Ereignisbericht: C06'> existieren hier Kreaturen, deren Erscheinung und Aktionsradius perfekt übereinstimmen"
  },
  AvgDialog_35993_Content_12 = {
    Text = "\nDieser Bericht wurde von der Misaq Universität im Vereinigten Archiv eingereicht.\nVersuchen Sie nun, seine Authentizität zu leugnen?"
  },
  AvgDialog_35993_Content_13 = {
    Text = "Es ist ein wenig übertrieben, die Zuverlässigkeit der Augenzeugenberichte infrage zu stellen, meine Herren."
  },
  AvgDialog_35993_Content_14 = {
    Text = "Anstatt Zeit mit Wortspielen zu verschwenden, warum fragen wir nicht die betroffene Person direkt?"
  },
  AvgDialog_35993_Content_15 = {
    Text = "Fräulein 24, erinnern Sie sich, was Sie am 17. Dezember um 21:15 Uhr in <Blue:Dr. Bernards Praxis> getan haben?"
  },
  AvgDialog_35993_Content_16 = {
    Text = "Huh? Ich..."
  },
  AvgDialog_35993_Content_17 = {
    Text = "Nur zur Erinnerung: Laut den Krankenakten von <Blue:Dr. Bernard> waren Sie die letzte Patientin, die er vor seinem Tod untersucht hat."
  },
  AvgDialog_35993_Content_18 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35993_Content_19 = {
    Text = "Was habe ich getan?"
  },
  AvgDialog_35993_Content_2 = {
    Text = "Die barfüßige Pilgerin kriecht voran."
  },
  AvgDialog_35993_Content_20 = {
    Text = "<Red:...Natürlich, ihn töten.>"
  },
  AvgDialog_35993_Content_21 = {
    Text = "Fräulein 24? Hörst du zu?"
  },
  AvgDialog_35993_Content_22 = {
    Text = "Ein Schlag, zwei Schläge, drei Schläge... Ich habe sein hübsches Gesicht zu Brei geschlagen, nicht einmal ein Knochen blieb übrig."
  },
  AvgDialog_35993_Content_23 = {
    Text = "Der Geschmack von Blut haftete eine ganze Woche lang an mir."
  },
  AvgDialog_35993_Content_24 = {
    Text = "<Small:Leider zeigt der Verdächtige Ausweichen-Verhalten; gemäß den Klauseln in «Der Vertrag» ist die Prüfungskommission berechtigt, ihn sofort zurückzubringen.>"
  },
  AvgDialog_35993_Content_25 = {
    Text = "<Small: Nein. Miss 24 ist anders als andere Erwecker. Sie—>"
  },
  AvgDialog_35993_Content_26 = {
    Text = "<Small:Sie leidet an Hysterie; sie ist eine Wahnsinnige, wie wir alle wissen. Aber bedeutet das, dass eine Wahnsinnige einen angesehenen Arzt nach Belieben töten darf?>"
  },
  AvgDialog_35993_Content_27 = {
    Text = "<Small:Das ist unzumutbar, Fräulein Doll.>"
  },
  AvgDialog_35993_Content_28 = {
    Text = "<Red: Ich bin ein Mörder.>"
  },
  AvgDialog_35993_Content_29 = {
    Text = "Fräulein 24...? <Big:Fräulein 24!>"
  },
  AvgDialog_35993_Content_3 = {
    Text = "Wind und Schnee des Hohen Nordens verbergen das Gesicht der Pilgerin. Ihre Zehen sind aufgerissen, ihr Blick ist verschwommen, und ihr Blut hinterlässt eine lange Spur im Schnee."
  },
  AvgDialog_35993_Content_30 = {
    Text = "Aufwachen! Ich habe noch nicht einmal mit der Injektion angefangen! Es ist noch nicht Zeit zum Schlafen..."
  },
  AvgDialog_35993_Content_31 = {
    Text = "Hm... Was ist das..."
  },
  AvgDialog_35993_Content_32 = {
    Text = "Gott sei Dank, dass du endlich wach bist!"
  },
  AvgDialog_35993_Content_33 = {
    Text = "Misaq-Lounge"
  },
  AvgDialog_35993_Content_34 = {
    Text = "Ich habe gehört, dass dein Gedächtnis in letzter Zeit ziemlich durcheinander war. Lass mich ein wenig erklären."
  },
  AvgDialog_35993_Content_35 = {
    Text = "Die letzte Untersuchung zu <Yellow:Dr. Bernards Tod> hat zu einem ziemlich unangenehmen Streit mit dem Prüfungsausschuss geführt."
  },
  AvgDialog_35993_Content_36 = {
    Text = "Das endgültige Ergebnis lautet: sieben Tage. Wir haben nur sieben Tage, um die Wahrheit aufzudecken."
  },
  AvgDialog_35993_Content_37 = {
    Text = "Wenn ich mich richtig erinnere, geschah das, bevor du ins Wachsfigurenkabinett geschickt wurdest, also wussten wir nichts davon."
  },
  AvgDialog_35993_Content_38 = {
    Text = "Die Akten waren monatelang versiegelt; wer weiß, wo sie die ausgegraben haben. Außerdem ist eine Ermittlung an einem chaotischen Ort wie dem Ostviertel nichts als ein Wunschtraum..."
  },
  AvgDialog_35993_Content_39 = {
    Text = "Also haben wir beschlossen, %player% zur Ermittlung in dein künstliches Labyrinth zu schicken. Wir brauchen deine kleine Mitarbeit..."
  },
  AvgDialog_35993_Content_4 = {
    Text = "Doch sie marschiert noch immer entschlossen und unbeirrt dem Gipfel entgegen."
  },
  AvgDialog_35993_Content_40 = {
    Text = "Verstehe. Entschuldigung, ich bin in letzter Zeit so schläfrig..."
  },
  AvgDialog_35993_Content_41 = {
    Text = "Es fühlt sich an, als braue sich ein schrecklicher Sturm im Inneren des Körpers zusammen, doch sein Wirt bemerkt nichts davon."
  },
  AvgDialog_35993_Content_42 = {Text = "Warte."},
  AvgDialog_35993_Content_43 = {
    Text = "„Bin ich wirklich die Herrin dieses Körpers?\""
  },
  AvgDialog_35993_Content_44 = {Text = "Ding—!"},
  AvgDialog_35993_Content_45 = {
    Text = "Winkle zieht schnell eine vorbereitete Spritze hervor."
  },
  AvgDialog_35993_Content_46 = {
    Text = "Keine Sorge, dafür bin ich hier. \nEine Spritze, und dein verwirrtes Gehirn wird wieder klar..."
  },
  AvgDialog_35993_Content_47 = {
    Text = "<Shake:So kann %player% drinnen weniger leiden, schließlich weiß niemand, was da drin ist, und wenn eine Katastrophe passiert...>"
  },
  AvgDialog_35993_Content_48 = {
    Text = "Oder wie beim letzten Mal, als wir auf „N\" trafen—<Big:Ah!!>"
  },
  AvgDialog_35993_Content_49 = {
    Text = "Zwinkern zwirbelt nervös ihre Haare und hat einen Schreck"
  },
  AvgDialog_35993_Content_5 = {
    Text = "Ja—\nUnter jenen weißen Bergen, in den Tiefen der dunklen Höhle, liegt der Ursprung aller Unreinheiten <Red:Quelle>."
  },
  AvgDialog_35993_Content_50 = {
    Text = "<Shake:Verdammt! Warum verliere ich so viele Haare...>"
  },
  AvgDialog_35993_Content_51 = {
    Text = "Miss 24 braucht Beruhigung, nicht deine Angst und Haare. Zwinkern, verlasse bitte schnell den Raum nach der Injektion"
  },
  AvgDialog_35993_Content_52 = {
    Text = "In zehn Minuten"
  },
  AvgDialog_35993_Content_53 = {
    Text = "Fühlst du dich jetzt besser, Miss 24?"
  },
  AvgDialog_35993_Content_54 = {
    Text = "Mir geht's gut, nur etwas schwindelig... und %player%?"
  },
  AvgDialog_35993_Content_55 = {
    Text = "Wir sind bereits im künstlichen Bereich der Durchgänge.\nMach dir keine Sorgen, die Zeit, die wir eingestellt haben, beträgt nur eine halbe Stunde, wir werden nicht lange verweilen"
  },
  AvgDialog_35993_Content_56 = {
    Text = "Wo ist Fräulein Ramona? Begleitet sie die Untersuchung nicht?"
  },
  AvgDialog_35993_Content_57 = {
    Text = "Angesichts des instabilen Geisteszustandes des Besitzers des Bereichs ist es unvorhersehbar, was im Bereich erscheinen kann"
  },
  AvgDialog_35993_Content_58 = {
    Text = "Ramonas geistige Stärke könnte nicht ausreichen"
  },
  AvgDialog_35993_Content_59 = {
    Text = "24 senkte frustriert den Kopf und ballte still die Bettdecke"
  },
  AvgDialog_35993_Content_6 = {
    Text = "Das ist ihre Angst, ihr Albtraum."
  },
  AvgDialog_35993_Content_60 = {
    Text = "Miss Doll, was ist, wenn ich sage ... der Mörder bin wirklich ich?"
  },
  AvgDialog_35993_Content_61 = {
    Text = "Ich erinnere mich. An dem Tag ging ich zur Klinik, und dann—"
  },
  AvgDialog_35993_Content_62 = {
    Text = "Pssst... Ich kann nicht garantieren, dass der Ausschuss hier keine Spione eingesetzt hat"
  },
  AvgDialog_35993_Content_63 = {
    Text = "Doll erinnert sich an das Aussehen von Sylvia und bemüht sich, sich ein Trost lächelndes Gesicht aufzusetzen"
  },
  AvgDialog_35993_Content_64 = {
    Text = "Fräulein 24, Sie kennen sich selbst wahrscheinlich nicht so gut, wie Sie denken"
  },
  AvgDialog_35993_Content_65 = {
    Text = "Die „Wahrheit“, die du siehst, ist nicht unbedingt echt"
  },
  AvgDialog_35993_Content_66 = {
    Text = "Ich verstehe nicht... Ist es nicht wahr...?"
  },
  AvgDialog_35993_Content_67 = {
    Text = "Du bist jetzt schon seit mehreren Monaten in Misaq, aber wir wissen nichts über deinen Zustand oder deine vergangenen Erlebnisse."
  },
  AvgDialog_35993_Content_68 = {
    Text = "Betrachte diese Geheimgang-Untersuchung als eine Gelegenheit, Dich neu kennenzulernen, Fräulein 24."
  },
  AvgDialog_35993_Content_69 = {
    Text = "Wir alle möchten dich besser kennenlernen."
  },
  AvgDialog_35993_Content_7 = {
    Text = "Es ist auch ihr letztes Ziel."
  },
  AvgDialog_35993_Content_8 = {
    Text = "Ich akzeptiere Ihre sogenannten „Beweise“ nicht."
  },
  AvgDialog_35993_Content_9 = {
    Text = "Dieser sogenannte Augenzeugenbericht beweist lediglich, dass der Täter eine nichtmenschliche Entität ist, und kann keine bestimmte Person identifizieren."
  },
  AvgDialog_35994_Content_1 = {
    Text = "Schattenmärchen"
  },
  AvgDialog_35994_Content_10 = {
    Text = "<Red:Zisch...>"
  },
  AvgDialog_35994_Content_11 = {
    Text = "In der Dunkelheit sind leise Geräusche zu hören, wie das Zischen einer Viper in einer verlassenen Ecke."
  },
  AvgDialog_35994_Content_12 = {
    Text = "Schlange... Wer ist da?!"
  },
  AvgDialog_35994_Content_13 = {
    Text = "Tippe, tippe, tippe."
  },
  AvgDialog_35994_Content_14 = {
    Text = "Die hastigen Schritte kommen näher, und langes Haar streift rasch an deinem Gesicht vorbei."
  },
  AvgDialog_35994_Content_15 = {
    Text = "Fräulein Mason?!"
  },
  AvgDialog_35994_Content_16 = {
    Text = "Lass mich los... Hey, wer bist du? Gehörst du zu <Yellow:dieser Frau>?"
  },
  AvgDialog_35994_Content_17 = {
    Text = "Hm, erinnerst du dich nicht an mich?"
  },
  AvgDialog_35994_Content_18 = {
    Text = "<Gray:Jetzt erinnere ich mich. Der Mord geschah, bevor Miss Mason das Wachsfigurenkabinett betrat, damals, als wir uns noch nicht begegnet waren...>"
  },
  AvgDialog_35994_Content_19 = {
    Text = "Tippe, tippe, tippe."
  },
  AvgDialog_35994_Content_2 = {
    Text = "<Yellow:Ermittlungsprotokoll des künstlichen Labyrinths>\n\n■Geheimgang-ID: M-C06\n■Einrichtungszeit: 17. Dezember, AF 315, 21:00–21:30 Uhr\n■Einrichtungsort: Klinik von Dr. Bernard"
  },
  AvgDialog_35994_Content_20 = {
    Text = "Anders als die vorherigen hastigen Schritte sind diese Schritte gleichmäßiger."
  },
  AvgDialog_35994_Content_21 = {
    Text = "<Shake:Sie kommt... Sie kommt...>"
  },
  AvgDialog_35994_Content_22 = {Text = "Wer kommt?"},
  AvgDialog_35994_Content_23 = {
    Text = "Sie... nein, „Ich“ bin angekommen!"
  },
  AvgDialog_35994_Content_24 = {
    Text = "<Big:„Ich komme, um mich zu töten!\">"
  },
  AvgDialog_35994_Content_25 = {Text = "?"},
  AvgDialog_35994_Content_26 = {
    Text = "Fäuste, die pfeifend durch die Luft sausen, schlagen auf dich ein."
  },
  AvgDialog_35994_Content_28 = {
    Text = "<Big:Ihr alle, sterbt!>"
  },
  AvgDialog_35994_Content_29 = {
    Text = "In zehn Minuten"
  },
  AvgDialog_35994_Content_3 = {
    Text = "■Labyrinth-Eigner: Mason @2\n■Labyrinth-Infiltrator: %player%\n■Ziel: <Yellow:Dr. Bernards Tod untersuchen>"
  },
  AvgDialog_35994_Content_31 = {
    Text = "Bitte beruhigen Sie sich, Miss... „24\"."
  },
  AvgDialog_35994_Content_32 = {
    Text = "Du stellst dich vor Mason und hältst die heftigen Angriffe der Schatten gerade noch zurück."
  },
  AvgDialog_35994_Content_33 = {
    Text = "Noch einen Schritt, und ich werde keine Gnade zeigen."
  },
  AvgDialog_35994_Content_34 = {
    Text = "Heh, sieht aus, als hätte die Heulsuse sich einen Helfer gesucht."
  },
  AvgDialog_35994_Content_35 = {
    Text = "Das schwache Licht zeichnet eine vertraute schlanke Gestalt nach: langes Haar, ein weißes Kleid und blutrote Iris."
  },
  AvgDialog_35994_Content_36 = {
    Text = "Es ist ein weiteres \"24\"."
  },
  AvgDialog_35994_Content_37 = {
    Text = "Keine Zeit mehr... Keine Sorge, ich werde mich um jeden von euch einzeln kümmern."
  },
  AvgDialog_35994_Content_38 = {
    Text = "Ihr seid bald an der Reihe."
  },
  AvgDialog_35994_Content_39 = {
    Text = "Ohne ein weiteres Wort verschwand „24\" umgehend."
  },
  AvgDialog_35994_Content_4 = {
    Text = "<Shake:Hust, hust... so ein Gestank...>"
  },
  AvgDialog_35994_Content_40 = {Text = "Warte—"},
  AvgDialog_35994_Content_41 = {
    Text = "Hör auf, ihr nachzujagen. Wir können sie nicht besiegen..."
  },
  AvgDialog_35994_Content_42 = {
    Text = "Was geht hier vor? Warum gibt es hier noch eine von dir?"
  },
  AvgDialog_35994_Content_43 = {
    Text = "Ich weiß nicht... Sie ist einfach plötzlich aufgetaucht und hat gesagt, sie wolle mich töten..."
  },
  AvgDialog_35994_Content_44 = {
    Text = "Wurde dieser Arzt auch von ihr getötet?"
  },
  AvgDialog_35994_Content_45 = {
    Text = "Also war sie es, die getötet hat?! Nein, nicht nur das... da ist auch noch die Schlange im Winterschlaf..."
  },
  AvgDialog_35994_Content_46 = {
    Text = "Tausende von Schlangen @2 töten ihre eigenen Geschwister, mit Fingern im Mund... Mmm..."
  },
  AvgDialog_35994_Content_47 = {
    Text = "Miss Mason? Weißt du, was du sagst?"
  },
  AvgDialog_35994_Content_48 = {
    Text = "Was? Es geht nicht darum, was man sagt, sondern was man tut! Das hat mir Herr @2 beigebracht..."
  },
  AvgDialog_35994_Content_49 = {
    Text = "Mason ist völlig in ihre eigene Welt versunken und murmelt eine Reihe wirrer Worte vor sich hin."
  },
  AvgDialog_35994_Content_5 = {
    Text = "Die Klinik ist in einen dichten, blutigen Gestank gehüllt, medizinische Geräte, Bücher und Fallakten liegen überall auf dem Boden verstreut."
  },
  AvgDialog_35994_Content_50 = {
    Text = "Du... Ich habe das Gefühl, dich schon einmal irgendwo gesehen zu haben..."
  },
  AvgDialog_35994_Content_51 = {
    Text = "%player%... Du bist der Schutzherr!"
  },
  AvgDialog_35994_Content_52 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35994_Content_53 = {
    Text = "Wie hast du dich plötzlich daran erinnert, wer ich bin?"
  },
  AvgDialog_35994_Content_54 = {
    Text = "Du spürst plötzlich Kopfschmerzen."
  },
  AvgDialog_35994_Content_55 = {
    Text = "Stürz dich nicht hinein; ich bin noch nicht fertig."
  },
  AvgDialog_35994_Content_56 = {
    Text = "24s Geheimgang unterscheidet sich von denen von Ramona und Sorel. Ihr fehlt eine stabile Persönlichkeit, was sich unweigerlich in ihrem Geheimgang widerspiegeln wird."
  },
  AvgDialog_35994_Content_57 = {
    Text = "Verschiedene Persönlichkeiten sind isoliert und doch miteinander verflochten. Du könntest sogar viele 24s darin sehen."
  },
  AvgDialog_35994_Content_58 = {
    Text = "Zack — Menschen, Orte, Zeit... vielleicht ist nichts davon real."
  },
  AvgDialog_35994_Content_59 = {
    Text = "Wenn alles falsch ist, hat meine Ermittlung dann überhaupt einen Sinn?"
  },
  AvgDialog_35994_Content_6 = {
    Text = "Dr. Bernards Leichnam lag zusammengesackt an der Wand. Sein Kopf war bis zur Unkenntlichkeit verstümmelt."
  },
  AvgDialog_35994_Content_60 = {
    Text = "Natürlich. Selbst wenn es nur eine einprozentige Chance gibt, dass es wahr ist, müssen wir sie ergreifen."
  },
  AvgDialog_35994_Content_61 = {
    Text = "Wir alle wissen, dass Fräulein 24 niemand ist, die wahllos tötet."
  },
  AvgDialog_35994_Content_62 = {
    Text = "Nichts davon ist real... Bleib ruhig, %player%. Kläre zuerst deine Ermittlungsziele."
  },
  AvgDialog_35994_Content_63 = {
    Text = "Du untersuchst Masons Finger. Er ist sehr sauber, ohne Anzeichen von Verletzungen oder Kampfspuren."
  },
  AvgDialog_35994_Content_64 = {
    Text = "Frau Mason, haben Sie irgendwelche Beschwerden gegen Dr. Bernard?"
  },
  AvgDialog_35994_Content_65 = {
    Text = "Er... er hat mich behandelt, aber in letzter Zeit juckt es mich überall. Es ist wirklich seltsam..."
  },
  AvgDialog_35994_Content_66 = {
    Text = "Mason sprach beiläufig und kratzte dabei an dem weißen Augapfel, der aus ihrer Schmelzwunde wuchs."
  },
  AvgDialog_35994_Content_67 = {
    Text = "Natürlich war sie sich ihres eigenen Verhaltens vollkommen nicht bewusst."
  },
  AvgDialog_35994_Content_68 = {
    Text = "Er hat Sie geheilt. Haben Sie beide dann angefangen zu streiten?"
  },
  AvgDialog_35994_Content_69 = {
    Text = "Später... später konnte ich mich an nichts mehr erinnern..."
  },
  AvgDialog_35994_Content_7 = {
    Text = "„30 Jahre alt, männlich, 1, 83 m groß, Abschluss mit Auszeichnung an der medizinischen Fakultät der Universität Lentiniën...“"
  },
  AvgDialog_35994_Content_70 = {
    Text = "Ich verstehe, ich verstehe."
  },
  AvgDialog_35994_Content_71 = {
    Text = "<Gray:Gedächtnisverlust ist ein Schlüsselzeichen für eine gespaltene Persönlichkeit. Während der Behandlung könnte etwas passiert sein, das die Schattenpersönlichkeit hervortreten und den Arzt töten ließ...>"
  },
  AvgDialog_35994_Content_72 = {
    Text = "<Gray:Als Nächstes müssen wir nur die Geheimgang-Zeit um eine Stunde zurückspulen und sehen, was damals passiert ist...>"
  },
  AvgDialog_35994_Content_73 = {
    Text = "Du hobst die Hand und warfst einen Blick auf deine Uhr."
  },
  AvgDialog_35994_Content_74 = {
    Text = "Das Gebiet steht kurz vor dem Ende. Lass uns diese Untersuchung vorerst abschließen."
  },
  AvgDialog_35994_Content_75 = {
    Text = "Fräulein Doll macht sich vielleicht zu viele Gedanken; dieser Geheimgang ist viel einfacher als der von Frau Sorel..."
  },
  AvgDialog_35994_Content_76 = {
    Text = "Du streckst dich gemächlich, dann hockst du dich vor Mason hin und schaust ihr direkt in die Augen."
  },
  AvgDialog_35994_Content_77 = {
    Text = "Fräulein Mason, Ihre Krankheit ist keine gewöhnliche. Das ist nichts, was irgendein Arzt mit einem schicken Diplom heilen kann."
  },
  AvgDialog_35994_Content_78 = {
    Text = "Denken Sie beim nächsten Mal daran, uns bei Misaq zu finden, verstanden?"
  },
  AvgDialog_35994_Content_79 = {
    Text = "Mi, sa, q..."
  },
  AvgDialog_35994_Content_8 = {
    Text = "„Bekannt für ihre Großzügigkeit, leisteten sie viele Jahre lang freiwillige medizinische Dienste in verschiedenen Teilen des Ostviertels...“"
  },
  AvgDialog_35994_Content_80 = {
    Text = "Ja, Misaq Universität. Wir sind Fachleute."
  },
  AvgDialog_35994_Content_81 = {Text = "Oh..."},
  AvgDialog_35994_Content_82 = {
    Text = "Plop. Plop."
  },
  AvgDialog_35994_Content_83 = {
    Text = "Die Wände oben beginnen Stück für Stück zu bröckeln, der Geheimgang ist nicht mehr stabil."
  },
  AvgDialog_35994_Content_84 = {
    Text = "Abschied, Miss Mason."
  },
  AvgDialog_35994_Content_85 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35994_Content_86 = {
    Text = "Es ist jetzt 21:30 Uhr.\nEin kalter Wind heult vorbei, und draußen vor dem Fenster lassen ein paar Krähen einsame Schreie ertönen."
  },
  AvgDialog_35994_Content_87 = {
    Text = "Du stehst immer noch fest in der Klinik, während Mason neben dir kniet und einen verwirrten Ausdruck trägt."
  },
  AvgDialog_35994_Content_88 = {
    Text = "Hmm... {Male=Mr.,Female=Miss} Schutzherr, hast du nicht vor, wieder zu gehen?"
  },
  AvgDialog_35994_Content_89 = {
    Text = "<Shake:Äh, funktioniert die Ausrüstung nicht richtig?>"
  },
  AvgDialog_35994_Content_9 = {
    Text = "Eine makellose Akte, kein Wunder, dass die Polizei und der Prüfungsausschuss sie so hoch schätzen."
  },
  AvgDialog_35994_Content_90 = {Text = "Bumm—!!"},
  AvgDialog_35994_Content_91 = {
    Text = "In der nächsten Sekunde bricht die Welt rasend schnell zusammen, und du fällst in einen bodenlosen Abgrund."
  },
  AvgDialog_35994_Content_92 = {
    Text = "<Big:Aaaaaaa—!!!>"
  },
  AvgDialog_35994_Content_93 = {
    Text = "<Yellow:Protokoll zur Untersuchung künstlicher Bereiche I>\n\n■Bereichs-ID: M-C06\n■Einrichtungszeit: 17. Dezember, Jahr 315 Hongji, 21:00-21:30\n■Einrichtungsort: Klinik von Dr. Bernard"
  },
  AvgDialog_35994_Content_94 = {
    Text = "<Yellow:■Ermittlungsergebnisse>\n\n—Schutzherr vermisst."
  },
  AvgDialog_35996_Content_1 = {
    Text = "Warum... warum..."
  },
  AvgDialog_35996_Content_10 = {
    Text = "Getrieben von Verzweiflung und ohne jemanden, an den man sich wenden kann, das ist „24\"."
  },
  AvgDialog_35996_Content_11 = {
    Text = "Diejenigen, die Glück in einem einfachen Leben finden, sind „24\"."
  },
  AvgDialog_35996_Content_12 = {
    Text = "Gequält von der Bildhauer-Gilde, das ist ebenfalls „24\"."
  },
  AvgDialog_35996_Content_13 = {
    Text = "Nein... Wenn es nicht wegen deiner Feigheit gewesen wäre, wären wir nicht von diesem Doktor gefangen worden..."
  },
  AvgDialog_35996_Content_14 = {Text = "Pssst..."},
  AvgDialog_35996_Content_15 = {
    Text = "Mason bedeckte sanft die Lippen des Schattens. Sie beugte sich hinunter und flüsterte ihm ins Ohr."
  },
  AvgDialog_35996_Content_16 = {
    Text = "Hier ist ein Geheimnis: <Red:Dieser Doktor wurde von mir getötet.>"
  },
  AvgDialog_35996_Content_17 = {
    Text = "Unmöglich. Wie konntest du es wagen...?!"
  },
  AvgDialog_35996_Content_18 = {
    Text = "Töten ist nicht schwer. Ich hatte keine Waffe, also benutzte ich meine Hände, um—"
  },
  AvgDialog_35996_Content_19 = {
    Text = "Am Ende waren meine Hände taub, und alles, was ich sehen konnte, war Blut."
  },
  AvgDialog_35996_Content_2 = {
    Text = "Der Schatten wird von dir besiegt. Sie bricht auf dem Boden zusammen, während winzige Lichtpartikel von ihrem Körper aufsteigen."
  },
  AvgDialog_35996_Content_20 = {
    Text = "Ich musste sicherstellen, dass er vollständig tot ist. Solange er noch atmet, wird er den Kindern des Waisenhauses und Jenkin sicher Schaden zufügen..."
  },
  AvgDialog_35996_Content_21 = {
    Text = "Er ist genau wie die Leute in der Bildhauer-Gilde, nein — er ist sogar noch furchteinflößender..."
  },
  AvgDialog_35996_Content_22 = {
    Text = "Er ist ein wahrer Dämon."
  },
  AvgDialog_35996_Content_23 = {
    Text = "Also warst du es... Du warst es wirklich..."
  },
  AvgDialog_35996_Content_24 = {
    Text = "Was habe ich damals nur getan... Ich wusste von nichts..."
  },
  AvgDialog_35996_Content_25 = {
    Text = "Mason schüttelte sanft den Kopf."
  },
  AvgDialog_35996_Content_26 = {
    Text = "Es war der Mut, den du und die anderen „24\" mir geschenkt haben."
  },
  AvgDialog_35996_Content_27 = {
    Text = "Alle „24\" zusammen bilden eine „Mason\".\nKeine „24\" kann für sich allein existieren."
  },
  AvgDialog_35996_Content_28 = {
    Text = "So wie alle Flüsse an einem Ort zusammenfließen, werden auch alle „24\" an einem Ort zusammenfließen..."
  },
  AvgDialog_35996_Content_29 = {
    Text = "Mason küsste sanft die Stirn des Schattens."
  },
  AvgDialog_35996_Content_3 = {
    Text = "Wie konnte jemand so Mächtiges und Wütendes wie ich... gegen dich verlieren, gegen diese Feigling verlieren..."
  },
  AvgDialog_35996_Content_30 = {
    Text = "Es gehört zu mir."
  },
  AvgDialog_35996_Content_32 = {
    Text = "Der Körper des Schattens verwandelt sich in Sternenlicht, das sich um Mason verstreut und in ihre Haut übergeht."
  },
  AvgDialog_35996_Content_33 = {
    Text = "Ich verstehe... Ich verstehe es jetzt."
  },
  AvgDialog_35996_Content_34 = {
    Text = "Du bist der Ursprung von allem und auch das Ende von allem..."
  },
  AvgDialog_35996_Content_35 = {
    Text = "In der warmen Umarmung verlor sie allmählich ihre Stimme."
  },
  AvgDialog_35996_Content_36 = {
    Text = "Sternenlicht flackert wie Glühwürmchen in der Nacht, erscheint und verschwindet, bis es schließlich vergeht."
  },
  AvgDialog_35996_Content_37 = {
    Text = "Gute Nacht, mein ‚Ein Vierundzwanzigstel'."
  },
  AvgDialog_35996_Content_38 = {
    Text = "<Yellow:Ermittlungsprotokoll künstliches Labyrinth IV>\n\n■Geheimgang–ID: M–C06\n■Fallzeit: Jahr 315 der Flut, Dezember @1\n■Fallort: Camberwell Street, Ostviertel"
  },
  AvgDialog_35996_Content_39 = {
    Text = "<Yellow:■Ermittlungsergebnisse>\n\nDer Geheimgang fand ein stilles Ende.\nDanach stabilisierte sich der Zustand von Fräulein Mason erheblich, was allen große Freude bereitete.\n\n<Yellow:Wir kommen der wahren Fräulein Mason schrittweise näher.>"
  },
  AvgDialog_35996_Content_4 = {Text = "Weil..."},
  AvgDialog_35996_Content_40 = {
    Text = "Misaq Universität, Sekretariat\nEinen Tag später"
  },
  AvgDialog_35996_Content_41 = {
    Text = "Was? Der Prüfungsausschuss hat die Anklage zurückgezogen?"
  },
  AvgDialog_35996_Content_42 = {
    Text = "Während du weg warst, sind viele interessante Dinge passiert. Sie sind jetzt damit beschäftigt, zusammen mit dem städtischen Umweltamt die Schlangenplage zu bekämpfen."
  },
  AvgDialog_35996_Content_43 = {
    Text = "Schlangenplage...?"
  },
  AvgDialog_35996_Content_44 = {
    Text = "Doll breitet eine Ausgabe der „Lentiniër Post\" von vor ein paar Tagen vor dir aus."
  },
  AvgDialog_35996_Content_45 = {
    Text = "„Kürzlich tauchte ein plötzlicher Schwarm von Albinonattern unbekannter Art aus der Klinik des verstorbenen Dr. Bernard auf und verursachte schwere Störungen des örtlichen Verkehrs und des täglichen Lebens...“"
  },
  AvgDialog_35996_Content_46 = {
    Text = "„Augenzeugen behaupten, dies sei die schrecklichste Szene gewesen, die sie je erlebt hätten. Sollten Leser dies ebenfalls beobachtet haben, wenden Sie sich bitte an einen Psychologen unter @2...“"
  },
  AvgDialog_35996_Content_47 = {
    Text = "„Nummer@4...“"
  },
  AvgDialog_35996_Content_48 = {
    Text = "Neben der Nachricht befindet sich ein Foto, auf dem du ein paar bekannte Gesichter vom Prüfungsausschuss zu erkennen scheinst."
  },
  AvgDialog_35996_Content_49 = {
    Text = "Sie halten Netze in den Händen und beseitigen unermüdlich die ständig auftauchenden kleinen Schlangen, ihre Gesichter verraten Erschöpfung und Ungeduld."
  },
  AvgDialog_35996_Content_5 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35996_Content_50 = {
    Text = "Dieser sogenannte „Arzt Bernard“ hat ernsthafte Probleme."
  },
  AvgDialog_35996_Content_51 = {
    Text = "Wir haben Mitglieder der Königlichen Medizinischen Gesellschaft gefunden, aber die Fotos, die sie vorgelegt haben, unterscheiden sich völlig von den Beschreibungen der Anwohner."
  },
  AvgDialog_35996_Content_52 = {
    Text = "Mit anderen Worten, der Verstorbene hat die Identität dieses Dr. Bernard gestohlen. Es ist jedoch noch unklar, ob dieser falsche Arzt wirklich tot ist."
  },
  AvgDialog_35996_Content_53 = {
    Text = "Immerhin lässt sich am Tatort nicht einmal eine Spur einer Leiche finden..."
  },
  AvgDialog_35996_Content_54 = {
    Text = [[
17. Dez., Der Tag des Vorfalls
Dr. Bernards Klinik]]
  },
  AvgDialog_35996_Content_55 = {
    Text = "Die heutige Behandlung ist abgeschlossen. Fräulein Mason, Sie erholen sich gut."
  },
  AvgDialog_35996_Content_56 = {
    Text = "Wirklich? Aber alle sagen, mein Zustand verschlechtere sich..."
  },
  AvgDialog_35996_Content_57 = {
    Text = "Ich fürchte, mein Verständnis von ‚ernst' unterscheidet sich von dem anderer Menschen.\nHaben Sie alle Tinkturen, die ich verschrieben habe, pünktlich eingenommen?"
  },
  AvgDialog_35996_Content_58 = {
    Text = "Platschen!!"
  },
  AvgDialog_35996_Content_59 = {
    Text = "Der Arzt stieß versehentlich die Akten um, und die vergilbten Seiten verteilten sich über den gesamten Boden."
  },
  AvgDialog_35996_Content_6 = {
    Text = "Überlass es mir."
  },
  AvgDialog_35996_Content_60 = {
    Text = "Entschuldigung, das Ostviertel wurde in letzter Zeit von häufigen Ausbrüchen heimgesucht, und die Dokumente der Klinik stapeln sich –"
  },
  AvgDialog_35996_Content_61 = {
    Text = "Keine Sorge! Sie sind ein vielbeschäftigter Arzt, der Tag und Nacht arbeitet. Überlassen Sie die kleine Aufgabe des Aufhebens..."
  },
  AvgDialog_35996_Content_62 = {Text = "Ich denke"},
  AvgDialog_35996_Content_63 = {
    Text = "Die Hand stoppte weniger als 5 Zentimeter vor der Akte. Es war ein Stapel Ausweisdokumente, und Mason konnte einige etwas vertraute Wörter gerade so entziffern."
  },
  AvgDialog_35996_Content_64 = {
    Text = "Versuchsbericht, Transferaufzeichnung...?"
  },
  AvgDialog_35996_Content_65 = {
    Text = "<Shake:Das sind... die vermissten Kinder aus dem Waisenhaus! Nein, es ist noch schlimmer...>"
  },
  AvgDialog_35996_Content_66 = {
    Text = "In der Ecke der aufgeschlagenen Akte ganz unten sah Mason Jenkins leicht trotziges Gesicht."
  },
  AvgDialog_35996_Content_67 = {
    Text = "Ist das deine Schwester? Ich habe sie gesehen. Sie macht sich immer Sorgen um dich und hat sogar versucht, sich einzuschleichen."
  },
  AvgDialog_35996_Content_68 = {
    Text = "Er lächelte schwach, sein Ausdruck wurde sanft."
  },
  AvgDialog_35996_Content_69 = {
    Text = "Ich hatte einst viele Geschwister... Sie fürchteten mich nur, also habe ich sie alle verschlungen."
  },
  AvgDialog_35996_Content_70 = {
    Text = "Alle... aufgefressen?"
  },
  AvgDialog_35996_Content_71 = {
    Text = "Keine Sorge, Fräulein Mason. Ich habe deine Freunde nicht gegessen; ich habe sie nur an einen <Red:sicheren Ort> gebracht."
  },
  AvgDialog_35996_Content_72 = {
    Text = "Also bist du der Drahtzieher hinter diesen Verschwinden..."
  },
  AvgDialog_35996_Content_73 = {
    Text = "<Shake:Dieser Witz ist überhaupt nicht lustig, Herr Bernard...>"
  },
  AvgDialog_35996_Content_74 = {
    Text = "Herr Bernard... Meinst du das hier?"
  },
  AvgDialog_35996_Content_75 = {
    Text = "Der Mann sprach und streckte eine lange Zunge aus seinem Mund, die sich um einen blutigen abgetrennten Finger wickelte."
  },
  AvgDialog_35996_Content_76 = {
    Text = "Er ist zu groß; ich kann ihn immer noch nicht verarbeiten."
  },
  AvgDialog_35996_Content_77 = {
    Text = "Lasst uns einander neu vorstellen. Ich bin <Yellow:Albino>, der Apotheker der Bildhauer-Gilde."
  },
  AvgDialog_35996_Content_78 = {
    Text = "Aaaaaah—!!"
  },
  AvgDialog_35996_Content_79 = {
    Text = "Masons Beine gaben nach, und er stürzte schwer zu Boden."
  },
  AvgDialog_35996_Content_8 = {
    Text = "Mason setzte sich neben den Schatten und hielt den reglosen Schatten in ihren Armen."
  },
  AvgDialog_35996_Content_80 = {
    Text = "<Shake:Du bist ein schlechter Mensch... Du willst sogar Jenkin mitnehmen...>"
  },
  AvgDialog_35996_Content_81 = {
    Text = "Der Mann richtete seine Brille und notierte schnell etwas in der Krankenakte."
  },
  AvgDialog_35996_Content_82 = {
    Text = "Pupillen geweitet, Körper zittert heftig, Herzrasen... Du musst gerade extrem verängstigt sein. Ist dir kalt?"
  },
  AvgDialog_35996_Content_83 = {
    Text = "Nein... Bleib zurück..."
  },
  AvgDialog_35996_Content_84 = {
    Text = "Bald wirst du aufgrund unzureichender Durchblutung des Gehirns ohnmächtig werden, genau wie andere stumpfsinnige Menschen."
  },
  AvgDialog_35996_Content_85 = {
    Text = "Er hob den Kopf von der Krankenakte, ein schwaches Glimmen der Erregung flackerte in seinen goldenen, vertikalen Pupillen."
  },
  AvgDialog_35996_Content_86 = {
    Text = "Oder... wirst du anders reagieren?"
  },
  AvgDialog_35996_Content_87 = {
    Text = "20 Minuten später"
  },
  AvgDialog_35996_Content_88 = {
    Text = "Ich habe jemanden getötet... Ich habe tatsächlich einen Arzt getötet... Die werden mir nicht glauben..."
  },
  AvgDialog_35996_Content_89 = {
    Text = "Nein, warum habe ich ihn einfach getötet...?"
  },
  AvgDialog_35996_Content_9 = {
    Text = "Weil... du nicht alle „24\" akzeptiert hast."
  },
  AvgDialog_35996_Content_90 = {
    Text = "Mason schreckte aus seiner Benommenheit auf und verließ hastig den Tatort."
  },
  AvgDialog_35996_Content_91 = {
    Text = "Der Körper des Mannes sackte gegen die Wand. Sein Kopf war bereits zertrümmert, und Blut sickerte unaufhörlich heraus."
  },
  AvgDialog_35996_Content_92 = {
    Text = "Nach einer unbestimmten Zeit leuchteten plötzlich eine Reihe schwarzer Fluchzeichen am Hals der Leiche auf."
  },
  AvgDialog_35996_Content_93 = {
    Text = "Die Fluchfesseln drehen sich langsam wie Schlangen, und das zu Brei zerquetschte Fleisch beginnt sich zusammenzufügen und neu zu formen..."
  },
  AvgDialog_35996_Content_94 = {
    Text = "Am Ende richtete sich die „Leiche“ langsam auf."
  },
  AvgDialog_35996_Content_95 = {
    Text = "Puh... Nicht schlecht, die Tinkturen haben gewirkt. Ihr Potenzial wurde vollständig entfesselt."
  },
  AvgDialog_35996_Content_96 = {
    Text = "Albino streckte seine lange Schlangenzunge heraus und leckte sich gemächlich das Blut vom Gesicht."
  },
  AvgDialog_35996_Content_97 = {
    Text = "Die Beute ist gereift. Es ist Zeit, unserem Gildenmeister Bericht zu erstatten."
  },
  AvgDialog_35996_Content_98 = {
    Text = "Er hob die Krankenakte zu seinen Füßen auf und ging gemächlich davon."
  },
  AvgDialog_35997_Content_1 = {
    Text = "Allwissende Katze"
  },
  AvgDialog_35997_Content_10 = {
    Text = "Pah, Braun und ich reichen locker aus, um euch Grünschnäbel zu erledigen."
  },
  AvgDialog_35997_Content_11 = {
    Text = "Was hast du gesagt?!"
  },
  AvgDialog_35997_Content_12 = {
    Text = "Wheatley winkte ab, und die aufmüpfigen Kinder verstummten sofort."
  },
  AvgDialog_35997_Content_13 = {
    Text = "Du kennst die Regeln, oder? Wenn du gegen uns verlierst, musst du die Kontrolle über die Camberwell Street abgeben."
  },
  AvgDialog_35997_Content_14 = {
    Text = "—Für immer."
  },
  AvgDialog_35997_Content_15 = {
    Text = "Hör auf zu trödeln! Wenn du kämpfen willst, dann los!"
  },
  AvgDialog_35997_Content_16 = {
    Text = "Quiek! Quiek! Quiek!"
  },
  AvgDialog_35997_Content_17 = {
    Text = "Sehr gut, hiermit erkläre ich offiziell, dass die 13. „Schlacht um Camberwell“ nun beginnt.\nBrüder—"
  },
  AvgDialog_35997_Content_18 = {
    Text = "<Big:Aufladung!!>"
  },
  AvgDialog_35997_Content_2 = {
    Text = "Künstlicher Bereich: Camberwell Straße, Ostbezirk"
  },
  AvgDialog_35997_Content_20 = {
    Text = "Autsch! Autsch... Es sind einfach zu viele..."
  },
  AvgDialog_35997_Content_21 = {
    Text = "<Shake:knarrend...>"
  },
  AvgDialog_35997_Content_22 = {
    Text = "Hmph! Das habt ihr davon, überall Ärger zu machen. Jetzt wisst ihr, wie stark wir sind!"
  },
  AvgDialog_35997_Content_23 = {
    Text = "Vorwärts, alle zusammen! Der Sieg ist zum Greifen nah—"
  },
  AvgDialog_35997_Content_24 = {Text = "Miau~"},
  AvgDialog_35997_Content_25 = {
    Text = "Ein wütender Schrei mit einem Hauch von Kindlichkeit unterbrach das kleine Scharmützel vor ihnen."
  },
  AvgDialog_35997_Content_26 = {
    Text = "Hört auf, Jenkin zu ärgern!"
  },
  AvgDialog_35997_Content_27 = {
    Text = "Katze... Katzenperson? Nein, das ist Schwester Mason?!"
  },
  AvgDialog_35997_Content_29 = {
    Text = "Bevor er reagieren konnte, erschienen drei rote Kratzspuren auf dem Gesicht des kleinen Mike."
  },
  AvgDialog_35997_Content_3 = {
    Text = "Ein trostloser, kalter Wind weht und wirbelt die welken Blätter auf."
  },
  AvgDialog_35997_Content_30 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35997_Content_31 = {
    Text = "<BigShake:Waaahhhh!!>"
  },
  AvgDialog_35997_Content_32 = {
    Text = "Kinder stoben in alle Richtungen davon. Das ohrenbetäubende Geschrei hallte bis in die übersehenen Ecken der Gassen."
  },
  AvgDialog_35997_Content_33 = {
    Text = "Hätte nie erwartet, eine 24 zu sehen, die wie eine Katze ist... Fräulein Mason, sollen wir rausgehen und nachsehen?"
  },
  AvgDialog_35997_Content_34 = {
    Text = "Niemand antwortete auf deine Bitte. Während des jüngsten Scharmützels war Mason spurlos verschwunden."
  },
  AvgDialog_35997_Content_35 = {
    Text = "Fräulein Mason...? Einfach gehen, ohne sich zu verabschieden?"
  },
  AvgDialog_35997_Content_36 = {
    Text = "*Schlürfen.*"
  },
  AvgDialog_35997_Content_37 = {
    Text = "Ein feuchtes Gefühl streift über die Seite meines Gesichts."
  },
  AvgDialog_35997_Content_38 = {
    Text = "Du drehst ungläubig den Kopf, nur um zu sehen, wie sich „24\" wie eine übergroße Puppe an dich klammert und dir ein schmeichelndes Lächeln schenkt."
  },
  AvgDialog_35997_Content_39 = {
    Text = "Miau, miau?"
  },
  AvgDialog_35997_Content_4 = {
    Text = "Little Mike stand mit einer Gruppe Kinder am Ende der Gasse. Die Hände in die Hüften gestemmt, war sein Gesichtsausdruck äußerst ernst."
  },
  AvgDialog_35997_Content_40 = {Text = "...?"},
  AvgDialog_35997_Content_41 = {
    Text = "Schnüffel, schnüffel... Da ist eine Ratte, miau!"
  },
  AvgDialog_35997_Content_43 = {
    Text = "Quiek Quiek@3!"
  },
  AvgDialog_35997_Content_44 = {
    Text = "Ein eisiger Schrei durchdringt den Himmel. Du schaust hinunter und siehst, wie „24\" Braun im Maul hält."
  },
  AvgDialog_35997_Content_45 = {
    Text = "<BigShake:Quiek Quiek Quiek Auuuu!>"
  },
  AvgDialog_35997_Content_46 = {
    Text = "Braun wand seinen weichen Körper heftig, wobei seine Schnurrhaare schnell zuckten."
  },
  AvgDialog_35997_Content_47 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35997_Content_48 = {
    Text = "Schnell, schnell! Schau, was ist das?"
  },
  AvgDialog_35997_Content_49 = {
    Text = "Jenkin hob geschickt eine Spiegelscherbe vom Boden auf und reflektierte sie auf die gegenüberliegende Wand."
  },
  AvgDialog_35997_Content_5 = {
    Text = "Tap. Tap. Tap."
  },
  AvgDialog_35997_Content_50 = {
    Text = "Im Nu erschienen intensive, flackernde Lichtpunkte auf der Steinwand und zogen erfolgreich die Aufmerksamkeit von „24\" auf sich."
  },
  AvgDialog_35997_Content_51 = {
    Text = "Glänzend Miau!"
  },
  AvgDialog_35997_Content_52 = {
    Text = "„24\" schoss mit einem Wusch davon und ließ Braun hemmungslos schluchzend an Ort und Stelle zurück."
  },
  AvgDialog_35997_Content_53 = {
    Text = "Wimmer... Quiek..."
  },
  AvgDialog_35997_Content_54 = {
    Text = "*seufz* Seit wir diesen Quacksalber aufgesucht haben, hat sich der Zustand meiner Schwester verschlechtert."
  },
  AvgDialog_35997_Content_55 = {
    Text = "Quacksalber? Du meinst Arzt Bernard?"
  },
  AvgDialog_35997_Content_56 = {
    Text = "Wer sonst? „Wunderarzt“ oder „Retter der Armen der Ostseite“? Pah!"
  },
  AvgDialog_35997_Content_57 = {
    Text = "Nichts im Leben ist umsonst. Ich wette, er führt etwas im Schilde..."
  },
  AvgDialog_35997_Content_58 = {
    Text = "Dr. Bernard ist ein guter Mensch, miau!"
  },
  AvgDialog_35997_Content_59 = {
    Text = "Ursprünglich dem Lichtpunkt hinterherjagend, lugte „24\" plötzlich hinter Jenkin hervor."
  },
  AvgDialog_35997_Content_6 = {
    Text = "Das Mädchen ging mit festen Schritten, der Wind hob ihren zerschlissenen Umhang."
  },
  AvgDialog_35997_Content_60 = {
    Text = "Schon gut, schon gut, er ist wirklich gut. Er ist der beste Arzt der Welt."
  },
  AvgDialog_35997_Content_61 = {
    Text = "Jenkin strich geschickt „24\"s Fell glatt.\n„24\" kniff die Augen zusammen und sah ziemlich zufrieden aus."
  },
  AvgDialog_35997_Content_62 = {
    Text = "Der kleine Jenkin ist auch ein guter Mensch, miau."
  },
  AvgDialog_35997_Content_63 = {
    Text = "Wann hat Fräulein Mason zum ersten Mal diese... eigenartigen Symptome gezeigt?"
  },
  AvgDialog_35997_Content_64 = {
    Text = "Nachdem sie diesen Quacksalber drei- oder viermal aufgesucht hatte, erzählte sie mir eines Tages plötzlich, dass sie eigentlich ein Silberdorsch sei."
  },
  AvgDialog_35997_Content_65 = {
    Text = "Später ersann sie einen Plan, das Fischbratrestaurant zu zerstören, und behauptete, es sei, um ihre Kameraden zu retten"
  },
  AvgDialog_35997_Content_66 = {
    Text = "<Gray:Verstehe. Ich habe dem Prüfungsausschuss zu sehr vertraut und die tatsächlichen Qualifikationen des Arztes übersehen.>"
  },
  AvgDialog_35997_Content_67 = {
    Text = "<Gray:Dieser Typ könnte wie Dr. Miller sein, ein Handlanger der Bildhauer...>"
  },
  AvgDialog_35997_Content_68 = {
    Text = "So müde, awuu..."
  },
  AvgDialog_35997_Content_69 = {
    Text = "„24\"streckte sich aus, machte eine lange, träge Dehnung und lehnte sich dann ganz natürlich an Jenkins Schulter."
  },
  AvgDialog_35997_Content_7 = {
    Text = "Du bist gekommen, wie versprochen. Allein?"
  },
  AvgDialog_35997_Content_70 = {
    Text = "Gurgle, gurgle..."
  },
  AvgDialog_35997_Content_71 = {
    Text = "Sie fiel in den Schlaf."
  },
  AvgDialog_35997_Content_72 = {
    Text = "Sie schnurrt wirklich wie eine Katze... genau wie die Katzen auf dem Misaq-Campus."
  },
  AvgDialog_35997_Content_73 = {
    Text = "Du hockst dich neugierig vor „24\"."
  },
  AvgDialog_35997_Content_74 = {
    Text = "Das Sonnenlicht badete gleichmäßig ihr Gesicht und ließ die feinen Härchen golden schimmern."
  },
  AvgDialog_35997_Content_75 = {
    Text = "Hey, worüber lachst du?!"
  },
  AvgDialog_35997_Content_76 = {
    Text = "Sie sieht jetzt glücklich aus, wirklich wie eine sorglose kleine Katze."
  },
  AvgDialog_35997_Content_77 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_35997_Content_78 = {
    Text = "Meine Schwester sagte immer, das Leben sei zu hart. Wenn sie wiedergeboren werden könnte, würde sie eine Katze werden wollen."
  },
  AvgDialog_35997_Content_79 = {
    Text = "Jenkin zog plötzlich ein rotes Band aus seiner Tasche. Es war Masons übliches Band, an dessen Ende eine rostige Glocke hing."
  },
  AvgDialog_35997_Content_8 = {Text = "Squeak!"},
  AvgDialog_35997_Content_80 = {
    Text = "Keine Sorge. Ob Katze oder Silberdorsch, sie sind alle meine Schwestern."
  },
  AvgDialog_35997_Content_81 = {
    Text = "Aber damit du nicht wegläufst, muss ich dir eine Glocke umbinden."
  },
  AvgDialog_35997_Content_82 = {
    Text = "Jenkin band das Band behutsam um „24\"s Handgelenk.\n„24\", noch immer schlafend, rümpfte nur leicht die Nase."
  },
  AvgDialog_35997_Content_83 = {
    Text = "Hier, das habe ich Wheatley und seiner Bande abgenommen. Achte darauf, dass du es sicher trägst."
  },
  AvgDialog_35997_Content_84 = {
    Text = "Die Nachmittagssonne fließt wie überlaufende Zeit sanft an dir vorbei. Jenkin betrachtet den von der Sonne gezeichneten, gefleckten Schatten des Hauses und schließt leise die Augen."
  },
  AvgDialog_35997_Content_85 = {
    Text = "Schwester ist sehr beschäftigt. Sie kümmert sich um mich und Braun, arbeitet gleichzeitig in mehreren Jobs, wie eine Maschine, die nie eine Störung hat."
  },
  AvgDialog_35997_Content_86 = {
    Text = "Jetzt, wo diese Maschine ausgefallen ist, bin ich endlich an der Reihe, mich darum zu kümmern."
  },
  AvgDialog_35997_Content_87 = {
    Text = "Sie braucht mich."
  },
  AvgDialog_35997_Content_9 = {
    Text = "Beeindruckend, du hast es gewagt, allein zu kommen. Du bist eine würdige Gegnerin."
  },
  AvgDialog_35999_Content_1 = {
    Text = "Bitterer Fluch"
  },
  AvgDialog_35999_Content_10 = {
    Text = "Ich erinnere mich an alles..."
  },
  AvgDialog_35999_Content_2 = {
    Text = "Gedenken strömen mit dem Sternenlicht herein."
  },
  AvgDialog_35999_Content_4 = {
    Text = "Jene Gedenken, künstlich erschaffen und durch Gewalt zerschmettert, strömten in Masons Geist und wichen dann rasch zurück wie die Gezeiten."
  },
  AvgDialog_35999_Content_5 = {
    Text = "Bis ganz zum Ende gelangte sie an den Fuß des Schneebergs, zum Eingang einer pechschwarzen Höhle."
  },
  AvgDialog_35999_Content_6 = {
    Text = "Folge dem Fluss, der unter deinen Füßen fließt, um das Lager des schlummernden Biests zu erreichen."
  },
  AvgDialog_35999_Content_7 = {
    Text = "Klopf, klopf. Klopf, klopf."
  },
  AvgDialog_35999_Content_8 = {
    Text = "Es war ein Herzschlag wie der einer alten Uhr, der gemeinsame Herzschlag zwischen ihr und der Bestie."
  },
  AvgDialog_35999_Content_9 = {
    Text = "Ich verstehe jetzt..."
  },
  AvgDialog_36227_Content_1 = {
    Text = "\"Der falsche Gott hat sich vollständig aus der zerbrechlichen, aber widerstandsfähigen Mutter befreit. Murphy wurde aus großer Höhe geworfen und krachte schließlich schwer auf das Deck."
  },
  AvgDialog_36227_Content_10 = {Text = "\"Silber\"."},
  AvgDialog_36227_Content_11 = {
    Text = "Murphy war nicht tot, aber ein Silber hatte sich bereits in ihr gebildet — das widerspricht dem, was du im Unterricht gelernt hast."
  },
  AvgDialog_36227_Content_12 = {
    Text = "Aber es bleibt keine Zeit zum Nachdenken. Getrieben von einem fast instinktiven Impuls ergreifst du Murphys Hand."
  },
  AvgDialog_36227_Content_13 = {
    Text = "Der silberne Schlüssel, der an deiner Brust hängt, gibt einen zitternden Klang von sich. Ein blendendes silbernes Licht bricht aus deinen gefalteten Händen hervor, hell genug, um jede Ecke zu erleuchten und jeden zu verschlingen."
  },
  AvgDialog_36227_Content_14 = {
    Text = "Zeit wird im Licht grenzenlos, und Seelen werden ununterbrochen in endloser Zeit komprimiert und gefaltet."
  },
  AvgDialog_36227_Content_15 = {
    Text = "In diesem ewigen Moment begleitet dich der Schmerz immer, drängt dich dazu, das Silber, das deine Handfläche durchbohrt, loszulassen."
  },
  AvgDialog_36227_Content_16 = {
    Text = "—Du hast abgelehnt. Der unerträgliche Schmerz drang gnadenlos in dein Bewusstsein ein, zertrümmerte das Gewebe in deinem Schädel. Das Blut, das in Klumpen geronnen war, strömte aus deinem Mund, deiner Nase und deinen Ohren."
  },
  AvgDialog_36227_Content_17 = {
    Text = "Du hast Murphys Seele immer festgehalten."
  },
  AvgDialog_36227_Content_18 = {
    Text = "Das Licht kollabiert zum Ursprung, und das gespenstische Flötenlied, das dich schläfrig macht, taucht wieder auf und fängt gewaltsam deine Aufmerksamkeit ein."
  },
  AvgDialog_36227_Content_19 = {
    Text = "Du fühlst deine Hand leer werden."
  },
  AvgDialog_36227_Content_2 = {
    Text = "Knochen zertrümmert bei Aufprall, die Brusthöhle wurde von selbst aufgerissen und weiter von dem auftauchenden \"Falschen Gott\" zertrümmert."
  },
  AvgDialog_36227_Content_20 = {
    Text = "Nachdem das silberne Licht verblasst, ist das Deck vor dir leer und hinterlässt nur Blutspuren."
  },
  AvgDialog_36227_Content_21 = {Text = "Hüter!?"},
  AvgDialog_36227_Content_22 = {
    Text = "Ramona zittert, während sie das Blut von der Ecke deines Auges wischt, aber es verwischt nur und lässt dein Gesicht mit Blutflecken bedeckt."
  },
  AvgDialog_36227_Content_23 = {Text = "Murphy..."},
  AvgDialog_36227_Content_24 = {
    Text = "Ramonas Schock und Fragen formten sich gerade, als ein tiefes Geräusch aus dem Bogen kam, wie das Murmeln eines Wesens aus dem Abgrund im Schlaf, das eine ominöse Atmosphäre trug."
  },
  AvgDialog_36227_Content_25 = {
    Text = "Ihr beide habt instinktiv eure Köpfe gewendet und gesehen, wie das Wesen namens \"Miryam\" den Gott mit fast fanatischer Hingabe anstarrte. Sie kniete am Bug des Schiffes, die Arme ausgestreckt in Richtung des falschen Gottes."
  },
  AvgDialog_36227_Content_26 = {
    Text = "Und diese zahllosen schwarzen Hände öffneten ihre Umarmung für sie. Sie umschlossen sanft ihre Taille und hoben die gläubige Anhängerin zu ihren Mündern."
  },
  AvgDialog_36227_Content_27 = {
    Text = "—<Red:Snap>."
  },
  AvgDialog_36227_Content_28 = {
    Text = "Im nächsten Moment ertönten nacheinander Geräusche des Kauens und Schluckens."
  },
  AvgDialog_36227_Content_29 = {
    Text = "Als ob es endlich von einer unbekannten Grenze des Schreckens befreit wurde, gab das Neugeborene ein schnurrendes Geräusch der Zufriedenheit von sich, als ob es das seltene Festmahl von \"Miryam\" verdauen würde."
  },
  AvgDialog_36227_Content_3 = {
    Text = "Wellen schlagen kontinuierlich auf das Deck, was die Blutlachen darunter wegspült, als ob sie jede Spur ihrer Existenz vollständig auslöschen würden."
  },
  AvgDialog_36227_Content_30 = {
    Text = "Der \"Neugeborene\" in der durchsichtigen schwarzen Kokon ähnelt einem großen, zerbrechlichen Primatenembryo. Seine Gliedmaßen zucken unbeholfen, als ob sie nach einer Richtung suchen, in die sie wachsen können—"
  },
  AvgDialog_36227_Content_31 = {
    Text = [[
Zeit bis zum Ausrichten: 
<Red:0> Minuten verbleibend]]
  },
  AvgDialog_36227_Content_4 = {
    Text = "Diese Art von Verletzung... können wir nicht bewältigen."
  },
  AvgDialog_36227_Content_5 = {
    Text = "\nMurphys Unterlippe zitterte noch, aber ihr Blick begann, unscharf zu werden.\nUnfähig, den Anblick dieser tragischen Szene zu ertragen, biss Ramona die Zähne zusammen und sah auf den \"falschen Gott\"."
  },
  AvgDialog_36227_Content_6 = {
    Text = "Hör auf damit. Wenn so ein massiver Clades-Kern nicht auf dem Schiff behandelt wird und an Land gelangt... die Konsequenzen werden unvorstellbar sein."
  },
  AvgDialog_36227_Content_7 = {
    Text = "Hüter, es ist Zeit zu handeln. Für Murphy's Wohl."
  },
  AvgDialog_36227_Content_8 = {
    Text = "Warte einen Moment! Ich könnte einen Weg haben."
  },
  AvgDialog_36227_Content_9 = {
    Text = "Du starrst aufmerksam auf das zerfetzte Gewebe unter Murphys Rippen, überzeugt davon, dass du dieses Ding gesehen hast—"
  },
  AvgDialog_36276_Content_1 = {
    Text = "Der äußere Teil... ist nicht seine wahre Gestalt?!"
  },
  AvgDialog_36276_Content_2 = {
    Text = "Das ist das, wonach Miryam strebt. Was sie sich sehnt, ist der „Gott“, der ihr die Wiederbelebung der Vergangenheit bringen kann..."
  },
  AvgDialog_36276_Content_3 = {
    Text = "Wir dürfen uns jetzt keine Nachlässigkeit leisten, nicht einmal für einen einzigen Moment!"
  },
  AvgDialog_36276_Content_4 = {
    Text = "Dieses hässliche Ding ist vollständig wach... Ich kann es fühlen."
  },
  AvgDialog_36277_Content_1 = {Text = "Hüter!"},
  AvgDialog_36277_Content_2 = {
    Text = "Tulu! Du bist endlich hier."
  },
  AvgDialog_36277_Content_3 = {
    Text = "Der Umgang mit Eltons Feinden dauerte eine Weile... <Small:Warte, Murphy?>"
  },
  AvgDialog_36277_Content_4 = {
    Text = "Tulus Augen gleiten vorbei am „Heiligen Kind“ und landen schließlich auf Murphy. Sie, die den Körper der Erwachenden besitzt, hat Tentakeln an ihrem Rock, die wild in der Luft wehen."
  },
  AvgDialog_36277_Content_5 = {
    Text = "......Seine Macht stammt aus derselben Quelle wie meine, was bedeutet, dass Er auch mein Verwandter ist. Obwohl ich Ihn nicht direkt befehlen kann, ist meine königliche Autorität, die von zehntausenden lemurischen Untertanen verehrt wird, unerreicht von irgendeinem gefälschten Gott."
  },
  AvgDialog_36277_Content_6 = {
    Text = "Die Gelegenheit klopft nur einmal. Nutze die Macht des Herren des Abgrundspirals... und entfessle die göttliche Vergeltung gegen Ihn!"
  },
  AvgDialog_37962_Content_1 = {
    Text = "Jetzt testen wir: Bildschirmeffekt - Dauerhaft Rot"
  },
  AvgDialog_37962_Content_10 = {
    Text = "Jetzt testen wir: Bildschirmeffekt - Sternenlicht"
  },
  AvgDialog_37962_Content_14 = {Text = "Ende"},
  AvgDialog_37962_Content_15 = {
    Text = "Jetzt testen wir: Bildschirmeffekt - Beleuchtung"
  },
  AvgDialog_37962_Content_19 = {Text = "Ende"},
  AvgDialog_37962_Content_20 = {
    Text = "Jetzt testen wir: Lauftext Typ 9"
  },
  AvgDialog_37962_Content_21 = {
    Text = "Frühling, Morgendämmerung. Die Berge erhellen sich, lila Wolken schweben.\nSommer, Nacht. Mit oder ohne Mond, Glühwürmchen tanzen. Regen verstärkt die Stimmung.\nHerbst, Dämmerung. Sonnenuntergang, Krähen kehren heim, melancholisch. Gänse fliegen in Formation, charmant. Nach Sonnenuntergang, Wind und Insekten.\nWinter, Morgen. Schnee oder Frost, kalte Luft, Feuer im Ofen, Kohlen durch den Flur tragen, passend. Mittags, Kohlen aschgrau, weniger reizvoll"
  },
  AvgDialog_37962_Content_22 = {Text = "Ende"},
  AvgDialog_37962_Content_5 = {Text = "Ende"},
  AvgDialog_37962_Content_6 = {
    Text = "Jetzt testen wir: Vergrößerungseffekt"
  },
  AvgDialog_37962_Content_7 = {
    Text = "Charakterbild vergrößern (1.5, 0.3)"
  },
  AvgDialog_37962_Content_8 = {
    Text = "Charakterbild zurücksetzen"
  },
  AvgDialog_37962_Content_9 = {
    Text = "Testende, tschü~"
  },
  AvgDialog_38725_Content_1 = {
    Text = "Ein schwacher blauer Schein umhüllt dich und vertreibt all deine Müdigkeit und deinen Schmerz."
  },
  AvgDialog_38725_Content_2 = {
    Text = "Der Vater Gott spendet dir \"Der Segen\"."
  },
  AvgDialog_38725_Content_3 = {
    Text = "Bischof Salvador!"
  },
  AvgDialog_38725_Content_4 = {
    Text = "Du bist der blasse Bote, die Flamme, die die Dunkelheit vertreibt."
  },
  AvgDialog_38725_Content_5 = {
    Text = "Du wirst all dieses Leiden beenden, und ich werde dir all die Hilfe bieten, die du brauchst."
  },
  AvgDialog_38727_Content_1 = {Text = "Blut Sigil"},
  AvgDialog_38727_Content_10 = {
    Text = "In der Tat, vielleicht... eine Sekte?"
  },
  AvgDialog_38727_Content_11 = {
    Text = "Szenen blitzen in deinem Kopf auf - ein Mädchen mit einem Dolch, eine Frau in einem schwarzen Schleier und ein Raum tief im Lai Krankenhaus, der niemals geöffnet werden kann..."
  },
  AvgDialog_38727_Content_12 = {
    Text = "Wie viele Organisationen wie <Yellow:Seefahrer> und <Yellow:Tempel Licht Kirche> gibt es in dieser Welt, und wie viele Menschen werden zu ihren Opfern?"
  },
  AvgDialog_38727_Content_13 = {
    Text = "Eure Exzellenz, hat Edward Ihnen etwas erwähnt?\nOb es sich um andere Religionen, alte Überzeugungen oder sogar Volkslegenden handelt."
  },
  AvgDialog_38727_Content_14 = {
    Text = "Salvador legte das Taschentuch nieder und wandte sich dir zu. Obwohl seine Augen mit Gaze bedeckt waren, kannst du dennoch seinen Blick spüren."
  },
  AvgDialog_38727_Content_15 = {
    Text = "Wenn ja, hast du vor, diese Angelegenheit zu untersuchen?"
  },
  AvgDialog_38727_Content_16 = {
    Text = "Ja. Ich... hatte Kontakt zu ähnlichen Organisationen und weiß, wie gefährlich sie sein können.\nWenn möglich, möchte ich nicht mehr Opfer sehen."
  },
  AvgDialog_38727_Content_17 = {
    Text = "Du hast eine strahlende Seele, %player%, warm, stark und bewundernswert.\nMöge das Licht des Vaters auf dir scheinen, wie es auf alle Mitglieder von <Yellow:Mythag> scheint."
  },
  AvgDialog_38727_Content_18 = {
    Text = "Woher hast du—"
  },
  AvgDialog_38727_Content_19 = {
    Text = "Der ehemalige Bischof war mein Freund. Er leitete die Kirche während Jahrzehnten und kannte viele Dinge"
  },
  AvgDialog_38727_Content_2 = {
    Text = "Die Holztür schließt sich langsam und schließt die Rufe der Verkäufer und das Getümmel der Menge aus. In der Stille kannst du nicht anders, als leise zu atmen."
  },
  AvgDialog_38727_Content_20 = {
    Text = "Ich werde mein Bestes tun, um dir zu helfen, aber ich fürchte, ich weiß nicht viel mehr als du."
  },
  AvgDialog_38727_Content_21 = {
    Text = "In der Tat war Edward nicht das erste Opfer dieser geheimnisvollen Religion."
  },
  AvgDialog_38727_Content_22 = {
    Text = "Vor einem halben Jahr wurde ein junger Mann namens Philip im Kirchenviertel wegen Mordes an seiner Frau zum Tode verurteilt."
  },
  AvgDialog_38727_Content_23 = {
    Text = "Als er zum ersten Mal inhaftiert wurde, besuchte ich ihn auf Einladung des Wärters.\nEr war blass, äußerst dünn und weigerte sich, mit irgendjemandem zu kommunizieren."
  },
  AvgDialog_38727_Content_24 = {
    Text = "Ich saß den ganzen Tag mit ihm zusammen, und als ich ging, sagte er die einzigen Worte, die er an diesem Tag gesprochen hatte."
  },
  AvgDialog_38727_Content_25 = {
    Text = "\"Hast du dieses schwarze <Red:Blut> gesehen?\""
  },
  AvgDialog_38727_Content_26 = {
    Text = "Vor der Exekution nahm er sich das Leben."
  },
  AvgDialog_38727_Content_27 = {
    Text = "Der gesamte Raum ist mit Blut bedeckt—auf dem Boden, den Wänden und der Decke. Allein dastehen reicht aus, um sich erdrückt zu fühlen. Unter den schweren Blutflecken entdeckte ich ein seltsames Symbol."
  },
  AvgDialog_38727_Content_28 = {
    Text = "Es ist flach und klein, als ob es mit einem Fingernagel gekratzt worden wäre. Hätte es nicht das Blut gegeben, das in die Ritze sickerte, wäre es vielleicht unbemerkt geblieben."
  },
  AvgDialog_38727_Content_29 = {
    Text = "Next to the symbol, there is a fainter mark."
  },
  AvgDialog_38727_Content_3 = {
    Text = "Eure Exzellenz, das Wasser ist angekommen."
  },
  AvgDialog_38727_Content_30 = {
    Text = "Das Zeichen ist schief, als ob es von jemandem geschnitzt wurde, der die Kraft verloren hat oder delirierend ist. Geleitet vom Vater erkannte ich es—es ist ein Wort."
  },
  AvgDialog_38727_Content_31 = {
    Text = "<Red: Reinigung>"
  },
  AvgDialog_38727_Content_32 = {
    Text = "Dieser Kult ist sehr vorsichtig und geschickt darin, sich zu verstecken. Hätte Edward heute nicht „Reinigung“ erwähnt, hätte ich nicht gewusst, dass er in ihre Fänge gefallen ist."
  },
  AvgDialog_38727_Content_33 = {
    Text = "Erinnerst du dich, wie dieses Symbol aussah? Vielleicht hat Mythag einige Aufzeichnungen darüber."
  },
  AvgDialog_38727_Content_34 = {
    Text = "Natürlich, strecke deine Hand aus."
  },
  AvgDialog_38727_Content_35 = {
    Text = "Er streckte einen Finger aus und zeichnete sanft ein einfaches Symbol auf deine Handfläche."
  },
  AvgDialog_38727_Content_36 = {Text = "Das...!"},
  AvgDialog_38727_Content_37 = {
    Text = "Du holst schnell dein Notizbuch aus der Tasche und kopierst das Muster, das Salvador gezeichnet hat."
  },
  AvgDialog_38727_Content_38 = {
    Text = "Mein Herr, was ist los? Was sind das für Symbole?"
  },
  AvgDialog_38727_Content_39 = {
    Text = "Umgekehrtes Dreieck, ein Punkt in der Mitte—"
  },
  AvgDialog_38727_Content_4 = {
    Text = "Vielen Dank, Ogier."
  },
  AvgDialog_38727_Content_40 = {
    Text = "Dies ist das Symbol der Tempellicht-Kirche."
  },
  AvgDialog_38727_Content_41 = {Text = "Bang!"},
  AvgDialog_38727_Content_42 = {
    Text = "Die Kirchentür wird plötzlich aufgerissen. Sophia, mit leicht zerzaustem Haar und keuchend, steht im Sonnenlicht, hält die Tür fest und schreit dich an."
  },
  AvgDialog_38727_Content_43 = {
    Text = "Bischof Salvador, etwas stimmt nicht! Die Leute draußen—"
  },
  AvgDialog_38727_Content_44 = {
    Text = "Blockiere nicht den Weg, lass uns rein!"
  },
  AvgDialog_38727_Content_45 = {
    Text = "Eine Hand schubst Sophia zur Seite und füllt die Kirche mit Rufen und Flüchen."
  },
  AvgDialog_38727_Content_46 = {
    Text = "Mehr als ein Dutzend Bürger strömten herein, einige mit Besen, andere mit Teigwalzen. Einer von ihnen schwang die Faust, noch mit Edwards Bissanfängen."
  },
  AvgDialog_38727_Content_47 = {
    Text = "Bring diesen Schurken Edward heraus! Wir haben eine Rechnung mit ihm zu begleichen!"
  },
  AvgDialog_38727_Content_5 = {
    Text = "Salvador nimmt ein sauberes Taschentuch aus seiner Tasche, taucht es in den Eimer, den Ogier mitgebracht hat, und wischt vorsichtig den Staub von Edward ab."
  },
  AvgDialog_38727_Content_6 = {
    Text = "Ein leicht feuchtes Tuch streift über seine Brust und lenkt deinen Blick auf seine auffällig sichtbaren Rippen — er ist viel zu dünn, als hätte er gerade eine große Hungersnot überlebt."
  },
  AvgDialog_38727_Content_7 = {
    Text = "<Small:...Sündiges... Blut... Reinigung...>"
  },
  AvgDialog_38727_Content_8 = {
    Text = "Bluten, Sünde... Obwohl du mit der <Blue:Leben Kirche> 's <Blue:\"Heiligen Schriften\"> nicht vertraut bist, passen diese blutigen Konzepte nicht zu deinem Eindruck dieser Religion"
  },
  AvgDialog_38727_Content_9 = {
    Text = "Dieses \"Unschuldig Land\" und \"Reinigung\"... scheinen nicht aus der \"Schrift\" zu stammen?"
  },
  AvgDialog_38729_Content_1 = {
    Text = "Entzünde die Weiße Hoffnung."
  },
  AvgDialog_38729_Content_10 = {
    Text = "Bitte... Lösche ihren Schmerz und beruhige ihre Herzen."
  },
  AvgDialog_38729_Content_100 = {
    Text = "Gewähre dem Sünder Vergebung, schenke ihnen \"Der Segen\"... Nach all diesen Jahren hast du dich wirklich nicht verändert, Bischof Salvador."
  },
  AvgDialog_38729_Content_101 = {
    Text = "Das Scheiterfeuer kann dich nicht verändern, noch kann die Auferstehung es. Wann wirst du endlich die Realität sehen? Vielleicht—"
  },
  AvgDialog_38729_Content_102 = {
    Text = "Sie streckt ihre Hand in die Luft, als würde sie etwas Unsichtbares berühren."
  },
  AvgDialog_38729_Content_103 = {
    Text = "Der prophezeite <Yellow:Schutzherr> mit der bleichen, doch warmen Seele kann mehr Variablen einbringen.\nGlaubt Ihr, {Male=he,Female=she} wäre bereit, sich uns anzuschließen?"
  },
  AvgDialog_38729_Content_104 = {
    Text = "Ein riesiger Hund trat aus den Schatten neben der Frau hervor, seine verzerrten Gliedmaßen erinnerten entfernt an die mutierte Sophia. Er schnaubt als Antwort auf die Worte der Frau."
  },
  AvgDialog_38729_Content_105 = {
    Text = "Nun, morgen ist immer ein neuer Tag."
  },
  AvgDialog_38729_Content_106 = {
    Text = "Lass uns gehen, mein Lieber. Wenn wir die Gelegenheit bekommen, werden wir sie wieder treffen."
  },
  AvgDialog_38729_Content_11 = {
    Text = "Die Augen der Menschen werden leer, ihre Körper entspannen sich. Panik und Angst verschwinden, ersetzt durch Ruhe und Gelassenheit."
  },
  AvgDialog_38729_Content_12 = {
    Text = "Befreie sie von den Qualen des Leidens und gewähre ihnen \"Der Segen\"."
  },
  AvgDialog_38729_Content_13 = {
    Text = "Das sich auftürmende Licht schwoll an, und jeder schloss die Augen, als ob er in Ruhe eingetaucht wäre."
  },
  AvgDialog_38729_Content_14 = {
    Text = "Die warme Sonne blickt auf alles herab. Alles scheint normal zu sein, bis auf den chaotischen Platz, der Zeuge des jüngsten Wahnsinns ist."
  },
  AvgDialog_38729_Content_15 = {
    Text = [[
Das Tablet klickte sanft und verschwand in den unsichtbaren Schatten der Nacht.
Salvador richtete seine Kleidung und ging zu Sofias Seite.]]
  },
  AvgDialog_38729_Content_16 = {
    Text = "...Du hättest mich nicht retten sollen."
  },
  AvgDialog_38729_Content_17 = {
    Text = "\"Alle, die ihren Weg zurückfinden, können in meine Umarmung zurückkehren.\""
  },
  AvgDialog_38729_Content_18 = {
    Text = "„Denn ihr seid alle meine Kinder, und ich liebe euch alle.\"\nAber Ihr irrt Euch, Läufer, und die „Heilige Schrift\" ebenso."
  },
  AvgDialog_38729_Content_19 = {
    Text = "Einige Menschen ändern sich niemals."
  },
  AvgDialog_38729_Content_2 = {
    Text = "Das Tablet hebt sich erneut."
  },
  AvgDialog_38729_Content_20 = {
    Text = "Was bringt dich hierher?"
  },
  AvgDialog_38729_Content_21 = {
    Text = "Sophia, ich—"
  },
  AvgDialog_38729_Content_22 = {
    Text = "Halt die Klappe! Reicht es nicht, dass du den Tod meiner Schwester und Mutter verursacht hast? Kommst du jetzt zu ihren Gräbern, um dich zu rühmen?!"
  },
  AvgDialog_38729_Content_23 = {
    Text = "Ich bin hier, um mich zu entschuldigen. Ich habe nicht erwartet..."
  },
  AvgDialog_38729_Content_24 = {
    Text = "Sophia lachte scharf."
  },
  AvgDialog_38729_Content_25 = {
    Text = "Hast du dich bei <Blue:Thompson> so entschuldigt, nachdem du den Tod seines einzigen Familienmitglieds und <Blue:Millie> verursacht hast?"
  },
  AvgDialog_38729_Content_26 = {
    Text = "Du ekelst mich an, Edward Bailey."
  },
  AvgDialog_38729_Content_27 = {
    Text = "Ich bereue es wirklich, was ich getan habe, Sophia. Ich weiß, dass ich deine Vergebung nicht verdienen kann—"
  },
  AvgDialog_38729_Content_28 = {
    Text = "Wenn du es wirklich bereust, hättest du am Tag, an dem Thompson dich getötet hat, nicht zu Bischof Salvador gehen sollen."
  },
  AvgDialog_38729_Content_29 = {
    Text = "Ja, ich weiß, wie du überlebt hast, du Feigling. <Yellow:Laterne> hat es mir gesagt."
  },
  AvgDialog_38729_Content_30 = {
    Text = "Die Entscheidung des Bischofs, dir \"<Yellow:Segnen>\" zu gewähren, war sein törichtester Fehler. Du verdienst es zu sterben, Bailey, gefoltert zu Tode."
  },
  AvgDialog_38729_Content_31 = {
    Text = "Ich wollte das auch nicht. Ich habe versucht, mich zu beherrschen, wirklich! Nachdem der Läufer mich gerettet hat, habe ich mich jeden Tag bei der Kirche gemeldet und wöchentlich bei deiner Wohltätigkeitsorganisation geholfen. Erinnerst du dich?"
  },
  AvgDialog_38729_Content_32 = {
    Text = "Ich möchte besser werden, das will ich wirklich. Es war dieser Aglo-Typ – er sagte, es sei ein narrensicherer Deal und bat mich, einen Bürgen einzuführen. Ich bin auch ein Opfer!"
  },
  AvgDialog_38729_Content_33 = {
    Text = "Sogar jetzt weichst du noch deiner Verantwortung aus. Sogar jetzt... hast du dich nicht wirklich gewandelt."
  },
  AvgDialog_38729_Content_34 = {
    Text = "Sie nahm einen silbernen Gegenstand aus der inneren Tasche ihres Rocks. Seine glatte Oberfläche schimmerte schwach im Sonnenlicht und warf einen ominösen rötlichen Schein."
  },
  AvgDialog_38729_Content_35 = {Text = "Sophia...?"},
  AvgDialog_38729_Content_36 = {Text = "Bereue."},
  AvgDialog_38729_Content_37 = {
    Text = "Folge den Lehren des gerechten Lichtbringers und läutere die Sünden in deiner Seele.\nNur dann kannst du Vergebung erlangen."
  },
  AvgDialog_38729_Content_38 = {
    Text = "Was bist du?"
  },
  AvgDialog_38729_Content_39 = {
    Text = "Ich... Ich bin Edward..."
  },
  AvgDialog_38729_Content_4 = {
    Text = "Salvador hob seine Hand, Blut floss kontinuierlich von seinem Körper und seiner Umgebung zur Tafel. Bläuliches Licht strömte erneut entlang der Linien, hell und dunkel, wie ein Atemzug."
  },
  AvgDialog_38729_Content_40 = {
    Text = [[
Der Spiegel blitzt auf, und die Augen des knienden jungen Mannes wurden erneut benommen.
Zitternd hob er den Stock in seiner Hand und schlug sich selbst hart.]]
  },
  AvgDialog_38729_Content_41 = {
    Text = "Ich frage noch einmal: Was bist du?"
  },
  AvgDialog_38729_Content_42 = {
    Text = "Ich bin ein Sünder."
  },
  AvgDialog_38729_Content_43 = {
    Text = "Welche Sünde hast du begangen?"
  },
  AvgDialog_38729_Content_44 = {
    Text = "Gier... Begierde... Ich habe zugelassen, dass das Böse meine Seele befleckt, und dann Unschuldigen Leid zugefügt."
  },
  AvgDialog_38729_Content_45 = {
    Text = "Was solltest du tun?"
  },
  AvgDialog_38729_Content_46 = {
    Text = "Reue vor den Göttern und jenen, denen ich Unrecht getan habe...\nIch muss die Peitsche erdulden, bluten, bis die schwarze Sünde herausfließt, bis die <Red:Läuterung> erlangt ist."
  },
  AvgDialog_38729_Content_47 = {
    Text = "Der Tag des Gerichtes naht. Nur reine Seelen dürfen das Unschuldig Paradies betreten."
  },
  AvgDialog_38729_Content_48 = {
    Text = "<Red: Möge die Laterne brennen bleiben.>"
  },
  AvgDialog_38729_Content_49 = {
    Text = "So wie du, selbst nach zwei Leben, immer noch dieselben Fehler gemacht hast."
  },
  AvgDialog_38729_Content_5 = {
    Text = "All-Vater des Ursprungs, unser barmherziger Schöpfer, bitte erhöre mein Gebet."
  },
  AvgDialog_38729_Content_50 = {
    Text = "...Wie hast du das gewusst?"
  },
  AvgDialog_38729_Content_51 = {
    Text = "Ist es wichtig?\nDeine Sünde des Hochmuts ist so tief, Bischof. Deine Seele muss völlig schmutzig sein."
  },
  AvgDialog_38729_Content_52 = {
    Text = "Sag mir, Sünder, warum bereust du nicht die Sünden, gegen die du predigst?"
  },
  AvgDialog_38729_Content_53 = {
    Text = "...weil das kein Verbrechen ist."
  },
  AvgDialog_38729_Content_54 = {
    Text = "Die Relikte des Vaters tragen immer Sein Licht. Jeder kann geblendet werden, aber ebenso leicht kann jeder das Licht des Vaters wiederentdecken."
  },
  AvgDialog_38729_Content_55 = {
    Text = "Wir können jemandem nicht sein ganzes Leben wegen einer einzigen momentanen Handlung nehmen."
  },
  AvgDialog_38729_Content_56 = {
    Text = "Du sagst das, aber hast du jemals an die gedacht, die durch sie geschädigt wurden?"
  },
  AvgDialog_38729_Content_57 = {
    Text = "Wenn diese Edwards das Licht zurückgewinnen, wie viele Millies müssen geopfert werden? Wie viele Olivias?"
  },
  AvgDialog_38729_Content_58 = {
    Text = "Sünde ist Sünde, und falsch ist falsch. Einmal begangen, gibt es kein Zurück."
  },
  AvgDialog_38729_Content_59 = {
    Text = "Sie blickt zu dir."
  },
  AvgDialog_38729_Content_6 = {
    Text = "Feuchte blaue Tentakeln strahlen von der Tafel aus, durchqueren die Menge und vertreiben den verbleibenden Blutduft, hinterlassen einen schwachen Duft"
  },
  AvgDialog_38729_Content_60 = {
    Text = "Nehmt mich mit, werft mich in eure korrupten Gesetze. Aber denk daran, der Tag des Gerichts wird kommen."
  },
  AvgDialog_38729_Content_61 = {
    Text = "Zu diesem Zeitpunkt werdet ihr alle aus dem Unschuldigen Land verbannt."
  },
  AvgDialog_38729_Content_62 = {
    Text = "Der Spiegel wurde gesichert, Schutzherr. Die betroffenen Zivilisten wurden in die großen Krankenhäuser gebracht und werden nach Untersuchungen entlassen."
  },
  AvgDialog_38729_Content_63 = {
    Text = "Die offizielle Erklärung lautet, dass dies ein Massenhalluzinationsereignis war, verursacht durch ein Leck von giftigem Gas in der Fabrik. Die Stadtregierung wird morgen eine öffentliche Entschuldigung aussprechen und disziplinarische Maßnahmen gegen die verantwortlichen Personen ergreifen."
  },
  AvgDialog_38729_Content_64 = {
    Text = "Ich verstehe. Danke für Ihre harte Arbeit."
  },
  AvgDialog_38729_Content_65 = {
    Text = "Dies ist das, was wir tun sollten."
  },
  AvgDialog_38729_Content_66 = {
    Text = "Der junge Mann in Uniform zögert einen Moment, dann sprach er:"
  },
  AvgDialog_38729_Content_67 = {
    Text = "Wie hast du das geschafft?"
  },
  AvgDialog_38729_Content_68 = {Text = "Was?"},
  AvgDialog_38729_Content_69 = {
    Text = "Die Lage war so chaotisch, und dennoch haben Sie allein mit einem Erweckten Körper die Opferzahl auf etwa ein Dutzend begrenzt — fast ein Wunder."
  },
  AvgDialog_38729_Content_7 = {
    Text = "Die stehenden Menschen setzten sich langsam hin."
  },
  AvgDialog_38729_Content_70 = {
    Text = "Du und Ogier tauscht einen schnellen Blick aus. Der junge Ritter räuspert sich leicht mit den Händen hinter dem Rücken."
  },
  AvgDialog_38729_Content_71 = {
    Text = "Das ist wahrscheinlich das unausgesprochene Verständnis zwischen meinem Herrn und mir."
  },
  AvgDialog_38729_Content_72 = {
    Text = "Dennoch spreche ich dir im Namen des Ersten Reaktionsteams des Ausschusses meinen Dank aus. \nInmitten der Krise hast du unser Volk nicht verlassen, sodass sie sicher nach Hause zurückkehren konnten. Darüber hinaus..."
  },
  AvgDialog_38729_Content_73 = {
    Text = "Viele von uns sind hier aufgewachsen; der Kirchenbezirk bedeutet uns viel.\nDanke für alles, was du getan hast."
  },
  AvgDialog_38729_Content_74 = {
    Text = "Das sollten wir tun."
  },
  AvgDialog_38729_Content_75 = {
    Text = "Es gibt nie zu viel Dankbarkeit."
  },
  AvgDialog_38729_Content_76 = {
    Text = "Fräulein Sophia... Was wird aus ihr?"
  },
  AvgDialog_38729_Content_77 = {
    Text = "Wir werden sie verhören. Wir werden über sie urteilen, nachdem wir herausgefunden haben, woher der Spiegel stammt."
  },
  AvgDialog_38729_Content_78 = {
    Text = "Das ketzerische Ritual hat weitreichendes Chaos und zahlreiche Opfer verursacht... Der Läufer hofft, dass sie nicht zum Tode verurteilt wird, aber ich bin nicht optimistisch."
  },
  AvgDialog_38729_Content_79 = {
    Text = "Was sie erwartet, wird kein gutes Ende nehmen."
  },
  AvgDialog_38729_Content_8 = {
    Text = "Die dort Sitzenden starren mit offenem Mund auf die wundersame Szene vor ihnen."
  },
  AvgDialog_38729_Content_80 = {
    Text = "Bischof Salvador."
  },
  AvgDialog_38729_Content_81 = {Text = "Gehst du?"},
  AvgDialog_38729_Content_82 = {
    Text = "Ja. Danke für Eure Hilfe bei diesem Vorfall."
  },
  AvgDialog_38729_Content_83 = {
    Text = "Das alles begann wegen mir, und du hast sogar meine Identität geheim gehalten. Ich sollte dir danken."
  },
  AvgDialog_38729_Content_84 = {
    Text = "Kommst du wirklich nicht mit uns zurück?"
  },
  AvgDialog_38729_Content_85 = {
    Text = "Mach dir keine Sorgen um die Pfarrei. Solange die Bedingungen stimmen, erlauben wir es Wachenden, frei zu handeln."
  },
  AvgDialog_38729_Content_86 = {
    Text = "Danke für Ihre Freundlichkeit, aber ich würde lieber hier bleiben."
  },
  AvgDialog_38729_Content_87 = {
    Text = "Der Vatergott hat mich hierher zurückgerufen, vermutlich in der Hoffnung, dass ich mehr Menschen helfen kann.\nWenn du Bedarf hast, <Yellow:Das Blasse Feuer>, komm jederzeit zu mir. Ich werde mein Bestes für dich geben."
  },
  AvgDialog_38729_Content_88 = {
    Text = "Es tut mir leid, aber... Was genau sind der <Yellow:Pale Messenger> und das <Yellow:Pale Fire>?"
  },
  AvgDialog_38729_Content_89 = {
    Text = "Es ist die Prophezeiung des Vaters in der Schrift."
  },
  AvgDialog_38729_Content_9 = {
    Text = "Jene, die das Bewusstsein verloren hatten oder sogar aufgehört hatten zu atmen, öffneten langsam ihre Augen in der sanften Brise."
  },
  AvgDialog_38729_Content_90 = {
    Text = "Grenzenlose Dunkelheit wird über die Welt hereinbrechen, die bleiche und warme Seele ist die Botin der Hoffnung, {Male=he,Female=she} wird die weiße Flamme entzünden, um den Weg nach vorn zu erhellen."
  },
  AvgDialog_38729_Content_91 = {
    Text = "Das kann unmöglich ich sein, oder? Es gibt so viele Menschen auf der Welt."
  },
  AvgDialog_38729_Content_92 = {
    Text = [[
Auch wenn meine Augen bedeckt sind, kann ich die Brillanz einer Seele nicht verkennen.
Deine ist so warm und hell. In all diesen Jahren habe ich noch nie eine andere wie sie gesehen.]]
  },
  AvgDialog_38729_Content_93 = {
    Text = "Der junge Schutzherr dreht sich um und geht. Salvador beobachtet das Schimmern und flüstert ein Gebet, als die Tür sich ein letztes Mal öffnet."
  },
  AvgDialog_38729_Content_94 = {
    Text = "Mögest du die Dunkelheit mit schwacher Hoffnung erleuchten."
  },
  AvgDialog_38729_Content_95 = {
    Text = "<Yellow:Bericht über anomale Ereignisse im Londinium Kirche Bezirk>\n\nA.F. 315 @2@3, Londinium großer Kirchenbezirk, brach plötzlich ein gewalttätiger Vorfall auf dem Platz vor der Londinium Kirche der ewigen Segnungen des Vaters aus. Die anwesenden Bürger zeigten schweres gewalttätiges Verhalten und Selbstverletzungen, was eine normale Kommunikation unmöglich machte.\n......\nDas abnormale Verhalten verschlechterte sich, nachdem eine unbekannte Lichtquelle flackerte, und eskalierte in großangelegte kannibalistische Handlungen. Ermittlungen ergaben, dass die unbekannte Lichtquelle tatsächlich ein Handspiegel aus poliertem reinem Silber war. Dieser Spiegel sammelt Energie, indem er Sonnenlicht und Mondlicht reflektiert; Personen, die den Reflexionen des Spiegels ausgesetzt sind, werden von ihren stärksten inneren Wünschen getrieben, einschließlich, aber nicht beschränkt auf Gewalt, Gier und Schläfrigkeit, was zu extremen Handlungen führt.\nDer Spiegel wurde von Hüter %player% und Erwacher Ogier sichergestellt. Vorläufige Analysen zeigen, dass er Silber oder silberähnliche Bestandteile enthält. Für weitere Details verweisen wir auf den speziellen Ausrüstungsforschungsbericht, der vom Fachbereich für spezielle Ausrüstungsforschung an der Mythag Universität bereitgestellt wurde.\n......"
  },
  AvgDialog_38729_Content_96 = {
    Text = "Bei der Befragung durch den Mystia-Vertragsausschuss gab <Yellow:Sophia Chastain> zu, vor drei Jahren der Kirche des Tempel Lichts beigetreten zu sein und während der letzten Kirchenveranstaltung einen Ritualspiegel vom Kirchenführer, Tempel Licht (nämlich <Yellow:Ms. Eve>), erhalten zu haben.\nAls der Agent sie weiter befragte, begann Sophia Chastain leise zu beten und gab keine weiteren Antworten.\n......"
  },
  AvgDialog_38729_Content_97 = {
    Text = "Die untergehende Sonne vertreibt den letzten Dunst am Himmel. Die Kirchenglocke läutet, und die Schiffssirene ertönt am Flussdock."
  },
  AvgDialog_38729_Content_98 = {
    Text = "Auf dem Dach eines hohen Gebäudes steht eine umhulte Gestalt allein mit dem Rücken zur Sonne."
  },
  AvgDialog_38729_Content_99 = {
    Text = "Selbst nach der Opferung der mutierten Sünder erschien kein <Red:Stigmata>.\nEs scheint, der Wert <Yellow:dieser Spiegel> ist genau so."
  },
  AvgDialog_38841_Content_1 = {Text = "Ugh!"},
  AvgDialog_38841_Content_10 = {Text = "Mein Herr!"},
  AvgDialog_38841_Content_12 = {
    Text = "Im nächsten Moment fiel eine riesige Tafel vor dir zu Boden"
  },
  AvgDialog_38841_Content_13 = {
    Text = "Die verzweifelt auf dich losstürmenden Menschen, das Blut, das sich ausbreitet, das chaotische, erschreckende Geschrei... alles ist hinter der Tafel abgeschnitten"
  },
  AvgDialog_38841_Content_14 = {
    Text = "Eine Hand in einem schwarzen Handschuh legt sich auf deinen Unterarm, das kühle Material lindert den Schmerz und wischt das Blut weg"
  },
  AvgDialog_38841_Content_15 = {
    Text = "Die Person, die dich gebissen hat, ist weg. Ein Priester in schwarzer Robe hält deinen Arm"
  },
  AvgDialog_38841_Content_16 = {
    Text = "Hinter ihm schwebten vier Steintafeln, jede mit komplizierten Runen, die in blauem Licht leuchteten, wie verkleinerte Galaxien"
  },
  AvgDialog_38841_Content_17 = {
    Text = "Ein blauer Lichtstrahl fließt seinen Arm entlang zu dir. Du schaust auf deinen Unterarm, die Bisswunde hat aufgehört zu bluten und heilt sogar vor deinen Augen"
  },
  AvgDialog_38841_Content_18 = {
    Text = "Salvador... Bischof?"
  },
  AvgDialog_38841_Content_2 = {
    Text = "Stumpfe Zähne bissen in die Kleidung und zogen daran. Der Mensch war völlig vom Hunger getrieben und biss heftig in deinen Arm"
  },
  AvgDialog_38841_Content_3 = {Text = "Mein Herr!"},
  AvgDialog_38841_Content_4 = {
    Text = "Als deine Bewegungen eingeschränkt waren, schauten auch die anderen hungrigen Menschen um dich herum zu dir"
  },
  AvgDialog_38841_Content_5 = {
    Text = "Tötet sie! Sonst kommen sie immer wieder, tötet sie schnell!"
  },
  AvgDialog_38841_Content_6 = {
    Text = "Viele rote Augen starren dich an, viele Hände greifen nach dir, gefolgt von weit aufgerissenen Mündern und weißen Zähnen"
  },
  AvgDialog_38841_Content_7 = {
    Text = "Ogiers Schrei wurde endlos verlängert"
  },
  AvgDialog_38841_Content_8 = {
    Text = "Du hörst das Reißen von Stoff"
  },
  AvgDialog_38841_Content_9 = {
    Text = "Die Hitze kommt wieder, dann ein stechender Schmerz, du weißt, dass der Angreifer endlich deine Hand gebissen hat"
  },
  AvgDialog_38842_Content_1 = {
    Text = "Unser Fehler"
  },
  AvgDialog_38842_Content_10 = {
    Text = "Herr... Meister"
  },
  AvgDialog_38842_Content_11 = {
    Text = "So rot, warum ist es so rot? Überall ist tiefes Rot, es erdrückt dich. Du musst dieses Licht verlassen, du musst weg"
  },
  AvgDialog_38842_Content_12 = {
    Text = "Ein wenig kühl, dann der Weihrauch der Kirche"
  },
  AvgDialog_38842_Content_13 = {
    Text = "Das blaue Licht erhellte einen Teil der Dunkelheit, du öffnest plötzlich die Augen und stellst fest, dass Ogier vor dir kniet, während schwarze Flüssigkeit aus seinem Mundwinkel läuft"
  },
  AvgDialog_38842_Content_14 = {
    Text = "Genau wie beim Kettentraining mit ihm"
  },
  AvgDialog_38842_Content_15 = {Text = "Ogier!"},
  AvgDialog_38842_Content_16 = {
    Text = "Du konzentrierst dich schnell, der silberne Schlüssel vibriert leicht an deiner Brust. Nach einem kurzen silbernen Blitz steht Ogier wieder auf"
  },
  AvgDialog_38842_Content_17 = {
    Text = "Reinigen, <Big:Reinigen!>"
  },
  AvgDialog_38842_Content_18 = {
    Text = "Der Handspiegel wurde heller, du wolltest deine Augen schützen, als ein Schatten vor dir auftauchte"
  },
  AvgDialog_38842_Content_19 = {
    Text = "Der riesige Steinblock schwebte vor dir, die komplexen Runen leuchteten mit einem blauen Licht, aber sie waren schon viel schwächer als zuvor"
  },
  AvgDialog_38842_Content_2 = {
    Text = "Der Blutmond hängt hoch am Himmel, sein purpurnes Licht wirkt als der stärkste Katalysator."
  },
  AvgDialog_38842_Content_20 = {
    Text = "Du drehst dich um, aber Salvador ist nicht mehr zu sehen"
  },
  AvgDialog_38842_Content_21 = {
    Text = "Ogier, hol den Spiegel"
  },
  AvgDialog_38842_Content_22 = {
    Text = "Aber, mein Herr, du—"
  },
  AvgDialog_38842_Content_23 = {
    Text = "Ich kann auf mich selbst aufpassen. Der Läufer hat uns wenig Zeit verschafft, beeile dich!"
  },
  AvgDialog_38842_Content_24 = {Text = "Ja!"},
  AvgDialog_38842_Content_3 = {
    Text = "Raufereien eskalieren zu brutalen Prügeleien, Selbstverletzung steigert sich zum Suizid, jene, die aktiv den Tod suchen, beenden ihr Leben auf unvorstellbar gewaltsame Weise."
  },
  AvgDialog_38842_Content_4 = {
    Text = "Der metallische Geruch von Blut überlagert den verbleibenden Weihrauch vollständig. Im roten Licht erscheint das verspritzte Blut schwarz wie Tinte, und die dem Wahnsinn Verfallenen gleichen monströsen Teufeln, wie man sie nur in Albträumen sieht."
  },
  AvgDialog_38842_Content_5 = {
    Text = "In dieser Hölle auf Erden ist nur Sophias Kleid noch sauber. Sie wischt das Blut von ihrem Gesicht und lacht laut"
  },
  AvgDialog_38842_Content_6 = {
    Text = "Fließt, lasst eure Sünden aus euren Körpern fließen! Lasst die schwarze Schuld fließen!"
  },
  AvgDialog_38842_Content_7 = {
    Text = "Bereut, ihr Sünder! Reinigt eure schmutzigen Seelen, bevor der strenge Lichtbringer sein Urteil fällt!"
  },
  AvgDialog_38842_Content_8 = {
    Text = "Während sie den Spiegel hält, flackert ein purpurnes Licht, das durchdringend deine Augen durchbohrt, direkt in deinen Geist und deine Seele."
  },
  AvgDialog_38842_Content_9 = {
    Text = "Etwas zieht sich immer enger zusammen, was ist das? Es tut weh, ich will mich übergeben"
  },
  AvgDialog_38843_Content_1 = {
    Text = "Reinige die Sünden"
  },
  AvgDialog_38843_Content_10 = {
    Text = "*Hust, würg*, eine Lache Flüssigkeit spritzt auf den Boden.\nDer Geruch von Blut wird noch stärker."
  },
  AvgDialog_38843_Content_11 = {
    Text = "Jetzt ist sie tot... <Blue:Milly> ist tot...! <Blue:Thompson> dieser Verrückte will, dass ich mit ihr sterbe. Ich... ich will nicht sterben, Bischof, aber ich"
  },
  AvgDialog_38843_Content_12 = {
    Text = "Entschuldigung, Entschuldigung... vergib mir, Bischof, nur der Vater kann mir vergeben, nur der Vater"
  },
  AvgDialog_38843_Content_13 = {
    Text = "...„Diejenigen, die Fehler gemacht haben, wird Er auch umarmen, solange sie aufrichtig bereuen.“"
  },
  AvgDialog_38843_Content_14 = {
    Text = "Ein schwaches blaues Licht scheint nach oben und erleuchtet Teile des Buntglasfensters. Der Gottvater auf dem Fenster blickt still herab, so wie Er es seit Jahrhunderten getan hat."
  },
  AvgDialog_38843_Content_15 = {
    Text = "Unter Salvadors Hand heilen die Verletzungen des jungen Mannes rasch, als wäre er nie verletzt gewesen."
  },
  AvgDialog_38843_Content_16 = {
    Text = "Öffne deine Augen, Edward, und schätze die Gelegenheit, die dir vom Vater gewährt wurde."
  },
  AvgDialog_38843_Content_17 = {
    Text = "Blaues Licht schlängelt sich wie eine Schlange über deinen Körper, und alle Schmerzen und Müdigkeit verschwinden.\nDu fühlst dich leicht und voller Energie"
  },
  AvgDialog_38843_Content_18 = {
    Text = "Bischof Salvador... ist..."
  },
  AvgDialog_38843_Content_19 = {
    Text = "Die Runen auf der Tafel blitzen regelmäßig wie ein Atemzug, mehr bläuliches Licht breitet sich wie die Wurzeln eines riesigen Baumes in alle Himmelsrichtungen aus. Unzählige Schäden und Todesfälle, das Weinen und Klagen, finden in diesem plötzlichen Wunder Erleichterung"
  },
  AvgDialog_38843_Content_2 = {
    Text = "Bischof... Bischof Salvador..."
  },
  AvgDialog_38843_Content_20 = {
    Text = "Der Duft des Räucherwerks in der Kirche streift leicht über deine Nasenspitze, sanft und schwach, als ob er nicht existierte, aber gleichzeitig den Duft des Blutes vollständig überdeckt"
  },
  AvgDialog_38843_Content_21 = {
    Text = "...ein Erwecker."
  },
  AvgDialog_38843_Content_22 = {
    Text = "Er drehte sich plötzlich um und wollte in deine Hand beißen. Seine Zähne kamen mit heißem Atem näher an deinen Arm, deine Haare standen zu Berge, und du bereitest dich auf den Schmerz vor"
  },
  AvgDialog_38843_Content_23 = {
    Text = "Plötzlich legte sich eine schwarz behandschuhte Hand auf deinen Arm"
  },
  AvgDialog_38843_Content_24 = {
    Text = "Die kühle Stofflichkeit und der beruhigende Duft des Kirchenrauchs breiten sich aus"
  },
  AvgDialog_38843_Content_25 = {
    Text = "Hast du mich damals auch so geheilt?\nIst das... deine Fähigkeit?"
  },
  AvgDialog_38843_Content_26 = {
    Text = "Salvador sah dich an, sein Blick durch den weißen Verband war dennoch sanft, sogar mitleidig"
  },
  AvgDialog_38843_Content_27 = {
    Text = "Du hast diese Sünder wieder einmal gerettet."
  },
  AvgDialog_38843_Content_28 = {
    Text = "Eine kalte Stimme unterbricht dich, du drehst dich um und siehst erwartungsgemäß Sophia"
  },
  AvgDialog_38843_Content_29 = {
    Text = "Du bist unter dem <Yellow:„Segen“>, hast eine Kraft, die gewöhnlichen Menschen fehlt, doch du weißt nur, diese sündhaften Seelen ungestraft walten zu lassen und ihr Leid zu verbreiten"
  },
  AvgDialog_38843_Content_3 = {Text = "Edward?"},
  AvgDialog_38843_Content_30 = {
    Text = "Du bist der größte Sünder hier, Salvador. Ich schwöre, dich deine Sünden erkennen zu lassen"
  },
  AvgDialog_38843_Content_31 = {
    Text = "Miss Sophia, worüber redest du eigentlich?"
  },
  AvgDialog_38843_Content_32 = {
    Text = "Verstehst du nicht? Dieser Bischof vor euch, dieser scheinheilige Missbraucher göttlicher Macht, verbirgt seine Identität und rettet immer wieder die Schuldigen vor dem Tod"
  },
  AvgDialog_38843_Content_33 = {
    Text = "Er gab ihnen immer wieder Chancen im Namen der Barmherzigkeit, ließ die Gerechten immer wieder leiden – das darf nicht so weitergehen"
  },
  AvgDialog_38843_Content_34 = {
    Text = "<Yellow:Die Laterne> führte mich, <Yellow:der Lampenträger aus reinem Silber> gab mir die Mission, das Lichtgericht zu beginnen"
  },
  AvgDialog_38843_Content_35 = {
    Text = "Sie hebt die Hand, richtet einen seltsam geformten Handspiegel auf den Nachthimmel, und das Sonnenlicht wird blutrot"
  },
  AvgDialog_38843_Content_36 = {
    Text = "Ich werde heute <Red:Reinigung> des Bösen vollziehen und ein unschuldiges Heiligtum begrüßen"
  },
  AvgDialog_38843_Content_37 = {
    Text = "Der Himmel verdunkelte sich plötzlich, die Sonne verschwand, und ein roter Schatten wurde immer größer.\nEs war der Mond, ein riesiger, blutroter Mond"
  },
  AvgDialog_38843_Content_38 = {
    Text = "Schwarz verschlingt den ganzen Himmel, Mondlicht ergießt sich und färbt alles blutrot"
  },
  AvgDialog_38843_Content_39 = {
    Text = "Sünder, schneidet euer Fleisch auf, lasst eure Sünden herausfließen—"
  },
  AvgDialog_38843_Content_4 = {
    Text = "Der süßliche, metallische Geruch wurde mit jedem Schritt stärker. Salvador hatte seine gewöhnliche Sicht längst aufgegeben, doch als er erneut erwachte, konnte er das sanfte Leuchten der Seelen um ihn herum sehen."
  },
  AvgDialog_38843_Content_40 = {
    Text = "Jene, die eben noch gegeneinander kämpften, wenden ihre Köpfe dem Befehl zu und ritzen mit Klingen und Zähnen in ihr eigenes Fleisch."
  },
  AvgDialog_38843_Content_41 = {
    Text = "Beseitige diejenigen, die sich nicht reinigen lassen!"
  },
  AvgDialog_38843_Content_43 = {
    Text = "Einer nach dem anderen wenden sie sich dir zu, ihre Augen reflektieren das Licht des roten Mondes"
  },
  AvgDialog_38843_Content_5 = {
    Text = "Die Seele vor ihm schwebt in der Dunkelheit auf und ab, beinahe erloschen."
  },
  AvgDialog_38843_Content_6 = {
    Text = "Oh meine Güte, Eduard! Stütz dich auf mich, ich bringe dich ins Krankenhaus!"
  },
  AvgDialog_38843_Content_7 = {
    Text = "Nein! Ich... Nein. Das ist mein eigenes Verschulden."
  },
  AvgDialog_38843_Content_8 = {
    Text = "Die Seele flackert erneut und schwächt sich weiter.\nSeine Zeit läuft ab."
  },
  AvgDialog_38843_Content_9 = {
    Text = "Du hast mich gewarnt, nicht von den Schmerzen anderer zu profitieren und nicht zu täuschen. Ich hätte mich ändern sollen, aber ich habe nie zugehört... *hust*!"
  },
  AvgDialog_38844_Content_1 = {
    Text = "Der langen Speer fegt über den Boden und trifft das Schienbein des jungen Mannes. Der wahnsinnige junge Mann stolpert unter seinen Füßen und fällt zu Boden; du nutzt den Moment, um seinen Arm zu verdrehen und ihn am Boden zu halten"
  },
  AvgDialog_38844_Content_10 = {
    Text = "Sophia, Sophia, ich weiß, dass ich Unrecht getan habe, Sophia. Bitte, wasche mich rein von meiner Sünde!"
  },
  AvgDialog_38844_Content_11 = {
    Text = "E–Eduard? Liebster, bist du das —"
  },
  AvgDialog_38844_Content_12 = {
    Text = "Ich bin es, ich bin es! Ich hätte deine Schwester nicht täuschen sollen. Ich bereue es, ich bereue es wirklich!"
  },
  AvgDialog_38844_Content_13 = {
    Text = "Er kriecht auf Knien vorwärts, ein unbeholfenes Durcheinander aus Weinen und Verbeugungen vor ihr."
  },
  AvgDialog_38844_Content_14 = {
    Text = "Ein Dämon hat meine Augen verblendet, meine Seele befleckt, bitte peitsche mich, reinige mich! Das Urteil naht, ich will nicht aus dem Unschuldigen Paradies verbannt werden!"
  },
  AvgDialog_38844_Content_15 = {
    Text = "Beruhige dich, Eduard. Was um alles in der Welt meinst du damit, genau?"
  },
  AvgDialog_38844_Content_16 = {
    Text = "Bitte, Sophia!"
  },
  AvgDialog_38844_Content_17 = {
    Text = "Edward, stopp."
  },
  AvgDialog_38844_Content_18 = {
    Text = "Der junge Mann, noch immer gebeugt, hebt den Kopf und blickt benommen zu Salvador hinüber."
  },
  AvgDialog_38844_Content_19 = {
    Text = "Bischof...?"
  },
  AvgDialog_38844_Content_2 = {
    Text = "Lasst mich los! Ich muss geläutert werden! Ich muss geläutert werden!"
  },
  AvgDialog_38844_Content_20 = {
    Text = "Ein blendender Lichtblitz zuckt am Rand deines Sichtfeldes entlang. Noch bevor du die Nachbilder wegblinzeln kannst, hörst du Eduards Stimme, die am Rande des Wahnsinns schwankt."
  },
  AvgDialog_38844_Content_21 = {
    Text = "Nein... Nicht... Du bist auch ein <Red:Sünder>, wir sind alle Sünder!\nBeichte, reinige! Sonst werden wir alle in der endlosen Hölle brennen!"
  },
  AvgDialog_38844_Content_23 = {
    Text = "Der junge Mann schwankte und fiel zu Boden. Ogier steckte schweigend seine Lanze weg, mit der er ihn niedergeschlagen hatte, und sah dich an"
  },
  AvgDialog_38844_Content_24 = {
    Text = "Bringt ihn in Sicherheit, bevor er noch jemanden verletzt. Ruft die Polizei und lasst die Fachleute sich darum kümmern."
  },
  AvgDialog_38844_Content_25 = {
    Text = "Die Leute in der Kirche sind alle draußen, jetzt sollte sie leer sein"
  },
  AvgDialog_38844_Content_26 = {
    Text = [[
So machen wir es.
Hoffentlich ist er bei seinem Erwachen klarer]]
  },
  AvgDialog_38844_Content_27 = {
    Text = "Er hockt sich nieder, hilft dir, Edward vom Boden auf seine Schulter zu heben."
  },
  AvgDialog_38844_Content_28 = {
    Text = "Ich übernehme, %player%{Male=Herr,Female=Frau}"
  },
  AvgDialog_38844_Content_29 = {
    Text = "Alles gut, ich bin es gewohnt. Aufstehen macht es nur schwieriger"
  },
  AvgDialog_38844_Content_3 = {
    Text = "Was ist los?"
  },
  AvgDialog_38844_Content_30 = {
    Text = "Das... dann überlasse ich es dir.\nIch bleibe hier noch ein bisschen, um zu sehen, ob jemand von Edward erschreckt oder verletzt wurde"
  },
  AvgDialog_38844_Content_31 = {
    Text = "Du nickst, doch bevor du dich umdrehen kannst, brennt dasselbe Licht wie zuvor erneut am Rand deines Sichtfeldes."
  },
  AvgDialog_38844_Content_32 = {Text = "?"},
  AvgDialog_38844_Content_33 = {
    Text = "Geht es dir gut, %player%?\nWenn du dich unwohl fühlst, kann ich das alleine bewältigen."
  },
  AvgDialog_38844_Content_34 = {
    Text = [[
Nichts, wahrscheinlich hat das Glas reflektiert und meine Augen geblendet.
Lass uns gehen]]
  },
  AvgDialog_38844_Content_4 = {
    Text = "Eine ruhige Stimme ertönt hinter dir, und der umgebende Lärm verstummt. Die Menge teilt sich und macht einem Läufer in schwarzer Soutane Platz."
  },
  AvgDialog_38844_Content_5 = {
    Text = "Läufer Salvador, mit verbundenen Augen, schreitet mit unheimlicher Anmut und Treffsicherheit auf dich zu. Sophia folgt dicht hinter ihm, das Gesicht voller Sorge."
  },
  AvgDialog_38844_Content_6 = {
    Text = "Sophia... Sophia!"
  },
  AvgDialog_38844_Content_7 = {
    Text = "Der junge Mann wurde plötzlich aufgeregt und riss sich mit unerwarteter Kraft von dir los, stürzte sich auf Sophia—"
  },
  AvgDialog_38844_Content_8 = {Text = "Vorsicht!"},
  AvgDialog_38844_Content_9 = {
    Text = "Er fällt abrupt auf die Knie."
  },
  AvgDialog_38845_Content_1 = {
    Text = "Ogier schleudert seinen Speer mit gewaltiger Kraft und durchbohrt den silbernen Spiegel."
  },
  AvgDialog_38845_Content_10 = {
    Text = "Wo bin ich? Wie habe ich..."
  },
  AvgDialog_38845_Content_11 = {
    Text = "Eure Exzellenz, seid Ihr das? Was ist mit Euch geschehen?"
  },
  AvgDialog_38845_Content_12 = {
    Text = "Bitte... warte..."
  },
  AvgDialog_38845_Content_13 = {
    Text = "Das blaue Licht verblasst vollständig, ohne dass es jemand bemerkt..."
  },
  AvgDialog_38845_Content_14 = {
    Text = "Salvador kniete zwischen den Tafeln, hob den Kopf zu dir, und aus dem weißen Verband liefen zwei Ströme Bluttränen"
  },
  AvgDialog_38845_Content_15 = {
    Text = "Mein Herr, was ist mit dem Läufer los?"
  },
  AvgDialog_38845_Content_16 = {
    Text = "Der Verbindung fehlt es an Kraft, aber bei einer solch schweren Instabilität... So etwas habe ich noch nie gesehen."
  },
  AvgDialog_38845_Content_17 = {
    Text = "Meine Verknüpfung... war... der ehemalige Bischof hier... Ich kann ihn nicht überfordern..."
  },
  AvgDialog_38845_Content_18 = {
    Text = "Blaser Bote... bitte... bitte..."
  },
  AvgDialog_38845_Content_19 = {
    Text = "Er zittert, hebt seine Hand und legt sie sanft auf Eure Schulter.\nDoch Ihr könnt ihr Gewicht kaum noch spüren."
  },
  AvgDialog_38845_Content_2 = {
    Text = "Fragmente des silbernen Spiegels fallen wie Sterne herab, und mit ihnen zerbricht der von Rissen durchzogene purpurrote Mond vollständig."
  },
  AvgDialog_38845_Content_20 = {
    Text = "Er schwindet schnell, es sei denn —"
  },
  AvgDialog_38845_Content_21 = {
    Text = "Ihr haltet Salvadors Hand und schließt die Augen..."
  },
  AvgDialog_38845_Content_22 = {
    Text = [[
Dunkelheit.
 Die Dunkelheit ist so friedlich, wie eine Umarmung, wie ein tiefer Schlummer.]]
  },
  AvgDialog_38845_Content_23 = {
    Text = "Die unzähligen Lichtpunkte tauchen in deinem Bewusstsein auf: Die beunruhigten Bürger rundherum, die Entschlossenen sind Ogier, und ein schwacher Bischof, der schwaches, kaum sichtbares blaues Licht ausstrahlt"
  },
  AvgDialog_38845_Content_24 = {
    Text = "Ihr nähert Euch ihm und hört schwache, gedämpfte Stimmen."
  },
  AvgDialog_38845_Content_25 = {
    Text = "Meine Familie hat sich stets der Beseitigung von Leid und der Verbreitung des Segens des Vaters gewidmet... Wie konnte es so weit kommen?"
  },
  AvgDialog_38845_Content_26 = {
    Text = "Halt die Klappe! Wie kannst du es wagen, meinen Vater so zu verleumden! Er ist nicht so eine Art Mensch! Überhaupt nicht!"
  },
  AvgDialog_38845_Content_27 = {
    Text = "Eure Exzellenz, warum ist die Welt immer voller Leid?"
  },
  AvgDialog_38845_Content_28 = {
    Text = "Ohne Sünder auf der Welt, würden Menschen wie meine Schwester, meine Mutter und die Kinder im Waisenhaus nicht mehr leiden?"
  },
  AvgDialog_38845_Content_29 = {
    Text = "Ist es möglich, dem Leid zu entkommen und glücklich bis ans Ende zu leben?"
  },
  AvgDialog_38845_Content_3 = {
    Text = "Das Monster stieß einen klagenden Schrei aus und fiel dann zu Boden. Der riesige Körper löste sich schnell in eine dunkle Blutlache auf, nur eine menschliche Gestalt blieb zurück"
  },
  AvgDialog_38845_Content_30 = {
    Text = "Das ist meine Verantwortung..."
  },
  AvgDialog_38845_Content_31 = {
    Text = "Das Bild von Salvador erschien an deiner Seite.\nErinnerungen wechselten ständig vor euch, er hatte keinen Ausdruck, doch du konntest einen Hauch von Traurigkeit spüren"
  },
  AvgDialog_38845_Content_32 = {
    Text = "Ich habe immer gewusst, dass sie Groll in ihrem Herzen hegte. Ich dachte, sie würde ihn loslassen, doch stattdessen ließ sie ihn schwären."
  },
  AvgDialog_38845_Content_33 = {
    Text = "Er sagte, Ihr hättet ihn damals gerettet, Läufer Salvador. Stimmt das? Aber warum?\nEr hat so viele schreckliche Dinge getan, so viele Menschen betrogen... Warum habt Ihr ihm geholfen?"
  },
  AvgDialog_38845_Content_34 = {
    Text = "Zweite Chance? Wer gibt meiner Familie eine zweite Chance, wer gibt meiner Schwester, meiner Mutter eine zweite Chance?\nSie sind tot, Bischof Salvador, sie sind im Schoß des Vaters, nur ich bin übrig"
  },
  AvgDialog_38845_Content_35 = {
    Text = "Nur ich bleibe..."
  },
  AvgDialog_38845_Content_36 = {
    Text = "Vater Gott, hab Erbarmen und gewähre mir eine weitere Chance auf Leben. Ich hätte es besser machen sollen, aber jetzt mache ich die gleichen Fehler wieder."
  },
  AvgDialog_38845_Content_37 = {
    Text = "Die Diebe, Spieler und Süchtigen kommen nicht zu dir, um Vergebung oder eine zweite Chance zu suchen, sondern zur Selbstberuhigung! Eine Ausrede, um falsch zu bleiben!"
  },
  AvgDialog_38845_Content_38 = {
    Text = "Sünder bereuen nicht. Endlose Nachsicht macht die Guten traurig und die Bösen dreist.\nSo wirst du niemanden retten"
  },
  AvgDialog_38845_Content_39 = {
    Text = "Ich vergebe ihnen und tröste sie, so wie ich allen vergebe und Trost spende.\nAlle genießen die Liebe des Vaters und haben die Möglichkeit, Fehler zu machen und auf den richtigen Weg zurückzukehren"
  },
  AvgDialog_38845_Content_4 = {
    Text = "Der Blutmond verblasst, und Sonnenlicht scheint erneut auf den Boden und beleuchtet den Körper, der in einer Blutlache liegt.\nSophia starrt ausdruckslos in den Himmel und murmelt leise vor sich hin."
  },
  AvgDialog_38845_Content_40 = {
    Text = "Leid ist das, was der Vater nicht sehen möchte, was Er zu lösen hofft, und was ich als sein Agent zerstreuen muss."
  },
  AvgDialog_38845_Content_41 = {
    Text = "Das Leid, das ich verursacht habe, muss von mir allein gesühnt werden."
  },
  AvgDialog_38845_Content_42 = {
    Text = "Er streckt die Hand aus und streicht sanft über seine Hand. Die vergilbten Gedenken kräuselten sich wie Wasser davon und sammelten sich zu Lichtpunkten seines Geistes."
  },
  AvgDialog_38845_Content_43 = {
    Text = "Er wendet sich dir zu und präsentiert das leuchtende Licht in seinen Händen."
  },
  AvgDialog_38845_Content_44 = {
    Text = "Bitte... Hilf mir, bleicher Bote.\nBefreie sie von ihrem Leid, damit sie ihre Reise in Frieden vollenden können."
  },
  AvgDialog_38845_Content_45 = {
    Text = "Das Licht annehmen"
  },
  AvgDialog_38845_Content_46 = {
    Text = "Ein blaues Licht wiegt sich wie ein Spinnenfaden. Ein Ende ist mit einem betagten, aber sanften Geist verbunden, das andere Ende taucht in den Lichtpunkt vor dir ein."
  },
  AvgDialog_38845_Content_47 = {
    Text = "Vorsichtig durchtrennst du den dünnen Faden und färbst ihn mit deiner eigenen Farbe."
  },
  AvgDialog_38845_Content_48 = {
    Text = "Ein weißes Licht folgt dem Seidenfaden immer weiter nach innen, während Lichtpunkte erscheinen und die Dunkelheit allmählich vertreiben."
  },
  AvgDialog_38845_Content_49 = {
    Text = "Vielen Dank..."
  },
  AvgDialog_38845_Content_5 = {
    Text = "<Yellow:Eve>... Ich habe dich enttäuscht, den <Yellow:Lichtträger> enttäuscht...\nIch konnte sie nicht reinigen, konnte ihre Sünden nicht läutern..."
  },
  AvgDialog_38845_Content_6 = {
    Text = "Träger des Lichts... Du, geformt aus reinem Silber... Ich bitte dich..."
  },
  AvgDialog_38845_Content_7 = {
    Text = "Sie holt zitternd Luft, und ein letztes Ausatmen entweicht ihrem zerbrechlichen Körper."
  },
  AvgDialog_38845_Content_8 = {
    Text = "Der Platz liegt in Trümmern — die Verwundeten liegen am Boden; viele haben ihr Leben verloren. Andere stöhnen vor Qual, unfähig, die vorangegangenen, grauenvollen Ereignisse zu begreifen."
  },
  AvgDialog_38845_Content_9 = {
    Text = "Ugh... Mein Kopf tut weh..."
  },
  AvgDialog_38846_Content_1 = {
    Text = "Entzünde die Weiße Hoffnung."
  },
  AvgDialog_38846_Content_10 = {
    Text = "Jene, die das Bewusstsein verloren hatten oder sogar aufgehört hatten zu atmen, öffneten langsam ihre Augen in der sanften Brise."
  },
  AvgDialog_38846_Content_11 = {
    Text = "Bitte... Lösche ihren Schmerz und beruhige ihre Herzen."
  },
  AvgDialog_38846_Content_12 = {
    Text = "Die Blicke der Menschen wurden leer, ihre Körper entspannten sich. Panik und Angst verschwanden, ersetzt durch Ruhe und Frieden"
  },
  AvgDialog_38846_Content_13 = {
    Text = "Lass sie nicht länger leiden und gib ihnen Segen"
  },
  AvgDialog_38846_Content_14 = {
    Text = "Wellen von Licht strömen in alle Richtungen, alle schließen die Augen, als ob sie in Ruhe versinken"
  },
  AvgDialog_38846_Content_15 = {
    Text = "Der helle Mond blickt auf alles herab, wie immer, nur der chaotische Platz zeugt von der jüngsten Raserei"
  },
  AvgDialog_38846_Content_16 = {
    Text = "Die Tafel gibt ein leises Geräusch von sich und verwandelt sich in einen unsichtbaren Schatten, der in die Nacht verschwindet. Salvador richtet seine Kleidung und geht zu Sophia"
  },
  AvgDialog_38846_Content_17 = {
    Text = "...Du hättest mich nicht retten sollen."
  },
  AvgDialog_38846_Content_18 = {
    Text = "\"Alle, die ihren Weg zurückfinden, können in meine Umarmung zurückkehren.\""
  },
  AvgDialog_38846_Content_19 = {
    Text = "„Denn ihr seid alle meine Kinder, und ich liebe euch alle.\"\nAber Ihr irrt Euch, Läufer, und die „Heilige Schrift\" ebenso."
  },
  AvgDialog_38846_Content_2 = {
    Text = "Das Tablet hebt sich erneut."
  },
  AvgDialog_38846_Content_20 = {
    Text = "Einige Menschen ändern sich niemals."
  },
  AvgDialog_38846_Content_21 = {
    Text = "Was bringt dich hierher?"
  },
  AvgDialog_38846_Content_22 = {
    Text = "Sophia, ich—"
  },
  AvgDialog_38846_Content_23 = {
    Text = "Halt die Klappe! Reicht es nicht, dass du den Tod meiner Schwester und Mutter verursacht hast? Kommst du jetzt zu ihren Gräbern, um dich zu rühmen?!"
  },
  AvgDialog_38846_Content_24 = {
    Text = "Ich bin hier, um mich zu entschuldigen. Ich habe nicht erwartet..."
  },
  AvgDialog_38846_Content_25 = {
    Text = "Sophia lachte scharf."
  },
  AvgDialog_38846_Content_26 = {
    Text = "Hast du dich auch bei <Blue:Thompson> so entschuldigt, nachdem du seinen einzigen Verwandten und <Blue:Millie> getötet hast?\nDu ekelst mich an, Edward Bailey"
  },
  AvgDialog_38846_Content_27 = {
    Text = "Ich bereue es wirklich, was ich getan habe, Sophia. Ich weiß, dass ich deine Vergebung nicht verdienen kann—"
  },
  AvgDialog_38846_Content_28 = {
    Text = "Wenn du es wirklich bereust, hättest du am Tag, an dem Thompson dich getötet hat, nicht zu Bischof Salvador gehen sollen."
  },
  AvgDialog_38846_Content_29 = {
    Text = "Genau, ich weiß, wie du überlebst, du Feigling. <Yellow:Die Laterne> hat es mir gesagt.\nDir „<Yellow:segnen>\" zu geben, war die dümmste Entscheidung des Bischofs. Du solltest sterben, Bailey, in Qualen"
  },
  AvgDialog_38846_Content_30 = {
    Text = "Ich wollte das auch nicht. Ich habe versucht, mich zu beherrschen, wirklich! Nachdem der Läufer mich gerettet hat, habe ich mich jeden Tag bei der Kirche gemeldet und wöchentlich bei deiner Wohltätigkeitsorganisation geholfen. Erinnerst du dich?"
  },
  AvgDialog_38846_Content_31 = {
    Text = "Ich möchte besser werden, das will ich wirklich. Es war dieser Aglo-Typ – er sagte, es sei ein narrensicherer Deal und bat mich, einen Bürgen einzuführen. Ich bin auch ein Opfer!"
  },
  AvgDialog_38846_Content_32 = {
    Text = "Sogar jetzt weichst du noch deiner Verantwortung aus. Sogar jetzt... hast du dich nicht wirklich gewandelt."
  },
  AvgDialog_38846_Content_33 = {
    Text = "Sie zog einen silbernen Gegenstand aus der Tasche ihres Kleides, dessen glatte Oberfläche im Sonnenlicht kurz aufblitzte und das reflektierte Licht in ein unheilvolles Rot verwandelte"
  },
  AvgDialog_38846_Content_34 = {Text = "Sophia...?"},
  AvgDialog_38846_Content_35 = {Text = "Bereue."},
  AvgDialog_38846_Content_36 = {
    Text = "Folge den Lehren des gerechten Lichtbringers und läutere die Sünden in deiner Seele.\nNur dann kannst du Vergebung erlangen."
  },
  AvgDialog_38846_Content_37 = {
    Text = "Was bist du?"
  },
  AvgDialog_38846_Content_38 = {
    Text = "Ich... Ich bin Edward..."
  },
  AvgDialog_38846_Content_39 = {
    Text = [[
Der Spiegel blitzt auf, und die Augen des knienden jungen Mannes wurden erneut benommen.
Zitternd hob er den Stock in seiner Hand und schlug sich selbst hart.]]
  },
  AvgDialog_38846_Content_4 = {
    Text = "Salvador hob die Hand, das Blut floss unaufhörlich von ihm und um ihn herum zur Tafel"
  },
  AvgDialog_38846_Content_40 = {
    Text = "Ich frage noch einmal: Was bist du?"
  },
  AvgDialog_38846_Content_41 = {
    Text = "Ich bin ein Sünder."
  },
  AvgDialog_38846_Content_42 = {
    Text = "Welche Sünde hast du begangen?"
  },
  AvgDialog_38846_Content_43 = {
    Text = "Gier... Begierde... Ich habe zugelassen, dass das Böse meine Seele befleckt, und dann Unschuldigen Leid zugefügt."
  },
  AvgDialog_38846_Content_44 = {
    Text = "Was solltest du tun?"
  },
  AvgDialog_38846_Content_45 = {
    Text = "Reue vor den Göttern und jenen, denen ich Unrecht getan habe...\nIch muss die Peitsche erdulden, bluten, bis die schwarze Sünde herausfließt, bis die <Red:Läuterung> erlangt ist."
  },
  AvgDialog_38846_Content_46 = {
    Text = "Der Tag des Gerichtes naht. Nur reine Seelen dürfen das Unschuldig Paradies betreten."
  },
  AvgDialog_38846_Content_47 = {
    Text = "<Red: Möge die Laterne brennen bleiben.>"
  },
  AvgDialog_38846_Content_48 = {
    Text = "Sünder ändern sich nicht. Solange sie existieren, wird das Leid nie enden.\nNur wenn sie alle beseitigt sind, kann die Welt Frieden finden"
  },
  AvgDialog_38846_Content_49 = {
    Text = "......Die Schöpfungen des Vaters tragen immer sein Licht. Jeder kann getäuscht werden, aber ebenso kann jeder das Licht des Vaters wiederfinden"
  },
  AvgDialog_38846_Content_5 = {
    Text = "Blaues Licht pulsierte entlang der Muster, wie ein Atemzug"
  },
  AvgDialog_38846_Content_50 = {
    Text = "Wir können jemandem nicht sein ganzes Leben wegen einer einzigen momentanen Handlung nehmen."
  },
  AvgDialog_38846_Content_51 = {
    Text = "Du sagst das, ohne an die Opfer zu denken. Wie viele Millies müssen für das Licht der Edwards geopfert werden? Wie viele Olivias?"
  },
  AvgDialog_38846_Content_52 = {
    Text = "Sünde ist Sünde, und falsch ist falsch. Einmal begangen, gibt es kein Zurück."
  },
  AvgDialog_38846_Content_53 = {
    Text = "Sie blickt zu dir."
  },
  AvgDialog_38846_Content_54 = {
    Text = "Nimm mich mit und wirf mich deinem korrupten Gesetz zum Fraß. Aber denke daran, der Tag des Gerichts wird kommen.\nZu diesem Zeitpunkt werdet ihr alle aus dem unschuldigen Paradies verbannt"
  },
  AvgDialog_38846_Content_55 = {
    Text = "Der Spiegel wurde gesichert, Schutzherr. Die betroffenen Zivilisten wurden in die großen Krankenhäuser gebracht und werden nach Untersuchungen entlassen."
  },
  AvgDialog_38846_Content_56 = {
    Text = "Die offizielle Erklärung lautet, dass dies ein Massenhalluzinationsereignis war, verursacht durch ein Leck von giftigem Gas in der Fabrik. Die Stadtregierung wird morgen eine öffentliche Entschuldigung aussprechen und disziplinarische Maßnahmen gegen die verantwortlichen Personen ergreifen."
  },
  AvgDialog_38846_Content_57 = {
    Text = "Ich verstehe. Danke für Ihre harte Arbeit."
  },
  AvgDialog_38846_Content_58 = {
    Text = "Dies ist das, was wir tun sollten."
  },
  AvgDialog_38846_Content_59 = {
    Text = "Der junge Mann in Uniform zögert einen Moment, dann sprach er:"
  },
  AvgDialog_38846_Content_6 = {
    Text = "All-Vater des Ursprungs, unser barmherziger Schöpfer, bitte erhöre mein Gebet."
  },
  AvgDialog_38846_Content_60 = {
    Text = "Wie hast du das geschafft?"
  },
  AvgDialog_38846_Content_61 = {Text = "Was?"},
  AvgDialog_38846_Content_62 = {
    Text = "Die Lage war so chaotisch, und dennoch haben Sie allein mit einem Erweckten Körper die Opferzahl auf etwa ein Dutzend begrenzt — fast ein Wunder."
  },
  AvgDialog_38846_Content_63 = {
    Text = "Du und Ogier tauscht einen schnellen Blick aus. Der junge Ritter räuspert sich leicht mit den Händen hinter dem Rücken."
  },
  AvgDialog_38846_Content_64 = {
    Text = "Das ist wahrscheinlich das unausgesprochene Verständnis zwischen meinem Herrn und mir."
  },
  AvgDialog_38846_Content_65 = {
    Text = "Dennoch spreche ich dir im Namen des Ersten Reaktionsteams des Ausschusses meinen Dank aus. \nInmitten der Krise hast du unser Volk nicht verlassen, sodass sie sicher nach Hause zurückkehren konnten. Darüber hinaus..."
  },
  AvgDialog_38846_Content_66 = {
    Text = "Viele von uns sind hier aufgewachsen; der Kirchenbezirk bedeutet uns viel.\nDanke für alles, was du getan hast."
  },
  AvgDialog_38846_Content_67 = {
    Text = "Das sollten wir tun."
  },
  AvgDialog_38846_Content_68 = {
    Text = "Es gibt nie zu viel Dankbarkeit."
  },
  AvgDialog_38846_Content_69 = {
    Text = "Fräulein Sophia... Was wird aus ihr?"
  },
  AvgDialog_38846_Content_7 = {
    Text = "Das sanfte Blau streckt sich mit dichten Wurzeln in die Tiefen um den Stein, sie durchdringen die Menge, ein kühler Wind vertreibt den verbleibenden Geruch von Blut und hinterlässt nur einen leichten Hauch von Duft"
  },
  AvgDialog_38846_Content_70 = {
    Text = "Wir werden sie verhören. Wir werden über sie urteilen, nachdem wir herausgefunden haben, woher der Spiegel stammt."
  },
  AvgDialog_38846_Content_71 = {
    Text = "Das ketzerische Ritual hat weitreichendes Chaos und zahlreiche Opfer verursacht... Der Läufer hofft, dass sie nicht zum Tode verurteilt wird, aber ich bin nicht optimistisch."
  },
  AvgDialog_38846_Content_72 = {
    Text = "Bischof Salvador."
  },
  AvgDialog_38846_Content_73 = {Text = "Gehst du?"},
  AvgDialog_38846_Content_74 = {
    Text = "Ja. Danke für Eure Hilfe bei diesem Vorfall."
  },
  AvgDialog_38846_Content_75 = {
    Text = "Das alles begann wegen mir, und du hast sogar meine Identität geheim gehalten. Ich sollte dir danken."
  },
  AvgDialog_38846_Content_76 = {
    Text = "Kommst du wirklich nicht mit uns zurück?"
  },
  AvgDialog_38846_Content_77 = {
    Text = "Mach dir keine Sorgen um die Pfarrei. Solange die Bedingungen stimmen, erlauben wir es Wachenden, frei zu handeln."
  },
  AvgDialog_38846_Content_78 = {
    Text = "Danke für Ihre Freundlichkeit, aber ich würde lieber hier bleiben."
  },
  AvgDialog_38846_Content_79 = {
    Text = "Salvador wandte sich dem Altar zu und lächelte sanft"
  },
  AvgDialog_38846_Content_8 = {
    Text = "Die stehenden Menschen setzten sich langsam hin."
  },
  AvgDialog_38846_Content_80 = {
    Text = "Der Vater ließ mich hier wieder lebendig werden, ich nehme an, es ist auch sein Wunsch, dass ich mehr Menschen helfe.\nWenn du etwas brauchst, <Yellow:dass bleiche Feuer>, kannst du jederzeit zu mir kommen. Ich werde mein Bestes für dich tun"
  },
  AvgDialog_38846_Content_81 = {
    Text = "Es tut mir leid, aber... Was genau sind der <Yellow:Pale Messenger> und das <Yellow:Pale Fire>?"
  },
  AvgDialog_38846_Content_82 = {
    Text = "Es ist eine Prophezeiung des Vaters aus <Yellow:„Schrift“>"
  },
  AvgDialog_38846_Content_83 = {
    Text = "Grenzenlose Dunkelheit wird über die Welt hereinbrechen, die bleiche und warme Seele ist die Botin der Hoffnung, {Male=he,Female=she} wird die weiße Flamme entzünden, um den Weg nach vorn zu erhellen."
  },
  AvgDialog_38846_Content_84 = {
    Text = "Das kann unmöglich ich sein, oder? Es gibt so viele Menschen auf der Welt."
  },
  AvgDialog_38846_Content_85 = {
    Text = [[
Auch wenn meine Augen bedeckt sind, kann ich die Brillanz einer Seele nicht verkennen.
Deine ist so warm und hell. In all diesen Jahren habe ich noch nie eine andere wie sie gesehen.]]
  },
  AvgDialog_38846_Content_86 = {
    Text = "[Hier sehen, wie die Hauptgeschichte gestaltet ist, ob Informationen zur Laterne erwähnt werden müssen]"
  },
  AvgDialog_38846_Content_87 = {
    Text = "Der junge Schutzherr dreht sich um und geht. Salvador beobachtet das Schimmern und flüstert ein Gebet, als die Tür sich ein letztes Mal öffnet."
  },
  AvgDialog_38846_Content_88 = {
    Text = "Mögest du die Dunkelheit mit schwacher Hoffnung erleuchten."
  },
  AvgDialog_38846_Content_89 = {
    Text = "<Yellow:Unfallbericht des Sanktuariums Lentinium>\n\nA.F. 315 @2@3 ereignete sich in der Großen Heiligen Kirche des All-Vaters im Sanktuarium Lentinium eine plötzliche Revolte. Die anwesenden Bürger zeigten schwerwiegende gewalttätige Handlungen und Selbstverletzungen und waren nicht ansprechbar.\n...\nDas ungewöhnliche Verhalten verschärfte sich nach dem Aufblitzen einer unbekannten Lichtquelle und entwickelte sich schließlich zu Kannibalismus auf breiter Ebene. Nach Ermittlungen stellte sich heraus, dass die unbekannte Lichtquelle ein handgehaltenes Spiegel aus reinem Silber war. Dieser Spiegel gewinnt durch das Reflektieren von Sonnen- und Mondlicht Energie. Individuen, die von dem reflektierten Licht bestrahlt wurden, gerieten unter den Einfluss ihres stärksten inneren Wunsches – darunter Gewalt, Fresssucht, Schlafsucht und Ähnliches – und zeigten daraufhin übermäßige Reaktionen.\nDer Spiegel wurde von dem Geheimwahrer %player% und dem Erwecker Ogier geborgen. Vorläufige Untersuchungen deuten darauf hin, dass er einen Silberkern oder ein silberähnliches Material enthält. Weitere Informationen finden Sie im Forschungsbericht der Abteilung für spezielle Geräte der Universität Misag.\n...\nNach der Befragung durch den Untersuchungsausschuss von Misdeia gestand <Blue:Sophia Chaztan>, dass sie vor drei Jahren der Tempellicht-Kirche beigetreten war und bei der letzten Kirchenveranstaltung von der Anführerin der Kirche, der Laterne (alias <Yellow:Eve>), das Ritualspiegel erhalten hatte.\nAls die Agenten weitere Fragen stellten, begann Sophia Chaztan leise zu beten und gab danach keine weiteren Antworten mehr.\n..."
  },
  AvgDialog_38846_Content_9 = {
    Text = "Die dort Sitzenden starren mit offenem Mund auf die wundersame Szene vor ihnen."
  },
  AvgDialog_38846_Content_90 = {
    Text = "Die untergehende Sonne vertreibt den letzten Dunst am Himmel. Die Kirchenglocke läutet, und die Schiffssirene ertönt am Flussdock."
  },
  AvgDialog_38846_Content_91 = {
    Text = "Auf dem Dach eines hohen Gebäudes steht eine umhulte Gestalt allein mit dem Rücken zur Sonne."
  },
  AvgDialog_38846_Content_92 = {
    Text = "Selbst nach der Opferung der mutierten Sünder erschien kein <Red:Stigmata>.\nEs scheint, der Wert <Yellow:dieser Spiegel> ist genau so."
  },
  AvgDialog_38846_Content_93 = {
    Text = "Vergib den Sündern und segne sie mit „der Segen\"... du bist immer noch unverändert, nicht wahr, Bischof Salvador"
  },
  AvgDialog_38846_Content_94 = {
    Text = "Das Scheiterfeuer kann dich nicht verändern, noch kann die Auferstehung es. Wann wirst du endlich die Realität sehen? Vielleicht—"
  },
  AvgDialog_38846_Content_95 = {
    Text = "Sie streckt ihre Hand in die Luft, als würde sie etwas Unsichtbares berühren."
  },
  AvgDialog_38846_Content_96 = {
    Text = "Der <Yellow:Wächter> mit der blassen und warmen Seele aus der Prophezeiung kann mehr Variablen bringen. Meinst du, {Male=er,Female=sie} würde sich uns anschließen?"
  },
  AvgDialog_38846_Content_97 = {
    Text = "Ein riesiger Hund trat aus den Schatten neben der Frau hervor, seine verzerrten Gliedmaßen erinnerten entfernt an die mutierte Sophia. Er schnaubt als Antwort auf die Worte der Frau."
  },
  AvgDialog_38846_Content_98 = {
    Text = "Nun, morgen ist immer ein neuer Tag."
  },
  AvgDialog_38846_Content_99 = {
    Text = "Lass uns gehen, mein Lieber. Wenn wir die Gelegenheit bekommen, werden wir sie wieder treffen."
  },
  AvgDialog_43774_Content_1 = {
    Text = "Als sie voranschritten, begannen sich lebhafte Grüns hinter den endlosen Sanddünen zu zeigen."
  },
  AvgDialog_43774_Content_2 = {
    Text = "In der Trockenzeit mag dieser nahezu ausgetrocknete Nebenfluss, bekannt als \"Oase im Sand\", etwas weit hergeholt erscheinen, doch er reicht aus, um eure Wasserbeutel zu füllen."
  },
  AvgDialog_43774_Content_3 = {
    Text = "Ich gehe Wasser holen. %player%, pass auf Ramona auf."
  },
  AvgDialog_43774_Content_4 = {
    Text = "Der Hüter wacht über Ramona, und ich wache über den Hüter.\nSchließlich sind diejenigen, die auf die Oase für das Überleben angewiesen sind, nicht einfach Reisende aus der Ferne..."
  },
  AvgDialog_43774_Content_5 = {
    Text = "Was ist mit den \"Eingeborenen\", was sagst du?"
  },
  AvgDialog_43775_Content_1 = {Text = "Oase"},
  AvgDialog_43775_Content_10 = {
    Text = "Oh, dieser Narzissenfrau... ihr Verhalten ist wirklich fragwürdig."
  },
  AvgDialog_43775_Content_11 = {
    Text = "Basierend auf Alistairs Berechnungen hat das Schwarze Becken seit der diesjährigen Schlüsselverleihzeremonie abnormale Schwankungen gezeigt."
  },
  AvgDialog_43775_Content_12 = {
    Text = "Das könnte ein Zeichen dafür sein, dass Tawils Stabilität zurückkehrt. Ich schlage vor, dass die Überwachungsabteilung verstärkt..."
  },
  AvgDialog_43775_Content_13 = {
    Text = "Warte einen Moment."
  },
  AvgDialog_43775_Content_14 = {
    Text = "Hast du Vorschläge, Professor Puppe?"
  },
  AvgDialog_43775_Content_15 = {
    Text = "Ich schlage vor, dass die Menschen die Empfindlichkeit ihrer Organe erhöhen, um zu vermeiden, während äußerer Invasionen über Mythags Geheimnisse zu sprechen."
  },
  AvgDialog_43775_Content_16 = {
    Text = "Angestoßen von Puppe durchdringt ein schwacher violetter Duft Ihre Nasenlöcher, und eine elegante Dame erhebt sich anmutig von der Gästesofalinie."
  },
  AvgDialog_43775_Content_17 = {
    Text = "Warum so angespannt? Das Meer des Grauen Nebels hat mir Tage bevor du begonnen hast, diese scheinbar präzisen Instrumente ins Wasser zu tauchen, bereits die Nachricht vom Schwarzen Pool gesendet."
  },
  AvgDialog_43775_Content_18 = {
    Text = "Lass uns den Small Talk überspringen. Ich bin zu euch gekommen, weil ich einen entscheidenden Hinweis von einer anderen Organisation erhalten habe, den ich Herrn William überbringen möchte."
  },
  AvgDialog_43775_Content_19 = {
    Text = "Über die Essenz des Verlangens—<Yellow:\"Der Mutterbaum\">."
  },
  AvgDialog_43775_Content_2 = {
    Text = "Ich, ebenfalls, habe einst geschlafen, aber jetzt bin ich wach.\nWüstenbestien werden aus den ▼▼ Flüssen trinken und an ihren Ufern ruhen,\ndenn niemand wird ihnen Angst einjagen."
  },
  AvgDialog_43775_Content_20 = {
    Text = "Auf jeden Fall wurden aufgrund einiger Worte dieser \"Narzissenlady\" mehrere Herren und Damen in dieser primitiven Wüste zurückgelassen, die mit den Gezeiten der Zeit überhaupt nicht Schritt gehalten hat."
  },
  AvgDialog_43775_Content_21 = {
    Text = "Mythags Entscheidungsträger sind genauso Spielertypen wie ich."
  },
  AvgDialog_43775_Content_22 = {
    Text = "Nach Wochen des Sandsturms ist mein Lieblingsmantel fast abgetragen. Kann ich etwas Geld für neue Kleidung bekommen?"
  },
  AvgDialog_43775_Content_23 = {
    Text = "Wenn du wirklich einen neuen Trenchcoat kaufen willst, anstatt dein Geld im Untergrund-Casino zu setzen, stört uns das nicht, Mr. Ryker."
  },
  AvgDialog_43775_Content_24 = {
    Text = "Verdiene genug für einen neuen Überwurf und die nächste Runde an nur einer Nacht. Ist das nicht eine Win-Win-Situation?"
  },
  AvgDialog_43775_Content_25 = {
    Text = "William räusperte sich leicht und schnitt das sinnlose Geplapper ab."
  },
  AvgDialog_43775_Content_26 = {
    Text = "<Yellow:Intellektueller Körper>Tawil schläft im Schwarzen Pool von Mythag, <Yellow:Freudiger Körper> umstreift die Welt in verschiedenen Formen, während die Aufenthaltsorte des <Yellow:Desire Body> ein Rätsel bleiben."
  },
  AvgDialog_43775_Content_27 = {
    Text = "Laut den Informationen von Narzisse wurde der Standort des Mutterbaums vor 225 Jahren durch die plötzlich erschienene <Yellow:Storm Wall> abgeschnitten, und seit 90 Jahren hat sich niemand diesem genähert."
  },
  AvgDialog_43775_Content_28 = {
    Text = "Die Aram planen ein großangelegtes opferähnliches Ritual, um die Verschmutzung des Mutterbaums global zu verbreiten."
  },
  AvgDialog_43775_Content_29 = {
    Text = "Deine Aufgabe ist es, den örtlichen Aram-Nomaden zu folgen und den Kern des Rituals—den Mutterbaum—zu zerstören."
  },
  AvgDialog_43775_Content_3 = {
    Text = "Vor zwei Wochen \"Operation Lemwash\""
  },
  AvgDialog_43775_Content_30 = {
    Text = "Verstanden, verstanden. Ist es nicht wichtiger, die unmittelbaren Probleme zu lösen als den großen Plänen eines fernen Befehlgebers zu folgen?"
  },
  AvgDialog_43775_Content_31 = {
    Text = "Sieh dir dieses kleine Mädchen an – Dehydrierung hat ihr Gesicht blass gemacht.\nWenn wir nicht bald Wasser finden, werden wir hier alle verdursten."
  },
  AvgDialog_43775_Content_32 = {
    Text = "Rede keinen Unsinn. Mir geht es gut—"
  },
  AvgDialog_43775_Content_33 = {
    Text = "Keine Notwendigkeit, so stur zu sein, kleines Mädchen. Wir haben gerade unseren Wasservorrat aufgebraucht, aber du hast seit gestern nicht an deinem Wasserbeutel gerochen, oder?"
  },
  AvgDialog_43775_Content_34 = {
    Text = "Was ist da drin?"
  },
  AvgDialog_43775_Content_35 = {Text = "!"},
  AvgDialog_43775_Content_36 = {
    Text = "Du schnappst dir Ramonas Wasserbeutel; er ist schwer, mit einem verschwommenen schwarzen Schatten, der darin schwingt."
  },
  AvgDialog_43775_Content_37 = {
    Text = "Ryker hob die Wasserblase und goss eine dicke schwarze Flüssigkeit aus."
  },
  AvgDialog_43775_Content_38 = {
    Text = "Es ist D-Schleim."
  },
  AvgDialog_43775_Content_39 = {
    Text = "Ramona, dein Wassersack... wann ist das passiert...?"
  },
  AvgDialog_43775_Content_4 = {
    Text = "Bevor es losgeht, hat mir niemand gesagt, dass neben dem sogenannten <Yellow:\"Der Mutterbaum\"> auch dies hier sein würde—"
  },
  AvgDialog_43775_Content_40 = {
    Text = "Vor ungefähr zwei Tagen.\nIch habe sorgfältig beobachtet und festgestellt, dass nur das Wasser in meiner Wasserflasche dieses Problem zu haben schien."
  },
  AvgDialog_43775_Content_41 = {
    Text = "Vielleicht hängt es mit deinem direkten Kontakt zu diesen Monstern zusammen?"
  },
  AvgDialog_43775_Content_42 = {
    Text = "Wir werden die Ursache später untersuchen. Wir müssen dringend unseren Wasservorrat auffüllen.\nRyker?"
  },
  AvgDialog_43775_Content_43 = {
    Text = "Verstanden, verstanden. Glück ist nichts, das man so nutzen kann!\nWenn ich gewusst hätte, dass du mich zu so etwas mitbringst, hätte ich eine Kopfschmerzen vorgetäuscht und zwei Wochen Urlaub genommen."
  },
  AvgDialog_43775_Content_44 = {
    Text = "Ryker murmelte, während er seine Nase zuckte, um die Feuchtigkeit in der heißen Luft aufzufangen."
  },
  AvgDialog_43775_Content_45 = {
    Text = "Gehe nach Westen; dort gibt es bestimmt eine Wasserquelle."
  },
  AvgDialog_43775_Content_6 = {
    Text = "Ramona durchbohrte das sich nähernde verzerrte Wesen mit ihrem Schwert. Seine Tentakel zuckten ein paar Mal, bevor sie auf die Düne fielen, während die abgetrennten Gliedmaßen in den Sand sanken, als würden sie absorbiert. Innerhalb weniger Sekunden verschlangen die rollenden Sandmassen es vollständig."
  },
  AvgDialog_43775_Content_7 = {
    Text = "Nachdem alles gesagt und getan ist, gibt es in Mythags Bibliothek nur vage Aufzeichnungen über die sogenannte Legende „Der Mutterbaum“."
  },
  AvgDialog_43775_Content_8 = {
    Text = "Das Königreich Remouahe bleibt in den historischen Aufzeichnungen der Menschheit weitgehend eine leere Seite. Bis auf das gelegentliche Aram auf den Märkten weiß niemand, was sich in den Sandstürmen verbirgt."
  },
  AvgDialog_43775_Content_9 = {
    Text = "Aber Professor Alistair bestätigte die Gültigkeit der Informationen über den Mutterbaum, die von Narzisse bereitgestellt wurden."
  },
  AvgDialog_43776_Content_1 = {Text = "Vorsicht!"},
  AvgDialog_43776_Content_10 = {
    Text = "Das Monster gibt einen erschreckenden Schrei von sich, seine schleimigen Tentakeln zucken schwach, während es zuckt und sich zerlegt."
  },
  AvgDialog_43776_Content_11 = {
    Text = "Eine kleine Karawane von Kamelen tauchte auf der anderen Seite der Dünen auf, und der Jagdhund heulte, während er freudig auf die Frau zusprintete, die die Gruppe anführte."
  },
  AvgDialog_43776_Content_12 = {
    Text = "Gutes Kind, gutes Kind."
  },
  AvgDialog_43776_Content_13 = {
    Text = "Mm-hmm, ich weiß alles.\nGut gemacht, du wirst die versprochene Belohnung erhalten."
  },
  AvgDialog_43776_Content_14 = {
    Text = "Sie stieg vom Kamel ab und sah dir direkt in die Augen."
  },
  AvgDialog_43776_Content_15 = {
    Text = "Aus deiner Kleidung zu urteilen, musst du von außerhalb der Stadt sein, oder?\nIhr alle sieht müde aus von der Reise. Lemwashi muss hart für euch gewesen sein."
  },
  AvgDialog_43776_Content_16 = {
    Text = "Wasser aus dem Heiligen Fluss von Yalan zu schöpfen ist eine schicksalhafte Begegnung.\nWenn es dir nichts ausmacht, warum nicht mit mir im Yalan Camp eine Pause machen?"
  },
  AvgDialog_43776_Content_17 = {
    Text = [[
Zur gleichen Zeit
Der schwarze Pool unter Mythag]]
  },
  AvgDialog_43776_Content_18 = {
    Text = "Du gibst niemals Informationen kostenlos, noch bietest du Kredit an. Wenn Mythag die Kosten nicht bezahlt hat, hat dann jemand im Voraus bezahlt."
  },
  AvgDialog_43776_Content_19 = {
    Text = "Wer wünschte sich, dass der Hüter von Mythag in dieser Wüste erscheint?"
  },
  AvgDialog_43776_Content_20 = {
    Text = "Du kannst alle täuschen, aber dich selbst kannst du nicht täuschen."
  },
  AvgDialog_43776_Content_21 = {
    Text = "Leider fand diese Transaktion vor lange Zeit statt, weshalb ich mich nicht an das Aussehen des Gastes erinnern kann."
  },
  AvgDialog_43776_Content_22 = {
    Text = "...Ich sehe."
  },
  AvgDialog_43776_Content_23 = {
    Text = [[
Lemwashi
Heiliger Fluss]]
  },
  AvgDialog_43776_Content_24 = {
    Text = "Also, kleine Yuli, du wurdest von den Remouahe-Leitungen erweckt und bist gekommen, um Aran unter dem Ruf der Träume zu führen?"
  },
  AvgDialog_43776_Content_25 = {
    Text = "Das klingt absolut erstaunlich!"
  },
  AvgDialog_43776_Content_26 = {
    Text = "Zunächst glaubte ich es nicht ganz, aber die Träume wiederholten sich Tag für Tag.\nEs ist schwer, nicht zu helfen, wenn ich weiß, dass eine Gruppe von Menschen in der Welt auf mich als den Agenten einer Gottheit wartet, oder?"
  },
  AvgDialog_43776_Content_27 = {
    Text = "Glücklicherweise hast du auf den Ruf des Schicksals reagiert, sonst wüssten wir nicht, wie lange wir wie kopflose Hühner umhergelaufen wären!"
  },
  AvgDialog_43776_Content_28 = {
    Text = "Es ist eine Ehre für Aran, solch angesehene Gäste wie euch willkommen zu heißen."
  },
  AvgDialog_43776_Content_29 = {
    Text = "Du hilfst Ramona auf das Kamel. Nicht weit entfernt hört man von Zeit zu Zeit das Lachen und Pfeifen von Juliette und Ryker."
  },
  AvgDialog_43776_Content_3 = {
    Text = "Ramonas Gestalt schwankte, ihr Rapier wies die Krallen des Monsters kaum ab."
  },
  AvgDialog_43776_Content_30 = {
    Text = "Trotz der wiederholten Angebote der anderen Arams, sie reiten zu lassen, bestand Juliette weiterhin darauf, zu Fuß zu gehen und gab dir das Kamel."
  },
  AvgDialog_43776_Content_31 = {
    Text = "Ist seine Darbietung nicht ein bisschen übertrieben?"
  },
  AvgDialog_43776_Content_32 = {
    Text = "Jemand aus deinem Team muss die Verantwortung übernehmen, Beziehungen zu den Einheimischen aufzubauen."
  },
  AvgDialog_43776_Content_33 = {
    Text = "Seufz, dieser junge Mann, nicht nur seine Kartenspielkünste, sondern auch sein Charisma sind auf meinem Niveau."
  },
  AvgDialog_43776_Content_34 = {
    Text = "Ich hoffe, der Edel versteht die Verwendung des Begriffs \"auf Augenhöhe\" nicht falsch.\nIch erinnere mich noch an eure und Rykers frustrierten Gesichter, nachdem wir die ganze Nacht Poker gespielt haben."
  },
  AvgDialog_43776_Content_35 = {
    Text = "Als der herausragendste Schützenmeister am Kartentisch in Londinium ist es nur natürlich, sich nach einer seltenen Niederlage ein wenig niedergeschlagen zu fühlen."
  },
  AvgDialog_43776_Content_36 = {
    Text = "An diesem Tag hast du dein ganzes Geld verloren und am nächsten Tag kein Frühstück gehabt."
  },
  AvgDialog_43776_Content_37 = {
    Text = "Patienten, hört auf zu streiten und ruht euch aus."
  },
  AvgDialog_43776_Content_38 = {
    Text = "In deinen Armen wird Ramonas heisere Stimme und ein brennendes Gefühl, das sich von der Luft unterscheidet, durch die Stöße an dich übertragen."
  },
  AvgDialog_43776_Content_39 = {
    Text = "Fieber trifft dich plötzlich. Du hast ein ungutes Gefühl dabei."
  },
  AvgDialog_43776_Content_4 = {
    Text = "Und von hinten—"
  },
  AvgDialog_43776_Content_40 = {
    Text = "Sieh dort drüben."
  },
  AvgDialog_43776_Content_41 = {
    Text = "Das rastlose Schlagen breitet sich durch den Wind und den Sand aus und erzeugt mit jedem Atemzug ein unerklärliches, erstickendes Gefühl."
  },
  AvgDialog_43776_Content_42 = {
    Text = "Der Klang der Kamelglocken schwebt und dehnt sich weit und breit. Am Rand des Sichtfeldes verzerrt die Hitze die untergehende Sonne. Am Horizont erscheinen verstreute Zelte wie eine Fata Morgana."
  },
  AvgDialog_43776_Content_43 = {
    Text = "Nach Wochen des Reisens haben Sie schließlich das Ziel dieser Untersuchung gefunden—Aram."
  },
  AvgDialog_43776_Content_44 = {
    Text = "Die Aram-Siedlung ist voraus. Um sicher zu sein, werden wir uns aufteilen und separate Aktionen durchführen."
  },
  AvgDialog_43776_Content_45 = {
    Text = "Es stellt sich heraus, dass es ein paar Dinge gibt, die ich untersuchen möchte..."
  },
  AvgDialog_43776_Content_5 = {
    Text = "Ramona konnte sich nicht rechtzeitig umdrehen; die Tentakel des Monsters tauchten aus dem Sand auf und convergierten zu Spitzen, die direkt auf ihren Rücken zutiefst rannten—"
  },
  AvgDialog_43776_Content_6 = {Text = "Ding—"},
  AvgDialog_43776_Content_7 = {
    Text = "Ein riesiger Jagdhund springt von der Seite und wirft das Monster zu Boden."
  },
  AvgDialog_43776_Content_8 = {
    Text = "Das überfallene Monster streckt blutrote Tentakel aus, um den Hals des Jagdhundes zu erwürgen."
  },
  AvgDialog_43776_Content_9 = {
    Text = "Ramona rollt zurück und stößt schnell ihren Degen in das Auge des Monsters."
  },
  AvgDialog_43777_Content_10 = {
    Text = "„Der Mutterbaum des Überflusses“ ist eines der <Yellow:Drei Essenzen>—das weltliche Medium der <Yellow:Essenzen des Verlangens, Tiphreya Sode>."
  },
  AvgDialog_43777_Content_11 = {
    Text = "Die Forschung am Skelett des Mutterbaums könnte ein entscheidender Pfeiler zum Verständnis des D-Phänomens sein."
  },
  AvgDialog_43777_Content_12 = {
    Text = "Jetzt beginnt die Zeremonie zur Öffnung des Sargs offiziell."
  },
  AvgDialog_43777_Content_13 = {
    Text = "Brauchen Sie die Hilfe eines Schülers?"
  },
  AvgDialog_43777_Content_14 = {
    Text = "Kein Problem, einfach einen Sarg aufdrücken."
  },
  AvgDialog_43777_Content_15 = {
    Text = "Ich habe gehört, dass Kinder im Elke Königreich schon in jungen Jahren mit Bären ringen, also muss Dean Czort ziemlich geschickt sein."
  },
  AvgDialog_43777_Content_16 = {
    Text = "Czort trat vor, holte tief Luft, spannte seine Muskeln an und drückte mit aller Kraft —"
  },
  AvgDialog_43777_Content_17 = {
    Text = "Der Sargdeckel rührt sich nicht."
  },
  AvgDialog_43777_Content_18 = {
    Text = "Denkst du immer noch, dass du so jung bist wie früher?\nErinnerst du dich überhaupt an das letzte Mal, als du den Trainingsraum betreten hast?"
  },
  AvgDialog_43777_Content_19 = {
    Text = "Oh mein Gott, die schwere Arbeitslast des stellvertretenden Dekans ist nicht das, was Dekan Czort wünscht."
  },
  AvgDialog_43777_Content_2 = {Text = "Thais"},
  AvgDialog_43777_Content_20 = {
    Text = "Ich werde es versuchen."
  },
  AvgDialog_43777_Content_21 = {
    Text = "Dein Blick streift über den gesamten Sarg, vorbei am abblätternden schwarzen und goldenen Lack, den kunstvollen Schnitzereien, die seine Oberfläche schmücken, und den strahlenden Edelsteinen, die in seinen Ecken eingelassen sind."
  },
  AvgDialog_43777_Content_22 = {
    Text = "Du hast den Sargdeckel geschoben, aber er blieb still."
  },
  AvgDialog_43777_Content_23 = {
    Text = "Du beißt die Zähne zusammen, hebst die Hand, um an deinem Fingerspitze zu beißen, erträgst den Schmerz und schlitzest sie über den Sarg—"
  },
  AvgDialog_43777_Content_24 = {
    Text = "Mit einem donnernden Geräusch öffnete sich der Sarg allmählich."
  },
  AvgDialog_43777_Content_25 = {
    Text = "Im Inneren des Sarg liegt etwas, das einst eine Mumie war—"
  },
  AvgDialog_43777_Content_26 = {
    Text = "Einst eine Mumie, jetzt reduziert auf antike Leinenstoffe, verstreute Binden und auslaufendes schwarzes Gesöff."
  },
  AvgDialog_43777_Content_27 = {
    Text = "Schicke die Inspektionsabteilung, um die Komponenten des Sargs und der Leinentücher zu analysieren."
  },
  AvgDialog_43777_Content_28 = {
    Text = "Durch Altersprüfungen könnten wir auf den Besitzer der Mumie schließen."
  },
  AvgDialog_43777_Content_29 = {
    Text = "Nein, danke."
  },
  AvgDialog_43777_Content_3 = {
    Text = "\"Eine Woche nach dem Ende der Operation Lemwash\""
  },
  AvgDialog_43777_Content_30 = {
    Text = "Ich weiß, wer sie ist."
  },
  AvgDialog_43777_Content_31 = {
    Text = "Du berührst sanft den gravierten Text im Sarg und spürst die unebene Textur, die allmählich den vertrauten Namen bildet, der in deinem Gedächtnis eingekratzt ist."
  },
  AvgDialog_43777_Content_32 = {Text = "Thais."},
  AvgDialog_43777_Content_33 = {
    Text = "Möge sie hier Frieden finden."
  },
  AvgDialog_43777_Content_4 = {
    Text = "Ein prächtiger Sarg ruht unter Mythag. Der ewige schwarze und goldene Lack evoziert seinen Ursprung und die Geschichte, die sich dahinter verbirgt."
  },
  AvgDialog_43777_Content_5 = {
    Text = "Es ist feierlich und würdevoll, erzählt von dem verlorenen Ruhm einer einst wohlhabenden Zivilisation und hallt mit den weiten und epischen Geschichten, die du erlebt hast."
  },
  AvgDialog_43777_Content_6 = {
    Text = "Hier ist die Beute, die der Hüter in dieser \"Operation Lemwash\" beschlagnahmt hat."
  },
  AvgDialog_43777_Content_7 = {
    Text = "Der Inhalt des Sarges wird von den lokalen Aram-Nomaden als das \"Mutterbaum-Skelett\" bezeichnet."
  },
  AvgDialog_43777_Content_8 = {
    Text = "Dein Blick wandert zu dem geschnitzten Muster in der Mitte des Sargs."
  },
  AvgDialog_43777_Content_9 = {
    Text = "Das Baum-Muster ist tief in den Umschlag aus unbekanntem Material eingraviert, mit üppigem Laub und ineinander verflochtenen Wurzeln. Sein dunkler Farbton reflektiert einen vagen Glanz."
  },
  AvgDialog_43788_Content_1 = {
    Text = "Übrigens, Ryker, komm einen Moment herüber."
  },
  AvgDialog_43788_Content_10 = {
    Text = "Oh, Yuli hat tatsächlich einige einzigartige Tricks."
  },
  AvgDialog_43788_Content_100 = {
    Text = [[
Ich verstehe!
Also bist du der Reisende, der Lemwashi besucht!]]
  },
  AvgDialog_43788_Content_101 = {
    Text = "Lemwashi hatte schon lange keine neuen Gäste mehr!\nIch werde alles vorbereiten für das größte Feuerfest. Stelle sicher, dass du dich in vollen Zügen amüsierst!"
  },
  AvgDialog_43788_Content_102 = {
    Text = "Dinnerparty?"
  },
  AvgDialog_43788_Content_103 = {
    Text = "Ja! Obwohl ihnen externes Wissen fehlt, sind die Herzen der Aram-Leute nicht verschlossen."
  },
  AvgDialog_43788_Content_104 = {
    Text = "Sobald du am Festmahl teilgenommen hast, bist du ein Mitglied des Yalan-Stammes!"
  },
  AvgDialog_43788_Content_105 = {
    Text = "Als einer von uns, solange du versprichst, nicht zu verraten, was du im Lager siehst, wirst du keine Strafe erfahren."
  },
  AvgDialog_43788_Content_106 = {
    Text = "Erlebe die Gastfreundschaft des Aram-Volkes beim Festmahl!"
  },
  AvgDialog_43788_Content_11 = {
    Text = "Sobald du im Camp angekommen bist, umgibt eine Gruppe von Bewohnern in Aram-Kleidung das Kamel von Juliette."
  },
  AvgDialog_43788_Content_12 = {
    Text = "Miss Juliette ist zurückgekehrt! Holt schnell die vorbereiteten Opfergaben heraus!"
  },
  AvgDialog_43788_Content_13 = {
    Text = "Hat Miss Juliette Gäste mitgebracht?"
  },
  AvgDialog_43788_Content_14 = {
    Text = "Miss Juliette, wir haben eine Gruppe von Nubiern etwa 800 Meter im Süden entdeckt, die ungefähr dreißig zählen!"
  },
  AvgDialog_43788_Content_15 = {
    Text = "Verstanden. Ich kümmere mich eins nach dem anderen.\nIst Alva im Zelt der Königin?"
  },
  AvgDialog_43788_Content_16 = {
    Text = "Der Häuptling führte das Team, um die Situation in Nubien zu bestätigen."
  },
  AvgDialog_43788_Content_17 = {
    Text = "Verstanden. Zuerst werde ich die Gäste zur Ruhe bringen. Bitte warte in dem Zelt des Chefs auf mich."
  },
  AvgDialog_43788_Content_18 = {
    Text = "Die Aram zerstreute sich, und Juliette zog an den Zügeln, richtete sich nach dir."
  },
  AvgDialog_43788_Content_19 = {
    Text = "Wie du sehen kannst, hat der Arlan-Stamm zahlreiche Angelegenheiten zu regeln. Als ihr Gesandter helfe ich gelegentlich bei verschiedenen Aufgaben."
  },
  AvgDialog_43788_Content_2 = {Text = "Hm?"},
  AvgDialog_43788_Content_20 = {
    Text = "Allerdings benötigst du für einen Übernachtungsaufenthalt hier die Genehmigung der Königin und des Häuptlings.\nDu kannst zuerst in meinem Zelt rasten oder mit den Aram interagieren."
  },
  AvgDialog_43788_Content_21 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_43788_Content_22 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_43788_Content_23 = {
    Text = "Lass uns etwas Informationen sammeln."
  },
  AvgDialog_43788_Content_24 = {
    Text = "Laut Juliette ist der <Yellow:Mutterbaum> verdorrt, bevor die <Yellow:Sturmwand> erschien."
  },
  AvgDialog_43788_Content_25 = {
    Text = "Wegen des Verblühens des Mutterbaums sind die Nebenflüsse des Heiligen Flusses ausgetrocknet, was die Desertifikation verschärft und es vielen kleinen Dörfern schwer macht zu überleben."
  },
  AvgDialog_43788_Content_26 = {
    Text = "Dieses Team trägt das Skelett des Überfluss Mutterbaums, auf der Suche nach einer Gelegenheit, die Sturmwand zu durchdringen und den Mutterbaum wiederzubeleben."
  },
  AvgDialog_43788_Content_27 = {
    Text = "Die Monster, die als Nubia bekannt sind, sind kürzlich in Lemwash erschienen."
  },
  AvgDialog_43788_Content_28 = {
    Text = "Die Zivilisation des Volkes der Aram ist recht primitiv, und das Besiegen von Nubians Erwecker, Juliette, wird als Botschafter mit „göttlicher Kraft“ betrachtet."
  },
  AvgDialog_43788_Content_29 = {
    Text = "Halte durch, jemand kommt."
  },
  AvgDialog_43788_Content_3 = {
    Text = "Bevor du das поселение betrittst, ist es notwendig, dein Aussehen anzusprechen."
  },
  AvgDialog_43788_Content_30 = {
    Text = "Meine Damen und Herren, sind Sie gut ausgeruht?"
  },
  AvgDialog_43788_Content_31 = {
    Text = "Wenn möglich, schick bitte einen Vertreter, um die Königin zu treffen."
  },
  AvgDialog_43788_Content_32 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_43788_Content_33 = {
    Text = "Der Himmel verdunkelt sich, und der Sonnenuntergang leuchtet blutrot.\nEin Wüstenteagle kreist einige Male, stößt einen letzten Schrei aus und sitzt auf einem verdorrten Ast im Schlaf."
  },
  AvgDialog_43788_Content_34 = {
    Text = "Geführt von Juliette, erreichen Sie ein einzigartig geformtes Zelt."
  },
  AvgDialog_43788_Content_35 = {
    Text = "Dies ist das Zelt der Königin. Nach der Tradition von Aram müssen alle angesehenen Gäste die Erlaubnis des Häuptlings unter dem wachsamen Auge der Königin einholen."
  },
  AvgDialog_43788_Content_36 = {
    Text = "Warte hier auf den Chef. Ich kümmere mich zuerst um die Angelegenheiten von vorhin."
  },
  AvgDialog_43788_Content_37 = {
    Text = "Erinnere dich, gehe niemals hinein."
  },
  AvgDialog_43788_Content_38 = {
    Text = "Wenn ich die Königin beleidigen würde, gäbe es wenig, was ich tun könnte, um zu helfen."
  },
  AvgDialog_43788_Content_39 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_43788_Content_4 = {
    Text = "Dieser Weihrauch kann mit deinen persönlichen Gegenständen getragen werden, versteckt in deiner Krawatte, an deinem Stock aufgehängt oder in deinem Ohr gesteckt."
  },
  AvgDialog_43788_Content_40 = {
    Text = "Eine sanfte Brise bewegt den Vorhang leicht und gibt Einblicke in das Innere des Zeltes durch die Lücken."
  },
  AvgDialog_43788_Content_41 = {
    Text = "Ein unerklärliches Verlangen steigt in deinem Hals auf und zwingt dich, einen Blick darauf zu werfen."
  },
  AvgDialog_43788_Content_42 = {
    Text = "Aus irgendeinem Grund sagt eine Stimme in deinem Kopf, dass alles, was du suchst, in diesem Zelt verborgen ist. Du musst den Vorhang zurückziehen, um die Antwort zu enthüllen."
  },
  AvgDialog_43788_Content_43 = {
    Text = "Das Land ist karg, nur der heulende Wind trägt Sandkörner mit sich."
  },
  AvgDialog_43788_Content_44 = {
    Text = "Das Zelt betreten"
  },
  AvgDialog_43788_Content_45 = {
    Text = "Durch das Zelt spähen"
  },
  AvgDialog_43788_Content_46 = {Text = "Tu nichts"},
  AvgDialog_43788_Content_47 = {
    Text = "Du bist nicht mit dem Aram vertraut. Wenn du diese Gelegenheit verpasst, wer weiß, wann du wieder die Chance haben wirst, ihnen näher zu kommen."
  },
  AvgDialog_43788_Content_48 = {
    Text = "Kann genauso gut alles riskieren. Da niemand in der Nähe ist, hebst du vorsichtig den Vorhang und betrittst das Zelt."
  },
  AvgDialog_43788_Content_49 = {
    Text = "Nur ein kurzer Blick. Selbst wenn du erwischt wirst, gibt es einen Weg, um Ärger zu vermeiden.\nMit diesem Gedanken hebst du vorsichtig den Vorhang und spähst hinein."
  },
  AvgDialog_43788_Content_5 = {
    Text = "Ryker nahm das kleine Stück Weihrauch, streckte einen Finger aus und steckte es in die Innenseite seines linken Handschuhs."
  },
  AvgDialog_43788_Content_50 = {
    Text = "Eine plötzliche Welle von Schwindel traf dich, und die Welt kam erst nach einigen Sekunden wieder in den Fokus."
  },
  AvgDialog_43788_Content_51 = {
    Text = "Bisher weißt du sehr wenig über das Aran-Rasse.\nAus Sicherheitsgründen ist es am besten, nichts zu tun."
  },
  AvgDialog_43788_Content_52 = {
    Text = "Wie glänzende Perlen, die herabfallen, hallt ein bezauberndes Lachen von hinten.\nUnter dem Zeltlappen breitet sich ein Stück weicher, weißer Stoff aus."
  },
  AvgDialog_43788_Content_53 = {
    Text = "Eine plötzliche Welle von Schwindel traf dich, und die Welt kam erst nach einigen Sekunden wieder in den Fokus."
  },
  AvgDialog_43788_Content_54 = {
    Text = "Im Zentrum des kuppelförmigen Zeltes, auf das alle Augen gerichtet sind, ruht ein Sarg."
  },
  AvgDialog_43788_Content_55 = {
    Text = "Als ob von einer Kraft verzaubert, kamst du zu dir und fandest dich neben dem Sarg stehend, und strecktest die Hand aus, um die mit Edelsteinen besetzten goldenen Kanten zu berühren."
  },
  AvgDialog_43788_Content_56 = {
    Text = "<Gray:DAS IST —>"
  },
  AvgDialog_43788_Content_57 = {
    Text = "Du fällst in die Illusion des Baumes."
  },
  AvgDialog_43788_Content_58 = {
    Text = "Der Samen sinkt in die feuchte, fruchtbare schwarze Erde. Zarte Wurzeln und Triebe brechen durch die harte Samenschale und tauchen aus der Erde auf."
  },
  AvgDialog_43788_Content_59 = {
    Text = "Zahlreiche Äste verwandeln sich in sich windende Tentakel, die sich eine unsichtbare Leiter zum Himmel hinaufdrängen, ihre zitternden Blätter geben unheimliche Klagerufe von sich."
  },
  AvgDialog_43788_Content_6 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_43788_Content_60 = {
    Text = "Dann sind die geschwollenen Blutgefäße im Baumtumor geplatzt und spien schwarzen, viskosen Eiter aus, der in den klaren Fluss spritzte und dessen Oberfläche wie schwebendes Eis schimmerte."
  },
  AvgDialog_43788_Content_61 = {Text = "Boom!"},
  AvgDialog_43788_Content_62 = {
    Text = "Der Baum fiel mit einem Krachen, und ein Stück verrottetes Treibholz trieb flussabwärts. Seine Form ähnelte einem Sarg..."
  },
  AvgDialog_43788_Content_63 = {
    Text = "...Das ist...das Skelett des Überfluss Mutterbaums."
  },
  AvgDialog_43788_Content_64 = {
    Text = "Deine Aufgabe ist es, den örtlichen Aram-Nomaden zu folgen und den Kern des Rituals—den Mutterbaum—zu zerstören."
  },
  AvgDialog_43788_Content_65 = {
    Text = "Laut Juliette war der Mutterbaum bereits verwelkt, bevor die Sturmwand erschien."
  },
  AvgDialog_43788_Content_66 = {
    Text = "Dieses Team trägt das Skelett des Überfluss Mutterbaums, auf der Suche nach einer Gelegenheit, die Sturmwand zu durchdringen und den Mutterbaum wiederzubeleben."
  },
  AvgDialog_43788_Content_67 = {
    Text = "Mit anderen Worten, stürze dich einfach vorwärts und verbrenne das Skelett des Heiligen Baumes im Sarg, und das ultimative Ziel dieser Mission wird erreicht sein."
  },
  AvgDialog_43788_Content_68 = {
    Text = "Wie kann ich anschließend den Aram-Eingang durchbrechen? Wird es bis dahin Zeit zum Nachdenken geben?"
  },
  AvgDialog_43788_Content_69 = {
    Text = "Dein Herz pocht, verstrickt in einem komplizierten Netz aus Zustimmung und Negation."
  },
  AvgDialog_43788_Content_7 = {
    Text = "Ramona, was ist los?"
  },
  AvgDialog_43788_Content_70 = {
    Text = "Das Geräusch des Summens, wie ein Gebet, begann—"
  },
  AvgDialog_43788_Content_71 = {
    Text = "Der Tod naht, das Ende hat begonnen"
  },
  AvgDialog_43788_Content_72 = {
    Text = "Die Überreste der Mutter sind verschwunden, Blut und Samen treiben über das Land und werden von den neu geborenen Tieren verschlungen"
  },
  AvgDialog_43788_Content_73 = {
    Text = "Der Himmel ist mit dunklen Wolken bedeckt, bis die Botschafter aus dem fremden Land erscheinen"
  },
  AvgDialog_43788_Content_74 = {
    Text = "Der Heilige Fluss des Wiedergeborenen Mutterbaums krönt die Verstorbenen und bringt ihre Blutlinie zu Yalan zurück."
  },
  AvgDialog_43788_Content_75 = {
    Text = "Warum ist nur Dunkelheit vor meinen Augen?"
  },
  AvgDialog_43788_Content_76 = {
    Text = "Wer singt wieder?"
  },
  AvgDialog_43788_Content_77 = {
    Text = "Ein Gast aus der Ferne..."
  },
  AvgDialog_43788_Content_78 = {
    Text = "Ein sanftes Lachen unterbricht deine Gedanken. Du schaust auf und an einem bestimmten Punkt erscheint eine weibliche Gestalt auf dem Sarg."
  },
  AvgDialog_43788_Content_79 = {
    Text = "Mit einem Lächeln in ihren Augen hebt sie die Seiten ihres Rocks wie eine Braut und verbeugt sich, um hinunter zu dir zu schauen."
  },
  AvgDialog_43788_Content_8 = {
    Text = "Du schaust auf Rykers Gesicht."
  },
  AvgDialog_43788_Content_80 = {
    Text = "Ich bin Thais, Königin von Yaran. Hast du Tribute gebracht, Gast aus der Ferne?"
  },
  AvgDialog_43788_Content_81 = {
    Text = "Sie springt aus dem Sarg, geht direkt zu deiner Seite und umkreist dich mit einem schlauen Blick."
  },
  AvgDialog_43788_Content_82 = {
    Text = "Welche Überraschung kannst du mir bringen, kleiner {Male=Herr,Female=Frau}?"
  },
  AvgDialog_43788_Content_83 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_43788_Content_84 = {
    Text = "Juliette entschied sich, dich unter dem Blick der Königin mit mir bekannt zu machen, was bedeutet, dass du ein distinguierter Gast bist."
  },
  AvgDialog_43788_Content_85 = {
    Text = "Hat sie dir nicht gesagt, welche Strafe die Störung der Königin erwartet?"
  },
  AvgDialog_43788_Content_86 = {
    Text = "Der Vorhang des Zeltes wurde beiseite geschoben, und eine sternengesehene Aran-Frau in ihren späten Dreißigern trat in das Zelt ein."
  },
  AvgDialog_43788_Content_87 = {
    Text = "Thais springt hastig zurück auf den Sarg, nimmt eine würdevoll Haltung ein, wie eine arrogante Königin auf ihrem Thron."
  },
  AvgDialog_43788_Content_88 = {
    Text = "Lieber Gast..."
  },
  AvgDialog_43788_Content_89 = {
    Text = "Ihr betroffener Ton wurde abrupt vom Neuankömmling unterbrochen."
  },
  AvgDialog_43788_Content_9 = {
    Text = "Lord D-Dexter!"
  },
  AvgDialog_43788_Content_90 = {
    Text = "Alva, Häuptling des Aran-Stammes"
  },
  AvgDialog_43788_Content_91 = {
    Text = "Juliette erzählte mir von deinen Ursprüngen."
  },
  AvgDialog_43788_Content_92 = {
    Text = "Aber ihre Einführung lässt den entscheidenden Teil aus—Jüngster, warum bist du nach Lemwash gekommen?"
  },
  AvgDialog_43788_Content_93 = {
    Text = "Du wirst plötzlich von einem Problem getroffen, und dein Gehirn reagiert instinktiv—"
  },
  AvgDialog_43788_Content_94 = {
    Text = "Führen Sie eine wissenschaftliche Untersuchung durch"
  },
  AvgDialog_43788_Content_95 = {
    Text = "Sehenswürdigkeiten"
  },
  AvgDialog_43788_Content_96 = {
    Text = "...Gibt es wirklich keinen anderen Zweck?"
  },
  AvgDialog_43788_Content_97 = {
    Text = "Ihr durchdringender Blick bohrt sich in deine Augen, als ob sie durch deine Lügen hindurchsehen könnte."
  },
  AvgDialog_43788_Content_98 = {
    Text = "Du beruhigst deinen Geist mit großer Mühe, verbirgst deine Panik und antwortest auf ihre Frage."
  },
  AvgDialog_43788_Content_99 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_43789_Content_1 = {Text = "Siedlung"},
  AvgDialog_43789_Content_2 = {
    Text = "Ein schnelles Pferd galoppiert aus dem Lager und kommt abrupt vor Juliette zum Stehen."
  },
  AvgDialog_43789_Content_3 = {
    Text = "Alle, es scheint, dass es eine dringende Mission gibt."
  },
  AvgDialog_43789_Content_4 = {
    Text = "Die Monster, die wir gerade zurückgedrängt haben, werden von den Einheimischen als \"Nubia\" bezeichnet. Jetzt gibt es ein kleines Team, das das Lager neidisch betrachtet."
  },
  AvgDialog_43789_Content_5 = {
    Text = "Für die Sicherheit des Lagers muss ich es zuerst räumen."
  },
  AvgDialog_43789_Content_6 = {
    Text = "Wie wäre es, wenn wir zusammen gehen?"
  },
  AvgDialog_43789_Content_7 = {
    Text = "Ich hoffe, es wird euch allen nicht zu viel Mühe bereiten."
  },
  AvgDialog_43789_Content_8 = {
    Text = "Yulis Angelegenheiten sind unsere Angelegenheiten. Mach dir keine Sorgen, ein paar Nubien sind kein großes Ding."
  },
  AvgDialog_43802_Content_1 = {
    Text = "Hier ist..."
  },
  AvgDialog_43802_Content_2 = {
    Text = "Das Meer des Bewusstseins des Mutterbaums.\nIndem du vom Sarg mit den Überresten des Mutterbaums zurückverfolgst, kannst du hierher gelangen."
  },
  AvgDialog_43802_Content_3 = {
    Text = "Dieses Kind... ist den Wurzeln des Mutterbaums zu nahe gekommen, was sie zu weit von dieser Welt entfernt und unvereinbar macht."
  },
  AvgDialog_43802_Content_4 = {
    Text = "Der undulierende Klang der silbernen Wellen führt dich zu einem fernen Ufer."
  },
  AvgDialog_43802_Content_5 = {
    Text = "Kannst du den Klang hören?"
  },
  AvgDialog_43802_Content_6 = {
    Text = "Der Klang von Wassertropfen. Das Summen der Silberresonanz."
  },
  AvgDialog_43802_Content_7 = {
    Text = "Identifiziere sorgfältig."
  },
  AvgDialog_43802_Content_8 = {
    Text = "Der Schrei des Lebens. Der erste Schrei des Neugeborenen, die letzte Träne des Alten, die für das verwehende Leben vergossen wurde."
  },
  AvgDialog_43802_Content_9 = {
    Text = "Tränen verwandeln sich innerhalb von Sekunden in dreieckige Auflösungswesen und starten mit erstaunlicher Geschwindigkeit und brutaler Kraft auf dich zu."
  },
  AvgDialog_43803_Content_1 = {Text = "Festmahl"},
  AvgDialog_43803_Content_10 = {
    Text = "Du solltest dich ausruhen."
  },
  AvgDialog_43803_Content_100 = {
    Text = "Ein plötzlicher Glockenklang ertönt aus einer unbekannten Quelle und bringt dich abrupt zur Besinnung."
  },
  AvgDialog_43803_Content_101 = {
    Text = "Von Angst überwältigt, ziehst du hastig von Thais weg.\nAls du dich umdrehst, siehst du, dass sie dich immer noch aufmerksam anstarrt."
  },
  AvgDialog_43803_Content_102 = {
    Text = "Ramona setzte sich aus dem Bett, ihre kalten Pupillen starrten auf die leidenschaftliche Thais."
  },
  AvgDialog_43803_Content_103 = {
    Text = "<Change>{Male=er,Female=sie} ist nicht dein Untertan"
  },
  AvgDialog_43803_Content_104 = {
    Text = "<Change>Du kannst {Male=er,Female=sie} nicht zwingen"
  },
  AvgDialog_43803_Content_105 = {
    Text = "<Change>S...-N...igath..."
  },
  AvgDialog_43803_Content_106 = {
    Text = "Obwohl es durch Ramon'as Stimmbänder kam, verstehst du deutlich, dass es nicht ihre Sprache ist.\nEs ist die Stimme einer höheren Ebene, die in ihr wohnt."
  },
  AvgDialog_43803_Content_107 = {
    Text = [[
In Ordnung, wie geizig.
Selten, solch einen feinen Samen zu finden...]]
  },
  AvgDialog_43803_Content_108 = {
    Text = "Thais lässt widerwillig deinen Arm los, dreht sich um und verlässt das Zelt, während sie ein mehrdeutiges Murmeln zurücklässt."
  },
  AvgDialog_43803_Content_109 = {
    Text = "Wir werden uns wiedersehen.\n Beim nächsten Mal lass meine Hand nicht los."
  },
  AvgDialog_43803_Content_11 = {
    Text = "Nein, ich weiß nicht warum, aber es gibt immer eine Stimme, die mich daran erinnert, dass diese Untersuchung... von mir durchgeführt werden muss."
  },
  AvgDialog_43803_Content_12 = {
    Text = "Ramonas Ton war fest, und du hattest deine Verdachtsmomente. Es war schwer, mit ihr sowohl emotional als auch rational zu streiten."
  },
  AvgDialog_43803_Content_13 = {
    Text = "Wo ist Ryker?"
  },
  AvgDialog_43803_Content_14 = {
    Text = "Er ist draußen und versteht sich gut mit den Aram.\nDank ihm haben wir zumindest ein besseres Verständnis für diese Aram."
  },
  AvgDialog_43803_Content_15 = {
    Text = "Wie wir wissen, verschwand der Mutterbaum vor Jahren über Nacht. Seitdem hat die Sturmwand die Überreste des Mutterbaums verdeckt, der die Quelle des Heiligen Flusses ist."
  },
  AvgDialog_43803_Content_16 = {
    Text = "Vor nicht allzu langer Zeit besuchte die Gesandte der Balladen, Juliette, geleitet von Träumen. Sie zerstreute den nubischen Schwarm für den Aram und näherte sich der Sturmwand."
  },
  AvgDialog_43803_Content_17 = {
    Text = "Allerdings wurden sie beim Durchbrechen der Sturmwand behindert"
  },
  AvgDialog_43803_Content_18 = {
    Text = "Alle diese Geschichten sind in den Balladen festgehalten, die durch Generationen des Arlan-Stammes überliefert wurden."
  },
  AvgDialog_43803_Content_19 = {
    Text = "Je mehr Ramona sprach, desto blasser wurde ihr Gesicht."
  },
  AvgDialog_43803_Content_2 = {
    Text = "Lagerfeuerfest?"
  },
  AvgDialog_43803_Content_20 = {
    Text = "Doll, könntest du den Inhalt des Liedes erklären?"
  },
  AvgDialog_43803_Content_21 = {
    Text = "Ich werde dieses dumme Gedicht nicht rezitieren.\nEs gibt Experten, die besser als ich darin sind, das Gedächtnis und die Rezitation zu stabilisieren."
  },
  AvgDialog_43803_Content_22 = {
    Text = "Erica, zu Ihren Diensten—"
  },
  AvgDialog_43803_Content_23 = {
    Text = "Der Tod naht, das Ende hat begonnen"
  },
  AvgDialog_43803_Content_24 = {Text = "Warte—"},
  AvgDialog_43803_Content_25 = {
    Text = "Erica schien deinen Befehl nicht zu hören und sprach mechanisch weiter."
  },
  AvgDialog_43803_Content_26 = {
    Text = "Die Überreste der Mutter sind verschwunden, Blut und Samen treiben über das Land und werden von den neu geborenen Tieren verschlungen"
  },
  AvgDialog_43803_Content_27 = {
    Text = "Der Himmel ist mit dunklen Wolken bedeckt, bis die Botschafter aus dem fremden Land erscheinen"
  },
  AvgDialog_43803_Content_28 = {
    Text = "Gesandter—Ankunft—Knarren—Ankunft—Knarren—Hehe, Gesandter—"
  },
  AvgDialog_43803_Content_29 = {
    Text = "Eine scharfe und kalte, anorganische Stimme hallte plötzlich im Zelt wider."
  },
  AvgDialog_43803_Content_3 = {
    Text = "Juliette wirkte zögerlich."
  },
  AvgDialog_43803_Content_30 = {
    Text = "Nur einen Moment."
  },
  AvgDialog_43803_Content_31 = {
    Text = "Mechanische Alarme schrillen, gefolgt von dem Rascheln von Papier, dem Drehen von Schrauben und dem Klirren von Metall."
  },
  AvgDialog_43803_Content_32 = {
    Text = "Entschuldigung, ich habe gerade den Wartungsstatus von Erica überprüft und noch nicht die Ursache für den Fehler gefunden."
  },
  AvgDialog_43803_Content_33 = {
    Text = "Es spielt keine Rolle mehr. Das Lied hat eine letzte Zeile, und ich werde mich darum kümmern..."
  },
  AvgDialog_43803_Content_34 = {
    Text = "...Der Mutterbaum bringt den heiligen Fluss zur Wiedergeburt, krönt die Verstorbenen und bringt die Blutlinie nach Yalan zurück."
  },
  AvgDialog_43803_Content_35 = {
    Text = "Aus der Perspektive der Kommunikationseffizienz, wenn du früher erwähnt hättest, dass du bereits Bescheid weißt, hätten wir eine erhebliche Menge an Zeit sparen können."
  },
  AvgDialog_43803_Content_36 = {
    Text = "Was hast du im Zelt der Königin gesehen?"
  },
  AvgDialog_43803_Content_37 = {
    Text = "Bevor du ein Wort sagen kannst, ertönt ein enthusiastischer Ruf von draußen vor dem Zelt."
  },
  AvgDialog_43803_Content_38 = {
    Text = "Liebe Gäste, das Bankett ist bereit!"
  },
  AvgDialog_43803_Content_39 = {
    Text = "Du zögerst einen Moment, lehnst dich dann aber nah an Ramonas Ohr und flüsterst die entscheidendste Information."
  },
  AvgDialog_43803_Content_4 = {
    Text = "Ich habe bereits erwähnt, dass die Arams als primitive Stammesgruppe viele \"einzigartige\" Traditionen haben, die für Außenstehende schwer zu verstehen sein könnten."
  },
  AvgDialog_43803_Content_40 = {
    Text = "Die Überreste des heiligen Baumes befinden sich im Zelt der Königin."
  },
  AvgDialog_43803_Content_41 = {
    Text = "Du bist so attraktiv und charmant, selbst Meister Alva wäre von dir fasziniert!"
  },
  AvgDialog_43803_Content_42 = {
    Text = "Du schmeichelst mir. Ich habe gehört, dass die beste Geschichtenerzählerin hier Miss Juliette ist."
  },
  AvgDialog_43803_Content_43 = {
    Text = "Sprichst du von dem Gesandten?"
  },
  AvgDialog_43803_Content_44 = {
    Text = "Ihre Geschichte selbst ist vielleicht nicht so fesselnd wie deine Erzählung von „dem letzten Würfel“, aber das Gespräch mit dem Boten fühlt sich wirklich erfrischend an."
  },
  AvgDialog_43803_Content_45 = {
    Text = "Außerdem hat dieses „umgedrehte blinde Auge“ aus irgendeinem Grund einen unverständlich starken Reiz..."
  },
  AvgDialog_43803_Content_46 = {
    Text = "Oh, sprichst du von mir?"
  },
  AvgDialog_43803_Content_47 = {
    Text = "Medinette lobt deine Fähigkeit, Geschichten zu erzählen."
  },
  AvgDialog_43803_Content_48 = {
    Text = "Hast du etwas dagegen, wenn ich mitmache?"
  },
  AvgDialog_43803_Content_49 = {
    Text = "Natürlich nicht, meine Dame."
  },
  AvgDialog_43803_Content_5 = {
    Text = "Das Lagerfeuer-Bankett ist eines der typischsten Beispiele."
  },
  AvgDialog_43803_Content_50 = {
    Text = "In letzter Zeit sind Überfälle aus Nubien häufiger geworden. Es ist Zeit für die Feuerzeremonie."
  },
  AvgDialog_43803_Content_51 = {
    Text = "Neue Kunden sind ein gutes Zeichen, also sei nicht niedergeschlagen!\nKomm schon, trink zuerst ein paar Gläser!"
  },
  AvgDialog_43803_Content_52 = {
    Text = "Gäste, trinkt mehr!\nGenießt das Festmahl. Wir werden das Beste zubereiten, um unsere geschätzten Gäste zu bewirten!"
  },
  AvgDialog_43803_Content_53 = {Text = "Prost!"},
  AvgDialog_43803_Content_54 = {
    Text = "Ich trinke keinen Alkohol."
  },
  AvgDialog_43803_Content_55 = {
    Text = "Du hebst dein Glas und stoßt mit dem enthusiastischen Aram an."
  },
  AvgDialog_43803_Content_56 = {
    Text = "In dem Moment hast du heimlich die Flüssigkeit aus seiner Tasse gegossen."
  },
  AvgDialog_43803_Content_57 = {
    Text = "Das Skelett des Mutterbaums befindet sich in einem Zelt, weniger als hundert Meter von dir entfernt. Jetzt ist nicht die beste Zeit für Freizeit."
  },
  AvgDialog_43803_Content_58 = {
    Text = "Was für ein Bedauern! Eine Zeremonie mit ein wenig Alkohol ist die beste!"
  },
  AvgDialog_43803_Content_59 = {
    Text = "Egal wie sehr die Aram überzeugen, du verweigerst einfach."
  },
  AvgDialog_43803_Content_6 = {
    Text = "Die spezifischen Details... wirst du heute Abend erfahren."
  },
  AvgDialog_43803_Content_60 = {
    Text = "Das Skelett des Mutterbaums befindet sich in einem Zelt, weniger als hundert Meter von dir entfernt. Jetzt ist nicht die beste Zeit für Freizeit."
  },
  AvgDialog_43803_Content_61 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_43803_Content_62 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_43803_Content_63 = {
    Text = "Während die Betrunkenheit von Aram stärker wird, erreicht die Atmosphäre des Festes ihren Höhepunkt."
  },
  AvgDialog_43803_Content_64 = {
    Text = "Mehrere Alan-Krieger hoben die Frauen von Alan auf ihre Schultern und führten sie durch den Veranstaltungsort."
  },
  AvgDialog_43803_Content_65 = {
    Text = "Die beschwipsten Frauen pflückten glitzernde Trauben und warfen sie mit ungebremstem Lachen in die Menge."
  },
  AvgDialog_43803_Content_66 = {
    Text = "Whoosh~ Hierher, hierher, gib mir auch zwei!"
  },
  AvgDialog_43803_Content_67 = {
    Text = "Die Frau schien Rykers Ruf zu hören, führte die Krieger zu ihm und sprang dann in seine Arme."
  },
  AvgDialog_43803_Content_68 = {
    Text = "Nein, nein, mein kleiner Körper kann das nicht ertragen..."
  },
  AvgDialog_43803_Content_69 = {
    Text = "Bevor Ryker zu Ende spricht, lässt die Szene vor dir euch alle sprachlos zurück."
  },
  AvgDialog_43803_Content_7 = {
    Text = "......Also ist das Migrationsziel der Aram auch die Ruinen des Mutterbaums?"
  },
  AvgDialog_43803_Content_70 = {
    Text = "Die Frau riss ihren Umhang ab und drückte sich ganz nackt an Ryker."
  },
  AvgDialog_43803_Content_71 = {
    Text = "Ihre Aktionen schienen wie ein Befehl; alle Aram-Leute begannen, sich auszuziehen und ihre Waffen abzulegen, wodurch die Szene zu einem Ozean der Dekadenz wurde."
  },
  AvgDialog_43803_Content_72 = {
    Text = "Als du siehst, dass Ryker reglos ist, stürzt die Frau ohne zu zögern auf den Aram-Krieger neben ihr zu und stöhnt auf eine Weise, die das Gesicht erröten lässt."
  },
  AvgDialog_43803_Content_73 = {Text = "?!"},
  AvgDialog_43803_Content_74 = {
    Text = "Komm, schließ dich uns an und genieße den ultimativen Spaß am Lagerfeuer!"
  },
  AvgDialog_43803_Content_75 = {
    Text = "Lauf! Lauf! Komm zurück zu Ramonás Zelt!"
  },
  AvgDialog_43803_Content_76 = {
    Text = "Ihr Geist wird leer, während Sie Ryker's Worte folgen und verzweifelt auf Ramona zurennen... nein, fliehen."
  },
  AvgDialog_43803_Content_77 = {
    Text = "Draußen vor dem Zelt war die Frau, die sich um Ramona kümmern sollte, nirgends zu sehen."
  },
  AvgDialog_43803_Content_78 = {
    Text = "Ramona ist derzeit bei Bewusstsein mit hohem Fieber und kann daher den Wahnsinn des Rituals nicht miterleben. Vielleicht ist das ein Segen in Verkleidung."
  },
  AvgDialog_43803_Content_79 = {Text = "Das ist"},
  AvgDialog_43803_Content_8 = {
    Text = "Ja, sie können auch die Sturmwand nicht durchbrechen."
  },
  AvgDialog_43803_Content_80 = {
    Text = [[
Lagerfeuerritual. Wahrscheinlich...
Das Aram-Lagerfeuerritual ist ein primitiver Paarungsbrauch.]]
  },
  AvgDialog_43803_Content_81 = {
    Text = "Dieser Ort... ist ein bisschen weit vom Zeremonienort entfernt. Ich werde draußen Wache halten, um zu verhindern, dass andere sich nähern."
  },
  AvgDialog_43803_Content_82 = {
    Text = "Du bleibst zurück, um Ramona zu betreuen."
  },
  AvgDialog_43803_Content_83 = {
    Text = "Diese Primitiven... Wahnsinnige."
  },
  AvgDialog_43803_Content_84 = {
    Text = "Im Vergleich zu dem Lärm draußen im Zelt war es drinnen ungewöhnlich ruhig, mit nur Ramonas leicht schwerem Atem, der durch hohes Fieber verursacht wurde."
  },
  AvgDialog_43803_Content_85 = {
    Text = "Die obszönen Murmeln des entfernten Rituals dringen durch die schwere Leinwand und stören deinen Geist."
  },
  AvgDialog_43803_Content_86 = {Text = "...Ryker?"},
  AvgDialog_43803_Content_87 = {
    Text = "Wie schade. War ich nicht derjenige, auf den du dich gefreut hast?"
  },
  AvgDialog_43803_Content_88 = {
    Text = "Königin von Aran – Thais zog den Vorhang zurück und trat ein. Sie näherte sich ohne Zögern, der dünne Schleier schmiegte sich an deinen Unterarm und machte eine direkte Einladung."
  },
  AvgDialog_43803_Content_89 = {
    Text = "Komm, akzeptiere das Blut von Arlan und werde einer von uns."
  },
  AvgDialog_43803_Content_9 = {
    Text = "Keeper, du bist hier. Puppe und ich besprechen die nächsten Schritte."
  },
  AvgDialog_43803_Content_90 = {
    Text = "Komm näher, umarme mich... Gib mir dein Blut, dein Wesen..."
  },
  AvgDialog_43803_Content_91 = {
    Text = "Die Flammen flackern in ihren leidenschaftlichen Pupillen, ihre geröteten Wangen offenbaren ein morbidens Verlangen."
  },
  AvgDialog_43803_Content_92 = {
    Text = "Ein einziger Tropfen reicht aus. Solange unser Knochenfleisch verschmilzt, wird Er uns die Zukunft gewähren, die wir uns wünschen..."
  },
  AvgDialog_43803_Content_93 = {
    Text = "Lass uns... Nachkommen für den Stamm zeugen, teilend in der Ewigkeit..."
  },
  AvgDialog_43803_Content_94 = {
    Text = "Dein Verstand sagt dir, abzulehnen. Du weißt nichts über den Alan-Stamm, und dieses wahnsinnig gefüllte Ritual könnte dich überallhin führen."
  },
  AvgDialog_43803_Content_95 = {
    Text = "Aber deine Glieder gehorchen nicht. Diese verführerische Stimme übernimmt die Kontrolle über deinen Körper und deine Seele und weckt deine primalen Wünsche und Triebe."
  },
  AvgDialog_43803_Content_96 = {
    Text = "Obwohl du keinen Tropfen Alkohol berührt hast, fühlst du dich betrunken. Die Welt erscheint in deinen trunkenen Augen schön verschwommen und ätherisch, mit nur dem Ruf aus dem Ursprung des Lebens, der verweilt."
  },
  AvgDialog_43803_Content_97 = {
    Text = "Reproduzieren, reproduzieren."
  },
  AvgDialog_43803_Content_98 = {
    Text = "<RedBig:Verbreite, verbreite!>"
  },
  AvgDialog_43803_Content_99 = {
    Text = "<Big: Säe die Samen in die Erde, lass <Red:Blutlinie> durch Kadath fließen!>"
  },
  AvgDialog_43804_Content_1 = {
    Text = "Kein Grund, dir Sorgen zu machen. Obwohl Lord Alva streng ist, ist sie ziemlich vernünftig."
  },
  AvgDialog_43804_Content_2 = {
    Text = "In einer Weile lade ich euch alle zu meinem Zelt ein, um eine ausführliche Diskussion zu führen.\nAber zuerst sollten wir diese Nubier zur Seite schaffen."
  },
  AvgDialog_43804_Content_3 = {
    Text = "Ich habe deine Fähigkeiten gesehen. Diese Unreinheiten abzuschütteln, sollte ein Kinderspiel sein, oder?"
  },
  AvgDialog_43805_Content_1 = {
    Text = "Proliferation"
  },
  AvgDialog_43805_Content_10 = {
    Text = "Der Lärm draußen hat aufgehört."
  },
  AvgDialog_43805_Content_11 = {
    Text = "Besuche den Hauptmann Alva."
  },
  AvgDialog_43805_Content_12 = {
    Text = "Geh diskutiere mit Juliette."
  },
  AvgDialog_43805_Content_13 = {
    Text = "Ja, im Kreis zu laufen, ist nicht die Lösung."
  },
  AvgDialog_43805_Content_14 = {
    Text = "Ryker schob den Vorhang beiseite, zuckte zusammen und erstarrte."
  },
  AvgDialog_43805_Content_15 = {
    Text = "Was ist los, Ryker?"
  },
  AvgDialog_43805_Content_16 = {
    Text = "Ryker reagierte nicht, also bist du neugierig hinter ihm hergegangen."
  },
  AvgDialog_43805_Content_17 = {
    Text = "Er atmete tief ein, ein heiserer Laut entkam seiner Kehle."
  },
  AvgDialog_43805_Content_18 = {
    Text = "Du... bleib vorerst zurück."
  },
  AvgDialog_43805_Content_19 = {
    Text = "Unmöglich, Ryker, wir können nicht in diesem Zelt gefangen sein..."
  },
  AvgDialog_43805_Content_2 = {
    Text = "Wann bin ich... eingeschlafen?"
  },
  AvgDialog_43805_Content_20 = {
    Text = "Dein Ton ist stagnierend geworden."
  },
  AvgDialog_43805_Content_21 = {
    Text = "Ryker hat recht, du hättest das nicht sehen sollen.\nAber die Tragödie fixierte deine Pupillen und machte es unmöglich, wegzusehen."
  },
  AvgDialog_43805_Content_22 = {
    Text = "Es ist ein Blut-Höllen, eine Katastrophe der Fortpflanzung, ein grotesker Albtraum, der sich gegen die menschliche Ethik richtet und natürliche Gesetze verletzt."
  },
  AvgDialog_43805_Content_23 = {
    Text = "Selbst das schmutzigste Rattenloch könnte das gegenwärtige Chaos nicht einfangen. Neugeborene, weiche Gliedmaßen und Plazenten sind zu grotesken Formen verwoben, während rotes Fluid in die Textur der Wüste sickert."
  },
  AvgDialog_43805_Content_24 = {
    Text = "Die Luft ist dick vom Gestank von Körperflüssigkeiten und einem seelenpiercenden Hauch von Rost, der einem den Brechreiz beschert."
  },
  AvgDialog_43805_Content_25 = {
    Text = "Der Wind hebt die Zeltklappe des Lagers der Königin, und Thais tritt langsam heraus."
  },
  AvgDialog_43805_Content_26 = {
    Text = "Sie hob ihre Hand und deutete auf den fernen Horizont, der durch Dünen segmentiert ist. Als sie sich bewegte, brachen die ersten Strahlen der aufgehenden Sonne durch."
  },
  AvgDialog_43805_Content_27 = {
    Text = "In einem Moment brachen aus zahllosen Zelten die Schreie von Babys hervor und webten eine Symphonie neuen Lebens."
  },
  AvgDialog_43805_Content_28 = {
    Text = "Aber du fühlst keine Freude der Wiedergeburt in dir, nur eine knochenkalte Kälte von Kopf bis Fuß."
  },
  AvgDialog_43805_Content_29 = {
    Text = "In letzter Zeit sind Überfälle aus Nubien häufiger geworden. Es ist Zeit für die Feuerzeremonie."
  },
  AvgDialog_43805_Content_3 = {
    Text = "Draußen ist alles still. Der seltsame und verstörte Wahnsinn von letzter Nacht fühlt sich wie ein verflogener Albtraum an."
  },
  AvgDialog_43805_Content_30 = {
    Text = "Das war keine moralboostende Zeremonie, sondern eine Zuchtveranstaltung zur Auffrischung der Truppen.\nWas betrachten sie das Leben als? Eine Art Überlebenswerkzeug?"
  },
  AvgDialog_43805_Content_31 = {
    Text = "Laut Aufzeichnungen ist die Kraft der Lustessenz mit Fortpflanzung und Fruchtbarkeit verbunden."
  },
  AvgDialog_43805_Content_32 = {
    Text = "Der Mutterbaum ist an der Quelle des Karigay-Flusses verwurzelt, bekannt als der Heilige Fluss, bereichert den Boden beider Ufer und verleiht dem Aram-Volk außergewöhnliche Fortpflanzungsfähigkeit."
  },
  AvgDialog_43805_Content_33 = {
    Text = "Vom Heiligen Fluss genährt, hat die Aran-Blutlinie durch die Generationen in der rauen Lemwahi-Wüste überdauert."
  },
  AvgDialog_43805_Content_34 = {
    Text = "Nähren, Fruchtbarkeit, Kontinuität... Die Verkörperung dieser liebevollen Worte ist so schmutzig und grausam."
  },
  AvgDialog_43805_Content_35 = {
    Text = "Jetzt liegen zwei Wege vor uns."
  },
  AvgDialog_43805_Content_36 = {
    Text = "Setze die Aram-Einheiten fort oder breche auf und finde deinen eigenen Weg, um das Missionsziel zu erreichen."
  },
  AvgDialog_43805_Content_37 = {
    Text = "Das vornehme Wegwerfen von deformierten Föten auf der Jagd nach extremer Fortpflanzungsgeschwindigkeit ist gleichbedeutend mit kollektivem Mord in einer zivilisierten Gesellschaft. Ich weiß, dass es dir schwerfallen wird, das zu ignorieren."
  },
  AvgDialog_43805_Content_38 = {
    Text = "Zudem gibt es ein Geheimnis in dieser Szene – hast du die Proportion der missgebildeten Föten bemerkt?"
  },
  AvgDialog_43805_Content_39 = {
    Text = "Der Mutterbaum gewährt dem Aram-Volk die Fähigkeit, über Nacht zu empfangen und zu gebären, aber warum ist das Verhältnis normaler Geburten weniger als eins zu zehn?"
  },
  AvgDialog_43805_Content_4 = {
    Text = "Ich weiß nicht. Als ich aufwachte, hast du schon geschlafen."
  },
  AvgDialog_43805_Content_40 = {
    Text = "Sieh, aus der Perspektive des Mythag Ermittlers und Detektivs ist der erste die offensichtliche Wahl. \nWir müssen dem Ziel und der Wahrheit am nächsten bleiben, oder?"
  },
  AvgDialog_43805_Content_41 = {
    Text = "Bevor du reagieren kannst, springen die Truppen in Aktion. Vom Zelt des Anführers aus eilen die Aram-Leute umher und rufen vor mehreren Zelten. Dann verlassen alle ihre Zelte und beginnen sich auszurüsten."
  },
  AvgDialog_43805_Content_42 = {
    Text = "Was ist passiert?"
  },
  AvgDialog_43805_Content_43 = {
    Text = "Nubianer! Eine Horde von Nubianern greift das Lager an, und die vorderen Wächter können sie nicht aufhalten!"
  },
  AvgDialog_43805_Content_44 = {
    Text = "Was für ein Zufall! Das Bankett ist gerade zu Ende, und Nubia hat einen Angriff gestartet?"
  },
  AvgDialog_43805_Content_45 = {
    Text = "Wer weiß? Es ist immer wie das. Dieses verdammte Biest lässt uns nie entspannen!"
  },
  AvgDialog_43805_Content_46 = {
    Text = "Du solltest auch rennen! Niemand kann sich jetzt um dich kümmern!"
  },
  AvgDialog_43805_Content_47 = {
    Text = "Wir müssen Alva sehen. Wo ist sie?"
  },
  AvgDialog_43805_Content_48 = {
    Text = "Der Häuptling leitet an der Vorderfront!"
  },
  AvgDialog_43805_Content_49 = {
    Text = "Linke Spalte, versammelt euch! Die Migration ist nicht abgeschlossen, lasst keinen Nubien durch!"
  },
  AvgDialog_43805_Content_5 = {
    Text = "Wo ist Ryker?"
  },
  AvgDialog_43805_Content_50 = {
    Text = "Nain, halte dir die Seite! Wenn du dich schwach fühlst, überfordere dich nicht; lass Wajet übernehmen!"
  },
  AvgDialog_43805_Content_51 = {
    Text = [[
Was machst du hier? 
Siehst du nicht, dass die Frontlinie mitten im Kampf ist?]]
  },
  AvgDialog_43805_Content_52 = {
    Text = "Der Aram-Stamm heißt Gäste, die \"Samen\" nicht tragen wollen, nicht willkommen. Bitte treffe deine eigenen Entscheidungen!"
  },
  AvgDialog_43805_Content_53 = {
    Text = "Lord Alva, darf ich ein paar Worte sagen?"
  },
  AvgDialog_43805_Content_54 = {
    Text = "%player% ist unbeabsichtigt in das Zelt der Königin geraten, und Ihre Majestät hat sich nicht darüber geärgert, oder?"
  },
  AvgDialog_43805_Content_55 = {
    Text = "Wenn man es genau nimmt, trage ich auch eine Mitschuld, weil ich {Male=er,Female=sie} ohne klare Anweisungen im Königinnenzelt warten ließ"
  },
  AvgDialog_43805_Content_56 = {
    Text = "Du starrst Juliette benommen an. Ihre Augen zittern, und sie schüttelt sanft den Kopf, als würde sie dich stumm daran erinnern, nicht zu sprechen."
  },
  AvgDialog_43805_Content_57 = {
    Text = "Du weißt nicht, warum sie dich beschützt, aber du hast keinen Grund, ihre Hilfe abzulehnen."
  },
  AvgDialog_43805_Content_58 = {
    Text = "Die Angriffe der Nubier sind in letzter Zeit häufiger geworden. Sie könnten helfen, gegen diese Übel zu kämpfen."
  },
  AvgDialog_43805_Content_59 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_43805_Content_6 = {
    Text = "Ramona deutete auf die Zeltür."
  },
  AvgDialog_43805_Content_60 = {
    Text = "Lasst sie dir folgen."
  },
  AvgDialog_43805_Content_61 = {
    Text = "Behalte sie im Auge. Lass mich nicht sehen, dass sie in der Nähe des Hauptzeltes sind.\nAndernfalls wird es nicht so einfach sein, aus dem Lager geworfen zu werden."
  },
  AvgDialog_43805_Content_7 = {
    Text = "Ryker schlief an der Tür, offenbar durch deine Bewegung geweckt. Seine pelzigen Ohren zuckten schnell, seine Wimpern flatterten zweimal und er öffnete seine schmalen Wolfaugen."
  },
  AvgDialog_43805_Content_8 = {
    Text = "Gestern... das Ritual, das war kein Traum, oder?"
  },
  AvgDialog_43805_Content_9 = {
    Text = "Um das gentlemanlike Verhalten Londiniums aufrechtzuerhalten, sollte ich nicht unüberlegt die Lebensstile anderer kritisieren, aber diese primitiven Rituale sind einfach zu viel."
  },
  AvgDialog_43806_Content_1 = {
    Text = "Wenn mehr von diesen großen Jungs auf einmal kommen, wird mein alter Rücken das wirklich nicht aushalten können."
  },
  AvgDialog_43806_Content_10 = {
    Text = "Warte, ist das—"
  },
  AvgDialog_43806_Content_11 = {
    Text = "Ein Mann zog Nubia gebunden über den Sand. Der Wind des Sandmeeres blies ihm den Kapuzenmantel von der schwarzen Robe, und das kalte Mondlicht ließ sein goldenes Haar schimmern."
  },
  AvgDialog_43806_Content_12 = {
    Text = "Senior William!"
  },
  AvgDialog_43806_Content_2 = {
    Text = "Laut Alva sind dies nur die Anführer kleiner Gruppen. Die wirkliche Bedrohung ist wahrscheinlich viel erschreckender."
  },
  AvgDialog_43806_Content_3 = {
    Text = "Sag nichts. Lass mich so tun, als ob ich bis zum Aufprall nichts wüsste, und genieße noch ein paar sorglose Tage."
  },
  AvgDialog_43806_Content_4 = {
    Text = "Es ist noch nicht an der Zeit, nachzulassen! %player%, schau mal da drüben!"
  },
  AvgDialog_43806_Content_5 = {
    Text = "Die unheimlichen Silhouetten, die du bereits leid bist zu sehen, tauchen hinter den Dünen der Nacht auf und torkeln auf dich zu."
  },
  AvgDialog_43806_Content_6 = {
    Text = "Sind noch Nachzügler übrig?"
  },
  AvgDialog_43806_Content_7 = {
    Text = "Komm schon, lass dich auch die Freude über eine drei Spiele währende Siegesserie genießen!"
  },
  AvgDialog_43806_Content_8 = {
    Text = "Nein, irgendetwas fühlt sich immer noch falsch an—"
  },
  AvgDialog_43806_Content_9 = {
    Text = "Bei genauerer Betrachtung bewegen sich diese Nubien außergewöhnlich langsam und steif."
  },
  AvgDialog_43807_Content_1 = {Text = "Pfad"},
  AvgDialog_43807_Content_10 = {
    Text = "So wie im Kampf..."
  },
  AvgDialog_43807_Content_11 = {
    Text = "Fehlgeschlagen."
  },
  AvgDialog_43807_Content_12 = {
    Text = "Ich denke, ihr beiden Kinder könnt es kaum erwarten, die Erklärung von eurem Senior zu hören."
  },
  AvgDialog_43807_Content_13 = {
    Text = "William stellte seine Brille ein und nickte dir zu."
  },
  AvgDialog_43807_Content_14 = {
    Text = "Dies ist das einzige vollständige Nubien-Muster, das wir bisher gesammelt haben."
  },
  AvgDialog_43807_Content_15 = {
    Text = "Bis zu diesem Jahr gab es kaum Sichtungen von Nubien. Es erschien kürzlich in der Remouahe-Wüste, breitete sich aber schnell aus und drang in das Territorium von Aram ein."
  },
  AvgDialog_43807_Content_16 = {
    Text = "Biologische Mutation allein kann seinen Ursprung nicht erklären; künstliche Modifikation passt besser zu den Umständen und dem Zeitpunkt seines Auftretens."
  },
  AvgDialog_43807_Content_17 = {
    Text = "So meinst du, dass jemand Nubia erschafft?"
  },
  AvgDialog_43807_Content_18 = {
    Text = "William nickte, anscheinend zufrieden mit deiner Vermutung."
  },
  AvgDialog_43807_Content_19 = {
    Text = "Außerdem wird die Quelle absichtlich verborgen. Das Schneiden eines Teils von Nubien wird dazu führen, dass es schnell Tentakeln nach innen ausbreitet, um die Wunde zu reparieren, und Narben im Inneren hinterlässt."
  },
  AvgDialog_43807_Content_2 = {
    Text = "Im rauen, primitiven Zeltzentrum steht der erschlaffte Körper von Nubien wie ein schwarzer Fleischberg, das düstere Licht lässt selbst die Schatten unheimlich erscheinen."
  },
  AvgDialog_43807_Content_20 = {
    Text = "Wenn es durch einen tödlichen Schlag verletzt wird, wird es schnell gasförmig und verschwindet, ohne Spuren zur Untersuchung zu hinterlassen.\nMan muss wissen, dass gewöhnlicher D-Schleim normalerweise nicht in so kurzer Zeit von selbst verschwindet."
  },
  AvgDialog_43807_Content_21 = {
    Text = "Was verbirgt der \"Designer\" dieser Leute?"
  },
  AvgDialog_43807_Content_22 = {
    Text = "Im Vergleich zu ihrer inneren Struktur bin ich mehr an Nubias Bewegungsmustern interessiert."
  },
  AvgDialog_43807_Content_23 = {
    Text = "Ich habe in letzter Zeit Informationen von Aram gesammelt. Laut ihrer Beschreibung wird die zuvor stationäre nubische Herde das Lager angreifen, wann immer sie anhalten, mehrere Tage campieren oder Zeremonien abhalten."
  },
  AvgDialog_43807_Content_24 = {
    Text = "Mein Bauchgefühl sagt mir, dass diese Nubier die Aram in eine bestimmte Richtung treiben."
  },
  AvgDialog_43807_Content_25 = {
    Text = "William nahm die Karte heraus und markierte jeden dichten Punkt in Nubien."
  },
  AvgDialog_43807_Content_26 = {
    Text = "Berücksichtige auch die Migrationswege der Aram."
  },
  AvgDialog_43807_Content_27 = {
    Text = "Ryker steckte den roten Baumwollfaden mit einer Nadel fest und zog einen Pfad entlang der Punkte, die von den Aram-Leuten angegeben wurden."
  },
  AvgDialog_43807_Content_28 = {
    Text = "Ein schwarzer Schatten folgt dicht hinter der roten Linie und drängt sie Schritt für Schritt zur Quelle des Heiligen Flusses."
  },
  AvgDialog_43807_Content_29 = {
    Text = "Deine Intuition war schon immer treffsicher."
  },
  AvgDialog_43807_Content_3 = {
    Text = "William holte ein Set von präzisen chirurgischen Werkzeugen aus den Falten seiner Beinschläuche: ein Skalpell, eine chirurgische Schere, feinzahnige Zangen und hämostatische Klemmen, alle wie ein Stahlsquad angeordnet."
  },
  AvgDialog_43807_Content_30 = {
    Text = "Die Quelle des Heiligen Flusses, verborgen innerhalb der Sturmwand."
  },
  AvgDialog_43807_Content_31 = {
    Text = "Jemand möchte nicht, dass die Aram außerhalb der Sturmwand verweilen. Er drängt ihren Lebensraum zusammen und zwingt sie in die Sturmwand."
  },
  AvgDialog_43807_Content_32 = {
    Text = "Die Umrisse des Falls sind erschienen. Das Motiv (whydunit) und die Methode (howdunit) wurden enthüllt."
  },
  AvgDialog_43807_Content_33 = {
    Text = "So ist die Frage, wer es getan hat (wer der Mörder ist)?"
  },
  AvgDialog_43807_Content_34 = {
    Text = "Zu wenige Hinweise, um vorerst einen Schluss zu ziehen.\nLass uns unsere jüngsten Beobachtungen synchronisieren. Hinweise können immer bei der Urteilsfindung helfen."
  },
  AvgDialog_43807_Content_35 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_43807_Content_36 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_43807_Content_37 = {
    Text = "Wir benötigen mehr Informationen über Nubien."
  },
  AvgDialog_43807_Content_38 = {
    Text = "Ihre Hauptmission bleibt unverändert: Untersuchen Sie die Wahrheit hinter dem Skelett des Mutterbaums im Lager der Königin und nutzen Sie die Gelegenheit, es zu zerstören."
  },
  AvgDialog_43807_Content_39 = {
    Text = "Ich werde meine Forschung über Nubien fortsetzen."
  },
  AvgDialog_43807_Content_4 = {
    Text = "Ich habe nicht erwartet, dass du das herumträgst. Planst du, auf das Retten von Leben umzusteigen?"
  },
  AvgDialog_43807_Content_40 = {
    Text = "Ich habe das Gefühl, dass die Wahrheit über Aram und den Mutterbaum hinter den Ursprüngen von Nubien verborgen ist."
  },
  AvgDialog_43807_Content_41 = {
    Text = "Als William sprach, drehte er sich um und hob den Umhang auf."
  },
  AvgDialog_43807_Content_42 = {
    Text = "Geht Senior William?"
  },
  AvgDialog_43807_Content_43 = {
    Text = "Abreise vor der Morgendämmerung.\nStelle sicher, dass Juliette von meinen Bewegungen nichts erfährt."
  },
  AvgDialog_43807_Content_44 = {
    Text = "William hebt den Vorhang und tritt hinaus, dreht sich um, um euch alle zu erinnern, und wäre fast mit der Person zusammengestoßen, die sich nähert."
  },
  AvgDialog_43807_Content_45 = {
    Text = "Seit unserer Begegnung am Heiligen Fluss scheine ich viele Annehmlichkeiten bereitgestellt zu haben, ohne Schaden zuzufügen. Warum sind Sie so misstrauisch gegenüber mir, Mr. William?"
  },
  AvgDialog_43807_Content_46 = {
    Text = "Die Luft im engen Zelt war angespannt, und niemand antwortete. Der einst glühende Wüstenwind fühlte sich jetzt seltsam kühl an."
  },
  AvgDialog_43807_Content_47 = {
    Text = "Mehrere Sekunden später war es immer noch Juliette, die dieStille brach."
  },
  AvgDialog_43807_Content_48 = {
    Text = "Nur ein Witz, kein Grund, so angespannt zu sein."
  },
  AvgDialog_43807_Content_49 = {
    Text = "Miss Juliette übertreibt. Wir sind auf dieser Reise alle gut miteinander ausgekommen. Es ist nur so, dass Herr William ein wenig introvertiert ist und nicht gerne mit Fremden interagiert..."
  },
  AvgDialog_43807_Content_5 = {
    Text = "William ignorierte deinen Scherz, runzelte die Stirn und machte den ersten Schnitt mit Vorsicht."
  },
  AvgDialog_43807_Content_50 = {
    Text = "Ryker redete wirr, und du bemerktest, dass Ramona auf der Schlafunterlage lag und nicht anders konnte, als mit den Augen zu rollen."
  },
  AvgDialog_43807_Content_51 = {
    Text = "Ähem, also, Fräulein Juliette, gibt es etwas Wichtiges, das Sie so spät in der Nacht besprechen müssen?"
  },
  AvgDialog_43807_Content_52 = {
    Text = "Es ist nicht gerade entscheidend—komm, lass uns in meinem Zelt reden."
  },
  AvgDialog_43807_Content_6 = {
    Text = "Das Skalpell schnitt in Nubias Körper, aber kein schwarzes Gelee floss wie erwartet heraus."
  },
  AvgDialog_43807_Content_7 = {
    Text = "Williams Nerven waren gespannt, als er langsam die Klinge hineinführte und dann nach unten schnitt—"
  },
  AvgDialog_43807_Content_8 = {Text = "Zzzap—"},
  AvgDialog_43807_Content_9 = {
    Text = "Das durchbohrte Nubien verwandelte sich sofort in einen Pool aus schwarzem Schlamm und verdampfte in einem Augenblick, sodass der Operationstisch makellos blieb, als ob er nie kontaminiert worden wäre."
  },
  AvgDialog_43808_Content_1 = {
    Text = "Die Stimmen, die in diesem mentalen Raum versammelt sind, sind das kollektive Bewusstsein aller Aram-Völker, von der Antike bis zur Gegenwart."
  },
  AvgDialog_43808_Content_10 = {
    Text = "Juliette kniete neben der Wiege und summte andächtig ein Lied."
  },
  AvgDialog_43808_Content_11 = {
    Text = "Ihr Summen enthält keine Texte, doch du erkennst die Melodie."
  },
  AvgDialog_43808_Content_12 = {
    Text = "Sie hob die Wickel und tauchte sie in den Heiligen Fluss."
  },
  AvgDialog_43808_Content_13 = {
    Text = "Der Quicksand begrub schnell das neu verlorene Leben."
  },
  AvgDialog_43808_Content_14 = {
    Text = "Der Tod naht, das Ende hat begonnen"
  },
  AvgDialog_43808_Content_15 = {
    Text = "Das schöne und melancholische Lied trägt einen Hauch von Traurigkeit, fließt mit dem heiligen Flusswasser, das in die Ferne windet."
  },
  AvgDialog_43808_Content_16 = {
    Text = "4:00 AM Reisendenzelt"
  },
  AvgDialog_43808_Content_17 = {
    Text = "Lass mich zusammenfassen:"
  },
  AvgDialog_43808_Content_18 = {
    Text = "Für die Aram, wenn der Mutterbaum nicht wiederbelebt wird, wird der Heilige Fluss austrocknen und Remouahe wird zu einer völlig kargen Wüste werden."
  },
  AvgDialog_43808_Content_19 = {
    Text = "Juliette hat vor, den Mutterbaum wiederzubeleben und die Aram zu leiten, um sich an das moderne Leben anzupassen und es zu akzeptieren."
  },
  AvgDialog_43808_Content_2 = {
    Text = "Weinen die Aram...?"
  },
  AvgDialog_43808_Content_20 = {
    Text = "Aber die Quelle der Narzisse hat uns gesagt, dass, wenn der Mutterbaum wiederbelebt wird, eine globale Auflösung ausbrechen könnte."
  },
  AvgDialog_43808_Content_21 = {
    Text = "Die Überreste des heiligen Baumes sind im Zelt der Königin. Sie zu zerstören, bevor man die Sturmwand betritt, sollte die Aufgabe mit minimalen Kosten abschließen."
  },
  AvgDialog_43808_Content_22 = {
    Text = "Also, wie vertrauenswürdig ist dieser Händler Daffodil in Ihren Augen? Sind ihre Quellen zuverlässig?"
  },
  AvgDialog_43808_Content_23 = {
    Text = "Alistair gab sein Bestes, bestätigte jedoch nur, dass jemand diese Nachricht absichtlich gesendet hatte. Die Genauigkeit der Nachricht konnte nicht bewertet werden."
  },
  AvgDialog_43808_Content_24 = {
    Text = "Das rücksichtlose Verbrennen der Überreste des Heiligen Baums könnte den letzten Rückzug von Aram abschneiden."
  },
  AvgDialog_43808_Content_25 = {
    Text = "Wir haben keinen Rückzug vor der Auflösung.\nLass nicht zu, dass vergebliche Mitgefühle dein Urteilsvermögen trüben."
  },
  AvgDialog_43808_Content_26 = {
    Text = "Es ist in Ordnung, Puppe. Selbst wenn wir den Ritualort stürmen und den Mutterbaum am Ende verbrennen müssen, werde ich bei dir sein."
  },
  AvgDialog_43808_Content_27 = {
    Text = "Ich stimme der Ansicht des Hüters zu; wir wissen sehr wenig über Arlan, und jetzt einen Angriff zu starten wäre unklug."
  },
  AvgDialog_43808_Content_28 = {
    Text = "Meine Forschung zu Nubien wird fortgesetzt.\nHüter, Ryker, die Untersuchung der Überreste des heiligen Baumes liegt in deinen Händen."
  },
  AvgDialog_43808_Content_3 = {
    Text = "Ja, die Seelen der Aram weinen.\nFür die Sünden des Lebens und die Angst vor dem Tod."
  },
  AvgDialog_43808_Content_4 = {
    Text = "Wenn ich das Aram durch die Sturmwand führen und den Mutterbaum finden kann...\nDas Aram wird mich als ihren neuen Anführer ansehen."
  },
  AvgDialog_43808_Content_5 = {
    Text = "Bis dahin werde ich diesem verfluchten und morbiden Ritual ein Ende setzen und die Aram für immer aus dieser trostlosen und rauen Wüste befreien."
  },
  AvgDialog_43808_Content_6 = {
    Text = "Jeder wird sich in ein reines und unberührtes Land niederlassen, frei von den Leiden, die durch die angeborene Sünde verursacht werden."
  },
  AvgDialog_43808_Content_7 = {
    Text = "%player%, bitte leihe mir deine Kraft."
  },
  AvgDialog_43808_Content_8 = {
    Text = "Du erwachst aus dem Traum und stellst fest, dass das Kind auf Juliette's Brust nicht mehr atmet"
  },
  AvgDialog_43808_Content_9 = {
    Text = "Lass ihn den Heiligen Fluss zurückgeben."
  },
  AvgDialog_43809_Content_1 = {
    Text = "Ursprung Fluss"
  },
  AvgDialog_43809_Content_10 = {
    Text = "Juliette kraulte sanft das flauschige Haar des Jungen."
  },
  AvgDialog_43809_Content_11 = {
    Text = "In Ordnung, wenn ihr Hilfe braucht..."
  },
  AvgDialog_43809_Content_12 = {
    Text = "Der junge Junge schaute dich misstrauisch an."
  },
  AvgDialog_43809_Content_13 = {
    Text = "Fühlen Sie sich frei, mich jederzeit zu wecken."
  },
  AvgDialog_43809_Content_14 = {
    Text = "Der Junge ging. Juliette schenkte dir ein entschuldigendes Lächeln."
  },
  AvgDialog_43809_Content_15 = {
    Text = "Es tut mir leid, er hat etwas übertrieben mit der Pflege."
  },
  AvgDialog_43809_Content_16 = {
    Text = "Du hast es erraten. Er ist derjenige, der unter diesen Kindern am schnellsten gewachsen ist."
  },
  AvgDialog_43809_Content_17 = {
    Text = "Im Gegensatz dazu..."
  },
  AvgDialog_43809_Content_18 = {
    Text = "Juliette führt dich zu einer groben Wiege."
  },
  AvgDialog_43809_Content_19 = {
    Text = "Sieh dir dieses Kind an."
  },
  AvgDialog_43809_Content_2 = {
    Text = "2:00 AM Gesandtenlager"
  },
  AvgDialog_43809_Content_20 = {
    Text = "Das war ein Säugling, der in Wickeltücher gehüllt war, mit baumartigen, dunklen Mustern, die seinen gesamten Körper bedeckten."
  },
  AvgDialog_43809_Content_21 = {
    Text = "An der Oberfläche zeigt es keine Deformitäten, aber in Wirklichkeit ist es bereits von der Krankheit des Mutterbaums infiziert."
  },
  AvgDialog_43809_Content_22 = {
    Text = "Versuche, deine Hand auf seine Haut zu legen."
  },
  AvgDialog_43809_Content_23 = {
    Text = "Du berührst die Haut des Kindes wie angewiesen. Es ist nicht die zarte, glatte Haut eines Babys, die du erwartet hast; stattdessen fühlt sie sich rau und rissig an, wie trockene Rinde."
  },
  AvgDialog_43809_Content_3 = {
    Text = "Das Zelt des Gesandten ist mit Bettzeug gefüllt, und mehrere Kinder im Alter von fünf oder sechs Jahren sind auf den Betten zusammengerollt und schlafen.\nEin lebhafter junger Junge nähert sich dir."
  },
  AvgDialog_43809_Content_4 = {
    Text = "Lady Juliette, du bist zurückgekehrt."
  },
  AvgDialog_43809_Content_5 = {
    Text = [[
Neferure, mein lieber Kind.
Hat jeder die Gelegenheit gehabt, sich auszuruhen?]]
  },
  AvgDialog_43809_Content_6 = {
    Text = "Ja, Lady Juliette."
  },
  AvgDialog_43809_Content_7 = {
    Text = "Diese Kinder sind..."
  },
  AvgDialog_43809_Content_8 = {
    Text = "Bis heute hattest du unter den Aram keine Minderjährigen gesehen."
  },
  AvgDialog_43809_Content_9 = {
    Text = [[
Nephry, du solltest dich jetzt ausruhen.
Es war nicht einfach, alle zum Schlafen zu bringen. Lord Alva wird dich morgen belohnen.]]
  },
  AvgDialog_43816_Content_1 = {
    Text = "Unerwartetes Feuer"
  },
  AvgDialog_43816_Content_10 = {
    Text = "Eine glatte männliche Stimme zielt auf dich — das benommene Ich, das unbeholfen unter dem Scheinwerferlicht stümpert."
  },
  AvgDialog_43816_Content_11 = {
    Text = "Die Mädchen um mich strecken ihre Körper wie Schwäne, ihre Tanzschritte sind synchron und zeigen rhythmische Schönheit."
  },
  AvgDialog_43816_Content_12 = {
    Text = "Jemand verhielt sich wie eine wilde Ente, die in eine Gruppe von Schwänen geraten ist."
  },
  AvgDialog_43816_Content_13 = {
    Text = "Du erkennst schnell, dass dies der Körper einer Tänzerin ist—aber das Gedächtnis des Körpers ist noch nicht vollständig zurückgekehrt. Sogar das Gehen ist tollpatschig, geschweige denn das Erinnern an diese komplexen Tanzschritte."
  },
  AvgDialog_43816_Content_14 = {
    Text = "Alles, was du tust, ist, Ärger zu verursachen. Du bist wirklich ein \"kompetenter\" Chef."
  },
  AvgDialog_43816_Content_15 = {
    Text = "Häuptling? Ich bin... der Häuptling..."
  },
  AvgDialog_43816_Content_16 = {
    Text = "Niemand antwortete auf deine Frage. Die Tänzer bewegten sich weiter, gleiten geschickt in Formation an dir vorbei – doch irgendwie schlug dir ein Ellenbogen hart zu."
  },
  AvgDialog_43816_Content_17 = {
    Text = "Du stolperst und verlierst dein Gleichgewicht, wirst an den Rand der Bühne gedrängt, während sich die Tanzformation verschiebt, aber du kannst dem scharfen Blick des Publikums nicht entkommen—"
  },
  AvgDialog_43816_Content_18 = {
    Text = "Unter der Bühne gibt es keine angeordneten Publikumssitze. Stattdessen sind Paare von Tischen und Stühlen in dem weiten offenen Raum platziert."
  },
  AvgDialog_43816_Content_19 = {
    Text = "Der Tischbezug ist ein prunkvoller Seidensamt mit Fransen, und die Juwelen des Publikums reflektieren im Dunkeln das Bühnenlicht, sodass die maskierten Gesichter noch unheimlicher wirken."
  },
  AvgDialog_43816_Content_2 = {
    Text = "Eins, zwei, drei, eins, zwei, drei... Ausgezeichnet, die Formation ist sehr ordentlich und elegant."
  },
  AvgDialog_43816_Content_20 = {
    Text = "Was ist mit dem Kind in der ersten Reihe? Ist es an die falsche Stelle gesprungen?"
  },
  AvgDialog_43816_Content_21 = {
    Text = "Hmph... Ob sie gut oder schlecht tanzen, ist ihnen einfach egal. Verstehst du nicht, um welche Art von Menschen es sich handelt?"
  },
  AvgDialog_43816_Content_22 = {
    Text = "In der Tat. Um ehrlich zu sein, sind ihre Sprünge nicht großartig, aber ihre Figur ist wirklich..."
  },
  AvgDialog_43816_Content_23 = {
    Text = "<Small:Diese Leute scheinen keine gewöhnlichen Zuschauer des Tanzes zu sein...>"
  },
  AvgDialog_43816_Content_24 = {
    Text = "Wofür starrst du ins Leere?!"
  },
  AvgDialog_43816_Content_25 = {
    Text = "Eine sanftmütige, gepflegte Hand greift nach deinem nackten Arm und versucht, dich in die Schatten der Bühnenvorhänge zu ziehen."
  },
  AvgDialog_43816_Content_26 = {
    Text = "Du hast fast den Tanz ruiniert! Dies ist die letzte Probe vor der offiziellen Aufführung. Was hast du dir dabei gedacht!"
  },
  AvgDialog_43816_Content_27 = {
    Text = "Entschuldigung, ich... ich..."
  },
  AvgDialog_43816_Content_28 = {
    Text = "Der Klang des Instruments hämmert gegen dein Trommelfell, die Sicht wird dunkel, die Tanzschritte sind im Nebel der Erinnerungen gefangen. Die Ziehbewegung des Mannes gibt dir eine Chance, und du nutzt den Schwung, um die Bühne zu verlassen—"
  },
  AvgDialog_43816_Content_29 = {
    Text = "Verlasse nicht. Nachdem ich auf der Bühne bin, brauche ich Leute, um die Formation auszubalancieren.\nFülle die Lücke hinten links in der Schlange und ahme meine Tanzbewegungen nach."
  },
  AvgDialog_43816_Content_3 = {
    Text = "Streicher und Holzbläser spielen im Hintergrund, verschmelzen mit dem Klang von Schritten zu einem ordentlichen und eleganten Geräusch, das lebhaft auf den Sinnen tanzt."
  },
  AvgDialog_43816_Content_30 = {
    Text = "Die Hand des Mannes wurde weggehauen. In seinen überraschten und erfreuten Augen ergriff eine blasse, schlanke Hand deinen Hüften und zog dich ins Licht."
  },
  AvgDialog_43816_Content_31 = {
    Text = "Mit anmutigen Schritten nutzte die Person geschickt ihre Tanzbewegungen, um die bereits verstreute Formation auseinanderzudrängen und dich gewaltsam in die Gruppe der Tänzer einzufügen."
  },
  AvgDialog_43816_Content_32 = {
    Text = "Die Tänzerinnen tauschen Blicke aus, aber niemand wagt es, über das Verhalten des Mädchens zu sprechen. Sie schnauben nur über dich, senken dann die Köpfe und tanzen weiter."
  },
  AvgDialog_43816_Content_33 = {
    Text = "Schnell! Beleuchte sie! Elizabeth ist endlich bereit, auf der Bühne zu tanzen! Dies ist ihr erstes Erscheinen seit drei Monaten!"
  },
  AvgDialog_43816_Content_34 = {Text = "Elizabeth?"},
  AvgDialog_43816_Content_35 = {
    Text = "Du wälzt den Namen in deinem Kopf und versuchst, das Mädchen anzusehen, das dich ohne ein Wort auf die Bühne gezogen hat."
  },
  AvgDialog_43816_Content_36 = {
    Text = "Als du nach oben schaust, schießt plötzlich ein Licht im zweiten Stock in deinem Sichtfeld auf und durchbricht es mit einem blendenden Strahl, der deine Welt in unkontrollierbares Weiß taucht."
  },
  AvgDialog_43816_Content_37 = {
    Text = "—Als ich meine Augen wieder öffnete, war das Mädchen im schwarzen Tanzkleid bereits nach vorne gesprungen."
  },
  AvgDialog_43816_Content_38 = {
    Text = "Jeder machte Platz für ihren Eintritt und ließ Raum für ihren Rock, um zu wehen.\nAuf dieser kleinen Bühne ist sie die fesselnde Hexe, der absolute Star."
  },
  AvgDialog_43816_Content_39 = {
    Text = "Das ist Elizabeth, die Stargasttänzerin der Adry Tanzgruppe... Mein Gott, sie ist wunderschön."
  },
  AvgDialog_43816_Content_4 = {
    Text = "Was ist das für ein Klang...?"
  },
  AvgDialog_43816_Content_40 = {
    Text = "Manager, hat Miss Eliza nicht gesagt, dass sie sich unwohl fühlt und bei dieser Aufführung nicht anwesend sein wird?"
  },
  AvgDialog_43816_Content_41 = {
    Text = "Meine Damen und Herren, dies ist... eine Überraschung, die Elizabeth für euch alle vorbereitet hat! Ja, eine Überraschung."
  },
  AvgDialog_43816_Content_42 = {
    Text = "Trotz ihrer Krankheit wird Elizabeth als Direktorin dieses neuen Stücks nicht zulassen, dass eine Bühnenaufführung misslingt!"
  },
  AvgDialog_43816_Content_43 = {
    Text = "Der Truppenleiter puffte stolz seine Brust heraus, seine Augen scannten umher wie ein wachsamer Kampfhahn."
  },
  AvgDialog_43816_Content_44 = {
    Text = "Der Spitzenschuh der Tänzerin traf mit schwerem Schritt die Bühne und zog deine Aufmerksamkeit auf sie."
  },
  AvgDialog_43816_Content_45 = {
    Text = "Ein Paar kalte grüne Augen schielte über dich. Im nächsten Moment, als ob dein Körper eingeschüchtert wäre, wurde dein Muskelgedächtnis aktiviert. Innerhalb von Momenten trug dich dein Körper in die Gruppe der Tänzer."
  },
  AvgDialog_43816_Content_46 = {
    Text = "Das ist richtig... Gut gemacht."
  },
  AvgDialog_43816_Content_47 = {
    Text = "Werde ein Blatt am Baum, vermeide ihren Blick und lass sie dich nie wieder sehen."
  },
  AvgDialog_43816_Content_48 = {
    Text = "Lass diese dreckigen Blicke... dich nicht bemerken."
  },
  AvgDialog_43816_Content_5 = {
    Text = "Durch Musik aus einem tiefen Schlaf erweckt, streckten sich meine schwachen Gliedmaßen instinctiv, doch meine Augen fühlten sich außergewöhnlich schwer an."
  },
  AvgDialog_43816_Content_6 = {
    Text = "Die oberen und unteren Augenlider sind fest zusammengepresst, und egal wie sehr du es versuchst, du kannst sie nicht einmal einen Spalt offenhalten."
  },
  AvgDialog_43816_Content_7 = {
    Text = "Ugh... Dieses Gefühl... in einen Traum eintreten..."
  },
  AvgDialog_43816_Content_8 = {
    Text = "In derohrenbetäubenden Musik gewinnt dein Bewusstsein allmählich Kontrolle über deinen Körper. Gerade als deine Augen das Licht wahrnehmen, versteifen sich plötzlich deine Gliedmaßen."
  },
  AvgDialog_43816_Content_9 = {
    Text = "Tolle Sprünge, Mädchen. Haltet den Rhythmus und bleibt im Takt—hey! Lasst die Konzentration nicht nachlassen!"
  },
  AvgDialog_44435_Content_1 = {
    Text = "Bitterer Fluch"
  },
  AvgDialog_44435_Content_2 = {
    Text = "Gedenken strömen mit dem Sternenlicht herein."
  },
  AvgDialog_44435_Content_3 = {
    Text = "Jene Gedenken, künstlich erschaffen und durch Gewalt zerschmettert, strömten in Masons Geist und wichen dann rasch zurück wie die Gezeiten."
  },
  AvgDialog_44435_Content_4 = {
    Text = "Bis ganz zum Ende gelangte sie an den Fuß des Schneebergs, zum Eingang einer pechschwarzen Höhle."
  },
  AvgDialog_44435_Content_5 = {
    Text = "Folge dem Fluss, der unter deinen Füßen fließt, um das Lager des schlummernden Biests zu erreichen."
  },
  AvgDialog_44435_Content_6 = {
    Text = "Klopf, klopf. Klopf, klopf."
  },
  AvgDialog_44435_Content_7 = {
    Text = "Das ist wie das Ticken einer alten Uhr. Der gemeinsame Herzschlag von ihr und dem Biest"
  },
  AvgDialog_44435_Content_8 = {
    Text = "Ich verstehe jetzt..."
  },
  AvgDialog_44435_Content_9 = {
    Text = "Ich verstehe alles"
  },
  AvgDialog_44436_Content_1 = {
    Text = "Warum... warum..."
  },
  AvgDialog_44436_Content_10 = {
    Text = "Diejenigen, die Glück in einem einfachen Leben finden, sind „24\"."
  },
  AvgDialog_44436_Content_11 = {
    Text = "Gequält von der Bildhauer-Gilde, das ist ebenfalls „24\"."
  },
  AvgDialog_44436_Content_12 = {
    Text = "Nein... wenn es nicht für deine Schwäche gewesen wäre, wären wir nicht von diesem Arzt"
  },
  AvgDialog_44436_Content_13 = {Text = "Pssst..."},
  AvgDialog_44436_Content_14 = {
    Text = "Mason bedeckte sanft die Lippen des Schattens. Sie beugte sich hinunter und flüsterte ihm ins Ohr."
  },
  AvgDialog_44436_Content_15 = {
    Text = "Hier ist ein Geheimnis: <Red:Dieser Doktor wurde von mir getötet.>"
  },
  AvgDialog_44436_Content_16 = {
    Text = "Wie hast du den Mut dazu...?!"
  },
  AvgDialog_44436_Content_17 = {
    Text = "Mord ist keine schwierige Angelegenheit. Ich habe keine Waffen zur Hand, also habe ich seinen Kopf wie eine Walnuss zertrümmert"
  },
  AvgDialog_44436_Content_18 = {
    Text = "Am Ende waren meine Hände taub, und alles, was ich sehen konnte, war Blut."
  },
  AvgDialog_44436_Content_19 = {
    Text = "Ich musste sicherstellen, dass er vollständig tot ist. Solange er noch atmet, wird er den Kindern des Waisenhauses und Jenkin sicher Schaden zufügen..."
  },
  AvgDialog_44436_Content_2 = {
    Text = "Der Schatten wurde von euch besiegt. In der Bewusstseinswelt liegt sie am Boden, und kleine Lichtpunkte schweben von ihrem Körper weg"
  },
  AvgDialog_44436_Content_20 = {
    Text = "Er ist genau wie die Leute in der Bildhauer-Gilde, nein — er ist sogar noch furchteinflößender..."
  },
  AvgDialog_44436_Content_21 = {
    Text = "Er ist ein wahrer Dämon."
  },
  AvgDialog_44436_Content_22 = {
    Text = "Was habe ich damals nur getan... Ich wusste von nichts..."
  },
  AvgDialog_44436_Content_23 = {
    Text = "Mason schüttelte sanft den Kopf."
  },
  AvgDialog_44436_Content_24 = {
    Text = "Du weißt es eigentlich, es ist der Mut, den du und die anderen „24\" mir geliehen haben"
  },
  AvgDialog_44436_Content_25 = {
    Text = "Alle „24\" zusammen ergeben einen „Mason\". Keine „24\" kann isoliert existieren"
  },
  AvgDialog_44436_Content_26 = {
    Text = "So wie alle Flüsse an einem Ort zusammenfließen, werden auch alle „24\" an einem Ort zusammenfließen..."
  },
  AvgDialog_44436_Content_27 = {
    Text = "Mason küsste sanft die Stirn des Schattens."
  },
  AvgDialog_44436_Content_28 = {
    Text = "Es gehört zu mir."
  },
  AvgDialog_44436_Content_29 = {
    Text = "Der Körper des Schattens verwandelt sich in Sternenlicht, das sich um Mason verstreut und in ihre Haut übergeht."
  },
  AvgDialog_44436_Content_3 = {
    Text = "Wie konnte jemand so Mächtiges und Wütendes wie ich... gegen dich verlieren, gegen diese Feigling verlieren..."
  },
  AvgDialog_44436_Content_30 = {
    Text = "Ich verstehe... Ich verstehe es jetzt."
  },
  AvgDialog_44436_Content_31 = {
    Text = "Du bist der Ursprung von allem und auch das Ende von allem..."
  },
  AvgDialog_44436_Content_32 = {
    Text = "In der warmen Umarmung verlor sie allmählich ihre Stimme."
  },
  AvgDialog_44436_Content_33 = {
    Text = "Sternenlicht flackert wie Glühwürmchen in der Nacht, erscheint und verschwindet, bis es schließlich vergeht."
  },
  AvgDialog_44436_Content_34 = {
    Text = "... Gute Nacht, mein „Eins von Vierundzwanzig \""
  },
  AvgDialog_44436_Content_35 = {
    Text = "<Yellow:Ermittlungsprotokoll künstliches Labyrinth IV>\n\n■Geheimgang–ID: M–C06\n■Fallzeit: Jahr 315 der Flut, Dezember @1\n■Fallort: Camberwell Street, Ostviertel"
  },
  AvgDialog_44436_Content_36 = {
    Text = "<Yellow: Untersuchungsergebnisse I>\n\nDer Bereich endete auf eine ausgeglichene Weise.\nDanach stabilisierte sich der Zustand von Miss Mason erheblich, was alle sehr erfreute.\nWir nähern uns allmählich der wahren Miss Mason"
  },
  AvgDialog_44436_Content_37 = {
    Text = "Misaq Universität, Sekretariat\nEinen Tag später"
  },
  AvgDialog_44436_Content_38 = {
    Text = "Was? Der Prüfungsausschuss hat die Anklage zurückgezogen?"
  },
  AvgDialog_44436_Content_39 = {
    Text = "Ja. Sie sind jetzt damit beschäftigt, zusammen mit den Leuten vom städtischen Umweltamt die Schlangenplage zu beseitigen"
  },
  AvgDialog_44436_Content_4 = {Text = "Weil..."},
  AvgDialog_44436_Content_40 = {
    Text = "Schlangenplage...?"
  },
  AvgDialog_44436_Content_41 = {
    Text = "Zwinkern breitet die letzten Ausgaben der „Londinium Post\" vor dir aus"
  },
  AvgDialog_44436_Content_42 = {
    Text = "„Kürzlich tauchte ein plötzlicher Schwarm von Albinonattern unbekannter Art aus der Klinik des verstorbenen Dr. Bernard auf und verursachte schwere Störungen des örtlichen Verkehrs und des täglichen Lebens...“"
  },
  AvgDialog_44436_Content_43 = {
    Text = "„Augenzeugen berichten, dass dies die schrecklichste Szene ist, die sie je in ihrem Leben gesehen haben. Wenn die Leser ebenfalls das Unglück hatten, dies live zu erleben, sind sie herzlich eingeladen, den Psychologen @2 um Hilfe zu bitten...“"
  },
  AvgDialog_44436_Content_44 = {
    Text = "„Nummer@4...“"
  },
  AvgDialog_44436_Content_45 = {
    Text = "Neben der Nachricht befindet sich ein Foto, auf dem du ein paar bekannte Gesichter vom Prüfungsausschuss zu erkennen scheinst."
  },
  AvgDialog_44436_Content_46 = {
    Text = "Sie tragen Masken und Netze, mühsam die ständig auftauchenden Schlangen beseitigend, mit unverhohlener Müdigkeit und Ungeduld im Gesicht"
  },
  AvgDialog_44436_Content_47 = {
    Text = "Das sogenannte „Doktor Bernard\" ist ein großes Problem"
  },
  AvgDialog_44436_Content_48 = {
    Text = "Wir haben jemanden von der Königlichen Medizinischen Gesellschaft gefunden. Die Beschreibung des Mannes unterscheidet sich völlig von dem, was William gesehen hat"
  },
  AvgDialog_44436_Content_49 = {
    Text = "Mit anderen Worten, der Verstorbene hat die Identität dieses Dr. Bernard gestohlen. Es ist jedoch noch unklar, ob dieser falsche Arzt wirklich tot ist."
  },
  AvgDialog_44436_Content_5 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_44436_Content_50 = {
    Text = "Immerhin lässt sich am Tatort nicht einmal eine Spur einer Leiche finden..."
  },
  AvgDialog_44436_Content_51 = {
    Text = [[
17. Dez., Der Tag des Vorfalls
Dr. Bernards Klinik]]
  },
  AvgDialog_44436_Content_52 = {
    Text = "Die heutige Behandlung ist abgeschlossen. Fräulein Mason, Sie erholen sich gut."
  },
  AvgDialog_44436_Content_53 = {
    Text = "Wirklich? Aber alle sagen, mein Zustand verschlechtere sich..."
  },
  AvgDialog_44436_Content_54 = {
    Text = "Meine Auffassung von \"ernst\" unterscheidet sich wohl von ihrer. Hast du die Tinkturen regelmäßig eingenommen?"
  },
  AvgDialog_44436_Content_55 = {Text = "Krach—!!"},
  AvgDialog_44436_Content_56 = {
    Text = "Der Mann stieß versehentlich die Akten neben sich um, die vergilbten Seiten breiteten sich auf dem Boden aus"
  },
  AvgDialog_44436_Content_57 = {
    Text = "Sie sind der fleißige Arzt, solche kleinen Aufgaben können Sie einfach überlassen"
  },
  AvgDialog_44436_Content_58 = {Text = "Ich denke"},
  AvgDialog_44436_Content_59 = {
    Text = "Die Hand stoppte knapp 2 Zoll vor den Akten. Es war ein Stapel Identitätsdokumente, Mason erkannte mühsam einige vertraute Wörter"
  },
  AvgDialog_44436_Content_6 = {
    Text = "Lass mich mich darum kümmern."
  },
  AvgDialog_44436_Content_60 = {
    Text = "Versuchsbericht, Transferaufzeichnung...?"
  },
  AvgDialog_44436_Content_61 = {
    Text = "<Shake:Das sind... die vermissten Kinder aus dem Waisenhaus! Nein, es ist noch schlimmer...>"
  },
  AvgDialog_44436_Content_62 = {
    Text = "In der Ecke der aufgeschlagenen Akte ganz unten sah Mason Jenkins leicht trotziges Gesicht."
  },
  AvgDialog_44436_Content_63 = {
    Text = "Ist das deine Schwester? Ich habe sie gesehen. Sie macht sich immer Sorgen um dich und hat sogar versucht, sich einzuschleichen."
  },
  AvgDialog_44436_Content_64 = {
    Text = "Er lächelte schwach, sein Ausdruck wurde sanft."
  },
  AvgDialog_44436_Content_65 = {
    Text = "Ich hatte einst viele Geschwister... Sie fürchteten mich nur, also habe ich sie alle verschlungen."
  },
  AvgDialog_44436_Content_66 = {
    Text = "Alle... aufgefressen?"
  },
  AvgDialog_44436_Content_67 = {
    Text = "Mach dir keine Sorgen, Miss Mason. Ich habe die Kinder nicht gefressen, sondern nur an einen <Red:sicheren Ort> gebracht"
  },
  AvgDialog_44436_Content_68 = {
    Text = "Also bist du der Drahtzieher hinter diesen Vermisstenfällen"
  },
  AvgDialog_44436_Content_69 = {
    Text = "<Shake:Dieser Witz ist überhaupt nicht lustig, Herr Bernard...>"
  },
  AvgDialog_44436_Content_7 = {
    Text = "Mason setzte sich neben den Schatten und hielt den reglosen Schatten in ihren Armen."
  },
  AvgDialog_44436_Content_70 = {
    Text = "Herr Bernard... Meinst du das hier?"
  },
  AvgDialog_44436_Content_71 = {
    Text = "Der Mann sprach und streckte eine lange Zunge aus seinem Mund, die sich um einen blutigen abgetrennten Finger wickelte."
  },
  AvgDialog_44436_Content_72 = {
    Text = "Er ist zu groß; ich kann ihn immer noch nicht verarbeiten."
  },
  AvgDialog_44436_Content_73 = {
    Text = "Lasst uns einander neu vorstellen. Ich bin <Yellow:Albino>, der Apotheker der Bildhauer-Gilde."
  },
  AvgDialog_44436_Content_74 = {
    Text = "Aaaaaah—!!"
  },
  AvgDialog_44436_Content_75 = {
    Text = "Masons Beine gaben nach, und er stürzte schwer zu Boden."
  },
  AvgDialog_44436_Content_76 = {
    Text = "Du willst... du willst auch Jenkins"
  },
  AvgDialog_44436_Content_77 = {
    Text = "Der Mann richtete seine Brille und notierte schnell etwas in der Krankenakte."
  },
  AvgDialog_44436_Content_78 = {
    Text = "Pupillen geweitet, Körper zittert heftig, Herzrasen... Du musst gerade extrem verängstigt sein. Ist dir kalt?"
  },
  AvgDialog_44436_Content_79 = {
    Text = "Nein... Bleib zurück..."
  },
  AvgDialog_44436_Content_8 = {
    Text = "Weil... du nicht alle „24\" akzeptiert hast."
  },
  AvgDialog_44436_Content_80 = {
    Text = "Sehr bald wirst du wegen mangelnder Gehirndurchblutung ohnmächtig, wie die anderen langweiligen Menschen"
  },
  AvgDialog_44436_Content_81 = {
    Text = "Er hob den Kopf von der Krankenakte, ein schwaches Glimmen der Erregung flackerte in seinen goldenen, vertikalen Pupillen."
  },
  AvgDialog_44436_Content_82 = {
    Text = "Oder... wirst du anders reagieren?"
  },
  AvgDialog_44436_Content_83 = {
    Text = "20 Minuten später"
  },
  AvgDialog_44436_Content_84 = {
    Text = "Ich habe jemanden getötet... Ich habe tatsächlich einen Arzt getötet... Die werden mir nicht glauben..."
  },
  AvgDialog_44436_Content_85 = {
    Text = "Nein, warum habe ich ihn einfach getötet...?"
  },
  AvgDialog_44436_Content_86 = {
    Text = "Mason schreckte aus seiner Benommenheit auf und verließ hastig den Tatort."
  },
  AvgDialog_44436_Content_87 = {
    Text = "Der Körper des Mannes sackte gegen die Wand. Sein Kopf war bereits zertrümmert, und Blut sickerte unaufhörlich heraus."
  },
  AvgDialog_44436_Content_88 = {
    Text = "Nach einer unbestimmten Zeit leuchteten plötzlich eine Reihe schwarzer Fluchzeichen am Hals der Leiche auf."
  },
  AvgDialog_44436_Content_89 = {
    Text = "Die Fluchfesseln drehen sich langsam wie Schlangen, und das zu Brei zerquetschte Fleisch beginnt sich zusammenzufügen und neu zu formen..."
  },
  AvgDialog_44436_Content_9 = {
    Text = "Getrieben von Verzweiflung und ohne jemanden, an den man sich wenden kann, das ist „24\"."
  },
  AvgDialog_44436_Content_90 = {
    Text = "Am Ende richtete sich die „Leiche“ langsam auf."
  },
  AvgDialog_44436_Content_91 = {
    Text = "Puh... Nicht schlecht, die Tinkturen haben gewirkt. Ihr Potenzial wurde vollständig entfesselt."
  },
  AvgDialog_44436_Content_92 = {
    Text = "Albino streckte seine lange Schlangenzunge heraus und leckte sich gemächlich das Blut vom Gesicht."
  },
  AvgDialog_44436_Content_93 = {
    Text = "Die Beute ist gereift. Es ist Zeit, unserem Gildenmeister Bericht zu erstatten."
  },
  AvgDialog_44436_Content_94 = {
    Text = "Er hob die Krankenakte zu seinen Füßen auf und ging gemächlich davon."
  },
  AvgDialog_44437_Content_1 = {
    Text = "Goldener Refrain"
  },
  AvgDialog_44437_Content_10 = {
    Text = "Die fahle Stille des Meeres wird durchbrochen, als eine dunkel purpurschwarze Seeschlange plötzlich hervorschießt und alle fest umschlingt."
  },
  AvgDialog_44437_Content_11 = {
    Text = "Hmm... Aaaahhh!!"
  },
  AvgDialog_44437_Content_12 = {
    Text = "Mit einem leisen Zischen verwandelt sich der Körper der Schlange in eine pechschwarze Klinge, die die Person vollständig durchbohrt."
  },
  AvgDialog_44437_Content_13 = {
    Text = "<Big:Komm nicht näher>......Hä?"
  },
  AvgDialog_44437_Content_15 = {
    Text = "Ein sanftes, kühles Gefühl geht von dem Hals aus, um den sich die schwarze Schlange windet, und heilt allmählich die Wunde."
  },
  AvgDialog_44437_Content_16 = {
    Text = "Meine Wunden... sind alle geheilt?"
  },
  AvgDialog_44437_Content_17 = {
    Text = "Die schwarze Schlange verließ euch ohne Zögern und umschlang Glenn mit unglaublicher Geschwindigkeit"
  },
  AvgDialog_44437_Content_18 = {
    Text = "Laufen, die Hexe... kommt..."
  },
  AvgDialog_44437_Content_19 = {
    Text = "Die pechschwarzen Schlangen krochen aus Glens Augen und Mund hervor. Er brach zusammen, bevor er einen vollständigen Satz aussprechen konnte."
  },
  AvgDialog_44437_Content_2 = {
    Text = "Klage um den Apostel der See.\nKlage um unser Licht, unsere Hoffnung.\n\nWir wehklagen, weinen und vergießen Tränen über unser Schicksal, ins Meer verbannt zu sein."
  },
  AvgDialog_44437_Content_20 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_44437_Content_21 = {
    Text = "Im Nu trieben unzählige zerschmetterte Leichen auf dem Meer."
  },
  AvgDialog_44437_Content_22 = {
    Text = "Dies ist ein stilles Massaker."
  },
  AvgDialog_44437_Content_23 = {
    Text = "<Gray:Ist es vorbei? Beeindruckend, wie man es von Miryam erwarten kann.>"
  },
  AvgDialog_44437_Content_24 = {
    Text = "Du hast uns geholfen... Wer bist du?"
  },
  AvgDialog_44437_Content_25 = {
    Text = "Die Frau mit dem schwarzen Schleier schweigt. Sie steht am Bug, ein dichter Nebel trennt dich von ihr."
  },
  AvgDialog_44437_Content_26 = {
    Text = "So nah und doch so fern."
  },
  AvgDialog_44437_Content_27 = {
    Text = "Die Frau blickte den verblüfften Goliath an, ein schwaches Lächeln umspielte ihre Lippen. Sie streckte ihren Finger in die Ferne, als würde sie eine stille Einladung aussprechen."
  },
  AvgDialog_44437_Content_28 = {
    Text = "Dann wendete sie den Bug und entfernte sich gemächlich."
  },
  AvgDialog_44437_Content_29 = {
    Text = "Warte, geh nicht...<Big:Geh nicht fort!>"
  },
  AvgDialog_44437_Content_3 = {
    Text = "Das Sichtfeld verdunkelt sich plötzlich; das grelle Sonnenlicht schwindet allmählich, und ein dichter Nebel legt sich über die gesamte Meeresoberfläche."
  },
  AvgDialog_44437_Content_30 = {
    Text = "Der Nebel lichtet sich, und ein Sonnenstrahl durchbricht die Wolken und taucht die Wellen in goldenes Licht."
  },
  AvgDialog_44437_Content_31 = {
    Text = "Du blinzelst, und das Ende des Meeres ist bereits leer."
  },
  AvgDialog_44437_Content_32 = {
    Text = "Der Sturm legt sich, und du und Goliath klammern euch an die einzige intakte Planke und ringt nach Atem."
  },
  AvgDialog_44437_Content_33 = {
    Text = "Das einst azurblaue Meer ist längst blutrot gefärbt, und ihr treibt dahin wie Wasserlinsen."
  },
  AvgDialog_44437_Content_34 = {
    Text = "Konnte das Schiff immer noch nicht bekommen... Jetzt weiß ich nicht einmal, wie ich nach Hause kommen soll."
  },
  AvgDialog_44437_Content_35 = {
    Text = "Ich gehe nicht nach Hause."
  },
  AvgDialog_44437_Content_36 = {
    Text = "Goliath stützte ein Bein auf und starrte mit leerem Blick in die Richtung, in die Miryam verschwunden war."
  },
  AvgDialog_44437_Content_37 = {
    Text = "Ich habe mich entschieden. Ich werde diese Hexe finden. Kommst du mit?"
  },
  AvgDialog_44437_Content_38 = {
    Text = "Ähm, „Nur ein Narr würde sein Leben einem anderen anvertrauen.“"
  },
  AvgDialog_44437_Content_39 = {
    Text = "Du senkst absichtlich deine Stimme, ahmst Goliaths früheren Tonfall nach und wiederholst, was er gesagt hat."
  },
  AvgDialog_44437_Content_4 = {
    Text = "Oh, beschütze jene, die vom Unglück geplagt sind.\nRichte deinen barmherzigen Blick auf uns..."
  },
  AvgDialog_44437_Content_40 = {
    Text = "Hmph, das liegt daran, dass der Einsatz nicht hoch genug war. Ich habe noch nie eine Macht gesehen, die alles in einem Augenblick zermalmen kann."
  },
  AvgDialog_44437_Content_41 = {
    Text = "Außerdem hat sie uns gerade geholfen und mir sogar eine Einladung ausgesprochen..."
  },
  AvgDialog_44437_Content_42 = {
    Text = "Aber was, wenn... es eine Falle ist?"
  },
  AvgDialog_44437_Content_43 = {Text = "Falle..."},
  AvgDialog_44437_Content_44 = {
    Text = "Erinnerst du dich an die Frage, die du mir vorhin gestellt hast?"
  },
  AvgDialog_44437_Content_45 = {
    Text = "...Das Wichtige ist, dank Euch, mein Gebieter, sind wir beide jetzt am Leben."
  },
  AvgDialog_44437_Content_46 = {
    Text = "Warum denkst du, ist das so?"
  },
  AvgDialog_44437_Content_47 = {
    Text = "Jetzt weiß ich die Antwort."
  },
  AvgDialog_44437_Content_48 = {
    Text = "Was ist die Antwort?"
  },
  AvgDialog_44437_Content_49 = {
    Text = "Ein Schwarm Seevögel flog plötzlich zusammen auf. Ihre weißen Schwingen schlugen wie Wolken im Flug, frei treibend in der Meeresbrise."
  },
  AvgDialog_44437_Content_5 = {
    Text = "Uralte, unheimliche Gesänge wehen heran. Die Silhouette einer Frau erscheint und verschwindet am Bug, wie ein Geist, der durch den Nebel wandelt."
  },
  AvgDialog_44437_Content_50 = {
    Text = "Goliath ließ sich von dem Vogelschwarm nicht stören. Er starrte geradeaus, seine Augen leuchteten vor Begeisterung."
  },
  AvgDialog_44437_Content_51 = {
    Text = "Weil ich Goliath bin."
  },
  AvgDialog_44437_Content_52 = {
    Text = "Goliath, der am längsten regierende Anführer in der Geschichte der Phillistine, ein unbezwingbarer Riese und ein legendärer Stammesheld."
  },
  AvgDialog_44437_Content_53 = {
    Text = "Selbst wenn nur ein einziger Gefolgsmann übrig bleibt – solange es einen Funken Hoffnung gibt, kann ich mich wieder erheben."
  },
  AvgDialog_44437_Content_54 = {
    Text = "Diese Hexe ist meine letzte Chance. Nur sie kann mir absolute Macht verleihen."
  },
  AvgDialog_44437_Content_55 = {
    Text = "Selbst wenn es eine Falle ist, werde ich hingehen."
  },
  AvgDialog_44437_Content_56 = {
    Text = "Warum rettest du mich dann? Ein „Taugenichts“ wie ich kann dir wahrscheinlich nicht von Nutzen sein..."
  },
  AvgDialog_44437_Content_57 = {
    Text = "Du hast absichtlich die Aussprache eines Wortes betont, was Goliath zum Lachen brachte."
  },
  AvgDialog_44437_Content_58 = {
    Text = "Das Sonnenlicht durchbricht die Wolken und taucht alles in goldenen Glanz. Haarsträhnen tanzen sanft unter dem azurblauen Himmel."
  },
  AvgDialog_44437_Content_59 = {
    Text = "Ein Anführer ohne Gefolgsleute kann in dieser Welt unmöglich Erfolg haben."
  },
  AvgDialog_44437_Content_6 = {
    Text = "Hm, singt da jemand?"
  },
  AvgDialog_44437_Content_60 = {
    Text = "Kleiner, du bist kein Versager. Du bist der einzige Anhänger des Riesen Goliath, niemand kann dich ersetzen"
  },
  AvgDialog_44437_Content_61 = {
    Text = "Wenn ich meine Vorherrschaft erringe, werde ich dich zumindest zum Stammeshäuptling ernennen!"
  },
  AvgDialog_44437_Content_62 = {
    Text = "...Nicht nötig."
  },
  AvgDialog_44437_Content_63 = {
    Text = "Der Himmel verdunkelte sich allmählich. Das Leuchten der Abenddämmerung glich schimmernden goldenen Flüssen, die über den Horizont strömten."
  },
  AvgDialog_44437_Content_64 = {
    Text = "Hey, weißt du was? Helden können nur Helden sein, weil es Leute wie uns gibt."
  },
  AvgDialog_44437_Content_65 = {
    Text = "<Small:Also bin ich auch wichtig, verstanden...>"
  },
  AvgDialog_44437_Content_66 = {
    Text = "<Small:Ugh...>"
  },
  AvgDialog_44437_Content_67 = {
    Text = "Bruchstückhafte Worte zerstreuen sich wie Pusteblumen in der Meeresbrise, weit, weit davongetragen."
  },
  AvgDialog_44437_Content_68 = {
    Text = "Du und Goliath saßt auf einer dünnen Holzplanke und saht aus wie winzige Blätter, die in einem goldenen Meer trieben."
  },
  AvgDialog_44437_Content_69 = {
    Text = "Niemand weiß, wohin ihr letztendlich segeln werdet."
  },
  AvgDialog_44437_Content_7 = {
    Text = "<Shake:Die Hexe, es ist die Hexe!>"
  },
  AvgDialog_44437_Content_8 = {
    Text = "Wie kann das sein... Könnte die Legende tatsächlich wahr sein..."
  },
  AvgDialog_44437_Content_9 = {
    Text = "<Red:Erbarmen. Erbarmen. Erbarmen...>"
  },
  AvgDialog_44438_Content_1 = {
    Text = "„Ursprung\""
  },
  AvgDialog_44438_Content_10 = {
    Text = "Hm? Fräulein Winkle hat gesagt, mein Geheimgang sei furchteinflößend, voller wilder Monster..."
  },
  AvgDialog_44438_Content_11 = {
    Text = "Das war alles nur ihre Einbildung. Aber ich habe wirklich etwas Besonderes gesehen, wie „dich“"
  },
  AvgDialog_44438_Content_12 = {Text = "Ich...?"},
  AvgDialog_44438_Content_13 = {
    Text = "Du lachtest leise und zwinkertst ihr zu."
  },
  AvgDialog_44438_Content_14 = {
    Text = "Das ist ein Geheimnis zwischen „ihr“ und mir. Ich erzähle dir in Zukunft mehr darüber."
  },
  AvgDialog_44438_Content_15 = {
    Text = "Sis——!!"
  },
  AvgDialog_44438_Content_16 = {
    Text = "Jenkin springt plötzlich aus den nahegelegenen Blumen hervor."
  },
  AvgDialog_44438_Content_17 = {
    Text = "Ich bin vom Herumstreifen mit Aigis zurück. Rate mal, was wir gefunden haben?"
  },
  AvgDialog_44438_Content_18 = {
    Text = "Jenkins schwenkte ein rotes Band in ihrer Hand. Anders als Masons übliches Band, hing an dessen Ende eine vergilbte Glocke"
  },
  AvgDialog_44438_Content_19 = {
    Text = "Eine sanfte Brise weht vorbei, und die Glocke klingelt hell, wie ein fröhlicher Kobold."
  },
  AvgDialog_44438_Content_2 = {
    Text = "Misaq Universität, Campus \n Drei Tage später"
  },
  AvgDialog_44438_Content_20 = {
    Text = "Das ist etwas, das im Geheimgang zu sehen war..."
  },
  AvgDialog_44438_Content_21 = {
    Text = "Oh, du hast sie auch im Geheimgang gesehen? Dann musst du die Schwester getroffen haben, die sich in eine Katze verwandelt hat!"
  },
  AvgDialog_44438_Content_22 = {
    Text = "Sag... sag das nicht..."
  },
  AvgDialog_44438_Content_23 = {
    Text = "Warum kann ich es nicht sagen? Dieses Band ist eine wichtige Erinnerung!"
  },
  AvgDialog_44438_Content_24 = {
    Text = "In dieser Zeit habe ich mich jeden Tag um dich gekümmert und mit dir gespielt. Es war so schön"
  },
  AvgDialog_44438_Content_25 = {
    Text = "Jenkin legte das Band behutsam in Masons Hand."
  },
  AvgDialog_44438_Content_26 = {
    Text = "Ich erinnere mich, dass du gesagt hast, du wolltest im nächsten Leben eine Katze sein"
  },
  AvgDialog_44438_Content_27 = {
    Text = "Wenn wir nur so unbeschwert bleiben könnten, könnte ich mich weiterhin um dich kümmern!"
  },
  AvgDialog_44438_Content_28 = {
    Text = "Mason lächelte hinab, ihre Finger strichen über das kühle, weiche Band."
  },
  AvgDialog_44438_Content_29 = {
    Text = "Eine Katze sein? Das ist etwas fürs nächste Leben."
  },
  AvgDialog_44438_Content_3 = {
    Text = "Ich verstehe. Kurz nachdem du Albino getötet hast, wurdest du von der Bildhauer-Gilde abgeholt."
  },
  AvgDialog_44438_Content_30 = {
    Text = "Jetzt will ich nur als „Mason\" leben"
  },
  AvgDialog_44438_Content_31 = {
    Text = "Jenkins sah dich überrascht an"
  },
  AvgDialog_44438_Content_32 = {
    Text = "Hm... Es scheint, dass dieser Geheimgang Schwester sehr verändert hat. So war sie vorher nicht."
  },
  AvgDialog_44438_Content_33 = {
    Text = "Ich bezeuge, dass Fräulein Mason die Wahrheit sagt."
  },
  AvgDialog_44438_Content_34 = {
    Text = "Du und Mason tauschtet ein Lächeln aus, die Gedanken kehrten zurück zu dem Moment kurz bevor der Geheimgang kollabierte..."
  },
  AvgDialog_44438_Content_35 = {
    Text = "Ich verstehe... Ich verstehe es jetzt."
  },
  AvgDialog_44438_Content_36 = {
    Text = "Du bist der Ursprung von allem und auch das Ende von allem..."
  },
  AvgDialog_44438_Content_37 = {
    Text = "Als der letzte Schimmer des Sternenlichts verblasst, scheint die Welt von schwarzer Tinte verschlungen zu werden."
  },
  AvgDialog_44438_Content_38 = {
    Text = "Du hörst Glocken aus der Ferne. Dong—Dong—"
  },
  AvgDialog_44438_Content_39 = {
    Text = "Kollabiert der Geheimgang... etwa?!"
  },
  AvgDialog_44438_Content_4 = {
    Text = "Das ist die Geschichte dessen, was danach geschah."
  },
  AvgDialog_44438_Content_40 = {
    Text = "Nimm meine Hand, {Male=Mr.,Female=Miss} %player%!"
  },
  AvgDialog_44438_Content_41 = {
    Text = "Du hältst Masons Hand fest."
  },
  AvgDialog_44438_Content_42 = {
    Text = "In diesem Moment schien dein Blut mühelos in ihren Körper zu fließen, und euer Bewusstsein verschmolz zu einem."
  },
  AvgDialog_44438_Content_43 = {
    Text = "Du spürst, wie du langsam in den Schlaf gleitest, unzählige Träume kommen einer nach dem anderen und tragen dich in die Tiefen der Dunkelheit."
  },
  AvgDialog_44438_Content_44 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_44438_Content_45 = {
    Text = "Du stehst in der Höhle, unter dir ein glitzernder goldener Fluss, wie die Adern der Erde"
  },
  AvgDialog_44438_Content_46 = {
    Text = "Ist das das Sternenlicht, das ich zuvor gesehen habe... Hat es sich alles hier versammelt?"
  },
  AvgDialog_44438_Content_47 = {
    Text = "<Red:Rückkehr, Rückkehr...>"
  },
  AvgDialog_44438_Content_48 = {
    Text = "Du folgst dem Strom des Sternenlichts tiefer in die Höhle."
  },
  AvgDialog_44438_Content_49 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_44438_Content_5 = {
    Text = "Hmm. Ich erinnere mich jetzt an alles. Es war keine angenehme Erinnerung..."
  },
  AvgDialog_44438_Content_50 = {
    Text = "Ist das...?!"
  },
  AvgDialog_44438_Content_51 = {
    Text = "Dieser Ort scheint der ultimative Ursprung aller verdrehten, deformierten und unreinen Dinge zu sein."
  },
  AvgDialog_44438_Content_52 = {
    Text = "Die hellgraue Masse zitterte und dehnte sich aus, spaltete sich windende, deformierte Monster ab, wie ein Magen in ständigem Kampf."
  },
  AvgDialog_44438_Content_53 = {
    Text = "Doch bevor sie das Ufer erreichten, fielen sie zurück in den Tümpel und wurden von den klaffenden Mäulern der Masse verschlungen."
  },
  AvgDialog_44438_Content_54 = {
    Text = "Die Silhouetten dieser Monster kommen mir irgendwie bekannt vor... Könnte es sein..."
  },
  AvgDialog_44438_Content_55 = {
    Text = "Du hast plötzlich eine starke Ahnung. Du watest durch den grauen Schleim und näherst dich dem Klumpen."
  },
  AvgDialog_44438_Content_56 = {
    Text = "Mason... bist du das?"
  },
  AvgDialog_44438_Content_57 = {
    Text = "Der Klumpen hielt einen Moment inne, dann begann er wieder sanft zu kriechen. Er machte ein raschelndes Geräusch, als ob er freundlich grüßen würde"
  },
  AvgDialog_44438_Content_58 = {
    Text = "Du betrachtest die Monster, die am Rand des Tümpels knien. Sie kämpfen sich vorwärts, zucken im Schleim, voller Sehnsucht, in die Umarmung der Masse zurückzukehren."
  },
  AvgDialog_44438_Content_59 = {
    Text = "Wie jene Pilger, die in Wind und Schnee nach Wundern suchen."
  },
  AvgDialog_44438_Content_6 = {
    Text = "Du hältst sanft Masons Hand."
  },
  AvgDialog_44438_Content_60 = {
    Text = "<Change>Die Quelle aller Unreinheit, Unsauberkeit und Unheil"
  },
  AvgDialog_44438_Content_61 = {
    Text = "<Change>Zurückkehren!"
  },
  AvgDialog_44438_Content_62 = {
    Text = "Denn hier enden alle Flüsse – egal, wie weit sie voneinander entfernt sein mögen, sie werden letztendlich hier zusammenfließen."
  },
  AvgDialog_44438_Content_63 = {
    Text = "Verstehe... das machst du also jeden Tag?"
  },
  AvgDialog_44438_Content_64 = {
    Text = "Mit einem gebrechlichen Körper jene verstreuten Persönlichkeiten wieder zusammenziehen und sich bemühen, das Erscheinungsbild aufrechtzuerhalten, das „normale Menschen\" haben sollten."
  },
  AvgDialog_44438_Content_65 = {
    Text = "...Kein Wunder, dass ich von diesen vergangenen Ereignissen geträumt habe."
  },
  AvgDialog_44438_Content_66 = {
    Text = "Als ich diese Sterne das letzte Mal sah, hatte ich plötzlich das Gefühl, dass ich ihnen sehr ähnlich bin."
  },
  AvgDialog_44438_Content_67 = {
    Text = "...es gibt auch Unterschiede. Sie wissen, wo ihr Zuhause ist, aber ich habe sogar meine Erinnerungen verloren."
  },
  AvgDialog_44438_Content_68 = {
    Text = "Deine Nase kribbelt plötzlich ein wenig. Du berührst sanft das Fleisch und spürst seinen ruhigen Puls."
  },
  AvgDialog_44438_Content_69 = {
    Text = "Mason... Werde auch ich eines Tages mein Zuhause finden? Einfach so, wie du es gerade tust..."
  },
  AvgDialog_44438_Content_7 = {
    Text = "Es ist vorbei. Ich verspreche dir, es wird nie wieder passieren"
  },
  AvgDialog_44438_Content_70 = {
    Text = "Das Fleisch windet sich und spaltet sich am Ende, um einen weichen, schleimigen Tentakel zu formen, der sanft die Tränen aus deinem Augenwinkel wischt."
  },
  AvgDialog_44438_Content_71 = {
    Text = "<Change>Es wird passieren"
  },
  AvgDialog_44438_Content_72 = {
    Text = "<Change>Weine nicht"
  },
  AvgDialog_44438_Content_73 = {Text = "Donnern..."},
  AvgDialog_44438_Content_74 = {
    Text = "Aus der Tiefe des Mantels kamen schwache Erschütterungen, die die Felswand aufrissen"
  },
  AvgDialog_44438_Content_75 = {
    Text = "Zeit bis zum Zusammenbruch des Bereichs: <Red:0> Min"
  },
  AvgDialog_44438_Content_76 = {
    Text = "Du drehst dich um und verlässt die Höhle. Am Ausgang kannst du nicht anders, als einen letzten Blick auf sie zu werfen"
  },
  AvgDialog_44438_Content_77 = {
    Text = "Abschied, Miss Mason."
  },
  AvgDialog_44438_Content_78 = {
    Text = "Freude, Trauer, Schmerz... Verschiedene Persönlichkeiten und Emotionen kommen und gehen, doch sie bleibt in jener Höhle."
  },
  AvgDialog_44438_Content_79 = {Text = "Sie lebt"},
  AvgDialog_44438_Content_8 = {
    Text = "Danke... {Male=Mr.,Female=Miss} %player%."
  },
  AvgDialog_44438_Content_9 = {
    Text = "Eigentlich sollte ich dir danken. Als der Bereich zusammenbrach, gabst du mir viele Ermutigungen und Trost"
  },
  AvgDialog_44439_Content_1 = {
    Text = "Goldene Fuge"
  },
  AvgDialog_44439_Content_10 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_44439_Content_11 = {
    Text = "Es scheint, als hätte ich zum ersten Mal von der Vergangenheit geträumt."
  },
  AvgDialog_44439_Content_12 = {
    Text = "Du umklammerst deinen Kopf und fühlst, als würde ein unsichtbarer Faden dein Bewusstsein vom Bett fortziehen."
  },
  AvgDialog_44439_Content_13 = {
    Text = "Dann öffnetest du das Fenster und sahst den ersten Schneefall des neuen Jahres."
  },
  AvgDialog_44439_Content_14 = {
    Text = "Wow, es schneit!!"
  },
  AvgDialog_44439_Content_15 = {
    Text = "Die aufgeregten Rufe der Kinder hallten durch den stillen Nachthimmel. Begleitet von chaotischen Schritten versammelten sich die Waisenkinder unten."
  },
  AvgDialog_44439_Content_16 = {
    Text = "So viel Schnee, schimmernd und wunderschön."
  },
  AvgDialog_44439_Content_17 = {
    Text = "Aigis will einen Schneemann bauen, genau wie der kleine Bobby."
  },
  AvgDialog_44439_Content_18 = {
    Text = "Das ist einfach, ich mach das—"
  },
  AvgDialog_44439_Content_19 = {
    Text = "Ta-da! Schaut euch mein Meisterwerk an!"
  },
  AvgDialog_44439_Content_2 = {
    Text = "Du hattest einen unglaublich langen Traum."
  },
  AvgDialog_44439_Content_20 = {
    Text = "Hmm... es sieht nicht ganz aus wie der kleine Bär Bobby. Es, es..."
  },
  AvgDialog_44439_Content_21 = {
    Text = "Es sieht aus wie ein Hund! Ein Mops!"
  },
  AvgDialog_44439_Content_22 = {
    Text = "<Big:Wahahahaha!>"
  },
  AvgDialog_44439_Content_23 = {
    Text = "Unsinn! Wie könnte ich nur wie ein Hund aussehen?!"
  },
  AvgDialog_44439_Content_24 = {Text = "Squeak!"},
  AvgDialog_44439_Content_25 = {
    Text = "Kinder lachen und spielen in den Gassen. Mason, bereits wach, steht neben dir."
  },
  AvgDialog_44439_Content_26 = {
    Text = "Sie streckte ihre Hand aus und fing ein paar sanfte Schneeflocken in ihrer Handfläche auf."
  },
  AvgDialog_44439_Content_27 = {
    Text = "Die Schneeflocke lag still in ihrer Handfläche, schmolz schnell zu kaltem Wasser und schimmerte in goldenem Sternenlicht."
  },
  AvgDialog_44439_Content_28 = {
    Text = "Hm, das ist das Licht, das wir letztes Mal gesehen haben..."
  },
  AvgDialog_44439_Content_29 = {
    Text = "Unzählige Sternenlichter fliegen aus den Fenstern des Korridors nebenan und verschmelzen zu einem goldenen Fluss am Nachthimmel."
  },
  AvgDialog_44439_Content_3 = {
    Text = "Im Traum war der Himmel wie ein zerrissener Friedhof, und schwarze Substanzen strömten wie Tinte herein."
  },
  AvgDialog_44439_Content_30 = {
    Text = "Sie fließen anmutig und erstrecken sich bis hin zu den fernen, mondbeleuchteten Bergen."
  },
  AvgDialog_44439_Content_31 = {
    Text = "Mason schloss sanft die Augen"
  },
  AvgDialog_44439_Content_32 = {
    Text = "Es ist der Duft dieser Clown-Dame. Sie hat uns verlassen."
  },
  AvgDialog_44439_Content_33 = {
    Text = "Aber ich bin nicht traurig... Es scheint, als hätte sie uns aus freiem Willen verlassen, als würde sie nach Hause zurückkehren."
  },
  AvgDialog_44439_Content_34 = {
    Text = "Nach Hause gehen..."
  },
  AvgDialog_44439_Content_35 = {
    Text = "Miss Mason, ich habe gehört, dass du schon in jungen Jahren in der Stadt gearbeitet hast. Vermisst du dein Zuhause noch?"
  },
  AvgDialog_44439_Content_36 = {
    Text = "Mason schaute auf Jenkin und den kleinen Mike, die unten miteinander rangen, und lächelte sanft."
  },
  AvgDialog_44439_Content_37 = {
    Text = "Mein Gedächtnis ist furchtbar. Als ich ein Kind war, sagten die Nonnen in der Kirchenschule, ich sei nicht zum Lernen geeignet."
  },
  AvgDialog_44439_Content_38 = {
    Text = "Eltern, Heimat... Ich erinnere mich kaum und möchte es auch nicht. Erinnerungen sollen Freude bewahren"
  },
  AvgDialog_44439_Content_39 = {
    Text = "In den Märchenbüchern, die ich gelesen habe, kann nur ein glücklicher und warmer Ort als Zuhause bezeichnet werden. Ich möchte das Zuhause von Jenkins und Brown sein"
  },
  AvgDialog_44439_Content_4 = {
    Text = "Du liegst mit dem Gesicht nach oben unter dem Riss, dein Herz so nah an der Erde wie möglich."
  },
  AvgDialog_44439_Content_40 = {
    Text = "Verstehe. Miss Mason, du bist viel stärker, als ich dachte"
  },
  AvgDialog_44439_Content_41 = {
    Text = "So waren Sie nicht, als wir uns zum ersten Mal im Wachsfigurenkabinett trafen."
  },
  AvgDialog_44439_Content_42 = {
    Text = "<Gray:Sieht so aus, als wäre Fräulein Winkles „Menophin-Super-Stabilisierungstherapie\" tatsächlich wirksam.>"
  },
  AvgDialog_44439_Content_43 = {
    Text = "Mason lächelte, seine Augen wurden schmal"
  },
  AvgDialog_44439_Content_44 = {
    Text = "Alle geben ihr Bestes, um mir zu helfen. Wie könnte ich mich da überhaupt nicht verändern?"
  },
  AvgDialog_44439_Content_45 = {
    Text = "Ich hoffe, ich kann allen helfen."
  },
  AvgDialog_44439_Content_46 = {
    Text = "Du streckst dich und blickst ziellos auf das dunkle Wohnviertel unten"
  },
  AvgDialog_44439_Content_47 = {
    Text = "Vielleicht ist es nur eine Illusion, aber du siehst „Schatten 24\" am Ende der dunklen Gasse stehen und mit euch den Lichtfluss am Himmel betrachten"
  },
  AvgDialog_44439_Content_48 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_44439_Content_49 = {
    Text = "Hier ist ein Geheimnis: Jede Persona ist wie ein treibendes Kraut, und ganz zu werden ist unser gemeinsamer Wunsch."
  },
  AvgDialog_44439_Content_5 = {
    Text = "Klopf, klopf. Klopf, klopf."
  },
  AvgDialog_44439_Content_50 = {
    Text = "Zusammen lachen, zusammen weinen und die Liebe und das Vertrauen von Jenkin spüren..."
  },
  AvgDialog_44439_Content_51 = {
    Text = "Es sind nur traurige Illusionen"
  },
  AvgDialog_44439_Content_52 = {
    Text = "Der Wind weht sanft, und Schneeflocken treiben wie weiche Watte durch die Luft, ziellos umherschwebend."
  },
  AvgDialog_44439_Content_53 = {
    Text = "Das Sternenlicht verblasst allmählich, und dein Bewusstsein scheint mit ihm davonzutreiben."
  },
  AvgDialog_44439_Content_54 = {
    Text = "Wie der nächste Geheimgang, der auf dich wartet, wohl sein wird?"
  },
  AvgDialog_44439_Content_55 = {
    Text = "Du freust dich tatsächlich ein wenig darauf."
  },
  AvgDialog_44439_Content_56 = {
    Text = "<Yellow:Protokoll zur Untersuchung künstlicher Bereiche III>\n\n■Bereichs-ID: M-C06\n■Zusammenbruchzeit: 24. Dezember, Jahr 315 Hongji\n■Zusammenbruchsstandort: Lilys Waisenhaus"
  },
  AvgDialog_44439_Content_57 = {
    Text = "<Yellow: Untersuchungsergebnisse>\n\nIch sah den Schnee und das goldene Sternenlicht, das im Schnee tanzte.\nSeltsamerweise ließ es mich immer an die Vergangenheit denken. Der Nebel stieg auf, das Licht fiel, das Lachen wurde zunehmend verschwommen.\nEs ist eine ruhige Winternacht.\n\n<Yellow: Frohes Neues Jahr.>\n\nAnmerkung: Die von Miss Sarah gemachten Zuckerguss-Mini-Kuchen sind sehr lecker"
  },
  AvgDialog_44439_Content_6 = {
    Text = "Du schließt die Augen und spürst das Beben aus der Tiefe des Erdmantels. Es ist ein melancholischer und uralter Rhythmus, der dich an dein Zuhause erinnert."
  },
  AvgDialog_44439_Content_7 = {
    Text = "Nach einer Weile hörst du ein gedämpftes Lachen, jemand ergreift deine Hand. Du erwiderst den lange vermissten Trost"
  },
  AvgDialog_44439_Content_8 = {
    Text = "Mutter. Du hast noch nicht einmal rufen können, aber die Tränen kamen schon"
  },
  AvgDialog_44439_Content_9 = {
    Text = "Ihr wart viel zu lange getrennt."
  },
  AvgDialog_44440_Content_1 = {
    Text = "Nein, es sind zu viele Leute... Es wird nur noch schlimmer..."
  },
  AvgDialog_44440_Content_10 = {
    Text = "Nein, Herr Goliath—!!"
  },
  AvgDialog_44440_Content_11 = {
    Text = "Es fühlt sich an, als wäre alles vor meinen Augen angehalten worden."
  },
  AvgDialog_44440_Content_12 = {
    Text = "Dieser Körper hat deine Kontrolle übertroffen, er stürzt sich nach vorne und stellt sich schützend vor Goliath"
  },
  AvgDialog_44440_Content_13 = {Text = "Hmm—"},
  AvgDialog_44440_Content_16 = {
    Text = "Eine Klinge schlitzt deine Kehle auf. Zitternd presst du die Hand auf die blutende Wunde, dein Verstand im Chaos."
  },
  AvgDialog_44440_Content_17 = {
    Text = "Hast du den Verstand verloren? Was machst du hier?!"
  },
  AvgDialog_44440_Content_18 = {
    Text = "Ich weiß nicht... Mein Körper hat sich von selbst bewegt..."
  },
  AvgDialog_44440_Content_19 = {
    Text = "Entschuldigung, Lord Goliath..."
  },
  AvgDialog_44440_Content_2 = {
    Text = "Ich... kann noch... töten!"
  },
  AvgDialog_44440_Content_22 = {
    Text = "Ein vergifteter Pfeil zischte durch die Luft, traf Goliaths Schulter und ließ ihn in deine Richtung stürzen."
  },
  AvgDialog_44440_Content_23 = {
    Text = "Goliath... Der riesige Goliath ist endlich gefallen!"
  },
  AvgDialog_44440_Content_24 = {
    Text = "Sein Kopf gehört mir! Niemand wird ihn mir wegnehmen!!!"
  },
  AvgDialog_44440_Content_25 = {
    Text = "Das Meer ließ ein tiefes, zorniges Beben ertönen. Der Riese versperrte die gleißende Sonne, bevor er krachend zusammenbrach."
  },
  AvgDialog_44440_Content_26 = {
    Text = "Euer Blut fließt zusammen und färbt das azurblaue Meer purpurrot."
  },
  AvgDialog_44440_Content_27 = {
    Text = "Du hörst den Wind, die Wellen und in der Ferne Jubel und Kampfgeschrei. Vor dir liegt nichts als endloses Gemetzel und Erniedrigung."
  },
  AvgDialog_44440_Content_28 = {
    Text = "Das salzige Meerwasser brennt in der Wunde an deinem Hals und lässt dich vor Schmerz zusammenzucken."
  },
  AvgDialog_44440_Content_29 = {
    Text = "Goliath geht es kaum besser als dir."
  },
  AvgDialog_44440_Content_3 = {
    Text = "Das dröhnende Hallen von Hörnern echote über das Meer. Angelockt von großzügigen Belohnungen strömten Krieger herbei, um sich dem Jagdspiel anzuschließen."
  },
  AvgDialog_44440_Content_30 = {
    Text = "Als er dein elendes Aussehen sah, verzog sich sein Mund zu einem bösen Lächeln"
  },
  AvgDialog_44440_Content_32 = {
    Text = "...Versager"
  },
  AvgDialog_44440_Content_4 = {
    Text = "Goliath näherte sich seinem Limit. Er schwang seine Riesenklinge ein weiteres Mal, doch in seiner trägen Bewegung ergriff jemand die Lücke."
  },
  AvgDialog_44440_Content_6 = {
    Text = "Goliath fiel zu Boden, die Wunde offenbarte seine blassen Knochen, und das Blut floss wie ein unaufhörlicher schwebender Strom"
  },
  AvgDialog_44440_Content_8 = {
    Text = "Jetzt ist der Moment! Macht ihn mit einem Schlag fertig!!"
  },
  AvgDialog_44440_Content_9 = {
    Text = "Die einkreisenden Krieger schwärmen heran wie blutdürstige Haie."
  },
  AvgDialog_44441_Content_1 = {
    Text = "Chronik der Riesen"
  },
  AvgDialog_44441_Content_10 = {
    Text = "Goliath stieß ein verächtliches Lachen aus"
  },
  AvgDialog_44441_Content_11 = {
    Text = "Was soll der Unsinn über Hexen? Du glaubst doch nicht etwa ihren Lügen, oder?"
  },
  AvgDialog_44441_Content_12 = {
    Text = "Nur Narren vertrauen ihr Leben anderen an."
  },
  AvgDialog_44441_Content_13 = {
    Text = "<Gray:Hexe...>"
  },
  AvgDialog_44441_Content_14 = {
    Text = "Laut Goliaths Erwachenakte ist diese sogenannte \"Hexe\" zweifellos Miryam."
  },
  AvgDialog_44441_Content_15 = {
    Text = "Obwohl die weitere Entwicklung nicht wie erwartet verlief, hat Miryam Goliath tatsächlich das Leben gerettet."
  },
  AvgDialog_44441_Content_16 = {
    Text = "Herr, ihr seid schwer verletzt, es gibt wohl keine andere Möglichkeit—"
  },
  AvgDialog_44441_Content_17 = {Text = "Rums!!"},
  AvgDialog_44441_Content_18 = {
    Text = "Mit gewaltiger Kraft wird deine zerbrechliche Kehle fest umklammert und du wirst vom Boden gehoben, bis du dem Riesen von Angesicht zu Angesicht gegenüberstehst."
  },
  AvgDialog_44441_Content_19 = {
    Text = "Ich sage das nur einmal: Sieh mich nicht mit diesem Blick an und sprich nicht in diesem Ton mit mir."
  },
  AvgDialog_44441_Content_2 = {
    Text = "Die Sonne brannte auf das Meer, als wollte sie alles Leben in dieser endlosen Hitze verzehren"
  },
  AvgDialog_44441_Content_20 = {
    Text = "Das Letzte, was ich, Goliath, brauche, ist das Mitleid der Schwachen."
  },
  AvgDialog_44441_Content_21 = {
    Text = "Goliath sprach ruhig, sein Gesichtsausdruck unverändert, als würde er mit dir über das Wetter plaudern."
  },
  AvgDialog_44441_Content_22 = {
    Text = "Doch du bist so nah, dass du seine Augen deutlich sehen kannst, rot vor Schmerz und Frustration."
  },
  AvgDialog_44441_Content_23 = {
    Text = "In diesem Moment schien er seinen Ruhm als Herrscher der Meere abzulegen und wurde zu nur einem weiteren verlorenen Fisch im endlosen Ozean, genau wie du."
  },
  AvgDialog_44441_Content_24 = {
    Text = "Verzeihung... äh, mein Gebieter..."
  },
  AvgDialog_44441_Content_25 = {
    Text = "<Shake:Wuuu—>"
  },
  AvgDialog_44441_Content_26 = {
    Text = "Der tiefe Klang eines Horns weht aus der Ferne heran."
  },
  AvgDialog_44441_Content_27 = {
    Text = "Das Gewicht am Hals ließ plötzlich nach. Goliath löste seinen Griff und blickte in die Richtung, aus der der Hornklang kam."
  },
  AvgDialog_44441_Content_28 = {
    Text = "<Gray:Hust... Puh, ich bin gerettet...>"
  },
  AvgDialog_44441_Content_29 = {
    Text = "Interessant... Macht ihr euch Sorgen, dass ich nicht schnell genug sterbe, und seid deshalb alle zusammengekommen, um mich zu verabschieden?"
  },
  AvgDialog_44441_Content_3 = {
    Text = "Du und Goliath klammert euch an das Brett, die einzige Insel im weiten Meer. Unter der sengenden Sonne wird dir wieder schwindelig."
  },
  AvgDialog_44441_Content_30 = {
    Text = "Es dauerte nicht lange, da umzingelte die gewaltige Flotte euch und ließ die schwankenden Holzplanken als einzige Insel in diesem weiten Meer zurück."
  },
  AvgDialog_44441_Content_31 = {
    Text = "Ihr seid bereits umzingelt."
  },
  AvgDialog_44441_Content_32 = {
    Text = "Erlaubt mir, allen den tapfersten Anführer in der Geschichte der Phillistine vorzustellen! Den unbeugsamen Riesen von gewaltiger Kraft! Den ehrfurchtgebietenden, unvergleichlichen Stammeshelden—"
  },
  AvgDialog_44441_Content_33 = {
    Text = "<BigShake:Lord Goliath!>"
  },
  AvgDialog_44441_Content_34 = {
    Text = "Das vom Meer reflektierte Sonnenlicht ist zu grell; du kannst nur die Silhouette einer schwarzen Gestalt erkennen, die am Bug steht und auf dich herabblickt."
  },
  AvgDialog_44441_Content_35 = {
    Text = "Die neu hinzugekommenen Brüder wissen es vielleicht nicht, aber dieser Lord wurde in einem Duell schwer verwundet und beinahe gefangen genommen, was unseren gesamten Clan an den Rand einer beispiellosen Krise trieb!"
  },
  AvgDialog_44441_Content_36 = {
    Text = "Das drohende Unheil verschlang den Großteil unseres Volkes! Gepriesen seist du, mein teuerster Lord Goliath!"
  },
  AvgDialog_44441_Content_37 = {
    Text = "Hehe... Wie könnte ich es wagen, mir eine so große Errungenschaft allein anzurechnen, Glen?"
  },
  AvgDialog_44441_Content_38 = {
    Text = "Wer hat sich hinter mir versteckt, zu feige zum Kämpfen, und wer war der Erste, der seine Waffe fallen ließ und weinend nach Hause rannte?"
  },
  AvgDialog_44441_Content_39 = {Text = "Du...!"},
  AvgDialog_44441_Content_4 = {
    Text = "<Shake:Entschuldigung, mir geht es nicht gut... Ich ruhe mich kurz aus...>"
  },
  AvgDialog_44441_Content_40 = {
    Text = "Glens Gesicht lief rot an, seine trüben Augen zitterten, bevor sie sich schließlich auf dich richteten."
  },
  AvgDialog_44441_Content_41 = {
    Text = "Oh, selbst wenn sich der Stamm auflöst, hat der Anführer immer noch einen... sehr entzückenden Gefolgsmann."
  },
  AvgDialog_44441_Content_42 = {
    Text = "Die Schande der Perisiter — ein Versager, der nicht einmal einen einzigen Schlag innerhalb des Stammes einstecken kann, und dennoch dir folgen will, um ein Krieger zu werden..."
  },
  AvgDialog_44441_Content_43 = {
    Text = "Hahahaha...!!"
  },
  AvgDialog_44441_Content_44 = {
    Text = "Goliath blickt auf und entdeckt dich überrascht durch das Gelächter der Menge."
  },
  AvgDialog_44441_Content_45 = {
    Text = "Hey, Kleiner, bist du aus freien Stücken gekommen, um mir zu folgen?"
  },
  AvgDialog_44441_Content_46 = {
    Text = "<Gray:Äh... So erinnere ich mich daran...>"
  },
  AvgDialog_44441_Content_47 = {
    Text = "Ist das nicht rührend? Ich habe nur beiläufig die Hexe erwähnt, und dieser kleine Narr hat es ernst genommen und wollte dir unbedingt hierher folgen..."
  },
  AvgDialog_44441_Content_48 = {
    Text = "Nicht aufzuhalten, haha—"
  },
  AvgDialog_44441_Content_49 = {
    Text = "Platschen!!"
  },
  AvgDialog_44441_Content_5 = {Text = "Bang!"},
  AvgDialog_44441_Content_50 = {
    Text = "Das Gelächter verstummte abrupt. Ein heftiger Wind heulte auf, und ein abgetrenntes Bein rollte vor aller Augen."
  },
  AvgDialog_44441_Content_51 = {
    Text = "Aaaah... mein Bein, mein Bein!!"
  },
  AvgDialog_44441_Content_52 = {
    Text = "Der einst dominierende Herrscher der Meere steht wie ein Berg vor Glen und strahlt eine Aura aus, die das Herz gefrieren lässt."
  },
  AvgDialog_44441_Content_53 = {
    Text = "Diese Fliege summt mir schon eine Weile um die Ohren..."
  },
  AvgDialog_44441_Content_54 = {
    Text = "Goliath wischte gemächlich das Blut von seiner Klinge, blickte dann auf und schenkte Glen ein kaltes Lächeln."
  },
  AvgDialog_44441_Content_55 = {
    Text = "Glenn, habe ich dir nicht gerade eine Frage gestellt?"
  },
  AvgDialog_44441_Content_6 = {
    Text = "Ein von Schweiß und Blut getränktes Hemd wird dir über den Kopf geworfen, woraufhin du wegen des Gestanks sofort hochspringst."
  },
  AvgDialog_44441_Content_7 = {
    Text = "Hust... Ugh!"
  },
  AvgDialog_44441_Content_8 = {
    Text = "Du hast einen Hitzschlag. Leg dir das auf den Kopf, um dich vor der Sonne zu schützen, und nimm es nicht ab."
  },
  AvgDialog_44441_Content_9 = {
    Text = "Danke, Herr... Wohin gehen wir als Nächstes? Zur Hexe?"
  },
  AvgDialog_44442_Content_1 = {Text = "Hmm—!!"},
  AvgDialog_44442_Content_10 = {
    Text = "Ich, der Krieger Glen, schwöre bei meinem Leben: Wer mir diesen Kopf bringt, dem gehören mein Reichtum, mein Land und meine Frauen!"
  },
  AvgDialog_44442_Content_11 = {
    Text = "Unter großer Belohnung treten gewiss tapfere Männer hervor. Die Krieger brachen in begeisterte Jubelrufe aus, ihre Waffen klirrten und hallten mit dem aufregenden Klang des Kampfes wider."
  },
  AvgDialog_44442_Content_12 = {
    Text = "Ja, wovor sollen wir Angst haben? Wir sind so viele!"
  },
  AvgDialog_44442_Content_13 = {
    Text = "Schnitt ihm zuerst die Hand ab, die das Messer hält!"
  },
  AvgDialog_44442_Content_14 = {
    Text = "Die einst kauernden Krieger brüllten auf und stürmten wie blutdürstige Heuschrecken nach vorn."
  },
  AvgDialog_44442_Content_15 = {
    Text = "Heh... meine liebsten Verwandten. Ich habe euch beigebracht, wie man kämpft, wie man tötet und wie man überlebt."
  },
  AvgDialog_44442_Content_16 = {
    Text = "Aber ich habe euch nie beigebracht, wie man vor überlegenen Feinden flieht"
  },
  AvgDialog_44442_Content_17 = {
    Text = "Goliath leckte das Blut aus seinem Mundwinkel und entblößte seine Reißzähne."
  },
  AvgDialog_44442_Content_18 = {
    Text = "...denn ihr habt nirgendwo mehr hin zu fliehen."
  },
  AvgDialog_44442_Content_19 = {
    Text = "Damit packte er beiläufig ihre Kehlen, hob ihre Köpfe an und schmetterte sie zusammen—"
  },
  AvgDialog_44442_Content_2 = {
    Text = "Ein rasendes Hackbeil zerschlug das Schiff in Stücke und zwang Glen zum Rückzug – mit nur noch einem verbliebenen Bein."
  },
  AvgDialog_44442_Content_20 = {
    Text = "Platschen!!"
  },
  AvgDialog_44442_Content_21 = {
    Text = "Gelbe und weiße Flüssigkeiten vermischten sich mit zersplittertem Blut und spritzten heraus. Goliath lachte herzhaft, seine Pupillen brannten vor blutdürstiger Bosheit."
  },
  AvgDialog_44442_Content_22 = {
    Text = "Hahaha! Ich habe gehört, jemand will mir den Kopf abnehmen?"
  },
  AvgDialog_44442_Content_23 = {
    Text = "Wenn du dich traust, komm und hol es!"
  },
  AvgDialog_44442_Content_3 = {
    Text = "<Shake:Warst du nicht verletzt? Wie konntest du...>"
  },
  AvgDialog_44442_Content_4 = {
    Text = "Verzeihung, aber um mit einem Handlanger wie dir fertigzuwerden, brauche ich nicht meine volle Stärke."
  },
  AvgDialog_44442_Content_5 = {
    Text = "Goliath steht stolz am Bug, seine gewaltige Klinge beschreibt einen Bogen vor ihm und hält seine einstigen Kameraden auf Abstand."
  },
  AvgDialog_44442_Content_6 = {
    Text = "Gibt es noch jemanden, der heraufkommen und mit mir spielen will? Eine Person reicht nicht zum Töten!"
  },
  AvgDialog_44442_Content_7 = {
    Text = "Glen blickte hastig um sich"
  },
  AvgDialog_44442_Content_8 = {
    Text = "Eingeschüchtert vom Schrecken des Riesen kauerten die Krieger wie junge Welpen, keiner wagte es, in den verbotenen Bogen vor ihnen zu treten, als wäre es ein Tabuort."
  },
  AvgDialog_44442_Content_9 = {
    Text = "Ein Haufen Taugenichtse! Mit solch schweren Verletzungen ist er nicht mehr der einst dominierende Herrscher der Meere."
  },
  AvgDialog_44811_Content_1 = {
    Text = "Brennendes Eis"
  },
  AvgDialog_44811_Content_10 = {
    Text = "Schlag? Halbherziger Chef?"
  },
  AvgDialog_44811_Content_11 = {
    Text = "Dein Körper weigert sich immer noch, sich deiner Seele zu öffnen, mit Erinnerungen, die in einer unbekannten Ecke versteckt sind."
  },
  AvgDialog_44811_Content_12 = {
    Text = "Du drängst dich hilflos durch die plappernden Tänzer, wie eine Schar Spatzen, und streckst die Hand zum Mädchen aus, das sich abwendet –"
  },
  AvgDialog_44811_Content_13 = {
    Text = "Liz, wohin gehst du?"
  },
  AvgDialog_44811_Content_14 = {
    Text = "Das stimmt, Liz."
  },
  AvgDialog_44811_Content_15 = {
    Text = "Die schwarzgekleidete Tänzerin, die dich aus einer misslichen Lage gerettet und diese Bühne gerettet hat, ist niemand anderes als die dir vertraute Erwachende Liz."
  },
  AvgDialog_44811_Content_16 = {
    Text = "Zweifellos gehört dieser Traum zu Liz, dem Mädchen, das sich immer im Mythag Tanzstudio einsperrt."
  },
  AvgDialog_44811_Content_17 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_44811_Content_18 = {
    Text = "Liz warf Ihnen einen Blick über die Schulter zu, die Muskeln an der Ecke ihres Mundes zuckten leicht, als ob sie etwas sagen wollte—"
  },
  AvgDialog_44811_Content_19 = {
    Text = "Elizabeth, meine liebe Elizabeth. Ich wusste, dass du diesem Tanz nicht widerstehen kannst—"
  },
  AvgDialog_44811_Content_2 = {
    Text = "<Small:Puh... Puh... Es ist endlich vorbei.>"
  },
  AvgDialog_44811_Content_20 = {
    Text = "Der stämmige Manager des Tanzensembles quetschte sich mit einem schmeichelhaften Lächeln neben Liz."
  },
  AvgDialog_44811_Content_21 = {
    Text = "Liz tritt elegant zurück, wie ein Schmetterling, der aus seiner Reichweite flattert."
  },
  AvgDialog_44811_Content_22 = {
    Text = "Niemand wagte, sie aufzuhalten, während sie hinter die Bühne verschwand. Das Lächeln des Managers erstarrte, dann spuckte er verächtlich"
  },
  AvgDialog_44811_Content_23 = {
    Text = "Für wen spielst du diese Reinheit vor? Wäre es nicht für die Gunst des Lordherzogs, hätte ich mit diesem Elenden schon lange Schluss gemacht..."
  },
  AvgDialog_44811_Content_24 = {
    Text = "Worauf starrst du? Beeil dich und bereite dich auf den nächsten Tanz vor! Wenn du die Herren und Damen verärgerst, kannst du nur dich selbst dafür blame"
  },
  AvgDialog_44811_Content_25 = {
    Text = "Die Mädchen zuckten zusammen, aber am Ende wagte es niemand, den Manager herauszufordern. Sie standen gehorsam von der Bühne auf und formierten ihren Tanz neu."
  },
  AvgDialog_44811_Content_26 = {
    Text = "Und du, wie heißt du nochmal... Egal, es ist nicht wichtig."
  },
  AvgDialog_44811_Content_27 = {
    Text = "Der Manager deutete beiläufig und wählte einen auffälligen Tänzer aus der Gruppe aus. Das gewählte Mädchen strahlte vor Freude und kam mit einem hellen Lächeln näher."
  },
  AvgDialog_44811_Content_28 = {
    Text = "Manager, mein Name ist Caroline..."
  },
  AvgDialog_44811_Content_29 = {
    Text = "Es ist mir egal, ob du Caroline oder Carol bist, du nimmst den letzten Vorhang."
  },
  AvgDialog_44811_Content_3 = {
    Text = "Die Musik verklingt, und dein Körper nimmt endlich eine erstarrte Pose neben den anderen Tänzern ein, bereit, den donnernden Applaus zu empfangen."
  },
  AvgDialog_44811_Content_30 = {
    Text = "In deinem Alter wirst du bald aus der Gruppe gedrängt. Das ist deine letzte Chance, einen Ausweg zu finden."
  },
  AvgDialog_44811_Content_31 = {
    Text = "Vielen Dank, Manager, danke!"
  },
  AvgDialog_44811_Content_32 = {
    Text = "Der Manager schoss einen Schimpf nach dem anderen ab, während die Tänzerin sich verbeugte und ihre zerschundene Würde opferte, was die Szene extrem unangenehm machte."
  },
  AvgDialog_44811_Content_33 = {
    Text = "...Du bist nicht in den Traum eingetreten, um ein Tanzstar zu werden."
  },
  AvgDialog_44811_Content_34 = {
    Text = "Während das Mädchen begeistert dem Manager dankte, hast du leicht den Kopf geneigt, um unter den anderen Mädchen nicht aufzufallen."
  },
  AvgDialog_44811_Content_35 = {
    Text = "Der Hintergang, durch den Liz geht, ist in greifbarer Nähe, aber eine fette Hand packt ihr dünnes Handgelenk und zieht dich mit unwiderstehlicher Kraft in den Hintergrund."
  },
  AvgDialog_44811_Content_36 = {
    Text = "Autsch, autsch... Manager, du—"
  },
  AvgDialog_44811_Content_37 = {Text = "—Snap!"},
  AvgDialog_44811_Content_38 = {
    Text = "Ein Summen hallt im Gehörgang wider, die Wange schwillt an und rötet sich sichtbar, und scharfe Stichschmerzen brechen fast durch die Haut."
  },
  AvgDialog_44811_Content_39 = {
    Text = "(Greife ihn an)"
  },
  AvgDialog_44811_Content_4 = {
    Text = "Aber von unter der Bühne kamen nur überlappende, leise Flüstern."
  },
  AvgDialog_44811_Content_40 = {
    Text = "Tänzer erhalten ihre Figuren, indem sie jahrelang vegetarisch leben. Abseits der Bühne sind ihre Körper praktisch unfähig, irgendeine Kraft auszuüben."
  },
  AvgDialog_44811_Content_41 = {
    Text = "Aber du bist anders; dein Geist hat das rigoroseste Training der Welt durchlaufen. Selbst beim \"Träumen\" kannst du die Macht des Erwachers nutzen, um diesen Kerl niederzuschlagen—"
  },
  AvgDialog_44811_Content_42 = {
    Text = "Auch wenn deine Fäuste geballt sind, schaffst du es, die Wut zu unterdrücken, die beinahe überläuft."
  },
  AvgDialog_44811_Content_43 = {
    Text = "(Den Zorn widerstehen)"
  },
  AvgDialog_44811_Content_44 = {
    Text = "... Vergiss es, das ist ohnehin nicht mein Körper."
  },
  AvgDialog_44811_Content_45 = {
    Text = "Der Protagonist von \"Traum-Invasion\" bist nicht du. Wenn du Charaktere im Traum willkürlich angreifst, wird das nur dazu führen, dass du dich weiter vom Eigentümer des Traums entfernst, und es könnte sogar so erscheinen, als sei das Entkommen aus der \"Traum-Invasion\" endlos fern."
  },
  AvgDialog_44811_Content_46 = {
    Text = "Weißt du überhaupt, was du heute getan hast! Ich habe dich zum neuen Leiter befördert, und so dankst du mir? Verursachst Probleme auf der entscheidenden Probenbühne?"
  },
  AvgDialog_44811_Content_47 = {
    Text = "Realisiert du, wie schändlich du bist? Als Haupttänzer hast du die Schritte vergessen und beinahe den Ruf der Yadri-Tanztruppe ruiniert!"
  },
  AvgDialog_44811_Content_48 = {
    Text = "Häuptling... Wenn ich der Häuptling bin, was ist dann mit Liz...?"
  },
  AvgDialog_44811_Content_49 = {
    Text = "Liz? Hmph, wenn sie nicht aufgehört hätte, wie hättest du dann die Hauptrolle übernehmen können?"
  },
  AvgDialog_44811_Content_5 = {
    Text = "...Preis...?"
  },
  AvgDialog_44811_Content_50 = {
    Text = "Schlag... Also, Liz war die ursprüngliche Führung, aber warum..."
  },
  AvgDialog_44811_Content_51 = {
    Text = "Warum so viele Warums! Geh zurück in dein Zimmer!"
  },
  AvgDialog_44811_Content_52 = {
    Text = "Der wütende Manager weigerte sich, weitere Fragen zu beantworten. Er packte deine Hand und schob dich in einen engen, dunklen Raum."
  },
  AvgDialog_44811_Content_53 = {
    Text = "Der Manager schlug die Tür zu und schrie durch sie zu dir."
  },
  AvgDialog_44811_Content_54 = {
    Text = "Du solltest besser beten, dass du Elizabeths Tanzschritte nicht vergisst, sonst wirst du im Haus der Freude verkauft!"
  },
  AvgDialog_44811_Content_55 = {
    Text = "Was... was für ein Zuhause?"
  },
  AvgDialog_44811_Content_56 = {Text = "—Klick."},
  AvgDialog_44811_Content_57 = {
    Text = "Nach dem kalten Geräusch des Schlosses weißt du, dass es keine Antwort geben wird — der Manager der Tanzgruppe hat dich im Raum eingesperrt."
  },
  AvgDialog_44811_Content_58 = {
    Text = "Du glitschiger alter Betrüger! Mit so einer schrecklichen Einstellung verfluche ich dich, die ganze Nacht auf der Toilette zu verbringen!"
  },
  AvgDialog_44811_Content_59 = {
    Text = "Du tritttest die Tür frustriert ein. Das schwere, alte Holz blieb fest im Rahmen stecken und widerstand still deinem schwachen Protest."
  },
  AvgDialog_44811_Content_6 = {
    Text = "Was besorgt dich! Wie auch immer... Aufführung... Auktion..."
  },
  AvgDialog_44811_Content_60 = {Text = "Hngh—!"},
  AvgDialog_44811_Content_61 = {
    Text = "Du hast den Schutz deiner Ballettschuhe überschätzt. Ein stechender Schmerz durchzuckt deinen großen Zeh, als ob das Nagelbett umgedreht worden wäre."
  },
  AvgDialog_44811_Content_62 = {
    Text = "Du kannst nicht anders, als ein schmerzliches Wimmern von dir zu geben, als du rückwärts auf das Bett fällst, dich mit hugenden Knien zusammenrollst und zweimal rollst."
  },
  AvgDialog_44811_Content_63 = {
    Text = "Jemand klopfte an das Fenster."
  },
  AvgDialog_44811_Content_64 = {
    Text = "Du warst gerade in den Raum eingetreten und hattest das Fenster noch nicht abgeschlossen. Jemand schob es auf und schlüpfte mühelos hinein."
  },
  AvgDialog_44811_Content_65 = {
    Text = "Du handelst immer so aggressiv, aber wenn es darum geht, tatsächlich jemanden zu schimpfen, warum bist du so machtlos?"
  },
  AvgDialog_44811_Content_66 = {
    Text = "Sie steht am Bett und beugt sich über dich mit ihren Händen hinter dem Rücken. Ihr langes, graues Haar fällt über ihre Schulter und auf dein Gesicht."
  },
  AvgDialog_44811_Content_67 = {Text = "Liz—!"},
  AvgDialog_44811_Content_68 = {
    Text = "Pssst, sei leise. Das Wohnheim und die Zuschauerränge sind nur durch eine Wand getrennt. Wenn die Musik aufhört, könnten die Leute draußen uns reden hören."
  },
  AvgDialog_44811_Content_69 = {
    Text = "Liz sagte, während sie ein kaltes Tuchbündel gegen dein Gesicht drückte."
  },
  AvgDialog_44811_Content_7 = {
    Text = "Bevor du die Gespräche der Gäste erkennen konntest, senkte sich der Vorhang langsam und teilte die Bühne und das Publikum in zwei separate Welten."
  },
  AvgDialog_44811_Content_70 = {
    Text = "Zisch—So kalt!"
  },
  AvgDialog_44811_Content_71 = {
    Text = "Wurde diese Seite gerade angegriffen?"
  },
  AvgDialog_44811_Content_72 = {
    Text = "Liz saß auf dem Bett und rollte einen Stoffbeutel über dein geschwollenes Gesicht. Die Kälte und der Schmerz ließen dich zusammenzucken."
  },
  AvgDialog_44811_Content_73 = {
    Text = "Eis... Wo hast du das Eis her?"
  },
  AvgDialog_44811_Content_74 = {
    Text = "Entnommen aus dem privaten Eiskeller dieses alten dicken Schweins."
  },
  AvgDialog_44811_Content_75 = {
    Text = "Fetter Schwein? Ist das der Verwalter? — Ah, entspann dich, entspann dich."
  },
  AvgDialog_44811_Content_76 = {
    Text = "Es ist der Höhepunkt des Sommers, und Eis ist kostbar. Warum sollte der Manager dir welches geben?"
  },
  AvgDialog_44811_Content_77 = {
    Text = "Liz' Untergebene zeigten in ihren Handlungen keine Gnade und drückten sogar noch härter zu—"
  },
  AvgDialog_44811_Content_78 = {
    Text = "Ich habe es selbst genommen."
  },
  AvgDialog_44811_Content_79 = {
    Text = "Liz ließ deine Hand los, zog dich hoch und setzte dich auf die Bettkante. Sie durchsuchte ein improvisiertes Eispack, fand einen kleinen Eiswürfel und steckte ihn dir in den Mund."
  },
  AvgDialog_44811_Content_8 = {
    Text = "So schön, das ist das wahre Ende von \"Schwanenlied\"... Wenn sie nicht eingegriffen hätte, kann ich mir nicht einmal vorstellen..."
  },
  AvgDialog_44811_Content_80 = {
    Text = "Eine seltsame Süße, begleitet von einem Schauer, breitet sich in deinem Mund aus und lindert den brennenden Schmerz an der Seite deines Gesichts. Mit Eis im Mund nimmst du das Kühlpack, das Liz dir gegeben hat, und drückst es gegen deine Wange."
  },
  AvgDialog_44811_Content_81 = {
    Text = "Hast du heute geweigert, auf der Bühne zu tanzen, weil du etwas herausgefunden hast?"
  },
  AvgDialog_44811_Content_82 = {Text = "Was?"},
  AvgDialog_44811_Content_83 = {
    Text = "Ihr Gesichtsausdruck wurde außergewöhnlich ernst und streng. Sie setzte sich ans Bett, hielt dein Gesicht mit beiden Händen und ließ dich fest auf sie schauen."
  },
  AvgDialog_44811_Content_84 = {
    Text = "Hast du die \"Wahrheit\" über das Tanzensemble entdeckt? Hat der Manager oder andere Agenten dich zu irgendetwas gezwungen—"
  },
  AvgDialog_44811_Content_85 = {
    Text = "Angst und Wut entzündeten allmählich ihre smaragdgrünen Augen, während ihre Handflächen kälter wurden als Eisbeutel."
  },
  AvgDialog_44811_Content_86 = {
    Text = "Du hast den Eisbeutel abgesetzt und sie direkt angestarrt."
  },
  AvgDialog_44811_Content_87 = {
    Text = "Was ist mit dir, Liz? Was haben sie dich gezwungen zu tun?"
  },
  AvgDialog_44811_Content_88 = {
    Text = "Sein Blick weicht unruhig von dir ab und richtet sich auf die entfernten Sterne am Nachthimmel außerhalb des Fensters."
  },
  AvgDialog_44811_Content_89 = {
    Text = "Die Stadt um Mitternacht hat das geschäftige Treiben des Tages verloren, und nur das Knarren der Kutschen, die über die Kopfsteinpflaster rollen, hallt durch die Straßen."
  },
  AvgDialog_44811_Content_9 = {
    Text = "Den Tag retten? Du gibst ihr zu viel Anerkennung! Wenn sie nicht aufgehört hätte, hätten wir sie nicht durch eine mittelmäßige Führungskraft ersetzen müssen..."
  },
  AvgDialog_44811_Content_90 = {
    Text = "Aber diese lachenden und bösartigen Stimmen durchdrangen die Wände, die von der Bühne kamen."
  },
  AvgDialog_44812_Content_1 = {
    Text = "Ein Sommernachtstraum"
  },
  AvgDialog_44812_Content_10 = {
    Text = "Elizabeth Saller... Saller, Saller, ich erinnere mich, dass das der Name einer Hoftanzgruppe ist."
  },
  AvgDialog_44812_Content_100 = {
    Text = "Du hast geweint..."
  },
  AvgDialog_44812_Content_101 = {
    Text = "Liz kam plötzlich näher zu dir, umschloss dein Gesicht mit beiden Händen und wischte die fallenden Tränen mit ihren Daumen weg."
  },
  AvgDialog_44812_Content_102 = {
    Text = "Bedeutet das, dass du mir zustimmst?"
  },
  AvgDialog_44812_Content_103 = {
    Text = "Ihre grau-grünen Augen sind nur wenige Zentimeter entfernt, und dieses Mal siehst du eindeutig den Kampf und den Schmerz, der in ihnen liegt. Sie wartet fast verzweifelt auf dich, sehnt sich nach deiner bekräftigenden Antwort."
  },
  AvgDialog_44812_Content_104 = {
    Text = "...Das stimmt, du hast absolut recht."
  },
  AvgDialog_44812_Content_105 = {
    Text = "Du erinnerst dich an das Gespräch mit Liz, aufgezeichnet im Mythag-Universitätsarchiv."
  },
  AvgDialog_44812_Content_106 = {
    Text = "Tanz... ist rein. Ein wahrer Tänzer sollte sein Herz durch seine Schritte ausdrücken, nicht nur durch seinen Körper."
  },
  AvgDialog_44812_Content_107 = {
    Text = "Liz's Augen leuchteten auf, voller Freude."
  },
  AvgDialog_44812_Content_108 = {
    Text = "Wir sind tatsächlich gleich. Du kannst mich verstehen..."
  },
  AvgDialog_44812_Content_109 = {
    Text = "So, kannst du mir helfen?"
  },
  AvgDialog_44812_Content_11 = {
    Text = "Ja, der Gründer der Saler-Truppe ist mein Großvater."
  },
  AvgDialog_44812_Content_110 = {
    Text = "Hilf dir? Liz, hast du einen Plan?"
  },
  AvgDialog_44812_Content_111 = {
    Text = "Ich möchte nicht, dass ihre Sünden sich ausbreiten... Ich werde dieses Übel hier beenden."
  },
  AvgDialog_44812_Content_112 = {
    Text = "Sicher. Ich werde dir helfen. Was muss ich tun?"
  },
  AvgDialog_44812_Content_113 = {
    Text = "Liz berührte sanft dein Gesicht, ihr Ton wurde weicher, und ein Hauch von Traurigkeit und Schuld erfüllte ihre Augen."
  },
  AvgDialog_44812_Content_114 = {
    Text = "Der Manager ist mir gegenüber sehr misstrauisch; er wird definitiv nicht glauben, dass ich freiwillig die Bühne betreten würde..."
  },
  AvgDialog_44812_Content_115 = {
    Text = "Sie kneifte den Stoff des improvisierten Kühlpacks mit zwei Fingern. Das meiste Eis war geschmolzen, und der Stoff war genug durchtränkt, um Wasser auszuwringen."
  },
  AvgDialog_44812_Content_116 = {
    Text = "Eine plötzliche Welle von unerklärlicher Schläfrigkeit überkam mich, selbst mein Atem stockte in meinem Hals—"
  },
  AvgDialog_44812_Content_117 = {
    Text = "Liz... Elizabeth... Was hast du mir angetan..."
  },
  AvgDialog_44812_Content_118 = {
    Text = "Du bist sein gewählter Anführer. Nur in deiner Abwesenheit hätte er keine andere Wahl, als sich an mich zu wenden..."
  },
  AvgDialog_44812_Content_119 = {
    Text = "Liz hielt dir ein Tuch über Mund und Nase, ein vertrauter, aber unangenehmer süßer Duft erfüllte deine Nasenlöcher."
  },
  AvgDialog_44812_Content_12 = {
    Text = "Oh... Ich verstehe. Elizabeth, darf ich dich Liz nennen? Tanzt du gerne?"
  },
  AvgDialog_44812_Content_120 = {
    Text = "Eis... Medizin..."
  },
  AvgDialog_44812_Content_121 = {
    Text = "...Ich bin überrascht, dass du so lange weiter auf diesem Eis rumgebissen hast. Schließlich ist es geschmolzen."
  },
  AvgDialog_44812_Content_122 = {
    Text = "Du wirst es gut haben. Ich habe gesehen, wie der Manager dieses Medikament benutzt hat, um \"unartige Mädchen\" gefügig zu machen... Es ist nur ein kurzer Schlaf."
  },
  AvgDialog_44812_Content_123 = {
    Text = "Genau, wenn du erwachst, wird alles vorbei sein..."
  },
  AvgDialog_44812_Content_13 = {
    Text = "Ich liebe das Tanzen, mein Herr. Mit nur einem Blick kann ich die Schritte wieder erinnern. Im Alter von zwölf Jahren choreografierte ich ein ganzes Tanzdrama."
  },
  AvgDialog_44812_Content_14 = {
    Text = "Oh? Können Sie choreografieren? Wie war der Empfang Ihres Tanzdramas?"
  },
  AvgDialog_44812_Content_15 = {
    Text = "Es tut mir leid, Manager. Mein Tanzauftritt war noch nie auf der Bühne. Meine Eltern sagten immer, sie würden mich enterben, wenn ich weiter tanze, und sogar mein Großvater hat mich deswegen mehrmals geschlagen..."
  },
  AvgDialog_44812_Content_16 = {
    Text = "<Small:Ich hätte nicht gedacht, dass dieser alte Kerl Saler so hohe Wellen schlägt...>"
  },
  AvgDialog_44812_Content_17 = {
    Text = "Manager? Hast du gerade etwas gesagt?"
  },
  AvgDialog_44812_Content_18 = {
    Text = "Ähem... Was ich sage, ist, dass dieser alte Geizkragen Salar dein Talent verschwendet!"
  },
  AvgDialog_44812_Content_19 = {
    Text = "Der Manager ging um Liz herum und musterte sie mit seinen Augen, als wäre sie ein Kunstwerk."
  },
  AvgDialog_44812_Content_2 = {
    Text = "Durch einen Flur voneinander getrennt, sind die Flüstern im Theater undeutlich. Man kann das Gemisch aus Verachtung und herablassendem Spott in diesen Stimmen spüren."
  },
  AvgDialog_44812_Content_20 = {
    Text = "Ihre Armmuskeln sind schöner als die eines Mädchens in der Truppe. Obwohl schlank, sind sie zweifellos stark, wie durch Ihren Vorsprech-Tanz demonstriert!"
  },
  AvgDialog_44812_Content_21 = {
    Text = "Dein Verhältnis von Taille zu Bein... Liz, du bist eine geborene Tänzerin! Dich und dein Talent zu Hause zu verstecken, ist eine Beleidigung für die Kunst!"
  },
  AvgDialog_44812_Content_22 = {
    Text = "Meinst du, die Yadri-Truppe wird meine Mitgliedschaft akzeptieren?"
  },
  AvgDialog_44812_Content_23 = {
    Text = "Ja! Ja. Du kannst der Tanzgruppe beitreten, die neue Hauptrolle übernehmen, mein neuer Ass! Dein Ballett — es wird im größten Theater Londiniums Premiere feiern!"
  },
  AvgDialog_44812_Content_24 = {
    Text = "Anführerin? Aber wenn du mich zur Anführerin machst, was ist dann mit der aktuellen Anführerin, Fräulein Deneuve... Ich habe gehört, sie ist eine außergewöhnlich stolze und talentierte Tänzerin..."
  },
  AvgDialog_44812_Content_25 = {
    Text = "Sie ist nicht wichtig! Was zählt, ist, dass wir dich jetzt haben!\nUnterschreibe diesen Mitgliedsvertrag, und ich garantiere dir, dass du ein weltberühmter Star wirst!"
  },
  AvgDialog_44812_Content_26 = {
    Text = "Der Manager schüttelte Liz' Hand. Überwältigt von Freude und Ehrgeiz, unterschrieb sie feierlich ihren Namen auf dem Papier."
  },
  AvgDialog_44812_Content_27 = {
    Text = "Und die verächtlichen oder mitleidigen Blicke der Mädchen wurden von ihr alle als Neid auf ihr Anerkanntwerden interpretiert."
  },
  AvgDialog_44812_Content_28 = {
    Text = "Vor drei Monaten"
  },
  AvgDialog_44812_Content_29 = {
    Text = "Das letzte Peitschenwirbeln, eins, zwei, drei, sehr gut."
  },
  AvgDialog_44812_Content_3 = {
    Text = "...Hör nicht auf diese Stimmen."
  },
  AvgDialog_44812_Content_30 = {
    Text = "Kalter Schweiß perlte aufgrund der Anspannung auf ihrer Stirn. Erst als die Tänzer ihre Bewegungen präzise vollendeten, atmete Liz schließlich erleichtert auf und schenkte ihren Mit Tänzern ein erfreutes Lächeln."
  },
  AvgDialog_44812_Content_31 = {
    Text = "Großartig... einfach großartig! Nur der letzte Akt bleibt, und mein \"Schwanengesang\" wird abgeschlossen sein"
  },
  AvgDialog_44812_Content_32 = {
    Text = "Liz wollte die Hände der Tänzerinnen ergreifen und diese Mädchen umarmen, doch sie wandten sich alle ab und mieden ihre Begeisterung."
  },
  AvgDialog_44812_Content_33 = {
    Text = "Was ist los, alle zusammen? Nur noch ein bisschen mehr Einsatz und wir können \"Schwanenlied\" nächsten Monat auf die Bühne bringen"
  },
  AvgDialog_44812_Content_34 = {
    Text = "Ah... Entschuldigung, ich war zu aufgeregt. Dank an alle, „Das letzte Lied des Schwans“ wurde geboren. Es ist die kollektive Schöpfung unserer Adri-Tanzgruppe—"
  },
  AvgDialog_44812_Content_35 = {
    Text = "Genug, Liz! Wir haben das so lange ertragen. Dieser Manager ist einfach—"
  },
  AvgDialog_44812_Content_36 = {
    Text = "Genug! Denk an den Schicksal von Denaf!"
  },
  AvgDialog_44812_Content_37 = {
    Text = "Die Tänzerin zieht ihren aufgeregten Partner, ihr Gesicht zeigt einen erleichterten Ausdruck, die Augen darteln umher."
  },
  AvgDialog_44812_Content_38 = {
    Text = "Fräulein Denafs... Schicksal? Der Manager sagte, sie hätte die Truppe verlassen und wäre in ihre Heimatstadt zurückgekehrt, um sich um die Alten zu kümmern, nicht wahr?"
  },
  AvgDialog_44812_Content_39 = {
    Text = "Sich um die Alten kümmern... Heh, der Ort, den der Manager für sie gewählt hat, Graf Jeffrey, ist sicherlich ein Ort für alte Menschen."
  },
  AvgDialog_44812_Content_4 = {
    Text = "Liz hob beide Hände und hielt dir die Ohren zu."
  },
  AvgDialog_44812_Content_40 = {
    Text = "Aber die Managerin schätzt Denaf wirklich, immer alte Männer mit einem Fuß im Grab für sie wählend... Vielleicht wird sie bald mit einem großen Erbe die Welt bereisen."
  },
  AvgDialog_44812_Content_41 = {
    Text = "Hey! Hat der Manager uns nicht speziell gewarnt, das ihr gegenüber zu erwähnen?!"
  },
  AvgDialog_44812_Content_42 = {
    Text = "Alter Graf, wähle, Erbe..."
  },
  AvgDialog_44812_Content_43 = {
    Text = "Worüber redet ihr...?"
  },
  AvgDialog_44812_Content_44 = {
    Text = "Um deiner echten Liebe zum Tanz willen—verlasse die Gruppe. Das ist alles, was ich sagen kann."
  },
  AvgDialog_44812_Content_45 = {
    Text = "Pssst, sei still! Versteck dich schnell hinter der Bühne – der Manager kommt!"
  },
  AvgDialog_44812_Content_46 = {
    Text = "Das Geräusch von Lederschuhen hallte von der anderen Seite der Bühne. Die Tänzer, die näher beieinander standen, stupsten einander schnell an und zogen sich backstage zurück, während Liz allein im Scheinwerferlicht stand."
  },
  AvgDialog_44812_Content_47 = {
    Text = "Sie erhielt langanhaltenden, großen Applaus—vom Manager, der sie der Tanzgruppe vorgestellt hatte. Der leidenschaftliche Glanz in seinen Augen ließ Liz ein leichtes Unbehagen verspüren."
  },
  AvgDialog_44812_Content_48 = {
    Text = "Liz, du bist ein wahrer Genie. Dieses Ballett wird sowohl die Truppe als auch deinen Wert auf beispiellose Höhen heben!"
  },
  AvgDialog_44812_Content_49 = {
    Text = "Nettovermögen...?"
  },
  AvgDialog_44812_Content_5 = {
    Text = "Hast du dir nicht immer gewünscht, warum ich aufgehört habe zu performen?"
  },
  AvgDialog_44812_Content_50 = {
    Text = "Graf Geoffrey ist bereit, die Betriebskosten der Truppe für ein ganzes Quartal zu decken, nur um dich zu treffen. Das sind unglaubliche Neuigkeiten."
  },
  AvgDialog_44812_Content_51 = {
    Text = "Boss, ich verstehe nicht... Wer ist dieser Graf? Warum ist er bereit, so viel für mich auszugeben?"
  },
  AvgDialog_44812_Content_52 = {
    Text = "Der Graf ist der größte Patron der Truppe und schätzt talentierte Tänzer sehr."
  },
  AvgDialog_44812_Content_53 = {
    Text = "Höre mir zu, die Gräfin ist vor zehn Tagen unerwartet verstorben. Dies ist deine perfekte Gelegenheit."
  },
  AvgDialog_44812_Content_54 = {
    Text = "Graf Geoffrey..."
  },
  AvgDialog_44812_Content_55 = {
    Text = "Genug! Denk an den Schicksal von Denaf!"
  },
  AvgDialog_44812_Content_56 = {
    Text = "Fräulein Denafs... Schicksal? Der Manager sagte, sie hätte die Truppe verlassen und wäre in ihre Heimatstadt zurückgekehrt, um sich um die Alten zu kümmern, nicht wahr?"
  },
  AvgDialog_44812_Content_57 = {
    Text = "Sich um die Alten kümmern... Heh, der Ort, den der Manager für sie gewählt hat, Graf Jeffrey, ist sicherlich ein Ort für alte Menschen."
  },
  AvgDialog_44812_Content_58 = {
    Text = "Aber die Managerin schätzt Denaf wirklich, immer alte Männer mit einem Fuß im Grab für sie wählend... Vielleicht wird sie bald mit einem großen Erbe die Welt bereisen."
  },
  AvgDialog_44812_Content_59 = {
    Text = "Ist die verstorbene Gräfin nicht die ehemalige Miss Denave?"
  },
  AvgDialog_44812_Content_6 = {
    Text = "Dann erreichte ihre Stimme in einem sanften und stetigen Ton deine Ohren durch ihre Hände."
  },
  AvgDialog_44812_Content_60 = {
    Text = "...Wer hat dir das gesagt?"
  },
  AvgDialog_44812_Content_61 = {
    Text = "Manager, sag mir bitte die Wahrheit.\n„Treffen mit dem Grafen“ – ist das wirklich so einfach?"
  },
  AvgDialog_44812_Content_62 = {
    Text = "Liz betrachtete den korpulenten Manager intensiv, ihr durchdringender Blick ließ ihn instinktiv seine Augen abwenden."
  },
  AvgDialog_44812_Content_63 = {
    Text = "Sag mir, hast du Miss Denaf an Graf Jeffrey verkauft?"
  },
  AvgDialog_44812_Content_64 = {Text = "Verkaufen?"},
  AvgDialog_44812_Content_65 = {
    Text = "Es scheint, dass der Manager einen Fehler in Liz' Worten erkannt hat, und sein Selbstvertrauen stieg, während er die Brust herausgestülpt und entschieden sprach."
  },
  AvgDialog_44812_Content_66 = {
    Text = "Denaf hat freiwillig den Grafen geheiratet! Was nach ihrer Hochzeit passiert ist, ist nicht mein Platz als bescheidener Troupe-Manager, darüber zu kommentieren. Sie sind schließlich Adelige!"
  },
  AvgDialog_44812_Content_67 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_44812_Content_68 = {
    Text = "Also, die Tanzgruppe war schon immer dein Werkzeug, um Ruhm und Reichtum zu verfolgen, deine Leiter zur Macht..."
  },
  AvgDialog_44812_Content_69 = {Text = "Ja. Genau!"},
  AvgDialog_44812_Content_7 = {
    Text = "Die Adley Tanzgruppe kann auf eine lange Geschichte zurückblicken und ist in der ganzen Föderation bekannt, oft als Gäste des Adels und sogar der Königsfamilien geehrt... Ich hörte ihren Namen, als ich sehr jung war."
  },
  AvgDialog_44812_Content_70 = {
    Text = "Weißt du, wie das Publikum uns sieht, dich sieht? Die Armen bewundern dich, während die Reichen dich kritisch betrachten! Über den ganzen Kontinent sind alle Tanzgruppen nicht anders."
  },
  AvgDialog_44812_Content_71 = {
    Text = "Meine Familie ist es nicht! Sie sind auch Mitglieder der Tanztruppe, sie..."
  },
  AvgDialog_44812_Content_72 = {
    Text = "Der alte Saler hat dir wirklich einen schönen Traum gesponnen – du hast keine Ahnung von den Machenschaften des Saller-Tanzvereins? Dein lieber Großvater Saler ist der berüchtigtste Zuhälter der gesamten Konstanten Föderation!"
  },
  AvgDialog_44812_Content_73 = {
    Text = "Kannst du endlich klar denken? In dieser Welt existiert pure Kunst einfach nicht!"
  },
  AvgDialog_44812_Content_74 = {
    Text = "Der Vertrag, den Sie beim Beitritt zur Tanzgruppe unterschrieben haben, gewährt mir volle Autorität über Sie – also, bis Sie bereit sind, den Grafen zu \"sehen\", werden Sie nirgendwo hingehen!"
  },
  AvgDialog_44812_Content_75 = {
    Text = "In Ordnung, ich werde das Theater nicht verlassen."
  },
  AvgDialog_44812_Content_76 = {
    Text = "Du weißt, was gut für dich ist, solange du—"
  },
  AvgDialog_44812_Content_77 = {
    Text = "Jedoch werde ich nicht mehr an der Probe von <Swan's Lament> teilnehmen. Ich werde dir die Tanzschritte des finalen Aktes nicht beibringen."
  },
  AvgDialog_44812_Content_78 = {Text = "Du—!"},
  AvgDialog_44812_Content_79 = {
    Text = "Ich werde nicht zulassen, dass du meine Arbeit weiterhin entweiht. Sie wird nicht zu einem Werkzeug für deine geheimen Geschäfte mit dem Adel werden."
  },
  AvgDialog_44812_Content_8 = {
    Text = "In einer lauen Sommernacht vor einem Jahr bin ich von zu Hause weggelaufen und habe mich der Yadri-Tanztruppe angeschlossen."
  },
  AvgDialog_44812_Content_80 = {
    Text = "Ich mache einen Streik."
  },
  AvgDialog_44812_Content_81 = {Text = "Jetzt"},
  AvgDialog_44812_Content_82 = {
    Text = "Die harte Realität lässt dich schwitzen und jagt dir einen Schauer über den Schädel. Das Eispack in deiner Hand hat sich unbemerkt in Wasser aufgelöst und dein Tanzkleid durchtränkt."
  },
  AvgDialog_44812_Content_83 = {
    Text = "Der Manager der Tanzgruppe... plant tatsächlich so etwas."
  },
  AvgDialog_44812_Content_84 = {
    Text = "Hast du... ihre Sünden vorher nicht erkannt?"
  },
  AvgDialog_44812_Content_85 = {
    Text = "Du bist der Rookie, den das dumme Schwein aus dem einfachen Volk ausgegraben hat, genau wie ich vor einem Jahr. Ich dachte, du hättest etwas entdeckt, weshalb du auf der Bühne warst..."
  },
  AvgDialog_44812_Content_86 = {
    Text = "Nein, ich fühle mich einfach zu nervös..."
  },
  AvgDialog_44812_Content_87 = {
    Text = "Alles, was Liz gesagt hat, wirbelt in deinem Kopf. Du möchtest instinktiv ihr glauben, aber..."
  },
  AvgDialog_44812_Content_88 = {
    Text = "Du wirfst einen Blick auf den Kalender neben deinem Bett. Dieser Traum fühlt sich sehr nah an deiner \" Realität \" an. Elizabeth Saller lebt in einer Vergangenheit, die weniger als dreißig Jahre zurückliegt."
  },
  AvgDialog_44812_Content_89 = {
    Text = "In deiner Zeit gelten Ballettaufführungen als der Inbegriff von Eleganz. Unter dem Patronat von Edel Dexter hast du Ramona zu mehreren Aufführungen verschiedener Tanztruppen begleitet."
  },
  AvgDialog_44812_Content_9 = {
    Text = "Vor einem Jahr"
  },
  AvgDialog_44812_Content_90 = {
    Text = "Wenn die heutigen Tanzgruppen so corrupt sind, was ist genau passiert, das zu einer so drastischen Veränderung geführt hat?"
  },
  AvgDialog_44812_Content_91 = {
    Text = "Jedoch, da Sie bereits aufgegeben hatten, warum sind Sie heute Abend auf die Bühne gegangen, um die Situation zu retten?"
  },
  AvgDialog_44812_Content_92 = {
    Text = "Liz sah zu dir auf, wie eine Ältere, die ein naives Kind betrachtet – obwohl sie selbst noch minderjährig sein sollte."
  },
  AvgDialog_44812_Content_93 = {
    Text = "Weil ich es nicht ertragen kann, loszulassen."
  },
  AvgDialog_44812_Content_94 = {
    Text = "Bevor ich laufen lernte, hatte ich bereits gemeistert, wie man mit den Armen schwingt. Während Kinder in meinem Alter mit Verstecken beschäftigt waren, übte ich heimlich das Tippen im Lagerhaus und fand Freude daran."
  },
  AvgDialog_44812_Content_95 = {
    Text = "Ich kann das Tanzen nicht aufgeben, noch kann ich meine Arbeit verlassen... Ich kann es nicht ertragen, den Manager zu sehen, der \"Swan Song\" mit unbeholfenen und groben Schritten füllt."
  },
  AvgDialog_44812_Content_96 = {
    Text = "Er erniedrigt mich... und meine Kunst."
  },
  AvgDialog_44812_Content_97 = {
    Text = "Liz's Griff um deine Hände wird fester, so stark, dass du das Gefühl hast, in ihren Schmerz eingesogen zu werden."
  },
  AvgDialog_44812_Content_98 = {
    Text = "In einem flüchtigen Moment scheint deine Seele ihren Zorn und ihren Kummer zu begreifen, und dieser Körper ist keine Ausnahme."
  },
  AvgDialog_44812_Content_99 = {
    Text = "Unkontrollierbar blinzelnd, hafteten Tränen an meinen Wimpern und verschwommen die Welt vor meinen Augen."
  },
  AvgDialog_44833_Content_1 = {
    Text = "Schwanengesang"
  },
  AvgDialog_44833_Content_10 = {
    Text = "Was ist dieser Geruch... so vertraut."
  },
  AvgDialog_44833_Content_11 = {
    Text = "Im Moment, in dem deine Hand die Tür berührt, spürst du die Wärme, die den hinteren Korridor durchdringt, während Rauchfäden durch die Ritzen in den Raum sickernd."
  },
  AvgDialog_44833_Content_12 = {
    Text = "In Flammen?!"
  },
  AvgDialog_44833_Content_13 = {
    Text = "Der gesunde Menschenverstand sagt dir, dass die Tür nicht lange halten wird. Wenn die Struktur dieses Theaters komplett aus Holz besteht, wird das gesamte Gebäude bald in Flammen aufgehen."
  },
  AvgDialog_44833_Content_14 = {
    Text = "Um den Raum zu verlassen, kannst du die Tür nicht benutzen - dein Blick wandert zum einzigen Fenster.\nWenn Liz in der Lage war, durch das Fenster hinein zu klettern, kannst du auch durch das Fenster hinaus klettern."
  },
  AvgDialog_44833_Content_15 = {
    Text = "Wie erwartet, stand eine Kutsche unten vor dem Fenster. Du bist aus dem Fenster geklettert, hast dich auf das Dach der Kutsche gestellt und hast das Zimmer im zweiten Stock mühelos verlassen."
  },
  AvgDialog_44833_Content_16 = {
    Text = "Du folgst dem Geräusch zum Vorderplatz des Theaters. Der Platz ist belebt, mit üppig gekleideten Gästen, die sich drängen, um das Theater zu verlassen—"
  },
  AvgDialog_44833_Content_17 = {
    Text = "Verschwinde aus dem Weg! Ich bin der Butler von Graf Jeffrey. Lass mich vorbei!"
  },
  AvgDialog_44833_Content_18 = {
    Text = "Sie ist verrückt geworden! Völlig verrückt!"
  },
  AvgDialog_44833_Content_19 = {
    Text = "Du hast die Adelige, deren Haarknoten sich gelöst hatte, schnell aufgefangen."
  },
  AvgDialog_44833_Content_2 = {Text = "Knistern."},
  AvgDialog_44833_Content_20 = {
    Text = "Madame, was ist im Theater passiert?"
  },
  AvgDialog_44833_Content_21 = {
    Text = "Du bist ein Tänzer?! Fass mich nicht an! Du bist mit dieser verrückten Frau im zweiten Theater, oder?!"
  },
  AvgDialog_44833_Content_22 = {
    Text = "Zweites Theater... Ist das Liz? Könnte es Elizabeth sein? Das Mädchen im schwarzen Tanzkleid?"
  },
  AvgDialog_44833_Content_23 = {
    Text = "Du kennst diesen Verrückten! Und du behauptest, du seist nicht ihr Komplize! Schnell! Töte diesen Tänzer jetzt!"
  },
  AvgDialog_44833_Content_24 = {
    Text = "Die Diener und einige Zuschauer tauschten Blicke aus, offensichtlich unwilling, das Gesetz für die Adligen zu brechen."
  },
  AvgDialog_44833_Content_25 = {
    Text = "Ich gebe 100 Leo-Fänge an denjenigen, der als Erster einen Kopf abtrennt! Nein, 300 Leo-Fänge!"
  },
  AvgDialog_44833_Content_26 = {
    Text = "Eine satte Summe Geld wurde an die zuvor kauernden Handlanger geworfen, was sie dazu veranlasste, ihre Werkzeuge zu heben und auf dich loszustürmen—"
  },
  AvgDialog_44833_Content_3 = {
    Text = "Du wirst benommen wach, hältst dir den Kopf. Draußen ist es immer noch dunkel.\nVielleicht warst du eine halbe Stunde weg, oder vielleicht lagst du dort einen ganzen Tag lang."
  },
  AvgDialog_44833_Content_4 = {
    Text = "Es riecht nach hochkonzentriertem Äther... Der Verwalter hat tatsächlich so eine gefährliche Substanz in einem Eiswürfel eingefroren."
  },
  AvgDialog_44833_Content_5 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_44833_Content_6 = {
    Text = "Sobald Liz hereinkam, gab sie mir Eis zu essen, also... egal, wie ich ihr letztendlich antwortete, sie hatte von Anfang an bereits beschlossen, mich zu vergiften..."
  },
  AvgDialog_44833_Content_7 = {
    Text = "Elizabeth Saller, Liz... Was versuchst du genau zu tun?"
  },
  AvgDialog_44833_Content_8 = {Text = "Knistern."},
  AvgDialog_44833_Content_9 = {
    Text = "Ein primärer, natürlicher verrußter Duft erfüllt die Nüstern, dringt tief ins Gehirn ein und vertreibt gewaltsam die nachwirkenden Effekte des Tranks."
  },
  AvgDialog_44835_Content_1 = {
    Text = "Du fasst den Mut, die Tür zum ersten Theater aufzustoßen. Zwar haben die Flammen diesen Ort noch nicht erreicht, aber dicker Rauch und brennende Hitze treffen dich frontal und stechen in deine Augen."
  },
  AvgDialog_44835_Content_10 = {
    Text = "Die Tänzerin zitterte gewaltsam, als hätten sie den Namen des Teufels gehört."
  },
  AvgDialog_44835_Content_11 = {
    Text = "Elizabeth, Elizabeth ist verrückt geworden! Sie hat das Essen für das Publikum und alle anderen vergiftet! Alle sind ohnmächtig!"
  },
  AvgDialog_44835_Content_12 = {
    Text = "Nur jemand wie ich, ein dicker Mann, der das Essen verboten ist, und einige Damen, die Mahlzeiten auslassen, um ihre Figur zu halten, haben es geschafft zu entkommen..."
  },
  AvgDialog_44835_Content_13 = {
    Text = "Hey! Hey, lauf nicht weg! Ich habe dir gesagt, dass du nicht hineingehen sollst!"
  },
  AvgDialog_44835_Content_14 = {
    Text = "Ignoriere die Warnung des Tänzers, du rennst ohne Zögern auf das zweite Theater zu."
  },
  AvgDialog_44835_Content_15 = {
    Text = "@2 Garten Zweites Theater"
  },
  AvgDialog_44835_Content_16 = {Text = "Liz!"},
  AvgDialog_44835_Content_17 = {
    Text = "Als du die Tür zum zweiten Theater aufdrückst, erstarrt dir das Blut in den Adern. Gäste und Tänzer liegen überall bewusstlos, ihr Leben und Tod unbekannt."
  },
  AvgDialog_44835_Content_18 = {
    Text = "Die einst belebte Halle ist nun still, Flammen breiten sich überall aus, und nur die Bereiche, die durch die D-Marke gekennzeichnet sind, blieben unbeschädigt—es gibt Dinge, die selbst das Feuer nicht verschlingen kann."
  },
  AvgDialog_44835_Content_19 = {
    Text = "Du hättest nicht kommen sollen."
  },
  AvgDialog_44835_Content_2 = {
    Text = "*Hust, hust...*"
  },
  AvgDialog_44835_Content_20 = {
    Text = "Liz steht in der Ecke der Bühne. Du kannst sie nicht sehen; nur ihre Stimme erreicht dich aus dem Theater."
  },
  AvgDialog_44835_Content_21 = {
    Text = "Liz, hast du dieses Feuer entfacht?"
  },
  AvgDialog_44835_Content_22 = {
    Text = "Zwei verzerrte Kichern kommen aus der Richtung der Bühne. Du weißt, diese Frage ist vergeblich.\nOb Liz das Feuer gelegt hat oder nicht, ihre und „deine“ Schicksale sind besiegelt."
  },
  AvgDialog_44835_Content_23 = {
    Text = "█Am A.F. 29 @1 Jahr @2 brach das Feuer im Zweiten Theater des Gartens aus, während das Ballett \"Schwanen-Requiem\" aufgeführt wurde.\n█Dreizehn Adelige, darunter der Graf Albert aus der königlichen Familie, sowie 25 Diener, 12 Tänzer und 1 Troupenleiter kamen bei dem Feuer ums Leben.\n█Ermittlungen ergaben, dass der Täter niemand anderes war als die Prima Ballerina des Balletts \"Elizabeth Saler\", die sich auf der Todesliste befand."
  },
  AvgDialog_44835_Content_24 = {
    Text = "Liz antwortet dir nicht. Sie hat immer noch den Rücken zu dir gewandt und bewegt eine Hand hin und her, als würde sie etwas aufwickeln."
  },
  AvgDialog_44835_Content_25 = {Text = "Alright."},
  AvgDialog_44835_Content_26 = {
    Text = "Sie machte zwei Schritte nach vorne und stand in der Mitte der Bühne. Sanfte Musik strömte heraus und vermischte sich mit den knisternden Flammen."
  },
  AvgDialog_44835_Content_27 = {
    Text = "\"Das wahre Finale von 'Swan Song' kann nur mit der Begleitung eines Phonographen aufgeführt werden.\""
  },
  AvgDialog_44835_Content_28 = {
    Text = "Du lässt die Musiker gehen, weil sie unschuldig waren, oder?"
  },
  AvgDialog_44835_Content_29 = {
    Text = "Du kannst auch gehen. Ich habe dich lange beobachtet, und du bist kein Komplize von ihnen geworden."
  },
  AvgDialog_44835_Content_3 = {
    Text = "Du hast ein Tischtuch abgerissen, eine dekorative Vase umgestoßen und das Tuch mit Blumewasser durchnässt."
  },
  AvgDialog_44835_Content_30 = {
    Text = "Ich... nein, ich habe deine Kunst entweiht. Hast du es vergessen? Ich habe fast dein \"Schwanenlied\" ruiniert"
  },
  AvgDialog_44835_Content_31 = {
    Text = "Liz kniete auf der Bühne und winkte dich zu sich heran. Erst jetzt bemerkst du, dass die Bühne bereits mit schwarzem Schleim bedeckt ist – ist das D-Schleim?"
  },
  AvgDialog_44835_Content_32 = {
    Text = "Du hattest erst zwei Schritte zu ihr gemacht, als ein Windstoß das Theaterfenster aufblies. Die Flammen, die still und heimlich im Dunkeln glimmten, wurden plötzlich belebt, stürmten vorwärts und verschlangen die Bühnenvorhänge."
  },
  AvgDialog_44835_Content_33 = {
    Text = "Liz! Geh runter, das Feuer hat begonnen!"
  },
  AvgDialog_44835_Content_34 = {
    Text = "Der Türsturz des zweiten Theaters kollabierte mit einem lauten Krachen, die verkohlten Balken trafen den Boden und verstreuten Asche und Funken, entzündeten den Wollteppich."
  },
  AvgDialog_44835_Content_35 = {
    Text = "Liz, Elizabeth! Hör auf, töricht zu sein. Lass uns gemeinsam fliehen, solange wir noch können!"
  },
  AvgDialog_44835_Content_36 = {
    Text = "Gib der Welt eine weitere Chance... In dreißig Jahren wird der Tanz eine der reinsten Kunstformen sein. Gib der Welt einfach ein bisschen mehr Zeit..."
  },
  AvgDialog_44835_Content_37 = {
    Text = "Liz liegt am Rand der Bühne und streckt sich erneut nach dir aus."
  },
  AvgDialog_44835_Content_38 = {
    Text = "Ihre Handfläche war mit D-Schleim bedeckt, doch sie vermittelte die Wärme eines lebenden Menschen, als sie an deine Wange gedrückt wurde."
  },
  AvgDialog_44835_Content_39 = {
    Text = "Ich wusste, dass ich diese Sünden heute nicht beenden konnte... Ich wusste es von Anfang an."
  },
  AvgDialog_44835_Content_4 = {
    Text = "Du hältst dir den Mund und die Nase mit einem nassen Tuch zu und atmest den erdigen, wurzelartigen Duft des Nebels ein. Gebückt kriechst du langsam vorwärts und tastest dich entlang des Teppichs."
  },
  AvgDialog_44835_Content_40 = {
    Text = "Was ich will, ist, dass die Welt die Dunkelheit erkennt. Ich möchte, dass das Sonnenlicht hereinscheint, aber ich habe keinen anderen Weg."
  },
  AvgDialog_44835_Content_41 = {
    Text = "Nachdem sie das gesagt hatte, schob sie dich gewaltsam weg."
  },
  AvgDialog_44835_Content_42 = {
    Text = "Entschuldigung, ich habe dich betäubt, ohne dich zu konsultieren."
  },
  AvgDialog_44835_Content_43 = {
    Text = "Verlässt du wirklich nicht? Es ist nicht zu spät, aus dem Fenster zu springen."
  },
  AvgDialog_44835_Content_44 = {
    Text = "Du schütteltest den Kopf und setztest dich an den Rand der Bühne, umarmst deine Beine."
  },
  AvgDialog_44835_Content_45 = {
    Text = "Du zählst die Leute im Theater, die Tanzkleider tragen, einschließlich Liz. Es sind insgesamt nur 11."
  },
  AvgDialog_44835_Content_46 = {
    Text = "Du bist die zwölfte Person, die von den Flammen verzehrt wird."
  },
  AvgDialog_44835_Content_47 = {
    Text = "In Ordnung, halte einfach deine Augen auf mich gerichtet."
  },
  AvgDialog_44835_Content_48 = {
    Text = "Elizabeth Saller präsentiert ihren Solo-Tanz „Das Klagelied des Schwans.“"
  },
  AvgDialog_44835_Content_49 = {
    Text = "Liz verbeugt sich vor Ihnen und hebt lässig den brennenden Vorhang. Der D-Schleim an ihren Händen und ihrem Körper entzündet sich sofort—nein, das ist Teer."
  },
  AvgDialog_44835_Content_5 = {Text = "—Au!"},
  AvgDialog_44835_Content_50 = {
    Text = "Dunkle Feuerwerke blühen leise auf dem Rock, wie die zitternden Flügel eines Schwans, der den Staub abschüttelt."
  },
  AvgDialog_44835_Content_51 = {
    Text = "Liz dreht sich elegant, jeder Dreh bringt sie den feurigen Meteoriten näher, die am Nachthimmel zischen."
  },
  AvgDialog_44835_Content_52 = {
    Text = "Die Tochter der Kunst ruft das letzte Kapitel des Lebens aus, Flammen rollen über die Bühne, doch ihre Augen zeigen keine Angst."
  },
  AvgDialog_44835_Content_53 = {
    Text = "Die Flammen verzehrten das Phonograph, reduzierten es zu Asche. Der letzte Ton verflog im Feuer und ihre Gestalt verblasste allmählich im Feuerschein."
  },
  AvgDialog_44835_Content_54 = {
    Text = "Im letzten Sprung, umarmt von Flammen, erreicht eine Geschichte ihren Abschluss, und eine Ära kommt zu ihrem Ende."
  },
  AvgDialog_44835_Content_6 = {
    Text = "Das laufende Mädchen stieß mit dir zusammen, und ihr beiden fiel zu Boden."
  },
  AvgDialog_44835_Content_7 = {
    Text = "Du... Warum gehst du noch tiefer? Lauf weg!"
  },
  AvgDialog_44835_Content_8 = {
    Text = "Du erinnerst dich an diese Tänzerin. Laut Liz scheint sie eine außergewöhnlich warmherzige Person zu sein."
  },
  AvgDialog_44835_Content_9 = {
    Text = "Ist Liz drinnen?"
  },
  AvgDialog_45413_Content_1 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45413_Content_10 = {Text = "N..."},
  AvgDialog_45413_Content_11 = {
    Text = "Es ist lange her, dass ich zuletzt daran dachte, wie ich dieses Aussehen erlangte."
  },
  AvgDialog_45413_Content_12 = {
    Text = "Liegt es daran, dass ich den Namen dieses Mannes gehört habe, oder sind es die letzten Momente, die vor meinen Augen vorbeiziehen?"
  },
  AvgDialog_45413_Content_13 = {
    Text = "Erinnerungen aus einer sehr, sehr langen Zeit tauchten plötzlich in meinem Kopf auf."
  },
  AvgDialog_45413_Content_14 = {
    Text = "Bevor ich ein \"Tier\" wurde, war ich nur ein gewöhnlicher Detektiv, der ein ereignisloses Leben führte und nach Erhalt meiner Zahlung ein paar Drinks genoss und die Freizeit auskostete."
  },
  AvgDialog_45413_Content_15 = {
    Text = "Dank außergewöhnlichem Glück bittet mich der Ermittler von Londinium oft, beim Sammeln von Hinweisen und beim Lokalisieren von Verdächtigen zu helfen."
  },
  AvgDialog_45413_Content_16 = {
    Text = "Es gibt keinen Grund, eine Lieferung direkt vor die Tür nicht anzunehmen."
  },
  AvgDialog_45413_Content_17 = {
    Text = "Bis der Verdächtige, den ich gefasst hatte, mysteriös aus der Haft verschwand und nur die sicher befestigten silbernen Handschellen, perfekt intakt, im Wind klimperten."
  },
  AvgDialog_45413_Content_18 = {
    Text = "Natürlich hat das nichts mit mir zu tun. Ich verschwende meine neu verdiente Provision normalerweise in diesem auffälligen Untergrund-Casino."
  },
  AvgDialog_45413_Content_19 = {
    Text = "Du bist... dieser Flüchtling!"
  },
  AvgDialog_45413_Content_2 = {
    Text = "Eine massive durchsichtige Klaue erschien am Himmel und schleuderte Ryker brutal gegen die Wand."
  },
  AvgDialog_45413_Content_20 = {
    Text = "Ah, habt ihr meinen Typen gefangen?"
  },
  AvgDialog_45413_Content_21 = {
    Text = "Es macht mir nichts aus, mit dir noch zwei Tage im Gefängnis zu verbringen—"
  },
  AvgDialog_45413_Content_22 = {
    Text = "Der Mann schüttelte den Würfelbecher neben sich."
  },
  AvgDialog_45413_Content_23 = {
    Text = "Aber du musst mich zuerst besiegen."
  },
  AvgDialog_45413_Content_24 = {
    Text = "Ich habe nicht gedacht, dass ich verlieren würde."
  },
  AvgDialog_45413_Content_25 = {
    Text = "Ryker lebt seit 25 Jahren und hat noch nie einmal verloren."
  },
  AvgDialog_45413_Content_26 = {
    Text = "Solange ich mich intensiv konzentriere, lasse die Casino-Lichter, das Geräusch der rollenden Würfel und das Flackern des Kartenspielens meinen Geist erfüllen..."
  },
  AvgDialog_45413_Content_27 = {
    Text = "Intuition wird mir die Antwort geben."
  },
  AvgDialog_45413_Content_28 = {Text = "Öffne es."},
  AvgDialog_45413_Content_29 = {
    Text = "Hey, warte! Du hast noch nicht gesagt, worauf du wetten willst."
  },
  AvgDialog_45413_Content_3 = {
    Text = "Blut rann aus Rykers Mund, als die Luft aus seinen Lungen gedrückt wurde, was es ihm schwer machte, zu atmen."
  },
  AvgDialog_45413_Content_30 = {
    Text = "Was willst du?"
  },
  AvgDialog_45413_Content_31 = {
    Text = [[
Ich hatte nie die Absicht, auf etwas zu setzen.
Egal was passiert, ich komme immer obenauf heraus.]]
  },
  AvgDialog_45413_Content_32 = {
    Text = "Keine Sorge, du kannst haben, was du willst."
  },
  AvgDialog_45413_Content_33 = {
    Text = "Hmm... Was ist mit diesem Zigarre?"
  },
  AvgDialog_45413_Content_34 = {
    Text = "Er zeigte auf die Zigarre, die ich rauchte."
  },
  AvgDialog_45413_Content_35 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45413_Content_36 = {
    Text = "Entschuldigung, ich werde es gerne akzeptieren."
  },
  AvgDialog_45413_Content_37 = {
    Text = "Der Mann grinste, als er sich die brennende Zigarre aus meiner Hand nahm, ignorierte meinen geschockten Gesichtsausdruck. Er zog tief daran und blies spöttisch weiße Rauchkringel aus."
  },
  AvgDialog_45413_Content_38 = {
    Text = "Wie wäre es mit einer weiteren Runde?"
  },
  AvgDialog_45413_Content_39 = {
    Text = "An diesem Tag verlor ich meine Brieftasche, meinen Stock, meinen Hut, meine Krawatte und meinen Anzug."
  },
  AvgDialog_45413_Content_4 = {
    Text = "Ist es wirklich sinnvoll, mehr Zeit zu verschwenden? Deine Kugeln werden schließlich ausgehen."
  },
  AvgDialog_45413_Content_40 = {
    Text = "Wir spielten High Card, Blackjack und Texas Hold'em."
  },
  AvgDialog_45413_Content_41 = {
    Text = "Ich habe hundert Kämpfe geführt, ohne einen einzigen Sieg."
  },
  AvgDialog_45413_Content_42 = {
    Text = "Schließlich zog er einen Revolver heraus."
  },
  AvgDialog_45413_Content_43 = {
    Text = "Das ist ein grausames Spiel namens Roulette, bei dem menschliche Leben auf dem Spiel stehen."
  },
  AvgDialog_45413_Content_44 = {
    Text = "Die Spieler zielen der Reihe nach mit einem Revolver auf ihre eigenen Köpfe und ziehen den Abzug, bis die letzte Kugel einen von ihnen in die Schläfe trifft."
  },
  AvgDialog_45413_Content_45 = {
    Text = "Ich feuerte ohne zu zögern, und die Kugel nahm mir mein Leben ebenso schnell."
  },
  AvgDialog_45413_Content_46 = {
    Text = "Um ihn zum Geständnis zu bringen und der Gerechtigkeit zuzuführen, jagte ich diesem Mann namens \"N\" nach und setzte 316 Spiele aufs Spiel."
  },
  AvgDialog_45413_Content_47 = {
    Text = "Ich habe nicht erwartet, dass du so ein starkes Gerechtigkeitsbewusstsein hast."
  },
  AvgDialog_45413_Content_48 = {
    Text = "Nein, es hat nichts mit einem Gerechtigkeitssinn zu tun. Ich habe einfach nie verloren."
  },
  AvgDialog_45413_Content_49 = {
    Text = "Magst du es nicht zu verlieren, kannst es nicht ertragen zu verlieren oder willst einfach nicht verlieren?"
  },
  AvgDialog_45413_Content_5 = {
    Text = "Und mit jedem Atemzug, den du nimmst, jedem Herzschlag, wird meine Darbietung mit neuer Energie durchdrungen."
  },
  AvgDialog_45413_Content_50 = {
    Text = "Das ist kein Wettbewerb um Semantik, mein Freund."
  },
  AvgDialog_45413_Content_51 = {
    Text = "Ich verliere einfach nie."
  },
  AvgDialog_45413_Content_52 = {
    Text = "Für mich ist der Sieg ein vorherbestimmtes Schicksal. Deshalb bin ich neugierig - neugierig darauf, wie dieser Mann zerbrach und das Schicksal übernahm."
  },
  AvgDialog_45413_Content_53 = {
    Text = "Neugier auf Kosten des Lebens, alle nennen mich einen Verrückten. Ich frage mich, wer von uns beiden wirklich verrückt ist."
  },
  AvgDialog_45413_Content_54 = {
    Text = "Du übertreibst. Diese Menschen haben ihr Leben der Erforschung und Lösung der Auflösung gewidmet. Herbert strebte nach der Aufstiegs des menschlichen Körpers, während sich die Aram auf das ewige Erbe ihrer Blutlinie konzentrierten."
  },
  AvgDialog_45413_Content_55 = {
    Text = "Jeder verbringt Zeit mit Dingen, ohne zu wissen, ob es Ergebnisse geben wird. Meine Neugier ist da nicht anders; sie kostet nichts."
  },
  AvgDialog_45413_Content_56 = {
    Text = "Ganz zu schweigen davon, dass dieser Mann mir einen neuen Körper und einen neuen Wette angeboten hat. Jetzt habe ich endlose Zeit, um neue Welten zu erkunden. Vielleicht ist es ein Segen in disguise."
  },
  AvgDialog_45413_Content_57 = {
    Text = "Eine Kugel, ein Moment des Schmerzes und er wird seinen Einsatz gegen mich platzieren, immer siegreich hervorgehend—"
  },
  AvgDialog_45413_Content_58 = {
    Text = "Dieses Mal wette ich, dass du verhindern kannst, dass %player% den Ritualplatz erreicht."
  },
  AvgDialog_45413_Content_59 = {
    Text = "Ryker drückte den Revolver an seine Schläfe."
  },
  AvgDialog_45413_Content_6 = {
    Text = "Je mehr du kämpfst, desto enger wird der Käfig."
  },
  AvgDialog_45413_Content_60 = {
    Text = "Zu zuversichtlich, zu unüberlegt!"
  },
  AvgDialog_45413_Content_61 = {
    Text = "Was, wenn ich dir sage, dass das Ganze von dieser Person orchestriert wurde?\nGlaubst du, er würde dir immer noch helfen?"
  },
  AvgDialog_45413_Content_62 = {
    Text = "Ryker ließ ein leises Seufzen hören."
  },
  AvgDialog_45413_Content_63 = {
    Text = "Als ein gleichgesinnter Sucher nach Spaß kannst du menschliche Emotionen nie vollständig wahrnehmen, daher ist dein Verständnis von Freude nicht vollständig."
  },
  AvgDialog_45413_Content_64 = {
    Text = "Ich setze dieses Leben als meinen Einsatz—ich vertraue darauf, dass er sein Versprechen halten wird."
  },
  AvgDialog_45413_Content_65 = {
    Text = "\"Boom!\" Ein Schuss ertönte."
  },
  AvgDialog_45413_Content_66 = {
    Text = "Einige Sekunden der Stille folgten."
  },
  AvgDialog_45413_Content_67 = {
    Text = "Was zur... Du hast mich wirklich erschreckt!"
  },
  AvgDialog_45413_Content_68 = {
    Text = "Über der Bühne hallten plötzlich fröhliche Lachen wider."
  },
  AvgDialog_45413_Content_69 = {
    Text = "Sehr gut, sehr gut! Du bist immer noch so arrogant wie eh und je. Mein Geschenk dieses perfekten Körpers war nicht umsonst.\nDa das der Fall ist, werde ich die Reste deines Lebens genießen und dir deinen Wunsch erfüllen."
  },
  AvgDialog_45413_Content_7 = {
    Text = "Die Person, die dir dieses Aussehen verliehen hat, heißt \"N\", richtig? Er ist wirklich geizig, nicht wahr?"
  },
  AvgDialog_45413_Content_70 = {
    Text = "Zwei rein schwarze und goldene 10-seitige Würfel erschienen in Rykers Handfläche."
  },
  AvgDialog_45413_Content_71 = {
    Text = "Würfle die Würfel. Wenn du eine 1 würfelst, werde ich deine Feinde verschlingen."
  },
  AvgDialog_45413_Content_72 = {
    Text = "Ryker lachte, sein Husten spritzte Blut unter dem Scheinwerfer."
  },
  AvgDialog_45413_Content_73 = {
    Text = "Unerreichbar."
  },
  AvgDialog_45413_Content_74 = {
    Text = "Ryker würfelte mit zwei 10-seitigen Würfeln."
  },
  AvgDialog_45413_Content_75 = {
    Text = "Der Würfel rollt mit einem grollenden Geräusch."
  },
  AvgDialog_45413_Content_76 = {
    Text = "Wenn es um Glück geht..."
  },
  AvgDialog_45413_Content_77 = {
    Text = "Ein Würfel kommt bei 00 zum Stillstand."
  },
  AvgDialog_45413_Content_78 = {
    Text = "Ich bin Ryker, und ich habe nie verloren."
  },
  AvgDialog_45413_Content_79 = {
    Text = "Ein weiterer Würfel bleibt bei 01 stehen."
  },
  AvgDialog_45413_Content_8 = {
    Text = "Mit dem sich lösenden Haken fiel Ryker, hustete heftig und brach schwach auf den Boden zusammen."
  },
  AvgDialog_45413_Content_80 = {
    Text = "Im nächsten Moment hallte das ungebremste Lachen des überlegenen Mannes und die herzzerreißenden Schreie des Magiers wider."
  },
  AvgDialog_45413_Content_81 = {
    Text = "Schwarzer D-Schleim löste den gesamten Vorhang auf, bis nur noch zwei halbmondförmige Überreste übrig waren, die wogen und auf den Sand fielen."
  },
  AvgDialog_45413_Content_82 = {
    Text = "Wie die sanften, lächelnden Augen eines Mannes."
  },
  AvgDialog_45413_Content_9 = {
    Text = "Du bist so schwach, dass du nicht einmal wie ein Erwachter wirkst. Ist dein Gnostischer Index über 21?"
  },
  AvgDialog_45414_Content_1 = {
    Text = "Mon... Monster!"
  },
  AvgDialog_45414_Content_10 = {
    Text = "Skelett, das Skelett ist im dunklen Raum voraus!"
  },
  AvgDialog_45414_Content_11 = {
    Text = "Zur gleichen Zeit - Verlassene Fabrik Pipeline"
  },
  AvgDialog_45414_Content_12 = {
    Text = "Ein junger Mann kroch entlang der verlassenen Fabrikrohre, Rost und Kohlenstaub färbten sein hübsches Gesicht mit gefleckten schwarzen Patches."
  },
  AvgDialog_45414_Content_13 = {
    Text = "Er bewegte sich so leise wie möglich und folgte dem Team unten in gemächlichem Tempo."
  },
  AvgDialog_45414_Content_14 = {
    Text = "Ich habe Lady Juliette von Anfang an gewarnt: Diese Reisenden sind definitiv nicht gut..."
  },
  AvgDialog_45414_Content_15 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45414_Content_16 = {
    Text = "Ich habe dich erwischt!"
  },
  AvgDialog_45414_Content_17 = {
    Text = "Am Eingang des dunklen Raumes trat der wolfsköpfige Mann durch die eiserne Tür, ließ einen Arlan-Soldaten an der Tür zurück, während die anderen allmählich über die gefallene Tür traten."
  },
  AvgDialog_45414_Content_18 = {
    Text = "Der Junge nutzte die Gelegenheit, um die Röhre hinunterzurutschen und die Kapuze sowie die Seile des Aran-Soldaten zu lösen."
  },
  AvgDialog_45414_Content_19 = {
    Text = "Pssst, wecke keinen Verdacht. Ich werde ihnen folgen, und du gehst den Lord Alva benachrichtigen..."
  },
  AvgDialog_45414_Content_2 = {
    Text = "Du kämpfst jeden Tag gegen Nubien, und doch denkst du immer noch, ich sei das Monster."
  },
  AvgDialog_45414_Content_3 = {
    Text = "Sag mir, wo hast du das Heilige Baum-Skelett verborgen?"
  },
  AvgDialog_45414_Content_4 = {
    Text = "Der Mutterbaum wacht über uns. Wir werden keine Informationen preisgeben—"
  },
  AvgDialog_45414_Content_5 = {
    Text = "Oh? Ist das wahr?"
  },
  AvgDialog_45414_Content_6 = {
    Text = "Ryker beugte sich vor, sein wolfähnliches Atmen trug ein tiefes, heiseres Grollen. Das Geräusch seiner zahnenden Kiefer war klar in der stillen Fabrik zu hören."
  },
  AvgDialog_45414_Content_7 = {
    Text = "Weißt du, wie es sich anfühlt, von einem Wolf zerfetzt zu werden? Lass mich dir sagen, es ist der Schmerz scharfer Zähne, die tief eindringen, dann ganze Stücke von Caro und Nerven herausgerissen werden—"
  },
  AvgDialog_45414_Content_8 = {
    Text = "<Shake:Nein, iss mich nicht. Ich habe gesagt—>"
  },
  AvgDialog_45414_Content_9 = {Text = "Hey, du—"},
  AvgDialog_45415_Content_1 = {
    Text = "Der Sturm intensivierte sich, die Aran-Soldaten schrien, tobten, riefen, beteten und fluchten."
  },
  AvgDialog_45415_Content_10 = {
    Text = "Unzählige Aram knien ehrfürchtig in Richtung der Thais"
  },
  AvgDialog_45415_Content_11 = {
    Text = "Die wütenden Sandkreaturen beruhigen sich durch Gebete, der Sturm legt sich"
  },
  AvgDialog_45415_Content_12 = {
    Text = "Es ist die Königin! Es ist die Königin!"
  },
  AvgDialog_45415_Content_13 = {
    Text = "Danke für den Schutz der Königin!"
  },
  AvgDialog_45415_Content_14 = {
    Text = "Die Augen der Königin sind immer noch auf uns gerichtet!"
  },
  AvgDialog_45415_Content_15 = {
    Text = "Wir... sind angekommen!"
  },
  AvgDialog_45415_Content_2 = {
    Text = "Auf einer nahen Düne siehst du die Silhouette"
  },
  AvgDialog_45415_Content_3 = {
    Text = "Sie erkennen die Silhouette. Es ist Thais."
  },
  AvgDialog_45415_Content_4 = {
    Text = "Der Sturm... ist er kleiner geworden?"
  },
  AvgDialog_45415_Content_5 = {
    Text = "Sie sang unbekannte Gebete, ließ den wilden Wind ihren Schleier aufwirbeln und ging langsam und sicher in den dunklen Sandsturm"
  },
  AvgDialog_45415_Content_6 = {
    Text = "Ohrenbetäubender Lärm, doch das Gebet ist klar zu hören, als würde es in deinem Schädel widerhallen"
  },
  AvgDialog_45415_Content_7 = {
    Text = "Im tobenden Wüstensturm sprach sie ruhig mit einer Kreatur der Wüste"
  },
  AvgDialog_45415_Content_8 = {
    Text = "Es ist die Königin! Die Königin ist gekommen, um uns zu retten, um Arlan zu retten!"
  },
  AvgDialog_45415_Content_9 = {
    Text = "Alans Team, das verzweifelt zu entkommen versucht hatte, kam plötzlich zum Stillstand."
  },
  AvgDialog_45416_Content_1 = {
    Text = "Es sieht so aus, als würdest du diese kleinen Monster erkennen, oder, Kleiner?"
  },
  AvgDialog_45416_Content_10 = {
    Text = "Mit dem Segen des Mutterbaums bekämpfen die Aram-Leute eine hohe Säuglingssterblichkeitsrate durch schnelle Fortpflanzung."
  },
  AvgDialog_45416_Content_11 = {
    Text = "So brauchen wir eine Lagerfeuerfeier... Eine Lagerfeuerfeier ist unerlässlich."
  },
  AvgDialog_45416_Content_12 = {
    Text = "Über Nubia"
  },
  AvgDialog_45416_Content_13 = {
    Text = "Ich kenne ihre Ursprünge auch nicht, aber ich kann eine vertraute Aura wahrnehmen, die von ihnen ausgeht."
  },
  AvgDialog_45416_Content_14 = {
    Text = "Manchmal habe ich das Gefühl, dass Nubien auch einer der Nachkommen von Arlan ist."
  },
  AvgDialog_45416_Content_15 = {
    Text = "......Sagst du, sie zwingen die Aram, die Sturmwand zu öffnen?"
  },
  AvgDialog_45416_Content_16 = {
    Text = "Das stimmt mit meiner Vermutung überein. Siehst du, die Aram wollen auch in die Sturmwand gelangen, um den Mutterbaum zu finden, oder?"
  },
  AvgDialog_45416_Content_17 = {
    Text = "Aber das wird nicht funktionieren. Die Sturmwand öffnet sich nur für anerkannte Boten."
  },
  AvgDialog_45416_Content_18 = {
    Text = "Irgendwelche anderen Fragen?"
  },
  AvgDialog_45416_Content_19 = {
    Text = "Über Juliette"
  },
  AvgDialog_45416_Content_2 = {
    Text = "Hmm, nein, im Vergleich zu diesen Bestien bist du das echte Monster."
  },
  AvgDialog_45416_Content_20 = {
    Text = "Außerdem möchte ich mehr über diesen \"Boten\", Juliette, erfahren."
  },
  AvgDialog_45416_Content_21 = {
    Text = "\"Bote aus einem fremden Land\"?"
  },
  AvgDialog_45416_Content_22 = {
    Text = "Diese Frage sollte ich stellen."
  },
  AvgDialog_45416_Content_23 = {
    Text = "%player%, vertraust du dem Boten namens Juliette?"
  },
  AvgDialog_45416_Content_24 = {Text = "Glauben"},
  AvgDialog_45416_Content_25 = {
    Text = "Glaube nicht"
  },
  AvgDialog_45416_Content_26 = {
    Text = "Bevor du sprechen konntest, lehnte sich Thais vor und berührte sanft deine Lippen mit ihrem Fingerspitze."
  },
  AvgDialog_45416_Content_27 = {
    Text = "Nehmt euch Zeit und erzählt mir langsam."
  },
  AvgDialog_45416_Content_28 = {
    Text = "Unsere Zeit... ist noch lang."
  },
  AvgDialog_45416_Content_3 = {
    Text = "Kleines Monster, gibt es etwas, das du die Königin von Aran fragen möchtest?"
  },
  AvgDialog_45416_Content_4 = {
    Text = "Bezüglich des Lagerfeuerfestes"
  },
  AvgDialog_45416_Content_5 = {
    Text = "*Seufz*, du hast wirklich eine herzzerreißende Frage gestellt."
  },
  AvgDialog_45416_Content_6 = {
    Text = "Ich habe nie erwartet, dass jemand sich weigern würde, ein Kind für Königin Aran zu bekommen."
  },
  AvgDialog_45416_Content_7 = {
    Text = "Kurz gesagt, denkst du, dass diese Wüste für das Überleben von Menschen geeignet ist?"
  },
  AvgDialog_45416_Content_8 = {
    Text = "Du erinnerst dich an die fegenden Sandstürme, nahezu trockene Wasserquellen, nachtaktive Bestien, giftige Schlangen und Ameisen und die aufgelöste Wasserspeicherung, während du den Kopf schüttelst"
  },
  AvgDialog_45416_Content_9 = {
    Text = "Aber die Leute von Aran können diesen Ort nicht verlassen."
  },
  AvgDialog_45417_Content_1 = {
    Text = "Die Äste des Mutterbaums scheinen eigenen Willen zu haben, sich in alle Richtungen auszudehnen, menschliche Umrisse erscheinen darin, unbeholfen und schmerzhaft"
  },
  AvgDialog_45417_Content_10 = {
    Text = "Ramona, entzünde den Mutterbaum mit dem Silberchipfeuer! Nur du kannst das tun!"
  },
  AvgDialog_45417_Content_11 = {
    Text = "Der silberne Phantasma stößt auf die Wurzeln des Mutterbaums, die silberne Flamme entfacht in einem Moment und verwandelt sich in die lodernde Flamme namens Zerstörung"
  },
  AvgDialog_45417_Content_12 = {
    Text = "Die Flammenzungen schossen wie silberne Schlangen die Äste hinauf, die Blätter kämpften und schrien in den wütenden Flammen, ein ohrenbetäubendes Zischen, als ob der Mutterbaum vor Schmerz stöhnte und heulte"
  },
  AvgDialog_45417_Content_13 = {
    Text = "Warte, der Baum fällt, der Hüter ist noch nicht unten!"
  },
  AvgDialog_45417_Content_14 = {
    Text = "Keine Sorge, gutes Kind, ich werde {Male=er,Female=sie} dir unversehrt zurückbringen"
  },
  AvgDialog_45417_Content_15 = {
    Text = "Der riesige Baum bebt, Himmel und Erde erzittern"
  },
  AvgDialog_45417_Content_16 = {
    Text = "Du verlierst den Halt und fällst geradewegs nach unten—"
  },
  AvgDialog_45417_Content_17 = {
    Text = "Wie hoch ist es hier? Tausend Fuß? Oder mehr?"
  },
  AvgDialog_45417_Content_18 = {
    Text = "Dann umarmte dich ein warmer, weicher Schoß"
  },
  AvgDialog_45417_Content_19 = {
    Text = "Braves Kind, du hast das großartig gemacht"
  },
  AvgDialog_45417_Content_2 = {
    Text = "Der erste, der eine Kehle entwickelte, stöhnte und brach mühsam aus den Fesseln des Mutterbaums, stürzte in den heiligen Fluss"
  },
  AvgDialog_45417_Content_20 = {
    Text = "An ihrer Brust strahlt der von dir angelegte weiße Jadeanhänger im Kontrast zu ihrer seidigen Haut"
  },
  AvgDialog_45417_Content_21 = {
    Text = "Thais griff danach, nahm es ab und brachte es an ihren Mund, wo sie sanft darauf biss"
  },
  AvgDialog_45417_Content_22 = {
    Text = "Ich werde zum heiligen Fluss zurückkehren und das ganze Land nähren.\nDies ist ein Abschiedsgeschenk für dich"
  },
  AvgDialog_45417_Content_23 = {
    Text = "Im Moment des Sturzes in den reißenden Heiligen Fluss berührten ihre Lippen deine"
  },
  AvgDialog_45417_Content_24 = {
    Text = "Eure Atemzüge vermischen sich, eure Seelen verschmelzen"
  },
  AvgDialog_45417_Content_25 = {
    Text = "Eine Zunge drang ein, warm, feucht, zärtlich und unwiderstehlich"
  },
  AvgDialog_45417_Content_26 = {
    Text = "Der Kuss war eine Mischung aus süßer Liebe, dem Geschmack von Blut und einem kleinen, runden Etwas"
  },
  AvgDialog_45417_Content_27 = {
    Text = "Die Samen des Baumes"
  },
  AvgDialog_45417_Content_28 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45417_Content_29 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45417_Content_3 = {Text = "...Bumm!"},
  AvgDialog_45417_Content_30 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45417_Content_31 = {
    Text = "Es ist zwar nicht so, wie ich es mir vorgestellt habe... aber es ist vorbei"
  },
  AvgDialog_45417_Content_32 = {
    Text = "Als Nachkommen der Essenz des Verlangens sind die Yaran bestrebt, ihre Blutlinie aufrechtzuerhalten."
  },
  AvgDialog_45417_Content_33 = {
    Text = "Zu diesem Zweck verehren wir den Mutterbaum, vermischen die Milch des Mutterbaums mit Knochen und Blut und beten für übermenschliche Fortpflanzungsfähigkeit"
  },
  AvgDialog_45417_Content_34 = {
    Text = "Solange eine Person der schwarzen Apokalypse entkommt, kann die Zivilisation in der nächsten Generation fortbestehen"
  },
  AvgDialog_45417_Content_35 = {
    Text = "Aber wir lagen falsch."
  },
  AvgDialog_45417_Content_36 = {
    Text = "Was die Alan-Leute antreibt, ist nicht irgendeine spezifische Alan-Ethnie; über die lange Zeitspanne hinweg sind sie zu Knechten des Vermehrungswunsches geworden und haben sich zu sehr auf das Konzept der „Nachkommen“ verlassen."
  },
  AvgDialog_45417_Content_37 = {
    Text = "In Jahrhunderten des Exils... ist Alva es, die die Aram weiter führt"
  },
  AvgDialog_45417_Content_38 = {
    Text = "Tawil, du hast recht; wir sollten an den menschlichen Willen glauben"
  },
  AvgDialog_45417_Content_39 = {
    Text = "Selbst in der dunkelsten Nacht, selbst bei schwachem Licht, ist ihr unermüdlicher Geist der wahre Schlüssel zur Veränderung der vorherbestimmten Zukunft"
  },
  AvgDialog_45417_Content_4 = {Text = "Platschen!"},
  AvgDialog_45417_Content_40 = {
    Text = "Ich habe jetzt eine neue Antwort"
  },
  AvgDialog_45417_Content_41 = {
    Text = "Also, sei großzügig und leih mir deinen Erben, okay?"
  },
  AvgDialog_45417_Content_42 = {
    Text = "Ich vertraue dieser Person und übergebe das Feuer an {Male=er,Female=sie}"
  },
  AvgDialog_45417_Content_43 = {
    Text = "Dieser Samen wird eines Tages Wurzeln schlagen und zu einem riesigen Baum wachsen,"
  },
  AvgDialog_45417_Content_44 = {
    Text = "So wie am Tag der Geburt des ersten Mutterbaums"
  },
  AvgDialog_45417_Content_45 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45417_Content_46 = {
    Text = "Das ist der letzte Samen, ich lasse ihn in deinem Körper"
  },
  AvgDialog_45417_Content_47 = {
    Text = "Bevor es mein Blut in die Erde trägt, darfst du nicht sterben"
  },
  AvgDialog_45417_Content_48 = {
    Text = "Erinnere dich immer an mich, vergiss mich nicht"
  },
  AvgDialog_45417_Content_49 = {
    Text = "Die Flut tobt"
  },
  AvgDialog_45417_Content_5 = {
    Text = "Dong! Dong!"
  },
  AvgDialog_45417_Content_50 = {
    Text = "Diese warme Umarmung stieß dich weg"
  },
  AvgDialog_45417_Content_51 = {
    Text = "Im Auf und Ab des Wassers siehst du, wie sie tiefer in den Fluss treibt"
  },
  AvgDialog_45417_Content_52 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45417_Content_53 = {
    Text = "Eine zarte, weiße Hand hält dich fest, die Kraft ist vertraut und entschlossen"
  },
  AvgDialog_45417_Content_54 = {Text = "%player%!"},
  AvgDialog_45417_Content_6 = {
    Text = "Immer wieder fallen Aram"
  },
  AvgDialog_45417_Content_7 = {
    Text = "Einige Sekunden später tauchten kleine Köpfe aus dem Wasser und schwammen zum Ufer"
  },
  AvgDialog_45417_Content_8 = {
    Text = "Die Äste unter deinen Füßen beginnen zu zittern"
  },
  AvgDialog_45417_Content_9 = {
    Text = "Es ist Zeit!"
  },
  AvgDialog_45418_Content_1 = {
    Text = "*Hust, hust*, ihr macht euch zusammen über mich lustig. Wie schamlos."
  },
  AvgDialog_45418_Content_10 = {
    Text = [[
Kein Grund.
Der Samen des Mutterbaums ist nicht drinnen.]]
  },
  AvgDialog_45418_Content_11 = {
    Text = "Unerwartet sind die Überreste des heiligen Baumes der Aram-Völker so weit aufgelöst worden..."
  },
  AvgDialog_45418_Content_12 = {
    Text = "Herberts und Casiahs Gestalten verschwanden am Ende des Sandmeers. Ihr drei hattet endlich einen Moment zum Durchatmen."
  },
  AvgDialog_45418_Content_13 = {
    Text = "Du kannst Alva jetzt benachrichtigen, das Skelett zu sammeln."
  },
  AvgDialog_45418_Content_14 = {
    Text = "Keine Eile, dies ist unsere beste Chance, die Überreste des Mutterbaums zu verstehen, oder?"
  },
  AvgDialog_45418_Content_15 = {
    Text = "Außerdem... sieh dir die Ecke an, wo Casiah war."
  },
  AvgDialog_45418_Content_16 = {
    Text = "In einem Spalt des Skeletts sickert schwarze Flüssigkeit langsam heraus und fließt in die absichtlich in den Boden eingravierte Rille."
  },
  AvgDialog_45418_Content_17 = {
    Text = "Warte einen Moment, ich glaube, ich habe eine ähnliche Struktur im Lager der Königin gesehen..."
  },
  AvgDialog_45418_Content_18 = {
    Text = [[
Das deutet darauf hin, dass es nicht Casiah's Machenschaft war, sondern eine Struktur, die von den Aram geschaffen wurde.
Aus irgendeinem Grund extrahieren sie D-Schleim aus Skeletten.]]
  },
  AvgDialog_45418_Content_19 = {
    Text = "Erlauben Sie mir, Ihre Neugier zu stillen."
  },
  AvgDialog_45418_Content_2 = {Text = "Aber..."},
  AvgDialog_45418_Content_20 = {
    Text = "Irgendwann kehrt Juliette zurück.\nSie erscheint hinter dem eisernen Tor und schreitet die Steinstufen zu dir hinauf."
  },
  AvgDialog_45418_Content_21 = {
    Text = "Da wir uns alle mit dem Mysterium befassen, werde ich direkt fragen: Hat die Mythag-Universität Kenntnisse über die drei Substanzen?"
  },
  AvgDialog_45418_Content_22 = {
    Text = "Ramona und Ryker schauen zu dir.\nBerücksichtigt man Juliets Haltung auf dem Weg, zögerst du einen Moment und nickst dann."
  },
  AvgDialog_45418_Content_23 = {
    Text = "Da du von der Essenz des Verlangens gehört hast, wird es viel einfacher zu erklären."
  },
  AvgDialog_45418_Content_24 = {
    Text = "Die sogenannten Überreste des heiligen Baumes... sind die Mumie der Substanz des Begehrens <Yellow:Tifreyyesod>."
  },
  AvgDialog_45418_Content_25 = {
    Text = "Für die Aram ist das angesammelte Flüssigkeit in diesem Sarg das Wichtigste."
  },
  AvgDialog_45418_Content_26 = {
    Text = "Es fließt endlos aus der Mumie."
  },
  AvgDialog_45418_Content_27 = {
    Text = "Du und ich wissen beide... das sind D-Schleim."
  },
  AvgDialog_45418_Content_28 = {
    Text = "Die göttliche Macht von Tifreyasod verlangsamt die Erosion durch Auflösung erheblich, die die Aram zur Fortpflanzung und Wiedergeburt nutzen."
  },
  AvgDialog_45418_Content_29 = {
    Text = "Warte, du meinst..."
  },
  AvgDialog_45418_Content_3 = {
    Text = "Casiahs Veranstaltungsort ist bereit!"
  },
  AvgDialog_45418_Content_30 = {
    Text = "Ramona beginnt zu würgen."
  },
  AvgDialog_45418_Content_31 = {
    Text = "Du... hast den <Yellow:D-Schleim> aus den Überresten des Mutterbaums benutzt... um das <Yellow:Getränk> der Party zu machen."
  },
  AvgDialog_45418_Content_32 = {
    Text = "So werden sie in den Wahnsinn absteigen, und sie werden abnormale Fruchtbarkeit erlangen..."
  },
  AvgDialog_45418_Content_33 = {
    Text = "Das kommt nicht von der Blutlinie, sondern von dieser Mumie."
  },
  AvgDialog_45418_Content_34 = {
    Text = "Wegen des Verschwindens des Mutterbaums und der Schwächung der göttlichen Kraft steigt der Anteil an deformierten Föten weiterhin."
  },
  AvgDialog_45418_Content_35 = {
    Text = "Du hast es auch bemerkt, oder? Der schwarze Auflösungsnebel um den Aram."
  },
  AvgDialog_45418_Content_36 = {
    Text = "Die Aram unterscheiden sich von gewöhnlichen Menschen; sie sind im Wesentlichen die Blutlinie des Mutterbaums."
  },
  AvgDialog_45418_Content_37 = {
    Text = "Wenn der Mutterbaum vollständig aufgelöst ist, wird nicht nur ihre Fortpflanzungsfähigkeit verschwinden, sondern auch alle bestehenden Aran-Blutlinien."
  },
  AvgDialog_45418_Content_38 = {
    Text = "Also, die Aram müssen die Sturmwand durchbrechen, um den Mutterbaum wieder zum Leben zu erwecken."
  },
  AvgDialog_45418_Content_39 = {
    Text = "Ich weiß nicht, warum Mythag Leute nach Remouahe geschickt hat, aber basierend auf dem Vertrauen zwischen uns werde ich Arams tiefstes Geheimnis euch allen offenbaren."
  },
  AvgDialog_45418_Content_4 = {
    Text = "Eine riesige transparente Klaue durchbricht die Luft, zerschmettert die lockere Wand. Casiah klettert darauf und die Klaue trägt sie in das ferne Sandscherenmeer."
  },
  AvgDialog_45418_Content_40 = {
    Text = "Wenn du das Ritual stopst, wird jeder Aram, den du in Remouahe gesehen hast, ohne Ausnahme sterben."
  },
  AvgDialog_45418_Content_41 = {
    Text = "Beim Erhalten der Nachricht kam William erneut mitten in der Nacht ins Lager."
  },
  AvgDialog_45418_Content_42 = {
    Text = "Schläft Ramona?"
  },
  AvgDialog_45418_Content_43 = {
    Text = "Hmm, mein ganzer Körper fühlt sich extrem heiß an."
  },
  AvgDialog_45418_Content_44 = {
    Text = "Was denkst du über das Wesen der Begierde?"
  },
  AvgDialog_45418_Content_45 = {
    Text = "Ich weiß nicht."
  },
  AvgDialog_45418_Content_46 = {
    Text = "Ich hätte es erwarten sollen, als ich von diesem morbiden Feuerbankett hörte."
  },
  AvgDialog_45418_Content_47 = {
    Text = "Diese Fortpflanzungsmethode unterscheidet sich von der gewöhnlicher Kadathianer."
  },
  AvgDialog_45418_Content_48 = {
    Text = "Außerdem hat Ramona, seit sie in Lemwash angekommen ist, Fieber gehabt."
  },
  AvgDialog_45418_Content_49 = {
    Text = "Hat das damit zu tun?"
  },
  AvgDialog_45418_Content_5 = {
    Text = "Wir sehen uns wieder!"
  },
  AvgDialog_45418_Content_50 = {
    Text = "Ich habe eine Vermutung..."
  },
  AvgDialog_45418_Content_51 = {
    Text = "Du hast Tawil getroffen und bist dir über <Blue:Ramona: Zeitlos> bewusst. Du solltest ein gewisses Verständnis für ihre Verbindung zu Tawil haben."
  },
  AvgDialog_45418_Content_52 = {
    Text = "Die Kräfte der drei Plasmide stoßen sich gegenseitig ab. Das Wasser aus der Blutlinie des Lust-Plasmids ist für Ramona an sich ein Gift."
  },
  AvgDialog_45418_Content_53 = {
    Text = "Je weiter du vorankommst, desto näher kommst du dem Ursprung des Heiligen Flusses, desto intensiver wird dieser abstoßende Effekt."
  },
  AvgDialog_45418_Content_54 = {
    Text = "Die Aram werden morgen versuchen, die Sturmwand erneut zu durchbrechen."
  },
  AvgDialog_45418_Content_55 = {
    Text = "Ramona muss außerhalb der Sturmwand bleiben."
  },
  AvgDialog_45418_Content_56 = {
    Text = "Der Weg vor uns wird von uns dreien beschritten."
  },
  AvgDialog_45418_Content_57 = {
    Text = "Unmöglich, ich bin auch ein Teil von Mythag, unmöglich..."
  },
  AvgDialog_45418_Content_58 = {
    Text = "Ramona kämpfte, um vom Bett aufzustehn, schwankte ein wenig und fiel beinahe zurück."
  },
  AvgDialog_45418_Content_59 = {
    Text = "Ramona, dein Gesundheitszustand macht es ungeeignet für dich, uns zu begleiten."
  },
  AvgDialog_45418_Content_6 = {Text = "Hey—"},
  AvgDialog_45418_Content_60 = {
    Text = "Du steckst ihre Decke ein.\nDas Mädchen, geschüttelt von der Hitzewelle, zittert und wirft dir einen Blick zu, ohne ein Wort zu sagen."
  },
  AvgDialog_45418_Content_61 = {
    Text = "Denk nicht einmal daran, mich allein zu lassen..."
  },
  AvgDialog_45418_Content_7 = {
    Text = "Lass sie gehen, die heiligen Baumreste sind noch hier, schwer zu sagen, ob es sich um eine List handelt, um den Tiger zu locken"
  },
  AvgDialog_45418_Content_8 = {
    Text = "Casiah schüttelt eine Flasche mit wirbelnder schwarzer Flüssigkeit."
  },
  AvgDialog_45418_Content_9 = {
    Text = "Ist das wirklich genug? Ich hätte auch den Sarg herausbringen können."
  },
  AvgDialog_45419_Content_1 = {
    Text = "Die riesige experimentelle Schöpfung der Bildhauergesellschaft fiel mit einem dumpfen Geräusch zusammen und erfüllte die Luft mit dem Gestank von Rost."
  },
  AvgDialog_45419_Content_10 = {
    Text = "In Arlans Territorium sind die wichtigsten Angelegenheiten möglicherweise nicht von Ihnen zu entscheiden."
  },
  AvgDialog_45419_Content_11 = {
    Text = "Eine wütende Stimme hallt durch die leere Fabrik.\nDie Königin von Aran führt Dutzende von Aram-Soldaten an und hat euch in diesen Ruinen eingekesselt."
  },
  AvgDialog_45419_Content_12 = {
    Text = "Der Soldat, den du außerhalb der Fabrik versteckt hast, hat irgendwie die Seile gelöst und zeigt jetzt auf deinen Standort hinter ihr."
  },
  AvgDialog_45419_Content_13 = {
    Text = "Ich denke, wir haben keinen Platz mehr für Verhandlungen, Fremder."
  },
  AvgDialog_45419_Content_2 = {
    Text = "...Der Skelett ist nicht hier."
  },
  AvgDialog_45419_Content_3 = {
    Text = "Nein, ich war einmal hier."
  },
  AvgDialog_45419_Content_4 = {
    Text = "Rykers Fingerspitze streift den Boden, hebt sich dann, um etwas zwischen Daumen und Zeigefinger zu nehmen und wegzublasen.\nStaub löst sich von seinen schwarzen Handschuhen und tanzt im Fensterlicht."
  },
  AvgDialog_45419_Content_5 = {
    Text = "Die Dicke des Staubes variiert, und schwache Fußabdrücke sind kaum zu erkennen."
  },
  AvgDialog_45419_Content_6 = {
    Text = [[
Schatten von dem zerbrochenen Fenster fielen auf die Zementplattform, wo die Silhouette des Sarges verblieb.
Aber der Sarg war spurlos verschwunden.]]
  },
  AvgDialog_45419_Content_7 = {
    Text = "Wir hätten es vorhersehen müssen – Lady Narzisse würde sich nicht damit zufrieden geben, die Informationen nur einmal zu verkaufen."
  },
  AvgDialog_45419_Content_8 = {
    Text = "Vielleicht sollte sie einen exklusiven Kaufpreis anbieten?"
  },
  AvgDialog_45419_Content_9 = {
    Text = "Lass deinen unnötigen Humor beiseite. Die oberste Priorität ist jetzt der Aufenthaltsort des Mutterbaum-Skeletts."
  },
  AvgDialog_45420_Content_1 = {
    Text = "Gnädige Elva, bitte erlauben Sie mir, ein paar Worte mit {Male=er,Female=sie} zu sprechen"
  },
  AvgDialog_45420_Content_10 = {
    Text = "Ihr Gesichtsausdruck ist seltsam fanatisch, ihre Sprache schnell, ihr Körper lehnt sich unwillkürlich vor, ihre Augen sind wie Geister"
  },
  AvgDialog_45420_Content_11 = {
    Text = "Leb wohl, blinder Blick"
  },
  AvgDialog_45420_Content_12 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45420_Content_13 = {
    Text = "Nein, das ist noch nicht das Ende. Denn diese Person hat dich mit der innigsten Stimme gebeten, ihren Namen zu rufen"
  },
  AvgDialog_45420_Content_14 = {
    Text = "In Gedanken an Thais' Blick aktivierte der Silberne Schlüssel"
  },
  AvgDialog_45420_Content_15 = {
    Text = "Silberne Fäden schwingen, ziehen, suchen"
  },
  AvgDialog_45420_Content_16 = {
    Text = "Am Ende des Fadens ist nichts"
  },
  AvgDialog_45420_Content_17 = {
    Text = "Das Phänomen namens Erosion hat sie vollständig verschlungen, selbst du kannst ihre Spur nicht finden"
  },
  AvgDialog_45420_Content_18 = {
    Text = "Hoffst du, dass sie zurückkommt? Die Aram gehorchen bereits mir"
  },
  AvgDialog_45420_Content_19 = {
    Text = "Thais... Thais!"
  },
  AvgDialog_45420_Content_2 = {
    Text = "Du und Alva sind in eine Pattsituation geraten, als Juliette spricht und euch aufhält"
  },
  AvgDialog_45420_Content_20 = {
    Text = "Wenn sie erscheinen kann, wird sie mit ihrer göttlichen Kraft Alva die Zukunft des Aram offenbaren"
  },
  AvgDialog_45420_Content_21 = {
    Text = "Selbst wenn du nur eine Entschuldigung vorbringst, musst du hier nicht mit Alva konfrontiert werden"
  },
  AvgDialog_45420_Content_22 = {
    Text = "Thais... Thais—!"
  },
  AvgDialog_45420_Content_23 = {
    Text = "Egal wie laut du rufst, es hilft nichts. Dein letztes Gespräch mit ihr endete mit Vorwürfen"
  },
  AvgDialog_45420_Content_24 = {
    Text = "Ein Wesen, das bereits durch Erosion aufgelöst wurde, ohne einen Hauch von **Silber**-Kontakt zu hinterlassen. Du kannst ihre Existenz überhaupt nicht berühren."
  },
  AvgDialog_45420_Content_25 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45420_Content_26 = {
    Text = "Warum, hat die Reise dich zu stolz gemacht?"
  },
  AvgDialog_45420_Content_27 = {
    Text = "Oder werde ich ohne dich zu einem weinerlichen, nutzlosen Kerl?"
  },
  AvgDialog_45420_Content_28 = {
    Text = "Egal was, selbst nachdem du all deine Gefährten verloren hast, hast du es dennoch alleine hierher geschafft. Solche Ausdauer ist immer lobenswert."
  },
  AvgDialog_45420_Content_29 = {
    Text = "Also, lass mich meine Kraft ihr und dir ebenfalls leihen."
  },
  AvgDialog_45420_Content_3 = {
    Text = "Da du darauf bestehst"
  },
  AvgDialog_45420_Content_30 = {
    Text = "Die Stille der Wüste wird von einem plötzlichen Windstoß durchbrochen, der Himmel verdunkelt sich schnell, als ob alles Licht von der kommenden Wut verschlungen wird"
  },
  AvgDialog_45420_Content_31 = {
    Text = "Der Sandsturm tobt wie ein wütendes Ungeheuer, wirbelt Tonnen von Sand auf, verdunkelt den Himmel und verschlingt Sonne und Himmel"
  },
  AvgDialog_45420_Content_32 = {
    Text = "In dieser tobenden Naturgewalt erscheint eine riesige Gestalt, die im Sandsturm flimmert"
  },
  AvgDialog_45420_Content_33 = {Text = "Sturmwand"},
  AvgDialog_45420_Content_34 = {
    Text = "Die Sturmwand wurde durch meine Macht herbeigerufen"
  },
  AvgDialog_45420_Content_35 = {
    Text = "Bist du... Thais...?"
  },
  AvgDialog_45420_Content_36 = {
    Text = "Es scheint unendliche Kraft zu besitzen, tanzt und verzerrt sich mit dem wirbelnden Sand, wie ein uraltes Wüstenmonster, das in einem Sandsturm nach Beute sucht"
  },
  AvgDialog_45420_Content_37 = {
    Text = "Seine Gestalt ist riesig und furchterregend, ein gewaltiger Kopf, scharfe Klauen und schwere Hufe, alles im wirbelnden Staub zu erkennen"
  },
  AvgDialog_45420_Content_38 = {
    Text = "So zu nennen, ist nicht falsch"
  },
  AvgDialog_45420_Content_39 = {
    Text = "Aber ich bin nicht die Königin, die du erwartest"
  },
  AvgDialog_45420_Content_4 = {
    Text = "Wachen, lasst den Gesandten keinen Schaden nehmen"
  },
  AvgDialog_45420_Content_40 = {
    Text = "Wenn du meine Macht ausleihen möchtest, rufe meinen heiligen Namen laut.\nIch bin die Verkörperung des Verlangens—"
  },
  AvgDialog_45420_Content_41 = {
    Text = "Der riesige, seltsame Schatten verblasst allmählich, und die Gestalt, die du nicht erreichen konntest, tritt aus dem heulenden Sandsturm hervor"
  },
  AvgDialog_45420_Content_42 = {
    Text = "Der Kieselsturm tobte um sie herum, doch er konnte ihren Schritt nicht erschüttern"
  },
  AvgDialog_45420_Content_44 = {
    Text = "Die Königin! Die Königin ist zurückgekehrt!"
  },
  AvgDialog_45420_Content_45 = {
    Text = "Königin, die Augen der Königin sind immer auf uns gerichtet!"
  },
  AvgDialog_45420_Content_46 = {
    Text = "Ihr Blick war fest auf Yalan gerichtet, beobachtete die Vergangenheit und Zukunft, die durch seine Blutlinie strömten."
  },
  AvgDialog_45420_Content_47 = {
    Text = "Lady Thais..."
  },
  AvgDialog_45420_Content_48 = {
    Text = "Höret, alle Aran-Geschlechter! Die alte Prophezeiung ist wahr geworden; der Mutterbaum ist wieder erschienen, um die Verstorbenen zu krönen!"
  },
  AvgDialog_45420_Content_49 = {
    Text = "Die Königin kehrt im Sand zurück, um sich erneut auf den Thron zu setzen!"
  },
  AvgDialog_45420_Content_5 = {Text = "Ja!"},
  AvgDialog_45420_Content_50 = {
    Text = "An die einzige Königin von Aran, Lady Thais—"
  },
  AvgDialog_45420_Content_51 = {
    Text = "Bringt eure Treue und euren Willen dar!"
  },
  AvgDialog_45420_Content_6 = {
    Text = "Juliette kam näher und flüsterte dir nur einen Arm entfernt zu"
  },
  AvgDialog_45420_Content_7 = {
    Text = "Die Rückkehr zum heiligen Fluss ist das Schicksal der Aram, ich habe ihnen nur ein wenig beschleunigt"
  },
  AvgDialog_45420_Content_8 = {
    Text = "Wenn sein Blick ganz Kadath erfasst, werden sie mit dem heiligen Fluss in die neue Welt eintreten"
  },
  AvgDialog_45420_Content_9 = {
    Text = "Das ist dein Wille, nicht wahr?"
  },
  AvgDialog_45421_Content_1 = {
    Text = "Wer ist da?!"
  },
  AvgDialog_45421_Content_2 = {
    Text = "Oh nein, wir sind vorne in einen Hinterhalt geraten und werden von hinten verfolgt!"
  },
  AvgDialog_45421_Content_3 = {
    Text = "Wir können nicht zulassen, dass diese Arlan-Soldaten uns finden."
  },
  AvgDialog_45421_Content_4 = {
    Text = "Es scheint, dass wir keine andere Wahl haben, als tiefer einzutauchen, oder?"
  },
  AvgDialog_45422_Content_1 = {
    Text = "Es ist etwas problematisch. Wir wissen nicht, wo das Skelett ist.\nDie Fabrik hat komplexe Gänge und viele Kompartimente. Alle zu durchsuchen könnte ewig dauern."
  },
  AvgDialog_45422_Content_10 = {
    Text = "Du bleibst verborgen und hilfst; zeige euch nicht. Ich werde sie verbunden halten!"
  },
  AvgDialog_45422_Content_2 = {
    Text = "Ich habe einen kleinen Trick."
  },
  AvgDialog_45422_Content_3 = {
    Text = "Lass uns einen Arlan-Wächter finden, ihn fesseln und verhören."
  },
  AvgDialog_45422_Content_4 = {
    Text = "Was jetzt? Wirst du ihn im gelben Sand begraben, um ihn zum Schweigen zu bringen, oder ihn gehen lassen und uns zu Arlans meistgesuchten machen?"
  },
  AvgDialog_45422_Content_5 = {
    Text = "Ups, daran habe ich nicht gedacht. Mein Fehler."
  },
  AvgDialog_45422_Content_6 = {
    Text = "Sein Fehler wird leicht abgetan, er wirkt unbesorgt.\nAus seinem mehrdeutigen Tonfall spürst du, dass er etwas zurückhält."
  },
  AvgDialog_45422_Content_7 = {
    Text = "Gibt es einen Weg, um nach Hinweisen zu fragen, ohne unsere Identität preiszugeben?"
  },
  AvgDialog_45422_Content_8 = {
    Text = "Ist das nicht einfach?"
  },
  AvgDialog_45422_Content_9 = {
    Text = "Ryker entfernte das Duftpflaster von seinem Handschuh. Seine Pupillen glühten grün und flackerten im Dunkeln."
  },
  AvgDialog_45423_Content_1 = {
    Text = "Nein, unmöglich! Die Sturmwand hat kein Ende!"
  },
  AvgDialog_45423_Content_2 = {
    Text = "Wir können nicht in die Sturmwand eintreten. Die Königin hat uns verlassen!"
  },
  AvgDialog_45423_Content_3 = {
    Text = "Die Königin hat uns lange verlassen!"
  },
  AvgDialog_45423_Content_4 = {
    Text = "Schreie und Weinen erfüllten die Luft."
  },
  AvgDialog_45424_Content_1 = {
    Text = "Königin, möge die Königin uns beschützen!"
  },
  AvgDialog_45424_Content_2 = {
    Text = "Möge die Königin Arlan schützen!"
  },
  AvgDialog_45424_Content_3 = {
    Text = "<Small:Thais ist eindeutig nicht hier...>"
  },
  AvgDialog_45424_Content_4 = {
    Text = "Nubien sammelt immer mehr!"
  },
  AvgDialog_45424_Content_5 = {
    Text = "Keine Wahl, wir müssen mit diesen Verrückten weitermachen!"
  },
  AvgDialog_45425_Content_1 = {Text = "Wette"},
  AvgDialog_45425_Content_10 = {
    Text = "Du öffnest deine Augen. Abgesehen vom hellen Tageslicht draußen im Zelt bleibt alles so, wie es war, bevor du eingeschlafen bist."
  },
  AvgDialog_45425_Content_11 = {
    Text = [[
Verstanden.
Die Antwort ist Motivation.]]
  },
  AvgDialog_45425_Content_12 = {
    Text = "Wenn all dies von der Tempellicht Kirche getan wurde, gäbe es keinen Grund für sie, die Lampe im Körper von Nubien zu lassen."
  },
  AvgDialog_45425_Content_13 = {
    Text = "Basierend auf allem, was wir unterwegs gesehen haben, glaube ich, dass der Täter nur sein kann—"
  },
  AvgDialog_45425_Content_14 = {
    Text = "Wolfsklauen rissen durch den Vorhang und enthüllten einen heimlichen Magier sowie das endlose Meer aus Sand durch den Riss im Zelt."
  },
  AvgDialog_45425_Content_15 = {
    Text = "Die beiden Mitglieder der Bildhauervereinigung."
  },
  AvgDialog_45425_Content_16 = {
    Text = "Ups, wurde ich entdeckt? Ich wollte noch ein wenig länger zuhören."
  },
  AvgDialog_45425_Content_17 = {
    Text = "Ihr Ton ist leicht und zeigt keine Anzeichen von Spannung aufgrund des gescheiterten Lauschens."
  },
  AvgDialog_45425_Content_18 = {
    Text = "Casiah, du—"
  },
  AvgDialog_45425_Content_19 = {
    Text = "Gerade um klarzustellen, Beschwerden haben ihre Ursprünge und Schulden haben ihre Schuldner. Ich habe niemanden getötet, also komm nicht nach mir."
  },
  AvgDialog_45425_Content_2 = {
    Text = "Du kehrst erschöpft zum Zelt zurück. Ryker sitzt still in einer Ecke, sein Kinn ruht auf einer Hand, vertieft in Gedanken."
  },
  AvgDialog_45425_Content_20 = {
    Text = "Meine Mission ist einfach: diesen einen zu eskortieren—"
  },
  AvgDialog_45425_Content_21 = {
    Text = "Sie zeigte auf dich."
  },
  AvgDialog_45425_Content_22 = {
    Text = "Verpackt als Geschenk für eine bestimmte wichtige Person."
  },
  AvgDialog_45425_Content_3 = {
    Text = "Eine große Schlacht könnte morgen kommen. Warum ruhst du dich nicht aus?"
  },
  AvgDialog_45425_Content_4 = {
    Text = "Du gehst zuerst schlafen.\nMein Instinkt sagt mir... diese \"Tatort\" enthält noch Rätsel."
  },
  AvgDialog_45425_Content_5 = {
    Text = "Du warst so erschöpft, dass du dich hast hastig gewaschen und ausgeruht."
  },
  AvgDialog_45425_Content_6 = {
    Text = "An einer chaotischen Nacht tauchen unzählige vertraute, aber dennoch seltsame Gesichter in deinem Gedächtnis auf und rufen nacheinander deinen Namen—verschwommen, heiser und düster."
  },
  AvgDialog_45425_Content_7 = {
    Text = "Ich möchte überleben..."
  },
  AvgDialog_45425_Content_8 = {
    Text = "<RedBig:Ich will überleben...>"
  },
  AvgDialog_45425_Content_9 = {Text = "Genug!"},
  AvgDialog_45426_Content_1 = {
    Text = "Abschiedskuss"
  },
  AvgDialog_45426_Content_10 = {
    Text = "Du holst tief Luft und willst gerade ins Zelt zurück, als Thais dir hinter dem Zelt zuwinkt"
  },
  AvgDialog_45426_Content_100 = {
    Text = "Aber Yalans Blutlinie verlässt sich zu sehr auf die Kraft des Mutterbaums."
  },
  AvgDialog_45426_Content_101 = {
    Text = "Diese Abhängigkeit ist wie ein zerbrechlicher Sandturm, scheinbar stabil, aber eine Flutwelle würde ihn vollständig zerstören"
  },
  AvgDialog_45426_Content_102 = {
    Text = "Selbst die kleinste, schwächste Hoffnung darf ich ihnen nicht leichtfertig nehmen"
  },
  AvgDialog_45426_Content_103 = {
    Text = "Ich verstehe nicht mehr"
  },
  AvgDialog_45426_Content_104 = {
    Text = "Um den Abschied weniger traurig zu machen, das Wiedersehen wertvoller... du musst es nicht verstehen"
  },
  AvgDialog_45426_Content_105 = {
    Text = "Aber du wirst mit ihnen zusammen das Ende dieser Reise erreichen"
  },
  AvgDialog_45426_Content_106 = {
    Text = "Du bist sprachlos"
  },
  AvgDialog_45426_Content_107 = {
    Text = "Dann... erinnere dich bitte daran, meinen Namen zu rufen"
  },
  AvgDialog_45426_Content_108 = {
    Text = "Sie gab dir einen sanften Kuss auf die Stirn"
  },
  AvgDialog_45426_Content_109 = {
    Text = "Du warst kurz abgelenkt, sie machte ein paar Schritte, du strecktest die Hand aus, aber konntest sie nicht erreichen"
  },
  AvgDialog_45426_Content_11 = {
    Text = "Morgen ist das Wiederbelebungsritual des Mutterbaums.\nDie Königin ruft mich jetzt... Was will sie?"
  },
  AvgDialog_45426_Content_110 = {
    Text = "Du siehst ihr nach, wie sie immer kleiner wird und schließlich im Mondlicht verschwindet"
  },
  AvgDialog_45426_Content_12 = {
    Text = "Als du sprachst, wurde dir klar, dass dein Ton unfreundlich war"
  },
  AvgDialog_45426_Content_13 = {
    Text = [[
Ich... habe es gesehen.
Es tut mir leid wegen deinem Freund]]
  },
  AvgDialog_45426_Content_14 = {
    Text = "Eine unvermeidliche Stille liegt zwischen euch."
  },
  AvgDialog_45426_Content_15 = {
    Text = "Das hat nichts mit Alan zu tun."
  },
  AvgDialog_45426_Content_16 = {
    Text = "Das ist nicht Thais' Fehler, sagst du dir innerlich, aber die Worte, die herausplatzen, sind wie ein vorsichtiger Igel in den Dünen"
  },
  AvgDialog_45426_Content_17 = {
    Text = "Ritual zur Wiederbelebung des Mutterbaums... Du hast auch Vorbereitungen zu treffen, oder?"
  },
  AvgDialog_45426_Content_18 = {
    Text = "Du versuchst, es zu retten, aber deine Worte klingen immer noch kalt und abweisend"
  },
  AvgDialog_45426_Content_19 = {
    Text = "Wo denkst du, wird der Aran-Stamm nach der Wiedergeburt des Mutterbaums hingehen?"
  },
  AvgDialog_45426_Content_2 = {
    Text = "Auf dieser Reise hast du viele Abschiede erlebt.\nAber kein Tod war so erstickend beiläufig"
  },
  AvgDialog_45426_Content_20 = {
    Text = "Du schweigst"
  },
  AvgDialog_45426_Content_21 = {
    Text = "Ich weiß, warum Mythag nach Remouahe kam, und ich weiß, warum du noch nicht gehandelt hast."
  },
  AvgDialog_45426_Content_22 = {
    Text = "Ich bin dir sehr dankbar, dass du Aran eine Chance gegeben hast."
  },
  AvgDialog_45426_Content_23 = {
    Text = "Aber diese Chance gibt es nicht mehr"
  },
  AvgDialog_45426_Content_24 = {
    Text = "Thais, weißt du, dass der Mutterbaum geschmolzen und kontaminiert wurde?"
  },
  AvgDialog_45426_Content_25 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45426_Content_26 = {
    Text = "Ich weiß, ich... wusste es die ganze Zeit."
  },
  AvgDialog_45426_Content_27 = {
    Text = "Dann solltest du wissen, dass Missaga die Ausbreitung der Korrosion nicht zulassen wird"
  },
  AvgDialog_45426_Content_28 = {
    Text = [[
Ich werde die Geburt des Mutterbaums aufhalten.
Thais, wir sind jetzt Feinde]]
  },
  AvgDialog_45426_Content_29 = {
    Text = "Der einst frische Wüstenwind wurde plötzlich dick und klebrig, und der Staub kratzte in deinem Hals, was leichte Schmerzen verursachte"
  },
  AvgDialog_45426_Content_3 = {
    Text = "Zumal das William ist—\nDie Legende von Missaga, dein Wegweiser auf dem Weg des Ermittlers"
  },
  AvgDialog_45426_Content_30 = {
    Text = "Zu deiner Überraschung weicht Thais nicht zurück, sondern kommt näher und umarmt dich"
  },
  AvgDialog_45426_Content_31 = {
    Text = "Braves Kind, ich verstehe deine Gedanken"
  },
  AvgDialog_45426_Content_32 = {
    Text = "Ich meine es nicht böse, und ich werde nicht gegen die Interessen der Alander handeln."
  },
  AvgDialog_45426_Content_33 = {
    Text = "Aber den Aramern blieben keine Optionen. Vor vielen Jahren war die göttliche Kraft der Königin bereits erschöpft, und sie konnten nicht einmal mehr den Mutterbaum beschützen"
  },
  AvgDialog_45426_Content_34 = {
    Text = "Nur indem wir die Leylinienkraft von Lemwash nutzen, können wir den Standort des Mutterbaums mit einer Sturmwand verbergen."
  },
  AvgDialog_45426_Content_35 = {
    Text = "Du meinst... die Sturmwand wurde durch die Macht der Königin beschworen?"
  },
  AvgDialog_45426_Content_36 = {
    Text = "Ja. Die Sturmwand... wird falsche Boten abweisen"
  },
  AvgDialog_45426_Content_37 = {
    Text = "Aber jedes Mal, wenn ein Ritual abgehalten wird, sterben viele Aram!"
  },
  AvgDialog_45426_Content_38 = {
    Text = "Solange die Fortpflanzungskraft besteht, wird das Yaran-Volk nicht aussterben."
  },
  AvgDialog_45426_Content_39 = {
    Text = "Also lässt du sie diese verfluchten Rituale durchführen und immer wieder in der Sturmwand untergehen?"
  },
  AvgDialog_45426_Content_4 = {
    Text = "Wer könnte einen legendären Ermittler aus nächster Nähe lautlos töten?"
  },
  AvgDialog_45426_Content_40 = {
    Text = "Das ist das Schicksal der Aram. Wir sind hier geboren, wir sind hier aufgewachsen"
  },
  AvgDialog_45426_Content_41 = {
    Text = "Unzählige haben für deinen kranken Glauben ihr Leben gelassen!"
  },
  AvgDialog_45426_Content_42 = {
    Text = "Jetzt, nicht nur dein Volk, sondern auch Senior William"
  },
  AvgDialog_45426_Content_43 = {
    Text = "Dein letzter Ton ist mit einem leichten Schluchzen durchzogen; du erkennst deine eigene Stimme kaum"
  },
  AvgDialog_45426_Content_44 = {
    Text = "Sag mir, Thais, du meinst das nicht ernst, oder?"
  },
  AvgDialog_45426_Content_45 = {
    Text = "Thais antwortete nicht auf deine Frage"
  },
  AvgDialog_45426_Content_46 = {
    Text = "Sie zog nur ihre Arme enger um sich"
  },
  AvgDialog_45426_Content_47 = {
    Text = "Ich weiß, du bist müde und wütend"
  },
  AvgDialog_45426_Content_48 = {
    Text = "Du bist wütend auf mich, verstehst mich nicht.\nDoch auch ich habe meine Gründe"
  },
  AvgDialog_45426_Content_49 = {
    Text = "Ich erzähle dir eine Geschichte, eine sehr lange Geschichte"
  },
  AvgDialog_45426_Content_5 = {
    Text = "Du taumelst kraftlos zurück und stößt gegen eine große Gestalt"
  },
  AvgDialog_45426_Content_50 = {
    Text = "Vor vielen, vielen Jahren, vor mehreren tausend Jahren, als die Überschwemmungen passierten, gab es eine Zivilisation, die die Göttin namens Mutterbaum verehrte"
  },
  AvgDialog_45426_Content_51 = {
    Text = "Doch der Wille des Mutterbaums konnte das Imperium nicht festigen, also schmiedeten sie einen Plan"
  },
  AvgDialog_45426_Content_52 = {
    Text = "Sie wählten viele Mädchen aus, zwangen sie, den roten Saft des Mutterbaums zu trinken und darin zu baden, bis sie mit dem Baum verschmolzen"
  },
  AvgDialog_45426_Content_53 = {
    Text = "Seitdem repräsentiert das puppenhafte Mädchen den Willen des Baumes"
  },
  AvgDialog_45426_Content_54 = {
    Text = "Doch niemand hört auf sie oder gehorcht ihren Worten. Das Mädchen hat keine Stimme und keinen eigenen Willen; es wiederholt lediglich die Befehle, die der König von Ninive es zu rezitieren zwang."
  },
  AvgDialog_45426_Content_55 = {
    Text = "Das Jahr, in dem sie sich wehrte, war das Mädchen fünfzehn"
  },
  AvgDialog_45426_Content_56 = {
    Text = "Warum? Warum ihn töten? Er ist doch der Vater von Ameyet!"
  },
  AvgDialog_45426_Content_57 = {
    Text = "Er hat das Tabu gebrochen, Thais. Er ist auf dem Schlachtfeld geflohen"
  },
  AvgDialog_45426_Content_58 = {
    Text = "Die Schlacht war völlig verloren, nur er überlebte. Er konnte unmöglich allein so viele Feinde bekämpfen!"
  },
  AvgDialog_45426_Content_59 = {
    Text = "Du bist noch zu jung, um die Dinge des Krieges zu verstehen, Thais"
  },
  AvgDialog_45426_Content_6 = {
    Text = "Ich verstehe deine Sorgen, aber jetzt ist nicht der Zeitpunkt, Schwäche zu zeigen"
  },
  AvgDialog_45426_Content_60 = {
    Text = "Er sollte mutig vorwärts stürmen und dann ehrenvoll sterben"
  },
  AvgDialog_45426_Content_61 = {
    Text = "Ist es nicht gut, wenn nur eine Person überlebt? Wenn nur eine Person überlebt... kann Ameiyt ein Krieger sein, Ameiyts Bruder wird ein Krieger sein, und sogar Ameiyts zukünftige Kinder"
  },
  AvgDialog_45426_Content_62 = {
    Text = "Es bringt nichts mehr, weiter zu reden"
  },
  AvgDialog_45426_Content_63 = {
    Text = "Der Wille des Mutterbaums, Sünder sollen von Insekten zerfressen werden"
  },
  AvgDialog_45426_Content_64 = {
    Text = "Ich habe es nicht gesagt!"
  },
  AvgDialog_45426_Content_65 = {
    Text = "Der Wille des Mutterbaums, Sünder sollen von Insekten zerfressen werden"
  },
  AvgDialog_45426_Content_66 = {
    Text = "Ich habe es nicht gesagt!"
  },
  AvgDialog_45426_Content_67 = {
    Text = "Der Wille des Mutterbaums..."
  },
  AvgDialog_45426_Content_68 = {
    Text = "Nein, tu das nicht...!"
  },
  AvgDialog_45426_Content_69 = {
    Text = "Sünder werden die Strafe erleiden, von Würmern verschlungen zu werden."
  },
  AvgDialog_45426_Content_7 = {
    Text = "Er... hat uns die entscheidenden Informationen hinterlassen"
  },
  AvgDialog_45426_Content_70 = {
    Text = "Das verzweifelte und laute Weinen des Mädchens hörte niemand"
  },
  AvgDialog_45426_Content_71 = {
    Text = "Du, wer bist du?"
  },
  AvgDialog_45426_Content_72 = {
    Text = "Braves Kind, sei leise, hör auf mich und komm schnell mit mir"
  },
  AvgDialog_45426_Content_73 = {
    Text = "Du bist nicht das erste Mädchen, das als Puppe des Baumes benutzt wird. Jedes Mal, wenn ein Mädchen sich gegen ihren Willen wehrt, opfern sie das Mädchen dem heiligen Fluss"
  },
  AvgDialog_45426_Content_74 = {
    Text = "Ich wurde von der Milch des Mutterbaums genährt, ich bin unsterblich!"
  },
  AvgDialog_45426_Content_75 = {
    Text = "Dummes Kind, sie haben dich belogen. Jeder, der in den Fluss springt, wird ertrinken"
  },
  AvgDialog_45426_Content_76 = {
    Text = "Ich werde nicht."
  },
  AvgDialog_45426_Content_77 = {
    Text = "Wer bist du überhaupt? Ich habe dich noch nie zuvor gesehen."
  },
  AvgDialog_45426_Content_78 = {
    Text = "Ich kümmere mich um deinen Garten und gehe vor Sonnenaufgang, deshalb hast du mich nie gesehen"
  },
  AvgDialog_45426_Content_79 = {
    Text = "Aber du kennst meinen Enkel... Sein Name ist Ameyet"
  },
  AvgDialog_45426_Content_8 = {
    Text = "Hinter Nubien liegt die Lichtkirche des Tempels.\nDie Narzisse hatte recht; das Ritual zu stoppen scheint unerlässlich."
  },
  AvgDialog_45426_Content_80 = {
    Text = "Ist das Mädchen entkommen?"
  },
  AvgDialog_45426_Content_81 = {Text = "Nein."},
  AvgDialog_45426_Content_82 = {
    Text = "Das Mädchen erkannte in diesem Moment viele Dinge."
  },
  AvgDialog_45426_Content_83 = {
    Text = "Der Garten, der beschmutzt wurde, wird sich nicht selbst reinigen."
  },
  AvgDialog_45426_Content_84 = {
    Text = "Einige Dinge scheinen zu existieren, sind aber noch nie gesehen worden."
  },
  AvgDialog_45426_Content_85 = {
    Text = "Es war so schmerzhaft, keinen Laut von sich geben zu können..."
  },
  AvgDialog_45426_Content_86 = {
    Text = "......Am Tag des Opferrituals sprang sie freiwillig in den heiligen Fluss."
  },
  AvgDialog_45426_Content_87 = {
    Text = "In diesem Moment resonierten das Mädchen und der Baum in der Ferne"
  },
  AvgDialog_45426_Content_88 = {
    Text = "Dann fragte der Wille des Baumes sie:"
  },
  AvgDialog_45426_Content_89 = {
    Text = "Bist du bereit, zum Träger des Baumes zu werden und sein Fleisch und seine Seele zu gebären?"
  },
  AvgDialog_45426_Content_9 = {
    Text = "Am weiten Himmel funkelten die Sterne, und der Wüstenwind der Nacht ließ deinen Atem allmählich wieder normal werden"
  },
  AvgDialog_45426_Content_90 = {
    Text = "Durch die wundersame Resonanz der Seele kann das Mädchen die Stimmen der Bäume hören.\nAn diesem Abend erfuhr sie das Wissen über <Red:Der schwarze Untergang>"
  },
  AvgDialog_45426_Content_91 = {
    Text = "Schwarzer Untergang... bedeutet das Erosion?"
  },
  AvgDialog_45426_Content_92 = {
    Text = "Das Mädchen kehrt zum Baum zurück, gehorcht aber nicht mehr dem König.\nNein... das Volk folgt nur dem Willen des Baumes"
  },
  AvgDialog_45426_Content_93 = {
    Text = "Das Mädchen ist der Baum, der Baum ist das Mädchen. Sie sorgt sich mehr um das Überleben ihrer Art als um ihr eigenes"
  },
  AvgDialog_45426_Content_94 = {
    Text = "Als das Imperium fiel, führte sie eine Gruppe tief in die Wüste, in die unbewohnten Stürme, um dem Massaker zu entkommen und die letzte Blutlinie zu bewahren"
  },
  AvgDialog_45426_Content_95 = {
    Text = "Ist das... der nomadische Stamm, Yalan?"
  },
  AvgDialog_45426_Content_96 = {
    Text = "Vor langer, langer Zeit verschwand das Mädchen wieder"
  },
  AvgDialog_45426_Content_97 = {
    Text = "Oder niemand hörte ihre Stimme, niemand sprach mehr ihren Namen"
  },
  AvgDialog_45426_Content_98 = {
    Text = "Aber alle folgen ihrem Willen und vermehren sich verzweifelt, um dem Untergang zu entkommen"
  },
  AvgDialog_45426_Content_99 = {
    Text = "Nur um die Saat des „Füllhorns\" für den Zeitpunkt der Apokalypse zu bewahren"
  },
  AvgDialog_45427_Content_1 = {Text = "Tanzen"},
  AvgDialog_45427_Content_10 = {
    Text = "Kinder werden ihren eigenen Weg finden."
  },
  AvgDialog_45427_Content_100 = {
    Text = "Du folgst dem Blick von Thais und siehst Ramona auf dich zulaufen, während Ryker ihr schnell, aber sicher folgt, ohne an Anmut und Eleganz einzubüßen"
  },
  AvgDialog_45427_Content_101 = {
    Text = "Vergiss nicht, dass diese Nacht nur unser Geheimnis gehört"
  },
  AvgDialog_45427_Content_102 = {
    Text = "Beim erneuten Hinsehen war Thais' Gestalt verschwunden, nur der Wind pfiff durch die Wüste"
  },
  AvgDialog_45427_Content_103 = {
    Text = "Vor dir im Sand drang ein dunkler Auflösungs-Schleim in den Treibsand ein und verband sich mit der Erde"
  },
  AvgDialog_45427_Content_11 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45427_Content_12 = {
    Text = "Du öffnest schläfrig deine Augen zu einem weiten, klaren und strahlend schönen Sternenhimmel."
  },
  AvgDialog_45427_Content_13 = {
    Text = "Wie bin ich... eingeschlafen?"
  },
  AvgDialog_45427_Content_14 = {
    Text = "Nach langer Wanderung in der Wüste ist Müdigkeit ganz normal"
  },
  AvgDialog_45427_Content_15 = {
    Text = "Ich habe noch viele Fragen"
  },
  AvgDialog_45427_Content_16 = {
    Text = "Der lange Traum scheint dich von der angespannten Reise zu lösen, eine Frage nach der anderen taucht in deinem Kopf auf"
  },
  AvgDialog_45427_Content_17 = {
    Text = "Warum verwandelt sich das Wasser in Ramonas Wassersack in D-Schleim?"
  },
  AvgDialog_45427_Content_18 = {
    Text = "Wer verbreitet die Nubier?"
  },
  AvgDialog_45427_Content_19 = {
    Text = "Was verbirgt sich im Inneren der Sturmwand?"
  },
  AvgDialog_45427_Content_2 = {
    Text = "▼▼Im Chaos, niemand kennt das Ende.\nWas geschehen wird, liegt in meinen Worten, aber die Menschen haben ihr Gehör und ihre Sicht verloren,\nNur die Schweigsamen bedecken die Erde"
  },
  AvgDialog_45427_Content_20 = {
    Text = "Was hat der geheimnisvolle Bote Juliette vor?"
  },
  AvgDialog_45427_Content_21 = {
    Text = "Worum geht es genau in Arlans Ritual?"
  },
  AvgDialog_45427_Content_22 = {
    Text = "Und ist der Thais, der hier vor uns steht, wirklich vertrauenswürdig?"
  },
  AvgDialog_45427_Content_23 = {
    Text = "Seit meiner Ankunft in Lemwahi haben ungewöhnliche Vorfälle nicht nachgelassen. Ein Geheimnis nach dem anderen lässt dich atemlos zurück."
  },
  AvgDialog_45427_Content_24 = {
    Text = "Du musst ruhig bleiben und nachdenken"
  },
  AvgDialog_45427_Content_25 = {
    Text = "Denk nicht mehr darüber nach, du bist müde, du brauchst Ruhe"
  },
  AvgDialog_45427_Content_26 = {
    Text = "Als du dich umdrehst, scheint nur der Vollmond auf Thais' schimmerndem Gesicht und es vermittelt einen durchsichtigen Eindruck"
  },
  AvgDialog_45427_Content_27 = {
    Text = "Auf der anderen Seite der Sturmwand... werden alle deine Fragen beantwortet"
  },
  AvgDialog_45427_Content_28 = {
    Text = "Auf der anderen Seite der Sturmwand"
  },
  AvgDialog_45427_Content_29 = {
    Text = "Juliette hat das genauso gesagt. Musst du wirklich den Wünschen jener im Hintergrund folgen, um in den Sturm zu gelangen?"
  },
  AvgDialog_45427_Content_3 = {
    Text = "Tawils Überwachungsdaten stabilisieren sich allmählich."
  },
  AvgDialog_45427_Content_30 = {
    Text = "Oder treibt eine unsichtbare Macht alle wie Pilger in den Sturm?"
  },
  AvgDialog_45427_Content_31 = {
    Text = "In deinem Gedankensee wächst der Zweifel und die Angst wie Samen"
  },
  AvgDialog_45427_Content_32 = {
    Text = "Kann dein Herz nie zur Ruhe kommen?"
  },
  AvgDialog_45427_Content_33 = {
    Text = "Schließe deine Augen."
  },
  AvgDialog_45427_Content_34 = {
    Text = "Thais ist nur einen Wimpernschlag von deinem Atem entfernt"
  },
  AvgDialog_45427_Content_35 = {
    Text = "Schließe deine Augen."
  },
  AvgDialog_45427_Content_36 = {
    Text = "Augen nicht schließen"
  },
  AvgDialog_45427_Content_37 = {
    Text = "Klarer Blick... nicht getrübt von der Reise"
  },
  AvgDialog_45427_Content_38 = {
    Text = "Thais setzte ihren Zeigefinger auf deine Lippen."
  },
  AvgDialog_45427_Content_39 = {
    Text = "Ihr Gesicht ist dir ganz nah, der Mondschein verleiht ihrer Haut einen sanften Glanz"
  },
  AvgDialog_45427_Content_4 = {
    Text = "Du hast in dieser Zeit hart gearbeitet."
  },
  AvgDialog_45427_Content_40 = {
    Text = "Du spürst einen nahen Atem, sanft und warm"
  },
  AvgDialog_45427_Content_41 = {
    Text = "Was für ein nostalgischer Duft"
  },
  AvgDialog_45427_Content_42 = {
    Text = "Wie lange ist es her, dass wir uns so nahe waren?"
  },
  AvgDialog_45427_Content_43 = {
    Text = "Ein kühles Gefühl auf den Lippen"
  },
  AvgDialog_45427_Content_44 = {
    Text = "Du öffnest die Augen, Thais’ Zeigefinger drückt gegen deine Lippen.\nIhr Gesicht ist dir so nah, das Mondlicht verleiht ihrem Haut einen sanften Glanz"
  },
  AvgDialog_45427_Content_45 = {
    Text = "Weißt du? In deinen Augen sehe ich Clades, uralte Glut und den Atem des Universums."
  },
  AvgDialog_45427_Content_46 = {
    Text = [[
Deine Reise war lang und beschwerlich, nicht wahr?
Aber dein Blick bleibt so fest und klar wie eh und je.]]
  },
  AvgDialog_45427_Content_47 = {
    Text = "Die Sterne können dich nicht ändern, und die Sandsee vielleicht auch nicht"
  },
  AvgDialog_45427_Content_48 = {
    Text = "Ich verstehe nicht, was du meinst"
  },
  AvgDialog_45427_Content_49 = {
    Text = "Du musst es jetzt noch nicht verstehen"
  },
  AvgDialog_45427_Content_5 = {
    Text = "Bleib wachsam.\nIn über dreihundert Jahren waren die Anomalien im Schwarzen Teich nie so häufig wie in diesem Jahr."
  },
  AvgDialog_45427_Content_50 = {
    Text = "Thais stand auf und schlenderte zu den Dünen hinunter"
  },
  AvgDialog_45427_Content_51 = {
    Text = "Unter diesem Sternenhimmel nur zu sitzen, ist zu unromantisch"
  },
  AvgDialog_45427_Content_52 = {
    Text = "Der Wind hob ihren durchsichtigen Schleier, sie schwebte über den weichen Sand"
  },
  AvgDialog_45427_Content_53 = {
    Text = "Lass mich dir diesen Tanz von Yalan präsentieren."
  },
  AvgDialog_45427_Content_54 = {
    Text = "Die Glocke läutet, sie hebt einen Arm und beginnt zu tanzen"
  },
  AvgDialog_45427_Content_55 = {
    Text = "Sie beugt sich, streckt sich, manchmal wild, manchmal zurückhaltend"
  },
  AvgDialog_45427_Content_56 = {
    Text = "Ich habe immer auf jemanden gewartet"
  },
  AvgDialog_45427_Content_57 = {
    Text = "Ihre Gestalt ist geschmeidig, ihr Tanz gleicht einer Schlange"
  },
  AvgDialog_45427_Content_58 = {
    Text = "Ein Beobachter, der Yalan in die „Zukunft“ führen kann."
  },
  AvgDialog_45427_Content_59 = {
    Text = "Sie drehte und bewegte sich, selbst ihre Nachbilder strahlten angeborene Eleganz und unglaubliche Flexibilität aus"
  },
  AvgDialog_45427_Content_6 = {
    Text = "Mach dir nicht zu viele Sorgen; das musste irgendwann passieren.\nFür \"Ihn\" ist Verstecken in der Vergangenheit oder der Zukunft keine tragfähige langfristige Lösung."
  },
  AvgDialog_45427_Content_60 = {
    Text = "Ist Elva nicht diese Person?"
  },
  AvgDialog_45427_Content_61 = {
    Text = "Thais drehte sich um, senkte den Blick und die anmutige Blume streifte über ihre seufzende Lippen"
  },
  AvgDialog_45427_Content_62 = {
    Text = "Elva ist ein gutes Kind, aber sie kann noch keinen neuen Weg erschließen"
  },
  AvgDialog_45427_Content_63 = {
    Text = "Was ist mit Juliette? Ist sie nicht die Botschafterin eines fremden Landes?"
  },
  AvgDialog_45427_Content_64 = {
    Text = "Hast du gerade gesagt, dass der Weg, den Juliette für die Aran suchte, aus der Wüste herausführt?"
  },
  AvgDialog_45427_Content_65 = {
    Text = "Thais streckte die Arme aus und blickte mit ihrem wandernden Blick zum Mond an ihren Fingerspitzen, als wollte sie die unsichtbaren Vögel verabschieden"
  },
  AvgDialog_45427_Content_66 = {
    Text = "Diejenigen, die gehen konnten, sind bereits gegangen. Yalan hat niemanden gebunden. Ob es eine Bindung an die Heimat oder eine Anpassung an das Leben in der Wüste ist, diejenigen, die geblieben sind, können hier nur überleben."
  },
  AvgDialog_45427_Content_67 = {
    Text = "Zumal das nicht die Antwort ist, die ich erwartet habe"
  },
  AvgDialog_45427_Content_68 = {
    Text = "Welche Antwort erwartest du?"
  },
  AvgDialog_45427_Content_69 = {
    Text = "Es steht schon lange in den Liedern"
  },
  AvgDialog_45427_Content_7 = {
    Text = "Was mich besorgt, ist nicht „Er“, sondern dieses Kind."
  },
  AvgDialog_45427_Content_70 = {
    Text = "Der Heilige Fluss des Wiedergeborenen Mutterbaums krönt die Verstorbenen und bringt ihre Blutlinie zu Yalan zurück."
  },
  AvgDialog_45427_Content_71 = {
    Text = "Die Wiedergeburt des Heiligen Flusses des Mutterbaums ist leicht zu verstehen, aber wer sind die Verstorbenen? Und wie bringen wir die Blutlinie zurück zu Yalan?"
  },
  AvgDialog_45427_Content_72 = {Text = "Shh—"},
  AvgDialog_45427_Content_73 = {
    Text = "Die Details sind zu komplex, @1s Prophezeiung kann nicht alle Antworten geben"
  },
  AvgDialog_45427_Content_74 = {
    Text = "Alles, was du tun musst, ist, mir vollkommen zu vertrauen.\nVertraue der Königin von Aran."
  },
  AvgDialog_45427_Content_75 = {
    Text = "Die Wüstenblume blüht in der dunklen Mondnacht, sie hebt die Hand, dreht sich und tanzt in einem alten Rhythmus auf dem Sand"
  },
  AvgDialog_45427_Content_76 = {
    Text = "Solange du mir vertraust, bin ich deine absolute, einzige, nur für dich bestimmte - Geheimwaffe"
  },
  AvgDialog_45427_Content_77 = {
    Text = "Im Mondlicht ist ihre Silhouette weich und geheimnisvoll, ihre Augen sprechen unausgesprochene Gefühle"
  },
  AvgDialog_45427_Content_78 = {
    Text = "Wenn dies ein endender Traum ist –\nferne Sterne sind ihre Zeugen"
  },
  AvgDialog_45427_Content_79 = {
    Text = "Warte, Thais, unter deinem Fuß—"
  },
  AvgDialog_45427_Content_8 = {
    Text = "Dies liegt über dem, was du und ich beeinflussen können."
  },
  AvgDialog_45427_Content_80 = {
    Text = "Du rufst verzweifelt"
  },
  AvgDialog_45427_Content_81 = {
    Text = "Sie trat auf die Wellen, nein, schwarze Wellen breiteten sich von ihren Zehenspitzen aus"
  },
  AvgDialog_45427_Content_82 = {
    Text = "Der Rand des weißen Schleiers schwingt wie tanzende Seerosenblätter, glänzend und tiefschwarz"
  },
  AvgDialog_45427_Content_83 = {
    Text = "Das ist ... D-Schleim ...?"
  },
  AvgDialog_45427_Content_84 = {
    Text = "Sie tanzte in einem illusorischen Schmelzbecken, immer wieder auf der schwarzen Oberfläche"
  },
  AvgDialog_45427_Content_85 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45427_Content_86 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45427_Content_87 = {
    Text = "Sie scheint deinen Ruf nicht zu hören und tanzt im Einklang mit einer unbekannten Melodie"
  },
  AvgDialog_45427_Content_88 = {
    Text = "Sie drehte sich zu dir um, ihre Haltung entspannt, die Kette, die du ihr angelegt hast, funkelte auf ihrer Brust"
  },
  AvgDialog_45427_Content_89 = {
    Text = "Sie lud dich zum Tanzen ein, und du legtest automatisch deine Hand in ihre"
  },
  AvgDialog_45427_Content_9 = {
    Text = "Mythag hat dreihundert Jahre Erbe in dies investiert. Der Erbe, den wir gewählt haben, darf vom vorbestimmten Weg nicht abweichen."
  },
  AvgDialog_45427_Content_90 = {
    Text = "Sie nahm deine Hand und führte deine Fingerspitze zu dem pulsierenden Jade"
  },
  AvgDialog_45427_Content_91 = {
    Text = "Ein Meteor fällt vom fernen Himmel.\nIhre Augen leuchten heller als die Sterne"
  },
  AvgDialog_45427_Content_93 = {
    Text = "Ihre Lippen öffneten sich leicht, der Abendwind trug ihr leises Flüstern herbei"
  },
  AvgDialog_45427_Content_94 = {
    Text = "Kann ich sie dir anvertrauen?"
  },
  AvgDialog_45427_Content_95 = {
    Text = "Ein Gefühl, ähnlich dem bei der Lagerfeuerparty, ergriff dich, und fast unwillkürlich murmelst du"
  },
  AvgDialog_45427_Content_96 = {
    Text = "Ja, es wird klappen"
  },
  AvgDialog_45427_Content_97 = {Text = "Gut."},
  AvgDialog_45427_Content_98 = {
    Text = "Thais lächelte"
  },
  AvgDialog_45427_Content_99 = {
    Text = "Deine Freunde sind angekommen."
  },
  AvgDialog_45429_Content_1 = {
    Text = "Casiahs rote Bänder flattern umher und zertrümmern Teller und Tassen im Zelt in Stücke."
  },
  AvgDialog_45429_Content_10 = {
    Text = "Sie enthüllte flink den riesigen Zauberhut und offenbarte eine unerwartete Gestalt."
  },
  AvgDialog_45429_Content_11 = {
    Text = "Wie könnte das du sein?!"
  },
  AvgDialog_45429_Content_12 = {
    Text = "Ups, nur ein kleines bisschen Glück."
  },
  AvgDialog_45429_Content_13 = {
    Text = "Casiah schaut hastig aus dem Fenster und sieht die Gestalt des Hüters, die auf einem Kamel davon springt."
  },
  AvgDialog_45429_Content_14 = {
    Text = "Drei Würfel durchbohrten den Vorhang und streiften Casiahs Wange."
  },
  AvgDialog_45429_Content_15 = {
    Text = "Alright, wirst du bis zum Ende mit mir kämpfen?"
  },
  AvgDialog_45429_Content_16 = {
    Text = "In Ordnung, lass uns dich in die Dimensionale Leere schicken, um über deine Fehler nachzudenken!"
  },
  AvgDialog_45429_Content_17 = {
    Text = "Die Illusion umhüllte plötzlich den Raum vor deinen Augen; die Sicht war von Farben bedeckt, die an ein Ölgemälde erinnerten. Als das mehrfarbige Chaos wieder Ordnung fand, hatte sich der Raum in eine Bühne eines Magiers verwandelt."
  },
  AvgDialog_45429_Content_18 = {
    Text = "Führe nach Herzenslust aus, \"Wunder Casiahs Magischer Karneval!\""
  },
  AvgDialog_45429_Content_2 = {
    Text = "Du tauschst einen Blick mit Ryker aus.\nDie oberste Priorität ist es jetzt, zu entkommen und das vom Tempel Licht Kirche orchestrierte Alan-Opferritual zu stoppen."
  },
  AvgDialog_45429_Content_3 = {
    Text = "Casiahs Zauberhut kommt auf dich zu. Du und Ryker trennen euch wie geplant, aber ein Hut verfolgt dich—"
  },
  AvgDialog_45429_Content_4 = {
    Text = "Heh heh, rate mal, in welchem Hut der Wächter ist?"
  },
  AvgDialog_45429_Content_5 = {
    Text = "Die linke Seite ist leer, und die rechte Seite ist auch leer~"
  },
  AvgDialog_45429_Content_6 = {
    Text = "Kling ~ Eigentlich ist keine der Hüte da, schau, {Male=er,Female=sie} ist im Vorhang von Casiah!"
  },
  AvgDialog_45429_Content_7 = {
    Text = "Ein scharlachroter Vorhang bricht aus der Leere hervor, wirbelt in wogenden Wellen und umwickelt den Hüter fest zu einer scharlachroten Mumie."
  },
  AvgDialog_45429_Content_8 = {
    Text = "Wie ist es? Fühlt es sich nicht an wie eine Aufführung voller Arlan-Charme?"
  },
  AvgDialog_45429_Content_9 = {
    Text = "Telekinese~ Hehe, es ist Zeit für mich, zu sammeln!"
  },
  AvgDialog_45430_Content_1 = {
    Text = "Zusammenführung"
  },
  AvgDialog_45430_Content_10 = {
    Text = "Mutterbaum... Ist er nicht genau dort?"
  },
  AvgDialog_45430_Content_100 = {
    Text = "Ihr rennt zum Lager unter den Dünen"
  },
  AvgDialog_45430_Content_101 = {
    Text = "Im Moment der Berührung des Vorhangs ergriff dich eine große Angst"
  },
  AvgDialog_45430_Content_103 = {
    Text = "Diese Angst ist anders als die Konfrontation mit Jagdhunden oder dem Heiligen Embryo"
  },
  AvgDialog_45430_Content_104 = {
    Text = "Das war ein tiefsitzender, unaussprechlicher Schrecken, dem man nicht entkommen konnte"
  },
  AvgDialog_45430_Content_105 = {
    Text = "Das ist der schwebende Albtraum, die abnorme Fantasie, die unerträgliche, erstickende Realität"
  },
  AvgDialog_45430_Content_106 = {
    Text = "Ein riesiges, wildes Monster schwingt seine schleimigen Tentakel, und Williams dünner Körper schwankt wie ein einsamer Schilfrohr"
  },
  AvgDialog_45430_Content_108 = {
    Text = "Die Narbe an seiner Schläfe, angeblich von seiner wahnsinnigen Mutter verursacht, sah jetzt wie ein flacher Graben aus, aus dem scharlachroter Saft sickerte"
  },
  AvgDialog_45430_Content_109 = {
    Text = "Der Silberschlüssel zerbricht auf deiner Brust, die standardmäßigen Handschuhe der Missaga sind mit Blut befleckt, und unheilvolle Flüssigkeit tropft entgegen der Schwerkraft"
  },
  AvgDialog_45430_Content_11 = {
    Text = "Der entfernte Horizont, wo der Himmel aufeinandertrifft."
  },
  AvgDialog_45430_Content_110 = {
    Text = "Hinter dem schwankenden Albtraum—"
  },
  AvgDialog_45430_Content_111 = {
    Text = "Ein riesiger Fleischberg öffnete wie eine Venusfliegenfalle den klaffenden Rachen"
  },
  AvgDialog_45430_Content_112 = {
    Text = "Die Plazenta und die Falten des missgebildeten Babys sind so klar wie das blutige Brandmal in deinem Kopf"
  },
  AvgDialog_45430_Content_113 = {
    Text = "In der Mitte des deformierten Fleischklumpens liegt das letzte Geschenk, das er euch durch ständige Rückverfolgung und Erforschung überreicht"
  },
  AvgDialog_45430_Content_114 = {
    Text = "Das ist die Wahrheit des Nubia-Kerns—"
  },
  AvgDialog_45430_Content_115 = {
    Text = "Eine kleine Laterne"
  },
  AvgDialog_45430_Content_12 = {
    Text = "Der gewaltige Mutterbaum steht, als wäre er in einem fernen Reich."
  },
  AvgDialog_45430_Content_13 = {
    Text = "Du meinst, du kannst den Mutterbaum sehen?"
  },
  AvgDialog_45430_Content_14 = {
    Text = "Du blickst zum Himmel auf, streckst deine Hand aus und umrissest die Silhouette des Mutterbaums."
  },
  AvgDialog_45430_Content_15 = {
    Text = "Ein verwelkter, schlanker Baum... hoch, aber einsam..."
  },
  AvgDialog_45430_Content_16 = {
    Text = "Vielleicht... der Mutterbaum verschwand wegen der Auflösung."
  },
  AvgDialog_45430_Content_17 = {
    Text = "Erinnerst du dich? %player% behält die Erinnerungen an Dinge, die der Auflösung verloren gingen."
  },
  AvgDialog_45430_Content_18 = {
    Text = "Du entfaltet die Zeitung, die von Jenkin gebracht wurde, und stellst fest, dass die Tinte darauf lebendig zu sein scheint und allmählich sich auflöst—"
  },
  AvgDialog_45430_Content_19 = {
    Text = "Bis du den Bericht über \"Frühling\" nicht mehr erkennen kannst"
  },
  AvgDialog_45430_Content_2 = {
    Text = "Dann wird ▼▼▼ zu ihrem Thron zurückkehren,\nChaos wird verbannt werden.\nDiejenigen, die dies miterleben, werden jubeln,\nund diejenigen, die dem König dienen, werden sich ebenfalls freuen."
  },
  AvgDialog_45430_Content_20 = {
    Text = "Diese beschädigten Wasserzeichen und Tintenflecken scheinen darauf aus zu sein, Masons Existenz vollständig auszulöschen."
  },
  AvgDialog_45430_Content_21 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45430_Content_22 = {
    Text = "Ist das eine Art von Magie? Ich habe diese Zeitung schon 800 Mal gelesen."
  },
  AvgDialog_45430_Content_23 = {
    Text = "Aber jetzt... kann ich mich nicht einmal an ein einziges Wort erinnern."
  },
  AvgDialog_45430_Content_24 = {
    Text = "Huh, erinnerst du dich an nichts?"
  },
  AvgDialog_45430_Content_25 = {
    Text = "\"Der herausragende Verteidiger des Kubismus, die Wiedergeburt der Seele von Botticelli, versteckt sich im Wachsfigurenkabinett an der Ecke der South Hark Street...\""
  },
  AvgDialog_45430_Content_26 = {
    Text = "Du siehst, ich kann sogar den Inhalt dieser Nachricht vortragen."
  },
  AvgDialog_45430_Content_27 = {
    Text = "Die Zeitung wurde aufgelöst. Dies deutet auf ein wahrscheinliches <Yellow:mass amnesia> Ereignis hin, verursacht durch die Auflösung, aber..."
  },
  AvgDialog_45430_Content_28 = {
    Text = "Ramona und Jenkins schauen gleichzeitig zu dir."
  },
  AvgDialog_45430_Content_29 = {
    Text = "Scheint keinen Einfluss auf jemanden zu haben."
  },
  AvgDialog_45430_Content_3 = {
    Text = "Die Gruppe... Nur drei Personen überlebten, einschließlich Nephlure."
  },
  AvgDialog_45430_Content_30 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45430_Content_31 = {
    Text = "Glaub es oder nicht, das fühlt sich nicht sonderlich gut an..."
  },
  AvgDialog_45430_Content_32 = {
    Text = "Es scheint, dass, ohne es zu merken, die Vergangenheit verändert wurde und die Geschichte von ihrem vorgesehenen Weg abgewichen ist."
  },
  AvgDialog_45430_Content_33 = {
    Text = "Und du bist der einzige Zeuge dieser Veränderungen geworden."
  },
  AvgDialog_45430_Content_34 = {
    Text = "Als Trägerin der Essenz des Wunsches muss der Mutterbaum einen tiefgreifenden Eindruck auf den Planeten hinterlassen haben."
  },
  AvgDialog_45430_Content_35 = {
    Text = "Die Widerstandsfähigkeit des Mutterbaums verlangsamt seine Erosionsrate um das Tausendfache"
  },
  AvgDialog_45430_Content_36 = {
    Text = "Also, für dich ist sie noch nicht ganz verschwunden."
  },
  AvgDialog_45430_Content_37 = {
    Text = "In hundert oder tausend Jahren wird Aram wahrscheinlich sogar das Dasein des Mutterbaums vergessen."
  },
  AvgDialog_45430_Content_38 = {
    Text = "Und Yalans Ritual könnte die schwache Präsenz der Überreste des Mutterbaums einfange."
  },
  AvgDialog_45430_Content_39 = {
    Text = "Wie ein Erwachen-Zeremonie?"
  },
  AvgDialog_45430_Content_4 = {
    Text = [[
Aber die Aram scheinen aufgeregt zu sein.
Solche Opfer... sind ihnen wahrscheinlich routine.]]
  },
  AvgDialog_45430_Content_40 = {
    Text = "In der Tat benutzt die Erwachungszeremonie die Geisterkraft des Ermittlers, um den Geist innerhalb des Silbers wieder zum Leben zu erwecken. Die \"Wiedergeburt\" des Mutterbaums sollte ähnlich sein."
  },
  AvgDialog_45430_Content_41 = {
    Text = "%player%, wie sieht der Mutterbaum für dich aus?"
  },
  AvgDialog_45430_Content_42 = {
    Text = "Hmm... Wie soll ich das ausdrücken? Es ist wie ein nackter Stamm, der in unfruchtbarem Boden wächst... völlig unabhängig von Fruchtbarkeit."
  },
  AvgDialog_45430_Content_43 = {
    Text = "Es ist wie... der Mutterbaum in seinen letzten Momenten."
  },
  AvgDialog_45430_Content_44 = {
    Text = "Ruhst du dich noch nicht aus? Die Aran-Zeremonie ist morgen!"
  },
  AvgDialog_45430_Content_45 = {
    Text = "Meine Sektion ist fast abgeschlossen."
  },
  AvgDialog_45430_Content_46 = {
    Text = "Es ist nicht die Zeit dafür, und du denkst immer noch an deine Sektion...\nObwohl ich das wirklich sagen möchte, hast du recht. Wir brauchen immer noch das letzte Stück des Puzzles."
  },
  AvgDialog_45430_Content_47 = {
    Text = "%player%, dies ist deine letzte Chance."
  },
  AvgDialog_45430_Content_48 = {
    Text = "Warum bleibt er für die Obduktion wach, und du auch?"
  },
  AvgDialog_45430_Content_49 = {
    Text = "Ich... erinnere mich an einen Traum."
  },
  AvgDialog_45430_Content_5 = {
    Text = "Du schaust hinaus auf die einst schweigende Menge, deren Pupillen wie eine Oase schimmern."
  },
  AvgDialog_45430_Content_50 = {
    Text = "Das ist einer der Träume, die du oft hast."
  },
  AvgDialog_45430_Content_51 = {
    Text = "Im Traum gab es nur Dunkelheit und die tosende Flut, die mit einem grollenden Geräusch gegen die Küste schlug."
  },
  AvgDialog_45430_Content_52 = {
    Text = "Dein Herz schlägt im Rhythmus des fließenden Wassers. Unzählige Herzen schlagen mit ihm."
  },
  AvgDialog_45430_Content_53 = {
    Text = "Die zahllosen Herzschläge vereinen sich zu einem pechschwarzen Fluss, dessen dunkler Strom unkontrollierbar zum Meer strömt und den ganzen Ozean tiefschwarz färbt..."
  },
  AvgDialog_45430_Content_54 = {
    Text = "Ich habe gehört, dass deine Träume oft Prophezeiungen enthalten."
  },
  AvgDialog_45430_Content_55 = {
    Text = "Manchmal ist es eine Erinnerung, manchmal eine Prophezeiung."
  },
  AvgDialog_45430_Content_56 = {
    Text = "So oder so bedeutet es, dass diese Leben tatsächlich aufgelöst und verschlungen wurden..."
  },
  AvgDialog_45430_Content_57 = {
    Text = "Denke nicht zu viel. Selbst ohne Auflösung ist die Menschheit auf einem ständigen Weg des Fortschritts und des Verfalls"
  },
  AvgDialog_45430_Content_58 = {
    Text = "Wenn wir über dieses Thema sprechen, denke ich, wir sollten William anrufen und ein paar Drinks haben."
  },
  AvgDialog_45430_Content_59 = {
    Text = "Mythags größter legendärer Ermittler hat mehr mysteriöse Ereignisse erlebt als die Anzahl der Wetten, die ich gewonnen habe."
  },
  AvgDialog_45430_Content_6 = {
    Text = "Mutterbaum, bitte bereichere das Land und Wasser von Yalan und beschütze seine Generationen."
  },
  AvgDialog_45430_Content_60 = {
    Text = "Du klopfst auf die Brosche an deiner Brust und rufst William."
  },
  AvgDialog_45430_Content_61 = {
    Text = "Ich hätte... ich hätte es erkennen sollen."
  },
  AvgDialog_45430_Content_62 = {
    Text = "In der Mitte des Zeltes lag Nubias Leiche, aufgeschlitzt, der Schnitt glatt und präzise.\nBei näherer Betrachtung konnte man noch ihr schwaches Atmen spüren."
  },
  AvgDialog_45430_Content_63 = {
    Text = "Das ist die Grenze, die durch zahllose Experimente erreicht wurde, ein Puls, der am Rand zwischen Leben und Tod balanciert."
  },
  AvgDialog_45430_Content_64 = {
    Text = "In der Lage, den Auflösungsprozess zu kontrollieren, wodurch Nubia-Anomalien verschwinden."
  },
  AvgDialog_45430_Content_65 = {
    Text = "Unsere Feinde verfügen über ein außergewöhnliches Verständnis und Beherrschung der Auflösung."
  },
  AvgDialog_45430_Content_66 = {
    Text = "Er legte das Skalpell nieder und holte tief Luft. Der Gestank, ähnlich wie faules Blut, erstickte ihn und löste einen heftigen Husten aus."
  },
  AvgDialog_45430_Content_67 = {
    Text = "Und dieses Lied..."
  },
  AvgDialog_45430_Content_68 = {
    Text = "Die Überreste der Mutter sind verschwunden, Blut und Samen treiben über das Land und werden von den neu geborenen Tieren verschlungen"
  },
  AvgDialog_45430_Content_69 = {
    Text = "Der Himmel ist mit dunklen Wolken bedeckt, bis die Botschafter aus dem fremden Land erscheinen"
  },
  AvgDialog_45430_Content_7 = {
    Text = "Sobald du wiedergeboren bist, wird Yalan dir bestimmt das süßeste Wasser bieten..."
  },
  AvgDialog_45430_Content_70 = {
    Text = "Die Ankunft des Ungeheuers geht der des Boten voraus."
  },
  AvgDialog_45430_Content_71 = {
    Text = "So hatte sich Juliette außerhalb der Sturmwand herumgetrieben, was sie sicher machte, dass sie es dieses Mal durchbrechen könnte."
  },
  AvgDialog_45430_Content_72 = {
    Text = "Juliette ist überhaupt nicht die legendäre ausländische Gesandte..."
  },
  AvgDialog_45430_Content_73 = {
    Text = [[
Sie kam aus der Tempellichter-Kirche, erfand einen sogenannten Traumaufruf und gewann das Vertrauen der Arams.
Ihr Ziel... ist es wahrscheinlich, mit den Arams zu reisen, den Mutterbaum und den heiligen Fluss zu kontaminieren.]]
  },
  AvgDialog_45430_Content_74 = {
    Text = "Der wahre Gesandte aus der Ferne...\nNicht nötig, zu raten, es ist zweifellos der Hüter."
  },
  AvgDialog_45430_Content_75 = {
    Text = "Nein, es ist immer noch nicht genug."
  },
  AvgDialog_45430_Content_76 = {
    Text = "Ein ungewöhnliches Gefühl veranlasste William, seine Schlussfolgerung weiter zu verfeinern."
  },
  AvgDialog_45430_Content_77 = {
    Text = [[
Hier sind diese abnormalen Schnittstellen...
Sie sind das Werk der Bildhauervereinigung und dieses Typen Herbert.]]
  },
  AvgDialog_45430_Content_78 = {
    Text = "Wenn dein Denken an dem vorherigen Schritt gestoppt hätte, hättest du Lemwash sicher verlassen können."
  },
  AvgDialog_45430_Content_79 = {
    Text = "So wie man es von Mythags legendärem Ermittler erwartet, findest du die Antwort vor allen anderen."
  },
  AvgDialog_45430_Content_8 = {
    Text = "Immer diese Aram über den Mutterbaum sprechen zu hören, frage ich mich, wie majestätisch dieser Anblick wirklich ist."
  },
  AvgDialog_45430_Content_80 = {Text = "Herbert!"},
  AvgDialog_45430_Content_81 = {
    Text = "Sei nicht nervös, ich habe an deine Fähigkeiten immer mehr geglaubt als alle anderen."
  },
  AvgDialog_45430_Content_82 = {
    Text = "Sie würden dasselbe tun oder warum dich hier allein ohne einen Erwachten lassen?"
  },
  AvgDialog_45430_Content_83 = {
    Text = [[
Ich auch.
Wenn ich mich recht erinnere, hat dein Erwacher die Kette mit dir in Rai gebrochen.]]
  },
  AvgDialog_45430_Content_84 = {
    Text = "Was den Erwacher betrifft, den du engagiert hast... Ich glaube, Lady Narzisse würde sich nicht offen gegen die Mythag-Universität aussprechen."
  },
  AvgDialog_45430_Content_85 = {
    Text = "Du denkst, ich wäre nicht in der Lage, dich hier zu töten."
  },
  AvgDialog_45430_Content_86 = {
    Text = "Ich unterschätze meine Feinde niemals, besonders den, der Professor Crowley getötet hat."
  },
  AvgDialog_45430_Content_87 = {
    Text = "Ich weiß, natürlich weiß ich das."
  },
  AvgDialog_45430_Content_88 = {
    Text = "Während der Ermittlungen im Studio und der Zeremonie am Sentinel Ridge... \nKeine der Diener des höheren Willens konnte dich aufhalten, geschweige denn bloße Erwachende."
  },
  AvgDialog_45430_Content_89 = {
    Text = "Also, als ich hörte, dass Mythag dich geschickt hatte, wusste ich, dass ich mich vollständig vorbereiten musste."
  },
  AvgDialog_45430_Content_9 = {
    Text = "Ryker... worüber redest du...?"
  },
  AvgDialog_45430_Content_90 = {
    Text = "Du bist Ramona: Zeitlos, richtig?"
  },
  AvgDialog_45430_Content_91 = {
    Text = "Öffnen Sie auf irgendeine Weise einen Durchgang zu anderen Welten und lassen Sie die Geister höherer Wesen aus diesen Welten die entsprechenden Individuen behausen."
  },
  AvgDialog_45430_Content_92 = {
    Text = "Herbert streichelte den Kopf der Monsterkatze auf seiner Schulter."
  },
  AvgDialog_45430_Content_93 = {
    Text = "Schatz, ich liebe dich so sehr wie ich es liebe."
  },
  AvgDialog_45430_Content_94 = {
    Text = "<Blue:Helot: Catena Helot>."
  },
  AvgDialog_45430_Content_95 = {
    Text = "Hey, Senior William..."
  },
  AvgDialog_45430_Content_96 = {
    Text = "Fünf Sekunden."
  },
  AvgDialog_45430_Content_97 = {
    Text = "10 Sekunden."
  },
  AvgDialog_45430_Content_98 = {
    Text = "William befindet sich in einem Zelt, nur hundert Schritte von dir entfernt, aber am anderen Ende der Kommunikation ist es still."
  },
  AvgDialog_45430_Content_99 = {
    Text = "Ein plötzlicher Anstieg des Unbehagens, Angst schlägt wie ein Hammer auf dein Herz"
  },
  AvgDialog_45431_Content_1 = {Text = "Überreste"},
  AvgDialog_45431_Content_10 = {
    Text = "Es ist jetzt etwas entspannter. Da William weg ist, mache ich mir Sorgen um euch beide."
  },
  AvgDialog_45431_Content_11 = {
    Text = "Ihre Wangen sind immer noch leicht rötlich. Du berührst sanft ihre Stirn; sie fühlt sich nicht mehr so heiß an wie zuvor."
  },
  AvgDialog_45431_Content_12 = {
    Text = "Was ist das hier...?"
  },
  AvgDialog_45431_Content_13 = {
    Text = "Im Gegensatz zur primitiven Atmosphäre des Yalan-Stammes liegen vor dir die Ruinen einer längst verlassenen Fabrik, die viel näher an der menschlichen Zivilisation ist, die du kennst."
  },
  AvgDialog_45431_Content_14 = {
    Text = "Nach dem alluvialen Ereignis führte das Lemwahis-Regime hier industrielle Bauarbeiten durch und errichtete mehrere Fabriken und Schulen."
  },
  AvgDialog_45431_Content_15 = {
    Text = "Aber die Aram, die nomadisch leben, boten nur begrenzte Unterstützung für die Industrialisierung der Wüste. Diese Strukturen wurden aufgegeben, als die Wüstenbildung sich verstärkte und sich Regierungen änderten."
  },
  AvgDialog_45431_Content_16 = {
    Text = "Die Aram-Leute verschwendeten diese Dächer nicht, sondern nutzten verlassene Fabriken, um Gegenstände zu lagern, die Belüftung, Feuchtigkeitsschutz und hohe Sicherheit erforderten – wie zum Beispiel die Überreste des Heiligen Baumes, mit denen du und ich vertraut sind."
  },
  AvgDialog_45431_Content_17 = {
    Text = "Warte, etwas kommt auf uns zu!"
  },
  AvgDialog_45431_Content_2 = {
    Text = [[
Du bist verschwunden, in dem Moment, als ich mich umdrehte.
Wem hast du gerade gesprochen?]]
  },
  AvgDialog_45431_Content_3 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45431_Content_4 = {
    Text = "Alles, was du tun musst, ist, mir vollkommen zu vertrauen.\nVertraue der Königin von Aran."
  },
  AvgDialog_45431_Content_5 = {
    Text = "Vergiss nicht, dass diese Nacht nur unser Geheimnis gehört"
  },
  AvgDialog_45431_Content_6 = {
    Text = "Dein Zögern blieb den Augen des Detektivs nicht verborgen."
  },
  AvgDialog_45431_Content_7 = {
    Text = "Unser kleiner Freund hat ein Geheimnis, das er nicht teilen möchte.\nMach dir keine Sorgen, verständnisvolle Erwachsene werden nicht drängen."
  },
  AvgDialog_45431_Content_8 = {
    Text = "Ramona und ich folgten nur Arans Team und bestätigten den Standort der Überreste des heiligen Baumes.\nDie Zeit drängt. Lass uns unter dem Deckmantel der Mitternacht eindringen."
  },
  AvgDialog_45431_Content_9 = {
    Text = "Ramona, ist dein Körper in Ordnung?"
  },
  AvgDialog_45432_Content_1 = {Text = "Sturmwand"},
  AvgDialog_45432_Content_10 = {
    Text = "Die Sturmwand ist kein permanentes Hindernis, sondern eine Verhüllung, die vom heiligen Baum erschaffen wurde."
  },
  AvgDialog_45432_Content_11 = {
    Text = "Wenn es nicht dem Zweck dienen würde, den Mutterbaum zu treffen, würde man die Sturmwand nicht einmal sehen, geschweige denn durchbrechen."
  },
  AvgDialog_45432_Content_12 = {
    Text = "Daher benötigen sie den \"Boten aus der Ferne\"."
  },
  AvgDialog_45432_Content_13 = {
    Text = "Die Schlange breitete sich ordentlich zu beiden Seiten aus, mit Abständen von fünf bis zehn Schritten, die eine lange schlangenartige Reihe von Menschen bildeten."
  },
  AvgDialog_45432_Content_14 = {
    Text = "Alle, nehmt eure Positionen ein und steht fest."
  },
  AvgDialog_45432_Content_15 = {
    Text = "Elva schwenkt die Fahne, sie bewegen sich synchron und ziehen die Speere durch die Wüste, wirbeln den blendenden Sand auf und singen seltsame, entfernte Lieder"
  },
  AvgDialog_45432_Content_16 = {
    Text = "Der Tod naht, das Ende hat begonnen"
  },
  AvgDialog_45432_Content_17 = {
    Text = "Die Überreste der Mutter sind verschwunden, Blut und Samen treiben über das Land und werden von den neu geborenen Tieren verschlungen"
  },
  AvgDialog_45432_Content_18 = {
    Text = "Der Himmel ist mit dunklen Wolken bedeckt, bis die Botschafter aus dem fremden Land erscheinen"
  },
  AvgDialog_45432_Content_19 = {
    Text = "Der Heilige Fluss des Wiedergeborenen Mutterbaums krönt die Verstorbenen und bringt ihre Blutlinie zu Yalan zurück."
  },
  AvgDialog_45432_Content_2 = {
    Text = "Mir geht's gut.\nAlva hat bereits begonnen, das Team zu zählen. Lass uns sie einholen."
  },
  AvgDialog_45432_Content_20 = {
    Text = "Gib die Blutlinie zurück... an Arlan..."
  },
  AvgDialog_45432_Content_21 = {
    Text = "Die grelle Sonne der Wüste ist verschwunden, der Himmel ist düster und der Wind hat seinen Ton geändert"
  },
  AvgDialog_45432_Content_22 = {
    Text = "Ein unerklärlicher Schrecken ergriff dich, du warst einen Moment lang benommen, dann weckte dich ein Schrei"
  },
  AvgDialog_45432_Content_23 = {
    Text = "Es, es kommt—!"
  },
  AvgDialog_45432_Content_24 = {
    Text = "Im Moment des Fokussierens verstehst du, was die „Sturmwand\" ist"
  },
  AvgDialog_45432_Content_25 = {
    Text = "Das ist eine graue Wand, die den Himmel verdeckt und alles verschlingt"
  },
  AvgDialog_45432_Content_26 = {
    Text = "Es sollte eine Flut sein, ist es aber nicht. Es ist riesig und still, bewegt sich vorwärts, scheint aber stillzustehen"
  },
  AvgDialog_45432_Content_27 = {
    Text = "Seine Grenzen lecken wie ein riesiges Tier die Erde, und die Reihen von Arlan werden in den Nebel verschlungen, zerrissen und verdaut vom Magen des Sturms"
  },
  AvgDialog_45432_Content_28 = {
    Text = "Spring weiter, nicht aufhören!"
  },
  AvgDialog_45432_Content_29 = {
    Text = "Der Bote aus der Fremde ist hier, die Königin wird uns den Weg zum Mutterbaum öffnen!"
  },
  AvgDialog_45432_Content_3 = {
    Text = "Heute ist der Tag, um zur Sturmwand aufzubrechen."
  },
  AvgDialog_45432_Content_30 = {
    Text = "Du bemerkst, dass Juliette ein leises Lächeln zeigt"
  },
  AvgDialog_45432_Content_31 = {
    Text = "Häuptling, Häuptling, der Sturm ist heute zu heftig, wir können uns nicht so viele Verluste leisten, ziehen wir uns zurück!"
  },
  AvgDialog_45432_Content_32 = {Text = "Nein!"},
  AvgDialog_45432_Content_33 = {
    Text = "Ihre Stimme war majestätisch, aber zitterte im Wind"
  },
  AvgDialog_45432_Content_34 = {
    Text = "Die Rate von Missbildungen im Lagerfeuerritual nimmt zu. Wenn das so weitergeht, wird Yalans Blutlinie im Fluss der Zeit verschwinden, bevor der Mutterbaum entdeckt wird."
  },
  AvgDialog_45432_Content_35 = {
    Text = "Juliette formte mit ihren Fingern einen Ring und pfiff einen durchdringenden Pfiff, während die anhaltenden Klänge vom Sturm erfasst und in das Unbekannte getragen wurden"
  },
  AvgDialog_45432_Content_36 = {
    Text = "Ich bin die Gesandte Juliette. Ich habe den Willen der Königin gehört. Heute werden wir die Sturmwand durchbrechen!"
  },
  AvgDialog_45432_Content_37 = {
    Text = "Alle, nur vorwärts, kein Rückzug!"
  },
  AvgDialog_45432_Content_38 = {
    Text = "Befehl des Gesandten befolgen, nur vorwärts, kein Rückzug!"
  },
  AvgDialog_45432_Content_39 = {
    Text = "<Small:Ja... ein Rückzugsweg... gibt es nicht...>"
  },
  AvgDialog_45432_Content_4 = {
    Text = "Krieger, seid ihr bereit?"
  },
  AvgDialog_45432_Content_40 = {
    Text = "Warte, Hüter, eine große Gruppe Nubier kommt von hinten...\nNach der Anzahl zu urteilen... mindestens... zweihundert!"
  },
  AvgDialog_45432_Content_41 = {
    Text = "Seht! Das ist der Wille der Königin! Ihr müsst vorwärts!"
  },
  AvgDialog_45432_Content_42 = {
    Text = "Nubia brüllt und rennt auf euch zu"
  },
  AvgDialog_45432_Content_5 = {
    Text = "Du bemerkst zwei Reihen von Soldaten, die Alva folgen.\nIhre ernsten Gesichtsausdrücke offenbaren ihre Bereitschaft, dem Tod ins Auge zu sehen."
  },
  AvgDialog_45432_Content_6 = {
    Text = "Der junge Mann, der vorne steht, hat ein markantes Profil und eine aufrechte Haltung, sieht etwas vertraut aus."
  },
  AvgDialog_45432_Content_7 = {Text = "Sturmwand?"},
  AvgDialog_45432_Content_8 = {
    Text = "Du blickst in die Ferne. Der Himmel ist klar, die Sicht ungehindert, ohne Anzeichen eines Sandsturms."
  },
  AvgDialog_45432_Content_9 = {
    Text = "Juliette trat vor."
  },
  AvgDialog_45433_Content_1 = {Text = "Epilog"},
  AvgDialog_45433_Content_10 = {
    Text = "Zumindest haben wir das schlimmste Ergebnis verhindert."
  },
  AvgDialog_45433_Content_11 = {
    Text = "Wenn der Mutterbaum unter der Kontrolle der Tempel Licht Kirche wiederbelebt, wird sich die Verschmutzung weit über die nördliche Wüste von Lemwashi ausbreiten."
  },
  AvgDialog_45433_Content_12 = {
    Text = "Allerdings haben wir auch den unerträglichsten Verlust seit der Gründung unserer Institution erlitten."
  },
  AvgDialog_45433_Content_13 = {
    Text = "Williams Körper... zeigte keine Spuren von Silber."
  },
  AvgDialog_45433_Content_14 = {
    Text = "Wir haben den besten Ermittler seit der Gründung der Mythag-Universität dauerhaft verloren, und es gibt keine Möglichkeit, sein Bewusstsein teilweise zurückzuholen."
  },
  AvgDialog_45433_Content_15 = {
    Text = "Heute werden seine Überreste hier begraben."
  },
  AvgDialog_45433_Content_16 = {
    Text = "William ist der talentierteste Ermittler, den ich kenne. Sein scharfer Einblick, seine furchtlose Haltung und seine außergewöhnlichen Fähigkeiten stechen unter den Menschen heraus."
  },
  AvgDialog_45433_Content_17 = {
    Text = "Lehrer Alistair!"
  },
  AvgDialog_45433_Content_18 = {
    Text = "Inmitten des Quietschen des Rollstuhls machte die Menge Platz für Alistair."
  },
  AvgDialog_45433_Content_19 = {
    Text = "Seine Karriere war in mysteriöse Schatten gehüllt, aber seine glorreichen Taten werden für immer wie die Sterne leuchten"
  },
  AvgDialog_45433_Content_2 = {
    Text = "Das Schlüsselgrab regnet leicht, genau wie am Tag der Schlüsselzeremonie."
  },
  AvgDialog_45433_Content_20 = {
    Text = "Der Tod ist stets gegenwärtig; wir haben wenig Zeit zu trauern angesichts der Auflösung."
  },
  AvgDialog_45433_Content_21 = {
    Text = "%player%, folge mir. Was Tawil, die drei Essenzen und die Auflösung betrifft... es gibt viel, was du jetzt wissen musst."
  },
  AvgDialog_45433_Content_22 = {
    Text = "Ich habe nie erwartet, dass deine Gleichgültigkeit gegenüber einem Kollegen so weit gehen würde, dass du nicht zu seiner Beerdigung erscheinst."
  },
  AvgDialog_45433_Content_23 = {
    Text = "Ich kann mich an diese Atmosphäre nicht gewöhnen."
  },
  AvgDialog_45433_Content_24 = {
    Text = "Mit dem erweckten Intellektuellen Körper, dem untergetauchten Sinnlichen Körper und dem präsenten Freude Körper... Jetzt, wo William weg ist, ist es meine Zeit, überwältigt zu werden."
  },
  AvgDialog_45433_Content_25 = {
    Text = "Erscheint die Essenz der Freude?"
  },
  AvgDialog_45433_Content_26 = {
    Text = "Die Untersuchung am Tatort von Williams Tod war nicht fruchtlos."
  },
  AvgDialog_45433_Content_27 = {
    Text = "Ein Stück Ultra Reich Silber, das als das von Casiah stammend identifiziert wurde."
  },
  AvgDialog_45433_Content_28 = {
    Text = "Außerdem haben wir auch Spuren von Aktivität der Joy Essence entdeckt—"
  },
  AvgDialog_45433_Content_29 = {
    Text = "Wer erlaubte dir, mit meinen Spielzeugen so nachlässig umzugehen und mich zwang, sie mit meinem kleinen Finger zu holen?"
  },
  AvgDialog_45433_Content_3 = {
    Text = "Die Menge steht solemn vor dem Grabstein, der mit Namen graviert ist, und bezeugt eine echte Beerdigung."
  },
  AvgDialog_45433_Content_30 = {
    Text = "Ich muss Herrn N für seine Hilfe danken."
  },
  AvgDialog_45433_Content_31 = {
    Text = "Next time we meet, remember to thank me for N's Großzügigkeit, Freundlichkeit, und Großmut..."
  },
  AvgDialog_45433_Content_32 = {
    Text = "Ryker kratzte sich am pelzigen Kopf."
  },
  AvgDialog_45433_Content_33 = {
    Text = "Das ist nicht ganz genau. Wir hatten vereinbart, dass ich, bis ich eine Runde gegen dich gewinne, die Qual von Misserfolg und Tod immer wieder erleben würde, richtig?"
  },
  AvgDialog_45433_Content_34 = {
    Text = "Um erneut zu sterben, muss ich zuerst wiederbelebt werden, oder? Also wirst du mich definitiv wiederbeleben."
  },
  AvgDialog_45433_Content_35 = {
    Text = "Du bist ziemlich geschickt darin, Schlupflöcher auszunutzen.\nGlaubst du wirklich, dass ich dir immer nachgeben werde?"
  },
  AvgDialog_45433_Content_36 = {
    Text = "Du bist eine vielseitige, mitfühlende, großzügige und großmütige Person. Ich glaube nicht, dass es irgendwelche Probleme geben wird."
  },
  AvgDialog_45433_Content_37 = {
    Text = "Lass uns sehen, welche spektakulären Aufführungen du für mich auf die Bühne bringen kannst."
  },
  AvgDialog_45433_Content_38 = {
    Text = [[
Nachdem die letzten Worte ausgesprochen wurden, verschwand N's Schatten.
Ryker wandte sich der Gruppe zu.]]
  },
  AvgDialog_45433_Content_39 = {
    Text = "Kurz gesagt, ich bin wieder zurück.\nEdel Dexter, möchtest du noch eine Runde spielen?"
  },
  AvgDialog_45433_Content_4 = {
    Text = "Heute hat ein neuer Gefährte sich uns auf unserer Reise angeschlossen."
  },
  AvgDialog_45433_Content_40 = {
    Text = "Zur gleichen Zeit die Lemwah-Wüste"
  },
  AvgDialog_45433_Content_41 = {
    Text = "Da, da, alles ist in Ordnung."
  },
  AvgDialog_45433_Content_42 = {
    Text = "Mein treuer und gehorsamer Hund, bitte schnüffle nach dem Aufenthaltsort dieser beiden Kinder für mich."
  },
  AvgDialog_45433_Content_43 = {
    Text = "Nur dann können wir dem Pharao einen angemessenen Bericht erstatten."
  },
  AvgDialog_45433_Content_44 = {
    Text = "Der Junge hockte in einer Ecke der Fabrik und warf gelegentlich einen Blick in die Ferne."
  },
  AvgDialog_45433_Content_45 = {
    Text = "Ich habe es geschafft, hier zu entkommen. Es sollte vorerst sicher sein..."
  },
  AvgDialog_45433_Content_46 = {
    Text = "Als nächstes, finde einen Weg, um ihm zu helfen, die Außenwelt zu verstehen."
  },
  AvgDialog_45433_Content_47 = {
    Text = "Bevor dieser Kerl uns findet."
  },
  AvgDialog_45433_Content_48 = {
    Text = "Er bemerkte überhaupt nicht, dass das Licht draußen das Schattenbild lang zog."
  },
  AvgDialog_45433_Content_49 = {
    Text = "Im langen Schatten erschien plötzlich ein gruseliges Lächeln."
  },
  AvgDialog_45433_Content_5 = {
    Text = "Es ist mir eine Ehre, Teil von Misaq zu sein.\nIch werde mit Ihnen allen für die Rettung der Menschheit kämpfen."
  },
  AvgDialog_45433_Content_6 = {
    Text = "An dem Tag, als sie Remouahe verließ, stand Alva am heiligen Fluss, schöpfte eine Handvoll Wasser und trank es."
  },
  AvgDialog_45433_Content_7 = {
    Text = "Niemand wagte zu fragen, wie es sich anfühlte, all deine Verwandten vor deinen eigenen Augen in einen strömenden Fluss verwandeln zu sehen."
  },
  AvgDialog_45433_Content_8 = {
    Text = "Aber im heutigen Regen lässt Alvas entschlossener Ausdruck dich glauben, dass sie ihren nächsten Schritt entschieden hat."
  },
  AvgDialog_45433_Content_9 = {
    Text = "Während dieser Felduntersuchung trafen wir auf die formidable Gegner und konnten nicht verhindern, dass die Lichtkirche des Tempels den Mutterbaum korrumpierte, was dazu führte, dass der Eran-Stamm aus der Geschichte ausgelöscht wurde."
  },
  AvgDialog_45434_Content_1 = {
    Text = "Du bahnst dir deinen Weg entlang des schmalen Fabrikpfades und achtest darauf, die rostigen, knarrenden verlassenen Maschinen nicht zu berühren."
  },
  AvgDialog_45434_Content_10 = {
    Text = "Aber ich bin bereit, dem Hüter zu vertrauen.\nSo wie Mythag sich entschied, dem Hüter zu vertrauen."
  },
  AvgDialog_45434_Content_11 = {
    Text = "Warte, ist das der Ort, von dem der Soldat vorher sprach—"
  },
  AvgDialog_45434_Content_12 = {
    Text = "Als die schwere Maschine umgangen wurde, krachte ein zerbrochenes Fenster herunter. Unter dem Fenster lauerte ein bekanntes riesiges Monster—"
  },
  AvgDialog_45434_Content_2 = {
    Text = "Selbst in Londinium sind Fabriken dieser Größe selten."
  },
  AvgDialog_45434_Content_3 = {
    Text = "In nur wenigen Jahrzehnten ist es bereits in solch einen Ruin gefallen."
  },
  AvgDialog_45434_Content_4 = {
    Text = "Im Jahr 308 des Holozän-Kalenders lud das Königreich Remouahe die Aram offen ein, sich in der Hauptstadt <Blue:Nasha> anzusiedeln.\nOffensichtlich erhielten sie keine Antwort."
  },
  AvgDialog_45434_Content_5 = {
    Text = "Die Aram fehlt die Fähigkeit und der Wille, eine industrielle Gesellschaft aufrechtzuerhalten; sie glauben an primalere und transzendentalere Kräfte."
  },
  AvgDialog_45434_Content_6 = {
    Text = "Ich dachte, dass Menschen auf unserer Seite ihre Gedanken besser verstehen könnten als diejenigen in der gewöhnlichen Gesellschaft."
  },
  AvgDialog_45434_Content_7 = {
    Text = "Glauben Sie, dass <Yellow:Silbertechnologie> die Zukunft der Menschheit verändern kann?"
  },
  AvgDialog_45434_Content_8 = {
    Text = "Wir wissen nichts über die Zukunft der Menschheit. Drei Jahrhunderte Forschung haben uns kein Stück näher zur Wahrheit der Auflösung gebracht."
  },
  AvgDialog_45434_Content_9 = {
    Text = "Vielleicht kann jeder Weg zum Ende führen, oder vielleicht führt jeder Weg zur gleichen Schlussfolgerung."
  },
  AvgDialog_45435_Content_1 = {Text = "Magie"},
  AvgDialog_45435_Content_10 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45435_Content_11 = {
    Text = "Leere Worte. Wir werden die Überreste des Heiligen Baumes zurückholen und sie Arlan zurückgeben."
  },
  AvgDialog_45435_Content_12 = {
    Text = "Alva ist tief in Gedanken, unsicher, ob sie deinen Worten glauben soll."
  },
  AvgDialog_45435_Content_13 = {
    Text = "Nachdem einer langen Weile, schien sie schließlich zu einer Schlussfolgerung zu kommen."
  },
  AvgDialog_45435_Content_14 = {
    Text = "Das Team wird morgen Nachmittag zur Sturmwand aufbrechen."
  },
  AvgDialog_45435_Content_15 = {
    Text = "Bevor ich das, muss ich die Überreste des Heiligen Baumes sehen."
  },
  AvgDialog_45435_Content_16 = {
    Text = "Andernfalls bitte erscheine nicht wieder in meinem Blickfeld."
  },
  AvgDialog_45435_Content_17 = {
    Text = "Alva und die Soldaten verließen ordnungsgemäß den Ort und ließen nur euch drei in der leeren Fabrik zurück."
  },
  AvgDialog_45435_Content_18 = {
    Text = "Ziemlich beeindruckend, eine recht lange Rede."
  },
  AvgDialog_45435_Content_19 = {
    Text = "Alva vertraut uns nicht; sie braucht nur eine Erklärung."
  },
  AvgDialog_45435_Content_2 = {
    Text = "<Small:Sollen wir es als Fall von hundert Vorsichtsmaßnahmen und einem Ausrutscher bezeichnen? Die Knochen dieses Kerls sind härter als wir erwartet hatten.>"
  },
  AvgDialog_45435_Content_20 = {
    Text = "Die Heiligen Baumreste befinden sich offensichtlich nicht in unserem Besitz. Uns unter Druck zu setzen, sie herauszugeben oder unsere Macht zu nutzen, um sie zu finden, dient ihren Interessen besser, als sich auf einfache Konflikte einzulassen."
  },
  AvgDialog_45435_Content_21 = {
    Text = "Kannst du wirklich die Überreste des Heiligen Baumes innerhalb eines Tages finden?"
  },
  AvgDialog_45435_Content_22 = {
    Text = "Kann nur sagen, dass es einige Ideen gibt, die es wert sind, ausprobiert zu werden."
  },
  AvgDialog_45435_Content_23 = {
    Text = "Du schließt deine Augen und versinkst im Meer des Bewusstseins."
  },
  AvgDialog_45435_Content_24 = {
    Text = "Das Geräusch des Summens, wie ein Gebet, begann—"
  },
  AvgDialog_45435_Content_25 = {
    Text = "Der Tod naht, das Ende hat begonnen"
  },
  AvgDialog_45435_Content_26 = {
    Text = "Die Überreste der Mutter sind verschwunden, Blut und Samen treiben über das Land und werden von den neu geborenen Tieren verschlungen"
  },
  AvgDialog_45435_Content_27 = {
    Text = "Ein sanftes Lachen unterbricht deine Gedanken. Du schaust auf und an einem bestimmten Punkt erscheint eine weibliche Gestalt auf dem Sarg."
  },
  AvgDialog_45435_Content_28 = {
    Text = "Kann ich sie dir anvertrauen?"
  },
  AvgDialog_45435_Content_29 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45435_Content_3 = {
    Text = "Ryker kratzte sich am Hinterkopf.\nEin strenger Aram-Soldat funkelte ihn wütend an; Ryker barte seine Zähne in einem Grinsen, und der Soldat wich zurück."
  },
  AvgDialog_45435_Content_30 = {
    Text = "Ein Wirbel von Gedanken entsteht in deinem Kopf, zerschneidend und kombinierend."
  },
  AvgDialog_45435_Content_31 = {
    Text = "Ein schwacher, ätherischer, farbloser Faden erscheint und zeigt auf die endgültige Antwort."
  },
  AvgDialog_45435_Content_32 = {
    Text = "Die Heiligen Baumreste sind hier."
  },
  AvgDialog_45435_Content_33 = {
    Text = "Du streichst sanft über die Wand, schließt die Augen und greifst ohne Zögern hinein, um ein weiches Stück Stoff zu fühlen, und ziehst es dann heraus—"
  },
  AvgDialog_45435_Content_34 = {
    Text = "Hey, stopp, stopp—"
  },
  AvgDialog_45435_Content_35 = {
    Text = "Die \"Wand\" crumblete, und das falsche Licht wurde durch echtes Sonnenlicht ersetzt, das blendend hell war."
  },
  AvgDialog_45435_Content_36 = {
    Text = "Verdammtes Ding, Casiahs Umhang wurde schief gezogen!"
  },
  AvgDialog_45435_Content_37 = {
    Text = "Ist es die Feindschaft zwischen alten Rivalen oder die Kameradschaft unter Schulfreunden, die uns Schritt für Schritt zusammengebracht hat?"
  },
  AvgDialog_45435_Content_38 = {
    Text = "Francis' Forschung beschränkt sich auf die Auflösung, und der Code in diesem Sanatorium wurde von dir eingerichtet."
  },
  AvgDialog_45435_Content_39 = {
    Text = "Diese Versuchssubjekte könnten sich unbemerkt in die Fabrik schleichen, während die Wachen nichts ahnen, aber sich bewegende Skelette sind eine gewaltige Aufgabe und können nicht lautlos bewegt werden."
  },
  AvgDialog_45435_Content_4 = {
    Text = "Lord Alva, ich habe sie eingeladen, die Überreste des Heiligen Baumes zu bewachen..."
  },
  AvgDialog_45435_Content_40 = {
    Text = "Wir können das Skelett nicht sehen. Es ist eine <Blue:Illusion>—diese Wand wurde um zwei Meter nach innen verschoben."
  },
  AvgDialog_45435_Content_41 = {
    Text = "Überhaupt nicht schlecht! Du hast dich seit dem letzten Mal, als wir uns trafen, als die Person, die ihre Teamkollegen im Stich gelassen und weggelaufen ist, stark verbessert."
  },
  AvgDialog_45435_Content_42 = {
    Text = "So, Casiah, deine Illusionen sind viel zu leicht zu zerstreuen."
  },
  AvgDialog_45435_Content_43 = {
    Text = "Hmph, du bekommst, wofür du bezahlst. Mythags Feldagenten sind alle emotional stabile Leute, aber sie verdienen nicht viel Geld."
  },
  AvgDialog_45435_Content_44 = {
    Text = "Fortgeschrittenere Lösungen sind auch möglich, wie zum Beispiel Lady Narzisse zu bitten, einen Weg zu öffnen, um diesen kleinen abgenutzten Sarg leicht herauszubekommen, aber..."
  },
  AvgDialog_45435_Content_45 = {Text = "Mmh-hmm?"},
  AvgDialog_45435_Content_46 = {
    Text = "Es wird mehr Geld benötigt!"
  },
  AvgDialog_45435_Content_47 = {
    Text = "Lady Daffodil ist sich meiner finanziellen Situation wohl bewusst. Wenn sie mich völlig ausbluten lässt, würde sie nicht einen regelmäßigen Kunden verlieren?"
  },
  AvgDialog_45435_Content_48 = {
    Text = "Ein langsamer und stetiger Fluss sichert langfristigen Erfolg, oder?"
  },
  AvgDialog_45435_Content_49 = {
    Text = "Ähem, wie wäre es, wenn wir über den Preis sprechen, nachdem diese Angelegenheit geklärt ist?"
  },
  AvgDialog_45435_Content_5 = {
    Text = "Also, könnten sie meine Soldaten fesseln und sie nach dem Standort der heiligen Baumreste verhören?"
  },
  AvgDialog_45435_Content_50 = {
    Text = "Ryker warf die Würfel in seiner Hand und warf sie kräftig—"
  },
  AvgDialog_45435_Content_51 = {
    Text = "Ein magischer Hut flog hoch, fing die rasenden Würfel ein und kehrte dann zu seinem Besitzer zurück.\nCasiah schüttelte den Hut, und die zerdrückten Würfel fielen als feiner Staub heraus."
  },
  AvgDialog_45435_Content_52 = {
    Text = "Du siehst, sie werden dich auch nicht leicht davonkommen lassen."
  },
  AvgDialog_45435_Content_53 = {
    Text = "An alle an der Mythag-Universität, um unserer Alumni-Verbindung willen, lassen Sie uns einen Schritt zurücktreten, oder?"
  },
  AvgDialog_45435_Content_54 = {
    Text = "Ich bin hier wegen der Überreste des heiligen Baumes. Als Gesandter von Mythag möchtest du sicherlich <Yellow:die Verschmutzung der Überreste des heiligen Baumes beseitigen>, damit sie den heiligen Fluss nicht verschmutzt."
  },
  AvgDialog_45435_Content_55 = {
    Text = "Lass uns einen Deal abschließen: Die heiligen Baumreste gehen an mich, der Mutterbaum wird nicht wiederbelebt, und ihr alle kehrt nach Hause zurück. Ist das nicht eine Win-Win-Situation?"
  },
  AvgDialog_45435_Content_56 = {
    Text = "<Yellow:Verschmutzung der Heiligen Baumreste>? Es scheint, dass Daffodil mehr darüber weiß, was sie an die Bildhauer verkauft hat, als wir."
  },
  AvgDialog_45435_Content_57 = {
    Text = "In diesem Fall dürfen wir die Überreste des Heiligen Baumes auf keinen Fall übergeben."
  },
  AvgDialog_45435_Content_58 = {
    Text = "Lass uns Casiahs Zaubershow früher beginnen lassen!"
  },
  AvgDialog_45435_Content_6 = {
    Text = "Indem du an das Monster denkst, dem du gerade begegnet bist, hatte dich ein plötzlicher Einfall getroffen."
  },
  AvgDialog_45435_Content_7 = {
    Text = "Gerade sahen wir Herbert, den Chef der Bildhauer, die Fabrik betreten, wo die Überreste des Heiligen Baumes sind, die sich hier befinden."
  },
  AvgDialog_45435_Content_8 = {
    Text = "Herbert sucht nach besonderen Relikten aus egoistischen Motiven. Wir vermuten, dass er die Macht der Überreste des Heiligen Baumes begehrt."
  },
  AvgDialog_45435_Content_9 = {
    Text = "In der Eile zwangen wir die Soldaten, den Standort des Skeletts preiszugeben, aber es war zu spät"
  },
  AvgDialog_45436_Content_1 = {Text = "Glut"},
  AvgDialog_45436_Content_2 = {
    Text = "Warum... das Skelett des Heiligen Baumes ist noch hier..."
  },
  AvgDialog_45436_Content_3 = {
    Text = "Hast du es nicht herausgefunden? Das sogenannte Mutterbaum-Skelett ist nur eine Tarnung."
  },
  AvgDialog_45436_Content_4 = {
    Text = "Was wir wirklich brauchen, sind nur „Boten aus der Ferne“ und „Der Caro der Arams“."
  },
  AvgDialog_45436_Content_5 = {
    Text = "Jetzt haben die törichten Gesandten die Sturmwand für mich geöffnet, und die Aram haben das Flusswasser getrunken, das mit Laternenasche vermischt ist."
  },
  AvgDialog_45436_Content_6 = {
    Text = "Meine große Vision ist auf Kurs; es bleibt nur noch, auf das Wachstum des Mutterbaums zu warten."
  },
  AvgDialog_45436_Content_7 = {
    Text = "Ah, ich kann es kaum erwarten, das Land zu sehen, das von Auflösung bedeckt ist und die Tore des Gottesreichs weit offen..."
  },
  AvgDialog_45437_Content_1 = {Text = "Halskette"},
  AvgDialog_45437_Content_10 = {
    Text = "Die Menge hat sich noch nicht aufgelöst."
  },
  AvgDialog_45437_Content_11 = {
    Text = "In Ordnung, jeder zurück zu seinen Aufgaben."
  },
  AvgDialog_45437_Content_12 = {
    Text = "Wir brechen in zwei Tagen zum Sturmwall auf. Ich brauche auch eine gute Ruhe!"
  },
  AvgDialog_45437_Content_13 = {
    Text = "Wir reinigen den Raum jeden Tag und warten nur auf deine Rückkehr. Wir haben bereits jemanden arrangiert, um das schlaffördernde Räucherstäbchen anzuzünden. Möge der Mutterbaum dir friedliche Träume schenken."
  },
  AvgDialog_45437_Content_14 = {
    Text = "In einer unauffälligen Ecke sprang Thais aus dem Sarg und fügte sich mühelos in die Menge ein."
  },
  AvgDialog_45437_Content_15 = {
    Text = "Hast du bemerkt, wohin die Überreste des Heiligen Baumes gegangen sind?"
  },
  AvgDialog_45437_Content_16 = {
    Text = "Ich habe die Hüter die ganze Zeit über Wache halten lassen."
  },
  AvgDialog_45437_Content_17 = {
    Text = "Warte, wo ist der Hüter?"
  },
  AvgDialog_45437_Content_18 = {
    Text = "Entschuldigen Sie, bitte machen Sie Platz."
  },
  AvgDialog_45437_Content_19 = {
    Text = "Du läufst um zwei Ecken, drängst dich durch die drängende Menge und suchst nach dieser Figur."
  },
  AvgDialog_45437_Content_2 = {
    Text = "Der Markt vor uns... Es sind so viele Leute da!"
  },
  AvgDialog_45437_Content_20 = {
    Text = "Die Frustration über den Verlust der Spur steigt auf, und du bereitest dich widerwillig darauf vor, zum Team zurückzukehren, nur um Thais zu entdecken, die im Schatten hinter einem kleinen Gebäude steht, lächelnd und dir zuwinkt."
  },
  AvgDialog_45437_Content_21 = {
    Text = "Suchst du nach mir?"
  },
  AvgDialog_45437_Content_22 = {
    Text = "Du folgst Thais, die unerwartet leise durch die Straßen geht."
  },
  AvgDialog_45437_Content_23 = {
    Text = "Vorbei an einem Stand voller Kleinigkeiten, blieb sie schließlich stehen, drehte sich um, beugte sich vor und flüsterte dir ins Ohr."
  },
  AvgDialog_45437_Content_24 = {
    Text = "Kannst du mir das geben?"
  },
  AvgDialog_45437_Content_25 = {
    Text = "Du folgst ihrem Blick und siehst einen Metallkragen."
  },
  AvgDialog_45437_Content_26 = {
    Text = "Guter Blick, Gast! Möchtest du dir diesem Kragen ansehen?"
  },
  AvgDialog_45437_Content_27 = {
    Text = "Das wurde persönlich von meiner Tochter gefertigt. Besonders der lapislazuli in der Mitte, mit seiner gleichmäßigen Textur und zarten Farbe – du kannst definitiv seine Qualität erkennen!"
  },
  AvgDialog_45437_Content_28 = {
    Text = "Kein Lapislazuli."
  },
  AvgDialog_45437_Content_29 = {
    Text = "<Willst du keinen Lapis Lazuli?>"
  },
  AvgDialog_45437_Content_3 = {
    Text = "Bote! Das Team des Boten ist zurückgekehrt!"
  },
  AvgDialog_45437_Content_30 = {
    Text = "Huh? Lapislazuli ist der abschließende Touch der Halskette. Bist du dir sicher, dass du ihn nicht haben möchtest?"
  },
  AvgDialog_45437_Content_31 = {
    Text = "Durch das Hinzufügen dieses Lapislazuli wird das Budget, das Mythag für Sie vorbereitet hat, bis zur Grenze belastet."
  },
  AvgDialog_45437_Content_32 = {
    Text = "Hmm, kein Lapislazuli erforderlich."
  },
  AvgDialog_45437_Content_33 = {
    Text = "In Ordnung, lass uns das für diesen Kunden abschließen."
  },
  AvgDialog_45437_Content_34 = {
    Text = "Du und Thais verlasst das Dorf und seht nur endlose Sandstürme und ein paar Geier, die den Himmel überqueren und ihre krächzenden Schreie hinterlassen."
  },
  AvgDialog_45437_Content_35 = {
    Text = "Die Handwerkskunst der Kara-Familie wird über Generationen weitergegeben und bleibt exquisit."
  },
  AvgDialog_45437_Content_36 = {
    Text = "Sie berührt sanft die Gravuren am Kragen, dann dreht sie den Edelsteinhänger um, um ihn dir zu zeigen."
  },
  AvgDialog_45437_Content_37 = {
    Text = "Dieses Muster ist das Symbol des Mutterbaums, und es wurde mit meiner eigenen Hand gezeichnet."
  },
  AvgDialog_45437_Content_38 = {
    Text = "O Bote aus der Ferne, könntest du mir helfen, diese Halskette anzulegen?"
  },
  AvgDialog_45437_Content_39 = {
    Text = "Du nimmst gehorsam den Kragen, und Thais senkt leicht ihren Kopf, sodass dein Arm um ihren Kopf und Hals kreisen kann, atmen in der Nähe."
  },
  AvgDialog_45437_Content_4 = {
    Text = "Die Dorfbewohner füllten die engen Straßen und hielten Gaben für Juliette hoch."
  },
  AvgDialog_45437_Content_40 = {
    Text = "Ein edelsteinartiger Stein, der weißen Jade ähnelt, ist in der Mitte des Anhängers eingelassen. Unter seinem glänzenden weißen Farbton ist ein schwacher Hauch von lebendigem Rot zu sehen, erinnernd an das Erröten eines schüchternen Mädchens, das genau den richtigen Hauch von Charme ausstrahlt."
  },
  AvgDialog_45437_Content_41 = {
    Text = "Klar, ich mag es. Im Gegenzug für dieses Geschenk werde ich deine Fragen beantworten, in Ordnung?\nDu musst viele Fragen haben, oder?"
  },
  AvgDialog_45437_Content_42 = {
    Text = "Jedoch sind zuvor einige böswillige Individuen eingetroffen. Lass uns diese taktlosen kleinen Monster zusammen bestrafen, einverstanden?"
  },
  AvgDialog_45437_Content_5 = {
    Text = "Ein Geschenk für den Gesandten!"
  },
  AvgDialog_45437_Content_6 = {
    Text = "Am Ende des Teams saß Thais gemütlich auf dem Sarg, getragen von vier Aram-Kriegern."
  },
  AvgDialog_45437_Content_7 = {
    Text = "Im Vergleich zu dem warmen Empfang, den Juliette erhielt, machten die spärlichen Jubelrufe den Titel der Königin unwürdig."
  },
  AvgDialog_45437_Content_8 = {
    Text = "Danke euch allen. Die sengende Sonne prüft jeden Reisenden, der den Wüstenboden betritt, und eure Begeisterung ist so unvergesslich wie das Wasser des Heiligen Flusses."
  },
  AvgDialog_45437_Content_9 = {
    Text = "Ich glaube, jeder ist erschöpft. Bitte kehren Sie in Ihre jeweiligen Homes zurück und genießen Sie eine ruhige Nacht."
  },
  AvgDialog_45438_Content_1 = {
    Text = "Juliette... Warum..."
  },
  AvgDialog_45438_Content_2 = {
    Text = "An diesem Punkt gibt es nichts mehr, wovor man Angst haben müsste."
  },
  AvgDialog_45438_Content_3 = {
    Text = "Die Aram handeln das Blut der Deformierten für das Überleben ihres Volkes. Deine Existenz ist Schmutz und Sünde."
  },
  AvgDialog_45438_Content_4 = {
    Text = "Geboren mit der Erbsünde, sind sie nur geeignet, zu Zunder für das Fundament des Göttlichen Reiches zu werden."
  },
  AvgDialog_45438_Content_5 = {
    Text = "Und das wertvollste Kind ist bereits in meinem Besitz, dazu bestimmt, ein qualifizierter Anwärter für die neue Welt zu werden."
  },
  AvgDialog_45438_Content_6 = {
    Text = "Ein Hund mit einem menschlichen Gesicht liegt vor Alva geduckt."
  },
  AvgDialog_45438_Content_7 = {
    Text = "Gut, so wie man es vom Auserwählten erwartet."
  },
  AvgDialog_45438_Content_8 = {
    Text = "Nefer... Rure..."
  },
  AvgDialog_45438_Content_9 = {
    Text = "Gehe, Kind, zerschmettere deine Feinde, um die Wiedergeburt des Mutterbaums zu schützen."
  },
  AvgDialog_45439_Content_1 = {
    Text = "Was verursacht diesen ganzen Tumult?"
  },
  AvgDialog_45439_Content_10 = {
    Text = "Welche Beweise hast du?"
  },
  AvgDialog_45439_Content_11 = {
    Text = "Der grausige Anblick von Williams Tod erscheint vor dir.\nEr wurde von einem bösartigen Monster getötet, das eng mit der Tempellichtkirche verbunden ist."
  },
  AvgDialog_45439_Content_12 = {
    Text = "Aber Juliette zu beschuldigen... du hast keine Beweise."
  },
  AvgDialog_45439_Content_13 = {
    Text = "Bitte nehmen Sie sich einen Moment Zeit, um sich an die Tage zu erinnern, die ich mit Ihnen verbracht habe."
  },
  AvgDialog_45439_Content_14 = {
    Text = "Wirst du %seinoderihr% Unsinn glauben?"
  },
  AvgDialog_45439_Content_15 = {
    Text = "Zweifelnde Stimmen erheben sich nacheinander, ohne Vertrauen in dich."
  },
  AvgDialog_45439_Content_16 = {
    Text = "%player%, ich bin zutiefst traurig. Bis jetzt habe ich dir vertraut, deine Unhöflichkeit in Aran übersehen und sogar beim Häuptling für dich geworben."
  },
  AvgDialog_45439_Content_17 = {
    Text = "Es scheint, ich habe dich falsch eingeschätzt."
  },
  AvgDialog_45439_Content_18 = {
    Text = "Lord Alva, bitte verzeihen Sie meinen Fehler."
  },
  AvgDialog_45439_Content_19 = {
    Text = "Egal wie dein Streit mit Juliette gelöst wird, das heutige Ritual muss bis zum Ende durchgeführt werden."
  },
  AvgDialog_45439_Content_2 = {
    Text = "Die Menge machte einen Weg frei."
  },
  AvgDialog_45439_Content_20 = {
    Text = "Jeder, der die Wiedergeburt des Mutterbaums behindert, wird ein Opfer auf seinem Weg zur Wiederauferstehung!"
  },
  AvgDialog_45439_Content_3 = {
    Text = "Bist du das?"
  },
  AvgDialog_45439_Content_4 = {
    Text = "Ja, wir haben wichtige Angelegenheiten zu berichten."
  },
  AvgDialog_45439_Content_5 = {
    Text = "Juliette... hat dich die ganze Zeit über getäuscht."
  },
  AvgDialog_45439_Content_6 = {
    Text = "Sie ist nicht der legendäre Bote, noch hat sie die göttliche Macht, den Mutterbaum wiederzubeleben"
  },
  AvgDialog_45439_Content_7 = {
    Text = "Sie konnte nicht einmal Zugang zur Sturmwand erhalten, da sie von Königin Thais gebaut wurde, um diejenigen mit abweichenden Absichten auszusperren!"
  },
  AvgDialog_45439_Content_8 = {
    Text = "Du schaust dich um und siehst Juliette an der Spitze der Menge stehen. Deine Worte scheinen keinen Einfluss auf sie zu haben."
  },
  AvgDialog_45439_Content_9 = {
    Text = "Hast du Beweise, um diese Anschuldigung zu stützen?"
  },
  AvgDialog_45440_Content_1 = {
    Text = "Lady Juliette... wird... mich... belohnen... richtig...?"
  },
  AvgDialog_45440_Content_2 = {
    Text = "Mm-hmm, gutes Kind, du warst eine große Hilfe."
  },
  AvgDialog_45440_Content_3 = {
    Text = "Der Mutterbaum... hat bereits begonnen, Gestalt anzunehmen."
  },
  AvgDialog_45441_Content_1 = {Text = "Rivale"},
  AvgDialog_45441_Content_2 = {
    Text = "Ryker trat gegen die verrostete Eisentür und ließ Staub aufwirbeln."
  },
  AvgDialog_45441_Content_3 = {
    Text = "Ein seltsames, doch vertrautes Brüllen, begleitet vom Geräusch knisternder Knochen, hallt aus allen Richtungen."
  },
  AvgDialog_45441_Content_4 = {
    Text = "Habe ich das richtig gesehen? Sind das die modifizierten Proben von den Bildhauern?"
  },
  AvgDialog_45441_Content_5 = {
    Text = "Ich habe es auch gesehen."
  },
  AvgDialog_45441_Content_6 = {
    Text = "Es ist ein Nahkampf. Ich spüre etwas Unheilvolles."
  },
  AvgDialog_45441_Content_7 = {
    Text = "Das Skelett des Mutterbaums liegt tief drinnen, in der Nähe des Fensters!"
  },
  AvgDialog_45441_Content_8 = {
    Text = "Lass uns weitermachen, sonst könnte er in die Hose machen."
  },
  AvgDialog_45442_Content_1 = {Text = "Traum"},
  AvgDialog_45442_Content_10 = {
    Text = "Das wird nicht gehen, Alva."
  },
  AvgDialog_45442_Content_100 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45442_Content_101 = {
    Text = "Ich habe einen tiefen, sehnsüchtigen Seufzer gehört."
  },
  AvgDialog_45442_Content_102 = {
    Text = "Letztlich ist die Puppe nicht perfekt, sie erfordert zu viel Kontrolle"
  },
  AvgDialog_45442_Content_103 = {
    Text = "Je stärker deine Entschlossenheit ist, für Arlan zu opfern, desto heftiger ist dein Widerstand, sobald die Wahrheit ans Licht kommt."
  },
  AvgDialog_45442_Content_104 = {
    Text = "Zum Glück habe ich diese Situation vorhergesehen"
  },
  AvgDialog_45442_Content_105 = {
    Text = "Die Zeit ist fast um, ihr alle, für euren geliebten Mutterbaum"
  },
  AvgDialog_45442_Content_106 = {
    Text = "Bringt Fleisch und Leben dar"
  },
  AvgDialog_45442_Content_107 = {
    Text = "Ich öffnete den Mund, konnte keinen Ton herausbringen.\nAlles um mich herum erstarrte vor Angst"
  },
  AvgDialog_45442_Content_108 = {
    Text = "Nein, die Welt steht nicht still, sondern meine Wahrnehmung, jedes Blinzeln scheint ein Jahrhundert zu dauern"
  },
  AvgDialog_45442_Content_109 = {
    Text = "In der stagnierenden und endlosen Reihenfolge marschierten nur meine ehemaligen Kameraden, nacheinander, die Yalan-Soldaten, in Richtung des Heiligen Flusses."
  },
  AvgDialog_45442_Content_11 = {
    Text = "Wie wäre es damit: <Blue:Haleman> hat gerade eine Einladung geschickt. Sie hat hervorragenden Wein vorbereitet und mich eingeladen, ihn zu probieren."
  },
  AvgDialog_45442_Content_110 = {Text = "Platsch—"},
  AvgDialog_45442_Content_111 = {
    Text = "Die Welt erlangte wieder Klang und Farbe"
  },
  AvgDialog_45442_Content_112 = {
    Text = "Einer nach dem anderen sprangen sie entschlossen in die reißenden Fluten des heiligen Flusses, streckten ihre Arme aus und umarmten den vertrockneten Stamm des Mutterbaums"
  },
  AvgDialog_45442_Content_113 = {
    Text = "Sie schreien wie besessen, erzeugen unbeschreibliche wahnhaften Geschrei"
  },
  AvgDialog_45442_Content_114 = {
    Text = "Ihre Haut wird schlaff wie weicher Schlamm; ihre Körperflüssigkeiten verlassen den Körper und bilden den heiligen Fluss"
  },
  AvgDialog_45442_Content_115 = {
    Text = "Ihre Knochen scheinen wie Fleisch zu erweichen; die Gliedmaßen winden, dehnen und verweben sich auf unhumane Weise und bilden aus ihrem eigenen Blut und Fleisch den massiven, fetten Stamm des heiligen Baumes"
  },
  AvgDialog_45442_Content_116 = {
    Text = "Sie verschmelzen langsam und schmerzhaft mit dem heiligen Baum"
  },
  AvgDialog_45442_Content_12 = {
    Text = "Wie wäre es, wenn du und ich zusammen gehen und bis zum Besoffensein trinken?"
  },
  AvgDialog_45442_Content_13 = {
    Text = "Lady Thais, ich fürchte..."
  },
  AvgDialog_45442_Content_14 = {
    Text = "Soldaten folgen Befehlen – das hast du gesagt."
  },
  AvgDialog_45442_Content_15 = {
    Text = "Mein Befehl lautet: Keine Ruhe, bis ich betrunken bin."
  },
  AvgDialog_45442_Content_16 = {
    Text = "Gibt es eine Utopie ohne Blut und Tränen?"
  },
  AvgDialog_45442_Content_17 = {
    Text = "Ich hätte niemals gedacht – du erscheinst so starr, doch du beherbergst so unschuldige Träume in dir."
  },
  AvgDialog_45442_Content_18 = {
    Text = "Lady Thais, zieh mich nicht auf..."
  },
  AvgDialog_45442_Content_19 = {
    Text = "Wie könnte ich über dich lachen?"
  },
  AvgDialog_45442_Content_2 = {
    Text = "Alva, du bist jetzt schon eine Weile bestellt worden. Abgesehen von Morgengymnastik und Arbeit hast du sogar die Einladung zum Abendessen von Karune beim letzten Mal abgelehnt."
  },
  AvgDialog_45442_Content_20 = {
    Text = "Mit meinen Knochen und meinem Blut nähre ich ganz Lemvah, damit Arams Blutlinie weiterfließt."
  },
  AvgDialog_45442_Content_21 = {
    Text = "Unendliche Blutlinien reproduzieren sich und hoffen, dass einer dem Blick des Meisters entkommt und meinen Willen im Zyklus von Anfang und Ende fortführt..."
  },
  AvgDialog_45442_Content_22 = {
    Text = "Sind wir nicht beide equally naiv und lächerlich?"
  },
  AvgDialog_45442_Content_23 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45442_Content_24 = {
    Text = "Schläfst du?"
  },
  AvgDialog_45442_Content_25 = {
    Text = "Alright. Du warst nie Teil des Aram-Rasse, und du solltest nicht in dieser öden Wüste gefangen sein."
  },
  AvgDialog_45442_Content_26 = {
    Text = "Wenn mein Leben zu Ende geht, verlasse Remvashi und finde einen neuen Auftragnehmer."
  },
  AvgDialog_45442_Content_27 = {
    Text = "Dieser Tag... rückt näher."
  },
  AvgDialog_45442_Content_28 = {
    Text = "Ich sitze im Zelt der Königin, draußen hallen die Trauerwälle mit durchdringendem Schmerz, Trauer und Widerwillen wider."
  },
  AvgDialog_45442_Content_29 = {
    Text = "In der Lage zu sein, für jemanden zu weinen, dem man vertraut, ist eine Art Segen.\nAuf dem Schlachtfeld haben wir normalerweise nicht die Möglichkeit, gefallene Kameraden zu betrauern."
  },
  AvgDialog_45442_Content_3 = {
    Text = "Möchten Sie nicht eine Belohnung?"
  },
  AvgDialog_45442_Content_30 = {
    Text = "Was mich mehr besorgt, ist, wohin die Aram nach dem Verlust ihrer Königin gehen sollten.\nWenn die Aram aus Trauer aufhören zu denken, werde ich für sie denken."
  },
  AvgDialog_45442_Content_31 = {
    Text = "Lady Thais vertraut mir nicht. Das habe ich immer gewusst."
  },
  AvgDialog_45442_Content_32 = {
    Text = "Die Aram bestimmen Verwandtschaft nach Blut; für sie bin ich, mit fremdem Blut, immer ein Außenseiter gewesen."
  },
  AvgDialog_45442_Content_33 = {
    Text = "Aber die Aram brauchen einen Führer, sowohl spirituell als auch in der Realität."
  },
  AvgDialog_45442_Content_34 = {
    Text = "Ich werde die Rolle des Häuptlings übernehmen und das Grab von Lady Thais bewachen."
  },
  AvgDialog_45442_Content_35 = {
    Text = "Jeder Schritt in die Zukunft des Aran-Stammes wird unter dem wachsamen Auge von <Red:Lady Thais> stehen."
  },
  AvgDialog_45442_Content_36 = {
    Text = "Die Zukunft des Aran-Stammes wird unter dem wachsamen Auge von <Red:Seiner Majestät der Königin> voranschreiten."
  },
  AvgDialog_45442_Content_37 = {
    Text = "Die Zukunft des Yalan-Volkes wird unter dem wachsamen Auge von <Red:@1 Meister> voranschreiten."
  },
  AvgDialog_45442_Content_38 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45442_Content_39 = {
    Text = "Warum bin ich hier?"
  },
  AvgDialog_45442_Content_4 = {
    Text = "Solange Aran stabil und wohlhabend bleibt, ist das die größte Belohnung für mich, Lady Thais."
  },
  AvgDialog_45442_Content_40 = {
    Text = "Das Ding in diesem Sarg... Oh richtig, es waren die Überreste des Heiligen Baumes."
  },
  AvgDialog_45442_Content_41 = {
    Text = "Warum befinden sich die Überreste des Heiligen Baumes im Zelt der Königin?"
  },
  AvgDialog_45442_Content_42 = {
    Text = "Kümmere dich nicht, ich kann mich nicht erinnern."
  },
  AvgDialog_45442_Content_43 = {
    Text = "Aber das macht nichts."
  },
  AvgDialog_45442_Content_44 = {
    Text = "<Big: Solange der Mutterbaum wiedergeboren wird, <Red:alles> wird gut sein.>"
  },
  AvgDialog_45442_Content_45 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45442_Content_46 = {
    Text = "Über die Jahrhunderte habe ich viele Nachfolger ausgebildet."
  },
  AvgDialog_45442_Content_47 = {
    Text = "Ich glaube, ein Held wird den Morgen nach Yalan bringen."
  },
  AvgDialog_45442_Content_48 = {
    Text = "Der erste Nachfolger starb an Schlangengift."
  },
  AvgDialog_45442_Content_49 = {
    Text = "Der zweite Nachfolger starb im Sturm."
  },
  AvgDialog_45442_Content_5 = {
    Text = "Du magst Alan überhaupt nicht, oder? Du wirst nicht einmal an der Lagerfeuerversammlung teilnehmen."
  },
  AvgDialog_45442_Content_50 = {
    Text = "Der dritte Nachfolger starb durch den Neid anderer."
  },
  AvgDialog_45442_Content_51 = {
    Text = "Die Wüste ist voller unerwarteter Ereignisse und Variablen. Die Art, die am längsten in der Wüste überlebt, ist nicht der furchtlose hochgekrönte Adler oder die giftige Wüstenhornschlange, sondern die silberne Ameise, die nur zehn Minuten am Tag aktiv ist."
  },
  AvgDialog_45442_Content_52 = {
    Text = "Hoffnung in eine Einzelperson zu setzen, ist für Yalan viel zu töricht."
  },
  AvgDialog_45442_Content_53 = {
    Text = "Das Tempo des Bevölkerungsrückgangs wartet auf niemanden.\nNur ein unerwarteter Sturm kann mehrere Teams hinwegfegen."
  },
  AvgDialog_45442_Content_54 = {
    Text = "An ihrem tiefsten Punkt schrumpfte Arans Team auf weniger als hundert Mitglieder."
  },
  AvgDialog_45442_Content_55 = {
    Text = "<Red: Wenn das so weitergeht, wird Aran von meiner Hand ausgelöscht.>"
  },
  AvgDialog_45442_Content_56 = {
    Text = "Morgen Nacht... Neustart des Lagerfeuer-Treffens."
  },
  AvgDialog_45442_Content_57 = {
    Text = "Auf der Party sangen und tranken sie fröhlich.\nBei Sonnenaufgang wurde ein Kind, das in einer Nacht empfangen wurde, geboren."
  },
  AvgDialog_45442_Content_58 = {
    Text = "Als ich das neugeborene Kind in meinen Armen hielt, stiegen mir Tränen in die Augen."
  },
  AvgDialog_45442_Content_59 = {
    Text = "Die Kraft des Mutterbaums ist ein Wunder, das Yalan von den Himmeln verliehen wurde. Doch aufgrund meines flachen und engstirnigen Verständnisses wies ich es törichterweise als Häresie zurück."
  },
  AvgDialog_45442_Content_6 = {
    Text = "Kümmere dich nicht um Diskussionen, ich durchschau es sofort.\nHier ist jeder ein wilder Wahnsinniger. Du passt nicht zu ihnen."
  },
  AvgDialog_45442_Content_60 = {Text = "Nur..."},
  AvgDialog_45442_Content_61 = {
    Text = "Die göttliche Kraft des Mutterbaums schwächt sich kontinuierlich."
  },
  AvgDialog_45442_Content_62 = {
    Text = "Immer mehr deformierte Feten."
  },
  AvgDialog_45442_Content_63 = {
    Text = "Ich bin am Ende meiner Kräfte, bis eine ältere Frau beiläufig erwähnt—"
  },
  AvgDialog_45442_Content_64 = {
    Text = "Erinnerst du dich immer noch an dieses Volkslied?"
  },
  AvgDialog_45442_Content_65 = {
    Text = "Der Tod naht, das Ende hat begonnen"
  },
  AvgDialog_45442_Content_66 = {
    Text = "Die Überreste der Mutter sind verschwunden, Blut und Samen treiben über das Land und werden von den neu geborenen Tieren verschlungen"
  },
  AvgDialog_45442_Content_67 = {
    Text = "Der Himmel ist mit dunklen Wolken bedeckt, bis die Botschafter aus dem fremden Land erscheinen"
  },
  AvgDialog_45442_Content_68 = {
    Text = "Der Heilige Fluss des Wiedergeborenen Mutterbaums krönt die Verstorbenen und bringt ihre Blutlinie zu Yalan zurück."
  },
  AvgDialog_45442_Content_69 = {
    Text = "Solange wir <Yellow:der Exil-Botschafter> finden, könnten wir die Wiedergeburt des Mutterbaums miterleben!"
  },
  AvgDialog_45442_Content_7 = {
    Text = "Aber findest du nicht, dass ein Leben, das ausschließlich für die Pflicht gelebt wird, langweilig ist?"
  },
  AvgDialog_45442_Content_70 = {
    Text = "Thais, Thais—!"
  },
  AvgDialog_45442_Content_71 = {
    Text = "Jemand ruft den Namen von jemandem."
  },
  AvgDialog_45442_Content_72 = {
    Text = "Kopfschmerz, unzählige silberne Nadeln durchbohren den Verstand, scharfe Geräusche zerreißen das Trommelfell, doch das Geräusch des Blutes, das durch die Venen fließt, bleibt klar hörbar."
  },
  AvgDialog_45442_Content_73 = {
    Text = "<Big:Thais, Thais—!>"
  },
  AvgDialog_45442_Content_74 = {
    Text = "Thais, wer ist das?"
  },
  AvgDialog_45442_Content_75 = {
    Text = "Lass dich nicht von dem Geräusch ablenken; es wird nur deinen Fokus stören."
  },
  AvgDialog_45442_Content_76 = {
    Text = "Der Mutterbaum steht kurz davor, zur Erde zurückzukehren. Bist du nicht erfreut?"
  },
  AvgDialog_45442_Content_77 = {
    Text = "Ich habe den Namen Thais irgendwo gehört."
  },
  AvgDialog_45442_Content_78 = {
    Text = "Aber wo genau ist das?"
  },
  AvgDialog_45442_Content_79 = {
    Text = "Das sich ständig verändernde Schlachtfeld in den Momenten vor dem Tod, das Lächeln der Kameraden am Rande des Vergehens, die kalten und herzlosen Reaktionen des Kommandanten...\nNein, keines davon."
  },
  AvgDialog_45442_Content_8 = {
    Text = "Lady Thais, du weißt.\nIch war in meinem früheren Leben ein Soldat. Soldaten folgen Befehlen."
  },
  AvgDialog_45442_Content_80 = {
    Text = "Erwacht zu täglicher Mühe, Bankette zu organisieren und gegen Bestienhorden zu kämpfen..."
  },
  AvgDialog_45442_Content_81 = {
    Text = "Erweckt...?"
  },
  AvgDialog_45442_Content_82 = {
    Text = "Wer hat mich erweckt?"
  },
  AvgDialog_45442_Content_83 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45442_Content_84 = {
    Text = "<Red:Thais.>"
  },
  AvgDialog_45442_Content_85 = {
    Text = "Warum habe ich ihren Namen vergessen?"
  },
  AvgDialog_45442_Content_86 = {
    Text = "Jeden einzelnen Tag rufe ich sie—"
  },
  AvgDialog_45442_Content_87 = {
    Text = "Aus dem Staub erschien die Gestalt, nach der ich Tag und Nacht gesehnt hatte."
  },
  AvgDialog_45442_Content_88 = {
    Text = "Jeder ihrer Schritte hinterlässt eine tiefe Spur auf der vom Wind erodierten Erde und weckt Wellen in meiner Brust, die mir Tränen in die Augen treiben."
  },
  AvgDialog_45442_Content_89 = {
    Text = "Lady Thais..."
  },
  AvgDialog_45442_Content_9 = {
    Text = [[
Du bist mein Linker.
Arlans Aufrechterhaltung ist dein Wunsch, und es ist auch meiner.]]
  },
  AvgDialog_45442_Content_90 = {
    Text = "Ich habe auf dich gewartet.\nIch wusste, dass du zurückkommen würdest. Du hast Yalan nie vergessen."
  },
  AvgDialog_45442_Content_91 = {
    Text = "Höret, alle Aran-Geschlechter! Die alte Prophezeiung ist wahr geworden; der Mutterbaum ist wieder erschienen, um die Verstorbenen zu krönen!"
  },
  AvgDialog_45442_Content_92 = {
    Text = "Die Königin kehrt im Sand zurück, um sich erneut auf den Thron zu setzen!"
  },
  AvgDialog_45442_Content_93 = {
    Text = "An die einzige Königin von Aran, Lady Thais—"
  },
  AvgDialog_45442_Content_94 = {
    Text = "Bringt eure Treue und euren Willen dar!"
  },
  AvgDialog_45442_Content_95 = {
    Text = "Ich habe endlich, endlich diesen Moment erreicht."
  },
  AvgDialog_45442_Content_96 = {
    Text = "So, könntest du mir jetzt ein Kompliment machen?"
  },
  AvgDialog_45442_Content_97 = {
    Text = "Gelobt sei meine Jahrhunderte währende Geduld, Jahrhunderte des Durchhaltens und Jahrhunderte, in denen ich endlich den Boten fand, um den Mutterbaum wiederzubeleben—"
  },
  AvgDialog_45442_Content_98 = {
    Text = "Lass uns gemeinsam daran arbeiten, Yalan zu einer Utopie ohne Blut und Tränen, rein und makellos, zu machen."
  },
  AvgDialog_45442_Content_99 = {
    Text = "Ah, Lady Thais, warum schüttelst du den Kopf über mich?"
  },
  AvgDialog_45443_Content_1 = {Text = "Rückkehr"},
  AvgDialog_45443_Content_10 = {
    Text = "Allein, du brauchst Gefährten, die dich unterstützen—das Gesicht von Thais erscheint vor dir."
  },
  AvgDialog_45443_Content_11 = {
    Text = "Alles, was du tun musst, ist, mir vollkommen zu vertrauen.\nVertraue der Königin von Aran."
  },
  AvgDialog_45443_Content_12 = {
    Text = "Sie wird dein Vertrauen sicher in gleichem Maße zurückgeben."
  },
  AvgDialog_45443_Content_13 = {
    Text = "Thais? Wer?"
  },
  AvgDialog_45443_Content_14 = {
    Text = "Wer sonst? Deine Königin Thais!"
  },
  AvgDialog_45443_Content_15 = {
    Text = "Bist du verrückt? Wenn du Ihre Majestät sehen möchtest, schneide dir mit dieser Klinge die Kehle durch!"
  },
  AvgDialog_45443_Content_16 = {
    Text = "Königin... Was ist los?"
  },
  AvgDialog_45443_Content_17 = {
    Text = "Was gibt es sonst zu sagen? Ihre Majestät die Königin ist seit Jahrhunderten verstorben. Wenn du noch einmal respektlos sprichst, werde ich nicht zurückhalten!"
  },
  AvgDialog_45443_Content_18 = {
    Text = "Als du seinen ernsten Gesichtsausdruck siehst, sinkt dein Herz, als würde es in eine Eishöhle fallen."
  },
  AvgDialog_45443_Content_19 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45443_Content_2 = {
    Text = "Fast tausend Aram-Leute versammelten sich am Heiligen Fluss, ihre tiefen Gesänge vermischten sich mit den fernen Tierheulen zu einer Symphonie des Chaos."
  },
  AvgDialog_45443_Content_20 = {
    Text = "Du blickst in die Ferne, zum Zentrum des Rituals."
  },
  AvgDialog_45443_Content_21 = {
    Text = "Der Sarg lag ruhig auf dem hohen Holzalter.\nNatürlich gab es keine Spur von Thais, die du zuvor gesehen hattest."
  },
  AvgDialog_45443_Content_22 = {
    Text = "Nicht nur dort.\nNirgendwo überhaupt."
  },
  AvgDialog_45443_Content_23 = {
    Text = "Der Vorhang des Zeltes wurde beiseite geschoben, und eine sternengesehene Aran-Frau in ihren späten Dreißigern trat in das Zelt ein."
  },
  AvgDialog_45443_Content_24 = {
    Text = "Thais springt hastig zurück auf den Sarg, nimmt eine würdevoll Haltung ein, wie eine arrogante Königin auf ihrem Thron."
  },
  AvgDialog_45443_Content_25 = {
    Text = "Lieber Gast..."
  },
  AvgDialog_45443_Content_26 = {
    Text = "<Red: Ihr betroffener Ton wurde abrupt vom Neuankömmling unterbrochen.>"
  },
  AvgDialog_45443_Content_27 = {
    Text = "Natürlich würde Alva die Erklärung der Königin nicht „unterbrechen“."
  },
  AvgDialog_45443_Content_28 = {
    Text = "Bote! Das Team des Boten ist zurückgekehrt!"
  },
  AvgDialog_45443_Content_29 = {
    Text = "Die Dorfbewohner füllten die engen Straßen und hielten Gaben für Juliette hoch."
  },
  AvgDialog_45443_Content_3 = {
    Text = "Ein massiver Holzaltar steht mitten in der Menge, auf ihm ein mit geheimnisvollen Symbolen gravierter Sarg. Die umgebenden Blicke sind eine Mischung aus Angst, Fanatismus und Erwartung."
  },
  AvgDialog_45443_Content_30 = {
    Text = "Am Ende des Teams saß Thais gemütlich auf dem Sarg, getragen von vier Aram-Kriegern."
  },
  AvgDialog_45443_Content_31 = {
    Text = "Im Vergleich zu dem warmen Empfang, den Juliette erhielt, <Red: machten die spärlichen Jubelrufe den Titel der Königin unwürdig>."
  },
  AvgDialog_45443_Content_32 = {
    Text = "In den Augen aller Menschen gibt es keine Königin, die auf dem Skelett sitzt."
  },
  AvgDialog_45443_Content_33 = {
    Text = "Kannst du mir das geben?"
  },
  AvgDialog_45443_Content_34 = {
    Text = "Du folgst ihrem Blick und siehst einen Metallkragen."
  },
  AvgDialog_45443_Content_35 = {
    Text = "Guter Blick, Gast! Möchtest du dir diesem Kragen ansehen?"
  },
  AvgDialog_45443_Content_36 = {
    Text = "Das hat meine Tochter von Hand gemacht. Besonders der lapislazuli in der Mitte, mit seiner gleichmäßigen Textur und feinen Farbe – du, mit deinem scharfen Auge, musst es bemerkt haben!"
  },
  AvgDialog_45443_Content_37 = {
    Text = "Kein Lapislazuli."
  },
  AvgDialog_45443_Content_38 = {
    Text = "<Willst du keinen Lapis Lazuli?>"
  },
  AvgDialog_45443_Content_39 = {
    Text = "Huh? Bist du dir sicher, dass du keinen Lapislazuli willst?"
  },
  AvgDialog_45443_Content_4 = {
    Text = "Sobald du eintrittst, begegnest du einem strengen Widerstand."
  },
  AvgDialog_45443_Content_40 = {
    Text = "Durch das Hinzufügen dieses Lapislazuli wird das Budget, das Mythag für Sie vorbereitet hat, bis zur Grenze belastet."
  },
  AvgDialog_45443_Content_41 = {
    Text = "Hmm, kein Lapislazuli erforderlich."
  },
  AvgDialog_45443_Content_42 = {
    Text = "Alright, erledige es für <Red:diesen Kunden>."
  },
  AvgDialog_45443_Content_43 = {
    Text = "Der Verkäufer reagiert nur auf deine Worte."
  },
  AvgDialog_45443_Content_44 = {
    Text = "Auf einer nahen Düne siehst du die Silhouette"
  },
  AvgDialog_45443_Content_45 = {
    Text = "Sie erkennen die Silhouette. Es ist Thais."
  },
  AvgDialog_45443_Content_46 = {
    Text = "Der Sturm... ist er kleiner geworden?"
  },
  AvgDialog_45443_Content_47 = {
    Text = "Sie sang unbekannte Gebete, ließ den wilden Wind ihren Schleier aufwirbeln und ging langsam und sicher in den dunklen Sandsturm"
  },
  AvgDialog_45443_Content_48 = {
    Text = "Ohrenbetäubender Lärm, doch das Gebet ist klar zu hören, als würde es in deinem Schädel widerhallen"
  },
  AvgDialog_45443_Content_49 = {
    Text = "Im tobenden Wüstensturm sprach sie ruhig mit einer Kreatur der Wüste"
  },
  AvgDialog_45443_Content_5 = {Text = "Wer da?!"},
  AvgDialog_45443_Content_50 = {
    Text = "Es ist die Königin! Die Königin ist gekommen, um uns zu retten, um Arlan zu retten!"
  },
  AvgDialog_45443_Content_51 = {
    Text = "Alans Team, das verzweifelt zu entkommen versucht hatte, kam plötzlich zum Stillstand."
  },
  AvgDialog_45443_Content_52 = {
    Text = "Unzählige Aram knien ehrfürchtig in Richtung der Thais"
  },
  AvgDialog_45443_Content_53 = {
    Text = [[
Aber am Ende ihrer Anbetungsrichtung...
liegt nichts; nur du kannst Thais' Kleid im sandigen Wind wehen sehen.]]
  },
  AvgDialog_45443_Content_54 = {
    Text = "Als Trägerin der Essenz des Wunsches muss der Mutterbaum einen tiefgreifenden Eindruck auf den Planeten hinterlassen haben."
  },
  AvgDialog_45443_Content_55 = {
    Text = "Die Widerstandsfähigkeit des Mutterbaums verlangsamt seine Erosionsrate um das Tausendfache"
  },
  AvgDialog_45443_Content_56 = {
    Text = "So, <Red:zu dir, ist sie noch nicht vollständig verschwunden>."
  },
  AvgDialog_45443_Content_57 = {
    Text = "In hundert oder tausend Jahren könnte <Red:Aram sogar das Dasein des Mutterbaums vergessen>."
  },
  AvgDialog_45443_Content_58 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_45443_Content_59 = {
    Text = "Sie sahen Königin Thais niemals; was sie glaubten und anbeteten, war lediglich das illusorische Ding, das durch Mundpropaganda überliefert wurde."
  },
  AvgDialog_45443_Content_6 = {
    Text = "Es ist der kritische Moment des Rituals. Unbefugte Personen dürfen nicht eintreten!"
  },
  AvgDialog_45443_Content_60 = {
    Text = "Die Thais, die dir die Gegend zeigten, für dich tanzten und auf dem Sarg posierten <Red:existierten niemals in ihren Augen>."
  },
  AvgDialog_45443_Content_61 = {
    Text = "Aber du bist dir sicher, absolut sicher—"
  },
  AvgDialog_45443_Content_62 = {
    Text = "Bestätige die Erinnerung unter der mondbeschienenen Nacht."
  },
  AvgDialog_45443_Content_63 = {
    Text = "Sicherlich spürst du die verweilende Wärme auf deinen Fingerspitzen."
  },
  AvgDialog_45443_Content_64 = {
    Text = "Anerkennen Sie ihr sanftes Murmeln."
  },
  AvgDialog_45443_Content_65 = {
    Text = "Weißt du? In deinen Augen sehe ich Clades, uralte Glut und den Atem des Universums."
  },
  AvgDialog_45443_Content_66 = {
    Text = "Deine Reise war lang und du bist erschöpft, oder? Aber dein Blick bleibt fest und klar"
  },
  AvgDialog_45443_Content_67 = {
    Text = "Die Sterne können dich nicht ändern, und die Sandsee vielleicht auch nicht"
  },
  AvgDialog_45443_Content_68 = {
    Text = "Ihr Atem vermischt sich mit deinem.\nDas sternenübersäte Meer brennt in ihren Augen."
  },
  AvgDialog_45443_Content_69 = {
    Text = "Ich werde dem Yharnam-Ritual ein Ende setzen."
  },
  AvgDialog_45443_Content_7 = {
    Text = "Ich möchte Thais sehen!"
  },
  AvgDialog_45443_Content_70 = {
    Text = "Thais... muss dort auf mich warten."
  },
  AvgDialog_45443_Content_8 = {
    Text = "Du darfst die wichtigen Hinweise, die William dir hinterlassen hat, nicht falsch deuten – Nubien, der Hochstapler, die Korruption des Mutterbaums... All dies ist das Werk der Tempellichtkirche."
  },
  AvgDialog_45443_Content_9 = {
    Text = "Ramona, William, Ryker... alle Kollegen von Mythag sind zu diesem Zeitpunkt bereits gegangen."
  },
  AvgDialog_45444_Content_1 = {
    Text = "Unter dem Mutterbaum kniet die hilflose Alva in Tränen"
  },
  AvgDialog_45444_Content_10 = {
    Text = "Nur durch enge Ritzen kann man einen Blick auf das Licht aus einer anderen Welt erhaschen."
  },
  AvgDialog_45444_Content_11 = {
    Text = "In diesem flüchtigen Moment wanderte ich mit dem Yalan-Stamm, ständig auf der Suche nach einem Zufluchtsort."
  },
  AvgDialog_45444_Content_12 = {
    Text = "Ich habe Alvas Entschlossenheit miterlebt, die Verantwortung zu übernehmen, als es keinen Führer gab."
  },
  AvgDialog_45444_Content_13 = {
    Text = "Ich habe Alvas Entschlossenheit erlebt, das Feuerzeremonie abzuschaffen, ihren Schmerz, als ihre gewählte Nachfolgerin frühzeitig starb, und ihre Hilflosigkeit, das Ritual neu zu starten."
  },
  AvgDialog_45444_Content_14 = {
    Text = "Sie sah, wie Alva das Team in einer verzweifelten Suche nach Wasserquellen anführte und wie sie sich bemühte, gegen Nubia anzukämpfen."
  },
  AvgDialog_45444_Content_15 = {
    Text = "Alva, du hast gut gemacht."
  },
  AvgDialog_45444_Content_16 = {
    Text = "Selbst wenn ich hier bleibe, kann ich es nicht besser machen als du."
  },
  AvgDialog_45444_Content_17 = {
    Text = "Also, überlasse den Rest mir."
  },
  AvgDialog_45444_Content_18 = {
    Text = "Thais streichelt Alvas Kopf und wendet sich dann den tausenden benommenen Aram-Soldaten zu."
  },
  AvgDialog_45444_Content_19 = {
    Text = "Ich bin die Mutter der Erde, die Verkörperung des Verlangens."
  },
  AvgDialog_45444_Content_2 = {
    Text = "Meine Königin... Ich... Es tut mir leid... Alan..."
  },
  AvgDialog_45444_Content_20 = {
    Text = "Mein Name ist Thais, heiliger Name <Yellow:Tifrey Yesod>."
  },
  AvgDialog_45444_Content_21 = {
    Text = "Im Namen der einzigen Königin Aran werde ich dich besiegen, heuchlerischer Mutterbaum, der das Leben verschlingt und den Tod verbreitet."
  },
  AvgDialog_45444_Content_22 = {
    Text = "Ich werde die Menschen von Yalan aus dir retten und einen Weg für ihr Überleben suchen."
  },
  AvgDialog_45444_Content_23 = {
    Text = "Menschen von Yalan, wenn ihr meine Stimme noch hören könnt, bitte erwacht!"
  },
  AvgDialog_45444_Content_24 = {
    Text = "Die Welt stürzt in eine flüchtige Stille."
  },
  AvgDialog_45444_Content_25 = {
    Text = "Doch innerhalb von Sekunden stürzte Alans Team wie unermüdliche, unnachgiebige Lemminge in den Heiligen Fluss."
  },
  AvgDialog_45444_Content_26 = {
    Text = "Nutzlos. Du und der Mutterbaum teilen denselben Ursprung und wurden vom Willen dieses Meisters betroffen. Mit deiner aktuellen Kraft kannst du den verdorbenen Willen des Mutterbaums nicht erschüttern."
  },
  AvgDialog_45444_Content_27 = {
    Text = "Natürlich weiß ich das."
  },
  AvgDialog_45444_Content_28 = {
    Text = "Wenn nicht dafür, warum Hunderte Jahre reisen?"
  },
  AvgDialog_45444_Content_29 = {
    Text = "Ich verstecke die Mutterbaum von dem heiligen Fluss und trage den Samen der Auflösung im Fleisch, ist das nicht, um auf diesen Moment zu warten?"
  },
  AvgDialog_45444_Content_3 = {
    Text = "Keine Sorge. Ich habe bereits die Stimme deines Herzens gehört."
  },
  AvgDialog_45444_Content_30 = {
    Text = "Die Stunde des Endkampfes ist gekommen!"
  },
  AvgDialog_45444_Content_31 = {
    Text = "Ich bitte im Namen des Wesens der Begierde, Tifréh Yesod, um <Yellow: Tawil>, bitte antworte auf unser Versprechen von vor tausend Jahren —"
  },
  AvgDialog_45444_Content_32 = {
    Text = "Wenn der Bote aus der Ferne ankommt, benutze deinen Avatar als Führer, um die Schatten über Lemoah vorübergehend für mich zu vertreiben."
  },
  AvgDialog_45444_Content_33 = {
    Text = "Ein lautes Klagelied ertönte am Himmel"
  },
  AvgDialog_45444_Content_34 = {
    Text = "Thais öffnete den Sarg, und heraus rollte zu ihrer Überraschung die rot glühende Ramona"
  },
  AvgDialog_45444_Content_35 = {
    Text = "Endlich... brauchst du mich"
  },
  AvgDialog_45444_Content_36 = {
    Text = "Hier drin zu verstecken und mitzukommen, das ist wirklich ein Einfall, kleines Mädchen"
  },
  AvgDialog_45444_Content_37 = {
    Text = "Gut, dass du mitgekommen bist. Jede Minute, die ich zurückgehe, um dich zu holen, kostet unzählige Leben"
  },
  AvgDialog_45444_Content_38 = {
    Text = "Die Stimme in meinem Kopf... sie sagte mir... ich muss durchhalten"
  },
  AvgDialog_45444_Content_39 = {
    Text = "Aber, auch wenn sie nichts sagt...\nIch bin %player%s einziger Assistent, in der gefährlichsten Zeit muss ich bei {Male=er,Female=sie} sein"
  },
  AvgDialog_45444_Content_4 = {
    Text = "Weil niemand den Schmerz des Ungehörtseins besser versteht als ich."
  },
  AvgDialog_45444_Content_40 = {
    Text = "Das ist meine Pflicht als einziger Assistent, oder?"
  },
  AvgDialog_45444_Content_41 = {
    Text = "Sie betonte das Wort „einzige“ sehr stark"
  },
  AvgDialog_45444_Content_42 = {
    Text = "Wenn du ihre Kraft auf diesem Land erweckst, wird dein Körper stärker beeinflusst"
  },
  AvgDialog_45444_Content_43 = {
    Text = "Wenn es einen anderen Weg gäbe, würde ich ihn nicht wählen"
  },
  AvgDialog_45444_Content_44 = {
    Text = "Missaga ist hier, um das Ritual zu stoppen. Ich bin ein Mitglied von Missaga, bereit zu sterben!"
  },
  AvgDialog_45444_Content_45 = {
    Text = "Gut! Ramona unterdrückt die Essenz der Begierde, %player%, du und ich werden den Mutterbaum vollständig vernichten!"
  },
  AvgDialog_45444_Content_46 = {
    Text = "Ein ohrenbetäubendes Heulen ertönte am Himmel, ein silberner Schatten zog über die Wüste"
  },
  AvgDialog_45444_Content_48 = {
    Text = "Du fühlst, wie dein Körper leicht wird, und im nächsten Moment landest du vor einem stinkenden Tumor"
  },
  AvgDialog_45444_Content_49 = {
    Text = "Die von der Mutterbaum verschlungenen Aram sammeln sich hier in embryonaler Form, in halbtransparenten Löchern erscheinen zahlreiche verzerrte und verschwommene Gesichter, und nur schwarze und rote Schleimströme fließen unaufhörlich aus den Löchern in den immer weniger klaren heiligen Fluss"
  },
  AvgDialog_45444_Content_5 = {
    Text = "Ich bin Yalans Team gefolgt, Hunderte von Jahren gewandert."
  },
  AvgDialog_45444_Content_6 = {
    Text = "Niemand kann mich sehen, niemand kann mich hören."
  },
  AvgDialog_45444_Content_7 = {
    Text = "Ich war einst die schönste Tänzerin beim Fest und die am meisten verehrte Königin des Aran-Stammes.\nAber jetzt ist mein Tanz unbemerkt, und meine Erlass ist ungehört."
  },
  AvgDialog_45444_Content_8 = {
    Text = "In der Auflösung liegt eine andere Welt."
  },
  AvgDialog_45444_Content_9 = {
    Text = "Dunkelheit, Stille, Verzweiflung."
  },
  AvgDialog_46539_Content_1 = {
    Text = "Nach einem Jahr des Unterrichts und kürzlicher Aufgabenuntersuchungen erlauben dir deine Qualifikationen jetzt, an \"Traphase\" teilzunehmen."
  },
  AvgDialog_46539_Content_10 = {
    Text = "Natürlich, die Kämpfe werden von Erwachten geführt—obwohl in dieser Phase einige Wesen <Yellow:Verzerrung> der physischen Grenzen erleben werden."
  },
  AvgDialog_46539_Content_11 = {
    Text = "<Yellow:Fähigkeiten der Erwachten>, <Yellow:Reichsbarrieren> und <Yellow:Kampfre Regeln> unterscheiden sich erheblich von der Realität."
  },
  AvgDialog_46539_Content_12 = {
    Text = "Du verstehst, dass die <Yellow:nurturing auch für die Erwachenden scheitern wird>, aber <Yellow:dasselbe gilt für die andere Partei>. In gewisser Weise ist \"Traphase\" ein <Yellow:fairer Duell>."
  },
  AvgDialog_46539_Content_13 = {
    Text = "Aktiviere das Phasen-Gerät und probiere eine Runde aus. Alle Fragen werden im Kampf beantwortet. Möge der Silber Schlüssel deinen Weg leiten."
  },
  AvgDialog_46539_Content_2 = {
    Text = "Übrigens, hast du von anderen über \"Traphase\" gehört?"
  },
  AvgDialog_46539_Content_3 = {
    Text = "Habe ein gewisses Verständnis"
  },
  AvgDialog_46539_Content_4 = {
    Text = "Sehr gut, aber gemäß den Vorschriften der Schule muss ich dir eine umfassendere Erklärung zu den Risiken und Regeln geben."
  },
  AvgDialog_46539_Content_5 = {
    Text = "Noch nie gehört"
  },
  AvgDialog_46539_Content_6 = {
    Text = "Alright, ich werde von Anfang an beginnen und es dir vorstellen."
  },
  AvgDialog_46539_Content_7 = {
    Text = "In unserer Forschung über Silber entdeckten wir, dass die Vibrationswellen, die von Silber während der Oszillation erzeugt werden, gelegentlich physische Grenzen überschreiten können. Wir bezeichnen den Ort, an dem diese Vibrationswellen auftreten, als <Yellow:Phase>."
  },
  AvgDialog_46539_Content_8 = {
    Text = "Und \"Traphase\" ist eine spezialisierte Trainingsmethode, die Phasen nutzt, um in <Yellow:Kampf> mit einem anderen Selbst aus einer anderen Zeit und einem anderen Raum zu treten, wodurch der Effekt erzielt wird, den Geist und das Kampf- Bewusstsein zu verbessern."
  },
  AvgDialog_46539_Content_9 = {
    Text = "Ich selbst aus einer anderen Dimension..."
  },
  AvgDialog_46700_Content_1 = {
    Text = "Gnostischer Index 89.8, Tidefrequenz 762Hz, steigt weiterhin..."
  },
  AvgDialog_46700_Content_2 = {
    Text = "Es ist zweifellos <Yellow:D-tide>. Alle Abteilungen sind in Position. Das Überwachungsteam meldet den Gnostischen Index in Echtzeit, das Strategie-Team bereitet Notfallpläne vor, und das Aktionsteam startet die künstliche Domäne, bereit, in die D-tide-Ausschlusszone durch die spirituelle Dimension einzutauchen!"
  },
  AvgDialog_46700_Content_3 = {
    Text = "D-Gezeiten?"
  },
  AvgDialog_46700_Content_4 = {
    Text = "Die periodischen Schwankungen in der Bewusstseinsdimension innerhalb des Schwarzen Pools, beeinflusst von Gezeitenkräften, könnten schwere Katastrophen in verbundenen <Yellow:Regional d-effect Zonen> auslösen, wenn sie nicht richtig behandelt werden."
  },
  AvgDialog_46700_Content_5 = {
    Text = "Die schwebende Anomalie, die Czort Dekan bei der Schlüsselübergabe erwähnte, ist ein Zeichen des D-Gezeiten-Ausbruchs."
  },
  AvgDialog_46700_Content_6 = {
    Text = "Unbekannte mentale Fluten stören die Stabilität des Bereichs. Die Umgebung ändert sich schnell. <Yellow:Erwachte und Feinde können von der Schwarzen Flut betroffen sein>..."
  },
  AvgDialog_46700_Content_7 = {
    Text = "Wir werden die Prinzipien im Unterricht besprechen. Die erste Welle des regionalen D-Effekts ist hier, bereite dich auf die Gezeitenkatastrophe vor!"
  },
  AvgDialog_46700_Content_8 = {
    Text = "Möge der Silberne Schlüssel dich leiten."
  },
  AvgDialog_46733_Content_1 = {
    Text = "Auch wenn es nur eine weitere gewöhnliche Nacht auf dem Feld ist, fühlst du dich immer unwohl beim Schlafen, wenn du nicht in der Schule bist."
  },
  AvgDialog_46733_Content_10 = {
    Text = "Ogier, fühlst du dich unwohl?"
  },
  AvgDialog_46733_Content_11 = {
    Text = "Mein Herr, ich... ich habe nicht... Es sind sie..."
  },
  AvgDialog_46733_Content_12 = {
    Text = "Ogier kämpfte darum, die unkontrollierbaren unsichtbaren Wesen zu heben. Was einst wie seine Macht um ihn schwebte, wurde jetzt ungewöhnlich aktiv—"
  },
  AvgDialog_46733_Content_13 = {
    Text = "*Schlürfen.*"
  },
  AvgDialog_46733_Content_14 = {
    Text = "Aktiv „lecken“ sie dein Gesicht wie die Zunge einer Katze, wenn du dich näher kommst, um einen Blick darauf zu werfen."
  },
  AvgDialog_46733_Content_15 = {
    Text = "Mein Herr—?!"
  },
  AvgDialog_46733_Content_16 = {
    Text = "Ich... wollte... nicht..."
  },
  AvgDialog_46733_Content_17 = {
    Text = "Du hast die unsichtbare, katzenartige Präsenz zurückgedrängt, deine Finger versanken in Ogier's weichem, goldenen Haar und streichelten es sanft."
  },
  AvgDialog_46733_Content_18 = {
    Text = "Es ist in Ordnung, nimm dir Zeit."
  },
  AvgDialog_46733_Content_19 = {
    Text = "Ich... Ich weiß nicht warum, aber heute möchte ich wirklich an deiner Seite bleiben. Dieses Gefühl ist so stark, dass selbst die immateriellen Dinge über meine Kontrolle hinausgehen..."
  },
  AvgDialog_46733_Content_2 = {
    Text = "Die Klänge der Welt werden in der Dunkelheit besonders auffällig, insbesondere jene jugendlichen, aber schweren Atemzüge—"
  },
  AvgDialog_46733_Content_20 = {
    Text = "<Small: Könnte es der Einfluss des Heiligen Flusses und des Mutterbaums sein?>"
  },
  AvgDialog_46733_Content_21 = {
    Text = "Wenn ich dich gestört habe, mein Herr..."
  },
  AvgDialog_46733_Content_22 = {
    Text = "Es ist alles in Ordnung."
  },
  AvgDialog_46733_Content_23 = {
    Text = "R-Wirklich?!"
  },
  AvgDialog_46733_Content_24 = {
    Text = "Du hast Ogier in das Zimmer gezogen, ihn gewaltsam auf das Bett gestoßen und dann einen Stuhl herübergezogen, um am Bett zu sitzen."
  },
  AvgDialog_46733_Content_25 = {
    Text = "Bleib heute Nacht bei mir, damit du gut schlafen kannst."
  },
  AvgDialog_46733_Content_26 = {
    Text = "Wie kann ich die Nacht im Bett meines Herrn verbringen? Das ist unangemessen—"
  },
  AvgDialog_46733_Content_27 = {
    Text = "Du hast Ogier in eine Decke gewickelt, und er zuckte wie eine Raupe, bis du deine Hand auf seine Stirn gelegt hast."
  },
  AvgDialog_46733_Content_28 = {
    Text = "Schlaf, schlaf..."
  },
  AvgDialog_46733_Content_29 = {
    Text = "Du hast nicht viele Wiegenlieder gehört, und jetzt summst du unbewusst eines von Londiniums gruseligen Kinderreimen."
  },
  AvgDialog_46733_Content_3 = {
    Text = "Wie kannst du nicht schlafen? Wir haben noch Ermittlung Aufgaben, die nach der Morgendämmerung auf uns warten!"
  },
  AvgDialog_46733_Content_30 = {
    Text = "Aber Ogier's leuchtende Augen trübten allmählich, wie der Abendstern, der im Nebel vor der Morgendämmerung versinkt."
  },
  AvgDialog_46733_Content_31 = {
    Text = "Meister... huch... Mein Herr..."
  },
  AvgDialog_46733_Content_32 = {
    Text = "Du standest lange an seinem Bett und beobachtetest ihn, bis sein Atem gleichmäßig wurde und die Sterne draußen verblassten. Erst dann berührtest du sanft die Haare auf seiner Stirn und schlichst aus dem Zimmer."
  },
  AvgDialog_46733_Content_33 = {
    Text = "Schlaf gut, gutes Kind."
  },
  AvgDialog_46733_Content_4 = {
    Text = "Meister, Meister! Ogier wollte deinen Schlaf nicht stören. Es ist nur... es ist nur..."
  },
  AvgDialog_46733_Content_5 = {
    Text = "Ogier hält seine Waffe, lehnt sich gegen den Flur und steht wachsamen wie eine Ritterstatue vor deiner Tür."
  },
  AvgDialog_46733_Content_6 = {
    Text = "Er wusste nicht, wie lange er dumm im Flur gestanden hatte. Als du die Tür öffnetest, versuchte er reflexartig, dir zu salutieren, schwankte aber schwach."
  },
  AvgDialog_46733_Content_7 = {
    Text = "—Vorsicht!"
  },
  AvgDialog_46733_Content_8 = {
    Text = "Du hast den Jungen, der beinahe gefallen wäre, stabilisiert, aber das hat Ogier nur noch nervöser gemacht."
  },
  AvgDialog_46733_Content_9 = {
    Text = "Sein Gesicht errötete, und er tastete herum, als würde er versuchen, einen unsichtbaren Überlauf zu zügeln, während er gleichzeitig von deiner Seite fliehen wollte."
  },
  AvgDialog_46734_Content_1 = {
    Text = "Geheimnisträger, hast du Zeit?"
  },
  AvgDialog_46734_Content_10 = {
    Text = "Die Hand der Frau greift deinen Arm, ihre Gelenke sind lang und kräftig, selbst durch den Stoff hindurch kann man die dünnen Schwielen spüren, die durch jahrelangen Gebrauch von Feuerwaffen entstanden sind."
  },
  AvgDialog_46734_Content_11 = {
    Text = "In diesen langen Jahren habe ich mich daran gewöhnt, die Auswirkungen des Heiligen Flusses zu ertragen... Ja, er ist heilig und barmherzig, lässt die Gemeinschaft fortbestehen, doch das, wonach ich suche, kann ich nicht in seiner Hitze finden."
  },
  AvgDialog_46734_Content_12 = {
    Text = "Wenn du so ehrliche Worte sprichst, Alva... deine Gesten sollten doch nicht so sein, oder?!"
  },
  AvgDialog_46734_Content_13 = {
    Text = "Ich meine, ich bin jetzt sehr ruhig, meine Handlungen stammen nicht vom Heiligen Fluss und auch nicht von irgendwelchen äußeren Einflüssen."
  },
  AvgDialog_46734_Content_14 = {
    Text = "<LightGray:(Nein, du siehst überhaupt nicht ruhig aus.)>"
  },
  AvgDialog_46734_Content_15 = {
    Text = "Es mag unangemessen sein, zu sagen, dass du, selbst wenn dir das Augenlicht genommen wurde, weißt, dass die jetzige Bewegung absolut nichts ist, was Alva normalerweise tun könnte."
  },
  AvgDialog_46734_Content_16 = {
    Text = "...nur der andere scheint das offensichtlich nicht zu denken."
  },
  AvgDialog_46734_Content_17 = {
    Text = "Denn ich weiß bereits, was ich schützen sollte und für wen, um die Vision zu erreichen, die ich anstrebe."
  },
  AvgDialog_46734_Content_18 = {
    Text = "Also denke ich darüber nach—ob ich heutzutage wählen kann, meinen Instinkten zu folgen und einige Dinge zu erforschen, die ich nie berührt habe."
  },
  AvgDialog_46734_Content_19 = {
    Text = "Alvas Erzählung ist äußerst ruhig, als ob es sich nur um einen Bericht über einen Trainingsplan handelt."
  },
  AvgDialog_46734_Content_2 = {
    Text = "Mein Körper erhitzt sich unkontrolliert, weder Puppe noch Silvea können mir helfen"
  },
  AvgDialog_46734_Content_20 = {
    Text = "Doch das Herz verriet seinen Besitzer, das pochende Geräusch ließ sich nicht so leicht wie das Licht vor dir verbergen."
  },
  AvgDialog_46734_Content_21 = {
    Text = "Dieser einst dem gerechten Märtyrertum gewidmete, erlebt offensichtlich einen weiteren Krieg mit sich selbst."
  },
  AvgDialog_46734_Content_22 = {
    Text = "Sie können mich jederzeit wegschieben und ohnmächtig schlagen."
  },
  AvgDialog_46734_Content_23 = {
    Text = "Oder—führe mich."
  },
  AvgDialog_46734_Content_24 = {
    Text = "Auf diesem endlosen Weg der Suche werde ich Ihnen meine ewige Loyalität schenken..."
  },
  AvgDialog_46734_Content_25 = {
    Text = "Ich bin bereit, für immer an Ihrer Seite zu eskortieren."
  },
  AvgDialog_46734_Content_3 = {
    Text = "Ein... fast instinktiver Drang führte mich zu deinem Zimmer"
  },
  AvgDialog_46734_Content_4 = {
    Text = "Lass mich einfach eine Weile hier bleiben, natürlich werde ich mein Bestes tun, um diesen Instinkt zu kontrollieren. Wenn ich Anzeichen von Kontrollverlust zeige, schlag mich sofort bewusstlos, ohne Gnade"
  },
  AvgDialog_46734_Content_5 = {
    Text = "...Ich denke nach, %player%, ich denke nach."
  },
  AvgDialog_46734_Content_6 = {
    Text = "Du weißt nicht, was sie denkt, aber die Vernunft sagt dir, dass du jetzt besser keine anderen Geräusche machen solltest, außer einem einsilbigen Ausdruck des Zweifels."
  },
  AvgDialog_46734_Content_7 = {
    Text = "Auch du hast das getan, und Alva lachte verständnisvoll über deine peinliche Steifheit."
  },
  AvgDialog_46734_Content_8 = {
    Text = "Ich weiß, woher der Einfluss des Heiligen Flusses kommt und was er bedeutet."
  },
  AvgDialog_46734_Content_9 = {
    Text = "Ich habe vielen Existenzen gedient, aber ich habe immer nur nach Gerechtigkeit gestrebt. Selbst in den Augen vieler mag die sogenannte Gerechtigkeit nur eine vorübergehende Illusion sein."
  },
  AvgDialog_46735_Content_1 = {
    Text = "Partner! Partner, komm schnell!"
  },
  AvgDialog_46735_Content_10 = {
    Text = "New friends! Auritas Drüsen haben sich heute in so viele neue Freunde aufgeteilt!"
  },
  AvgDialog_46735_Content_11 = {
    Text = "Sie lachte aufgeregt und schob die giftige Qualle in deine Hände."
  },
  AvgDialog_46735_Content_12 = {
    Text = "Jeder sagt, er will bei dir sein, also möchte Aurita auch dabei sein!"
  },
  AvgDialog_46735_Content_13 = {
    Text = "<Italic:So viele Quallen... gut, dass ich nicht zu Allergien neige.>"
  },
  AvgDialog_46735_Content_14 = {
    Text = "Nun, auch wenn sie zu Allergien neigt, scheinen ein paar Adrenalinschübe es wert zu sein für ihr Lächeln."
  },
  AvgDialog_46735_Content_2 = {
    Text = "<Small:Dieses Geräusch... Könnte es...>"
  },
  AvgDialog_46735_Content_3 = {
    Text = "Halte dich fest, ich werde die Tür sofort öffnen—"
  },
  AvgDialog_46735_Content_4 = {
    Text = "Die Person stürmte ohne Vorwarnung ins Wohnheimzimmer und krachte mit einem Dumpf in dich hinein."
  },
  AvgDialog_46735_Content_5 = {
    Text = "Du taumeltest zwei Schritte, während du das Mädchen stützt, kannst aber letztendlich der Schwerkraft nicht widerstehen und fällst mit ihr zu Boden, deine Sicht dreht sich."
  },
  AvgDialog_46735_Content_6 = {
    Text = "Partner, schau!"
  },
  AvgDialog_46735_Content_7 = {
    Text = "Bevor du dich wieder vom Boden aufrappeln konntest, hatte Aurita ihre \"Hände\" in deine Richtung ausgestreckt."
  },
  AvgDialog_46735_Content_8 = {
    Text = "Die schirmförmigen Arme schließen sich zusammen und halten eine daumengroße Qualle."
  },
  AvgDialog_46735_Content_9 = {
    Text = "Was sind diese Quallen?"
  },
  AvgDialog_47150_Content_1 = {
    Text = "<Italic:Die vielen Tränen von heute Nacht sind unvergesslich~>"
  },
  AvgDialog_47150_Content_10 = {
    Text = "Ihre Dienstmagd sollte etwas erfrischenden Tee zubereitet haben. Ich werde sie bitten, ihn zu bringen."
  },
  AvgDialog_47150_Content_11 = {
    Text = "Tu das nicht—"
  },
  AvgDialog_47150_Content_12 = {
    Text = "Sorel zog dich nach unten, und ihr beiden fiel auf die weiche Couch. Trotz ihres zerzausten Aussehens hielt sie das Weinglas immer noch fest in der Hand."
  },
  AvgDialog_47150_Content_13 = {
    Text = "Das Herrenhaus ist in Dunkelheit gehüllt, nur der goldene Wein in ihrem Glas bricht das Mondlicht und wirft einen intimen Glanz zwischen euch."
  },
  AvgDialog_47150_Content_14 = {
    Text = "Ich bin nicht betrunken, also ist kein Entziehungstee nötig."
  },
  AvgDialog_47150_Content_15 = {
    Text = "Mein Salon... war nie so ruhig, doch es gibt mir so viel Frieden."
  },
  AvgDialog_47150_Content_16 = {
    Text = "Bei jedem früheren Gala zählte ich mental die Salongäste. Diejenigen, die meine Einladung angenommen, ein Ticket gekauft oder sich hineingeschlichen hatten... Ich erinnere mich an jedes Gesicht."
  },
  AvgDialog_47150_Content_17 = {
    Text = "Wenn jemand die Einladung angenommen hat, aber nicht erschienen ist, werde ich mich erinnern... Diese Leute müssen Geheimnisse haben, die ich noch aufdecken muss."
  },
  AvgDialog_47150_Content_18 = {
    Text = "Ich kann nicht anders, als mir über diese verborgenen Gefahren Sorgen zu machen und mich über die unkontrollierbare Zukunft ängstlich zu fühlen..."
  },
  AvgDialog_47150_Content_19 = {
    Text = "Damit hob sie dein Kinn mit einer Hand an und verhinderte, dass dein Blick umher schweifte."
  },
  AvgDialog_47150_Content_2 = {
    Text = "Lady Sorel? Karen hat gesagt, dass du mich sehen wolltest."
  },
  AvgDialog_47150_Content_20 = {
    Text = "Aber bezüglich des unbekannten \"du,\" fühlte ich nur Neugier."
  },
  AvgDialog_47150_Content_21 = {
    Text = "Vielleicht... können du und ich den lebhaftesten und widerstandsfähigsten Trieb zusammen nähren."
  },
  AvgDialog_47150_Content_22 = {
    Text = "Wir werden gemeinsam in dem Unerreichbaren stehen..."
  },
  AvgDialog_47150_Content_23 = {Text = "Puh..."},
  AvgDialog_47150_Content_24 = {
    Text = "Bevor Sorel ihren Satz beenden konnte, wurde ihr Körper schlaff und sie fiel zu dir."
  },
  AvgDialog_47150_Content_25 = {
    Text = "Der Kelch rollte auf den Marmorboden, während der Wein schnell in die Ritzen zwischen den Steinplatten sickerte. Der mit Alkohol beladene Atem schwebte leise in deinen fast schmelzenden Verstand."
  },
  AvgDialog_47150_Content_3 = {
    Text = "Ah... Kleiner Hüter, du bist hier."
  },
  AvgDialog_47150_Content_4 = {
    Text = "Kleiner, kleiner Hüter?"
  },
  AvgDialog_47150_Content_5 = {
    Text = "Bevor du weiter reagieren konntest, brachte Sorel dir ein Glas Wein an die Lippen."
  },
  AvgDialog_47150_Content_6 = {
    Text = "Wenn sie sich nähert, weht ein starker Geruch von Alkohol aus ihrem Haar und ihrem Kleid. Das Aroma von Alkohol und blumigen Früchten vermischt sich, getragen von ihrem warmen Atem zu Ihrem Handgelenk."
  },
  AvgDialog_47150_Content_7 = {
    Text = "Frau Sorel, Sie sind schon wieder betrunken."
  },
  AvgDialog_47150_Content_8 = {
    Text = "Betrunken? Vielleicht. Ich nehme an, ich bin es wirklich."
  },
  AvgDialog_47150_Content_9 = {
    Text = "Da du keinen einzigen Schluck genommen hast, gab Sorel vor, genervt zu sein, schüttelte den Kopf und nahm selbst ein paar Schlücke."
  },
  AvgDialog_47164_Content_1 = {
    Text = "Horcht, Sterne"
  },
  AvgDialog_47164_Content_10 = {
    Text = "Ich bin hier, Deborah. Ich bin hier."
  },
  AvgDialog_47164_Content_100 = {
    Text = "...Wo sind die Wachen?"
  },
  AvgDialog_47164_Content_101 = {
    Text = "Während ihr angestoßen und getrunken habt, haben wir bereits eure Leibgarden abgeschlachtet."
  },
  AvgDialog_47164_Content_102 = {
    Text = "Was eure Armeen außerhalb der Stadt betrifft... versucht gar nicht erst, sie zu kontaktieren."
  },
  AvgDialog_47164_Content_103 = {
    Text = "Blut befleckt jeden Winkel der Halle. Schreie hallen von den Wänden wider wie eine Symphonie aus der Hölle."
  },
  AvgDialog_47164_Content_104 = {
    Text = "Jene, die den vergifteten Wein nicht getrunken haben, zittern, ihre Körper zu schwach, um auch nur ein Schwert zu ziehen oder zu fliehen."
  },
  AvgDialog_47164_Content_105 = {
    Text = "Goliath bewundert das blutige Meisterwerk und genießt den Schrecken in ihren Gesichtern. Er seufzt zufrieden und hebt seine gewaltige Klinge."
  },
  AvgDialog_47164_Content_106 = {
    Text = "Trinkt den Wein und werdet zu Fischmenschen, oder geht hier zugrunde. Trefft eure Wahl."
  },
  AvgDialog_47164_Content_107 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47164_Content_108 = {
    Text = "Ah!!!——"
  },
  AvgDialog_47164_Content_109 = {
    Text = "Ein durchdringender Schrei trifft auf die Steintafeln und erzeugt ein dumpfes, schweres Echo."
  },
  AvgDialog_47164_Content_11 = {
    Text = "Miryam? Was machst du...?"
  },
  AvgDialog_47164_Content_110 = {
    Text = "Sie versucht sich zu wehren, zu entkommen, doch Miryam hält sie eisern fest. Sie kann sich keinen Zentimeter bewegen."
  },
  AvgDialog_47164_Content_111 = {
    Text = "Sie sehnt sich danach, in Ohnmacht zu fallen, doch ihr Verstand bleibt qualvoll klar und zwingt sie, sich der Pein und der Angst zu stellen."
  },
  AvgDialog_47164_Content_112 = {
    Text = "Sprich mir nach: „Die Frommen sollen umarmt werden — denn der Herr erblickt ihre Hingabe.“"
  },
  AvgDialog_47164_Content_113 = {
    Text = "Deborahs Blut spritzt über Miryams Gestalt. Sie erinnert sich, wie sie vor vielen Jahren dasselbe mit ihrem Vater auf dem Tempelaltar getan hat."
  },
  AvgDialog_47164_Content_114 = {
    Text = "Abschied ist doch nur ein Vorspiel zu einem größeren Wiedersehen, nicht wahr, mein Herr?"
  },
  AvgDialog_47164_Content_115 = {
    Text = "Sie starrt gebannt auf Deborahs Unterleib, während ihre Klinge ansetzt, den letzten Strich des Diagramms zu vollenden."
  },
  AvgDialog_47164_Content_116 = {
    Text = "Nun denn, Deborah. Sprich. ‚Die sehnenden Seelen...'"
  },
  AvgDialog_47164_Content_117 = {
    Text = "Miryams Hand griff in Deborahs Bauch, rührte und riss."
  },
  AvgDialog_47164_Content_118 = {
    Text = "Deborahs heisere Stimme kratzt vor Qual. Ihre blutunterlaufenen Augen fliegen im Wahnsinn auf und starren direkt in ihre eigenen Eingeweide."
  },
  AvgDialog_47164_Content_119 = {
    Text = "„... soll erhört werden — denn der Herr hört ihre Gebete.“"
  },
  AvgDialog_47164_Content_12 = {
    Text = "Dieser Witz ist überhaupt nicht lustig, Miryam... Setz mich ab..."
  },
  AvgDialog_47164_Content_120 = {
    Text = "Miryam reißt etwas heraus. Es sollte schmerzhaft sein, doch Deborah spürt es nicht mehr."
  },
  AvgDialog_47164_Content_121 = {
    Text = "Ihr Geist ist taub geworden; ihre Gefühle und Sinne haben sie verlassen."
  },
  AvgDialog_47164_Content_122 = {
    Text = "Sie sieht verschwommen, wie Miryam eine blutige Masse aus ihrem offenen Unterleib zieht."
  },
  AvgDialog_47164_Content_123 = {
    Text = "Sa... Sa..."
  },
  AvgDialog_47164_Content_124 = {
    Text = "Sara. Miryam hatte ihr gesagt, es sei der Name ihrer jüngeren Schwester."
  },
  AvgDialog_47164_Content_125 = {
    Text = "Sie und Nord hatten sich darauf geeinigt, ihre Tochter so zu nennen, doch sie bekam nie die Gelegenheit, es Miryam zu sagen."
  },
  AvgDialog_47164_Content_126 = {
    Text = "<Italic:Nenn sie Sara...> Deborahs Lippen bewegen sich, doch sie kann ihre Stimme nicht mehr finden."
  },
  AvgDialog_47164_Content_127 = {
    Text = "„Herr, mögen unsere Hymnen das abgrundtiefe Dunkel durchdringen, auf dass wir mit Dir emporsteigen — in die ewige Leere, wo Stille und Wahnsinn als eines herrschen.“"
  },
  AvgDialog_47164_Content_128 = {
    Text = "Miryam küsst zärtlich ihr Patenkind, ihre Lippen vom Blut des Säuglings befleckt. Als sie Deborahs Augen schließt, tropft Blut aus ihrem Mundwinkel."
  },
  AvgDialog_47164_Content_129 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47164_Content_13 = {
    Text = "Nein, Deborah, das ist kein Scherz. Nichts in dieser Welt ist ernster als das."
  },
  AvgDialog_47164_Content_130 = {
    Text = "Tippe, tippe, tippe..."
  },
  AvgDialog_47164_Content_131 = {
    Text = "Ohnmächtige Schritte sind aus dem Haus zu hören."
  },
  AvgDialog_47164_Content_132 = {
    Text = "Dieser bescheidene Schuppen, aus dunklen Tafeln gebaut, sieht genau wie das Zuhause aus, in dem Miryam einst lebte."
  },
  AvgDialog_47164_Content_133 = {
    Text = "In diesem Haus verabschiedete sie sich von ihrer Mutter, ihrem Vater, ihrer Schwester und ihren Freunden."
  },
  AvgDialog_47164_Content_134 = {
    Text = "In diesem Haus wird sie sich wieder mit ihnen vereinen."
  },
  AvgDialog_47164_Content_135 = {
    Text = "Die Schritte hielten an der Tür auf."
  },
  AvgDialog_47164_Content_136 = {
    Text = "Lobe den Hohen Priester!"
  },
  AvgDialog_47164_Content_137 = {
    Text = "Lobe den Hohen Priester!"
  },
  AvgDialog_47164_Content_138 = {
    Text = "Goliath kniete nieder. Hinter ihm riefen unzählige Murlocs denselben Satz und knieten einstimmig."
  },
  AvgDialog_47164_Content_139 = {
    Text = "Sie umgeben die Hütte wie endlose Wellen und warten auf Aequors Befehl."
  },
  AvgDialog_47164_Content_14 = {
    Text = "Was willst du, Miryam... Hast du nicht gesagt, ich wäre deine beste Freundin?"
  },
  AvgDialog_47164_Content_140 = {
    Text = "Miryam trug das blutige Baby zur Menge. Die Fischmänner machten ihr Platz."
  },
  AvgDialog_47164_Content_141 = {
    Text = "Die Sterne stehen günstig. Des Königs Heiliger Embryo wurde in das Heilige Kind eingepflanzt. Bald wird der König in diese Welt zurückkehren."
  },
  AvgDialog_47164_Content_142 = {
    Text = "Der König wird seine tugendhaften Untertanen beschützen, das Göttliche Reich herbeiführen!"
  },
  AvgDialog_47164_Content_143 = {
    Text = "Gottes Reich! Gottes Reich!"
  },
  AvgDialog_47164_Content_144 = {
    Text = "Die Fischmenschen jubeln und tanzen in einem Rausch des Wahnsinns. Miryam steht in der Mitte, Sternenlicht erhellt ihr Gesicht, das von Blut und Tränen gezeichnet ist."
  },
  AvgDialog_47164_Content_145 = {
    Text = "Das Wort unseres Herrn wird sich über die Welt verbreiten. Hohepriesterin, gebt dieser Herde einen Namen."
  },
  AvgDialog_47164_Content_146 = {
    Text = "Kalte, brennende Augen wenden sich langsam. Miryam mustert ihre Soldaten, ihre Untertanen. Sie schenkt ihnen das Lächeln einer Priesterin."
  },
  AvgDialog_47164_Content_147 = {
    Text = "Wir sind über das Meer gesegelt, den Fußstapfen des Königs folgend.\nWir sind über das Meer gesegelt und haben das Reich des Königs hervorgebracht..."
  },
  AvgDialog_47164_Content_148 = {
    Text = "Die Welt wird uns nennen... Seefahrer."
  },
  AvgDialog_47164_Content_149 = {
    Text = "Seefahrer! Seefahrer!!"
  },
  AvgDialog_47164_Content_15 = {
    Text = "Du... hattest einmal auch eine Freundin namens Deborah... Ist das nicht Schicksal, Miryam? Bitte... bitte tu mir nichts an..."
  },
  AvgDialog_47164_Content_150 = {
    Text = "Inmitten des ohrenbetäubenden Chors der Fischmenschen hebt Miryam das Baby mit beiden Händen empor."
  },
  AvgDialog_47164_Content_151 = {
    Text = "Anstelle ihres Herzens strahlt der Heilige Embryo ein reines, weißes Leuchten unter den Sternen aus."
  },
  AvgDialog_47164_Content_152 = {Text = "Waaahhh—"},
  AvgDialog_47164_Content_153 = {
    Text = "Stille fällt ein. Der blutbedeckte Säugling, der sich in den Ruinen windet, stößt seinen ersten, verspäteten Schrei aus."
  },
  AvgDialog_47164_Content_154 = {
    Text = "Die Sterne lauschen schweigend jenem orakelhaften Schrei. Ein einzelner Stern fällt und zieht eine traurige Spur über den Nachthimmel."
  },
  AvgDialog_47164_Content_155 = {
    Text = "—Eine weitere Geschichte der Sterne steht kurz bevor."
  },
  AvgDialog_47164_Content_16 = {
    Text = "Nein, Deborah. Wie könnte ich es ertragen, dir weh zu tun? Du bist meine beste Freundin, meine einzige Freundin..."
  },
  AvgDialog_47164_Content_17 = {
    Text = "Sie streichelte sanft Deborahs Gesicht und wischte ihre Tränen der Angst weg. Die kalte und glitschige Berührung ließ Deborah unkontrollierbar zittern."
  },
  AvgDialog_47164_Content_18 = {
    Text = "Ich werde dir niemals, niemals schaden, Deborah. Ich gebe dir lediglich ein Geschenk."
  },
  AvgDialog_47164_Content_19 = {
    Text = "Geschenk, Präsenz?"
  },
  AvgDialog_47164_Content_2 = {
    Text = "Territorium der Ornn-Familie, Altar"
  },
  AvgDialog_47164_Content_20 = {
    Text = "Ich wünschte mir so sehr, ich könnte die Heilige Frucht tragen. Aber du hast gesehen, wie ich versucht habe, sie einzupflanzen; ich bin nicht würdig."
  },
  AvgDialog_47164_Content_21 = {
    Text = "Diese Ehre ist nichts, was jeder erreichen kann. Mein Bedauern besteht darin, dass ich sie nicht genießen kann..."
  },
  AvgDialog_47164_Content_22 = {
    Text = "Deborah, ich bin die Patin deiner Tochter. Ich werde dieser höchsten Ehre meiner Göttin zuteilwerden lassen, und auch dir, meiner liebsten und einzigen Freundin."
  },
  AvgDialog_47164_Content_23 = {
    Text = "Miryam, ich bin bereit... ich bin bereit, meine Tochter zu einem Gefäß zu machen, um diese Ehre zu umarmen..."
  },
  AvgDialog_47164_Content_24 = {
    Text = "Aber sie wird erst in drei Monaten geboren... Ich kann nichts tun."
  },
  AvgDialog_47164_Content_25 = {
    Text = "Es ist zu spät, Deborah. Es ist zu spät."
  },
  AvgDialog_47164_Content_26 = {
    Text = "Miryam sah Deborah mit Zuneigung an, ihr Ton wurde noch sanfter."
  },
  AvgDialog_47164_Content_27 = {
    Text = "Sie ist die perfekte Wahl. Sie muss heute geboren werden."
  },
  AvgDialog_47164_Content_28 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47164_Content_29 = {
    Text = "Edmond Familiengebiet, Festsaal"
  },
  AvgDialog_47164_Content_3 = {
    Text = "Tick-tack—"
  },
  AvgDialog_47164_Content_30 = {
    Text = "Jetzt lasst uns den Gastgeber dieses Festes willkommen heißen — Goliath aus Orne!"
  },
  AvgDialog_47164_Content_31 = {
    Text = "Jubelschreie hallten im Saal. Goliath betrat die Bühne und scannte langsam den Raum."
  },
  AvgDialog_47164_Content_32 = {
    Text = "Edmond, Pappas, Enom... Mitglieder aller bedeutenden Familien haben sich hier versammelt."
  },
  AvgDialog_47164_Content_33 = {
    Text = "Ihre prächtige Kleidung erzählt eine Geschichte von Blutvergießen, und ihre lachenden Augen glänzen vor Gier."
  },
  AvgDialog_47164_Content_34 = {
    Text = "Sie sind die Herren des Landes und der Geschichte. Sie sind die Sklaven der Macht und des Begehrens."
  },
  AvgDialog_47164_Content_35 = {
    Text = "Goliath lächelte ihnen zu."
  },
  AvgDialog_47164_Content_36 = {
    Text = "Meine Damen und Herren, heute markiert die offizielle Gründung der Allianz der Sieben Familien. Detaillierte Vereinbarungen werden Ihnen in Kürze mitgeteilt."
  },
  AvgDialog_47164_Content_37 = {
    Text = "Jetzt lass uns dieses wunderbare Fest genießen. Prost auf Land, Geld und Macht!"
  },
  AvgDialog_47164_Content_38 = {
    Text = "Die Menge jubelte und hob ihre Gläser. Exquisite und reichhaltige Gerichte wurden nacheinander serviert."
  },
  AvgDialog_47164_Content_39 = {
    Text = "Das Bankett begann, und die Adligen hoben ihre Gläser, um die bevorstehenden Gewinne zu feiern. Das Geschrei übertönte alle Geräusche von außen."
  },
  AvgDialog_47164_Content_4 = {
    Text = "Der Klang von tropfendem Wasser erreichte Deborahs Ohren klar. Sie öffnete langsam die Augen."
  },
  AvgDialog_47164_Content_40 = {
    Text = "Draußen vor der Tür."
  },
  AvgDialog_47164_Content_41 = {Text = "Ah—"},
  AvgDialog_47164_Content_42 = {
    Text = "Du bist... Ugh!..."
  },
  AvgDialog_47164_Content_43 = {
    Text = "Abisha zieht das Messer aus dem Körper des Wächters."
  },
  AvgDialog_47164_Content_44 = {
    Text = "Puh... Wenn ich nur diese Murlocs nicht verstehen könnte, dann müsste ich diesen Job nicht machen..."
  },
  AvgDialog_47164_Content_45 = {
    Text = "Er warf einen Blick auf den Fischkrieger neben ihm und seufzte."
  },
  AvgDialog_47164_Content_46 = {
    Text = "Sind alle anderen Ausgänge gesichert? Sind die persönlichen Wachen, die von diesen Familien gebracht wurden, getötet worden?"
  },
  AvgDialog_47164_Content_47 = {
    Text = "Gut... Sichere alle Ausgänge des Schlosses. Stationiere ein Team mit mir in der Nähe des Festsaals und warte auf die nächsten Befehle von Lord Goliath."
  },
  AvgDialog_47164_Content_48 = {
    Text = "Ihre Hauptstreitkräfte werden wahrscheinlich eine oder zwei Stunden brauchen, um von der Anomalie hier zu erfahren. Bete, dass Lord Goliath es bis dahin löst..."
  },
  AvgDialog_47164_Content_49 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47164_Content_5 = {
    Text = "Ein Raum, umgeben von dunklen Tafeln, mit Sternenlicht, das von einem Loch oben herabfällt und auf ihren Bauch scheint."
  },
  AvgDialog_47164_Content_50 = {
    Text = "Nein... Miryam... tu es nicht!"
  },
  AvgDialog_47164_Content_51 = {
    Text = "Bitte... bitte... um unserer Verbindung willen... verschone mich..."
  },
  AvgDialog_47164_Content_52 = {
    Text = "Ich verleihe dir die höchste Ehre, doch du beleidigst diese Freundschaft, Deborah."
  },
  AvgDialog_47164_Content_53 = {
    Text = "Aber es ist in Ordnung. Mein Herr versteht deine Angst. Unsere Freundschaft wird sich durch diese Beleidigungen nicht ändern."
  },
  AvgDialog_47164_Content_54 = {
    Text = "Ehrfürchtig stellt sie das Götzenbild von Tulu neben den Altar und verneigt sich davor."
  },
  AvgDialog_47164_Content_55 = {
    Text = "Gepriesen sei der Herr... Lemuria, der Große König... Heute Nacht heiße ich deine Rückkehr willkommen."
  },
  AvgDialog_47164_Content_56 = {
    Text = "Habe Geduld. Die Sterne rücken in ihre Konstellation."
  },
  AvgDialog_47164_Content_57 = {
    Text = "Sie erhebt sich und schreitet mit sanftem Gang auf Deborah zu. Ein bizarrer Zeremoniendolch glitzert in ihrer bleichen Hand."
  },
  AvgDialog_47164_Content_58 = {
    Text = "Nein! Miryam! Ich flehe dich an... bitte... tu das nicht..."
  },
  AvgDialog_47164_Content_59 = {
    Text = "Sieh mich an, Deborah. Sieh mir in die Augen."
  },
  AvgDialog_47164_Content_6 = {
    Text = "Ihr Körper war nackt, ihr Bauch geschwollen, mit unter dem Sternenlicht deutlich sichtbaren Venen."
  },
  AvgDialog_47164_Content_60 = {
    Text = "Ich weiß, dass du Angst hast. Ich habe viele Gläubige zittern sehen, wenn sie das Ende dieses Lebens erreichten."
  },
  AvgDialog_47164_Content_61 = {
    Text = "Aber keine Sorge. Du bist einer der höchsten Menschen im Göttlichen Reich; alles, was du ertragen hast, wird dir im Göttlichen Reich vergolten."
  },
  AvgDialog_47164_Content_62 = {
    Text = "Komm, bete mit mir, Deborah."
  },
  AvgDialog_47164_Content_63 = {
    Text = "Nein... Miryam... bitte..."
  },
  AvgDialog_47164_Content_64 = {
    Text = "Sprich mir nach: „Das Leid soll vergolten werden...“"
  },
  AvgDialog_47164_Content_65 = {
    Text = "Das... das Leid... nein, Miryam..."
  },
  AvgDialog_47164_Content_66 = {
    Text = "Sprich mir nach: „Die Frevler sollen gegeißelt werden — denn der Herr richtet ihre Missetat.“"
  },
  AvgDialog_47164_Content_67 = {
    Text = "Miryam singt die Gebete, während sie an die Seite ihrer Freundin tritt."
  },
  AvgDialog_47164_Content_68 = {
    Text = "Lass mich ein Wort an Nord richten! Miryam... nur ein einziges Wort an ihn..."
  },
  AvgDialog_47164_Content_69 = {
    Text = "<Big:Ah!!!—>"
  },
  AvgDialog_47164_Content_7 = {
    Text = "Was ist los... Miryam?!"
  },
  AvgDialog_47164_Content_70 = {
    Text = "Qual flammt in ihrem Unterleib auf. Sie blickt hoch und sieht Miryams bleiche, schlangengleiche Hand, die den Dolch tief hineintreibt und einen purpurroten Pfad über ihren Bauch zieht."
  },
  AvgDialog_47164_Content_71 = {
    Text = "Miryam ist taub für die schrillen Schreie. Sie sieht nicht das von Entsetzen und Schmerz verzerrte Gesicht."
  },
  AvgDialog_47164_Content_72 = {
    Text = "Der Dolch bewegte sich stetig und spritzte warmes Blut auf Miryams Gesicht. Sie bete devot und trat den Weg zum Göttlichen Reich ein."
  },
  AvgDialog_47164_Content_73 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47164_Content_74 = {
    Text = "Tötet Miryam! Spaltet die Familie Ornn! Lang lebe unsere Allianz! Jubel!"
  },
  AvgDialog_47164_Content_75 = {
    Text = "Gläser klirren, während zügellose Gier sich mit dem Duft von Wein und Fleisch vermischt."
  },
  AvgDialog_47164_Content_76 = {
    Text = "Goliath leckt sich die Lippen und genießt den berauschenden Geschmack."
  },
  AvgDialog_47164_Content_77 = {
    Text = "Komm schon, mach weiter. Was ist los mit dir?"
  },
  AvgDialog_47164_Content_78 = {
    Text = "Euer... euer Gesicht..."
  },
  AvgDialog_47164_Content_79 = {
    Text = "Mein Gesicht?"
  },
  AvgDialog_47164_Content_8 = {
    Text = "Sie versuchte aufzustehen, stellte jedoch fest, dass ihr Körper und ihre Gliedmaßen an einem steinernen Altar gefesselt waren und sie sich nicht bewegen konnte."
  },
  AvgDialog_47164_Content_80 = {
    Text = "Er blickt auf die spiegelblanken Fliesen neben sich und sieht ein Gesicht, das einem Fisch gleicht."
  },
  AvgDialog_47164_Content_81 = {Text = "ARGH!!"},
  AvgDialog_47164_Content_82 = {
    Text = "Wunden öffnen sich auf seiner Brust, als würden unsichtbare Dolche sie einritzen. Seine Ohren und Augenbrauen verschwinden; seine Augäpfel quellen hervor und wandern an die Seiten seines Kopfes."
  },
  AvgDialog_47164_Content_83 = {
    Text = "Qual durchdringt den Nebel aus Alkohol und Adrenalin. Er bricht zu Boden, würgt vor Schmerz, seine Hände kratzen verzweifelt an seinem Gesicht."
  },
  AvgDialog_47164_Content_84 = {
    Text = "Was ist das? Ah!!"
  },
  AvgDialog_47164_Content_85 = {
    Text = "Eine Person, zwei, drei... im prunkvollen Bankettsaal fallen die Adeligen einer nach dem anderen zu Boden."
  },
  AvgDialog_47164_Content_86 = {
    Text = "Blutrote Risse erscheinen auf ihren Körpern, Blut und Fleisch formen uralte, groteske Muster."
  },
  AvgDialog_47164_Content_87 = {
    Text = "Ihre Schmerzensschreie vereinen sich zu einer gewaltigen Symphonie. Blut spritzt und füllt jeden Kelch."
  },
  AvgDialog_47164_Content_88 = {
    Text = "Das ist... das ist... ein Fische-Ritual!"
  },
  AvgDialog_47164_Content_89 = {
    Text = "Ja, das Fischmann-Ritual. Du musst von der Tragödie gehört haben, die der Familie Orne widerfahren ist."
  },
  AvgDialog_47164_Content_9 = {
    Text = "Ein Paar Hände streckte sich aus und ergriff ihre. Sie waren kalt und rutschig, wie eine blasse Schlange."
  },
  AvgDialog_47164_Content_90 = {
    Text = "Warum... Goliath?"
  },
  AvgDialog_47164_Content_91 = {Text = "Warum?"},
  AvgDialog_47164_Content_92 = {
    Text = "Goliath scheint einen urkomischen Witz gehört zu haben. Er erhebt sich vom Hochsitz und greift zu seiner Klinge."
  },
  AvgDialog_47164_Content_93 = {
    Text = "Mit euch zusammenzuarbeiten hätte mir einen kleinen Fetzen von Ornns Territorium eingebracht."
  },
  AvgDialog_47164_Content_94 = {
    Text = "Aber durch die Zusammenarbeit mit Miryam erlange ich Macht jenseits eures Verständnisses. Ich kann eure gesamten Häuser in Fischmenschen verwandeln und all euren Reichtum an mich reißen."
  },
  AvgDialog_47164_Content_95 = {
    Text = "Sag mir, Mr. Edmond, wenn du an meiner Stelle wärst, was würdest du wählen?"
  },
  AvgDialog_47164_Content_96 = {
    Text = "Wir... wir werden nicht kampflos aufgeben!"
  },
  AvgDialog_47164_Content_97 = {
    Text = "Ganz recht! Goliath, bei der Ehre der Familie Enom, werden wir—ugh!"
  },
  AvgDialog_47164_Content_98 = {
    Text = "Eine gewaltige Klinge fährt herab und spaltet den jungen Adeligen entzwei. Seine Ehre stirbt mit ihm."
  },
  AvgDialog_47164_Content_99 = {
    Text = "Die Türen fliegen auf, als eine Flut von Fischmenschen die Halle überschwemmt."
  },
  AvgDialog_47165_Content_1 = {
    Text = "Herzensfreund"
  },
  AvgDialog_47165_Content_10 = {
    Text = "Sei nicht nervös, Mr. Edmund. Miryam hat mir meine Freiheit genommen; wir teilen einen gemeinsamen Feind."
  },
  AvgDialog_47165_Content_100 = {
    Text = "Miryam, mach dir nicht zu viele Sorgen. Wir können gemeinsam an anderen Lösungen denken..."
  },
  AvgDialog_47165_Content_101 = {
    Text = "Es gibt keinen anderen Weg, Deborah. Nur noch eine Option bleibt..."
  },
  AvgDialog_47165_Content_102 = {
    Text = "Sie blickte auf, wischte ihre Tränen weg und streichelte sanft Deborahs Gesicht."
  },
  AvgDialog_47165_Content_103 = {
    Text = "Sie erinnerte sich an einige längst vergessene Fragen. Diese Fragen, vom Verlauf der Zeit begraben, tauchten nun wieder auf und erfüllten ihren Geist mit einem staubigen Dunst."
  },
  AvgDialog_47165_Content_104 = {
    Text = "Deborah, glaubst du an den König?"
  },
  AvgDialog_47165_Content_105 = {
    Text = "Natürlich..."
  },
  AvgDialog_47165_Content_106 = {
    Text = "Deborah, weißt du, was Glaube ist?"
  },
  AvgDialog_47165_Content_107 = {
    Text = "Mein Lehrer hat mir einmal gesagt, dass Glauben immer mit Verantwortung und Bedeutung zu tun hat, ohne Platz für etwas anderes."
  },
  AvgDialog_47165_Content_108 = {
    Text = "Hmm... Du machst es so kompliziert..."
  },
  AvgDialog_47165_Content_109 = {
    Text = "Es ist eigentlich ganz einfach. Deborah, du bist seit langem meine einzige wahre Freundin..."
  },
  AvgDialog_47165_Content_11 = {
    Text = "Miryam besitzt immense Macht. Du hast viele tapfere Krieger, aber sie zu beseitigen wird einen äußerst hohen Preis kosten."
  },
  AvgDialog_47165_Content_110 = {
    Text = "Ich habe dir höchste Ehre versprochen, dich zum ersten Bürger des Göttlichen Reiches zu machen. Ich habe versprochen, dein Zuhause zur glücklichsten Familie im Göttlichen Reich zu machen."
  },
  AvgDialog_47165_Content_111 = {
    Text = "Ich werde es tun, Deborah. Ich werde deine Hoffnungen für die Zukunft in Erinnerung behalten. Nun, ich verleihe dir diese Ehre."
  },
  AvgDialog_47165_Content_112 = {
    Text = "Das Reich der Götter wird gewiss kommen, und der Weg dorthin wird deinen Namen tragen. Jeder Gläubige und Bürger des Götterreichs wird sich an dich erinnern..."
  },
  AvgDialog_47165_Content_113 = {Text = "!!!"},
  AvgDialog_47165_Content_114 = {
    Text = "Warte, Miryam, ich..."
  },
  AvgDialog_47165_Content_115 = {
    Text = "Deborah hatte keine Zeit, Angst zu empfinden. Bevor sie ihren Satz beendet hatte, drang ein schlangenartiger schwarzer Nebel in ihren Körper ein. Sie fühlte sich schwindelig und sank auf Miryams Schulter."
  },
  AvgDialog_47165_Content_116 = {
    Text = "Sie können das nicht tun..."
  },
  AvgDialog_47165_Content_117 = {
    Text = "Ich muss das tun."
  },
  AvgDialog_47165_Content_118 = {
    Text = "Dein Vater und der König möchten dich nicht so sehen!"
  },
  AvgDialog_47165_Content_119 = {
    Text = "Du bist erst neun Jahre alt, Miryam. Du verstehst es nicht."
  },
  AvgDialog_47165_Content_12 = {
    Text = "Ich bin bereit, mit dir zusammenzuarbeiten. Das sind meine Aufrichtigkeiten."
  },
  AvgDialog_47165_Content_120 = {
    Text = "Vater und König, die wünschten, das Kommen des Reiches des Gottes zu witnessen."
  },
  AvgDialog_47165_Content_121 = {
    Text = "Erfülle ich ihre Wünsche nicht?"
  },
  AvgDialog_47165_Content_122 = {
    Text = "Aber... das ist unkorrekt..."
  },
  AvgDialog_47165_Content_123 = {
    Text = "Nur das Reich Gottes ist richtig."
  },
  AvgDialog_47165_Content_124 = {
    Text = "Miryams Ton war ruhig, als ob sie ein Stück Allgemeinwissen erzählte, das jeder verstehen sollte."
  },
  AvgDialog_47165_Content_125 = {
    Text = "Little Miryam sieht sich Jahre später an. Sie ist selbstbewusst, entschlossen und stark. Sie ist die unbestrittene Hohepriesterin von Lemuria und die einsame Gesandte des Reiches Gottes."
  },
  AvgDialog_47165_Content_126 = {
    Text = "Die Tochter, zitternd unter den Trümmern, ruft nach ihrem Vater, der keine Verbindung mehr zu ihr hat."
  },
  AvgDialog_47165_Content_127 = {
    Text = "Ich verstehe... Ich nehme an, es ist Zeit für mich zu gehen."
  },
  AvgDialog_47165_Content_128 = {
    Text = "Sie sah sie traurig an."
  },
  AvgDialog_47165_Content_129 = {
    Text = "Mögest du dein Göttliches Reich finden, Miryam."
  },
  AvgDialog_47165_Content_13 = {
    Text = "Die Wachen trugen mehrere Truhen in den Salon. Als die Truhen geöffnet wurden, strahlte das blendende goldene Licht auf Old Edmonds Gesicht und ließ seinen Geist für einen Moment benommen zurück."
  },
  AvgDialog_47165_Content_130 = {Text = "Ich werde."},
  AvgDialog_47165_Content_131 = {
    Text = "Sie wusste, dass es der letzte Segen und Abschied war. Kleine Miryam ging, als hätte sie nie existiert. Miryam warf keinen Blick an den Ort, an dem sie verschwunden war."
  },
  AvgDialog_47165_Content_132 = {
    Text = "Sie umarmte Deborah und klopfte sanft auf ihren Rücken, während sie leise ein lemurisches Wiegenlied summte, als würde sie ein Kind in den Schlaf wiegen."
  },
  AvgDialog_47165_Content_133 = {
    Text = "Draußen vom Fenster ist die Sonne untergegangen, und die Sterne beginnen, ihre jeweiligen Wege zu beschreiten."
  },
  AvgDialog_47165_Content_134 = {
    Text = "—Der Moment des himmlischen Ausrichtens rückt näher."
  },
  AvgDialog_47165_Content_14 = {
    Text = "Ich kann deine Aufrichtigkeit fühlen, Mr. Goliath... Was ist dein Plan?"
  },
  AvgDialog_47165_Content_15 = {
    Text = "Ich habe bereits die Pappas, Enom und mehrere andere prominente Familien der Reihe nach besucht."
  },
  AvgDialog_47165_Content_16 = {
    Text = "Die Armeen der verschiedenen Familien haben sich zu versammeln begonnen. Bevor sie aktiv werden, glaube ich, dass wir ein Treffen abhalten müssen."
  },
  AvgDialog_47165_Content_17 = {
    Text = "Ich werde dir alles über die Familie Ornn erzählen und meinen Rat geben."
  },
  AvgDialog_47165_Content_18 = {
    Text = "Ich werde sicherstellen, dass du Miryam bei minimalen Kosten tötest. Und..."
  },
  AvgDialog_47165_Content_19 = {
    Text = "Er beugte sich nah an das Ohr von Old Edmond."
  },
  AvgDialog_47165_Content_2 = {
    Text = "Bitte setzen Sie sich, Goliath von der Familie Orne."
  },
  AvgDialog_47165_Content_20 = {
    Text = "Um ehrlich mit Ihnen zu sein, Mr. Edmund, ich suche nach der richtigen Person, um tiefgründig zusammenzuarbeiten."
  },
  AvgDialog_47165_Content_21 = {
    Text = "Um ehrlich zu sein, wird die Stärke der Familie Edmond unter den großen Familien nicht als besonders stark angesehen. Genau deshalb bin ich bereit, mit dir zusammenzuarbeiten."
  },
  AvgDialog_47165_Content_22 = {
    Text = "Den Reichtum und die Ländereien der Orns, sogar Miryams Macht, ich kann einen Teil davon dir anbieten."
  },
  AvgDialog_47165_Content_23 = {
    Text = "Was ich suche, ist eine tiefe Allianz. Schließlich ist unser Ziel nicht nur, Miryam und die Familie On zu besiegen, oder?"
  },
  AvgDialog_47165_Content_24 = {
    Text = "Der alte Mann schaute Goliath mit einem wissenden Lächeln an."
  },
  AvgDialog_47165_Content_25 = {
    Text = "Hehehe, du ehrgeizige Kleine..."
  },
  AvgDialog_47165_Content_26 = {
    Text = "Deine Sicht ist weitreichend, Herr Goliath. In der Tat ist der Fall der Familie Ornn nur der Prolog."
  },
  AvgDialog_47165_Content_27 = {
    Text = "Unsere Allianz wird zweifellos eine neue Dynastie in dieses Land bringen..."
  },
  AvgDialog_47165_Content_28 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47165_Content_29 = {
    Text = "Schwester... Vater... Ah!..."
  },
  AvgDialog_47165_Content_3 = {
    Text = "Die Worte des alten Mannes behielten eine grundlegende aristokratische Raffinesse, aber sein Ton der Verachtung war keineswegs verborgen."
  },
  AvgDialog_47165_Content_30 = {
    Text = "Miryam? Miryam, geht es dir gut?"
  },
  AvgDialog_47165_Content_31 = {
    Text = "Miryam wachte schweißgebadet auf, ihr Rücken war durchnässt."
  },
  AvgDialog_47165_Content_32 = {
    Text = "Ihr Vater und ihre Schwester verschwanden aus ihrem Blickfeld, ersetzt durch Deborahs besorgtes Gesicht."
  },
  AvgDialog_47165_Content_33 = {
    Text = "Hast du von deiner Familie geträumt?"
  },
  AvgDialog_47165_Content_34 = {
    Text = "Ich habe meinen Vater und meine Schwester gesehen; sie hatten beide fischähnliche Gesichter... Vater sagte, sie hätten so seit zehntausenden von Jahren gelebt..."
  },
  AvgDialog_47165_Content_35 = {
    Text = "Er fragte mich: \"Wie lange muss ich noch warten...\""
  },
  AvgDialog_47165_Content_36 = {
    Text = "Deborah, ich... kann mich nicht mehr erinnern, wie mein Vater aussieht..."
  },
  AvgDialog_47165_Content_37 = {
    Text = "Miryam konnte nicht länger weitersprechen. Sie lehnte schwach gegen das Bettgitter."
  },
  AvgDialog_47165_Content_38 = {
    Text = "Deborah legte ein Taschentuch auf Miryams Stirn und klopfte sanft auf ihren Rücken."
  },
  AvgDialog_47165_Content_39 = {
    Text = "Du hattest in letzter Zeit Albträume... Deine Wunden sind noch nicht vollständig verheilt, also hör auf, darüber nachzudenken."
  },
  AvgDialog_47165_Content_4 = {
    Text = "Herr Edmond, ich verstehe Ihre Feindseligkeit gegenüber der Familie Orne vollkommen."
  },
  AvgDialog_47165_Content_40 = {
    Text = "Es ist in Ordnung. Sobald du deinen Körper wiederhergestellt hast und das Göttliche Reich hierher gebracht hast, wirst du bald wieder mit deiner Familie vereint sein."
  },
  AvgDialog_47165_Content_41 = {
    Text = "Es tut mir leid, Deborah... Ob in Lemuria oder jetzt, du hast mir so sehr geholfen..."
  },
  AvgDialog_47165_Content_42 = {
    Text = "Sagst du wieder Dinge, die ich nicht verstehen kann... Muß ich mich dafür entschuldigen?"
  },
  AvgDialog_47165_Content_43 = {
    Text = "Miryam schüttelte den Kopf und gab keine weitere Erklärung. Sie starrte mit einem komplexen Ausdruck auf Deborahs geschwollenen Bauch."
  },
  AvgDialog_47165_Content_44 = {
    Text = "Meine Wunden sind fast verheilt. Du wirst bald Mutter sein, also kümmere dich zuerst um dich selbst."
  },
  AvgDialog_47165_Content_45 = {
    Text = "Ich bin genauso gesund wie sie..."
  },
  AvgDialog_47165_Content_46 = {
    Text = "Ah! Miryam! Miryam, hör zu... Sie tritt mich!"
  },
  AvgDialog_47165_Content_47 = {
    Text = "Wirklich? Lass mich hören..."
  },
  AvgDialog_47165_Content_48 = {
    Text = "Miryam beugte sich herunter und lehnte sich nahe an Deborahs Bauch."
  },
  AvgDialog_47165_Content_49 = {
    Text = "Ah, es ist echt... Ich habe es gehört..."
  },
  AvgDialog_47165_Content_5 = {
    Text = "Die Familie Orne hat nun einen ungewöhnlichen Weg eingeschlagen..."
  },
  AvgDialog_47165_Content_50 = {
    Text = "Kind, schau, das ist deine Patentante, unsere Hohepriesterin Miryam. Sie hat dich gespürt, deshalb wussten wir frühzeitig, dass du ein Mädchen bist und haben Geschenke für deine Geburt vorbereitet."
  },
  AvgDialog_47165_Content_51 = {
    Text = "In der Zukunft wird sie unsere ganze Familie in das legendäre Gott-Reich mitnehmen!"
  },
  AvgDialog_47165_Content_52 = {
    Text = "Bis dahin wird dein Vater immer noch der Fahrer des Oberpriesters sein, und ich werde immer noch die Dienerin des Oberpriesters sein..."
  },
  AvgDialog_47165_Content_53 = {
    Text = "Im Göttlichen Reich sind keine Kutscher und Diener nötig."
  },
  AvgDialog_47165_Content_54 = {
    Text = "Das wird nicht funktionieren; es macht nicht so viel Spaß wie mit dir zusammen zu sein."
  },
  AvgDialog_47165_Content_55 = {
    Text = "Miryam blickte auf Deborahs Bauch und enthüllte ein komplexes Lächeln."
  },
  AvgDialog_47165_Content_56 = {
    Text = "Deborah, du bist meine einzige Freundin. Es gibt etwas, das ich dir sagen möchte..."
  },
  AvgDialog_47165_Content_57 = {
    Text = "Berichte dem Hohen Priester. Goliath wartet an der Tür."
  },
  AvgDialog_47165_Content_58 = {
    Text = "... Lass ihn rein."
  },
  AvgDialog_47165_Content_59 = {
    Text = "Sieht so aus, als müsste ich etwas länger warten, um diese Überraschung zu hören~"
  },
  AvgDialog_47165_Content_6 = {
    Text = "Ein ungewöhnlicher Weg? Ihr Freaks... Eure Existenz ist eine Blasphemie für alle auf diesem Kontinent."
  },
  AvgDialog_47165_Content_60 = {
    Text = "Deborah machte ein Gesicht zu Miryam und zog sich ins Nebenzimmer zurück. Goliath trat ein und betrachtete nachdenklich Deborahs Gestalt."
  },
  AvgDialog_47165_Content_61 = {
    Text = "Wie läuft die Kommunikation mit den anderen Familien?"
  },
  AvgDialog_47165_Content_62 = {
    Text = "In der Tat, Landbewohner sind schlauer als Perishiten, aber solange sie Mensch sind, werden die Dinge, die sie sich wünschen, nicht zu unterschiedlich sein."
  },
  AvgDialog_47165_Content_63 = {
    Text = "Ich habe jeder Familie gesagt, dass sie unsere engsten Verbündeten werden würden. Gemeinsam werden wir dich töten, die Familie Ornn zerstören und dann werde ich das Land, den Reichtum und die Macht unter ihnen aufteilen."
  },
  AvgDialog_47165_Content_64 = {
    Text = "Dieses Versprechen ist voller Schlupflöcher, aber diese Typen sind arrogant genug zu glauben, es sei ihr Schicksal, an der Spitze der Welt zu stehen, ohne einen Funken Zweifel."
  },
  AvgDialog_47165_Content_65 = {
    Text = "Ihre Armee versammelt sich. Der Ausrichtungs-Tag ist nur noch wenige Tage entfernt, und wir werden dann ein Fest veranstalten."
  },
  AvgDialog_47165_Content_66 = {
    Text = "Das wird sicherlich ein wirklich wunderbares Festmahl sein."
  },
  AvgDialog_47165_Content_67 = {
    Text = "Goliath grinste boshaft und zeigte seine haifischähnlichen scharfen Zähne."
  },
  AvgDialog_47165_Content_68 = {
    Text = "Du hast gute Arbeit geleistet."
  },
  AvgDialog_47165_Content_69 = {
    Text = "Wie wäre es mit dir? Wie läuft die Vorbereitung, um das Heilige Kind zu finden?"
  },
  AvgDialog_47165_Content_7 = {
    Text = "Vertraue mir, Mr. Edmund, es war ein Unfall. Diese Hexe, Miryam, hat all das verursacht."
  },
  AvgDialog_47165_Content_70 = {
    Text = "Ich habe jede einzelne Person innerhalb der Ornn-Familie durchsucht."
  },
  AvgDialog_47165_Content_71 = {
    Text = "Ich habe einige Babys gefunden, die im Moment der stellarischen Ausrichtung geboren werden sollen, aber ihre Familien glauben nicht an das Göttliche Reich."
  },
  AvgDialog_47165_Content_72 = {
    Text = "So eine Person ist nicht würdig, das Gefäß zur Erziehung des Königs zu sein."
  },
  AvgDialog_47165_Content_73 = {
    Text = "In diesem genauen Moment geboren zu werden und eine Familie zu haben, die an dein Gottes Reich glaubt, ist in der Tat eine schwere Aufgabe."
  },
  AvgDialog_47165_Content_74 = {
    Text = "Das Territorium der Ornn-Familie ist derzeit sehr begrenzt, und dein Glauben hat sich noch nicht verbreitet. Wir haben sehr wenige Personen, die wir finden können..."
  },
  AvgDialog_47165_Content_75 = {
    Text = "Es ist schade, dass Deborahs Kind erst in drei Monaten geboren wird. Andernfalls wäre sie eine perfekte Kandidatin gewesen."
  },
  AvgDialog_47165_Content_76 = {
    Text = "Also, was jetzt? Sollten wir denen, die unter den Ausrichten-Sternen geboren wurden, die Chance geben?"
  },
  AvgDialog_47165_Content_77 = {
    Text = "Wenn die Implantation wieder fehlschlägt, könnte der Heilige Fötus beschädigt werden... Ich kann es nicht zulassen, dass der König ein solches Risiko eingeht."
  },
  AvgDialog_47165_Content_78 = {
    Text = "Das ist knifflig... Ich kann mir keinen anderen Weg vorstellen, dir zu helfen."
  },
  AvgDialog_47165_Content_79 = {
    Text = "Goliath lehnte sich in seinem Stuhl zurück. Als er sah, wohin Miryam blickte, und ihren Gesichtsausdruck sah, richtete sich Goliath plötzlich auf."
  },
  AvgDialog_47165_Content_8 = {
    Text = "Ich weiß, dass Sie und mehrere andere Familien heimlich Pläne diskutieren, um die Familie Ornn zu belagern..."
  },
  AvgDialog_47165_Content_80 = {
    Text = "Warte einen Moment... Du denkst doch nicht etwa an..."
  },
  AvgDialog_47165_Content_81 = {
    Text = "Miryam drehte leicht ihren Kopf und sah zu Goliath. Ihr Blick ließ eine Gänsehaut über Goliaths Rücken bis ins Gehirn steigen."
  },
  AvgDialog_47165_Content_82 = {
    Text = "Das ist genau wie du, Miryam. Du bist wirklich @2 eine Verrückte."
  },
  AvgDialog_47165_Content_83 = {
    Text = "Mach dir keine Sorgen, es macht mir nichts aus. Meine Wahl war richtig. Nur durch die Zusammenarbeit mit jemandem, der so verrückt ist wie du, können wir erreichen, was andere nicht können."
  },
  AvgDialog_47165_Content_84 = {
    Text = "Geh und mach dich bereit... Ich muss auch mit den Vorbereitungen für mein Ritual beginnen."
  },
  AvgDialog_47165_Content_85 = {
    Text = "Heh... Wenn die Sterne in Alignment sind, wird es sicherlich eine prächtige Nacht. Bis dann, Hoher Priester."
  },
  AvgDialog_47165_Content_86 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47165_Content_87 = {
    Text = "Die Tür wurde aufgestoßen, und das sanfte Licht der untergehenden Sonne fiel auf Deborah."
  },
  AvgDialog_47165_Content_88 = {
    Text = "Sie summt eine lokale Melodie, während sie sanft ihren geschwollenen Bauch streichelt, vielleicht denkend daran, was sie für das Baby vorbereiten oder welchen Namen sie wählen soll."
  },
  AvgDialog_47165_Content_89 = {
    Text = "Als du siehst, wie Miryam hereinkommt, winkt sie ihr zu."
  },
  AvgDialog_47165_Content_9 = {
    Text = "Der alte Edmonds Körper spannte sich plötzlich an, und er setzte sich leicht auf. Goliath bemerkte all dies und lächelte ihn an."
  },
  AvgDialog_47165_Content_90 = {
    Text = "Miryam, bist du fertig mit Reden? Wie lief es?!"
  },
  AvgDialog_47165_Content_91 = {
    Text = "Sehr geschmeidig, Goliath war gut vorbereitet."
  },
  AvgDialog_47165_Content_92 = {
    Text = "Großartig! Bedeutet das, dass wir bald das göttliche Reich willkommen heißen werden!"
  },
  AvgDialog_47165_Content_93 = {
    Text = "Miryam lächelte sie an. Deborah, die sie schon so lange kannte, bemerkte leicht die Erschöpfung in Miryams Lächeln."
  },
  AvgDialog_47165_Content_94 = {
    Text = "Miryam, ich habe das Gefühl, dass dein Geist ein wenig abseits scheint."
  },
  AvgDialog_47165_Content_95 = {
    Text = "Du hast gesagt, dass alles mit Goliath reibungslos verlief... Was ist mit unserer Seite? Gibt es ein Problem?"
  },
  AvgDialog_47165_Content_96 = {
    Text = "Ich kann die richtige Person nicht finden, Deborah... Unser Glaube hat sich noch nicht ausgebreitet, und es gibt kein qualifiziertes Heiliges Kind..."
  },
  AvgDialog_47165_Content_97 = {
    Text = "Ich wollte auf die nächste Stern-Ausrichtung warten, aber Vater und der König drängen mich... ich kann nicht länger warten, Deborah."
  },
  AvgDialog_47165_Content_98 = {
    Text = "Sie umarmte Deborah und vergrub ihr Gesicht in Deborahs Bauch. Tränen fielen und durchnässen Deborahs Kleidung."
  },
  AvgDialog_47165_Content_99 = {
    Text = "Oh, wenn mein Kind nur zwei oder drei Monate früher geboren worden wäre, könnte ich dir geholfen haben..."
  },
  AvgDialog_47166_Content_1 = {
    Text = "Vergangenes Fata Morgana<br>"
  },
  AvgDialog_47166_Content_10 = {
    Text = "Ich hatte ursprünglich geplant, später einen Blick darauf zu werfen, wenn ich Zeit hätte, aber bevor ich dazu kam, ließ ich mich in das Chaos von Glens Rebellion verwickeln."
  },
  AvgDialog_47166_Content_100 = {
    Text = "Hehe, Junge, du fängst an, mich besser zu verstehen."
  },
  AvgDialog_47166_Content_101 = {
    Text = "Lord Goliath, warum hast du Miryam nicht getötet?"
  },
  AvgDialog_47166_Content_102 = {
    Text = "Töte sie, und ich wäre tatsächlich frei. Aber was nützt die Freiheit?"
  },
  AvgDialog_47166_Content_103 = {
    Text = "Goliath betrachtete den Schwarm von Vögeln über dem Meer und schloss die Augen voller Trost."
  },
  AvgDialog_47166_Content_104 = {
    Text = "Ich kann mit den Stämmen abrechnen, die die Perishiten besiegt haben, oder weiterhin die Küste mit meinem Stamm plündern. Aber das ist alles, was es dazu zu sagen gibt."
  },
  AvgDialog_47166_Content_105 = {
    Text = "Miryam gab mir Macht, aber es ist nicht genug. Weit nicht genug."
  },
  AvgDialog_47166_Content_106 = {
    Text = "Einfach rohe Stärke. Gegen diese mächtigen Truppen des Königreichs werden wir trotzdem gejagt, flüchten wie streunende Hunde in diesen Gewässern."
  },
  AvgDialog_47166_Content_107 = {
    Text = "Ich wünsche mir eine Macht, die größer ist als die, die Miryam mir verliehen hat."
  },
  AvgDialog_47166_Content_108 = {
    Text = "—Es nennt sich Macht, Abisha. Im Vergleich zur Macht ist Freiheit unbedeutend."
  },
  AvgDialog_47166_Content_109 = {
    Text = "Ein scharlachroter Glanz flackerte in seinen Augen, während er sich über die Lippen leckte und mit Freude lächelte."
  },
  AvgDialog_47166_Content_11 = {
    Text = "Ist das dein Zuhause?"
  },
  AvgDialog_47166_Content_110 = {
    Text = "Miryam kontrolliert nun die Familie Orne. Ich kann sie nutzen, um diese Macht exponentiell zu vervielfachen."
  },
  AvgDialog_47166_Content_111 = {
    Text = "Zu diesem Zeitpunkt werde ich diese Kräfte aus ihren Händen zurückholen."
  },
  AvgDialog_47166_Content_112 = {
    Text = "Aber Miryam ist so mächtig... dieses Risiko ist zu groß..."
  },
  AvgDialog_47166_Content_113 = {
    Text = "Abishai, ich bin der Anführer der Perishit, erinnerst du dich? Wir haben versagt und sind geflohen. Ich werde die Perishit zum Sieg führen."
  },
  AvgDialog_47166_Content_114 = {
    Text = "Was die Risiken betrifft... Was denkst du, habe ich noch zu verlieren?"
  },
  AvgDialog_47166_Content_115 = {
    Text = "Der Riese klopfte sanft Abishas Schulter, stand dann auf und ging zu Miryams Bett."
  },
  AvgDialog_47166_Content_116 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47166_Content_117 = {
    Text = "King... Mein Herr... Du hast mich verlassen... Warum..."
  },
  AvgDialog_47166_Content_118 = {
    Text = "Blut sickert durch die Verbände auf ihrer Brust, aber Miryam merkt es nicht. Sie liegt schwach auf dem Bett und starrt leer auf das endlose Meer."
  },
  AvgDialog_47166_Content_119 = {
    Text = "Seit du wach bist, wiederholst du diesen Satz die ganze Zeit. Kannst du es nicht ein wenig variieren?"
  },
  AvgDialog_47166_Content_12 = {
    Text = "Das Erscheinungsbild der Insel hat sich erheblich verändert. Es könnte Lemuria sein, oder vielleicht etwas anderes; ich bin mir nicht sicher."
  },
  AvgDialog_47166_Content_120 = {
    Text = "Du schaust aus wie ein totgefangener Fisch."
  },
  AvgDialog_47166_Content_121 = {
    Text = "Das heilige Embryo kann definitiv von einem Körper gehalten werden. Ich habe es sehr deutlich gespürt... Meine Methode ist korrekt!"
  },
  AvgDialog_47166_Content_122 = {
    Text = "Aber der König wies mich zurück... Der König wies mich zurück!"
  },
  AvgDialog_47166_Content_123 = {
    Text = "Goliath sah deutlich Miryams Schmerz und Verwirrung. Sie flogen vorbei."
  },
  AvgDialog_47166_Content_124 = {
    Text = "Der König sagte mir, dass er wieder erscheinen wird, wenn die Sterne zusammenfallen, und Lemuria zurückkehren wird..."
  },
  AvgDialog_47166_Content_125 = {
    Text = "Sterne, Sterne... Könnte es mit den Sternen zusammenhängen..."
  },
  AvgDialog_47166_Content_126 = {
    Text = "Verstanden, verstanden! Die Macht des Königs stammt von den Sternen. Vielleicht können nur die, die unter der richtigen Ausrichtung geboren wurden, den Heiligen Fötus des Königs nähren..."
  },
  AvgDialog_47166_Content_127 = {
    Text = "Die nächste Stern-Ausrichten wird bald eintreffen. Ich kann ein Neugeborenes finden... *Husten*"
  },
  AvgDialog_47166_Content_128 = {
    Text = "Aufregung blitzt in Miryams Augen auf. Sie steht plötzlich auf, verschlimmert ihre Wunden und beginnt heftig zu husten."
  },
  AvgDialog_47166_Content_129 = {
    Text = "Nehmt euch Zeit zur Genesung. Wenn du hier stirbst, wird auch dein König nicht überleben."
  },
  AvgDialog_47166_Content_13 = {
    Text = "Über zehntausend Jahre können sich viele Dinge ändern..."
  },
  AvgDialog_47166_Content_130 = {
    Text = "Ob es darum geht, das Heilige Kind zu suchen, den Heiligen Fetus zu fördern oder Anhänger zu versammeln... alles, was du als Nächstes tun musst, erfordert eine Menge Geld, Macht, Manpower und Autorität."
  },
  AvgDialog_47166_Content_131 = {
    Text = "Ich habe keine Zeit, mir darüber Sorgen zu machen..."
  },
  AvgDialog_47166_Content_132 = {
    Text = "Das ist genau der Grund, warum wir zusammenarbeiten. Ich habe Zeit—reichlich Zeit."
  },
  AvgDialog_47166_Content_133 = {
    Text = "Die Kraft der Ornn-Familie allein reicht nicht aus für das, was vor uns liegt. Wir brauchen die Unterstützung weiterer Familien auf diesem Kontinent."
  },
  AvgDialog_47166_Content_134 = {
    Text = "Alle Kräfte der Familie Ornn stehen dir zur Verfügung. Kümmere dich um diese Angelegenheiten."
  },
  AvgDialog_47166_Content_135 = {
    Text = "Bevor das nächste himmlische Ausrichten stattfindet, werde ich ein passendes Gefäß für des Königs heiliges Fötus finden."
  },
  AvgDialog_47166_Content_136 = {
    Text = "Miryam drehte leicht ihren Kopf und warf einen Blick auf Goliath."
  },
  AvgDialog_47166_Content_137 = {
    Text = "Kraft, Autorität, Reichtum, Würde... Ich weiß, was du zu tun versuchst, Perishit. Es ist mir egal."
  },
  AvgDialog_47166_Content_138 = {
    Text = "Dich am Leben zu halten, liegt daran, dass du klug genug bist. Mach nichts Dummes."
  },
  AvgDialog_47166_Content_139 = {
    Text = "Goliath zeigt ein hinterhältiges Lächeln."
  },
  AvgDialog_47166_Content_14 = {
    Text = "Miryam streichelte vorsichtig den feinen Sand am Ufer. Sie erinnerte sich an die Zerstörung ihres Zuhauses, während sie unter den Fischmenschen stand und hoffnungslos zusah, wie das Meer alles in Lemuria verschlang."
  },
  AvgDialog_47166_Content_140 = {
    Text = "Wie du wünschst, Hoher Priester."
  },
  AvgDialog_47166_Content_141 = {
    Text = "Miryam, wir sind zu Hause!"
  },
  AvgDialog_47166_Content_142 = {
    Text = "Entlang der gewundenen Küste des Gebiets der Familie Ornn stehen die seltsamen Fischmenschen, von einem Ruf angezogen, dicht am Ufer, wartend auf ihren Meister."
  },
  AvgDialog_47166_Content_143 = {
    Text = "Goliath betrachtete ihre seltsamen Formen, die Klinge in seiner Hand und ihre loyalen, aber törichten Augen mit Zufriedenheit."
  },
  AvgDialog_47166_Content_144 = {
    Text = "Er schaute auf das endlose fruchtbare Land hinter dem Murloc, wie ein Hai, der sein sterbendes Beute anvisiert."
  },
  AvgDialog_47166_Content_15 = {
    Text = "Jetzt ist sie hier wieder aufgetaucht. Bald wird sie Lemuria zurück in diese Gewässer bringen."
  },
  AvgDialog_47166_Content_16 = {
    Text = "Wo hast du die Statue gefunden? Bring mich dorthin."
  },
  AvgDialog_47166_Content_17 = {
    Text = "Folgen Sie mir."
  },
  AvgDialog_47166_Content_18 = {
    Text = "Was hast du vorhin gesagt, wonach du suchst? Das Relikt des Königs? Wozu wird es verwendet?"
  },
  AvgDialog_47166_Content_19 = {
    Text = "Erwecke den König: Sie müssen die silberne Substanz finden, die nach dem Tod des Königs zurückgelassen wurde. Sie ist für das Ritual unerlässlich."
  },
  AvgDialog_47166_Content_2 = {
    Text = "Der Schiffsboden kratzte über den feinen Sand und kam am Ufer zum Stillstand. Miryam steigt vom Schiff, blickt auf die einsame Insel vor ihr."
  },
  AvgDialog_47166_Content_20 = {
    Text = "Was beinhaltet dieses Ritual genau? Ist es ähnlich dem, das du verwendet hast, um uns in Murlocs zu verwandeln?"
  },
  AvgDialog_47166_Content_21 = {
    Text = "Also, wirst du die Leiche deines Königs ausgraben und sie auspeitschen? Er ist seit zehntausenden von Jahren tot; sein Körper würde wahrscheinlich bei einer Berührung zerfallen..."
  },
  AvgDialog_47166_Content_22 = {Text = "Zisch—"},
  AvgDialog_47166_Content_23 = {
    Text = "Das lila Leuchten an seinem Hals flackerte, und derqualvolle Schmerz ließ Goliath keuchen."
  },
  AvgDialog_47166_Content_24 = {
    Text = "Zeige weiterhin jeglichen Respektlosigkeit gegenüber dem König, und die Bestrafung wird weit schlimmer sein. Führe den Weg angemessen."
  },
  AvgDialog_47166_Content_25 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47166_Content_26 = {
    Text = "Das Unkraut und der dichte Wald wurden vom schwarzen Nebel geteilt, und ein kleiner Bucht offenbarte sich vor allen."
  },
  AvgDialog_47166_Content_27 = {
    Text = "Huh, als ich gerade eben von der anderen Richtung schaute, habe ich diese Bucht nicht gesehen? Und die Bucht selbst sieht so seltsam aus..."
  },
  AvgDialog_47166_Content_28 = {
    Text = "Das stimmt, sein Erscheinungsbild ändert sich oder verschwindet sogar, wenn man es aus verschiedenen Richtungen betrachtet. Ich nehme also an, es muss irgendeine Art von Zauberei oder ähnlichem sein..."
  },
  AvgDialog_47166_Content_29 = {
    Text = "Es ist ein Traum. Ein Traum, den der König erschaffen hat, um Lemuria vor den Eindringlingen zu schützen!"
  },
  AvgDialog_47166_Content_3 = {
    Text = "Die Insel ist extrem klein, wie ein zerklüftetes Riff. Antike und komplexe Vegetation bedeckt sie und erzählt eine lange Geschichte der Einsamkeit."
  },
  AvgDialog_47166_Content_30 = {
    Text = "Miryams Blick beginnt sich mit Aufregung zu füllen."
  },
  AvgDialog_47166_Content_31 = {Text = "\"Traum\"?"},
  AvgDialog_47166_Content_32 = {
    Text = "Wo wurde diese Statue gefunden?"
  },
  AvgDialog_47166_Content_33 = {
    Text = "Genau dort."
  },
  AvgDialog_47166_Content_34 = {
    Text = "Goliath deutete auf einen Altar, der nicht weit entfernt war. Der Altar war mit Unkraut bedeckt und kaum zu erkennen."
  },
  AvgDialog_47166_Content_35 = {
    Text = "Deborah holte die Statue von Tulu hervor und stellte sie auf den Altar. Die Basis passte perfekt zum Altar."
  },
  AvgDialog_47166_Content_36 = {
    Text = "Es scheint, als hätte sich ... nichts verändert... Habe ich es falsch platziert?"
  },
  AvgDialog_47166_Content_37 = {
    Text = "Wenn es dabei Änderungen gegeben hätte, wäre ich schon längst hineingegangen und hätte alle wertvollen Gegenstände mitgenommen."
  },
  AvgDialog_47166_Content_38 = {
    Text = "Er sah Miryam fragend an. Sie ging zum Altar, holte ein Messer heraus und schnitt sich in den Finger."
  },
  AvgDialog_47166_Content_39 = {
    Text = "Ein Tropfen blutrotes Blut fiel von den reinweißen Fingerspitzen und landete auf der Statue."
  },
  AvgDialog_47166_Content_4 = {
    Text = "Die verlorene Zivilisation Lemuria ist eine alte Legende, die unter den philistischen Stämmen weitergegeben wird."
  },
  AvgDialog_47166_Content_40 = {Text = "Whoosh—"},
  AvgDialog_47166_Content_41 = {
    Text = "Eine Welle scheint durch die Luft zu laufen und lässt die isolierte Insel unter den Füßen aller zu wackeln beginnen."
  },
  AvgDialog_47166_Content_42 = {
    Text = "Ist das? ......"
  },
  AvgDialog_47166_Content_43 = {
    Text = "Die Form der Bucht begann zu verschwommen, während das Meerwasser wirbelte und aufrecht aufstieg, und einen riesigen Strudel bildete, der wie ein riesiges Tor allen eine Einladung aussprach."
  },
  AvgDialog_47166_Content_44 = {
    Text = "König, das ist das Grab, das du für dich selbst vorbereitet hast... Das Feuer, das du für Lemuria hinterlassen hast, ist drinnen, nicht wahr?"
  },
  AvgDialog_47166_Content_45 = {
    Text = "Hey, warte! Hast du einen Todeswunsch?!"
  },
  AvgDialog_47166_Content_46 = {
    Text = "Miryam ging aufgeregt in Richtung des Zentrums des Wirbels, ignorierte Goliaths Rufe. Goliath fluchte und folgte."
  },
  AvgDialog_47166_Content_47 = {
    Text = "Ist das... unter Wasser?"
  },
  AvgDialog_47166_Content_48 = {
    Text = "Wir können hier atmen und sprechen... Es ist wahrhaft ein Wunder!"
  },
  AvgDialog_47166_Content_49 = {
    Text = "Eine enge Steintreppe erschien, die zum unergründlichen Meeresboden führte. Sie folgten Miryam nach unten."
  },
  AvgDialog_47166_Content_5 = {
    Text = "Nachdem ein Küstenausfall, geriet meine Flotte in einen Sturm und landete zufällig hier."
  },
  AvgDialog_47166_Content_50 = {
    Text = "Was ist das... da vorne?"
  },
  AvgDialog_47166_Content_51 = {
    Text = "Nachdem wir eine unbestimmte Zeit entlang der Steinstufen gegangen waren, erschien vor allen eine prächtige Ruine."
  },
  AvgDialog_47166_Content_52 = {
    Text = "Die dunklen Steinsäulen stehen feierlich wie enthauptete Wachen, die ihre Hellebarden zu beiden Seiten halten."
  },
  AvgDialog_47166_Content_53 = {
    Text = "Mauern und Straßen aus riesigen Steinen sind gebrochen und verfallen, während schmutzige Algen über ihre Überreste kriechen und Geschichten vergangener Ruhm und Jahrtausende einsamen Schicksals erzählen."
  },
  AvgDialog_47166_Content_54 = {
    Text = "Eine Gruppe von Menschen stapfte durch das Seewasser und den Kies und erklomm die zerbrochenen Stufen."
  },
  AvgDialog_47166_Content_55 = {
    Text = "Ist das... der Thron von Lemuria?"
  },
  AvgDialog_47166_Content_56 = {
    Text = "Ein zerbrochener Steinthron steht am Ende des Weges. Darauf ruht ein längst verstorbenes Skelett mit dem Kinn aufgestützt und blickt müde auf die Überreste vergangener Träume."
  },
  AvgDialog_47166_Content_57 = {
    Text = "Es bist du, mein Herr... Es ist dein heiliges Relikt! Ich habe dich gefunden!"
  },
  AvgDialog_47166_Content_58 = {
    Text = "Es sind zehntausende Jahre vergangen, zehntausende Jahre, seit ich dich das letzte Mal gesehen habe..."
  },
  AvgDialog_47166_Content_59 = {
    Text = "Miryam verbeugt sich andächtig und kniet vor den Knochen."
  },
  AvgDialog_47166_Content_6 = {
    Text = "Die Statue wurde genau hier gefunden."
  },
  AvgDialog_47166_Content_60 = {
    Text = "Sie stand auf, ihre Hände suchten im schmutzigen Körper. Als sie sie wieder herauszog, erschien ein schwaches silbernes Licht in den düsteren Ruinen."
  },
  AvgDialog_47166_Content_61 = {
    Text = "Eine silberne Kugel ruhte in Miryams Hand, ihre Oberfläche schimmerte mit fließendem Licht und warf traumartige Reflexionen unter Wasser. Miryam beugte sich näher, um ihr Atmen zu hören."
  },
  AvgDialog_47166_Content_62 = {
    Text = "Ist das das, was du... silberne Materie nennst?"
  },
  AvgDialog_47166_Content_63 = {
    Text = "Entgegen dem, was Talis gesagt hat... aber das muss es sein, was ich suche!"
  },
  AvgDialog_47166_Content_64 = {
    Text = "Bist du dir sicher...? Dieses Ding sieht nicht nach etwas Gutem aus..."
  },
  AvgDialog_47166_Content_65 = {
    Text = "Wenn du wieder schlecht über den König sprichst, werde ich dir den qualvollsten Tod gewähren."
  },
  AvgDialog_47166_Content_66 = {
    Text = "Ich mach nur Spaß, warum so ernst..."
  },
  AvgDialog_47166_Content_67 = {
    Text = "Du hast gesagt, dass das, was Talis beschrieben hat, anders ist, also wird seine Methode wahrscheinlich nicht funktionieren. Was ist dein nächster Schritt?"
  },
  AvgDialog_47166_Content_68 = {
    Text = "Ich habe einen Herzschlag darauf gehört... Es ist der Herzschlag des Königs..."
  },
  AvgDialog_47166_Content_69 = {
    Text = "Sein Leben schwindet, ich kann es fühlen... Ihm Leben zu geben wird den König auferwecken! Ja, es muss so sein!"
  },
  AvgDialog_47166_Content_7 = {
    Text = "Gibt es sonst noch etwas?"
  },
  AvgDialog_47166_Content_70 = {
    Text = "Sie zog ihren Dolch."
  },
  AvgDialog_47166_Content_71 = {
    Text = "Miryam! Was hast du vor?"
  },
  AvgDialog_47166_Content_72 = {
    Text = "Um die Wiedergeburt des Königs mit meinem eigenen Leben zu nähren... Was für eine hohe Ehre... Das ist meine Mission!"
  },
  AvgDialog_47166_Content_73 = {
    Text = "Segne mich, Deborah..."
  },
  AvgDialog_47166_Content_74 = {Text = "Zack—"},
  AvgDialog_47166_Content_75 = {
    Text = "Der rituelle Dolch stieß in Miryams Brust und drehte sich, um ein blutiges Loch auszuhöhlen."
  },
  AvgDialog_47166_Content_76 = {
    Text = "Zahlreiche Blutströme vermischten sich mit Meerwasser und wirbelten um den Ruin des Thrones. Die Skelette badeten in dem warmen Blut und beobachteten kalt die Szene vor ihnen."
  },
  AvgDialog_47166_Content_77 = {
    Text = "Miryam schien vollständig unbeeindruckt von dem Schmerz, ihr Lächeln wurde immer leidenschaftlicher."
  },
  AvgDialog_47166_Content_78 = {
    Text = "Sie hielt die geschmolzene Silberkugel und steckte sie in die Leere in ihrer Brust."
  },
  AvgDialog_47166_Content_79 = {Text = "Ugh—"},
  AvgDialog_47166_Content_8 = {
    Text = "Es gibt einige verstreut; die meisten wurden dir gerade gezeigt."
  },
  AvgDialog_47166_Content_80 = {
    Text = "In dem Moment, als es in Miryams Körper eindrang, strahlte die Lichtkugel ein starkes Licht aus und zappelnde vor Wahnsinn. Es wehrte sich."
  },
  AvgDialog_47166_Content_81 = {
    Text = "Miryams Leben fließt hinein, wird konsumiert und dann verworfen."
  },
  AvgDialog_47166_Content_82 = {
    Text = "Flammen verbrannten jede Ecke ihrer Haut, Klingen rissen in jedes Stück ihres Caro. Endloser Schmerz überwältigte Miryam, die sich bemühte, ihr verzerrtes Lächeln aufrecht zu erhalten."
  },
  AvgDialog_47166_Content_83 = {
    Text = "Mein Herr... bitte... akzeptieren... Sie mich..."
  },
  AvgDialog_47166_Content_84 = {Text = "Bang—"},
  AvgDialog_47166_Content_85 = {Text = "Miryam!"},
  AvgDialog_47166_Content_86 = {
    Text = "Miryam konnte nicht mehr festhalten und fiel in Ohnmacht."
  },
  AvgDialog_47166_Content_87 = {
    Text = "Entferne dieses unheilvolle Ding von ihrem Körper und bringe sie an Bord des Schiffes."
  },
  AvgDialog_47166_Content_88 = {
    Text = "Aber Miryam sagte..."
  },
  AvgDialog_47166_Content_89 = {
    Text = "Wenn du willst, dass sie lebt, tu es jetzt."
  },
  AvgDialog_47166_Content_9 = {
    Text = "Ich habe die gesamte Insel durchsucht und keine Ruinen gefunden, nur diese kleinen Kunstwerke."
  },
  AvgDialog_47166_Content_90 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47166_Content_91 = {
    Text = "Der Nebel und die Wellen haben sich verzogen, und die Insel bleibt als einsamer schwarzer Punkt in der Ferne zurück."
  },
  AvgDialog_47166_Content_92 = {
    Text = "Goliath lehnte sich gegen das Schiffsreling und genoss das sanfte Schaukeln des Schiffs."
  },
  AvgDialog_47166_Content_93 = {
    Text = "Lord Goliath, du scheinst in guter Stimmung zu sein. Erinnert dich diese Sonne an die Küste deiner Heimat, Philistia?"
  },
  AvgDialog_47166_Content_94 = {
    Text = "Die Küste meines Heimatlandes? Ha. Ich habe gerade gedacht, wenn ich Miryam jetzt töte, kann ich überall hingehen."
  },
  AvgDialog_47166_Content_95 = {
    Text = "Huh? Meister, das... scheint nicht richtig zu sein..."
  },
  AvgDialog_47166_Content_96 = {
    Text = "Miryams Macht übertrifft meine weit. Sie ist jetzt schwer verletzt; wenn sie heute versagt, könnte es ihre letzte Chance sein."
  },
  AvgDialog_47166_Content_97 = {
    Text = "Du würdest so etwas nicht tun."
  },
  AvgDialog_47166_Content_98 = {
    Text = "Was? Denkst du, ich bin irgendwie eine weichherzige Person?"
  },
  AvgDialog_47166_Content_99 = {
    Text = "Es ist nicht so... Wenn du wirklich vorhattest, sie umzubringen, hättest du das jetzt schon getan, anstatt mit mir hier zu plaudern."
  },
  AvgDialog_47167_Content_1 = {Text = "Mistbound"},
  AvgDialog_47167_Content_10 = {
    Text = "Wertlos. Der Riese sah seinen sterbenden Anhänger an, grinste bösartig und schloss die Augen."
  },
  AvgDialog_47167_Content_100 = {
    Text = "Du hast bereits Wege, mich zu kontrollieren. Meine Loyalität dir gegenüber sollte sogar noch standhafter sein."
  },
  AvgDialog_47167_Content_101 = {
    Text = "Unsere Partnerschaft bleibt effektiv. Niemand ist ein besserer Partner als ich. Akzeptiere meinen Dienst, und lass unsere Zusammenarbeit weitergehen."
  },
  AvgDialog_47167_Content_102 = {
    Text = "Wie du weißt, bin ich keine treue Person, aber was du brauchst, ist meine Fähigkeit, nicht meine Loyalität, oder?"
  },
  AvgDialog_47167_Content_103 = {
    Text = "Miryam sah Goliath überrascht an, und nach einem Moment lächelte sie."
  },
  AvgDialog_47167_Content_104 = {
    Text = "Deine Tricks und Niedertracht überraschen mich... Du hast recht, Goliath. Eine Person wie du kann viele Dinge tun, die ich nicht kann."
  },
  AvgDialog_47167_Content_105 = {
    Text = "Sollen wir unsere Zusammenarbeit fortsetzen?"
  },
  AvgDialog_47167_Content_106 = {
    Text = "Goliath lächelte und streckte seine Hand aus, aber Miryam ignorierte sie und wandte sich ab, um in Richtung des Schiffsverdecks zu gehen."
  },
  AvgDialog_47167_Content_107 = {
    Text = "Von nun an nenne mich den Hohen Priester."
  },
  AvgDialog_47167_Content_108 = {
    Text = "Goliath zog seine Hand zurück und berührte das Mal an seinem Hals. Er lächelte, während er auf das Meer schaute, seine neuen Reißzähne glänzten scharf im Sonnenlicht."
  },
  AvgDialog_47167_Content_109 = {
    Text = "Es war mir ein Vergnügen, mit dir zu arbeiten, Hoher Priester."
  },
  AvgDialog_47167_Content_11 = {
    Text = "Seufze um unser Licht, unsere Hoffnung."
  },
  AvgDialog_47167_Content_12 = {
    Text = "In den Ozean verbannt, rufen wir aus, klagen und vergießen all unsere Tränen ..."
  },
  AvgDialog_47167_Content_13 = {
    Text = "\"Ist es eine Phantasmagorie vor dem Tod?\" fragte der Riese."
  },
  AvgDialog_47167_Content_14 = {
    Text = "Eine alte, unheimliche Melodie erreichte seine Ohren. Durch den dichten Nebel trat die Gestalt einer Frau in seiner verschwommenen Sicht auf."
  },
  AvgDialog_47167_Content_15 = {
    Text = "Ah, Miryam, es ist er, dieser philistische Riese! So viele Legenden über ihn entlang der Küste..."
  },
  AvgDialog_47167_Content_16 = {
    Text = "Steht er kurz vor dem Sterben?"
  },
  AvgDialog_47167_Content_17 = {
    Text = "Er wird nicht sterben."
  },
  AvgDialog_47167_Content_18 = {
    Text = "Ein sanftes, kaltes Gefühl strömt von dort, wo die schwarze Schlange ihren Hals umschlingt. Die trüben, dunklen Augen des Riesen werden allmählich klar."
  },
  AvgDialog_47167_Content_19 = {
    Text = "Hexe, es ist die Hexe!"
  },
  AvgDialog_47167_Content_2 = {Text = "@2—"},
  AvgDialog_47167_Content_20 = {
    Text = "Die Ereignisse im Territorium der Familie Orne breiteten sich über die Meere aus; sie trat aus dem Nebel der Legende hervor und stand vor den Sterblichen."
  },
  AvgDialog_47167_Content_21 = {
    Text = "Die philistäischen Hyänen erkannten, was geschah. Sie begannen zu fliehen oder sprangen auf das kleine Boot für einen letzten, verzweifelten Kampf."
  },
  AvgDialog_47167_Content_22 = {
    Text = "Miryam sah den verblüfften Riesen an, lächelte und deutete in die Ferne. Sie klopfte Deborah auf die Schulter und drehte das Boot um."
  },
  AvgDialog_47167_Content_23 = {
    Text = "Sie hat kein Interesse am Rennen und Kämpfen der Hyäne."
  },
  AvgDialog_47167_Content_24 = {
    Text = "Schwarze Schlangen schlängeln sich, jagen, beißen und verschlingen. Im dichten Nebel über dem Meer tauchen immer mehr zerbrochene Leichen auf."
  },
  AvgDialog_47167_Content_25 = {
    Text = "Das stille Gemetzel endete schnell und hinterließ ein blutgetränktes Meer und den verwirrten Ausdruck des Riesen."
  },
  AvgDialog_47167_Content_26 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47167_Content_27 = {
    Text = "Miryam, jetzt wo du ihn gefunden hast, warum weggehen?"
  },
  AvgDialog_47167_Content_28 = {
    Text = "Die Suche nach meinem Herrn ist eine heilige Angelegenheit. Er würde es nicht wollen, dass ich dies an einem so schmutzigen Ort bespreche."
  },
  AvgDialog_47167_Content_29 = {
    Text = "Aber du hast kein Wort zu diesem großen Kerl gesagt... Wird er nach dir suchen?"
  },
  AvgDialog_47167_Content_3 = {
    Text = "Der Riese grunzte und zog den scharfen Pfeil aus seiner Schulter."
  },
  AvgDialog_47167_Content_30 = {
    Text = "Warte einen Moment, ihr beiden!"
  },
  AvgDialog_47167_Content_31 = {
    Text = "Eine Stimme durchdrang den dichten Nebel. Deborah streckte ihre Zunge in Richtung Miryam heraus und brachte das Boot allmählich zum Stillstand."
  },
  AvgDialog_47167_Content_32 = {
    Text = "Bald stoppte ein ramponiertes Holzboot vor ihrem Schiff."
  },
  AvgDialog_47167_Content_33 = {
    Text = "Deine Giftstoffe wurden nicht vollständig beseitigt. Angesichts der Segelgeschwindigkeit des Perishit kannst du dich eine Weile ausruhen, bevor du zu mir zurückkehrst."
  },
  AvgDialog_47167_Content_34 = {
    Text = "Im Vergleich zu einem entscheidenden Deal ist diese kleine Verletzung nichts."
  },
  AvgDialog_47167_Content_35 = {
    Text = "Ich habe nie gesagt, dass ich einen Deal mit dir machen wollte."
  },
  AvgDialog_47167_Content_36 = {
    Text = "Ich möchte nicht deine Zeit verschwenden, Meisterhexe.\nIch weiß über Lemuria Bescheid und ich glaube, das ist der Grund, warum du mich gefunden hast."
  },
  AvgDialog_47167_Content_37 = {
    Text = "Weißt du, was ich mir wünsche?"
  },
  AvgDialog_47167_Content_38 = {
    Text = "Was du dem Perishiten im Oren Manor angetan hast, hat sich über die Meere verbreitet. Offen gesagt, ich habe diese Geschichten zuvor nie geglaubt."
  },
  AvgDialog_47167_Content_39 = {
    Text = "Aber jetzt hast du dich mir genähert. Es muss einen Grund dafür geben."
  },
  AvgDialog_47167_Content_4 = {
    Text = "Vergiftetes Blut spritzte von seiner Schulter auf das Deck und erschien im Sonnenlicht schmutzig schwarz."
  },
  AvgDialog_47167_Content_40 = {
    Text = "Es heißt, dass du sehr an diesen schwarzen Statuen interessiert bist. Ich habe sie gefunden und weiß, wofür sie stehen."
  },
  AvgDialog_47167_Content_41 = {
    Text = "Sag mir, was du weißt."
  },
  AvgDialog_47167_Content_42 = {
    Text = "Bevor ich das, Lady Witch, vielleicht können wir eine Zusammenarbeit erreichen."
  },
  AvgDialog_47167_Content_43 = {
    Text = "Ich habe deine große Macht erlebt... Ich glaube, du solltest in der Lage sein, mir diese Macht zu verleihen?"
  },
  AvgDialog_47167_Content_44 = {
    Text = "Ich habe viele Möglichkeiten, dich zum Reden zu bringen, Perishit. Glaubst du, du bist qualifiziert, einen Deal zu machen?"
  },
  AvgDialog_47167_Content_45 = {
    Text = "Du missverstehst, Meisterhexe... Du hast mir das Leben gerettet. Selbst wenn du nicht mit mir handeln möchtest, werde ich dir dennoch alle Informationen, die ich besitze, ohne Vorbehalt anbieten."
  },
  AvgDialog_47167_Content_46 = {
    Text = "Was ich mit dir tauschen möchte, ist nicht diese Information."
  },
  AvgDialog_47167_Content_47 = {
    Text = "Was kannst du sonst noch bieten?"
  },
  AvgDialog_47167_Content_48 = {
    Text = "Meine Loyalität."
  },
  AvgDialog_47167_Content_49 = {
    Text = "Ich interessiere mich nicht für deine Loyalität, Goliath."
  },
  AvgDialog_47167_Content_5 = {
    Text = "Beeindruckend, Glen... Perishite... diese giftigen Dinge jetzt benutzen..."
  },
  AvgDialog_47167_Content_50 = {
    Text = "Ist das so? Ich hörte von deiner Kontrolle über die Ornn-Familie, wirklich beeindruckend... Lady Witch, du brauchst Personal für eine bestimmte große Aufgabe, richtig?"
  },
  AvgDialog_47167_Content_51 = {
    Text = "Wie viele Menschen kannst du nach all deinen mühsamen Anstrengungen kommandieren? Wer kann dir beim Verfolgen des geben, was du dir wünschst, helfen?"
  },
  AvgDialog_47167_Content_52 = {
    Text = "Ehrlich gesagt, meine Dame, du bist mächtig, aber Angelegenheiten des Herzens, Macht und echtes Töten liegen nicht in deinem Fachgebiet."
  },
  AvgDialog_47167_Content_53 = {
    Text = "Ich weiß nicht, was dein großes Unterfangen ist. Aber du wirst definitiv meine Hilfe benötigen."
  },
  AvgDialog_47167_Content_54 = {
    Text = "Bitte akzeptiere meine Loyalität! Sie wird dir großen Nutzen bringen und keinen Schaden."
  },
  AvgDialog_47167_Content_55 = {
    Text = "Miryam starrte ihn schweigend an. Nach einem Moment nickte sie."
  },
  AvgDialog_47167_Content_56 = {
    Text = "Deine Überzeugung hat mich überzeugt, Goliath. Du hast deine Fähigkeit bewiesen."
  },
  AvgDialog_47167_Content_57 = {
    Text = "Jetzt wirf deine Klinge ins Aequor."
  },
  AvgDialog_47167_Content_58 = {
    Text = "Mein Messer..."
  },
  AvgDialog_47167_Content_59 = {
    Text = "Goliath warf einen Blick auf die riesige Klinge, die seit Jahren bei ihm war, biss die Zähne zusammen und warf sie ins Meer."
  },
  AvgDialog_47167_Content_6 = {
    Text = "Die Vision des Riesen verschwamm, und sein Geist wurde schwindelig. Er konnte sich nicht mehr halten und kollabierte mit einem Krachen."
  },
  AvgDialog_47167_Content_60 = {
    Text = "Das Schiff wackelte, als ob etwas den Meeresboden unter ihm bewegte."
  },
  AvgDialog_47167_Content_61 = {
    Text = "Miryam streckte die Hand aus. Die riesige Klinge sprang aus dem Meer und strahlte ein dunkles Licht aus, wie nie zuvor gesehen."
  },
  AvgDialog_47167_Content_62 = {
    Text = "Die massive Klinge fiel in Miryams Hand, in ihren zarten Fingern so leicht wie eine Feder gehalten."
  },
  AvgDialog_47167_Content_63 = {
    Text = "Hast du Angst vor Schmerz?"
  },
  AvgDialog_47167_Content_64 = {
    Text = "Ich genieße den Schmerz, meine Dame Hexe."
  },
  AvgDialog_47167_Content_65 = {
    Text = "Goliath lächelte und kniete halb vor Miryam."
  },
  AvgDialog_47167_Content_66 = {
    Text = "Miryam setzte die riesige Klinge an Goliaths Hals."
  },
  AvgDialog_47167_Content_67 = {
    Text = "Meister Goliath!"
  },
  AvgDialog_47167_Content_68 = {Text = "Zack—"},
  AvgDialog_47167_Content_69 = {
    Text = "Die massive Klinge schnitt durch Goliaths Hals und zertrennte ihn mühelos in zwei, während das Blut herausspritzte."
  },
  AvgDialog_47167_Content_7 = {
    Text = "Goliath... Der riesige Goliath ist endlich gefallen!"
  },
  AvgDialog_47167_Content_70 = {
    Text = "Bevor jemand in der Nähe reagieren konnte, flackerte ein schwaches violett-schwarzes Licht an der Wunde an Goliaths Hals."
  },
  AvgDialog_47167_Content_71 = {
    Text = "Es bewegt sich und schnitzt ein kompliziertes und antikes Muster auf die dunkle Haut."
  },
  AvgDialog_47167_Content_72 = {Text = "Ugh!!!—"},
  AvgDialog_47167_Content_73 = {
    Text = "Intensiver Schmerz durchströmte Goliath. Er kam nicht nur von der Wunde, sondern durchzog seinen ganzen Körper."
  },
  AvgDialog_47167_Content_74 = {
    Text = "Schweiß rann von der Stirn des Riesen. Er gritt seine Zähne zusammen, sein ganzer Körper zitterte, während er gegen den Schmerz kämpfte."
  },
  AvgDialog_47167_Content_75 = {
    Text = "In unerträglichem Schmerz sprießen flossenartige Klingen aus Goliaths Ohren, seine Zähne werden scharf und geschichtet, und seine Augen nehmen ein blutrot an."
  },
  AvgDialog_47167_Content_76 = {
    Text = "Lord Goliath... du... du jetzt..."
  },
  AvgDialog_47167_Content_77 = {
    Text = "Dies ist ein unglaublich langer Prozess. Goliath hatte das Gefühl, ein Jahr lang unerträgliche Schmerzen erlitten zu haben. Während dieser langen Zeit starb er in Qual und wurde inmitten des Schmerzes wiedergeboren."
  },
  AvgDialog_47167_Content_78 = {
    Text = "Als das Bewusstsein des Goliaths wieder klar wurde, erkannte er, dass das Ritual schon lange beendet war. Er lag mit dem Gesicht nach unten auf dem Schiff, sein Schweiß vom Schmerz durchdrang das Deck."
  },
  AvgDialog_47167_Content_79 = {
    Text = "Er schaute auf sein Spiegelbild im Meer. Die Züge eines Meermanns waren deutlich an seinem riesigen Körper sichtbar. Ein wilder Hai zeigte sich vor allen."
  },
  AvgDialog_47167_Content_8 = {
    Text = "Sein Kopf gehört mir! Niemand wird ihn mir wegnehmen!!!"
  },
  AvgDialog_47167_Content_80 = {
    Text = "Der Effekt, ein Meermann zu werden, hängt von deinem eigenen Potenzial ab. Du bist sehr talentiert, Goliath."
  },
  AvgDialog_47167_Content_81 = {
    Text = "Genieße deine Stärke."
  },
  AvgDialog_47167_Content_82 = {
    Text = "Ein beispielloser Kraftschub durchströmte Goliaths Körper. Er hob mühelos die riesige Klinge neben sich an und schwang sie in Richtung Wasser."
  },
  AvgDialog_47167_Content_83 = {Text = "Boom—"},
  AvgDialog_47167_Content_84 = {
    Text = "Die ruhige See schwoll mit massiven Wellen, die zwei kleine Boote hin und her warfen und sie heftig schaukelten."
  },
  AvgDialog_47167_Content_85 = {
    Text = "Hehehehe... Hahahaha!!!"
  },
  AvgDialog_47167_Content_86 = {
    Text = "Inmitten des heftigen Zitterns brach Goliath in lautes Lachen aus. Er drehte sich zu Miryam um, das rote Licht in seinen Augen blitzte heftig."
  },
  AvgDialog_47167_Content_87 = {
    Text = "Vielen Dank, Lady Hexe. Ich werde die Macht, die du mir gegeben hast, sehr genießen."
  },
  AvgDialog_47167_Content_88 = {
    Text = "Entschuldigung, ich habe keine Zeit, dir meine Loyalität zu versichern. Die philiströsen Verräter und Feinde warten darauf, von mir erledigt zu werden."
  },
  AvgDialog_47167_Content_89 = {
    Text = "Gib mir keine Schuld. Gib dir selbst die Schuld dafür, dass du unvorsichtig warst. Von jetzt an werde ich dich mit dem Blut unserer Feinde ehren!"
  },
  AvgDialog_47167_Content_9 = {
    Text = "Die einst ängstlichen Perishiten strömten jetzt auf Goliath zu, wie mutige Hyänen um die Leiche eines Löwen."
  },
  AvgDialog_47167_Content_90 = {
    Text = "Goliath schwang plötzlich sein Schwert auf Miryam. Doch als die mächtige Klinge sich ihr näherte, fror sie abrupt ein und verlor all ihre Kraft."
  },
  AvgDialog_47167_Content_91 = {Text = "Hmm—ah!!"},
  AvgDialog_47167_Content_92 = {
    Text = "Die Narbe an Goliaths Hals leuchtete mit einem schlangenartigen, lila Licht. Er brach vor Schmerz zusammen, als der stechende, beissende Schmerz mit Wut zurückkam, und die Kraft in ihm ohne eine Spur verschwand."
  },
  AvgDialog_47167_Content_93 = {
    Text = "Was... hast... du... getan..."
  },
  AvgDialog_47167_Content_94 = {
    Text = "Ich bin der Hohe Priester von Lemuria. Ich bin in den Angelegenheiten, die du erwähnt hast, tatsächlich nicht geschickt, aber ich verstehe, was Menschlichkeit ist, Perishit."
  },
  AvgDialog_47167_Content_95 = {
    Text = "Schmerz und Macht, ich gewähre dir beides. Egal wo du bist, egal wie stark du wirst, ich kann deine Macht entziehen und deinen Schmerz nach Belieben wiederherstellen."
  },
  AvgDialog_47167_Content_96 = {
    Text = "Du genießt es, nicht wahr?"
  },
  AvgDialog_47167_Content_97 = {
    Text = "Beeindruckend... Lady Witch..."
  },
  AvgDialog_47167_Content_98 = {
    Text = "Sag mir, was du weißt, und ich werde dir einen schmerzfreien Tod gewähren."
  },
  AvgDialog_47167_Content_99 = {
    Text = "Es ist nur eine kleine Episode... Warum sich die Mühe machen, Herrin Hexe?"
  },
  AvgDialog_47168_Content_1 = {Text = "Blutfest"},
  AvgDialog_47168_Content_10 = {
    Text = "Es ist okay, es ist okay, nur ein Familientreffen. Ist dein Körper in Ordnung?"
  },
  AvgDialog_47168_Content_100 = {
    Text = "Hahaha, es ist nicht so einfach!"
  },
  AvgDialog_47168_Content_101 = {
    Text = "Zauber, Körper und..."
  },
  AvgDialog_47168_Content_102 = {
    Text = "Seine bleichen Augen rissen auf, und er murmelte plötzlich einen harten, lautlosen Zauberspruch."
  },
  AvgDialog_47168_Content_103 = {Text = "Ah!—"},
  AvgDialog_47168_Content_104 = {
    Text = "Miryam kniet auf dem Boden. Nadelartige Schmerzen überfallen ihren Geist und überwältigen sie mit immensem Leiden."
  },
  AvgDialog_47168_Content_105 = {
    Text = "@2, denkst du, ich weiß nicht, was du denkst?"
  },
  AvgDialog_47168_Content_106 = {
    Text = "Nenne mich \"Vater\" und tue Dinge für mich... Aber was du wirklich wünschst, ist etwas anderes, nicht wahr?"
  },
  AvgDialog_47168_Content_107 = {
    Text = "Miryam, ich weiß nicht, wie dein Heimatdorf aussieht, aber offenbar hast du keinen Schimmer, was Kämpfen bedeutet."
  },
  AvgDialog_47168_Content_108 = {
    Text = "Wenn ich ein Dummkopf wäre, wäre ich mit sechs Jahren in der Scheune ertrunken und hätte es bis heute nicht geschafft."
  },
  AvgDialog_47168_Content_109 = {
    Text = "Wie ein unsichtbares Seil, das straffer gezogen wird, wächst Miryams seelischer Schmerz intensiver."
  },
  AvgDialog_47168_Content_11 = {
    Text = "Fast fertig. Ah, ist der große Bruder auch hier?"
  },
  AvgDialog_47168_Content_110 = {
    Text = "Du bist stark, aber was soll's? Du bist nur ein Jagdhund; du tust, was ich dir sage!"
  },
  AvgDialog_47168_Content_111 = {
    Text = "Mein Zweck ist jetzt erfüllt, und ich benötige dich im Moment nicht. Dich wiederzubeleben wäre lästig, aber eine Waffe mit eigenen Gedanken zu behalten ist noch lästiger."
  },
  AvgDialog_47168_Content_112 = {
    Text = "Also, stirb einfach einmal mehr. Keine Sorge, ich lasse dich die Sonne wieder sehen, wenn ich dich brauche..."
  },
  AvgDialog_47168_Content_113 = {
    Text = "Talis funkelte Miryam an und beschwor einen Zauber. Das unsichtbare Seil schnürte sich zu einer Schlinge um Miryams Hals."
  },
  AvgDialog_47168_Content_114 = {
    Text = "Talis zieht plötzlich den Griff an der Schlinge..."
  },
  AvgDialog_47168_Content_115 = {
    Text = "??! Was... passiert gerade?!"
  },
  AvgDialog_47168_Content_116 = {
    Text = "Die Schlinge war immer noch da, aber Talis konnte seine Kontrolle darüber nicht spüren. Egal wie er Zauber wirkte, das Seil lag einfach da, regungslos."
  },
  AvgDialog_47168_Content_117 = {Text = "Whoosh—"},
  AvgDialog_47168_Content_118 = {Text = "Ah!!—"},
  AvgDialog_47168_Content_119 = {
    Text = "Ein scharfer Schmerz durchfuhr Taliss Körper. Eine lange, gerade frische Wunde erschien auf seiner Brust, als hätte jemand sie sorgfältig und absichtlich mit einem Dolch geschnitten."
  },
  AvgDialog_47168_Content_12 = {
    Text = "Talis lächelte und verbeugte sich vor ihm."
  },
  AvgDialog_47168_Content_120 = {
    Text = "Die Gäste im Saal verstummten schnell, standen still, während die Wachen sie mit Waffen umzingelten, wagten es jedoch nicht, sich Miryam weiter zu nähern."
  },
  AvgDialog_47168_Content_121 = {
    Text = "Das... Was ist das...?"
  },
  AvgDialog_47168_Content_122 = {
    Text = "In meinem Heimatland nennt man es das Murloc-Ritual."
  },
  AvgDialog_47168_Content_123 = {
    Text = "Früher musste ich mit einem Dolch den Körper einer Person aufschneiden und göttliches Blut in ihren Körper infundieren. Aber jetzt ist das nicht mehr nötig."
  },
  AvgDialog_47168_Content_124 = {
    Text = "Trinke einfach mein Blut und katalysiere es mit meiner Macht, dann wird das Ritual vollendet sein."
  },
  AvgDialog_47168_Content_125 = {
    Text = "Dein Blut... wird hinzugefügt, hinzugefügt zu..."
  },
  AvgDialog_47168_Content_126 = {
    Text = "Im Wein, das ist richtig. Bei diesem Festmahl hast du bereits davon gekostet."
  },
  AvgDialog_47168_Content_127 = {
    Text = "Miryam steht auf und klopft den Staub von ihrem Körper."
  },
  AvgDialog_47168_Content_128 = {
    Text = "Du... hast das bereits durchdacht..."
  },
  AvgDialog_47168_Content_129 = {
    Text = "Die Menschen in dieser Welt haben sich verändert. Glauben, Familie, Würde... nichts davon hat in deinen Augen Wert. Das weiß ich nur zu gut, Talis."
  },
  AvgDialog_47168_Content_13 = {
    Text = "Ich bin auch gerade angekommen und bin dabei, meinem Vater ein Geschenk zu überreichen."
  },
  AvgDialog_47168_Content_130 = {
    Text = "Keine Sorgen, ich werde eine bessere Welt schaffen. Dir zu helfen, Häuptling zu werden, wird die Ornn-Familie zu meinen Verbündeten machen und mich bei dieser heiligen und großartigen Mission unterstützen."
  },
  AvgDialog_47168_Content_131 = {
    Text = "Du hast grundlegende Herzen, unwürdig für das Reich der Götter. Aber du hast die Mission meiner Wiedergeburt erfüllt. Dies ist das Geschenk, das ich dir zurückgebe."
  },
  AvgDialog_47168_Content_132 = {
    Text = "Du kannst ... mit mir handeln ... du musst nicht ..."
  },
  AvgDialog_47168_Content_133 = {
    Text = "Jagdhunde haben kein Recht zu handeln. Also kann ich nur dein Meister werden. Jetzt, denke ich, qualifiziere ich mich."
  },
  AvgDialog_47168_Content_134 = {
    Text = "Ich möchte jemanden wiederbeleben. Sag mir, was soll ich tun?"
  },
  AvgDialog_47168_Content_135 = {
    Text = "Ich sagte: \"Kannst du mich leben lassen?\""
  },
  AvgDialog_47168_Content_136 = {Text = "Ah!!—"},
  AvgDialog_47168_Content_137 = {
    Text = "Miryam sagte nichts. Eine tiefe Wunde erschien an Talis, und Blut spritzte heraus."
  },
  AvgDialog_47168_Content_138 = {
    Text = "Ich sage! Ich sage!"
  },
  AvgDialog_47168_Content_139 = {
    Text = "In meinem Büro... in der Schublade... gibt es ein Buch, das alle meine Forschungsergebnisse aufzeichnet."
  },
  AvgDialog_47168_Content_14 = {
    Text = "Alright, nun sind alle Brüder anwesend."
  },
  AvgDialog_47168_Content_140 = {
    Text = "Alles über den Golem steht darin geschrieben!"
  },
  AvgDialog_47168_Content_141 = {
    Text = "Miryam wirft ihm einen Blick zu und nickt."
  },
  AvgDialog_47168_Content_142 = {
    Text = "Ich weiß, dass du die Wahrheit sagst."
  },
  AvgDialog_47168_Content_143 = {
    Text = "Du hast recht, die Lemurianer haben solche Kämpfe nicht."
  },
  AvgDialog_47168_Content_144 = {
    Text = "Jedoch, sobald man eine göttliche Mission zu erfüllen hat, wird das Lernen dieser Dinge nicht schwierig."
  },
  AvgDialog_47168_Content_145 = {
    Text = "Das stimmt, das stimmt... Kann ich jetzt gehen?"
  },
  AvgDialog_47168_Content_146 = {Text = "ARGH!!"},
  AvgDialog_47168_Content_147 = {
    Text = "Wunden erschienen weiterhin auf ihm. Die Linien aus Blut und Fleisch verflechteten sich und bildeten ein Muster aus einer antiken Zivilisation."
  },
  AvgDialog_47168_Content_148 = {
    Text = "Inzwischen erschienen diese Linien auf den meisten Gästen und Wachen. Schreie vermischten sich mit Blut, das in jeder Ecke des Saales spritzte."
  },
  AvgDialog_47168_Content_149 = {
    Text = "Der luxuriöse Saal verwandelte sich in eine Hölle aus Blut und Fleisch, gefüllt mit den Klagen der Familie Ornn."
  },
  AvgDialog_47168_Content_15 = {
    Text = "Das Bankett wird vorbereitet. Davor gibt es einige wichtige Angelegenheiten, die ich mit dir besprechen muss. Es geht um meine letzten Angelegenheiten."
  },
  AvgDialog_47168_Content_150 = {
    Text = "Talis' Gesicht begann sich zu verformen, Fischschuppen traten auf seiner Haut hervor. Seine einst durchdringenden Schreie wurden heiser und schwach, durchzogen vom Duft des Aequor."
  },
  AvgDialog_47168_Content_151 = {
    Text = "Dieses Land ist verwest... Ich werde ihnen ein perfektes Göttliches Reich zeigen."
  },
  AvgDialog_47168_Content_152 = {
    Text = "Was der König sagt, ist wahr. Das Reich der Götter naht... Ich weiß bereits, wo ich ihn finden kann. Warte ein wenig länger, und wir werden bald zusammen sein."
  },
  AvgDialog_47168_Content_153 = {
    Text = "Talis' qualvollen Schreie haben fast aufgehört. Unter dem starken Einfluss von Miryam ist seine Verwandlung in einen Lemuren noch vollständiger als die der alten Lemurier."
  },
  AvgDialog_47168_Content_154 = {
    Text = "Sie beugte sich hinunter und berührte Talis' deformiertes Gesicht und schuppige Arme. Mitten im Blut und den Schreien, die den Raum erfüllten, weinte sie und lächelte."
  },
  AvgDialog_47168_Content_155 = {
    Text = "Lange nicht gesehen, Vater."
  },
  AvgDialog_47168_Content_156 = {
    Text = "Sie überbrachte ihre herzlichsten Grüße an den writhenden Murloc."
  },
  AvgDialog_47168_Content_16 = {
    Text = "Vater! Bitte sag das nicht..."
  },
  AvgDialog_47168_Content_17 = {
    Text = "Der zweite Sohn trat zwei Schritte vor und stützte den Arm des Älteren. Der Ältere klopfte sanft auf die Rückseite seiner Hand."
  },
  AvgDialog_47168_Content_18 = {
    Text = "Lass mich fertig machen. Ich kenne meinen Gesundheitszustand gut. Einige Dinge müssen im Voraus arrangiert werden, damit die Familie Orne gedeihen kann."
  },
  AvgDialog_47168_Content_19 = {
    Text = "Nach dem Bankett heute Abend werde ich die Position des Oberhaupts der Familie Ornn an meinen zweiten Sohn übergeben. Ich plane, ein paar Jahre der Muße zu genießen."
  },
  AvgDialog_47168_Content_2 = {
    Text = "Grüße dich, Vater, der ewige Anführer der Ornn-Familie."
  },
  AvgDialog_47168_Content_20 = {
    Text = "Vater, aber... das ist so plötzlich. Ich bin noch nicht bereit..."
  },
  AvgDialog_47168_Content_21 = {
    Text = "Du bist der beste Erbe der Familie Orne, mit dem edelsten Stammbaum und der besten Erziehung. Das war mein Versprechen an deine Mutter, und ich werde es erfüllen."
  },
  AvgDialog_47168_Content_22 = {
    Text = "Sei unbesorgt, ich habe bereits unsere alten Familienfreunde informiert. Deine Brüder werden dir ebenfalls helfen."
  },
  AvgDialog_47168_Content_23 = {
    Text = "Er warf einen Blick auf seine anderen Söhne."
  },
  AvgDialog_47168_Content_24 = {
    Text = "Dein Territorium bleibt unverändert. Ich verstehe deine Bindung zum zweiten Ältesten. Der Titel des Häuptlings ist nur ein Name; wir sind alle eine Familie und müssen vereint bleiben."
  },
  AvgDialog_47168_Content_25 = {
    Text = "Was dich betrifft..."
  },
  AvgDialog_47168_Content_26 = {
    Text = "Er blickte nach oben und starrte auf Talis."
  },
  AvgDialog_47168_Content_27 = {
    Text = "Dein Territorium wird sich ebenfalls nicht verändern. Allerdings hast du dir in letzter Zeit zu viele Gedanken gemacht."
  },
  AvgDialog_47168_Content_28 = {
    Text = "Du wirst alt. Gib das Kommando über deine Armee an deinen Bruder ab. Ich denke, du solltest, wie ich, ein entspannteres Leben genießen."
  },
  AvgDialog_47168_Content_29 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47168_Content_3 = {
    Text = "Talis verneigte sich, und Miryam, die hinter ihm stand, nickte leicht dem alten Mann im Hauptsitz zu."
  },
  AvgDialog_47168_Content_30 = {
    Text = "Ist das ein unwiderstehlicher Befehl, richtig?"
  },
  AvgDialog_47168_Content_31 = {
    Text = "Der alte Mann schien diese Antwort bereits erwartet zu haben und lehnte sich in seinem Stuhl zurück."
  },
  AvgDialog_47168_Content_32 = {
    Text = "Vor drei Tagen schickte ich Truppen zu deiner Basis."
  },
  AvgDialog_47168_Content_33 = {
    Text = "Ich war mir immer deiner Ambitionen bewusst, aber du bist immer noch mein Sohn. Ich gebe dir die Chance zu wählen."
  },
  AvgDialog_47168_Content_34 = {
    Text = "Das ist eine Entscheidung, die ich für den langfristigen Nutzen der Ornn-Familie getroffen habe. Ich hoffe, du wirst mir nicht böse sein."
  },
  AvgDialog_47168_Content_35 = {
    Text = "...Wie könnte das sein, Vater? Ich muss dir danken."
  },
  AvgDialog_47168_Content_36 = {
    Text = "Talis ließ ein erleichtertes Lächeln aufblitzen."
  },
  AvgDialog_47168_Content_37 = {
    Text = "Auf meinem Weg hierher, allein beim Nachdenken über das, was ich tun muss, können Sie sich nicht vorstellen, wie gequält ich war..."
  },
  AvgDialog_47168_Content_38 = {
    Text = "Vielen Dank und danke an euch alle, meine Brüder. Jetzt bin ich frei von allen Lasten."
  },
  AvgDialog_47168_Content_39 = {
    Text = "Der alte Mann klopfte auf seinen Stuhl, und eine Truppe von Wachen stürmte hinter dem Vorhang hervor und umzingelte Thaïs und Miryam."
  },
  AvgDialog_47168_Content_4 = {
    Text = "Der alte Mann winkte ungeduldig."
  },
  AvgDialog_47168_Content_40 = {
    Text = "Next to him, the second son widened his eyes, his voice growing hoarse from tension."
  },
  AvgDialog_47168_Content_41 = {
    Text = "\"Vater? Was machst du...\""
  },
  AvgDialog_47168_Content_42 = {
    Text = "Du hast wirklich alles so gründlich vorbereitet, Vater. Die Wachen vor der Stadt zu stationieren und meine Waffen zu konfiszieren, hat mir keine einzige Chance gelassen."
  },
  AvgDialog_47168_Content_43 = {
    Text = "Ein Bastard, geboren von einer Magd, ungebildet, der den ganzen Tag mit deiner lächerlichen Alchemie und deinen absurden Ambitionen verbringt... Du hast keine Gefühle für deine Familie; alles, was du willst, ist Macht."
  },
  AvgDialog_47168_Content_44 = {
    Text = "Ich habe lange genug mit dir ausgehalten; ich habe meine Pflicht erfüllt."
  },
  AvgDialog_47168_Content_45 = {
    Text = "Die Soldaten ziehen ihre Schwerter und nähern sich. Talis winkt, und Miryam tritt vor. Hinter ihr sammelt sich schwarzer Nebel und windet sich empor."
  },
  AvgDialog_47168_Content_46 = {
    Text = "Diese Zofe? ..."
  },
  AvgDialog_47168_Content_47 = {
    Text = "Ich stimme zu, Vater. Du hast mich ertragen, vielleicht ein wenig zu viel."
  },
  AvgDialog_47168_Content_48 = {
    Text = "Sieh die absurden Ergebnisse meiner Alchemie, Vater!"
  },
  AvgDialog_47168_Content_49 = {
    Text = "Der Soldat spürte die Gefahr und stürmte auf die beiden los."
  },
  AvgDialog_47168_Content_5 = {
    Text = "\"Als älterer Bruder solltest du ein Vorbild für andere sein. Kannst du nicht einmal einem Diener angemessene Manieren beibringen?\""
  },
  AvgDialog_47168_Content_50 = {
    Text = "Schwisch—"
  },
  AvgDialog_47168_Content_51 = {
    Text = "Ein schlangenähnlicher Nebel fegte über sein Gesicht. Im nächsten Moment fiel ein kopfloser Körper zu Boden."
  },
  AvgDialog_47168_Content_52 = {
    Text = "D-Das ist..."
  },
  AvgDialog_47168_Content_53 = {
    Text = "Bevor die anderen Soldaten reagieren konnten, erschien serpentinartiger schwarzer Nebel neben jedem von ihnen."
  },
  AvgDialog_47168_Content_54 = {
    Text = "Der schwarze Nebel umwickelt ihre Körper, schnippt mit seiner Zunge und bewundert sie."
  },
  AvgDialog_47168_Content_55 = {
    Text = "Nein... nicht..."
  },
  AvgDialog_47168_Content_56 = {
    Text = "Einige Rauchschwaden verweilten in der Luft. Die schwarzen Schlangen bissen auf ihre Beute, und der Raum war erfüllt mit fortwährenden Schreien."
  },
  AvgDialog_47168_Content_57 = {
    Text = "Bald hörten die Schreie auf. Die Familie Orne sank zu Boden, umgeben von Körperteilen und Blut, ihre Kehlen konnten nur schwache Stöhnen ausstoßen."
  },
  AvgDialog_47168_Content_58 = {
    Text = "Öffne deine Augen weit und schau dir das Ergebnis meiner Alchemie an... meine „Tochter.“"
  },
  AvgDialog_47168_Content_59 = {
    Text = "In den letzten Monaten habe ich alle möglichen Mittel eingesetzt, um ihre Existenz zu verbergen, alles für diesen Tag."
  },
  AvgDialog_47168_Content_6 = {
    Text = "*Seufz*... Macht nichts, du würdest solche Dinge wahrscheinlich sowieso nicht verstehen."
  },
  AvgDialog_47168_Content_60 = {
    Text = "Hier ist ein großzügiges Geschenk, das ich für dich vorbereitet habe. Gefällt es dir, alter Mann?"
  },
  AvgDialog_47168_Content_61 = {
    Text = "Talis beobachtete den zitternden, sprachlosen alten Mann mit einem zufriedenen Lächeln."
  },
  AvgDialog_47168_Content_62 = {
    Text = "Du hast absolut recht; Nur mit vorheriger Planung kann die Familie Ornn gedeihen und florieren."
  },
  AvgDialog_47168_Content_63 = {
    Text = "Mach dir keine Sorgen, Vater. Ich habe die Familie Ornn und meine Lieben immer tief geliebt..."
  },
  AvgDialog_47168_Content_64 = {
    Text = "Überlasse die Familie Ornn mir, und ich werde sie zum Gedeihen bringen—"
  },
  AvgDialog_47168_Content_65 = {Text = "Zack—"},
  AvgDialog_47168_Content_66 = {
    Text = "Das scharfe Messer stach in die abgemagerte Brust des alten Mannes. Das Letzte, was er sah, war das triumphierende Lächeln des Bastards."
  },
  AvgDialog_47168_Content_67 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47168_Content_68 = {Text = "Alle."},
  AvgDialog_47168_Content_69 = {
    Text = "BANG! BANG BANG!"
  },
  AvgDialog_47168_Content_7 = {
    Text = "...Das hat mir Vater beigebracht."
  },
  AvgDialog_47168_Content_70 = {
    Text = "Ein silberner Löffel klirrt gegen einen kunstvoll geschnitzten Gobel und erzeugt einen klaren Klang."
  },
  AvgDialog_47168_Content_71 = {
    Text = "Der laute Festsaal verstummte. Alle wendeten ihren Blick zum Hauptplatz."
  },
  AvgDialog_47168_Content_72 = {
    Text = "Die Blutspuren auf dem Sitz sind noch nicht vollständig getrocknet. Talis, der den verbleibenden Geruch des Blutes genießt, schaute zufrieden auf die Blicke, die auf ihn gerichtet waren."
  },
  AvgDialog_47168_Content_73 = {
    Text = "Ich weiß, ich weiß, du solltest eigentlich an der Geburtstagsfeier meines Vaters teilnehmen. Aber ich bin dir wirklich dankbar für deine Anwesenheit."
  },
  AvgDialog_47168_Content_74 = {
    Text = "Eine große Vorstellung wäre ohne Publikum völlig langweilig."
  },
  AvgDialog_47168_Content_75 = {
    Text = "Danke euch allen fürs Kommen. Heute versammelt sich die Familie Ornn, um den wichtigsten Moment meines Lebens zu witnessen."
  },
  AvgDialog_47168_Content_76 = {
    Text = "Besonders meine nächsten Brüder..."
  },
  AvgDialog_47168_Content_77 = {
    Text = "Er stand auf, hob sein Glas und winkte es in die Ecke."
  },
  AvgDialog_47168_Content_78 = {
    Text = "Unter dem Blick einer Truppe voll bewaffneter Soldaten saßen Talis' jüngere Brüder am Tisch, ängstlich und schweigend."
  },
  AvgDialog_47168_Content_79 = {
    Text = "Mit ihrer Hilfe wirst du heute einen großartigen Moment erleben."
  },
  AvgDialog_47168_Content_8 = {
    Text = "Eine Reihe hastiger Schritte hallte draußen an der Tür wider. Ein junger Mann, der Talis ähnelte, erschien in der Halle."
  },
  AvgDialog_47168_Content_80 = {
    Text = "Die Geschichte der Familie Ornn wird heute komplett verändert."
  },
  AvgDialog_47168_Content_81 = {
    Text = "Er zog sein Schwert und stieß es in den Holztisch."
  },
  AvgDialog_47168_Content_82 = {
    Text = "Ich, Thalys, ein Bastard, ein uneheliches Kind. Ab heute bin ich der Diktator der Familie Orne!"
  },
  AvgDialog_47168_Content_83 = {
    Text = "Meine Damen und Herren, ihr werdet meine neuen Freunde in Talis. Wir werden eine mächtige Allianz schmieden, und alle Feinde werden durch sie zerschmettert!"
  },
  AvgDialog_47168_Content_84 = {
    Text = "Die Gäste mögen Freunde des ehemaligen Häuptlings gewesen sein, aber nicht mehr. Jetzt freundet man sich nur noch mit dem Sieger an."
  },
  AvgDialog_47168_Content_85 = {
    Text = "Während Talis' großzügiger Rede hoben die Gäste ihre Gläser."
  },
  AvgDialog_47168_Content_86 = {
    Text = "Heil Talis!"
  },
  AvgDialog_47168_Content_87 = {
    Text = "Hahaha... Auf dich, meine Freunde! Auf unsere große Allianz! Auf die strahlende Zukunft der Ornn-Familie!"
  },
  AvgDialog_47168_Content_88 = {Text = "Prost!"},
  AvgDialog_47168_Content_89 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47168_Content_9 = {
    Text = "Vater! Entschuldigung, ich war gestern krank und bin gerade erst aufgestanden..."
  },
  AvgDialog_47168_Content_90 = {
    Text = "Klingende Gläser, lebhaftes Geplänkel. Menschen, ob aufrichtig oder nur aus Gewohnheit, verschmelzen mit dem Festmahl, werden Teil davon."
  },
  AvgDialog_47168_Content_91 = {
    Text = "Miryam stand daneben, lächelnd, und beobachtete die Gäste und die Regeln dieser neuen Ära."
  },
  AvgDialog_47168_Content_92 = {
    Text = "Talis, berauscht vor Freude, ließ sich wieder im Hauptsitz nieder. Er hob sein Glas auf alle, trank herzhaft und genoss diesen Moment enormen Glücks in seinem Leben."
  },
  AvgDialog_47168_Content_93 = {
    Text = "Miryam, auch für dich... du bist mein Stolz!"
  },
  AvgDialog_47168_Content_94 = {
    Text = "Du hast keine Ahnung, wie viel ich getan habe, um dich zu finden, um dich zu Erwecken..."
  },
  AvgDialog_47168_Content_95 = {
    Text = "Diese \"silbernen Substanzen\", die du vorher erwähnt hast..."
  },
  AvgDialog_47168_Content_96 = {
    Text = "Ja, genau, diese silbernen Substanzen... Gold? Edelsteine? Hahaha, das alles ist Müll!"
  },
  AvgDialog_47168_Content_97 = {
    Text = "Was ist silberne Materie? Was ist Alchemie? Es ist Macht! Angesichts von Macht, was ist Reichtum? Es ist nur ein Nebenprodukt der Macht."
  },
  AvgDialog_47168_Content_98 = {
    Text = "Alchemie ist Macht... Miryam, du bist die Verkörperung der Macht! Prost!"
  },
  AvgDialog_47168_Content_99 = {
    Text = "Stimmt es, dass alles, was nötig ist, um jemanden wiederzubeleben, diese silberne Substanz ist?"
  },
  AvgDialog_47169_Content_1 = {
    Text = "Alter Freund"
  },
  AvgDialog_47169_Content_10 = {
    Text = "Talis holte mich ins Leben zurück; er muss etwas wissen. Ich werde einen Weg finden, dich durch ihn zurückzubringen!"
  },
  AvgDialog_47169_Content_100 = {
    Text = "Er wird den Preis für sein Zögern zahlen."
  },
  AvgDialog_47169_Content_101 = {
    Text = "Unser Essen und Wasser werden nur zwei oder drei Tage reichen..."
  },
  AvgDialog_47169_Content_102 = {
    Text = "Obwohl du klein bist, würde ich dich im Ernstfall nicht scheuen, dich zu essen."
  },
  AvgDialog_47169_Content_103 = {
    Text = "Mach dir keine Sorgen. Um dir für deine Loyalität zu danken, werde ich dir in deinen Träumen ein schnelles Ende gewähren."
  },
  AvgDialog_47169_Content_104 = {
    Text = "Lord Goliath, ich bin dein Anhänger. Bitte erschrecke mich nicht..."
  },
  AvgDialog_47169_Content_105 = {
    Text = "Aber mein Herr, seien wir nicht so pessimistisch. Wenn Glen uns geschickt hat, um die Hexe zu finden, die unsere Stammesangehörigen getötet hat, vielleicht können wir überleben, wenn wir sie finden!"
  },
  AvgDialog_47169_Content_106 = {
    Text = "Naives kleines Wesen, Glen ist nicht so. Es gibt keine Hexe – nur eine Lüge, um den Stamm zu täuschen."
  },
  AvgDialog_47169_Content_107 = {
    Text = "Aber jetzt, wo die Dinge so stehen, hoffe ich, dass diese Legende wahr ist..."
  },
  AvgDialog_47169_Content_108 = {
    Text = "Der Riese öffnete seine Augen und starrte auf das grenzenlose Meer."
  },
  AvgDialog_47169_Content_109 = {
    Text = "Wenn so eine Person existiert, kann ich vielleicht wirklich etwas erreichen."
  },
  AvgDialog_47169_Content_11 = {
    Text = "\"Wenn die Sterne sich ausrichten, wird Lemuria wieder in der Welt erscheinen.\""
  },
  AvgDialog_47169_Content_12 = {
    Text = "Ich werde dich zurückbringen, zurück nach Lemuria... Das hast du mir gesagt. Bitte sei versichert, ich werde meine Mission definitiv erfüllen!"
  },
  AvgDialog_47169_Content_13 = {
    Text = "Sie starrte gierig auf den Schatten."
  },
  AvgDialog_47169_Content_14 = {
    Text = "Der Schatten schwieg. Sein Gesicht war durch Licht und Tentakeln verdeckt, was seinen Ausdruck unleserlich machte. Er senkte den Kopf und ließ einen leisen Seufzer hören."
  },
  AvgDialog_47169_Content_15 = {
    Text = "Ein leiser Seufzer hallte wie Donner in der Illusion wider, als das Licht begann, sich zu zerstreuen und zu verblassen."
  },
  AvgDialog_47169_Content_16 = {
    Text = "Meister? Meister? ..."
  },
  AvgDialog_47169_Content_17 = {
    Text = "Mein Herr!!..."
  },
  AvgDialog_47169_Content_18 = {
    Text = "Das helle Licht ließ Miryams Augen stechen."
  },
  AvgDialog_47169_Content_19 = {
    Text = "Als die Sicht von Unschärfe zu Klarheit wechselte, wurde die Statue stetig auf die Fensterbank gestellt."
  },
  AvgDialog_47169_Content_2 = {
    Text = "Absolute Stille. Absolute Dunkelheit."
  },
  AvgDialog_47169_Content_20 = {
    Text = "Das dunkle Steinematerial ist kunstvoll geschnitzt. Der König, der sein Kinn in die Hand stützt, lehnt sich auf einen Thron, der mit Tentakeln verwoben ist, und betrachtet still Miryam."
  },
  AvgDialog_47169_Content_21 = {
    Text = "Die Sonne ging hinter ihm auf und warf einen verschwommenen Schatten."
  },
  AvgDialog_47169_Content_22 = {
    Text = "Miryam lächelte und verbeugte sich ehrfurchtsvoll vor der Statue."
  },
  AvgDialog_47169_Content_23 = {
    Text = "Bitte sei geduldig, mein Herr."
  },
  AvgDialog_47169_Content_24 = {
    Text = "Miryam, ich habe dich wieder im Schlaf reden hören... Geht es dir gut?"
  },
  AvgDialog_47169_Content_25 = {
    Text = "Hmm... Mir geht's gut, Deborah."
  },
  AvgDialog_47169_Content_26 = {
    Text = "Warum redest du im Schlaf? Ich habe es schon so oft gehört."
  },
  AvgDialog_47169_Content_27 = {
    Text = "Die Dienstmagd trat vor, berührte sanft ihre Stirn. Miryam starrte sie verwirrt an."
  },
  AvgDialog_47169_Content_28 = {
    Text = "Worauf schaust du mich an?"
  },
  AvgDialog_47169_Content_29 = {
    Text = "Ich dachte, der Name Deborah klingt wirklich schön."
  },
  AvgDialog_47169_Content_3 = {
    Text = "Sie war von Dunkelheit umgeben, egal in welche Richtung sie blickte, sah sie nur endlose Leere."
  },
  AvgDialog_47169_Content_30 = {
    Text = "Hehe, richtig? Ein Kind eines Sklaven sollte keinen Namen haben, aber die alte Herrin mochte mich und gab mir diesen. Ich liebe ihn!"
  },
  AvgDialog_47169_Content_31 = {
    Text = "Das Gesicht dieses Freundes in meiner Erinnerung überschneidet sich mit dem Gesicht der Dienerin."
  },
  AvgDialog_47169_Content_32 = {
    Text = "Priester Deborah half einst Miryam, Hohepriesterin zu werden, und vielleicht wird Maid Deborah Miryam auch helfen, das Reich Gottes willkommen zu heißen."
  },
  AvgDialog_47169_Content_33 = {
    Text = "Was für ein wunderbarer Zufall. Was für ein göttliches Schicksal. Miryam sah sie an und lächelte unbewusst."
  },
  AvgDialog_47169_Content_34 = {
    Text = "Dein Kopf fühlt sich nicht heiß an? Warum scheinst du ein wenig benommen"
  },
  AvgDialog_47169_Content_35 = {
    Text = "Wenn dir etwas zustößt, wird Lord Talis mir das niemals verzeihen."
  },
  AvgDialog_47169_Content_36 = {
    Text = "Obwohl wir alle als Dienstmädchen bezeichnet werden, sind Sie viel kostbarer als wir anderen!"
  },
  AvgDialog_47169_Content_37 = {
    Text = "Wir sind nicht anders. Jeder in dieser Welt ist lediglich ein Diener des großen Daseins."
  },
  AvgDialog_47169_Content_38 = {
    Text = "Seufz, du redest schon wieder wirres Zeug..."
  },
  AvgDialog_47169_Content_39 = {
    Text = "Deborah, du hast kürzlich mit mir über viele Dinge gesprochen. Dieser Ort ist mir fremd, und ich bin dankbar, jemanden zum Reden zu haben."
  },
  AvgDialog_47169_Content_4 = {
    Text = "Miryam fühlte sich wie ein Stern ohne Licht, ihre Energie sammelte sich irgendwo— ein Gefühl, sowohl vertraut als auch nostalgisch."
  },
  AvgDialog_47169_Content_40 = {
    Text = "Du bist mein bester Freund. Es war schon immer so."
  },
  AvgDialog_47169_Content_41 = {
    Text = "Sie lächelte und nahm die Hand der Dienstmagd."
  },
  AvgDialog_47169_Content_42 = {
    Text = "Lass uns gehen. Lord Talis sollte auf uns warten."
  },
  AvgDialog_47169_Content_43 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47169_Content_44 = {
    Text = "Ich werde dir etwas sagen, aber du darfst es niemandem erzählen!"
  },
  AvgDialog_47169_Content_45 = {
    Text = "Sei unbesorgt, ich werde kein Wort sagen."
  },
  AvgDialog_47169_Content_46 = {
    Text = "Du musst nicht jedes Geheimnis mit diesem Satz einleiten. Das ist das fünfte Mal, dass du es heute gesagt hast."
  },
  AvgDialog_47169_Content_47 = {
    Text = "Außerdem denke ich, es ist kein Geheimnis, dass du erwähnt hast, jemand zu mögen. Jeder im Herrenhaus weiß wahrscheinlich, wer es ist."
  },
  AvgDialog_47169_Content_48 = {
    Text = "Unmöglich! Ich habe es so gut versteckt... Du wirst mich niemals dazu bringen, es zu offenbaren!"
  },
  AvgDialog_47169_Content_49 = {
    Text = "Oh, naja, es ist auf jeden Fall ein großes Ding... Ich denke, Lord Talis plant etwas Ernstes."
  },
  AvgDialog_47169_Content_5 = {
    Text = "Sie sah in diese Richtung. Das Licht stieg auf und bildete dort eine verschwommene Silhouette."
  },
  AvgDialog_47169_Content_50 = {
    Text = "Dieser alte Mann ist sehr schlau. Sei vorsichtig!"
  },
  AvgDialog_47169_Content_51 = {
    Text = "Ist das so?"
  },
  AvgDialog_47169_Content_52 = {
    Text = "Miryam sagte das, aber ihr Lächeln blieb unverändert, ohne einen Hauch von Überraschung."
  },
  AvgDialog_47169_Content_53 = {
    Text = "Das stimmt! Schau ihn dir an, du hast in letzter Zeit ziemlich viele Menschen getötet. Diese Menschen waren Freunde der Familie Ornn und hatten eine enge Beziehung zu Lord Talis' Vater..."
  },
  AvgDialog_47169_Content_54 = {
    Text = "Jedes Mal scheint er sich gut mit diesen Menschen zu verstehen, als wären sie enge Freunde, aber dann dreht er sich um und lässt dich sie alle töten."
  },
  AvgDialog_47169_Content_55 = {
    Text = "Ich weiß, dass du dies definitiv nicht tun möchtest, aber es gibt kein Drumherum – du musst den Befehlen von Lord Talis folgen."
  },
  AvgDialog_47169_Content_56 = {
    Text = "In dieser Welt gibt es keine Naturkatastrophen, aber die Herzen der Menschen sind erschreckender als jede Plage."
  },
  AvgDialog_47169_Content_57 = {
    Text = "In einer so unvollkommenen Welt wird das Töten immer existieren. Es ist etwas, dem wir nicht entkommen können."
  },
  AvgDialog_47169_Content_58 = {
    Text = "Seufz, ich verstehe einfach nicht... Warum müssen die Königreiche und Familien ständig miteinander kämpfen? Es gibt immer noch so viele Menschen, die nicht einmal ordentlich leben können."
  },
  AvgDialog_47169_Content_59 = {
    Text = "Ich hoffe einfach, in Zukunft einen ruhigen kleinen Ort zu finden, ein Haus zu bauen und mit Nord zu sein..."
  },
  AvgDialog_47169_Content_6 = {
    Text = "Mein Herr... Bist das du?"
  },
  AvgDialog_47169_Content_60 = {Text = "Ups! ..."},
  AvgDialog_47169_Content_61 = {
    Text = "Als ihr klar wurde, dass sie es verraten hatte, errötete Deborahs Gesicht, und sie deckte hastig ihren Mund zu."
  },
  AvgDialog_47169_Content_62 = {
    Text = "Es ist in Ordnung. Jeder weiß, dass du Gefühle für diesen jungen Kutscher hast. Sogar Lord Tallis hat mir davon erzählt."
  },
  AvgDialog_47169_Content_63 = {
    Text = "Sie lächelte und tätschelte Debora's errötetes Gesicht."
  },
  AvgDialog_47169_Content_64 = {
    Text = "Sei unbesorgt, Deborah. In Zukunft wird es eine perfekte Welt geben."
  },
  AvgDialog_47169_Content_65 = {
    Text = "Wirklich? Wie hast du das herausgefunden?"
  },
  AvgDialog_47169_Content_66 = {
    Text = "Es ist wahr, Deborah. Es gibt einige Dinge, die ich dir langsam erzählen werde. Ich werde dich zum ersten Gläubigen dieses neuen Zeitalters und zum ersten Bürger des Göttlichen Reichs machen."
  },
  AvgDialog_47169_Content_67 = {
    Text = "Ich werde das Kommen des perfekten Reichs eines Gottes bringen... Das ist meine Mission."
  },
  AvgDialog_47169_Content_68 = {
    Text = "Lass mich hier. Du unterhältst dich unterwegs mit Miryam, glücklich, oder?"
  },
  AvgDialog_47169_Content_69 = {
    Text = "Talis' düstere Stimme unterbrach ihr Gespräch."
  },
  AvgDialog_47169_Content_7 = {
    Text = "Die Gestalt aus gesammelt Licht saß schief auf dem Thron, ruhte eine Hand auf ihrem Kinn und beobachtete still Miryam."
  },
  AvgDialog_47169_Content_70 = {
    Text = "Ist das die Art, wie du Ms. Miryam einlädst?"
  },
  AvgDialog_47169_Content_71 = {
    Text = "Ruf sie bei ihrem Namen und geh Seite an Seite... Soldat, zieh dieses unartige Ding heraus und kümmere dich darum."
  },
  AvgDialog_47169_Content_72 = {
    Text = "Lord Talis! Bitte verschone mich... ich... ich einfach..."
  },
  AvgDialog_47169_Content_73 = {
    Text = "Ich bin schuld, und es hat nichts mit Deborah zu tun. Bitte, \"Vater\", vergib ihr."
  },
  AvgDialog_47169_Content_74 = {
    Text = "Talis warf einen Blick auf Deborah und winkte ungeduldig."
  },
  AvgDialog_47169_Content_75 = {
    Text = "Da Miryam für dich gefleht hat, lasse ich es dieses Mal durchgehen. Das nächste Mal wird dir niemand helfen können. Verzieh dich."
  },
  AvgDialog_47169_Content_76 = {
    Text = "Meine Tochter, komm, komm hierher..."
  },
  AvgDialog_47169_Content_77 = {
    Text = "Deborah verneigte sich vor ihm, zwinkerte heimlich Miryam zu und ging verständig nach draußen, um die Tür zu schließen."
  },
  AvgDialog_47169_Content_78 = {
    Text = "Talis' Stimme erwärmte sich sofort, als sie anfingen, mit Miryam zu sprechen."
  },
  AvgDialog_47169_Content_79 = {
    Text = "Du hast in den letzten Monaten außergewöhnlich gut abgeschnitten, wirklich herausragend."
  },
  AvgDialog_47169_Content_8 = {
    Text = "Mein Herr... ich bin mit Zweifeln über dich gestorben. Das ist meine Sünde..."
  },
  AvgDialog_47169_Content_80 = {
    Text = "Ich studierte einmal Alchemie, und mein Vater sagte immer, ich verschwende meine Zeit. Aber als das Kind einer Dienerin würde er, egal was ich tue, niemals zustimmen... Dienerin, hm."
  },
  AvgDialog_47169_Content_81 = {
    Text = "Sein Griff am Griff zog sich an, Adern sprengten sich, und entspannte sich dann langsam."
  },
  AvgDialog_47169_Content_82 = {
    Text = "Es ist jetzt anders, Miryam. Mit dir habe ich eine Armee... Nein, etwas noch Stärkeres!"
  },
  AvgDialog_47169_Content_83 = {
    Text = "Wir können mehr Golems wie mich erschaffen. Das Ritual erfordert eine große Menge an Geistkraft; ich kann dir helfen."
  },
  AvgDialog_47169_Content_84 = {
    Text = "Ich habe auch darüber nachgedacht. Allerdings ist diese silberne Substanz nicht etwas, das man überall finden kann."
  },
  AvgDialog_47169_Content_85 = {
    Text = "\"Silbermaterie...\""
  },
  AvgDialog_47169_Content_86 = {
    Text = "Ich werde es dir später erklären, wenn ich Zeit habe. Es gibt keinen Grund, in dieser Angelegenheit jetzt zu hetzen. Mit dir hier, reicht es mir, das zu erreichen, was ich will."
  },
  AvgDialog_47169_Content_87 = {
    Text = "Er atmete tief ein, hielt sein Messer fest und schaute auf den Ozean hinter dem Fenster."
  },
  AvgDialog_47169_Content_88 = {
    Text = "Es wird nicht lange dauern, bis der 70. Geburtstag meines Vaters kommt. Ich werde Geschenke in die Hauptstadt des Ornn-Familiengebiets bringen, um seinen Geburtstag zu feiern."
  },
  AvgDialog_47169_Content_89 = {
    Text = "Unsere Vorbereitungen sind fast abgeschlossen. Wenn die Zeit kommt, werden wir ihm ein wertvolles Geschenk überreichen. Stimmt's, Miryam?"
  },
  AvgDialog_47169_Content_9 = {
    Text = "Ich suche nicht deine Vergebung ... ich werde meine Sünden tragen! Bis dahin werde ich tun, was ich muss!"
  },
  AvgDialog_47169_Content_90 = {
    Text = "Klar, „Vater.“ Das wird ein unschätzbares Geschenk für die gesamte Ornn-Familie sein."
  },
  AvgDialog_47169_Content_91 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47169_Content_92 = {
    Text = "Einige Tage später."
  },
  AvgDialog_47169_Content_93 = {
    Text = "Auf dem Meer treibt ein Holzschiff allein."
  },
  AvgDialog_47169_Content_94 = {
    Text = "Lord Goliath, die Schiffe der Stammesangehörigen sind nicht mehr zu sehen."
  },
  AvgDialog_47169_Content_95 = {
    Text = "Eine gute Sache."
  },
  AvgDialog_47169_Content_96 = {
    Text = "Der Riese ließ sein Messer fallen, lehnte sich gegen den Mast und schloss die Augen, um sich auszuruhen."
  },
  AvgDialog_47169_Content_97 = {
    Text = "Verletzungen, die im Kampf erlitten wurden, Verrat und Intrigen meiner Verwandten nach meiner Verwundung... Es war meine eigene Nachlässigkeit. Ich kann anderen keinen Vorwurf machen."
  },
  AvgDialog_47169_Content_98 = {
    Text = "Aber selbst er fühlte sich ein wenig müde."
  },
  AvgDialog_47169_Content_99 = {
    Text = "Hehe, Glen der Feige. Er will mich töten, hat aber Angst, seinen Ruf zu beschmutzen. Er verbannt mich unter dem Vorwand, Hexen zu jagen – was für eine lästige Taktik."
  },
  AvgDialog_47170_Content_1 = {
    Text = "Dunkle Statue"
  },
  AvgDialog_47170_Content_10 = {
    Text = "\"Wach auf, kehre in die Umarmung deiner Familie zurück...\""
  },
  AvgDialog_47170_Content_100 = {
    Text = "Bald konnte drinnen niemand mehr die Stimmen der Perishiten hören."
  },
  AvgDialog_47170_Content_101 = {
    Text = "Miryam schien alles um sich herum zu ignorieren. Sie ging zu den Überresten weiter und hob die dunkle Statue ehrfurchtsvoll für eine genauere Inspektion auf."
  },
  AvgDialog_47170_Content_102 = {
    Text = "„Es ist eine Lemuria-Statue... Ja, es ist eine Lemuria-Statue...“"
  },
  AvgDialog_47170_Content_103 = {
    Text = "\"Das ist ein Golem... Das ist die Kraft eines Golems!!\""
  },
  AvgDialog_47170_Content_104 = {Text = "@2@3..."},
  AvgDialog_47170_Content_105 = {
    Text = "Talis stand auf, sein Gesicht war vor Aufregung rot. Er beschwor einen Zauber und winkte mit der Hand."
  },
  AvgDialog_47170_Content_106 = {
    Text = "Miryam spürte eine starke Kraft vom anderen Ende der Verknüpfung, doch sie verschwand, bevor sie echten Schaden anrichten konnte."
  },
  AvgDialog_47170_Content_107 = {
    Text = "\"Golem, ich bin deine Verknüpfung, ich gab dir Leben. Von nun an bin ich dein Vater.\""
  },
  AvgDialog_47170_Content_108 = {
    Text = "\"Deine Fähigkeiten sind formidable, aber wenn ich es so will, kann ich dich immer wieder auf einen bloßen Leichnam reduzieren.\""
  },
  AvgDialog_47170_Content_109 = {
    Text = "\"Dein Schicksal ist mit meinem verbunden. Wenn ich sterbe, wirst du auch nicht überleben können.\""
  },
  AvgDialog_47170_Content_11 = {
    Text = "„Vater!...“"
  },
  AvgDialog_47170_Content_110 = {
    Text = "\"Also, unterhalte dich nicht mit unangemessenen Gedanken. Widme dich mir und werde der Anführer der Ornn-Familie.\""
  },
  AvgDialog_47170_Content_111 = {
    Text = "\"Vater\"? \"Vater\"... Der König hatte Recht; ich bin derjenige, der das Schicksal tragen muss! Ich weiß jetzt, was zu tun ist. Ich kann so viele Dinge erreichen...\""
  },
  AvgDialog_47170_Content_112 = {
    Text = "\"Sei unbesorgt, Vater. Miryam wird dich bestimmt ins Göttliche Reich zurückbringen!\""
  },
  AvgDialog_47170_Content_113 = {
    Text = "Miryam sah Talis mit einem begierigen und seltsamen Blick an. Es war, als würden ihre Augen durch ihn hindurchdringen und sich auf etwas konzentrieren, das weit über sein Verständnis hinausgeht."
  },
  AvgDialog_47170_Content_114 = {
    Text = "Es ist so brennend wie die Sonne, aber so dunkel und kalt wie das Aequor."
  },
  AvgDialog_47170_Content_115 = {
    Text = "\"Welches Götterreich? Sprichst du vom Land der Familie Orne? Eigenartiger Brauch. Aber es ist nicht wichtig; tu, wie du willst.\""
  },
  AvgDialog_47170_Content_116 = {
    Text = "\"Diese Perishiten genießen immer noch mein Schloss und Anwesen. Miryam, töte sie. Zeig mir, was du tun kannst.\""
  },
  AvgDialog_47170_Content_117 = {
    Text = "\"As you wish, 'Father.'\"  -> \"Wie du wünscht, 'Vater.'\""
  },
  AvgDialog_47170_Content_118 = {
    Text = "Miryam verneigte sich vor Talis und ging hinaus."
  },
  AvgDialog_47170_Content_119 = {
    Text = "Blut tropft von der dunklen Statue. Hinter Miryam breitet sich eine schwarze Schlange wie Flügel aus und zeigt scharfe Reißzähne."
  },
  AvgDialog_47170_Content_12 = {
    Text = "Sie öffnete plötzlich ihre Augen und sprang aus dem Meer."
  },
  AvgDialog_47170_Content_13 = {
    Text = "\"Sie ist wach! Meister Talis, sie ist wach!\""
  },
  AvgDialog_47170_Content_14 = {
    Text = "„Wo ist das hier?...“"
  },
  AvgDialog_47170_Content_15 = {
    Text = "Miryam findet sich in einem geräumigen und luxuriösen Saal wieder, kniet im Zentrum eines rituellen magischen Kreises."
  },
  AvgDialog_47170_Content_16 = {
    Text = "Die Menschen um sie herum hatten Gesichter, die sie noch nie zuvor gesehen hatte, gekleidet in ihr unbekannte Kleidung, und riefen aufgeregt."
  },
  AvgDialog_47170_Content_17 = {
    Text = "Ein mittelalter Mann steht außerhalb des magischen Kreises und sieht sie mit Erschöpfung und Aufregung an"
  },
  AvgDialog_47170_Content_18 = {
    Text = "\"Es hat funktioniert... Ich habe den Golem beschworen! Ich habe mein ganzes Leben mit Forschung verbracht... und endlich Erfolg gehabt!!\""
  },
  AvgDialog_47170_Content_19 = {
    Text = "\"Wo... wo ist der König hingegangen? Ist das nicht Lemuria?\""
  },
  AvgDialog_47170_Content_2 = {
    Text = "\"Im Namen von @3 rufe ich dich, mein Kind...\""
  },
  AvgDialog_47170_Content_20 = {
    Text = "Die Dienstmagd, die etwas vertraut aussah, starrte sie verwirrt an."
  },
  AvgDialog_47170_Content_21 = {
    Text = "\"Lemuria? Was ist das?\""
  },
  AvgDialog_47170_Content_22 = {
    Text = "\"Wahrscheinlich eine Art alte Zivilisation... Wer weiß?\""
  },
  AvgDialog_47170_Content_23 = {
    Text = "\"An ihrer Kleidung zu urteilen, muss sie jemand Wichtiges sein... Meine Bemühungen waren nicht umsonst!\""
  },
  AvgDialog_47170_Content_24 = {
    Text = "Sein Blick auf Miryam wurde zunehmend intensiver. Er näherte sich ihr und streckte die Hand aus, um seine Hand auf ihre Stirn zu legen."
  },
  AvgDialog_47170_Content_25 = {
    Text = "\"Ich bin deine Verknüpfung... Jetzt, öffne deine Augen und sieh alles...\""
  },
  AvgDialog_47170_Content_26 = {
    Text = "Die Realität verschwand kurzzeitig. Unzählige Informationsstücke strömten in Miryams Geist, ertränkten sie wie ein Ozean."
  },
  AvgDialog_47170_Content_27 = {
    Text = "Sie sah ihr Heimatland versinken, beobachtete, wie sich das Meer wandelte, und sah die Insel mit dem Festland verbinden."
  },
  AvgDialog_47170_Content_28 = {
    Text = "Sie sah neue Zivilisationen geboren, neue Nationen gegründet, neue Gläubige, die neue Gebete sangen, und neue Könige, die neue Throne bestiegen."
  },
  AvgDialog_47170_Content_29 = {
    Text = "Sie sah zu, wie die langen Jahre mit unzähligen Tagen und Nächten schnell vergingen, und Lemuria aus dem Gedächtnis der Welt verschwand, ohne eine Spur zu hinterlassen."
  },
  AvgDialog_47170_Content_3 = {
    Text = "\"Lass die Umarmung der Familie deinen müden Körper beruhigen, und der Duft von Zuhause deine wandernde Seele heilen.\""
  },
  AvgDialog_47170_Content_30 = {
    Text = "\"Ich habe geschlafen... für zehntausend Jahre?\""
  },
  AvgDialog_47170_Content_31 = {
    Text = "\"Schlaf? Hahaha... Nein, nein. Du bist einmal gestorben.\""
  },
  AvgDialog_47170_Content_32 = {
    Text = "\"Ich war es! Ich habe dich erweckt und dir erneut Leben geschenk!\""
  },
  AvgDialog_47170_Content_33 = {
    Text = "\"Schnell, sag mir, welche Fähigkeiten du hast und wie du mir helfen kannst.\""
  },
  AvgDialog_47170_Content_34 = {
    Text = "\"Lemuria... verschwand, ohne eine Spur zu hinterlassen...\""
  },
  AvgDialog_47170_Content_35 = {
    Text = "Ignoriere Talis' dringende Fragen, Miryam blieb in ihren Gedanken verloren."
  },
  AvgDialog_47170_Content_36 = {
    Text = "Die Veränderungen in der Welt, das Verschwinden ihrer Heimat und der Verlauf von zehntausend Jahren – all dies ließ ihren neu erwachten Geist unfähig, Gedanken zu verarbeiten."
  },
  AvgDialog_47170_Content_37 = {
    Text = "Die Dienstmagd streichelte sich die Stirn und seufzte."
  },
  AvgDialog_47170_Content_38 = {
    Text = "\"Oh nein, Lord Talis... sie scheint nicht sehr klug zu sein, oder?\""
  },
  AvgDialog_47170_Content_39 = {
    Text = "\"Aber es ist in Ordnung. Nachdem ich mich eine Weile gut um sie gekümmert habe, könnte sie...\""
  },
  AvgDialog_47170_Content_4 = {
    Text = "„Vater?...“"
  },
  AvgDialog_47170_Content_40 = {Text = "\"Ah!—\""},
  AvgDialog_47170_Content_41 = {
    Text = "Das Geräusch kommt von weit draußen aus dem Haus."
  },
  AvgDialog_47170_Content_42 = {
    Text = "\"Welches Geräusch?\""
  },
  AvgDialog_47170_Content_43 = {
    Text = "\"Perishiten... Perishiten-Invasion! Soldaten bewachen das Erwachen-Zeremoniell; die Küstenverteidigungslinie wurde durchbrochen!\""
  },
  AvgDialog_47170_Content_44 = {
    Text = "\"\"Warnung! Perishite... Ah!...\""
  },
  AvgDialog_47170_Content_45 = {
    Text = "Ein Wächter rannte und rief. Bevor er den Satz beenden konnte, flog ein riesiger Harpunenwurf aus der Ferne und durchbohrte sein Herz."
  },
  AvgDialog_47170_Content_46 = {
    Text = "Eine Gruppe von dunkelhäutigen, ungerüsteten ausländischen Kriegern, die seltsame Schlachtrufe ausstießen, umzingelte uns von allen Seiten."
  },
  AvgDialog_47170_Content_47 = {
    Text = "\"Schnell... Golem! Töte sie für mich!\""
  },
  AvgDialog_47170_Content_48 = {Text = "„...\""},
  AvgDialog_47170_Content_49 = {
    Text = "Miryam fiel auf den Boden, senkte benommen den Kopf und reagierte nicht."
  },
  AvgDialog_47170_Content_5 = {
    Text = "Das Bewusstsein kehrte allmählich zu Miryam zurück. Halbschlafend fühlte sie sich, als würde sie in warmem Meerwasser gewickelt."
  },
  AvgDialog_47170_Content_50 = {
    Text = "\"@2! Kann nicht glauben, dass wir eine nutzlose Person erweckt haben...\""
  },
  AvgDialog_47170_Content_51 = {
    Text = "\"Das Innere des Schlosses der Familie Ornn sieht so aus. Wirklich luxuriös.\""
  },
  AvgDialog_47170_Content_52 = {
    Text = "\"Ihr Wilden! Das ist das Gebiet der Familie Oren. Wenn ihr nicht von der Armee der Familie Oren massakriert werden wollt, entfernt euch von hier!\""
  },
  AvgDialog_47170_Content_53 = {Text = "Zisch—"},
  AvgDialog_47170_Content_54 = {Text = "\"Ah!!\""},
  AvgDialog_47170_Content_55 = {
    Text = "Der Harpunen traf seine Schulter, und er ließ einen Schrei los, während er sich schmerzhaft die Wunde hielt."
  },
  AvgDialog_47170_Content_56 = {
    Text = "\"Wenn du wieder bellst, wird es beim nächsten Mal dein Auge durchbohren, dann deinen Hals.\""
  },
  AvgDialog_47170_Content_57 = {
    Text = "Jeder im Raum war kontrolliert, während die Wachen draußen von Harpunen getötet wurden. Der Perishit lief gelangweilt umher und beobachtete gierig alles."
  },
  AvgDialog_47170_Content_58 = {
    Text = "\"Goliath sagte oft, man solle niemals seine Augen auf das Schloss der Familie Ornn richten; es ist eine extrem gefährliche Sache. Aber jetzt? Wir stehen direkt im Schloss der Familie Ornn.\""
  },
  AvgDialog_47170_Content_59 = {
    Text = "\"Alles hier wird bald unser sein!\""
  },
  AvgDialog_47170_Content_6 = {
    Text = "Der Klang schallt schwach, und die Kontur der Sonne durchdringt das Wasser, erscheint vage darüber."
  },
  AvgDialog_47170_Content_60 = {
    Text = "Next to him, another Philisterkrieger eagerly raised his trident."
  },
  AvgDialog_47170_Content_61 = {
    Text = "\"Das stimmt, Goliath ist ein Feigling! Wir hätten auf Eglon hören sollen. Er sollte Goliath als unseren Anführer ersetzen!\""
  },
  AvgDialog_47170_Content_62 = {
    Text = "\"Boss, sobald du Ornes Schloss eroberst, wird Eglon dich bei unserer Rückkehr bestimmt schätzen!\""
  },
  AvgDialog_47170_Content_63 = {
    Text = "\"Wäre ich nicht mitten in der Erweckungszeremonie gewesen, hätte dein Hinterhalt nicht Erfolg gehabt... Ihr abscheulichen Wilden!\""
  },
  AvgDialog_47170_Content_64 = {
    Text = "\"Golem! Ich habe dich gerettet! Wenn ich sterbe, wirst du es auch nicht schaffen! Beeil dich... komm wieder zu dir, hilf mir!...\""
  },
  AvgDialog_47170_Content_65 = {
    Text = "„Sie? Du setzt deine Hoffnungen auf eine Frau? Hahaha...“"
  },
  AvgDialog_47170_Content_66 = {
    Text = "Der Spott der Phillistine hallt durch den Raum. Der Phillistine-Hauptmann schüttelt den Kopf, packt Talis an den Haaren und zieht einen Dolch hervor."
  },
  AvgDialog_47170_Content_67 = {
    Text = "Er wendet sich Miryam zu. Eine Statuette baumelt an seiner Hüfte. Sie reißt plötzlich die Augen auf."
  },
  AvgDialog_47170_Content_68 = {
    Text = "„Woher habt ihr diese Statuette?\""
  },
  AvgDialog_47170_Content_69 = {
    Text = "„Oh... Du kannst also reden, hm? Ich dachte, du wärst eine Schwachsinnige.\""
  },
  AvgDialog_47170_Content_7 = {
    Text = "Das ist ein traumloser Schlaf. Miryam weiß nicht, wie lange sie geschlafen hat—vielleicht einen Tag? Oder eine Woche?"
  },
  AvgDialog_47170_Content_70 = {
    Text = "„Statuette, woher stammt sie?\""
  },
  AvgDialog_47170_Content_71 = {
    Text = "Der Hauptmann legt sein Messer ab und blickt auf die Statuette an seinem Gürtel hinunter."
  },
  AvgDialog_47170_Content_72 = {
    Text = "Die Statue besteht aus einem alten, stumpfen Steinmaterial, das eine Gestalt auf einem Thron darstellt. Seltsame Tentakel strecken sich chaotisch aus und verdecken sein Gesicht."
  },
  AvgDialog_47170_Content_73 = {
    Text = "\"Heh... Das hier? Goliath hat es gefunden und mich für meinen Mut belohnt.\""
  },
  AvgDialog_47170_Content_74 = {
    Text = "„Ich habe mein Leben für ihn riskiert, und das ist die Belohnung, die er mir gab. Irgendein nutzloser Plunder, den irgendeine dumme Zivilisation hinterlassen hat.\""
  },
  AvgDialog_47170_Content_75 = {Text = "\"...Oh?\""},
  AvgDialog_47170_Content_76 = {
    Text = "Der philistäische Hauptmann sprach immer noch, als er plötzlich bemerkte, dass die Frau vor ihm aufstand."
  },
  AvgDialog_47170_Content_77 = {
    Text = "Er untersuchte neugierig ihre seltsame Bekleidung und die bizarren, aber teuren Accessoires."
  },
  AvgDialog_47170_Content_78 = {
    Text = "\"Was hast du gesagt, dass diese Statue war?\""
  },
  AvgDialog_47170_Content_79 = {
    Text = "\"Ich sage, du bist so nutzlos wie Müll. Was ist los? Sind deine Ohren so schlecht wie dein Mund?\""
  },
  AvgDialog_47170_Content_8 = {
    Text = "Allmählich wurde ihr Bewusstsein klarer und verband sich mit ihrem Körper. Vage sah sie eine Gruppe von Menschen, die ihr vom Meer aus entgegenstreckten."
  },
  AvgDialog_47170_Content_80 = {
    Text = "\"Kapitän, verschwende keine Zeit mit ihr. Nur ein Schnitt... Ah!!!!...\""
  },
  AvgDialog_47170_Content_81 = {
    Text = "Der schwarze Nebel erschien fast im Handumdrehen."
  },
  AvgDialog_47170_Content_82 = {
    Text = "Der schwarze Nebel kondensiert zu mehreren riesigen Schlangen, die hungrig auf den Philisterkrieger losstürzen."
  },
  AvgDialog_47170_Content_83 = {
    Text = "Sein Messer zog sich von Miryams Hals zurück. Die Hand, die das Messer hielt, wurde von einer schwarzen Schlange abgebissen, Blut spritzte und durchnässte Miryams Kleidung."
  },
  AvgDialog_47170_Content_84 = {
    Text = "Schwarze Schlangen wurden auf den Perishiten geworfen, verschlangen ihn, bevor er mehr Schreie ausstoßen konnte."
  },
  AvgDialog_47170_Content_85 = {
    Text = "Nur wenige Überreste und ein Blutfleck liegen noch auf dem Boden."
  },
  AvgDialog_47170_Content_86 = {
    Text = "„Das... das ist...“"
  },
  AvgDialog_47170_Content_87 = {
    Text = "Jeder im Raum war von der plötzlichen Szene verblüfft und begann, an seiner eigenen Sicht zu zweifeln."
  },
  AvgDialog_47170_Content_88 = {
    Text = "Miryam sah auf ihre Hände hinab. Ein allmählich strahlendes Lächeln erschien auf ihrem Gesicht."
  },
  AvgDialog_47170_Content_89 = {
    Text = "Sie sah in Richtung des philistinischen Kapitäns, nicht ihn, sondern die Statue an seinem Gürtel.\nTränen füllten ihre Augen"
  },
  AvgDialog_47170_Content_9 = {
    Text = "Vater, Mutter, Schwester, Ältester Priester, König, Deborah... Sie alle streckten ihre Hände aus und luden sie ein."
  },
  AvgDialog_47170_Content_90 = {
    Text = "\"Eure Majestät, ich sehe Sie wieder... Es stellt sich heraus, dass alles, was Sie gesagt haben, wahr ist...\""
  },
  AvgDialog_47170_Content_91 = {
    Text = "\"Ich bin wirklich wiedergeboren worden! Ich habe jetzt mehr Macht als je zuvor!\""
  },
  AvgDialog_47170_Content_92 = {
    Text = "\"<Mein Herr>... Ich entschuldige mich für meine Zweifel... Du hast mich wirklich nicht getäuscht...\""
  },
  AvgDialog_47170_Content_93 = {Text = "\"Ah!!!\""},
  AvgDialog_47170_Content_94 = {
    Text = "Die furchtbare Hexe war in komplexe Emotionen vertieft. Nachdem sie seit ihrer Jugend Brandstiftung und Plünderung erlebt hatte, hatte der Perishit ein instinktives Gespür für Gefahr. Er wusste, dass dies seine einzige Chance war."
  },
  AvgDialog_47170_Content_95 = {
    Text = "Er brüllte, hielt ein Messer und stürmte mit voller Geschwindigkeit auf Miryam zu."
  },
  AvgDialog_47170_Content_96 = {Text = "Zisch—"},
  AvgDialog_47170_Content_97 = {
    Text = "Die schwarze Schlange erschien aus dem Nichts in einer Form, die er nicht begreifen konnte, und durchbohrte seinen Körper"
  },
  AvgDialog_47170_Content_98 = {
    Text = "Innerhalb und außerhalb stürmten einige Perishiten mit Waffen vor, einige flohen in alle Richtungen, und einige knieten nieder und baten um Gnade."
  },
  AvgDialog_47170_Content_99 = {
    Text = "Miryam war es egal, welche mutigen oder abscheulichen Entscheidungen sie getroffen hatten. Die schwarze Schlange erschien und verschwand, spielte mit, biss und jagte diese niederträchtigen Leben."
  },
  AvgDialog_47171_Content_1 = {
    Text = "Die Tugend der Lügen"
  },
  AvgDialog_47171_Content_10 = {
    Text = "Als du Deborahs Ausdruck gesehen hast, nickten die Anhänger verständnisvoll."
  },
  AvgDialog_47171_Content_100 = {
    Text = "Was der Lehrer sagte... das waren alles Lügen, oder?"
  },
  AvgDialog_47171_Content_101 = {
    Text = "Seit Jahren sind alle Katastrophen verschwunden, und Lemuria rückt immer näher an das Reich der Götter... Nur einen Schritt entfernt, wir sind nur einen Schritt entfernt..."
  },
  AvgDialog_47171_Content_102 = {
    Text = "Du wirst sicherlich das Göttliche Reich hervorbringen, mein Herr! Ich bin dein treuer Diener, für immer..."
  },
  AvgDialog_47171_Content_103 = {
    Text = "Ich habe so lange gesucht... Die Gestalt Gottes erscheint nicht mehr in meinen Träumen."
  },
  AvgDialog_47171_Content_104 = {
    Text = "Tulu wandte seinen Blick von Miryams Gesicht ab."
  },
  AvgDialog_47171_Content_105 = {
    Text = "Unsere Zivilisation wird unweigerlich sterben... Dies war Seine letzte Botschaft an mich."
  },
  AvgDialog_47171_Content_106 = {
    Text = "Günstiges Wetter und Frieden über die Meere, dies ist die letzte Dämmerung von Lemuria."
  },
  AvgDialog_47171_Content_107 = {
    Text = "Diese Katastrophe ist die Strafe, die der König und der Hohe Priester tragen müssen."
  },
  AvgDialog_47171_Content_108 = {
    Text = "Also... was du sagst, ist... die Lemurier, all ihre Gebete und Erwartungen waren eine Täuschung..."
  },
  AvgDialog_47171_Content_109 = {
    Text = "Jeder, von der Geburt bis zum Tod, lebt in einer Täuschung, nicht wahr, mein Lord?"
  },
  AvgDialog_47171_Content_11 = {
    Text = "Sie hielten den Mund geschlossen und knieten vor Miryam. Mit ehrfurchtsvollen und erwartungsvollen Augen starrten sie sie an, ohne sich zu bewegen."
  },
  AvgDialog_47171_Content_110 = {
    Text = "Dein Lehrer hat dich bereits informiert."
  },
  AvgDialog_47171_Content_111 = {
    Text = "Ich möchte hören, dass du es selbst sagst, mein Lord..."
  },
  AvgDialog_47171_Content_112 = {
    Text = "Bitte sagen Sie mir persönlich, dass unsere Gebete bedeutungslos sind. Diese Pioniere haben alles geopfert – Intelligenz, Emotionen, Würde – und wurden in diesen Pool gepfercht, wartend auf eine ferne Lüge..."
  },
  AvgDialog_47171_Content_113 = {
    Text = "Sag mir, das göttliche Reich... wird niemals ankommen..."
  },
  AvgDialog_47171_Content_114 = {
    Text = "Es ist ein stiller Zusammenbruch. Miryam weint nicht und fällt nicht in den Wahnsinn. Sie sieht zu Tulu und fragt in ihrer Schwäche alles."
  },
  AvgDialog_47171_Content_115 = {
    Text = "Ihre Augen waren unblinkend, genau wie die Murlocs um sie herum – keine Gedanken, keine Emotionen, einfach Tulu aufmerksam und still beobachtend."
  },
  AvgDialog_47171_Content_116 = {
    Text = "Wie Feuerwerke, die kurz davor sind zu verblassen, sehnen sich nach der fernen Dämmerung."
  },
  AvgDialog_47171_Content_117 = {
    Text = "Tulu schloss die Augen und holte tief Luft. In diesem Moment erinnerten ihn diese Blicke an viele Dinge."
  },
  AvgDialog_47171_Content_118 = {
    Text = "Vielleicht erinnerte er sich an diejenigen, die seit Generationen in Lügen lebten."
  },
  AvgDialog_47171_Content_119 = {
    Text = "Vielleicht dachte er an die Gläubigen, die ihren Verstand, ihre Gefühle und ihre Würde opferten, sowie an jene, deren Seelen verzerrt waren."
  },
  AvgDialog_47171_Content_12 = {
    Text = "Mein loyaler Anhänger meines Herrn, mein Herr wird dich immer segnen."
  },
  AvgDialog_47171_Content_120 = {
    Text = "Vielleicht hat er sich nur erinnert, dass er vor dieser Täuschung des Schlafes, wie die Menschen von Lemuria, einmal glaubte, er könne einen neuen Morgen für dieses Land bringen."
  },
  AvgDialog_47171_Content_121 = {
    Text = "Den Menschen Hoffnung zu geben, ist die Pflicht eines Königs, der alleinige Sinn dieser Farce. In diesem Fall, lasst uns die Farce fortsetzen."
  },
  AvgDialog_47171_Content_122 = {
    Text = "Tulu öffnete seine Augen und stand vor Miryam."
  },
  AvgDialog_47171_Content_123 = {
    Text = "Ich habe die Götter schon lange nicht mehr gesehen... aber ich weiß, dass sie noch da sind, tief in den Träumen."
  },
  AvgDialog_47171_Content_124 = {
    Text = "Das Reich der Götter existiert noch."
  },
  AvgDialog_47171_Content_125 = {
    Text = "Miryam hob plötzlich ihren Kopf."
  },
  AvgDialog_47171_Content_126 = {
    Text = "Aber... aber der Lehrer sagte..."
  },
  AvgDialog_47171_Content_127 = {
    Text = "Das Reich Gottes wird nicht ankommen, bis der Untergang von Lemuria erfolgt. Alle werden in dieser Katastrophe sterben."
  },
  AvgDialog_47171_Content_128 = {
    Text = "Mein Herr, meinst du"
  },
  AvgDialog_47171_Content_129 = {
    Text = "... Aber die Sterne haben mir einst prophezeit, dass Lemuria wiedergeboren werden würde."
  },
  AvgDialog_47171_Content_13 = {
    Text = "Eine schwarze Schlange tanzt hinter Miryam. Ihre Hand berührt sanft die Stirn jedes Gläubigen."
  },
  AvgDialog_47171_Content_130 = {
    Text = "Er sah Miryam nicht an, drehte sich um und ging auf den Thron zu."
  },
  AvgDialog_47171_Content_131 = {
    Text = "Zur Zeit des Ausrichtens wird Lemuria wieder erscheinen."
  },
  AvgDialog_47171_Content_132 = {
    Text = "Derjenige, der Lemuria rettet, bin nicht ich. Derjenige, der Lemuria rettet, bist du."
  },
  AvgDialog_47171_Content_133 = {Text = "?!!"},
  AvgDialog_47171_Content_134 = {
    Text = "Miryam, Hohepriesterin von Lemuria. Du wirst wiedergeboren. Du wirst die Überbleibsel zurückbringen und Lemuria wiederherstellen."
  },
  AvgDialog_47171_Content_135 = {
    Text = "Dann werde ich sicherstellen, dass das Reich Gottes für immer in Lemuria besteht."
  },
  AvgDialog_47171_Content_136 = {
    Text = "Tulu saß auf dem Thron. Er stützte sein Kinn und lehnte sich müde zurück"
  },
  AvgDialog_47171_Content_137 = {
    Text = "Er beachtete den schockierten und kämpfenden Ausdruck auf Miryams Gesicht überhaupt nicht. Er wusste, dass Miryam das nicht ganz glaubte. Niemand konnte es wirklich glauben."
  },
  AvgDialog_47171_Content_138 = {
    Text = "Was ist grausamer, Lügen oder Wahrheit? Er dachte lange nach, konnte aber trotzdem keine Antwort finden."
  },
  AvgDialog_47171_Content_139 = {
    Text = "Wenn meine Wahl falsch ist, dann lass es mit diesem Fehler enden."
  },
  AvgDialog_47171_Content_14 = {
    Text = "Lobe unseren Herrn... Lobe den Hohen Priester!"
  },
  AvgDialog_47171_Content_140 = {
    Text = "Aber... mein Herr, was... was soll ich tun?"
  },
  AvgDialog_47171_Content_141 = {
    Text = "Warte. Bis dahin, geh in Richtung Ende mit Lemuria."
  },
  AvgDialog_47171_Content_142 = {
    Text = "Lemuria, und..."
  },
  AvgDialog_47171_Content_143 = {
    Text = "Drei Tage. In drei Tagen wird Lemuria sein Ende finden."
  },
  AvgDialog_47171_Content_144 = {
    Text = "Was hast du vor... mein Herr?"
  },
  AvgDialog_47171_Content_145 = {
    Text = "Ein großes Ritual geht weiter, während die Anhänger beten... meinen Namen rufen. Ich werde ganz Lemuria in den Schlaf versetzen."
  },
  AvgDialog_47171_Content_146 = {
    Text = "Ich werde ihnen die schönsten Träume gewähren."
  },
  AvgDialog_47171_Content_147 = {
    Text = "Der alte Hohe Priester sagte, er würde nicht einschlafen; er wollte mit eigenen Augen sehen, wie Lemuria im Aequor sinkt."
  },
  AvgDialog_47171_Content_148 = {
    Text = "Wie wäre es mit dir?"
  },
  AvgDialog_47171_Content_149 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47171_Content_15 = {
    Text = "Von mehreren Wachen gedrängt, verließen die Anhänger, die den Segen des Hohepriesters erhalten hatten, mit großer Freude."
  },
  AvgDialog_47171_Content_150 = {
    Text = "...Ich bin bereit, dem Ende mit Klarheit entgegenzutreten, mein Herr."
  },
  AvgDialog_47171_Content_151 = {
    Text = "Miryam geht. Tulu sinkt auf den Thron, starrt auf den leeren Raum, die unordentlichen Fischmenschen und Miryams zögerliche Gestalt."
  },
  AvgDialog_47171_Content_152 = {
    Text = "Das Gespräch zwischen dem König von Lemuria und dem Hohepriester kam zu einem Ende.\nIn den unzähligen Tagen und Nächten der kommenden Jahrtausende würde dies ihr einziges Treffen sein."
  },
  AvgDialog_47171_Content_16 = {
    Text = "Während sie ihren Rücken beobachtet, lässt Deborah einen zufriedenen Seufzer hören."
  },
  AvgDialog_47171_Content_17 = {
    Text = "Seit du der Hohe Priester geworden bist, hat Lemuria seit langem keine Naturkatastrophen mehr erlebt."
  },
  AvgDialog_47171_Content_18 = {
    Text = "Du hast diesen Ort gut geleitet. Sieh dir diese Gläubigen an, sie verehren dich wirklich!"
  },
  AvgDialog_47171_Content_19 = {
    Text = "Ich bin lediglich der Bote meines Herrn. Die Lemurier sollten nur meinen Herrn verehren."
  },
  AvgDialog_47171_Content_2 = {
    Text = "Jahre später."
  },
  AvgDialog_47171_Content_20 = {
    Text = "Bevor unser Herr den Thron bestieg, hatte ich ein solches Lemuria noch nie gesehen. Niemals hätte ich mir vorgestellt, dass ein solches Lemuria tatsächlich existieren könnte..."
  },
  AvgDialog_47171_Content_21 = {
    Text = "Miryam und Deborah standen auf den Küstenfelsen, blickten auf die lebhaften Felder, die ständig wachsende Stadt und den alten, majestätischen Tempel, der ihnen so vertraut war."
  },
  AvgDialog_47171_Content_22 = {
    Text = "Ihre Stimme ist sanft und ruhig, aber ihre Augen leuchten mit einer Leidenschaft, die die eines jeden Gläubigen weit übertrifft."
  },
  AvgDialog_47171_Content_23 = {
    Text = "Bete für unseren König, Deborah... Wir kommen dem Gottes Reich näher."
  },
  AvgDialog_47171_Content_24 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47171_Content_25 = {
    Text = "„In dem fernen sonnenlosen Abgrund schlummert die große uralte Seele...“"
  },
  AvgDialog_47171_Content_26 = {
    Text = "„... Sein Wille webt sich wie ein Netz aus Sternen; in der ewigen Leere wartet Er darauf, dass du in Seinen Traum eintrittst...“"
  },
  AvgDialog_47171_Content_27 = {
    Text = "Am nächsten zur Statue kniete Miryam allein in frommer Anbetung. Ihre Gebete flossen reibungslos, wie eine Quelle, die aus den Bergen sprudelt."
  },
  AvgDialog_47171_Content_28 = {
    Text = "Der Frühling wirbelte und floss in diesem Raum und bildete einen schwarzen Vorhang, der sie umhüllte."
  },
  AvgDialog_47171_Content_29 = {
    Text = "Die ewige Illusion der spirituellen Dimension gelangte an ihre Seite. Sie verspürte kein Unbehagen, nur ein überwältigendes Gefühl von Wärme."
  },
  AvgDialog_47171_Content_3 = {
    Text = "Ein leichter Regen war gerade vorbeigezogen und der Himmel klärte sich schnell. Sanftes Sonnenlicht schien auf einige lemurische Kinder, die am Ufer spielten."
  },
  AvgDialog_47171_Content_30 = {
    Text = "Kleine Lichtfunken flackern im Dunkeln, mit schwachen Fäden, die aus den leuchtenden Punkten hervorkommen."
  },
  AvgDialog_47171_Content_31 = {
    Text = "Wo sich Licht vereint, beleuchtet ein riesiges, strahlendes Umriss wie der Mond am Nachthimmel eine ewige weiße Nacht in dieser Illusion."
  },
  AvgDialog_47171_Content_32 = {
    Text = "Mein Herr, der schlafende König von Lemuria... Bitte verzeihen Sie mir, dass ich Ihren großen Traum stören darf."
  },
  AvgDialog_47171_Content_33 = {
    Text = "Dein Orakel hat die Menschen gerettet, und alle Katastrophen sind vor dir zurückgewichen. Im Namen der Menschen von Lemuria überbringe ich dir unsere tiefste Ehrfurcht..."
  },
  AvgDialog_47171_Content_34 = {
    Text = "Du bist der Gesandte Gottes, der Retter Lemurias. Wir bieten alles an, um dir zu helfen, das Orakel zu empfangen und das Göttliche Reich einzuläuten."
  },
  AvgDialog_47171_Content_35 = {
    Text = "Bitte führe mich. Bitte antworte deinem treuesten Gläubigen..."
  },
  AvgDialog_47171_Content_36 = {
    Text = "Ihr Bewusstsein driftete vorwärts zur Statue, die aus Sternenlicht geformt war. Sie streckte ihre Hand aus und berührte ehrfurchtsvoll die Strahlen..."
  },
  AvgDialog_47171_Content_37 = {Text = "Boom! —"},
  AvgDialog_47171_Content_38 = {
    Text = "Bevor sie die Balken berühren konnte, zerbrach die Skulptur. Die Balken kollidierten und verstreuten sich in alle Richtungen."
  },
  AvgDialog_47171_Content_39 = {
    Text = "Ein starker Windstoß schleudert Miryam nach hinten und wirft sie zu Boden."
  },
  AvgDialog_47171_Content_4 = {
    Text = "Einwohner mehrerer Städte saßen auf den Steinstufen am Ufer und sangen ein altes und freudiges Lied."
  },
  AvgDialog_47171_Content_40 = {
    Text = "Die Dunkelheit verschwand. Miryam stand verwirrt auf. Inmitten des Staubs fiel ein riesiger Stein aus unbekanntem Ort und zerschmetterte die Wand des Tempels, wobei die Statue des Königs zerbrach."
  },
  AvgDialog_47171_Content_41 = {
    Text = "Nein! Mein Herr! Das... das ist..."
  },
  AvgDialog_47171_Content_42 = {
    Text = "Steine, die einst Tentakel und der Kopf der Figur waren, liegen zertrümmert am Boden. Nur ein halber Körper verbleibt auf dem Thron. Regentropfen treiben durch das klaffende Loch in der Wand und durchnässen die einst heiligen Ruinen."
  },
  AvgDialog_47171_Content_43 = {
    Text = "Miryam, in einer Panik, kauerte sich vor der verbleibenden Statue nieder."
  },
  AvgDialog_47171_Content_44 = {
    Text = "Ist es... habe ich etwas falsch gemacht? Bitte sag es mir..."
  },
  AvgDialog_47171_Content_45 = {
    Text = "Husten... Husten..."
  },
  AvgDialog_47171_Content_46 = {
    Text = "Das Husten des alten Mannes hallte im Gebetssaal wider. Für eine ältere Person fühlten sich ein paar Jahre wie eine Ewigkeit an. Er kämpfte darum, den erstickenden Staub wegzuwinken und bewegte sich langsam vorwärts."
  },
  AvgDialog_47171_Content_47 = {
    Text = "Lehrerin? Warum bist du allein hier...?"
  },
  AvgDialog_47171_Content_48 = {
    Text = "Fühlen Sie sich danach, alleine spazieren zu gehen. Es ist lange her, dass ich einen Spaziergang gemacht habe."
  },
  AvgDialog_47171_Content_49 = {
    Text = "Er näherte sich der ruinösen Statue und verneigte sich langsam und respektvoll."
  },
  AvgDialog_47171_Content_5 = {
    Text = "Das Lied, begleitet von den Schreien der Möwen, erreichte Miryams Ohren."
  },
  AvgDialog_47171_Content_50 = {
    Text = "Miryam sieht in seine Augen, die immer noch scharf, aber mit Emotionen gefüllt sind, die sie nicht begreifen kann."
  },
  AvgDialog_47171_Content_51 = {
    Text = "Es war ein äußerst komplexes Gefühl, wie ein Neugeborenes, das dieser unbekannten Welt zum ersten Mal begegnete, wie ein Verräter, der seiner geliebten Heimat gegenüberstand."
  },
  AvgDialog_47171_Content_52 = {
    Text = "Lehrer... Was ist los? Dieses unheilvolle Zeichen... Sollen wir ein großes Opferzeremoniell durchführen?"
  },
  AvgDialog_47171_Content_53 = {
    Text = "Miryam, verneige dich vor dem König und höre auf das Dekret des Königs."
  },
  AvgDialog_47171_Content_54 = {Text = "Ja!"},
  AvgDialog_47171_Content_55 = {
    Text = "Sie verbeugte sich respektvoll. Nach dem Gruß an die Statue sah sie ihren Lehrer gespannt an, voller Vorfreude"
  },
  AvgDialog_47171_Content_56 = {
    Text = "\"In den Träumen des Königs sind die Götter verschwunden. Lemuria wurde von den Göttern verlassen.\""
  },
  AvgDialog_47171_Content_57 = {
    Text = "\"Der letzte Moment naht. Das Königreich wird in Aequor sinken, und die Zivilisation von Lemuria wird hier verschwinden.\""
  },
  AvgDialog_47171_Content_58 = {
    Text = "\"Das Göttliche Reich wird niemals ankommen.\""
  },
  AvgDialog_47171_Content_59 = {
    Text = "Lehrer... Was... was sagst du? Diese Worte... diese blasphemischen Worte..."
  },
  AvgDialog_47171_Content_6 = {
    Text = "Ist das... der Hohepriester?"
  },
  AvgDialog_47171_Content_60 = {
    Text = "Ist das ein Test? Sei unbesorgt, ich habe unerschütterlichen Glauben an den König! Ich werde dem König helfen, das Göttliche Reich zu bringen..."
  },
  AvgDialog_47171_Content_61 = {
    Text = "Diese Worte wurden vom König selbst gesprochen."
  },
  AvgDialog_47171_Content_62 = {
    Text = "Vor seiner Erhebung spürte er es in einem Traum und informierte mich... Er suchte in Träumen, und jetzt erblickt er endlich die Zukunft."
  },
  AvgDialog_47171_Content_63 = {
    Text = "Der König kann Lemuria nicht retten."
  },
  AvgDialog_47171_Content_64 = {
    Text = "Er drehte sich um und sah Miryam ernsthaft an."
  },
  AvgDialog_47171_Content_65 = {
    Text = "Er sah das Licht aus ihren Augen verblassen. Sie stand erstarrt, ihre Hände, die ans Verbeugen gewöhnt waren, fühlten sich jetzt unbehaglich und fehl am Platz an."
  },
  AvgDialog_47171_Content_66 = {
    Text = "So flusternd wie ich war, als ich zum ersten Mal über diese Dinge erfahren habe."
  },
  AvgDialog_47171_Content_67 = {
    Text = "Miryam, weißt du, was die wichtigste Verantwortung des Hohen Priesters von Lemuria ist?"
  },
  AvgDialog_47171_Content_68 = {
    Text = "Den Worten des königlichen Orakels zu lauschen, dem König zu helfen, das Göttliche Reich zu bringen, Gläubige zu organisieren, um Rituale abzuhalten... nichts davon."
  },
  AvgDialog_47171_Content_69 = {
    Text = "Die wichtigste Pflicht des Hohen Priesters ist die Täuschung."
  },
  AvgDialog_47171_Content_7 = {
    Text = "Meister Priester!"
  },
  AvgDialog_47171_Content_70 = {
    Text = "Täusche die Anhänger von Lemuria und gib ihnen einen Hauch von Licht, damit sie bis zum Ende von Lemuria mit weniger Leid leben können..."
  },
  AvgDialog_47171_Content_71 = {
    Text = "Wir teilen ein Geheimnis mit dem König. Wir sind seine Sprecher und Komplizen. Wir sind die hochrangigen Sünder von Lemuria..."
  },
  AvgDialog_47171_Content_72 = {
    Text = "Jetzt bist du einer von uns."
  },
  AvgDialog_47171_Content_73 = {
    Text = "Lehrer... meinst du... heh, nein... ich..."
  },
  AvgDialog_47171_Content_74 = {
    Text = "Miryam lächelte instinktiv."
  },
  AvgDialog_47171_Content_75 = {
    Text = "Ist das ein Scherz? Oder eine Art Test? Es muss so sein."
  },
  AvgDialog_47171_Content_76 = {
    Text = "Liegt es daran, dass ich dem König nicht ausreichend treu gewesen bin, sodass der König mich testet?"
  },
  AvgDialog_47171_Content_77 = {
    Text = "Nur ein wenig besser, nur ein wenig frommer..."
  },
  AvgDialog_47171_Content_78 = {
    Text = "Miryam dachte dies. Ihre Hand umklammerte fest den Sockel der Statue, als würde sie an einem Lebensfaden klammern."
  },
  AvgDialog_47171_Content_79 = {
    Text = "Die scharfe Kante der Statue schnitt in ihre Handfläche und das Blut tropfte unbemerkt."
  },
  AvgDialog_47171_Content_8 = {
    Text = "Als die lila Robe erschien, versammelten sich mehrere Bewohner von Lemuria um Miryam."
  },
  AvgDialog_47171_Content_80 = {
    Text = "Der alte Mann schüttelte langsam den Kopf, sein Blick fiel durch die zerbrochene Statue und dicke Tafel, hin zur fernen Himmel"
  },
  AvgDialog_47171_Content_81 = {
    Text = "Die Sterne haben mir gesagt, dass ich das Schicksal von Lemuria dir anvertrauen soll. Das sollte eigentlich meine Pflicht sein. Aber jetzt ist diese Last auf dich gefallen..."
  },
  AvgDialog_47171_Content_82 = {
    Text = "Es ist nicht fair dir gegenüber, Kleines. Überhaupt nicht. Aber zu den Sternen, dem Schicksal oder den Göttern... Fairness ist bedeutungslos."
  },
  AvgDialog_47171_Content_83 = {
    Text = "Ich kann dir keine Gerechtigkeit bringen, noch kann ich dir etwas mehr beibringen."
  },
  AvgDialog_47171_Content_84 = {
    Text = "So, mach, was du willst. Als Opfer von Ungerechtigkeit und Sünder von Lemuria hast du das Recht dazu."
  },
  AvgDialog_47171_Content_85 = {
    Text = "Die Augen des alten Priesters hielten keine Schärfe oder Autorität mehr, sondern nur Müdigkeit und Verwirrung. Er buckelte sich, während er hinausging."
  },
  AvgDialog_47171_Content_86 = {
    Text = "Der König ist erwacht und wartet auf dich."
  },
  AvgDialog_47171_Content_87 = {
    Text = "Ich denke, du möchtest Ihn treffen."
  },
  AvgDialog_47171_Content_88 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47171_Content_89 = {
    Text = "Er starrt auf das Becken."
  },
  AvgDialog_47171_Content_9 = {
    Text = "Pssst! Lass nicht zu, dass andere das entdecken!"
  },
  AvgDialog_47171_Content_90 = {
    Text = "Unzählige glitschige Köpfe tauchen auf, dann sinken sie wieder hinab. Steigen und sinken. Schmutzige Wellen stören die Oberfläche."
  },
  AvgDialog_47171_Content_91 = {
    Text = "Gewaltige Augäpfel, die zu beiden Seiten hervorquellen, rollen leer umher, während sie sich ihm entgegenstrecken. Ihre schmallippigen Münder öffnen und schließen sich, murmeln unerklärliche Silben, als versuchten sie, ihn etwas zu fragen."
  },
  AvgDialog_47171_Content_92 = {
    Text = "Hinter ihm gleiten die Schiefertüren auf."
  },
  AvgDialog_47171_Content_93 = {
    Text = "Gepriesen sei unser Herr... Gepriesen sei der große König von Lemuria..."
  },
  AvgDialog_47171_Content_94 = {
    Text = "Jedes Mal, wenn wir uns treffen, höre ich immer diesen Sarkasmus."
  },
  AvgDialog_47171_Content_95 = {
    Text = "Die massive Krone von Lemuria reflektierte einen schwachen Glanz aus einer unbekannten Quelle im Raum, die überproportional groß auf dem Körper des Jungen erschien."
  },
  AvgDialog_47171_Content_96 = {
    Text = "Die Krone auf seinem Kopf sah ganz natürlich aus, als ob sie ein Teil seines Körpers wäre."
  },
  AvgDialog_47171_Content_97 = {
    Text = "Seine schlummernden Augen verfolgen Miryams Gesicht, die Brauen zucken wie das Ausatmen des Meeres. Stille verhüllt sein jugendliches Antlitz und verbirgt jede knabenhafte Regung."
  },
  AvgDialog_47171_Content_98 = {
    Text = "Ich hatte vermutet, dass du weinen, in den Wahnsinn fallen oder versuchen würdest, mich zu töten."
  },
  AvgDialog_47171_Content_99 = {
    Text = "Du bist sehr ruhig. Ich bin mir nicht sicher, ob diese Ruhe ein Segen oder ein Fluch ist."
  },
  AvgDialog_47172_Content_1 = {Text = "Im Rege"},
  AvgDialog_47172_Content_10 = {
    Text = "\"Du solltest darüber nachdenken, was du mit dir anfangen willst; dieser Ansatz wird nicht funktionieren!\""
  },
  AvgDialog_47172_Content_100 = {
    Text = "\"Der König hat uns geschützt. Ich bin nur ein wertloser Bittsteller, doch der König hat dennoch gewählt, mich zu schützen...\""
  },
  AvgDialog_47172_Content_101 = {
    Text = "\"Du bist anders als Papa, Miryam. Du kannst ein Priester werden, unser Stolz. Du hast Bedeutung...\""
  },
  AvgDialog_47172_Content_102 = {
    Text = "\"Du kannst dem König helfen, Lemuria retten und... das Reich Gottes willkommen heißen...\""
  },
  AvgDialog_47172_Content_103 = {
    Text = "„Vater... Vater!!!“"
  },
  AvgDialog_47172_Content_104 = {
    Text = "Das Blut aus der Wunde ist fast getrocknet. Regen, vermischt mit Blutstrichen, färbt Miryams langes Kleid rot."
  },
  AvgDialog_47172_Content_105 = {
    Text = "Enos' gebeugter Körper schützt immer noch seine verstorbene Tochter vor den unerbittlichen Stürmen."
  },
  AvgDialog_47172_Content_106 = {
    Text = "Er beugte sich nieder, scheinbar nur um seine Tochter zu umarmen, verabschiedete sich von den Mühen des Tages und trat in den süßen Schlaf der Nacht ein."
  },
  AvgDialog_47172_Content_107 = {
    Text = "„Vater... ich... es tut mir leid... ich habe versagt...“"
  },
  AvgDialog_47172_Content_108 = {
    Text = "Bedauern und Schmerz fühlten sich an wie ein endloser, erdrückender schwarzer Nebel, der Miryam erstickte. Sie umklammert fest die Körper ihres Vaters und ihrer Schwester."
  },
  AvgDialog_47172_Content_109 = {
    Text = "Der Regen schien etwas nachzulassen. Sie schaute auf und sah einen schwarzen Regenschirm, der den Himmel schützte."
  },
  AvgDialog_47172_Content_11 = {
    Text = "\"Heute ist es glücklicherweise nur ein Übung. Ohne Priester, die zusehen, sonst würdest du wieder ausgeschimpft werden...\""
  },
  AvgDialog_47172_Content_110 = {
    Text = "Miryam drehte sich um und sah eine Reihe von Wachen, sowie den alten Mann im heiligen Gewand, der in der Mitte stand."
  },
  AvgDialog_47172_Content_111 = {
    Text = "Es war, als ob sie einen Lebensfaden entdeckt hätte; sie kniete und kroch auf den alten Mann zu."
  },
  AvgDialog_47172_Content_112 = {
    Text = "\"Hochpriester! Hochpriester, bitte rette meinen Vater!\""
  },
  AvgDialog_47172_Content_113 = {
    Text = "\"Wächter, bringt sie weg.\""
  },
  AvgDialog_47172_Content_114 = {
    Text = "\"Meine Sünden sind meine zu tragen! Aber mein Vater, er war immer der loyalste Gläubige des Königs... Bitte rette ihn!\""
  },
  AvgDialog_47172_Content_115 = {
    Text = "\"Du verstehst nicht, Miryam.\""
  },
  AvgDialog_47172_Content_116 = {
    Text = "\"Lemuria ist es egal, ob das Leben oder Sterben eines Gläubigen, noch kümmert es sich um deine Sünden.\""
  },
  AvgDialog_47172_Content_117 = {
    Text = "\"Was die Lemurier betrifft, ist nur die Zukunft in ihren Träumen wichtig—die Zukunft, ein Götterreich zu werden.\""
  },
  AvgDialog_47172_Content_118 = {
    Text = "\"Du könntest ein Teil der Zukunft sein, aber... es hängt von deiner eigenen Entscheidung ab.\""
  },
  AvgDialog_47172_Content_119 = {
    Text = "Der alte Priester blickte zum Himmel auf. Seine scharfen Augen schienen ein Gespräch zu führen, das Miryam nicht verstand."
  },
  AvgDialog_47172_Content_12 = {
    Text = "\"Scheltungen zu bekommen, sind meine geringsten Sorgen. Wäre ich der Priester, hätte ich mich vielleicht selbst aus den Reihen der Priesterlehrlinge ausgeschlossen.\""
  },
  AvgDialog_47172_Content_120 = {
    Text = "\"Miryam, glaubst du an den König?\""
  },
  AvgDialog_47172_Content_121 = {
    Text = "\"Ich glaube an den König, Hoher Priester. Ich glaube an den König! Ich bin ein Anhänger des Königs... Ich bin bereit, alles zu tun!\""
  },
  AvgDialog_47172_Content_122 = {
    Text = "\"Also, würdest du deinen Vater für den König töten?\""
  },
  AvgDialog_47172_Content_123 = {
    Text = "„Das... ich...“"
  },
  AvgDialog_47172_Content_124 = {
    Text = "\"Miryam, glaubst du an den König?!\""
  },
  AvgDialog_47172_Content_125 = {
    Text = "Der hochrangige Priester trat plötzlich auf sie zu, seine Augen starrten scharf wie eine Klinge auf sie."
  },
  AvgDialog_47172_Content_126 = {
    Text = "Miryam erstarrte. Die Frage des Oberhauptes ließ sie fast vergessen, um Hilfe von ihrem Vater zu rufen."
  },
  AvgDialog_47172_Content_127 = {
    Text = "„Es gibt einen Weg, deinen Vater am Leben zu halten.“"
  },
  AvgDialog_47172_Content_128 = {
    Text = "\"Erzpriester?!!!\""
  },
  AvgDialog_47172_Content_129 = {
    Text = "\"Nun, antworte mir. Was ist Glauben?\""
  },
  AvgDialog_47172_Content_13 = {
    Text = "\"Du weißt es, nicht wahr? Wie kannst du trotz allem noch lächeln! Es ist fast ein halbes Jahr vergangen, und du kannst das Fischmann-Ritual immer noch nicht jedes Mal durchführen – es wird gefährlich!\""
  },
  AvgDialog_47172_Content_130 = {
    Text = "\"Ich... weiß nicht... Meister...\""
  },
  AvgDialog_47172_Content_131 = {
    Text = "\"Glaube ist das Fundament aller Verantwortung und Bedeutung. Es lässt keinen Platz für etwas anderes.\""
  },
  AvgDialog_47172_Content_132 = {
    Text = "\"Nur durch den Glauben an den König kannst du deinen Vater retten.\nUm diesen Glauben zu gewinnen, musst du zuerst deinen Vater töten.\""
  },
  AvgDialog_47172_Content_133 = {
    Text = "\"Meisterpriester... Ich... verstehe nicht...\""
  },
  AvgDialog_47172_Content_134 = {
    Text = "Der Hohe Priester ging langsam auf Miryam zu, starrte ihr in die Augen und suchte nach jedem subtilen Wellenzug."
  },
  AvgDialog_47172_Content_135 = {
    Text = "\"Nur indem du deinen Vater in einen Meermann verwandelst, kannst du sein Leben retten.\""
  },
  AvgDialog_47172_Content_136 = {
    Text = "\"Vergiss deinen Vater. Vergiss deine Familie. Widme dich dem Gott von Lemuria, preise Ihn und folge Ihm. Vollziehe wie ein Priester das Transformationsritual, wie es vom Gott geleitet wird.\""
  },
  AvgDialog_47172_Content_137 = {
    Text = "\"Um deinen Vater zu retten und deine Sünden zu sühnen, ist dies der einzige Weg.\""
  },
  AvgDialog_47172_Content_138 = {
    Text = "Er blickte auf Miryams zerbrechliche Gestalt auf dem Boden, als würde er eine Prophezeiung von Zerstörung und Wiedergeburt, von Abgrund und Hoffnung sehen."
  },
  AvgDialog_47172_Content_139 = {
    Text = "\"Also, Miryam, bist du bereit, deinen Vater zu töten?\""
  },
  AvgDialog_47172_Content_14 = {
    Text = "\"Du begreifst diese komplexen Kräutertheorie-Kurse schneller als jeder andere, warum kannst du mit diesem Ritual nicht umgehen...\""
  },
  AvgDialog_47172_Content_15 = {
    Text = "\"Es tut mir leid, ich... ich kann mich nicht dazu bringen, ihnen so etwas Grausames anzutun... ich kann einfach nicht...\""
  },
  AvgDialog_47172_Content_16 = {
    Text = "\"Mit so unglaublichem Talent, wie könntest du überhaupt versagen? So wie der Hohe Priester sagte, musst du nur von ganzem Herzen für den König beten und alles andere vergessen. Du kannst es schaffen!\""
  },
  AvgDialog_47172_Content_17 = {
    Text = "\"Deborah, ich wirklich... Jedes Mal, wenn ich diese Gebete und diese fischähnlichen Kreaturen sehe, denke ich an meine Familie.\""
  },
  AvgDialog_47172_Content_18 = {
    Text = "\"Diejenigen, die immer an meiner Seite erschienen sind, um mich zu beschützen, sind meine Familie, nicht der König...\""
  },
  AvgDialog_47172_Content_19 = {
    Text = "\"Pssst! Was für einen Unsinn redest du?!\""
  },
  AvgDialog_47172_Content_2 = {
    Text = "Mehrere Monate später."
  },
  AvgDialog_47172_Content_20 = {
    Text = "\"<Mein Herr>, bitte vergib Miryam; ihr Geist wurde von den Tiefen Wesen erschreckt... Bitte vergib ihr, bitte vergib...\""
  },
  AvgDialog_47172_Content_21 = {
    Text = "Deborah neigte respektvoll ihren Kopf vor der Statue im Gebetssaal und starrte dann wütend auf Miryam."
  },
  AvgDialog_47172_Content_22 = {
    Text = "\"Achte auf deine Worte! Wenn der König das hört, wirst du bestraft!\""
  },
  AvgDialog_47172_Content_23 = {
    Text = "\"Es tut mir leid... Ich hätte das nicht sagen sollen...\""
  },
  AvgDialog_47172_Content_24 = {
    Text = "\"Du solltest nicht so denken! Ach, vergiss es. Es gibt keinen Grund zur Eile. Wir nehmen uns Zeit.\""
  },
  AvgDialog_47172_Content_25 = {
    Text = "„Die Lemurier kümmern sich hauptsächlich um ihren König, aber du scheinst mehr um deine Familie besorgt zu sein. Doch, ich habe noch nie gehört, dass du über sie sprichst?“"
  },
  AvgDialog_47172_Content_26 = {
    Text = "\"Habe sie seit einem halben Jahr nicht gesehen. Du musst sie sehr vermissen... Möchtest du darüber reden?\""
  },
  AvgDialog_47172_Content_27 = {
    Text = "\"Ist das in Ordnung? Es könnte lange dauern, es zu erklären, und es sind alles nur triviale Angelegenheiten...\""
  },
  AvgDialog_47172_Content_28 = {
    Text = "\"Wie auch immer, es spielt keine Rolle. Nimm dir Zeit, mir zu erzählen, und ich werde geduldig zuhören.\""
  },
  AvgDialog_47172_Content_29 = {
    Text = "\"Ich versuche herauszufinden, wo ich anfangen soll... Hmm, in der Vergangenheit lebte ich mit meinem Vater, meiner Mutter und meiner jüngeren Schwester.\""
  },
  AvgDialog_47172_Content_3 = {
    Text = "Sie hielt einen rituellen Dolch und starrte auf das halb-menschliche, halb-fischartige Wesen auf dem Steinaltar."
  },
  AvgDialog_47172_Content_30 = {
    Text = "\"Als ich jung war, starb meine Mutter aufgrund von Naturkatastrophen, und mein Vater zog uns allein groß. Er ist ein großartiger Mann, der unsere Familie immer beschützt hat.\""
  },
  AvgDialog_47172_Content_31 = {
    Text = "„Meine Schwester ist auch sehr süß. Obwohl sie manchmal etwas unvorsichtig sein kann, ist sie klug und sehr verständnisvoll...“"
  },
  AvgDialog_47172_Content_32 = {
    Text = "\"Wenn ich darüber nachdenke, sind eure Persönlichkeiten ziemlich ähnlich. Wie wäre es, wenn ich heute eine weitere kleine Schwester aufnehme?\""
  },
  AvgDialog_47172_Content_33 = {
    Text = "\"Nun, Miryam, du weißt wirklich, wie du mich ausnutzen kannst!\""
  },
  AvgDialog_47172_Content_34 = {
    Text = "Miryam erzählte diese Dinge selten anderen. Zuerst war sie nicht ganz daran gewöhnt, sprach intermittierend. Aber bald wurden ihre Worte fließend und leicht."
  },
  AvgDialog_47172_Content_35 = {
    Text = "Sie erzählte Deborah ausführlich von den Familienerinnerungen und lächelte, als würde sie ihre geheimen Schätze offenbaren"
  },
  AvgDialog_47172_Content_36 = {
    Text = "Inmitten des schwachen Donners gingen sie den langen, friedlichen Gang entlang, spielend und lachend."
  },
  AvgDialog_47172_Content_37 = {
    Text = "......Am Tag bevor ich zum Tempel kam, bereitete er mir einen Tisch mit Fisch. Ich tat so, als ob ich es sehr mochte und aß jeden Fisch auf diesem Teller. Er sah in diesem Moment so glücklich aus"
  },
  AvgDialog_47172_Content_38 = {
    Text = "\"Hahaha... Wenn dein Vater die Wahrheit wüsste, wäre er definitiv wütend!\""
  },
  AvgDialog_47172_Content_39 = {
    Text = "\"Ich habe meiner Schwester versprochen, dass er niemals davon erfahren wird. Wenn ich zurückkomme, muss ich wieder seinen Fisch essen... Ugh, allein der Gedanke daran verursacht Kopfschmerzen.\""
  },
  AvgDialog_47172_Content_4 = {
    Text = "Der Klang von Wind und Regen, zusammen mit dem fernen Donner, durchdrang die dicken Steinmauern und hallte dumpf im Tempel wider."
  },
  AvgDialog_47172_Content_40 = {
    Text = "„Kopfschmerzen? Du scheinst mir ziemlich glücklich zu sein. Du leidest, aber genießt es~ Das hast du davon~“"
  },
  AvgDialog_47172_Content_41 = {
    Text = "Klang! Klang! Klang!—"
  },
  AvgDialog_47172_Content_42 = {
    Text = "Der Klang von zusammenschlagenden Waffen und hastigen Schritten hallte durch die innere Halle und unterbrach ihr Gespräch."
  },
  AvgDialog_47172_Content_43 = {Text = "\"Halt!\""},
  AvgDialog_47172_Content_44 = {
    Text = "„Notfall! ... Katastrophe ... Südtal ... Opfer ... Erholungsteam ... Vermeide die Plage ...“"
  },
  AvgDialog_47172_Content_45 = {
    Text = "Einige Worte erreichten Miryams Ohren aus der Ferne, und die Wachen hurried in die tiefere Halle. Sie hielt plötzlich an."
  },
  AvgDialog_47172_Content_46 = {
    Text = "\"Südliches Tal... Miryam, du hast gerade gesagt, dein Zuhause ist dort um die Ecke...\""
  },
  AvgDialog_47172_Content_47 = {
    Text = "\"Deborah, ich muss zurück!\""
  },
  AvgDialog_47172_Content_48 = {
    Text = "Miryam nickte schnell und schaute ängstlich umher, als ob sie nach etwas suchte."
  },
  AvgDialog_47172_Content_49 = {
    Text = "\"Bist du verrückt? Es ist ein schweres Verbrechen für einen Priesterlehrling, aus dem Tempel zu fliehen!\""
  },
  AvgDialog_47172_Content_5 = {
    Text = "\"Anhänger meines Herrn, bitte, bitte öffnet eure Herzen und akzeptiert... akzeptiert meinen Herrn...\""
  },
  AvgDialog_47172_Content_50 = {
    Text = "\"Mach dir keine Sorgen, Miryam... Deiner Familie wird es gut gehen...\""
  },
  AvgDialog_47172_Content_51 = {
    Text = "\"Nein, Deborah... Das Terrain im Südtal ist tückisch... genau wie Mutter vorher...\""
  },
  AvgDialog_47172_Content_52 = {
    Text = "\"Ich habe ein Gefühl... Ich muss zurückgehen und es überprüfen!\""
  },
  AvgDialog_47172_Content_53 = {
    Text = "\"Aber... das Zusammentreffen aller Lehrlinge steht kurz bevor und ich kann mir keinen Weg vorstellen, um zu helfen...\""
  },
  AvgDialog_47172_Content_54 = {
    Text = "\"Ah! Miryam... du...\""
  },
  AvgDialog_47172_Content_55 = {
    Text = "Eine starke Schläfrigkeit überkam ihren Verstand. Es war ein hypnotisches Kraut, das in Opferzeremonien verwendet wurde und von den Priestern getragen wurde."
  },
  AvgDialog_47172_Content_56 = {
    Text = "Es hilft den Gläubigen, Frieden zu finden und unterstützt die Priester dabei, Sünden zu verringern."
  },
  AvgDialog_47172_Content_57 = {
    Text = "Unter allen Lehrlingen war Miryam die fähigste in diesen Kursen, und Deborah hatte das schon immer gewusst."
  },
  AvgDialog_47172_Content_58 = {
    Text = "\"Ich möchte dich da nicht mit hineinziehen. Ruh dich einfach etwas aus.\""
  },
  AvgDialog_47172_Content_59 = {
    Text = "\"Ich muss zurückkehren... Es tut mir leid, Deborah.\""
  },
  AvgDialog_47172_Content_6 = {
    Text = "\"Es tut mir leid... ähm—\""
  },
  AvgDialog_47172_Content_60 = {
    Text = "Sie setzte Deborah sanft in eine unauffällige Ecke. Bevor die Wachen zurückkehrten, drehte sie sich um und rannte zur Außenseite des Tempels."
  },
  AvgDialog_47172_Content_61 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47172_Content_62 = {
    Text = "\"Höre auf meinen Herrn. Widme dich meinem Herrn.\""
  },
  AvgDialog_47172_Content_63 = {
    Text = "Tropischer Regen. Heftiger Wind. Donner."
  },
  AvgDialog_47172_Content_64 = {
    Text = "\"Den Gläubigen wird mein Herr Gnade erweisen.\""
  },
  AvgDialog_47172_Content_65 = {
    Text = "Einstürzende Häuser. Weinen crowds. Trümmer stürzen herab wie verstreute Bausteine von den Berghängen."
  },
  AvgDialog_47172_Content_66 = {
    Text = "\"Allen, die es wünschen, wird mein Herr gewähren.\""
  },
  AvgDialog_47172_Content_67 = {
    Text = "Die Welt in ihren Augen nahm eine andere Farbe an, als ob sie von einem blutgetönten Filter bedeckt wäre."
  },
  AvgDialog_47172_Content_68 = {
    Text = "Nachdem sie stundenlang im Regen gelaufen war, war sie sich nicht sicher, ob dies ihre Heimatstadt war."
  },
  AvgDialog_47172_Content_69 = {
    Text = "Warum sind all diese vertrauten Straßen und Gebäude verschwunden?"
  },
  AvgDialog_47172_Content_7 = {
    Text = "Sie rannte zur Seite, hielt sich den Mund zu und konnte kaum auf den Beinen stehen, lehnte sich gegen die Wand, während ihr Magen krampfte."
  },
  AvgDialog_47172_Content_70 = {
    Text = "Warum sind viele dieser bekannten Nachbarn verschwunden?"
  },
  AvgDialog_47172_Content_71 = {
    Text = "Sie ist die ganze Strecke hierher gereist, aber jetzt will sie einfach nur gehen. Doch ihre Beine zogen sie weiterhin zurück nach Hause."
  },
  AvgDialog_47172_Content_72 = {
    Text = "—Das Zuhause, das ihr unzählige Lachen und Tränen brachte. Ein Zuhause, das von unzähligen Katastrophen verwüstet wurde, aber immer wieder neu aufgebaut wurde."
  },
  AvgDialog_47172_Content_73 = {
    Text = "Das einst wohlhabende Zuhause liegt jetzt in Trümmern."
  },
  AvgDialog_47172_Content_74 = {
    Text = "\"All suffering will be repaid by our Lord.\"  -> \"Alles Leid wird von unserem Herrn vergolten.\""
  },
  AvgDialog_47172_Content_75 = {
    Text = "Der Mann kniete unter den Ruinen, völlig indifferent gegenüber den scharfen Steinen und Splittern."
  },
  AvgDialog_47172_Content_76 = {
    Text = "Der starke Regen prasselte auf seinen Rücken. Er beugte seine Wirbelsäule und versuchte, seinen Körper in einen improvisierten Schutz gegen den Sturm zu krümmen."
  },
  AvgDialog_47172_Content_77 = {
    Text = "Die Dachüberstände konnten keinen Schutz bieten. Egal wie sehr er versuchte, sie zu schützen, der starke Regen drang durch seinen kleinen Körper und tropfte auf den leblosen Körper des kleinen Mädchens in seinen Armen."
  },
  AvgDialog_47172_Content_78 = {
    Text = "Er konnte nur weiter ihr Gesicht mit seinen groben Händen streicheln und das Regenwasser von ihrem allmählich abkühlenden und bleichenden Gesicht wischen."
  },
  AvgDialog_47172_Content_79 = {
    Text = "\"Sa... Sara... nein...\""
  },
  AvgDialog_47172_Content_8 = {
    Text = "\"Miryam, geht es dir gut?\""
  },
  AvgDialog_47172_Content_80 = {
    Text = "Miryams Stimmbänder vibrierte kaum, ihre Stimme war fast unhörbar. Sie ging vorwärts, fiel, kroch gedämpft zu dem Körper ihrer Schwester und berührte ihn mit zitternden Händen."
  },
  AvgDialog_47172_Content_81 = {
    Text = "\"Zu diesem Zeitpunkt schlief sie. Du weißt ja, Sara schläft immer fest. Nichts kann sie aufwecken.\""
  },
  AvgDialog_47172_Content_82 = {
    Text = "\"Sie ging friedlich... ohne Angst, ohne Schmerz, ohne Sehnsucht, nichts.\""
  },
  AvgDialog_47172_Content_83 = {
    Text = "\"Damals, als deine Mutter starb, sagte ich mir dasselbe.\""
  },
  AvgDialog_47172_Content_84 = {
    Text = "\"Das ist der einzige Weg, wie ich mich trösten kann, Miryam... Ich konnte sie nicht beschützen, und dies ist alles, was ich tun kann...\""
  },
  AvgDialog_47172_Content_85 = {
    Text = "Der Mann dachte, seine Tränen wären längst getrocknet, doch sobald er ein paar Worte sprach, vermischten sie sich wieder mit dem Regen. Seine blassen Lippen, zitternd vor Kälte und Erschöpfung, bebten leicht."
  },
  AvgDialog_47172_Content_86 = {
    Text = "Enos hustete schmerzlich. Miryam bemerkte zwei große Wunden an seinem Bein und Bauch, aus denen das letzte Blut herausquoll."
  },
  AvgDialog_47172_Content_87 = {
    Text = "\"Vater! Du... bist verletzt?...\""
  },
  AvgDialog_47172_Content_88 = {
    Text = "Sie nahm hektisch einige unbekannte Kräuter heraus und trug sie auf die Wunde ihres Vaters auf, dann sah sie verzweifelt nach etwas Nützlichem um."
  },
  AvgDialog_47172_Content_89 = {
    Text = "\"Miryam, das hat keinen Sinn.\""
  },
  AvgDialog_47172_Content_9 = {
    Text = "\"Mir geht's gut... Entschuldige, Deborah, ich habe dich warten lassen...\""
  },
  AvgDialog_47172_Content_90 = {
    Text = "\"Ich kann dich retten... Ich kann dich retten, Vater!\""
  },
  AvgDialog_47172_Content_91 = {
    Text = "\"Ich habe alles getan, was ich konnte, Miryam. Aber es war alles umsonst... sie sind immer noch gestorben. Deine Mutter, deine Schwester...\""
  },
  AvgDialog_47172_Content_92 = {
    Text = "\"In Lemuria hat das, was jemand wie ich tut, keine Bedeutung...\""
  },
  AvgDialog_47172_Content_93 = {
    Text = "Er mühte sich, seinen Kopf zu heben, während er auf die zusammengebrochenen Berge, die Ruinen um sich herum und den gleichgültigen Himmel starrte, der sorglos das Unheil über die Insel gebracht hatte."
  },
  AvgDialog_47172_Content_94 = {
    Text = "Seinem Blick folgend, schaute Miryam auf die Berge auf beiden Seiten."
  },
  AvgDialog_47172_Content_95 = {
    Text = "„Vater, das ist...“"
  },
  AvgDialog_47172_Content_96 = {
    Text = "Riesige Felsen rollten den Berg hinunter und drohten, die ganze Stadt vollständig zu verschlingen."
  },
  AvgDialog_47172_Content_97 = {
    Text = "Mehrere massive Tentakel sind aus dem Boden hervorgetreten und blockieren die meisten der erschreckenden Steine."
  },
  AvgDialog_47172_Content_98 = {
    Text = "Inos senkte den Kopf und schaute auf seine Tochter, seine einzige verbleibende Hoffnung und seinen Stolz."
  },
  AvgDialog_47172_Content_99 = {
    Text = "\"Es ist das Wunder des Königs...\""
  },
  AvgDialog_47173_Content_1 = {
    Text = "Königliches Opfer"
  },
  AvgDialog_47173_Content_10 = {
    Text = "Ich erinnere mich, Vater... an alles."
  },
  AvgDialog_47173_Content_100 = {
    Text = "Wenn du dich nicht mit dem Traum des Königs verbinden kannst, wirst du in Qualen sterben."
  },
  AvgDialog_47173_Content_101 = {
    Text = "Wenn du überlebst, zieh diese Kleidung an. Ich werde dich anleiten, ein wahrer Lemurianer-Priester zu werden."
  },
  AvgDialog_47173_Content_102 = {
    Text = "Es scheint, eine entmutigende Aufgabe wurde abgeschlossen, oder ein abscheuliches Verbrechen begangen. Der alte Mann ließ einen tiefen Seufzer hören, beugte sich über seinen Körper und verließ den Gebetsraum."
  },
  AvgDialog_47173_Content_103 = {
    Text = "Miryam ging mechanisch zur Statue und hob das Weinglas auf."
  },
  AvgDialog_47173_Content_104 = {
    Text = "Du hast deinen Vater getötet."
  },
  AvgDialog_47173_Content_105 = {
    Text = "Es war ein Gesicht, das Miryam gut kannte, sich jedoch so fremd anfühlte."
  },
  AvgDialog_47173_Content_106 = {
    Text = "Die achtzehnjährige Miryam sah zur Seite und sah ihr neunjähriges Ich neben sich sitzen, das die Statue ansah."
  },
  AvgDialog_47173_Content_107 = {
    Text = "Nein, ich habe Vater gerettet... Er hat uns unzählige Male beschützt. Jetzt ist es unsere Aufgabe, ihn zu beschützen."
  },
  AvgDialog_47173_Content_108 = {
    Text = "Aber Vater hätte dich nicht so sehen wollen..."
  },
  AvgDialog_47173_Content_109 = {
    Text = "Er wird. Mein Vater wird Schmerz empfinden, wird Trauer empfinden, aber er wird mich unterstützen."
  },
  AvgDialog_47173_Content_11 = {
    Text = "Dieser Weg fühlt sich wirklich an wie der, der nach Hause führt."
  },
  AvgDialog_47173_Content_110 = {
    Text = "Nur dann kann ich Lemuria wirklich helfen und das Reich Gottes zu ihm bringen..."
  },
  AvgDialog_47173_Content_111 = {
    Text = "So viel Schlangenblut, nur wenige können damit umgehen. Suchst du den Tod?"
  },
  AvgDialog_47173_Content_112 = {
    Text = "Miryam... glaubst du an das Göttliche Reich?"
  },
  AvgDialog_47173_Content_113 = {
    Text = "Sie starrte in ihre Augen, als ob sie einen unschuldigen Gott ansähe. Die Augen des neunjährigen Mädchens trugen eine tiefere Traurigkeit als die der achtzehnjährigen Miryam."
  },
  AvgDialog_47173_Content_114 = {
    Text = "...Woran kann ich sonst glauben?"
  },
  AvgDialog_47173_Content_115 = {
    Text = "Miryam lächelte sie an, hob ihr Glas und starrte ehrfurchtsvoll auf die Statue vor ihr."
  },
  AvgDialog_47173_Content_116 = {
    Text = "Ich biete dir alles an. Antworte auf mein Flehen, mein Herr."
  },
  AvgDialog_47173_Content_117 = {
    Text = "Das Blut ihres Vaters tropfte von ihrem Gesicht und vermischte sich mit dem Schlangenblut in der Tasse."
  },
  AvgDialog_47173_Content_118 = {
    Text = "Ohne Zögern kippte sie den Kopf zurück und trank die Flüssigkeit mit dem starken fischigen Geruch in einem Schluck."
  },
  AvgDialog_47173_Content_12 = {
    Text = "Die Tochter ist jetzt erwachsen. Wenn Papa müde ist, hat er endlich jemanden, an den er sich anlehnen kann."
  },
  AvgDialog_47173_Content_13 = {
    Text = "Miryam sah ihren Vater an. Derjenige, der einst vor ihr erschien wie ein himmlisches Wesen, sie schützend und die ganze Familie unterstützend, war jetzt unglaublich alt und schwach."
  },
  AvgDialog_47173_Content_14 = {
    Text = "Wie ein trügerischer Stein, wenn die harte Schale bricht, zeigt sich ein zerbrechliches Herz darin."
  },
  AvgDialog_47173_Content_15 = {
    Text = "Wir sind angekommen. Steigen Sie aus dem Fahrzeug aus."
  },
  AvgDialog_47173_Content_16 = {
    Text = "Der Wagen hält. Im Dunkel der Ritualkammer brennen Öllampen schwach. Der Kandelaber dreht sich langsam, seine Oberfläche mit sich windenden Tentakeln und hervorstehenden Augen verziert — alle beobachten die Menschen, die sich geschäftig darunter bewegen."
  },
  AvgDialog_47173_Content_17 = {
    Text = "In der Mitte eines blutroten Magiekreises, der mit alten Symbolen gezeichnet ist, liegt ein einsames Steint bed auf dich."
  },
  AvgDialog_47173_Content_18 = {
    Text = "Miryam half ihrem Vater auf das Steinkissen."
  },
  AvgDialog_47173_Content_19 = {
    Text = "Nur ein paar Schritte schienen Innos' gesamte Kraft entzogen zu haben. Er hustete schmerzlich, fast ohnmächtig."
  },
  AvgDialog_47173_Content_2 = {
    Text = "Im Tempel, so sieht es also aus..."
  },
  AvgDialog_47173_Content_20 = {
    Text = "Es ist alles in Ordnung, Vater, es ist alles in Ordnung... Du wirst bald gesund werden..."
  },
  AvgDialog_47173_Content_21 = {
    Text = "Es war in diesem Raum, dass dein Ritual viele Male gescheitert ist."
  },
  AvgDialog_47173_Content_22 = {
    Text = "Ich... erinnere mich, Hoher Priester."
  },
  AvgDialog_47173_Content_23 = {
    Text = "Wenn du dem Befehl des Königs nicht von ganzem Herzen folgen und seine Zustimmung gewinnen kannst, wird dein Ritual dennoch scheitern."
  },
  AvgDialog_47173_Content_24 = {
    Text = "Du kannst dich entscheiden, aufzugeben. Ich werde sicherstellen, dass sein Tod schmerzlos ist."
  },
  AvgDialog_47173_Content_25 = {Text = "Ich..."},
  AvgDialog_47173_Content_26 = {
    Text = "Dies ist dein Schicksal. Denk darüber nach, dann triff deine Entscheidung."
  },
  AvgDialog_47173_Content_27 = {
    Text = "Die Wachen legten die für das Ritual benötigten Werkzeuge und Materialien beiseite und verließen den Raum zusammen mit dem Hauptpriester."
  },
  AvgDialog_47173_Content_28 = {
    Text = "Das kalte, schwache Kerzenlicht erleuchtet die letzten zwei Bewohner des Raumes."
  },
  AvgDialog_47173_Content_29 = {
    Text = "Miryam kniet am steinernen Bett und vergräbt ihren Kopf in der Brust ihres Vaters."
  },
  AvgDialog_47173_Content_3 = {
    Text = "Sarah erwähnte vor einigen Tagen, dass sie ihre Schwester vermisst und sie besuchen möchte, um zu sehen, wie es bei ihrer Schwester aussieht."
  },
  AvgDialog_47173_Content_30 = {
    Text = "Was soll ich tun... Vater..."
  },
  AvgDialog_47173_Content_31 = {
    Text = "Du hast geweint, Kind... Was hat unsere kleine Miryam so traurig gemacht?"
  },
  AvgDialog_47173_Content_32 = {
    Text = "Ein Paar Hände streicheln sanft Miryams Kopf, trösten sie, wie sie es immer getan haben, seit sie ein Kind war, wann immer sie traurig war."
  },
  AvgDialog_47173_Content_33 = {
    Text = "Miryam konnte nicht aufhören zu weinen. Ihr Körper erzitterte, während Tränen auf Enos' kalten, nassen Körper fielen."
  },
  AvgDialog_47173_Content_34 = {
    Text = "Sie hielt die Hand ihres Vaters fest, als könnte ihr fester Griff ihn an ihrer Seite halten."
  },
  AvgDialog_47173_Content_35 = {
    Text = "Miryam, hast du das gehört? Es ist die Stimme deiner Mutter... Sie ruft uns zum Essen nach Hause. Und Sarah, sie winkt uns zu..."
  },
  AvgDialog_47173_Content_36 = {
    Text = "Ich habe es gesehen... Vater, ich habe es gesehen..."
  },
  AvgDialog_47173_Content_37 = {
    Text = "Ich habe deiner Mutter gesagt, dass wir heute Fisch haben werden. Papa weiß, dass es dein Favorit ist."
  },
  AvgDialog_47173_Content_38 = {
    Text = "Deine Mutter weiß noch nicht, dass unsere Miryam ein Priesterlehrling geworden ist. Sag es ihr später; das wird sie bestimmt überraschen."
  },
  AvgDialog_47173_Content_39 = {
    Text = "Bald wirst du ein Priester, nicht wahr?"
  },
  AvgDialog_47173_Content_4 = {
    Text = "Inos streichelt sanft das Gesicht seiner kleinen Tochter."
  },
  AvgDialog_47173_Content_40 = {
    Text = "...Ja, Vater, bald werde ich ein Priester werden..."
  },
  AvgDialog_47173_Content_41 = {
    Text = "Ich wusste es. Du hast Talent, und ich habe das immer gewusst."
  },
  AvgDialog_47173_Content_42 = {
    Text = "Die Menschen von Lemuria führen ein hartes Leben. Ich mochte Lemuria nie, Kleiner, aber ich kann nicht gehen... denn du bist hier, und mein Zuhause ist hier."
  },
  AvgDialog_47173_Content_43 = {
    Text = "Ich kann viele Dinge tun—Häuser bauen, für Geld fischen, für dich kochen... aber ich kann nichts ändern."
  },
  AvgDialog_47173_Content_44 = {
    Text = "Du bist anders, Miryam. Du wirst der vertrauenswürdigste Vertraute des Königs werden und dem König helfen, Lemuria zum sagenumwobenen Göttlichen Reich zu machen..."
  },
  AvgDialog_47173_Content_45 = {
    Text = "Im Gott-Reich gibt es eine endlose Versorgung mit Speisen und feinem Wein, mit täglich konstant schönem Wetter und klarem Himmel. Niemand wird mehr an Katastrophen sterben."
  },
  AvgDialog_47173_Content_46 = {
    Text = "Wir werden ein stabiles Steinhaus haben... Inos, Paya, Miryam, Sarah. In diesem Haus wird unsere Familie glücklich zusammen leben..."
  },
  AvgDialog_47173_Content_47 = {
    Text = "Ja, Vater... wir werden uns im Göttlichen Reich wiedersehen! Unsere Familie wird gemeinsam im Göttlichen Reich leben..."
  },
  AvgDialog_47173_Content_48 = {
    Text = "Sie wischt sich die Tränen ab und steht langsam auf. Ihre Hand greift nach dem Dolch neben dem Bett."
  },
  AvgDialog_47173_Content_49 = {
    Text = "Die Klinge des Dolches biegt sich in einem bizarren Bogen, eingraviert mit kunstvollen Hieroglyphen, die eine verwirrende Ähnlichkeit mit jenen in Gebeten aufweisen."
  },
  AvgDialog_47173_Content_5 = {
    Text = "Die teuren Kräuter retteten ihm vorübergehend das Leben. Dieser gläubige Anhänger betrat zum ersten Mal die heilige Halle und kam dem König so nah."
  },
  AvgDialog_47173_Content_50 = {
    Text = "Next to the dagger, the blood in the stone basin, which shares origin with the Götter, ripples slightly. The candlelight reflects, casting a dark and eerie sheen."
  },
  AvgDialog_47173_Content_51 = {
    Text = "Schweres Delirium hat Enos den Großteil seines Bewusstseins geraubt. Er betrachtet Miryam mit Neugier, wie ein Neugeborenes, das die Welt zum ersten Mal erblickt."
  },
  AvgDialog_47173_Content_52 = {
    Text = "Miryam, du bist jetzt ein Priester... Hast du den König gefragt? Hat der König dir gesagt, wann Gottes Reich in Lemuria ankommen wird?"
  },
  AvgDialog_47173_Content_53 = {
    Text = "Ja, ich habe um Seine Führung gebetet... Er hat verkündet, dass es bald sein wird, sehr bald..."
  },
  AvgDialog_47173_Content_54 = {
    Text = "Ein schwaches, blasses Lächeln formt sich inmitten der verschlungenen Tränenspuren. Sie nähert sich Enos, beugt sich hinunter und berührt seine Wange."
  },
  AvgDialog_47173_Content_55 = {
    Text = "Ich werde dich nicht enttäuschen, Vater."
  },
  AvgDialog_47173_Content_56 = {
    Text = "Das Reich der Götter naht, Vater. Bald werden wir als Familie wieder vereint sein..."
  },
  AvgDialog_47173_Content_57 = {Text = "Zack—"},
  AvgDialog_47173_Content_58 = {
    Text = "Der Dolch dringt tief in Enos' Brust. Ein Schrei brennender Qual bricht hervor. Sein Blut spritzt unkontrolliert und befleckt Miryams rechte Wange."
  },
  AvgDialog_47173_Content_59 = {
    Text = "Miryams Augen weiten sich, während sie sich auf die Wunden konzentriert, wo der Dolch auf das Fleisch trifft, als würde sie ein Meisterwerk betrachten."
  },
  AvgDialog_47173_Content_6 = {
    Text = "Hass auf Katastrophen, Trauer über den Verlust seiner Tochter, Angst vor dem Tod und die Freude an der Pilgerfahrt... widersprüchliche Emotionen rissen an seinem gewöhnlichen Körper. Er lehnte sich auf Miryams Schulter."
  },
  AvgDialog_47173_Content_60 = {
    Text = "Über die Haut schneidend, die Adern durchbohrend, die Knochen trennend. Enos' Schreie hören nie auf, wie ein sterbendes Tier, das zerrissen wird."
  },
  AvgDialog_47173_Content_61 = {
    Text = "Blut schreit mit verzerrtem Brüllen. Blutrote Stacheln mit aufwallender Gewalt. Hervorquellend durchbohren sie Miryams Gesicht und Haut, bevor sie sich in ihre Eingeweide bohren."
  },
  AvgDialog_47173_Content_63 = {
    Text = "„Gläubiger des Herrn, öffne dein Herz und empfange den Herrn...“"
  },
  AvgDialog_47173_Content_64 = {
    Text = "Blut und Tränen waschen über Miryams verzerrtes Gesicht. Gebete murmelnd bewegt sie ihre Hände schneller und schneller."
  },
  AvgDialog_47173_Content_65 = {
    Text = "Als der Dolch innehält, sind die Siegel des Glücks und der Hoffnung bereits in Enos' Körper geritzt, inmitten seines zitternden Fleisches."
  },
  AvgDialog_47173_Content_66 = {
    Text = "„Den Frommen wird der Herr Gnade schenken...“"
  },
  AvgDialog_47173_Content_67 = {
    Text = "<Big:„Den Sehnenden wird der Herr gewähren...\">"
  },
  AvgDialog_47173_Content_68 = {
    Text = "Sie hebt das Becken mit dem heiligen Blut empor und gießt es in die siegelartigen Wunden auf Enos' Körper."
  },
  AvgDialog_47173_Content_69 = {
    Text = "In dem Moment, als das heilige Blut diese Siegel berührt, scheint es Lebenskraft zu gewinnen. Wie eine Schlange auf Enos' Körper wirbelnd, scheint sich ein Gefühl der Erregung beim Spüren der Wärme seiner Beute durch seine mäandernden Spuren auszubreiten."
  },
  AvgDialog_47173_Content_7 = {
    Text = "Als du klein warst, bist du mit mir angeln gegangen. Als du müde wurdest und wir nach Hause gingen, hast du dich einfach so an mich gelehnt."
  },
  AvgDialog_47173_Content_70 = {
    Text = "Ohne Miryams Führung zu benötigen, folgen sie der Wärmequelle und dringen durch die Wunden in Enos' Körper ein."
  },
  AvgDialog_47173_Content_71 = {
    Text = "Während das Blut hineinfließt, werden Enos' Laute unerträglich intensiv, während seine Wunden sich mit sichtbarer Geschwindigkeit schließen."
  },
  AvgDialog_47173_Content_72 = {
    Text = "Gleichzeitig beginnen seine Züge zu degenerieren; seine Augen werden riesig und quellen hervor, seine Lippen werden schleimig, und sein Kopf wird flach und länglich."
  },
  AvgDialog_47173_Content_73 = {
    Text = "Ein kiemenartiges Organ erscheint an seinem Hals. Glitschige Schuppen ersetzen sein Haar und wachsen an verschiedenen Stellen seines Körpers."
  },
  AvgDialog_47173_Content_74 = {
    Text = "Er stöhnt noch immer vor Schmerz, doch seine Laute verwandeln sich allmählich in Kreischen, erfüllt von der feuchten, stickigen Luft salzigen Wassers..."
  },
  AvgDialog_47173_Content_75 = {
    Text = "Ich habe es getan, Vater... Ich habe dich nicht enttäuscht, oder?"
  },
  AvgDialog_47173_Content_76 = {
    Text = "Das Zischen verstummt. Das halb Fisch, halb Mensch gewordene Monster starrt sie ausdruckslos an. Seine riesigen Augen quellen blass hervor, sein Verstand aufgelöst."
  },
  AvgDialog_47173_Content_77 = {
    Text = "Miryam nähert sich dem Steinaltar und streichelt das Monster. Der dichte Fischgeruch füllt ihre Nase, die Haut unter ihren Händen klebrig und glitschig."
  },
  AvgDialog_47173_Content_78 = {
    Text = "Dieser Geruch und dieses Gefühl ekelten sie einst an. Doch jetzt findet sie sie tröstlicher als je zuvor."
  },
  AvgDialog_47173_Content_79 = {
    Text = "Ich liebe wirklich Fisch. Wenn wir uns wieder im Göttlichen Reich treffen, werde ich jeden Tag den Fisch essen, den du kochst..."
  },
  AvgDialog_47173_Content_8 = {
    Text = "Wenn du aufwachst, sind wir zu Hause. Deine Mutter war damals mit deiner Schwester schwanger und war einen langen Weg gekommen, um uns abzuholen."
  },
  AvgDialog_47173_Content_80 = {
    Text = "Warte auf mich, Vater."
  },
  AvgDialog_47173_Content_81 = {
    Text = "Sie beugt sich zu der Kreatur hinunter und küsst ihre Wange. Schleimig, feucht, unverkennbar warm."
  },
  AvgDialog_47173_Content_82 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47173_Content_83 = {
    Text = "Die Tablet Tür öffnete sich langsam. Die Wachen machten instinktiv Platz."
  },
  AvgDialog_47173_Content_84 = {
    Text = "Die ruhigen, langsamen Schritte näherten sich dem Gebetsraum und hielten hinter dem Hochpriester an."
  },
  AvgDialog_47173_Content_85 = {
    Text = "Wenn du ein Meerjungmann werden und mit deinem Vater leben möchtest, kann ich dir helfen."
  },
  AvgDialog_47173_Content_86 = {
    Text = "Miryam schüttelte sanft den Kopf."
  },
  AvgDialog_47173_Content_87 = {
    Text = "Für dich sollte es viel schmerzhafter sein, mit Vernunft zu leben, als den Verstand zu verlieren."
  },
  AvgDialog_47173_Content_88 = {
    Text = "In der Tat, Hoher Priester, aber ich fürchte mich nicht vor Schmerz..."
  },
  AvgDialog_47173_Content_89 = {
    Text = "Sie kniete vor dem Oberpriester."
  },
  AvgDialog_47173_Content_9 = {
    Text = "Ich sage ihr immer, sie solle sich zu Hause ausruhen, aber sie hört nie zu... Erinnerst du dich, Miryam?"
  },
  AvgDialog_47173_Content_90 = {
    Text = "Bitte gib mir noch eine Chance... Ich werde dir beweisen, dass ich der beste Priester in Lemuria werden kann."
  },
  AvgDialog_47173_Content_91 = {
    Text = "Ich werde dir beitreten, um dem König zu helfen, das Reich Gottes nach Lemuria zu bringen!"
  },
  AvgDialog_47173_Content_92 = {
    Text = "Also, würdest du deinen Vater für den König töten?"
  },
  AvgDialog_47173_Content_93 = {
    Text = "Ja, Eure Heiligkeit. Ich bin bereit. Für den König werde ich alles tun."
  },
  AvgDialog_47173_Content_94 = {
    Text = "Dies ist der einzige Weg, um mein Zuhause und meinen Vater zu retten."
  },
  AvgDialog_47173_Content_95 = {
    Text = "Der König ist mein Vater, der König ist mein Zuhause... In Lemuria ist dies die einzige Wahrheit."
  },
  AvgDialog_47173_Content_96 = {
    Text = "Die eine Hälfte von Miryams Gesicht ist mit dem Blut ihres Vaters besudelt, wie eine lebendige Maske."
  },
  AvgDialog_47173_Content_97 = {
    Text = "Die Hohe Priesterin starrte sie an, ihre scharfen Augen wurden für einen Moment schließlich sanft."
  },
  AvgDialog_47173_Content_98 = {
    Text = "Er zeigte neben sich. Auf dem Tisch waren bereits ein Weinglas und ein Satz Kleidung vorbereitet."
  },
  AvgDialog_47173_Content_99 = {
    Text = "Trink das Blut der Schlange, chant das Gebet und bete zum König."
  },
  AvgDialog_47174_Content_1 = {
    Text = "Priester's Ritus"
  },
  AvgDialog_47174_Content_10 = {
    Text = "Jede Kirche an jedem Ort erzählt ihre Geschichte. Man sagt, dass sie, als sie noch Priesterin in der Ausbildung war, während ihres ersten Gebets den Schatten des Königs sah."
  },
  AvgDialog_47174_Content_11 = {
    Text = "Nach dem Trinken von Schlangenblut sind andere Priester mindestens eine Woche lang bettlägerig, aber sie ist völlig in Ordnung"
  },
  AvgDialog_47174_Content_12 = {
    Text = "So jung, und doch schon so nah am König, so viel für Lemuria tun. Wirklich beneidenswert."
  },
  AvgDialog_47174_Content_13 = {
    Text = "Ich wäre bereit, alles zu opfern für die Chance, den Platz mit ihr zu tauschen..."
  },
  AvgDialog_47174_Content_14 = {
    Text = "Ah! Schau, schau, der stellvertretende Hohepriester kommt heraus!"
  },
  AvgDialog_47174_Content_15 = {
    Text = "Die Kerzenflammen flackern im Wind. Eine Gruppe von Wachen tritt heraus und reiht sich auf beiden Seiten des Opferaltars auf."
  },
  AvgDialog_47174_Content_16 = {
    Text = "Im Traum des Thrones hört der König Gottes Offenbarung:"
  },
  AvgDialog_47174_Content_17 = {
    Text = "Lemurias Stürme werden sich legen. Lemurias Abgrund wird verschwinden."
  },
  AvgDialog_47174_Content_18 = {
    Text = "Der König wird seine tugendhaften Untertanen beschützen und das Königreich Gottes einläuten."
  },
  AvgDialog_47174_Content_19 = {
    Text = "Sei gepriesen, mein Herr."
  },
  AvgDialog_47174_Content_2 = {
    Text = "Schau dir das Wetter an, es wird gleich wieder gießen... Das Wetter wird wirklich immer schlimmer."
  },
  AvgDialog_47174_Content_20 = {
    Text = "Gelobt sei mein Herr!"
  },
  AvgDialog_47174_Content_21 = {
    Text = "Der Klang scheint von weit her zu kommen, sanft und doch kristallklar."
  },
  AvgDialog_47174_Content_22 = {
    Text = "Unter den Blicken der Priesterlehrlinge tauchte eine lila Gestalt langsam aus dem Tempel auf."
  },
  AvgDialog_47174_Content_23 = {
    Text = "Sie stand am Altar, ihre Augen scannen ruhig die Menge durch einen blasslila Schleier. Zwei Fäden schwarzer Nebel, die ungebildeten Schlangen ähneln, wanden sich hinter ihr."
  },
  AvgDialog_47174_Content_24 = {
    Text = "Unter diesem ruhigen Blick schien eine kraftvolle Energie zu liegen, die das Atmen aller verlangsamt."
  },
  AvgDialog_47174_Content_25 = {
    Text = "Der Hohe Priester ist in letzter Zeit unwohl. Ich werde das Ritual der Murloc-Transformation lehren."
  },
  AvgDialog_47174_Content_26 = {
    Text = "Bring den Pionier."
  },
  AvgDialog_47174_Content_27 = {
    Text = "Unter der Eskorte von Wachen wurden ein Vater und eine Tochter in den Raum gebracht."
  },
  AvgDialog_47174_Content_28 = {
    Text = "Ein feuchter Kerzenständer, kaltes Kerzenlicht. Alles scheint wie vor drei Jahren zu sein."
  },
  AvgDialog_47174_Content_29 = {
    Text = "Der benommene Vater wurde auf den Steintisch gelegt, während seine jugendliche Tochter, von den Wachen gehalten, sich wand und schrie."
  },
  AvgDialog_47174_Content_3 = {
    Text = "In den letzten Jahren sind Naturkatastrophen viel häufiger geworden. Besonders die im Südertal vor drei Jahren, die viele Leben forderte..."
  },
  AvgDialog_47174_Content_30 = {
    Text = "Priester! Bitte, bitte hab Erbarmen..."
  },
  AvgDialog_47174_Content_31 = {
    Text = "Mein Vater hat nur ein wenig gestohlen... Meine Mutter starb an der Pest, und weil mein Vater kein Geld hatte, griff er zum Stehlen..."
  },
  AvgDialog_47174_Content_32 = {
    Text = "Ich werde alles tun, bitte verschone meinen Vater..."
  },
  AvgDialog_47174_Content_33 = {
    Text = "Bereit, alles zu tun... Würdest du dann deinen Vater für den König töten?"
  },
  AvgDialog_47174_Content_34 = {
    Text = "...Priester?"
  },
  AvgDialog_47174_Content_35 = {
    Text = "Der verwirrte Ausdruck des Mädchens kam Miryam bekannt vor. Jeder durchläuft diese Phase, aber niemand versteht sie besser als Miryam."
  },
  AvgDialog_47174_Content_36 = {
    Text = "Sie trat vor und tätschelte das Mädchen sanft auf den Kopf."
  },
  AvgDialog_47174_Content_37 = {
    Text = "Fürchtet euch nicht, Anhänger des Herrn."
  },
  AvgDialog_47174_Content_38 = {
    Text = "Komm, hier drüben."
  },
  AvgDialog_47174_Content_39 = {
    Text = "Sie hielt die Hand des Mädchens und leitete sie an, die Wange ihres eigenen Vaters zu berühren."
  },
  AvgDialog_47174_Content_4 = {
    Text = "In der Tat... aber seit die neue stellvertretende Priesterin ihr Amt angetreten hat, hat sie einiges erreicht. Die Renovierung der Häuser der Anhänger, die großangelegte Auswahl von Priestern und die ritualisierten Zeremonien wurden alle von ihr organisiert."
  },
  AvgDialog_47174_Content_40 = {
    Text = "Sag mir, du und dein Vater, sehnt ihr euch nach dem göttlichen Reich?"
  },
  AvgDialog_47174_Content_41 = {
    Text = "Wir... wir sehnen uns nach dem Göttlichen Reich..."
  },
  AvgDialog_47174_Content_42 = {
    Text = "Ja, Lemurianer sollten sich nach dem Göttlichen Reich sehnen."
  },
  AvgDialog_47174_Content_43 = {
    Text = "Es gibt alles, was du dir wünschst. Keine Katastrophen, keine Krankheiten... Das Göttliche Reich ist das Einzige, was wir verfolgen sollten."
  },
  AvgDialog_47174_Content_44 = {
    Text = "Sie legte das opfernde Messer in die zitternden Hände des Mädchens. Miryam hielt sie sanft."
  },
  AvgDialog_47174_Content_45 = {
    Text = "Du bist keine Verbrecher. Ihr liebt euch tief, diese Liebe ist lobenswert und sollte nicht als Verbrechen betrachtet werden."
  },
  AvgDialog_47174_Content_46 = {
    Text = "Darum bist du qualifiziert, hier zu sein, qualifiziert, deine eigene Kraft für das Kommen des Reichs des Gottes einzubringen."
  },
  AvgDialog_47174_Content_47 = {
    Text = "Nein... Priester, da es keine Sünde ist, bitte bestraft uns nicht... Bitte, wir flehen dich an, bitte tu es nicht..."
  },
  AvgDialog_47174_Content_48 = {
    Text = "Strafe? Nein, Anhänger meines Herrn, das ist keine Strafe. Das ist das Geschenk des Königs an euch—"
  },
  AvgDialog_47174_Content_49 = {Text = "Zack—"},
  AvgDialog_47174_Content_5 = {
    Text = "Es gab auch öffentliche Murloc-Transformationszeremonien wie die heutige, die zuvor noch nie gesehen worden waren."
  },
  AvgDialog_47174_Content_50 = {Text = "ARGH!!"},
  AvgDialog_47174_Content_51 = {
    Text = "Miryam drückte die Hand des Mädchens gewaltsam nach unten. Die Klinge des rituellen Dolches versank vollständig in der Brust des Mannes."
  },
  AvgDialog_47174_Content_52 = {
    Text = "Blut spritzte und bespritzte das Gesicht des Mädchens. Die verzweifelten Schreie des Vaters und die schrillen Schreie der Tochter hallten durch den Raum."
  },
  AvgDialog_47174_Content_53 = {
    Text = "Sei unbesorgt, treuer Anhänger. Sobald das Ritual deines Vaters abgeschlossen ist, wird es deine Wendung sein."
  },
  AvgDialog_47174_Content_54 = {
    Text = "Sie können immer noch mit Ihrem Vater leben. Ich werde die Kosten für diese Klarheit für Sie tragen."
  },
  AvgDialog_47174_Content_55 = {
    Text = "Als sie sprach, leitete sie den Dolch über den Körper des Mannes. Im Laufe der Jahre hatte sie dieses Ritual unzählige Male durchgeführt."
  },
  AvgDialog_47174_Content_56 = {
    Text = "Ein tiefes Gefühl des Glücks umhüllt sie. Das verspritzte Blut und die verdrehten Gesichter sind die Schritte, die zum Reich Gottes führen. Die Lemurier sollten es gerne annehmen."
  },
  AvgDialog_47174_Content_57 = {
    Text = "Wie ich, glaube an den König. Wie ich, warte geduldig. Bald werden du und deine Familie im Göttlichen Reich wiedervereint sein."
  },
  AvgDialog_47174_Content_58 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47174_Content_59 = {Text = "Plopp—"},
  AvgDialog_47174_Content_6 = {
    Text = "Ich habe gehört, dass der stellvertretende Hochpriester aus dem South Valley stammt?"
  },
  AvgDialog_47174_Content_60 = {
    Text = "Für die Priesterlehrlinge mag das Ritual lang erschienen sein, aber für Miryam endete es schnell."
  },
  AvgDialog_47174_Content_61 = {
    Text = "Zwei halb menschliche, halb fischartige Monster wurden in den Pool geworfen. Miryam stand am Rande des Pools, bückte sich und streichelte sanft ihre glitschige Haut."
  },
  AvgDialog_47174_Content_62 = {
    Text = "Der beißende Gestank füllte ihre Lungen, und das schmutzige Poolwasser durchnässte ihr Kleid, aber das kümmerte sie nicht."
  },
  AvgDialog_47174_Content_63 = {
    Text = "Diese Murlocs haben drastischere Veränderungen durchgemacht als zuvor. Deine Fähigkeiten sind immer raffinierter geworden, stellvertretender Hochpriester."
  },
  AvgDialog_47174_Content_64 = {
    Text = "Deborah, ich habe dir schon oft gesagt, dass du mich nicht den stellvertretenden Hochpriester nennen sollst."
  },
  AvgDialog_47174_Content_65 = {
    Text = "Sie drehte sich um und lächelte ihrem einzigen Freund warm zu."
  },
  AvgDialog_47174_Content_66 = {
    Text = "Die Zeit vergeht. Ich erinnere mich noch, wie ängstlich du vor diesen Pionieren warst. Jetzt schau dich an, ein großer Wurf in Lemuria~"
  },
  AvgDialog_47174_Content_67 = {
    Text = "Der alte Hohe Priester ist nicht in guter Gesundheit. Wenn der neue König aufsteigt, könntest du unser Hoher Priester werden!"
  },
  AvgDialog_47174_Content_68 = {
    Text = "Es ist alles das Gleiche, Deborah. Der Lehrer wird uns führen, alles dem König zu widmen. Bald wird das Reich Gottes ankommen."
  },
  AvgDialog_47174_Content_69 = {
    Text = "Die Zeit für die Krönung des neuen Königs rückt näher. Wir müssen sorgfältig vorbereiten. Ich werde in den Gebetsraum gehen..."
  },
  AvgDialog_47174_Content_7 = {
    Text = "Ja! Vor drei Jahren warst du ein Priester-Azubi, und in weniger als einem Jahr wurdest du Lemurias jüngster stellvertretender Hauptpriester..."
  },
  AvgDialog_47174_Content_70 = {Text = "Miryam..."},
  AvgDialog_47174_Content_71 = {
    Text = "Sie zeigte auf Miryams Körper. Miryam schaute nach unten und bemerkte, dass sie mit Blut bedeckt war."
  },
  AvgDialog_47174_Content_72 = {
    Text = "Ah, tut mir leid... Ich habe gerade das Ritual beendet und völlig vergessen..."
  },
  AvgDialog_47174_Content_73 = {
    Text = "Miryam, geht es dir gut?"
  },
  AvgDialog_47174_Content_74 = {
    Text = "Ich? Mir geht's gut... Warum fragst du?"
  },
  AvgDialog_47174_Content_75 = {
    Text = "Ich weiß auch nicht. Seit diesem Vorfall fühlt es sich an, als wärst du eine ganz andere Person geworden..."
  },
  AvgDialog_47174_Content_76 = {
    Text = "Ich habe mich nicht verändert, sondern bin nur erwachsen geworden. Die Menschen müssen immer wachsen."
  },
  AvgDialog_47174_Content_77 = {
    Text = "Deborah, erinnerst du dich an unseren Wunsch? Du hast mir einmal gesagt, dass wir zusammen Priester werden, dem König helfen und das Göttliche Reich nach Lemuria bringen würden."
  },
  AvgDialog_47174_Content_78 = {
    Text = "Natürlich erinnere ich mich. Damals warst du nur ein Lehrling, der nicht einmal richtig beten konnte~"
  },
  AvgDialog_47174_Content_79 = {
    Text = "Sieh, ich habe alle früheren Versprechen erfüllt. Du solltest für mich glücklich sein, oder?"
  },
  AvgDialog_47174_Content_8 = {
    Text = "Die Gesundheit des Hohen Priesters verschlechtert sich, und die meisten Aufgaben wurden ihr anvertraut. Vielleicht wird sie bald die jüngste Hohe Priesterin in Lemuria werden."
  },
  AvgDialog_47174_Content_80 = {
    Text = "Ich freue mich jeden Tag aufrichtig für dich! Aber manchmal, wenn ich dich anschaue, habe ich das Gefühl, du scheinst sehr müde zu sein. Ich mache mir ein wenig Sorgen..."
  },
  AvgDialog_47174_Content_81 = {
    Text = "Mach dir keine Sorgen, Deborah. Mir geht's gut. Ich habe mich in all diesen Jahren nie so gut gefühlt."
  },
  AvgDialog_47174_Content_82 = {
    Text = "Sie klopfte Deborah auf die Schulter, lächelte sie an und ging in ihre Quartiere."
  },
  AvgDialog_47174_Content_83 = {
    Text = "Die Krönungszeremonie des neuen Königs erfordert umfangreiche Vorbereitungen. Eine geschäftige Zeit liegt vor uns."
  },
  AvgDialog_47174_Content_84 = {
    Text = "Auf dem Weg betrachtete sie die Kammer des neuen Königs, in die sie kein Recht hatte, einzutreten."
  },
  AvgDialog_47174_Content_85 = {
    Text = "Die Menschen von Lemuria haben alle eine Version der Legende des neuen Königs gehört."
  },
  AvgDialog_47174_Content_86 = {
    Text = "Der Aufstieg des neuen Königs bringt Lemuria näher zum Reich Gottes. Sie lächelte und gab dem Wächter beiläufig den Seidenstoff, der dazu benutzt wurde, das Blut abzuwischen."
  },
  AvgDialog_47174_Content_9 = {
    Text = "Sie ist erst zwanzig, wirklich bemerkenswert..."
  },
  AvgDialog_47175_Content_1 = {
    Text = "Neuer König"
  },
  AvgDialog_47175_Content_10 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47175_Content_11 = {
    Text = "Draußen vor dem Lemuria Tempel."
  },
  AvgDialog_47175_Content_12 = {
    Text = "Eure Majestät! Mein Herr!"
  },
  AvgDialog_47175_Content_13 = {
    Text = "Lobet unseren Herrn! Willkommen im Göttlichen Reich!"
  },
  AvgDialog_47175_Content_14 = {
    Text = "Der große Tempel von Lemuria steht hoch und majestätisch, wie ein Berg an der weiten Küste."
  },
  AvgDialog_47175_Content_15 = {
    Text = "Die Anhänger strömten zusammen und füllten den Platz vor dem Tempel, während sie auf den großen Altar starrten, der in schwachem Licht leuchtete."
  },
  AvgDialog_47175_Content_16 = {
    Text = "Menschen standen auf den Zehenspitzen und schauten über das Menschenmeer und die Gruppen von Wachen hinweg, um einen Blick auf den neuen König im Altar zu erhaschen."
  },
  AvgDialog_47175_Content_17 = {
    Text = "Hinter dem Altar öffnet sich das große Tafelportal des Tempels selten vor den Gläubigen. Der Wind, der den tiefen und geheimnisvollen Duft von Aequor trägt, weht vom Tempel herüber und lässt den halbtransparenten Vorhang leicht flattern."
  },
  AvgDialog_47175_Content_18 = {
    Text = "Miryam standete vorne in den priesterlichen Reihen vor dem Altar, die Hände fest verschränkt, und starrte reglos auf die Rückseite des Vorhangs."
  },
  AvgDialog_47175_Content_19 = {
    Text = "Eine vage Gestalt lehnt gegen den Thron hinter dem Vorhang, scheinbar schlafend. Die einzigartige Krone, die den König symbolisiert, lässt Miryams Atmung unwillkürlich schneller werden."
  },
  AvgDialog_47175_Content_2 = {
    Text = "Thud... Thud..."
  },
  AvgDialog_47175_Content_20 = {Text = "Boom—"},
  AvgDialog_47175_Content_21 = {Text = "Ah!—"},
  AvgDialog_47175_Content_22 = {
    Text = "Der plötzliche Donner ließ die Anhänger innehalten. Angst vor der Katastrophe floss durch ihre Adern und sie schauten panisch auf."
  },
  AvgDialog_47175_Content_23 = {
    Text = "Der Himmel, einst von Wolken verhüllt, wurde immer dunkler. Blitze zuckten, Donner grollte, und der Ozean brauste mit Wellen, die Unheil und Tod symbolisierten."
  },
  AvgDialog_47175_Content_24 = {
    Text = "Calamität... Es ist eine Calamität! Die Calamität naht!"
  },
  AvgDialog_47175_Content_25 = {
    Text = "Wenn der Tempel eine Katastrophe erleidet, dann..."
  },
  AvgDialog_47175_Content_26 = {
    Text = "Wie kann das jetzt sein... am Tag der Thronbesteigung des neuen Königs..."
  },
  AvgDialog_47175_Content_27 = {
    Text = "Könnte es... dieser neue König sein..."
  },
  AvgDialog_47175_Content_28 = {
    Text = "Unter unheilvollen Zeichen wurden die Gläubigen, die sich um den Tempel versammelt hatten, unruhig. Unruhe breitete sich durch die Menge aus."
  },
  AvgDialog_47175_Content_29 = {
    Text = "Hinter dem Vorhang war ein leises Seufzen zu hören. Eine winzige Gestalt erhob sich vom Thron."
  },
  AvgDialog_47175_Content_3 = {
    Text = "Tiefe, resonante Glocken, wie ein göttliches Dekret, läuteten aus dem Tempel von Lemuria."
  },
  AvgDialog_47175_Content_30 = {
    Text = "Keine Katastrophe wird eintreffen."
  },
  AvgDialog_47175_Content_31 = {
    Text = "In einem Traum hörte ich das Orakel:"
  },
  AvgDialog_47175_Content_32 = {
    Text = "Heute wird Lemuria einen neuen König willkommen heißen."
  },
  AvgDialog_47175_Content_33 = {
    Text = "Von diesem Tag an werden alle Naturkatastrophen vor mir zurückweichen."
  },
  AvgDialog_47175_Content_34 = {
    Text = "Diese jugendliche Stimme war ruhig, doch sie hallte klar in jedermanns Ohren wie ein Glockenläuten."
  },
  AvgDialog_47175_Content_35 = {
    Text = "Ist das... der neue König? Es ist die Stimme des neuen Königs!"
  },
  AvgDialog_47175_Content_36 = {
    Text = "Sieh! Sieh dir den Himmel an!"
  },
  AvgDialog_47175_Content_37 = {
    Text = "Fast sofort nachdem Tulu gesprochen hatte, begannen die Wolken am Himmel sich sichtbar aufzulösen."
  },
  AvgDialog_47175_Content_38 = {
    Text = "Das Grollen des Ozeans begann nachzulassen, und das helle Sonnenlicht strahlte herab und erleuchtete die Gesichter aller Gläubigen."
  },
  AvgDialog_47175_Content_39 = {
    Text = "Wunder... Das ist ein Wunder!"
  },
  AvgDialog_47175_Content_4 = {
    Text = "Die Glocke schlägt in Richtung Küste, in Richtung Berge, in Richtung Städte und Dörfer."
  },
  AvgDialog_47175_Content_40 = {
    Text = "Auf dem Vorhang hinter dem Altar zeichnet das Sonnenlicht eine klare Silhouette."
  },
  AvgDialog_47175_Content_41 = {
    Text = "Ein junger Körper erreicht den Rand des Vorhangs und hebt sanft einen Arm."
  },
  AvgDialog_47175_Content_42 = {Text = "Boom..."},
  AvgDialog_47175_Content_43 = {
    Text = "Mit seinen Bewegungen durchbohrten mehrere riesige Tentakel den Ozean, die Ebenen und die Berge und erschienen vor allen."
  },
  AvgDialog_47175_Content_44 = {
    Text = "Ohnmacht-Licht strahlt von den Tentakeln aus. Das Licht verbindet sich allmählich und webt zu einem grandiosen Gemälde vor all den Gläubigen."
  },
  AvgDialog_47175_Content_45 = {
    Text = "Das... das ist..."
  },
  AvgDialog_47175_Content_46 = {
    Text = "Miryams Augen weiteten sich, als sie alles vor sich betrachtete."
  },
  AvgDialog_47175_Content_47 = {
    Text = "Ihre Welt änderte sich. Die Berge waren nicht mehr in Trümmern, das Meer nicht mehr stürmisch. Sie sah, wie das Sonnenlicht auf ein ruhiges und friedliches Land fiel."
  },
  AvgDialog_47175_Content_48 = {Text = "Schwester!"},
  AvgDialog_47175_Content_49 = {
    Text = "Die Stimme erreichte Miryams Ohren. Sie blickte scharf auf und sah die vertraute Gestalt vor sich."
  },
  AvgDialog_47175_Content_5 = {
    Text = "Lemurias neuer König... Der neue König steht kurz vor der Thronbesteigung!!"
  },
  AvgDialog_47175_Content_50 = {
    Text = "Sa...Sarah? Wie konnte das sein..."
  },
  AvgDialog_47175_Content_51 = {
    Text = "Schwester, es ist so lange her. Wie hast du dich überhaupt nicht verändert? Sieh mich an, ich bin gewachsen!"
  },
  AvgDialog_47175_Content_52 = {
    Text = "Miryam...geht es dir gut im Tempel?"
  },
  AvgDialog_47175_Content_53 = {
    Text = "Es ist so lange her, dass ich dich das letzte Mal gesehen habe... Mama vermisst dich."
  },
  AvgDialog_47175_Content_54 = {
    Text = "Mutter... Mutter... Du..."
  },
  AvgDialog_47175_Content_55 = {
    Text = "Miryam starrte leer auf die zwei näherkommenden Gestalten. Schritte hallten hinter ihr wider. Langsam drehte sie sich um."
  },
  AvgDialog_47175_Content_56 = {
    Text = "Ah, mein Priester ist zurückgekehrt!"
  },
  AvgDialog_47175_Content_57 = {Text = "Vater..."},
  AvgDialog_47175_Content_58 = {
    Text = "Tränen verschwommen ihre Sicht. Ihre Kehle war heiser, und sie konnte nicht sprechen."
  },
  AvgDialog_47175_Content_59 = {
    Text = "Eine Hand ruht auf ihrem Kopf und streichelt sanft."
  },
  AvgDialog_47175_Content_6 = {
    Text = "Die Schreie und das Läuten der Glocken hallten durch die Ohren jedes Bürgers in diesem gewaltigen Königreich."
  },
  AvgDialog_47175_Content_60 = {
    Text = "Sei nicht traurig, Miryam. Du hast es geschafft... Du hast dem König geholfen, das Reich Gottes zu bringen!"
  },
  AvgDialog_47175_Content_61 = {
    Text = "Jetzt haben wir nichts zu fürchten. Unsere Familie wird glücklich zusammen im Reich der Götter leben. Für immer und ewig..."
  },
  AvgDialog_47175_Content_62 = {
    Text = "Ich... Ich habe es getan? Ich habe es getan..."
  },
  AvgDialog_47175_Content_63 = {
    Text = "Die Schwester rannte zu ihrer Seite und umarmte sie. Die Mutter kam zu ihrer Seite und umarmte sie. Der Vater kam zu ihrer Seite und umarmte sie."
  },
  AvgDialog_47175_Content_64 = {
    Text = "Umarmung. Eine Berührung der Körper. Eine warme Umarmung. Eine Umarmung zur Wiedervereinigung, nicht zum Abschied. Eine Umarmung, bei der niemand fehlt."
  },
  AvgDialog_47175_Content_65 = {
    Text = "Umarmung, das ist alles, wonach sie suchte."
  },
  AvgDialog_47175_Content_66 = {
    Text = "Tränen quollen hervor und fielen von Miryams Gesicht, als sie ihren Kopf hob."
  },
  AvgDialog_47175_Content_67 = {
    Text = "Die Umarmung verschwand. Das Licht wechselte, und sie kehrte zum Tempel zurück. Vor ihr standen unzählige Gläubige, die Tränen vergossen."
  },
  AvgDialog_47175_Content_68 = {
    Text = "Der Glanz des Göttlichen Reichs, das tiefste Verlangen in jedem Herzen, entfaltet sich lebhaft vor den Gläubigen."
  },
  AvgDialog_47175_Content_69 = {
    Text = "Ich sah es... Ich sah es, mein Herr!"
  },
  AvgDialog_47175_Content_7 = {
    Text = "Millionen von Lemuriern strömten in die Straßen und Plätze, riefen und erwarteten begeistert."
  },
  AvgDialog_47175_Content_70 = {
    Text = "Dies ist das Göttliche Reich... Dies ist das Göttliche Reich, das du uns versprochen hast!"
  },
  AvgDialog_47175_Content_71 = {
    Text = "Mein Herr... Ich habe es gesehen!"
  },
  AvgDialog_47175_Content_72 = {
    Text = "Miryam murmelte diese wiederholten Worte, kniete vor dem neuen König hinter dem Vorhang."
  },
  AvgDialog_47175_Content_73 = {
    Text = "Keine Organisation war nötig; unzählige Anhänger knieten und zollten ihr Respekt hinter ihr."
  },
  AvgDialog_47175_Content_74 = {
    Text = "Durch tränenverschleierte Augen beobachteten unzählige Augen ungeduldig den Altar und starrten auf die kleine Silhouette des neuen Königs hinter dem Vorhang"
  },
  AvgDialog_47175_Content_75 = {
    Text = "Dies ist die Pracht des Göttlichen Reiches. Dies ist die Majestät meines Herrn."
  },
  AvgDialog_47175_Content_76 = {
    Text = "Ich bin alt. Auf Befehl meines Herrn wird Miryam der Hohe Priester nachfolgen und den neuen König von Lemuria unterstützen."
  },
  AvgDialog_47175_Content_77 = {Text = "Mein Herr."},
  AvgDialog_47175_Content_78 = {
    Text = "Der Hohe Priester trat zur Seite und senkte seine Stimme."
  },
  AvgDialog_47175_Content_79 = {
    Text = "Mein Herr, Lemuria hat Zeuge deiner Majestät gegeben. Bitte, fahre fort. Bring Hoffnung nach Lemuria."
  },
  AvgDialog_47175_Content_8 = {
    Text = "Der alte König könnte abgedankt oder verstorben sein. Die Lemurier wissen es nicht und interessiert es nicht."
  },
  AvgDialog_47175_Content_80 = {
    Text = "Er machte eine einladende Geste und verbeugte sich vor Tulu."
  },
  AvgDialog_47175_Content_81 = {
    Text = "Der junge neue König schwieg einen Moment, dann machte er einen Schritt nach vorne."
  },
  AvgDialog_47175_Content_82 = {
    Text = "Ich, der Agent der Götter, der König von Lemuria."
  },
  AvgDialog_47175_Content_83 = {
    Text = "Ich... werde das Göttliche Reich nach Lemuria bringen."
  },
  AvgDialog_47175_Content_84 = {
    Text = "Götter... Mögen die Götter Lemuria beschützen!"
  },
  AvgDialog_47175_Content_85 = {
    Text = "Mein Herr! Allen Lob meinem Herrn!"
  },
  AvgDialog_47175_Content_86 = {
    Text = "Lobe unseren Herrn!!"
  },
  AvgDialog_47175_Content_87 = {
    Text = "Zehntausende von Gläubigen knien auf dem Boden, und die Jubel, wie Berge und Meere, hallen durch jede Ecke des Königreichs."
  },
  AvgDialog_47175_Content_88 = {
    Text = "Tulu drehte sich müde um."
  },
  AvgDialog_47175_Content_89 = {
    Text = "Lemuria wartet auf meine Worte, und ich habe gesprochen."
  },
  AvgDialog_47175_Content_9 = {
    Text = "Während ihres langen Kampfes gegen das Unheil lernten sie, die Trauer über das Gestern abzulegen. Ihre Augen sehen jetzt nur noch das strahlende Morgen, das von dem neuen König gebracht wird, leuchtend mit dem Ruhm von Gottes Reich."
  },
  AvgDialog_47175_Content_90 = {
    Text = "Ich bin erschöpft. Es gibt keinen Grund zu folgen."
  },
  AvgDialog_47175_Content_91 = {
    Text = "Er winkte mit seiner Hand, um die Wächter und den Hochpriester am Folgen zu hindern."
  },
  AvgDialog_47175_Content_92 = {
    Text = "Mitten in den fanatischen Schreien der Anhänger betritt der junge neue König schweigend allein den leeren Tempel."
  },
  AvgDialog_47176_Content_1 = {
    Text = "Prophezeiung"
  },
  AvgDialog_47176_Content_10 = {
    Text = "Das Haus ist fast vollständig zusammengebrochen und hat sie in dieser engen Ecke mit Trümmern gefangen. Der Regen strömte durch die Lücken zwischen den Steinen und durchnässte sie."
  },
  AvgDialog_47176_Content_100 = {
    Text = "\"Aber, aber mein Vater ist ein gläubiger Mensch. Der König kümmert sich um sein Volk und wird mir nicht erlauben...\""
  },
  AvgDialog_47176_Content_101 = {
    Text = "\"Du solltest kein Priester sein. Du solltest nicht in Lemuria geboren worden sein. Du solltest exiliert oder hingerichtet werden.\""
  },
  AvgDialog_47176_Content_102 = {
    Text = "\"Miryam, der Hohepriester meinte das nicht...\""
  },
  AvgDialog_47176_Content_103 = {
    Text = "\"Hochpriester! Bitte vergib Miryam, sie hat nur Schwierigkeiten, sich auszudrücken... Wir sind bereit, alles für den König zu geben!\""
  },
  AvgDialog_47176_Content_104 = {
    Text = "\"Die Götter führten mich hierher. Das muss das Schicksal sein, das durch die Sterne vorhergesagt wurde... Schicksal, huh.\""
  },
  AvgDialog_47176_Content_105 = {
    Text = "Der Hohe Priester ignorierte Enos und Miryam, seufzte tief und ging zurück in die Tiefen des Tempels."
  },
  AvgDialog_47176_Content_106 = {
    Text = "Bald hastete ein Priester herbei, dessen Schritte in der stillen Halle widerhallten."
  },
  AvgDialog_47176_Content_107 = {
    Text = "Sie hielt vor Miryam an, lächelte und übergab ihr ein Abzeichen."
  },
  AvgDialog_47176_Content_108 = {
    Text = "Bring es in sieben Tagen zum Tempel und nimm am Training teil"
  },
  AvgDialog_47176_Content_109 = {
    Text = "\"Herzlichen Glückwunsch, Miryam. Sie sind jetzt ein Priesterlehrling von Lemuria.\""
  },
  AvgDialog_47176_Content_11 = {
    Text = "Mehrere massive Felsblöcke hängen über ihrem Kopf, nur durch eine rissige, schlanke Säule kaum gestützt, die im Regensturm zittert."
  },
  AvgDialog_47176_Content_110 = {Text = "„!!!\""},
  AvgDialog_47176_Content_111 = {
    Text = "\"Die Schwester wurde gewählt! Die Schwester wurde gewählt!\""
  },
  AvgDialog_47176_Content_112 = {
    Text = "Sarah sprang aufgeregt auf, während Enos leicht zitternd in Richtung der Statue trat, seine Hände fest vor ihm verschränkt."
  },
  AvgDialog_47176_Content_113 = {
    Text = "\"Danke, lieber Priester, danke!\""
  },
  AvgDialog_47176_Content_114 = {
    Text = "\"Unser Herr hat unsere Stimmen gehört... Danke, Herr... Danke...\""
  },
  AvgDialog_47176_Content_115 = {
    Text = "\"Paya, hast du gehört? Unser Kind ist ein Priesterlehrling geworden!\""
  },
  AvgDialog_47176_Content_116 = {
    Text = "\"Wenn du das nur sehen könntest, würdest du so glücklich sein, Paya...\""
  },
  AvgDialog_47176_Content_117 = {
    Text = "Miryam stand wie versteinert da und verstand nicht, was passiert war."
  },
  AvgDialog_47176_Content_118 = {
    Text = "Die Schwester jubelte wild, der Vater wischte heimlich Tränen weg, und die umstehenden Leute sprachen aufrichtig oder neidisch ihre Glückwünsche aus."
  },
  AvgDialog_47176_Content_119 = {
    Text = "Ein dunkles Emblem, eingraviert mit Tentakeln und Stürmen, liegt ruhig in ihrer Handfläche, gleichgültig gegenüber allen Anblicken und Geräuschen um sich herum, wie eine abgetrennte Prophezeiung."
  },
  AvgDialog_47176_Content_12 = {
    Text = "\"Eure Majestät... Ihre geliebte Majestät...\""
  },
  AvgDialog_47176_Content_120 = {
    Text = "\"Du magst Fisch. Wenn wir zurückkommen, werde ich ein Festmahl mit deinen Lieblingsgerichten für dich vorbereiten!\""
  },
  AvgDialog_47176_Content_121 = {
    Text = "\"Ich muss alle informieren und die gute Nachricht teilen!\""
  },
  AvgDialog_47176_Content_122 = {
    Text = "\"<Meine Miryam wird Priesterin von Lemuria werden!\""
  },
  AvgDialog_47176_Content_123 = {
    Text = "\"Immer noch nur eine Auszubildende...\""
  },
  AvgDialog_47176_Content_124 = {
    Text = "„Der Hohepriester hat dir besondere Aufmerksamkeit geschenkt, was zeigt, dass Miryams Geschenk wirklich außergewöhnlich ist! Es wird definitiv keine Probleme geben!“"
  },
  AvgDialog_47176_Content_125 = {
    Text = "Miryam verstand nicht, was der Hohe Priester meinte oder warum sie ausgewählt worden war. Sie sah ihren Vater und ihre Schwester an und bemerkte zum ersten Mal seit langem Glück auf ihren Gesichtern."
  },
  AvgDialog_47176_Content_126 = {
    Text = "Miryam berührte das Abzeichen und ein Lächeln erschien auf ihrem Gesicht."
  },
  AvgDialog_47176_Content_127 = {
    Text = "Schließlich brachte sie, genau wie ihr Vater, ihrer Familie Lächeln. Lass dieses Lächeln weiterbestehen, dachte sie."
  },
  AvgDialog_47176_Content_13 = {
    Text = "\"Bitte... rette deinen treuen Gläubigen...\""
  },
  AvgDialog_47176_Content_14 = {
    Text = "Sie blickte auf die wackeligen Felsen oben und schrumpfte in die Ecke, ihre Finger in einem Gebet gegen ihre Brust gefaltet."
  },
  AvgDialog_47176_Content_15 = {
    Text = "Regensturm. Donnerschlag. Erdbeben. Tsunami."
  },
  AvgDialog_47176_Content_16 = {
    Text = "Die Menschen von Lemuria schlafen inmitten von Katastrophen; das Gebet war das erste, was sie lernten."
  },
  AvgDialog_47176_Content_17 = {
    Text = "\"Du bist der Vollstrecker der Götter, der Glaube des Volkes von Lemuria... Ich werde dir alles anbieten...\""
  },
  AvgDialog_47176_Content_18 = {
    Text = "\"Bitte hilf mir... Rettet mich...\""
  },
  AvgDialog_47176_Content_19 = {
    Text = "Vater sagte, dass die Götter und der König das Volk von Lemuria retten würden. Sie wusste nicht, was Götter oder ein König waren. Sie rief immer wieder."
  },
  AvgDialog_47176_Content_2 = {
    Text = "\"In der Illusion des Thrones hört der König die Offenbarungen der Götter:\""
  },
  AvgDialog_47176_Content_20 = {
    Text = "Die Götter sind immer noch nicht erschienen; sie sind ihr nie erschienen. Aber außer zu beten, kann sie nichts tun."
  },
  AvgDialog_47176_Content_21 = {
    Text = "Die Risse in der Steinsäule werden deutlicher. Sie kann das Gewicht der darüber liegenden Trümmer nicht mehr tragen."
  },
  AvgDialog_47176_Content_22 = {
    Text = "\"Mein Herr... bitte rette mich...\""
  },
  AvgDialog_47176_Content_23 = {
    Text = "Miryam dachte an den schmutzigen, zerbrochenen Körper ihrer Mutter, als er aus den Ruinen geborgen wurde."
  },
  AvgDialog_47176_Content_24 = {
    Text = "In ihren letzten Momenten war sie auch kalt, ängstlich und hoffnungslos, so wie ich es jetzt bin?"
  },
  AvgDialog_47176_Content_25 = {
    Text = "Tränen vermischen sich hilflos mit dem Regen. Die Stimme wurde schwächer und zitterte zusammen mit dem Körper..."
  },
  AvgDialog_47176_Content_26 = {Text = "Boom—"},
  AvgDialog_47176_Content_27 = {Text = "\"Ah!!!...\""},
  AvgDialog_47176_Content_28 = {Text = "\"Miryam!\""},
  AvgDialog_47176_Content_29 = {
    Text = "Die Steinsäule bricht. Bevor der massive Stein fällt, stürzt eine vertraute Gestalt herüber und zieht Miryam in ihre Arme."
  },
  AvgDialog_47176_Content_3 = {
    Text = "\"Die Stürme Lemurias werden sich legen. Der Abgrund Lemurias wird verschwinden.\""
  },
  AvgDialog_47176_Content_30 = {
    Text = "\"Vater... Vater!...\""
  },
  AvgDialog_47176_Content_31 = {
    Text = "Miryam bewegte langsam ihren Arm, der instinktiv ihre Augen schützte."
  },
  AvgDialog_47176_Content_32 = {Text = "\"\"Uwa...\""},
  AvgDialog_47176_Content_33 = {
    Text = "Sie umarmte die vertraute Gestalt."
  },
  AvgDialog_47176_Content_34 = {
    Text = "\"Hab keine Angst, Miryam. Hab keine Angst. Ich bin hier.\""
  },
  AvgDialog_47176_Content_35 = {
    Text = "\"Hiss... Sei vorsichtig, Kind... Berühre nicht die Schulter...\""
  },
  AvgDialog_47176_Content_36 = {
    Text = "\"Blutest du?!\""
  },
  AvgDialog_47176_Content_37 = {
    Text = "Steine fielen, Trümmer flogen. Der Mann schützte das Mädchen vor den herabfallenden Steinen, seine sonnengebräunte Haut war übersät mit Schnitten und Prellungen, die durch die Trümmer verursacht wurden."
  },
  AvgDialog_47176_Content_38 = {
    Text = "Rasendes Graben durch Steine und Erde hinterließ die rauen Hände blutig und wund."
  },
  AvgDialog_47176_Content_39 = {
    Text = "Der Regen wusch über den Körper des Mannes und vermischte sich mit frischem Blut, das die Trümmer blutrot färbte."
  },
  AvgDialog_47176_Content_4 = {
    Text = "\"Der König wird sein gutes Volk beherbergen und das Königreich der Götter bringen.\nSanfte Gewässer, die jede Fläche von Gras und Holz nähren...\""
  },
  AvgDialog_47176_Content_40 = {
    Text = "„Vater... ich... ich bin der, der dir wehgetan hat...“"
  },
  AvgDialog_47176_Content_41 = {
    Text = "Eine grobe, breite Hand ruhte sanft auf ihrem Kopf und streichelte ihn sanft."
  },
  AvgDialog_47176_Content_42 = {
    Text = "\"Dummes Kind, was sagst du? Solange du unversehrt bist, ist keine Verletzung zu groß, um sie zu ertragen.\""
  },
  AvgDialog_47176_Content_43 = {
    Text = "„Das ist gut, das ist gut... Endlich aufgeholt...“"
  },
  AvgDialog_47176_Content_44 = {
    Text = "\"Danke, mein Herr! Für den Schutz meiner Familie...\""
  },
  AvgDialog_47176_Content_45 = {
    Text = "„Mein Beschützer... war mein Vater...“"
  },
  AvgDialog_47176_Content_46 = {
    Text = "\"Das Volk von Lemuria überlebte dank des Königs. Nur durch fromme Verehrung des Königs kannst du deine Familie schützen. Du bist noch jung, aber du wirst es verstehen, wenn du erwachsen bist.\""
  },
  AvgDialog_47176_Content_47 = {
    Text = "Enos lächelte und streichelte ihren Kopf. Zusammen mit Miryam verbeugte er sich fromm zum Tempel."
  },
  AvgDialog_47176_Content_48 = {
    Text = "\"Kommen Sie, rezitieren Sie mit mir. \nAlle, die verloren sind, mein Herr wird führen...\""
  },
  AvgDialog_47176_Content_49 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47176_Content_5 = {Text = "Boom—"},
  AvgDialog_47176_Content_50 = {
    Text = "\"...Alles, was erhofft wird, wird mein Herr gewähren...\""
  },
  AvgDialog_47176_Content_51 = {Text = "\"Miryam?\""},
  AvgDialog_47176_Content_52 = {
    Text = "...Alle, die fromm sind, werden von unserem Herrn begünstigt..."
  },
  AvgDialog_47176_Content_53 = {
    Text = "\"Miryam? Schlafen?\""
  },
  AvgDialog_47176_Content_54 = {
    Text = "\"Ah, Vater! Es tut mir leid... ich habe nur über einige Dinge aus der Vergangenheit nachgedacht...\""
  },
  AvgDialog_47176_Content_55 = {
    Text = "\"Miryam, bist du sicher, dass du Priesteranwärterin werden möchtest?\""
  },
  AvgDialog_47176_Content_56 = {
    Text = "„Ja, Vater.“"
  },
  AvgDialog_47176_Content_57 = {
    Text = "\"Das ist gut, das ist gut. Ich habe bemerkt, dass du abgelenkt zu sein scheinst und normalerweise nicht gerne über diese Dinge redest... Ich dachte, du magst das nicht...\""
  },
  AvgDialog_47176_Content_58 = {
    Text = "\"Du hast dich an diesem Tag freiwillig für den Priesterlehrling beworben, und Papa war so glücklich. Unsere Tochter ist erwachsen geworden...\""
  },
  AvgDialog_47176_Content_59 = {
    Text = "\"Da wir hier sind, lass uns dem Priester zuhören. Der König steht Gott am nächsten, Er sieht alles. Nur die Frommen erhalten Seine Gnade.\""
  },
  AvgDialog_47176_Content_6 = {
    Text = "\"Ah!......\""
  },
  AvgDialog_47176_Content_60 = {
    Text = "\"Hmm... Ich verstehe, Vater.\""
  },
  AvgDialog_47176_Content_61 = {
    Text = "Es ist nie der König, der sich sorgt. Miryam dachte dies, sagte es aber nicht."
  },
  AvgDialog_47176_Content_62 = {
    Text = "\"Papa, wird meine Schwester gewählt?\""
  },
  AvgDialog_47176_Content_63 = {
    Text = "\"Natürlich! Die Priester in der Stadt sagten, dass die spirituelle Krafttalente deiner Schwester sogar stärker sind als die der Priester selbst.\""
  },
  AvgDialog_47176_Content_64 = {
    Text = "\"Nicht nur kann sie Priesterin werden, sie könnte sogar in Zukunft die Hochpriesterin werden!\""
  },
  AvgDialog_47176_Content_65 = {
    Text = "\"Das ist die größte Ehre... Wenn das wahr ist, wäre deine Mutter in der anderen Welt stolz auf dich!\""
  },
  AvgDialog_47176_Content_66 = {
    Text = "\"Ah! Der Priester kommt!\""
  },
  AvgDialog_47176_Content_67 = {
    Text = "Inmitten von Sarahs aufgeregten Rufen blickten alle nach vorne."
  },
  AvgDialog_47176_Content_68 = {
    Text = "Die Priesterin im lila Schleier betet, während sie geht. Sie passiert jedes Kandidatenkind und hält vor Miryams Familie an."
  },
  AvgDialog_47176_Content_69 = {
    Text = "\"<Mein Herr>, bitte höre mein frommes Flehen. Ich bitte demütig darum, meine Tochter, Miryam, anzunehmen...\""
  },
  AvgDialog_47176_Content_7 = {
    Text = "Donner krachte über der Insel. Ein kleiner Körper zittert unter den Ruinen."
  },
  AvgDialog_47176_Content_70 = {
    Text = "Die sanften Gebete des Vaters und die feierliche Autorität des Priesters ließen Miryam verstummen."
  },
  AvgDialog_47176_Content_71 = {
    Text = "Sie senkte ihren Kopf in Erwartung. Die erhobene Hand des Priesters ruhte auf ihrer Stirn."
  },
  AvgDialog_47176_Content_72 = {
    Text = "\"Großer Priester, darf ich nach meinem Kind fragen...\""
  },
  AvgDialog_47176_Content_73 = {
    Text = "Der Vater schaute dem Priester demütig entgegen. Sie reagierte nicht und zeigte auch keinen Ausdruck. Sie hatte zu viele solche Geschichten gehört und kein Interesse an den leisen Schreien der Tiere."
  },
  AvgDialog_47176_Content_74 = {
    Text = "Diese gut gepflegten Hände blieben keinen Moment lang stehen. Der Priester, begleitet von dem Diener, drehte sich um und ging, zurück zum Altar."
  },
  AvgDialog_47176_Content_75 = {
    Text = "\"Hat nicht geschafft, huh...\""
  },
  AvgDialog_47176_Content_76 = {
    Text = "\"Vater, es tut mir leid... Ich konnte der Familie immer noch nicht helfen...\""
  },
  AvgDialog_47176_Content_77 = {
    Text = "\"Worüber redest du, albernes Kind? Die Sterne haben bereits das Schicksal eines jeden bestimmt. Hat dein Vater nicht auch versagt, Priester zu werden?\""
  },
  AvgDialog_47176_Content_78 = {
    Text = "\"Solange du gesund und glücklich leben kannst, wird Dad zufrieden sein. Auch wenn du kein Priester werden kannst, bist du immer noch Dads gutes Kind.\""
  },
  AvgDialog_47176_Content_79 = {
    Text = "\"Papa, was ist mit mir?\""
  },
  AvgDialog_47176_Content_8 = {
    Text = "Der Ozean grollte wütend nicht weit von ihr entfernt und übertönte fast den Donner. Die große Insel Lemuria zitterte wie ein einsames verwelktes Blatt im weiten Meer."
  },
  AvgDialog_47176_Content_80 = {
    Text = "\"Hahaha, ihr seid alles gute Kinder!\""
  },
  AvgDialog_47176_Content_81 = {
    Text = "Miryam konnte den Gesichtsausdruck ihres Vaters der Enttäuschung sehen. Doch diese raue, breite Hand ruhte immer noch sanft auf ihrem Kopf."
  },
  AvgDialog_47176_Content_82 = {
    Text = "Seit sie klein war, erschien immer diese Hand, wenn sie sich ängstlich, verloren oder traurig fühlte, sanft, um ihren Kopf zu streicheln und sie zu beruhigen."
  },
  AvgDialog_47176_Content_83 = {
    Text = "Vom Kindesalter bis zum Erwachsenenalter, was hat der Besitzer dieser Hand erlitten? Und was habe ich getan, um ihm zu helfen?"
  },
  AvgDialog_47176_Content_84 = {
    Text = "Miryam senkte den Kopf und verbarg ihre geröteten Augen."
  },
  AvgDialog_47176_Content_85 = {
    Text = "\"Hey, Schwester, schau! Ein alter Mann betritt die Bühne!\""
  },
  AvgDialog_47176_Content_86 = {
    Text = "\"Diese Robe! ... Die lila! ...\""
  },
  AvgDialog_47176_Content_87 = {
    Text = "Ein eifriger Gläubiger drängte sich neugierig neben Inos und stellte sich auf die Zehenspitzen für eine bessere Sicht."
  },
  AvgDialog_47176_Content_88 = {
    Text = "\"Ist es der Hohepriester? Der Hohepriester ist tatsächlich aus dem Tempel herausgekommen?! Niemand hat das erwähnt...\""
  },
  AvgDialog_47176_Content_89 = {
    Text = "Ein alter Mann trat aus dem Hinterzimmer hervor. Sein Gesicht war gealtert, aber seine Schritte waren sicher, und seine Kleidung war sorgfältig gepflegt, ohne einen einzigen Falten."
  },
  AvgDialog_47176_Content_9 = {
    Text = "Das starke Erdbeben der Insel hat nachgelassen, aber sie fühlt sich immer noch schwindelig."
  },
  AvgDialog_47176_Content_90 = {
    Text = "Der Hohe Priester, der Einzige, der den König treffen kann. In ganz Lemuria ist sein Status nur dem des Königs untergeordnet, der mit Gott kommuniziert."
  },
  AvgDialog_47176_Content_91 = {
    Text = "Der strenge Blick des alten Mannes schwenkte durch den Raum. Er sagte nichts, aber unter seinem Blick verstummte der einst laute Tempel."
  },
  AvgDialog_47176_Content_92 = {
    Text = "Bald richtete sich dieser Blick auf Miryam. Der Priester führte den alten Mann, der seine faltige Hand auf ihre Stirn legte."
  },
  AvgDialog_47176_Content_93 = {
    Text = "Die arroganten Priester beugen sich nun vor dem alten Mann. Alles im Tempel scheint mit seinem Eintreffen eingefroren zu sein. Sie kann nicht atmen oder den Zeitverlauf wahrnehmen."
  },
  AvgDialog_47176_Content_94 = {
    Text = "\"Würdest du deinen Vater für den König töten?\""
  },
  AvgDialog_47176_Content_95 = {
    Text = "Eine kalte Stimme kam vom Hohepriester und zerschmetterte die gefrorene Zeit wie einen Donnerhall."
  },
  AvgDialog_47176_Content_96 = {
    Text = "Miryam hob plötzlich ihren Kopf und sah das gealterte, strenge Gesicht des Hohen Priesters."
  },
  AvgDialog_47176_Content_97 = {
    Text = "\"Was... Was hast du gesagt?\""
  },
  AvgDialog_47176_Content_98 = {
    Text = "\"Sag mir, was ist Glaube?\""
  },
  AvgDialog_47176_Content_99 = {
    Text = "„Der Glaube ist... alles für den König zu geben...“"
  },
  AvgDialog_47177_Content_1 = {
    Text = "Fischfleisch"
  },
  AvgDialog_47177_Content_10 = {
    Text = "Schwester, Fisch ist so lecker. Warum magst du es nicht, ihn zu essen?"
  },
  AvgDialog_47177_Content_11 = {
    Text = "Vielleicht lag es daran, dass ich als Kind zu viel gegessen habe, vielleicht war es der fischige Geschmack oder vielleicht..."
  },
  AvgDialog_47177_Content_12 = {
    Text = "Sara, ich habe dir noch nicht von Mamas Tod erzählt, oder?"
  },
  AvgDialog_47177_Content_13 = {
    Text = "Sarah schüttelte den Kopf und kuschelte sich leise in Miryams Arme, um zuzuhören."
  },
  AvgDialog_47177_Content_14 = {
    Text = "Du warst gerade geboren worden, und deine Mutter war ans Bett gefesselt. Als die Steine den Berg hinunterrollten, hatte sie keine Zeit zu entkommen."
  },
  AvgDialog_47177_Content_15 = {
    Text = "Der Wind war an diesem Tag stark, und Fische fielen vom Himmel und landeten auf Mom."
  },
  AvgDialog_47177_Content_16 = {
    Text = "Ihre Augen waren weit geöffnet, genau wie die Fische..."
  },
  AvgDialog_47177_Content_17 = {
    Text = "Miryam sprach nicht weiter, und Sarah stellte keine weiteren Fragen. Die jüngere Schwester klammerte sich fest an ihre ältere Schwester und klopfte ihr den Rücken."
  },
  AvgDialog_47177_Content_18 = {
    Text = "Wenn dir das nicht gefällt, warum sagst du es dann nicht Vater?"
  },
  AvgDialog_47177_Content_19 = {
    Text = "Wenn es etwas gibt, das ich nicht mag, sage ich es dir direkt."
  },
  AvgDialog_47177_Content_2 = {Text = "Zzzap—"},
  AvgDialog_47177_Content_20 = {
    Text = "Nachdem Mama gestorben war, hat Papa uns ganz allein großgezogen. Er lebte ein hartes Leben."
  },
  AvgDialog_47177_Content_21 = {
    Text = "In Lemuria ist Fisch das billigste Essen."
  },
  AvgDialog_47177_Content_22 = {
    Text = "Ich bin nicht sehr fähig und kann zu Hause nicht viel helfen. Das Einzige, was ich tun kann, ist, zu vermeiden, ihm Probleme zu bereiten..."
  },
  AvgDialog_47177_Content_23 = {
    Text = "Sara, denk daran, wenn du groß bist, musst du Dad helfen, okay?"
  },
  AvgDialog_47177_Content_24 = {
    Text = "Hmm! Hey, Schwester, ist es für dich dasselbe, als Priesterin zu sein, wie Fisch zu essen?"
  },
  AvgDialog_47177_Content_25 = {
    Text = "Hier! Für die beiden kleinen Prinzessinnen ist das letzte Gericht fertig!"
  },
  AvgDialog_47177_Content_26 = {
    Text = "Die Stimme des Vaters aus der Küche unterbrach Sarahs Frage. Miryam lächelte und änderte das Thema."
  },
  AvgDialog_47177_Content_27 = {
    Text = "Sarah, du darfst niemandem von diesen Angelegenheiten erzählen, in Ordnung?"
  },
  AvgDialog_47177_Content_28 = {
    Text = "Verstanden! Sara wird ihrer Schwester und ihrem Vater keine Probleme bereiten~"
  },
  AvgDialog_47177_Content_29 = {
    Text = "Miryam lächelt und patscht ihrer Schwester auf den Kopf, führt sie in die Küche, um das Festmahl zu genießen, das ihr Vater für sie zubereitet hat."
  },
  AvgDialog_47177_Content_3 = {
    Text = "Frisches Fischfleisch wird in den Topf gelegt, mit wunderbaren Geräuschen und Aromen, die aus der einfachen Küche strömen."
  },
  AvgDialog_47177_Content_30 = {
    Text = "Bald füllten verschiedene Fischgerichte den kleinen Tisch zu Hause."
  },
  AvgDialog_47177_Content_31 = {
    Text = "Als du zum Einkaufen gingst, habe ich den Stadtbewohnern erzählt und Briefe an unsere entfernten Verwandten geschrieben. Sie werden in ein paar Tagen Bescheid wissen."
  },
  AvgDialog_47177_Content_32 = {
    Text = "Die Nachbarn, die dich aufwachsen sahen, freuen sich für dich und haben viele Lebensmittel und Getränke mitgebracht."
  },
  AvgDialog_47177_Content_33 = {
    Text = "Oh richtig, und der Priester in der Stadt. Ich habe gehört, dass du vom Oberpriester ausgewählt wurdest. Er kam, um mit mir zu sprechen, sehr höflich!"
  },
  AvgDialog_47177_Content_34 = {
    Text = "Es ist nur ein kleines Problem... Es ist nicht nötig, so viele Leute zu informieren..."
  },
  AvgDialog_47177_Content_35 = {
    Text = "Das ist keine Kleinigkeit! Wenn meine Schwester Priesterin wird, wird sie viel Geld verdienen und jemanden anheuern können, der für mich putzt..."
  },
  AvgDialog_47177_Content_36 = {
    Text = "Rede keinen Unsinn, Sarah. Priester zu sein ist ein heiliger Beruf, nicht für solche Dinge."
  },
  AvgDialog_47177_Content_37 = {
    Text = "Was macht der Priester?"
  },
  AvgDialog_47177_Content_38 = {
    Text = "Die Mission des Priesters... sie reicht weit zurück. Dies ist eine Geschichte, die jeder Lemurisch kennen sollte."
  },
  AvgDialog_47177_Content_39 = {
    Text = "Inos hebt Sara auf, setzt sie auf seinen Schoß und streichelt ihren Kopf."
  },
  AvgDialog_47177_Content_4 = {
    Text = "Das sind die Lieblingsgerichte der Töchter. Inos macht sie seit über einem Jahrzehnt und kann die Menge jedes Gewürzes präzise kontrollieren, während sie die Augen geschlossen hat."
  },
  AvgDialog_47177_Content_40 = {
    Text = "Lemuria hat eine glorreiche Geschichte und eine brillante Zivilisation. Die Macht der Götter schützt dieses Land und gewährt uns endloses Glück und Frieden."
  },
  AvgDialog_47177_Content_41 = {
    Text = "Es gibt keine Naturkatastrophen oder Krankheiten hier. Jeder hat einen endlosen Vorrat an Essen und Wein. Selbst die Verstorbenen können sich mit den Lebenden mit Hilfe der Götter wiedervereinen."
  },
  AvgDialog_47177_Content_42 = {
    Text = "Aber irgendwann konnten die Menschen hier die Stimme Gottes nicht mehr hören. Naturkatastrophen wurden immer häufiger..."
  },
  AvgDialog_47177_Content_43 = {
    Text = "Unser Land ist von endlosen Meeren umgeben, und niemand konnte jemals entkommen. Nur die Götter können das ändern."
  },
  AvgDialog_47177_Content_44 = {
    Text = "Unser König ist der Einzige, der mit den Göttern kommunizieren kann. Der König wird das Orakel hören und uns göttliche Segnungen bringen."
  },
  AvgDialog_47177_Content_45 = {
    Text = "Bis dahin werden alle Katastrophen verschwunden sein, die Verstorbenen werden wiedergeboren, und wir werden hier ewig wohnen... Lemuria wird wieder das perfekte Reich des Gottes werden!"
  },
  AvgDialog_47177_Content_46 = {
    Text = "Sein Adamsapfel bewegte sich, als er seinen hoffnungsvollen Blick von der Richtung des Tempels abzog."
  },
  AvgDialog_47177_Content_47 = {
    Text = "Jedoch ist die Macht des Königs begrenzt und erfordert die Hilfe seiner Untertanen. Nur diejenigen mit ausreichender Geistkraft sind in der Lage, Priester zu werden, den Willen des Königs zu verkünden und ihm zu helfen."
  },
  AvgDialog_47177_Content_48 = {
    Text = "Als gewöhnlicher Mensch wie ich habe ich nicht das Talent, irgendetwas zu tun. Ich kann nur hilflos zusehen, während deine Mutter..."
  },
  AvgDialog_47177_Content_49 = {
    Text = "Vergiss es, vergiss es. Heute ist ein guter Tag; lass uns nicht darüber reden."
  },
  AvgDialog_47177_Content_5 = {Text = "Hmm—"},
  AvgDialog_47177_Content_50 = {
    Text = "Er wischte sich die Ecken der Augen und tätschelte mit einem Lächeln die Köpfe seiner beiden Töchter."
  },
  AvgDialog_47177_Content_51 = {
    Text = "Priester zu werden, dem König zu helfen und Lemuria zu retten, ist die größte Ehre."
  },
  AvgDialog_47177_Content_52 = {
    Text = "Vielen Dank, Eure Majestät, dass Sie unserem bescheidenen Zuhause eine solche Gelegenheit gegeben haben..."
  },
  AvgDialog_47177_Content_53 = {
    Text = "Inos hob den Becher. Die trübe Flüssigkeit wirbelte darin und verströmte einen stechenden Geruch nach minderwertigem Alkohol."
  },
  AvgDialog_47177_Content_54 = {
    Text = "Die Armen in Lemuria lieben dieses Getränk; es ist billig und stark und bietet ihnen für wenig Geld kurze Erholung."
  },
  AvgDialog_47177_Content_55 = {
    Text = "Verunreinigungen im Alkohol verursachen am nächsten Tag starke Kopfschmerzen. Für sie sind Kater und Schmerz ein wertvolles Geschenk."
  },
  AvgDialog_47177_Content_56 = {
    Text = "Er trank alles auf einen Schluck."
  },
  AvgDialog_47177_Content_57 = {
    Text = "Sarah, dein Vater ist nicht von großem Nutzen, aber deine Schwester ist der Stolz unserer ganzen Familie!"
  },
  AvgDialog_47177_Content_58 = {
    Text = "Hier, Miryam, das ist dein Lieblingsfischfilet. Alte Ona hat es heute gefangen! Ich habe ihn speziell gebeten, es für mich aufzuheben."
  },
  AvgDialog_47177_Content_59 = {
    Text = "Papa möchte dir nicht zu viel Stress auferlegen. Mach einfach dein Ding. Ich weiß, du kannst es schaffen!"
  },
  AvgDialog_47177_Content_6 = {
    Text = "Schwester, dein Magen macht wieder Probleme... Jedes Mal, wenn du Fisch riechst, wird dir übel. Seufz."
  },
  AvgDialog_47177_Content_60 = {
    Text = "Dad hofft nur, dass du in Zukunft gut auf dich aufpassen kannst. Wenn dich etwas stört, schreibe mir."
  },
  AvgDialog_47177_Content_61 = {
    Text = "Ich verlasse morgen das Haus. Wer weiß, wann ich wieder Fisch von Papa essen kann..."
  },
  AvgDialog_47177_Content_62 = {
    Text = "Ein Teller voller Fische wurde vor Miryam platziert. Goldfarben und reich an Aroma."
  },
  AvgDialog_47177_Content_63 = {
    Text = "Die Schwester lächelt. Der Vater lächelt, Tränen steigen ihm in die Augen. Die Mutter scheint in der Nähe zu sitzen und lächelt mich an."
  },
  AvgDialog_47177_Content_64 = {
    Text = "Ihre Kleider waren zerrissen, ihr Körper verstümmelt, und ihre Augen weit offen, wie der Fisch auf dem Teller."
  },
  AvgDialog_47177_Content_65 = {
    Text = "Ich werde ein Priester werden... Ich werde dich nicht enttäuschen, Vater."
  },
  AvgDialog_47177_Content_66 = {
    Text = "Miryam steckte den Fisch in den Mund, kaute und schluckte. Sie lächelte ihrer Familie zu."
  },
  AvgDialog_47177_Content_7 = {
    Text = "Die jüngere Schwester klopfte Miryam auf den Rücken, während sie seufzte und den Kopf schüttelte."
  },
  AvgDialog_47177_Content_8 = {
    Text = "Ein großmütterlicher Ausdruck erschien auf dem Gesicht des Zehnjährigen, was Miryam zum Kichern brachte."
  },
  AvgDialog_47177_Content_9 = {
    Text = "Mir geht's gut, Sarah."
  },
  AvgDialog_47178_Content_1 = {
    Text = "Abgründiges Gebet"
  },
  AvgDialog_47178_Content_10 = {
    Text = "Schwisch—"
  },
  AvgDialog_47178_Content_100 = {
    Text = "Die schwer fassbaren Augen scheinen an den Anhängern in diesem Raum vorbei zu blicken, über die massiven Steintore hinweg, und auf die Menge von Lemuria zu schauen."
  },
  AvgDialog_47178_Content_101 = {
    Text = "Was ist in diesen Augen eingraviert, frage ich mich – ist es Überzeugung, Mitgefühl oder Müdigkeit?"
  },
  AvgDialog_47178_Content_11 = {
    Text = "<Shake:Mmm!!!...>"
  },
  AvgDialog_47178_Content_12 = {
    Text = "Ein durchnässter Kreatur springt aus dem Wasser, spärliche menschliche Haare hängen von ihrem Kopf und bedecken ihr fischähnliches Gesicht."
  },
  AvgDialog_47178_Content_13 = {
    Text = "Seine Kiemen öffnen sich leicht, schleimige Lippen vibrieren, mutierte Stimmbänder zittern und geben chaotische, bedeutungslose Silben von sich."
  },
  AvgDialog_47178_Content_14 = {
    Text = "Die menschlichen Gliedmaßen sind mit chaotischen Schuppen bedeckt, die einen schmutzigen Glanz reflektieren, wild an der Wasseroberfläche herumfuchtelnd."
  },
  AvgDialog_47178_Content_15 = {
    Text = "Klapper klapper klapper klapper..."
  },
  AvgDialog_47178_Content_16 = {
    Text = "In zwei großen Becken tauchen zahllose fischgesichtige Kreaturen mit identischen Gesichtern auf, die wild auf das Wasser schlagen und seltsame Geräusche von sich geben."
  },
  AvgDialog_47178_Content_17 = {
    Text = "Sie drängen sich im Wasser zusammen, unzählige Fischaugen starren leer und gefühllos auf Miryam."
  },
  AvgDialog_47178_Content_18 = {Text = "Hmm—"},
  AvgDialog_47178_Content_19 = {
    Text = "Miryam setzte all ihre Kraft ein, um sich davon abzuhalten, sich zu übergeben."
  },
  AvgDialog_47178_Content_2 = {
    Text = "Ein tiefes Summen, wie ein Ruf aus alten Zeiten."
  },
  AvgDialog_47178_Content_20 = {
    Text = "Das sind..."
  },
  AvgDialog_47178_Content_21 = {
    Text = "Das stimmt, sie sind die großen Pioniere! Ich sehe sie auch zum ersten Mal. So sehen sie also aus!"
  },
  AvgDialog_47178_Content_22 = {
    Text = "Die Priesterlehrling namens Deborah stand neben Miryam und klopfte ihr begeistert auf die Schulter, obwohl es ihr erstes Treffen war."
  },
  AvgDialog_47178_Content_23 = {
    Text = "Die Legende besagt, dass der König eine göttliche Offenbarung erhielt: Bevor Lemuria in das Göttliche Reich verwandelt wird, muss er mit heiligem Blut sein Volk verwandeln, um ihnen die Fähigkeit zu verleihen, Katastrophen zu überstehen."
  },
  AvgDialog_47178_Content_24 = {
    Text = "Diese Pioniere sind mutig diesen Schritt für die Zukunft der Lemurier gegangen."
  },
  AvgDialog_47178_Content_25 = {
    Text = "Sobald wir Priester werden, wird das Murloc-Transformationsritual von uns durchgeführt. Ich werde so aufgeregt sein, dass ich nicht schlafen kann!"
  },
  AvgDialog_47178_Content_26 = {
    Text = "Deborah begrüßte die Murlocs freudig und streichelte sanft ihre glatten Gesichter."
  },
  AvgDialog_47178_Content_27 = {
    Text = "Die anderen Lehrlingen verbeugten sich ebenfalls und ehrten die Weisen. Miryam stand still und beobachtete die Szenerie."
  },
  AvgDialog_47178_Content_28 = {
    Text = "„Die großen Pioniere“... Ich frage mich, ob ihre Familien genauso fühlen würden, wenn sie das sehen."
  },
  AvgDialog_47178_Content_29 = {
    Text = "Der Gebetsraum ist gleich vorne. Alle, folgt mir."
  },
  AvgDialog_47178_Content_3 = {
    Text = "Eine riesige plattierte Tür, die mit Reliefs graviert war, wurde von einer unbekannten Kraft bewegt und öffnete sich auf beiden Seiten. Das äußere Licht konnte überhaupt nicht nach drinnen eindringen."
  },
  AvgDialog_47178_Content_30 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47178_Content_31 = {
    Text = "Die Tablet Tür schließt sich lautlos und schneidet die Schreie der Meerleute und den Lärm von außen ab."
  },
  AvgDialog_47178_Content_32 = {
    Text = "Die Lehrlinge knien an den Gebetsplätzen und blicken auf den Altar und die massive Statue dahinter, die aus menschlichen Körpern, einem Thron und Tentakeln besteht."
  },
  AvgDialog_47178_Content_33 = {
    Text = "Das Gesicht auf der Statue ist verschwommen, mit einem menschlichen Körper, der zwischen einem massiven Thron und Tentakeln sitzt, was einen krassen Kontrast schafft."
  },
  AvgDialog_47178_Content_34 = {
    Text = "Das ist eine Statue, die den König symbolisiert."
  },
  AvgDialog_47178_Content_35 = {
    Text = "Der alte Mann trat von der rechten Seite des Statuesaals heraus, winkte mit seiner Hand und hielt die Lehrlinge auf, die aufstehen und salutieren wollten."
  },
  AvgDialog_47178_Content_36 = {
    Text = "Die Gebete stehen vor dir. Lies sie, rezitiere sie und, am wichtigsten, glaube an sie."
  },
  AvgDialog_47178_Content_37 = {
    Text = "Hochpriester, wenn wir diese Aufgaben erfüllen, können wir dann dem König helfen?"
  },
  AvgDialog_47178_Content_38 = {
    Text = "Der Hohe Priester warf ihr einen Blick zu."
  },
  AvgDialog_47178_Content_39 = {
    Text = "Der Herr wird es euch sagen. Nun betet."
  },
  AvgDialog_47178_Content_4 = {
    Text = "Intensive und reine Dunkelheit lädt alle von hinter der Tür ein."
  },
  AvgDialog_47178_Content_40 = {
    Text = "Er verlässt den Raum und lässt nur einen Priester und einige Wachen bei den Lehrlingen zurück."
  },
  AvgDialog_47178_Content_41 = {
    Text = "Das Licht im Gebetsraum wird schwächer. Ein geheimnisvolles, schwaches Leuchten beginnt auf der Oberfläche der Statue zu erscheinen."
  },
  AvgDialog_47178_Content_42 = {
    Text = "Miryam nimmt das Gebetsblatt vor sich auf."
  },
  AvgDialog_47178_Content_43 = {Text = "Ah..."},
  AvgDialog_47178_Content_44 = {
    Text = "Die Texte auf dem Papier sind in einer Sprache verfasst, die sich vom gewöhnlichen Lemurischen unterscheidet. Übersät mit komplexen Hieroglyphen, besitzt sie mehr Dimensionen als der reale Raum."
  },
  AvgDialog_47178_Content_45 = {
    Text = "Miryam fragt sich, ob diese seltsamen Glyphen von uralten Inschriften stammen oder gar aus einer anderen Welt. Doch ihre Bedeutung dringt beim Lesen von selbst in ihren Geist ein."
  },
  AvgDialog_47178_Content_46 = {
    Text = "Unzählige Schriften fluten in Miryams Gehirn. Als sich ihre Bedeutungen in überwältigender Weite entfalten, gerät ihr zerbrechlicher Verstand an den Rand des Zusammenbruchs."
  },
  AvgDialog_47178_Content_47 = {
    Text = "<Shake:Mein Kopf... es tut weh...>"
  },
  AvgDialog_47178_Content_48 = {
    Text = "Ringsherum fallen Menschen zu Boden. Den Schmerz ertragend, rezitiert Miryam die Gebete vom Papier."
  },
  AvgDialog_47178_Content_49 = {
    Text = "„In dem fernen sonnenlosen Abgrund schlummert die große uralte Seele...“"
  },
  AvgDialog_47178_Content_5 = {
    Text = "Die Außenansicht des Tempels ist normalen Gläubigen geöffnet, aber nur diejenigen, die qualifiziert sind, Priester zu werden, dürfen hierher kommen."
  },
  AvgDialog_47178_Content_50 = {
    Text = "Miryam spricht diese Worte in gewöhnlichem Lemurisch, doch während sie spricht, erwachen die Worte zum Leben. Buchstaben verzerren sich wie Tentakel, schwarze Tinte tanzt in der Luft, bis sie sich in eine andere Sprache verwandeln."
  },
  AvgDialog_47178_Content_51 = {
    Text = "Ihre Stimme überlagert und verflicht sich in diesem einen Augenblick. Vokale haken sich an Konsonanten, Endungen verschmelzen mit Anfängen, genau wie jene Symbole. Was aus ihrer Kehle dringt, formt eine komplexe Struktur in einer höheren Dimension, als würde es aus einer unvorstellbaren Raumzeit widerhallen."
  },
  AvgDialog_47178_Content_52 = {
    Text = "„... Sein Wille webt sich wie ein Netz aus Sternen; in der ewigen Leere wartet Er darauf, dass du in Seinen Traum eintrittst...“"
  },
  AvgDialog_47178_Content_53 = {
    Text = "Miryam singt mit all ihrer Kraft weiter."
  },
  AvgDialog_47178_Content_54 = {
    Text = "Während ihre Worte nachhallen und sich unaufhörlich übereinanderschichten, verschwimmt die Realität um sie herum, löst sich auf."
  },
  AvgDialog_47178_Content_55 = {
    Text = "Sie findet sich in einem tiefen Meer versunken wieder. Geschmeidiges Wasser fließt in alle Richtungen, einer Illusion gleichend."
  },
  AvgDialog_47178_Content_56 = {
    Text = "Es schimmert in silbrigem Licht. Leuchtende Sterne sind überall verstreut, treiben dahin, flackern."
  },
  AvgDialog_47178_Content_57 = {
    Text = "Miryam spürt, dass sie gewissermaßen Teil des Sternenbildes geworden ist. Ihr Mottenlicht wird zu einem bestimmten Ort gelockt. Sie blickt dorthin."
  },
  AvgDialog_47178_Content_58 = {
    Text = "Unzählige Lichtströme wirbeln mit leuchtendem Schaum, einander jagend auf eine ferne, verschwommene Silhouette zu. Eine Silhouette, zusammengesetzt aus einem menschlichen Körper, einem Thron und unzähligen Tentakeln."
  },
  AvgDialog_47178_Content_59 = {
    Text = "Ist das... der Herrscher?"
  },
  AvgDialog_47178_Content_6 = {
    Text = "Meine Damen und Herren, willkommen im Inneren Heiligtum. Willkommen im Wohnsitz des Königs."
  },
  AvgDialog_47178_Content_60 = {Text = "Knack—"},
  AvgDialog_47178_Content_61 = {
    Text = "Eine Stimme reißt ihn von der Steinbank hoch. Als er erwacht, scheint der gesamte Raum der Illusion für einen Moment zu verblassen."
  },
  AvgDialog_47178_Content_62 = {
    Text = "Die vage Gestalt eines alten Mannes erscheint hinter ihm."
  },
  AvgDialog_47178_Content_63 = {
    Text = "Du hast ihre Stimme gehört, mein Lord."
  },
  AvgDialog_47178_Content_64 = {
    Text = "Der König von Lemuria sitzt immer noch auf dem Thron, und ich bin lediglich der Nachfolger. Du solltest mich nicht so ansprechen."
  },
  AvgDialog_47178_Content_65 = {
    Text = "Der König von Lemuria wird nicht durch diejenigen bestimmt, die auf dem Thron sitzen. Wer auch immer den Göttern am nächsten ist, ist unser Herr."
  },
  AvgDialog_47178_Content_66 = {
    Text = "Ich mag diesen Titel nicht."
  },
  AvgDialog_47178_Content_67 = {
    Text = "In seinem Leben hörte der alte König ein einziges Orakel. Dieses Orakel hielt ihn auf dem Thron und wurde zum Glauben seines Volkes."
  },
  AvgDialog_47178_Content_68 = {
    Text = "Die Orakel, die du gehört hast, übertreffen die zahllosen vergangenen Könige von Lemuria. Und du... bist noch ein Kind."
  },
  AvgDialog_47178_Content_69 = {
    Text = "Du bist die Hoffnung von Lemuria. Die Tage des alten Königs sind gezählt, und er hat bereits sein Einverständnis gegeben. Bald wirst du den Thron besteigen. Du musst dich an diesen Titel gewöhnen, mein Herr."
  },
  AvgDialog_47178_Content_7 = {
    Text = "Ein Windstoß wehte aus dem versiegelten inneren Saal und trug einen starken Aequor-Duft mit sich."
  },
  AvgDialog_47178_Content_70 = {
    Text = "Der junge Junge lehnte sich müde in seinen Stuhl zurück und stritt nicht länger mit dem alten Mann."
  },
  AvgDialog_47178_Content_71 = {
    Text = "Das erste Gebet verbindet dich mit mir und ermöglicht es dir, meine Form zu sehen. Ist sie diejenige, die von den Sternen prophezeit wurde?"
  },
  AvgDialog_47178_Content_72 = {
    Text = "Ja, ich habe es überprüft. Sofern die Sterne sich nicht irren, ist sie... die Zukunft Lemurias."
  },
  AvgDialog_47178_Content_73 = {
    Text = "Ihr glaubt das nicht wirklich."
  },
  AvgDialog_47178_Content_74 = {
    Text = "Genug Talent, aber unzureichende Hingabe. Sie kann Euch nicht wahrhaft dienen, mein Gebieter."
  },
  AvgDialog_47178_Content_75 = {
    Text = "Sie glaubt nicht an Gebete, an dich oder an die Zukunft von Lemuria. Sie glaubt nur an ihre Familie."
  },
  AvgDialog_47178_Content_76 = {
    Text = "Miryam lebt in der Realität. Eine solche Person kann nicht das Schicksal der Nation tragen."
  },
  AvgDialog_47178_Content_77 = {
    Text = "In der Wahrheit zu leben, statt in der Illusion, das ist Yus Hoffnung."
  },
  AvgDialog_47178_Content_78 = {
    Text = "Niemand sollte das Schicksal von Lemuria tragen..."
  },
  AvgDialog_47178_Content_79 = {
    Text = "Ein edler Wunsch, mein Gebieter. Doch in Lemuria geboren, hat jeder von uns seine eigenen Pflichten zu erfüllen."
  },
  AvgDialog_47178_Content_8 = {
    Text = "Folge dem Priester in das innere Heiligtum. Die Dunkelheit verschwindet auf seltsame Weise, als ein unbekanntes Licht den scheinbar endlosen Kopfsteinpflasterweg erleuchtet."
  },
  AvgDialog_47178_Content_80 = {
    Text = "Sie hat keine Wahl. Ich habe keine Wahl. Und Ihr, mein Gebieter... habt ebenfalls keine Wahl."
  },
  AvgDialog_47178_Content_81 = {
    Text = "...Langweilig. Ich wünsche jetzt zu ruhen."
  },
  AvgDialog_47178_Content_82 = {
    Text = "Er winkt mit der Hand. Der Älteste verneigt sich vor ihm und verschwindet."
  },
  AvgDialog_47178_Content_83 = {
    Text = "Bevor er in seine Träume zurückkehrt, blickt der Junge auf die Millionen von Lichtern und die Seelen, die sie ihm widmen. Ein flüchtiger Seufzer löst sich in der unermesslichen Leere auf, ungehört, unbeantwortet."
  },
  AvgDialog_47178_Content_84 = {Text = "Autsch!!"},
  AvgDialog_47178_Content_85 = {
    Text = "Dann folgt ein atemberaubendes Gefühl des Fallens, gefolgt von einem stechenden Schmerz."
  },
  AvgDialog_47178_Content_86 = {
    Text = "Der Schmerz hält nicht lange an. Miryam verlässt diesen geistigen Raum. Sie öffnet die Augen und blickt sich verwirrt um."
  },
  AvgDialog_47178_Content_87 = {
    Text = "Diejenigen, die die Gebete nicht lesen oder rezitieren konnten, wurden hinausgeführt. Von den Verbliebenen liegen einige schmerzgeplagt am Boden, während andere mit geschlossenen Augen im Gebet selige Lächeln tragen."
  },
  AvgDialog_47178_Content_88 = {
    Text = "Deborah sitzt neben ihr, ein sanftes Lächeln breitet sich auf ihrem Gesicht aus, als sie langsam die Augen öffnet. Doch ihr Ausdruck verfinstert sich, als sich ihre Blicke mit Miryams treffen."
  },
  AvgDialog_47178_Content_89 = {
    Text = "Hey, Miryam? Geht es dir gut?"
  },
  AvgDialog_47178_Content_9 = {
    Text = "An beiden Enden des Pfades lagen zwei massive Becken. Miryam näherte sich einem Becken und spähte hinein."
  },
  AvgDialog_47178_Content_90 = {
    Text = "Mein Kopf tut weh... Ich war vor kurzem noch in Ordnung. Warum bin ich plötzlich gegangen? Ist etwas falsch...?"
  },
  AvgDialog_47178_Content_91 = {
    Text = "Es scheint... du hast versagt. Der Traum des Königs hat dich abgelehnt"
  },
  AvgDialog_47178_Content_92 = {
    Text = "Aber warum... Ich habe klar eine Silhouette gesehen. Wie konnte sie plötzlich..."
  },
  AvgDialog_47178_Content_93 = {
    Text = "Der Priester betritt den Traum des Königs durch Gebete, um Unterstützung zu bieten. Die Silhouette des Königs zu sehen, ist eine bemerkenswerte Leistung, die nur den begabtesten Priestern gelingt!"
  },
  AvgDialog_47178_Content_94 = {
    Text = "Ich bin mir nicht ganz sicher, wo das Problem liegt... Aber das ist nur das erste Mal! Vielleicht liegt es einfach daran, sich daran zu gewöhnen. Es wird besser!"
  },
  AvgDialog_47178_Content_95 = {
    Text = "Vielen Dank..."
  },
  AvgDialog_47178_Content_96 = {
    Text = "Keine Notwendigkeit, höflich zu sein~ Mach weiter so! Dieses Gebet ist für jeden Priester unerlässlich. Du wirst es für sowohl Gebete als auch Fisch-Mann-Rituale brauchen, um mit dem König zu verknüpfen."
  },
  AvgDialog_47178_Content_97 = {
    Text = "In der Zukunft werden wir im Tempel bleiben und die Priester des Königs werden, um Lemuria zurück zu Gottes Reich zu verwandeln!"
  },
  AvgDialog_47178_Content_98 = {
    Text = "Die Freundlichkeit eines Freundes lindert Miryams Schwäche. Als sie sich zum Gehen bereit macht, wirft sie einen Blick auf die Statue. Die Lichter, die in der Geist-Dimension gesehen werden, überlagern sich mit der Statue."
  },
  AvgDialog_47178_Content_99 = {
    Text = "Eine vage Gestalt saß schräg auf dem Thron, ihr Gesicht von Tentakeln verborgen, die große Macht symbolisieren"
  },
  AvgDialog_47232_Content_1 = {
    Text = "Eingeschränkter Bereich voraus. Unbefugtes Personal darf nicht eintreten. Bitte zeigen Sie Ihren Ausweis."
  },
  AvgDialog_47232_Content_10 = {
    Text = "Möge der Silberschlüssel uns leiten"
  },
  AvgDialog_47232_Content_2 = {
    Text = "Mythag Universität Ermittler, William Draper, Silber Schlüssel ID I-2083."
  },
  AvgDialog_47232_Content_3 = {
    Text = "%player%, K-0617."
  },
  AvgDialog_47232_Content_4 = {
    Text = "Ramona, ich-3017."
  },
  AvgDialog_47232_Content_5 = {
    Text = "Seine Augen sehen aus, als ob er jemanden anstarrt, der dem Tod entgegengeht..."
  },
  AvgDialog_47232_Content_6 = {
    Text = "Die spirituelle Dimension im regionalen d-Effekt-Zone ist chaotisch instabil. Wir müssen oft <Yellow:mehrere spirituelle Kämpfe gleichzeitig führen>, und der psychische Schaden übersteigt bei weitem den physischen."
  },
  AvgDialog_47232_Content_7 = {
    Text = "Viele Ermittler sind verrückt geworden, während sie versucht haben, die Regionale D-Effekt Zone zu unterdrücken. Ressourcen über die Schlachtfelder hinweg ausbalancieren, um das schlimmste Ergebnis zu vermeiden."
  },
  AvgDialog_47232_Content_8 = {
    Text = "Im Rückspiegel zieht der diensthabende Wächter seinen Hut für dich."
  },
  AvgDialog_47232_Content_9 = {
    Text = "Möge der Silberschlüssel unseren Weg erhellen."
  },
  AvgDialog_47798_Content_1 = {
    Text = "Ist es wirklich okay, dass wir uns hier reinschleichen? Das ist Frau Silvias Büro"
  },
  AvgDialog_47798_Content_10 = {
    Text = "Möchtest du es versuchen?"
  },
  AvgDialog_47798_Content_11 = {
    Text = "Murphy nahm ein Stück Milchschokolade, Kopf gesenkt und schweigsam. Der Beratungsraum fiel in eine erschreckende Stille, die dir einen Schauer über den Rücken jagte."
  },
  AvgDialog_47798_Content_12 = {
    Text = "Ist es... Gefällt es dir nicht, Schokolade zu essen? Oder bist du allergisch gegen Kakaobohnen?"
  },
  AvgDialog_47798_Content_13 = {
    Text = "Lass uns ins Schulcafé gehen und etwas anderes finden! Obwohl der Koch zu dieser Stunde nicht da ist, können wir versuchen, etwas selbst zu machen—hmm!"
  },
  AvgDialog_47798_Content_14 = {
    Text = "Bevor du reagieren konntest, wurde dir ein Stück Milchschokolade in den Mund geschoben."
  },
  AvgDialog_47798_Content_15 = {
    Text = "Als sie sich zurückzog, strichen die kalten Polster ihrer Finger über deine Zunge. Im nächsten Moment explodierte ein reichhaltiger Kakaogeschmack in deinem Mund und rutschte deinen Hals hinunter."
  },
  AvgDialog_47798_Content_16 = {
    Text = "Ich habe nie gesagt, dass man nicht essen soll—"
  },
  AvgDialog_47798_Content_17 = {
    Text = "Murphy sagte, während sie die dunkelste Schokolade aus der Geschenkbox nahm. Sie sah äußerst rein aus, ohne zugesetzten Zucker—"
  },
  AvgDialog_47798_Content_18 = {
    Text = "So sauer...! Sauer und bitter..."
  },
  AvgDialog_47798_Content_19 = {
    Text = "Als du siehst, wie ihr Gesicht vor Schmerz verzerrt ist, gibst du ihr schnell ein weiteres Stück Milchschokolade."
  },
  AvgDialog_47798_Content_2 = {
    Text = "Kein Problem. Miss Sylvia hat gesagt, dass ich jederzeit Süßigkeiten aus dem Beratungszimmer nehmen kann"
  },
  AvgDialog_47798_Content_20 = {Text = "D-Danke..."},
  AvgDialog_47798_Content_21 = {
    Text = "Der Beratungsraum ist mit einem vollständigen Teeservice ausgestattet. Sie haben einen Topf leichten Schwarztee aufgebrüht und sich ungezwungen unterhalten."
  },
  AvgDialog_47798_Content_22 = {
    Text = "Bis Murphy das letzte Stück Milchschokolade gegessen und genüsslich seine Finger geleckt hat, wirfst du endlich einen Blick auf die Uhr an der Wand."
  },
  AvgDialog_47798_Content_23 = {
    Text = "Ich werde später auf eine Mission gehen. Ich habe um Mitternacht Süßigkeiten gegessen, also denk daran, dir die Zähne zu putzen, bevor du dich zum Ausruhen hinlegst."
  },
  AvgDialog_47798_Content_24 = {
    Text = "Die Mission ausführen? So spät?"
  },
  AvgDialog_47798_Content_25 = {
    Text = "Liegt es an der Mutation in Remouahe? Die gesamte Mythag-Universität ist in Aufruhr.\nLass uns gehen. Ich bringe dich zuerst zurück zu deinem Zimmer."
  },
  AvgDialog_47798_Content_26 = {
    Text = "Du machst einen Schritt nach vorne, und im nächsten Moment wirst du unerwartet gestolpert und fällst zu Boden."
  },
  AvgDialog_47798_Content_27 = {
    Text = "Ah?! E-Entschuldigung."
  },
  AvgDialog_47798_Content_28 = {
    Text = "Murphy half dir hastig auf. Du blicktest nach unten und sahst einen dunkelroten Tentakel, der fest dein Bein umklammerte."
  },
  AvgDialog_47798_Content_29 = {
    Text = "Das ist ein Teil von Murphys Kleid, oder besser gesagt, ein Teil ihres \"Körpers\"."
  },
  AvgDialog_47798_Content_3 = {
    Text = "Wenn das wahr ist, hätten wir nicht durch das Fenster klettern müssen, oder?"
  },
  AvgDialog_47798_Content_30 = {
    Text = "Musst du wirklich jetzt gehen?"
  },
  AvgDialog_47798_Content_31 = {
    Text = "Aufgrund des Einflusses des Heiligen Flusses von Remouahe sind weltweit Anomalien in den Bereichen aufgetreten."
  },
  AvgDialog_47798_Content_32 = {
    Text = "Das zweite Jahr Ermittlerteam patrouillierte die ganze Nacht. Wir vereinbarten, die Gebietspatrouille im östlichen Bezirk um 8 Uhr morgens zu übernehmen."
  },
  AvgDialog_47798_Content_33 = {
    Text = "Abnormal..."
  },
  AvgDialog_47798_Content_34 = {
    Text = "Ich... Ich fühle... Ich fühle mich auch... ein bisschen seltsam..."
  },
  AvgDialog_47798_Content_35 = {
    Text = "Fühlst du dich unwohl? Hast du Fieber?"
  },
  AvgDialog_47798_Content_36 = {
    Text = "Während du sprichst, ziehst du deine Handschuhe aus und streckst die Hand aus, um ihre Stirn zu fühlen. Murphy tritt plötzlich einen Schritt zurück und weicht deiner Hand aus - doch ihre Tentakeln bleiben um dein Bein gewickelt."
  },
  AvgDialog_47798_Content_37 = {
    Text = "Ich erinnere mich, dass der Fahrer nur eine halbe Stunde braucht, um dich zum Osten zu bringen. Es ist nicht nötig, so früh zu gehen."
  },
  AvgDialog_47798_Content_38 = {
    Text = "Als Belohnung... wird diese junge Dame dich tagsüber bei der Patrouille begleiten..."
  },
  AvgDialog_47798_Content_39 = {
    Text = "Kurz gesagt... bleib einfach bis zur Dämmerung bei mir..."
  },
  AvgDialog_47798_Content_4 = {
    Text = "......macht nichts, schließlich ist Miss Chervilia nicht in der Schule. Um die Auswirkungen des Lemuwashi-Vorfalls zu mildern, ist sie zusammen mit anderen Ermittlern ins Zentrum von Londinium gegangen"
  },
  AvgDialog_47798_Content_5 = {
    Text = "Ich habe es gefunden."
  },
  AvgDialog_47798_Content_6 = {
    Text = "Aus dem Dessertschrank im Beratungsraum hast du eine exquisite Geschenkbox herausgenommen—"
  },
  AvgDialog_47798_Content_7 = {
    Text = "Diese Schokoladenmarke..."
  },
  AvgDialog_47798_Content_8 = {
    Text = "Das goldene Geschenkpapier ist glatt und ordentlich, mit einem silbernen Faden entlang des dekorativen Bandes gestickt, was den hohen Wert dieser Schokoladenschachtel beweist."
  },
  AvgDialog_47798_Content_9 = {
    Text = "Das bittere Aroma von Kakao strömte förmlich heraus, sobald das Band gelöst wurde."
  },
  AvgDialog_47803_Content_1 = {
    Text = "Heh... Ein Hüter aus Mythag, du hast tatsächlich meiner bescheidenen Behausung die Ehre gegeben.\nMeine bescheidene Werkstatt fühlt sich durch deine Anwesenheit geehrt."
  },
  AvgDialog_47803_Content_10 = {
    Text = "Miss Sanga!"
  },
  AvgDialog_47803_Content_11 = {
    Text = "Pssst, pssst... Lass mich einen leisen Blick werfen."
  },
  AvgDialog_47803_Content_12 = {
    Text = "Sie hörte auf, ihr Schnitzmesser zu schwingen, und benutzte die Spitze, um hin und her über dein Gesicht zu reiben."
  },
  AvgDialog_47803_Content_13 = {
    Text = "Wusstest du, dass jeder Künstler eine einzigartige Muse hat?"
  },
  AvgDialog_47803_Content_14 = {
    Text = "Catullus hatte seine Lesbia, Petrarca hatte seine geliebte Laura..."
  },
  AvgDialog_47803_Content_15 = {
    Text = "Diese unermesslichen Augen zeigen keine Spur von Wildheit oder Gewalt; stattdessen sind sie mit unaussprechlichen Emotionen gefüllt—"
  },
  AvgDialog_47803_Content_16 = {
    Text = "Und jetzt habe ich mein eigenes <Blue:Camille>. Würdest du nicht zustimmen, Hüter?"
  },
  AvgDialog_47803_Content_2 = {
    Text = "Du hast die Skulpturmaterialien beiseite geschoben, die neben der Tür gestapelt waren, und dich in Sanga's Studio im Westflügel von Mythag gezwängt."
  },
  AvgDialog_47803_Content_3 = {
    Text = "Die Bildhauerin saß auf einer Korallenbasis, das Schnitzmesser flog zwischen ihren Fingern umher und machte die Zuschauer nervös — das Messer war so scharf, dass es ihr die Finger abschneiden konnte."
  },
  AvgDialog_47803_Content_4 = {
    Text = "Warst nicht du es, der dem diensthabenden Ermittler gesagt hat, dass du mich sehen wolltest?"
  },
  AvgDialog_47803_Content_5 = {
    Text = "Erwachende genießen absolute Freiheit innerhalb der Grenzen der Schulregeln, aber Sanga ist eine Ausnahme—aufgrund der Verbrechen, die sie im Armenhaus begangen hat, darf sie nicht allein handeln."
  },
  AvgDialog_47803_Content_6 = {
    Text = "Ah... In der Tat. Siehst du, es ist der Mangel an Inspiration, der meinen Kopf mit Korallen gefüllt hat"
  },
  AvgDialog_47803_Content_7 = {
    Text = "Bitte komm ein wenig näher, lass mich deine Augen noch einmal sehen... Lass diese arme Seele, die diesen Raum nicht verlassen kann, die Welt durch deine Augen sehen."
  },
  AvgDialog_47803_Content_8 = {
    Text = "Mit einem solch großartigen Grund kannst du keinen Weg finden, ihr abzulehnen, und rückst näher heran—"
  },
  AvgDialog_47803_Content_9 = {
    Text = "Sanga griff plötzlich nach deinem Schulumhang und zog dein Gesicht näher an ihres."
  },
  AvgDialog_47807_Content_1 = {
    Text = "Ein anhaltender Nebel hüllt die Sinne in den Schlaf. Die scheinbar ruhige Dunkelheit verbirgt aufbrandende schwarze Wellen, die gegen die Barrieren des Geistes prallen."
  },
  AvgDialog_47807_Content_10 = {
    Text = "Celeste schwang den Kompass und drückte dich auf das Bett."
  },
  AvgDialog_47807_Content_11 = {
    Text = "Sie zeigte auf den Vollmond draußen am Fenster, dann auf dich—"
  },
  AvgDialog_47807_Content_12 = {
    Text = "...Albtraum."
  },
  AvgDialog_47807_Content_13 = {
    Text = "Solange ich hier bin, wird es keine Alpträume geben."
  },
  AvgDialog_47807_Content_14 = {
    Text = "Dein Atem synchronisiert sich allmählich mit dem sanften Rhythmus, in dem sie die Bettwäsche zurechtrückt, jeder Atemzug wie ein Duett mit dem Wind. Das Bewusstsein beginnt erneut zu schwinden, versinkt in einen weiteren Traum."
  },
  AvgDialog_47807_Content_15 = {
    Text = "Ein weiterer sanfter und weicher Traum, der auf einen ruhigen Morgen zusteuert."
  },
  AvgDialog_47807_Content_2 = {
    Text = "Bis heute setzt der Einfluss des Heiligen Flusses und des riesigen Baumes sein Band mit dir fort."
  },
  AvgDialog_47807_Content_3 = {
    Text = "Die Erinnerungen der Vergangenheit verdichten sich zu zerbrechlichen Blasen in deinen Träumen, die sich bei jeder Bewegung wie Illusionen zerschlagen."
  },
  AvgDialog_47807_Content_4 = {
    Text = "Die chaotische Dunkelheit zieht Sie in die tiefsten Tiefen Ihres Bewusstseins. Gerade als Sie sich selbst in Stücke zerbrechen fühlen, tritt eine schwache Brise in Ihren Traum ein."
  },
  AvgDialog_47807_Content_5 = {
    Text = "Der Wind scheint eine Farbe zu haben, auffällig, aber nicht auffällig. Er ist wie ein schwacher Beschützer, der mit seiner Präsenz beweist, dass du nicht in Träume verloren gehst—"
  },
  AvgDialog_47807_Content_6 = {
    Text = "In dem Moment, als du deine Augen öffnest, triffst du den Blick des \"Traum Hüters\"."
  },
  AvgDialog_47807_Content_7 = {
    Text = "Celeste... Was machst du hier?"
  },
  AvgDialog_47807_Content_8 = {
    Text = "Der stille Erwachte nickte und setzte sich auf die Bettkante, die Matratze senkte sich leicht unter dem Gewicht."
  },
  AvgDialog_47807_Content_9 = {
    Text = "Gibt es ein unerwartetes Problem mit der Mission? Ich bin sofort dort—"
  },
  AvgDialog_47808_Content_1 = {
    Text = "Faros, was schaust du an?"
  },
  AvgDialog_47808_Content_10 = {
    Text = "Faros' Licht flackerte ein paar Mal."
  },
  AvgDialog_47808_Content_11 = {
    Text = "Als ich alt genug war, um an Versammlungen teilzunehmen, war Lemuria bereits von Katastrophen umgeben."
  },
  AvgDialog_47808_Content_12 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47808_Content_13 = {
    Text = "Keeper, würdest du heute Nacht bei mir bleiben?"
  },
  AvgDialog_47808_Content_14 = {
    Text = "Gerade betrachte es als... die Geschichte eines Verrückten, einer Nacht, nur einer Nacht..."
  },
  AvgDialog_47808_Content_2 = {
    Text = "Du entdeckst Faros aus der Ferne; sie ist einfach zu \"auffällig\" bei Nacht. In dem stillen Sandmeer ist sie das einzige Licht, das sich von den Himmelskörpern unterscheidet."
  },
  AvgDialog_47808_Content_3 = {Text = "Keeper."},
  AvgDialog_47808_Content_4 = {
    Text = "Mit ihrer Hilfe erklimmst du die Düne. Der kalte, trockene Wüsten-Nachtwind schlägt dir ins Gesicht und fühlt sich an wie Klingen, die über deine Haut kratzen."
  },
  AvgDialog_47808_Content_5 = {
    Text = "Als Erwacher des Tiefsee-Reichs trug Faros' Kleid immer einen Hauch von Feuchtigkeit. Doch jetzt erscheinen sogar ihre Tentakel leblos aufgrund der Trockenheit."
  },
  AvgDialog_47808_Content_6 = {
    Text = "Ich schaue... auf diesen Fluss."
  },
  AvgDialog_47808_Content_7 = {
    Text = "Es erinnert mich an Lemuria. Mein Heimatland wurde auch von einem großen Fluss wie diesem genährt."
  },
  AvgDialog_47808_Content_8 = {
    Text = "Bevor all die Katastrophen eintrafen, versammelten sich die Jugendlichen jeden Sommerabend am Fluss... um ihre Lebenspartner zu treffen und neue Familien zu gründen."
  },
  AvgDialog_47808_Content_9 = {
    Text = "Klingt so, als ob es lebhaft wird. Und Faros? Hast du an der Sommernachtsparty teilgenommen?"
  },
  AvgDialog_47977_Content_1 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_47977_Content_10 = {
    Text = "Jetzt, um zum Punkt zu kommen. Diese Operation dient der Beobachtung der Scanning-Aktivität des Bewusstseins in \"24\", um sie für zukünftige Heilungen zu verwenden."
  },
  AvgDialog_47977_Content_11 = {
    Text = "Geh nicht dorthin, wo du nicht sein solltest, es sei denn, du möchtest für immer in jemandes Verstand gefangen sein."
  },
  AvgDialog_47977_Content_12 = {
    Text = "Sei nicht faul und schlafe nicht ein!"
  },
  AvgDialog_47977_Content_13 = {
    Text = "<Shake:Mehrere meiner Gefährten sind so verschwunden. Tausende von Jahren sind vergangen, und ich weiß immer noch nicht, ob sie leben oder tot sind...>"
  },
  AvgDialog_47977_Content_14 = {
    Text = "...Ich werde darauf achten."
  },
  AvgDialog_47977_Content_15 = {
    Text = "Keine Sorge, wir werden deinen Zustand und deine Gefühle genau überwachen. Wenn sich etwas ändert, wird die Operation sofort gestoppt."
  },
  AvgDialog_47977_Content_16 = {
    Text = "Bist du bereit, %player%?"
  },
  AvgDialog_47977_Content_17 = {
    Text = "Du schaust auf die kompliziert verbundenen Kammern vor dir. Sie dehnen sich rhythmisch aus und ziehen sich zusammen, ihre geschwollenen Abschnitte steigen und fallen mit jedem Atemzug und erwecken das Bild eines endlosen Ozeans."
  },
  AvgDialog_47977_Content_18 = {
    Text = "Und du, ein einsamer Reisender, der auf dem Deck steht."
  },
  AvgDialog_47977_Content_19 = {Text = "Bereit"},
  AvgDialog_47977_Content_2 = {
    Text = "Erwachen? Befolgen Sie die Anweisungen: Gehen Sie geradeaus für 100 Mikrometer, dann nach rechts, dann nach links, springen Sie hoch und betreten Sie den dritten Ventrikel..."
  },
  AvgDialog_47977_Content_20 = {
    Text = "Lass uns gehen. Sowohl Miss \"24\" als auch wir freuen uns auf deine Ergebnisse."
  },
  AvgDialog_47977_Content_21 = {
    Text = "Gute Reise, Hüter."
  },
  AvgDialog_47977_Content_3 = {
    Text = "Warte, was für ein drittes Ventrikel—<ShakeBig:Ahh, meine Hand?!>"
  },
  AvgDialog_47977_Content_4 = {
    Text = "Du versuchst, dir die Augen zu reiben, nur um festzustellen, dass deine Gliedmaßen zu weichen Synapsen geworden sind, die sanft in einem warmen, roten Ozean treiben."
  },
  AvgDialog_47977_Content_5 = {
    Text = "Hab keine Angst. Winkle hat einige minimale Iterationen basierend auf <Yellow:dem Wandern> vorgenommen. Dein Bewusstsein driftet jetzt im Verstand von \"24\", und alles, was du wahrnimmst, wird zurück an das entfernte Terminal übertragen."
  },
  AvgDialog_47977_Content_6 = {
    Text = "Dein Körper hat sich in einen Kegel verwandelt, und du hast sogar Antennen auf deinem Kopf!"
  },
  AvgDialog_47977_Content_7 = {
    Text = "Berühre nicht! Diese Antennen sind entscheidend für die Wahrnehmung der Umwelt. Auf meinem Heimatplaneten stehen sie für den Status – je länger die Antennen, desto höher der Rang."
  },
  AvgDialog_47977_Content_8 = {
    Text = "Verstanden. Hat Ms. Zwinkern auch lange Tentakeln?"
  },
  AvgDialog_47977_Content_9 = {
    Text = "Uh... D-das versteht sich von selbst!"
  },
  AvgDialog_48091_Content_1 = {Text = "!"},
  AvgDialog_48091_Content_10 = {Text = "...Okay!"},
  AvgDialog_48091_Content_11 = {
    Text = "Nach einer kurzen Ruhepause bemerkst du, dass Lily weiterhin vorsichtig auf deine Brust schielt, als ob sie etwas sagen möchte, aber sich zurückhält."
  },
  AvgDialog_48091_Content_12 = {
    Text = "Aus irgendeinem Grund scheint der glänzende Silber-Schlüssel eine ungewöhnliche Anziehungskraft auf dieses Kind auszuüben."
  },
  AvgDialog_48091_Content_13 = {
    Text = "<Gray:Es sollte in der Schule in Ordnung sein...>"
  },
  AvgDialog_48091_Content_14 = {
    Text = "Du hast einen Moment gezögert, aber hast dennoch den silbernen Schlüssel in ihre zarte Hand gelegt"
  },
  AvgDialog_48091_Content_15 = {
    Text = "So kühl..."
  },
  AvgDialog_48091_Content_16 = {
    Text = "Ist es zu eisig?"
  },
  AvgDialog_48091_Content_17 = {
    Text = "Nein... Es ist kühl und beruhigend..."
  },
  AvgDialog_48091_Content_18 = {
    Text = "Vor langer Zeit, als Lily krank war, hielt ihre Mutter sie und erzählte ihr Gutenachtgeschichten..."
  },
  AvgDialog_48091_Content_19 = {
    Text = "Lasst mich euch erzählen."
  },
  AvgDialog_48091_Content_2 = {
    Text = "Lily legt ihren Kopf auf deine Brust, genau wie an dem Morgen, als du sie zum ersten Mal in Daffodils Laden getroffen hast."
  },
  AvgDialog_48091_Content_20 = {
    Text = "Vor sehr, sehr langer Zeit, in einem fernen Turm, gab es eine Prinzessin mit extrem langen Haaren..."
  },
  AvgDialog_48091_Content_21 = {
    Text = "Du klopfst sanft ihren Rücken und siehst zu, wie sie allmählich in einen friedlichen Schlaf driftet."
  },
  AvgDialog_48091_Content_22 = {Text = "Mutter..."},
  AvgDialog_48091_Content_23 = {
    Text = "Lily liegt in deinen Armen, schläft ruhig und atmet sanft. Du ziehst vorsichtig eine dünne Decke über sie und das kleine Pustelchen."
  },
  AvgDialog_48091_Content_24 = {
    Text = "<Gray:Ich fühle mich auch ein bisschen schläfrig...>"
  },
  AvgDialog_48091_Content_25 = {
    Text = "Aber jetzt ist das Wichtigste, diesen Moment des Glücks für das kleine Mädchen zu schätzen."
  },
  AvgDialog_48091_Content_3 = {
    Text = "Anders als an jenem Tag ist der kleine Körper zusammengekauert, mit rosigen Wangen."
  },
  AvgDialog_48091_Content_4 = {
    Text = "Meister, es scheint, dass Lily Fieber hat."
  },
  AvgDialog_48091_Content_5 = {
    Text = "Ich werde dich ins Krankenhaus schicken."
  },
  AvgDialog_48091_Content_6 = {
    Text = "Lily schüttelte entschieden den Kopf, ein paar Pusteln schwangen wie Ballons, die von einem Jahrmarktverkäufer gehalten wurden, und stießen aneinander."
  },
  AvgDialog_48091_Content_7 = {
    Text = "Lily, keine Injektionen."
  },
  AvgDialog_48091_Content_8 = {
    Text = "So, möchtest du dich hinlegen und ausruhen?"
  },
  AvgDialog_48091_Content_9 = {
    Text = "Du rutschst zur Seite und machst einen kleinen Platz für sie auf dem Bett."
  },
  AvgDialog_48092_Content_1 = {
    Text = "Halte durch, Hüter. Ich habe etwas Entscheidendes mit dir zu besprechen."
  },
  AvgDialog_48092_Content_10 = {
    Text = "Doll zieht deine Hand direkt an ihre Taille."
  },
  AvgDialog_48092_Content_11 = {
    Text = "Nicht genug. Ich muss die Intensität des Verlangens verstärken, um eindringende Gedanken in Echtzeit zu lokalisieren und zu verfolgen.\nMit anderen Worten, hör nicht auf, bis ich es spüre."
  },
  AvgDialog_48092_Content_12 = {
    Text = "Das... scheint nicht ganz angebracht zu sein...?"
  },
  AvgDialog_48092_Content_13 = {
    Text = "Es gibt nichts Unangemesseneres, als abnormalen Gedanken in meinem Kopf nachzuhängen.\nFür dich ist das doch eine seltene Erfahrung, oder nicht?"
  },
  AvgDialog_48092_Content_14 = {
    Text = "Ihre Augen sind auf dich fixiert, sodass du dich wie ein hilfloses Kaninchen fühlst, das von einem Leopard in die Enge getrieben wird."
  },
  AvgDialog_48092_Content_15 = {
    Text = "Nur eine Aufgabe, nur eine Aufgabe..."
  },
  AvgDialog_48092_Content_16 = {
    Text = "Sich überzeugend, drückten Sie Ihre Lippen darauf.\nDie eisige Berührung des Gehirn-Glases ließ Ihnen den Atem stocken."
  },
  AvgDialog_48092_Content_17 = {
    Text = "Flammen flackern in Doll's Pupillen, und du kannst ihren Körper vor Freude zittern spüren."
  },
  AvgDialog_48092_Content_18 = {
    Text = "Gedankeneinbruch wird vollständig durchgeführt."
  },
  AvgDialog_48092_Content_19 = {
    Text = "Als nächstes, ist es Zeit, den Räumungsprozess durchzuführen."
  },
  AvgDialog_48092_Content_2 = {
    Text = "Jemand dringt in meine Gedanken ein."
  },
  AvgDialog_48092_Content_20 = {
    Text = "Lass nicht los, bis der Prozess abgeschlossen ist."
  },
  AvgDialog_48092_Content_3 = {
    Text = "Wie hast du davon erfahren..."
  },
  AvgDialog_48092_Content_4 = {
    Text = "Die Alaemyces-Zivilisation hat körperliche Körper und Fortpflanzungswünsche schon lange aufgegeben. Solche verfallenen Gedanken, die in meinen Geist dringen, müssen auf eine externe Invasion zurückzuführen sein."
  },
  AvgDialog_48092_Content_5 = {
    Text = "Was kann ich für dich tun?"
  },
  AvgDialog_48092_Content_6 = {
    Text = "Komm, umarm mich."
  },
  AvgDialog_48092_Content_7 = {Text = "??"},
  AvgDialog_48092_Content_8 = {
    Text = "Obwohl ich mich etwas unwohl fühlte, folgtest du der Anweisung und umarmtest den kleinen Körper der Puppe. Ihr weiches, gekräuseltes Haar strich über deine Nase und verursachte ein leichtes, kitzelndes Jucken."
  },
  AvgDialog_48092_Content_9 = {
    Text = "Kannst du nicht einmal eine so kleine Aufgabe bewältigen?\nKomm ein wenig näher."
  },
  AvgDialog_48093_Content_1 = {
    Text = "Oh je, lieber Gast, bist du bereit, Pandias Liebkosungen zu empfangen?"
  },
  AvgDialog_48093_Content_10 = {
    Text = "Die Kerze in ihrem Unterbauch brannte ungewöhnlich hell, als wollte sie das Feuer in ihren Augen ebenfalls entzünden, während die ölige Peitsche mit einem Knallen die Luft aus dem Raum zog."
  },
  AvgDialog_48093_Content_11 = {
    Text = "Geht das, Geheimnisträger? Du bist so nah mit den Menschen, dass sie all deine—so viel Liebe~ spüren."
  },
  AvgDialog_48093_Content_12 = {
    Text = "Hmm! Pandia! Pfft, beruhige dich!"
  },
  AvgDialog_48093_Content_13 = {
    Text = "Der verzweifelte Kampf gegen die Wut verschaffte dir einen Hauch von Hoffnung. Hastig spucktest du das Tuch aus und schlossest instinktiv die Augen, bereit, den imaginären Schlägen zu entkommen..."
  },
  AvgDialog_48093_Content_14 = {
    Text = "Aber die Peitsche blieb nur sanft an der Spitze deiner Nase stehen."
  },
  AvgDialog_48093_Content_15 = {
    Text = "Pandias Augen waren verwirrt und verloren den Fokus, während sie ungeduldig und verärgert ihr Gesicht kratzte."
  },
  AvgDialog_48093_Content_16 = {
    Text = "Nein, nein, so fühlt es sich nicht an, was ich will~!"
  },
  AvgDialog_48093_Content_17 = {
    Text = "Soll ich das Gesicht des Schutzherrn schlagen oder ihn mit dem Fuß heftig auf @2 treten? Nein, nein, nein, das ist alles falsch!"
  },
  AvgDialog_48093_Content_18 = {
    Text = "Der gescheiterte Entführer wurde wütend, der Einfluss des Heiligen Flusses ließ sie unruhig mit der Peitsche herumfuchteln."
  },
  AvgDialog_48093_Content_19 = {
    Text = "Warum hat man bei der Vorstellung des Schutzherrn @2 und @2 überhaupt nicht die heiße, brennende Süße gespürt?"
  },
  AvgDialog_48093_Content_2 = {
    Text = "Es scheint, dass Sie endlich verstanden haben, dass Schmerz zu genießen, die Voraussetzung ist, Liebe zu genießen"
  },
  AvgDialog_48093_Content_20 = {
    Text = "Der Kampf mit dem Seil war nicht erfolgreich, dein Gehirn hat vollständig aufgehört zu funktionieren und beginnt automatisch stumpfe, kalte Witze auszuspeien."
  },
  AvgDialog_48093_Content_21 = {
    Text = "Wenn es sich für dich nicht richtig anfühlt, mich zu schlagen, wie wäre es, wenn ich dich schlage?"
  },
  AvgDialog_48093_Content_22 = {
    Text = "Du hast nicht einmal die Gelegenheit gehabt, deine Zunge für diesen Satz zu schlucken, als Pandias Pupillen plötzlich weit aufgerissen wurden."
  },
  AvgDialog_48093_Content_23 = {
    Text = "Stimmt! Warum ist mir das nicht eingefallen? Was sie wirklich ~ wirklich, wirklich begehrt...!"
  },
  AvgDialog_48093_Content_24 = {
    Text = "Ihr Körper begann leicht zu zittern, weil sie extrem begeistert war."
  },
  AvgDialog_48093_Content_25 = {
    Text = "Außer der Kerze, die immer noch in ihr brennend leuchtet, sind alle Lichter im Raum erloschen."
  },
  AvgDialog_48093_Content_26 = {
    Text = "Im Mondlicht drehte das Mädchen den Griff der Peitsche und biss in ihr Lederpeitsche. Ihre Stimme wurde dickflüssig und verschwommen, wie Zuckerguss, der darauf wartet, gekostet zu werden... oder eine Art schwere, feuchte, kalte Dunkelheit."
  },
  AvgDialog_48093_Content_27 = {
    Text = "Ein dumpfer Schlag, das Seil, das deinen Arm fesselte, fiel zu Boden."
  },
  AvgDialog_48093_Content_28 = {
    Text = "Bestrafe mich, peitsche mich, misshandle mich..."
  },
  AvgDialog_48093_Content_29 = {
    Text = "So wie man anderen Menschen etwas schenkt, schenke auch den süßen Schmerz~!"
  },
  AvgDialog_48093_Content_3 = {
    Text = "Kleine Peitsche~ Kleine Peitsche~ Wo bist du~"
  },
  AvgDialog_48093_Content_4 = {
    Text = "Hey, lauf nicht weg!"
  },
  AvgDialog_48093_Content_5 = {
    Text = "(Woher kommt es, dass du meinen Mund blockierst!)"
  },
  AvgDialog_48093_Content_6 = {
    Text = "Im Bildungssystem von Misaq hat kein Kurs gelehrt, wie man in einer solchen Situation mit einem physisch “brennenden“ Erwecker umgeht."
  },
  AvgDialog_48093_Content_7 = {
    Text = "Und sie hat bereits fast ihren mit Wachsöl ähnlichen, glatten Oberschenkel vollständig auf deine Brust gedrückt."
  },
  AvgDialog_48093_Content_8 = {
    Text = "(Pandia, wenn du nicht aufstehst, werde ich vor dem Ersticken wegen deiner Begeisterung zuerst wegen deines Gewichts ersticken.)"
  },
  AvgDialog_48093_Content_9 = {
    Text = "Du versuchst, diese komplexe Nachricht mit deinem Blick zu übermitteln, aber offensichtlich ist die Aufmerksamkeit des Mädchens überhaupt nicht darauf gerichtet, deine Überlebenschancen zu erhöhen."
  },
  AvgDialog_48094_Content_1 = {
    Text = "Aigis? Andere sagen, du hast dich seit drei Tagen in deinem Zimmer eingeschlossen."
  },
  AvgDialog_48094_Content_10 = {
    Text = "Es ist okay, es ist nicht Aigis's Schuld..."
  },
  AvgDialog_48094_Content_11 = {
    Text = "Du tröstest sie, während du dich näherst, Lösungen blitzen schnell durch deinen Kopf—"
  },
  AvgDialog_48094_Content_12 = {
    Text = "Komm nicht näher! Du wirst verletzt..."
  },
  AvgDialog_48094_Content_13 = {
    Text = "Es ist in Ordnung. Ich bin der einzige Hüter. Aigis konnte mich im Armenhaus nicht in Stein verwandeln, oder?"
  },
  AvgDialog_48094_Content_14 = {
    Text = "Um den ungewöhnlichen Emotionen der Erwacher eine \"Freisetzung\" zu ermöglichen, muss Aigis angeleitet werden, ihre Augen zu öffnen—"
  },
  AvgDialog_48094_Content_15 = {
    Text = "Das junge Mädchen zitterte, ihre Augen öffneten sich einen Spalt— aber im nächsten Moment sickerte klebriger, bräunlich-gelber Sirup aus ihrer freiliegenden Haut."
  },
  AvgDialog_48094_Content_16 = {
    Text = "Waaah!! Schutzherr!!"
  },
  AvgDialog_48094_Content_17 = {
    Text = "Sob... Es ist ganz Aigis' Schuld... Aigis hätte ihre Augen nicht öffnen sollen..."
  },
  AvgDialog_48094_Content_18 = {
    Text = "Es ist in Ordnung, es ist nur eine Schicht Zucker. Sieh, es gibt jetzt kein Problem mehr."
  },
  AvgDialog_48094_Content_19 = {
    Text = "Aigis blinzelte, fühlte ein Brennen in ihrem Hals und bewegte zögernd ihren Mund."
  },
  AvgDialog_48094_Content_2 = {
    Text = "Du klopfst an die Tür des Mädchens und hörst sofort etwas umfallen — wie Steine, die auf den Boden treffen und in unzählige Stücke zerbrechen."
  },
  AvgDialog_48094_Content_20 = {
    Text = "Der Klang ist zu leise, Aigis."
  },
  AvgDialog_48094_Content_21 = {Text = "Ugh..."},
  AvgDialog_48094_Content_22 = {
    Text = "Könntest du bitte heiße Schokolade für Aigis holen? Nur ein Schluck kann ihre Krankheit heilen... Das hat mir Miss Sarah gesagt."
  },
  AvgDialog_48094_Content_3 = {
    Text = "Was ist das für ein Geräusch? Aigis, ich komme rein."
  },
  AvgDialog_48094_Content_4 = {
    Text = "Als du die Tür aufdrücktest, fühltest du keinen erwarteten Widerstand. Instinktiv blicktest du zurück: das Schloss war zu dünnem, brüchigem Stein geworden und zerbrach überall auf den Boden durch deine Bewegung."
  },
  AvgDialog_48094_Content_5 = {
    Text = "S-Schutzherr... Mir geht's gut... Aigis geht es gut..."
  },
  AvgDialog_48094_Content_6 = {
    Text = "Aigis saß in der Mitte des Raumes, der römischen Ruinen ähnelte, mit fest geschlossenen Augen."
  },
  AvgDialog_48094_Content_7 = {
    Text = "Ai, Aigis scheint Fieber zu haben... Ihre großen Augen gehorchen ihr nicht mehr, und alles, was sie ansieht, verwandelt sich in Stein..."
  },
  AvgDialog_48094_Content_8 = {
    Text = "Fieber, ein weiterer Fall von unbekanntem Fieber von einem Erwachenden."
  },
  AvgDialog_48094_Content_9 = {
    Text = "Du verstehst: es ist wieder der Einfluss des Lemwash-Ereignisses."
  },
  AvgDialog_48095_Content_1 = {
    Text = "1 Anhang, 3 Kuhmägen, 16 Zähne verschiedener Arten und ein großer Haufen gebrochener Knochen..."
  },
  AvgDialog_48095_Content_10 = {
    Text = "Uvhash präsentierte dir stolz einen glänzenden Unterkiefer. Im Mondlicht leuchteten die Lücken zwischen seinen Zähnen mit einem unheimlichen grünen Licht."
  },
  AvgDialog_48095_Content_11 = {
    Text = "Wie ist das? Lustig, oder? Hahaha!!"
  },
  AvgDialog_48095_Content_12 = {
    Text = "<Shake:Ughhhh—!!>"
  },
  AvgDialog_48095_Content_13 = {
    Text = "Du schlägst gewaltsam die Hand von Youwu weg. Der Kieferfall fällt versehentlich zu Boden und zerbricht sofort in zwei Stücke."
  },
  AvgDialog_48095_Content_14 = {
    Text = "@3! Ich konnte es kaum von dieser Dienerin kaufen..."
  },
  AvgDialog_48095_Content_15 = {
    Text = "Eine Magd? Könnte es Karen sein...? Wie viel hast du ausgegeben?"
  },
  AvgDialog_48095_Content_16 = {
    Text = "Ich kenne ihren Namen nicht, nur ein grünes Wesen. Es hat etwa 100 Leo Fang gekostet."
  },
  AvgDialog_48095_Content_17 = {
    Text = "Sie sagte, es sei ein erhabener Schatz aus der 108. Dynastie von Lemwasi."
  },
  AvgDialog_48095_Content_18 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_48095_Content_19 = {
    Text = "Du wurdest getäuscht. Die Lemwasi-Dynastie dauerte nur bis zur 30. Generation, und diese Knochen müssen zusammengesetzt worden sein; andernfalls würden sie nicht so leicht brechen."
  },
  AvgDialog_48095_Content_2 = {
    Text = "Du wirfst einen blutbefleckten Sack hart vor Youwu."
  },
  AvgDialog_48095_Content_20 = {
    Text = "Wie wagst du es, mich zu täuschen... Heh. Gib mir zehn Minuten; ich werde diesen grünhaarigen Wahnsinnigen umbringen."
  },
  AvgDialog_48095_Content_21 = {
    Text = "Warte, Uvhash."
  },
  AvgDialog_48095_Content_22 = {
    Text = "Du hebst die Fragmente vom Boden auf und legst sie sanft in Youwus Hand."
  },
  AvgDialog_48095_Content_23 = {
    Text = "Danke für das Geschenk. Bitte fragt das nächste Mal jedoch nach meiner Meinung, bevor ihr mir etwas gebt."
  },
  AvgDialog_48095_Content_24 = {
    Text = "Uvhash senkte den Kopf, seine überragende Gestalt blockierte das Mondlicht hinter ihm und erinnerte an einen sanften Löwen."
  },
  AvgDialog_48095_Content_25 = {
    Text = "Ich dachte, du würdest es mögen. Ich kann deutlich die Präsenz eines verwandten Geistes in dir spüren, besonders in den letzten Tagen —"
  },
  AvgDialog_48095_Content_26 = {
    Text = "Selbst Mitglieder derselben Art können nicht genau die gleichen Dinge mögen. Wenn du so denkst, bedeutet das, dass wir uns nicht gut genug kennen, oder?"
  },
  AvgDialog_48095_Content_27 = {
    Text = "Uvhash runzelt unruhig die Stirn. Dies ist keine vertraute Gesprächsatmosphäre für ihn."
  },
  AvgDialog_48095_Content_28 = {
    Text = "...Oh. Dann sag mir etwas, das dir gefällt."
  },
  AvgDialog_48095_Content_29 = {
    Text = "<SmallItalic:Eine Sache, die ich mag... Sams Bäckerei in der Lincoln High Street hat guten Zitronenkuchen. Achte darauf, dass sie extra Glasur und Pudding drauftut. Einfach nicht zu viel Sahne, sonst beschwert sich Ramona...>"
  },
  AvgDialog_48095_Content_3 = {
    Text = "Wenn ich mich gestern nicht geirrt habe, warst du es, der in mein Zimmer geschlichen ist und Sachen durcheinander geworfen hat."
  },
  AvgDialog_48095_Content_30 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_48095_Content_31 = {
    Text = "In Ordnung, ich werde es für dich kaufen. Aber zuerst muss ich die Rechnung mit diesem grünhaarigen Monster klären, das es gewagt hat, sich mit mir anzulegen..."
  },
  AvgDialog_48095_Content_32 = {
    Text = "Tut, was ihr beiden wollt, aber verursacht keine Tode."
  },
  AvgDialog_48095_Content_33 = {
    Text = "Uvhash ging wütend zum Fenster, erinnerte sich dann plötzlich an etwas und sah äußerst unnatürlich aus."
  },
  AvgDialog_48095_Content_34 = {
    Text = "Pass auf dich auf... Ich komme morgen vorbei, um dich zu sehen."
  },
  AvgDialog_48095_Content_35 = {
    Text = "Nachdem er das gesagt hatte, sprang er und seine schlanke Gestalt verschwand im Mondlicht."
  },
  AvgDialog_48095_Content_36 = {
    Text = "Bis morgen, Uvhash."
  },
  AvgDialog_48095_Content_37 = {
    Text = "Mein Wohnheim hat eine Tür, <Big:Bitte benutze beim nächsten Mal den Haupteingang—!!>"
  },
  AvgDialog_48095_Content_4 = {
    Text = "Uvhash, hast du eine Erklärung dafür?"
  },
  AvgDialog_48095_Content_5 = {Text = "...Hmph."},
  AvgDialog_48095_Content_6 = {
    Text = "Dank dir will niemand in der Nähe meines Wohnheims sein. Ich rieche jetzt wie fauliger Kohl."
  },
  AvgDialog_48095_Content_7 = {
    Text = "Es scheint, dass du die Geschenke, die ich dir gegeben habe, nicht magst. Hehe, ich dachte, wir hätten ähnliche Geschmäcker..."
  },
  AvgDialog_48095_Content_8 = {
    Text = "<Gray:Vater im Himmel, was habe ich getan, um ihn so missverstanden zu lassen?>"
  },
  AvgDialog_48095_Content_9 = {
    Text = "Würdest du nicht in Betracht ziehen, diesen Kieferknochen zu behalten? Es gibt nachts eine Überraschung für dich."
  },
  AvgDialog_48096_Content_1 = {
    Text = "Seufze, Doll hat wieder überzogen. Die nächste Klasse ist im Gebäude F. Was sollen wir jetzt tun?"
  },
  AvgDialog_48096_Content_10 = {
    Text = "Solange du einbezogen bist, solange du zu allem hinzugefügt wirst, bleibt die schwarze Katastrophe fern, fern weg. Wir müssen zusammenbleiben; sonst werden schlimme Dinge geschehen - schwarze Dinge."
  },
  AvgDialog_48096_Content_11 = {
    Text = "Helle, helle, helle Seele... Du strahlst so hell... Es muss sehr sicher um dich herum sein..."
  },
  AvgDialog_48096_Content_12 = {
    Text = "Ihre fragmentierten Murmeln gleiten an deinen Ohren vorbei, aber du kannst ihnen nicht mehr Beachtung schenken, denn—"
  },
  AvgDialog_48096_Content_13 = {
    Text = "Zwinkern, lass los! Die Schulglocke läutet. Ich werde zu spät kommen! <BigShake:Zwinkern!>"
  },
  AvgDialog_48096_Content_2 = {Text = "<Big:Ah!>"},
  AvgDialog_48096_Content_3 = {
    Text = "Die enorme Kraft von hinten lässt dich taumeln und fast fallen."
  },
  AvgDialog_48096_Content_4 = {
    Text = "Winkle? Was ist das...?"
  },
  AvgDialog_48096_Content_5 = {
    Text = "Es tut mir leid, es tut mir leid, es tut mir leid! Ich... ich wollte das nicht! Ich muss einfach bei dir sein, ich muss..."
  },
  AvgDialog_48096_Content_6 = {
    Text = "...Zwinkern?"
  },
  AvgDialog_48096_Content_7 = {
    Text = "Ich plane, die @3-Formel und die @1@4-Vermutung zu verwenden, um die Distanz zwischen der schwarzen Katastrophe und uns zu berechnen, aber ich bekomme es einfach nicht hin, egal was ich tue..."
  },
  AvgDialog_48096_Content_8 = {
    Text = "Schließlich wurde mir klar, dass ich eine Variable übersehen hatte — die hellste Seele —"
  },
  AvgDialog_48096_Content_9 = {
    Text = "Das bist du!"
  },
  AvgDialog_48139_Content_1 = {Text = "—Spritz."},
  AvgDialog_48139_Content_10 = {
    Text = "Wenn es um Hilfe geht, kannst du direkt nach Mythag kommen, um mich zu finden—huh?!"
  },
  AvgDialog_48139_Content_11 = {
    Text = "Sie umschließt mit einer Hand deinen Hals, ihr umliegender Schleim verwandelt sich in scharfe Klingen, die deinen Uniformkragen aufschneiden. Der Klingenrand drückt gegen deinen Hals und macht jeden Atemzug gefährlich."
  },
  AvgDialog_48139_Content_12 = {
    Text = "Shh... Sei ruhig. Diese Sporenwesen dürfen nicht erschreckt werden."
  },
  AvgDialog_48139_Content_13 = {
    Text = "Ein Finger drückt gegen deine Lippen. Auf Helots Signal siehst du dir die Beule hinter ihr an—"
  },
  AvgDialog_48139_Content_14 = {
    Text = "Diese neu entstandenen Pusteln haben sich abgespalten, aber ihnen fehlt das Selbstbewusstsein... Sie können mir bei meiner Rache nicht helfen."
  },
  AvgDialog_48139_Content_15 = {
    Text = "Nicht selbstbewusst genug?"
  },
  AvgDialog_48139_Content_16 = {
    Text = "Die Pusteln sind ungewöhnlich aktiv und klammern sich jetzt an deine Füße und erzeugen quitschende Geräusche, während sie kollidieren."
  },
  AvgDialog_48139_Content_17 = {
    Text = "Nicht genug, also brauche ich deine Hilfe."
  },
  AvgDialog_48139_Content_18 = {Text = "Ich?"},
  AvgDialog_48139_Content_19 = {
    Text = "Helot packt dich kraftvoll, drückt deine Hand gegen ihren entblößten Oberschenkel. Das klebrige Gefühl gleitet lautlos in ihren offenen Kragen."
  },
  AvgDialog_48139_Content_2 = {
    Text = "Die Bewegung des Aufstehens zog an den Ketten, wodurch das Geräusch von klirrendem Metall in der Dunkelheit widerhallte."
  },
  AvgDialog_48139_Content_20 = {
    Text = "Hey?! Helot, was hast du vor?!"
  },
  AvgDialog_48139_Content_21 = {
    Text = "Sie gleiten feucht über jede Hautstelle, wie Wasser, das in ein Flussbett fließt, und umreißen die Konturen der Muskeln nach unten."
  },
  AvgDialog_48139_Content_22 = {
    Text = "Ihr Meister umgreift Ihre Hand, ihre blutroten Augen brennen intensiv, als wären sie kurz davor, auszulöschen."
  },
  AvgDialog_48139_Content_23 = {
    Text = "Verwende deinen Verstand, um ihnen wahres \"Bewusstsein\" zu verleihen."
  },
  AvgDialog_48139_Content_3 = {
    Text = "Du bist wach. Es gibt keine Zeit zu verlieren, lass uns anfangen."
  },
  AvgDialog_48139_Content_4 = {
    Text = "Diese Stimme... Helot?! Was machst du? Ich dachte, wir hätten diese Missverständnisse ausgeräumt."
  },
  AvgDialog_48139_Content_5 = {
    Text = "Was ist jetzt los mit dem Festbinden hier?"
  },
  AvgDialog_48139_Content_6 = {
    Text = "In der Tat... es gibt keinen Interessenkonflikt mehr zwischen uns."
  },
  AvgDialog_48139_Content_7 = {
    Text = "Helot kniet vor dir und nutzt den Schleim, um die Ketten, die deine Beine binden, zu korrodieren."
  },
  AvgDialog_48139_Content_8 = {
    Text = "Du bist frei, aber denk nicht ans Entkommen. Diese Untergrundbahn wurde nach unserem Kampf aufgegeben, und du wirst keine Hilfe finden."
  },
  AvgDialog_48139_Content_9 = {
    Text = "Ich brauche dich, um mir einen Gefallen zu tun."
  },
  AvgDialog_48142_Content_1 = {
    Text = "Sie haben sich wertvolle Zeit aus Ihrem vollen Terminplan genommen, um zur Großen Kirche zu kommen. Diese Freundlichkeit werde ich nie in meinem Leben vergessen."
  },
  AvgDialog_48142_Content_10 = {
    Text = "......Ich verstehe.\nDer Zusammenbruch des Heiligen Baumes von Remouahe hat weltweit starke Reaktionen unter den Erwachten ausgelöst..."
  },
  AvgDialog_48142_Content_11 = {
    Text = "*Hust* *Hust*, intensiv..."
  },
  AvgDialog_48142_Content_12 = {
    Text = "So ist es. Es ist das \"Verlangen nach Verbreitung\", beeinflusst von Anomalien, das mich ruft."
  },
  AvgDialog_48142_Content_13 = {
    Text = "Entschuldigung, ich habe die Fassung verloren."
  },
  AvgDialog_48142_Content_14 = {
    Text = "...Nein, das ist es nicht. Ich...ich vergebe deine Sünden. Ist es okay, das zu sagen?"
  },
  AvgDialog_48142_Content_15 = {
    Text = "Es war mein Versehen; du hast keine Erfahrung mit Beichten."
  },
  AvgDialog_48142_Content_16 = {
    Text = "Salvador öffnete das kleine Fenster des Beichtstuhls, legte seine Hände mit den Handflächen nach oben auf das Fensterbrett zu dir."
  },
  AvgDialog_48142_Content_17 = {
    Text = "Wenn du kannst, halte bitte meine Hand."
  },
  AvgDialog_48142_Content_18 = {
    Text = "(Beide Hände ausstrecken)"
  },
  AvgDialog_48142_Content_19 = {
    Text = "Auch mit Handschuhen kannst du seine abnormale Körpertemperatur nicht blockieren. Wie die Flammen, die aus einer kochenden Seele aufsteigen, brennt sie unwiderstehlich durch deine Adern."
  },
  AvgDialog_48142_Content_2 = {
    Text = "Natürlich, solange ich Bischof Salvador helfen kann..."
  },
  AvgDialog_48142_Content_20 = {
    Text = "Der silberne Schlüssel auf deiner Brust brennt, schält Schichten deiner Seele ab und lässt nur den nackten, freigelegten Kern zurück."
  },
  AvgDialog_48142_Content_21 = {
    Text = "Als nächstes, bitte wiederhole, was ich sage."
  },
  AvgDialog_48142_Content_22 = {
    Text = "Sünde ist wie eine Fessel, aber der Schlüssel zur Vergebung und Erlösung liegt auch innerhalb der Fessel."
  },
  AvgDialog_48142_Content_23 = {
    Text = "Sünde ist wie eine Fessel, aber der Schlüssel zur Vergebung und Erlösung liegt auch innerhalb der Fessel."
  },
  AvgDialog_48142_Content_24 = {
    Text = "Sein Herz, verzehrt von der Qual der Tugend, hat die bitteren Früchte gekostet."
  },
  AvgDialog_48142_Content_25 = {
    Text = "Durch die Qual der Tugend verbraucht, hat er die bittere Frucht gekostet..."
  },
  AvgDialog_48142_Content_26 = {
    Text = "Ein Blitz der Inspiration durchzuckte deinen Geist und verband die Worte in deinem Kopf. Bevor Salvador weitermachen konnte, trieb dich dein Instinkt dazu, zuerst zu sprechen."
  },
  AvgDialog_48142_Content_27 = {
    Text = "... Barmherziger Vater, gewähre ihm bitte das Licht, um zu gehen, und vergib ihm seine Sünden."
  },
  AvgDialog_48142_Content_28 = {
    Text = "Du hast auch die Führung des Vaters gehört..."
  },
  AvgDialog_48142_Content_29 = {
    Text = "Blaser Bote, danke, dass du meine Dunkelheit einmal mehr vertreibt."
  },
  AvgDialog_48142_Content_3 = {
    Text = "Die Beichte ist düster und eng. Du sitzt unruhig auf dem Eichenstuhl, aber deine \"Neugierde\" darüber, warum du hierher gerufen wurdest, überwiegt bei weitem deine Angst."
  },
  AvgDialog_48142_Content_4 = {
    Text = "Normalerweise ist Salvador derjenige im Beichtstuhl. Wenn er dich hier in der Großen Kirche hat sitzen lassen, muss es einen besonderen Grund geben."
  },
  AvgDialog_48142_Content_5 = {
    Text = "Bitte erlaube mir, die Formalitäten zu überspringen, Das Blasse Feuer, und meiner Beichte zuzuhören."
  },
  AvgDialog_48142_Content_6 = {
    Text = "In letzter Zeit habe ich... aus irgendeinem Grund ein unangemessenes Verlangen verspürt."
  },
  AvgDialog_48142_Content_7 = {
    Text = "Seine Stimme hallte wie die fernen Berge, drang langsam in die antiken Holzwände der Beichtstube ein und durchdrang sie. Der tiefen Ton hielt ein namenloses Biest zurück, aus Angst, es könnte das unsichtbare Tabu berühren."
  },
  AvgDialog_48142_Content_8 = {
    Text = "Ich muss zugeben, obwohl ich diese Wünsche kenne, habe ich sie nie wirklich erlebt, noch verstehe ich, wie sie den Ruhm des Vaters überschattet und mein Herz befleckt."
  },
  AvgDialog_48142_Content_9 = {
    Text = "Jedoch, ebenso wie ein Heiler Heilung benötigt, könnte ich, der Beauftragte, auch gestehen müssen, um Rat und Vergebung vom Boten des Vaters zu erhalten."
  },
  AvgDialog_48238_Content_1 = {
    Text = "Fühlst du dich etwas besser, Liz?"
  },
  AvgDialog_48238_Content_10 = {
    Text = "Eine Hand streckt sich von der Bühne aus, graziös zu dir hin."
  },
  AvgDialog_48238_Content_11 = {
    Text = "Ich? Aber ich habe nie... Hey..."
  },
  AvgDialog_48238_Content_12 = {
    Text = "Bevor du den Satz beenden konntest, zog diese Hand dich ohne Zögern auf die Bühne."
  },
  AvgDialog_48238_Content_13 = {
    Text = "...Bitte halte mich an der Taille, Hüter."
  },
  AvgDialog_48238_Content_14 = {
    Text = "Ich kann immer noch nicht tanzen, aber ich glaube, ich kann dir diese schönen Bewegungen beibringen."
  },
  AvgDialog_48238_Content_15 = {
    Text = "Du hast gesagt, du würdest mir helfen, mit dem Einfluss des Heiligen Flusses umzugehen, nicht wahr"
  },
  AvgDialog_48238_Content_16 = {
    Text = "In dem Moment, als diese Hand deine zur Taille führte, zitterte der wohlgeformte Körper leicht."
  },
  AvgDialog_48238_Content_17 = {
    Text = "Die Fingerkuppen fühlen die kühle Berührung von Seide. Unter der Seide hebt und senkt sich eine weiche und feste Taille sanft mit jedem Atemzug."
  },
  AvgDialog_48238_Content_18 = {
    Text = "Ich hatte nie Kontakt mit Ballett... Kann ich das wirklich schaffen?"
  },
  AvgDialog_48238_Content_19 = {
    Text = "Folge der Musik und tu, was du willst."
  },
  AvgDialog_48238_Content_2 = {
    Text = "Im verlassenen Theater schüttelte das Mädchen den Kopf. Du hörst ihr unregelmäßiges Atmen und siehst ihre leicht geröteten Wangen im schummrigen Licht."
  },
  AvgDialog_48238_Content_20 = {
    Text = "Erinnere dich, das Geheimnis des Balletts ist das Drehen."
  },
  AvgDialog_48238_Content_21 = {
    Text = "Von den Händen bis zur Taille, von der Taille bis zu den Beinen. Die Tänzerin führt dich durch jede anmutige Bewegung und ermöglicht dir, die subtilen Veränderungen in jedem Teil ihres Körpers zu spüren."
  },
  AvgDialog_48238_Content_22 = {
    Text = "Tritt. Biege. Springe."
  },
  AvgDialog_48238_Content_23 = {
    Text = "Ethereale Musik hallt im leeren Theater, ein kalter Lichtstrahl folgt dir auf die Bühne."
  },
  AvgDialog_48238_Content_24 = {
    Text = "Du drehst zusammen. Liz' Gesicht wird röter, ihre grünen Augen schauen schüchtern zu dir."
  },
  AvgDialog_48238_Content_25 = {
    Text = "Wie war mein Sprung?"
  },
  AvgDialog_48238_Content_26 = {
    Text = "Nutzlos. Aber dies wird meine Lieblingsaufführung, Hüter."
  },
  AvgDialog_48238_Content_27 = {
    Text = "Sollen wir uns ein wenig verlangsamen? Ich fühle mich ein wenig..."
  },
  AvgDialog_48238_Content_28 = {
    Text = "Die grünen Augen schlossen sich sanft, und die kalten Lippen küssten dich."
  },
  AvgDialog_48238_Content_29 = {
    Text = "Drehe dich. Drehe dich."
  },
  AvgDialog_48238_Content_3 = {
    Text = "Ich dachte, das Theater könnte dich beruhigen und den Einfluss des Heiligen Flusses beseitigen."
  },
  AvgDialog_48238_Content_30 = {
    Text = "Weisse Haare wehen im Wind, eingehüllt von smaragdgrünen Flammen, die keine Wärme tragen, tanzend zur Musik. Das schwarz-grüne Tanzoutfit zeichnet einen schwanenartigen Bogen in die Luft."
  },
  AvgDialog_48238_Content_31 = {
    Text = "Betäubt. Du meinst \"betäubt.\""
  },
  AvgDialog_48238_Content_32 = {
    Text = "Liz's immer schwerere Atemzüge streifen dein Gesicht. Instinktiv ziehst du deine Arme um ihre Taille fester, was sie leicht zusammenziehen lässt. Ihr dreht euch zusammen."
  },
  AvgDialog_48238_Content_33 = {
    Text = "Erinnere dich, Hüter. Das Geheimnis des Balletts ist der Dreh..."
  },
  AvgDialog_48238_Content_34 = {
    Text = "Heute Abend, im Schein des Theaters, verliert ein Paar Tänzer sich im Wirbel."
  },
  AvgDialog_48238_Content_4 = {
    Text = "Vielleicht könnte ich etwas anderes tun, um mich abzulenken. Lass mich nachdenken..."
  },
  AvgDialog_48238_Content_5 = {
    Text = "Grüne Augen blitzen, ein schwarzer Rock schwingt in einem Bogen vor dir und das Mädchen betritt geschickt die Bühne."
  },
  AvgDialog_48238_Content_6 = {
    Text = "Ich dachte, du hättest immer noch einen Groll gegen das Tanzen..."
  },
  AvgDialog_48238_Content_7 = {
    Text = "Ich habe nie gesagt, ich würde springen."
  },
  AvgDialog_48238_Content_8 = {
    Text = "Also, was meinst du...?"
  },
  AvgDialog_48238_Content_9 = {
    Text = "Lass mich dir beibringen, wie man tanzt, Hüter."
  },
  AvgDialog_48555_Content_1 = {
    Text = "Als ich eine weitere Ecke im Schulgebäude umging, wird die erdrückende Atmosphäre, die seit heute Morgen auf dir lastet, schwerer, sodass es fast unmöglich ist zu atmen."
  },
  AvgDialog_48555_Content_10 = {
    Text = "Die Kugel strahlt ein schwaches Licht aus deiner Handfläche aus und pulsiert mit immensen Lebenskräften."
  },
  AvgDialog_48555_Content_11 = {
    Text = "Innerhalb der durchsichtigen Sakwandfalten falten sich flügelähnliche Äste zusammen und flattern gelegentlich, als ob sie in einem langen, endlosen Traum wären."
  },
  AvgDialog_48555_Content_12 = {
    Text = "Was ist das...?"
  },
  AvgDialog_48555_Content_13 = {
    Text = "Faint seufzte erleichtert, als ein zufriedenes Lächeln auf ihrem Gesicht erschien, als du ihr Geschenk nicht abgelehnt hast."
  },
  AvgDialog_48555_Content_14 = {
    Text = "Dies ist die neue Züchtung unseres @2 Clans. Jeder reife Mitglied von uns wird solche Früchte tragen."
  },
  AvgDialog_48555_Content_15 = {
    Text = "So lange, so lange sprießte ich nie... Ich dachte, ich würde niemals ein vollständiges @2 werden."
  },
  AvgDialog_48555_Content_16 = {
    Text = "<Small:Abnormales Wachstum... verursacht durch Lemwash.>"
  },
  AvgDialog_48555_Content_17 = {
    Text = "Wie fühlt sich Ohnmacht jetzt? Hat dein Körper nach dem Sprießen noch andere Anomalien erfahren?"
  },
  AvgDialog_48555_Content_18 = {
    Text = "Faint schüttelte den Kopf, ihr jugendliches Gesicht strahlte vor Freude."
  },
  AvgDialog_48555_Content_19 = {
    Text = "So heiß... Mein Kopf und meine Glieder fühlen sich so heiß an. Vielleicht ist das, was Tinct meinte, wenn sie von Erwachsenwerden spricht?"
  },
  AvgDialog_48555_Content_2 = {
    Text = "Du hockst gegen die Wand und wirfst einen Blick auf einen vertrauten Schatten, der vorbeizieht."
  },
  AvgDialog_48555_Content_3 = {
    Text = "...Ohnmacht? Bist das du?"
  },
  AvgDialog_48555_Content_4 = {
    Text = "Der weiße Schatten hielt kurz inne, dann hörte er auf, seine Präsenz zu verbergen. Der weiße Rahmen, der seinen Meister trug, schwebte vor dir."
  },
  AvgDialog_48555_Content_5 = {Text = "...Hüter."},
  AvgDialog_48555_Content_6 = {
    Text = "Sie streckt die Hand nach dir aus, scheint aus der \"Wiege\" herauskriechen zu wollen – aber dieses Verlassen des Einsperrers würde nur ihre Instinkte wilder machen."
  },
  AvgDialog_48555_Content_7 = {
    Text = "Ohnmacht bemerkte schnell ihre Anomalie, also presste sie nur ihre Lippen zusammen und drehte die nächstgelegene Glühbirne auf dem \"Wiege\" neben ihrem Körper ab."
  },
  AvgDialog_48555_Content_8 = {
    Text = "Bitte... nimm das an."
  },
  AvgDialog_48555_Content_9 = {
    Text = "Du greifst nach, und deine Fingerspitzen berühren ihre weiche Handfläche, während du den Ball nimmst. Ohnmachtszittern durchläuft ihren Körper, während sie sich tiefer in die Wiege hineinrollt."
  },
  AvgDialog_48556_Content_1 = {
    Text = "Hüter, wenn es dir passt, könntest du jetzt einen Moment für mich entbehren?"
  },
  AvgDialog_48556_Content_10 = {
    Text = "Das war keine Melodie von Kadath. Der Klang, der die quer zur Schläfe verlaufende Gyrus durchdrang, war so unheimlich wie der Kosmos, und doch so sanft wie die Morgensterne."
  },
  AvgDialog_48556_Content_11 = {
    Text = "Das Bewusstsein wurde zu einem ziellosen Schiff, das unter Tinktur's Gesang in Richtung des Ufers des Verlangens trieb."
  },
  AvgDialog_48556_Content_12 = {
    Text = "Der kalte, feuchte Hauch verweilte auf meinen Lippen und entfachte ein namenloses dunkles Feuer in meinem Hals."
  },
  AvgDialog_48556_Content_13 = {
    Text = "Wenn Sie Ihre Augen wieder öffnen, schaut Tinktur ebenfalls nach oben, ihre Lippen erscheinen besonders feucht und voll."
  },
  AvgDialog_48556_Content_14 = {
    Text = "Eine unglaubliche Antwort liegt dir auf der Zunge, doch die Vernunft wird schnell von dem wiederkehrenden Gesang von deinen Lippen hinweggefegt."
  },
  AvgDialog_48556_Content_15 = {
    Text = "Das Lied spielt mit den tiefsten Wünschen und verwischt erneut die Grenze zwischen Realität und Fantasie. Ohnmächtig, sich zu widersetzen, ohnmächtig, zu entkommen."
  },
  AvgDialog_48556_Content_16 = {
    Text = "Shh... Nur für heute Nacht, werde ein Gefangener meines Liedes..."
  },
  AvgDialog_48556_Content_2 = {
    Text = "Na sicher, hast du in letzter Zeit an der Schule unglückliche Ereignisse erlebt?"
  },
  AvgDialog_48556_Content_3 = {
    Text = "Nein, nein... das ist es nicht."
  },
  AvgDialog_48556_Content_4 = {
    Text = "Ich habe ein Lied, das ich, egal was passiert... für dich singen möchte."
  },
  AvgDialog_48556_Content_5 = {
    Text = "Du nickst und setzt dich zurück auf die Liege im Pausenraum – es ist nur ein Lied."
  },
  AvgDialog_48556_Content_6 = {
    Text = "Die Unruhe in den Augen des Erwachenden verschwindet in einem Augenblick, und ein mysteriöses Lächeln breitet sich über ihr exquisite, andereweltliche Gesicht aus—"
  },
  AvgDialog_48556_Content_7 = {
    Text = "Ein Lied, das nur für dich geboren und nur für dich gesungen wird."
  },
  AvgDialog_48556_Content_8 = {
    Text = "Sobald das Lied meine Ohren erreichte, wurde mein Bewusstsein mitgerissen und in eine faszinierende Illusion gezogen."
  },
  AvgDialog_48556_Content_9 = {
    Text = "Tinkturs Lied umging die Verteidigungslinie der Rationalität, schlüpfte durch die Ritzen des Körpers in die Seele—"
  },
  AvgDialog_48596_Content_1 = {
    Text = "Laut Ericas Hinweisen wurde mein Ersatzumhang zuletzt außerhalb der alten Quartiere des Erwachens gesehen..."
  },
  AvgDialog_48596_Content_10 = {
    Text = "Gespenst... ein Gespenst?!"
  },
  AvgDialog_48596_Content_11 = {
    Text = "Brown, lass uns gehen – worauf wartest du!"
  },
  AvgDialog_48596_Content_12 = {
    Text = "Jenkin greift verzweifelt nach deiner Hand und versucht, dich aus dem \"Haus der Hexe\" zu ziehen. Doch die ungewöhnliche Wärme ihrer Hand lässt dich sofort spüren, dass etwas nicht stimmt."
  },
  AvgDialog_48596_Content_13 = {
    Text = "<Small:Der Einfluss von Lemwashi...>"
  },
  AvgDialog_48596_Content_14 = {
    Text = "Ohne Jenkins nervöse Miene zu beachten, tratst du vor und öffnete den Kleiderschrank. Verschiedene Stoffe fielen heraus und begruben dich vollständig darunter."
  },
  AvgDialog_48596_Content_15 = {
    Text = "%player%?! Stirb nicht!"
  },
  AvgDialog_48596_Content_16 = {Text = "Squeak!!!"},
  AvgDialog_48596_Content_17 = {
    Text = "Jenkin und Braun schlossen sich zusammen, um dich unter deinem fehlenden Umhang, deinem neu gekauften Hemd, deinen sorgfältig aufbewahrten Winterdecken und anderer Kleidung zu retten."
  },
  AvgDialog_48596_Content_18 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_48596_Content_19 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_48596_Content_2 = {
    Text = "*Hust, hust,* es ist alles Staub... Dieser Ort scheint seit Jahren verlassen zu sein. Gibt es wirklich jemanden—?"
  },
  AvgDialog_48596_Content_20 = {
    Text = "Bist du... in Ordnung?"
  },
  AvgDialog_48596_Content_21 = {
    Text = "Warum stiehlst du... warum sammelst du meine Kleider?"
  },
  AvgDialog_48596_Content_22 = {
    Text = "Jenkin murmelte etwas vor sich hin, sein Körper war bereit, jederzeit zu fliehen."
  },
  AvgDialog_48596_Content_23 = {
    Text = "Du hockst hilflos und nimmst einen \"Geisel\". Braun lässt einen seltsamen Schrei ertönen, seine großen Augen sehen besonders unschuldig aus."
  },
  AvgDialog_48596_Content_24 = {
    Text = "Braun—In Ordnung! Ich werde es sagen!"
  },
  AvgDialog_48596_Content_25 = {
    Text = "Weil ich in die Pubertät gekommen bin. Meine Schwester sagte einmal, dass während der Pubertät seltsame Gedanken in deinen Kopf kommen könnten."
  },
  AvgDialog_48596_Content_26 = {
    Text = "Es ist die Pubertät."
  },
  AvgDialog_48596_Content_27 = {
    Text = "Das stimmt! Jugend! Für mich äußert es sich als starker Wunsch, dir deine Sachen zu stehlen. Es ist ein Beweis, dass ich mich um dich kümmere!"
  },
  AvgDialog_48596_Content_28 = {
    Text = "Du ziehst ihren Kapuzenpulli herunter und schüttelst mit einem Lächeln den Kopf, als sie ausruft: \"Au!\""
  },
  AvgDialog_48596_Content_29 = {
    Text = "Deine Pubertät kam nicht so früh. Ruhe dich in den kommenden Tagen aus, und du wirst bald wieder normal sein."
  },
  AvgDialog_48596_Content_3 = {
    Text = "Zwei Fußabdrücke erstrecken sich von der Treppe bis zum Raum am Ende. Der kleinere Abdruck scheint zu einem nagetierartigen Freund zu gehören."
  },
  AvgDialog_48596_Content_30 = {
    Text = "Aber wenn du in Zukunft meine Sachen \"einsammeln\" möchtest, lass es mich bitte vorher wissen."
  },
  AvgDialog_48596_Content_4 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_48596_Content_5 = {
    Text = "Du trittst vorsichtig und atmest leise, folgst der Richtung der Fußabdrücke, bis du eine Tür tief im Flur aufdrückst."
  },
  AvgDialog_48596_Content_6 = {
    Text = "Quietschen—!"
  },
  AvgDialog_48596_Content_7 = {
    Text = "<Shake:WOAH!>\nIst das nicht d–der große Schutzherr? Was verschlägt Euch so plötzlich hierher?"
  },
  AvgDialog_48596_Content_8 = {
    Text = "Jenkin schlug den Schrank mit einem Krachen zu und erwischte dabei fast Browns Schwanz im Chaos. Der kleine Raum wurde sofort durcheinandergeworfen."
  },
  AvgDialog_48596_Content_9 = {
    Text = "Ich sollte fragen, wie du hierher gekommen bist. Dieses Gebäude wurde seit Jahren nicht mehr genutzt, und ich habe gehört, dass Geister früher dort spukten, weshalb die Studenten es auch \"Hexenhaus\" nennen..."
  },
  AvgDialog_48597_Content_1 = {
    Text = "Hast du dich beruhigt?"
  },
  AvgDialog_48597_Content_10 = {
    Text = "Ich möchte... dich wieder umarmen, genau wie zuvor."
  },
  AvgDialog_48597_Content_11 = {Text = "Du nickst."},
  AvgDialog_48597_Content_12 = {
    Text = "Dann drückte der kalte Oberkörper gegen dich."
  },
  AvgDialog_48597_Content_13 = {
    Text = "Während meiner Tage im Sanatorium erlebte ich nie eine solche Wärme.\nWäre es doch nur möglich, dass du immer an meiner Seite sein könntest..."
  },
  AvgDialog_48597_Content_14 = {
    Text = "Diese Wärme ist wie ein anderes Gift, das mich langsam verzehrt.\nIch frage mich oft: Wenn das Meer uns schließlich trennt, wie einsam wird es sein..."
  },
  AvgDialog_48597_Content_15 = {
    Text = "Sie können hier für immer bleiben."
  },
  AvgDialog_48597_Content_16 = {
    Text = "Die Stille dauerte mehrere Dutzend Sekunden, bis ihr stagnierender Atem wieder normal wurde und sie dich sanft losließ."
  },
  AvgDialog_48597_Content_17 = {
    Text = "Lass uns gehen. Es ist Zeit für \"heilen\"."
  },
  AvgDialog_48597_Content_18 = {
    Text = "Nymphaea nimmt deine Hand und sinkt Schritt für Schritt in die Umarmung des Meeres. \nDas Meerwasser hebt sanft ihren Saum, als würde es eine langsam erblühende blasslila Wasserlilie wiegen."
  },
  AvgDialog_48597_Content_19 = {
    Text = "Ihre Hände sind kalt, aber ihr Blick brennt dich fast."
  },
  AvgDialog_48597_Content_2 = {
    Text = "Ah, äh, tut mir leid..."
  },
  AvgDialog_48597_Content_20 = {
    Text = "Sei unbesorgt, das Meerwasser wird das Gift reinigen, das ich in deinem Körper hinterlassen habe."
  },
  AvgDialog_48597_Content_21 = {
    Text = "Was das \"Gift\" betrifft, das du in meinem Herzen hinterlassen hast... Ich werde es schätzen."
  },
  AvgDialog_48597_Content_3 = {
    Text = "Mach dir keine Sorgen, jeder ist in letzter Zeit von der Überschwemmung des Heiligen Flusses betroffen. Einige ungewöhnliche Aktionen sind zu erwarten."
  },
  AvgDialog_48597_Content_4 = {
    Text = "Ich verstehe, aber... zu nah bei mir zu sein, wird durch das \"Gift\" in mir getrübt."
  },
  AvgDialog_48597_Content_5 = {
    Text = "Du schaust dir deine Handfläche an; ein schwacher Bluterguss bildet sich dort, wo du die unheimliche, knöcherne Hand von Nymphaea berührt hast."
  },
  AvgDialog_48597_Content_6 = {
    Text = "Ich weiß... ich weiß, wie man es heilt.\nBitte folge mir."
  },
  AvgDialog_48597_Content_7 = {
    Text = "Die Flut brüllte, die salzige Meeresbrise hob Nymphaeas sanftes Haar. Sie drückte ihren Hut nach unten, die schwarze Seidenblume schwankte mit ihrer Bewegung."
  },
  AvgDialog_48597_Content_8 = {
    Text = "Die Toxine, die in diesem Skelett konzentriert sind, werden im Meerwasser auflösen."
  },
  AvgDialog_48597_Content_9 = {
    Text = "Seit das \"Antidot\" in Reichweite ist, darf ich eine selbstsüchtige Bitte äußern?"
  },
  AvgDialog_48598_Content_1 = {
    Text = "Sie erkennen diesen Ort; Sie wurden einst während einer Veranstaltung von seinem Besitzer in diesen Raum eingeladen."
  },
  AvgDialog_48598_Content_10 = {
    Text = "Du siehst die Essenz, die Stück für Stück, Schicht für Schicht an dem gruseligen Schädel haftet, sich miteinander verwebt und ein vertrautes Gesicht umreißt."
  },
  AvgDialog_48598_Content_11 = {
    Text = "Lady Daffodil..."
  },
  AvgDialog_48598_Content_12 = {
    Text = "Die Hexe aus einer anderen Dimension offenbarte ein geheimnisvolles Lächeln. Sie hob ihren Kopf und ließ ihre grau-lila Lippen sich von den verzweifelten des Reisenden lösen, die nach Luft verlangten."
  },
  AvgDialog_48598_Content_13 = {
    Text = "Ich habe dich wieder einmal vor Gefahr gerettet, mein lieber kleiner Gast."
  },
  AvgDialog_48598_Content_14 = {
    Text = "Hmm... Aber ich würde nicht ohne Grund ins Meer der Ursprünge eintreten. Es warst du..."
  },
  AvgDialog_48598_Content_15 = {
    Text = "Shh... Höre, die Schädel flüstern."
  },
  AvgDialog_48598_Content_16 = {
    Text = "Sie hungern nach dir. Ohne mich wärst du lebendig zerrissen worden."
  },
  AvgDialog_48598_Content_17 = {
    Text = "Nun... und was ist mit dir? Ohne dein Einverständnis könnten diese Köpfe mich nicht in diesen Bereich gezerrt haben."
  },
  AvgDialog_48598_Content_18 = {
    Text = "...Natürlich, ich fühle mich genauso."
  },
  AvgDialog_48598_Content_19 = {
    Text = "Also werde ich derjenige sein, der die Belohnung für diesen Deal bestimmt..."
  },
  AvgDialog_48598_Content_2 = {
    Text = "Auf dem dunklen Wasser liegend, sind deine Augen auf die grau-weiße Sonne gerichtet. Die Köpfe um dich herum lachen, beleidigen einander und klagen in Einsamkeit."
  },
  AvgDialog_48598_Content_3 = {
    Text = "Sie kommen nacheinander, prallen gegen deinen Arm und lassen dich fast ins Wasser fallen—"
  },
  AvgDialog_48598_Content_4 = {
    Text = "Meer der Ursubstanz, der Versteck der Düsteren Hexe, die kostbarste Zuflucht von Narzisse."
  },
  AvgDialog_48598_Content_5 = {
    Text = "Warum bist du hier? Eine weitere Einladung von Narzisse? Oder ist das nur ein absurdes Dream"
  },
  AvgDialog_48598_Content_6 = {
    Text = "Ihre Glieder strecken sich aus und lassen das Meer der urtümlichen Materie Sie zur nicht existierenden Küste drücken. Unzählige Köpfe drängeln sich in den grauen Wellen, das Geräusch von zusammenprallenden Knochen klar und gespenstisch."
  },
  AvgDialog_48598_Content_7 = {
    Text = "Das primordiale Meerwasser strömt aus den Augenwinkeln, der Körper sinkt unter dem Druck des Kopfes unter die Oberfläche. In Momenten verdeckt der den Himmel blockierende Kopf sämtliches Licht."
  },
  AvgDialog_48598_Content_8 = {
    Text = "—Dann schmiegt sich der Kopf des Chaos an dein Ohr, die Lippen berühren sich."
  },
  AvgDialog_48598_Content_9 = {
    Text = "Kalte, feuchte Luft strömt zwischen deinem oberen und unteren Kiefer, und ein violetter Duft sickert aus deinen Organen und breitet sich aus."
  },
  AvgDialog_4870_Content_1 = {
    Text = "Tsk, dieser Typ ist im Weg"
  },
  AvgDialog_4870_Content_2 = {
    Text = "Casiah ist noch nicht aus ihrer Ohnmacht erwacht und lässt Lotan sie mitnehmen"
  },
  AvgDialog_4870_Content_3 = {
    Text = "Überlassen Sie den Kampf mir!"
  },
  AvgDialog_4871_Content_1 = {
    Text = "Kommunikator wird warm, klare Frauenstimme ertönt im Kopf, besorgt und eilig"
  },
  AvgDialog_4871_Content_10 = {
    Text = "Film und Kamera sind neue Erfindungen, auf dem Markt knapp und teuer.\nUnd <Yellow:von Missaga bearbeiteter> „Film\" ist noch teurer"
  },
  AvgDialog_4871_Content_11 = {
    Text = "Verarbeitung? Kann der Film des Kaufhauses nicht direkt verwendet werden?"
  },
  AvgDialog_4871_Content_12 = {
    Text = "Silberkerne verursachen eine Überbelichtung des Films, nur Filme, die im <Blue:Missaga Silberkern-Labor> behandelt wurden, können das Erwachen aufzeichnen"
  },
  AvgDialog_4871_Content_13 = {
    Text = "Diese einzigartige Prototyp-Filmrolle kann nur etwa 20 Minuten aufnehmen... Ist der Dreh abgeschlossen?"
  },
  AvgDialog_4871_Content_14 = {
    Text = "Mmh... Es dauert... noch ein bisschen... Alle... müssen noch nachdenken!"
  },
  AvgDialog_4871_Content_15 = {
    Text = "Stimmt, schließlich ist das Testen der Kameraeffekte zweitrangig — die Hauptsache ist, Spaß zu haben, oder?"
  },
  AvgDialog_4871_Content_16 = {
    Text = "Nun, habt einen wunderbaren Feiertag, und ich freue mich darauf, eure Arbeit zu sehen."
  },
  AvgDialog_4871_Content_17 = {
    Text = "Ramona beendete den Anruf und ließ Euch kreidebleich zurück."
  },
  AvgDialog_4871_Content_2 = {
    Text = "Ich spüre eine mentale Welle. Hattest du einen Kampf? Bist du unverletzt?"
  },
  AvgDialog_4871_Content_3 = {
    Text = "Wir sind nur auf ein paar Mutanten gestoßen, das ist alles. Allen geht es gut."
  },
  AvgDialog_4871_Content_4 = {
    Text = "Das ist gut. Läuft alles glatt?"
  },
  AvgDialog_4871_Content_5 = {
    Text = "Es lief... einigermaßen gut"
  },
  AvgDialog_4871_Content_6 = {
    Text = "Du siehst einigen erwartungsvollen Gesichtern entgegen, diese jungen Menschen haben einen gewissen Respekt vor dem „Besitzer der Kamera“"
  },
  AvgDialog_4871_Content_7 = {
    Text = "Übrigens, ist die Filmrolle teuer? Aurita ist sehr neugierig"
  },
  AvgDialog_4871_Content_8 = {
    Text = "Aurita hat auch nicht viel——hm, hm!"
  },
  AvgDialog_4871_Content_9 = {
    Text = "Wann und wo auch immer saß Casiah, die von Lotans Schulter heruntergeklettert war, und hielt Auritas Mund zu, brachte das schreiende Mädchen zur Seite"
  },
  AvgDialog_4872_Content_1 = {
    Text = "Ich habe den Duft des Austauschgeschäfts gerochen, ich gehe hier entlang"
  },
  AvgDialog_4872_Content_2 = {
    Text = "Schnüffeln, schnüffeln..."
  },
  AvgDialog_4872_Content_3 = {
    Text = "Außer Braun hat Aurita nichts gerochen!"
  },
  AvgDialog_4872_Content_4 = {
    Text = "Ihr seid doch keine kleinen Welpen!"
  },
  AvgDialog_4873_Content_1 = {
    Text = "Ich kenne Daffodil am besten. Sie ist nicht der Typ, der sich für Kinderkram interessiert."
  },
  AvgDialog_4873_Content_10 = {
    Text = "Handlung. Willst du nicht deine eigene Handlung verfilmen?"
  },
  AvgDialog_4873_Content_11 = {
    Text = "Meine Aufgabe ist es, euch alle sicher und wohlbehalten zurück zur Schule zu bringen.\nRechnet nicht mit mir, wenn es ums Drehbuchschreiben oder Filmemachen geht."
  },
  AvgDialog_4873_Content_13 = {
    Text = "Die Gestalt des Mutanten löste sich auf, begleitet vom Klang eines Langschwerts, das den Wind durchschnitt. Lotan wischte den schwarzen Schlamm von ihrer Klinge und wandte sich dir mit einem Lächeln zu."
  },
  AvgDialog_4873_Content_14 = {
    Text = "Das ist es, was ich tun soll."
  },
  AvgDialog_4873_Content_2 = {
    Text = "Nur die intensivsten und extremsten Emotionen... können ihr wahres Lächeln hervorlocken."
  },
  AvgDialog_4873_Content_3 = {
    Text = "Das ist Schmerz! Sie muss sich nach einer Geschichte sehnen, die tief in Schmerz begraben ist, einer, die alle zum <Red:Bluten> bringt!"
  },
  AvgDialog_4873_Content_4 = {
    Text = "Ist das wirklich ihre Persönlichkeit hinter so einer ruhigen Fassade?\nDann könnte meine Geschichte... ihr nicht ins Auge fallen."
  },
  AvgDialog_4873_Content_5 = {
    Text = "Hör nicht auf den Unsinn dieses Kerls.\nDaffodil mag zwar Drama genießen, aber ihre Persönlichkeit ist nicht so boshaft."
  },
  AvgDialog_4873_Content_6 = {
    Text = "Was geht dir durch den Kopf? Magst du es teilen?"
  },
  AvgDialog_4873_Content_7 = {
    Text = "Das habe ich in einem Buch gelesen. Es erzählt die Geschichte eines Träumers, der mit ritterlichen Ambitionen in einer Ära reist, in der die Ritter verschwunden sind."
  },
  AvgDialog_4873_Content_8 = {
    Text = "Ich glaube, das Buch habe ich auch gelesen... Lotan, was ist mit dir?"
  },
  AvgDialog_4873_Content_9 = {
    Text = "Was ist mit mir?"
  },
  AvgDialog_4874_Content_1 = {
    Text = "Diesmal dürfen wir den Magier nicht wieder die Geschichte schreiben lassen!"
  },
  AvgDialog_4874_Content_10 = {
    Text = "Squeak squeak!!"
  },
  AvgDialog_4874_Content_11 = {
    Text = "Braun, warte! Du bist gleich an der Reihe!"
  },
  AvgDialog_4874_Content_12 = {
    Text = "Was? Du meinst den Feind?"
  },
  AvgDialog_4874_Content_13 = {
    Text = "Ahhh—! Wann sind diese Verrückten aufgetaucht?!"
  },
  AvgDialog_4874_Content_2 = {
    Text = "Warum nicht? Zeit, Ort, Figuren, Konflikt, Spannung — haben meine Geschichten nicht all diese Elemente? Und ich habe sie alle am Anfang eingeführt. Ist das nicht korrekt?"
  },
  AvgDialog_4874_Content_3 = {
    Text = "Hetz, hetz was? Du hast zu schnell gesprochen. Ich hab das nicht verstanden."
  },
  AvgDialog_4874_Content_4 = {
    Text = "Oh je, es ist einfach so klischeehaft! Selbst Aurita würde es langweilig finden."
  },
  AvgDialog_4874_Content_5 = {
    Text = "Hmm? Aurita findet alles in Ordnung!"
  },
  AvgDialog_4874_Content_6 = {
    Text = "Du Dummkopf...!"
  },
  AvgDialog_4874_Content_7 = {
    Text = "Egal, wenn es nach mir ginge, würde ich definitiv „<Blue:Lentiniëns Mitternachtsritter>“ schreiben!"
  },
  AvgDialog_4874_Content_8 = {
    Text = "Quiek Quiek—Quiek Quiek Quiek Quiek!"
  },
  AvgDialog_4874_Content_9 = {
    Text = "Im purpurroten Hotel, unter dem Tisch des prunkvollen Restaurants, zielte die Hand des rechtschaffenen Diebes auf die Brieftasche des bösen Tycoons..."
  },
  AvgDialog_4875_Content_1 = {
    Text = "Nur spezieller Film kann Erweckte Körper aufzeichnen, aber wir haben gerade unser einziges Testexemplar zerstört..."
  },
  AvgDialog_4875_Content_10 = {
    Text = "Was für ein Trick! Das ist Magie, <Big:Magie!!>"
  },
  AvgDialog_4875_Content_11 = {
    Text = "Lotan, hör auf, sie zu necken."
  },
  AvgDialog_4875_Content_12 = {
    Text = "Fräulein Casiah, die Methode, die Ihr erwähnt habt, ist...?"
  },
  AvgDialog_4875_Content_13 = {
    Text = "Sucht Lady Nymphaea auf. Sie hat sicherlich eine Lösung.\nEine Frau, die so begeistert von Spektakeln ist, kann eine <Yellow:Maschine, die Erweckte Körper aufzeichnet>, nicht ignorieren."
  },
  AvgDialog_4875_Content_14 = {
    Text = "Tsk... Muss ich mich schon wieder mit dieser Frau herumschlagen?"
  },
  AvgDialog_4875_Content_15 = {
    Text = "Die Hilfe der Narzisse-Dame in Anspruch nehmen? Es ist eine gangbare Lösung, solange das, was sie im Austausch möchte, nicht zu übertrieben ist..."
  },
  AvgDialog_4875_Content_16 = {
    Text = "Ein leichtes Zupfen an Eurem Umhang erregt Eure Aufmerksamkeit. Ihr blickt hinunter und seht Lily auf Zehenspitzen stehen, daran ziehend, ihre Augen funkeln, als sie Euren Blick treffen."
  },
  AvgDialog_4875_Content_17 = {
    Text = "Möchte Lily die Narzissen-Dame besuchen?"
  },
  AvgDialog_4875_Content_18 = {
    Text = "Narzissenfrau... Mamas Freundin, ja!"
  },
  AvgDialog_4875_Content_19 = {
    Text = "Wenn Lily das sagt, dann los, Hüter der Geheimnisse"
  },
  AvgDialog_4875_Content_2 = {
    Text = "Fräulein Dolls Forschungstests... Mein Gebieter, ich glaube, wir..."
  },
  AvgDialog_4875_Content_3 = {
    Text = "Ogiers Gesicht wird aschfahl, er teilt denselben Schmerz und dieselbe Angst wie Ihr."
  },
  AvgDialog_4875_Content_4 = {
    Text = "Wir werden wahrscheinlich hingerichtet."
  },
  AvgDialog_4875_Content_5 = {
    Text = "Mein Gebieter, ich werde... das nicht... zulassen..."
  },
  AvgDialog_4875_Content_6 = {
    Text = "Ogiers Worten fehlte ihre übliche Bestimmtheit, und er schien sich über Dolls möglichen Zorn unsicher zu sein."
  },
  AvgDialog_4875_Content_7 = {
    Text = "Warum seht ihr beide so niedergeschlagen aus?\nKommt schon — schenkt mir ein Lächeln!"
  },
  AvgDialog_4875_Content_8 = {
    Text = "Es ist nur spezieller Film. Es gibt noch einen Weg."
  },
  AvgDialog_4875_Content_9 = {
    Text = "Kennst du noch irgendwelche Tricks, um Dinge zu reparieren?"
  },
  AvgDialog_4876_Content_10 = {
    Text = "Tochter... Meine Tochter!"
  },
  AvgDialog_4876_Content_11 = {
    Text = "Es ist alles meine Schuld. Ich habe versagt, dich zu beschützen, und nun bist du in der Dunkelheit verloren!"
  },
  AvgDialog_4876_Content_12 = {
    Text = "{Male=He,Female=She} spielte wie ein Affe, dem man auf den Fuß getreten hat."
  },
  AvgDialog_4876_Content_13 = {
    Text = "Wo hast du diesen Affen gesehen? Im Zoo von Lentiniën?"
  },
  AvgDialog_4876_Content_14 = {
    Text = "Still, still!!"
  },
  AvgDialog_4876_Content_15 = {
    Text = "Beruhigt euch, Fräulein Casiah! Ein weiterer Aberrant-Körper nähert sich!"
  },
  AvgDialog_4876_Content_2 = {
    Text = "Mutter, Mutter, wo bist du?"
  },
  AvgDialog_4876_Content_3 = {
    Text = "Ich bin nicht absichtlich verloren gegangen, es tut mir leid, Mutter, es tut mir leid"
  },
  AvgDialog_4876_Content_4 = {
    Text = "Lily... ich bin kein böses Kind, bitte lass mich nicht allein"
  },
  AvgDialog_4876_Content_5 = {
    Text = "Die Stimme des Mädchens verklang im Wind, ihre Tränen fielen auf die dunkle Erde."
  },
  AvgDialog_4876_Content_6 = {
    Text = "Sie weinte leise in dem stockfinsteren Raum, eine weitere Handvoll kummervoller Tränen benetzte die reinweißen Lilien an ihrem Bett."
  },
  AvgDialog_4876_Content_7 = {
    Text = "%player%, beeil dich! Du bist dran!"
  },
  AvgDialog_4876_Content_8 = {
    Text = "Mach kein Theater! Sei leise!"
  },
  AvgDialog_4876_Content_9 = {
    Text = "Du richtetest deinen Kragen, versuchtest schmerzerfüllt auszusehen, und humpeltest vor die Kamera."
  },
  AvgDialog_4877_Content_10 = {
    Text = "Der besorgte Ausdruck auf dem Gesicht des Mädchens."
  },
  AvgDialog_4877_Content_11 = {
    Text = "Mutter...! Mutter!"
  },
  AvgDialog_4877_Content_12 = {
    Text = "Eine kleine Hand grub sich durch den Schnee. Ein zerbrechlicher, winziger Körper schirmte sie ab und stellte sich dem tosenden Schneesturm entgegen —"
  },
  AvgDialog_4877_Content_2 = {
    Text = "Eine in dicke Winterkleidung gehüllte Frau stapft durch den Schnee, ihre schwere Last drückt ihre Schritte nieder und hinterlässt tiefe Fußabdrücke."
  },
  AvgDialog_4877_Content_3 = {
    Text = "Warte auf mich... meine Tochter, Mama wird bald bei dir sein..."
  },
  AvgDialog_4877_Content_4 = {
    Text = "Vom fernen Schneeberg hallte das laute Geräusch von etwas Einstürzendem wider."
  },
  AvgDialog_4877_Content_5 = {Text = "Lawine?!"},
  AvgDialog_4877_Content_6 = {
    Text = "Moment, die Lawine in der <Yellow:Magie–Fata Morgana> ist doch nicht wirklich gefährlich, oder?"
  },
  AvgDialog_4877_Content_7 = {
    Text = "Was ist die Magie–Fata Morgana? Sie ist die grandiose Phantasie dieser einsamen Abenteurerin und das Meisterwerk eines großen Magiers. Sie vereint Kälte, Angst, Albträume und Krisen in einem!"
  },
  AvgDialog_4877_Content_8 = {
    Text = "Von einstürzenden Schneeblöcken verfolgt, wagte sich die Abenteurerin tief ins Schneefeld. Doch wie können gebrechliche Menschen die Natur bezwingen? In einem Moment der Unachtsamkeit fiel sie in eine bodenlose Eishöhle."
  },
  AvgDialog_4877_Content_9 = {
    Text = "Der dichte Schnee drückte gegen die Luftröhre der Abenteurerin und ließ ihre Sicht verschwimmen. Gedenken blitzten vor ihren Augen auf — schwarze Wunden der Krankheit, der strömende Regen am Tag der Beerdigung, und —"
  },
  AvgDialog_4878_Content_10 = {
    Text = "Konflikt! Dies muss einer der Höhepunkte der Geschichte sein; es braucht Konflikt!"
  },
  AvgDialog_4878_Content_2 = {
    Text = "Ich hörte deine Stimme, warm und feucht... Mutter, weinst du?"
  },
  AvgDialog_4878_Content_3 = {
    Text = "Mutter... Mutter? Warum weinst du?"
  },
  AvgDialog_4878_Content_4 = {
    Text = "Eine Mutter stand vor einer Steintafel und weinte, während die Rufe des Mädchens von einer Mischung aus Erde und Holz erstickt wurden.\nObwohl nur einen Schritt entfernt, konnte sie das Flehen ihrer geliebten Tochter nicht hören."
  },
  AvgDialog_4878_Content_5 = {
    Text = "Mutter, bitte weine nicht. Ich werde ein braves Kind sein... Bitte übersehe mich nicht..."
  },
  AvgDialog_4878_Content_6 = {
    Text = "Mutter... Ich bin so erschöpft... Wirst du mich finden, wenn ich aufwache?"
  },
  AvgDialog_4878_Content_7 = {
    Text = "Wie eine Kerze kurz vor dem Erlöschen wurde ihre Stimme schwächer und leiser.\nAm Ende konnte sie nicht einmal mehr ihre eigene Stimme hören..."
  },
  AvgDialog_4878_Content_8 = {
    Text = "Als das Mädchen in tiefen Schlaf fällt, bricht die lauernde Dunkelheit auf dem Friedhof hervor! Sie stürzt sich auf die ahnungslose und trauernde Mutter!"
  },
  AvgDialog_4878_Content_9 = {
    Text = "Moment! Im Drehbuch war kein Kampf vorgesehen?"
  },
  AvgDialog_4879_Content_1 = {Text = "Dort."},
  AvgDialog_4879_Content_10 = {
    Text = "Du und Nymphaea beobachtetet das Mädchen still aus der Ferne. Ihre Augen waren geschlossen, doch ein glückliches und zufriedenes Lächeln zierte ihr Gesicht."
  },
  AvgDialog_4879_Content_11 = {
    Text = "Du zögerst, die Ruhe zu stören, doch die Patienten im Hof lassen keinen Raum für anhaltende Stille."
  },
  AvgDialog_4879_Content_12 = {
    Text = "Schwester Nymphaea... Meister..."
  },
  AvgDialog_4879_Content_13 = {
    Text = "Es tut mir leid, ich bin ohne Erlaubnis von eurer Seite gewichen..."
  },
  AvgDialog_4879_Content_14 = {
    Text = "Es ist in Ordnung, Lily. Möchtest du noch ein wenig bei deiner Mutter bleiben?"
  },
  AvgDialog_4879_Content_15 = {
    Text = "Lily hält deine Hand, blickt zurück zur stillen Tür und schüttelt entschlossen den Kopf."
  },
  AvgDialog_4879_Content_16 = {
    Text = "Lily weiß, welche Geschichte sie erzählen will. Lasst uns schnell zurückgehen."
  },
  AvgDialog_4879_Content_17 = {
    Text = "Nachdem ihr euch von Nymphaea verabschiedet habt, verlasst ihr das Sanatorium und macht euch auf den Rückweg nach Lentiniën."
  },
  AvgDialog_4879_Content_18 = {
    Text = "Mondlicht sickert durch die neblige Luft und das trübe Glas des Sanatoriums."
  },
  AvgDialog_4879_Content_19 = {
    Text = "In einem Winkel, in dem die Zeit stillsteht, fließt ein verborgenes Licht durch den dunkelvioletten magischen Kreis."
  },
  AvgDialog_4879_Content_2 = {
    Text = "Das Mädchen, das du suchst, sitzt am Ende des Korridors und lehnt sich an eine Tür, die dir nur allzu vertraut ist."
  },
  AvgDialog_4879_Content_3 = {
    Text = "Verschlungene und geheimnisvolle Muster durchdringen die Tür und strahlen ein dunkles, violettes Licht aus."
  },
  AvgDialog_4879_Content_4 = {Text = "Mutter..."},
  AvgDialog_4879_Content_5 = {
    Text = "Kannst du Lily sprechen hören?"
  },
  AvgDialog_4879_Content_6 = {
    Text = "Das welpenartige Murmeln erhielt keine Antwort, vielleicht weil die Tür zu dick war, oder vielleicht weil sich dahinter kein Leben mehr befand."
  },
  AvgDialog_4879_Content_7 = {
    Text = "Verzeihung... Lily hat versehentlich die Geschichten vergessen, die Mama und Lily erzählt haben."
  },
  AvgDialog_4879_Content_8 = {
    Text = "Lily möchte ihren Freunden Geschichten erzählen... Kann Mutter sie ihr beibringen?"
  },
  AvgDialog_4879_Content_9 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_4880_Content_10 = {
    Text = "Seid ihr die Legendären aus Lentiniën —!"
  },
  AvgDialog_4880_Content_11 = {
    Text = "Ja! Durch Lentiniën streifend bei Nacht, die gewöhnlichen Nächte des East End bewachend, für die Arbeiter sprechend, für die Verarmten rufend —"
  },
  AvgDialog_4880_Content_12 = {
    Text = "Wir sind die <Blue:Endenachtstreuner> und ihre treuen Assistenten!"
  },
  AvgDialog_4880_Content_13 = {
    Text = "Der Große Nachtstreuner sprang von der Schulter des Assistenten und durchtrennte mit ein paar flinken Bewegungen das Hanfseil mit seiner angeborenen Waffe!"
  },
  AvgDialog_4880_Content_14 = {
    Text = "Squeak, squeak!"
  },
  AvgDialog_4880_Content_15 = {
    Text = "Braun sagte... *hust hust*, Nachtstreuner sagte: Dieses Seil ist wirklich zäh zum Durchnagen!\nAber wir haben es geschafft! Das Licht der Freiheit winkt uns!"
  },
  AvgDialog_4880_Content_16 = {
    Text = "Danke, Nachtstreuner und Partner..."
  },
  AvgDialog_4880_Content_17 = {
    Text = "Das Mädchen hielt nach dem Sprechen inne und zeigte auf das Gesindel, das der Nachtstreuner angelockt hatte."
  },
  AvgDialog_4880_Content_2 = {
    Text = "Detektiv, ich habe das Geräusch von knirschenden Zähnen gehört."
  },
  AvgDialog_4880_Content_3 = {
    Text = "Einfach einen Moment... Fast geschafft..."
  },
  AvgDialog_4880_Content_4 = {
    Text = "Der tapfere und gutaussehende Detektiv lag wie ein Hund auf dem Boden, die Hände hinter dem Rücken gefesselt. Ohne aufzugeben, versuchte er, das Seil an den Handgelenken des Mädchens durchzubeißen."
  },
  AvgDialog_4880_Content_5 = {
    Text = "In einem Winkel, verborgen vor den beiden, glimmen ein Paar wilder Augen in der Dunkelheit! Etwas ist im Begriff, die Schatten zu durchbrechen und das erste Licht der Morgendämmerung zu bringen!"
  },
  AvgDialog_4880_Content_6 = {
    Text = "Squeak, squeak squeak!"
  },
  AvgDialog_4880_Content_7 = {
    Text = "<Blue:Nachtstreuner> sagte: Er empfiehlt, nicht weiter zu beißen. Meister Houdinis magisches Seil ist hart wie Stahl."
  },
  AvgDialog_4880_Content_8 = {
    Text = "Eine Person..."
  },
  AvgDialog_4880_Content_9 = {
    Text = "Eine Maus..."
  },
  AvgDialog_4881_Content_1 = {
    Text = "Wir haben gewonnen... Wir haben gewonnen!"
  },
  AvgDialog_4881_Content_10 = {
    Text = "Der Assistent hielt den Nachtstreuner hoch und schützte vorübergehend das schöne Fell des Streuners."
  },
  AvgDialog_4881_Content_11 = {
    Text = "Hey!! Leiche, hör auf zu reden! Schutzherr! Lotan! Tut etwas!!"
  },
  AvgDialog_4881_Content_12 = {
    Text = "Lotan schüttelte den Kopf, ein Phantom einer walartigen Kreatur erschien hinter ihr. Einfach als sie im Begriff war, alle aus dem Wasser zu ziehen, stürzte sich eine helle Gestalt hinein."
  },
  AvgDialog_4881_Content_13 = {
    Text = "Wasser! Es ist Wasser～ Auritas liebstes Meer!"
  },
  AvgDialog_4881_Content_14 = {
    Text = "Äußert einen Wunsch an mich, ihr Bedürftigen! Der Ozean wird all euren Erwartungen entsprechen!"
  },
  AvgDialog_4881_Content_15 = {
    Text = "Kommissar G und der Nachtstreuner tauschten Blicke aus und schoben gleichzeitig das lange schweigsame Mädchen in Weiß zur Ozean-Elfe."
  },
  AvgDialog_4881_Content_16 = {Text = "...?!"},
  AvgDialog_4881_Content_17 = {
    Text = "Bitte, bitte bring uns von hier weg."
  },
  AvgDialog_4881_Content_18 = {
    Text = "Casiah, deren Körper bereits zur Hälfte im Wasser versunken war, verzog ihre Lippen zu einem zufriedenen Lächeln."
  },
  AvgDialog_4881_Content_19 = {
    Text = "Magische Illusionen verschieben und verwandeln sich mit einer Bewegung ihrer Hand."
  },
  AvgDialog_4881_Content_2 = {
    Text = "Die böse Zauberin wurde durch die vereinten Kräfte aller besiegt. Sie brach zu Boden zusammen und streckte schwach ihre Hand nach einem Knopf aus."
  },
  AvgDialog_4881_Content_20 = {
    Text = "Im Handumdrehen waren alle durchnässt."
  },
  AvgDialog_4881_Content_21 = {
    Text = "Niemand bleibt verschont."
  },
  AvgDialog_4881_Content_22 = {
    Text = "Du machst es ernst!?"
  },
  AvgDialog_4881_Content_23 = {
    Text = "Die Elfe kehrte in die Freiheit des Meeres zurück, und alle entkamen Houdinis Werkstatt. Erfüllt das nicht den Wunsch des Mädchens?"
  },
  AvgDialog_4881_Content_24 = {
    Text = "Da hast du nicht unrecht, aber... wie kann diese Geschichte das Ende erreichen, das Lily sich wünscht?"
  },
  AvgDialog_4881_Content_25 = {
    Text = "„Das Mädchen lebte glücklich bis ans Ende ihrer Tage mit ihrer Mutter.\""
  },
  AvgDialog_4881_Content_26 = {
    Text = "„Tsk, das ist das letzte Mal, dass ich für dich Babysitter spiele.\nBitte mich nie wieder um solche lästigen Gefallen.\""
  },
  AvgDialog_4881_Content_27 = {
    Text = "Lily, Offizier, schaut mal! Was ist da drüben im Wasser?!"
  },
  AvgDialog_4881_Content_29 = {
    Text = "Eine gewaltige Wirbelsäule erhebt sich aus dem Wasser – das große Ungeheuer, das seit der Geburt des Planeten in der Tiefsee von Kardas gehaust hat. Es folgt dem Ruf des Lebens und durchquert den Schleier der Zeit!"
  },
  AvgDialog_4881_Content_3 = {
    Text = "Als sie das sah, warf Lotan dir einen Lautsprecher zu.\nSie schritt zu Casiah hinüber und begann, ihr etwas ins Ohr zu flüstern."
  },
  AvgDialog_4881_Content_30 = {Text = "Lotan...?"},
  AvgDialog_4881_Content_31 = {
    Text = "Seid ihr bereit aufzubrechen? Wenn nicht, wird eure Geschichte in diesem Wasser ihr Ende finden."
  },
  AvgDialog_4881_Content_32 = {
    Text = "Wow! Großer Fisch!"
  },
  AvgDialog_4881_Content_33 = {
    Text = "Nicht drängeln, einer nach dem anderen. Fräulein Lotans Rücken ist recht geräumig."
  },
  AvgDialog_4881_Content_34 = {
    Text = "Kannst du, halbfertige Meeresfee, aufhören, das Rampenlicht zu stehlen? Offensichtlich sind Bru... Nein, der Nachtstreuner und ich die wahren Helden hier!"
  },
  AvgDialog_4881_Content_35 = {Text = "Ähm..."},
  AvgDialog_4881_Content_36 = {
    Text = "Der große Fisch ist Auritas Begleiter! Also muss Aurita vorne sitzen!"
  },
  AvgDialog_4881_Content_37 = {Text = "Um...!"},
  AvgDialog_4881_Content_38 = {
    Text = "Lily, Lily... Ich..."
  },
  AvgDialog_4881_Content_39 = {
    Text = "Darf ich vorne sitzen?"
  },
  AvgDialog_4881_Content_4 = {
    Text = "Was heckst du jetzt schon wieder aus? Mach es nicht unmöglich für alle, das Chaos aufzuräumen."
  },
  AvgDialog_4881_Content_40 = {
    Text = "Da du jünger bist als ich... Sei vorsichtig! Auf dem Rücken des großen Kerls gibt es keinen Sitzplatz."
  },
  AvgDialog_4881_Content_41 = {
    Text = "Aurita möchte mit ihren Freunden zusammen sein!"
  },
  AvgDialog_4881_Content_42 = {
    Text = "Hey! Warum bist du so glitschig!? Wenn du schwimmen kannst, dann kletter nicht hier hoch!"
  },
  AvgDialog_4881_Content_43 = {
    Text = "Der Koloss brüllt durch seine Atemwege, springt mit Lachen und Hoffnung aus dem Wasser."
  },
  AvgDialog_4881_Content_44 = {
    Text = "Das Licht der Morgendämmerung durchdringt Wolken und Nebel und hüllt das Meer, die kolossalen Bestien und die Abenteurer in Rot– und Rosatöne."
  },
  AvgDialog_4881_Content_45 = {
    Text = "So, so hoch—!"
  },
  AvgDialog_4881_Content_47 = {
    Text = "Kommissar G, die Meerenspirite und der Gehilfe des Nachtstreuners taten sich zusammen, um das Mädchen aufzufangen und zu verhindern, dass sie vom Rücken der riesigen Bestie rutschte."
  },
  AvgDialog_4881_Content_48 = {
    Text = "Ein paar Leute lachten und spielten, schmierten sich gegenseitig Wasser auf die Kleidung."
  },
  AvgDialog_4881_Content_49 = {
    Text = "Vielleicht spielt für diese glücklichen Überlebenden das ursprünglich vorgesehene Ende der Geschichte keine Rolle mehr."
  },
  AvgDialog_4881_Content_5 = {
    Text = "Hoppla, nur ein kleiner Test—"
  },
  AvgDialog_4881_Content_50 = {
    Text = "In diesem Moment starrte das mutige Mädchen plötzlich direkt dich an, still auf dem Riff sitzend."
  },
  AvgDialog_4881_Content_51 = {
    Text = "Das Licht flackerte in seinen Augen, und ein außergewöhnlich strahlendes Lächeln breitete sich über sein jugendliches Gesicht aus."
  },
  AvgDialog_4881_Content_52 = {
    Text = "Eine von der Zeit gebundene Lilie, die ihre Blütezeit verpasst hat—"
  },
  AvgDialog_4881_Content_53 = {
    Text = "Der Moment des Blühens ist endlich angekommen."
  },
  AvgDialog_4881_Content_54 = {
    Text = "Klapper—Klapper—Klapper—"
  },
  AvgDialog_4881_Content_55 = {
    Text = "Applaus hallt von jenseits der Kulisse wider, und der Duft von Veilchen erfüllt allmählich die Luft. Jemand nähert sich anmutig und zieht ein wallendes Kleid hinter sich her."
  },
  AvgDialog_4881_Content_56 = {Text = "Daffodil!"},
  AvgDialog_4881_Content_57 = {
    Text = "Daffodil lächelte, als sie den Spezialfilm entnahm, und blies elegant nicht vorhandenen Staub davon."
  },
  AvgDialog_4881_Content_58 = {
    Text = "In der Tat, eine gute Geschichte. Ich akzeptiere diesen Tausch."
  },
  AvgDialog_4881_Content_59 = {
    Text = "Warte! Du hast nie erwähnt, dass du den Film mitnimmst.\nJetzt können wir Doll keinen Bericht erstatten."
  },
  AvgDialog_4881_Content_6 = {
    Text = "Während sich das Lächeln auf Casiahs Gesicht langsam verbreitert, dringt das Geräusch einer Unterströmung in aller Ohren."
  },
  AvgDialog_4881_Content_60 = {
    Text = "Du bist immer noch so impulsiv wie eh und je, Schwarzer Schwertkämpfer.\nDenk genau über Fräulein Dolls Auftrag nach—"
  },
  AvgDialog_4881_Content_61 = {
    Text = "„Modifizierte Maschinen testen“... anstatt Spezialfilm zu testen, richtig?"
  },
  AvgDialog_4881_Content_62 = {
    Text = "Aber ich habe den Film noch gar nicht gesehen! Er unterscheidet sich vom Comic, oder?"
  },
  AvgDialog_4881_Content_63 = {
    Text = "\nDie Maschine hat eure Geschichte treu aufgezeichnet, und der Film ist lediglich das Medium dieser wunderschönen Zeit...\nDie Aufgabe, die euch das „Gehirn im Glas\" zugewiesen hat, habt ihr doch längst erledigt, nicht wahr?"
  },
  AvgDialog_4881_Content_64 = {
    Text = "Was den fertigen Film betrifft, so heiße ich alle herzlich willkommen, zum Austauschhändler zu kommen und ihn gemeinsam zu genießen."
  },
  AvgDialog_4881_Content_65 = {
    Text = "Gerade als du den Händler überzeugen wolltest, den Film zu behalten, summte dein Kommunikator ungelegen."
  },
  AvgDialog_4881_Content_66 = {
    Text = "So lange zum Antworten gebraucht, du musst ja viel Spaß haben? Ich hoffe, du kannst genauso konzentriert sein, wenn du deine Schularbeiten erledigst."
  },
  AvgDialog_4881_Content_67 = {
    Text = "Lassen wir die Höflichkeiten. Ich habe etwas verloren — ich habe dir nur eine Schachtel Spezialfilm übergeben, als ich das Forschungslabor verlassen habe, korrekt?"
  },
  AvgDialog_4881_Content_68 = {
    Text = "Hmm... Tatsächlich, nur eine Kamera und eine Rolle Film."
  },
  AvgDialog_4881_Content_69 = {
    Text = "Dolls emotionslose Stimme floss in die Gedanken aller anwesenden Misaq-Mitarbeiter, sodass die zuvor lachende und plaudernde Menge den Atem anhielt, aus Angst, irgendeine Information zu verpassen."
  },
  AvgDialog_4881_Content_7 = {
    Text = "Kommt herbei, Fluten! Seid Zeugen von Meister Houdinis Finale — die ultimative Wassertank-Flucht!"
  },
  AvgDialog_4881_Content_70 = {
    Text = "Nun, da es keinen Ausgangsnachweis von Erica gibt, ist es sinnlos, dich zu fragen."
  },
  AvgDialog_4881_Content_71 = {
    Text = "Komm bald zurück. Du warst lange genug draußen."
  },
  AvgDialog_4881_Content_72 = {
    Text = "Doll beendete abrupt die Kommunikation. Als der Strom ihre Gehirne verließ, seufzten alle erleichtert auf."
  },
  AvgDialog_4881_Content_73 = {
    Text = "Lady Daffodil! Könnte der Film, den du uns gegeben hast, sein—"
  },
  AvgDialog_4881_Content_74 = {
    Text = "Wo ist diese böse Frau?! Wann ist sie verschwunden?!"
  },
  AvgDialog_4881_Content_75 = {
    Text = "Lily beobachtete, wie das Graue Meer um die Ecke der Kulisse verschwand. Als sie deinen Blick bemerkte, drehte sie sich um und ging zu dir herüber."
  },
  AvgDialog_4881_Content_76 = {
    Text = "Was ist los, Lily?"
  },
  AvgDialog_4881_Content_77 = {
    Text = "Lily ist sehr glücklich..."
  },
  AvgDialog_4881_Content_78 = {
    Text = "Sie umklammert fest den Saum deines Umhangs, blickt auf und schenkt dir ein strahlendes Lächeln."
  },
  AvgDialog_4881_Content_79 = {
    Text = "Danke... „Mutter“."
  },
  AvgDialog_4881_Content_8 = {
    Text = "Der Wasserspiegel stieg rapide an, bedeckte bald die Füße der Kinder, dann ihre Waden... Schließlich erreichte er ihre Oberschenkel und machte es ihnen schwer, sich zu bewegen."
  },
  AvgDialog_4881_Content_80 = {Text = "Ende"},
  AvgDialog_4881_Content_9 = {
    Text = "Casiah!!! Was tust du da?! Willst du uns ertränken?!"
  },
  AvgDialog_4882_Content_1 = {
    Text = "Die Mutantin stieß einen letzten Schrei aus und verstreute silberne Funken. \nBald werden sie und ihre Trauer von der Welt vergessen sein."
  },
  AvgDialog_4882_Content_10 = {
    Text = "Ich sah ihr dabei zu, wie sie Tag für Tag verwelkte, von einer Sonne zu einem leblosen Tümpel, den nicht einmal der Wind kräuseln konnte."
  },
  AvgDialog_4882_Content_11 = {
    Text = "Schließlich tropfte nur noch die schwarze, zähe Flüssigkeit von ihren Fingern und verschmolz mit dem Boden."
  },
  AvgDialog_4882_Content_12 = {
    Text = "Anders als Gedichte stammen Geschichten immer von Menschen. Händler und wohlhabende Geschäftsleute, Studenten und Soldaten, Adlige und Diener... sie alle sind Geschichten."
  },
  AvgDialog_4882_Content_13 = {
    Text = "Aber mein Ansatz... der kummervolle Ansatz wird die Geschichte immer zum selben Ende führen."
  },
  AvgDialog_4882_Content_14 = {
    Text = "Miss Horla..."
  },
  AvgDialog_4882_Content_15 = {
    Text = "Meisterin, es ist nicht Fräulein Horlas Schuld, oder?"
  },
  AvgDialog_4882_Content_16 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_4882_Content_17 = {
    Text = "Es ist schon gut, kleine Lily, ich habe diese Situation bereits akzeptiert."
  },
  AvgDialog_4882_Content_18 = {
    Text = "Nein, es ist nicht deine Schuld."
  },
  AvgDialog_4882_Content_19 = {
    Text = "Warum... sagst du das?"
  },
  AvgDialog_4882_Content_2 = {
    Text = "Der Schatten der Trauer... Ihr kanntet sie von früher, nicht wahr?"
  },
  AvgDialog_4882_Content_20 = {
    Text = "Ich hörte die Stimme des Mutanten. Zumindest hat das Symptom: Zusammenbruch dieses Blumenhändlers nichts mit dir zu tun."
  },
  AvgDialog_4882_Content_21 = {Text = "Was?"},
  AvgDialog_4882_Content_22 = {
    Text = "Aus den spärlichen Worten, die der Aufgelöste Körper hinterließ, schloss ich, dass sie bereits lange bevor du beantragt hast, Mythag zu verlassen, Symptome der Auflösung zeigte."
  },
  AvgDialog_4882_Content_23 = {
    Text = [[
Krank... ich bin krank.
Ich kann mich nicht mehr an Dinge erinnern, und manchmal sehe ich seltsame Dinge.
Der Arzt sagt, es sei ein Trugbild, ein Symptom: Hysterie.
Hysterie... das klingt so fern.]]
  },
  AvgDialog_4882_Content_24 = {
    Text = "Ich habe von anderen gehört, dass die neue Nachbarin am Ende der Straße ziemlich talentiert ist..."
  },
  AvgDialog_4882_Content_25 = {
    Text = "Sie hat einen Blumenstrauß bei mir gekauft und mir ein Gedicht geschenkt. Wie wunderbar! Mama hat das Gedicht auf die Vorhänge gestickt!"
  },
  AvgDialog_4882_Content_26 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_4882_Content_27 = {
    Text = "Ich werde immer kränker, und Mama wird immer vergesslicher.\nWas soll ich tun? Wenn ich gehe, wer kümmert sich dann um sie? Wer wird sich um diesen Laden kümmern?"
  },
  AvgDialog_4882_Content_28 = {
    Text = "Ich will nicht von zu Hause fort... Meine Familie braucht mich noch."
  },
  AvgDialog_4882_Content_29 = {
    Text = "Der Tod... Nein, ich will noch nicht..."
  },
  AvgDialog_4882_Content_3 = {
    Text = "Vor dem Besuch der <Yellow:Pestilenz> war Reni die Floristin der Stadt."
  },
  AvgDialog_4882_Content_30 = {
    Text = "Ihre Trauer entspringt dem Schmerz des Abschieds von ihrer Familie und der Angst, diese Welt zu verlassen."
  },
  AvgDialog_4882_Content_31 = {
    Text = "Wirklich... hat nichts mit mir zu tun?"
  },
  AvgDialog_4882_Content_32 = {
    Text = "Hat sie... eine Nachricht hinterlassen?"
  },
  AvgDialog_4882_Content_33 = {
    Text = "Sie sagte..."
  },
  AvgDialog_4882_Content_34 = {
    Text = "„Die neue Nachbarin verdient die schönsten Blumen.“"
  },
  AvgDialog_4882_Content_35 = {
    Text = "<Italic:Einst in voller Blüte, für immer strahlend...>"
  },
  AvgDialog_4882_Content_36 = {
    Text = "Danke für die Nachricht... Ich werde das letzte Gedicht für ihre Geschichte verfassen."
  },
  AvgDialog_4882_Content_37 = {
    Text = "Horla beugte sich hinab, ihre Fingerspitzen streiften Lilys Stirn, den Duft üppiger Blütenblätter und die Kühle von Wasser mit sich tragend."
  },
  AvgDialog_4882_Content_38 = {
    Text = "Nimm sie mit, um die Geschichten zu finden, in die Stadt, in die Natur, in ihre Zukunft, in ihre Vergangenheit..."
  },
  AvgDialog_4882_Content_39 = {
    Text = "Geschichten werden dich unerwartet finden."
  },
  AvgDialog_4882_Content_4 = {
    Text = "Horla kauert neben dem A-Schleim, den der Mutant hinterlassen hat, streckt die Hand aus und fährt mit ihr durch die Luft darüber."
  },
  AvgDialog_4882_Content_5 = {
    Text = "Ihr Vater und ihr Bruder kamen beide bei einem Grubenunglück ums Leben, doch sie hielt die Familie tapfer zusammen."
  },
  AvgDialog_4882_Content_6 = {
    Text = "Die Rose erstarrt im Schlamm und blüht still in ihrer nach oben geöffneten Handfläche."
  },
  AvgDialog_4882_Content_7 = {
    Text = "Sie erbte den Blumenladen ihrer Großmutter und sorgte für sich und ihre kranke Mutter... Sie hätte ein glückliches und friedliches Ende verdient."
  },
  AvgDialog_4882_Content_8 = {
    Text = "Wenn... sie mich nicht getroffen hätte..."
  },
  AvgDialog_4882_Content_9 = {
    Text = "Horla senkte den Blick und sah zu, wie die Auflösungsblume verwelkte und fiel..."
  },
  AvgDialog_4883_Content_1 = {
    Text = "Kann Aurita auch Geschichten erzählen? Aurita hat Geschichten!"
  },
  AvgDialog_4883_Content_10 = {
    Text = "Das Meer..."
  },
  AvgDialog_4883_Content_11 = {
    Text = "Das letzte Mal, als ich das Meer gesehen habe, war auf dem Weg, als ich mit meiner Mama das Schneefeld verließ..."
  },
  AvgDialog_4883_Content_12 = {
    Text = "Hat Lily auch eine Geschichte? Aurita will deine hören!"
  },
  AvgDialog_4883_Content_13 = {
    Text = "Handlung... Bevor Mama krank wurde, hat sie mir oft Gute-Nacht-Geschichten erzählt."
  },
  AvgDialog_4883_Content_14 = {
    Text = "Aber ich... ich kann mich auch nicht erinnern."
  },
  AvgDialog_4883_Content_15 = {
    Text = "Lily, du Frechdachs—!"
  },
  AvgDialog_4883_Content_16 = {
    Text = "Du musst dich mehr anstrengen! Denk sorgfältig nach!"
  },
  AvgDialog_4883_Content_17 = {Text = "Aber..."},
  AvgDialog_4883_Content_18 = {
    Text = "Lily, das ist so unfair. Willst du dich etwa drücken?"
  },
  AvgDialog_4883_Content_19 = {
    Text = "Aurita schwänzt den Unterricht und bekommt doppelte Hausaufgaben, während Lily schwänzt und doppelte Handlungen bekommt!"
  },
  AvgDialog_4883_Content_2 = {
    Text = "Vor langer—langer Zeit hat Oma gesagt, dass Aurita ein Kind des Meeres ist!"
  },
  AvgDialog_4883_Content_20 = {Text = "?!"},
  AvgDialog_4883_Content_21 = {
    Text = "Na, das klingt großartig! Du hängst immer nur mit Lotan und {Male=Mr., Female=Miss} „Ashe“ ab und spielst nie mit uns."
  },
  AvgDialog_4883_Content_22 = {
    Text = "Nutze die Gelegenheit und lass alle mal was von dir haben!"
  },
  AvgDialog_4883_Content_23 = {
    Text = "Quiek! Quiek, quiek!"
  },
  AvgDialog_4883_Content_24 = {
    Text = "Drehbuch! Drehbuch! Lily schreibt das Drehbuch!"
  },
  AvgDialog_4883_Content_25 = {
    Text = "Drehbuch! Drehbuch! Lily schreibt das Drehbuch!"
  },
  AvgDialog_4883_Content_3 = {
    Text = "Auritas Eltern sind ins Unterwasserkönigreich zurückgekehrt. Wenn Aurita groß ist, wird sie sich mit ihnen wiedervereinen."
  },
  AvgDialog_4883_Content_4 = {
    Text = "Sie machen sich bestimmt Sorgen um Aurita, also wird Aurita ganz, ganz viele Freunde mitbringen!\nHündchen, Kätzchen, Krähen, Schutzherren... und Auritas Lieblingsquallen!"
  },
  AvgDialog_4883_Content_5 = {
    Text = "Jetzt wissen sie, dass Aurita auch das Leben an Land genießt!"
  },
  AvgDialog_4883_Content_6 = {
    Text = "Da scheinen einige Wesen dabei zu sein, die nicht fürs Meer geeignet sind..."
  },
  AvgDialog_4883_Content_7 = {
    Text = "Gehöre ich auch zu denen, die mit ins Meer genommen werden?"
  },
  AvgDialog_4883_Content_8 = {
    Text = "Ja! Ja, ja! Der Schutzherr ist Auritas Begleiter! Lily will auch mitkommen!"
  },
  AvgDialog_4883_Content_9 = {Text = "...!"},
  AvgDialog_4884_Content_1 = {
    Text = "Unter der Führung von Casiah haltet ihr vor dem größten Kaufhaus in Londinium, umgeben von geschäftigen Kunden"
  },
  AvgDialog_4884_Content_10 = {
    Text = "Fast vergessen, es sind zwei verschlossene Typen"
  },
  AvgDialog_4884_Content_11 = {
    Text = "Casiah zog sich hinter die anderen zurück und schob die seit langem stumme Lily nach vorne"
  },
  AvgDialog_4884_Content_12 = {
    Text = "Guten Morgen, Lady Narzisse."
  },
  AvgDialog_4884_Content_13 = {
    Text = "Guten Morgen, mein kleiner Gast. Lass mich raten, warum ihr diesmal hier seid"
  },
  AvgDialog_4884_Content_14 = {
    Text = "„Film, der das Bild des Erwachens aufzeichnet\"... Ich kann solche Gegenstände für die Gäste finden"
  },
  AvgDialog_4884_Content_15 = {
    Text = "Woher weißt du das? Hast du uns wieder jemanden hinterherschicken lassen?!"
  },
  AvgDialog_4884_Content_16 = {
    Text = "Wie hätte ich vorhersehen können, dass ihr den kostbaren Film versehentlich beschädigt?"
  },
  AvgDialog_4884_Content_17 = {
    Text = "Daffodil legte mit einem geheimnisvollen und unergründlichen Lächeln das, was ihr begehrtet, auf den Tresen."
  },
  AvgDialog_4884_Content_18 = {
    Text = "Dieser mit hochreiner Silberkernquellflüssigkeit verarbeitete Film kann das Aussehen von Erweckten normal einfangen. Sehr kostbar. Nur ein Exemplar im Laden verfügbar."
  },
  AvgDialog_4884_Content_19 = {
    Text = "War das nicht der Spezialfilm aus <Yellow:Dolls neuer Forschung>? Woher hast du den?"
  },
  AvgDialog_4884_Content_2 = {
    Text = "Das ist zu lebhaft. Warum hat die Frau den Laden hier geparkt?"
  },
  AvgDialog_4884_Content_20 = {
    Text = "Der Händler, der durch Dimensionen reist, hat besondere Kanäle.\nSchau mich nicht so misstrauisch an; das bricht mir das Herz."
  },
  AvgDialog_4884_Content_21 = {
    Text = "Wie sieht's aus? Wenn ihr ihn nicht braucht, räume ich ihn wieder weg."
  },
  AvgDialog_4884_Content_22 = {
    Text = "In Ordnung, wir nehmen ihn."
  },
  AvgDialog_4884_Content_23 = {
    Text = "Lily drückte deine Hand, ein Hauch von Unbehagen in ihren Augen."
  },
  AvgDialog_4884_Content_24 = {
    Text = "Austauschhändler... Muss die Dame belohnen."
  },
  AvgDialog_4884_Content_25 = {
    Text = "Ah, Lily erinnert sich noch an die Regeln hier."
  },
  AvgDialog_4884_Content_26 = {
    Text = "Keine Sorge, ich verlange diesmal nicht viel — ich möchte nur die „Handlung“ sehen."
  },
  AvgDialog_4884_Content_27 = {
    Text = "Eine brillante, vollständige und reuelose Handlung.\nDas ist es, was ich im Austausch möchte."
  },
  AvgDialog_4884_Content_3 = {
    Text = "„Um eine Karo 6 zu verstecken, mische sie in ein Deck.“"
  },
  AvgDialog_4884_Content_4 = {
    Text = "Casiah führt euch neben das Warenhaus und öffnet als Erste die Tür.\nEin Schwall lila Rauch zieht alle hinein"
  },
  AvgDialog_4884_Content_5 = {
    Text = "Willkommen zurück in meinem „Austauschladen“, meine geehrten Gäste, und"
  },
  AvgDialog_4884_Content_6 = {
    Text = "Und meine lieben „Mitarbeiter“.\nWie ist das Leben in Missaga, hast du echte Gefühle gelernt?"
  },
  AvgDialog_4884_Content_7 = {
    Text = "Danke für Ihre Großzügigkeit, aber von lauten kleinen Mäusen, unwissenden Einzellern, arroganten Gewalttätigen und verschlossenen Leuten kann ich wirklich nichts lernen"
  },
  AvgDialog_4884_Content_8 = {
    Text = "Wer hat hier Lärm gemacht?!"
  },
  AvgDialog_4884_Content_9 = {
    Text = "Meinst du mich mit „Sturkopf“?"
  },
  AvgDialog_4885_Content_2 = {
    Text = "Hör auf! Lass dieses Mädchen los!"
  },
  AvgDialog_4885_Content_3 = {
    Text = "Oh? Könntet Ihr etwa der berühmte... <Blue:Kommissar G von der Gartenabteilung der Lentiniëner Polizei> sein?"
  },
  AvgDialog_4885_Content_4 = {
    Text = "J–Ja, ich bin der <Blue:Oberkommissar Hua der Lentiniëner Polizeibehörde... mmph!>"
  },
  AvgDialog_4885_Content_5 = {
    Text = "Der umständliche Titel brachte den Detektiv dazu, sich auf die Zunge zu beißen, doch das wird seine Entschlossenheit, unschuldige Bürger zu retten, nicht beeinträchtigen."
  },
  AvgDialog_4885_Content_6 = {
    Text = "Ich werde sie aus Euren finsteren Machenschaften befreien! Stellt Euch der Gerechtigkeit, Zauberin Houdini!"
  },
  AvgDialog_4886_Content_1 = {Text = "Ah...!"},
  AvgDialog_4886_Content_2 = {
    Text = "<Small:Es ist kaputt...>"
  },
  AvgDialog_4886_Content_3 = {
    Text = "Nochmal, nochmal! Hat Casiah nicht auch Spaß!"
  },
  AvgDialog_4886_Content_4 = {
    Text = "Unverschämter Mistkerl! Ich reiße dich in Stücke! Du wirst keinen Platz in der Welt des Films haben!"
  },
  AvgDialog_4886_Content_5 = {
    Text = "Sch, sch! Provozier Fräulein Casiah nicht noch weiter."
  },
  AvgDialog_4886_Content_6 = {
    Text = "Da alle Aufmerksamkeit auf den chaotischen Kampf gerichtet war, blieb das leise Keuchen unbemerkt."
  },
  AvgDialog_4886_Content_7 = {
    Text = "Lily atmete tief ein und schrie mit all ihrer Kraft."
  },
  AvgDialog_4886_Content_8 = {
    Text = "Es ist kaputt... <BigShake:Die Maschine ist kaputt!>"
  },
  AvgDialog_4887_Content_1 = {
    Text = "Der Pfleger überwältigte geübt den tobenden Patienten und fixierte schnell dessen Gliedmaßen mit Ledergurten.\nErst als er fertig war, bemerkte er die Anwesenheit eines Außenstehenden und kratzte sich verlegen am Kopf."
  },
  AvgDialog_4887_Content_10 = {
    Text = "Es gibt große Mengen unsichtbaren A-Schleims — möglicherweise die Quelle des Wahnsinns."
  },
  AvgDialog_4887_Content_2 = {
    Text = "Seien Sie vorsichtig. Die Patienten sind heute besonders unberechenbar. Lassen Sie sich nicht von ihnen verletzen."
  },
  AvgDialog_4887_Content_3 = {
    Text = "Kollektiver Wahnsinn? Kommt das häufig vor?"
  },
  AvgDialog_4887_Content_4 = {
    Text = "Die in der Anstalt Zurückgelassenen haben Seelen, so zerbrechlich wie Papier, das sieben Tage und Nächte in der Sonne lag — sie zerreißen beim leisesten Windhauch. Plötzliche Ausbrüche kollektiven Wahnsinns sind hier nichts Ungewöhnliches."
  },
  AvgDialog_4887_Content_5 = {
    Text = "Lass uns gehen. Die verantwortliche Person sollte auf diesem Stockwerk sein."
  },
  AvgDialog_4887_Content_6 = {
    Text = "Hey! Pass auf!"
  },
  AvgDialog_4887_Content_7 = {
    Text = "Du hast den Pfleger plötzlich gestoßen, der ein paar Schritte zurücktaumelte und dich mit einem verwirrten Blick ansah."
  },
  AvgDialog_4887_Content_8 = {
    Text = "Da ist etwas Wasser; gehen wir am Rand des Korridors entlang."
  },
  AvgDialog_4887_Content_9 = {
    Text = "Der Pfleger fragte nicht weiter nach und mied die Richtung, die du angegeben hattest. Nur du atmest insgeheim erleichtert auf."
  },
  AvgDialog_4888_Content_1 = {
    Text = "Sicherheitsteam, unterstützt Ms. Ellie dabei, die Patienten aus dem Hof zurück in ihre Zimmer zu bringen. \nDaisy, bereite die Komfortartikel und Toilettenartikel der Patienten vor."
  },
  AvgDialog_4888_Content_10 = {
    Text = "Danke, dass du mir eine lang vermisste Freundin aus der Ferne gebracht hast."
  },
  AvgDialog_4888_Content_11 = {
    Text = "„Danke“ zu sagen ist zu förmlich. Lasst uns zuerst den Vorfall auf der Station klären."
  },
  AvgDialog_4888_Content_12 = {
    Text = "Die Sanitäter gaben Nymphaea ein Zeichen und verließen, nachdem sie ihr zustimmendes Nicken erhalten hatten, nacheinander das Büro."
  },
  AvgDialog_4888_Content_13 = {
    Text = "Es scheint, dass du hier nach dem Höllenhund–Vorfall gute Arbeit geleistet hast."
  },
  AvgDialog_4888_Content_14 = {
    Text = "Dank dir und Fräulein Ramona konnte das Sanatorium reibungslos weiterbetrieben werden."
  },
  AvgDialog_4888_Content_15 = {
    Text = "Gibt es etwas, das euch so spät in der Nacht hergeführt hat?"
  },
  AvgDialog_4888_Content_16 = {
    Text = "Ihr erklärtet dem blassen Mädchen die Dreharbeiten, das Drehbuch und Lily..."
  },
  AvgDialog_4888_Content_17 = {
    Text = "Verstehe... Ihr wollt eine Geschichte erschaffen?\nIch kann keine Gedichte oder Drehbücher schreiben, aber ich habe reichlich Geschichten gelesen."
  },
  AvgDialog_4888_Content_18 = {
    Text = "Nymphaea schloss die Augen und sprach leise, als würde sie rezitieren."
  },
  AvgDialog_4888_Content_19 = {
    Text = "Am wichtigsten ist das <Yellow:Zuhören>, nicht wahr?\nHöre auf die Stimme in deinem Inneren, folge dem Fluss der Emotionen... Sie werden dich zur Antwort führen."
  },
  AvgDialog_4888_Content_2 = {
    Text = "Mr. Jackson, bitte... helfen Sie, die Kartoffeln fürs Curry zu schneiden. Verschwenden Sie sie nicht."
  },
  AvgDialog_4888_Content_20 = {
    Text = "Lily hört zu und denkt nach, versucht Nymphaeas Worte zu verstehen."
  },
  AvgDialog_4888_Content_21 = {
    Text = "Mitten in ihrem Gespräch drang ein gedämpftes Wehklagen von unten herauf. Lily, die tief in Gedanken versunken war, erschrak und stieß gegen Nymphaeas Bein."
  },
  AvgDialog_4888_Content_22 = {
    Text = "Er klingt, als hätte er Schmerzen..."
  },
  AvgDialog_4888_Content_23 = {
    Text = "Die Patienten hier erleiden plötzliche, unvorhersehbare Verschlechterungen ihres Zustands, aber sie erholen sich normalerweise innerhalb eines halben Tages...\nEntschuldigt die Unannehmlichkeiten."
  },
  AvgDialog_4888_Content_24 = {
    Text = "Ihr könnt die Misaq Universität um Ermittlungshilfe bitten. Lorde Dexter sollte Kontaktdaten hinterlassen haben."
  },
  AvgDialog_4888_Content_25 = {
    Text = "Ich kenne den Grund für die Mutation, und ich fürchte, es ist ein Problem, das selbst Misaq nicht lösen kann."
  },
  AvgDialog_4888_Content_26 = {
    Text = "Ich werde bei der „Säuberung“ helfen. Möchtest du dich mir anschließen?"
  },
  AvgDialog_4888_Content_3 = {
    Text = "Hat jemand Mr. Robert gesehen? Ist jemand losgegangen, um nach ihm zu suchen? Soweit ich weiß, ist er heute Nacht für die zweite Station zuständig..."
  },
  AvgDialog_4888_Content_4 = {
    Text = "Ich bin hier, Miss Nymphaea."
  },
  AvgDialog_4888_Content_5 = {
    Text = "Diejenige, die die medizinische Arbeit systematisch organisiert, ist Nymphaea, die ihr bereits kennengelernt habt.\nAls sie euch im Sanatorium sieht, zeigt ihr Gesicht einen überraschten Ausdruck."
  },
  AvgDialog_4888_Content_6 = {
    Text = "Es bist du... und Lily."
  },
  AvgDialog_4888_Content_7 = {
    Text = "Schwester Nymphaea."
  },
  AvgDialog_4888_Content_8 = {
    Text = "Warum habt ihr beiden nicht früher erwähnt, dass ihr Fräulein Polonaise kennt? Ich hätte sie fast für eine Betrügerin gehalten."
  },
  AvgDialog_4888_Content_9 = {
    Text = "Nymphaea kicherte leise und nahm Lilys Hand."
  },
  AvgDialog_4889_Content_1 = {
    Text = "Perfektes Finale"
  },
  AvgDialog_4889_Content_10 = {
    Text = "Sie besuchte die Kunstausstellung, ging in den Zoo, fuhr mit der U-Bahn und dem Zug. Sie segelten sogar die Isis hinunter und stürzten sich in den weiten südlichen Ozean!"
  },
  AvgDialog_4889_Content_11 = {
    Text = "Nachdem sie alle möglichen Abenteuer erlebt hatten, begannen die beiden ein friedliches und ruhiges Leben... Doch das Mädchen bewahrte sich ihre Neugier und Sehnsucht nach dem Unbekannten."
  },
  AvgDialog_4889_Content_12 = {
    Text = "Neugier... Ist das etwas Schlechtes?"
  },
  AvgDialog_4889_Content_13 = {
    Text = "Nein, nein, nein, es ist definitiv etwas Gutes. Neugier ist die ewige treibende Kraft, die die Zivilisation vorantreibt—"
  },
  AvgDialog_4889_Content_14 = {
    Text = "Leider wurde das Mädchen diesmal neugierig auf einen mysteriösen Fang..."
  },
  AvgDialog_4889_Content_15 = {
    Text = "Ein vielsagender Blick zu Casiah"
  },
  AvgDialog_4889_Content_16 = {
    Text = "Du zwinkert Casiah zu und reißt die Magierin aus ihrer Benommenheit, nachdem du das Megafon genommen hast."
  },
  AvgDialog_4889_Content_17 = {
    Text = "Warum muss ich schon wieder der große Dämonenlord sein?"
  },
  AvgDialog_4889_Content_18 = {
    Text = "Aus Unterstützung für deine Arbeit — oder einfach um einen Streich zu spielen — murrte sie, kooperierte aber dennoch und beschwor erneut die magische Illusion herauf."
  },
  AvgDialog_4889_Content_19 = {
    Text = "Die Magie-Werkstatt wurde von einem unheimlichen und finsteren Licht erhellt. Das seltsame Leuchten entzog der Welt der Lebenden die Lebenskraft und ließ einen sich fühlen, als wäre man in der Unterwelt."
  },
  AvgDialog_4889_Content_2 = {Text = "Zisch—!"},
  AvgDialog_4889_Content_20 = {
    Text = "Ich bin Houdini, der Großmagier aus der Welt der Toten. Dieses hübsche kleine Mädchen ist mein liebstes Magie-Requisit. Tapfere Abenteurer, habt ihr den Mut, mich herauszufordern?"
  },
  AvgDialog_4889_Content_21 = {
    Text = "Fräulein Casiah...?"
  },
  AvgDialog_4889_Content_22 = {
    Text = "Houdini! Meistermagier Houdini! Du solltest vor Angst zittern und den Verstand verlieren!"
  },
  AvgDialog_4889_Content_23 = {
    Text = "Unter deinem und Casiahs erwartungsvollen Blick schluckte Lily mechanisch ein paar Mal—"
  },
  AvgDialog_4889_Content_24 = {
    Text = "Komm, komm..."
  },
  AvgDialog_4889_Content_25 = {
    Text = "Sprich lauter! Schrei! Lass mich die Angst aus den Tiefen deiner Seele hören!"
  },
  AvgDialog_4889_Content_26 = {
    Text = "<BigShake:Hilfe! Jemand, helft mir — Mutter!>"
  },
  AvgDialog_4889_Content_3 = {
    Text = "Was ist das für ein Geräusch?!"
  },
  AvgDialog_4889_Content_4 = {
    Text = "Lotan schirmte instinktiv die kleinen Erwecker ab und umklammerte wachsam den Schwertgriff mit beiden Händen."
  },
  AvgDialog_4889_Content_5 = {
    Text = "Entschuldigung, ich benutze diesen Lautsprecher zum ersten Mal."
  },
  AvgDialog_4889_Content_6 = {
    Text = "Willst du noch ein bisschen länger spielen?"
  },
  AvgDialog_4889_Content_7 = {
    Text = "Du schütteltest den Kopf, drücktest erneut den Schalter des Lautsprechers und richtetest das Licht auf die Mitte der Bühne."
  },
  AvgDialog_4889_Content_8 = {
    Text = "Das tapfere Mädchen und die Abenteurerin kehrten in die Stadt zurück. Die Abenteurerin behandelte das Mädchen wie ihr eigenes Kind und teilte unzählige Lebenserfahrungen mit ihr—"
  },
  AvgDialog_4889_Content_9 = {
    Text = "Lilys Augen leuchteten plötzlich auf. Sie riss sie weit auf und zeigte einen Ausdruck des Unglaubens."
  },
  AvgDialog_4890_Content_1 = {
    Text = "<Change>Ich will nicht... fortgehen... von zu Hause..."
  },
  AvgDialog_4890_Content_2 = {
    Text = "<Change>Tod... nein..."
  },
  AvgDialog_4890_Content_3 = {
    Text = "Ein schweres Gefühl umklammert deine Knöchel, zerrt dich in einen unsichtbaren Abgrund und macht selbst das Atmen schwer."
  },
  AvgDialog_4890_Content_4 = {
    Text = "Lily spürt ein schweres Gewicht auf ihrer Brust, und es lässt sie sich furchtbar fühlen..."
  },
  AvgDialog_4890_Content_5 = {
    Text = "Verzeiht, dass ich Euch Unbehagen bereitet habe."
  },
  AvgDialog_4890_Content_6 = {
    Text = "Hüter, bitte hilf mir, sie zu besiegen."
  },
  AvgDialog_4891_Content_1 = {
    Text = "Die junge Dichterin schüttelte den Kopf, ihr Ton kummervoll und trostlos. Ohne es zu bemerken, hatte sie sich unter den Brief zurückgezogen und eine Spur von Traurigkeit offenbart."
  },
  AvgDialog_4891_Content_2 = {
    Text = "Gehüllt in Schatten der Trauer, könnten meine Dichtung und Inspiration... dem Schutzherrn und Lily von keinem Nutzen sein."
  },
  AvgDialog_4891_Content_3 = {
    Text = "Ein kummervoller... Schatten?"
  },
  AvgDialog_4891_Content_4 = {
    Text = "Angesichts Lilys verwirrtem Gesichtsausdruck stieß Horla einen kaum hörbaren Seufzer aus."
  },
  AvgDialog_4891_Content_5 = {
    Text = "Wenn es möglich ist, erlaubt mir, es Euch zu zeigen..."
  },
  AvgDialog_4891_Content_6 = {
    Text = "Horla stieß die Tür auf und hielt die Außenwelt nicht länger fern, als dicke, abgestandene Luft in den Raum strömte."
  },
  AvgDialog_4891_Content_7 = {
    Text = "Was ist „der Schatten der Trauer“?"
  },
  AvgDialog_4892_Content_1 = {
    Text = "<Change>Die neue Nachbarin am Ende der Straße... talentiert..."
  },
  AvgDialog_4892_Content_2 = {
    Text = "<Change>Die schönste Blume... Sie..."
  },
  AvgDialog_4892_Content_3 = {
    Text = "<Change>Meine Blume... ein Gedicht..."
  },
  AvgDialog_4892_Content_4 = {
    Text = "<Gray:Renny Stadt litt einst unter einer schweren Auflösung Clades; vielleicht verweilen die Stimmen der verlorenen Bewohner hier noch...>"
  },
  AvgDialog_4893_Content_1 = {
    Text = "<Change>Ich bin... ich bin krank..."
  },
  AvgDialog_4893_Content_2 = {
    Text = "Wer ist da?!"
  },
  AvgDialog_4893_Content_3 = {
    Text = "Dahinter war nichts, nur der Wind, der ein schweres, klagevolles Geräusch mit sich trug."
  },
  AvgDialog_4893_Content_4 = {
    Text = "Hast du etwas gehört?"
  },
  AvgDialog_4893_Content_5 = {
    Text = "Nein... vielleicht ein Trugbild."
  },
  AvgDialog_4894_Content_1 = {
    Text = "Nutzlos! Inkompetent! Ihr habt alle Statisten von Casiah vertrieben!"
  },
  AvgDialog_4894_Content_10 = {
    Text = "Im letzten Moment schwang Ogier seinen Speer und zerstreute das tobende Kaninchen in einen Schleier aus Schatten."
  },
  AvgDialog_4894_Content_11 = {
    Text = "Nervig! Nervig! Wer nicht kooperiert, hat keinen Platz an Casiahs Set!"
  },
  AvgDialog_4894_Content_12 = {
    Text = "\nEs scheint, als würde sie mit ihrer „emotionalen Nachahmung„ nicht aufhören, solange sie keine Abreibung bekommt.\nDiesmal kannst du mich nicht als „Kampfmaniac„ bezeichnen, oder?"
  },
  AvgDialog_4894_Content_13 = {
    Text = "Wir sollten sie von jetzt an weniger von diesen bunten Zeitschriften lesen lassen..."
  },
  AvgDialog_4894_Content_2 = {
    Text = "Extras? Aurita weiß es, Aurita weiß es!"
  },
  AvgDialog_4894_Content_3 = {
    Text = "Aurita allein ist wie eine ganze Schauspieltruppe!"
  },
  AvgDialog_4894_Content_4 = {
    Text = "Du kleiner Frechdachs bist wirklich—"
  },
  AvgDialog_4894_Content_5 = {
    Text = "„Die ‚Regisseurin' schwang wütend den Zauberstab, wodurch Requisiten und Karten umherflogen und deutliche Kratzer auf verschiedenen Gegenständen hinterließen.“"
  },
  AvgDialog_4894_Content_6 = {Text = "Ah—!"},
  AvgDialog_4894_Content_7 = {
    Text = "Das Phantomkaninchen kracht in die Kulisse und richtet seinen Blick schließlich auf Aurita, um direkt auf sie loszustürmen."
  },
  AvgDialog_4894_Content_8 = {Text = "Vorsicht!"},
  AvgDialog_4895_Content_1 = {
    Text = "Am meisten vermisst"
  },
  AvgDialog_4895_Content_10 = {
    Text = "Sobald der Raum geöffnet wird, wird der darin gefangene Dimensionshund das Zeitsiegel durchbrechen.\nDer aktuelle Zustand von Franz darin ist völlig unbekannt"
  },
  AvgDialog_4895_Content_11 = {
    Text = "Du kannst Lily keine Versprechen machen, noch möchtest du Versprechen geben, die nicht gehalten werden können."
  },
  AvgDialog_4895_Content_2 = {
    Text = "Es ist eine Weile her seit deinem letzten Besuch. Obwohl die Landschaft unverändert geblieben ist, trägt die Luft nicht mehr eine Aura der Anspannung und des Zitterns."
  },
  AvgDialog_4895_Content_3 = {
    Text = "Dieser Ort, einst vom Schatten der „Höllenhunde\" umhüllt, scheint wahren Frieden wiedergefunden zu haben."
  },
  AvgDialog_4895_Content_4 = {
    Text = "Lily, alles in Ordnung?"
  },
  AvgDialog_4895_Content_5 = {
    Text = "Obwohl Lily normalerweise ein ruhiges Kind ist, hat sie seit dem Betreten der Stadt Lai kein einziges Wort gesagt."
  },
  AvgDialog_4895_Content_6 = {
    Text = "In deiner Brust breitet sich eine Welle des Unbehagens aus. Unruhe, Freude, Angst... Ein Gemisch aus Emotionen, das durch die Verbindung deine Nerven durchströmt."
  },
  AvgDialog_4895_Content_7 = {
    Text = "Meister... Wird Lily dieses Mal ihre Mutter sehen können?"
  },
  AvgDialog_4895_Content_8 = {
    Text = "Obwohl Lily nicht gewachsen ist... waren wir so lange fort. Wird sie Lily noch erkennen?"
  },
  AvgDialog_4895_Content_9 = {
    Text = "Als du in Lilys Augen blicktest, die schwach vor Vorfreude funkelten, streicheltest du sanft über ihr seidenweiches Haar und führtest sie zum anderen Ende der Eisenbahnbrücke—"
  },
  AvgDialog_4896_Content_1 = {
    Text = "Dieser Kerl hat endlich aufgehört, so steif wie ein Holzklotz zu sein."
  },
  AvgDialog_4896_Content_2 = {
    Text = "Der Meister war nie hölzern, {Male=he,Female=she} ist nur, nur ein bisschen..."
  },
  AvgDialog_4896_Content_3 = {
    Text = "Beständig? Reif? Oder meinst du langweilig?"
  },
  AvgDialog_4896_Content_4 = {
    Text = "So habe ich das nie gemeint!"
  },
  AvgDialog_4896_Content_5 = {
    Text = "Als Lotan sah, wie Ogiers Gesicht schon nach wenigen Worten rot anlief, lachte er herzlich und schubste den jungen Ritter plötzlich ins Rampenlicht."
  },
  AvgDialog_4896_Content_6 = {
    Text = "Gesell dich jetzt zu ihnen; ohne dich wäre dieses Videoband nicht vollständig."
  },
  AvgDialog_4897_Content_1 = {
    Text = "Ihr habt Casiahs Magie–Skript beleidigt!! Alle... <Big:Hört auf die Regisseurin und arbeitet mit mir zusammen!>"
  },
  AvgDialog_4897_Content_2 = {
    Text = "<Yellow:„Daffodils Führer zum Umgang mit Casiah\"> Auf der ersten Seite steht, Casiah hat eine <Yellow:emotionale Störung>, und all ihre emotionalen Ausdrücke sind nur Nachahmungen"
  },
  AvgDialog_4897_Content_3 = {
    Text = "Woher kommt dann ihre Wut?"
  },
  AvgDialog_4897_Content_4 = {
    Text = "<Big:Probier die <Red:Kraft von Andy Johnson>!>"
  },
  AvgDialog_4897_Content_5 = {
    Text = "Andy Johnson? Der Name kommt mir bekannt vor... Wo habe ich ihn schon mal gehört..."
  },
  AvgDialog_4897_Content_6 = {
    Text = "Ich kenne diesen Namen!! Das ist ein berühmter Regisseur aus Oakwood in der Agro-Republik!"
  },
  AvgDialog_4897_Content_7 = {
    Text = "Ich habe die Tanten auf dem Markt über ihn reden hören, sie sagten, er hätte letztes Jahr seinen Fotoassistenten ins Krankenhaus geschickt!!"
  },
  AvgDialog_4897_Content_8 = {
    Text = "Zumindest wissen wir jetzt, wen sie imitiert..."
  },
  AvgDialog_4898_Content_1 = {
    Text = "Schönste Blüte"
  },
  AvgDialog_4898_Content_10 = {
    Text = "Lily, du... kannst nicht lesen?"
  },
  AvgDialog_4898_Content_11 = {
    Text = "Lily... Ich..."
  },
  AvgDialog_4898_Content_12 = {
    Text = "Lily senkte den Kopf, zögerte einen Moment und nickte schließlich, ihr Gesicht voller Unbehagen."
  },
  AvgDialog_4898_Content_13 = {
    Text = "Schreiben, das hat Mutter mir beigebracht. Aber... Lily erinnert sich nicht mehr daran.\nGeschichten und Drehbücher, Lily kann sie auch nicht schreiben."
  },
  AvgDialog_4898_Content_14 = {
    Text = "Hab keine Angst; ich dränge dich nicht.\nLass es uns zusammen machen."
  },
  AvgDialog_4898_Content_15 = {
    Text = "Lily, kannst du mir erzählen, wovon diese Geschichte handelt?"
  },
  AvgDialog_4898_Content_16 = {
    Text = "Die Geschichte von Mutter, Kum und Lily."
  },
  AvgDialog_4898_Content_17 = {
    Text = "Mit welchem Ereignis beginnt die Geschichte? Hmm... Anders gesagt, wann möchte Lily anfangen, sie zu erzählen?"
  },
  AvgDialog_4898_Content_18 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_4898_Content_19 = {
    Text = "Nicht sicher..."
  },
  AvgDialog_4898_Content_2 = {
    Text = "Lily saß am Schminktisch, ihre Füße baumelten hin und her, ohne den Boden zu erreichen."
  },
  AvgDialog_4898_Content_20 = {
    Text = "Hüter, komm einen Moment mit mir."
  },
  AvgDialog_4898_Content_21 = {
    Text = "Lotan zog dich an den Rand des Sets und sah dich missbilligend an."
  },
  AvgDialog_4898_Content_22 = {
    Text = "Die Vergangenheit dieses Kindes ist es nicht wert, in Erinnerungen zu schwelgen. Sie das in eine Geschichte schreiben zu lassen, scheint nicht angemessen, oder?"
  },
  AvgDialog_4898_Content_23 = {
    Text = "Du sitzt hier schon einen halben Tag, ohne etwas zu schreiben. Wenn du mich fragst, warum nimmst du Lily nicht mit nach draußen auf einen Spaziergang und findest andere Inspiration?"
  },
  AvgDialog_4898_Content_24 = {
    Text = "Lilys scharfe Ohren fingen ihren Namen auf. Sie sprang mit einem Stift in der Hand vom Stuhl und huschte wie ein kleines Tier an deine Seite."
  },
  AvgDialog_4898_Content_25 = {
    Text = "Lotan wuschelte dem Mädchen durchs Haar und reichte dir den Buntstift."
  },
  AvgDialog_4898_Content_26 = {
    Text = "Geht raus und genießt die Landschaft, lass sie mit jemandem plaudern, der schreiben kann. Was dich betrifft..."
  },
  AvgDialog_4898_Content_27 = {
    Text = "Einfach ihr folgen und ihre Inspirationen aufschreiben."
  },
  AvgDialog_4898_Content_28 = {
    Text = "Meister, wohin gehen wir?"
  },
  AvgDialog_4898_Content_29 = {
    Text = "Was „jemanden, der schreiben kann“ angeht... du solltest wirklich diese Person treffen gehen."
  },
  AvgDialog_4898_Content_3 = {
    Text = "Handlung... Handlung......"
  },
  AvgDialog_4898_Content_30 = {
    Text = "„Diese Person“?"
  },
  AvgDialog_4898_Content_31 = {
    Text = "Eine talentierte ältere Schwester. Lotan hat arrangiert, dass wir sie treffen, wenn der Bus die Endstation erreicht."
  },
  AvgDialog_4898_Content_32 = {
    Text = "Lily nickt unschuldig, hält deine Hand und schweigt."
  },
  AvgDialog_4898_Content_33 = {
    Text = "Das ist ihr zweites Mal in der U-Bahn. Anders als die Aufregung und Neugier beim ersten Mal bleibt sie diesmal dicht bei dir, brav und doch vorsichtig, ganz wie ein kleines Tier, das sich an die Umarmung seiner Mutter schmiegt."
  },
  AvgDialog_4898_Content_4 = {
    Text = "Sie murmelte, während sie den Stift hielt, dessen Spitze über das Papier glitt und ein raschelndes Geräusch erzeugte."
  },
  AvgDialog_4898_Content_5 = {
    Text = "Mit ernstem und feierlichem Ausdruck sind die Pinselstriche kräftig und kraftvoll, das Papier durchdringend—"
  },
  AvgDialog_4898_Content_6 = {
    Text = "Doch was auf dem Papier zu sehen ist, ist kein Text; es ist lediglich eine einfache, kindliche Kritzelei."
  },
  AvgDialog_4898_Content_7 = {
    Text = "Ist das... Kum und Franz?"
  },
  AvgDialog_4898_Content_8 = {Text = "Ja...!"},
  AvgDialog_4898_Content_9 = {
    Text = "M-Meister..."
  },
  AvgDialog_4899_Content_1 = {
    Text = "Du und Lily klopftet an eine unauffällige Tür an der Straßenecke."
  },
  AvgDialog_4899_Content_10 = {
    Text = "Nein, nein, Fräulein Horla hat das missverstanden."
  },
  AvgDialog_4899_Content_11 = {
    Text = "Ihr seid wegen des Drehbuchs zu mir gekommen, nicht wahr?"
  },
  AvgDialog_4899_Content_12 = {
    Text = "Ja, aber nicht ganz."
  },
  AvgDialog_4899_Content_13 = {
    Text = "Du blickst hinunter zu Lily, die sich fast an dein Bein klammert, und schiebst sie sanft in Richtung Horla."
  },
  AvgDialog_4899_Content_14 = {
    Text = "<Italic:Ein unerwartetes Leben, erblühend jenseits der Grenzen der Zeit...>"
  },
  AvgDialog_4899_Content_15 = {
    Text = "Hallo, Lily."
  },
  AvgDialog_4899_Content_16 = {
    Text = "Hallo, sei gegrüßt!"
  },
  AvgDialog_4899_Content_17 = {
    Text = "Wir würden gerne deinen Rat einholen, wie man Geschichten erschafft."
  },
  AvgDialog_4899_Content_2 = {
    Text = "Willkommen aus der Ferne. Verzeiht, dass ich Euch nicht früher begrüßt habe..."
  },
  AvgDialog_4899_Content_3 = {
    Text = "Es war ein Rosenduft mit einem Hauch von Morgentau, der durch den Spalt der geöffneten Tür sickerte, heimlich und unaufhörlich strömend."
  },
  AvgDialog_4899_Content_4 = {
    Text = "Lange nicht gesehen, <Blue:Frau Horla>."
  },
  AvgDialog_4899_Content_5 = {
    Text = "Guten Morgen, Hüter."
  },
  AvgDialog_4899_Content_6 = {
    Text = "Wer ist dieser kleine Gast...?"
  },
  AvgDialog_4899_Content_7 = {
    Text = "Du erklärtest der Dichterin das Filmen, das Drehbuch und Lily..."
  },
  AvgDialog_4899_Content_8 = {
    Text = "Verstehe. Um Frau Dolls modifizierte Kamera zu testen, müsst ihr einen Film drehen..."
  },
  AvgDialog_4899_Content_9 = {
    Text = "Aber vielleicht erinnert Ihr Euch, ich bin nur eine unbedeutende Dichterin... Was das Schreiben von Drehbüchern angeht, bin ich weit davon entfernt, „qualifiziert“ zu sein."
  },
  AvgDialog_4900_Content_1 = {
    Text = "Große Illusion"
  },
  AvgDialog_4900_Content_10 = {Text = "Sonst was?"},
  AvgDialog_4900_Content_11 = {
    Text = "Wird von den echten Kulissen der Illusionen zerschmettert!"
  },
  AvgDialog_4900_Content_12 = {
    Text = "Habt ihr schon die Frau, die sowohl Ärztin als auch Psychologin an der Mythag Universität ist, gesehen?"
  },
  AvgDialog_4900_Content_13 = {
    Text = "Das ist ein hinterhältiger, listiger und böser Dämonenkönig. Es heißt, die Verletzten, die zu ihr gehen, kommen am Ende liegend heraus"
  },
  AvgDialog_4900_Content_14 = {
    Text = "Das, das wurde nicht aufgenommen, oder?"
  },
  AvgDialog_4900_Content_15 = {
    Text = "Ogier blickte nervös zu dir, der die Kamera hielt, und atmete erleichtert auf, als er eine bestätigende Antwort erhielt"
  },
  AvgDialog_4900_Content_16 = {
    Text = "Miss Sylvia ist sehr sanft zu verletzten Schülern..."
  },
  AvgDialog_4900_Content_17 = {
    Text = "Wenn alle bereit sind, dann lasst uns mit dem Filmen beginnen"
  },
  AvgDialog_4900_Content_18 = {
    Text = "Juhu— Fotoshooting~ Fotoshooting~"
  },
  AvgDialog_4900_Content_19 = {
    Text = "Aurita kommt hierher! Für diesen Teil müssen wir nicht auf die Bühne, lass uns erstmal außerhalb der Kamera warten—"
  },
  AvgDialog_4900_Content_2 = {
    Text = "Junge Schauspieler, seid ihr bereit!"
  },
  AvgDialog_4900_Content_20 = {
    Text = "Die erweckten Körper versteckten sich außerhalb der Kamera, du warfst einen letzten Blick auf das „Drehbuch“ mit nur wenigen Sätzen und gingst zu deinem vorgesehenen Auftrittsort"
  },
  AvgDialog_4900_Content_3 = {
    Text = "Geheimnisträger, bist du bereit!"
  },
  AvgDialog_4900_Content_4 = {
    Text = "Nicht blinzeln, halte den Atem an – na ja, jetzt kannst du atmen"
  },
  AvgDialog_4900_Content_5 = {
    Text = "Weil Casiahs Illusionsmagie dich sicherlich atemlos machen wird—!"
  },
  AvgDialog_4900_Content_6 = {
    Text = "Die Szenerie verzerrt sich, nach einem Moment der Zersplitterung fügen sich die Fragmente zu einer vertrauten Realität zusammen"
  },
  AvgDialog_4900_Content_7 = {
    Text = "Das, was ist das für Magie?!"
  },
  AvgDialog_4900_Content_8 = {
    Text = "Squeak, squeak squeak!"
  },
  AvgDialog_4900_Content_9 = {
    Text = "Pass gut auf deinen kleinen Dieb-Kameraden auf, Casiah's Illusionszauber sind nur eine Illusion... Handle hier vorsichtig, gehe auf keinen Fall wirklich in die Illusion, sonst"
  },
  AvgDialog_4901_Content_1 = {
    Text = "Gaben des Händlers"
  },
  AvgDialog_4901_Content_10 = {
    Text = "Die schwarze Box mit dem Film rollte zur Seite, und Licht schien durch den Spalt."
  },
  AvgDialog_4901_Content_11 = {
    Text = "Doll hat ausdrücklich gewarnt, dass der Film nicht dem Licht ausgesetzt werden darf... Das ist schlecht!"
  },
  AvgDialog_4901_Content_12 = {
    Text = "<Shake:Unsere Mission diesmal ist es, die von Doll modifizierte Kamera zu testen!>"
  },
  AvgDialog_4901_Content_13 = {
    Text = "Das ist nichts. Einfach eine neue Filmrolle im Kaufhaus kaufen."
  },
  AvgDialog_4901_Content_14 = {
    Text = "Dein Geldbeutel wird nicht mehr so dünn sein wie zuvor, oder, {Male=Mr., Female=Miss} „Ashe“?"
  },
  AvgDialog_4901_Content_15 = {
    Text = "Du klopftest auf deinen armen Geldbeutel und rechnest im Kopf den nächsten Stipendientag aus"
  },
  AvgDialog_4901_Content_16 = {
    Text = "Hat dein Beutel ein Loch? Soll ich versuchen, diesen verdammten Film zu „besorgen“?"
  },
  AvgDialog_4901_Content_17 = {
    Text = "Bitte, bewahrt etwas Würde für das Gesetz"
  },
  AvgDialog_4901_Content_18 = {
    Text = "Lass uns zum Kaufhaus gehen"
  },
  AvgDialog_4901_Content_2 = {Text = "Was?!"},
  AvgDialog_4901_Content_3 = {
    Text = "Tsk, lästig."
  },
  AvgDialog_4901_Content_4 = {
    Text = "Lotan hörte auf zu kämpfen, schlug Casiah mit dem Schwertknauf bewusstlos, steckte ihr Schwert ein und ging zu Lily."
  },
  AvgDialog_4901_Content_5 = {
    Text = "Die Maschine war in den Kampf geraten und zwischen den Trümmern der Kulissen und Requisiten zusammengebrochen."
  },
  AvgDialog_4901_Content_6 = {
    Text = "Was? Was ist mit der Maschine los? Ist sie erschöpft?"
  },
  AvgDialog_4901_Content_7 = {
    Text = "Etwas ist von innen herausgefallen. Ist sie kaputt?"
  },
  AvgDialog_4901_Content_8 = {
    Text = "Du hebst die Maschine hoch. Die Kamera scheint unbeschädigt zu sein, bis auf ein radförmiges Teil, das abgefallen ist."
  },
  AvgDialog_4901_Content_9 = {
    Text = "Oh nein! Der Film!"
  },
  AvgDialog_4902_Content_1 = {
    Text = "Halt, halt! Nicht rennen!"
  },
  AvgDialog_4902_Content_10 = {
    Text = "Wen wollen Sie besuchen? Die Besuchszeiten im Sanatorium sind längst vorbei!"
  },
  AvgDialog_4902_Content_11 = {
    Text = "<Small:Der Sicherheitsdienst der Dexter-Stiftung taugt nichts...>\nVergessen Sie's, Sie können hier nicht bleiben. Ich lasse Sie vom Sicherheitsdienst hinausbegleiten."
  },
  AvgDialog_4902_Content_12 = {
    Text = "Nach dem Höllenhund-Vorfall finanzierte die Familie Dexter großzügig das Rai-Mentalasyl. Auf eine Weise ist es zum Privatbesitz des Professors geworden"
  },
  AvgDialog_4902_Content_13 = {
    Text = "Ich bin ein Schüler von Lorde Dexter"
  },
  AvgDialog_4902_Content_14 = {
    Text = "Ich bin ein Schüler des Lorden in Lentiniën. Auf meinen Reisen komme ich durch Rai und hoffe, eine Nacht im Sanatorium verbringen zu können."
  },
  AvgDialog_4902_Content_15 = {
    Text = "Ein Schüler des Lorden? Den ganzen Weg aus Lentiniën?"
  },
  AvgDialog_4902_Content_16 = {
    Text = "Selbst wenn Sie den Lorden wirklich kennen, wie sollen wir bei unserer derzeitigen Lage jemanden über Nacht unterbringen!\nSo ein Aufwand... Na gut, ich bringe Sie zur verantwortlichen Person."
  },
  AvgDialog_4902_Content_17 = {
    Text = "Ich bin Ramona Dexter"
  },
  AvgDialog_4902_Content_18 = {Text = "?!"},
  AvgDialog_4902_Content_19 = {
    Text = "Du drücktest Lilys Schulter, um ihr zu signalisieren, nicht in Panik zu geraten."
  },
  AvgDialog_4902_Content_2 = {
    Text = "Die Kranken im dritten Stock veranstalten eine Wasserschlacht im Hof, die im ersten Stock spielen mit Kartoffeln und Curry in der Küche, und die im zweiten Stock heulen—Oh mein Gott!!"
  },
  AvgDialog_4902_Content_20 = {
    Text = "Ich bin die alleinige Erbin der Familie Dexter, und es ist mein rechtmäßiges Anliegen, unsere Familienunternehmen zu inspizieren."
  },
  AvgDialog_4902_Content_21 = {
    Text = "...Ich habe Miss Dexter einmal auf einer Dinnerparty gesehen — eine Dame mit schimmerndem silbernem Haar."
  },
  AvgDialog_4902_Content_22 = {
    Text = "Sie... ach, schon gut, schon gut.\n<Small:Robert, bleib ruhig. Du hast hier schon genug Verrückte gesehen; einer mehr macht auch keinen Unterschied.>"
  },
  AvgDialog_4902_Content_23 = {
    Text = [[
Ob Besuch oder Einweisung, die Genehmigung der verantwortlichen Person ist erforderlich.
Ich bringe Sie zu ihr.]]
  },
  AvgDialog_4902_Content_3 = {
    Text = "Ich gebe auf! Ich höre auf!!"
  },
  AvgDialog_4902_Content_4 = {
    Text = "Alarme heulen, rote Lichter blinken. Die Rai Psychiatrie versinkt innen und außen im Chaos. Kranke laufen Amok, und verzweifelte Pfleger jagen ihnen hinterher."
  },
  AvgDialog_4902_Content_5 = {Text = "...!"},
  AvgDialog_4902_Content_6 = {
    Text = "Psychiatrie... Mutter!"
  },
  AvgDialog_4902_Content_7 = {
    Text = "Lily, nicht hetzen, bleib ruhig."
  },
  AvgDialog_4902_Content_8 = {
    Text = "Obwohl das medizinische Personal überfordert wirkte, verrieten ihre methodischen Handlungen, dass sie lediglich Beschwerden über die geschäftige und mühsame Arbeit äußerten."
  },
  AvgDialog_4902_Content_9 = {
    Text = "Hallo, darf ich fragen, ob etwas im Sanatorium nicht stimmt?"
  },
  AvgDialog_4903_Content_1 = {
    Text = "Was ist mit diesen Mutanten los?"
  },
  AvgDialog_4903_Content_10 = {
    Text = "Wann ist sie verschwunden?!"
  },
  AvgDialog_4903_Content_11 = {
    Text = "Keine Sorge, das hier ist Lilys Zuhause. Sie wird nicht in Gefahr sein.\nLass uns diese Mutanten beseitigen, während wir nach ihr suchen."
  },
  AvgDialog_4903_Content_2 = {
    Text = "Erinnerst du dich an die Kriegerin, die du und Fräulein Lotan besiegt habt?"
  },
  AvgDialog_4903_Content_3 = {
    Text = "Überlasst sie... mir!"
  },
  AvgDialog_4903_Content_4 = {
    Text = "Helot... Die ursprüngliche Befreierin der Tilos, der rachsüchtige Geist."
  },
  AvgDialog_4903_Content_5 = {
    Text = "Genau.\nGemäß dem Wunsch von Dekan Oswald ist Frau Helots Verbindung jeder Patient im Sanatorium."
  },
  AvgDialog_4903_Content_6 = {
    Text = "Ihre Handlungen draußen haben Anomalien im Sanatorium ausgelöst, die sich normalerweise bis zum Morgen wieder normalisieren...\nAngesichts des Chaos dieser Nacht ist es wirklich viel verlangt, dich zu bitten, sie aufzuspüren."
  },
  AvgDialog_4903_Content_7 = {
    Text = "Es gibt eine schwache Verbindung zwischen Erweckten Körpern gleichen Ursprungs. Lily könnte spüren, wo Helot ist. Sollte sich die Lage im Sanatorium verschlechtern, kontaktiert uns bitte umgehend."
  },
  AvgDialog_4903_Content_8 = {
    Text = "Danke für eure Freundlichkeit. Ich werde... Hm?"
  },
  AvgDialog_4903_Content_9 = {Text = "Lily?"},
  AvgDialog_4904_Content_1 = {
    Text = "El@1...@4...!"
  },
  AvgDialog_4904_Content_2 = {
    Text = "Der Patient stieß einen schmerzerfüllten Schrei auf dem Bett aus, der abrupt abbrach, als ob die Welt sich weigerte, ihn einen Laut von sich geben zu lassen."
  },
  AvgDialog_4904_Content_3 = {
    Text = "Sch, sch... Hör auf das Rauschen des fließenden Meeres..."
  },
  AvgDialog_4904_Content_4 = {
    Text = "Nymphaea tröstete den Patienten sanft, unsichtbare Ströme umschlangen ihn. Bald verstummte er und sank friedlich in Nymphaeas Arme."
  },
  AvgDialog_4904_Content_5 = {Text = "Das ist..."},
  AvgDialog_4904_Content_6 = {
    Text = "Nymphaea machte eine beschwichtigende Geste, deckte den Patienten zu und führte dich dann zurück auf den Flur."
  },
  AvgDialog_4904_Content_7 = {
    Text = "Keine Sorge, es ist nur eine Spur von Ozeantoxin. Dein Körper wird es im Schlaf abbauen."
  },
  AvgDialog_4904_Content_8 = {
    Text = "Geh weiter durch diesen Korridor. Lily könnte tiefer im Sanatorium sein."
  },
  AvgDialog_4904_Content_9 = {
    Text = "Du blickst auf den vertrauten, tiefen Gang und nickst zustimmend."
  },
  AvgDialog_4905_Content_1 = {
    Text = "Andy Johnsons Kraft"
  },
  AvgDialog_4905_Content_10 = {
    Text = "Leise Schritte kamen aus einer Ecke des Sets. Lotan hob eine Augenbraue in Auritas Richtung, die sofort verstand und das Licht auf jene Ecke richtete."
  },
  AvgDialog_4905_Content_11 = {
    Text = "Das grelle Licht ließ die Augen des Mädchens unwillkürlich zusammenkneifen. Sie ging barfuß zur Mitte des Sets und wäre dabei mehrmals beinahe gegen die wahllos aufgestapelten Requisiten gestoßen."
  },
  AvgDialog_4905_Content_12 = {
    Text = "— „Höllenhund\"!"
  },
  AvgDialog_4905_Content_13 = {
    Text = "Grrr... Auuuuh..."
  },
  AvgDialog_4905_Content_14 = {
    Text = "Seine Klauen sind schärfer als die feinsten Messer eines Kaufhauses, seine Augen heller als die Suchscheinwerfer eines Gefängnisturms. Gesichtslos lauert er in den Ecken der Stadt und sucht Opfer für das Böse..."
  },
  AvgDialog_4905_Content_15 = {
    Text = "Nein... Nein, das stimmt nicht..."
  },
  AvgDialog_4905_Content_16 = {
    Text = "Kum... So ist das nicht..."
  },
  AvgDialog_4905_Content_17 = {
    Text = "*Hust, hust!*"
  },
  AvgDialog_4905_Content_18 = {
    Text = "Kurzum, es sucht Ziele für ein finsteres Opferritual..."
  },
  AvgDialog_4905_Content_19 = {
    Text = "Was ist das für ein Drehbuch? Lentiniën ist doch gar nicht so gefährlich... *hust*."
  },
  AvgDialog_4905_Content_2 = {
    Text = "Vor langer, langer Zeit wurde die Stadt von einer verheerenden Flut heimgesucht."
  },
  AvgDialog_4905_Content_20 = {
    Text = "Obwohl Lentiniën gefährlich ist, sollten keine Höllenhunde durch die Straßen streifen!"
  },
  AvgDialog_4905_Content_21 = {
    Text = "Jenkin, Miss Casiahs Skript ist nur eine Geschichte..."
  },
  AvgDialog_4905_Content_22 = {
    Text = "Man kann sich die Geschichte doch nicht einfach ausdenken, oder? Ich habe schon lange gesagt, dass das Schreiben des Skripts viel zu wichtig ist, um es Außenstehenden zu überlassen."
  },
  AvgDialog_4905_Content_23 = {
    Text = "Auch der Schutzherr, habt Ihr nicht viel unter dieser Dame gelitten? Wie könnt Ihr den Leuten vertrauen, die sie in die Schule gebracht hat?"
  },
  AvgDialog_4905_Content_24 = {Text = "Squeak!"},
  AvgDialog_4905_Content_25 = {
    Text = "Schon gut, schon gut, beruhigt euch. Alle, beruhigt euch einfach."
  },
  AvgDialog_4905_Content_26 = {
    Text = "Lady Daffodil hat einen Deal mit den hochrangigen Beamten der Universität gemacht. Casiah ist jetzt ein vorübergehender Gast in Misaq."
  },
  AvgDialog_4905_Content_27 = {
    Text = "Die kleine Maus hat nicht unrecht; die Geschichte des Höllenhunds ist fesselnd genug, wie sie ist, und außerdem..."
  },
  AvgDialog_4905_Content_28 = {
    Text = "Lotan sprach und warf einen Blick auf Lily. Das Mädchen stand immer noch im Scheinwerferlicht, den Kopf leicht gesenkt, sodass ihr Gesichtsausdruck nicht zu erkennen war."
  },
  AvgDialog_4905_Content_29 = {
    Text = "Bedenkt die Gefühle der Betroffenen, Miss Magierin."
  },
  AvgDialog_4905_Content_3 = {
    Text = "Straßen wurden überflutet, Türme stürzten ein. Von Menschen bis zu Dingen — Lentiniën hat ein vollständiges „Mischen\" durchgemacht!"
  },
  AvgDialog_4905_Content_30 = {
    Text = "Hmm... Hmm hmm!"
  },
  AvgDialog_4905_Content_31 = {
    Text = "Die Schatten auf dem Boden wallten auf, die Drähte an der Krempe des hohen Zylinderhuts rissen einer nach dem anderen, und enthüllten einen leuchtenden Spalt, der an das Grinsen eines Verbrechers erinnerte."
  },
  AvgDialog_4905_Content_32 = {
    Text = "Ein Stab wurde aus dem Riss geworfen, gefolgt von einer Hand, und schließlich trat ein junges Mädchen hervor."
  },
  AvgDialog_4905_Content_33 = {
    Text = "Die Magierin sah unzufrieden aus. Sie erhob sich vom Boden, klopfte sich den Staub ab und nahm ihren Zylinderhut, um ihn wieder aufzusetzen."
  },
  AvgDialog_4905_Content_34 = {
    Text = "Du sagst das eine, sie sagt das andere, hin und her... <Big:Ihr seid ein Haufen Darsteller ohne Respekt vor der Kunst!>"
  },
  AvgDialog_4905_Content_35 = {
    Text = "In einer kaum wahrnehmbaren Ecke öffnet Casiahs „Wut“ den Hyperraum, mit vertrautem Rascheln, das sich im Dunkeln regt..."
  },
  AvgDialog_4905_Content_36 = {
    Text = "Dieser Schulurlaub sollte eigentlich nur dazu dienen, Dolls neue Erfindung zu testen... wie ist es zu einem Kampf gekommen?"
  },
  AvgDialog_4905_Content_37 = {
    Text = "Worte sind billig. Lasst uns in Stimmung kommen."
  },
  AvgDialog_4905_Content_4 = {
    Text = "Was ist „das Große Mischen\"?"
  },
  AvgDialog_4905_Content_5 = {
    Text = "Psst, ich erkläre es, wenn diese Szene vorbei ist."
  },
  AvgDialog_4905_Content_6 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_4905_Content_7 = {
    Text = "Nachdem die Flut zurückgegangen war, brach am Ufer der Isis erneut Chaos aus! Das Unglück suchte diese unglückselige Stadt ein weiteres Mal heim!"
  },
  AvgDialog_4905_Content_8 = {
    Text = [[
Dichter Nebel treibt auf der Isis, sodass man nicht einmal eine Handbreit weit sehen kann!
Und in diesem dichten Nebel lauert etwas...]]
  },
  AvgDialog_4905_Content_9 = {
    Text = "So lautet die uralte Legende: „Echidna als Mutter, Typhon als Vater, mit drei Köpfen, <Yellow:wer dreimal von ihm gejagt wird, dessen Seele ist der Unterwelt bestimmt>\" —"
  },
  AvgDialog_4906_Content_1 = {
    Text = "Geschichtensucher"
  },
  AvgDialog_4906_Content_10 = {
    Text = "Habt Ihr eine Idee, was für eine Geschichte wir erzählen sollten, mein Gebieter?"
  },
  AvgDialog_4906_Content_11 = {Text = "Ugh..."},
  AvgDialog_4906_Content_12 = {
    Text = "Hier herumzustehen und zu starren hilft nicht. Lasst uns zum Veranstaltungsbereich zurückgehen und unterwegs darüber nachdenken."
  },
  AvgDialog_4906_Content_2 = {
    Text = "Endlich draußen. Dieser Ort hat so einen seltsamen Geruch, er bringt meine Nase fast um."
  },
  AvgDialog_4906_Content_3 = {Text = "Squeak!"},
  AvgDialog_4906_Content_4 = {
    Text = "Wenn sie das hört, kommen wir heute nicht so leicht hier weg."
  },
  AvgDialog_4906_Content_5 = {
    Text = "Wir sind schon zehn Meter vom Laden entfernt! Sie hat doch keine drei Paar Ohren, wie sollte sie uns reden hören können?"
  },
  AvgDialog_4906_Content_6 = {
    Text = "Du wogst den Film in deiner Hand; er fühlte sich nicht anders an als der beschädigte.\nDu erinnertest dich an die Belohnung, die Daffodil verlangt hatte..."
  },
  AvgDialog_4906_Content_7 = {
    Text = "Eine brillante, vollständige und reuelose Handlung.\nDas ist es, was ich im Austausch möchte."
  },
  AvgDialog_4906_Content_8 = {
    Text = "Diesmal kannst du nicht einfach drauflos fotografieren; ein Plan ist nötig."
  },
  AvgDialog_4906_Content_9 = {
    Text = "Plan～Handlungsplan～"
  },
  AvgDialog_4907_Content_1 = {
    Text = "Was passiert da hinten...?"
  },
  AvgDialog_4907_Content_10 = {
    Text = "Lily presste die Lippen zusammen und zog das Papier wie ein schutzbedürftiges kleines Mäuschen in ihre Arme. Man konnte nicht erkennen, ob sie schüchtern, verängstigt oder traurig war."
  },
  AvgDialog_4907_Content_11 = {
    Text = "Es tut mir leid... aber wenn ich an meine Mutter denke..."
  },
  AvgDialog_4907_Content_12 = {
    Text = "Du hast nichts falsch gemacht, schließlich ist dieses Ende..."
  },
  AvgDialog_4907_Content_13 = {
    Text = "Das war's für heute. Wir haben genug gefilmt. Wenn Doll irgendwelche Probleme hat, kann sie zu mir kommen."
  },
  AvgDialog_4907_Content_14 = {
    Text = "Hä—? Aber Aurita ist noch gar nicht aufgetreten!"
  },
  AvgDialog_4907_Content_15 = {
    Text = "Hast du nicht ewig hinter der Bühne mit Braun genascht? Warum willst du jetzt vor die Kamera?"
  },
  AvgDialog_4907_Content_16 = {
    Text = "Aurita will auch ein Ölgemälde malen!"
  },
  AvgDialog_4907_Content_17 = {
    Text = "Dein Umhang wird kräftig gezogen. Du blickst zu deinem Bein hinunter und siehst Lily, deren Augen voller Unruhe und Schuldgefühle sind."
  },
  AvgDialog_4907_Content_18 = {
    Text = "Das junge Mädchen weigert sich, sich daran zu erinnern, wie sie gezwungen wurde, sich von ihrer Mutter zu trennen, und niemand kann es ihr verübeln."
  },
  AvgDialog_4907_Content_19 = {
    Text = "Aber gibt es einen Weg, sie diesen Kummer vergessen zu lassen, wenn auch nur vorübergehend...?"
  },
  AvgDialog_4907_Content_2 = {
    Text = "Klick! Klick!"
  },
  AvgDialog_4907_Content_20 = {
    Text = "Eine grobe Skizze liegt vor uns, aber dank der hervorragenden Gestaltungskünste des Großen Magiers ist euer Unsinn gerade noch handhabbar."
  },
  AvgDialog_4907_Content_21 = {
    Text = "<Yellow:Unsinn>..."
  },
  AvgDialog_4907_Content_3 = {
    Text = "Casiah stoppt abrupt die Aufnahme; die magische Illusion verblasst, und sie wedelt wütend mit dem Drehbuch."
  },
  AvgDialog_4907_Content_4 = {
    Text = "Warum hast du plötzlich abgebrochen? Diesmal ist es nicht meine Schuld. Weder Braun noch ich haben ein Wort gesagt!"
  },
  AvgDialog_4907_Content_5 = {
    Text = "Eine grobe Skizze liegt vor uns, aber dank der hervorragenden Gestaltungskünste des Großen Magiers ist euer Unsinn gerade noch handhabbar."
  },
  AvgDialog_4907_Content_6 = {
    Text = "Aber schaut euch dieses Drehbuch für den vierten Akt an, das ist nicht einmal eine Skizze. Wie soll Lady Casiah davon ausgehend zu schreiben beginnen!"
  },
  AvgDialog_4907_Content_7 = {
    Text = "Casiah wirft dir das Drehbuch entgegen, lose Seiten fliegen aus dem Ordner."
  },
  AvgDialog_4907_Content_8 = {
    Text = "Ein nahezu leeres Blatt Papier fiel allen vor die Füße, bedeckt nur mit einigen kindlichen Kritzeleien:"
  },
  AvgDialog_4907_Content_9 = {
    Text = "„Das Mädchen lebte glücklich bis ans Ende ihrer Tage mit ihrer Mutter.\""
  },
  AvgDialog_49091_Content_1 = {Text = "Thais..."},
  AvgDialog_49091_Content_10 = {
    Text = "Sie hob ihre Hand und teilte die übergroße Milchstraße mit ihrem glatten und eleganten Arm, doch sie floss weiter, unbeirrt."
  },
  AvgDialog_49091_Content_11 = {
    Text = "Ich werde auch an dich denken, die Freude, die aufsprang, und der flüchtige Nervenkitzel."
  },
  AvgDialog_49091_Content_12 = {
    Text = "Ein Meteor zieht über den Himmel und hinterlässt einen langen Schweif."
  },
  AvgDialog_49091_Content_13 = {
    Text = "Komm schon, mach weiter..."
  },
  AvgDialog_49091_Content_14 = {
    Text = "Erkunde mich, vertiefe dich in mich, bis zum Reich der Glückseligkeit..."
  },
  AvgDialog_49091_Content_15 = {
    Text = "Ihr Brennen verzehrt deinen Verstand wie ein Schwarm Termiten, die nagen und nagen."
  },
  AvgDialog_49091_Content_16 = {
    Text = "Die Auswirkungen der Flut des Heiliger Fluss sind zu schwerwiegend. Ich möchte das nicht, noch sollte ich das gerade jetzt tun..."
  },
  AvgDialog_49091_Content_17 = {
    Text = "Machst du dir darüber tatsächlich Sorgen? Was für ein gutes Kind."
  },
  AvgDialog_49091_Content_18 = {
    Text = "Ihr sanftes Lachen trägt eine gewisse fesselnde Anziehungskraft, die durch das Schiff deiner unausgesprochenen Gedanken dringt."
  },
  AvgDialog_49091_Content_19 = {
    Text = "Die Kraft des Heiligen Flusses ist meine Kraft. Ich habe mich niemals von ihrer Versuchung verführen lassen."
  },
  AvgDialog_49091_Content_2 = {
    Text = "Thais erhebt sich widerwillig von dir, ein zarter Faden Speichel verbindet eure Lippen und dient als Beweis für das, was gerade passiert ist."
  },
  AvgDialog_49091_Content_20 = {
    Text = "Alle meine Entscheidungen basieren auf meinen eigenen Wünschen."
  },
  AvgDialog_49091_Content_21 = {
    Text = "Das Flusswasser sickerte durch das Loch im Rumpf und umhüllte allmählich deine Zehen, deine Knie, deine Brust, deinen Hals und deinen Mund und deine Nase..."
  },
  AvgDialog_49091_Content_22 = {
    Text = "Jetzt ist es dein Turn, zu antworten... Wirst du in meinem grenzenlosen Meer des Verlangens gefangen sein?"
  },
  AvgDialog_49091_Content_23 = {
    Text = "Bevor du reagieren konntest, versiegelten warme Lippen den Auslass deiner Worte."
  },
  AvgDialog_49091_Content_24 = {
    Text = "In solchen Momenten erscheinen Worte zu blass."
  },
  AvgDialog_49091_Content_25 = {
    Text = "Verwenden Sie Ihren Körper... um mir zu antworten."
  },
  AvgDialog_49091_Content_3 = {
    Text = "Ihr Blick, benommen und chaotisch, streift über dich von Kopf bis Fuß."
  },
  AvgDialog_49091_Content_4 = {
    Text = "Deine verschränkten Finger wurden fester, als ob sie fürchteten, dass du entkommen könntest, und hielten dich in diesem tiefen, heißen Reich des Verlangens gefangen."
  },
  AvgDialog_49091_Content_5 = {
    Text = "Das weite Meer aus weißem Sand vor dir schimmert im Sternenlicht, hypnotisierend und blendend."
  },
  AvgDialog_49091_Content_6 = {
    Text = "Woran erinnert dich dieses sternenklare Meer?"
  },
  AvgDialog_49091_Content_7 = {
    Text = "Du kannst dich an nichts erinnern. Im Meer der fragmentierten Erinnerungen siehst du nur das schimmernde Sternenlicht, das sich in Thais' Pupillen spiegelt."
  },
  AvgDialog_49091_Content_8 = {
    Text = "Ich werde an Yalan erinnern."
  },
  AvgDialog_49091_Content_9 = {
    Text = "Erinnere dich an die Samen des Lebens, die sich zu einem großen Fluss vereinen, kraftvoll durch jedes Kapillargefäß der Wüste strömen."
  },
  AvgDialog_49092_Content_1 = {
    Text = "Ein schwarzes Tuch wird von deinem Kopf entfernt. Du reibst dir die Augen."
  },
  AvgDialog_49092_Content_10 = {
    Text = "Jetzt genieße bitte die von Casiah präsentierte Zaubershow, \"Eine Nacht, die der Hüter nicht vergessen kann\"..."
  },
  AvgDialog_49092_Content_11 = {
    Text = "Ein Paar schelmischer Augen blitzen vor dir. Für einen Moment scheint es, als würde dieser sorglose Zauberer zum ersten Mal erröten."
  },
  AvgDialog_49092_Content_12 = {Text = "Was...?"},
  AvgDialog_49092_Content_13 = {
    Text = "Bevor du reagieren konntest, wurde ein schwarzes Tuch wieder über dich gelegt. Unter dem schwachen Sternenlicht lehnte sich ein warmer, weicher Körper in deine Arme."
  },
  AvgDialog_49092_Content_14 = {
    Text = "Hey... Casiah, warte..."
  },
  AvgDialog_49092_Content_15 = {
    Text = "Pssst, Hüter. Die Zaubershow hat begonnen..."
  },
  AvgDialog_49092_Content_16 = {
    Text = "Du möchtest mehr sagen, aber ein weiches, kaltes Objekt blockiert deinen Mund."
  },
  AvgDialog_49092_Content_17 = {
    Text = "Du schließt deine Augen. Keine Bühne, kein Publikum. In einer anderen Dimension gibt es nur Sterne, nur euch beide."
  },
  AvgDialog_49092_Content_18 = {
    Text = "In deiner Erinnerung war das Casiahs erfolgreichste magische Aufführung."
  },
  AvgDialog_49092_Content_2 = {
    Text = "Wo... ist dieser Ort?"
  },
  AvgDialog_49092_Content_3 = {
    Text = "Natürlich ist es ein anderer dimensionaler Raum~ Hüter, erkennst du diesen Ort nicht?"
  },
  AvgDialog_49092_Content_4 = {
    Text = "Hey, Casiah, ich habe mit deinem Körperübertragungsakt mitgemacht, aber ich habe nie zugestimmt, hierher gebracht zu werden."
  },
  AvgDialog_49092_Content_5 = {
    Text = "Lass uns frühzeitig zurückkehren und die Aufführung fortsetzen, um den Einfluss des Heiligen Flusses auf dich zu verringern..."
  },
  AvgDialog_49092_Content_6 = {
    Text = "Die Aufführung läuft immer noch, nicht wahr? Du hast versprochen, mir bei meinem Zaubertrick zu helfen, also gibt es kein Zurück mehr."
  },
  AvgDialog_49092_Content_7 = {
    Text = "Aber diese Zuschauer warten immer noch..."
  },
  AvgDialog_49092_Content_8 = {
    Text = "Die Zaubershow für das Publikum ist zu Ende. Diese Darbietung war ein Geschenk für den Hüter."
  },
  AvgDialog_49092_Content_9 = {
    Text = "Casiah springt vor dich, die Hände hinter dem Rücken, den Kopf leicht schräg."
  },
  AvgDialog_49093_Content_10 = {
    Text = "Blas es einfach aus, oder?"
  },
  AvgDialog_49093_Content_11 = {Text = "Hui—"},
  AvgDialog_49093_Content_12 = {
    Text = "Wie sieht es aus?"
  },
  AvgDialog_49093_Content_13 = {
    Text = "Der Schmerz ist verschwunden, und der Staub scheint weggeblasen worden zu sein. Lass uns weitermachen."
  },
  AvgDialog_49093_Content_14 = {
    Text = "Nein, das ist alles für heute."
  },
  AvgDialog_49093_Content_15 = {
    Text = "Stoppe dein Kampfltraining, bevor du vollständig zufrieden bist? Das ist nicht dein üblichen Stil..."
  },
  AvgDialog_49093_Content_16 = {
    Text = "Ha... dank Tolemwhasi kannst du mich jetzt nicht mehr „vergnügen“."
  },
  AvgDialog_49093_Content_17 = {
    Text = "Die Strähnen Haare auf der Stirn werden beiseite gestrichen, und eine schwere Seele drückt einen herablassenden Kuss auf die Schläfe."
  },
  AvgDialog_49093_Content_18 = {Text = "Lotan?!"},
  AvgDialog_49093_Content_19 = {
    Text = "Lotan patschte dir ins Gesicht und zog dich dann vom kalten, harten Boden hoch."
  },
  AvgDialog_49093_Content_2 = {
    Text = "Nicht genug, immer noch nicht genug!"
  },
  AvgDialog_49093_Content_20 = {
    Text = "Wenn ich rational bin, können mich diese chaotischen Begierden nicht kontrollieren.\nVergiss nicht, ich bin ein uraltes Relikt."
  },
  AvgDialog_49093_Content_21 = {
    Text = "Jetzt geh zurück. Du kleiner Schelm."
  },
  AvgDialog_49093_Content_3 = {
    Text = "Ist das deine wahre Stärke? Nach einem Jahr Training und mehreren Missionen..."
  },
  AvgDialog_49093_Content_4 = {
    Text = "Die Angriffe prasselten wie ein Strom herab und zertrümmerten gnadenlos die Fliesen des Trainingsplatzes."
  },
  AvgDialog_49093_Content_5 = {
    Text = "Staub flog in deine Augen und verursachte eine unwillkürliche Reaktion, die dich dazu brachte, sie zu schließen."
  },
  AvgDialog_49093_Content_6 = {
    Text = "Lotan! Pause, ich—"
  },
  AvgDialog_49093_Content_7 = {
    Text = "Der Krieger öffnete gewaltsam deine Augenlider, der Stoff seiner Handschuhe rieb gegen deine empfindliche und fragile Haut, was dich häufig blinzeln ließ."
  },
  AvgDialog_49093_Content_8 = {
    Text = "Beweg dich nicht."
  },
  AvgDialog_49093_Content_9 = {
    Text = "Lotan legte einfach ihre Waffe nieder, fixierte deinen Kopf mit einer Hand, um zu verhindern, dass sich dein Körper instinktiv zurückzieht und flieht."
  },
  AvgDialog_49094_Content_1 = {
    Text = "Mutternüsse, Schrauben, Eisensprossen... Ja, genau wie beim Reparieren eines Motorrades."
  },
  AvgDialog_49094_Content_2 = {
    Text = "Huh? Es ist nicht kaputt. Warum hat dieser Typ mich ins Zimmer gerufen? Könnte es sein, dass das kaputte Ding nicht dieses Bett ist?"
  },
  AvgDialog_49094_Content_3 = {
    Text = "Das Mädchen sah verwirrt auf, ihre Hände waren mit Fett beschmiert, was darauf hindeutete, dass sie eine umfassende Überholung des Zimmers perfekt abgeschlossen hatte."
  },
  AvgDialog_49094_Content_4 = {
    Text = "Schnüffeln... schnüffeln schnüffeln..."
  },
  AvgDialog_49094_Content_5 = {
    Text = "Diese Person trägt meinen Duft..."
  },
  AvgDialog_49094_Content_6 = {
    Text = "Nautila beugte sich über den schlafenden Studenten auf der Krankenschu, in Gedanken versunken."
  },
  AvgDialog_49094_Content_7 = {
    Text = "%hisorher% hat deutliche schwarze Flecken an den Ecken von %hisorher% Mund und auf %hisorher% Gesicht. Nautila erkennt sie sofort als Spuren ihres speziell formulierten Öls."
  },
  AvgDialog_49094_Content_8 = {
    Text = "Hmm... Ich kenne {Male=him,Female=her} definitiv. {Male=His,Female=Her} Name ist..."
  },
  AvgDialog_49094_Content_9 = {
    Text = "%player%... Genau, %player%."
  },
  AvgDialog_49095_Content_1 = {
    Text = "Du fällst tiefer in den Traum."
  },
  AvgDialog_49095_Content_10 = {
    Text = "Hör auf zu atmen. Ich bringe dich zurück zur Realität."
  },
  AvgDialog_49095_Content_11 = {
    Text = "Tulu?! *Hust* *Hust*..."
  },
  AvgDialog_49095_Content_12 = {
    Text = "Die Anwesenheit des Erweckers hilft, die Situation zu klären. Du rufst seinen Namen begierig, aber diese seltsamen Gedanken überfluten deinen Geist sofort wie eine Flut, die durch deine Atemwege strömt."
  },
  AvgDialog_49095_Content_13 = {
    Text = "...Wie Yu gerade sagte, hör auf zu atmen."
  },
  AvgDialog_49095_Content_14 = {
    Text = "Im nächsten Moment drang ein kaltes und volles Tentakel gewaltsam in deinen Mund, schob chaotische Erinnerungen beiseite und trieb jene jetzt bedeutungslosen Geräusche aus."
  },
  AvgDialog_49095_Content_15 = {
    Text = "Die echte Monsunbrise streift über mein Gesicht, und mein Körper entspannt sich unter ungewohnter Müdigkeit, als ob ich im Begriff bin, in einen traumlosen tiefen Schlaf einzutreten..."
  },
  AvgDialog_49095_Content_16 = {
    Text = "Hast du meinen Traum überlebt und wagst es, wieder zu schlafen? Dein Mut beeindruckt mich."
  },
  AvgDialog_49095_Content_17 = {
    Text = "Tu, Tulu..."
  },
  AvgDialog_49095_Content_18 = {
    Text = "Hast du gerade gesagt, das war dein Traum?"
  },
  AvgDialog_49095_Content_19 = {
    Text = "Der Erwacher wendet sich ab, ein wenig verlegen."
  },
  AvgDialog_49095_Content_2 = {
    Text = "Die Flut zerbrach abrupt die Balken des Traums und füllte die Grenze zwischen Traum und Realität mit Schreien, die sich dann in unzählige feuchte, dunkle Steine verwandelten"
  },
  AvgDialog_49095_Content_20 = {
    Text = "\"Wenn ich ruhe, werden die überfließenden Träume den Wahnsinn der Geister entfachen\"... Die Anomalie meines Körpers hat dich in den Traum gezogen, und dafür bin ich verantwortlich."
  },
  AvgDialog_49095_Content_21 = {
    Text = "Diese Anomalie ließ Yus Träume unbewusst in deine Träume eindringen... Wenn du deshalb Groll empfindest, kann ich deine Gefühle vollkommen verstehen."
  },
  AvgDialog_49095_Content_22 = {
    Text = "Groll? Wie könnte ich dir gegenüber einen hegen? Es war unbeabsichtigt von deiner Seite. Außerdem bist du nicht gerade rechtzeitig angekommen, als die Stimmen von Lemuria mich überwältigten?"
  },
  AvgDialog_49095_Content_23 = {Text = "Du..."},
  AvgDialog_49095_Content_24 = {
    Text = "Nachdem ich zur Schule zurückgekehrt bin, werde ich sofort zum Schwarzen Pool gehen. Vielleicht kann die Umgebung dort vorübergehend das... Anomalie in mir unterdrücken."
  },
  AvgDialog_49095_Content_25 = {
    Text = "Er hielt seine Tentakel in einer Ecke der Kutsche zurück und warf seitlich einen Blick auf die tiefe, dunkle Nacht draußen am Fenster."
  },
  AvgDialog_49095_Content_26 = {
    Text = "Aber die häufigen Blicke, die auf die Ecke deiner Lippen fallen, scheinen nicht unbeabsichtigt zu sein."
  },
  AvgDialog_49095_Content_3 = {
    Text = "Dies ist nicht mein Traum... Dies ist nicht meins..."
  },
  AvgDialog_49095_Content_4 = {
    Text = "Du murmelst, sehnst dich danach, aufzuwachen. Deine mit Wasser gefüllten Alveolen schwellen wie der Bauch eines unheilbar kranken Patienten; dein Körper passt sich dem vergessenen Ozean an."
  },
  AvgDialog_49095_Content_5 = {
    Text = "Aber der geräuschlose Wasserfluss zog deinen Kopf für einen Blick zurück."
  },
  AvgDialog_49095_Content_6 = {
    Text = "Musik, Gemälde, Geschichten, die in unbekannten Sprachen geschrieben sind - unzählige bizarre Ideen strömen in deine Träume, sobald du zurückblickst."
  },
  AvgDialog_49095_Content_7 = {
    Text = "Du versuchst zu sprechen, aber es kommt nur sinnloses Gestammel heraus – obwohl es Bedeutung trägt."
  },
  AvgDialog_49095_Content_8 = {
    Text = "Sie sind in der Tat bedeutungsvoll. Vor langer Zeit waren sie einmal —"
  },
  AvgDialog_49095_Content_9 = {
    Text = "Hör auf, hier das Wasser zu trinken."
  },
  AvgDialog_49261_Content_1 = {
    Text = "Mein Kopf tut weh... Was ist los mit mir..."
  },
  AvgDialog_49261_Content_10 = {
    Text = "<Small:Ugh... Ich wusste es. Jemand wie ich ist nur ein übersehener schwarzer Hemd, eine Ratte im Gully, ein Tautropfen, der im Sonnenlicht verschwindet...>"
  },
  AvgDialog_49261_Content_11 = {
    Text = "Fräulein Mason, Fräulein Mason!"
  },
  AvgDialog_49261_Content_12 = {
    Text = "Du rüttelst an ihren Schultern, in dem Versuch, sie aus ihrem endlosen Selbstzweifel zu reißen."
  },
  AvgDialog_49261_Content_13 = {
    Text = "Niemand wird sich weigern, dich zu akzeptieren; du bist einer von uns."
  },
  AvgDialog_49261_Content_14 = {
    Text = "Niemand würde sich weigern, mich zu akzeptieren..."
  },
  AvgDialog_49261_Content_15 = {
    Text = "Sie blickt plötzlich zu dir auf, die Mundwinkel verziehen sich zu einem verzerrten Lächeln."
  },
  AvgDialog_49261_Content_16 = {
    Text = "Das stimmt, werde ein Teil von mir und lass uns ein neues \"24\" erschaffen!"
  },
  AvgDialog_49261_Content_17 = {
    Text = "Ein erschreckender Riss spaltete ihre Schulter, aber darin war kein Muskel oder Knochen. Graue Massen pulsierten und schwollen unter der Haut an, wie ein Universum, das geboren wird."
  },
  AvgDialog_49261_Content_18 = {
    Text = "Schleim schlüpfte aus dem Riss und umschloss Ihre Finger. Die nasse, glitschige Berührung holte Sie sofort zurück in den Moment des Erwachens aus der Bewusstlosigkeit."
  },
  AvgDialog_49261_Content_19 = {
    Text = "'\"24\"s Pupillen erweitern sich. Sie dürstet nach dir, sehnt sich danach, dich zu umarmen, und möchte Teil des Endes werden.'"
  },
  AvgDialog_49261_Content_2 = {
    Text = "Du findest dich auf dem viel zu vertrauten weichen Bett wieder, mit einem Schmerz im Hinterkopf, der ebenso vertraut ist."
  },
  AvgDialog_49261_Content_20 = {
    Text = "Egal, welche neue Persönlichkeit von Miss Mason du bist... reiß dich zusammen!"
  },
  AvgDialog_49261_Content_21 = {
    Text = "Du kämpfst darum, den Silberschlüssel zu erreichen, der an deiner Brust hängt, aber deine Hand bewegt sich nur leicht, bevor eine überwältigende Kraft dich ergreift"
  },
  AvgDialog_49261_Content_22 = {
    Text = "Warum widerstehen? Hast du nicht gesagt, dass du mich vollständig akzeptieren würdest? \"Diese Person\" schätzt dich so sehr, sie sehnt sich bestimmt auch danach..."
  },
  AvgDialog_49261_Content_23 = {
    Text = "Als die kalten Lippen den Winkel deines Mundes berührten, bemerktest du, dass ihre Augen vollständig von Wahnsinn erodiert waren – sie war nicht der „Mason“, den du einmal gekannt hast."
  },
  AvgDialog_49261_Content_24 = {Text = "Ugh!"},
  AvgDialog_49261_Content_25 = {
    Text = "'\"24\" zitterte, keuchend wie ein kaputter Blasebalg. Sie ließ ihren Griff von dir los und begann, ihren schlanken Hals zu kratzen.'"
  },
  AvgDialog_49261_Content_26 = {
    Text = "Warum! Warum bist du diejenige, die das Sagen hat—"
  },
  AvgDialog_49261_Content_27 = {
    Text = "Nein, nein, nein, nein, nein, nein, nein, nein, nein, nein, nein, nein—"
  },
  AvgDialog_49261_Content_28 = {
    Text = "\"24\" ließ einen scharfen Schrei hören, Ihre Gliedmaßen falteten sich ungeschickt auf ihre Schultern. Schließlich senkte sie den Kopf und verstummte."
  },
  AvgDialog_49261_Content_29 = {
    Text = "Fräulein Mei, Mason? Bist das du?"
  },
  AvgDialog_49261_Content_3 = {
    Text = "Du versuchst, dich im Bett aufzurichten, nur um festzustellen, dass du in einer Masse aus feuchtem, glitschigem Gewebe versinkst."
  },
  AvgDialog_49261_Content_30 = {
    Text = "Hüter! Ich... es tut mir so leid... Aus irgendeinem Grund hat diese neue Persönlichkeit von mir einige ungewöhnliche Gefühle für dich entwickelt..."
  },
  AvgDialog_49261_Content_31 = {
    Text = "Mason winkte frantically mit ihren völlig ausgerenkten Armen, die wie zwei Stücke Teig von ihren Schultern hingen."
  },
  AvgDialog_49261_Content_32 = {
    Text = "Keine Notwendigkeit, sich zu entschuldigen. Du bist nur vom Heiligen Fluss betroffen."
  },
  AvgDialog_49261_Content_33 = {
    Text = "Du hebst ihre Hand – ihre Menschenhand – und führst die verrenkten Gelenke vorsichtig wieder an ihren Platz."
  },
  AvgDialog_49261_Content_34 = {
    Text = "Es ist wirklich lästig für dich..."
  },
  AvgDialog_49261_Content_35 = {
    Text = "Ihre Stimme war so weich wie das Summen einer Mücke, doch schien es einen flüchtigen Hauch von Freude in ihrem Ton zu geben."
  },
  AvgDialog_49261_Content_4 = {
    Text = "Hüter, Hüter..."
  },
  AvgDialog_49261_Content_5 = {
    Text = "Als du wach warst, errötete die junge Frau tief und ließ eine sanfte, zarte Stimme hören, die du noch nie zuvor von ihr gehört hattest."
  },
  AvgDialog_49261_Content_6 = {
    Text = "Fräulein Mei, Mason?!"
  },
  AvgDialog_49261_Content_7 = {
    Text = "\"Mason\" liegt auf der anderen Seite des Bettes, ihre dunklen Finger drücken gegen deine Brust. Obwohl ihre Hände schwach wirken, halten sie dich fest fest."
  },
  AvgDialog_49261_Content_8 = {
    Text = "Verlasse nicht... Warum gehst du?"
  },
  AvgDialog_49261_Content_9 = {
    Text = "Oder waren diese süßen Worte von \"24\" nur die Wahnvorstellungen meines instabilen Geistes?"
  },
  AvgDialog_49398_Content_1 = {
    Text = "Der Sturm intensivierte sich, die Aran-Soldaten schrien, tobten, riefen, beteten und fluchten."
  },
  AvgDialog_49398_Content_10 = {
    Text = "Unzählige Aram knien ehrfürchtig in Richtung der Thais"
  },
  AvgDialog_49398_Content_11 = {
    Text = "Die wütenden Sandkreaturen beruhigen sich durch Gebete, der Sturm legt sich"
  },
  AvgDialog_49398_Content_12 = {
    Text = "Es ist die Königin! Es ist die Königin!"
  },
  AvgDialog_49398_Content_13 = {
    Text = "Danke für den Schutz der Königin!"
  },
  AvgDialog_49398_Content_14 = {
    Text = "Die Augen der Königin sind immer noch auf uns gerichtet!"
  },
  AvgDialog_49398_Content_15 = {
    Text = "Wir... sind angekommen!"
  },
  AvgDialog_49398_Content_2 = {
    Text = "Auf einer nahen Düne siehst du die Silhouette"
  },
  AvgDialog_49398_Content_3 = {
    Text = "Sie erkennen die Silhouette. Es ist Thais."
  },
  AvgDialog_49398_Content_4 = {
    Text = "Der Sturm... ist er kleiner geworden?"
  },
  AvgDialog_49398_Content_5 = {
    Text = "Sie sang unbekannte Gebete, ließ den wilden Wind ihren Schleier aufwirbeln und ging langsam und sicher in den dunklen Sandsturm"
  },
  AvgDialog_49398_Content_6 = {
    Text = "Ohrenbetäubender Lärm, doch das Gebet ist klar zu hören, als würde es in deinem Schädel widerhallen"
  },
  AvgDialog_49398_Content_7 = {
    Text = "Im tobenden Wüstensturm sprach sie ruhig mit einer Kreatur der Wüste"
  },
  AvgDialog_49398_Content_8 = {
    Text = "Es ist die Königin! Die Königin ist gekommen, um uns zu retten, um Arlan zu retten!"
  },
  AvgDialog_49398_Content_9 = {
    Text = "Alans Team, das verzweifelt zu entkommen versucht hatte, kam plötzlich zum Stillstand."
  },
  AvgDialog_49399_Content_1 = {Text = "Sturmwand"},
  AvgDialog_49399_Content_10 = {
    Text = "Es, es kommt—!"
  },
  AvgDialog_49399_Content_11 = {
    Text = "Im Moment des Fokussierens verstehst du, was die „Sturmwand\" ist"
  },
  AvgDialog_49399_Content_12 = {
    Text = "Das ist eine graue Wand, die den Himmel verdeckt und alles verschlingt"
  },
  AvgDialog_49399_Content_13 = {
    Text = "Es sollte eine Flut sein, ist es aber nicht. Es ist riesig und still, bewegt sich vorwärts, scheint aber stillzustehen"
  },
  AvgDialog_49399_Content_14 = {
    Text = "Seine Grenzen lecken wie ein riesiges Tier die Erde, und die Reihen von Arlan werden in den Nebel verschlungen, zerrissen und verdaut vom Magen des Sturms"
  },
  AvgDialog_49399_Content_15 = {
    Text = "Spring weiter, nicht aufhören!"
  },
  AvgDialog_49399_Content_16 = {
    Text = "Der Bote aus der Fremde ist hier, die Königin wird uns den Weg zum Mutterbaum öffnen!"
  },
  AvgDialog_49399_Content_17 = {
    Text = "Du bemerkst, dass Juliette ein leises Lächeln zeigt"
  },
  AvgDialog_49399_Content_18 = {
    Text = "Häuptling, Häuptling, der Sturm ist heute zu heftig, wir können uns nicht so viele Verluste leisten, ziehen wir uns zurück!"
  },
  AvgDialog_49399_Content_19 = {Text = "Nein!"},
  AvgDialog_49399_Content_2 = {
    Text = "Elva schwenkt die Fahne, sie bewegen sich synchron und ziehen die Speere durch die Wüste, wirbeln den blendenden Sand auf und singen seltsame, entfernte Lieder"
  },
  AvgDialog_49399_Content_20 = {
    Text = "Ihre Stimme war majestätisch, aber zitterte im Wind"
  },
  AvgDialog_49399_Content_21 = {
    Text = "Die Rate von Missbildungen im Lagerfeuerritual nimmt zu. Wenn das so weitergeht, wird Yalans Blutlinie im Fluss der Zeit verschwinden, bevor der Mutterbaum entdeckt wird."
  },
  AvgDialog_49399_Content_22 = {
    Text = "Juliette formte mit ihren Fingern einen Ring und pfiff einen durchdringenden Pfiff, während die anhaltenden Klänge vom Sturm erfasst und in das Unbekannte getragen wurden"
  },
  AvgDialog_49399_Content_23 = {
    Text = "Ich bin die Gesandte Juliette. Ich habe den Willen der Königin gehört. Heute werden wir die Sturmwand durchbrechen!"
  },
  AvgDialog_49399_Content_24 = {
    Text = "Alle, nur vorwärts, kein Rückzug!"
  },
  AvgDialog_49399_Content_25 = {
    Text = "Befehl des Gesandten befolgen, nur vorwärts, kein Rückzug!"
  },
  AvgDialog_49399_Content_26 = {
    Text = "<Small:Ja... ein Rückzugsweg... gibt es nicht...>"
  },
  AvgDialog_49399_Content_27 = {
    Text = "Warte, Hüter, eine große Gruppe Nubier kommt von hinten...\nNach der Anzahl zu urteilen... mindestens... zweihundert!"
  },
  AvgDialog_49399_Content_28 = {
    Text = "Seht! Das ist der Wille der Königin! Ihr müsst vorwärts!"
  },
  AvgDialog_49399_Content_29 = {
    Text = "Nubia brüllt und rennt auf euch zu"
  },
  AvgDialog_49399_Content_3 = {
    Text = "Der Tod naht, das Ende hat begonnen"
  },
  AvgDialog_49399_Content_4 = {
    Text = "Die Überreste der Mutter sind verschwunden, Blut und Samen treiben über das Land und werden von den neu geborenen Tieren verschlungen"
  },
  AvgDialog_49399_Content_5 = {
    Text = "Der Himmel ist mit dunklen Wolken bedeckt, bis die Botschafter aus dem fremden Land erscheinen"
  },
  AvgDialog_49399_Content_6 = {
    Text = "Der Heilige Fluss des Wiedergeborenen Mutterbaums krönt die Verstorbenen und bringt ihre Blutlinie zu Yalan zurück."
  },
  AvgDialog_49399_Content_7 = {
    Text = "Gib die Blutlinie zurück... an Arlan..."
  },
  AvgDialog_49399_Content_8 = {
    Text = "Die grelle Sonne der Wüste ist verschwunden, der Himmel ist düster und der Wind hat seinen Ton geändert"
  },
  AvgDialog_49399_Content_9 = {
    Text = "Ein unerklärlicher Schrecken ergriff dich, du warst einen Moment lang benommen, dann weckte dich ein Schrei"
  },
  AvgDialog_49400_Content_1 = {
    Text = "Gnädige Elva, bitte erlauben Sie mir, ein paar Worte mit {Male=er,Female=sie} zu sprechen"
  },
  AvgDialog_49400_Content_10 = {
    Text = "Ihr Gesichtsausdruck ist seltsam fanatisch, ihre Sprache schnell, ihr Körper lehnt sich unwillkürlich vor, ihre Augen sind wie Geister"
  },
  AvgDialog_49400_Content_11 = {
    Text = "Leb wohl, blinder Blick"
  },
  AvgDialog_49400_Content_12 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_49400_Content_13 = {
    Text = "Nein, das ist noch nicht das Ende. Denn diese Person hat dich mit der innigsten Stimme gebeten, ihren Namen zu rufen"
  },
  AvgDialog_49400_Content_14 = {
    Text = "In Gedanken an Thais' Blick aktivierte der Silberne Schlüssel"
  },
  AvgDialog_49400_Content_15 = {
    Text = "Silberne Fäden schwingen, ziehen, suchen"
  },
  AvgDialog_49400_Content_16 = {
    Text = "Am Ende des Fadens ist nichts"
  },
  AvgDialog_49400_Content_17 = {
    Text = "Das Phänomen namens Erosion hat sie vollständig verschlungen, selbst du kannst ihre Spur nicht finden"
  },
  AvgDialog_49400_Content_18 = {
    Text = "Hoffst du, dass sie zurückkommt? Die Aram gehorchen bereits mir"
  },
  AvgDialog_49400_Content_19 = {
    Text = "Thais... Thais!"
  },
  AvgDialog_49400_Content_2 = {
    Text = "Du und Alva sind in eine Pattsituation geraten, als Juliette spricht und euch aufhält"
  },
  AvgDialog_49400_Content_20 = {
    Text = "Wenn sie erscheinen kann, wird sie mit ihrer göttlichen Kraft Alva die Zukunft des Aram offenbaren"
  },
  AvgDialog_49400_Content_21 = {
    Text = "Selbst wenn du nur eine Entschuldigung vorbringst, musst du hier nicht mit Alva konfrontiert werden"
  },
  AvgDialog_49400_Content_22 = {
    Text = "Thais... Thais—!"
  },
  AvgDialog_49400_Content_23 = {
    Text = "Egal wie laut du rufst, es hilft nichts. Dein letztes Gespräch mit ihr endete mit Vorwürfen"
  },
  AvgDialog_49400_Content_24 = {
    Text = "Eine erodierte Existenz, kein Silberkernkontakt, du kannst sie nicht berühren"
  },
  AvgDialog_49400_Content_25 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_49400_Content_26 = {
    Text = "Warum, hat die Reise dich zu stolz gemacht?"
  },
  AvgDialog_49400_Content_27 = {
    Text = "Oder werde ich ohne dich zu einem weinerlichen, nutzlosen Kerl?"
  },
  AvgDialog_49400_Content_28 = {
    Text = "Die Stille der Wüste wird von einem plötzlichen Windstoß durchbrochen, der Himmel verdunkelt sich schnell, als ob alles Licht von der kommenden Wut verschlungen wird"
  },
  AvgDialog_49400_Content_29 = {
    Text = "Der Sandsturm tobt wie ein wütendes Ungeheuer, wirbelt Tonnen von Sand auf, verdunkelt den Himmel und verschlingt Sonne und Himmel"
  },
  AvgDialog_49400_Content_3 = {
    Text = "Da du darauf bestehst"
  },
  AvgDialog_49400_Content_30 = {
    Text = "In dieser tobenden Naturgewalt erscheint eine riesige Gestalt, die im Sandsturm flimmert"
  },
  AvgDialog_49400_Content_31 = {Text = "Sturmwand"},
  AvgDialog_49400_Content_32 = {
    Text = "Die Sturmwand wurde durch meine Macht herbeigerufen"
  },
  AvgDialog_49400_Content_33 = {
    Text = "Bist du... Thais...?"
  },
  AvgDialog_49400_Content_34 = {
    Text = "Es scheint unendliche Kraft zu besitzen, tanzt und verzerrt sich mit dem wirbelnden Sand, wie ein uraltes Wüstenmonster, das in einem Sandsturm nach Beute sucht"
  },
  AvgDialog_49400_Content_35 = {
    Text = "Seine Gestalt ist riesig und furchterregend, ein gewaltiger Kopf, scharfe Klauen und schwere Hufe, alles im wirbelnden Staub zu erkennen"
  },
  AvgDialog_49400_Content_36 = {
    Text = "So zu nennen, ist nicht falsch"
  },
  AvgDialog_49400_Content_37 = {
    Text = "Aber ich bin nicht die Königin, die du erwartest"
  },
  AvgDialog_49400_Content_38 = {
    Text = "Wenn du meine Macht nutzen willst, rufe laut meinen heiligen Namen –"
  },
  AvgDialog_49400_Content_39 = {
    Text = "Der riesige, seltsame Schatten verblasst allmählich, und die Gestalt, die du nicht erreichen konntest, tritt aus dem heulenden Sandsturm hervor"
  },
  AvgDialog_49400_Content_4 = {
    Text = "Wachen, lasst den Gesandten keinen Schaden nehmen"
  },
  AvgDialog_49400_Content_40 = {
    Text = "Der Kieselsturm tobte um sie herum, doch er konnte ihren Schritt nicht erschüttern"
  },
  AvgDialog_49400_Content_42 = {
    Text = "Die Königin! Die Königin ist zurückgekehrt!"
  },
  AvgDialog_49400_Content_43 = {
    Text = "Königin, die Augen der Königin sind immer auf uns gerichtet!"
  },
  AvgDialog_49400_Content_44 = {
    Text = "Ihr Blick war fest auf Yalan gerichtet, beobachtete die Vergangenheit und Zukunft, die durch seine Blutlinie strömten."
  },
  AvgDialog_49400_Content_45 = {
    Text = "Lady Thais..."
  },
  AvgDialog_49400_Content_46 = {
    Text = "Höret, alle Aran-Geschlechter! Die alte Prophezeiung ist wahr geworden; der Mutterbaum ist wieder erschienen, um die Verstorbenen zu krönen!"
  },
  AvgDialog_49400_Content_47 = {
    Text = "Die Königin kehrt im Sand zurück, um sich erneut auf den Thron zu setzen!"
  },
  AvgDialog_49400_Content_48 = {
    Text = "An die einzige Königin von Aran, Lady Thais—"
  },
  AvgDialog_49400_Content_49 = {
    Text = "Bringt eure Treue und euren Willen dar!"
  },
  AvgDialog_49400_Content_5 = {Text = "Ja!"},
  AvgDialog_49400_Content_6 = {
    Text = "Juliette kam näher und flüsterte dir nur einen Arm entfernt zu"
  },
  AvgDialog_49400_Content_7 = {
    Text = "Die Rückkehr zum heiligen Fluss ist das Schicksal der Aram, ich habe ihnen nur ein wenig beschleunigt"
  },
  AvgDialog_49400_Content_8 = {
    Text = "Wenn sein Blick ganz Kadath erfasst, werden sie mit dem heiligen Fluss in die neue Welt eintreten"
  },
  AvgDialog_49400_Content_9 = {
    Text = "Das ist dein Wille, nicht wahr?"
  },
  AvgDialog_49401_Content_1 = {
    Text = "Die Äste des Mutterbaums scheinen eigenen Willen zu haben, sich in alle Richtungen auszudehnen, menschliche Umrisse erscheinen darin, unbeholfen und schmerzhaft"
  },
  AvgDialog_49401_Content_10 = {
    Text = "Ramona, entzünde den Mutterbaum mit dem Silberchipfeuer! Nur du kannst das tun!"
  },
  AvgDialog_49401_Content_11 = {
    Text = "Der silberne Phantasma stößt auf die Wurzeln des Mutterbaums, die silberne Flamme entfacht in einem Moment und verwandelt sich in die lodernde Flamme namens Zerstörung"
  },
  AvgDialog_49401_Content_12 = {
    Text = "Die Flammenzungen schossen wie silberne Schlangen die Äste hinauf, die Blätter kämpften und schrien in den wütenden Flammen, ein ohrenbetäubendes Zischen, als ob der Mutterbaum vor Schmerz stöhnte und heulte"
  },
  AvgDialog_49401_Content_13 = {
    Text = "Warte, der Baum fällt, der Hüter ist noch nicht unten!"
  },
  AvgDialog_49401_Content_14 = {
    Text = "Keine Sorge, gutes Kind, ich werde {Male=er,Female=sie} dir unversehrt zurückbringen"
  },
  AvgDialog_49401_Content_15 = {
    Text = "Der riesige Baum bebt, Himmel und Erde erzittern"
  },
  AvgDialog_49401_Content_16 = {
    Text = "Du verlierst den Halt und fällst geradewegs nach unten—"
  },
  AvgDialog_49401_Content_17 = {
    Text = "Wie hoch ist es hier? Tausend Fuß? Oder mehr?"
  },
  AvgDialog_49401_Content_18 = {
    Text = "Dann umarmte dich ein warmer, weicher Schoß"
  },
  AvgDialog_49401_Content_19 = {
    Text = "Braves Kind, du hast das großartig gemacht"
  },
  AvgDialog_49401_Content_2 = {
    Text = "Der erste, der eine Kehle entwickelte, stöhnte und brach mühsam aus den Fesseln des Mutterbaums, stürzte in den heiligen Fluss"
  },
  AvgDialog_49401_Content_20 = {
    Text = "An ihrer Brust strahlt der von dir angelegte weiße Jadeanhänger im Kontrast zu ihrer seidigen Haut"
  },
  AvgDialog_49401_Content_21 = {
    Text = "Thais griff danach, nahm es ab und brachte es an ihren Mund, wo sie sanft darauf biss"
  },
  AvgDialog_49401_Content_22 = {
    Text = "Ich werde zum heiligen Fluss zurückkehren und das ganze Land nähren.\nDies ist ein Abschiedsgeschenk für dich"
  },
  AvgDialog_49401_Content_23 = {
    Text = "Im Moment des Sturzes in den reißenden Heiligen Fluss berührten ihre Lippen deine"
  },
  AvgDialog_49401_Content_24 = {
    Text = "Eure Atemzüge vermischen sich, eure Seelen verschmelzen"
  },
  AvgDialog_49401_Content_25 = {
    Text = "Eine Zunge drang ein, warm, feucht, zärtlich und unwiderstehlich"
  },
  AvgDialog_49401_Content_26 = {
    Text = "Der Kuss war eine Mischung aus süßer Liebe, dem Geschmack von Blut und einem kleinen, runden Etwas"
  },
  AvgDialog_49401_Content_27 = {
    Text = "Die Samen des Baumes"
  },
  AvgDialog_49401_Content_28 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_49401_Content_29 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_49401_Content_3 = {Text = "...Bumm!"},
  AvgDialog_49401_Content_30 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_49401_Content_31 = {
    Text = "Es ist zwar nicht so, wie ich es mir vorgestellt habe... aber es ist vorbei"
  },
  AvgDialog_49401_Content_32 = {
    Text = "Als Nachkommen der Essenz des Verlangens sind die Yaran bestrebt, ihre Blutlinie aufrechtzuerhalten."
  },
  AvgDialog_49401_Content_33 = {
    Text = "Zu diesem Zweck verehren wir den Mutterbaum, vermischen die Milch des Mutterbaums mit Knochen und Blut und beten für übermenschliche Fortpflanzungsfähigkeit"
  },
  AvgDialog_49401_Content_34 = {
    Text = "Solange eine Person der schwarzen Apokalypse entkommt, kann die Zivilisation in der nächsten Generation fortbestehen"
  },
  AvgDialog_49401_Content_35 = {
    Text = "Aber wir lagen falsch."
  },
  AvgDialog_49401_Content_36 = {
    Text = "Die Fortsetzung des Aran-Stammes hängt nicht von einer bestimmten Aran-Abstammung ab. Im Laufe der Zeit sind sie Sklaven des Konzepts \"Nachkommen\" geworden und übermäßig von dem Wunsch abhängig, sich fortzupflanzen."
  },
  AvgDialog_49401_Content_37 = {
    Text = "In Jahrhunderten des Exils... ist Alva es, die die Aram weiter führt"
  },
  AvgDialog_49401_Content_38 = {
    Text = "Tawil, du hast recht; wir sollten an den menschlichen Willen glauben"
  },
  AvgDialog_49401_Content_39 = {
    Text = "Selbst in der dunkelsten Nacht, selbst bei schwachem Licht, ist ihr unermüdlicher Geist der wahre Schlüssel zur Veränderung der vorherbestimmten Zukunft"
  },
  AvgDialog_49401_Content_4 = {Text = "Platschen!"},
  AvgDialog_49401_Content_40 = {
    Text = "Ich habe jetzt eine neue Antwort"
  },
  AvgDialog_49401_Content_41 = {
    Text = "Also, sei großzügig und leih mir deinen Erben, okay?"
  },
  AvgDialog_49401_Content_42 = {
    Text = "Ich vertraue dieser Person und übergebe das Feuer an {Male=er,Female=sie}"
  },
  AvgDialog_49401_Content_43 = {
    Text = "Dieser Samen wird eines Tages Wurzeln schlagen und zu einem riesigen Baum wachsen,"
  },
  AvgDialog_49401_Content_44 = {
    Text = "So wie am Tag der Geburt des ersten Mutterbaums"
  },
  AvgDialog_49401_Content_45 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_49401_Content_46 = {
    Text = "Das ist der letzte Samen, ich lasse ihn in deinem Körper"
  },
  AvgDialog_49401_Content_47 = {
    Text = "Bevor es mein Blut in die Erde trägt, darfst du nicht sterben"
  },
  AvgDialog_49401_Content_48 = {
    Text = "Erinnere dich immer an mich, vergiss mich nicht"
  },
  AvgDialog_49401_Content_49 = {
    Text = "Die Flut tobt"
  },
  AvgDialog_49401_Content_5 = {
    Text = "Dong! Dong!"
  },
  AvgDialog_49401_Content_50 = {
    Text = "Diese warme Umarmung stieß dich weg"
  },
  AvgDialog_49401_Content_51 = {
    Text = "Im Auf und Ab des Wassers siehst du, wie sie tiefer in den Fluss treibt"
  },
  AvgDialog_49401_Content_52 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_49401_Content_53 = {
    Text = "Eine zarte, weiße Hand hält dich fest, die Kraft ist vertraut und entschlossen"
  },
  AvgDialog_49401_Content_54 = {Text = "%player%!"},
  AvgDialog_49401_Content_6 = {
    Text = "Immer wieder fallen Aram"
  },
  AvgDialog_49401_Content_7 = {
    Text = "Einige Sekunden später tauchten kleine Köpfe aus dem Wasser und schwammen zum Ufer"
  },
  AvgDialog_49401_Content_8 = {
    Text = "Die Äste unter deinen Füßen beginnen zu zittern"
  },
  AvgDialog_49401_Content_9 = {
    Text = "Es ist Zeit!"
  },
  AvgDialog_49402_Content_1 = {Text = "Tanzen"},
  AvgDialog_49402_Content_10 = {
    Text = "Was verbirgt sich im Inneren der Sturmwand?"
  },
  AvgDialog_49402_Content_11 = {
    Text = "Was hat der geheimnisvolle Bote Juliette vor?"
  },
  AvgDialog_49402_Content_12 = {
    Text = "Worum geht es genau in Arlans Ritual?"
  },
  AvgDialog_49402_Content_13 = {
    Text = "Und ist der Thais, der hier vor uns steht, wirklich vertrauenswürdig?"
  },
  AvgDialog_49402_Content_14 = {
    Text = "Seit meiner Ankunft in Lemwahi haben ungewöhnliche Vorfälle nicht nachgelassen. Ein Geheimnis nach dem anderen lässt dich atemlos zurück."
  },
  AvgDialog_49402_Content_15 = {
    Text = "Du musst ruhig bleiben und nachdenken"
  },
  AvgDialog_49402_Content_16 = {
    Text = "Denk nicht mehr darüber nach, du bist müde, du brauchst Ruhe"
  },
  AvgDialog_49402_Content_17 = {
    Text = "Als du dich umdrehst, scheint nur der Vollmond auf Thais' schimmerndem Gesicht und es vermittelt einen durchsichtigen Eindruck"
  },
  AvgDialog_49402_Content_18 = {
    Text = "Auf der anderen Seite der Sturmwand... werden alle deine Fragen beantwortet"
  },
  AvgDialog_49402_Content_19 = {
    Text = "Auf der anderen Seite der Sturmwand"
  },
  AvgDialog_49402_Content_2 = {
    Text = "▼▼Im Chaos, niemand kennt das Ende.\nWas geschehen wird, liegt in meinen Worten, aber die Menschen haben ihr Gehör und ihre Sicht verloren,\nNur die Schweigsamen bedecken die Erde"
  },
  AvgDialog_49402_Content_20 = {
    Text = "Juliette hat das genauso gesagt. Musst du wirklich den Wünschen jener im Hintergrund folgen, um in den Sturm zu gelangen?"
  },
  AvgDialog_49402_Content_21 = {
    Text = "Oder treibt eine unsichtbare Macht alle wie Pilger in den Sturm?"
  },
  AvgDialog_49402_Content_22 = {
    Text = "In deinem Gedankensee wächst der Zweifel und die Angst wie Samen"
  },
  AvgDialog_49402_Content_23 = {
    Text = "Kann dein Herz nie zur Ruhe kommen?"
  },
  AvgDialog_49402_Content_24 = {
    Text = "Schließe deine Augen."
  },
  AvgDialog_49402_Content_25 = {
    Text = "Thais ist nur einen Wimpernschlag von deinem Atem entfernt"
  },
  AvgDialog_49402_Content_26 = {
    Text = "Schließe deine Augen."
  },
  AvgDialog_49402_Content_27 = {
    Text = "Augen nicht schließen"
  },
  AvgDialog_49402_Content_28 = {
    Text = "Klarer Blick... nicht getrübt von der Reise"
  },
  AvgDialog_49402_Content_29 = {
    Text = "Thais setzte ihren Zeigefinger auf deine Lippen"
  },
  AvgDialog_49402_Content_3 = {
    Text = "Du öffnest benommen die Augen und siehst einen klaren, funkelnden Sternenhimmel"
  },
  AvgDialog_49402_Content_30 = {
    Text = "Ihr Gesicht ist dir ganz nah, der Mondschein verleiht ihrer Haut einen sanften Glanz"
  },
  AvgDialog_49402_Content_31 = {
    Text = "Du spürst einen nahen Atem, sanft und warm"
  },
  AvgDialog_49402_Content_32 = {
    Text = "Was für ein nostalgischer Duft"
  },
  AvgDialog_49402_Content_33 = {
    Text = "Wie lange ist es her, dass wir uns so nahe waren?"
  },
  AvgDialog_49402_Content_34 = {
    Text = "Ein kühles Gefühl auf den Lippen"
  },
  AvgDialog_49402_Content_35 = {
    Text = "Du öffnest die Augen, Thais’ Zeigefinger drückt gegen deine Lippen.\nIhr Gesicht ist dir so nah, das Mondlicht verleiht ihrem Haut einen sanften Glanz"
  },
  AvgDialog_49402_Content_36 = {
    Text = "Weißt du? In deinen Augen sehe ich Clades, uralte Glut und den Atem des Universums."
  },
  AvgDialog_49402_Content_37 = {
    Text = "Deine Reise war lang und du bist erschöpft, oder? Aber dein Blick bleibt fest und klar"
  },
  AvgDialog_49402_Content_38 = {
    Text = "Die Sterne können dich nicht ändern, und die Sandsee vielleicht auch nicht"
  },
  AvgDialog_49402_Content_39 = {
    Text = "Ich verstehe nicht, was du meinst"
  },
  AvgDialog_49402_Content_4 = {
    Text = "Wie bin ich... eingeschlafen?"
  },
  AvgDialog_49402_Content_40 = {
    Text = "Du musst es jetzt noch nicht verstehen"
  },
  AvgDialog_49402_Content_41 = {
    Text = "Thais stand auf und schlenderte zu den Dünen hinunter"
  },
  AvgDialog_49402_Content_42 = {
    Text = "Unter diesem Sternenhimmel nur zu sitzen, ist zu unromantisch"
  },
  AvgDialog_49402_Content_43 = {
    Text = "Der Wind hob ihren durchsichtigen Schleier, sie schwebte über den weichen Sand"
  },
  AvgDialog_49402_Content_44 = {
    Text = "Lass mich dir diesen Tanz von Yalan präsentieren."
  },
  AvgDialog_49402_Content_45 = {
    Text = "Die Glocke läutet, sie hebt einen Arm und beginnt zu tanzen"
  },
  AvgDialog_49402_Content_46 = {
    Text = "Sie beugt sich, streckt sich, manchmal wild, manchmal zurückhaltend"
  },
  AvgDialog_49402_Content_47 = {
    Text = "Ich habe immer auf jemanden gewartet"
  },
  AvgDialog_49402_Content_48 = {
    Text = "Ihre Gestalt ist geschmeidig, ihr Tanz gleicht einer Schlange"
  },
  AvgDialog_49402_Content_49 = {
    Text = "Ein Beobachter, der Yalan in die „Zukunft“ führen kann."
  },
  AvgDialog_49402_Content_5 = {
    Text = "Nach langer Wanderung in der Wüste ist Müdigkeit ganz normal"
  },
  AvgDialog_49402_Content_50 = {
    Text = "Sie drehte und bewegte sich, selbst ihre Nachbilder strahlten angeborene Eleganz und unglaubliche Flexibilität aus"
  },
  AvgDialog_49402_Content_51 = {
    Text = "Ist Elva nicht diese Person?"
  },
  AvgDialog_49402_Content_52 = {
    Text = "Thais drehte sich um, senkte den Blick und die anmutige Blume streifte über ihre seufzende Lippen"
  },
  AvgDialog_49402_Content_53 = {
    Text = "Elva ist ein gutes Kind, aber sie kann noch keinen neuen Weg erschließen"
  },
  AvgDialog_49402_Content_54 = {
    Text = "Was ist mit Juliette? Ist sie nicht die Botschafterin eines fremden Landes?"
  },
  AvgDialog_49402_Content_55 = {
    Text = "Hast du gerade gesagt, dass der Weg, den Juliette für die Aran suchte, aus der Wüste herausführt?"
  },
  AvgDialog_49402_Content_56 = {
    Text = "Thais streckte die Arme aus und blickte mit ihrem wandernden Blick zum Mond an ihren Fingerspitzen, als wollte sie die unsichtbaren Vögel verabschieden"
  },
  AvgDialog_49402_Content_57 = {
    Text = "Diejenigen, die gehen konnten, sind bereits gegangen. Yalan hat niemanden gebunden. Ob es eine Bindung an die Heimat oder eine Anpassung an das Leben in der Wüste ist, diejenigen, die geblieben sind, können hier nur überleben."
  },
  AvgDialog_49402_Content_58 = {
    Text = "Zumal das nicht die Antwort ist, die ich erwartet habe"
  },
  AvgDialog_49402_Content_59 = {
    Text = "Welche Antwort erwartest du?"
  },
  AvgDialog_49402_Content_6 = {
    Text = "Ich habe noch viele Fragen"
  },
  AvgDialog_49402_Content_60 = {
    Text = "Es steht schon lange in den Liedern"
  },
  AvgDialog_49402_Content_61 = {
    Text = "Der Heilige Fluss des Wiedergeborenen Mutterbaums krönt die Verstorbenen und bringt ihre Blutlinie zu Yalan zurück."
  },
  AvgDialog_49402_Content_62 = {
    Text = "Die Wiedergeburt des Heiligen Flusses des Mutterbaums ist leicht zu verstehen, aber wer sind die Verstorbenen? Und wie bringen wir die Blutlinie zurück zu Yalan?"
  },
  AvgDialog_49402_Content_63 = {Text = "Shh—"},
  AvgDialog_49402_Content_64 = {
    Text = "Die Details sind zu komplex, @1s Prophezeiung kann nicht alle Antworten geben"
  },
  AvgDialog_49402_Content_65 = {
    Text = "Alles, was du tun musst, ist, mir vollkommen zu vertrauen.\nVertraue der Königin von Aran."
  },
  AvgDialog_49402_Content_66 = {
    Text = "Die Wüstenblume blüht in der dunklen Mondnacht, sie hebt die Hand, dreht sich und tanzt in einem alten Rhythmus auf dem Sand"
  },
  AvgDialog_49402_Content_67 = {
    Text = "Solange du mir vertraust, bin ich deine absolute, einzige, nur für dich bestimmte - Geheimwaffe"
  },
  AvgDialog_49402_Content_68 = {
    Text = "Im Mondlicht ist ihre Silhouette weich und geheimnisvoll, ihre Augen sprechen unausgesprochene Gefühle"
  },
  AvgDialog_49402_Content_69 = {
    Text = "Wenn dies ein endender Traum ist –\nferne Sterne sind ihre Zeugen"
  },
  AvgDialog_49402_Content_7 = {
    Text = "Der lange Traum scheint dich von der angespannten Reise zu lösen, eine Frage nach der anderen taucht in deinem Kopf auf"
  },
  AvgDialog_49402_Content_70 = {
    Text = "Warte, Thais, unter deinem Fuß—"
  },
  AvgDialog_49402_Content_71 = {
    Text = "Du rufst verzweifelt"
  },
  AvgDialog_49402_Content_72 = {
    Text = "Sie trat auf die Wellen, nein, schwarze Wellen breiteten sich von ihren Zehenspitzen aus"
  },
  AvgDialog_49402_Content_73 = {
    Text = "Der Rand des weißen Schleiers schwingt wie tanzende Seerosenblätter, glänzend und tiefschwarz"
  },
  AvgDialog_49402_Content_74 = {
    Text = "Das ist ... D-Schleim ...?"
  },
  AvgDialog_49402_Content_75 = {
    Text = "Sie tanzte in einem illusorischen Schmelzbecken, immer wieder auf der schwarzen Oberfläche"
  },
  AvgDialog_49402_Content_76 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_49402_Content_77 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_49402_Content_78 = {
    Text = "Sie scheint deinen Ruf nicht zu hören und tanzt im Einklang mit einer unbekannten Melodie"
  },
  AvgDialog_49402_Content_79 = {
    Text = "Sie drehte sich zu dir um, ihre Haltung entspannt, die Kette, die du ihr angelegt hast, funkelte auf ihrer Brust"
  },
  AvgDialog_49402_Content_8 = {
    Text = "Warum verwandelt sich das Wasser in Ramonas Wassersack in D-Schleim?"
  },
  AvgDialog_49402_Content_80 = {
    Text = "Sie lud dich zum Tanzen ein, und du legtest automatisch deine Hand in ihre"
  },
  AvgDialog_49402_Content_81 = {
    Text = "Sie nahm deine Hand und führte deine Fingerspitze zu dem pulsierenden Jade"
  },
  AvgDialog_49402_Content_82 = {
    Text = "Ein Meteor fällt vom fernen Himmel.\nIhre Augen leuchten heller als die Sterne"
  },
  AvgDialog_49402_Content_84 = {
    Text = "Ihre Lippen öffneten sich leicht, der Abendwind trug ihr leises Flüstern herbei"
  },
  AvgDialog_49402_Content_85 = {
    Text = "Kann ich sie dir anvertrauen?"
  },
  AvgDialog_49402_Content_86 = {
    Text = "Ein Gefühl, ähnlich dem bei der Lagerfeuerparty, ergriff dich, und fast unwillkürlich murmelst du"
  },
  AvgDialog_49402_Content_87 = {
    Text = "Ja, es wird klappen"
  },
  AvgDialog_49402_Content_88 = {Text = "Gut."},
  AvgDialog_49402_Content_89 = {
    Text = "Thais lächelte"
  },
  AvgDialog_49402_Content_9 = {
    Text = "Wer verbreitet die Nubier?"
  },
  AvgDialog_49402_Content_90 = {
    Text = "Deine Freunde sind angekommen."
  },
  AvgDialog_49402_Content_91 = {
    Text = "Du folgst dem Blick von Thais und siehst Ramona auf dich zulaufen, während Ryker ihr schnell, aber sicher folgt, ohne an Anmut und Eleganz einzubüßen"
  },
  AvgDialog_49402_Content_92 = {
    Text = "Vergiss nicht, dass diese Nacht nur unser Geheimnis gehört"
  },
  AvgDialog_49402_Content_93 = {
    Text = "Beim erneuten Hinsehen war Thais' Gestalt verschwunden, nur der Wind pfiff durch die Wüste"
  },
  AvgDialog_49402_Content_94 = {
    Text = "Vor dir im Sand drang ein dunkler Auflösungs-Schleim in den Treibsand ein und verband sich mit der Erde"
  },
  AvgDialog_49414_Content_1 = {
    Text = "Hüter, die Funktion Erinnerung wurde aktiviert. Um sie zu nutzen, tippe auf den Kommunikator und rufe Erica nach dem Piepton an, um den Rückruf einzuleiten."
  },
  AvgDialog_49414_Content_2 = {
    Text = "Erinnerung... Was ist das?"
  },
  AvgDialog_49414_Content_3 = {
    Text = "Ihre Erinnerungsaufzeichnungen werden hier vorübergehend gespeichert. Über die Erinnerungsfunktion können Sie Ihre Erlebnisse in verschiedenen Ermittlungsereignissen leichter abrufen."
  },
  AvgDialog_49414_Content_4 = {
    Text = "Achte auf die Details, die du einst übersehen hast. Menschen müssen immer aus der Vergangenheit lernen, um der Zukunft zu begegnen."
  },
  AvgDialog_49440_Content_1 = {
    Text = "(Keuchen, keuchen...)"
  },
  AvgDialog_49440_Content_2 = {
    Text = "Karen...? Was machst du da?"
  },
  AvgDialog_49440_Content_3 = {
    Text = "Deine Sicht ist komplett dunkel. Etwas bedeckt deine Augen."
  },
  AvgDialog_49440_Content_4 = {
    Text = "Du versuchst, deine Hände zu heben, aber der weiche Stoff fesselt deine Handgelenke und erlaubt nur eine eingeschränkte Bewegung."
  },
  AvgDialog_49440_Content_5 = {
    Text = "Ist es nicht offensichtlich? Natürlich... es ist eine gründliche Reinigung~"
  },
  AvgDialog_49440_Content_6 = {
    Text = "Warum werde ich für die Frühjahrsputzaktion gefesselt?"
  },
  AvgDialog_49440_Content_7 = {
    Text = "Ein Gefühl der Vorahnung steigt in dir auf. Die unvorhersehbaren Handlungen dieser schwer fassbaren Magd unter dem Einfluss des Heiligen Flusses übersteigen deine Erwartungen."
  },
  AvgDialog_49440_Content_8 = {
    Text = "Der Schlüssel zu einer gründlichen Reinigung ist Gründlichkeit! Der Hüter ist auch Teil der Reinigung!"
  },
  AvgDialog_49440_Content_9 = {
    Text = "Hier, da... Jeder Ort muss gründlich gereinigt werden~"
  },
  AvgDialog_49441_Content_1 = {
    Text = "Erica, kannst du finden, auf welchem Regal sich der Brief A-617 befindet?"
  },
  AvgDialog_49441_Content_10 = {Text = "Ai—"},
  AvgDialog_49441_Content_11 = {
    Text = "Deine Stimme wird von einem leisen Elektrizitätsstrom in deinen Magen zurückgedrängt, und das Gefühl in deinen gefalteten Händen übersteigt das, was gewöhnliche Menschen ertragen können."
  },
  AvgDialog_49441_Content_12 = {
    Text = "Ein kurzer und strahlender Strom weckt alle deine Sinne, eine außergewöhnliche Verknüpfung weckt indes beschreibbares Verlangen in deinem Blut."
  },
  AvgDialog_49441_Content_13 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_49441_Content_14 = {
    Text = "Erica zwinkerte und zog ihre Hand zurück."
  },
  AvgDialog_49441_Content_15 = {
    Text = "Alright. Der Brief A-617 befindet sich im eingeschränkten Bereich des Archivs, vor dem Hüter."
  },
  AvgDialog_49441_Content_16 = {
    Text = "Nachdem sie gesprochen hatte, drehte sich Erica um und ging in die Sperrzone, ohne sich umzudrehen, und ließ dich mit dem Knistern zurück."
  },
  AvgDialog_49441_Content_17 = {
    Text = "...Automaten werden nicht von der Anomalie des Heiligen Flusses betroffen sein, oder?"
  },
  AvgDialog_49441_Content_18 = {
    Text = "Ist das richtig?"
  },
  AvgDialog_49441_Content_2 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_49441_Content_3 = {Text = "Erica?"},
  AvgDialog_49441_Content_4 = {
    Text = "Der Roboter steht still in der Ecke des Raumes, trägt sein gewohntes Lächeln, aber die Stille lässt das Lächeln noch unheimlicher erscheinen."
  },
  AvgDialog_49441_Content_5 = {
    Text = "Du winkst zweimal vor ihren Augen, aber es gibt kein Anzeichen von Bewegung in ihren Augen."
  },
  AvgDialog_49441_Content_6 = {
    Text = "Seltsam, Erica ist nie abwesend... Könnte es ein Problem mit ihrem mechanischen Körper geben?"
  },
  AvgDialog_49441_Content_7 = {
    Text = "Du murmelst für dich selbst, während du um Ericas Hülle herumkreisst."
  },
  AvgDialog_49441_Content_8 = {
    Text = "—Rumpeln."
  },
  AvgDialog_49441_Content_9 = {
    Text = "Das schwache Geräusch einer Explosion lenkte deine Aufmerksamkeit auf sich. Instinktiv blickstest du in die Richtung der Quelle, nur um deine Hand gepackt zu bekommen."
  },
  AvgDialog_49442_Content_1 = {Text = "Traum"},
  AvgDialog_49442_Content_10 = {Text = "Platsch—"},
  AvgDialog_49442_Content_11 = {
    Text = "Die Welt erlangte wieder Klang und Farbe"
  },
  AvgDialog_49442_Content_12 = {
    Text = "Einer nach dem anderen sprangen sie entschlossen in die reißenden Fluten des heiligen Flusses, streckten ihre Arme aus und umarmten den vertrockneten Stamm des Mutterbaums"
  },
  AvgDialog_49442_Content_13 = {
    Text = "Sie schreien wie besessen, erzeugen unbeschreibliche wahnhaften Geschrei"
  },
  AvgDialog_49442_Content_14 = {
    Text = "Ihre Haut wird schlaff wie weicher Schlamm; ihre Körperflüssigkeiten verlassen den Körper und bilden den heiligen Fluss"
  },
  AvgDialog_49442_Content_15 = {
    Text = "Ihre Knochen scheinen wie Fleisch zu erweichen; die Gliedmaßen winden, dehnen und verweben sich auf unhumane Weise und bilden aus ihrem eigenen Blut und Fleisch den massiven, fetten Stamm des heiligen Baumes"
  },
  AvgDialog_49442_Content_16 = {
    Text = "Sie verschmelzen langsam und schmerzhaft mit dem heiligen Baum"
  },
  AvgDialog_49442_Content_2 = {
    Text = "Letztlich ist die Puppe nicht perfekt, sie erfordert zu viel Kontrolle"
  },
  AvgDialog_49442_Content_3 = {
    Text = "Je stärker deine Entschlossenheit ist, für Arlan zu opfern, desto heftiger ist dein Widerstand, sobald die Wahrheit ans Licht kommt."
  },
  AvgDialog_49442_Content_4 = {
    Text = "Zum Glück habe ich diese Situation vorhergesehen"
  },
  AvgDialog_49442_Content_5 = {
    Text = "Die Zeit ist fast um, ihr alle, für euren geliebten Mutterbaum"
  },
  AvgDialog_49442_Content_6 = {
    Text = "Bringt Fleisch und Leben dar"
  },
  AvgDialog_49442_Content_7 = {
    Text = "Ich öffnete den Mund, konnte keinen Ton herausbringen.\nAlles um mich herum erstarrte vor Angst"
  },
  AvgDialog_49442_Content_8 = {
    Text = "Nein, die Welt steht nicht still, sondern meine Wahrnehmung, jedes Blinzeln scheint ein Jahrhundert zu dauern"
  },
  AvgDialog_49442_Content_9 = {
    Text = "In der stagnierenden und endlosen Reihenfolge marschierten nur meine ehemaligen Kameraden, nacheinander, die Yalan-Soldaten, in Richtung des Heiligen Flusses."
  },
  AvgDialog_49443_Content_1 = {
    Text = "Unter dem Mutterbaum kniet die hilflose Alva in Tränen"
  },
  AvgDialog_49443_Content_10 = {
    Text = "Gut, dass du mitgekommen bist. Jede Minute, die ich zurückgehe, um dich zu holen, kostet unzählige Leben"
  },
  AvgDialog_49443_Content_11 = {
    Text = "Die Stimme in meinem Kopf... sie sagte mir... ich muss durchhalten"
  },
  AvgDialog_49443_Content_12 = {
    Text = "Aber, auch wenn sie nichts sagt...\nIch bin %player%s einziger Assistent, in der gefährlichsten Zeit muss ich bei {Male=er,Female=sie} sein"
  },
  AvgDialog_49443_Content_13 = {
    Text = "Das ist meine Pflicht als einziger Assistent, oder?"
  },
  AvgDialog_49443_Content_14 = {
    Text = "Sie betonte das Wort „einzige“ sehr stark"
  },
  AvgDialog_49443_Content_15 = {
    Text = "Wenn du ihre Kraft auf diesem Land erweckst, wird dein Körper stärker beeinflusst"
  },
  AvgDialog_49443_Content_16 = {
    Text = "Wenn es einen anderen Weg gäbe, würde ich ihn nicht wählen"
  },
  AvgDialog_49443_Content_17 = {
    Text = "Missaga ist hier, um das Ritual zu stoppen. Ich bin ein Mitglied von Missaga, bereit zu sterben!"
  },
  AvgDialog_49443_Content_18 = {
    Text = "Gut! Ramona unterdrückt die Essenz der Begierde, %player%, du und ich werden den Mutterbaum vollständig vernichten!"
  },
  AvgDialog_49443_Content_19 = {
    Text = "Ein ohrenbetäubendes Heulen ertönte am Himmel, ein silberner Schatten zog über die Wüste"
  },
  AvgDialog_49443_Content_2 = {
    Text = "Ich verstecke die Mutterbaum von dem heiligen Fluss und trage den Samen der Auflösung im Fleisch, ist das nicht, um auf diesen Moment zu warten?"
  },
  AvgDialog_49443_Content_21 = {
    Text = "Du fühlst, wie dein Körper leicht wird, und im nächsten Moment landest du vor einem stinkenden Tumor"
  },
  AvgDialog_49443_Content_22 = {
    Text = "Die von der Mutterbaum verschlungenen Aram sammeln sich hier in embryonaler Form, in halbtransparenten Löchern erscheinen zahlreiche verzerrte und verschwommene Gesichter, und nur schwarze und rote Schleimströme fließen unaufhörlich aus den Löchern in den immer weniger klaren heiligen Fluss"
  },
  AvgDialog_49443_Content_3 = {
    Text = "Die Stunde des Endkampfes ist gekommen!"
  },
  AvgDialog_49443_Content_4 = {
    Text = "Ich bitte im Namen des Wesens der Begierde, Tifréh Yesod, um <Yellow: Tawil>, bitte antworte auf unser Versprechen von vor tausend Jahren —"
  },
  AvgDialog_49443_Content_5 = {
    Text = "Wenn der Bote aus der Ferne ankommt, benutze deinen Avatar als Führer, um die Schatten über Lemoah vorübergehend für mich zu vertreiben."
  },
  AvgDialog_49443_Content_6 = {
    Text = "Ein lautes Klagelied ertönte am Himmel"
  },
  AvgDialog_49443_Content_7 = {
    Text = "Thais öffnete den Sarg, und heraus rollte zu ihrer Überraschung die rot glühende Ramona"
  },
  AvgDialog_49443_Content_8 = {
    Text = "Endlich... brauchst du mich"
  },
  AvgDialog_49443_Content_9 = {
    Text = "Hier drin zu verstecken und mitzukommen, das ist wirklich ein Einfall, kleines Mädchen"
  },
  AvgDialog_49476_Content_1 = {
    Text = "Die Tür öffnete sich leise, und das Licht enthüllte eine vertraute Silhouette."
  },
  AvgDialog_49476_Content_10 = {
    Text = "Es scheint, dass der Einfluss des Heiligen Flusses deine Dimension erreicht hat... Geht es dir gut?"
  },
  AvgDialog_49476_Content_11 = {
    Text = "Kannst du mir Gesellschaft leisten, Hüter?"
  },
  AvgDialog_49476_Content_12 = {
    Text = "Sicher, sicher. Es ist nur so, dass ich nicht weiß, wie ich dir helfen kann..."
  },
  AvgDialog_49476_Content_13 = {
    Text = "Ich möchte dich irgendwohin mitnehmen."
  },
  AvgDialog_49476_Content_14 = {Text = "Wo?"},
  AvgDialog_49476_Content_15 = {
    Text = "Ramona sitzt neben dir. Die Röte vermischt sich natürlich mit dem Licht und ihrer hellen Haut, was dich Atem holen lässt."
  },
  AvgDialog_49476_Content_16 = {
    Text = "In dem Moment, als sie deine Hand nahm, begann der Raum um dich herum sich zu verlagern. Unzählige Bilder vereinigten sich zu einer chaotischen Szene, die unheimlich vertraut erschien."
  },
  AvgDialog_49476_Content_17 = {
    Text = "Die Szene hier ist chaotisch... Sind diese aus deiner Erinnerung?"
  },
  AvgDialog_49476_Content_18 = {
    Text = "Entschuldigung... Ich habe diese Szene viele Male erlebt. Die Erinnerungen sind zu komplex... Aber ich denke, du kannst diesen Ort deutlich sehen."
  },
  AvgDialog_49476_Content_19 = {
    Text = "Diese verschwommenen Sicht- und Gerüche, so vertraut... Wie die Nachwirkungen einer gewaltigen Explosion... Könnte dieser Ort sein?!"
  },
  AvgDialog_49476_Content_2 = {
    Text = "Ramona? Hast du nicht gesagt, dass du morgen eine Prüfung hast und heute früh ins Bett gehen solltest?"
  },
  AvgDialog_49476_Content_20 = {
    Text = "Akut, der Ort, an dem die Erinnerungen deines Lebens begonnen haben... und wo du mich in dieser Welt getroffen hast."
  },
  AvgDialog_49476_Content_21 = {Text = "!!!"},
  AvgDialog_49476_Content_22 = {
    Text = "Keeper, es gibt Dinge, die du längst vergessen hast, aber ich erinnere mich noch an sie alle."
  },
  AvgDialog_49476_Content_23 = {
    Text = "Hier habe ich dich verloren, immer wieder. Jedes Mal ist es mir lebhaft in Erinnerung geblieben."
  },
  AvgDialog_49476_Content_24 = {
    Text = "Nur dieses eine Mal bist du in die unendliche Zerstörung abgestiegen, auf den einzigen Hoffnungsschimmer... aber dieser Hoffnungsschimmer hatte nichts mit mir zu tun."
  },
  AvgDialog_49476_Content_25 = {
    Text = "Ein scharfer Schmerz durchbohrt dein Herz wie eine Klinge. Du streckst deine Arme aus und ziehst das Mädchen in deine Umarmung."
  },
  AvgDialog_49476_Content_26 = {
    Text = "Dieses Mal wehrte sich das ruhige Mädchen, das über unzählige Zeitlinien gekämpft hatte, nicht."
  },
  AvgDialog_49476_Content_27 = {
    Text = "Sie kuschelt gehorsam in deinen Armen und reibt sanft ihren Kopf gegen deine Brust, wie eine Katze, die nach einem Schmerz zu ihrem Besitzer zurückkehrt."
  },
  AvgDialog_49476_Content_28 = {
    Text = "In dieser Dimension hast du viele Gefährten an deiner Seite. Puppe, Czort, Alistair... und ich, der immer mit dir in dieser Welt war."
  },
  AvgDialog_49476_Content_29 = {
    Text = "Ich glaube, Sie werden reibungslos vorankommen und erreichen, was Sie sich wünschen."
  },
  AvgDialog_49476_Content_3 = {
    Text = "Perfekte Timing! Professor Dexter hat gerade erwähnt, dass er morgen zu Hause das Mittagessen zubereiten wird. Wir können direkt nach unserer Beurteilung vorbeikommen."
  },
  AvgDialog_49476_Content_30 = {
    Text = "Ich hätte nicht so erscheinen sollen. Mit Erfahrungen aus so vielen verschiedenen Zeitlinien hätte ich reifer werden sollen."
  },
  AvgDialog_49476_Content_31 = {
    Text = "Aber ich will dich nicht nochmal verlieren, Hüter."
  },
  AvgDialog_49476_Content_32 = {
    Text = "Kristallklares Liquid tropft aus dem Augenpflaster des Mädchens, fließt durch ihr blasses Haar und über ihre roten Wangen."
  },
  AvgDialog_49476_Content_33 = {
    Text = "Ihre Stirn drückte an Ihre, ihr Haar strich sanft über Ihre Wange. Ihr Atem blieb Ihnen stecken, während Sie durch die weiche Augenbinde auf ihre abwesenden, mit Tränen gefüllten Augen starrten."
  },
  AvgDialog_49476_Content_34 = {
    Text = "Ihre kühle, zitternde Stimme flüstert dir ins Ohr, warmer Atem streicht über dich, wie zahllose zarte Murmeln aus verschiedenen Zeiten und Räumen."
  },
  AvgDialog_49476_Content_35 = {
    Text = "Die Schuluniform des Mythag-Schülers, abgetragen und zerfetzt aus unzähligen Kämpfen, gleitet sanft in deine Hände."
  },
  AvgDialog_49476_Content_36 = {
    Text = "Wie wäre es, wenn wir es dem Einfluss des Heiligen Flusses zuschreiben?"
  },
  AvgDialog_49476_Content_37 = {
    Text = "Heute lass mich kindisch sein. Zum letzten Mal."
  },
  AvgDialog_49476_Content_4 = {
    Text = "Ich würde gerne gehen, Hüter. Es ist lange her, dass ich meinen Vater das letzte Mal gesehen habe... Allerdings fürchte ich, dass ich nicht geeignet bin, in seinem Haus zu erscheinen."
  },
  AvgDialog_49476_Content_5 = {
    Text = "Die gleiche Gestalt, die gleiche Stimme, doch ohne jede Spur von Naivität. Was bleibt, ist eine Gelassenheit, geformt durch Entbehrungen, und ein Hauch von unerklärlichem Unbehagen."
  },
  AvgDialog_49476_Content_6 = {
    Text = "Unter dem Licht erscheind, dem Klang folgend, ist das unvergessliche Augenpflaster."
  },
  AvgDialog_49476_Content_7 = {
    Text = "Bist du das?"
  },
  AvgDialog_49476_Content_8 = {
    Text = "Entschuldigung, ich sagte, ich würde dich nicht belästigen, aber..."
  },
  AvgDialog_49476_Content_9 = {
    Text = "Unter dem schwarzen Augenpflaster des Mädchens erschien ein ungewöhnlicher Schimmer auf ihrem zuvor blassen Gesicht."
  },
  AvgDialog_49742_Content_1 = {
    Text = "Du hast jeden gefragt: Puppe, Erica, Sylvie, czort, Hanna"
  },
  AvgDialog_49742_Content_10 = {Text = "Hüter..."},
  AvgDialog_49742_Content_11 = {
    Text = "Ramona zog sich subtil einen halben Schritt zurück und zeigte einen distanzierten Ausdruck dir gegenüber."
  },
  AvgDialog_49742_Content_12 = {
    Text = "Es tut mir leid, bitte komm vorerst nicht näher, ich..."
  },
  AvgDialog_49742_Content_13 = {
    Text = "Die Störung des Heiligen Flusses beeinflusste viele Erwachte. Ich dachte... ich wäre eine Ausnahme, angesichts meines... Status..."
  },
  AvgDialog_49742_Content_14 = {
    Text = "Ramona ist Ramona, und das wird sich nie ändern."
  },
  AvgDialog_49742_Content_15 = {
    Text = "Ich bin, wer ich bin..."
  },
  AvgDialog_49742_Content_16 = {Text = "Ja. Genau!"},
  AvgDialog_49742_Content_17 = {
    Text = "Du machst fest zwei Schritte nach vorne, gehst zu ihr und hältst ihre Hand."
  },
  AvgDialog_49742_Content_18 = {
    Text = "Ob in der Stadt La'i oder in meinen Träumen, egal wie oft du mich fragst, meine Antwort wird immer gleich bleiben."
  },
  AvgDialog_49742_Content_19 = {
    Text = "Eine unwiderstehliche Kraft zieht dich zu Ramona. Sie fängt deine taumelnden Schritte auf, ihre Arme kreuzen sich hinter deinem Rücken, und ihr Kinn ruht auf deiner linken Schulter."
  },
  AvgDialog_49742_Content_2 = {
    Text = "Jeder zeigte dir in die gleiche Richtung. Sie wollen, dass du den Campus-Innenhof überquerst und das kunstvoll verzierte Eisentor am Ende des Steinwegs aufstößt."
  },
  AvgDialog_49742_Content_20 = {
    Text = "Ihre einfachen Worte haben meine Seele beruhigt... War ich in letzter Zeit zu angespannt?"
  },
  AvgDialog_49742_Content_21 = {
    Text = "Du bist einfach zu müde, wie wir alle."
  },
  AvgDialog_49742_Content_22 = {
    Text = "Seine Hände umschlossen instinktiv ihre Taille. Die Welt verstummte, nur das Geräusch eures Atems blieb, während ihr weiterhin intime Wärme voneinander aufnahmt."
  },
  AvgDialog_49742_Content_23 = {
    Text = "...Danke, %player%."
  },
  AvgDialog_49742_Content_24 = {
    Text = "Ramona ist die erste, die sich von der Zuflucht zurückzieht. Sie hält deine Schulter, möchte etwas sagen, zögert aber."
  },
  AvgDialog_49742_Content_25 = {
    Text = "Gibt es sonst noch etwas, das du mir sagen möchtest?"
  },
  AvgDialog_49742_Content_26 = {
    Text = "Nein, jetzt nicht."
  },
  AvgDialog_49742_Content_27 = {
    Text = "Sie klopft dir auf die Schulter und deutet auf den Ausgang."
  },
  AvgDialog_49742_Content_28 = {
    Text = "Geh zurück, okay? Ich verspreche, dass du mich morgen wieder normal sehen wirst."
  },
  AvgDialog_49742_Content_29 = {
    Text = "Sie braucht jetzt mehr Zeit und Raum, und das verstehst du vollkommen."
  },
  AvgDialog_49742_Content_3 = {
    Text = "Als du das Schlüsselgrab betrittst, entfesseln die Sturmwolken über dir ihr erstes Donnergrollen. Ein harscher Blitz schlägt vom Himmel hinab und springt zum Horizont."
  },
  AvgDialog_49742_Content_30 = {
    Text = "Ramona ließ einen schweren Seufzer los, während sie zusah, wie die Figur ihres Partners unter den Steinmonumenten verschwand."
  },
  AvgDialog_49742_Content_31 = {
    Text = "Ihre Kehle brannte wie Feuer, jeder Atemzug glich dem schmerzhaften Keuchen eines Patienten—aber vor ihrem Partner verbarg sie ihr Unbehagen mit aller Kraft."
  },
  AvgDialog_49742_Content_32 = {
    Text = "Sie setzte sich langsam vor das schlüsselförmige Denkmal, als würde sie vom Schicksal geleitet, ihre Finger drückten auf die eingravierten Namen."
  },
  AvgDialog_49742_Content_33 = {
    Text = "Sie neigte den Kopf, ihre Lippen drückten sich langsam gegen die kalte Oberfläche des Denkmals und fühlten die Wärme des Schicksals mit ihrer Sanftheit."
  },
  AvgDialog_49742_Content_34 = {
    Text = "%player%..."
  },
  AvgDialog_49742_Content_35 = {
    Text = "Dies ist der Name, den sie nie vergessen wird, niemals."
  },
  AvgDialog_49742_Content_4 = {
    Text = "Es wird bald regnen... Warum kam sie bei so einem Wetter zum Schlüsselgrab?"
  },
  AvgDialog_49742_Content_5 = {
    Text = "Sie ist eine kluge Person; „den Regen voraussehen“ ist ihr Markenzeichen. Vorfahrenrituale am Vorabend eines Regens? Das entspricht nicht ihrem Stil."
  },
  AvgDialog_49742_Content_6 = {
    Text = "Du machst dich auf den Weg durch die einzigartig gestalteten schlüsselförmigen Säulen und erblickst schließlich die vertraute Gestalt in der Ferne."
  },
  AvgDialog_49742_Content_7 = {
    Text = "Sie steht im Zentrum der Aluvialen Ära 315 schlüsselförmigen Stele-Gruppe und neigt ihren Kopf zu einem Grabstein.\nSie scheint in ein unbekanntes Gefühl vertieft, sich nicht bewusst über dein Eintreffen."
  },
  AvgDialog_49742_Content_8 = {
    Text = "Der kalte, feuchte Wind vor dem Regen trägt den Klang des Lebens fort. Das Schlüsselgrab ist ein weites Grab. Das Mädchen steht dort, ihr schwarzer Umhang wird vom Wind um ihren Körper gewickelt, wie eine einsame Friedhofswärterin."
  },
  AvgDialog_49742_Content_9 = {
    Text = "Ramona, ich bin's."
  },
  AvgDialog_49825_Content_1 = {
    Text = "Was dich geweckt hat, war nicht die Morgensonne von Mythag, sondern ein seltsames Gefühl, das durch dein Blut floss."
  },
  AvgDialog_49825_Content_10 = {
    Text = "<Big:Wie wagst du es, zu widersprechen!>"
  },
  AvgDialog_49825_Content_11 = {
    Text = "Hmph... Ich werde dir heute das Prinzip beibringen, dass \"nichts mehr als dreimal passiert\"."
  },
  AvgDialog_49825_Content_2 = {
    Text = "Wie feine Nadeln, die stechen, oder die Beine von Arthropoden, die entlang der inneren Wände von Blutgefäßen krabbeln. Der dichte, prickelnde Juckreiz sticht in die Nerven und verursacht unkontrollierbare Krämpfe im ganzen Körper."
  },
  AvgDialog_49825_Content_3 = {
    Text = "Hör auf, **so zu tun, als ob du schläfst, ich weiß, dass du wach bist!**"
  },
  AvgDialog_49825_Content_4 = {
    Text = "Während du kämpfst, um deine Augen zu öffnen, versetzt dir der Anblick davor den Atem in den Hals—"
  },
  AvgDialog_49825_Content_5 = {
    Text = "Ein Labyrinth ohne Ausgang, das Versteck des Blassen Lords, und ein Mädchen mit dualen Pupillen, umgeben von Anhängern."
  },
  AvgDialog_49825_Content_6 = {
    Text = "Verdutzt? Diese kleinen Dinge scheinen keine Fähigkeit zu haben, Menschen sprachlos zu machen, oder?"
  },
  AvgDialog_49825_Content_7 = {
    Text = [[
In Ordnung, genug mit dem Smalltalk...
Erinnert ihr euch? Vor heute habt ihr mich schon zweimal abgelehnt.]]
  },
  AvgDialog_49825_Content_8 = {
    Text = "Schließe dich der Verbreitung des Blassen Lords an... Du hast mich schon zweimal abgelehnt!"
  },
  AvgDialog_49825_Content_9 = {
    Text = "Mein menschlicher Körper kann die Qualen von deinen kleinen Spinnen nicht ertragen..."
  },
  AvgDialog_49826_Content_1 = {
    Text = "Warst du es, Hüter?"
  },
  AvgDialog_49826_Content_10 = {
    Text = "Wenn das deine Hilfe ist... werde ich diese Kraft an dich übertragen."
  },
  AvgDialog_49826_Content_11 = {
    Text = "Wir können diese Kraft teilen. Schließ dich mir bei der fortgeschrittenen Evolution an."
  },
  AvgDialog_49826_Content_2 = {
    Text = "Was habe ich getan? Sei nicht so schnell damit, deine Waffe auf mich zu schwingen. Wir können das klären—"
  },
  AvgDialog_49826_Content_3 = {
    Text = "Sobald er die Station betrat, stürmte der Junge eifrig vorwärts."
  },
  AvgDialog_49826_Content_4 = {
    Text = "Meine Rückenflosse erhitzt sich... und meine Ohrfinnen auch."
  },
  AvgDialog_49826_Content_5 = {
    Text = "Er griff nach deiner Hand, wodurch du die zitternde Flosse des Seefahrers berührst."
  },
  AvgDialog_49826_Content_6 = {
    Text = "Die grau-rosanen Ohrflossen sind mit einer Schicht feuchthaltendem Schleim bedeckt, die sich kalt und nass anfühlen sollte, aber deine Finger spüren jetzt eine brennende Hitze."
  },
  AvgDialog_49826_Content_7 = {
    Text = "Habe ich Fieber? Ich werde Lady Sylvia holen, um nachzusehen, der Zustand des Erweckers muss auch zu Puppe gebracht werden"
  },
  AvgDialog_49826_Content_8 = {
    Text = "Caecus blockierte dich an der Tür mit seiner Waffe, sein Atem schwer und feucht wie nie zuvor."
  },
  AvgDialog_49826_Content_9 = {
    Text = "Nein... Das ist der Beweis, dass ich die volle Kraft von Aequor entwickle."
  },
  AvgDialog_49836_Content_1 = {
    Text = "Abschiedskuss"
  },
  AvgDialog_49836_Content_10 = {
    Text = "Aber unzählige Menschen haben ihr Leben für kranke Glauben geopfert"
  },
  AvgDialog_49836_Content_11 = {
    Text = "Das ist das Schicksal der Aram. Wir sind hier geboren, wir sind hier aufgewachsen"
  },
  AvgDialog_49836_Content_12 = {
    Text = "Also lässt du sie diese verfluchten Rituale durchführen und immer wieder in der Sturmwand untergehen?"
  },
  AvgDialog_49836_Content_13 = {
    Text = "Thais antwortete nicht auf deine Frage"
  },
  AvgDialog_49836_Content_14 = {
    Text = "Sie kam nur näher und nahm dich sanft in die Arme"
  },
  AvgDialog_49836_Content_15 = {
    Text = "Ich weiß, du bist müde und wütend"
  },
  AvgDialog_49836_Content_16 = {
    Text = "Du bist wütend auf mich, verstehst mich nicht.\nDoch auch ich habe meine Gründe"
  },
  AvgDialog_49836_Content_17 = {
    Text = "Ich erzähle dir eine Geschichte, eine sehr lange Geschichte"
  },
  AvgDialog_49836_Content_18 = {
    Text = "Vor vielen, vielen Jahren, vor mehreren tausend Jahren, als die Überschwemmungen passierten, gab es eine Zivilisation, die die Göttin namens Mutterbaum verehrte"
  },
  AvgDialog_49836_Content_19 = {
    Text = "Doch der Wille des Mutterbaums konnte das Imperium nicht festigen, also schmiedeten sie einen Plan"
  },
  AvgDialog_49836_Content_2 = {
    Text = "Die Nacht ist tief, William hat sich auch schon zur Ruhe gelegt"
  },
  AvgDialog_49836_Content_20 = {
    Text = "Sie wählten viele Mädchen aus, zwangen sie, den roten Saft des Mutterbaums zu trinken und darin zu baden, bis sie mit dem Baum verschmolzen"
  },
  AvgDialog_49836_Content_21 = {
    Text = "Seitdem repräsentiert das puppenhafte Mädchen den Willen des Baumes"
  },
  AvgDialog_49836_Content_22 = {
    Text = "Doch niemand hört auf sie oder gehorcht ihren Worten. Das Mädchen hat keine Stimme und keinen eigenen Willen; es wiederholt lediglich die Befehle, die der König von Ninive es zu rezitieren zwang."
  },
  AvgDialog_49836_Content_23 = {
    Text = "Ein gutherziger Minister rettete sie aus den Klauen und sagte ihr, sie könne sie selbst sein"
  },
  AvgDialog_49836_Content_24 = {
    Text = "Ist das Mädchen entkommen?"
  },
  AvgDialog_49836_Content_25 = {Text = "Entkommen"},
  AvgDialog_49836_Content_26 = {
    Text = "Aber die Geschichte endet hier nicht"
  },
  AvgDialog_49836_Content_27 = {
    Text = "Das geflohene Mädchen mischte sich unter die Menge, kauerte in einer Ecke und erhielt nur ein Stück Brot, als sie sich vor den anderen fürchtete"
  },
  AvgDialog_49836_Content_28 = {
    Text = "Sie gaben ihr Brot, nicht weil sie die Kaiserin war, nicht weil sie die Agentin des Mutterbaumes war... sondern einfach weil sie ein Kind war."
  },
  AvgDialog_49836_Content_29 = {
    Text = "In diesem Moment resonierten das Mädchen und der Baum in der Ferne"
  },
  AvgDialog_49836_Content_3 = {
    Text = "Du holst tief Luft und willst gerade ins Zelt zurück, als Thais dir hinter dem Zelt zuwinkt"
  },
  AvgDialog_49836_Content_30 = {
    Text = "Dann fragte der Wille des Baumes sie:"
  },
  AvgDialog_49836_Content_31 = {
    Text = "Bist du bereit, zum Träger des Baumes zu werden und sein Fleisch und seine Seele zu gebären?"
  },
  AvgDialog_49836_Content_32 = {
    Text = "Durch die wundersame Resonanz der Seele kann das Mädchen die Stimmen der Bäume hören.\nAn diesem Abend erfuhr sie das Wissen über <Red:Der schwarze Untergang>"
  },
  AvgDialog_49836_Content_33 = {
    Text = "Schwarzer Untergang... bedeutet das Erosion?"
  },
  AvgDialog_49836_Content_34 = {
    Text = "Das Mädchen kehrt zum Baum zurück, gehorcht aber nicht mehr dem König.\nNein... das Volk folgt nur dem Willen des Baumes"
  },
  AvgDialog_49836_Content_35 = {
    Text = "Das Mädchen ist der Baum, der Baum ist das Mädchen. Sie sorgt sich mehr um das Überleben ihrer Art als um ihr eigenes"
  },
  AvgDialog_49836_Content_36 = {
    Text = "Als das Imperium fiel, führte sie eine Gruppe tief in die Wüste, in die unbewohnten Stürme, um dem Massaker zu entkommen und die letzte Blutlinie zu bewahren"
  },
  AvgDialog_49836_Content_37 = {
    Text = "Ist das... der nomadische Stamm, Yalan?"
  },
  AvgDialog_49836_Content_38 = {
    Text = "Vor langer, langer Zeit verschwand das Mädchen wieder"
  },
  AvgDialog_49836_Content_39 = {
    Text = "Oder niemand hörte ihre Stimme, niemand sprach mehr ihren Namen"
  },
  AvgDialog_49836_Content_4 = {
    Text = "Königin... was wollt Ihr von mir?"
  },
  AvgDialog_49836_Content_40 = {
    Text = "Aber alle folgen ihrem Willen und vermehren sich verzweifelt, um dem Untergang zu entkommen"
  },
  AvgDialog_49836_Content_41 = {
    Text = "Nur um die Saat des „Füllhorns\" für den Zeitpunkt der Apokalypse zu bewahren"
  },
  AvgDialog_49836_Content_42 = {
    Text = "Aber Yalans Blutlinie verlässt sich zu sehr auf die Kraft des Mutterbaums."
  },
  AvgDialog_49836_Content_43 = {
    Text = "Diese Abhängigkeit ist wie ein zerbrechlicher Sandturm, scheinbar stabil, aber eine Flutwelle würde ihn vollständig zerstören"
  },
  AvgDialog_49836_Content_44 = {
    Text = "Vielleicht verstehst du jetzt nicht, dass die Aram keine andere Wahl hatten"
  },
  AvgDialog_49836_Content_45 = {
    Text = "Aber du wirst mit ihnen zusammen das Ende dieser Reise erreichen"
  },
  AvgDialog_49836_Content_46 = {
    Text = "Du bist sprachlos"
  },
  AvgDialog_49836_Content_47 = {
    Text = "Dann... erinnere dich bitte daran, meinen Namen zu rufen"
  },
  AvgDialog_49836_Content_48 = {
    Text = [[
Sie gab dir einen sanften Kuss auf die Stirn.
Du warst kurz benommen, sie machte ein paar Schritte, du strecktest die Hand aus, konntest sie aber nicht erreichen]]
  },
  AvgDialog_49836_Content_49 = {
    Text = "Du siehst ihr nach, wie sie immer kleiner wird und schließlich im Mondlicht verschwindet"
  },
  AvgDialog_49836_Content_5 = {
    Text = [[
Morgen ist das Wiederbelebungsritual des Mutterbaums, also wollte ich dich sehen.
Mein kleines Monster, bist du bereit?]]
  },
  AvgDialog_49836_Content_6 = {
    Text = "Frag nicht, ob ich bereit bin... die Königin sollte sich vorbereiten"
  },
  AvgDialog_49836_Content_7 = {
    Text = "Oder, bist du gut vorbereitet?"
  },
  AvgDialog_49836_Content_8 = {
    Text = "Ramona's kränkliches Gesicht erschien vor deinem inneren Auge, und die Wut in deiner Brust stieg auf"
  },
  AvgDialog_49836_Content_9 = {
    Text = "Ich meine es nicht böse, und ich werde nicht gegen die Interessen der Alander handeln."
  },
  AvgDialog_49837_Content_1 = {
    Text = "Zusammenführung"
  },
  AvgDialog_49837_Content_11 = {
    Text = "Die Narbe an seiner Schläfe, angeblich von seiner wahnsinnigen Mutter verursacht, sah jetzt wie ein flacher Graben aus, aus dem scharlachroter Saft sickerte"
  },
  AvgDialog_49837_Content_12 = {
    Text = "Der Silberschlüssel zerbricht auf deiner Brust, die standardmäßigen Handschuhe der Missaga sind mit Blut befleckt, und unheilvolle Flüssigkeit tropft entgegen der Schwerkraft"
  },
  AvgDialog_49837_Content_13 = {
    Text = "Hinter dem schwankenden Albtraum—"
  },
  AvgDialog_49837_Content_14 = {
    Text = "Ein riesiger Fleischberg öffnete wie eine Venusfliegenfalle den klaffenden Rachen"
  },
  AvgDialog_49837_Content_15 = {
    Text = "Die Plazenta und die Falten des missgebildeten Babys sind so klar wie das blutige Brandmal in deinem Kopf"
  },
  AvgDialog_49837_Content_16 = {
    Text = "In der Mitte des deformierten Fleischklumpens liegt das letzte Geschenk, das er euch durch ständige Rückverfolgung und Erforschung überreicht"
  },
  AvgDialog_49837_Content_17 = {
    Text = "Das ist die Wahrheit des Nubia-Kerns—"
  },
  AvgDialog_49837_Content_18 = {
    Text = "Eine kleine Laterne"
  },
  AvgDialog_49837_Content_2 = {
    Text = "Ein plötzlicher Anstieg des Unbehagens, Angst schlägt wie ein Hammer auf dein Herz"
  },
  AvgDialog_49837_Content_3 = {
    Text = "Ihr rennt zum Lager unter den Dünen"
  },
  AvgDialog_49837_Content_4 = {
    Text = "Im Moment der Berührung des Vorhangs ergriff dich eine große Angst"
  },
  AvgDialog_49837_Content_6 = {
    Text = "Diese Angst ist anders als die Konfrontation mit Jagdhunden oder dem Heiligen Embryo"
  },
  AvgDialog_49837_Content_7 = {
    Text = "Das war ein tiefsitzender, unaussprechlicher Schrecken, dem man nicht entkommen konnte"
  },
  AvgDialog_49837_Content_8 = {
    Text = "Das ist der schwebende Albtraum, die abnorme Fantasie, die unerträgliche, erstickende Realität"
  },
  AvgDialog_49837_Content_9 = {
    Text = "Ein riesiges, wildes Monster schwingt seine schleimigen Tentakel, und Williams dünner Körper schwankt wie ein einsamer Schilfrohr"
  },
  AvgDialog_49838_Content_1 = {
    Text = "Zusammenführung"
  },
  AvgDialog_49838_Content_10 = {
    Text = "Du holst tief Luft und willst gerade ins Zelt zurück, als Thais dir hinter dem Zelt zuwinkt"
  },
  AvgDialog_49838_Content_100 = {
    Text = "Aber du wirst mit ihnen zusammen das Ende dieser Reise erreichen"
  },
  AvgDialog_49838_Content_101 = {
    Text = "Du bist sprachlos"
  },
  AvgDialog_49838_Content_102 = {
    Text = "Dann... erinnere dich bitte daran, meinen Namen zu rufen"
  },
  AvgDialog_49838_Content_103 = {
    Text = "Sie gab dir einen sanften Kuss auf die Stirn"
  },
  AvgDialog_49838_Content_104 = {
    Text = "Du warst kurz abgelenkt, sie machte ein paar Schritte, du strecktest die Hand aus, aber konntest sie nicht erreichen"
  },
  AvgDialog_49838_Content_105 = {
    Text = "Du siehst ihr nach, wie sie immer kleiner wird und schließlich im Mondlicht verschwindet"
  },
  AvgDialog_49838_Content_11 = {
    Text = "Morgen ist das Wiederbelebungsritual des Mutterbaums.\nDie Königin ruft mich jetzt... Was will sie?"
  },
  AvgDialog_49838_Content_12 = {
    Text = "Als du sprachst, wurde dir klar, dass dein Ton unfreundlich war"
  },
  AvgDialog_49838_Content_13 = {
    Text = [[
Ich... habe es gesehen.
Es tut mir leid wegen deinem Freund]]
  },
  AvgDialog_49838_Content_14 = {
    Text = "Eine unvermeidliche Stille liegt zwischen euch."
  },
  AvgDialog_49838_Content_15 = {
    Text = "Das hat nichts mit Alan zu tun."
  },
  AvgDialog_49838_Content_16 = {
    Text = "Das ist nicht Thais' Fehler, sagst du dir innerlich, aber die Worte, die herausplatzen, sind wie ein vorsichtiger Igel in den Dünen"
  },
  AvgDialog_49838_Content_17 = {
    Text = "Ritual zur Wiederbelebung des Mutterbaums... Du hast auch Vorbereitungen zu treffen, oder?"
  },
  AvgDialog_49838_Content_18 = {
    Text = "Du versuchst, es zu retten, aber deine Worte klingen immer noch kalt und abweisend"
  },
  AvgDialog_49838_Content_19 = {
    Text = "Wo denkst du, wird der Aran-Stamm nach der Wiedergeburt des Mutterbaums hingehen?"
  },
  AvgDialog_49838_Content_2 = {
    Text = "Auf dieser Reise hast du viele Abschiede erlebt.\nAber kein Tod war so erstickend beiläufig"
  },
  AvgDialog_49838_Content_20 = {
    Text = "Du schweigst"
  },
  AvgDialog_49838_Content_21 = {
    Text = "Ich weiß, warum Mythag nach Remouahe kam, und ich weiß, warum du noch nicht gehandelt hast."
  },
  AvgDialog_49838_Content_22 = {
    Text = "Ich bin dir sehr dankbar, dass du Aran eine Chance gegeben hast."
  },
  AvgDialog_49838_Content_23 = {
    Text = "Aber diese Chance gibt es nicht mehr"
  },
  AvgDialog_49838_Content_24 = {
    Text = "Thais, weißt du, dass der Mutterbaum geschmolzen und kontaminiert wurde?"
  },
  AvgDialog_49838_Content_25 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_49838_Content_26 = {
    Text = "Ich weiß, ich... wusste es die ganze Zeit."
  },
  AvgDialog_49838_Content_27 = {
    Text = "Dann solltest du wissen, dass Missaga die Ausbreitung der Korrosion nicht zulassen wird"
  },
  AvgDialog_49838_Content_28 = {
    Text = [[
Ich werde die Geburt des Mutterbaums aufhalten.
Thais, wir sind jetzt Feinde]]
  },
  AvgDialog_49838_Content_29 = {
    Text = "Der einst frische Wüstenwind wurde plötzlich dick und klebrig, und der Staub kratzte in deinem Hals, was leichte Schmerzen verursachte"
  },
  AvgDialog_49838_Content_3 = {
    Text = "Zumal das William ist—\nDie Legende von Missaga, dein Wegweiser auf dem Weg des Ermittlers"
  },
  AvgDialog_49838_Content_30 = {
    Text = "Zu deiner Überraschung weicht Thais nicht zurück, sondern kommt näher und umarmt dich"
  },
  AvgDialog_49838_Content_31 = {
    Text = "Braves Kind, ich verstehe deine Gedanken"
  },
  AvgDialog_49838_Content_32 = {
    Text = "Ich meine es nicht böse, und ich werde nicht gegen die Interessen der Alander handeln."
  },
  AvgDialog_49838_Content_33 = {
    Text = "Aber den Aramern blieben keine Optionen. Vor vielen Jahren war die göttliche Kraft der Königin bereits erschöpft, und sie konnten nicht einmal mehr den Mutterbaum beschützen"
  },
  AvgDialog_49838_Content_34 = {
    Text = "Nur indem wir die Leylinienkraft von Lemwash nutzen, können wir den Standort des Mutterbaums mit einer Sturmwand verbergen."
  },
  AvgDialog_49838_Content_35 = {
    Text = "Du meinst... die Sturmwand wurde durch die Macht der Königin beschworen?"
  },
  AvgDialog_49838_Content_36 = {
    Text = "Ja. Die Sturmwand... wird falsche Boten abweisen"
  },
  AvgDialog_49838_Content_37 = {
    Text = "Aber jedes Mal, wenn ein Ritual abgehalten wird, sterben viele Aram!"
  },
  AvgDialog_49838_Content_38 = {
    Text = "Solange die Fortpflanzungskraft besteht, wird das Yaran-Volk nicht aussterben."
  },
  AvgDialog_49838_Content_39 = {
    Text = "Also lässt du sie diese verfluchten Rituale durchführen und immer wieder in der Sturmwand untergehen?"
  },
  AvgDialog_49838_Content_4 = {
    Text = "Wer könnte einen legendären Ermittler aus nächster Nähe lautlos töten?"
  },
  AvgDialog_49838_Content_40 = {
    Text = "Das ist das Schicksal der Aram. Wir sind hier geboren, wir sind hier aufgewachsen"
  },
  AvgDialog_49838_Content_41 = {
    Text = "Unzählige haben für deinen kranken Glauben ihr Leben gelassen!"
  },
  AvgDialog_49838_Content_42 = {
    Text = "Jetzt, nicht nur dein Volk, sondern auch Senior William"
  },
  AvgDialog_49838_Content_43 = {
    Text = "Dein letzter Ton ist mit einem leichten Schluchzen durchzogen; du erkennst deine eigene Stimme kaum"
  },
  AvgDialog_49838_Content_44 = {
    Text = "Sag mir, Thais, du meinst das nicht ernst, oder?"
  },
  AvgDialog_49838_Content_45 = {
    Text = "Thais antwortete nicht auf deine Frage"
  },
  AvgDialog_49838_Content_46 = {
    Text = "Sie zog nur ihre Arme enger um sich"
  },
  AvgDialog_49838_Content_47 = {
    Text = "Ich weiß, du bist müde und wütend"
  },
  AvgDialog_49838_Content_48 = {
    Text = "Du bist wütend auf mich, verstehst mich nicht.\nDoch auch ich habe meine Gründe"
  },
  AvgDialog_49838_Content_49 = {
    Text = "Ich erzähle dir eine Geschichte, eine sehr lange Geschichte"
  },
  AvgDialog_49838_Content_5 = {
    Text = "Du taumelst kraftlos zurück und stößt gegen eine große Gestalt"
  },
  AvgDialog_49838_Content_50 = {
    Text = "Vor vielen, vielen Jahren, vor mehreren tausend Jahren, als die Überschwemmungen passierten, gab es eine Zivilisation, die die Göttin namens Mutterbaum verehrte"
  },
  AvgDialog_49838_Content_51 = {
    Text = "Doch der Wille des Mutterbaums konnte das Imperium nicht festigen, also schmiedeten sie einen Plan"
  },
  AvgDialog_49838_Content_52 = {
    Text = "Sie wählten viele Mädchen aus, zwangen sie, den roten Saft des Mutterbaums zu trinken und darin zu baden, bis sie mit dem Baum verschmolzen"
  },
  AvgDialog_49838_Content_53 = {
    Text = "Seitdem repräsentiert das puppenhafte Mädchen den Willen des Baumes"
  },
  AvgDialog_49838_Content_54 = {
    Text = "Doch niemand hört auf sie oder gehorcht ihren Worten. Das Mädchen hat keine Stimme und keinen eigenen Willen; es wiederholt lediglich die Befehle, die der König von Ninive es zu rezitieren zwang."
  },
  AvgDialog_49838_Content_55 = {
    Text = "Das Jahr, in dem sie sich wehrte, war das Mädchen fünfzehn"
  },
  AvgDialog_49838_Content_56 = {
    Text = "Warum? Warum ihn töten? Er ist doch der Vater von Ameyet!"
  },
  AvgDialog_49838_Content_57 = {
    Text = "Er hat das Tabu gebrochen, Thais. Er ist auf dem Schlachtfeld geflohen"
  },
  AvgDialog_49838_Content_58 = {
    Text = "Die Schlacht war völlig verloren, nur er überlebte. Er konnte unmöglich allein so viele Feinde bekämpfen!"
  },
  AvgDialog_49838_Content_59 = {
    Text = "Du bist noch zu jung, um die Dinge des Krieges zu verstehen, Thais"
  },
  AvgDialog_49838_Content_6 = {
    Text = "Ich verstehe deine Sorgen, aber jetzt ist nicht der Zeitpunkt, Schwäche zu zeigen"
  },
  AvgDialog_49838_Content_60 = {
    Text = "Er sollte mutig vorwärts stürmen und dann ehrenvoll sterben"
  },
  AvgDialog_49838_Content_61 = {
    Text = "Ist es nicht gut, wenn nur eine Person überlebt? Wenn nur eine Person überlebt... kann Ameiyt ein Krieger sein, Ameiyts Bruder wird ein Krieger sein, und sogar Ameiyts zukünftige Kinder"
  },
  AvgDialog_49838_Content_62 = {
    Text = "Es bringt nichts mehr, weiter zu reden"
  },
  AvgDialog_49838_Content_63 = {
    Text = "Der Wille des Mutterbaums, Sünder sollen von Insekten zerfressen werden"
  },
  AvgDialog_49838_Content_64 = {
    Text = "Ich habe es nicht gesagt!"
  },
  AvgDialog_49838_Content_65 = {
    Text = "Der Wille des Mutterbaums, Sünder sollen von Insekten zerfressen werden"
  },
  AvgDialog_49838_Content_66 = {
    Text = "Ich habe es nicht gesagt!"
  },
  AvgDialog_49838_Content_67 = {
    Text = "Der Wille des Mutterbaums, Sünder sollen von Insekten zerfressen werden"
  },
  AvgDialog_49838_Content_68 = {
    Text = "Das verzweifelte und laute Weinen des Mädchens hörte niemand"
  },
  AvgDialog_49838_Content_69 = {
    Text = "Du, wer bist du?"
  },
  AvgDialog_49838_Content_7 = {
    Text = "Er... hat uns die entscheidenden Informationen hinterlassen"
  },
  AvgDialog_49838_Content_70 = {
    Text = "Braves Kind, sei leise, hör auf mich und komm schnell mit mir"
  },
  AvgDialog_49838_Content_71 = {
    Text = "Du bist nicht das erste Mädchen, das als Puppe des Baumes benutzt wird. Jedes Mal, wenn ein Mädchen sich gegen ihren Willen wehrt, opfern sie das Mädchen dem heiligen Fluss"
  },
  AvgDialog_49838_Content_72 = {
    Text = "Ich wurde von der Milch des Mutterbaums genährt, ich bin unsterblich!"
  },
  AvgDialog_49838_Content_73 = {
    Text = "Dummes Kind, sie haben dich belogen. Jeder, der in den Fluss springt, wird ertrinken"
  },
  AvgDialog_49838_Content_74 = {
    Text = "Ich werde nicht."
  },
  AvgDialog_49838_Content_75 = {
    Text = "Wer bist du überhaupt? Ich habe dich noch nie zuvor gesehen."
  },
  AvgDialog_49838_Content_76 = {
    Text = "Ich kümmere mich um deinen Garten und gehe vor Sonnenaufgang, deshalb hast du mich nie gesehen"
  },
  AvgDialog_49838_Content_77 = {
    Text = "Aber du kennst meinen Enkel... Sein Name ist Ameyet"
  },
  AvgDialog_49838_Content_78 = {
    Text = "Ist das Mädchen entkommen?"
  },
  AvgDialog_49838_Content_79 = {Text = "Nein."},
  AvgDialog_49838_Content_8 = {
    Text = "Hinter Nubien liegt die Lichtkirche des Tempels.\nDie Narzisse hatte recht; das Ritual zu stoppen scheint unerlässlich."
  },
  AvgDialog_49838_Content_80 = {
    Text = "In diesem Moment verstand das Mädchen vieles, dass ein schmutziger Garten sich nicht von selbst reinigt und dass es schmerzhaft ist, keinen Laut von sich zu geben"
  },
  AvgDialog_49838_Content_81 = {
    Text = "Sie sprang freiwillig in den heiligen Fluss"
  },
  AvgDialog_49838_Content_82 = {
    Text = "In diesem Moment resonierten das Mädchen und der Baum in der Ferne"
  },
  AvgDialog_49838_Content_83 = {
    Text = "Dann fragte der Wille des Baumes sie:"
  },
  AvgDialog_49838_Content_84 = {
    Text = "Bist du bereit, zum Träger des Baumes zu werden und sein Fleisch und seine Seele zu gebären?"
  },
  AvgDialog_49838_Content_85 = {
    Text = "Durch die wundersame Resonanz der Seele kann das Mädchen die Stimmen der Bäume hören.\nAn diesem Abend erfuhr sie das Wissen über <Red:Der schwarze Untergang>"
  },
  AvgDialog_49838_Content_86 = {
    Text = "Schwarzer Untergang... bedeutet das Erosion?"
  },
  AvgDialog_49838_Content_87 = {
    Text = "Das Mädchen kehrt zum Baum zurück, gehorcht aber nicht mehr dem König.\nNein... das Volk folgt nur dem Willen des Baumes"
  },
  AvgDialog_49838_Content_88 = {
    Text = "Das Mädchen ist der Baum, der Baum ist das Mädchen. Sie sorgt sich mehr um das Überleben ihrer Art als um ihr eigenes"
  },
  AvgDialog_49838_Content_89 = {
    Text = "Als das Imperium fiel, führte sie eine Gruppe tief in die Wüste, in die unbewohnten Stürme, um dem Massaker zu entkommen und die letzte Blutlinie zu bewahren"
  },
  AvgDialog_49838_Content_9 = {
    Text = "Am weiten Himmel funkelten die Sterne, und der Wüstenwind der Nacht ließ deinen Atem allmählich wieder normal werden"
  },
  AvgDialog_49838_Content_90 = {
    Text = "Ist das... der nomadische Stamm, Yalan?"
  },
  AvgDialog_49838_Content_91 = {
    Text = "Vor langer, langer Zeit verschwand das Mädchen wieder"
  },
  AvgDialog_49838_Content_92 = {
    Text = "Oder niemand hörte ihre Stimme, niemand sprach mehr ihren Namen"
  },
  AvgDialog_49838_Content_93 = {
    Text = "Aber alle folgen ihrem Willen und vermehren sich verzweifelt, um dem Untergang zu entkommen"
  },
  AvgDialog_49838_Content_94 = {
    Text = "Nur um die Saat des „Füllhorns\" für den Zeitpunkt der Apokalypse zu bewahren"
  },
  AvgDialog_49838_Content_95 = {
    Text = "Aber Yalans Blutlinie verlässt sich zu sehr auf die Kraft des Mutterbaums."
  },
  AvgDialog_49838_Content_96 = {
    Text = "Diese Abhängigkeit ist wie ein zerbrechlicher Sandturm, scheinbar stabil, aber eine Flutwelle würde ihn vollständig zerstören"
  },
  AvgDialog_49838_Content_97 = {
    Text = "Selbst die kleinste, schwächste Hoffnung darf ich ihnen nicht leichtfertig nehmen"
  },
  AvgDialog_49838_Content_98 = {
    Text = "Ich verstehe nicht mehr"
  },
  AvgDialog_49838_Content_99 = {
    Text = "Um den Abschied weniger traurig zu machen, das Wiedersehen wertvoller... du musst es nicht verstehen"
  },
  AvgDialog_49865_Content_1 = {
    Text = "Der Mutterbaum ist hochragend und erreicht den Himmel."
  },
  AvgDialog_49865_Content_2 = {
    Text = "Der geschwollene Baumtumor bringt unzählige Nachkommen zur Welt, während zahllose Nubien durch den Leib des Baumes dringen, um hervorzutreten."
  },
  AvgDialog_49865_Content_3 = {
    Text = "Der Mutterbaum... erschafft Nubien."
  },
  AvgDialog_49865_Content_4 = {
    Text = "Arans Caro, der Kern der Laterne, meine Kinder, Kinder, die vom Unglück befleckt sind..."
  },
  AvgDialog_49865_Content_5 = {
    Text = "Sie streichelte sanft ein schwaches Nubien, zart wie eine Mutter, die ihr schlafendes Kind beruhigt."
  },
  AvgDialog_49865_Content_6 = {
    Text = "Dann explodierte Nubias Kopf in ihrer Hand, und Blut spritzte auf ihre Wangen und verlieh ihr ein grimmiges Aussehen."
  },
  AvgDialog_49865_Content_7 = {
    Text = "Rückkehr zum Mutterleib, Rückkehr zum Heiligen Fluss. Deine unvollendete Zukunft... wird durch die Blutlinie bis zum Ende der Welt getragen."
  },
  AvgDialog_49865_Content_8 = {
    Text = "Ich verspreche es dir."
  },
  AvgDialog_49869_Content_1 = {
    Text = "Huch... huch..."
  },
  AvgDialog_49869_Content_10 = {Text = "...?"},
  AvgDialog_49869_Content_11 = {
    Text = "Miryam! Sie muss hinter meinem Rücken Intrigen gesponnen haben, sodass ich... nicht in der Lage bin zu..."
  },
  AvgDialog_49869_Content_12 = {
    Text = "...Was konnte ich nicht tun?"
  },
  AvgDialog_49869_Content_13 = {
    Text = "Unkontrollierbar möchte ich dir näherkommen, und auch..."
  },
  AvgDialog_49869_Content_14 = {
    Text = "RRRRIIISS—!"
  },
  AvgDialog_49869_Content_15 = {
    Text = "Im nächsten Sekunden wurden deine Schlafanzüge in zwei Hälften gerissen."
  },
  AvgDialog_49869_Content_16 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_49869_Content_17 = {
    Text = "<Shake:Verdammtes, es kann nicht das sein, was ich denke...>"
  },
  AvgDialog_49869_Content_18 = {
    Text = "Das stimmt! Zerreiß deine Kleider, und dann..."
  },
  AvgDialog_49869_Content_19 = {
    Text = "Goliath packt dein Handgelenk fest, sein gerötetes Gesicht fast an deinem."
  },
  AvgDialog_49869_Content_2 = {
    Text = "Eine weitere ruhige Nacht. Du versinkst in das weiche Federkissen, atmest ruhig und friedlich."
  },
  AvgDialog_49869_Content_20 = {
    Text = "Heißer Atem streift dein Ohr und färbt dein Gesicht rosig."
  },
  AvgDialog_49869_Content_21 = {
    Text = "Keine Zeit mehr. Die oberste Priorität ist jetzt, mich @2 zu treffen. Morgen werden wir uns gemeinsam mit dieser Frau befassen."
  },
  AvgDialog_49869_Content_22 = {
    Text = "Heute Abend musst du es eine Weile ertragen... Nein, warte, das ist keine Ausdauer; es ist deine Ehre!"
  },
  AvgDialog_49869_Content_23 = {
    Text = "@2? Herr Goliath, bitte zeig etwas Selbstachtung... Halte Abstand von mir!"
  },
  AvgDialog_49869_Content_24 = {
    Text = "<Big:Ramona! Puppe! Hilf mir—!!>"
  },
  AvgDialog_49869_Content_4 = {Text = "Wow!!!"},
  AvgDialog_49869_Content_5 = {
    Text = "Ein schweres Breitschwert spaltet dein kleines Bett in zwei, und du wirst wach, als du auf den Boden landest."
  },
  AvgDialog_49869_Content_6 = {
    Text = "Was ist los?! Greift die Bildhauer wieder an?"
  },
  AvgDialog_49869_Content_7 = {
    Text = "Aus der Dunkelheit kommt ein zitternder Atem. Eine überragende Gestalt steht neben dem zerbrochenen Bettgestell."
  },
  AvgDialog_49869_Content_8 = {
    Text = "So mächtig, so unbekannt... Diese aufsteigende Kraft..."
  },
  AvgDialog_49869_Content_9 = {
    Text = "Hüter, ich könnte von dieser verrückten Frau vergiftet worden sein."
  },
  AvgDialog_49870_Content_1 = {
    Text = "Der wütende Sturm draußen kann den ruhigen Traum nicht stören; in der Dunkelheit hallt nur das Geräusch deines ruhigen Atems wider."
  },
  AvgDialog_49870_Content_10 = {
    Text = "Super... Super! Ganz genau so!"
  },
  AvgDialog_49870_Content_11 = {
    Text = "Ein Werkzeug mit genau dem richtigen Gleichgewicht zwischen Weichheit und Festigkeit, das meine Haut nicht zerreißt. Die aufgebrachte Kraft ist perfekt, hinterlässt keine unschönen Spuren... Wunderschön, deine Technik ist wirklich bemerkenswert."
  },
  AvgDialog_49870_Content_12 = {
    Text = "Leighs Lob für dich verwandelt sich fast in einen Gesang, ohne auf einen Blutstrom zu achten, der an ihrem Haaransatz herunterläuft."
  },
  AvgDialog_49870_Content_13 = {
    Text = "...Lass mich dich zuerst behandeln, bis deine Wunde gut ist."
  },
  AvgDialog_49870_Content_14 = {
    Text = "Miss Leighs Wunde ist nicht schwerwiegend. Wären wir nur etwas später angekommen, hätte sie sich bereits geheilt."
  },
  AvgDialog_49870_Content_15 = {
    Text = "Aber ich will wirklich..."
  },
  AvgDialog_49870_Content_16 = {
    Text = "...lass sie eine angemessene Menge Blut aufnehmen."
  },
  AvgDialog_49870_Content_17 = {
    Text = "Wirklich? Kann ich wirklich? Du bist wirklich eine gutherzige Person—"
  },
  AvgDialog_49870_Content_18 = {
    Text = "Verabreichen Sie die Transfusionsinjektion; verwöhnen Sie sie nicht."
  },
  AvgDialog_49870_Content_19 = {
    Text = "Obwohl sie ihr Lieblingsblut erhielt, wirkt Leigh dennoch lustlos, wie eine verwelkte Dahlie, ans Bett durch IVs und Blutbeutel gebunden."
  },
  AvgDialog_49870_Content_2 = {
    Text = "In dem Moment, bevor der Donner grollte, durchbohrte ein greller weißer Blitz die Nacht und erhellte den Schatten am Fenster."
  },
  AvgDialog_49870_Content_20 = {
    Text = "Nicht in der Lage, ihre Augen voller Traurigkeit zu ertragen, kannst du schließlich nicht anders, als zu fragen."
  },
  AvgDialog_49870_Content_21 = {
    Text = "Warum bist du heute Nacht in mein Zimmer eingedrungen?"
  },
  AvgDialog_49870_Content_22 = {
    Text = "...Ich... will..."
  },
  AvgDialog_49870_Content_23 = {
    Text = "Leigh springt plötzlich auf, die Nadel schnellt heraus, und Blut aus dem Beutel sowie ihr eigenes spritzt überall über sie."
  },
  AvgDialog_49870_Content_24 = {
    Text = "Sie vergrub ihren Kopf in deinem Nacken, ihr kalter Atem ließ dir einen Schauer über den Rücken laufen."
  },
  AvgDialog_49870_Content_25 = {
    Text = "Ich will das Blut des Hüters... und Ihres."
  },
  AvgDialog_49870_Content_3 = {
    Text = "Es erscheint plötzlich und bewegt sich langsam im Dunkeln deines Schlafzimmers. Gerade als es einen kalten, blutigen Geruch in die Nähe deines Bettes bringt und dein Kopfkissen kühlt—"
  },
  AvgDialog_49870_Content_4 = {Text = "—Bang!"},
  AvgDialog_49870_Content_5 = {
    Text = "Du hast die Schreibtischlampe ergriffen und sie mit voller Wucht gegen den Kopf des Eindringlings geschlagen."
  },
  AvgDialog_49870_Content_6 = {
    Text = "Hmm... Mm..."
  },
  AvgDialog_49870_Content_7 = {Text = "Leigh?!"},
  AvgDialog_49870_Content_8 = {
    Text = "Was machst du in meinem Zimmer?"
  },
  AvgDialog_49870_Content_9 = {Text = "Ich..."},
  AvgDialog_49871_Content_1 = {
    Text = "Keeper, du musst die jüngsten Störungen auf dem Campus bemerkt haben."
  },
  AvgDialog_49871_Content_2 = {
    Text = "Beschäftigt mit dem Lem Wah Ereignisbericht, habe ich andere Dinge nicht bemerkt..."
  },
  AvgDialog_49871_Content_3 = {
    Text = "Aber jetzt, da der amtierende Dekan es erwähnt hat, sind in letzter Zeit ziemlich viele Erwachte in die Krankenstation gedrängt... Ist etwas passiert?"
  },
  AvgDialog_49871_Content_4 = {
    Text = "Beeinflusst durch das <Yellow:Le Mwashar Ereignis> wiesen nahezu alle Erwachten eine Form von emotionaler Anomalie auf."
  },
  AvgDialog_49871_Content_5 = {
    Text = "Es scheint, dass es mehr gibt, was in den Bericht aufgenommen werden sollte... Gibt es etwas, das ich tun kann?"
  },
  AvgDialog_49871_Content_6 = {
    Text = "Die meisten Erwacher wurden abnormal beeinflusst, selbst die Puppen. Die Forscher suchen nach Wegen, um alle zu beruhigen."
  },
  AvgDialog_49871_Content_7 = {
    Text = "Bis der Aufprall vollständig nachlässt, senke nicht deine Wachsamkeit gegenüber den Erweckern. Sie könnten zu einer <Red:Quelle der Gefahr> werden."
  },
  AvgDialog_49880_Content_1 = {
    Text = "Die Rüstung bewegte sich zwischen Wange und Hals, ihre spitze Kante öffnete schließlich den Riemen der Schuluniform und drückte mit einer Fingerspitze gegen das freiliegende Schlüsselbein."
  },
  AvgDialog_49880_Content_10 = {
    Text = "Wanda riss grob deine Augenbinde ab. Sie blinzelte, eine ungewohnte Aura von Druck, die sich von bloßer Brutalität unterschied, ging von ihr aus."
  },
  AvgDialog_49880_Content_11 = {
    Text = "Wirbelkanülen streiften das Schlüsselbein, raue Spieße rissen die Haut. Wanda schloss ihre Augen, genießt den Duft von frischem Blut in der Luft, zufrieden mit dem Ausdruck."
  },
  AvgDialog_49880_Content_12 = {
    Text = "Kurz nachdem ich die vierte Konkubine meines Königs getötet hatte, traf mein Königreich auf diesem Planeten sein Ende."
  },
  AvgDialog_49880_Content_13 = {
    Text = "Komm und denk mal nach, es ist schon so lange her, seit ich zuletzt einen Neuling getroffen habe."
  },
  AvgDialog_49880_Content_14 = {
    Text = "Die Wirbelsäulennadel wurde hoch erhoben, mit klebrigem Liquid, das an ihrer Spitze kondensierte, nahe eurer freiliegenden Wunde."
  },
  AvgDialog_49880_Content_15 = {
    Text = "Jetzt ist ein guter Zeitpunkt, oder?"
  },
  AvgDialog_49880_Content_16 = {
    Text = "Fernab von Tumult und Seuche, frei von Sorgen und Pflichten... nur vertrauenswürdige Menschen um einen herum. Das ist wirklich die beste Zeit!"
  },
  AvgDialog_49880_Content_17 = {
    Text = "Wanda, denkst du wirklich so?"
  },
  AvgDialog_49880_Content_18 = {
    Text = "Was meinst du?"
  },
  AvgDialog_49880_Content_19 = {
    Text = "Keine Sorgen, keine Verantwortlichkeiten..."
  },
  AvgDialog_49880_Content_2 = {
    Text = "Du bist... ein Erwacher, richtig?"
  },
  AvgDialog_49880_Content_20 = {
    Text = "Indem du dich entscheidest, dem Ende mit Cambrian entgegenzutreten, hast du Verantwortung niemals als Last angesehen."
  },
  AvgDialog_49880_Content_21 = {
    Text = "Wie weißt du von Cambrian's —"
  },
  AvgDialog_49880_Content_22 = {
    Text = "Königin des fremden Sterns, bevor du mich zur neuen Königsbraut machst, prüfe bitte gründlich dein eigenes Herz."
  },
  AvgDialog_49880_Content_23 = {
    Text = "Der Einfluss des Heiligen Flusses Lemwashi wird dein Aussehen nicht verändern."
  },
  AvgDialog_49880_Content_24 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_49880_Content_25 = {
    Text = "Du hast recht, kleines Haustier."
  },
  AvgDialog_49880_Content_26 = {
    Text = "Die bezaubernde Atmosphäre verschwand, Rückenstäbe zogen sich wie der zurückweichende Gezeiten zurück und schwankten hinter Wanda."
  },
  AvgDialog_49880_Content_27 = {
    Text = "Lass uns gehen. Heute Nacht ist noch nicht die Zeit."
  },
  AvgDialog_49880_Content_28 = {
    Text = "Ist dies nicht der richtige Zeitpunkt?"
  },
  AvgDialog_49880_Content_29 = {
    Text = "Die untoten Diener schwärmten und schoben dich weg, während Wanda ein zufriedenes Schnaufen von sich gab."
  },
  AvgDialog_49880_Content_3 = {
    Text = "Blinded by black silk, the senses are heightened to the extreme by darkness. The sound of armor sliding against the skin blends with breathing, sending a shiver from deep within the soul."
  },
  AvgDialog_49880_Content_30 = {
    Text = "Die Königin wird ihren Verstand nicht verlieren oder ihre Worte zurückziehen, aber es ist tatsächlich noch zu früh, um dich zu meinem Nachfolger zu machen."
  },
  AvgDialog_49880_Content_31 = {
    Text = "Lass uns gehen, kleines Haustier. Aber sei vorbereitet — ich rufe dich zurück, wenn die Zeit reif ist."
  },
  AvgDialog_49880_Content_4 = {
    Text = "Hey? Kannst du verstehen, was ich sage?"
  },
  AvgDialog_49880_Content_5 = {
    Text = "Ein leichtes Lachen kommt von oben. Gerade als du dich fragst, wer es ist, umschlingt eine Stachelnadel deinen Taillengürtel."
  },
  AvgDialog_49880_Content_6 = {
    Text = "Es ist wie eine launische riesige Python: Wenn sie wütend ist, durchbohren ihre Knochensporne deinen Körper gnadenlos; manchmal liegt sie faul über deiner Schulter."
  },
  AvgDialog_49880_Content_7 = {
    Text = "In diesem Moment bewegt es sich durch deinen Körper, dessen Spitze gegen deinen Hals drückt, wie ein Tier in sanften Werben, ähnelt aber auch einem gefährlichen Dolch."
  },
  AvgDialog_49880_Content_8 = {
    Text = "Wanda... das bist du, oder!"
  },
  AvgDialog_49880_Content_9 = {
    Text = "Hmph... Hast du so lange gebraucht, um deinen Meister zu erkennen? Was für ein inkompetentes kleines Haustier."
  },
  AvgDialog_50760_Content_1 = {
    Text = "Du starrst fassungslos auf die klebrigen, schwarzen Überreste vor dir. Dein Kamerad, der noch vor Kurzem an deiner Seite stand, liegt nun hier und ruht für immer auf diesem ewig schneebedeckten Gletscher."
  },
  AvgDialog_50760_Content_10 = {
    Text = "Du blickst nach oben. Wie eine Wolke, die die Sonne verdeckt, erhebt sich ein gewaltiger Schatten von der Seite der Klippe und ragt über euch auf."
  },
  AvgDialog_50760_Content_11 = {
    Text = "Auf dem Körper des riesigen Monsters ist ein gewaltiges Symbol eingeritzt — du hast es in deinen Träumen gesehen."
  },
  AvgDialog_50760_Content_12 = {
    Text = "Das ist... die Tempellichtkirche!!!"
  },
  AvgDialog_50760_Content_13 = {Text = "BUMM!"},
  AvgDialog_50760_Content_14 = {
    Text = "<Shake:Ah—>"
  },
  AvgDialog_50760_Content_15 = {
    Text = "Große{Male=Herr Schutzherr,Female=Frau Schutzherrin}!!!"
  },
  AvgDialog_50760_Content_16 = {
    Text = "Ein kolossales Objekt schwebt in der Luft und stürzt herab. Mit einem ohrenbetäubenden Krachen, das den Berggipfel zerreißt, pulverisiert es den Fels unter euren Füßen."
  },
  AvgDialog_50760_Content_17 = {
    Text = "Du verfehltest einen Tritt und fielst zusammen mit Helot in das tiefe Tal."
  },
  AvgDialog_50760_Content_18 = {
    Text = "—Inmitten deiner entsetzten Schreie grinste Helot und lachte zum ersten Mal."
  },
  AvgDialog_50760_Content_2 = {Text = "Ugh—"},
  AvgDialog_50760_Content_3 = {
    Text = "Unzählige Entdecker sind auf dem Schneeberg gestorben, doch solch tragische Tode und die schiere Anzahl der Opfer sind für den Führer beispiellos."
  },
  AvgDialog_50760_Content_4 = {
    Text = "Er konnte nicht mehr durchhalten, seine Schultern zitterten, als er laut würgte."
  },
  AvgDialog_50760_Content_5 = {
    Text = "Sie wurden ebenfalls aufgelöst... Das Schmelzen hier schreitet so rasant voran..."
  },
  AvgDialog_50760_Content_6 = {
    Text = "Diese fliehenden Monster und die Reaktionen dieser Teammitglieder sind einfach viel zu abnormal..."
  },
  AvgDialog_50760_Content_7 = {
    Text = "Jetzt sind nur noch wir übrig. Wir müssen schnell den Berg hinunter, sonst..."
  },
  AvgDialog_50760_Content_8 = {Text = "Boom—"},
  AvgDialog_50760_Content_9 = {
    Text = "Bevor er seinen Satz beenden konnte, wurde alles schwarz."
  },
  AvgDialog_50761_Content_1 = {
    Text = "Der Gletscher donnert erneut und beginnt, seine Haltung in äußerst langsamem Tempo zu verändern."
  },
  AvgDialog_50761_Content_10 = {
    Text = "Verlassen... Wir hatten nie das Recht zu gehen."
  },
  AvgDialog_50761_Content_11 = {
    Text = "Die Besessenheit und der Wahnsinn in den Augen der anderen „Shiro“ verschwanden plötzlich."
  },
  AvgDialog_50761_Content_12 = {
    Text = "Sie blickte Helot mit einer beispiellosen Gefasstheit und Ruhe an."
  },
  AvgDialog_50761_Content_13 = {
    Text = "Hast du die Dinge vergessen, die dich einst verletzt haben, den tief verwurzelten Hass, „Shiro“?"
  },
  AvgDialog_50761_Content_14 = {
    Text = "Ich habe nie vergessen... Ich habe nur..."
  },
  AvgDialog_50761_Content_15 = {
    Text = "Du bist verwirrt, „Shiro“."
  },
  AvgDialog_50761_Content_16 = {
    Text = "Nur mit ausreichender Macht können wir unsere Rache vollenden. Rache ist unser einziger Zweck."
  },
  AvgDialog_50761_Content_17 = {
    Text = "Rache... aber an wem?"
  },
  AvgDialog_50761_Content_18 = {Text = "Schicksal"},
  AvgDialog_50761_Content_19 = {
    Text = "Die zwei ruhigen Worte ließen Helots Körper heftig erzittern."
  },
  AvgDialog_50761_Content_2 = {
    Text = "Diesmal offenbarte der lang verborgene Eissee seine wahre Gestalt. Du erhaschst einen Blick auf eine dünne Gestalt, bedeckt mit schwarzen Pusteln, auf dem See."
  },
  AvgDialog_50761_Content_20 = {
    Text = "Egal wo wir sind, dieser Berg ruft nach uns und verschlingt uns."
  },
  AvgDialog_50761_Content_21 = {
    Text = "Das ist unser Schicksal, genau wie die abscheulichen Dinge, die wir erlebt haben..."
  },
  AvgDialog_50761_Content_22 = {
    Text = "Du kanntest die Antwort die ganze Zeit, hast aber beschlossen, sie zu ignorieren, nicht wahr?"
  },
  AvgDialog_50761_Content_23 = {
    Text = "Im Vergleich zu den Menschen und Dingen, die du hasst, ist das Schicksal ein weitaus furchteinflößenderer Gegner..."
  },
  AvgDialog_50761_Content_24 = {
    Text = "Du verdienst es nicht, ein „Krieger\" genannt zu werden, du Feigling."
  },
  AvgDialog_50761_Content_25 = {
    Text = "Dein Körper hält nicht mehr lange durch... Du wirst hier sterben."
  },
  AvgDialog_50761_Content_26 = {
    Text = "Trotzdem... was ist damit?"
  },
  AvgDialog_50761_Content_27 = {
    Text = "Sie wendet dir ihr Gesicht zu und entblößt mit einem Grinsen ein Paar listiger Reißzähne."
  },
  AvgDialog_50761_Content_28 = {
    Text = "Das Laternenlicht hat mich hierher gelockt, um mich zu benutzen, @3 wiederzuerwecken. Der Berg ruft nach mir und versucht, mich zu verschlingen. Ich wusste es die ganze Zeit, und trotzdem bin ich gekommen."
  },
  AvgDialog_50761_Content_29 = {
    Text = "Wenn der Berg mich sehen will, werde ich zu ihm kommen."
  },
  AvgDialog_50761_Content_3 = {
    Text = "Der Riss im Eissee wird breiter, wie eine lange Wunde, die sich unter dem endlosen Gletscher über die Oberfläche erstreckt."
  },
  AvgDialog_50761_Content_30 = {
    Text = "Ich muss der Laterne danken, dass sie mir die Gelegenheit gegeben hat, Ihm gegenüberzutreten..."
  },
  AvgDialog_50761_Content_31 = {
    Text = "Du bist so ein Feigling, und trotzdem bist du gekommen, nicht wahr?"
  },
  AvgDialog_50761_Content_32 = {
    Text = "Ich bin deine Zukunft, „Shiro“. Wenn du den Mut hast, dein Schwert gegen das Schicksal zu erheben, wirst du zu mir."
  },
  AvgDialog_50761_Content_33 = {
    Text = "Die schwarzen Pusteln vermehrten sich, wie ein Schwarm gieriger Urwesen, die unersättlich ihren Körper verschlangen und ihre Wangen hinaufkrochen."
  },
  AvgDialog_50761_Content_34 = {
    Text = "Sie lachte wie ein Raubtier, das gierig rohes Fleisch zerreißt, wie ein König, der im Begriff ist, den Thron zu besteigen."
  },
  AvgDialog_50761_Content_35 = {
    Text = "Sieh zu, „Shiro“... Ich werde Ihn verschlingen, stärker werden, und kein Schicksal wird mich jemals aufhalten!"
  },
  AvgDialog_50761_Content_36 = {
    Text = "Keine Ketten mehr... kein... Verrat mehr..."
  },
  AvgDialog_50761_Content_37 = {
    Text = "Schwarze Pusteln breiten sich aus und häufen sich auf ihr an, bohren sich in ihren gepeinigten Körper und bedecken ihr Gesicht mit einer Mischung aus Ruhe und Wahnsinn..."
  },
  AvgDialog_50761_Content_38 = {
    Text = "Ich werde... <Big:Rache!!!>"
  },
  AvgDialog_50761_Content_39 = {Text = "Bang—"},
  AvgDialog_50761_Content_4 = {
    Text = "Schwarze Pusteln sickern unaufhörlich hervor und bedecken eine andere „Shiro“."
  },
  AvgDialog_50761_Content_40 = {
    Text = "Wie eine aufgeplatzte Pustel spritzen schwarze und rote Flüssigkeiten überallhin."
  },
  AvgDialog_50761_Content_41 = {
    Text = "Das letzte Brüllen der Bestie hallt noch durch das Tal.\nWo sie einst stand, ist nichts geblieben als eine Pfütze aus Flüssigkeit."
  },
  AvgDialog_50761_Content_42 = {
    Text = "\"Rache\"... huh..."
  },
  AvgDialog_50761_Content_43 = {
    Text = "Helot hebt verwirrt den Kopf und blickt in den grauweiß verhangenen Himmel."
  },
  AvgDialog_50761_Content_44 = {
    Text = "Grobe Schneeflocken rollten von ihrer Haut ab und schmolzen zu kleinen Wasserflecken."
  },
  AvgDialog_50761_Content_45 = {
    Text = "Wurde sie... vom Berg verschlungen?"
  },
  AvgDialog_50761_Content_46 = {Text = "@2...@3..."},
  AvgDialog_50761_Content_47 = {
    Text = "Bevor Helot sprechen konnte, war deine Frage bereits beantwortet worden—"
  },
  AvgDialog_50761_Content_48 = {
    Text = "Der Boden unter euch beginnt zu beben. Aus den Tiefen der Berge ertönt ein dumpfer, unreiner Ruf..."
  },
  AvgDialog_50761_Content_5 = {
    Text = "Ich kann es spüren... mehr, gib mir mehr!"
  },
  AvgDialog_50761_Content_6 = {
    Text = "Diese seltsamen Pusteln spürten ihren Ruf, summten aufgeregt, strömten zu ihrem Mund und suchten aktiv danach, von ihr verschlungen zu werden."
  },
  AvgDialog_50761_Content_7 = {
    Text = "Sie scheinen es zu genießen, zerhackt zu werden, verehren es, geschluckt zu werden, und sehnen sich danach, verschlungen zu werden."
  },
  AvgDialog_50761_Content_8 = {
    Text = "Du näherst dich einer anderen „Shiro“. Ihr Körper ist in einer dunklen Blase versunken, ihre Gestalt so ätherisch, dass sie einem Hauch von Nebel gleicht, leicht zu zerstreuen."
  },
  AvgDialog_50761_Content_9 = {
    Text = "Geh jetzt, solange du noch die Chance hast..."
  },
  AvgDialog_50762_Content_1 = {
    Text = "Keine Zeit zum Nachdenken. Getrieben vom Überlebensinstinkt kriecht ihr durch den von der Höhle abgesonderten Schleim, auf den sich langsam verengenden Ausgang zu."
  },
  AvgDialog_50762_Content_10 = {
    Text = "Staub, vermischt mit Schneekörnern, zerstreut sich vor deinen Augen."
  },
  AvgDialog_50762_Content_11 = {
    Text = "Ein Riss durchzog den stockfinsteren Tunnel, und gleißend weißes Licht fiel auf meine Schultern."
  },
  AvgDialog_50762_Content_12 = {
    Text = "Halt dich fest, ich hole dich raus."
  },
  AvgDialog_50762_Content_13 = {
    Text = "Sie zerschmetterte das Höhlengestein und zog dich aus den Trümmern heraus."
  },
  AvgDialog_50762_Content_14 = {
    Text = "Die Schuld, die ich bei dir hatte, ist nun beglichen..."
  },
  AvgDialog_50762_Content_15 = {Text = "...Ah!!"},
  AvgDialog_50762_Content_16 = {Text = "Helot!!..."},
  AvgDialog_50762_Content_17 = {
    Text = "Bevor sie ihren Satz beenden konnte, stolperte sie plötzlich."
  },
  AvgDialog_50762_Content_18 = {
    Text = "—Der Boden, der einst ein Berghang war, löste sich in Luft auf und verwandelte sich im Nu in einen bodenlosen Abgrund."
  },
  AvgDialog_50762_Content_2 = {
    Text = "Fast da, gleich dort vorne —"
  },
  AvgDialog_50762_Content_3 = {
    Text = "<Big:Boom——>"
  },
  AvgDialog_50762_Content_4 = {
    Text = "Der gesamte Berg wird auf den Kopf gestellt, der Winkel des Tunnels ändert sich plötzlich und er fällt rapide ab."
  },
  AvgDialog_50762_Content_5 = {
    Text = "Der Schleim unter dir ist glitschig und bietet kaum Halt. Du kämpfst dich zum beleuchteten Höhleneingang vor, während sich der Tunnel immer heftiger windet."
  },
  AvgDialog_50762_Content_6 = {
    Text = "Die warmen Felsplatten ziehen sich immer weiter zusammen, pressen deinen Brustkorb ein und erschweren das Atmen. Selbst Lilys Körper ist in der Spalte eingeklemmt und kann sich nicht bewegen."
  },
  AvgDialog_50762_Content_7 = {
    Text = "Der einzige Ausgang wird allmählich von schwarzem Gestein verschlungen, der nahe Weg wird abgeschnitten und du versinkst in völliger Dunkelheit."
  },
  AvgDialog_50762_Content_8 = {
    Text = "Kann nicht... hier bleiben..."
  },
  AvgDialog_50762_Content_9 = {
    Text = "Krach——"
  },
  AvgDialog_50763_Content_1 = {
    Text = "Helot geht in die Hocke, ahmt deine Haltung nach und tätschelt unbeholfen Lilys weiches Haar."
  },
  AvgDialog_50763_Content_10 = {
    Text = "Sie stieß ihr Schwert in den Felsen. Nasse Haarsträhnen fielen ihr ins Gesicht, gefroren rasch zu Eiszapfen und zitterten mit ihren bebenden Schultern."
  },
  AvgDialog_50763_Content_11 = {
    Text = "Der kalte Wind des Schneebergs tobt weiter, mit dröhnenden Geräuschen, die unaufhörlich widerhallen."
  },
  AvgDialog_50763_Content_12 = {
    Text = "Welle um Welle scharfen Schmerzes durchfuhr sie, doch in diesem Moment war die Stimme in ihrem Geist glasklar."
  },
  AvgDialog_50763_Content_13 = {
    Text = "Es gibt noch viele Dinge, die ich nicht tun will, viele... Dinge, zu denen ich gezwungen und getrieben werde."
  },
  AvgDialog_50763_Content_14 = {
    Text = "<Change>Übergebe sie... mir!"
  },
  AvgDialog_50763_Content_15 = {
    Text = "Hast du auch die Fähigkeit zu kommunizieren verloren?"
  },
  AvgDialog_50763_Content_16 = {
    Text = "Dann leg deine Worte und Gefühle in dein Schwert.\nLass mich deine Wut im Kampf hören!"
  },
  AvgDialog_50763_Content_17 = {
    Text = "Ich bin viele, viele Male verraten worden."
  },
  AvgDialog_50763_Content_18 = {
    Text = "Warum? Warum? Ich muss die Herrin sehen!"
  },
  AvgDialog_50763_Content_19 = {
    Text = "Mach dir nichts vor. Glaubst du immer noch, du wärst die edle Adoptivtochter des Regenten?"
  },
  AvgDialog_50763_Content_2 = {
    Text = "Lily war halb im Berg begraben, ihre schwarzen Tränen flossen unkontrolliert, ihre leeren Augen auf Helot gerichtet."
  },
  AvgDialog_50763_Content_20 = {
    Text = "Schmutzige Blutlinie, am Ende konnte sie nur eine <Blue:Verräterin> wie dich hervorbringen."
  },
  AvgDialog_50763_Content_21 = {
    Text = "<BigShake:Antworte mir!>\nBin ich verstoßen worden?!"
  },
  AvgDialog_50763_Content_22 = {
    Text = "Ja, aber... was das Ergebnis betrifft..."
  },
  AvgDialog_50763_Content_23 = {
    Text = "Ihre zitternde Hand konnte den Griff nicht mehr halten; das Langschwert gab ein metallisches Summen von sich, ausgelöst durch das Beben des Felsens."
  },
  AvgDialog_50763_Content_24 = {
    Text = "Einst dachte ich, Rache wäre alles für mich... Doch heute erkenne ich, dass ich ihre Bedeutung missverstanden und den falschen Gegner ins Visier genommen habe."
  },
  AvgDialog_50763_Content_25 = {
    Text = "Nur mit ausreichender Macht können wir unsere Rache vollenden. Rache ist unser einziger Zweck."
  },
  AvgDialog_50763_Content_26 = {
    Text = "Wenn der Berg mich sehen will, werde ich zu ihm kommen."
  },
  AvgDialog_50763_Content_27 = {
    Text = "Ich bin deine Zukunft, „Shiro“. Wenn du den Mut hast, dein Schwert gegen das Schicksal zu erheben, wirst du zu mir."
  },
  AvgDialog_50763_Content_28 = {
    Text = "Du willst also Rache am Verräter nehmen und Franz beschützen, richtig?\nAber beim Kampf geht es nicht darum."
  },
  AvgDialog_50763_Content_29 = {
    Text = [[
Nicht zum Schutz, nicht zur Rache, nicht zum Beweis.
Kampf ist einfach Kampf.]]
  },
  AvgDialog_50763_Content_3 = {
    Text = "Sie hat genug gelitten. Lass mich das erledigen."
  },
  AvgDialog_50763_Content_30 = {
    Text = "Deine Welt ist zu klein, deshalb fixierst du dich immer auf das schwache Glimmen, das andere entzünden, wie eine Motte, die vom Licht angezogen wird."
  },
  AvgDialog_50763_Content_31 = {
    Text = "Wenn Sie die Gelegenheit haben, gehen Sie und erkunden Sie eine größere Welt."
  },
  AvgDialog_50763_Content_32 = {
    Text = "Lass los! Du hältst das nicht lange durch."
  },
  AvgDialog_50763_Content_33 = {
    Text = "Ich... werde nicht..."
  },
  AvgDialog_50763_Content_34 = {
    Text = "Lass los... Du stirbst, wenn das so weitergeht!"
  },
  AvgDialog_50763_Content_35 = {
    Text = "Ich werde keinen Kameraden jemals im Stich lassen, egal was... Niemals!"
  },
  AvgDialog_50763_Content_36 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_50763_Content_38 = {
    Text = "Lotan sagte: „Kampf ist einfach Kampf, weder zum Schutz noch zur Rache.\""
  },
  AvgDialog_50763_Content_39 = {
    Text = "Ich habe lange und gründlich nachgedacht und verstehe endlich, warum du und dein Erwecker so mächtig seid..."
  },
  AvgDialog_50763_Content_4 = {
    Text = "Nein... Nein, es darf nicht so enden... Es muss einen anderen Weg geben..."
  },
  AvgDialog_50763_Content_40 = {
    Text = "Ich glaube, Lotan lag falsch. Vielleicht hat sie es selbst nicht einmal bemerkt."
  },
  AvgDialog_50763_Content_41 = {
    Text = "Lotan, Lily, du... ihr alle habt etwas, das ihr beschützt."
  },
  AvgDialog_50763_Content_42 = {
    Text = "Wachen ist meine vorbestimmte Rolle."
  },
  AvgDialog_50763_Content_43 = {
    Text = "Diese Lektion hast du mich gelehrt, Schutzherr."
  },
  AvgDialog_50763_Content_44 = {
    Text = "„Bumm—“"
  },
  AvgDialog_50763_Content_45 = {
    Text = "Der Berg bebte erneut heftig, und das dicke Eis auf dem See zerbarst Stück für Stück."
  },
  AvgDialog_50763_Content_46 = {
    Text = "Unter den zerbrochenen Fragmenten quellen schwarze Pusteln hervor und breiten sich aus wie kochende Brühe."
  },
  AvgDialog_50763_Content_47 = {
    Text = "Helot, ich werde niemals meine Kameraden im Stich lassen!"
  },
  AvgDialog_50763_Content_48 = {
    Text = "Ich mag es nicht, bei anderen in der Schuld zu stehen. Du hast mich gerettet, also sind wir nach heute quitt."
  },
  AvgDialog_50763_Content_49 = {
    Text = "Ich kann einen weiteren „Shiro“ spüren... Sie wartet in den Bergen auf mich. Sie will sich mir anschließen, um das Schicksal zu rächen."
  },
  AvgDialog_50763_Content_5 = {
    Text = "Keine Zeit mehr, Schutzherr."
  },
  AvgDialog_50763_Content_50 = {
    Text = "Du hast niemanden im Stich gelassen. Den Rest des Weges gehen wir allein."
  },
  AvgDialog_50763_Content_51 = {
    Text = "Wir sind Krieger. Krieger sind geboren, um zu kämpfen."
  },
  AvgDialog_50763_Content_52 = {
    Text = "Dies ist das Schicksal, das wir selbst gewählt haben... Dies ist unser Kampf mit dem Berg."
  },
  AvgDialog_50763_Content_53 = {
    Text = "Helot zieht den schwarzen Stachel heraus."
  },
  AvgDialog_50763_Content_54 = {
    Text = "Dichte Wolken bedecken den Schneeberg, kein Sonnenlicht erreicht den Boden."
  },
  AvgDialog_50763_Content_55 = {
    Text = "Helots Körper ist von schwarzem Schleim umschlungen, gebunden von den Ketten unbewussten Wahnsinns, die sie in Schichten von Fesseln einschließen."
  },
  AvgDialog_50763_Content_56 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_50763_Content_58 = {
    Text = "Mit Ketten auf ihren schmalen Schultern schleppte sie sich vorwärts. Ihr Körper, von schweren Fesseln gebunden, rang nach Atem und brach im Schnee zusammen."
  },
  AvgDialog_50763_Content_59 = {Text = "Helot..."},
  AvgDialog_50763_Content_6 = {
    Text = "Der einzige Weg, wie ihr Aelwys lebend verlassen könnt, ohne euch erneut vor meinen Augen in Monster zu verwandeln, ist dieser..."
  },
  AvgDialog_50763_Content_60 = {
    Text = "Endloses Flüstern von Tabus füllt ihre Ohren. Im zähflüssigen, dunklen Klang hört Helot die Resonanz von Bergen und Herzschlägen."
  },
  AvgDialog_50763_Content_61 = {
    Text = "Bumm, bumm, bumm..."
  },
  AvgDialog_50763_Content_62 = {
    Text = "Unter der gefrorenen, harten Gesteinsschicht brummt der erwachte Riese ungeduldig und sehnt sich nach ihr."
  },
  AvgDialog_50763_Content_63 = {
    Text = "Sie stand auf dem Gipfel."
  },
  AvgDialog_50763_Content_64 = {
    Text = "Die rasenden Berggipfel regten sich, der Boden bebte heftig, und der eisige Wind zerrte an Helots dünner Kleidung, doch sie blieb unerschütterlich."
  },
  AvgDialog_50763_Content_65 = {
    Text = "Ein Schwall schwarzen Schleims ergießt sich von der Spitze des Schneebergs und umkreist sie wie eine turmhohe Welle —"
  },
  AvgDialog_50763_Content_66 = {
    Text = "@3Rückkehr... Zerstören @2... Vergessen @3@2... Komm... Zurück zu @3..."
  },
  AvgDialog_50763_Content_67 = {
    Text = "...Rückkehr@3"
  },
  AvgDialog_50763_Content_68 = {
    Text = "Wenn wir gewinnen, wird das Eis und der Schnee von Aelwys schmelzen. Dann werden wir gemeinsam wieder erscheinen."
  },
  AvgDialog_50763_Content_69 = {
    Text = "Warte, Schutzherr."
  },
  AvgDialog_50763_Content_7 = {
    Text = "Ihr werdet hier sterben!"
  },
  AvgDialog_50763_Content_70 = {
    Text = "Helot dreht kurz den Kopf. Du glaubst, ein flüchtiges Lächeln über ihr Gesicht huschen zu sehen."
  },
  AvgDialog_50763_Content_71 = {
    Text = "Sie drehte sich um und hob den schwarzen Stachel der ewigen blauen Flamme entgegen —"
  },
  AvgDialog_50763_Content_72 = {
    Text = "Kampf, Beginn."
  },
  AvgDialog_50763_Content_74 = {
    Text = "Es war zugleich eine Erklärung und ein Befehl. Unzählige schwarze Schleimmassen fielen plötzlich herab und verschlangen alles auf dem Gipfel."
  },
  AvgDialog_50763_Content_75 = {
    Text = "Das Aelwys-Gebirge erbebte. Die durchgehende Bergkette wirbelte milchigen Eisnebel auf, starre und unbeholfene Massen rangen und wanden sich verzweifelt, als kämpften sie gegen etwas an."
  },
  AvgDialog_50763_Content_76 = {
    Text = "Die brennenden Wolken werden von heftigen Winden gepeitscht, und ein gewaltiger Wirbel verschlingt den gesamten Gipfel. Furchteinflößende Kraft bricht unkontrolliert hervor, als würde sie den Himmel zerreißen..."
  },
  AvgDialog_50763_Content_77 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_50763_Content_78 = {
    Text = "Die Zeit verging unbemerkt. Der Staub legte sich endlich, und der Boden unter den Füßen bebte nicht mehr."
  },
  AvgDialog_50763_Content_79 = {
    Text = "Lily, nun wieder normal, kommt herüber und nimmt deine Hand."
  },
  AvgDialog_50763_Content_8 = {
    Text = "„Selbst wenn... was soll's?“"
  },
  AvgDialog_50763_Content_80 = {
    Text = "Helot... ist fort."
  },
  AvgDialog_50763_Content_81 = {
    Text = "Die Berge atmen gleichmäßig. Du hebst den Kopf und blickst zum Himmel empor."
  },
  AvgDialog_50763_Content_82 = {
    Text = "Grobe Schneeflocken fallen herab, häufen sich auf deinem Kopf und färben dein Haar grau."
  },
  AvgDialog_50763_Content_83 = {
    Text = "Aelwys ist unheimlich still, als wäre nie etwas geschehen."
  },
  AvgDialog_50764_Content_1 = {
    Text = "Wein und Neuigkeiten, du wirst beides lieben. Gute Ruhe, Schutzherr."
  },
  AvgDialog_50764_Content_2 = {
    Text = "Dexter machte dir eine elegante leichte Verbeugung und schloss sanft die Tür."
  },
  AvgDialog_50764_Content_3 = {
    Text = "Manchmal, wenn ich Professor Dexter gegenüberstehe, bereue ich es, Rhetorik nicht eingehender studiert zu haben."
  },
  AvgDialog_50764_Content_4 = {
    Text = "Sie nahm die Zeitung auf, die Dexter hinterlassen hatte."
  },
  AvgDialog_50764_Content_5 = {
    Text = "„Kürzlich ereignete sich eine schwere Lawine in den ewig gefrorenen Schneebergen von Aelwys. Nun haben seltsame Anzeichen von Tauwetter begonnen zu erscheinen...\""
  },
  AvgDialog_50764_Content_6 = {
    Text = "Du drehtest schnell den Kopf und griffst nach der Zeitung."
  },
  AvgDialog_50764_Content_7 = {
    Text = "Das verschwommene, in Tinte gedruckte Bild zeigt, dass der Schneesturm in den Bergen aufgehört hat."
  },
  AvgDialog_50764_Content_8 = {
    Text = "Ein kleiner Löwenzahn bricht durch den ewigen Schnee und schaut hervor"
  },
  AvgDialog_50764_Content_9 = {
    Text = "Er begrüßt Aelwys' ersten Frühling."
  },
  AvgDialog_50895_Content_1 = {
    Text = "Ich kann nicht... nicht mehr festhalten..."
  },
  AvgDialog_50895_Content_10 = {
    Text = "Der vertraute Schrei hallt erneut am Himmel von Lemwash wider. Im Gegensatz zu zuvor ist er jedoch dieses Mal besonders sanft, wie eine silberne Brise, die vorüberzieht."
  },
  AvgDialog_50895_Content_11 = {
    Text = "In einem Dämmerzustand scheinst du zu sehen, wie die Gestalt am Tor sich umdreht und dich ansieht—"
  },
  AvgDialog_50895_Content_2 = {
    Text = "Ramona spuckte einen Mundvoll Blut aus, das beim Aufprall auf den Boden pechschwarz wurde."
  },
  AvgDialog_50895_Content_3 = {
    Text = "Zwei scharfe Kräfte prallten in ihrem Geist aufeinander; das silberne Geschrei und der Blutrausch verwandelten ihr mentales Meer in Chaos."
  },
  AvgDialog_50895_Content_4 = {
    Text = "Ist das das Ende...?"
  },
  AvgDialog_50895_Content_5 = {
    Text = "Du schnappst nach Luft, deine Sicht verschwommen von Blut und Schweiß, verlässt dich allein auf deinen Willen, um dich stehend zu halten."
  },
  AvgDialog_50895_Content_6 = {
    Text = "Ist das das Ende? Dir gehen die Patronen aus, doch der Embryo des Mutterbaums wächst weiter, windet sich und vermehrt sich..."
  },
  AvgDialog_50895_Content_7 = {
    Text = "Ding-dong—"
  },
  AvgDialog_50895_Content_8 = {
    Text = "Eine kalte und sanfte Feder verwandelt sich in einen Tropfen Silber, der lautlos über deine blutverschmierten Wangen rollt und Spuren wie reine Sil Tränen hinterlässt."
  },
  AvgDialog_50895_Content_9 = {
    Text = "Für Mythag, für die Zukunft der Menschheit, halte noch ein wenig durch."
  },
  AvgDialog_50896_Content_1 = {
    Text = "Der massive Tumor des Mutterbaums wird von einem Rapier durchstochen, spritzt Blut und durchnässt dich mit einem Regen aus scharlachrotem Regen."
  },
  AvgDialog_50896_Content_10 = {Text = "Juliette!"},
  AvgDialog_50896_Content_11 = {
    Text = "Juliette saß auf dem Ast und seufzte von oben. Sie streichelte sanft die wankenden Äste des Mutterbaums, als würde sie ein unruhiges Tier beruhigen."
  },
  AvgDialog_50896_Content_12 = {
    Text = "Große Mutterbaum, bitte schöpfe aus der Quelle des Lebens."
  },
  AvgDialog_50896_Content_13 = {
    Text = "Bitte benutze deinen Körper, um den schwarzen Segen über die Wüste zu verbreiten und eine Treppe zur neuen Welt zu bauen."
  },
  AvgDialog_50896_Content_14 = {
    Text = "Es ist nicht nötig, Sündern Mitleid zu erweisen. Um Erlösung zu suchen, haben die Aram schon längst geschworen, dir ihre volle Hingabe anzubieten."
  },
  AvgDialog_50896_Content_15 = {
    Text = "Knack, knack, das Geräusch brechender Knochen hallte wider. Alans Caro verschmolz mit den Ästen in sichtbarem Tempo. Die zuckenden Klumpen bewegten sich, lösten sich auf und reformierten sich."
  },
  AvgDialog_50896_Content_16 = {
    Text = "Tausende von Nachkommen und Caro versammeln sich zu einer deformierten Mutter, und der schwankende Stamm stabilisiert sich allmählich."
  },
  AvgDialog_50896_Content_17 = {
    Text = "Möge die Laterne brennen bleiben."
  },
  AvgDialog_50896_Content_2 = {
    Text = "*Hust, hust...*"
  },
  AvgDialog_50896_Content_3 = {
    Text = "Der wilde Blutregen betraf Ramona viel mehr als dich. Ramona wischte sich das Blut aus den Ponys und begann heftig zu husten."
  },
  AvgDialog_50896_Content_4 = {
    Text = "Ramona, du..."
  },
  AvgDialog_50896_Content_5 = {
    Text = "Es ist okay, ich kann durchhalten. Schau dir die Baumknolle an!"
  },
  AvgDialog_50896_Content_6 = {
    Text = "Der platzende Baumknoten sinkt wie ein blutloses Stück Fleisch, und der einst stolze Stamm des Mutterbaums zittert, als würde er eine ungewöhnliche Angst und Unruhe vermitteln."
  },
  AvgDialog_50896_Content_7 = {
    Text = "Wird der Mutterbaum... fallen?"
  },
  AvgDialog_50896_Content_8 = {
    Text = "Nein, noch nicht..."
  },
  AvgDialog_50896_Content_9 = {
    Text = "Es ist wirklich traurig. Warum bestehst du auf so vergeblichen Bemühungen?"
  },
  AvgDialog_50897_Content_1 = {
    Text = "Der Mutterbaum beginnt weiter Nubien zu spalten...!"
  },
  AvgDialog_50897_Content_2 = {
    Text = "Es tut mir leid, die Belastung durch Juliette ist tiefgreifend. Ich werde den Mutterbaum nicht kontrollieren können, bis Tawil ihre Reinigung abgeschlossen hat."
  },
  AvgDialog_50897_Content_3 = {
    Text = "Das ist mein Versagen als Verlangenseinheit. Daher werde ich dir im bevorstehenden Kampf meine Kraft leihen."
  },
  AvgDialog_50897_Content_4 = {
    Text = "Es ist ziemlich selten, die Gelegenheit zu haben, die Macht von Tifrey Yesod zu wielden."
  },
  AvgDialog_50897_Content_5 = {
    Text = "Fühlen Sie sich frei, es zu benutzen, verschwenden Sie keinen Tropfen, in Ordnung?"
  },
  AvgDialog_51150_Content_1 = {Text = "Horla?"},
  AvgDialog_51150_Content_10 = {
    Text = "Diese Dinge sind alle in meiner Gedichtsammlung aufgetaucht. Alles hier ist genau so, wie ich es in meinen Gedichten vorgestellt habe..."
  },
  AvgDialog_51150_Content_11 = {
    Text = "{Male=Sir,Female=Madam} Schutzherr, das ist nicht die echte Cité."
  },
  AvgDialog_51150_Content_12 = {
    Text = "Das ist die <Yellow:Cité meiner Vorstellung>..."
  },
  AvgDialog_51150_Content_13 = {
    Text = "Unter dem Sternenlicht der Märzstraße drehte sich Aurita langsam im Kreis und betrachtete alles, was zu ihrem Gedicht gehörte"
  },
  AvgDialog_51150_Content_14 = {
    Text = "Wie ein Schleier fällt das Sonnenlicht und beleuchtet ihr neugieriges, trauriges, verwirrtes Gesicht"
  },
  AvgDialog_51150_Content_15 = {
    Text = "Ich verstehe... Kein Wunder, dass es hier so viele bizarre Dinge gibt."
  },
  AvgDialog_51150_Content_16 = {
    Text = "Aber wie konnte es zur Cité kommen"
  },
  AvgDialog_51150_Content_17 = {
    Text = "Ich weiß auch nicht... Und hier sind einige Dinge anders als in meinen Gedichten, der Maler sollte eigentlich ein süßer alter Mann sein"
  },
  AvgDialog_51150_Content_18 = {
    Text = "Aber ich denke, wenn wir das Problem hier lösen wollen, müssen wir zuerst dieses Gedicht finden."
  },
  AvgDialog_51150_Content_19 = {
    Text = "Erinnerst du dich immer noch an den Weg?"
  },
  AvgDialog_51150_Content_2 = {
    Text = "Ah, Entschuldigung, Geheimnisträger{Male=Herr,Female=Frau}, ich war gerade abgelenkt"
  },
  AvgDialog_51150_Content_20 = {
    Text = "In meiner Poesie ist die March Street nahe der Heimat. Ich erinnere mich immer an den Rückweg."
  },
  AvgDialog_51150_Content_21 = {
    Text = "Sie lächelte in Richtung der Slums."
  },
  AvgDialog_51150_Content_22 = {
    Text = "Gehen wir, {Male=Sir,Female=Madam} Schutzherr, wir begeben uns zum Rosengarten... dorthin, wo ich gestorben bin."
  },
  AvgDialog_51150_Content_3 = {
    Text = "Ich habe eine Vermutung... Nein, ich bin mir sicher"
  },
  AvgDialog_51150_Content_4 = {
    Text = "Das ist nicht die Cité!"
  },
  AvgDialog_51150_Content_5 = {
    Text = "...Horla, was sagst du da?"
  },
  AvgDialog_51150_Content_6 = {
    Text = "Ah, ich meine, das hier ist nicht das echte Cité"
  },
  AvgDialog_51150_Content_7 = {
    Text = "Das ist nicht die echte Cité...?"
  },
  AvgDialog_51150_Content_8 = {
    Text = "Der Raupenzug, für den man ein Gedicht als Fahrkarte braucht, Madame Schmetterling, nur die Märzstraße Nr. 99, der Maler, Gänseblümchen-Sterne..."
  },
  AvgDialog_51150_Content_9 = {
    Text = "Diese Dinge, die wir sehen, kommen mir so vertraut vor. Bis gerade eben habe ich es endlich erkannt"
  },
  AvgDialog_51254_Content_1 = {
    Text = "Ihr Blick reinigte deine Seele, wusch sofort die Müdigkeit weg und entzündete den unbezwingbaren Kampfgeist in deiner Brust."
  },
  AvgDialog_51254_Content_2 = {
    Text = "Danke, Tawil..."
  },
  AvgDialog_51254_Content_3 = {
    Text = "Ich werde deinen Willen bis zum letzten Moment umsetzen.\nMöge der Silberne Schlüssel den Weg leiten."
  },
  AvgDialog_51254_Content_4 = {
    Text = "Möge der Silberschlüssel uns leiten"
  },
  AvgDialog_51998_Content_1 = {
    Text = "Der Spott der Phillistine hallt durch den Raum. Der Phillistine-Hauptmann schüttelt den Kopf, packt Talis an den Haaren und zieht einen Dolch hervor."
  },
  AvgDialog_51998_Content_10 = {
    Text = "„Du hast mich daran erinnert, dass ich Goliaths Sachen wegwerfen sollte, damit Iglan keinen Verdacht schöpft.\""
  },
  AvgDialog_51998_Content_11 = {
    Text = "„Dafür kann ich dir einen weniger schmerzhaften Tod gewähren... oh?\""
  },
  AvgDialog_51998_Content_2 = {
    Text = "Er wendet sich Miryam zu. Eine Statuette baumelt an seiner Hüfte. Sie reißt plötzlich die Augen auf."
  },
  AvgDialog_51998_Content_3 = {
    Text = "„Woher habt ihr diese Statuette?\""
  },
  AvgDialog_51998_Content_4 = {
    Text = "„Oh... Du kannst also reden, hm? Ich dachte, du wärst eine Schwachsinnige.\""
  },
  AvgDialog_51998_Content_5 = {
    Text = "„Statuette, woher stammt sie?\""
  },
  AvgDialog_51998_Content_6 = {
    Text = "Der Hauptmann legt sein Messer ab und blickt auf die Statuette an seinem Gürtel hinunter."
  },
  AvgDialog_51998_Content_7 = {
    Text = "Die Statue besteht aus einem sehr alten, matten Steinmaterial und zeigt einen Jungen auf einem Thron. Einige seltsame Tentakel verdecken sein Gesicht"
  },
  AvgDialog_51998_Content_8 = {
    Text = "„Heh... das? Der frühere Häuptling Goliath hat es gefunden. Er hat es mir für meinen Mut gegeben.\""
  },
  AvgDialog_51998_Content_9 = {
    Text = "„Ich habe mein Leben für ihn riskiert, und das ist die Belohnung, die er mir gab. Irgendein nutzloser Plunder, den irgendeine dumme Zivilisation hinterlassen hat.\""
  },
  AvgDialog_51999_Content_1 = {Text = "Boom—"},
  AvgDialog_51999_Content_10 = {
    Text = "\"Auch du wirst von einem höheren Willen verfolgt und gejagt. Wie Yu bist du eine herrenlose, wandernde Seele.\""
  },
  AvgDialog_51999_Content_11 = {
    Text = "\"Die Lemurianer verehren grausame Götter und schwache Könige. Göttliches Reich... Haha, es ist so langweilig.\""
  },
  AvgDialog_51999_Content_2 = {
    Text = "Ein gedämpftes Geräusch dringt durch zahlreiche dicke Steinwände und hallt im Gemach des Tempels wider."
  },
  AvgDialog_51999_Content_3 = {
    Text = "Tulu sitzt auf dem Thron, das Kinn in eine Hand gestützt, die Augenlider schwer vor Erschöpfung."
  },
  AvgDialog_51999_Content_4 = {
    Text = "Die Lemurianer sind in ewigen Schlummer gefallen. Er hat all seine Kraft aufgebraucht, um ihnen einen schönen Traum zu schenken, ein Trugbild seines Versprechens."
  },
  AvgDialog_51999_Content_5 = {
    Text = "„„Der Sturm von Limoria wird sich legen. Der Abgrund von Limoria wird verschwinden.\"„"
  },
  AvgDialog_51999_Content_6 = {
    Text = "„Der König soll sein gütiges Volk beschirmen und das Göttliche Reich hervorbringen.“"
  },
  AvgDialog_51999_Content_7 = {
    Text = "\"Wie ironisch. Ist dies dein Wille, 'Gott von Lemuria'?\""
  },
  AvgDialog_51999_Content_8 = {
    Text = "Er hebt den Kopf. Sein Blick durchdringt die Dachplatten, den prasselnden Regen und die sich vereinenden Wolken, bis er den tiefen Sternenhimmel und den tiefen Traum der Sternbilder erreicht."
  },
  AvgDialog_51999_Content_9 = {
    Text = "„Du bist schon tot. Du hast dich nie um Limoria gekümmert.\""
  },
  AvgDialog_52000_Content_1 = {
    Text = "Die Tugend der Lügen"
  },
  AvgDialog_52000_Content_10 = {
    Text = "Dieser König, der von den Lemurischen unzählige Male besungen wurde, steht zum ersten Mal vor Miryam"
  },
  AvgDialog_52000_Content_11 = {
    Text = "Hinter dieser Tür werden einige weinen, einige werden verrückt, und einige haben versucht, mich zu töten"
  },
  AvgDialog_52000_Content_2 = {
    Text = "Er starrt auf das Becken."
  },
  AvgDialog_52000_Content_3 = {
    Text = "Unzählige glitschige Köpfe tauchen auf, dann sinken sie wieder hinab. Steigen und sinken. Schmutzige Wellen stören die Oberfläche."
  },
  AvgDialog_52000_Content_4 = {
    Text = "Gewaltige Augäpfel, die zu beiden Seiten hervorquellen, rollen leer umher, während sie sich ihm entgegenstrecken. Ihre schmallippigen Münder öffnen und schließen sich, murmeln unerklärliche Silben, als versuchten sie, ihn etwas zu fragen."
  },
  AvgDialog_52000_Content_5 = {
    Text = "Hinter ihm gleiten die Schiefertüren auf."
  },
  AvgDialog_52000_Content_6 = {
    Text = "Gepriesen sei unser Herr... Gepriesen sei der große König von Lemuria..."
  },
  AvgDialog_52000_Content_7 = {
    Text = "Bei jedem ersten Treffen mit dem Hauptpriester höre ich diesen sarkastischen Satz"
  },
  AvgDialog_52000_Content_8 = {
    Text = "Lemurias riesige Krone reflektierte das düstere Licht im Raum und war unverhältnismäßig groß für den Jungen, aber sie passte perfekt, als wäre sie ein Teil von ihm"
  },
  AvgDialog_52000_Content_9 = {
    Text = "Seine schlummernden Augen verfolgen Miryams Gesicht, die Brauen zucken wie das Ausatmen des Meeres. Stille verhüllt sein jugendliches Antlitz und verbirgt jede knabenhafte Regung."
  },
  AvgDialog_52001_Content_1 = {
    Text = "Aber das macht nichts, mein Herr versteht deine Angst. Unsere Freundschaft wird durch diese Beleidigungen nicht verändert"
  },
  AvgDialog_52001_Content_10 = {
    Text = "Komm, bete mit mir, Deborah."
  },
  AvgDialog_52001_Content_11 = {
    Text = "Nein... Miryam... bitte..."
  },
  AvgDialog_52001_Content_12 = {
    Text = "Sprich mir nach: „Das Leid soll vergolten werden...“"
  },
  AvgDialog_52001_Content_13 = {
    Text = "Das... das Leid... nein, Miryam..."
  },
  AvgDialog_52001_Content_14 = {
    Text = "Sprich mir nach: „Die Frevler sollen gegeißelt werden — denn der Herr richtet ihre Missetat.“"
  },
  AvgDialog_52001_Content_15 = {
    Text = "Miryam singt die Gebete, während sie an die Seite ihrer Freundin tritt."
  },
  AvgDialog_52001_Content_16 = {
    Text = "Lass mich ein Wort an Nord richten! Miryam... nur ein einziges Wort an ihn..."
  },
  AvgDialog_52001_Content_17 = {
    Text = "Ah!!!——"
  },
  AvgDialog_52001_Content_18 = {
    Text = "Qual flammt in ihrem Unterleib auf. Sie blickt hoch und sieht Miryams bleiche, schlangengleiche Hand, die den Dolch tief hineintreibt und einen purpurroten Pfad über ihren Bauch zieht."
  },
  AvgDialog_52001_Content_19 = {
    Text = "Miryam ist taub für die schrillen Schreie. Sie sieht nicht das von Entsetzen und Schmerz verzerrte Gesicht."
  },
  AvgDialog_52001_Content_2 = {
    Text = "Ehrfürchtig stellt sie das Götzenbild von Tulu neben den Altar und verneigt sich davor."
  },
  AvgDialog_52001_Content_20 = {
    Text = "Der Dolch bewegte sich stetig und spritzte warmes Blut auf Miryams Gesicht. Sie bete devot und trat den Weg zum Göttlichen Reich ein."
  },
  AvgDialog_52001_Content_21 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_52001_Content_22 = {
    Text = "Tötet Miryam! Spaltet die Familie Ornn! Lang lebe unsere Allianz! Jubel!"
  },
  AvgDialog_52001_Content_23 = {
    Text = "Gläser klirren, während zügellose Gier sich mit dem Duft von Wein und Fleisch vermischt."
  },
  AvgDialog_52001_Content_24 = {
    Text = "Goliath leckt sich die Lippen und genießt den berauschenden Geschmack."
  },
  AvgDialog_52001_Content_25 = {
    Text = "Komm schon, mach weiter. Was ist los mit dir?"
  },
  AvgDialog_52001_Content_26 = {
    Text = "Euer... euer Gesicht..."
  },
  AvgDialog_52001_Content_27 = {
    Text = "Mein Gesicht?"
  },
  AvgDialog_52001_Content_28 = {
    Text = "Er blickt auf die spiegelblanken Fliesen neben sich und sieht ein Gesicht, das einem Fisch gleicht."
  },
  AvgDialog_52001_Content_29 = {Text = "ARGH!!"},
  AvgDialog_52001_Content_3 = {
    Text = "Gepriesen sei der Herr... Lemuria, der Große König... Heute Nacht heiße ich deine Rückkehr willkommen."
  },
  AvgDialog_52001_Content_30 = {
    Text = "Wunden öffnen sich auf seiner Brust, als würden unsichtbare Dolche sie einritzen. Seine Ohren und Augenbrauen verschwinden; seine Augäpfel quellen hervor und wandern an die Seiten seines Kopfes."
  },
  AvgDialog_52001_Content_31 = {
    Text = "Qual durchdringt den Nebel aus Alkohol und Adrenalin. Er bricht zu Boden, würgt vor Schmerz, seine Hände kratzen verzweifelt an seinem Gesicht."
  },
  AvgDialog_52001_Content_32 = {
    Text = "Was ist das? Ah!!"
  },
  AvgDialog_52001_Content_33 = {
    Text = "Eine Person, zwei, drei... im prunkvollen Bankettsaal fallen die Adeligen einer nach dem anderen zu Boden."
  },
  AvgDialog_52001_Content_34 = {
    Text = "Blutrote Risse erscheinen auf ihren Körpern, Blut und Fleisch formen uralte, groteske Muster."
  },
  AvgDialog_52001_Content_35 = {
    Text = "Ihre Schmerzensschreie vereinen sich zu einer gewaltigen Symphonie. Blut spritzt und füllt jeden Kelch."
  },
  AvgDialog_52001_Content_36 = {
    Text = "Das ist... das ist... ein Fische-Ritual!"
  },
  AvgDialog_52001_Content_37 = {
    Text = "Stimmt, das Fischmenschenritual. Ihr kennt sicher die Tragödie der Orns"
  },
  AvgDialog_52001_Content_38 = {
    Text = "Warum... Goliath?"
  },
  AvgDialog_52001_Content_39 = {Text = "Warum?"},
  AvgDialog_52001_Content_4 = {
    Text = "Habe Geduld. Die Sterne rücken in ihre Konstellation."
  },
  AvgDialog_52001_Content_40 = {
    Text = "Goliath scheint einen urkomischen Witz gehört zu haben. Er erhebt sich vom Hochsitz und greift zu seiner Klinge."
  },
  AvgDialog_52001_Content_41 = {
    Text = "Mit euch zusammenzuarbeiten hätte mir einen kleinen Fetzen von Ornns Territorium eingebracht."
  },
  AvgDialog_52001_Content_42 = {
    Text = "Aber durch die Zusammenarbeit mit Miryam erlange ich Macht jenseits eures Verständnisses. Ich kann eure gesamten Häuser in Fischmenschen verwandeln und all euren Reichtum an mich reißen."
  },
  AvgDialog_52001_Content_43 = {
    Text = "Sag mir, Mr. Edmond, wenn du an meiner Stelle wärst, was würdest du wählen?"
  },
  AvgDialog_52001_Content_44 = {
    Text = "Wir... wir werden nicht kampflos aufgeben!"
  },
  AvgDialog_52001_Content_45 = {
    Text = "Ganz recht! Goliath, bei der Ehre der Familie Enom, werden wir—ugh!"
  },
  AvgDialog_52001_Content_46 = {
    Text = "Eine gewaltige Klinge fährt herab und spaltet den jungen Adeligen entzwei. Seine Ehre stirbt mit ihm."
  },
  AvgDialog_52001_Content_47 = {
    Text = "Die Türen fliegen auf, als eine Flut von Fischmenschen die Halle überschwemmt."
  },
  AvgDialog_52001_Content_48 = {
    Text = "...Wo sind die Wachen?"
  },
  AvgDialog_52001_Content_49 = {
    Text = "Während ihr angestoßen und getrunken habt, haben wir bereits eure Leibgarden abgeschlachtet."
  },
  AvgDialog_52001_Content_5 = {
    Text = "Sie erhebt sich und schreitet mit sanftem Gang auf Deborah zu. Ein bizarrer Zeremoniendolch glitzert in ihrer bleichen Hand."
  },
  AvgDialog_52001_Content_50 = {
    Text = "Was eure Armeen außerhalb der Stadt betrifft... versucht gar nicht erst, sie zu kontaktieren."
  },
  AvgDialog_52001_Content_51 = {
    Text = "Blut befleckt jeden Winkel der Halle. Schreie hallen von den Wänden wider wie eine Symphonie aus der Hölle."
  },
  AvgDialog_52001_Content_52 = {
    Text = "Jene, die den vergifteten Wein nicht getrunken haben, zittern, ihre Körper zu schwach, um auch nur ein Schwert zu ziehen oder zu fliehen."
  },
  AvgDialog_52001_Content_53 = {
    Text = "Goliath bewundert das blutige Meisterwerk und genießt den Schrecken in ihren Gesichtern. Er seufzt zufrieden und hebt seine gewaltige Klinge."
  },
  AvgDialog_52001_Content_54 = {
    Text = "Trinkt den Wein und werdet zu Fischmenschen, oder geht hier zugrunde. Trefft eure Wahl."
  },
  AvgDialog_52001_Content_55 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_52001_Content_56 = {
    Text = "Ah!!!——"
  },
  AvgDialog_52001_Content_57 = {
    Text = "Ein durchdringender Schrei trifft auf die Steintafeln und erzeugt ein dumpfes, schweres Echo."
  },
  AvgDialog_52001_Content_58 = {
    Text = "Sie versucht sich zu wehren, zu entkommen, doch Miryam hält sie eisern fest. Sie kann sich keinen Zentimeter bewegen."
  },
  AvgDialog_52001_Content_59 = {
    Text = "Sie sehnt sich danach, in Ohnmacht zu fallen, doch ihr Verstand bleibt qualvoll klar und zwingt sie, sich der Pein und der Angst zu stellen."
  },
  AvgDialog_52001_Content_6 = {
    Text = "Nein! Miryam! Ich flehe dich an... bitte... tu das nicht..."
  },
  AvgDialog_52001_Content_60 = {
    Text = "Sprich mir nach: „Die Frommen sollen umarmt werden — denn der Herr erblickt ihre Hingabe.“"
  },
  AvgDialog_52001_Content_61 = {
    Text = "Deborahs Blut spritzt über Miryams Gestalt. Sie erinnert sich, wie sie vor vielen Jahren dasselbe mit ihrem Vater auf dem Tempelaltar getan hat."
  },
  AvgDialog_52001_Content_62 = {
    Text = "Abschied ist doch nur ein Vorspiel zu einem größeren Wiedersehen, nicht wahr, mein Herr?"
  },
  AvgDialog_52001_Content_63 = {
    Text = "Sie starrt gebannt auf Deborahs Unterleib, während ihre Klinge ansetzt, den letzten Strich des Diagramms zu vollenden."
  },
  AvgDialog_52001_Content_64 = {
    Text = "Nun denn, Deborah. Sprich. ‚Die sehnenden Seelen...'"
  },
  AvgDialog_52001_Content_65 = {
    Text = "Miryams Hand grub sich in ihren Bauch, rührte um, riss"
  },
  AvgDialog_52001_Content_66 = {
    Text = "Deborahs heisere Stimme kratzt vor Qual. Ihre blutunterlaufenen Augen fliegen im Wahnsinn auf und starren direkt in ihre eigenen Eingeweide."
  },
  AvgDialog_52001_Content_67 = {
    Text = "„... soll erhört werden — denn der Herr hört ihre Gebete.“"
  },
  AvgDialog_52001_Content_68 = {
    Text = "Miryam reißt etwas heraus. Es sollte schmerzhaft sein, doch Deborah spürt es nicht mehr."
  },
  AvgDialog_52001_Content_69 = {
    Text = "Ihr Geist ist taub geworden; ihre Gefühle und Sinne haben sie verlassen."
  },
  AvgDialog_52001_Content_7 = {
    Text = "Sieh mich an, Deborah. Sieh mir in die Augen."
  },
  AvgDialog_52001_Content_70 = {
    Text = "Sie sieht verschwommen, wie Miryam eine blutige Masse aus ihrem offenen Unterleib zieht."
  },
  AvgDialog_52001_Content_71 = {
    Text = "Sa... Sa..."
  },
  AvgDialog_52001_Content_72 = {
    Text = "Sara. Miryam hatte ihr gesagt, es sei der Name ihrer jüngeren Schwester."
  },
  AvgDialog_52001_Content_73 = {
    Text = "Sie und Nord hatten sich darauf geeinigt, ihre Tochter so zu nennen, doch sie bekam nie die Gelegenheit, es Miryam zu sagen."
  },
  AvgDialog_52001_Content_74 = {
    Text = "<Italic:Nenn sie Sara...> Deborahs Lippen bewegen sich, doch sie kann ihre Stimme nicht mehr finden."
  },
  AvgDialog_52001_Content_75 = {
    Text = "„Herr, mögen unsere Hymnen das abgrundtiefe Dunkel durchdringen, auf dass wir mit Dir emporsteigen — in die ewige Leere, wo Stille und Wahnsinn als eines herrschen.“"
  },
  AvgDialog_52001_Content_76 = {
    Text = "Miryam küsst zärtlich ihr Patenkind, ihre Lippen vom Blut des Säuglings befleckt. Als sie Deborahs Augen schließt, tropft Blut aus ihrem Mundwinkel."
  },
  AvgDialog_52001_Content_77 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_52001_Content_8 = {
    Text = "Ich weiß, dass du Angst hast. Ich habe viele Gläubige zittern sehen, wenn sie das Ende dieses Lebens erreichten."
  },
  AvgDialog_52001_Content_9 = {
    Text = "Aber keine Sorge. Du bist einer der höchsten Menschen im Göttlichen Reich; alles, was du ertragen hast, wird dir im Göttlichen Reich vergolten."
  },
  AvgDialog_52002_Content_1 = {
    Text = "Die Sterne stehen günstig. Des Königs Heiliger Embryo wurde in das Heilige Kind eingepflanzt. Bald wird der König in diese Welt zurückkehren."
  },
  AvgDialog_52002_Content_10 = {
    Text = "Inmitten des ohrenbetäubenden Chors der Fischmenschen hebt Miryam das Baby mit beiden Händen empor."
  },
  AvgDialog_52002_Content_11 = {
    Text = "Anstelle ihres Herzens strahlt der Heilige Embryo ein reines, weißes Leuchten unter den Sternen aus."
  },
  AvgDialog_52002_Content_12 = {Text = "Waaahhh—"},
  AvgDialog_52002_Content_13 = {
    Text = "Stille fällt ein. Der blutbedeckte Säugling, der sich in den Ruinen windet, stößt seinen ersten, verspäteten Schrei aus."
  },
  AvgDialog_52002_Content_14 = {
    Text = "Die Sterne lauschen schweigend jenem orakelhaften Schrei. Ein einzelner Stern fällt und zieht eine traurige Spur über den Nachthimmel."
  },
  AvgDialog_52002_Content_15 = {
    Text = "—Eine weitere Geschichte der Sterne steht kurz bevor."
  },
  AvgDialog_52002_Content_2 = {
    Text = "Der König wird seine tugendhaften Untertanen beschützen, das Göttliche Reich herbeiführen!"
  },
  AvgDialog_52002_Content_3 = {
    Text = "Gottes Reich! Gottes Reich!"
  },
  AvgDialog_52002_Content_4 = {
    Text = "Die Fischmenschen jubeln und tanzen in einem Rausch des Wahnsinns. Miryam steht in der Mitte, Sternenlicht erhellt ihr Gesicht, das von Blut und Tränen gezeichnet ist."
  },
  AvgDialog_52002_Content_5 = {
    Text = "Das Wort unseres Herrn wird sich über die Welt verbreiten. Hohepriesterin, gebt dieser Herde einen Namen."
  },
  AvgDialog_52002_Content_6 = {
    Text = "Kalte, brennende Augen wenden sich langsam. Miryam mustert ihre Soldaten, ihre Untertanen. Sie schenkt ihnen das Lächeln einer Priesterin."
  },
  AvgDialog_52002_Content_7 = {
    Text = "Wir sind dem König ins Meer gefolgt. Wir sind aus dem Meer gekommen und bringen das Königreich"
  },
  AvgDialog_52002_Content_8 = {
    Text = "Die Welt wird uns nennen... Seefahrer."
  },
  AvgDialog_52002_Content_9 = {
    Text = "Seefahrer! Seefahrer!!"
  },
  AvgDialog_52003_Content_1 = {
    Text = "Der Herr wird es euch sagen. Nun betet."
  },
  AvgDialog_52003_Content_10 = {
    Text = "Ringsherum fallen Menschen zu Boden. Den Schmerz ertragend, rezitiert Miryam die Gebete vom Papier."
  },
  AvgDialog_52003_Content_11 = {
    Text = "„In dem fernen sonnenlosen Abgrund schlummert die große uralte Seele...“"
  },
  AvgDialog_52003_Content_12 = {
    Text = "Miryam spricht diese Worte in gewöhnlichem Lemurisch, doch während sie spricht, erwachen die Worte zum Leben. Buchstaben verzerren sich wie Tentakel, schwarze Tinte tanzt in der Luft, bis sie sich in eine andere Sprache verwandeln."
  },
  AvgDialog_52003_Content_13 = {
    Text = "Ihre Stimme überlagert und verflicht sich in diesem einen Augenblick. Vokale haken sich an Konsonanten, Endungen verschmelzen mit Anfängen, genau wie jene Symbole. Was aus ihrer Kehle dringt, formt eine komplexe Struktur in einer höheren Dimension, als würde es aus einer unvorstellbaren Raumzeit widerhallen."
  },
  AvgDialog_52003_Content_14 = {
    Text = "„... Sein Wille webt sich wie ein Netz aus Sternen; in der ewigen Leere wartet Er darauf, dass du in Seinen Traum eintrittst...“"
  },
  AvgDialog_52003_Content_15 = {
    Text = "Miryam singt mit all ihrer Kraft weiter."
  },
  AvgDialog_52003_Content_16 = {
    Text = "Während ihre Worte nachhallen und sich unaufhörlich übereinanderschichten, verschwimmt die Realität um sie herum, löst sich auf."
  },
  AvgDialog_52003_Content_17 = {
    Text = "Sie findet sich in einem tiefen Meer versunken wieder. Geschmeidiges Wasser fließt in alle Richtungen, einer Illusion gleichend."
  },
  AvgDialog_52003_Content_18 = {
    Text = "Es schimmert in silbrigem Licht. Leuchtende Sterne sind überall verstreut, treiben dahin, flackern."
  },
  AvgDialog_52003_Content_19 = {
    Text = "Miryam spürt, dass sie gewissermaßen Teil des Sternenbildes geworden ist. Ihr Mottenlicht wird zu einem bestimmten Ort gelockt. Sie blickt dorthin."
  },
  AvgDialog_52003_Content_2 = {
    Text = "Er verlässt den Raum und lässt nur einen Priester und einige Wachen bei den Lehrlingen zurück."
  },
  AvgDialog_52003_Content_20 = {
    Text = "Unzählige Lichtströme wirbeln mit leuchtendem Schaum, einander jagend auf eine ferne, verschwommene Silhouette zu. Eine Silhouette, zusammengesetzt aus einem menschlichen Körper, einem Thron und unzähligen Tentakeln."
  },
  AvgDialog_52003_Content_21 = {
    Text = "Ist das... der Herrscher?"
  },
  AvgDialog_52003_Content_22 = {Text = "Knack—"},
  AvgDialog_52003_Content_23 = {
    Text = "Als ob er von einem Geräusch aufgeschreckt würde, erwacht er von seinem Thron. Mit seinem Erwachen scheint die gesamte Leere für einen Augenblick zu verdunkeln."
  },
  AvgDialog_52003_Content_24 = {
    Text = "Die vage Gestalt eines alten Mannes erscheint hinter ihm."
  },
  AvgDialog_52003_Content_25 = {
    Text = "Du hast ihre Stimme gehört, mein Lord."
  },
  AvgDialog_52003_Content_26 = {
    Text = "Ist sie diejenige, die von den Sternen prophezeit wurde?"
  },
  AvgDialog_52003_Content_27 = {
    Text = "Ja, ich habe es überprüft. Sofern die Sterne sich nicht irren, ist sie... die Zukunft Lemurias."
  },
  AvgDialog_52003_Content_28 = {
    Text = "Ihr glaubt das nicht wirklich."
  },
  AvgDialog_52003_Content_29 = {
    Text = "Genug Talent, aber unzureichende Hingabe. Sie kann Euch nicht wahrhaft dienen, mein Gebieter."
  },
  AvgDialog_52003_Content_3 = {
    Text = "Das Licht im Gebetsraum wird schwächer. Ein geheimnisvolles, schwaches Leuchten beginnt auf der Oberfläche der Statue zu erscheinen."
  },
  AvgDialog_52003_Content_30 = {
    Text = "Sie glaubt nicht an Gebete, an dich oder an die Zukunft von Lemuria. Sie glaubt nur an ihre Familie."
  },
  AvgDialog_52003_Content_31 = {
    Text = "Miryam lebt in der Realität. Eine solche Person kann nicht das Schicksal der Nation tragen."
  },
  AvgDialog_52003_Content_32 = {
    Text = "In der Wahrheit zu leben, statt in der Illusion, das ist Yus Hoffnung."
  },
  AvgDialog_52003_Content_33 = {
    Text = "Ein edler Wunsch, mein Gebieter. Doch in Lemuria geboren, hat jeder von uns seine eigenen Pflichten zu erfüllen."
  },
  AvgDialog_52003_Content_34 = {
    Text = "Sie hat keine Wahl. Ich habe keine Wahl. Und Ihr, mein Gebieter... habt ebenfalls keine Wahl."
  },
  AvgDialog_52003_Content_35 = {
    Text = "...Langweilig. Ich wünsche jetzt zu ruhen."
  },
  AvgDialog_52003_Content_36 = {
    Text = "Er winkt mit der Hand. Der Älteste verneigt sich vor ihm und verschwindet."
  },
  AvgDialog_52003_Content_37 = {
    Text = "Bevor er in seine Träume zurückkehrt, blickt der Junge auf die Millionen von Lichtern und die Seelen, die sie ihm widmen. Ein flüchtiger Seufzer löst sich in der unermesslichen Leere auf, ungehört, unbeantwortet."
  },
  AvgDialog_52003_Content_38 = {Text = "Autsch!!"},
  AvgDialog_52003_Content_39 = {
    Text = "Dann folgt ein atemberaubendes Gefühl des Fallens, gefolgt von einem stechenden Schmerz."
  },
  AvgDialog_52003_Content_4 = {
    Text = "Miryam nimmt das Gebetsblatt vor sich auf."
  },
  AvgDialog_52003_Content_40 = {
    Text = "Der Schmerz hält nicht lange an. Miryam verlässt diesen geistigen Raum. Sie öffnet die Augen und blickt sich verwirrt um."
  },
  AvgDialog_52003_Content_41 = {
    Text = "Diejenigen, die die Gebete nicht lesen oder rezitieren konnten, wurden hinausgeführt. Von den Verbliebenen liegen einige schmerzgeplagt am Boden, während andere mit geschlossenen Augen im Gebet selige Lächeln tragen."
  },
  AvgDialog_52003_Content_42 = {
    Text = "Deborah sitzt neben ihr, ein sanftes Lächeln breitet sich auf ihrem Gesicht aus, als sie langsam die Augen öffnet. Doch ihr Ausdruck verfinstert sich, als sich ihre Blicke mit Miryams treffen."
  },
  AvgDialog_52003_Content_5 = {Text = "Ah..."},
  AvgDialog_52003_Content_6 = {
    Text = "Die Texte auf dem Papier sind in einer Sprache verfasst, die sich vom gewöhnlichen Lemurischen unterscheidet. Übersät mit komplexen Hieroglyphen, besitzt sie mehr Dimensionen als der reale Raum."
  },
  AvgDialog_52003_Content_7 = {
    Text = "Miryam fragt sich, ob diese seltsamen Glyphen von uralten Inschriften stammen oder gar aus einer anderen Welt. Doch ihre Bedeutung dringt beim Lesen von selbst in ihren Geist ein."
  },
  AvgDialog_52003_Content_8 = {
    Text = "Unzählige Schriften fluten in Miryams Gehirn. Als sich ihre Bedeutungen in überwältigender Weite entfalten, gerät ihr zerbrechlicher Verstand an den Rand des Zusammenbruchs."
  },
  AvgDialog_52003_Content_9 = {
    Text = "<Shake:Mein Kopf... es tut weh...>"
  },
  AvgDialog_52004_Content_1 = {
    Text = "Solange du an den König glaubst, wird der König auf deinen Glauben reagieren..."
  },
  AvgDialog_52004_Content_10 = {
    Text = "Möge Seine Einsicht Unheil voraussehen,\nMöge Seine Weisheit Sein Volk leiten."
  },
  AvgDialog_52004_Content_11 = {
    Text = "„Möge dein scharfer Blick Unheil erkennen,\nMöge deine Weisheit dein Volk führen.!“"
  },
  AvgDialog_52004_Content_12 = {
    Text = "Der Sturm legte sich, das Wasser war ruhig;\nDas Erdbeben hörte auf, die Erde war friedlich"
  },
  AvgDialog_52004_Content_13 = {
    Text = "Mögen alle Katastrophen in Seinen stillen Träumen vergehen,\nMöge das Göttliche Reich unter Seinem Schutz anbrechen."
  },
  AvgDialog_52004_Content_14 = {
    Text = "„Mögen alle Katastrophen in Seinen stillen Träumen vergehen!“"
  },
  AvgDialog_52004_Content_15 = {
    Text = "„Möge das Göttliche Reich anbrechen, \nunter Seinem Schutz...“"
  },
  AvgDialog_52004_Content_16 = {Text = "Boom..."},
  AvgDialog_52004_Content_17 = {
    Text = "Mehrere gewaltige Tentakel strecken sich aus dem Boden unter dem Tempel hervor, begleitet von dröhnenden Echos."
  },
  AvgDialog_52004_Content_18 = {
    Text = "Es ist unser Herr! Das Wunder unseres Herrn hat sich offenbart!!!"
  },
  AvgDialog_52004_Content_19 = {
    Text = "Anhänger heben ihre Arme und jubeln in Ekstase."
  },
  AvgDialog_52004_Content_2 = {
    Text = "So, sag mir, glaubst du an den König? Bist du bereit, alles dem König zu geben?"
  },
  AvgDialog_52004_Content_20 = {
    Text = "Die Tentakel schwanken sanft im Wind und Regen, und jeder in Lemuria glaubt fest daran, dass diese großen lemurischen Gottheiten die Macht besitzen, allen Katastrophen zu widerstehen."
  },
  AvgDialog_52004_Content_21 = {
    Text = "Unser Herr, Tulu—"
  },
  AvgDialog_52004_Content_22 = {
    Text = "Mein Herr, Tulu!! Tulu!!!"
  },
  AvgDialog_52004_Content_23 = {
    Text = "Sie dreht sich um, blickt in das Innere des Tempels und kniet nieder."
  },
  AvgDialog_52004_Content_24 = {
    Text = "Doch niemand kann sehen, dass in ihren Augen keine Spur der Erwartungen oder Würde einer Hohepriesterin liegt, nur Verwirrung."
  },
  AvgDialog_52004_Content_25 = {
    Text = "Höre den Ruf deiner Anhänger. Bringe uns das göttliche Reich."
  },
  AvgDialog_52004_Content_26 = {
    Text = "Bring uns das Göttliche Reich!"
  },
  AvgDialog_52004_Content_27 = {
    Text = "Mein Herr! Göttliches Reich! Hahaha... Es kommt näher!"
  },
  AvgDialog_52004_Content_28 = {
    Text = "Begleitet von Schreien des Wahnsinns beginnen die Tentakel zu tanzen. Die heitere Aura der Tiefsee strömt von ihnen aus und dringt in die Sinne jedes Lemuriers ein."
  },
  AvgDialog_52004_Content_29 = {Text = "Boom—"},
  AvgDialog_52004_Content_3 = {
    Text = "Ich glaube an den König, Euer Gnaden! Ich bin bereit, dem König alles zu opfern!"
  },
  AvgDialog_52004_Content_30 = {
    Text = "Im grollenden Donner verstummen die Jubelrufe. Blitze zerreißen den Himmel und erhellen Lemurias einsames Land."
  },
  AvgDialog_52004_Content_31 = {
    Text = "In diesem Moment des Jubels erstarren die Bewegungen der Gläubigen. Sie verharren in ihrem höchsten Lobpreis und Glauben an den König, für immer gefangen im Bernstein ihrer grenzenlosen Visionen und Sehnsüchte nach der Zukunft."
  },
  AvgDialog_52004_Content_32 = {
    Text = "Im heftigen Regen fallen die Menschen von Lemuria in einen tiefen Schlaf."
  },
  AvgDialog_52004_Content_4 = {
    Text = "Ich bin der loyalste Anhänger des Königs!"
  },
  AvgDialog_52004_Content_5 = {
    Text = "Ja! Euer Gnaden, ja!"
  },
  AvgDialog_52004_Content_6 = {
    Text = "Dann jetzt, begleite mich im Gesang des Namens des Königs—"
  },
  AvgDialog_52004_Content_7 = {
    Text = "Sie überblickt alle auf dem Platz."
  },
  AvgDialog_52004_Content_8 = {
    Text = "Im tobenden Sturm knien alle nieder, breiten ihre Arme aus und blicken in Richtung des Throns im Tempel."
  },
  AvgDialog_52004_Content_9 = {
    Text = "Unter dem gestirnten Firmament, auf einer einsamen Insel in der Tiefsee, beten wir mit Hingabe zu unserem Herrn:"
  },
  AvgDialog_52005_Content_1 = {
    Text = "Ja, Vater... wir werden uns im Göttlichen Reich wiedersehen! Unsere Familie wird gemeinsam im Göttlichen Reich leben..."
  },
  AvgDialog_52005_Content_10 = {
    Text = "Das Reich der Götter naht, Vater. Bald werden wir als Familie wieder vereint sein..."
  },
  AvgDialog_52005_Content_11 = {Text = "Zack—"},
  AvgDialog_52005_Content_12 = {
    Text = "Der Dolch dringt tief in Enos' Brust. Ein Schrei brennender Qual bricht hervor. Sein Blut spritzt unkontrolliert und befleckt Miryams rechte Wange."
  },
  AvgDialog_52005_Content_13 = {
    Text = "Miryams Augen weiten sich, während sie sich auf die Wunden konzentriert, wo der Dolch auf das Fleisch trifft, als würde sie ein Meisterwerk betrachten."
  },
  AvgDialog_52005_Content_14 = {
    Text = "Über die Haut schneidend, die Adern durchbohrend, die Knochen trennend. Enos' Schreie hören nie auf, wie ein sterbendes Tier, das zerrissen wird."
  },
  AvgDialog_52005_Content_15 = {
    Text = "Blut schreit mit verzerrtem Brüllen. Blutrote Stacheln mit aufwallender Gewalt. Hervorquellend durchbohren sie Miryams Gesicht und Haut, bevor sie sich in ihre Eingeweide bohren."
  },
  AvgDialog_52005_Content_17 = {
    Text = "„Gläubiger des Herrn, öffne dein Herz und empfange den Herrn...“"
  },
  AvgDialog_52005_Content_18 = {
    Text = "Blut und Tränen waschen über Miryams verzerrtes Gesicht. Gebete murmelnd bewegt sie ihre Hände schneller und schneller."
  },
  AvgDialog_52005_Content_19 = {
    Text = "Als der Dolch innehält, sind die Siegel des Glücks und der Hoffnung bereits in Enos' Körper geritzt, inmitten seines zitternden Fleisches."
  },
  AvgDialog_52005_Content_2 = {
    Text = "Sie wischt sich die Tränen ab und steht langsam auf. Ihre Hand greift nach dem Dolch neben dem Bett."
  },
  AvgDialog_52005_Content_20 = {
    Text = "„Den Frommen wird der Herr Gnade schenken...“"
  },
  AvgDialog_52005_Content_21 = {
    Text = "<Big:„Den Sehnenden wird der Herr gewähren...\">"
  },
  AvgDialog_52005_Content_22 = {
    Text = "Sie hebt das Becken mit dem heiligen Blut empor und gießt es in die siegelartigen Wunden auf Enos' Körper."
  },
  AvgDialog_52005_Content_23 = {
    Text = "In dem Moment, als das heilige Blut diese Siegel berührt, scheint es Lebenskraft zu gewinnen. Wie eine Schlange auf Enos' Körper wirbelnd, scheint sich ein Gefühl der Erregung beim Spüren der Wärme seiner Beute durch seine mäandernden Spuren auszubreiten."
  },
  AvgDialog_52005_Content_24 = {
    Text = "Ohne Miryams Führung zu benötigen, folgen sie der Wärmequelle und dringen durch die Wunden in Enos' Körper ein."
  },
  AvgDialog_52005_Content_25 = {
    Text = "Während das Blut hineinfließt, werden Enos' Laute unerträglich intensiv, während seine Wunden sich mit sichtbarer Geschwindigkeit schließen."
  },
  AvgDialog_52005_Content_26 = {
    Text = "Gleichzeitig beginnen seine Züge zu degenerieren; seine Augen werden riesig und quellen hervor, seine Lippen werden schleimig, und sein Kopf wird flach und länglich."
  },
  AvgDialog_52005_Content_27 = {
    Text = "Ein kiemenartiges Organ erscheint an seinem Hals. Glitschige Schuppen ersetzen sein Haar und wachsen an verschiedenen Stellen seines Körpers."
  },
  AvgDialog_52005_Content_28 = {
    Text = "Er stöhnt noch immer vor Schmerz, doch seine Laute verwandeln sich allmählich in Kreischen, erfüllt von der feuchten, stickigen Luft salzigen Wassers..."
  },
  AvgDialog_52005_Content_29 = {
    Text = "Ich habe es getan, Vater... Ich habe dich nicht enttäuscht, oder?"
  },
  AvgDialog_52005_Content_3 = {
    Text = "Die Klinge des Dolches biegt sich in einem bizarren Bogen, eingraviert mit kunstvollen Hieroglyphen, die eine verwirrende Ähnlichkeit mit jenen in Gebeten aufweisen."
  },
  AvgDialog_52005_Content_30 = {
    Text = "Das Zischen verstummt. Das halb Fisch, halb Mensch gewordene Monster starrt sie ausdruckslos an. Seine riesigen Augen quellen blass hervor, sein Verstand aufgelöst."
  },
  AvgDialog_52005_Content_31 = {
    Text = "Miryam nähert sich dem Steinaltar und streichelt das Monster. Der dichte Fischgeruch füllt ihre Nase, die Haut unter ihren Händen klebrig und glitschig."
  },
  AvgDialog_52005_Content_32 = {
    Text = "Dieser Geruch und dieses Gefühl ekelten sie einst an. Doch jetzt findet sie sie tröstlicher als je zuvor."
  },
  AvgDialog_52005_Content_33 = {
    Text = "Ich liebe wirklich Fisch. Wenn wir uns wieder im Göttlichen Reich treffen, werde ich jeden Tag den Fisch essen, den du kochst..."
  },
  AvgDialog_52005_Content_34 = {
    Text = "Warte auf mich, Vater."
  },
  AvgDialog_52005_Content_35 = {
    Text = "Sie beugt sich zu der Kreatur hinunter und küsst ihre Wange. Schleimig, feucht, unverkennbar warm."
  },
  AvgDialog_52005_Content_4 = {
    Text = "Neben dem Dolch, in einer steinernen Schüssel, begannen die göttlichen Blutströme, sanft Wellen zu schlagen, das Kerzenlicht reflektierte einen bizarren rot-grünen Glanz"
  },
  AvgDialog_52005_Content_5 = {
    Text = "Schweres Delirium hat Enos den Großteil seines Bewusstseins geraubt. Er betrachtet Miryam mit Neugier, wie ein Neugeborenes, das die Welt zum ersten Mal erblickt."
  },
  AvgDialog_52005_Content_6 = {
    Text = "Miryam, du bist jetzt ein Priester... Hast du den König gefragt? Hat der König dir gesagt, wann Gottes Reich in Lemuria ankommen wird?"
  },
  AvgDialog_52005_Content_7 = {
    Text = "Ja, ich habe um Seine Führung gebetet... Er hat verkündet, dass es bald sein wird, sehr bald..."
  },
  AvgDialog_52005_Content_8 = {
    Text = "Ein schwaches, blasses Lächeln formt sich inmitten der verschlungenen Tränenspuren. Sie nähert sich Enos, beugt sich hinunter und berührt seine Wange."
  },
  AvgDialog_52005_Content_9 = {
    Text = "Ich werde dich nicht enttäuschen, Vater."
  },
  AvgDialog_54067_Content_1 = {
    Text = "Rückruf von Lemuria"
  },
  AvgDialog_54067_Content_10 = {
    Text = "Der Lärm kommt von den Fischen, die um sie herumschwärmen, mit einem Ozean der Stille zwischen ihr und den Fischen, ihre Stimme erhebt sich klar"
  },
  AvgDialog_54067_Content_100 = {
    Text = "Der Regen prasselte auf seinen verwelkten Körper, und der Wind blies ihn fast um. An der höchsten Stelle von Lemuria blickte der alte Mann auf die weite Insel."
  },
  AvgDialog_54067_Content_101 = {
    Text = "Die Schärfe und das Alter in ihren Augen verschwanden. Sie waren klar, belebt und neugierig, wie ein Neugeborenes, das aufmerksam auf das vernarbte Land starrt."
  },
  AvgDialog_54067_Content_102 = {
    Text = "\"Hehehe... Lemuria, was für ein schöner Ort.\""
  },
  AvgDialog_54067_Content_103 = {
    Text = "\"Was denkst du jetzt, Mein Lord?\""
  },
  AvgDialog_54067_Content_104 = {
    Text = "\"Du hast immer gesagt, du hättest kein Interesse daran, Lemuria zu retten, fühlst dich nur müde. Doch um Lemuria willen hast du dich auf den Thron zurückgezogen, in deinen eigenen Träumen gefangen.\""
  },
  AvgDialog_54067_Content_105 = {
    Text = "\"Die Götter sind verschwunden, aber du strebst weiterhin... Ich bin lediglich ein Betrüger. Du bist Lemurias größter Hüter.\""
  },
  AvgDialog_54067_Content_106 = {
    Text = "\"Ein letzter Blick, mein Lord. Ein letzter Blick. <Lemuria>, unser <Zuhause>...\""
  },
  AvgDialog_54067_Content_107 = {
    Text = "Der alte Mann hob den Kopf, sein Blick wanderte von den schlafenden Insulanern hinüber zum aufgewühlten Meer am Horizont und dann zum unerbittlichen Donner und Regen am Himmel."
  },
  AvgDialog_54067_Content_108 = {
    Text = "Er stand wackelig auf und Wärme schmolz in seinen tiefgründigen Augen. Sein Bart und sein Gewand flatterten im Wind, und seine Augen, nun wieder scharf, durchbohrten den Himmel wie Klingen."
  },
  AvgDialog_54067_Content_109 = {
    Text = "\"Komplizierte Machenschaften, mühsame Missionen, ernste Versprechen - lassen Sie sie alle zur Hölle fahren.\""
  },
  AvgDialog_54067_Content_11 = {
    Text = "\"...Im Namen von Tulu, meinem Meister, schwöre ich:\""
  },
  AvgDialog_54067_Content_110 = {
    Text = "Er warf seinen Stock weg, breitete seine Arme aus und umarmte den Sturm. Er brüllte."
  },
  AvgDialog_54067_Content_111 = {
    Text = "\"Komm, Clades! Komm, niederträchtige Götter!\""
  },
  AvgDialog_54067_Content_112 = {
    Text = "\"Ich bin dein Komplize. Lass uns Lemuria zusammen begraben!\""
  },
  AvgDialog_54067_Content_113 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_54067_Content_114 = {Text = "Boom—"},
  AvgDialog_54067_Content_115 = {
    Text = "Ein gedämpftes Geräusch dringt durch zahlreiche dicke Steinwände und hallt im Gemach des Tempels wider."
  },
  AvgDialog_54067_Content_116 = {
    Text = "Tulu sitzt auf dem Thron, das Kinn in eine Hand gestützt, die Augenlider schwer vor Erschöpfung."
  },
  AvgDialog_54067_Content_117 = {
    Text = "Die Lemurianer sind in ewigen Schlummer gefallen. Er hat all seine Kraft aufgebraucht, um ihnen einen schönen Traum zu schenken, ein Trugbild seines Versprechens."
  },
  AvgDialog_54067_Content_118 = {
    Text = "„„Der Sturm von Limoria wird sich legen. Der Abgrund von Limoria wird verschwinden.\"„"
  },
  AvgDialog_54067_Content_119 = {
    Text = "„Der König soll sein gütiges Volk beschirmen und das Göttliche Reich hervorbringen.“"
  },
  AvgDialog_54067_Content_12 = {
    Text = "\"Ich bin ein Diener von Lemuria. Ich bin ein Gehilfe des Königs.\""
  },
  AvgDialog_54067_Content_120 = {
    Text = "\"Wie ironisch. Ist dies dein Wille, 'Gott von Lemuria'?\""
  },
  AvgDialog_54067_Content_121 = {
    Text = "Er hebt den Kopf. Sein Blick durchdringt die Dachplatten, den prasselnden Regen und die sich vereinenden Wolken, bis er den tiefen Sternenhimmel und den tiefen Traum der Sternbilder erreicht."
  },
  AvgDialog_54067_Content_122 = {
    Text = "\"Du bist schon lange weg... Du hast dich nie um Lemuria gekümmert, oder?\""
  },
  AvgDialog_54067_Content_123 = {
    Text = "\"Auch du wirst von einem höheren Willen verfolgt, gejagt und verlassen. Wie Yu bist du eine herrenlose verlorene Seele.\""
  },
  AvgDialog_54067_Content_124 = {
    Text = "\"Die Lemurianer verehren grausame Götter und schwache Könige. Göttliches Reich... Haha, es ist so langweilig.\""
  },
  AvgDialog_54067_Content_125 = {
    Text = "\"Es tut mir leid. Aber diesmal fühle ich mich wirklich erschöpft.\""
  },
  AvgDialog_54067_Content_126 = {
    Text = "Er lehnte sich auf dem Thron zurück, eine Hand stützte sein Kinn und schlief tief."
  },
  AvgDialog_54067_Content_127 = {
    Text = "Er und seine Leute traten in denselben Traum ein. Dort war Lemuria in Sonnenschein gehüllt und voller Lachen."
  },
  AvgDialog_54067_Content_128 = {
    Text = "Er brachte das lang ersehnte Reich der Götter nach Lemuria. Er brachte die lang ersehnten Lügen nach Lemuria."
  },
  AvgDialog_54067_Content_129 = {
    Text = "Er verabschiedete sich mit Lügen von seiner Heimat, das war sein letzter Akt der Macht und des Mitgefühls als König von Lemuria."
  },
  AvgDialog_54067_Content_13 = {
    Text = "\"Ich werde die Menschen von Lemuria leiten. Ich werde auf die Stimme meines Herrschafts hören und den Befehl meines Herrschafts befolgen.\""
  },
  AvgDialog_54067_Content_130 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_54067_Content_131 = {Text = "Knack—"},
  AvgDialog_54067_Content_132 = {
    Text = "Schutt fällt von der Statue. Die einst große, stille Statue ist jetzt in Trümmern."
  },
  AvgDialog_54067_Content_133 = {
    Text = "„Vater, schau... das sind die Tränen des Königs. Unser Herr trauert um Lemuria.“"
  },
  AvgDialog_54067_Content_134 = {
    Text = "In ihren Armen blinzelte ein Murloc mit seinen großen Augen und blickte verwirrt umher."
  },
  AvgDialog_54067_Content_135 = {
    Text = "Sie konnte Enos nicht finden, also wurde jeder Murloc zu Enos."
  },
  AvgDialog_54067_Content_136 = {
    Text = "Der Klang des strömenden Regens durchdrang die Wände und wurde lauter. Der schwere Gestank der Murlocs erfüllte den Raum. Sie streichelte es sanft."
  },
  AvgDialog_54067_Content_137 = {
    Text = "\"Lehrer, der König... es scheint, als hätten sie alle aufgegeben.\""
  },
  AvgDialog_54067_Content_138 = {
    Text = "\"Ich... werde nicht aufgeben... Ich kann Lemuria retten und zurückbringen. Das hat mir der König gesagt.\""
  },
  AvgDialog_54067_Content_139 = {
    Text = "\"Die Mutter ist tot, die Schwester ist tot, der Vater... ist auch tot.\""
  },
  AvgDialog_54067_Content_14 = {
    Text = "\"Ich werde mich mit allen Gläubigen zusammenschließen, um das Göttliche Reich willkommen zu heißen.\""
  },
  AvgDialog_54067_Content_140 = {
    Text = "\"Ich habe Angst, Miryam. Ich fürchte, dass alles, was wir getan haben, bedeutungslos war...\""
  },
  AvgDialog_54067_Content_141 = {
    Text = "\"So viele Katastrophen, und doch fürchtete sich mein Vater, ein gewöhnlicher Mann, nie oder gab auf.\""
  },
  AvgDialog_54067_Content_142 = {
    Text = "\"\"Wir sind die Hochpriester von Lemuria, und wir werden niemals aufgeben... Das hat mir Vater beigebracht.\""
  },
  AvgDialog_54067_Content_143 = {
    Text = "Sie lächelte sanft und flüsterte Trost spendende Worte. Tränen liefen herunter und vermischten sich mit ihren ungewissen Worten, tropften auf die Schuppen des Meermanns und reflektierten ein schwaches Licht."
  },
  AvgDialog_54067_Content_144 = {
    Text = "Boom Boom Boom—"
  },
  AvgDialog_54067_Content_145 = {
    Text = "Der Boden bebte gewaltsam unter deinen Füßen. Die stabilen Säulen des Tempels kämpften ums Überleben, und die Tafeln darüber zerfielen allmählich und zerbrachen auf dem Boden."
  },
  AvgDialog_54067_Content_146 = {
    Text = "In dem gewalttätigen Beben zerbröckeln die Überreste der Statue. Die Geräusche des Sturms und des Erdbebens trommeln gegen Miryams Trommelfelle."
  },
  AvgDialog_54067_Content_147 = {
    Text = "Sie schloss die Augen, kniete sich vor die zerbrochene Statue und nahm die Hand der kleinen Miryam."
  },
  AvgDialog_54067_Content_148 = {
    Text = "\"Höre auf meinen Herrn, widme dich meinem Herrn, preise meinen Herrn...\""
  },
  AvgDialog_54067_Content_149 = {
    Text = "\"Alle, die leiden, mein Herr wird zurückzahlen. \nAlle Sünde, mein Herr wird bestrafen...\""
  },
  AvgDialog_54067_Content_15 = {Text = "Boom—"},
  AvgDialog_54067_Content_150 = {
    Text = "Das Zittern hat nicht aufgehört, und das Licht scheint sich zu dimmen. Eine tiefblaue Wand erhebt sich aus dem fernen Ozean und reicht bis zum Himmel—"
  },
  AvgDialog_54067_Content_151 = {
    Text = "Der Ozean erhob sich wie ein wachender Riese und schritt auf Lemuria zu."
  },
  AvgDialog_54067_Content_152 = {
    Text = "Vor dem Ozean ist dieses glorreiche Königreich so klein und zerbrechlich wie ein verwelkter Blatt."
  },
  AvgDialog_54067_Content_153 = {
    Text = "\"Den Gläubigen wird mein Herr Gnade erweisen.\""
  },
  AvgDialog_54067_Content_154 = {
    Text = "\"Allen, die es wünschen, wird mein Herr gewähren... wird gewähren...\""
  },
  AvgDialog_54067_Content_155 = {
    Text = "Ein wütender Hurrikan schlägt auf den zerbrechlichen Tempel ein, hebt die schweren Tafeln und robusten Fundamente."
  },
  AvgDialog_54067_Content_156 = {
    Text = "Das verbleibende Licht wurde fast vollständig vom aufrechten Ozean blockiert. In der düsteren, ruinösen Einöde hielt sie den Meermann fest in ihren Armen."
  },
  AvgDialog_54067_Content_157 = {
    Text = "Der Atem des Todes aus den Tiefen des Ozeans umgibt sie. Ihre Augen sind mit Tränen gefüllt."
  },
  AvgDialog_54067_Content_158 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_54067_Content_159 = {
    Text = "\"<Mein Herr>... mein Glaube ist bei dir, bis zum Ende der Sterne...\""
  },
  AvgDialog_54067_Content_16 = {
    Text = "Ein Blitz durchzuckte den Himmel von Lemuria."
  },
  AvgDialog_54067_Content_160 = {
    Text = "\"Du hast mich nicht angelogen, das Göttliche Reich wird ankommen, richtig, mein Herr?\""
  },
  AvgDialog_54067_Content_161 = {
    Text = "Zum letzten Mal sah sie auf, blickte verzweifelt dorthin, wo einst die Statue des Königs stand."
  },
  AvgDialog_54067_Content_162 = {
    Text = "Es gibt keine Statuen, noch einen König."
  },
  AvgDialog_54067_Content_163 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_54067_Content_164 = {
    Text = "<Big:Boom ——>"
  },
  AvgDialog_54067_Content_165 = {
    Text = "Der Ozean kam vor dem Verwelkten Blatt."
  },
  AvgDialog_54067_Content_166 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_54067_Content_167 = {
    Text = "Im Jahr 3 des alten Kalenders sank Lemuria in Aequor und ließ keine Überlebenden zurück."
  },
  AvgDialog_54067_Content_17 = {
    Text = "Der laute Lärm ließ die Menge anfangen, sich zu beruhigen."
  },
  AvgDialog_54067_Content_18 = {
    Text = "Calamity... Beginnt das Unheil von neuem?"
  },
  AvgDialog_54067_Content_19 = {
    Text = "Hochpriester... Ist das... die drohende Katastrophe?"
  },
  AvgDialog_54067_Content_2 = {
    Text = "Der heulende Sturm treibt den strömenden Regen und durchnässt die Menschen auf dem Platz."
  },
  AvgDialog_54067_Content_20 = {
    Text = "Katastrophen hören nie auf. Lemuria schläft an ihrer Seite."
  },
  AvgDialog_54067_Content_21 = {
    Text = "Aber Lemuria hat immer schon existiert, oder nicht?"
  },
  AvgDialog_54067_Content_22 = {
    Text = "Das ist richtig... Das ist richtig..."
  },
  AvgDialog_54067_Content_23 = {
    Text = "Hochpriester, wann wird das Reich Gottes... ankommen?"
  },
  AvgDialog_54067_Content_24 = {
    Text = "Fast da, mein Freund."
  },
  AvgDialog_54067_Content_25 = {Text = "So bald?!"},
  AvgDialog_54067_Content_26 = {
    Text = "Ja, sehr bald..."
  },
  AvgDialog_54067_Content_27 = {
    Text = "Miryam verlässt den Schutz der Wachen und nähert sich dem Altar."
  },
  AvgDialog_54067_Content_28 = {
    Text = "Zahlreiche Hände strecken sich aus, Gläubige drängen sich zu ihr, um den Segen des Lemuria-Priesters zu suchen."
  },
  AvgDialog_54067_Content_29 = {
    Text = "Sie blickte umher, ihre Augen ruhig und lächelnd, doch dieser Blick schüchterte die lauten Anhänger schnell ein."
  },
  AvgDialog_54067_Content_3 = {
    Text = "Die Menschen haben so einen starken Regen lange nicht mehr gesehen, aber ihre Schreie übertönen dennoch das Donnern der Insel."
  },
  AvgDialog_54067_Content_30 = {
    Text = "Im Lärm des Sturms streckte sie die Hand aus und berührte die Stirn des Gläubigen."
  },
  AvgDialog_54067_Content_31 = {
    Text = "Der Gläubige faltete die Hände vor der Brust und kniete nieder."
  },
  AvgDialog_54067_Content_32 = {
    Text = "Solange du an den König glaubst, wird der König auf deinen Glauben reagieren..."
  },
  AvgDialog_54067_Content_33 = {
    Text = "So, sag mir, glaubst du an den König? Bist du bereit, alles dem König zu geben?"
  },
  AvgDialog_54067_Content_34 = {
    Text = "Ich glaube an den König, Euer Gnaden! Ich bin bereit, dem König alles zu opfern!"
  },
  AvgDialog_54067_Content_35 = {
    Text = "Ich bin der loyalste Anhänger des Königs!"
  },
  AvgDialog_54067_Content_36 = {
    Text = "Ja! Euer Gnaden, ja!"
  },
  AvgDialog_54067_Content_37 = {
    Text = "Dann jetzt, begleite mich im Gesang des Namens des Königs—"
  },
  AvgDialog_54067_Content_38 = {
    Text = "Sie überblickt alle auf dem Platz."
  },
  AvgDialog_54067_Content_39 = {
    Text = "Im tobenden Sturm knien alle nieder, breiten ihre Arme aus und blicken in Richtung des Throns im Tempel."
  },
  AvgDialog_54067_Content_4 = {
    Text = "Hochpriester! Der Hochpriester hat uns das Orakel des Königs gebracht!"
  },
  AvgDialog_54067_Content_40 = {
    Text = "Unter dem sternenklaren Himmel über dem alten Aequor bete ich aufrichtig für meinen Herrn:"
  },
  AvgDialog_54067_Content_41 = {
    Text = "Möge Seine Einsicht Unheil voraussehen,\nMöge Seine Weisheit Sein Volk leiten."
  },
  AvgDialog_54067_Content_42 = {
    Text = "\"Möge dein scharfer Verstand das Unheil voraussehen,\nMöge deine Weisheit das Volk führen!\""
  },
  AvgDialog_54067_Content_43 = {
    Text = "Der Sturm lässt nach, die Gewässer beruhigen sich;\nDie Erschütterungen hören auf, das Land ist in Frieden."
  },
  AvgDialog_54067_Content_44 = {
    Text = "Mögen alle Katastrophen in Seinen stillen Träumen vergehen,\nMöge das Göttliche Reich unter Seinem Schutz anbrechen."
  },
  AvgDialog_54067_Content_45 = {
    Text = "„Mögen alle Katastrophen in Seinen stillen Träumen vergehen!“"
  },
  AvgDialog_54067_Content_46 = {
    Text = "„Möge das Göttliche Reich anbrechen, \nunter Seinem Schutz...“"
  },
  AvgDialog_54067_Content_47 = {Text = "Boom..."},
  AvgDialog_54067_Content_48 = {
    Text = "Mehrere gewaltige Tentakel strecken sich aus dem Boden unter dem Tempel hervor, begleitet von dröhnenden Echos."
  },
  AvgDialog_54067_Content_49 = {
    Text = "Es ist unser Herr! Das Wunder unseres Herrn hat sich offenbart!!!"
  },
  AvgDialog_54067_Content_5 = {
    Text = "Gelobt sei mein Herr! Gelobt sei der Hohe Priester!"
  },
  AvgDialog_54067_Content_50 = {
    Text = "Anhänger heben ihre Arme und jubeln in Ekstase."
  },
  AvgDialog_54067_Content_51 = {
    Text = "Die Tentakel schwanken sanft im Wind und Regen, und jeder in Lemuria glaubt fest daran, dass diese großen lemurischen Gottheiten die Macht besitzen, allen Katastrophen zu widerstehen."
  },
  AvgDialog_54067_Content_52 = {
    Text = "Unser Herr, Tulu—"
  },
  AvgDialog_54067_Content_53 = {
    Text = "Mein Herr, Tulu!! Tulu!!!"
  },
  AvgDialog_54067_Content_54 = {
    Text = "Sie dreht sich um, blickt in das Innere des Tempels und kniet nieder."
  },
  AvgDialog_54067_Content_55 = {
    Text = "Doch niemand kann sehen, dass in ihren Augen keine Spur der Erwartungen oder Würde einer Hohepriesterin liegt, nur Verwirrung."
  },
  AvgDialog_54067_Content_56 = {
    Text = "Höre den Ruf deiner Anhänger. Bringe uns das göttliche Reich."
  },
  AvgDialog_54067_Content_57 = {
    Text = "Bring uns das Göttliche Reich!"
  },
  AvgDialog_54067_Content_58 = {
    Text = "Mein Herr! Göttliches Reich! Hahaha... Es kommt näher!"
  },
  AvgDialog_54067_Content_59 = {
    Text = "Inmitten wilder Schreie begannen die Tentakel zu tanzen. Die stille Aequor-Aura verbreitete sich von den Tentakeln, fließend vom Tempel zu jedem Zentimeter von Lemuria und drang in die Sinne jedes Lemurischen ein."
  },
  AvgDialog_54067_Content_6 = {
    Text = "Der Hohepriester wird uns ins Reich Gottes führen!"
  },
  AvgDialog_54067_Content_60 = {Text = "Boom—"},
  AvgDialog_54067_Content_61 = {
    Text = "Im grollenden Donner verstummen die Jubelrufe. Blitze zerreißen den Himmel und erhellen Lemurias einsames Land."
  },
  AvgDialog_54067_Content_62 = {
    Text = "In diesem Moment des Jubels erstarren die Bewegungen der Gläubigen. Sie verharren in ihrem höchsten Lobpreis und Glauben an den König, für immer gefangen im Bernstein ihrer grenzenlosen Visionen und Sehnsüchte nach der Zukunft."
  },
  AvgDialog_54067_Content_63 = {
    Text = "Im heftigen Regen fallen die Menschen von Lemuria in einen tiefen Schlaf."
  },
  AvgDialog_54067_Content_64 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_54067_Content_65 = {
    Text = "Der Klang der Schiebetür, die sich schließt, wurde lang und schwer."
  },
  AvgDialog_54067_Content_66 = {
    Text = "Der starke Geruch von Fisch erfüllt den gesamten Raum. Der einst geräumige Gebetsraum fühlt sich jetzt unerträglich eng an."
  },
  AvgDialog_54067_Content_67 = {
    Text = "Alle Murlocs wurden aus dem Pool gezogen und auf den Boden des Gebetssaals gelegt."
  },
  AvgDialog_54067_Content_68 = {
    Text = "Die Wachen hatten keine Ahnung, was der neue Hochpriester vorhatte, und sie würden nie die Gelegenheit bekommen, es herauszufinden."
  },
  AvgDialog_54067_Content_69 = {
    Text = "Miryam ging in die Ecke des Raumes, hockte sich hin und berührte den nächsten Fischmenschen."
  },
  AvgDialog_54067_Content_7 = {
    Text = "Die frenetischen Cheergeschrei strömten wie Wellen zum Altar."
  },
  AvgDialog_54067_Content_70 = {
    Text = "„Vater... bist du das?“"
  },
  AvgDialog_54067_Content_71 = {
    Text = "\"Ich bin Miryam, deine Tochter.\""
  },
  AvgDialog_54067_Content_72 = {
    Text = "\"Wenn du mich hörst, antworte bitte... Vater...\""
  },
  AvgDialog_54067_Content_73 = {
    Text = "\"...Woo...Woo...\""
  },
  AvgDialog_54067_Content_74 = {
    Text = "Die Kiemen des Meerjungmanns öffneten und schlossen sich, seine Lippen bewegten sich auf und ab und gaben ein unverständliches Wimmern von sich, wie gewohnt."
  },
  AvgDialog_54067_Content_75 = {
    Text = "Miryam bewegt sich zur zweiten, hockt sich hin und berührt sie."
  },
  AvgDialog_54067_Content_76 = {
    Text = "\"Vater, ich bin der Hohe Priester von Lemuria geworden und habe sogar die Träume übertroffen, die du einst für mich hattest...\""
  },
  AvgDialog_54067_Content_77 = {
    Text = "\"Ich habe dich nicht enttäuscht, Vater... Öffne deine Augen und sieh mich an...\""
  },
  AvgDialog_54067_Content_78 = {
    Text = "Die großen Augen des Murlocs wanderten ziellos in diesem unbekannten Ort umher und zeigten kein Interesse am Hohepriester vor ihm."
  },
  AvgDialog_54067_Content_79 = {
    Text = "Sie ging auf die dritte zu."
  },
  AvgDialog_54067_Content_8 = {
    Text = "Die drängende Menge erinnerte Miryam an Fische, die mit weit geöffneten Augen in einem Teich starren."
  },
  AvgDialog_54067_Content_80 = {
    Text = "\"Ich sah den König, den wir verehren... aber der König sagte mir, dass Lemuria zum Untergang verurteilt ist.\""
  },
  AvgDialog_54067_Content_81 = {
    Text = "„Der König sagte, ich könnte Lemuria retten, und ich könnte es zurückbringen...“"
  },
  AvgDialog_54067_Content_82 = {
    Text = "\"Ich kann den Worten des Königs nicht glauben. Aber wenn das wahr ist, kann ich nur akzeptieren, dass wir in Lügen gelebt haben. Alles, was wir getan haben, die Dinge, die ich dir angetan habe... diese Dinge sind bedeutungslos.\""
  },
  AvgDialog_54067_Content_83 = {
    Text = "\"Ich weiß nicht, ich weiß nicht... Vater, was soll ich tun?\""
  },
  AvgDialog_54067_Content_84 = {
    Text = "\"Öffne deine Augen und schau mich an, Vater... Sprich mit mir und berühre meinen Kopf, nur einmal...\""
  },
  AvgDialog_54067_Content_85 = {
    Text = "Der Murloc starrte es mit leerem Blick an, als würde er eine schwankende lila Alge betrachten."
  },
  AvgDialog_54067_Content_86 = {
    Text = "Miryam bewegt sich zur nächsten, dann zur übernächsten... Sie hockt sich hin, berührt und küsst jede von ihnen."
  },
  AvgDialog_54067_Content_87 = {
    Text = "Die Lehrerin gab ihr eine Aufgabe, der König gab ihr Hoffnung. Aber derjenige, der ihr Verwirrung und Schmerz hätte zuhören können, derjenige, der sie durch Streicheln ihres Kopfes hätte trösten können, ist längst verschwunden."
  },
  AvgDialog_54067_Content_88 = {
    Text = "Sie beugte sich zu jedem Einzelnen, flüsterte ihnen zu und suchte unter ihnen."
  },
  AvgDialog_54067_Content_89 = {
    Text = "Lebt mein Vater noch? Kann der überlebende Meerjungmann noch als mein Vater betrachtet werden?"
  },
  AvgDialog_54067_Content_9 = {
    Text = "Es fühlte sich an, als ob man in Aequor versinkt, Wasser füllt ihre Sinne. Bilder verschwammen und Geräusche verwandelten sich in Chaos."
  },
  AvgDialog_54067_Content_90 = {
    Text = "Sie weiß es nicht. Es ist ihr egal."
  },
  AvgDialog_54067_Content_91 = {
    Text = "Der Klang des schweren Regens drang durch die Wände. In dem weiten Gebetsraum lagen unzählige Fischmenschen am Boden und zuckten mit ihren Gliedern und Flossen."
  },
  AvgDialog_54067_Content_92 = {
    Text = "Eine lila Figur bewegt sich unter den Murlocs, sucht und erzählt Geschichten."
  },
  AvgDialog_54067_Content_93 = {
    Text = "Eine halb beschädigte Statue sitzt auf einem zerbrochenen Thron und blickt ruhig zu ihr."
  },
  AvgDialog_54067_Content_94 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_54067_Content_95 = {Text = "Boom—"},
  AvgDialog_54067_Content_96 = {
    Text = "Donner grollte über dem Kopf des alten Mannes. Er ignorierte es und stieg die letzte Steinstufe hinauf."
  },
  AvgDialog_54067_Content_97 = {
    Text = "\"Huff... huff...\""
  },
  AvgDialog_54067_Content_98 = {
    Text = "Er ist zu alt, allein diesen Berg zu erklimmen, ist eine so schwierige Aufgabe für ihn."
  },
  AvgDialog_54067_Content_99 = {
    Text = "Er brach auf dem kahlen Gipfel zusammen, rang nach Luft, seine Lungen keuchten wie rostige Windmühlen und gaben ein gealtertes Stöhnen von sich."
  },
  AvgDialog_54802_Content_1 = {Text = "Ah!—"},
  AvgDialog_54802_Content_10 = {
    Text = "Da... da ist..."
  },
  AvgDialog_54802_Content_100 = {
    Text = "Diese vernarbte Hand reichte Horla eine leicht beschädigte, aber immer noch lebhaft rote Rose."
  },
  AvgDialog_54802_Content_101 = {
    Text = "Ein feines Gedicht, Horla... In Zukunft tausche ich meine Blumen gegen deine Gedichte!"
  },
  AvgDialog_54802_Content_11 = {
    Text = "Du stehst am Rand des Gartenplatzes. Sichtbare D-Rifts steigen von unter dem kleinen Gebäude auf und umschließen den offenen Raum in der Mitte des Gartens."
  },
  AvgDialog_54802_Content_12 = {
    Text = "Das ist... unser Garten... nein... Colette, nein..."
  },
  AvgDialog_54802_Content_13 = {
    Text = "Horla senkte den Kopf. Colette trat zu ihr, hob ihr Kinn und lenkte ihren Blick auf die Mitte des Gartens."
  },
  AvgDialog_54802_Content_14 = {
    Text = "Weißt du, Horla... Vor vielen Jahren habe ich beobachtet, wie genau hier das große Feuer begann."
  },
  AvgDialog_54802_Content_15 = {
    Text = "Ich habe diesen Ort in einen Platz verwandelt und hier meine Statue errichtet... Sieh mal, ich verstehe auch Symbolik."
  },
  AvgDialog_54802_Content_16 = {
    Text = "Genau hinschauen. Sieh es klar. Das ist unser Zuhause... Das ist unser Garten. Bald wird alles dort verschwinden."
  },
  AvgDialog_54802_Content_17 = {
    Text = "Mein Leben begann wirklich an dem Tag, an dem du gestorben bist. Heute wird es wieder in Richtung Brillanz bewegen..."
  },
  AvgDialog_54802_Content_18 = {
    Text = "Der schwarze Riss breitet sich schnell aus. Bald ist die gesamte luxuriöse Villa ergriffen."
  },
  AvgDialog_54802_Content_19 = {
    Text = "Garten, Asche, Kritzeleien, Poesie, Erinnerungen, Lachen, Eide... Alles ist in die endlose Dunkelheit gesunken."
  },
  AvgDialog_54802_Content_2 = {
    Text = "Euer Überraschungsangriff hat Colette niedergeschlagen, aber im Moment eurer Annäherung schießen unzählige Blumenranken aus dem Boden um sie herum"
  },
  AvgDialog_54802_Content_20 = {
    Text = "Tick-tack—"
  },
  AvgDialog_54802_Content_21 = {
    Text = "Hä? Was ist mit meinen Augen los...?"
  },
  AvgDialog_54802_Content_22 = {
    Text = "War das... gerade eben Herzschmerz? Warum..."
  },
  AvgDialog_54802_Content_23 = {
    Text = "Eine Träne rutschte Horlas Gesicht hinunter."
  },
  AvgDialog_54802_Content_24 = {
    Text = "Tränen fallen zu Boden, wie Tropfen in einen ruhenden See. Stille Wellen breiten sich aus und streifen jedes blasse Herz in dieser illusorischen Welt."
  },
  AvgDialog_54802_Content_25 = {
    Text = "!! Nein... dieses Gefühl..."
  },
  AvgDialog_54802_Content_26 = {
    Text = "Colette bemerkte die Veränderung in ihren Emotionen. Sie sah überrascht zu Horla neben ihr."
  },
  AvgDialog_54802_Content_27 = {
    Text = "<LightGray:Ist das... die Fähigkeit von Horla, Emotionen zu verbreiten?!>"
  },
  AvgDialog_54802_Content_28 = {
    Text = "<LightGray:Dieser Bereich basiert auf den Gedichten von Horla... Ihre Fähigkeit könnte von Nutzen sein!>"
  },
  AvgDialog_54802_Content_29 = {
    Text = "Du willst mich töten und das Gedicht nutzen, um das Leben zu bekommen, das du dir wünschst... Egal, was du getan hast, ich habe dich nie gehasst, Kolette."
  },
  AvgDialog_54802_Content_3 = {
    Text = "Die Dornen an der Blütenranke durchbohren euren Körper und fesseln euch fest"
  },
  AvgDialog_54802_Content_30 = {
    Text = "Die Colette, die ich einst kannte, war meine beste Freundin. Aber wenn du diesen Ort zerstörst... wird nur die gegenwärtige Colette übrig bleiben."
  },
  AvgDialog_54802_Content_31 = {
    Text = "Ich kann... nicht zulassen, dass die Colette, die ich einst kannte, von dir ausgelöscht wird..."
  },
  AvgDialog_54802_Content_32 = {
    Text = "Sieh dich selbst an, Horla... Was kannst du sonst noch tun, außer Gedichte zu schreiben?"
  },
  AvgDialog_54802_Content_33 = {
    Text = "Du hast recht... Abgesehen vom Dichten bin ich in nichts gut..."
  },
  AvgDialog_54802_Content_34 = {
    Text = "Die Cité ist die Stadt der Blumen und der Poesie, sie ist unsere Heimat... aber hier sind alle Rosen gestorben, Corette"
  },
  AvgDialog_54802_Content_35 = {
    Text = "Diese Rosen sind die, die du mir einmal gegeben hast. Heute gebe ich sie dir zurück."
  },
  AvgDialog_54802_Content_36 = {
    Text = "Sie macht einen Schritt nach vorne."
  },
  AvgDialog_54802_Content_37 = {Text = "Horla!!!"},
  AvgDialog_54802_Content_38 = {
    Text = "Der riesige Rosendornen stach durch ihr Herz"
  },
  AvgDialog_54802_Content_39 = {
    Text = "Ihr Blut floss an den schwarzen Ranken herab"
  },
  AvgDialog_54802_Content_4 = {
    Text = "Du... hast meine Kleidung schmutzig gemacht..."
  },
  AvgDialog_54802_Content_40 = {
    Text = "Schwarze Blumen verwelkten schnell an den Zweigen"
  },
  AvgDialog_54802_Content_41 = {
    Text = "Eine rote Rose, die aus dem Zweig sprießt, entfaltet sich und blüht"
  },
  AvgDialog_54802_Content_42 = {
    Text = "Blut fließt entlang der Ranken, wie die Adern der Blätter, und breitet sich in jede Ecke der Stadt aus."
  },
  AvgDialog_54802_Content_43 = {
    Text = "Dort, wo es vorbeigeht, verschwindet das düstere Schwarz"
  },
  AvgDialog_54802_Content_44 = {
    Text = "Es hat die Farben und Emotionen, die Blumen und Gedichte zurück an Cité gegeben"
  },
  AvgDialog_54802_Content_45 = {
    Text = "Also... so viel Schmerz..."
  },
  AvgDialog_54802_Content_46 = {
    Text = "Herz... fühlt sich an, als wäre es durchbohrt worden..."
  },
  AvgDialog_54802_Content_47 = {
    Text = "Das ist... Mutter! Mutter..."
  },
  AvgDialog_54802_Content_48 = {
    Text = "Kind... mein Kind ist geboren..."
  },
  AvgDialog_54802_Content_49 = {
    Text = "Während sich das Blut ausbreitet, entfalten sich Szenen vor den Augen der Leute."
  },
  AvgDialog_54802_Content_5 = {
    Text = "Weißt du, wie viel dieses Outfit gekostet hat?"
  },
  AvgDialog_54802_Content_50 = {
    Text = "Es ist die Wiedergeburt des Neugeborenen, das Wiegenlied der Mutter und der Abschied der Liebenden."
  },
  AvgDialog_54802_Content_51 = {
    Text = "Das war der kostbarste Moment in eurem Leben."
  },
  AvgDialog_54802_Content_53 = {
    Text = "Die immense Schmerzen, die Horla erduldet hat, breiteten sich über ganz Cité aus und wogen mit ihrem Blut."
  },
  AvgDialog_54802_Content_54 = {
    Text = "Rosendornen durchbohren unzählige Herzen. Blutrote Blumen erblühen in jedem einzelnen."
  },
  AvgDialog_54802_Content_55 = {
    Text = "Das ist... dein Gedicht?"
  },
  AvgDialog_54802_Content_56 = {
    Text = "Tränen wischten ihr sorgfältiges Make-up weg, aber sie kümmerte sich nicht darum und ließ sie unpassende Spuren auf ihrem Gesicht hinterlassen"
  },
  AvgDialog_54802_Content_57 = {
    Text = "Colette konnte sich nicht erinnern, wann ihre Tränen zu fließen begonnen hatten."
  },
  AvgDialog_54802_Content_58 = {
    Text = "—Die vergangenen Szenen entblättern sich klar vor ihr. Zum ersten Mal verstand sie wirklich Horlas Poesie. Sie erkannte endlich, was sie wirklich schätzte."
  },
  AvgDialog_54802_Content_59 = {
    Text = "Es ist nicht nur sie. Alle hier in Cité haben das Gedicht von Horla verstanden"
  },
  AvgDialog_54802_Content_6 = {
    Text = "Colettes Wut verschwand schnell. Sie setzte wieder ihr nobles Lächeln auf"
  },
  AvgDialog_54802_Content_60 = {
    Text = "Machtgelüste schwinden, Gefühle kehren zurück. In diesem Gedicht zerfallen die Grundfesten dieser Welt"
  },
  AvgDialog_54802_Content_61 = {
    Text = "Sie fühlte, wie ihre Macht schwand. Sie spürte die Niederlage nahtreten. Sie beschwor stachelige Klingen und ging auf Horla zu."
  },
  AvgDialog_54802_Content_62 = {
    Text = "\"Colette,\" Sieg... Als der Hund der alten Dame starb und sie mir seinen Namen gab, warst du direkt neben mir."
  },
  AvgDialog_54802_Content_63 = {
    Text = "Ich habe diesen Namen niemals gewechselt. Weil ich nicht mehr verlieren wollte, Horla"
  },
  AvgDialog_54802_Content_64 = {
    Text = "Lady Colette schniefte schmerzlich, taumelte und näherte sich langsam Horla"
  },
  AvgDialog_54802_Content_65 = {
    Text = "Der Bereich verschwindet. Dein Plan ist gescheitert, Colette!"
  },
  AvgDialog_54802_Content_66 = {
    Text = "Selbst wenn du sie jetzt angreifst, wird sich nichts ändern!"
  },
  AvgDialog_54802_Content_67 = {
    Text = "Du kämpfst darum, dich Aurita zu nähern. Dornen und Schmerzen umgeben dich, lassen dich nicht bewegen"
  },
  AvgDialog_54802_Content_68 = {
    Text = "Der Stachel richtet sich in Richtung des Kopfes von Horla."
  },
  AvgDialog_54802_Content_69 = {Text = "Warte!!"},
  AvgDialog_54802_Content_7 = {
    Text = "Es ist alles in Ordnung, es ist alles in Ordnung..."
  },
  AvgDialog_54802_Content_70 = {
    Text = "*Schnapp*—"
  },
  AvgDialog_54802_Content_71 = {
    Text = "Eine Rose wurde geschnitten. Colette nahm sie und reichte sie Horla."
  },
  AvgDialog_54802_Content_72 = {
    Text = "Ein gutes Gedicht, Horla... Ich werde meine Blumen gegen deine Gedichte eintauschen"
  },
  AvgDialog_54802_Content_73 = {Text = "Bang—"},
  AvgDialog_54802_Content_74 = {
    Text = "Vielleicht hat die Auflösung des Bereichs den Gärtner verändert."
  },
  AvgDialog_54802_Content_75 = {
    Text = "Oder vielleicht hat die Transformation des Gärtners dazu geführt, dass sich der Bereich auflöste."
  },
  AvgDialog_54802_Content_76 = {
    Text = "Die Cité in den Gedichten verschwindet allmählich, und die Macht, die Colette unterstützt hat, ist ebenfalls verschwunden."
  },
  AvgDialog_54802_Content_77 = {
    Text = "Ihr Körper verwandelte sich in einen Pool aus schwarzem Schlamm, vermischt mit verstreuten Blütenblättern, und versank vor Horla in den Boden."
  },
  AvgDialog_54802_Content_78 = {
    Text = "Colette, Colette, hast du das Lesen beendet?"
  },
  AvgDialog_54802_Content_79 = {
    Text = "Hmm... Ich habe es zu Ende gelesen... aber ich verstehe es nicht ganz."
  },
  AvgDialog_54802_Content_8 = {
    Text = "Mich in meinem Garten herauszufordern – dazu muss man mutig und töricht zugleich sein."
  },
  AvgDialog_54802_Content_80 = {
    Text = "Ah, ist das so...? Dies ist mein erstes Gedicht. Es ist nicht sehr gut..."
  },
  AvgDialog_54802_Content_81 = {
    Text = "Es liegt nicht an dir, Horla. Ich verstehe die Gedichte von niemandem wirklich."
  },
  AvgDialog_54802_Content_82 = {
    Text = "Ich habe viele Menschen um mich herum gefragt, und sie konnten es auch nicht verstehen."
  },
  AvgDialog_54802_Content_83 = {
    Text = "Ich verstehe es nicht... Was bringt etwas, das niemand begreifen kann?"
  },
  AvgDialog_54802_Content_84 = {
    Text = "Hmm... Ich denke, Poesie besteht nicht nur aus Worten oder Bildern; sie ist wie ein Schlüssel."
  },
  AvgDialog_54802_Content_85 = {
    Text = "Ein... Schlüssel?"
  },
  AvgDialog_54802_Content_86 = {
    Text = "Ja! Das Herz eines Menschen ist wie eine Box, gefüllt mit vielen Emotionen. Diese Box ist verschlossen, und diese Emotionen werden normalerweise darin aufbewahrt, schwer herauszunehmen."
  },
  AvgDialog_54802_Content_87 = {
    Text = "Poesie ist der Schlüssel, um diese Truhe zu öffnen."
  },
  AvgDialog_54802_Content_88 = {
    Text = "Eigentlich muss Poesie nicht verstanden oder sogar gelesen werden."
  },
  AvgDialog_54802_Content_89 = {
    Text = "Alle, ob sie Gedichte lesen oder nicht, werden früher oder später diesen Schlüssel zu einem bestimmten Moment in ihrem Leben finden."
  },
  AvgDialog_54802_Content_9 = {
    Text = "Du hast deine letzte Chance zur Flucht vertan... Bei dieser Feier musst du es mit mir durchstehen."
  },
  AvgDialog_54802_Content_90 = {
    Text = "Du wirst sicher der beste Schlosser werden!"
  },
  AvgDialog_54802_Content_91 = {
    Text = "Lügner... Du hast gerade gesagt, du hast es nicht verstanden."
  },
  AvgDialog_54802_Content_92 = {
    Text = "Ich verstehe nicht, was du sagst, aber ich vertraue dir, Horla."
  },
  AvgDialog_54802_Content_93 = {
    Text = "Dieses Gedicht, \"Die Wohnstätte der Rosen\", ist dein erstes Stück. Ab heute werde ich dir helfen, all deine Gedichte zu schätzen."
  },
  AvgDialog_54802_Content_94 = {
    Text = "Ich werde Nadeln benutzen, um sie zusammenzuhalten, und wenn ich Geld habe, werde ich eine schöne Gedichtsammlung drucken!"
  },
  AvgDialog_54802_Content_95 = {
    Text = "Sie streckte ihre Hand aus, die sie hinter ihrem Rücken gehalten hatte. Die Hände waren von Dornen verwundet, dunkel und rau, völlig unverkennbar als die einer jungen Frau."
  },
  AvgDialog_54802_Content_96 = {
    Text = "Das... das ist..."
  },
  AvgDialog_54802_Content_97 = {
    Text = "Die neuen Adligen sagen, dass Cité eine Stadt der Blumen und der Poesie ist. Ein gutes Gedicht kann dir einen Blumenstrauß mit Rosen einbringen..."
  },
  AvgDialog_54802_Content_98 = {
    Text = "Meine Rosen sind heute aufgeblüht. Nicht viele, und alle wurden verwendet, um die Miete und Pacht zu zahlen."
  },
  AvgDialog_54802_Content_99 = {
    Text = "Aber als sie nicht hingeschaut haben, habe ich heimlich eine Blume behalten..."
  },
  AvgDialog_56163_Content_1 = {
    Text = "Aufgrund der jüngsten abnormalen Bedingungen unter den Erwachenden hat die Schule beschlossen, die Überwachung ihres Status zu verstärken und regelmäßige Kontrollen durchzuführen, um Unfälle zu verhindern."
  },
  AvgDialog_56163_Content_10 = {
    Text = "Du spürst ein Gefühl der Erleichterung, dankbar, dass du dich nicht mit dieser von Wahnsinn verzehrten Frau auseinandersetzen musst."
  },
  AvgDialog_56163_Content_11 = {
    Text = "Doch deine Erfahrung und Intuition aus den Untersuchungen verspürten plötzlich etwas Ungewöhnliches. Du hast angehalten und das Kerzenlicht aufmerksam beobachtet."
  },
  AvgDialog_56163_Content_12 = {
    Text = "Die Schatten, die an der Wand flackern und von dem Kerzenlicht geworfen werden, sind keine bloßen Flammen, sondern sich windende, schlangenartige Silhouetten."
  },
  AvgDialog_56163_Content_13 = {
    Text = "Schlangen-Schatten winden sich um das Kerzenlicht, als ob sie versuchen, die einzige Wärme des Raumes zu ergreifen."
  },
  AvgDialog_56163_Content_14 = {
    Text = "Miryam drehte ihren Kopf, ihr Gesicht errötete mit einer ungewöhnlichen Röte. Ihre Stimme war sanft und fröhlich, als ob sie von den Göttern gesegnet wäre."
  },
  AvgDialog_56163_Content_15 = {
    Text = "Es bist du, Hüter. Bist du hierher gekommen, um dem Ruf des Reiches der Götter zu folgen?"
  },
  AvgDialog_56163_Content_16 = {
    Text = "Ihre blassen, dünnen Glieder waren mit sich wälzenden Schattenschlangen verwoben, aber ihre Hände blieben in einer betenden Haltung, wie die einer gebundenen Nonne, gefangen in einer ewigen Mission."
  },
  AvgDialog_56163_Content_17 = {
    Text = "Dein Gehirn schreit Gefahr, aber es ist zu spät, um sich zurückzuziehen. Der kalte, feuchte Schlangenschatten ist bereits durch die Dunkelheit geschlängelt, windet sich fest um deine Beine und klettert deinen Rücken hinauf."
  },
  AvgDialog_56163_Content_18 = {
    Text = "Dein Körper fühlt sich so warm an..."
  },
  AvgDialog_56163_Content_19 = {
    Text = "Offensichtlich hast du das schwache Kerzenlicht ersetzt und bist zur Hauptquelle der Wärme in diesem Raum geworden."
  },
  AvgDialog_56163_Content_2 = {
    Text = "Um potenziellen Erwachenden-Rampagen zu begegnen, werden Zimmerkontrollen unter inaktiven Ermittlern rotiert. Heute bist du als Wohnheimaufsicht an der Reihe."
  },
  AvgDialog_56163_Content_20 = {
    Text = "Nein, nein, nein, du musst dich irren! Ich habe die Beschwörung des Gottesreichs nicht gehört, ich bin nur hier, um die Räume zu überprüfen!"
  },
  AvgDialog_56163_Content_21 = {
    Text = "Deine frenetische Erklärung ist vergeblich. Der Schattenschlange zieht dich zum Gebetstisch und setzt dich neben Miryam vor die Statue mit zuckenden Tentakeln."
  },
  AvgDialog_56163_Content_22 = {
    Text = "Ich habe seit Ewigkeiten solch Freude und Aufregung nicht mehr gefühlt! Es ist das Göttliche Reich – es hat auf mich reagiert!"
  },
  AvgDialog_56163_Content_23 = {
    Text = "Du möchtest leugnen und die Wahrheit sagen, aber als du ihren glücklichen Ausdruck siehst, hältst du weise deine Worte zurück."
  },
  AvgDialog_56163_Content_24 = {
    Text = "Das Göttliche Reich drängt mich zum Handeln. Ich sollte dieser Anweisung folgen."
  },
  AvgDialog_56163_Content_25 = {
    Text = "Jetzt wurde dieses Dekret dir übermittelt."
  },
  AvgDialog_56163_Content_26 = {
    Text = "Sie dreht ihren Kopf, zitternde Finger streicheln sanft dein Gesicht, halten deine Wangen, als ob sie Trost spenden, als ob sie einladen wollen."
  },
  AvgDialog_56163_Content_27 = {
    Text = "Komm, bete mit mir, gemeinsam werden wir alles für die Fortsetzung des Reichs des Gottes opfern."
  },
  AvgDialog_56163_Content_28 = {
    Text = "Die eisige Berührung des Schattens der Schlange lässt dich vor Kälte zittern, dein Widerstand wird von ihren engen Windungen zerbrochen und zwingt deinen Körper in eine ehrfürchtige Haltung."
  },
  AvgDialog_56163_Content_29 = {
    Text = "Du und der glühende Priester beginnt ein Gebet, um die Götter zu besänftigen."
  },
  AvgDialog_56163_Content_3 = {
    Text = "Nachdem du mehrfach belästigt wurdest, klopfst du nervös an jede Tür und zeichnest jeden normalen Zustand auf."
  },
  AvgDialog_56163_Content_4 = {
    Text = "Schließlich, als ich an einer bestimmten Tür klopfte, blieb nur eine unempfindliche Stille zurück. Dein Herz sank und signalisierte: \"Es ist endlich gekommen.\""
  },
  AvgDialog_56163_Content_5 = {
    Text = "Du schaust auf den Namen „Miryam“ auf dem Türschild, öffnest die Tür mit einem ernsthaften Ausdruck und spähst vorsichtig halb hinaus."
  },
  AvgDialog_56163_Content_6 = {
    Text = "Miryam? Bist du da?"
  },
  AvgDialog_56163_Content_7 = {
    Text = "Im dunklen Raum beleuchtet nur eine flackernde Kerze eine düstere Ecke und wirft Licht auf das Gesicht einer Nonne, die in tiefem frommen Gebet vertieft ist."
  },
  AvgDialog_56163_Content_8 = {
    Text = "Ihr Rücken ist friedlich und gelassen, wie die unzähligen Jahre asketischer Praxis."
  },
  AvgDialog_56163_Content_9 = {
    Text = "So hast du gebetet. Entschuldige die Unterbrechung. Da es dir gut geht, werde ich meine Runde fortsetzen."
  },
  AvgDialog_56308_Content_1 = {
    Text = "So heiß..."
  },
  AvgDialog_56308_Content_10 = {
    Text = "Es ist schwer zu sagen, ob es dazu dient, sich abzulenken, oder aus echtem Interesse. Du siehst dich um."
  },
  AvgDialog_56308_Content_11 = {
    Text = "Immer blühendere Blumen, heißeres Wetter und bezauberndere Architektur und Musik."
  },
  AvgDialog_56308_Content_12 = {
    Text = "Eine Welt, die durch Worte heraufbeschworen wird, in der jeder Ort mit Metaphern und Andeutungen gefüllt ist."
  },
  AvgDialog_56308_Content_13 = {
    Text = "Entschuldigung, Hüter... ich weiß nicht warum... Die Gedichte, die ich heute schreibe, sind immer... immer..."
  },
  AvgDialog_56308_Content_14 = {
    Text = "Emotionen durchziehen den Raum. Dein Hals zuckt leicht."
  },
  AvgDialog_56308_Content_15 = {
    Text = "Du greifst aus und nimmst das Pergament von dem Kopf des Mädchens."
  },
  AvgDialog_56308_Content_16 = {Text = "Autsch!!"},
  AvgDialog_56308_Content_17 = {
    Text = "Das Mädchen, wie ein erschrecktes Kaninchen, sitzt unruhig. Ihr verborgener Körper zitterte, und ihr entblößtes Gesicht errötete bis zu den Ohren."
  },
  AvgDialog_56308_Content_18 = {
    Text = "Horla, ich mag dieses Gedicht."
  },
  AvgDialog_56308_Content_19 = {
    Text = "Aber... aber dieses Gedicht ist noch nicht vollendet..."
  },
  AvgDialog_56308_Content_2 = {
    Text = "Eine plötzliche Unruhe weckt dich auf."
  },
  AvgDialog_56308_Content_20 = {
    Text = "Dann lass es uns gemeinsam vollenden."
  },
  AvgDialog_56308_Content_21 = {
    Text = "Als nächstes, die nächste Zeile... was sollte sie sein..."
  },
  AvgDialog_56308_Content_22 = {
    Text = "Es ist dunkel, und alle Blicke sind verschwunden..."
  },
  AvgDialog_56308_Content_23 = {
    Text = "Die Sonne und die Sterne sind untergegangen..."
  },
  AvgDialog_56308_Content_24 = {
    Text = "......Nur Rosen bleiben zurück, geheim in ihrem Garten versteckt......"
  },
  AvgDialog_56308_Content_25 = {
    Text = "Unsichtbare Worte erscheinen um sie herum, und der im Gedicht beschriebene Garten verblasst."
  },
  AvgDialog_56308_Content_26 = {
    Text = "Horlas sanfte Stimme nähert sich. Du hörst ihren sanften Atem. Du spürst ihre zitternde Wärme."
  },
  AvgDialog_56308_Content_27 = {
    Text = "—Im dunklen Garten hast du das Geheimnis einer Rose entdeckt."
  },
  AvgDialog_56308_Content_3 = {Text = "!!!"},
  AvgDialog_56308_Content_4 = {
    Text = "Habe ich nicht in meinem Wohnheim geschlafen...? Wo ist dieser Ort?"
  },
  AvgDialog_56308_Content_5 = {
    Text = "Ich-Es tut mir leid... Hüter..."
  },
  AvgDialog_56308_Content_6 = {
    Text = "Also bist du es... Kein Wunder."
  },
  AvgDialog_56308_Content_7 = {
    Text = "Die Fähigkeit, Emotionen zu verbreiten, kombiniert mit dem Einfluss des Heiligen Flusses... Was für eine unerwartete Kombination."
  },
  AvgDialog_56308_Content_8 = {
    Text = "Unter Horlas Einfluss haben Sie schließlich die Empfindung erlebt, vom Heiligen Fluss berührt zu werden."
  },
  AvgDialog_56308_Content_9 = {
    Text = "Dieses Mal scheint die Welt innerhalb des Gedichts etwas anders zu sein als zuvor?"
  },
  AvgDialog_57563_Content_1 = {
    Text = "Nachdem ich gerade eine externe Mission abgeschlossen habe, begegne ich auf dem Rückweg einem strömenden Regen und bin am Stadtrand, weit entfernt von der Stadt, gestrandet."
  },
  AvgDialog_57563_Content_10 = {
    Text = "Du schaust auf das vertraute Gesicht vor dir und rufst ihren Namen überrascht, kämpfend und heiser."
  },
  AvgDialog_57563_Content_11 = {
    Text = "Husten... Shi... Lo!"
  },
  AvgDialog_57563_Content_12 = {
    Text = "Das Mädchen vor dir hob leicht die Augenbrauen, aber ihre scharlachroten Augen zeigten keine Spur von Freude beim Wiedersehen mit einer alten Freundin, nur eine tiefe und eisige Kälte."
  },
  AvgDialog_57563_Content_13 = {
    Text = "So wie du denkst, dass du gleich sterben wirst, curlen sich die Lippen des Mädchens leicht, und ihre Hand lässt schließlich deinen Hals los."
  },
  AvgDialog_57563_Content_14 = {
    Text = "Also bist du es. Ich erinnere mich, gesagt zu haben, dass ich dich in Stücke reißen würde, wenn ich dich wieder sehe."
  },
  AvgDialog_57563_Content_15 = {
    Text = "Du fällst zu Boden, hustest so stark, dass du fast deine Lunge herausbekommst, und erst nach einiger Zeit gelingt es dir, dich umzudrehen."
  },
  AvgDialog_57563_Content_16 = {
    Text = "Du würdest nicht, *hüsteln*, denn wir sind... Freunde..."
  },
  AvgDialog_57563_Content_17 = {
    Text = "Als du das Mädchen klar siehst, erstarrst du.\nIhre Kleidung klebt an ihrem Körper und tropft vor Regen. Der Geruch von Blut mischt sich mit der feuchten Luft. Ihr blasses Gesicht zeigt einen schwachen fiebrigen Schimmer."
  },
  AvgDialog_57563_Content_18 = {
    Text = "Die massiven Fesseln verschmolzen mit ihrem Körper, und ihre von Ketten verbundenen Gliedmaßen waren von unheilvollem Schwarz und Rot durchzogen."
  },
  AvgDialog_57563_Content_19 = {
    Text = "Du erinnerst dich an die Begegnung auf dem Schneeberg und schluckst instinktiv nervös."
  },
  AvgDialog_57563_Content_2 = {
    Text = "Glücklicherweise erinnerst du dich trotz des Unglücks an den Standort einer nahegelegenen verlassenen Fabrik, die ausreicht, um einem unglücklichen Reisenden wie dir vorübergehenden Schutz zu bieten."
  },
  AvgDialog_57563_Content_20 = {
    Text = "Es scheint, dass du mich missverstanden hast. Verwechsele mich nicht mit diesem Schwächling."
  },
  AvgDialog_57563_Content_21 = {
    Text = "Als du den Mordwillen in ihren Augen erneut aufflammend sahst, drückst du schnell als Freund Besorgnis aus."
  },
  AvgDialog_57563_Content_22 = {
    Text = "Nein, nein, nein! Solange du es bist, bist du mein Freund!"
  },
  AvgDialog_57563_Content_23 = {
    Text = "Kümmere dich nicht darum. Bist du verletzt?"
  },
  AvgDialog_57563_Content_24 = {
    Text = "Ihr Gesicht offenbarte plötzlich einen seltsamen und komplexen Ausdruck – kalt, verärgert und mit einem Hauch von Verwirrung."
  },
  AvgDialog_57563_Content_25 = {
    Text = "Die Verletzung ist nicht schwer, aber sie scheint vergiftet zu sein. Der Körper... fühlt sich seltsam an."
  },
  AvgDialog_57563_Content_26 = {
    Text = "Ein flüchtiger Moment des Zweifels und der Zerbrechlichkeit verging, aber Brutalität erfüllte bald wieder ihre Augen."
  },
  AvgDialog_57563_Content_27 = {
    Text = "Wenn ich die Person fange, die mich vergiftet hat, werde ich ihre Innereien Stück für Stück zerquetschen."
  },
  AvgDialog_57563_Content_28 = {
    Text = "Gerade als du im Begriff bist, den Einfluss des Heiligen Flusses zu erklären, tust du schnell so, als wäre nichts passiert, und nickst zustimmend."
  },
  AvgDialog_57563_Content_29 = {Text = "Hmm..."},
  AvgDialog_57563_Content_3 = {
    Text = "Während du dem schweren Regen hörst, der auf das Fabrikdach niederschlägt, sitzt du untätig in der Ecke."
  },
  AvgDialog_57563_Content_30 = {
    Text = "Aber, ich habe nichts wie Freunde."
  },
  AvgDialog_57563_Content_31 = {
    Text = "Deine Kopfhaut zieht sich sofort zusammen."
  },
  AvgDialog_57563_Content_32 = {
    Text = "Aber deine Aura ist rein, frei von Bosheit und ohne den Geruch von Lügen."
  },
  AvgDialog_57563_Content_33 = {
    Text = "Das Mädchen sah dich erneut an, scheinbar vertraute sie dir widerwillig."
  },
  AvgDialog_57563_Content_34 = {
    Text = "Sie setzte sich an die Wand und nahm deinen ursprünglichen Platz ein."
  },
  AvgDialog_57563_Content_35 = {
    Text = "Da du mir zuvor geholfen hast, werde ich mich eine Weile ausruhen und du passt auf mich auf."
  },
  AvgDialog_57563_Content_36 = {
    Text = "Wenn ich dich in Bewegung fangen kann..."
  },
  AvgDialog_57563_Content_37 = {
    Text = "Du schüttelst sofort den Kopf und siehst loyal und ergeben aus."
  },
  AvgDialog_57563_Content_38 = {
    Text = "Die Augen des Mädchens schlossen sich langsam, ihr nasser Körper krümmte sich instinktiv wie ein obdachloses Tier in der regnerischen Nacht."
  },
  AvgDialog_57563_Content_39 = {Text = "Warte!"},
  AvgDialog_57563_Content_4 = {
    Text = "Ich möchte mich wirklich auf das große Bett im Schlafsaal legen..."
  },
  AvgDialog_57563_Content_40 = {
    Text = "Diese heftigen roten Augen starren dich ungeduldig an."
  },
  AvgDialog_57563_Content_41 = {
    Text = "Du ziehst deine Jacke aus und legst sie sanft über das Mädchen."
  },
  AvgDialog_57563_Content_42 = {
    Text = "Sie sah nach unten und weigerte sich nicht."
  },
  AvgDialog_57563_Content_43 = {
    Text = "Das müde Mädchen umklammert den Saum deiner Kleider im Schlaf, der tiefsitzende Hass und die Tötungsabsicht auf ihrer Stirn lösen sich vorübergehend auf."
  },
  AvgDialog_57563_Content_44 = {
    Text = "Der Regen draußen lässt allmählich nach, plätschert auf das Dach."
  },
  AvgDialog_57563_Content_45 = {
    Text = "In der ruhigen Fabrik bleibt nur das überlappende Geräusch deiner Atemzüge."
  },
  AvgDialog_57563_Content_46 = {
    Text = "Während der langen regnerischen Nacht ruhen zwei einsame Reisende."
  },
  AvgDialog_57563_Content_5 = {
    Text = "Gerade dabei, die Augen für ein Nickerchen zu schließen, hörst du plötzlich ein zähneknirschendes Quietschen.\nEs ist das Geräusch der rostigen Fabriktür, die sich öffnet."
  },
  AvgDialog_57563_Content_6 = {
    Text = "Ungewiss über die Identität des Fremden, hältst du vorsichtig den Atem an und steigst langsam auf."
  },
  AvgDialog_57563_Content_7 = {
    Text = "Bevor du untersuchen konntest, durchbrach ein scharfer Pfeifton plötzlich die leere Stille um dich herum."
  },
  AvgDialog_57563_Content_8 = {
    Text = "Du rollst schnell zur Seite, um einem massiven Kettenball auszuweichen, der mit einem lauten Knall auf den Boden schlägt, wo du gestanden hast, wodurch ein tiefes Krater entsteht."
  },
  AvgDialog_57563_Content_9 = {
    Text = "Bevor du die Neuankömmlinge klar erkennen konntest, griff eine mächtige Kraft voller Tötungsabsicht sofort nach deinem Hals."
  },
  AvgDialog_57592_Content_1 = {
    Text = "Als Ryker heute dem 17. Studenten am Spieltisch die Hosen gewann, brach jemand schließlich in Tränen aus und meldete dies dem Hüter."
  },
  AvgDialog_57592_Content_10 = {
    Text = "Sei nicht so grausam. Ich höre auf, nur eine letzte Wette mit mir—nur eine—um das kostbarste Ding..."
  },
  AvgDialog_57592_Content_11 = {
    Text = "Rykers hundeähnlicher Schwanz wedelt glücklich, seine nasse Nase schnüffelt ständig an dir, als würde sie nach dem schmackhaftesten Teil ihrer Beute suchen, wobei sie unbeabsichtigt gegen dein Ohrläppchen streicht."
  },
  AvgDialog_57592_Content_12 = {
    Text = "Worauf wetten?"
  },
  AvgDialog_57592_Content_13 = {
    Text = "Du erstarrst wie eine unnachgiebige Stahlplatte und beäugst den übermäßig aufgeregten Tiermenschen misstrauisch."
  },
  AvgDialog_57592_Content_14 = {
    Text = "Niemand an der Schule hat es bisher geschafft, Ryker am Spieltisch zu schlagen; die angebliche Wette ist nicht anders als ein offenes Raubüberfall. Du beginnst, Verhandlungsstrategien zu entwerfen und dich auf das Feilschen vorzubereiten."
  },
  AvgDialog_57592_Content_15 = {
    Text = "Worauf wetten?"
  },
  AvgDialog_57592_Content_16 = {
    Text = "Das scheint eine Frage zu sein, über die man nachdenken sollte. Ryker umkreist dich und murmelt etwas Unhörbares."
  },
  AvgDialog_57592_Content_17 = {
    Text = "In der Tat, du bist besonders. Ich kann es riechen; dein Duft ist erfreulich. Wenn ich nur einen Bissen nehmen könnte, wenn ich nur kosten könnte..."
  },
  AvgDialog_57592_Content_18 = {Text = "Was?"},
  AvgDialog_57592_Content_19 = {
    Text = "Bald verweilt warmer Atem an deinem Ohr. Das gierige Tier fletscht die Zähne und offenbart seine tiefsten Begierden."
  },
  AvgDialog_57592_Content_2 = {
    Text = "Ryker! Stoppe sofort deine illegalen Glücksspielaktivitäten!"
  },
  AvgDialog_57592_Content_20 = {
    Text = "Eine Wette... um einen Kuss von dir."
  },
  AvgDialog_57592_Content_3 = {
    Text = "Du durchbrichst die Tür und schreist wie ein gerechter Polizist."
  },
  AvgDialog_57592_Content_4 = {
    Text = "Der große Spieltisch in der Mitte des Raumes ist von benommenen, zitternden Studenten umgeben, einige mit Tränen des Schmerzes im Gesicht, als hätte ein Dämon das Wichtigste mit einer Klaue geraubt."
  },
  AvgDialog_57592_Content_5 = {
    Text = "Langweilig, langweilig! Solche konservativen Wetten werden deiner Leidenschaft nicht gerecht!"
  },
  AvgDialog_57592_Content_6 = {
    Text = "Das arrogante Ungeheuer schlägt auf den Tisch, mit einem Berg von seltsamen Trophäen hinter ihm, eindeutig ohne Reue."
  },
  AvgDialog_57592_Content_7 = {
    Text = "Ah, du bist es, mein Watson. Hast du auch Lust, eine Runde zu spielen?"
  },
  AvgDialog_57592_Content_8 = {
    Text = "Der normalerweise faule und entspannte Beastman hat einen ungewöhnlichen Eifer in seinen Augen. Als er dich sieht, leuchten seine Augen auf, und er kommt eifrig näher, während seine pelzigen Ohren aufgeregt aufstellen."
  },
  AvgDialog_57592_Content_9 = {
    Text = "Bevor die Schulbehörden kommen, um diesen Ort zu versiegeln, rate ich dir, aufzuhören."
  },
  AvgDialog_57723_Content_1 = {
    Text = "In letzter Zeit schwirrten auf dem Campus übernatürliche Gerüchte umher, dass in leeren Musikräumen um Mitternacht Musik von selbst spielte."
  },
  AvgDialog_57723_Content_10 = {
    Text = "Die schwarz-weißen Klaviertasten ziehen dich wie ein Strudel an."
  },
  AvgDialog_57723_Content_11 = {
    Text = "So schön..."
  },
  AvgDialog_57723_Content_12 = {
    Text = "Du legst deine Hände auf die Tasten, gibst deinem Instinkt nach und beginnst zu spielen mit deinen mittelmäßigen musikalischen Fähigkeiten."
  },
  AvgDialog_57723_Content_13 = {
    Text = "Zunächst stolpernd, nimmt die Melodie allmählich Gestalt an, während die Musik wie ein sanfter Strom fließt und den leeren Konzertsaal erfüllt."
  },
  AvgDialog_57723_Content_14 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_57723_Content_15 = {
    Text = "Etwas in der Luft scheint stagnierend zu werden. Du bleibst gefasst, spielst weiterhin mit Ernsthaftigkeit, dein Gesichtsausdruck ernst, wie ein Pilger der Musik."
  },
  AvgDialog_57723_Content_16 = {
    Text = "Endlich kam ein Seufzer aus dem Nichts, als ob er vom Horizont käme, doch direkt neben deinem Ohr."
  },
  AvgDialog_57723_Content_17 = {
    Text = "Du hast die falsche Note gespielt."
  },
  AvgDialog_57723_Content_18 = {
    Text = "Eine unsichtbare Hand bedeckt deine Hand, ein intimer Griff, der gerade barely in Kontakt bleibt."
  },
  AvgDialog_57723_Content_19 = {
    Text = "Du spürst eine sanfte Kraft, die deine Finger führt und jeden abrupten Fehler korrigiert."
  },
  AvgDialog_57723_Content_2 = {
    Text = "Nach mehrfachen Ermittlungen wurde niemand gefunden. Diejenigen, die das Musikzimmer betreten haben, um der Musik zuzuhören, zeigten unterschiedliche Grade von Wahnsinn."
  },
  AvgDialog_57723_Content_20 = {
    Text = "Ein schwindelerregender Schauer breitet sich vom Trommelfell aus und vermittelt die volle Schönheit der nahezu perfekten Darbietung."
  },
  AvgDialog_57723_Content_21 = {
    Text = "Du hältst unbewusst den Atem an, fasziniert vom turbulenten Fluss der Musik, sinkst in Wellen, die manchmal so hart wie Stahl und manchmal so weich wie Baumwolle sind."
  },
  AvgDialog_57723_Content_22 = {
    Text = "Ein bisschen... kann nicht klar sehen..."
  },
  AvgDialog_57723_Content_23 = {
    Text = "Du konzentrierst dich auf die Notenblätter, während dein peripheres Sehen den schwindelerregenden Tanz der Tasten erfasst, und dein Oberkörper beugt sich unbewusst nach vorne."
  },
  AvgDialog_57723_Content_24 = {
    Text = "Blutflecken sickern langsam durch die Notenblätter. Du möchtest es wirklich klarer sehen und in deinem Gedächtnis festhalten."
  },
  AvgDialog_57723_Content_25 = {
    Text = "Dein Kopf bewegt sich Schritt für Schritt näher zur Partitur."
  },
  AvgDialog_57723_Content_26 = {
    Text = "Seufzte erneut und eine unwiderstehliche Kraft ergriff deine Hände."
  },
  AvgDialog_57723_Content_27 = {Text = "Halt."},
  AvgDialog_57723_Content_28 = {
    Text = "Ein disharmonischer Klang schlägt auf die Tasten und verstummt abrupt die gesamte Musik."
  },
  AvgDialog_57723_Content_29 = {
    Text = "Du bist durchnässt von Schweiß und atmest schwer."
  },
  AvgDialog_57723_Content_3 = {
    Text = "Als du siehst, dass sich bei Nacht keine Lehrer oder Schüler im Unterrichtsgebäude aufhalten, kommst du schließlich in diesem geheimnisvollen Musikraum an und trägst die letzte Hoffnung."
  },
  AvgDialog_57723_Content_30 = {
    Text = "Irgendwann offenbarte die Hand, die deine Hände bedeckte, ihre Form."
  },
  AvgDialog_57723_Content_31 = {
    Text = "Ein Paar Hände, umhüllt von makellosen weißen Handschuhen, schlank und elegant."
  },
  AvgDialog_57723_Content_32 = {
    Text = "Du drehst dich um und siehst den Besitzer dieser Hände – Hameln, ein flüchtiger Ausdruck der Hilflosigkeit huscht über sein kaltes Gesicht."
  },
  AvgDialog_57723_Content_33 = {
    Text = "Es bist du!"
  },
  AvgDialog_57723_Content_34 = {
    Text = "Du versuchst, aufzustehen, wirst jedoch von einem schwindelerregenden Schwindel gestoppt."
  },
  AvgDialog_57723_Content_35 = {
    Text = "Die Hände, gekleidet in weiße Handschuhe, ruhen sanft auf deinen Schultern und ziehen eine Flöte aus dem Nichts hervor."
  },
  AvgDialog_57723_Content_36 = {
    Text = "Das Aussehen der Flöte ist undeutlich, doch unerklärlich beruhigend."
  },
  AvgDialog_57723_Content_37 = {
    Text = "Bitte ruhen Sie sich aus; ich werde an Ihrer Seite bleiben."
  },
  AvgDialog_57723_Content_38 = {
    Text = "Hameln hob die Flöte an die Lippen, die ätherische Melodie wickelte sich um dich wie eine sanfte Umarmung."
  },
  AvgDialog_57723_Content_39 = {
    Text = "Unkontrollierbare Schläfrigkeit überwältigt dich. Du legst deinen Kopf auf das Klavier und sinkst in einen tiefen und süßen Schlaf."
  },
  AvgDialog_57723_Content_4 = {
    Text = "Hinter der schweren schalldichten Tür ist alles still, wie es in der Nacht sein sollte; nur das leise Echo deiner eigenen Schritte ist zu hören."
  },
  AvgDialog_57723_Content_40 = {
    Text = "Hameln sieht dein schlafendes Gesicht an. Ein leises Murmeln schwebt in der stillen Nacht, von niemandem gehört."
  },
  AvgDialog_57723_Content_41 = {
    Text = "Für immer, für immer..."
  },
  AvgDialog_57723_Content_5 = {
    Text = "Seltsam, es gibt keine Anzeichen von Auflösung..."
  },
  AvgDialog_57723_Content_6 = {
    Text = "Nachdem einer fruchtlosen Suche, findest du dich am Flügel in der Mitte des Klassenzimmers und nimmst beinahe instinktiv einige Notenblätter vom Ständer."
  },
  AvgDialog_57723_Content_7 = {
    Text = "Hat jemand seine Partitur fallen lassen?"
  },
  AvgDialog_57723_Content_8 = {
    Text = "Das scheint eine unvollendete Partitur zu sein, aber die bestehende Melodie ist bereits ein Meisterwerk, das die Geschichte erstaunen und zu einem zeitlosen Werk werden könnte."
  },
  AvgDialog_57723_Content_9 = {
    Text = "Deine Augen sind fest auf jede Note fixiert, fast obsessiv, und du setzt dich."
  },
  AvgDialog_57804_Content_1 = {
    Text = "Hameln's Stimme ist zu hören"
  },
  AvgDialog_57804_Content_2 = {
    Text = "Offensichtlich außer Kontrolle, ich werde zuerst seine Fusion reduzieren!"
  },
  AvgDialog_57813_Content_1 = {
    Text = "Keeper... zzzz... entdeckte, dass \"Puppe\" sich befreite... Schwarzer Pool... du... Gefahr... zzzz"
  },
  AvgDialog_57813_Content_10 = {
    Text = "Du standst langsam auf und tratst zurück, kämpfend darum, eine Frage zu stellen."
  },
  AvgDialog_57813_Content_11 = {
    Text = "Bist du gekommen, um mich zu sehen, weil du eine neue Zukunft gesehen hast?"
  },
  AvgDialog_57813_Content_12 = {
    Text = "\"Puppe\" beobachtet dich, folgt deinen Schritten, als würde sie in einer harmonischen Routine tanzen"
  },
  AvgDialog_57813_Content_13 = {
    Text = "Die Zukunft kann nicht verändert werden, aber in letzter Zeit hatte ich einen plötzlichen Inspirationsschub und herausgefunden, wie ich am schnellsten ans Ziel komme."
  },
  AvgDialog_57813_Content_14 = {
    Text = "...Was tun?"
  },
  AvgDialog_57813_Content_15 = {
    Text = "Du erkundigst dich kooperativ nach ihrem unvollendeten Satz, als du plötzlich gegen eine solide Wand hinter dir stößt."
  },
  AvgDialog_57813_Content_16 = {
    Text = "Natürlich... um die größte Variable in Mythag zu eliminieren."
  },
  AvgDialog_57813_Content_17 = {
    Text = "Bevor sie zu Ende spricht, rollst du ohne zu zögern zur Seite, Arme schützend über deinem Kopf, und stürzt dich auf das Fenster in der Wand."
  },
  AvgDialog_57813_Content_18 = {
    Text = "Das Glas zerbrach mit einem krachen, unzählige glitzernde Fragmente spiegelten deine und „Puppe“ Gesicht wider, du fielst in einer standardisierten gepufferten Haltung zu Boden, ignorierend die Schnitte auf deiner Haut, und begannst verzweifelt zu rennen"
  },
  AvgDialog_57813_Content_19 = {Text = "Campus."},
  AvgDialog_57813_Content_2 = {
    Text = "Die plötzliche Silberkommunikation flackert und verblasst und offenbart eine Krise, die dir das Haar zu Berge stehen lässt."
  },
  AvgDialog_57813_Content_20 = {Text = "Korridor."},
  AvgDialog_57813_Content_21 = {
    Text = "Unterirdischer Durchgang."
  },
  AvgDialog_57813_Content_22 = {
    Text = "Wie oft hast du dem Tod nur knapp entkommen, gegen Wände geknallt und an Ecken gefallen, aber nie gewagt, aufzuhören, während du um dein Leben flehst und schwer atmest?"
  },
  AvgDialog_57813_Content_23 = {
    Text = "Du bist so ein guter Schüler. Lass den Lehrer dir die beste Kampfausbildung geben."
  },
  AvgDialog_57813_Content_24 = {
    Text = "Unverkleidetes Lachen, überfließend vor Wahnsinn, folgt dir wie ein Geist. Der mörderische Wille durchdringt fast deinen Rücken, während du erneut knapp ausweichst und das Klirren der Sense in die Metallrohre hörst."
  },
  AvgDialog_57813_Content_25 = {
    Text = "Unbekannte Dämpfe entweichen aus den Rohren und füllen den engen Raum mit kochendem Dampf, wobei deine Sicht beeinträchtigt wird."
  },
  AvgDialog_57813_Content_26 = {
    Text = "Du spürst etwas und versteckst dich sofort in einem Labor, dem Verlauf des Rohres folgend."
  },
  AvgDialog_57813_Content_27 = {
    Text = "Bald brachen die versiegelten Türen des Labors mit mehreren lauten Krachen auf, und vertraute Stimmen näherten sich allmählich."
  },
  AvgDialog_57813_Content_28 = {
    Text = "Lass uns unser Versteckspiel hier beenden. So weit zu kommen, verdient zehn zusätzliche Punkte für deine Endnote."
  },
  AvgDialog_57813_Content_29 = {
    Text = "\"Puppe\"'s Sense kratzte über den Boden und erzeugte ein scharfes Geräusch."
  },
  AvgDialog_57813_Content_3 = {
    Text = "\"Puppe\" hat sich aus der Gefangenschaft des Schwarzen Beckens befreit?"
  },
  AvgDialog_57813_Content_30 = {
    Text = "Fürchte dich nicht. Wenn ich dich selbst zerstöre, werde ich deinen Körper in einem Eiskasten als wertvolles Andenken bewahren."
  },
  AvgDialog_57813_Content_31 = {
    Text = "Du wirst meine kostbarste und herausragendste Forschung sein. Wir haben noch so viel Zeit zusammen..."
  },
  AvgDialog_57813_Content_32 = {
    Text = "Durch den nebligen Rauch erhaschte sie einen Blick auf ein Stück Kleidung neben der großen Maschine in der Mitte des Raumes, und ihre Lippen krümmten sich zu einem schwachen Lächeln."
  },
  AvgDialog_57813_Content_33 = {
    Text = "Wo bist du, kleiner Welpe? Lass mich dich zweimal bellen hören."
  },
  AvgDialog_57813_Content_34 = {
    Text = "Das ohrenbetäubende metallische Kreischen verschwand plötzlich, und das Labor fiel in eine tödliche Stille."
  },
  AvgDialog_57813_Content_35 = {
    Text = "Die Zeit gefror fast während der qualvollen Wartezeit; ihre Stimme erschien schließlich wieder, so leise wie ein Flüstern."
  },
  AvgDialog_57813_Content_36 = {
    Text = "Ich habe dich gefunden."
  },
  AvgDialog_57813_Content_38 = {
    Text = "Die Sense, die das Instrument mit tödlicher Kraft trifft, schlägt nur eine leichte Schuluniform um."
  },
  AvgDialog_57813_Content_39 = {
    Text = "In dem Moment, als die Sense im Gerät feststeckte, drücktest du den roten Knopf, den du fest in der Hand hieltst. Die Ladeluken des Ofenmechanismus öffneten sich schnell und zeigten die höllische, geschmolzene Szene im Inneren."
  },
  AvgDialog_57813_Content_4 = {
    Text = "Du erinnerst dich an diese Augen, die dich mit Wahnsinn anstarren. Getrieben von Intuition bereitest du dich vor, die Tür zu öffnen und schnell zu den anderen Erwachten zurückzukehren."
  },
  AvgDialog_57813_Content_40 = {
    Text = "Du bist hinter \"Puppe\" erschienen und hast sie mit all deiner Kraft in Richtung des Ofens gestoßen."
  },
  AvgDialog_57813_Content_41 = {
    Text = "Von den Flammen verschlungen, wandte sich die \"Puppe\" um, ihre Augen zeigten eine vage Wertschätzung und ein seltsames Lächeln."
  },
  AvgDialog_57813_Content_42 = {
    Text = "Mit einem schlechten Gefühl senkst du deinen Kopf und siehst, wie die andere Hand der Puppe dein letztes Kleidungsstück greift."
  },
  AvgDialog_57813_Content_43 = {
    Text = "Deine Hände stützen instinktiv den Rahmen des Instruments, die Restwärme brennt sofort die Haut deiner Handflächen. Ein zischendes Geräusch begleitet den heftigen Schmerz, während du die Zähne zusammenbeißt und der gewaltigen inneren Kraft widerstehst."
  },
  AvgDialog_57813_Content_44 = {
    Text = "Der Umriss des Puppenkörpers verschwamm im hellen Feuerschein, wobei nur ihre Augen, heller als die Flammen, dich weiterhin anstarrten."
  },
  AvgDialog_57813_Content_45 = {
    Text = "Mythags Fakultät und Studenten sind endlich angekommen, nachdem sie dein Notsignal empfangen haben, und haben dich hastig vom Schmelzofen weggezogen."
  },
  AvgDialog_57813_Content_46 = {
    Text = "Durch die Flammen blickend, erhaschtest du die letzte Botschaft auf ihren Lippen, kurz bevor ihr Gesicht zu Asche wurde."
  },
  AvgDialog_57813_Content_47 = {
    Text = "Wir treffen uns am Ende."
  },
  AvgDialog_57813_Content_5 = {
    Text = "Als deine Hand den Türknauf umschließt, stellt sich dir aus einem instinktiven Warnsignal jedes Haar am Körper auf und du hockst dich abrupt mit klopfendem Herzen nieder."
  },
  AvgDialog_57813_Content_7 = {
    Text = "Gleichzeitig fegte eine scharfe Windbö über deinen Kopf, schnitt durch einige fliegende Haarsträhnen, und mit einem lauten Krachen brach schließlich die Tür des Schlafsaals zusammen."
  },
  AvgDialog_57813_Content_8 = {
    Text = "Schade, ich habe nicht erwartet, dass der Welpe sich hinlegt. Komm schon, Händedruck?"
  },
  AvgDialog_57813_Content_9 = {
    Text = "Du siehst nach oben, und diese Augen überschneiden sich zwischen Erinnerung und Realität, blicken mit demselben freudigen Lächeln wie immer auf dich herab."
  },
  AvgDialog_57890_Content_1 = {
    Text = "Ich werde die Verschmelzung von Tawil beschleunigen, Hüter, wie wirst du damit umgehen?"
  },
  AvgDialog_58289_Content_1 = {
    Text = "Unerwünschter Gast"
  },
  AvgDialog_58289_Content_10 = {
    Text = "Nein. Was, wenn es schon Nacht ist?!"
  },
  AvgDialog_58289_Content_11 = {
    Text = "Du rollst dich schnell aus dem Bett, findest zielsicher Stift, Schmierpapier und Radiergummi und stopfst alles in deine Tasche."
  },
  AvgDialog_58289_Content_12 = {
    Text = "Sobald alles bereit ist, holst du tief Luft und öffnest die Zimmertür—"
  },
  AvgDialog_58289_Content_13 = {
    Text = "Hä...? Das ist nicht die Schule, die ich kenne."
  },
  AvgDialog_58289_Content_14 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58289_Content_15 = {
    Text = "Ach so, das muss ein Traum sein! Gut, dann schlafe ich weiter..."
  },
  AvgDialog_58289_Content_16 = {
    Text = "Du drehst dich schnell um, aber die Zimmertür—ja, das ganze Gebäude—ist nirgends zu finden."
  },
  AvgDialog_58289_Content_17 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58289_Content_18 = {
    Text = "Du musstest dich wieder umdrehen und auf die Straße vor dir blicken."
  },
  AvgDialog_58289_Content_19 = {
    Text = "Ist da jemand—Hallo—"
  },
  AvgDialog_58289_Content_2 = {
    Text = "Verschiedene Tiere leben hier, und gelegentlich tauchen auch dämonische Wesen auf."
  },
  AvgDialog_58289_Content_20 = {
    Text = "Guten Morgen, guten Tag, guten Abend—"
  },
  AvgDialog_58289_Content_21 = {
    Text = "Gluck, gluck!"
  },
  AvgDialog_58289_Content_22 = {
    Text = "Gott sei Dank, endlich hat mir etwas geantwortet!"
  },
  AvgDialog_58289_Content_23 = {
    Text = "Du rennst aufgeregt zur Quelle des Geräuschs, nur um einen kleinen roten Briefkasten zu finden."
  },
  AvgDialog_58289_Content_24 = {
    Text = "Gluck gluck, Verdauungsprobleme, Hilfe... Hilfe..."
  },
  AvgDialog_58289_Content_25 = {
    Text = "<BigShake:Whoa, ugh!!>"
  },
  AvgDialog_58289_Content_26 = {
    Text = "Der Briefkasten zuckte nervös und spuckte dann einen feuchten Brief aus."
  },
  AvgDialog_58289_Content_27 = {
    Text = "Ist das für mich? Es sieht ein bisschen eklig aus..."
  },
  AvgDialog_58289_Content_28 = {
    Text = "Es ist eine windstille Nacht. Die Gebäude sind in dunkelrotes Mondlicht getaucht, und die fest verschlossenen Türen verwehren jedem den Eintritt."
  },
  AvgDialog_58289_Content_29 = {
    Text = "Du bist das einzige Lebewesen im Umkreis von hundert Meilen."
  },
  AvgDialog_58289_Content_3 = {
    Text = "Klingel–klingel—"
  },
  AvgDialog_58289_Content_30 = {
    Text = "Öffne den Umschlag"
  },
  AvgDialog_58289_Content_31 = {
    Text = "Du versuchst, das klebrige Gefühl an deinen Fingerspitzen zu ignorieren, während du vorsichtig den Umschlag öffnest."
  },
  AvgDialog_58289_Content_32 = {
    Text = "An den fernen Empfänger:\n\nBitte treffen Sie vor Mitternacht im Ferle-Herrenhaus ein.\n<Red:Seien Sie pünktlich, oder tragen Sie die Konsequenzen (Gehirn@2 explodiert zu @3)!>\nAdresse des Herrenhauses: Vertraulich.\n\n-▼-"
  },
  AvgDialog_58289_Content_33 = {
    Text = "Das Ferland-Herrenhaus? Ich erinnere mich, das ist Herrn Dexters Anwesen. Seit wann spielt er denn auch Streiche...?"
  },
  AvgDialog_58289_Content_34 = {
    Text = "Außerdem habe ich meine Uhr nicht dabei, also kann ich nicht mal die Zeit ablesen—"
  },
  AvgDialog_58289_Content_35 = {
    Text = "Tick tack. Tick tack."
  },
  AvgDialog_58289_Content_36 = {
    Text = "Eine riesige Uhr ist irgendwann am Himmel erschienen, deren Stunden- und Minutenzeiger genau auf 11 Uhr stehen."
  },
  AvgDialog_58289_Content_37 = {
    Text = "Der dünne Sekundenzeiger bewegt sich weiterhin in gleichmäßigem Tempo vorwärts, kalt und akribisch."
  },
  AvgDialog_58289_Content_38 = {
    Text = "Was... geschieht hier..."
  },
  AvgDialog_58289_Content_39 = {
    Text = "Hm, hast du denselben Brief bekommen wie ich?"
  },
  AvgDialog_58289_Content_4 = {
    Text = "Mm... so müde, stör mich nicht."
  },
  AvgDialog_58289_Content_40 = {
    Text = "Wer ist da?!"
  },
  AvgDialog_58289_Content_41 = {
    Text = "Entschuldigung, {Male=Mr.,Female=Miss} Schutzherr! Du schienst ziemlich konzentriert. Ich habe dich mehrmals gerufen..."
  },
  AvgDialog_58289_Content_42 = {
    Text = "Erinnerst du dich nicht an mich? Ich bin Elsa. Wir hatten zusammen Fräulein Dolls Einführung in die Auflösung."
  },
  AvgDialog_58289_Content_43 = {
    Text = "Elsa... Jetzt erinnere ich mich, sie war diejenige, die sich oft Ramonas Notizen ausgeliehen hat."
  },
  AvgDialog_58289_Content_44 = {
    Text = "<Small:Tut mir leid, ich falle ständig durch meine Kurse...>"
  },
  AvgDialog_58289_Content_45 = {
    Text = "Elsa senkte den Kopf und drückte verzweifelt das herzförmige Kissen fest an sich."
  },
  AvgDialog_58289_Content_46 = {
    Text = "Sei nicht traurig, Frau Elsa. In Frau Dolls Kurs durchzufallen ist ein Initiationsritus für die meisten Ermittler."
  },
  AvgDialog_58289_Content_47 = {
    Text = "Übrigens, du sagtest, du hast denselben Brief erhalten. Kannst du sie auch sehen?"
  },
  AvgDialog_58289_Content_48 = {
    Text = "Du zeigst auf die riesige Uhr, die über dem Vollmond hängt."
  },
  AvgDialog_58289_Content_49 = {
    Text = "Ich kann sie sehen. Aber ich habe mich verirrt, kann die richtige Richtung nicht finden, und es gibt noch weniger als eine Minute."
  },
  AvgDialog_58289_Content_5 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58289_Content_50 = {
    Text = "Seltsam, mein Countdown zeigt noch eine Stunde an. Könnte es daran liegen, dass du diese Welt zuerst betreten hast?"
  },
  AvgDialog_58289_Content_51 = {
    Text = "Ich weiß nicht... Das ist doch nur ein Streich, oder, {Male=Mr.,Female=Miss} %player%?"
  },
  AvgDialog_58289_Content_52 = {
    Text = "Ich war noch nie auf Außeneinsätzen, also habe ich keine Erfahrung mit abnormalen Ereignissen..."
  },
  AvgDialog_58289_Content_53 = {
    Text = "Ehrlich gesagt, ist es auch für mich das erste Mal, dass ich auf so eine Situation stoße."
  },
  AvgDialog_58289_Content_54 = {
    Text = "Countdown endet in: <Red:5> Sekunden"
  },
  AvgDialog_58289_Content_55 = {
    Text = "Du nimmst sanft Elsas Hand."
  },
  AvgDialog_58289_Content_56 = {
    Text = "Mit nur noch einer Minute kann nicht einmal eine Zeitmaschine helfen. Aber hab keine Angst."
  },
  AvgDialog_58289_Content_57 = {
    Text = "Zeit bis das Countdown endet: <Red:0> Sekunde"
  },
  AvgDialog_58289_Content_58 = {
    Text = "Egal, was als Nächstes passiert, ich werde beschützen —"
  },
  AvgDialog_58289_Content_59 = {Text = "Deine..."},
  AvgDialog_58289_Content_6 = {
    Text = "Oh nein, heute ist die Prüfung in Einführung in die Auflösungslehre. Wie spät ist es..."
  },
  AvgDialog_58289_Content_60 = {
    Text = "Elsas Kopf explodierte in einem warmen Brei aus Gehirnmasse. Die zähe Flüssigkeit spritzte auf mein Gesicht und erfüllte die Luft mit dem metallischen Geruch von Blut."
  },
  AvgDialog_58289_Content_61 = {
    Text = "%player%@2, rette @3..."
  },
  AvgDialog_58289_Content_62 = {
    Text = "Dunkler Schlamm sickert unaufhörlich aus dem gebrochenen Hals und formt rasch ein weiteres blasses, fremdes Gesicht."
  },
  AvgDialog_58289_Content_63 = {
    Text = "<Change>Rette mich, rette mich..."
  },
  AvgDialog_58289_Content_64 = {
    Text = "Fräulein Elsa?! Was... geht hier vor..."
  },
  AvgDialog_58289_Content_66 = {
    Text = "Die Klinge der Bestie durchschnitt die Luft und teilte „Elsa“ in zwei Hälften. Schwarzer D–Schleim schoss hervor wie Blut."
  },
  AvgDialog_58289_Content_67 = {
    Text = "Es ist zwecklos. Sie hat ihren Verstand schon vor langer Zeit verloren."
  },
  AvgDialog_58289_Content_68 = {
    Text = "Mr. Ryker?!"
  },
  AvgDialog_58289_Content_69 = {
    Text = "Ryker zog seine Bestienklauen ein und kam leichten Schrittes auf dich zu."
  },
  AvgDialog_58289_Content_7 = {
    Text = "6:37, noch früh..."
  },
  AvgDialog_58289_Content_70 = {
    Text = "Warum machst du so ein weinerliches Gesicht? Keine Sorge, dieser Ort ist wahrscheinlich jemandes Geheimgang."
  },
  AvgDialog_58289_Content_71 = {
    Text = "Geheimgang...?"
  },
  AvgDialog_58289_Content_72 = {
    Text = "Mm. Mit anderen Worten, diese Elsa ist in der Realität höchstwahrscheinlich noch am Leben."
  },
  AvgDialog_58289_Content_73 = {
    Text = "Wie vom Detektiv zu erwarten, sofort erkannt. Wie lautet deine Schlussfolgerung?"
  },
  AvgDialog_58289_Content_74 = {
    Text = "Es war in einer Nacht wie dieser, als ich Elsa zum ersten Mal traf."
  },
  AvgDialog_58289_Content_75 = {
    Text = "Damals wurde sie von einer Horde Auflösungsmonster verfolgt. Ich war gerade aus der Taverne gekommen, zeigte ihr einen Weg und tötete die Monster, die sie verfolgten."
  },
  AvgDialog_58289_Content_76 = {
    Text = "Wir sind uns gerade eben wieder begegnet. Gleiche Zeit, gleicher Ort, aber ich habe ihr den falschen Weg gezeigt, wodurch sie verletzt wurde. Das bedeutet also—"
  },
  AvgDialog_58289_Content_77 = {
    Text = "Das heißt?"
  },
  AvgDialog_58289_Content_78 = {
    Text = "Mein Glück ist verschwunden! Das ist etwas, das absolut nicht passieren kann, also schlussfolgere ich logisch, dass dies nicht die Realität ist."
  },
  AvgDialog_58289_Content_79 = {
    Text = "Oder du könntest mir zweimal ins Gesicht klatschen, um zu prüfen, ob das ein Traum ist? Ich habe mir vorhin schon mehrmals selbst eine verpasst, aber es hat nichts gebracht."
  },
  AvgDialog_58289_Content_8 = {
    Text = "Du tastest herum und drückst den Weckerschalter, und fällst zurück in tiefen Schlaf."
  },
  AvgDialog_58289_Content_80 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58289_Content_81 = {
    Text = "Zack, was ich weiß, ist, dass ich nicht will, dass mein Kopf explodiert, weder im Geheimgang noch in der Realität."
  },
  AvgDialog_58289_Content_82 = {
    Text = "Du brauchst dringend meine Hilfe! Auf meinem Weg bin ich auf ziemlich viele Nachzügler wie Elsa gestoßen. Wir sollten besser die Luftroute nehmen."
  },
  AvgDialog_58289_Content_83 = {
    Text = "Ryker sprach und deutete auf das Dach eines nahegelegenen Gebäudes."
  },
  AvgDialog_58289_Content_84 = {
    Text = "Du meinst, vom Dach aus hinüberfliegen?"
  },
  AvgDialog_58289_Content_85 = {
    Text = "Tut mir leid, ich bin nur ein gewöhnlicher Schutzherr und kann bei deinen akrobatischen Abenteuern nicht mitmachen—"
  },
  AvgDialog_58289_Content_86 = {
    Text = "In der nächsten Sekunde warf Ryker dich auf seinen Rücken und sprang in die Luft."
  },
  AvgDialog_58289_Content_87 = {
    Text = "Halt dich fest, {Male=Mr.,Female=Miss} %player%!"
  },
  AvgDialog_58289_Content_88 = {
    Text = "<Shake:Wahhh!!>"
  },
  AvgDialog_58289_Content_89 = {
    Text = "Du klammerst dich voller Angst an Rykers Kragen fest. Der geduckte Detektiv springt flink über große und kleine Dächer und schlängelt sich durch die dicht gedrängten Gebäude von Lentiniën."
  },
  AvgDialog_58289_Content_9 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58289_Content_90 = {
    Text = "Ein Mann und ein Wolf preschen unter dem stillen Mond dahin."
  },
  AvgDialog_58289_Content_91 = {
    Text = "Du hörst nur das reine Rauschen des Windes. Du duckst dich und schmiegst dich in das weiche Fell unter dir."
  },
  AvgDialog_58289_Content_92 = {
    Text = "Und? Hat es Spaß gemacht?"
  },
  AvgDialog_58289_Content_93 = {
    Text = "Hätte nie erwartet, dass du so etwas draufhast... <Big:Langsamer, bitte langsamer!>"
  },
  AvgDialog_58289_Content_94 = {
    Text = "Ryker lachte herzhaft, sein Brustkorb vibrierte, als würde jede Zelle in seinem Körper jubeln und vor Freude springen."
  },
  AvgDialog_58289_Content_95 = {
    Text = "Das ist es, was ein Wolf tun sollte! Ich kehre nur zu meinen alten Gewohnheiten zurück, verstanden?"
  },
  AvgDialog_58289_Content_96 = {
    Text = "Ich hab gesagt, <BigShake:Langsamer!!>"
  },
  AvgDialog_58289_Content_97 = {
    Text = "Sachte, sachte, vergreif dich nicht an meinem Fell!"
  },
  AvgDialog_58290_Content_1 = {Text = "Spukhaus"},
  AvgDialog_58290_Content_10 = {
    Text = "Das Spiel am Tisch ist in vollem Gange, und niemand beachtet deine kleine Frage."
  },
  AvgDialog_58290_Content_11 = {
    Text = "<BigShake:Entschuldigt die Störung bei eurem Vergnügen!>"
  },
  AvgDialog_58290_Content_12 = {
    Text = "Erinnert sich noch jemand daran, dass wir im Reich einer verdammten wahnsinnigen Gottheit gefangen sind?"
  },
  AvgDialog_58290_Content_13 = {
    Text = "Korrektur: einer wahnsinnigen und vergesslichen Gottheit. Was wir jetzt tun müssen, ist unsere Energie zu schonen, bis Er sich an die Frage erinnert, die Er stellen will, richtig?"
  },
  AvgDialog_58290_Content_14 = {
    Text = "Straight Flush, nicht schlecht!"
  },
  AvgDialog_58290_Content_15 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58290_Content_16 = {
    Text = "Gut, ich werde in der Nähe eine Untersuchung durchführen."
  },
  AvgDialog_58290_Content_17 = {
    Text = [[
Ferland-Anwesen
Arbeitszimmer im Ersten Stock]]
  },
  AvgDialog_58290_Content_18 = {
    Text = "Mm... Alle Bücher dieses Kerls sind schicke Hardcover-Ausgaben, die nie geöffnet wurden. Wie um alles in der Welt ist er Professor an der Misaq geworden?"
  },
  AvgDialog_58290_Content_19 = {
    Text = "Hä, was ist das?"
  },
  AvgDialog_58290_Content_2 = {
    Text = "Herrenhaus Ferland\nZwei Stunden später"
  },
  AvgDialog_58290_Content_20 = {
    Text = "In einer vernachlässigten Ecke fällt dir ein schwarzer Sarg auf."
  },
  AvgDialog_58290_Content_21 = {
    Text = "Komplexe Muster und Symbole sind in Gold auf die Seiten des Sarges gemalt, und dichter schwarzer Nebel sickert schwach aus dem zentralen Spalt."
  },
  AvgDialog_58290_Content_22 = {
    Text = "Mm—lässt sich überhaupt nicht aufschieben."
  },
  AvgDialog_58290_Content_23 = {
    Text = "Es scheint, dass etwas im Stil von Gourem Washi ist. Woher hat Dexter das?"
  },
  AvgDialog_58290_Content_24 = {
    Text = "Neugierig strecktest du die Hand aus und berührtest sanft die vergoldeten Muster an der Seite des Sarges, doch dann—"
  },
  AvgDialog_58290_Content_25 = {
    Text = [[
Apophis, der Schwarze Pharao, ist Karnak.
Du ehrst ihn; er lebt, er lebt, er lebt.]]
  },
  AvgDialog_58290_Content_26 = {
    Text = "Apophis, er ist nicht tot, er ist nicht tot, Apophis."
  },
  AvgDialog_58290_Content_27 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58290_Content_28 = {
    Text = "Was ist los, Lorde? Dein Teint sieht so blass aus."
  },
  AvgDialog_58290_Content_29 = {
    Text = "Entschuldigung, ich habe eine dringende Angelegenheit zu erledigen. Ich bin gleich zurück."
  },
  AvgDialog_58290_Content_3 = {
    Text = "Es scheint, als hätte Fortuna Sie heute Abend nicht begünstigt, Herr Ryker."
  },
  AvgDialog_58290_Content_30 = {
    Text = "Schon wieder einer weggelaufen, sieht so aus, als würde ich bald quitt sein... Wo sind die Roboterassistentin und die Magierin?"
  },
  AvgDialog_58290_Content_31 = {
    Text = "Mm, ich habe gerade Fräulein Erica nach oben gehen sehen. Was Fräulein Casiah betrifft, hat sie seit ihrer Rückkehr niemand mehr gesehen."
  },
  AvgDialog_58290_Content_32 = {
    Text = "Ich bin auch etwas müde. Ich möchte etwas frische Luft schnappen."
  },
  AvgDialog_58290_Content_33 = {
    Text = "Aber es schneit draußen stark. Du wirst dich erkälten, Mrs. Sorel!"
  },
  AvgDialog_58290_Content_34 = {
    Text = "Dies ist nicht die echte Welt. Es besteht keine Notwendigkeit, sich an Konventionen zu halten. Außerdem ist es doch schön, einen Moment innezuhalten und die verschneite Landschaft zu genießen, oder?"
  },
  AvgDialog_58290_Content_35 = {
    Text = "Sorel verließ den Raum mit anmutigen Schritten, und die einst lebhafte Halle wurde augenblicklich still."
  },
  AvgDialog_58290_Content_36 = {
    Text = "<SmallShake:Chef, das Kartenspiel ist nur eine Tarnung, oder? Ich weiß, dass du einen Plan haben musst!>"
  },
  AvgDialog_58290_Content_37 = {Text = "Äh"},
  AvgDialog_58290_Content_38 = {
    Text = "Richtig! Herr Dexters Reaktion war eben seltsam. Lass uns sein Schlafzimmer überprüfen."
  },
  AvgDialog_58290_Content_39 = {
    Text = "Wow! Das Detektivspiel hat endlich begonnen!"
  },
  AvgDialog_58290_Content_4 = {
    Text = "Der Pot hat 10.000 Leo Fang überschritten. Möchten Sie erhöhen?"
  },
  AvgDialog_58290_Content_40 = {
    Text = [[
Ferland-Anwesen
Treppenhaus]]
  },
  AvgDialog_58290_Content_41 = {
    Text = "Chef, bist du sicher, dass Herr Dexter in seinem Schlafzimmer ist? Ich dachte, ich hätte ihn in Richtung Arbeitszimmer gehen sehen."
  },
  AvgDialog_58290_Content_42 = {
    Text = "Mm... Es ist schwer, meinen Denkprozess zu erklären. Du kannst es dir als eine seltsame Intuition vorstellen."
  },
  AvgDialog_58290_Content_43 = {
    Text = "Verstehe! Das muss die legendäre Intuition eines berühmten Detektivs sein!!"
  },
  AvgDialog_58290_Content_44 = {
    Text = "Keine Sorge, Chef. Ich werde kein einziges Wort anzweifeln."
  },
  AvgDialog_58290_Content_45 = {
    Text = "Hanna klopft sich auf die Brust und zückt dann ihre Lupe, um die Umgebung zu inspizieren."
  },
  AvgDialog_58290_Content_46 = {
    Text = "Ermittlungseinsatz 215 beginnt offiziell! Zunächst erscheint vor uns die aus Ebenholz geschnitzte Treppe – bescheiden und doch luxuriös, losgelöst von weltlichen Belangen..."
  },
  AvgDialog_58290_Content_47 = {
    Text = "Denken Sie an einen Berufswechsel, Fräulein Hanna? Plötzlich habe ich das Gefühl, Sie wären bestens geeignet, Werbung bei <Blue:Heinz Co.> zu verkaufen."
  },
  AvgDialog_58290_Content_48 = {
    Text = "Bitte unterbrechen Sie nicht die Ermittlung anderer! Zu guter Letzt gibt es da noch das geschnitzte Fenster neben der Treppe –"
  },
  AvgDialog_58290_Content_49 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58290_Content_5 = {
    Text = "...Natürlich."
  },
  AvgDialog_58290_Content_50 = {
    Text = "Nicht weit von der Stelle, auf die die Linse gerichtet war, huschte eine schattenhafte Gestalt am Fenster vorbei."
  },
  AvgDialog_58290_Content_51 = {
    Text = "Aah! G-G-Geist!!"
  },
  AvgDialog_58290_Content_52 = {
    Text = "Drücken Sie sich so aus, dass ich es verstehen kann, Fräulein Hanna."
  },
  AvgDialog_58290_Content_53 = {
    Text = "<Shake:Herr Dexters Geist! Direkt am Treppenhaus! Er schwebt nach oben, immer weiter nach oben!>"
  },
  AvgDialog_58290_Content_54 = {
    Text = "Ryker trat vor und öffnete das Fenster. Der Wind heulte, und Schneeflocken wirbelten ziellos umher und rieselten in alle Richtungen herab."
  },
  AvgDialog_58290_Content_55 = {
    Text = "Er blickte nach oben, das warme Licht aus dem Zimmer im zweiten Stock tauchte die Schneeflocken in ein schwaches orangefarbenes Leuchten."
  },
  AvgDialog_58290_Content_56 = {
    Text = "Interessant, in mehr als einem Zimmer brennt Licht... Lass uns nachsehen."
  },
  AvgDialog_58290_Content_57 = {
    Text = [[
Ferland-Anwesen
Flur im zweiten Stock]]
  },
  AvgDialog_58290_Content_58 = {
    Text = "Hmm, die Tür ist abgeschlossen."
  },
  AvgDialog_58290_Content_59 = {
    Text = "Herr Dexter, sind Sie da drin? Geht es Ihnen schon besser?"
  },
  AvgDialog_58290_Content_6 = {
    Text = "Das freut mich zu hören, Herr Ryker. Sobald wir aus dem Geheimgang heraus sind, werde ich den Butler alle Rechnungen an Sie schicken lassen."
  },
  AvgDialog_58290_Content_60 = {
    Text = "Das Zimmer war totenstill. Nach einer Weile drang Dexters gedämpfte Stimme von drinnen heraus."
  },
  AvgDialog_58290_Content_61 = {
    Text = "Entschuldigung, mir geht es nicht gut. Kann ich eine kurze Pause machen?"
  },
  AvgDialog_58290_Content_62 = {
    Text = "Du hattest recht. Er ist wirklich da drin. Was ist jetzt der Plan?"
  },
  AvgDialog_58290_Content_63 = {
    Text = "Ziehen wir uns zurück. Dies ist das Anwesen eines adligen Lords; wir sollten grundlegende Etikette wahren."
  },
  AvgDialog_58290_Content_64 = {
    Text = "Ryker sprach, während er ein paar Schritte zurücktrat."
  },
  AvgDialog_58290_Content_65 = {
    Text = "Dann beschleunigte er plötzlich und sprang, trat gegen die Tür—"
  },
  AvgDialog_58290_Content_66 = {
    Text = "Platschen!!"
  },
  AvgDialog_58290_Content_67 = {
    Text = "Die massive Eichentür wurde aufgetreten und hinterließ ein großes Loch. Ryker griff hinein, fand mühelos die Klinke und öffnete die Tür seelenruhig."
  },
  AvgDialog_58290_Content_68 = {
    Text = "Die Dame zuerst, bitte—"
  },
  AvgDialog_58290_Content_69 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58290_Content_7 = {
    Text = "Schickt unsere Rechnung auch an ihn, hehehe～"
  },
  AvgDialog_58290_Content_70 = {
    Text = "<Shake:Was ist mit Etikette und Manieren passiert?>"
  },
  AvgDialog_58290_Content_71 = {
    Text = "Tut mir leid, meine begrenzten Manieren und Etikette gelten nur für Menschen. Mach die Augen auf, was ist das?"
  },
  AvgDialog_58290_Content_72 = {
    Text = "Hannas Blick folgt Rykers, und sie sieht ein schwarzes Grammophon neben dem Schreibtisch. Die schwarze Schallplatte dreht sich langsam."
  },
  AvgDialog_58290_Content_73 = {
    Text = "Entschuldigung, mir geht es nicht gut. Kann ich eine kurze Pause machen?"
  },
  AvgDialog_58290_Content_74 = {
    Text = "Entschuldigung @2... Fühle mich nicht gut... Ruhe..."
  },
  AvgDialog_58290_Content_75 = {
    Text = "Ruhe, Ruhe@2 Ruhe..."
  },
  AvgDialog_58290_Content_76 = {
    Text = "Alle, bitte verlassen Sie so schnell wie möglich den Raum und stören Sie Herrn Dexters Ruhe nicht."
  },
  AvgDialog_58290_Content_77 = {
    Text = "<Shake:Whoa!! Wann hast du...>"
  },
  AvgDialog_58290_Content_78 = {
    Text = "Fräulein Erica, auch wenn dieser Kerl dich zum Narren gemacht hat, muss ich dich trotzdem darauf hinweisen..."
  },
  AvgDialog_58290_Content_79 = {
    Text = "Nicht ein einziges Haar von Dexter ist hier zu finden."
  },
  AvgDialog_58290_Content_8 = {
    Text = "Verdammt! Dieser Kerl N muss etwas mit mir angestellt haben..."
  },
  AvgDialog_58290_Content_80 = {
    Text = "Alle, bitte verlasst so schnell wie möglich das Gebäude und..."
  },
  AvgDialog_58290_Content_81 = {
    Text = "Vergiss sie erstmal. Was hat es mit diesem Grammophon auf sich?"
  },
  AvgDialog_58290_Content_82 = {
    Text = "Ganz einfach. Jemand hat ein Alibi fabriziert, aber ich habe es sofort durchschaut."
  },
  AvgDialog_58290_Content_83 = {
    Text = "Verstehe. Ich kapier's! In Kriminalromanen gibt es dort, wo ein Alibi ist, auch einen Mord—"
  },
  AvgDialog_58290_Content_84 = {Text = "Bang!"},
  AvgDialog_58290_Content_85 = {
    Text = "Ein plötzlicher Schuss durchbricht die stille Nacht."
  },
  AvgDialog_58290_Content_86 = {
    Text = "<Shake:Das war... von unten...>"
  },
  AvgDialog_58290_Content_87 = {
    Text = "Geh und sieh nach. Das Spiel... es hat vielleicht schon begonnen."
  },
  AvgDialog_58290_Content_9 = {
    Text = "Entschuldigen Sie..."
  },
  AvgDialog_58291_Content_1 = {
    Text = "Niemand überlebte"
  },
  AvgDialog_58291_Content_10 = {
    Text = [[
Ferland-Anwesen
23:45 Uhr]]
  },
  AvgDialog_58291_Content_100 = {
    Text = "Schon gut, schon gut, was auch immer du sagst—"
  },
  AvgDialog_58291_Content_101 = {
    Text = "Schon gut, Erica wird euch als Nächstes unterhalten. Es gibt noch 1124 Kreaturen, die darauf warten, dämonische Verträge mit mir zu schließen."
  },
  AvgDialog_58291_Content_102 = {
    Text = "Vergesst das nicht..."
  },
  AvgDialog_58291_Content_103 = {
    Text = "<Red:Der Bösewicht versteckt sich unter uns. Vertraut niemandem.>"
  },
  AvgDialog_58291_Content_104 = {Text = "?!"},
  AvgDialog_58291_Content_105 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58291_Content_106 = {
    Text = "Worauf schaust du? Ich hatte noch nicht einmal die Gelegenheit, etwas zu tun!"
  },
  AvgDialog_58291_Content_107 = {
    Text = "Oh? Erzähl doch mal, was hattest du ursprünglich vor?"
  },
  AvgDialog_58291_Content_108 = {
    Text = "Ausgezeichnet, alle zusammen! Behaltet den Streitgeist bei. Lasst euch von meiner Anwesenheit nicht bremsen!"
  },
  AvgDialog_58291_Content_109 = {
    Text = "Unsere erste Verhaltensregel: Chaos! Zweite Regel: Chaos! Dritte Regel..."
  },
  AvgDialog_58291_Content_11 = {
    Text = "Die schwere Holztür wird aufgestoßen. Ryker betritt die Halle mit weit ausgebreiteten Armen und überschwänglicher Begeisterung."
  },
  AvgDialog_58291_Content_110 = {
    Text = "Lass mich raten, wieder Chaos?"
  },
  AvgDialog_58291_Content_111 = {
    Text = "Falsch! Es ist <Red:Endloses Chaos>!"
  },
  AvgDialog_58291_Content_112 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58291_Content_113 = {
    Text = "Also dann, viel Spaß euch allen～"
  },
  AvgDialog_58291_Content_114 = {
    Text = "Nach diesen Worten verschwand N in dichtem schwarzen Nebel und ließ alle zurück, die sich verwirrt anstarrten."
  },
  AvgDialog_58291_Content_115 = {
    Text = "%player%, woher kommt dieser nervige Typ? Du scheinst Ihn gut zu kennen."
  },
  AvgDialog_58291_Content_116 = {
    Text = "Du zögertest und überlegtest, ob du Hanna alles erzählen solltest, was du wusstest. Doch bald wurde dir klar, dass es unnötig war."
  },
  AvgDialog_58291_Content_117 = {
    Text = "Du weißt auch nichts über N."
  },
  AvgDialog_58291_Content_118 = {
    Text = "Tut mir leid, ich weiß auch nicht viel über diese Person. Nachdem sie ihr Aussehen verändert hat, wurde ihre Persönlichkeit noch..."
  },
  AvgDialog_58291_Content_119 = {
    Text = "Du wolltest „lebhaft“ sagen, schlucktest das Wort aber herunter."
  },
  AvgDialog_58291_Content_12 = {
    Text = "Dexter, mein alter Kumpel! Es sind erst ein paar Tage vergangen, und du lädst uns schon auf dein Anwesen zu einem Wiedersehen ein?"
  },
  AvgDialog_58291_Content_120 = {
    Text = "Noch nerviger."
  },
  AvgDialog_58291_Content_121 = {
    Text = "Wenn ich mich nicht irre, müssen wir das Rätsel lösen, um <Yellow:die endgültige Wahrheit> aufzudecken, richtig?"
  },
  AvgDialog_58291_Content_122 = {
    Text = "Mm... Das ist richtig."
  },
  AvgDialog_58291_Content_123 = {
    Text = "Ein kleines Problem. Diese Person scheint vergessen zu haben, das Thema zu nennen."
  },
  AvgDialog_58291_Content_124 = {
    Text = "In der Tat, ein endloser Zustand des Chaos."
  },
  AvgDialog_58291_Content_125 = {
    Text = "Du blicktest auf die völlig zerstörte Brücke vor dir. Das pechschwarze Tal wirkte wie ein bodenloser Abgrund und schnitt dich vollständig von der fernen Insel ab."
  },
  AvgDialog_58291_Content_126 = {
    Text = "Herr Dexter, sind Sie sicher, dass dies der einzige Weg ist, der in die Außenwelt führt?"
  },
  AvgDialog_58291_Content_127 = {
    Text = "Dexter zuckte hilflos mit den Schultern."
  },
  AvgDialog_58291_Content_128 = {
    Text = "Ich habe diesen Ort gewählt, weil er abgelegen ist und mich vor vielen sinnlosen sozialen Interaktionen und Aufmerksamkeit schützt."
  },
  AvgDialog_58291_Content_129 = {
    Text = "Die Dinge nahmen eine unerwartete Wendung."
  },
  AvgDialog_58291_Content_13 = {
    Text = "Natürlich muss ich euch darauf hinweisen, dass diese Art der Einladung etwas extrem ist."
  },
  AvgDialog_58291_Content_130 = {
    Text = "Der Schnee fiel dicht und schnell und bedeckte rasch die beschädigte Holzbrücke."
  },
  AvgDialog_58291_Content_131 = {
    Text = "Hatschi! Schneestürme, abgelegene Bergvillen und Menschen, die sich auf mysteriöse Weise zusammenfinden..."
  },
  AvgDialog_58291_Content_132 = {
    Text = "Ich habe ein schlechtes Gefühl."
  },
  AvgDialog_58291_Content_14 = {
    Text = "<Small:Hey, was ist mit dem Hinterhalt!>"
  },
  AvgDialog_58291_Content_15 = {
    Text = "Ich weiß, worauf du anspielst — ich war es nicht."
  },
  AvgDialog_58291_Content_16 = {
    Text = "Dexter saß am Ende des langen Tisches und fuhr sich ungeduldig durch seine zerzausten Haare."
  },
  AvgDialog_58291_Content_17 = {
    Text = "<Gray:Ramona hat erwähnt, dass Herr Dexter äußerst reizbar wird, wenn sein Schlaf gestört wird...>"
  },
  AvgDialog_58291_Content_18 = {
    Text = "Ich schlief tief und fest zu Hause, als plötzlich eine Gruppe Leute an die Tür klopfte und alle Diener verschwunden waren."
  },
  AvgDialog_58291_Content_19 = {
    Text = "Ich verstehe immer noch nicht, was passiert ist."
  },
  AvgDialog_58291_Content_2 = {
    Text = [[
Ferland-Anwesen
23:30 Uhr]]
  },
  AvgDialog_58291_Content_20 = {
    Text = "Eine Gruppe Leute...?"
  },
  AvgDialog_58291_Content_21 = {Text = "Knips!"},
  AvgDialog_58291_Content_22 = {
    Text = "Ein weißes Blitzen, und der Raum kehrte sofort in seine ursprüngliche Stille zurück."
  },
  AvgDialog_58291_Content_23 = {
    Text = "Hm, kann immer noch nichts einfangen. Dieser Ort ist wirklich seltsam..."
  },
  AvgDialog_58291_Content_24 = {
    Text = "Hannah?! Was machst du hier?"
  },
  AvgDialog_58291_Content_25 = {
    Text = "Hmph, der Titel der Vizepräsidentin der Folgerungsgesellschaft ist nicht nur zur Zierde! Ich bin die Beste im Wegefinden."
  },
  AvgDialog_58291_Content_26 = {
    Text = "Guten Abend, {Male=Mr.,Female=Miss} %player%, guten Abend, Chef!"
  },
  AvgDialog_58291_Content_27 = {Text = "Mhm."},
  AvgDialog_58291_Content_28 = {
    Text = "Chef...? Ich hätte nicht erwartet, dass ihr zwei euch kennt."
  },
  AvgDialog_58291_Content_29 = {
    Text = "Herr Ryker ist ein renommierter Detektiv im Ostviertel. Wenn wir uns zusammentun, machen Verbrecher einen großen Bogen um uns!"
  },
  AvgDialog_58291_Content_3 = {
    Text = "Yoho! Erfolgreiche Landung～"
  },
  AvgDialog_58291_Content_30 = {
    Text = "Hust, hust. Zügel deinen journalistischen Instinkt; das hier ist kein Nachrichtenbericht."
  },
  AvgDialog_58291_Content_31 = {
    Text = "Ryker zuckte hilflos mit den Schultern in deine Richtung."
  },
  AvgDialog_58291_Content_32 = {
    Text = "Ich bitte sie manchmal, Besorgungen für mich zu erledigen, und im Gegenzug hat sie es geschafft, mir einiges an Informationen zu entlocken. Es ist eine für beide Seiten vorteilhafte Vereinbarung."
  },
  AvgDialog_58291_Content_33 = {
    Text = "Wo wir gerade von gegenseitigem Nutzen sprechen, hatte nicht noch eine andere Person enge Verbindungen zu Misaq?"
  },
  AvgDialog_58291_Content_34 = {
    Text = "Rykers Blick folgend, bemerkst du eine reich gekleidete Frau, die ein Weinglas hält und dir aus dem Schatten heraus zulächelt."
  },
  AvgDialog_58291_Content_35 = {
    Text = "Wir sehen uns wieder, {Male=Mr.,Female=Miss} Schutzherr."
  },
  AvgDialog_58291_Content_36 = {
    Text = "Frau Sorel?! Sie, wie könnten Sie auch..."
  },
  AvgDialog_58291_Content_37 = {
    Text = "Schade, ich hatte gehofft, wir würden uns unter förmlicheren Umständen wiedersehen."
  },
  AvgDialog_58291_Content_38 = {
    Text = "Aber hier gibt es nur ein abgelegenes Herrenhaus und ein leeres Weinglas. Was soll ich tun, um mir die Zeit zu vertreiben?"
  },
  AvgDialog_58291_Content_39 = {
    Text = "Natürlich, füllt die Gläser und lasst uns die ganze Nacht trinken～!"
  },
  AvgDialog_58291_Content_4 = {
    Text = "Bist du sicher, dass Dexter in dieser Bruchbude wohnt? Ist er etwa bankrottgegangen?"
  },
  AvgDialog_58291_Content_40 = {
    Text = "Mit einer fröhlichen Frauenstimme füllte sich das Weinglas in Sorels Hand wie von Zauberhand erneut."
  },
  AvgDialog_58291_Content_41 = {
    Text = "Überraschend, es schmeckt nach Chardonnay... Wie ist das möglich?"
  },
  AvgDialog_58291_Content_42 = {
    Text = "Hehe, was ist das? Schaut euch das an—"
  },
  AvgDialog_58291_Content_43 = {
    Text = "Casiah tippt sanft mit ihrem Stock an den Rand des Weinglases, woraufhin frische rote Rosen augenblicklich erblühen und im Licht erzittern."
  },
  AvgDialog_58291_Content_44 = {
    Text = "Sie pflückte die zarteste und lebendigste Blüte und steckte sie behutsam hinter Sorels Ohr."
  },
  AvgDialog_58291_Content_45 = {
    Text = "Die strahlendste Rose für die schönste Schönheit Lentiniëns."
  },
  AvgDialog_58291_Content_46 = {
    Text = "Wunderbar, Frau Magierin! Hättet Ihr Interesse an einer Stellung bei Hofe? Ich muss Euch Ihrer Majestät der Königin empfehlen."
  },
  AvgDialog_58291_Content_47 = {
    Text = "Wenn der Preis stimmt, lässt sich alles arrangieren..."
  },
  AvgDialog_58291_Content_48 = {
    Text = "Hmm, ist das nicht unser {Male=Mr.,Female=Miss} Schutzherr und Herr Detektiv?"
  },
  AvgDialog_58291_Content_49 = {
    Text = "Casiah wirkt überrascht, als hätte sie euch gerade erst bemerkt."
  },
  AvgDialog_58291_Content_5 = {
    Text = "Verzeihung, dies ist das unauffälligste seiner mehr als fünfzig Anwesen."
  },
  AvgDialog_58291_Content_50 = {
    Text = "Seit wir uns in Aram trennten, habe ich jeden Tag an euch gedacht."
  },
  AvgDialog_58291_Content_51 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58291_Content_52 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58291_Content_53 = {
    Text = "Wartet! Ich habe Wilhelm, den Seniorstudenten, nicht getötet. Casiah ist nur eine arme Arbeiterin. Ihr wollt doch kein Massaker im Hause dieses Gentleman anrichten, oder?"
  },
  AvgDialog_58291_Content_54 = {
    Text = "Kein Problem, ich habe nichts dagegen, draußen ein nettes Gespräch zu führen."
  },
  AvgDialog_58291_Content_55 = {
    Text = "Zisch... Lasst mich das klarstellen: Ich kenne dieses Gelände wie meine Westentasche."
  },
  AvgDialog_58291_Content_56 = {
    Text = "Wenn ihr nicht gewinnen könnt, rennt..."
  },
  AvgDialog_58291_Content_57 = {
    Text = "Dong — Dong —"
  },
  AvgDialog_58291_Content_58 = {
    Text = "Eine riesige Uhr hing plötzlich über allen, ihre Zeiger auf Mitternacht gerichtet."
  },
  AvgDialog_58291_Content_59 = {
    Text = "Meine Damen und Herren, guten Abend! Willkommen in meinem Paradies!"
  },
  AvgDialog_58291_Content_6 = {
    Text = "Hmm... Mir ist gerade eine brillante Idee gekommen—"
  },
  AvgDialog_58291_Content_60 = {
    Text = "Aah! Warum hat dieses Kind kein Gesicht?!"
  },
  AvgDialog_58291_Content_61 = {
    Text = "Diese vertraute Kleidung und dieses Gefühl... Könnte es sein..."
  },
  AvgDialog_58291_Content_62 = {
    Text = "Herzlichen Glückwunsch an alle, dass ihr eure Intelligenz und euren Teamgeist eingesetzt habt, um die erste Herausforderung, die ich gestellt habe, erfolgreich zu meistern."
  },
  AvgDialog_58291_Content_63 = {
    Text = "Das Aufwärmen ist vorbei; kommen wir nun zum Hauptthema—"
  },
  AvgDialog_58291_Content_64 = {Text = "Bang!"},
  AvgDialog_58291_Content_65 = {
    Text = "Die Kugel durchbohrte das Gesicht der mysteriösen Gestalt und hinterließ ein großes Loch in der Mitte."
  },
  AvgDialog_58291_Content_66 = {
    Text = "Entschuldigung, die Waffe hat sich versehentlich gelöst. Macht dir das Vater-Mutter-Kind-Spiel Spaß, N?"
  },
  AvgDialog_58291_Content_67 = {
    Text = "Also ist Er es..."
  },
  AvgDialog_58291_Content_68 = {
    Text = "Der verbleibende schwarze Nebel auf Ns Gesicht wand und streckte sich unablässig und füllte rasch die Lücke."
  },
  AvgDialog_58291_Content_69 = {
    Text = "Wie langweilig, ihr habt mich so schnell erkannt."
  },
  AvgDialog_58291_Content_7 = {
    Text = "Nur damit das klar ist: Denk nicht einmal daran, Herrn Dexter auszunutzen. Er hat keinerlei Interesse an jeglicher Form von Glücksspiel, spekulativen Investitionen oder riskanten Unternehmungen."
  },
  AvgDialog_58291_Content_70 = {
    Text = "Herr Ryker war beim Angriff unter dem Mond ziemlich begeistert. Gefällt dir das Rollenspiel, das ich für dich maßgeschneidert habe?"
  },
  AvgDialog_58291_Content_71 = {
    Text = "Hah... Ziemlich gewöhnlich. Ist das dein Geheimgang?"
  },
  AvgDialog_58291_Content_72 = {
    Text = "Natürlich. Wenn ihr hier rauskommen wollt, bleibt in diesem Haus und löst die Rätsel, die ich gestellt habe."
  },
  AvgDialog_58291_Content_73 = {
    Text = "Hey, das ist mein Haus. Interessiert sich niemand für meine Meinung?"
  },
  AvgDialog_58291_Content_74 = {
    Text = "Zzz... Zzz..."
  },
  AvgDialog_58291_Content_75 = {Text = "WUMM!!"},
  AvgDialog_58291_Content_76 = {
    Text = "Perfekt, mein kleiner Assistent hat die einzige Brücke zur Außenwelt abgesägt."
  },
  AvgDialog_58291_Content_77 = {
    Text = "Jetzt kannst du nirgendwo hingehen!"
  },
  AvgDialog_58291_Content_78 = {
    Text = "Was?! Beeilt euch und seht nach—"
  },
  AvgDialog_58291_Content_79 = {
    Text = "Ringsum herrscht Stille. Du stehst am Rand der zerbrochenen Brücke auf der Klippe, sprachlos."
  },
  AvgDialog_58291_Content_8 = {
    Text = "Der Detektiv, unhöflich unterbrochen, zog widerwillig seine Hand zurück und nickte stur in Richtung des Herrenhauses in der Ferne."
  },
  AvgDialog_58291_Content_80 = {
    Text = "Irgendwann begann dichter Schnee vom Himmel zu fallen, wirbelnd und treibend in der Luft."
  },
  AvgDialog_58291_Content_81 = {
    Text = "Du umklammertest den matt silbernen Schlüssel an deiner Brust. Seit du dieses Land betreten hast, ist deine Verbindung zu ihm abgerissen."
  },
  AvgDialog_58291_Content_82 = {
    Text = "Es ist zwecklos. Ich habe deine Verbindung zu @2 gekappt. Jetzt besitzt du keine besonderen Fähigkeiten mehr, die über die gewöhnlicher Menschen hinausgehen."
  },
  AvgDialog_58291_Content_83 = {
    Text = "Also warst du es die ganze Zeit..."
  },
  AvgDialog_58291_Content_84 = {
    Text = "Keine Sorge, selbst wenn du dir die Augen aus dem Kopf drückst, wird es nichts nützen."
  },
  AvgDialog_58291_Content_85 = {
    Text = "Wahre Helden lösen Probleme einfach wie gewöhnliche Menschen — habe ich recht, Erica?"
  },
  AvgDialog_58291_Content_86 = {Text = "Erica...?"},
  AvgDialog_58291_Content_87 = {
    Text = "Mechanische Schritte ertönen aus der Ecke."
  },
  AvgDialog_58291_Content_88 = {
    Text = "Erica schwingt eine riesige Kettensäge und streckt rasend schnell ihren Arm aus. Das Verbindungskabel ihrer Prothese dehnt sich auf eine extreme Distanz und sägt sogar die Brücke vor ihr ab."
  },
  AvgDialog_58291_Content_89 = {Text = "...?"},
  AvgDialog_58291_Content_9 = {
    Text = "Hust, hust... Was denkst du denn? Ich meine, wir sollten reingehen und einen Hinterhalt aufbauen, um Informationen zu sammeln..."
  },
  AvgDialog_58291_Content_90 = {
    Text = "Der mechanische Arm von der ist wirklich interessant. Ich muss einen Weg finden, ihn zu bekommen..."
  },
  AvgDialog_58291_Content_91 = {
    Text = "Erica schaltete die Kettensäge aus, ging hinter N und verbeugte sich sogar respektvoll."
  },
  AvgDialog_58291_Content_92 = {
    Text = "Meldung, Meister. Der einzige Durchgang, der Ferrand mit der Außenwelt verbindet, wurde zerstört. Verstrichene Gesamtzeit: 5 Minuten und 40 Sekunden. Verbrauchte Energie..."
  },
  AvgDialog_58291_Content_93 = {
    Text = "Du... Was hast du mit Fräulein Erica gemacht?!"
  },
  AvgDialog_58291_Content_94 = {
    Text = "N sprang leichtfüßig auf Ericas Schulter und schlug lässig die Beine übereinander."
  },
  AvgDialog_58291_Content_95 = {
    Text = "Keine Sorge, ich habe ihre Gedanken nur ein wenig mit meinem Charisma beeinflusst. Darf ich euch meine neue Assistentin vorstellen, Erica."
  },
  AvgDialog_58291_Content_96 = {
    Text = "Erica, sag schnell allen einen guten Abend."
  },
  AvgDialog_58291_Content_97 = {
    Text = "Guten Abend. Bis auf Weiteres wird Erica dafür verantwortlich sein, alle zu beaufsichtigen und zu betreuen. Bitte folgt mir zurück zum Herrenhaus."
  },
  AvgDialog_58291_Content_98 = {
    Text = "Einfach eine kleine Vorwarnung: Falls es jemand wagt, meiner neu eingestellten Assistentin nicht zu gehorchen..."
  },
  AvgDialog_58291_Content_99 = {
    Text = "N drückte sanft den Schalter der elektrischen Säge in Ericas Hand, und der ohrenbetäubende Lärm ließ alle sofort die Ohren zuhalten."
  },
  AvgDialog_58292_Content_1 = {
    Text = "Erstes Treffen"
  },
  AvgDialog_58292_Content_10 = {
    Text = "Aber, aber ich war die ganze Zeit bei Herrn Ryker, nicht wahr, Chef?"
  },
  AvgDialog_58292_Content_11 = {
    Text = "Niemand reagiert auf Hannas etwas schuldbewussten Ruf."
  },
  AvgDialog_58292_Content_12 = {
    Text = "Am anderen Ende des Hauses begannen der Detektiv und sein vorübergehender Assistent ihre Untersuchung vor Ort."
  },
  AvgDialog_58292_Content_13 = {
    Text = "Beide Schuhe fehlen. Es gibt auch zwei Furchen am Hals, seltsam."
  },
  AvgDialog_58292_Content_14 = {
    Text = "Du untersuchst die beiden Strangulationsmarken an Herrn Dexters Hals sorgfältig mit einer Lupe. Sie sind nahezu identisch, mit nur leichten Abweichungen im Winkel."
  },
  AvgDialog_58292_Content_15 = {
    Text = "Die Muster der beiden Eindrücke sind ebenfalls uneinheitlich. Innen zeigt sich eine ordentliche Rautenstruktur, während die äußere rauer ist..."
  },
  AvgDialog_58292_Content_16 = {
    Text = "Vielleicht ist das Seil mittendrin gerissen, oder es wurde blutig, also hat der Mörder es ausgetauscht."
  },
  AvgDialog_58292_Content_17 = {
    Text = "Wie dem auch sei, beide Male am Hals verliefen über die Kieferlinie hinaus, erstreckten sich hinter die Ohren und verschwanden allmählich zum Hinterkopf hin..."
  },
  AvgDialog_58292_Content_18 = {
    Text = "Das sind Strangulationsmarken, die durch Erhängen verursacht wurden."
  },
  AvgDialog_58292_Content_19 = {
    Text = "Nein, das ist nicht korrekt... Die Kratzspuren in der Nähe der Strangulationsmarken deuten auf einen heftigen Kampf hin."
  },
  AvgDialog_58292_Content_2 = {
    Text = "Ferland–Herrenhaus Arbeitszimmer\n90 Minuten verbleiben bis zum Abschluss des Falls <Red:90>"
  },
  AvgDialog_58292_Content_20 = {
    Text = "Oder vielleicht haben sie es nach dem Erhängen bereut? Ich habe von ähnlichen Fällen gehört."
  },
  AvgDialog_58292_Content_21 = {
    Text = "Ohne diese Schallplatte hätten neun von zehn Polizisten den Fall als Selbstmord abgeschlossen."
  },
  AvgDialog_58292_Content_22 = {
    Text = "Und ich bin der Letzte des wachsamen einen Zehntels!"
  },
  AvgDialog_58292_Content_23 = {
    Text = "Vinylplatte?"
  },
  AvgDialog_58292_Content_24 = {
    Text = "{Male=Mr.,Female=Miss} Der Schutzherr war damals nicht am Tatort! Es gab eine Schallplatte, die ständig Herrn Dexters Stimme in Schleife abspielte, wie ein Geist..."
  },
  AvgDialog_58292_Content_25 = {
    Text = "Hanna wirft plötzlich ein, beschreibt alles lebhaft und kann ein Schaudern nicht unterdrücken."
  },
  AvgDialog_58292_Content_26 = {
    Text = "Boss, wir haben überall gesucht, aber Mrs. Sorel nicht gefunden. Könnte sie bereits sein..."
  },
  AvgDialog_58292_Content_27 = {
    Text = "Ryker winkte zuversichtlich ab."
  },
  AvgDialog_58292_Content_28 = {
    Text = "Sehr bald werdet ihr wissen, wo sie ist. Dieser Fall ist fast identisch mit meinem ersten Mordfall"
  },
  AvgDialog_58292_Content_29 = {
    Text = "Das ist also die „Intuition“, von der der Boss sprach"
  },
  AvgDialog_58292_Content_3 = {
    Text = "Ich war draußen vor dem Haus, bin herumgewandert und habe nach einem Weg gesucht, um zu entkommen."
  },
  AvgDialog_58292_Content_30 = {
    Text = "Hust hust, tut mir leid. Das stimmt"
  },
  AvgDialog_58292_Content_31 = {
    Text = "Schallplatte, verlassene Villa, mysteriöser erhängter Hausherr... Hannah erinnert sich auch!"
  },
  AvgDialog_58292_Content_32 = {
    Text = "„Der mysteriöse Hundekopf-Mann löst den Skandal der Reichen auf\" - ich erinnere mich noch an die Schlagzeilen!"
  },
  AvgDialog_58292_Content_33 = {
    Text = "Hundekopf? Das ist doch ein erfundener Titel, ich präsentiere mich immer als Gentleman"
  },
  AvgDialog_58292_Content_34 = {
    Text = "Sobald Liliths Vergangenheit erwähnt wird, bist du sofort interessiert und ziehst Hanna heran"
  },
  AvgDialog_58292_Content_35 = {
    Text = "<Small:Ich habe immer gedacht, dass seine Detektiv-Identität verdächtig ist.>"
  },
  AvgDialog_58292_Content_36 = {
    Text = "<Small:In Lentinen bringt die Aufklärung eines Falls weniger ein als zehn Minuten am Spieltisch.>"
  },
  AvgDialog_58292_Content_37 = {
    Text = "<Small:Vielleicht ist die Detektiv-Identität nur eine Tarnung...>"
  },
  AvgDialog_58292_Content_38 = {
    Text = "Nehmen Sie Ihre Beleidigung zurück, Geheimnisträger %player%. Auch Spieler können Hobbys und Karrieren haben"
  },
  AvgDialog_58292_Content_39 = {
    Text = "Hmm, warum steht hier ein Sarg? Dexters Geschmack"
  },
  AvgDialog_58292_Content_4 = {
    Text = "Sie sagen also, Sie haben kein Alibi. Notiert... Haben Sie den Weg gefunden, Miss Casiah?"
  },
  AvgDialog_58292_Content_40 = {Text = "!!!"},
  AvgDialog_58292_Content_41 = {
    Text = "Fass es nicht an!"
  },
  AvgDialog_58292_Content_42 = {
    Text = "Kaum waren die Worte gefallen, trat der Detektiv schon gelangweilt gegen den Sarg. Die Antwort war totenstille"
  },
  AvgDialog_58292_Content_43 = {
    Text = "Seltsam... Es reagiert nicht auf deine Berührung?"
  },
  AvgDialog_58292_Content_44 = {
    Text = "Oh? Dann sag mal, wie sollte es reagieren?"
  },
  AvgDialog_58292_Content_45 = {
    Text = "Du hast Lek alles erzählt, was du zuvor erlebt hast"
  },
  AvgDialog_58292_Content_46 = {
    Text = "Verstehe... ich habe es verstanden!"
  },
  AvgDialog_58292_Content_47 = {
    Text = "Hier drin muss eine geheimnisvolle, mächtige Mumie sein!"
  },
  AvgDialog_58292_Content_48 = {
    Text = "Ryker hockte sich plötzlich hin und sprach in einer „Sprache“, die du überhaupt nicht verstehen konntest"
  },
  AvgDialog_58292_Content_49 = {
    Text = "Mudchoke! Racoonmire @3!"
  },
  AvgDialog_58292_Content_5 = {
    Text = "Benutz dein kleines Hirn, Detektiv. Wenn ich ihn gefunden hätte, würde ich dann noch hier stehen?"
  },
  AvgDialog_58292_Content_50 = {
    Text = "...Was sagst du da?"
  },
  AvgDialog_58292_Content_51 = {
    Text = "Das ist die Sprache der Lemouahe. ‚Waxylaik klu, nedkesanmin zy?'"
  },
  AvgDialog_58292_Content_52 = {
    Text = "Der schwarze Sarg blieb feierlich und still, unbeeindruckt von den freundlichen, aber etwas verwirrenden Begrüßungen."
  },
  AvgDialog_58292_Content_53 = {
    Text = "Schon gut, genug. Ich habe die alte Sprache von Aram gehört, und sie klingt ganz anders als deine."
  },
  AvgDialog_58292_Content_54 = {
    Text = "Tsk, wie langweilig. Zurück an die Arbeit."
  },
  AvgDialog_58292_Content_55 = {
    Text = "Ryker stand auf, streckte sich träge und schnippte zweimal mit den Fingern in der Luft."
  },
  AvgDialog_58292_Content_56 = {
    Text = "Also gut, alle zusammen, ich weiß, wer der Mörder ist. Um Zeit zu sparen, überspringe ich die Herleitung und führe euch direkt zum Täter."
  },
  AvgDialog_58292_Content_57 = {Text = "...?"},
  AvgDialog_58292_Content_58 = {
    Text = "Pff. Wenn irgendein Romanautor die Handlung so vorantreiben würde wie Herr Ryker, würde er wohl schon längst von wütenden Lesern an Laternenmasten aufgehängt werden."
  },
  AvgDialog_58292_Content_59 = {
    Text = "Nicht bereit, auch nur den kleinsten Hinweis zu teilen?"
  },
  AvgDialog_58292_Content_6 = {
    Text = "Äh... Das ergibt Sinn."
  },
  AvgDialog_58292_Content_60 = {
    Text = "Ryker kratzte sich gereizt am Kopf."
  },
  AvgDialog_58292_Content_61 = {
    Text = "Schallplatte. Ihre Anwesenheit deutet wahrscheinlich darauf hin, dass der Mörder versuchte, ein Alibi zu fabrizieren, indem er den Tatzeitpunkt hinauszögerte."
  },
  AvgDialog_58292_Content_62 = {
    Text = "Mit anderen Worten, während die Schallplatte die Stimme des Opfers spielte, befand sich der Täter tatsächlich am Tatort."
  },
  AvgDialog_58292_Content_63 = {
    Text = "Ein cleverer Trick, aber leider bin ich nicht dem Pfad gefolgt, den der Mörder geplant hatte. Als ich das Geräusch hörte, ging ich nicht weg, sondern trat die Tür ein."
  },
  AvgDialog_58292_Content_64 = {
    Text = "Ein kompetenter Detektiv zerlegt das Alibi; ein außergewöhnlicher Detektiv erstickt das Alibi im Keim!"
  },
  AvgDialog_58292_Content_65 = {
    Text = "Hast du diesen tiefgründigen Spruch aufgeschrieben, Hanna?"
  },
  AvgDialog_58292_Content_66 = {
    Text = "Äh? Verstanden, Boss!"
  },
  AvgDialog_58292_Content_67 = {
    Text = "Aber Boss, du hast gerade gesagt, der Täter war am Tatort... Also..."
  },
  AvgDialog_58292_Content_68 = {
    Text = "Ryker zog eine Handfeuerwaffe hervor und ging gemächlich vorwärts."
  },
  AvgDialog_58292_Content_69 = {
    Text = "Nun denn, lasst uns die junge Mörderin vorstellen, die seit dem Vorfall nicht mehr aufgetaucht ist und sich nur panisch im Schatten verbergen konnte."
  },
  AvgDialog_58292_Content_7 = {
    Text = "Küche im Erdgeschoss. Der Gastgeber hat angewiesen, Essen für alle vorzubereiten."
  },
  AvgDialog_58292_Content_70 = {
    Text = "Der Detektiv bleibt vor dem Kleiderschrank stehen und klopft zweimal leicht an die Tür."
  },
  AvgDialog_58292_Content_71 = {
    Text = "Hast du immer noch vor, dich bis zum letzten Moment zu verstecken? Dann bin ich mit der Höflichkeit am Ende—"
  },
  AvgDialog_58292_Content_72 = {
    Text = "Der Detektiv reibt sich mit gequältem Blick die Schläfe mit dem Lauf seiner Waffe, bevor er die Schranktür aufreißt."
  },
  AvgDialog_58292_Content_73 = {Text = "Sorel..."},
  AvgDialog_58292_Content_74 = {Text = "?!"},
  AvgDialog_58292_Content_75 = {
    Text = "Frau Sorel!!!"
  },
  AvgDialog_58292_Content_76 = {
    Text = "Keine lahmen Ausreden, kein beschämendes Verstecken, kein tränenreiches Geständnis."
  },
  AvgDialog_58292_Content_77 = {
    Text = "Nur Sorels Körper ruhte still in der Ecke, das Einschussloch in ihrer Stirn unübersehbar, als würde es die Selbstgefälligkeit des Detektivs verhöhnen."
  },
  AvgDialog_58292_Content_78 = {
    Text = "Nein... Das kann nicht sein..."
  },
  AvgDialog_58292_Content_79 = {
    Text = "Klirr, klirr, klirr!"
  },
  AvgDialog_58292_Content_8 = {
    Text = "Niemand ging während dieser Zeit in die Küche, was bedeutet, dass auch Fräulein Erica kein Alibi hat..."
  },
  AvgDialog_58292_Content_80 = {
    Text = "Es klingt, als hätte jemand eine falsche Schlussfolgerung gezogen!"
  },
  AvgDialog_58292_Content_81 = {
    Text = "Einen unschuldigen Menschen zu beschuldigen ist eine unverzeihliche Sünde; es ist Zeit für die Bestrafung!"
  },
  AvgDialog_58292_Content_82 = {
    Text = "N war beunruhigt und hielt Sein rundes Kinn. Wenn Er nachdenkt, verlangsamt sich der Nebel um Sein Gesicht."
  },
  AvgDialog_58292_Content_83 = {
    Text = "Bestrafung, Bestrafung... Wen soll ich töten?"
  },
  AvgDialog_58292_Content_9 = {
    Text = "Verzeihung, Detektiv. Aus unserer Sicht sind Sie, der Schutzherr und Herr Ryker alle verdächtig～"
  },
  AvgDialog_58293_Content_1 = {Text = "Sargwand"},
  AvgDialog_58293_Content_10 = {
    Text = "Dies sollte unser letztes Treffen sein, und doch bleibt dein Herz unerschütterlich."
  },
  AvgDialog_58293_Content_11 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58293_Content_12 = {
    Text = "Karnak, mein Name ist Karnak."
  },
  AvgDialog_58293_Content_13 = {Text = "!!"},
  AvgDialog_58293_Content_14 = {
    Text = "Mm... was für ein seltsamer Traum. Warum bin ich in diesem Korridor... Seit ich diesen Sarg berührt habe, ist mein Verstand in Aufruhr."
  },
  AvgDialog_58293_Content_15 = {
    Text = "Tapp, tapp, tapp."
  },
  AvgDialog_58293_Content_16 = {
    Text = "Mit einer Reihe hastiger Schritte prallst du mit einem dunklen Schatten zusammen."
  },
  AvgDialog_58293_Content_17 = {
    Text = "Autsch! Steh nicht im Weg... Hmm, das ist ja {Male=Mr.,Female=Miss} Schutzherr!"
  },
  AvgDialog_58293_Content_18 = {
    Text = "Puh... Gut, dass es dir gut geht. Ich dachte..."
  },
  AvgDialog_58293_Content_19 = {
    Text = "Warum seid ihr zwei hier? Ist etwas passiert?"
  },
  AvgDialog_58293_Content_2 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58293_Content_20 = {
    Text = "Im Verborgenen hat das Jagdspiel begonnen～"
  },
  AvgDialog_58293_Content_21 = {
    Text = "Ein schlanker Körper bewegte sich durch die Dunkelheit; Casiah landete leichtfüßig vor dir, als wäre es Zauberei."
  },
  AvgDialog_58293_Content_22 = {
    Text = "Ich weiß, woher der Schuss kam. Willst du mit mir nachsehen gehen? Ich habe ein bisschen Angst, allein zu gehen."
  },
  AvgDialog_58293_Content_23 = {
    Text = "Wo kommst du denn her..."
  },
  AvgDialog_58293_Content_24 = {
    Text = "Casiah hat gerade eben auf dem Kronleuchter geschlafen. Wie man so schön sagt: Je höher man steht, desto weiter sieht man..."
  },
  AvgDialog_58293_Content_25 = {
    Text = "Ich sah alles, weißt du~"
  },
  AvgDialog_58293_Content_26 = {
    Text = "Casiah zwinkert dir verspielt zu und lacht fröhlich."
  },
  AvgDialog_58293_Content_27 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58293_Content_28 = {
    Text = "Was steht ihr alle so herum? Wollt ihr nicht die Ersten sein, die den Tatort begutachten?"
  },
  AvgDialog_58293_Content_29 = {
    Text = [[
Ferland-Anwesen
Arbeitszimmer im Ersten Stock]]
  },
  AvgDialog_58293_Content_3 = {
    Text = "Hier trennen sich unsere Wege. Suchst du immer noch nach der <Yellow:Wand der Wahrheit>?"
  },
  AvgDialog_58293_Content_30 = {
    Text = "Du hast die Tür zum Arbeitszimmer aufgestoßen."
  },
  AvgDialog_58293_Content_31 = {
    Text = "D-Das ist..."
  },
  AvgDialog_58293_Content_32 = {
    Text = "Herr Dexter?!"
  },
  AvgDialog_58293_Content_33 = {
    Text = "Ein Mann hängt an einem Seil von den Dachbalken, wie ein Blatt, das im Wind treibt. Sein Gesicht ist von einer bläulich-grünen Blässe überzogen, und seine Augen quellen aus den Höhlen hervor."
  },
  AvgDialog_58293_Content_34 = {
    Text = "Alle, bitte bewahrt Ruhe, um den Tatort nicht zu kontaminieren."
  },
  AvgDialog_58293_Content_35 = {
    Text = "Tat... ort?"
  },
  AvgDialog_58293_Content_36 = {
    Text = "Schau nicht hin, der Kerl ist mausetot. Lass mich raten – ist das das Rätsel, das man uns hinterlassen hat?"
  },
  AvgDialog_58293_Content_37 = {
    Text = "Eine Art Detektiv- und Deduktionsspiel?"
  },
  AvgDialog_58293_Content_38 = {
    Text = "Bingo! Korrigieren~!"
  },
  AvgDialog_58293_Content_39 = {
    Text = "Wer also hat in einer solch verschneiten Nacht einen Gentleman von solcher Vornehmheit so grausam ermordet?"
  },
  AvgDialog_58293_Content_4 = {
    Text = "\"Du\" nickte."
  },
  AvgDialog_58293_Content_40 = {
    Text = "Bitte versucht, die Wahrheit aufzudecken, liebe Detektive."
  },
  AvgDialog_58293_Content_41 = {
    Text = "Wie seltsam, solltet nicht Ihr der Hauptverdächtige sein, lieber Herr N?"
  },
  AvgDialog_58293_Content_42 = {
    Text = "Hust, hust, erlaubt mir, es genauer zu formulieren — Findet den Mörder, der sich als einer meiner Klone ausgibt!"
  },
  AvgDialog_58293_Content_43 = {
    Text = "Direkt unter euch!"
  },
  AvgDialog_58293_Content_44 = {
    Text = "Eine tödliche Stille."
  },
  AvgDialog_58293_Content_45 = {
    Text = "Angst und Unbehagen breiteten sich leise unter den Anwesenden aus. Blicke wanderten unauffällig umher, während jeder still über den Wahrheitsgehalt von Ns Worten nachdachte."
  },
  AvgDialog_58293_Content_46 = {
    Text = "Was, wenn wir dieses Spiel ablehnen?"
  },
  AvgDialog_58293_Content_47 = {
    Text = "Wisst ihr, was für einen Spieledesigner wie mich, der vor Idealen und Leidenschaft nur so strotzt, am wichtigsten ist?"
  },
  AvgDialog_58293_Content_48 = {
    Text = "Natürlich das Engagement der Spieler! Wenn sich niemand dafür interessiert, muss ich bedauerlicherweise das Ende des Spiels verkünden!"
  },
  AvgDialog_58293_Content_49 = {
    Text = "Keine Reaktion. Alle warten auf das „Aber“ —"
  },
  AvgDialog_58293_Content_5 = {
    Text = "Dann werde ich nicht versuchen, dich umzustimmen. Ehrlich gesagt, ich konnte dich nie durchschauen... Du siehst jung aus, aber du wirkst, als hättest du schon Tausende von Jahren gelebt."
  },
  AvgDialog_58293_Content_50 = {Text = "Aber!"},
  AvgDialog_58293_Content_51 = {
    Text = "Lebt wohl für immer, armer Herr Dexter und Fräulein Elsa."
  },
  AvgDialog_58293_Content_52 = {
    Text = [[
Mythag Krankenhaus
Inzwischen...]]
  },
  AvgDialog_58293_Content_53 = {
    Text = "Wie ist die Lage?"
  },
  AvgDialog_58293_Content_54 = {
    Text = "Die Lage ist nicht optimistisch. Elsa hat schwere intrakranielle Blutungen, steigenden Liquordruck, und ihre Körpertemperatur bleibt über 38 °C."
  },
  AvgDialog_58293_Content_55 = {
    Text = "Der Schutzherr und Hanna sind in einen Zustand des Deliriums gefallen. Obwohl sie in einem ständigen Schlaf verharren, sind ihre körperlichen Werte normal."
  },
  AvgDialog_58293_Content_56 = {
    Text = "Verstanden. Und... was ist mit ihm?"
  },
  AvgDialog_58293_Content_57 = {
    Text = "Das Mädchen nannte keinen Namen, doch alle Anwesenden wussten, wen sie meinte."
  },
  AvgDialog_58293_Content_58 = {
    Text = "Herr Dexter... Die vorläufige Diagnose lautet, dass neuraler Druck einen reflektorischen Herzstillstand verursacht hat, ähnlich einer mechanischen Asphyxie."
  },
  AvgDialog_58293_Content_59 = {
    Text = "Herzstillstand?"
  },
  AvgDialog_58293_Content_6 = {
    Text = "Wie auch immer, danke. Ich habe einen Weg gefunden, das Siegel zu brechen. Nächster Schritt: nach Rom reisen und die Bestie befreien..."
  },
  AvgDialog_58293_Content_60 = {
    Text = "Winkle nickt."
  },
  AvgDialog_58293_Content_61 = {
    Text = "Rettung fehlgeschlagen. Atmung vor fünf Minuten ausgesetzt. Theoretisch..."
  },
  AvgDialog_58293_Content_62 = {
    Text = "Er ist tot."
  },
  AvgDialog_58293_Content_63 = {
    Text = [[
Ferland-Anwesen
Arbeitszimmer im Ersten Stock]]
  },
  AvgDialog_58293_Content_64 = {
    Text = "Mit anderen Worten, wenn wir uns nicht an deine Regeln halten, wachen Menschen, die hier sterben, auch in der realen Welt nicht mehr auf?"
  },
  AvgDialog_58293_Content_65 = {
    Text = "N nickte zufrieden."
  },
  AvgDialog_58293_Content_66 = {
    Text = "Wie erwartet, du bist derjenige, der mich am besten kennt!"
  },
  AvgDialog_58293_Content_67 = {
    Text = "...Heh, darauf bin ich ganz und gar nicht stolz."
  },
  AvgDialog_58293_Content_68 = {
    Text = "Was, wenn das nur ein Bluff ist? Wie kannst du beweisen, dass du nicht lügst?"
  },
  AvgDialog_58293_Content_69 = {
    Text = "Natürlich kann ich es beweisen — aber ich will nicht, hehe."
  },
  AvgDialog_58293_Content_7 = {
    Text = "Der Zauberer packte mühsam seine Sachen, und nachdem er ein paar Schritte gegangen war, drehte er sich um."
  },
  AvgDialog_58293_Content_70 = {
    Text = "Oder ihr könntet es riskieren und das Spiel sofort beenden, zurückkehren in eure niedliche kleine Welt, in der sich nichts verändert hat."
  },
  AvgDialog_58293_Content_71 = {
    Text = "Die Wärme des Bettes bleibt konstant, Prüfungen gehen weiter wie gewohnt, und alle bleiben gesund und am Leben."
  },
  AvgDialog_58293_Content_72 = {
    Text = "N schaute Ryker an und breitete leidenschaftlich seine kleinen Arme aus."
  },
  AvgDialog_58293_Content_73 = {
    Text = "Willst du wetten? Das ist doch das, worin du am besten bist."
  },
  AvgDialog_58293_Content_74 = {
    Text = "Tut mir leid, ich spiele nie mit dem Leben anderer Menschen."
  },
  AvgDialog_58293_Content_75 = {
    Text = "Das Spiel hat gerade erst begonnen. Es jetzt zu beenden wäre viel zu langweilig!"
  },
  AvgDialog_58293_Content_76 = {
    Text = "Casiah richtet sich auf und hebt rasch ihre rechte Hand."
  },
  AvgDialog_58293_Content_77 = {
    Text = "Piep piep! Ich stimme dafür, weiterzuspielen～!"
  },
  AvgDialog_58293_Content_78 = {
    Text = "Nach langer Diskussion kamen alle aus unterschiedlichen Gründen überraschenderweise zu einem Konsens."
  },
  AvgDialog_58293_Content_79 = {
    Text = "Ich bin wirklich gerührt! Danke euch allen, dass ihr mein Design bedingungslos respektiert!"
  },
  AvgDialog_58293_Content_8 = {
    Text = "Hey, du hast mir deinen Namen noch nicht gesagt."
  },
  AvgDialog_58293_Content_80 = {
    Text = "Hiermit erkläre ich: <Red:Die zweite Prüfung beginnt offiziell!>"
  },
  AvgDialog_58293_Content_81 = {
    Text = "Ihr alle habt volle zwei Stunden, um das Rätsel zu lösen～"
  },
  AvgDialog_58293_Content_82 = {
    Text = "Einfach zwei Stunden... das reicht nicht."
  },
  AvgDialog_58293_Content_83 = {
    Text = "Oh ho ho, während einige am großen Lord N zweifelten, sind weitere zehn Sekunden verstrichen."
  },
  AvgDialog_58293_Content_84 = {
    Text = "Nun, viel Spaß, alle zusammen~"
  },
  AvgDialog_58293_Content_85 = {
    Text = "Nach diesen Worten verwandelte sich N in schwarzen Rauch und verschwand lautlos."
  },
  AvgDialog_58293_Content_86 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58293_Content_87 = {
    Text = "Ryker überlegte einen Moment, bevor er dir plötzlich in die Wange kniff."
  },
  AvgDialog_58293_Content_88 = {
    Text = "Pain... Hey, was soll das?!"
  },
  AvgDialog_58293_Content_89 = {
    Text = "Freigeben. Lass uns überprüfen, ob du eine Fälschung bist."
  },
  AvgDialog_58293_Content_9 = {
    Text = "Der Wind trug Wellen goldenen feinen Sandes herbei. Der zerlumpte Zauberer lehnte sich gegen den blauen Himmel, eine seltene Güte zeigte sich auf seinem geröteten Gesicht."
  },
  AvgDialog_58293_Content_90 = {
    Text = "Mm, ein gewisses Maß an Vorsicht ist nötig. Also—"
  },
  AvgDialog_58293_Content_91 = {
    Text = "Du hast eine Handvoll von Rykers flauschigem Fell gepackt und ein paar Strähnen herausgezogen."
  },
  AvgDialog_58293_Content_92 = {Text = "Fauuch!!"},
  AvgDialog_58293_Content_93 = {
    Text = "Schnüffel... Es riecht echt."
  },
  AvgDialog_58293_Content_94 = {
    Text = "„Gern geschehen. Die gehören alle dir. Denk dran, sie zu waschen, luftzutrocknen und ordentlich aufzubewahren.\""
  },
  AvgDialog_58294_Content_1 = {
    Text = "Unter der Realität"
  },
  AvgDialog_58294_Content_10 = {
    Text = "Er trat entschlossen vor und ging auf N zu."
  },
  AvgDialog_58294_Content_11 = {
    Text = "Falsche Schlussfolgerung? Unmöglich. Du musst etwas manipuliert haben."
  },
  AvgDialog_58294_Content_12 = {
    Text = "Hast du die zwei verschiedenen Würgemale und die fehlenden Schuhe völlig vergessen?"
  },
  AvgDialog_58294_Content_13 = {
    Text = "Ich kann dir auf der Stelle Dutzende Möglichkeiten aufzählen, aber sind sie wirklich von Bedeutung? Oder ist es so, dass sie keine Rolle gespielt hätten, außer unter deiner Anordnung —"
  },
  AvgDialog_58294_Content_14 = {
    Text = "„Ursprünglich“? Das ist seltsam. Wenn meine Aufgabe darin besteht, die Wahrheit des <Red:Geheimgangs> aufzudecken, dann ist der Geheimgang deine einzige aktuelle Realität und Referenz."
  },
  AvgDialog_58294_Content_15 = {
    Text = "Warum verweilt jemand immer bei der sogenannten „Vergangenheit“?"
  },
  AvgDialog_58294_Content_16 = {Text = "!!"},
  AvgDialog_58294_Content_17 = {
    Text = "Vielleicht hast du diesen Fall einst brillant gelöst, ein klägliches Bisschen Eitelkeit und Aufmerksamkeit gewonnen und schwelgst seitdem in Erinnerungen daran."
  },
  AvgDialog_58294_Content_18 = {
    Text = "Aber leider hast du hier alles völlig vermasselt, Detektiv."
  },
  AvgDialog_58294_Content_19 = {
    Text = "N hob langsam die Hand und schnippte leicht mit den Fingern."
  },
  AvgDialog_58294_Content_2 = {
    Text = "Wen sollte ich töten..."
  },
  AvgDialog_58294_Content_20 = {Text = "...Hä?"},
  AvgDialog_58294_Content_21 = {
    Text = "Im nächsten Moment strömten plötzlich Schwaden schwarzen Nebels aus Casiahs Körper, die die ganze Zeit von der Seite zugesehen hatte."
  },
  AvgDialog_58294_Content_22 = {
    Text = "Es ist entschieden. Die Bestrafung beginnt mit dir."
  },
  AvgDialog_58294_Content_23 = {
    Text = "Hey... sollte dieser Kerl nicht die Schlussfolgerung vermasselt haben? Warum muss Casiah dafür büßen!"
  },
  AvgDialog_58294_Content_24 = {
    Text = "Nein... Es ist so schmerzhaft..."
  },
  AvgDialog_58294_Content_25 = {
    Text = "Siehst du? Jede dumme Entscheidung, die du triffst, hat Konsequenzen für jemand anderen, genau wie im echten Leben."
  },
  AvgDialog_58294_Content_26 = {Text = "?!"},
  AvgDialog_58294_Content_27 = {
    Text = "Schnüff, schnüff... Ich hatte noch nicht genug Spaß... Warum sollte es mich kümmern..."
  },
  AvgDialog_58294_Content_28 = {
    Text = "Casiah starrt Ryker wütend an und schleudert den Gehstock."
  },
  AvgDialog_58294_Content_29 = {
    Text = "Das ist alles deine Schuld! So dumm — au!"
  },
  AvgDialog_58294_Content_3 = {
    Text = "<Shake:Es tut uns so, so leid, Herr N!> Die Schlussfolgerung eben war Unsinn von diesem Kerl. Wir sind alle anderer Meinung!"
  },
  AvgDialog_58294_Content_30 = {
    Text = "Bevor sie ihre Worte beenden konnte, verschwand Casiah vollständig vor deinen Augen, als wäre sie mit einem Radiergummi aus dem Bauplan gelöscht worden."
  },
  AvgDialog_58294_Content_31 = {
    Text = "Fräulein Casiah!!"
  },
  AvgDialog_58294_Content_32 = {
    Text = "Schnief... Sie hat versprochen, mir ein paar Zaubertricks beizubringen..."
  },
  AvgDialog_58294_Content_33 = {
    Text = "In Ordnung, alle zusammen, ihr habt noch eine Stunde. Wenn es keine weiteren Fragen gibt, dann—"
  },
  AvgDialog_58294_Content_34 = {
    Text = "...und so weiter."
  },
  AvgDialog_58294_Content_35 = {
    Text = "Der Detektiv klopft dir auf die Schulter und tritt dann vor."
  },
  AvgDialog_58294_Content_36 = {
    Text = "%player%, mach du mit der Ermittlung weiter. Ich muss ein Wörtchen mit diesem Kerl reden."
  },
  AvgDialog_58294_Content_37 = {
    Text = "...Verstanden."
  },
  AvgDialog_58294_Content_38 = {
    Text = "Die versammelte Menge zerstreute sich erneut, als zähflüssige Dunkelheit hervorquoll und rasch das gesamte Gebiet verschlang."
  },
  AvgDialog_58294_Content_39 = {
    Text = "In Ordnung, jetzt können wir frei reden. Was hältst du von meinem neuen Avatar?"
  },
  AvgDialog_58294_Content_4 = {
    Text = "Ich wollte ihm von Anfang an widersprechen, aber hatte nie die Gelegenheit..."
  },
  AvgDialog_58294_Content_40 = {
    Text = "Ich bin eher an dein jetziges Aussehen gewöhnt."
  },
  AvgDialog_58294_Content_41 = {
    Text = "Wie schade. In letzter Zeit habe ich darüber nachgedacht, ob mein Aussehen zu furchterregend ist und alle deshalb Angst vor mir haben."
  },
  AvgDialog_58294_Content_42 = {
    Text = "Glaub mir, du wärst beliebter, wenn du diese dunklen und verdrehten Spiele aufgeben würdest — kein Köpfetauschen nötig."
  },
  AvgDialog_58294_Content_43 = {
    Text = "Das geht nicht. Würdest du das Atmen aufgeben?"
  },
  AvgDialog_58294_Content_44 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58294_Content_45 = {
    Text = "In Ordnung, kommen wir zurück zum Thema."
  },
  AvgDialog_58294_Content_46 = {
    Text = "Du hast vorhin gesagt... alle werden für mein schlechtes Urteilsvermögen bezahlen, genau wie es in der realen Welt geschehen würde."
  },
  AvgDialog_58294_Content_47 = {
    Text = "Könntest du es mir erklären?"
  },
  AvgDialog_58294_Content_48 = {
    Text = "N neigte Seinen Kopf, und der dunkle Nebel umhüllte Ihn rasch."
  },
  AvgDialog_58294_Content_49 = {
    Text = "In der nächsten Sekunde wechselte Er erneut Seine Gestalt."
  },
  AvgDialog_58294_Content_5 = {
    Text = "Fräulein Hanna, ich nehme an, Sie sind ebenfalls nicht einverstanden mit Herrn Rykers Schlussfolgerung eben?"
  },
  AvgDialog_58294_Content_50 = {
    Text = "Willst du es wirklich wissen? Komm mir bloß nicht hinterher heulend an. Ich hasse menschliche Tränen!"
  },
  AvgDialog_58294_Content_51 = {
    Text = "Ryker verschränkte die Arme und starrte N ausdruckslos an."
  },
  AvgDialog_58294_Content_52 = {
    Text = "Hmph, ich kann dir nichts abschlagen. Wo soll ich anfangen... Ah, erinnerst du dich an das Mädchen namens Elsa?"
  },
  AvgDialog_58294_Content_53 = {
    Text = "In der Handlung zeigte der mutige Detektiv dem Mädchen den Weg und half ihr dann, die Auflösungsmonster abzuwehren."
  },
  AvgDialog_58294_Content_54 = {
    Text = "Aber in Wirklichkeit folgte das Mädchen den Anweisungen des Detektivs, betrat eine Sackgasse und wurde von dem verfolgenden Auflösungsmonster getötet."
  },
  AvgDialog_58294_Content_55 = {Text = "?!"},
  AvgDialog_58294_Content_56 = {
    Text = "Pst... Ruhe, hör mir zu. In der Handlung löst ein vorbeikommender Glücksspieler einen Mord in einer mysteriösen Villa und verwandelt sich in einen großen Detektiv."
  },
  AvgDialog_58294_Content_57 = {
    Text = "Aber in Wirklichkeit beschuldigte der Glücksspieler einen Unschuldigen, wodurch der wahre Mörder ungeschoren davonkam."
  },
  AvgDialog_58294_Content_58 = {
    Text = "Ich kann unzählige solcher Beispiele nennen. Detektiv, hast du jemals in Betracht gezogen, dass dein „Glück“ nicht der Grund ist, warum du es so weit geschafft hast, sondern vielmehr das Ergebnis?"
  },
  AvgDialog_58294_Content_59 = {
    Text = "Ergebnis...?"
  },
  AvgDialog_58294_Content_6 = {
    Text = "Ah... I-Ich bin auch nicht einverstanden! Nur ein Wahnsinniger könnte sich so etwas ausdenken!"
  },
  AvgDialog_58294_Content_60 = {
    Text = "Ein verändertes Ergebnis. Der Gott schenkt Sterblichen Glück, und der Preis dafür ist, dass die Übrigen das Leid an seiner Stelle tragen müssen."
  },
  AvgDialog_58294_Content_61 = {
    Text = "Wie ich bereits sagte, ist der Bereich eure Realität."
  },
  AvgDialog_58294_Content_62 = {
    Text = "Du meinst, alles, was ich durch Glück erlangt habe, und die Menschen, denen ich in der Vergangenheit geholfen habe... war alles eine Lüge?"
  },
  AvgDialog_58294_Content_63 = {
    Text = "Hey, was soll der weinerliche Blick? Denk daran, in einer Lüge zu leben kann auch eine Art Glück sein."
  },
  AvgDialog_58294_Content_64 = {
    Text = "Wenn du mir nicht glaubst, dann wirf einen Blick auf die wahre Gestalt von Aram, den du einst gerettet hast—"
  },
  AvgDialog_58294_Content_65 = {
    Text = "Flammen lecken am Himmel, das Geräusch von Schreien und der Geruch von verbranntem Fleisch machen dich schwindelig."
  },
  AvgDialog_58294_Content_66 = {
    Text = "Blutrote Adern geronnenen Blutes sprossen aus der Basis des Mutterbaums und streckten sich freudig dem Horizont entgegen, der kein Ende zu haben schien."
  },
  AvgDialog_58294_Content_67 = {
    Text = "Haufen von Fleisch und Gliedmaßen sind wie riesige Schreine unter einem trüb gelben Himmel aufgetürmt und verschlingen selbst das Sonnenlicht."
  },
  AvgDialog_58294_Content_68 = {
    Text = "Im Zentrum des Schreins sah Ryker sein eigenes Gesicht. Es war grau und matt, mit hängenden Augenlidern, und wirkte äußerst fügsam."
  },
  AvgDialog_58294_Content_69 = {
    Text = "Wäre nicht die Hälfte seines Kopfes abgetrennt gewesen, wodurch ein von Maden wimmelnder Hirnstamm freigelegt wurde, wäre dies ein makelloses Heiligengesicht gewesen."
  },
  AvgDialog_58294_Content_7 = {
    Text = "...Wahnsinn?"
  },
  AvgDialog_58294_Content_70 = {
    Text = "<Red:Die wahre Handlung>: Du hast es nicht geschafft, Casiah aufzuhalten, und du hast es auch nicht geschafft, Herbert aufzuhalten. Du hast es nicht einmal bis zu Arams Lager geschafft."
  },
  AvgDialog_58294_Content_71 = {
    Text = "Die Wahrheit ist, du hast nichts erreicht. Und deshalb ist Aram so geendet."
  },
  AvgDialog_58294_Content_72 = {
    Text = "Ist das die Realität, die du dir wünschst, mein lieber Herr Glücksspieler?"
  },
  AvgDialog_58294_Content_73 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58294_Content_74 = {
    Text = "Die „Realität“ ebbt davon und lässt Ryker allein in der Dunkelheit zurück."
  },
  AvgDialog_58294_Content_75 = {
    Text = "Hah. Du hast dir also all diese Mühe gemacht, ein Spiel zu entwerfen, nur um mich an meine Fehlschläge zu erinnern?"
  },
  AvgDialog_58294_Content_76 = {
    Text = "Das ist nicht nötig. Wenn es eine Wahrheit gibt, die mich diese Welt gelehrt hat, dann diese: Ich bin wertlos. Es tut mir leid. Wie bedauerlich."
  },
  AvgDialog_58294_Content_77 = {
    Text = "Einfach eine kleine Warnung. Ich will nicht, dass sich wiederholt, was während deiner Zeit in Aram passiert ist."
  },
  AvgDialog_58294_Content_78 = {
    Text = "Wenn du noch so eine sinnlose Aktion abziehst, die Leben gefährdet, werden noch mehr Menschen verschwinden. Verstanden?"
  },
  AvgDialog_58294_Content_79 = {
    Text = "...Verstanden."
  },
  AvgDialog_58294_Content_8 = {
    Text = "Halt die Klappe."
  },
  AvgDialog_58294_Content_80 = {
    Text = "„Der Detektiv senkte den Kopf und antwortete träge.\""
  },
  AvgDialog_58294_Content_81 = {
    Text = "Als sich der Vorhang der Dunkelheit hob, kehrte er in sein vertrautes Arbeitszimmer zurück."
  },
  AvgDialog_58294_Content_82 = {
    Text = "Puh... Endlich wach! Du standest plötzlich reglos da und hast uns zu Tode erschreckt!"
  },
  AvgDialog_58294_Content_83 = {
    Text = "Was ist passiert, Herr Ryker? Du siehst schrecklich aus."
  },
  AvgDialog_58294_Content_84 = {
    Text = "Nichts. Ich brauche etwas Zeit für mich. Ich bin bald zurück."
  },
  AvgDialog_58294_Content_85 = {
    Text = "„Der Detektiv blieb ruhig und schenkte euch sogar ein warmes Lächeln.\""
  },
  AvgDialog_58294_Content_86 = {
    Text = "Er ging beinahe, ohne sich auch nur einmal nach euch umzudrehen."
  },
  AvgDialog_58294_Content_87 = {
    Text = "Mr. Ryker...?"
  },
  AvgDialog_58294_Content_9 = {
    Text = "Du trittst dem Detektiv auf den Fuß, aber der kampflustige Detektiv ignoriert deinen aggressiven Hinweis."
  },
  AvgDialog_58326_Content_1 = {
    Text = "Umgekehrte Deduktion"
  },
  AvgDialog_58326_Content_10 = {
    Text = "Einmal klopfen für ja, zweimal klopfen für nein. Schaffst du das?"
  },
  AvgDialog_58326_Content_11 = {
    Text = "Durch das dicke Sandelholzbrett hindurch hatte Rykers Stimme eine ungewöhnlich sanfte und unwirkliche Qualität."
  },
  AvgDialog_58326_Content_12 = {
    Text = "Du klopfst leicht."
  },
  AvgDialog_58326_Content_13 = {
    Text = "Großartig! Eigentlich ist es ganz einfach. Es gibt noch nur drei Fragen."
  },
  AvgDialog_58326_Content_14 = {
    Text = "Erste Frage, bist du in etwas eingesperrt?"
  },
  AvgDialog_58326_Content_15 = {
    Text = "<Yellow:Dumpf.>"
  },
  AvgDialog_58326_Content_16 = {
    Text = "Zweite Frage, gehörst du zu uns? Mit „uns“ meine ich diejenigen, die den Geheimgang von diesem Typen betreten haben."
  },
  AvgDialog_58326_Content_17 = {
    Text = "<Yellow:Dumpf.>"
  },
  AvgDialog_58326_Content_18 = {
    Text = "Großartig, mein Instinkt lügt nie. Die dritte Frage..."
  },
  AvgDialog_58326_Content_19 = {
    Text = "Bist du %player%?"
  },
  AvgDialog_58326_Content_2 = {
    Text = "Das Klopfen hält an."
  },
  AvgDialog_58326_Content_20 = {
    Text = "Du schlägst kräftig gegen den Sarg und hörst dann ein leises Lachen."
  },
  AvgDialog_58326_Content_21 = {
    Text = "Du bist es wirklich. Hab keine Angst; ich werde alle Rätsel lösen und dich retten. Bleib hier und bleib in Sicherheit, verstanden?"
  },
  AvgDialog_58326_Content_22 = {
    Text = "<Yellow:Dumpf.>"
  },
  AvgDialog_58326_Content_23 = {
    Text = "Sehr gut, mein Freund. Leb wohl."
  },
  AvgDialog_58326_Content_24 = {
    Text = "Das Rascheln von Kleidung und sich allmählich entfernende Schritte dringen an meine Ohren."
  },
  AvgDialog_58326_Content_25 = {
    Text = "Du stößt einen tiefen Seufzer aus und schließt die Augen. Doch nicht lange danach kehren die Schritte zurück."
  },
  AvgDialog_58326_Content_26 = {
    Text = "Entschuldigung, ich habe tatsächlich die wichtigste Frage vergessen. Das ist entscheidend für meine nächsten Schritte."
  },
  AvgDialog_58326_Content_27 = {
    Text = "Du wartest still auf diese „wichtige Frage“."
  },
  AvgDialog_58326_Content_28 = {
    Text = "Vertraust du mir?"
  },
  AvgDialog_58326_Content_29 = {
    Text = "<Gray:Was ist das denn für eine Frage...>"
  },
  AvgDialog_58326_Content_3 = {
    Text = "Hey, Freund im Sarg, alles in Ordnung bei dir?"
  },
  AvgDialog_58326_Content_30 = {
    Text = "Du lächelst und berührst sanft die glatte Innenfläche des Sarges."
  },
  AvgDialog_58326_Content_31 = {Text = "—Plumps."},
  AvgDialog_58326_Content_32 = {
    Text = "Ich vertraue dir."
  },
  AvgDialog_58326_Content_33 = {
    Text = "Ich verstehe. Dein Gespür war schon immer scharf."
  },
  AvgDialog_58326_Content_34 = {
    Text = "Leider... {Male=he,Female=she} ist im Bewusstsein von <Yellow:diesem Kerl> gefangen, selbst wenn du die letzte Wahrheit aufdeckst, nützt es nichts."
  },
  AvgDialog_58326_Content_35 = {
    Text = "Die Realität ist, dass {Male=he,Female=she} für immer im sorgfältig ausgewählten Bewusstsein des Gefäßes gefangen sein wird."
  },
  AvgDialog_58326_Content_36 = {Text = "?!"},
  AvgDialog_58326_Content_37 = {
    Text = "Du hast gesagt: „Sobald alle Wahrheiten enthüllt sind...\""
  },
  AvgDialog_58326_Content_38 = {
    Text = "Der langsam fließende schwarze Nebel auf Ns Gesicht kräuselte sich behaglich, als würde er eine seltene Delikatesse genießen."
  },
  AvgDialog_58326_Content_39 = {
    Text = "Heh... es ist das erste Mal, dass ich diesen Ausdruck bei dir sehe. Schade, Wut wird nichts lösen."
  },
  AvgDialog_58326_Content_4 = {
    Text = "Eine leichte und fröhliche Stimme ertönt, als wäre sie mit magischer Kraft erfüllt, und bringt deine Tränen augenblicklich zum Versiegen."
  },
  AvgDialog_58326_Content_40 = {
    Text = "Ich habe nur versprochen, den Geheimgang aufzulösen, nicht, dass alle in Sicherheit wären."
  },
  AvgDialog_58326_Content_41 = {
    Text = "Verabschiede dich von deinem kleinen Freund, Detektiv."
  },
  AvgDialog_58326_Content_42 = {
    Text = "N hob einen Finger, doch im nächsten Moment—"
  },
  AvgDialog_58326_Content_43 = {
    Text = "<Red:Der Albtraum ist vorbei. Öffne deine Augen.>"
  },
  AvgDialog_58326_Content_44 = {Text = "Donnern..."},
  AvgDialog_58326_Content_45 = {
    Text = "Der Boden darunter bricht plötzlich auf, und eine schwarze Königsnatter schießt aus dem bodenlosen Abgrund empor und durchbohrt blitzschnell Ns Körper."
  },
  AvgDialog_58326_Content_46 = {Text = "...?"},
  AvgDialog_58326_Content_47 = {
    Text = "Zur Klarstellung: 80% meines Körpers bestehen aus Nebel, und die restlichen 20% sind ebenfalls Nebel. Diese vergeblichen Tricks—"
  },
  AvgDialog_58326_Content_48 = {
    Text = "Das silberne Schimmern leuchtet plötzlich auf, wie ein Scheinwerfer, der den Beginn einer Vorstellung ankündigt."
  },
  AvgDialog_58326_Content_49 = {
    Text = "Ein Student mit lockigem Haar rieb sich mit einer Hand die steife Schulter, hielt in der anderen einen silbernen Schlüssel und trat aus den Schatten hervor."
  },
  AvgDialog_58326_Content_5 = {
    Text = "Entschuldige, wenn ich vorhin etwas unhöflich zu dir war."
  },
  AvgDialog_58326_Content_50 = {
    Text = "Puh... Endlich geschafft."
  },
  AvgDialog_58326_Content_51 = {
    Text = "Wie erwartet von der Person, der ich vertraue! Ich wusste, dass du dich nicht so leicht fangen lässt."
  },
  AvgDialog_58326_Content_52 = {
    Text = "Hmm, natürlich."
  },
  AvgDialog_58326_Content_53 = {
    Text = "Dank der neuen Freunde, die ich im Sarg kennengelernt habe."
  },
  AvgDialog_58326_Content_54 = {Text = "Zisch..."},
  AvgDialog_58326_Content_55 = {
    Text = "Schlange...?"
  },
  AvgDialog_58326_Content_56 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58326_Content_57 = {
    Text = "Lange nicht gesehen, Apophis."
  },
  AvgDialog_58326_Content_6 = {
    Text = "Aber ich habe jetzt viele Fragen und würde dich gerne dazu befragen. Kannst du gerade nicht reden?"
  },
  AvgDialog_58326_Content_7 = {
    Text = "<Change>Ja!!"
  },
  AvgDialog_58326_Content_8 = {
    Text = "Du sammelst all deine Kraft, um zu sprechen, doch die Worte verwandeln sich in unzusammenhängendes Murmeln."
  },
  AvgDialog_58326_Content_9 = {
    Text = "Das macht die Sache komplizierter... Oh, kannst du noch deine Hand bewegen?"
  },
  AvgDialog_58327_Content_1 = {
    Text = "Viel Glück!"
  },
  AvgDialog_58327_Content_10 = {
    Text = "Dexter zuckt unschuldig mit den Schultern."
  },
  AvgDialog_58327_Content_11 = {
    Text = "Das würde ich auch gerne wissen. Bevor du mich verhörst, unterscheide bitte zwischen der Realität und dem Geheimgang."
  },
  AvgDialog_58327_Content_12 = {
    Text = "Schließlich sind in meiner Familie in Wirklichkeit nie Kriminalfälle vorgekommen, oder?"
  },
  AvgDialog_58327_Content_13 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58327_Content_14 = {
    Text = "Hat jemand Ryker gesehen? Elsa ist gerade aufgewacht und bittet um sein Autogramm."
  },
  AvgDialog_58327_Content_15 = {
    Text = "Hätte nie erwartet, dass Herr Ryker Bewunderer hat... Wirklich erstaunlich."
  },
  AvgDialog_58327_Content_16 = {
    Text = "Immerhin war ich es, der sie vor diesem Monster gerettet hat. Wenn ich es wirklich sagen muss..."
  },
  AvgDialog_58327_Content_17 = {
    Text = "Elsa hat sich entschieden, in Misaq zu studieren, in der Hoffnung, eines Tages wie Herr Ryker zu sein —"
  },
  AvgDialog_58327_Content_18 = {
    Text = "Werde ein Spielabhängiger?"
  },
  AvgDialog_58327_Content_19 = {
    Text = "Hingehen und anderen helfen."
  },
  AvgDialog_58327_Content_2 = {
    Text = "Misaq-Campus \n Eine Woche Später"
  },
  AvgDialog_58327_Content_20 = {
    Text = "Herr Ryker bleibt nicht gerne in der Schule. Was %player% betrifft... {Male=he,Female=she} ist früh am Morgen aufgebrochen und sagte, es gäbe etwas Dringendes."
  },
  AvgDialog_58327_Content_21 = {
    Text = "Außerdem... irgendetwas fühlt sich seltsam an. Hat N diesen Geheimgang wirklich nur erschaffen, um Ryker zu ärgern?"
  },
  AvgDialog_58327_Content_22 = {
    Text = "Vielleicht, vielleicht auch nicht. Das ist so schwierig wie das Doppelspaltexperiment. Wir sollten uns auf praktischere Angelegenheiten konzentrieren."
  },
  AvgDialog_58327_Content_23 = {
    Text = "Zum Beispiel, was sollen wir gegen Hannas schwere Erkältung tun?"
  },
  AvgDialog_58327_Content_24 = {
    Text = "In einer endlosen, pechschwarzen Höhle öffnen und schließen sich unzählige Augen langsam, wie flackernde Geisterlichter in der Dunkelheit."
  },
  AvgDialog_58327_Content_25 = {
    Text = "Ein kalter Wind fegte hindurch, und ein schwacher schwarzer Nebel wand sich in der Mitte der Höhle, kaum zu einer ätherischen humanoiden Gestalt zusammenfließend."
  },
  AvgDialog_58327_Content_26 = {
    Text = "<Change>Ugh... Meister... verletzt..."
  },
  AvgDialog_58327_Content_27 = {
    Text = "Lange nicht gesehen, meine verabscheuungswürdigen und doch geliebten Kinder. Es sind Jahrhunderte seit meinem letzten Besuch vergangen."
  },
  AvgDialog_58327_Content_28 = {
    Text = "Lasst mich sehen, ob ihr gewachsen seid... Oh, Verzeihung. Ich vergaß, dass nur noch eure Augen übrig sind."
  },
  AvgDialog_58327_Content_29 = {
    Text = "<Change>Meister... Liebe..."
  },
  AvgDialog_58327_Content_3 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58327_Content_30 = {
    Text = "In Ordnung, den Plausch heben wir uns für später auf. Ich habe etwas Interessantes bestätigt."
  },
  AvgDialog_58327_Content_31 = {
    Text = "Dieser Schutzherr kann tatsächlich mit Karnaks Bewusstsein resonieren... interessant."
  },
  AvgDialog_58327_Content_32 = {
    Text = "<Change>Hihi... Lalala..."
  },
  AvgDialog_58327_Content_33 = {
    Text = "Genug... Meine Projektion ist verletzt und braucht etwas Heilung."
  },
  AvgDialog_58327_Content_34 = {
    Text = "Alle von euch, haltet den Mund."
  },
  AvgDialog_58327_Content_35 = {Text = "—!!"},
  AvgDialog_58327_Content_36 = {
    Text = "Mit einem durchdringenden Schrei wurden alle Augen zerquetscht, und Blut begann auf den Boden zu tropfen."
  },
  AvgDialog_58327_Content_37 = {
    Text = "Der schwarze Nebel breitete sich rasch aus und verschlang gierig den Blutnebel in der Luft. Allmählich wurde die einst ätherische menschliche Gestalt endlich greifbar."
  },
  AvgDialog_58327_Content_38 = {
    Text = "Furchtbarer Geschmack..."
  },
  AvgDialog_58327_Content_39 = {
    Text = "Highgate-Friedhof\nOst-Lentiniën, Kent"
  },
  AvgDialog_58327_Content_4 = {
    Text = "Geht es dir besser? Frau Sylvia hat erwähnt, dass du wenig Appetit hast."
  },
  AvgDialog_58327_Content_40 = {
    Text = "Siehst du das? Der erste Unglückliche, den ich ins Gefängnis gebracht habe, liegt hier begraben."
  },
  AvgDialog_58327_Content_41 = {
    Text = "Du standest vor einem einsamen Grabstein in der Ecke."
  },
  AvgDialog_58327_Content_42 = {
    Text = "Den Schlussfolgerungen im Geheimgang zufolge hast du wahrscheinlich den Falschen eingesperrt. Immerhin kannst du die zwei Male und den fehlenden Schuh immer noch nicht erklären."
  },
  AvgDialog_58327_Content_43 = {
    Text = "Das glaube ich nicht. Woher weißt du, dass das Seil nicht hastig ausgetauscht wurde, weil es mit dem Blut des Mörders befleckt war?"
  },
  AvgDialog_58327_Content_44 = {
    Text = "Was die fehlenden Schuhe angeht – es ist seltsam, aber spät nachts barfuß zu Hause zu sein, erscheint nicht ungewöhnlich."
  },
  AvgDialog_58327_Content_45 = {
    Text = "Außerdem, welche Kraft und Präzision braucht man, um jemanden aus einem Fenster im ersten Stock aufzuhängen? Denk daran, außer dem Opfer waren in jener Nacht alle anderen Frauen oder Kinder."
  },
  AvgDialog_58327_Content_46 = {
    Text = "Mm-hmm, diese Begründung kann ich akzeptieren."
  },
  AvgDialog_58327_Content_47 = {Text = "Also –"},
  AvgDialog_58327_Content_48 = {
    Text = "Ryker tätschelte deinen Kopf mit einem fröhlichen Lächeln."
  },
  AvgDialog_58327_Content_49 = {
    Text = "Die reale Welt ist kein Kriminalroman, Schutzherr. Niemand würde mit solch umständlichen Methoden töten."
  },
  AvgDialog_58327_Content_5 = {
    Text = "Erwürgt und dann wiederbelebt zu werden fühlt sich überhaupt nicht gut an. Ich habe ständig das Gefühl, als wäre mein Hals mit Steinen verstopft."
  },
  AvgDialog_58327_Content_50 = {
    Text = "Tch. Kein Kriminalroman, sondern dein Glück?"
  },
  AvgDialog_58327_Content_51 = {
    Text = "Vielleicht. Was für ein Zufall, dass ich über diese Hinweise gestolpert bin. Haben die sich etwa Beine wachsen lassen?"
  },
  AvgDialog_58327_Content_52 = {
    Text = "Die Leute bestaunen immer die Genialität eines Mathematikers, wenn er ein Problem löst. Doch Genialität bedeutet einfach, dem Durchschnittsmenschen einen Schritt voraus zu sein."
  },
  AvgDialog_58327_Content_53 = {
    Text = "Ryker lachte und machte eine Siegesgeste in die unsichtbare Ferne."
  },
  AvgDialog_58327_Content_54 = {
    Text = "Ich schätze, du bist genauso wie ich?"
  },
  AvgDialog_58327_Content_55 = {
    Text = "Niemand reagiert auf den naiven Vorstoß des Detektivs. Eine sanfte Brise weht, raschelt durch die Blätter, und die Dunkelheit senkt sich allmählich herab."
  },
  AvgDialog_58327_Content_56 = {
    Text = "Langweilig. Sieht aus, als würde es gleich regnen. Lass uns gehen."
  },
  AvgDialog_58327_Content_57 = {
    Text = "Du und Ryker gingt durch den Friedhof, das Knirschen von Herbstlaub unter euren Füßen. Niemand sprach."
  },
  AvgDialog_58327_Content_58 = {
    Text = "Wo wir gerade dabei sind... Wir haben so viel zusammen durchgemacht. Wäre es nicht langsam an der Zeit, mir etwas über deine Vergangenheit zu erzählen, so wie in den Romanen?"
  },
  AvgDialog_58327_Content_59 = {
    Text = "Zum Beispiel, woher du kommst und wie du dem Glücksspiel verfallen bist"
  },
  AvgDialog_58327_Content_6 = {
    Text = "Hust hust hust"
  },
  AvgDialog_58327_Content_60 = {Text = "Hey..."},
  AvgDialog_58327_Content_61 = {
    Text = "Leider ist meine Vergangenheit, genau wie dieser Fall, ziemlich unspektakulär. Sie zu erzählen könnte das Mysterium zerstören, das ich in deinen Augen darstelle."
  },
  AvgDialog_58327_Content_62 = {
    Text = "Heh, deine Selbstwahrnehmung ist immer noch so ein Durcheinander. Genau deshalb war ich schon immer neugierig."
  },
  AvgDialog_58327_Content_63 = {
    Text = "Na gut, wenn du darauf bestehst, lass uns ein Café finden und in Ruhe reden..."
  },
  AvgDialog_58327_Content_64 = {
    Text = "Das Lachen verklingt allmählich, und der Friedhof kehrt zur Stille zurück."
  },
  AvgDialog_58327_Content_65 = {
    Text = "Ein schwacher schwarzer Nebel treibt durch die Luft, gleich uralten, unsichtbaren Partikeln, die seit Jahrtausenden verborgen waren."
  },
  AvgDialog_58327_Content_66 = {
    Text = "Der Nebel beobachtete, wie der Detektiv und der Hüter gingen, dehnte sich dann einen Moment freudig aus, bevor er sich widerwillig auflöste."
  },
  AvgDialog_58327_Content_67 = {
    Text = "Als ob er nie erschienen wäre."
  },
  AvgDialog_58327_Content_7 = {
    Text = "Dexter hustet nach dem Sprechen übertrieben."
  },
  AvgDialog_58327_Content_8 = {
    Text = "Scheint, als wäre alles in Ordnung. Also, reden wir über das Hauptthema: Was hat es mit dem Sarg bei dir zu Hause auf sich?"
  },
  AvgDialog_58327_Content_9 = {
    Text = "Wenn ich richtig liege, gehört er dem letzten Pharao von Lemvah — Kanak."
  },
  AvgDialog_58328_Content_1 = {
    Text = "Nächsten Montag, Sir"
  },
  AvgDialog_58328_Content_10 = {
    Text = "Weil er der berühmte „Glücksdetektiv“ von der East Side ist."
  },
  AvgDialog_58328_Content_11 = {
    Text = "Solange er an einem Fall arbeitet, scheinen Hinweise aus dem Nichts aufzutauchen, und der Täter kann nicht länger als drei Tage unentdeckt bleiben!"
  },
  AvgDialog_58328_Content_12 = {
    Text = "Manche sagen, dass man nur einen Tag lang Herrn Ryker folgen muss, um zehn Leofangs zu finden. Jedenfalls ist er für alle ein Glücksbringer."
  },
  AvgDialog_58328_Content_13 = {
    Text = "Aber sein Glück hält hier nicht stand..."
  },
  AvgDialog_58328_Content_14 = {
    Text = "Ich habe gehört, dieser Fall ähnelt sehr einem, den Herr Ryker bearbeitet hat?"
  },
  AvgDialog_58328_Content_15 = {
    Text = "Ja. Obwohl Herr Ryker es nicht sagt, liegt ihm dieser Fall tatsächlich sehr am Herzen."
  },
  AvgDialog_58328_Content_16 = {
    Text = "Ihr solltet wissen, er hatte noch einen anderen Spitznamen: <Blue:Herr Nächsten Montag>."
  },
  AvgDialog_58328_Content_17 = {
    Text = "Nächsten Montag, mein Herr...?"
  },
  AvgDialog_58328_Content_18 = {
    Text = "Hanna räuspert sich und beginnt in einem übertriebenen Tonfall zu sprechen."
  },
  AvgDialog_58328_Content_19 = {
    Text = "„Ryker, wann zahlst du deine Spielschulden zurück?“ „Nächsten Montag!“"
  },
  AvgDialog_58328_Content_2 = {
    Text = "Ferland-Anwesen Außenbereich\n60 Minuten verbleiben bis zum Abschluss des Falls <Red:60>"
  },
  AvgDialog_58328_Content_20 = {
    Text = "„Ryker, wann hast du vor, dir eine Arbeit zu suchen?“ „Nächsten Montag!“"
  },
  AvgDialog_58328_Content_21 = {
    Text = "„Ryker, wann wirst du sterben?“ „Nächsten Montag!“"
  },
  AvgDialog_58328_Content_22 = {
    Text = "Hier, so in etwa. Damals lachten ihn alle aus; die Kinder schnitten hinter seinem Rücken Grimassen, und der Barbesitzer griff zum Stuhl, wenn er ihn sah..."
  },
  AvgDialog_58328_Content_23 = {
    Text = "Kurz gesagt, niemand respektierte ihn."
  },
  AvgDialog_58328_Content_24 = {
    Text = "...Bis er diesen Fall gelöst hat."
  },
  AvgDialog_58328_Content_25 = {
    Text = "Ganz genau! Seitdem schien sein Leben wie verzaubert zu sein. Das Glück kam ihm immer entgegen, und alle mochten ihn mehr und mehr."
  },
  AvgDialog_58328_Content_26 = {
    Text = "Wie seltsam. Gibt es solche Magie wirklich auf der Welt?"
  },
  AvgDialog_58328_Content_27 = {
    Text = "Wer weiß, in diesen Zeiten ist nichts mehr überraschend — Moment, was ist das?"
  },
  AvgDialog_58328_Content_28 = {
    Text = "In der Ecke nahe der Wand war ein schwarzer Herrenlederschuh halb im weichen, weißen Schnee vergraben."
  },
  AvgDialog_58328_Content_29 = {
    Text = "Wow, solch exquisite Schnitzereien. Sieht nach etwas aus, das ich mir nie leisten könnte..."
  },
  AvgDialog_58328_Content_3 = {
    Text = "Hatschi... Hatschi!"
  },
  AvgDialog_58328_Content_30 = {Text = "!!!"},
  AvgDialog_58328_Content_31 = {
    Text = "Das ist Herrn Dexters Lederschuh."
  },
  AvgDialog_58328_Content_32 = {
    Text = "Du blickst nach oben. Die kalten, grauen Wände ragen in die Höhe, und die schwachen Lichter schweben wie Leuchttürme."
  },
  AvgDialog_58328_Content_33 = {
    Text = "Dort oben ist Dexters Schlafzimmer."
  },
  AvgDialog_58328_Content_34 = {
    Text = "Du blickst nach unten; das Arbeitszimmer liegt direkt vor dir. Durch das geschnitzte Fenster starrt Dexters hängender Schatten schweigend zu dir zurück."
  },
  AvgDialog_58328_Content_35 = {
    Text = "Die beiden Räume liegen vertikal übereinander."
  },
  AvgDialog_58328_Content_36 = {
    Text = "Hanna... Ich habe plötzlich eine Vermutung."
  },
  AvgDialog_58328_Content_37 = {
    Text = "Du drückst Hanna die Schuhe in die Hände."
  },
  AvgDialog_58328_Content_38 = {
    Text = "Lass uns das Arbeitszimmer überprüfen."
  },
  AvgDialog_58328_Content_39 = {
    Text = [[
Ferland-Herrenhaus Arbeitszimmer
30 Minuten verbleiben bis zum Fallabschluss <Red:30>]]
  },
  AvgDialog_58328_Content_4 = {
    Text = "Hanna hält eine Petroleumlampe und kauert sich neben dir zu einem kleinen Knäuel zusammen."
  },
  AvgDialog_58328_Content_40 = {
    Text = "Du griffst nach dem Türknauf und zogst die Tür auf."
  },
  AvgDialog_58328_Content_41 = {
    Text = "Was ist los? Wart ihr beiden draußen einkaufen?"
  },
  AvgDialog_58328_Content_42 = {
    Text = "Herr Ryker?! Sind Sie nicht..."
  },
  AvgDialog_58328_Content_43 = {
    Text = "Ja, ich war gerade eben tief bewegt und habe mich in der Ecke ordentlich ausgeweint."
  },
  AvgDialog_58328_Content_44 = {
    Text = "Du wirfst einen Blick auf seine unbekümmerte Haltung und klopfst ihm plötzlich auf die Schulter."
  },
  AvgDialog_58328_Content_45 = {
    Text = "Es freut mich zu hören, dass es dir gut geht."
  },
  AvgDialog_58328_Content_46 = {
    Text = "Tss. Was soll dieser widerliche Gesichtsausdruck..."
  },
  AvgDialog_58328_Content_47 = {
    Text = "Also gut, keine Zeit zum Murmeln! Herr Ryker, wir haben gerade unten eine wichtige Entdeckung gemacht!"
  },
  AvgDialog_58328_Content_48 = {
    Text = "Du schildertest Ryker deine Beobachtungen von unten."
  },
  AvgDialog_58328_Content_49 = {
    Text = "...Ich sehe."
  },
  AvgDialog_58328_Content_5 = {
    Text = "Verdammt, nicht eine einzige Fußspur übrig! Wir sind zu spät rausgekommen."
  },
  AvgDialog_58328_Content_50 = {
    Text = "Ryker trat ans Fenster des Arbeitszimmers, wo ein schwacher Schuhabdruck auf dem weißen Rahmen zu erkennen war."
  },
  AvgDialog_58328_Content_51 = {
    Text = "Er lehnte sich hinaus und schaute nach oben."
  },
  AvgDialog_58328_Content_52 = {Text = "Ugh..."},
  AvgDialog_58328_Content_53 = {
    Text = "Wenn ich mich nicht irre, befindet sich der andere Schuh höchstwahrscheinlich in diesem Zimmer."
  },
  AvgDialog_58328_Content_54 = {Text = "?!"},
  AvgDialog_58328_Content_55 = {
    Text = "Aber davor gibt es eine Sache, die ich bestätigen möchte..."
  },
  AvgDialog_58328_Content_56 = {
    Text = "Der Detektiv nähert sich Sorels Leichnam und untersucht sorgfältig die Schusswunde an ihrer Stirn."
  },
  AvgDialog_58328_Content_57 = {
    Text = "Die Ränder weisen dicken Rauchruß und Brandspuren auf — der Mörder hat ihr aus nächster Nähe direkt ins Gesicht geschossen."
  },
  AvgDialog_58328_Content_58 = {
    Text = "Hmm... Was könnte das bedeuten?"
  },
  AvgDialog_58328_Content_59 = {
    Text = "Der Detektiv bricht plötzlich in Gelächter aus. Es ist das erste Mal seit dem Betreten des Herrenhauses, dass er so herzhaft gelacht hat."
  },
  AvgDialog_58328_Content_6 = {
    Text = "Der Raum wurde gründlich durchsucht. Wir können jetzt nur noch draußen unser Glück versuchen."
  },
  AvgDialog_58328_Content_60 = {
    Text = "Zack, alle Erklärungen sind abgeschlossen. Fahren wir fort. Es ist Zeit für eine Deduktionsshow."
  },
  AvgDialog_58328_Content_7 = {
    Text = "Seufz... Wenn nur Herr Ryker hier wäre, er wüsste, was zu tun ist."
  },
  AvgDialog_58328_Content_8 = {
    Text = "„Er sagte, er wolle eine Weile allein sein, und verschwand dann.\""
  },
  AvgDialog_58328_Content_9 = {
    Text = "Wo wir gerade davon sprechen, ich kannte Herrn Ryker nur als Spieler. Ich hätte nicht erwartet, dass er sich auch als Detektiv gut schlagen würde..."
  },
  AvgDialog_58329_Content_1 = {
    Text = "Eine Wahrheit"
  },
  AvgDialog_58329_Content_10 = {Text = "!!"},
  AvgDialog_58329_Content_11 = {
    Text = "„Du warst so erpicht darauf, mich zu unterbrechen, bevor ich die Wahrheit über Sorels Tod enthüllen konnte. Glaub nicht, dass dein Auftritt mich dazu bringt, dir gegenüber unvorsichtig zu werden.\""
  },
  AvgDialog_58329_Content_12 = {
    Text = "<Red:Lieber Mr. N?>"
  },
  AvgDialog_58329_Content_13 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58329_Content_14 = {
    Text = "Das Blut hörte auf zu fließen. Es verwandelte sich in einen pechschwarzen Nebel, der „dich“ einhüllte."
  },
  AvgDialog_58329_Content_15 = {
    Text = "Schließlich verschwindet der lockenhaarige Student, und der dunkle Nebel strömt in Ns Körper."
  },
  AvgDialog_58329_Content_16 = {
    Text = "Du scheinst die Vorstellung zu genießen, alter Freund."
  },
  AvgDialog_58329_Content_17 = {
    Text = "Einfach ein bisschen Inspiration, die ich von dir bekommen habe. Wir sind vom gleichen Schlag."
  },
  AvgDialog_58329_Content_18 = {
    Text = "Interessant... sehr interessant. Wie hast du es geschafft, das herauszufinden?"
  },
  AvgDialog_58329_Content_19 = {
    Text = "Hast du nicht von Anfang an gesagt: „Vertraue niemandem.\" Ich habe viele Schwächen, aber mein natürliches Misstrauen ist etwas, das ich in meinem ganzen Leben nicht ablegen werde."
  },
  AvgDialog_58329_Content_2 = {
    Text = "Nein... Warum..."
  },
  AvgDialog_58329_Content_20 = {
    Text = "Der erste Verdacht kam auf, als ich Sorels Leiche sah. Sie wurde von vorne erschossen und hatte keine anderen Wunden."
  },
  AvgDialog_58329_Content_21 = {
    Text = "Die Einschusswunde an der Stirn wies starke Ruß- und Schmauchspuren auf, was auf zwei Dinge hindeutet."
  },
  AvgDialog_58329_Content_22 = {
    Text = "Erstens: Der Mörder hat sie aus sehr kurzer Entfernung erschossen."
  },
  AvgDialog_58329_Content_23 = {
    Text = "Und der zweite Punkt?"
  },
  AvgDialog_58329_Content_24 = {
    Text = "Es deutet darauf hin, dass der Täter jemand ist, dem das Opfer vertraute und in dessen Nähe es die Wachsamkeit fallen ließ. Die einzige Person hier, auf die diese Beschreibung zutrifft, ist %player%."
  },
  AvgDialog_58329_Content_25 = {
    Text = "Du hattest es eilig, sie zu töten, weil ich das Geheimnis der Schallplatte aufgedeckt habe."
  },
  AvgDialog_58329_Content_26 = {
    Text = "Und du willst nicht, dass das Spiel vorzeitig endet, richtig?"
  },
  AvgDialog_58329_Content_27 = {
    Text = "N zuckte gleichgültig mit den Schultern."
  },
  AvgDialog_58329_Content_28 = {
    Text = "Es ist nur ein unbegründeter Verdacht, und trotzdem hattest du das Herz, den Schutzherrn zu erschießen? Du bist wahrlich der Spieler, den ich ausgewählt habe."
  },
  AvgDialog_58329_Content_29 = {
    Text = "Wenn ich dieser {Male=Mr.,Female=Miss} %player% wäre, würde ich in diesem Moment Tränen über deine Skrupellosigkeit vergießen."
  },
  AvgDialog_58329_Content_3 = {
    Text = "Du brichst auf die Knie zusammen. Ein schwacher Schmerz strahlt von deiner Brust aus, dunkelrotes Blut durchdringt deine Uniformjacke."
  },
  AvgDialog_58329_Content_30 = {
    Text = "Hehe, ich würde niemals mit %hisorher% Leben scherzen. Es gibt nur einen Grund, warum ich es gewagt habe, auf dich zu schießen..."
  },
  AvgDialog_58329_Content_31 = {
    Text = "<Yellow:Ich weiß schon lange, wo {Male=he,Female=she} ist.>"
  },
  AvgDialog_58329_Content_32 = {Text = "?!"},
  AvgDialog_58329_Content_33 = {
    Text = "Gerade eine Stunde zuvor."
  },
  AvgDialog_58329_Content_34 = {
    Text = [[
Farlander-Anwesen, Sarg
Eine Stunde zuvor]]
  },
  AvgDialog_58329_Content_35 = {
    Text = "Ein ursprüngliches und warmes Chaos."
  },
  AvgDialog_58329_Content_36 = {
    Text = "Du schließt die Augen und lässt dein Bewusstsein auf die tiefste Ebene sinken."
  },
  AvgDialog_58329_Content_37 = {
    Text = "Endlich kommst „du“ am Fuße der hohen Mauer an."
  },
  AvgDialog_58329_Content_38 = {
    Text = "Dies ist die <Yellow:Wand der Wahrheit>. Verborgen hinter dem Vorhang vor deinen Augen, wird nur eine Ecke während einer Zeremonie enthüllt, die alle paar Jahre stattfindet."
  },
  AvgDialog_58329_Content_39 = {
    Text = "Sie versiegelt die Vergangenheit, verzeichnet die Gegenwart und sagt die Zukunft voraus."
  },
  AvgDialog_58329_Content_4 = {
    Text = "Du Narr... Was redest du da..."
  },
  AvgDialog_58329_Content_40 = {
    Text = "Der Priester spricht und kniet ehrfürchtig vor dir nieder."
  },
  AvgDialog_58329_Content_41 = {
    Text = "Inklusive deiner Ankunft, Karnak."
  },
  AvgDialog_58329_Content_42 = {
    Text = "Es begann zu regnen"
  },
  AvgDialog_58329_Content_43 = {
    Text = "Du kniest vor dem gewaltigen Gemälde, stöhnend wie ein gefangenes Tier, das endlich Erlösung findet. Regenwasser vermischt sich mit deinen Tränen und fließt von deinen Brauen und Augen herab."
  },
  AvgDialog_58329_Content_44 = {
    Text = "Nach Tausenden von Jahren bist du endlich der Pharao von Lemvah geworden."
  },
  AvgDialog_58329_Content_45 = {
    Text = "Du hast dein Schicksal erfüllt."
  },
  AvgDialog_58329_Content_46 = {Text = "Später..."},
  AvgDialog_58329_Content_47 = {
    Text = "Zur Seite. Ich werde diese verdammten Vorhänge in Fetzen reißen!"
  },
  AvgDialog_58329_Content_48 = {
    Text = "Edles Kind des Amun, du solltest nicht hier sein. Jeder, der sich der Wand der Wahrheit widersetzt, wird den Tod über sein Haupt bringen."
  },
  AvgDialog_58329_Content_49 = {
    Text = "Heh. Pest, Hungersnot, und jetzt steht Apophis' Armee vor den Stadtmauern. Öffne deine Augen und sieh die Welt, blinder Priester — der Tod ist bereits eingetroffen."
  },
  AvgDialog_58329_Content_5 = {
    Text = "Ryker betrachtete die fein gearbeitete Handfeuerwaffe in seiner Hand und blies dann gemächlich über den Lauf."
  },
  AvgDialog_58329_Content_50 = {
    Text = "Ich folgte andächtig den Anweisungen der Wand, brachte aber Unheil über die Menschen, die seit Generationen am Flussufer gelebt hatten. Das ist die Folge blinden Gehorsams."
  },
  AvgDialog_58329_Content_51 = {
    Text = "Gedulde dich, junger Herrscher von Lemvah. Was getan wurde, betrifft das Jenseits; was noch getan wird, betrifft die Ewigkeit. Das Jenseits ist nur Tageslicht, doch die Ewigkeit ist die Nacht."
  },
  AvgDialog_58329_Content_52 = {
    Text = "Die Wand der Wahrheit bringt sowohl Honig und Papyrus als auch Gift und Pest."
  },
  AvgDialog_58329_Content_53 = {
    Text = "Nur indem wir ihrem Willen folgen, können unsere Seelen nach dem Tod sicher den Fluss der Nacht überqueren und am fernen Ufer ewig werden—"
  },
  AvgDialog_58329_Content_54 = {
    Text = "Mich kümmert die „Ewigkeit“ nicht, die ihr lügenden Blutsauger von euch gebt. Ich sehe nur, wie meine hart erkämpften Ländereien über Nacht verschwinden, wie mein Volk einer nach dem anderen stirbt."
  },
  AvgDialog_58329_Content_55 = {
    Text = "Selbst mein treuester Untergebener, <Blue:Apophis>, wandte seine Klinge gegen mich. Er ist jetzt draußen und wartet darauf, meinen Kopf zu nehmen und ihn hoch an die Mauer zu hängen."
  },
  AvgDialog_58329_Content_56 = {
    Text = "Ich habe alles verloren, Priester. Wenn dies die Bestimmung meines erbärmlichen Schicksals durch die Wand der Wahrheit ist, werde ich meine Augen weit offen halten und zusehen, wie sie stirbt."
  },
  AvgDialog_58329_Content_57 = {
    Text = "„Du“ schobst den alten Priester beiseite und rissest den Schleier herunter."
  },
  AvgDialog_58329_Content_58 = {
    Text = "Von diesem Punkt an entfalten sich die Wahrheiten der Welt vor „Dir“."
  },
  AvgDialog_58329_Content_59 = {
    Text = "Eins, zwei..."
  },
  AvgDialog_58329_Content_6 = {
    Text = "Als er deinen zerzausten Zustand sah, zeigte er ein finsteres Lächeln."
  },
  AvgDialog_58329_Content_60 = {
    Text = "Unzählige grobe Smiley-Graffiti, in ziegelrot gemalt, mit weit aufgerissenen Mündern, lachen höhnisch über „deine“ Verzweiflung."
  },
  AvgDialog_58329_Content_61 = {
    Text = "Ich verstehe, das ist also die sogenannte Wahrheit. Hehe...hahahaha..."
  },
  AvgDialog_58329_Content_62 = {
    Text = "Absurdität. Verachtung. Das ist die Wahrheit der Welt."
  },
  AvgDialog_58329_Content_63 = {Text = "!!!"},
  AvgDialog_58329_Content_64 = {
    Text = "Im nächsten Moment verschwand das Rollbild, und die Dunkelheit kehrte erneut zurück."
  },
  AvgDialog_58329_Content_65 = {
    Text = "Keine Wüste, keine Priester und keine Schriftrollen; du bist allein in einem dunklen Sarg."
  },
  AvgDialog_58329_Content_66 = {
    Text = "Deine Gedanken sind noch immer in den Erinnerungen an Karnak gefangen; eine endlose Welle der Trauer umhüllt dich."
  },
  AvgDialog_58329_Content_67 = {
    Text = "Tränen ließen sich nicht mehr zurückhalten, wie ein endloser Regenvorhang."
  },
  AvgDialog_58329_Content_68 = {
    Text = "<Change>Nein... Ich..."
  },
  AvgDialog_58329_Content_69 = {
    Text = "<Change>Ich will doch nur am Leben bleiben..."
  },
  AvgDialog_58329_Content_7 = {
    Text = "Der Grund, warum ich dich nicht davon abgehalten habe, Hanna wegzuschicken, war die Angst, dass sie die Wahrheit nicht verkraften könnte. Schließlich ist sie nur eine gewöhnliche Studentin."
  },
  AvgDialog_58329_Content_70 = {
    Text = "Bumm. Bumm bumm."
  },
  AvgDialog_58329_Content_71 = {
    Text = "Ein fernes Klopfen durchbricht den ewigen Rhythmus dieses Ozeans der Trauer. Dann hörst du eine vertraute Stimme —"
  },
  AvgDialog_58329_Content_72 = {
    Text = "Hey, Freund im Sarg, alles in Ordnung bei dir?"
  },
  AvgDialog_58329_Content_8 = {
    Text = "Und du, mein Freund—"
  },
  AvgDialog_58329_Content_9 = {
    Text = "Ich wusste, dass du dem Drang nicht widerstehen könntest, dich in Szene zu setzen. Hey, macht Schauspielern Spaß?"
  },
  AvgDialog_58330_Content_1 = {
    Text = "Tragödienaufführung"
  },
  AvgDialog_58330_Content_10 = {
    Text = "Es gibt noch eine andere Meinung meinerseits zu diesem Punkt, aber lassen wir das vorerst beiseite. Was geschah, nachdem Herr Dexter das Haus verlassen hatte?"
  },
  AvgDialog_58330_Content_100 = {
    Text = "Weil du den wahren Mörder von Mrs. Sorel nicht identifiziert hast. Deine Deduktionen meiden absichtlich ihren Tod, nicht wahr?"
  },
  AvgDialog_58330_Content_101 = {
    Text = "Wovor hast du Angst?"
  },
  AvgDialog_58330_Content_102 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58330_Content_103 = {
    Text = "Es ist bedauerlich, dass ihr einen weiteren Freund verloren habt. Vielleicht ist das Glück in dieser Welt endlich."
  },
  AvgDialog_58330_Content_104 = {
    Text = "Ihr habt Glück erlangt, euer Leben hat sich erheblich verbessert, doch andere erlitten deswegen großes Unglück."
  },
  AvgDialog_58330_Content_105 = {
    Text = "Könnt ihr die unsichtbaren Gesetze, die über den Köpfen der Menschen schweben, wirklich akzeptieren?"
  },
  AvgDialog_58330_Content_106 = {
    Text = "Heh... Was für ein Haufen Unsinn, das ist nur dein persönliches kleines Spiel."
  },
  AvgDialog_58330_Content_107 = {
    Text = "Eure Feindseligkeit mir gegenüber bleibt so aufrichtig, bezaubernd und doch bedauerlich."
  },
  AvgDialog_58330_Content_108 = {
    Text = "Obwohl es euch nicht gelungen ist, alle Rätsel zu lösen, war ich stets sehr nachsichtig..."
  },
  AvgDialog_58330_Content_109 = {
    Text = "N hob einen Finger und sandte dichten schwarzen Nebel auf euch zu, der euch fest umschlang."
  },
  AvgDialog_58330_Content_11 = {Text = "...!!"},
  AvgDialog_58330_Content_110 = {
    Text = "Nein... Ugh!"
  },
  AvgDialog_58330_Content_111 = {Text = "!!"},
  AvgDialog_58330_Content_112 = {
    Text = "Mr. N, ich weiß, dass mein Handeln in Aram Sie verärgert hat, und ich entschuldige mich aufrichtig."
  },
  AvgDialog_58330_Content_113 = {
    Text = "Sie können mich bestrafen, wie Sie wollen, aber es gibt keinen Grund, hinter {Male=him,Female=her} her zu sein."
  },
  AvgDialog_58330_Content_114 = {
    Text = "Ungeduldiger Detektiv, hören Sie mich an. Ich habe eine letzte Frage für Sie vorbereitet."
  },
  AvgDialog_58330_Content_115 = {
    Text = "...In Ordnung, ich höre."
  },
  AvgDialog_58330_Content_116 = {
    Text = "Eine einfache Wahl: <Red:Töten Sie %player%, und ich werde alle, die zuvor gestorben sind, wiederbeleben.>"
  },
  AvgDialog_58330_Content_117 = {
    Text = "Alles wird wieder normal, außer für diesen Pechvogel neben Ihnen. Niemand sonst wird verletzt."
  },
  AvgDialog_58330_Content_118 = {
    Text = "Oder Sie könnten sich entscheiden, %player% nicht zu töten, und Sie beide können den Geheimgang sicher verlassen."
  },
  AvgDialog_58330_Content_119 = {
    Text = "War es wirklich so einfach?"
  },
  AvgDialog_58330_Content_12 = {
    Text = "Erinnert ihr euch an den Geist, den ich vorhin am Treppenaufgang gesehen habe? In der Luft schwebend, der Geist, das Erhängen... Könnte es sein..."
  },
  AvgDialog_58330_Content_120 = {Text = "?!"},
  AvgDialog_58330_Content_121 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58330_Content_122 = {
    Text = "Haben Sie noch Ihre Handfeuerwaffe dabei? Der Countdown beginnt jetzt. 10."
  },
  AvgDialog_58330_Content_123 = {
    Text = "Nein, du kannst nicht..."
  },
  AvgDialog_58330_Content_124 = {Text = "9"},
  AvgDialog_58330_Content_125 = {
    Text = "Ryker sah dich benommen an, wie ein Kind, das etwas falsch gemacht hatte."
  },
  AvgDialog_58330_Content_126 = {
    Text = "Mach dir keine Sorgen um mich, hust... Vielleicht machen sie mich zu einem Erweckten Körper, wenn ich sterbe."
  },
  AvgDialog_58330_Content_127 = {
    Text = "Du spannst alle Gesichtsmuskeln an, um Ryker ein gequältes Lächeln zu schenken."
  },
  AvgDialog_58330_Content_128 = {
    Text = "... Nur zu."
  },
  AvgDialog_58330_Content_129 = {Text = "6"},
  AvgDialog_58330_Content_13 = {
    Text = "Richtig. Die Wahrheit ist: Jemand hat Herrn Dexter abgelenkt, ihm dann in dem Moment, als er sich hinauslehnte, eine Schlinge um den Hals gelegt und sie straff zugezogen —"
  },
  AvgDialog_58330_Content_130 = {
    Text = "Ryker ging langsam auf dich zu, seine Augen ruhig und gelassen."
  },
  AvgDialog_58330_Content_131 = {
    Text = "Als deine Sicht allmählich verschwamm, blicktest du in seine Augen, und Erinnerungen an gemeinsam verbrachte Momente zogen vor deinem inneren Auge vorbei."
  },
  AvgDialog_58330_Content_132 = {
    Text = "Es gibt Zeiten, in denen sie sich spielerisch durch die Wüste jagen, gemeinsam aus der ■■-Versammlung der Alanen fliehen und er sein Leben als Köder einsetzt, um Casiah zu verderben..."
  },
  AvgDialog_58330_Content_133 = {
    Text = "Es gibt zu viele Erinnerungen zwischen euch beiden."
  },
  AvgDialog_58330_Content_134 = {
    Text = "Ohne dass du es bemerkt hast, stand Ryker bereits vor dir. Du konntest sein Gesicht nicht sehen, aber du wusstest, dass sein Schmerz nicht geringer war als deiner."
  },
  AvgDialog_58330_Content_135 = {
    Text = "Im nächsten Moment hob er die Pistole."
  },
  AvgDialog_58330_Content_136 = {
    Text = "Weißt du was... Ich habe nie an dir gezweifelt. Also—"
  },
  AvgDialog_58330_Content_137 = {
    Text = "Der Schuss ertönt und trifft genau dort, wo dein Herz ist, mitten ins Zentrum."
  },
  AvgDialog_58330_Content_138 = {Text = "Was...?"},
  AvgDialog_58330_Content_139 = {
    Text = "Ryker stand über dir, ein spöttisches Lächeln auf den Lippen."
  },
  AvgDialog_58330_Content_14 = {
    Text = "Ryker hob sein Gesicht und deutete auf das Schlafzimmer im zweiten Stock."
  },
  AvgDialog_58330_Content_140 = {
    Text = "Ich habe lange auf diesen Moment gewartet, Hüter."
  },
  AvgDialog_58330_Content_15 = {
    Text = "<Yellow:Der Mörder war in Herrn Dexters Schlafzimmer.> Diese beiden Räume liegen in einer geraden Linie."
  },
  AvgDialog_58330_Content_16 = {
    Text = "Brillant! Das erklärt das Geisterereignis und die Fußabdrücke auf dem Fensterrahmen — es lag an Herrn Dexters Kampf, nachdem er gefesselt wurde."
  },
  AvgDialog_58330_Content_17 = {
    Text = "Aber dafür braucht man große Armkraft und Winkelpräzision, und alle hier hatten ihre Fähigkeiten versiegelt, wie"
  },
  AvgDialog_58330_Content_18 = {
    Text = "Hanna hält mitten im Satz inne, eine Vermutung formt sich in ihrem Kopf."
  },
  AvgDialog_58330_Content_19 = {
    Text = "Aber... nach dem Geisterereignis sind wir schnell nach oben ins Schlafzimmer gegangen. Wir haben in dieser Zeit keine anderen Geräusche gehört. Der Mörder muss noch im Schlafzimmer gewesen sein"
  },
  AvgDialog_58330_Content_2 = {
    Text = "Hatschi... Hatschi!"
  },
  AvgDialog_58330_Content_20 = {
    Text = "Abgesehen von diesem Grammophon schien nichts anderes ungewöhnlich... HATSCHI! HATSCHI!"
  },
  AvgDialog_58330_Content_21 = {
    Text = "Hanna wischt sich zwei glänzende Rotzfäden weg."
  },
  AvgDialog_58330_Content_22 = {
    Text = "Vater im Himmel, wie kann man sich selbst in einem Geheimgang erkälten!"
  },
  AvgDialog_58330_Content_23 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58330_Content_24 = {
    Text = "Wir haben das Äußere bereits besprochen. Lasst uns schnell nach drinnen gehen..."
  },
  AvgDialog_58330_Content_25 = {
    Text = "Denkt genau nach. Was geschah, nachdem wir die Tür eingetreten haben?"
  },
  AvgDialog_58330_Content_26 = {
    Text = "Was ist passiert..."
  },
  AvgDialog_58330_Content_27 = {
    Text = "Entschuldigung, mir geht es nicht gut. Kann ich eine kurze Pause machen?"
  },
  AvgDialog_58330_Content_28 = {
    Text = "Entschuldigung @2... Fühle mich nicht gut... Ruhe..."
  },
  AvgDialog_58330_Content_29 = {
    Text = "Ruhe, Ruhe@2 Ruhe..."
  },
  AvgDialog_58330_Content_3 = {
    Text = "Der Kühleffekt dieses Geheimgangs ist wirklich beeindruckend. Anführer, können wir nicht drinnen am Kamin schlussfolgern?"
  },
  AvgDialog_58330_Content_30 = {
    Text = "Alle, bitte verlassen Sie so schnell wie möglich den Raum und stören Sie Herrn Dexters Ruhe nicht."
  },
  AvgDialog_58330_Content_31 = {
    Text = "<Shake:Whoa!! Wann hast du...>"
  },
  AvgDialog_58330_Content_32 = {
    Text = "Also ist es so..."
  },
  AvgDialog_58330_Content_33 = {
    Text = "Hanna hebt plötzlich den Kopf und starrt direkt auf Erica hinter der Menge."
  },
  AvgDialog_58330_Content_34 = {
    Text = "Du warst kein Nachzügler. Du warst die ganze Zeit im Raum... Vielleicht hinter der Tür versteckt, hast unsere Aufmerksamkeit abgelenkt, während wir alle auf den Plattenspieler fokussiert waren."
  },
  AvgDialog_58330_Content_35 = {
    Text = "Abgelehnt. Erica hat nicht die Fähigkeit, an zwei Orten gleichzeitig zu sein, was es unmöglich macht zu erklären, warum der Verstorbene im Arbeitszimmer auftauchte."
  },
  AvgDialog_58330_Content_36 = {
    Text = "Ja, dir fehlt die Fähigkeit, an zwei Orten gleichzeitig zu sein. Deshalb hast du einen Helfer."
  },
  AvgDialog_58330_Content_37 = {Text = "!!"},
  AvgDialog_58330_Content_38 = {
    Text = "Einen erwachsenen Mann mit einem ausfahrbaren mechanischen Arm in der Luft zu erwürgen, ist ein Kinderspiel für Fräulein Erica."
  },
  AvgDialog_58330_Content_39 = {
    Text = "Einfach so, wie du zuvor deinen Arm ausgestreckt hast, um die Holzbrücke durchzusägen."
  },
  AvgDialog_58330_Content_4 = {
    Text = "Keine Sorge, es wird nicht allzu viel von jedermanns Zeit in Anspruch nehmen."
  },
  AvgDialog_58330_Content_40 = {
    Text = "Nachdem Herr Dexter aufhört zu atmen, wirfst du ihn beiseite, und der Helfer, der die ganze Zeit gewartet hat, schleift die Leiche ins Arbeitszimmer."
  },
  AvgDialog_58330_Content_41 = {
    Text = "Das erklärt auch, warum es zwei Strangulationsmarken an der Leiche gab, sowie die Feuchtigkeit der Kleidung — weil die Leiche durch den Schnee geschleift wurde."
  },
  AvgDialog_58330_Content_42 = {
    Text = "Der Komplize muss die einzige Person ohne Alibi vom Schuss bis zum Verbrechen sein..."
  },
  AvgDialog_58330_Content_43 = {
    Text = "Ryker blickt zum Kleiderschrank in der Ecke des Arbeitszimmers, während er spricht."
  },
  AvgDialog_58330_Content_44 = {
    Text = "Frau Sorel."
  },
  AvgDialog_58330_Content_45 = {
    Text = "Verstehe. Ich dachte, Herr Dexter wurde in der Luft erwürgt, aber ich hätte nie erwartet, dass es einen Komplizen gibt."
  },
  AvgDialog_58330_Content_46 = {
    Text = "Abgelehnt. Alle obigen Schlussfolgerungen sind spekulativ und es fehlen konkrete Beweise."
  },
  AvgDialog_58330_Content_47 = {
    Text = "Beweise? Einfach genug."
  },
  AvgDialog_58330_Content_48 = {
    Text = "Erinnert ihr euch an die Muster der beiden Würgemale am Hals?"
  },
  AvgDialog_58330_Content_49 = {
    Text = "Die Muster der beiden Eindrücke sind ebenfalls uneinheitlich. Innen zeigt sich eine ordentliche Rautenstruktur, während die äußere rauer ist..."
  },
  AvgDialog_58330_Content_5 = {
    Text = "Zunächst die Schuhe draußen. Frage: Unter welchen Umständen würden Schuhe draußen landen?"
  },
  AvgDialog_58330_Content_50 = {
    Text = "Vielleicht ist das Seil mittendrin gerissen, oder es wurde blutig, also hat der Mörder es ausgetauscht."
  },
  AvgDialog_58330_Content_51 = {Text = "!!"},
  AvgDialog_58330_Content_52 = {
    Text = "Saubere Rautenformen. Fräulein Erica, könnten Sie Ihren mechanischen Arm ausstrecken und uns das einziehbare Verbindungsseil darin zeigen?"
  },
  AvgDialog_58330_Content_53 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58330_Content_54 = {
    Text = "Einen wachsamen erwachsenen Mann im zweiten Stock mit einem Seil am Hals zu fangen, ist nahezu unmöglich."
  },
  AvgDialog_58330_Content_55 = {
    Text = "Aber wenn das Seil Teil Ihres Körpers ist, dann ergibt alles einen Sinn."
  },
  AvgDialog_58330_Content_56 = {
    Text = "Also sind Sie es, Fräulein Erica..."
  },
  AvgDialog_58330_Content_57 = {
    Text = "Erica streckt langsam ihren rechten Arm aus. Im Licht schimmert die Verbindungsschnur zwischen ihrem Unterarm und ihrer Hand auf schaurige Weise"
  },
  AvgDialog_58330_Content_58 = {
    Text = "Diese rautenförmigen Muster sind in ordentlichen Reihen angeordnet, wie die Schuppen eines Fisches aus der Tiefsee."
  },
  AvgDialog_58330_Content_59 = {
    Text = "Einfach wie erwartet... genau gleich..."
  },
  AvgDialog_58330_Content_6 = {
    Text = "Mm... ist der Verstorbene hinausgegangen und dann verunglückt?"
  },
  AvgDialog_58330_Content_60 = {
    Text = "Erica antwortet nicht. Schwarzer Nebel sickert aus ihr hervor und enthüllt eine weitere vertraute Gestalt."
  },
  AvgDialog_58330_Content_61 = {
    Text = "Ausgezeichnete Schlussfolgerung!"
  },
  AvgDialog_58330_Content_62 = {
    Text = "Also ist diese sogenannte Fräulein Erica Ihr Doppelgänger... was bedeutet, dass Fräulein Erica in Wirklichkeit wohlauf ist!"
  },
  AvgDialog_58330_Content_63 = {
    Text = "Ihr würdet den Spaß am Rollenspiel nicht verstehen, hehe."
  },
  AvgDialog_58330_Content_64 = {
    Text = "Ist die Schlussfolgerung, die Sie gerade vorgetragen haben, Ihre endgültige Antwort?"
  },
  AvgDialog_58330_Content_65 = {Text = "...Ja."},
  AvgDialog_58330_Content_66 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58330_Content_67 = {
    Text = "Heh... Wie schade. Einfach nur einen Schritt entfernt."
  },
  AvgDialog_58330_Content_68 = {
    Text = "Das ist nicht die endgültige Wahrheit, also—"
  },
  AvgDialog_58330_Content_69 = {
    Text = "N schnippte mit den Fingern, und dunkler Nebel begann aus Hannas Körper zu sickern und erfüllte das Arbeitszimmer."
  },
  AvgDialog_58330_Content_7 = {
    Text = "Das ist tatsächlich eine Möglichkeit. Beim Vergleich haben wir festgestellt, dass das Muster auf der Sohle dieses Schuhs perfekt mit dem Fußabdruck auf dem Fensterrahmen übereinstimmt."
  },
  AvgDialog_58330_Content_70 = {
    Text = "Sie klammerte sich panisch an Rykers Mantel."
  },
  AvgDialog_58330_Content_71 = {
    Text = "Wie kann das sein? Fräulein Erica hat es auch nicht bestritten?!"
  },
  AvgDialog_58330_Content_72 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58330_Content_73 = {
    Text = "Tsk, tsk, tsk, dein Schutzherr-Kumpel ist zu voreilig, denk daran, nächstes Mal vor {Male=he,Female=she} zu sprechen～"
  },
  AvgDialog_58330_Content_74 = {
    Text = "Verzeih mir, Hanna. Ich..."
  },
  AvgDialog_58330_Content_75 = {
    Text = "Rettet mich...! Ich habe die endgültige Wahrheit noch nicht gehört, bitte nicht..."
  },
  AvgDialog_58330_Content_76 = {
    Text = "In der nächsten Sekunde verschwand auch Hanna vor euren Augen."
  },
  AvgDialog_58330_Content_77 = {Text = "Hanna—!"},
  AvgDialog_58330_Content_78 = {
    Text = "Was habe ich getan..."
  },
  AvgDialog_58330_Content_79 = {
    Text = "Nein, es ist alles meine Schuld... Ich war zu ungeduldig."
  },
  AvgDialog_58330_Content_8 = {
    Text = "Würde Lord Dexter, der stets auf Etikette bedacht ist, durch ein Fenster aus seinem Haus klettern, besonders wenn das Türschloss in einwandfreiem Zustand ist?"
  },
  AvgDialog_58330_Content_80 = {
    Text = "Mm, jetzt sind nur noch wir drei übrig. Was die anderen betrifft, sie müssen in der realen Welt leiden."
  },
  AvgDialog_58330_Content_81 = {
    Text = "Hehehe, interessant, sehr interessant!"
  },
  AvgDialog_58330_Content_82 = {
    Text = [[
Mythag Krankenhaus
Inzwischen...]]
  },
  AvgDialog_58330_Content_83 = {
    Text = "Wie ist die Lage?"
  },
  AvgDialog_58330_Content_84 = {
    Text = "Fräulein Hannas und des Schutzherrn Zustand verschlechtert sich ebenfalls. Fräulein Hannas innere Organe sind aus unbekannten Gründen an mehreren Stellen gerissen und zeigen Anzeichen von Blutungen."
  },
  AvgDialog_58330_Content_85 = {
    Text = "Der Schutzherr zeigt schwere Erstickungssymptome. Wenn wir weiter zögern..."
  },
  AvgDialog_58330_Content_86 = {
    Text = "Wir haben viele Schüler befragt, und unser Technikteam hat alle Einrichtungen überprüft, aber keine Auffälligkeiten gefunden."
  },
  AvgDialog_58330_Content_87 = {
    Text = "Einen solchen Aufruhr direkt vor aller Augen zu veranstalten..."
  },
  AvgDialog_58330_Content_88 = {Text = "...N."},
  AvgDialog_58330_Content_89 = {
    Text = "Alistair und ich sind uns einig. Wenn Er es ist, ergibt alles einen Sinn."
  },
  AvgDialog_58330_Content_9 = {
    Text = "Hat er etwas vor dem Fenster gesehen und ist hinausgestürzt?"
  },
  AvgDialog_58330_Content_90 = {
    Text = "Was sollen wir tun? Wir haben keinerlei Gegenmaßnahmen..."
  },
  AvgDialog_58330_Content_91 = {
    Text = "Doll berührte den runden Kopf in ihrer Hand und stieß einen leisen Seufzer aus."
  },
  AvgDialog_58330_Content_92 = {
    Text = "Eines ist sicher: Es scheint immer noch nicht darauf erpicht zu sein, dem Schutzherrn das Leben zu nehmen."
  },
  AvgDialog_58330_Content_93 = {
    Text = "Was den Rest betrifft... Ich schlage vor, dass Ihr mit mir betet."
  },
  AvgDialog_58330_Content_94 = {
    Text = "Gut, jetzt, da die Unbeteiligten fort sind, können wir ehrlich sein."
  },
  AvgDialog_58330_Content_95 = {
    Text = "Ein eisiger Nebel wallte von Ns Körper empor und legte sich Schicht um Schicht über Sein Gesicht, bis Sein ursprüngliches Aussehen vollständig verborgen war."
  },
  AvgDialog_58330_Content_96 = {
    Text = "Nicht nur das – der Raum, in dem ihr euch befindet, verschwindet plötzlich und wird durch das vertraute Opernhaus ersetzt."
  },
  AvgDialog_58330_Content_97 = {
    Text = "Verzeihung, ich bin kein Freund von engen Räumen."
  },
  AvgDialog_58330_Content_98 = {
    Text = "Lange nicht gesehen, meine alten Freunde."
  },
  AvgDialog_58330_Content_99 = {
    Text = "Was meintet Ihr vorhin? Das ist nicht die endgültige Wahrheit...?"
  },
  AvgDialog_58331_Content_1 = {
    Text = "Jetzt, Apophis!"
  },
  AvgDialog_58331_Content_10 = {
    Text = "Ryker ging Schritt für Schritt auf N zu."
  },
  AvgDialog_58331_Content_11 = {
    Text = "Sieht so aus, als wäre das Glück endlich auf meiner Seite."
  },
  AvgDialog_58331_Content_12 = {
    Text = "Sei vorsichtig, Detektiv. Für einen unverbesserlichen Spieler ist das Beängstigendste bei einem Glücksspiel nicht das Verlieren, sondern das Gewinnen."
  },
  AvgDialog_58331_Content_13 = {
    Text = "Wenn du mir nicht glaubst, frag doch den Meister dieser schwarzen Schlange."
  },
  AvgDialog_58331_Content_14 = {
    Text = "Es scheint, du kennst mich immer noch nicht gut genug, aber in einem Punkt hast du recht."
  },
  AvgDialog_58331_Content_15 = {
    Text = "Ryker hob seine Waffe und zielte auf Ns nebliges Gesicht."
  },
  AvgDialog_58331_Content_16 = {
    Text = "Ich bin tatsächlich ein hoffnungsloser Spieler. Ungeachtet des Glücks, selbst wenn ich weiß, dass ich alles verlieren werde, setze ich trotzdem alles auf eine Karte."
  },
  AvgDialog_58331_Content_17 = {
    Text = "Nur diejenigen, die vom Schicksal begünstigt sind, wagen es, Risiken einzugehen; sie sind gewöhnliche Menschen, keine Spieler. Als du mich damals gewählt hast, war es nicht, weil du das in mir gesehen hast?"
  },
  AvgDialog_58331_Content_18 = {
    Text = "Hah... Hahaha... Du bist wirklich ein Wahnsinniger. Deinen Urinstinkten nachzugeben, wie töricht und naiv, Herr Spieler."
  },
  AvgDialog_58331_Content_19 = {
    Text = "Ebenso. Mein größter Vorteil gegenüber anderen Spielern ist —"
  },
  AvgDialog_58331_Content_2 = {
    Text = "Auf deinen Befehl hin schoss die dunkle Königsschlange blitzschnell hervor, durchbohrte Ns Körper und wand sich fest darum."
  },
  AvgDialog_58331_Content_21 = {
    Text = "Ich akzeptiere meine Niederlage mit Ehre."
  },
  AvgDialog_58331_Content_22 = {
    Text = "Der Abzug wird sanft gedrückt."
  },
  AvgDialog_58331_Content_23 = {
    Text = "Ein Schuss ertönte, und Ns Kopf neigte sich sanft zur Seite."
  },
  AvgDialog_58331_Content_24 = {
    Text = "Du hast es wirklich eilig, nicht wahr? Ich hatte bereits vor, dich zu verabschieden."
  },
  AvgDialog_58331_Content_25 = {
    Text = "Bevor ich gehe, verrate ich dir ein Geheimnis —"
  },
  AvgDialog_58331_Content_26 = {
    Text = "Tatsächlich habe ich dein Schicksal nie umgeschrieben. Bei einem so interessanten Spiel zu schummeln, würde keinerlei Freude bringen."
  },
  AvgDialog_58331_Content_27 = {
    Text = "Leb wohl, Detektiv."
  },
  AvgDialog_58331_Content_3 = {
    Text = "Der schwarze Nebel, der von der Königsschlange ausgeht, verschmilzt mit Ns eigenem schwarzen Nebel und verleiht Ihm allmählich eine physische Gestalt."
  },
  AvgDialog_58331_Content_4 = {
    Text = "Lange nicht gesehen, Kanaks kleines Haustier. Ist dein Meister immer noch verärgert?"
  },
  AvgDialog_58331_Content_5 = {
    Text = "Der Meister hegt keinen Hass gegen Euch. Seine Taten wurden von Euch gebilligt. Wir folgen lediglich treu dem Drehbuch."
  },
  AvgDialog_58331_Content_6 = {
    Text = "Ist das so... interessant. Das war nicht einmal mir bewusst."
  },
  AvgDialog_58331_Content_7 = {
    Text = "Die schlanke Zunge der Königsschlange züngelte und trug ihre tiefe, beruhigende Stimme an dein Ohr."
  },
  AvgDialog_58331_Content_8 = {
    Text = "Ich kann Seine Projektion nur eine Weile im Geheimgang gefangen halten. Sobald die Projektion sich zurückzieht, wird der Geheimgang aufgelöst."
  },
  AvgDialog_58331_Content_9 = {
    Text = "Als Nächstes... liegt es an dir."
  },
  AvgDialog_58332_Content_1 = {
    Text = "Letzter Gruß"
  },
  AvgDialog_58332_Content_10 = {
    Text = "Wie Tränen."
  },
  AvgDialog_58332_Content_11 = {
    Text = "Was geschah danach? Nachdem du... die sogenannte Wahrheit gesehen hast."
  },
  AvgDialog_58332_Content_12 = {
    Text = "Nach... Ich schlug die Rebellion nieder und verwandelte Apophis in eine Schlange, die auf ewig zu meinen Füßen liegt."
  },
  AvgDialog_58332_Content_13 = {
    Text = "Ich befahl, die Mauer der Wahrheit vollständig zu versiegeln, und begann dann meine eigene Herrschaft."
  },
  AvgDialog_58332_Content_14 = {
    Text = "Keine Ideologie, kein System, kein Parlament... Ich stelle einfach eine Namensliste auf, verbanne sie einen nach dem anderen und beschlagnahme ihr Vermögen."
  },
  AvgDialog_58332_Content_15 = {
    Text = "Ich verlieh Bürgern Orden, die das Casino mehr als 50 Mal besucht hatten, und ordnete den Bau einer ewig unvollendeten Glaspyramide in der Hauptstadt an..."
  },
  AvgDialog_58332_Content_16 = {
    Text = "Vom Schicksal verhöhnt, wurdest du zum Tyrannen. Wurdest du später gestürzt?"
  },
  AvgDialog_58332_Content_17 = {
    Text = "Ganz im Gegenteil, meine Nation blüht. Weißt du, warum?"
  },
  AvgDialog_58332_Content_18 = {
    Text = "Du schütteltest den Kopf. Der schwarze Nebel kicherte vergnügt."
  },
  AvgDialog_58332_Content_19 = {
    Text = "Selbst der kleinste Krieg, den ein rationaler Tyrann führt, kostet tausendmal mehr als der Preis, den das Volk für meine Launen zahlt."
  },
  AvgDialog_58332_Content_2 = {Text = "Zuvor..."},
  AvgDialog_58332_Content_20 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58332_Content_21 = {
    Text = "Aber du bist nicht glücklich, und dein Volk wird mit solch launenhaften Taten nicht zufrieden sein. Was soll das Ganze?"
  },
  AvgDialog_58332_Content_22 = {
    Text = "Sinn? Sogenanntes Glück und Sinn zu verfolgen heißt, in die Falle dieses Erwachsenen zu tappen. Ich bin weder glücklich noch traurig."
  },
  AvgDialog_58332_Content_23 = {
    Text = "Ich spiele lediglich treu die Rolle, die das Schicksal von mir zu spielen verlangt."
  },
  AvgDialog_58332_Content_24 = {Text = "Er...?"},
  AvgDialog_58332_Content_25 = {
    Text = "Beim Anblick der boshaften und doch irgendwie vertrauten Graffiti hast du plötzlich alles verstanden."
  },
  AvgDialog_58332_Content_26 = {
    Text = "Also bist du es, N..."
  },
  AvgDialog_58332_Content_27 = {
    Text = "Du bist also ein Opfer der Launen dieser Person geworden. Jetzt sitzen wir beide hier fest und können nichts tun..."
  },
  AvgDialog_58332_Content_28 = {
    Text = "Hast du das gehört? Der Schuss — dein Freund hat noch nicht aufgegeben."
  },
  AvgDialog_58332_Content_29 = {
    Text = "Während ich meine Erinnerungen las, habe ich auch deine gelesen. Für Ihn sind du und dieser Detektiv... anders."
  },
  AvgDialog_58332_Content_3 = {Text = "Bang—!"},
  AvgDialog_58332_Content_30 = {
    Text = "So macht es mir nichts aus, ihm eine Überraschung zu geben."
  },
  AvgDialog_58332_Content_31 = {
    Text = "Dunkler Nebel wirbelte um Karnak und verdichtete sich allmählich zu einer pechschwarzen Königskobra."
  },
  AvgDialog_58332_Content_32 = {
    Text = "Du solltest besser nicht aus Langeweile meinen Schlaf stören, mein alter Freund."
  },
  AvgDialog_58332_Content_33 = {
    Text = "Lange nicht gesehen, Apophis. Das ist ein neuer Freund von mir, {Male=he,Female=she} braucht deine Hilfe."
  },
  AvgDialog_58332_Content_34 = {
    Text = "Apophis steht anmutig da, den Hals sanft geneigt, smaragdgrüne Schlitzpupillen betrachten dich still."
  },
  AvgDialog_58332_Content_35 = {
    Text = "Das Geheimnis des ewigen Lebens ist kein anderes als das Vergessen. Mein Meister hat dich erneut vergessen, so wie er sich auch nicht an seine Vergangenheit in Taranto erinnert."
  },
  AvgDialog_58332_Content_36 = {
    Text = "Aber ich kenne deinen Geist, das bleiche Blinde Auge."
  },
  AvgDialog_58332_Content_37 = {
    Text = "Bist du... mir schon begegnet?"
  },
  AvgDialog_58332_Content_38 = {
    Text = "Bringe %player% von hier weg, Apophis."
  },
  AvgDialog_58332_Content_39 = {
    Text = "Die schwarze Schlange umschlingt sanft deinen Körper, während Nebel in deinen Körper fließt."
  },
  AvgDialog_58332_Content_4 = {
    Text = "Der Schuss scheint aus der Ferne zu kommen."
  },
  AvgDialog_58332_Content_40 = {
    Text = "Du schlossest die Augen. Dein leerer Körper wurde von unausgesprochenem Bewusstsein erfüllt, und das Schimmern des silbernen Schlüssels erstrahlte erneut."
  },
  AvgDialog_58332_Content_41 = {
    Text = "Im nächsten Moment war der Sarg bereits verschwunden, und du fandest dich in einer Ecke des Theaters wieder, mit Blick auf Ryker und N in der Mitte der Bühne."
  },
  AvgDialog_58332_Content_42 = {
    Text = "Ein sanftes und besonnenes Flüstern hallt tief in meinem Geist wider."
  },
  AvgDialog_58332_Content_43 = {
    Text = "Ich habe den Befehlen meines Herrn gehorcht und dich hierhergebracht."
  },
  AvgDialog_58332_Content_44 = {
    Text = "Der Albtraum ist vorbei. Öffne deine Augen."
  },
  AvgDialog_58332_Content_5 = {
    Text = "Du öffnest die Augen und siehst dieselbe Wand, bedeckt mit verzerrten Zeichen."
  },
  AvgDialog_58332_Content_6 = {
    Text = "Irgendwann hatte es angefangen zu regnen."
  },
  AvgDialog_58332_Content_7 = {
    Text = "Ein schwarzer Nebel schwebt neben dir. Du kannst seine Umrisse nicht erkennen, doch du spürst ein seltsames Gefühl der Vertrautheit — es ist Kanak."
  },
  AvgDialog_58332_Content_8 = {
    Text = "Der Regen fiel weiter, und Stille lag zwischen euch beiden."
  },
  AvgDialog_58332_Content_9 = {
    Text = "Seltsam. Es regnete sowohl beim ersten als auch beim letzten Mal, als ich diese Wand sah."
  },
  AvgDialog_58879_Content_1 = {
    Text = "Jetzt, Apophis!"
  },
  AvgDialog_58879_Content_10 = {
    Text = "Ryker ging Schritt für Schritt auf N zu."
  },
  AvgDialog_58879_Content_11 = {
    Text = "Sieht so aus, als wäre das Glück endlich auf meiner Seite."
  },
  AvgDialog_58879_Content_12 = {
    Text = "Sei vorsichtig, Detektiv. Für einen unverbesserlichen Spieler ist das Beängstigendste bei einem Glücksspiel nicht das Verlieren, sondern das Gewinnen."
  },
  AvgDialog_58879_Content_13 = {
    Text = "Wenn du mir nicht glaubst, frag doch den Meister dieser schwarzen Schlange."
  },
  AvgDialog_58879_Content_14 = {
    Text = "Es scheint, du kennst mich immer noch nicht gut genug, aber in einem Punkt hast du recht."
  },
  AvgDialog_58879_Content_15 = {
    Text = "Ryker hob seine Waffe und zielte auf Ns nebliges Gesicht."
  },
  AvgDialog_58879_Content_16 = {
    Text = "Ich bin tatsächlich ein hoffnungsloser Spieler. Ungeachtet des Glücks, selbst wenn ich weiß, dass ich alles verlieren werde, setze ich trotzdem alles auf eine Karte."
  },
  AvgDialog_58879_Content_17 = {
    Text = "Nur diejenigen, die vom Schicksal begünstigt sind, wagen es, Risiken einzugehen; sie sind gewöhnliche Menschen, keine Spieler. Als du mich damals gewählt hast, war es nicht, weil du das in mir gesehen hast?"
  },
  AvgDialog_58879_Content_18 = {
    Text = "Hah... Hahaha... Du bist wirklich ein Wahnsinniger. Deinen Urinstinkten nachzugeben, wie töricht und naiv, Herr Spieler."
  },
  AvgDialog_58879_Content_19 = {
    Text = "Ebenso. Mein größter Vorteil gegenüber anderen Spielern ist —"
  },
  AvgDialog_58879_Content_2 = {
    Text = "Auf deinen Befehl hin schoss die dunkle Königsschlange blitzschnell hervor, durchbohrte Ns Körper und wand sich fest darum."
  },
  AvgDialog_58879_Content_21 = {
    Text = "Ich akzeptiere meine Niederlage mit Ehre."
  },
  AvgDialog_58879_Content_22 = {
    Text = "Der Abzug wird sanft gedrückt."
  },
  AvgDialog_58879_Content_23 = {
    Text = "Ein Schuss ertönte, und Ns Kopf neigte sich sanft zur Seite."
  },
  AvgDialog_58879_Content_24 = {
    Text = "Die Bühne zerbricht, der Bereich kollabiert, und die Königsschlange verschwindet spurlos"
  },
  AvgDialog_58879_Content_25 = {
    Text = "%player%, Vorsicht vor dem Felsbrocken! Spring auf meinen Rücken!"
  },
  AvgDialog_58879_Content_26 = {
    Text = "Du springst bereitwillig auf Rykers Rücken und festigst seinen Kragen"
  },
  AvgDialog_58879_Content_27 = {
    Text = "Über seine Schulter hinweg sah man, dass die Ränder von Ns Gesichtshöhle noch langsam zuckten"
  },
  AvgDialog_58879_Content_28 = {
    Text = "Du hast es wirklich eilig, nicht wahr? Ich hatte bereits vor, dich zu verabschieden."
  },
  AvgDialog_58879_Content_29 = {
    Text = "Bevor ich gehe, verrate ich dir ein Geheimnis —"
  },
  AvgDialog_58879_Content_3 = {
    Text = "Der schwarze Nebel, der von der Königsschlange ausgeht, verschmilzt mit Ns eigenem schwarzen Nebel und verleiht Ihm allmählich eine physische Gestalt."
  },
  AvgDialog_58879_Content_30 = {
    Text = "Tatsächlich habe ich dein Schicksal nie umgeschrieben. Bei einem so interessanten Spiel zu schummeln, würde keinerlei Freude bringen."
  },
  AvgDialog_58879_Content_31 = {
    Text = "Leb wohl, Detektiv."
  },
  AvgDialog_58879_Content_4 = {
    Text = "Lange nicht gesehen, Kanaks kleines Haustier. Ist dein Meister immer noch verärgert?"
  },
  AvgDialog_58879_Content_5 = {
    Text = "Der Meister hegt keinen Hass gegen Euch. Seine Taten wurden von Euch gebilligt. Wir folgen lediglich treu dem Drehbuch."
  },
  AvgDialog_58879_Content_6 = {
    Text = "Ist das so... interessant. Das war nicht einmal mir bewusst."
  },
  AvgDialog_58879_Content_7 = {
    Text = "Die schlanke Zunge der Königsschlange züngelte und trug ihre tiefe, beruhigende Stimme an dein Ohr."
  },
  AvgDialog_58879_Content_8 = {
    Text = "Ich kann Seine Projektion nur eine Weile im Geheimgang gefangen halten. Sobald die Projektion sich zurückzieht, wird der Geheimgang aufgelöst."
  },
  AvgDialog_58879_Content_9 = {
    Text = "Als Nächstes... liegt es an dir."
  },
  AvgDialog_58894_Content_1 = {
    Text = "Unerwünschter Gast"
  },
  AvgDialog_58894_Content_10 = {
    Text = "Nein. Was, wenn es schon Nacht ist?!"
  },
  AvgDialog_58894_Content_11 = {
    Text = "Du rollst dich schnell aus dem Bett, findest zielsicher Stift, Schmierpapier und Radiergummi und stopfst alles in deine Tasche."
  },
  AvgDialog_58894_Content_12 = {
    Text = "Nachdem alles bereit ist, atmest du tief durch und öffnest die Tür des Schlafsaals"
  },
  AvgDialog_58894_Content_13 = {Text = "Hmm...?"},
  AvgDialog_58894_Content_14 = {
    Text = "Ein roter Mond hing hoch am Himmel, die ganze Straße war in düsteres rotes Licht getaucht, als wäre sie in einen Schleier gehüllt"
  },
  AvgDialog_58894_Content_15 = {
    Text = "Es herrscht eine gespenstische Stille, die Straßenlaternen auf beiden Seiten der Straße flackern mit müdem Schimmer"
  },
  AvgDialog_58894_Content_16 = {
    Text = "Das ist nicht die Schule, die ich kenne"
  },
  AvgDialog_58894_Content_17 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58894_Content_18 = {
    Text = "Ich verstehe, das muss ein Traum sein. Gut, ich gehe zurück und schlafe weiter"
  },
  AvgDialog_58894_Content_19 = {
    Text = "Du drehst dich schnell um, aber die Zimmertür—ja, das ganze Gebäude—ist nirgends zu finden."
  },
  AvgDialog_58894_Content_2 = {
    Text = "Hier leben verschiedene Tiere, gelegentlich auch einige böse Wesen.\n— Ian · @2, \"Wiederbelebung des Wels\""
  },
  AvgDialog_58894_Content_20 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58894_Content_21 = {
    Text = "Du musstest dich wieder umdrehen und auf die Straße vor dir blicken."
  },
  AvgDialog_58894_Content_22 = {
    Text = "Ist da jemand—Hallo—"
  },
  AvgDialog_58894_Content_23 = {
    Text = "Guten Morgen, guten Tag, guten Abend—"
  },
  AvgDialog_58894_Content_24 = {
    Text = "Gluck, gluck!"
  },
  AvgDialog_58894_Content_25 = {
    Text = "Gott sei Dank, endlich hat mir etwas geantwortet!"
  },
  AvgDialog_58894_Content_26 = {
    Text = "Du rennst aufgeregt zur Quelle des Geräuschs, nur um einen kleinen roten Briefkasten zu finden."
  },
  AvgDialog_58894_Content_27 = {
    Text = "Gluck gluck, Verdauungsprobleme, Hilfe... Hilfe..."
  },
  AvgDialog_58894_Content_28 = {
    Text = "<BigShake:Whoa, ugh!!>"
  },
  AvgDialog_58894_Content_29 = {
    Text = "Der Briefkasten zuckte nervös und spuckte dann einen feuchten Brief aus."
  },
  AvgDialog_58894_Content_3 = {
    Text = "Klingel–klingel—"
  },
  AvgDialog_58894_Content_30 = {
    Text = "Ist das für mich? Es sieht ein bisschen eklig aus..."
  },
  AvgDialog_58894_Content_31 = {
    Text = "Rundherum sind alle Gebäude im dunkelroten Mondlicht getaucht, Türen und Fenster sind fest verschlossen, um jeden Zutritt zu verhindern"
  },
  AvgDialog_58894_Content_32 = {
    Text = "Du bist das einzige Lebewesen im Umkreis von hundert Meilen."
  },
  AvgDialog_58894_Content_33 = {
    Text = "Öffne den Umschlag"
  },
  AvgDialog_58894_Content_34 = {
    Text = "Du ignorierst bewusst das klebrige Gefühl an deinen Fingerspitzen und öffnest zitternd den Umschlag"
  },
  AvgDialog_58894_Content_35 = {
    Text = "An den fernen Empfänger:\nBitte erreichen Sie die Flandre-Villa vor Mitternacht. Seien Sie pünktlich, sonst tragen Sie die Konsequenzen (Gehirn @2 explodiert @3).\nAdresse: @2 Bezirk\n-▼"
  },
  AvgDialog_58894_Content_36 = {
    Text = "Das Ferland-Herrenhaus? Ich erinnere mich, das ist Herrn Dexters Anwesen. Seit wann spielt er denn auch Streiche...?"
  },
  AvgDialog_58894_Content_37 = {
    Text = "Du schaust auf dein leeres Handgelenk"
  },
  AvgDialog_58894_Content_38 = {
    Text = "Außerdem habe ich meine Uhr nicht dabei, also kann ich nicht mal die Zeit ablesen—"
  },
  AvgDialog_58894_Content_39 = {
    Text = "Tick tack. Tick tack."
  },
  AvgDialog_58894_Content_4 = {
    Text = "Mm... so müde, stör mich nicht."
  },
  AvgDialog_58894_Content_40 = {
    Text = "Eine riesige Uhr ist irgendwann am Himmel erschienen, deren Stunden- und Minutenzeiger genau auf 11 Uhr stehen."
  },
  AvgDialog_58894_Content_41 = {
    Text = "Nur der Sekundenzeiger bewegt sich kalt und gleichmäßig"
  },
  AvgDialog_58894_Content_42 = {
    Text = "Was... geschieht hier..."
  },
  AvgDialog_58894_Content_43 = {
    Text = "Hm, hast du denselben Brief bekommen wie ich?"
  },
  AvgDialog_58894_Content_44 = {
    Text = "Wer ist da?!"
  },
  AvgDialog_58894_Content_45 = {
    Text = "Entschuldigung, du warst gerade sehr konzentriert. Ich habe dich mehrmals gerufen"
  },
  AvgDialog_58894_Content_46 = {
    Text = "Erinnerst du dich nicht an mich? Ich bin Elsa. Wir hatten zusammen Fräulein Dolls Einführung in die Auflösung."
  },
  AvgDialog_58894_Content_47 = {
    Text = "Elsa... Jetzt erinnere ich mich, sie war diejenige, die sich oft Ramonas Notizen ausgeliehen hat."
  },
  AvgDialog_58894_Content_48 = {
    Text = "Entschuldigung, weil ich immer durchfalle"
  },
  AvgDialog_58894_Content_49 = {
    Text = "Elsa senkte den Kopf und drückte verzweifelt das herzförmige Kissen fest an sich."
  },
  AvgDialog_58894_Content_5 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58894_Content_50 = {
    Text = "Sei nicht traurig, Frau Elsa. In Frau Dolls Kurs durchzufallen ist ein Initiationsritus für die meisten Ermittler."
  },
  AvgDialog_58894_Content_51 = {
    Text = "Übrigens, du hast gerade gesagt, du hast einen ähnlichen Brief erhalten, kannst du das auch sehen?"
  },
  AvgDialog_58894_Content_52 = {
    Text = "Du zeigst auf die große Uhr über dem Vollmond. Elsa folgt deinem Blick und nickt leicht"
  },
  AvgDialog_58894_Content_53 = {
    Text = "Ich kann sie sehen. Aber ich habe mich verirrt, kann die richtige Richtung nicht finden, und es gibt noch weniger als eine Minute."
  },
  AvgDialog_58894_Content_54 = {
    Text = "Seltsam, mein Countdown zeigt noch eine Stunde an. Könnte es daran liegen, dass du diese Welt zuerst betreten hast?"
  },
  AvgDialog_58894_Content_55 = {
    Text = "Ich weiß nicht. Das ist nur ein Streich, %player%{Male=Herr,Female=Frau}? Ich war noch nie im Außendienst, ich habe keine Erfahrung mit anomalen Ereignissen"
  },
  AvgDialog_58894_Content_56 = {
    Text = "Ehrlich gesagt, das ist das erste Mal, dass ich so etwas erlebe"
  },
  AvgDialog_58894_Content_57 = {
    Text = "Zeit bis das Countdown endet: <Red:3> Sekunde"
  },
  AvgDialog_58894_Content_58 = {
    Text = "Du nimmst sanft Elsas Hand."
  },
  AvgDialog_58894_Content_59 = {
    Text = "Jetzt würde selbst ein Wurmloch nicht ausreichen, um dich rechtzeitig zur Flandre-Villa zu bringen, aber hab keine Angst"
  },
  AvgDialog_58894_Content_6 = {
    Text = "Oh nein, heute ist die Prüfung in Einführung in die Auflösungslehre. Wie spät ist es..."
  },
  AvgDialog_58894_Content_60 = {
    Text = "Zeit bis das Countdown endet: <Red:0> Sekunde"
  },
  AvgDialog_58894_Content_61 = {
    Text = "Egal, was als Nächstes passiert, ich werde beschützen —"
  },
  AvgDialog_58894_Content_62 = {Text = "Deine..."},
  AvgDialog_58894_Content_63 = {
    Text = "Elsas Kopf explodierte in eine warme Masse Gehirn. Dicke Flüssigkeit spritzt ins Gesicht, der Geruch von Eisen liegt in der Luft"
  },
  AvgDialog_58894_Content_64 = {
    Text = "%player%@2, rette @3..."
  },
  AvgDialog_58894_Content_65 = {
    Text = "Dunkler Schlamm sickert unaufhörlich aus dem gebrochenen Hals und formt rasch ein weiteres blasses, fremdes Gesicht."
  },
  AvgDialog_58894_Content_66 = {
    Text = "<Change>Rette mich, rette mich..."
  },
  AvgDialog_58894_Content_68 = {
    Text = "Die Klinge der Bestie durchschnitt die Luft und teilte „Elsa“ in zwei Hälften. Schwarzer D–Schleim schoss hervor wie Blut."
  },
  AvgDialog_58894_Content_69 = {
    Text = "Es ist zwecklos. Sie hat ihren Verstand schon vor langer Zeit verloren."
  },
  AvgDialog_58894_Content_7 = {
    Text = "6:37, noch früh..."
  },
  AvgDialog_58894_Content_70 = {
    Text = "Mr. Ryker?!"
  },
  AvgDialog_58894_Content_71 = {
    Text = "Ryker zog seine Bestienklauen ein und kam leichten Schrittes auf dich zu."
  },
  AvgDialog_58894_Content_72 = {
    Text = "Warum machst du so ein weinerliches Gesicht? Keine Sorge, dieser Ort ist wahrscheinlich jemandes Geheimgang."
  },
  AvgDialog_58894_Content_73 = {
    Text = "Geheimgang...?"
  },
  AvgDialog_58894_Content_74 = {
    Text = "Mm. Mit anderen Worten, diese Elsa ist in der Realität höchstwahrscheinlich noch am Leben."
  },
  AvgDialog_58894_Content_75 = {
    Text = "Nicht umsonst bist du Detektiv, du hast das künstliche Gebiet sofort durchschaut. Was ist die Grundlage dafür?"
  },
  AvgDialog_58894_Content_76 = {
    Text = "Als ich Elsa zum ersten Mal traf, war es auch so eine Nacht. Sie wurde von einer Gruppe von Schmelzmonstern verfolgt, und ich kam gerade aus der Taverne und zeigte ihr den Weg, während ich die Monster tötete"
  },
  AvgDialog_58894_Content_77 = {
    Text = "Wir sind uns gerade wieder begegnet, zur gleichen Zeit, am gleichen Ort, aber ich habe ihr den falschen Weg gezeigt und sie hat sich den Kopf gestoßen. Das heißt also—"
  },
  AvgDialog_58894_Content_78 = {
    Text = "Das heißt?"
  },
  AvgDialog_58894_Content_79 = {
    Text = "Mein Glück ist verschwunden! Das ist etwas, das absolut nicht passieren kann, also schlussfolgere ich logisch, dass dies nicht die Realität ist."
  },
  AvgDialog_58894_Content_8 = {
    Text = "Du tastest herum und drückst den Weckerschalter, und fällst zurück in tiefen Schlaf."
  },
  AvgDialog_58894_Content_80 = {
    Text = "Oder du könntest mir zweimal ins Gesicht klatschen, um zu prüfen, ob das ein Traum ist? Ich habe mir vorhin schon mehrmals selbst eine verpasst, aber es hat nichts gebracht."
  },
  AvgDialog_58894_Content_81 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58894_Content_82 = {
    Text = "Zack, was ich weiß, ist, dass ich nicht will, dass mein Kopf explodiert, weder im Geheimgang noch in der Realität."
  },
  AvgDialog_58894_Content_83 = {
    Text = "Du brauchst dringend meine Hilfe! Auf meinem Weg bin ich auf ziemlich viele Nachzügler wie Elsa gestoßen. Wir sollten besser die Luftroute nehmen."
  },
  AvgDialog_58894_Content_84 = {
    Text = "Ryker sprach und deutete auf das Dach eines nahegelegenen Gebäudes."
  },
  AvgDialog_58894_Content_85 = {
    Text = "Tut mir leid, ich bin nur ein gewöhnlicher Schutzherr und kann bei deinen akrobatischen Abenteuern nicht mitmachen—"
  },
  AvgDialog_58894_Content_86 = {
    Text = "In der nächsten Sekunde warf Ryker dich auf seinen Rücken und sprang in die Luft."
  },
  AvgDialog_58894_Content_87 = {
    Text = "Halt dich fest, {Male=Mr.,Female=Miss} %player%!"
  },
  AvgDialog_58894_Content_88 = {
    Text = "<Shake:Wahhh!!>"
  },
  AvgDialog_58894_Content_89 = {
    Text = "Du greifst erschrocken nach Leiks Kragen. Der gekrümmte Detektiv springt geschmeidig über die Dächer und schlüpft durch die klobigen Gebäude Londiniums"
  },
  AvgDialog_58894_Content_9 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58894_Content_90 = {
    Text = "Ein Mensch und ein Wolf stürzen unter dem ruhigen Mond. Das einzige, was du hörst, ist der reine Wind, du beugst dich und drückst dich in das weiche Fell unter dir"
  },
  AvgDialog_58894_Content_91 = {
    Text = "Und? Hat es Spaß gemacht?"
  },
  AvgDialog_58894_Content_92 = {
    Text = "Ich hätte nicht gedacht, dass du so etwas kannst... Verlangsamen, verlangsame!"
  },
  AvgDialog_58894_Content_93 = {
    Text = "Ryker lachte herzhaft, sein Brustkorb vibrierte, als würde jede Zelle in seinem Körper jubeln und vor Freude springen."
  },
  AvgDialog_58894_Content_94 = {
    Text = "Das ist es, was ein Wolf tun sollte! Ich kehre nur zu meinen alten Gewohnheiten zurück, verstanden?"
  },
  AvgDialog_58894_Content_95 = {
    Text = "Ich hab gesagt, <BigShake:Langsamer!!>"
  },
  AvgDialog_58894_Content_96 = {
    Text = "Sachte, sachte, vergreif dich nicht an meinem Fell!"
  },
  AvgDialog_58895_Content_1 = {
    Text = "Tragödienaufführung"
  },
  AvgDialog_58895_Content_10 = {
    Text = "Es gibt noch eine andere Meinung meinerseits zu diesem Punkt, aber lassen wir das vorerst beiseite. Was geschah, nachdem Herr Dexter das Haus verlassen hatte?"
  },
  AvgDialog_58895_Content_100 = {
    Text = "Es ist bedauerlich, dass ihr einen weiteren Freund verloren habt. Vielleicht ist das Glück in dieser Welt endlich."
  },
  AvgDialog_58895_Content_101 = {
    Text = "Ihr habt Glück erlangt, euer Leben hat sich erheblich verbessert, doch andere erlitten deswegen großes Unglück."
  },
  AvgDialog_58895_Content_102 = {
    Text = "Unsichtbare, mysteriöse Regeln schweben über den Köpfen der Menschen. Kannst du das wirklich akzeptieren?"
  },
  AvgDialog_58895_Content_103 = {
    Text = "Hehe... Was für ein mysteriöses Gesetz, das ist nur dein kleines Spiel"
  },
  AvgDialog_58895_Content_104 = {
    Text = "Eure Feindseligkeit mir gegenüber bleibt so aufrichtig, bezaubernd und doch bedauerlich."
  },
  AvgDialog_58895_Content_105 = {
    Text = "Obwohl es euch nicht gelungen ist, alle Rätsel zu lösen, war ich stets sehr nachsichtig..."
  },
  AvgDialog_58895_Content_106 = {
    Text = "N hob einen Finger und sandte dichten schwarzen Nebel auf euch zu, der euch fest umschlang."
  },
  AvgDialog_58895_Content_107 = {
    Text = "Nein... Ugh!"
  },
  AvgDialog_58895_Content_108 = {Text = "!!"},
  AvgDialog_58895_Content_109 = {
    Text = "Mr. N, ich weiß, dass mein Handeln in Aram Sie verärgert hat, und ich entschuldige mich aufrichtig."
  },
  AvgDialog_58895_Content_11 = {Text = "...!!"},
  AvgDialog_58895_Content_110 = {
    Text = "Du kannst mich bestrafen, aber {Male=er,Female=sie} ist unschuldig!"
  },
  AvgDialog_58895_Content_111 = {
    Text = "Ungeduldiger Detektiv, hören Sie mich an. Ich habe eine letzte Frage für Sie vorbereitet."
  },
  AvgDialog_58895_Content_112 = {
    Text = "Alright, ich höre zu."
  },
  AvgDialog_58895_Content_113 = {
    Text = "Einfache Wahl: Töte %player%, und ich werde alle zuvor Verstorbenen wiederbeleben"
  },
  AvgDialog_58895_Content_114 = {
    Text = "Alles wird wieder normal, außer für diesen Pechvogel neben Ihnen. Niemand sonst wird verletzt."
  },
  AvgDialog_58895_Content_115 = {
    Text = "Oder Sie könnten sich entscheiden, %player% nicht zu töten, und Sie beide können den Geheimgang sicher verlassen."
  },
  AvgDialog_58895_Content_116 = {
    Text = "War es wirklich so einfach?"
  },
  AvgDialog_58895_Content_117 = {Text = "?!"},
  AvgDialog_58895_Content_118 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58895_Content_119 = {
    Text = "Haben Sie noch Ihre Handfeuerwaffe dabei? Der Countdown beginnt jetzt. 10."
  },
  AvgDialog_58895_Content_12 = {
    Text = "Erinnert ihr euch an den Geist, den ich vorhin am Treppenaufgang gesehen habe? In der Luft schwebend, der Geist, das Erhängen... Könnte es sein..."
  },
  AvgDialog_58895_Content_120 = {
    Text = "Nein, du kannst nicht..."
  },
  AvgDialog_58895_Content_121 = {Text = "9"},
  AvgDialog_58895_Content_122 = {
    Text = "Ryker sah dich benommen an, wie ein Kind, das etwas falsch gemacht hatte."
  },
  AvgDialog_58895_Content_123 = {
    Text = "Mach dir keine Sorgen um mich, hust... Vielleicht machen sie mich zu einem Erweckten Körper, wenn ich sterbe."
  },
  AvgDialog_58895_Content_124 = {
    Text = "Du spannst alle Gesichtsmuskeln an, um Ryker ein gequältes Lächeln zu schenken."
  },
  AvgDialog_58895_Content_125 = {
    Text = "... Nur zu."
  },
  AvgDialog_58895_Content_126 = {Text = "6"},
  AvgDialog_58895_Content_127 = {
    Text = "Ryker ging langsam auf dich zu, seine Augen ruhig und gelassen."
  },
  AvgDialog_58895_Content_128 = {
    Text = "Als deine Sicht allmählich verschwamm, blicktest du in seine Augen, und Erinnerungen an gemeinsam verbrachte Momente zogen vor deinem inneren Auge vorbei."
  },
  AvgDialog_58895_Content_129 = {
    Text = "Es gibt Zeiten, in denen sie sich spielerisch durch die Wüste jagen, gemeinsam aus der ■■-Versammlung der Alanen fliehen und er sein Leben als Köder einsetzt, um Casiah zu verderben..."
  },
  AvgDialog_58895_Content_13 = {
    Text = "Richtig. Die Wahrheit ist: Jemand hat Herrn Dexter abgelenkt, ihm dann in dem Moment, als er sich hinauslehnte, eine Schlinge um den Hals gelegt und sie straff zugezogen —"
  },
  AvgDialog_58895_Content_130 = {
    Text = "Es gibt zu viele Erinnerungen zwischen euch beiden."
  },
  AvgDialog_58895_Content_131 = {
    Text = "Ohne dass du es bemerkt hast, stand Ryker bereits vor dir. Du konntest sein Gesicht nicht sehen, aber du wusstest, dass sein Schmerz nicht geringer war als deiner."
  },
  AvgDialog_58895_Content_132 = {
    Text = "Im nächsten Moment hob er die Pistole."
  },
  AvgDialog_58895_Content_133 = {
    Text = "Weißt du was... Ich habe nie an dir gezweifelt. Also—"
  },
  AvgDialog_58895_Content_134 = {
    Text = "Der Schuss ertönt und trifft genau dort, wo dein Herz ist, mitten ins Zentrum."
  },
  AvgDialog_58895_Content_135 = {Text = "Was...?"},
  AvgDialog_58895_Content_136 = {
    Text = "Ryker stand über dir, ein spöttisches Lächeln auf den Lippen."
  },
  AvgDialog_58895_Content_137 = {
    Text = "Ich habe lange auf diesen Moment gewartet, Hüter."
  },
  AvgDialog_58895_Content_14 = {
    Text = "Ryker hob sein Gesicht und deutete auf das Schlafzimmer im zweiten Stock."
  },
  AvgDialog_58895_Content_15 = {
    Text = "Der Mörder war damals in diesem Raum. Diese beiden Räume liegen genau in einer Linie"
  },
  AvgDialog_58895_Content_16 = {
    Text = "Brillant! Das erklärt das Geisterereignis und die Fußabdrücke auf dem Fensterrahmen — es lag an Herrn Dexters Kampf, nachdem er gefesselt wurde."
  },
  AvgDialog_58895_Content_17 = {
    Text = "Das erfordert viel Kraft und präzise Winkelvorhersage, alle hier haben ihre Fähigkeiten versiegelt, wie soll das möglich sein"
  },
  AvgDialog_58895_Content_18 = {
    Text = "Hanna hält mitten im Satz inne, eine Vermutung formt sich in ihrem Kopf."
  },
  AvgDialog_58895_Content_19 = {
    Text = "Aber... nach dem Geisterereignis sind wir schnell nach oben ins Schlafzimmer gegangen. Wir haben in dieser Zeit keine anderen Geräusche gehört. Der Mörder muss noch im Schlafzimmer gewesen sein"
  },
  AvgDialog_58895_Content_2 = {
    Text = "Hatschi... Hatschi!"
  },
  AvgDialog_58895_Content_20 = {
    Text = "Aber außer dem Plattenspieler gab es nichts Ungewöhnliches... Hatschi, Hatschi!"
  },
  AvgDialog_58895_Content_21 = {
    Text = "Hanna wischt sich zwei glänzende Rotzfäden weg."
  },
  AvgDialog_58895_Content_22 = {
    Text = "Vater im Himmel, wie kann man sich selbst in einem Geheimgang erkälten!"
  },
  AvgDialog_58895_Content_23 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58895_Content_24 = {
    Text = "Wir haben alles über draußen besprochen. Gehen wir rein"
  },
  AvgDialog_58895_Content_25 = {
    Text = "Denkt genau nach. Was geschah, nachdem wir die Tür eingetreten haben?"
  },
  AvgDialog_58895_Content_26 = {
    Text = "Was ist passiert..."
  },
  AvgDialog_58895_Content_27 = {
    Text = "Entschuldigung, mir geht es nicht gut. Kann ich eine kurze Pause machen?"
  },
  AvgDialog_58895_Content_28 = {
    Text = "Entschuldigung @2... Fühle mich nicht gut... Ruhe..."
  },
  AvgDialog_58895_Content_29 = {
    Text = "Ruhe, Ruhe@2 Ruhe..."
  },
  AvgDialog_58895_Content_3 = {
    Text = "Der Kühleffekt dieses Geheimgangs ist wirklich beeindruckend. Anführer, können wir nicht drinnen am Kamin schlussfolgern?"
  },
  AvgDialog_58895_Content_30 = {
    Text = "Alle, bitte verlassen Sie so schnell wie möglich den Raum und stören Sie Herrn Dexters Ruhe nicht."
  },
  AvgDialog_58895_Content_31 = {
    Text = "<Shake:Whoa!! Wann hast du...>"
  },
  AvgDialog_58895_Content_32 = {
    Text = "Miss Erica, auch wenn Sie jetzt eine Idiotin sind, möchte ich trotzdem daran erinnern: Hier gibt es nicht einmal ein Haar von Dexter"
  },
  AvgDialog_58895_Content_33 = {
    Text = "Alle, bitte verlasst so schnell wie möglich das Gebäude und..."
  },
  AvgDialog_58895_Content_34 = {
    Text = "Egal, lass sie erst mal"
  },
  AvgDialog_58895_Content_35 = {
    Text = "Also ist es so..."
  },
  AvgDialog_58895_Content_36 = {
    Text = "Hanna hebt plötzlich den Kopf und starrt direkt auf Erica hinter der Menge."
  },
  AvgDialog_58895_Content_37 = {
    Text = "Du warst kein Nachzügler. Du warst die ganze Zeit im Raum... Vielleicht hinter der Tür versteckt, hast unsere Aufmerksamkeit abgelenkt, während wir alle auf den Plattenspieler fokussiert waren."
  },
  AvgDialog_58895_Content_38 = {
    Text = "Abgelehnt. Erica hat nicht die Fähigkeit, an zwei Orten gleichzeitig zu sein, was es unmöglich macht zu erklären, warum der Verstorbene im Arbeitszimmer auftauchte."
  },
  AvgDialog_58895_Content_39 = {
    Text = "Ja, dir fehlt die Fähigkeit, an zwei Orten gleichzeitig zu sein. Deshalb hast du einen Helfer."
  },
  AvgDialog_58895_Content_4 = {
    Text = "Keine Sorge, es wird nicht allzu viel von jedermanns Zeit in Anspruch nehmen."
  },
  AvgDialog_58895_Content_40 = {Text = "!!"},
  AvgDialog_58895_Content_41 = {
    Text = "Einen erwachsenen Mann mit einem ausfahrbaren mechanischen Arm in der Luft zu erwürgen, ist ein Kinderspiel für Fräulein Erica."
  },
  AvgDialog_58895_Content_42 = {
    Text = "Nachdem Herr Dexter aufhört zu atmen, wirfst du ihn beiseite, und der Helfer, der die ganze Zeit gewartet hat, schleift die Leiche ins Arbeitszimmer."
  },
  AvgDialog_58895_Content_43 = {
    Text = "Das erklärt auch die zwei Strangulationsspuren und die Feuchtigkeit der Kleidung – weil die Leiche im Schnee geschleift wurde"
  },
  AvgDialog_58895_Content_44 = {
    Text = "Der Komplize muss die einzige Person ohne Alibi vom Schuss bis zum Verbrechen sein..."
  },
  AvgDialog_58895_Content_45 = {
    Text = "Während Ryker sprach, blickte er auf das Licht im Arbeitszimmer, das blass und gelb leuchtete"
  },
  AvgDialog_58895_Content_46 = {
    Text = "Frau Sorel."
  },
  AvgDialog_58895_Content_47 = {
    Text = "Verstehe. Ich dachte, Herr Dexter wurde in der Luft erwürgt, aber ich hätte nie erwartet, dass es einen Komplizen gibt."
  },
  AvgDialog_58895_Content_48 = {
    Text = "Abgelehnt. Alle obigen Schlussfolgerungen sind spekulativ und es fehlen konkrete Beweise."
  },
  AvgDialog_58895_Content_49 = {
    Text = "Beweise? Einfach genug."
  },
  AvgDialog_58895_Content_5 = {
    Text = "Zunächst die Schuhe draußen. Frage: Unter welchen Umständen würden Schuhe draußen landen?"
  },
  AvgDialog_58895_Content_50 = {
    Text = "Erinnert ihr euch an die Muster der beiden Würgemale am Hals?"
  },
  AvgDialog_58895_Content_51 = {
    Text = "Die Muster der beiden Eindrücke sind ebenfalls uneinheitlich. Innen zeigt sich eine ordentliche Rautenstruktur, während die äußere rauer ist..."
  },
  AvgDialog_58895_Content_52 = {
    Text = "Vielleicht ist das Seil mittendrin gerissen, oder es wurde blutig, also hat der Mörder es ausgetauscht."
  },
  AvgDialog_58895_Content_53 = {Text = "!!"},
  AvgDialog_58895_Content_54 = {
    Text = "Saubere Rautenformen. Fräulein Erica, könnten Sie Ihren mechanischen Arm ausstrecken und uns das einziehbare Verbindungsseil darin zeigen?"
  },
  AvgDialog_58895_Content_55 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58895_Content_56 = {
    Text = "Einen wachsamen erwachsenen Mann im zweiten Stock mit einem Seil am Hals zu fangen, ist nahezu unmöglich."
  },
  AvgDialog_58895_Content_57 = {
    Text = "Aber wenn das Seil Teil Ihres Körpers ist, dann ergibt alles einen Sinn."
  },
  AvgDialog_58895_Content_58 = {
    Text = "Also sind Sie es, Fräulein Erica..."
  },
  AvgDialog_58895_Content_59 = {
    Text = "Erica streckt langsam ihren rechten Arm aus. Im Licht schimmert die Verbindungsschnur zwischen ihrem Unterarm und ihrer Hand auf schaurige Weise"
  },
  AvgDialog_58895_Content_6 = {
    Text = "Mm... ist der Verstorbene hinausgegangen und dann verunglückt?"
  },
  AvgDialog_58895_Content_60 = {
    Text = "Diese rautenförmigen Muster sind in ordentlichen Reihen angeordnet, wie die Schuppen eines Fisches aus der Tiefsee."
  },
  AvgDialog_58895_Content_61 = {
    Text = "Einfach wie erwartet... genau gleich..."
  },
  AvgDialog_58895_Content_62 = {
    Text = "Erica antwortete nicht. Der schwarze Nebel in ihrem Inneren quoll heraus, dann——"
  },
  AvgDialog_58895_Content_63 = {
    Text = "Schöne Deduktion! Ist das eure endgültige Schlussfolgerung?"
  },
  AvgDialog_58895_Content_64 = {
    Text = "Natürlich. Ich denke nicht, dass es hier noch Probleme gibt"
  },
  AvgDialog_58895_Content_65 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58895_Content_66 = {
    Text = "Heh... Wie schade. Einfach nur einen Schritt entfernt."
  },
  AvgDialog_58895_Content_67 = {
    Text = "Das ist nicht die endgültige Wahrheit, also—"
  },
  AvgDialog_58895_Content_68 = {
    Text = "N schnippte mit den Fingern, und dunkler Nebel begann aus Hannas Körper zu sickern und erfüllte das Arbeitszimmer."
  },
  AvgDialog_58895_Content_69 = {
    Text = "Sie klammerte sich panisch an Rykers Mantel."
  },
  AvgDialog_58895_Content_7 = {
    Text = "Das ist tatsächlich eine Möglichkeit. Beim Vergleich haben wir festgestellt, dass das Muster auf der Sohle dieses Schuhs perfekt mit dem Fußabdruck auf dem Fensterrahmen übereinstimmt."
  },
  AvgDialog_58895_Content_70 = {
    Text = "Wie kann das sein? Fräulein Erica hat es auch nicht bestritten?!"
  },
  AvgDialog_58895_Content_71 = {
    Text = "Warte! Ich war noch nicht fertig"
  },
  AvgDialog_58895_Content_72 = {
    Text = "Tsk, tsk, tsk, dein Schutzherr-Kumpel ist zu voreilig, denk daran, nächstes Mal vor {Male=he,Female=she} zu sprechen～"
  },
  AvgDialog_58895_Content_73 = {
    Text = "Rette mich... Boss! Ich habe die letzte Wahrheit noch nicht gehört, bitte nicht"
  },
  AvgDialog_58895_Content_74 = {
    Text = "In der nächsten Sekunde verschwand auch Hanna vor euren Augen."
  },
  AvgDialog_58895_Content_75 = {
    Text = "Miss Hannah!"
  },
  AvgDialog_58895_Content_76 = {
    Text = "Nein, es ist alles meine Schuld..."
  },
  AvgDialog_58895_Content_77 = {
    Text = "Mm, jetzt sind nur noch wir drei übrig. Was die anderen betrifft, sie müssen in der realen Welt leiden."
  },
  AvgDialog_58895_Content_78 = {
    Text = "Hehehe, interessant, sehr interessant!"
  },
  AvgDialog_58895_Content_79 = {
    Text = [[
Mythag Krankenhaus
Inzwischen...]]
  },
  AvgDialog_58895_Content_8 = {
    Text = "Würde Lord Dexter, der stets auf Etikette bedacht ist, durch ein Fenster aus seinem Haus klettern, besonders wenn das Türschloss in einwandfreiem Zustand ist?"
  },
  AvgDialog_58895_Content_80 = {
    Text = "Wie ist die Lage?"
  },
  AvgDialog_58895_Content_81 = {
    Text = "Fräulein Hannas und des Schutzherrn Zustand verschlechtert sich ebenfalls. Fräulein Hannas innere Organe sind aus unbekannten Gründen an mehreren Stellen gerissen und zeigen Anzeichen von Blutungen."
  },
  AvgDialog_58895_Content_82 = {
    Text = "Der Schutzherr zeigt schwere Erstickungssymptome. Wenn wir weiter zögern..."
  },
  AvgDialog_58895_Content_83 = {
    Text = "Wir haben viele Schüler befragt, und unser Technikteam hat alle Einrichtungen überprüft, aber keine Auffälligkeiten gefunden."
  },
  AvgDialog_58895_Content_84 = {
    Text = "Einen solchen Aufruhr direkt vor aller Augen zu veranstalten..."
  },
  AvgDialog_58895_Content_85 = {Text = "...N."},
  AvgDialog_58895_Content_86 = {
    Text = "Alistair und ich sind uns einig. Wenn Er es ist, ergibt alles einen Sinn."
  },
  AvgDialog_58895_Content_87 = {
    Text = "Was sollen wir tun? Wir haben keinerlei Gegenmaßnahmen..."
  },
  AvgDialog_58895_Content_88 = {
    Text = "Doll berührte den runden Kopf in ihrer Hand und stieß einen leisen Seufzer aus."
  },
  AvgDialog_58895_Content_89 = {
    Text = "Eines ist sicher: Es scheint immer noch nicht darauf erpicht zu sein, dem Schutzherrn das Leben zu nehmen."
  },
  AvgDialog_58895_Content_9 = {
    Text = "Hat er etwas vor dem Fenster gesehen und ist hinausgestürzt?"
  },
  AvgDialog_58895_Content_90 = {
    Text = "Was den Rest betrifft... Ich schlage vor, dass Ihr mit mir betet."
  },
  AvgDialog_58895_Content_91 = {
    Text = "Gut, jetzt, da die Unbeteiligten fort sind, können wir ehrlich sein."
  },
  AvgDialog_58895_Content_92 = {
    Text = "Ein eisiger Nebel wallte von Ns Körper empor und legte sich Schicht um Schicht über Sein Gesicht, bis Sein ursprüngliches Aussehen vollständig verborgen war."
  },
  AvgDialog_58895_Content_93 = {
    Text = "Nicht nur das, der Schnee verschwand plötzlich und stattdessen befandet ihr euch im vertrauten Opernhaus"
  },
  AvgDialog_58895_Content_94 = {
    Text = "Entschuldigt bitte. Ich bin sehr anspruchsvoll, was die Qualität der Umgebung angeht"
  },
  AvgDialog_58895_Content_95 = {
    Text = "Lange nicht gesehen, meine alten Freunde."
  },
  AvgDialog_58895_Content_96 = {
    Text = "Was meintet Ihr vorhin? Das ist nicht die endgültige Wahrheit...?"
  },
  AvgDialog_58895_Content_97 = {
    Text = "Weil du den wahren Mörder von Mrs. Sorel nicht identifiziert hast. Deine Deduktionen meiden absichtlich ihren Tod, nicht wahr?"
  },
  AvgDialog_58895_Content_98 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_58895_Content_99 = {
    Text = "Entschuldigung, ich war zu ungeduldig und habe dich unterbrochen"
  },
  AvgDialog_59157_Content_1 = {
    Text = "Führer, Zauberer und Sklave"
  },
  AvgDialog_60107_Content_10 = {
    Text = "Lotan lehnte sich auf die Bank zurück und dehnte seine Gelenke."
  },
  AvgDialog_60107_Content_100 = {
    Text = "Remouahes Plan ist gescheitert, was bedauerlich, aber letztendlich belanglos ist."
  },
  AvgDialog_60107_Content_101 = {
    Text = "Das einzige, was wirklich zählt, ist heute—heute, zwanzig Jahre später."
  },
  AvgDialog_60107_Content_102 = {
    Text = "Es ist eine Freude, diesen wichtigen Moment mit einem Partner wie dir zu erleben"
  },
  AvgDialog_60107_Content_103 = {
    Text = "Unser Ziel ist dasselbe. Diese Aufführung ist nicht für uns"
  },
  AvgDialog_60107_Content_104 = {
    Text = "Um die Musik dieses großen Wesens wieder zu hören, ist jeder Einsatz unbedeutend"
  },
  AvgDialog_60107_Content_105 = {
    Text = "Drehen, stehen. Der junge Dirigent hebt die Hände und verbeugt sich vor dem leeren Theater, vor den unbekannten Tiefen des Sternenhimmels außerhalb des Theaters"
  },
  AvgDialog_60107_Content_106 = {
    Text = "Alles ist bereit, machen wir uns auf den Weg, Frau Juliette"
  },
  AvgDialog_60107_Content_107 = {
    Text = "Die wahre Aufführung beginnt jetzt"
  },
  AvgDialog_60107_Content_11 = {
    Text = "Seit der Schlüsselgrabzeremonie hat Mythag ein Problem nach dem anderen getroffen."
  },
  AvgDialog_60107_Content_12 = {
    Text = "Es ist großartig, interessante Gegner zu treffen, aber auch eine kleine Auszeit ist nicht schlecht."
  },
  AvgDialog_60107_Content_13 = {
    Text = "Ogier senkte seine Lanze und stand mit einem leichten Stirnrunzeln zur Seite."
  },
  AvgDialog_60107_Content_14 = {
    Text = "Sprechen wir darüber... Lady Lotan, denkst du nicht, dass wir in letzter Zeit zu häufig auf Dinge gestoßen sind?"
  },
  AvgDialog_60107_Content_15 = {
    Text = "Vom Armenhaus, dem Wachs-Museum, über Rai und Sonaniel bis zu den heiligen Dünen von Remouahe..."
  },
  AvgDialog_60107_Content_16 = {
    Text = "Seit der Herr Hüter wurde, haben sich diese Ereignisse angesammelt. Es scheint kein Zufall zu sein."
  },
  AvgDialog_60107_Content_17 = {
    Text = "Doll hat auch mit mir darüber gesprochen, aber ich bin nicht sehr interessiert."
  },
  AvgDialog_60107_Content_18 = {
    Text = "\"Überlass das Denken Doll und den anderen. Unsere Aufgabe ist anders.\""
  },
  AvgDialog_60107_Content_19 = {
    Text = "Lotan legte geschickt ihre Hand auf das hochaufragende Riesenschwert neben sich."
  },
  AvgDialog_60107_Content_2 = {Text = "Admission"},
  AvgDialog_60107_Content_20 = {
    Text = "Der Geheimnisträger führt Missaga auf den richtigen Weg. Ich muss nur mit meinem Schwert erscheinen, wenn {Male=er,Female=sie} mich braucht"
  },
  AvgDialog_60107_Content_21 = {
    Text = "Du hast absolut recht, Lady Lotan! Ich glaube, unser Herr wird ganz bestimmt einen Weg finden, die Auflösung zu überwinden. Die Ruhe in Mythag ist der beste Beweis dafür!"
  },
  AvgDialog_60107_Content_22 = {
    Text = "Ogier warf einen letzten Blick auf den ruhigen Campus und hob eifrig sein Lance erneut an."
  },
  AvgDialog_60107_Content_23 = {
    Text = "Lass uns gehen, Ms. Lotan. Ich kenne viele interessante Ritterturniere. Nachdem die Patrouille heute abgeschlossen ist, können wir unseren Herrn einladen..."
  },
  AvgDialog_60107_Content_24 = {
    Text = "Wenn möglich, könntest du uns mitbringen?"
  },
  AvgDialog_60107_Content_25 = {Text = "!!!"},
  AvgDialog_60107_Content_26 = {
    Text = "Ogier drehte sich plötzlich um."
  },
  AvgDialog_60107_Content_27 = {
    Text = "Mythags Tor öffnete sich lautlos, und aus dem dichten Nebel, der Mythag einst von der Außenwelt isolierte, trat langsam eine Gruppe von Menschen hervor."
  },
  AvgDialog_60107_Content_28 = {
    Text = "Das Emblem des Mystia-Ausschusses ist eindeutig auf ihren Uniformen sichtbar."
  },
  AvgDialog_60107_Content_29 = {
    Text = "Du... du bist..."
  },
  AvgDialog_60107_Content_3 = {Text = "Ding—"},
  AvgDialog_60107_Content_30 = {
    Text = "Der führende Agent nahm ein Papier mit einem Siegel und komplizierten Mustern heraus und übergab es dann Ogier."
  },
  AvgDialog_60107_Content_31 = {
    Text = "Unter Untersuchung: Mitglieder von Mythag, angeführt von Alistair, führen illegale Forschungen zur Auflösung mithilfe des Schwarzen Beckens durch, was die Sicherheit der Bürger von Leo erheblich bedroht."
  },
  AvgDialog_60107_Content_32 = {
    Text = "Sonderoperationsteam des Mystia-Vertragsausschusses, hier um Mythag zu übernehmen und Verstöße zu verhaften."
  },
  AvgDialog_60107_Content_33 = {
    Text = "Der Ausschuss... Verbrecher... aber wir haben niemals eine Mitteilung erhalten!"
  },
  AvgDialog_60107_Content_34 = {
    Text = "Die Maßnahmen des Ausschusses erfordern keine Mitteilung an deine Schule, Kind."
  },
  AvgDialog_60107_Content_35 = {
    Text = "Ist das so? Aber ich erinnere mich anders an die Mythag-Regeln."
  },
  AvgDialog_60107_Content_36 = {
    Text = "Lotan erhob sich mit dem Schwert in der Hand."
  },
  AvgDialog_60107_Content_37 = {
    Text = "Ich weiß nicht, wie du den Nebel draußen vor der Schule durchdrungen hast; ich stelle mir vor, du wärst nicht so offen gewesen, bevor du besiegt wurdest."
  },
  AvgDialog_60107_Content_38 = {
    Text = "Laut den Regeln von Mythag wird jeder, der ohne Erlaubnis eintritt, als Eindringling angesehen, egal wer er ist."
  },
  AvgDialog_60107_Content_39 = {
    Text = "Achte auf deinen Ton, gnädige Frau. Sie sprechen jetzt mit dem Ausschuss!"
  },
  AvgDialog_60107_Content_4 = {
    Text = "Der klare Klang der Glocken erklingt, begleitet vom fernen Lachen der Mythag-Studenten, was die Vögel, die auf dem Dach ruhen, erschreckt."
  },
  AvgDialog_60107_Content_40 = {
    Text = "Es tut mir leid, ich habe meinen Allgemeinbildungskurs nicht bestanden. Was ist der Ausschuss...?"
  },
  AvgDialog_60107_Content_41 = {Text = "!!!"},
  AvgDialog_60107_Content_42 = {
    Text = "Bevor er einen klaren Blick bekommen konnte, war Lotan bereits hinter ihm."
  },
  AvgDialog_60107_Content_43 = {
    Text = "Ogier folgte Lotan und hob ein Schild hinter ihr."
  },
  AvgDialog_60107_Content_44 = {
    Text = "Mythag ist kein Ort, in den du einfach so spazieren kannst, Kleines."
  },
  AvgDialog_60107_Content_45 = {
    Text = "Lotan hielt ihr riesiges Schwert verkehrt herum und griff den Vorsitzenden des Ausschusses mit unaufhaltsamer Kraft am Griff an—"
  },
  AvgDialog_60107_Content_46 = {Text = "Ding—"},
  AvgDialog_60107_Content_47 = {
    Text = "Beruhige deinen Zorn und höre auf die Stimme tief in dir."
  },
  AvgDialog_60107_Content_48 = {
    Text = "Ruhe friedlich, mein Freund. All dieser Tumult betrifft dich nicht mehr..."
  },
  AvgDialog_60107_Content_49 = {
    Text = "Der klare Klang der Windspiele ertönt von irgendwo, leise und fern, aber deutlich hörbar."
  },
  AvgDialog_60107_Content_5 = {
    Text = "In der Dämmerung fiel das verschwommene Licht auf die Statue des Gründers und beleuchtete Lotans Gesicht."
  },
  AvgDialog_60107_Content_50 = {
    Text = "Lotans Großschwert und Ogier's Gewehrschild fielen zu Boden. Beide unbewacht, verloren sie jegliche Kraft beim Hören der Windglocken."
  },
  AvgDialog_60107_Content_51 = {
    Text = "Eine überwältigende Schläfrigkeit überkommt seinen Körper. Er kämpft darum, die Augen offen zu halten."
  },
  AvgDialog_60107_Content_52 = {
    Text = "Im verschwommenen Blick erscheint langsam die Figur einer Frau hinter dem Nebel."
  },
  AvgDialog_60107_Content_53 = {
    Text = "Kein Wunder, dass es Mythag ist. Die Landschaft ist so bezaubernd, wie die Gerüchte sagen."
  },
  AvgDialog_60107_Content_54 = {Text = "Du... bist"},
  AvgDialog_60107_Content_55 = {
    Text = "Wir haben uns schon einmal getroffen, aber ich nehme an, Sie haben es vergessen, junger Herr."
  },
  AvgDialog_60107_Content_56 = {
    Text = "Armenhaus...Psychologe..."
  },
  AvgDialog_60107_Content_57 = {
    Text = "Ah, nach so langer Zeit in Erinnerung gehalten zu werden, was für eine Ehre."
  },
  AvgDialog_60107_Content_58 = {
    Text = "Es tut mir leid, dass ich nicht sofort herausgekommen bin, um dich zu treffen, aber im Angesicht von Mythags Erweckern sind einige clevere Tricks wirklich erforderlich, um sich den Weg freizukämpfen."
  },
  AvgDialog_60107_Content_59 = {Text = "Ruhe gut."},
  AvgDialog_60107_Content_6 = {
    Text = "Was für ein seltener, perfekter Tag. Ogier, komm und kämpfe mit mir."
  },
  AvgDialog_60107_Content_60 = {
    Text = "Sie streichelte sanft Lotan und Ogier über den Kopf. Sie konnten nicht länger durchhalten und fielen in einen tiefen Schlaf."
  },
  AvgDialog_60107_Content_61 = {
    Text = "\"Clementine stand auf, hob leicht ihren Arm und zeigte auf das Innere von Mythag.\""
  },
  AvgDialog_60107_Content_62 = {
    Text = "Dieser isolierte Campus muss sich ebenfalls seinem Schicksal stellen."
  },
  AvgDialog_60107_Content_63 = {
    Text = "Mythag-Invasion, beginnen."
  },
  AvgDialog_60107_Content_64 = {
    Text = "12 Yards entfernt versteckte sich Hannah im Gebüsch, ihre Hand fest über ihren Mund gelegt, um keinen Laut von sich zu geben."
  },
  AvgDialog_60107_Content_65 = {
    Text = "Durch die Ritzen im Gras beobachtete sie, wie Clementine die Ausschussmitglieder von beiden Seiten ins Innere von Mythag führte."
  },
  AvgDialog_60107_Content_66 = {
    Text = "Große Sache... eine große Sache ist passiert"
  },
  AvgDialog_60107_Content_67 = {
    Text = "Wir müssen es allen sagen... und dem Geheimnisträger!"
  },
  AvgDialog_60107_Content_68 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_60107_Content_69 = {
    Text = "Der Taktstock des Dirigenten zog eine sanfte Kurve in der Luft. Das Musikstück kam zum Ende"
  },
  AvgDialog_60107_Content_7 = {
    Text = "Lady Lotan, unsere Patrouille ist noch nicht abgeschlossen."
  },
  AvgDialog_60107_Content_70 = {
    Text = "Die intensiven Akkorde und die komplexen mehrstimmigen Klanglandschaften beruhigen sich"
  },
  AvgDialog_60107_Content_71 = {
    Text = "Arpeggien von Flöte und Harfe schwebten sanft hinaus, wie die Wolken im Abendlicht"
  },
  AvgDialog_60107_Content_72 = {
    Text = "Harmonische, lang anhaltende Akkorde verflüchtigen sich langsam in der Luft, und das letzte Zeichen der Streicher bringt die Noten zum Abschluss"
  },
  AvgDialog_60107_Content_73 = {
    Text = "In diesem fernen Moment legte der Dirigent seinen Taktstock weg. Er berechnete schweigend"
  },
  AvgDialog_60107_Content_74 = {
    Text = "Zehn Sekunden, das Publikum versunken in die Musik, das Theater in morgendlicher Stille"
  },
  AvgDialog_60107_Content_75 = {
    Text = "Eine Minute und fünfzehn Sekunden, der Applaus des Publikums wird donnern und allmählich verklingen"
  },
  AvgDialog_60107_Content_76 = {
    Text = "In fünfundzwanzig Minuten werden das Orchester und das Publikum den Saal verlassen haben"
  },
  AvgDialog_60107_Content_77 = {
    Text = "Die Zeit ist genau wie geplant, wie eine zweite präzise Aufführung"
  },
  AvgDialog_60107_Content_78 = {
    Text = "Der Dirigent nickte zufrieden und verbeugte sich vor dem leeren Zuschauerraum"
  },
  AvgDialog_60107_Content_79 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_60107_Content_8 = {
    Text = "\"Du bist gut in allem, außer dass du zu ernst bist.\""
  },
  AvgDialog_60107_Content_80 = {
    Text = "In einer unauffälligen Ecke des Zuschauerraums ertönte erneut ein leiser Applaus"
  },
  AvgDialog_60107_Content_81 = {
    Text = "Eine großartige Vorstellung, Herr Hameln"
  },
  AvgDialog_60107_Content_82 = {
    Text = "Vielleicht war es vollständig, aber noch lange nicht großartig. Die wahre Meistervorstellung findet außerhalb des Theaters statt"
  },
  AvgDialog_60107_Content_83 = {
    Text = "Der Dirigent legte den Taktstock weg und schaute mit gerunzelter Stirn zur Dame an der Seite des Zuschauerraums"
  },
  AvgDialog_60107_Content_84 = {
    Text = "Wir haben es vorher gesagt, du solltest nicht im Theater sein, Frau Juliette"
  },
  AvgDialog_60107_Content_85 = {
    Text = "Unsere Zusammenarbeit hat nichts mit der Aufführung zu tun, ich möchte keine Störungen. Ich dachte, das wäre dir klar"
  },
  AvgDialog_60107_Content_86 = {
    Text = "Deine Anwesenheit hier könnte unnötige Probleme verursachen"
  },
  AvgDialog_60107_Content_87 = {
    Text = "Natürlich, Herr Hameln. Ich wäre sehr bedauert, wenn ich Ihre Aufführung nicht vor Ort hören würde"
  },
  AvgDialog_60107_Content_88 = {
    Text = "Juliette lächelte und nickte, während sie sanft die Falten ihres Kleidungsstückes glattstrich"
  },
  AvgDialog_60107_Content_89 = {
    Text = "An die Ausdrucksweise von Hameln hat sie sich längst gewöhnt und kümmert sich nicht darum"
  },
  AvgDialog_60107_Content_9 = {
    Text = "So rare Freizeit. Wäre es ohne etwas Unterhaltung nicht langweilig?"
  },
  AvgDialog_60107_Content_90 = {
    Text = "Übrigens, ich habe etwas Wichtiges, das ich Ihnen persönlich mitteilen muss."
  },
  AvgDialog_60107_Content_91 = {
    Text = "Hat die Aktion begonnen?"
  },
  AvgDialog_60107_Content_92 = {
    Text = "Richtig. Clementine hat die Patrouillen von Missaga problemlos erledigt, wir haben mehr Zeit gewonnen als erwartet"
  },
  AvgDialog_60107_Content_93 = {
    Text = "Dein Plan war sehr erfolgreich"
  },
  AvgDialog_60107_Content_94 = {
    Text = "Nur ein nicht allzu kompliziertes Vorspiel, es ist zu früh, um von Erfolg zu sprechen"
  },
  AvgDialog_60107_Content_95 = {
    Text = "Ich vertraue auf deine Weisheit, Herr Dirigent"
  },
  AvgDialog_60107_Content_96 = {
    Text = "Wie lange haben wir auf diesen Tag gewartet?"
  },
  AvgDialog_60107_Content_97 = {
    Text = "Fast zwei Jahrzehnte."
  },
  AvgDialog_60107_Content_98 = {
    Text = "Ja, fast zwanzig Jahre. Was für einen langen Zeitraum."
  },
  AvgDialog_60107_Content_99 = {
    Text = "Das Spiel zwischen den Bildhauern und Seefahrern hat genug Aufmerksamkeit auf sich gezogen; unsere Anwesenheit ist gut verborgen."
  },
  AvgDialog_60202_Content_1 = {
    Text = "Illegale Forschung? Übernahme von Mythag..."
  },
  AvgDialog_60202_Content_10 = {Text = "Greife an"},
  AvgDialog_60202_Content_11 = {
    Text = "\"Pass auf dich auf, Hannah.\""
  },
  AvgDialog_60202_Content_2 = {
    Text = "Ja... Das hat der Ausschuss gesagt!"
  },
  AvgDialog_60202_Content_3 = {
    Text = "Das ist wahrscheinlich keine offizielle Ausschussaktion. Diese Frau, Clementine, muss andere Motive haben..."
  },
  AvgDialog_60202_Content_4 = {
    Text = "Wie ist die Lage jetzt? Wissen andere darüber Bescheid?"
  },
  AvgDialog_60202_Content_5 = {
    Text = "Sobald sie das Schultor betreten hatten, trennten sie sich... Diese Frau führte eine große Gruppe in Richtung des Lehrgebäudes."
  },
  AvgDialog_60202_Content_6 = {
    Text = "Ich habe den Lehrern und Klassenkameraden, die ich unterwegs getroffen habe, von der Situation erzählt. Mehrere Erwachte sind bereits auf dem Weg..."
  },
  AvgDialog_60202_Content_7 = {
    Text = "Ah, Hüter!"
  },
  AvgDialog_60202_Content_8 = {
    Text = "Am Ende des Flurs spähen mehrere Mitglieder des Ausschusses mit Suchhaustieren in die nahegelegenen Klassenräume."
  },
  AvgDialog_60202_Content_9 = {
    Text = "Du beschleunigtest dein Tempo und zogst den Silberschlüssel heraus"
  },
  AvgDialog_60203_Content_1 = {
    Text = "Mythags herausragende Schüler sollten nicht von denen lernen, die mit öffentlichen Pflichten in Konflikt stehen."
  },
  AvgDialog_60203_Content_10 = {
    Text = "Wenn sich die Gelegenheit bietet, würde ich gerne ein gutes Gespräch mit dir führen. Aber nicht heute."
  },
  AvgDialog_60203_Content_11 = {
    Text = "Lass uns zur Arbeit kommen."
  },
  AvgDialog_60203_Content_12 = {Text = "Ja."},
  AvgDialog_60203_Content_13 = {
    Text = "Er machte eine Geste."
  },
  AvgDialog_60203_Content_14 = {
    Text = "Die Agenten drängten sich vor und zogen den Ring enger."
  },
  AvgDialog_60203_Content_15 = {
    Text = "Die Erwecker kämpften mit aller Kraft gegen die überwältigende Schläfrigkeit; die Klingen an den Kehlen der Schüler hielten sie davon ab, irgendwelche unüberlegten Bewegungen zu machen."
  },
  AvgDialog_60203_Content_16 = {
    Text = "„Leg los.“"
  },
  AvgDialog_60203_Content_17 = {
    Text = "Die Waffen des Ausschusses waren auf den Erwacher in der Mitte gerichtet, Finger an den Abzügen."
  },
  AvgDialog_60203_Content_18 = {
    Text = "Aktiviere den Silberschlüssel"
  },
  AvgDialog_60203_Content_19 = {Text = "Ding—"},
  AvgDialog_60203_Content_2 = {
    Text = "Die Landschaft im Gefängnis ist nicht so verlockend wie die auf dem Campus."
  },
  AvgDialog_60203_Content_20 = {
    Text = "Übertreten!"
  },
  AvgDialog_60203_Content_21 = {
    Text = "Mit einem Blitz intensiven silbernen Lichts brachen unzählige Tentakel aus dem Boden hervor und schleuderten die Agenten zu Boden, die die Mythag-Schüler festhielten."
  },
  AvgDialog_60203_Content_22 = {
    Text = "Du bist endlich angekommen."
  },
  AvgDialog_60203_Content_23 = {
    Text = "Du erinnerst dich an sie. Die Psychologin im Armenhaus, die dich mühelos machtlos zurückließ."
  },
  AvgDialog_60203_Content_24 = {
    Text = "Du beobachtest vorsichtig das hypnotisierende Werkzeug in ihrer Hand."
  },
  AvgDialog_60203_Content_25 = {
    Text = "Hallo wieder, Miss Clementine."
  },
  AvgDialog_60203_Content_26 = {
    Text = "Hüter! Tulu!"
  },
  AvgDialog_60203_Content_27 = {
    Text = "Bist du verletzt?"
  },
  AvgDialog_60203_Content_28 = {
    Text = "Eine kleine Angelegenheit, nichts Signifikantes!"
  },
  AvgDialog_60203_Content_29 = {
    Text = "Viele Menschen strömten in die Schule, und Lily konnte sie nicht aufhalten..."
  },
  AvgDialog_60203_Content_3 = {
    Text = "Du... Frau! Kein einziges ehrliches Wort aus deinem Mund! Alle, hört nicht auf sie!"
  },
  AvgDialog_60203_Content_30 = {
    Text = "Jenkin wischte sich das Blut von seinem Gesicht und senkte den Kopf."
  },
  AvgDialog_60203_Content_31 = {
    Text = "Du klopfst sanft ihren Köpfen."
  },
  AvgDialog_60203_Content_32 = {
    Text = "Das Licht des silbernen Schlüssels leuchtet und füllt den Körper des Erweckers stetig mit geistiger Energie durch den silbernen Schlüssel in dir."
  },
  AvgDialog_60203_Content_33 = {
    Text = "Du hast großartige Arbeit geleistet. Ich werde die nächsten Schritte zusammen mit dir abschließen."
  },
  AvgDialog_60203_Content_34 = {
    Text = "Du blickst zu Clementine und den zahlreichen Ausschuss-Agenten um sie herum auf."
  },
  AvgDialog_60203_Content_35 = {
    Text = "Hüter {Male=Herr,Female=Frau}, du bist kein Kind mehr, denk darüber nach. Wir sind offizielle Ermittler, durchsuchen Misaq, das ist ein offizieller Befehl."
  },
  AvgDialog_60203_Content_36 = {
    Text = "Ohne Erlaubnis in Mythag einzutreten, das Volk zu schädigen... Ich sah keine Beamten, nur eine Gruppe von Banditen."
  },
  AvgDialog_60203_Content_37 = {
    Text = "Es ist mir egal, was deine wahren Absichten sind. Gegenüber Räubern hat Mythag nur eine Haltung."
  },
  AvgDialog_60203_Content_38 = {
    Text = "Beginne Counter"
  },
  AvgDialog_60203_Content_39 = {
    Text = "Erwecker, formiert euch und stellt euch dem Feind!"
  },
  AvgDialog_60203_Content_4 = {
    Text = "Mythag ist mein Zuhause, und ich lasse dich nicht hinein!"
  },
  AvgDialog_60203_Content_5 = {
    Text = "Lily wird diesen Ort beschützen!"
  },
  AvgDialog_60203_Content_6 = {
    Text = "Trotz deiner eingeschränkten Bewegungsfreiheit gelingt es dir, so berührend zu sprechen. Wahrlich bedauernswert."
  },
  AvgDialog_60203_Content_7 = {
    Text = "Sie warf einen Blick auf die verwundeten Erwachen-Kinder sowie auf die von den Ausschuss-Agenten kontrollierten Studenten und Forscher."
  },
  AvgDialog_60203_Content_8 = {
    Text = "Aber bei so vielen gewöhnlichen Menschen in Mythag, was können ein paar Kinder wie du überhaupt erreichen?"
  },
  AvgDialog_60203_Content_9 = {
    Text = "„Du! Verwerflich... Schamlos!“"
  },
  AvgDialog_60208_Content_1 = {Text = "Dirigent"},
  AvgDialog_60208_Content_10 = {
    Text = "Mythags Hüter... Ich verstehe endlich, warum die Bildhauer und die Laterne so an deiner Fähigkeit interessiert sind, Erwecker zu verbinden."
  },
  AvgDialog_60208_Content_11 = {
    Text = "Wir haben uns kurz im Armenhaus getroffen, aber hatten keine Gelegenheit, tiefgehende Gespräche zu führen. Wie schade."
  },
  AvgDialog_60208_Content_12 = {
    Text = "Jedoch ist es lange genug her... es sollte bald bereit sein."
  },
  AvgDialog_60208_Content_13 = {
    Text = "\"Clementine klopfte sich leicht den Staub ab, schaute an dir vorbei und blickte in die Tiefen von Mythag.\""
  },
  AvgDialog_60208_Content_14 = {
    Text = "Sie betrachtete ihre Taschenuhr, ein schwaches Lächeln umspielte die Ecken ihrer Lippen."
  },
  AvgDialog_60208_Content_15 = {
    Text = "Die Zeit ist um."
  },
  AvgDialog_60208_Content_17 = {Text = "Ah!—"},
  AvgDialog_60208_Content_18 = {Text = "Ugh..."},
  AvgDialog_60208_Content_19 = {
    Text = "Es fühlte sich an, als ob eine mächtige Explosion in deinen Gedanken stattgefunden hätte."
  },
  AvgDialog_60208_Content_2 = {
    Text = "Brown, komm her!"
  },
  AvgDialog_60208_Content_20 = {
    Text = "\"Die Erwachenden, die gerade eben voller Energie waren, schienen einen schweren Schlag erlitten zu haben und fielen auf die Knie.\""
  },
  AvgDialog_60208_Content_21 = {
    Text = "Ein scharfer Schmerz trifft dich, und du stabilisierst dich instinktiv, indem du dich an dem nahen Sitz festhältst, um einen Sturz zu vermeiden."
  },
  AvgDialog_60208_Content_22 = {
    Text = "Jenkin! Tulu! Geht's euch gut?"
  },
  AvgDialog_60208_Content_23 = {
    Text = "Ich werde dir helfen—"
  },
  AvgDialog_60208_Content_24 = {
    Text = "Du versuchst, deine Geisterenergie zu ihnen zu übertragen."
  },
  AvgDialog_60208_Content_25 = {Text = "!!!"},
  AvgDialog_60208_Content_26 = {Text = "Das ist..."},
  AvgDialog_60208_Content_27 = {
    Text = "In der Geisterdimension begannen die ursprünglich vertrauten Figuren plötzlich zu verschwommen."
  },
  AvgDialog_60208_Content_28 = {
    Text = "Die einst fest verbundenen Verbindungen scheinen jetzt von etwas blockiert zu sein. Die Verbindung zwischen dir und den Schatten ist ungewöhnlich vage geworden."
  },
  AvgDialog_60208_Content_29 = {
    Text = "Meine Verbindung zu den Erwachenden... hat nachgelassen?"
  },
  AvgDialog_60208_Content_3 = {Text = "Squeak!"},
  AvgDialog_60208_Content_30 = {
    Text = "Nein... Sie können doch nicht so eine Macht haben..."
  },
  AvgDialog_60208_Content_31 = {
    Text = "Deine Pupillen erweitern sich plötzlich, als du an etwas denkst."
  },
  AvgDialog_60208_Content_32 = {
    Text = "Du schaust auf und starrst schockiert auf Clementine. Ein Schweißtropfen fällt von deiner Stirn."
  },
  AvgDialog_60208_Content_33 = {
    Text = "Es ist der Schwarze Pool... Irgendetwas ist damit schiefgelaufen!"
  },
  AvgDialog_60208_Content_34 = {
    Text = "Ein so grandioses Spektakel, um unsere Aufmerksamkeit hierher zu ziehen... Der wahre Zweck liegt im Schwarzen Pool...!"
  },
  AvgDialog_60208_Content_35 = {
    Text = "Ja, der Schwarze Pool."
  },
  AvgDialog_60208_Content_36 = {
    Text = "Die Anomalien in der Geisterwelt und die intensiven Erdstöße stehen wahrscheinlich im Zusammenhang mit D-Rissen und Katastrophen"
  },
  AvgDialog_60208_Content_37 = {
    Text = "Der schwarze Pool, der früheste und großartigste D-Riss der Welt. Er ist sowohl die Quelle der Silberkraft als auch die größte Bedrohung für sie."
  },
  AvgDialog_60208_Content_38 = {
    Text = "Dein Verstand ist ebenfalls bewundernswert, Wächter{Male=Herr,Female=Frau}"
  },
  AvgDialog_60208_Content_39 = {
    Text = "\"Almost infinite link count, enviable spirit power...\"  -> \"Fast unendliche Verknüpfungsanzahl, beneidenswerte Geisterkraft...\""
  },
  AvgDialog_60208_Content_4 = {
    Text = "Ich werde diejenigen bestrafen, die meinen Frieden stören."
  },
  AvgDialog_60208_Content_40 = {
    Text = "Du bist tatsächlich stark. Aber ohne diese Macht, was kannst du tun?"
  },
  AvgDialog_60208_Content_41 = {
    Text = "Großer{Male=Herr Schutzherr,Female=Frau Schutzherrin}, pass auf!"
  },
  AvgDialog_60208_Content_42 = {
    Text = "Eine schwarze Kugel mit Stacheln kommt vor dir und stößt einen sich nähernden Ausschuss-Agenten zur Seite."
  },
  AvgDialog_60208_Content_43 = {
    Text = "Die schwarze Kugel versucht einen weiteren Angriff, zerbricht jedoch nach kurzer Bewegung."
  },
  AvgDialog_60208_Content_44 = {
    Text = "Lily kann nicht mehr durchhalten, ihr kleiner Körper zittert vor Schmerz."
  },
  AvgDialog_60208_Content_45 = {
    Text = "Du scannst die Umgebung. Jenkin, Tulu, Lily... Anzeichen erster Instabilität haben unter den Erwachten aufgrund geschwächter Verbindungen begonnen zu erscheinen."
  },
  AvgDialog_60208_Content_46 = {
    Text = "Nein, wir müssen einen Weg finden..."
  },
  AvgDialog_60208_Content_47 = {
    Text = "Ich habe eine Idee... Braun!"
  },
  AvgDialog_60208_Content_48 = {Text = "Squeak!"},
  AvgDialog_60208_Content_49 = {
    Text = "Squeak—Squeak—"
  },
  AvgDialog_60208_Content_5 = {
    Text = "Mehrere riesige Tentakel schwingen und werfen einige Agenten um, die versuchen, sich heranzuschleichen."
  },
  AvgDialog_60208_Content_50 = {
    Text = "Ist es... ist es eine Ratte?!"
  },
  AvgDialog_60208_Content_51 = {
    Text = "Zahlreiche durchdringende Schreie von Ratten hallten wider."
  },
  AvgDialog_60208_Content_52 = {
    Text = "Korridore, Abwasserkanäle, Büsche... Unzählige Ratten strömten aus allen Richtungen und bedeckten den Spielplatz dicht."
  },
  AvgDialog_60208_Content_53 = {
    Text = "Braun führt den Schwarm von Mäusen direkt zu den Agenten des Ausschusses."
  },
  AvgDialog_60208_Content_54 = {
    Text = "Hüter, jetzt ist die Gelegenheit!"
  },
  AvgDialog_60208_Content_55 = {
    Text = "Meine Augen! Meine Augen!"
  },
  AvgDialog_60208_Content_56 = {
    Text = "Geh weg! Geh weg!"
  },
  AvgDialog_60208_Content_57 = {
    Text = "Eine Flut von Mäusen ergoss sich über das Feld, verschlang die Menge und Braun."
  },
  AvgDialog_60208_Content_58 = {
    Text = "Die Mäuse kämpften furchtlos. Die Mäuse wurden leicht besiegt. Die Flut der Mäuse zog sich zurück und hinterließ einen Boden, der mit toten Mäusen bedeckt war."
  },
  AvgDialog_60208_Content_59 = {
    Text = "Clementines Blick durchfegt das Chaos, findet dich oder die Erwachten nicht mehr."
  },
  AvgDialog_60208_Content_6 = {
    Text = "Auf Mythags Platz fielen die Ausschussagenten wie verdorrtes Gras."
  },
  AvgDialog_60208_Content_7 = {
    Text = "Die verbleibenden Agenten umringten dich, wagten aber nicht, einen Schritt zu machen."
  },
  AvgDialog_60208_Content_8 = {
    Text = "Gib auf, Clementine. Befiehl deinen Agenten, sich zurückzuziehen und Mythags Lehrer und Schüler nicht weiter zu stören."
  },
  AvgDialog_60208_Content_9 = {
    Text = "Die Schule wird dir eine angemessene Lösung anbieten."
  },
  AvgDialog_60209_Content_1 = {
    Text = "Schuldekrets"
  },
  AvgDialog_60209_Content_10 = {
    Text = "Husten... Husten, Husten..."
  },
  AvgDialog_60209_Content_11 = {Text = "Lehrerin!"},
  AvgDialog_60209_Content_12 = {
    Text = "Dein Rollstuhl zittert. Du hältst Alistair steady."
  },
  AvgDialog_60209_Content_13 = {
    Text = "Ein einfacher Satz schien seinen Geist erschöpft zu haben, wodurch sein ohnehin schwacher Körper noch schwächer wurde."
  },
  AvgDialog_60209_Content_14 = {
    Text = "Lehrer, wie weißt du diese Dinge...?"
  },
  AvgDialog_60209_Content_15 = {
    Text = "Alistair rollt seinen Rollstuhl zum Fenster. Du folgst seinem Blick und schaust gemeinsam auf das Licht im Schwarzen Pool."
  },
  AvgDialog_60209_Content_16 = {
    Text = "Der Intellektuelle Körper hat Tawil eine Menge Wissen vermittelt. Keines dieser Kenntnisse wurde schriftlich festgehalten, da allein die Dokumentation endlose Katastrophen heraufbeschwören würde."
  },
  AvgDialog_60209_Content_17 = {
    Text = "Im Schwarzen Teich bleibt eine schlafende Muschel zurück. Ihr Bewusstsein ist nicht hier oder vielmehr nicht in dieser Dimension, zu dieser Zeit..."
  },
  AvgDialog_60209_Content_18 = {
    Text = "Als Er wach war, vermittelte Er dieses Wissen... husten, husten... an mich."
  },
  AvgDialog_60209_Content_19 = {
    Text = "Tawil ist nicht in dieser Dimension... Versteckt er sich vor etwas?"
  },
  AvgDialog_60209_Content_2 = {
    Text = "Katastrophe aus einer anderen Welt? Lehrer, ich verstehe das nicht ganz..."
  },
  AvgDialog_60209_Content_20 = {
    Text = "Thais hat mir auch gesagt, dass sie vor einer \"ultimativen Krise\" fliehen."
  },
  AvgDialog_60209_Content_21 = {
    Text = "Ist die Katastrophe mit dem Höchsten Wesen verbunden?"
  },
  AvgDialog_60209_Content_22 = {
    Text = "Könnte etwas, das die Agenten beider Essenzen in Angst versetzt, die Katastrophe sein, die du erwähnt hast und die aus einer anderen Welt stammt?"
  },
  AvgDialog_60209_Content_23 = {
    Text = "Hat dieses Unheil mit dem höchsten Wesen zu tun?"
  },
  AvgDialog_60209_Content_24 = {
    Text = "Alistair sah dich zustimmend an, lächelte und nickte."
  },
  AvgDialog_60209_Content_25 = {
    Text = "Du bist scharfsinnig, %player%. Das ist gut."
  },
  AvgDialog_60209_Content_26 = {
    Text = "Scharfheit ist eine kostbare Eigenschaft eines Hüters."
  },
  AvgDialog_60209_Content_27 = {
    Text = "Du hast recht. Sie haben Angst."
  },
  AvgDialog_60209_Content_28 = {
    Text = "Alistair richtet sich auf, sein Ausdruck wird ernst."
  },
  AvgDialog_60209_Content_29 = {
    Text = "Dieses höchste Wesen, Tawil nennt ihn den höchsten Willen..."
  },
  AvgDialog_60209_Content_3 = {
    Text = "Du schaust auf die Überreste des Mutterbaums auf dem Tisch. Seit deiner Rückkehr aus der Wüste liegt er wie eine hässliche Parabel auf Alistairs Tisch."
  },
  AvgDialog_60209_Content_30 = {
    Text = "Er ist der alleinige Herrscher unzähliger Universen. Die drei Essenzen wurden aus ihm geboren. Er kreiert, kontrolliert und bringt Zerstörung über alles."
  },
  AvgDialog_60209_Content_31 = {
    Text = "Er ist die Quelle aller Katastrophen."
  },
  AvgDialog_60209_Content_32 = {
    Text = "Alle Quellen der Katastrophen... Du meinst...!"
  },
  AvgDialog_60209_Content_33 = {
    Text = "Ja. Das, was wir immer verstehen und besiegen wollten - Auflösung."
  },
  AvgDialog_60209_Content_34 = {
    Text = "Was ist die Beziehung zwischen der Auflösung und dem höchsten Willen?"
  },
  AvgDialog_60209_Content_35 = {
    Text = "Tawil hat mich nicht informiert. Vielleicht hat der Intellektuelle Körper etwas vor Ihm verborgen."
  },
  AvgDialog_60209_Content_36 = {
    Text = "Wir haben eine Vermutung, dass der Höchste Wille in Verbindung mit..."
  },
  AvgDialog_60209_Content_37 = {
    Text = "Alistair starrt dich an. Plötzlich zieht er die Stirn tief zusammen."
  },
  AvgDialog_60209_Content_38 = {Text = "Lehrerin?"},
  AvgDialog_60209_Content_39 = {
    Text = "Eine starke Vorahnung, wie am Tag der Explosion von Akut. Ein überwältigendes Gefühl der nahenden Gefahr..."
  },
  AvgDialog_60209_Content_4 = {
    Text = "Alistair schweigt lange. Er blickt auf den leeren Schwarzen Pool, in seinem Geist scheinen widersprüchliche Gedanken zu kämpfen."
  },
  AvgDialog_60209_Content_40 = {
    Text = "Mach dich bereit, %player%. Bald könnte etwas Bedeutendes passieren."
  },
  AvgDialog_60209_Content_41 = {
    Text = "Etwas Unvorstellbares, das Angst und Qual zu allen bringt..."
  },
  AvgDialog_60209_Content_42 = {
    Text = "Klopf klopf klopf—"
  },
  AvgDialog_60209_Content_43 = {
    Text = "Bevor Alistair seinen Satz beenden konnte, war dringendes Klopfen von draußen im unterirdischen Forschungsraum zu hören."
  },
  AvgDialog_60209_Content_44 = {
    Text = "Alistair runzelt nachdenklich die Stirn. Du öffnest die Tür, verwirrt."
  },
  AvgDialog_60209_Content_45 = {
    Text = "\"E-etwas ist passiert!\""
  },
  AvgDialog_60209_Content_46 = {
    Text = "Hanna? Wie sind Sie an diesen Ort geraten?"
  },
  AvgDialog_60209_Content_47 = {
    Text = "Dieser Ort ist in der Nähe des Schwarzen Teichs, sehr gefährlich. Nur diejenigen mit speziellen Pässen können..."
  },
  AvgDialog_60209_Content_48 = {
    Text = "Bevor du deinen Satz zu Ende sprichst, packt Hanna dich und läuft in Richtung des unterirdischen Forschungslabors."
  },
  AvgDialog_60209_Content_49 = {
    Text = "Hey! Hanna, was ist los..."
  },
  AvgDialog_60209_Content_5 = {
    Text = "Du hast mit den Gesandten der drei Hauptwesen interagiert. Ich glaube, es ist Zeit, dir ein paar Dinge zu erzählen."
  },
  AvgDialog_60209_Content_50 = {
    Text = "Ausschuss... Der Ausschuss hat die Schule überfallen!"
  },
  AvgDialog_60209_Content_51 = {Text = "!!!"},
  AvgDialog_60209_Content_6 = {
    Text = "Als du Alistairs Augen gesehen hast, bist du geschickt nähergegangen, hast seinen Rollstuhl stabilisiert und ihn zum Tisch gefahren."
  },
  AvgDialog_60209_Content_7 = {
    Text = "Wie viel weißt du über das Tri-Entity?"
  },
  AvgDialog_60209_Content_8 = {
    Text = "Zahlreich. Ich weiß, dass sie jeweils Intellekt, Verlangen und Genuss regieren, unvorstellbare Macht besitzen - die stärksten Götter im Universum..."
  },
  AvgDialog_60209_Content_9 = {
    Text = "Nein, %player%, über den drei Attributen gibt es ein noch höheres..."
  },
  AvgDialog_60210_Content_1 = {Text = "Überreste"},
  AvgDialog_60210_Content_10 = {
    Text = "Aber es gibt jemanden, der deinen Schutz mehr braucht als ich, sowohl in Bezug auf den Wert als Geisel als auch auf die Unannehmlichkeiten in der Bewegung."
  },
  AvgDialog_60210_Content_100 = {
    Text = "Es wird sie alarmieren! Stoppe es!"
  },
  AvgDialog_60210_Content_11 = {
    Text = "Ich verstehe, Dean. Sobald du in der sicheren Zone bist, werde ich sofort Professor Alistair aufsuchen."
  },
  AvgDialog_60210_Content_12 = {
    Text = "Alle drei wandten ihren Blick zurück auf den geheimnisvollen und gefährlichen Riss—ein dunkles Maul, das droht, alles in Mythag zu verschlingen."
  },
  AvgDialog_60210_Content_13 = {
    Text = "Ich hoffe, Alistair ist wohlauf und sicher..."
  },
  AvgDialog_60210_Content_14 = {
    Text = "Schwarzer Tee wurde heute Morgen aufgegossen. Möchtest du etwas?"
  },
  AvgDialog_60210_Content_15 = {
    Text = "Für diejenigen ohne Gliedmaßen fügt jede Aufnahme über das hinaus, was notwendig ist, um das Leben zu erhalten, nur Unannehmlichkeiten hinzu."
  },
  AvgDialog_60210_Content_16 = {
    Text = "Ich möchte mich nicht stören, noch möchte ich andere stören. Bitte, fahren Sie fort, Professor Doll."
  },
  AvgDialog_60210_Content_17 = {
    Text = "Doll blies auf ihre Teetasse und nahm einen sanften Schluck."
  },
  AvgDialog_60210_Content_18 = {
    Text = "Das Wasser des schwarzen Pools dringt in das unterirdische Forschungslabor ein, gefährlich unter ihren Füßen wie eine bizarre Hintergrundmusik zu einer Teeparty."
  },
  AvgDialog_60210_Content_19 = {
    Text = "Eifersüchtig? Dieser Körper hat sogar Duftsensoren, genug, um das Gefühl von warmem schwarzem Tee zu genießen, der auf der Zunge tanzt."
  },
  AvgDialog_60210_Content_2 = {
    Text = "Ramona spähte vorsichtig hinaus und durchsuchte gründlich den Fluchtweg."
  },
  AvgDialog_60210_Content_20 = {
    Text = "Statt eifersüchtig auf deinen Genuss des duftenden schwarzen Tees zu sein, beneide ich die Bequemlichkeit, mit der du zu anderen künstlichen Körpern überwechseln kannst."
  },
  AvgDialog_60210_Content_21 = {
    Text = "Leider kann ein künstlicher Körper deine spirituelle Macht nicht tragen. Um die Überlegenheit außergewöhnlichen Talents zu genießen, musst du den entsprechenden Preis zahlen."
  },
  AvgDialog_60210_Content_22 = {
    Text = "Doll stellte ihre Teetasse ab und sah Alistair an."
  },
  AvgDialog_60210_Content_23 = {
    Text = "Professor Alistair, kannst du fühlen, wer es ist?"
  },
  AvgDialog_60210_Content_24 = {
    Text = "Sprichst du von dem Maulwurf innerhalb von Mythag?"
  },
  AvgDialog_60210_Content_25 = {
    Text = "In der Tat. Der Nebel, der Mythag umgibt, wurde von den Gründern und Tawil erschaffen. Der Standort von Black Pool ist ebenfalls ein Geheimnis, das über gewöhnliches Wissen hinausgeht."
  },
  AvgDialog_60210_Content_26 = {
    Text = "Den Nebel beseitigen und den schwarzen Pool zur Explosion bringen – nur eine Handvoll Menschen kann solche Taten vollbringen."
  },
  AvgDialog_60210_Content_27 = {
    Text = "Ich habe es auf ein paar Personen eingegrenzt. Aber mit den derzeit verfügbaren Informationen ist eine weitere Eingrenzung schwierig."
  },
  AvgDialog_60210_Content_28 = {
    Text = "Bin ich einer der Zielpersonen?"
  },
  AvgDialog_60210_Content_29 = {
    Text = "Alistair neigte leicht den Kopf, ein mehrdeutiges Licht flackerte in seinen Augen."
  },
  AvgDialog_60210_Content_3 = {
    Text = "Es gibt keine Ausschussmitglieder hier. Geh diesen Weg."
  },
  AvgDialog_60210_Content_30 = {
    Text = "Du bist der Erste."
  },
  AvgDialog_60210_Content_31 = {
    Text = "Doll nahm einen Schluck schwarzen Tee, der wirbelnde Nebel verbarg ihren Ausdruck und fror die Atmosphäre im Forschungslabor ein."
  },
  AvgDialog_60210_Content_32 = {
    Text = "Es wurde bereits ausgeschlossen."
  },
  AvgDialog_60210_Content_33 = {
    Text = "Es wird nicht du sein. Du bist der \"Kern\" von Mythag, und es gibt viele Wege, Mythag zu zerstören, ohne so viel Mühe auf sich zu nehmen."
  },
  AvgDialog_60210_Content_34 = {
    Text = "In diesem Tumult spielt der Maulwurf die gefährlichste Rolle"
  },
  AvgDialog_60210_Content_35 = {
    Text = "Meine Fähigkeit eignet sich nicht für den Kampf an der Front.\nDen Maulwurf zu finden, ist meine Mission. Ich brauche Ihre Hilfe."
  },
  AvgDialog_60210_Content_36 = {
    Text = "Entschuldigung, Professor Doll. Ich habe nicht das geringste Gefühl für diesen Maulwurf-Freund."
  },
  AvgDialog_60210_Content_37 = {
    Text = "Das sollte nicht möglich sein. Theoretisch sollte jede Vibration jedes Silbers innerhalb von Mythag in deinem Einflussbereich liegen."
  },
  AvgDialog_60210_Content_38 = {
    Text = "In der Tat.\nEr ist über mein Wahrnehmungsvermögen hinaus."
  },
  AvgDialog_60210_Content_39 = {
    Text = "Das bedeutet, dass er die Fähigkeit hat, deiner Wahrnehmung zu entkommen?"
  },
  AvgDialog_60210_Content_4 = {
    Text = "Sie drehte sich um und stützte Czorts Arm."
  },
  AvgDialog_60210_Content_40 = {
    Text = "Es gibt auch andere Möglichkeiten."
  },
  AvgDialog_60210_Content_41 = {
    Text = "Doll schwieg einen Moment, als würde sie etwas in Erinnerung rufen."
  },
  AvgDialog_60210_Content_42 = {
    Text = "Ich verstehe. Das ist eine neue Richtung, die man in Betracht ziehen sollte."
  },
  AvgDialog_60210_Content_43 = {
    Text = "Alistair nickte, schloss die Augen und atmete zufrieden den Duft des Tees ein, wobei er ein zufriedenes Seufzen ausstieß."
  },
  AvgDialog_60210_Content_44 = {
    Text = "Du scheinst ziemlich entspannt zu sein. Gerade macht sich wahrscheinlich das gesamte Mythag Sorgen um dich."
  },
  AvgDialog_60210_Content_45 = {
    Text = "Ich bin die letzte Person, um die sich jemand Sorgen machen müsste."
  },
  AvgDialog_60210_Content_46 = {
    Text = "Doll sah Alistair an, ein Hauch von Zögerlichkeit durchbrach ihre ruhige Fassade."
  },
  AvgDialog_60210_Content_47 = {
    Text = "Ich sehe keinen Anzeichen von Unbehagen in Ihrem Gesicht. Ihr Wille ist wirklich bewundernswert."
  },
  AvgDialog_60210_Content_48 = {
    Text = "......Der Schmerz, den du jetzt erträgst, muss unvorstellbar sein, Professor Alistair, oder?"
  },
  AvgDialog_60210_Content_49 = {
    Text = "Ich... *hust*"
  },
  AvgDialog_60210_Content_5 = {
    Text = "Ramona, ich werde Dean Czort eskortieren. Der Schwarze Pool hat Probleme, und dir geht es nicht gut..."
  },
  AvgDialog_60210_Content_50 = {
    Text = "Alistair hustete heftig. Der Rollstuhl stieß gegen den Schreibtisch, und der Tee verschüttete sich aus der Tasse in den Schwarzen Pool und verschwand spurlos."
  },
  AvgDialog_60210_Content_51 = {
    Text = "Der schwarze Pool explodiert. Du bist am nächsten zu ihm und trägst die Hauptlast seines Aufpralls."
  },
  AvgDialog_60210_Content_52 = {
    Text = "Wenn du nicht gehst, wird dein Körper hier nicht standhalten können."
  },
  AvgDialog_60210_Content_53 = {
    Text = "Menschen, die für ihre Rationalität bekannt sind, sollten solche emotional aufgeladenen Dinge nicht sagen."
  },
  AvgDialog_60210_Content_54 = {
    Text = "Deine gespielte Unwissenheit klingt ziemlich steif, Professor Puppe."
  },
  AvgDialog_60210_Content_55 = {
    Text = "Alistair schüttelt mit einem Lächeln den Kopf."
  },
  AvgDialog_60210_Content_56 = {
    Text = "Wenn ich gehe, wird der Schwarze Pool außer Kontrolle geraten. Bis dahin wird nicht nur Mythag zerstört sein."
  },
  AvgDialog_60210_Content_57 = {
    Text = "Doll konnte deutlich Alistairs sanfte Stimme hören, die unkontrollierbar zu zittern begann, das unverkennbare Leid aus den Tiefen des Geistes offenbarend."
  },
  AvgDialog_60210_Content_58 = {
    Text = "\"Besorgnis muss ausgedrückt werden.\""
  },
  AvgDialog_60210_Content_59 = {
    Text = "Abgesehen von dieser nutzlosen Förmlichkeit kann ich mir keinen anderen Weg vorstellen, meinen Respekt für einen Menschen auszudrücken."
  },
  AvgDialog_60210_Content_6 = {
    Text = "Wenn der Ausschuss Czort Dean verletzen kann, können sie noch verrücktere Dinge tun."
  },
  AvgDialog_60210_Content_60 = {
    Text = "Es ist nicht einfach, solche Worte von dir zu hören. Es ist mir eine Ehre."
  },
  AvgDialog_60210_Content_61 = {
    Text = "Die Person, die mir helfen kann, ist wahrscheinlich auf dem Weg. Bitte mach dir keine Sorgen um mich."
  },
  AvgDialog_60210_Content_62 = {
    Text = [[
Es gibt andere Orte, die dich brauchen. Verlasse diesen Ort, Professor Puppe.
Ein alter Mann im Schwarzen Pool ist genug.]]
  },
  AvgDialog_60210_Content_63 = {
    Text = "Doll schloss die Augen und seufzte, sagte nichts mehr und verließ das unterirdische Forschungslabor."
  },
  AvgDialog_60210_Content_64 = {
    Text = "Hinter ihr sitzt der erste Hüter von Mythag in einem Rollstuhl und beobachtet ruhig das schwache Leuchten im Schwarzen Pool."
  },
  AvgDialog_60210_Content_65 = {
    Text = "Sein verbleibender Körper zitterte leicht, Schweiß und Blut drangen aus den Bandagen und tropften in den kochenden Pool zu seinen Füßen."
  },
  AvgDialog_60210_Content_66 = {
    Text = "In den unsichtbaren Tiefen des Geistes, in dieser illusorischen und gefährlichen Dimension, steht Alistair allein dem Schwarzen Becken gegenüber."
  },
  AvgDialog_60210_Content_68 = {
    Text = "Anführerin der Tempel-Licht-Kirche? Juliette?! Hissss—"
  },
  AvgDialog_60210_Content_69 = {
    Text = "Bleib ruhig. Je näher du dem Schwarzen Teich kommst, desto mehr Stress wird dein Geist ertragen müssen.\nWenn deine Emotionen zu stark schwanken, wird meine Musik deinen Schmerz nicht unterdrücken können."
  },
  AvgDialog_60210_Content_7 = {
    Text = "Ob ihr Ziel darin besteht, Geiseln zu entführen oder etwas anderes, du benötigst Menschen mit Kampffähigkeiten zur Eskorte."
  },
  AvgDialog_60210_Content_70 = {
    Text = "Die Bildhauer, Seefahrer... diese Leute..."
  },
  AvgDialog_60210_Content_71 = {
    Text = "Überrascht? Sie waren schon immer komplex miteinander verbunden."
  },
  AvgDialog_60210_Content_72 = {
    Text = "Sie sind durch eine Anomalie verbunden, die als Auflösung bekannt ist, und weben ein dichtes Netz rund um die Verbreitung der Schwarzen Pest in Kadath."
  },
  AvgDialog_60210_Content_73 = {
    Text = "Misaq strebt nach der Wahrheit der Auflösung und dem Fortbestand der Menschheit, im Wesentlichen sind sie Gegner der Auflösung und unversöhnliche Feinde der Laterne, die die Auflösung verbreiten will."
  },
  AvgDialog_60210_Content_74 = {
    Text = "Die Bildhauer zielen darauf ab, die Auflösung individuell zu überwinden und ignorieren alle Befehle der menschlichen Gesellschaft. Die von der Tempel-Licht-Kirche bereitgestellten Forschungmaterialien und -ressourcen übertreffen bei weitem andere – Herbert's Verrat steht wahrscheinlich damit in Zusammenhang."
  },
  AvgDialog_60210_Content_75 = {
    Text = "Was die Seefahrer betrifft, sie sind lediglich Narren, deren Geister in der alten Ära gefangen bleiben."
  },
  AvgDialog_60210_Content_76 = {
    Text = "Verlangen ist eine Schwäche. Mit Juliettes Finesse ist es ein müheloses Unterfangen, diese Menschen zu manipulieren."
  },
  AvgDialog_60210_Content_77 = {
    Text = "Du weißt viel zu viel."
  },
  AvgDialog_60210_Content_78 = {
    Text = "Es ist nicht surprising. Du hattest einfach noch nicht die \"Berechtigungen\" erhalten."
  },
  AvgDialog_60210_Content_79 = {
    Text = "Diese Informationen, abgesehen von Juliette's recentem Aufstieg, sind nichts weiter als banaler Gesprächsstoff für legere Unterhaltungen."
  },
  AvgDialog_60210_Content_8 = {
    Text = "Mach dir keine Sorgen, Professor Sylvia. Ich bin mir nicht sicher warum, aber die Schwankungen des Schwarzen Pools haben meine Kampfkräfte nicht beeinträchtigt."
  },
  AvgDialog_60210_Content_80 = {
    Text = "Hätte nie gedacht, dass sie all das inszeniert hat... Also sind der Ausschuss und der Maulwurf innerhalb von Mythag beide mit der Tempel Licht Kirche verbunden?"
  },
  AvgDialog_60210_Content_81 = {
    Text = "Hameln nickte sanft, mit weißen Handschuhen und einem Taktstock hinter sich, wie eine Klinge, die bereit ist, jeden Moment einen tödlichen Schlag auszuführen."
  },
  AvgDialog_60210_Content_82 = {
    Text = "Ein hochrangiges Mitglied des Ausschusses ist Juliettes Bauer. Die meisten Machtmittel, die er mobilisieren kann, konzentrieren sich jetzt auf Mythag."
  },
  AvgDialog_60210_Content_83 = {
    Text = "Weißt du, wer der Insider in Mythag ist?"
  },
  AvgDialog_60210_Content_84 = {
    Text = "Juliette hielt eine direkte Verbindung zu ihm aufrecht. Abgesehen von ihnen wusste sonst niemand, wer sie wirklich waren."
  },
  AvgDialog_60210_Content_85 = {
    Text = "Selbst du weißt es nicht. Es scheint, dass das Finden dieses Maulwurfs eine mühsame Aufgabe sein wird..."
  },
  AvgDialog_60210_Content_86 = {
    Text = "Was ist ihr wahres Ziel?"
  },
  AvgDialog_60210_Content_87 = {
    Text = "Was ist Juliette's wahres Ziel, so grandios in Mythag aufzutreten?"
  },
  AvgDialog_60210_Content_88 = {
    Text = "Was weißt du über das Zwillingsprojekt der Tempel-Licht-Kirche?"
  },
  AvgDialog_60210_Content_89 = {
    Text = "Hameln antwortete nicht direkt auf deine Frage, sondern stellte stattdessen eine eigene Frage."
  },
  AvgDialog_60210_Content_9 = {
    Text = "Ihre Logik ist einwandfrei, Ramona."
  },
  AvgDialog_60210_Content_90 = {
    Text = "Sein strenger Blick durchbohrt dich wie eine Klinge; du runzelst die Stirn und kämpfst darum, dich zu erinnern."
  },
  AvgDialog_60210_Content_91 = {
    Text = "Ich gewann einige Einblicke, als ich zuvor mit Lily und Helot interagierte."
  },
  AvgDialog_60210_Content_92 = {
    Text = "Sie bezeichneten die beiden homologen Erwachten als \"Laternenzwillinge\", vielleicht in der Hoffnung, etwas auf diese Weise heraufzubeschwören..."
  },
  AvgDialog_60210_Content_93 = {
    Text = "Die Tempel-Licht-Kirche glaubt, dass die Fusion von zwei Erweckern ein Gefäß schafft, das das Göttliche tragen kann."
  },
  AvgDialog_60210_Content_94 = {
    Text = "Sie zielen darauf ab, auf diese Weise einen Gott zu erschaffen."
  },
  AvgDialog_60210_Content_95 = {
    Text = "\"Götter erschaffen... Aber was hat das mit Mythag zu tun?\""
  },
  AvgDialog_60210_Content_96 = {Text = "Weil..."},
  AvgDialog_60210_Content_97 = {
    Text = "Hameln blieb abrupt stehen, sein scharfer Blick fixierte einen Grabstein dahinter."
  },
  AvgDialog_60210_Content_98 = {
    Text = "Hinter dem blaugrauen schlüsselförmigen Tablet sind leise Raschelgeräusche zu hören."
  },
  AvgDialog_60210_Content_99 = {
    Text = "Es ist Juliette's anthropomorpher Hund. Meine Hilfe für dich muss Juliette unbekannt bleiben."
  },
  AvgDialog_60212_Content_1 = {Text = "Probe"},
  AvgDialog_60212_Content_10 = {
    Text = "Ich habe nicht erwartet, dass Mythag und der Ausschuss Interesse an mir zeigen."
  },
  AvgDialog_60212_Content_11 = {
    Text = "Von unserer Untersuchung her stimmt deine Rundreise eng mit der Aktivitätskurve der Kirche des Tempellichts überein."
  },
  AvgDialog_60212_Content_12 = {
    Text = "Du beobachtest vorsichtig den Erwecker vor dir."
  },
  AvgDialog_60212_Content_13 = {
    Text = "Du hast mich und die Erwecker gerettet, dafür bin ich sehr dankbar. Aber jetzt ist Misaq in Gefahr, ich hoffe, du verstehst meine Vorsicht."
  },
  AvgDialog_60212_Content_14 = {
    Text = "Auf dem Weg fragte ich dich, wie du nach Mythag gekommen bist und was dein Zweck war, hierher zu kommen. Jetzt kannst du mir antworten."
  },
  AvgDialog_60212_Content_15 = {
    Text = "Ist Ihr Erwachender in Ordnung?"
  },
  AvgDialog_60212_Content_16 = {
    Text = "...Ich habe die meisten Erwecker in die Nähe des Schwarzen Teichs geschickt. Nur wenige sind noch an meiner Seite."
  },
  AvgDialog_60212_Content_17 = {
    Text = "Wie läuft die Link-Wiederherstellung?"
  },
  AvgDialog_60212_Content_18 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_60212_Content_19 = {
    Text = "Mit der Hilfe deiner Musik wurde meine Verbindung zu diesen Erwachten wiederhergestellt."
  },
  AvgDialog_60212_Content_2 = {
    Text = "\"Wir sind hier.\""
  },
  AvgDialog_60212_Content_20 = {
    Text = "Deine Situation ist einzigartig. Ich kann nur eine minimale Verbindung zum Erwachter aufrechterhalten. Das sollte ausreichen."
  },
  AvgDialog_60212_Content_21 = {
    Text = "Er hob den Taktstock sanft an."
  },
  AvgDialog_60212_Content_22 = {
    Text = "Greif mich jetzt an."
  },
  AvgDialog_60212_Content_23 = {Text = "???"},
  AvgDialog_60212_Content_24 = {
    Text = "Was hast du gesagt?"
  },
  AvgDialog_60212_Content_25 = {
    Text = "Meine Leo-Sprachausprache sollte in Ordnung sein."
  },
  AvgDialog_60212_Content_26 = {
    Text = "Ich habe dich gehört, ich meine..."
  },
  AvgDialog_60212_Content_27 = {
    Text = "Ein weiterer Zweck, um ins Musikzimmer zu kommen, ist die Fülle an Musikinstrumenten hier. Die Resonanz zwischen diesen Instrumenten kann meine Fähigkeit verbessern."
  },
  AvgDialog_60212_Content_28 = {
    Text = "Nicht interessiert am Angreifen? Verteidigung funktioniert auch. Mach dich bereit."
  },
  AvgDialog_60212_Content_29 = {
    Text = "Bevor du realisierst, was geschieht, zeigt Hameln mit seinem Stock geschickt nach unten."
  },
  AvgDialog_60212_Content_3 = {
    Text = "Musikraum? Ist dieser Ort sicher?"
  },
  AvgDialog_60212_Content_30 = {
    Text = "Ein klarer Saitenklang hallt gleichzeitig im Musikraum und in deinem Kopf wider."
  },
  AvgDialog_60212_Content_31 = {
    Text = "Die Aufführung beginnt."
  },
  AvgDialog_60212_Content_4 = {
    Text = "Was die Funktionalität betrifft, so liegt dieser Bereich nahe der Suchzone des Ausschusses, also ist es nicht sicher."
  },
  AvgDialog_60212_Content_5 = {
    Text = "Hmm, ich sehe... Der gefährlichste Ort ist der sicherste. Gut durchdacht."
  },
  AvgDialog_60212_Content_6 = {
    Text = "Du denkst zu viel nach. Ich bin hier, weil ich es genieße, an Orten mit Musikinstrumenten zu sein."
  },
  AvgDialog_60212_Content_7 = {
    Text = "......Da du dich entschieden hast, mir zu helfen, kannst du ebenso gut ein Gespräch beginnen."
  },
  AvgDialog_60212_Content_8 = {
    Text = "Hameln, ich habe von dir gehört – dem weltweit führenden Dirigenten – der derzeit auf Tour in Londinium ist."
  },
  AvgDialog_60212_Content_9 = {
    Text = "Sowohl Mythag als auch der Ausschuss haben Untersuchungen über dich angestellt. Niemand hatte erwartet, dass du ein Erwachender sein würdest."
  },
  AvgDialog_60213_Content_1 = {
    Text = "Puh... Ich bin immer noch verletzt, die Verknüpfung wurde gerade wiederhergestellt. Ist das notwendig?"
  },
  AvgDialog_60213_Content_10 = {
    Text = "Hameln denkt einen Moment nach, dann sieht er zu dir auf."
  },
  AvgDialog_60213_Content_11 = {
    Text = "Ich hörte einst eine großartige Melodie, die einem höchsten Wesen gehörte."
  },
  AvgDialog_60213_Content_12 = {
    Text = "Ich bin gekommen, um die vollkommenste Note in diesem Universum zu finden."
  },
  AvgDialog_60213_Content_13 = {
    Text = "Aber was hat das mit mir zu tun? Meine Musiknoten sind nicht sehr gut..."
  },
  AvgDialog_60213_Content_14 = {
    Text = "...unabhängig davon."
  },
  AvgDialog_60213_Content_15 = {
    Text = "Ich verstehe das nicht ganz..."
  },
  AvgDialog_60213_Content_16 = {
    Text = "Jetzt ist nicht die Zeit zu erklären. Deine oberste Priorität ist es, zur Schwarzen Pfütze zu gehen und sie zu stabilisieren."
  },
  AvgDialog_60213_Content_17 = {
    Text = "Die Mitglieder des Ausschusses sind weit weg gegangen. Wir können jetzt aufbrechen."
  },
  AvgDialog_60213_Content_18 = {
    Text = "Wirst du mit uns handeln?"
  },
  AvgDialog_60213_Content_19 = {
    Text = "Meine Musik hat Reichweitenbeschränkungen. Ohne meine Hilfe kannst du jetzt nichts tun."
  },
  AvgDialog_60213_Content_2 = {
    Text = "Du hast noch die Energie, so viel zu reden. Es scheint, als würde sich deine Fähigkeit gut erholen."
  },
  AvgDialog_60213_Content_20 = {
    Text = "Sie können meine Hilfe ablehnen, aber ich würde davon abraten."
  },
  AvgDialog_60213_Content_21 = {
    Text = "Mein Wissen über dich ist sehr begrenzt, aber du scheinst viele Dinge zu wissen..."
  },
  AvgDialog_60213_Content_22 = {
    Text = "Ich mag dieses Gefühl, kontrolliert zu werden, nicht."
  },
  AvgDialog_60213_Content_23 = {
    Text = "Niemand würde es mögen. Doch diese Symphonie hat bereits begonnen. Auf der Bühne muss jeder Musiker seine Rolle erfüllen."
  },
  AvgDialog_60213_Content_24 = {
    Text = "Fehler wie das Verfehlen des Tons oder das Auslassen von Noten... jeder einzelne Fehler könnte diese Aufführung für immer ruinieren."
  },
  AvgDialog_60213_Content_25 = {
    Text = "Er steckte den Schlagstock weg und verließ den Klassenraum."
  },
  AvgDialog_60213_Content_26 = {
    Text = "Es macht mir nichts aus, deine Feindseligkeit. Aber du hast jetzt keine Wahl."
  },
  AvgDialog_60213_Content_27 = {
    Text = "Was du wissen möchtest, werde ich dir auf dem Weg sagen. Lass uns gehen..."
  },
  AvgDialog_60213_Content_28 = {
    Text = "Er neigte seinen Kopf, sein kalter Blick war fest auf dich gerichtet."
  },
  AvgDialog_60213_Content_29 = {
    Text = "...Blinder Blick."
  },
  AvgDialog_60213_Content_3 = {
    Text = "Du wischst dir den Schweiß von der Stirn und runzelst die Stirn, während du ihn anstarrst."
  },
  AvgDialog_60213_Content_4 = {
    Text = "Die Generalprobe ist vorbei. Du hast die Frage von vorhin immer noch nicht beantwortet."
  },
  AvgDialog_60213_Content_5 = {
    Text = "Ich habe dir bereits die Antwort gegeben. Ich hege keine Feindseligkeit dir gegenüber."
  },
  AvgDialog_60213_Content_6 = {
    Text = "Du tauchst aus heiterem Himmel in Mythag zu dieser Zeit auf, plus Clemantines Reaktion..."
  },
  AvgDialog_60213_Content_7 = {
    Text = "Dieses Ereignis betrifft nicht nur Clementine und den Ausschuss. Ich weiß nicht genau, wer sie sind, aber du bist einer von ihnen."
  },
  AvgDialog_60213_Content_8 = {
    Text = "Du könntest das sagen."
  },
  AvgDialog_60213_Content_9 = {
    Text = "Also, warum hilfst du mir?"
  },
  AvgDialog_60217_Content_1 = {
    Text = "Großer{Male=Herr Schutzherr,Female=Frau Schutzherrin}, Lily... Lilys Kopf tut weh"
  },
  AvgDialog_60217_Content_10 = {Text = "Erica?!"},
  AvgDialog_60217_Content_11 = {
    Text = "Erica! Geht es dir gut?"
  },
  AvgDialog_60217_Content_12 = {
    Text = "Feindliche Personen erkannt... Bitte verlassen... Hüter..."
  },
  AvgDialog_60217_Content_13 = {
    Text = "Sie hielt sich schmerzhaft den Kopf, gefühlskalte mechanische Geräusche durchbrachen intermittierend."
  },
  AvgDialog_60217_Content_14 = {
    Text = "Meine Verknüpfung wird schwächer, Erica. Ich werde dich zum Schwarzen Pool bringen. Alles wird gut sein, sobald wir dort angekommen sind..."
  },
  AvgDialog_60217_Content_15 = {
    Text = "Du näherst dich ihr und versuchst, ihren Arm zu stützen. Mit ihrem letzten Rest an Bewusstsein zieht sie sich zurück."
  },
  AvgDialog_60217_Content_16 = {
    Text = "Modifiziert... unkontrollierbar... gefährlich. Bitte geh."
  },
  AvgDialog_60217_Content_17 = {Text = "Erica?"},
  AvgDialog_60217_Content_18 = {
    Text = "Du scheinst ein leises mechanisches Piepen zu hören."
  },
  AvgDialog_60217_Content_19 = {
    Text = "Nach dieser Stimme hebt Erica ihren Kopf und ihre ausdruckslosen Augen starren dich direkt an."
  },
  AvgDialog_60217_Content_2 = {
    Text = "Mein... mein Geist ist auch betroffen..."
  },
  AvgDialog_60217_Content_20 = {
    Text = "Feindliche Personen erkannt. Initiierung des Ausrottungsprotokolls."
  },
  AvgDialog_60217_Content_21 = {Text = "Vorsicht!!"},
  AvgDialog_60217_Content_3 = {
    Text = "Meine Verbindung zu dir wird schwächer... Wenn das so weitergeht, wirst du die Kontrolle verlieren..."
  },
  AvgDialog_60217_Content_4 = {
    Text = "Ich habe Hannah gesagt, sie solle alle Erwachten am Schwarzen Pool versammeln."
  },
  AvgDialog_60217_Content_5 = {
    Text = "Wir müssen uns auch dort drängen. Mit der Hilfe des Lehrers und Tawil kannst du dich vorerst stabilisieren."
  },
  AvgDialog_60217_Content_6 = {
    Text = "Bevor das Komitee aufholt, sollten wir..."
  },
  AvgDialog_60217_Content_7 = {
    Text = "Alarm, feindliche Personen erkannt."
  },
  AvgDialog_60217_Content_8 = {
    Text = "Die Gefahr des Verweilens übersteigt 90%. Bitte verlasse diesen Ort, Hüter."
  },
  AvgDialog_60217_Content_9 = {
    Text = "Am Ende des Flurs erschien Erica, ihre Gestalt wankend."
  },
  AvgDialog_60222_Content_1 = {Text = "Erica!"},
  AvgDialog_60222_Content_10 = {
    Text = "Ericas Reaktion gerade eben... Sie wurde nicht von dem Schwarzen Pool beeinflusst."
  },
  AvgDialog_60222_Content_11 = {
    Text = "Du schaust dir die Überreste von Erikas Explosion an. Mitten im Schutt liegt ein Gerät mit einer ungewöhnlichen Form."
  },
  AvgDialog_60222_Content_12 = {
    Text = "Dieses pyramidenförmige Gerät ist in Erikas Gehirn eingebettet. Auch wenn du mit Erikas mechanischer Struktur nicht vertraut bist, weißt du ganz klar, dass ihr Gehirn ein solches Gerät nicht hat."
  },
  AvgDialog_60222_Content_13 = {
    Text = "Dispelliere den Nebel, detonieren das schwarze Becken und kontrolliere Erica..."
  },
  AvgDialog_60222_Content_14 = {
    Text = "Es gibt einen Maulwurf in Mythag."
  },
  AvgDialog_60222_Content_15 = {
    Text = "Wer hat es getan?! Ich lasse Braun es holen... ugh..."
  },
  AvgDialog_60222_Content_16 = {
    Text = "\"Intensive Schmerzen unterbrachen Jenkins aufgeregte Worte.\""
  },
  AvgDialog_60222_Content_17 = {
    Text = "Ohnmächti ge Schritte sind zu hören, die sich nähern."
  },
  AvgDialog_60222_Content_18 = {
    Text = "Die Explosion kam von dort drüben! Geh!"
  },
  AvgDialog_60222_Content_19 = {
    Text = "Sie verfolgen uns... Lass uns zuerst diesen Ort verlassen!"
  },
  AvgDialog_60222_Content_2 = {Text = "Geh weg!"},
  AvgDialog_60222_Content_20 = {
    Text = "{Male=Er,Female=Sie} ist dorthin gerannt! Durchsucht die Gegend!"
  },
  AvgDialog_60222_Content_21 = {
    Text = "Huch... huch..."
  },
  AvgDialog_60222_Content_22 = {
    Text = "Eilige Schritte nähern sich von hinter dir und verschwinden dann allmählich."
  },
  AvgDialog_60222_Content_23 = {
    Text = "Du versteckst dich hinter einer Säule am Rand des Flures und holst deinen Atem nach."
  },
  AvgDialog_60222_Content_24 = {
    Text = "Der Ausschuss wird bald diesen Ort durchsuchen; wir brauchen einen Plan... Ah!..."
  },
  AvgDialog_60222_Content_25 = {
    Text = "Du greifst dir verzweifelt an den Kopf."
  },
  AvgDialog_60222_Content_26 = {
    Text = "Ein mächtiges Beben breitet sich über die Geisterdimension aus, dein Kopf pocht, kaum kannst du stehen, indem du dich am Pfeiler festhältst"
  },
  AvgDialog_60222_Content_27 = {
    Text = "Deine Erwacherinnen, die dir folgen, haben fast keine Kraft mehr zu sprechen. Du siehst ernsthaft gen Richtung des Schwarzen Pools."
  },
  AvgDialog_60222_Content_28 = {
    Text = "Wenn das so weitergeht, können weder ich noch die Erwacher es aushalten. Wir müssen einen Weg finden, damit umzugehen..."
  },
  AvgDialog_60222_Content_29 = {
    Text = "Verstanden, Hüter."
  },
  AvgDialog_60222_Content_3 = {Text = "Bang—"},
  AvgDialog_60222_Content_30 = {Text = "!!!"},
  AvgDialog_60222_Content_31 = {
    Text = "Beiseite treten"
  },
  AvgDialog_60222_Content_32 = {
    Text = "Mit einem plötzlichen Kraftausbruch in deinen Beinen wichst du schnell zur Seite aus."
  },
  AvgDialog_60222_Content_33 = {
    Text = "Ein Degen fällt genau dorthin, wo du gerade gestanden hast, seine Spitze klirrt gegen die Steinsäule."
  },
  AvgDialog_60222_Content_34 = {
    Text = "Um nach beiden mentalen Schocks und körperlichen Verletzungen immer noch ein solches Maß an Reaktionsfähigkeit zu besitzen."
  },
  AvgDialog_60222_Content_35 = {
    Text = "Der Hüter von Mythag hat seit der Übernahme der Rolle unzählige Gefahren gegenübergestanden."
  },
  AvgDialog_60222_Content_36 = {
    Text = "Mit einem Rapier wirst du sie/ihn nicht fangen"
  },
  AvgDialog_60222_Content_37 = {
    Text = "Beeindruckende Geschwindigkeit, Clementine."
  },
  AvgDialog_60222_Content_38 = {
    Text = "Du wirfst vorsichtig einen Blick auf ihre hypnotischen Werkzeuge, während du die umgebenden Ausschuss-Agenten absuchst."
  },
  AvgDialog_60222_Content_39 = {
    Text = "Dutzende von Agenten haben jeden möglichen Fluchtweg vollständig blockiert."
  },
  AvgDialog_60222_Content_4 = {Text = "Hmm—"},
  AvgDialog_60222_Content_40 = {
    Text = "Leider gibt es dieses Mal keine Zeit, um mit dem Hüter aufzuholen."
  },
  AvgDialog_60222_Content_41 = {
    Text = "Aber keine Sorge, Hüter. Meine Leute werden dich an einen sicheren Ort bringen. Bald haben wir genug Zeit zum Reden."
  },
  AvgDialog_60222_Content_42 = {
    Text = "\"Clementine winkte.\""
  },
  AvgDialog_60222_Content_43 = {
    Text = "Als die Agenten sich dir näherten, begann dein Herz unkontrollierbar zu pochen."
  },
  AvgDialog_60222_Content_44 = {
    Text = "Wenn sie uns jetzt fangen, und die Erwachen in Mythag außer Kontrolle geraten..."
  },
  AvgDialog_60222_Content_45 = {
    Text = "Nein, ich kann das nicht geschehen lassen..."
  },
  AvgDialog_60222_Content_46 = {
    Text = "Selbst wenn der Schwarze Pool außer Kontrolle gerät, selbst wenn die Verknüpfung mit dem Wecker schwächer wird, wird es definitiv einen Weg geben..."
  },
  AvgDialog_60222_Content_47 = {
    Text = "Du bist in die Ecke gedrängt und hältst den Silberschlüssel fest in deiner Hand, während du die Wunde, die durch Ericas Explosion verursacht wurde, abdeckst."
  },
  AvgDialog_60222_Content_48 = {
    Text = "Wellen von Zittern überfallen deinen Geist, und du spürst, wie der schwarze Pool brodelt."
  },
  AvgDialog_60222_Content_49 = {
    Text = "Die leuchtenden Punkte, die einst die Erwachter in deiner Geisterwelt repräsentierten, sind jetzt extrem schwach geworden, und einige sind sogar aus der Geisterwelt verschwunden."
  },
  AvgDialog_60222_Content_5 = {
    Text = "Tulu streckte einen Tentakel aus und zog dich aus der heftigen Explosion heraus."
  },
  AvgDialog_60222_Content_50 = {
    Text = "Ohne den Erwacher ist der Hüter machtlos."
  },
  AvgDialog_60222_Content_51 = {
    Text = "Ruhig, denke..."
  },
  AvgDialog_60222_Content_52 = {
    Text = "Es muss... Es muss einen Weg geben..."
  },
  AvgDialog_60222_Content_53 = {
    Text = "\"Beruhige dich, %player%. Beruhig dich...\""
  },
  AvgDialog_60222_Content_54 = {
    Text = "Mit genügend Geisterkraft, um den Silberschlüssel zu bewegen, können nahegelegene Erwachte formidable Kampffähigkeiten zurückgewinnen..."
  },
  AvgDialog_60222_Content_55 = {
    Text = "Ja, du kennst den Weg. Du hast ihn schon immer gekannt."
  },
  AvgDialog_60222_Content_56 = {
    Text = "Jedoch, angesichts deines aktuellen Geist-Zustands, welche irreversible Schäden könnte das zwangsweise Führen eines Erwachens verursachen?"
  },
  AvgDialog_60222_Content_57 = {
    Text = "Gehirnschaden? Permanente Behinderung, zu einem Gemüse werden? Oder..."
  },
  AvgDialog_60222_Content_58 = {
    Text = "Tief in deinem Geist hörst du den leisen Ruf der Erwachten. Du wendest dich Mythag zu, hältst den silbernen Schlüssel fest in der Hand, dein Hand zittert leicht von der Anstrengung."
  },
  AvgDialog_60222_Content_59 = {
    Text = "Die Konsequenzen könnten mittlerweile egal sein. Du weißt, dass du keine andere Wahl hast."
  },
  AvgDialog_60222_Content_6 = {
    Text = "Ericas Körperteile liegen überall auf dem Boden verstreut. Scharfe Fragmente hinterlassen zahlreiche Wunden an deinem Körper, und Blut fließt heraus und färbt deine Uniform rot."
  },
  AvgDialog_60222_Content_60 = {
    Text = "Es gibt nur diesen einen Weg"
  },
  AvgDialog_60222_Content_61 = {
    Text = "Fang {Male=er,Female=sie}"
  },
  AvgDialog_60222_Content_62 = {
    Text = "Aktivierung des silbernen Schlüssels erzwingen"
  },
  AvgDialog_60222_Content_63 = {
    Text = "Du hebst deine Hand mit dem silbernen Schlüssel."
  },
  AvgDialog_60222_Content_64 = {
    Text = "Ich werde dich nicht lassen..."
  },
  AvgDialog_60222_Content_65 = {
    Text = "Zweiter Satz, Anfang"
  },
  AvgDialog_60222_Content_66 = {Text = "Hmm—"},
  AvgDialog_60222_Content_67 = {Text = "?!"},
  AvgDialog_60222_Content_68 = {
    Text = "Bevor der silberne Schlüssel in deiner Hand aufleuchten konnte, hörtest du eine kühle Stimme hinter dir"
  },
  AvgDialog_60222_Content_69 = {
    Text = "Diese Stimme ist die Spur des Dirigenten, das unumstößliche Gesetz in der Welt der Noten"
  },
  AvgDialog_60222_Content_7 = {
    Text = "Große{Male=Herr Schutzherr,Female=Frau Schutzherrin}!"
  },
  AvgDialog_60222_Content_70 = {
    Text = "Nach dieser Stimme ertönt majestätische Musik aus eurem Bewusstsein"
  },
  AvgDialog_60222_Content_72 = {Text = "!!!"},
  AvgDialog_60222_Content_73 = {
    Text = "Ist das? ......"
  },
  AvgDialog_60222_Content_74 = {
    Text = "Verstaue deinen Silberschlüssel. Aktivierst du ihn jetzt, stirbst du"
  },
  AvgDialog_60222_Content_75 = {
    Text = "Takt. Melodie. Die sanften Obertöne der Streicher füllen eure Gedanken"
  },
  AvgDialog_60222_Content_76 = {
    Text = "Das ist ein mysteriöses Frequenzband. Die Leute des Ausschusses fallen schmerzhaft zu Boden bei dieser Musik, während du dich fühlst, als wärst du von Thermalwasser umhüllt und gereinigt"
  },
  AvgDialog_60222_Content_77 = {
    Text = "Du spürst deutlich, dass die Verbindung zu den Erweckern wiederhergestellt ist. Die Wellen von der schwarzen Pfütze scheinen ebenfalls in diesem Klang zu verschwinden"
  },
  AvgDialog_60222_Content_78 = {
    Text = "Clementine schaut überrascht in Richtung der Stimme"
  },
  AvgDialog_60222_Content_79 = {
    Text = "Du bist es! Warum"
  },
  AvgDialog_60222_Content_8 = {
    Text = "Mir geht's gut..."
  },
  AvgDialog_60222_Content_80 = {
    Text = "Schlagzeug, Stopp"
  },
  AvgDialog_60222_Content_81 = {
    Text = "Der Mann schwang leicht den Taktstock. Ein kurzer, kraftvoller Befehlston brachte einen Moment der Stille"
  },
  AvgDialog_60222_Content_82 = {
    Text = "Clementine bricht zusammen und fällt zu Boden"
  },
  AvgDialog_60222_Content_83 = {Text = "Du... bist"},
  AvgDialog_60222_Content_84 = {
    Text = "Andere werden bald hier sein, meine Musik hält nicht lange"
  },
  AvgDialog_60222_Content_85 = {
    Text = "Ich werde dich an einen sicheren Ort bringen"
  },
  AvgDialog_60222_Content_86 = {
    Text = "Er drehte sich um, nickte dir leicht zu, sein Gesichtsausdruck war ruhig wie ein stiller See"
  },
  AvgDialog_60222_Content_87 = {
    Text = "Dirigent Hameln, zu Ihren Diensten."
  },
  AvgDialog_60222_Content_9 = {
    Text = "Erica scheint nicht vom Schwarzen Pool betroffen zu sein."
  },
  AvgDialog_60223_Content_1 = {
    Text = "Als du dich bereit machst, es zu erledigen, springt der scheinbar sterbende hundegesichtige Wesen plötzlich an dir vorbei."
  },
  AvgDialog_60223_Content_10 = {
    Text = "Eine große Frau erschien vor dir und steckte ihr Schwert weg."
  },
  AvgDialog_60223_Content_11 = {
    Text = "Alva! Geht es dir gut?"
  },
  AvgDialog_60223_Content_12 = {
    Text = "Ein wenig betroffen, den Aufforderungen folgend, ziehe ich mich in die Nähe des Black Pool zurück."
  },
  AvgDialog_60223_Content_13 = {
    Text = "Wer ist das?"
  },
  AvgDialog_60223_Content_14 = {
    Text = "Sie runzelte die Stirn und hielt das Messer hinter sich fest."
  },
  AvgDialog_60223_Content_15 = {
    Text = "Er hat den Duft der Tempellicht-Kirche"
  },
  AvgDialog_60223_Content_16 = {
    Text = "Das ist Hameln... Ich werde später mehr erklären, aber er ist jetzt ein Verbündeter von Mythag."
  },
  AvgDialog_60223_Content_17 = {
    Text = "Du trittst vor, um die Leiche mit dem Hundegesicht zu untersuchen."
  },
  AvgDialog_60223_Content_18 = {
    Text = "Es ist das Zeichen der Tempel-Licht-Kirche. Die Richtung, in die sie gehen will, ist der Schwarze See..."
  },
  AvgDialog_60223_Content_19 = {
    Text = "Juliette hat den Schwarzen Teich erreicht. Wir müssen schnell handeln."
  },
  AvgDialog_60223_Content_2 = {
    Text = "Es ist entkommen! Halt es auf!"
  },
  AvgDialog_60223_Content_20 = {
    Text = [[
Du packst zusammen, die Augen auf den Uhrturm gerichtet.
Der Schwarze Pool existiert seit 300 Jahren lautlos im Abgrund darunter.]]
  },
  AvgDialog_60223_Content_21 = {
    Text = "Hameln, du hast gerade erwähnt, welche Beziehung besteht zwischen dem Zwillingsprojekt und Mythag?"
  },
  AvgDialog_60223_Content_22 = {
    Text = "Die Laterne erzeugte drei Paare von Zwillingen, aber zwei der Paare endeten im Misserfolg."
  },
  AvgDialog_60223_Content_23 = {
    Text = "Ihr erstes und vielversprechendstes Zwillingspaar befindet sich in Mythag."
  },
  AvgDialog_60223_Content_24 = {
    Text = "Wer ist es?"
  },
  AvgDialog_60223_Content_25 = {
    Text = "Vor Jahren wurde einer der ersten Zwillinge, die mit der vollen Kraft der Tempellichtkirche erschaffen wurden, von dem Edelmann Dexter aus Mythag abgefangen."
  },
  AvgDialog_60223_Content_26 = {
    Text = "Als Sie den Namen \"Dexter\" hörten, sprang Ihr Herz in Ihren Hals."
  },
  AvgDialog_60223_Content_27 = {
    Text = "Hameln senkte seine langen Wimpern und sprach leise die Informationen aus, die du nicht glauben wolltest, die in deinem Kopf wirbelten."
  },
  AvgDialog_60223_Content_28 = {
    Text = "Ihr Name ist Ramona."
  },
  AvgDialog_60223_Content_29 = {
    Text = "Ihr Kopf schwirrt, und alles um Sie herum fühlt sich wie ein Traum an, der kurz vor dem Erwachen steht."
  },
  AvgDialog_60223_Content_3 = {
    Text = "Hameln schwingt schnell den Taktstock, die Musik beginnt, aber der menschenähnliche Hund bewegt sich mit unglaublicher Geschwindigkeit und erreicht im Handumdrehen den Rand von Hameln's Angriffsreichweite."
  },
  AvgDialog_60223_Content_30 = {
    Text = "Du meinst..."
  },
  AvgDialog_60223_Content_31 = {
    Text = "Deine Klassenkameraden, deine Freunde, deine engsten Begleiter."
  },
  AvgDialog_60223_Content_32 = {
    Text = "Juliette setzte all ihre Kraft ein. Sie kam für Ramona."
  },
  AvgDialog_60223_Content_4 = {
    Text = "Die Melodie brachte es ins Stolpern, aber es wurde nicht vollständig gestoppt."
  },
  AvgDialog_60223_Content_5 = {
    Text = "Wir können es nicht entkommen lassen!"
  },
  AvgDialog_60223_Content_6 = {
    Text = "Du jagst vergeblich. Der Kreigermensch ist extrem schnell und steht kurz davor, aus deinem Blickfeld zu verschwinden..."
  },
  AvgDialog_60223_Content_7 = {
    Text = "Schwisch—"
  },
  AvgDialog_60223_Content_8 = {
    Text = "Ein Blitz der Klinge taucht plötzlich aus dem Gebüsch auf und schneidet dem Hund mit menschlichem Gesicht über den Kopf."
  },
  AvgDialog_60223_Content_9 = {
    Text = "Der Kopf trennte sich vom Körper, rollte auf dem Boden und hinterließ eine schmutzige Blutspur."
  },
  AvgDialog_60327_Content_1 = {Text = "Boom—"},
  AvgDialog_60327_Content_10 = {
    Text = "Eine mächtige Schockwelle stößt dich zurück. Die Zwillinge stoßen einen scharfen, durchdringenden Schrei aus, der fast deine Trommelfelle platzen lässt."
  },
  AvgDialog_60327_Content_11 = {
    Text = "Das große Rad, das Zeit und Schicksal symbolisiert, zerbricht, gefolgt vom Körper der Statue."
  },
  AvgDialog_60327_Content_12 = {
    Text = "Mit einem Kreischen zerbrachen die Zwillingsidole und stürzten ein. Ihre massiven Teile verwandelten sich in schwarze Auflösungsflüssigkeit, die in den Schwarzen Pool fiel und keine Spur hinterließ."
  },
  AvgDialog_60327_Content_13 = {
    Text = "Hüter, haben wir... erfolgreich abgeschnitten?"
  },
  AvgDialog_60327_Content_14 = {
    Text = "Ja, Ramona, wir haben es geschafft!"
  },
  AvgDialog_60327_Content_15 = {
    Text = "Du hältst sie fest."
  },
  AvgDialog_60327_Content_16 = {
    Text = "Dieses Mal hat Ramona nicht widerstanden. Sie lag in deinen Armen und lächelte wie ein Kleinkind."
  },
  AvgDialog_60327_Content_17 = {
    Text = "Vielen Dank, %player%."
  },
  AvgDialog_60327_Content_18 = {
    Text = "Du hebst deinen Kopf."
  },
  AvgDialog_60327_Content_19 = {
    Text = "Die Gestalt, die vor der Tür Wache stand, diejenige, die dir in einer Illusion begegnete, steht jetzt vor dir."
  },
  AvgDialog_60327_Content_2 = {Text = "Ramona!"},
  AvgDialog_60327_Content_20 = {Text = "Tawil?!"},
  AvgDialog_60327_Content_21 = {
    Text = "Tawil? Du..."
  },
  AvgDialog_60327_Content_22 = {
    Text = "Tawil und mein Bewusstsein verschmelzen und trennen sich dann innerhalb der Statue."
  },
  AvgDialog_60327_Content_23 = {
    Text = "Nachdem die göttliche Statue zerstört wurde, kehrte ihr Bewusstsein in ihren Körper zurück."
  },
  AvgDialog_60327_Content_24 = {
    Text = "Die Kraft des intellektuellen Körpers hat mich fast vollständig verlassen. Die verborgene Dimension wurde ebenfalls verschlungen und aufgelöst."
  },
  AvgDialog_60327_Content_25 = {
    Text = "Glücklicherweise muss ich mich nicht mehr verstecken. Der höchste Wille kann meine Stimme nicht mehr hören."
  },
  AvgDialog_60327_Content_26 = {
    Text = "Tawil schenkt dir ein schwaches Lächeln. Ein sanftes Leuchten umhüllt ihr schwaches, sanftes Gesicht."
  },
  AvgDialog_60327_Content_27 = {
    Text = "Du hast dein Versprechen gehalten, %player%."
  },
  AvgDialog_60327_Content_28 = {
    Text = "Du hast uns besiegt... Du hast uns gerettet."
  },
  AvgDialog_60327_Content_29 = {
    Text = "Hüter, schau."
  },
  AvgDialog_60327_Content_3 = {
    Text = "Du springst heraus und fängst die schwache Gestalt zwischen der zusammenbrechenden Statue."
  },
  AvgDialog_60327_Content_30 = {
    Text = "Du folgst Ramonas Blick."
  },
  AvgDialog_60327_Content_31 = {
    Text = "Hinter der Statue hielten die riesigen Steintore an, und die unzähligen Illusionen drinnen beruhigten sich"
  },
  AvgDialog_60327_Content_32 = {
    Text = "Komplexe Farben fließen langsam innerhalb des Tores, wie ein Traum, aus dem man niemals erwacht."
  },
  AvgDialog_60327_Content_4 = {
    Text = "Keeper... Keeper..."
  },
  AvgDialog_60327_Content_5 = {
    Text = "Ramona sieht dich an. Du kannst ihre Dimension nicht genau bestimmen oder ob sie Ramona, Tawil oder jemand anderes ist."
  },
  AvgDialog_60327_Content_6 = {
    Text = "Aber das ist nicht wichtig. Wichtig ist, dass sie wieder bei dir ist, genau wie unzählige Male zuvor."
  },
  AvgDialog_60327_Content_7 = {
    Text = "Du nimmst ihre Hand, genau wie als du zum ersten Mal ein Hüter wurdest."
  },
  AvgDialog_60327_Content_8 = {
    Text = "Ein kontinuierlicher Fluss von Geisterkraft, wie ein Ozean, strömt in den silbernen Schlüssel und leitet sich in Romanas Körper."
  },
  AvgDialog_60327_Content_9 = {Text = "Ahhhh—"},
  AvgDialog_60340_Content_1 = {Text = "Pfad"},
  AvgDialog_60340_Content_10 = {
    Text = "Sie und Sylvia eskortieren Czort und gehen von einem abgelegenen westlichen Korridor zum Biologie-Institut..."
  },
  AvgDialog_60340_Content_11 = {
    Text = "Der Korridor nach Westen?"
  },
  AvgDialog_60340_Content_12 = {
    Text = "Beim Hören von Alvas Worten runzelte Hameln leicht die Stirn."
  },
  AvgDialog_60340_Content_13 = {
    Text = "Bevor ich kam, um dich zu finden, führte Herbert eine Gruppe westlich der Schule. Seine Mission war es, Ramona zu finden."
  },
  AvgDialog_60340_Content_14 = {
    Text = "Ramona ist klug; Herbert sollte nichts gegen sie ausrichten können..."
  },
  AvgDialog_60340_Content_15 = {
    Text = "Nicht so einfach. Ramona hat ein Zeichen der Tempellichtkirche in ihren Körper eingraviert."
  },
  AvgDialog_60340_Content_16 = {
    Text = "Folgend den Markierungen können sie nicht nur Ramonas Standort verfolgen, sondern ihr auch die Bewegungsfreiheit entziehen."
  },
  AvgDialog_60340_Content_17 = {Text = "!!!"},
  AvgDialog_60340_Content_18 = {
    Text = "Ich werde Musik verwenden, um vorübergehend deine geistige Verbindungsstärke auf ein normales Niveau zu steigern. Versuche, sie zu lokalisieren."
  },
  AvgDialog_60340_Content_19 = {Text = "Danke!"},
  AvgDialog_60340_Content_2 = {
    Text = "Du meinst... Ramona wurde von der Laterne erschaffen?!"
  },
  AvgDialog_60340_Content_20 = {
    Text = "Hameln nickte leicht. Sein Dirigentenstab zeichnete elegant einen perfekten Bogen in der Luft."
  },
  AvgDialog_60340_Content_21 = {
    Text = "Eine begeisterte Melodie strömt in deinen Geist und synchronisiert sich mit seinen geschickten Bewegungen.\nDu schließt deine Augen und lässt die Welle der Musik dein schwebendes Bewusstsein leiten."
  },
  AvgDialog_60340_Content_22 = {
    Text = "Suche nach Ramonas Figur"
  },
  AvgDialog_60340_Content_23 = {
    Text = "Im Geisterdimension leuchteten die vertrauten Lichtpunkte erneut auf. Du suchst intensiv."
  },
  AvgDialog_60340_Content_24 = {
    Text = "Aber unter diesen Punkten des Lichts wirst du, egal wie sehr du suchst, diese vertraute Gestalt nicht finden."
  },
  AvgDialog_60340_Content_25 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_60340_Content_26 = {
    Text = "Hüter, wie ist es?"
  },
  AvgDialog_60340_Content_27 = {
    Text = "{Male=Er,Female=Sie} wurde nicht gefunden"
  },
  AvgDialog_60340_Content_28 = {
    Text = "Da die Laterne nach Ramona kommt, lass uns sie zuerst retten!"
  },
  AvgDialog_60340_Content_29 = {
    Text = "Du sprichst, während du nach Westen gehst."
  },
  AvgDialog_60340_Content_3 = {
    Text = "Dein Körper bewegt sich mechanisch zum Schwarzen Pool, aber dein Geist ist vollkommen von Hamelns Worten besetzt."
  },
  AvgDialog_60340_Content_30 = {
    Text = "Ich weiß, wie wichtig Ramona dir ist. Aber bleib ruhig, Hüter."
  },
  AvgDialog_60340_Content_31 = {
    Text = "Sich mit dem Problem des Schwarzen Pools zu beschäftigen, hat höchste Dringlichkeit. Du weißt jetzt auch nicht, wo Ramona ist."
  },
  AvgDialog_60340_Content_32 = {
    Text = "Das ist anders als zuvor. Die Laterne ist hinter ihr her und ich kann das nicht einfach ignorieren."
  },
  AvgDialog_60340_Content_33 = {
    Text = "Wenn wir einfach zu ihrem letzten bekannten Aufenthaltsort gehen, werden wir sie bald finden..."
  },
  AvgDialog_60340_Content_34 = {
    Text = "Ich weiß, wo sie ist."
  },
  AvgDialog_60340_Content_35 = {Text = "!!!"},
  AvgDialog_60340_Content_36 = {
    Text = "Du hältst plötzlich an. Hameln nickt leicht, seine sorgfältig frisierten Kleider schwingen rhythmisch mit seinen Bewegungen."
  },
  AvgDialog_60340_Content_37 = {
    Text = "Sie können sie in der Geistdimensionalität nicht finden, was bedeutet, dass sie gefangen genommen worden sein muss."
  },
  AvgDialog_60340_Content_38 = {
    Text = "Wie geplant wird Herbert Ramona zum Schwarzen Pool bringen. Sie wird vorerst nicht in Gefahr sein."
  },
  AvgDialog_60340_Content_39 = {Text = "Warum?"},
  AvgDialog_60340_Content_4 = {
    Text = "Vor fast zwanzig Jahren drang die Tempellicht-Kirche mit Herberts Hilfe in den Schwarzen Pool ein und nutzte Tawils Bewusstsein, um die Zwillingsheiligen Ramona zu erschaffen."
  },
  AvgDialog_60340_Content_40 = {
    Text = "Das Schöpfungsritual der Laterne erfordert die Kraft eines D-Rifts. Es gibt nur einen D-Rift in Mythag."
  },
  AvgDialog_60340_Content_41 = {
    Text = "—Neben der Behinderung deiner Aktionen und der Verursachung von Chaos unter den Erwachten ist Juliettes Ziel bei der Detonation des Schwarzen Pools, mehr von seiner Macht freizusetzen."
  },
  AvgDialog_60340_Content_42 = {Text = "Ramona..."},
  AvgDialog_60340_Content_43 = {
    Text = "Der Tod von Ramona ist bedeutungslos. Das Ritual zur Schaffung eines Gottes erfordert eine lange Vorbereitungszeit. Bis dahin wird Ramona sicher sein."
  },
  AvgDialog_60340_Content_44 = {
    Text = "Ich verstehe... Ich verstehe es jetzt."
  },
  AvgDialog_60340_Content_45 = {
    Text = "Du nimmst einen tiefen Atemzug, um dich zu beruhigen, und blickst dann in Richtung des Eingangs des nicht weit entfernten unterirdischen Durchgangs."
  },
  AvgDialog_60340_Content_46 = {
    Text = "Lass uns gehen... zum Schwarzen Pool und sie finden!"
  },
  AvgDialog_60340_Content_5 = {
    Text = "\"Als sie sich vorbereitete zu gehen, wurde Ramona von einem Professor aus Mythag gerettet. Seitdem ist sie bei Mythag geblieben.\""
  },
  AvgDialog_60340_Content_6 = {
    Text = "Professor Dexter... Ja, er erwähnte tatsächlich die Herkunft von Ramona."
  },
  AvgDialog_60340_Content_7 = {
    Text = "Es stellt sich heraus, dass er Ramona damals aus der Kirche des Tempellichts gerettet hat!"
  },
  AvgDialog_60340_Content_8 = {
    Text = "Da die Tempellichtkirche hinter Ramona her ist, müssen wir sie schnell warnen..."
  },
  AvgDialog_60340_Content_9 = {
    Text = "Ich traf sie auf dem Weg hierher."
  },
  AvgDialog_60341_Content_1 = {
    Text = "Nachdem Sie sich mit den Ausschussagenten auf dem Weg befasst haben, erreichen Sie den vertrauten Raum und drücken vorsichtig die Tür auf."
  },
  AvgDialog_60341_Content_10 = {
    Text = "Alistair ließ ein leichtes Seufzen hören."
  },
  AvgDialog_60341_Content_11 = {
    Text = "Lehrer, sag mir bitte... Was soll ich jetzt tun?"
  },
  AvgDialog_60341_Content_12 = {
    Text = "Ich spüre die Kraft der drei Entitäten... Sie sind alle im Schwarzen Pool erschienen."
  },
  AvgDialog_60341_Content_13 = {
    Text = "Obwohl ich den Grund nicht kenne, habe ich den Weg gesehen, den du gehen wirst."
  },
  AvgDialog_60341_Content_14 = {
    Text = "Gehe zum Schwarzen Pool, %player%. Suche die drei Essenzen."
  },
  AvgDialog_60341_Content_15 = {
    Text = "Werden sie uns helfen?"
  },
  AvgDialog_60341_Content_16 = {
    Text = "Die drei großen Entitäten trafen vollkommen unterschiedliche Entscheidungen als Reaktion auf die finale Katastrophe."
  },
  AvgDialog_60341_Content_17 = {
    Text = "Der Intellektuelle Körper entschied sich, zurückzuschlagen. Sie wählte einen Executor, etablierte Mythag und lehrte die Menschheit die Silber-Chip-Technologie."
  },
  AvgDialog_60341_Content_18 = {
    Text = "Die Essenz des Verlangens wählte es vor, sich zu entziehen. Sie nutzt ihre Proxys, um ihre Samen überall zu pflanzen und versucht, auf diese Weise die ultimative Katastrophe zu überleben."
  },
  AvgDialog_60341_Content_19 = {
    Text = "Wo ist die Essenz der Freude?"
  },
  AvgDialog_60341_Content_2 = {
    Text = "Du bist hier, %player%... *hust*..."
  },
  AvgDialog_60341_Content_20 = {
    Text = "Tawil sagt mir, dass Er sich entscheidet zu beobachten. Er kümmert sich weder um Leben noch um Tod, sondern nur um sein eigenes Vergnügen."
  },
  AvgDialog_60341_Content_21 = {
    Text = "Also, abgesehen vom Intellektuellen Körper, ist die Haltung der anderen beiden gegenüber Mythag unklar; sie könnten mir möglicherweise nicht helfen..."
  },
  AvgDialog_60341_Content_22 = {
    Text = "Es spielt keine Rolle. Du suchst nicht nach Ihrer Hilfe, %player%."
  },
  AvgDialog_60341_Content_23 = {
    Text = "Ein scharfer Glanz blitzt in Alistairs sanften Augen auf."
  },
  AvgDialog_60341_Content_24 = {
    Text = "Deine Aufgabe ist es, Ihre Fähigkeiten zu erlangen und Ihre Mächte zu akzeptieren!"
  },
  AvgDialog_60341_Content_25 = {
    Text = "Aber... das ist ein Tri-Entität..."
  },
  AvgDialog_60341_Content_26 = {
    Text = "Lehrer... Das..."
  },
  AvgDialog_60341_Content_27 = {
    Text = "Sie würden nicht einmal Hilfe anbieten, also wie könnten sie das..."
  },
  AvgDialog_60341_Content_28 = {
    Text = "Außerdem bin ich mir nicht klar, was diese Kräfte sind oder wie ich sie nutzen kann."
  },
  AvgDialog_60341_Content_29 = {
    Text = "Dies ist dein Pfad. Du wirst beginnen, ihn zu verstehen."
  },
  AvgDialog_60341_Content_3 = {
    Text = "Lehrer Alistair!"
  },
  AvgDialog_60341_Content_30 = {
    Text = "Alistairs Lächeln war wie ein Paar sanfter Hände, die deinen Kopf streichelten."
  },
  AvgDialog_60341_Content_31 = {
    Text = "Auf diesem Weg wirst du sowohl Freunde als auch Feinde treffen."
  },
  AvgDialog_60341_Content_32 = {
    Text = "Die Flut kommt. Jeder muss seinen Teil beitragen. Wir sind alle gleich."
  },
  AvgDialog_60341_Content_33 = {
    Text = "Er blickt dich und Hameln an und spricht Worte voller Bedeutung, die unklar lassen, an wen sie gerichtet sind."
  },
  AvgDialog_60341_Content_34 = {
    Text = "Hameln stand im Schatten und nickte leicht."
  },
  AvgDialog_60341_Content_35 = {
    Text = "Alistair sagte nichts mehr. Er drehte sich um und starrte weiterhin auf den grenzenlosen Schwarzen Pool."
  },
  AvgDialog_60341_Content_36 = {
    Text = "Mach dir keine Sorgen um den Schwarzen Pool oder um mich."
  },
  AvgDialog_60341_Content_37 = {
    Text = "Du wirst bald lernen, was bekannt werden muss."
  },
  AvgDialog_60341_Content_38 = {
    Text = "Gehe. Es ist Zeit, deinen eigenen Weg zu gehen."
  },
  AvgDialog_60341_Content_4 = {
    Text = "Blut spritzte aus Alistairs Mund und färbte die Bandagen an seinem Oberkörper dunkelrot."
  },
  AvgDialog_60341_Content_5 = {
    Text = "In nur wenigen Stunden wurde Alistair extrem schwach, sein Körper zitterte vor Kälte und Schmerz, kaum in der Lage, auf seinem Rollstuhl zu bleiben."
  },
  AvgDialog_60341_Content_6 = {
    Text = "Lehrer... Ich bin spät dran... Ich hole dich sofort heraus!"
  },
  AvgDialog_60341_Content_7 = {
    Text = "Alistair sagte nicht viel, lächelte nur und schüttelte leicht den Kopf."
  },
  AvgDialog_60341_Content_8 = {
    Text = "Die schwarze Pfütze zu unterdrücken ist meine Pflicht. Deine Pflicht liegt nicht hier."
  },
  AvgDialog_60341_Content_9 = {
    Text = "Das ist ein Weg, der zehntausendmal schwieriger ist als meiner..."
  },
  AvgDialog_60342_Content_1 = {
    Text = "Es geschafft!"
  },
  AvgDialog_60342_Content_10 = {
    Text = "Du tratst vor und streckst deine Hand zu ihr aus."
  },
  AvgDialog_60342_Content_11 = {
    Text = "Antworte mir, Tawil..."
  },
  AvgDialog_60342_Content_12 = {Text = "!!!"},
  AvgDialog_60342_Content_13 = {
    Text = "Hier ist..."
  },
  AvgDialog_60342_Content_14 = {
    Text = "Im Moment, in dem du Tawils Körper berührst, verschwindet das schwarze Becken aus deiner Sicht."
  },
  AvgDialog_60342_Content_15 = {
    Text = "Du schaust auf die fließenden Substanzen vor dir. Unsicher, was sie sind, streckst du die Hand aus und lässt sie durch deinen Körper fließen und langsam vorbeiziehen."
  },
  AvgDialog_60342_Content_16 = {
    Text = "In diesem fantastischen Glanz entfaltet sich ein illusorisches Bild vor dir. Ein bekanntes Gesicht erscheint"
  },
  AvgDialog_60342_Content_17 = {
    Text = "Ramona! Dieser Ort ist..."
  },
  AvgDialog_60342_Content_18 = {
    Text = "Bewusstsein, Träume, die Vereinigung zahlloser Zeiten und Dimensionen, wo Rationalität und Irrationalität aufeinandertreffen. Eine nicht-existierende Singularität..."
  },
  AvgDialog_60342_Content_19 = {
    Text = "Die illusorische Ramona spricht und erzählt dir die Herkunft dieses Ortes, bevor sie aus dem Blickfeld verschwindet."
  },
  AvgDialog_60342_Content_2 = {
    Text = "Ramona scheint abwesend zu sein..."
  },
  AvgDialog_60342_Content_20 = {Text = "Ramona!"},
  AvgDialog_60342_Content_21 = {
    Text = "Das ist ihr Schatten. Ein Schatten aus der Vergangenheit."
  },
  AvgDialog_60342_Content_22 = {
    Text = "Eine Stimme, scheinbar von weitem, doch auch aus deinem Geist heraus."
  },
  AvgDialog_60342_Content_23 = {
    Text = "Willkommen in meinem Versteck, Hüter."
  },
  AvgDialog_60342_Content_24 = {
    Text = "Tawil... Ich verstehe jetzt. Hier versteckst du dich vor dem Höchsten Willen."
  },
  AvgDialog_60342_Content_25 = {
    Text = "In Mythag sind viele Dinge passiert. Ich kam, um dich zu finden, weil..."
  },
  AvgDialog_60342_Content_26 = {
    Text = "Katastrophe naht, Alistair hat dir alles gesagt. Tifereth und Malkuth haben ihre Autorität an dich übergeben."
  },
  AvgDialog_60342_Content_27 = {
    Text = "Weißt du alles, was draußen passiert ist?"
  },
  AvgDialog_60342_Content_28 = {
    Text = "Dieser Raum ist mit allem gefüllt, was mit der Vergangenheit, der Gegenwart und der Zukunft zu tun hat."
  },
  AvgDialog_60342_Content_29 = {
    Text = "Der Intellektuelle Körper, allwissend."
  },
  AvgDialog_60342_Content_3 = {
    Text = "Die in der Nähe patrouillierenden Ausschussmitglieder zeigen unterschiedliche Anzeichen von Auflösung."
  },
  AvgDialog_60342_Content_30 = {
    Text = "Um die endgültige Katastrophe nicht zu alarmieren, kann ich nicht direkt in deine Welt eingreifen. Daher habe ich dich hierher gebracht, um dich zu treffen."
  },
  AvgDialog_60342_Content_31 = {
    Text = "Ich werde Mythag helfen. Ich werde deiner Welt helfen."
  },
  AvgDialog_60342_Content_32 = {
    Text = "Klasse! Jetzt..."
  },
  AvgDialog_60342_Content_33 = {
    Text = "Quelle von Akut, ich habe dich gesehen. Es gibt etwas an dir, das ich nicht discernieren kann."
  },
  AvgDialog_60342_Content_34 = {
    Text = "Ich rechne hier. In unzähligen Zukunftsvisionen habe ich den richtigen Weg gesehen... Jetzt sehe ich dich klar."
  },
  AvgDialog_60342_Content_35 = {
    Text = "Ihre Augen öffneten sich langsam, kalt und allsehend, sie starrten dich an."
  },
  AvgDialog_60342_Content_36 = {
    Text = "Die Substanz, die um dich herumströmte, kam plötzlich zum Halt. Überrascht wurdest du von einem überwältigenden Druck fest umhüllt, was das Atmen erschwerte."
  },
  AvgDialog_60342_Content_37 = {
    Text = "Was... sagst du..."
  },
  AvgDialog_60342_Content_38 = {
    Text = "Du liegst mit allen Berechnungen falsch."
  },
  AvgDialog_60342_Content_39 = {
    Text = "Für Mythag, für den Fortbestand dieser Welt, werde ich diesen Fehler hier korrigieren."
  },
  AvgDialog_60342_Content_4 = {
    Text = "Je näher du Tawil kommst, desto heftiger wird die Auflösungserosion. Juliette wird sich nicht nähern, bis das Ritual bereit ist."
  },
  AvgDialog_60342_Content_40 = {Text = "!!!"},
  AvgDialog_60342_Content_5 = {
    Text = "Vollständig die Wiederherstellung der Autorität, bevor sie erscheint."
  },
  AvgDialog_60342_Content_6 = {
    Text = "Du schaust auf die illusorische Gestalt vor dir."
  },
  AvgDialog_60342_Content_7 = {
    Text = "Ein leuchtendes weißes Federchen schwebt sanft nach unten und verschwindet in der Luft. Innerhalb der riesigen Flügel wird ein schlafendes Gesicht offenbart."
  },
  AvgDialog_60342_Content_8 = {
    Text = "Verflochtenes Licht und Schatten verdeckten deine Sicht; egal wie sehr du dich anstrengtest, du konntest ihr Gesicht nicht erkennen, als ob es in deiner Zeit und deinem Raum nicht existierte."
  },
  AvgDialog_60342_Content_9 = {
    Text = "Berühre Tawil"
  },
  AvgDialog_60343_Content_1 = {
    Text = "Nicht schlecht, Hüter {Male=Herr,Female=Frau}"
  },
  AvgDialog_60343_Content_2 = {
    Text = "Gerade die Macht des Verlangens absorbiert und hält immer noch durch... Ich habe dich unterschätzt"
  },
  AvgDialog_60343_Content_3 = {
    Text = "N erhebt sich aus dem Publikum, zieht seinen Hut und grüßt dich höflich auf der Bühne."
  },
  AvgDialog_60343_Content_4 = {
    Text = "Als nächstes, sind wir an der Reihe aufzutreten."
  },
  AvgDialog_60343_Content_5 = {
    Text = "Der heimtückische und charmante letzte Bösewicht steht kurz vor seinem Auftritt—"
  },
  AvgDialog_60344_Content_1 = {
    Text = "Guter Schüler, schlechter Schüler"
  },
  AvgDialog_60344_Content_10 = {
    Text = "Ramona, entschuldige die Umstände. Wenn ich nicht verletzt wäre, könnte ich dir vielleicht etwas helfen"
  },
  AvgDialog_60344_Content_100 = {
    Text = "Er stand auf und lächelte, während er die haarlose Katze auf seiner Schulter streichelte."
  },
  AvgDialog_60344_Content_101 = {
    Text = "Die Katze hob ihren Kopf und ihr gelangweilter Blick fegte über die Menschen als Reaktion."
  },
  AvgDialog_60344_Content_11 = {
    Text = [[
Sag das nicht, Direktor.
Die Leute von Mythag betrachten die Verwundeten niemals als Belastung.]]
  },
  AvgDialog_60344_Content_12 = {
    Text = "Wenn wir euch im Gebäude der Lebenswissenschaften unterbringen, können wir"
  },
  AvgDialog_60344_Content_13 = {
    Text = "Brauchen Sie eine Mitfahrgelegenheit, Miss Ramona?"
  },
  AvgDialog_60344_Content_14 = {Text = "!!!"},
  AvgDialog_60344_Content_15 = {Text = "Vorsicht!"},
  AvgDialog_60344_Content_16 = {
    Text = "Ramona hebt ihr Schwert und hält es vor sich"
  },
  AvgDialog_60344_Content_17 = {
    Text = "Hinter ihr blickt Sylvia mit zusammengekniffenen Augen, während sie den geschwächten Czort beschützt."
  },
  AvgDialog_60344_Content_18 = {
    Text = "Eilige Schritte ertönten, als hätten sie hier lange auf der Lauer gelegen"
  },
  AvgDialog_60344_Content_19 = {
    Text = "Am Ende des schmalen Korridors steht eine dichte Menge von Agenten in Ausschussuniform, die ihren Weg blockieren"
  },
  AvgDialog_60344_Content_2 = {
    Text = "Im langen Korridor ist niemand zu sehen. Schwere Atem- und Schritte hallen wider"
  },
  AvgDialog_60344_Content_20 = {
    Text = "Der einäugige Mann geht zur Menge und streichelt sanft die zweiköpfige, haarlose Katze auf seiner Schulter"
  },
  AvgDialog_60344_Content_21 = {
    Text = "Es ist... du..."
  },
  AvgDialog_60344_Content_22 = {
    Text = "Als er das Gesicht vor sich sah, spannte sich Herlet sofort an"
  },
  AvgDialog_60344_Content_23 = {
    Text = "Herbert... du Bastard..."
  },
  AvgDialog_60344_Content_24 = {
    Text = "Professor Crowley behandelte dich wie sein eigenes Kind, doch du hast ihn getötet und seine akademischen Leistungen gestohlen... Selbst jetzt, wie kannst du es wagen, dein Gesicht zu zeigen und zurückzukehren..."
  },
  AvgDialog_60344_Content_25 = {
    Text = "Pssst, Klassenkamerad czort... oh nein, ich sollte dich Dekan czort nennen"
  },
  AvgDialog_60344_Content_26 = {
    Text = "Nach meinem Weggang ist der Posten des Direktors natürlich für dich bestimmt"
  },
  AvgDialog_60344_Content_27 = {
    Text = "Ich würde gerne mit dir über alte Zeiten plaudern, aber ich habe heute noch andere Aufgaben"
  },
  AvgDialog_60344_Content_28 = {
    Text = "Sein Blick richtete sich auf Ramona"
  },
  AvgDialog_60344_Content_29 = {
    Text = "Es ist lange her, Miss Ramona. Ich habe dich wirklich sehr vermisst."
  },
  AvgDialog_60344_Content_3 = {
    Text = "Huh... Dekan czort, halte durch, wir sind fast da"
  },
  AvgDialog_60344_Content_30 = {
    Text = "Aber wir haben uns nur ein paar Mal getroffen, nicht so vertraut"
  },
  AvgDialog_60344_Content_31 = {
    Text = "Diese Zeit? Nein, nein"
  },
  AvgDialog_60344_Content_32 = {
    Text = "Herbert hob seinen Blick, sein Blick ging über Czort und Ramona und ließ schließlich in die dunkle Leere wandern, als würde er an einen Ort starren, der so weit entfernt und unerreichbar war."
  },
  AvgDialog_60344_Content_33 = {
    Text = "Ich erinnere mich, dass ich dich das erste Mal gesehen habe, scheint es in diesem Durchgang gewesen zu sein"
  },
  AvgDialog_60344_Content_34 = {
    Text = "Damals warst du noch... so klein"
  },
  AvgDialog_60344_Content_35 = {
    Text = "Herbert streckte die Hände aus und zeigte die Länge einer haarlosen Katze"
  },
  AvgDialog_60344_Content_36 = {
    Text = "Was meinst du...?"
  },
  AvgDialog_60344_Content_37 = {
    Text = "Meine Schöpfung. Mein Kind"
  },
  AvgDialog_60344_Content_38 = {
    Text = "Helot ist ein gescheitertes Produkt, und diese schwachen, ausländischen Zwillinge sind nicht in der Lage, die große Mission zu tragen.\nIn meiner Zusammenarbeit mit der Tempel Licht Kirche bist du die perfekteste Kristallisation."
  },
  AvgDialog_60344_Content_39 = {
    Text = "Ich verstehe nicht..."
  },
  AvgDialog_60344_Content_4 = {
    Text = "Ramona, sei bitte vorsichtig mit der Wunde..."
  },
  AvgDialog_60344_Content_40 = {
    Text = "Verstehst du es immer noch nicht, Ramona?"
  },
  AvgDialog_60344_Content_41 = {
    Text = "Die Menschen, die dir wichtig sind, wurden erschreckt, verletzt und stehen unter dem Druck von Kontrollverlust und Tod... All diese Katastrophen, die Mythisch erlitten hat, sind wegen dir"
  },
  AvgDialog_60344_Content_42 = {
    Text = "Du... was sagst du?"
  },
  AvgDialog_60344_Content_43 = {
    Text = "Als Herbert das summende und zitternde Schwert in Ramonas Hand sah, lächelte er und machte zwei Schritte nach vorne."
  },
  AvgDialog_60344_Content_44 = {
    Text = "Vor vielen Jahren stahl Dexter, dieser Dieb, dich von uns"
  },
  AvgDialog_60344_Content_45 = {
    Text = "Dieser Tag kam spät, aber das macht nichts – er kam genau zur richtigen Zeit"
  },
  AvgDialog_60344_Content_46 = {
    Text = "Du bist ein wertvolles Zwilling, die perfekte Schöpfung der Lampe"
  },
  AvgDialog_60344_Content_47 = {
    Text = "Wir sind gekommen, um dich zurückzubringen."
  },
  AvgDialog_60344_Content_48 = {
    Text = "So, komm mit mir, Ramona."
  },
  AvgDialog_60344_Content_49 = {
    Text = "Ich versichere Ihnen, solange Sie ruhig mit mir gehen, werden alle Störungen an Mythag aufhören."
  },
  AvgDialog_60344_Content_5 = {
    Text = "Sie holte ein Taschentuch heraus und wischte vorsichtig das Blut von Ramonas Arm."
  },
  AvgDialog_60344_Content_50 = {
    Text = "Ramona, du..."
  },
  AvgDialog_60344_Content_51 = {
    Text = "Siehst du mich als so einen Dummkopf, Herbert?"
  },
  AvgDialog_60344_Content_52 = {
    Text = "Das ist Mythag. Egal, welches Ziel du hast, wir werden nicht zulassen, dass du es erreichst."
  },
  AvgDialog_60344_Content_53 = {
    Text = "Als du siehst, wie Ramona ihr schlankes Schwert hebt, bewegt Herbert leicht seinen Finger."
  },
  AvgDialog_60344_Content_54 = {
    Text = "Natürlich bist du eine intelligente Person, Ramona."
  },
  AvgDialog_60344_Content_55 = {
    Text = "Du musst zwei Damen eskortieren, die nicht in der Lage sind, sich selbst zu verteidigen, also hast du diese wenig bekannte Route gewählt."
  },
  AvgDialog_60344_Content_56 = {
    Text = "Ich vertraue vollkommen auf deine Fähigkeit, durchzubrechen. Wenn du allein gekommen wärst, hätte ich dich nicht aufhalten können."
  },
  AvgDialog_60344_Content_57 = {
    Text = "Aber schau zurück auf deine respektierten Mentoren, Czort Dekan und Lehrerin Silvia, Ramona."
  },
  AvgDialog_60344_Content_58 = {
    Text = "Ramona musterte die Ausschuss-Agenten, die sie misstrauisch beäugten, das Schwert fest an ihrer Brust."
  },
  AvgDialog_60344_Content_59 = {
    Text = "Die Sicherheit von Mythag hat oberste Priorität. Tu das Richtige, Ramona."
  },
  AvgDialog_60344_Content_6 = {
    Text = "Ah... Entschuldigung."
  },
  AvgDialog_60344_Content_60 = {
    Text = "Czorts Worte flüsterten in Ramonas Ohr. Sie hielt inne, ohne zu nicken."
  },
  AvgDialog_60344_Content_61 = {
    Text = "Nach einem Moment sah sie auf und schaute Herbert an."
  },
  AvgDialog_60344_Content_62 = {
    Text = "Ich verspreche es dir..."
  },
  AvgDialog_60344_Content_63 = {Text = "Ramona!"},
  AvgDialog_60344_Content_64 = {
    Text = "Aber, ich habe eine Bedingung."
  },
  AvgDialog_60344_Content_65 = {
    Text = "Bitte sprechen Sie."
  },
  AvgDialog_60344_Content_66 = {
    Text = "Lass deine Männer den Durchgang räumen. Sobald Czort Dekan und Lehrerin Silvie weit genug entfernt sind, werde ich mit dir gehen."
  },
  AvgDialog_60344_Content_67 = {
    Text = "Ah, natürlich, kein Problem—"
  },
  AvgDialog_60344_Content_68 = {
    Text = "Er winkte. Unter seiner Anleitung machten die Agenten des Ausschusses Platz."
  },
  AvgDialog_60344_Content_69 = {
    Text = "Ramona, ihr Ziel ist es, dich mitzunehmen; du darfst nicht mit ihnen gehen!"
  },
  AvgDialog_60344_Content_7 = {
    Text = "Gerade als ich gegen diese Leute vom Ausschuss kämpfte, war ich kurz unaufmerksam"
  },
  AvgDialog_60344_Content_70 = {
    Text = "Mach dir keine Sorgen, Dean Czort. Ich bin ihnen wichtig, also werden sie mir nichts antun."
  },
  AvgDialog_60344_Content_71 = {Text = "Aber..."},
  AvgDialog_60344_Content_72 = {
    Text = "Dean Czort, lass uns gehen."
  },
  AvgDialog_60344_Content_73 = {
    Text = "Ramona hat recht. Herbert wird ihr nichts tun können."
  },
  AvgDialog_60344_Content_74 = {
    Text = "Glaube ihr."
  },
  AvgDialog_60344_Content_75 = {
    Text = "Aus ihren lächelnden Augen verstand Czort ihre Bedeutung. Sie nickte."
  },
  AvgDialog_60344_Content_76 = {
    Text = "Die Agenten des Ausschusses traten zur Seite, wodurch ihre ursprünglich intakte Formation chaotisch wurde. Eine klare Lücke erschien in der Umzingelung."
  },
  AvgDialog_60344_Content_77 = {
    Text = "Der Fokus der sich bewegenden Agenten verlagerte sich allmählich auf die Veränderungen in der Formation, während sie Ramonas jede Bewegung nicht mehr so aufmerksam verfolgten."
  },
  AvgDialog_60344_Content_78 = {Text = "Ah!!"},
  AvgDialog_60344_Content_79 = {
    Text = "Die Schreie der beiden Agenten lenkten die Aufmerksamkeit aller auf sich."
  },
  AvgDialog_60344_Content_8 = {
    Text = "Hat die Unruhe des Schwarzen Pools dich unvermeidlich betroffen, oder?"
  },
  AvgDialog_60344_Content_80 = {
    Text = "Während die Wachsamkeit des Ausschusses zu schwinden begann, beseitigte Ramona swift die beiden Agenten, die sie mit ihrem Schwert kontrollierten."
  },
  AvgDialog_60344_Content_81 = {
    Text = "(Es tut mir leid, Czort Dean, Professor Sylvia. Ich kann Mythag nicht in Gefahr bringen.)"
  },
  AvgDialog_60344_Content_82 = {
    Text = "(Ich werde andere Erwachte bringen, um dich zu retten. Bald!)"
  },
  AvgDialog_60344_Content_83 = {
    Text = "Ramona hatte keine Zeit, diese Worte zu sagen. Das war ihre einzige Chance; sie floh durch die plötzlich auftauchende Öffnung."
  },
  AvgDialog_60344_Content_84 = {
    Text = "Einige Agenten reagierten kaum, aber sie konnten Ramonas Schwert nicht standhalten. Czort und Silvia tauschten einen erleichterten Blick aus, ihre Gesichter zeigten ein Gefühl der Erleichterung."
  },
  AvgDialog_60344_Content_85 = {
    Text = "Herbert erhaschte ihre Ausdrücke im Augenwinkel, lächelte und hob seine Hand zu einem sanften Winken."
  },
  AvgDialog_60344_Content_86 = {
    Text = "Wir warten hier auf dich, o Höchster Wille..."
  },
  AvgDialog_60344_Content_87 = {
    Text = "Für deinen Abstieg, segne uns und bestrafe die Respektlosen..."
  },
  AvgDialog_60344_Content_88 = {
    Text = "Eine seltsame Silbe driftete aus der Menge. In dem Moment, als sie Ramonas Ohren erreichte, schnürte sich ihr Inneres zusammen, als hätte ein unsichtbares Seil sie fest umschlungen und alle ihre Kraft ausgesogen."
  },
  AvgDialog_60344_Content_89 = {
    Text = "Unvorbereitet fällt sie zu Boden, ihr dünnes Schwert rollt weg und stoppt in der Nähe mit einem metallischen Klirren.\nRamona streckt die Hand aus, kann es jedoch nicht ganz fassen."
  },
  AvgDialog_60344_Content_9 = {
    Text = "Nur ein kleines bisschen."
  },
  AvgDialog_60344_Content_90 = {
    Text = "Das... das ist..."
  },
  AvgDialog_60344_Content_91 = {
    Text = "Selbst die billigsten Laternen-Relikte hinterlassen eine Spur im Körper. Besonders du"
  },
  AvgDialog_60344_Content_92 = {
    Text = "Du musst einen Weg finden, um zu entkommen. Ich warte darauf, dass die Tempel-Licht-Kirche das Siegel in dir aktiviert. Das wird Zeit in Anspruch nehmen."
  },
  AvgDialog_60344_Content_93 = {
    Text = "Wenn wir zu Gewalt greifen und dich verletzen, oder wenn du entkommen kannst, wäre das kein gutes Ergebnis."
  },
  AvgDialog_60344_Content_94 = {
    Text = "Du... hast immer gewusst, dass ich entkommen würde..."
  },
  AvgDialog_60344_Content_95 = {
    Text = "Ich habe nie gedacht, dass du so einfach aufgeben würdest. Du bist nicht so töricht."
  },
  AvgDialog_60344_Content_96 = {
    Text = "Herbert ging zu Ramona, hob das Rapier auf und spielte damit, während er seufzte."
  },
  AvgDialog_60344_Content_97 = {
    Text = "Wenn du dich von Anfang an entschieden hättest, zu widerstehen, hätten wir dich vielleicht wirklich nicht aufhalten können. Aber du willst alles—mehr Informationen, zu geringeren Kosten..."
  },
  AvgDialog_60344_Content_98 = {
    Text = "Ich kenne dich, Ramona. Du strebst nach Perfektion. Selbst in solch desolaten Verhältnissen möchtest du Mythag und die Hüter so gut wie möglich helfen."
  },
  AvgDialog_60344_Content_99 = {
    Text = "Doch wenn die Informationen asymmetrisch sind, desto mehr du nach Perfektion strebst, desto mehr Fehler machst du wahrscheinlich. Stimmst du nicht zu?"
  },
  AvgDialog_60346_Content_1 = {
    Text = "Überlebensmittel"
  },
  AvgDialog_60346_Content_10 = {Text = "Thais..."},
  AvgDialog_60346_Content_11 = {
    Text = "Ich bin hier."
  },
  AvgDialog_60346_Content_12 = {
    Text = "Thais, wirst du mich besuchen?"
  },
  AvgDialog_60346_Content_13 = {
    Text = "Es wird einen Preis geben."
  },
  AvgDialog_60346_Content_14 = {
    Text = "Ich bin bereit zu erdulden!"
  },
  AvgDialog_60346_Content_15 = {Text = "Hmm—"},
  AvgDialog_60346_Content_16 = {
    Text = "Der intensive Schmerz bringt dich zu deinen Knien. Ein schwach leuchtender Samen erscheint aus deinem Bauch und schwebt über dem schwarzen Pool."
  },
  AvgDialog_60346_Content_17 = {
    Text = "Ein Samen fällt in den schwarzen Pool und verursacht Wellen. Während sich die Wellen ausbreiten, verändert sich die Szene im schwarzen Pool. Vertraute Dünen erscheinen vor dir."
  },
  AvgDialog_60346_Content_18 = {
    Text = "Eine süße Brise rührt den endlosen gelben Sand auf, der sich vor dir sammelt."
  },
  AvgDialog_60346_Content_19 = {
    Text = "Bald erscheint eine humanoide Gestalt vor Ihnen, die diesen Samen als Kern und Sand als Fleisch verwendet"
  },
  AvgDialog_60346_Content_2 = {
    Text = "Die Lichter des unterirdischen Forschungslabors werden fern und verwandeln sich in schwache Glühwürmchen."
  },
  AvgDialog_60346_Content_20 = {Text = "Thais...?"},
  AvgDialog_60346_Content_21 = {
    Text = "Seit sie während des Zusammenbruchs des Mutterbaums in der Flut des Heiligen Flusses verschwunden ist, kennt niemand ihren Aufenthaltsort."
  },
  AvgDialog_60346_Content_22 = {
    Text = [[
Dies ist... der Schwarze Pool, wo die schwarze Flut aus dem Erdkern hervorsprudelt...
Nur sie kann hier die ewige und tiefe Dunkelheit ertragen.]]
  },
  AvgDialog_60346_Content_23 = {
    Text = "Thais bewegte sich plötzlich näher, ihre vollen Lippen, ihre mehrdeutigen Augen und ihr stilles Lächeln, alles wie Remouahe."
  },
  AvgDialog_60346_Content_24 = {
    Text = "Antworte mir, Hüter. Warum hast du mich hier geweckt, bevor wir die neue Welt erreichen?"
  },
  AvgDialog_60346_Content_25 = {
    Text = "Sie erzählen Alistairs Anweisungen der Reihe nach."
  },
  AvgDialog_60346_Content_26 = {
    Text = "Thais' Gesichtsausdruck wechselte von Verwirrung zu Panik und schließlich zu Terror."
  },
  AvgDialog_60346_Content_27 = {
    Text = "Nein... das ist kein gangbarer Weg..."
  },
  AvgDialog_60346_Content_28 = {
    Text = "Er wird schließlich erwachen. Niemand kann Ihn besiegen..."
  },
  AvgDialog_60346_Content_29 = {
    Text = "Aber ich habe meine Entscheidung getroffen."
  },
  AvgDialog_60346_Content_3 = {
    Text = "Der schwarze Pool blubbert unter dir. Tawils schwaches Licht flackert in der Ferne, wie weiße Farbe, die in Aequor tropft und bald verschwindet."
  },
  AvgDialog_60346_Content_30 = {
    Text = "Thais ließ einen sanften Seufzer hören."
  },
  AvgDialog_60346_Content_31 = {
    Text = "Gewähre mir die Autorität über die Essenz des Verlangens."
  },
  AvgDialog_60346_Content_32 = {
    Text = "Du machst einen Schritt nach vorne und starrst Thais direkt in die Augen."
  },
  AvgDialog_60346_Content_33 = {
    Text = "Oh, Kleines..."
  },
  AvgDialog_60346_Content_34 = {
    Text = "Ich habe dir bereits meine Autorität anvertraut.\nIch habe dir nichts vorenthalten."
  },
  AvgDialog_60346_Content_35 = {
    Text = "Der Samen, den ich in dir eingepflanzt habe... meine Autorität haftet daran."
  },
  AvgDialog_60346_Content_36 = {
    Text = [[
Aber es wurde gewaltsam von dir weggerissen.
Es ist voller Angst und Wut...]]
  },
  AvgDialog_60346_Content_37 = {
    Text = "Um es neu zu kultivieren, musst du es zuerst beruhigen..."
  },
  AvgDialog_60346_Content_4 = {
    Text = "Als du tiefer vordrangst, wurde die Unruhe des Schwarzen Beckens zunehmend offensichtlich."
  },
  AvgDialog_60346_Content_5 = {
    Text = "Tawil jetzt zu finden, würde Juliette alarmieren. Sie muss als letztes gerettet werden."
  },
  AvgDialog_60346_Content_6 = {
    Text = "Wo soll ich nach den anderen beiden Essenzen suchen...?"
  },
  AvgDialog_60346_Content_7 = {
    Text = "Dein Lehrer weiß viele Dinge. Er hat dir das nicht gesagt; vielleicht solltest du es selbst wissen."
  },
  AvgDialog_60346_Content_8 = {
    Text = "Rufe sie zurück, nenne ihre Namen; sie könnten auf dich reagieren."
  },
  AvgDialog_60346_Content_9 = {
    Text = "Ein lächelndes Gesicht tritt in den Sinn; sie schritt einmal durch den Sand in einem entscheidenden Moment, als du den Überresten des heiligen Baumes gegenüberstandest und alle Hindernisse für dich beseitigte."
  },
  AvgDialog_60347_Content_1 = {
    Text = "Dexterianische Wendung"
  },
  AvgDialog_60347_Content_10 = {
    Text = "Du fühlst es intensiv. Thais' überwältigende Macht richtet Chaos in deinem Körper an und lässt dich völlig im Dunkeln darüber, wie du sie absorbieren kannst. Selbst normale Bewegungen sind stark betroffen."
  },
  AvgDialog_60347_Content_11 = {
    Text = "Ich habe keine Ahnung, wie lange das hier weitergeht. Ramona ist immer noch im Schwarzen Pool gefangen. Ich muss mich beeilen..."
  },
  AvgDialog_60347_Content_12 = {
    Text = "In so kaltem Wetter kann das Liegen im Schwarzen Pool dich krank machen."
  },
  AvgDialog_60347_Content_13 = {
    Text = "Professor Dexter?"
  },
  AvgDialog_60347_Content_14 = {
    Text = "Professor Dexter?!"
  },
  AvgDialog_60347_Content_15 = {
    Text = "Eine vertraute Stimme, eine vertraute Gestalt."
  },
  AvgDialog_60347_Content_16 = {
    Text = "Polierte Hände ruhen auf einem Stock, sie treten vor dich."
  },
  AvgDialog_60347_Content_17 = {
    Text = "Professor Dexter, es ist extrem gefährlich im Schwarzen Pool. Bitte verlasse sofort!"
  },
  AvgDialog_60347_Content_18 = {
    Text = "Mach dir keine Sorgen um Ramona. Ich werde sie bald retten..."
  },
  AvgDialog_60347_Content_19 = {
    Text = "Du sorgst dich immer noch um Ramona wie immer, Hüter."
  },
  AvgDialog_60347_Content_2 = {
    Text = "Die Dünen... sind verschwunden..."
  },
  AvgDialog_60347_Content_20 = {
    Text = "Danke für deine Sorge. Ich habe gerade Ramona getroffen."
  },
  AvgDialog_60347_Content_21 = {
    Text = "Du bereits...?"
  },
  AvgDialog_60347_Content_22 = {
    Text = "Das ist korrekt. Sie fühlt sich jetzt äußerst... wohl."
  },
  AvgDialog_60347_Content_23 = {
    Text = "Sie hat lange nicht mehr so fest geschlafen. Ich denke, sie brauchte diesen Schlaf wirklich."
  },
  AvgDialog_60347_Content_24 = {
    Text = "Sie... ist jetzt in großer Gefahr... warum hast du nicht..."
  },
  AvgDialog_60347_Content_25 = {
    Text = "Finde einen Weg, um sie zu retten? Oh, richtig, warum... Dexter liebt seine Tochter so sehr, dass er derjenige sein sollte, der einen Weg findet, um sie zu retten."
  },
  AvgDialog_60347_Content_26 = {
    Text = "Selbst wenn es mir mein Leben kosten sollte, wird es sich lohnen..."
  },
  AvgDialog_60347_Content_27 = {
    Text = "Dexter schaut auf, lässt ein leises Seufzen aus und scheint in Gedanken verloren."
  },
  AvgDialog_60347_Content_28 = {
    Text = "Das ist auch eine Wahl, eine Richtung der Geschichte"
  },
  AvgDialog_60347_Content_29 = {
    Text = "Aber wenn wir sie wirklich retten, wird die Geschichte nicht mehr so spannend sein, oder?"
  },
  AvgDialog_60347_Content_3 = {
    Text = "Ich habe von der Geschichte zwischen dir und Thais gehört."
  },
  AvgDialog_60347_Content_30 = {
    Text = "Sorge, Sehnsucht, Trauer... alles verschwand aus Dexters Gesicht"
  },
  AvgDialog_60347_Content_31 = {
    Text = "Du siehst, wie er dir ein perfektes, aber kaltes Lächeln zeigt"
  },
  AvgDialog_60347_Content_32 = {
    Text = "Professor Dexter würde so etwas nie sagen... Wer sind Sie wirklich?!"
  },
  AvgDialog_60347_Content_33 = {
    Text = "Er kam auf dich zu, seine vertrauten Augen mit einem fremden Lächeln"
  },
  AvgDialog_60347_Content_34 = {
    Text = "Ein schwarzer Rauch stieg von ihm auf und hüllte ihn langsam ein"
  },
  AvgDialog_60347_Content_35 = {
    Text = "Ja, wer bin ich eigentlich"
  },
  AvgDialog_60347_Content_36 = {
    Text = "Großzügiger Aktionär. Besorgter Vater. Berühmter Playboy. Beliebter Misaq-Professor."
  },
  AvgDialog_60347_Content_37 = {
    Text = "Ein engagierter Schauspieler. Zwanzig Jahre lang spielte er dieselbe Rolle, ohne auch nur einen Hauch von Faulheit, alles für die perfekte Wendung in der Geschichte."
  },
  AvgDialog_60347_Content_38 = {Text = "Jetzt"},
  AvgDialog_60347_Content_39 = {
    Text = "Meine lieben Zuschauer, schenkt mir euren lautesten Applaus"
  },
  AvgDialog_60347_Content_4 = {
    Text = "Darf ich unterbrechen, aber jetzt ist nicht die Zeit, von diesen Emotionen eingenommen zu werden."
  },
  AvgDialog_60347_Content_40 = {
    Text = "Der schwarze Nebel umgab sie wie ein Applaus"
  },
  AvgDialog_60347_Content_41 = {
    Text = "Vor dir erscheint ein Gesicht, das du schon einmal gesehen hast und das dir unzählige Albträume beschert hat"
  },
  AvgDialog_60347_Content_42 = {
    Text = "Das gesichtslose Grinsen genießt gierig deine Bestürzung und Angst"
  },
  AvgDialog_60347_Content_43 = {
    Text = "Du bist... N!"
  },
  AvgDialog_60347_Content_44 = {
    Text = "Ein Titel, für meine unzähligen Inkarnationen ist das eine Beleidigung... aber nenn mich, wie du willst"
  },
  AvgDialog_60347_Content_45 = {
    Text = "Was hast du mit Professor Dexter gemacht!"
  },
  AvgDialog_60347_Content_46 = {
    Text = "Professor Dexter? Wer ist Professor Dexter?"
  },
  AvgDialog_60347_Content_47 = {
    Text = "Geheimnisträger, kennst du und Ramona wirklich Dexter?"
  },
  AvgDialog_60347_Content_48 = {
    Text = "Was meinst du... wie könnten wir... etwa?!"
  },
  AvgDialog_60347_Content_49 = {
    Text = "Du erinnerst dich an die Worte von N. Seit Jahren spielt er dieselbe Rolle..."
  },
  AvgDialog_60347_Content_5 = {
    Text = "Sie und ich sind nicht..."
  },
  AvgDialog_60347_Content_50 = {
    Text = "Die Pupillen ziehen sich scharf zusammen. Du hebst plötzlich den Kopf und siehst auf N's gesichtslosen Körper"
  },
  AvgDialog_60347_Content_51 = {
    Text = "Sehr gut, Geheimnishüter. Genau dieser Ausdruck!"
  },
  AvgDialog_60347_Content_52 = {
    Text = "Beweg dich nicht, bleib so. Ja, genau... Lass mich dich so in Erinnerung behalten"
  },
  AvgDialog_60347_Content_53 = {
    Text = "Leider hatte Ramona, als sie davon erfuhr, noch nicht erwacht, und ich sah nur ihre Tränen."
  },
  AvgDialog_60347_Content_54 = {
    Text = "Ich stelle mir vor, der Ausdruck in ihrem Herzen in diesem Moment muss sogar wundervoller gewesen sein als deiner."
  },
  AvgDialog_60347_Content_55 = {
    Text = "Ns Körper zitterte leicht, als würde er mit starkem Lachen kämpfen"
  },
  AvgDialog_60347_Content_56 = {
    Text = "Er beugte sich vor, kam dir nahe und betrachtete dich genau"
  },
  AvgDialog_60347_Content_57 = {
    Text = "Du... warum kontrollierst du Professor Dexter?"
  },
  AvgDialog_60347_Content_58 = {
    Text = "Kontrolle? Oh nein. Kontrolle ist eine minderwertige Unterhaltung"
  },
  AvgDialog_60347_Content_59 = {
    Text = "Ein guter Schauspieler muss spielen und werden"
  },
  AvgDialog_60347_Content_6 = {
    Text = "Es ist nicht nötig zu erklären. Was auch immer die Methode ist, die Wiedererlangung der Autorität ist das Wichtigste."
  },
  AvgDialog_60347_Content_60 = {
    Text = "Er beugte sich zu deinem Ohr und flüsterte dir ein großes Geheimnis zu—"
  },
  AvgDialog_60347_Content_61 = {
    Text = "Dexter starb vor langer Zeit, am Tag, an dem er Ramona rettete."
  },
  AvgDialog_60347_Content_62 = {
    Text = "In all diesen Jahren, du und Ramona, ihr habt sicher eine gute Zeit mit mir gehabt, oder?"
  },
  AvgDialog_60347_Content_63 = {
    Text = "Sein Gesicht war dir zugewandt. Auf diesem leeren Gesicht schienen die arroganten Züge deutlich sichtbar"
  },
  AvgDialog_60347_Content_64 = {
    Text = "Er beugt sich hinein, um jede Expression und jedes unkontrollierbare Zittern zu memorieren."
  },
  AvgDialog_60347_Content_65 = {
    Text = "Ein charmanter Playboy, ein liebevoller Vater, solche Rollen interessieren mich eigentlich nicht"
  },
  AvgDialog_60347_Content_66 = {
    Text = "Ich interessiere mich nur für sie... meine „Tochter“. Tawils Zwillingsrelikt, Ramona"
  },
  AvgDialog_60347_Content_67 = {
    Text = "N lächelte in Richtung der Mitte der schwarzen Pfütze, in Richtung Tawil"
  },
  AvgDialog_60347_Content_68 = {
    Text = "Du... warum hast du ihn getötet"
  },
  AvgDialog_60347_Content_69 = {
    Text = "Dein Missverständnis ist so traurig, Geheimnishüter"
  },
  AvgDialog_60347_Content_7 = {
    Text = "Ich... egal, ich bin zu faul, darüber zu sprechen. Lass uns zuerst... hiss!"
  },
  AvgDialog_60347_Content_70 = {
    Text = "Der Zwillingsplan der Laterne ist nichts, womit ein schwacher Playboy leicht fertig wird. Aber er konnte das Baby stehlen"
  },
  AvgDialog_60347_Content_71 = {
    Text = "Als er mich sah, leuchteten seine Augen wie die eines Erlösers... Ha"
  },
  AvgDialog_60347_Content_72 = {
    Text = "N erinnerte sich an die Geschichte und lächelte erfreut"
  },
  AvgDialog_60347_Content_73 = {
    Text = "Er machte mir ein Angebot. Kannst du das glauben? Ein sterblicher Mensch, der mir ein Angebot macht"
  },
  AvgDialog_60347_Content_74 = {
    Text = "Er hat mir alles gegeben. Sein Vermögen, seinen Status, seine Tochter"
  },
  AvgDialog_60347_Content_75 = {
    Text = "Er ließ mich ihn spielen, den Vater seiner Tochter"
  },
  AvgDialog_60347_Content_76 = {
    Text = "Er starb, während er das Baby hielt. Im Sterben murmelte er immer wieder, dass der Vater sie gut beschützen würde"
  },
  AvgDialog_60347_Content_77 = {
    Text = "Der Verräter von Missaga... bist du es?"
  },
  AvgDialog_60347_Content_78 = {
    Text = "N zuckt gleichgültig mit den Schultern, als er deine verwirrten und wütenden Augen sieht"
  },
  AvgDialog_60347_Content_79 = {
    Text = "Ich oder nicht ich, spielt das eine Rolle? Schwer zu glauben, dass du dir darüber noch Gedanken machst"
  },
  AvgDialog_60347_Content_8 = {
    Text = "Du bist dabei, aufzustehen, als ein stechender Schmerz in dir dich keuchen lässt."
  },
  AvgDialog_60347_Content_80 = {
    Text = "Als Dexter zu spielen, ermöglichte eine enge Nähe zu Mythag und bot eine bequeme Gelegenheit."
  },
  AvgDialog_60347_Content_81 = {
    Text = "Dieser Ort ist der interessanteste Vergnügungspark der Welt"
  },
  AvgDialog_60347_Content_82 = {
    Text = "Ich wollte sehen, wie ihr ausseht, als ich euch täuschte. Schau dir Tawils gescheiterte Pläne an und ihre gescheiterte Haltung"
  },
  AvgDialog_60347_Content_83 = {
    Text = "Natürlich, und du"
  },
  AvgDialog_60347_Content_84 = {
    Text = "N schnippte mit seinen Fingern. Das Wasser des Schwarzen Pools hob sich leicht und bildete eine grausame Bühne vor deinen Augen."
  },
  AvgDialog_60347_Content_85 = {
    Text = "Er sah dich an, leckte sich die Lippen, wie ein unschuldiges Kind, das ein Spielzeug zerstören will"
  },
  AvgDialog_60347_Content_86 = {
    Text = "Thais hat dir ihren Samen geschenkt, sie glaubte wirklich, du könntest sie am Leben halten... ha, diese verrückte Frau"
  },
  AvgDialog_60347_Content_87 = {
    Text = "Schade, sie vertraute der falschen Person. Den Zepter des Verlangens, ich werde ihn nehmen."
  },
  AvgDialog_60347_Content_88 = {
    Text = "Lass mich sehen, welches Gesicht du machst, wenn die Hoffnung erlischt"
  },
  AvgDialog_60347_Content_9 = {
    Text = "Die Kraft der drei Essenzen ist gewaltig. Anpassungen werden nicht schnell geschehen. Du musst eine Weile warten."
  },
  AvgDialog_60348_Content_1 = {
    Text = "Das ist der Eingang zum Schwarzen Pool."
  },
  AvgDialog_60348_Content_10 = {
    Text = "Du nimmst einen tiefen Atemzug und überlegst dir eine Strategie."
  },
  AvgDialog_60348_Content_11 = {Text = "Alistair"},
  AvgDialog_60348_Content_12 = {
    Text = "Bevor du Juliette triffst, untersuche die Situation im Schwarzen Pool, stabilisiere sie so gut wie möglich und stelle die Macht wieder her."
  },
  AvgDialog_60348_Content_13 = {
    Text = "Beide Angelegenheiten erfordern die Hilfe von Lehrer Alistair. Lass uns ihn zuerst finden."
  },
  AvgDialog_60348_Content_14 = {Text = "Hüter!"},
  AvgDialog_60348_Content_15 = {
    Text = "Alva macht eine Geste für Stille."
  },
  AvgDialog_60348_Content_16 = {
    Text = "In die Richtung, die sie zeigte, steht ein Mitglied des Ausschusses am Eingang von Black Pool."
  },
  AvgDialog_60348_Content_17 = {
    Text = "Es scheint, dass der Weg vor uns nicht so einfach sein wird... Bereite dich auf einen Angriff vor."
  },
  AvgDialog_60348_Content_2 = {
    Text = "Hameln, weißt du, wo sich Juliette gerade befindet?"
  },
  AvgDialog_60348_Content_3 = {
    Text = "Sie müssen Tawils Macht nutzen, um die Zwilling Heiligen Söhne zu beschwören.\nDie Vorbereitungen für das Ritual werden wahrscheinlich dort stattfinden, wo Tawils Macht am besten zugänglich ist."
  },
  AvgDialog_60348_Content_4 = {
    Text = "In der Nähe von Tawil, ich verstehe. Lass uns jetzt gehen..."
  },
  AvgDialog_60348_Content_5 = {
    Text = "Noch nicht."
  },
  AvgDialog_60348_Content_6 = {
    Text = "Juliette ist mit all ihrer Kraft nach Mythag gekommen. Selbst ich kann ihre Fähigkeiten nicht vollständig begreifen."
  },
  AvgDialog_60348_Content_7 = {
    Text = "Deine Kraft ist erheblich geschwächt worden. Ein schwacher Musiker kann keine kraftvolle Musik spielen."
  },
  AvgDialog_60348_Content_8 = {
    Text = "Wenn Sie scheitern, wird die Bühne von Mythag aufhören zu existieren."
  },
  AvgDialog_60348_Content_9 = {
    Text = "Du hast recht, ich habe keine zweite Chance."
  },
  AvgDialog_60349_Content_1 = {
    Text = "Als das Licht des Silbernen Schlüssels schwächer wurde, fiel N zu Boden."
  },
  AvgDialog_60349_Content_10 = {
    Text = "Der schwarze Nebel formiert sich erneut vor dir. N schaut dich an und schüttelt bedauernd den Kopf."
  },
  AvgDialog_60349_Content_11 = {
    Text = "Frohe Zeiten enden immer zu schnell. Der Abschied eines guten Schauspielers hinterlässt wirklich ein Gefühl von Einsamkeit..."
  },
  AvgDialog_60349_Content_12 = {
    Text = "Jedoch sollte man als engagiertes Publikum die vergangenen Geschichten vergessen und ernsthaft dem Nächsten entgegenblicken."
  },
  AvgDialog_60349_Content_13 = {
    Text = "Ramona und Tawil, die aufregende Vorstellung steht kurz vor Beginn."
  },
  AvgDialog_60349_Content_14 = {
    Text = "Vorher hast du 30 Sekunden Zeit, deine Abschiedsworte zu sagen, Wächter {Male=Herr,Female=Frau}"
  },
  AvgDialog_60349_Content_15 = {
    Text = "N sprach, während er die Form der Rose in seinen Händen anpasste, als würde er ein letztes Abschiedsgeschenk für eine Beerdigung vorbereiten."
  },
  AvgDialog_60349_Content_16 = {
    Text = "Ich beanspruche die Autorität, Mythag zu retten, um die um mich herum zu retten... und alles in dieser Welt, einschließlich dir!"
  },
  AvgDialog_60349_Content_17 = {
    Text = "20 Sekunden."
  },
  AvgDialog_60349_Content_18 = {
    Text = "N brachte seine nicht vorhandene Nase nahe an die Rose, schnüffelte tief und ließ einen zufriedenen Seufzer hören."
  },
  AvgDialog_60349_Content_19 = {
    Text = "Zwanzig Jahre... Du bist seit zwanzig Jahren bei Mythag. Selbst wenn du alle anderen ignorierst, was ist mit Ramona?"
  },
  AvgDialog_60349_Content_2 = {
    Text = "Puh... Endlich..."
  },
  AvgDialog_60349_Content_20 = {
    Text = "Ich kann es nicht glauben, dass du überhaupt keine Gefühle für Ramona hast..."
  },
  AvgDialog_60349_Content_21 = {
    Text = "10 Sekunden."
  },
  AvgDialog_60349_Content_22 = {
    Text = "Er legte die Rose sanft auf deine Brust."
  },
  AvgDialog_60349_Content_23 = {
    Text = "Gerechtigkeit? Pflicht? Begierde? Emotionen?"
  },
  AvgDialog_60349_Content_24 = {
    Text = "Zahlreiche Worte, die die Menschheit antreiben, flitzen durch deinen Kopf. Keines davon ist für N geeignet."
  },
  AvgDialog_60349_Content_25 = {
    Text = "Was will er... Was verfolgt er..."
  },
  AvgDialog_60349_Content_26 = {
    Text = "Drei Sekunden."
  },
  AvgDialog_60349_Content_27 = {
    Text = "Er zupfte ein Rosenblatt, das sich in eine scharfe Klinge verwandelte, die an deinem Hals drückte."
  },
  AvgDialog_60349_Content_28 = {
    Text = "Tawil sagt mir, dass Er sich entscheidet zu beobachten. Er kümmert sich weder um Leben noch um Tod, sondern nur um sein eigenes Vergnügen."
  },
  AvgDialog_60349_Content_29 = {
    Text = "\"Die Klinge schnitt in deinen Hals. Du fühltest den scharfen Stich deutlich. Deine Augen schnellten auf.\""
  },
  AvgDialog_60349_Content_3 = {
    Text = "N, ich habe etwas zu sagen..."
  },
  AvgDialog_60349_Content_30 = {Text = "Langweilig"},
  AvgDialog_60349_Content_31 = {
    Text = "Langweilig!"
  },
  AvgDialog_60349_Content_32 = {Text = "Mmh-hmm?"},
  AvgDialog_60349_Content_33 = {
    Text = "Deine Wahl... ist extrem langweilig..."
  },
  AvgDialog_60349_Content_34 = {Text = "Oh?"},
  AvgDialog_60349_Content_35 = {
    Text = "\"Die Klinge schwebte an deinem Hals. N wartete.\""
  },
  AvgDialog_60349_Content_36 = {
    Text = "Die ultimative Katastrophe wird kommen... und niemand wird verschont bleiben..."
  },
  AvgDialog_60349_Content_37 = {
    Text = "Aber was, wenn jemand diese Katastrophe stoppen könnte?"
  },
  AvgDialog_60349_Content_38 = {
    Text = "Du... was sagst du?"
  },
  AvgDialog_60349_Content_39 = {
    Text = "Ich kann. Egal, was dieses Desaster ist, ich werde seine Ankunft aufhalten!"
  },
  AvgDialog_60349_Content_4 = {Text = "!!!"},
  AvgDialog_60349_Content_40 = {
    Text = "Erfolg oder Misserfolg... So oder so, es wird die interessanteste Show für euch sein."
  },
  AvgDialog_60349_Content_41 = {
    Text = "Hehehehe... du? Hahahaha!"
  },
  AvgDialog_60349_Content_42 = {
    Text = "N schien einen absolut urkomischen Witz gehört zu haben. Er hielt sich den Bauch und lachte unkontrolliert."
  },
  AvgDialog_60349_Content_43 = {
    Text = "Heiteres Lachen hallt ständig durch die leere Bühne des Schwarzen Beckens."
  },
  AvgDialog_60349_Content_44 = {
    Text = "Du weißt nicht einmal, worüber du redest!"
  },
  AvgDialog_60349_Content_45 = {
    Text = "Ich weiß es wirklich nicht. Aber das beeinflusst die Genauigkeit dieser Aussage nicht."
  },
  AvgDialog_60349_Content_46 = {
    Text = "N, du wusstest es die ganze Zeit. Du hattest nie die Absicht, mich zu töten."
  },
  AvgDialog_60349_Content_47 = {
    Text = "Gib mir dreißig Sekunden. Du willst nur hören, dass ich es sage, oder?"
  },
  AvgDialog_60349_Content_48 = {
    Text = "Nachdem einer langen Weile, hört N endlich auf zu lachen. Er nimmt einen tiefen Atemzug und schaut dich intensiv an."
  },
  AvgDialog_60349_Content_49 = {
    Text = "Es tut mir leid, die Beherrschung verloren zu haben..."
  },
  AvgDialog_60349_Content_5 = {
    Text = "Bevor du reagieren kannst, verwandelt sich der Körper am Boden in eine Wolke aus schwarzem Nebel und verschwindet."
  },
  AvgDialog_60349_Content_50 = {
    Text = "Du hast absolut recht, Hüter. Das ist der größte Spaß, den es in dieser Welt gibt."
  },
  AvgDialog_60349_Content_51 = {
    Text = "Er lächelte und reichte dir eine Rose."
  },
  AvgDialog_60349_Content_52 = {
    Text = "Was ist das...?"
  },
  AvgDialog_60349_Content_53 = {
    Text = "Du berührst unbewusst die Rose und fragst."
  },
  AvgDialog_60349_Content_54 = {
    Text = "Im Moment, in dem du die Blüte berührst, hallen unzählige Lacher gleichzeitig in deinen Ohren wider."
  },
  AvgDialog_60349_Content_55 = {
    Text = "Alle Arten von Lachen — grob, elegant, scharf und dumpf — verschmelzen zu einer chaotischen Clownarmee, die auf deinen Trommelfellen tanzt."
  },
  AvgDialog_60349_Content_56 = {
    Text = "Deine Gedanken kommen zum Stillstand, Schmerz sticht wie eine Klinge in deine Nerven."
  },
  AvgDialog_60349_Content_57 = {
    Text = "In dem intensiven, chaotischen, fast wahnsinnigen Lachen klingen Ns Worte weiterhin klar in deinem Kopf."
  },
  AvgDialog_60349_Content_58 = {
    Text = "Genieße den Zepter des Vergnügens in vollen Zügen."
  },
  AvgDialog_60349_Content_59 = {
    Text = "Ich werde still warten. Wenn dieses große Spiel beginnt, werde ich dir sicherlich aus dem Publikum mit dem wärmsten Applaus zujubeln."
  },
  AvgDialog_60349_Content_6 = {
    Text = "Das Ende, der Untergang des Helden."
  },
  AvgDialog_60349_Content_7 = {Text = "Bang—"},
  AvgDialog_60349_Content_8 = {
    Text = "Der heftige Schlag zerschmetterte fast deinen Körper."
  },
  AvgDialog_60349_Content_9 = {
    Text = "Die Wunden entlang des Weges, die schwere Last der Macht des Verlangens, der psychische Schock vom Schwarzen Pool – alles viel zu ertragen. Du brichst vor Schmerz zusammen und kannst dich nicht wieder erheben."
  },
  AvgDialog_60350_Content_1 = {
    Text = "Thais' Kraft scheint unerschöpflich. Der ständig zunehmende Druck lässt dich ersticken."
  },
  AvgDialog_60350_Content_10 = {
    Text = "Ich weiß nicht, Thais. Aber ich weiß eines: Ich werde nicht aufgeben."
  },
  AvgDialog_60350_Content_11 = {
    Text = "Ob du mir deine Macht geben möchtest, ist deine Wahl; ich werde dich nicht zwingen."
  },
  AvgDialog_60350_Content_12 = {
    Text = "Dies ist dein wertsamstes Samenkorn. Gib es demjenigen, der am ehesten von hier entkommen kann..."
  },
  AvgDialog_60350_Content_13 = {
    Text = "Ich werde hier niemals aufgeben. Egal was passiert, ich werde bis zum Ende gegen alles kämpfen, was es vernichten will..."
  },
  AvgDialog_60350_Content_14 = {
    Text = "Aber... warum?"
  },
  AvgDialog_60350_Content_15 = {
    Text = "Was könnte wichtiger sein, als am Leben zu bleiben?"
  },
  AvgDialog_60350_Content_16 = {
    Text = "Ich kann diese Welt, die Menschen um mich herum, die Erwachter oder dich... nicht aufgeben..."
  },
  AvgDialog_60350_Content_17 = {
    Text = "So wie du Alan nie aufgegeben hast."
  },
  AvgDialog_60350_Content_18 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_60350_Content_19 = {
    Text = "Seit der Explosion haben sich alle meine Erinnerungen um dich gedreht. Du bist mein Alles."
  },
  AvgDialog_60350_Content_2 = {
    Text = "Mein Nachwuchs, mein Leben, endlos... Du kannst mich nicht besiegen, Hüter."
  },
  AvgDialog_60350_Content_20 = {
    Text = "Ich verlor einst mein Leben. Zu wählen, zu sterben, um alles zu schützen, oder alles aufzugeben, um zu leben – so oder so, ich habe nur eine Wahl."
  },
  AvgDialog_60350_Content_21 = {
    Text = "Thais starrt lange schweigend in deine Augen."
  },
  AvgDialog_60350_Content_22 = {
    Text = "Ich kann zwischen Lügen und der Wahrheit unterscheiden... Du sprichst die Wahrheit, Hüter."
  },
  AvgDialog_60350_Content_23 = {
    Text = "Sieht so aus, als hätte ich der falschen Person vertraut. Du bist nicht derjenige, der mich in die neue Welt bringen kann..."
  },
  AvgDialog_60350_Content_24 = {
    Text = "Thais ließ einen Seufzer der Enttäuschung hören."
  },
  AvgDialog_60350_Content_25 = {
    Text = "Sie kam an deine Seite."
  },
  AvgDialog_60350_Content_26 = {
    Text = "Thais, du möchtest... mmph—"
  },
  AvgDialog_60350_Content_27 = {
    Text = "Ein warmes Objekt blockiert deinen Mund."
  },
  AvgDialog_60350_Content_28 = {
    Text = "Ein sphärisches Objekt tritt aus Thais' Mund hervor und gleitet langsam hinaus."
  },
  AvgDialog_60350_Content_29 = {
    Text = "Es ging durch deinen Mund, deinen Hals und deine Speiseröhre. Es verwandelte sich in eine Frühlingsbrise, die gegen jedes Organ und die Spitzen jedes Blutgefäßes in dir strich."
  },
  AvgDialog_60350_Content_3 = {
    Text = "Aufgeben, all deine Mühen sind vergeblich; hör auf, zu versuchen, Ihm zu widerstehen."
  },
  AvgDialog_60350_Content_30 = {
    Text = "Ich weiß nicht, wie lange es her ist. Thais ließ dich los und leckte sich leicht über die Lippen."
  },
  AvgDialog_60350_Content_31 = {Text = "Thais...?"},
  AvgDialog_60350_Content_32 = {
    Text = "„Gerade eben... Was war das...“"
  },
  AvgDialog_60350_Content_33 = {
    Text = "Du bist ein Lügner, ein Dummkopf, %player%. Du kannst es nicht besiegen. Du verdienst es nicht einmal, es anzusehen..."
  },
  AvgDialog_60350_Content_34 = {
    Text = "Aber du bist einfach so, was kann ich sonst noch tun?"
  },
  AvgDialog_60350_Content_35 = {
    Text = "Thais lässt einen sanften Seufzer hören. Ihr Atem streicht sanft über dein Gesicht, süß wie eine Frühlingsbrise."
  },
  AvgDialog_60350_Content_36 = {
    Text = "Dieser Samen hält die Macht, Wünsche zu regieren."
  },
  AvgDialog_60350_Content_37 = {
    Text = "Ich habe es dir bereits gegeben... Einmal verschenkt, kann ein Geschenk nicht zurückgenommen werden."
  },
  AvgDialog_60350_Content_38 = {
    Text = "Sie hob dein Kinn an, untersuchte dich neugierig, während ein schwaches Lächeln auf ihren Lippen spielte."
  },
  AvgDialog_60350_Content_39 = {
    Text = "Ich werde dich beobachten, Hüter."
  },
  AvgDialog_60350_Content_4 = {
    Text = "Ich glaube Ihnen. Lass uns gemeinsam in diese sorglose neue Welt gehen..."
  },
  AvgDialog_60350_Content_40 = {
    Text = "Ich werde dich beobachten, wie du diesen verdammten Weg unbeirrt gehst... Ich werde um dich bei deiner Beerdigung trauern."
  },
  AvgDialog_60350_Content_41 = {
    Text = "Ohne die Unterstützung von Samen kann die aus Sand geformte menschliche Gestalt ihre Struktur nicht mehr aufrechterhalten."
  },
  AvgDialog_60350_Content_42 = {
    Text = "Im sanften Frühlingswind verwandelt sich Thais' Gestalt in Sand und zerstreut sich wie ein sanfter Seufzer."
  },
  AvgDialog_60350_Content_5 = {
    Text = "Ich habe den Zweck nicht verstanden, warum du die Samen zuvor gepflanzt hast."
  },
  AvgDialog_60350_Content_6 = {
    Text = "Ich werde dir nicht zustimmen, Thais."
  },
  AvgDialog_60350_Content_7 = {
    Text = "Sieh dich selbst an, Hüter... Selbst ich, nur ein Saat, kann dich in einen so elenden Zustand ziehen."
  },
  AvgDialog_60350_Content_8 = {
    Text = "Selbst wenn du alle Autorität zurückforderst, bist du trotzdem nur ein Fragment... Was kannst du erreichen?"
  },
  AvgDialog_60350_Content_9 = {
    Text = "Ich werde nicht aufgeben, Thais"
  },
  AvgDialog_60351_Content_1 = {
    Text = "Vater und Tochter"
  },
  AvgDialog_60351_Content_10 = {
    Text = "Tawil... ich... habe dich schon einmal gesehen..."
  },
  AvgDialog_60351_Content_11 = {
    Text = "Herbert sagte: \"Ich bin das Zwillingsrelikt der Laterne, und die Kirche des Lichttempels kam für mich...\""
  },
  AvgDialog_60351_Content_12 = {
    Text = "Er lügt nicht. Die andere Hälfte der Zwillinge bin ich."
  },
  AvgDialog_60351_Content_13 = {
    Text = "...Ich sehe."
  },
  AvgDialog_60351_Content_14 = {
    Text = "Du bist nicht überrascht."
  },
  AvgDialog_60351_Content_15 = {
    Text = [[
Ich habe einige Spekulationen angestellt.
Herbert sagte, dass ich ein wichtiges Zwillingsrelikt der Kirche des Lichttempels bin, obwohl ich im schwarzen Teich geboren wurde.]]
  },
  AvgDialog_60351_Content_16 = {
    Text = "Außerdem habe ich dich gesehen... Dein Gesicht gesehen..."
  },
  AvgDialog_60351_Content_17 = {
    Text = "Deine Vermutung ist vollkommen richtig."
  },
  AvgDialog_60351_Content_18 = {
    Text = "Wo ist das?"
  },
  AvgDialog_60351_Content_19 = {
    Text = "Bewusstsein, Träume, die Vereinigung zahlloser Zeiten und Dimensionen, wo das Rationale auf das Irrationale trifft."
  },
  AvgDialog_60351_Content_2 = {
    Text = "\"Halo. Farben.\""
  },
  AvgDialog_60351_Content_20 = {
    Text = "Dies ist eine nicht existente Singularität... mein Versteck."
  },
  AvgDialog_60351_Content_21 = {
    Text = [[
Versteck...
Wovor versteckst du dich?]]
  },
  AvgDialog_60351_Content_22 = {
    Text = "Ein Blick. Ein Blick des höchsten Willens."
  },
  AvgDialog_60351_Content_23 = {
    Text = "Ein... Blick?"
  },
  AvgDialog_60351_Content_24 = {
    Text = "Du kannst dir ihn als ein schlafendes Baby vorstellen."
  },
  AvgDialog_60351_Content_25 = {
    Text = "Unser Universum, der gesamte Planet und die Zivilisation, sind bloß Sein Traum.\nWenn Er erwacht, wird das gesamte Universum aufhören zu existieren."
  },
  AvgDialog_60351_Content_26 = {
    Text = "Unser... Universum?!"
  },
  AvgDialog_60351_Content_27 = {
    Text = "Tawil machte keinen Moment halt, trotz Ramonas Erstaunen. Ihre Stimme hallte aus jeder Ecke des Raumes."
  },
  AvgDialog_60351_Content_28 = {
    Text = "Für Ihn ist alles Existenz Lärm; die Präsenz der drei Hauptkörper ist zu intensiv und könnte Ihn aus dem Traum wecken."
  },
  AvgDialog_60351_Content_29 = {
    Text = "Deshalb muss ich mich verstecken. Jenseits seiner Träume"
  },
  AvgDialog_60351_Content_3 = {
    Text = "Ein Phantomfluss fließt vor Ramona."
  },
  AvgDialog_60351_Content_30 = {
    Text = "Deshalb kann ich nicht direkt in alles eingreifen, was in deiner Welt geschieht."
  },
  AvgDialog_60351_Content_31 = {
    Text = "Die Zwillingsstatuen, die die Tempellichtkirche beschwören möchte, sind wir..."
  },
  AvgDialog_60351_Content_32 = {
    Text = "Versuchen sie... den Supreme Will mit Lärm zu erwecken?!"
  },
  AvgDialog_60351_Content_33 = {
    Text = "Ein schwaches Lächeln der Zustimmung scheint auf Tawils illusorischem Gesicht zu erscheinen. Sie nickt Ramona zu."
  },
  AvgDialog_60351_Content_34 = {
    Text = "Du bist ein Fragment meines Bewusstseins. Durch dich werden sie meinen Geist von hier in deinen Körper übertragen."
  },
  AvgDialog_60351_Content_35 = {
    Text = "Wenn sie erfolgreich sind, wird der Blick des Höchsten Willens bald auf deine Welt gerichtet sein..."
  },
  AvgDialog_60351_Content_36 = {
    Text = "\"Bis dahin wird die Szene, die von meinem anderen Fragment gesehen wurde, erneut geschehen.\""
  },
  AvgDialog_60351_Content_37 = {
    Text = "Sag mir, was ich tun kann! Solange wir Juliette besiegen können, können wir..."
  },
  AvgDialog_60351_Content_38 = {
    Text = "Die Lampe ist nicht wichtig, Ramona. Ohne die Lampe, ohne die Zwillinge, wird es immer noch etwas anderes geben."
  },
  AvgDialog_60351_Content_39 = {
    Text = "Die Ankunft des höchsten Willens ist unvermeidlich. Alles, was ich getan habe, ist, sein Erwachen zu verzögern."
  },
  AvgDialog_60351_Content_4 = {
    Text = "Was dir bevorsteht, ist Zeit, Dimension und die Einheit von Rationalität und Irrationalität."
  },
  AvgDialog_60351_Content_40 = {
    Text = "Nur {Male=er,Female=sie} kann Missaga und deine Welt retten"
  },
  AvgDialog_60351_Content_41 = {
    Text = "Du meinst... den Wächter?"
  },
  AvgDialog_60351_Content_42 = {
    Text = "Seit der Akut-Explosion war {Male=er,Female=sie} dazu bestimmt, diesen Weg zu gehen"
  },
  AvgDialog_60351_Content_43 = {
    Text = "Wenn die Zwillingsstatuen erscheinen, wird das \"Tor\" sich manifestieren."
  },
  AvgDialog_60351_Content_44 = {
    Text = "Damals wird {Male=er,Female=sie} die Tür betreten und alles erfahren, was {Male=er,Female=sie} wissen muss"
  },
  AvgDialog_60351_Content_45 = {
    Text = "Keeper... wer genau bist du?"
  },
  AvgDialog_60351_Content_46 = {
    Text = "Der Ausdruck auf Tawils Gesicht wird wieder illusorisch. Sie schüttelt den Kopf."
  },
  AvgDialog_60351_Content_47 = {
    Text = "Ich bin der Delegierte des Intellektuellen Körpers. Ich weiß nur, was er mir erlaubt zu wissen."
  },
  AvgDialog_60351_Content_48 = {
    Text = "Sie öffnete ihre Augen und sah ernsthaft Ramona an."
  },
  AvgDialog_60351_Content_49 = {
    Text = "Ramona, deine Geburt war ein Fehler. Dein Leben, eine fehlerhafte Simulation."
  },
  AvgDialog_60351_Content_5 = {
    Text = "Alle Kognitionen konvergieren in einem illusorischen Strom, der über ihren leichten Körper strömt."
  },
  AvgDialog_60351_Content_50 = {
    Text = "Doch die Kombination von Fehlern ergab ein korrektes Ergebnis."
  },
  AvgDialog_60351_Content_51 = {
    Text = "In unzähligen Zukünften ist deine Hilfe für {Male=er,Female=sie} der einzige Weg, diese Katastrophe zu verhindern"
  },
  AvgDialog_60351_Content_52 = {
    Text = "Hmm... Ich glaube, ich höre sie mit jemandem sprechen?"
  },
  AvgDialog_60351_Content_53 = {
    Text = "Ramona war sich nicht sicher, ob sie wach war oder träumte. Tawils Stimme war längst verstummt, ersetzt durch eine andere vertraute Stimme in ihrem Ohr."
  },
  AvgDialog_60351_Content_54 = {Text = "Wer?!"},
  AvgDialog_60351_Content_55 = {
    Text = "Was, mein alter Freund, erkennst du mich jetzt nicht?"
  },
  AvgDialog_60351_Content_56 = {
    Text = "(Professor Dexter... Vater?)"
  },
  AvgDialog_60351_Content_57 = {
    Text = "Herbert wusste nicht, wie dieser Mann plötzlich neben ihm erschienen war."
  },
  AvgDialog_60351_Content_58 = {
    Text = "Neben ihm umringten Clementine und die Mitglieder des Ausschusses Dexter."
  },
  AvgDialog_60351_Content_59 = {
    Text = "Dexter scheint oblivious gegenüber den auf ihn gerichteten Waffen zu sein und geht direkt zu Ramona, um sie zu inspizieren."
  },
  AvgDialog_60351_Content_6 = {
    Text = "Erwache, mein Wirt. Mein Fragment."
  },
  AvgDialog_60351_Content_60 = {
    Text = "Du, der Dieb, der sie gestohlen hat... Weder du noch sie werden heute gehen!"
  },
  AvgDialog_60351_Content_61 = {
    Text = "Ich vergebe deinen Respektlosigkeiten. Schließlich habe ich nicht die Absicht, eure Leben im Moment zu nehmen."
  },
  AvgDialog_60351_Content_62 = {
    Text = "Natürlich braucht man sich keine Sorgen darüber zu machen, was ich tun könnte. Ich bin erleichtert, einfach nur zu sehen, dass meine Tochter wohlauf ist. Du hast so gut auf sie aufgepasst; ich möchte sie nicht wegnehmen."
  },
  AvgDialog_60351_Content_63 = {
    Text = "Herbert runzelte die Stirn und starrte intensiv in Dexters Augen, versuchte, seine Gedanken zu entschlüsseln."
  },
  AvgDialog_60351_Content_64 = {
    Text = "Aber an seinem Gesicht konnte man, abgesehen von einem eleganten Lächeln, das zu einem Gentleman passt, nichts discernieren."
  },
  AvgDialog_60351_Content_65 = {
    Text = "Eine gefährliche Präsenz spürend, machte er eine Geste hinter sich."
  },
  AvgDialog_60351_Content_66 = {
    Text = "Keine Notwendigkeit, nervös zu sein, Mr. Herbert. Mr. Dexter ist unser Freund."
  },
  AvgDialog_60351_Content_67 = {Text = "Freund?"},
  AvgDialog_60351_Content_68 = {
    Text = "Bitte missverstehe nicht, Frau Juliette. Ich habe es dir vor vielen Jahren sehr klar gemacht."
  },
  AvgDialog_60351_Content_69 = {
    Text = "Ich bin nicht dein Freund. Ich bin lediglich ein Beobachter."
  },
  AvgDialog_60351_Content_7 = {
    Text = "Ramonas Augen weiteten sich."
  },
  AvgDialog_60351_Content_70 = {
    Text = "Die Favoriten des Theaters – jährliche Logenplätze kaufen, höflich, niemals laut und niemals abwesend."
  },
  AvgDialog_60351_Content_71 = {
    Text = "Er klopfte Juliette sanft auf die Schulter, wie ein edles Publikum, das aufrichtige Bewunderung für einen herausragenden Darsteller zeigt."
  },
  AvgDialog_60351_Content_72 = {
    Text = "Frau Juliette, ich bin froh zu sehen, dass Sie endlich Ihr Versprechen eingelöst haben."
  },
  AvgDialog_60351_Content_73 = {
    Text = "Aber du musst vorsichtig sein. Ich habe nur eine Tochter, also bitte, sorge dafür, dass ihr nichts zustößt."
  },
  AvgDialog_60351_Content_74 = {
    Text = "Ich habe zwanzig Jahre auf diese Darbietung gewartet."
  },
  AvgDialog_60351_Content_75 = {
    Text = "Ramona hofft, hofft, dass sie sich noch im Raum von Tawil befindet, und wünscht, es wäre alles ein absurdes Traum."
  },
  AvgDialog_60351_Content_76 = {
    Text = "Sie konnte ihren Körper nicht am Zittern hindern, noch konnte sie verhindern, dass eine Träne in den brodelnden schwarzen Pool fiel."
  },
  AvgDialog_60351_Content_77 = {
    Text = "Diese kristalline Träne spiegelt einen Glanz in Dexters Auge wider."
  },
  AvgDialog_60351_Content_78 = {
    Text = "Ich habe wichtige Gäste zu treffen. Auf Wiedersehen, alle."
  },
  AvgDialog_60351_Content_79 = {
    Text = "Er lächelt und nickt allen zu, verschwindet ohne einen einzigen Träne in den Schatten des Schwarzen Pools."
  },
  AvgDialog_60351_Content_8 = {
    Text = "In diesem illusorischen Raum zeigt die in der schwarzen Pfütze versunkene Gestalt ihr leicht verhülltes Gesicht"
  },
  AvgDialog_60351_Content_9 = {
    Text = "—Ein Gesicht, das Ramonas entspricht."
  },
  AvgDialog_60352_Content_1 = {
    Text = "Thais hobte ihren Arm und verstreute samenartige Lichter vor dir."
  },
  AvgDialog_60352_Content_2 = {
    Text = "Lichtpunkte ziehen gelben Sand an, der sich zu einer Gruppe vertrauter Relikte zusammentut."
  },
  AvgDialog_60352_Content_3 = {
    Text = "Die Kreaturen, denen du in der Wüste begegnet bist, erscheinen dir erneut in einer erschreckenden Form."
  },
  AvgDialog_60352_Content_4 = {
    Text = "Thais! Beruhige dich..."
  },
  AvgDialog_60352_Content_5 = {
    Text = "Ich bin ruhig, Hüter."
  },
  AvgDialog_60352_Content_6 = {
    Text = "Besiege sie, besänftige sie, auch wenn du einen Blick auf meinen Phantasmagorie erhaschst, es wird sich lohnen.\nDanach werde ich mich wieder in einen Samen verwandeln und in deinen Körper eintreten."
  },
  AvgDialog_60352_Content_7 = {
    Text = "Ich werde mit dir in eine neue Welt gehen..."
  },
  AvgDialog_60352_Content_8 = {
    Text = "Er winkte mit der Hand. Kreaturen, die aus der schwarzen Pfütze entstanden, stürmten auf dich zu"
  },
  AvgDialog_60353_Content_1 = {Text = "Schicksal"},
  AvgDialog_60353_Content_10 = {
    Text = "Die Dauer der Bewegung ist begrenzt; spare sie für wichtigere Momente. Im Vergleich zum Versagen ist Schmerz nichts."
  },
  AvgDialog_60353_Content_11 = {
    Text = "\"Du lässt einen tiefen Seufzer hören.\""
  },
  AvgDialog_60353_Content_12 = {
    Text = "Die sanfte Frühlingsbrise und ungehemmtes Lachen verweben sich und beruhigen sich allmählich, deine Beweglichkeit hat sich größtenteils erholt."
  },
  AvgDialog_60353_Content_13 = {
    Text = "Zwei eigenwillige Wesen haben mir ihre Autorität übertragen."
  },
  AvgDialog_60353_Content_14 = {
    Text = "Als nächstes, bleibt nur der Intellektuelle Körper, der immer auf der Seite von Mythag stand..."
  },
  AvgDialog_60353_Content_15 = {
    Text = "Du starrst geradeaus und ballst die Fäuste."
  },
  AvgDialog_60353_Content_16 = {
    Text = "Lass uns gehen, Hameln. Wir müssen uns beeilen."
  },
  AvgDialog_60353_Content_17 = {
    Text = "In der Nähe von Tawil setzt Juliette schwere Patrouillen ein."
  },
  AvgDialog_60353_Content_18 = {
    Text = "Sei vorsichtig."
  },
  AvgDialog_60353_Content_2 = {
    Text = "Dein Ausdruck hat sich etwas entspannt. Es scheint, als ob du dich gut anpasst, indem du deine Autorität ein zweites Mal zurückforderst."
  },
  AvgDialog_60353_Content_3 = {
    Text = "Du erträgst das wahnsinnige Lachen, das in deinen Ohren klingt, und kannst nicht anders, als die Augen über Hameln zu rollen."
  },
  AvgDialog_60353_Content_4 = {
    Text = "Und du hast die Frechheit zu kritisieren... Wo warst du, als N mich bedrohte?"
  },
  AvgDialog_60353_Content_5 = {
    Text = "Es ist deine Pflicht, N zu überzeugen. Du kannst das schaffen."
  },
  AvgDialog_60353_Content_6 = {
    Text = "N ist arrogant; meine Art der Kommunikation wird es dir nur schwerer machen, dein Ziel zu erreichen."
  },
  AvgDialog_60353_Content_7 = {
    Text = "Du bist dir deiner selbst sehr bewusst..."
  },
  AvgDialog_60353_Content_8 = {
    Text = "Jeder hat seinen Platz. Wenn sie ihre Rolle nicht erfüllen, wäre die Aufführung unmöglich."
  },
  AvgDialog_60353_Content_9 = {
    Text = "Könntest du wenigstens deine Musik benutzen, um meinen Schmerz ein wenig zu lindern? Weißt du, wie unerträglich das Zeug ist, das N mir gegeben hat?"
  },
  AvgDialog_60354_Content_1 = {
    Text = "Huch... huch..."
  },
  AvgDialog_60354_Content_10 = {
    Text = "Dein Magen windet sich vor Qual. Du öffnest deinen Mund, und ein dicker Nebel strömt aus dir heraus, wie Tinte, die sich im Wasser ausbreitet."
  },
  AvgDialog_60354_Content_11 = {
    Text = "Der Nebel verhärtete sich zu einer ellipsoidalen Form, die dem Auge eines Wesens ähnelt."
  },
  AvgDialog_60354_Content_12 = {
    Text = "Dieses Auge zerstreut sich im Licht von Tawil, bevor es sich überhaupt öffnet."
  },
  AvgDialog_60354_Content_13 = {Text = "Das ist..."},
  AvgDialog_60354_Content_14 = {
    Text = "Du bewegst langsam deine Hände von deinen Augen weg. Die illusorische Gestalt von Tawil steht vor dir und nickt langsam."
  },
  AvgDialog_60354_Content_15 = {
    Text = "Die Fehler in dir wurden korrigiert."
  },
  AvgDialog_60354_Content_16 = {
    Text = "Sagst du, dass der Fehler nicht meiner war...?"
  },
  AvgDialog_60354_Content_17 = {
    Text = "Der Fehler liegt in dir. Es ist das Auge, durch das der höchste Wille diese Welt beobachtet."
  },
  AvgDialog_60354_Content_18 = {
    Text = "N spürte seine Präsenz. Er gewährte dir Autorität sowie einen Willen, dich zu kontrollieren."
  },
  AvgDialog_60354_Content_19 = {
    Text = "Jetzt sind all diese Fehler beseitigt. Du bist für den Moment sicher."
  },
  AvgDialog_60354_Content_2 = {
    Text = "Du hast Tawils Angriff gerade noch standgehalten."
  },
  AvgDialog_60354_Content_20 = {
    Text = "So ist es also... Ich dachte, es wäre nur mein Überdenken."
  },
  AvgDialog_60354_Content_21 = {
    Text = "\"Du nimmst einen tiefen Atemzug und stehst auf.\""
  },
  AvgDialog_60354_Content_22 = {
    Text = "Vielen Dank..."
  },
  AvgDialog_60354_Content_23 = {
    Text = "Kein Grund, mir zu danken. Ich mache nur das, was ich tun soll. Was als Nächstes kommt, liegt an dir."
  },
  AvgDialog_60354_Content_24 = {
    Text = "Es gibt eine Sache, die ich nicht verstehe."
  },
  AvgDialog_60354_Content_25 = {
    Text = "Höchster Wille, was hat das mit mir zu tun... Warum wurde ich gewählt? Wer bin ich wirklich?"
  },
  AvgDialog_60354_Content_26 = {
    Text = "Du ziehst die Stirn kraus und schaust Tawil an."
  },
  AvgDialog_60354_Content_27 = {
    Text = "Wahrheit bedeutet oft Verantwortung, sowie Leiden."
  },
  AvgDialog_60354_Content_28 = {
    Text = "Ich bin bereit, es auf mich zu nehmen."
  },
  AvgDialog_60354_Content_29 = {
    Text = "Ich bin der Hüter von Mythag und ich habe einen Eid im Heiligtum der Schlüssel geschworen."
  },
  AvgDialog_60354_Content_3 = {
    Text = "Der intensive Aufprall entzieht dir alle Kraft und zwingt dich, auf die Knie zu fallen."
  },
  AvgDialog_60354_Content_30 = {
    Text = "Wenn das ist, was ich ertragen muss, dann werde ich es ertragen."
  },
  AvgDialog_60354_Content_31 = {
    Text = "Tawil sieht in deine entschlossenen Augen, ihr Ausdruck flackert, als ob sie sich an etwas Entferntes erinnert."
  },
  AvgDialog_60354_Content_32 = {
    Text = "Er ist das urtümliche Chaos, ein unbewusster Zerstörer... Als sein Fragment bist du anders."
  },
  AvgDialog_60354_Content_33 = {Text = "?!!"},
  AvgDialog_60354_Content_34 = {
    Text = "Akut Frühling, du bist in dieser Welt angekommen. Ich kann das Schicksal, das du bringen wirst, nicht voraussehen. Ich dachte einmal, du würdest der Vorbote der Zerstörung dieser Welt sein."
  },
  AvgDialog_60354_Content_35 = {
    Text = "Ich lag falsch, Hüter. Zerstörung braucht keinen Katalysator. Seine Geistfragmente, sein naives bewusstes Dasein, werden die einzige Lösung sein."
  },
  AvgDialog_60354_Content_36 = {
    Text = "Fragmente des Höchsten Willens..."
  },
  AvgDialog_60354_Content_37 = {
    Text = "Das Herz springt plötzlich. Was in der Tiefe verweilt, scheint eine Resonanz aus den entferntesten Regionen des Universums zu sein."
  },
  AvgDialog_60354_Content_38 = {
    Text = "Dein Talent, die Einstellungen der drei Essenzen dir gegenüber... Du hast darüber nachgedacht. Als die Antwort schließlich kommt, spürst du immer noch ein Zittern."
  },
  AvgDialog_60354_Content_39 = {
    Text = "Aber weißt du, es gibt eine drängendere Frage, die beantwortet werden muss."
  },
  AvgDialog_60354_Content_4 = {Text = "Warum"},
  AvgDialog_60354_Content_40 = {
    Text = "Tawil, sag mir bitte, wie kann ich Seine Macht erlangen... Wie kann ich Seine Ankunft stoppen!"
  },
  AvgDialog_60354_Content_41 = {
    Text = "Die Ankunft des höchsten Willens ist unaufhaltsam. Hüter."
  },
  AvgDialog_60354_Content_42 = {
    Text = "Der Intellektuelle Körper weiß alles, aber er hat mir nicht das gesamte Wissen gegeben.\nOmniscience ist kein Segen; manchmal bringt sie nur größere Katastrophen."
  },
  AvgDialog_60354_Content_43 = {
    Text = "Von den Dingen, die ich weiß, gibt es keine Antwort, die du benötigst."
  },
  AvgDialog_60354_Content_44 = {
    Text = "Alle Antworten, alle Katastrophen, liegen hinter der Tür..."
  },
  AvgDialog_60354_Content_45 = {
    Text = "Ein leises Geräusch unterbrach Tawil. Sie drehte ruhig ihren Kopf, ihre Augen schienen durch diesen Raum zu stechen und irgendwo darüber hinaus zu landen."
  },
  AvgDialog_60354_Content_46 = {
    Text = "Ein erleichtertes Lächeln erscheint auf dem ätherischen und schönen Gesicht."
  },
  AvgDialog_60354_Content_47 = {
    Text = "Sie fand schließlich mich."
  },
  AvgDialog_60354_Content_48 = {
    Text = "Plötzlich erscheint eine Auflösung in diesem geheimen Raum."
  },
  AvgDialog_60354_Content_49 = {
    Text = "Sie? Du meinst...Juliette?"
  },
  AvgDialog_60354_Content_5 = {
    Text = "Verschwinden."
  },
  AvgDialog_60354_Content_50 = {
    Text = "Die Auflösung breitet sich schnell aus und kontaminiert gierig jede Ecke dieses Raumes."
  },
  AvgDialog_60354_Content_51 = {
    Text = "Zahlreiche Auflösungsflüssigkeiten stürzen sich wie Raubtiere auf Tawil und versuchen, sie zu umhüllen, zu binden und zu ertränken."
  },
  AvgDialog_60354_Content_52 = {Text = "Tawil!!"},
  AvgDialog_60354_Content_53 = {
    Text = "Die riesigen Flügel breiteten sich plötzlich aus. Mit dem Zug der Auflösungsflüssigkeit springt sie auf dich zu—"
  },
  AvgDialog_60354_Content_54 = {
    Text = "Der Zug der Auflösungsflüssigkeit hinterließ große Wunden an ihr, die schwarze Flüssigkeit in ihrem Körper vermischte sich mit der Auflösung und verwandelte sie in ein surreales und schmutziges Ölgemälde."
  },
  AvgDialog_60354_Content_55 = {
    Text = "In diesem Schmerz und Schmutz schaut Er ruhig auf dich und streckt seine Hand aus—"
  },
  AvgDialog_60354_Content_56 = {
    Text = "Ramona und ich werden vorübergehend oder dauerhaft sterben."
  },
  AvgDialog_60354_Content_57 = {
    Text = "Sobald du diesen Ort verlässt, werden wir Feinde sein."
  },
  AvgDialog_60354_Content_58 = {
    Text = "Sein Fingerspitze tippte sanft auf deine Stirn."
  },
  AvgDialog_60354_Content_59 = {
    Text = "Ein reines Licht erfüllt deinen Geist und erleuchtet jede Nervenenden. Dein Gehirn ist mit unzähligen Wissensstücken gefüllt."
  },
  AvgDialog_60354_Content_6 = {
    Text = "Sie hob ihre Hand."
  },
  AvgDialog_60354_Content_60 = {
    Text = "Die tobende Kraft von Thais und N in dir beruhigt sich, als das Licht hinein strömt, und der heulende Wind und das Lachen verstummen plötzlich."
  },
  AvgDialog_60354_Content_61 = {
    Text = "Wie beim Vervollständigen des letzten Puzzlestücks balancierten und vereinheitlichten drei Kräfte in dir und bildeten eine ruhige und weite Galaxie."
  },
  AvgDialog_60354_Content_62 = {
    Text = "Keine Bitte. Keine Flucht. So ist das Schicksal dieser Welt."
  },
  AvgDialog_60354_Content_63 = {
    Text = "Ich gewähre dir all meine Macht und Autorität, Hüter."
  },
  AvgDialog_60354_Content_64 = {
    Text = "Besiege uns. Töte uns. Dann, rette uns."
  },
  AvgDialog_60354_Content_7 = {Text = "Warte! —"},
  AvgDialog_60354_Content_8 = {
    Text = "Ein blendender, weißer Lichtschein bricht von Tawil aus.\nDu bist machtlos, dich zu widersetzen, und lässt das intensive Licht geradezu durch deinen Körper dringen."
  },
  AvgDialog_60354_Content_9 = {Text = "Hmm—"},
  AvgDialog_60356_Content_1 = {
    Text = "Huch... huch..."
  },
  AvgDialog_60356_Content_10 = {
    Text = "Egal was, ich werde niemals zulassen, dass deine Pläne erfolgreich sind!"
  },
  AvgDialog_60356_Content_11 = {
    Text = "Hameln, decke mich!"
  },
  AvgDialog_60356_Content_12 = {
    Text = "Hameln hob sanft die Hand, die seinen Dirigentenstab hielt."
  },
  AvgDialog_60356_Content_13 = {
    Text = "Juliettes Ausdruck bleibt unverändert, egal wie viele Untergebene fallen. Sie lächelt dich immer noch an, als wären sie nur kostengünstige Materialien, die verwendet werden, um deine Geisterenergie zu erschöpfen."
  },
  AvgDialog_60356_Content_14 = {
    Text = "Du gibst schnell Befehle an die Erwachten aus. Dies ist eine Gelegenheit, die du dir nicht entgehen lassen darfst; du musst sie im Handumdrehen besiegen!"
  },
  AvgDialog_60356_Content_15 = {
    Text = "Du hebst deine Hand mit dem silbernen Schlüssel hoch. Der silberne Schlüssel strahlt hell und überträgt massive geistige Kraft auf die Erwachten"
  },
  AvgDialog_60356_Content_16 = {
    Text = "Bereite dich anzugreifen vor!"
  },
  AvgDialog_60356_Content_17 = {
    Text = "Erwachender, bereite dich vor..."
  },
  AvgDialog_60356_Content_18 = {
    Text = "Vierte Symphonie, stoppe."
  },
  AvgDialog_60356_Content_19 = {
    Text = "Eine vertraute Stimme. Kühl, fest und unbestreitbar.\nDer Stock klopft sanft hinter dir, so gleichmäßig und elegant wie auf der Theaterbühne."
  },
  AvgDialog_60356_Content_2 = {
    Text = "Dein Körper zittert vor Erschöpfung, und der immense Stress von der Geisterverbindung bringt pulssschmerz in deinen Kopf"
  },
  AvgDialog_60356_Content_20 = {
    Text = "Mit diesem Befehl verschwindet die Musik, die deinen Geist stabilisiert, und wird durch durchdringenden, chaotischen Lärm ersetzt."
  },
  AvgDialog_60356_Content_21 = {
    Text = "Diese Melodie war die Kuppel, die deine Geisterwelt schützte und dich vor dem aufwallenden schwarzen Pool abschirmte."
  },
  AvgDialog_60356_Content_22 = {
    Text = "In diesem Moment stürzte die Kuppel plötzlich ein, verwandelte sich in zerbrochene Klingen, vermischt mit dem brodelnden Schwarzen Pool, und griff deine Geistwelt an."
  },
  AvgDialog_60356_Content_23 = {Text = "Ah!!—"},
  AvgDialog_60356_Content_24 = {
    Text = "Die immense Schmerzen sind unerträglich. Der Verbindungsweg zu den Erwachten wird gekappt, und sie verlieren sofort alle Macht, einer nach dem anderen kollabierend zu Juliettes Füßen."
  },
  AvgDialog_60356_Content_25 = {
    Text = "Erschöpft von längeren Kämpfen und unvorbereitet überrascht, lässt diese plötzliche Krise Ihnen keinen Raum zum Widerstand."
  },
  AvgDialog_60356_Content_26 = {
    Text = "Meine Mission ist erfüllt."
  },
  AvgDialog_60356_Content_27 = {
    Text = "Der Dirigent steckt seinen Taktstock weg. Sauber, elegant und ohne Zögern."
  },
  AvgDialog_60356_Content_28 = {
    Text = "Ihr Urteil ist absolut korrekt, Herr Hameln."
  },
  AvgDialog_60356_Content_29 = {
    Text = "Der Hüter ist unsere größte Bedrohung. Dies ist %seinoderihr% eigenes Gebiet. Wenn wir die Kontrolle über %ihnoderihn% verlieren, wird unser Plan einer erheblichen Bedrohung ausgesetzt sein."
  },
  AvgDialog_60356_Content_3 = {
    Text = "Zahlreiche Soldaten und Priester des Ausschusses fielen im Schwarzen Teich neben dir und bildeten aus der Vogelperspektive ein Gemälde aus übereinandergeschichteten Körpern."
  },
  AvgDialog_60356_Content_30 = {
    Text = "Gewinne das Vertrauen von %hisorher%, nicht nur um {Male=er,Female=sie} zu helfen, Tawil zu finden, sondern auch um %hisorher% Bewegungen zu überwachen"
  },
  AvgDialog_60356_Content_31 = {
    Text = "Wenn nicht für deine Strategie, wäre unser Plan nicht so reibungslos verlaufen. Es ist eine Ehre, mit einer so herausragenden Person wie dir zusammenzuarbeiten."
  },
  AvgDialog_60356_Content_32 = {
    Text = "Nicht der Rede wert."
  },
  AvgDialog_60356_Content_33 = {
    Text = "Hameln nickte leicht als Antwort auf Juliette."
  },
  AvgDialog_60356_Content_34 = {
    Text = "Mit deinem letzten bisschen Kraft hebst du deinen Kopf und schaust die Person neben dir an."
  },
  AvgDialog_60356_Content_35 = {Text = "Hameln...?"},
  AvgDialog_60356_Content_36 = {
    Text = "Hameln, du..."
  },
  AvgDialog_60356_Content_37 = {
    Text = "Ihre Geisterverbindung ist vollständig zerstört; Sie sind jetzt machtlos."
  },
  AvgDialog_60356_Content_38 = {
    Text = "Die Dinge stehen jetzt so. Es hat keinen Zweck, mehr zu sagen. Einfach akzeptieren und abwarten."
  },
  AvgDialog_60356_Content_39 = {
    Text = "Warte auf das Eintreffen dieser erhabenen Melodie."
  },
  AvgDialog_60356_Content_4 = {
    Text = "Unglaublich, Hüter... Dein Talent ist wirklich beneidenswert."
  },
  AvgDialog_60356_Content_40 = {
    Text = "Hameln's Stimme ist so ruhig wie ein eisiger See—rein und leer, nichts offenbarend."
  },
  AvgDialog_60356_Content_41 = {
    Text = "Der Klang von Schritten hallt wider, als eine Gruppe von Klerikern erscheint und jemanden trägt."
  },
  AvgDialog_60356_Content_42 = {
    Text = "Ramona...!!"
  },
  AvgDialog_60356_Content_43 = {
    Text = "Du versuchst zu kämpfen, aber dein Körper rührt sich keinen Zentimeter. Du kannst nur hilflos zusehen, wie sie Ramonas Körper unter Tawils Hülle legen."
  },
  AvgDialog_60356_Content_44 = {
    Text = "Als Ramonas Körper in den Schwarzen Pool eintauchte, erschien ein großer magischer Kreis, verziert mit einem Laternenemblem, unter ihr."
  },
  AvgDialog_60356_Content_45 = {
    Text = "Juliette lächelte und setzte eine seltsam geformte Lampe auf Ramonas Kopf."
  },
  AvgDialog_60356_Content_46 = {
    Text = "Sie hebt langsam ihren Arm, ihr Lächeln wird allmählich ernst."
  },
  AvgDialog_60356_Content_47 = {
    Text = "Das letzte Hindernis wurde beseitigt, und alles ist bereit."
  },
  AvgDialog_60356_Content_48 = {
    Text = "Höchstes Relikt, antworte unserem Ruf..."
  },
  AvgDialog_60356_Content_49 = {
    Text = "Bringe große Reinigung in diese Welt!"
  },
  AvgDialog_60356_Content_5 = {
    Text = "Aber leider bist du mir nicht gewachsen."
  },
  AvgDialog_60356_Content_50 = {Text = "Whoosh—"},
  AvgDialog_60356_Content_51 = {
    Text = "Der grenzenlose schwarze Pool begann, heftig zu zittern."
  },
  AvgDialog_60356_Content_52 = {
    Text = "Unter dem gewaltigen magischen Zirkel offenbarte sich in deinen verzweifelten Augen langsam der Kopf einer riesigen weißen Idole"
  },
  AvgDialog_60356_Content_6 = {
    Text = "Die Kraft der drei Elemente hat sich stabilisiert, und meine Stärke ist zurückgekehrt."
  },
  AvgDialog_60356_Content_7 = {
    Text = "Ich habe schon einmal gegen dich gekämpft, Juliette. Ich kenne deine Fähigkeiten gut."
  },
  AvgDialog_60356_Content_8 = {
    Text = "Ich weiß, dass du mächtig bist, und ich weiß auch, dass du noch verborgene Kräfte hast, die du noch nicht eingesetzt hast... Aber wenn du Mythag ins Visier nimmst, hast du den falschen Gegner gewählt."
  },
  AvgDialog_60356_Content_9 = {
    Text = "Du greifst das Silber und die Erwachenden um dich herum, die deinem Befehl folgen, umzingeln Juliette."
  },
  AvgDialog_60357_Content_1 = {
    Text = "Der dritte Satz"
  },
  AvgDialog_60357_Content_10 = {
    Text = "Sowohl körperliche Funktionen als auch Geisterkraft werden wiederhergestellt!"
  },
  AvgDialog_60357_Content_11 = {
    Text = "Der Einfluss des Schwarzen Pools ist größtenteils verschwunden, aber ich weiß immer noch nicht, wie ich die Kraft der drei Essenzen nutzen kann..."
  },
  AvgDialog_60357_Content_12 = {
    Text = "Die Methode zur Machtabsorption liegt hinter der Tür."
  },
  AvgDialog_60357_Content_13 = {
    Text = "In Tawils Raum informierte er mich auch darüber... Wie hast du das gewusst?"
  },
  AvgDialog_60357_Content_14 = {
    Text = "Spekulation."
  },
  AvgDialog_60357_Content_15 = {
    Text = "Die Musik jetzt zu stoppen ist riskant. Bis die Autorität der drei Essenzen vollständig Wirkung zeigt, werde ich weiterhin helfen, die Stabilität deines Geistes aufrechtzuerhalten."
  },
  AvgDialog_60357_Content_16 = {
    Text = "Vielen Dank... Hameln. Ich hätte es bis hierher ohne deine Hilfe nicht geschafft."
  },
  AvgDialog_60357_Content_17 = {
    Text = "Ich habe meinen eigenen Zweck."
  },
  AvgDialog_60357_Content_18 = {
    Text = "Du hast mir geholfen, also werde ich mein Bestes tun, um dir zu helfen, das zu finden, was du suchst."
  },
  AvgDialog_60357_Content_19 = {
    Text = "Natürlich wirst du das. Ich habe nie daran gezweifelt."
  },
  AvgDialog_60357_Content_2 = {
    Text = "Der Berührungsreiz der Finger verblasst von deiner Stirn. Du öffnest deine Augen und findest Tawil und ihren Raum verschwunden; der Schwarze Pool erscheint wieder zu deinen Füßen."
  },
  AvgDialog_60357_Content_20 = {
    Text = "Lass uns zuerst Juliette finden und Ramona retten..."
  },
  AvgDialog_60357_Content_21 = {
    Text = "Hehe, ich bin hier, um Mythag zu besuchen. Es wäre nicht angemessen, den Gastgeber zu belästigen, mich zu suchen."
  },
  AvgDialog_60357_Content_22 = {Text = "!!!"},
  AvgDialog_60357_Content_23 = {
    Text = "Ein starkes Krisengefühl lässt dich sofort angespannt sein. Du und Hameln stehen Rücken an Rücken und beobachtet jeweils die Hälfte des Bereichs."
  },
  AvgDialog_60357_Content_24 = {
    Text = "Ein vertrauter lila Schleier blitzt im schwachen Licht des Schwarzen Pools auf."
  },
  AvgDialog_60357_Content_25 = {
    Text = "Wir treffen uns wieder, Hüter. Und Sie, Herr Verräter."
  },
  AvgDialog_60357_Content_26 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_60357_Content_27 = {
    Text = "Die Frau unter dem Schleier bietet dir ein sanftes Lächeln, genau wie das, als ihr euch zum ersten Mal in der Wüste begegnet seid."
  },
  AvgDialog_60357_Content_28 = {
    Text = "Als ihre Stimme widerhallte, erschienen unzählige Agenten und lila-robed Kleriker um dich herum und umzingelten dich vollständig."
  },
  AvgDialog_60357_Content_29 = {
    Text = "Sie wussten nicht, wie lange sie in der kochenden schwarzen Pfütze geblieben waren und massiven Schaden erlitten hatten. Manchmal fällt jemand, verwandelt sich in schwarze Auflösungsflüssigkeit und verschmilzt mit dem Pool"
  },
  AvgDialog_60357_Content_3 = {
    Text = "Ich... bin zurückgekehrt?"
  },
  AvgDialog_60357_Content_30 = {
    Text = "Ob es sich um die Menschen um sie herum oder um sich selbst handelt, ihre Gesichter bleiben völlig unbewegt."
  },
  AvgDialog_60357_Content_31 = {
    Text = "Sie sind Juliettes Hunde, die nur dem Willen der Laterne gehorchen."
  },
  AvgDialog_60357_Content_32 = {
    Text = "Hast du... auf mich gewartet?"
  },
  AvgDialog_60357_Content_33 = {
    Text = "Ich habe lange auf dich gewartet, zum Glück war es nicht umsonst. Danke dir, Geheimguardian{Male=Herr,Female=Frau}"
  },
  AvgDialog_60357_Content_34 = {
    Text = "Tawil zu finden, ist für die meisten Menschen nahezu unmöglich. Hätte Tawil dich nicht in seinen Bereich gebracht, hätte es Wochen gedauert, ihn zu finden."
  },
  AvgDialog_60357_Content_35 = {Text = "!!!"},
  AvgDialog_60357_Content_36 = {
    Text = "War das... absichtlich?"
  },
  AvgDialog_60357_Content_37 = {
    Text = "Unmöglich... Auf dem Friedhof haben wir den Cynocephalus getötet. Du könntest unmöglich wissen, wo ich bin oder was ich plane..."
  },
  AvgDialog_60357_Content_38 = {
    Text = "Menschen können das große Ganze nicht begreifen; das ist die Grenze des Menschseins."
  },
  AvgDialog_60357_Content_39 = {
    Text = "Hüter {Male=Herr,Female=Frau}, du hast Großes für die Ankunft des Gottes geleistet. Im neuen Welt des Gottes wirst du bevorzugt behandelt"
  },
  AvgDialog_60357_Content_4 = {
    Text = "Du scheinst kurz das Bewusstsein verloren zu haben."
  },
  AvgDialog_60357_Content_40 = {
    Text = "Sie winkte. Die umstehenden Priester und Soldaten, mit ausdruckslosen Gesichtern, stürzten sich auf dich..."
  },
  AvgDialog_60357_Content_5 = {
    Text = "Ich... wurde von Tawil in einen seltsamen Raum gebracht..."
  },
  AvgDialog_60357_Content_6 = {
    Text = "Es scheint, dass Sie die gesamte Autorität der drei Essenzen zurückgewonnen haben."
  },
  AvgDialog_60357_Content_7 = {
    Text = "„Du schließt deine Augen und fühlst die Macht, die in dir schwelt.“"
  },
  AvgDialog_60357_Content_8 = {
    Text = "Diese drei kraftvollen Kräfte balancieren einander in dir aus und bilden einen harmonischen Ozean, der mit deinem Atem steigt und fällt."
  },
  AvgDialog_60357_Content_9 = {
    Text = "Du stehst auf und überprüfst deinen Gesundheitszustand."
  },
  AvgDialog_60358_Content_1 = {
    Text = "Eine große Anzahl von Schatten strömte aus N's Körper heraus."
  },
  AvgDialog_60358_Content_10 = {
    Text = "Also, bring mir diese verlorene und wiedergefundene Show, Hüter {Male=Herr,Female=Frau}"
  },
  AvgDialog_60358_Content_2 = {
    Text = "Schatten fallen auf die Bühne und verwandeln sich schnell in gefährliche Auflösungswesen, die dich umgeben."
  },
  AvgDialog_60358_Content_3 = {
    Text = "So, wie läuft es, mein Freund?"
  },
  AvgDialog_60358_Content_4 = {
    Text = "Wie fühlt es sich an, die Autorität über das Wesen des Verlangens erfolgreich zurückzuerobern, nur um es wieder weggenommen zu sehen?"
  },
  AvgDialog_60358_Content_5 = {
    Text = "Was hast du vor, N!?"
  },
  AvgDialog_60358_Content_6 = {
    Text = "Diese Autorität nützt dir nichts!"
  },
  AvgDialog_60358_Content_7 = {
    Text = "In der Tat, es ist nutzlos... Aber es ist nützlich für mich, dich Autorität verlieren zu sehen."
  },
  AvgDialog_60358_Content_8 = {
    Text = "Was meinst du..."
  },
  AvgDialog_60358_Content_9 = {
    Text = "Als Schauspieler und Publikum sollte der Konflikt des Dramas unser lebenslanger Streben sein..."
  },
  AvgDialog_60596_Content_1 = {
    Text = "Die Laterne ist erschienen. Höchster Wille, lass mich ihre Flamme für dich entfachen—"
  },
  AvgDialog_60596_Content_2 = {
    Text = "Die Ikone verschlingt Tawil und Ramona."
  },
  AvgDialog_60596_Content_3 = {
    Text = "Meine Musik hat für dich begonnen zu spielen. Störe ihre Fusion, Hüter!"
  },
  AvgDialog_60842_Content_1 = {Text = "Lex lethis"},
  AvgDialog_60842_Content_10 = {
    Text = "Ich habe dich gefunden... Tawil!"
  },
  AvgDialog_60842_Content_11 = {
    Text = "Ein scharfer Schrei hallt über die schwarze Pfütze. Der Stab, der Wissen repräsentiert, vibriert mit dem Schrei"
  },
  AvgDialog_60842_Content_12 = {
    Text = "Unzählige weiße Schemen, aus verschiedenen Dimensionen und Zeiten gefangen, verschmelzen in der schwarz-weißen Statue"
  },
  AvgDialog_60842_Content_13 = {
    Text = "Sehr bald verstummten alle Schreie und Vibrationen"
  },
  AvgDialog_60842_Content_14 = {
    Text = "Auch ohne die Laterne werden andere kommen. Niemand kann ihm, Tawil, entkommen."
  },
  AvgDialog_60842_Content_15 = {
    Text = "Komm, lasst uns gemeinsam seine Geburt feiern!"
  },
  AvgDialog_60842_Content_16 = {
    Text = "Als Juliette stoppte, begannen die riesigen Zwillingslaternen sich zum Zentrum zu bewegen und suchten dringend nach einer Verschmelzung mit der zentralen schwarz-weißen Statue, als ob sie nach einer Seele suchten."
  },
  AvgDialog_60842_Content_17 = {
    Text = "Tawil! Ramona!! Ah—"
  },
  AvgDialog_60842_Content_18 = {
    Text = "Ein starkes Licht brach plötzlich auf. Hinter dem riesigen Zwillingsartefakt erschien ein Spalt"
  },
  AvgDialog_60842_Content_19 = {
    Text = "Du nimmst langsam die Hände von deinen Augen"
  },
  AvgDialog_60842_Content_2 = {
    Text = "Du bist im Sturm"
  },
  AvgDialog_60842_Content_20 = {
    Text = "Das ist... eine Tür?"
  },
  AvgDialog_60842_Content_21 = {
    Text = "Die illusorische Tür hinter Tawil erlangte in diesem Moment physische Existenz"
  },
  AvgDialog_60842_Content_22 = {
    Text = "Licht strömt durch den sich öffnenden Spalt, kalt wie das Universum, rein wie die Wahrheit"
  },
  AvgDialog_60842_Content_23 = {
    Text = "Juliette starrt ins Licht, Tränen rollen unbemerkt im starken Glanz über ihr Gesicht, unfähig, wegzuschauen."
  },
  AvgDialog_60842_Content_24 = {
    Text = "Tür... das Tor zu allem... das Wohnsitz des Gottes"
  },
  AvgDialog_60842_Content_25 = {
    Text = "Endlich, endlich ist dieser Tag gekommen!"
  },
  AvgDialog_60842_Content_26 = {
    Text = "Nein, die Tür darf nicht geöffnet werden"
  },
  AvgDialog_60842_Content_27 = {
    Text = "Du willst etwas tun. Du versuchst, den Silberschlüssel zu aktivieren, aber deine geistige Kraft wird unterdrückt, der Schlüssel reagiert nicht"
  },
  AvgDialog_60842_Content_29 = {
    Text = "Du starrst verzweifelt auf die Tür, die sich von verschwommen zu klar verändert und einen Spalt öffnet"
  },
  AvgDialog_60842_Content_3 = {
    Text = "Starke Erschütterungen lassen das Wasser der schwarzen Pfütze heftig wogen und riesige Wellen aufsteigen, die gegen dich schlagen"
  },
  AvgDialog_60842_Content_30 = {
    Text = "Die mächtige Kraft, wie eine Flut, die die Welt zu überfluten droht, strömt aus der Tür zu den Zwillingslaternenstatuen"
  },
  AvgDialog_60842_Content_31 = {
    Text = "Juliette starrte mit weit aufgerissenen Augen auf die Tür und die Statue, das Lächeln in ihrem Gesicht wurde immer grausamer"
  },
  AvgDialog_60842_Content_32 = {
    Text = "Die Macht, die Macht hinter der Tür... Die Zwillingsstatuen werden bald verschmelzen"
  },
  AvgDialog_60842_Content_33 = {
    Text = "Missaga... Hüter des Geheimnisses... und diese sündige Welt, begrüßt die endgültige Reinigung!"
  },
  AvgDialog_60842_Content_34 = {Text = "Ding—"},
  AvgDialog_60842_Content_35 = {
    Text = "Sonate, beginne."
  },
  AvgDialog_60842_Content_36 = {Text = "!!!"},
  AvgDialog_60842_Content_37 = {
    Text = "Als ob zehntausende Musiker gleichzeitig ihre Instrumente spielten – Streicher, Holzbläser, Schlagzeug – vermischten sich ihre Klänge zu einem mächtigen, strömenden Fluss."
  },
  AvgDialog_60842_Content_38 = {
    Text = "Der Fluss strömt und trifft auf die schwache Verbindung zwischen Tür und Zwillingsstatuen"
  },
  AvgDialog_60842_Content_39 = {Text = "Husten—"},
  AvgDialog_60842_Content_4 = {
    Text = "Die schwarze Pfütze schwankt. Die Kuppel schwankt. Es scheint, als zittert die gesamte Mythag, der gesamte Kontinent, unter Juliette's Gesang"
  },
  AvgDialog_60842_Content_40 = {
    Text = "Ein Schwall Blut spritzte aus Hamelns Mund und befleckte seinen Kragen und seinen Stock."
  },
  AvgDialog_60842_Content_41 = {
    Text = "Die Musik kollidierte mit der Kraft der Tür, der intensive Aufprall war zu viel für Hameln, um ihn zu ertragen."
  },
  AvgDialog_60842_Content_42 = {
    Text = "Der normalerweise akribische Dirigent schenkte seinem aktuellen zerrissenen Zustand keine Beachtung. Sein Blick war auf die Tür gerichtet, und seine Bewegungen mit dem Taktstock zeigten keine Zögerlichkeit."
  },
  AvgDialog_60842_Content_43 = {
    Text = "Ströme der Musik prallen unermüdlich gegen die feste Wand."
  },
  AvgDialog_60842_Content_44 = {Text = "Boom—"},
  AvgDialog_60842_Content_45 = {
    Text = "Die Zwillingsstatuen zittern. Unter dem Aufprall des musikalischen Stroms erscheint ein Riss in dem entscheidenden und fragilen Zusammenhang zwischen der Tür und den Statuen im entscheidendsten Moment ihrer Entstehung."
  },
  AvgDialog_60842_Content_46 = {
    Text = "Die gefährliche Aura, die von der Statue ausgeht, hat merklich nachgelassen. Die Statuen, die sich auf den Mittelpunkt zubewegen, haben ihre Bewegungen eingestellt."
  },
  AvgDialog_60842_Content_47 = {
    Text = "Das vertraute Gesicht tritt aus den Schatten und steht erneut an deiner Seite."
  },
  AvgDialog_60842_Content_48 = {
    Text = "Die Zeit ist gekommen. Die letzte Aufführung beginnt bald"
  },
  AvgDialog_60842_Content_49 = {
    Text = "Er schwingt sanft den Taktstock. Ein sanfter Klang dringt in deine Geisterwelt ein"
  },
  AvgDialog_60842_Content_5 = {
    Text = "Im erdbebengleichen Beben schaust du nach oben auf das zunehmend majestätische Werk vor dir"
  },
  AvgDialog_60842_Content_50 = {
    Text = "Die schweren Fesseln und der Schmerz verschwanden plötzlich, du bist wieder in einer heißen Quelle und dein Geist füllt sich erneut mit einer noch mächtigeren Geisterkraft"
  },
  AvgDialog_60842_Content_51 = {
    Text = "Du... hast du meine Geisterverbindung nicht durchbrochen?"
  },
  AvgDialog_60842_Content_52 = {
    Text = "Vorher habe ich deine Verbindungsfähigkeit vorübergehend unterbrochen. Ein Trick, um Juliette zu täuschen"
  },
  AvgDialog_60842_Content_53 = {
    Text = "Deine Beschränkungen sind aufgehoben. Jetzt ist die Tür offen, alle Vorbereitungen sind abgeschlossen"
  },
  AvgDialog_60842_Content_54 = {
    Text = "Er stand vor dir, in seinen ruhigen Augen brannte ein leidenschaftliches Feuer"
  },
  AvgDialog_60842_Content_55 = {
    Text = "Er hielt den Taktstock hinter seinem Rücken und verbeugte sich vor dir"
  },
  AvgDialog_60842_Content_56 = {
    Text = "Blinder Blick, Vollstrecker des höchsten Willens. Dirigent Hameln, zu Ihren Diensten."
  },
  AvgDialog_60842_Content_57 = {
    Text = "Ich werde dir helfen, deine rechtmäßige Autorität zurückzuerlangen."
  },
  AvgDialog_60842_Content_58 = {
    Text = "Du... du weißt..."
  },
  AvgDialog_60842_Content_59 = {
    Text = "Die Ankunft des obersten Willens ist unvermeidlich, nur du kannst ihm entgegentreten"
  },
  AvgDialog_60842_Content_6 = {
    Text = "Zwillinge... Statue"
  },
  AvgDialog_60842_Content_60 = {
    Text = "Lass die Zwillinge erscheinen, und die Tür öffne sich, damit du die Fähigkeit zurückgewinnen kannst, gegen Ihn zu kämpfen"
  },
  AvgDialog_60842_Content_61 = {
    Text = "In der Not, entschuldige bitte mein vorheriges Fehlverhalten"
  },
  AvgDialog_60842_Content_62 = {
    Text = "Hameln! Was... was machst du da?!!"
  },
  AvgDialog_60842_Content_63 = {
    Text = "Tun, was ich tun muss"
  },
  AvgDialog_60842_Content_64 = {
    Text = "Die Statue wurde in ihrem verletzlichsten Moment beschädigt, was es deinem Gott erschwert, deinen Ruf zu hören."
  },
  AvgDialog_60842_Content_65 = {
    Text = "Er ist nur ein Fragment! Nur mit meiner Methode kann der wahre oberste Wille erweckt werden"
  },
  AvgDialog_60842_Content_66 = {
    Text = "Du solltest die höchste Melodie, die du vom obersten Willen hören wolltest, nicht vergessen haben! Hameln, du hast deinen Glauben verraten!"
  },
  AvgDialog_60842_Content_67 = {
    Text = "Gott ist nicht unbedingt größer als seine Fragmente. Das ist auch nicht, was ich möchte, meine Damen Juliette"
  },
  AvgDialog_60842_Content_68 = {
    Text = "Früher dachte ich, das Requiem des höchsten Willens sei der größte Klang im Universum. Jetzt merke ich, dass wahre höchste Kunst sich selbst übersteigt."
  },
  AvgDialog_60842_Content_69 = {
    Text = "Er hebt den Kopf, seine Augen brennen vor wilder Flamme, und er schaut ruhig auf Juliette"
  },
  AvgDialog_60842_Content_7 = {
    Text = "Zwei weiße humanoide Statuen erscheinen langsam aus der schwarzen Pfütze, dass die gesamte schwarze Pfütze erbebt"
  },
  AvgDialog_60842_Content_70 = {
    Text = "Es wird im Kampf ertönen – der Konflikt zwischen Menschheit und Gottheit. Die Konfrontation zwischen Fragmenten und dem Ursprünglichen"
  },
  AvgDialog_60842_Content_71 = {
    Text = "Gegen den obersten Willen kämpfen, mit dem obersten Willen im Duett spielen... das wird eine erhabenere Melodie als das Requiem des obersten Willens sein!"
  },
  AvgDialog_60842_Content_72 = {Text = "Seit wann"},
  AvgDialog_60842_Content_73 = {
    Text = "Im Frühling des Akut erlebten wir die Explosion."
  },
  AvgDialog_60842_Content_74 = {
    Text = "An diesem Tag hörte ich es... eine Melodie, die ewiger ist als jedes Requiem, die ich gesucht hatte."
  },
  AvgDialog_60842_Content_75 = {
    Text = "Ich hörte damals nur die Einleitung. Heute wird es in seiner Gesamtheit die Welt durchdringen."
  },
  AvgDialog_60842_Content_76 = {
    Text = "Hamelns ruhige Stimme zittert unkontrolliert"
  },
  AvgDialog_60842_Content_77 = {
    Text = "Also, seit diesem Tag planst du den Verrat"
  },
  AvgDialog_60842_Content_78 = {
    Text = "Gott hat seine Musik bereits vergessen. Er ist nur ein unbewusster Chaos-Körper, eine große Katastrophe"
  },
  AvgDialog_60842_Content_79 = {
    Text = "All seine Schönheit, all seine Weisheit liegt in seinen Fragmenten."
  },
  AvgDialog_60842_Content_8 = {
    Text = "Im Spalt in der Mitte der Statue ist Ramonas Körper mit Tawils Schale umschlungen und eingehüllt."
  },
  AvgDialog_60842_Content_80 = {
    Text = "Ich bin loyal zur Musik, zur Schönheit und zur Wahrheit. Ich habe dir niemals untreu gewesen, Juliette."
  },
  AvgDialog_60842_Content_81 = {
    Text = "Ihre Taten sind unentschuldbar."
  },
  AvgDialog_60842_Content_82 = {
    Text = "Warum... wenn du mir von Anfang an geholfen hättest, wäre Ramona nicht"
  },
  AvgDialog_60842_Content_83 = {
    Text = "Hameln, ich kann dir nicht vergeben, was du getan hast."
  },
  AvgDialog_60842_Content_84 = {
    Text = "Warum hast du das getan?"
  },
  AvgDialog_60842_Content_85 = {
    Text = "Warum... wenn du mir von Anfang an geholfen hättest, wäre Ramona nicht"
  },
  AvgDialog_60842_Content_86 = {
    Text = "Er sah ruhig auf Juliette, den Koloss und die Tür hinter dem Koloss"
  },
  AvgDialog_60842_Content_87 = {
    Text = "Er stand neben dir"
  },
  AvgDialog_60842_Content_88 = {
    Text = "Hüter {Male=Herr,Female=Frau}, Juliette aufzuhalten, kann nur die Ankunft des obersten Willens hinauszögern. Chronischer Tod, ohne Bedeutung"
  },
  AvgDialog_60842_Content_89 = {
    Text = "Lass Juliette die Tür beschwören, damit du deine Autorität reibungslos zurückerlangen kannst. Das ist der einzige Weg."
  },
  AvgDialog_60842_Content_9 = {
    Text = "Zwei herrenlose Körper verschmelzen zu einer riesigen schwarz-weißen Statue, die zwischen den großen Halbbüsten schwebt"
  },
  AvgDialog_60842_Content_90 = {
    Text = "Wir suchen nach unterschiedlichen Dingen, aber ob höchste Musik oder der Fortbestand der Welt, es gibt nur diese eine Chance"
  },
  AvgDialog_60842_Content_91 = {
    Text = "In dieser unausweichlichen Aufführung sind du, ich, Frau Ramona und alle hier lediglich Musiker."
  },
  AvgDialog_60842_Content_92 = {
    Text = "Ich verlange nicht dein Verständnis oder deine Verzeihung. Ich übernehme die Verantwortung für jede Note, die ich spiele."
  },
  AvgDialog_60842_Content_93 = {
    Text = "Bis dahin werde ich dir helfen, Juliette aufzuhalten und Ramona zu retten."
  },
  AvgDialog_60842_Content_94 = {
    Text = "Du weißt, dass Hameln recht hat. Für die Kontinuität der Welt zögert Ramona nie, sich selbst zu opfern.\nAber du tust es."
  },
  AvgDialog_60842_Content_95 = {
    Text = "Wenn Sie den Anstieg der Spirit-Energie in sich spüren, schauen Sie auf die gewaltige Statue."
  },
  AvgDialog_60842_Content_96 = {
    Text = "Niemand kann sich ihm nähern... Meine Anhänger, meine \"Hunde\", blockieren sie!"
  },
  AvgDialog_60886_Content_1 = {
    Text = "Das ist auch eine Wahl, eine Richtung der Geschichte"
  },
  AvgDialog_60886_Content_10 = {
    Text = "Ein engagierter Schauspieler. Neunzehn Jahre lang die gleiche Rolle gespielt, ohne jemals nachzulassen, für die wunderbare Wendung der Geschichte"
  },
  AvgDialog_60886_Content_11 = {Text = "Jetzt"},
  AvgDialog_60886_Content_12 = {
    Text = "Meine lieben Zuschauer, schenkt mir euren lautesten Applaus"
  },
  AvgDialog_60886_Content_13 = {
    Text = "Der schwarze Nebel umgab sie wie ein Applaus"
  },
  AvgDialog_60886_Content_14 = {
    Text = "Vor dir erscheint ein Gesicht, das du schon einmal gesehen hast und das dir unzählige Albträume beschert hat"
  },
  AvgDialog_60886_Content_15 = {
    Text = "Das gesichtslose Grinsen genießt gierig deine Bestürzung und Angst"
  },
  AvgDialog_60886_Content_16 = {
    Text = "Du bist... N!"
  },
  AvgDialog_60886_Content_17 = {
    Text = "Ein Titel, für meine unzähligen Inkarnationen ist das eine Beleidigung... aber nenn mich, wie du willst"
  },
  AvgDialog_60886_Content_18 = {
    Text = "Was hast du mit Professor Dexter gemacht!"
  },
  AvgDialog_60886_Content_19 = {
    Text = "Professor Dexter? Wer ist Professor Dexter?"
  },
  AvgDialog_60886_Content_2 = {
    Text = "Aber wenn wir sie wirklich retten, wird die Geschichte nicht mehr so spannend sein, oder?"
  },
  AvgDialog_60886_Content_20 = {
    Text = "Geheimnisträger, kennst du und Ramona wirklich Dexter?"
  },
  AvgDialog_60886_Content_21 = {
    Text = "Was meinst du... wie könnten wir... etwa?!"
  },
  AvgDialog_60886_Content_22 = {
    Text = "Du erinnerst dich an Ns Worte. Neunzehn Jahre lang hat er dieselbe Rolle gespielt"
  },
  AvgDialog_60886_Content_23 = {
    Text = "Die Pupillen ziehen sich scharf zusammen. Du hebst plötzlich den Kopf und siehst auf N's gesichtslosen Körper"
  },
  AvgDialog_60886_Content_24 = {
    Text = "Sehr gut, Geheimnishüter. Genau dieser Ausdruck!"
  },
  AvgDialog_60886_Content_25 = {
    Text = "Beweg dich nicht, bleib so. Ja, genau... Lass mich dich so in Erinnerung behalten"
  },
  AvgDialog_60886_Content_26 = {
    Text = "Schade, dass Ramona, als sie davon erfuhr, noch nicht erwacht war. Ich konnte ihren Gesichtsausdruck nicht sehen"
  },
  AvgDialog_60886_Content_27 = {
    Text = "Ich denke, ihr Ausdruck ist wahrscheinlich genauso interessant wie deiner"
  },
  AvgDialog_60886_Content_28 = {
    Text = "Ns Körper zitterte leicht, als würde er mit starkem Lachen kämpfen"
  },
  AvgDialog_60886_Content_29 = {
    Text = "Er beugte sich vor, kam dir nahe und betrachtete dich genau"
  },
  AvgDialog_60886_Content_3 = {
    Text = "Sorge, Sehnsucht, Trauer... alles verschwand aus Dexters Gesicht"
  },
  AvgDialog_60886_Content_30 = {
    Text = "Du... warum kontrollierst du Professor Dexter?"
  },
  AvgDialog_60886_Content_31 = {
    Text = "Kontrolle? Oh nein. Kontrolle ist eine minderwertige Unterhaltung"
  },
  AvgDialog_60886_Content_32 = {
    Text = "Ein guter Schauspieler muss spielen und werden"
  },
  AvgDialog_60886_Content_33 = {
    Text = "Er beugte sich zu deinem Ohr und flüsterte dir ein großes Geheimnis zu—"
  },
  AvgDialog_60886_Content_34 = {
    Text = "Dexter starb vor langer Zeit, am Tag, an dem er Ramona rettete."
  },
  AvgDialog_60886_Content_35 = {
    Text = "In all diesen Jahren, du und Ramona, ihr habt sicher eine gute Zeit mit mir gehabt, oder?"
  },
  AvgDialog_60886_Content_36 = {
    Text = "Sein Gesicht war dir zugewandt. Auf diesem leeren Gesicht schienen die arroganten Züge deutlich sichtbar"
  },
  AvgDialog_60886_Content_37 = {
    Text = "Er beugte sich vor, um dir ins Gesicht zu sehen, betrachtete dich aufmerksam, als wolle er jeden deiner Ausdrücke, jedes unkontrollierbare Zucken festhalten"
  },
  AvgDialog_60886_Content_38 = {
    Text = "Ein charmanter Playboy, ein liebevoller Vater, solche Rollen interessieren mich eigentlich nicht"
  },
  AvgDialog_60886_Content_39 = {
    Text = "Ich interessiere mich nur für sie... meine „Tochter“. Tawils Zwillingsrelikt, Ramona"
  },
  AvgDialog_60886_Content_4 = {
    Text = "Du siehst, wie er dir ein perfektes, aber kaltes Lächeln zeigt"
  },
  AvgDialog_60886_Content_40 = {
    Text = "N lächelte in Richtung der Mitte der schwarzen Pfütze, in Richtung Tawil"
  },
  AvgDialog_60886_Content_41 = {
    Text = "Du... warum hast du ihn getötet"
  },
  AvgDialog_60886_Content_42 = {
    Text = "Dein Missverständnis ist so traurig, Geheimnishüter"
  },
  AvgDialog_60886_Content_43 = {
    Text = "Der Zwillingsplan der Laterne ist nichts, womit ein schwacher Playboy leicht fertig wird. Aber er konnte das Baby stehlen"
  },
  AvgDialog_60886_Content_44 = {
    Text = "Als er mich sah, leuchteten seine Augen wie die eines Erlösers... Ha"
  },
  AvgDialog_60886_Content_45 = {
    Text = "N erinnerte sich an die Geschichte und lächelte erfreut"
  },
  AvgDialog_60886_Content_46 = {
    Text = "Er machte mir ein Angebot. Kannst du das glauben? Ein sterblicher Mensch, der mir ein Angebot macht"
  },
  AvgDialog_60886_Content_47 = {
    Text = "Er hat mir alles gegeben. Sein Vermögen, seinen Status, seine Tochter"
  },
  AvgDialog_60886_Content_48 = {
    Text = "Er ließ mich ihn spielen, den Vater seiner Tochter"
  },
  AvgDialog_60886_Content_49 = {
    Text = "Er starb, während er das Baby hielt. Im Sterben murmelte er immer wieder, dass der Vater sie gut beschützen würde"
  },
  AvgDialog_60886_Content_5 = {
    Text = "Professor Dexter würde so etwas nie sagen... Wer sind Sie wirklich?!"
  },
  AvgDialog_60886_Content_50 = {
    Text = "Der Verräter von Missaga... bist du es?"
  },
  AvgDialog_60886_Content_51 = {
    Text = "N zuckt gleichgültig mit den Schultern, als er deine verwirrten und wütenden Augen sieht"
  },
  AvgDialog_60886_Content_52 = {
    Text = "Ich oder nicht ich, spielt das eine Rolle? Schwer zu glauben, dass du dir darüber noch Gedanken machst"
  },
  AvgDialog_60886_Content_53 = {
    Text = "Als Dexter zu spielen und nahe bei Missaga zu bleiben, ist wirklich praktisch"
  },
  AvgDialog_60886_Content_54 = {
    Text = "Dieser Ort ist der interessanteste Vergnügungspark der Welt"
  },
  AvgDialog_60886_Content_55 = {
    Text = "Ich wollte sehen, wie ihr ausseht, als ich euch täuschte. Schau dir Tawils gescheiterte Pläne an und ihre gescheiterte Haltung"
  },
  AvgDialog_60886_Content_56 = {
    Text = "Natürlich, und du"
  },
  AvgDialog_60886_Content_57 = {
    Text = "Er sah dich an, leckte sich die Lippen, wie ein unschuldiges Kind, das ein Spielzeug zerstören will"
  },
  AvgDialog_60886_Content_58 = {
    Text = "Thais hat dir ihren Samen geschenkt, sie glaubte wirklich, du könntest sie am Leben halten... ha, diese verrückte Frau"
  },
  AvgDialog_60886_Content_59 = {
    Text = "Sehr schade, sie hat den falschen Menschen vertraut. Ich nehme die Macht der Fortpflanzung an mich"
  },
  AvgDialog_60886_Content_6 = {
    Text = "Er kam auf dich zu, seine vertrauten Augen mit einem fremden Lächeln"
  },
  AvgDialog_60886_Content_60 = {
    Text = "Lass mich sehen, welches Gesicht du machst, wenn die Hoffnung erlischt"
  },
  AvgDialog_60886_Content_7 = {
    Text = "Ein schwarzer Rauch stieg von ihm auf und hüllte ihn langsam ein"
  },
  AvgDialog_60886_Content_8 = {
    Text = "Ja, wer bin ich eigentlich"
  },
  AvgDialog_60886_Content_9 = {
    Text = "Großzügiger Aktionär. Besorgter Vater. Berühmter Playboy. Beliebter Misaq-Professor."
  },
  AvgDialog_60887_Content_1 = {
    Text = "Es gibt nur diesen einen Weg"
  },
  AvgDialog_60887_Content_10 = {
    Text = "Nach dieser Stimme ertönt majestätische Musik aus eurem Bewusstsein"
  },
  AvgDialog_60887_Content_12 = {Text = "!!!"},
  AvgDialog_60887_Content_13 = {
    Text = "Das... das ist..."
  },
  AvgDialog_60887_Content_14 = {
    Text = "Verstaue deinen Silberschlüssel. Aktivierst du ihn jetzt, stirbst du"
  },
  AvgDialog_60887_Content_15 = {
    Text = "Takt. Melodie. Die sanften Obertöne der Streicher füllen eure Gedanken"
  },
  AvgDialog_60887_Content_16 = {
    Text = "Das ist ein mysteriöses Frequenzband. Die Leute des Ausschusses fallen schmerzhaft zu Boden bei dieser Musik, während du dich fühlst, als wärst du von Thermalwasser umhüllt und gereinigt"
  },
  AvgDialog_60887_Content_17 = {
    Text = "Du spürst deutlich, dass die Verbindung zu den Erweckern wiederhergestellt ist. Die Wellen von der schwarzen Pfütze scheinen ebenfalls in diesem Klang zu verschwinden"
  },
  AvgDialog_60887_Content_18 = {
    Text = "Clementine schaut überrascht in Richtung der Stimme"
  },
  AvgDialog_60887_Content_19 = {
    Text = "Du bist es! Warum"
  },
  AvgDialog_60887_Content_2 = {
    Text = "Fang {Male=er,Female=sie}"
  },
  AvgDialog_60887_Content_20 = {
    Text = "Schlagzeug, Stopp"
  },
  AvgDialog_60887_Content_21 = {
    Text = "Der Mann schwang leicht den Taktstock. Ein kurzer, kraftvoller Befehlston brachte einen Moment der Stille"
  },
  AvgDialog_60887_Content_22 = {
    Text = "Clementine bricht zusammen und fällt zu Boden"
  },
  AvgDialog_60887_Content_23 = {Text = "Du... bist"},
  AvgDialog_60887_Content_24 = {
    Text = "Andere werden bald hier sein, meine Musik hält nicht lange"
  },
  AvgDialog_60887_Content_25 = {
    Text = "Ich werde dich an einen sicheren Ort bringen"
  },
  AvgDialog_60887_Content_26 = {
    Text = "Er drehte sich um, nickte dir leicht zu, sein Gesichtsausdruck war ruhig wie ein stiller See"
  },
  AvgDialog_60887_Content_27 = {
    Text = "Dirigent Hameln, zu Ihren Diensten."
  },
  AvgDialog_60887_Content_3 = {
    Text = "Du hebst deine Hand."
  },
  AvgDialog_60887_Content_4 = {
    Text = "Ich werde dich nicht lassen..."
  },
  AvgDialog_60887_Content_5 = {
    Text = "Zweiter Satz, Anfang"
  },
  AvgDialog_60887_Content_6 = {Text = "Hmm—"},
  AvgDialog_60887_Content_7 = {Text = "?!"},
  AvgDialog_60887_Content_8 = {
    Text = "Bevor der silberne Schlüssel in deiner Hand aufleuchten konnte, hörtest du eine kühle Stimme hinter dir"
  },
  AvgDialog_60887_Content_9 = {
    Text = "Diese Stimme ist die Spur des Dirigenten, das unumstößliche Gesetz in der Welt der Noten"
  },
  AvgDialog_60888_Content_1 = {
    Text = "Große Sache... eine große Sache ist passiert"
  },
  AvgDialog_60888_Content_10 = {
    Text = "Eine Minute und fünfzehn Sekunden, der Applaus des Publikums wird donnern und allmählich verklingen"
  },
  AvgDialog_60888_Content_11 = {
    Text = "In fünfundzwanzig Minuten werden das Orchester und das Publikum den Saal verlassen haben"
  },
  AvgDialog_60888_Content_12 = {
    Text = "Die Zeit ist genau wie geplant, wie eine zweite präzise Aufführung"
  },
  AvgDialog_60888_Content_13 = {
    Text = "Der Dirigent nickte zufrieden und verbeugte sich vor dem leeren Zuschauerraum"
  },
  AvgDialog_60888_Content_14 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_60888_Content_15 = {
    Text = "In einer unauffälligen Ecke des Zuschauerraums ertönte erneut ein leiser Applaus"
  },
  AvgDialog_60888_Content_16 = {
    Text = "Eine großartige Vorstellung, Herr Hameln"
  },
  AvgDialog_60888_Content_17 = {
    Text = "Vielleicht war es vollständig, aber noch lange nicht großartig. Die wahre Meistervorstellung findet außerhalb des Theaters statt"
  },
  AvgDialog_60888_Content_18 = {
    Text = "Der Dirigent legte den Taktstock weg und schaute mit gerunzelter Stirn zur Dame an der Seite des Zuschauerraums"
  },
  AvgDialog_60888_Content_19 = {
    Text = "Wir haben es vorher gesagt, du solltest nicht im Theater sein, Frau Juliette"
  },
  AvgDialog_60888_Content_2 = {
    Text = "Wir müssen es allen sagen... und dem Geheimnisträger!"
  },
  AvgDialog_60888_Content_20 = {
    Text = "Unsere Zusammenarbeit hat nichts mit der Aufführung zu tun, ich möchte keine Störungen. Ich dachte, das wäre dir klar"
  },
  AvgDialog_60888_Content_21 = {
    Text = "Deine Anwesenheit hier könnte unnötige Probleme verursachen"
  },
  AvgDialog_60888_Content_22 = {
    Text = "Natürlich, Herr Hameln. Ich wäre sehr bedauert, wenn ich Ihre Aufführung nicht vor Ort hören würde"
  },
  AvgDialog_60888_Content_23 = {
    Text = "Juliette lächelte und nickte, während sie sanft die Falten ihres Kleidungsstückes glattstrich"
  },
  AvgDialog_60888_Content_24 = {
    Text = "An die Ausdrucksweise von Hameln hat sie sich längst gewöhnt und kümmert sich nicht darum"
  },
  AvgDialog_60888_Content_25 = {
    Text = "Ich habe auch wichtige Dinge, die ich dir persönlich mitteilen muss"
  },
  AvgDialog_60888_Content_26 = {
    Text = "Hat die Aktion begonnen?"
  },
  AvgDialog_60888_Content_27 = {
    Text = "Richtig. Clementine hat die Patrouillen von Missaga problemlos erledigt, wir haben mehr Zeit gewonnen als erwartet"
  },
  AvgDialog_60888_Content_28 = {
    Text = "Dein Plan war sehr erfolgreich"
  },
  AvgDialog_60888_Content_29 = {
    Text = "Nur ein nicht allzu kompliziertes Vorspiel, es ist zu früh, um von Erfolg zu sprechen"
  },
  AvgDialog_60888_Content_3 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_60888_Content_30 = {
    Text = "Ich vertraue auf deine Weisheit, Herr Dirigent"
  },
  AvgDialog_60888_Content_31 = {
    Text = "Wie lange haben wir auf diesen Tag gewartet?"
  },
  AvgDialog_60888_Content_32 = {
    Text = "Neunzehn Jahre."
  },
  AvgDialog_60888_Content_33 = {
    Text = "Stimmt, neunzehn Jahre. Eine lange Zeit"
  },
  AvgDialog_60888_Content_34 = {
    Text = "Das Spiel zwischen den Bildhauern und Seefahrern hat genug Aufmerksamkeit auf sich gezogen; unsere Anwesenheit ist gut verborgen."
  },
  AvgDialog_60888_Content_35 = {
    Text = "Remouahes Plan ist gescheitert, was bedauerlich, aber letztendlich belanglos ist."
  },
  AvgDialog_60888_Content_36 = {
    Text = "Wichtig ist nur heute – neunzehn Jahre später"
  },
  AvgDialog_60888_Content_37 = {
    Text = "Es ist eine Freude, diesen wichtigen Moment mit einem Partner wie dir zu erleben"
  },
  AvgDialog_60888_Content_38 = {
    Text = "Unser Ziel ist dasselbe. Diese Aufführung ist nicht für uns"
  },
  AvgDialog_60888_Content_39 = {
    Text = "Um die Musik dieses großen Wesens wieder zu hören, ist jeder Einsatz unbedeutend"
  },
  AvgDialog_60888_Content_4 = {
    Text = "Der Taktstock des Dirigenten zog eine sanfte Kurve in der Luft. Das Musikstück kam zum Ende"
  },
  AvgDialog_60888_Content_40 = {
    Text = "Drehen, stehen. Der junge Dirigent hebt die Hände und verbeugt sich vor dem leeren Theater, vor den unbekannten Tiefen des Sternenhimmels außerhalb des Theaters"
  },
  AvgDialog_60888_Content_41 = {
    Text = "Alles ist bereit, machen wir uns auf den Weg, Frau Juliette"
  },
  AvgDialog_60888_Content_42 = {
    Text = "Die wahre Aufführung beginnt jetzt"
  },
  AvgDialog_60888_Content_5 = {
    Text = "Die intensiven Akkorde und die komplexen mehrstimmigen Klanglandschaften beruhigen sich"
  },
  AvgDialog_60888_Content_6 = {
    Text = "Arpeggien von Flöte und Harfe schwebten sanft hinaus, wie die Wolken im Abendlicht"
  },
  AvgDialog_60888_Content_7 = {
    Text = "Harmonische, lang anhaltende Akkorde verflüchtigen sich langsam in der Luft, und das letzte Zeichen der Streicher bringt die Noten zum Abschluss"
  },
  AvgDialog_60888_Content_8 = {
    Text = "In diesem fernen Moment legte der Dirigent seinen Taktstock weg. Er berechnete schweigend"
  },
  AvgDialog_60888_Content_9 = {
    Text = "Zehn Sekunden, das Publikum versunken in die Musik, das Theater in morgendlicher Stille"
  },
  AvgDialog_60889_Content_1 = {
    Text = "Im langen Korridor ist niemand zu sehen. Schwere Atem- und Schritte hallen wider"
  },
  AvgDialog_60889_Content_10 = {
    Text = "Sag sowas nicht, Direktor"
  },
  AvgDialog_60889_Content_11 = {
    Text = "Wenn wir euch im Gebäude der Lebenswissenschaften unterbringen, können wir"
  },
  AvgDialog_60889_Content_12 = {
    Text = "Brauchen Sie eine Mitfahrgelegenheit, Miss Ramona?"
  },
  AvgDialog_60889_Content_13 = {Text = "!!!"},
  AvgDialog_60889_Content_14 = {Text = "Vorsicht!"},
  AvgDialog_60889_Content_15 = {
    Text = "Ramona hebt ihr Schwert und hält es vor sich"
  },
  AvgDialog_60889_Content_16 = {
    Text = "Hinter ihr blickt Sylvia mit zusammengekniffenen Augen, während sie den geschwächten Czort beschützt."
  },
  AvgDialog_60889_Content_17 = {
    Text = "Eilige Schritte ertönten, als hätten sie hier lange auf der Lauer gelegen"
  },
  AvgDialog_60889_Content_18 = {
    Text = "Am Ende des schmalen Korridors steht eine dichte Menge von Agenten in Ausschussuniform, die ihren Weg blockieren"
  },
  AvgDialog_60889_Content_19 = {
    Text = "Der einäugige Mann geht zur Menge und streichelt sanft die zweiköpfige, haarlose Katze auf seiner Schulter"
  },
  AvgDialog_60889_Content_2 = {
    Text = "Huh... Dekan czort, halte durch, wir sind fast da"
  },
  AvgDialog_60889_Content_20 = {
    Text = "Es ist... du..."
  },
  AvgDialog_60889_Content_21 = {
    Text = "Als er das Gesicht vor sich sah, spannte sich Herlet sofort an"
  },
  AvgDialog_60889_Content_22 = {
    Text = "Herbert... du Bastard..."
  },
  AvgDialog_60889_Content_23 = {
    Text = "Professor Crowley behandelte dich wie sein eigenes Kind, und du hast ihm das angetan. Und jetzt kommst du zurück"
  },
  AvgDialog_60889_Content_24 = {
    Text = "Pssst, Klassenkamerad czort... oh nein, ich sollte dich Dekan czort nennen"
  },
  AvgDialog_60889_Content_25 = {
    Text = "Nach meinem Weggang ist der Posten des Direktors natürlich für dich bestimmt"
  },
  AvgDialog_60889_Content_26 = {
    Text = "Ich würde gerne mit dir über alte Zeiten plaudern, aber ich habe heute noch andere Aufgaben"
  },
  AvgDialog_60889_Content_27 = {
    Text = "Sein Blick richtete sich auf Ramona"
  },
  AvgDialog_60889_Content_28 = {
    Text = "Lange nicht gesehen, ich habe Sie sehr vermisst, Miss Ramona"
  },
  AvgDialog_60889_Content_29 = {
    Text = "Aber wir haben uns nur ein paar Mal getroffen, nicht so vertraut"
  },
  AvgDialog_60889_Content_3 = {
    Text = "Ramona, deine Wunde"
  },
  AvgDialog_60889_Content_30 = {
    Text = "Diese Zeit? Nein, nein"
  },
  AvgDialog_60889_Content_31 = {
    Text = "Ich erinnere mich, dass ich dich das erste Mal gesehen habe, scheint es in diesem Durchgang gewesen zu sein"
  },
  AvgDialog_60889_Content_32 = {
    Text = "Damals warst du noch... so klein"
  },
  AvgDialog_60889_Content_33 = {
    Text = "Herbert streckte die Hände aus und zeigte die Länge einer haarlosen Katze"
  },
  AvgDialog_60889_Content_34 = {
    Text = "Was meinst du...?"
  },
  AvgDialog_60889_Content_35 = {
    Text = "Meine Schöpfung. Mein Kind"
  },
  AvgDialog_60889_Content_36 = {
    Text = "Helot ist ein gescheitertes Produkt. In meiner Zusammenarbeit mit der Tempel Licht Kirche bist du die perfekte Schöpfung."
  },
  AvgDialog_60889_Content_37 = {
    Text = "Ich verstehe nicht..."
  },
  AvgDialog_60889_Content_38 = {
    Text = "Verstehst du es immer noch nicht, Ramona?"
  },
  AvgDialog_60889_Content_39 = {
    Text = "Die Menschen, die dir wichtig sind, wurden erschreckt, verletzt und stehen unter dem Druck von Kontrollverlust und Tod... All diese Katastrophen, die Mythisch erlitten hat, sind wegen dir"
  },
  AvgDialog_60889_Content_4 = {
    Text = "Sie nahm ein Tuch und wischte das Blut von Ramonas Arm"
  },
  AvgDialog_60889_Content_40 = {
    Text = "Du... was sagst du?"
  },
  AvgDialog_60889_Content_41 = {
    Text = "Beim Anblick des zitternden Schwertes in Ramonas Hand lächelte Herbert und machte zwei Schritte nach vorne"
  },
  AvgDialog_60889_Content_42 = {
    Text = "Vor vielen Jahren stahl Dexter, dieser Dieb, dich von uns"
  },
  AvgDialog_60889_Content_43 = {
    Text = "Dieser Tag kam spät, aber das macht nichts – er kam genau zur richtigen Zeit"
  },
  AvgDialog_60889_Content_44 = {
    Text = "Du bist ein wertvolles Zwilling, die perfekte Schöpfung der Lampe"
  },
  AvgDialog_60889_Content_5 = {
    Text = "Ah... Entschuldigung."
  },
  AvgDialog_60889_Content_6 = {
    Text = "Gerade als ich gegen diese Leute vom Ausschuss kämpfte, war ich kurz unaufmerksam"
  },
  AvgDialog_60889_Content_7 = {
    Text = "Die Unruhe der schwarzen Pfütze hat dich betroffen, nicht wahr?"
  },
  AvgDialog_60889_Content_8 = {
    Text = "Nur ein kleines bisschen."
  },
  AvgDialog_60889_Content_9 = {
    Text = "Ramona, entschuldige die Umstände. Wenn ich nicht verletzt wäre, könnte ich dir vielleicht etwas helfen"
  },
  AvgDialog_60890_Content_1 = {
    Text = "Du bist im Sturm"
  },
  AvgDialog_60890_Content_10 = {
    Text = "Ein scharfer Schrei hallt über die schwarze Pfütze. Der Stab, der Wissen repräsentiert, vibriert mit dem Schrei"
  },
  AvgDialog_60890_Content_11 = {
    Text = "Unzählige weiße Schemen, aus verschiedenen Dimensionen und Zeiten gefangen, verschmelzen in der schwarz-weißen Statue"
  },
  AvgDialog_60890_Content_12 = {
    Text = "Sehr bald verstummten alle Schreie und Vibrationen"
  },
  AvgDialog_60890_Content_13 = {
    Text = "Niemand kann ihm entkommen, Tawil"
  },
  AvgDialog_60890_Content_14 = {
    Text = "Komm, lasst uns gemeinsam seine Geburt feiern!"
  },
  AvgDialog_60890_Content_15 = {
    Text = "Als Juliette ihre Bewegung stoppte, begannen die riesigen Laternen-Zwillingsstatuen, sich zur Mitte hin zusammenzuziehen, als würden sie die Körper suchen, um sich hastig mit der schwarz-weißen Statue in der Mitte zu vereinen"
  },
  AvgDialog_60890_Content_16 = {
    Text = "Tawil! Ramona!! Ah—"
  },
  AvgDialog_60890_Content_17 = {
    Text = "Ein starkes Licht brach plötzlich auf. Hinter dem riesigen Zwillingsartefakt erschien ein Spalt"
  },
  AvgDialog_60890_Content_18 = {
    Text = "Du nimmst langsam die Hände von deinen Augen"
  },
  AvgDialog_60890_Content_19 = {
    Text = "Das ist... eine Tür?"
  },
  AvgDialog_60890_Content_2 = {
    Text = "Starke Erschütterungen lassen das Wasser der schwarzen Pfütze heftig wogen und riesige Wellen aufsteigen, die gegen dich schlagen"
  },
  AvgDialog_60890_Content_20 = {
    Text = "Die illusorische Tür hinter Tawil erlangte in diesem Moment physische Existenz"
  },
  AvgDialog_60890_Content_21 = {
    Text = "Licht strömt durch den sich öffnenden Spalt, kalt wie das Universum, rein wie die Wahrheit"
  },
  AvgDialog_60890_Content_22 = {
    Text = "Du starrst auf das Licht, Tränen fließen im grellen Licht, ohne dass du es bemerkst. Du kannst deinen Blick nicht abwenden"
  },
  AvgDialog_60890_Content_23 = {
    Text = "Tür... das Tor zu allem... das Wohnsitz des Gottes"
  },
  AvgDialog_60890_Content_24 = {
    Text = "Endlich, endlich ist dieser Tag gekommen!"
  },
  AvgDialog_60890_Content_25 = {
    Text = "Nein, die Tür darf nicht geöffnet werden"
  },
  AvgDialog_60890_Content_26 = {
    Text = "Du willst etwas tun. Du versuchst, den Silberschlüssel zu aktivieren, aber deine geistige Kraft wird unterdrückt, der Schlüssel reagiert nicht"
  },
  AvgDialog_60890_Content_28 = {
    Text = "Du starrst verzweifelt auf die Tür, die sich von verschwommen zu klar verändert und einen Spalt öffnet"
  },
  AvgDialog_60890_Content_29 = {
    Text = "Die mächtige Kraft, wie eine Flut, die die Welt zu überfluten droht, strömt aus der Tür zu den Zwillingslaternenstatuen"
  },
  AvgDialog_60890_Content_3 = {
    Text = "Die schwarze Pfütze schwankt. Die Kuppel schwankt. Es scheint, als zittert die gesamte Mythag, der gesamte Kontinent, unter Juliette's Gesang"
  },
  AvgDialog_60890_Content_30 = {
    Text = "Juliette starrte mit weit aufgerissenen Augen auf die Tür und die Statue, das Lächeln in ihrem Gesicht wurde immer grausamer"
  },
  AvgDialog_60890_Content_31 = {
    Text = "Die Macht, die Macht hinter der Tür... Die Zwillingsstatuen werden bald verschmelzen"
  },
  AvgDialog_60890_Content_32 = {
    Text = "Missaga... Hüter des Geheimnisses... und diese sündige Welt, begrüßt die endgültige Reinigung!"
  },
  AvgDialog_60890_Content_33 = {Text = "Ding—"},
  AvgDialog_60890_Content_34 = {
    Text = "Vierte Symphonie, Aufbruch"
  },
  AvgDialog_60890_Content_35 = {Text = "!!!"},
  AvgDialog_60890_Content_36 = {
    Text = "Wie zehntausende Musiker, die gleichzeitig ihre Instrumente spielen, Streicher, Bläser, Schlagzeug, verschiedene Klänge verweben sich zu einem majestätischen Fluss"
  },
  AvgDialog_60890_Content_37 = {
    Text = "Der Fluss strömt und trifft auf die schwache Verbindung zwischen Tür und Zwillingsstatuen"
  },
  AvgDialog_60890_Content_38 = {
    Text = "Die Rückwirkung der inneren Kräfte der Tür ließ die Zwillinge erzittern. Die gefährliche Aura der Statue wurde merklich schwächer"
  },
  AvgDialog_60890_Content_39 = {
    Text = "Die Statue, die sich zur Mitte bewegte, hielt inne"
  },
  AvgDialog_60890_Content_4 = {
    Text = "In diesem heftigen Schütteln hebst du den Kopf und siehst das immer grandioser werdende Gebilde vor dir"
  },
  AvgDialog_60890_Content_40 = {
    Text = "Das vertraute Gesicht tritt aus dem Schatten und erscheint wieder in deinem Blickfeld"
  },
  AvgDialog_60890_Content_41 = {
    Text = "Die Zeit ist gekommen. Die letzte Aufführung beginnt bald"
  },
  AvgDialog_60890_Content_42 = {
    Text = "Er schwingt sanft den Taktstock. Ein sanfter Klang dringt in deine Geisterwelt ein"
  },
  AvgDialog_60890_Content_43 = {
    Text = "Die schweren Fesseln und der Schmerz verschwanden plötzlich, du bist wieder in einer heißen Quelle und dein Geist füllt sich erneut mit einer noch mächtigeren Geisterkraft"
  },
  AvgDialog_60890_Content_44 = {
    Text = "Du... hast meine Geisterverbindung nicht beschädigt"
  },
  AvgDialog_60890_Content_45 = {
    Text = "Vorher habe ich deine Verbindungsfähigkeit vorübergehend unterbrochen. Ein Trick, um Juliette zu täuschen"
  },
  AvgDialog_60890_Content_46 = {
    Text = "Deine Beschränkungen sind aufgehoben. Jetzt ist die Tür offen, alle Vorbereitungen sind abgeschlossen"
  },
  AvgDialog_60890_Content_47 = {
    Text = "Er stand vor dir, in seinen ruhigen Augen brannte ein leidenschaftliches Feuer"
  },
  AvgDialog_60890_Content_48 = {
    Text = "Er hielt den Taktstock hinter seinem Rücken und verbeugte sich vor dir"
  },
  AvgDialog_60890_Content_49 = {
    Text = "Blinder Blick, der Vollstrecker des höchsten Willens. Ich werde dir helfen, deine rechtmäßige Autorität zurückzugewinnen."
  },
  AvgDialog_60890_Content_5 = {
    Text = "Zwillinge... Statue"
  },
  AvgDialog_60890_Content_50 = {
    Text = "Du... was sagst du?"
  },
  AvgDialog_60890_Content_51 = {
    Text = "Die Ankunft des obersten Willens ist unvermeidlich, nur du kannst ihm entgegentreten"
  },
  AvgDialog_60890_Content_52 = {
    Text = "Lass die Zwillinge erscheinen, und die Tür öffne sich, damit du die Fähigkeit zurückgewinnen kannst, gegen Ihn zu kämpfen"
  },
  AvgDialog_60890_Content_53 = {
    Text = "In der Not, entschuldige bitte mein vorheriges Fehlverhalten"
  },
  AvgDialog_60890_Content_54 = {
    Text = "Hameln! Was... was machst du da?!!"
  },
  AvgDialog_60890_Content_55 = {
    Text = "Tun, was ich tun muss"
  },
  AvgDialog_60890_Content_56 = {
    Text = "Er ist nur ein Fragment! Nur mit meiner Methode kann der wahre oberste Wille erweckt werden"
  },
  AvgDialog_60890_Content_57 = {
    Text = "Du solltest die höchste Melodie, die du vom obersten Willen hören wolltest, nicht vergessen haben! Hameln, du hast deinen Glauben verraten!"
  },
  AvgDialog_60890_Content_58 = {
    Text = "Gott ist nicht unbedingt größer als seine Fragmente. Das ist auch nicht, was ich möchte, meine Damen Juliette"
  },
  AvgDialog_60890_Content_59 = {
    Text = "Ich dachte einmal, dass das Requiem des obersten Willens die größte Musik im Universum sei, aber dann verstand ich endlich. Wahre, höchste Kunst übersteigt sich selbst"
  },
  AvgDialog_60890_Content_6 = {
    Text = "Zwei weiße humanoide Statuen erscheinen langsam aus der schwarzen Pfütze, dass die gesamte schwarze Pfütze erbebt"
  },
  AvgDialog_60890_Content_60 = {
    Text = "Er hebt den Kopf, seine Augen brennen vor wilder Flamme, und er schaut ruhig auf Juliette"
  },
  AvgDialog_60890_Content_61 = {
    Text = "Es wird im Kampf ertönen – der Konflikt zwischen Menschheit und Gottheit. Die Konfrontation zwischen Fragmenten und dem Ursprünglichen"
  },
  AvgDialog_60890_Content_62 = {
    Text = "Gegen den obersten Willen kämpfen, mit dem obersten Willen im Duett spielen... das wird eine erhabenere Melodie als das Requiem des obersten Willens sein!"
  },
  AvgDialog_60890_Content_63 = {Text = "Seit wann"},
  AvgDialog_60890_Content_64 = {
    Text = "Im Frühling des Akut erlebten wir die Explosion."
  },
  AvgDialog_60890_Content_65 = {
    Text = "An jenem Tag hörte ich es... Die Musik, die ich suchte, ewiger als das Requiem, die im Widerstand erklang"
  },
  AvgDialog_60890_Content_66 = {
    Text = "Damals hörte ich nur das Vorspiel. Heute wird es die Welt vollständig durchdringen"
  },
  AvgDialog_60890_Content_67 = {
    Text = "Hamelns ruhige Stimme zittert unkontrolliert"
  },
  AvgDialog_60890_Content_68 = {
    Text = "Also, seit diesem Tag planst du den Verrat"
  },
  AvgDialog_60890_Content_69 = {
    Text = "Gott hat seine Musik bereits vergessen. Er ist nur ein unbewusster Chaos-Körper, eine große Katastrophe"
  },
  AvgDialog_60890_Content_7 = {
    Text = "In der Lücke in der Mitte der Statue war Ramonas Körper mit dem Körper von Tawil umhüllt und eingewickelt"
  },
  AvgDialog_60890_Content_70 = {
    Text = "All seine Schönheit ist in seinen Fragmenten"
  },
  AvgDialog_60890_Content_71 = {
    Text = "Ich bin der Musik treu, ich habe dich nie verraten, Juliette"
  },
  AvgDialog_60890_Content_72 = {
    Text = "Er sah ruhig auf Juliette, den Koloss und die Tür hinter dem Koloss"
  },
  AvgDialog_60890_Content_73 = {
    Text = "Er stand neben dir"
  },
  AvgDialog_60890_Content_74 = {
    Text = "Warum... wenn du mir von Anfang an geholfen hättest, wäre Ramona nicht"
  },
  AvgDialog_60890_Content_75 = {
    Text = "Hüter %player%, die Ankunft des obersten Willens ist nicht aufzuhalten. Lass Juliette das Tor beschwören, um dir die Rückübertragung der Macht zu ermöglichen, ist der einzige Weg"
  },
  AvgDialog_60890_Content_76 = {
    Text = "Wir suchen nach unterschiedlichen Dingen, aber ob höchste Musik oder der Fortbestand der Welt, es gibt nur diese eine Chance"
  },
  AvgDialog_60890_Content_77 = {
    Text = "In dieser Aufführung sind du, ich, Fräulein Ramona und alle hier nur Musiker"
  },
  AvgDialog_60890_Content_78 = {
    Text = "Miss Ramona wird es verstehen."
  },
  AvgDialog_60890_Content_79 = {
    Text = "Du weißt, dass hameln recht hat. Ramona wird es verstehen. Für das Überleben der Welt hat sie nie ein Problem damit, sich selbst zu opfern"
  },
  AvgDialog_60890_Content_8 = {
    Text = "Zwei herrenlose Körper verschmelzen zu einer riesigen schwarz-weißen Statue, die zwischen den großen Halbbüsten schwebt"
  },
  AvgDialog_60890_Content_80 = {
    Text = "Dexter ist verschwunden, aber es gibt immer noch Menschen, die sich darum kümmern"
  },
  AvgDialog_60890_Content_81 = {
    Text = "——Zumindest lebt sie noch"
  },
  AvgDialog_60890_Content_82 = {
    Text = "Während du die immer stärker werdende Geisterenergie in dir spürst, hebst du den Kopf und blickst auf die schwarz-weiße Skulptur"
  },
  AvgDialog_60890_Content_83 = {
    Text = "Los, Hüter %player%. Zerschlage die Statue und rette deine Kameraden"
  },
  AvgDialog_60890_Content_84 = {
    Text = "Zeige dieser Welt deine Macht... erinnere dich erneut an alles über den obersten Willen"
  },
  AvgDialog_60890_Content_9 = {
    Text = "Ich habe dich gefunden... Tawil!"
  },
  AvgDialog_60897_Content_1 = {
    Text = "Hüter... wir haben es geschafft!"
  },
  AvgDialog_60897_Content_10 = {
    Text = "Sie drehte sich um und schaute in die Richtung, in die du blicktest—"
  },
  AvgDialog_60897_Content_11 = {
    Text = "Hinter der offenen Tür zerplatzten unzählige Blasen gleichzeitig. Zeit, Raum und Wissen zerbrachen in Fragmente, wie chaotisches Öl, das diese Dimension in komplexe, schmutzige Farben tauchte"
  },
  AvgDialog_60897_Content_12 = {
    Text = "Hinter diesen Fragmenten, die alles symbolisieren, öffnet sich langsam ein Auge, wie ein neugeborenes Kind, das neugierig die Welt betrachtet"
  },
  AvgDialog_60897_Content_13 = {
    Text = "Wo das Auge hinsah, wurden unzählige Objekte, die einst existierten, zu Auflösungsflüssigkeit und flossen in die schwarze Pfütze"
  },
  AvgDialog_60897_Content_14 = {
    Text = "Dieser Blick wanderte und fixierte sich schließlich auf dich"
  },
  AvgDialog_60897_Content_15 = {
    Text = "Erwachen...@3...Erwachen!"
  },
  AvgDialog_60897_Content_16 = {
    Text = "Seine Pupillen weiten sich plötzlich, das gesamte Universum scheint einen Moment lang mit ihm zu vibrieren"
  },
  AvgDialog_60897_Content_17 = {
    Text = "Du starrst Ihn an. Dieser Blick ist zweifellos eine Blasphemie. Alles auf der Welt verschwindet aus deinem Bewusstsein"
  },
  AvgDialog_60897_Content_18 = {
    Text = "Angst. Die ursprünglichste, reinste Angst, unvorstellbar und unwiderstehlich, erfüllt deinen ganzen Körper"
  },
  AvgDialog_60897_Content_2 = {
    Text = "Ein Lächeln breitete sich auf Ramonas Gesicht aus"
  },
  AvgDialog_60897_Content_20 = {
    Text = "Hehehehe... Hahaha!"
  },
  AvgDialog_60897_Content_21 = {
    Text = "Ich habe mich nicht in dir getäuscht, %player%. Ich habe mich nicht in dir getäuscht!"
  },
  AvgDialog_60897_Content_22 = {
    Text = "Ns Stimme kam aus den Schatten der schwarzen Pfütze. Das Bild vor ihm ließ ihn völlig vergessen, seine Eleganz zu wahren. Er lachte verrückt und sah begeistert in die Tür"
  },
  AvgDialog_60897_Content_23 = {
    Text = "Er ist erwacht. Er ist erwacht! Ha!"
  },
  AvgDialog_60897_Content_24 = {
    Text = "So, %player%, Fragment, Betrüger..."
  },
  AvgDialog_60897_Content_25 = {
    Text = "Er drehte sich um, sein böser Mund weit aufgerissen, sein augenloses, schwarzes Gesicht starrte dich spöttisch an"
  },
  AvgDialog_60897_Content_26 = {
    Text = "Sag mir... Was kannst du jetzt tun?"
  },
  AvgDialog_60897_Content_3 = {
    Text = "Geheimnisträger, können wir jetzt"
  },
  AvgDialog_60897_Content_4 = {Text = "?!"},
  AvgDialog_60897_Content_5 = {Text = "Keeper?"},
  AvgDialog_60897_Content_6 = {
    Text = "Ramona sah dich verwirrt an"
  },
  AvgDialog_60897_Content_7 = {
    Text = "In diesem freudigen Moment sah sie einen Ausdruck auf deinem Gesicht, den sie noch nie zuvor gesehen hatte——"
  },
  AvgDialog_60897_Content_8 = {
    Text = "Das ist ein Mensch, der dem Zusammenbruch des majestätischen Universums gegenübersteht"
  },
  AvgDialog_60897_Content_9 = {
    Text = "Kälte, Angst, Verzweiflung, Schwäche"
  },
  AvgDialog_61921_Content_1 = {
    Text = "Du bist mit amorphen Albträumen umschlungen, seltsame Emotionen ergreifen dein Bewusstsein und verzerren deine Träume ins Chaos."
  },
  AvgDialog_61921_Content_10 = {
    Text = "Sie dreht sich um, ihr Blick ruhig und gleichgültig, doch ihre Worte sind unmöglich zu widerstehen."
  },
  AvgDialog_61921_Content_11 = {
    Text = "Komm näher."
  },
  AvgDialog_61921_Content_12 = {
    Text = "Sie lehnt an deiner Brust, was dein Atmen beschleunigt."
  },
  AvgDialog_61921_Content_13 = {
    Text = "Tawil nimmt deine Hand und berührt sanft die Oberfläche des Schwarzen Beckens. Wellen breiten sich kreisförmig aus."
  },
  AvgDialog_61921_Content_14 = {
    Text = "Kannst du es hören? Es ist der Schlag deines Herzens."
  },
  AvgDialog_61921_Content_15 = {
    Text = "Egal in welcher Ära oder welchem Raum... dein Atem und dein Herzschlag werden mich durch dieses Becken erreichen."
  },
  AvgDialog_61921_Content_16 = {
    Text = "Dies ist das erste Mal, dass ich deinen Herzschlag so höre.\nIm Einklang mit dem Klang, den ich Tag und Nacht gehört habe, ist es ohrenbetäubend."
  },
  AvgDialog_61921_Content_17 = {
    Text = "Sie blickte zu dir auf, ihre grau-grünen Pupillen waren mit vagen und unklaren Gedanken gefüllt."
  },
  AvgDialog_61921_Content_18 = {
    Text = "Du fühlst, dass es wieder regnet.\nFällt im Schwarzen Pool auch Regen?"
  },
  AvgDialog_61921_Content_19 = {
    Text = "Silberregentropfen verflechten euch beide fest.\nDiese Zeit und dieser Raum gehören ausschließlich dir und ihr."
  },
  AvgDialog_61921_Content_2 = {
    Text = "Ein kühler Tropfen Flüssigkeit landet wie ein sanfter Kuss auf deiner Stirn, gefolgt von einem Strömregen aus silbernem Niederschlag.\nDer silberne Regen weckt dich."
  },
  AvgDialog_61921_Content_20 = {
    Text = "Weißt du? Sie wird es bereuen, solche Wünsche zu verbreiten..."
  },
  AvgDialog_61921_Content_21 = {
    Text = "Die Verknüpfung zwischen uns ist viel tiefer und stärker als ihr Versuch, dich zu infiziere"
  },
  AvgDialog_61921_Content_3 = {
    Text = "Huch... Huch..."
  },
  AvgDialog_61921_Content_4 = {
    Text = "Die Nacht im Schlafheim fühlt sich verhüllt an, mit gedämpften Geräuschen, die in deinen Ohren widerhallen."
  },
  AvgDialog_61921_Content_5 = {
    Text = "Ich werde am Schwarzen Pool auf dich warten."
  },
  AvgDialog_61921_Content_6 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgDialog_61921_Content_7 = {
    Text = "Ihr Profil ist durch weiße Gaze verborgen. Der Nebel um den Schwarzen Pool scheint eine Erweiterung von ihr zu sein, der dich in einen phantasmagorischen Traum zieht."
  },
  AvgDialog_61921_Content_8 = {
    Text = "Unter unzähligen Träumen steht sie vor der Schwelle der Enden und stellt dir schweigend eine Frage."
  },
  AvgDialog_61921_Content_9 = {
    Text = "Komm zu mir."
  },
  AvgDialog_62163_Content_1 = {
    Text = "Ramona war... erneut von der Statue verschlungen?!"
  },
  AvgDialog_62163_Content_2 = {
    Text = "Es ist die Kraft des \"Vergessenen Wissens\"... Mein Bewusstsein wurde beeinflusst, und ich kann dir keine vollständigen Melodien mehr anbieten. Der bevorstehende Kampf wird äußerst schwierig sein..."
  },
  AvgDialog_62163_Content_3 = {
    Text = "Er, wie wir, hat seine Grenze erreicht... Ich werde niemals... hier fallen!"
  },
  AvgDialog_62164_Content_1 = {
    Text = "Ramona war... erneut von der Statue verschlungen?!"
  },
  AvgDialog_62164_Content_2 = {
    Text = "Es ist die Kraft des \"Vergessensprinzips\"... Mein Bewusstsein wurde beeinflusst, und ich kann dir die vollständige Melodie nicht mehr bieten."
  },
  AvgDialog_62164_Content_3 = {
    Text = "Bevor sie verschlungen wurde, fügte Ramonas Bewusstsein ihm schwere Verletzungen zu. Sie steht immer noch mit dir, Hüter."
  },
  AvgDialog_62164_Content_4 = {
    Text = "Eine Saite in deinem Geist zittert leicht; du hörst eine schwache Stimme."
  },
  AvgDialog_62164_Content_5 = {
    Text = "Erinnere dich an die Vergangenheit... kann... nicht... vergessen..."
  },
  AvgDialog_62164_Content_6 = {
    Text = "Lasst mich... mit dir stehen..."
  },
  AvgDialog_62165_Content_1 = {Text = "Hüter..."},
  AvgDialog_62165_Content_2 = {
    Text = "Ramona?! Bist du... wieder bei Bewusstsein?!"
  },
  AvgDialog_62165_Content_3 = {
    Text = "Es tut mir leid, dass ich diesmal nicht an deiner Seite kämpfen konnte... Aber jetzt werde ich mein Versprechen nicht noch einmal brechen."
  },
  AvgDialog_62165_Content_4 = {
    Text = "Von unseren ersten Verknüpfungen gehören unsere Erinnerungen uns, und niemand kann sie uns nehmen.\nRichtig, Hüter?"
  },
  AvgDialog_62165_Content_5 = {
    Text = "Während Ramonas Worte in deinem Geist verweilten, stieß die Statue einen scharfen Schrei aus, als ob eine Klinge ihre Nerven durchbohrt hätte."
  },
  AvgDialog_62165_Content_6 = {
    Text = "Ein Lichtstrahl blüht aus der silbernen Blume auf seinem Kopf und fällt auf dich."
  },
  AvgDialog_62165_Content_7 = {
    Text = "Du weißt, sie hat niemals vergessen. Sie ist an deine Seite gekommen – genau wie unzählige Male zuvor."
  },
  AvgDialog_62166_Content_1 = {
    Text = "Wir können das Idol nicht alleine stoppen... Ich werde meine Musik nutzen, um dich mit Ramona zu verknüpfen. Schließe deine Augen und rufe sie mit deinem Geist!"
  },
  AvgDialog_62166_Content_10 = {
    Text = "Ramona blickte nach oben zur Quelle des Geräuschs."
  },
  AvgDialog_62166_Content_11 = {
    Text = "Ich habe {Male=er,Female=sie} versprochen. Egal wann, egal was passiert... Ich werde immer an {Male=er,Female=sie}s Seite stehen"
  },
  AvgDialog_62166_Content_12 = {
    Text = "Zum Klang der Melodie von Hameln und deinem Ruf, stoppt die Fusion der göttlichen Statue plötzlich.\nEine beschädigte, strahlend silberne Blume schwebt graziös vom Körper der schwarz-weißen Statue weg."
  },
  AvgDialog_62166_Content_13 = {
    Text = "Ramona, warte auf mich!"
  },
  AvgDialog_62166_Content_14 = {
    Text = "Ich werde dich auf jeden Fall retten! ...Ramona, warte auf mich!!"
  },
  AvgDialog_62166_Content_15 = {
    Text = "Du schreist nach der reinen Silberblume. Durch die Illusion der Geisterwelt lächelt dir ein silberner Nachbilder entgegen."
  },
  AvgDialog_62166_Content_16 = {
    Text = "Ich glaube Ihnen, Hüter."
  },
  AvgDialog_62166_Content_17 = {
    Text = "...Ich werde auf dich warten."
  },
  AvgDialog_62166_Content_2 = {Text = "Ramona!"},
  AvgDialog_62166_Content_3 = {
    Text = "Es gibt ein Geräusch... es ist vertraut, es ist..."
  },
  AvgDialog_62166_Content_4 = {
    Text = "Die Ikone verschlingt unser Bewusstsein. Unsere Erinnerungen verblassen, Ramona. Verblassen aus jeder Dimension, jedem Raum-Zeit-Kontinuum, als hätten wir nie existiert."
  },
  AvgDialog_62166_Content_5 = {
    Text = "Vater, Macht, Freiheit, Leben... Du wirst bald mehr verlieren, Ramona."
  },
  AvgDialog_62166_Content_6 = {
    Text = "Nein, Tawil... Es gibt gewisse Dinge, die kann ich nicht verlieren. Zumindest jetzt besitze ich noch {Male=er,Female=sie}"
  },
  AvgDialog_62166_Content_7 = {
    Text = "Die Fesseln der Statue sind unzerbrechlich. Ein gewaltsamer Ausbruch bringt großen Schmerz und wenig Hilfe von {Male=er,Female=sie}"
  },
  AvgDialog_62166_Content_8 = {
    Text = "Seid ihr bereit, auch so?"
  },
  AvgDialog_62166_Content_9 = {
    Text = "Sonst können wir nur erlauben, dass das Idol Gestalt annimmt. Richtig?"
  },
  AvgDialog_62167_Content_1 = {
    Text = "Das Spiel ist vorbei, Hüter der Geheimnisse {Male=Herr,Female=Frau}"
  },
  AvgDialog_62167_Content_10 = {
    Text = "Sie konnte ihre Gelassenheit nicht mehr bewahren und beugte sich vor, um sich zu übergeben."
  },
  AvgDialog_62167_Content_11 = {
    Text = "Nein, unmöglich... Du bist der oberste Wille... Du bringst Reinigung in diese Welt..."
  },
  AvgDialog_62167_Content_12 = {
    Text = "Ein Traum... Zerstörung... nein... nein!"
  },
  AvgDialog_62167_Content_13 = {
    Text = "Sie brach vor der Tür zusammen, umarmte ihre Arme, ihr Körper zitterte unkontrollierbar."
  },
  AvgDialog_62167_Content_14 = {
    Text = "Juliette? Was hast du gesehen?!"
  },
  AvgDialog_62167_Content_15 = {
    Text = "Die Wahrheit... So ist die Wahrheit..."
  },
  AvgDialog_62167_Content_16 = {
    Text = "Juliette ignoriert deinen Ruf. Nachdem sie die Tür gesehen hat, scheint in dieser Welt nichts mehr für sie von Bedeutung zu sein."
  },
  AvgDialog_62167_Content_17 = {
    Text = "Statue! ..."
  },
  AvgDialog_62167_Content_18 = {
    Text = "Du schaust hinauf—"
  },
  AvgDialog_62167_Content_19 = {
    Text = "Die Aura, die hinter der Tür austritt, wird vollständig absorbiert, und die Statuen, die aufgrund deiner Behinderung gestoppt hatten, verschmelzen plötzlich miteinander."
  },
  AvgDialog_62167_Content_2 = {
    Text = "Vor Juliette öffnete sich eine Lücke in der Tür, die groß genug war, damit eine Person hindurchpassen konnte."
  },
  AvgDialog_62167_Content_20 = {
    Text = "Die massive Steinstatue steht vor dir und strahlt eine lebensechte Majestät aus."
  },
  AvgDialog_62167_Content_21 = {
    Text = "Juliette hob schwach den Kopf und betrachtete das massive Relikt, das sie nicht mehr kontrollieren konnte, und zwang sich zu einem tragischen Lächeln mit ihrer letzten Kraft."
  },
  AvgDialog_62167_Content_22 = {
    Text = "Ein falscher Anfang, ein falsches Ende. Das Ende ist auch Reinigung... Lass alles hier zu einem Ende kommen."
  },
  AvgDialog_62167_Content_23 = {
    Text = "Juliette brach langsam vor der Wahrheit der Tür zusammen."
  },
  AvgDialog_62167_Content_24 = {
    Text = "Vor ihrem Körper erhebt sich langsam eine massive Statue mit einer abgrundtiefen Aura vor dir—"
  },
  AvgDialog_62167_Content_3 = {
    Text = "Dein Wille ist bewundernswert, aber ein fehlgeleiteter Wille ist nutzlos."
  },
  AvgDialog_62167_Content_4 = {
    Text = "Alles Wissen und Macht liegen hinter dieser Tür. Die Tür wird mir helfen, die Fusion der beiden Statuen abzuschließen."
  },
  AvgDialog_62167_Content_5 = {
    Text = "Ich werde hier sein, um den höchsten Gott willkommen zu heißen, der diese Welt reinigen wird —"
  },
  AvgDialog_62167_Content_6 = {
    Text = "Sie näherte sich der Tür und lächelte, während sie hineinlugt."
  },
  AvgDialog_62167_Content_7 = {
    Text = "Juliette... warte!"
  },
  AvgDialog_62167_Content_8 = {
    Text = "Ah!!!——"
  },
  AvgDialog_62167_Content_9 = {
    Text = "Juliette hat fast einen Blick hinein geworfen, hat dann geschrien und sich zurückgezogen."
  },
  AvgDialog_62168_Content_1 = {
    Text = "Die Fusion der Statue ist fast vollständig...!"
  },
  AvgDialog_62168_Content_10 = {
