  },
  AvgDialog_62168_Content_3 = {
    Text = "Hameln's Taktstock fiel schwer zu Boden, ohne auf das Blut zu achten, das aus seinem Mund spritzte."
  },
  AvgDialog_62168_Content_4 = {
    Text = "Die fast vollständig verwachsene Statue zerreißt unter dem Einfluss der Musik und bildet einen Riss."
  },
  AvgDialog_62168_Content_5 = {
    Text = "Juliette beobachtet diese Szene und schüttelt mit einem Lächeln den Kopf."
  },
  AvgDialog_62168_Content_6 = {
