  },
  AvgDialog_62168_Content_9 = {
    Text = "Alles Wissen und Macht liegen hinter dieser Tür. Die Tür wird mir helfen, die Fusion der beiden Statuen abzuschließen."
  },
  AvgDialog_62169_Content_1 = {
    Text = "Die Statue lockert sich... Ich werde Musik verwenden, um dir zu helfen, mit Ramona zu verbinden. Schließe deine Augen und rufe sie mit deinem Geist."
  },
  AvgDialog_62169_Content_10 = {
    Text = "Ramona, warte auf mich!"
  },
